"use client";

import React, { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Button } from "@/components/ui/button";
import {
  Calendar,
  MapPin,
  Clock,
  User,
  Phone,
  Mail,
} from "lucide-react";
import type { Booking } from "@/types/beautonomi";
import { toast } from "sonner";
import OrderDetailsDynamic from "@/app/checkout/components/order-details-dynamic";
import Breadcrumb from "../../components/breadcrumb";
import BackButton from "../../components/back-button";
import AuthGuard from "@/components/auth/auth-guard";
import { SafetyPanicButton } from "@/components/safety/SafetyPanicButton";

export default function BookingDetailPage() {
  const params = useParams();
  const router = useRouter();
  const bookingId = params.id as string;

  const [booking, setBooking] = useState<Booking | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isCancelling, setIsCancelling] = useState(false);

  useEffect(() => {
    const loadBooking = async () => {
      try {
        setIsLoading(true);
        setError(null);

        const response = await fetcher.get<{
          data: Booking;
          error: null;
        }>(`/api/me/bookings/${bookingId}`, { cache: "no-store" });

        setBooking(response.data);
      } catch (err) {
        const errorMessage =
          err instanceof FetchTimeoutError
            ? "Request timed out. Please try again."
            : err instanceof FetchError
            ? err.message
            : "Failed to load booking";
        setError(errorMessage);
        console.error("Error loading booking:", err);
      } finally {
        setIsLoading(false);
      }
    };

    if (bookingId) {
      loadBooking();
    }
  }, [bookingId]);

  const handleCancel = async () => {
    if (!booking) return;

    const confirmed = window.confirm(
      "Are you sure you want to cancel this booking? This action cannot be undone."
    );
    if (!confirmed) return;

    try {
      setIsCancelling(true);
      const response = await fetcher.post<{
        data: { booking: Booking };
        error: null;
      }>(`/api/me/bookings/${bookingId}/cancel`, {
        reason: "Customer request",
        version: (booking as any).version, // Include version for conflict detection
      });

      setBooking(response.data.booking);
      toast.success("Booking cancelled successfully");
    } catch (err) {
      if (err instanceof FetchError && err.status === 409) {
        toast.error("This booking was modified by another user. Please refresh and try again.");
        // Reload booking to get latest version
        const refreshResponse = await fetcher.get<{
          data: Booking;
          error: null;
        }>(`/api/me/bookings/${bookingId}`, { cache: "no-store" });
        setBooking(refreshResponse.data);
      } else {
        const errorMessage =
          err instanceof FetchError ? err.message : "Failed to cancel booking";
        toast.error(errorMessage);
      }
    } finally {
      setIsCancelling(false);
    }
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString("en-US", {
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  const formatTime = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleTimeString("en-US", {
      hour: "2-digit",
      minute: "2-digit",
      hour12: true,
    });
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading booking details..." />
      </div>
    );
  }

  if (error || !booking) {
    return (
      <div className="container mx-auto px-4 py-8">
        <EmptyState
          title="Booking not found"
          description={error || "The booking you're looking for doesn't exist"}
          action={{
            label: "Go Back",
            onClick: () => router.push("/account-settings/bookings"),
          }}
        />
      </div>
    );
  }

  const canCancel =
    booking.status === "confirmed" || booking.status === "pending";
  const canReschedule = booking.status === "confirmed";

  return (
    <AuthGuard>
      <div className="w-full max-w-4xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
      <BackButton href="/account-settings/bookings" label="Back to Bookings" />
      {booking && (
        <Breadcrumb 
          items={[
            { label: "Account", href: "/account-settings" },
            { label: "Bookings", href: "/account-settings/bookings" },
            { label: `Booking #${booking.booking_number}` }
          ]} 
        />
      )}

      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl md:text-3xl font-semibold mb-2 text-gray-900">
            Booking #{booking.booking_number}
          </h1>
          <span
            className={`inline-block px-3 py-1 rounded-full text-sm font-medium ${
              booking.status === "confirmed"
                ? "bg-green-100 text-green-800"
                : booking.status === "pending"
                ? "bg-yellow-100 text-yellow-800"
                : booking.status === "cancelled"
                ? "bg-red-100 text-red-800"
                : booking.status === "completed"
                ? "bg-blue-100 text-blue-800"
                : "bg-gray-100 text-gray-800"
            }`}
          >
            {booking.status}
          </span>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6 mb-6">
        {/* Booking Details */}
        <div className="bg-white border border-gray-200 rounded-lg p-4 md:p-6">
          <h2 className="text-lg md:text-xl font-semibold mb-4 text-gray-900">Booking Details</h2>
          <div className="space-y-4">
            <div className="flex items-start gap-3">
              <Calendar className="w-5 h-5 text-gray-400 mt-0.5" />
              <div>
                <p className="text-sm text-gray-600">Date</p>
                <p className="font-medium">{formatDate(booking.scheduled_at)}</p>
              </div>
            </div>
            <div className="flex items-start gap-3">
              <Clock className="w-5 h-5 text-gray-400 mt-0.5" />
              <div>
                <p className="text-sm text-gray-600">Time</p>
                <p className="font-medium">{formatTime(booking.scheduled_at)}</p>
              </div>
            </div>
            <div className="flex items-start gap-3">
              <MapPin className="w-5 h-5 text-gray-400 mt-0.5" />
              <div>
                <p className="text-sm text-gray-600">Location</p>
                <p className="font-medium">
                  {booking.location_type === "at_salon"
                    ? (booking as any).location?.name || (booking as any).location_name || "At Salon"
                    : booking.address
                    ? `${booking.address.line1}, ${booking.address.city}`
                    : "At your location"}
                </p>
              </div>
            </div>
            {booking.services?.[0]?.staff_name && (
              <div className="flex items-start gap-3">
                <User className="w-5 h-5 text-gray-400 mt-0.5" />
                <div>
                  <p className="text-sm text-gray-600">Professional</p>
                  <p className="font-medium">{booking.services[0].staff_name}</p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Provider Info */}
        <div className="bg-white border border-gray-200 rounded-lg p-4 md:p-6">
          <h2 className="text-lg md:text-xl font-semibold mb-4 text-gray-900">Provider</h2>
          <div className="space-y-4">
            <div>
              <p className="font-medium text-lg">
                {(booking as any).provider?.business_name || "Provider"}
              </p>
              {(booking as any).provider?.phone && (
                <div className="flex items-center gap-2 mt-2 text-sm text-gray-600">
                  <Phone className="w-4 h-4" />
                  <span>{(booking as any).provider.phone}</span>
                </div>
              )}
              {(booking as any).provider?.email && (
                <div className="flex items-center gap-2 mt-1 text-sm text-gray-600">
                  <Mail className="w-4 h-4" />
                  <span>{(booking as any).provider.email}</span>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Services */}
      <div className="bg-white border border-gray-200 rounded-lg p-4 md:p-6 mb-6">
        <h2 className="text-lg md:text-xl font-semibold mb-4 text-gray-900">Services</h2>
        <div className="space-y-3">
          {booking.services?.map((service, index) => (
            <div
              key={service.id || index}
              className="flex justify-between items-center py-3 border-b last:border-0"
            >
              <div>
                <p className="font-medium">{service.offering_name || "Service"}</p>
                <p className="text-sm text-gray-600">{service.duration_minutes} mins</p>
              </div>
              <p className="font-medium">
                {booking.currency} {service.price.toFixed(2)}
              </p>
            </div>
          ))}
          {(!booking.services || booking.services.length === 0) && (
            <p className="text-sm text-gray-500">No services</p>
          )}
        </div>
      </div>

      {/* Products */}
      {(booking as any).products && (booking as any).products.length > 0 && (
        <div className="bg-white border border-gray-200 rounded-lg p-4 md:p-6 mb-6">
          <h2 className="text-lg md:text-xl font-semibold mb-4 text-gray-900">Products</h2>
          <div className="space-y-3">
            {(booking as any).products.map((product: any, index: number) => (
              <div
                key={product.id || index}
                className="flex justify-between items-center py-3 border-b last:border-0"
              >
                <div>
                  <p className="font-medium">{product.product_name || "Product"}</p>
                  <p className="text-sm text-gray-600">Quantity: {product.quantity}</p>
                </div>
                <p className="font-medium">
                  {booking.currency} {product.total_price.toFixed(2)}
                </p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Additional Charges */}
      {(booking as any).additional_charges && (booking as any).additional_charges.length > 0 && (
        <div className="bg-white border border-gray-200 rounded-lg p-4 md:p-6 mb-6">
          <h2 className="text-lg md:text-xl font-semibold mb-4 text-gray-900">Additional Charges</h2>
          <div className="space-y-3">
            {(booking as any).additional_charges.map((charge: any) => (
              <div
                key={charge.id}
                className={`p-4 border rounded-lg ${
                  charge.status === 'paid'
                    ? 'bg-green-50 border-green-200'
                    : charge.status === 'pending' || charge.status === 'approved'
                    ? 'bg-yellow-50 border-yellow-200'
                    : 'bg-gray-50 border-gray-200'
                }`}
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="flex-1">
                    <p className="font-medium text-gray-900">{charge.description}</p>
                    <p className="text-sm text-gray-600 mt-1">
                      {charge.currency} {Number(charge.amount).toFixed(2)}
                    </p>
                  </div>
                  <span
                    className={`px-2 py-1 rounded text-xs font-medium ${
                      charge.status === 'paid'
                        ? 'bg-green-100 text-green-800'
                        : charge.status === 'pending' || charge.status === 'approved'
                        ? 'bg-yellow-100 text-yellow-800'
                        : charge.status === 'rejected'
                        ? 'bg-red-100 text-red-800'
                        : 'bg-gray-100 text-gray-800'
                    }`}
                  >
                    {charge.status}
                  </span>
                </div>
                {(charge.status === 'pending' || charge.status === 'approved') && (
                  <Button
                    onClick={() => router.push(`/account-settings/bookings/${bookingId}/pay-additional/${charge.id}`)}
                    className="mt-2 w-full sm:w-auto bg-gradient-to-r from-[#FF0077] to-[#E6006A] hover:from-[#E6006A] hover:to-[#FF0077] text-white"
                  >
                    Pay Now
                  </Button>
                )}
                {charge.paid_at && (
                  <p className="text-xs text-gray-500 mt-2">
                    Paid on {new Date(charge.paid_at).toLocaleDateString()}
                  </p>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Payment Summary */}
      <div className="bg-white border border-gray-200 rounded-lg p-4 md:p-6 mb-6">
        <h2 className="text-lg md:text-xl font-semibold mb-4 text-gray-900">Payment Summary</h2>
        <div className="space-y-2">
          <div className="flex justify-between">
            <span className="text-gray-600">Subtotal</span>
            <span className="font-medium">
              {booking.currency} {booking.subtotal.toFixed(2)}
            </span>
          </div>
          {booking.tip_amount > 0 && (
            <div className="flex justify-between">
              <span className="text-gray-600">Tip</span>
              <span className="font-medium">
                {booking.currency} {booking.tip_amount.toFixed(2)}
              </span>
            </div>
          )}
          {(booking as any).additional_charges && (booking as any).additional_charges.length > 0 && (
            <div className="pt-2 border-t">
              <p className="text-sm font-medium text-gray-700 mb-2">Additional Charges</p>
              {(booking as any).additional_charges
                .filter((c: any) => c.status !== 'rejected')
                .map((charge: any) => (
                  <div key={charge.id} className="flex justify-between text-sm mb-1">
                    <span className="text-gray-600">{charge.description}</span>
                    <span className={`font-medium ${
                      charge.status === 'paid' ? 'text-green-600' : 'text-yellow-600'
                    }`}>
                      {charge.currency} {Number(charge.amount).toFixed(2)}
                      {charge.status !== 'paid' && ' (Pending)'}
                    </span>
                  </div>
                ))}
            </div>
          )}
          <div className="border-t pt-2 mt-2">
            <div className="flex justify-between">
              <span className="font-semibold">Total</span>
              <span className="font-semibold text-lg">
                {booking.currency} {booking.total_amount.toFixed(2)}
              </span>
            </div>
          </div>
          {(booking as any).outstanding_balance !== undefined && (booking as any).outstanding_balance > 0 && (
            <div className="pt-2 border-t">
              <div className="flex justify-between">
                <span className="font-semibold text-orange-600">Outstanding Balance</span>
                <span className="font-semibold text-lg text-orange-600">
                  {booking.currency} {(booking as any).outstanding_balance.toFixed(2)}
                </span>
              </div>
            </div>
          )}
          <div className="flex justify-between text-sm text-gray-600 mt-2">
            <span>Payment Status</span>
            <span
              className={`font-medium ${
                booking.payment_status === "paid"
                  ? "text-green-600"
                  : booking.payment_status === "pending"
                  ? "text-yellow-600"
                  : "text-red-600"
              }`}
            >
              {booking.payment_status}
            </span>
          </div>
        </div>
      </div>

      {/* Order Tracking (for at-home bookings) */}
      {booking.location_type === "at_home" && (
        <div className="bg-white border border-gray-200 rounded-lg p-4 md:p-6 mb-6">
          <OrderDetailsDynamic bookingId={bookingId} booking={booking} />
        </div>
      )}

      {/* Actions */}
      <div className="flex flex-col sm:flex-row gap-3 md:gap-4 flex-wrap">
        <SafetyPanicButton bookingId={bookingId} />
        {canReschedule && (
          <Button
            variant="outline"
            onClick={() => router.push(`/account-settings/bookings/${bookingId}/reschedule`)}
            className="flex-1"
          >
            Reschedule
          </Button>
        )}
        {canCancel && (
          <Button
            variant="destructive"
            onClick={handleCancel}
            disabled={isCancelling}
            className="flex-1"
          >
            {isCancelling ? "Cancelling..." : "Cancel Booking"}
          </Button>
        )}
        {booking.status === "completed" && (
          <>
            <Button
              variant="outline"
              onClick={() => router.push(`/account-settings/bookings/${bookingId}/review`)}
              className="flex-1"
            >
              Write Review
            </Button>
            <Button
              variant="outline"
              onClick={() => router.push(`/account-settings/bookings/${bookingId}/receipt`)}
              className="flex-1"
            >
              View Receipt
            </Button>
          </>
        )}
        {booking.payment_status === "paid" && booking.status !== "completed" && (
          <Button
            variant="outline"
            onClick={() => router.push(`/account-settings/bookings/${bookingId}/receipt`)}
            className="flex-1"
          >
            View Receipt
          </Button>
        )}
      </div>
      </div>
    </AuthGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Button } from "@/components/ui/button";
import { CreditCard, AlertCircle, CheckCircle2 } from "lucide-react";
import { toast } from "sonner";
import Breadcrumb from "../../../../components/breadcrumb";
import BackButton from "../../../../components/back-button";
import AuthGuard from "@/components/auth/auth-guard";

interface AdditionalCharge {
  id: string;
  description: string;
  amount: number;
  currency: string;
  status: 'pending' | 'approved' | 'rejected' | 'paid';
  requested_at: string;
  paid_at?: string;
}

export default function PayAdditionalChargePage() {
  const params = useParams();
  const router = useRouter();
  const bookingId = params.id as string;
  const chargeId = params.chargeId as string;

  const [charge, setCharge] = useState<AdditionalCharge | null>(null);
  const [booking, setBooking] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadCharge();
  }, [bookingId, chargeId]); // eslint-disable-line react-hooks/exhaustive-deps -- load on mount and when ids change

  const loadCharge = async () => {
    try {
      setIsLoading(true);
      setError(null);

      // Load booking to get charge info
      const bookingResponse = await fetcher.get<{
        data: any;
        error: null;
      }>(`/api/me/bookings/${bookingId}`, { cache: "no-store" });

      const bookingData = bookingResponse.data;
      setBooking(bookingData);

      // Find the specific charge
      const foundCharge = bookingData.additional_charges?.find(
        (c: any) => c.id === chargeId
      );

      if (!foundCharge) {
        setError("Additional charge not found");
        return;
      }

      if (foundCharge.status === 'paid') {
        setError("This charge has already been paid");
        return;
      }

      if (foundCharge.status === 'rejected') {
        setError("This charge has been rejected");
        return;
      }

      setCharge(foundCharge);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load charge";
      setError(errorMessage);
      console.error("Error loading charge:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handlePayNow = async () => {
    if (!charge) return;

    try {
      setIsProcessing(true);

      // Initialize Paystack payment
      const response = await fetcher.post<{
        data: {
          authorization_url: string;
          access_code: string;
          reference: string;
        };
      }>(`/api/me/bookings/${bookingId}/additional-charges/${chargeId}/pay`, {
        amount: charge.amount,
        currency: charge.currency,
      });

      // Redirect to Paystack payment page
      if (response.data.authorization_url) {
        window.location.href = response.data.authorization_url;
      } else {
        throw new Error("Payment link not received");
      }
    } catch (err) {
      const errorMessage =
        err instanceof FetchError ? err.message : "Failed to initiate payment";
      toast.error(errorMessage);
      console.error("Error initiating payment:", err);
    } finally {
      setIsProcessing(false);
    }
  };

  if (isLoading) {
    return (
      <AuthGuard>
        <div className="container mx-auto px-4 py-8">
          <LoadingTimeout loadingMessage="Loading payment details..." />
        </div>
      </AuthGuard>
    );
  }

  if (error || !charge) {
    return (
      <AuthGuard>
        <div className="container mx-auto px-4 py-8">
          <EmptyState
            title="Charge not found"
            description={error || "The additional charge you're looking for doesn't exist or has already been paid"}
            action={{
              label: "Back to Booking",
              onClick: () => router.push(`/account-settings/bookings/${bookingId}`),
            }}
          />
        </div>
      </AuthGuard>
    );
  }

  return (
    <AuthGuard>
      <div className="w-full max-w-2xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
        <BackButton 
          href={`/account-settings/bookings/${bookingId}`} 
          label="Back to Booking" 
        />
        <Breadcrumb
          items={[
            { label: "Account", href: "/account-settings" },
            { label: "Bookings", href: "/account-settings/bookings" },
            { label: `Booking #${booking?.booking_number}`, href: `/account-settings/bookings/${bookingId}` },
            { label: "Pay Additional Charge" },
          ]}
        />

        <div className="mt-6">
          <h1 className="text-2xl md:text-3xl font-semibold mb-2 text-gray-900">
            Pay Additional Charge
          </h1>
          <p className="text-gray-600 mb-6">
            Complete payment for this additional charge from your booking
          </p>

          {/* Charge Details */}
          <div className="bg-white border border-gray-200 rounded-lg p-6 mb-6">
            <div className="flex items-start gap-4 mb-4">
              <div className="p-3 bg-yellow-100 rounded-full">
                <CreditCard className="w-6 h-6 text-yellow-600" />
              </div>
              <div className="flex-1">
                <h2 className="text-lg font-semibold text-gray-900 mb-1">
                  {charge.description}
                </h2>
                <p className="text-sm text-gray-600">
                  Requested on {new Date(charge.requested_at).toLocaleDateString()}
                </p>
              </div>
            </div>

            <div className="border-t pt-4">
              <div className="flex justify-between items-center mb-4">
                <span className="text-lg font-medium text-gray-700">Amount Due</span>
                <span className="text-3xl font-bold text-gray-900">
                  {charge.currency} {charge.amount.toFixed(2)}
                </span>
              </div>

              {charge.status === 'pending' && (
                <div className="p-3 bg-yellow-50 border border-yellow-200 rounded-lg mb-4">
                  <div className="flex items-start gap-2">
                    <AlertCircle className="w-5 h-5 text-yellow-600 flex-shrink-0 mt-0.5" />
                    <div>
                      <p className="text-sm font-medium text-yellow-900">
                        Payment Pending
                      </p>
                      <p className="text-xs text-yellow-700 mt-1">
                        This charge is awaiting your payment. Please complete payment to proceed.
                      </p>
                    </div>
                  </div>
                </div>
              )}

              {charge.status === 'approved' && (
                <div className="p-3 bg-blue-50 border border-blue-200 rounded-lg mb-4">
                  <div className="flex items-start gap-2">
                    <CheckCircle2 className="w-5 h-5 text-blue-600 flex-shrink-0 mt-0.5" />
                    <div>
                      <p className="text-sm font-medium text-blue-900">
                        Payment Approved
                      </p>
                      <p className="text-xs text-blue-700 mt-1">
                        This charge has been approved. Please complete payment.
                      </p>
                    </div>
                  </div>
                </div>
              )}

              <Button
                onClick={handlePayNow}
                disabled={isProcessing || charge.status === 'paid'}
                className="w-full bg-gradient-to-r from-[#FF0077] to-[#E6006A] hover:from-[#E6006A] hover:to-[#FF0077] text-white py-6 text-lg font-semibold"
              >
                {isProcessing ? (
                  "Processing..."
                ) : charge.status === 'paid' ? (
                  "Already Paid"
                ) : (
                  <>
                    <CreditCard className="w-5 h-5 mr-2" />
                    Pay {charge.currency} {charge.amount.toFixed(2)} Now
                  </>
                )}
              </Button>

              <p className="text-xs text-gray-500 text-center mt-4">
                Secure payment powered by Paystack
              </p>
            </div>
          </div>

          {/* Booking Info */}
          {booking && (
            <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
              <p className="text-sm text-gray-600">
                <span className="font-medium">Booking:</span> #{booking.booking_number}
              </p>
              <p className="text-sm text-gray-600 mt-1">
                <span className="font-medium">Provider:</span> {booking.provider?.business_name || "Provider"}
              </p>
            </div>
          )}
        </div>
      </div>
    </AuthGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useParams } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Download, Printer, ArrowLeft, CheckCircle2 } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import Link from "next/link";
import AuthGuard from "@/components/auth/auth-guard";

interface Receipt {
  booking_number: string;
  booking_date: string;
  service_date: string;
  customer: {
    full_name: string | null;
    email: string;
  };
  provider: {
    business_name: string;
    owner_email: string | null;
    address: any;
  };
  services: Array<{
    name: string;
    quantity: number;
    price: number;
    total: number;
  }>;
  products: Array<{
    name: string;
    quantity: number;
    price: number;
    total: number;
  }>;
  subtotal: number;
  tax: number;
  fees: number;
  discount: number;
  total: number;
  payment_status: string;
}

export default function ReceiptPage() {
  const params = useParams();
  const bookingId = params.id as string;

  const [receipt, setReceipt] = useState<Receipt | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    loadReceipt();
  }, [bookingId]); // eslint-disable-line react-hooks/exhaustive-deps -- load on mount when bookingId changes

  const loadReceipt = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ receipt: Receipt }>(
        `/api/bookings/${bookingId}/receipt`,
        { cache: "no-store" }
      );
      setReceipt(response.receipt);
    } catch (error) {
      console.error("Failed to load receipt:", error);
      toast.error("Failed to load receipt");
    } finally {
      setIsLoading(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = () => {
    // In a real implementation, generate PDF and download
    toast.info("PDF download functionality coming soon");
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
    }).format(amount);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString("en-US", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading receipt..." />
      </div>
    );
  }

  if (!receipt) {
    return (
      <div className="container mx-auto px-4 py-8">
        <div className="text-center">
          <p className="text-gray-500">Receipt not found</p>
          <Link href={`/account-settings/bookings/${bookingId}`}>
            <Button variant="outline" className="mt-4">
              Back to Booking
            </Button>
          </Link>
        </div>
      </div>
    );
  }

  return (
    <AuthGuard>
      <div className="container mx-auto px-4 py-8 max-w-4xl">
        <div className="flex justify-between items-center mb-6 print:hidden">
          <Link href={`/account-settings/bookings/${bookingId}`}>
            <Button variant="ghost">
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Booking
            </Button>
          </Link>
          <div className="flex gap-2">
            <Button variant="outline" onClick={handleDownload}>
              <Download className="w-4 h-4 mr-2" />
              Download PDF
            </Button>
            <Button variant="outline" onClick={handlePrint}>
              <Printer className="w-4 h-4 mr-2" />
              Print
            </Button>
          </div>
        </div>

        <Card className="print:shadow-none print:border-0">
          <CardHeader className="text-center border-b pb-4">
            <CardTitle className="text-3xl">Receipt</CardTitle>
            <p className="text-gray-600 mt-2">Booking #{receipt.booking_number}</p>
          </CardHeader>
          <CardContent className="space-y-6 pt-6">
            <div className="grid grid-cols-2 gap-6">
              <div>
                <h3 className="font-semibold mb-2">Customer</h3>
                <p className="text-sm">{receipt.customer.full_name || "N/A"}</p>
                <p className="text-sm text-gray-600">{receipt.customer.email}</p>
              </div>
              <div>
                <h3 className="font-semibold mb-2">Provider</h3>
                <p className="text-sm">{receipt.provider.business_name}</p>
                {receipt.provider.owner_email && (
                  <p className="text-sm text-gray-600">{receipt.provider.owner_email}</p>
                )}
              </div>
            </div>

            <div className="border-t pt-4">
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <span className="text-gray-600">Booking Date:</span>
                  <p className="font-medium">{formatDate(receipt.booking_date)}</p>
                </div>
                <div>
                  <span className="text-gray-600">Service Date:</span>
                  <p className="font-medium">{formatDate(receipt.service_date)}</p>
                </div>
              </div>
            </div>

            {(receipt.services.length > 0 || receipt.products.length > 0) && (
              <div className="border-t pt-4">
                <h3 className="font-semibold mb-4">Items</h3>
                <div className="space-y-4">
                  {receipt.services.map((service, index) => (
                    <div key={index} className="flex justify-between items-start">
                      <div>
                        <p className="font-medium">{service.name}</p>
                        <p className="text-sm text-gray-600">
                          Quantity: {service.quantity} ├ù {formatCurrency(service.price)}
                        </p>
                      </div>
                      <p className="font-medium">{formatCurrency(service.total)}</p>
                    </div>
                  ))}
                  {receipt.products.map((product, index) => (
                    <div key={index} className="flex justify-between items-start">
                      <div>
                        <p className="font-medium">{product.name}</p>
                        <p className="text-sm text-gray-600">
                          Quantity: {product.quantity} ├ù {formatCurrency(product.price)}
                        </p>
                      </div>
                      <p className="font-medium">{formatCurrency(product.total)}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="border-t pt-4 space-y-2">
              <div className="flex justify-between text-sm">
                <span>Subtotal</span>
                <span>{formatCurrency(receipt.subtotal)}</span>
              </div>
              {receipt.tax > 0 && (
                <div className="flex justify-between text-sm">
                  <span>Tax</span>
                  <span>{formatCurrency(receipt.tax)}</span>
                </div>
              )}
              {receipt.fees > 0 && (
                <div className="flex justify-between text-sm">
                  <span>Platform Fee</span>
                  <span>{formatCurrency(receipt.fees)}</span>
                </div>
              )}
              {receipt.discount > 0 && (
                <div className="flex justify-between text-sm text-green-600">
                  <span>Discount</span>
                  <span>-{formatCurrency(receipt.discount)}</span>
                </div>
              )}
              <div className="flex justify-between font-bold text-lg pt-2 border-t">
                <span>Total</span>
                <span>{formatCurrency(receipt.total)}</span>
              </div>
            </div>

            <div className="border-t pt-4">
              <div className="flex items-center gap-2">
                <span className="text-sm text-gray-600">Payment Status:</span>
                <Badge
                  className={
                    receipt.payment_status === "paid"
                      ? "bg-green-100 text-green-800"
                      : receipt.payment_status === "pending"
                      ? "bg-yellow-100 text-yellow-800"
                      : "bg-red-100 text-red-800"
                  }
                >
                  {receipt.payment_status === "paid" && (
                    <CheckCircle2 className="w-3 h-3 mr-1" />
                  )}
                  {receipt.payment_status.charAt(0).toUpperCase() +
                    receipt.payment_status.slice(1)}
                </Badge>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </AuthGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Star, Send, ArrowLeft, Upload, X } from "lucide-react";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import Link from "next/link";
import Image from "next/image";
import AuthGuard from "@/components/auth/auth-guard";
import { useAuth } from "@/providers/AuthProvider";

export default function ReviewPage() {
  const params = useParams();
  const router = useRouter();
  useAuth();
  const bookingId = params.id as string;

  const [rating, setRating] = useState(0);
  const [hoveredRating, setHoveredRating] = useState(0);
  const [comment, setComment] = useState("");
  const [photos, setPhotos] = useState<string[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [booking, setBooking] = useState<any>(null);

  useEffect(() => {
    loadBooking();
  }, [bookingId]); // eslint-disable-line react-hooks/exhaustive-deps -- load on mount when bookingId changes

  const loadBooking = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<any>(`/api/me/bookings/${bookingId}`, { cache: "no-store" });
      setBooking(response.data);
    } catch (error) {
      console.error("Failed to load booking:", error);
      toast.error("Failed to load booking");
    } finally {
      setIsLoading(false);
    }
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    // In a real implementation, upload to storage and get URLs
    // For now, we'll just show a placeholder
    toast.info("Photo upload functionality coming soon");
  };

  const handleSubmit = async () => {
    if (rating === 0) {
      toast.error("Please select a rating");
      return;
    }

    try {
      setIsSubmitting(true);
      await fetcher.post(`/api/bookings/${bookingId}/review`, {
        rating,
        comment: comment.trim() || null,
        photos,
      });

      toast.success("Review submitted successfully!");
      router.push(`/account-settings/bookings/${bookingId}`);
    } catch (error) {
      console.error("Failed to submit review:", error);
      toast.error(
        error instanceof FetchError
          ? error.message
          : "Failed to submit review. Please try again."
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading..." />
      </div>
    );
  }

  return (
    <AuthGuard>
      <div className="container mx-auto px-4 py-8 max-w-2xl">
        <Link href={`/account-settings/bookings/${bookingId}`}>
          <Button variant="ghost" className="mb-6">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Booking
          </Button>
        </Link>

        <Card>
          <CardHeader>
            <CardTitle className="text-2xl">Write a Review</CardTitle>
            {booking && (
              <p className="text-gray-600 mt-2">
                Share your experience with {booking.provider?.business_name || "this provider"}
              </p>
            )}
          </CardHeader>
          <CardContent className="space-y-6">
            <div>
              <Label className="text-base font-medium mb-3 block">
                How would you rate your experience? *
              </Label>
              <div className="flex gap-2">
                {[1, 2, 3, 4, 5].map((star) => (
                  <button
                    key={star}
                    type="button"
                    onClick={() => setRating(star)}
                    onMouseEnter={() => setHoveredRating(star)}
                    onMouseLeave={() => setHoveredRating(0)}
                    className="focus:outline-none"
                  >
                    <Star
                      className={`w-10 h-10 transition-colors ${
                        star <= (hoveredRating || rating)
                          ? "fill-yellow-400 text-yellow-400"
                          : "text-gray-300"
                      }`}
                    />
                  </button>
                ))}
              </div>
              {rating > 0 && (
                <p className="text-sm text-gray-600 mt-2">
                  {rating === 5
                    ? "Excellent!"
                    : rating === 4
                    ? "Great!"
                    : rating === 3
                    ? "Good"
                    : rating === 2
                    ? "Fair"
                    : "Poor"}
                </p>
              )}
            </div>

            <div>
              <Label htmlFor="comment" className="text-base font-medium mb-3 block">
                Tell us about your experience
              </Label>
              <Textarea
                id="comment"
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                placeholder="Share details about your experience..."
                rows={6}
                maxLength={1000}
              />
              <p className="text-xs text-gray-500 mt-2">
                {comment.length}/1000 characters
              </p>
            </div>

            <div>
              <Label className="text-base font-medium mb-3 block">
                Add Photos (Optional)
              </Label>
              <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center">
                <Upload className="w-8 h-8 text-gray-400 mx-auto mb-2" />
                <p className="text-sm text-gray-600 mb-2">
                  Upload photos of your experience
                </p>
                <input
                  type="file"
                  accept="image/*"
                  multiple
                  onChange={handlePhotoUpload}
                  className="hidden"
                  id="photo-upload"
                />
                <label htmlFor="photo-upload">
                  <Button variant="outline" type="button" asChild>
                    <span>Choose Photos</span>
                  </Button>
                </label>
              </div>
              {photos.length > 0 && (
                <div className="mt-4 flex gap-2">
                  {photos.map((photo, index) => (
                    <div key={index} className="relative">
                      <Image
                        src={photo}
                        alt={`Review photo ${index + 1}`}
                        width={80}
                        height={80}
                        className="w-20 h-20 object-cover rounded"
                        unoptimized
                      />
                      <button
                        onClick={() => setPhotos(photos.filter((_, i) => i !== index))}
                        className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1"
                      >
                        <X className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="flex gap-4 pt-4">
              <Button
                variant="outline"
                onClick={() => router.back()}
                className="flex-1"
              >
                Cancel
              </Button>
              <Button
                onClick={handleSubmit}
                disabled={isSubmitting || rating === 0}
                className="flex-1 bg-[#FF0077] hover:bg-[#D60565]"
              >
                {isSubmitting ? (
                  "Submitting..."
                ) : (
                  <>
                    <Send className="w-4 h-4 mr-2" />
                    Submit Review
                  </>
                )}
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    </AuthGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import type { Booking } from "@/types/beautonomi";
import { Button } from "@/components/ui/button";
import Link from "next/link";
import { Calendar, MapPin, Clock, User, Sparkles } from "lucide-react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";

interface BookingsListProps {
  status?: "upcoming" | "past" | "cancelled";
  /** Increment to force refetch (e.g. when realtime update received) */
  refreshTrigger?: number;
}

export default function BookingsList({ status, refreshTrigger }: BookingsListProps) {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const router = useRouter();

  useEffect(() => {
    const loadBookings = async () => {
      try {
        setIsLoading(true);
        setError(null);

        const params = status ? `?status=${status}` : "";
        const response = await fetcher.get<{
          data: {
            items: Booking[];
            total: number;
            page: number;
            limit: number;
            has_more: boolean;
          };
          error: null;
        }>(`/api/me/bookings${params}`, { cache: "no-store" });

        // Handle paginated response - extract items array
        const bookingsData = response.data?.items || response.data || [];
        setBookings(Array.isArray(bookingsData) ? bookingsData : []);
      } catch (err) {
        const errorMessage =
          err instanceof FetchTimeoutError
            ? "Request timed out. Please try again."
            : err instanceof FetchError
            ? err.message
            : "Failed to load bookings";
        setError(errorMessage);
        console.error("Error loading bookings:", err);
      } finally {
        setIsLoading(false);
      }
    };

    loadBookings();
  }, [status, refreshTrigger]);

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString("en-US", {
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  const formatTime = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleTimeString("en-US", {
      hour: "2-digit",
      minute: "2-digit",
      hour12: true,
    });
  };

  if (isLoading) {
    return (
      <div className="py-8">
        <LoadingTimeout loadingMessage="Loading bookings..." />
      </div>
    );
  }

  if (error) {
    return (
      <EmptyState
        title="Failed to load bookings"
        description={error}
        action={{
          label: "Retry",
          onClick: () => window.location.reload(),
        }}
      />
    );
  }

  if (bookings.length === 0) {
    return (
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4 }}
        className="text-center py-12 md:py-16"
      >
        <motion.div
          initial={{ scale: 0.9 }}
          animate={{ scale: 1 }}
          transition={{ duration: 0.3, delay: 0.1 }}
          className="inline-flex items-center justify-center w-20 h-20 md:w-24 md:h-24 rounded-full bg-gradient-to-br from-pink-100 to-rose-100 mb-6"
        >
          <Sparkles className="w-10 h-10 md:w-12 md:h-12 text-[#FF0077]" />
        </motion.div>
        <h3 className="text-2xl md:text-3xl font-semibold tracking-tighter text-gray-900 mb-3">
          No appointments scheduled...yet!
        </h3>
        <p className="text-base md:text-lg font-light text-gray-600 mb-8 max-w-md mx-auto leading-relaxed">
          Unveil your radiance and step into a world of luxury. It&apos;s time to
          pamper yourself and embrace your true beauty with our expert care.
        </p>
        <Link href="/search" className="inline-block">
          <motion.div
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
          >
            <Button 
              className="bg-gradient-to-r from-[#FF0077] to-[#E6006A] hover:from-[#E6006A] hover:to-[#FF0077] text-white font-semibold px-8 py-6 text-base shadow-lg hover:shadow-xl transition-all"
            >
              Start Searching
            </Button>
          </motion.div>
        </Link>
      </motion.div>
    );
  }

  return (
    <div className="space-y-4 md:space-y-6">
      {bookings.map((booking, index) => (
        <motion.div
          key={booking.id}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3, delay: index * 0.1 }}
          whileHover={{ scale: 1.01, y: -2 }}
          whileTap={{ scale: 0.98 }}
          className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-2xl p-6 md:p-8 shadow-lg hover:shadow-2xl transition-all duration-300"
        >
          <div className="flex flex-col md:flex-row md:items-start md:justify-between gap-4">
            <div className="flex-1">
              <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-3 mb-3">
                <h3 className="text-lg md:text-xl font-semibold text-gray-900">
                  {(booking as any).provider_name || booking.services?.[0]?.offering_name || "Beauty Service"}
                </h3>
                <span
                  className={`px-3 py-1.5 rounded-full text-xs font-semibold tracking-tight ${
                    booking.status === "confirmed"
                      ? "bg-green-50 text-green-700 border border-green-200"
                      : booking.status === "pending"
                      ? "bg-yellow-50 text-yellow-700 border border-yellow-200"
                      : booking.status === "cancelled"
                      ? "bg-red-50 text-red-700 border border-red-200"
                      : "bg-gray-50 text-gray-700 border border-gray-200"
                  }`}
                >
                  {booking.status.charAt(0).toUpperCase() + booking.status.slice(1)}
                </span>
              </div>

              <div className="space-y-3 text-sm md:text-base text-gray-700">
                <div className="flex items-center gap-3">
                  <div className="p-2 rounded-lg bg-pink-50 border border-pink-100">
                    <Calendar className="w-4 h-4 text-[#FF0077]" />
                  </div>
                  <span className="break-words font-medium">{formatDate(booking.scheduled_at)}</span>
                </div>
                <div className="flex items-center gap-3">
                  <div className="p-2 rounded-lg bg-pink-50 border border-pink-100">
                    <Clock className="w-4 h-4 text-[#FF0077]" />
                  </div>
                  <span className="font-medium">{formatTime(booking.scheduled_at)}</span>
                </div>
                {booking.location_type === "at_salon" && (
                  <div className="flex items-center gap-3">
                    <div className="p-2 rounded-lg bg-pink-50 border border-pink-100">
                      <MapPin className="w-4 h-4 text-[#FF0077]" />
                    </div>
                    <span className="font-medium">At Salon</span>
                  </div>
                )}
                {booking.location_type === "at_home" && (
                  <div className="flex items-center gap-3">
                    <div className="p-2 rounded-lg bg-pink-50 border border-pink-100">
                      <MapPin className="w-4 h-4 text-[#FF0077]" />
                    </div>
                    <span className="font-medium">At your location</span>
                  </div>
                )}
                {booking.services?.[0]?.staff_name && (
                  <div className="flex items-center gap-3">
                    <div className="p-2 rounded-lg bg-pink-50 border border-pink-100">
                      <User className="w-4 h-4 text-[#FF0077]" />
                    </div>
                    <span className="font-medium">{booking.services[0].staff_name}</span>
                  </div>
                )}
              </div>

              <div className="mt-6 pt-4 border-t border-gray-200/50">
                <p className="text-xl md:text-2xl font-semibold text-gray-900 mb-1">
                  {booking.currency} {booking.total_amount?.toFixed(2)}
                </p>
                <p className="text-xs md:text-sm text-gray-500 font-light">
                  Booking #{booking.booking_number}
                </p>
              </div>
            </div>

            <div className="flex flex-col gap-3 w-full sm:w-auto md:w-48 flex-shrink-0">
              <Link href={`/account-settings/bookings/${booking.id}`} className="w-full">
                <motion.div
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                >
                  <Button 
                    variant="outline" 
                    className="w-full border-gray-300 hover:border-[#FF0077] hover:text-[#FF0077] transition-colors"
                  >
                    View Details
                  </Button>
                </motion.div>
              </Link>
              {booking.status === "confirmed" && (
                <>
                  <motion.div
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                  >
                    <Button
                      className="w-full bg-gradient-to-r from-[#FF0077] to-[#E6006A] hover:from-[#E6006A] hover:to-[#FF0077] text-white font-semibold shadow-md hover:shadow-lg transition-all"
                      onClick={() => {
                        router.push(
                          `/account-settings/bookings/${booking.id}/reschedule`
                        );
                      }}
                    >
                      Reschedule
                    </Button>
                  </motion.div>
                  <Link href={`/account-settings/bookings/${booking.id}`} className="w-full block">
                    <Button
                      variant="outline"
                      className="w-full border-red-200 text-red-600 hover:bg-red-50 hover:text-red-700"
                    >
                      Cancel
                    </Button>
                  </Link>
                </>
              )}
            </div>
          </div>
        </motion.div>
      ))}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { fetcher } from "@/lib/http/fetcher";
import { Calendar, MapPin, ArrowRight } from "lucide-react";

interface BookingPreview {
  id: string;
  booking_number: string;
  scheduled_at: string;
  status: string;
  location_type: string;
  provider_name?: string;
  service_summary?: string;
}

export function UpcomingBookingPreview() {
  const [booking, setBooking] = useState<BookingPreview | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        const response = await fetcher.get<{
          data: { items: BookingPreview[]; total: number };
        }>("/api/me/bookings?status=upcoming&limit=1", { cache: "no-store" });
        const items = response.data?.items || [];
        setBooking(items[0] || null);
      } catch {
        setBooking(null);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  if (loading) return null;
  if (!booking) return null;

  const date = new Date(booking.scheduled_at);
  const dateStr = date.toLocaleDateString("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
  });
  const timeStr = date.toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
  });

  return (
    <Link
      href={`/account-settings/bookings/${booking.id}`}
      className="block bg-gradient-to-br from-pink-50 to-rose-50 border border-pink-100 rounded-xl p-4 hover:border-pink-200 hover:shadow-sm transition-all"
    >
      <div className="flex items-start justify-between gap-3">
        <div className="flex-1 min-w-0">
          <p className="text-xs font-medium text-pink-600 uppercase tracking-wide mb-1">
            Next appointment
          </p>
          <p className="font-semibold text-gray-900 truncate">
            {(booking as any).provider_name || "Beauty Service"}
          </p>
          <div className="flex items-center gap-2 mt-1 text-sm text-gray-600">
            <Calendar className="h-4 w-4 text-pink-500 shrink-0" />
            <span>
              {dateStr} at {timeStr}
            </span>
          </div>
          {booking.location_type && (
            <div className="flex items-center gap-2 mt-0.5 text-sm text-gray-500">
              <MapPin className="h-4 w-4 text-pink-500 shrink-0" />
              <span>
                {booking.location_type === "at_salon" ? "At Salon" : "At your location"}
              </span>
            </div>
          )}
        </div>
        <ArrowRight className="h-5 w-5 text-pink-500 shrink-0 mt-1" />
      </div>
    </Link>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import AuthGuard from "@/components/auth/auth-guard";
import BackButton from "../components/back-button";
import Breadcrumb from "../components/breadcrumb";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { useAuth } from "@/providers/AuthProvider";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Plus } from "lucide-react";

type Offer = {
  id: string;
  price: number;
  currency: string;
  duration_minutes: number;
  expiration_at: string;
  notes?: string | null;
  status: string;
  payment_url?: string | null;
  paid_at?: string | null;
  staff_id?: string | null;
  location_id?: string | null;
  scheduled_at?: string | null;
  staff?: { id: string; name: string } | null;
  location?: { id: string; name: string } | null;
};

type CustomRequest = {
  id: string;
  description: string;
  status: string;
  preferred_start_at?: string | null;
  location_type: string;
  budget_min?: number | null;
  budget_max?: number | null;
  created_at: string;
  service_name?: string | null;
  address_line1?: string | null;
  address_line2?: string | null;
  address_city?: string | null;
  address_state?: string | null;
  address_country?: string | null;
  address_postal_code?: string | null;
  provider?: { business_name?: string | null; slug?: string | null } | null;
  customer?: { id: string; full_name?: string | null; email?: string | null; avatar_url?: string | null } | null;
  offers?: Offer[];
};

type Client = {
  id: string;
  customer_id: string;
  customer?: {
    id: string;
    full_name?: string | null;
    email?: string | null;
    avatar_url?: string | null;
  } | null;
};

export default function CustomRequestsPage() {
  const { role } = useAuth();
  const isProvider = role === "provider_owner" || role === "provider_staff";

  const [items, setItems] = useState<CustomRequest[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showOfferModal, setShowOfferModal] = useState(false);
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoadingClients, setIsLoadingClients] = useState(false);
  const [staffList, setStaffList] = useState<Array<{ id: string; name: string }>>([]);
  const [locationsList, setLocationsList] = useState<Array<{ id: string; name: string }>>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Form state for creating new custom offer
  const [formData, setFormData] = useState({
    customer_id: "",
    description: "",
    location_type: "at_salon" as "at_home" | "at_salon",
    price: "",
    currency: "ZAR",
    duration_minutes: "60",
    expiration_days: "7",
    notes: "",
    preferred_start_at: "",
    staff_id: "",
    location_id: "",
  });

  // Form state for creating offer for existing request
  const [offerFormData, setOfferFormData] = useState({
    price: "",
    currency: "ZAR",
    duration_minutes: "60",
    expiration_days: "7",
    notes: "",
    staff_id: "",
    location_id: "",
    scheduled_at: "",
  });

  const load = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const endpoint = isProvider ? "/api/provider/custom-requests" : "/api/me/custom-requests";
      const res = await fetcher.get<{ data: CustomRequest[] }>(endpoint, { cache: "no-store" });
      setItems(res.data || []);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load custom requests";
      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const loadClients = async () => {
    if (!isProvider) return;
    try {
      setIsLoadingClients(true);
      const res = await fetcher.get<{ data: Client[] }>("/api/provider/clients", { cache: "no-store" });
      setClients(res.data || []);
    } catch (err) {
      console.error("Failed to load clients:", err);
      toast.error("Failed to load clients");
    } finally {
      setIsLoadingClients(false);
    }
  };

  const loadStaffAndLocations = async () => {
    if (!isProvider) return;
    try {
      const [staffRes, locRes] = await Promise.all([
        fetcher.get<{ data: Array<{ id: string; name: string }> }>("/api/provider/staff", { cache: "no-store" }),
        fetcher.get<{ data: Array<{ id: string; name: string }> }>("/api/provider/locations", { cache: "no-store" }),
      ]);
      setStaffList(staffRes.data?.map((s) => ({ id: s.id, name: s.name })) ?? []);
      setLocationsList(locRes.data?.map((l) => ({ id: l.id, name: l.name })) ?? []);
    } catch (err) {
      console.error("Failed to load staff/locations:", err);
    }
  };

  useEffect(() => {
    load();
    if (isProvider) {
      loadClients();
      loadStaffAndLocations();
    }
  }, [isProvider]); // eslint-disable-line react-hooks/exhaustive-deps -- load when isProvider changes

  const acceptAndPay = async (offerId: string) => {
    try {
      const res = await fetcher.post<{ data: { paymentUrl: string } }>(`/api/me/custom-offers/${offerId}/accept`, {});
      const url = res.data.paymentUrl;
      if (url) {
        window.location.href = url;
        return;
      }
      toast.error("No payment URL returned");
    } catch (e: any) {
      toast.error(e?.message || "Failed to start payment");
    }
  };

  const handleCreateOffer = async () => {
    if (!formData.customer_id || !formData.description || !formData.price) {
      toast.error("Please fill in all required fields");
      return;
    }

    try {
      setIsSubmitting(true);
      const expirationDate = new Date();
      expirationDate.setDate(expirationDate.getDate() + parseInt(formData.expiration_days));

      const payload = {
        customer_id: formData.customer_id,
        description: formData.description,
        location_type: formData.location_type,
        price: parseFloat(formData.price),
        currency: formData.currency,
        duration_minutes: parseInt(formData.duration_minutes),
        expiration_at: expirationDate.toISOString(),
        notes: formData.notes || null,
        preferred_start_at: formData.preferred_start_at || null,
        staff_id: formData.staff_id || null,
        location_id: formData.location_id || null,
      };

      await fetcher.post("/api/provider/custom-offers/create", payload);
      toast.success("Custom offer sent successfully!");
      setShowCreateModal(false);
      setFormData({
        customer_id: "",
        description: "",
        location_type: "at_salon",
        price: "",
        currency: "ZAR",
        duration_minutes: "60",
        expiration_days: "7",
        notes: "",
        preferred_start_at: "",
        staff_id: "",
        location_id: "",
      });
      load();
    } catch (e: any) {
      toast.error(e?.message || "Failed to create custom offer");
    } finally {
      setIsSubmitting(false);
    }
  };

  const openOfferModal = (requestId: string) => {
    setSelectedRequestId(requestId);
    setOfferFormData({
      price: "",
      currency: "ZAR",
      duration_minutes: "60",
      expiration_days: "7",
      notes: "",
      staff_id: "",
      location_id: "",
      scheduled_at: "",
    });
    setShowOfferModal(true);
  };

  const handleCreateOfferForRequest = async () => {
    if (!selectedRequestId || !offerFormData.price) {
      toast.error("Please fill in all required fields");
      return;
    }

    try {
      setIsSubmitting(true);
      const expirationDate = new Date();
      expirationDate.setDate(expirationDate.getDate() + parseInt(offerFormData.expiration_days));

      const payload = {
        price: parseFloat(offerFormData.price),
        currency: offerFormData.currency,
        duration_minutes: parseInt(offerFormData.duration_minutes),
        expiration_at: expirationDate.toISOString(),
        notes: offerFormData.notes || null,
        staff_id: offerFormData.staff_id || null,
        location_id: offerFormData.location_id || null,
        scheduled_at: offerFormData.scheduled_at ? new Date(offerFormData.scheduled_at).toISOString() : null,
      };

      await fetcher.post(`/api/provider/custom-requests/${selectedRequestId}/offers`, payload);
      toast.success("Offer created successfully!");
      setShowOfferModal(false);
      setSelectedRequestId(null);
      load();
    } catch (e: any) {
      toast.error(e?.message || "Failed to create offer");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <AuthGuard>
      <div className="w-full max-w-[950px] mx-auto px-4 md:px-6 lg:px-8 py-6 md:py-8 lg:py-12">
        <BackButton href="/account-settings" />
        <Breadcrumb items={[{ label: "Account", href: "/account-settings" }, { label: "Custom Requests" }]} />

        <div className="flex items-center justify-between mb-6">
          <h1 className="text-2xl md:text-3xl font-bold text-gray-900">Custom Requests</h1>
          {isProvider && (
            <Button onClick={() => setShowCreateModal(true)}>
              <Plus className="h-4 w-4 mr-2" />
              Create Custom Offer
            </Button>
          )}
        </div>

        {isProvider && (
          <p className="text-sm text-gray-600 mb-6">
            Set venue, staff, and appointment time when creating offers so the booking appears on the calendar and is assigned correctly once the customer pays.
          </p>
        )}

        {isLoading ? (
          <LoadingTimeout loadingMessage="Loading custom requests..." />
        ) : error ? (
          <EmptyState
            title="Failed to load"
            description={error}
            action={{ label: "Retry", onClick: load }}
          />
        ) : items.length === 0 ? (
          <EmptyState
            title={isProvider ? "No custom requests yet" : "No custom requests yet"}
            description={
              isProvider
                ? "Customer custom requests will appear here."
                : "Request a custom service from a provider to receive a tailored offer."
            }
          />
        ) : (
          <div className="space-y-4">
            {items.map((r) => (
              <div key={r.id} className="border rounded-lg p-4 bg-white">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1">
                    <div className="text-sm text-gray-600">
                      {isProvider ? (
                        <>
                          {r.customer?.full_name || r.customer?.email || "Customer"} ΓÇó{" "}
                          <span className="capitalize">{r.status}</span>
                        </>
                      ) : (
                        <>
                          {r.provider?.business_name ? r.provider.business_name : "Provider"} ΓÇó{" "}
                          <span className="capitalize">{r.status}</span>
                        </>
                      )}
                    </div>
                    <div className="font-medium mt-1">{r.description}</div>
                    <div className="text-sm text-gray-600 mt-2 space-y-0.5">
                      <span>
                        {r.preferred_start_at ? `Preferred: ${new Date(r.preferred_start_at).toLocaleString()}` : "Preferred: not set"} ΓÇó{" "}
                        {r.location_type === "at_salon" ? "At salon" : "At home"}
                        {r.budget_min != null || r.budget_max != null
                          ? ` ΓÇó Budget: ${r.budget_min ?? ""} - ${r.budget_max ?? ""}`
                          : ""}
                      </span>
                      {r.location_type === "at_home" && (r.address_line1 || r.address_city || r.address_country) && (
                        <div className="text-gray-500">
                          Address: {[r.address_line1, r.address_line2, r.address_city, r.address_state, r.address_country].filter(Boolean).join(", ") || "ΓÇö"}
                        </div>
                      )}
                    </div>
                  </div>
                  {isProvider && r.status === "pending" && (!r.offers || r.offers.length === 0) && (
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => openOfferModal(r.id)}
                    >
                      Create Offer
                    </Button>
                  )}
                </div>

                <div className="mt-4 space-y-2">
                  {r.offers && r.offers.length > 0 ? (
                    r.offers.map((o) => (
                      <div key={o.id} className="border rounded-md p-3 flex items-center justify-between gap-4">
                        <div className="min-w-0 flex-1">
                          <div className="font-medium">
                            Offer: {o.currency} {o.price} ΓÇó {o.duration_minutes} mins
                          </div>
                          <div className="text-sm text-gray-600 mt-1">
                            Expires: {new Date(o.expiration_at).toLocaleString()} ΓÇó <span className="capitalize">{o.status}</span>
                          </div>
                          {(o.location?.name || o.staff?.name) && (
                            <div className="text-sm text-gray-600 mt-1">
                              {o.location?.name && <span>Venue: {o.location.name}</span>}
                              {o.location?.name && o.staff?.name && " ΓÇó "}
                              {o.staff?.name && <span>Staff: {o.staff.name}</span>}
                            </div>
                          )}
                          {(o.scheduled_at ?? r.preferred_start_at) && (
                            <div className="text-sm text-gray-600">
                              Scheduled: {new Date(o.scheduled_at ?? r.preferred_start_at!).toLocaleString()}
                            </div>
                          )}
                          {o.notes ? <div className="text-sm mt-1">{o.notes}</div> : null}
                        </div>
                        {!isProvider && (
                          <div className="flex gap-2">
                            {o.status === "paid" ? (
                              <Button variant="secondary" disabled>
                                Paid
                              </Button>
                            ) : (
                              <Button onClick={() => acceptAndPay(o.id)}>Accept & Pay</Button>
                            )}
                          </div>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="text-sm text-gray-600">
                      {isProvider ? "No offers sent yet." : "No offers yet."}
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Create Custom Offer Modal */}
        <Dialog open={showCreateModal} onOpenChange={setShowCreateModal}>
          <DialogContent className="max-w-[95vw] sm:max-w-2xl max-h-[95vh] overflow-y-auto p-4 sm:p-6">
            <DialogHeader>
              <DialogTitle>Create Custom Offer</DialogTitle>
              <DialogDescription>
                Send a tailored service offer to a client. They can review and accept it to create a booking.
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4 mt-4">
              <div>
                <Label htmlFor="customer">Client *</Label>
                <Select
                  value={formData.customer_id}
                  onValueChange={(value) => setFormData({ ...formData, customer_id: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select a client" />
                  </SelectTrigger>
                  <SelectContent>
                    {isLoadingClients ? (
                      <SelectItem value="loading" disabled>Loading clients...</SelectItem>
                    ) : clients.length === 0 ? (
                      <SelectItem value="none" disabled>No clients found</SelectItem>
                    ) : (
                      clients.map((client) => (
                        <SelectItem key={client.customer_id} value={client.customer_id}>
                          {client.customer?.full_name || client.customer?.email || "Unknown"}
                        </SelectItem>
                      ))
                    )}
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label htmlFor="description">Service Description *</Label>
                <Textarea
                  id="description"
                  placeholder="Describe the custom service you're offering..."
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  rows={4}
                  maxLength={4000}
                />
                <p className="text-xs text-gray-500 mt-1">{formData.description.length}/4000 characters</p>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="location_type">Location Type</Label>
                  <Select
                    value={formData.location_type}
                    onValueChange={(value: "at_home" | "at_salon") =>
                      setFormData({ ...formData, location_type: value })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="at_salon">At Salon</SelectItem>
                      <SelectItem value="at_home">At Home</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <Label htmlFor="duration_minutes">Duration (minutes) *</Label>
                  <Input
                    id="duration_minutes"
                    type="number"
                    min="15"
                    max="480"
                    value={formData.duration_minutes}
                    onChange={(e) => setFormData({ ...formData, duration_minutes: e.target.value })}
                  />
                </div>
              </div>

              <div className={`grid gap-4 ${formData.location_type === "at_salon" ? "grid-cols-2" : "grid-cols-1"}`}>
                {formData.location_type === "at_salon" && (
                  <div>
                    <Label htmlFor="venue">Venue</Label>
                    <Select
                      value={formData.location_id || "none"}
                      onValueChange={(v) => setFormData({ ...formData, location_id: v === "none" ? "" : v })}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select venue" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="none">No specific venue</SelectItem>
                        {locationsList.map((loc) => (
                          <SelectItem key={loc.id} value={loc.id}>{loc.name}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                )}
                <div>
                  <Label htmlFor="staff">Assigned Staff</Label>
                  <Select
                    value={formData.staff_id || "none"}
                    onValueChange={(v) => setFormData({ ...formData, staff_id: v === "none" ? "" : v })}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select staff" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="none">No specific staff</SelectItem>
                      {staffList.map((s) => (
                        <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="price">Price *</Label>
                  <Input
                    id="price"
                    type="number"
                    min="0"
                    step="0.01"
                    value={formData.price}
                    onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                    placeholder="0.00"
                  />
                </div>

                <div>
                  <Label htmlFor="currency">Currency</Label>
                  <Select
                    value={formData.currency}
                    onValueChange={(value) => setFormData({ ...formData, currency: value })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="ZAR">ZAR</SelectItem>
                      <SelectItem value="USD">USD</SelectItem>
                      <SelectItem value="EUR">EUR</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="expiration_days">Offer Expires In (days)</Label>
                  <Input
                    id="expiration_days"
                    type="number"
                    min="1"
                    max="30"
                    value={formData.expiration_days}
                    onChange={(e) => setFormData({ ...formData, expiration_days: e.target.value })}
                  />
                </div>

                <div>
                  <Label htmlFor="preferred_start_at">Preferred Start Date (optional)</Label>
                  <Input
                    id="preferred_start_at"
                    type="datetime-local"
                    value={formData.preferred_start_at}
                    onChange={(e) => setFormData({ ...formData, preferred_start_at: e.target.value })}
                  />
                </div>
              </div>

              <div>
                <Label htmlFor="notes">Additional Notes (optional)</Label>
                <Textarea
                  id="notes"
                  placeholder="Add any additional information about this offer..."
                  value={formData.notes}
                  onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                  rows={3}
                  maxLength={4000}
                />
              </div>

              <div className="flex justify-end gap-2 pt-4">
                <Button variant="outline" onClick={() => setShowCreateModal(false)}>
                  Cancel
                </Button>
                <Button onClick={handleCreateOffer} disabled={isSubmitting}>
                  {isSubmitting ? "Sending..." : "Send Offer"}
                </Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>

        {/* Create Offer for Existing Request Modal */}
        <Dialog open={showOfferModal} onOpenChange={setShowOfferModal}>
          <DialogContent className="max-w-[95vw] sm:max-w-xl p-4 sm:p-6">
            <DialogHeader>
              <DialogTitle>Create Offer</DialogTitle>
              <DialogDescription>
                Create a custom offer for this request. The customer will be notified and can accept it.
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4 mt-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="offer_venue">Venue (for at salon)</Label>
                  <Select
                    value={offerFormData.location_id || "none"}
                    onValueChange={(v) => setOfferFormData({ ...offerFormData, location_id: v === "none" ? "" : v })}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select venue" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="none">No specific venue</SelectItem>
                      {locationsList.map((loc) => (
                        <SelectItem key={loc.id} value={loc.id}>{loc.name}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label htmlFor="offer_staff">Assigned Staff</Label>
                  <Select
                    value={offerFormData.staff_id || "none"}
                    onValueChange={(v) => setOfferFormData({ ...offerFormData, staff_id: v === "none" ? "" : v })}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select staff" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="none">No specific staff</SelectItem>
                      {staffList.map((s) => (
