    if (!prefs) return "On: Email and SMS";
    const channels = [];
    if (prefs.email) channels.push("Email");
    if (prefs.sms) channels.push("SMS");
    if (prefs.push) channels.push("Push");
    return channels.length > 0 ? `On: ${channels.join(", ")}` : "Off";
