);

const InfoCard: React.FC<{ title: string; content: string; img: any }> = ({ title, content, img }) => (
  <div className="mb-4 md:mb-5 pb-4 md:pb-5 border-b border-gray-200 last:border-0">
   <Image src={img} width={35} height={35} alt={title} className="mb-2" />
    <h3 className="font-medium text-sm md:text-base my-2 text-gray-900">{title}</h3>
    <p className="text-xs md:text-sm text-gray-600 font-light leading-relaxed">{content}</p>
  </div>
);

interface ModalProps {
  content: ModalContent;
  onClose: () => void;
  onSave: (newValue: any) => void;
  isSaving: boolean;
  initialData?: PersonalInfoData;
  countries?: Country[];
  defaultCountryCode?: string;
  defaultCountry?: string;
  languages?: string[];
}

const Modal: React.FC<ModalProps> = ({ content, onClose, onSave, isSaving, initialData, countries = [], defaultCountryCode = "+27", defaultCountry = "South Africa", languages = ['English'] }) => {
  // Initialize form data with existing values
  const getInitialFormData = () => {
    if (!initialData) return {};

    switch (content.type) {
      case 'legalName':
        return {
          first: initialData.legalName.first,
          last: initialData.legalName.last,
        };
      case 'preferredName':
        return {
          preferredName: initialData.preferredName !== 'Not provided' ? initialData.preferredName : '',
        };
      case 'email':
        // For email, we can't extract the full email from masked value
        // So we'll just use empty and let user re-enter
        return {
          email: '',
        };
      case 'phone':
        // For phone, we can't extract the full number from masked value
        // So we'll just use default values and let user re-enter
        const defaultPhoneCountry = countries.find(c => c.phone_country_code === defaultCountryCode) || countries[0];
        return {
          countryCode: defaultPhoneCountry ? `${defaultPhoneCountry.name} (${defaultPhoneCountry.phone_country_code})` : `${defaultCountry} (${defaultCountryCode})`,
          phone: '',
        };
      case 'address':
        return {
          country: initialData.address.country || defaultCountry,
          street: initialData.address.street,
          apt: initialData.address.apt,
          city: initialData.address.city,
          state: initialData.address.state,
          zip: initialData.address.zip,
        };
      case 'emergencyContact':
        const defaultECCountry = countries.find(c => c.phone_country_code === defaultCountryCode) || countries[0];
        return {
          name: initialData.emergencyContact.name || '',
          relationship: initialData.emergencyContact.relationship || '',
          language: initialData.emergencyContact.language || languages[0] || 'English',
          email: initialData.emergencyContact.email || '',
          countryCode: initialData.emergencyContact.countryCode ? 
            (initialData.emergencyContact.countryCode.includes('+') 
              ? countries.find(c => c.phone_country_code === initialData.emergencyContact.countryCode) 
                ? `${countries.find(c => c.phone_country_code === initialData.emergencyContact.countryCode)!.name} (${initialData.emergencyContact.countryCode})`
                : initialData.emergencyContact.countryCode
              : initialData.emergencyContact.countryCode) 
            : (defaultECCountry ? `${defaultECCountry.name} (${defaultECCountry.phone_country_code})` : `${defaultCountry} (${defaultCountryCode})`),
          phone: initialData.emergencyContact.phone || '',
        };
      case 'governmentId':
        return {
          documentType: '',
          country: initialData.address.country || defaultCountry,
          file: null,
        };
      default:
        return {};
    }
  };

  const [formData, setFormData] = useState<any>(getInitialFormData());
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);

  // Reset form data and file when modal content changes
  useEffect(() => {
    queueMicrotask(() => {
      setFormData(getInitialFormData());
      setSelectedFile(null);
      setFilePreview(null);
    });
  }, [content.type, initialData, countries, defaultCountryCode, defaultCountry, languages]); // eslint-disable-line react-hooks/exhaustive-deps -- getInitialFormData is stable; reset when modal content deps change

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedFile(file);
      // Create preview for images
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
          setFilePreview(reader.result as string);
        };
        reader.readAsDataURL(file);
      } else {
        setFilePreview(null);
      }
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Include file in form data if it's a government ID upload
    if (content.type === 'governmentId' && selectedFile) {
      onSave({ ...formData, file: selectedFile });
    } else {
      onSave(formData);
    }
  };

  return (
    <div 
      className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50"
      onClick={onClose}
    >
      <div 
        className="bg-white p-6 rounded-lg w-full max-w-md mx-4 max-h-[90vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-bold">{content.title}</h2>
          <button 
            onClick={onClose} 
            className="text-gray-500 hover:text-gray-700 text-2xl leading-none"
            aria-label="Close"
          >
            ├ù
          </button>
        </div>
        <p className="mb-4 text-gray-600 text-sm">{content.description}</p>
        <form onSubmit={handleSubmit}>
          {content.fields.map((field) => (
            <div key={field.name} className="mb-4">
              <label className="block mb-2 text-sm font-medium text-gray-700" htmlFor={field.name}>
                {field.label}
              </label>
              {field.type === 'file' ? (
                <div>
                  <input
                    type="file"
                    id={field.name}
                    name={field.name}
                    accept={field.accept || "image/*,.pdf"}
                    className="w-full p-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#FF0077] focus:border-transparent"
                    onChange={handleFileChange}
                    required={content.type === 'governmentId'}
                  />
                  {filePreview && (
                    <div className="mt-2 relative w-full h-48">
                      <Image src={filePreview} alt="Preview" fill className="object-contain border border-gray-300 rounded-md" unoptimized />
                    </div>
                  )}
                  {selectedFile && !filePreview && (
                    <div className="mt-2 text-sm text-gray-600">
                      Selected: {selectedFile.name} ({(selectedFile.size / 1024 / 1024).toFixed(2)} MB)
                    </div>
                  )}
                  <p className="mt-1 text-xs text-gray-500">
                    Accepted formats: JPEG, PNG, WebP, PDF (Max 10MB)
                  </p>
                </div>
              ) : field.type === 'select' ? (
                <select
                  id={field.name}
                  name={field.name}
                  value={formData[field.name] || ''}
                  className="w-full p-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#FF0077] focus:border-transparent"
                  onChange={handleChange}
                  required={field.name !== 'apt' && field.name !== 'line2'}
                >
                  <option value="">Select {field.label}</option>
                  {field.options?.map((option) => (
                    <option key={option} value={option}>{option}</option>
                  ))}
                </select>
              ) : (
                <input
                  type={field.type}
                  id={field.name}
                  name={field.name}
                  value={formData[field.name] || ''}
                  className="w-full p-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#FF0077] focus:border-transparent"
                  onChange={handleChange}
                  required={field.name !== 'apt' && field.name !== 'line2' && field.name !== 'preferredName'}
                />
              )}
            </div>
          ))}
          <div className="flex justify-end gap-3 mt-6">
            <button
              type="button"
              onClick={onClose}
              disabled={isSaving}
              className="px-4 py-2 border border-gray-300 text-gray-700 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isSaving || (content.type === 'governmentId' && !selectedFile)}
              className="px-4 py-2 bg-black text-white rounded-md hover:bg-gray-800 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isSaving
                ? "Uploading..."
                : content.type === "phone"
                ? "Verify"
                : content.type === "governmentId"
                ? "Upload for Verification"
                : "Save"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

const getModalContent = (type: keyof PersonalInfoData, countries: Country[] = [], languages: string[] = ['English']): ModalContent => {
  // Generate country options for phone
  const phoneCountryOptions = countries
    .filter(c => c.phone_country_code)
    .map(c => `${c.name} (${c.phone_country_code})`);

  // Generate country options for address
  const addressCountryOptions = countries.map(c => c.name);

  // Generate language options
  const languageOptions = languages.length > 0 ? languages : ['English'];

  switch (type) {
    case 'legalName':
      return {
        type: 'legalName',
        title: 'Legal name',
        description: 'Make sure this matches the name on your government ID.',
        fields: [
          { name: 'first', label: 'First name on ID', type: 'text' },
          { name: 'last', label: 'Last name on ID', type: 'text' },
        ],
      };
    case 'preferredName':
      return {
        type: 'preferredName',
        title: 'Preferred name',
        description: 'This is how your first name will appear to Providers and clients. Learn more',
        fields: [
          { name: 'preferredName', label: 'Preferred name (optional)', type: 'text' },
        ],
      };
    case 'email':
      return {
        type: 'email',
        title: 'Email address',
        description: 'Use an address you\'ll always have access to.',
        fields: [
          { name: 'email', label: 'Email address', type: 'email' },
        ],
      };
    case 'phone':
      return {
        type: 'phone',
        title: 'Phone number',
        description: 'For notifications, reminders, and help logging in',
        fields: [
          { name: 'countryCode', label: 'Country code', type: 'select', options: phoneCountryOptions.length > 0 ? phoneCountryOptions : ['South Africa (+27)'] },
          { name: 'phone', label: 'Phone number', type: 'tel' },
        ],
      };
    case 'address':
      return {
        type: 'address',
        title: 'Address',
        description: 'Use a permanent address where you can receive mail.',
        fields: [
          { name: 'country', label: 'Country/region', type: 'select', options: addressCountryOptions.length > 0 ? addressCountryOptions : ['South Africa'] },
          { name: 'street', label: 'Street address', type: 'text' },
          { name: 'apt', label: 'Apt, suite. (optional)', type: 'text' },
          { name: 'city', label: 'City', type: 'text' },
          { name: 'state', label: 'State / Province / County / Region', type: 'text' },
          { name: 'zip', label: 'ZIP code', type: 'text' },
        ],
      };
    case 'emergencyContact':
      return {
        type: 'emergencyContact',
        title: 'Emergency contact',
        description: 'A trusted contact we can alert in an urgent situation.',
        fields: [
          { name: 'name', label: 'Name', type: 'text' },
          { name: 'relationship', label: 'Relationship', type: 'text' },
          { name: 'language', label: 'Preferred language', type: 'select', options: languageOptions },
          { name: 'email', label: 'Email', type: 'email' },
          { name: 'countryCode', label: 'Country code', type: 'select', options: phoneCountryOptions.length > 0 ? phoneCountryOptions : ['South Africa (+27)'] },
          { name: 'phone', label: 'Phone number', type: 'tel' },
        ],
      };
    case 'governmentId':
      return {
        type: 'governmentId',
        title: 'Government ID',
        description: 'Upload a government-issued ID for identity verification. This helps keep our community safe. Your document will be reviewed by our team.',
        fields: [
          { name: 'documentType', label: 'Document type', type: 'select', options: ['Driver\'s License', 'Passport', 'National ID'] },
          { name: 'country', label: 'Country', type: 'select', options: addressCountryOptions.length > 0 ? addressCountryOptions : ['South Africa'] },
          { name: 'file', label: 'Upload document', type: 'file', accept: 'image/*,.pdf' },
        ],
      };
    default:
      throw new Error(`Unknown modal type: ${type}`);
  }
};

export default PersonalInfo;

"use client";

import React, { useState, useEffect } from 'react';
import { motion } from "framer-motion";
import Breadcrumb from "@/components/ui/breadcrumb";
import BackButton from "@/components/ui/back-button";
import BottomNav from "@/components/layout/bottom-nav";
import AuthGuard from "@/components/auth/auth-guard";
import { useAuth } from "@/providers/AuthProvider";
import { useRouter } from "next/navigation";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Edit, Check, X, Globe, Loader2 } from "lucide-react";

type PreferenceField = "language" | "currency" | "timezone" | null;

interface PreferenceOption {
  id: string;
  type: 'language' | 'currency' | 'timezone';
  code: string | null;
  name: string;
  display_order: number;
  metadata?: any;
}

interface Preferences {
  language: { code: string; name: string } | null;
  currency: { code: string; name: string } | null;
  timezone: { code: string; name: string } | null;
}

const GlobalPreferences: React.FC = () => {
  const { user } = useAuth();
  const [editingField, setEditingField] = useState<PreferenceField>(null);
  const [preferences, setPreferences] = useState<Preferences>({
    language: null,
    currency: null,
    timezone: null,
  });
  const [tempValue, setTempValue] = useState<string>("");
  const [options, setOptions] = useState<{
    languages: PreferenceOption[];
    currencies: PreferenceOption[];
    timezones: PreferenceOption[];
  }>({
    languages: [],
    currencies: [],
    timezones: [],
  });
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const router = useRouter();

  useEffect(() => {
    if (user) {
      loadOptionsAndPreferences();
    }
  }, [user]); // eslint-disable-line react-hooks/exhaustive-deps -- load when user changes

  const loadOptionsAndPreferences = async () => {
    if (!user) return;

    try {
      setIsLoading(true);

      // Load options and preferences in parallel
      const [langsRes, currenciesRes, timezonesRes, profileRes] = await Promise.all([
        fetcher.get<{ data: PreferenceOption[] }>("/api/public/preference-options?type=language"),
        fetcher.get<{ data: PreferenceOption[] }>("/api/public/preference-options?type=currency"),
        fetcher.get<{ data: PreferenceOption[] }>("/api/public/preference-options?type=timezone"),
        fetcher.get<{ 
          data: { 
            preferred_language: string | null; 
            preferred_currency: string | null; 
            timezone: string | null;
          } 
        }>("/api/me/profile", { cache: "no-store" }),
      ]);

      const loadedOptions = {
        languages: langsRes.data || [],
        currencies: currenciesRes.data || [],
        timezones: timezonesRes.data || [],
      };

      setOptions(loadedOptions);

      // Now load preferences with the loaded options
      const data = profileRes.data;
      const languageCode = data?.preferred_language || "en";
      const currencyCode = data?.preferred_currency || "ZAR";
      const timezoneCode = data?.timezone || "Africa/Johannesburg";

      const languageOption = loadedOptions.languages.find(l => l.code === languageCode) || 
        loadedOptions.languages.find(l => l.code === "en") || 
        { code: "en", name: "English" };
      const currencyOption = loadedOptions.currencies.find(c => c.code === currencyCode) || 
        loadedOptions.currencies.find(c => c.code === "ZAR") || 
        { code: "ZAR", name: "South African Rand" };
      const timezoneOption = loadedOptions.timezones.find(t => t.code === timezoneCode) || 
        loadedOptions.timezones.find(t => t.code === "Africa/Johannesburg") || 
        { code: "Africa/Johannesburg", name: "Africa/Johannesburg" };

      setPreferences({
        language: { code: languageOption.code || "en", name: languageOption.name },
        currency: { code: currencyOption.code || "ZAR", name: currencyOption.name },
        timezone: { code: timezoneOption.code || "Africa/Johannesburg", name: timezoneOption.name },
      });
    } catch (error) {
      console.error("Failed to load preferences:", error);
      toast.error("Failed to load preferences");
    } finally {
      setIsLoading(false);
    }
  };

  const handleEdit = (field: PreferenceField) => {
    if (!field) return;

    if (editingField === field) {
      // Cancel edit
      setEditingField(null);
      setTempValue("");
    } else {
      // Start editing
      const currentValue = preferences[field]?.code || "";
      setTempValue(currentValue);
      setEditingField(field);
    }
  };

  const handleSave = async (field: PreferenceField) => {
    if (!field || !tempValue) return;

    try {
      setIsSaving(true);
      const updateData: Record<string, string> = {};

      if (field === "language") {
        updateData.preferred_language = tempValue;
      } else if (field === "currency") {
        updateData.preferred_currency = tempValue;
      } else if (field === "timezone") {
        updateData.timezone = tempValue;
      }

      await fetcher.patch("/api/me/profile", updateData);

      // Find the option to get the name
      const optionList = field === "language" ? options.languages : 
                        field === "currency" ? options.currencies : 
                        options.timezones;
      const selectedOption = optionList.find(o => o.code === tempValue);

      // Update preferences state
      setPreferences({
        ...preferences,
        [field]: {
          code: tempValue,
          name: selectedOption?.name || tempValue,
        },
      });

      toast.success(`${field === "language" ? "Language" : field === "currency" ? "Currency" : "Timezone"} updated successfully`);
      setEditingField(null);
      setTempValue("");
      router.refresh();
    } catch (error: any) {
      console.error("Failed to save preference:", error);
      toast.error(error.message || "Failed to save preference");
    } finally {
      setIsSaving(false);
    }
  };

  const getCurrentOptions = (field: PreferenceField): PreferenceOption[] => {
    if (field === "language") return options.languages;
    if (field === "currency") return options.currencies;
    return options.timezones;
  };

  const renderField = (
    label: string, 
    field: PreferenceField,
    icon: React.ReactNode
  ) => {
    if (!field) return null;

    const isEditing = editingField === field;
    const currentPreference = preferences[field];
    const currentOptions = getCurrentOptions(field);

    return (
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 mb-6"
      >
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-gradient-to-br from-[#FF0077]/10 to-[#E6006A]/10 rounded-lg">
              {icon}
            </div>
            <div>
              <h2 className="text-lg font-semibold tracking-tighter text-gray-900">{label}</h2>
              {!isEditing && currentPreference && (
                <p className="text-sm font-light text-gray-600 mt-1">{currentPreference.name}</p>
              )}
            </div>
          </div>

          {!isEditing ? (
            <motion.button
              onClick={() => handleEdit(field)}
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              className="flex items-center gap-2 px-4 py-2 text-[#FF0077] hover:bg-[#FF0077]/10 rounded-lg transition-colors font-medium"
            >
              <Edit className="w-4 h-4" />
              <span>Edit</span>
            </motion.button>
          ) : (
            <div className="flex items-center gap-2">
              <motion.button
                onClick={() => handleEdit(field)}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className="p-2 text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                disabled={isSaving}
              >
                <X className="w-4 h-4" />
              </motion.button>
              <motion.button
                onClick={() => handleSave(field)}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className="p-2 text-[#FF0077] hover:bg-[#FF0077]/10 rounded-lg transition-colors"
                disabled={isSaving || !tempValue}
              >
                {isSaving ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <Check className="w-4 h-4" />
                )}
              </motion.button>
            </div>
          )}
        </div>

        {isEditing && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="mt-4"
          >
            <Select
              value={tempValue}
              onValueChange={setTempValue}
            >
              <SelectTrigger className="w-full backdrop-blur-sm bg-white/60 border-white/40">
                <SelectValue placeholder={`Select ${label.toLowerCase()}`} />
              </SelectTrigger>
              <SelectContent>
                {currentOptions.map((option) => (
                  <SelectItem key={option.id} value={option.code || option.name}>
                    {option.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </motion.div>
        )}
      </motion.div>
    );
  };

  return (
    <AuthGuard>
      <div className="min-h-screen bg-zinc-50/50 pb-20 md:pb-0">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-6 md:py-8">
          <Breadcrumb 
            items={[
              { label: "Home", href: "/" },
              { label: "Account Settings", href: "/account-settings" },
              { label: "Global preferences" }
            ]} 
          />
          <BackButton href="/account-settings" />

          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3 }}
            className="mt-6"
          >
            <h1 className="text-3xl md:text-4xl font-semibold tracking-tighter text-gray-900 mb-8">
              Global preferences
            </h1>

            {isLoading ? (
              <div className="flex items-center justify-center py-20">
                <Loader2 className="w-8 h-8 text-[#FF0077] animate-spin" />
              </div>
            ) : (
              <div className="flex flex-col lg:flex-row gap-6">
                {/* Main Content */}
                <div className="w-full lg:w-2/3">
                  {renderField("Preferred language", "language", <Globe className="w-5 h-5 text-[#FF0077]" />)}
                  {renderField("Preferred currency", "currency", <Globe className="w-5 h-5 text-[#FF0077]" />)}
                  {renderField("Time zone", "timezone", <Globe className="w-5 h-5 text-[#FF0077]" />)}
                </div>

                {/* Sidebar */}
                <div className="w-full lg:w-1/3">
                  <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 sticky top-6"
                  >
                    <div className="flex items-center gap-3 mb-4">
                      <div className="p-3 bg-gradient-to-br from-[#FF0077]/10 to-[#E6006A]/10 rounded-xl">
                        <Globe className="w-6 h-6 text-[#FF0077]" />
                      </div>
                      <h2 className="text-lg font-semibold tracking-tighter text-gray-900">
                        Your global preferences
                      </h2>
                    </div>
                    <p className="text-sm font-light text-gray-600 leading-relaxed">
                      Changing your currency updates how you see prices. You can change how you get payments in your payments & payouts preferences.
                    </p>
                  </motion.div>
                </div>
              </div>
            )}
          </motion.div>
        </div>
        <BottomNav />
      </div>
    </AuthGuard>
  );
};

export default GlobalPreferences;

"use client";

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Switch } from "@/components/ui/switch";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Eye, Share2, Download, Trash2, HelpCircle } from "lucide-react";
import Breadcrumb from "../components/breadcrumb";
import BackButton from "../components/back-button";
import AuthGuard from "@/components/auth/auth-guard";
import { toast } from "sonner";
import { fetcher } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";

const tabs = [
  { value: "account", label: "Account" },
  { value: "data", label: "Data" },
  { value: "sharing", label: "Sharing" },
  { value: "services", label: "Services" },
];

const PrivacyPage = () => {
  const [activeTab, setActiveTab] = useState("account");

  // Account tab states
  const [accountVisibility, setAccountVisibility] = useState(false);
  const [profileInformation, setProfileInformation] = useState(false);

  // Sharing tab states
  const [readReceipts, setReadReceipts] = useState(false);
  const [includeInSearchEngines, setIncludeInSearchEngines] = useState(false);
  const [showHomeCity, setShowHomeCity] = useState(false);
  const [showTripType, setShowTripType] = useState(false);
  const [showLengthOfStay, setShowLengthOfStay] = useState(false);

  // Data tab states
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);
  const [deletePassword, setDeletePassword] = useState("");
  const [deleteConfirmText, setDeleteConfirmText] = useState("");
  const [deleteReason, setDeleteReason] = useState("");
  const [isRequestingData, setIsRequestingData] = useState(false);
  const [isDeletingAccount, setIsDeletingAccount] = useState(false);

  const DELETE_CONFIRM_PHRASE = "DELETE";
  const canConfirmDelete =
    !!deletePassword?.trim() &&
    deleteConfirmText?.trim().toUpperCase() === DELETE_CONFIRM_PHRASE;
  const [isLoadingSettings, setIsLoadingSettings] = useState(true);
  const [dataExportStatus, setDataExportStatus] = useState<{
    isReady: boolean;
    isPending: boolean;
    downloadUrl?: string;
    fileName?: string;
  } | null>(null);

  useEffect(() => {
    loadPrivacySettings();
    loadDataExportStatus();
  }, []);

  const loadPrivacySettings = async () => {
    try {
      setIsLoadingSettings(true);
      const response = await fetcher.get<{
        data: {
          accountVisibility: boolean;
          profileInformation: boolean;
          readReceipts: boolean;
          includeInSearchEngines: boolean;
          showHomeCity: boolean;
          showTripType: boolean;
          showLengthOfStay: boolean;
        };
      }>("/api/me/privacy-settings", { cache: "no-store" });

      const settings = response.data || (response as any);

      setAccountVisibility(settings.accountVisibility ?? false);
      setProfileInformation(settings.profileInformation ?? false);
      setReadReceipts(settings.readReceipts ?? false);
      setIncludeInSearchEngines(settings.includeInSearchEngines ?? false);
      setShowHomeCity(settings.showHomeCity ?? false);
      setShowTripType(settings.showTripType ?? false);
      setShowLengthOfStay(settings.showLengthOfStay ?? false);
    } catch (error: any) {
      console.error("Failed to load privacy settings:", error);
      toast.error("Failed to load privacy settings. Please try again.");
    } finally {
      setIsLoadingSettings(false);
    }
  };

  const updatePrivacySetting = async (setting: string, value: boolean) => {
    try {
      await fetcher.patch("/api/me/privacy-settings", {
        [setting]: value,
      });
      toast.success("Setting updated successfully");
      await loadPrivacySettings();
    } catch (error: any) {
      toast.error(error.message || "Failed to update setting. Please try again.");
      throw error;
    }
  };

  const loadDataExportStatus = async () => {
    try {
      const response = await fetcher.get<{
        data: {
          isReady: boolean;
          isPending: boolean;
          downloadUrl?: string;
          fileName?: string;
          requestedAt?: string;
          readyAt?: string;
        };
      }>("/api/me/request-data", { cache: "no-store" });

      const responseData = response.data || (response as any);

      setDataExportStatus({
        isReady: responseData.isReady || false,
        isPending: responseData.isPending || false,
        downloadUrl: responseData.downloadUrl,
        fileName: responseData.fileName,
      });
    } catch (error: any) {
      console.error("Failed to load data export status:", error);
      // Set default state on error
      setDataExportStatus({
        isReady: false,
        isPending: false,
      });
    }
  };

  const handleRequestData = async () => {
    try {
      setIsRequestingData(true);
      const response = await fetcher.post<{
        data: {
          message: string;
          downloadUrl?: string;
          fileName?: string;
          requestedAt?: string;
        };
      }>("/api/me/request-data");

      const responseData = response.data || response as any;

      if (responseData.downloadUrl) {
        setDataExportStatus({
          isReady: true,
          isPending: false,
          downloadUrl: responseData.downloadUrl,
          fileName: responseData.fileName || `beautonomi-data-export-${new Date().toISOString().split('T')[0]}.json`,
        });
        toast.success("Your data export is ready for download!");

        // Trigger download
        if (responseData.downloadUrl.startsWith("data:")) {
          const link = document.createElement("a");
          link.href = responseData.downloadUrl;
          link.download = responseData.fileName || "beautonomi-data-export.json";
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
        } else if (responseData.downloadUrl) {
          // If it's a URL, open in new tab
          window.open(responseData.downloadUrl, '_blank');
        }
      } else {
        toast.success(responseData.message || "Your data request has been submitted.");
        await loadDataExportStatus();
      }
    } catch (error: any) {
      toast.error(error.message || "Failed to request your data. Please try again.");
    } finally {
      setIsRequestingData(false);
    }
  };

  const handleDownloadData = () => {
    if (dataExportStatus?.downloadUrl) {
      if (dataExportStatus.downloadUrl.startsWith("data:")) {
        const link = document.createElement("a");
        link.href = dataExportStatus.downloadUrl;
        link.download = dataExportStatus.fileName || "beautonomi-data-export.json";
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      } else {
        // If it's a URL, open in new tab
        window.open(dataExportStatus.downloadUrl, '_blank');
      }
    } else {
      toast.error("Download URL not available. Please request your data again.");
    }
  };

  const handleDeleteAccount = async () => {
    if (!deletePassword) {
      toast.error("Password is required to delete your account");
      return;
    }

    try {
      setIsDeletingAccount(true);
      await fetcher.post("/api/me/delete-account", {
        password: deletePassword,
        reason: deleteReason || null,
      });
      toast.success("Your account deletion request has been submitted.");
      setShowDeleteDialog(false);
      setDeletePassword("");
      setDeleteConfirmText("");
      setDeleteReason("");
      setTimeout(() => {
        window.location.href = "/";
      }, 2000);
    } catch (error: any) {
      toast.error(error.message || "Failed to delete your account. Please try again.");
    } finally {
      setIsDeletingAccount(false);
    }
  };

  if (isLoadingSettings) {
    return (
      <AuthGuard>
        <div className="min-h-screen bg-zinc-50/50">
          <div className="w-full max-w-5xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
            <LoadingTimeout loadingMessage="Loading privacy settings..." />
          </div>
        </div>
      </AuthGuard>
    );
  }

  return (
    <AuthGuard>
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-5xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
            className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 md:p-8 mt-8 mb-12"
          >
            <BackButton href="/account-settings" />
            <Breadcrumb
              items={[
                { label: "Account", href: "/account-settings" },
                { label: "Privacy & sharing" },
              ]}
            />

            <motion.h1
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.2, duration: 0.5, ease: "easeOut" }}
              className="text-2xl md:text-3xl font-semibold tracking-tighter text-gray-900 border-b border-gray-200 mb-6 pb-4 mt-4 md:mt-6"
            >
              Privacy and sharing
            </motion.h1>

            <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
              <TabsList className="mb-6 grid grid-cols-4 w-full h-auto p-1 bg-gray-100 rounded-xl shadow-inner border border-gray-200">
                {tabs.map((tab) => (
                  <TabsTrigger
                    key={tab.value}
                    value={tab.value}
                    className="text-xs md:text-sm font-medium text-gray-700 data-[state=active]:bg-white data-[state=active]:text-[#FF0077] data-[state=active]:shadow-md data-[state=active]:border data-[state=active]:border-white/40 data-[state=active]:ring-1 data-[state=active]:ring-inset data-[state=active]:ring-gray-200 rounded-lg transition-all duration-200"
                  >
                    {tab.label}
                  </TabsTrigger>
                ))}
              </TabsList>

              <TabsContent value="account">
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.3, duration: 0.5, ease: "easeOut" }}
                  className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-lg rounded-2xl p-6 md:p-8 space-y-8"
                >
                  <div>
                    <h2 className="text-xl font-semibold tracking-tight text-gray-900 mb-2">
                      Privacy and sharing
                    </h2>
                    <p className="text-sm md:text-base font-light text-gray-600 mb-6">
                      Manage your privacy settings and how your information is shared.
                    </p>

                    <div className="space-y-6">
                      <motion.div
                        whileHover={{ scale: 1.01 }}
                        className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-5"
                      >
                        <div className="flex items-center justify-between">
                          <div className="flex-1">
                            <div className="flex items-center gap-3 mb-2">
                              <div className="p-2 bg-pink-50 rounded-full border border-pink-100">
                                <Eye className="w-5 h-5 text-[#FF0077]" />
                              </div>
                              <div>
                                <h3 className="text-base font-semibold text-gray-900">
                                  Account visibility
                                </h3>
                                <p className="text-sm font-light text-gray-600">
                                  Control who can see your profile and account information.
                                </p>
                              </div>
                            </div>
                          </div>
                          <Switch
                            checked={accountVisibility}
                            disabled={isLoadingSettings}
                            onCheckedChange={async (checked) => {
                              const previousValue = accountVisibility;
                              setAccountVisibility(checked);
                              try {
                                await updatePrivacySetting("accountVisibility", checked);
                              } catch {
                                setAccountVisibility(previousValue);
                              }
                            }}
                            className="data-[state=checked]:bg-[#FF0077] data-[state=unchecked]:bg-gray-300"
                          />
                        </div>
                      </motion.div>

                      <motion.div
                        whileHover={{ scale: 1.01 }}
                        className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-5"
                      >
                        <div className="flex items-center justify-between">
                          <div className="flex-1">
                            <div className="flex items-center gap-3 mb-2">
                              <div className="p-2 bg-pink-50 rounded-full border border-pink-100">
                                <Share2 className="w-5 h-5 text-[#FF0077]" />
                              </div>
                              <div>
                                <h3 className="text-base font-semibold text-gray-900">
                                  Profile information
                                </h3>
                                <p className="text-sm font-light text-gray-600">
                                  Manage what information is visible on your public profile.
                                </p>
                              </div>
                            </div>
                          </div>
                          <Switch
                            checked={profileInformation}
                            disabled={isLoadingSettings}
                            onCheckedChange={async (checked) => {
                              const previousValue = profileInformation;
                              setProfileInformation(checked);
                              try {
                                await updatePrivacySetting("profileInformation", checked);
                              } catch {
                                setProfileInformation(previousValue);
                              }
                            }}
                            className="data-[state=checked]:bg-[#FF0077] data-[state=unchecked]:bg-gray-300"
                          />
                        </div>
                      </motion.div>
                    </div>
                  </div>

                  {/* Help Section */}
                  <motion.div
