"use client";

import React, { useState, useEffect } from "react";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Calendar, Clock, MapPin, Pause, Play, X } from "lucide-react";
import AuthGuard from "@/components/auth/auth-guard";
import { toast } from "sonner";
import BackButton from "../components/back-button";

interface RecurringBooking {
  id: string;
  frequency: "weekly" | "biweekly" | "monthly";
  start_date: string;
  end_date: string | null;
  preferred_time: string;
  location_type: "at_home" | "at_salon";
  is_active: boolean;
  provider: {
    id: string;
    business_name: string;
    slug: string;
  };
  metadata: {
    services?: Array<{ offering_id: string; staff_id?: string }>;
    address?: any;
  };
  created_at: string;
}

export default function RecurringBookingsPage() {
  const [recurring, setRecurring] = useState<RecurringBooking[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadRecurring();
  }, []);

  const loadRecurring = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const response = await fetcher.get<{ data: { recurring: RecurringBooking[] } }>(
        "/api/recurring-bookings",
        { cache: "no-store" }
      );
      setRecurring(response.data.recurring || []);
    } catch (err) {
      setError(err instanceof FetchError ? err.message : "Failed to load recurring bookings");
      console.error("Error loading recurring bookings:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleToggle = async (id: string, isActive: boolean) => {
    try {
      await fetcher.patch(`/api/recurring-bookings/${id}`, {
        is_active: !isActive,
      });
      toast.success(isActive ? "Recurring booking paused" : "Recurring booking resumed");
      loadRecurring();
    } catch (err) {
      toast.error(err instanceof FetchError ? err.message : "Failed to update recurring booking");
    }
  };

  const handleCancel = async (id: string) => {
    if (!confirm("Are you sure you want to cancel this recurring booking?")) {
      return;
    }

    try {
      await fetcher.delete(`/api/recurring-bookings/${id}`);
      toast.success("Recurring booking cancelled");
      loadRecurring();
    } catch (err) {
      toast.error(err instanceof FetchError ? err.message : "Failed to cancel recurring booking");
    }
  };

  const getFrequencyLabel = (freq: string) => {
    const labels: Record<string, string> = {
      weekly: "Weekly",
      biweekly: "Bi-weekly",
      monthly: "Monthly",
    };
    return labels[freq] || freq;
  };

  if (isLoading) {
    return (
      <AuthGuard>
        <div className="container mx-auto px-4 py-8">
          <LoadingTimeout loadingMessage="Loading recurring bookings..." />
        </div>
      </AuthGuard>
    );
  }

  return (
    <AuthGuard>
      <div className="container mx-auto px-4 py-8">
        <BackButton href="/account-settings" />
        <h1 className="text-3xl font-bold mb-6">Recurring Bookings</h1>

        {error && (
          <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg">
            <p className="text-red-600">{error}</p>
          </div>
        )}

        <div className="space-y-4">
          {recurring.length === 0 ? (
            <Card>
              <CardContent className="py-8 text-center">
                <p className="text-gray-600 mb-4">No recurring bookings</p>
                <p className="text-sm text-gray-500">
                  Create a recurring booking to automatically schedule appointments
                </p>
              </CardContent>
            </Card>
          ) : (
            recurring.map((booking) => (
              <Card key={booking.id}>
                <CardHeader>
                  <div className="flex justify-between items-start">
                    <div>
                      <CardTitle>{booking.provider.business_name}</CardTitle>
                      <div className="flex items-center gap-2 mt-2">
                        <Badge variant={booking.is_active ? "default" : "secondary"}>
                          {booking.is_active ? "Active" : "Paused"}
                        </Badge>
                        <Badge variant="outline">{getFrequencyLabel(booking.frequency)}</Badge>
                      </div>
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  <div className="space-y-3 mb-4">
                    <div className="flex items-center gap-2">
                      <Calendar className="w-4 h-4 text-gray-400" />
                      <div>
                        <p className="text-sm font-semibold">Start Date</p>
                        <p className="text-sm text-gray-600">
                          {new Date(booking.start_date).toLocaleDateString()}
                        </p>
                      </div>
                    </div>
                    {booking.end_date && (
                      <div className="flex items-center gap-2">
                        <Calendar className="w-4 h-4 text-gray-400" />
                        <div>
                          <p className="text-sm font-semibold">End Date</p>
                          <p className="text-sm text-gray-600">
                            {new Date(booking.end_date).toLocaleDateString()}
                          </p>
                        </div>
                      </div>
                    )}
                    <div className="flex items-center gap-2">
                      <Clock className="w-4 h-4 text-gray-400" />
                      <div>
                        <p className="text-sm font-semibold">Preferred Time</p>
                        <p className="text-sm text-gray-600">{booking.preferred_time}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <MapPin className="w-4 h-4 text-gray-400" />
                      <div>
                        <p className="text-sm font-semibold">Location</p>
                        <p className="text-sm text-gray-600">
                          {booking.location_type === "at_home" ? "At Home" : "At Salon"}
                        </p>
                      </div>
                    </div>
                  </div>

                  <div className="flex gap-2 pt-4 border-t">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleToggle(booking.id, booking.is_active)}
                    >
                      {booking.is_active ? (
                        <>
                          <Pause className="w-4 h-4 mr-1" />
                          Pause
                        </>
                      ) : (
                        <>
                          <Play className="w-4 h-4 mr-1" />
                          Resume
                        </>
                      )}
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleCancel(booking.id)}
                      className="text-red-600 hover:text-red-700"
                    >
                      <X className="w-4 h-4 mr-1" />
                      Cancel
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>
      </div>
    </AuthGuard>
  );
}

"use client";

import { useState, useEffect } from "react";
import { X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { motion } from "framer-motion";
import { fetcher } from "@/lib/http/fetcher";

interface TaxInfoModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (data: any) => Promise<void>;
  initialData?: any;
}

export default function TaxInfoModal({ isOpen, onClose, onSave, initialData }: TaxInfoModalProps) {
  const [countries, setCountries] = useState<Array<{ code: string; name: string }>>([]);
  const [formData, setFormData] = useState({
    country: "",
    tax_id: "",
    full_name: "",
    address: {
      line1: "",
      line2: "",
      city: "",
      state: "",
      postal_code: "",
      country: "",
    },
  });
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (isOpen) {
      // Load countries
      fetcher.get<{ data: Array<{ code: string; name: string }> }>("/api/public/countries")
        .then((response) => {
          setCountries(response.data || []);
        })
        .catch(() => {
          // Fallback countries
          setCountries([
            { code: "US", name: "United States" },
            { code: "ZA", name: "South Africa" },
            { code: "GB", name: "United Kingdom" },
            { code: "CA", name: "Canada" },
          ]);
        });

      // Pre-fill form if editing
      if (initialData) {
        setFormData({
          country: initialData.country || "",
          tax_id: initialData.tax_id || "",
          full_name: initialData.full_name || "",
          address: {
            line1: initialData.address?.line1 || "",
            line2: initialData.address?.line2 || "",
            city: initialData.address?.city || "",
            state: initialData.address?.state || "",
            postal_code: initialData.address?.postal_code || "",
            country: initialData.address?.country || initialData.country || "",
          },
        });
      }
    }
  }, [isOpen, initialData]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      await onSave(formData);
    } catch {
      // Error already handled in parent
    } finally {
      setIsLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.95 }}
        className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto"
      >
        <div className="sticky top-0 bg-white border-b border-gray-200 px-6 py-4 flex items-center justify-between z-10">
          <h2 className="text-xl font-semibold text-gray-900">Add tax info</h2>
          <button
            onClick={onClose}
            className="text-gray-500 hover:text-gray-700 transition-colors"
            aria-label="Close"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          <div>
            <Label htmlFor="country" className="text-sm font-medium text-gray-700 mb-2 block">
              Country/Region *
            </Label>
            <Select
              value={formData.country}
              onValueChange={(value) => {
                setFormData({
                  ...formData,
                  country: value,
                  address: { ...formData.address, country: value },
                });
              }}
            >
              <SelectTrigger id="country" className="w-full">
                <SelectValue placeholder="Select a country" />
              </SelectTrigger>
              <SelectContent>
                {countries.map((country) => (
                  <SelectItem key={country.code} value={country.name}>
                    {country.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label htmlFor="tax_id" className="text-sm font-medium text-gray-700 mb-2 block">
              Tax ID / SSN / TIN *
            </Label>
            <Input
              id="tax_id"
              value={formData.tax_id}
              onChange={(e) => setFormData({ ...formData, tax_id: e.target.value })}
              placeholder="Enter your tax identification number"
              required
            />
          </div>

          <div>
            <Label htmlFor="full_name" className="text-sm font-medium text-gray-700 mb-2 block">
              Full Name (as on tax documents) *
            </Label>
            <Input
              id="full_name"
              value={formData.full_name}
              onChange={(e) => setFormData({ ...formData, full_name: e.target.value })}
              placeholder="Enter your full legal name"
              required
            />
          </div>

          <div className="space-y-4">
            <h3 className="text-base font-semibold text-gray-900">Address (optional)</h3>

            <div>
              <Label htmlFor="address_line1" className="text-sm font-medium text-gray-700 mb-2 block">
                Address Line 1
              </Label>
              <Input
                id="address_line1"
                value={formData.address.line1}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    address: { ...formData.address, line1: e.target.value },
                  })
                }
                placeholder="Street address"
              />
            </div>

            <div>
              <Label htmlFor="address_line2" className="text-sm font-medium text-gray-700 mb-2 block">
                Address Line 2
              </Label>
              <Input
                id="address_line2"
                value={formData.address.line2}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    address: { ...formData.address, line2: e.target.value },
                  })
                }
                placeholder="Apartment, suite, etc."
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="city" className="text-sm font-medium text-gray-700 mb-2 block">
                  City
                </Label>
                <Input
                  id="city"
                  value={formData.address.city}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      address: { ...formData.address, city: e.target.value },
                    })
                  }
                  placeholder="City"
                />
              </div>

              <div>
                <Label htmlFor="state" className="text-sm font-medium text-gray-700 mb-2 block">
                  State/Province
                </Label>
                <Input
                  id="state"
                  value={formData.address.state}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      address: { ...formData.address, state: e.target.value },
                    })
                  }
                  placeholder="State"
                />
              </div>
            </div>

            <div>
              <Label htmlFor="postal_code" className="text-sm font-medium text-gray-700 mb-2 block">
                Postal Code
              </Label>
              <Input
                id="postal_code"
                value={formData.address.postal_code}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    address: { ...formData.address, postal_code: e.target.value },
                  })
                }
                placeholder="Postal code"
              />
            </div>
          </div>

          <div className="flex justify-end gap-3 pt-4 border-t">
            <Button type="button" variant="outline" onClick={onClose} disabled={isLoading}>
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isLoading || !formData.country || !formData.tax_id || !formData.full_name}
              className="bg-gradient-to-r from-[#FF0077] to-[#E6006A] hover:from-[#E6006A] hover:to-[#FF0077] text-white"
            >
              {isLoading ? "Saving..." : "Save"}
            </Button>
          </div>
        </form>
      </motion.div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { FileText, Receipt, Plus, Edit, Download, HelpCircle } from "lucide-react";
import Breadcrumb from "../components/breadcrumb";
import BackButton from "../components/back-button";
import AuthGuard from "@/components/auth/auth-guard";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import TaxInfoModal from "./components/tax-info-modal";
import VatIdModal from "./components/vat-id-modal";

interface TaxInfo {
  country?: string;
  tax_id?: string;
  full_name?: string;
  address?: {
    line1?: string;
    line2?: string;
    city?: string;
    state?: string;
    postal_code?: string;
    country?: string;
  };
  updated_at?: string;
}

interface TaxDocument {
  year: number;
  document_url: string | null;
  issued_at: string | null;
  status: "issued" | "not_issued";
}

const TaxesPage = () => {
  const [activeTab, setActiveTab] = useState("taxpayers");
  const [isTaxInfoModalOpen, setTaxInfoModalOpen] = useState(false);
  const [isVatModalOpen, setVatModalOpen] = useState(false);
  const [taxInfo, setTaxInfo] = useState<TaxInfo | null>(null);
  const [vatId, setVatId] = useState<string | null>(null);
  const [taxDocuments, setTaxDocuments] = useState<TaxDocument[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadTaxData();
  }, []);

  const loadTaxData = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const [taxInfoResponse, documentsResponse] = await Promise.all([
        fetcher.get<{ data: { tax_info: TaxInfo | null; vat_id: string | null } }>("/api/me/tax-info", { cache: "no-store" }),
        fetcher.get<{ data: TaxDocument[] }>("/api/me/tax-documents", { cache: "no-store" }),
      ]);

      setTaxInfo(taxInfoResponse.data.tax_info);
      setVatId(taxInfoResponse.data.vat_id);
      setTaxDocuments(documentsResponse.data || []);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load tax information";
      setError(errorMessage);
      console.error("Error loading tax data:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleTaxInfoSave = async (data: any) => {
    try {
      await fetcher.post("/api/me/tax-info", data);
      toast.success("Tax information saved successfully");
      await loadTaxData();
      setTaxInfoModalOpen(false);
    } catch (err: any) {
      toast.error(err.message || "Failed to save tax information");
      throw err;
    }
  };

  const handleVatIdSave = async (vatId: string) => {
    try {
      await fetcher.patch("/api/me/tax-info/vat-id", { vat_id: vatId });
      toast.success("VAT ID saved successfully");
      await loadTaxData();
      setVatModalOpen(false);
    } catch (err: any) {
      toast.error(err.message || "Failed to save VAT ID");
      throw err;
    }
  };

  if (isLoading) {
    return (
      <AuthGuard>
        <div className="min-h-screen bg-zinc-50/50">
          <div className="w-full max-w-5xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
            <LoadingTimeout loadingMessage="Loading tax information..." />
          </div>
        </div>
      </AuthGuard>
    );
  }

  if (error) {
    return (
      <AuthGuard>
        <div className="min-h-screen bg-zinc-50/50">
          <div className="w-full max-w-5xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
            <EmptyState
              title="Unable to load tax information"
              description={error}
              action={{ label: "Try Again", onClick: () => loadTaxData() }}
            />
          </div>
        </div>
      </AuthGuard>
    );
  }

  return (
    <AuthGuard>
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-5xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
            className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 md:p-8 mt-8 mb-12"
          >
            <BackButton href="/account-settings" />
            <Breadcrumb
              items={[
                { label: "Account", href: "/account-settings" },
                { label: "Taxes" },
              ]}
            />

            <motion.h1
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.2, duration: 0.5, ease: "easeOut" }}
              className="text-2xl md:text-3xl font-semibold tracking-tighter text-gray-900 border-b border-gray-200 mb-6 pb-4 mt-4 md:mt-6"
            >
              Taxes
            </motion.h1>

            <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
              <TabsList className="mb-6 grid grid-cols-2 w-full h-auto p-1 bg-gray-100 rounded-xl shadow-inner border border-gray-200">
                <TabsTrigger
                  value="taxpayers"
                  className="text-sm md:text-base font-medium text-gray-700 data-[state=active]:bg-white data-[state=active]:text-[#FF0077] data-[state=active]:shadow-md data-[state=active]:border data-[state=active]:border-white/40 data-[state=active]:ring-1 data-[state=active]:ring-inset data-[state=active]:ring-gray-200 rounded-lg transition-all duration-200"
                >
                  Taxpayers
                </TabsTrigger>
                <TabsTrigger
                  value="taxDocuments"
                  className="text-sm md:text-base font-medium text-gray-700 data-[state=active]:bg-white data-[state=active]:text-[#FF0077] data-[state=active]:shadow-md data-[state=active]:border data-[state=active]:border-white/40 data-[state=active]:ring-1 data-[state=active]:ring-inset data-[state=active]:ring-gray-200 rounded-lg transition-all duration-200"
                >
                  Tax Documents
                </TabsTrigger>
              </TabsList>

              <TabsContent value="taxpayers">
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.3, duration: 0.5, ease: "easeOut" }}
                  className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-lg rounded-2xl p-6 md:p-8"
                >
                  <div className="space-y-8">
                    {/* Taxpayer Information */}
                    <div>
                      <h2 className="text-xl font-semibold tracking-tight text-gray-900 mb-2">
                        Taxpayer information
                      </h2>
                      <p className="text-sm md:text-base font-light text-gray-600 mb-6">
                        Tax info is required for most countries/regions.
                      </p>

                      {taxInfo ? (
                        <motion.div
                          initial={{ opacity: 0, scale: 0.95 }}
                          animate={{ opacity: 1, scale: 1 }}
                          className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-5 mb-4"
                        >
                          <div className="flex items-start justify-between">
                            <div className="flex-1 space-y-2">
                              {taxInfo.country && (
                                <div className="flex items-center gap-2">
                                  <div className="p-1.5 bg-pink-50 rounded-full border border-pink-100">
                                    <FileText className="w-4 h-4 text-[#FF0077]" />
                                  </div>
                                  <span className="text-sm md:text-base text-gray-700">
                                    <span className="font-medium">Country:</span> {taxInfo.country}
                                  </span>
                                </div>
                              )}
                              {taxInfo.tax_id && (
                                <div className="flex items-center gap-2">
                                  <div className="p-1.5 bg-pink-50 rounded-full border border-pink-100">
                                    <Receipt className="w-4 h-4 text-[#FF0077]" />
                                  </div>
                                  <span className="text-sm md:text-base text-gray-700">
                                    <span className="font-medium">Tax ID:</span> {taxInfo.tax_id}
                                  </span>
                                </div>
                              )}
                              {taxInfo.full_name && (
                                <div className="flex items-center gap-2">
                                  <div className="p-1.5 bg-pink-50 rounded-full border border-pink-100">
                                    <FileText className="w-4 h-4 text-[#FF0077]" />
