                            <p className="text-sm font-light text-gray-500">
                              {doc.status === "issued" && doc.document_url
                                ? `Issued on ${new Date(doc.issued_at!).toLocaleDateString()}`
                                : "No tax document issued"}
                            </p>
                          </div>
                          {doc.status === "issued" && doc.document_url && (
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => window.open(doc.document_url!, "_blank")}
                              className="text-[#FF0077] border-[#FF0077] hover:bg-pink-50"
                            >
                              <Download className="w-4 h-4 mr-2" />
                              Download
                            </Button>
                          )}
                        </div>
                      </motion.div>
                    ))}
                  </div>

                  <p className="text-sm font-light text-gray-600 mt-8">
                    For tax documents issued prior to {new Date().getFullYear() - 4}, contact us.
                  </p>

                  {/* Help Section */}
                  <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.5, duration: 0.5, ease: "easeOut" }}
                    className="mt-8 pt-6 border-t border-gray-200"
                  >
                    <div className="flex items-start gap-3">
                      <div className="p-2 bg-pink-50 rounded-full border border-pink-100">
                        <HelpCircle className="w-5 h-5 text-[#FF0077]" />
                      </div>
                      <div className="flex-1">
                        <h3 className="text-base font-semibold text-gray-900 mb-2">Need help?</h3>
                        <p className="text-sm font-light text-gray-600 mb-3">
                          Get answers to questions about taxes in our Help Center.
                        </p>
                        <a
                          href="/help-center"
                          className="text-sm font-medium text-[#FF0077] hover:text-[#D60565] underline transition-colors"
                        >
                          Visit Help Center
                        </a>
                      </div>
                    </div>
                  </motion.div>
                </motion.div>
              </TabsContent>
            </Tabs>
          </motion.div>
        </div>

        {/* Modals */}
        <TaxInfoModal
          isOpen={isTaxInfoModalOpen}
          onClose={() => setTaxInfoModalOpen(false)}
          onSave={handleTaxInfoSave}
          initialData={taxInfo}
        />
        <VatIdModal
          isOpen={isVatModalOpen}
          onClose={() => setVatModalOpen(false)}
          onSave={handleVatIdSave}
          initialData={vatId}
        />
      </div>
    </AuthGuard>
  );
};

export default TaxesPage;

"use client";

import { useEffect, useState } from "react";
import { fetcher } from "@/lib/http/fetcher";
import AuthGuard from "@/components/auth/auth-guard";
import BackButton from "@/components/ui/back-button";
import Breadcrumb from "@/components/ui/breadcrumb";
import BottomNav from "@/components/layout/bottom-nav";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { usePlatformCurrency } from "@/hooks/usePlatformCurrency";
import { motion } from "framer-motion";
import { Wallet, RefreshCw, ArrowUpRight, ArrowDownRight, Loader2 } from "lucide-react";
import EmptyState from "@/components/ui/empty-state";

type WalletData = {
  id: string;
  balance: number;
  currency: string;
};

type WalletTx = {
  id: string;
  type: "credit" | "debit";
  amount: number;
  description?: string | null;
  reference_type?: string | null;
  created_at: string;
};

export default function WalletPage() {
  const { format } = usePlatformCurrency();
  const [wallet, setWallet] = useState<WalletData | null>(null);
  const [transactions, setTransactions] = useState<WalletTx[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [topupAmount, setTopupAmount] = useState<string>("");
  const [isToppingUp, setIsToppingUp] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const load = async () => {
    try {
      setIsLoading(true);
      const res = await fetcher.get<{ data: { wallet: WalletData; transactions: WalletTx[] } }>("/api/me/wallet", { cache: "no-store" });
      setWallet(res.data.wallet);
      setTransactions(res.data.transactions || []);
    } catch (e) {
      toast.error("Failed to load wallet");
      console.error("Error loading wallet:", e);
    } finally {
      setIsLoading(false);
    }
  };

  const refresh = async () => {
    try {
      setIsRefreshing(true);
      const res = await fetcher.get<{ data: { wallet: WalletData; transactions: WalletTx[] } }>("/api/me/wallet", { cache: "no-store" });
      setWallet(res.data.wallet);
      setTransactions(res.data.transactions || []);
      toast.success("Wallet refreshed");
    } catch (e) {
      toast.error("Failed to refresh wallet");
      console.error("Error refreshing wallet:", e);
    } finally {
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const startTopup = async () => {
    const amount = Number(topupAmount);
    if (!amount || amount <= 0) {
      toast.error("Enter a valid amount");
      return;
    }
    if (amount < 1) {
      toast.error("Minimum top up amount is 1");
      return;
    }
    try {
      setIsToppingUp(true);
      const res = await fetcher.post<{ data: { payment_url?: string } }>("/api/me/wallet/topup", { amount });
      const url = (res as any)?.data?.payment_url;
      if (!url) {
        toast.error("Payment link was not returned");
        return;
      }
      window.location.href = url;
    } catch (e: any) {
      toast.error(e.message || "Failed to start top up");
      console.error("Error starting top up:", e);
    } finally {
      setIsToppingUp(false);
    }
  };

  return (
    <AuthGuard>
      <div className="min-h-screen bg-zinc-50/50 pb-20 md:pb-0">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-6 md:py-8">
          <Breadcrumb items={[{ label: "Home", href: "/" }, { label: "Account Settings", href: "/account-settings" }, { label: "Wallet" }]} />
          <BackButton href="/account-settings" />

          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3 }}
            className="mt-6"
          >
            <h1 className="text-3xl md:text-4xl font-semibold tracking-tighter text-gray-900 mb-8">Wallet</h1>

            {isLoading ? (
              <div className="flex items-center justify-center py-20">
                <Loader2 className="w-8 h-8 text-[#FF0077] animate-spin" />
              </div>
            ) : (
              <div className="space-y-6">
                {/* Available Balance Card */}
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.1 }}
                  className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 md:p-8"
                >
                  <div className="flex items-center gap-3 mb-4">
                    <div className="p-3 bg-gradient-to-br from-[#FF0077]/10 to-[#E6006A]/10 rounded-xl">
                      <Wallet className="w-6 h-6 text-[#FF0077]" />
                    </div>
                    <h2 className="text-lg font-semibold tracking-tighter text-gray-900">Available balance</h2>
                  </div>
                  <div className="text-4xl md:text-5xl font-bold text-gray-900 mt-2">
                    {wallet ? format(Number(wallet.balance || 0)) : "ΓÇö"}
                  </div>
                </motion.div>

                {/* Top Up Card */}
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.2 }}
                  className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 md:p-8"
                >
                  <h2 className="text-xl font-semibold tracking-tighter text-gray-900 mb-6">Top up</h2>
                  
                  <div className="space-y-4">
                    <div>
                      <Label htmlFor="amount" className="text-sm font-medium text-gray-700 mb-2 block">
                        Amount
                      </Label>
                      <Input
                        id="amount"
                        type="number"
                        min="1"
                        step="0.01"
                        value={topupAmount}
                        onChange={(e) => setTopupAmount(e.target.value)}
                        placeholder="Enter amount"
                        inputMode="decimal"
                        className="w-full backdrop-blur-sm bg-white/60 border-white/40 text-base"
                      />
                    </div>
                    
                    <motion.button
                      type="button"
                      onClick={startTopup}
                      disabled={isToppingUp || !topupAmount || Number(topupAmount) <= 0}
                      whileHover={{ scale: 1.02 }}
                      whileTap={{ scale: 0.98 }}
                      className="w-full bg-gradient-to-r from-[#FF0077] to-[#E6006A] hover:from-[#E6006A] hover:to-[#FF0077] text-white px-6 py-3 rounded-xl font-semibold transition-all shadow-lg hover:shadow-xl disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                    >
                      {isToppingUp ? (
                        <>
                          <Loader2 className="w-5 h-5 animate-spin" />
                          <span>Processing...</span>
                        </>
                      ) : (
                        <>
                          <ArrowUpRight className="w-5 h-5" />
                          <span>Top up</span>
                        </>
                      )}
                    </motion.button>
                    
                    <p className="text-xs text-gray-500 font-light mt-2">
                      You&apos;ll be redirected to Paystack to complete the top up.
                    </p>
                  </div>
                </motion.div>

                {/* Recent Activity Card */}
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.3 }}
                  className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 md:p-8"
                >
                  <div className="flex items-center justify-between mb-6">
                    <h2 className="text-xl font-semibold tracking-tighter text-gray-900">Recent activity</h2>
                    <motion.button
                      onClick={refresh}
                      disabled={isRefreshing}
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      className="p-2 hover:bg-white/40 rounded-lg transition-colors disabled:opacity-50"
                      aria-label="Refresh"
                    >
                      <RefreshCw className={`w-5 h-5 text-gray-600 ${isRefreshing ? "animate-spin" : ""}`} />
                    </motion.button>
                  </div>

                  {transactions.length === 0 ? (
                    <EmptyState
                      icon={Wallet}
                      title="No wallet transactions yet"
                      description="Your transaction history will appear here once you make a top up or use your wallet balance."
                    />
                  ) : (
                    <div className="space-y-3">
                      {transactions.map((t) => (
                        <motion.div
                          key={t.id}
                          initial={{ opacity: 0, x: -10 }}
                          animate={{ opacity: 1, x: 0 }}
                          className="flex items-center justify-between p-4 bg-white/40 backdrop-blur-sm rounded-xl border border-white/20 hover:bg-white/60 transition-colors"
                        >
                          <div className="flex items-center gap-4 flex-1">
                            <div className={`p-2 rounded-lg ${
                              t.type === "credit" 
                                ? "bg-green-100/50 text-green-700" 
                                : "bg-red-100/50 text-red-700"
                            }`}>
                              {t.type === "credit" ? (
                                <ArrowDownRight className="w-5 h-5" />
                              ) : (
                                <ArrowUpRight className="w-5 h-5" />
                              )}
                            </div>
                            <div className="flex-1 min-w-0">
                              <div className="text-sm font-medium text-gray-900 truncate">
                                {t.description || (t.type === "credit" ? "Credit" : "Debit")}
                              </div>
                              <div className="text-xs text-gray-500 mt-1">
                                {t.reference_type && `${t.reference_type} ΓÇó `}
                                {new Date(t.created_at).toLocaleDateString("en-US", {
                                  year: "numeric",
                                  month: "short",
                                  day: "numeric",
                                  hour: "2-digit",
                                  minute: "2-digit",
                                })}
                              </div>
                            </div>
                          </div>
                          <div className={`text-sm font-semibold ${
                            t.type === "credit" ? "text-green-700" : "text-red-700"
                          }`}>
                            {t.type === "credit" ? "+" : "-"}
                            {format(Number(t.amount || 0))}
                          </div>
                        </motion.div>
                      ))}
                    </div>
                  )}
                </motion.div>
              </div>
            )}
          </motion.div>
        </div>
        <BottomNav />
      </div>
    </AuthGuard>
  );
}

"use client";
import React, { useState, useEffect } from 'react'
import Breadcrumb from "../../components/breadcrumb";
import BackButton from "../../components/back-button";
import AuthGuard from "@/components/auth/auth-guard";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import ProviderCard from "@/app/home/components/provider-card";

export default function RecentlyViewedPage() {
  const [providers, setProviders] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadRecentlyViewed = async () => {
      try {
        setIsLoading(true);
        setError(null);
        const response = await fetcher.get<{ data: any[] }>("/api/me/recently-viewed", { cache: "no-store" });
        setProviders(response.data || []);
      } catch (err) {
        const errorMessage =
          err instanceof FetchTimeoutError
            ? "Request timed out. Please try again."
            : err instanceof FetchError
            ? err.message
            : "Failed to load recently viewed providers";
        setError(errorMessage);
        console.error("Error loading recently viewed:", err);
      } finally {
        setIsLoading(false);
      }
    };

    loadRecentlyViewed();
  }, []);

  if (isLoading) {
    return (
      <AuthGuard>
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-10 py-4 md:py-6">
          <LoadingTimeout loadingMessage="Loading recently viewed..." />
        </div>
      </AuthGuard>
    );
  }

  if (error) {
    return (
      <AuthGuard>
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-10 py-4 md:py-6">
          <EmptyState
            title="Unable to load recently viewed"
            description={error}
            action={{
              label: "Try Again",
              onClick: () => window.location.reload(),
            }}
          />
        </div>
      </AuthGuard>
    );
  }


  return (
    <AuthGuard>
      <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-10 py-4 md:py-6">
        <BackButton href="/account-settings/wishlists" />
        <Breadcrumb
          items={[
            { label: "Account", href: "/account-settings" },
            { label: "Wishlists", href: "/account-settings/wishlists" },
            { label: "Recently Viewed" }
          ]}
        />
        <h2 className='text-2xl md:text-3xl font-normal mb-4 md:mb-5 text-gray-900'>Recently Viewed</h2>

        {providers.length === 0 ? (
          <EmptyState
            title="No recently viewed providers"
            description="You haven't viewed any providers recently. Start browsing to see them here."
            action={{
              label: "Browse Providers",
              onClick: () => window.location.href = "/",
            }}
          />
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 justify-start gap-6 gap-y-10">
            {providers.map((provider, index) => (
              <ProviderCard key={provider.id || index} provider={provider} />
            ))}
          </div>
        )}
      </div>
    </AuthGuard>
  )
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { fetcher } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";
import { Plus, Edit, Trash2 } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface ServiceAddon {
  id: string;
  name: string;
  description?: string | null;
  type: "service" | "product" | "upgrade";
  category?: string | null;
  price: number;
  currency: string;
  duration_minutes?: number | null;
  is_active: boolean;
  is_recommended: boolean;
  image_url?: string | null;
  provider_id?: string | null;
  service_ids: string[];
  max_quantity?: number | null;
  requires_service: boolean;
  sort_order: number;
}

export default function AdminAddons() {
  const [addons, setAddons] = useState<ServiceAddon[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showDialog, setShowDialog] = useState(false);
  const [editingAddon, setEditingAddon] = useState<ServiceAddon | null>(null);
  const [services, setServices] = useState<Array<{ id: string; title: string }>>([]);
  const [filterType, setFilterType] = useState<string>("all");

  useEffect(() => {
    loadAddons();
    loadServices();
  }, [filterType]); // eslint-disable-line react-hooks/exhaustive-deps -- load when filterType changes

  const loadAddons = async () => {
    try {
      setIsLoading(true);
      const params = filterType !== "all" ? `?type=${filterType}` : "";
      const response = await fetcher.get<{ data: ServiceAddon[] }>(`/api/admin/addons${params}`);
      setAddons(response.data || []);
    } catch (error) {
      console.error("Error loading addons:", error);
      toast.error("Failed to load addons");
    } finally {
      setIsLoading(false);
    }
  };

  const loadServices = async () => {
    try {
      const response = await fetcher.get<{ data: Array<{ id: string; title: string }> }>(
        "/api/admin/catalog/services"
      );
      setServices(response.data || []);
    } catch (error) {
      console.error("Error loading services:", error);
    }
  };

  const handleCreate = () => {
    setEditingAddon(null);
    setShowDialog(true);
  };

  const handleEdit = (addon: ServiceAddon) => {
    setEditingAddon(addon);
    setShowDialog(true);
  };

  const handleDelete = async (addon: ServiceAddon) => {
    if (!confirm(`Are you sure you want to delete "${addon.name}"?`)) return;

    try {
      await fetcher.delete(`/api/admin/addons/${addon.id}`);
      toast.success("Addon deleted");
      loadAddons();
    } catch {
      toast.error("Failed to delete addon");
    }
  };

  const handleSave = async (addonData: any) => {
    try {
      if (editingAddon) {
        await fetcher.put(`/api/admin/addons/${editingAddon.id}`, addonData);
        toast.success("Addon updated");
      } else {
        await fetcher.post("/api/admin/addons", addonData);
        toast.success("Addon created");
      }
      setShowDialog(false);
      setEditingAddon(null);
      loadAddons();
    } catch (error: any) {
      toast.error(error.message || "Failed to save addon");
    }
  };

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading addons..." />;
  }

  const filteredAddons = filterType === "all" ? addons : addons.filter((a) => a.type === filterType);

  return (
    <RoleGuard allowedRoles={["superadmin", "provider_owner"]} redirectTo="/admin/dashboard">
      <div className="container mx-auto px-4 py-8 max-w-7xl">
        <div className="mb-6 flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-semibold mb-2">Service Addons</h1>
            <p className="text-gray-600">Manage service addons, products, and upgrades</p>
            <p className="text-sm text-amber-600 mt-2">
              Note: Addons are now managed by providers. This page is for provider use only.
            </p>
          </div>
          <Button onClick={handleCreate}>
            <Plus className="w-4 h-4 mr-2" />
            Add Addon
          </Button>
        </div>

        <div className="mb-4">
          <Select value={filterType} onValueChange={setFilterType}>
            <SelectTrigger className="w-48">
              <SelectValue placeholder="Filter by type" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Types</SelectItem>
              <SelectItem value="service">Services</SelectItem>
              <SelectItem value="product">Products</SelectItem>
              <SelectItem value="upgrade">Upgrades</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {filteredAddons.length === 0 ? (
          <EmptyState
            title="No addons"
            description="Create addons to offer additional services, products, or upgrades"
            action={{
              label: "Add Addon",
              onClick: handleCreate,
            }}
          />
        ) : (
          <div className="bg-white border rounded-lg overflow-hidden">
            <table className="w-full">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Name</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Type</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Price</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Duration</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {filteredAddons.map((addon) => (
                  <tr key={addon.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <span className="font-medium">{addon.name}</span>
                        {addon.is_recommended && (
                          <Badge variant="default" className="bg-pink-100 text-pink-800">
                            Recommended
                          </Badge>
                        )}
                        {addon.provider_id && (
                          <Badge variant="secondary">Provider</Badge>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <Badge variant={addon.type === "service" ? "default" : "secondary"}>
                        {addon.type}
                      </Badge>
                    </td>
                    <td className="px-6 py-4">
                      {addon.currency} {addon.price.toFixed(2)}
                    </td>
                    <td className="px-6 py-4">
                      {addon.duration_minutes ? `${addon.duration_minutes} mins` : "-"}
                    </td>
                    <td className="px-6 py-4">
                      <Badge className={addon.is_active ? "bg-green-100 text-green-800" : "bg-gray-100 text-gray-800"}>
                        {addon.is_active ? "Active" : "Inactive"}
                      </Badge>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex gap-2">
                        <Button variant="ghost" size="sm" onClick={() => handleEdit(addon)}>
                          <Edit className="w-4 h-4" />
                        </Button>
                        <Button variant="ghost" size="sm" onClick={() => handleDelete(addon)}>
                          <Trash2 className="w-4 h-4 text-red-600" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {showDialog && (
          <AddonDialog
            addon={editingAddon}
            services={services}
            onClose={() => {
              setShowDialog(false);
              setEditingAddon(null);
            }}
            onSave={handleSave}
          />
        )}
      </div>
    </RoleGuard>
  );
}

function AddonDialog({
  addon,
  services,
  onClose,
  onSave,
}: {
  addon: ServiceAddon | null;
  services: Array<{ id: string; title: string }>;
  onClose: () => void;
  onSave: (data: any) => void;
}) {
  const [formData, setFormData] = useState({
    name: addon?.name || "",
    description: addon?.description || "",
    type: (addon?.type || "service") as "service" | "product" | "upgrade",
    category: addon?.category || "",
    price: addon?.price || 0,
    currency: addon?.currency || "ZAR",
    duration_minutes: addon?.duration_minutes || null,
    is_active: addon?.is_active ?? true,
    is_recommended: addon?.is_recommended ?? false,
    image_url: addon?.image_url || "",
    service_ids: addon?.service_ids || [],
    max_quantity: addon?.max_quantity || null,
    requires_service: addon?.requires_service ?? false,
    sort_order: addon?.sort_order || 0,
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      duration_minutes: formData.duration_minutes || null,
      max_quantity: formData.max_quantity || null,
      price: parseFloat(formData.price.toString()),
      sort_order: parseInt(formData.sort_order.toString()),
    });
  };

  const toggleService = (serviceId: string) => {
    setFormData((prev) => ({
      ...prev,
      service_ids: prev.service_ids.includes(serviceId)
        ? prev.service_ids.filter((id) => id !== serviceId)
        : [...prev.service_ids, serviceId],
    }));
  };

  return (
    <Dialog open={true} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{addon ? "Edit Addon" : "Add Addon"}</DialogTitle>
          <DialogDescription>
            Create addons that customers can add to their bookings
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="name">Name *</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              required
            />
          </div>

          <div>
            <Label htmlFor="description">Description</Label>
            <textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              className="w-full p-2 border rounded-md min-h-[80px]"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="type">Type *</Label>
              <Select
                value={formData.type}
                onValueChange={(value) => setFormData({ ...formData, type: value as any })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="service">Service</SelectItem>
                  <SelectItem value="product">Product</SelectItem>
                  <SelectItem value="upgrade">Upgrade</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label htmlFor="category">Category</Label>
              <Input
                id="category"
                value={formData.category}
                onChange={(e) => setFormData({ ...formData, category: e.target.value })}
              />
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div>
              <Label htmlFor="price">Price *</Label>
              <Input
                id="price"
                type="number"
                min="0"
                step="0.01"
                value={formData.price}
                onChange={(e) => setFormData({ ...formData, price: parseFloat(e.target.value) || 0 })}
                required
              />
            </div>

            <div>
              <Label htmlFor="currency">Currency *</Label>
              <Input
                id="currency"
                value={formData.currency}
                onChange={(e) => setFormData({ ...formData, currency: e.target.value.toUpperCase() })}
                maxLength={3}
                required
              />
            </div>

            <div>
              <Label htmlFor="duration_minutes">Duration (mins)</Label>
              <Input
                id="duration_minutes"
                type="number"
                min="0"
                value={formData.duration_minutes || ""}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    duration_minutes: e.target.value ? parseInt(e.target.value) : null,
                  })
                }
              />
            </div>
          </div>

          <div>
            <Label htmlFor="image_url">Image URL</Label>
            <Input
              id="image_url"
              type="url"
              value={formData.image_url}
              onChange={(e) => setFormData({ ...formData, image_url: e.target.value })}
            />
          </div>

          <div>
            <Label>Associated Services</Label>
            <div className="mt-2 max-h-40 overflow-y-auto border rounded-md p-2">
              {services.length === 0 ? (
                <p className="text-sm text-gray-500">No services available</p>
              ) : (
                <div className="space-y-2">
                  {services.map((service) => (
                    <label key={service.id} className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={formData.service_ids.includes(service.id)}
                        onChange={() => toggleService(service.id)}
                      />
                      <span className="text-sm">{service.title}</span>
                    </label>
                  ))}
                </div>
              )}
            </div>
            <p className="text-xs text-gray-500 mt-1">
              Select services this addon can be added to. Leave empty to allow with any service.
            </p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="max_quantity">Max Quantity</Label>
              <Input
                id="max_quantity"
                type="number"
                min="1"
                value={formData.max_quantity || ""}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    max_quantity: e.target.value ? parseInt(e.target.value) : null,
                  })
                }
              />
            </div>

            <div>
              <Label htmlFor="sort_order">Sort Order</Label>
              <Input
                id="sort_order"
                type="number"
                value={formData.sort_order}
                onChange={(e) =>
                  setFormData({ ...formData, sort_order: parseInt(e.target.value) || 0 })
                }
              />
            </div>
          </div>

          <div className="flex items-center gap-6">
            <label className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={formData.is_active}
                onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
              />
              <span>Active</span>
            </label>
            <label className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={formData.is_recommended}
                onChange={(e) => setFormData({ ...formData, is_recommended: e.target.checked })}
              />
              <span>Recommended</span>
            </label>
            <label className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={formData.requires_service}
                onChange={(e) => setFormData({ ...formData, requires_service: e.target.checked })}
              />
              <span>Requires Service</span>
            </label>
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit">{addon ? "Update" : "Create"}</Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Users, Calendar, DollarSign, Download } from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { toast } from "sonner";
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from "recharts";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { format } from "date-fns";

const CURRENCY_CODE = "R";
const formatCurrency = (value: number) =>
  `${CURRENCY_CODE} ${(value ?? 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const formatGrowth = (growth: number | undefined | null) => {
  if (growth == null || (typeof growth === "number" && Number.isNaN(growth))) return "No growth data";
  if (growth > 0) return `+${growth}% growth`;
  if (growth < 0) return `${growth}% growth`;
  return "No change";
};

interface TimeSeriesData {
  date: string;
  count?: number;
  revenue?: number;
}

interface AnalyticsData {
  period: string;
  timeSeries: {
    users: TimeSeriesData[];
    providers: TimeSeriesData[];
    bookings: TimeSeriesData[];
    revenue: TimeSeriesData[];
  };
  breakdowns: {
    providerStatus: {
      active: number;
      pending: number;
      suspended: number;
      rejected: number;
    };
    bookingStatus: {
      confirmed: number;
      completed: number;
      cancelled: number;
      no_show: number;
    };
  };
  topProviders: Array<{
    provider_id: string;
    business_name: string;
    revenue: number;
  }>;
}

export default function AdminAnalytics() {
  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingAnalytics, setIsLoadingAnalytics] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [stats, setStats] = useState<any>(null);
  const [analyticsData, setAnalyticsData] = useState<AnalyticsData | null>(null);
  const [period, setPeriod] = useState("30d");

  useEffect(() => {
    loadAnalytics();
    loadDetailedAnalytics();
  }, [period]); // eslint-disable-line react-hooks/exhaustive-deps -- load when period changes

  const loadAnalytics = async () => {
    try {
      setIsLoading(true);
      setError(null);

      // Fetch dashboard stats which includes analytics data
      const response = await fetcher.get<{ data: any }>("/api/admin/dashboard");
      setStats(response.data);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load analytics";
      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const loadDetailedAnalytics = async () => {
    try {
      setIsLoadingAnalytics(true);
      const response = await fetcher.get<{ data: AnalyticsData }>(
        `/api/admin/analytics?period=${period}`
      );
      // Handle response format - fetcher may unwrap or return nested data
      const analyticsData = (response as any).data || response;
      setAnalyticsData(analyticsData);
    } catch (err) {
      console.error("Error loading detailed analytics:", err);
      toast.error("Failed to load detailed analytics");
    } finally {
      setIsLoadingAnalytics(false);
    }
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading analytics..." />
      </div>
    );
  }

  if (error || !stats) {
    return (
      <div className="container mx-auto px-4 py-8">
        <EmptyState
          title="Failed to load analytics"
          description={error || "Unable to load analytics data"}
          action={{
            label: "Retry",
            onClick: loadAnalytics,
          }}
        />
      </div>
    );
  }

  const COLORS = ["#0088FE", "#00C49F", "#FFBB28", "#FF8042", "#8884d8"];

  const formatDate = (dateStr: string) => {
    try {
      return format(new Date(dateStr), "MMM d");
    } catch {
      return dateStr;
    }
  };

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="space-y-6">
        <div className="flex items-center justify-between flex-wrap gap-4">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Analytics & Reports</h1>
            <p className="text-gray-600 mt-1">Platform analytics and business intelligence</p>
          </div>
          <div className="flex items-center gap-2">
            <Select value={period} onValueChange={setPeriod}>
              <SelectTrigger className="w-[140px]">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="7d">Last 7 days</SelectItem>
                <SelectItem value="30d">Last 30 days</SelectItem>
                <SelectItem value="90d">Last 90 days</SelectItem>
                <SelectItem value="1y">Last year</SelectItem>
              </SelectContent>
            </Select>
            <div className="flex gap-2">
              <Button
                onClick={async () => {
                  try {
                    const response = await fetch(`/api/admin/export/analytics?period=${period}`);
                    if (!response.ok) throw new Error("Export failed");
                    
                    const blob = await response.blob();
                    const url = window.URL.createObjectURL(blob);
                    const a = document.createElement("a");
                    a.href = url;
                    a.download = `analytics-export-${period}-${new Date().toISOString().split("T")[0]}.csv`;
                    document.body.appendChild(a);
                    a.click();
                    window.URL.revokeObjectURL(url);
                    document.body.removeChild(a);
                    toast.success("Export downloaded");
                  } catch {
                    toast.error("Failed to export analytics");
                  }
                }}
              >
                <Download className="w-4 h-4 mr-2" />
                Export CSV
              </Button>
            </div>
          </div>
        </div>

        {/* Key Metrics */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Users</CardTitle>
              <Users className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{stats.total_users ?? 0}</div>
              <p className="text-xs text-muted-foreground">
                {formatGrowth(stats.users_growth)}
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Providers</CardTitle>
              <Users className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{stats.total_providers ?? 0}</div>
              <p className="text-xs text-muted-foreground">
                {formatGrowth(stats.providers_growth)}
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Bookings</CardTitle>
              <Calendar className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{stats.total_bookings ?? 0}</div>
              <p className="text-xs text-muted-foreground">
                {formatGrowth(stats.bookings_growth)}
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Revenue</CardTitle>
              <DollarSign className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                {formatCurrency(stats.total_revenue ?? 0)}
              </div>
              <p className="text-xs text-muted-foreground">
                {formatGrowth(stats.revenue_growth)}
              </p>
            </CardContent>
          </Card>
        </div>

        {/* Revenue Breakdown */}
        <Card>
          <CardHeader>
            <CardTitle>Revenue Breakdown</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <div className="flex justify-between items-center">
                <span className="text-sm text-gray-600">GMV Total</span>
                <span className="font-semibold">{formatCurrency(stats.gmv_total ?? 0)}</span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-sm text-gray-600">Platform Net Total</span>
                <span className="font-semibold">
                  {formatCurrency(stats.platform_net_total ?? 0)}
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-sm text-gray-600">Platform Commission (Gross)</span>
                <span className="font-semibold">
                  {formatCurrency(stats.platform_commission_gross_total ?? 0)}
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-sm text-gray-600">Gateway Fees</span>
                <span className="font-semibold">
                  {formatCurrency(stats.gateway_fees_total ?? 0)}
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-sm text-gray-600">Refunds Total</span>
                <span className="font-semibold text-red-600">
                  {formatCurrency(stats.refunds_total ?? 0)}
                </span>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Additional Stats */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <Card>
            <CardHeader>
              <CardTitle>Today&apos;s Activity</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                <div className="flex justify-between">
                  <span className="text-sm text-gray-600">Active Bookings</span>
                  <span className="font-semibold">{stats.active_bookings_today ?? 0}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-gray-600">Revenue Today</span>
                  <span className="font-semibold">
                    {formatCurrency(stats.revenue_today ?? 0)}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-gray-600">Pending Approvals</span>
                  <span className="font-semibold">{stats.pending_approvals ?? 0}</span>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>This Month</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                <div className="flex justify-between">
                  <span className="text-sm text-gray-600">Revenue This Month</span>
                  <span className="font-semibold">
                    {formatCurrency(stats.revenue_this_month ?? 0)}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-gray-600">Subscription Net</span>
                  <span className="font-semibold">
                    {formatCurrency(stats.subscription_net_total ?? 0)}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-gray-600">Gift Card Sales</span>
                  <span className="font-semibold">
                    {formatCurrency(stats.gift_card_sales_total ?? 0)}
                  </span>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Time Series Charts */}
        {isLoadingAnalytics ? (
          <Card>
            <CardContent className="p-6">
              <LoadingTimeout loadingMessage="Loading charts..." />
            </CardContent>
          </Card>
        ) : analyticsData ? (
          <>
            {/* Revenue Time Series */}
            <Card>
              <CardHeader>
                <CardTitle>Revenue Over Time</CardTitle>
              </CardHeader>
              <CardContent>
                <ResponsiveContainer width="100%" height={300}>
                  <LineChart data={analyticsData.timeSeries?.revenue ?? []}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis
                      dataKey="date"
                      tickFormatter={formatDate}
                      angle={-45}
                      textAnchor="end"
                      height={80}
                    />
                    <YAxis tickFormatter={(value) => formatCurrency(Number(value))} />
                    <Tooltip
                      formatter={(value: number) => formatCurrency(Number(value))}
                      labelFormatter={formatDate}
                    />
                    <Legend />
                    <Line
                      type="monotone"
                      dataKey="revenue"
                      stroke="#0088FE"
                      strokeWidth={2}
                      name="Revenue"
                    />
                  </LineChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>

            {/* Growth Metrics */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Card>
                <CardHeader>
                  <CardTitle>User Growth</CardTitle>
                </CardHeader>
                <CardContent>
                  <ResponsiveContainer width="100%" height={250}>
                    <LineChart data={analyticsData.timeSeries?.users ?? []}>
                      <CartesianGrid strokeDasharray="3 3" />
                      <XAxis
                        dataKey="date"
                        tickFormatter={formatDate}
                        angle={-45}
                        textAnchor="end"
                        height={80}
                      />
                      <YAxis />
                      <Tooltip labelFormatter={formatDate} />
                      <Legend />
                      <Line
                        type="monotone"
                        dataKey="count"
                        stroke="#00C49F"
                        strokeWidth={2}
                        name="New Users"
                      />
                    </LineChart>
                  </ResponsiveContainer>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Provider Growth</CardTitle>
                </CardHeader>
                <CardContent>
                  <ResponsiveContainer width="100%" height={250}>
                    <LineChart data={analyticsData.timeSeries?.providers ?? []}>
                      <CartesianGrid strokeDasharray="3 3" />
                      <XAxis
                        dataKey="date"
                        tickFormatter={formatDate}
                        angle={-45}
                        textAnchor="end"
                        height={80}
                      />
                      <YAxis />
                      <Tooltip labelFormatter={formatDate} />
                      <Legend />
                      <Line
                        type="monotone"
                        dataKey="count"
                        stroke="#FFBB28"
                        strokeWidth={2}
                        name="New Providers"
                      />
                    </LineChart>
                  </ResponsiveContainer>
                </CardContent>
              </Card>
            </div>

            {/* Bookings Time Series */}
            <Card>
              <CardHeader>
                <CardTitle>Bookings Over Time</CardTitle>
              </CardHeader>
              <CardContent>
                <ResponsiveContainer width="100%" height={300}>
                  <BarChart data={analyticsData.timeSeries?.bookings ?? []}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis
                      dataKey="date"
                      tickFormatter={formatDate}
                      angle={-45}
                      textAnchor="end"
                      height={80}
                    />
                    <YAxis />
                    <Tooltip labelFormatter={formatDate} />
                    <Legend />
                    <Bar dataKey="count" fill="#8884d8" name="Bookings" />
                  </BarChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>

            {/* Breakdown Charts */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Card>
                <CardHeader>
                  <CardTitle>Provider Status Breakdown</CardTitle>
                </CardHeader>
                <CardContent>
                  <ResponsiveContainer width="100%" height={250}>
                    <PieChart>
                      <Pie
                        data={[
                          { name: "Active", value: analyticsData.breakdowns?.providerStatus?.active ?? 0 },
                          { name: "Pending", value: analyticsData.breakdowns?.providerStatus?.pending ?? 0 },
                          { name: "Suspended", value: analyticsData.breakdowns?.providerStatus?.suspended ?? 0 },
                          { name: "Rejected", value: analyticsData.breakdowns?.providerStatus?.rejected ?? 0 },
                        ]}
                        cx="50%"
                        cy="50%"
                        labelLine={false}
                        label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                        outerRadius={80}
                        fill="#8884d8"
                        dataKey="value"
                      >
                        {[
                          analyticsData.breakdowns?.providerStatus?.active ?? 0,
                          analyticsData.breakdowns?.providerStatus?.pending ?? 0,
                          analyticsData.breakdowns?.providerStatus?.suspended ?? 0,
                          analyticsData.breakdowns?.providerStatus?.rejected ?? 0,
                        ].map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                        ))}
                      </Pie>
                      <Tooltip />
                    </PieChart>
                  </ResponsiveContainer>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Booking Status Breakdown</CardTitle>
                </CardHeader>
                <CardContent>
                  <ResponsiveContainer width="100%" height={250}>
                    <PieChart>
                      <Pie
                        data={[
                          { name: "Completed", value: analyticsData.breakdowns?.bookingStatus?.completed ?? 0 },
                          { name: "Confirmed", value: analyticsData.breakdowns?.bookingStatus?.confirmed ?? 0 },
                          { name: "Cancelled", value: analyticsData.breakdowns?.bookingStatus?.cancelled ?? 0 },
                          { name: "No Show", value: analyticsData.breakdowns?.bookingStatus?.no_show ?? 0 },
                        ]}
                        cx="50%"
                        cy="50%"
                        labelLine={false}
                        label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                        outerRadius={80}
                        fill="#8884d8"
                        dataKey="value"
                      >
                        {[
                          analyticsData.breakdowns?.bookingStatus?.completed ?? 0,
                          analyticsData.breakdowns?.bookingStatus?.confirmed ?? 0,
                          analyticsData.breakdowns?.bookingStatus?.cancelled ?? 0,
                          analyticsData.breakdowns?.bookingStatus?.no_show ?? 0,
                        ].map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                        ))}
                      </Pie>
                      <Tooltip />
                    </PieChart>
                  </ResponsiveContainer>
                </CardContent>
              </Card>
            </div>

            {/* Top Providers */}
            {(analyticsData.topProviders?.length ?? 0) > 0 && (
              <Card>
                <CardHeader>
                  <CardTitle>Top Providers by Revenue</CardTitle>
                </CardHeader>
                <CardContent>
                  <ResponsiveContainer width="100%" height={300}>
                    <BarChart
                      data={analyticsData.topProviders ?? []}
                      layout="vertical"
                      margin={{ top: 5, right: 30, left: 100, bottom: 5 }}
                    >
                      <CartesianGrid strokeDasharray="3 3" />
                      <XAxis type="number" tickFormatter={(value) => formatCurrency(Number(value))} />
                      <YAxis
                        dataKey="business_name"
                        type="category"
                        width={90}
                        tick={{ fontSize: 12 }}
                      />
                      <Tooltip formatter={(value: number) => formatCurrency(Number(value))} />
                      <Legend />
                      <Bar dataKey="revenue" fill="#0088FE" name="Revenue" />
                    </BarChart>
                  </ResponsiveContainer>
                </CardContent>
              </Card>
            )}
          </>
        ) : null}
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect, useRef } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Search, Radio, Download } from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import { AdminFilterBar } from "@/components/admin/AdminFilterBar";
import { Badge } from "@/components/ui/badge";
import { getSupabaseClient } from "@/lib/supabase/client";
import { toast } from "sonner";

interface AuditLog {
  id: string;
  actor_user_id: string | null;
  actor_role: string | null;
  action: string;
  entity_type: string | null;
  entity_id: string | null;
  metadata: any;
  created_at: string;
  actor?: {
    id: string;
    full_name: string | null;
    email: string;
  };
}

export default function AdminAuditLogs() {
  const [logs, setLogs] = useState<AuditLog[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [actionFilter, setActionFilter] = useState("");
  const [entityTypeFilter, setEntityTypeFilter] = useState("");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [isRealtimeEnabled, setIsRealtimeEnabled] = useState(true);
  const channelRef = useRef<ReturnType<ReturnType<typeof getSupabaseClient>["channel"]> | null>(null);

  useEffect(() => {
    loadLogs();
  }, [page, actionFilter, entityTypeFilter, startDate, endDate]); // eslint-disable-line react-hooks/exhaustive-deps -- load when filters change

  // Polling fallback when realtime is disabled (10ΓÇô30s)
  const POLL_INTERVAL_MS = 30000;
  useEffect(() => {
    if (isRealtimeEnabled) return;
    const intervalId = setInterval(() => {
      loadLogs();
    }, POLL_INTERVAL_MS);
    return () => clearInterval(intervalId);
  }, [isRealtimeEnabled]); // eslint-disable-line react-hooks/exhaustive-deps -- loadLogs is stable

  // Real-time subscription for new audit logs (single subscription guarded by ref)
  useEffect(() => {
    if (!isRealtimeEnabled) return;

    const supabase = getSupabaseClient();
    if (!supabase) return;

    if (channelRef.current) {
      try {
        supabase.removeChannel(channelRef.current);
      } catch {
        // ignore
      }
      channelRef.current = null;
    }

    const channel = supabase
      .channel("audit-logs-realtime")
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "audit_logs",
        },
        async (payload: any) => {
          // Fetch actor details for the new log
          try {
            const { data: actor } = await supabase
              .from("users")
              .select("id, full_name, email")
              .eq("id", payload.new.actor_user_id)
              .single();

            const newLog: AuditLog = {
              ...payload.new,
              actor: actor ? {
                id: actor.id,
                full_name: actor.full_name,
                email: actor.email,
              } : undefined,
            };

            // Add new log to the beginning of the list
            setLogs((prev) => [newLog, ...prev.slice(0, 49)]); // Keep max 50 logs
            setTotal((prev) => prev + 1);
            toast.info("New audit log received", { duration: 2000 });
          } catch (error) {
            console.error("Error fetching actor for new log:", error);
            // Still add the log without actor details
            setLogs((prev) => [payload.new, ...prev.slice(0, 49)]);
            setTotal((prev) => prev + 1);
          }
        }
      )
      .subscribe();

    channelRef.current = channel;

    return () => {
      try {
        supabase.removeChannel(channel);
      } catch {
        // Ignore when channel is still connecting (e.g. React Strict Mode unmount)
      }
      if (channelRef.current === channel) {
        channelRef.current = null;
      }
    };
  }, [isRealtimeEnabled]);

  const loadLogs = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      if (searchQuery) params.set("search", searchQuery);
      if (actionFilter) params.set("action", actionFilter);
      if (entityTypeFilter) params.set("entity_type", entityTypeFilter);
      if (startDate) params.set("start_date", startDate);
      if (endDate) params.set("end_date", endDate);
      params.set("page", page.toString());
      params.set("limit", "50");

      const response = await fetcher.get<{
        data: AuditLog[];
        error: null;
        meta: { page: number; limit: number; total: number; has_more: boolean };
      }>(`/api/admin/audit-logs?${params.toString()}`);

      setLogs(response.data ?? []);
      setTotal(response.meta?.total ?? 0);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load audit logs";
      setError(errorMessage);
      console.error("Error loading audit logs:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    setPage(1);
    loadLogs();
  };

  if (isLoading && logs.length === 0) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading audit logs..." />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="container mx-auto px-4 py-8">
        <AdminPageHeader
          title="Audit Logs"
          description="Track all administrative actions"
          actions={
            <div className="flex items-center gap-2">
              {isRealtimeEnabled && (
                <Badge variant="outline" className="bg-green-50 text-green-700 border-green-200">
                  <Radio className="w-3 h-3 mr-1 animate-pulse" />
                  Live
                </Badge>
              )}
              <Button
                variant="outline"
                size="sm"
                onClick={() => setIsRealtimeEnabled(!isRealtimeEnabled)}
              >
                {isRealtimeEnabled ? "Disable" : "Enable"} Real-time
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={async () => {
                  try {
                    const params = new URLSearchParams();
                    if (actionFilter) params.set("action", actionFilter);
                    if (entityTypeFilter) params.set("entity_type", entityTypeFilter);
                    if (startDate) params.set("start_date", startDate);
                    if (endDate) params.set("end_date", endDate);
                    
                    const response = await fetch(`/api/admin/export/audit-logs?${params.toString()}`);
                    if (!response.ok) throw new Error("Export failed");
                    
                    const blob = await response.blob();
                    const url = window.URL.createObjectURL(blob);
                    const a = document.createElement("a");
                    a.href = url;
                    a.download = `audit-logs-export-${new Date().toISOString().split("T")[0]}.csv`;
                    document.body.appendChild(a);
                    a.click();
                    window.URL.revokeObjectURL(url);
                    document.body.removeChild(a);
                    toast.success("Export downloaded");
                  } catch {
                    toast.error("Failed to export audit logs");
                  }
                }}
              >
                <Download className="w-4 h-4 mr-2" />
                Export CSV
              </Button>
            </div>
          }
        />

        <AdminFilterBar className="mb-6">
          <div className="space-y-4">
          <form onSubmit={handleSearch} className="flex gap-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
              <Input
                placeholder="Search actions or entity types..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>
            <Button type="submit">Search</Button>
          </form>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
              <label className="text-sm font-medium mb-1 block">Action</label>
              <select
                value={actionFilter}
                onChange={(e) => {
                  setActionFilter(e.target.value);
                  setPage(1);
                }}
                className="w-full px-3 py-2 border rounded-md"
              >
                <option value="">All Actions</option>
                <option value="admin.refund">Admin Refund</option>
                <option value="admin.dispute.resolve">Dispute Resolve</option>
              </select>
            </div>
            <div>
              <label className="text-sm font-medium mb-1 block">Entity Type</label>
              <select
                value={entityTypeFilter}
                onChange={(e) => {
                  setEntityTypeFilter(e.target.value);
                  setPage(1);
                }}
                className="w-full px-3 py-2 border rounded-md"
              >
                <option value="">All Types</option>
                <option value="booking">Booking</option>
                <option value="payment_transaction">Payment Transaction</option>
              </select>
            </div>
            <div>
              <label className="text-sm font-medium mb-1 block">Start Date</label>
              <Input
                type="date"
                value={startDate}
                onChange={(e) => {
                  setStartDate(e.target.value);
                  setPage(1);
                }}
              />
            </div>
            <div>
              <label className="text-sm font-medium mb-1 block">End Date</label>
              <Input
                type="date"
                value={endDate}
                onChange={(e) => {
                  setEndDate(e.target.value);
                  setPage(1);
                }}
              />
            </div>
          </div>
        </div>
        </AdminFilterBar>

        {/* Logs Table */}
        {error ? (
          <EmptyState
            title="Failed to load audit logs"
            description={error}
            action={{ label: "Retry", onClick: loadLogs }}
          />
        ) : logs.length === 0 ? (
          <EmptyState title="No audit logs found" description="No logs match your filters" />
        ) : (
          <>
            <div className="bg-white border rounded-lg overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead className="bg-gray-50 border-b">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                        Timestamp
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                        Actor
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                        Action
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                        Entity
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                        Metadata
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200">
                    {logs.map((log) => (
                      <tr key={log.id} className="hover:bg-gray-50">
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {new Date(log.created_at).toLocaleString()}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="text-sm text-gray-900">
                            {log.actor?.full_name || log.actor?.email || log.actor_user_id || "Unknown"}
                          </div>
                          {log.actor_role && (
                            <div className="text-xs text-gray-500">{log.actor_role}</div>
                          )}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <Badge variant="outline" className="capitalize">
                            {log.action}
                          </Badge>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                          <div className="capitalize">{log.entity_type || "ΓÇö"}</div>
                          <div className="text-xs text-gray-500">{log.entity_id ? `${log.entity_id.slice(0, 8)}...` : "ΓÇö"}</div>
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-500">
                          <pre className="text-xs bg-gray-50 p-2 rounded max-w-md overflow-x-auto">
                            {JSON.stringify(log.metadata, null, 2)}
                          </pre>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Pagination */}
            {total > 50 && (
              <div className="mt-4 flex items-center justify-between">
                <div className="text-sm text-gray-700">
                  Showing {((page - 1) * 50) + 1} to {Math.min(page * 50, total)} of {total} logs
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    onClick={() => setPage((p) => Math.max(1, p - 1))}
                    disabled={page === 1}
                  >
                    Previous
                  </Button>
                  <Button
                    variant="outline"
                    onClick={() => setPage((p) => p + 1)}
                    disabled={total <= page * 50}
                  >
                    Next
                  </Button>
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { motion } from "framer-motion";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Calendar,
  MapPin,
  Edit,
  Save,
  X,
  ArrowLeft,
  XCircle,
  RotateCcw,
  Mail,
  Phone,
} from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import Link from "next/link";
import { format } from "date-fns";

interface BookingService {
  id: string;
  service_id: string;
  duration_minutes: number;
  price: number;
  services: {
    id: string;
    title: string;
    name: string;
  };
}

interface BookingProduct {
  id: string;
  product_id: string;
  quantity: number;
  unit_price: number;
  total_price: number;
  products: {
    id: string;
    name: string;
    retail_price: number;
  };
}

interface Booking {
  id: string;
  booking_number: string;
  customer_id: string;
  provider_id: string;
  status: string;
  scheduled_at: string;
  location_type: string;
  address_line1?: string;
  address_line2?: string;
  city?: string;
  country?: string;
  total_amount: number;
  currency: string;
  notes?: string;
  customer: {
    id: string;
    full_name: string;
    email: string;
    phone: string;
    avatar_url: string;
  };
  provider: {
    id: string;
    business_name: string;
    slug: string;
    email: string;
    phone: string;
  };
  location?: {
    id: string;
    name: string;
    address_line1: string;
    city: string;
    country: string;
  };
  booking_services?: BookingService[];
  booking_products?: BookingProduct[];
  payment_transaction?: any;
  created_at: string;
  updated_at: string;
}

export default function BookingDetailPage() {
  const params = useParams();
  const router = useRouter();
  const bookingId = params.id as string;
  
  const [booking, setBooking] = useState<Booking | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editData, setEditData] = useState<Partial<Booking>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [showCancelDialog, setShowCancelDialog] = useState(false);
  const [cancelReason, setCancelReason] = useState("");
  const [showRefundDialog, setShowRefundDialog] = useState(false);
  const [refundAmount, setRefundAmount] = useState(0);
  const [refundReason, setRefundReason] = useState("");

  useEffect(() => {
    if (bookingId) {
      loadBooking();
    }
  }, [bookingId]); // eslint-disable-line react-hooks/exhaustive-deps -- load when bookingId changes

  const loadBooking = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetcher.get<{ data: Booking }>(
        `/api/admin/bookings/${bookingId}`
      );
      setBooking(response.data);
      setEditData(response.data);
      if (response.data.total_amount) {
        setRefundAmount(response.data.total_amount);
      }
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load booking";
      setError(errorMessage);
      console.error("Error loading booking:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!booking) return;

    try {
      setIsSaving(true);

      await fetcher.patch(`/api/admin/bookings/${bookingId}`, editData);
      
      toast.success("Booking updated successfully");
      setIsEditing(false);
      loadBooking();
    } catch (error: any) {
      toast.error(error.message || "Failed to update booking");
    } finally {
      setIsSaving(false);
    }
  };

  const handleCancel = async () => {
    if (!booking) return;

    try {
      await fetcher.post(`/api/admin/bookings/${bookingId}/cancel`, {
        reason: cancelReason || undefined,
      });

      toast.success("Booking cancelled successfully");
      setShowCancelDialog(false);
      setCancelReason("");
      loadBooking();
    } catch (error: any) {
      toast.error(error.message || "Failed to cancel booking");
    }
  };

  const handleRefund = async () => {
    if (!booking) return;

    try {
      await fetcher.post(`/api/admin/bookings/${bookingId}/refund`, {
        amount: refundAmount,
        reason: refundReason || undefined,
      });

      toast.success("Refund processed successfully");
      setShowRefundDialog(false);
      setRefundReason("");
      loadBooking();
    } catch (error: any) {
      toast.error(error.message || "Failed to process refund");
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "confirmed":
      case "booked":
        return "bg-green-100 text-green-800";
      case "pending":
        return "bg-yellow-100 text-yellow-800";
      case "in_progress":
      case "started":
        return "bg-blue-100 text-blue-800";
      case "completed":
        return "bg-purple-100 text-purple-800";
      case "cancelled":
        return "bg-red-100 text-red-800";
      case "no_show":
        return "bg-orange-100 text-orange-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <LoadingTimeout loadingMessage="Loading booking details..." />
        </div>
      </div>
    );
  }

  if (error || !booking) {
    return (
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <EmptyState
            title="Failed to load booking"
            description={error || "Booking not found"}
            action={{
              label: "Back to Bookings",
              onClick: () => router.push("/admin/bookings"),
            }}
          />
        </div>
      </div>
    );
  }

  const subtotal = booking.booking_services?.reduce((sum, s) => sum + (s.price || 0), 0) || 0;
  const productTotal = booking.booking_products?.reduce((sum, p) => sum + (p.total_price || 0), 0) || 0;
  const total = subtotal + productTotal;

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          {/* Header */}
          <div className="mb-6">
            <Link href="/admin/bookings">
              <Button variant="ghost" className="mb-4">
                <ArrowLeft className="w-4 h-4 mr-2" />
                Back to Bookings
              </Button>
            </Link>

            <div className="flex items-start justify-between">
              <div>
                <div className="flex items-center gap-3 mb-2">
                  <h1 className="text-3xl font-semibold text-gray-900">
                    Booking #{booking.booking_number}
                  </h1>
                  <Badge className={getStatusColor(booking.status)}>
                    {booking.status}
                  </Badge>
                </div>
                <p className="text-gray-600">
                  {format(new Date(booking.scheduled_at), "PPP 'at' p")}
                </p>
              </div>

              <div className="flex gap-2">
                {!isEditing ? (
                  <>
                    <Button
                      variant="outline"
                      onClick={() => setIsEditing(true)}
                    >
                      <Edit className="w-4 h-4 mr-2" />
                      Edit
                    </Button>
                    {booking.status !== "cancelled" && booking.status !== "completed" && (
                      <>
                        <Button
                          variant="destructive"
                          onClick={() => setShowCancelDialog(true)}
                        >
                          <XCircle className="w-4 h-4 mr-2" />
                          Cancel
                        </Button>
                        {booking.payment_transaction && (
                          <Button
                            variant="outline"
                            onClick={() => setShowRefundDialog(true)}
                          >
                            <RotateCcw className="w-4 h-4 mr-2" />
                            Refund
                          </Button>
                        )}
                      </>
                    )}
                  </>
                ) : (
                  <>
                    <Button
                      variant="outline"
                      onClick={() => {
                        setIsEditing(false);
                        setEditData(booking);
                      }}
                    >
                      <X className="w-4 h-4 mr-2" />
                      Cancel
                    </Button>
                    <Button
                      onClick={handleSave}
                      disabled={isSaving}
                    >
                      <Save className="w-4 h-4 mr-2" />
                      {isSaving ? "Saving..." : "Save"}
                    </Button>
                  </>
                )}
              </div>
            </div>
          </div>

          {/* Main Content */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Main Info */}
            <div className="lg:col-span-2 space-y-6">
              {/* Booking Information */}
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-white border rounded-lg p-6"
              >
                <h2 className="text-xl font-semibold mb-4">Booking Information</h2>
                
                {isEditing ? (
                  <div className="space-y-4">
                    <div>
                      <Label htmlFor="status">Status</Label>
                      <Select
                        value={editData.status || booking.status}
                        onValueChange={(value) =>
                          setEditData({ ...editData, status: value })
                        }
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="pending">Pending</SelectItem>
                          <SelectItem value="confirmed">Confirmed</SelectItem>
                          <SelectItem value="in_progress">In Progress</SelectItem>
                          <SelectItem value="completed">Completed</SelectItem>
                          <SelectItem value="cancelled">Cancelled</SelectItem>
                          <SelectItem value="no_show">No Show</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                    <div>
                      <Label htmlFor="scheduled_at">Scheduled Date & Time</Label>
                      <Input
                        id="scheduled_at"
                        type="datetime-local"
                        value={editData.scheduled_at ? format(new Date(editData.scheduled_at), "yyyy-MM-dd'T'HH:mm") : ""}
                        onChange={(e) =>
                          setEditData({ ...editData, scheduled_at: new Date(e.target.value).toISOString() })
                        }
                      />
                    </div>
                    <div>
                      <Label htmlFor="location_type">Location Type</Label>
                      <Select
                        value={editData.location_type || booking.location_type}
                        onValueChange={(value) =>
                          setEditData({ ...editData, location_type: value })
                        }
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="at_salon">At Salon</SelectItem>
                          <SelectItem value="at_home">At Home</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                    {editData.location_type === "at_home" && (
                      <>
                        <div>
                          <Label htmlFor="address_line1">Address Line 1</Label>
                          <Input
                            id="address_line1"
                            value={editData.address_line1 || ""}
                            onChange={(e) =>
                              setEditData({ ...editData, address_line1: e.target.value })
                            }
                          />
                        </div>
                        <div>
                          <Label htmlFor="city">City</Label>
                          <Input
                            id="city"
                            value={editData.city || ""}
                            onChange={(e) =>
                              setEditData({ ...editData, city: e.target.value })
                            }
                          />
                        </div>
                      </>
                    )}
                    <div>
                      <Label htmlFor="notes">Notes</Label>
                      <Textarea
                        id="notes"
                        value={editData.notes || ""}
                        onChange={(e) =>
                          setEditData({ ...editData, notes: e.target.value })
                        }
                        rows={4}
                      />
                    </div>
                  </div>
                ) : (
                  <div className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Status</p>
                        <Badge className={getStatusColor(booking.status)}>
                          {booking.status}
                        </Badge>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Scheduled</p>
                        <div className="flex items-center gap-2">
                          <Calendar className="w-4 h-4 text-gray-400" />
                          <p>{format(new Date(booking.scheduled_at), "PPP 'at' p")}</p>
                        </div>
                      </div>
                    </div>
                    <div>
                      <p className="text-sm text-gray-500 mb-1">Location Type</p>
                      <p className="capitalize">{booking.location_type?.replace("_", " ")}</p>
                    </div>
                    {booking.location_type === "at_home" && (
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Address</p>
                        <div className="flex items-start gap-2">
                          <MapPin className="w-4 h-4 text-gray-400 mt-0.5" />
                          <div>
                            <p>{booking.address_line1}</p>
                            {booking.address_line2 && <p>{booking.address_line2}</p>}
                            <p>{booking.city}, {booking.country}</p>
                          </div>
                        </div>
                      </div>
                    )}
                    {booking.location && (
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Location</p>
                        <div className="flex items-start gap-2">
                          <MapPin className="w-4 h-4 text-gray-400 mt-0.5" />
                          <div>
                            <p className="font-medium">{booking.location.name}</p>
                            <p className="text-sm text-gray-600">
                              {booking.location.address_line1}, {booking.location.city}, {booking.location.country}
                            </p>
                          </div>
                        </div>
                      </div>
                    )}
                    {booking.notes && (
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Notes</p>
                        <p>{booking.notes}</p>
                      </div>
                    )}
                  </div>
                )}
              </motion.div>

              {/* Services & Products */}
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.1 }}
                className="bg-white border rounded-lg p-6"
              >
                <h2 className="text-xl font-semibold mb-4">Services & Products</h2>
                
                {booking.booking_services && booking.booking_services.length > 0 && (
                  <div className="mb-6">
                    <h3 className="font-medium mb-3">Services</h3>
                    <div className="space-y-2">
                      {booking.booking_services.map((service) => (
                        <div
                          key={service.id}
                          className="flex items-center justify-between p-3 border rounded-lg"
                        >
                          <div>
                            <p className="font-medium">
                              {service.services?.title || service.services?.name || "Service"}
                            </p>
                            <p className="text-sm text-gray-500">
                              {service.duration_minutes} minutes
                            </p>
                          </div>
                          <p className="font-semibold">
                            {booking.currency} {service.price?.toFixed(2)}
                          </p>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {booking.booking_products && booking.booking_products.length > 0 && (
                  <div>
                    <h3 className="font-medium mb-3">Products</h3>
                    <div className="space-y-2">
                      {booking.booking_products.map((product) => (
                        <div
                          key={product.id}
                          className="flex items-center justify-between p-3 border rounded-lg"
                        >
                          <div>
                            <p className="font-medium">
                              {product.products?.name || "Product"}
                            </p>
                            <p className="text-sm text-gray-500">
                              Qty: {product.quantity} ├ù {booking.currency} {product.unit_price?.toFixed(2)}
                            </p>
                          </div>
                          <p className="font-semibold">
                            {booking.currency} {product.total_price?.toFixed(2)}
                          </p>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {(!booking.booking_services || booking.booking_services.length === 0) &&
                 (!booking.booking_products || booking.booking_products.length === 0) && (
                  <p className="text-gray-600">No services or products</p>
                )}
              </motion.div>

              {/* Payment Information */}
              {booking.payment_transaction && (
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.2 }}
                  className="bg-white border rounded-lg p-6"
                >
                  <h2 className="text-xl font-semibold mb-4">Payment Information</h2>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <p className="text-gray-600">Status</p>
                      <Badge>
                        {booking.payment_transaction.status}
                      </Badge>
                    </div>
                    <div className="flex justify-between">
                      <p className="text-gray-600">Amount</p>
                      <p className="font-semibold">
                        {booking.currency} {booking.payment_transaction.amount?.toFixed(2)}
                      </p>
                    </div>
                    <div className="flex justify-between">
                      <p className="text-gray-600">Transaction ID</p>
                      <p className="font-mono text-sm">
                        {booking.payment_transaction.transaction_id || "N/A"}
                      </p>
                    </div>
                  </div>
                </motion.div>
              )}
            </div>

            {/* Sidebar */}
            <div className="space-y-6">
              {/* Customer Info */}
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-white border rounded-lg p-6"
              >
                <h2 className="text-xl font-semibold mb-4">Customer</h2>
                <div className="space-y-3">
                  <div>
                    <p className="font-medium">{booking.customer?.full_name || "N/A"}</p>
                  </div>
                  <div className="space-y-2">
                    <div className="flex items-center gap-2 text-sm">
                      <Mail className="w-4 h-4 text-gray-400" />
                      <p>{booking.customer?.email || "N/A"}</p>
                    </div>
                    <div className="flex items-center gap-2 text-sm">
                      <Phone className="w-4 h-4 text-gray-400" />
                      <p>{booking.customer?.phone || "N/A"}</p>
                    </div>
                  </div>
                  <Link href={`/admin/users/${booking.customer_id}`}>
                    <Button variant="outline" size="sm" className="w-full">
                      View Customer Profile
                    </Button>
                  </Link>
                </div>
              </motion.div>

              {/* Provider Info */}
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.1 }}
                className="bg-white border rounded-lg p-6"
              >
                <h2 className="text-xl font-semibold mb-4">Provider</h2>
                <div className="space-y-3">
                  <div>
                    <p className="font-medium">{booking.provider?.business_name || "N/A"}</p>
                  </div>
                  <div className="space-y-2">
                    <div className="flex items-center gap-2 text-sm">
                      <Mail className="w-4 h-4 text-gray-400" />
                      <p>{booking.provider?.email || "N/A"}</p>
                    </div>
                    <div className="flex items-center gap-2 text-sm">
                      <Phone className="w-4 h-4 text-gray-400" />
                      <p>{booking.provider?.phone || "N/A"}</p>
                    </div>
                  </div>
                  <Link href={`/admin/providers/${booking.provider_id}`}>
                    <Button variant="outline" size="sm" className="w-full">
                      View Provider Profile
                    </Button>
                  </Link>
                </div>
              </motion.div>

              {/* Pricing Summary */}
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
                className="bg-white border rounded-lg p-6"
              >
                <h2 className="text-xl font-semibold mb-4">Pricing Summary</h2>
                <div className="space-y-2">
                  <div className="flex justify-between">
                    <p className="text-gray-600">Subtotal</p>
                    <p>{booking.currency} {subtotal.toFixed(2)}</p>
                  </div>
                  {productTotal > 0 && (
                    <div className="flex justify-between">
                      <p className="text-gray-600">Products</p>
                      <p>{booking.currency} {productTotal.toFixed(2)}</p>
                    </div>
                  )}
                  <div className="border-t pt-2 mt-2">
                    <div className="flex justify-between">
                      <p className="font-semibold">Total</p>
                      <p className="font-semibold text-lg">
                        {booking.currency} {booking.total_amount?.toFixed(2) || total.toFixed(2)}
                      </p>
                    </div>
                  </div>
                </div>
              </motion.div>
            </div>
          </div>
        </div>

        {/* Cancel Dialog */}
        <Dialog open={showCancelDialog} onOpenChange={setShowCancelDialog}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Cancel Booking</DialogTitle>
              <DialogDescription>
                Are you sure you want to cancel this booking? This action cannot be undone.
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4">
              <div>
                <Label htmlFor="cancel_reason">Reason (optional)</Label>
                <Textarea
                  id="cancel_reason"
                  value={cancelReason}
                  onChange={(e) => setCancelReason(e.target.value)}
                  placeholder="Enter reason for cancellation..."
                  rows={3}
                />
              </div>
              <div className="flex justify-end gap-2">
                <Button
                  variant="outline"
                  onClick={() => {
                    setShowCancelDialog(false);
                    setCancelReason("");
                  }}
                >
                  Cancel
                </Button>
                <Button variant="destructive" onClick={handleCancel}>
                  Confirm Cancellation
                </Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>

        {/* Refund Dialog */}
        <Dialog open={showRefundDialog} onOpenChange={setShowRefundDialog}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Process Refund</DialogTitle>
              <DialogDescription>
                Process a refund for this booking.
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4">
              <div>
                <Label htmlFor="refund_amount">Refund Amount</Label>
                <Input
                  id="refund_amount"
                  type="number"
                  value={refundAmount}
                  onChange={(e) => setRefundAmount(parseFloat(e.target.value) || 0)}
                  min={0}
                  max={booking.total_amount}
                />
                <p className="text-sm text-gray-500 mt-1">
                  Maximum: {booking.currency} {booking.total_amount?.toFixed(2)}
                </p>
              </div>
              <div>
                <Label htmlFor="refund_reason">Reason (optional)</Label>
                <Textarea
                  id="refund_reason"
                  value={refundReason}
                  onChange={(e) => setRefundReason(e.target.value)}
                  placeholder="Enter reason for refund..."
                  rows={3}
                />
              </div>
              <div className="flex justify-end gap-2">
                <Button
                  variant="outline"
                  onClick={() => {
                    setShowRefundDialog(false);
                    setRefundReason("");
                  }}
                >
                  Cancel
                </Button>
                <Button onClick={handleRefund}>
                  Process Refund
                </Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Search,
  Filter,
  Calendar,
  User,
  Building2,
  DollarSign,
  Eye,
  Download,
  CheckCircle2,
  XCircle,
} from "lucide-react";
import BulkActionsBar from "@/components/admin/BulkActionsBar";
import { Checkbox } from "@/components/ui/checkbox";
import { toast } from "sonner";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import type { Booking } from "@/types/beautonomi";
import Link from "next/link";

export default function AdminBookings() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [dateFilter, setDateFilter] = useState<string>("");
  const [showFilters, setShowFilters] = useState(false);
  const [selectedBookingIds, setSelectedBookingIds] = useState<Set<string>>(new Set());
  const [isSelectAll, setIsSelectAll] = useState(false);

  useEffect(() => {
    loadBookings();
  }, [statusFilter, dateFilter]); // eslint-disable-line react-hooks/exhaustive-deps -- load when filters change

  const loadBookings = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      if (statusFilter !== "all") params.set("status", statusFilter);
      if (dateFilter) params.set("date", dateFilter);
      const response = await fetcher.get<{ data?: Booking[] }>(
        `/api/admin/bookings?${params.toString()}`
      );
      setBookings(response.data ?? []);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load bookings";
      setError(errorMessage);
      console.error("Error loading bookings:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSelectBooking = (bookingId: string, checked: boolean) => {
    const newSelected = new Set(selectedBookingIds);
    if (checked) {
      newSelected.add(bookingId);
    } else {
      newSelected.delete(bookingId);
    }
    setSelectedBookingIds(newSelected);
    setIsSelectAll(newSelected.size === filteredBookings.length && filteredBookings.length > 0);
  };

  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      const allIds = new Set(filteredBookings.map((b) => b.id));
      setSelectedBookingIds(allIds);
      setIsSelectAll(true);
    } else {
      setSelectedBookingIds(new Set());
      setIsSelectAll(false);
    }
  };

  const handleBulkAction = async (action: string) => {
    if (selectedBookingIds.size === 0) {
      toast.error("Please select at least one booking");
      return;
    }

    const bookingIds = Array.from(selectedBookingIds);

    try {
      if (!confirm(`Perform ${action} on ${bookingIds.length} booking(s)?`)) return;

      await fetcher.post("/api/admin/bookings/bulk", {
        booking_ids: bookingIds,
        action: action === "cancel" ? "cancel" : action === "complete" ? "complete" : "export",
      });

      toast.success(`${bookingIds.length} booking(s) updated`);
      setSelectedBookingIds(new Set());
      setIsSelectAll(false);
      loadBookings();
    } catch (error: any) {
      toast.error(error.message || `Failed to perform bulk ${action}`);
    }
  };

  const filteredBookings = bookings.filter((booking) => {
    const matchesSearch =
      (booking.booking_number ?? "").toLowerCase().includes(searchQuery.toLowerCase());
    return matchesSearch;
  });

  const groupedBookings = {
    all: filteredBookings,
    pending: filteredBookings.filter((b) => b.status === "pending"),
    confirmed: filteredBookings.filter((b) => b.status === "confirmed"),
    in_progress: filteredBookings.filter((b) => b.status === "in_progress"),
    completed: filteredBookings.filter((b) => b.status === "completed"),
    cancelled: filteredBookings.filter((b) => b.status === "cancelled"),
    no_show: filteredBookings.filter((b) => b.status === "no_show"),
  };

  const stats = {
    total: bookings.length,
    pending: groupedBookings.pending.length,
    confirmed: groupedBookings.confirmed.length,
    in_progress: groupedBookings.in_progress.length,
    completed: groupedBookings.completed.length,
    cancelled: groupedBookings.cancelled.length,
    no_show: groupedBookings.no_show.length,
    total_revenue: bookings
      .filter((b) => b.status === "completed")
      .reduce((sum, b) => sum + (b.total_amount || 0), 0),
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <LoadingTimeout loadingMessage="Loading bookings..." />
        </div>
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
            className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 md:p-8 mb-8"
          >
            {/* Header */}
            <div className="mb-6">
              <motion.h1
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.2, duration: 0.5, ease: "easeOut" }}
                className="text-2xl md:text-3xl font-semibold tracking-tighter mb-2 text-gray-900"
              >
                Bookings Oversight
              </motion.h1>
              <p className="text-sm md:text-base font-light text-gray-600">Monitor all platform bookings</p>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-4 mb-6">
              <motion.div
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 shadow-lg"
              >
                <p className="text-sm font-light text-gray-600 mb-1">Total</p>
                <p className="text-2xl font-semibold tracking-tight text-gray-900">{stats.total}</p>
              </motion.div>
              <motion.div
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 shadow-lg"
              >
                <p className="text-sm font-light text-gray-600 mb-1">Pending</p>
                <p className="text-2xl font-semibold tracking-tight text-yellow-600">{stats.pending}</p>
              </motion.div>
              <motion.div
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 shadow-lg"
              >
                <p className="text-sm font-light text-gray-600 mb-1">Confirmed</p>
                <p className="text-2xl font-semibold tracking-tight text-blue-600">{stats.confirmed}</p>
              </motion.div>
              <motion.div
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 shadow-lg"
              >
                <p className="text-sm font-light text-gray-600 mb-1">In Progress</p>
                <p className="text-2xl font-semibold tracking-tight text-purple-600">{stats.in_progress}</p>
              </motion.div>
              <motion.div
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 shadow-lg"
              >
                <p className="text-sm font-light text-gray-600 mb-1">Completed</p>
                <p className="text-2xl font-semibold tracking-tight text-green-600">{stats.completed}</p>
              </motion.div>
              <motion.div
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 shadow-lg"
              >
                <p className="text-sm font-light text-gray-600 mb-1">Cancelled</p>
                <p className="text-2xl font-semibold tracking-tight text-red-600">{stats.cancelled}</p>
              </motion.div>
              <motion.div
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 shadow-lg"
              >
                <p className="text-sm font-light text-gray-600 mb-1">Revenue</p>
                <p className="text-2xl font-semibold tracking-tight text-gray-900">R {stats.total_revenue.toLocaleString()}</p>
              </motion.div>
            </div>

            {/* Search and Filters */}
            <div className="mb-6 space-y-4">
              <div className="flex gap-4">
                <div className="relative flex-1">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                  <Input
                    placeholder="Search by customer, provider, or booking number..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="pl-10 backdrop-blur-xl bg-white/80 border border-white/40 focus:border-[#FF0077] focus:ring-[#FF0077] rounded-xl"
                  />
                </div>
                <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
                  <Button
                    variant="outline"
                    onClick={() => setShowFilters(!showFilters)}
                    className="border-white/40 backdrop-blur-xl bg-white/80 hover:bg-white/90 rounded-xl"
                  >
                    <Filter className="w-4 h-4 mr-2" />
                    Filters
                  </Button>
                </motion.div>
                <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
                  <Button
                    variant="outline"
                    onClick={async () => {
                try {
                  const params = new URLSearchParams();
                  if (statusFilter !== "all") params.set("status", statusFilter);
                  if (dateFilter) params.set("start_date", dateFilter);

                  const response = await fetch(`/api/admin/export/bookings?${params.toString()}`);
                  if (!response.ok) throw new Error("Export failed");

                  const blob = await response.blob();
                  const url = window.URL.createObjectURL(blob);
                  const a = document.createElement("a");
                  a.href = url;
                  a.download = `bookings-export-${new Date().toISOString().split("T")[0]}.csv`;
                  document.body.appendChild(a);
                  a.click();
                  window.URL.revokeObjectURL(url);
                  document.body.removeChild(a);
                  toast.success("Export downloaded");
                } catch {
                  toast.error("Failed to export bookings");
                }
              }}
            >
                      <Download className="w-4 h-4 mr-2" />
                      Export CSV
                    </Button>
                  </motion.div>
                </div>

                {showFilters && (
                  <motion.div
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: "auto" }}
                    exit={{ opacity: 0, height: 0 }}
                    className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 space-y-4"
                  >
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="text-sm font-medium mb-2 block">Status</label>
                  <select
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value)}
                    className="w-full p-2 border rounded-md"
                  >
                    <option value="all">All Statuses</option>
                    <option value="pending">Pending</option>
                    <option value="confirmed">Confirmed</option>
                    <option value="in_progress">In Progress</option>
                    <option value="completed">Completed</option>
                    <option value="cancelled">Cancelled</option>
                    <option value="no_show">No Show</option>
                  </select>
                </div>
                <div>
                  <label className="text-sm font-medium mb-2 block">Date</label>
                  <Input
                    type="date"
                    value={dateFilter}
                    onChange={(e) => setDateFilter(e.target.value)}
                  />
                </div>
              </div>
            </motion.div>
          )}
        </div>

        {/* Bulk Actions Bar */}
        <BulkActionsBar
          selectedCount={selectedBookingIds.size}
          onClearSelection={() => {
            setSelectedBookingIds(new Set());
            setIsSelectAll(false);
          }}
          onBulkAction={handleBulkAction}
          actions={[
            { id: "complete", label: "Mark Complete", icon: CheckCircle2, variant: "default" as const },
            { id: "cancel", label: "Cancel", icon: XCircle, variant: "destructive" as const },
            { id: "export", label: "Export", icon: Download, variant: "outline" as const },
          ]}
        />

        {/* Bookings Tabs */}
        {error ? (
          <EmptyState
            title="Failed to load bookings"
            description={error}
            action={{
              label: "Retry",
              onClick: loadBookings,
            }}
          />
        ) : (
            <Tabs defaultValue="all" className="w-full">
              <TabsList className="mb-6 backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-1 shadow-lg">
                <TabsTrigger value="all" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">All ({groupedBookings.all.length})</TabsTrigger>
                <TabsTrigger value="pending" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">
                  Pending ({groupedBookings.pending.length})
                </TabsTrigger>
                <TabsTrigger value="confirmed" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">
                Confirmed ({groupedBookings.confirmed.length})
              </TabsTrigger>
                <TabsTrigger value="in_progress" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">
                  In Progress ({groupedBookings.in_progress.length})
                </TabsTrigger>
                <TabsTrigger value="completed" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">
                  Completed ({groupedBookings.completed.length})
                </TabsTrigger>
                <TabsTrigger value="cancelled" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">
                  Cancelled ({groupedBookings.cancelled.length})
                </TabsTrigger>
                <TabsTrigger value="no_show" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">
                  No Show ({groupedBookings.no_show.length})
                </TabsTrigger>
              </TabsList>

            <TabsContent value="all">
              <BookingsList
                bookings={groupedBookings.all}
                selectedIds={selectedBookingIds}
                onSelect={handleSelectBooking}
                isSelectAll={isSelectAll}
                onSelectAll={handleSelectAll}
              />
            </TabsContent>
            <TabsContent value="pending">
              <BookingsList
                bookings={groupedBookings.pending}
                selectedIds={selectedBookingIds}
                onSelect={handleSelectBooking}
                isSelectAll={isSelectAll}
                onSelectAll={handleSelectAll}
              />
            </TabsContent>
            <TabsContent value="confirmed">
              <BookingsList
                bookings={groupedBookings.confirmed}
                selectedIds={selectedBookingIds}
                onSelect={handleSelectBooking}
                isSelectAll={isSelectAll}
                onSelectAll={handleSelectAll}
              />
            </TabsContent>
            <TabsContent value="in_progress">
              <BookingsList
                bookings={groupedBookings.in_progress}
                selectedIds={selectedBookingIds}
                onSelect={handleSelectBooking}
                isSelectAll={isSelectAll}
                onSelectAll={handleSelectAll}
              />
            </TabsContent>
            <TabsContent value="completed">
              <BookingsList
                bookings={groupedBookings.completed}
                selectedIds={selectedBookingIds}
                onSelect={handleSelectBooking}
                isSelectAll={isSelectAll}
                onSelectAll={handleSelectAll}
              />
            </TabsContent>
            <TabsContent value="cancelled">
              <BookingsList
                bookings={groupedBookings.cancelled}
                selectedIds={selectedBookingIds}
                onSelect={handleSelectBooking}
                isSelectAll={isSelectAll}
                onSelectAll={handleSelectAll}
              />
            </TabsContent>
            <TabsContent value="no_show">
              <BookingsList
                bookings={groupedBookings.no_show}
                selectedIds={selectedBookingIds}
                onSelect={handleSelectBooking}
                isSelectAll={isSelectAll}
                onSelectAll={handleSelectAll}
              />
            </TabsContent>
            </Tabs>
          )}
          </motion.div>
        </div>
      </div>
    </RoleGuard>
  );
}


function BookingsList({
  bookings,
  selectedIds,
  onSelect,
  isSelectAll: _isSelectAll,
  onSelectAll: _onSelectAll,
}: {
  bookings: Booking[];
  selectedIds: Set<string>;
  onSelect: (id: string, checked: boolean) => void;
  isSelectAll: boolean;
  onSelectAll: (checked: boolean) => void;
}) {

  if (bookings.length === 0) {
    return (
      <EmptyState
        title="No bookings found"
        description="No bookings match these criteria"
      />
    );
  }

  return (
    <div className="space-y-4">
      {bookings.map((booking) => (
        <BookingCard
          key={booking.id}
          booking={booking}
          selected={selectedIds.has(booking.id)}
          onSelect={(checked) => onSelect(booking.id, checked)}
        />
      ))}
    </div>
  );
}

function BookingCard({
  booking,
  selected,
  onSelect,
}: {
  booking: Booking;
  selected: boolean;
  onSelect: (checked: boolean) => void;
}) {
  const getStatusColor = () => {
    switch (booking.status) {
      case "confirmed":
        return "bg-green-100 text-green-800";
      case "pending":
        return "bg-yellow-100 text-yellow-800";
      case "in_progress":
        return "bg-purple-100 text-purple-800";
      case "cancelled":
        return "bg-red-100 text-red-800";
      case "completed":
        return "bg-blue-100 text-blue-800";
      case "no_show":
        return "bg-orange-100 text-orange-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      whileHover={{ scale: 1.01 }}
      whileTap={{ scale: 0.99 }}
      className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-6 shadow-lg hover:shadow-xl transition-all"
    >
      <div className="flex items-start gap-3">
        <div className="pt-1" onClick={(e) => e.stopPropagation()}>
          <Checkbox checked={selected} onCheckedChange={onSelect} />
        </div>
        <div className="flex-1">
          <div className="flex flex-col md:flex-row md:items-start md:justify-between gap-4">
            <div className="flex-1">
          <div className="flex items-center gap-3 mb-3 flex-wrap">
            <span className={`px-3 py-1 rounded-full text-xs font-semibold ${getStatusColor()}`}>
              {booking.status}
            </span>
            <h3 className="text-lg font-semibold tracking-tight text-gray-900">
              Booking #{booking.booking_number}
            </h3>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm text-gray-600 mb-4">
            <div className="flex items-center gap-2">
              <User className="w-4 h-4" />
              <span>
                <span className="font-medium">Customer ID:</span> {booking.customer_id}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <Building2 className="w-4 h-4" />
              <span>
                <span className="font-medium">Provider ID:</span> {booking.provider_id}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <Calendar className="w-4 h-4" />
              <span>
                {new Date(booking.scheduled_at).toLocaleDateString("en-US", {
                  weekday: "long",
                  year: "numeric",
                  month: "long",
                  day: "numeric",
                })}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <DollarSign className="w-4 h-4" />
              <span>
                {booking.currency} {booking.total_amount?.toFixed(2)}
              </span>
            </div>
          </div>

          <div className="flex flex-wrap gap-2">
            {booking.services?.slice(0, 3).map((service, index) => (
              <span
                key={index}
                className="px-2 py-1 backdrop-blur-sm bg-pink-50/80 border border-pink-100 rounded-lg text-xs font-medium text-[#FF0077]"
              >
                {service.offering_name || "Service"}
              </span>
            ))}
            {booking.services && booking.services.length > 3 && (
              <span className="px-2 py-1 backdrop-blur-sm bg-pink-50/80 border border-pink-100 rounded-lg text-xs font-medium text-[#FF0077]">
                +{booking.services.length - 3} more
              </span>
            )}
          </div>
            </div>

            <div>
              <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
                <Link href={`/admin/bookings/${booking.id}`}>
                  <Button variant="outline" className="border-white/40 backdrop-blur-sm bg-white/60 hover:bg-white/80">
                    <Eye className="w-4 h-4 mr-2" />
                    View Details
                  </Button>
                </Link>
              </motion.div>
            </div>
          </div>
        </div>
      </div>
    </motion.div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Mail,
  MessageSquare,
  Bell,
  Send,
  History,
  Users,
  Building2,
  UserPlus,
} from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import { FetchError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { format } from "date-fns";

const RECIPIENT_OPTIONS = [
  { value: "all_users", label: "All Customers", icon: Users },
  { value: "all_providers", label: "All Providers", icon: Building2 },
  { value: "custom", label: "Specific recipients", icon: UserPlus },
] as const;

function parseUserIds(input: string): string[] {
  return input
    .split(/[\n,]+/)
    .map((s) => s.trim())
    .filter(Boolean);
}

function formatFetchError(e: any, fallback: string): string {
  if (!(e instanceof FetchError)) return e instanceof Error ? e.message : fallback;
  return e.details ? `${e.message}: ${Array.isArray(e.details) ? (e.details as Array<{ message?: string }>).map((d) => d.message).join("; ") : String(e.details)}` : e.message;
}

interface BroadcastLog {
  id: string;
  sent_by: string;
  recipient_type: string;
  recipient_count: number;
  channel: string;
  subject?: string;
  message: string;
  status: string;
  notification_id?: string;
  created_at: string;
}

export default function BroadcastPage() {
  const [activeTab, setActiveTab] = useState<"email" | "sms" | "push" | "history">("email");
  const [isSending, setIsSending] = useState(false);
  const [history, setHistory] = useState<BroadcastLog[]>([]);
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);

  // Email form
  const [emailSubject, setEmailSubject] = useState("");
  const [emailMessage, setEmailMessage] = useState("");
  const [emailRecipientType, setEmailRecipientType] = useState<string>("all_users");
  const [emailSpecificIds, setEmailSpecificIds] = useState("");

  // SMS form
  const [smsMessage, setSmsMessage] = useState("");
  const [smsRecipientType, setSmsRecipientType] = useState<string>("all_users");
  const [smsSpecificIds, setSmsSpecificIds] = useState("");

  // Push form
  const [pushTitle, setPushTitle] = useState("");
  const [pushMessage, setPushMessage] = useState("");
  const [pushRecipientType, setPushRecipientType] = useState<string>("all_users");
  const [pushSpecificIds, setPushSpecificIds] = useState("");
  const [pushUrl, setPushUrl] = useState("");

  useEffect(() => {
    if (activeTab === "history") {
      loadHistory();
    }
  }, [activeTab]);

  const loadHistory = async () => {
    try {
      setIsLoadingHistory(true);
      const response = await fetcher.get<{
        data?: { broadcasts?: BroadcastLog[]; meta?: { total: number } };
        broadcasts?: BroadcastLog[];
      }>("/api/admin/broadcast/history");
      const raw = (response as any)?.data ?? response;
      const broadcasts = Array.isArray(raw?.broadcasts) ? raw.broadcasts : Array.isArray(raw) ? raw : [];
      setHistory(broadcasts);
    } catch (error) {
      console.error("Error loading history:", error);
      toast.error(formatFetchError(error, "Failed to load broadcast history"));
    } finally {
      setIsLoadingHistory(false);
    }
  };

  const getRecipientLabel = (type: string) => {
    if (type === "all_users") return "all customers";
    if (type === "all_providers") return "all providers";
    return "specific recipients";
  };

  const handleSendEmail = async () => {
    if (!emailSubject.trim() || !emailMessage.trim()) {
      toast.error("Subject and message are required");
      return;
    }
    if (emailRecipientType === "custom") {
      const ids = parseUserIds(emailSpecificIds);
      if (ids.length === 0) {
        toast.error("Enter at least one user ID for specific recipients");
        return;
      }
    }
    if (!confirm(`Send email to ${getRecipientLabel(emailRecipientType)}?`)) return;

    try {
      setIsSending(true);
      const payload: { subject: string; message: string; recipient_type: string; user_ids?: string[] } = {
        subject: emailSubject,
        message: emailMessage,
        recipient_type: emailRecipientType,
      };
      if (emailRecipientType === "custom") payload.user_ids = parseUserIds(emailSpecificIds);
      const response = await fetcher.post<{ success: boolean; recipients: number; notification_id: string }>(
        "/api/admin/broadcast/email",
        payload
      );
      const responseData = (response as any)?.data ?? response;
      toast.success(`Email sent to ${responseData?.recipients ?? 0} recipients`);
      setEmailSubject("");
      setEmailMessage("");
      if (emailRecipientType === "custom") setEmailSpecificIds("");
      if (activeTab === "history") loadHistory();
    } catch (error) {
      toast.error(formatFetchError(error, "Failed to send email broadcast"));
    } finally {
      setIsSending(false);
    }
  };

  const handleSendSMS = async () => {
    if (!smsMessage.trim()) {
      toast.error("Message is required");
      return;
    }
    if (smsRecipientType === "custom") {
      const ids = parseUserIds(smsSpecificIds);
      if (ids.length === 0) {
        toast.error("Enter at least one user ID for specific recipients");
        return;
      }
    }
    if (!confirm(`Send SMS to ${getRecipientLabel(smsRecipientType)}?`)) return;

    try {
      setIsSending(true);
      const payload: { message: string; recipient_type: string; user_ids?: string[] } = {
        message: smsMessage,
        recipient_type: smsRecipientType,
      };
      if (smsRecipientType === "custom") payload.user_ids = parseUserIds(smsSpecificIds);
      const response = await fetcher.post<{ success: boolean; recipients: number; notification_id: string }>(
        "/api/admin/broadcast/sms",
        payload
      );
      const responseData = (response as any)?.data ?? response;
      toast.success(`SMS sent to ${responseData?.recipients ?? 0} recipients`);
      setSmsMessage("");
      if (smsRecipientType === "custom") setSmsSpecificIds("");
      if (activeTab === "history") loadHistory();
    } catch (error) {
      toast.error(formatFetchError(error, "Failed to send SMS broadcast"));
    } finally {
      setIsSending(false);
    }
  };

  const handleSendPush = async () => {
    if (!pushTitle.trim() || !pushMessage.trim()) {
      toast.error("Title and message are required");
      return;
    }
    if (pushRecipientType === "custom") {
      const ids = parseUserIds(pushSpecificIds);
      if (ids.length === 0) {
        toast.error("Enter at least one user ID for specific recipients");
        return;
      }
    }
    if (!confirm(`Send push notification to ${getRecipientLabel(pushRecipientType)}?`)) return;

    try {
      setIsSending(true);
      const payload: { title: string; message: string; recipient_type: string; url?: string; user_ids?: string[] } = {
        title: pushTitle,
        message: pushMessage,
        recipient_type: pushRecipientType,
        url: pushUrl || undefined,
      };
      if (pushRecipientType === "custom") payload.user_ids = parseUserIds(pushSpecificIds);
      const response = await fetcher.post<{ success: boolean; recipients: number; notification_id: string }>(
        "/api/admin/broadcast/push",
        payload
      );
      const responseData = (response as any)?.data ?? response;
      toast.success(`Push notification sent to ${responseData?.recipients ?? 0} recipients`);
      setPushTitle("");
      setPushMessage("");
      setPushUrl("");
      if (pushRecipientType === "custom") setPushSpecificIds("");
      if (activeTab === "history") loadHistory();
    } catch (error) {
      toast.error(formatFetchError(error, "Failed to send push broadcast"));
    } finally {
      setIsSending(false);
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "sent":
        return <Badge className="bg-green-100 text-green-800">Sent</Badge>;
      case "failed":
        return <Badge className="bg-red-100 text-red-800">Failed</Badge>;
      default:
        return <Badge className="bg-gray-100 text-gray-800">{status}</Badge>;
    }
  };

  const getChannelIcon = (channel: string) => {
    switch (channel) {
      case "email":
        return <Mail className="w-4 h-4" />;
      case "sms":
        return <MessageSquare className="w-4 h-4" />;
      case "push":
        return <Bell className="w-4 h-4" />;
      default:
        return null;
    }
  };

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 md:p-8 mb-8"
          >
            <div className="mb-6">
              <h1 className="text-3xl font-semibold text-gray-900 mb-2">
                Broadcast Messaging
              </h1>
              <p className="text-gray-600">
                Send messages to all users, providers, or custom segments
              </p>
            </div>

            <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as any)}>
              <TabsList className="mb-6">
                <TabsTrigger value="email">
                  <Mail className="w-4 h-4 mr-2" />
                  Email
                </TabsTrigger>
                <TabsTrigger value="sms">
                  <MessageSquare className="w-4 h-4 mr-2" />
                  SMS
                </TabsTrigger>
                <TabsTrigger value="push">
                  <Bell className="w-4 h-4 mr-2" />
                  Push
                </TabsTrigger>
                <TabsTrigger value="history">
                  <History className="w-4 h-4 mr-2" />
                  History
                </TabsTrigger>
              </TabsList>

              <TabsContent value="email">
