  const [slugError, setSlugError] = useState<string | null>(null);
  const [showIconPicker, setShowIconPicker] = useState(false);
  const [slugManuallyEdited, setSlugManuallyEdited] = useState(false);
  const [iconSearch, setIconSearch] = useState("");
  const [selectedIconCategory, setSelectedIconCategory] = useState<string>("All");
  const [iconType, setIconType] = useState<"icon" | "image">(() => {
    // Detect if existing icon is a URL (image) or icon name
    if (category?.icon && (category.icon.startsWith("http") || category.icon.startsWith("data:"))) {
      return "image";
    }
    return "icon";
  });
  const [imagePreview, setImagePreview] = useState<string | null>(
    category?.icon && (category.icon.startsWith("http") || category.icon.startsWith("data:")) 
      ? category.icon 
      : null
  );

  // Auto-generate slug from name when name changes (unless slug was manually edited)
  useEffect(() => {
    if (!category && !slugManuallyEdited && formData.name) {
      const generatedSlug = generateSlug(formData.name);
      setFormData((prev) => ({ ...prev, slug: generatedSlug }));
      setSlugError(null);
    }
  }, [formData.name, category, slugManuallyEdited]);

  // Validate slug format
  const validateSlug = (slug: string): string | null => {
    if (!slug) {
      return "Slug is required";
    }
    if (!/^[a-z0-9-]+$/.test(slug)) {
      return "Slug must contain only lowercase letters, numbers, and hyphens";
    }
    if (slug.startsWith("-") || slug.endsWith("-")) {
      return "Slug cannot start or end with a hyphen";
    }
    return null;
  };

  const handleNameChange = (name: string) => {
    setFormData((prev) => ({ ...prev, name }));
    if (!slugManuallyEdited && !category) {
      const generatedSlug = generateSlug(name);
      setFormData((prev) => ({ ...prev, slug: generatedSlug }));
    }
  };

  const handleSlugChange = (slug: string) => {
    setSlugManuallyEdited(true);
    const error = validateSlug(slug);
    setSlugError(error);
    setFormData((prev) => ({ ...prev, slug }));
  };

  const handleIconSelect = (iconName: string) => {
    setFormData((prev) => ({ ...prev, icon: iconName }));
    setShowIconPicker(false);
    setIconSearch("");
    setIconType("icon");
    setImagePreview(null);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file type
    if (!file.type.startsWith("image/")) {
      toast.error("Please upload an image file");
      return;
    }

    // Validate file size (max 2MB)
    if (file.size > 2 * 1024 * 1024) {
      toast.error("Image size must be less than 2MB");
      return;
    }

    // Read file as data URL
    const reader = new FileReader();
    reader.onloadend = () => {
      const dataUrl = reader.result as string;
      setImagePreview(dataUrl);
      setFormData((prev) => ({ ...prev, icon: dataUrl }));
      setIconType("image");
    };
    reader.onerror = () => {
      toast.error("Failed to read image file");
    };
    reader.readAsDataURL(file);
  };

  const handleImageUrlChange = (url: string) => {
    setFormData((prev) => ({ ...prev, icon: url }));
    setImagePreview(url);
    setIconType("image");
  };

  const handleRemoveImage = () => {
    setImagePreview(null);
    setFormData((prev) => ({ ...prev, icon: "" }));
  };

  // Check if icon is a URL/image
  const isImageUrl = (icon: string | undefined) => {
    return icon ? (icon.startsWith("http") || icon.startsWith("data:")) : false;
  };

  // Get unique categories
  const iconCategories = ["All", ...Array.from(new Set(BEAUTY_ICONS.map(item => item.category)))];

  const filteredIcons = BEAUTY_ICONS.filter((item) => {
    const matchesSearch = (item.name ?? "").toLowerCase().includes(iconSearch.toLowerCase());
    const matchesCategory = selectedIconCategory === "All" || item.category === selectedIconCategory;
    return matchesSearch && matchesCategory;
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validate slug before submitting
    const slugValidationError = validateSlug(formData.slug);
    if (slugValidationError) {
      setSlugError(slugValidationError);
      toast.error(slugValidationError);
      return;
    }

    try {
      setIsSaving(true);
      setSlugError(null);

      if (category) {
        await fetcher.put(`/api/admin/catalog/global-categories/${category.id}`, formData);
        toast.success("Global category updated");
      } else {
        await fetcher.post("/api/admin/catalog/global-categories", formData);
        toast.success("Global category created");
      }
      onSave();
    } catch (error: any) {
      const errorMessage = error instanceof FetchError 
        ? error.message 
        : error?.response?.data?.error || "Failed to save global category";
      toast.error(errorMessage);
      console.error("Error saving category:", error);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-2xl font-semibold mb-4">
          {category ? "Edit Global Category" : "Add Global Category"}
        </h2>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="gc_name" className="flex items-center gap-2">
              Category Name *
            </Label>
            <Input
              id="gc_name"
              value={formData.name}
              onChange={(e) => handleNameChange(e.target.value)}
              required
              placeholder="e.g., Hair & Styling"
            />
            <p className="text-xs text-gray-500 mt-1">
              The display name for this category
            </p>
          </div>

          <div>
            <Label htmlFor="gc_slug" className="flex items-center gap-2">
              Slug *
              <div className="group relative">
                <HelpCircle className="w-4 h-4 text-gray-400 cursor-help" />
                <div className="absolute left-0 bottom-full mb-2 hidden group-hover:block w-64 p-2 bg-gray-800 text-white text-xs rounded shadow-lg z-10">
                  A slug is a URL-friendly version of the name. It&apos;s used in web addresses (e.g., &quot;hair-styling&quot; becomes /category/hair-styling). Only lowercase letters, numbers, and hyphens are allowed.
                </div>
              </div>
            </Label>
            <Input
              id="gc_slug"
              value={formData.slug}
              onChange={(e) => handleSlugChange(e.target.value)}
              required
              placeholder="e.g., hair-styling"
              className={slugError ? "border-red-500" : ""}
            />
            {slugError ? (
              <p className="text-xs text-red-500 mt-1">{slugError}</p>
            ) : (
              <p className="text-xs text-gray-500 mt-1">
                Auto-generated from name. You can edit it manually. Only lowercase letters, numbers, and hyphens.
              </p>
            )}
          </div>

          <div>
            <Label htmlFor="gc_icon" className="flex items-center gap-2">
              Icon / Image
              <Sparkles className="w-4 h-4 text-gray-400" />
            </Label>

            {/* Toggle between Icon and Image */}
            <div className="flex gap-2 mb-3">
              <Button
                type="button"
                size="sm"
                onClick={() => {
                  setIconType("icon");
                  if (isImageUrl(formData.icon)) {
                    setFormData((prev) => ({ ...prev, icon: "" }));
                    setImagePreview(null);
                  }
                }}
                variant={iconType === "icon" ? "secondary" : "outline"}
                className={iconType === "icon" ? "bg-purple-600 hover:bg-purple-700 text-white" : ""}
              >
                <Tag className="w-4 h-4 inline mr-2" />
                Icon
              </Button>
              <Button
                type="button"
                size="sm"
                onClick={() => {
                  setIconType("image");
                  if (!isImageUrl(formData.icon) && formData.icon) {
                    setFormData((prev) => ({ ...prev, icon: "" }));
                  }
                }}
                variant={iconType === "image" ? "secondary" : "outline"}
                className={iconType === "image" ? "bg-purple-600 hover:bg-purple-700 text-white" : ""}
              >
                <ImageIcon className="w-4 h-4 inline mr-2" />
                Image
              </Button>
            </div>

            {iconType === "icon" ? (
              <div className="flex gap-2">
                <div className="flex-1 relative">
                  <Input
                    id="gc_icon"
                    value={isImageUrl(formData.icon) ? "" : formData.icon}
                    onChange={(e) => setFormData({ ...formData, icon: e.target.value })}
                    placeholder="e.g., Scissors, Heart, Star"
                    className="pr-10"
                  />
                  {formData.icon && !isImageUrl(formData.icon) && getIconByName(formData.icon) && (
                    <div className="absolute right-3 top-1/2 -translate-y-1/2">
                      {(() => {
                        const IconComponent = getIconByName(formData.icon);
                        return IconComponent ? (
                          <IconComponent className="w-4 h-4 text-gray-400" />
                        ) : null;
                      })()}
                    </div>
                  )}
                </div>
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setShowIconPicker(!showIconPicker)}
                >
                  Pick Icon
                </Button>
              </div>
            ) : (
              <div className="space-y-3">
                {/* Image Preview */}
                {imagePreview && (
                  <div className="relative inline-block">
                    <img
                      src={imagePreview}
                      alt="Icon preview"
                      className="w-20 h-20 object-contain border rounded-lg p-2 bg-gray-50"
                    />
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      onClick={handleRemoveImage}
                      className="absolute -top-2 -right-2 h-7 w-7 bg-red-500 text-white rounded-full p-0 hover:bg-red-600"
                    >
                      <X className="w-3 h-3" />
                    </Button>
                  </div>
                )}

                {/* Upload File */}
                <div>
                  <Label htmlFor="icon-upload" className="cursor-pointer">
                    <div className="flex items-center gap-2 p-3 border-2 border-dashed rounded-lg hover:bg-gray-50 transition-colors">
                      <Upload className="w-5 h-5 text-gray-400" />
                      <span className="text-sm text-gray-600">
                        {imagePreview ? "Change Image" : "Upload Image"}
                      </span>
                    </div>
                  </Label>
                  <Input
                    id="icon-upload"
                    type="file"
                    accept="image/*"
                    onChange={handleImageUpload}
                    className="hidden"
                  />
                </div>

                {/* Or Enter URL */}
                <div>
                  <Label htmlFor="icon-url" className="text-sm text-gray-600">
                    Or enter image URL:
                  </Label>
                  <Input
                    id="icon-url"
                    type="url"
                    value={isImageUrl(formData.icon) ? formData.icon : ""}
                    onChange={(e) => handleImageUrlChange(e.target.value)}
                    placeholder="https://example.com/icon.png"
                    className="mt-1"
                  />
                </div>
              </div>
            )}
            {iconType === "icon" && showIconPicker && (
              <div className="mt-2 p-4 border rounded-lg bg-gray-50 max-h-96 overflow-y-auto">
                <div className="mb-3 space-y-2">
                  <Input
                    placeholder="Search icons..."
                    value={iconSearch}
                    onChange={(e) => setIconSearch(e.target.value)}
                    className="w-full"
                  />
                  <div className="flex flex-wrap gap-2">
                    {iconCategories.map((cat) => (
                      <Button
                        key={cat}
                        type="button"
                        size="sm"
                        variant={selectedIconCategory === cat ? "secondary" : "outline"}
                        onClick={() => setSelectedIconCategory(cat)}
                        className={selectedIconCategory === cat ? "rounded-full bg-purple-600 hover:bg-purple-700 text-white text-xs" : "rounded-full text-xs"}
                      >
                        {cat}
                      </Button>
                    ))}
                  </div>
                </div>
                <p className="text-xs text-gray-600 mb-2">
                  Select an icon ({filteredIcons.length} {filteredIcons.length === 1 ? 'icon' : 'icons'}):
                </p>
                <div className="grid grid-cols-4 sm:grid-cols-6 gap-2">
                  {filteredIcons.map(({ name, icon: IconComponent, category }, index) => (
                    <Button
                      key={`${category}-${name}-${index}`}
                      type="button"
                      variant="outline"
                      onClick={() => handleIconSelect(name)}
                      className={`flex flex-col items-center justify-center p-3 h-auto rounded-lg border-2 transition-all hover:bg-white hover:border-purple-400 hover:scale-105 ${
                        formData.icon === name
                          ? "bg-purple-100 border-purple-500"
                          : "bg-white border-gray-200"
                      }`}
                      title={name}
                    >
                      <IconComponent className="w-5 h-5 text-gray-700 mb-1" />
                      <span className="text-xs text-gray-600 truncate w-full text-center">
                        {name}
                      </span>
                    </Button>
                  ))}
                </div>
                {filteredIcons.length === 0 && (
                  <p className="text-xs text-gray-500 text-center py-4">
                    No icons found matching &quot;{iconSearch}&quot;
                  </p>
                )}
                <p className="text-xs text-gray-500 mt-3">
                  Click an icon above, or type the icon name manually (e.g., &quot;Scissors&quot;, &quot;Heart&quot;)
                </p>
              </div>
            )}
            <p className="text-xs text-gray-500 mt-1">
              {iconType === "icon" 
                ? "A professional icon to represent this category (optional). Choose from the picker or type the icon name."
                : "Upload an image or enter an image URL to represent this category (optional). Max 2MB."}
            </p>
          </div>
          <div>
            <Label htmlFor="gc_description">Description</Label>
            <textarea
              id="gc_description"
              value={formData.description}
              onChange={(e) =>
                setFormData({ ...formData, description: e.target.value })
              }
              className="w-full p-2 border rounded-md min-h-[100px]"
            />
          </div>
          <div>
            <Label htmlFor="gc_display_order">Display Order</Label>
            <Input
              id="gc_display_order"
              type="number"
              value={formData.display_order}
              onChange={(e) => setFormData({ ...formData, display_order: parseInt(e.target.value) || 0 })}
            />
          </div>
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                id="gc_is_featured"
                checked={formData.is_featured}
                onChange={(e) =>
                  setFormData({ ...formData, is_featured: e.target.checked })
                }
              />
              <Label htmlFor="gc_is_featured">Featured</Label>
            </div>
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                id="gc_is_active"
                checked={formData.is_active}
                onChange={(e) =>
                  setFormData({ ...formData, is_active: e.target.checked })
                }
              />
              <Label htmlFor="gc_is_active">Active</Label>
            </div>
          </div>
          <div className="flex gap-2 pt-4">
            <Button type="button" variant="outline" onClick={onClose} className="flex-1">
              Cancel
            </Button>
            <Button type="submit" disabled={isSaving} className="flex-1">
              {isSaving ? "Saving..." : category ? "Update" : "Create"}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";

interface AboutUsContent {
  id: string;
  section_key: string;
  title: string;
  content: string;
  display_order: number;
  is_active: boolean;
  image_url?: string | null;
}

interface AboutUsModalProps {
  content: AboutUsContent | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: () => void;
}

export function AboutUsModal({
  content,
  isOpen,
  onClose,
  onSave,
}: AboutUsModalProps) {
  const [title, setTitle] = useState("");
  const [sectionKey, setSectionKey] = useState("");
  const [contentText, setContentText] = useState("");
  const [displayOrder, setDisplayOrder] = useState(0);
  const [isActive, setIsActive] = useState(true);
  const [imageUrl, setImageUrl] = useState("");
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (content) {
      setTitle(content.title);
      setSectionKey(content.section_key);
      setContentText(content.content);
      setDisplayOrder(content.display_order);
      setIsActive(content.is_active);
      setImageUrl(content.image_url ?? "");
    } else {
      setTitle("");
      setSectionKey("");
      setContentText("");
      setDisplayOrder(0);
      setIsActive(true);
      setImageUrl("");
    }
  }, [content, isOpen]);

  const handleSave = async () => {
    if (!title.trim() || !sectionKey.trim() || !contentText.trim()) {
      toast.error("Title, section key, and content are required");
      return;
    }

    try {
      setIsSaving(true);
      if (content) {
        await fetcher.put(`/api/admin/content/about-us/${content.id}`, {
          title: title.trim(),
          content: contentText.trim(),
          display_order: displayOrder,
          is_active: isActive,
          image_url: imageUrl.trim() || null,
        });
        toast.success("About Us content updated");
      } else {
        await fetcher.post("/api/admin/content/about-us", {
          section_key: sectionKey.trim(),
          title: title.trim(),
          content: contentText.trim(),
          display_order: displayOrder,
          is_active: isActive,
          image_url: imageUrl.trim() || null,
        });
        toast.success("About Us content created");
      }
      onSave();
      onClose();
    } catch (error: any) {
      console.error("Error saving about us content:", error);
      toast.error(error.message || "Failed to save about us content");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {content ? `Edit About Us Content: ${content.title}` : "Add About Us Content"}
          </DialogTitle>
          <DialogDescription>
            {content
              ? "Update the about us content section"
              : "Create a new section for the About Us modal"}
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4 py-4">
          <div className="space-y-2">
            <Label htmlFor="section_key">Section Key *</Label>
            <Input
              id="section_key"
              value={sectionKey}
              onChange={(e) => setSectionKey(e.target.value)}
              placeholder="e.g., mission, what_we_do, contact_email"
              disabled={!!content}
              className={content ? "bg-gray-50" : ""}
            />
            <p className="text-xs text-gray-500">
              {content
                ? "The section key cannot be changed after creation"
                : "Unique identifier for this section (e.g., mission, what_we_do)"}
            </p>
          </div>
          <div className="space-y-2">
            <Label htmlFor="title">Title *</Label>
            <Input
              id="title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="e.g., Our Mission, What We Do"
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="content">Content *</Label>
            <Textarea
              id="content"
              value={contentText}
              onChange={(e) => setContentText(e.target.value)}
              placeholder="Enter the content for this section"
              rows={6}
              className="resize-none"
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="image_url">Image URL (optional)</Label>
            <Input
              id="image_url"
              type="url"
              value={imageUrl}
              onChange={(e) => setImageUrl(e.target.value)}
              placeholder="https://..."
            />
            <p className="text-xs text-gray-500">Image shown for this section on the About page.</p>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="display_order">Display Order</Label>
              <Input
                id="display_order"
                type="number"
                value={displayOrder}
                onChange={(e) => setDisplayOrder(parseInt(e.target.value) || 0)}
                min="0"
              />
            </div>
            <div className="space-y-2 flex items-end">
              <div className="flex items-center gap-2">
                <input
                  type="checkbox"
                  id="is_active"
                  checked={isActive}
                  onChange={(e) => setIsActive(e.target.checked)}
                  className="w-4 h-4"
                />
                <Label htmlFor="is_active" className="cursor-pointer">
                  Active
                </Label>
              </div>
            </div>
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={isSaving}>
            Cancel
          </Button>
          <Button
            onClick={handleSave}
            disabled={isSaving || !title.trim() || !sectionKey.trim() || !contentText.trim()}
            className="bg-[#FF0077] hover:bg-[#D60565] text-white"
          >
            {isSaving ? "Saving..." : content ? "Save Changes" : "Create"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";

interface AppLink {
  id: string;
  platform: "ios" | "android";
  title: string;
  href: string;
  display_order: number;
  is_active: boolean;
}

export function AppLinkModal({
  link,
  onClose,
  onSave,
}: {
  link: AppLink | null;
  onClose: () => void;
  onSave: () => void;
}) {
  const [formData, setFormData] = useState({
    platform: (link?.platform || "ios") as "ios" | "android",
    title: link?.title || "",
    href: link?.href || "",
    display_order: link?.display_order || 0,
    is_active: link?.is_active ?? true,
  });
  const [isSaving, setIsSaving] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setIsSaving(true);
      if (link) {
        await fetcher.put(`/api/admin/content/app-links/${link.id}`, formData);
        toast.success("App link updated");
      } else {
        await fetcher.post("/api/admin/content/app-links", formData);
        toast.success("App link created");
      }
      onSave();
    } catch {
      toast.error("Failed to save app link");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-2xl font-semibold mb-4">
          {link ? "Edit App Link" : "Add App Link"}
        </h2>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="platform">Platform *</Label>
            <select
              id="platform"
              value={formData.platform}
              onChange={(e) => setFormData({ ...formData, platform: e.target.value as any })}
              className="w-full p-2 border rounded-md"
              required
              disabled={!!link} // Can't change platform after creation
            >
              <option value="ios">iOS (App Store)</option>
              <option value="android">Android (Google Play)</option>
            </select>
            {link && <p className="text-xs text-gray-500 mt-1">Platform cannot be changed after creation</p>}
          </div>
          <div>
            <Label htmlFor="title">Title *</Label>
            <Input
              id="title"
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
              placeholder="Download app from iOS App Store"
              required
            />
          </div>
          <div>
