"use client";

import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";

interface PreferenceOption {
  id: string;
  type: 'language' | 'currency' | 'timezone';
  code: string | null;
  name: string;
  display_order: number;
  is_active: boolean;
  metadata?: any;
}

interface PreferenceOptionModalProps {
  option: PreferenceOption | null;
  type: 'language' | 'currency' | 'timezone';
  isOpen: boolean;
  onClose: () => void;
  onSave: () => void;
}

export function PreferenceOptionModal({
  option,
  type,
  isOpen,
  onClose,
  onSave,
}: PreferenceOptionModalProps) {
  const [formData, setFormData] = useState({
    code: "",
    name: "",
    display_order: 0,
    is_active: true,
    metadata: {} as any,
  });
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (option) {
      setFormData({
        code: option.code || "",
        name: option.name,
        display_order: option.display_order,
        is_active: option.is_active,
        metadata: option.metadata || {},
      });
    } else {
      setFormData({
        code: "",
        name: "",
        display_order: 0,
        is_active: true,
        metadata: {},
      });
    }
  }, [option, isOpen]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!formData.name.trim()) {
      toast.error("Name is required");
      return;
    }

    try {
      setIsSaving(true);
      const payload = {
        type,
        code: formData.code.trim() || null,
        name: formData.name.trim(),
        display_order: formData.display_order,
        is_active: formData.is_active,
        metadata: Object.keys(formData.metadata).length > 0 ? formData.metadata : null,
      };

      if (option) {
        await fetcher.put(`/api/admin/content/preference-options/${option.id}`, payload);
        toast.success(`${type} updated`);
      } else {
        await fetcher.post("/api/admin/content/preference-options", payload);
        toast.success(`${type} created`);
      }
      onSave();
    } catch (error: any) {
      console.error("Failed to save preference option:", error);
      // Extract error message from API response
      let errorMessage = `Failed to save ${type}`;
      if (error.message) {
        errorMessage = error.message;
      } else if (error.error?.message) {
        errorMessage = error.error.message;
      } else if (typeof error === 'string') {
        errorMessage = error;
      }
      toast.error(errorMessage);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>
            {option ? `Edit ${type}` : `Add ${type}`}
          </DialogTitle>
          <DialogDescription>
            {option ? `Update the ${type} option` : `Create a new ${type} option for users to select`}
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4 py-4">
          <div className="space-y-2">
            <Label htmlFor="name">Name *</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              placeholder={type === 'language' ? 'e.g., English' : type === 'currency' ? 'e.g., United States dollar' : 'e.g., (GMT-05:00) Eastern Time'}
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="code">
              Code {type === 'timezone' ? '(Optional)' : '(Recommended)'}
            </Label>
            <Input
              id="code"
              value={formData.code}
              onChange={(e) => setFormData({ ...formData, code: e.target.value })}
              placeholder={type === 'language' ? 'e.g., en' : type === 'currency' ? 'e.g., USD' : 'e.g., GMT-5'}
            />
            <p className="text-xs text-gray-500">
              {type === 'language' && 'ISO language code (e.g., en, es, fr)'}
              {type === 'currency' && 'ISO currency code (e.g., USD, EUR, GBP)'}
              {type === 'timezone' && 'Timezone identifier (optional)'}
            </p>
          </div>

          {type === 'currency' && (
            <div className="space-y-2">
              <Label htmlFor="symbol">Currency Symbol (Optional)</Label>
              <Input
                id="symbol"
                value={formData.metadata?.symbol || ""}
                onChange={(e) => setFormData({
                  ...formData,
                  metadata: { ...formData.metadata, symbol: e.target.value }
                })}
                placeholder="e.g., R, Γé¼, ┬ú"
              />
            </div>
          )}

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="display_order">Display Order</Label>
              <Input
                id="display_order"
                type="number"
                value={formData.display_order}
                onChange={(e) => setFormData({ ...formData, display_order: parseInt(e.target.value) || 0 })}
                min="0"
              />
              <p className="text-xs text-gray-500">Lower numbers appear first</p>
            </div>
            <div className="flex items-center gap-2 pt-6">
              <Switch
                id="is_active"
                checked={formData.is_active}
                onCheckedChange={(checked) => setFormData({ ...formData, is_active: checked })}
              />
              <Label htmlFor="is_active" className="cursor-pointer">
                Active (visible to users)
              </Label>
            </div>
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose} disabled={isSaving}>
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSaving || !formData.name.trim()}
              className="bg-[#FF0077] hover:bg-[#D60565] text-white"
            >
              {isSaving ? "Saving..." : option ? "Update" : "Create"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import WysiwygEditor from "@/components/admin/WysiwygEditor";

/** Accepts PageContent (order) or SignupPageContent (display_order) */
interface SignupPageContent {
  id?: string;
  section_key: string;
  content_type: "text" | "html" | "json" | "image" | "video";
  content: string;
  metadata?: Record<string, any>;
  display_order?: number;
  order?: number;
  is_active: boolean;
}

const getDisplayOrder = (c: SignupPageContent | null) =>
  c ? (c.display_order ?? c.order ?? 0) : 0;

interface SignupPageModalProps {
  content: SignupPageContent | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: () => void;
}

export function SignupPageModal({ content, isOpen, onClose, onSave }: SignupPageModalProps) {
  const [formData, setFormData] = useState<SignupPageContent>({
    section_key: content?.section_key || "",
    content_type: content?.content_type || "text",
    content: content?.content || "",
    metadata: content?.metadata || {},
    display_order: getDisplayOrder(content),
    is_active: content?.is_active ?? true,
  });
  const [isSaving, setIsSaving] = useState(false);
  const [metadataJson, setMetadataJson] = useState(JSON.stringify(formData.metadata || {}, null, 2));

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setIsSaving(true);
      
      // Parse metadata JSON
      let parsedMetadata = {};
      try {
        parsedMetadata = metadataJson.trim() ? JSON.parse(metadataJson) : {};
      } catch {
        toast.error("Invalid JSON in metadata field");
        return;
      }

      const payload = {
        page_slug: "signup",
        section_key: formData.section_key,
        content_type: formData.content_type,
        content: formData.content,
        metadata: parsedMetadata,
        display_order: formData.display_order,
        is_active: formData.is_active,
      };

      if (content?.id) {
        await fetcher.put(`/api/admin/content/pages/${content.id}`, payload);
        toast.success("Signup page content updated");
      } else {
        await fetcher.post("/api/admin/content/pages", payload);
        toast.success("Signup page content created");
      }
      onSave();
    } catch (error: any) {
      toast.error(error.message || "Failed to save content");
    } finally {
      setIsSaving(false);
    }
  };

  const sectionKeyOptions = [
    { value: "headline", label: "Headline (Main title)" },
    { value: "sub_heading", label: "Sub-heading" },
    { value: "provider_card_title", label: "Provider Card - Title" },
    { value: "provider_card_micro_copy", label: "Provider Card - Micro Copy" },
    { value: "provider_card_description", label: "Provider Card - Description" },
    { value: "provider_card_badge", label: "Provider Card - Badge Text" },
    { value: "customer_card_title", label: "Customer Card - Title" },
    { value: "customer_card_description", label: "Customer Card - Description" },
    { value: "customer_card_sub_description", label: "Customer Card - Sub Description" },
    { value: "testimonial_quote", label: "Testimonial - Quote" },
    { value: "testimonial_attribution", label: "Testimonial - Attribution" },
    { value: "testimonial_pure_commerce", label: "Testimonial - Pure Commerce Badge" },
    { value: "testimonial_yoco_support", label: "Testimonial - Yoco Support Badge" },
    { value: "background_image_url", label: "Background Image URL" },
    { value: "footer_text", label: "Footer Text" },
  ];

  return (
    <div className="fixed inset-0 bg-black/60 dark:bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-white dark:bg-gray-800 rounded-lg p-4 sm:p-6 max-w-4xl w-full max-h-[90vh] overflow-y-auto shadow-2xl border border-gray-200 dark:border-gray-700">
        <h2 className="text-xl sm:text-2xl font-bold mb-4 text-gray-900 dark:text-white">
          {content?.id ? "Edit Signup Page Content" : "Add Signup Page Content"}
        </h2>
        
        <div className="mb-4 p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
          <p className="text-sm text-blue-800 dark:text-blue-200">
            <strong>≡ƒÆí Signup Page Content Management:</strong> Manage all content for the signup entry portal. 
            Use <strong>HTML</strong> content type for rich text formatting. The <strong>background_image_url</strong> 
            section should use <strong>image</strong> content type.
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <Label htmlFor="section_key" className="text-sm font-semibold text-gray-900 dark:text-white mb-2 block">
                Section Key *
              </Label>
              <select
                id="section_key"
                value={formData.section_key}
                onChange={(e) => setFormData({ ...formData, section_key: e.target.value })}
                className="w-full p-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:border-primary focus:ring-primary"
                required
              >
