export default function ControlPlaneFeatureFlagsPage() {
  const [flags, setFlags] = useState<Array<Record<string, any>>>([]);
  const [loading, setLoading] = useState(true);
  const [preview, setPreview] = useState<Record<string, { enabled: boolean }> | null>(null);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [previewForm, setPreviewForm] = useState({
    user_id: "",
    role: "",
    platform: "web",
    environment: "production",
    app_version: "",
  });

  useEffect(() => {
    (async () => {
      try {
        const res = await fetcher.get<{ data: Array<Record<string, any>> }>("/api/admin/feature-flags");
        setFlags(res.data ?? []);
      } catch {
        toast.error("Failed to load feature flags");
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const runPreview = async () => {
    setPreviewLoading(true);
    try {
      const res = await fetcher.post<{ data: { resolved: Record<string, { enabled: boolean }> } }>(
        "/api/admin/control-plane/flags-preview",
        previewForm
      );
      setPreview(res.data?.resolved ?? null);
    } catch {
      toast.error("Failed to run preview");
    } finally {
        setPreviewLoading(false);
    }
  };

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
    <div className="space-y-6">
      <div className="flex items-center gap-2">
        <Link href="/admin/control-plane/overview">
          <Button variant="ghost" size="icon"><ArrowLeft className="h-4 w-4" /></Button>
        </Link>
        <div>
          <h1 className="text-2xl font-bold">Feature Flags</h1>
          <p className="text-muted-foreground">Manage rollouts, platforms, roles, and min version. Use the main <Link className="underline" href="/admin/settings/feature-flags">Feature Flags</Link> page for full CRUD.</p>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Preview resolver</CardTitle>
          <CardDescription>See how flags resolve for a given user/role/platform/environment/app version.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-5">
            <div>
              <Label>User ID (optional)</Label>
              <Input
                placeholder="uuid"
                value={previewForm.user_id}
                onChange={(e) => setPreviewForm((p) => ({ ...p, user_id: e.target.value }))}
              />
            </div>
            <div>
              <Label>Role</Label>
              <Select
                value={previewForm.role || "__any__"}
                onValueChange={(v) => setPreviewForm((p) => ({ ...p, role: v === "__any__" ? "" : v }))}
              >
                <SelectTrigger><SelectValue placeholder="Any" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="__any__">Any</SelectItem>
                  <SelectItem value="superadmin">superadmin</SelectItem>
                  <SelectItem value="provider_owner">provider_owner</SelectItem>
                  <SelectItem value="provider_staff">provider_staff</SelectItem>
                  <SelectItem value="customer">customer</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Platform</Label>
              <Select value={previewForm.platform} onValueChange={(v) => setPreviewForm((p) => ({ ...p, platform: v }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="web">web</SelectItem>
                  <SelectItem value="customer">customer</SelectItem>
                  <SelectItem value="provider">provider</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Environment</Label>
              <Select value={previewForm.environment} onValueChange={(v) => setPreviewForm((p) => ({ ...p, environment: v }))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="production">production</SelectItem>
                  <SelectItem value="staging">staging</SelectItem>
                  <SelectItem value="development">development</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>App version (optional)</Label>
              <Input
                placeholder="1.0.0"
                value={previewForm.app_version}
                onChange={(e) => setPreviewForm((p) => ({ ...p, app_version: e.target.value }))}
              />
            </div>
          </div>
          <Button onClick={runPreview} disabled={previewLoading}>{previewLoading ? "ResolvingΓÇª" : "Resolve"}</Button>
          {preview && (
            <div className="rounded border p-4">
              <p className="text-sm font-medium mb-2">Resolved flags</p>
              <div className="flex flex-wrap gap-2">
                {Object.entries(preview).map(([key, v]) => (
                  <Badge key={key} variant={v.enabled ? "default" : "secondary"}>{key}: {v.enabled ? "on" : "off"}</Badge>
                ))}
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {loading ? (
        <p>LoadingΓÇª</p>
      ) : (
        <Card>
          <CardHeader>
            <CardTitle>All flags (read-only here)</CardTitle>
            <CardDescription>Edit rollout %, platforms, roles, min_app_version on the main Feature Flags page; changes are logged to config change log.</CardDescription>
          </CardHeader>
          <CardContent>
            <ul className="space-y-2">
              {flags.map((f) => (
                <li key={String(f.id)} className="flex items-center gap-2">
                  <Badge variant={(f.enabled as boolean) ? "default" : "secondary"}>
                    {String(f.feature_key)}
                  </Badge>
                  <span className="text-sm text-muted-foreground">
                    rollout={Number(f.rollout_percent ?? 100)}%
                    {(f.platforms_allowed as string[] | null)?.length ? ` ┬╖ platforms=${(f.platforms_allowed as string[]).join(",")}` : ""}
                    {(f.roles_allowed as string[] | null)?.length ? ` ┬╖ roles=${(f.roles_allowed as string[]).join(",")}` : ""}
                    {f.min_app_version ? ` ┬╖ min=${f.min_app_version}` : ""}
                  </span>
                </li>
              ))}
            </ul>
          </CardContent>
        </Card>
      )}
    </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { toast } from "sonner";
import { fetcher } from "@/lib/http/fetcher";
import { ArrowLeft } from "lucide-react";
import RoleGuard from "@/components/auth/RoleGuard";

export default function AuraIntegrationPage() {
  const [env, setEnv] = useState("production");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    enabled: false,
    org_id: "",
    api_key_secret: "",
  });
  const [apiKeySet, setApiKeySet] = useState(false);

  useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        const res = await fetcher.get<{ data: Record<string, any> | null }>(`/api/admin/control-plane/integrations/aura?environment=${env}`);
        const d = res.data;
        if (d) {
          setForm((p) => ({
            ...p,
            enabled: Boolean(d.enabled),
            org_id: String(d.org_id ?? ""),
          }));
          setApiKeySet(Boolean((d as { api_key_set?: boolean }).api_key_set));
        }
      } catch {
        toast.error("Failed to load config");
      } finally {
        setLoading(false);
      }
    })();
  }, [env]);

  const save = async () => {
    setSaving(true);
    try {
      await fetcher.put("/api/admin/control-plane/integrations/aura", {
        environment: env,
        enabled: form.enabled,
        org_id: form.org_id || null,
        ...(form.api_key_secret ? { api_key_secret: form.api_key_secret } : {}),
      });
      setForm((p) => ({ ...p, api_key_secret: "" }));
      if (form.api_key_secret) setApiKeySet(true);
      toast.success("Saved");
    } catch {
      toast.error("Failed to save");
    } finally {
      setSaving(false);
    }
  };

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
    <div className="space-y-6">
      <div className="flex items-center gap-2">
        <Link href="/admin/control-plane/integrations"><Button variant="ghost" size="icon"><ArrowLeft className="h-4 w-4" /></Button></Link>
        <div>
          <h1 className="text-2xl font-bold">Aura</h1>
          <p className="text-muted-foreground">Identity/trust & safety (panic, check-in, escalation). API key and org ID. Never shown after save.</p>
        </div>
      </div>

      <div className="flex items-center gap-4">
        <Label>Environment</Label>
        <Select value={env} onValueChange={setEnv}>
          <SelectTrigger className="w-[180px]"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="development">Development</SelectItem>
            <SelectItem value="staging">Staging</SelectItem>
            <SelectItem value="production">Production</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {loading ? (
        <p>LoadingΓÇª</p>
      ) : (
        <Card>
          <CardHeader>
            <CardTitle>Config</CardTitle>
            <CardDescription>API key is never returned. Leave blank to keep existing key.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center gap-2">
              <Switch checked={form.enabled} onCheckedChange={(v) => setForm((p) => ({ ...p, enabled: v }))} />
              <Label>Enabled</Label>
            </div>
            <div>
              <Label>Org ID</Label>
              <Input value={form.org_id} onChange={(e) => setForm((p) => ({ ...p, org_id: e.target.value }))} placeholder="aura-org-id" />
            </div>
            <div>
              <Label>API key (leave blank to keep)</Label>
              <Input type="password" placeholder={apiKeySet ? "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" : "Enter Aura API key"} value={form.api_key_secret} onChange={(e) => setForm((p) => ({ ...p, api_key_secret: e.target.value }))} />
            </div>
            <Button onClick={save} disabled={saving}>{saving ? "SavingΓÇª" : "Save"}</Button>
          </CardContent>
        </Card>
      )}
    </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { toast } from "sonner";
import { fetcher } from "@/lib/http/fetcher";
import { ArrowLeft } from "lucide-react";
import RoleGuard from "@/components/auth/RoleGuard";

export default function GeminiIntegrationPage() {
  const [env, setEnv] = useState("production");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    enabled: false,
    api_key_secret: "",
    default_model: "gemini-1.5-flash",
    allowed_models: "[\"gemini-1.5-flash\",\"gemini-1.5-pro\"]",
    safety_settings: "{}",
  });
  const [apiKeySet, setApiKeySet] = useState(false);

  useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        const res = await fetcher.get<{ data: Record<string, any> | null }>(`/api/admin/control-plane/integrations/gemini?environment=${env}`);
        const d = res.data;
        if (d) {
          setForm((p) => ({
            ...p,
            enabled: Boolean(d.enabled),
            default_model: String(d.default_model ?? "gemini-1.5-flash"),
            allowed_models: typeof d.allowed_models === "string" ? d.allowed_models : JSON.stringify(d.allowed_models ?? [], null, 2),
            safety_settings: typeof d.safety_settings === "string" ? d.safety_settings : JSON.stringify(d.safety_settings ?? {}, null, 2),
          }));
          setApiKeySet(Boolean((d as { api_key_set?: boolean }).api_key_set));
        }
      } catch {
        toast.error("Failed to load config");
      } finally {
        setLoading(false);
      }
    })();
  }, [env]);

  const save = async () => {
    setSaving(true);
    try {
      let allowed_models: string[] = [];
      let safety_settings: Record<string, any> = {};
      try {
        allowed_models = JSON.parse(form.allowed_models);
        safety_settings = JSON.parse(form.safety_settings || "{}");
      } catch {
        toast.error("Invalid JSON");
        setSaving(false);
        return;
      }
      await fetcher.put("/api/admin/control-plane/integrations/gemini", {
        environment: env,
        enabled: form.enabled,
        default_model: form.default_model,
        allowed_models,
        safety_settings,
        ...(form.api_key_secret ? { api_key_secret: form.api_key_secret } : {}),
      });
      setForm((p) => ({ ...p, api_key_secret: "" }));
      setApiKeySet(!!form.api_key_secret || apiKeySet);
      toast.success("Saved");
    } catch {
      toast.error("Failed to save");
    } finally {
      setSaving(false);
    }
  };

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
    <div className="space-y-6">
      <div className="flex items-center gap-2">
        <Link href="/admin/control-plane/integrations"><Button variant="ghost" size="icon"><ArrowLeft className="h-4 w-4" /></Button></Link>
        <div>
          <h1 className="text-2xl font-bold">Gemini</h1>
          <p className="text-muted-foreground">API key (stored securely), default model, allowed models, safety settings.</p>
        </div>
      </div>

      <div className="flex items-center gap-4">
        <Label>Environment</Label>
        <Select value={env} onValueChange={setEnv}>
          <SelectTrigger className="w-[180px]"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="development">Development</SelectItem>
            <SelectItem value="staging">Staging</SelectItem>
            <SelectItem value="production">Production</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {loading ? (
        <p>LoadingΓÇª</p>
      ) : (
        <Card>
          <CardHeader>
            <CardTitle>Config</CardTitle>
            <CardDescription>API key is never returned after save. Leave blank to keep existing key.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center gap-2">
              <Switch checked={form.enabled} onCheckedChange={(v) => setForm((p) => ({ ...p, enabled: v }))} />
              <Label>Enabled</Label>
            </div>
            <div>
              <Label>API key (leave blank to keep current)</Label>
              <Input
                type="password"
                placeholder={apiKeySet ? "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" : "Enter Gemini API key"}
                value={form.api_key_secret}
                onChange={(e) => setForm((p) => ({ ...p, api_key_secret: e.target.value }))}
              />
            </div>
            <div>
              <Label>Default model</Label>
              <Input value={form.default_model} onChange={(e) => setForm((p) => ({ ...p, default_model: e.target.value }))} />
            </div>
            <div>
              <Label>Allowed models (JSON array)</Label>
              <textarea className="w-full min-h-[80px] rounded border p-2 font-mono text-sm" value={form.allowed_models} onChange={(e) => setForm((p) => ({ ...p, allowed_models: e.target.value }))} />
            </div>
            <div>
              <Label>Safety settings (JSON)</Label>
              <textarea className="w-full min-h-[80px] rounded border p-2 font-mono text-sm" value={form.safety_settings} onChange={(e) => setForm((p) => ({ ...p, safety_settings: e.target.value }))} />
            </div>
            <Button onClick={save} disabled={saving}>{saving ? "SavingΓÇª" : "Save"}</Button>
          </CardContent>
        </Card>
      )}
    </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { toast } from "sonner";
import { fetcher } from "@/lib/http/fetcher";
import { ArrowLeft } from "lucide-react";
import RoleGuard from "@/components/auth/RoleGuard";

export default function SumsubIntegrationPage() {
  const [env, setEnv] = useState("production");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    enabled: false,
    level_name: "",
    app_token_secret: "",
    secret_key_secret: "",
    webhook_secret_secret: "",
  });
  const [secretsSet, setSecretsSet] = useState({ app_token: false, secret_key: false, webhook: false });

  useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        const res = await fetcher.get<{ data: Record<string, any> | null }>(`/api/admin/control-plane/integrations/sumsub?environment=${env}`);
        const d = res.data;
        if (d) {
          setForm((p) => ({
            ...p,
            enabled: Boolean(d.enabled),
            level_name: String(d.level_name ?? ""),
          }));
          setSecretsSet({
            app_token: Boolean((d as { app_token_set?: boolean }).app_token_set),
            secret_key: Boolean((d as { secret_key_set?: boolean }).secret_key_set),
            webhook: Boolean((d as { webhook_secret_set?: boolean }).webhook_secret_set),
          });
        }
      } catch {
        toast.error("Failed to load config");
      } finally {
        setLoading(false);
      }
    })();
  }, [env]);

  const save = async () => {
    setSaving(true);
    try {
      await fetcher.put("/api/admin/control-plane/integrations/sumsub", {
        environment: env,
        enabled: form.enabled,
        level_name: form.level_name || null,
        ...(form.app_token_secret ? { app_token_secret: form.app_token_secret } : {}),
        ...(form.secret_key_secret ? { secret_key_secret: form.secret_key_secret } : {}),
        ...(form.webhook_secret_secret ? { webhook_secret_secret: form.webhook_secret_secret } : {}),
      });
      setForm((p) => ({ ...p, app_token_secret: "", secret_key_secret: "", webhook_secret_secret: "" }));
      if (form.app_token_secret) setSecretsSet((s) => ({ ...s, app_token: true }));
      if (form.secret_key_secret) setSecretsSet((s) => ({ ...s, secret_key: true }));
      if (form.webhook_secret_secret) setSecretsSet((s) => ({ ...s, webhook: true }));
      toast.success("Saved");
    } catch {
      toast.error("Failed to save");
    } finally {
      setSaving(false);
    }
  };

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
