            escalation_enabled: Boolean(d.escalation_enabled ?? true),
            cooldown_seconds: Number(d.cooldown_seconds ?? 300),
            ui_copy: typeof d.ui_copy === "string" ? d.ui_copy : JSON.stringify(d.ui_copy ?? {}, null, 2),
          });
        }
      } catch {
        toast.error("Failed to load config");
      } finally {
        setLoading(false);
      }
    })();
  }, [env]);

  const save = async () => {
    setSaving(true);
    try {
      let uiCopy: Record<string, any> = {};
      try {
        uiCopy = JSON.parse(form.ui_copy || "{}");
      } catch {
        toast.error("Invalid JSON in UI copy");
        setSaving(false);
        return;
      }
      await fetcher.put("/api/admin/control-plane/modules/safety", {
        environment: env,
        enabled: form.enabled,
        check_in_enabled: form.check_in_enabled,
        escalation_enabled: form.escalation_enabled,
        cooldown_seconds: form.cooldown_seconds,
        ui_copy: uiCopy,
      });
      toast.success("Saved");
    } catch {
      toast.error("Failed to save");
    } finally {
      setSaving(false);
    }
  };

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
    <div className="space-y-6">
      <div className="flex items-center gap-2">
        <Link href="/admin/control-plane/overview"><Button variant="ghost" size="icon"><ArrowLeft className="h-4 w-4" /></Button></Link>
        <div>
          <h1 className="text-2xl font-bold">Safety Module</h1>
          <p className="text-muted-foreground">Panic / assist / check-in via Aura. Enable check-in and escalation; set cooldown and UI copy.</p>
        </div>
      </div>

      <div className="flex items-center gap-4">
        <Label>Environment</Label>
        <Select value={env} onValueChange={setEnv}>
          <SelectTrigger className="w-[180px]"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="development">Development</SelectItem>
            <SelectItem value="staging">Staging</SelectItem>
            <SelectItem value="production">Production</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {loading ? (
        <p>LoadingΓÇª</p>
      ) : (
        <Card>
          <CardHeader>
            <CardTitle>Config</CardTitle>
            <CardDescription>Requires Aura integration enabled for escalation. Use feature flags safety.enabled, safety.panic.enabled, safety.check_in.enabled.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center gap-2">
              <Switch checked={form.enabled} onCheckedChange={(v) => setForm((p) => ({ ...p, enabled: v }))} />
              <Label>Enabled</Label>
            </div>
            <div className="flex items-center gap-2">
              <Switch checked={form.check_in_enabled} onCheckedChange={(v) => setForm((p) => ({ ...p, check_in_enabled: v }))} />
              <Label>Check-in enabled</Label>
            </div>
            <div className="flex items-center gap-2">
              <Switch checked={form.escalation_enabled} onCheckedChange={(v) => setForm((p) => ({ ...p, escalation_enabled: v }))} />
              <Label>Escalation enabled (Aura)</Label>
            </div>
            <div>
              <Label>Cooldown (seconds)</Label>
              <Input type="number" min={0} value={form.cooldown_seconds} onChange={(e) => setForm((p) => ({ ...p, cooldown_seconds: parseInt(e.target.value, 10) || 0 }))} />
            </div>
            <div>
              <Label>UI copy (JSON)</Label>
              <textarea className="w-full min-h-[80px] rounded border p-2 font-mono text-sm" value={form.ui_copy} onChange={(e) => setForm((p) => ({ ...p, ui_copy: e.target.value }))} />
            </div>
            <Button onClick={save} disabled={saving}>{saving ? "SavingΓÇª" : "Save"}</Button>
          </CardContent>
        </Card>
      )}
    </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Switch } from "@/components/ui/switch";
import { Plus, Edit, Trash2 } from "lucide-react";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

interface CustomField {
  id: string;
  name: string;
  label: string;
  field_type: string;
  entity_type: string;
  is_required: boolean;
  is_active: boolean;
  validation_rules: Record<string, any> | null;
  default_value: string | null;
  placeholder: string | null;
  help_text: string | null;
  display_order: number;
  created_at: string;
}

export default function CustomFieldsPage() {
  const [fields, setFields] = useState<CustomField[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingField, setEditingField] = useState<CustomField | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    label: "",
    field_type: "text",
    entity_type: "user",
    is_required: false,
    is_active: true,
    placeholder: "",
    help_text: "",
    default_value: "",
    display_order: 0,
  });

  useEffect(() => {
    loadFields();
  }, []);

  const loadFields = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher
        .get<{ data?: { fields?: CustomField[] } }>("/api/admin/custom-fields")
        .catch(() => ({ data: { fields: [] } }));
      setFields(response.data?.fields ?? []);
    } catch (error) {
      console.error("Failed to load custom fields:", error);
      // Don't show error if endpoint doesn't exist yet
      setFields([]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreate = () => {
    setEditingField(null);
    setFormData({
      name: "",
      label: "",
      field_type: "text",
      entity_type: "user",
      is_required: false,
      is_active: true,
      placeholder: "",
      help_text: "",
      default_value: "",
      display_order: fields.length,
    });
    setIsDialogOpen(true);
  };

  const handleEdit = (field: CustomField) => {
    setEditingField(field);
    setFormData({
      name: field.name,
      label: field.label,
      field_type: field.field_type,
      entity_type: field.entity_type,
      is_required: field.is_required,
      is_active: field.is_active,
      placeholder: field.placeholder || "",
      help_text: field.help_text || "",
      default_value: field.default_value || "",
      display_order: field.display_order,
    });
    setIsDialogOpen(true);
  };

  const handleSubmit = async () => {
    try {
      if (editingField) {
        await fetcher.put(`/api/admin/custom-fields/${editingField.id}`, formData);
        toast.success("Custom field updated successfully");
      } else {
        await fetcher.post("/api/admin/custom-fields", formData);
        toast.success("Custom field created successfully");
      }
      setIsDialogOpen(false);
      loadFields();
    } catch (error) {
      console.error("Failed to save custom field:", error);
      toast.error(error instanceof FetchError ? error.message : "Failed to save custom field");
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this custom field?")) {
      return;
    }

    try {
      await fetcher.delete(`/api/admin/custom-fields/${id}`);
      toast.success("Custom field deleted successfully");
      loadFields();
    } catch (error) {
      console.error("Failed to delete custom field:", error);
      toast.error("Failed to delete custom field");
    }
  };

  const handleToggleActive = async (field: CustomField) => {
    try {
      await fetcher.patch(`/api/admin/custom-fields/${field.id}`, {
        is_active: !field.is_active,
      });
      toast.success(`Custom field ${!field.is_active ? "activated" : "deactivated"}`);
      loadFields();
    } catch (error) {
      console.error("Failed to toggle custom field:", error);
      toast.error("Failed to update custom field");
    }
  };

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading custom fields..." />;
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="container mx-auto px-4 py-8">
        <div className="mb-6">
          <AdminPageHeader
            title="Custom Fields"
            description="Platform-level definitions: extra fields that can apply to users, providers, bookings, and services. Managed by superadmin onlyΓÇönot by individual providers."
            actions={
              <Button onClick={handleCreate} className="bg-[#FF0077] hover:bg-[#D60565]">
                <Plus className="w-4 h-4 mr-2" />
                Add Custom Field
              </Button>
            }
          />
          <p className="text-sm text-amber-700 mt-2">
            <strong>Not provider-managed:</strong> Providers do not define their own custom fields here. You define which fields exist for each entity type; those definitions would be used when editing a user, provider, booking, or service (consumer UI may not be wired yet).
          </p>
        </div>

        {fields.length === 0 ? (
          <EmptyState
            icon={Edit}
            title="No custom fields yet"
            description="Define platform-wide extra fields for user, provider, booking, or service entities. Only superadmin can create or edit these."
            action={{
              label: "Create Custom Field",
              onClick: handleCreate,
            }}
          />
        ) : (
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Name</TableHead>
                  <TableHead>Label</TableHead>
                  <TableHead>Type</TableHead>
                  <TableHead>Entity</TableHead>
                  <TableHead>Required</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Order</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {fields.map((field) => (
                  <TableRow key={field.id}>
                    <TableCell className="font-medium">{field.name}</TableCell>
                    <TableCell>{field.label}</TableCell>
                    <TableCell>
                      <Badge variant="outline">{field.field_type}</Badge>
                    </TableCell>
                    <TableCell>
                      <Badge variant="secondary">{field.entity_type}</Badge>
                    </TableCell>
                    <TableCell>
                      {field.is_required ? (
                        <Badge variant="destructive">Required</Badge>
                      ) : (
                        <span className="text-gray-400">Optional</span>
                      )}
                    </TableCell>
                    <TableCell>
                      <Switch
                        checked={field.is_active}
                        onCheckedChange={() => handleToggleActive(field)}
                      />
                    </TableCell>
                    <TableCell>{field.display_order}</TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleEdit(field)}
                        >
                          <Edit className="w-4 h-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDelete(field.id)}
                        >
                          <Trash2 className="w-4 h-4 text-red-600" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}

        <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
          <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>
                {editingField ? "Edit Custom Field" : "Create Custom Field"}
              </DialogTitle>
              <DialogDescription>
                {editingField
                  ? "Update the custom field details"
                  : "Add a new custom field to collect additional information"}
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4 py-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="name">Field Name *</Label>
                  <Input
                    id="name"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    placeholder="e.g., emergency_contact"
                  />
                </div>
                <div>
                  <Label htmlFor="label">Display Label *</Label>
                  <Input
                    id="label"
                    value={formData.label}
                    onChange={(e) => setFormData({ ...formData, label: e.target.value })}
                    placeholder="e.g., Emergency Contact"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="field_type">Field Type *</Label>
                  <Select
                    value={formData.field_type}
                    onValueChange={(value) => setFormData({ ...formData, field_type: value })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="text">Text</SelectItem>
                      <SelectItem value="textarea">Textarea</SelectItem>
                      <SelectItem value="number">Number</SelectItem>
                      <SelectItem value="email">Email</SelectItem>
                      <SelectItem value="phone">Phone</SelectItem>
                      <SelectItem value="date">Date</SelectItem>
                      <SelectItem value="select">Select</SelectItem>
                      <SelectItem value="checkbox">Checkbox</SelectItem>
                      <SelectItem value="radio">Radio</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label htmlFor="entity_type">Entity Type *</Label>
                  <Select
                    value={formData.entity_type}
                    onValueChange={(value) => setFormData({ ...formData, entity_type: value })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="user">User</SelectItem>
                      <SelectItem value="provider">Provider</SelectItem>
                      <SelectItem value="booking">Booking</SelectItem>
                      <SelectItem value="service">Service</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div>
                <Label htmlFor="placeholder">Placeholder</Label>
                <Input
                  id="placeholder"
                  value={formData.placeholder}
                  onChange={(e) => setFormData({ ...formData, placeholder: e.target.value })}
                  placeholder="Enter placeholder text"
                />
              </div>

              <div>
                <Label htmlFor="help_text">Help Text</Label>
                <Textarea
                  id="help_text"
                  value={formData.help_text}
                  onChange={(e) => setFormData({ ...formData, help_text: e.target.value })}
                  placeholder="Additional information to help users"
                  rows={2}
                />
              </div>

              <div>
                <Label htmlFor="default_value">Default Value</Label>
                <Input
                  id="default_value"
                  value={formData.default_value}
                  onChange={(e) => setFormData({ ...formData, default_value: e.target.value })}
                  placeholder="Default value for this field"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="display_order">Display Order</Label>
                  <Input
                    id="display_order"
                    type="number"
                    value={formData.display_order}
                    onChange={(e) => setFormData({ ...formData, display_order: parseInt(e.target.value) || 0 })}
                  />
                </div>
              </div>

              <div className="flex items-center gap-4">
                <div className="flex items-center gap-2">
                  <Switch
                    id="is_required"
                    checked={formData.is_required}
                    onCheckedChange={(checked) => setFormData({ ...formData, is_required: checked })}
                  />
                  <Label htmlFor="is_required">Required Field</Label>
                </div>
                <div className="flex items-center gap-2">
                  <Switch
                    id="is_active"
                    checked={formData.is_active}
                    onCheckedChange={(checked) => setFormData({ ...formData, is_active: checked })}
                  />
                  <Label htmlFor="is_active">Active</Label>
                </div>
              </div>
            </div>
            <DialogFooter>
              <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
                Cancel
              </Button>
              <Button
                onClick={handleSubmit}
                disabled={!formData.name || !formData.label}
                className="bg-[#FF0077] hover:bg-[#D60565]"
              >
                {editingField ? "Update" : "Create"}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Search, AlertCircle } from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import { AdminFilterBar } from "@/components/admin/AdminFilterBar";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

interface Dispute {
  id: string;
  booking_id: string;
  reason: string;
  description: string | null;
  opened_by: "customer" | "provider" | "admin";
  status: "open" | "resolved" | "closed";
  opened_at: string;
  resolved_at: string | null;
  resolution: "refund_full" | "refund_partial" | "deny" | null;
  refund_amount: number | null;
  notes: string | null;
  booking: {
    id: string;
    booking_number: string;
    status: string;
    total_amount: number;
    customer: { id: string; full_name: string | null; email: string };
    provider: { id: string; business_name: string; owner_name: string | null };
  };
}

export default function AdminDisputes() {
  const [disputes, setDisputes] = useState<Dispute[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [selectedDispute, setSelectedDispute] = useState<Dispute | null>(null);
  const [showResolveDialog, setShowResolveDialog] = useState(false);
  const [resolution, setResolution] = useState<"refund_full" | "refund_partial" | "deny">("deny");
  const [refundAmount, setRefundAmount] = useState("");
  const [notes, setNotes] = useState("");

  useEffect(() => {
    loadDisputes();
  }, [statusFilter]); // eslint-disable-line react-hooks/exhaustive-deps -- load when filter changes

  const loadDisputes = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      if (statusFilter !== "all") params.set("status", statusFilter);

      const response = await fetcher.get<{
        data?: { disputes?: Dispute[]; statistics?: any; pagination?: any };
      }>(`/api/admin/disputes?${params.toString()}`);

      setDisputes(response.data?.disputes ?? []);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load disputes";
      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleResolve = async () => {
    if (!selectedDispute) return;

    try {
      const updateData: any = {
        status: "resolved",
        resolution,
        notes,
      };

      if (resolution === "refund_full" && selectedDispute.booking?.total_amount != null) {
        updateData.refund_amount = selectedDispute.booking.total_amount;
      } else if (resolution === "refund_partial") {
        const amount = parseFloat(refundAmount);
        if (!Number.isNaN(amount)) updateData.refund_amount = amount;
      }

      await fetcher.patch(`/api/admin/disputes/${selectedDispute.id}`, updateData);

      toast.success("Dispute resolved successfully");
      setShowResolveDialog(false);
      setSelectedDispute(null);
      setNotes("");
      setRefundAmount("");
      loadDisputes();
    } catch (err) {
      toast.error(err instanceof FetchError ? err.message : "Failed to resolve dispute");
    }
  };

  const filteredDisputes = disputes.filter((dispute) => {
    const matchesSearch =
      (dispute.booking?.booking_number ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (dispute.booking?.customer?.full_name ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (dispute.booking?.customer?.email ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (dispute.booking?.provider?.business_name ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (dispute.reason ?? "").toLowerCase().includes(searchQuery.toLowerCase());
    return matchesSearch;
  });

  const groupedDisputes = {
    all: filteredDisputes,
    open: filteredDisputes.filter((d) => d.status === "open"),
    resolved: filteredDisputes.filter((d) => d.status === "resolved"),
    closed: filteredDisputes.filter((d) => d.status === "closed"),
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading disputes..." />
      </div>
    );
  }

  if (error) {
    return (
      <div className="container mx-auto px-4 py-8">
        <EmptyState
          title="Failed to load disputes"
          description={error}
          action={{
            label: "Retry",
            onClick: loadDisputes,
          }}
        />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="space-y-6">
        <AdminPageHeader
          title="Disputes & Support"
          description="Manage booking disputes and support tickets"
        />

        <AdminFilterBar>
          <div className="flex flex-col md:flex-row gap-4">
            <div className="flex-1">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                <Input
                  type="text"
                  placeholder="Search by booking number, customer, provider, or reason..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-10"
                />
              </div>
            </div>
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg"
            >
              <option value="all">All Status</option>
              <option value="open">Open</option>
              <option value="resolved">Resolved</option>
              <option value="closed">Closed</option>
            </select>
          </div>
        </AdminFilterBar>

        {/* Disputes List */}
        <Tabs defaultValue="all" className="space-y-4">
          <TabsList>
            <TabsTrigger value="all">All ({groupedDisputes.all.length})</TabsTrigger>
            <TabsTrigger value="open">Open ({groupedDisputes.open.length})</TabsTrigger>
            <TabsTrigger value="resolved">Resolved ({groupedDisputes.resolved.length})</TabsTrigger>
            <TabsTrigger value="closed">Closed ({groupedDisputes.closed.length})</TabsTrigger>
          </TabsList>

          <TabsContent value="all" className="space-y-4">
            <DisputeList
              disputes={groupedDisputes.all}
              onResolve={(dispute) => {
                setSelectedDispute(dispute);
                setShowResolveDialog(true);
              }}
            />
          </TabsContent>
          <TabsContent value="open" className="space-y-4">
            <DisputeList
              disputes={groupedDisputes.open}
              onResolve={(dispute) => {
                setSelectedDispute(dispute);
                setShowResolveDialog(true);
              }}
            />
          </TabsContent>
          <TabsContent value="resolved" className="space-y-4">
            <DisputeList disputes={groupedDisputes.resolved} onResolve={() => {}} />
          </TabsContent>
          <TabsContent value="closed" className="space-y-4">
            <DisputeList disputes={groupedDisputes.closed} onResolve={() => {}} />
          </TabsContent>
        </Tabs>

        {/* Resolve Dialog */}
        <Dialog open={showResolveDialog} onOpenChange={setShowResolveDialog}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Resolve Dispute</DialogTitle>
              <DialogDescription>
                Choose a resolution for this dispute and add any notes.
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4">
              <div>
                <Label>Resolution</Label>
                <Select value={resolution} onValueChange={(v: any) => setResolution(v)}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="refund_full">Full Refund</SelectItem>
                    <SelectItem value="refund_partial">Partial Refund</SelectItem>
                    <SelectItem value="deny">Deny</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              {resolution === "refund_partial" && (
                <div>
                  <Label>Refund Amount</Label>
                  <Input
                    type="number"
                    value={refundAmount}
                    onChange={(e) => setRefundAmount(e.target.value)}
                    placeholder="Enter refund amount"
                    max={selectedDispute?.booking?.total_amount ?? undefined}
                  />
                </div>
              )}
              <div>
                <Label>Notes</Label>
                <Textarea
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  placeholder="Add resolution notes..."
                  rows={4}
                />
              </div>
              <div className="flex justify-end gap-2">
                <Button variant="outline" onClick={() => setShowResolveDialog(false)}>
                  Cancel
                </Button>
                <Button onClick={handleResolve}>Resolve</Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      </div>
    </RoleGuard>
  );
}

function DisputeList({
  disputes,
  onResolve,
}: {
  disputes: Dispute[];
  onResolve: (dispute: Dispute) => void;
}) {
  if (disputes.length === 0) {
    return (
      <div className="bg-white p-8 rounded-lg border border-gray-200 text-center">
        <AlertCircle className="w-12 h-12 text-gray-400 mx-auto mb-4" />
        <p className="text-gray-600">No disputes found</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {disputes.map((dispute) => (
        <div key={dispute.id} className="bg-white p-6 rounded-lg border border-gray-200">
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <div className="flex items-center gap-3 mb-2">
                <Badge
                  variant={
                    dispute.status === "open"
                      ? "destructive"
                      : dispute.status === "resolved"
                      ? "default"
                      : "secondary"
                  }
                >
                  {dispute.status}
                </Badge>
                <Badge variant="outline">Opened by: {dispute.opened_by}</Badge>
                {dispute.resolution && (
                  <Badge variant="outline">Resolution: {dispute.resolution}</Badge>
                )}
              </div>
              <h3 className="font-semibold text-gray-900 mb-1">{dispute.reason}</h3>
              {dispute.description && (
                <p className="text-gray-600 mb-3">{dispute.description}</p>
              )}
              <div className="flex items-center gap-4 text-sm text-gray-600">
                <span>
                  <strong>Booking:</strong> {dispute.booking?.booking_number}
                </span>
                <span>
                  <strong>Amount:</strong> ${dispute.booking?.total_amount?.toFixed(2)}
                </span>
                <span>
                  <strong>Customer:</strong>{" "}
                  {dispute.booking?.customer?.full_name || dispute.booking?.customer?.email}
                </span>
                <span>
                  <strong>Provider:</strong> {dispute.booking?.provider?.business_name}
                </span>
                <span>
                  <strong>Opened:</strong> {new Date(dispute.opened_at).toLocaleDateString()}
                </span>
              </div>
              {dispute.refund_amount && (
                <div className="mt-2 text-sm">
                  <strong>Refund Amount:</strong> ${dispute.refund_amount.toFixed(2)}
                </div>
              )}
              {dispute.notes && (
                <div className="mt-2 p-2 bg-gray-50 border border-gray-200 rounded text-sm">
                  <strong>Notes:</strong> {dispute.notes}
                </div>
              )}
            </div>
            {dispute.status === "open" && (
              <Button onClick={() => onResolve(dispute)}>Resolve</Button>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Settings,
  Edit,
  CheckCircle,
  XCircle,
  Plus,
  Info,
} from "lucide-react";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";

interface FeeConfig {
  id: string;
  gateway_name: string;
  fee_type: "percentage" | "fixed" | "tiered";
  fee_percentage: number;
  fee_fixed_amount: number;
  fee_tiered_config: any;
  currency: string;
  is_active: boolean;
  effective_from: string;
  effective_until: string | null;
  description: string | null;
}

interface FeeAdjustment {
  id: string;
  payment_transaction_id: string | null;
  finance_transaction_id: string | null;
  original_fee_amount: number;
  adjusted_fee_amount: number;
  adjustment_reason: string;
  adjustment_type: string;
  notes: string | null;
  reconciled: boolean;
  created_at: string;
  payment_transaction?: {
    id: string;
    reference: string;
    amount: number;
    fees: number;
    provider: string;
  };
  finance_transaction?: {
    id: string;
    transaction_type: string;
    amount: number;
    fees: number;
  };
}

interface Reconciliation {
  id: string;
  reconciliation_date: string;
  gateway_name: string;
  expected_fees: number;
  actual_fees: number;
  variance: number;
  status: "pending" | "reviewed" | "resolved" | "disputed";
  notes: string | null;
  statement_reference: string | null;
  created_at: string;
}

export default function AdminFees() {
  const [activeTab, setActiveTab] = useState("configs");

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="container mx-auto px-3 sm:px-4 py-4 sm:py-8">
        <div className="mb-4 sm:mb-6">
          <div className="flex items-start gap-2 mb-2">
            <h1 className="text-2xl sm:text-3xl font-semibold">Fee Management</h1>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="ghost" size="icon" className="mt-1 text-gray-400 hover:text-gray-600">
                  <Info className="w-5 h-5" />
                </Button>
              </PopoverTrigger>
          <PopoverContent className="w-80 sm:w-96 max-h-[80vh] overflow-y-auto">
              <div className="space-y-3">
                <h3 className="font-semibold text-sm">About Fee Management</h3>
                <p className="text-xs text-gray-600">
                  This section helps you manage payment gateway fees across your platform. Payment gateways 
                  (like Paystack, Stripe, etc.) charge fees on each transaction. This system helps you:
                </p>
                <ul className="text-xs text-gray-600 list-disc list-inside space-y-1 mt-2">
                  <li><strong>Configure</strong> expected fee rates for each gateway</li>
                  <li><strong>Adjust</strong> fees when discrepancies occur</li>
                  <li><strong>Reconcile</strong> expected vs actual fees from gateway statements</li>
                </ul>
                
                <div className="border-t pt-2 mt-2">
                  <h4 className="font-medium text-xs mb-1">How Fees Affect Revenue:</h4>
                  <div className="text-xs text-gray-600 space-y-1">
                    <p><strong>Gross Revenue:</strong> Total amount customers pay</p>
                    <p><strong>Gateway Fees:</strong> Deducted from platform revenue (not provider earnings)</p>
                    <p><strong>Net Revenue:</strong> Gross - Gateway Fees</p>
                    <p><strong>Platform Take:</strong> Commission - Gateway Fees</p>
                    <p className="text-gray-500 italic mt-1">
                      Gateway fees reduce your platform revenue, not the provider's share. 
                      Accurate fee tracking ensures correct revenue calculations.
                    </p>
                  </div>
                </div>
              </div>
            </PopoverContent>
            </Popover>
          </div>
          <p className="text-sm sm:text-base text-gray-600">
            Configure payment gateway fees, adjust fees, and reconcile fee discrepancies
          </p>
        </div>

        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList className="mb-4 sm:mb-6 flex-wrap">
            <TabsTrigger value="configs" className="text-xs sm:text-sm">
              <Settings className="w-3 h-3 sm:w-4 sm:h-4 mr-1 sm:mr-2" />
              <span className="hidden sm:inline">Fee Configurations</span>
              <span className="sm:hidden">Configs</span>
            </TabsTrigger>
            <TabsTrigger value="adjustments" className="text-xs sm:text-sm">
              <Edit className="w-3 h-3 sm:w-4 sm:h-4 mr-1 sm:mr-2" />
              <span className="hidden sm:inline">Fee Adjustments</span>
              <span className="sm:hidden">Adjustments</span>
            </TabsTrigger>
            <TabsTrigger value="reconciliations" className="text-xs sm:text-sm">
              <CheckCircle className="w-3 h-3 sm:w-4 sm:h-4 mr-1 sm:mr-2" />
              <span className="hidden sm:inline">Reconciliations</span>
              <span className="sm:hidden">Reconcile</span>
            </TabsTrigger>
          </TabsList>

          <TabsContent value="configs">
            <FeeConfigsTab />
          </TabsContent>

          <TabsContent value="adjustments">
            <FeeAdjustmentsTab />
          </TabsContent>

          <TabsContent value="reconciliations">
            <ReconciliationsTab />
          </TabsContent>
        </Tabs>
      </div>
    </RoleGuard>
  );
}

function FeeConfigsTab() {
  const [configs, setConfigs] = useState<FeeConfig[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [editingConfig, setEditingConfig] = useState<FeeConfig | null>(null);

  useEffect(() => {
    loadConfigs();
  }, []);

  const loadConfigs = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const response = await fetcher.get<{ data: FeeConfig[] }>(
        "/api/admin/fees/configs?active_only=false"
      );
      setConfigs(response.data || []);
    } catch (err) {
      const errorMessage =
        err instanceof FetchError
          ? err.message
          : "Failed to load fee configurations";
      setError(errorMessage);
      console.error("Error loading configs:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async (configData: Partial<FeeConfig>) => {
    try {
      if (editingConfig) {
        await fetcher.patch("/api/admin/fees/configs", {
          id: editingConfig.id,
          ...configData,
        });
        toast.success("Fee configuration updated");
      } else {
        await fetcher.post("/api/admin/fees/configs", configData);
        toast.success("Fee configuration created");
      }
      setShowModal(false);
      setEditingConfig(null);
      loadConfigs();
    } catch (err) {
      toast.error("Failed to save fee configuration");
      console.error("Error saving config:", err);
    }
  };

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading fee configurations..." />;
  }

  if (error) {
    return (
      <EmptyState
        title="Failed to load configurations"
        description={error}
        action={{ label: "Retry", onClick: loadConfigs }}
      />
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-2">
          <h2 className="text-lg font-semibold">Payment Gateway Fee Configurations</h2>
          <Popover>
            <PopoverTrigger asChild>
              <Button variant="ghost" size="icon" className="text-gray-400 hover:text-gray-600">
                <Info className="w-4 h-4" />
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-80 sm:w-96">
              <div className="space-y-2">
                <h3 className="font-semibold text-sm">Fee Configurations</h3>
                <p className="text-xs text-gray-600">
                  Configure the expected fee structure for each payment gateway. These configurations 
                  determine how fees are calculated for transactions.
                </p>
                <div className="mt-3 space-y-2">
                  <div>
                    <strong className="text-xs">Percentage Fees:</strong>
                    <p className="text-xs text-gray-600">
                      Fee is calculated as a percentage of the transaction amount (e.g., 1.5% = 0.015)
                    </p>
                  </div>
                  <div>
                    <strong className="text-xs">Fixed Fees:</strong>
                    <p className="text-xs text-gray-600">
                      A fixed amount charged per transaction regardless of transaction size
                    </p>
                  </div>
                  <div>
                    <strong className="text-xs">Tiered Fees:</strong>
                    <p className="text-xs text-gray-600">
                      Different fee rates based on transaction amount tiers (advanced configuration)
                    </p>
                  </div>
                </div>
                <p className="text-xs text-gray-600 mt-2">
                  <strong>Tip:</strong> Set effective dates to manage fee changes over time. Only one 
                  active configuration per gateway/currency combination is used at a time.
                </p>
              </div>
            </PopoverContent>
          </Popover>
        </div>
        <Button onClick={() => {
          setEditingConfig(null);
          setShowModal(true);
        }}>
          <Plus className="w-4 h-4 mr-2" />
          Add Configuration
        </Button>
      </div>

      <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 mb-4">
        <div className="flex items-start gap-2">
          <Info className="w-4 h-4 text-blue-600 mt-0.5 flex-shrink-0" />
          <div className="text-xs text-blue-800">
            <p className="font-medium mb-1">Quick Guide:</p>
            <ul className="list-disc list-inside space-y-0.5">
              <li>Each gateway can have multiple configurations with different effective dates</li>
              <li>Only one active configuration per gateway/currency is used at a time</li>
              <li>Set "Effective Until" to automatically expire old configurations</li>
              <li>Use descriptions to document why a configuration was created</li>
            </ul>
          </div>
        </div>
      </div>

      <div className="bg-white border rounded-lg overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-50 border-b">
              <tr>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                  <div className="flex items-center gap-1">
                    Gateway
                    <Popover>
                      <PopoverTrigger asChild>
                        <Button variant="ghost" size="icon" className="text-gray-400 hover:text-gray-600">
                          <Info className="w-3 h-3" />
                        </Button>
                      </PopoverTrigger>
                      <PopoverContent className="w-64">
                        <p className="text-xs text-gray-600">
                          The payment gateway provider (e.g., Paystack, Stripe, Yoco). Each gateway 
                          can have separate fee configurations.
                        </p>
                      </PopoverContent>
                    </Popover>
                  </div>
                </th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Type</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Fee</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Currency</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Effective From</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {configs.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-4 py-8 text-center text-gray-500">
                    No fee configurations found
                  </td>
                </tr>
              ) : (
                configs.map((config) => (
                  <tr key={config.id} className="hover:bg-gray-50">
                    <td className="px-4 py-4 text-sm font-medium">{config.gateway_name}</td>
                    <td className="px-4 py-4 text-sm capitalize">{config.fee_type}</td>
                    <td className="px-4 py-4 text-sm">
                      {config.fee_type === "percentage"
                        ? `${(config.fee_percentage * 100).toFixed(2)}%`
                        : `ZAR ${config.fee_fixed_amount.toFixed(2)}`}
                    </td>
                    <td className="px-4 py-4 text-sm">{config.currency}</td>
                    <td className="px-4 py-4 text-sm">
                      {config.is_active ? (
                        <span className="text-green-600">Active</span>
                      ) : (
                        <span className="text-gray-400">Inactive</span>
                      )}
                    </td>
                    <td className="px-4 py-4 text-sm">
                      {new Date(config.effective_from).toLocaleDateString()}
                    </td>
                    <td className="px-4 py-4 text-sm">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => {
                          setEditingConfig(config);
                          setShowModal(true);
                        }}
                      >
                        <Edit className="w-3 h-3 mr-1" />
                        Edit
                      </Button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {showModal && (
        <FeeConfigModal
          config={editingConfig}
          onClose={() => {
            setShowModal(false);
            setEditingConfig(null);
          }}
          onSave={handleSave}
        />
      )}
    </div>
  );
}

function FeeConfigModal({
  config,
  onClose,
  onSave,
}: {
  config: FeeConfig | null;
  onClose: () => void;
  onSave: (data: Partial<FeeConfig>) => void;
}) {
  const [formData, setFormData] = useState({
    gateway_name: config?.gateway_name || "",
    fee_type: config?.fee_type || "percentage",
    fee_percentage: config?.fee_percentage || 0,
    fee_fixed_amount: config?.fee_fixed_amount || 0,
    currency: config?.currency || "ZAR",
    is_active: config?.is_active !== false,
    effective_from: config?.effective_from
      ? new Date(config.effective_from).toISOString().split("T")[0]
      : new Date().toISOString().split("T")[0],
    effective_until: config?.effective_until
      ? new Date(config.effective_until).toISOString().split("T")[0]
      : "",
    description: config?.description || "",
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(formData);
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
        <div className="p-6">
          <h2 className="text-xl font-semibold mb-4">
            {config ? "Edit" : "Create"} Fee Configuration
          </h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <Label htmlFor="gateway_name">Gateway Name *</Label>
              <Input
                id="gateway_name"
                value={formData.gateway_name}
                onChange={(e) =>
                  setFormData({ ...formData, gateway_name: e.target.value })
                }
                required
                placeholder="paystack, stripe, yoco"
              />
            </div>

            <div>
              <div className="flex items-center gap-2 mb-1">
                <Label htmlFor="fee_type">Fee Type *</Label>
                <Popover>
                  <PopoverTrigger asChild>
                    <Button variant="ghost" size="icon" type="button" className="text-gray-400 hover:text-gray-600">
                      <Info className="w-3 h-3" />
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-72">
                    <div className="space-y-2">
                      <h4 className="font-semibold text-xs">Fee Type Options</h4>
                      <div className="text-xs text-gray-600 space-y-1">
                        <p><strong>Percentage:</strong> Fee calculated as % of transaction (e.g., 1.5% = 0.015)</p>
                        <p><strong>Fixed:</strong> Same fee amount regardless of transaction size</p>
                        <p><strong>Tiered:</strong> Different rates based on transaction amount ranges</p>
                      </div>
                    </div>
                  </PopoverContent>
                </Popover>
              </div>
              <select
                id="fee_type"
                value={formData.fee_type}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    fee_type: e.target.value as "percentage" | "fixed" | "tiered",
                  })
                }
                className="w-full p-2 border rounded-md"
                required
              >
                <option value="percentage">Percentage</option>
                <option value="fixed">Fixed Amount</option>
                <option value="tiered">Tiered</option>
              </select>
            </div>

            {formData.fee_type === "percentage" && (
              <div>
                <div className="flex items-center gap-2 mb-1">
                  <Label htmlFor="fee_percentage">Fee Percentage *</Label>
                  <Popover>
                    <PopoverTrigger asChild>
                      <Button variant="ghost" size="icon" type="button" className="text-gray-400 hover:text-gray-600">
                        <Info className="w-3 h-3" />
                      </Button>
                    </PopoverTrigger>
                    <PopoverContent className="w-72">
                      <div className="space-y-2">
                        <h4 className="font-semibold text-xs">Percentage Fee</h4>
                        <p className="text-xs text-gray-600">
                          Enter as a decimal (e.g., 0.015 for 1.5%). The system will calculate the fee 
                          by multiplying this percentage by the transaction amount.
                        </p>
                        <p className="text-xs text-gray-600 mt-2">
                          <strong>Example:</strong> For a 1.5% fee on a R100 transaction, enter 0.015, 
                          which results in a R1.50 fee.
                        </p>
                      </div>
                    </PopoverContent>
                  </Popover>
                </div>
                <div className="flex items-center gap-2">
                  <Input
                    id="fee_percentage"
                    type="number"
                    step="0.0001"
                    min="0"
                    max="1"
                    value={formData.fee_percentage}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        fee_percentage: parseFloat(e.target.value) || 0,
                      })
                    }
                    required
                  />
                  <span className="text-sm text-gray-600">
                    ({(formData.fee_percentage * 100).toFixed(4)}%)
                  </span>
                </div>
              </div>
            )}

            {formData.fee_type === "fixed" && (
              <div>
                <div className="flex items-center gap-2 mb-1">
                  <Label htmlFor="fee_fixed_amount">Fixed Fee Amount *</Label>
                  <Popover>
                    <PopoverTrigger asChild>
                      <Button variant="ghost" size="icon" type="button" className="text-gray-400 hover:text-gray-600">
                        <Info className="w-3 h-3" />
                      </Button>
                    </PopoverTrigger>
                    <PopoverContent className="w-72">
                      <div className="space-y-2">
                        <h4 className="font-semibold text-xs">Fixed Fee</h4>
                        <p className="text-xs text-gray-600">
                          Enter the exact fee amount that will be charged per transaction, regardless 
                          of the transaction size. This is useful when gateways charge a flat fee.
                        </p>
                        <p className="text-xs text-gray-600 mt-2">
                          <strong>Example:</strong> If the gateway charges R2.50 per transaction, 
                          enter 2.50 here.
                        </p>
                      </div>
                    </PopoverContent>
                  </Popover>
                </div>
                <Input
                  id="fee_fixed_amount"
                  type="number"
                  step="0.01"
                  min="0"
                  value={formData.fee_fixed_amount}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      fee_fixed_amount: parseFloat(e.target.value) || 0,
                    })
                  }
                  required
                />
              </div>
            )}

            <div>
              <Label htmlFor="currency">Currency *</Label>
              <Input
                id="currency"
