                      </p>
                    </div>
                  </PopoverContent>
                </Popover>
              </div>
              <Input
                id="effective_from"
                type="date"
                value={formData.effective_from}
                onChange={(e) =>
                  setFormData({ ...formData, effective_from: e.target.value })
