                          more than expected. Negative (red) means you paid less. Zero variance means 
                          perfect alignment.
                        </p>
                      </PopoverContent>
                    </Popover>
                  </div>
                </th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Reference</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {reconciliations.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-4 py-8 text-center text-gray-500">
                    No reconciliations found
                  </td>
                </tr>
              ) : (
                reconciliations.map((rec) => (
                  <tr key={rec.id} className="hover:bg-gray-50">
                    <td className="px-4 py-4 text-sm">
                      {new Date(rec.reconciliation_date).toLocaleDateString()}
                    </td>
                    <td className="px-4 py-4 text-sm font-medium">
                      {rec.gateway_name}
                    </td>
                    <td className="px-4 py-4 text-sm">
                      ZAR {rec.expected_fees.toFixed(2)}
                    </td>
                    <td className="px-4 py-4 text-sm">
                      ZAR {rec.actual_fees.toFixed(2)}
                    </td>
                    <td
                      className={`px-4 py-4 text-sm font-medium ${
                        rec.variance >= 0 ? "text-green-600" : "text-red-600"
                      }`}
                    >
                      {rec.variance >= 0 ? "+" : ""}
                      {rec.variance.toFixed(2)}
                    </td>
                    <td className="px-4 py-4 text-sm">
                      <span
                        className={`px-2 py-1 rounded text-xs ${
                          rec.status === "resolved"
                            ? "bg-green-100 text-green-800"
                            : rec.status === "pending"
                            ? "bg-yellow-100 text-yellow-800"
                            : rec.status === "disputed"
                            ? "bg-red-100 text-red-800"
                            : "bg-blue-100 text-blue-800"
                        }`}
                      >
                        {rec.status}
                      </span>
                    </td>
                    <td className="px-4 py-4 text-sm">
                      {rec.statement_reference || "N/A"}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {total > limit && (
          <div className="px-4 py-3 border-t flex justify-between items-center">
            <div className="text-sm text-gray-700">
              Showing {((page - 1) * limit) + 1} to {Math.min(page * limit, total)} of {total}
            </div>
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                disabled={page === 1}
              >
                Previous
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setPage((p) => p + 1)}
                disabled={total <= page * limit}
              >
                Next
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

