type ProviderBadge = {
  id: string;
  name: string;
  slug: string;
  description: string | null;
  icon_url: string | null;
  tier: number;
  color: string | null;
  requirements: Record<string, number>;
  benefits: Record<string, any>;
  is_active: boolean;
  display_order: number;
  created_at?: string;
  updated_at?: string;
};

const defaultRequirements = {
  points: 0,
  min_rating: 0,
  min_reviews: 0,
  min_bookings: 0,
};

const defaultBenefits: Record<string, any> = {};

function slugFromName(name: string): string {
  return name
    .toLowerCase()
    .trim()
    .replace(/\s+/g, "-")
    .replace(/[^a-z0-9-]/g, "");
}

export default function AdminProviderBadgesPage() {
  const [badges, setBadges] = useState<ProviderBadge[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [includeInactive, setIncludeInactive] = useState(false);
  const [isRecalculating, setIsRecalculating] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [form, setForm] = useState({
    name: "",
    slug: "",
    description: "",
    icon_url: "",
    tier: 1,
    color: "#6b7280",
    requirements: { ...defaultRequirements },
    benefitsJson: "{}",
    is_active: true,
    display_order: 0,
  });

  const loadBadges = useCallback(async () => {
    try {
      setIsLoading(true);
      const url = includeInactive
        ? "/api/admin/gamification/badges?include_inactive=true"
        : "/api/admin/gamification/badges";
      const res = await fetcher.get<{ data: { badges: ProviderBadge[] }; badges?: ProviderBadge[] }>(url);
      const list = (res as { data?: { badges?: ProviderBadge[] }; badges?: ProviderBadge[] }).data?.badges
        ?? (res as { badges?: ProviderBadge[] }).badges
        ?? [];
      setBadges(Array.isArray(list) ? list : []);
    } catch {
      toast.error("Failed to load badges");
    } finally {
      setIsLoading(false);
    }
  }, [includeInactive]);

  useEffect(() => {
    loadBadges();
  }, [loadBadges]);

  const openCreate = () => {
    setEditingId(null);
    setForm({
      name: "",
      slug: "",
      description: "",
      icon_url: "",
      tier: 1,
      color: "#6b7280",
      requirements: { ...defaultRequirements },
      benefitsJson: "{}",
      is_active: true,
      display_order: 0,
    });
    setDialogOpen(true);
  };

  const openEdit = (badge: ProviderBadge) => {
    setEditingId(badge.id);
    const req = badge.requirements && typeof badge.requirements === "object"
      ? {
          points: Number((badge.requirements as Record<string, any>).points) || 0,
          min_rating: Number((badge.requirements as Record<string, any>).min_rating) || 0,
          min_reviews: Number((badge.requirements as Record<string, any>).min_reviews) || 0,
          min_bookings: Number((badge.requirements as Record<string, any>).min_bookings) || 0,
        }
      : { ...defaultRequirements };
    setForm({
      name: badge.name,
      slug: badge.slug,
      description: badge.description ?? "",
      icon_url: badge.icon_url ?? "",
      tier: badge.tier,
      color: badge.color ?? "#6b7280",
      requirements: req,
      benefitsJson: JSON.stringify(badge.benefits ?? {}, null, 2),
      is_active: badge.is_active,
      display_order: badge.display_order ?? 0,
    });
    setDialogOpen(true);
  };

  const updateForm = (updates: Partial<typeof form>) => {
    setForm((prev) => ({ ...prev, ...updates }));
    if ("name" in updates && updates.name !== undefined && !editingId) {
      setForm((prev) => ({ ...prev, slug: slugFromName(updates.name) || prev.slug }));
    }
  };

  const updateRequirement = (key: keyof typeof defaultRequirements, value: number) => {
    setForm((prev) => ({
      ...prev,
      requirements: { ...prev.requirements, [key]: value },
    }));
  };

  const handleSave = async () => {
    if (!form.name.trim() || !form.slug.trim() || !form.color.trim()) {
      toast.error("Name, slug and color are required");
      return;
    }
    let benefits: Record<string, any>;
    try {
      benefits = JSON.parse(form.benefitsJson || "{}");
    } catch {
      toast.error("Benefits must be valid JSON");
      return;
    }
    const requirements = {
      points: Number(form.requirements.points) || 0,
      min_rating: Number(form.requirements.min_rating) || 0,
      min_reviews: Number(form.requirements.min_reviews) || 0,
      min_bookings: Number(form.requirements.min_bookings) || 0,
    };
    const payload = {
      name: form.name.trim(),
      slug: form.slug.trim().toLowerCase().replace(/\s+/g, "-"),
      description: form.description.trim() || null,
      icon_url: form.icon_url.trim() || null,
      tier: Math.min(10, Math.max(1, Number(form.tier) || 1)),
      color: form.color.trim(),
      requirements,
      benefits,
      is_active: form.is_active,
      display_order: Number(form.display_order) || 0,
    };
    try {
      setIsSaving(true);
      if (editingId) {
        await fetcher.patch(`/api/admin/gamification/badges/${editingId}`, payload);
        toast.success("Badge updated");
      } else {
        await fetcher.post("/api/admin/gamification/badges", payload);
        toast.success("Badge created");
      }
      setDialogOpen(false);
      loadBadges();
    } catch (e: any) {
      const msg = e && typeof e === "object" && "message" in e ? String((e as { message: string }).message) : "Failed to save";
      toast.error(msg);
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      setIsDeleting(true);
      await fetcher.delete(`/api/admin/gamification/badges/${deleteId}`);
      toast.success("Badge deleted");
      setDeleteId(null);
      loadBadges();
    } catch (e: any) {
      const msg = e && typeof e === "object" && "message" in e ? String((e as { message: string }).message) : "Failed to delete";
      toast.error(msg);
    } finally {
      setIsDeleting(false);
    }
  };

  const handleRecalculateAll = async () => {
    try {
      setIsRecalculating(true);
      const res = await fetcher.put<{ data?: { providers_processed?: number } }>("/api/admin/gamification/backfill/initialize");
      const count = res?.data?.providers_processed ?? 0;
      toast.success(`Recalculated badges for ${count} providers. Refresh the homepage or provider pages to see badges.`);
    } catch (e: any) {
      const msg = e && typeof e === "object" && "message" in e ? String((e as { message: string }).message) : "Failed to recalculate";
      toast.error(msg);
    } finally {
      setIsRecalculating(false);
    }
  };

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
      <div className="container max-w-6xl py-8 px-4">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
          <div className="flex items-center gap-3">
            <Medal className="w-8 h-8 text-amber-600" />
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Provider badges</h1>
              <p className="text-sm text-gray-500">
                Tier names, requirements and benefits for provider levels. Used for automatic badge assignment by points and stats.
              </p>
              <p className="text-sm text-gray-500 mt-1">
                Point earning rules:{" "}
                <Link href="/admin/gamification/point-rules" className="text-[#FF0077] hover:underline inline-flex items-center gap-1">
                  <Link2 className="w-3.5 h-3.5" />
                  Point rules
                </Link>
              </p>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-3">
            <label className="flex items-center gap-2 text-sm text-gray-600">
              <Checkbox
                checked={includeInactive}
                onCheckedChange={(c) => setIncludeInactive(!!c)}
              />
              Include inactive
            </label>
            <Button
              variant="outline"
              onClick={handleRecalculateAll}
              disabled={isRecalculating}
              title="Create or update provider_points for all active providers and assign badges from current requirements"
            >
              {isRecalculating ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Medal className="w-4 h-4 mr-2" />}
              {isRecalculating ? "RecalculatingΓÇª" : "Recalculate all badges"}
            </Button>
            <Button onClick={openCreate}>
              <Plus className="w-4 h-4 mr-2" />
              Add badge
            </Button>
          </div>
        </div>

        {isLoading ? (
          <div className="flex justify-center py-12">
            <Loader2 className="w-8 h-8 animate-spin text-gray-400" />
          </div>
        ) : badges.length === 0 ? (
          <div className="rounded-lg border border-gray-200 bg-white p-8 text-center text-gray-500">
            No badges yet. Add one to define provider tiers (e.g. Bronze, Silver, Gold).
          </div>
        ) : (
          <div className="rounded-lg border border-gray-200 bg-white overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b bg-gray-50">
                    <th className="text-left p-3 font-medium text-gray-700">Name</th>
                    <th className="text-left p-3 font-medium text-gray-700">Tier</th>
                    <th className="text-left p-3 font-medium text-gray-700">Requirements</th>
                    <th className="text-left p-3 font-medium text-gray-700">Benefits</th>
                    <th className="text-left p-3 font-medium text-gray-700">Status</th>
                    <th className="text-right p-3 font-medium text-gray-700">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {badges.map((b) => {
                    const req = (b.requirements || {}) as Record<string, any>;
                    const pts = Number(req.points) ?? 0;
                    const rating = Number(req.min_rating) ?? 0;
                    const reviews = Number(req.min_reviews) ?? 0;
                    const bookings = Number(req.min_bookings) ?? 0;
                    const benefitKeys = b.benefits && typeof b.benefits === "object" ? Object.keys(b.benefits) : [];
                    return (
                      <tr key={b.id} className="border-b last:border-0 hover:bg-gray-50/50">
                        <td className="p-3">
                          <div className="flex items-center gap-2">
                            {b.color && (
                              <span
                                className="w-4 h-4 rounded-full shrink-0 border border-gray-200"
                                style={{ backgroundColor: b.color }}
                              />
                            )}
                            <span className="font-medium text-gray-900">{b.name}</span>
                          </div>
                          <div className="text-xs text-gray-500">{b.slug}</div>
                        </td>
                        <td className="p-3">{b.tier}</td>
                        <td className="p-3 text-gray-600">
                          ptsΓëÑ{pts} ┬╖ ratingΓëÑ{rating} ┬╖ reviewsΓëÑ{reviews} ┬╖ bookingsΓëÑ{bookings}
                        </td>
                        <td className="p-3 text-gray-600">
                          {benefitKeys.length ? benefitKeys.join(", ") : "ΓÇö"}
                        </td>
                        <td className="p-3">
                          {b.is_active ? (
                            <Badge className="bg-green-100 text-green-800">Active</Badge>
                          ) : (
                            <Badge variant="secondary">Inactive</Badge>
                          )}
                        </td>
                        <td className="p-3 text-right">
                          <Button variant="ghost" size="sm" onClick={() => openEdit(b)}>
                            <Pencil className="w-4 h-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            className="text-red-600 hover:text-red-700"
                            onClick={() => setDeleteId(b.id)}
                          >
                            <Trash2 className="w-4 h-4" />
                          </Button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[95vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingId ? "Edit badge" : "Add badge"}</DialogTitle>
          </DialogHeader>
          <div className="grid gap-4 py-2">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="badge-name">Name *</Label>
                <Input
                  id="badge-name"
                  value={form.name}
                  onChange={(e) => updateForm({ name: e.target.value })}
                  placeholder="e.g. Gold"
                />
              </div>
              <div>
                <Label htmlFor="badge-slug">Slug *</Label>
                <Input
                  id="badge-slug"
                  value={form.slug}
                  onChange={(e) => updateForm({ slug: e.target.value })}
                  placeholder="e.g. gold"
                />
              </div>
            </div>
            <div>
              <Label htmlFor="badge-desc">Description</Label>
              <Textarea
                id="badge-desc"
                value={form.description}
                onChange={(e) => updateForm({ description: e.target.value })}
                placeholder="Optional description"
                rows={2}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="badge-tier">Tier (1ΓÇô10) *</Label>
                <Input
                  id="badge-tier"
                  type="number"
                  min={1}
                  max={10}
                  value={form.tier}
                  onChange={(e) => updateForm({ tier: parseInt(e.target.value, 10) || 1 })}
                />
              </div>
              <div>
                <Label htmlFor="badge-color">Color (hex) *</Label>
                <div className="flex gap-2">
                  <input
                    type="color"
                    value={form.color}
                    onChange={(e) => updateForm({ color: e.target.value })}
                    className="h-10 w-14 rounded border cursor-pointer"
                  />
                  <Input
                    id="badge-color"
                    value={form.color}
                    onChange={(e) => updateForm({ color: e.target.value })}
                    placeholder="#6b7280"
                  />
                </div>
              </div>
            </div>
            <div>
              <Label htmlFor="badge-icon">Icon URL</Label>
              <Input
                id="badge-icon"
                value={form.icon_url}
                onChange={(e) => updateForm({ icon_url: e.target.value })}
                placeholder="https://..."
              />
            </div>
            <div>
              <Label className="mb-2 block">Requirements</Label>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                <div>
                  <Label htmlFor="req-points" className="text-xs text-gray-500">Points</Label>
                  <Input
                    id="req-points"
                    type="number"
                    min={0}
                    value={form.requirements.points}
                    onChange={(e) => updateRequirement("points", parseInt(e.target.value, 10) || 0)}
                  />
                </div>
                <div>
                  <Label htmlFor="req-rating" className="text-xs text-gray-500">Min rating</Label>
                  <Input
                    id="req-rating"
                    type="number"
                    min={0}
                    max={5}
                    step={0.1}
                    value={form.requirements.min_rating}
                    onChange={(e) => updateRequirement("min_rating", parseFloat(e.target.value) || 0)}
                  />
                </div>
                <div>
                  <Label htmlFor="req-reviews" className="text-xs text-gray-500">Min reviews</Label>
                  <Input
                    id="req-reviews"
                    type="number"
                    min={0}
                    value={form.requirements.min_reviews}
                    onChange={(e) => updateRequirement("min_reviews", parseInt(e.target.value, 10) || 0)}
                  />
                </div>
                <div>
                  <Label htmlFor="req-bookings" className="text-xs text-gray-500">Min bookings</Label>
                  <Input
                    id="req-bookings"
                    type="number"
                    min={0}
                    value={form.requirements.min_bookings}
                    onChange={(e) => updateRequirement("min_bookings", parseInt(e.target.value, 10) || 0)}
                  />
                </div>
              </div>
            </div>
            <div>
              <Label htmlFor="badge-benefits">Benefits (JSON)</Label>
              <Textarea
                id="badge-benefits"
                value={form.benefitsJson}
                onChange={(e) => updateForm({ benefitsJson: e.target.value })}
                placeholder='{"featured": true, "free_subscription": false}'
                rows={3}
                className="font-mono text-sm"
              />
            </div>
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                <Checkbox
                  id="badge-active"
                  checked={form.is_active}
                  onCheckedChange={(c) => updateForm({ is_active: !!c })}
                />
                <Label htmlFor="badge-active">Active</Label>
              </div>
              <div>
                <Label htmlFor="badge-order" className="text-xs text-gray-500">Display order</Label>
                <Input
                  id="badge-order"
                  type="number"
                  min={0}
                  value={form.display_order}
                  onChange={(e) => updateForm({ display_order: parseInt(e.target.value, 10) || 0 })}
                  className="w-24"
                />
              </div>
            </div>
          </div>
          <div className="flex justify-end gap-2 pt-2">
            <Button variant="outline" onClick={() => setDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={isSaving}>
              {isSaving ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin mr-2" />
                  Saving...
                </>
              ) : editingId ? (
                "Update badge"
              ) : (
                "Create badge"
              )}
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      <AlertDialog open={!!deleteId} onOpenChange={(open) => !open && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete badge?</AlertDialogTitle>
            <AlertDialogDescription>
              This cannot be undone. If this badge is assigned to any providers, you must deactivate it instead of deleting.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              disabled={isDeleting}
              className="bg-red-600 hover:bg-red-700"
            >
              {isDeleting ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                "Delete"
              )}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </RoleGuard>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import { Award, Save, Loader2, Link2 } from "lucide-react";
import Link from "next/link";
import RoleGuard from "@/components/auth/RoleGuard";

type PointRule = {
  id: string;
  source: string;
  points: number;
  label: string;
  description: string | null;
  display_order: number;
};

export default function AdminPointRulesPage() {
  const [rules, setRules] = useState<PointRule[]>([]);
  const [editing, setEditing] = useState<Record<string, number>>({});
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  const load = async () => {
    try {
      setIsLoading(true);
      const res = await fetcher.get<{ data: { rules: PointRule[] } }>("/api/admin/gamification/point-rules");
      const list = (res as any)?.data?.rules ?? (res as any)?.rules ?? [];
      setRules(Array.isArray(list) ? list : []);
      setEditing({});
    } catch {
      toast.error("Failed to load point rules");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const handlePointsChange = (source: string, value: number) => {
    setEditing((prev) => ({ ...prev, [source]: value }));
  };

  const handleSave = async () => {
    const entries = Object.entries(editing).filter(([, points]) => typeof points === "number");
    if (entries.length === 0) {
      toast.info("No changes to save");
      return;
    }
    try {
      setIsSaving(true);
      await fetcher.patch("/api/admin/gamification/point-rules", {
        rules: entries.map(([source, points]) => ({ source, points })),
      });
      toast.success("Point rules updated");
      await load();
    } catch {
      toast.error("Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const getPoints = (r: PointRule) => (editing[r.source] !== undefined ? editing[r.source] : r.points);

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
      <div className="container max-w-3xl py-8 px-4">
        <div className="flex items-center gap-3 mb-6">
          <Award className="w-8 h-8 text-amber-600" />
          <div>
            <h1 className="text-2xl font-bold text-gray-900">Provider point rules</h1>
            <p className="text-sm text-gray-500">
              Control how many reward points providers earn for each task. Changes apply to new awards only.
            </p>
            <p className="text-sm text-gray-500 mt-1">
              For <strong>customer</strong> loyalty rules and milestone rewards, go to{" "}
              <Link href="/admin/loyalty" className="text-[#FF0077] hover:underline inline-flex items-center gap-1">
                <Link2 className="w-3.5 h-3.5" />
                Loyalty
              </Link> (Marketing &amp; comms).
            </p>
          </div>
        </div>

        {isLoading ? (
          <div className="flex justify-center py-12">
            <Loader2 className="w-8 h-8 animate-spin text-gray-400" />
          </div>
        ) : (
          <div className="space-y-4">
            {rules.map((r) => (
              <div
                key={r.id}
                className="flex flex-wrap items-center gap-4 p-4 rounded-lg border border-gray-200 bg-white"
              >
                <div className="flex-1 min-w-[200px]">
                  <p className="font-medium text-gray-900">{r.label}</p>
                  {r.description && (
                    <p className="text-sm text-gray-500 mt-0.5">{r.description}</p>
                  )}
                  <p className="text-xs text-gray-400 mt-1">Source: {r.source}</p>
                </div>
                <div className="flex items-center gap-2">
                  <Label htmlFor={`pts-${r.source}`} className="text-sm whitespace-nowrap">
                    Points
                  </Label>
                  <Input
                    id={`pts-${r.source}`}
                    type="number"
                    min={0}
                    value={getPoints(r)}
                    onChange={(e) => handlePointsChange(r.source, parseInt(e.target.value, 10) || 0)}
                    className="w-24"
                  />
                </div>
              </div>
            ))}
            <div className="pt-4 flex justify-end">
              <Button onClick={handleSave} disabled={isSaving || Object.keys(editing).length === 0}>
                {isSaving ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin mr-2" />
                    Saving...
                  </>
                ) : (
                  <>
                    <Save className="w-4 h-4 mr-2" />
                    Save changes
                  </>
                )}
              </Button>
            </div>
          </div>
        )}
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Plus, Edit, Trash2, Search, Gift, Eye, Copy } from "lucide-react";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import { AdminFilterBar } from "@/components/admin/AdminFilterBar";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

interface GiftCard {
  id: string;
  code: string;
  currency: string;
  initial_balance: number;
  balance: number;
  is_active: boolean;
  expires_at: string | null;
  created_at: string;
  updated_at: string;
  metadata?: any;
}

export default function AdminGiftCards() {
  const [giftCards, setGiftCards] = useState<GiftCard[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isViewDialogOpen, setIsViewDialogOpen] = useState(false);
  const [viewingCard, setViewingCard] = useState<GiftCard | null>(null);
  const [editingCard, setEditingCard] = useState<GiftCard | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [formData, setFormData] = useState({
    code: "",
    initial_balance: "",
    currency: "ZAR",
    expires_at: "",
    metadata: "{}",
  });

  useEffect(() => {
    loadGiftCards();
  }, [statusFilter]); // eslint-disable-line react-hooks/exhaustive-deps -- load when filter changes

  const loadGiftCards = async () => {
    try {
      setIsLoading(true);
      const params = new URLSearchParams();
      if (searchQuery) params.set("search", searchQuery);
      if (statusFilter !== "all") params.set("status", statusFilter);

      const response = await fetcher.get<{
        data: {
          gift_cards: GiftCard[];
          meta: { total: number; page: number; limit: number; has_more: boolean };
        };
      }>(`/api/admin/gift-cards?${params.toString()}`);
      setGiftCards(response.data?.gift_cards ?? []);
    } catch (error) {
      console.error("Failed to load gift cards:", error);
      toast.error("Failed to load gift cards");
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreate = () => {
    setEditingCard(null);
    setFormData({
      code: "",
      initial_balance: "",
      currency: "ZAR",
      expires_at: "",
      metadata: "{}",
    });
    setIsDialogOpen(true);
  };

  const handleEdit = (card: GiftCard) => {
    setEditingCard(card);
    setFormData({
      code: card.code,
      initial_balance: card.balance.toString(),
      currency: card.currency,
      expires_at: card.expires_at ? new Date(card.expires_at).toISOString().split("T")[0] : "",
      metadata: JSON.stringify(card.metadata || {}, null, 2),
    });
    setIsDialogOpen(true);
  };

  const handleView = async (card: GiftCard) => {
    try {
      const response = await fetcher.get<{ data: { gift_card: GiftCard & { redemptions?: any[] } } }>(
        `/api/admin/gift-cards/${card.id}`
      );
      setViewingCard(response.data?.gift_card ?? null);
      setIsViewDialogOpen(true);
    } catch (error) {
      console.error("Failed to load gift card details:", error);
      toast.error("Failed to load gift card details");
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this gift card?")) return;

    try {
      await fetcher.delete(`/api/admin/gift-cards/${id}`);
      toast.success("Gift card deleted successfully");
      loadGiftCards();
    } catch (error) {
      console.error("Failed to delete gift card:", error);
      toast.error(error instanceof FetchError ? error.message : "Failed to delete gift card");
    }
  };

  const handleSave = async () => {
    try {
      let metadataObj = {};
      try {
        metadataObj = JSON.parse(formData.metadata);
      } catch {
        toast.error("Invalid JSON in metadata field");
        return;
      }

      if (editingCard) {
        await fetcher.patch(`/api/admin/gift-cards/${editingCard.id}`, {
          balance: parseFloat(formData.initial_balance),
          expires_at: formData.expires_at || null,
          metadata: metadataObj,
        });
        toast.success("Gift card updated successfully");
      } else {
        if (!formData.code || !formData.initial_balance) {
          toast.error("Code and initial balance are required");
          return;
        }
        await fetcher.post("/api/admin/gift-cards", {
          code: formData.code,
          initial_balance: parseFloat(formData.initial_balance),
          currency: formData.currency,
          expires_at: formData.expires_at || null,
          metadata: metadataObj,
        });
        toast.success("Gift card created successfully");
      }
      setIsDialogOpen(false);
      loadGiftCards();
    } catch (error) {
      console.error("Failed to save gift card:", error);
      toast.error(error instanceof FetchError ? error.message : "Failed to save gift card");
    }
  };

  const handleCopyCode = (code: string) => {
    navigator.clipboard.writeText(code);
    toast.success("Gift card code copied to clipboard");
  };

  const formatCurrency = (amount: number, currency: string) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: currency || "ZAR",
    }).format(amount);
  };

  const getStatusBadge = (card: GiftCard) => {
    if (!card.is_active) {
      return <Badge variant="outline">Inactive</Badge>;
    }
    if (card.expires_at && new Date(card.expires_at) < new Date()) {
      return <Badge className="bg-red-100 text-red-800">Expired</Badge>;
    }
    if (card.balance === 0) {
      return <Badge className="bg-gray-100 text-gray-800">Zero Balance</Badge>;
    }
    return <Badge className="bg-green-100 text-green-800">Active</Badge>;
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading gift cards..." />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="container mx-auto px-4 py-8">
        <AdminPageHeader
          title="Gift Cards Management"
          description="Manage gift cards and view redemption history"
          actions={
            <Button onClick={handleCreate} className="bg-[#FF0077] hover:bg-[#D60565]">
              <Plus className="w-4 h-4 mr-2" />
              Create Gift Card
            </Button>
          }
        />

        <AdminFilterBar className="mb-6">
          <div className="flex gap-4 flex-col sm:flex-row">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
            <Input
              placeholder="Search by code or recipient email..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  loadGiftCards();
                }
              }}
              className="pl-10"
            />
          </div>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-48">
              <SelectValue placeholder="Filter by status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Statuses</SelectItem>
              <SelectItem value="active">Active</SelectItem>
              <SelectItem value="inactive">Inactive</SelectItem>
              <SelectItem value="expired">Expired</SelectItem>
              <SelectItem value="zero_balance">Zero Balance</SelectItem>
            </SelectContent>
          </Select>
          </div>
        </AdminFilterBar>

        {giftCards.length === 0 ? (
          <EmptyState
            icon={Gift}
            title="No gift cards found"
            description="Create your first gift card to get started"
            action={{
              label: "Create Gift Card",
              onClick: handleCreate,
            }}
          />
        ) : (
          <div className="bg-white rounded-lg shadow overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Code</TableHead>
                  <TableHead>Initial Balance</TableHead>
                  <TableHead>Current Balance</TableHead>
                  <TableHead>Currency</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Expires</TableHead>
                  <TableHead>Created</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {giftCards.map((card) => (
                  <TableRow key={card.id}>
                    <TableCell className="font-mono font-medium">
                      <div className="flex items-center gap-2">
                        {card.code}
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => handleCopyCode(card.code)}
                          className="h-7 w-7 text-gray-400 hover:text-gray-600"
                        >
                          <Copy className="w-3 h-3" />
                        </Button>
                      </div>
                    </TableCell>
                    <TableCell>{formatCurrency(card.initial_balance, card.currency)}</TableCell>
                    <TableCell>
                      <span
                        className={
                          card.balance === 0 ? "text-gray-500" : "font-semibold"
                        }
                      >
                        {formatCurrency(card.balance, card.currency)}
                      </span>
                    </TableCell>
                    <TableCell>{card.currency}</TableCell>
                    <TableCell>{getStatusBadge(card)}</TableCell>
                    <TableCell>
                      {card.expires_at
                        ? new Date(card.expires_at).toLocaleDateString()
                        : "Never"}
                    </TableCell>
                    <TableCell>
                      {new Date(card.created_at).toLocaleDateString()}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex items-center justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleView(card)}
                        >
                          <Eye className="w-4 h-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleEdit(card)}
                        >
                          <Edit className="w-4 h-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDelete(card.id)}
                          className="text-red-600 hover:text-red-700"
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}

        {/* Create/Edit Dialog */}
        <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>
                {editingCard ? "Edit Gift Card" : "Create Gift Card"}
              </DialogTitle>
              <DialogDescription>
                {editingCard
                  ? "Update gift card details"
                  : "Create a new gift card with a unique code"}
              </DialogDescription>
            </DialogHeader>

            <div className="space-y-4">
              <div>
                <Label htmlFor="code">Gift Card Code *</Label>
                <Input
                  id="code"
                  value={formData.code}
                  onChange={(e) => setFormData({ ...formData, code: e.target.value.toUpperCase() })}
                  placeholder="GIFT123456"
                  disabled={!!editingCard}
                  required
                />
                {!editingCard && (
                  <p className="text-xs text-gray-500 mt-1">
                    Code will be converted to uppercase
                  </p>
                )}
              </div>

              {!editingCard && (
                <div>
                  <Label htmlFor="initial_balance">Initial Balance *</Label>
                  <Input
                    id="initial_balance"
                    type="number"
                    step="0.01"
                    min="0"
                    value={formData.initial_balance}
                    onChange={(e) => setFormData({ ...formData, initial_balance: e.target.value })}
                    placeholder="500.00"
                    required
                  />
                </div>
              )}

              {editingCard && (
                <div>
                  <Label htmlFor="balance">Current Balance *</Label>
                  <Input
                    id="balance"
                    type="number"
                    step="0.01"
                    min="0"
                    value={formData.initial_balance}
                    onChange={(e) => setFormData({ ...formData, initial_balance: e.target.value })}
                    placeholder="500.00"
                    required
                  />
                </div>
              )}

              {!editingCard && (
                <div>
                  <Label htmlFor="currency">Currency</Label>
                  <Select
                    value={formData.currency}
                    onValueChange={(v) => setFormData({ ...formData, currency: v })}
                  >
                    <SelectTrigger id="currency">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="ZAR">ZAR (South African Rand)</SelectItem>
                      <SelectItem value="USD">USD (US Dollar)</SelectItem>
                      <SelectItem value="EUR">EUR (Euro)</SelectItem>
                      <SelectItem value="GBP">GBP (British Pound)</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              )}

              <div>
                <Label htmlFor="expires_at">Expiration Date (Optional)</Label>
                <Input
                  id="expires_at"
                  type="date"
                  value={formData.expires_at}
                  onChange={(e) => setFormData({ ...formData, expires_at: e.target.value })}
                />
                <p className="text-xs text-gray-500 mt-1">
                  Leave empty for gift cards that never expire
                </p>
              </div>

              <div>
                <Label htmlFor="metadata">Metadata (JSON)</Label>
                <textarea
                  id="metadata"
                  value={formData.metadata}
                  onChange={(e) => setFormData({ ...formData, metadata: e.target.value })}
                  rows={4}
                  className="w-full p-2 border rounded-md font-mono text-sm"
                  placeholder='{"recipient_email": "user@example.com"}'
                />
                <p className="text-xs text-gray-500 mt-1">
                  Add <code className="bg-gray-100 px-1 rounded">recipient_email</code> so the customer sees this card under Account ΓåÆ Payments ΓåÆ Gift cards.
                </p>
              </div>
            </div>

            <DialogFooter>
              <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
                Cancel
              </Button>
              <Button
                onClick={handleSave}
                className="bg-[#FF0077] hover:bg-[#D60565]"
              >
                {editingCard ? "Update" : "Create"} Gift Card
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>

        {/* View Details Dialog */}
        <Dialog open={isViewDialogOpen} onOpenChange={setIsViewDialogOpen}>
          <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>Gift Card Details: {viewingCard?.code}</DialogTitle>
              <DialogDescription>View gift card information and redemption history</DialogDescription>
            </DialogHeader>

            {viewingCard && (
              <div className="space-y-6">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label className="text-sm font-medium text-gray-500">Code</Label>
                    <p className="text-sm font-mono font-medium">{viewingCard.code}</p>
                  </div>
                  <div>
                    <Label className="text-sm font-medium text-gray-500">Currency</Label>
                    <p className="text-sm">{viewingCard.currency}</p>
                  </div>
                  <div>
                    <Label className="text-sm font-medium text-gray-500">Initial Balance</Label>
                    <p className="text-sm font-semibold">
                      {formatCurrency(viewingCard.initial_balance, viewingCard.currency)}
                    </p>
                  </div>
                  <div>
                    <Label className="text-sm font-medium text-gray-500">Current Balance</Label>
                    <p className="text-sm font-semibold">
                      {formatCurrency(viewingCard.balance, viewingCard.currency)}
                    </p>
                  </div>
                  <div>
                    <Label className="text-sm font-medium text-gray-500">Status</Label>
                    <div className="mt-1">{getStatusBadge(viewingCard)}</div>
                  </div>
                  <div>
                    <Label className="text-sm font-medium text-gray-500">Expires</Label>
                    <p className="text-sm">
                      {viewingCard.expires_at
                        ? new Date(viewingCard.expires_at).toLocaleString()
                        : "Never"}
                    </p>
                  </div>
                </div>

                {(viewingCard as any).redemptions &&
                  (viewingCard as any).redemptions.length > 0 && (
                    <div>
                      <Label className="text-sm font-medium text-gray-500 mb-2 block">
                        Redemption History
                      </Label>
                      <div className="space-y-2">
                        {(viewingCard as any).redemptions.map((redemption: any) => (
                          <div
                            key={redemption.id}
                            className="flex items-center justify-between p-3 border rounded"
                          >
                            <div>
                              <p className="text-sm font-medium">
                                {formatCurrency(redemption.amount, viewingCard.currency)}
                              </p>
                              <p className="text-xs text-gray-500">
                                Booking: {redemption.booking_id?.substring(0, 8)}...
                              </p>
                            </div>
                            <div className="flex items-center gap-2">
                              <Badge
                                className={
                                  redemption.status === "captured"
                                    ? "bg-green-100 text-green-800"
                                    : redemption.status === "voided"
                                    ? "bg-gray-100 text-gray-800"
                                    : "bg-yellow-100 text-yellow-800"
                                }
                              >
                                {redemption.status}
                              </Badge>
                              <p className="text-xs text-gray-500">
                                {new Date(redemption.created_at).toLocaleDateString()}
                              </p>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
              </div>
            )}
          </DialogContent>
        </Dialog>
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Plus, Edit, Trash2, Globe, CreditCard, Clock, Languages } from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { FetchError } from "@/lib/http/fetcher";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface Currency {
  code: string;
  name: string;
  symbol?: string | null;
  decimal_places: number;
  is_active: boolean;
  is_default: boolean;
}

interface Language {
  code: string;
  name: string;
  native_name?: string | null;
  is_active: boolean;
  is_default: boolean;
  rtl: boolean;
}

interface Country {
  code: string;
  code3?: string | null;
  numeric_code?: string | null;
  name: string;
  phone_country_code: string;
  is_active: boolean;
  is_default: boolean;
}

interface Locale {
  code: string;
  language_code: string;
  country_code: string;
  name: string;
  is_active: boolean;
  is_default: boolean;
}

interface Timezone {
  code: string;
  name: string;
  utc_offset: string;
  country_code?: string | null;
  is_active: boolean;
  is_default: boolean;
}

export default function AdminIsoCodes() {
  const [activeTab, setActiveTab] = useState<"currencies" | "languages" | "countries" | "locales" | "timezones">("currencies");
  const [currencies, setCurrencies] = useState<Currency[]>([]);
  const [languages, setLanguages] = useState<Language[]>([]);
  const [countries, setCountries] = useState<Country[]>([]);
  const [locales, setLocales] = useState<Locale[]>([]);
  const [timezones, setTimezones] = useState<Timezone[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showDialog, setShowDialog] = useState(false);
  const [editingItem, setEditingItem] = useState<any>(null);
  const [dialogType, setDialogType] = useState<typeof activeTab | null>(null);

  useEffect(() => {
    loadData();
  }, [activeTab]); // eslint-disable-line react-hooks/exhaustive-deps -- load when tab changes

  // Load languages and countries on mount so Locales/Timezones tabs and dialogs have dropdown data
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const [langsRes, countriesRes] = await Promise.all([
          fetcher.get<{ data?: Language[] }>("/api/admin/iso-codes/languages"),
          fetcher.get<{ data?: Country[] }>("/api/admin/iso-codes/countries"),
        ]);
        if (!cancelled) {
          const langList = Array.isArray(langsRes?.data) ? langsRes.data : [];
          const countryList = Array.isArray(countriesRes?.data) ? countriesRes.data : [];
          setLanguages(langList as Language[]);
          setCountries(countryList as Country[]);
        }
      } catch {
        // Non-blocking; dropdowns will populate when user visits Languages/Countries tab
      }
    })();
    return () => { cancelled = true; };
  }, []);

  const loadData = async () => {
    try {
      setIsLoading(true);
      const endpoint = `/api/admin/iso-codes/${activeTab}`;
      const response = await fetcher.get<{ data?: any[]; error?: { message?: string } }>(endpoint);
      const data = Array.isArray(response?.data) ? response.data : [];

      switch (activeTab) {
        case "currencies":
          setCurrencies(data as Currency[]);
          break;
        case "languages":
          setLanguages(data as Language[]);
          break;
        case "countries":
          setCountries(data as Country[]);
          break;
        case "locales":
          setLocales(data as Locale[]);
          break;
        case "timezones":
          setTimezones(data as Timezone[]);
          break;
      }
    } catch (e) {
      const message = e instanceof FetchError ? e.message : e instanceof Error ? e.message : "Failed to load data";
      toast.error(message);
      switch (activeTab) {
        case "currencies": setCurrencies([]); break;
        case "languages": setLanguages([]); break;
        case "countries": setCountries([]); break;
        case "locales": setLocales([]); break;
        case "timezones": setTimezones([]); break;
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreate = () => {
    setEditingItem(null);
    setDialogType(activeTab);
    setShowDialog(true);
  };

  const handleEdit = (item: any) => {
    setEditingItem(item);
    setDialogType(activeTab);
    setShowDialog(true);
  };

  function formatFetchError(e: any, fallback: string): string {
    if (!(e instanceof FetchError)) return e instanceof Error ? e.message : fallback;
    const msg = e.message;
    if (!e.details) return msg;
    const details = Array.isArray(e.details)
      ? (e.details as Array<{ path?: string; message?: string }>).map((d) => (d.path ? `${d.path}: ${d.message ?? ""}` : String(d.message ?? d))).join("; ")
      : String(e.details);
    return details ? `${msg}: ${details}` : msg;
  }

  const handleDelete = async (item: { code: string; name?: string }) => {
    if (!confirm(`Are you sure you want to delete ${item.code || item.name}?`)) return;
    try {
      const code = encodeURIComponent(item.code);
      await fetcher.delete(`/api/admin/iso-codes/${activeTab}/${code}`);
      toast.success("Deleted successfully");
      loadData();
    } catch (e) {
      toast.error(formatFetchError(e, "Failed to delete"));
    }
  };

  const handleSave = async (formData: Record<string, any>) => {
    try {
      if (editingItem) {
        const code = encodeURIComponent(String(editingItem.code));
        await fetcher.put(`/api/admin/iso-codes/${activeTab}/${code}`, formData);
        toast.success("Updated successfully");
      } else {
        await fetcher.post(`/api/admin/iso-codes/${activeTab}`, formData);
        toast.success("Created successfully");
      }
      setShowDialog(false);
      setEditingItem(null);
      loadData();
    } catch (e) {
      toast.error(formatFetchError(e, "Failed to save"));
    }
  };

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading ISO codes..." />;
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
      <div className="container mx-auto px-4 py-8 max-w-7xl">
        <div className="mb-6">
          <h1 className="text-3xl font-semibold mb-2">ISO Codes Management</h1>
          <p className="text-gray-600 mb-2">Manage currencies, languages, countries, locales, and timezones. This reference data drives the platform: active countries power <code className="text-xs bg-gray-100 px-1 rounded">/api/public/countries</code> (forms, onboarding); active languages power the app language selector and <code className="text-xs bg-gray-100 px-1 rounded">/api/public/languages</code>. Align with Admin ΓåÆ Settings ΓåÆ Localization for default language and timezone.</p>
        </div>

        <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as any)}>
          <TabsList className="mb-6">
            <TabsTrigger value="currencies">
              <CreditCard className="w-4 h-4 mr-2" />
              Currencies
            </TabsTrigger>
            <TabsTrigger value="languages">
              <Languages className="w-4 h-4 mr-2" />
              Languages
            </TabsTrigger>
            <TabsTrigger value="countries">
              <Globe className="w-4 h-4 mr-2" />
              Countries
            </TabsTrigger>
            <TabsTrigger value="locales">
              <Globe className="w-4 h-4 mr-2" />
              Locales
            </TabsTrigger>
            <TabsTrigger value="timezones">
              <Clock className="w-4 h-4 mr-2" />
              Timezones
            </TabsTrigger>
          </TabsList>

          <TabsContent value="currencies">
            <CurrencyTab
              currencies={currencies}
              onEdit={handleEdit}
              onDelete={handleDelete}
              onCreate={handleCreate}
            />
          </TabsContent>

          <TabsContent value="languages">
            <LanguageTab
              languages={languages}
              onEdit={handleEdit}
              onDelete={handleDelete}
              onCreate={handleCreate}
            />
          </TabsContent>

          <TabsContent value="countries">
            <CountryTab
              countries={countries}
              onEdit={handleEdit}
              onDelete={handleDelete}
              onCreate={handleCreate}
            />
          </TabsContent>

          <TabsContent value="locales">
            <LocaleTab
              locales={locales}
              languages={languages}
              countries={countries}
              onEdit={handleEdit}
              onDelete={handleDelete}
              onCreate={handleCreate}
            />
          </TabsContent>

          <TabsContent value="timezones">
            <TimezoneTab
              timezones={timezones}
              countries={countries}
              onEdit={handleEdit}
              onDelete={handleDelete}
              onCreate={handleCreate}
            />
          </TabsContent>
        </Tabs>

        {showDialog && dialogType && (
          <IsoCodeDialog
            type={dialogType}
            item={editingItem}
            languages={languages}
            countries={countries}
            onClose={() => {
              setShowDialog(false);
              setEditingItem(null);
            }}
            onSave={handleSave}
          />
        )}
      </div>
    </RoleGuard>
  );
}

function CurrencyTab({
  currencies,
  onEdit,
  onDelete,
  onCreate,
}: {
  currencies: Currency[];
  onEdit: (item: Currency) => void;
  onDelete: (item: Currency) => void;
  onCreate: () => void;
}) {
  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <p className="text-sm text-gray-600">ISO 4217 Currency Codes</p>
        <Button onClick={onCreate}>
          <Plus className="w-4 h-4 mr-2" />
          Add Currency
        </Button>
      </div>
      {currencies.length === 0 ? (
        <EmptyState
          title="No currencies"
          description="Add your first currency to get started"
          action={{ label: "Add currency", onClick: onCreate }}
        />
      ) : (
        <div className="bg-white border rounded-lg overflow-hidden">
          <table className="w-full">
            <thead className="bg-gray-50 border-b">
              <tr>
