function IsoCodeDialog({
  type,
  item,
  languages,
  countries,
  onClose,
  onSave,
}: {
  type: "currencies" | "languages" | "countries" | "locales" | "timezones";
  item: any;
  languages: Language[];
  countries: Country[];
  onClose: () => void;
  onSave: (data: any) => void;
}) {
  const [formData, setFormData] = useState<any>(() => {
    if (item) return { ...item };
    
    // Default values for new items
    switch (type) {
      case "currencies":
        return { code: "", name: "", symbol: "", decimal_places: 2, is_active: true, is_default: false };
      case "languages":
        return { code: "", name: "", native_name: "", is_active: true, is_default: false, rtl: false };
      case "countries":
        return { code: "", code3: "", numeric_code: "", name: "", phone_country_code: "", is_active: true, is_default: false };
      case "locales":
        return { code: "", language_code: "", country_code: "", name: "", is_active: true, is_default: false };
      case "timezones":
        return { code: "", name: "", utc_offset: "+00:00", country_code: "", is_active: true, is_default: false };
      default:
        return {};
    }
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    
    // Auto-generate locale code from language + country
    const dataToSave = type === "locales" && !item && formData.language_code && formData.country_code
      ? { ...formData, code: `${formData.language_code.toLowerCase()}-${formData.country_code.toUpperCase()}` }
      : formData;
    onSave(dataToSave);
  };

  return (
    <Dialog open={true} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{item ? `Edit ${type.slice(0, -1)}` : `Add ${type.slice(0, -1)}`}</DialogTitle>
          <DialogDescription>
            {type === "currencies" && "ISO 4217 Currency Code (3 uppercase letters)"}
            {type === "languages" && "ISO 639-1 Language Code (2 lowercase letters)"}
            {type === "countries" && "ISO 3166-1 Country Code (2 uppercase letters) with ITU-T E.164 phone code"}
            {type === "locales" && "ISO 639-1 + ISO 3166-1 Locale Code (e.g., en-US)"}
            {type === "timezones" && "IANA Timezone Code (e.g., Africa/Johannesburg)"}
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          {type === "currencies" && (
            <>
              <div>
                <Label htmlFor="code">Currency Code (ISO 4217) *</Label>
                <Input
                  id="code"
                  value={formData.code}
                  onChange={(e) => setFormData({ ...formData, code: e.target.value.toUpperCase() })}
                  placeholder="USD"
                  maxLength={3}
                  required
                  disabled={!!item}
                  pattern="[A-Z]{3}"
                />
                <p className="text-xs text-gray-500 mt-1">3 uppercase letters (e.g., USD, ZAR, EUR)</p>
              </div>
              <div>
                <Label htmlFor="name">Currency Name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="US Dollar"
                  required
                />
              </div>
              <div>
                <Label htmlFor="symbol">Symbol</Label>
                <Input
                  id="symbol"
                  value={formData.symbol || ""}
                  onChange={(e) => setFormData({ ...formData, symbol: e.target.value })}
                  placeholder="R"
                />
              </div>
              <div>
                <Label htmlFor="decimal_places">Decimal Places *</Label>
                <Input
                  id="decimal_places"
                  type="number"
                  min="0"
                  max="4"
                  value={formData.decimal_places}
                  onChange={(e) => setFormData({ ...formData, decimal_places: parseInt(e.target.value) })}
                  required
                />
              </div>
              <div className="flex items-center gap-4">
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={formData.is_active}
                    onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                  />
                  <span>Active</span>
                </label>
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={formData.is_default}
                    onChange={(e) => setFormData({ ...formData, is_default: e.target.checked })}
                  />
                  <span>Default</span>
                </label>
              </div>
            </>
          )}

          {type === "languages" && (
            <>
              <div>
                <Label htmlFor="code">Language Code (ISO 639-1) *</Label>
                <Input
                  id="code"
                  value={formData.code}
                  onChange={(e) => setFormData({ ...formData, code: e.target.value.toLowerCase() })}
                  placeholder="en"
                  maxLength={2}
                  required
                  disabled={!!item}
                  pattern="[a-z]{2}"
                />
                <p className="text-xs text-gray-500 mt-1">2 lowercase letters (e.g., en, af, zu)</p>
              </div>
              <div>
                <Label htmlFor="name">Language Name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="English"
                  required
                />
              </div>
              <div>
                <Label htmlFor="native_name">Native Name</Label>
                <Input
                  id="native_name"
                  value={formData.native_name || ""}
                  onChange={(e) => setFormData({ ...formData, native_name: e.target.value })}
                  placeholder="English"
                />
              </div>
              <div className="flex items-center gap-4">
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={formData.rtl}
                    onChange={(e) => setFormData({ ...formData, rtl: e.target.checked })}
                  />
                  <span>Right-to-Left (RTL)</span>
                </label>
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={formData.is_active}
                    onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                  />
                  <span>Active</span>
                </label>
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={formData.is_default}
                    onChange={(e) => setFormData({ ...formData, is_default: e.target.checked })}
                  />
                  <span>Default</span>
                </label>
              </div>
            </>
          )}

          {type === "countries" && (
            <>
              <div>
                <Label htmlFor="code">Country Code (ISO 3166-1 alpha-2) *</Label>
                <Input
                  id="code"
                  value={formData.code}
                  onChange={(e) => setFormData({ ...formData, code: e.target.value.toUpperCase() })}
                  placeholder="US"
                  maxLength={2}
                  required
                  disabled={!!item}
                  pattern="[A-Z]{2}"
                />
                <p className="text-xs text-gray-500 mt-1">2 uppercase letters (e.g., US, ZA, GB)</p>
              </div>
              <div>
                <Label htmlFor="code3">Country Code (ISO 3166-1 alpha-3)</Label>
                <Input
                  id="code3"
                  value={formData.code3 || ""}
                  onChange={(e) => setFormData({ ...formData, code3: e.target.value.toUpperCase() })}
                  placeholder="USA"
                  maxLength={3}
                  pattern="[A-Z]{3}"
                />
              </div>
              <div>
                <Label htmlFor="numeric_code">Numeric Code (ISO 3166-1 numeric)</Label>
                <Input
                  id="numeric_code"
                  value={formData.numeric_code || ""}
                  onChange={(e) => setFormData({ ...formData, numeric_code: e.target.value })}
                  placeholder="840"
                  maxLength={3}
                  pattern="[0-9]{3}"
                />
              </div>
              <div>
                <Label htmlFor="name">Country Name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="United States"
                  required
                />
              </div>
              <div>
                <Label htmlFor="phone_country_code">Phone Country Code (ITU-T E.164) *</Label>
                <Input
                  id="phone_country_code"
                  value={formData.phone_country_code}
                  onChange={(e) => setFormData({ ...formData, phone_country_code: e.target.value })}
                  placeholder="+1"
                  required
                  pattern="\+\d{1,4}"
                />
                <p className="text-xs text-gray-500 mt-1">Format: +XXX (e.g., +1, +27, +44)</p>
              </div>
              <div className="flex items-center gap-4">
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={formData.is_active}
                    onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                  />
                  <span>Active</span>
                </label>
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={formData.is_default}
                    onChange={(e) => setFormData({ ...formData, is_default: e.target.checked })}
                  />
                  <span>Default</span>
                </label>
              </div>
            </>
          )}

          {type === "locales" && (
            <>
              <div>
                <Label htmlFor="language_code">Language Code (ISO 639-1) *</Label>
                <Select
                  value={formData.language_code || ""}
                  onValueChange={(value) => {
                    const lang = (value || "").toLowerCase();
                    const country = (formData.country_code || "").toUpperCase();
                    const newCode = item ? formData.code : (lang && country ? `${lang}-${country}` : formData.code || "");
                    setFormData({ ...formData, language_code: value, code: newCode });
                  }}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select language" />
                  </SelectTrigger>
                  <SelectContent>
                    {languages.map((lang) => (
                      <SelectItem key={lang.code} value={lang.code}>
                        {lang.name} ({lang.code})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label htmlFor="country_code">Country Code (ISO 3166-1) *</Label>
                <Select
                  value={formData.country_code || ""}
                  onValueChange={(value) => {
                    const lang = (formData.language_code || "").toLowerCase();
                    const country = (value || "").toUpperCase();
                    const newCode = item ? formData.code : (lang && country ? `${lang}-${country}` : formData.code || "");
                    setFormData({ ...formData, country_code: value, code: newCode });
                  }}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select country" />
                  </SelectTrigger>
                  <SelectContent>
                    {countries.map((country) => (
                      <SelectItem key={country.code} value={country.code}>
                        {country.name} ({country.code})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label htmlFor="code">Locale Code *</Label>
                <Input
                  id="code"
                  value={formData.code}
                  onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                  placeholder="en-US"
                  required
                  disabled={!!item}
                  pattern="[a-z]{2}-[A-Z]{2}"
                />
                <p className="text-xs text-gray-500 mt-1">Format: ll-CC (e.g., en-US, en-ZA, af-ZA)</p>
              </div>
              <div>
                <Label htmlFor="name">Locale Name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="English (United States)"
                  required
                />
              </div>
              <div className="flex items-center gap-4">
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={formData.is_active}
                    onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                  />
                  <span>Active</span>
                </label>
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={formData.is_default}
                    onChange={(e) => setFormData({ ...formData, is_default: e.target.checked })}
                  />
                  <span>Default</span>
                </label>
              </div>
            </>
          )}

          {type === "timezones" && (
            <>
              <div>
                <Label htmlFor="code">Timezone Code (IANA) *</Label>
                <Input
                  id="code"
                  value={formData.code}
                  onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                  placeholder="Africa/Johannesburg"
                  required
                  disabled={!!item}
                />
                <p className="text-xs text-gray-500 mt-1">IANA timezone identifier (e.g., Africa/Johannesburg, America/New_York)</p>
              </div>
              <div>
                <Label htmlFor="name">Timezone Name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="South Africa Standard Time"
                  required
                />
              </div>
              <div>
                <Label htmlFor="utc_offset">UTC Offset *</Label>
                <Input
                  id="utc_offset"
                  value={formData.utc_offset}
                  onChange={(e) => setFormData({ ...formData, utc_offset: e.target.value })}
                  placeholder="+02:00"
                  required
                  pattern="[+-]\d{2}:\d{2}"
                />
                <p className="text-xs text-gray-500 mt-1">Format: +/-HH:MM (e.g., +02:00, -05:00)</p>
              </div>
              <div>
                <Label htmlFor="country_code">Country Code (Optional)</Label>
                <Select
                  value={formData.country_code || ""}
                  onValueChange={(value) => setFormData({ ...formData, country_code: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select country" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="">None</SelectItem>
                    {countries.map((country) => (
                      <SelectItem key={country.code} value={country.code}>
                        {country.name} ({country.code})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="flex items-center gap-4">
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={formData.is_active}
                    onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                  />
                  <span>Active</span>
                </label>
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={formData.is_default}
                    onChange={(e) => setFormData({ ...formData, is_default: e.target.checked })}
                  />
                  <span>Default</span>
                </label>
              </div>
            </>
          )}

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit">
              {item ? "Update" : "Create"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { motion } from "framer-motion";
import RoleGuard from "@/components/auth/RoleGuard";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";
import { Gift, Award, TrendingUp, Save, Edit, Trash2, RefreshCw, Loader2 } from "lucide-react";

type LoyaltyRule = {
  id: string;
  points_per_currency_unit: number;
  currency: string;
  redemption_rate: number;
  is_active: boolean;
  effective_from: string;
};

type LoyaltyMilestone = {
  id: string;
  name: string;
  description?: string | null;
  points_threshold: number;
  reward_type: "wallet_credit";
  reward_amount: number;
  reward_currency: string;
  is_active: boolean;
};

export default function AdminLoyaltyPage() {
  const [rules, setRules] = useState<LoyaltyRule[]>([]);
  const [milestones, setMilestones] = useState<LoyaltyMilestone[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const activeRule = useMemo(() => rules.find((r) => r.is_active) || rules[0] || null, [rules]);

  const [newRule, setNewRule] = useState({
    points_per_currency_unit: 1,
    currency: "ZAR",
    redemption_rate: 100,
  });

  const [milestoneForm, setMilestoneForm] = useState<Partial<LoyaltyMilestone>>({
    name: "",
    description: "",
    points_threshold: 100,
    reward_amount: 10,
    reward_currency: "ZAR",
    is_active: true,
  });
  const [editingId, setEditingId] = useState<string | null>(null);

  const load = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const [rulesRes, milestonesRes] = await Promise.all([
        fetcher.get<{ data: LoyaltyRule[] }>("/api/admin/loyalty/rules"),
        fetcher.get<{ data: LoyaltyMilestone[] }>("/api/admin/loyalty/milestones"),
      ]);
      setRules(rulesRes.data || []);
      setMilestones(milestonesRes.data || []);
    } catch (err) {
      const msg =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load loyalty settings";
      setError(msg);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const createRule = async () => {
    try {
      setIsSaving(true);
      await fetcher.post("/api/admin/loyalty/rules", newRule);
      toast.success("Loyalty rule created successfully");
      await load();
      setNewRule({ points_per_currency_unit: 1, currency: "ZAR", redemption_rate: 100 });
    } catch (err: any) {
      toast.error(err.message || "Failed to create loyalty rule");
    } finally {
      setIsSaving(false);
    }
  };

  const saveMilestone = async () => {
    if (!milestoneForm.name || !milestoneForm.points_threshold) {
      toast.error("Please fill in all required fields");
      return;
    }

    try {
      setIsSaving(true);
      const payload = {
        name: milestoneForm.name,
        description: milestoneForm.description || null,
        points_threshold: Number(milestoneForm.points_threshold),
        reward_type: "wallet_credit" as const,
        reward_amount: Number(milestoneForm.reward_amount),
        reward_currency: milestoneForm.reward_currency || "ZAR",
        is_active: Boolean(milestoneForm.is_active),
      };

      if (editingId) {
        await fetcher.put(`/api/admin/loyalty/milestones/${editingId}`, payload);
        toast.success("Milestone updated successfully");
      } else {
        await fetcher.post("/api/admin/loyalty/milestones", payload);
        toast.success("Milestone created successfully");
      }
      setEditingId(null);
      setMilestoneForm({
        name: "",
        description: "",
        points_threshold: 100,
        reward_amount: 10,
        reward_currency: "ZAR",
        is_active: true,
      });
      await load();
    } catch (err: any) {
      toast.error(err.message || "Failed to save milestone");
    } finally {
      setIsSaving(false);
    }
  };

  const editMilestone = (m: LoyaltyMilestone) => {
    setEditingId(m.id);
    setMilestoneForm({ ...m });
  };

  const deleteMilestone = async (id: string) => {
    if (!confirm("Are you sure you want to delete this milestone? This action cannot be undone.")) return;
    try {
      await fetcher.delete(`/api/admin/loyalty/milestones/${id}`);
      toast.success("Milestone deleted successfully");
      await load();
    } catch (err: any) {
      toast.error(err.message || "Failed to delete milestone");
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-zinc-50/50 flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-[#FF0077] animate-spin" />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]}>
      <div className="min-h-screen bg-zinc-50/50 py-6 md:py-8">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3 }}
          >
            <div className="flex items-center gap-3 mb-8">
              <div className="p-3 bg-gradient-to-br from-[#FF0077]/10 to-[#E6006A]/10 rounded-xl">
                <Gift className="w-8 h-8 text-[#FF0077]" />
              </div>
              <div>
                <h1 className="text-3xl md:text-4xl font-semibold tracking-tighter text-gray-900">
                  Loyalty Program
                </h1>
                <p className="text-sm font-light text-gray-600 mt-1">
                  Manage loyalty rules and milestone rewards
                </p>
              </div>
            </div>

            {error && (
              <motion.div
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                className="mb-6"
              >
                <EmptyState
                  title="Failed to load loyalty settings"
                  description={error}
                  action={{ label: "Retry", onClick: load }}
                />
              </motion.div>
            )}

            {!error && (
              <div className="space-y-6">
                {/* Loyalty Rules Card */}
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.1 }}
                  className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 md:p-8"
                >
                  <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-gradient-to-br from-[#FF0077]/10 to-[#E6006A]/10 rounded-lg">
                        <TrendingUp className="w-5 h-5 text-[#FF0077]" />
                      </div>
                      <div>
                        <h2 className="text-xl font-semibold tracking-tighter text-gray-900">
                          Loyalty Rules
                        </h2>
                        <p className="text-sm font-light text-gray-600 mt-1">
                          Configure how points are earned and redeemed
                        </p>
                      </div>
                    </div>
                  </div>

                  {activeRule && (
                    <div className="mb-6 p-4 backdrop-blur-sm bg-white/60 border border-white/40 rounded-xl">
                      <p className="text-xs font-medium text-gray-500 mb-1">Current Active Rule</p>
                      <p className="text-sm font-semibold text-gray-900">
                        {activeRule.points_per_currency_unit} point{activeRule.points_per_currency_unit !== 1 ? "s" : ""} per {activeRule.currency} ΓÇó 
                        {" "}Redemption: {activeRule.redemption_rate} points = 1 {activeRule.currency}
                      </p>
                      <p className="text-xs text-gray-500 mt-1">
                        Effective from {new Date(activeRule.effective_from).toLocaleDateString()}
                      </p>
                    </div>
                  )}

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                    <div>
                      <Label htmlFor="points_per_unit" className="text-sm font-medium text-gray-700 mb-2 block">
                        Points per currency unit
                      </Label>
                      <Input
                        id="points_per_unit"
                        type="number"
                        min="0.01"
                        step="0.01"
                        value={newRule.points_per_currency_unit}
                        onChange={(e) => setNewRule((s) => ({ ...s, points_per_currency_unit: Number(e.target.value) }))}
                        className="backdrop-blur-sm bg-white/60 border-white/40"
                        placeholder="1"
                      />
                      <p className="text-xs text-gray-500 mt-1">e.g., 1 point per 1 ZAR spent</p>
                    </div>
                    <div>
                      <Label htmlFor="currency" className="text-sm font-medium text-gray-700 mb-2 block">
                        Currency
                      </Label>
                      <Input
                        id="currency"
                        value={newRule.currency}
                        onChange={(e) => setNewRule((s) => ({ ...s, currency: e.target.value.toUpperCase() }))}
                        className="backdrop-blur-sm bg-white/60 border-white/40"
                        placeholder="ZAR"
                        maxLength={3}
                      />
                    </div>
                    <div>
                      <Label htmlFor="redemption_rate" className="text-sm font-medium text-gray-700 mb-2 block">
                        Redemption rate
                      </Label>
                      <Input
                        id="redemption_rate"
                        type="number"
                        min="1"
                        step="1"
                        value={newRule.redemption_rate}
                        onChange={(e) => setNewRule((s) => ({ ...s, redemption_rate: Number(e.target.value) }))}
                        className="backdrop-blur-sm bg-white/60 border-white/40"
                        placeholder="100"
                      />
                      <p className="text-xs text-gray-500 mt-1">
                        {newRule.redemption_rate} points = 1 {newRule.currency}
                      </p>
                    </div>
                  </div>

                  <motion.button
                    onClick={createRule}
                    disabled={isSaving}
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    className="bg-gradient-to-r from-[#FF0077] to-[#E6006A] hover:from-[#E6006A] hover:to-[#FF0077] text-white px-6 py-3 rounded-xl font-semibold transition-all shadow-lg hover:shadow-xl disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                  >
                    {isSaving ? (
                      <>
                        <Loader2 className="w-5 h-5 animate-spin" />
                        <span>Creating...</span>
                      </>
                    ) : (
                      <>
                        <Save className="w-5 h-5" />
                        <span>Create New Rule</span>
                      </>
                    )}
                  </motion.button>
                </motion.div>

                {/* Milestone Rewards Card */}
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.2 }}
                  className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 md:p-8"
                >
                  <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-gradient-to-br from-[#FF0077]/10 to-[#E6006A]/10 rounded-lg">
                        <Award className="w-5 h-5 text-[#FF0077]" />
                      </div>
                      <div>
                        <h2 className="text-xl font-semibold tracking-tighter text-gray-900">
                          Milestone Rewards
                        </h2>
                        <p className="text-sm font-light text-gray-600 mt-1">
                          Set reward thresholds that users unlock when they reach certain point levels
                        </p>
                      </div>
                    </div>
                    <motion.button
                      onClick={load}
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      className="p-2 hover:bg-white/40 rounded-lg transition-colors"
                      aria-label="Refresh"
                    >
                      <RefreshCw className="w-5 h-5 text-gray-600" />
                    </motion.button>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-5 gap-4 mb-4">
                    <div className="md:col-span-2">
                      <Label htmlFor="milestone_name" className="text-sm font-medium text-gray-700 mb-2 block">
                        Milestone Name *
                      </Label>
                      <Input
                        id="milestone_name"
                        value={milestoneForm.name || ""}
                        onChange={(e) => setMilestoneForm((s) => ({ ...s, name: e.target.value }))}
                        className="backdrop-blur-sm bg-white/60 border-white/40"
                        placeholder="e.g., Bronze Member"
                        required
                      />
                    </div>
                    <div>
                      <Label htmlFor="points_threshold" className="text-sm font-medium text-gray-700 mb-2 block">
                        Points Threshold *
                      </Label>
                      <Input
                        id="points_threshold"
                        type="number"
                        min="1"
                        step="1"
                        value={milestoneForm.points_threshold ?? 0}
                        onChange={(e) => setMilestoneForm((s) => ({ ...s, points_threshold: Number(e.target.value) }))}
                        className="backdrop-blur-sm bg-white/60 border-white/40"
                        placeholder="100"
                        required
                      />
                    </div>
                    <div>
                      <Label htmlFor="reward_amount" className="text-sm font-medium text-gray-700 mb-2 block">
                        Reward Amount *
                      </Label>
                      <Input
                        id="reward_amount"
                        type="number"
                        min="0"
                        step="0.01"
                        value={milestoneForm.reward_amount ?? 0}
                        onChange={(e) => setMilestoneForm((s) => ({ ...s, reward_amount: Number(e.target.value) }))}
                        className="backdrop-blur-sm bg-white/60 border-white/40"
                        placeholder="10.00"
                        required
                      />
                    </div>
                    <div>
                      <Label htmlFor="reward_currency" className="text-sm font-medium text-gray-700 mb-2 block">
                        Currency
                      </Label>
                      <Input
                        id="reward_currency"
                        value={milestoneForm.reward_currency || "ZAR"}
                        onChange={(e) => setMilestoneForm((s) => ({ ...s, reward_currency: e.target.value.toUpperCase() }))}
                        className="backdrop-blur-sm bg-white/60 border-white/40"
                        placeholder="ZAR"
                        maxLength={3}
                      />
                    </div>
                  </div>

                  <div className="mb-4">
                    <Label htmlFor="milestone_description" className="text-sm font-medium text-gray-700 mb-2 block">
                      Description
                    </Label>
                    <Textarea
                      id="milestone_description"
                      value={milestoneForm.description || ""}
                      onChange={(e) => setMilestoneForm((s) => ({ ...s, description: e.target.value }))}
                      className="backdrop-blur-sm bg-white/60 border-white/40"
                      placeholder="Optional description for this milestone..."
                      rows={2}
                    />
                  </div>

                  <div className="flex items-center gap-4 mb-6">
                    <motion.button
                      onClick={saveMilestone}
                      disabled={isSaving || !milestoneForm.name || !milestoneForm.points_threshold}
                      whileHover={{ scale: 1.02 }}
                      whileTap={{ scale: 0.98 }}
                      className="bg-gradient-to-r from-[#FF0077] to-[#E6006A] hover:from-[#E6006A] hover:to-[#FF0077] text-white px-6 py-3 rounded-xl font-semibold transition-all shadow-lg hover:shadow-xl disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                    >
                      {isSaving ? (
                        <>
                          <Loader2 className="w-5 h-5 animate-spin" />
                          <span>{editingId ? "Updating..." : "Creating..."}</span>
                        </>
                      ) : (
                        <>
                          <Save className="w-5 h-5" />
                          <span>{editingId ? "Update Milestone" : "Create Milestone"}</span>
                        </>
                      )}
                    </motion.button>
                    {editingId && (
                      <motion.button
                        onClick={() => {
                          setEditingId(null);
                          setMilestoneForm({
                            name: "",
                            description: "",
                            points_threshold: 100,
                            reward_amount: 10,
                            reward_currency: "ZAR",
                            is_active: true,
                          });
                        }}
                        whileHover={{ scale: 1.02 }}
                        whileTap={{ scale: 0.98 }}
                        className="px-6 py-3 backdrop-blur-sm bg-white/60 border border-white/40 hover:bg-white/80 text-gray-700 rounded-xl font-semibold transition-all"
                      >
                        Cancel
                      </motion.button>
                    )}
                  </div>

                  {/* Milestones List */}
                  <div className="space-y-3">
                    {milestones.length === 0 ? (
                      <div className="p-8 text-center backdrop-blur-sm bg-white/40 border border-white/20 rounded-xl">
                        <Award className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                        <p className="text-sm text-gray-600">No milestones created yet</p>
                        <p className="text-xs text-gray-500 mt-1">Create your first milestone above</p>
                      </div>
                    ) : (
                      milestones.map((m) => (
                        <motion.div
                          key={m.id}
                          initial={{ opacity: 0, x: -10 }}
                          animate={{ opacity: 1, x: 0 }}
                          className="p-4 backdrop-blur-sm bg-white/40 border border-white/20 rounded-xl hover:bg-white/60 transition-colors"
                        >
                          <div className="flex items-center justify-between gap-4">
                            <div className="flex-1">
                              <div className="flex items-center gap-3 mb-2">
                                <Award className={`w-5 h-5 ${m.is_active ? "text-[#FF0077]" : "text-gray-400"}`} />
                                <div>
                                  <p className="font-semibold text-gray-900">
                                    {m.name}
                                    {!m.is_active && (
                                      <span className="ml-2 text-xs text-gray-500 font-normal">(Inactive)</span>
                                    )}
                                  </p>
                                  <p className="text-sm text-gray-600">
                                    {m.points_threshold.toLocaleString()} points ΓåÆ {m.reward_currency} {m.reward_amount.toLocaleString()}
                                  </p>
                                  {m.description && (
                                    <p className="text-xs text-gray-500 mt-1">{m.description}</p>
                                  )}
                                </div>
                              </div>
                            </div>
                            <div className="flex gap-2">
                              <motion.button
                                onClick={() => editMilestone(m)}
                                whileHover={{ scale: 1.05 }}
                                whileTap={{ scale: 0.95 }}
                                className="p-2 text-[#FF0077] hover:bg-[#FF0077]/10 rounded-lg transition-colors"
                                aria-label="Edit milestone"
                              >
                                <Edit className="w-4 h-4" />
                              </motion.button>
                              <motion.button
                                onClick={() => deleteMilestone(m.id)}
                                whileHover={{ scale: 1.05 }}
                                whileTap={{ scale: 0.95 }}
                                className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                aria-label="Delete milestone"
                              >
                                <Trash2 className="w-4 h-4" />
                              </motion.button>
                            </div>
                          </div>
                        </motion.div>
                      ))
                    )}
                  </div>
                </motion.div>
              </div>
            )}
          </motion.div>
        </div>
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { fetcher } from "@/lib/http/fetcher";
import { FetchError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import { toast } from "sonner";
import { Save, Eye, EyeOff } from "lucide-react";

function formatFetchError(e: any, fallback: string): string {
  if (!(e instanceof FetchError)) return e instanceof Error ? e.message : fallback;
  const msg = e.message;
  if (!e.details) return msg;
  const details = Array.isArray(e.details)
    ? (e.details as Array<{ path?: string; message?: string }>)
        .map((d) => (d.path ? `${d.path}: ${d.message ?? ""}` : String(d.message ?? d)))
        .join("; ")
    : String(e.details);
  return details ? `${msg}: ${details}` : msg;
}

interface MapboxConfig {
  access_token: string;
  public_access_token: string;
  style_url?: string | null;
  is_enabled: boolean;
}

export default function MapboxConfigTab() {
  const [config, setConfig] = useState<MapboxConfig | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [showAccessToken, setShowAccessToken] = useState(false);
  const [showPublicToken, setShowPublicToken] = useState(false);
  const [formData, setFormData] = useState({
    access_token: "",
    public_access_token: "",
    style_url: "",
    is_enabled: true,
  });

  useEffect(() => {
    loadConfig();
  }, []);

  const loadConfig = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data: MapboxConfig | null }>("/api/admin/mapbox/config");
      if (response?.data) {
        setConfig(response.data);
        const pub = response.data.public_access_token || "";
        const isMasked = pub === "***" || pub.length <= 12 || pub.endsWith("...");
        setFormData({
          access_token: "",
          public_access_token: isMasked ? "" : pub,
          style_url: response.data.style_url || "",
          is_enabled: response.data.is_enabled,
        });
      }
    } catch (error) {
      console.error("Error loading config:", error);
      toast.error("Failed to load Mapbox configuration");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const payload: Record<string, any> = {
      is_enabled: formData.is_enabled,
      style_url: formData.style_url || null,
    };
    if (formData.access_token.trim()) payload.access_token = formData.access_token;
    const pub = formData.public_access_token.trim();
    if (pub && pub !== "***" && !pub.endsWith("...")) payload.public_access_token = pub;
    try {
      setIsSaving(true);
      await fetcher.put("/api/admin/mapbox/config", payload);
      toast.success("Mapbox configuration saved successfully");
      await loadConfig();
    } catch (error) {
      toast.error(formatFetchError(error, "Failed to save configuration"));
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading Mapbox configuration..." />;
  }

  return (
    <div className="bg-white border rounded-lg p-6">
      <form onSubmit={handleSave} className="space-y-6">
        <div>
          <Label htmlFor="is_enabled">Enable Mapbox</Label>
          <div className="flex items-center gap-4 mt-2">
            <input
              type="checkbox"
              id="is_enabled"
              checked={formData.is_enabled}
              onChange={(e) => setFormData({ ...formData, is_enabled: e.target.checked })}
              className="w-5 h-5"
            />
            <span className="text-sm text-gray-600">
              Enable Mapbox services across the platform
            </span>
          </div>
        </div>

        <div>
          <Label htmlFor="access_token">Server Access Token {config ? "" : "*"}</Label>
          <div className="relative mt-1">
            <Input
              id="access_token"
              type={showAccessToken ? "text" : "password"}
              value={formData.access_token}
              onChange={(e) => setFormData({ ...formData, access_token: e.target.value })}
              placeholder={config ? "Leave blank to keep current" : "pk.eyJ1Ijoi..."}
              required={!config}
              className="pr-10"
            />
            <Button
              type="button"
              variant="ghost"
              size="icon"
              onClick={() => setShowAccessToken(!showAccessToken)}
              className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500 hover:text-gray-700"
            >
              {showAccessToken ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
            </Button>
          </div>
          <p className="text-xs text-gray-500 mt-1">
            Server-side token for geocoding, routing, and distance calculations. Keep this secret. {config && "Leave blank to keep current."}
          </p>
        </div>

        <div>
          <Label htmlFor="public_access_token">
            Public Access Token {config ? "" : "*"}
          </Label>
          <div className="relative mt-1">
            <Input
              id="public_access_token"
              type={showPublicToken ? "text" : "password"}
              value={formData.public_access_token}
              onChange={(e) => setFormData({ ...formData, public_access_token: e.target.value })}
              placeholder={config ? "Leave blank to keep current" : "pk.eyJ1Ijoi..."}
              required={!config}
              className="pr-10"
            />
            <Button
              type="button"
              variant="ghost"
              size="icon"
              onClick={() => setShowPublicToken(!showPublicToken)}
              className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500 hover:text-gray-700"
            >
              {showPublicToken ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
            </Button>
          </div>
          <p className="text-xs text-gray-500 mt-1">
            Public token for client-side map rendering (web, customer & provider apps). {config && "Leave blank to keep current token."}
          </p>
        </div>

        <div>
          <Label htmlFor="style_url">Map Style URL (Optional)</Label>
          <Input
            id="style_url"
            type="url"
            value={formData.style_url}
            onChange={(e) => setFormData({ ...formData, style_url: e.target.value })}
            placeholder="mapbox://styles/mapbox/streets-v12"
            className="mt-1"
          />
          <p className="text-xs text-gray-500 mt-1">
            Custom Mapbox style URL. Defaults to Mapbox Streets if not provided.
          </p>
        </div>

        <div className="flex justify-end">
          <Button type="submit" disabled={isSaving}>
            <Save className="w-4 h-4 mr-2" />
            {isSaving ? "Saving..." : "Save Configuration"}
          </Button>
        </div>
      </form>

      <div className="mt-8 p-4 bg-blue-50 border border-blue-200 rounded-lg">
        <h3 className="font-semibold text-blue-900 mb-2">Getting Started</h3>
        <ol className="list-decimal list-inside space-y-1 text-sm text-blue-800">
          <li>Sign up for a Mapbox account at <a href="https://www.mapbox.com" target="_blank" rel="noopener noreferrer" className="underline">mapbox.com</a></li>
          <li>Create an access token in your Mapbox account dashboard</li>
          <li>Use the same token for both server and public access, or create separate tokens with appropriate scopes</li>
          <li>For custom styles, create a style in Mapbox Studio and use its URL</li>
          <li>Reference: <a href="https://docs.mapbox.com/api/" target="_blank" rel="noopener noreferrer" className="underline">Mapbox API Documentation</a></li>
        </ol>
      </div>
    </div>
  );
}

