}

"use client";

import React, { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Activity, RefreshCw } from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { format } from "date-fns";
import RoleGuard from "@/components/auth/RoleGuard";

interface SystemHealth {
  overall_status: "healthy" | "degraded" | "down";
  total_endpoints: number;
  healthy_endpoints: number;
  degraded_endpoints: number;
  down_endpoints: number;
  average_response_time_ms: number;
  endpoints: Array<{
    endpoint: string;
    method: string;
    average_response_time_ms: number;
    success_rate: number;
    total_checks: number;
    last_check: string;
    last_status: "healthy" | "degraded" | "down";
  }>;
}

interface ErrorStats {
  total: number;
  by_severity: Record<string, number>;
  by_endpoint: Array<{ endpoint: string; count: number }>;
  recent_errors: Array<{
    id: string;
    error_type: string;
    error_message: string;
    endpoint?: string;
    method?: string;
    status_code?: number;
    severity: "low" | "medium" | "high" | "critical";
    created_at: string;
  }>;
}

export default function MonitoringPage() {
  const [health, setHealth] = useState<SystemHealth | null>(null);
  const [errorStats, setErrorStats] = useState<ErrorStats | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [autoRefresh, setAutoRefresh] = useState(true);
  const [timeframe] = useState<"24h" | "7d" | "30d">("24h");

  useEffect(() => {
    loadData();
    
    if (autoRefresh) {
      const interval = setInterval(() => {
        loadData();
      }, 30000); // Refresh every 30 seconds

      return () => clearInterval(interval);
    }
  }, [autoRefresh, timeframe]); // eslint-disable-line react-hooks/exhaustive-deps -- load on mount and when options change

  const emptyErrorStats: ErrorStats = {
    total: 0,
    by_severity: {},
    by_endpoint: [],
    recent_errors: [],
  };

  const loadData = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const [healthResult, errorsResult] = await Promise.allSettled([
        fetcher.get<{ data: SystemHealth }>("/api/admin/monitoring/health?hours=24"),
        fetcher.get<{ data: { stats: ErrorStats; logs: any[] } }>(
          `/api/admin/monitoring/errors?timeframe=${timeframe}`
        ),
      ]);

      const health =
        healthResult.status === "fulfilled" && healthResult.value?.data != null
          ? healthResult.value.data
          : null;
      const stats =
        errorsResult.status === "fulfilled" && errorsResult.value?.data?.stats != null
          ? errorsResult.value.data.stats
          : emptyErrorStats;

      setHealth(health);
      setErrorStats(stats);

      if (healthResult.status === "rejected" && errorsResult.status === "rejected") {
        const msg =
          healthResult.reason instanceof Error
            ? healthResult.reason.message
            : "Failed to load monitoring data";
        setError(msg);
        toast.error(msg);
      }
    } catch (e) {
      const errorMessage = e instanceof Error ? e.message : "Failed to load monitoring data";
      setError(errorMessage);
      toast.error(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "healthy":
        return "bg-green-100 text-green-800 border-green-200";
      case "degraded":
        return "bg-yellow-100 text-yellow-800 border-yellow-200";
      case "down":
        return "bg-red-100 text-red-800 border-red-200";
      default:
        return "bg-gray-100 text-gray-800 border-gray-200";
    }
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case "critical":
        return "bg-red-100 text-red-800 border-red-200";
      case "high":
        return "bg-orange-100 text-orange-800 border-orange-200";
      case "medium":
        return "bg-yellow-100 text-yellow-800 border-yellow-200";
      case "low":
        return "bg-blue-100 text-blue-800 border-blue-200";
      default:
        return "bg-gray-100 text-gray-800 border-gray-200";
    }
  };

  if (isLoading) {
    return (
      <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
        <div className="container mx-auto px-4 py-8">
          <LoadingTimeout loadingMessage="Loading monitoring data..." />
        </div>
      </RoleGuard>
    );
  }

  if (error) {
    return (
      <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
        <div className="container mx-auto px-4 py-8">
          <EmptyState
          title="Failed to load monitoring data"
          description={error}
          action={{
            label: "Retry",
            onClick: loadData,
          }}
        />
        </div>
      </RoleGuard>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
    <div className="container mx-auto px-4 py-8">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-3xl font-semibold mb-2">System Monitoring</h1>
            <p className="text-gray-600">Real-time API health and error tracking</p>
          </div>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setAutoRefresh(!autoRefresh)}
            >
              <RefreshCw className={`w-4 h-4 mr-2 ${autoRefresh ? "animate-spin" : ""}`} />
              Auto-refresh {autoRefresh ? "ON" : "OFF"}
            </Button>
            <Button variant="outline" size="sm" onClick={loadData}>
              <RefreshCw className="w-4 h-4 mr-2" />
              Refresh Now
            </Button>
          </div>
        </div>

        <Tabs defaultValue="health" className="space-y-4">
          <TabsList>
            <TabsTrigger value="health">API Health</TabsTrigger>
            <TabsTrigger value="errors">Error Logs</TabsTrigger>
          </TabsList>

          <TabsContent value="health" className="space-y-4">
            {!health ? (
              <Card>
                <CardContent className="py-8">
                  <p className="text-muted-foreground text-center">
                    No health data available. Health checks may not be configured or the API failed to load.
                  </p>
                </CardContent>
              </Card>
            ) : (
              <>
                {/* Overall Status */}
                <Card>
                  <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                      <Activity className="w-5 h-5" />
                      Overall System Status
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="flex items-center gap-4">
                      <Badge className={getStatusColor(health.overall_status)}>
                        {health.overall_status.toUpperCase()}
                      </Badge>
                      <div className="flex items-center gap-6">
                        <div>
                          <p className="text-sm text-gray-600">Total Endpoints</p>
                          <p className="text-2xl font-semibold">{health.total_endpoints}</p>
                        </div>
                        <div>
                          <p className="text-sm text-gray-600">Healthy</p>
                          <p className="text-2xl font-semibold text-green-600">
                            {health.healthy_endpoints}
                          </p>
                        </div>
                        <div>
                          <p className="text-sm text-gray-600">Degraded</p>
                          <p className="text-2xl font-semibold text-yellow-600">
                            {health.degraded_endpoints}
                          </p>
                        </div>
                        <div>
                          <p className="text-sm text-gray-600">Down</p>
                          <p className="text-2xl font-semibold text-red-600">
                            {health.down_endpoints}
                          </p>
                        </div>
                        <div>
                          <p className="text-sm text-gray-600">Avg Response Time</p>
                          <p className="text-2xl font-semibold">
                            {health.average_response_time_ms}ms
                          </p>
                        </div>
                      </div>
                    </div>
                  </CardContent>
                </Card>

                {/* Endpoints Table */}
                <Card>
                  <CardHeader>
                    <CardTitle>Endpoint Health</CardTitle>
                    <CardDescription>Last 24 hours</CardDescription>
                  </CardHeader>
                  <CardContent>
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead>Endpoint</TableHead>
                          <TableHead>Method</TableHead>
                          <TableHead>Status</TableHead>
                          <TableHead>Avg Response Time</TableHead>
                          <TableHead>Success Rate</TableHead>
                          <TableHead>Total Checks</TableHead>
                          <TableHead>Last Check</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {health.endpoints.map((endpoint) => (
                          <TableRow key={`${endpoint.endpoint}-${endpoint.method}`}>
                            <TableCell className="font-mono text-sm">
                              {endpoint.endpoint}
                            </TableCell>
                            <TableCell>
                              <Badge variant="outline">{endpoint.method}</Badge>
                            </TableCell>
                            <TableCell>
                              <Badge className={getStatusColor(endpoint.last_status)}>
                                {endpoint.last_status}
                              </Badge>
                            </TableCell>
                            <TableCell>{endpoint.average_response_time_ms}ms</TableCell>
                            <TableCell>
                              <div className="flex items-center gap-2">
                                <div className="w-16 bg-gray-200 rounded-full h-2">
                                  <div
                                    className={`h-2 rounded-full ${
                                      endpoint.success_rate >= 95
                                        ? "bg-green-500"
                                        : endpoint.success_rate >= 80
                                        ? "bg-yellow-500"
                                        : "bg-red-500"
                                    }`}
                                    style={{ width: `${endpoint.success_rate}%` }}
                                  />
                                </div>
                                <span className="text-sm">{endpoint.success_rate.toFixed(1)}%</span>
                              </div>
                            </TableCell>
                            <TableCell>{endpoint.total_checks}</TableCell>
                            <TableCell>
                              {format(new Date(endpoint.last_check), "MMM d, HH:mm:ss")}
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </CardContent>
                </Card>
              </>
            )}
          </TabsContent>

          <TabsContent value="errors" className="space-y-4">
            {errorStats && (
              <>
                {/* Error Stats */}
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <Card>
                    <CardHeader>
                      <CardTitle className="text-sm font-medium">Total Errors</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <p className="text-3xl font-semibold">{errorStats.total}</p>
                    </CardContent>
                  </Card>
                  {Object.entries(errorStats.by_severity).map(([severity, count]) => (
                    <Card key={severity}>
                      <CardHeader>
                        <CardTitle className="text-sm font-medium capitalize">{severity}</CardTitle>
                      </CardHeader>
                      <CardContent>
                        <p className="text-3xl font-semibold">{count}</p>
                      </CardContent>
                    </Card>
                  ))}
                </div>

                {/* Top Error Endpoints */}
                <Card>
                  <CardHeader>
                    <CardTitle>Top Error Endpoints</CardTitle>
                    <CardDescription>Endpoints with most errors</CardDescription>
                  </CardHeader>
                  <CardContent>
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead>Endpoint</TableHead>
                          <TableHead>Error Count</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {errorStats.by_endpoint.map((item) => (
                          <TableRow key={item.endpoint}>
                            <TableCell className="font-mono text-sm">{item.endpoint}</TableCell>
                            <TableCell>{item.count}</TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </CardContent>
                </Card>

                {/* Recent Errors */}
                <Card>
                  <CardHeader>
                    <CardTitle>Recent Errors</CardTitle>
                    <CardDescription>Latest error occurrences</CardDescription>
                  </CardHeader>
                  <CardContent>
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead>Time</TableHead>
                          <TableHead>Severity</TableHead>
                          <TableHead>Type</TableHead>
                          <TableHead>Endpoint</TableHead>
                          <TableHead>Message</TableHead>
                          <TableHead>Status Code</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {errorStats.recent_errors.map((error) => (
                          <TableRow key={error.id}>
                            <TableCell>
                              {format(new Date(error.created_at), "MMM d, HH:mm:ss")}
                            </TableCell>
                            <TableCell>
                              <Badge className={getSeverityColor(error.severity)}>
                                {error.severity}
                              </Badge>
                            </TableCell>
                            <TableCell className="text-sm">{error.error_type}</TableCell>
                            <TableCell className="font-mono text-xs">
                              {error.endpoint || "N/A"}
                            </TableCell>
                            <TableCell className="max-w-md truncate">{error.error_message}</TableCell>
                            <TableCell>{error.status_code || "N/A"}</TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </CardContent>
                </Card>
              </>
            )}
          </TabsContent>
        </Tabs>
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Plus, Edit, Trash2, Bell, Mail, MessageSquare, Smartphone } from "lucide-react";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import RoleGuard from "@/components/auth/RoleGuard";

interface NotificationTemplate {
  id: string;
  name: string;
  type: string;
  title_template: string;
  message_template: string;
  priority: 'low' | 'medium' | 'high';
  channels: string[];
  enabled: boolean;
  variables?: string[];
  created_at: string;
  updated_at: string;
  key?: string;
  title?: string;
  body?: string;
  email_subject?: string | null;
  email_body?: string | null;
  sms_body?: string | null;
  url?: string | null;
  description?: string | null;
}

export default function NotificationTemplatesPage() {
  const [templates, setTemplates] = useState<NotificationTemplate[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingTemplate, setEditingTemplate] = useState<NotificationTemplate | null>(null);
  const [formData, setFormData] = useState({
    key: "",
    name: "",
    type: "",
    title_template: "",
    message_template: "",
    priority: "medium" as "low" | "medium" | "high",
    channels: [] as string[],
    enabled: true,
    variables: [] as string[],
  });

  useEffect(() => {
    loadTemplates();
  }, []);

  const loadTemplates = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data?: { templates?: NotificationTemplate[] }; templates?: NotificationTemplate[] }>('/api/admin/notification-templates');
      const list = response.data?.templates ?? response.templates ?? [];
      setTemplates(Array.isArray(list) ? list : []);
    } catch {
      toast.error("Failed to load notification templates");
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreate = () => {
    setEditingTemplate(null);
    setFormData({
      key: "",
      name: "",
      type: "",
      title_template: "",
      message_template: "",
      priority: "medium",
      channels: [],
      enabled: true,
      variables: [],
    });
    setIsDialogOpen(true);
  };

  const handleEdit = (template: NotificationTemplate) => {
    setEditingTemplate(template);
    setFormData({
      key: template.key ?? template.name ?? "",
      name: template.name,
      type: template.type,
      title_template: template.title_template ?? template.title ?? "",
      message_template: template.message_template ?? template.body ?? "",
      priority: template.priority,
      channels: template.channels ?? [],
      enabled: template.enabled,
      variables: template.variables || [],
    });
    setIsDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this template?")) return;

    try {
      await fetcher.delete(`/api/admin/notification-templates/${id}`);
      toast.success("Template deleted successfully");
      loadTemplates();
    } catch {
      toast.error("Failed to delete template");
    }
  };

  const handleSave = async () => {
    try {
      if (editingTemplate) {
        await fetcher.patch(`/api/admin/notification-templates/${editingTemplate.id}`, {
          title: formData.title_template,
          body: formData.message_template,
          channels: formData.channels,
          enabled: formData.enabled,
          variables: formData.variables,
        });
        toast.success("Template updated successfully");
      } else {
        const key = (formData.key || formData.type || "").trim().replace(/\s+/g, "_").toLowerCase();
        if (!key) {
          toast.error("Key is required (e.g. my_notification_type)");
          return;
        }
        await fetcher.post('/api/admin/notification-templates', {
          key,
          title: formData.title_template,
          body: formData.message_template,
          channels: formData.channels.length ? formData.channels : ["push"],
          enabled: formData.enabled,
          variables: formData.variables,
        });
        toast.success("Template created successfully");
      }
      setIsDialogOpen(false);
      loadTemplates();
    } catch (e) {
      toast.error(e instanceof FetchError ? e.message : "Failed to save template");
    }
  };

  const toggleChannel = (channel: string) => {
    setFormData((prev) => ({
      ...prev,
      channels: prev.channels.includes(channel)
        ? prev.channels.filter((c) => c !== channel)
        : [...prev.channels, channel],
    }));
  };

  const notificationTypes = [
    { value: 'appointment_reminder', label: 'Appointment Reminder' },
    { value: 'appointment_cancelled', label: 'Appointment Cancelled' },
    { value: 'appointment_rescheduled', label: 'Appointment Rescheduled' },
    { value: 'new_appointment', label: 'New Appointment' },
    { value: 'payment_received', label: 'Payment Received' },
    { value: 'payout_processed', label: 'Payout Processed' },
    { value: 'refund_processed', label: 'Refund Processed' },
    { value: 'new_client', label: 'New Client' },
    { value: 'client_message', label: 'Client Message' },
    { value: 'staff_clock_in', label: 'Staff Clock In' },
    { value: 'staff_clock_out', label: 'Staff Clock Out' },
    { value: 'shift_reminder', label: 'Shift Reminder' },
    { value: 'service_booking', label: 'Service Booking' },
    { value: 'product_order', label: 'Product Order' },
    { value: 'team_member_added', label: 'Team Member Added' },
    { value: 'team_member_updated', label: 'Team Member Updated' },
    { value: 'system_update', label: 'System Update' },
    { value: 'maintenance', label: 'Maintenance' },
    { value: 'report_ready', label: 'Report Ready' },
    { value: 'document_ready', label: 'Document Ready' },
    { value: 'payment_failed', label: 'Payment Failed' },
    { value: 'subscription_expiring', label: 'Subscription Expiring' },
    { value: 'account_verification', label: 'Account Verification' },
    { value: 'high_priority', label: 'High Priority' },
  ];

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
    <SettingsDetailLayout
      title="Notification Templates"
      subtitle="Single place for all notification content: push, email, and SMS. Each template has a key and channel-specific text (title, body, email_subject/email_body, sms_body)."
      showCloseButton={false}
    >
      <div className="space-y-4 sm:space-y-6">
        <p className="text-sm text-amber-700 bg-amber-50 border border-amber-200 rounded-md px-3 py-2">
          <strong>Note:</strong> Email Templates and SMS Templates (legacy) are no longer in the menu. Edit email and SMS copy here per template (email_subject, email_body, sms_body). Sending uses only this table.
        </p>
        <div className="flex justify-end">
          <Button
            onClick={handleCreate}
            className="bg-[#FF0077] hover:bg-[#D60565] min-h-[44px] touch-manipulation"
          >
            <Plus className="w-4 h-4 mr-2" />
            Create Template
          </Button>
        </div>

        {isLoading ? (
          <SectionCard>
            <Skeleton className="h-64 w-full" />
          </SectionCard>
        ) : templates.length === 0 ? (
          <SectionCard className="p-8 sm:p-12 text-center">
            <Bell className="w-12 h-12 sm:w-16 sm:h-16 text-gray-300 mx-auto mb-4" />
            <p className="text-gray-600 mb-4">No notification templates found</p>
            <Button onClick={handleCreate} className="min-h-[44px] touch-manipulation">
              <Plus className="w-4 h-4 mr-2" />
              Create Template
            </Button>
          </SectionCard>
        ) : (
          <SectionCard className="p-0 overflow-hidden">
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Name</TableHead>
                    <TableHead>Type</TableHead>
                    <TableHead>Priority</TableHead>
                    <TableHead>Channels</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {templates.map((template) => (
                    <TableRow key={template.id}>
                      <TableCell className="font-medium">{template.name}</TableCell>
                      <TableCell>
                        <Badge variant="outline">{template.type}</Badge>
                      </TableCell>
                      <TableCell>
                        <Badge
                          className={
                            template.priority === 'high'
                              ? 'bg-red-100 text-red-800'
                              : template.priority === 'medium'
                              ? 'bg-yellow-100 text-yellow-800'
                              : 'bg-blue-100 text-blue-800'
                          }
                        >
                          {template.priority}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-1 flex-wrap">
                          {template.channels.map((channel) => (
                            <Badge key={channel} variant="outline" className="text-xs">
                              {channel}
                            </Badge>
                          ))}
                        </div>
                      </TableCell>
                      <TableCell>
                        {template.enabled ? (
                          <Badge className="bg-green-100 text-green-800">Enabled</Badge>
                        ) : (
                          <Badge variant="outline">Disabled</Badge>
                        )}
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex items-center justify-end gap-2">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleEdit(template)}
                            className="min-h-[36px] touch-manipulation"
                          >
                            <Edit className="w-4 h-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleDelete(template.id)}
                            className="text-red-600 hover:text-red-700 min-h-[36px] touch-manipulation"
                          >
                            <Trash2 className="w-4 h-4" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </SectionCard>
        )}
      </div>

      {/* Create/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-[95vw] sm:max-w-3xl max-h-[95vh] overflow-y-auto p-4 sm:p-6">
          <DialogHeader>
            <DialogTitle className="text-base sm:text-lg font-semibold">
              {editingTemplate ? "Edit Template" : "Create Template"}
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-4 sm:space-y-6">
            <div>
              <Label htmlFor="key" className="text-sm sm:text-base">Key (unique identifier) *</Label>
              <Input
                id="key"
                value={formData.key}
                onChange={(e) => setFormData({ ...formData, key: e.target.value })}
                className="mt-1.5 min-h-[44px] touch-manipulation"
                placeholder="e.g. booking_confirmed or my_custom_alert"
                required
                readOnly={!!editingTemplate}
                disabled={!!editingTemplate}
              />
              {editingTemplate ? (
                <p className="text-xs text-gray-500 mt-1.5">Key cannot be changed when editing.</p>
              ) : (
                <p className="text-xs text-gray-500 mt-1.5">Lowercase, use underscores. Must be unique.</p>
              )}
            </div>

            <div>
              <Label htmlFor="name" className="text-sm sm:text-base">Template Name (display)</Label>
              <Input
                id="name"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                className="mt-1.5 min-h-[44px] touch-manipulation"
                placeholder="e.g., Appointment Reminder"
              />
            </div>

            <div>
              <Label htmlFor="type" className="text-sm sm:text-base">Notification Type *</Label>
              <Select
                value={formData.type}
                onValueChange={(value) => setFormData({ ...formData, type: value })}
              >
                <SelectTrigger className="mt-1.5 min-h-[44px] touch-manipulation">
                  <SelectValue placeholder="Select type" />
                </SelectTrigger>
                <SelectContent>
                  {notificationTypes.map((type) => (
                    <SelectItem key={type.value} value={type.value}>
                      {type.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label htmlFor="title_template" className="text-sm sm:text-base">Title Template *</Label>
              <Input
                id="title_template"
                value={formData.title_template}
                onChange={(e) => setFormData({ ...formData, title_template: e.target.value })}
                className="mt-1.5 min-h-[44px] touch-manipulation"
                placeholder="e.g., Appointment Reminder: {{service_name}}"
                required
              />
              <p className="text-xs text-gray-500 mt-1.5">
                Use {`{{variable_name}}`} for dynamic content
              </p>
            </div>

            <div>
              <Label htmlFor="message_template" className="text-sm sm:text-base">Message Template *</Label>
              <Textarea
                id="message_template"
                value={formData.message_template}
                onChange={(e) => setFormData({ ...formData, message_template: e.target.value })}
                className="mt-1.5 min-h-[100px] touch-manipulation"
                placeholder="e.g., Your appointment for {{service_name}} is scheduled for {{appointment_date}} at {{appointment_time}}."
                required
              />
              <p className="text-xs text-gray-500 mt-1.5">
                Use {`{{variable_name}}`} for dynamic content
              </p>
            </div>

            <div>
              <Label htmlFor="priority" className="text-sm sm:text-base">Priority *</Label>
              <Select
                value={formData.priority}
                onValueChange={(value: any) => setFormData({ ...formData, priority: value })}
              >
                <SelectTrigger className="mt-1.5 min-h-[44px] touch-manipulation">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="low">Low</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="high">High</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label className="text-sm sm:text-base mb-2 block">Channels *</Label>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                {['email', 'sms', 'push', 'in_app'].map((channel) => (
                  <div
                    key={channel}
                    className="flex items-center gap-2 p-3 border rounded-lg cursor-pointer hover:bg-gray-50"
                    onClick={() => toggleChannel(channel)}
                  >
                    <input
                      type="checkbox"
                      checked={formData.channels.includes(channel)}
                      onChange={() => toggleChannel(channel)}
                      className="w-4 h-4"
                    />
                    <div className="flex items-center gap-2">
                      {channel === 'email' && <Mail className="w-4 h-4" />}
                      {channel === 'sms' && <MessageSquare className="w-4 h-4" />}
                      {channel === 'push' && <Smartphone className="w-4 h-4" />}
                      {channel === 'in_app' && <Bell className="w-4 h-4" />}
                      <span className="text-sm capitalize">{channel}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="flex items-start gap-4 p-4 bg-gray-50 rounded-lg">
              <Switch
                checked={formData.enabled}
                onCheckedChange={(checked) => setFormData({ ...formData, enabled: checked })}
                className="mt-1"
              />
              <div className="flex-1">
                <Label className="text-sm sm:text-base font-medium cursor-pointer">
                  Enabled
                </Label>
                <p className="text-xs text-gray-500 mt-1">
                  Enable this template to send notifications
                </p>
              </div>
            </div>
          </div>

          <DialogFooter className="flex-col-reverse sm:flex-row gap-2 -mx-4 sm:-mx-6 px-4 sm:px-6 pt-4 border-t">
            <Button
              variant="outline"
              onClick={() => setIsDialogOpen(false)}
              className="w-full sm:w-auto min-h-[44px] touch-manipulation"
            >
              Cancel
            </Button>
            <Button
              onClick={handleSave}
              className="w-full sm:w-auto bg-[#FF0077] hover:bg-[#D60565] min-h-[44px] touch-manipulation"
            >
              {editingTemplate ? "Update" : "Create"} Template
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </SettingsDetailLayout>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Bell,
  Send,
  FileText,
  Search,
  Plus,
  Edit,
  Trash2,
} from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface NotificationTemplate {
  id: string;
  key: string;
  title: string;
  body: string;
  channels: string[];
  email_subject?: string | null;
  email_body?: string | null;
  sms_body?: string | null;
  live_activities_config?: Record<string, any> | null;
  variables: string[];
  url: string | null;
  image?: string | null;
  onesignal_template_id?: string | null;
  enabled: boolean;
  description?: string | null;
}

interface NotificationLog {
  id: string;
  event_type: string;
  recipients: string;
  payload: {
    title: string;
    message: string;
  };
  status: "sent" | "failed";
  provider_response: any;
  created_at: string;
}

export default function AdminNotifications() {
  const [activeTab, setActiveTab] = useState<"send" | "templates" | "logs">("send");
  const [templates, setTemplates] = useState<NotificationTemplate[]>([]);
  const [logs, setLogs] = useState<NotificationLog[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showTemplateDialog, setShowTemplateDialog] = useState(false);
  const [editingTemplate, setEditingTemplate] = useState<NotificationTemplate | null>(null);

  useEffect(() => {
    loadData();
  }, [activeTab]); // eslint-disable-line react-hooks/exhaustive-deps -- load when tab changes

  const loadData = async () => {
    try {
      setIsLoading(true);
      setError(null);

      if (activeTab === "templates") {
        const response = await fetcher.get<{ data: NotificationTemplate[]; error: null }>(
          "/api/admin/notifications/templates"
        );
        setTemplates(response.data || []);
      } else if (activeTab === "logs") {
        const response = await fetcher.get<{
          data: NotificationLog[];
          error: null;
          meta: any;
        }>("/api/admin/notifications/logs");
        setLogs(response.data || []);
      }
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load data";
      setError(errorMessage);
      console.error("Error loading data:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteTemplate = async (id: string) => {
    if (!confirm("Are you sure you want to delete this template?")) return;
    try {
      await fetcher.delete(`/api/admin/notifications/templates/${id}`);
      toast.success("Template deleted");
      loadData();
    } catch {
      toast.error("Failed to delete template");
    }
  };

  if (isLoading && activeTab !== "send") {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading notifications..." />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]}>
      <div className="container mx-auto px-3 sm:px-4 py-4 sm:py-8">
        <div className="mb-4 sm:mb-6">
          <h1 className="text-2xl sm:text-3xl font-semibold mb-1 sm:mb-2">Notifications</h1>
          <p className="text-sm sm:text-base text-gray-600">Send notifications and manage templates</p>
        </div>

        <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as any)}>
          <TabsList className="mb-6">
            <TabsTrigger value="send">
              <Send className="w-4 h-4 mr-2" />
              Send Notification
            </TabsTrigger>
            <TabsTrigger value="templates">
              <FileText className="w-4 h-4 mr-2" />
              Templates
            </TabsTrigger>
            <TabsTrigger value="logs">
              <Bell className="w-4 h-4 mr-2" />
              Logs
            </TabsTrigger>
          </TabsList>

          <TabsContent value="send">
            <SendNotificationTab onSend={() => loadData()} />
          </TabsContent>

          <TabsContent value="templates">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-semibold">Notification Templates</h2>
              <Button onClick={() => setShowTemplateDialog(true)}>
                <Plus className="w-4 h-4 mr-2" />
                Add Template
              </Button>
            </div>
            {error ? (
              <EmptyState
                title="Failed to load templates"
                description={error}
                action={{ label: "Retry", onClick: loadData }}
              />
            ) : templates.length === 0 ? (
              <EmptyState
                title="No templates yet"
                description="Create your first notification template"
                action={{
                  label: "Add Template",
                  onClick: () => setShowTemplateDialog(true),
                }}
              />
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {templates.map((template) => (
                  <TemplateCard
                    key={template.id}
                    template={template}
                    onEdit={() => {
                      setEditingTemplate(template);
                      setShowTemplateDialog(true);
                    }}
                    onDelete={() => handleDeleteTemplate(template.id)}
                  />
                ))}
              </div>
            )}
          </TabsContent>

          <TabsContent value="logs">
            <div className="mb-6">
              <h2 className="text-xl font-semibold mb-4">Notification Logs</h2>
            </div>
            {error ? (
              <EmptyState
                title="Failed to load logs"
                description={error}
                action={{ label: "Retry", onClick: loadData }}
              />
            ) : logs.length === 0 ? (
              <EmptyState title="No notification logs" description="No notifications sent yet" />
            ) : (
              <div className="bg-white border rounded-lg overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead className="bg-gray-50 border-b">
                      <tr>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                          Date
                        </th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                          Type
                        </th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                          Title
                        </th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                          Recipients
                        </th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                          Status
                        </th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200">
                      {logs.map((log) => (
                        <tr key={log.id} className="hover:bg-gray-50">
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                            {new Date(log.created_at).toLocaleString()}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 capitalize">
                            {log.event_type}
                          </td>
                          <td className="px-6 py-4 text-sm text-gray-900">
                            {log.payload.title}
                          </td>
                          <td className="px-6 py-4 text-sm text-gray-500">
                            {log.recipients.length > 50
                              ? `${log.recipients.slice(0, 50)}...`
                              : log.recipients}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <Badge
                              className={
                                log.status === "sent"
                                  ? "bg-green-100 text-green-800"
                                  : "bg-red-100 text-red-800"
                              }
                            >
                              {log.status}
                            </Badge>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </TabsContent>
        </Tabs>

        {/* Template Dialog */}
        {showTemplateDialog && (
          <TemplateDialog
            template={editingTemplate}
            onClose={() => {
              setShowTemplateDialog(false);
              setEditingTemplate(null);
            }}
            onSave={() => {
              setShowTemplateDialog(false);
              setEditingTemplate(null);
              loadData();
            }}
          />
        )}
      </div>
    </RoleGuard>
  );
}

function SendNotificationTab({ onSend }: { onSend: () => void }) {
  const [type, setType] = useState<"user" | "users" | "segment" | "template" | "broadcast" | "scheduled">("user");
  const [userId, setUserId] = useState("");
  const [userSearch, setUserSearch] = useState(""); // Email or phone for search
  const [userSearchResult, setUserSearchResult] = useState<{ id: string; email: string; phone: string | null; full_name: string | null } | null>(null);
  const [isSearching, setIsSearching] = useState(false);
  const [userIds, setUserIds] = useState("");
  const [templateKey, setTemplateKey] = useState("");
  const [channels, setChannels] = useState<string[]>(["push"]);
  const [title, setTitle] = useState("");
  const [message, setMessage] = useState("");
  const [emailSubject, setEmailSubject] = useState("");
  const [emailBody, setEmailBody] = useState("");
  const [smsBody, setSmsBody] = useState("");
  const [url, setUrl] = useState("");
  const [image, setImage] = useState("");
  const [isSending, setIsSending] = useState(false);
  const [broadcastTarget, setBroadcastTarget] = useState<"all" | "customers" | "providers">("all");
  const [segmentFilters, setSegmentFilters] = useState({
    role: "",
    city: "",
    country: "",
    verified: "",
  });
  const [scheduledDate, setScheduledDate] = useState("");
  const [scheduledTime, setScheduledTime] = useState("");

  const handleSearchUser = async () => {
    if (!userSearch.trim()) {
      toast.error("Please enter an email or phone number");
      return;
    }

    setIsSearching(true);
    try {
      const response = await fetcher.get<{ data: { id: string; email: string; phone: string | null; full_name: string | null } }>(
        `/api/admin/users/search?q=${encodeURIComponent(userSearch.trim())}`
      );
      setUserSearchResult(response.data);
      setUserId(response.data.id);
      toast.success("User found!");
    } catch {
      setUserSearchResult(null);
      setUserId("");
      toast.error("User not found. Please check the email or phone number.");
    } finally {
      setIsSearching(false);
    }
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setIsSending(true);

      const payload: any = { type };

      payload.channels = channels;

      if (type === "user") {
        if (!userId) {
          toast.error("Please search for a user first");
          return;
        }
        payload.user_id = userId;
        payload.title = title;
        payload.message = message;
