      setUserId("");
      setUserSearch("");
      setUserSearchResult(null);
      setUserIds("");
      setTitle("");
      setMessage("");
      setEmailSubject("");
      setEmailBody("");
      setSmsBody("");
      setUrl("");
      setImage("");
      setChannels(["push"]);
    } catch (e) {
      toast.error(e instanceof FetchError ? e.message : "Failed to send notification");
