                placeholder="uuid1, uuid2, uuid3"
                required
              />
            </div>
            <div>
              <Label htmlFor="channels">Channels (optional - uses template channels if not specified)</Label>
              <div className="mt-2 space-y-2">
                <div className="flex flex-wrap gap-4">
                  {[
                    { value: "push", label: "Push Notification", icon: "≡ƒô▒", desc: "Browser/Mobile push notifications" },
                    { value: "email", label: "Email", icon: "≡ƒôº", desc: "Email notification via OneSignal" },
                    { value: "sms", label: "SMS", icon: "≡ƒÆ¼", desc: "Text message (SMS) - not WhatsApp" },
                    { value: "live_activities", label: "Live Activities", icon: "≡ƒö┤", desc: "iOS Live Activities only" },
                  ].map((channel) => (
                    <label key={channel.value} className="flex items-start gap-2 p-3 border rounded-md cursor-pointer hover:bg-gray-50 transition-colors w-full sm:w-auto">
                      <input
                        type="checkbox"
                        checked={channels.includes(channel.value)}
                        onChange={(e) => {
                          if (e.target.checked) {
                            setChannels([...channels, channel.value]);
                          } else {
                            setChannels(channels.filter((c) => c !== channel.value));
                          }
                        }}
                        className="mt-1"
                      />
                      <div className="flex-1">
                        <div className="flex items-center gap-1">
                          <span className="text-lg">{channel.icon}</span>
                          <span className="font-medium text-sm sm:text-base capitalize">{channel.label}</span>
                        </div>
                        <p className="text-xs text-gray-500 mt-0.5">{channel.desc}</p>
                      </div>
                    </label>
                  ))}
                </div>
              </div>
            </div>
          </>
        )}

        {type === "scheduled" && (
          <>
            <div>
              <Label htmlFor="user_ids">User IDs (comma-separated) *</Label>
              <Input
                id="user_ids"
                value={userIds}
                onChange={(e) => setUserIds(e.target.value)}
                placeholder="uuid1, uuid2, uuid3"
                required
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="scheduled_date">Schedule Date *</Label>
                <Input
                  id="scheduled_date"
                  type="date"
                  value={scheduledDate}
                  onChange={(e) => setScheduledDate(e.target.value)}
                  min={new Date().toISOString().split("T")[0]}
                  required
                />
              </div>
              <div>
                <Label htmlFor="scheduled_time">Schedule Time *</Label>
                <Input
                  id="scheduled_time"
                  type="time"
                  value={scheduledTime}
                  onChange={(e) => setScheduledTime(e.target.value)}
                  required
                />
              </div>
            </div>
            <div>
              <Label htmlFor="channels">Notification Channels *</Label>
              <div className="mt-2 space-y-2">
                <div className="flex flex-wrap gap-4">
                  {[
                    { value: "push", label: "Push Notification", icon: "≡ƒô▒", desc: "Browser/Mobile push notifications" },
                    { value: "email", label: "Email", icon: "≡ƒôº", desc: "Email notification via OneSignal" },
                    { value: "sms", label: "SMS", icon: "≡ƒÆ¼", desc: "Text message (SMS) - not WhatsApp" },
                  ].map((channel) => (
                    <label key={channel.value} className="flex items-start gap-2 p-3 border rounded-md cursor-pointer hover:bg-gray-50 transition-colors w-full sm:w-auto">
                      <input
                        type="checkbox"
                        checked={channels.includes(channel.value)}
                        onChange={(e) => {
                          if (e.target.checked) {
                            setChannels([...channels, channel.value]);
                          } else {
                            setChannels(channels.filter((c) => c !== channel.value));
                          }
                        }}
                        className="mt-1"
                      />
                      <div className="flex-1">
                        <div className="flex items-center gap-1">
                          <span className="text-lg">{channel.icon}</span>
                          <span className="font-medium text-sm sm:text-base capitalize">{channel.label}</span>
                        </div>
                        <p className="text-xs text-gray-500 mt-0.5">{channel.desc}</p>
                      </div>
                    </label>
                  ))}
                </div>
              </div>
            </div>
            <div>
              <Label htmlFor="title">Title *</Label>
              <Input
                id="title"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                required
              />
            </div>
            <div>
              <Label htmlFor="message">Message *</Label>
              <textarea
                id="message"
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                className="w-full p-2 border rounded-md min-h-[100px]"
                required
              />
            </div>
          </>
        )}

        {(type !== "broadcast" && type !== "segment" && type !== "scheduled") && (
          <div>
            <Label htmlFor="url">URL (optional)</Label>
            <Input
              id="url"
              type="url"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              placeholder="https://..."
            />
          </div>
        )}

        <Button type="submit" disabled={isSending} className="bg-[#FF0077] hover:bg-[#D60565]">
          {isSending
            ? "Sending..."
            : type === "scheduled"
            ? "Schedule Notification"
            : type === "broadcast"
            ? "Send Broadcast"
            : "Send Notification"}
        </Button>
      </form>
    </div>
  );
}

function TemplateCard({
  template,
  onEdit,
  onDelete,
}: {
  template: NotificationTemplate;
  onEdit: () => void;
  onDelete: () => void;
}) {
  return (
    <div className="bg-white border rounded-lg p-6 hover:shadow-md transition-shadow">
      <div className="flex justify-between items-start mb-3">
        <div className="flex-1">
          <h3 className="font-semibold text-lg mb-1">{template.key}</h3>
          <p className="text-sm text-gray-600 mb-2">{template.title}</p>
          <p className="text-sm text-gray-500">{template.body}</p>
        </div>
        <div className="flex gap-2 ml-4">
          <Button
            variant="ghost"
            size="icon"
            onClick={onEdit}
            className="h-8 w-8 text-gray-600 hover:text-blue-600"
          >
            <Edit className="w-4 h-4" />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            onClick={onDelete}
            className="h-8 w-8 text-gray-600 hover:text-red-600"
          >
            <Trash2 className="w-4 h-4" />
          </Button>
        </div>
      </div>
      <div className="flex items-center justify-between pt-3 border-t">
        <div className="flex gap-2">
          {template.channels.map((channel) => (
            <Badge key={channel} variant="outline" className="capitalize">
              {channel}
            </Badge>
          ))}
        </div>
        <Badge
          className={
            template.enabled
              ? "bg-green-100 text-green-800"
