}

function TemplateDialog({
  template,
  onClose,
  onSave,
}: {
  template: NotificationTemplate | null;
  onClose: () => void;
  onSave: () => void;
}) {
  const [formData, setFormData] = useState({
    key: template?.key || "",
    title: template?.title || "",
    body: template?.body || "",
    channels: template?.channels || ["push"],
    email_subject: template?.email_subject || "",
    email_body: template?.email_body || "",
    sms_body: template?.sms_body || "",
    live_activities_config: template?.live_activities_config || null,
    variables: template?.variables?.join(",") || "",
    url: template?.url || "",
    image: template?.image || "",
    onesignal_template_id: template?.onesignal_template_id || "",
    enabled: template?.enabled ?? true,
    description: template?.description || "",
  });
  const [isSaving, setIsSaving] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setIsSaving(true);
      const payload = {
        ...formData,
        variables: formData.variables
          .split(",")
          .map((v) => v.trim())
          .filter((v) => v),
      };

      if (template) {
        await fetcher.put(`/api/admin/notifications/templates/${template.id}`, payload);
        toast.success("Template updated");
      } else {
        await fetcher.post("/api/admin/notifications/templates", payload);
        toast.success("Template created");
      }
      onSave();
    } catch {
      toast.error("Failed to save template");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <Dialog open={true} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{template ? "Edit Template" : "Add Template"}</DialogTitle>
          <DialogDescription>
            Create a reusable notification template with variables
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="key">Template Key *</Label>
            <Input
              id="key"
              value={formData.key}
              onChange={(e) => setFormData({ ...formData, key: e.target.value })}
              required
              disabled={!!template}
            />
          </div>
          <div>
            <Label htmlFor="title">Title *</Label>
            <Input
              id="title"
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
              required
            />
          </div>
          <div>
            <Label htmlFor="channels">Channels *</Label>
            <div className="flex gap-4 mt-2">
              {["push", "email", "sms", "live_activities"].map((channel) => (
                <label key={channel} className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={formData.channels.includes(channel)}
                    onChange={(e) => {
                      if (e.target.checked) {
                        setFormData({ ...formData, channels: [...formData.channels, channel] });
                      } else {
                        setFormData({ ...formData, channels: formData.channels.filter((c) => c !== channel) });
                      }
                    }}
                  />
                  <span className="capitalize">{channel.replace("_", " ")}</span>
                </label>
              ))}
            </div>
          </div>
          <div>
            <Label htmlFor="body">Body (Push) *</Label>
            <textarea
              id="body"
              value={formData.body}
              onChange={(e) => setFormData({ ...formData, body: e.target.value })}
              className="w-full p-2 border rounded-md min-h-[100px]"
              required
            />
          </div>
          {formData.channels.includes("email") && (
            <>
              <div>
                <Label htmlFor="email_subject">Email Subject</Label>
                <Input
                  id="email_subject"
                  value={formData.email_subject}
                  onChange={(e) => setFormData({ ...formData, email_subject: e.target.value })}
                  placeholder="Leave empty to use title"
                />
              </div>
              <div>
                <Label htmlFor="email_body">Email Body</Label>
                <textarea
                  id="email_body"
                  value={formData.email_body}
                  onChange={(e) => setFormData({ ...formData, email_body: e.target.value })}
                  className="w-full p-2 border rounded-md min-h-[150px]"
                  placeholder="Leave empty to use body (supports HTML)"
                />
              </div>
            </>
          )}
          {formData.channels.includes("sms") && (
            <div>
              <Label htmlFor="sms_body">SMS Body</Label>
              <textarea
                id="sms_body"
                value={formData.sms_body}
                onChange={(e) => setFormData({ ...formData, sms_body: e.target.value })}
                className="w-full p-2 border rounded-md min-h-[80px]"
                placeholder="Leave empty to use body (160 chars for single SMS)"
                maxLength={1600}
              />
              <p className="text-xs text-gray-500 mt-1">
                {formData.sms_body.length || formData.body.length} characters
              </p>
            </div>
          )}
          {formData.channels.includes("live_activities") && (
            <div>
              <Label htmlFor="live_activities_config">Live Activities Config (JSON)</Label>
              <textarea
                id="live_activities_config"
                value={formData.live_activities_config ? JSON.stringify(formData.live_activities_config, null, 2) : ""}
                onChange={(e) => {
                  try {
                    const parsed = e.target.value ? JSON.parse(e.target.value) : null;
                    setFormData({ ...formData, live_activities_config: parsed });
                  } catch {
                    // Invalid JSON, keep as is
                  }
                }}
                className="w-full p-2 border rounded-md min-h-[100px] font-mono text-sm"
                placeholder='{"event": "update", "priority": "active"}'
              />
            </div>
          )}
          <div>
            <Label htmlFor="variables">Variables (comma-separated)</Label>
            <Input
              id="variables"
              value={formData.variables}
              onChange={(e) => setFormData({ ...formData, variables: e.target.value })}
              placeholder="name, amount, booking_number"
            />
            <p className="text-xs text-gray-500 mt-1">
              Use {"{{variable_name}}"} in title/body to insert variables
            </p>
          </div>
          <div>
            <Label htmlFor="url">Deep Link URL (optional)</Label>
            <Input
              id="url"
              type="url"
              value={formData.url}
              onChange={(e) => setFormData({ ...formData, url: e.target.value })}
              placeholder="https://..."
            />
          </div>
          <div>
            <Label htmlFor="image">Image URL (optional)</Label>
            <Input
              id="image"
              type="url"
              value={formData.image}
              onChange={(e) => setFormData({ ...formData, image: e.target.value })}
              placeholder="https://..."
            />
          </div>
          <div>
            <Label htmlFor="onesignal_template_id">OneSignal Template ID (optional)</Label>
            <Input
              id="onesignal_template_id"
              value={formData.onesignal_template_id}
              onChange={(e) => setFormData({ ...formData, onesignal_template_id: e.target.value })}
              placeholder="If using OneSignal's template system"
            />
          </div>
          <div>
            <Label htmlFor="description">Description (optional)</Label>
            <textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              className="w-full p-2 border rounded-md min-h-[60px]"
              placeholder="Template description for admin reference"
            />
          </div>
          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="enabled"
              checked={formData.enabled}
              onChange={(e) => setFormData({ ...formData, enabled: e.target.checked })}
            />
            <Label htmlFor="enabled">Enabled</Label>
          </div>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit" disabled={isSaving}>
              {isSaving ? "Saving..." : template ? "Update" : "Create"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Plus, Edit, Trash2, Search, Tag, Calendar, Percent } from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";

interface Promotion {
  id: string;
  name: string;
  code: string;
  type: "percentage" | "fixed_amount";
  value: number;
  min_purchase?: number;
  max_discount?: number;
  start_date: string;
  end_date: string;
  usage_limit?: number;
  used_count: number;
  is_active: boolean;
  applicable_to: "all" | "category" | "provider" | "service";
}

export default function AdminPromotions() {
  const [promotions, setPromotions] = useState<Promotion[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingPromotion, setEditingPromotion] = useState<Promotion | null>(null);

  useEffect(() => {
    loadPromotions();
  }, []);

  const loadPromotions = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetcher.get<{ data: Promotion[] }>(
        "/api/admin/promotions"
      );
      setPromotions(response.data);
    } catch (e) {
      const errorMessage =
        e instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : e instanceof FetchError
          ? e.message
          : "Failed to load promotions";
      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this promotion?")) return;

    try {
      await fetcher.delete(`/api/admin/promotions/${id}`);
      toast.success("Promotion deleted");
      loadPromotions();
    } catch {
      toast.error("Failed to delete promotion");
    }
  };

  const filteredPromotions = promotions.filter((promo) =>
    (promo.name ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
    (promo.code ?? "").toLowerCase().includes(searchQuery.toLowerCase())
  );

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading promotions..." />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-6">
          <div>
            <h1 className="text-3xl font-semibold mb-2">Promotions & Discounts</h1>
            <p className="text-gray-600">Manage platform-wide promotions and coupon codes</p>
          </div>
          <Button onClick={() => setShowAddModal(true)}>
            <Plus className="w-4 h-4 mr-2" />
            Create Promotion
          </Button>
        </div>

        {/* Search */}
        <div className="mb-6">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
            <Input
              placeholder="Search promotions by name or code..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10"
            />
          </div>
        </div>

        {/* Promotions List */}
        {error ? (
          <EmptyState
            title="Failed to load promotions"
            description={error}
            action={{
              label: "Retry",
              onClick: loadPromotions,
            }}
          />
        ) : filteredPromotions.length === 0 ? (
          <EmptyState
            title="No promotions yet"
            description="Create your first promotion or discount code"
            action={{
              label: "Create Promotion",
              onClick: () => setShowAddModal(true),
            }}
          />
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {filteredPromotions.map((promotion) => (
              <PromotionCard
                key={promotion.id}
                promotion={promotion}
                onEdit={() => setEditingPromotion(promotion)}
                onDelete={() => handleDelete(promotion.id)}
              />
            ))}
          </div>
        )}

        {/* Add/Edit Modal */}
        {(showAddModal || editingPromotion) && (
          <PromotionModal
            promotion={editingPromotion}
            onClose={() => {
              setShowAddModal(false);
              setEditingPromotion(null);
            }}
            onSave={() => {
              setShowAddModal(false);
              setEditingPromotion(null);
              loadPromotions();
            }}
          />
        )}
      </div>
    </RoleGuard>
  );
}

function PromotionCard({
  promotion,
  onEdit,
  onDelete,
}: {
  promotion: Promotion;
  onEdit: () => void;
  onDelete: () => void;
}) {
  const isExpired = new Date(promotion.end_date) < new Date();
  const isActive = promotion.is_active && !isExpired;

  return (
    <div className="bg-white border rounded-lg p-6 hover:shadow-md transition-shadow">
      <div className="flex justify-between items-start mb-4">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-blue-100 rounded-lg">
            <Tag className="w-5 h-5 text-blue-600" />
          </div>
          <div>
            <h3 className="font-semibold text-lg">{promotion.name}</h3>
            <p className="text-sm text-gray-600 font-mono">{promotion.code}</p>
          </div>
        </div>
        <div className="flex gap-2">
          <Button
            variant="ghost"
            size="icon"
            onClick={onEdit}
            className="h-8 w-8 text-gray-600 hover:text-blue-600"
          >
            <Edit className="w-4 h-4" />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            onClick={onDelete}
            className="h-8 w-8 text-gray-600 hover:text-red-600"
          >
            <Trash2 className="w-4 h-4" />
          </Button>
        </div>
      </div>

      <div className="space-y-2 text-sm mb-4">
        <div className="flex items-center gap-2">
          <Percent className="w-4 h-4 text-gray-400" />
          <span>
            {promotion.type === "percentage"
              ? `${promotion.value}% off`
              : `${promotion.value} ${promotion.type === "fixed_amount" ? "ZAR" : ""} off`}
          </span>
        </div>
        <div className="flex items-center gap-2">
          <Calendar className="w-4 h-4 text-gray-400" />
          <span>
            {new Date(promotion.start_date).toLocaleDateString()} -{" "}
            {new Date(promotion.end_date).toLocaleDateString()}
          </span>
        </div>
        {promotion.usage_limit && (
          <div>
            <span className="text-gray-600">Usage: </span>
            <span>
              {promotion.used_count} / {promotion.usage_limit}
            </span>
          </div>
        )}
      </div>

      <div className="flex items-center justify-between pt-4 border-t">
        <span
          className={`px-2 py-1 rounded text-xs font-medium ${
            isActive
              ? "bg-green-100 text-green-800"
              : isExpired
              ? "bg-red-100 text-red-800"
              : "bg-gray-100 text-gray-800"
          }`}
        >
          {isActive ? "Active" : isExpired ? "Expired" : "Inactive"}
        </span>
        <span className="text-xs text-gray-600 capitalize">
          {promotion.applicable_to}
        </span>
      </div>
    </div>
  );
}

function PromotionModal({
  promotion,
  onClose,
  onSave,
}: {
  promotion: Promotion | null;
  onClose: () => void;
  onSave: () => void;
}) {
  const [formData, setFormData] = useState({
    name: promotion?.name || "",
    code: promotion?.code || "",
    type: promotion?.type || "percentage",
    value: promotion?.value || 0,
    min_purchase: promotion?.min_purchase || 0,
    max_discount: promotion?.max_discount || 0,
    start_date: promotion?.start_date
      ? new Date(promotion.start_date).toISOString().split("T")[0]
      : "",
    end_date: promotion?.end_date
      ? new Date(promotion.end_date).toISOString().split("T")[0]
      : "",
    usage_limit: promotion?.usage_limit || 0,
    is_active: promotion?.is_active ?? true,
    applicable_to: promotion?.applicable_to || "all",
  });
  const [isSaving, setIsSaving] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setIsSaving(true);
      if (promotion) {
        await fetcher.patch(`/api/admin/promotions/${promotion.id}`, formData);
      } else {
        await fetcher.post("/api/admin/promotions", formData);
      }
      toast.success(promotion ? "Promotion updated" : "Promotion created");
      onSave();
    } catch {
      toast.error("Failed to save promotion");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-2xl font-semibold mb-4">
          {promotion ? "Edit Promotion" : "Create Promotion"}
        </h2>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="name">Promotion Name *</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              required
            />
          </div>

          <div>
            <Label htmlFor="code">Promo Code *</Label>
            <Input
              id="code"
              value={formData.code}
              onChange={(e) =>
                setFormData({ ...formData, code: e.target.value.toUpperCase() })
              }
              required
              className="font-mono"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="type">Discount Type *</Label>
              <select
                id="type"
                value={formData.type}
                onChange={(e) =>
                  setFormData({ ...formData, type: e.target.value as any })
                }
                className="w-full p-2 border rounded-md"
                required
              >
                <option value="percentage">Percentage</option>
                <option value="fixed_amount">Fixed Amount</option>
              </select>
            </div>
            <div>
              <Label htmlFor="value">Discount Value *</Label>
              <Input
                id="value"
                type="number"
                step="0.01"
                value={formData.value}
                onChange={(e) =>
                  setFormData({ ...formData, value: parseFloat(e.target.value) })
                }
                required
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="start_date">Start Date *</Label>
              <Input
                id="start_date"
                type="date"
                value={formData.start_date}
                onChange={(e) =>
                  setFormData({ ...formData, start_date: e.target.value })
                }
                required
              />
            </div>
            <div>
              <Label htmlFor="end_date">End Date *</Label>
              <Input
                id="end_date"
                type="date"
                value={formData.end_date}
                onChange={(e) =>
                  setFormData({ ...formData, end_date: e.target.value })
                }
                required
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="min_purchase">Minimum Purchase (ZAR)</Label>
              <Input
                id="min_purchase"
                type="number"
                step="0.01"
                value={formData.min_purchase}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    min_purchase: parseFloat(e.target.value),
                  })
                }
              />
            </div>
            <div>
              <Label htmlFor="max_discount">Max Discount (ZAR)</Label>
              <Input
                id="max_discount"
                type="number"
                step="0.01"
                value={formData.max_discount}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    max_discount: parseFloat(e.target.value),
                  })
                }
              />
            </div>
          </div>

          <div>
            <Label htmlFor="usage_limit">Usage Limit (0 = unlimited)</Label>
            <Input
              id="usage_limit"
              type="number"
              value={formData.usage_limit}
              onChange={(e) =>
                setFormData({
                  ...formData,
                  usage_limit: parseInt(e.target.value),
                })
              }
            />
          </div>

          <div>
            <Label htmlFor="applicable_to">Applicable To *</Label>
            <select
              id="applicable_to"
              value={formData.applicable_to}
              onChange={(e) =>
                setFormData({ ...formData, applicable_to: e.target.value as any })
              }
              className="w-full p-2 border rounded-md"
              required
            >
              <option value="all">All Services</option>
              <option value="category">Specific Category</option>
              <option value="provider">Specific Provider</option>
              <option value="service">Specific Service</option>
            </select>
          </div>

          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="is_active"
              checked={formData.is_active}
              onChange={(e) =>
                setFormData({ ...formData, is_active: e.target.checked })
              }
            />
            <Label htmlFor="is_active">Active</Label>
          </div>

          <div className="flex gap-2 pt-4">
            <Button type="button" variant="outline" onClick={onClose} className="flex-1">
              Cancel
            </Button>
            <Button type="submit" disabled={isSaving} className="flex-1">
              {isSaving ? "Saving..." : promotion ? "Update" : "Create"}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { motion } from "framer-motion";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Mail,
  Phone,
  MapPin,
  Calendar,
  DollarSign,
  Star,
  CheckCircle2,
  XCircle,
  Edit,
  Save,
  X,
  ArrowLeft,
  CreditCard,
  Building,
} from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import Link from "next/link";

interface Provider {
  id: string;
  business_name: string;
  slug: string;
  business_type: string;
  status: string;
  is_verified: boolean;
  email: string;
  phone: string;
  description: string;
  owner: {
    id: string;
    full_name: string;
    email: string;
    phone: string;
    avatar_url: string;
  };
  locations: Array<{
    id: string;
    name: string;
    address_line1: string;
    city: string;
    country: string;
    is_primary: boolean;
  }>;
  staff: Array<{
    id: string;
    name: string;
    email: string;
    role: string;
    is_active: boolean;
  }>;
  offerings: Array<{
    id: string;
    title: string;
    name: string;
    price: number;
    duration_minutes: number;
    is_active: boolean;
  }>;
  stats: {
    booking_count: number;
    review_count: number;
    average_rating: number;
  };
  created_at: string;
  updated_at: string;
}

export default function ProviderDetailPage() {
  const params = useParams();
  const router = useRouter();
  const providerId = params.id as string;

  const [provider, setProvider] = useState<Provider | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editData, setEditData] = useState<Partial<Provider>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [showStatusDialog, setShowStatusDialog] = useState(false);
  const [statusAction, setStatusAction] = useState<"approve" | "suspend" | "reject" | "reactivate">("approve");
  const [statusReason, setStatusReason] = useState("");
  const [payoutAccounts, setPayoutAccounts] = useState<
    Array<{
      id: string;
      account_name: string;
      account_number_last4: string;
      bank_name: string | null;
      bank_code: string;
      currency: string;
      active: boolean;
    }>
  >([]);

  useEffect(() => {
    if (providerId) {
      loadProvider();
    }
  }, [providerId]); // eslint-disable-line react-hooks/exhaustive-deps -- load when providerId changes

  const loadPayoutAccounts = async (id: string) => {
    try {
      const res = await fetcher.get<{ data: typeof payoutAccounts }>(
        `/api/admin/providers/${id}/payout-accounts`
      );
      setPayoutAccounts(res.data || []);
    } catch {
      setPayoutAccounts([]);
    }
  };

  const loadProvider = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetcher.get<{ data: Provider }>(
        `/api/admin/providers/${providerId}`
      );
      setProvider(response.data);
      setEditData(response.data);
      await loadPayoutAccounts(response.data.id);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load provider";
      setError(errorMessage);
      // Don't log expected 404 (e.g. invalid id or deleted provider) as an error
      const isNotFound =
        err instanceof FetchError &&
        (err.status === 404 || err.message === "Provider not found");
      if (!isNotFound) {
        console.error("Error loading provider:", err);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!provider) return;

    try {
      setIsSaving(true);

      await fetcher.patch(`/api/admin/providers/${provider.id}`, editData);

      toast.success("Provider updated successfully");
      setIsEditing(false);
      loadProvider();
    } catch (error: any) {
      toast.error(error.message || "Failed to update provider");
    } finally {
      setIsSaving(false);
    }
  };

  const handleStatusChange = async (action: "approve" | "suspend" | "reject" | "reactivate") => {
    if (!provider) return;

    setStatusAction(action);
    setShowStatusDialog(true);
  };

  const confirmStatusChange = async () => {
    if (!provider) return;

    try {
      let newStatus = provider.status;

      switch (statusAction) {
        case "approve":
          newStatus = "active";
          break;
        case "suspend":
          newStatus = "suspended";
          break;
        case "reject":
          newStatus = "rejected";
          break;
        case "reactivate":
          newStatus = "active";
          break;
      }

      await fetcher.patch(`/api/admin/providers/${provider.id}/status`, {
        status: newStatus,
        reason: statusReason || undefined,
      });

      toast.success(`Provider ${statusAction}d successfully`);
      setShowStatusDialog(false);
      setStatusReason("");
      loadProvider();
    } catch (error: any) {
      toast.error(error.message || `Failed to ${statusAction} provider`);
    }
  };

  const handleVerification = async (verified: boolean) => {
    if (!provider) return;

    try {
      await fetcher.patch(`/api/admin/providers/${provider.id}/verify`, {
        verified,
      });

      toast.success(verified ? "Provider verified" : "Verification removed");
      loadProvider();
    } catch (error: any) {
      toast.error(error.message || "Failed to update verification");
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "active":
        return "bg-green-100 text-green-800";
      case "pending":
      case "pending_approval":
        return "bg-yellow-100 text-yellow-800";
      case "suspended":
        return "bg-red-100 text-red-800";
      case "rejected":
        return "bg-gray-100 text-gray-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <LoadingTimeout loadingMessage="Loading provider details..." />
        </div>
      </div>
    );
  }

  if (error || !provider) {
    return (
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <EmptyState
            title="Failed to load provider"
            description={error || "Provider not found"}
            action={{
              label: "Back to Providers",
              onClick: () => router.push("/admin/providers"),
            }}
          />
        </div>
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          {/* Header */}
          <div className="mb-6">
            <Link href="/admin/providers">
              <Button variant="ghost" className="mb-4">
                <ArrowLeft className="w-4 h-4 mr-2" />
                Back to Providers
              </Button>
            </Link>

            <div className="flex items-start justify-between">
              <div>
                <div className="flex items-center gap-3 mb-2">
                  <h1 className="text-3xl font-semibold text-gray-900">
                    {provider.business_name}
                  </h1>
                  <Badge className={getStatusColor(provider.status)}>
                    {provider.status}
                  </Badge>
                  {provider.is_verified && (
                    <Badge className="bg-blue-100 text-blue-800">
                      <CheckCircle2 className="w-3 h-3 mr-1" />
                      Verified
                    </Badge>
                  )}
                </div>
                <p className="text-gray-600">{provider.business_type}</p>
              </div>

              <div className="flex gap-2">
                {!isEditing ? (
                  <>
                    <Button
                      variant="outline"
                      onClick={() => setIsEditing(true)}
                    >
                      <Edit className="w-4 h-4 mr-2" />
                      Edit
                    </Button>
                    {provider.status === "pending" || provider.status === "pending_approval" ? (
                      <>
                        <Button
                          onClick={() => handleStatusChange("approve")}
                          className="bg-green-600 hover:bg-green-700"
                        >
                          <CheckCircle2 className="w-4 h-4 mr-2" />
                          Approve
                        </Button>
                        <Button
                          variant="destructive"
                          onClick={() => handleStatusChange("reject")}
                        >
                          <XCircle className="w-4 h-4 mr-2" />
                          Reject
                        </Button>
                      </>
                    ) : provider.status === "active" ? (
                      <>
                        <Button
                          variant="destructive"
                          onClick={() => handleStatusChange("suspend")}
                        >
                          Suspend
                        </Button>
                        {!provider.is_verified && (
                          <Button
                            variant="outline"
                            onClick={() => handleVerification(true)}
                          >
                            Verify
                          </Button>
                        )}
                      </>
                    ) : provider.status === "suspended" ? (
                      <Button
                        onClick={() => handleStatusChange("reactivate")}
                        className="bg-green-600 hover:bg-green-700"
                      >
                        Reactivate
                      </Button>
                    ) : null}
                  </>
                ) : (
                  <>
                    <Button
                      variant="outline"
                      onClick={() => {
                        setIsEditing(false);
                        setEditData(provider);
                      }}
                    >
                      <X className="w-4 h-4 mr-2" />
                      Cancel
                    </Button>
                    <Button
                      onClick={handleSave}
                      disabled={isSaving}
                    >
                      <Save className="w-4 h-4 mr-2" />
                      {isSaving ? "Saving..." : "Save"}
                    </Button>
                  </>
                )}
              </div>
            </div>
          </div>

          {/* Main Content */}
          <Tabs defaultValue="overview" className="w-full">
            <TabsList className="mb-6">
              <TabsTrigger value="overview">Overview</TabsTrigger>
              <TabsTrigger value="settings">Settings</TabsTrigger>
              <TabsTrigger value="staff">
                Staff ({provider.staff?.length || 0})
              </TabsTrigger>
              <TabsTrigger value="services">
                Services ({provider.offerings?.length || 0})
              </TabsTrigger>
              <TabsTrigger value="analytics">Analytics</TabsTrigger>
            </TabsList>

            <TabsContent value="overview">
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Main Info */}
                <div className="lg:col-span-2 space-y-6">
                  {/* Business Information */}
                  <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-white border rounded-lg p-6"
                  >
                    <h2 className="text-xl font-semibold mb-4">Business Information</h2>

                    {isEditing ? (
                      <div className="space-y-4">
                        <div>
                          <Label htmlFor="business_name">Business Name</Label>
                          <Input
                            id="business_name"
                            value={editData.business_name || ""}
                            onChange={(e) =>
                              setEditData({ ...editData, business_name: e.target.value })
                            }
                          />
                        </div>
                        <div>
                          <Label htmlFor="description">Description</Label>
                          <Textarea
                            id="description"
                            value={editData.description || ""}
                            onChange={(e) =>
                              setEditData({ ...editData, description: e.target.value })
                            }
                            rows={4}
                          />
                        </div>
                        <div>
                          <Label htmlFor="email">Email</Label>
                          <Input
                            id="email"
                            type="email"
                            value={editData.email || ""}
                            onChange={(e) =>
                              setEditData({ ...editData, email: e.target.value })
                            }
                          />
                        </div>
                        <div>
                          <Label htmlFor="phone">Phone</Label>
                          <Input
                            id="phone"
                            value={editData.phone || ""}
                            onChange={(e) =>
                              setEditData({ ...editData, phone: e.target.value })
                            }
                          />
                        </div>
                      </div>
                    ) : (
                      <div className="space-y-4">
                        <div>
                          <p className="text-sm text-gray-500 mb-1">Business Name</p>
                          <p className="font-medium">{provider.business_name}</p>
                        </div>
                        {provider.description && (
                          <div>
                            <p className="text-sm text-gray-500 mb-1">Description</p>
                            <p>{provider.description}</p>
                          </div>
                        )}
                        <div className="grid grid-cols-2 gap-4">
                          <div>
                            <p className="text-sm text-gray-500 mb-1">Email</p>
                            <div className="flex items-center gap-2">
                              <Mail className="w-4 h-4 text-gray-400" />
                              <p>{provider.email}</p>
                            </div>
                          </div>
                          <div>
                            <p className="text-sm text-gray-500 mb-1">Phone</p>
                            <div className="flex items-center gap-2">
                              <Phone className="w-4 h-4 text-gray-400" />
                              <p>{provider.phone || "N/A"}</p>
                            </div>
                          </div>
                        </div>
                      </div>
                    )}
                  </motion.div>

                  {/* Owner Information */}
                  <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-white border rounded-lg p-6"
                  >
                    <h2 className="text-xl font-semibold mb-4">Owner Information</h2>
                    <div className="space-y-3">
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Name</p>
                        <p className="font-medium">{provider.owner?.full_name || "N/A"}</p>
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <p className="text-sm text-gray-500 mb-1">Email</p>
                          <p>{provider.owner?.email || "N/A"}</p>
                        </div>
                        <div>
                          <p className="text-sm text-gray-500 mb-1">Phone</p>
                          <p>{provider.owner?.phone || "N/A"}</p>
                        </div>
                      </div>
                      <Link href={`/admin/users/${provider.owner?.id}`}>
                        <Button variant="outline" size="sm">
                          View Owner Profile
                        </Button>
                      </Link>
                    </div>
                  </motion.div>

                  {/* Locations */}
                  {provider.locations && provider.locations.length > 0 && (
                    <motion.div
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: 0.2 }}
                      className="bg-white border rounded-lg p-6"
                    >
                      <h2 className="text-xl font-semibold mb-4">Locations</h2>
                      <div className="space-y-3">
                        {provider.locations.map((location) => (
                          <div
                            key={location.id}
                            className="flex items-start gap-3 p-3 border rounded-lg"
                          >
                            <MapPin className="w-5 h-5 text-gray-400 mt-0.5" />
                            <div className="flex-1">
                              <p className="font-medium">{location.name}</p>
                              <p className="text-sm text-gray-600">
                                {location.address_line1}, {location.city}, {location.country}
                              </p>
                              {location.is_primary && (
                                <Badge className="mt-1 bg-blue-100 text-blue-800">
                                  Primary
                                </Badge>
                              )}
                            </div>
                          </div>
                        ))}
                      </div>
                    </motion.div>
                  )}
                </div>

                {/* Sidebar Stats */}
                <div className="space-y-6">
                  {/* Stats */}
                  <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-white border rounded-lg p-6"
                  >
                    <h2 className="text-xl font-semibold mb-4">Statistics</h2>
                    <div className="space-y-4">
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Total Bookings</p>
                        <p className="text-2xl font-semibold">
                          {provider.stats?.booking_count || 0}
                        </p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Reviews</p>
                        <div className="flex items-center gap-2">
                          <Star className="w-5 h-5 text-yellow-500" />
                          <p className="text-2xl font-semibold">
                            {provider.stats?.average_rating?.toFixed(1) || "0.0"}
                          </p>
                          <p className="text-sm text-gray-500">
                            ({provider.stats?.review_count || 0} reviews)
                          </p>
                        </div>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Staff Members</p>
                        <p className="text-2xl font-semibold">
                          {provider.staff?.length || 0}
                        </p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Services</p>
                        <p className="text-2xl font-semibold">
                          {provider.offerings?.length || 0}
                        </p>
                      </div>
                    </div>
                  </motion.div>

                  {/* Quick Actions */}
                  <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-white border rounded-lg p-6"
                  >
                    <h2 className="text-xl font-semibold mb-4">Quick Actions</h2>
                    <div className="space-y-2">
                      <Link href={`/admin/bookings?provider_id=${provider.id}`}>
                        <Button variant="outline" className="w-full justify-start">
                          <Calendar className="w-4 h-4 mr-2" />
                          View Bookings
                        </Button>
                      </Link>
                      <Link href={`/admin/reviews?provider_id=${provider.id}`}>
                        <Button variant="outline" className="w-full justify-start">
                          <Star className="w-4 h-4 mr-2" />
                          View Reviews
                        </Button>
                      </Link>
                      <Link href={`/admin/finance?provider_id=${provider.id}`}>
                        <Button variant="outline" className="w-full justify-start">
                          <DollarSign className="w-4 h-4 mr-2" />
                          View Finance
                        </Button>
                      </Link>
                      <Link href={`/admin/payouts?provider_id=${provider.id}`}>
                        <Button variant="outline" className="w-full justify-start">
                          <CreditCard className="w-4 h-4 mr-2" />
                          View Payouts
                        </Button>
                      </Link>
