                        <Badge
                          className={service.is_active ? "bg-green-100 text-green-800" : "bg-gray-100 text-gray-800"}
                        >
                          {service.is_active ? "Active" : "Inactive"}
                        </Badge>
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="text-gray-600">No services found</p>
                )}
              </div>
            </TabsContent>

            <TabsContent value="analytics">
              <div className="bg-white border rounded-lg p-6">
                <h2 className="text-xl font-semibold mb-4">Analytics</h2>
                <p className="text-gray-600">Analytics coming soon...</p>
              </div>
            </TabsContent>
          </Tabs>
        </div>

        {/* Status Change Dialog */}
        <Dialog open={showStatusDialog} onOpenChange={setShowStatusDialog}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>
                {statusAction === "approve" && "Approve Provider"}
                {statusAction === "suspend" && "Suspend Provider"}
                {statusAction === "reject" && "Reject Provider"}
                {statusAction === "reactivate" && "Reactivate Provider"}
              </DialogTitle>
              <DialogDescription>
                {statusAction === "approve" && "Are you sure you want to approve this provider?"}
                {statusAction === "suspend" && "Are you sure you want to suspend this provider?"}
                {statusAction === "reject" && "Are you sure you want to reject this provider?"}
                {statusAction === "reactivate" && "Are you sure you want to reactivate this provider?"}
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4">
              <div>
                <Label htmlFor="reason">Reason (optional)</Label>
                <Textarea
                  id="reason"
                  value={statusReason}
                  onChange={(e) => setStatusReason(e.target.value)}
                  placeholder="Enter reason for this action..."
                  rows={3}
                />
              </div>
              <div className="flex justify-end gap-2">
                <Button
                  variant="outline"
                  onClick={() => {
                    setShowStatusDialog(false);
                    setStatusReason("");
                  }}
                >
                  Cancel
                </Button>
                <Button
                  onClick={confirmStatusChange}
                  variant={statusAction === "reject" || statusAction === "suspend" ? "destructive" : "default"}
                >
                  Confirm
                </Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Search,
  Filter,
  CheckCircle2,
  XCircle,
  Building2,
  MapPin,
  Phone,
  Mail,
} from "lucide-react";
import BulkActionsBar from "@/components/admin/BulkActionsBar";
import { Checkbox } from "@/components/ui/checkbox";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { toast } from "sonner";
import Link from "next/link";

interface Provider {
  id: string;
  business_name: string;
  slug: string;
  business_type: string;
  status: "pending" | "active" | "suspended" | "rejected";
  verification_status: "unverified" | "pending" | "verified";
  owner_name: string;
  owner_email: string;
  owner_phone?: string;
  city: string;
  country: string;
  created_at: string;
  rating?: number;
  review_count?: number;
}

export default function AdminProviders() {
  const [providers, setProviders] = useState<Provider[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [showFilters, setShowFilters] = useState(false);
  const [selectedProviderIds, setSelectedProviderIds] = useState<Set<string>>(new Set());
  const [isSelectAll, setIsSelectAll] = useState(false);

  useEffect(() => {
    loadProviders();
  }, [statusFilter]); // eslint-disable-line react-hooks/exhaustive-deps -- load when filter changes

  const loadProviders = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      if (statusFilter !== "all") params.set("status", statusFilter);
      const response = await fetcher.get<{ data?: Provider[] }>(
        `/api/admin/providers?${params.toString()}`
      );
      setProviders(response.data ?? []);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load providers";
      setError(errorMessage);
      console.error("Error loading providers:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleStatusChange = async (providerId: string, newStatus: string) => {
    try {
      await fetcher.patch(`/api/admin/providers/${providerId}/status`, {
        status: newStatus,
      });
      toast.success("Provider status updated");
      loadProviders();
    } catch {
      toast.error("Failed to update provider status");
    }
  };

  const handleVerification = async (providerId: string, verified: boolean) => {
    try {
      await fetcher.patch(`/api/admin/providers/${providerId}/verify`, {
        verified,
      });
      toast.success(verified ? "Provider verified" : "Verification removed");
      loadProviders();
    } catch {
      toast.error("Failed to update verification");
    }
  };

  const handleSelectProvider = (providerId: string, checked: boolean) => {
    const newSelected = new Set(selectedProviderIds);
    if (checked) {
      newSelected.add(providerId);
    } else {
      newSelected.delete(providerId);
    }
    setSelectedProviderIds(newSelected);
    setIsSelectAll(newSelected.size === filteredProviders.length && filteredProviders.length > 0);
  };

  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      const allIds = new Set(filteredProviders.map((p) => p.id));
      setSelectedProviderIds(allIds);
      setIsSelectAll(true);
    } else {
      setSelectedProviderIds(new Set());
      setIsSelectAll(false);
    }
  };

  const handleBulkAction = async (action: string) => {
    if (selectedProviderIds.size === 0) {
      toast.error("Please select at least one provider");
      return;
    }

    const providerIds = Array.from(selectedProviderIds);

    try {
      if (!confirm(`Perform ${action} on ${providerIds.length} provider(s)?`)) return;

      await fetcher.post("/api/admin/providers/bulk", {
        provider_ids: providerIds,
        action: action === "approve" ? "approve" : action === "suspend" ? "suspend" : action === "reject" ? "reject" : action === "verify" ? "verify" : "unverify",
      });

      toast.success(`${providerIds.length} provider(s) updated`);
      setSelectedProviderIds(new Set());
      setIsSelectAll(false);
      loadProviders();
    } catch (error: any) {
      toast.error(error.message || `Failed to perform bulk ${action}`);
    }
  };

  const filteredProviders = providers.filter((provider) => {
    const matchesSearch =
      (provider.business_name ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (provider.owner_name ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (provider.owner_email ?? "").toLowerCase().includes(searchQuery.toLowerCase());
    return matchesSearch;
  });

  const groupedProviders = {
    pending: filteredProviders.filter((p) => p.status === "pending"),
    active: filteredProviders.filter((p) => p.status === "active"),
    suspended: filteredProviders.filter((p) => p.status === "suspended"),
    rejected: filteredProviders.filter((p) => p.status === "rejected"),
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <LoadingTimeout loadingMessage="Loading providers..." />
        </div>
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
            className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 md:p-8 mb-8"
          >
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-6">
              <motion.div
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.2, duration: 0.5, ease: "easeOut" }}
              >
                <h1 className="text-2xl md:text-3xl font-semibold tracking-tighter mb-2 text-gray-900">Provider Management</h1>
                <p className="text-sm md:text-base font-light text-gray-600">Manage provider accounts and approvals</p>
              </motion.div>
            </div>

            {/* Search and Filters */}
            <div className="mb-6 space-y-4">
              <div className="flex gap-4">
                <div className="relative flex-1">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                  <Input
                    placeholder="Search by business name, owner name, or email..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="pl-10 backdrop-blur-xl bg-white/80 border border-white/40 focus:border-[#FF0077] focus:ring-[#FF0077] rounded-xl"
                  />
                </div>
                <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
                  <Button
                    variant="outline"
                    onClick={() => setShowFilters(!showFilters)}
                    className="border-white/40 backdrop-blur-xl bg-white/80 hover:bg-white/90 rounded-xl"
                  >
                    <Filter className="w-4 h-4 mr-2" />
                    Filters
                  </Button>
                </motion.div>
              </div>

              {showFilters && (
                <motion.div
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4"
                >
                  <div>
                    <label className="text-sm font-medium mb-2 block text-gray-700">Status</label>
                    <select
                      value={statusFilter}
                      onChange={(e) => setStatusFilter(e.target.value)}
                      className="w-full p-2 border border-white/40 rounded-lg backdrop-blur-sm bg-white/60 focus:border-[#FF0077] focus:ring-[#FF0077]"
                    >
                      <option value="all">All Statuses</option>
                      <option value="pending">Pending</option>
                      <option value="active">Active</option>
                      <option value="suspended">Suspended</option>
                      <option value="rejected">Rejected</option>
                    </select>
                  </div>
                </motion.div>
              )}
            </div>

        {/* Bulk Actions Bar */}
        <BulkActionsBar
          selectedCount={selectedProviderIds.size}
          onClearSelection={() => {
            setSelectedProviderIds(new Set());
            setIsSelectAll(false);
          }}
          onBulkAction={handleBulkAction}
          actions={[
            { id: "approve", label: "Approve", icon: CheckCircle2, variant: "default" as const },
            { id: "suspend", label: "Suspend", icon: XCircle, variant: "outline" as const },
            { id: "reject", label: "Reject", icon: XCircle, variant: "destructive" as const },
            { id: "verify", label: "Verify", icon: CheckCircle2, variant: "default" as const },
            { id: "unverify", label: "Unverify", icon: XCircle, variant: "outline" as const },
          ]}
        />

        {/* Providers Tabs */}
        {error ? (
          <EmptyState
            title="Failed to load providers"
            description={error}
            action={{
              label: "Retry",
              onClick: loadProviders,
            }}
          />
        ) : (
            <Tabs defaultValue="pending" className="w-full">
              <TabsList className="mb-6 backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-1 shadow-lg">
                <TabsTrigger value="pending" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">
                  Pending ({groupedProviders.pending.length})
                </TabsTrigger>
                <TabsTrigger value="active" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">
                  Active ({groupedProviders.active.length})
                </TabsTrigger>
                <TabsTrigger value="suspended" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">
                  Suspended ({groupedProviders.suspended.length})
                </TabsTrigger>
                <TabsTrigger value="rejected" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">
                  Rejected ({groupedProviders.rejected.length})
                </TabsTrigger>
              </TabsList>

            <TabsContent value="pending">
              <ProvidersList
                providers={groupedProviders.pending}
                onStatusChange={handleStatusChange}
                onVerification={handleVerification}
                selectedIds={selectedProviderIds}
                onSelect={handleSelectProvider}
                isSelectAll={isSelectAll}
                onSelectAll={handleSelectAll}
              />
            </TabsContent>
            <TabsContent value="active">
              <ProvidersList
                providers={groupedProviders.active}
                onStatusChange={handleStatusChange}
                onVerification={handleVerification}
                selectedIds={selectedProviderIds}
                onSelect={handleSelectProvider}
                isSelectAll={isSelectAll}
                onSelectAll={handleSelectAll}
              />
            </TabsContent>
            <TabsContent value="suspended">
              <ProvidersList
                providers={groupedProviders.suspended}
                onStatusChange={handleStatusChange}
                onVerification={handleVerification}
                selectedIds={selectedProviderIds}
                onSelect={handleSelectProvider}
                isSelectAll={isSelectAll}
                onSelectAll={handleSelectAll}
              />
            </TabsContent>
            <TabsContent value="rejected">
              <ProvidersList
                providers={groupedProviders.rejected}
                onStatusChange={handleStatusChange}
                onVerification={handleVerification}
                selectedIds={selectedProviderIds}
                onSelect={handleSelectProvider}
                isSelectAll={isSelectAll}
                onSelectAll={handleSelectAll}
              />
            </TabsContent>
          </Tabs>
        )}
          </motion.div>
        </div>
      </div>
    </RoleGuard>
  );
}

function ProvidersList({
  providers,
  onStatusChange,
  onVerification,
  selectedIds,
  onSelect,
  isSelectAll,
  onSelectAll,
}: {
  providers: Provider[];
  onStatusChange: (id: string, status: string) => void;
  onVerification: (id: string, verified: boolean) => void;
  selectedIds: Set<string>;
  onSelect: (id: string, checked: boolean) => void;
  isSelectAll: boolean;
  onSelectAll: (checked: boolean) => void;
}) {
  void isSelectAll;
  void onSelectAll;
  if (providers.length === 0) {
    return (
      <EmptyState
        title="No providers found"
        description="No providers match these criteria"
      />
    );
  }

  return (
    <div className="space-y-4">
      {providers.map((provider) => (
        <ProviderCard
          key={provider.id}
          provider={provider}
          onStatusChange={onStatusChange}
          onVerification={onVerification}
          selected={selectedIds.has(provider.id)}
          onSelect={(checked) => onSelect(provider.id, checked)}
        />
      ))}
    </div>
  );
}

function ProviderCard({
  provider,
  onStatusChange,
  onVerification,
  selected,
  onSelect,
}: {
  provider: Provider;
  onStatusChange: (id: string, status: string) => void;
  onVerification: (id: string, verified: boolean) => void;
  selected: boolean;
  onSelect: (checked: boolean) => void;
}) {
  const getStatusColor = () => {
    switch (provider.status) {
      case "active":
        return "bg-green-100 text-green-800";
      case "pending":
        return "bg-yellow-100 text-yellow-800";
      case "suspended":
        return "bg-red-100 text-red-800";
      case "rejected":
        return "bg-gray-100 text-gray-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  const getVerificationColor = () => {
    switch (provider.verification_status) {
      case "verified":
        return "bg-blue-100 text-blue-800";
      case "pending":
        return "bg-yellow-100 text-yellow-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      whileHover={{ scale: 1.01 }}
      whileTap={{ scale: 0.99 }}
      className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-6 shadow-lg hover:shadow-xl transition-all"
    >
      <div className="flex items-start gap-3">
        <div className="pt-1" onClick={(e) => e.stopPropagation()}>
          <Checkbox checked={selected} onCheckedChange={onSelect} />
        </div>
        <div className="flex-1">
          <div className="flex flex-col md:flex-row md:items-start md:justify-between gap-4">
            <div className="flex-1">
          <div className="flex items-center gap-3 mb-3 flex-wrap">
            <div className="p-2 bg-pink-50 rounded-lg border border-pink-100">
              <Building2 className="w-5 h-5 text-[#FF0077]" />
            </div>
            <h3 className="text-lg font-semibold tracking-tight text-gray-900">{provider.business_name}</h3>
            <span className={`px-3 py-1 rounded-full text-xs font-semibold ${getStatusColor()}`}>
              {provider.status}
            </span>
            <span className={`px-3 py-1 rounded-full text-xs font-semibold ${getVerificationColor()}`}>
              {provider.verification_status}
            </span>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm text-gray-600 mb-4">
            <div>
              <p className="font-medium text-gray-900 mb-1">Owner</p>
              <p>{provider.owner_name}</p>
            </div>
            <div className="flex items-center gap-2">
              <Mail className="w-4 h-4" />
              <span>{provider.owner_email}</span>
            </div>
            {provider.owner_phone && (
              <div className="flex items-center gap-2">
                <Phone className="w-4 h-4" />
                <span>{provider.owner_phone}</span>
              </div>
            )}
            <div className="flex items-center gap-2">
              <MapPin className="w-4 h-4" />
              <span>{provider.city}, {provider.country}</span>
            </div>
          </div>

          <div className="flex items-center gap-4 text-sm">
            {provider.rating && (
              <div>
                <span className="font-medium">Rating: </span>
                <span>{provider.rating.toFixed(1)} Γ¡É</span>
              </div>
            )}
            {provider.review_count !== undefined && (
              <div>
                <span className="font-medium">Reviews: </span>
                <span>{provider.review_count}</span>
              </div>
            )}
            <div>
              <span className="font-medium">Type: </span>
              <span className="capitalize">{provider.business_type}</span>
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-2">
          {provider.status === "pending" && (
            <>
              <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
                <Button
                  onClick={() => onStatusChange(provider.id, "active")}
                  className="bg-gradient-to-r from-green-600 to-green-700 hover:from-green-700 hover:to-green-600 text-white shadow-lg"
                >
                  <CheckCircle2 className="w-4 h-4 mr-2" />
                  Approve
                </Button>
              </motion.div>
              <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
                <Button
                  variant="destructive"
                  onClick={() => onStatusChange(provider.id, "rejected")}
                  className="shadow-lg"
                >
                  <XCircle className="w-4 h-4 mr-2" />
                  Reject
                </Button>
              </motion.div>
            </>
          )}
          {provider.status === "active" && (
            <>
              <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
                <Button
                  variant="destructive"
                  onClick={() => onStatusChange(provider.id, "suspended")}
                  className="shadow-lg"
                >
                  Suspend
                </Button>
              </motion.div>
              {provider.verification_status !== "verified" ? (
                <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
                  <Button
                    variant="outline"
                    onClick={() => onVerification(provider.id, true)}
                    className="border-[#FF0077] text-[#FF0077] hover:bg-pink-50"
                  >
                    Verify
                  </Button>
                </motion.div>
              ) : (
                <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
                  <Button
                    variant="outline"
                    onClick={() => onVerification(provider.id, false)}
                    className="border-gray-400 text-gray-600 hover:bg-gray-50"
                  >
                    Unverify
                  </Button>
                </motion.div>
              )}
            </>
          )}
          {provider.status === "suspended" && (
            <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
              <Button
                onClick={() => onStatusChange(provider.id, "active")}
                className="bg-gradient-to-r from-green-600 to-green-700 hover:from-green-700 hover:to-green-600 text-white shadow-lg"
              >
                Reactivate
              </Button>
            </motion.div>
          )}
          <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
            <Link href={`/admin/providers/${provider.id}`}>
              <Button variant="outline" className="mt-2 border-white/40 backdrop-blur-sm bg-white/60 hover:bg-white/80">
                View Details
              </Button>
            </Link>
          </motion.div>
        </div>
          </div>
        </div>
      </div>
    </motion.div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Search, DollarSign } from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import { AdminFilterBar } from "@/components/admin/AdminFilterBar";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";

interface Refund {
  id: string;
  booking_id: string;
  transaction_type: string;
  amount: number;
  refund_amount: number | null;
  refund_reference: string | null;
  refund_reason: string | null;
  refunded_at: string | null;
  refunded_by: string | null;
  status: string;
  created_at: string;
  booking: {
    id: string;
    booking_number: string;
    status: string;
    total_amount: number;
    customer: { id: string; full_name: string | null; email: string };
    provider: { id: string; business_name: string };
  };
  refunded_by_user: { id: string; full_name: string | null; email: string } | null;
}

export default function AdminRefunds() {
  const [refunds, setRefunds] = useState<Refund[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [selectedRefund, setSelectedRefund] = useState<Refund | null>(null);
  const [showProcessDialog, setShowProcessDialog] = useState(false);
  const [refundAmount, setRefundAmount] = useState("");
  const [refundReason, setRefundReason] = useState("");

  useEffect(() => {
    loadRefunds();
  }, [statusFilter]); // eslint-disable-line react-hooks/exhaustive-deps -- load when filter changes

  const loadRefunds = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      if (statusFilter !== "all") params.set("status", statusFilter);

      const response = await fetcher.get<{
        data?: { refunds?: Refund[]; statistics?: any; pagination?: any };
      }>(`/api/admin/refunds?${params.toString()}`);

      setRefunds(response.data?.refunds ?? []);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load refunds";
      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleProcessRefund = async () => {
    if (!selectedRefund || !refundAmount || !refundReason) {
      toast.error("Please fill in all required fields");
      return;
    }

    try {
      await fetcher.post(`/api/admin/refunds/${selectedRefund.id}`, {
        refund_amount: parseFloat(refundAmount),
        refund_reason: refundReason,
      });

      toast.success("Refund processed successfully");
      setShowProcessDialog(false);
      setSelectedRefund(null);
      setRefundAmount("");
      setRefundReason("");
      loadRefunds();
    } catch (err) {
      toast.error(err instanceof FetchError ? err.message : "Failed to process refund");
    }
  };

  const filteredRefunds = refunds.filter((refund) => {
    const matchesSearch =
      (refund.booking?.booking_number ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (refund.booking?.customer?.full_name ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (refund.booking?.customer?.email ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (refund.refund_reference ?? "").toLowerCase().includes(searchQuery.toLowerCase());
    return matchesSearch;
  });

  const groupedRefunds = {
    all: filteredRefunds,
    success: filteredRefunds.filter((r) => r.status === "success"),
    failed: filteredRefunds.filter((r) => r.status === "failed"),
    pending: filteredRefunds.filter((r) => r.status === "pending"),
    refunded: filteredRefunds.filter((r) => r.status === "refunded"),
    partially_refunded: filteredRefunds.filter((r) => r.status === "partially_refunded"),
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading refunds..." />
      </div>
    );
  }

  if (error) {
    return (
      <div className="container mx-auto px-4 py-8">
        <EmptyState
          title="Failed to load refunds"
          description={error}
          action={{
            label: "Retry",
            onClick: loadRefunds,
          }}
        />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="space-y-6">
        <AdminPageHeader
          title="Refunds Management"
          description="Process and manage all refunds"
        />

        <AdminFilterBar>
          <div className="flex flex-col md:flex-row gap-4">
            <div className="flex-1">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                <Input
                  type="text"
                  placeholder="Search by booking number, customer, or reference..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-10"
                />
              </div>
            </div>
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg"
            >
              <option value="all">All Status</option>
              <option value="success">Success</option>
              <option value="failed">Failed</option>
              <option value="pending">Pending</option>
              <option value="refunded">Refunded</option>
              <option value="partially_refunded">Partially Refunded</option>
            </select>
          </div>
        </AdminFilterBar>

        {/* Refunds List */}
        <Tabs defaultValue="all" className="space-y-4">
          <TabsList>
            <TabsTrigger value="all">All ({groupedRefunds.all.length})</TabsTrigger>
            <TabsTrigger value="refunded">Refunded ({groupedRefunds.refunded.length})</TabsTrigger>
            <TabsTrigger value="pending">Pending ({groupedRefunds.pending.length})</TabsTrigger>
            <TabsTrigger value="failed">Failed ({groupedRefunds.failed.length})</TabsTrigger>
          </TabsList>

          <TabsContent value="all" className="space-y-4">
            <RefundList
              refunds={groupedRefunds.all}
              onProcess={(refund) => {
                setSelectedRefund(refund);
                setRefundAmount(refund.amount.toString());
                setShowProcessDialog(true);
              }}
            />
          </TabsContent>
          <TabsContent value="refunded" className="space-y-4">
            <RefundList refunds={groupedRefunds.refunded} onProcess={() => {}} />
          </TabsContent>
          <TabsContent value="pending" className="space-y-4">
            <RefundList
              refunds={groupedRefunds.pending}
              onProcess={(refund) => {
                setSelectedRefund(refund);
                setRefundAmount(refund.amount.toString());
                setShowProcessDialog(true);
              }}
            />
          </TabsContent>
          <TabsContent value="failed" className="space-y-4">
            <RefundList refunds={groupedRefunds.failed} onProcess={() => {}} />
          </TabsContent>
        </Tabs>

        {/* Process Refund Dialog */}
        <Dialog open={showProcessDialog} onOpenChange={setShowProcessDialog}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Process Refund</DialogTitle>
              <DialogDescription>
                Process a refund for this transaction. The refund amount cannot exceed the
                transaction amount.
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4">
              <div>
                <Label>Refund Amount</Label>
                <Input
                  type="number"
                  value={refundAmount}
                  onChange={(e) => setRefundAmount(e.target.value)}
                  placeholder="Enter refund amount"
                  max={selectedRefund?.amount}
                />
                <p className="text-sm text-gray-500 mt-1">
                  Transaction amount: ${selectedRefund?.amount.toFixed(2)}
                </p>
              </div>
              <div>
                <Label>Refund Reason *</Label>
                <Textarea
                  value={refundReason}
                  onChange={(e) => setRefundReason(e.target.value)}
                  placeholder="Enter reason for refund..."
                  rows={4}
                />
              </div>
              <div className="flex justify-end gap-2">
                <Button variant="outline" onClick={() => setShowProcessDialog(false)}>
                  Cancel
                </Button>
                <Button onClick={handleProcessRefund}>Process Refund</Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      </div>
    </RoleGuard>
  );
}

function RefundList({
  refunds,
  onProcess,
}: {
  refunds: Refund[];
  onProcess: (refund: Refund) => void;
}) {
  if (refunds.length === 0) {
    return (
      <div className="bg-white p-8 rounded-lg border border-gray-200 text-center">
        <DollarSign className="w-12 h-12 text-gray-400 mx-auto mb-4" />
        <p className="text-gray-600">No refunds found</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {refunds.map((refund) => (
        <div key={refund.id} className="bg-white p-6 rounded-lg border border-gray-200">
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <div className="flex items-center gap-3 mb-2">
                <Badge
                  variant={
                    refund.status === "refunded"
                      ? "default"
                      : refund.status === "failed"
                      ? "destructive"
                      : refund.status === "pending"
                      ? "secondary"
                      : "outline"
                  }
                >
                  {refund.status}
                </Badge>
                {refund.refund_amount && (
                  <Badge variant="outline">
                    ${refund.refund_amount.toFixed(2)} refunded
                  </Badge>
                )}
              </div>
              <div className="flex items-center gap-4 text-sm text-gray-600 mb-2">
                <span>
                  <strong>Booking:</strong> {refund.booking?.booking_number}
                </span>
                <span>
                  <strong>Amount:</strong> ${refund.amount.toFixed(2)}
                </span>
                <span>
                  <strong>Customer:</strong>{" "}
                  {refund.booking?.customer?.full_name || refund.booking?.customer?.email}
                </span>
                <span>
                  <strong>Provider:</strong> {refund.booking?.provider?.business_name}
                </span>
              </div>
              {refund.refund_reason && (
                <div className="text-sm text-gray-600 mb-2">
                  <strong>Reason:</strong> {refund.refund_reason}
                </div>
              )}
              {refund.refunded_at && (
                <div className="text-sm text-gray-600">
                  <strong>Refunded:</strong> {new Date(refund.refunded_at).toLocaleString()} by{" "}
                  {refund.refunded_by_user?.full_name || refund.refunded_by_user?.email}
                </div>
              )}
            </div>
            {refund.status !== "refunded" && refund.status !== "partially_refunded" && (
              <Button onClick={() => onProcess(refund)}>Process Refund</Button>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Download, Calendar, CheckCircle, XCircle, Clock } from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";
import {
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from "recharts";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

const COLORS = ["#0088FE", "#00C49F", "#FFBB28", "#FF8042", "#8884d8"];

interface BookingReportData {
  period: string;
  totalBookings: number;
  bookingsByDay: Array<{ date: string; count: number }>;
  bookingsByStatus: Array<{ status: string; count: number; percentage: number }>;
  bookingsByProvider: Array<{ provider_id: string; provider_name: string; count: number }>;
  completionRate: number;
  cancellationRate: number;
  noShowRate: number;
}

export default function BookingReportPage() {
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [data, setData] = useState<BookingReportData | null>(null);
  const [period, setPeriod] = useState("30d");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  useEffect(() => {
    loadReport();
  }, [period, startDate, endDate]); // eslint-disable-line react-hooks/exhaustive-deps -- load when params change

  const loadReport = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      params.set("period", period);
      if (startDate) params.set("start_date", startDate);
      if (endDate) params.set("end_date", endDate);

      const response = await fetcher.get<{ data: BookingReportData }>(
        `/api/admin/reports/bookings?${params.toString()}`
      );
      const reportData = (response as any).data || response;
      setData(reportData);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load booking report";
      setError(errorMessage);
      toast.error(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleExport = async () => {
    try {
      const params = new URLSearchParams();
      params.set("period", period);
      if (startDate) params.set("start_date", startDate);
      if (endDate) params.set("end_date", endDate);

      const response = await fetch(`/api/admin/export/bookings?${params.toString()}`);
      if (!response.ok) throw new Error("Export failed");

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `bookings-report-${period}-${new Date().toISOString().split("T")[0]}.csv`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
      toast.success("Export downloaded");
    } catch {
      toast.error("Failed to export report");
    }
  };

  if (isLoading) {
    return (
      <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
        <div className="container mx-auto px-4 py-8">
          <LoadingTimeout loadingMessage="Loading booking report..." />
        </div>
      </RoleGuard>
    );
  }

  if (error || !data) {
    return (
      <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
        <div className="container mx-auto px-4 py-8">
          <EmptyState
            title="Failed to load booking report"
            description={error || "Unable to load report data"}
            action={{
              label: "Retry",
              onClick: loadReport,
            }}
          />
        </div>
      </RoleGuard>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="container mx-auto px-4 py-8">
        <div className="mb-6 flex items-center justify-between flex-wrap gap-4">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Booking Report</h1>
            <p className="text-gray-600 mt-1">Platform booking analysis and trends</p>
          </div>
          <Button onClick={handleExport}>
            <Download className="w-4 h-4 mr-2" />
            Export CSV
          </Button>
        </div>

        {/* Filters */}
        <Card className="mb-6">
          <CardHeader>
            <CardTitle>Filters</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <div>
                <Label>Period</Label>
                <Select value={period} onValueChange={setPeriod}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="7d">Last 7 days</SelectItem>
                    <SelectItem value="30d">Last 30 days</SelectItem>
                    <SelectItem value="90d">Last 90 days</SelectItem>
                    <SelectItem value="1y">Last year</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Start Date</Label>
                <Input
                  type="date"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                />
              </div>
              <div>
                <Label>End Date</Label>
                <Input
                  type="date"
                  value={endDate}
                  onChange={(e) => setEndDate(e.target.value)}
                />
              </div>
              <div className="flex items-end">
                <Button
                  variant="outline"
                  onClick={() => {
                    setStartDate("");
                    setEndDate("");
                  }}
                  className="w-full"
                >
                  Clear Dates
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Summary */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Bookings</CardTitle>
              <Calendar className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{data.totalBookings}</div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Completion Rate</CardTitle>
              <CheckCircle className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{data.completionRate.toFixed(1)}%</div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Cancellation Rate</CardTitle>
              <XCircle className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{data.cancellationRate.toFixed(1)}%</div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">No-Show Rate</CardTitle>
              <Clock className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{data.noShowRate.toFixed(1)}%</div>
            </CardContent>
          </Card>
        </div>

        {/* Bookings Over Time */}
        <Card className="mb-6">
          <CardHeader>
            <CardTitle>Bookings Over Time</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={data.bookingsByDay}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="date" />
                <YAxis />
                <Tooltip />
                <Legend />
                <Bar dataKey="count" fill="#0088FE" name="Bookings" />
              </BarChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>

        {/* Bookings by Status */}
        {data.bookingsByStatus.length > 0 && (
          <Card>
            <CardHeader>
              <CardTitle>Bookings by Status</CardTitle>
            </CardHeader>
            <CardContent>
              <ResponsiveContainer width="100%" height={300}>
                <PieChart>
                  <Pie
                    data={data.bookingsByStatus}
                    cx="50%"
                    cy="50%"
                    labelLine={false}
                    label={({ status, percentage }) => `${status} ${percentage.toFixed(1)}%`}
                    outerRadius={80}
                    fill="#8884d8"
                    dataKey="count"
                  >
                    {data.bookingsByStatus.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </CardContent>
          </Card>
        )}
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
