} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { format } from "date-fns";

interface RevenueReportData {
  period: string;
  totalRevenue: number;
  revenueByDay: Array<{ date: string; revenue: number; bookings: number }>;
  revenueByProvider: Array<{ provider_id: string; provider_name: string; revenue: number; bookings: number }>;
  revenueByService: Array<{ service_id: string; service_name: string; revenue: number; bookings: number }>;
  revenueByStatus: Array<{ status: string; revenue: number; bookings: number }>;
  giftCardMetrics?: {
    totalSales: number;
    totalRedemptions: number;
    outstandingLiability: number;
    redemptionRate: number;
    salesByDay: Array<{ date: string; sales: number; count: number }>;
    redemptionsByDay: Array<{ date: string; redemptions: number; count: number }>;
  };
}

export default function RevenueReportPage() {
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [data, setData] = useState<RevenueReportData | null>(null);
  const [period, setPeriod] = useState("30d");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  useEffect(() => {
    loadReport();
  }, [period, startDate, endDate]); // eslint-disable-line react-hooks/exhaustive-deps -- load when params change

  const loadReport = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      params.set("period", period);
      if (startDate) params.set("start_date", startDate);
      if (endDate) params.set("end_date", endDate);

      const response = await fetcher.get<{ data: RevenueReportData }>(
        `/api/admin/reports/revenue?${params.toString()}`
      );
      const reportData = (response as any).data || response;
      setData(reportData);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load revenue report";
      setError(errorMessage);
      toast.error(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleExport = async () => {
    try {
      const params = new URLSearchParams();
      params.set("period", period);
      if (startDate) params.set("start_date", startDate);
      if (endDate) params.set("end_date", endDate);

      const response = await fetch(`/api/admin/export/analytics?period=${period}&report_type=revenue`);
      if (!response.ok) throw new Error("Export failed");

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `revenue-report-${period}-${new Date().toISOString().split("T")[0]}.csv`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
      toast.success("Export downloaded");
    } catch {
      toast.error("Failed to export report");
    }
  };

  if (isLoading) {
    return (
      <RoleGuard allowedRoles={["superadmin"]}>
        <div className="container mx-auto px-4 py-8">
          <LoadingTimeout loadingMessage="Loading revenue report..." />
        </div>
      </RoleGuard>
    );
  }

  if (error || !data) {
    return (
      <RoleGuard allowedRoles={["superadmin"]}>
        <div className="container mx-auto px-4 py-8">
          <EmptyState
            title="Failed to load revenue report"
            description={error || "Unable to load report data"}
            action={{
              label: "Retry",
              onClick: loadReport,
            }}
          />
        </div>
      </RoleGuard>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]}>
      <div className="container mx-auto px-4 py-8">
        <div className="mb-6 flex items-center justify-between flex-wrap gap-4">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Revenue Report</h1>
            <p className="text-gray-600 mt-1">Platform revenue analysis and trends</p>
          </div>
          <Button onClick={handleExport}>
            <Download className="w-4 h-4 mr-2" />
            Export CSV
          </Button>
        </div>

        {/* Filters */}
        <Card className="mb-6">
          <CardHeader>
            <CardTitle>Filters</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <div>
                <Label>Period</Label>
                <Select value={period} onValueChange={setPeriod}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="7d">Last 7 days</SelectItem>
                    <SelectItem value="30d">Last 30 days</SelectItem>
                    <SelectItem value="90d">Last 90 days</SelectItem>
                    <SelectItem value="1y">Last year</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Start Date</Label>
                <Input
                  type="date"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                />
              </div>
              <div>
                <Label>End Date</Label>
                <Input
                  type="date"
                  value={endDate}
                  onChange={(e) => setEndDate(e.target.value)}
                />
              </div>
              <div className="flex items-end">
                <Button
                  variant="outline"
                  onClick={() => {
                    setStartDate("");
                    setEndDate("");
                  }}
                  className="w-full"
                >
                  Clear Dates
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Summary */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Revenue</CardTitle>
              <DollarSign className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                R {data.totalRevenue.toLocaleString()}
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Bookings</CardTitle>
              <Calendar className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                {data.revenueByDay.reduce((sum, day) => sum + day.bookings, 0)}
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Average Booking Value</CardTitle>
              <TrendingUp className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                R {(data.totalRevenue / Math.max(1, data.revenueByDay.reduce((sum, day) => sum + day.bookings, 0))).toFixed(2)}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Revenue Over Time */}
        <Card className="mb-6">
          <CardHeader>
            <CardTitle>Revenue Over Time</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={300}>
              <LineChart data={data.revenueByDay}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis
                  dataKey="date"
                  tickFormatter={(value) => format(new Date(value), "MMM d")}
                />
                <YAxis tickFormatter={(value) => `R ${value.toLocaleString()}`} />
                <Tooltip
                  formatter={(value: number) => `R ${value.toLocaleString()}`}
                  labelFormatter={(label) => format(new Date(label), "PP")}
                />
                <Legend />
                <Line
                  type="monotone"
                  dataKey="revenue"
                  stroke="#0088FE"
                  strokeWidth={2}
                  name="Revenue"
                />
              </LineChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>

        {/* Revenue by Provider */}
        {data.revenueByProvider.length > 0 && (
          <Card className="mb-6">
            <CardHeader>
              <CardTitle>Revenue by Provider</CardTitle>
            </CardHeader>
            <CardContent>
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={data.revenueByProvider.slice(0, 10)}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis
                    dataKey="provider_name"
                    angle={-45}
                    textAnchor="end"
                    height={100}
                  />
                  <YAxis tickFormatter={(value) => `R ${value.toLocaleString()}`} />
                  <Tooltip formatter={(value: number) => `R ${value.toLocaleString()}`} />
                  <Legend />
                  <Bar dataKey="revenue" fill="#00C49F" name="Revenue" />
                </BarChart>
              </ResponsiveContainer>
            </CardContent>
          </Card>
        )}

        {/* Revenue by Status */}
        {data.revenueByStatus.length > 0 && (
          <Card className="mb-6">
            <CardHeader>
              <CardTitle>Revenue by Booking Status</CardTitle>
            </CardHeader>
            <CardContent>
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={data.revenueByStatus}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="status" />
                  <YAxis tickFormatter={(value) => `R ${value.toLocaleString()}`} />
                  <Tooltip formatter={(value: number) => `R ${value.toLocaleString()}`} />
                  <Legend />
                  <Bar dataKey="revenue" fill="#FFBB28" name="Revenue" />
                </BarChart>
              </ResponsiveContainer>
            </CardContent>
          </Card>
        )}

        {/* Gift Card Metrics Section */}
        {data.giftCardMetrics && (
          <>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
              <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium">Gift Card Sales</CardTitle>
                  <DollarSign className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">
                    R {data.giftCardMetrics.totalSales.toLocaleString()}
                  </div>
                  <p className="text-xs text-muted-foreground mt-1">Cash received (liability)</p>
                </CardContent>
              </Card>
              <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium">Gift Card Redemptions</CardTitle>
                  <Gift className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">
                    R {data.giftCardMetrics.totalRedemptions.toLocaleString()}
                  </div>
                  <p className="text-xs text-muted-foreground mt-1">Value redeemed</p>
                </CardContent>
              </Card>
              <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium">Outstanding Liability</CardTitle>
                  <DollarSign className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">
                    R {data.giftCardMetrics.outstandingLiability.toLocaleString()}
                  </div>
                  <p className="text-xs text-muted-foreground mt-1">Unredeemed balance</p>
                </CardContent>
              </Card>
              <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium">Redemption Rate</CardTitle>
                  <TrendingUp className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">
                    {data.giftCardMetrics.redemptionRate.toFixed(1)}%
                  </div>
                  <p className="text-xs text-muted-foreground mt-1">Cards redeemed</p>
                </CardContent>
              </Card>
            </div>

            <Card className="mb-6">
              <CardHeader>
                <CardTitle>Gift Card Sales vs. Redemptions</CardTitle>
              </CardHeader>
              <CardContent>
                <ResponsiveContainer width="100%" height={300}>
                  <LineChart
                    data={data.giftCardMetrics.salesByDay.map((sale) => {
                      const redemption = data.giftCardMetrics!.redemptionsByDay.find(
                        (r) => r.date === sale.date
                      );
                      return {
                        date: sale.date,
                        sales: sale.sales,
                        redemptions: redemption?.redemptions || 0,
                      };
                    })}
                  >
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis
                      dataKey="date"
                      tickFormatter={(value) => format(new Date(value), "MMM d")}
                    />
                    <YAxis tickFormatter={(value) => `R ${value.toLocaleString()}`} />
                    <Tooltip
                      formatter={(value: number) => `R ${value.toLocaleString()}`}
                      labelFormatter={(label) => format(new Date(label), "PP")}
                    />
                    <Legend />
                    <Line
                      type="monotone"
                      dataKey="sales"
                      stroke="#00C49F"
                      strokeWidth={2}
                      name="Sales"
                    />
                    <Line
                      type="monotone"
                      dataKey="redemptions"
                      stroke="#FF0077"
                      strokeWidth={2}
                      name="Redemptions"
                    />
                  </LineChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </>
        )}
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Search,
  Eye,
  EyeOff,
  Flag,
  Star,
  XCircle,
  MessageSquare,
  Download,
  MoreVertical,
} from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";

interface Review {
  id: string;
  booking_id: string;
  customer_id: string;
  provider_id: string;
  rating: number;
  comment: string | null;
  is_verified: boolean;
  is_flagged: boolean;
  flagged_reason: string | null;
  is_visible: boolean;
  helpful_count: number;
  created_at: string;
  customer: {
    id: string;
    full_name: string | null;
    email: string;
    avatar_url: string | null;
  };
  provider: {
    id: string;
    business_name: string;
    thumbnail_url?: string | null;
    logo_url?: string | null; // deprecated, use thumbnail_url
  };
  booking: {
    id: string;
    booking_number: string;
    status: string;
  };
}

interface ReviewStatistics {
  total: number;
  visible: number;
  hidden: number;
  flagged: number;
  average_rating: string;
  rating_distribution: {
    5: number;
    4: number;
    3: number;
    2: number;
    1: number;
  };
}

export default function AdminReviews() {
  const [reviews, setReviews] = useState<Review[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [ratingFilter, setRatingFilter] = useState<string>("all");
  const [statistics, setStatistics] = useState<ReviewStatistics | null>(null);
  const [selectedReview, setSelectedReview] = useState<Review | null>(null);
  const [showModerateDialog, setShowModerateDialog] = useState(false);
  const [moderateAction, setModerateAction] = useState<"hide" | "flag" | "edit">("hide");
  const [moderateReason, setModerateReason] = useState("");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [moderateComment, setModerateComment] = useState("");

  useEffect(() => {
    loadReviews();
  }, [statusFilter, ratingFilter, startDate, endDate]); // eslint-disable-line react-hooks/exhaustive-deps -- load when filters change

  const loadReviews = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      if (statusFilter !== "all") params.set("status", statusFilter);
      if (ratingFilter !== "all") params.set("rating", ratingFilter);
      if (startDate) params.set("start_date", startDate);
      if (endDate) params.set("end_date", endDate);

      const response = await fetcher.get<{
        data?: {
          reviews?: Review[];
          statistics?: ReviewStatistics;
          pagination?: any;
        };
      }>(`/api/admin/reviews?${params.toString()}`);

      setReviews(response.data?.reviews ?? []);
      setStatistics(response.data?.statistics ?? null);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load reviews";
      setError(errorMessage);
      console.error("Error loading reviews:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleModerate = async () => {
    if (!selectedReview) return;

    try {
      const updateData: any = {};

      if (moderateAction === "hide") {
        updateData.is_visible = false;
      } else if (moderateAction === "flag") {
        updateData.is_flagged = true;
        updateData.flagged_reason = moderateReason;
      } else if (moderateAction === "edit") {
        updateData.comment = moderateComment;
      }

      await fetcher.patch(`/api/admin/reviews/${selectedReview.id}`, updateData);

      toast.success("Review updated successfully");
      setShowModerateDialog(false);
      setSelectedReview(null);
      setModerateReason("");
      setModerateComment("");
      loadReviews();
    } catch (err) {
      toast.error(err instanceof FetchError ? err.message : "Failed to update review");
    }
  };

  const handleDelete = async (reviewId: string) => {
    if (!confirm("Are you sure you want to delete this review? This action cannot be undone.")) {
      return;
    }

    try {
      await fetcher.delete(`/api/admin/reviews/${reviewId}`);
      toast.success("Review deleted successfully");
      loadReviews();
    } catch (err) {
      toast.error(err instanceof FetchError ? err.message : "Failed to delete review");
    }
  };

  const filteredReviews = reviews.filter((review) => {
    const matchesSearch =
      (review.customer?.full_name ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (review.customer?.email ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (review.provider?.business_name ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (review.booking?.booking_number ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (review.comment ?? "").toLowerCase().includes(searchQuery.toLowerCase());
    return matchesSearch;
  });

  const groupedReviews = {
    all: filteredReviews,
    visible: filteredReviews.filter((r) => r.is_visible),
    hidden: filteredReviews.filter((r) => !r.is_visible),
    flagged: filteredReviews.filter((r) => r.is_flagged),
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <LoadingTimeout loadingMessage="Loading reviews..." />
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <EmptyState
            title="Failed to load reviews"
            description={error}
            action={{
              label: "Retry",
              onClick: loadReviews,
            }}
          />
        </div>
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
            className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 md:p-8 mb-8"
          >
            <div className="flex items-center justify-between mb-6 flex-wrap gap-4">
              <motion.div
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.2, duration: 0.5, ease: "easeOut" }}
              >
                <h1 className="text-2xl md:text-3xl font-semibold tracking-tighter text-gray-900">Reviews Management</h1>
                <p className="text-sm md:text-base font-light text-gray-600 mt-1">Moderate and manage all platform reviews</p>
              </motion.div>
              <Button
                variant="outline"
                onClick={async () => {
                  try {
                    const params = new URLSearchParams();
                    if (statusFilter !== "all") params.set("status", statusFilter);
                    if (ratingFilter !== "all") params.set("rating", ratingFilter);
                    if (startDate) params.set("start_date", startDate);
                    if (endDate) params.set("end_date", endDate);
                    
                    const response = await fetch(`/api/admin/export/reviews?${params.toString()}`);
                    if (!response.ok) throw new Error("Export failed");
                    
                    const blob = await response.blob();
                    const url = window.URL.createObjectURL(blob);
                    const a = document.createElement("a");
                    a.href = url;
                    a.download = `reviews-export-${new Date().toISOString().split("T")[0]}.csv`;
                    document.body.appendChild(a);
                    a.click();
                    window.URL.revokeObjectURL(url);
                    document.body.removeChild(a);
                    toast.success("Export downloaded");
                  } catch {
                    toast.error("Failed to export reviews");
                  }
                }}
              >
                <Download className="w-4 h-4 mr-2" />
                Export CSV
              </Button>
            </div>

            {/* Statistics */}
            {statistics && (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4 mb-6">
                <motion.div
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 shadow-lg"
                >
                  <div className="text-sm font-light text-gray-600">Total Reviews</div>
                  <div className="text-2xl font-semibold tracking-tight text-gray-900">{statistics.total}</div>
                </motion.div>
                <motion.div
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 shadow-lg"
                >
                  <div className="text-sm font-light text-gray-600">Visible</div>
                  <div className="text-2xl font-semibold tracking-tight text-green-600">{statistics.visible}</div>
                </motion.div>
                <motion.div
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 shadow-lg"
                >
                  <div className="text-sm font-light text-gray-600">Hidden</div>
                  <div className="text-2xl font-semibold tracking-tight text-gray-600">{statistics.hidden}</div>
                </motion.div>
                <motion.div
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 shadow-lg"
                >
                  <div className="text-sm font-light text-gray-600">Flagged</div>
                  <div className="text-2xl font-semibold tracking-tight text-red-600">{statistics.flagged}</div>
                </motion.div>
                <motion.div
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 shadow-lg"
                >
                  <div className="text-sm font-light text-gray-600">Avg Rating</div>
                  <div className="text-2xl font-semibold tracking-tight text-yellow-600">{statistics.average_rating}</div>
                </motion.div>
                <motion.div
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 shadow-lg"
                >
                  <div className="text-sm font-light text-gray-600">5 Stars</div>
                  <div className="text-2xl font-semibold tracking-tight text-yellow-600">
                    {statistics.rating_distribution[5]}
                  </div>
                </motion.div>
              </div>
            )}

            {/* Filters */}
            <div className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-4 mb-6">
              <div className="flex flex-col gap-4">
                <div className="flex flex-col md:flex-row gap-4">
                  <div className="flex-1">
                    <div className="relative">
                      <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                      <Input
                        type="text"
                        placeholder="Search by customer, provider, booking number, or comment..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="pl-10 backdrop-blur-sm bg-white/60 border border-white/40 focus:border-[#FF0077] focus:ring-[#FF0077] rounded-xl"
                      />
                    </div>
                  </div>
                  <select
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value)}
                    className="px-4 py-2 border border-white/40 rounded-xl backdrop-blur-sm bg-white/60 focus:border-[#FF0077] focus:ring-[#FF0077]"
                  >
                    <option value="all">All Status</option>
                    <option value="visible">Visible</option>
                    <option value="hidden">Hidden</option>
                    <option value="flagged">Flagged</option>
                  </select>
                  <select
                    value={ratingFilter}
                    onChange={(e) => setRatingFilter(e.target.value)}
                    className="px-4 py-2 border border-white/40 rounded-xl backdrop-blur-sm bg-white/60 focus:border-[#FF0077] focus:ring-[#FF0077]"
                  >
                    <option value="all">All Ratings</option>
                    <option value="5">5 Stars</option>
                    <option value="4">4 Stars</option>
                    <option value="3">3 Stars</option>
                    <option value="2">2 Stars</option>
                    <option value="1">1 Star</option>
                  </select>
                </div>
                <div className="flex flex-col md:flex-row gap-4">
                  <Input
                    type="date"
                    placeholder="Start Date"
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                    className="backdrop-blur-sm bg-white/60 border border-white/40 focus:border-[#FF0077] focus:ring-[#FF0077] rounded-xl"
                  />
                  <Input
                    type="date"
                    placeholder="End Date"
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    className="backdrop-blur-sm bg-white/60 border border-white/40 focus:border-[#FF0077] focus:ring-[#FF0077] rounded-xl"
                  />
                </div>
              </div>
            </div>

            {/* Reviews List */}
            <Tabs defaultValue="all" className="space-y-4">
              <TabsList className="backdrop-blur-xl bg-white/80 border border-white/40 rounded-xl p-1 shadow-lg">
                <TabsTrigger value="all" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">All ({groupedReviews.all.length})</TabsTrigger>
                <TabsTrigger value="visible" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">Visible ({groupedReviews.visible.length})</TabsTrigger>
                <TabsTrigger value="hidden" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">Hidden ({groupedReviews.hidden.length})</TabsTrigger>
                <TabsTrigger value="flagged" className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-[#FF0077] data-[state=active]:to-[#E6006A] data-[state=active]:text-white rounded-lg transition-all">Flagged ({groupedReviews.flagged.length})</TabsTrigger>
              </TabsList>

          <TabsContent value="all" className="space-y-4">
            <ReviewList
              reviews={groupedReviews.all}
              onModerate={(review, action) => {
                setSelectedReview(review);
                setModerateAction(action);
                setModerateComment(review.comment || "");
                setShowModerateDialog(true);
              }}
              onDelete={handleDelete}
            />
          </TabsContent>
          <TabsContent value="visible" className="space-y-4">
            <ReviewList
              reviews={groupedReviews.visible}
              onModerate={(review, action) => {
                setSelectedReview(review);
                setModerateAction(action);
                setModerateComment(review.comment || "");
                setShowModerateDialog(true);
              }}
              onDelete={handleDelete}
            />
          </TabsContent>
          <TabsContent value="hidden" className="space-y-4">
            <ReviewList
              reviews={groupedReviews.hidden}
              onModerate={(review, action) => {
                setSelectedReview(review);
                setModerateAction(action);
                setModerateComment(review.comment || "");
                setShowModerateDialog(true);
              }}
              onDelete={handleDelete}
            />
          </TabsContent>
          <TabsContent value="flagged" className="space-y-4">
            <ReviewList
              reviews={groupedReviews.flagged}
              onModerate={(review, action) => {
                setSelectedReview(review);
                setModerateAction(action);
                setModerateComment(review.comment || "");
                setShowModerateDialog(true);
              }}
              onDelete={handleDelete}
            />
            </TabsContent>
            </Tabs>
          </motion.div>
        </div>
      </div>

      {/* Moderate Dialog */}
      <Dialog open={showModerateDialog} onOpenChange={setShowModerateDialog}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>
                {moderateAction === "hide"
                  ? "Hide Review"
                  : moderateAction === "flag"
                  ? "Flag Review"
                  : "Edit Review"}
              </DialogTitle>
              <DialogDescription>
                {moderateAction === "hide"
                  ? "This review will be hidden from public view."
                  : moderateAction === "flag"
                  ? "Flag this review for further review. Please provide a reason."
                  : "Edit the review comment."}
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4">
              {moderateAction === "flag" && (
                <div>
                  <Label>Reason for Flagging</Label>
                  <Textarea
                    value={moderateReason}
                    onChange={(e) => setModerateReason(e.target.value)}
                    placeholder="Enter reason for flagging this review..."
                    rows={3}
                  />
                </div>
              )}
              {moderateAction === "edit" && (
                <div>
                  <Label>Review Comment</Label>
                  <Textarea
                    value={moderateComment}
                    onChange={(e) => setModerateComment(e.target.value)}
                    placeholder="Edit review comment..."
                    rows={5}
                  />
                </div>
              )}
              <div className="flex justify-end gap-2">
                <Button variant="outline" onClick={() => setShowModerateDialog(false)}>
                  Cancel
                </Button>
                <Button onClick={handleModerate}>Confirm</Button>
              </div>
            </div>
          </DialogContent>
      </Dialog>
    </RoleGuard>
  );
}

function ReviewList({
  reviews,
  onModerate,
  onDelete,
}: {
  reviews: Review[];
  onModerate: (review: Review, action: "hide" | "flag" | "edit") => void;
  onDelete: (reviewId: string) => void;
}) {
  if (reviews.length === 0) {
    return (
      <div className="bg-white p-8 rounded-lg border border-gray-200 text-center">
        <MessageSquare className="w-12 h-12 text-gray-400 mx-auto mb-4" />
        <p className="text-gray-600">No reviews found</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {reviews.map((review) => (
        <div key={review.id} className="bg-white p-6 rounded-lg border border-gray-200">
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <div className="flex items-center gap-3 mb-2">
                <div className="flex items-center gap-1">
                  {[...Array(5)].map((_, i) => (
                    <Star
                      key={i}
                      className={`w-4 h-4 ${
                        i < review.rating ? "fill-yellow-400 text-yellow-400" : "text-gray-300"
                      }`}
                    />
                  ))}
                </div>
                <Badge variant={review.is_visible ? "default" : "secondary"}>
                  {review.is_visible ? "Visible" : "Hidden"}
                </Badge>
                {review.is_flagged && (
                  <Badge variant="destructive">Flagged</Badge>
                )}
                {review.is_verified && (
                  <Badge variant="outline">Verified</Badge>
                )}
              </div>
              <p className="text-gray-900 mb-3">{review.comment || "No comment"}</p>
              <div className="flex items-center gap-4 text-sm text-gray-600">
                <span>
                  <strong>Customer:</strong> {review.customer?.full_name || review.customer?.email}
                </span>
                <span>
                  <strong>Provider:</strong> {review.provider?.business_name}
                </span>
                <span>
                  <strong>Booking:</strong> {review.booking?.booking_number}
                </span>
                <span>
                  <strong>Date:</strong> {new Date(review.created_at).toLocaleDateString()}
                </span>
                {review.helpful_count > 0 && (
                  <span>
                    <strong>Helpful:</strong> {review.helpful_count}
                  </span>
                )}
              </div>
              {review.flagged_reason && (
                <div className="mt-2 p-2 bg-red-50 border border-red-200 rounded text-sm text-red-800">
                  <strong>Flagged Reason:</strong> {review.flagged_reason}
                </div>
              )}
            </div>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="icon">
                  <MoreVertical className="w-4 h-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                {review.is_visible ? (
                  <DropdownMenuItem onClick={() => onModerate(review, "hide")}>
                    <EyeOff className="w-4 h-4 mr-2" />
                    Hide
                  </DropdownMenuItem>
                ) : (
                  <DropdownMenuItem
                    onClick={async () => {
                      await fetcher.patch(`/api/admin/reviews/${review.id}`, { is_visible: true });
                      window.location.reload();
                    }}
                  >
                    <Eye className="w-4 h-4 mr-2" />
                    Show
                  </DropdownMenuItem>
                )}
                <DropdownMenuItem onClick={() => onModerate(review, "flag")}>
                  <Flag className="w-4 h-4 mr-2" />
                  Flag
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => onModerate(review, "edit")}>
                  <MessageSquare className="w-4 h-4 mr-2" />
                  Edit
                </DropdownMenuItem>
                <DropdownMenuItem
                  onClick={() => onDelete(review.id)}
                  className="text-red-600"
                >
                  <XCircle className="w-4 h-4 mr-2" />
                  Delete
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </div>
      ))}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import {
  Plus,
  Edit,
  Trash2,
  Search,
} from "lucide-react";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import {
  getAllFeatureFlags,
  updateFeatureFlag,
  createFeatureFlag,
  deleteFeatureFlag,
  type FeatureFlag,
} from "@/lib/feature-flags";

export default function FeatureFlagsPage() {
  const [featureFlags, setFeatureFlags] = useState<FeatureFlag[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<string>("all");
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [selectedFeature, setSelectedFeature] = useState<FeatureFlag | null>(
    null
  );

  // Form state for create/edit
  const [formData, setFormData] = useState({
    feature_key: "",
    feature_name: "",
    description: "",
    enabled: false,
    category: "",
    metadata: {},
    rollout_percent: 100,
    platforms_allowed: "" as string,
    roles_allowed: "" as string,
    min_app_version: "",
    environments_allowed: "" as string,
  });

  // Fetch feature flags
  const fetchFeatureFlags = async () => {
    try {
      setLoading(true);
      const flags = await getAllFeatureFlags();
      setFeatureFlags(flags);
    } catch {
      toast.error("Failed to load feature flags");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchFeatureFlags();
  }, []);

  // Get unique categories
  const categories = Array.from(
    new Set(featureFlags.map((flag) => flag.category).filter((cat): cat is string => Boolean(cat)))
  );

  // Filter feature flags
  const filteredFlags = featureFlags.filter((flag) => {
    const matchesSearch =
      (flag.feature_name ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (flag.feature_key ?? "").toLowerCase().includes(searchQuery.toLowerCase()) ||
      (flag.description ?? "").toLowerCase().includes(searchQuery.toLowerCase());

    const matchesCategory =
      selectedCategory === "all" || flag.category === selectedCategory;

    return matchesSearch && matchesCategory;
  });

  // Group by category (reserved for future category UI)
  const _groupedFlags = filteredFlags.reduce((acc, flag) => {
    const category = flag.category || "uncategorized";
    if (!acc[category]) {
      acc[category] = [];
    }
    acc[category].push(flag);
    return acc;
  }, {} as Record<string, FeatureFlag[]>);

  // Handle toggle feature
  const handleToggleFeature = async (flag: FeatureFlag) => {
    try {
      const updated = await updateFeatureFlag(flag.id, {
        enabled: !flag.enabled,
      });
      setFeatureFlags((prev) =>
        prev.map((f) => (f.id === flag.id ? updated : f))
      );
      toast.success(
        `${flag.feature_name} ${updated.enabled ? "enabled" : "disabled"}`
      );
    } catch (error) {
      console.error("Error toggling feature:", error);
      toast.error("Failed to update feature flag");
    }
  };

  // Handle create
  const handleCreate = async () => {
    try {
      if (!formData.feature_key || !formData.feature_name) {
        toast.error("Feature key and name are required");
        return;
      }

      const newFlag = await createFeatureFlag({
        feature_key: formData.feature_key,
        feature_name: formData.feature_name,
        description: formData.description || null,
        enabled: formData.enabled,
        category: formData.category || null,
        metadata: formData.metadata,
      });

      setFeatureFlags((prev) => [...prev, newFlag]);
      setIsCreateDialogOpen(false);
      setFormData({
        feature_key: "",
        feature_name: "",
        description: "",
        enabled: false,
        category: "",
        metadata: {},
        rollout_percent: 100,
        platforms_allowed: "",
        roles_allowed: "",
        min_app_version: "",
        environments_allowed: "",
      });
      toast.success("Feature flag created successfully");
    } catch (error: any) {
      console.error("Error creating feature flag:", error);
      toast.error(error.message || "Failed to create feature flag");
    }
  };

  // Handle edit
  const handleEdit = async () => {
    if (!selectedFeature) return;

    try {
      const platforms = formData.platforms_allowed
        ? formData.platforms_allowed.split(",").map((s) => s.trim()).filter(Boolean)
        : null;
      const roles = formData.roles_allowed
        ? formData.roles_allowed.split(",").map((s) => s.trim()).filter(Boolean)
        : null;
      const environments = formData.environments_allowed
        ? formData.environments_allowed.split(",").map((s) => s.trim()).filter(Boolean)
        : null;
      const updated = await updateFeatureFlag(selectedFeature.id, {
        feature_name: formData.feature_name,
        description: formData.description || null,
        enabled: formData.enabled,
        category: formData.category || null,
        metadata: formData.metadata,
        rollout_percent: formData.rollout_percent,
        platforms_allowed: platforms ?? undefined,
        roles_allowed: roles ?? undefined,
        min_app_version: formData.min_app_version || null,
        environments_allowed: environments ?? undefined,
      });

      setFeatureFlags((prev) =>
        prev.map((f) => (f.id === selectedFeature.id ? updated : f))
      );
      setIsEditDialogOpen(false);
      setSelectedFeature(null);
      toast.success("Feature flag updated successfully");
    } catch (error: any) {
      console.error("Error updating feature flag:", error);
      toast.error(error.message || "Failed to update feature flag");
    }
  };

  // Handle delete
  const handleDelete = async (flag: FeatureFlag) => {
    if (
      !confirm(
        `Are you sure you want to delete "${flag.feature_name}"? This action cannot be undone.`
      )
    ) {
      return;
    }

    try {
      await deleteFeatureFlag(flag.id);
      setFeatureFlags((prev) => prev.filter((f) => f.id !== flag.id));
      toast.success("Feature flag deleted successfully");
    } catch (error: any) {
      console.error("Error deleting feature flag:", error);
      toast.error(error.message || "Failed to delete feature flag");
    }
  };

  // Open edit dialog
  const openEditDialog = (flag: FeatureFlag) => {
    setSelectedFeature(flag);
    setFormData({
      feature_key: flag.feature_key,
      feature_name: flag.feature_name,
      description: flag.description || "",
      enabled: flag.enabled,
      category: flag.category || "",
      metadata: flag.metadata || {},
      rollout_percent: flag.rollout_percent ?? 100,
      platforms_allowed: (flag.platforms_allowed ?? []).join(", "),
      roles_allowed: (flag.roles_allowed ?? []).join(", "),
      min_app_version: flag.min_app_version || "",
      environments_allowed: (flag.environments_allowed ?? []).join(", "),
    });
    setIsEditDialogOpen(true);
  };

  if (loading) {
    return <LoadingTimeout loadingMessage="Loading feature flags..." />;
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="container mx-auto p-6 space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold">Feature Flags</h1>
            <p className="text-muted-foreground mt-1">
              Enable or disable features across the platform
            </p>
          </div>
          <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
            <DialogTrigger asChild>
              <Button>
                <Plus className="mr-2 h-4 w-4" />
                Add Feature Flag
              </Button>
            </DialogTrigger>
            <DialogContent className="max-w-2xl">
              <DialogHeader>
                <DialogTitle>Create Feature Flag</DialogTitle>
                <DialogDescription>
                  Add a new feature flag to control platform features
                </DialogDescription>
              </DialogHeader>
              <div className="space-y-4">
                <div>
                  <Label htmlFor="create-key">Feature Key *</Label>
                  <Input
                    id="create-key"
                    value={formData.feature_key}
                    onChange={(e) =>
                      setFormData({ ...formData, feature_key: e.target.value })
                    }
                    placeholder="e.g., booking_online"
                  />
                </div>
                <div>
                  <Label htmlFor="create-name">Feature Name *</Label>
                  <Input
                    id="create-name"
                    value={formData.feature_name}
                    onChange={(e) =>
                      setFormData({ ...formData, feature_name: e.target.value })
                    }
                    placeholder="e.g., Online Booking"
                  />
                </div>
                <div>
                  <Label htmlFor="create-description">Description</Label>
                  <Textarea
                    id="create-description"
                    value={formData.description}
                    onChange={(e) =>
                      setFormData({ ...formData, description: e.target.value })
                    }
                    placeholder="Describe what this feature does..."
                    rows={3}
                  />
                </div>
                <div>
                  <Label htmlFor="create-category">Category</Label>
                  <Input
                    id="create-category"
                    value={formData.category}
                    onChange={(e) =>
                      setFormData({ ...formData, category: e.target.value })
                    }
                    placeholder="e.g., booking, payment, notifications"
                  />
                </div>
                <div className="flex items-center space-x-2">
                  <Switch
                    id="create-enabled"
                    checked={formData.enabled}
                    onCheckedChange={(checked) =>
                      setFormData({ ...formData, enabled: checked })
                    }
                  />
                  <Label htmlFor="create-enabled">Enabled</Label>
                </div>
              </div>
              <DialogFooter>
                <Button
                  variant="outline"
                  onClick={() => setIsCreateDialogOpen(false)}
                >
                  Cancel
                </Button>
                <Button onClick={handleCreate}>Create</Button>
              </DialogFooter>
            </DialogContent>
          </Dialog>
        </div>

        {/* Filters */}
        <div className="flex gap-4">
          <div className="flex-1">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search feature flags..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>
          </div>
          <Select value={selectedCategory} onValueChange={setSelectedCategory}>
            <SelectTrigger className="w-[200px]">
              <SelectValue placeholder="All Categories" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Categories</SelectItem>
              {categories.map((category) => (
                <SelectItem key={category} value={category}>
                  {category}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Feature Flags Table */}
        {filteredFlags.length === 0 ? (
          <EmptyState
            title="No feature flags found"
            description={
              searchQuery || selectedCategory !== "all"
                ? "Try adjusting your filters"
                : "Create your first feature flag to get started"
            }
          />
        ) : (
          <div className="border rounded-lg">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Feature</TableHead>
                  <TableHead>Key</TableHead>
                  <TableHead>Category</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredFlags.map((flag) => (
                  <TableRow key={flag.id}>
                    <TableCell>
                      <div>
                        <div className="font-medium">{flag.feature_name}</div>
                        {flag.description && (
                          <div className="text-sm text-muted-foreground">
                            {flag.description}
                          </div>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <code className="text-xs bg-muted px-2 py-1 rounded">
                        {flag.feature_key}
                      </code>
                    </TableCell>
                    <TableCell>
                      {flag.category ? (
                        <Badge variant="outline">{flag.category}</Badge>
                      ) : (
                        <span className="text-muted-foreground">ΓÇö</span>
                      )}
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <Switch
                          checked={flag.enabled}
                          onCheckedChange={() => handleToggleFeature(flag)}
                        />
                        <Badge
                          variant={flag.enabled ? "default" : "secondary"}
                        >
                          {flag.enabled ? "Enabled" : "Disabled"}
                        </Badge>
                      </div>
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => openEditDialog(flag)}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDelete(flag)}
                        >
                          <Trash2 className="h-4 w-4 text-destructive" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}

        {/* Edit Dialog */}
        <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>Edit Feature Flag</DialogTitle>
              <DialogDescription>
                Update the feature flag settings
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4">
              <div>
                <Label htmlFor="edit-key">Feature Key</Label>
                <Input
                  id="edit-key"
                  value={formData.feature_key}
                  disabled
                  className="bg-muted"
                />
                <p className="text-xs text-muted-foreground mt-1">
                  Feature key cannot be changed
                </p>
              </div>
              <div>
                <Label htmlFor="edit-name">Feature Name *</Label>
                <Input
                  id="edit-name"
                  value={formData.feature_name}
                  onChange={(e) =>
                    setFormData({ ...formData, feature_name: e.target.value })
                  }
                />
              </div>
              <div>
                <Label htmlFor="edit-description">Description</Label>
                <Textarea
                  id="edit-description"
                  value={formData.description}
                  onChange={(e) =>
                    setFormData({ ...formData, description: e.target.value })
                  }
                  rows={3}
                />
              </div>
              <div>
                <Label htmlFor="edit-category">Category</Label>
                <Input
                  id="edit-category"
                  value={formData.category}
                  onChange={(e) =>
                    setFormData({ ...formData, category: e.target.value })
                  }
                />
              </div>
              <div className="flex items-center space-x-2">
                <Switch
                  id="edit-enabled"
                  checked={formData.enabled}
                  onCheckedChange={(checked) =>
                    setFormData({ ...formData, enabled: checked })
                  }
                />
                <Label htmlFor="edit-enabled">Enabled</Label>
              </div>
              <div className="border-t pt-4 space-y-4">
                <p className="text-sm font-medium text-muted-foreground">Rollout &amp; gating</p>
                <div>
                  <Label htmlFor="edit-rollout">Rollout % (0-100)</Label>
                  <Input
                    id="edit-rollout"
                    type="number"
                    min={0}
                    max={100}
                    value={formData.rollout_percent}
                    onChange={(e) =>
                      setFormData({ ...formData, rollout_percent: parseInt(e.target.value, 10) || 100 })
                    }
                  />
                </div>
                <div>
                  <Label htmlFor="edit-platforms">Platforms allowed (comma-separated: web, customer, provider)</Label>
                  <Input
                    id="edit-platforms"
                    value={formData.platforms_allowed}
                    onChange={(e) =>
                      setFormData({ ...formData, platforms_allowed: e.target.value })
                    }
                    placeholder="web, customer, provider or empty for all"
                  />
                </div>
                <div>
                  <Label htmlFor="edit-roles">Roles allowed (comma-separated)</Label>
                  <Input
                    id="edit-roles"
                    value={formData.roles_allowed}
                    onChange={(e) =>
                      setFormData({ ...formData, roles_allowed: e.target.value })
                    }
                    placeholder="superadmin, provider_owner, customer or empty for all"
                  />
                </div>
                <div>
                  <Label htmlFor="edit-min-version">Min app version</Label>
                  <Input
                    id="edit-min-version"
                    value={formData.min_app_version}
                    onChange={(e) =>
                      setFormData({ ...formData, min_app_version: e.target.value })
                    }
                    placeholder="e.g. 1.2.0 or empty"
                  />
                </div>
                <div>
                  <Label htmlFor="edit-envs">Environments allowed (comma-separated)</Label>
                  <Input
                    id="edit-envs"
                    value={formData.environments_allowed}
                    onChange={(e) =>
                      setFormData({ ...formData, environments_allowed: e.target.value })
                    }
                    placeholder="production, staging, development or empty for all"
                  />
                </div>
              </div>
            </div>
            <DialogFooter>
              <Button
                variant="outline"
                onClick={() => setIsEditDialogOpen(false)}
              >
                Cancel
              </Button>
              <Button onClick={handleEdit}>Save Changes</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>
    </RoleGuard>
  );
}

