          </p>

          <div className="flex items-center justify-between mb-4">
            <div>
              <Label htmlFor="google_calendar_enabled" className="text-sm sm:text-base">
                Enable Google Calendar Integration
              </Label>
              <p className="text-xs sm:text-sm text-gray-600 mt-1">
                Allow providers to sync appointments with Google Calendar
              </p>
            </div>
            <input
              type="checkbox"
              id="google_calendar_enabled"
              checked={safeSettings.google.enabled}
              onChange={(e) =>
                onChange({
                  google: { ...safeSettings.google, enabled: e.target.checked },
                })
              }
              className="w-5 h-5"
            />
          </div>

          {safeSettings.google.enabled && (
            <div className="space-y-4 border-t pt-4">
              <div>
                <Label htmlFor="google_calendar_client_id" className="text-sm sm:text-base">
                  Google Calendar Client ID *
                </Label>
                <Input
                  id="google_calendar_client_id"
                  type="text"
                  value={safeSettings.google.client_id}
                  onChange={(e) =>
                    onChange({
                      google: { ...safeSettings.google, client_id: e.target.value },
                    })
                  }
                  placeholder="xxxxx.apps.googleusercontent.com"
                  className="mt-1 font-mono text-xs sm:text-sm"
                  required
                />
                <p className="text-xs sm:text-sm text-gray-600 mt-1">
                  OAuth 2.0 Client ID from Google Cloud Console
                </p>
              </div>

              <div>
                <Label htmlFor="google_calendar_client_secret" className="text-sm sm:text-base">
                  Google Calendar Client Secret *
                </Label>
                <Input
                  id="google_calendar_client_secret"
                  type="password"
                  value={safeSettings.google.client_secret}
                  onChange={(e) =>
                    onChange({
                      google: { ...safeSettings.google, client_secret: e.target.value },
                    })
                  }
                  placeholder="GOCSPX-..."
                  className="mt-1 font-mono text-xs sm:text-sm"
                  required
                />
                <p className="text-xs sm:text-sm text-gray-600 mt-1">
                  OAuth 2.0 Client Secret from Google Cloud Console (keep secure)
                </p>
              </div>

              <div className="p-3 bg-blue-50 border border-blue-200 rounded-lg">
                <p className="text-xs sm:text-sm text-blue-800">
                  <strong>Redirect URI:</strong> <code className="bg-blue-100 px-1 rounded">
                    {process.env.NEXT_PUBLIC_APP_URL || "https://yourdomain.com"}/api/provider/calendar/callback/google
                  </code>
                </p>
                <p className="text-xs sm:text-sm text-blue-800 mt-2">
                  Make sure to add this exact redirect URI in your Google Cloud Console OAuth client configuration.
                </p>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white border rounded-lg p-4 sm:p-6 space-y-6">
        <div>
          <h3 className="text-base sm:text-lg font-semibold mb-2">Microsoft Outlook Integration</h3>
          <p className="text-sm text-gray-600 mb-4">
            Configure OAuth credentials for Microsoft Outlook. Once configured, providers can connect their own Outlook accounts.
          </p>

          <div className="flex items-center justify-between mb-4">
            <div>
              <Label htmlFor="outlook_enabled" className="text-sm sm:text-base">
                Enable Outlook Integration
              </Label>
              <p className="text-xs sm:text-sm text-gray-600 mt-1">
                Allow providers to sync appointments with Microsoft Outlook
              </p>
            </div>
            <input
              type="checkbox"
              id="outlook_enabled"
              checked={safeSettings.outlook.enabled}
              onChange={(e) =>
                onChange({
                  outlook: { ...safeSettings.outlook, enabled: e.target.checked },
                })
              }
              className="w-5 h-5"
            />
          </div>

          {safeSettings.outlook.enabled && (
            <div className="space-y-4 border-t pt-4">
              <div>
                <Label htmlFor="outlook_client_id" className="text-sm sm:text-base">
                  Outlook Client ID (Application ID) *
                </Label>
                <Input
                  id="outlook_client_id"
                  type="text"
                  value={safeSettings.outlook.client_id}
                  onChange={(e) =>
                    onChange({
                      outlook: { ...safeSettings.outlook, client_id: e.target.value },
                    })
                  }
                  placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"
                  className="mt-1 font-mono text-xs sm:text-sm"
                  required
                />
                <p className="text-xs sm:text-sm text-gray-600 mt-1">
                  Application (client) ID from Azure Portal
                </p>
              </div>

              <div>
                <Label htmlFor="outlook_client_secret" className="text-sm sm:text-base">
                  Outlook Client Secret *
                </Label>
                <Input
                  id="outlook_client_secret"
                  type="password"
                  value={safeSettings.outlook.client_secret}
                  onChange={(e) =>
                    onChange({
                      outlook: { ...safeSettings.outlook, client_secret: e.target.value },
                    })
                  }
                  placeholder="Client secret value"
                  className="mt-1 font-mono text-xs sm:text-sm"
                  required
                />
                <p className="text-xs sm:text-sm text-gray-600 mt-1">
                  Client Secret Value from Azure Portal (keep secure)
                </p>
              </div>

              <div className="p-3 bg-blue-50 border border-blue-200 rounded-lg">
                <p className="text-xs sm:text-sm text-blue-800">
                  <strong>Redirect URI:</strong> <code className="bg-blue-100 px-1 rounded">
                    {process.env.NEXT_PUBLIC_APP_URL || "https://yourdomain.com"}/api/provider/calendar/callback/outlook
                  </code>
                </p>
                <p className="text-xs sm:text-sm text-blue-800 mt-2">
                  Make sure to add this exact redirect URI in your Azure App Registration.
                </p>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white border rounded-lg p-4 sm:p-6 space-y-6">
        <div>
          <h3 className="text-base sm:text-lg font-semibold mb-2">Apple Calendar (iCal) Integration</h3>
          <p className="text-sm text-gray-600 mb-4">
            Apple Calendar uses iCal subscription URLs. No OAuth credentials are required. Providers can subscribe to their calendar feed.
          </p>

          <div className="flex items-center justify-between mb-4">
            <div>
              <Label htmlFor="apple_calendar_enabled" className="text-sm sm:text-base">
                Enable Apple Calendar (iCal) Integration
              </Label>
              <p className="text-xs sm:text-sm text-gray-600 mt-1">
                Allow providers to share iCal subscription URLs for Apple Calendar
              </p>
            </div>
            <input
              type="checkbox"
              id="apple_calendar_enabled"
              checked={safeSettings.apple.enabled}
              onChange={(e) =>
                onChange({
                  apple: { enabled: e.target.checked },
                })
              }
              className="w-5 h-5"
            />
          </div>

          {safeSettings.apple.enabled && (
            <div className="p-3 bg-blue-50 border border-blue-200 rounded-lg">
              <p className="text-xs sm:text-sm text-blue-800">
                <strong>Note:</strong> Apple Calendar uses iCal subscription URLs. Providers can generate and share their calendar feed URL, which customers can subscribe to in Apple Calendar. No OAuth setup is required.
              </p>
            </div>
          )}
        </div>
      </div>

      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
        <p className="text-sm text-yellow-800">
          <strong>How it works:</strong>
          <ul className="list-disc list-inside mt-2 space-y-1 text-xs sm:text-sm">
            <li>Superadmin configures OAuth credentials here (one-time setup for Google/Outlook)</li>
            <li>Each provider connects their own Google/Outlook account through the provider portal</li>
            <li>Each provider's access tokens are stored separately in the database</li>
            <li>Apple Calendar uses iCal subscription URLs (no OAuth required)</li>
            <li>This centralized approach is more secure and easier to manage than per-provider OAuth apps</li>
          </ul>
        </p>
      </div>
    </div>
  );
}

function ProviderSettings({
  settings,
  onChange,
}: {
  settings: PlatformSettings["features"] | undefined;
  onChange: (updates: Partial<PlatformSettings["features"]>) => void;
}) {
  const safeSettings = {
    auto_approve_providers: settings?.auto_approve_providers ?? false,
  };

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold mb-4">Provider Management</h3>
        <p className="text-sm text-gray-600 mb-6">
          Configure how provider applications are processed and approved.
        </p>

        <div className="space-y-6">
          <div className="flex items-center justify-between p-4 border rounded-lg">
            <div className="flex-1">
              <Label htmlFor="auto_approve_providers" className="text-base font-medium">
                Auto-Approve Providers
              </Label>
              <p className="text-sm text-gray-600 mt-1">
                When enabled, new provider applications will be automatically approved and set to active status.
                When disabled, providers will require manual approval by a superadmin.
              </p>
            </div>
            <div className="ml-4">
              <Switch
                id="auto_approve_providers"
                checked={safeSettings.auto_approve_providers}
                onCheckedChange={(checked) =>
                  onChange({ auto_approve_providers: checked })
                }
              />
            </div>
          </div>

          {safeSettings.auto_approve_providers && (
            <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg">
              <p className="text-sm text-blue-800">
                <strong>Note:</strong> With auto-approval enabled, all new provider applications will be automatically
                activated. Make sure you have proper verification and onboarding processes in place.
              </p>
            </div>
          )}

          {!safeSettings.auto_approve_providers && (
            <div className="p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
              <p className="text-sm text-yellow-800">
                <strong>Manual Approval Mode:</strong> New provider applications will be set to "pending_approval" status
                and require manual review in the{" "}
                <Link href="/admin/providers" className="text-[#FF0077] hover:underline font-medium">
                  Providers
                </Link>{" "}
                section.
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Search,
  Building2,
  User,
  Mail,
  Phone,
  Ban,
  CheckCircle2,
} from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Edit, KeyRound } from "lucide-react";

interface StaffMember {
  id: string;
  provider_id: string;
  user_id: string | null;
  name: string;
  email: string | null;
  phone: string | null;
  role: "owner" | "manager" | "employee";
  user_role: string | null; // from users.role: provider_owner | provider_staff
  avatar_url: string | null;
  bio: string | null;
  is_active: boolean;
  commission_percentage: number;
  created_at: string;
  provider: {
    id: string;
    business_name: string;
    slug: string;
  };
}

interface StaffStatistics {
  total: number;
  active: number;
  inactive: number;
  by_staff_role: {
    owner: number;
    manager: number;
    employee: number;
  };
  by_user_role: {
    provider_owner: number;
    provider_staff: number;
    no_account: number;
  };
}

export default function AdminStaff() {
  const [staff, setStaff] = useState<StaffMember[]>([]);
  const [statistics, setStatistics] = useState<StaffStatistics | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [staffRoleFilter, setStaffRoleFilter] = useState<string>("all");
  const [userRoleFilter, setUserRoleFilter] = useState<string>("all");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [editingMember, setEditingMember] = useState<StaffMember | null>(null);
  const [editForm, setEditForm] = useState<{ name: string; email: string; phone: string; role: string; commission_percentage: number; bio: string }>({ name: "", email: "", phone: "", role: "employee", commission_percentage: 0, bio: "" });
  const [isSavingEdit, setIsSavingEdit] = useState(false);
  const [isSendingReset, setIsSendingReset] = useState<string | null>(null);

  useEffect(() => {
    loadStaff();
  }, [staffRoleFilter, userRoleFilter, statusFilter]); // eslint-disable-line react-hooks/exhaustive-deps -- load when filters change

  const loadStaff = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      if (staffRoleFilter !== "all") params.set("role", staffRoleFilter);
      if (userRoleFilter !== "all") params.set("user_role", userRoleFilter);
      if (statusFilter !== "all") params.set("is_active", statusFilter === "active" ? "true" : "false");

      const response = await fetcher.get<{
        data: { staff: StaffMember[]; statistics: StaffStatistics };
      }>(`/api/admin/staff?${params.toString()}`);

      const data = (response as { data?: { staff?: StaffMember[]; statistics?: StaffStatistics } }).data;
      setStaff(data?.staff || []);
      setStatistics(data?.statistics ?? null);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load staff";
      setError(errorMessage);
      console.error("Error loading staff:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleToggleActive = async (staffId: string, currentStatus: boolean) => {
    try {
      await fetcher.patch(`/api/admin/staff/${staffId}`, {
        is_active: !currentStatus,
      });
      toast.success(`Staff member ${!currentStatus ? "activated" : "deactivated"}`);
      loadStaff();
    } catch (error: any) {
      toast.error(error.message || "Failed to update staff status");
    }
  };

  const openEditModal = (member: StaffMember) => {
    setEditingMember(member);
    setEditForm({
      name: member.name ?? "",
      email: member.email ?? "",
      phone: member.phone ?? "",
      role: member.role ?? "employee",
      commission_percentage: member.commission_percentage ?? 0,
      bio: member.bio ?? "",
    });
  };

  const handleSaveEdit = async () => {
    if (!editingMember) return;
    try {
      setIsSavingEdit(true);
      await fetcher.patch(`/api/admin/staff/${editingMember.id}`, {
        name: editForm.name,
        email: editForm.email || null,
        phone: editForm.phone || null,
        role: editForm.role,
        commission_percentage: editForm.commission_percentage,
        bio: editForm.bio || null,
      });
      toast.success("Staff details updated");
      setEditingMember(null);
      loadStaff();
    } catch (error: any) {
      toast.error(error.message || "Failed to update");
    } finally {
      setIsSavingEdit(false);
    }
  };

  const handleSendPasswordReset = async (member: StaffMember) => {
    if (!member.email && !member.user_id) {
      toast.error("Add an email for this staff member first");
      return;
    }
    try {
      setIsSendingReset(member.id);
      await fetcher.post(`/api/admin/staff/${member.id}/reset-password`, {});
      toast.success("Password reset email sent");
    } catch (error: any) {
      toast.error(error.message || "Failed to send reset email");
    } finally {
      setIsSendingReset(null);
    }
  };

  const getStaffRoleBadgeColor = (role: string) => {
    switch (role) {
      case "owner":
        return "bg-purple-100 text-purple-800";
      case "manager":
        return "bg-blue-100 text-blue-800";
      case "employee":
        return "bg-gray-100 text-gray-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  const getUserRoleLabel = (userRole: string | null) => {
    if (!userRole) return "ΓÇö";
    if (userRole === "provider_owner") return "Provider owner";
    if (userRole === "provider_staff") return "Provider staff";
    return userRole;
  };

  const getUserRoleBadgeColor = (userRole: string | null) => {
    if (!userRole) return "bg-gray-100 text-gray-500";
    if (userRole === "provider_owner") return "bg-amber-100 text-amber-800";
    if (userRole === "provider_staff") return "bg-sky-100 text-sky-800";
    return "bg-gray-100 text-gray-800";
  };

  const filteredStaff = staff.filter((member) => {
    if (!searchQuery) return true;
    const query = searchQuery.toLowerCase();
    return (
      (member.name ?? "").toLowerCase().includes(query) ||
      (member.email ?? "").toLowerCase().includes(query) ||
      (member.phone ?? "").toLowerCase().includes(query) ||
      (member.provider?.business_name ?? "").toLowerCase().includes(query)
    );
  });

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading staff..." />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="mb-6">
          <h1 className="text-3xl font-semibold mb-2">Staff Management</h1>
          <p className="text-gray-600">Manage staff members across all providers</p>
        </div>

        {/* Statistics */}
        {statistics && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4 mb-6">
            <div className="bg-white border rounded-lg p-4">
              <p className="text-sm text-gray-600 mb-1">Total Staff</p>
              <p className="text-2xl font-semibold">{statistics.total}</p>
            </div>
            <div className="bg-white border rounded-lg p-4">
              <p className="text-sm text-gray-600 mb-1">Active</p>
              <p className="text-2xl font-semibold text-green-600">{statistics.active}</p>
            </div>
            <div className="bg-white border rounded-lg p-4">
              <p className="text-sm text-gray-600 mb-1">Provider owners</p>
              <p className="text-2xl font-semibold">{statistics.by_user_role?.provider_owner ?? 0}</p>
            </div>
            <div className="bg-white border rounded-lg p-4">
              <p className="text-sm text-gray-600 mb-1">Provider staff</p>
              <p className="text-2xl font-semibold">{statistics.by_user_role?.provider_staff ?? 0}</p>
            </div>
            <div className="bg-white border rounded-lg p-4">
              <p className="text-sm text-gray-600 mb-1">Staff role: Manager</p>
              <p className="text-2xl font-semibold">{statistics.by_staff_role?.manager ?? 0}</p>
            </div>
            <div className="bg-white border rounded-lg p-4">
              <p className="text-sm text-gray-600 mb-1">Staff role: Employee</p>
              <p className="text-2xl font-semibold">{statistics.by_staff_role?.employee ?? 0}</p>
            </div>
          </div>
        )}

        {/* Search and Filters */}
        <div className="mb-6 space-y-4">
          <div className="flex gap-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
              <Input
                placeholder="Search by name, email, phone, or provider..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>
            <select
              value={userRoleFilter}
              onChange={(e) => setUserRoleFilter(e.target.value)}
              className="px-4 py-2 border rounded-md bg-white"
              title="Account role (users table)"
            >
              <option value="all">All account roles</option>
              <option value="provider_owner">Provider owner</option>
              <option value="provider_staff">Provider staff</option>
            </select>
            <select
              value={staffRoleFilter}
              onChange={(e) => setStaffRoleFilter(e.target.value)}
              className="px-4 py-2 border rounded-md bg-white"
              title="Staff role within provider"
            >
              <option value="all">All staff roles</option>
              <option value="owner">Owner</option>
              <option value="manager">Manager</option>
              <option value="employee">Employee</option>
            </select>
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="px-4 py-2 border rounded-md bg-white"
            >
              <option value="all">All Status</option>
              <option value="active">Active</option>
              <option value="inactive">Inactive</option>
            </select>
          </div>
        </div>

        {/* Staff Table */}
        {error ? (
          <EmptyState
            title="Failed to load staff"
            description={error}
            action={{ label: "Retry", onClick: loadStaff }}
          />
        ) : filteredStaff.length === 0 ? (
          <EmptyState
            title="No staff found"
            description="No staff members match your search criteria"
          />
        ) : (
          <div className="bg-white border rounded-lg overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Staff Member</TableHead>
                  <TableHead>Provider</TableHead>
                  <TableHead>Contact</TableHead>
                  <TableHead>Account role</TableHead>
                  <TableHead>Staff role</TableHead>
                  <TableHead>Commission</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredStaff.map((member) => (
                  <TableRow key={member.id}>
                    <TableCell>
                      <div className="flex items-center gap-3">
                        {member.avatar_url ? (
                          <img
                            className="h-10 w-10 rounded-full"
                            src={member.avatar_url}
                            alt={member.name}
                          />
                        ) : (
                          <div className="h-10 w-10 rounded-full bg-gray-200 flex items-center justify-center">
                            <User className="w-5 h-5 text-gray-500" />
                          </div>
                        )}
                        <div>
                          <div className="font-medium">{member.name}</div>
                          {member.bio && (
                            <div className="text-sm text-gray-500 truncate max-w-xs">
                              {member.bio}
                            </div>
                          )}
                        </div>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <Building2 className="w-4 h-4 text-gray-400" />
                        <span className="font-medium">{member.provider.business_name}</span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="space-y-1">
                        {member.email && (
                          <div className="flex items-center gap-2 text-sm">
                            <Mail className="w-3 h-3 text-gray-400" />
                            <span>{member.email}</span>
                          </div>
                        )}
                        {member.phone && (
                          <div className="flex items-center gap-2 text-sm">
                            <Phone className="w-3 h-3 text-gray-400" />
                            <span>{member.phone}</span>
                          </div>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge className={getUserRoleBadgeColor(member.user_role ?? null)}>
                        {getUserRoleLabel(member.user_role ?? null)}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Badge className={getStaffRoleBadgeColor(member.role)}>
                        {member.role}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      {member.commission_percentage > 0 ? (
                        <span className="font-medium">{member.commission_percentage}%</span>
                      ) : (
                        <span className="text-gray-400">ΓÇö</span>
                      )}
                    </TableCell>
                    <TableCell>
                      {member.is_active ? (
                        <Badge className="bg-green-100 text-green-800">
                          <CheckCircle2 className="w-3 h-3 mr-1" />
                          Active
                        </Badge>
                      ) : (
                        <Badge className="bg-red-100 text-red-800">
                          <Ban className="w-3 h-3 mr-1" />
                          Inactive
                        </Badge>
                      )}
                    </TableCell>
                    <TableCell>
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="outline" size="sm">
                            Actions
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={() => openEditModal(member)}>
                            <Edit className="w-4 h-4 mr-2" />
                            Edit details
                          </DropdownMenuItem>
                          <DropdownMenuItem
                            onClick={() => handleSendPasswordReset(member)}
                            disabled={(!member.email && !member.user_id) || isSendingReset === member.id}
                          >
                            <KeyRound className="w-4 h-4 mr-2" />
                            {isSendingReset === member.id ? "SendingΓÇª" : "Send password reset"}
                          </DropdownMenuItem>
                          <DropdownMenuItem
                            onClick={() => handleToggleActive(member.id, member.is_active)}
                          >
                            {member.is_active ? "Deactivate" : "Activate"}
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}

        {/* Edit staff dialog */}
        <Dialog open={!!editingMember} onOpenChange={(open) => !open && setEditingMember(null)}>
          <DialogContent className="sm:max-w-md">
            <DialogHeader>
              <DialogTitle>Edit staff member</DialogTitle>
            </DialogHeader>
            {editingMember && (
              <div className="space-y-4 py-2">
                <div>
                  <Label htmlFor="edit-name">Name</Label>
                  <Input
                    id="edit-name"
                    value={editForm.name}
                    onChange={(e) => setEditForm((f) => ({ ...f, name: e.target.value }))}
                    className="mt-1"
                  />
                </div>
                <div>
                  <Label htmlFor="edit-email">Email</Label>
                  <Input
                    id="edit-email"
                    type="email"
                    value={editForm.email}
                    onChange={(e) => setEditForm((f) => ({ ...f, email: e.target.value }))}
                    className="mt-1"
                  />
                </div>
                <div>
                  <Label htmlFor="edit-phone">Phone</Label>
                  <Input
                    id="edit-phone"
                    value={editForm.phone}
                    onChange={(e) => setEditForm((f) => ({ ...f, phone: e.target.value }))}
                    className="mt-1"
                  />
                </div>
                <div>
                  <Label htmlFor="edit-role">Staff role</Label>
                  <select
                    id="edit-role"
                    value={editForm.role}
                    onChange={(e) => setEditForm((f) => ({ ...f, role: e.target.value }))}
                    className="mt-1 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                  >
                    <option value="owner">Owner</option>
                    <option value="manager">Manager</option>
                    <option value="employee">Employee</option>
                  </select>
                </div>
                <div>
                  <Label htmlFor="edit-commission">Commission %</Label>
                  <Input
                    id="edit-commission"
                    type="number"
                    min={0}
                    max={100}
                    step={0.01}
                    value={editForm.commission_percentage}
                    onChange={(e) => setEditForm((f) => ({ ...f, commission_percentage: parseFloat(e.target.value) || 0 }))}
                    className="mt-1"
                  />
                </div>
                <div>
                  <Label htmlFor="edit-bio">Bio</Label>
                  <Textarea
                    id="edit-bio"
                    value={editForm.bio}
                    onChange={(e) => setEditForm((f) => ({ ...f, bio: e.target.value }))}
                    className="mt-1 min-h-[80px]"
                  />
                </div>
              </div>
            )}
            <DialogFooter>
              <Button variant="outline" onClick={() => setEditingMember(null)}>
                Cancel
              </Button>
              <Button onClick={handleSaveEdit} disabled={isSavingEdit}>
                {isSavingEdit ? "SavingΓÇª" : "Save"}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { Badge } from "@/components/ui/badge";
import { Plus, Edit, CreditCard, Gift, ChevronDown, ChevronRight } from "lucide-react";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";

// Complex feature gating structure matching migration 133
interface FeatureGating {
  marketing_campaigns?: {
    enabled: boolean;
    channels?: string[];
    max_campaigns_per_month?: number | null;
    max_recipients_per_campaign?: number | null;
    advanced_segmentation?: boolean;
    custom_integrations?: boolean;
  };
  chat_messages?: {
    enabled: boolean;
    max_messages_per_month?: number | null;
    file_attachments?: boolean;
    group_chats?: boolean;
  };
  yoco_integration?: {
    enabled: boolean;
    max_devices?: number | null;
    advanced_features?: boolean;
  };
  staff_management?: {
    enabled: boolean;
    max_staff_members?: number | null;
  };
  multi_location?: {
    enabled: boolean;
    max_locations?: number | null;
  };
  booking_limits?: {
    enabled: boolean;
    max_bookings_per_month?: number | null;
  };
  advanced_analytics?: {
    enabled: boolean;
    basic_reports?: boolean;
    advanced_reports?: boolean;
    data_export?: boolean;
    api_access?: boolean;
    report_types?: string[];
  };
  marketing_automations?: {
    enabled: boolean;
    max_automations?: number | null;
  };
  recurring_appointments?: {
    enabled: boolean;
    advanced_patterns?: boolean;
  };
  express_booking?: {
    enabled: boolean;
    max_links?: number | null;
  };
  calendar_sync?: {
    enabled: boolean;
    providers?: string[];
    api_access?: boolean;
  };
}

interface PricingPlanLink {
  id: string;
  name: string;
  price: string;
  period: string | null;
  description: string | null;
  cta_text: string;
  is_popular: boolean;
  display_order: number;
  subscription_plan_id: string | null;
}

interface SubscriptionPlan {
  id: string;
  name: string;
  description?: string;
  price_monthly?: number;
  price_yearly?: number;
  currency: string;
  features: FeatureGating | string[] | null; // Support both complex and legacy
  is_free: boolean;
  is_active: boolean;
  is_popular: boolean;
  display_order: number;
  max_bookings_per_month?: number | null;
  max_staff_members?: number | null;
  max_locations: number;
  paystack_plan_code_monthly?: string;
  paystack_plan_code_yearly?: string;
  created_at: string;
  updated_at: string;
  pricing_plan?: PricingPlanLink | null;
}

// Default feature structure
const getDefaultFeatures = (): FeatureGating => ({
  marketing_campaigns: {
    enabled: false,
    channels: [],
    max_campaigns_per_month: null,
    max_recipients_per_campaign: null,
    advanced_segmentation: false,
    custom_integrations: false,
  },
  chat_messages: {
    enabled: true,
    max_messages_per_month: 50,
    file_attachments: false,
    group_chats: false,
  },
  yoco_integration: {
    enabled: false,
    max_devices: 0,
    advanced_features: false,
  },
  staff_management: {
    enabled: false,
    max_staff_members: 0,
  },
  multi_location: {
    enabled: true,
    max_locations: 1,
  },
  booking_limits: {
    enabled: true,
    max_bookings_per_month: 10,
  },
  advanced_analytics: {
    enabled: false,
    basic_reports: false,
    advanced_reports: false,
    data_export: false,
    api_access: false,
    report_types: [],
  },
  marketing_automations: {
    enabled: false,
    max_automations: 0,
  },
  recurring_appointments: {
    enabled: false,
    advanced_patterns: false,
  },
  express_booking: {
    enabled: false,
    max_links: 0,
  },
  calendar_sync: {
    enabled: false,
    providers: [],
    api_access: false,
  },
});

// Available channels and providers
const MARKETING_CHANNELS = ["email", "sms", "whatsapp"];
const CALENDAR_PROVIDERS = ["google", "outlook", "ical"];
const REPORT_TYPES = ["sales", "bookings", "staff", "clients", "products", "payments", "gift_cards", "packages"];

type PlansPageProps = { useMergedPlans?: boolean };

export default function SubscriptionPlansPage({ useMergedPlans = false }: PlansPageProps) {
  const [plans, setPlans] = useState<SubscriptionPlan[]>([]);
  const [loading, setLoading] = useState(true);
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState<SubscriptionPlan | null>(null);
  const [expandedFeatures, setExpandedFeatures] = useState<Record<string, boolean>>({});

  const [formData, setFormData] = useState({
    name: "",
    description: "",
    price_monthly: "",
    price_yearly: "",
    currency: "ZAR",
    features: getDefaultFeatures(),
    is_free: false,
    is_active: true,
    is_popular: false,
    display_order: 0,
    max_bookings_per_month: "",
    max_staff_members: "",
    max_locations: "1",
    paystack_plan_code_monthly: "",
    paystack_plan_code_yearly: "",
    // Pricing page (public) - when useMergedPlans
    show_on_pricing_page: false,
    price_display: "",
    period_display: "month",
    description_display: "",
    cta_text: "Get started",
    display_order_pricing: 0,
  });

  // Helper to normalize features from API (handle both legacy array and complex object)
  const normalizeFeatures = (features: any): FeatureGating => {
    if (!features) return getDefaultFeatures();
    if (Array.isArray(features)) return getDefaultFeatures(); // Legacy array format
    if (typeof features === 'object') {
      // Merge with defaults to ensure all fields exist
      const defaults = getDefaultFeatures();
      return {
        ...defaults,
        ...features,
        marketing_campaigns: { ...defaults.marketing_campaigns, ...features.marketing_campaigns },
        chat_messages: { ...defaults.chat_messages, ...features.chat_messages },
        yoco_integration: { ...defaults.yoco_integration, ...features.yoco_integration },
        staff_management: { ...defaults.staff_management, ...features.staff_management },
        multi_location: { ...defaults.multi_location, ...features.multi_location },
        booking_limits: { ...defaults.booking_limits, ...features.booking_limits },
        advanced_analytics: { ...defaults.advanced_analytics, ...features.advanced_analytics },
        marketing_automations: { ...defaults.marketing_automations, ...features.marketing_automations },
        recurring_appointments: { ...defaults.recurring_appointments, ...features.recurring_appointments },
        express_booking: { ...defaults.express_booking, ...features.express_booking },
        calendar_sync: { ...defaults.calendar_sync, ...features.calendar_sync },
      };
    }
    return getDefaultFeatures();
  };

  const fetchPlans = async () => {
    try {
      setLoading(true);
      const url = useMergedPlans ? "/api/admin/plans" : "/api/admin/subscription-plans";
      const response = await fetcher.get<{ data: SubscriptionPlan[] }>(url);
      setPlans(response.data || []);
    } catch (error) {
      console.error("Error fetching plans:", error);
      toast.error("Failed to load subscription plans");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPlans();
  }, []);

  const handleCreate = () => {
    setSelectedPlan(null);
    setFormData({
      name: "",
      description: "",
      price_monthly: "",
      price_yearly: "",
      currency: "ZAR",
      features: getDefaultFeatures(),
      is_free: false,
      is_active: true,
      is_popular: false,
      display_order: plans.length,
      max_bookings_per_month: "",
      max_staff_members: "",
      max_locations: "1",
      paystack_plan_code_monthly: "",
      paystack_plan_code_yearly: "",
      show_on_pricing_page: false,
      price_display: "",
      period_display: "month",
      description_display: "",
      cta_text: "Get started",
      display_order_pricing: plans.length,
    });
    setIsCreateDialogOpen(true);
  };

  const handleEdit = (plan: SubscriptionPlan) => {
    setSelectedPlan(plan);
    const normalizedFeatures = normalizeFeatures(plan.features);
    const pp = plan.pricing_plan;
    setFormData({
      name: plan.name,
      description: plan.description || "",
      price_monthly: plan.price_monthly?.toString() || "",
      price_yearly: plan.price_yearly?.toString() || "",
      currency: plan.currency,
      features: normalizedFeatures,
      is_free: plan.is_free,
      is_active: plan.is_active,
      is_popular: plan.is_popular,
      display_order: plan.display_order,
      max_bookings_per_month: plan.max_bookings_per_month?.toString() || "",
      max_staff_members: plan.max_staff_members?.toString() || "",
      max_locations: plan.max_locations?.toString() || "1",
      paystack_plan_code_monthly: plan.paystack_plan_code_monthly || "",
      paystack_plan_code_yearly: plan.paystack_plan_code_yearly || "",
      show_on_pricing_page: !!pp,
      price_display: pp?.price || "",
      period_display: pp?.period || "month",
      description_display: pp?.description || "",
      cta_text: pp?.cta_text || "Get started",
      display_order_pricing: pp?.display_order ?? plan.display_order,
    });
    setIsEditDialogOpen(true);
  };

  const handleSubmit = async () => {
    try {
      const payload = {
        ...(selectedPlan ? { id: selectedPlan.id } : {}),
        name: formData.name,
        description: formData.description || undefined,
        price_monthly: formData.is_free ? undefined : parseFloat(formData.price_monthly) || undefined,
        price_yearly: formData.is_free ? undefined : parseFloat(formData.price_yearly) || undefined,
        currency: formData.currency,
        features: formData.features,
        is_free: formData.is_free,
        is_active: formData.is_active,
        is_popular: formData.is_popular,
        display_order: formData.display_order,
        max_bookings_per_month: formData.max_bookings_per_month ? parseInt(formData.max_bookings_per_month) : null,
        max_staff_members: formData.max_staff_members ? parseInt(formData.max_staff_members) : null,
        max_locations: parseInt(formData.max_locations) || 1,
        paystack_plan_code_monthly: formData.paystack_plan_code_monthly || null,
        paystack_plan_code_yearly: formData.paystack_plan_code_yearly || null,
      };

      let savedPlan: SubscriptionPlan;
      if (selectedPlan) {
        const res = await fetcher.put<{ data: SubscriptionPlan }>("/api/admin/subscription-plans", payload);
        savedPlan = res.data;
        toast.success("Plan updated successfully");
      } else {
        const res = await fetcher.post<{ data: SubscriptionPlan }>("/api/admin/subscription-plans", payload);
        savedPlan = res.data;
        toast.success("Plan created successfully");
      }

      // When consolidated view: sync pricing page entry so public pricing and onboarding use it
      if (useMergedPlans && formData.show_on_pricing_page && savedPlan?.id) {
        const pricingPayload = {
          ...(selectedPlan?.pricing_plan ? { id: selectedPlan.pricing_plan.id } : {}),
          name: formData.name,
          price: formData.price_display || (savedPlan.price_monthly != null ? String(savedPlan.price_monthly) : "0"),
          period: formData.period_display || null,
          description: formData.description_display || null,
          cta_text: formData.cta_text,
          is_popular: formData.is_popular,
          display_order: formData.display_order_pricing,
          is_active: savedPlan.is_active,
          subscription_plan_id: savedPlan.id,
          paystack_plan_code_monthly: savedPlan.paystack_plan_code_monthly || null,
          paystack_plan_code_yearly: savedPlan.paystack_plan_code_yearly || null,
        };
        if (selectedPlan?.pricing_plan) {
          await fetcher.put("/api/admin/pricing-plans", pricingPayload);
        } else {
          await fetcher.post("/api/admin/pricing-plans", pricingPayload);
        }
      } else if (useMergedPlans && !formData.show_on_pricing_page && selectedPlan?.pricing_plan) {
        // Unlink: deactivate or delete pricing plan so it no longer appears on public page
        await fetcher.put("/api/admin/pricing-plans", {
          id: selectedPlan.pricing_plan.id,
          is_active: false,
          subscription_plan_id: null,
        });
      }

      setIsCreateDialogOpen(false);
      setIsEditDialogOpen(false);
      fetchPlans();
    } catch (error) {
      const errorMessage =
        error instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : error instanceof FetchError
          ? error.message
          : "Failed to save plan";
      toast.error(errorMessage);
      console.error("Error saving plan:", error);
    }
  };

  const updateFeature = (category: keyof FeatureGating, updates: any) => {
    setFormData((prev) => ({
      ...prev,
      features: {
        ...prev.features,
        [category]: {
          ...prev.features[category],
          ...updates,
        },
      },
    }));
  };

  const toggleFeatureCategory = (category: keyof FeatureGating) => {
    const current = formData.features[category];
    updateFeature(category, { enabled: !current?.enabled });
  };

  const toggleArrayItem = (category: keyof FeatureGating, field: string, item: string) => {
    const current = formData.features[category] as any;
    const currentArray = (current?.[field] as string[]) || [];
    const newArray = currentArray.includes(item)
      ? currentArray.filter((i) => i !== item)
      : [...currentArray, item];
    updateFeature(category, { [field]: newArray });
  };

  const getFeatureSummary = (plan: SubscriptionPlan): string => {
    const features = normalizeFeatures(plan.features);
    const enabled = Object.values(features).filter((f) => f?.enabled).length;
    const total = Object.keys(features).length;
    return `${enabled}/${total} enabled`;
  };

  if (loading) {
    return (
      <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
        <LoadingTimeout loadingMessage={useMergedPlans ? "Loading plans..." : "Loading subscription plans..."} />
      </RoleGuard>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="container mx-auto p-6 space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold">
              {useMergedPlans ? "Plans" : "Subscription Plans"}
            </h1>
            <p className="text-gray-600 mt-1">
              {useMergedPlans
                ? "Manage subscription tiers, feature access, and public pricing page in one place"
                : "Manage subscription tiers and feature access with granular controls"}
            </p>
          </div>
          <Button onClick={handleCreate}>
            <Plus className="w-4 h-4 mr-2" />
            Create Plan
          </Button>
        </div>

        {plans.length === 0 ? (
          <EmptyState
            title={useMergedPlans ? "No plans" : "No subscription plans"}
            description={useMergedPlans ? "Create your first plan to get started" : "Create your first subscription plan to get started"}
            action={{
              label: "Create Plan",
              onClick: handleCreate,
            }}
          />
        ) : (
          <div className="bg-white rounded-lg border shadow-sm">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Name</TableHead>
                  {useMergedPlans && <TableHead>On pricing page</TableHead>}
                  <TableHead>Type</TableHead>
                  <TableHead>Pricing</TableHead>
                  <TableHead>Features</TableHead>
                  <TableHead>Limits</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Paystack</TableHead>
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {plans.map((plan) => (
                  <TableRow key={plan.id}>
                    <TableCell className="font-medium">
                      <div className="flex items-center gap-2">
                        {plan.name}
                        {plan.is_popular && (
                          <Badge variant="secondary" className="bg-pink-100 text-pink-800">
                            Popular
                          </Badge>
                        )}
                      </div>
                    </TableCell>
                    {useMergedPlans && (
                      <TableCell>
                        {plan.pricing_plan ? (
                          <Badge variant="outline" className="bg-green-50 text-green-800">Yes</Badge>
                        ) : (
                          <span className="text-gray-400 text-sm">No</span>
                        )}
                      </TableCell>
                    )}
                    <TableCell>
                      {plan.is_free ? (
                        <Badge className="bg-green-100 text-green-800">
                          <Gift className="w-3 h-3 mr-1" />
                          Free
                        </Badge>
                      ) : (
                        <Badge variant="outline">
                          <CreditCard className="w-3 h-3 mr-1" />
                          Paid
                        </Badge>
                      )}
                    </TableCell>
                    <TableCell>
                      {plan.is_free ? (
                        <span className="text-gray-500">Free</span>
                      ) : (
                        <div className="text-sm">
                          {plan.price_monthly && (
                            <div>
                              {plan.currency} {plan.price_monthly}/mo
                            </div>
                          )}
                          {plan.price_yearly && (
                            <div className="text-gray-500">
                              {plan.currency} {plan.price_yearly}/yr
                            </div>
                          )}
                        </div>
                      )}
                    </TableCell>
                    <TableCell>
                      <div className="text-sm text-gray-600">
                        {getFeatureSummary(plan)}
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="text-sm text-gray-600">
                        {plan.max_bookings_per_month
                          ? `${plan.max_bookings_per_month} bookings/mo`
                          : "Unlimited"}
                        <br />
                        {plan.max_staff_members
                          ? `${plan.max_staff_members} staff`
                          : "Unlimited staff"}
                        <br />
                        {plan.max_locations} location{plan.max_locations !== 1 ? "s" : ""}
                      </div>
                    </TableCell>
                    <TableCell>
                      {plan.is_active ? (
                        <Badge className="bg-green-100 text-green-800">Active</Badge>
                      ) : (
                        <Badge variant="secondary">Inactive</Badge>
                      )}
                    </TableCell>
                    <TableCell>
                      <div className="text-xs text-gray-500">
                        {plan.paystack_plan_code_monthly && (
                          <div>Monthly: {plan.paystack_plan_code_monthly.slice(0, 8)}...</div>
                        )}
                        {plan.paystack_plan_code_yearly && (
                          <div>Yearly: {plan.paystack_plan_code_yearly.slice(0, 8)}...</div>
                        )}
                        {!plan.paystack_plan_code_monthly && !plan.paystack_plan_code_yearly && (
                          <span>Not synced</span>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleEdit(plan)}
                      >
                        <Edit className="w-4 h-4" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}

        {/* Create/Edit Dialog */}
        <Dialog
          open={isCreateDialogOpen || isEditDialogOpen}
          onOpenChange={(open) => {
            if (!open) {
              setIsCreateDialogOpen(false);
              setIsEditDialogOpen(false);
            }
          }}
        >
          <DialogContent className="max-w-5xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
