"use client";

import React, { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { RefreshCw, Activity, Database, Server, AlertTriangle, CheckCircle2, XCircle, Clock } from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import RoleGuard from "@/components/auth/RoleGuard";

interface SystemStats {
  api_requests: {
    total: number;
    successful: number;
    failed: number;
    avg_response_time: number;
  };
  database: {
    connections: number;
    query_time: number;
    slow_queries: number;
  };
  server: {
    cpu_usage: number;
    memory_usage: number;
    disk_usage: number;
  };
  errors: {
    total: number;
    rate: number;
  };
}

interface HealthMetric {
  id: string;
  metric_type: string;
  metric_name: string;
  value: number;
  unit: string;
  status: string;
  recorded_at: string;
}

interface ErrorLogEntry {
  id?: string;
  error_type?: string;
  error_message?: string;
  endpoint?: string;
  severity?: string;
  created_at?: string;
}

export default function SystemHealthPage() {
  const [stats, setStats] = useState<SystemStats | null>(null);
  const [metrics, setMetrics] = useState<HealthMetric[]>([]);
  const [recentErrorLogs, setRecentErrorLogs] = useState<ErrorLogEntry[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [autoRefresh, setAutoRefresh] = useState(true);

  useEffect(() => {
    loadHealthData();

    if (autoRefresh) {
      const interval = setInterval(() => {
        loadHealthData();
      }, 30000); // Refresh every 30 seconds

      return () => clearInterval(interval);
    }
  }, [autoRefresh]);

  const loadHealthData = async () => {
    try {
      setIsLoading(true);
      const [healthResponse, errorsResponse] = await Promise.all([
        fetcher.get<{ data?: Record<string, any> }>("/api/admin/monitoring/health?hours=24"),
        fetcher.get<{ data?: { stats?: { total?: number; recent_errors?: Array<{ id?: string; error_type?: string; error_message?: string; endpoint?: string; severity?: string; created_at?: string }> }; logs?: any[] } }>("/api/admin/monitoring/errors?timeframe=24h"),
      ]);

      const healthData = healthResponse?.data ?? {};
      const errorsData = errorsResponse?.data ?? {};
      const errorsTotal = (errorsData as { stats?: { total?: number } }).stats?.total ?? 0;
      const recentErrors = (errorsData as { stats?: { recent_errors?: any[] }; logs?: any[] }).stats?.recent_errors ?? (errorsData as { logs?: any[] }).logs ?? [];

      // Transform health data to match existing interface (health = endpoint checks, not request counts)
      setStats({
        api_requests: {
          total: Number((healthData as { total_endpoints?: number }).total_endpoints) || 0,
          successful: Number((healthData as { healthy_endpoints?: number }).healthy_endpoints) || 0,
          failed: Number((healthData as { down_endpoints?: number }).down_endpoints) || 0,
          avg_response_time: Number((healthData as { average_response_time_ms?: number }).average_response_time_ms) || 0,
        },
        database: {
          connections: 0,
          query_time: 0,
          slow_queries: 0,
        },
        server: {
          cpu_usage: 0,
          memory_usage: 0,
          disk_usage: 0,
        },
        errors: {
          total: errorsTotal,
          rate: errorsTotal / 24, // errors per hour for 24h window
        },
      });

      // Transform endpoints to metrics for API tab
      const endpoints = (healthData as { endpoints?: Array<{ endpoint?: string; method?: string; average_response_time_ms?: number; last_status?: string; last_check?: string }> }).endpoints ?? [];
      const metrics: HealthMetric[] = endpoints.map((endpoint: { endpoint?: string; method?: string; average_response_time_ms?: number; last_status?: string; last_check?: string }) => ({
        id: `${endpoint.endpoint ?? ""}-${endpoint.method ?? ""}`,
        metric_type: "api_endpoint",
        metric_name: `${endpoint.method ?? "GET"} ${endpoint.endpoint ?? ""}`,
        value: endpoint.average_response_time_ms ?? 0,
        unit: "ms",
        status: endpoint.last_status ?? "unknown",
        recorded_at: endpoint.last_check ?? "",
      }));

      setMetrics(metrics);
      setRecentErrorLogs(Array.isArray(recentErrors) ? recentErrors : []);
      setLastUpdated(new Date());
      setError(null);
    } catch (err) {
      console.error("Failed to load system health:", err);
      const errorMessage = err instanceof Error ? err.message : "Failed to load system health data";
      setError(errorMessage);
      toast.error(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch ((status ?? "").toLowerCase()) {
      case "healthy":
        return "bg-green-100 text-green-800";
      case "warning":
      case "degraded":
      case "medium":
        return "bg-yellow-100 text-yellow-800";
      case "error":
      case "critical":
      case "high":
      case "down":
        return "bg-red-100 text-red-800";
      case "low":
        return "bg-gray-100 text-gray-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  const getStatusIcon = (status: string) => {
    switch ((status ?? "").toLowerCase()) {
      case "healthy":
        return <CheckCircle2 className="w-4 h-4 text-green-600" />;
      case "warning":
      case "degraded":
        return <AlertTriangle className="w-4 h-4 text-yellow-600" />;
      case "error":
      case "critical":
      case "down":
        return <XCircle className="w-4 h-4 text-red-600" />;
      default:
        return <Clock className="w-4 h-4 text-muted-foreground" />;
    }
  };

  if (isLoading && !stats) {
    return (
      <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
        <div className="container mx-auto px-4 py-8">
          <LoadingTimeout loadingMessage="Loading system health..." />
        </div>
      </RoleGuard>
    );
  }

  if (error && !stats) {
    return (
      <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
        <div className="container mx-auto px-4 py-8">
          <EmptyState
            title="Failed to load system health data"
            description={error}
            action={{
              label: "Retry",
              onClick: loadHealthData,
            }}
          />
        </div>
      </RoleGuard>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/admin/dashboard">
    <div className="container mx-auto px-4 py-8">
        <div className="flex justify-between items-center mb-6">
          <div>
            <h1 className="text-2xl font-bold">System Health & Monitoring</h1>
            <p className="text-gray-600 mt-1">Real-time system metrics and performance</p>
          </div>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setAutoRefresh(!autoRefresh)}
            >
              Auto-refresh: {autoRefresh ? "ON" : "OFF"}
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={loadHealthData}
              disabled={isLoading}
            >
              <RefreshCw className={`w-4 h-4 mr-2 ${isLoading ? "animate-spin" : ""}`} />
              Refresh
            </Button>
          </div>
        </div>

        {lastUpdated && (
          <div className="mb-4 text-sm text-gray-500">
            Last updated: {lastUpdated.toLocaleString()}
          </div>
        )}

        {stats && (
          <Tabs defaultValue="overview" className="space-y-4">
            <TabsList>
              <TabsTrigger value="overview">Overview</TabsTrigger>
              <TabsTrigger value="api">API Performance</TabsTrigger>
              <TabsTrigger value="database">Database</TabsTrigger>
              <TabsTrigger value="server">Server</TabsTrigger>
              <TabsTrigger value="errors">Errors</TabsTrigger>
            </TabsList>

            <TabsContent value="overview" className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <Card>
                  <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">API Endpoints</CardTitle>
                    <Activity className="h-4 w-4 text-muted-foreground" />
                  </CardHeader>
                  <CardContent>
                    <div className="text-2xl font-bold">{stats.api_requests.total}</div>
                    <div className="flex items-center gap-2 mt-2">
                      <Badge className="bg-green-100 text-green-800">
                        {stats.api_requests.successful} healthy
                      </Badge>
                      <Badge className="bg-red-100 text-red-800">
                        {stats.api_requests.failed} down
                      </Badge>
                    </div>
                    <p className="text-xs text-muted-foreground mt-2">
                      Avg response: {stats.api_requests.avg_response_time.toFixed(2)}ms
                    </p>
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">Database</CardTitle>
                    <Database className="h-4 w-4 text-muted-foreground" />
                  </CardHeader>
                  <CardContent>
                    <div className="text-2xl font-bold">{stats.database.connections}</div>
                    <p className="text-xs text-muted-foreground mt-2">
                      Connections active
                    </p>
                    {stats.database.slow_queries > 0 ? (
                      <Badge className="bg-yellow-100 text-yellow-800 mt-2">
                        {stats.database.slow_queries} slow queries
                      </Badge>
                    ) : (
                      <p className="text-xs text-muted-foreground mt-2">Metrics not yet collected</p>
                    )}
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">Server</CardTitle>
                    <Server className="h-4 w-4 text-muted-foreground" />
                  </CardHeader>
                  <CardContent>
                    {stats.server.cpu_usage === 0 && stats.server.memory_usage === 0 ? (
                      <p className="text-xs text-muted-foreground">Metrics not yet collected</p>
                    ) : (
                    <div className="space-y-2">
                      <div>
                        <div className="flex justify-between text-sm">
                          <span>CPU</span>
                          <span>{stats.server.cpu_usage.toFixed(1)}%</span>
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-2 mt-1">
                          <div
                            className={`h-2 rounded-full ${
                              stats.server.cpu_usage > 80
                                ? "bg-red-500"
                                : stats.server.cpu_usage > 60
                                ? "bg-yellow-500"
                                : "bg-green-500"
                            }`}
                            style={{ width: `${Math.min(stats.server.cpu_usage, 100)}%` }}
                          />
                        </div>
                      </div>
                      <div>
                        <div className="flex justify-between text-sm">
                          <span>Memory</span>
                          <span>{stats.server.memory_usage.toFixed(1)}%</span>
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-2 mt-1">
                          <div
                            className={`h-2 rounded-full ${
                              stats.server.memory_usage > 80
                                ? "bg-red-500"
                                : stats.server.memory_usage > 60
                                ? "bg-yellow-500"
                                : "bg-green-500"
                            }`}
                            style={{ width: `${Math.min(stats.server.memory_usage, 100)}%` }}
                          />
                        </div>
                      </div>
                    </div>
                    )}
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">Errors</CardTitle>
                    <AlertTriangle className="h-4 w-4 text-muted-foreground" />
                  </CardHeader>
                  <CardContent>
                    <div className="text-2xl font-bold">{stats.errors.total}</div>
                    <p className="text-xs text-muted-foreground mt-2">
                      {stats.errors.rate.toFixed(2)} errors/hour
                    </p>
                    {stats.errors.total > 0 && (
                      <Badge className="bg-red-100 text-red-800 mt-2">
                        Action required
                      </Badge>
                    )}
                  </CardContent>
                </Card>
              </div>
            </TabsContent>

            <TabsContent value="api" className="space-y-4">
              <Card>
                <CardHeader>
                  <CardTitle>API Performance</CardTitle>
                  <p className="text-sm text-muted-foreground mt-1">Public endpoints monitored (24h)</p>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    <div className="flex justify-between items-center">
                      <span>Endpoints Monitored</span>
                      <span className="font-bold">{stats.api_requests.total}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span>Successful</span>
                      <Badge className="bg-green-100 text-green-800">
                        {stats.api_requests.successful}
                      </Badge>
                    </div>
                    <div className="flex justify-between items-center">
                      <span>Failed</span>
                      <Badge className="bg-red-100 text-red-800">
                        {stats.api_requests.failed}
                      </Badge>
                    </div>
                    <div className="flex justify-between items-center">
                      <span>Average Response Time</span>
                      <span className="font-bold">
                        {stats.api_requests.avg_response_time.toFixed(2)}ms
                      </span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span>Success Rate</span>
                      <span className="font-bold">
                        {stats.api_requests.total > 0
                          ? ((stats.api_requests.successful / stats.api_requests.total) * 100).toFixed(2)
                          : 0}%
                      </span>
                    </div>
                  </div>
                </CardContent>
              </Card>
              {metrics.length > 0 && (
                <Card>
                  <CardHeader>
                    <CardTitle>Endpoint breakdown</CardTitle>
                    <p className="text-sm text-muted-foreground mt-1">Per-endpoint status and avg response time (24h)</p>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-2">
                      {metrics.map((m) => (
                        <div
                          key={m.id}
                          className="flex items-center justify-between p-2 border rounded"
                        >
                          <div className="flex items-center gap-2 min-w-0">
                            {getStatusIcon(m.status)}
                            <span className="text-sm truncate">{m.metric_name}</span>
                          </div>
                          <div className="flex items-center gap-2 shrink-0">
                            <span className="text-sm text-muted-foreground">{m.value} ms</span>
                            <Badge className={getStatusColor(m.status)}>{m.status}</Badge>
                          </div>
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              )}
            </TabsContent>

            <TabsContent value="database" className="space-y-4">
              <Card>
                <CardHeader>
                  <CardTitle>Database Metrics</CardTitle>
                  <p className="text-sm text-muted-foreground mt-1">Connection and query metrics (when available)</p>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    {stats.database.connections === 0 && stats.database.query_time === 0 && stats.database.slow_queries === 0 ? (
                      <p className="text-sm text-muted-foreground">Database metrics are not yet collected. Configure monitoring to populate this tab.</p>
                    ) : (
                    <>
                    <div className="flex justify-between items-center">
                      <span>Active Connections</span>
                      <span className="font-bold">{stats.database.connections}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span>Average Query Time</span>
                      <span className="font-bold">{stats.database.query_time.toFixed(2)}ms</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span>Slow Queries</span>
                      <Badge
                        className={
                          stats.database.slow_queries > 0
                            ? "bg-yellow-100 text-yellow-800"
                            : "bg-green-100 text-green-800"
                        }
                      >
                        {stats.database.slow_queries}
                      </Badge>
                    </div>
                    </>
                    )}
                  </div>
                </CardContent>
              </Card>
            </TabsContent>

            <TabsContent value="server" className="space-y-4">
              <Card>
                <CardHeader>
                  <CardTitle>Server Resources</CardTitle>
                  <p className="text-sm text-muted-foreground mt-1">CPU, memory, disk (when available)</p>
                </CardHeader>
                <CardContent>
                  {stats.server.cpu_usage === 0 && stats.server.memory_usage === 0 && stats.server.disk_usage === 0 ? (
                    <p className="text-sm text-muted-foreground">Server metrics are not yet collected. Configure monitoring to populate this tab.</p>
                  ) : (
                  <div className="space-y-4">
                    <div>
                      <div className="flex justify-between text-sm mb-2">
                        <span>CPU Usage</span>
                        <span className="font-bold">{stats.server.cpu_usage.toFixed(1)}%</span>
                      </div>
                      <div className="w-full bg-gray-200 rounded-full h-3">
                        <div
                          className={`h-3 rounded-full ${
                            stats.server.cpu_usage > 80
                              ? "bg-red-500"
                              : stats.server.cpu_usage > 60
                              ? "bg-yellow-500"
                              : "bg-green-500"
                          }`}
                          style={{ width: `${Math.min(stats.server.cpu_usage, 100)}%` }}
                        />
                      </div>
                    </div>
                    <div>
                      <div className="flex justify-between text-sm mb-2">
                        <span>Memory Usage</span>
                        <span className="font-bold">{stats.server.memory_usage.toFixed(1)}%</span>
                      </div>
                      <div className="w-full bg-gray-200 rounded-full h-3">
                        <div
                          className={`h-3 rounded-full ${
                            stats.server.memory_usage > 80
                              ? "bg-red-500"
                              : stats.server.memory_usage > 60
                              ? "bg-yellow-500"
                              : "bg-green-500"
                          }`}
                          style={{ width: `${Math.min(stats.server.memory_usage, 100)}%` }}
                        />
                      </div>
                    </div>
                    <div>
                      <div className="flex justify-between text-sm mb-2">
                        <span>Disk Usage</span>
                        <span className="font-bold">{stats.server.disk_usage.toFixed(1)}%</span>
                      </div>
                      <div className="w-full bg-gray-200 rounded-full h-3">
                        <div
                          className={`h-3 rounded-full ${
                            stats.server.disk_usage > 80
                              ? "bg-red-500"
                              : stats.server.disk_usage > 60
                              ? "bg-yellow-500"
                              : "bg-green-500"
                          }`}
                          style={{ width: `${Math.min(stats.server.disk_usage, 100)}%` }}
                        />
                      </div>
                    </div>
                  </div>
                  )}
                </CardContent>
              </Card>
            </TabsContent>

            <TabsContent value="errors" className="space-y-4">
              <Card>
                <CardHeader>
                  <CardTitle>Error Tracking</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    <div className="flex justify-between items-center">
                      <span>Total Errors (24h)</span>
                      <Badge
                        className={
                          stats.errors.total > 0
                            ? "bg-red-100 text-red-800"
                            : "bg-green-100 text-green-800"
                        }
                      >
                        {stats.errors.total}
                      </Badge>
                    </div>
                    <div className="flex justify-between items-center">
                      <span>Error Rate</span>
                      <span className="font-bold">{stats.errors.rate.toFixed(2)} errors/hour</span>
                    </div>
                    {stats.errors.total > 0 && (
                      <div className="mt-4 p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
                        <p className="text-sm text-yellow-800">
                          ΓÜá∩╕Å There are errors in the system. Please review the error logs.
                        </p>
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>

              {(recentErrorLogs.length > 0) && (
                <Card>
                  <CardHeader>
                    <CardTitle>Recent Errors</CardTitle>
                    <p className="text-sm text-muted-foreground mt-1">From error_logs (24h)</p>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-2">
                      {recentErrorLogs.slice(0, 15).map((log, idx) => (
                        <div
                          key={(log as { id?: string }).id ?? idx}
                          className="flex items-center justify-between p-2 border rounded text-left"
                        >
                          <div className="flex flex-col gap-0.5 min-w-0">
                            <span className="text-sm font-medium truncate">
                              {log.error_type ?? "Error"} {log.endpoint ? `ΓÇö ${log.endpoint}` : ""}
                            </span>
                            <span className="text-xs text-muted-foreground truncate" title={log.error_message}>
                              {log.error_message}
                            </span>
                            {log.created_at && (
                              <span className="text-xs text-muted-foreground">
                                {new Date(log.created_at).toLocaleString()}
                              </span>
                            )}
                          </div>
                          <Badge className={getStatusColor(log.severity ?? "unknown")}>
                            {log.severity ?? "ΓÇö"}
                          </Badge>
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              )}
            </TabsContent>
          </Tabs>
        )}
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Plus, Edit } from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

interface TaxRate {
  id: string;
  code: string;
  name: string;
  description: string;
  display_order: number;
  metadata: {
    rate: number;
    included: boolean;
  };
}

interface ProviderTaxRate {
  provider_id: string;
  provider_name: string;
  tax_rate_percent: number;
}

interface TaxStatistics {
  total_tax_collected: number;
  total_revenue: number;
  tax_percentage: number;
  total_bookings: number;
}

export default function AdminTaxes() {
  const [taxRates, setTaxRates] = useState<TaxRate[]>([]);
  const [_providerTaxRates, setProviderTaxRates] = useState<ProviderTaxRate[]>([]);
  void _providerTaxRates;
  const [statistics, setStatistics] = useState<TaxStatistics | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingRate, setEditingRate] = useState<TaxRate | null>(null);
  const [formData, setFormData] = useState({
    code: "",
    name: "",
    description: "",
    rate: 0,
    included: false,
    display_order: 999,
  });

  useEffect(() => {
    loadTaxData();
  }, []);

  const loadTaxData = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetcher.get<{
        tax_rates: TaxRate[];
        provider_tax_rate: ProviderTaxRate | null;
        statistics: TaxStatistics;
      }>("/api/admin/taxes");

      setTaxRates(response.tax_rates || []);
      if (response.provider_tax_rate) {
        setProviderTaxRates([response.provider_tax_rate]);
      }
      setStatistics(response.statistics);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load tax data";
      setError(errorMessage);
      console.error("Error loading tax data:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreate = () => {
    setEditingRate(null);
    setFormData({
      code: "",
      name: "",
      description: "",
      rate: 0,
      included: false,
      display_order: 999,
    });
    setIsDialogOpen(true);
  };

  const handleEdit = (rate: TaxRate) => {
    setEditingRate(rate);
    setFormData({
      code: rate.code,
      name: rate.name,
      description: rate.description,
      rate: rate.metadata.rate,
      included: rate.metadata.included,
      display_order: rate.display_order,
    });
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    try {
      if (editingRate) {
        // Update existing rate
        await fetcher.patch(`/api/admin/taxes/${editingRate.id}`, formData);
        toast.success("Tax rate updated");
      } else {
        // Create new rate
        await fetcher.post("/api/admin/taxes", formData);
        toast.success("Tax rate created");
      }
      setIsDialogOpen(false);
      loadTaxData();
    } catch (error: any) {
      toast.error(error.message || "Failed to save tax rate");
    }
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading tax data..." />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="mb-6">
          <h1 className="text-3xl font-semibold mb-2">Tax Management</h1>
          <p className="text-gray-600">Manage the platform tax rate catalog and view platform-wide statistics.</p>
          <p className="text-sm text-amber-700 mt-2">
            <strong>Providers control their own tax:</strong> Each provider sets their tax (e.g. VAT) under <em>Provider ΓåÆ Settings ΓåÆ Sales ΓåÆ Taxes</em>. Here you manage the <em>catalog</em> of available rates (reference_data) and can override a specific providerΓÇÖs rate if needed. Platform stats below are for reporting only.
          </p>
        </div>

        {/* Statistics */}
        {statistics && (
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
            <div className="bg-white border rounded-lg p-4">
              <p className="text-sm text-gray-600 mb-1">Total Tax Collected</p>
              <p className="text-2xl font-semibold">
                ZAR {statistics.total_tax_collected.toLocaleString(undefined, {
                  minimumFractionDigits: 2,
                  maximumFractionDigits: 2,
                })}
              </p>
            </div>
            <div className="bg-white border rounded-lg p-4">
              <p className="text-sm text-gray-600 mb-1">Total Revenue</p>
              <p className="text-2xl font-semibold">
                ZAR {statistics.total_revenue.toLocaleString(undefined, {
                  minimumFractionDigits: 2,
                  maximumFractionDigits: 2,
                })}
              </p>
            </div>
            <div className="bg-white border rounded-lg p-4">
              <p className="text-sm text-gray-600 mb-1">Tax Percentage</p>
              <p className="text-2xl font-semibold">
                {statistics.tax_percentage.toFixed(2)}%
              </p>
            </div>
            <div className="bg-white border rounded-lg p-4">
              <p className="text-sm text-gray-600 mb-1">Completed Bookings</p>
              <p className="text-2xl font-semibold">{statistics.total_bookings}</p>
            </div>
          </div>
        )}

        {/* Tax Rates */}
        <div className="bg-white border rounded-lg p-6 mb-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-semibold">Tax Rates</h2>
            <Button onClick={handleCreate} className="bg-[#FF0077] hover:bg-[#E6006A]">
              <Plus className="w-4 h-4 mr-2" />
              Add Tax Rate
            </Button>
          </div>

          {error ? (
            <EmptyState
              title="Failed to load tax rates"
              description={error}
              action={{ label: "Retry", onClick: loadTaxData }}
            />
          ) : taxRates.length === 0 ? (
            <EmptyState
              title="No tax rates found"
              description="Create your first tax rate to get started"
            />
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Code</TableHead>
                  <TableHead>Name</TableHead>
                  <TableHead>Rate</TableHead>
                  <TableHead>Type</TableHead>
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {taxRates.map((rate) => (
                  <TableRow key={rate.id}>
                    <TableCell className="font-medium">{rate.code}</TableCell>
                    <TableCell>{rate.name}</TableCell>
                    <TableCell>{rate.metadata.rate}%</TableCell>
                    <TableCell>
                      <Badge variant={rate.metadata.included ? "default" : "outline"}>
                        {rate.metadata.included ? "Included" : "Excluded"}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleEdit(rate)}
                      >
                        <Edit className="w-4 h-4" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </div>

        {/* Create/Edit Dialog */}
        <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
          <DialogContent className="max-w-md">
            <DialogHeader>
              <DialogTitle>
                {editingRate ? "Edit Tax Rate" : "Create Tax Rate"}
              </DialogTitle>
            </DialogHeader>

            <div className="space-y-4">
              <div>
                <Label htmlFor="code">Code *</Label>
                <Input
                  id="code"
                  value={formData.code}
                  onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                  placeholder="e.g., 15"
                />
              </div>

              <div>
                <Label htmlFor="name">Name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="e.g., Standard Tax (15%)"
                />
              </div>

              <div>
                <Label htmlFor="description">Description</Label>
                <Input
                  id="description"
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  placeholder="e.g., South African VAT"
                />
              </div>

              <div>
                <Label htmlFor="rate">Rate (%) *</Label>
                <Input
                  id="rate"
                  type="number"
                  min="0"
                  max="100"
                  step="0.01"
                  value={formData.rate}
                  onChange={(e) => setFormData({ ...formData, rate: parseFloat(e.target.value) || 0 })}
                />
              </div>

              <div className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  id="included"
                  checked={formData.included}
                  onChange={(e) => setFormData({ ...formData, included: e.target.checked })}
                  className="w-4 h-4"
                />
                <Label htmlFor="included">Tax included in price</Label>
              </div>
            </div>

            <DialogFooter>
              <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
                Cancel
              </Button>
              <Button onClick={handleSave} className="bg-[#FF0077] hover:bg-[#E6006A]">
                {editingRate ? "Update" : "Create"}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { motion } from "framer-motion";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  User,
  Mail,
  Phone,
  Shield,
  Calendar,
  DollarSign,
  ArrowLeft,
  Edit,
  Ban,
  CheckCircle,
  XCircle,
} from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { format } from "date-fns";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

interface UserDetail {
  id: string;
  email: string;
  full_name: string | null;
  phone: string | null;
  avatar_url: string | null;
  role: string;
  created_at: string;
  deactivated_at?: string | null;
  deactivation_reason?: string | null;
  stats?: {
    total_bookings: number;
    total_spent: number;
    last_booking_date: string | null;
  };
}

export default function UserDetailPage() {
  const params = useParams();
  const router = useRouter();
  const userId = params.id as string;

  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [user, setUser] = useState<UserDetail | null>(null);

  useEffect(() => {
    if (userId) {
      loadUser();
    }
  }, [userId]); // eslint-disable-line react-hooks/exhaustive-deps -- load when userId changes

  const loadUser = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetcher.get<{ data: UserDetail }>(`/api/admin/users/${userId}`);
      setUser(response.data);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load user";
      setError(errorMessage);
      toast.error(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeactivate = async () => {
    if (!confirm("Are you sure you want to deactivate this user?")) {
      return;
    }

    try {
      await fetcher.patch(`/api/admin/users/${userId}`, {
        deactivated_at: new Date().toISOString(),
        deactivation_reason: "Deactivated by admin",
      });
      toast.success("User deactivated successfully");
      loadUser();
    } catch (err: any) {
      toast.error(err.message || "Failed to deactivate user");
    }
  };

  const handleReactivate = async () => {
    try {
      await fetcher.patch(`/api/admin/users/${userId}`, {
        deactivated_at: null,
        deactivation_reason: null,
      });
      toast.success("User reactivated successfully");
      loadUser();
    } catch (err: any) {
      toast.error(err.message || "Failed to reactivate user");
    }
  };

  if (isLoading) {
    return (
      <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
        <div className="container mx-auto px-4 py-8">
          <LoadingTimeout loadingMessage="Loading user details..." />
        </div>
      </RoleGuard>
    );
  }

  if (error || !user) {
    return (
      <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
        <div className="container mx-auto px-4 py-8">
          <EmptyState
            title="Failed to load user"
            description={error || "Unable to load user details"}
            action={{
              label: "Back to Users",
              onClick: () => router.push("/admin/users"),
            }}
          />
        </div>
      </RoleGuard>
    );
  }

  const isDeactivated = !!user.deactivated_at;

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="min-h-screen bg-zinc-50/50">
        <div className="w-full max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-6 lg:py-8">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="space-y-6"
          >
            {/* Header */}
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => router.push("/admin/users")}
                >
                  <ArrowLeft className="w-4 h-4" />
                </Button>
                <div>
                  <h1 className="text-3xl font-semibold text-gray-900">
                    {user.full_name || "User"}
                  </h1>
                  <p className="text-gray-600 mt-1">{user.email}</p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <Badge
                  variant={isDeactivated ? "destructive" : "default"}
                  className="text-sm"
                >
                  {isDeactivated ? "Deactivated" : "Active"}
                </Badge>
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button variant="outline">
                      <Edit className="w-4 h-4 mr-2" />
                      Actions
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent>
                    {isDeactivated ? (
                      <DropdownMenuItem onClick={handleReactivate}>
                        <CheckCircle className="w-4 h-4 mr-2" />
                        Reactivate User
                      </DropdownMenuItem>
                    ) : (
                      <DropdownMenuItem onClick={handleDeactivate}>
                        <Ban className="w-4 h-4 mr-2" />
                        Deactivate User
                      </DropdownMenuItem>
                    )}
                  </DropdownMenuContent>
                </DropdownMenu>
              </div>
            </div>

            {/* User Info */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <Card>
                <CardHeader>
                  <CardTitle>User Information</CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex items-center gap-3">
                    <User className="w-5 h-5 text-gray-400" />
                    <div>
                      <p className="text-sm text-gray-500">Full Name</p>
                      <p className="font-medium">{user.full_name || "Not provided"}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <Mail className="w-5 h-5 text-gray-400" />
                    <div>
                      <p className="text-sm text-gray-500">Email</p>
                      <p className="font-medium">{user.email}</p>
                    </div>
                  </div>
                  {user.phone && (
                    <div className="flex items-center gap-3">
                      <Phone className="w-5 h-5 text-gray-400" />
                      <div>
                        <p className="text-sm text-gray-500">Phone</p>
                        <p className="font-medium">{user.phone}</p>
                      </div>
                    </div>
                  )}
                  <div className="flex items-center gap-3">
                    <Shield className="w-5 h-5 text-gray-400" />
                    <div>
                      <p className="text-sm text-gray-500">Role</p>
                      <Badge className="mt-1">{user.role}</Badge>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <Calendar className="w-5 h-5 text-gray-400" />
                    <div>
                      <p className="text-sm text-gray-500">Member Since</p>
                      <p className="font-medium">
                        {format(new Date(user.created_at), "PP")}
                      </p>
                    </div>
                  </div>
                  {isDeactivated && (
                    <div className="flex items-center gap-3">
                      <XCircle className="w-5 h-5 text-red-400" />
                      <div>
                        <p className="text-sm text-gray-500">Deactivated</p>
                        <p className="font-medium text-red-600">
                          {user.deactivated_at
                            ? format(new Date(user.deactivated_at), "PP")
                            : "N/A"}
                        </p>
                        {user.deactivation_reason && (
                          <p className="text-sm text-gray-500 mt-1">
                            {user.deactivation_reason}
                          </p>
                        )}
                      </div>
                    </div>
                  )}
                </CardContent>
              </Card>

              {/* Stats */}
              {user.stats && (
                <Card>
                  <CardHeader>
                    <CardTitle>Activity Statistics</CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="flex items-center gap-3">
                      <Calendar className="w-5 h-5 text-gray-400" />
                      <div>
                        <p className="text-sm text-gray-500">Total Bookings</p>
                        <p className="font-medium text-2xl">{user.stats.total_bookings || 0}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <DollarSign className="w-5 h-5 text-gray-400" />
                      <div>
                        <p className="text-sm text-gray-500">Total Spent</p>
                        <p className="font-medium text-2xl">
                          R {(user.stats.total_spent || 0).toLocaleString()}
                        </p>
                      </div>
                    </div>
                    {user.stats.last_booking_date && (
                      <div className="flex items-center gap-3">
                        <Calendar className="w-5 h-5 text-gray-400" />
                        <div>
                          <p className="text-sm text-gray-500">Last Booking</p>
                          <p className="font-medium">
                            {format(new Date(user.stats.last_booking_date), "PP")}
                          </p>
                        </div>
                      </div>
                    )}
                  </CardContent>
                </Card>
              )}
            </div>
          </motion.div>
        </div>
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  User,
  Mail,
  Phone,
  Shield,
  Calendar,
  CreditCard,
  Key,
  Eye,
  EyeOff,
  RefreshCw,
  Download,
  Ban,
  Trash2,
  CheckCircle,
} from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import type { UserRole } from "@/types/beautonomi";

interface UserData {
  id: string;
  email: string;
  full_name: string | null;
  phone: string | null;
  avatar_url: string | null;
  role: UserRole;
  created_at: string;
  updated_at?: string;
  last_login?: string;
  is_active?: boolean;
  deactivated_at?: string | null;
  deactivation_reason?: string | null;
  stats?: {
    booking_count?: number;
    provider_count?: number;
    total_spent?: number;
  };
}

interface Booking {
  id: string;
  status: string;
  service_name: string;
  provider_name: string;
  scheduled_at: string;
  total_amount: number;
  created_at: string;
}

interface UserDetailModalProps {
  user: UserData | null;
  open: boolean;
  onClose: () => void;
  onUpdate: () => void;
}

export default function UserDetailModal({
  user,
  open,
  onClose,
  onUpdate,
}: UserDetailModalProps) {
  const [activeTab, setActiveTab] = useState("overview");
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [isLoadingBookings, setIsLoadingBookings] = useState(false);
  const [showPasswordForm, setShowPasswordForm] = useState(false);
  const [passwordData, setPasswordData] = useState({
    newPassword: "",
    confirmPassword: "",
  });
  const [isResettingPassword, setIsResettingPassword] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [isSuspending, setIsSuspending] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
   
  const [, _setSuspensionReason] = useState("");

  const [fullUserData, setFullUserData] = useState<UserData | null>(null);

  useEffect(() => {
    if (open && user) {
      loadFullUserData();
      if (activeTab === "bookings") {
        loadBookings();
      }
    }
  }, [open, user, activeTab]); // eslint-disable-line react-hooks/exhaustive-deps -- load when modal opens or tab changes

  const loadFullUserData = async () => {
    if (!user) return;
    try {
      const response = await fetcher.get<{
        data: UserData;
        error: null;
      }>(`/api/admin/users/${user.id}`);
      setFullUserData(response.data);
    } catch (error) {
      console.error("Error loading user data:", error);
      setFullUserData(user); // Fallback to passed user data
    }
  };

  const loadBookings = async () => {
    if (!user) return;
    try {
      setIsLoadingBookings(true);
      const response = await fetcher.get<{
        data: Booking[];
        error: null;
      }>(`/api/admin/users/${user.id}/bookings`);
      setBookings(response.data || []);
    } catch (error) {
      console.error("Error loading bookings:", error);
      toast.error("Failed to load bookings");
    } finally {
      setIsLoadingBookings(false);
    }
  };

  const handlePasswordReset = async () => {
    if (!displayUser) return;
    if (!passwordData.newPassword || passwordData.newPassword.length < 8) {
      toast.error("Password must be at least 8 characters");
      return;
    }
    if (passwordData.newPassword !== passwordData.confirmPassword) {
      toast.error("Passwords do not match");
      return;
    }

    try {
      setIsResettingPassword(true);
      await fetcher.put(`/api/admin/users/${displayUser.id}/password`, {
        new_password: passwordData.newPassword,
      });
      toast.success("Password reset successfully");
      setShowPasswordForm(false);
      setPasswordData({ newPassword: "", confirmPassword: "" });
    } catch (error: any) {
      toast.error(error.message || "Failed to reset password");
    } finally {
      setIsResettingPassword(false);
    }
  };

  const handleImpersonate = async () => {
    if (!displayUser) return;
    if (
      !confirm(
        `Are you sure you want to impersonate ${displayUser.full_name || displayUser.email}? You will be logged in as this user.`
      )
    ) {
      return;
    }

    try {
      const response = await fetcher.post<{ data: { success: boolean; url: string }; error: null }>(
        `/api/admin/users/${displayUser.id}/impersonate`,
        undefined,
        { timeoutMs: 30000 } // 30 seconds timeout for impersonation
      );
      if (response.data?.url) {
        window.location.href = response.data.url;
      } else {
        toast.success("Impersonation started. Redirecting...");
        setTimeout(() => {
          window.location.reload();
        }, 1000);
      }
    } catch (error: any) {
      toast.error(error.message || "Failed to impersonate user");
    }
  };

  const handleSuspend = async () => {
    if (!displayUser) return;
    
    const reason = prompt(
      `Enter reason for suspending ${displayUser.full_name || displayUser.email} (optional):`
    );
    
    if (reason === null) return; // User cancelled

    if (
      !confirm(
        `Are you sure you want to suspend ${displayUser.full_name || displayUser.email}? They will not be able to access their account.`
      )
    ) {
      return;
    }

    try {
      setIsSuspending(true);
      await fetcher.patch(`/api/admin/users/${displayUser.id}`, {
        deactivated_at: new Date().toISOString(),
        deactivation_reason: reason || null,
      });
      toast.success("User suspended successfully");
      loadFullUserData();
      onUpdate();
    } catch (error: any) {
      toast.error(error.message || "Failed to suspend user");
    } finally {
      setIsSuspending(false);
    }
  };

  const handleReactivate = async () => {
    if (!displayUser) return;
    
    if (
      !confirm(
        `Are you sure you want to reactivate ${displayUser.full_name || displayUser.email}? They will be able to access their account again.`
      )
    ) {
      return;
    }

    try {
      setIsSuspending(true);
      await fetcher.patch(`/api/admin/users/${displayUser.id}`, {
        deactivated_at: null,
        deactivation_reason: null,
      });
      toast.success("User reactivated successfully");
      loadFullUserData();
      onUpdate();
    } catch (error: any) {
      toast.error(error.message || "Failed to reactivate user");
    } finally {
      setIsSuspending(false);
    }
  };

  const handleDelete = async () => {
    if (!displayUser) return;
    
    const confirmMessage = `WARNING: This will permanently delete ${displayUser.full_name || displayUser.email} and all their data. This action cannot be undone.\n\nType "DELETE" to confirm:`;
    const confirmation = prompt(confirmMessage);
    
    if (confirmation !== "DELETE") {
      toast.info("Deletion cancelled");
      return;
    }

    if (
      !confirm(
        `Final confirmation: Are you absolutely sure you want to permanently delete ${displayUser.full_name || displayUser.email}? This cannot be undone!`
      )
    ) {
      return;
    }

    try {
      setIsDeleting(true);
      await fetcher.delete(`/api/admin/users/${displayUser.id}`);
      toast.success("User deleted successfully");
      onClose();
      onUpdate();
    } catch (error: any) {
      toast.error(error.message || "Failed to delete user");
    } finally {
      setIsDeleting(false);
    }
  };

  const getRoleBadgeColor = (role: UserRole) => {
    switch (role) {
      case "superadmin":
        return "bg-red-100 text-red-800";
      case "provider_owner":
        return "bg-blue-100 text-blue-800";
      case "provider_staff":
        return "bg-purple-100 text-purple-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleString();
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-ZA", {
      style: "currency",
      currency: "ZAR",
    }).format(amount);
  };

  const displayUser = fullUserData || user;
  if (!displayUser) return null;

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-3">
            <div className="h-12 w-12 rounded-full bg-gray-200 flex items-center justify-center">
              {displayUser.avatar_url ? (
                <img
                  src={displayUser.avatar_url}
                  alt={displayUser.full_name || displayUser.email}
                  className="h-12 w-12 rounded-full"
                />
              ) : (
                <User className="w-6 h-6 text-gray-500" />
              )}
            </div>
            <div>
              <div className="text-xl font-semibold">
                {displayUser.full_name || "No name"}
              </div>
              <div className="text-sm text-gray-500 font-normal">{displayUser.email}</div>
            </div>
          </DialogTitle>
          <DialogDescription>
            User ID: {displayUser.id}
          </DialogDescription>
        </DialogHeader>

        <Tabs value={activeTab} onValueChange={setActiveTab} className="mt-4">
          <TabsList className="grid w-full grid-cols-4">
            <TabsTrigger value="overview">Overview</TabsTrigger>
            <TabsTrigger value="bookings">Bookings</TabsTrigger>
            <TabsTrigger value="security">Security</TabsTrigger>
            <TabsTrigger value="actions">Actions</TabsTrigger>
          </TabsList>

          <TabsContent value="overview" className="space-y-4 mt-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-3">
                <div className="flex items-center gap-2 text-sm">
                  <Mail className="w-4 h-4 text-gray-500" />
                  <span className="text-gray-500">Email:</span>
                  <span className="font-medium">{displayUser.email}</span>
                </div>
                {displayUser.phone && (
                  <div className="flex items-center gap-2 text-sm">
                    <Phone className="w-4 h-4 text-gray-500" />
                    <span className="text-gray-500">Phone:</span>
                    <span className="font-medium">{displayUser.phone}</span>
                  </div>
                )}
                <div className="flex items-center gap-2 text-sm">
                  <Shield className="w-4 h-4 text-gray-500" />
                  <span className="text-gray-500">Role:</span>
                  <Badge className={getRoleBadgeColor(displayUser.role)}>
                    {displayUser.role}
                  </Badge>
                </div>
                <div className="flex items-center gap-2 text-sm">
                  <Calendar className="w-4 h-4 text-gray-500" />
                  <span className="text-gray-500">Created:</span>
                  <span className="font-medium">{formatDate(displayUser.created_at)}</span>
                </div>
                {displayUser.last_login && (
                  <div className="flex items-center gap-2 text-sm">
                    <Calendar className="w-4 h-4 text-gray-500" />
                    <span className="text-gray-500">Last Login:</span>
                    <span className="font-medium">{formatDate(displayUser.last_login)}</span>
                  </div>
                )}
                {displayUser.deactivated_at && (
                  <div className="flex items-center gap-2 text-sm">
                    <Ban className="w-4 h-4 text-red-500" />
                    <span className="text-red-500 font-semibold">Suspended</span>
                    <span className="text-gray-500">({formatDate(displayUser.deactivated_at)})</span>
                  </div>
                )}
                {displayUser.deactivation_reason && (
                  <div className="flex items-center gap-2 text-sm">
                    <span className="text-gray-500">Reason:</span>
                    <span className="font-medium text-red-600">{displayUser.deactivation_reason}</span>
                  </div>
                )}
              </div>
              <div className="space-y-3">
                {displayUser.stats && (
                  <>
                    {displayUser.stats.booking_count !== undefined && (
                      <div className="flex items-center gap-2 text-sm">
                        <CreditCard className="w-4 h-4 text-gray-500" />
                        <span className="text-gray-500">Total Bookings:</span>
                        <span className="font-medium">{displayUser.stats.booking_count}</span>
                      </div>
                    )}
                    {displayUser.stats.provider_count !== undefined && (
                      <div className="flex items-center gap-2 text-sm">
                        <User className="w-4 h-4 text-gray-500" />
                        <span className="text-gray-500">Providers:</span>
                        <span className="font-medium">{displayUser.stats.provider_count}</span>
                      </div>
                    )}
                    {displayUser.stats.total_spent !== undefined && (
                      <div className="flex items-center gap-2 text-sm">
                        <CreditCard className="w-4 h-4 text-gray-500" />
                        <span className="text-gray-500">Total Spent:</span>
                        <span className="font-medium">
                          {formatCurrency(displayUser.stats.total_spent)}
                        </span>
                      </div>
                    )}
                  </>
                )}
              </div>
            </div>
          </TabsContent>

          <TabsContent value="bookings" className="mt-4">
            {isLoadingBookings ? (
              <div className="text-center py-8">
                <RefreshCw className="w-6 h-6 animate-spin mx-auto text-gray-400" />
                <p className="mt-2 text-sm text-gray-500">Loading bookings...</p>
              </div>
            ) : bookings.length === 0 ? (
              <div className="text-center py-8">
                <p className="text-gray-500">No bookings found</p>
              </div>
            ) : (
              <div className="space-y-3">
                {bookings.map((booking) => (
                  <div
                    key={booking.id}
                    className="border rounded-lg p-4 hover:bg-gray-50 transition-colors"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="font-semibold text-sm">{booking.service_name}</div>
                        <div className="text-xs text-gray-500 mt-1">
                          Provider: {booking.provider_name}
                        </div>
                        <div className="text-xs text-gray-500">
                          Scheduled: {formatDate(booking.scheduled_at)}
                        </div>
                        <div className="text-xs text-gray-500">
                          Amount: {formatCurrency(booking.total_amount)}
                        </div>
                      </div>
                      <Badge
                        className={`ml-2 ${
                          booking.status === "completed"
                            ? "bg-green-100 text-green-800"
                            : booking.status === "cancelled"
                            ? "bg-red-100 text-red-800"
                            : "bg-yellow-100 text-yellow-800"
                        }`}
                      >
                        {booking.status}
                      </Badge>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </TabsContent>

          <TabsContent value="security" className="mt-4 space-y-4">
            <div className="space-y-4">
              <div>
                <h3 className="font-semibold mb-2">Reset Password</h3>
                {!showPasswordForm ? (
                  <Button
                    variant="outline"
                    onClick={() => setShowPasswordForm(true)}
                    className="w-full sm:w-auto"
                  >
                    <Key className="w-4 h-4 mr-2" />
                    Reset Password
                  </Button>
                ) : (
                  <div className="space-y-3 border rounded-lg p-4">
                    <div>
                      <label className="text-sm font-medium mb-1 block">
                        New Password
                      </label>
                      <div className="relative">
                        <Input
                          type={showPassword ? "text" : "password"}
                          value={passwordData.newPassword}
                          onChange={(e) =>
                            setPasswordData({
                              ...passwordData,
                              newPassword: e.target.value,
                            })
                          }
                          placeholder="Enter new password (min 8 characters)"
                          className="pr-10"
                        />
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          onClick={() => setShowPassword(!showPassword)}
                          className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 h-8 w-8"
                        >
                          {showPassword ? (
                            <EyeOff className="w-4 h-4" />
                          ) : (
                            <Eye className="w-4 h-4" />
                          )}
                        </Button>
                      </div>
                    </div>
                    <div>
                      <label className="text-sm font-medium mb-1 block">
                        Confirm Password
                      </label>
                      <Input
                        type={showPassword ? "text" : "password"}
                        value={passwordData.confirmPassword}
                        onChange={(e) =>
                          setPasswordData({
                            ...passwordData,
                            confirmPassword: e.target.value,
                          })
                        }
                        placeholder="Confirm new password"
                      />
                    </div>
                    <div className="flex gap-2">
                      <Button
                        onClick={handlePasswordReset}
                        disabled={isResettingPassword}
                        className="flex-1"
                      >
                        {isResettingPassword ? (
                          <>
                            <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                            Resetting...
                          </>
                        ) : (
                          <>
                            <Key className="w-4 h-4 mr-2" />
                            Reset Password
                          </>
                        )}
                      </Button>
                      <Button
                        variant="outline"
                        onClick={() => {
                          setShowPasswordForm(false);
                          setPasswordData({ newPassword: "", confirmPassword: "" });
                        }}
                      >
                        Cancel
                      </Button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </TabsContent>

          <TabsContent value="actions" className="mt-4 space-y-4">
            <div className="space-y-4">
              <div>
                <h3 className="font-semibold mb-2">User Actions</h3>
                <div className="space-y-2">
                  <Button
                    variant="outline"
                    onClick={handleImpersonate}
                    className="w-full sm:w-auto"
                  >
                    <Eye className="w-4 h-4 mr-2" />
                    Impersonate User
                  </Button>
                  <Button
                    variant="outline"
                    onClick={async () => {
                      try {
                      const response = await fetch(
                        `/api/admin/users/${displayUser.id}/export`
                      );
                        if (!response.ok) throw new Error("Export failed");
                        const blob = await response.blob();
                        const url = window.URL.createObjectURL(blob);
                        const a = document.createElement("a");
                        a.href = url;
                        a.download = `user-${displayUser.id}-export-${new Date().toISOString().split("T")[0]}.csv`;
                        document.body.appendChild(a);
                        a.click();
                        window.URL.revokeObjectURL(url);
                        document.body.removeChild(a);
                        toast.success("User data exported");
                      } catch {
                        toast.error("Failed to export user data");
                      }
                    }}
                    className="w-full sm:w-auto ml-0 sm:ml-2"
                  >
                    <Download className="w-4 h-4 mr-2" />
                    Export User Data
                  </Button>
                </div>
              </div>

              <div className="border-t pt-4">
                <h3 className="font-semibold mb-2">Account Status</h3>
                <div className="space-y-2">
                  {displayUser.deactivated_at ? (
                    <Button
                      variant="outline"
                      onClick={handleReactivate}
                      disabled={isSuspending}
                      className="w-full sm:w-auto bg-green-50 hover:bg-green-100 text-green-700 border-green-300"
                    >
                      {isSuspending ? (
                        <>
                          <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                          Reactivating...
                        </>
                      ) : (
                        <>
                          <CheckCircle className="w-4 h-4 mr-2" />
                          Reactivate User
                        </>
                      )}
                    </Button>
                  ) : (
                    <Button
                      variant="outline"
                      onClick={handleSuspend}
                      disabled={isSuspending || displayUser.role === "superadmin"}
                      className="w-full sm:w-auto bg-yellow-50 hover:bg-yellow-100 text-yellow-700 border-yellow-300"
                    >
                      {isSuspending ? (
                        <>
                          <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                          Suspending...
                        </>
                      ) : (
                        <>
                          <Ban className="w-4 h-4 mr-2" />
                          Suspend User
                        </>
                      )}
                    </Button>
                  )}
                  {displayUser.role === "superadmin" && (
                    <p className="text-xs text-gray-500 mt-1">
                      Superadmin accounts cannot be suspended
                    </p>
                  )}
                </div>
              </div>

              <div className="border-t pt-4">
                <h3 className="font-semibold mb-2 text-red-600">Danger Zone</h3>
                <div className="space-y-2">
                  <Button
                    variant="destructive"
                    onClick={handleDelete}
                    disabled={isDeleting || displayUser.role === "superadmin"}
                    className="w-full sm:w-auto"
                  >
                    {isDeleting ? (
                      <>
                        <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                        Deleting...
                      </>
                    ) : (
                      <>
                        <Trash2 className="w-4 h-4 mr-2" />
                        Delete User Permanently
                      </>
                    )}
                  </Button>
                  {displayUser.role === "superadmin" && (
                    <p className="text-xs text-gray-500 mt-1">
                      Superadmin accounts cannot be deleted
                    </p>
                  )}
                  <p className="text-xs text-red-600 mt-1">
                    This action cannot be undone. All user data will be permanently deleted.
                  </p>
                </div>
              </div>
            </div>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Search,
  User,
  ChevronDown,
  Edit,
  Download,
  Ban,
  Trash2,
  CheckCircle,
} from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import type { UserRole } from "@/types/beautonomi";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import UserDetailModal from "./components/UserDetailModal";
import Link from "next/link";
import BulkActionsBar from "@/components/admin/BulkActionsBar";
import { Checkbox } from "@/components/ui/checkbox";

interface UserData {
  id: string;
  email: string;
  full_name: string | null;
  phone: string | null;
  avatar_url: string | null;
  role: UserRole;
  created_at: string;
  deactivated_at?: string | null;
  deactivation_reason?: string | null;
  stats?: {
    booking_count?: number;
    provider_count?: number;
  };
}

export default function AdminUsers() {
  const [users, setUsers] = useState<UserData[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [debouncedSearchQuery, setDebouncedSearchQuery] = useState("");
  const [roleFilter, setRoleFilter] = useState<string>("all");
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const [selectedUser, setSelectedUser] = useState<UserData | null>(null);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [selectedUserIds, setSelectedUserIds] = useState<Set<string>>(new Set());
  const [isSelectAll, setIsSelectAll] = useState(false);

  // Debounce search query
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearchQuery(searchQuery);
    }, 500);

    return () => clearTimeout(timer);
  }, [searchQuery]);

  useEffect(() => {
    loadUsers();
  }, [page, roleFilter, debouncedSearchQuery]); // eslint-disable-line react-hooks/exhaustive-deps -- load when filters/pagination change

  const loadUsers = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      if (debouncedSearchQuery) params.set("search", debouncedSearchQuery);
      if (roleFilter !== "all") params.set("role", roleFilter);
      params.set("page", page.toString());
      params.set("limit", "50");

      const response = await fetcher.get<{
        data: { data: UserData[]; meta: { page: number; limit: number; total: number; has_more: boolean } };
        error: null;
      }>(`/api/admin/users?${params.toString()}`);

      const inner = (response as { data?: { data?: UserData[]; meta?: { total: number; has_more: boolean } } })?.data;
      const list = Array.isArray(inner?.data) ? inner.data : [];
      setUsers(list);
      if (inner?.meta) {
        setTotal(inner.meta.total);
        setHasMore(inner.meta.has_more ?? false);
      }
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load users";
      setError(errorMessage);
      console.error("Error loading users:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleUserClick = (user: UserData) => {
    setSelectedUser(user);
    setIsDetailModalOpen(true);
  };

  const handleModalClose = () => {
    setIsDetailModalOpen(false);
    setSelectedUser(null);
  };

  const handleModalUpdate = () => {
    loadUsers();
  };

  const handleSelectUser = (userId: string, checked: boolean) => {
    const newSelected = new Set(selectedUserIds);
    if (checked) {
      newSelected.add(userId);
    } else {
      newSelected.delete(userId);
    }
    setSelectedUserIds(newSelected);
    setIsSelectAll(newSelected.size === filteredUsers.length && filteredUsers.length > 0);
  };

  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      const allIds = new Set(filteredUsers.map((u) => u.id));
      setSelectedUserIds(allIds);
      setIsSelectAll(true);
    } else {
      setSelectedUserIds(new Set());
      setIsSelectAll(false);
    }
  };

  const handleBulkAction = async (action: string) => {
    if (selectedUserIds.size === 0) {
      toast.error("Please select at least one user");
      return;
    }

    const userIds = Array.from(selectedUserIds);

    try {
      switch (action) {
        case "activate":
          if (!confirm(`Activate ${userIds.length} user(s)?`)) return;
          await fetcher.post("/api/admin/users/bulk", {
            user_ids: userIds,
            action: "activate",
          });
          toast.success(`${userIds.length} user(s) activated`);
          break;
        case "deactivate":
          if (!confirm(`Deactivate ${userIds.length} user(s)?`)) return;
          const reason = prompt("Enter reason (optional):");
          await fetcher.post("/api/admin/users/bulk", {
            user_ids: userIds,
            action: "deactivate",
            reason: reason || null,
          });
          toast.success(`${userIds.length} user(s) deactivated`);
          break;
        case "delete":
          const confirmation = prompt(
            `WARNING: This will permanently delete ${userIds.length} user(s) and all their data. This action cannot be undone.\n\nType "DELETE" to confirm:`
          );
          if (confirmation !== "DELETE") {
            toast.info("Deletion cancelled");
            return;
          }
          await fetcher.post("/api/admin/users/bulk", {
            user_ids: userIds,
            action: "delete",
          });
          toast.success(`${userIds.length} user(s) deleted`);
          break;
        case "export":
          // Export selected users
          toast.info("Export functionality for selected users coming soon");
          return;
      }
      setSelectedUserIds(new Set());
      setIsSelectAll(false);
      loadUsers();
    } catch (error: any) {
      toast.error(error.message || `Failed to perform bulk ${action}`);
    }
  };

  const handleRoleChange = async (userId: string, newRole: UserRole) => {
    if (!confirm(`Are you sure you want to change this user's role to ${newRole}?`)) {
      return;
    }

    try {
      await fetcher.put(`/api/admin/users/${userId}/role`, { role: newRole });
      toast.success("User role updated");
      loadUsers();
    } catch {
      toast.error("Failed to update user role");
    }
  };

  const handleSuspend = async (user: UserData, e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent row click
    if (user.role === "superadmin") {
      toast.error("Cannot suspend superadmin accounts");
      return;
    }

    const reason = prompt(`Enter reason for suspending ${user.full_name || user.email} (optional):`);
    if (reason === null) return;

    if (!confirm(`Are you sure you want to suspend ${user.full_name || user.email}?`)) {
      return;
    }

    try {
      await fetcher.patch(`/api/admin/users/${user.id}`, {
        deactivated_at: new Date().toISOString(),
        deactivation_reason: reason || null,
      });
      toast.success("User suspended successfully");
      loadUsers();
    } catch (error: any) {
      toast.error(error.message || "Failed to suspend user");
    }
  };

  const handleReactivate = async (user: UserData, e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent row click

    if (!confirm(`Are you sure you want to reactivate ${user.full_name || user.email}?`)) {
      return;
    }

    try {
      await fetcher.patch(`/api/admin/users/${user.id}`, {
        deactivated_at: null,
        deactivation_reason: null,
