                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={(e) => handleDelete(user, e)}
                          disabled={user.role === "superadmin"}
                          className="text-red-600"
                        >
                          <Trash2 className="w-4 h-4 mr-2" />
                          Delete
                        </DropdownMenuItem>
                        <DropdownMenuItem asChild>
                          <Link href={`/admin/users/${user.id}`}>
