                      </span>
                    </div>
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-gray-500">Role:</span>
                      <div className="flex flex-col gap-1 items-end">
                        <Badge className={getRoleBadgeColor(user.role)}>
                          {user.role}
