                </span>
                <span className="font-medium capitalize">{verification.document_type}</span>
              </div>
              <div className="flex items-center justify-between text-xs sm:text-sm">
                <span className="text-gray-500 flex items-center gap-1">
                  <Globe className="w-3 h-3" />
                  Country:
                </span>
                <span className="font-medium">{verification.country}</span>
              </div>
              <div className="flex items-center justify-between text-xs sm:text-sm">
                <span className="text-gray-500 flex items-center gap-1">
                  <Calendar className="w-3 h-3" />
                  Submitted:
                </span>
                <span className="font-medium">
                  {new Date(verification.submitted_at).toLocaleDateString()}
                </span>
              </div>
              {verification.rejection_reason && (
                <div className="mt-2 p-2 bg-red-50 border border-red-200 rounded text-xs text-red-700">
                  <strong>Reason:</strong> {verification.rejection_reason}
                </div>
              )}
            </div>

            <div className="mt-3 pt-3 border-t border-white/40">
              <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => onReview(verification)}
                  className="w-full text-xs sm:text-sm border-white/40 backdrop-blur-sm bg-white/60 hover:bg-white/80"
                >
                  <Eye className="h-3 w-3 sm:h-4 sm:w-4 mr-2" />
                  Review Verification
                </Button>
              </motion.div>
            </div>
          </motion.div>
        ))}
      </div>
    </>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Switch } from "@/components/ui/switch";
import { Plus, Edit, Trash2, Copy, Webhook, TestTube, Eye, AlertCircle, CheckCircle2, XCircle } from "lucide-react";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Textarea } from "@/components/ui/textarea";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Checkbox } from "@/components/ui/checkbox";

interface WebhookEndpoint {
  id: string;
  name: string;
  url: string;
  events: string[];
  is_active: boolean;
  retry_count: number;
  timeout_seconds: number;
  created_at: string;
  updated_at: string;
}

interface WebhookEvent {
  id: string;
  event_type: string;
  status: string;
  response_status: number | null;
  error_message: string | null;
  attempt_count: number;
  created_at: string;
  sent_at: string | null;
}

const availableEvents = [
  "booking.created",
  "booking.updated",
  "booking.cancelled",
  "booking.completed",
  "payment.received",
  "payment.refunded",
  "provider.approved",
  "provider.suspended",
  "user.created",
  "user.updated",
  "review.created",
  "review.updated",
];

export default function WebhooksPage() {
  const [endpoints, setEndpoints] = useState<WebhookEndpoint[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isTestDialogOpen, setIsTestDialogOpen] = useState(false);
  const [isViewDialogOpen, setIsViewDialogOpen] = useState(false);
  const [viewingEndpoint, setViewingEndpoint] = useState<WebhookEndpoint | null>(null);
  const [viewingEvents, setViewingEvents] = useState<WebhookEvent[]>([]);
  const [newSecret, setNewSecret] = useState<string | null>(null);
  const [testingEndpoint, setTestingEndpoint] = useState<WebhookEndpoint | null>(null);
  const [testResult, setTestResult] = useState<any>(null);
  const [editingEndpoint, setEditingEndpoint] = useState<WebhookEndpoint | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    url: "",
    events: [] as string[],
    is_active: true,
    retry_count: 3,
    timeout_seconds: 30,
    headers: "{}",
  });

  useEffect(() => {
    loadEndpoints();
  }, []);

  const loadEndpoints = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data: { endpoints: WebhookEndpoint[] } }>(
        "/api/admin/webhooks/endpoints"
      );
      setEndpoints(response.data?.endpoints ?? []);
    } catch (error) {
      console.error("Failed to load webhook endpoints:", error);
      toast.error("Failed to load webhook endpoints");
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreate = () => {
    setEditingEndpoint(null);
    setNewSecret(null);
    setFormData({
      name: "",
      url: "",
      events: [],
      is_active: true,
      retry_count: 3,
      timeout_seconds: 30,
      headers: "{}",
    });
    setIsDialogOpen(true);
  };

  const handleEdit = (endpoint: WebhookEndpoint) => {
    setEditingEndpoint(endpoint);
    setNewSecret(null);
    setFormData({
      name: endpoint.name,
      url: endpoint.url,
      events: endpoint.events || [],
      is_active: endpoint.is_active,
      retry_count: endpoint.retry_count,
      timeout_seconds: endpoint.timeout_seconds,
      headers: "{}",
    });
    setIsDialogOpen(true);
  };

  const handleView = async (endpoint: WebhookEndpoint) => {
    setViewingEndpoint(endpoint);
    try {
      const response = await fetcher.get<{
        endpoint: WebhookEndpoint;
        events: WebhookEvent[];
      }>(`/api/admin/webhooks/endpoints/${endpoint.id}`);
      setViewingEvents(response.events || []);
      setIsViewDialogOpen(true);
    } catch (error) {
      console.error("Failed to load endpoint details:", error);
      toast.error("Failed to load endpoint details");
    }
  };

  const handleTest = (endpoint: WebhookEndpoint) => {
    setTestingEndpoint(endpoint);
    setTestResult(null);
    setIsTestDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this webhook endpoint?")) return;

    try {
      await fetcher.delete(`/api/admin/webhooks/endpoints/${id}`);
      toast.success("Webhook endpoint deleted successfully");
      loadEndpoints();
    } catch (error) {
      console.error("Failed to delete endpoint:", error);
      toast.error("Failed to delete webhook endpoint");
    }
  };

  const handleSave = async () => {
    try {
      let headersObj = {};
      try {
        headersObj = JSON.parse(formData.headers);
      } catch {
        toast.error("Invalid JSON in headers field");
        return;
      }

      if (editingEndpoint) {
        await fetcher.patch(`/api/admin/webhooks/endpoints/${editingEndpoint.id}`, {
          ...formData,
          headers: headersObj,
        });
        toast.success("Webhook endpoint updated successfully");
      } else {
        const response = await fetcher.post<{
          data: { endpoint: WebhookEndpoint & { secret?: string } };
        }>("/api/admin/webhooks/endpoints", {
          ...formData,
          headers: headersObj,
        });
        const endpoint = response.data?.endpoint;
        if (endpoint?.secret) {
          setNewSecret(endpoint.secret);
          toast.success("Webhook endpoint created successfully");
        }
      }
      setIsDialogOpen(false);
      loadEndpoints();
    } catch (error) {
      console.error("Failed to save endpoint:", error);
      toast.error(error instanceof FetchError ? error.message : "Failed to save webhook endpoint");
    }
  };

  const handleRunTest = async () => {
    if (!testingEndpoint) return;

    try {
      const response = await fetcher.post<{
        data: {
          success: boolean;
          status: number;
          response: string;
          timestamp: number;
          signature: string;
        };
      }>(`/api/admin/webhooks/endpoints/${testingEndpoint.id}/test`, {
        test_payload: { test: true, message: "Test webhook from admin panel" },
      });

      setTestResult(response.data ?? response);
      toast.success("Test webhook sent");
      loadEndpoints(); // Refresh to see the test event
    } catch (error) {
      console.error("Failed to test webhook:", error);
      toast.error(error instanceof FetchError ? error.message : "Failed to test webhook");
      setTestResult({
        success: false,
        error: error instanceof FetchError ? error.message : "Test failed",
      });
    }
  };

  const handleCopySecret = (secret: string) => {
    navigator.clipboard.writeText(secret);
    toast.success("Secret copied to clipboard");
  };

  const toggleEvent = (event: string) => {
    setFormData((prev) => ({
      ...prev,
      events: prev.events.includes(event)
        ? prev.events.filter((e) => e !== event)
        : [...prev.events, event],
    }));
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "success":
        return "bg-green-100 text-green-800";
      case "failed":
        return "bg-red-100 text-red-800";
      case "pending":
        return "bg-yellow-100 text-yellow-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "success":
        return <CheckCircle2 className="w-4 h-4" />;
      case "failed":
        return <XCircle className="w-4 h-4" />;
      default:
        return <AlertCircle className="w-4 h-4" />;
    }
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading webhook endpoints..." />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["superadmin"]} redirectTo="/">
      <div className="container mx-auto px-4 py-8">
        <div className="flex justify-between items-center mb-6">
          <div>
            <h1 className="text-2xl font-bold">Webhooks Management</h1>
            <p className="text-gray-600 mt-1">Configure webhook endpoints for external integrations</p>
          </div>
          <Button onClick={handleCreate} className="bg-[#FF0077] hover:bg-[#D60565]">
            <Plus className="w-4 h-4 mr-2" />
            Create Webhook
          </Button>
        </div>

        {newSecret && (
          <div className="mb-6 p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
            <div className="flex items-start justify-between">
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-2">
                  <AlertCircle className="w-5 h-5 text-yellow-600" />
                  <h3 className="font-semibold text-yellow-900">Webhook Secret</h3>
                </div>
                <p className="text-sm text-yellow-800 mb-3">
                  Please copy this secret now. You won't be able to see it again!
                </p>
                <div className="flex items-center gap-2">
                  <Input value={newSecret} readOnly className="font-mono text-sm" />
                  <Button variant="outline" size="sm" onClick={() => handleCopySecret(newSecret)}>
                    <Copy className="w-4 h-4 mr-2" />
                    Copy
                  </Button>
                </div>
              </div>
              <Button variant="ghost" size="sm" onClick={() => setNewSecret(null)}>
                ├ù
              </Button>
            </div>
          </div>
        )}

        <Tabs defaultValue="endpoints" className="space-y-4">
          <TabsList>
            <TabsTrigger value="endpoints">Endpoints</TabsTrigger>
            <TabsTrigger value="failures">Failed Events</TabsTrigger>
          </TabsList>

          <TabsContent value="endpoints" className="space-y-4">
            {endpoints.length === 0 ? (
              <EmptyState
                icon={Webhook}
                title="No webhook endpoints"
                description="Create your first webhook endpoint to get started"
                action={{
                  label: "Create Webhook",
                  onClick: handleCreate,
                }}
              />
            ) : (
              <div className="bg-white rounded-lg shadow overflow-hidden">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Name</TableHead>
                      <TableHead>URL</TableHead>
                      <TableHead>Events</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead>Retries</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {endpoints.map((endpoint) => (
                      <TableRow key={endpoint.id}>
                        <TableCell className="font-medium">{endpoint.name}</TableCell>
                        <TableCell>
                          <code className="text-sm bg-gray-100 px-2 py-1 rounded">
                            {endpoint.url.length > 50
                              ? `${endpoint.url.substring(0, 50)}...`
                              : endpoint.url}
                          </code>
                        </TableCell>
                        <TableCell>
                          <div className="flex flex-wrap gap-1">
                            {endpoint.events.slice(0, 2).map((e) => (
                              <Badge key={e} variant="secondary" className="text-xs">
                                {e}
                              </Badge>
                            ))}
                            {endpoint.events.length > 2 && (
                              <Badge variant="secondary" className="text-xs">
                                +{endpoint.events.length - 2}
                              </Badge>
                            )}
                          </div>
                        </TableCell>
                        <TableCell>
                          {endpoint.is_active ? (
                            <Badge className="bg-green-100 text-green-800">Active</Badge>
                          ) : (
                            <Badge variant="outline">Inactive</Badge>
                          )}
                        </TableCell>
                        <TableCell>{endpoint.retry_count}</TableCell>
                        <TableCell className="text-right">
                          <div className="flex items-center justify-end gap-2">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleView(endpoint)}
                            >
                              <Eye className="w-4 h-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleTest(endpoint)}
                            >
                              <TestTube className="w-4 h-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleEdit(endpoint)}
                            >
                              <Edit className="w-4 h-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleDelete(endpoint.id)}
                              className="text-red-600 hover:text-red-700"
                            >
                              <Trash2 className="w-4 h-4" />
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            )}
          </TabsContent>

          <TabsContent value="failures" className="space-y-4">
            <WebhookFailuresTab />
          </TabsContent>
        </Tabs>

        {/* Create/Edit Dialog */}
        <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
          <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>
                {editingEndpoint ? "Edit Webhook Endpoint" : "Create Webhook Endpoint"}
              </DialogTitle>
              <DialogDescription>
                {editingEndpoint
                  ? "Update webhook endpoint configuration"
                  : "Create a new webhook endpoint for external integrations"}
              </DialogDescription>
            </DialogHeader>

            <div className="space-y-4">
              <div>
                <Label htmlFor="name">Name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="e.g., Production Webhook"
                  required
                />
              </div>

              <div>
                <Label htmlFor="url">Webhook URL *</Label>
                <Input
                  id="url"
                  type="url"
                  value={formData.url}
                  onChange={(e) => setFormData({ ...formData, url: e.target.value })}
                  placeholder="https://example.com/webhook"
                  required
                />
              </div>

              <div>
                <Label>Subscribe to Events *</Label>
                <div className="grid grid-cols-2 gap-2 mt-2 max-h-64 overflow-y-auto p-2 border rounded">
                  {availableEvents.map((event) => (
                    <div
                      key={event}
                      className="flex items-center gap-2 p-2 border rounded cursor-pointer hover:bg-gray-50"
                      onClick={() => toggleEvent(event)}
                    >
                      <Checkbox
                        checked={formData.events.includes(event)}
                        onCheckedChange={() => toggleEvent(event)}
                      />
                      <span className="text-sm">{event}</span>
                    </div>
                  ))}
                </div>
                {formData.events.length === 0 && (
                  <p className="text-xs text-red-600 mt-1">Please select at least one event</p>
                )}
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="retry_count">Retry Count</Label>
                  <Input
                    id="retry_count"
                    type="number"
                    value={formData.retry_count}
                    onChange={(e) =>
                      setFormData({ ...formData, retry_count: parseInt(e.target.value) || 3 })
                    }
                    min={0}
                    max={10}
                  />
                </div>
                <div>
                  <Label htmlFor="timeout_seconds">Timeout (seconds)</Label>
                  <Input
                    id="timeout_seconds"
                    type="number"
                    value={formData.timeout_seconds}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        timeout_seconds: parseInt(e.target.value) || 30,
                      })
                    }
                    min={1}
                    max={300}
                  />
                </div>
              </div>

              <div>
                <Label htmlFor="headers">Custom Headers (JSON)</Label>
                <Textarea
                  id="headers"
                  value={formData.headers}
                  onChange={(e) => setFormData({ ...formData, headers: e.target.value })}
                  rows={3}
                  placeholder='{"Authorization": "Bearer token"}'
                  className="font-mono text-sm"
                />
                <p className="text-xs text-gray-500 mt-1">
                  Optional custom headers to include with webhook requests
                </p>
              </div>

              <div className="flex items-center gap-4 p-4 bg-gray-50 rounded-lg">
                <Switch
                  checked={formData.is_active}
                  onCheckedChange={(checked) => setFormData({ ...formData, is_active: checked })}
                />
                <div>
                  <Label>Active</Label>
                  <p className="text-xs text-gray-500">Enable this webhook endpoint</p>
                </div>
              </div>
            </div>

            <DialogFooter>
              <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
                Cancel
              </Button>
              <Button
                onClick={handleSave}
                disabled={formData.events.length === 0}
                className="bg-[#FF0077] hover:bg-[#D60565]"
              >
                {editingEndpoint ? "Update" : "Create"} Webhook
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>

        {/* Test Dialog */}
        <Dialog open={isTestDialogOpen} onOpenChange={setIsTestDialogOpen}>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>Test Webhook: {testingEndpoint?.name}</DialogTitle>
              <DialogDescription>
                Send a test webhook to verify the endpoint is working
              </DialogDescription>
            </DialogHeader>

            {testResult && (
              <div
                className={`p-4 rounded-lg mb-4 ${
                  testResult.success
                    ? "bg-green-50 border border-green-200"
                    : "bg-red-50 border border-red-200"
                }`}
              >
                <div className="flex items-center gap-2 mb-2">
                  {testResult.success ? (
                    <CheckCircle2 className="w-5 h-5 text-green-600" />
                  ) : (
                    <XCircle className="w-5 h-5 text-red-600" />
                  )}
                  <h3 className="font-semibold">
                    {testResult.success ? "Test Successful" : "Test Failed"}
                  </h3>
                </div>
                {testResult.status && (
                  <p className="text-sm">HTTP Status: {testResult.status}</p>
                )}
                {testResult.response && (
                  <div className="mt-2">
                    <p className="text-sm font-medium mb-1">Response:</p>
                    <pre className="text-xs bg-white p-2 rounded border overflow-auto max-h-32">
                      {testResult.response}
                    </pre>
                  </div>
                )}
                {testResult.error && (
                  <p className="text-sm text-red-600 mt-2">{testResult.error}</p>
                )}
              </div>
            )}

            <div className="space-y-4">
              <p className="text-sm text-gray-600">
                Click the button below to send a test webhook to this endpoint.
              </p>
              <Button onClick={handleRunTest} className="bg-[#FF0077] hover:bg-[#D60565]">
                <TestTube className="w-4 h-4 mr-2" />
                Send Test Webhook
              </Button>
            </div>
          </DialogContent>
        </Dialog>

        {/* View Details Dialog */}
        <Dialog open={isViewDialogOpen} onOpenChange={setIsViewDialogOpen}>
          <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>Webhook Details: {viewingEndpoint?.name}</DialogTitle>
              <DialogDescription>View endpoint details and recent events</DialogDescription>
            </DialogHeader>

            {viewingEndpoint && (
              <div className="space-y-6">
                <div>
                  <Label className="text-sm font-medium text-gray-500">URL</Label>
                  <p className="text-sm font-mono bg-gray-100 p-2 rounded">{viewingEndpoint.url}</p>
                </div>

                <div>
                  <Label className="text-sm font-medium text-gray-500">Subscribed Events</Label>
                  <div className="flex flex-wrap gap-2 mt-2">
                    {viewingEndpoint.events.map((event) => (
                      <Badge key={event} variant="secondary">
                        {event}
                      </Badge>
                    ))}
                  </div>
                </div>

                <div>
                  <Label className="text-sm font-medium text-gray-500 mb-2 block">
                    Recent Events
                  </Label>
                  {viewingEvents.length === 0 ? (
                    <p className="text-sm text-gray-500">No events yet</p>
                  ) : (
                    <div className="space-y-2">
                      {viewingEvents.map((event) => (
                        <div
                          key={event.id}
                          className="flex items-center justify-between p-3 border rounded"
                        >
                          <div className="flex items-center gap-3">
                            {getStatusIcon(event.status)}
                            <div>
                              <p className="text-sm font-medium">{event.event_type}</p>
                              <p className="text-xs text-gray-500">
                                {new Date(event.created_at).toLocaleString()}
                              </p>
                            </div>
                          </div>
                          <div className="flex items-center gap-2">
                            <Badge className={getStatusColor(event.status)}>
                              {event.status}
                            </Badge>
                            {event.response_status && (
                              <Badge variant="outline">{event.response_status}</Badge>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            )}
          </DialogContent>
        </Dialog>
      </div>
    </RoleGuard>
  );
}

function WebhookFailuresTab() {
  const [failures, setFailures] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [retryingId, setRetryingId] = useState<string | null>(null);

  useEffect(() => {
    loadFailures();
  }, []);

  const loadFailures = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data: any[] }>("/api/admin/webhooks/failures");
      setFailures(Array.isArray(response.data) ? response.data : []);
    } catch (error) {
      console.error("Failed to load webhook failures:", error);
      toast.error("Failed to load webhook failures");
    } finally {
      setIsLoading(false);
    }
  };

  const handleRetry = async (id: string) => {
    try {
      setRetryingId(id);
      await fetcher.post(`/api/admin/webhooks/failures/${id}/retry`, {});
      toast.success("Retry initiated");
      await loadFailures();
    } catch (error) {
      console.error("Failed to retry webhook:", error);
      toast.error(error instanceof FetchError ? error.message : "Failed to retry webhook");
    } finally {
      setRetryingId(null);
    }
  };

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading webhook failures..." />;
  }

  return (
    <div>
      {failures.length === 0 ? (
        <EmptyState
          icon={CheckCircle2}
          title="No webhook failures"
          description="All webhooks are working correctly"
        />
      ) : (
        <div className="bg-white rounded-lg shadow overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Event Type</TableHead>
                <TableHead>Endpoint</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Attempts</TableHead>
                <TableHead>Created</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {failures.map((failure) => (
                <TableRow key={failure.id}>
                  <TableCell className="font-medium">{failure.event_type}</TableCell>
                  <TableCell>
                    <code className="text-xs">{failure.endpoint_id?.substring(0, 8)}...</code>
                  </TableCell>
                  <TableCell>
                    <Badge className="bg-red-100 text-red-800">Failed</Badge>
                  </TableCell>
                  <TableCell>{failure.attempt_count}</TableCell>
                  <TableCell>
                    {new Date(failure.created_at).toLocaleString()}
                  </TableCell>
                  <TableCell className="text-right">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleRetry(failure.id)}
                      disabled={retryingId === failure.id}
                    >
                      {retryingId === failure.id ? "RetryingΓÇª" : "Retry"}
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}
    </div>
  );
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";

/**
 * GET /api/admin/account-security-copy
 * Returns the account security sidebar copy for superadmin editing.
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const { data: row } = await supabase
      .from("platform_settings")
      .select("id, settings")
      .eq("is_active", true)
      .limit(1)
      .maybeSingle();

    const settings = (row as any)?.settings ?? {};
    const copy = settings.account_security_copy ?? {
      title: "Keeping your account secure",
      body: "We regularly review accounts to make sure they're as secure as possible. We'll also let you know if there's more we can do to increase the security of your account.",
      safety_tips_customer: { label: "Safety tips for customers", url: "/help#customer" },
      safety_tips_provider: { label: "Safety tips for providers", url: "/help#provider" },
    };
    return successResponse(copy);
  } catch (error) {
    return handleApiError(error);
  }
}

/**
 * PATCH /api/admin/account-security-copy
 * Update the account security sidebar copy (superadmin only).
 */
export async function PATCH(req: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["superadmin"], req);
    const supabase = await getSupabaseServer(req);
    const body = await req.json();

    const { data: row } = await supabase
      .from("platform_settings")
      .select("id, settings")
      .eq("is_active", true)
      .limit(1)
      .maybeSingle();

    if (!row) {
      return successResponse({ message: "No platform settings row to update; account security copy will use defaults until a row exists." });
    }

    const currentSettings = (row as any).settings ?? {};
    const updatedSettings = {
      ...currentSettings,
      account_security_copy: {
        title: body.title ?? currentSettings.account_security_copy?.title ?? "Keeping your account secure",
        body: body.body ?? currentSettings.account_security_copy?.body ?? "",
        safety_tips_customer:
          body.safety_tips_customer && typeof body.safety_tips_customer === "object"
            ? {
                label: body.safety_tips_customer.label ?? "Safety tips for customers",
                url: body.safety_tips_customer.url ?? "/help#customer",
              }
            : currentSettings.account_security_copy?.safety_tips_customer ?? {
                label: "Safety tips for customers",
                url: "/help#customer",
              },
        safety_tips_provider:
          body.safety_tips_provider && typeof body.safety_tips_provider === "object"
            ? {
                label: body.safety_tips_provider.label ?? "Safety tips for providers",
                url: body.safety_tips_provider.url ?? "/help#provider",
              }
            : currentSettings.account_security_copy?.safety_tips_provider ?? {
                label: "Safety tips for providers",
                url: "/help#provider",
              },
      },
    };

    const { error } = await supabase
      .from("platform_settings")
      .update({
        settings: updatedSettings,
        updated_at: new Date().toISOString(),
      })
      .eq("id", (row as any).id);

    if (error) throw error;

    await writeAuditLog({
      actor_user_id: user.id,
      actor_role: (user as { role?: string }).role ?? null,
      action: "account_security_copy_updated",
      entity_type: "platform_settings",
      metadata: {},
    });

    return successResponse({ message: "Account security copy saved" });
  } catch (error) {
    return handleApiError(error);
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseServer } from '@/lib/supabase/server';
import { requireRoleInApi, successResponse, handleApiError } from '@/lib/supabase/api-helpers';

/**
 * GET /api/admin/activity
 * Get recent activity notifications for admin dashboard
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = await getSupabaseServer(request);

    if (!supabase) {
      return successResponse([]);
    }

    const now = new Date();
    const last24Hours = new Date(now.getTime() - 24 * 60 * 60 * 1000);
    const last7Days = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

    // Fetch all activity types in parallel
    const [
      pendingPayouts,
      pendingVerifications,
      newProviders,
      recentBookings,
      pendingProviderApprovals,
      webhookFailures,
      failedPayments,
      refundRequests,
      highValueTransactions,
      providerViolations,
      accountIssues,
      disputes,
    ] = await Promise.allSettled([
      // Pending payouts
      supabase
        .from('payouts')
        .select('id, provider_id, amount, currency, status, scheduled_at, created_at')
        .eq('status', 'pending')
        .order('created_at', { ascending: false })
        .limit(10),
      
      // Pending verifications
      supabase
        .from('user_verifications')
        .select('id, user_id, verification_type, status, submitted_at, created_at')
        .eq('status', 'pending')
        .order('submitted_at', { ascending: false })
        .limit(10),
      
      // New providers (last 7 days)
      supabase
        .from('providers')
        .select('id, user_id, business_name, status, created_at')
        .gte('created_at', last7Days.toISOString())
        .order('created_at', { ascending: false })
        .limit(10),
      
      // Recent bookings (last 24 hours)
      supabase
        .from('bookings')
        .select('id, customer_id, provider_id, booking_number, status, created_at')
        .gte('created_at', last24Hours.toISOString())
        .order('created_at', { ascending: false })
        .limit(10),
      
      // Pending provider approvals
      supabase
        .from('providers')
        .select('id, user_id, business_name, status, created_at')
        .eq('status', 'pending_approval')
        .order('created_at', { ascending: false })
        .limit(10),
      
      // Webhook failures (last 24 hours)
      supabase
        .from('webhook_events')
        .select('id, source, event_type, status, error_message, created_at')
        .eq('status', 'failed')
        .gte('created_at', last24Hours.toISOString())
        .order('created_at', { ascending: false })
        .limit(10),
      
      // Failed payment transactions (last 24 hours)
      supabase
        .from('finance_transactions')
        .select('id, transaction_type, amount, currency, status, booking_id, created_at')
        .in('status', ['failed', 'declined', 'error'])
        .gte('created_at', last24Hours.toISOString())
        .order('created_at', { ascending: false })
        .limit(10),
      
      // Refund requests (last 7 days)
      supabase
        .from('finance_transactions')
        .select('id, transaction_type, amount, currency, booking_id, created_at')
        .eq('transaction_type', 'refund')
        .gte('created_at', last7Days.toISOString())
        .order('created_at', { ascending: false })
        .limit(10),
      
      // High-value transactions (last 24 hours, > $500 or equivalent)
      supabase
        .from('finance_transactions')
        .select('id, transaction_type, amount, currency, booking_id, created_at')
        .eq('transaction_type', 'payment')
        .gte('amount', 500)
        .gte('created_at', last24Hours.toISOString())
        .order('amount', { ascending: false })
        .limit(5),
      
      // Provider violations/suspensions
      supabase
        .from('providers')
        .select('id, user_id, business_name, status, created_at, updated_at')
        .in('status', ['suspended', 'banned', 'inactive'])
        .gte('updated_at', last7Days.toISOString())
        .order('updated_at', { ascending: false })
        .limit(10),
      
      // Account issues (deactivated, suspended users)
      supabase
        .from('users')
        .select('id, full_name, email, role, is_active, deactivated_at, created_at')
        .or('is_active.eq.false,deactivated_at.not.is.null')
        .gte('deactivated_at', last7Days.toISOString())
        .order('deactivated_at', { ascending: false })
        .limit(10),
      
      // Booking disputes (open disputes)
      supabase
        .from('booking_disputes')
        .select('id, booking_id, reason, status, opened_by, created_at')
        .eq('status', 'open')
        .gte('created_at', last7Days.toISOString())
        .order('created_at', { ascending: false })
        .limit(10),
    ]);

    const activities: any[] = [];

    // Process pending payouts
    if (pendingPayouts.status === 'fulfilled' && pendingPayouts.value.data) {
      const { data: payouts } = pendingPayouts.value;
      if (payouts && payouts.length > 0) {
        // Get provider names
        const providerIds = [...new Set(payouts.map((p: any) => p.provider_id).filter(Boolean))];
        const { data: providers } = providerIds.length > 0
          ? await supabase
              .from('providers')
              .select('id, business_name')
              .in('id', providerIds)
          : { data: [] };
        
        const providerMap = new Map((providers || []).map((p: any) => [p.id, p]));
        
        payouts.forEach((payout: any) => {
          const provider = providerMap.get(payout.provider_id);
          activities.push({
            id: `payout-${payout.id}`,
            type: 'payout_request',
            title: 'Payout Request',
            message: provider 
              ? `${provider.business_name} requested payout of ${payout.currency} ${payout.amount.toFixed(2)}`
              : `Payout request of ${payout.currency} ${payout.amount.toFixed(2)}`,
            timestamp: payout.created_at,
            link: `/admin/payouts?status=pending`,
            priority: 'high',
          });
        });
      }
    }

    // Process pending verifications
    if (pendingVerifications.status === 'fulfilled' && pendingVerifications.value.data) {
      const { data: verifications } = pendingVerifications.value;
      if (verifications && verifications.length > 0) {
        // Get user names
        const userIds = [...new Set(verifications.map((v: any) => v.user_id).filter(Boolean))];
        const { data: users } = userIds.length > 0
          ? await supabase
              .from('users')
              .select('id, full_name, email')
              .in('id', userIds)
          : { data: [] };
        
        const userMap = new Map((users || []).map((u: any) => [u.id, u]));
        
        verifications.forEach((verification: any) => {
          const user = userMap.get(verification.user_id);
          activities.push({
            id: `verification-${verification.id}`,
            type: 'verification',
            title: 'Identity Verification',
            message: user
              ? `${user.full_name || user.email} submitted ${verification.verification_type} verification`
              : `New ${verification.verification_type} verification submitted`,
            timestamp: verification.submitted_at || verification.created_at,
            link: `/admin/verifications?status=pending`,
            priority: 'high',
          });
        });
      }
    }

    // Process pending provider approvals
    if (pendingProviderApprovals.status === 'fulfilled' && pendingProviderApprovals.value.data) {
      const { data: providers } = pendingProviderApprovals.value;
      if (providers && providers.length > 0) {
        providers.forEach((provider: any) => {
          activities.push({
            id: `provider-approval-${provider.id}`,
            type: 'provider_approval',
            title: 'Provider Approval',
            message: `${provider.business_name || 'New provider'} is waiting for approval`,
            timestamp: provider.created_at,
            link: `/admin/providers?status=pending_approval`,
            priority: 'high',
          });
        });
      }
    }

    // Process new providers (last 7 days)
    if (newProviders.status === 'fulfilled' && newProviders.value.data) {
      const { data: providers } = newProviders.value;
      if (providers && providers.length > 0) {
        providers.forEach((provider: any) => {
          // Only add if not already added as pending approval
          if (provider.status !== 'pending_approval') {
            activities.push({
              id: `new-provider-${provider.id}`,
              type: 'new_provider',
              title: 'New Provider',
              message: `${provider.business_name || 'New provider'} joined the platform`,
              timestamp: provider.created_at,
              link: `/admin/providers`,
              priority: 'medium',
            });
          }
        });
      }
    }

    // Process recent bookings
    if (recentBookings.status === 'fulfilled' && recentBookings.value.data) {
      const { data: bookings } = recentBookings.value;
      if (bookings && bookings.length > 0) {
        bookings.forEach((booking: any) => {
          activities.push({
            id: `booking-${booking.id}`,
            type: 'booking',
            title: 'New Booking',
            message: `Booking #${booking.booking_number || booking.id.slice(0, 8)} created`,
            timestamp: booking.created_at,
            link: `/admin/bookings`,
            priority: 'medium',
          });
        });
      }
    }

    // Sort by timestamp (most recent first)
    activities.sort((a, b) => 
      new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
    );

    // Process webhook failures
    if (webhookFailures.status === 'fulfilled' && webhookFailures.value.data) {
      const { data: failures } = webhookFailures.value;
      if (failures && failures.length > 0) {
        failures.forEach((failure: any) => {
          activities.push({
            id: `webhook-${failure.id}`,
            type: 'webhook_failure',
            title: 'Webhook Failure',
            message: `${failure.source || 'System'} webhook failed: ${failure.event_type || 'Unknown event'}`,
            timestamp: failure.created_at,
            link: `/admin/webhooks/failures`,
            priority: 'high',
          });
        });
      }
    }

    // Process failed payments
    if (failedPayments.status === 'fulfilled' && failedPayments.value.data) {
      const { data: transactions } = failedPayments.value;
      if (transactions && transactions.length > 0) {
        transactions.forEach((tx: any) => {
          activities.push({
            id: `payment-failure-${tx.id}`,
            type: 'payment_failure',
            title: 'Payment Failed',
            message: `Payment of ${tx.currency} ${tx.amount.toFixed(2)} failed (${tx.status})`,
            timestamp: tx.created_at,
            link: `/admin/finance`,
            priority: 'high',
          });
        });
      }
    }

    // Process refund requests
    if (refundRequests.status === 'fulfilled' && refundRequests.value.data) {
      const { data: refunds } = refundRequests.value;
      if (refunds && refunds.length > 0) {
        refunds.forEach((refund: any) => {
          activities.push({
            id: `refund-${refund.id}`,
            type: 'refund_request',
            title: 'Refund Request',
            message: `Refund request for ${refund.currency} ${refund.amount.toFixed(2)}`,
            timestamp: refund.created_at,
            link: `/admin/finance`,
            priority: 'high',
          });
        });
      }
    }

    // Process high-value transactions
    if (highValueTransactions.status === 'fulfilled' && highValueTransactions.value.data) {
      const { data: transactions } = highValueTransactions.value;
      if (transactions && transactions.length > 0) {
        transactions.forEach((tx: any) => {
          activities.push({
            id: `high-value-${tx.id}`,
            type: 'high_value_transaction',
            title: 'High-Value Transaction',
            message: `Large payment: ${tx.currency} ${tx.amount.toFixed(2)}`,
            timestamp: tx.created_at,
            link: `/admin/finance`,
            priority: 'medium',
          });
        });
      }
    }

    // Process provider violations
    if (providerViolations.status === 'fulfilled' && providerViolations.value.data) {
      const { data: providers } = providerViolations.value;
      if (providers && providers.length > 0) {
        providers.forEach((provider: any) => {
          activities.push({
            id: `provider-violation-${provider.id}`,
            type: 'provider_violation',
            title: 'Provider Status Change',
            message: `${provider.business_name || 'Provider'} status changed to ${provider.status}`,
            timestamp: provider.updated_at || provider.created_at,
            link: `/admin/providers?status=${provider.status}`,
            priority: 'high',
          });
        });
      }
    }

    // Process account issues
    if (accountIssues.status === 'fulfilled' && accountIssues.value.data) {
      const { data: users } = accountIssues.value;
      if (users && users.length > 0) {
        users.forEach((user: any) => {
          activities.push({
            id: `account-issue-${user.id}`,
            type: 'account_issue',
            title: 'Account Deactivated',
            message: `${user.full_name || user.email} (${user.role}) account was deactivated`,
            timestamp: user.deactivated_at || user.created_at,
            link: `/admin/users`,
            priority: 'medium',
          });
        });
      }
    }

    // Process disputes
    if (disputes.status === 'fulfilled' && disputes.value.data) {
      const { data: bookingDisputes } = disputes.value;
      if (bookingDisputes && bookingDisputes.length > 0) {
        // Get booking numbers
        const bookingIds = [...new Set(bookingDisputes.map((d: any) => d.booking_id).filter(Boolean))];
        const { data: bookings } = bookingIds.length > 0
          ? await supabase
              .from('bookings')
              .select('id, booking_number')
              .in('id', bookingIds)
          : { data: [] };
        
        const bookingMap = new Map((bookings || []).map((b: any) => [b.id, b]));
        
        bookingDisputes.forEach((dispute: any) => {
          const booking = bookingMap.get(dispute.booking_id);
          activities.push({
            id: `dispute-${dispute.id}`,
            type: 'dispute',
            title: 'Booking Dispute',
            message: `Dispute opened by ${dispute.opened_by} for booking #${booking?.booking_number || dispute.booking_id.slice(0, 8)}`,
            timestamp: dispute.created_at,
            link: `/admin/bookings`,
            priority: 'high',
          });
        });
      }
    }

    // Get counts for badge
    const counts = {
      pending_payouts: pendingPayouts.status === 'fulfilled' && pendingPayouts.value.data
        ? pendingPayouts.value.data.length
        : 0,
      pending_verifications: pendingVerifications.status === 'fulfilled' && pendingVerifications.value.data
        ? pendingVerifications.value.data.length
        : 0,
      pending_provider_approvals: pendingProviderApprovals.status === 'fulfilled' && pendingProviderApprovals.value.data
        ? pendingProviderApprovals.value.data.length
        : 0,
      webhook_failures: webhookFailures.status === 'fulfilled' && webhookFailures.value.data
        ? webhookFailures.value.data.length
        : 0,
      payment_failures: failedPayments.status === 'fulfilled' && failedPayments.value.data
        ? failedPayments.value.data.length
        : 0,
      refund_requests: refundRequests.status === 'fulfilled' && refundRequests.value.data
        ? refundRequests.value.data.length
        : 0,
      disputes: disputes.status === 'fulfilled' && disputes.value.data
        ? disputes.value.data.length
        : 0,
      provider_violations: providerViolations.status === 'fulfilled' && providerViolations.value.data
        ? providerViolations.value.data.length
        : 0,
    };

    const totalUnread = 
      counts.pending_payouts + 
      counts.pending_verifications + 
      counts.pending_provider_approvals +
      counts.webhook_failures +
      counts.payment_failures +
      counts.refund_requests +
      counts.disputes +
      counts.provider_violations;

    return successResponse({
      activities: activities.slice(0, 20), // Limit to 20 most recent
      counts,
      total_unread: totalUnread,
    });
  } catch (error) {
    return handleApiError(error, 'Failed to fetch activity notifications');
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";
import { z } from "zod";

const updateAddonSchema = z.object({
  name: z.string().min(1).optional(),
  description: z.string().optional().nullable(),
  type: z.enum(["service", "product", "upgrade"]).optional(),
  category: z.string().optional().nullable(),
  price: z.number().min(0).optional(),
  currency: z.string().length(3).optional(),
  duration_minutes: z.number().int().min(0).optional().nullable(),
  is_active: z.boolean().optional(),
  is_recommended: z.boolean().optional(),
  image_url: z.string().url().optional().nullable(),
  max_quantity: z.number().int().min(1).optional().nullable(),
  requires_service: z.boolean().optional(),
  sort_order: z.number().int().optional(),
  service_ids: z.array(z.string().uuid()).optional(),
});

/**
 * GET /api/admin/addons/[id]
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user: authUser } = await requireRoleInApi(["superadmin", "provider_owner"], request);

    const { id } = await params;
    const supabase = await getSupabaseServer(request);
    if (!supabase) {
      return NextResponse.json(
        { data: null, error: { message: "Server error", code: "SERVER_ERROR" } },
        { status: 500 }
      );
    }

    const { data: addon, error } = await supabase
      .from("service_addons")
      .select("*")
      .eq("id", id)
      .single();

    if (error || !addon) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Addon not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    // Check access - providers can only access their own addons; superadmin can access any
    if (authUser.role === "provider_owner" && (addon as any).provider_id) {
      const { data: provider } = await supabase
        .from("providers")
        .select("id")
        .eq("id", (addon as any).provider_id)
        .eq("user_id", authUser.id)
        .single();

      if (!provider) {
        return NextResponse.json(
          {
            data: null,
            error: {
              message: "Access denied",
              code: "FORBIDDEN",
            },
          },
          { status: 403 }
        );
      }
    }

    // service_addons view is from offerings; use applicable_service_ids (no service_addon_associations table)
    const addonData = addon as Record<string, any> & { applicable_service_ids?: string[]; title?: string };
    return NextResponse.json({
      data: {
        ...addonData,
        name: addonData.name ?? addonData.title ?? "",
        service_ids: Array.isArray(addonData.applicable_service_ids) ? addonData.applicable_service_ids : [],
      },
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch addon",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

/**
 * PUT /api/admin/addons/[id]
 */
export async function PUT(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user: authUser } = await requireRoleInApi(["superadmin", "provider_owner"], request);

    const { id } = await params;
    const supabase = await getSupabaseServer(request);
    if (!supabase) {
      return NextResponse.json(
        { data: null, error: { message: "Server error", code: "SERVER_ERROR" } },
        { status: 500 }
      );
    }
    const body = await request.json();

    const validationResult = updateAddonSchema.safeParse(body);
    if (!validationResult.success) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Validation failed",
            code: "VALIDATION_ERROR",
            details: validationResult.error.issues.map((issue) => ({
              path: issue.path.join("."),
              message: issue.message,
            })),
          },
        },
        { status: 400 }
      );
    }

    // Check existing addon
    const { data: existing } = await supabase
      .from("service_addons")
      .select("*")
      .eq("id", id)
      .single();

    if (!existing) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Addon not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    // Check access for provider_owner
    if (authUser.role === "provider_owner" && (existing as any).provider_id) {
      const { data: provider } = await supabase
        .from("providers")
        .select("id")
        .eq("id", (existing as any).provider_id)
        .eq("user_id", authUser.id)
        .single();

      if (!provider) {
        return NextResponse.json(
          {
            data: null,
            error: {
              message: "Access denied",
              code: "FORBIDDEN",
            },
          },
          { status: 403 }
        );
      }
    }

    const { service_ids, ...updateData } = validationResult.data;

    const { data: addon, error } = await (supabase
      .from("service_addons") as any)
      .update({
        ...updateData,
        updated_at: new Date().toISOString(),
      })
      .eq("id", id)
      .select()
      .single();

    if (error || !addon) {
      console.error("Error updating addon:", error);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to update addon",
            code: "UPDATE_ERROR",
          },
        },
        { status: 500 }
      );
    }

    // Update service associations if provided
    if (service_ids !== undefined) {
      // Delete existing associations
      await (supabase as any).from("service_addon_associations").delete().eq("addon_id", id);

      // Create new associations
      if (service_ids.length > 0) {
        const associations = service_ids.map((serviceId: string) => ({
          addon_id: id,
          service_id: serviceId,
          created_at: new Date().toISOString(),
        }));

        await (supabase as any).from("service_addon_associations").insert(associations);
      }
    }

    // Load updated service associations
    const { data: associations } = await (supabase as any)
      .from("service_addon_associations")
      .select("service_id")
      .eq("addon_id", id);

    await writeAuditLog({
      actor_user_id: authUser.id,
      actor_role: (authUser as any).role || "superadmin",
      action: "admin.addon.update",
      entity_type: "service_addon",
      entity_id: id,
      metadata: { provider_id: (addon as any).provider_id || null, type: (addon as any).type },
    });

    return NextResponse.json({
      data: {
        ...(addon as Record<string, any>),
        service_ids: associations?.map((a: any) => a.service_id) || [],
      },
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to update addon",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

/**
