import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { z } from "zod";
import { writeAuditLog } from "@/lib/audit/audit";

const addonSchema = z.object({
  name: z.string().min(1, "Name is required"),
  description: z.string().optional().nullable(),
  type: z.enum(["service", "product", "upgrade"]),
  category: z.string().optional().nullable(),
  price: z.number().min(0, "Price must be non-negative"),
  currency: z.string().length(3).default("ZAR"),
  duration_minutes: z.number().int().min(0).optional().nullable(),
  is_active: z.boolean().default(true),
  is_recommended: z.boolean().default(false),
  image_url: z.string().url().optional().nullable(),
  provider_id: z.string().uuid().optional().nullable(), // null = global addon
  service_ids: z.array(z.string().uuid()).optional().default([]), // Services this addon can be added to
  max_quantity: z.number().int().min(1).optional().nullable(),
  requires_service: z.boolean().default(false), // Can only be added with a service
  sort_order: z.number().int().default(0),
});

/**
 * GET /api/admin/addons
 * 
 * List all addons (global and provider-specific)
 */
export async function GET(request: NextRequest) {
  try {
    const { user: authUser } = await requireRoleInApi(["superadmin", "provider_owner"], request);

    const supabase = await getSupabaseServer(request);
    if (!supabase) {
      return NextResponse.json(
        { data: null, error: { message: "Server error", code: "SERVER_ERROR" } },
        { status: 500 }
      );
    }
    const { searchParams } = new URL(request.url);
    const providerId = searchParams.get("provider_id");
    const type = searchParams.get("type");
    const isActive = searchParams.get("is_active");

    // service_addons view is from offerings: use display_order, title (view has no sort_order/name)
    let query = supabase
      .from("service_addons")
      .select("*")
      .order("display_order", { ascending: true })
      .order("title", { ascending: true });

    if (providerId) {
      query = query.eq("provider_id", providerId);
    } else if (authUser.role === "provider_owner") {
      // Providers can only see their own addons; superadmin sees all
      const { data: provider } = await supabase
        .from("providers")
        .select("id")
        .eq("user_id", authUser.id)
        .single();

      if (provider) {
        query = query.eq("provider_id", (provider as any).id);
      } else {
        return NextResponse.json({
          data: [],
          error: null,
        });
      }
    }

    if (type) {
      query = query.eq("type", type);
    }

    if (isActive !== null) {
      query = query.eq("is_active", isActive === "true");
    }

    const { data: addons, error } = await query;

    if (error) {
      console.error("Error fetching addons:", error);
      return errorResponse("Failed to fetch addons", "FETCH_ERROR", 500);
    }

    // service_addons view is from offerings; use applicable_service_ids (no service_addon_associations table)
    if (addons && addons.length > 0) {
      const addonsWithServices = addons.map((addon: any) => ({
        ...addon,
        name: addon.name ?? addon.title ?? "",
        service_ids: Array.isArray(addon.applicable_service_ids) ? addon.applicable_service_ids : [],
      }));

      return successResponse(addonsWithServices);
    }

    return successResponse(addons || []);
  } catch (error) {
    console.error("Unexpected error in /api/admin/addons:", error);
    return handleApiError(error, "Failed to fetch addons");
  }
}

/**
 * POST /api/admin/addons
 * 
 * Create a new addon
 */
export async function POST(request: NextRequest) {
  try {
    const { user: authUser } = await requireRoleInApi(["superadmin", "provider_owner"], request);

    const supabase = await getSupabaseServer(request);
    if (!supabase) {
      return NextResponse.json(
        { data: null, error: { message: "Server error", code: "SERVER_ERROR" } },
        { status: 500 }
      );
    }
    const body = await request.json();

    const validationResult = addonSchema.safeParse(body);
    if (!validationResult.success) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Validation failed",
            code: "VALIDATION_ERROR",
            details: validationResult.error.issues.map((issue) => ({
              path: issue.path.join("."),
              message: issue.message,
            })),
          },
        },
        { status: 400 }
      );
    }

    // Superadmin can set provider_id = null (global addon); provider_owner must use their provider
    if (authUser.role === "provider_owner") {
      if (validationResult.data.provider_id) {
        const { data: provider } = await supabase
          .from("providers")
          .select("id")
          .eq("id", validationResult.data.provider_id)
          .eq("user_id", authUser.id)
          .single();

        if (!provider) {
          return NextResponse.json(
            {
              data: null,
              error: {
                message: "Provider not found or access denied",
                code: "FORBIDDEN",
              },
            },
            { status: 403 }
          );
        }
      } else {
        const { data: provider } = await supabase
          .from("providers")
          .select("id")
          .eq("user_id", authUser.id)
          .single();

        if (provider) {
          validationResult.data.provider_id = (provider as any).id;
        } else {
          return NextResponse.json(
            {
              data: null,
              error: {
                message: "Provider not found",
                code: "NOT_FOUND",
              },
            },
            { status: 404 }
          );
        }
      }
    }

    const { service_ids, ...addonData } = validationResult.data;

    const { data: addon, error } = await (supabase
      .from("service_addons") as any)
      .insert({
        ...addonData,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .select()
      .single();

    if (error || !addon) {
      console.error("Error creating addon:", error);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to create addon",
            code: "CREATE_ERROR",
          },
        },
        { status: 500 }
      );
    }

    // Create service associations
    if (service_ids && service_ids.length > 0) {
      const associations = service_ids.map((serviceId: string) => ({
        addon_id: (addon as any).id,
        service_id: serviceId,
        created_at: new Date().toISOString(),
      }));

      await (supabase as any).from("service_addon_associations").insert(associations);
    }

    await writeAuditLog({
      actor_user_id: authUser.id,
      actor_role: (authUser as any).role || "superadmin",
      action: "admin.addon.create",
      entity_type: "service_addon",
      entity_id: (addon as any).id,
      metadata: { provider_id: (addon as any).provider_id || null, type: (addon as any).type, price: (addon as any).price, currency: (addon as any).currency },
    });

    return NextResponse.json({
      data: { ...(addon as Record<string, any>), service_ids },
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/admin/addons:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to create addon",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";

/**
 * GET /api/admin/analytics/previous-software
 * 
 * Get analytics on previous salon software used by providers
 * Superadmin only - provides competitor analysis data
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);
    if (!supabase) {
      return handleApiError(new Error("Server error"), "Database connection failed");
    }

    // Get all providers with previous software data
    const { data: providers, error } = await supabase
      .from("providers")
      .select("id, business_name, previous_software, previous_software_other, created_at, status")
      .not("previous_software", "is", null)
      .order("created_at", { ascending: false });

    if (error) {
      throw error;
    }

    // Aggregate data
    const softwareCounts: Record<string, number> = {};
    const softwareDetails: Record<string, any[]> = {};
    const totalWithSoftware = providers?.length || 0;

    (providers as any[])?.forEach((provider: any) => {
      const software = provider.previous_software === "other" 
        ? provider.previous_software_other || "Other"
        : provider.previous_software;

      if (!softwareCounts[software]) {
        softwareCounts[software] = 0;
        softwareDetails[software] = [];
      }

      softwareCounts[software]++;
      softwareDetails[software].push({
        id: provider.id,
        business_name: provider.business_name,
        created_at: provider.created_at,
        status: provider.status,
        custom_name: provider.previous_software === "other" ? provider.previous_software_other : null,
      });
    });

    // Get total providers for percentage calculation
    const { count: totalProviders } = await supabase
      .from("providers")
      .select("*", { count: "exact", head: true });

    // Sort by count (descending)
    const sortedSoftware = Object.entries(softwareCounts)
      .map(([name, count]) => ({
        name,
        count,
        percentage: totalProviders ? ((count / totalProviders) * 100).toFixed(1) : "0",
        providers: softwareDetails[name],
      }))
      .sort((a, b) => b.count - a.count);

    return successResponse({
      summary: {
        total_providers: totalProviders || 0,
        providers_with_previous_software: totalWithSoftware,
        providers_without_previous_software: (totalProviders || 0) - totalWithSoftware,
        response_rate: totalProviders 
          ? ((totalWithSoftware / totalProviders) * 100).toFixed(1) 
          : "0",
      },
      by_software: sortedSoftware,
      raw_data: providers,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch previous software analytics");
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseServer } from '@/lib/supabase/server';
import { requireRoleInApi, successResponse, handleApiError } from '@/lib/supabase/api-helpers';

export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = await getSupabaseServer(request);
    
    const { searchParams } = new URL(request.url);
    const period = searchParams.get('period') || '30d'; // 7d, 30d, 90d, 1y

    const now = new Date();
    let startDate: Date;
    
    switch (period) {
      case '7d':
        startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        break;
      case '30d':
        startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        break;
      case '90d':
        startDate = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
        break;
      case '1y':
        startDate = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000);
        break;
      default:
        startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
    }

    // Get daily time series data (optional extra filter, e.g. for users by role)
    const getDailyTimeSeries = async (
      table: string,
      dateField: string = 'created_at',
      extraFilter?: { column: string; value: string }
    ) => {
      let query = supabase
        .from(table)
        .select(dateField)
        .gte(dateField, startDate.toISOString())
        .order(dateField, { ascending: true });
      if (extraFilter) {
        query = query.eq(extraFilter.column, extraFilter.value);
      }
      const { data, error } = await query;

      if (error) {
        console.error(`Error fetching ${table}:`, error);
        return [];
      }

      // Group by date
      const grouped: Record<string, number> = {};
      (data || []).forEach((item: any) => {
        const date = new Date(item[dateField]).toISOString().split('T')[0];
        grouped[date] = (grouped[date] || 0) + 1;
      });

      // Fill in missing dates with 0
      const result: Array<{ date: string; count: number }> = [];
      const current = new Date(startDate);
      while (current <= now) {
        const dateStr = current.toISOString().split('T')[0];
        result.push({
          date: dateStr,
          count: grouped[dateStr] || 0,
        });
        current.setDate(current.getDate() + 1);
      }

      return result;
    };

    // Get revenue time series
    const getRevenueTimeSeries = async () => {
      const { data, error } = await supabase
        .from('finance_transactions')
        .select('created_at, net, transaction_type')
        .gte('created_at', startDate.toISOString())
        .in('transaction_type', ['payment', 'additional_charge_payment', 'refund'])
        .order('created_at', { ascending: true });

      if (error) {
        console.error('Error fetching revenue:', error);
        return [];
      }

      const grouped: Record<string, number> = {};
      (data || []).forEach((item: any) => {
        const date = new Date(item.created_at).toISOString().split('T')[0];
        const amount = item.transaction_type === 'refund' ? -Math.abs(item.net || 0) : Math.abs(item.net || 0);
        grouped[date] = (grouped[date] || 0) + amount;
      });

      const result: Array<{ date: string; revenue: number }> = [];
      const current = new Date(startDate);
      while (current <= now) {
        const dateStr = current.toISOString().split('T')[0];
        result.push({
          date: dateStr,
          revenue: grouped[dateStr] || 0,
        });
        current.setDate(current.getDate() + 1);
      }

      return result;
    };

    // Get provider status breakdown (all providers by current status)
    const getProviderStatusBreakdown = async () => {
      const { data, error } = await supabase
        .from('providers')
        .select('status');

      if (error) {
        console.error('Error fetching provider status:', error);
        return { active: 0, pending: 0, suspended: 0, rejected: 0 };
      }

      const breakdown = {
        active: 0,
        pending: 0,
        suspended: 0,
        rejected: 0,
      };

      (data || []).forEach((p: any) => {
        if (p.status === 'active') breakdown.active++;
        else if (p.status === 'pending_approval') breakdown.pending++;
        else if (p.status === 'suspended') breakdown.suspended++;
        else if (p.status === 'rejected') breakdown.rejected++;
      });

      return breakdown;
    };

    // Get booking status breakdown
    const getBookingStatusBreakdown = async () => {
      const { data, error } = await supabase
        .from('bookings')
        .select('status')
        .gte('created_at', startDate.toISOString());

      if (error) {
        console.error('Error fetching booking status:', error);
        return { confirmed: 0, completed: 0, cancelled: 0, no_show: 0 };
      }

      const breakdown = {
        confirmed: 0,
        completed: 0,
        cancelled: 0,
        no_show: 0,
      };

      (data || []).forEach((b: any) => {
        if (b.status === 'confirmed') breakdown.confirmed++;
        else if (b.status === 'completed') breakdown.completed++;
        else if (b.status === 'cancelled') breakdown.cancelled++;
        else if (b.status === 'no_show') breakdown.no_show++;
      });

      return breakdown;
    };

    // Get top providers by revenue (provider earnings: provider_earnings, travel_fee, tip)
    const getTopProviders = async () => {
      const { data, error } = await supabase
        .from('finance_transactions')
        .select('provider_id, net, amount')
        .gte('created_at', startDate.toISOString())
        .in('transaction_type', ['provider_earnings', 'travel_fee', 'tip']);

      if (error) {
        console.error('Error fetching top providers:', error);
        return [];
      }

      const providerRevenue: Record<string, number> = {};
      (data || []).forEach((t: any) => {
        if (t.provider_id) {
          const amt = Number(t.net ?? t.amount ?? 0);
          providerRevenue[t.provider_id] = (providerRevenue[t.provider_id] || 0) + amt;
        }
      });

      const topProviders = Object.entries(providerRevenue)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 10)
        .map(([providerId, revenue]) => ({ provider_id: providerId, revenue }));

      // Fetch provider names
      if (topProviders.length > 0) {
        const providerIds = topProviders.map(p => p.provider_id);
        const { data: providers } = await supabase
          .from('providers')
          .select('id, business_name')
          .in('id', providerIds);

        const providerMap = new Map((providers || []).map((p: any) => [p.id, p.business_name]));

        return topProviders.map(p => ({
          provider_id: p.provider_id,
          business_name: providerMap.get(p.provider_id) || 'Unknown',
          revenue: p.revenue,
        }));
      }

      return [];
    };

    // Run all queries in parallel (users = customers only for growth chart)
    const [
      usersTimeSeries,
      providersTimeSeries,
      bookingsTimeSeries,
      revenueTimeSeries,
      providerStatusBreakdown,
      bookingStatusBreakdown,
      topProviders,
    ] = await Promise.all([
      getDailyTimeSeries('users', 'created_at', { column: 'role', value: 'customer' }),
      getDailyTimeSeries('providers', 'created_at'),
      getDailyTimeSeries('bookings', 'created_at'),
      getRevenueTimeSeries(),
      getProviderStatusBreakdown(),
      getBookingStatusBreakdown(),
      getTopProviders(),
    ]);

    return successResponse({
      period,
      timeSeries: {
        users: usersTimeSeries,
        providers: providersTimeSeries,
        bookings: bookingsTimeSeries,
        revenue: revenueTimeSeries,
      },
      breakdowns: {
        providerStatus: providerStatusBreakdown,
        bookingStatus: bookingStatusBreakdown,
      },
      topProviders,
    });
  } catch (error) {
    return handleApiError(error, 'Failed to load analytics');
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole } from "@/lib/supabase/auth-server";
import { writeAuditLog } from "@/lib/audit/audit";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    await requireRole(["superadmin"]);
    const supabase = await getSupabaseServer(request);

    const { data, error } = await supabase
      .from("api_keys")
      .select("*")
      .eq("id", id)
      .single();

    if (error) throw error;

    // Get usage stats
    const { data: usageStats } = await supabase
      .from("api_key_usage_logs")
      .select("endpoint, method, status_code, response_time_ms, created_at")
      .eq("api_key_id", id)
      .order("created_at", { ascending: false })
      .limit(100);

    // Calculate usage summary
    const last24Hours = new Date();
    last24Hours.setHours(last24Hours.getHours() - 24);

    const { count: recentUsage } = await supabase
      .from("api_key_usage_logs")
      .select("*", { count: "exact", head: true })
      .eq("api_key_id", id)
      .gte("created_at", last24Hours.toISOString());

    return NextResponse.json({
      key: {
        ...data,
        key_hash: undefined, // Don't return hash
      },
      usage: {
        recent: usageStats || [],
        last_24_hours: recentUsage || 0,
      },
    });
  } catch (error: any) {
    console.error("Error fetching API key:", error);
    return NextResponse.json(
      { error: error.message || "Failed to fetch API key" },
      { status: 500 }
    );
  }
}

