import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole } from "@/lib/supabase/auth-server";
import { writeAuditLog } from "@/lib/audit/audit";
import crypto from "crypto";

export async function GET(request: NextRequest) {
  try {
    await requireRole(["superadmin"]);
    const supabase = await getSupabaseServer(request);

    const { searchParams } = new URL(request.url);
    const isActive = searchParams.get("is_active");

    let query = supabase
      .from("api_keys")
      .select("*")
      .order("created_at", { ascending: false });

    if (isActive !== null) {
      query = query.eq("is_active", isActive === "true");
    }

    const { data, error } = await query;

    if (error) throw error;

    // Don't return full key hash, just prefix
    const safeData = (data || []).map((key: any) => ({
      ...key,
      key_hash: undefined, // Remove hash from response
    }));

    return NextResponse.json({ keys: safeData });
  } catch (error: any) {
    console.error("Error fetching API keys:", error);
    return NextResponse.json(
      { error: error.message || "Failed to fetch API keys" },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRole(["superadmin"]);
    const supabase = await getSupabaseServer(request);

    const body = await request.json();
    const {
      name,
      permissions,
      rate_limit_per_minute,
      rate_limit_per_hour,
      rate_limit_per_day,
      expires_at,
    } = body;

    if (!name) {
      return NextResponse.json(
        { error: "Name is required" },
        { status: 400 }
      );
    }

    // Generate API key
    const apiKey = `bk_${crypto.randomBytes(32).toString("hex")}`;
    const keyHash = crypto.createHash("sha256").update(apiKey).digest("hex");
    const keyPrefix = apiKey.substring(0, 12) + "...";

    const { data, error } = await supabase
      .from("api_keys")
      .insert({
        name,
        key_hash: keyHash,
        key_prefix: keyPrefix,
        permissions: permissions || [],
        rate_limit_per_minute: rate_limit_per_minute || 60,
        rate_limit_per_hour: rate_limit_per_hour || 1000,
        rate_limit_per_day: rate_limit_per_day || 10000,
        expires_at: expires_at || null,
        created_by: user.id,
      })
      .select()
      .single();

    if (error) throw error;

    await writeAuditLog({
      actor_user_id: user.id,
      actor_role: "superadmin",
      action: "admin.api_key.create",
      entity_type: "api_key",
      entity_id: data.id,
      metadata: { name },
    });

    // Return the actual key only once (for display)
    return NextResponse.json({
      key: {
        ...data,
        key_hash: undefined,
        api_key: apiKey, // Only returned on creation
      },
    });
  } catch (error: any) {
    console.error("Error creating API key:", error);
    return NextResponse.json(
      { error: error.message || "Failed to create API key" },
      { status: 500 }
    );
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseServer } from '@/lib/supabase/server';
import { requireRoleInApi, successResponse, handleApiError } from '@/lib/supabase/api-helpers';
import { z } from 'zod';

const versionSettingsSchema = z.object({
  ios: z.object({
    min_version: z.string(),
    latest_version: z.string(),
    force_update: z.boolean().optional(),
    update_url: z.string().url(),
  }),
  android: z.object({
    min_version: z.string(),
    latest_version: z.string(),
    force_update: z.boolean().optional(),
    update_url: z.string().url(),
  }),
});

/**
 * GET /api/admin/app-version
 * 
 * Get app version settings
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = await getSupabaseServer(request);

    const { data: versionSettings, error } = await (supabase
      .from('app_version_settings') as any)
      .select('*');

    if (error) {
      // Return default structure if table doesn't exist yet
      return successResponse({
        ios: {
          min_version: '1.0.0',
          latest_version: '1.0.0',
          force_update: false,
          update_url: 'https://apps.apple.com/app/beautonomi',
        },
        android: {
          min_version: '1.0.0',
          latest_version: '1.0.0',
          force_update: false,
          update_url: 'https://play.google.com/store/apps/details?id=com.beautonomi',
        },
      });
    }

    // Transform data to match expected structure
    const iosSettings = (versionSettings as any[])?.find((s: any) => s.platform === 'ios') || {
      platform: 'ios',
      min_version: '1.0.0',
      latest_version: '1.0.0',
      force_update: false,
      update_url: 'https://apps.apple.com/app/beautonomi',
    };

    const androidSettings = (versionSettings as any[])?.find((s: any) => s.platform === 'android') || {
      platform: 'android',
      min_version: '1.0.0',
      latest_version: '1.0.0',
      force_update: false,
      update_url: 'https://play.google.com/store/apps/details?id=com.beautonomi',
    };

    return successResponse({
      ios: {
        min_version: iosSettings.min_version,
        latest_version: iosSettings.latest_version,
        force_update: iosSettings.force_update || false,
        update_url: iosSettings.update_url,
      },
      android: {
        min_version: androidSettings.min_version,
        latest_version: androidSettings.latest_version,
        force_update: androidSettings.force_update || false,
        update_url: androidSettings.update_url,
      },
    });
  } catch (error) {
    return handleApiError(error, 'Failed to fetch app version settings');
  }
}

/**
 * PATCH /api/admin/app-version
 * 
 * Update app version settings
 */
export async function PATCH(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    const { ios, android } = versionSettingsSchema.parse(body);

    // Upsert iOS settings
    const { error: iosError } = await (supabase
      .from('app_version_settings') as any)
      .upsert(
        {
          platform: 'ios',
          min_version: ios.min_version,
          latest_version: ios.latest_version,
          force_update: ios.force_update || false,
          update_url: ios.update_url,
          updated_at: new Date().toISOString(),
        },
        {
          onConflict: 'platform',
        }
      );

    if (iosError) {
      throw iosError;
    }

    // Upsert Android settings
    const { error: androidError } = await (supabase
      .from('app_version_settings') as any)
      .upsert(
        {
          platform: 'android',
          min_version: android.min_version,
          latest_version: android.latest_version,
          force_update: android.force_update || false,
          update_url: android.update_url,
          updated_at: new Date().toISOString(),
        },
        {
          onConflict: 'platform',
        }
      );

    if (androidError) {
      throw androidError;
    }

    // Return updated settings
    const { data: updatedSettings } = await (supabase
      .from('app_version_settings') as any)
      .select('*');

    const updatedIos = (updatedSettings as any[])?.find((s: any) => s.platform === 'ios') || ios;
    const updatedAndroid = (updatedSettings as any[])?.find((s: any) => s.platform === 'android') || android;

    return successResponse({
      ios: {
        min_version: updatedIos.min_version,
        latest_version: updatedIos.latest_version,
        force_update: updatedIos.force_update || false,
        update_url: updatedIos.update_url,
      },
      android: {
        min_version: updatedAndroid.min_version,
        latest_version: updatedAndroid.latest_version,
        force_update: updatedAndroid.force_update || false,
        update_url: updatedAndroid.update_url,
      },
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        new Error(error.issues.map(e => e.message).join(', ')),
        'Validation failed'
      );
    }
    return handleApiError(error, 'Failed to update app version settings');
  }
}

import { NextResponse } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import {
  requireRoleInApi,
  handleApiError,
  getPaginationParams,
} from "@/lib/supabase/api-helpers";

/**
 * GET /api/admin/audit-logs
 *
 * Get audit logs with filters and search. Uses admin client so the actor join
 * to users returns data (RLS would otherwise hide other users from the actor column).
 */
export async function GET(request: Request) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = getSupabaseAdmin();

    // Validate request URL
    if (!request.url) {
      return handleApiError(new Error("Invalid request URL"), "Invalid request URL");
    }

    let url: URL;
    try {
      url = new URL(request.url);
    } catch (error) {
      return handleApiError(error, "Invalid URL");
    }

    const { searchParams } = url;

    const search = searchParams.get("search");
    const action = searchParams.get("action");
    const entityType = searchParams.get("entity_type");
    const actorUserId = searchParams.get("actor_user_id");
    const startDate = searchParams.get("start_date");
    const endDate = searchParams.get("end_date");
    const { page, limit, offset } = getPaginationParams(request);

    let query = supabase
      .from("audit_logs")
      .select(`
        *,
        actor:users!audit_logs_actor_user_id_fkey(id, full_name, email)
      `, { count: "exact" });

    // Apply filters
    if (search) {
      const searchPattern = `%${search}%`;
      query = query.or(
        `action.ilike.${searchPattern},entity_type.ilike.${searchPattern},actor_role.ilike.${searchPattern}`
      );
    }
    if (action) {
      query = query.eq("action", action);
    }
    if (entityType) {
      query = query.eq("entity_type", entityType);
    }
    if (actorUserId) {
      query = query.eq("actor_user_id", actorUserId);
    }
    if (startDate) {
      query = query.gte("created_at", startDate);
    }
    if (endDate) {
      query = query.lte("created_at", endDate);
    }

    // Apply pagination
    const { data: logs, error, count } = await query
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (error) {
      return handleApiError(error, "Failed to fetch audit logs");
    }

    // Transform logs to include actor information
    const transformedLogs = (logs || []).map((log: any) => ({
      ...log,
      actor: log.actor ? {
        id: log.actor.id,
        full_name: log.actor.full_name,
        email: log.actor.email,
      } : null,
    }));

    // Return response in format expected by frontend
    return NextResponse.json({
      data: transformedLogs,
      error: null,
      meta: {
        page,
        limit,
        total: count || 0,
        has_more: (count || 0) > page * limit,
      },
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch audit logs");
  }
}

import { NextRequest } from "next/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { getSupabaseAdmin } from "@/lib/supabase/admin";

/**
 * GET /api/admin/automations
 * 
 * Get all automations across all providers (admin view)
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);

    const supabaseAdmin = getSupabaseAdmin();
    const searchParams = request.nextUrl.searchParams;
    const search = searchParams.get("search") || "";
    const status = searchParams.get("status") || "all";
    const type = searchParams.get("type") || "all";

    // Build query
    let query = supabaseAdmin
      .from("marketing_automations")
      .select(`
        *,
        provider:providers!marketing_automations_provider_id_fkey(
          id,
          business_name
        )
      `)
      .eq("is_template", false)
      .order("created_at", { ascending: false })
      .limit(1000);

    // Apply filters
    if (status === "active") {
      query = query.eq("is_active", true);
    } else if (status === "inactive") {
      query = query.eq("is_active", false);
    }

    if (type !== "all") {
      // Map UI types to trigger types
      const triggerTypeMap: Record<string, string[]> = {
        reminder: ["appointment_reminder"],
        update: ["appointment_rescheduled", "appointment_no_show"],
        booking: [
          "booking_completed",
          "client_inactive",
          "new_lead",
          "package_expiring",
          "seasonal_promotion",
        ],
        milestone: [
          "client_birthday",
          "client_anniversary",
          "visit_milestone",
          "referral_received",
          "holiday",
        ],
      };

      const triggerTypes = triggerTypeMap[type] || [];
      if (triggerTypes.length > 0) {
        query = query.in("trigger_type", triggerTypes);
      }
    }

    const { data: automations, error } = await query;

    if (error) {
      throw error;
    }

    // Get execution counts and last executed dates
    const automationIds = automations?.map((a) => a.id) || [];
    const { data: executions } = await supabaseAdmin
      .from("automation_executions")
      .select("automation_id, executed_at")
      .in("automation_id", automationIds)
      .order("executed_at", { ascending: false });

    // Aggregate execution data
    const executionMap = new Map<string, { count: number; lastExecuted: string | null }>();
    executions?.forEach((exec) => {
      const existing = executionMap.get(exec.automation_id) || {
        count: 0,
        lastExecuted: null,
      };
      executionMap.set(exec.automation_id, {
        count: existing.count + 1,
        lastExecuted: existing.lastExecuted || exec.executed_at,
      });
    });

    // Format response
    const formatted = (automations || [])
      .filter((auto) => {
        if (!search) return true;
        const searchLower = search.toLowerCase();
        return (
          auto.name?.toLowerCase().includes(searchLower) ||
          (auto.provider as any)?.business_name?.toLowerCase().includes(searchLower)
        );
      })
      .map((auto) => {
        const execData = executionMap.get(auto.id) || {
          count: 0,
          lastExecuted: null,
        };
        return {
          id: auto.id,
          name: auto.name,
          provider_id: auto.provider_id,
          provider_name: (auto.provider as any)?.business_name || "Unknown",
          trigger_type: auto.trigger_type,
          action_type: auto.action_type,
          is_active: auto.is_active,
          is_template: auto.is_template,
          created_at: auto.created_at,
          execution_count: execData.count,
          last_executed_at: execData.lastExecuted,
        };
      });

    return successResponse(formatted);
  } catch (error) {
    return handleApiError(error, "Failed to fetch automations");
  }
}

import { NextRequest } from "next/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { getSupabaseAdmin } from "@/lib/supabase/admin";

/**
 * GET /api/admin/automations/stats
 * 
 * Get automation statistics for admin dashboard
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);

    const supabaseAdmin = getSupabaseAdmin();

    // Get total automations
    const { count: totalCount } = await supabaseAdmin
      .from("marketing_automations")
      .select("*", { count: "exact", head: true })
      .eq("is_template", false);

    // Get active automations
    const { count: activeCount } = await supabaseAdmin
      .from("marketing_automations")
      .select("*", { count: "exact", head: true })
      .eq("is_active", true)
      .eq("is_template", false);

    // Get total executions
    const { count: totalExecutions } = await supabaseAdmin
      .from("automation_executions")
      .select("*", { count: "exact", head: true });

    // Get executions today
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const { count: executionsToday } = await supabaseAdmin
      .from("automation_executions")
      .select("*", { count: "exact", head: true })
      .gte("executed_at", today.toISOString());

    // Get executions this month
    const monthStart = new Date(today.getFullYear(), today.getMonth(), 1);
    const { count: executionsThisMonth } = await supabaseAdmin
      .from("automation_executions")
      .select("*", { count: "exact", head: true })
      .gte("executed_at", monthStart.toISOString());

    // Get providers with automations
    const { data: providersWithAutomations } = await supabaseAdmin
      .from("marketing_automations")
      .select("provider_id")
      .eq("is_template", false)
      .not("provider_id", "is", null);

    const uniqueProviders = new Set(
      providersWithAutomations?.map((p) => p.provider_id) || []
    ).size;

    // Calculate revenue from automation-enabled subscriptions
    // This is an estimate based on providers who have automations and their subscription plans
    const { data: providerSubscriptions } = await supabaseAdmin
      .from("provider_subscriptions")
      .select(`
        provider_id,
        plan:subscription_plans(
          id,
          name,
          price_monthly,
          features
        )
      `)
      .eq("status", "active")
      .gte("expires_at", new Date().toISOString());

    let revenueFromAutomations = 0;
    const providersWithActiveAutomations = new Set(
      providersWithAutomations?.map((p) => p.provider_id) || []
    );

    providerSubscriptions?.forEach((sub: any) => {
      if (
        providersWithActiveAutomations.has(sub.provider_id) &&
        sub.plan?.features?.marketing_automations?.enabled
      ) {
        revenueFromAutomations += sub.plan.price_monthly || 0;
      }
    });

    // Calculate average automations per provider
    const avgAutomationsPerProvider =
      uniqueProviders > 0
        ? (totalCount || 0) / uniqueProviders
        : 0;

    return successResponse({
      total_automations: totalCount || 0,
      active_automations: activeCount || 0,
      total_executions: totalExecutions || 0,
      executions_today: executionsToday || 0,
      executions_this_month: executionsThisMonth || 0,
      providers_with_automations: uniqueProviders,
      revenue_from_automations: revenueFromAutomations,
      avg_automations_per_provider: avgAutomationsPerProvider,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch automation statistics");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";

/**
 * POST /api/admin/bookings/[id]/cancel
 *
 * Cancel a booking. Superadmin only. Audit logged.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRoleInApi(["superadmin"], request);
    if (!auth) throw new Error("Authentication required");
    const { id } = await params;
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    // Verify booking exists
    const { data: booking } = await supabase
      .from("bookings")
      .select("id, status, customer_id, booking_number")
      .eq("id", id)
      .single();

    if (!booking) {
      return notFoundResponse("Booking not found");
    }

    if ((booking as any).status === "cancelled") {
      return errorResponse("Booking is already cancelled", "INVALID_STATE", 400);
    }

    // Update booking status
    const { data: updatedBooking, error: updateError } = await supabase
      .from("bookings")
      .update({
        status: "cancelled",
        updated_at: new Date().toISOString(),
        cancellation_reason: body.reason || null,
        cancelled_at: new Date().toISOString(),
      })
      .eq("id", id)
      .select()
      .single();

    if (updateError || !updatedBooking) {
      return handleApiError(updateError, "Failed to cancel booking");
    }

    // Notify customer
    try {
      const { sendToUser } = await import("@/lib/notifications/onesignal");
      await sendToUser((booking as any).customer_id, {
        title: "Booking Cancelled",
        message: `Your booking ${(booking as any).booking_number} has been cancelled.`,
        data: {
          type: "booking_cancelled",
          booking_id: id,
        },
        url: `/account-settings/bookings/${id}`,
      });
    } catch (notifError) {
      console.error("Error sending notification:", notifError);
    }

    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as { role?: string })?.role ?? "superadmin",
      action: "admin.booking.cancel",
      entity_type: "booking",
      entity_id: id,
      metadata: { reason: body.reason ?? null, booking_number: (booking as any).booking_number },
    });

    return successResponse(updatedBooking);
  } catch (error) {
    return handleApiError(error, "Failed to cancel booking");
  }
}

import { NextResponse } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRole, unauthorizedResponse } from "@/lib/auth/requireRole";
import { z } from "zod";
import { writeAuditLog } from "@/lib/audit/audit";

const resolveDisputeSchema = z.object({
  resolution: z.enum(["refund_full", "refund_partial", "deny"]),
  refund_amount: z.number().min(0).optional(),
  notes: z.string().optional().nullable(),
});

/**
 * POST /api/admin/bookings/[id]/dispute/resolve
 * 
 * Resolve a booking dispute
 */
export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const { id } = await params;
    const supabase = getSupabaseAdmin();
    const body = await request.json();

    // Validate request body
    const validationResult = resolveDisputeSchema.safeParse(body);
    if (!validationResult.success) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Validation failed",
            code: "VALIDATION_ERROR",
            details: validationResult.error.issues.map((issue) => ({
              path: issue.path.join("."),
              message: issue.message,
            })),
          },
        },
        { status: 400 }
      );
    }

    // Get dispute
    const { data: dispute } = await supabase
      .from("booking_disputes")
      .select("*")
      .eq("booking_id", id)
      .eq("status", "open")
      .single();

    if (!dispute) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "No open dispute found for this booking",
            code: "NO_DISPUTE",
          },
        },
        { status: 404 }
      );
    }

    // Get booking
    const { data: booking } = await supabase
      .from("bookings")
      .select("*")
      .eq("id", id)
      .single();

    if (!booking) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Booking not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    const { resolution, refund_amount, notes } = validationResult.data;
    const bookingData = booking as any;

    // Handle refunds: always credit customer wallet (no Paystack call)
    if (resolution === "refund_full" || resolution === "refund_partial") {
      const refundAmt =
        resolution === "refund_full"
          ? bookingData.total_amount
          : refund_amount || 0;

      if (refundAmt <= 0 || refundAmt > bookingData.total_amount) {
        return NextResponse.json(
          {
            data: null,
            error: {
              message: "Refund amount must be positive and cannot exceed booking total",
              code: "INVALID_REFUND_AMOUNT",
            },
          },
          { status: 400 }
        );
      }

      // Credit customer wallet
      const { error: walletError } = await (supabase.rpc as any)("wallet_credit_admin", {
        p_user_id: bookingData.customer_id,
        p_amount: refundAmt,
        p_currency: bookingData.currency || "ZAR",
        p_description: `Dispute resolution refund for booking ${bookingData.booking_number}`,
        p_reference_id: (dispute as any).id,
        p_reference_type: "booking_dispute",
      });

      if (walletError) {
        console.error("Wallet credit failed:", walletError);
        return NextResponse.json(
          {
            data: null,
            error: {
              message: "Failed to credit customer wallet",
              code: "WALLET_ERROR",
            },
          },
          { status: 500 }
        );
      }

      const refundReference = `dispute_refund_${(dispute as any).id}_${Date.now()}`;
      const newBookingPaymentStatus = refundAmt >= bookingData.total_amount ? "refunded" : "partially_refunded";

      // Optional: mark any success payment_transaction for this booking as refunded (ledger consistency)
      const { data: tx } = await (supabase
        .from("payment_transactions") as any)
        .select("id, amount")
        .eq("booking_id", id)
        .eq("status", "success")
        .neq("transaction_type", "refund")
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (tx) {
        const txData = tx as any;
        const isFullRefund = refundAmt >= Number(txData.amount || 0);
        await (supabase
          .from("payment_transactions") as any)
          .update({
            status: isFullRefund ? "refunded" : "partially_refunded",
            refund_amount: refundAmt,
            refund_reference: refundReference,
            refund_reason: "booking_dispute",
            refunded_at: new Date().toISOString(),
            refunded_by: auth.user.id,
          })
          .eq("id", txData.id);
      }

      // booking_refunds so update_booking_payment_status trigger keeps totals in sync
      await (supabase.from("booking_refunds") as any).insert({
        booking_id: id,
        amount: refundAmt,
        reason: "Dispute resolution",
        refund_method: "store_credit",
        status: "completed",
        created_by: auth.user.id,
      });

      await (supabase
        .from("bookings") as any)
        .update({ payment_status: newBookingPaymentStatus })
        .eq("id", id);
    }

    // Update dispute
    const { data: updatedDispute, error: disputeError } = await (supabase
      .from("booking_disputes") as any)
      .update({
        status: "resolved",
        resolution,
        refund_amount: resolution.includes("refund") ? (refund_amount || bookingData.total_amount) : null,
        resolved_at: new Date().toISOString(),
        resolved_by: auth.user.id,
        notes: notes || null,
      })
      .eq("id", (dispute as any).id)
      .select()
      .single();

    if (disputeError || !updatedDispute) {
      console.error("Error resolving dispute:", disputeError);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to resolve dispute",
            code: "UPDATE_ERROR",
          },
        },
        { status: 500 }
      );
    }

    // Update booking status
    const newBookingStatus =
      resolution === "refund_full" ? "cancelled" : bookingData.status;
    await (supabase
      .from("bookings") as any)
      .update({ status: newBookingStatus })
      .eq("id", id);

    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as any).role || "superadmin",
      action: "admin.dispute.resolve",
      entity_type: "booking",
      entity_id: id,
      metadata: {
        dispute_id: (dispute as any).id,
        resolution,
        refund_amount: resolution.includes("refund") ? (refund_amount || bookingData.total_amount) : null,
        notes: notes || null,
      },
    });

    // Send OneSignal notifications
    try {
      const { sendToUser } = await import("@/lib/notifications/onesignal");
      
      const resolutionMessage =
        resolution === "refund_full"
          ? "Your dispute has been resolved with a full refund. The amount has been added to your walletΓÇöuse it for your next booking or request a payout."
          : resolution === "refund_partial"
          ? `Your dispute has been resolved with a partial refund of ${bookingData.currency || "ZAR"} ${refund_amount ?? 0}. The amount has been added to your wallet.`
          : "Your dispute has been reviewed and the decision is in favor of the provider.";

      // Notify customer
      await sendToUser(bookingData.customer_id, {
        title: "Dispute Resolved",
        message: resolutionMessage,
        data: {
          type: "dispute_resolved",
          booking_id: id,
          resolution,
        },
        url: `/account-settings/bookings/${id}`,
      });

      // Notify provider
      const { data: providerRow } = await supabase
        .from("providers")
        .select("user_id")
        .eq("id", bookingData.provider_id)
        .single();

      const providerUserId = (providerRow as any)?.user_id;
      if (providerUserId) {
        await sendToUser(providerUserId, {
          title: "Dispute Resolved",
          message: `A dispute for booking ${bookingData.booking_number} has been resolved.`,
          data: {
            type: "dispute_resolved",
            booking_id: id,
            resolution,
          },
          url: `/provider/bookings/${id}`,
        });
      }
    } catch (notifError) {
      console.error("Error sending notifications:", notifError);
      // Don't fail the request if notifications fail
    }

    return NextResponse.json({
      data: updatedDispute,
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/admin/bookings/[id]/dispute/resolve:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to resolve dispute",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole, unauthorizedResponse } from "@/lib/auth/requireRole";
import { z } from "zod";
import { writeAuditLog } from "@/lib/audit/audit";
import { sendToUsers } from "@/lib/notifications/onesignal";

const disputeSchema = z.object({
  reason: z.string().min(1, "Reason is required"),
  description: z.string().optional().nullable(),
  opened_by: z.enum(["customer", "provider"]),
});

/**
 * POST /api/admin/bookings/[id]/dispute
 * 
 * Open a dispute for a booking
 */
export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const { id } = await params;
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    // Validate request body
    const validationResult = disputeSchema.safeParse(body);
    if (!validationResult.success) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Validation failed",
            code: "VALIDATION_ERROR",
            details: validationResult.error.issues.map((issue) => ({
              path: issue.path.join("."),
              message: issue.message,
            })),
          },
        },
        { status: 400 }
      );
    }

    // Verify booking exists
    const { data: booking } = await supabase
      .from("bookings")
      .select("id, customer_id, provider_id")
      .eq("id", id)
      .single();

    if (!booking) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Booking not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    // Check if dispute already exists
    const { data: existingDispute } = await supabase
      .from("booking_disputes")
      .select("id")
      .eq("booking_id", id)
      .eq("status", "open")
      .single();

    if (existingDispute) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "An open dispute already exists for this booking",
            code: "DISPUTE_EXISTS",
          },
        },
        { status: 409 }
      );
    }

    const { reason, description, opened_by } = validationResult.data;

    // Create dispute
    const { data: dispute, error } = await (supabase
      .from("booking_disputes") as any)
      .insert({
        booking_id: id,
        reason,
        description: description || null,
        opened_by,
        status: "open",
        opened_at: new Date().toISOString(),
      })
      .select()
      .single();

    if (error || !dispute) {
      console.error("Error creating dispute:", error);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to create dispute",
            code: "CREATE_ERROR",
          },
        },
        { status: 500 }
      );
    }

    // NOTE: We intentionally do NOT update bookings.status here, because the booking_status enum
    // does not include a "disputed" state in this codebase. Disputes are tracked in booking_disputes.

    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as any).role || "superadmin",
      action: "admin.booking.dispute.open",
      entity_type: "booking_dispute",
      entity_id: (dispute as any).id,
      metadata: { booking_id: id, reason, opened_by },
    });

    // Notify customer + provider owner (best-effort)
    try {
      const bookingData = booking as any;
      const { data: provider } = await supabase
        .from("providers")
        .select("user_id")
        .eq("id", bookingData.provider_id)
        .single();

      const recipients = [
        bookingData.customer_id,
        (provider as any)?.user_id,
      ].filter(Boolean);

      if (recipients.length > 0) {
        await sendToUsers(recipients, {
          title: "Dispute opened",
          message: "A dispute has been opened for a booking. Our team will review and follow up.",
          data: {
            type: "booking_dispute_opened",
            bookingId: id,
            disputeId: (dispute as any).id,
          },
        });
      }
    } catch (e) {
      console.warn("Failed to send dispute opened notifications:", e);
    }

    return NextResponse.json({
      data: dispute,
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/admin/bookings/[id]/dispute:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to create dispute",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRoleInApi, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";

/**
 * POST /api/admin/bookings/[id]/refund
 *
 * Process a refund for a booking. Refunds always credit the customer's wallet
 * (use for next booking or request payout). Uses booking_refunds so
 * update_booking_payment_status trigger keeps totals in sync.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRoleInApi(["superadmin"], request);
    if (!auth) throw new Error("Authentication required");
    const { id } = await params;
    const supabase = getSupabaseAdmin();
    const body = await request.json();

    const { amount, reason } = body;

    if (!amount || amount <= 0) {
      return errorResponse("Invalid refund amount", "VALIDATION_ERROR", 400);
    }

    const { data: booking } = await supabase
      .from("bookings")
      .select("id, total_amount, total_paid, total_refunded, customer_id, booking_number, currency, payment_status")
      .eq("id", id)
      .single();

    if (!booking) {
      return notFoundResponse("Booking not found");
    }

    const b = booking as {
      total_amount: number;
      total_paid?: number;
      total_refunded?: number;
      payment_status?: string;
      customer_id: string;
      booking_number: string;
      currency?: string;
    };

    if (b.payment_status !== "paid" && b.payment_status !== "partially_paid") {
      return errorResponse("Can only refund paid or partially paid bookings", "INVALID_STATUS", 400);
    }

    const availableForRefund = (b.total_paid ?? 0) - (b.total_refunded ?? 0);
    if (amount > availableForRefund) {
      return errorResponse(
        `Refund amount exceeds available refund amount (R${availableForRefund.toFixed(2)})`,
        "VALIDATION_ERROR",
        400
      );
    }

    // 1. Credit customer wallet (refunds always go to wallet)
    const { error: walletError } = await (supabase.rpc as any)("wallet_credit_admin", {
      p_user_id: b.customer_id,
      p_amount: amount,
      p_currency: b.currency || "ZAR",
      p_description: `Refund for booking ${b.booking_number}: ${reason || "Admin refund"}`,
      p_reference_id: id,
      p_reference_type: "booking_refund",
    });

    if (walletError) {
      console.error("Wallet credit failed:", walletError);
      return errorResponse("Failed to credit customer wallet", "WALLET_ERROR", 500);
    }

    // 2. Create refund record in booking_refunds (triggers update_booking_payment_status)
    const { data: refund, error: refundError } = await supabase
      .from("booking_refunds")
      .insert({
        booking_id: id,
        amount,
        reason: reason || "Admin refund",
        refund_method: "store_credit",
        status: "completed",
        created_by: auth.user.id,
      })
      .select()
      .single();

    if (refundError || !refund) {
      return handleApiError(refundError, "Failed to create refund");
    }

    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as { role?: string }).role || "superadmin",
      action: "admin.refund.create",
      entity_type: "refund",
      entity_id: (refund as { id: string }).id,
      metadata: { booking_id: id, amount, reason, wallet_credit: true },
    });

    if (amount >= b.total_amount) {
      await supabase
        .from("bookings")
        .update({
          status: "cancelled",
          updated_at: new Date().toISOString(),
        })
        .eq("id", id);
    }

    try {
      const { sendToUser } = await import("@/lib/notifications/onesignal");
      await sendToUser(b.customer_id, {
        title: "Refund added to wallet",
        message: `A refund of ${b.currency || "ZAR"} ${amount.toFixed(2)} for booking ${b.booking_number} has been added to your wallet. Use it for your next booking or request a payout.`,
        data: { type: "refund_processed", booking_id: id, refund_id: (refund as { id: string }).id },
        url: "/account-settings/wallet",
      });
    } catch (notifError) {
      console.error("Error sending notification:", notifError);
    }

    return successResponse(refund);
  } catch (error) {
    return handleApiError(error, "Failed to process refund");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRoleInApi, successResponse, notFoundResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/admin/bookings/[id]
 *
 * Get detailed booking information. Uses admin client so superadmin always sees any booking.
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(['superadmin'], request);

    const { id } = await params;
    const supabase = getSupabaseAdmin();

    // Get booking with related data
    const { data: booking, error } = await supabase
      .from("bookings")
      .select(`
        *,
        customer:users!bookings_customer_id_fkey(id, full_name, email, phone, avatar_url),
        provider:providers!bookings_provider_id_fkey(id, business_name, slug, email, phone),
        location:provider_locations(id, name, address_line1, city, country),
        booking_services(
          id,
          offering_id,
          staff_id,
          duration_minutes,
          price,
          scheduled_start_at,
          scheduled_end_at,
          offerings:offerings!booking_services_offering_id_fkey(id, title)
        ),
        booking_products(
          id,
          product_id,
          quantity,
          unit_price,
          total_price,
          products:products!booking_products_product_id_fkey(id, name, retail_price)
        )
      `)
      .eq("id", id)
      .single();

    if (error || !booking) {
      return notFoundResponse("Booking not found");
    }

    // Get payment transaction if exists
    const { data: transaction } = await supabase
      .from("payment_transactions")
      .select("*")
      .eq("booking_id", id)
      .order("created_at", { ascending: false })
      .limit(1)
      .single();

    return successResponse({
      ...(booking as any),
      payment_transaction: transaction || null,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch booking");
  }
}

/**
 * PATCH /api/admin/bookings/[id]
 *
 * Update booking details
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const { id } = await params;
    const supabase = getSupabaseAdmin();
    const body = await request.json();

    // Verify booking exists
    const { data: booking } = await supabase
      .from("bookings")
      .select("id, status")
      .eq("id", id)
      .single();

    if (!booking) {
      return notFoundResponse("Booking not found");
    }

    // Prepare update data
    const updateData: any = {
      updated_at: new Date().toISOString(),
    };

    if (body.status !== undefined) updateData.status = body.status;
    if (body.scheduled_at !== undefined) updateData.scheduled_at = body.scheduled_at;
    if (body.location_id !== undefined) updateData.location_id = body.location_id;
    if (body.location_type !== undefined) updateData.location_type = body.location_type;
    if (body.address_line1 !== undefined) updateData.address_line1 = body.address_line1;
    if (body.address_line2 !== undefined) updateData.address_line2 = body.address_line2;
    if (body.city !== undefined) updateData.city = body.city;
    if (body.country !== undefined) updateData.country = body.country;
    if (body.total_amount !== undefined) updateData.total_amount = body.total_amount;
    if (body.notes !== undefined) updateData.notes = body.notes;

    // Update booking
    const { data: updatedBooking, error: updateError } = await supabase
      .from("bookings")
      .update(updateData)
      .eq("id", id)
      .select(`
        *,
        customer:users!bookings_customer_id_fkey(id, full_name, email, phone, avatar_url),
        provider:providers!bookings_provider_id_fkey(id, business_name, slug, email, phone),
        location:provider_locations(id, name, address_line1, city, country),
        booking_services(
          id,
          offering_id,
          staff_id,
          duration_minutes,
          price,
          scheduled_start_at,
          scheduled_end_at,
          offerings:offerings!booking_services_offering_id_fkey(id, title)
        ),
        booking_products(
          id,
          product_id,
          quantity,
          unit_price,
          total_price,
          products:products!booking_products_product_id_fkey(id, name, retail_price)
        )
      `)
      .single();

    if (updateError || !updatedBooking) {
      return handleApiError(updateError, "Failed to update booking");
    }

    // Notify customer if status changed
    if (body.status && body.status !== booking.status) {
      try {
        const { sendToUser } = await import("@/lib/notifications/onesignal");
        const { data: bookingData } = await supabase
          .from("bookings")
          .select("customer_id, booking_number")
          .eq("id", id)
          .single();

        if (bookingData) {
          await sendToUser((bookingData as any).customer_id, {
            title: "Booking Updated",
            message: `Your booking ${(bookingData as any).booking_number} has been updated.`,
            data: {
              type: "booking_updated",
              booking_id: id,
            },
            url: `/account-settings/bookings/${id}`,
          });
        }
      } catch (notifError) {
        console.error("Error sending notification:", notifError);
      }
    }

    return successResponse(updatedBooking);
  } catch (error) {
    return handleApiError(error, "Failed to update booking");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole, unauthorizedResponse } from "@/lib/auth/requireRole";
import { successResponse, errorResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";
import { z } from "zod";

const bulkActionSchema = z.object({
  booking_ids: z.array(z.string().uuid()).min(1, "At least one booking ID is required"),
  action: z.enum(["cancel", "complete", "export"]),
  reason: z.string().optional().nullable(),
});

/**
 * POST /api/admin/bookings/bulk
 * 
 * Perform bulk actions on bookings
 */
export async function POST(request: NextRequest) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    // Validate request body
    const validationResult = bulkActionSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400
      );
    }

    const { booking_ids, action, reason } = validationResult.data;

    let updateData: any = {};
    const results = { success: 0, failed: 0, errors: [] as string[] };

    switch (action) {
      case "cancel":
        updateData = { status: "cancelled" };
        break;
      case "complete":
        updateData = { status: "completed" };
        break;
      case "export":
        // Export is handled separately, just return success
        return successResponse({
          success: true,
          message: "Export functionality should use /api/admin/export/bookings",
        });
    }

    // Perform bulk update
    const { error: updateError } = await supabase
      .from("bookings")
      .update(updateData)
      .in("id", booking_ids);

    if (updateError) {
      throw updateError;
    }

    results.success = booking_ids.length;

    // Log audit trail
    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as any).role || "superadmin",
      action: `admin.bookings.bulk.${action}`,
      entity_type: "booking",
      entity_id: booking_ids.join(","),
      metadata: { booking_ids, action, reason, count: booking_ids.length },
    });

    return successResponse({
      success: true,
      results,
    });
  } catch (error) {
    return handleApiError(error, "Failed to perform bulk action");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/admin/bookings
 *
 * Get all platform bookings with filters. Uses admin client so superadmin sees all bookings.
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);

    const supabase = getSupabaseAdmin();
    const { searchParams } = new URL(request.url);

    // Get bookings without joins to avoid join issues
    let query = supabase
      .from("bookings")
      .select("*");

    // Apply filters
    const status = searchParams.get("status");
    if (status && status !== "all") {
      query = query.eq("status", status);
    }

    const date = searchParams.get("date");
    if (date) {
      const startDate = new Date(date);
      startDate.setHours(0, 0, 0, 0);
      const endDate = new Date(startDate);
      endDate.setDate(endDate.getDate() + 1);
      query = query
        .gte("scheduled_at", startDate.toISOString())
        .lt("scheduled_at", endDate.toISOString());
    }

    const { data: bookings, error } = await query
      .order("scheduled_at", { ascending: false });

    if (error) {
      console.error("Error fetching bookings:", error);
      console.error("Query details:", {
        status,
        date,
        errorMessage: error.message,
        errorCode: error.code,
        errorDetails: error.details
      });
      // Return empty array instead of throwing to avoid 500 error
      return successResponse([]);
    }

    // Handle case where no bookings are found
    if (!bookings || bookings.length === 0) {
      return successResponse([]);
    }

    // Fetch related data separately
    const customerIds = [...new Set(bookings.map((b: any) => b.customer_id).filter(Boolean))];
    const providerIds = [...new Set(bookings.map((b: any) => b.provider_id).filter(Boolean))];
    const locationIds = [...new Set(bookings.map((b: any) => b.location_id).filter(Boolean))];

    // Fetch customers
    let customersData: any[] = [];
    if (customerIds.length > 0) {
      try {
        const { data, error: customersError } = await supabase
          .from("users")
          .select("id, full_name, email, phone")
          .in("id", customerIds);
        if (!customersError) {
          customersData = data || [];
        }
      } catch (err) {
        console.error("Error fetching customers:", err);
      }
    }
    const _customersMap = new Map(customersData.map((u: any) => [u.id, u]));
    void _customersMap;

    // Fetch providers
    let providersData: any[] = [];
    if (providerIds.length > 0) {
      try {
        const { data, error: providersError } = await supabase
          .from("providers")
          .select("id, business_name")
          .in("id", providerIds);
        if (!providersError) {
          providersData = data || [];
        }
      } catch (err) {
        console.error("Error fetching providers:", err);
      }
    }
    const _providersMap = new Map(providersData.map((p: any) => [p.id, p]));
    void _providersMap;

    // Fetch locations
    let locationsData: any[] = [];
    if (locationIds.length > 0) {
      try {
        const { data, error: locationsError } = await supabase
          .from("provider_locations")
          .select("id, name, address_line1, city")
          .in("id", locationIds);
        if (!locationsError) {
          locationsData = data || [];
        }
      } catch (err) {
        console.error("Error fetching locations:", err);
      }
    }
    const _locationsMap = new Map(locationsData.map((l: any) => [l.id, l]));
    void _locationsMap;

    // Transform to match Booking type
    const transformedBookings = bookings.map((booking: any) => ({
      id: booking.id,
      booking_number: booking.booking_number,
      customer_id: booking.customer_id,
      provider_id: booking.provider_id,
      status: booking.status,
      location_type: booking.location_type,
      location_id: booking.location_id,
      address: booking.address || null,
      scheduled_at: booking.scheduled_at,
      completed_at: booking.completed_at || null,
      cancelled_at: booking.cancelled_at || null,
      cancellation_reason: booking.cancellation_reason || null,
      services: booking.services || [],
      addons: booking.addons || [],
      package_id: booking.package_id || null,
      subtotal: booking.subtotal || 0,
      tip_amount: booking.tip_amount || 0,
      total_amount: booking.total_amount || 0,
      currency: booking.currency || "ZAR",
      payment_status: booking.payment_status,
      payment_method: booking.payment_method || null,
      special_requests: booking.special_requests || null,
      loyalty_points_earned: booking.loyalty_points_earned || 0,
      created_at: booking.created_at,
      updated_at: booking.updated_at,
    }));

    // Return array directly to match frontend expectations (same as providers)
    return successResponse(transformedBookings);
  } catch (error) {
    return handleApiError(error, "Failed to fetch bookings");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { sendToUsers } from "@/lib/notifications/onesignal";

/**
 * POST /api/admin/broadcast/email
 * 
 * Send email broadcast to all users, all providers, or a segment
 */
export async function POST(request: NextRequest) {
  try {
    const auth = await requireRoleInApi(['superadmin'], request);
    if (!auth) throw new Error("Authentication required");
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    const { subject, message, recipient_type, user_ids } = body;

    if (!subject || !message) {
      return errorResponse("Subject and message are required", "VALIDATION_ERROR", 400);
    }

    if (!recipient_type || !["all_users", "all_providers", "custom"].includes(recipient_type)) {
      return errorResponse("Invalid recipient_type", "VALIDATION_ERROR", 400);
    }

    let userIds: string[] = [];

    // Get user IDs based on recipient type
    if (recipient_type === "all_users") {
      const { data: users } = await supabase
        .from("users")
        .select("id")
        .eq("role", "customer");
      userIds = users?.map((u: any) => u.id) || [];
    } else if (recipient_type === "all_providers") {
      const { data: providers } = await supabase
        .from("providers")
        .select("user_id")
        .not("user_id", "is", null);
      userIds = providers?.map((p: any) => p.user_id).filter(Boolean) || [];
    } else if (recipient_type === "custom" && user_ids && Array.isArray(user_ids)) {
      userIds = user_ids;
    } else {
      return errorResponse("Invalid recipient configuration", "VALIDATION_ERROR", 400);
    }

    if (userIds.length === 0) {
      return errorResponse("No recipients found", "VALIDATION_ERROR", 400);
    }

    // Send email broadcast
    const result = await sendToUsers(
      userIds,
      {
        title: subject,
        message: message,
        type: "admin_broadcast",
        data: {
          type: "admin_broadcast",
          recipient_type,
        },
      },
      ["email"]
    );

    if (!result.success) {
      return errorResponse(result.error || "Failed to send broadcast", "BROADCAST_ERROR", 500);
    }

    // Log broadcast
    const { error: logError } = await supabase.from("broadcast_logs").insert({
      sent_by: auth.user.id,
      recipient_type,
      recipient_count: userIds.length,
      channel: "email",
      subject,
      message,
      status: result.success ? "sent" : "failed",
      notification_id: result.notification_id,
      created_at: new Date().toISOString(),
    });

    if (logError) {
      console.error("Error logging broadcast:", logError);
      // Don't fail the request if logging fails
    }

    return successResponse({
      success: true,
      recipients: userIds.length,
      notification_id: result.notification_id,
    });
  } catch (error) {
    return handleApiError(error, "Failed to send email broadcast");
  }
}

