  try {
    const { user } = await requireRole(["superadmin"]);
    const supabase = await getSupabaseServer(request);

    const body = await request.json();
    const {
      name,
      subject_template,
      body_template,
      category,
      variables,
      is_html,
      enabled,
    } = body;

    if (!name || !subject_template || !body_template) {
      return NextResponse.json(
        { error: "Name, subject_template, and body_template are required" },
        { status: 400 }
      );
    }

    const { data, error } = await supabase
      .from("email_templates")
      .insert({
        name,
        subject_template,
        body_template,
        category: category || null,
        variables: variables || [],
        is_html: is_html !== false,
        enabled: enabled !== false,
        created_by: user.id,
      })
      .select()
      .single();

    if (error) throw error;

    // Create initial version
    await supabase.from("email_template_versions").insert({
      template_id: data.id,
      version: 1,
      subject_template,
      body_template,
      created_by: user.id,
    });

    return NextResponse.json({ template: data });
  } catch (error: any) {
    console.error("Error creating email template:", error);
    return NextResponse.json(
      { error: error.message || "Failed to create email template" },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import {
  successResponse,
  errorResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";
import { requireRoleInApi } from "@/lib/supabase/api-helpers";

/**
 * PATCH /api/admin/explore/posts/[id]
 * Hide/unhide post, optional moderation_notes. Superadmin only.
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["superadmin"], request);
    const supabaseAdmin = getSupabaseAdmin();
    const { id } = await params;

    const body = await request.json();
    const { is_hidden, moderation_notes } = body;

    if (typeof is_hidden !== "boolean") {
      return errorResponse("is_hidden must be boolean", "VALIDATION_ERROR", 400);
    }

    const update: Record<string, any> = {
      is_hidden,
      moderated_at: new Date().toISOString(),
      moderated_by: user.id,
    };
    if (moderation_notes !== undefined) {
      update.moderation_notes = is_hidden ? (moderation_notes || null) : null;
    }

    const { data, error } = await supabaseAdmin
      .from("explore_posts")
      .update(update)
      .eq("id", id)
      .select("id, is_hidden, moderation_notes, moderated_at")
      .single();

    if (error) return handleApiError(error, "Failed to update post");
    return successResponse(data);
  } catch (error) {
    return handleApiError(error, "Failed to update post");
