import { NextRequest, NextResponse } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRole } from "@/lib/supabase/auth-server";

function isTableMissingError(e: any): boolean {
  const msg = typeof (e as any)?.message === "string" ? (e as any).message : "";
  return msg.includes("schema cache") || (msg.includes("relation ") && msg.includes("does not exist")) || msg.includes("Could not find the table");
}

export async function GET(request: NextRequest) {
  try {
    await requireRole(["superadmin"]);
    const supabase = getSupabaseAdmin();

    const { searchParams } = new URL(request.url);
    const paymentTransactionId = searchParams.get("payment_transaction_id");
    const financeTransactionId = searchParams.get("finance_transaction_id");
    const reconciled = searchParams.get("reconciled");
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "50");
    const offset = (page - 1) * limit;

    let query = supabase
      .from("payment_fee_adjustments")
      .select(
        `
        *,
        payment_transaction:payment_transaction_id(id, reference, amount, fees, provider),
        finance_transaction:finance_transaction_id(id, transaction_type, amount, fees)
      `,
        { count: "exact" }
      )
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (paymentTransactionId) {
      query = query.eq("payment_transaction_id", paymentTransactionId);
    }
    if (financeTransactionId) {
      query = query.eq("finance_transaction_id", financeTransactionId);
    }
    if (reconciled !== null && reconciled !== undefined) {
      query = query.eq("reconciled", reconciled === "true");
    }

    const { data, error, count } = await query;

    if (error) {
      if (isTableMissingError(error)) {
        return NextResponse.json({ data: [], meta: { page, limit, total: 0, has_more: false }, error: null });
      }
      throw error;
    }

    return NextResponse.json({
      data: data || [],
      meta: {
        page,
        limit,
        total: count || 0,
        has_more: (count || 0) > offset + limit,
      },
      error: null,
    });
  } catch (error: any) {
    const err = error as { message?: string };
    console.error("Error fetching fee adjustments:", err);
    if (isTableMissingError(err)) {
      return NextResponse.json({ data: [], meta: { page: 1, limit: 50, total: 0, has_more: false }, error: null });
    }
    return NextResponse.json(
      { error: err?.message || "Failed to fetch fee adjustments" },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRole(["superadmin"]);
    const supabase = getSupabaseAdmin();

    const body = await request.json();
    const {
      payment_transaction_id,
      finance_transaction_id,
      original_fee_amount,
      adjusted_fee_amount,
      adjustment_reason,
      adjustment_type,
      notes,
    } = body;

    // Validate required fields
    if (
      !payment_transaction_id &&
      !finance_transaction_id
    ) {
      return NextResponse.json(
        { error: "Either payment_transaction_id or finance_transaction_id is required" },
        { status: 400 }
      );
    }

    if (
      !original_fee_amount ||
      adjusted_fee_amount === undefined ||
      !adjustment_reason ||
      !adjustment_type
    ) {
      return NextResponse.json(
        { error: "Missing required fields" },
        { status: 400 }
      );
    }

    // Get the original transaction to verify fee
    let originalFee = original_fee_amount;
    if (payment_transaction_id) {
      const { data: tx } = await supabase
        .from("payment_transactions")
        .select("fees")
        .eq("id", payment_transaction_id)
        .single();
      if (tx) originalFee = tx.fees;
    } else if (finance_transaction_id) {
      const { data: tx } = await supabase
        .from("finance_transactions")
        .select("fees")
        .eq("id", finance_transaction_id)
        .single();
      if (tx) originalFee = tx.fees;
    }

    // Create the adjustment
    const { data: adjustment, error: adjustmentError } = await supabase
      .from("payment_fee_adjustments")
      .insert({
        payment_transaction_id: payment_transaction_id || null,
        finance_transaction_id: finance_transaction_id || null,
        original_fee_amount: originalFee,
        adjusted_fee_amount,
        adjustment_reason,
        adjustment_type,
        notes,
        created_by: user.id,
      })
      .select()
      .single();

    if (adjustmentError) throw adjustmentError;

    // Update the actual transaction fee
    if (payment_transaction_id) {
      const { error: updateError } = await supabase
        .from("payment_transactions")
        .update({
          fees: adjusted_fee_amount,
          net_amount: () => `amount - ${adjusted_fee_amount}`,
        })
        .eq("id", payment_transaction_id);

      if (updateError) {
        console.error("Error updating payment_transaction fee:", updateError);
        // Don't fail the request, just log it
      }
    } else if (finance_transaction_id) {
      const { error: updateError } = await supabase
        .from("finance_transactions")
        .update({
          fees: adjusted_fee_amount,
          net: () => `amount - ${adjusted_fee_amount} - commission`,
        })
        .eq("id", finance_transaction_id);

      if (updateError) {
        console.error("Error updating finance_transaction fee:", updateError);
        // Don't fail the request, just log it
      }
    }

    return NextResponse.json({ data: adjustment, error: null });
  } catch (error: any) {
    console.error("Error creating fee adjustment:", error);
    return NextResponse.json(
      { error: error.message || "Failed to create fee adjustment" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRole } from "@/lib/supabase/auth-server";

/** Table/schema cache errors when the table does not exist yet (migration not applied). */
function isTableMissingError(e: any): boolean {
  const msg = typeof (e as any)?.message === "string" ? (e as any).message : "";
  return (
    msg.includes("schema cache") ||
    msg.includes("relation ") && msg.includes("does not exist") ||
    msg.includes("Could not find the table")
  );
}

export async function GET(request: NextRequest) {
  try {
    await requireRole(["superadmin"]);
    const supabase = getSupabaseAdmin();

    const { searchParams } = new URL(request.url);
    const gateway = searchParams.get("gateway");
    const currency = searchParams.get("currency");
    const activeOnly = searchParams.get("active_only") === "true";

    let query = supabase
      .from("payment_gateway_fee_configs")
      .select("*")
      .order("effective_from", { ascending: false });

    if (gateway) {
      query = query.eq("gateway_name", gateway);
    }
    if (currency) {
      query = query.eq("currency", currency);
    }
    if (activeOnly) {
      query = query.eq("is_active", true);
    }

    const { data, error } = await query;

    if (error) {
      if (isTableMissingError(error)) {
        return NextResponse.json({ data: [], error: null });
      }
      throw error;
    }

    return NextResponse.json({ data: data ?? [], error: null });
  } catch (error: any) {
    const err = error as { message?: string };
    console.error("Error fetching fee configs:", err);
    if (isTableMissingError(err)) {
      return NextResponse.json({ data: [], error: null });
    }
    return NextResponse.json(
      { error: err?.message || "Failed to fetch fee configs" },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRole(["superadmin"]);
    const supabase = getSupabaseAdmin();

    const body = await request.json();
    const {
      gateway_name,
      fee_type,
      fee_percentage,
      fee_fixed_amount,
      fee_tiered_config,
      currency,
      is_active,
      effective_from,
      effective_until,
      description,
    } = body;

    // Validate required fields
    if (!gateway_name || !fee_type || !currency) {
      return NextResponse.json(
        { error: "Missing required fields" },
        { status: 400 }
      );
    }

    // Validate fee type and corresponding values
    if (fee_type === "percentage" && (!fee_percentage || fee_percentage < 0)) {
      return NextResponse.json(
        { error: "Percentage fee requires a valid fee_percentage" },
        { status: 400 }
      );
    }

    if (fee_type === "fixed" && (!fee_fixed_amount || fee_fixed_amount < 0)) {
      return NextResponse.json(
        { error: "Fixed fee requires a valid fee_fixed_amount" },
        { status: 400 }
      );
    }

    const { data, error } = await supabase
      .from("payment_gateway_fee_configs")
      .insert({
        gateway_name,
        fee_type,
        fee_percentage: fee_percentage || 0,
        fee_fixed_amount: fee_fixed_amount || 0,
        fee_tiered_config: fee_tiered_config || {},
        currency,
        is_active: is_active !== false,
        effective_from: effective_from || new Date().toISOString(),
        effective_until: effective_until || null,
        description,
        created_by: user.id,
        updated_by: user.id,
      })
      .select()
      .single();

    if (error) throw error;

    return NextResponse.json({ data, error: null });
  } catch (error: any) {
    console.error("Error creating fee config:", error);
    return NextResponse.json(
      { error: error.message || "Failed to create fee config" },
      { status: 500 }
    );
  }
}

export async function PATCH(request: NextRequest) {
  try {
    const { user } = await requireRole(["superadmin"]);
    const supabase = getSupabaseAdmin();

    const body = await request.json();
    const { id, ...updates } = body;

    if (!id) {
      return NextResponse.json(
        { error: "Missing fee config ID" },
        { status: 400 }
      );
    }

    // Add updated_by
    updates.updated_by = user.id;

    const { data, error } = await supabase
      .from("payment_gateway_fee_configs")
      .update(updates)
      .eq("id", id)
      .select()
      .single();

    if (error) throw error;

    return NextResponse.json({ data, error: null });
  } catch (error: any) {
    console.error("Error updating fee config:", error);
    return NextResponse.json(
      { error: error.message || "Failed to update fee config" },
      { status: 500 }
    );
  }
}

