    }
    if (endDate) {
      query = query.lte("reconciliation_date", endDate);
    }

    const { data, error, count } = await query;

    if (error) {
      if (isTableMissingError(error)) {
        return NextResponse.json({ data: [], meta: { page, limit, total: 0, has_more: false }, error: null });
      }
      throw error;
    }

    return NextResponse.json({
      data: data || [],
      meta: {
        page,
        limit,
        total: count || 0,
        has_more: (count || 0) > offset + limit,
      },
      error: null,
    });
  } catch (error: any) {
    const err = error as { message?: string };
    console.error("Error fetching reconciliations:", err);
    if (isTableMissingError(err)) {
      return NextResponse.json({ data: [], meta: { page: 1, limit: 50, total: 0, has_more: false }, error: null });
    }
    return NextResponse.json(
      { error: err?.message || "Failed to fetch reconciliations" },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRole(["superadmin"]);
    const supabase = getSupabaseAdmin();

    const body = await request.json();
    const {
      reconciliation_date,
      gateway_name,
      expected_fees,
      actual_fees,
      notes,
      statement_reference,
    } = body;

    // Validate required fields
    if (!reconciliation_date || !gateway_name || expected_fees === undefined || actual_fees === undefined) {
      return NextResponse.json(
        { error: "Missing required fields" },
        { status: 400 }
      );
    }

    // Calculate variance
    const variance = actual_fees - expected_fees;

    const { data, error } = await supabase
      .from("fee_reconciliations")
      .insert({
        reconciliation_date,
        gateway_name,
        expected_fees,
        actual_fees,
        variance,
        notes,
        statement_reference,
        created_by: user.id,
      })
      .select()
      .single();

    if (error) throw error;

    return NextResponse.json({ data, error: null });
  } catch (error: any) {
    console.error("Error creating reconciliation:", error);
    return NextResponse.json(
      { error: error.message || "Failed to create reconciliation" },
      { status: 500 }
    );
  }
}

export async function PATCH(request: NextRequest) {
  try {
    const { user } = await requireRole(["superadmin"]);
    const supabase = getSupabaseAdmin();

    const body = await request.json();
    const { id, status, notes, ...updates } = body;

    if (!id) {
      return NextResponse.json(
        { error: "Missing reconciliation ID" },
        { status: 400 }
      );
    }

    // If status is being updated to reviewed/resolved, add reviewed_by and reviewed_at
    if (status && (status === "reviewed" || status === "resolved")) {
      updates.reviewed_by = user.id;
      updates.reviewed_at = new Date().toISOString();
    }

    if (status) {
      updates.status = status;
    }
    if (notes !== undefined) {
      updates.notes = notes;
    }

    const { data, error } = await supabase
      .from("fee_reconciliations")
      .update(updates)
      .eq("id", id)
      .select()
      .single();

    if (error) throw error;

    return NextResponse.json({ data, error: null });
  } catch (error: any) {
    console.error("Error updating reconciliation:", error);
    return NextResponse.json(
      { error: error.message || "Failed to update reconciliation" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRole, unauthorizedResponse } from "@/lib/auth/requireRole";

/**
 * GET /api/admin/finance/summary
 * 
 * Get financial summary (GMV, fees, net, provider earnings)
 */
export async function GET(request: Request) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);
    const startDate = searchParams.get("start_date");
    const endDate = searchParams.get("end_date");

    // Finance ledger is the source of truth
    let ftQuery = supabase
      .from("finance_transactions")
      .select("transaction_type, amount, fees, commission, net, created_at", { count: "exact" });

    if (startDate) ftQuery = ftQuery.gte("created_at", startDate);
    if (endDate) ftQuery = ftQuery.lte("created_at", endDate);

    const { data: rows } = await ftQuery;
    const tx = rows || [];

    const sum = (
      types: string[],
      field: "amount" | "fees" | "commission" | "net" = "amount"
    ) =>
      tx
        .filter((r: any) => types.includes(r.transaction_type))
        .reduce((s: number, r: any) => s + Number(r[field] || 0), 0);

    // Gateway fees (only on payment and additional_charge_payment)
    const gatewayFeesServices = sum(["payment", "additional_charge_payment"], "fees");

    // Services collected (GMV): full customer payment for bookings + additional charges.
    // - payment row: amount = commission base (not full booking); full booking = commission base + provider_earnings + tip + tax + travel_fee + service_fee.
    // - additional_charge_payment: amount = net after gateway, so gross = amount + fees.
    const bookingGmv =
      sum(["payment"], "amount") +
      sum(["provider_earnings"], "amount") +
      sum(["tip"], "amount") +
      sum(["tax"], "amount") +
      sum(["travel_fee"], "amount") +
      sum(["service_fee"], "amount");
    const additionalChargeGross =
      sum(["additional_charge_payment"], "amount") + sum(["additional_charge_payment"], "fees");
    const serviceCollectedGross = bookingGmv + additionalChargeGross;
    const serviceCollectedNet = serviceCollectedGross - gatewayFeesServices;

    // Platform commission (gross and net of refunds)
    const platformCommissionGross = sum(["payment", "additional_charge_payment"], "net");
    const platformRefundImpact = sum(["refund"], "net"); // negative (commission reversal)
    const platformCommissionNet = platformCommissionGross + platformRefundImpact;

    // Platform take-home (commission net of refunds, minus gateway fees)
    const platformTakeNet = platformCommissionNet - gatewayFeesServices;

    // Tips & taxes (gross reporting; excluded from platform take)
    const tipsGross = sum(["tip"], "amount");
    const taxesGross = sum(["tax"], "amount");

    // Provider subscription revenue (platform earns this directly)
    const subscriptionNet = sum(["provider_subscription_payment"], "net");
    const subscriptionGatewayFees = sum(["provider_subscription_payment"], "fees");
    const subscriptionGross = subscriptionNet + subscriptionGatewayFees;

    // Ads revenue (provider pre-pay for campaign budget; platform earns when they pay)
    const adsNet = sum(["provider_ads_payment"], "net");
    const adsGatewayFees = sum(["provider_ads_payment"], "fees");
    const adsGross = adsNet + adsGatewayFees;

    const providerEarnings = sum(["provider_earnings"], "net");

    // Other provider-linked sales (gross)
    const giftCardSales = sum(["gift_card_sale"], "amount");
    const membershipSales = sum(["membership_sale"], "amount");

    // Refund gross: total amount refunded to customers (positive number for display)
    const refundsGross = sum(["refund"], "amount");

    // Wallet top-up revenue (cash in from customers; not in finance_transactions)
    const supabaseAdmin = getSupabaseAdmin();
    let walletTopupRevenue = 0;
    let referralPayouts = 0;
    try {
      let topupQuery = supabaseAdmin
        .from("wallet_topups")
        .select("amount")
        .eq("status", "paid");
      if (startDate) topupQuery = topupQuery.gte("paid_at", startDate);
      if (endDate) topupQuery = topupQuery.lte("paid_at", endDate);
      const { data: topups } = await topupQuery;
      walletTopupRevenue = (topups || []).reduce((s, r) => s + Number(r.amount || 0), 0);

      // Referral payouts (platform expense: credits to referrers' wallets)
      let refQuery = supabaseAdmin
        .from("wallet_transactions")
        .select("amount")
        .eq("type", "credit")
        .eq("reference_type", "referral");
      if (startDate) refQuery = refQuery.gte("created_at", startDate);
      if (endDate) refQuery = refQuery.lte("created_at", endDate);
      const { data: refTxs } = await refQuery;
      referralPayouts = (refTxs || []).reduce((s, r) => s + Number(r.amount || 0), 0);
    } catch (e) {
      console.warn("Wallet/referral counts failed:", e);
    }

    // Total platform take including subscription, ads, wallet top-up, minus referral payouts
    const totalPlatformTakeAfterReferrals =
      platformTakeNet + subscriptionNet + adsNet + walletTopupRevenue - referralPayouts;

    // Get period comparison (previous period)
    const period = startDate && endDate ? "custom" : "month";
    let previousStart: string;
    let previousEnd: string;

    if (period === "month") {
      const now = new Date();
      const _currentMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);
      const previousMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
      const previousMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0);

      previousStart = previousMonthStart.toISOString();
      previousEnd = previousMonthEnd.toISOString();
    } else {
      // For custom dates, calculate previous period of same length
      if (startDate && endDate) {
        const start = new Date(startDate);
        const end = new Date(endDate);
        const diff = end.getTime() - start.getTime();
        const prevEnd = new Date(start.getTime() - 1);
        const prevStart = new Date(prevEnd.getTime() - diff);

        previousStart = prevStart.toISOString();
        previousEnd = prevEnd.toISOString();
      } else {
        previousStart = "";
        previousEnd = "";
      }
    }

    let previousGmv = 0;
    if (previousStart && previousEnd) {
      const prevQuery = supabase
        .from("finance_transactions")
        .select("transaction_type, amount, fees")
        .gte("created_at", previousStart)
        .lte("created_at", previousEnd);
      const { data: prevRows } = await prevQuery;
      const prev = prevRows || [];
      const prevSum = (types: string[], field: "amount" | "fees") =>
        prev
          .filter((r: any) => types.includes(r.transaction_type))
          .reduce((s: number, r: any) => s + Number(r[field] || 0), 0);
      previousGmv =
        prevSum(["payment"], "amount") +
        prevSum(["provider_earnings"], "amount") +
        prevSum(["tip"], "amount") +
        prevSum(["tax"], "amount") +
        prevSum(["travel_fee"], "amount") +
        prevSum(["service_fee"], "amount") +
        prevSum(["additional_charge_payment"], "amount") +
        prevSum(["additional_charge_payment"], "fees");
    }

    const gmvGrowth = previousGmv > 0 ? ((serviceCollectedGross - previousGmv) / previousGmv) * 100 : 0;

    return NextResponse.json({
      data: {
        service_collected_gross: serviceCollectedGross,
        service_collected_net: serviceCollectedNet,
        gateway_fees: gatewayFeesServices,

        platform_commission_gross: platformCommissionGross,
        platform_refund_impact: platformRefundImpact,
        platform_commission_net: platformCommissionNet,
        platform_take_net: platformTakeNet,

        tips_gross: tipsGross,
        taxes_gross: taxesGross,

        subscription_collected_gross: subscriptionGross,
        subscription_net: subscriptionNet,
        subscription_gateway_fees: subscriptionGatewayFees,
        ads_net: adsNet,
        ads_gross: adsGross,
        ads_gateway_fees: adsGatewayFees,
        total_platform_take_net: platformTakeNet + subscriptionNet + adsNet,

        provider_earnings: providerEarnings,
        refunds_gross: refundsGross,
        gift_card_sales: giftCardSales,
        membership_sales: membershipSales,

        wallet_topup_revenue: walletTopupRevenue,
        referral_payouts: referralPayouts,
        total_platform_take_after_referrals: totalPlatformTakeAfterReferrals,

        gmv_growth: gmvGrowth,
        period: {
          start_date: startDate || null,
          end_date: endDate || null,
        },
      },
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/admin/finance/summary:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch finance summary",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, handleApiError, getPaginationParams } from "@/lib/supabase/api-helpers";

/**
 * GET /api/admin/finance/transactions
 * 
 * Get financial transactions with filters and pagination
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);

    if (!supabase) {
      return NextResponse.json({
        data: [],
        error: null,
        meta: {
          page: 1,
          limit: 50,
          total: 0,
          has_more: false,
        },
      });
    }

    const { searchParams } = new URL(request.url);
    const { page, limit, offset } = getPaginationParams(request);

    const startDate = searchParams.get("start_date");
    const endDate = searchParams.get("end_date");
    const type = searchParams.get("type"); // payment, refund, payout, fee

    // Get transactions from finance_transactions table
    let query = supabase
      .from("finance_transactions")
      .select("*", { count: "exact" });

    // Apply filters
    if (startDate) {
      query = query.gte("created_at", startDate);
    }
    if (endDate) {
      query = query.lte("created_at", endDate);
    }
    if (type && type !== "all") {
      query = query.eq("transaction_type", type);
    }

    // Apply pagination
    const { data: transactions, error, count } = await query
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (error) {
      console.error("Error fetching transactions:", error);
      // Return empty array instead of error to prevent crashes
      return NextResponse.json({
        data: [],
        error: null,
        meta: {
          page,
          limit,
          total: 0,
          has_more: false,
        },
      });
    }

    // Fetch related booking data separately if needed
    const bookingIds = [
      ...new Set(
        (transactions || [])
          .map((t: any) => t.booking_id)
          .filter(Boolean)
      ),
    ];

    let bookingMap = new Map();
    if (bookingIds.length > 0) {
      const { data: bookings } = await supabase
        .from("bookings")
        .select("id, booking_number")
        .in("id", bookingIds);

      if (bookings) {
        bookingMap = new Map(bookings.map((b: any) => [b.id, b]));
      }
    }

    // Transform transactions to match frontend expectations
    const transformedTransactions = (transactions || []).map((tx: any) => ({
      id: tx.id,
      transaction_type: tx.transaction_type || "unknown",
      amount: parseFloat(tx.amount || 0),
      fees: parseFloat(tx.fees || 0),
      commission: parseFloat(tx.commission || 0),
      net: parseFloat(tx.net || tx.amount || 0),
      created_at: tx.created_at,
      booking: tx.booking_id
        ? bookingMap.get(tx.booking_id) || null
        : null,
    }));

    return NextResponse.json({
      data: transformedTransactions,
      error: null,
      meta: {
        page,
        limit,
        total: count || 0,
        has_more: (count || 0) > offset + limit,
      },
    });
  } catch (error) {
    console.error("Unexpected error in /api/admin/finance/transactions:", error);
    return handleApiError(error, "Failed to fetch transactions");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/admin/gamification/badges/[id]
 *
 * Get a specific badge (superadmin only). Uses admin client to bypass RLS.
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = getSupabaseAdmin();
    const { id } = await params;

    const { data: badge, error } = await supabase
      .from('provider_badges')
      .select('*')
      .eq('id', id)
      .single();

    if (error) {
      if (error.code === 'PGRST116') {
        return handleApiError(
          new Error('Badge not found'),
          'NOT_FOUND',
          404
        );
      }
      throw error;
    }

    return successResponse({ badge });
  } catch (error) {
    return handleApiError(error, 'Failed to fetch badge');
  }
}

/**
 * PATCH /api/admin/gamification/badges/[id]
 *
 * Update a badge (superadmin only). Uses admin client to bypass RLS.
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = getSupabaseAdmin();
    const { id } = await params;

    const body = await request.json();
    const updateData: any = {};

    // Only update provided fields
    if (body.name !== undefined) updateData.name = body.name;
    if (body.slug !== undefined) updateData.slug = body.slug;
    if (body.description !== undefined) updateData.description = body.description;
    if (body.icon_url !== undefined) updateData.icon_url = body.icon_url;
    if (body.tier !== undefined) {
      if (body.tier < 1 || body.tier > 10) {
        return handleApiError(
          new Error('Tier must be between 1 and 10'),
          'VALIDATION_ERROR',
          400
        );
      }
      updateData.tier = body.tier;
    }
    if (body.color !== undefined) updateData.color = body.color;
    if (body.requirements !== undefined) updateData.requirements = body.requirements;
    if (body.benefits !== undefined) updateData.benefits = body.benefits;
    if (body.is_active !== undefined) updateData.is_active = body.is_active;
    if (body.display_order !== undefined) updateData.display_order = body.display_order;

    const { data: badge, error } = await supabase
      .from('provider_badges')
      .update(updateData)
      .eq('id', id)
      .select()
      .single();

    if (error) {
      if (error.code === 'PGRST116') {
        return handleApiError(
          new Error('Badge not found'),
          'NOT_FOUND',
          404
        );
      }
      throw error;
    }

    return successResponse({
      badge,
      message: 'Badge updated successfully',
    });
  } catch (error) {
    return handleApiError(error, 'Failed to update badge');
  }
}

/**
 * DELETE /api/admin/gamification/badges/[id]
 *
 * Delete a badge (superadmin only). Uses admin client to bypass RLS.
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = getSupabaseAdmin();
    const { id } = await params;

    // Check if badge is in use
    const { data: providersWithBadge, error: checkError } = await supabase
      .from('provider_points')
      .select('provider_id')
      .eq('current_badge_id', id)
      .limit(1);

    if (checkError) {
      throw checkError;
    }

    if (providersWithBadge && providersWithBadge.length > 0) {
      return handleApiError(
        new Error('Cannot delete badge that is currently assigned to providers. Deactivate it instead.'),
        'BADGE_IN_USE',
        400
      );
    }

    const { error } = await supabase
      .from('provider_badges')
      .delete()
      .eq('id', id);

    if (error) {
      if (error.code === 'PGRST116') {
        return handleApiError(
          new Error('Badge not found'),
          'NOT_FOUND',
          404
        );
      }
      throw error;
    }

    return successResponse({
      message: 'Badge deleted successfully',
    });
  } catch (error) {
    return handleApiError(error, 'Failed to delete badge');
  }
}

import { NextRequest } from "next/server";
import { requireRoleInApi, successResponse, handleApiError, errorResponse, notFoundResponse } from "@/lib/supabase/api-helpers";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { z } from "zod";

const updateGiftCardSchema = z.object({
  balance: z.number().min(0, "Balance cannot be negative").optional(),
  expires_at: z.string().nullable().optional(),
  is_active: z.boolean().optional(),
  metadata: z.record(z.string(), z.any()).optional(),
});

/**
 * GET /api/admin/gift-cards/[id]
 * Get gift card details with redemptions (superadmin only)
 */
export async function GET(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    await requireRoleInApi(["superadmin"], request);

    const supabaseAdmin = getSupabaseAdmin();

    const { id } = params;

    // Get gift card with redemptions
    const { data: giftCard, error: giftCardError } = await supabaseAdmin
      .from("gift_cards")
      .select("*")
      .eq("id", id)
      .single();

    if (giftCardError || !giftCard) {
      return notFoundResponse("Gift card not found");
    }

    // Get redemptions
    const { data: redemptions, error: redemptionsError } = await supabaseAdmin
      .from("gift_card_redemptions")
      .select("id, booking_id, amount, currency, status, created_at, captured_at, voided_at")
      .eq("gift_card_id", id)
      .order("created_at", { ascending: false });

    if (redemptionsError) {
      console.error("Error fetching redemptions:", redemptionsError);
      // Don't fail, just return gift card without redemptions
    }

    return successResponse({
      gift_card: {
        ...giftCard,
        redemptions: redemptions || [],
      },
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch gift card");
  }
}

/**
 * PATCH /api/admin/gift-cards/[id]
 * Update gift card (superadmin only)
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    await requireRoleInApi(["superadmin"], request);

    const supabaseAdmin = getSupabaseAdmin();

    const { id } = params;
    const body = await request.json();
    const validationResult = updateGiftCardSchema.safeParse(body);

    if (!validationResult.success) {
      return errorResponse("Validation failed", "VALIDATION_ERROR", 400, validationResult.error.issues);
    }

    const updateData: any = {};
    if (validationResult.data.balance !== undefined) {
      updateData.balance = validationResult.data.balance;
    }
    if (validationResult.data.expires_at !== undefined) {
      updateData.expires_at = validationResult.data.expires_at
        ? new Date(validationResult.data.expires_at).toISOString()
        : null;
    }
    if (validationResult.data.is_active !== undefined) {
      updateData.is_active = validationResult.data.is_active;
    }
    if (validationResult.data.metadata !== undefined) {
      updateData.metadata = validationResult.data.metadata;
    }

    const { data: giftCard, error } = await supabaseAdmin
      .from("gift_cards")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (error) {
      if (error.code === "PGRST116") {
        return notFoundResponse("Gift card not found");
      }
      throw error;
    }

    return successResponse({ gift_card: giftCard });
  } catch (error) {
    return handleApiError(error, "Failed to update gift card");
  }
}

/**
 * DELETE /api/admin/gift-cards/[id]
 * Delete gift card (superadmin only)
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    await requireRoleInApi(["superadmin"], request);

    const supabaseAdmin = getSupabaseAdmin();

    const { id } = params;

    const { error } = await supabaseAdmin.from("gift_cards").delete().eq("id", id);

    if (error) {
      if (error.code === "PGRST116") {
        return notFoundResponse("Gift card not found");
      }
      throw error;
    }

    return successResponse({ message: "Gift card deleted successfully" });
  } catch (error) {
    return handleApiError(error, "Failed to delete gift card");
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseAdmin } from '@/lib/supabase/admin';
import { requireRoleInApi, successResponse, handleApiError } from '@/lib/supabase/api-helpers';

export async function GET(request: NextRequest) {
  try {
    // Require superadmin role
    await requireRoleInApi(['superadmin'], request);

    const supabase = getSupabaseAdmin();

    if (!supabase) {
      console.error("Failed to get Supabase admin client");
      return handleApiError(new Error("Database connection failed"), 'Failed to load Gods Eye data');
    }

    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0, 0);
    const startOfWeek = new Date(now);
    startOfWeek.setDate(now.getDate() - now.getDay());
    startOfWeek.setHours(0, 0, 0, 0);
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);

    // Get overview counts
    const [
      { count: totalUsers } = { count: 0 },
      { count: totalProviders } = { count: 0 },
      { count: totalBookings } = { count: 0 },
      { count: activeBookings } = { count: 0 },
      { count: pendingApprovals } = { count: 0 },
      { count: houseCallBookings } = { count: 0 },
      { count: salonBookings } = { count: 0 },
    ] = await Promise.all([
      supabase.from('users').select('*', { count: 'exact', head: true }).eq('role', 'customer'),
      supabase.from('providers').select('*', { count: 'exact', head: true }).eq('status', 'active'),
      supabase.from('bookings').select('*', { count: 'exact', head: true }),
      supabase.from('bookings').select('*', { count: 'exact', head: true }).in('status', ['confirmed', 'pending', 'in_progress']),
      supabase.from('providers').select('*', { count: 'exact', head: true }).eq('status', 'pending_approval'),
      supabase.from('bookings').select('*', { count: 'exact', head: true }).eq('location_type', 'at_home'),
      supabase.from('bookings').select('*', { count: 'exact', head: true }).eq('location_type', 'at_salon'),
    ]);

    // Get bookings by status
    const [
      { count: confirmedBookings } = { count: 0 },
      { count: pendingBookings } = { count: 0 },
      { count: cancelledBookings } = { count: 0 },
      { count: completedBookings } = { count: 0 },
    ] = await Promise.all([
      supabase.from('bookings').select('*', { count: 'exact', head: true }).eq('status', 'confirmed'),
      supabase.from('bookings').select('*', { count: 'exact', head: true }).eq('status', 'pending'),
      supabase.from('bookings').select('*', { count: 'exact', head: true }).eq('status', 'cancelled'),
      supabase.from('bookings').select('*', { count: 'exact', head: true }).eq('status', 'completed'),
    ]);

    // Get revenue breakdown (GMV = sum of amount for payment types)
    const getRevenue = async (startISO: string, endISO?: string) => {
      try {
        let query = supabase
          .from("finance_transactions")
          .select("transaction_type, amount")
          .in("transaction_type", ["payment", "additional_charge_payment"])
          .gte("created_at", startISO);

        if (endISO) {
          query = query.lte("created_at", endISO);
        }

        const { data, error } = await query;

        if (error) {
          console.error("Error fetching revenue:", error);
          return 0;
        }

        const rows = data || [];
        return rows.reduce((sum: number, r: any) => sum + Number(r.amount || 0), 0);
      } catch (err) {
        console.error("Error calculating revenue:", err);
        return 0;
      }
    };

    const [revenueToday, revenueThisWeek, revenueThisMonth, revenueAllTime] = await Promise.all([
      getRevenue(startOfToday.toISOString()),
      getRevenue(startOfWeek.toISOString()),
      getRevenue(startOfMonth.toISOString()),
      getRevenue(new Date(0).toISOString()), // All time
    ]);

    // Top providers: fetch all providers (any status) so list is never empty when providers exist
    const { data: activeProvidersData } = await supabase
      .from('providers')
      .select('id, business_name, owner_name, rating_average, status')
      .limit(20);

    const allProviderIds = (activeProvidersData || []).map((p: any) => p.id);

    // Revenue from finance_transactions (provider_earnings, travel_fee, tip)
    const providerRevenue: Record<string, number> = {};
    if (allProviderIds.length > 0) {
      const { data: providerTxRows } = await supabase
        .from('finance_transactions')
        .select('provider_id, net, amount')
        .in('provider_id', allProviderIds)
        .in('transaction_type', ['provider_earnings', 'travel_fee', 'tip']);
      (providerTxRows || []).forEach((t: any) => {
        const id = t.provider_id;
        if (!id) return;
        if (!providerRevenue[id]) providerRevenue[id] = 0;
        providerRevenue[id] += Number(t.net ?? t.amount ?? 0);
      });
    }

    // Bookings count per provider
    const bookingsCounts: Record<string, number> = {};
    if (allProviderIds.length > 0) {
      const { data: bookingRows } = await supabase
        .from('bookings')
        .select('provider_id')
        .in('provider_id', allProviderIds);
      (bookingRows || []).forEach((b: any) => {
        bookingsCounts[b.provider_id] = (bookingsCounts[b.provider_id] || 0) + 1;
      });
    }

    const topProviders = (activeProvidersData || [])
      .map((provider: any) => ({
        id: provider.id,
        name: provider.business_name || provider.owner_name || 'Unknown',
        bookings_count: bookingsCounts[provider.id] || 0,
        revenue: providerRevenue[provider.id] ?? 0,
        rating: Number(provider.rating_average) || 0,
      }))
      .sort((a, b) => b.revenue - a.revenue)
      .slice(0, 5);

    // Get top customers (by total spent) - finance_transactions has booking_id not customer_id, so derive via bookings
    const { data: topCustomersData } = await supabase
      .from('users')
      .select('id, full_name, email')
      .eq('role', 'customer')
      .limit(20);

    const customerIds = (topCustomersData || []).map((c: any) => c.id);
    const customerBookingsCounts: Record<string, number> = {};
    const customerSpent: Record<string, number> = {};

    if (customerIds.length > 0) {
      const { data: customerBookings } = await supabase
        .from('bookings')
        .select('id, customer_id')
        .in('customer_id', customerIds);
      (customerBookings || []).forEach((b: any) => {
        customerBookingsCounts[b.customer_id] = (customerBookingsCounts[b.customer_id] || 0) + 1;
      });
      const bookingIds = (customerBookings || []).map((b: any) => b.id);
      if (bookingIds.length > 0) {
        const { data: txRows } = await supabase
          .from('finance_transactions')
          .select('booking_id, amount')
          .in('booking_id', bookingIds)
          .in('transaction_type', ['payment', 'additional_charge_payment']);
        const bookingToCustomer: Record<string, string> = {};
        (customerBookings || []).forEach((b: any) => {
          bookingToCustomer[b.id] = b.customer_id;
        });
        (txRows || []).forEach((t: any) => {
          const cid = bookingToCustomer[t.booking_id];
          if (cid) {
            customerSpent[cid] = (customerSpent[cid] || 0) + Number(t.amount || 0);
          }
        });
      }
    }

    const topCustomers = (topCustomersData || []).map((customer: any) => ({
      id: customer.id,
      name: customer.full_name || customer.email || 'Unknown',
      bookings_count: customerBookingsCounts[customer.id] || 0,
      total_spent: customerSpent[customer.id] || 0,
    })).sort((a, b) => b.total_spent - a.total_spent).slice(0, 5);

    // Get recent activity
    const recentActivity: Array<{
      id: string;
      type: string;
      action: string;
      entity_id: string;
      entity_name: string;
      timestamp: string;
      status: string;
    }> = [];

    // Recent bookings
    const { data: recentBookings } = await supabase
      .from('bookings')
      .select('id, booking_number, status, created_at')
      .order('created_at', { ascending: false })
      .limit(20);

    if (recentBookings) {
      recentBookings.forEach((booking: any) => {
        recentActivity.push({
          id: `booking-${booking.id}`,
          type: 'booking',
          action: `Booking ${booking.booking_number} ${booking.status}`,
          entity_id: booking.id,
          entity_name: booking.booking_number,
          timestamp: booking.created_at,
          status: booking.status,
        });
      });
    }

    // Recent users
    const { data: recentUsers } = await supabase
      .from('users')
      .select('id, full_name, email, created_at')
      .order('created_at', { ascending: false })
      .limit(10);

    if (recentUsers) {
      recentUsers.forEach((user: any) => {
        recentActivity.push({
          id: `user-${user.id}`,
          type: 'user',
          action: `New user registered`,
          entity_id: user.id,
          entity_name: user.full_name || user.email || 'Unknown',
          timestamp: user.created_at,
          status: 'success',
        });
      });
    }

    // Recent providers
    const { data: recentProviders } = await supabase
      .from('providers')
      .select('id, business_name, status, created_at')
      .order('created_at', { ascending: false })
      .limit(10);

    if (recentProviders) {
      recentProviders.forEach((provider: any) => {
        recentActivity.push({
          id: `provider-${provider.id}`,
          type: 'provider',
          action: `Provider ${provider.status}`,
          entity_id: provider.id,
          entity_name: provider.business_name || 'Unknown',
          timestamp: provider.created_at,
          status: provider.status,
        });
      });
    }

    // Sort by timestamp and take most recent 50
    recentActivity.sort((a, b) => 
      new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
    );
    const topActivity = recentActivity.slice(0, 50);

    return successResponse({
      overview: {
        total_users: totalUsers || 0,
        total_providers: totalProviders || 0,
        total_bookings: totalBookings || 0,
        total_revenue: revenueAllTime,
        active_bookings: activeBookings || 0,
        pending_approvals: pendingApprovals || 0,
        house_call_bookings: houseCallBookings || 0,
        salon_bookings: salonBookings || 0,
      },
      recent_activity: topActivity,
      bookings_by_status: {
        confirmed: confirmedBookings || 0,
        pending: pendingBookings || 0,
        cancelled: cancelledBookings || 0,
        completed: completedBookings || 0,
      },
      bookings_by_type: {
        at_home: houseCallBookings || 0,
        at_salon: salonBookings || 0,
      },
      revenue_breakdown: {
        today: revenueToday,
        this_week: revenueThisWeek,
        this_month: revenueThisMonth,
        all_time: revenueAllTime,
      },
      top_providers: topProviders
        .sort((a, b) => b.revenue - a.revenue)
        .slice(0, 5),
      top_customers: topCustomers
        .sort((a, b) => b.total_spent - a.total_spent)
        .slice(0, 5),
      system_health: {
        api_uptime: 99.9, // Mock value - in production, calculate from actual metrics
        database_status: 'operational', // In production, check actual database connection
        payment_gateway_status: 'operational', // In production, check Paystack API status
        notification_service_status: 'operational', // In production, check OneSignal API status
      },
    });
  } catch (error) {
    return handleApiError(error, 'Failed to load Gods Eye data');
  }
}

import { NextRequest } from "next/server";
import { cookies } from "next/headers";
import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";

export async function GET(request: NextRequest) {
  try {
    // Require authenticated session
    const supabase = await getSupabaseServer(request);
    if (!supabase) {
      return NextResponse.json(
        { error: "Authentication required", isImpersonating: false },
        { status: 401 }
      );
    }
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) {
      return NextResponse.json(
        { error: "Authentication required", isImpersonating: false },
        { status: 401 }
      );
    }

    const cookieStore = await cookies();

    // Check if we have an impersonation admin ID cookie
    const adminId = cookieStore.get("impersonation_admin_id")?.value;

    return NextResponse.json({
      isImpersonating: !!adminId,
    });
  } catch (error: any) {
    console.error("Error checking impersonation status:", error);
    return NextResponse.json(
      { isImpersonating: false },
      { status: 200 }
    );
  }
}

import { NextRequest } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { cookies } from "next/headers";
import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { writeAuditLog } from "@/lib/audit/audit";

export async function POST(request: NextRequest) {
  try {
    // Require authenticated session (during impersonation, session is the impersonated user)
    const supabase = await getSupabaseServer(request);
    if (!supabase) {
      return NextResponse.json(
        { error: "Authentication required" },
        { status: 401 }
      );
    }
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) {
      return NextResponse.json(
        { error: "Authentication required" },
        { status: 401 }
      );
    }

    const cookieStore = await cookies();

    // Get the original admin user ID from cookie
    const adminUserId = cookieStore.get("impersonation_admin_id")?.value;

    if (!adminUserId) {
      return NextResponse.json(
        { error: "No impersonation session found" },
        { status: 400 }
      );
    }

    // Use service role client to generate a sign-in link for the admin
    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    // Get the admin user
    const { data: adminUser, error: adminError } = await supabaseAdmin.auth.admin.getUserById(adminUserId);

    if (adminError || !adminUser) {
      return NextResponse.json(
        { error: "Admin user not found" },
        { status: 404 }
      );
    }

    // Generate a sign-in link for the admin
    const { data: linkData, error: linkError } = await supabaseAdmin.auth.admin.generateLink({
      type: "recovery",
      email: adminUser.user.email!,
      options: {
        redirectTo: `${request.nextUrl.origin}/auth/callback`,
      },
    });

    if (linkError || !linkData) {
      console.error("Error generating admin sign-in link:", linkError);
      return NextResponse.json(
        { error: "Failed to create admin session" },
        { status: 500 }
      );
    }

    // Extract the action link
    let actionLink: string | null = null;
    if (linkData && typeof linkData === 'object') {
      const data = linkData as any;
      if (data.properties?.action_link) {
        actionLink = data.properties.action_link;
      } else if (data.properties?.actionLink) {
        actionLink = data.properties.actionLink;
      } else if (data.action_link) {
        actionLink = data.action_link;
      } else if (data.actionLink) {
        actionLink = data.actionLink;
      } else if (typeof data.properties === 'string') {
        actionLink = data.properties;
      }
    } else if (typeof linkData === 'string') {
      actionLink = linkData;
    }

    if (!actionLink) {
      return NextResponse.json(
        { error: "Failed to extract action link" },
        { status: 500 }
      );
    }

    // Extract token_hash from the action link
    let token: string | null = null;
    try {
      const linkUrl = new URL(actionLink);
      token = linkUrl.searchParams.get("token_hash");
      if (!token) {
        token = linkUrl.searchParams.get("token");
      }
    } catch {
      const tokenMatch = actionLink.match(/[?&]token_hash=([^&?#]+)/) || 
                        actionLink.match(/[?&]token=([^&?#]+)/);
      if (tokenMatch) {
        token = decodeURIComponent(tokenMatch[1]);
      }
    }

    if (!token) {
      return NextResponse.json(
        { error: "Failed to extract token from link" },
        { status: 500 }
      );
    }

    // Log impersonation end before clearing cookies
    const ipAddress =
      request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ||
      request.headers.get("x-real-ip") ||
      "unknown";
    const userAgentHeader = request.headers.get("user-agent") || "unknown";

    await writeAuditLog({
      actor_user_id: adminUserId,
      actor_role: "superadmin",
      action: "admin_impersonation_end",
      entity_type: "user",
      entity_id: user.id, // the impersonated user
      metadata: {
        admin_id: adminUserId,
        impersonated_user_id: user.id,
        impersonated_email: user.email,
        ip_address: ipAddress,
        user_agent: userAgentHeader,
      },
    });

    // Clear impersonation cookies
    cookieStore.delete("impersonation_token");
    cookieStore.delete("impersonation_admin_id");

    // Return redirect URL
    return NextResponse.json({
      success: true,
      url: `/auth/callback?token_hash=${token}&type=recovery`,
    });
  } catch (error: any) {
    console.error("Error ending impersonation:", error);
    return NextResponse.json(
      { error: "Failed to end impersonation" },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, errorResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";
import { revalidateTag } from "next/cache";
import { trackServer } from "@/lib/analytics/amplitude/server";
import { EVENT_API_KEY_CREATED, EVENT_API_KEY_UPDATED } from "@/lib/analytics/amplitude/types";

export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);

    const { searchParams } = new URL(request.url);
    const environment = searchParams.get("environment") || "production";

    const { data, error } = await supabase
      .from("amplitude_integration_config")
      .select("*")
      .eq("environment", environment)
      .maybeSingle();

    if (error) throw error;

    if (!data) {
      return successResponse(null);
    }

    return successResponse(data);
  } catch (error: any) {
    return handleApiError(error, "Failed to fetch Amplitude configuration");
  }
}

export async function PUT(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);

    const body = await request.json();
    const {
      api_key_public,
      api_key_server,
      ingestion_endpoint,
      environment = "production",
      enabled_client_portal,
      enabled_provider_portal,
      enabled_admin_portal,
      guides_enabled,
      surveys_enabled,
      sampling_rate,
      debug_mode,
    } = body;

    // Validation
    if (!api_key_public) {
      return errorResponse("Public API key is required", "VALIDATION_ERROR", 400);
    }

    if (environment && !["production", "staging", "development"].includes(environment)) {
      return errorResponse("Environment must be production, staging, or development", "VALIDATION_ERROR", 400);
    }

    if (sampling_rate !== undefined && (sampling_rate < 0 || sampling_rate > 1)) {
      return errorResponse("Sampling rate must be between 0 and 1", "VALIDATION_ERROR", 400);
    }

    // Check if config exists for this environment
    const { data: existing } = await supabase
      .from("amplitude_integration_config")
      .select("id")
      .eq("environment", environment)
      .maybeSingle();

    let result;
    if (existing) {
      // Update existing config
      const updateData: any = {
        api_key_public,
        ingestion_endpoint: ingestion_endpoint || "https://api2.amplitude.com/2/httpapi",
        environment,
        updated_by: user.id,
      };

      // Only update optional fields if provided
      if (api_key_server !== undefined) updateData.api_key_server = api_key_server;
      if (enabled_client_portal !== undefined) updateData.enabled_client_portal = enabled_client_portal;
      if (enabled_provider_portal !== undefined) updateData.enabled_provider_portal = enabled_provider_portal;
      if (enabled_admin_portal !== undefined) updateData.enabled_admin_portal = enabled_admin_portal;
      if (guides_enabled !== undefined) updateData.guides_enabled = guides_enabled;
      if (surveys_enabled !== undefined) updateData.surveys_enabled = surveys_enabled;
      if (sampling_rate !== undefined) updateData.sampling_rate = sampling_rate;
      if (debug_mode !== undefined) updateData.debug_mode = debug_mode;

      const { data, error } = await supabase
        .from("amplitude_integration_config")
        .update(updateData)
        .eq("id", existing.id)
        .select()
        .single();

      if (error) throw error;
      result = data;
    } else {
      // Create new config
      const { data, error } = await supabase
        .from("amplitude_integration_config")
        .insert({
          api_key_public,
          api_key_server: api_key_server || null,
          ingestion_endpoint: ingestion_endpoint || "https://api2.amplitude.com/2/httpapi",
          environment,
          enabled_client_portal: enabled_client_portal ?? true,
          enabled_provider_portal: enabled_provider_portal ?? true,
          enabled_admin_portal: enabled_admin_portal ?? true,
          guides_enabled: guides_enabled ?? false,
          surveys_enabled: surveys_enabled ?? false,
          sampling_rate: sampling_rate ?? 1.0,
          debug_mode: debug_mode ?? false,
          created_by: user.id,
          updated_by: user.id,
        })
        .select()
        .single();

      if (error) throw error;
      result = data;
    }

    // Write audit log
    await writeAuditLog({
      actor_user_id: user.id,
      actor_role: "superadmin",
      action: existing ? "admin.amplitude_config.update" : "admin.amplitude_config.create",
      entity_type: "amplitude_integration_config",
      entity_id: result.id,
      metadata: {
        environment,
        enabled_client_portal: result.enabled_client_portal,
        enabled_provider_portal: result.enabled_provider_portal,
        enabled_admin_portal: result.enabled_admin_portal,
        guides_enabled: result.guides_enabled,
        surveys_enabled: result.surveys_enabled,
      },
    });

    // Track Amplitude event
    try {
      await trackServer(
        existing ? EVENT_API_KEY_UPDATED : EVENT_API_KEY_CREATED,
        {
          portal: "admin",
          api_key_id: result.id,
          key_name: "amplitude_integration_config",
          environment,
        },
        user.id
      );
    } catch (amplitudeError) {
      console.error("[Amplitude] Failed to track config update:", amplitudeError);
    }

    // Revalidate cache for public config endpoint
    revalidateTag("amplitude-config", "default");

    return successResponse(result);
  } catch (error: any) {
    return handleApiError(error, "Failed to update Amplitude configuration");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  handleApiError,
  notFoundResponse,
} from "@/lib/supabase/api-helpers";

/**
 * PATCH /api/admin/invoices/[id]
 * Update invoice (e.g. mark as sent) ΓÇö superadmin only.
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const { id } = await params;
    const body = await request.json();
    const { status, notes } = body;

    const updates: Record<string, any> = { updated_at: new Date().toISOString() };
    if (status) {
      updates.status = status;
      if (status === "sent") {
        updates.sent_at = new Date().toISOString();
      }
    }
    if (notes !== undefined) {
      updates.notes = notes;
    }

    const { data: invoice, error } = await supabase
      .from("provider_invoices")
      .update(updates)
      .eq("id", id)
      .select()
      .single();

    if (error) {
      throw error;
    }
    if (!invoice) {
      return notFoundResponse("Invoice not found");
    }

    return successResponse(invoice);
  } catch (error) {
    return handleApiError(error, "Failed to update invoice");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, getPaginationParams } from "@/lib/supabase/api-helpers";

/**
 * GET /api/admin/invoices
 * Get list of all invoices (superadmin only)
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(["superadmin"], request);

    const supabase = await getSupabaseServer(request);
    const { page, limit, offset } = getPaginationParams(request);
    const searchParams = request.nextUrl.searchParams;
    const status = searchParams.get("status");
    const providerId = searchParams.get("provider_id");

    let query = supabase
      .from("provider_invoices")
      .select(
        `
        *,
        providers!inner(id, business_name, billing_email, billing_phone)
      `,
        { count: "exact" }
      )
      .order("issue_date", { ascending: false })
      .range(offset, offset + limit - 1);

    if (status) {
      query = query.eq("status", status);
    }

    if (providerId) {
      query = query.eq("provider_id", providerId);
    }

    const { data: invoices, error, count } = await query;

    if (error) {
      throw error;
    }

    // Transform to include provider info (business_name as name for display)
    const transformedInvoices = (invoices || []).map((invoice: any) => ({
      ...invoice,
      provider: invoice.providers
        ? { ...invoice.providers, name: invoice.providers.business_name }
        : null,
    }));

    return successResponse({
      invoices: transformedInvoices,
      total: count || 0,
      page,
      limit,
      total_pages: Math.ceil((count || 0) / limit),
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch invoices");
  }
}

