import { NextRequest, NextResponse } from "next/server";
import { revalidateTag } from "next/cache";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole, unauthorizedResponse } from "@/lib/auth/requireRole";
import { z } from "zod";
import { writeAuditLog } from "@/lib/audit/audit";
import { getSupabaseAdmin } from "@/lib/supabase/admin";

const mapboxConfigSchema = z.object({
  // access_token is a secret and is stored in platform_secrets; only update when provided
  access_token: z.string().optional().nullable(),
  // public token; optional on update (leave blank to keep current); required when creating new config
  public_access_token: z.string().optional().nullable(),
  style_url: z.string().url().optional().nullable(),
  is_enabled: z.boolean().default(true),
});

function isMaskedOrEmptyToken(value: string | null | undefined): boolean {
  if (!value || value === "***") return true;
  if (value.length <= 12 || value.endsWith("...")) return true;
  return false;
}

/**
 * GET /api/admin/mapbox/config
 * 
 * Get Mapbox configuration
 */
export async function GET(request: NextRequest) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = await getSupabaseServer(request);

    const { data: config, error } = await supabase
      .from("mapbox_config")
      .select("*")
      .single();

    if (error && error.code !== "PGRST116") {
      // PGRST116 = not found, which is okay
      console.error("Error fetching Mapbox config:", error);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to fetch Mapbox configuration",
            code: "FETCH_ERROR",
          },
        },
        { status: 500 }
      );
    }

    // Response contains only non-secret config; secret token lives in platform_secrets
    if (config) {
      const maskedConfig = {
        ...(config as Record<string, any>),
        public_access_token: (config as any).public_access_token
          ? `${(config as any).public_access_token.substring(0, 8)}...`
          : null,
        access_token: "***",
      };
      return NextResponse.json({ data: maskedConfig, error: null });
    }

    return NextResponse.json({
      data: null,
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/admin/mapbox/config:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch Mapbox configuration",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

/**
 * PUT /api/admin/mapbox/config
 * 
 * Update Mapbox configuration
 */
export async function PUT(request: Request) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    const validationResult = mapboxConfigSchema.safeParse(body);
    if (!validationResult.success) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Validation failed",
            code: "VALIDATION_ERROR",
            details: validationResult.error.issues.map((issue) => ({
              path: issue.path.join("."),
              message: issue.message,
            })),
          },
        },
        { status: 400 }
      );
    }

    const admin = getSupabaseAdmin();

    // If secret access_token provided (and not placeholder), store in platform_secrets
    const newAccessToken = validationResult.data.access_token?.trim();
    if (newAccessToken && newAccessToken !== "***") {
      const { data: existingSecrets } = await (admin.from("platform_secrets") as any).select("id").limit(1).maybeSingle();
      if (existingSecrets?.id) {
        await (admin.from("platform_secrets") as any)
          .update({ mapbox_access_token: newAccessToken, updated_at: new Date().toISOString() })
          .eq("id", existingSecrets.id);
      } else {
        await (admin.from("platform_secrets") as any).insert({ mapbox_access_token: newAccessToken });
      }
    }

    // Resolve effective public token: new value if provided and not masked, else existing from DB
    const { data: existingConfig } = await supabase.from("mapbox_config").select("id, public_access_token").single();
    const existingPublicToken = (existingConfig as any)?.public_access_token as string | null | undefined;
    const sentPublicToken = validationResult.data.public_access_token?.trim();
    const useNewPublicToken = sentPublicToken && !isMaskedOrEmptyToken(sentPublicToken);
    const effectivePublicToken = useNewPublicToken ? sentPublicToken : (existingPublicToken || null);

    if (!existingConfig && !effectivePublicToken) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Public access token is required when creating Mapbox configuration",
            code: "VALIDATION_ERROR",
          },
        },
        { status: 400 }
      );
    }

    let config: any;
    if (existingConfig) {
      const { data, error } = await (supabase
        .from("mapbox_config") as any)
        .update({
          ...(effectivePublicToken != null && { public_access_token: effectivePublicToken }),
          style_url: validationResult.data.style_url ?? null,
          is_enabled: validationResult.data.is_enabled,
          updated_at: new Date().toISOString(),
        })
        .eq("id", (existingConfig as any).id)
        .select()
        .single();

      if (error) {
        console.error("Error updating Mapbox config:", error);
        return NextResponse.json(
          {
            data: null,
            error: {
              message: "Failed to update Mapbox configuration",
              code: "UPDATE_ERROR",
            },
          },
          { status: 500 }
        );
      }
      config = data;
    } else {
      const { data, error } = await (supabase
        .from("mapbox_config") as any)
        .insert({
          public_access_token: effectivePublicToken!,
          style_url: validationResult.data.style_url || null,
          is_enabled: validationResult.data.is_enabled,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        })
        .select()
        .single();

      if (error) {
        console.error("Error creating Mapbox config:", error);
        return NextResponse.json(
          {
            data: null,
            error: {
              message: "Failed to create Mapbox configuration",
              code: "CREATE_ERROR",
            },
          },
          { status: 500 }
        );
      }
      config = data;
    }

    // Sync to platform_settings so web, customer, and provider apps get same config via third-party-config
    const publicTokenForClients = effectivePublicToken ?? (config?.public_access_token as string) ?? "";
    try {
      const { data: psRow } = await (admin.from("platform_settings") as any).select("id, settings").single();
      if (psRow?.settings) {
        const settings = { ...(psRow.settings as Record<string, any>) };
        const mapbox = (settings.mapbox as Record<string, any>) || {};
        settings.mapbox = {
          ...mapbox,
          public_token: (publicTokenForClients || (mapbox.public_token as string)) ?? "",
          enabled: validationResult.data.is_enabled,
        };
        await (admin.from("platform_settings") as any)
          .update({ settings, updated_at: new Date().toISOString() })
          .eq("id", psRow.id);
      }
    } catch (syncErr) {
      console.warn("Mapbox config sync to platform_settings failed (non-blocking):", syncErr);
    }
    revalidateTag("platform-settings", "default");

    // Mask token in response
    const maskedConfig = {
      ...config,
      access_token: "***",
      public_access_token: config.public_access_token
        ? `${config.public_access_token.substring(0, 8)}...`
        : null,
    };

    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as any).role || "superadmin",
      action: "admin.mapbox.config.update",
      entity_type: "mapbox_config",
      entity_id: (config as any)?.id || null,
      metadata: {
        is_enabled: validationResult.data.is_enabled,
        style_url: validationResult.data.style_url || null,
        public_access_token_set: !!validationResult.data.public_access_token,
        access_token_set: !!validationResult.data.access_token,
      },
    });

    return NextResponse.json({
      data: maskedConfig,
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/admin/mapbox/config:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to update Mapbox configuration",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole, unauthorizedResponse } from "@/lib/auth/requireRole";
import { z } from "zod";

const updateServiceZoneSchema = z.object({
  name: z.string().min(1).optional(),
  type: z.enum(["radius", "polygon"]).optional(),
  coordinates: z
    .union([
      z.object({
        longitude: z.number(),
        latitude: z.number(),
      }),
      z.array(
        z.object({
          longitude: z.number(),
          latitude: z.number(),
        })
      ),
    ])
    .optional(),
  radius_km: z.number().min(0).optional(),
  is_active: z.boolean().optional(),
  provider_id: z.string().uuid().optional().nullable(),
});

/**
 * GET /api/admin/mapbox/service-zones/[id]
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRole(["superadmin", "provider_owner"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const { id } = await params;
    const supabase = await getSupabaseServer(request);

    const { data: zone, error } = await supabase
      .from("service_zones")
      .select("*")
      .eq("id", id)
      .single();

    if (error || !zone) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Service zone not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    // Check access for provider_owner
    if (auth.user.role === "provider_owner" && (zone as any).provider_id) {
      const { data: provider } = await supabase
        .from("providers")
        .select("id")
        .eq("id", (zone as any).provider_id)
        .eq("user_id", auth.user.id)
        .single();

      if (!provider) {
        return NextResponse.json(
          {
            data: null,
            error: {
              message: "Access denied",
              code: "FORBIDDEN",
            },
          },
          { status: 403 }
        );
      }
    }

    // Transform database schema to match frontend expectations
    const transformedZone: any = {
      id: zone.id,
      name: zone.name,
      type: zone.zone_type, // zone_type -> type
      is_active: zone.is_active,
      provider_id: zone.provider_id,
      radius_km: zone.radius_km,
    };

    // Transform coordinates based on zone type
    if (zone.zone_type === "radius") {
      transformedZone.coordinates = {
        longitude: zone.center_longitude,
        latitude: zone.center_latitude,
      };
    } else if (zone.zone_type === "polygon") {
      // Transform polygon_coordinates from [[lat, lng], ...] to [{longitude, latitude}, ...]
      if (Array.isArray(zone.polygon_coordinates)) {
        transformedZone.coordinates = zone.polygon_coordinates.map((coord: any) => {
          if (Array.isArray(coord) && coord.length >= 2) {
            return {
              longitude: coord[1], // lng is second
              latitude: coord[0],  // lat is first
            };
          }
          return coord;
        });
      } else {
        transformedZone.coordinates = [];
      }
    }

    return NextResponse.json({
      data: transformedZone,
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch service zone",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

/**
 * PUT /api/admin/mapbox/service-zones/[id]
 */
export async function PUT(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRole(["superadmin", "provider_owner"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const { id } = await params;
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    const validationResult = updateServiceZoneSchema.safeParse(body);
    if (!validationResult.success) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Validation failed",
            code: "VALIDATION_ERROR",
            details: validationResult.error.issues.map((issue) => ({
              path: issue.path.join("."),
              message: issue.message,
            })),
          },
        },
        { status: 400 }
      );
    }

    // Check existing zone
    const { data: existing } = await supabase
      .from("service_zones")
      .select("*")
      .eq("id", id)
      .single();

    if (!existing) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Service zone not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    // Check access for provider_owner
    if (auth.user.role === "provider_owner" && (existing as any).provider_id) {
      const { data: provider } = await supabase
        .from("providers")
        .select("id")
        .eq("id", (existing as any).provider_id)
        .eq("user_id", auth.user.id)
        .single();

      if (!provider) {
        return NextResponse.json(
          {
            data: null,
            error: {
              message: "Access denied",
              code: "FORBIDDEN",
            },
          },
          { status: 403 }
        );
      }
    }

    // Transform frontend schema to database schema
    const updateData: any = {
      updated_at: new Date().toISOString(),
    };

    if (validationResult.data.name !== undefined) {
      updateData.name = validationResult.data.name;
    }
    if (validationResult.data.is_active !== undefined) {
      updateData.is_active = validationResult.data.is_active;
    }
    if (validationResult.data.provider_id !== undefined) {
      updateData.provider_id = validationResult.data.provider_id;
    }
    if (validationResult.data.radius_km !== undefined) {
      updateData.radius_km = validationResult.data.radius_km;
    }
    if (validationResult.data.type !== undefined) {
      updateData.zone_type = validationResult.data.type; // type -> zone_type
    }

    // Handle coordinates transformation
    if (validationResult.data.coordinates !== undefined) {
      const zoneType = validationResult.data.type || existing.zone_type;
      
      if (zoneType === "radius") {
        const coords = validationResult.data.coordinates as { longitude: number; latitude: number };
        updateData.center_longitude = coords.longitude;
        updateData.center_latitude = coords.latitude;
        updateData.polygon_coordinates = null; // Clear polygon data
      } else if (zoneType === "polygon") {
        const coords = validationResult.data.coordinates as Array<{ longitude: number; latitude: number }>;
        updateData.polygon_coordinates = coords.map((coord) => [coord.latitude, coord.longitude]);
        updateData.center_longitude = null; // Clear radius data
        updateData.center_latitude = null;
        updateData.radius_km = null;
      }
    }

    const { data: zone, error } = await (supabase
      .from("service_zones") as any)
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (error || !zone) {
      console.error("Error updating service zone:", error);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to update service zone",
            code: "UPDATE_ERROR",
          },
        },
        { status: 500 }
      );
    }

    // Transform database schema back to frontend format
    const transformedZone: any = {
      id: zone.id,
      name: zone.name,
      type: zone.zone_type,
      is_active: zone.is_active,
      provider_id: zone.provider_id,
      radius_km: zone.radius_km,
    };

    if (zone.zone_type === "radius") {
      transformedZone.coordinates = {
        longitude: zone.center_longitude,
        latitude: zone.center_latitude,
      };
    } else if (zone.zone_type === "polygon") {
      if (Array.isArray(zone.polygon_coordinates)) {
        transformedZone.coordinates = zone.polygon_coordinates.map((coord: any) => {
          if (Array.isArray(coord) && coord.length >= 2) {
            return {
              longitude: coord[1],
              latitude: coord[0],
            };
          }
          return coord;
        });
      } else {
        transformedZone.coordinates = [];
      }
    }

    return NextResponse.json({
      data: transformedZone,
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to update service zone",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

