import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole, unauthorizedResponse } from "@/lib/auth/requireRole";
import { successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";

/**
 * GET /api/admin/notification-templates
 * 
 * Get all notification templates
 */
export async function GET(request: NextRequest) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);
    const enabled = searchParams.get("enabled");
    const channel = searchParams.get("channel");

    let query = supabase
      .from("notification_templates")
      .select("*")
      .order("created_at", { ascending: false });

    if (enabled !== null) {
      query = query.eq("enabled", enabled === "true");
    }

    if (channel) {
      query = query.contains("channels", [channel]);
    }

    const { data: rows, error } = await query;

    if (error) throw error;

    // Map DB shape (key, title, body) to UI shape (name, type, title_template, message_template)
    const templates = (rows || []).map((row: any) => ({
      id: row.id,
      name: row.key,
      type: row.key,
      title_template: row.title ?? "",
      message_template: row.body ?? "",
      priority: "medium" as const,
      channels: Array.isArray(row.channels) ? row.channels : [],
      enabled: row.enabled !== false,
      variables: Array.isArray(row.variables) ? row.variables : [],
      created_at: row.created_at,
      updated_at: row.updated_at,
      // Pass through for edit form (email, url, description)
      key: row.key,
      title: row.title,
      body: row.body,
      email_subject: row.email_subject,
      email_body: row.email_body,
      sms_body: row.sms_body,
      url: row.url,
      description: row.description,
    }));

    return successResponse({
      templates,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch notification templates");
  }
}

/**
 * POST /api/admin/notification-templates
 * 
 * Create a new notification template
 */
export async function POST(request: NextRequest) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = await getSupabaseServer(request);
    const body = await request.json();
    const key = (body.key || body.type || (body.name && String(body.name).trim()) || "").trim();
    if (!key) {
      return errorResponse("key is required (e.g. my_notification_type)", "VALIDATION_ERROR", 400);
    }

    const { data: template, error } = await supabase
      .from("notification_templates")
      .insert({
        key: key.replace(/\s+/g, "_").toLowerCase(),
        title: body.title ?? body.title_template ?? body.name ?? "",
        body: body.body ?? body.message_template ?? "",
        channels: (() => {
          const raw = Array.isArray(body.channels) && body.channels.length > 0 ? body.channels : ["push"];
          const allowed = ["push", "email", "sms", "live_activities"];
          return raw.map((c: string) => (c === "in_app" ? "push" : c)).filter((c: string) => allowed.includes(c));
        })(),
        email_subject: body.email_subject ?? null,
        email_body: body.email_body ?? null,
        sms_body: body.sms_body ?? null,
        variables: Array.isArray(body.variables) ? body.variables : [],
        url: body.url ?? null,
        enabled: body.enabled !== undefined ? body.enabled : true,
        description: body.description ?? null,
      })
      .select()
      .single();

    if (error) throw error;

    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as any).role || "superadmin",
      action: "admin.notification_templates.create",
      entity_type: "notification_template",
      entity_id: template.id,
      metadata: { key: body.key },
    });

    return successResponse({ template });
  } catch (error) {
    return handleApiError(error, "Failed to create notification template");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { requireRoleInApi } from "@/lib/supabase/api-helpers";
import { 
  sendToUser, 
  sendToUsers, 
  sendToSegment, 
  sendTemplateNotification,
  type NotificationChannel 
} from "@/lib/notifications/onesignal";
import { z } from "zod";
import { writeAuditLog } from "@/lib/audit/audit";

const sendNotificationSchema = z.object({
  type: z.enum(["user", "users", "segment", "template"]),
  user_id: z.string().uuid().optional(),
  user_ids: z.array(z.string().uuid()).optional(),
  segment: z.record(z.string(), z.any()).optional(),
  template_key: z.string().optional(),
  template_variables: z.record(z.string(), z.string()).optional(),
  channels: z.array(z.enum(["push", "email", "sms", "live_activities"])).optional().default(["push"]),
  // Notification content
  title: z.string().min(1).optional(),
  message: z.string().min(1).optional(),
  // Channel-specific content
  email_subject: z.string().optional(),
  email_body: z.string().optional(),
  sms_body: z.string().optional(),
  live_activities_config: z.record(z.string(), z.any()).optional(),
  // Additional data
  data: z.record(z.string(), z.any()).optional(),
  url: z.string().url().optional(),
  image: z.string().url().optional(),
});

/**
 * POST /api/admin/notifications/send
 * 
 * Send a notification campaign
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["superadmin"], request);

    const body = await request.json();
    const validationResult = sendNotificationSchema.safeParse(body);

    if (!validationResult.success) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Validation failed",
            code: "VALIDATION_ERROR",
            details: validationResult.error.issues.map((issue) => ({ path: issue.path.join("."), message: issue.message })),
          },
        },
        { status: 400 }
      );
    }

    const {
      type,
      user_id,
      user_ids,
      segment,
      template_key,
      template_variables,
      channels,
      title,
      message,
      email_subject: _email_subject,
      email_body: _email_body,
      sms_body: _sms_body,
      live_activities_config: _live_activities_config,
      data,
      url,
      image,
    } = validationResult.data;

    let result;

    switch (type) {
      case "user":
        if (!user_id) {
          return NextResponse.json(
            {
              data: null,
              error: {
                message: "user_id is required for type 'user'",
                code: "VALIDATION_ERROR",
              },
            },
            { status: 400 }
          );
        }
        result = await sendToUser(
          user_id,
          {
            title: title!,
            message: message!,
            data,
            url,
            image,
          },
          channels as NotificationChannel[]
        );
        break;

      case "users":
        if (!user_ids || user_ids.length === 0) {
          return NextResponse.json(
            {
              data: null,
              error: {
                message: "user_ids is required for type 'users'",
                code: "VALIDATION_ERROR",
              },
            },
            { status: 400 }
          );
        }
        result = await sendToUsers(
          user_ids,
          {
            title: title!,
            message: message!,
            data,
            url,
            image,
          },
          channels as NotificationChannel[]
        );
        break;

      case "segment":
        if (!segment) {
          return NextResponse.json(
            {
              data: null,
              error: {
                message: "segment is required for type 'segment'",
                code: "VALIDATION_ERROR",
              },
            },
            { status: 400 }
          );
        }
        result = await sendToSegment(
          segment,
          {
            title: title!,
            message: message!,
            data,
            url,
            image,
          },
          channels as NotificationChannel[]
        );
        break;

      case "template":
        if (!template_key || !user_ids || user_ids.length === 0) {
          return NextResponse.json(
            {
              data: null,
              error: {
                message: "template_key and user_ids are required for type 'template'",
                code: "VALIDATION_ERROR",
              },
            },
            { status: 400 }
          );
        }
        result = await sendTemplateNotification(
          template_key,
          user_ids,
          template_variables || {},
          channels as NotificationChannel[]
        );
        break;

      default:
        return NextResponse.json(
          {
            data: null,
            error: {
              message: "Invalid notification type",
              code: "VALIDATION_ERROR",
            },
          },
          { status: 400 }
        );
    }

    if (!result.success) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: result.error || "Failed to send notification",
            code: "SEND_ERROR",
          },
        },
        { status: 500 }
      );
    }

    try {
      await writeAuditLog({
        actor_user_id: user.id,
        actor_role: (user as any).role || "superadmin",
        action: "admin.notifications.send",
        entity_type: "notification",
        entity_id: null,
        metadata: {
          type,
          user_id,
          user_ids,
          segment,
          template_key,
          channels,
          notification_id: result.notification_id,
        },
      });
    } catch (auditError) {
      console.error("Audit log failed (notification still sent):", auditError);
    }

    return NextResponse.json({
      data: {
        notification_id: result.notification_id,
        success: true,
      },
      error: null,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Failed to send notification";
    console.error("Unexpected error in /api/admin/notifications/send:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: message.includes("OneSignal") || message.includes("configured")
            ? message
            : "Failed to send notification",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

