import { requireRoleInApi, successResponse, handleApiError } from '@/lib/supabase/api-helpers';
import { z } from 'zod';

const platformFeesSchema = z.object({
  platform_service_fee_type: z.enum(['percentage', 'fixed']).optional(),
  platform_service_fee_percentage: z.number().min(0).max(100).optional(),
  platform_service_fee_fixed: z.number().min(0).optional(),
  show_service_fee_to_customer: z.boolean().optional(),
});

const DEFAULT_PLATFORM_FEES = {
  platform_service_fee_type: 'percentage' as const,
  platform_service_fee_percentage: 5,
  platform_service_fee_fixed: 0,
  show_service_fee_to_customer: true,
};

/**
 * GET /api/admin/platform-fees
 *
 * Get platform fee settings from platform_settings.settings.payouts (JSONB)
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = await getSupabaseServer(request);

    const { data: row, error } = await supabase
      .from('platform_settings')
      .select('id, settings')
      .eq('is_active', true)
      .limit(1)
      .maybeSingle();

    if (error) {
      console.warn('Platform fees query error (returning defaults):', error.code, error.message);
      return successResponse(DEFAULT_PLATFORM_FEES);
    }

    const payouts = (row?.settings as Record<string, any>)?.payouts as Record<string, any> | undefined;
    return successResponse({
      platform_service_fee_type: (payouts?.platform_service_fee_type as string) || 'percentage',
      platform_service_fee_percentage: (payouts?.platform_service_fee_percentage as number) ?? 5,
      platform_service_fee_fixed: (payouts?.platform_service_fee_fixed as number) ?? 0,
      show_service_fee_to_customer: (payouts?.show_service_fee_to_customer as boolean) !== false,
    });
  } catch (error) {
    return handleApiError(error, 'Failed to fetch platform fee settings');
  }
}

/**
 * PATCH /api/admin/platform-fees
 *
 * Update platform fee settings in platform_settings.settings.payouts (JSONB)
 */
export async function PATCH(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    const validatedData = platformFeesSchema.parse(body);

    const { data: existingRow, error: fetchError } = await supabase
      .from('platform_settings')
      .select('id, settings')
      .eq('is_active', true)
      .limit(1)
      .maybeSingle();

    if (fetchError) {
      throw fetchError;
    }

    const currentSettings = (existingRow?.settings as Record<string, any>) || {};
    const payouts = { ...(currentSettings.payouts as Record<string, any> || {}) };
    payouts.platform_service_fee_type = validatedData.platform_service_fee_type ?? payouts.platform_service_fee_type ?? 'percentage';
    payouts.platform_service_fee_percentage = validatedData.platform_service_fee_percentage ?? (payouts.platform_service_fee_percentage as number) ?? 0;
    payouts.platform_service_fee_fixed = validatedData.platform_service_fee_fixed ?? (payouts.platform_service_fee_fixed as number) ?? 0;
    if (validatedData.show_service_fee_to_customer !== undefined) {
      payouts.show_service_fee_to_customer = validatedData.show_service_fee_to_customer;
    }
    const updatedSettings = { ...currentSettings, payouts };

    if (existingRow?.id) {
      const { data: updated, error: updateError } = await supabase
        .from('platform_settings')
        .update({
          settings: updatedSettings,
          updated_at: new Date().toISOString(),
        })
        .eq('id', existingRow.id)
        .select('settings')
        .single();

      if (updateError || !updated) {
        throw updateError || new Error('Failed to update platform fee settings');
      }

      const outPayouts = (updated?.settings as Record<string, any>)?.payouts as Record<string, any> | undefined;
      return successResponse({
        platform_service_fee_type: (outPayouts?.platform_service_fee_type as string) || 'percentage',
        platform_service_fee_percentage: (outPayouts?.platform_service_fee_percentage as number) ?? 5,
        platform_service_fee_fixed: (outPayouts?.platform_service_fee_fixed as number) ?? 0,
        show_service_fee_to_customer: (outPayouts?.show_service_fee_to_customer as boolean) !== false,
      });
    }

    // No row yet: insert one with payouts and minimal defaults
    const { data: inserted, error: insertError } = await supabase
      .from('platform_settings')
      .insert({
        settings: updatedSettings,
        is_active: true,
      })
      .select('settings')
      .single();

    if (insertError || !inserted) {
      throw insertError || new Error('Failed to create platform fee settings');
    }

    const outPayouts = (inserted?.settings as Record<string, any>)?.payouts as Record<string, any> | undefined;
    return successResponse({
      platform_service_fee_type: (outPayouts?.platform_service_fee_type as string) || 'percentage',
      platform_service_fee_percentage: (outPayouts?.platform_service_fee_percentage as number) ?? 5,
      platform_service_fee_fixed: (outPayouts?.platform_service_fee_fixed as number) ?? 0,
      show_service_fee_to_customer: (outPayouts?.show_service_fee_to_customer as boolean) !== false,
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        new Error(error.issues.map((e: any) => e.message).join(', ')),
        'Validation failed',
        'VALIDATION_ERROR',
        400
      );
    }
    return handleApiError(error, 'Failed to update platform fee settings');
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  handleApiError,
  errorResponse,
  notFoundResponse,
} from "@/lib/supabase/api-helpers";
import { z } from "zod";

const updatePlatformZoneSchema = z.object({
  name: z.string().min(1).optional(),
  zone_type: z.enum(["postal_code", "city", "polygon", "radius"]).optional(),
  postal_codes: z.array(z.string()).optional(),
  cities: z.array(z.string()).optional(),
  polygon_coordinates: z.any().optional(),
  center_latitude: z.number().optional(),
  center_longitude: z.number().optional(),
  radius_km: z.number().positive().optional(),
  description: z.string().optional().nullable(),
  is_active: z.boolean().optional(),
});

/**
 * GET /api/admin/platform-zones/[id]
 * Get a specific platform zone (superadmin only)
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const { id } = await params;

    const { data: zone, error } = await supabase
      .from("platform_zones")
      .select("*")
      .eq("id", id)
      .single();

    if (error || !zone) {
      return notFoundResponse("Platform zone not found");
    }

    return successResponse(zone);
  } catch (error) {
    return handleApiError(error, "Failed to fetch platform zone");
  }
}

/**
 * PATCH /api/admin/platform-zones/[id]
 * Update a platform zone (superadmin only)
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const { id } = await params;

    const { data: existingZone, error: fetchError } = await supabase
      .from("platform_zones")
      .select("id, zone_type")
      .eq("id", id)
      .single();

    if (fetchError || !existingZone) {
      return notFoundResponse("Platform zone not found");
    }

    const body = await request.json();
    const validationResult = updatePlatformZoneSchema.safeParse(body);

    if (!validationResult.success) {
      return errorResponse(
        validationResult.error.issues.map((i) => i.message).join(", ")
      );
    }

    const data = validationResult.data;
    const zoneType = data.zone_type || existingZone.zone_type;

    // Validate zone type specific fields if zone_type is being updated
    if (data.zone_type) {
      if (zoneType === "postal_code" && (!data.postal_codes || data.postal_codes.length === 0)) {
        return errorResponse("Postal codes are required for postal_code zones");
      }
      if (zoneType === "city" && (!data.cities || data.cities.length === 0)) {
        return errorResponse("Cities are required for city zones");
      }
      if (zoneType === "polygon" && !data.polygon_coordinates) {
        return errorResponse("Polygon coordinates are required for polygon zones");
      }
      if (zoneType === "radius") {
        if (!data.center_latitude || !data.center_longitude || !data.radius_km) {
          return errorResponse("Center coordinates and radius are required for radius zones");
        }
      }
    }

    const updateData: any = {};
    if (data.name !== undefined) updateData.name = data.name;
    if (data.zone_type !== undefined) updateData.zone_type = data.zone_type;
    if (data.postal_codes !== undefined) updateData.postal_codes = data.postal_codes;
    if (data.cities !== undefined) updateData.cities = data.cities;
    if (data.polygon_coordinates !== undefined) updateData.polygon_coordinates = data.polygon_coordinates;
    if (data.center_latitude !== undefined) updateData.center_latitude = data.center_latitude;
    if (data.center_longitude !== undefined) updateData.center_longitude = data.center_longitude;
    if (data.radius_km !== undefined) updateData.radius_km = data.radius_km;
    if (data.description !== undefined) updateData.description = data.description;
    if (data.is_active !== undefined) updateData.is_active = data.is_active;

    const { data: zone, error } = await supabase
      .from("platform_zones")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (error) {
      throw error;
    }

    return successResponse(zone);
  } catch (error) {
    return handleApiError(error, "Failed to update platform zone");
  }
}

/**
 * DELETE /api/admin/platform-zones/[id]
 * Delete a platform zone (superadmin only)
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const { id } = await params;

    // Check if any providers have selected this zone
    const { data: selections, error: checkError } = await supabase
      .from("provider_zone_selections")
      .select("id")
      .eq("platform_zone_id", id)
      .limit(1);

    if (checkError) {
      throw checkError;
    }

    if (selections && selections.length > 0) {
      return errorResponse(
        "Cannot delete platform zone: Some providers have selected this zone. Please deactivate it instead."
      );
    }

    const { error } = await supabase
      .from("platform_zones")
      .delete()
      .eq("id", id);

    if (error) {
      throw error;
    }

    return successResponse({ success: true });
  } catch (error) {
    return handleApiError(error, "Failed to delete platform zone");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";

/**
 * GET /api/admin/product-orders ΓÇö superadmin: list all product orders with stats
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);

    const status = searchParams.get("status");
    const providerId = searchParams.get("provider_id");
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "20");
    const offset = (page - 1) * limit;

    let query = (supabase.from("product_orders") as any)
      .select(
        `*,
        items:product_order_items(id, product_name, quantity, unit_price, total_price),
        customer:users!product_orders_customer_id_fkey(id, full_name, email),
        provider:providers(id, business_name)`,
        { count: "exact" },
      )
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (status) query = query.eq("status", status);
    if (providerId) query = query.eq("provider_id", providerId);

    const { data: orders, error, count } = await query;
    if (error) throw error;

    // Aggregate stats
    const { data: stats } = await (supabase.from("product_orders") as any)
      .select("status, total_amount, payment_status")
      .order("created_at", { ascending: false });

    const summary = {
      total_orders: (stats ?? []).length,
      total_revenue: (stats ?? [])
        .filter((o: any) => o.payment_status === "paid")
        .reduce((s: number, o: any) => s + Number(o.total_amount), 0),
      pending: (stats ?? []).filter((o: any) => o.status === "pending").length,
      delivered: (stats ?? []).filter((o: any) => o.status === "delivered").length,
      cancelled: (stats ?? []).filter((o: any) => o.status === "cancelled").length,
    };

    return successResponse({
      orders: orders ?? [],
      summary,
      pagination: { page, limit, total: count ?? 0, totalPages: Math.ceil((count ?? 0) / limit) },
    });
  } catch (err) {
    return handleApiError(err, "Failed to fetch product orders");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  notFoundResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";
import { z } from "zod";

const resolveSchema = z.object({
  resolution: z.enum(["full_refund", "partial_refund", "replacement", "store_credit", "denied"]),
  admin_notes: z.string().max(1000).optional(),
  refund_processed_amount: z.number().min(0).optional(),
});

/**
 * GET /api/admin/product-returns/[id]
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);

    const { data, error } = await (supabase.from("product_return_requests") as any)
      .select(
        `*,
        order:product_orders(*,items:product_order_items(*)),
        customer:users!product_return_requests_customer_id_fkey(id, full_name, email, phone),
        provider:providers(id, business_name, owner_id)`,
      )
      .eq("id", id)
      .single();

    if (error || !data) return notFoundResponse("Return request not found");
    return successResponse({ return_request: data });
  } catch (err) {
    return handleApiError(err, "Failed to fetch return request");
  }
}

/**
 * PATCH /api/admin/product-returns/[id] ΓÇö superadmin resolves escalated/any return
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    const { user } = await requireRoleInApi(["superadmin"], request);
    const body = await request.json();
    const parsed = resolveSchema.parse(body);
    const supabase = await getSupabaseServer(request);

    const { data: req } = await (supabase.from("product_return_requests") as any)
      .select("id, status, refund_amount")
      .eq("id", id)
      .single();

    if (!req) return notFoundResponse("Return request not found");

    const isRefund = ["full_refund", "partial_refund", "store_credit"].includes(parsed.resolution);

    const update: Record<string, any> = {
      status: isRefund ? "refunded" : "resolved_by_admin",
      resolution: parsed.resolution,
      admin_notes: parsed.admin_notes ?? null,
      resolved_by: user.id,
    };

    if (isRefund) {
      update.refunded_at = new Date().toISOString();
      update.refund_processed_amount =
        parsed.refund_processed_amount ?? Number(req.refund_amount);
      update.refund_method = "admin_override";
    }

    const { data, error } = await (supabase.from("product_return_requests") as any)
      .update(update)
      .eq("id", id)
      .select()
      .single();

    if (error) throw error;
    return successResponse({ return_request: data });
  } catch (err) {
    return handleApiError(err, "Failed to resolve return request");
  }
}

