import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRoleInApi, successResponse, notFoundResponse, handleApiError } from "@/lib/supabase/api-helpers";

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

/**
 * GET /api/admin/providers/[id]
 *
 * Get detailed provider information (superadmin only). Uses admin client to bypass RLS.
 * [id] can be provider UUID or slug.
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(['superadmin'], request);

    const { id: idOrSlug } = await params;
    const supabase = getSupabaseAdmin();

    const byId = UUID_REGEX.test(idOrSlug);

    const { data: provider, error } = await supabase
      .from("providers")
      .select(`
        *,
        locations:provider_locations(*),
        staff:provider_staff(*),
        offerings(*)
      `)
      .eq(byId ? "id" : "slug", idOrSlug)
      .single();

    if (error || !provider) {
      return notFoundResponse("Provider not found");
    }

    const providerId = (provider as Record<string, any> & { id: string }).id;

    const prov = provider as Record<string, any> & { user_id?: string };
    let owner: { id: string; full_name: string | null; email: string | null; phone: string | null; avatar_url: string | null } | null = null;
    if (prov.user_id) {
      const { data: ownerRow } = await supabase
        .from("users")
        .select("id, full_name, email, phone, avatar_url")
        .eq("id", prov.user_id)
        .single();
      owner = ownerRow as typeof owner;
    }

    // Get stats (use resolved provider id)
    const { count: bookingCount } = await supabase
      .from("bookings")
      .select("*", { count: "exact", head: true })
      .eq("provider_id", providerId);

    const { count: reviewCount } = await supabase
      .from("reviews")
      .select("*", { count: "exact", head: true })
      .eq("provider_id", providerId);

    const { data: reviews } = await supabase
      .from("reviews")
      .select("rating")
      .eq("provider_id", providerId);

    const avgRating =
      reviews && reviews.length > 0
        ? reviews.reduce((sum: number, r: any) => sum + (r.rating || 0), 0) / reviews.length
        : 0;

    return successResponse({
      ...(provider as Record<string, any>),
      owner: owner ?? null,
      stats: {
        booking_count: bookingCount || 0,
        review_count: reviewCount || 0,
        average_rating: avgRating,
      },
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch provider");
  }
}

/**
 * PATCH /api/admin/providers/[id]
 *
 * Update provider details. [id] can be provider UUID or slug.
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const { id: idOrSlug } = await params;
    const supabase = getSupabaseAdmin();
    const body = await request.json();

    const byId = UUID_REGEX.test(idOrSlug);

    const { data: provider } = await supabase
      .from("providers")
      .select("id")
      .eq(byId ? "id" : "slug", idOrSlug)
      .single();

    if (!provider) {
      return notFoundResponse("Provider not found");
    }

    const providerId = (provider as { id: string }).id;

    // Prepare update data (only allow specific fields)
    const updateData: any = {
      updated_at: new Date().toISOString(),
    };

    if (body.business_name !== undefined) updateData.business_name = body.business_name;
    if (body.description !== undefined) updateData.description = body.description;
    if (body.email !== undefined) updateData.email = body.email;
    if (body.phone !== undefined) updateData.phone = body.phone;
    if (body.business_type !== undefined) updateData.business_type = body.business_type;

    const { data: updatedProvider, error: updateError } = await supabase
      .from("providers")
      .update(updateData)
      .eq("id", providerId)
      .select("*, locations:provider_locations(*), staff:provider_staff(*), offerings(*)")
      .single();

    if (updateError || !updatedProvider) {
      return handleApiError(updateError, "Failed to update provider");
    }

    const updated = updatedProvider as Record<string, any> & { user_id?: string };
    let owner: { id: string; full_name: string | null; email: string | null; phone: string | null; avatar_url: string | null } | null = null;
    if (updated.user_id) {
      const { data: ownerRow } = await supabase
        .from("users")
        .select("id, full_name, email, phone, avatar_url")
        .eq("id", updated.user_id)
        .single();
      owner = ownerRow as typeof owner;
    }
    return successResponse({ ...updated, owner: owner ?? null });
  } catch (error) {
    return handleApiError(error, "Failed to update provider");
  }
}

import { getSupabaseAdmin } from "@/lib/supabase/admin";
import {
  requireRoleInApi,
  handleApiError,
  successResponse,
  notFoundResponse,
  errorResponse,
} from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";
import { z } from "zod";

/**
 * PATCH /api/admin/providers/[id]/status
 * 
 * Update provider status (approve, reject, suspend, reactivate). Uses admin client to bypass RLS.
 */
const updateProviderStatusSchema = z.object({
  status: z.enum(["pending", "active", "suspended", "rejected", "approved"]),
  reason: z.string().optional(),
});

export async function PATCH(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRoleInApi(["superadmin"], request);
    if (!auth) throw new Error("Authentication required");
    const supabase = getSupabaseAdmin();
    const { id } = await params;
    const body = await request.json();

    // Validate input
    const validationResult = updateProviderStatusSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Invalid input data",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    const { status, reason } = validationResult.data;

    // Verify provider exists
    const { data: provider } = await supabase
      .from("providers")
      .select("id, status")
      .eq("id", id)
      .single();

    if (!provider) {
      return notFoundResponse("Provider not found");
    }

    // Update provider status
    const updateData: any = {
      status,
      updated_at: new Date().toISOString(),
    };

    if (reason) {
      updateData.status_reason = reason;
    }

    const { data: updatedProvider, error: updateError } = await (supabase
      .from("providers") as any)
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (updateError || !updatedProvider) {
      return handleApiError(updateError, "Failed to update provider status");
    }

    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as any).role || "superadmin",
      action: "admin.provider.status",
      entity_type: "provider",
      entity_id: id,
      metadata: { previous_status: provider.status, new_status: status, reason },
    });

    // Send notification using templates
    try {
      const { sendTemplateNotification } = await import("@/lib/notifications/onesignal");

      // Get provider owner
      const { data: providerWithOwner } = await supabase
        .from("providers")
        .select("user_id, business_name")
        .eq("id", id)
        .single();

      if (providerWithOwner) {
        const ownerId = (providerWithOwner as any).user_id;
        const businessName = (providerWithOwner as any).business_name;

        let templateKey: string | null = null;
        const variables: Record<string, string> = {
          business_name: businessName,
        };

        // Determine template based on status
        if (status === "active" || status === "approved") {
          // Check if this is a reactivation (was suspended before) or new approval
          if (provider.status === "suspended") {
            templateKey = "provider_reactivated";
          } else {
            templateKey = "provider_approved";
          }
        } else if (status === "suspended") {
          templateKey = "provider_suspended";
          variables.reason = reason || "Please contact support for more information.";
        } else if (status === "rejected") {
          templateKey = "provider_profile_rejected";
          variables.rejection_reason = reason || "Please contact support for more information.";
        }

        // Send notification using template
        if (templateKey) {
          // Send via push, email, and SMS
          await sendTemplateNotification(
            templateKey,
            [ownerId],
            variables,
            ["push", "email", "sms"]
          );
        }
      }
    } catch (notifError) {
      console.error("Error sending notification:", notifError);
      // Don't fail the request if notification fails
    }

    return successResponse(updatedProvider);
  } catch (error) {
    return handleApiError(error, "Failed to update provider status");
  }
}

