import { z } from "zod";

const bulkActionSchema = z.object({
  provider_ids: z.array(z.string().uuid()).min(1, "At least one provider ID is required"),
  action: z.enum(["approve", "suspend", "reject", "verify", "unverify"]),
  reason: z.string().optional().nullable(),
});

/**
 * POST /api/admin/providers/bulk
 * 
 * Perform bulk actions on providers
 */
export async function POST(request: NextRequest) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    // Validate request body
    const validationResult = bulkActionSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400
      );
    }

    const { provider_ids, action, reason } = validationResult.data;

    let updateData: any = {};
    const results = { success: 0, failed: 0, errors: [] as string[] };

    switch (action) {
      case "approve":
        updateData = { status: "active" };
        break;
      case "suspend":
        updateData = { status: "suspended" };
        break;
      case "reject":
        updateData = { status: "rejected" };
        break;
      case "verify":
        updateData = { is_verified: true };
        break;
      case "unverify":
        updateData = { is_verified: false };
        break;
    }

    // Perform bulk update
    const { error: updateError } = await supabase
      .from("providers")
      .update(updateData)
      .in("id", provider_ids);

    if (updateError) {
      throw updateError;
    }

    results.success = provider_ids.length;

    // Log audit trail
    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as any).role || "superadmin",
      action: `admin.providers.bulk.${action}`,
      entity_type: "provider",
      entity_id: provider_ids.join(","),
      metadata: { provider_ids, action, reason, count: provider_ids.length },
    });

    return successResponse({
      success: true,
      results,
    });
  } catch (error) {
    return handleApiError(error, "Failed to perform bulk action");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/admin/providers
 * Get list of all providers (superadmin only). Uses admin client to bypass RLS.
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(["superadmin"], request);

    const supabase = getSupabaseAdmin();
    const { searchParams } = new URL(request.url);
    const statusFilter = searchParams.get("status");

    let query = supabase
      .from("providers")
      .select(`
        id,
        business_name,
        slug,
        business_type,
        status,
        is_verified,
        billing_email,
        billing_phone,
        user_id,
        rating_average,
        review_count,
        created_at,
        provider_locations (city, country)
      `)
      .order("business_name", { ascending: true });

    if (statusFilter && statusFilter !== "all") {
      if (statusFilter === "pending") {
        query = query.in("status", ["draft", "pending_approval"]);
      } else {
        query = query.eq("status", statusFilter);
      }
    }

    const { data: providers, error } = await query;

    if (error) {
      throw error;
    }

    const userIds = [...new Set((providers || []).map((p: any) => p.user_id).filter(Boolean))];
    const usersMap = new Map<string, { full_name?: string; email?: string; phone?: string }>();
    if (userIds.length > 0) {
      const { data: users } = await supabase
        .from("users")
        .select("id, full_name, email, phone")
        .in("id", userIds);
      for (const u of users || []) {
        usersMap.set((u as any).id, u);
      }
    }

    const transformed = (providers || []).map((p: any) => {
      const locations = (p.provider_locations || []) as { city?: string; country?: string }[];
      const firstLoc = locations[0];
      const status = p.status === "pending_approval" || p.status === "draft" ? "pending" : p.status;
      const owner = usersMap.get(p.user_id);

      return {
        id: p.id,
        business_name: p.business_name,
        slug: p.slug,
        business_type: p.business_type,
        status,
        verification_status: p.is_verified ? "verified" : "unverified",
        owner_name: owner?.full_name || "ΓÇö",
        owner_email: p.billing_email || owner?.email || "ΓÇö",
        owner_phone: p.billing_phone || owner?.phone,
        city: firstLoc?.city || "ΓÇö",
        country: firstLoc?.country || "ΓÇö",
        created_at: p.created_at,
        rating: p.rating_average ?? 0,
        review_count: p.review_count ?? 0,
      };
    });

    return successResponse(transformed);
  } catch (error) {
    return handleApiError(error, "Failed to fetch providers");
  }
}

import { NextRequest } from "next/server";
import { z } from "zod";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, notFoundResponse } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";

const updateSchema = z.object({
  question: z.string().min(1).optional(),
  answer: z.string().optional().nullable(),
  answer_type: z.enum(["text", "list"]).optional(),
  answer_list: z.array(z.string()).optional().nullable(),
  display_order: z.number().int().min(0).optional(),
  is_active: z.boolean().optional(),
});

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const { id } = await params;
    const body = updateSchema.parse(await request.json());

    const updateData: any = {};
    if (body.question !== undefined) updateData.question = body.question;
    if (body.answer !== undefined) updateData.answer = body.answer;
    if (body.answer_type !== undefined) updateData.answer_type = body.answer_type;
    if (body.answer_list !== undefined) updateData.answer_list = body.answer_list;
    if (body.display_order !== undefined) updateData.display_order = body.display_order;
    if (body.is_active !== undefined) updateData.is_active = body.is_active;
    updateData.updated_at = new Date().toISOString();

    const { data: row, error } = await (supabase.from("referral_faqs") as any)
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (error || !row) {
      if (error?.code === "42P01") {
        return handleApiError(
          new Error("referral_faqs table does not exist. Please run the migration first."),
          "Database table not found",
          "TABLE_NOT_FOUND",
          500
        );
      }
      return notFoundResponse("FAQ not found");
    }

    await writeAuditLog({
      actor_user_id: user.id,
      actor_role: user.role,
      action: "update",
      entity_type: "referral_faq",
      entity_id: id,
      metadata: body,
    });

    return successResponse(row);
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(error, "Invalid request", "VALIDATION_ERROR", 400);
    }
    return handleApiError(error, "Failed to update referral FAQ");
  }
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const { id } = await params;

    const { data: existing } = await supabase
      .from("referral_faqs")
      .select("id")
      .eq("id", id)
      .maybeSingle();

    if (!existing) {
      return notFoundResponse("FAQ not found");
    }

    const { error } = await (supabase.from("referral_faqs") as any).delete().eq("id", id);
    if (error) throw error;

    await writeAuditLog({
      actor_user_id: user.id,
      actor_role: user.role,
      action: "delete",
      entity_type: "referral_faq",
      entity_id: id,
      metadata: {},
    });

    return successResponse({ ok: true });
  } catch (error) {
    return handleApiError(error, "Failed to delete referral FAQ");
  }
}

import { NextRequest } from "next/server";
import { z } from "zod";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";

const faqSchema = z.object({
  question: z.string().min(1),
  answer: z.string().min(1),
  answer_type: z.enum(["text", "list"]).default("text"),
  answer_list: z.array(z.string()).optional().nullable(),
  display_order: z.number().int().min(0).default(0),
  is_active: z.boolean().optional().default(true),
});

export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);

    const { data, error } = await supabase
      .from("referral_faqs")
      .select("*")
      .order("display_order", { ascending: true })
      .order("created_at", { ascending: true });

    if (error) {
      // If table doesn't exist, return empty array
      if (error.code === "42P01") {
        return successResponse([]);
      }
      throw error;
    }

    return successResponse(data || []);
  } catch (error) {
    return handleApiError(error, "Failed to fetch referral FAQs");
  }
}

export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const body = faqSchema.parse(await request.json());

    const { data: row, error } = await (supabase.from("referral_faqs") as any)
      .insert({
        question: body.question,
        answer: body.answer_type === "text" ? body.answer : null,
        answer_type: body.answer_type,
        answer_list: body.answer_type === "list" ? body.answer_list : null,
        display_order: body.display_order,
        is_active: body.is_active ?? true,
      })
      .select()
      .single();

    if (error) {
      // If table doesn't exist, return error with instructions
      if (error.code === "42P01") {
        return handleApiError(
          new Error("referral_faqs table does not exist. Please run the migration first."),
          "Database table not found",
          "TABLE_NOT_FOUND",
          500
        );
      }
      throw error;
    }

    await writeAuditLog({
      actor_user_id: user.id,
      actor_role: user.role,
      action: "create",
      entity_type: "referral_faq",
      entity_id: row.id,
      metadata: { question: body.question },
    });

    return successResponse(row);
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(error, "Invalid request", "VALIDATION_ERROR", 400);
    }
    return handleApiError(error, "Failed to create referral FAQ");
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseServer } from '@/lib/supabase/server';
import { requireRoleInApi, successResponse, handleApiError } from '@/lib/supabase/api-helpers';
import { z } from 'zod';

const referralSettingsSchema = z.object({
  referral_amount: z.number().min(0).optional(),
  referral_message: z.string().min(1).optional(),
  referral_currency: z.string().length(3).optional(),
  is_enabled: z.boolean().optional(),
});

const REFERRAL_SETTINGS_ID = '00000000-0000-0000-0000-000000000001';
const DEFAULT_REFERRAL_SETTINGS = {
  referral_amount: 50,
  referral_message: 'Join Beautonomi and get rewarded! Use my referral link to get started.',
  referral_currency: 'ZAR',
  is_enabled: true,
};

/**
 * GET /api/admin/referrals
 * Get referral settings (single-row table by fixed id).
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = await getSupabaseServer(request);

    const { data: referralSettings, error } = await supabase
      .from('referral_settings')
      .select('*')
      .eq('id', REFERRAL_SETTINGS_ID)
      .maybeSingle();

    if (error) throw error;
    if (!referralSettings) return successResponse(DEFAULT_REFERRAL_SETTINGS);

    return successResponse({
      referral_amount: referralSettings.referral_amount ?? 50,
      referral_message: referralSettings.referral_message || DEFAULT_REFERRAL_SETTINGS.referral_message,
      referral_currency: referralSettings.referral_currency || 'ZAR',
      is_enabled: referralSettings.is_enabled !== false,
    });
  } catch (error) {
    return handleApiError(error, 'Failed to fetch referral settings');
  }
}

/**
 * PATCH /api/admin/referrals
 * 
 * Update referral settings
 */
export async function PATCH(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    const validatedData = referralSettingsSchema.parse(body);

    const { data: settings, error } = await supabase
      .from('referral_settings')
      .upsert(
        {
          id: REFERRAL_SETTINGS_ID,
          referral_amount: validatedData.referral_amount ?? 50,
          referral_message: validatedData.referral_message || 'Join Beautonomi and get rewarded! Use my referral link to get started.',
          referral_currency: validatedData.referral_currency || 'ZAR',
          is_enabled: validatedData.is_enabled !== false,
          updated_at: new Date().toISOString(),
        },
        { onConflict: 'id' }
      )
      .select()
      .single();

    if (error) {
      throw error;
    }

    return successResponse(settings);
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        new Error(error.issues.map((e: any) => e.message).join(', ')),
        'Validation failed',
        'VALIDATION_ERROR',
        400
      );
    }
    return handleApiError(error, 'Failed to update referral settings');
  }
}

import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRole, unauthorizedResponse } from "@/lib/auth/requireRole";
import { successResponse, errorResponse, handleApiError, notFoundResponse } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";
import { z } from "zod";

const processRefundSchema = z.object({
  refund_amount: z.number().positive(),
  refund_reason: z.string().min(1),
  notes: z.string().optional().nullable(),
});

/**
 * GET /api/admin/refunds/[id]
 * 
 * Get a single refund by ID
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = getSupabaseAdmin();
    const { id } = await params;

    const { data: refund, error } = await supabase
      .from("payment_transactions")
      .select(`
        id,
        booking_id,
        transaction_type,
        amount,
        refund_amount,
        refund_reference,
        refund_reason,
        refunded_at,
        refunded_by,
        status,
        created_at,
        booking:bookings(
          id,
          booking_number,
          status,
          total_amount,
          customer_id,
          provider_id,
          customer:users!bookings_customer_id_fkey(id, full_name, email),
          provider:providers!bookings_provider_id_fkey(id, business_name)
        ),
        refunded_by_user:users!payment_transactions_refunded_by_fkey(id, full_name, email)
      `)
      .eq("id", id)
      .single();

    if (error || !refund) {
      return notFoundResponse("Refund not found");
    }

    return successResponse(refund);
  } catch (error) {
    return handleApiError(error, "Failed to fetch refund");
  }
}

/**
 * POST /api/admin/refunds/[id]
 *
 * Process a refund: always credits the customer's wallet (they can request payout
 * or use the balance for the next booking). Updates payment_transactions and
 * booking_refunds so totals stay in sync.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = getSupabaseAdmin();
    const { id } = await params;
    const body = await request.json();

    const validationResult = processRefundSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400
      );
    }

    const { data: transaction } = await supabase
      .from("payment_transactions")
      .select("id, booking_id, amount, status, transaction_type")
      .eq("id", id)
      .single();

    if (!transaction) {
      return notFoundResponse("Transaction not found");
    }

    if (transaction.status === "refunded" || transaction.status === "partially_refunded") {
      return errorResponse(
        "Transaction already refunded",
        "ALREADY_REFUNDED",
        400
      );
    }

    const { refund_amount, refund_reason, notes } = validationResult.data;
    const txnAmount = parseFloat(transaction.amount || "0");
    if (refund_amount > txnAmount) {
      return errorResponse(
        "Refund amount cannot exceed transaction amount",
        "INVALID_AMOUNT",
        400
      );
    }

    const { data: booking } = await supabase
      .from("bookings")
      .select("id, customer_id, booking_number, currency")
      .eq("id", transaction.booking_id)
      .single();

    if (!booking) {
      return notFoundResponse("Booking not found");
    }

    const customerId = (booking as { customer_id: string }).customer_id;
    const bookingNumber = (booking as { booking_number: string }).booking_number;
    const currency = (booking as { currency?: string }).currency || "ZAR";

    // 1. Credit customer wallet (refunds always go to wallet; they can request payout or use for next booking)
    const { error: walletError } = await (supabase.rpc as any)("wallet_credit_admin", {
      p_user_id: customerId,
      p_amount: refund_amount,
      p_currency: currency,
      p_description: `Refund for booking ${bookingNumber}: ${refund_reason}`,
      p_reference_id: id,
      p_reference_type: "refund",
    });

    if (walletError) {
      console.error("Wallet credit failed:", walletError);
      return errorResponse(
        "Failed to credit customer wallet",
        "WALLET_ERROR",
        500
      );
    }

    const refundReference = `wallet_refund_${id}_${Date.now()}`;
    const isFullRefund = refund_amount >= txnAmount;

    // 2. Update payment_transactions
    const updateData: any = {
      refund_amount,
      refund_reason,
      refund_reference: refundReference,
      refunded_at: new Date().toISOString(),
      refunded_by: auth.user.id,
      status: isFullRefund ? "refunded" : "partially_refunded",
    };

    const { data: updatedTransaction, error } = await supabase
      .from("payment_transactions")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (error) throw error;

    // 3. Record in booking_refunds so update_booking_payment_status trigger keeps totals in sync
    await (supabase.from("booking_refunds") as any).insert({
      booking_id: transaction.booking_id,
      amount: refund_amount,
      reason: refund_reason,
      refund_method: "store_credit",
      status: "completed",
      created_by: auth.user.id,
    });

    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as any).role || "superadmin",
      action: "admin.refund.process",
      entity_type: "payment_transaction",
      entity_id: id,
      metadata: { refund_amount, refund_reason, notes, wallet_credit: true },
    });

    // 4. Notify customer
    try {
      const { sendToUser } = await import("@/lib/notifications/onesignal");
      await sendToUser(customerId, {
        title: "Refund added to wallet",
        message: `A refund of ${currency} ${refund_amount.toFixed(2)} for booking ${bookingNumber} has been added to your wallet. Use it for your next booking or request a payout.`,
        data: { type: "refund_processed", booking_id: transaction.booking_id, refund_reference: refundReference },
        url: "/account-settings/wallet",
      });
    } catch (notifErr) {
      console.error("Refund notification failed:", notifErr);
    }

    return successResponse(updatedTransaction);
  } catch (error) {
    return handleApiError(error, "Failed to process refund");
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseAdmin } from '@/lib/supabase/admin';
import { requireRoleInApi, successResponse, handleApiError } from '@/lib/supabase/api-helpers';

export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = getSupabaseAdmin();
    
    const { searchParams } = new URL(request.url);
    const period = searchParams.get('period') || '30d';
    const startDateParam = searchParams.get('start_date');
    const endDateParam = searchParams.get('end_date');

    const now = new Date();
    let startDate: Date;
    let endDate: Date = now;

    if (startDateParam && endDateParam) {
      startDate = new Date(startDateParam);
      endDate = new Date(endDateParam);
    } else {
      switch (period) {
        case '7d':
          startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
          break;
        case '30d':
          startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
          break;
        case '90d':
          startDate = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
          break;
        case '1y':
          startDate = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000);
          break;
        default:
          startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
      }
    }

    // Get bookings
    const { data: bookings } = await supabase
      .from('bookings')
      .select('scheduled_at, status, provider_id')
      .gte('scheduled_at', startDate.toISOString())
      .lte('scheduled_at', endDate.toISOString());

    const bookingsByDay: Record<string, number> = {};
    const bookingsByStatus: Record<string, number> = {};
    const bookingsByProvider: Record<string, { count: number; provider_name: string }> = {};

    let totalBookings = 0;
    let completed = 0;
    let cancelled = 0;
    let noShow = 0;

    (bookings || []).forEach((booking: any) => {
      const date = new Date(booking.scheduled_at).toISOString().split('T')[0];
      
      // By day
      bookingsByDay[date] = (bookingsByDay[date] || 0) + 1;

      // By status
      bookingsByStatus[booking.status] = (bookingsByStatus[booking.status] || 0) + 1;

      // By provider
      if (booking.provider_id) {
        if (!bookingsByProvider[booking.provider_id]) {
          bookingsByProvider[booking.provider_id] = { count: 0, provider_name: 'Unknown' };
        }
        bookingsByProvider[booking.provider_id].count += 1;
      }

      totalBookings += 1;
      if (booking.status === 'completed') completed += 1;
      if (booking.status === 'cancelled') cancelled += 1;
      if (booking.status === 'no_show') noShow += 1;
    });

    // Get provider names
    const providerIds = Object.keys(bookingsByProvider);
    if (providerIds.length > 0) {
      const { data: providers } = await supabase
        .from('providers')
        .select('id, business_name')
        .in('id', providerIds);

      (providers || []).forEach((p: any) => {
        if (bookingsByProvider[p.id]) {
          bookingsByProvider[p.id].provider_name = p.business_name;
        }
      });
    }

    // Fill missing dates
    const bookingsByDayArray = [];
    const current = new Date(startDate);
    while (current <= endDate) {
      const dateStr = current.toISOString().split('T')[0];
      bookingsByDayArray.push({
        date: dateStr,
        count: bookingsByDay[dateStr] || 0,
      });
      current.setDate(current.getDate() + 1);
    }

    const completionRate = totalBookings > 0 ? (completed / totalBookings) * 100 : 0;
    const cancellationRate = totalBookings > 0 ? (cancelled / totalBookings) * 100 : 0;
    const noShowRate = totalBookings > 0 ? (noShow / totalBookings) * 100 : 0;

    return successResponse({
      period,
      totalBookings,
      bookingsByDay: bookingsByDayArray,
      bookingsByStatus: Object.entries(bookingsByStatus).map(([status, count]) => ({
        status,
        count,
        percentage: totalBookings > 0 ? (count / totalBookings) * 100 : 0,
      })),
      bookingsByProvider: Object.entries(bookingsByProvider).map(([provider_id, data]) => ({
        provider_id,
        ...data,
      })).sort((a, b) => b.count - a.count),
      completionRate,
      cancellationRate,
      noShowRate,
    });
  } catch (error) {
    return handleApiError(error, 'Failed to load booking report');
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseAdmin } from '@/lib/supabase/admin';
import { requireRoleInApi, successResponse, handleApiError } from '@/lib/supabase/api-helpers';

export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = getSupabaseAdmin();

    const { searchParams } = new URL(request.url);
    const period = searchParams.get('period') || '30d';
    const startDateParam = searchParams.get('start_date');
    const endDateParam = searchParams.get('end_date');

    const now = new Date();
    let startDate: Date;
    let endDate: Date = now;

    if (startDateParam && endDateParam) {
      startDate = new Date(startDateParam);
      endDate = new Date(endDateParam);
    } else {
      switch (period) {
        case '7d':
          startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
          break;
        case '30d':
          startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
          break;
        case '90d':
          startDate = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
          break;
        case '1y':
          startDate = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000);
          break;
        default:
          startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
      }
    }

    const startISO = startDate.toISOString();
    const endISO = endDate.toISOString();

    // Customers (role = customer)
    const { data: customers } = await supabase
      .from('users')
      .select('id, full_name, email, created_at')
      .eq('role', 'customer');

    const customerIds = (customers || []).map((c: { id: string }) => c.id);

    // Bookings in period by customer
    const { data: bookings } = customerIds.length > 0
      ? await supabase
          .from('bookings')
          .select('id, customer_id, scheduled_at, total_amount, status')
          .in('customer_id', customerIds)
          .gte('scheduled_at', startISO)
          .lte('scheduled_at', endISO)
      : { data: [] };

    const bookingsByCustomer: Record<string, { count: number; total_amount: number }> = {};
    (bookings || []).forEach((b: { customer_id: string; total_amount?: number; status: string }) => {
      const id = b.customer_id;
      if (!bookingsByCustomer[id]) bookingsByCustomer[id] = { count: 0, total_amount: 0 };
      bookingsByCustomer[id].count += 1;
      if (b.total_amount) bookingsByCustomer[id].total_amount += Number(b.total_amount);
    });

    const customersWithMetrics = (customers || []).map((c: any) => {
      const data = bookingsByCustomer[c.id] || { count: 0, total_amount: 0 };
      return {
        customer_id: c.id,
        customer_name: c.full_name || c.email || 'Unknown',
        bookings_count: data.count,
        total_spent: data.total_amount,
      };
    });

    const sorted = customersWithMetrics.sort((a, b) => b.total_spent - a.total_spent);
    const totalCustomers = sorted.length;
    const customersWithBookings = sorted.filter((c) => c.bookings_count > 0).length;

    return successResponse({
      period,
      totalCustomers,
      customersWithBookings,
      customers: sorted,
    });
  } catch (error) {
    return handleApiError(error, 'Failed to load customer report');
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseAdmin } from '@/lib/supabase/admin';
import { requireRoleInApi, successResponse, handleApiError } from '@/lib/supabase/api-helpers';

export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = getSupabaseAdmin();

    const { searchParams } = new URL(request.url);
    const period = searchParams.get('period') || '30d';
    const startDateParam = searchParams.get('start_date');
    const endDateParam = searchParams.get('end_date');

    const now = new Date();
    let startDate: Date;
    let endDate: Date = now;

    if (startDateParam && endDateParam) {
      startDate = new Date(startDateParam);
      endDate = new Date(endDateParam);
    } else {
      switch (period) {
        case '7d':
          startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
          break;
        case '30d':
          startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
          break;
        case '90d':
          startDate = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
          break;
        case '1y':
          startDate = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000);
          break;
        default:
          startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
      }
    }

    const startISO = startDate.toISOString();
    const endISO = endDate.toISOString();

    // All providers with basic info
    const { data: providers } = await supabase
      .from('providers')
      .select('id, business_name, owner_name, status, rating_average, created_at');

    const providerIds = (providers || []).map((p: { id: string }) => p.id);

    // Bookings in period (count + revenue via completed bookings)
    const { data: bookings } = providerIds.length > 0
      ? await supabase
          .from('bookings')
          .select('provider_id, scheduled_at, total_amount, status')
          .in('provider_id', providerIds)
          .gte('scheduled_at', startISO)
          .lte('scheduled_at', endISO)
      : { data: [] };

    const bookingsByProvider: Record<string, { count: number; revenue: number }> = {};
    (bookings || []).forEach((b: { provider_id: string; total_amount?: number; status: string }) => {
      const id = b.provider_id;
      if (!bookingsByProvider[id]) bookingsByProvider[id] = { count: 0, revenue: 0 };
      bookingsByProvider[id].count += 1;
      if (b.status === 'completed' && b.total_amount) {
        bookingsByProvider[id].revenue += Number(b.total_amount);
      }
    });

    // Provider earnings from finance_transactions for period (more accurate revenue)
    const { data: txRows } = providerIds.length > 0
      ? await supabase
          .from('finance_transactions')
          .select('provider_id, net, amount')
          .in('provider_id', providerIds)
          .in('transaction_type', ['provider_earnings', 'travel_fee', 'tip'])
          .gte('created_at', startISO)
          .lte('created_at', endISO)
      : { data: [] };

    const revenueByProvider: Record<string, number> = {};
    (txRows || []).forEach((t: { provider_id: string; net?: number; amount?: number }) => {
      const id = t.provider_id;
      if (!revenueByProvider[id]) revenueByProvider[id] = 0;
      revenueByProvider[id] += Number(t.net ?? t.amount ?? 0);
    });

    const providersWithMetrics = (providers || []).map((p: any) => {
      const bookingsData = bookingsByProvider[p.id] || { count: 0, revenue: 0 };
      const txRevenue = revenueByProvider[p.id] ?? 0;
      return {
        provider_id: p.id,
        provider_name: p.business_name || p.owner_name || 'Unknown',
        status: p.status,
        rating_average: Number(p.rating_average) || 0,
        bookings_count: bookingsData.count,
        revenue: txRevenue > 0 ? txRevenue : bookingsData.revenue,
      };
    });

    const sorted = providersWithMetrics.sort((a, b) => b.revenue - a.revenue);
    const totalProviders = sorted.length;
    const activeCount = sorted.filter((p) => p.status === 'active').length;

    return successResponse({
      period,
      totalProviders,
      activeProviders: activeCount,
      providers: sorted,
    });
  } catch (error) {
    return handleApiError(error, 'Failed to load provider report');
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseAdmin } from '@/lib/supabase/admin';
import { requireRoleInApi, successResponse, handleApiError } from '@/lib/supabase/api-helpers';

export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = getSupabaseAdmin();

    const { searchParams } = new URL(request.url);
    const period = searchParams.get('period') || '30d';
    const startDateParam = searchParams.get('start_date');
    const endDateParam = searchParams.get('end_date');

    const now = new Date();
    let startDate: Date;
    let endDate: Date = now;

    if (startDateParam && endDateParam) {
      startDate = new Date(startDateParam);
      endDate = new Date(endDateParam);
    } else {
      switch (period) {
        case '7d':
          startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
          break;
        case '30d':
          startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
          break;
        case '90d':
          startDate = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
          break;
        case '1y':
          startDate = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000);
          break;
        default:
          startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
      }
    }

    // Get revenue by day
    const { data: bookings } = await supabase
      .from('bookings')
      .select('scheduled_at, total_amount, status, provider_id')
      .gte('scheduled_at', startDate.toISOString())
      .lte('scheduled_at', endDate.toISOString())
      .in('status', ['completed', 'confirmed']);

    const revenueByDay: Record<string, { revenue: number; bookings: number }> = {};
    const revenueByProvider: Record<string, { revenue: number; bookings: number; provider_name: string }> = {};
    const revenueByStatus: Record<string, { revenue: number; bookings: number }> = {};

    let totalRevenue = 0;

    (bookings || []).forEach((booking: any) => {
      const date = new Date(booking.scheduled_at).toISOString().split('T')[0];
      const amount = booking.total_amount || 0;

      // By day
      if (!revenueByDay[date]) {
        revenueByDay[date] = { revenue: 0, bookings: 0 };
      }
      revenueByDay[date].revenue += amount;
      revenueByDay[date].bookings += 1;

      // By provider
      if (booking.provider_id) {
        if (!revenueByProvider[booking.provider_id]) {
          revenueByProvider[booking.provider_id] = { revenue: 0, bookings: 0, provider_name: 'Unknown' };
        }
        revenueByProvider[booking.provider_id].revenue += amount;
        revenueByProvider[booking.provider_id].bookings += 1;
      }

      // By status
      if (!revenueByStatus[booking.status]) {
        revenueByStatus[booking.status] = { revenue: 0, bookings: 0 };
      }
      revenueByStatus[booking.status].revenue += amount;
      revenueByStatus[booking.status].bookings += 1;

      totalRevenue += amount;
    });

    // Get provider names
    const providerIds = Object.keys(revenueByProvider);
    if (providerIds.length > 0) {
      const { data: providers } = await supabase
        .from('providers')
        .select('id, business_name')
        .in('id', providerIds);

      (providers || []).forEach((p: any) => {
        if (revenueByProvider[p.id]) {
          revenueByProvider[p.id].provider_name = p.business_name;
        }
      });
    }

    // Fill missing dates
    const revenueByDayArray = [];
    const current = new Date(startDate);
    while (current <= endDate) {
      const dateStr = current.toISOString().split('T')[0];
      revenueByDayArray.push({
        date: dateStr,
        revenue: revenueByDay[dateStr]?.revenue || 0,
        bookings: revenueByDay[dateStr]?.bookings || 0,
      });
      current.setDate(current.getDate() + 1);
    }

    // Get gift card metrics
    // Gift card sales
    const { data: salesTransactions } = await supabase
      .from("finance_transactions")
      .select("amount, created_at")
      .eq("transaction_type", "gift_card_sale")
      .gte("created_at", startDate.toISOString())
      .lte("created_at", endDate.toISOString());

    // Gift card redemptions
    const { data: redemptions } = await supabase
      .from("gift_card_redemptions")
      .select("amount, captured_at, created_at")
      .eq("status", "captured")
      .not("captured_at", "is", null)
      .gte("captured_at", startDate.toISOString())
      .lte("captured_at", endDate.toISOString());

    // Active gift cards (outstanding liability)
    const { data: activeGiftCards } = await supabase
      .from("gift_cards")
      .select("balance")
      .eq("is_active", true)
      .gt("balance", 0);

    const totalSales = (salesTransactions || []).reduce((sum, t) => sum + Number(t.amount || 0), 0);
    const totalRedemptions = (redemptions || []).reduce((sum, r) => sum + Number(r.amount || 0), 0);
    const outstandingLiability = (activeGiftCards || []).reduce((sum, g) => sum + Number(g.balance || 0), 0);

    // Get total orders for redemption rate
    const { data: orders } = await supabase
      .from("gift_card_orders")
      .select("id")
      .eq("status", "paid")
      .gte("created_at", startDate.toISOString())
      .lte("created_at", endDate.toISOString());

    const totalOrders = (orders || []).length;
    const totalRedemptionCount = (redemptions || []).length;
    const redemptionRate = totalOrders > 0 ? (totalRedemptionCount / totalOrders) * 100 : 0;

    // Sales by day
    const salesByDay: Record<string, { sales: number; count: number }> = {};
    (salesTransactions || []).forEach((t) => {
      const date = new Date(t.created_at).toISOString().split("T")[0];
      if (!salesByDay[date]) {
        salesByDay[date] = { sales: 0, count: 0 };
      }
      salesByDay[date].sales += Number(t.amount || 0);
      salesByDay[date].count += 1;
    });

    // Redemptions by day
    const redemptionsByDay: Record<string, { redemptions: number; count: number }> = {};
    (redemptions || []).forEach((r) => {
      const date = new Date(r.captured_at || r.created_at).toISOString().split("T")[0];
      if (!redemptionsByDay[date]) {
        redemptionsByDay[date] = { redemptions: 0, count: 0 };
      }
      redemptionsByDay[date].redemptions += Number(r.amount || 0);
      redemptionsByDay[date].count += 1;
    });

    // Fill missing dates
    const salesByDayArray = [];
    const redemptionsByDayArray = [];
    const iterDate = new Date(startDate);
    while (iterDate <= endDate) {
      const dateStr = iterDate.toISOString().split("T")[0];
      salesByDayArray.push({
        date: dateStr,
        sales: salesByDay[dateStr]?.sales || 0,
        count: salesByDay[dateStr]?.count || 0,
      });
      redemptionsByDayArray.push({
        date: dateStr,
        redemptions: redemptionsByDay[dateStr]?.redemptions || 0,
        count: redemptionsByDay[dateStr]?.count || 0,
      });
      iterDate.setDate(iterDate.getDate() + 1);
    }

    return successResponse({
      period,
      totalRevenue,
      revenueByDay: revenueByDayArray,
      revenueByProvider: Object.values(revenueByProvider).sort((a, b) => b.revenue - a.revenue),
      revenueByService: [], // Can be enhanced later
      revenueByStatus: Object.entries(revenueByStatus).map(([status, data]) => ({
        status,
        ...data,
      })),
      giftCardMetrics: {
        totalSales,
        totalRedemptions,
        outstandingLiability,
        redemptionRate,
        salesByDay: salesByDayArray,
        redemptionsByDay: redemptionsByDayArray,
      },
    });
  } catch (error) {
    return handleApiError(error, 'Failed to load revenue report');
  }
}

import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRole, unauthorizedResponse } from "@/lib/auth/requireRole";
import { successResponse, errorResponse, handleApiError, notFoundResponse } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";
import { z } from "zod";

const updateReviewSchema = z.object({
  is_visible: z.boolean().optional(),
  is_flagged: z.boolean().optional(),
  flagged_reason: z.string().optional().nullable(),
  comment: z.string().optional().nullable(),
});

/**
 * GET /api/admin/reviews/[id]
 * 
 * Get a single review by ID
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = getSupabaseAdmin();
    const { id } = await params;

    const { data: review, error } = await supabase
      .from("reviews")
      .select(`
        id,
        booking_id,
        customer_id,
        provider_id,
        rating,
        comment,
        service_ratings,
        staff_rating,
        provider_response,
        provider_response_at,
        is_verified,
        is_flagged,
        flagged_reason,
        flagged_by,
        is_visible,
        helpful_count,
        created_at,
        updated_at,
        customer:users!reviews_customer_id_fkey(id, full_name, email, avatar_url),
        provider:providers!reviews_provider_id_fkey(id, business_name, thumbnail_url, avatar_url),
        booking:bookings(id, booking_number, status)
      `)
      .eq("id", id)
      .single();

    if (error || !review) {
      return notFoundResponse("Review not found");
    }

    return successResponse(review);
  } catch (error) {
    return handleApiError(error, "Failed to fetch review");
  }
}

/**
 * PATCH /api/admin/reviews/[id]
 * 
 * Update a review (moderate, flag, hide, edit)
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = getSupabaseAdmin();
    const { id } = await params;
    const body = await request.json();

    // Validate request body
    const validationResult = updateReviewSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400
      );
    }

    // Verify review exists
    const { data: existingReview } = await supabase
      .from("reviews")
      .select("id, provider_id, customer_id")
      .eq("id", id)
      .single();

    if (!existingReview) {
      return notFoundResponse("Review not found");
    }

    const updateData: any = {};
    if (validationResult.data.is_visible !== undefined) {
      updateData.is_visible = validationResult.data.is_visible;
    }
    if (validationResult.data.is_flagged !== undefined) {
      updateData.is_flagged = validationResult.data.is_flagged;
      if (validationResult.data.flagged_reason !== undefined) {
        updateData.flagged_reason = validationResult.data.flagged_reason;
      }
      if (validationResult.data.is_flagged) {
        updateData.flagged_by = auth.user.id;
      } else {
        updateData.flagged_reason = null;
        updateData.flagged_by = null;
      }
    }
    if (validationResult.data.comment !== undefined) {
      updateData.comment = validationResult.data.comment;
    }

    const { data: updatedReview, error } = await supabase
      .from("reviews")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (error) {
      throw error;
    }

    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as any).role || "superadmin",
      action: "admin.review.update",
      entity_type: "review",
      entity_id: id,
      metadata: updateData,
    });

    return successResponse(updatedReview);
  } catch (error) {
    return handleApiError(error, "Failed to update review");
  }
}

/**
 * DELETE /api/admin/reviews/[id]
 * 
 * Delete a review
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = getSupabaseAdmin();
    const { id } = await params;

    // Verify review exists
    const { data: review } = await supabase
      .from("reviews")
      .select("id, provider_id, customer_id")
      .eq("id", id)
      .single();

    if (!review) {
      return notFoundResponse("Review not found");
    }

    const { error } = await supabase.from("reviews").delete().eq("id", id);

    if (error) {
      throw error;
    }

    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as any).role || "superadmin",
      action: "admin.review.delete",
      entity_type: "review",
      entity_id: id,
      metadata: {},
    });

    return successResponse({ success: true });
  } catch (error) {
    return handleApiError(error, "Failed to delete review");
  }
}

