const DEFAULTS = {
  password_policy: {
    min_length: 8,
    require_uppercase: true,
    require_lowercase: true,
    require_numbers: true,
    require_special_chars: false,
    max_age_days: 90,
  },
  two_factor: {
    enabled: false,
    required_for_admins: false,
  },
  rate_limiting: {
    enabled: true,
    max_attempts: 5,
    window_minutes: 15,
    lockout_minutes: 30,
  },
