/**
 * GET /api/admin/settings
 *
 * Get platform settings
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);

    const supabase = getSupabaseAdmin();
    const defaultSettings = getDefaultPlatformSettings();

    // Get latest platform_settings row (table has id, settings, is_active; no key/value)
    try {
      const { data: settings, error: settingsError } = await (supabase
        .from("platform_settings") as any)
        .select("*")
        .order("updated_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (settingsError || !settings) {
        return successResponse(defaultSettings, 200);
      }

      if (settings && (settings as any).settings) {
        // Merge secret "configured" markers for superadmin UI
        const merged = { ...(settings as any).settings } as PlatformSettings;
        try {
          const { data: secretRow } = await (supabase.from("platform_secrets") as any)
            .select("paystack_secret_key, paystack_public_key, paystack_webhook_secret, onesignal_rest_api_key, mapbox_access_token, amplitude_secret_key, google_calendar_client_id, google_calendar_client_secret, outlook_client_id, outlook_client_secret")
            .limit(1)
            .maybeSingle();

          if (secretRow?.paystack_secret_key) merged.paystack.secret_key = "***";
          if (secretRow?.paystack_public_key) merged.paystack.public_key = "***";
          if (secretRow?.paystack_webhook_secret) merged.paystack.webhook_secret = "***" as any;
          if (secretRow?.onesignal_rest_api_key) merged.onesignal.rest_api_key = "***";
          if (secretRow?.mapbox_access_token) merged.mapbox.access_token = "***";
          if (secretRow?.amplitude_secret_key) merged.amplitude.secret_key = "***" as any;
          if (secretRow?.google_calendar_client_id) merged.calendar_integrations.google.client_id = "***";
          if (secretRow?.google_calendar_client_secret) merged.calendar_integrations.google.client_secret = "***";
          if (secretRow?.outlook_client_id) merged.calendar_integrations.outlook.client_id = "***";
          if (secretRow?.outlook_client_secret) merged.calendar_integrations.outlook.client_secret = "***";
        } catch {
          // ignore (table may not exist yet in dev)
        }

        return successResponse(merged, 200);
      }
    } catch (error) {
      // Table might not exist, return default settings
      console.warn("Platform settings table may not exist, using defaults:", error);
    }

    return successResponse(defaultSettings, 200);
  } catch (error) {
    return handleApiError(error, "Failed to load settings");
  }
}

/**
 * PATCH /api/admin/settings
 * 
 * Update platform settings
 */
export async function PATCH(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['superadmin'], request);

    const supabase = getSupabaseAdmin();
    const body = (await request.json()) as Partial<PlatformSettings>;

    // Load existing settings and merge with defaults + body so partial payloads always validate
    const { data: existingRow } = await (supabase
      .from("platform_settings") as any)
      .select("id, settings")
      .order("updated_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    const defaults = getDefaultPlatformSettings();
    const existing = (existingRow as any)?.settings || {};
    const settings: PlatformSettings = { ...defaults, ...existing, ...body } as PlatformSettings;

    // Validate required top-level sections after merge
    if (!settings.branding || !settings.localization || !settings.payouts || !settings.notifications || !settings.payment_types || !settings.paystack || !settings.onesignal || !settings.mapbox || !settings.amplitude || !settings.google || !settings.calendar_integrations || !settings.apps || !settings.features) {
      return errorResponse("Invalid settings structure: missing required section (branding, localization, payouts, notifications, payment_types, paystack, onesignal, mapbox, amplitude, google, calendar_integrations, apps, features)", "VALIDATION_ERROR", 400);
    }

    // Store sensitive secrets in platform_secrets (NOT in public platform_settings JSON)
    // NOTE: platform_settings has public-read policies in migrations, so secrets must not live there.
    const hasAnySecrets =
      !!settings.paystack.secret_key ||
      !!settings.paystack.public_key ||
      !!settings.paystack.webhook_secret ||
      !!settings.onesignal.rest_api_key ||
      !!settings.mapbox.access_token ||
      !!settings.amplitude.secret_key ||
      !!settings.calendar_integrations.google.client_id ||
      !!settings.calendar_integrations.google.client_secret ||
      !!settings.calendar_integrations.outlook.client_id ||
      !!settings.calendar_integrations.outlook.client_secret;

    if (hasAnySecrets) {
      // Upsert singleton row
      const { data: existingSecretRow } = await (supabase.from("platform_secrets") as any)
        .select("id")
        .limit(1)
        .maybeSingle();

      const secretPayload: Record<string, any> = {
        paystack_secret_key: settings.paystack.secret_key || null,
        paystack_public_key: settings.paystack.public_key || null,
        paystack_webhook_secret: settings.paystack.webhook_secret || null,
        onesignal_rest_api_key: settings.onesignal.rest_api_key || null,
        mapbox_access_token: settings.mapbox.access_token || null,
        amplitude_secret_key: settings.amplitude.secret_key || null,
        google_calendar_client_id: settings.calendar_integrations.google.client_id || null,
        google_calendar_client_secret: settings.calendar_integrations.google.client_secret || null,
        outlook_client_id: settings.calendar_integrations.outlook.client_id || null,
        outlook_client_secret: settings.calendar_integrations.outlook.client_secret || null,
        updated_at: new Date().toISOString(),
      };

      if (existingSecretRow?.id) {
        await (supabase.from("platform_secrets") as any).update(secretPayload).eq("id", existingSecretRow.id);
      } else {
        await (supabase.from("platform_secrets") as any).insert(secretPayload);
      }
    }
    // NOTE: process.env mutations do not persist reliably in serverless deployments.
    // Persist config via database instead.

    // Remove secrets before storing public settings JSON
    settings.paystack.secret_key = "";
    settings.paystack.public_key = "";
    settings.paystack.webhook_secret = undefined;
    settings.onesignal.rest_api_key = "";
    settings.mapbox.access_token = "";
    settings.amplitude.secret_key = undefined;
    settings.calendar_integrations.google.client_id = "";
    settings.calendar_integrations.google.client_secret = "";
    settings.calendar_integrations.outlook.client_id = "";
    settings.calendar_integrations.outlook.client_secret = "";

    const existingSettings = existingRow;

    if (existingSettings && (existingSettings as any).id) {
      // Update
      const { data: updatedSettings, error: updateError } = await (supabase
        .from("platform_settings") as any)
        .update({
          settings,
          updated_at: new Date().toISOString(),
        })
        .eq("id", (existingSettings as any).id)
        .select()
        .single();

      if (updateError || !updatedSettings) {
        throw updateError || new Error("Failed to update settings");
      }

      await writeAuditLog({
        actor_user_id: user.id,
        actor_role: (user as any).role || "superadmin",
        action: "admin.settings.update",
        entity_type: "platform_settings",
        entity_id: (existingSettings as any).id,
        metadata: {
          updated_at: new Date().toISOString(),
          has_secrets_update: hasAnySecrets,
        },
      });

      revalidateTag("platform-settings", "max");
      const updatedPayload = (updatedSettings as any).settings as PlatformSettings;
      return successResponse(updatedPayload, 200);
    } else {
      // Create
      const { data: newSettings, error: createError } = await (supabase
        .from("platform_settings") as any)
        .insert({
          settings,
        })
        .select()
        .single();

      if (createError || !newSettings) {
        throw createError || new Error("Failed to create settings");
      }

      await writeAuditLog({
        actor_user_id: user.id,
        actor_role: (user as any).role || "superadmin",
        action: "admin.settings.create",
        entity_type: "platform_settings",
        entity_id: (newSettings as any).id,
        metadata: {
          created_at: new Date().toISOString(),
          has_secrets_update: hasAnySecrets,
        },
      });

      revalidateTag("platform-settings", "max");
      const newPayload = (newSettings as any).settings as PlatformSettings;
      return successResponse(newPayload, 200);
    }
  } catch (error) {
    return handleApiError(error, "Failed to save settings");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";
import { z } from "zod";
import type { PlatformSalesDefaults, PlatformSalesConstraints } from "@/lib/platform-sales-settings";

const salesDefaultsSchema = z.object({
  tax_rate_percent: z.number().min(0).max(100).optional(),
  receipt_prefix: z.string().max(20).optional(),
  receipt_next_number: z.number().int().min(1).optional(),
  receipt_header: z.string().max(2000).nullable().optional(),
  receipt_footer: z.string().max(2000).nullable().optional(),
  gift_cards_enabled: z.boolean().optional(),
  gift_card_terms: z.string().nullable().optional(),
  service_charge_name: z.string().optional(),
  service_charge_rate: z.number().min(0).optional(),
  upselling_enabled: z.boolean().optional(),
});

const salesConstraintsSchema = z.object({
  max_tax_rate_percent: z.number().min(0).max(100).optional(),
  required_receipt_fields: z.array(z.string()).optional(),
  max_receipt_prefix_length: z.number().int().min(1).max(50).optional(),
  min_receipt_next_number: z.number().int().min(1).optional(),
  max_receipt_header_length: z.number().int().min(1).optional(),
  max_receipt_footer_length: z.number().int().min(1).optional(),
});

const updateSalesSettingsSchema = z.object({
  defaults: salesDefaultsSchema.optional(),
  constraints: salesConstraintsSchema.optional(),
});

/**
 * GET /api/admin/settings/sales
 * 
 * Get platform sales defaults and constraints
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);

    const supabase = await getSupabaseServer(request);

    const { data: settings, error } = await supabase
      .from("platform_settings")
      .select("settings")
      .eq("is_active", true)
      .single();

    if (error || !settings) {
      // Return defaults if no settings exist
      return successResponse({
        defaults: {
          tax_rate_percent: 0,
          receipt_prefix: "REC",
          receipt_next_number: 1,
          receipt_header: null,
          receipt_footer: null,
          gift_cards_enabled: false,
          gift_card_terms: null,
          service_charge_name: "Service Charge",
          service_charge_rate: 0,
          upselling_enabled: false,
        },
        constraints: {
          max_tax_rate_percent: 30,
          required_receipt_fields: ["receipt_number", "date", "total"],
          max_receipt_prefix_length: 20,
          min_receipt_next_number: 1,
          max_receipt_header_length: 2000,
          max_receipt_footer_length: 2000,
        },
      });
    }

    const platformSettings = (settings as any).settings || {};
    const salesSettings = platformSettings.sales || {};

    // Merge with defaults
    const defaults: PlatformSalesDefaults = {
      tax_rate_percent: 0,
      receipt_prefix: "REC",
      receipt_next_number: 1,
      receipt_header: null,
      receipt_footer: null,
      gift_cards_enabled: false,
      gift_card_terms: null,
      service_charge_name: "Service Charge",
      service_charge_rate: 0,
      upselling_enabled: false,
      ...salesSettings.defaults,
    };

    const constraints: PlatformSalesConstraints = {
      max_tax_rate_percent: 30,
      required_receipt_fields: ["receipt_number", "date", "total"],
      max_receipt_prefix_length: 20,
      min_receipt_next_number: 1,
      max_receipt_header_length: 2000,
      max_receipt_footer_length: 2000,
      ...salesSettings.constraints,
    };

    return successResponse({ defaults, constraints });
  } catch (error) {
    return handleApiError(error, "Failed to load sales settings");
  }
}

/**
 * PATCH /api/admin/settings/sales
 * 
 * Update platform sales defaults and constraints
 */
export async function PATCH(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['superadmin'], request);

    const supabase = await getSupabaseServer(request);
    const body = await request.json();
    const validated = updateSalesSettingsSchema.parse(body);

    // Get existing settings
    const { data: existingSettings, error: fetchError } = await supabase
      .from("platform_settings")
      .select("id, settings")
      .eq("is_active", true)
      .single();

    let platformSettings: any = {};
    let settingsId: string | null = null;

    if (existingSettings && !fetchError) {
      platformSettings = (existingSettings as any).settings || {};
      settingsId = (existingSettings as any).id;
    }

    // Update sales settings
    if (!platformSettings.sales) {
      platformSettings.sales = {};
    }

    if (validated.defaults) {
      platformSettings.sales.defaults = {
        ...platformSettings.sales.defaults,
        ...validated.defaults,
      };
    }

    if (validated.constraints) {
      platformSettings.sales.constraints = {
        ...platformSettings.sales.constraints,
        ...validated.constraints,
      };
    }

    // Upsert settings
    if (settingsId) {
      const { data: updatedSettings, error: updateError } = await supabase
        .from("platform_settings")
        .update({
          settings: platformSettings,
          updated_at: new Date().toISOString(),
        })
        .eq("id", settingsId)
        .select("settings")
        .single();

      if (updateError || !updatedSettings) {
        throw updateError || new Error("Failed to update settings");
      }

      await writeAuditLog({
        actor_user_id: user.id,
        actor_role: (user as any).role || "superadmin",
        action: "admin.settings.sales.update",
        entity_type: "platform_settings",
        entity_id: settingsId,
        metadata: {
          updated_fields: Object.keys(validated),
          updated_at: new Date().toISOString(),
        },
      });

      const salesSettings = (updatedSettings as any).settings?.sales || {};
      return successResponse({
        defaults: salesSettings.defaults || {},
        constraints: salesSettings.constraints || {},
      });
    } else {
      // Create new settings
      const { data: newSettings, error: createError } = await supabase
        .from("platform_settings")
        .insert({
          settings: platformSettings,
        })
        .select("id, settings")
        .single();

      if (createError || !newSettings) {
        throw createError || new Error("Failed to create settings");
      }

      await writeAuditLog({
        actor_user_id: user.id,
        actor_role: (user as any).role || "superadmin",
        action: "admin.settings.sales.create",
        entity_type: "platform_settings",
        entity_id: (newSettings as any).id,
        metadata: {
          created_at: new Date().toISOString(),
        },
      });

      const salesSettings = (newSettings as any).settings?.sales || {};
      return successResponse({
        defaults: salesSettings.defaults || {},
        constraints: salesSettings.constraints || {},
      });
    }
  } catch (error) {
    if (error instanceof z.ZodError) {
      return errorResponse("Invalid request data", "VALIDATION_ERROR", 400, error.issues);
    }
    return handleApiError(error, "Failed to update sales settings");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole } from "@/lib/supabase/auth-server";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRole(["superadmin"]);
    const supabase = await getSupabaseServer(request);
    const { id } = await params;

    const { data, error } = await supabase
      .from("sms_templates")
