/**
 * GET /api/admin/taxes
 * 
 * Get tax configuration and rates
 */
export async function GET(request: NextRequest) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);
    const providerId = searchParams.get("provider_id");

    // Get tax rates from reference_data
    const { data: taxRates, error: taxError } = await supabase
      .from("reference_data")
      .select("*")
      .eq("type", "tax_rate")
      .order("display_order", { ascending: true });

    if (taxError) throw taxError;

    // Get provider-specific tax rates if provider_id is provided
    let providerTaxRate = null;
    if (providerId) {
      const { data: provider } = await supabase
        .from("providers")
        .select("id, business_name, tax_rate_percent")
        .eq("id", providerId)
        .single();

      if (provider) {
        providerTaxRate = {
          provider_id: provider.id,
          provider_name: provider.business_name,
          tax_rate_percent: provider.tax_rate_percent || 0,
        };
      }
    }

    // Get platform-wide tax statistics
    const { data: bookings } = await supabase
      .from("bookings")
      .select("tax_amount, total_amount, status")
      .eq("status", "completed");

    const totalTaxCollected = bookings?.reduce((sum, b) => sum + (Number(b.tax_amount) || 0), 0) || 0;
    const totalRevenue = bookings?.reduce((sum, b) => sum + (Number(b.total_amount) || 0), 0) || 0;

    return successResponse({
      tax_rates: taxRates || [],
      provider_tax_rate: providerTaxRate,
      statistics: {
        total_tax_collected: totalTaxCollected,
        total_revenue: totalRevenue,
        tax_percentage: totalRevenue > 0 ? (totalTaxCollected / totalRevenue) * 100 : 0,
        total_bookings: bookings?.length || 0,
      },
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch tax data");
  }
}

/**
 * POST /api/admin/taxes
 * 
 * Create or update tax rate
 */
export async function POST(request: NextRequest) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = await getSupabaseServer(request);
    const body = await request.json();
    const { provider_id, tax_rate_percent } = body;

    if (provider_id) {
      // Update provider-specific tax rate
      const { error } = await supabase
        .from("providers")
        .update({ tax_rate_percent: tax_rate_percent || 0 })
        .eq("id", provider_id);

      if (error) throw error;

      await writeAuditLog({
        actor_user_id: auth.user.id,
        actor_role: (auth.user as any).role || "superadmin",
        action: "admin.taxes.update_provider",
        entity_type: "provider",
        entity_id: provider_id,
        metadata: { tax_rate_percent },
      });

      return successResponse({ success: true });
    } else {
      // Create new tax rate in reference_data
      const { error } = await supabase
        .from("reference_data")
        .insert({
          type: "tax_rate",
          code: body.code,
          name: body.name,
          description: body.description,
          display_order: body.display_order || 999,
          metadata: { rate: body.rate, included: body.included || false },
        });

      if (error) throw error;

      await writeAuditLog({
        actor_user_id: auth.user.id,
        actor_role: (auth.user as any).role || "superadmin",
        action: "admin.taxes.create_rate",
        entity_type: "reference_data",
        entity_id: null,
        metadata: body,
      });

      return successResponse({ success: true });
    }
  } catch (error) {
    return handleApiError(error, "Failed to update tax configuration");
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseAdmin } from '@/lib/supabase/admin';
import { requireRoleInApi, successResponse, handleApiError } from '@/lib/supabase/api-helpers';
import { z } from 'zod';

const travelFeesSchema = z.object({
  default_rate_per_km: z.number().min(0).optional(),
  default_minimum_fee: z.number().min(0).optional(),
  default_maximum_fee: z.number().min(0).nullable().optional(),
  default_currency: z.string().optional(),
  allow_provider_customization: z.boolean().optional(),
  provider_min_rate_per_km: z.number().min(0).optional(),
  provider_max_rate_per_km: z.number().min(0).optional(),
  provider_min_minimum_fee: z.number().min(0).optional(),
  provider_max_minimum_fee: z.number().min(0).optional(),
});

/**
 * GET /api/admin/travel-fees
 * 
 * Get platform travel fee settings
 * Allows providers to read limits (for validation), but only superadmins can modify
 */
export async function GET(request: NextRequest) {
  try {
    // Allow providers and superadmins to read platform limits
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin']);
    const supabase = getSupabaseAdmin();

    const { data: platformSettings, error } = await supabase
      .from('platform_settings')
      .select('settings')
      .eq('is_active', true)
      .order('updated_at', { ascending: false })
      .limit(1)
      .maybeSingle();

    if (error && error.code !== 'PGRST116') {
      throw error;
    }

    const travelFees = platformSettings?.settings?.travel_fees || {
      default_rate_per_km: 8.00,
      default_minimum_fee: 20.00,
      default_maximum_fee: null,
      default_currency: 'ZAR',
      allow_provider_customization: true,
      provider_min_rate_per_km: 0.00,
      provider_max_rate_per_km: 50.00,
      provider_min_minimum_fee: 0.00,
      provider_max_minimum_fee: 100.00,
    };

    // For providers, only return the limits they need for validation
    // For superadmins, return full settings
    if (user.role === 'superadmin') {
      return successResponse(travelFees);
    } else {
      // Return only the limits providers need
      return successResponse({
        provider_min_rate_per_km: travelFees.provider_min_rate_per_km || 0.00,
        provider_max_rate_per_km: travelFees.provider_max_rate_per_km || 50.00,
        provider_min_minimum_fee: travelFees.provider_min_minimum_fee || 0.00,
        provider_max_minimum_fee: travelFees.provider_max_minimum_fee || 100.00,
        allow_provider_customization: travelFees.allow_provider_customization !== false,
      });
    }
  } catch (error) {
    return handleApiError(error, 'Failed to fetch travel fee settings');
  }
}

/**
 * PATCH /api/admin/travel-fees
 * 
 * Update platform travel fee settings
 */
export async function PATCH(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = getSupabaseAdmin();
    const body = await request.json();

    const validatedData = travelFeesSchema.parse(body);

    // Get latest platform_settings row
    const { data: existing, error: _fetchError } = await supabase
      .from('platform_settings')
      .select('id, settings')
      .order('updated_at', { ascending: false })
      .limit(1)
      .maybeSingle();

    const currentSettings = (existing as any)?.settings || {};
    const currentTravelFees = currentSettings.travel_fees || {};

    const updatedTravelFees = {
      ...currentTravelFees,
      ...validatedData,
    };

    const newSettings = {
      ...currentSettings,
      travel_fees: updatedTravelFees,
    };

    if (existing && (existing as any).id) {
      const { data: updated, error: updateError } = await supabase
        .from('platform_settings')
        .update({
          settings: newSettings,
          updated_at: new Date().toISOString(),
        })
        .eq('id', (existing as any).id)
        .select('settings')
        .single();

      if (updateError) throw updateError;
      return successResponse((updated as any).settings.travel_fees);
    }

    // No row: create one
    const { data: created, error: createError } = await supabase
      .from('platform_settings')
      .insert({
        settings: {
          travel_fees: {
            default_rate_per_km: 8.00,
            default_minimum_fee: 20.00,
            default_maximum_fee: null,
            default_currency: 'ZAR',
            allow_provider_customization: true,
            provider_min_rate_per_km: 0.00,
            provider_max_rate_per_km: 50.00,
            provider_min_minimum_fee: 0.00,
            provider_max_minimum_fee: 100.00,
            ...validatedData,
          },
        },
        is_active: true,
      })
      .select('settings')
      .single();

    if (createError) throw createError;
    return successResponse((created as any).settings.travel_fees);
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        new Error(error.issues.map((e: any) => e.message).join(', ')),
        'Validation failed',
        'VALIDATION_ERROR',
        400
      );
    }
    return handleApiError(error, 'Failed to update travel fee settings');
  }
}

import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import {
  successResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";
import { requireRoleInApi } from "@/lib/supabase/api-helpers";

/**
 * GET /api/admin/user-reports
 * List user reports (customer vs provider). Superadmin only.
 * Query: status=pending|resolved|dismissed, limit, offset
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseAdmin();

    const { searchParams } = new URL(request.url);
    const status = searchParams.get("status");
    const limit = Math.min(parseInt(searchParams.get("limit") || "50", 10), 100);
    const offset = Math.max(parseInt(searchParams.get("offset") || "0", 10), 0);

    let query = supabase
      .from("user_reports")
      .select(
        "id, reporter_id, reported_user_id, report_type, description, booking_id, status, resolution_notes, resolved_by, resolved_at, created_at, updated_at"
      )
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (status && ["pending", "resolved", "dismissed"].includes(status)) {
      query = query.eq("status", status);
    }

    const { data: rows, error } = await query;

    if (error) return handleApiError(error, "Failed to fetch reports");

    const userIds = [
      ...new Set(
        (rows || []).flatMap((r: any) => [r.reporter_id, r.reported_user_id])
      ),
    ].filter(Boolean);

    let userMap: Record<string, { id: string; full_name: string | null; email: string }> = {};
    if (userIds.length > 0) {
      const { data: users } = await supabase
        .from("users")
        .select("id, full_name, email")
        .in("id", userIds);
      userMap = (users || []).reduce(
        (acc: Record<string, any>, u: any) => {
          acc[u.id] = { id: u.id, full_name: u.full_name, email: u.email };
          return acc;
        },
        {}
      );
    }

    const reports = (rows || []).map((r: any) => ({
      id: r.id,
      reporter_id: r.reporter_id,
      reported_user_id: r.reported_user_id,
      report_type: r.report_type,
      description: r.description,
      booking_id: r.booking_id,
      status: r.status,
      resolution_notes: r.resolution_notes,
      resolved_by: r.resolved_by,
      resolved_at: r.resolved_at,
      created_at: r.created_at,
      updated_at: r.updated_at,
      reporter: userMap[r.reporter_id] ?? null,
      reported: userMap[r.reported_user_id] ?? null,
    }));

    return successResponse({
      data: reports,
      has_more: reports.length === limit,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch reports");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);

    if (!supabase) {
      return successResponse([]);
    }

    const { id } = await params;

    // Fetch bookings for the user - check both user_id and customer_id columns
    const { data: bookings, error: bookingsError } = await supabase
      .from("bookings")
      .select(`
        id,
        status,
        scheduled_at,
        total_amount,
        created_at,
        customer_id,
        provider_id,
        service_id
      `)
      .or(`customer_id.eq.${id},user_id.eq.${id}`)
      .order("created_at", { ascending: false })
      .limit(100);

    if (bookingsError) {
      console.error("Error fetching bookings:", bookingsError);
      return successResponse([]);
    }

    // Fetch related data separately to avoid join issues
    const providerIds = [...new Set((bookings || []).map((b: any) => b.provider_id).filter(Boolean))];
    const serviceIds = [...new Set((bookings || []).map((b: any) => b.service_id).filter(Boolean))];

    const { data: providers } = providerIds.length > 0
      ? await supabase
          .from("providers")
          .select("id, business_name, full_name")
          .in("id", providerIds)
      : { data: [] };

    const { data: services } = serviceIds.length > 0
      ? await supabase
          .from("master_services")
          .select("id, name")
          .in("id", serviceIds)
      : { data: [] };

    const providerMap = new Map((providers || []).map((p: any) => [p.id, p]));
    const serviceMap = new Map((services || []).map((s: any) => [s.id, s]));

    // Transform the data to match expected format
    const transformedBookings = (bookings || []).map((booking: any) => {
      const provider = providerMap.get(booking.provider_id);
      const service = serviceMap.get(booking.service_id);
      
      return {
        id: booking.id,
        status: booking.status,
        service_name: service?.name || "Unknown Service",
        provider_name:
          provider?.business_name ||
          provider?.full_name ||
          "Unknown Provider",
        scheduled_at: booking.scheduled_at,
        total_amount: booking.total_amount || 0,
        created_at: booking.created_at,
      };
    });

    return successResponse(transformedBookings);
  } catch (error) {
    return handleApiError(error, "Failed to fetch user bookings");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi } from "@/lib/supabase/api-helpers";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);

    if (!supabase) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Supabase client not available",
            code: "SERVER_ERROR",
          },
        },
        { status: 500 }
      );
    }

    const { id } = await params;

    // Fetch user data
    const { data: user, error: userError } = await supabase
      .from("users")
      .select("*")
      .eq("id", id)
      .single();

    if (userError || !user) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "User not found",
            code: "USER_NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    // Fetch user bookings
    const { data: bookings } = await supabase
      .from("bookings")
      .select("*")
      .eq("user_id", id);

    // Convert to CSV format
    const csvRows = [];
    csvRows.push("User Data");
    csvRows.push("Field,Value");
    csvRows.push(`ID,${user.id}`);
    csvRows.push(`Email,${user.email || ""}`);
    csvRows.push(`Full Name,${user.full_name || ""}`);
    csvRows.push(`Phone,${user.phone || ""}`);
    csvRows.push(`Role,${user.role || ""}`);
    csvRows.push(`Created At,${user.created_at || ""}`);
    csvRows.push(`Updated At,${user.updated_at || ""}`);
    csvRows.push("");

    if (bookings && bookings.length > 0) {
      csvRows.push("Bookings");
      csvRows.push("ID,Status,Scheduled At,Total Amount,Created At");
      bookings.forEach((booking) => {
        csvRows.push(
          `${booking.id},${booking.status || ""},${booking.scheduled_at || ""},${booking.total_amount || 0},${booking.created_at || ""}`
        );
      });
    }

    const csvContent = csvRows.join("\n");

    return new NextResponse(csvContent, {
      headers: {
        "Content-Type": "text/csv",
        "Content-Disposition": `attachment; filename="user-${id}-export-${new Date().toISOString().split("T")[0]}.csv"`,
      },
    });
  } catch (error: any) {
    console.error("Error exporting user data:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: error.message || "Failed to export user data",
          code: "SERVER_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { requireRoleInApi, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { cookies } from "next/headers";

const MAX_IMPERSONATIONS_PER_HOUR = 5;

/**
 * Check rate limit: max impersonations per admin per hour.
 * Returns true if the admin is within the allowed limit.
 */
async function checkImpersonationRateLimit(adminId: string): Promise<{ allowed: boolean; count: number }> {
  const supabase = getSupabaseAdmin();
  const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000).toISOString();

  const { count, error } = await supabase
    .from("audit_logs")
    .select("id", { count: "exact", head: true })
    .eq("actor_user_id", adminId)
    .eq("action", "admin_impersonation_start")
    .gte("created_at", oneHourAgo);

  if (error) {
    console.error("Rate limit check failed:", error);
    // Fail open but log ΓÇö don't block admins due to DB errors
    return { allowed: true, count: 0 };
  }

  const currentCount = count ?? 0;
  return { allowed: currentCount < MAX_IMPERSONATIONS_PER_HOUR, count: currentCount };
}

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user: adminUser } = await requireRoleInApi(["superadmin"], request);

    const { id } = await params;

    // Parse request body and require a reason
    let body: { reason?: string } = {};
    try {
      body = await request.json();
    } catch {
      // Body may be empty in legacy callers ΓÇö we now require it
    }

    const reason = body.reason?.trim();
    if (!reason || reason.length < 3) {
      return errorResponse(
        "A reason is required for impersonation (minimum 3 characters)",
        "REASON_REQUIRED",
        400
      );
    }

    // Rate limiting: max 5 impersonations per admin per hour
    const rateLimit = await checkImpersonationRateLimit(adminUser.id);
    if (!rateLimit.allowed) {
      return errorResponse(
        `Rate limit exceeded: ${rateLimit.count}/${MAX_IMPERSONATIONS_PER_HOUR} impersonations in the last hour. Please wait before trying again.`,
        "RATE_LIMIT_EXCEEDED",
        429
      );
    }

    // Collect request metadata for audit trail
    const ipAddress =
      request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ||
      request.headers.get("x-real-ip") ||
      "unknown";
    const userAgent = request.headers.get("user-agent") || "unknown";

    // Use service role client for admin operations
    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    // Get the target user
    const { data: targetUser, error: targetError } = await supabaseAdmin.auth.admin.getUserById(id);

    if (targetError || !targetUser) {
      return errorResponse("Target user not found", "USER_NOT_FOUND", 404);
    }

    // Generate a sign-in link for the target user using recovery type (works better for impersonation)
    const { data: linkData, error: linkError } = await supabaseAdmin.auth.admin.generateLink({
      type: "recovery",
      email: targetUser.user.email!,
      options: {
        redirectTo: `${request.nextUrl.origin}/auth/callback`,
      },
    });

    if (linkError || !linkData) {
      console.error("Error generating impersonation link:", linkError);
      return errorResponse("Failed to create impersonation session", "SESSION_ERROR", 500);
    }

    // Log the full response to debug
    console.log("Link data received:", JSON.stringify(linkData, null, 2));

    // Extract the action link from the response
    // Supabase returns: { properties: { action_link: "..." } }
    let actionLink: string | null = null;

    if (linkData && typeof linkData === 'object') {
      const data = linkData as any;
      // Try properties.action_link first (most common)
      if (data.properties?.action_link) {
        actionLink = data.properties.action_link;
      } else if (data.properties?.actionLink) {
        actionLink = data.properties.actionLink;
      } else if (data.action_link) {
        actionLink = data.action_link;
      } else if (data.actionLink) {
        actionLink = data.actionLink;
      } else if (typeof data.properties === 'string') {
        actionLink = data.properties;
      }
    } else if (typeof linkData === 'string') {
      actionLink = linkData;
    }

    if (!actionLink) {
      console.error("Link data structure:", JSON.stringify(linkData, null, 2));
      return errorResponse("Failed to extract action link from response", "LINK_EXTRACTION_ERROR", 500);
    }

    console.log("Action link extracted:", actionLink);

    // Extract token_hash from the action link
    let token: string | null = null;
    try {
      // Parse the URL to extract token_hash
      const linkUrl = new URL(actionLink);
      token = linkUrl.searchParams.get("token_hash");

      // If not found, try token parameter
      if (!token) {
        token = linkUrl.searchParams.get("token");
      }
    } catch {
      // If parsing fails, try regex extraction
      console.log("Error parsing URL, trying regex extraction");
      const tokenMatch = actionLink.match(/[?&]token_hash=([^&?#]+)/) || 
                        actionLink.match(/[?&]token=([^&?#]+)/);
      if (tokenMatch) {
        token = decodeURIComponent(tokenMatch[1]);
      }
    }

    if (!token) {
      console.error("Link data:", JSON.stringify(linkData, null, 2));
      console.error("Action link:", actionLink);
      return errorResponse("Failed to extract token from link. Please check server logs for details.", "TOKEN_ERROR", 500);
    }

    console.log("Token extracted successfully:", token.substring(0, 20) + "...");

    // Store impersonation info in cookies
    const cookieStore = await cookies();
    cookieStore.set("impersonation_token", token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      maxAge: 60 * 60, // 1 hour
    });

    // Store original admin user ID so we can return to it
    cookieStore.set("impersonation_admin_id", adminUser.id, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      maxAge: 60 * 60, // 1 hour
    });

    // Enhanced audit log: admin_impersonation_start
    await writeAuditLog({
      actor_user_id: adminUser.id,
      actor_role: "superadmin",
      action: "admin_impersonation_start",
      entity_type: "user",
      entity_id: id,
      metadata: {
        target_email: targetUser.user.email,
        target_user_id: id,
        reason,
        ip_address: ipAddress,
        user_agent: userAgent,
      },
    });

    // Return redirect URL - use recovery type since we generated a recovery link
    return successResponse({
      success: true,
      url: `/auth/callback?token_hash=${token}&type=recovery`,
    });
  } catch (error: any) {
    console.error("Error in impersonation:", error);
    return handleApiError(error, "Failed to impersonate user");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi } from "@/lib/supabase/api-helpers";

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(["superadmin"], request);
    const supabase = await getSupabaseServer(request);

    if (!supabase) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Supabase client not available",
            code: "SERVER_ERROR",
          },
        },
        { status: 500 }
      );
    }

    const { id } = await params;
    const body = await request.json();
    const { new_password } = body;

    if (!new_password || new_password.length < 8) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Password must be at least 8 characters",
            code: "VALIDATION_ERROR",
          },
        },
        { status: 400 }
      );
    }

    // Use Supabase Admin API to update password
    // Note: This requires service role key or admin API access
    const { error } = await supabase.auth.admin.updateUserById(id, {
      password: new_password,
    });

    if (error) {
      console.error("Error updating password:", error);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: error.message || "Failed to update password",
            code: "PASSWORD_UPDATE_ERROR",
          },
        },
        { status: 500 }
      );
    }

    return NextResponse.json({
      data: { success: true },
      error: null,
    });
  } catch (error: any) {
    console.error("Error in password reset:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: error.message || "Failed to reset password",
          code: "SERVER_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { z } from "zod";
import type { UserRole } from "@/types/beautonomi";
import { writeAuditLog } from "@/lib/audit/audit";

const roleUpdateSchema = z.object({
  role: z.enum(["customer", "provider_owner", "provider_staff", "superadmin"]),
});

/**
 * PUT /api/admin/users/[id]/role
 * 
 * Update user role (audit logged)
 */
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['superadmin'], request);

    const { id } = await params;
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    // Validate request body
    const validationResult = roleUpdateSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues.map((issue) => ({ path: issue.path, message: issue.message }))
      );
    }

    // Get current user data
    const { data: currentUser } = await supabase
      .from("users")
      .select("role, full_name, email")
      .eq("id", id)
      .single();

    if (!currentUser) {
      return notFoundResponse("User not found");
    }

    const newRole = validationResult.data.role as UserRole;
    const oldRole = (currentUser as any).role as UserRole;

    // Prevent changing own role from superadmin
    if (id === user.id && oldRole === "superadmin" && newRole !== "superadmin") {
      return errorResponse("Cannot change your own role from superadmin", "SELF_ROLE_CHANGE", 400);
    }

    // Update user role
    const { data: updatedUser, error } = await (supabase
      .from("users") as any)
      .update({ role: newRole })
      .eq("id", id)
      .select()
      .single();

    if (error || !updatedUser) {
      throw error || new Error("Failed to update user role");
    }

    await writeAuditLog({
      actor_user_id: user.id,
      actor_role: (user as any).role || "superadmin",
      action: "admin.user.role.update",
      entity_type: "user",
      entity_id: id,
      metadata: { role: { from: oldRole, to: newRole } },
    });

    return successResponse(updatedUser);
  } catch (error) {
    return handleApiError(error, "Failed to update user role");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRoleInApi, successResponse, notFoundResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { z } from "zod";

/**
 * GET /api/admin/users/[id]
 * 
 * Get detailed user information
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(['superadmin'], request);

    const { id } = await params;
    const supabase = await getSupabaseServer(request);

    const { data: userData, error } = await supabase
      .from("users")
      .select("*")
      .eq("id", id)
      .single();

    if (error || !userData) {
      return notFoundResponse("User not found");
    }

    // Get user stats based on role
    const stats: any = {};

    if ((userData as any).role === "customer") {
      const { count: bookingCount } = await supabase
        .from("bookings")
        .select("*", { count: "exact", head: true })
        .eq("customer_id", id);

      // Get total spent
      const { data: bookings } = await supabase
        .from("bookings")
        .select("total_amount")
        .eq("customer_id", id)
        .in("status", ["completed", "confirmed"]);

      const totalSpent = bookings?.reduce((sum, b) => sum + (b.total_amount || 0), 0) || 0;

      // Get last booking date
      const { data: lastBooking } = await supabase
        .from("bookings")
        .select("scheduled_at")
        .eq("customer_id", id)
        .order("scheduled_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      stats.total_bookings = bookingCount || 0;
      stats.total_spent = totalSpent;
      stats.last_booking_date = lastBooking?.scheduled_at || null;
    } else if ((userData as any).role === "provider_owner") {
      const { count: providerCount } = await supabase
        .from("providers")
        .select("*", { count: "exact", head: true })
        .eq("user_id", id);

      stats.provider_count = providerCount || 0;
    }

    return successResponse({
      ...(userData as Record<string, any>),
      stats,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch user");
  }
}

/**
 * PATCH /api/admin/users/[id]
 * 
 * Update user (suspend/reactivate)
 */
const updateUserSchema = z.object({
  deactivated_at: z.string().nullable().optional(),
  deactivation_reason: z.string().nullable().optional(),
  role: z.enum(["customer", "provider", "admin", "superadmin"]).optional(),
  email_notifications_enabled: z.boolean().optional(),
  sms_notifications_enabled: z.boolean().optional(),
  push_notifications_enabled: z.boolean().optional(),
});

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['superadmin'], request);

    const { id } = await params;
    const body = await request.json();
    const validationResult = updateUserSchema.safeParse(body);

    if (!validationResult.success) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Validation failed",
            code: "VALIDATION_ERROR",
            details: validationResult.error.issues.map((issue) => ({
              path: issue.path.join("."),
              message: issue.message,
            })),
          },
        },
        { status: 400 }
      );
    }

    const supabase = await getSupabaseServer(request);

    // Check if user exists
    const { data: existingUser, error: fetchError } = await supabase
      .from("users")
      .select("id, role")
      .eq("id", id)
      .single();

    if (fetchError || !existingUser) {
      return notFoundResponse("User not found");
    }

    // Prevent superadmins from modifying other superadmins (except themselves)
    if (existingUser.role === "superadmin" && id !== user.id) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Cannot modify another superadmin account",
            code: "PERMISSION_DENIED",
          },
        },
        { status: 403 }
      );
    }

    // Build update object
    const updateData: any = {};
    
    if (validationResult.data.deactivated_at !== undefined) {
      const at = validationResult.data.deactivated_at
        ? new Date(validationResult.data.deactivated_at).toISOString()
        : null;
      updateData.deactivated_at = at;
      updateData.deactivated_by = at ? 'admin' : null;
    }

    if (validationResult.data.deactivation_reason !== undefined) {
      updateData.deactivation_reason = validationResult.data.deactivation_reason;
    }
    
    if (validationResult.data.role !== undefined) {
      updateData.role = validationResult.data.role;
    }
    
    if (validationResult.data.email_notifications_enabled !== undefined) {
      updateData.email_notifications_enabled = validationResult.data.email_notifications_enabled;
    }
    
    if (validationResult.data.sms_notifications_enabled !== undefined) {
      updateData.sms_notifications_enabled = validationResult.data.sms_notifications_enabled;
    }
    
    if (validationResult.data.push_notifications_enabled !== undefined) {
      updateData.push_notifications_enabled = validationResult.data.push_notifications_enabled;
    }

    // Update user
    const { data: updatedUser, error: updateError } = await supabase
      .from("users")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (updateError) {
      console.error("Error updating user:", updateError);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to update user",
            code: "UPDATE_ERROR",
            details: updateError.message,
          },
        },
        { status: 500 }
      );
    }

    // If user is being deactivated, also deactivate auth user
    if (updateData.deactivated_at) {
      const supabaseAdmin = getSupabaseAdmin();
      await supabaseAdmin.auth.admin.updateUserById(id, {
        ban_duration: "876000h", // ~100 years (effectively permanent)
      });
    } else if (updateData.deactivated_at === null) {
      // If user is being reactivated, unban auth user
      const supabaseAdmin = getSupabaseAdmin();
      await supabaseAdmin.auth.admin.updateUserById(id, {
        ban_duration: "0",
      });
    }

    return successResponse(updatedUser);
  } catch (error) {
    return handleApiError(error, "Failed to update user");
  }
}

/**
 * DELETE /api/admin/users/[id]
 * 
 * Permanently delete a user (superadmin only)
 * WARNING: This will permanently delete the user and all associated data
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['superadmin'], request);

    const { id } = await params;
    const supabase = await getSupabaseServer(request);

    // Check if user exists
    const { data: existingUser, error: fetchError } = await supabase
      .from("users")
      .select("id, role, email")
      .eq("id", id)
      .single();

    if (fetchError || !existingUser) {
      return notFoundResponse("User not found");
    }

    // Prevent superadmins from deleting themselves
    if (id === user.id) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Cannot delete your own account",
            code: "PERMISSION_DENIED",
          },
        },
        { status: 403 }
      );
    }

    // Prevent superadmins from deleting other superadmins
    if (existingUser.role === "superadmin") {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Cannot delete another superadmin account",
            code: "PERMISSION_DENIED",
          },
        },
        { status: 403 }
      );
    }

    // Use admin client to delete auth user (this will cascade delete user record)
    const supabaseAdmin = getSupabaseAdmin();
    const { error: deleteError } = await supabaseAdmin.auth.admin.deleteUser(id);

    if (deleteError) {
      console.error("Error deleting auth user:", deleteError);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to delete user",
            code: "DELETE_ERROR",
            details: deleteError.message,
          },
        },
        { status: 500 }
      );
    }

    return successResponse({
      id,
      deleted: true,
      message: "User deleted successfully",
    });
  } catch (error) {
    return handleApiError(error, "Failed to delete user");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole, unauthorizedResponse } from "@/lib/auth/requireRole";
import { successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";
import { z } from "zod";

const bulkActionSchema = z.object({
  user_ids: z.array(z.string().uuid()).min(1, "At least one user ID is required"),
  action: z.enum(["activate", "deactivate", "delete", "change_role"]),
  role: z.enum(["customer", "provider", "superadmin"]).optional(),
  reason: z.string().optional().nullable(),
});

/**
 * POST /api/admin/users/bulk
 * 
 * Perform bulk actions on users
 */
export async function POST(request: NextRequest) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    // Validate request body
    const validationResult = bulkActionSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    const { user_ids, action, role, reason } = validationResult.data;

    // Check if any selected users are superadmins (for delete/deactivate)
    if (action === "delete" || action === "deactivate") {
      const { data: superadmins } = await supabase
        .from("users")
        .select("id, email")
        .in("id", user_ids)
        .eq("role", "superadmin");

      if (superadmins && superadmins.length > 0) {
        return errorResponse(
          "Cannot delete or deactivate superadmin accounts",
          "INVALID_ACTION",
          400
        );
      }
    }

    let updateData: any = {};
    const results = { success: 0, failed: 0, errors: [] as string[] };

    switch (action) {
      case "activate":
        updateData = {
          deactivated_at: null,
          deactivation_reason: null,
        };
        break;
      case "deactivate":
        updateData = {
          deactivated_at: new Date().toISOString(),
          deactivation_reason: reason || "Bulk deactivation by admin",
        };
        break;
      case "change_role":
        if (!role) {
          return errorResponse(
            "Role is required for change_role action",
            "VALIDATION_ERROR",
            400
          );
        }
        updateData = { role };
        break;
      case "delete":
        // For delete, we'll handle it separately
        break;
    }

    // Perform bulk update or delete
    if (action === "delete") {
      // Delete users (cascade will handle related data)
      const { error: deleteError } = await supabase
        .from("users")
        .delete()
        .in("id", user_ids);

      if (deleteError) {
        throw deleteError;
      }

      results.success = user_ids.length;
    } else {
      // Bulk update
      const { error: updateError } = await supabase
        .from("users")
        .update(updateData)
        .in("id", user_ids);

      if (updateError) {
        throw updateError;
      }

      results.success = user_ids.length;
    }

    // Log audit trail
    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as any).role || "superadmin",
      action: `admin.users.bulk.${action}`,
      entity_type: "user",
      entity_id: user_ids.join(","),
      metadata: { user_ids, action, role, reason, count: user_ids.length },
    });

    return successResponse({
      success: true,
      results,
    });
  } catch (error) {
    return handleApiError(error, "Failed to perform bulk action");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, notFoundResponse } from "@/lib/supabase/api-helpers";
import { writeAuditLog } from "@/lib/audit/audit";
import { z } from "zod";

// Schema for verification review
const reviewSchema = z.object({
  status: z.enum(['approved', 'rejected']),
  rejection_reason: z.string().max(500).nullable().optional(),
});

/**
 * GET /api/admin/verifications/[id]
 * Get a specific verification
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const { id } = await params;
    const supabase = await getSupabaseServer(request);

    const { data: verification, error } = await supabase
      .from("user_verifications")
      .select(`
        *,
        user:users!user_verifications_user_id_fkey (
          id,
          full_name,
          email,
          phone,
          avatar_url
        ),
        reviewer:users!user_verifications_reviewed_by_fkey (
          id,
          full_name,
          email
        )
      `)
      .eq("id", id)
      .single();

    if (error) {
      if (error.code === 'PGRST116') {
        return notFoundResponse("Verification not found");
      }
      throw error;
    }

    return successResponse(verification);
  } catch (error) {
    return handleApiError(error, "Failed to fetch verification");
  }
}

/**
 * PATCH /api/admin/verifications/[id]
 * Review a verification (approve or reject)
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['superadmin'], request);
    const { id } = await params;
    const body = await request.json();
    const supabase = await getSupabaseServer(request);

    const validationResult = reviewSchema.safeParse(body);
    if (!validationResult.success) {
      return NextResponse.json(
        { error: "Validation failed", details: validationResult.error.issues },
        { status: 400 }
      );
    }

    const { status, rejection_reason } = validationResult.data;

    // Update verification
    const { data: verification, error: updateError } = await supabase
      .from("user_verifications")
      .update({
        status,
        rejection_reason: status === 'rejected' ? rejection_reason : null,
        reviewed_at: new Date().toISOString(),
        reviewed_by: user.id,
      })
      .eq("id", id)
      .select(`
        *,
        user:users!user_verifications_user_id_fkey (
          id,
          full_name,
          email
        )
      `)
      .single();

    if (updateError) {
      if (updateError.code === 'PGRST116') {
        return notFoundResponse("Verification not found");
      }
      throw updateError;
    }

    await writeAuditLog({
      actor_user_id: user.id,
      actor_role: (user as any).role || "superadmin",
      action: "admin.verification.review",
      entity_type: "user_verification",
      entity_id: id,
      metadata: { status, user_id: (verification as any)?.user_id, rejection_reason: status === "rejected" ? rejection_reason : null },
    });

    return successResponse(verification);
  } catch (error) {
    return handleApiError(error, "Failed to review verification");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/admin/verifications
 * Get all pending verifications (for admin review)
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(['superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);
    const status = searchParams.get("status") || "pending"; // Filter by status

    if (!supabase) {
      return successResponse([]);
    }

    // Fetch verifications
    let query = supabase
      .from("user_verifications")
      .select("*")
      .order("submitted_at", { ascending: false });

    if (status !== "all") {
      query = query.eq("status", status);
    }

    const { data: verifications, error } = await query;

    if (error) {
      console.error("Error fetching verifications:", error);
      return successResponse([]);
    }

    if (!verifications || verifications.length === 0) {
      return successResponse([]);
    }

    // Fetch related user data separately
    const userIds = [...new Set(verifications.map((v: any) => v.user_id).filter(Boolean))];
    const reviewerIds = [
      ...new Set(verifications.map((v: any) => v.reviewed_by).filter(Boolean)),
    ];

    const { data: users } = userIds.length > 0
      ? await supabase
          .from("users")
          .select("id, full_name, email, phone, avatar_url")
          .in("id", userIds)
      : { data: [] };

    const { data: reviewers } = reviewerIds.length > 0
      ? await supabase
          .from("users")
          .select("id, full_name, email")
          .in("id", reviewerIds)
      : { data: [] };

    const userMap = new Map((users || []).map((u: any) => [u.id, u]));
    const reviewerMap = new Map((reviewers || []).map((r: any) => [r.id, r]));

    // Combine data
    const enrichedVerifications = verifications.map((v: any) => ({
      ...v,
      user: userMap.get(v.user_id) || {
        id: v.user_id,
        full_name: "Unknown User",
        email: "N/A",
        phone: null,
      },
      reviewer: v.reviewed_by ? reviewerMap.get(v.reviewed_by) || null : null,
    }));

    return successResponse(enrichedVerifications);
  } catch (error) {
    return handleApiError(error, "Failed to fetch verifications");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole } from "@/lib/auth/requireRole";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const supabase = await getSupabaseServer(request);
    const result = await requireRole(["superadmin"]);

    if (!result) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const { id } = await params;

    const { data, error } = await supabase
      .from("webhook_endpoints")
      .select("*")
      .eq("id", id)
      .single();

    if (error) throw error;

    // Get recent events for this endpoint
    const { data: events } = await supabase
      .from("webhook_events")
      .select("*")
      .eq("endpoint_id", id)
      .order("created_at", { ascending: false })
      .limit(50);

    return NextResponse.json({
      endpoint: {
        ...data,
        secret: undefined, // Don't return secret
      },
      events: events || [],
    });
  } catch (error: any) {
    console.error("Error fetching webhook endpoint:", error);
    return NextResponse.json(
      { error: error.message || "Failed to fetch webhook endpoint" },
      { status: 500 }
    );
  }
}

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(["superadmin"], request);

    const supabase = await getSupabaseServer(request);
    const { id } = await params;

    const body = await request.json();
    const {
      name,
      url,
      events,
      is_active,
      retry_count,
      timeout_seconds,
      headers,
    } = body;

    const updateData: any = {};
    if (name !== undefined) updateData.name = name;
    if (url !== undefined) updateData.url = url;
    if (events !== undefined) updateData.events = events;
    if (is_active !== undefined) updateData.is_active = is_active;
    if (retry_count !== undefined) updateData.retry_count = retry_count;
    if (timeout_seconds !== undefined) updateData.timeout_seconds = timeout_seconds;
    if (headers !== undefined) updateData.headers = headers;

    const { data, error } = await supabase
      .from("webhook_endpoints")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (error) throw error;

    return successResponse({
      endpoint: {
        ...data,
        secret: undefined,
      },
    });
  } catch (error: any) {
    return handleApiError(error, "Failed to update webhook endpoint");
  }
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(["superadmin"], request);

    const supabase = await getSupabaseServer(request);
    const { id } = await params;

    const { error } = await supabase
      .from("webhook_endpoints")
      .delete()
      .eq("id", id);

    if (error) throw error;

    return successResponse({ success: true });
  } catch (error: any) {
    return handleApiError(error, "Failed to delete webhook endpoint");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, notFoundResponse, errorResponse } from "@/lib/supabase/api-helpers";
import crypto from "crypto";

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(["superadmin"], request);

    const supabase = await getSupabaseServer(request);

    const { id } = await params;

    const body = await request.json();
    const { test_payload } = body;

    // Get endpoint
    const { data: endpoint, error: endpointError } = await supabase
      .from("webhook_endpoints")
      .select("*")
      .eq("id", id)
      .single();

    if (endpointError || !endpoint) {
      return notFoundResponse("Webhook endpoint not found");
    }

    if (!endpoint.is_active) {
      return errorResponse("Webhook endpoint is not active", "VALIDATION_ERROR", 400);
    }

    // Create signature
    const timestamp = Math.floor(Date.now() / 1000);
    const payload = JSON.stringify(test_payload || { test: true, timestamp });
    const signature = crypto
      .createHmac("sha256", endpoint.secret)
      .update(`${timestamp}.${payload}`)
      .digest("hex");

    // Send test webhook
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), (endpoint.timeout_seconds || 30) * 1000);

    try {
      const response = await fetch(endpoint.url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-Webhook-Signature": signature,
          "X-Webhook-Timestamp": timestamp.toString(),
          ...(endpoint.headers || {}),
        },
        body: payload,
        signal: controller.signal,
      });

      clearTimeout(timeout);

      const responseText = await response.text();

      // Log the test event
      await supabase.from("webhook_events").insert({
        endpoint_id: endpoint.id,
        event_type: "test",
        payload: test_payload || { test: true },
        status: response.ok ? "success" : "failed",
        response_status: response.status,
        response_body: responseText,
        attempt_count: 1,
        source: "admin_test",
        sent_at: new Date().toISOString(),
      });

      return successResponse({
        success: response.ok,
        status: response.status,
        response: responseText,
        timestamp,
        signature,
      });
    } catch (fetchError: any) {
      clearTimeout(timeout);

      // Log failed test
      await supabase.from("webhook_events").insert({
        endpoint_id: endpoint.id,
        event_type: "test",
        payload: test_payload || { test: true },
        status: "failed",
        error_message: fetchError.message || "Request failed",
        attempt_count: 1,
        source: "admin_test",
      });

      throw fetchError;
    }
  } catch (error: any) {
    return handleApiError(error, "Failed to test webhook");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import crypto from "crypto";

export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(["superadmin"], request);

    const supabase = await getSupabaseServer(request);
    const { data, error } = await supabase
      .from("webhook_endpoints")
      .select("*")
      .order("created_at", { ascending: false });

    if (error) throw error;

    // Don't return secrets
    const safeData = (data || []).map((endpoint: any) => ({
      ...endpoint,
      secret: undefined, // Remove secret from response
    }));

    return successResponse({ endpoints: safeData });
  } catch (error: any) {
    return handleApiError(error, "Failed to fetch webhook endpoints");
  }
}

export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["superadmin"], request);

    const supabase = await getSupabaseServer(request);
    const body = await request.json();
    const {
      name,
      url,
      events,
      is_active,
      retry_count,
      timeout_seconds,
      headers,
    } = body;

    if (!name || !url) {
      return handleApiError(
        new Error("Name and URL are required"),
        "Name and URL are required",
        "VALIDATION_ERROR",
        400
      );
    }

    // Generate webhook secret
    const secret = crypto.randomBytes(32).toString("hex");

    const { data, error } = await supabase
      .from("webhook_endpoints")
      .insert({
        name,
        url,
        secret,
        events: events || [],
        is_active: is_active !== false,
        retry_count: retry_count || 3,
        timeout_seconds: timeout_seconds || 30,
        headers: headers || {},
        created_by: user.id,
      })
      .select()
      .single();

    if (error) throw error;

    // Return the secret only once (for display)
    return successResponse({
      endpoint: {
        ...data,
        secret, // Only returned on creation
      },
    }, 201);
  } catch (error: any) {
    return handleApiError(error, "Failed to create webhook endpoint");
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole, unauthorizedResponse } from "@/lib/auth/requireRole";
import { writeAuditLog } from "@/lib/audit/audit";

/**
 * POST /api/admin/webhooks/failures/[id]/retry
 * 
 * Retry a failed webhook event
 */
export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRole(["superadmin"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const { id } = await params;
    const supabase = await getSupabaseServer(request);

    // Get the failed webhook event
    const { data: webhookEvent, error: fetchError } = await supabase
      .from("webhook_events")
      .select("*")
      .eq("id", id)
      .eq("status", "failed")
      .single();

    if (fetchError || !webhookEvent) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Webhook event not found or not in failed state",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    const eventData = webhookEvent as any;

    // Reset status to processing and increment retry count
    const { data: updated, error: updateError } = await (supabase
      .from("webhook_events") as any)
      .update({
        status: "processing",
        retry_count: (eventData.retry_count || 0) + 1,
        error_message: null,
        error_stack: null,
      })
      .eq("id", id)
      .select()
      .single();

    if (updateError || !updated) {
      console.error("Error updating webhook event:", updateError);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to retry webhook",
            code: "UPDATE_ERROR",
          },
        },
        { status: 500 }
      );
    }

    // Re-deliver the webhook to its endpoint
    const { data: webhookEventData } = await supabase
      .from("webhook_events")
      .select("*")
      .eq("id", id)
      .single();

    if (!webhookEventData) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Webhook event not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    const eventPayload = webhookEventData as any;

    const { data: endpoint } = await supabase
      .from("webhook_endpoints")
      .select("url, secret, headers")
      .eq("id", eventPayload.endpoint_id)
      .single();

    if (!endpoint) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Webhook endpoint not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    const endpointData = endpoint as any;

    const response = await fetch(endpointData.url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Webhook-Secret": endpointData.secret || "",
        ...(endpointData.headers || {}),
      },
      body: JSON.stringify(eventPayload.payload),
    });

    await (supabase
      .from("webhook_events") as any)
      .update({
        status: response.ok ? "delivered" : "failed",
        response_code: response.status,
        last_attempt_at: new Date().toISOString(),
        retry_count: (eventPayload.retry_count || 0) + 1,
      })
      .eq("id", id);

    await writeAuditLog({
      actor_user_id: auth.user.id,
      actor_role: (auth.user as any).role || "superadmin",
      action: "admin.webhook.retry",
      entity_type: "webhook_event",
      entity_id: id,
      metadata: { endpoint_id: eventPayload.endpoint_id, delivered: response.ok, response_code: response.status },
    });

    return NextResponse.json({
      data: { id, retry_initiated: true, delivered: response.ok },
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/admin/webhooks/failures/[id]/retry:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to retry webhook",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { getProviderIdForUser } from "@/lib/supabase/api-helpers";
import { loadAvailabilityConstraints } from "@/lib/availability/load-constraints";
import { calculateAvailableSlots } from "@/lib/availability/calculate-slots";

/**
 * GET /api/availability
 *
 * Get available time slots for a staff member on a specific date.
 * Uses loadAvailabilityConstraints + calculateAvailableSlots (same pipeline as
 * portal/me reschedule). For duration, pass total blocked minutes (e.g. sum of
 * service durations + buffers) so slots match the book flow.
 * Query params: staffId, date, mode, duration, travelBuffer, avoidGaps
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const staffId = searchParams.get("staffId");
    const date = searchParams.get("date");
    const mode = searchParams.get("mode") || "salon";
    const duration = parseInt(searchParams.get("duration") || "60");
    const travelBuffer = parseInt(searchParams.get("travelBuffer") || "0");
    const avoidGaps = searchParams.get("avoidGaps") === "true";

    if (!date) {
      return successResponse({ date, slots: [] });
    }

    if (!staffId || staffId === "any") {
      return successResponse({ date, slots: [] });
    }

    const supabase = await getSupabaseServer();
    if (!supabase) {
      return handleApiError(new Error("Database connection failed"), "Failed to connect to database");
    }

    // --- Optional auth: enrich response for authenticated users ---
    let authenticatedProviderId: string | null = null;

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        authenticatedProviderId = await getProviderIdForUser(user.id, supabase);
      }
    } catch {
      // Auth is optional ΓÇö swallow errors and continue as public
    }

    // Load constraints (staff shifts, time blocks, existing bookings)
    const constraints = await loadAvailabilityConstraints(supabase, staffId, date);

    // If work hours are enabled but no staff shifts, return empty
    if (constraints.workHoursEnabled && constraints.staffShifts.length === 0) {
      return successResponse({ date, slots: [] });
    }

    // Calculate available slots
    const slots = calculateAvailableSlots(
      constraints,
      duration,
      date,
      {
        slotInterval: 15,
        avoidGaps,
        travelBuffer: mode === "mobile" ? travelBuffer : 0,
      }
    );

    // Build response ΓÇö enrich when the caller is an authenticated provider/staff member
    const response: Record<string, any> = {
      date,
      slots,
    };

    if (authenticatedProviderId) {
      // Authenticated provider/staff: include provider-specific context
      // so the front-end can show richer booking UI (e.g. internal notes, buffer info)
      response.provider_context = {
        provider_id: authenticatedProviderId,
        is_own_staff: true,
        slot_count: slots.length,
      };
    }

    return successResponse(response);
  } catch (error) {
    console.error("Error calculating availability:", error);
    return handleApiError(error, "Failed to fetch availability");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole } from "@/lib/supabase/auth-server";

export async function GET(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const supabase = await getSupabaseServer();
    const { user } = await requireRole(["customer", "provider_owner", "provider_staff"]);

    // Get booking with all related data
    const { data: booking, error: bookingError } = await supabase
      .from("bookings")
      .select(`
        *,
        customer:users!bookings_customer_id_fkey(id, email, full_name, phone),
        provider:providers!bookings_provider_id_fkey(
          id,
          business_name,
          owner_email,
          phone,
          address
        ),
        booking_services:booking_services(
          id,
          offering_id,
          duration_minutes,
          price,
          currency,
          offerings:offerings!booking_services_offering_id_fkey(id, title, price, duration_minutes)
        ),
        booking_products:booking_products(
          id,
          product_id,
          product_variant_id,
          quantity,
          unit_price,
          total_price,
          products:products!booking_products_product_id_fkey(
            id,
            name,
            retail_price
          ),
          product_variant:product_variants(id, option_values)
        ),
        payment_transactions:payment_transactions(
          id,
          amount,
          transaction_type,
          status,
          created_at
        )
      `)
      .eq("id", params.id)
      .single();

    if (bookingError || !booking) {
      return NextResponse.json(
        { error: "Booking not found" },
        { status: 404 }
      );
    }

    // Verify access
    const isCustomer = user.role === "customer" && booking.customer_id === user.id;
    const isProvider =
      (user.role === "provider_owner" || user.role === "provider_staff") &&
      booking.provider_id === user.id;

    if (!isCustomer && !isProvider) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 403 }
      );
    }

    // Calculate totals (booking_services stores price per service line, no quantity)
    const servicesTotal =
      booking.booking_services?.reduce(
        (sum: number, bs: any) => sum + Number(bs.price || 0),
        0
      ) || 0;

    const productsTotal =
      booking.booking_products?.reduce(
        (sum: number, bp: any) => sum + Number(bp.total_price || (bp.unit_price || bp.products?.retail_price || 0) * (bp.quantity || 1)),
        0
      ) || 0;

    const subtotal = servicesTotal + productsTotal;
    const tax = booking.tax_amount || 0;
    const fees = booking.service_fee_amount || 0;
    const discount = booking.discount_amount || 0;
    const total = subtotal + tax + fees - discount;

    const receipt = {
      booking_number: booking.booking_number,
      booking_date: booking.created_at,
      service_date: booking.scheduled_at,
      customer: booking.customer,
      provider: booking.provider,
      services: booking.booking_services?.map((bs: any) => ({
        name: bs.offerings?.title || "Service",
        quantity: 1,
        price: bs.price || bs.offerings?.price || 0,
        total: bs.price || bs.offerings?.price || 0,
      })) || [],
      products: booking.booking_products?.map((bp: any) => {
        const variantLabel = bp.product_variant?.option_values && typeof bp.product_variant.option_values === "object"
          ? ` ┬╖ ${Object.values(bp.product_variant.option_values).join(" / ")}`
          : "";
        return {
          name: `${bp.products?.name || "Product"}${variantLabel}`,
          quantity: bp.quantity || 1,
          price: bp.unit_price || bp.products?.retail_price || 0,
          total: bp.total_price || (bp.unit_price || bp.products?.retail_price || 0) * (bp.quantity || 1),
        };
      }) || [],
      subtotal,
      tax,
      fees,
      discount,
      total,
      payment_status: booking.payment_status,
      transactions: booking.payment_transactions || [],
    };

    return NextResponse.json({ receipt });
  } catch (error: any) {
    console.error("Error generating receipt:", error);
    return NextResponse.json(
      { error: error.message || "Failed to generate receipt" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole } from "@/lib/supabase/auth-server";
import { awardPointsForReview, checkProviderMilestones } from "@/lib/services/provider-gamification";

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const supabase = await getSupabaseServer();
    const { user } = await requireRole(["customer", "provider_owner"]);

    const { id: bookingId } = await params;
    const body = await request.json();
    const { rating, comment, photos } = body;

    if (!rating || rating < 1 || rating > 5) {
      return NextResponse.json(
        { error: "Rating must be between 1 and 5" },
        { status: 400 }
      );
    }

    // Get booking to verify ownership
    const { data: booking, error: bookingError } = await supabase
      .from("bookings")
      .select("id, customer_id, provider_id, status")
      .eq("id", bookingId)
      .single();

    if (bookingError || !booking) {
      return NextResponse.json(
        { error: "Booking not found" },
        { status: 404 }
      );
    }

    // Verify user is the customer for this booking
    if (user.role === "customer" && booking.customer_id !== user.id) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 403 }
      );
    }

    // Check if booking is completed
    if (booking.status !== "completed") {
      return NextResponse.json(
        { error: "Can only review completed bookings" },
        { status: 400 }
      );
    }

    // Check if review already exists
    const { data: existingReview } = await supabase
      .from("reviews")
      .select("id")
      .eq("booking_id", bookingId)
      .eq("customer_id", user.id)
      .single();

    if (existingReview) {
      return NextResponse.json(
        { error: "Review already exists for this booking" },
        { status: 400 }
      );
    }

    // Create review
    const { data: review, error: reviewError } = await supabase
      .from("reviews")
      .insert({
        booking_id: bookingId,
        customer_id: user.id,
        provider_id: booking.provider_id,
        rating,
        comment: comment || null,
        photos: photos || [],
        is_verified: true,
      })
      .select()
      .single();

    if (reviewError) throw reviewError;

    // Notify provider that customer left a review
    try {
      const supabase = await getSupabaseServer();
      const { data: providerData } = await supabase
        .from("providers")
        .select("user_id")
        .eq("id", booking.provider_id)
        .single();

      if (providerData?.user_id) {
        await supabase.from("notifications").insert({
          user_id: providerData.user_id,
          type: "new_review",
          title: "New Review Received",
          message: `You received a ${rating}-star review from a customer.`,
          metadata: {
            review_id: review.id,
            booking_id: bookingId,
            rating,
          },
          link: `/provider/reviews`,
        });
      }
    } catch (notifError) {
      // Log but don't fail the request
      console.warn("Failed to create provider notification for review:", notifError);
    }

    // Award points and check milestones (non-blocking)
    if (review && booking.provider_id) {
      awardPointsForReview(booking.provider_id, review.id, rating).catch(err => 
        console.error('Failed to award points for review:', err)
      );
      checkProviderMilestones(booking.provider_id).catch(err => 
        console.error('Failed to check milestones:', err)
      );
    }

    return NextResponse.json({ review });
  } catch (error: any) {
    console.error("Error creating review:", error);
    return NextResponse.json(
      { error: error.message || "Failed to create review" },
      { status: 500 }
    );
  }
}

