import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getMapboxService } from "@/lib/mapbox/mapbox";
import { z } from "zod";

const calculateDistanceSchema = z.object({
  provider_id: z.string().uuid(),
  address: z.object({
    latitude: z.number(),
    longitude: z.number(),
  }),
});

/**
 * POST /api/bookings/at-home/calculate-distance
 * 
 * Calculate distance from provider location to customer address
 * Returns distance in km and estimated travel time
 */
export async function POST(request: Request) {
  try {
    const body = await request.json();
    const validationResult = calculateDistanceSchema.safeParse(body);

    if (!validationResult.success) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Validation failed",
            code: "VALIDATION_ERROR",
            details: validationResult.error.issues.map((issue) => ({
              path: issue.path.join("."),
              message: issue.message,
            })),
          },
        },
        { status: 400 }
      );
    }

    const supabase = await getSupabaseServer();
    const mapbox = await getMapboxService();

    // Get provider's primary location
    const { data: providerLocation } = await supabase
      .from("provider_locations")
      .select("latitude, longitude")
      .eq("provider_id", validationResult.data.provider_id)
      .eq("is_active", true)
      .order("created_at", { ascending: true })
      .limit(1)
      .single();

    if (!providerLocation || !(providerLocation as any).latitude || !(providerLocation as any).longitude) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Provider location not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    const providerCoords = {
      latitude: (providerLocation as any).latitude,
      longitude: (providerLocation as any).longitude,
    };

    const customerCoords = validationResult.data.address;

    // Calculate straight-line distance
    const distanceKm = mapbox.calculateDistance(providerCoords, customerCoords);

    // Calculate route for travel time
    let route = null;
    try {
      route = await mapbox.calculateRoute([providerCoords, customerCoords], {
        profile: "driving",
        steps: false,
        overview: "simplified",
      });
    } catch (error) {
      console.warn("Route calculation failed, using straight-line distance:", error);
    }

    return NextResponse.json({
      data: {
        distance_km: distanceKm,
        distance_m: distanceKm * 1000,
        route_distance_km: route ? route.distance / 1000 : null,
        estimated_duration_minutes: route ? Math.round(route.duration / 60) : null,
        coordinates: {
          provider: providerCoords,
          customer: customerCoords,
        },
      },
      error: null,
    });
  } catch (error: any) {
    console.error("Error calculating distance:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: error.message || "Failed to calculate distance",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getMapboxService } from "@/lib/mapbox/mapbox";
import { z } from "zod";

const checkAvailabilitySchema = z.object({
  provider_id: z.string().uuid(),
  service_id: z.string().uuid().optional(),
  address: z.object({
    address_line1: z.string(),
    city: z.string(),
    country: z.string(),
    latitude: z.number().optional(),
    longitude: z.number().optional(),
  }),
});

/**
 * POST /api/bookings/at-home/check-availability
 * 
 * Check if at-home service is available at the given address
 * - Verifies address is within provider's service zones
 * - Calculates distance from provider location
 * - Checks if service supports at-home
 */
export async function POST(request: Request) {
  try {
    const body = await request.json();
    const validationResult = checkAvailabilitySchema.safeParse(body);

    if (!validationResult.success) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Validation failed",
            code: "VALIDATION_ERROR",
            details: validationResult.error.issues.map((issue) => ({
              path: issue.path.join("."),
              message: issue.message,
            })),
          },
        },
        { status: 400 }
      );
    }

    const supabase = await getSupabaseServer();
    const mapbox = await getMapboxService();

    // Get provider
    const { data: provider } = await supabase
      .from("providers")
      .select("id")
      .eq("id", validationResult.data.provider_id)
      .single();

    if (!provider) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Provider not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    // Geocode address if coordinates not provided
    let latitude = validationResult.data.address.latitude;
    let longitude = validationResult.data.address.longitude;

    if (!latitude || !longitude) {
      try {
        const fullAddress = [
          validationResult.data.address.address_line1,
          validationResult.data.address.city,
          validationResult.data.address.country,
        ]
          .filter(Boolean)
          .join(", ");

        const geocodeResults = await mapbox.geocode(fullAddress, {
          country: validationResult.data.address.country,
          limit: 1,
        });

        if (geocodeResults.length > 0) {
          const result = geocodeResults[0];
          longitude = result.center[0];
          latitude = result.center[1];
        } else {
          return NextResponse.json(
            {
              data: null,
              error: {
                message: "Could not geocode address",
                code: "GEOCODE_ERROR",
              },
            },
            { status: 400 }
          );
        }
      } catch (error) {
        console.error("Geocoding error:", error);
        return NextResponse.json(
          {
            data: null,
            error: {
              message: "Failed to geocode address",
              code: "GEOCODE_ERROR",
            },
          },
          { status: 500 }
        );
      }
    }

    // Check service zones
    const { data: zones } = await supabase
      .from("service_zones")
      .select("*")
      .eq("provider_id", validationResult.data.provider_id)
      .eq("is_active", true);

    let isInZone = false;
    if (zones && zones.length > 0) {
      for (const zone of zones) {
        const zoneData = {
          id: (zone as any).id,
          name: (zone as any).name,
          type: (zone as any).type,
          coordinates: JSON.parse((zone as any).coordinates),
          radius_km: (zone as any).radius_km,
          is_active: (zone as any).is_active,
        };

        if (mapbox.isPointInZone({ latitude, longitude }, zoneData)) {
          isInZone = true;
          break;
        }
      }
    } else {
      // No zones defined = service available everywhere (or check provider location)
      isInZone = true;
    }

    // Get provider's primary location for distance calculation
    const { data: providerLocation } = await supabase
      .from("provider_locations")
      .select("latitude, longitude")
      .eq("provider_id", validationResult.data.provider_id)
      .eq("is_active", true)
      .order("created_at", { ascending: true })
      .limit(1)
      .single();

    let distanceKm = null;
    if (providerLocation && (providerLocation as any).latitude && (providerLocation as any).longitude) {
      distanceKm = mapbox.calculateDistance(
        {
          latitude: (providerLocation as any).latitude,
          longitude: (providerLocation as any).longitude,
        },
        { latitude, longitude }
      );
    }

    // Check if service supports at-home
    let serviceSupportsAtHome = true;
    if (validationResult.data.service_id) {
      const { data: service } = await supabase
        .from("offerings")
        .select("supports_at_home, at_home_radius_km")
        .eq("id", validationResult.data.service_id)
        .single();

      if (service) {
        serviceSupportsAtHome = (service as any).supports_at_home || false;
        const maxRadius = (service as any).at_home_radius_km;

        if (serviceSupportsAtHome && maxRadius && distanceKm && distanceKm > maxRadius) {
          return NextResponse.json({
            data: {
              available: false,
              reason: "distance_exceeded",
              distance_km: distanceKm,
              max_radius_km: maxRadius,
              is_in_zone: isInZone,
            },
            error: null,
          });
        }
      }
    }

    return NextResponse.json({
      data: {
        available: isInZone && serviceSupportsAtHome,
        is_in_zone: isInZone,
        service_supports_at_home: serviceSupportsAtHome,
        distance_km: distanceKm,
        coordinates: {
          latitude,
          longitude,
        },
      },
      error: null,
    });
  } catch (error: any) {
    console.error("Error checking at-home availability:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: error.message || "Failed to check availability",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { z } from "zod";

const updateCouponSchema = z.object({
  name: z.string().optional(),
  description: z.string().optional(),
  discount_type: z.enum(["percentage", "fixed"]).optional(),
  discount_value: z.number().positive().optional(),
  currency: z.string().optional(),
  min_purchase_amount: z.number().min(0).optional(),
  max_discount_amount: z.number().positive().optional().nullable(),
  valid_from: z.string().datetime().optional().nullable(),
  valid_until: z.string().datetime().optional().nullable(),
  max_uses: z.number().int().positive().optional().nullable(),
  max_uses_per_user: z.number().int().positive().optional(),
  is_active: z.boolean().optional(),
});

/**
 * GET /api/coupons/[id]
 * 
 * Get a specific coupon
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const supabase = await getSupabaseServer();
    const { id } = await params;

    const { data: coupon, error } = await supabase
      .from("coupons")
      .select("*")
      .eq("id", id)
      .single();

    if (error || !coupon) {
      return notFoundResponse("Coupon not found");
    }

    return successResponse({ coupon });
  } catch (error) {
    return handleApiError(error, "Failed to fetch coupon");
  }
}

/**
 * PATCH /api/coupons/[id]
 * 
 * Update a coupon (admin only)
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(['superadmin']);
    const supabase = await getSupabaseServer();
    const { id } = await params;
    const body = await request.json();

    const validated = updateCouponSchema.parse(body);

    // Update coupon
    const updateData: any = {};
    if (validated.name !== undefined) updateData.name = validated.name;
    if (validated.description !== undefined) updateData.description = validated.description;
    if (validated.discount_type !== undefined) updateData.discount_type = validated.discount_type;
    if (validated.discount_value !== undefined) updateData.discount_value = validated.discount_value;
    if (validated.currency !== undefined) updateData.currency = validated.currency;
    if (validated.min_purchase_amount !== undefined) updateData.min_purchase_amount = validated.min_purchase_amount;
    if (validated.max_discount_amount !== undefined) updateData.max_discount_amount = validated.max_discount_amount;
    if (validated.valid_from !== undefined) updateData.valid_from = validated.valid_from;
    if (validated.valid_until !== undefined) updateData.valid_until = validated.valid_until;
    if (validated.max_uses !== undefined) updateData.max_uses = validated.max_uses;
    if (validated.max_uses_per_user !== undefined) updateData.max_uses_per_user = validated.max_uses_per_user;
    if (validated.is_active !== undefined) updateData.is_active = validated.is_active;

    const { data: coupon, error } = await supabase
      .from("coupons")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (error) {
      throw error;
    }

    return successResponse({
      coupon,
      message: "Coupon updated successfully",
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return errorResponse(
        error.issues.map((e) => e.message).join(", "),
        "VALIDATION_ERROR",
        400
      );
    }
    return handleApiError(error, "Failed to update coupon");
  }
}

/**
 * DELETE /api/coupons/[id]
 * 
 * Delete a coupon (admin only)
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(['superadmin']);
    const supabase = await getSupabaseServer();
    const { id } = await params;

    // Deactivate instead of delete
    const { error } = await supabase
      .from("coupons")
      .update({ is_active: false })
      .eq("id", id);

    if (error) {
      throw error;
    }

    return successResponse({
      message: "Coupon deactivated successfully",
    });
  } catch (error) {
    return handleApiError(error, "Failed to delete coupon");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { verifyCronRequest } from "@/lib/cron-auth";

/**
 * GET /api/cron/process-recurring-bookings
 * 
 * Cron job to create bookings from active recurring appointments
 * Should be called daily
 */
export async function GET(request: NextRequest) {
  try {
    // Verify cron request (secret + Vercel origin)
    const auth = verifyCronRequest(request);
    if (!auth.valid) {
      return new Response(auth.error || "Unauthorized", { status: 401 });
    }

    const supabaseAdmin = getSupabaseAdmin();
    const today = new Date();
    const todayStr = today.toISOString().split("T")[0];

    // Get active recurring appointments
    const { data: recurring, error } = await supabaseAdmin
      .from("recurring_appointments")
      .select("*")
      .eq("is_active", true)
      .lte("start_date", todayStr)
      .or(`end_date.is.null,end_date.gte.${todayStr}`);

    if (error) {
      throw error;
    }

    if (!recurring || recurring.length === 0) {
      return successResponse({
        message: "No recurring bookings to process",
        processed: 0,
      });
    }

    let processed = 0;
    const errors: string[] = [];

    for (const appointment of recurring) {
      try {
        // Calculate next booking date based on frequency
        const lastBookingDate = appointment.last_booking_date 
          ? new Date(appointment.last_booking_date)
          : new Date(appointment.start_date);

        const daysToAdd = appointment.frequency === "weekly" 
          ? 7
          : appointment.frequency === "biweekly"
          ? 14
          : 30; // monthly

        const nextBookingDate = new Date(lastBookingDate.getTime() + daysToAdd * 24 * 60 * 60 * 1000);
        const nextBookingDateStr = nextBookingDate.toISOString().split("T")[0];

        // Check if booking should be created today
        if (nextBookingDateStr === todayStr) {
          // Create booking
          const [hours, minutes] = appointment.preferred_time.split(":");
          const scheduledAt = new Date(nextBookingDate);
          scheduledAt.setHours(parseInt(hours), parseInt(minutes), 0, 0);

          const services = appointment.metadata?.services || [];
          if (services.length === 0) {
            continue;
          }

          // Create booking (simplified - would need full booking creation logic)
          const { error: bookingError } = await supabaseAdmin
            .from("bookings")
            .insert({
              customer_id: appointment.customer_id,
              provider_id: appointment.provider_id,
              status: "confirmed",
              location_type: appointment.location_type,
              location_id: appointment.location_id,
              scheduled_at: scheduledAt.toISOString(),
              // Other booking fields would be set here
            });

          if (bookingError) {
            errors.push(`Failed to create booking for recurring ${appointment.id}: ${bookingError.message}`);
            continue;
          }

          // Update last_booking_date
          await supabaseAdmin
            .from("recurring_appointments")
            .update({ last_booking_date: nextBookingDateStr })
            .eq("id", appointment.id);

          processed++;
        }
      } catch (err: any) {
        errors.push(`Error processing recurring ${appointment.id}: ${err.message}`);
      }
    }

    return successResponse({
      message: "Recurring bookings processed",
      processed,
      errors: errors.length > 0 ? errors : undefined,
    });
  } catch (error) {
    return handleApiError(error, "Failed to process recurring bookings");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  successResponse,
  errorResponse,
  handleApiError,
  requireAuthInApi,
  getProviderIdForUser,
} from "@/lib/supabase/api-helpers";
import type { ExploreComment } from "@/types/explore";

/** Returns true if the post is publicly visible (published + not hidden). */
function isPostPublic(post: { status: string; is_hidden: boolean }) {
  return post.status === "published" && post.is_hidden === false;
}

/** Check if the authenticated user can access this post as provider (owner or staff). */
async function userCanAccessPostAsProvider(userId: string, postProviderId: string): Promise<boolean> {
  const providerId = await getProviderIdForUser(userId);
  return providerId === postProviderId;
}

/**
 * GET /api/explore/posts/[id]/comments
 * Public: list comments for a published post.
 * Provider: list comments for own post (any status, e.g. draft).
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id: postId } = await params;
    const { searchParams } = new URL(request.url);
    const limit = Math.min(Math.max(parseInt(searchParams.get("limit") ?? "50", 10), 1), 100);
    const offset = Math.max(parseInt(searchParams.get("offset") ?? "0", 10), 0);

    const supabaseAdmin = await getSupabaseAdmin();

    const { data: post, error: postError } = await supabaseAdmin
      .from("explore_posts")
      .select("id, provider_id, status, is_hidden")
      .eq("id", postId)
      .single();

    if (postError || !post) {
      return errorResponse("Post not found", "NOT_FOUND", 404);
    }

    let canAccess = isPostPublic(post);
    if (!canAccess) {
      const supabase = await getSupabaseServer();
      const { data: { user } } = await supabase.auth.getUser();
      canAccess = !!(user && (await userCanAccessPostAsProvider(user.id, post.provider_id)));
    }
    if (!canAccess) {
      return errorResponse("Post not found", "NOT_FOUND", 404);
    }

    const { data: rows, error } = await supabaseAdmin
      .from("explore_comments")
      .select(
        `
        id,
        post_id,
        user_id,
        body,
        mentioned_user_ids,
        created_at,
        updated_at,
        users:user_id(id, full_name, avatar_url)
      `
      )
      .eq("post_id", postId)
      .order("created_at", { ascending: true })
      .order("id", { ascending: true })
      .range(offset, offset + limit - 1);

    if (error) return handleApiError(error, "Failed to fetch comments");

    const comments: ExploreComment[] = (rows || []).map((r: any) => ({
      id: r.id,
      post_id: r.post_id,
      user_id: r.user_id,
      author: r.users
        ? {
            id: r.users.id,
            full_name: r.users.full_name ?? null,
            avatar_url: r.users.avatar_url ?? null,
          }
        : { id: r.user_id, full_name: null, avatar_url: null },
      body: r.body,
      mentioned_user_ids: r.mentioned_user_ids ?? [],
      created_at: r.created_at,
      updated_at: r.updated_at,
    }));

    const next_offset = comments.length === limit ? offset + limit : undefined;

    return successResponse({
      data: comments,
      next_offset: next_offset ?? undefined,
      has_more: !!next_offset,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch comments");
  }
}

/**
 * POST /api/explore/posts/[id]/comments
 * Authenticated: create a comment on a published post.
 * Body: { body: string, mention_user_ids?: string[] }
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireAuthInApi(request);
    const { id: postId } = await params;

    const body = await request.json();
    const text = typeof body.body === "string" ? body.body.trim() : "";
    if (!text) {
      return errorResponse("Comment body is required", "VALIDATION_ERROR", 400);
    }
    const MAX_BODY_LENGTH = 200;
    if (text.length > MAX_BODY_LENGTH) {
      return errorResponse(
        `Comment must be ${MAX_BODY_LENGTH} characters or fewer`,
        "VALIDATION_ERROR",
        400
      );
    }

    const mentionUserIds: string[] = Array.isArray(body.mention_user_ids)
      ? body.mention_user_ids.filter((id: any) => typeof id === "string")
      : [];

    const supabaseAdmin = await getSupabaseAdmin();

    const { data: post, error: postError } = await supabaseAdmin
      .from("explore_posts")
      .select("id, provider_id, status, is_hidden")
      .eq("id", postId)
      .single();

    if (postError || !post) {
      return errorResponse("Post not found", "NOT_FOUND", 404);
    }

    const canComment =
      isPostPublic(post) || (await userCanAccessPostAsProvider(user.id, post.provider_id));
    if (!canComment) {
      return errorResponse("Post not found", "NOT_FOUND", 404);
    }

    const { data: row, error } = await supabaseAdmin
      .from("explore_comments")
      .insert({
        post_id: postId,
        user_id: user.id,
        body: text,
        mentioned_user_ids: mentionUserIds,
      })
      .select(
        `
        id,
        post_id,
        user_id,
        body,
        mentioned_user_ids,
        created_at,
        updated_at,
        users:user_id(id, full_name, avatar_url)
      `
      )
      .single();

    if (error) return handleApiError(error, "Failed to create comment");

    const comment: ExploreComment = {
      id: row.id,
      post_id: row.post_id,
      user_id: row.user_id,
      author: row.users
        ? (() => {
            const u = Array.isArray(row.users) ? (row.users as any)[0] : (row.users as any);
            return {
              id: u?.id ?? row.user_id,
              full_name: u?.full_name ?? null,
              avatar_url: u?.avatar_url ?? null,
            };
          })()
        : { id: row.user_id, full_name: null, avatar_url: null },
      body: row.body,
      mentioned_user_ids: row.mentioned_user_ids ?? [],
      created_at: row.created_at,
      updated_at: row.updated_at,
    };

    return successResponse(comment, 201);
  } catch (error) {
    return handleApiError(error, "Failed to create comment");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import {
  getProviderIdForUser,
  successResponse,
  errorResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";
import { requireRoleInApi } from "@/lib/supabase/api-helpers";
import { hasPermission } from "@/lib/auth/permissions";
import { getSupabaseServer } from "@/lib/supabase/server";
import type { ExplorePost } from "@/types/explore";
import { toPublicMediaUrl, toStoragePath } from "@/lib/explore/media-urls";

const supabaseUrl = () => process.env.NEXT_PUBLIC_SUPABASE_URL;

function mapToExplorePost(row: any, savedIds: Set<string>, likedIds: Set<string>): ExplorePost {
  const mediaUrls = (row.media_urls || []).map((p: string) =>
    toPublicMediaUrl(p, supabaseUrl())
  );
  const provider = row.providers
    ? { business_name: row.providers.business_name, slug: row.providers.slug }
    : row.provider_business_name
      ? { business_name: row.provider_business_name, slug: row.provider_slug }
      : { business_name: "", slug: "" };
  return {
    id: row.id,
    provider_id: row.provider_id,
    provider,
    created_by_user_id: row.created_by_user_id,
    caption: row.caption,
    media_urls: mediaUrls,
    status: row.status,
    published_at: row.published_at,
    like_count: row.like_count ?? 0,
    comment_count: row.comment_count ?? 0,
    created_at: row.created_at,
    updated_at: row.updated_at,
    is_saved: savedIds.has(row.id),
    is_liked: likedIds.has(row.id),
  };
}

/**
 * GET /api/explore/posts/[id]
 * Public: fetch single published post.
 */
export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const supabaseAdmin = await getSupabaseAdmin();
    const supabase = await getSupabaseServer();
    const { data: { user } } = await supabase.auth.getUser();

    const { data: row, error } = await supabaseAdmin
      .from("explore_posts")
      .select(
        "id, provider_id, created_by_user_id, caption, media_urls, status, published_at, like_count, comment_count, created_at, updated_at"
      )
      .eq("id", id)
      .eq("status", "published")
      .eq("is_hidden", false)
      .single();

    if (error || !row) {
      return errorResponse("Post not found", "NOT_FOUND", 404);
    }

    const { data: provData } = await supabaseAdmin
      .from("providers")
      .select("id, business_name, slug")
      .eq("id", row.provider_id)
      .single();

    const enriched = {
      ...row,
      provider_business_name: provData?.business_name ?? "",
      provider_slug: provData?.slug ?? "",
    };

    const savedIds = new Set<string>();
    const likedIds = new Set<string>();
    if (user) {
      const [savedRes, likedRes] = await Promise.all([
        supabaseAdmin.from("explore_saved").select("post_id").eq("user_id", user.id).eq("post_id", id),
        supabaseAdmin
          .from("explore_events")
          .select("post_id")
          .eq("actor_type", "authed")
          .eq("actor_key", user.id)
          .eq("event_type", "like")
          .eq("post_id", id),
      ]);
      if (savedRes.data?.length) savedIds.add(id);
      if (likedRes.data?.length) likedIds.add(id);
    }

    const post = mapToExplorePost(enriched, savedIds, likedIds);
    return successResponse(post);
  } catch (error) {
    return handleApiError(error, "Failed to fetch post");
  }
}

/**
 * PATCH /api/explore/posts/[id]
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const { user } = await requireRoleInApi(
      ["provider_owner", "provider_staff", "superadmin"],
      request
    );
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return errorResponse("Provider not found", "NOT_FOUND", 404);
    }

    const supabaseAdmin = await getSupabaseAdmin();
    const isOwner =
      (await supabaseAdmin
        .from("providers")
        .select("id")
        .eq("user_id", user.id)
        .single()).data != null;

    if (!isOwner) {
      const hasCreatePermission = await hasPermission(
        user.id,
        "create_explore_posts"
      );
      if (!hasCreatePermission) {
        return errorResponse(
          "Permission denied: create_explore_posts required",
          "FORBIDDEN",
          403
        );
      }
    }

    const { data: existing } = await supabaseAdmin
      .from("explore_posts")
      .select("provider_id")
      .eq("id", id)
      .single();

    if (!existing || existing.provider_id !== providerId) {
      return errorResponse("Post not found", "NOT_FOUND", 404);
    }

    const body = await request.json();
    const updates: Record<string, any> = {};
    if (body.caption !== undefined) updates.caption = body.caption;
    if (body.media_urls !== undefined) {
      updates.media_urls = (body.media_urls as string[]).map((u: string) => toStoragePath(String(u)));
    }
    if (body.status !== undefined) {
      updates.status = body.status === "published" ? "published" : "draft";
      if (body.status === "published") {
        updates.published_at = new Date().toISOString();
      }
    }

    if (Object.keys(updates).length === 0) {
      return errorResponse("No valid fields to update", "VALIDATION_ERROR", 400);
    }

    const { data: post, error } = await supabaseAdmin
      .from("explore_posts")
      .update(updates)
      .eq("id", id)
      .select(
        `
        id,
        provider_id,
        created_by_user_id,
        caption,
        media_urls,
        status,
        published_at,
        like_count,
        created_at,
        updated_at,
        providers:provider_id(business_name, slug)
      `
      )
      .single();

    if (error) return handleApiError(error, "Failed to update post");

    // Award reward points when post is published (idempotent: no double award)
    if (updates.status === "published") {
      try {
        await supabaseAdmin.rpc("award_provider_points_for_explore_post", {
          p_provider_id: existing.provider_id,
          p_post_id: (post as any).id,
        });
      } catch (pointsErr) {
        console.warn("[explore/posts PATCH] Award points for publish:", pointsErr);
      }
    }

    const explorePost: ExplorePost = {
      ...post,
      provider: post.providers
        ? (() => {
            const p = Array.isArray(post.providers) ? (post.providers as any)[0] : (post.providers as any);
            return { business_name: p?.business_name ?? "", slug: p?.slug ?? "" };
          })()
        : { business_name: "", slug: "" },
      media_urls: (post.media_urls || []).map((p: string) =>
        toPublicMediaUrl(p, supabaseUrl())
      ),
    };
    return successResponse(explorePost);
  } catch (error) {
    return handleApiError(error, "Failed to update post");
  }
}

