import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { getMapboxService } from "@/lib/mapbox/mapbox";
import { z } from "zod";

const updateAddressSchema = z.object({
  label: z.string().min(1).optional(),
  address_line1: z.string().min(1).optional(),
  address_line2: z.string().optional().nullable(),
  city: z.string().min(1).optional(),
  state: z.string().optional().nullable(),
  postal_code: z.string().optional().nullable(),
  country: z.string().min(1).optional(),
  latitude: z.number().optional().nullable(),
  longitude: z.number().optional().nullable(),
  is_default: z.boolean().optional(),
  // House call specific fields
  apartment_unit: z.string().optional().nullable(),
  building_name: z.string().optional().nullable(),
  floor_number: z.string().optional().nullable(),
  access_codes: z.record(z.string(), z.string()).optional().nullable(),
  parking_instructions: z.string().optional().nullable(),
  location_landmarks: z.string().optional().nullable(),
});

/**
 * GET /api/me/addresses/[id]
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);

    const { id } = await params;
    const supabase = await getSupabaseServer();

    const { data: address, error } = await supabase
      .from("user_addresses")
      .select("*")
      .eq("id", id)
      .eq("user_id", user.id)
      .single();

    if (error || !address) {
      return notFoundResponse("Address not found");
    }

    return successResponse(address);
  } catch (error) {
    return handleApiError(error, "Failed to fetch address");
  }
}

/**
 * PUT /api/me/addresses/[id]
 */
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);

    const { id } = await params;
    const supabase = await getSupabaseServer();
    const body = await request.json();

    const validationResult = updateAddressSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues.map((issue) => ({
          path: issue.path.join("."),
          message: issue.message,
        }))
      );
    }

    // Check existing address
    const { data: existing } = await supabase
      .from("user_addresses")
      .select("*")
      .eq("id", id)
      .eq("user_id", user.id)
      .single();

    if (!existing) {
      return notFoundResponse("Address not found");
    }

    let latitude = validationResult.data.latitude ?? (existing as any).latitude;
    let longitude = validationResult.data.longitude ?? (existing as any).longitude;

    // Re-geocode if address fields changed and coordinates not provided
    const addressChanged =
      validationResult.data.address_line1 ||
      validationResult.data.city ||
      validationResult.data.country;

    if (addressChanged && (!latitude || !longitude)) {
      try {
        const mapbox = await getMapboxService();
        const fullAddress = [
          validationResult.data.address_line1 || (existing as any).address_line1,
          validationResult.data.address_line2 || (existing as any).address_line2,
          validationResult.data.city || (existing as any).city,
          validationResult.data.state || (existing as any).state,
          validationResult.data.postal_code || (existing as any).postal_code,
          validationResult.data.country || (existing as any).country,
        ]
          .filter(Boolean)
          .join(", ");

        const geocodeResults = await mapbox.geocode(fullAddress, {
          country: validationResult.data.country || (existing as any).country,
          limit: 1,
        });

        if (geocodeResults.length > 0) {
          const result = geocodeResults[0];
          longitude = result.center[0];
          latitude = result.center[1];
        }
      } catch (error) {
        console.warn("Geocoding failed:", error);
      }
    }

    // If setting as default, unset other defaults
    if (validationResult.data.is_default) {
      await (supabase as any)
        .from("user_addresses")
        .update({ is_default: false })
        .eq("user_id", user.id)
        .neq("id", id);
    }

    // Prepare access_codes as JSONB if provided
    const updateData: any = {
      ...validationResult.data,
      latitude,
      longitude,
      updated_at: new Date().toISOString(),
    };

    if (validationResult.data.access_codes !== undefined) {
      updateData.access_codes = validationResult.data.access_codes
        ? JSON.stringify(validationResult.data.access_codes)
        : null;
    }

    const { data: address, error } = await (supabase
      .from("user_addresses") as any)
      .update(updateData)
      .eq("id", id)
      .eq("user_id", user.id)
      .select()
      .single();

    if (error || !address) {
      throw error || new Error("Failed to update address");
    }

    return successResponse(address);
  } catch (error) {
    return handleApiError(error, "Failed to update address");
  }
}

/**
 * DELETE /api/me/addresses/[id]
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);

    const { id } = await params;
    const supabase = await getSupabaseServer();

    const { error } = await supabase
      .from("user_addresses")
      .delete()
      .eq("id", id)
      .eq("user_id", user.id);

    if (error) {
      throw error;
    }

    return successResponse({ id, deleted: true });
  } catch (error) {
    return handleApiError(error, "Failed to delete address");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { getMapboxService } from "@/lib/mapbox/mapbox";
import { z } from "zod";

const addressSchema = z.object({
  label: z.string().min(1, "Label is required"),
  address_line1: z.string().min(1, "Address is required"),
  address_line2: z.string().optional().nullable(),
  city: z.string().min(1, "City is required"),
  state: z.string().optional().nullable(),
  postal_code: z.string().optional().nullable(),
  country: z.string().min(1, "Country is required"),
  latitude: z.number().optional().nullable(),
  longitude: z.number().optional().nullable(),
  is_default: z.boolean().default(false),
  // House call specific fields
  apartment_unit: z.string().optional().nullable(),
  building_name: z.string().optional().nullable(),
  floor_number: z.string().optional().nullable(),
  access_codes: z.record(z.string(), z.string()).optional().nullable(), // {gate: "1234", buzzer: "Apt 5", door: "4567"}
  parking_instructions: z.string().optional().nullable(),
  location_landmarks: z.string().optional().nullable(),
});

/**
 * GET /api/me/addresses
 * 
 * Get user's saved addresses
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer();

    const { data: addresses, error } = await supabase
      .from("user_addresses")
      .select("*")
      .eq("user_id", user.id)
      .order("is_default", { ascending: false })
      .order("created_at", { ascending: false });

    if (error) {
      throw error;
    }

    return successResponse(addresses || []);
  } catch (error) {
    return handleApiError(error, "Failed to fetch addresses");
  }
}

/**
 * POST /api/me/addresses
 * 
 * Create a new saved address (with Mapbox geocoding)
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer();
    const body = await request.json();

    const validationResult = addressSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues.map((issue) => ({
          path: issue.path.join("."),
          message: issue.message,
        }))
      );
    }

    let latitude = validationResult.data.latitude;
    let longitude = validationResult.data.longitude;

    // Geocode address if coordinates not provided
    if (!latitude || !longitude) {
      try {
        const mapbox = await getMapboxService();
        const fullAddress = [
          validationResult.data.address_line1,
          validationResult.data.address_line2,
          validationResult.data.city,
          validationResult.data.state,
          validationResult.data.postal_code,
          validationResult.data.country,
        ]
          .filter(Boolean)
          .join(", ");

        const geocodeResults = await mapbox.geocode(fullAddress, {
          country: validationResult.data.country,
          limit: 1,
        });

        if (geocodeResults.length > 0) {
          const result = geocodeResults[0];
          longitude = result.center[0];
          latitude = result.center[1];
        }
      } catch (error) {
        console.warn("Geocoding failed, continuing without coordinates:", error);
        // Continue without coordinates - they can be added later
      }
    }

    // If setting as default, unset other defaults
    if (validationResult.data.is_default) {
      await (supabase as any)
        .from("user_addresses")
        .update({ is_default: false })
        .eq("user_id", user.id);
    }

    // Prepare access_codes as JSONB
    const accessCodesJson = validationResult.data.access_codes 
      ? JSON.stringify(validationResult.data.access_codes)
      : null;

    const { data: address, error } = await (supabase
      .from("user_addresses") as any)
      .insert({
        user_id: user.id,
        ...validationResult.data,
        access_codes: accessCodesJson,
        latitude,
        longitude,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .select()
      .single();

    if (error || !address) {
      throw error || new Error("Failed to create address");
    }

    return successResponse(address);
  } catch (error) {
    return handleApiError(error, "Failed to create address");
  }
}

/**
 * POST /api/me/analytics/identify
 *
 * Server-side endpoint to fetch user properties for Amplitude identification.
 * Used by the AmplitudeProvider client component - avoids importing server-only
 * code (next/headers, getSupabaseServer) in the client bundle.
 */

import { NextRequest } from "next/server";
import {
  successResponse,
  unauthorizedResponse,
  handleApiError,
  requireRoleInApi,
} from "@/lib/supabase/api-helpers";
import { identifyUser } from "@/lib/analytics/amplitude/identify";

export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(
      ["customer", "provider_owner", "provider_staff", "superadmin"],
      request
    );

    const body = await request.json().catch(() => ({}));
    const { email, full_name, phone } = body;

    const properties = await identifyUser(
      user.id,
      user.role || "customer",
      { email: user.email || email, full_name: user.full_name || full_name, phone: (user as any).phone || phone }
    );

    return successResponse(properties);
  } catch (error) {
    if (error instanceof Error && error.message === "Authentication required") {
      return unauthorizedResponse();
    }
    return handleApiError(error, "Failed to identify user");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";

/**
 * POST /api/me/avatar
 * Upload user avatar
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer();

    // For storage operations, try using service role if available (bypasses RLS)
    // Otherwise use the regular client with user context
    let storageClient = supabase;
    const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
    if (serviceRoleKey) {
      const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
      if (supabaseUrl) {
        storageClient = createClient(supabaseUrl, serviceRoleKey, {
          auth: {
            autoRefreshToken: false,
            persistSession: false,
          },
        });
      }
    }

    const formData = await request.formData();
    const file = formData.get('file') as File;

    if (!file) {
      return NextResponse.json(
        { error: "No file provided" },
        { status: 400 }
      );
    }

    // Validate file type
    const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'];
    if (!allowedTypes.includes(file.type)) {
      return NextResponse.json(
        { error: "Invalid file type. Only JPEG, PNG, and WebP are allowed." },
        { status: 400 }
      );
    }

    // Validate file size (5MB max)
    const maxSize = 5 * 1024 * 1024; // 5MB
    if (file.size > maxSize) {
      return NextResponse.json(
        { error: "File size exceeds 5MB limit." },
        { status: 400 }
      );
    }

    // Generate file path - use simpler path format
    const fileExt = file.name.split('.').pop() || 'jpg';
    // Use user ID as folder and timestamped filename
    const fileName = `avatar-${Date.now()}.${fileExt}`;
    const filePath = `${user.id}/${fileName}`;

    // Convert File to ArrayBuffer for Supabase
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);

    console.log('Uploading avatar:', {
      filePath,
      fileSize: file.size,
      fileType: file.type,
      userId: user.id,
    });

    // Check if bucket exists and is accessible
    const { data: buckets, error: bucketError } = await storageClient.storage.listBuckets();
    if (bucketError) {
      console.error('Error listing buckets:', bucketError);
    } else {
      const avatarsBucket = buckets?.find(b => b.name === 'avatars');
      if (!avatarsBucket) {
        throw new Error('Storage bucket "avatars" not found. Please create it in Supabase Dashboard > Storage.');
      }
      console.log('Avatars bucket found:', avatarsBucket);
    }

    // Upload to Supabase Storage
    // First, try to delete existing avatar if it exists (optional cleanup)
    try {
      const existingFiles = await storageClient.storage
        .from('avatars')
        .list(`${user.id}/`, {
          search: 'avatar-',
        });

      if (existingFiles.data && existingFiles.data.length > 0) {
        // Delete old avatars
        const oldFiles = existingFiles.data.map(f => `${user.id}/${f.name}`);
        await storageClient.storage
          .from('avatars')
          .remove(oldFiles);
      }
    } catch (cleanupError) {
      // Ignore cleanup errors, proceed with upload
      console.warn('Could not clean up old avatars:', cleanupError);
    }

    const { data: uploadData, error: uploadError } = await storageClient.storage
      .from('avatars')
      .upload(filePath, buffer, {
        contentType: file.type,
        cacheControl: '3600',
        upsert: true,
      });

    if (uploadError) {
      console.error('Avatar upload error:', {
        message: uploadError.message,
        status: (uploadError as any).status || (uploadError as any).statusCode,
        name: uploadError.name,
        error: JSON.stringify(uploadError, Object.getOwnPropertyNames(uploadError)),
        filePath,
        fileSize: file.size,
        fileType: file.type,
        userId: user.id,
      });

      // Provide more specific error messages
      const errorMsg = uploadError.message || '';

      if (errorMsg.includes('Bucket not found') || errorMsg.includes('does not exist') || errorMsg.includes('The resource was not found')) {
        throw new Error('Storage bucket "avatars" not found. Please create it in Supabase Dashboard > Storage.');
      }

      if (errorMsg.includes('row-level security') || errorMsg.includes('RLS') || errorMsg.includes('permission')) {
        throw new Error('Permission denied. Please check storage bucket policies in Supabase Dashboard.');
      }

      if (errorMsg.includes('duplicate') || errorMsg.includes('already exists')) {
        // File already exists, try to get the URL
        const { data: { publicUrl } } = storageClient.storage
          .from('avatars')
          .getPublicUrl(filePath);
        return successResponse({ url: publicUrl, path: filePath });
      }

      // Return the actual error message for debugging
      throw new Error(`Upload failed: ${errorMsg || 'Unknown error'}`);
    }

    if (!uploadData) {
      throw new Error('Upload succeeded but no data returned');
    }

    // Get public URL
    const { data: { publicUrl } } = storageClient.storage
      .from('avatars')
      .getPublicUrl(uploadData.path);

    return successResponse({ url: publicUrl, path: uploadData.path });
  } catch (error) {
    console.error('Avatar upload route error:', {
      error,
      message: error instanceof Error ? error.message : String(error),
      stack: error instanceof Error ? error.stack : undefined,
    });
    return handleApiError(error, "Failed to upload avatar");
  }
}

import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, handleApiError, requireRoleInApi } from "@/lib/supabase/api-helpers";
import { NextRequest } from "next/server";

/**
 * GET /api/me/beauty-preferences
 * 
 * Get current user's beauty preferences
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer();

    const { data: profileData, error } = await supabase
      .from("user_profiles")
      .select("beauty_preferences")
      .eq("user_id", user.id)
      .maybeSingle();

    if (error && error.code !== 'PGRST116') {
      throw error;
    }

    const beautyPreferences = profileData?.beauty_preferences || {};

    return successResponse(beautyPreferences);
  } catch (error) {
    return handleApiError(error, "Failed to fetch beauty preferences");
  }
}

/**
 * PATCH /api/me/beauty-preferences
 * 
 * Update current user's beauty preferences
 */
export async function PATCH(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer();
    const body = await request.json();

    const {
      hair_type,
      skin_type,
      allergies,
      things_to_avoid,
      appointment_style,
      preferred_times,
      preferred_days,
      product_preferences,
    } = body;

    // Get existing profile
    const { data: existingProfile } = await supabase
      .from("user_profiles")
      .select("beauty_preferences")
      .eq("user_id", user.id)
      .maybeSingle();

    const currentPreferences = existingProfile?.beauty_preferences || {};

    // Merge with new preferences (only update provided fields)
    const updatedPreferences: Record<string, any> = {
      ...currentPreferences,
    };

    if (hair_type !== undefined) updatedPreferences.hair_type = hair_type;
    if (skin_type !== undefined) updatedPreferences.skin_type = skin_type;
    if (allergies !== undefined) updatedPreferences.allergies = allergies || [];
    if (things_to_avoid !== undefined) updatedPreferences.things_to_avoid = things_to_avoid;
    if (appointment_style !== undefined) updatedPreferences.appointment_style = appointment_style;
    if (preferred_times !== undefined) updatedPreferences.preferred_times = preferred_times || [];
    if (preferred_days !== undefined) updatedPreferences.preferred_days = preferred_days || [];
    if (product_preferences !== undefined) updatedPreferences.product_preferences = product_preferences;

    // Update or insert profile
    const { data: profileData, error: checkError } = await supabase
      .from("user_profiles")
      .select("id")
      .eq("user_id", user.id)
      .maybeSingle();

    if (checkError && checkError.code !== 'PGRST116') {
      throw checkError;
    }

    let result;
    if (profileData) {
      // Update existing profile
      const { data, error } = await supabase
        .from("user_profiles")
        .update({ beauty_preferences: updatedPreferences })
        .eq("user_id", user.id)
        .select("beauty_preferences")
        .single();

      if (error) {
        throw error;
      }
      result = data?.beauty_preferences || {};
    } else {
      // Create new profile with beauty preferences
      const { data, error } = await supabase
        .from("user_profiles")
        .insert({
          user_id: user.id,
          beauty_preferences: updatedPreferences,
        })
        .select("beauty_preferences")
        .single();

      if (error) {
        throw error;
      }
      result = data?.beauty_preferences || {};
    }

    return successResponse(result);
  } catch (error) {
    return handleApiError(error, "Failed to update beauty preferences");
  }
}

import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  handleApiError,
  successResponse,
  notFoundResponse,
  errorResponse,
} from "@/lib/supabase/api-helpers";
import { z } from "zod";
import type { Booking } from "@/types/beautonomi";

const approvePaymentSchema = z.object({
  charge_id: z.string().uuid(),
  approved: z.boolean(),
});

/**
 * POST /api/me/bookings/[id]/approve-payment
 * 
 * Customer approves or rejects additional payment request
 */
export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer();
    const { id } = await params;
    const body = await request.json();

    const validationResult = approvePaymentSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    const { charge_id, approved } = validationResult.data;

    // Ensure booking belongs to customer
    const { data: booking, error: bookingError } = await supabase
      .from("bookings")
      .select("id")
      .eq("id", id)
      .eq("customer_id", user.id)
      .single();

    if (bookingError || !booking) {
      return notFoundResponse("Booking not found");
    }

    // Update additional charge row
    const { data: chargeRow, error: chargeError } = await (supabase
      .from("additional_charges") as any)
      .update({
        status: approved ? "approved" : "rejected",
        approved_at: approved ? new Date().toISOString() : null,
        approved_by: approved ? user.id : null,
      })
      .eq("id", charge_id)
      .eq("booking_id", id)
      .select("*")
      .single();

    if (chargeError || !chargeRow) {
      return notFoundResponse("Charge not found");
    }

    // Notify provider owner
    try {
      const { sendToUser } = await import("@/lib/notifications/onesignal");
      const { data: bookingRow } = await supabase
        .from("bookings")
        .select("provider_id, booking_number")
        .eq("id", id)
        .single();

      const providerId = (bookingRow as any)?.provider_id;
      if (providerId) {
        const { data: providerRow } = await supabase
          .from("providers")
          .select("user_id")
          .eq("id", providerId)
          .single();

        const providerUserId = (providerRow as any)?.user_id;
        if (providerUserId) {
          await sendToUser(providerUserId, {
            title: "Additional Payment Update",
            message: `Customer has ${approved ? "approved" : "rejected"} an additional payment request for booking ${(bookingRow as any)?.booking_number || ""}.`,
            data: {
              type: approved ? "additional_payment_approved" : "additional_payment_rejected",
              booking_id: id,
              charge_id,
            },
            url: `/provider/bookings/${id}`,
          });
        }
      }
    } catch (notifError) {
      console.error("Error notifying provider about approval:", notifError);
    }

    // Create booking event
    await supabase
      .from("booking_events")
      .insert({
        booking_id: id,
        event_type: approved ? "additional_payment_approved" : "additional_payment_rejected",
        event_data: {
          charge_id,
          approved,
        },
        created_by: user.id,
      });

    // Fetch updated booking
    const { data: updatedBooking } = await supabase
      .from("bookings")
      .select("*")
      .eq("id", id)
      .single();

    return successResponse({
      booking: updatedBooking as Booking,
      message: approved ? "Payment request approved" : "Payment request rejected",
    });
  } catch (error) {
    return handleApiError(error, "Failed to approve payment");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { successResponse, handleApiError, requireAuthInApi } from "@/lib/supabase/api-helpers";
import { getCancellationPolicy, canCancelBooking } from "@/lib/bookings/cancellation-policy";
import { trackServer } from "@/lib/analytics/amplitude/server";
import { EVENT_BOOKING_CANCELLED } from "@/lib/analytics/amplitude/types";

/**
 * POST /api/me/bookings/[id]/cancel
 * 
 * Cancel a booking (subject to cancellation policy)
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireAuthInApi(request);
    const { id: bookingId } = await params;

    const supabase = await getSupabaseServer();
    const adminSupabase = getSupabaseAdmin();

    // Load booking (include version for conflict detection)
    const { data: booking, error: bookingError } = await supabase
      .from('bookings')
      .select('id, provider_id, location_type, scheduled_at, created_at, status, customer_id, version, booking_number')
      .eq('id', bookingId)
      .single();

    if (bookingError || !booking) {
      return handleApiError(
        new Error("Booking not found"),
        "Booking not found",
        "NOT_FOUND",
        404
      );
    }

    // Verify user owns the booking
    if (booking.customer_id !== user.id) {
      return handleApiError(
        new Error("Unauthorized"),
        "You can only cancel your own bookings",
        "UNAUTHORIZED",
        403
      );
    }

    // Check if booking is already cancelled
    if (booking.status === 'cancelled') {
      return handleApiError(
        new Error("Booking already cancelled"),
        "This booking has already been cancelled",
        "ALREADY_CANCELLED",
        400
      );
    }

    // Load cancellation policy
    const policy = await getCancellationPolicy(
      supabase,
      booking.provider_id,
      booking.location_type as 'at_salon' | 'at_home'
    );

    if (!policy) {
      return handleApiError(
        new Error("Cancellation policy not found"),
        "Cancellation policy not configured",
        "POLICY_NOT_FOUND",
        500
      );
    }

    // Check if cancellation is allowed
    const checkResult = canCancelBooking(
      {
        id: booking.id,
        created_at: booking.created_at,
        scheduled_at: booking.scheduled_at,
        location_type: booking.location_type as 'at_salon' | 'at_home',
      },
      policy
    );

    if (!checkResult.allowed) {
      return handleApiError(
        new Error(checkResult.reason || "Cancellation not allowed"),
        checkResult.reason || "Cancellation not allowed",
        "CANCELLATION_BLOCKED",
        403
      );
    }

    // Get request body for optional fields
    let body: { reason?: string; version?: number } = {};
    try {
      body = await request.json().catch(() => ({}));
    } catch {
      // Body is optional
    }

    // Check for conflicts if version is provided in request body
    if (body.version !== undefined && (booking as any).version !== body.version) {
      return handleApiError(
        new Error("Booking was modified by another user"),
        "This booking was modified by another user. Please refresh and try again.",
        "CONFLICT",
        409
      );
    }

    // Cancel the booking (increment version for conflict detection)
    const currentVersion = (booking as any).version || 0;
    const { data: updatedBooking, error: updateError } = await adminSupabase
      .from('bookings')
      .update({
        status: 'cancelled',
        cancelled_at: new Date().toISOString(),
        cancelled_by: user.id,
        cancellation_reason: body.reason || 'Customer cancellation',
        version: currentVersion + 1, // Increment version
        updated_at: new Date().toISOString(),
      })
      .eq('id', bookingId)
      .select()
      .single();

    if (updateError) {
      throw updateError;
    }

    // Create booking event
    await adminSupabase.from('booking_events').insert({
      booking_id: bookingId,
      event_type: 'cancelled',
      event_data: {
        cancelled_by: user.id,
        policy_applied: policy.id,
        grace_window_used: checkResult.allowed && new Date(booking.created_at).getTime() + policy.grace_window_minutes * 60000 >= new Date().getTime(),
      },
      created_by: user.id,
    });

    // Create audit log entry
    try {
      const { data: userData } = await supabase
        .from("users")
        .select("full_name, email")
        .eq("id", user.id)
        .single();

      await adminSupabase
        .from("booking_audit_log")
        .insert({
          booking_id: bookingId,
          event_type: "cancelled",
          event_data: {
            previous_status: booking.status,
            new_status: "cancelled",
            field: "status",
            old_value: booking.status,
            new_value: "cancelled",
            cancelled_by: "customer",
            cancellation_reason: body.reason || 'Customer cancellation',
            policy_applied: policy.id,
          },
          created_by: user.id,
          created_by_name: userData?.full_name || userData?.email || "Customer",
        });
    } catch (auditError) {
      // Log but don't fail the request if audit logging fails
      console.error("Failed to create audit log entry:", auditError);
    }

    // Check if this is a group booking
    const { data: groupBookingData } = await supabase
      .from('group_bookings')
      .select('id, status')
      .eq('primary_contact_booking_id', bookingId)
      .single();

    const isGroupBooking = !!groupBookingData;

    // Send cancellation notification
    const { sendCancellationNotification } = await import('@/lib/bookings/notifications');
    const refundInfo = policy.late_cancellation_type === 'full_refund' 
      ? 'Full refund will be processed'
      : policy.late_cancellation_type === 'partial_refund'
      ? 'Partial refund will be processed'
      : 'No refund applicable per cancellation policy';

    await sendCancellationNotification(bookingId, {
      cancelledBy: 'customer',
      refundInfo,
    });

    // If group booking, cancel entire group and notify all participants
    if (isGroupBooking && groupBookingData) {
      try {
        const { cancelGroupBooking, getGroupBookingParticipantsForCancellation } = await import('@/lib/bookings/group-booking-cancellation');
        await cancelGroupBooking(supabase, groupBookingData.id, user.id, body.reason || 'Customer cancellation');

        // Notify all participants
        const participants = await getGroupBookingParticipantsForCancellation(supabase, groupBookingData.id);
        for (const participant of participants) {
          if (participant.participant_email) {
            // Send cancellation email to participant
            await fetch('/api/notifications/send-email', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                to: participant.participant_email,
                subject: `Group Booking Cancelled - ${booking.booking_number || bookingId}`,
                body: `Hi ${participant.participant_name}, the group booking ${booking.booking_number || bookingId} has been cancelled. ${refundInfo}`,
                type: 'group_booking_cancellation',
              }),
            }).catch(() => {});
          }
        }
      } catch (groupError) {
        console.error('Error handling group booking cancellation:', groupError);
        // Don't fail the cancellation if group handling fails
      }
    }

    // Invalidate availability cache for the cancelled booking
    try {
      const { invalidateAvailabilityCache } = await import('@/lib/availability/cache-invalidation');
      const { data: bookingServices } = await supabase
        .from('booking_services')
        .select('staff_id, scheduled_start_at')
        .eq('booking_id', bookingId)
        .limit(1);

      if (bookingServices && bookingServices.length > 0) {
        const service = bookingServices[0];
        const cancelledDate = new Date(service.scheduled_start_at).toISOString().split('T')[0];
        if (service.staff_id) {
          await invalidateAvailabilityCache(supabase, service.staff_id, cancelledDate);
        }
      }
    } catch (cacheError) {
      console.error('Error invalidating availability cache:', cacheError);
    }

    // Match waitlist entries for the cancelled slot
    try {
      const { matchWaitlistOnCancellation } = await import('@/lib/waitlist/matching');
      await matchWaitlistOnCancellation(supabase, bookingId);
    } catch (waitlistError) {
      // Don't fail cancellation if waitlist matching fails
      console.error('Error matching waitlist on cancellation:', waitlistError);
    }

    // Process refunds if applicable (based on late_cancellation_type)
    if (checkResult.allowed && policy.late_cancellation_type !== 'no_refund') {
      try {
        const { processBookingRefund } = await import('@/lib/bookings/refund-processing');
        const { data: bookingForRefund } = await supabase
          .from('bookings')
          .select('total_amount, currency')
          .eq('id', bookingId)
          .single();

        if (bookingForRefund) {
          const refundResult = await processBookingRefund(
            bookingId,
            bookingForRefund.total_amount,
            bookingForRefund.currency || 'ZAR',
            policy
          );

          if (refundResult.success && refundResult.amount && refundResult.amount > 0) {
            // Refund processed successfully
            console.log(`Refund processed: ${refundResult.amount} ${bookingForRefund.currency}`);
          }
        }
      } catch (refundError) {
        // Log but don't fail cancellation if refund fails
        console.error('Error processing refund during cancellation:', refundError);
      }
    }

    // Track Amplitude event
    try {
      await trackServer(EVENT_BOOKING_CANCELLED, {
        portal: "client",
        provider_id: booking.provider_id,
        booking_id: bookingId,
        cancellation_reason: body.reason || "user_requested",
      }, user.id);
    } catch (amplitudeError) {
      console.error("[Amplitude] Failed to track booking cancellation:", amplitudeError);
    }

    return successResponse({
      booking: updatedBooking,
      policy_applied: policy,
      message: "Booking cancelled successfully",
    });
  } catch (error) {
    return handleApiError(error, "Failed to cancel booking");
  }
}

import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  handleApiError,
  successResponse,
  notFoundResponse,
  errorResponse,
} from "@/lib/supabase/api-helpers";
import { z } from "zod";
import type { Booking } from "@/types/beautonomi";
import { convertToSmallestUnit, generateTransactionReference } from "@/lib/payments/paystack";
import { initializePaystackTransaction } from "@/lib/payments/paystack-server";

const payAdditionalSchema = z.object({
  charge_id: z.string().uuid(),
  payment_method: z.string().optional(),
});

/**
 * POST /api/me/bookings/[id]/pay-additional
 * 
 * Process payment for approved additional charge
 */
export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer();
    const { id } = await params;
    const body = await request.json();

    const validationResult = payAdditionalSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    const { charge_id, payment_method } = validationResult.data;

    // Get booking
    const { data: booking, error: bookingError } = await supabase
      .from("bookings")
      .select("*")
      .eq("id", id)
      .eq("customer_id", user.id)
      .single();

    if (bookingError || !booking) {
      return notFoundResponse("Booking not found");
    }

    const bookingData = booking as any;

    // Get charge row from real table
    const { data: charge, error: chargeError } = await (supabase
      .from("additional_charges") as any)
      .select("*")
      .eq("id", charge_id)
      .eq("booking_id", id)
      .single();

    if (chargeError || !charge) {
      return notFoundResponse("Charge not found");
    }

    // Check if charge is approved
    if ((charge as any).status !== "approved") {
      return errorResponse("Charge must be approved before payment", "INVALID_STATUS", 400);
    }

    // Initialize Paystack payment for the additional charge
    const { data: userEmailRow } = await supabase
      .from("users")
      .select("email")
      .eq("id", bookingData.customer_id)
      .single();

    const {
      data: { user: authUser },
    } = await supabase.auth.getUser();

    const email = userEmailRow?.email || authUser?.email;
    if (!email) {
      return errorResponse("User email is required for payment", "VALIDATION_ERROR", 400);
    }

    const reference = generateTransactionReference("additional", `${id}:${charge_id}`);
    const callbackUrl = `${process.env.NEXT_PUBLIC_APP_URL || ""}/checkout/success`;

    const paystackData = await initializePaystackTransaction({
      email,
      amountInSmallestUnit: convertToSmallestUnit(Number((charge as any).amount || 0)),
      currency: (charge as any).currency || bookingData.currency || "ZAR",
      reference,
      callback_url: callbackUrl,
      metadata: {
        booking_id: id,
        additional_charge_id: charge_id,
        customer_id: bookingData.customer_id,
      },
    });

    const paymentUrl = paystackData?.data?.authorization_url || null;

    // Create a payments row for tracking (do NOT overwrite booking.payment_reference)
    await (supabase.from("payments") as any).insert({
      booking_id: id,
      user_id: bookingData.customer_id,
      provider_id: bookingData.provider_id,
      payment_number: "",
      amount: Number((charge as any).amount || 0),
      currency: (charge as any).currency || bookingData.currency || "ZAR",
      status: "pending",
      payment_provider: "paystack",
      payment_provider_transaction_id: reference,
      payment_provider_response: paystackData,
      description: `Additional charge for booking ${bookingData.booking_number}`,
      metadata: {
        type: "additional_charge",
        additional_charge_id: charge_id,
        payment_method: payment_method || null,
      },
    });

    // Create booking event
    await supabase
      .from("booking_events")
      .insert({
        booking_id: id,
        event_type: "additional_payment_initiated",
        event_data: {
          charge_id,
          amount: (charge as any).amount,
          payment_method,
          reference,
        },
        created_by: user.id,
      });

    // Fetch updated booking
    const { data: updatedBooking } = await supabase
      .from("bookings")
      .select("*")
      .eq("id", id)
      .single();

    return successResponse({
      booking: updatedBooking as Booking,
      payment_url: paymentUrl,
      reference,
      message: "Additional payment initiated successfully",
    });
  } catch (error) {
    return handleApiError(error, "Failed to process payment");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { successResponse, handleApiError, requireAuthInApi } from "@/lib/supabase/api-helpers";
import { getCancellationPolicy, canCancelBooking } from "@/lib/bookings/cancellation-policy";
import { loadAvailabilityConstraints } from "@/lib/availability/load-constraints";
import { calculateAvailableSlots } from "@/lib/availability/calculate-slots";
import { z } from "zod";
import { trackServer } from "@/lib/analytics/amplitude/server";
import { EVENT_BOOKING_RESCHEDULED } from "@/lib/analytics/amplitude/types";

const rescheduleSchema = z.object({
  new_datetime: z.string().datetime("Invalid datetime format"),
});

/**
 * POST /api/me/bookings/[id]/reschedule
 * 
 * Reschedule a booking (subject to cancellation policy and availability)
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireAuthInApi(request);
    const { id: bookingId } = await params;
    const body = await request.json();

    // Validate input
    const validated = rescheduleSchema.parse(body);
    const newDatetime = new Date(validated.new_datetime);

    const supabase = await getSupabaseServer();
    const adminSupabase = getSupabaseAdmin();

    // Load booking with services
    const { data: booking, error: bookingError } = await supabase
      .from('bookings')
      .select(`
        id,
        provider_id,
        location_type,
        scheduled_at,
        created_at,
        status,
        customer_id,
        booking_services (
          id,
          offering_id,
          staff_id,
          scheduled_start_at,
          scheduled_end_at,
          duration_minutes,
          offerings:offerings!booking_services_offering_id_fkey!inner(buffer_minutes, duration_minutes)
        )
      `)
      .eq('id', bookingId)
      .single();

    if (bookingError || !booking) {
      return handleApiError(
        new Error("Booking not found"),
        "Booking not found",
        "NOT_FOUND",
        404
      );
    }

    // Verify user owns the booking
    if (booking.customer_id !== user.id) {
      return handleApiError(
        new Error("Unauthorized"),
        "You can only reschedule your own bookings",
        "UNAUTHORIZED",
        403
      );
    }

    // Check if booking is part of a group booking
    const { data: participant } = await supabase
      .from('booking_participants')
      .select('group_booking_id, is_primary_contact')
      .eq('booking_id', bookingId)
      .single();

    if (participant?.group_booking_id) {
      // If part of group, only primary contact can reschedule
      if (!participant.is_primary_contact) {
        // Get primary contact info
        const { data: groupBooking } = await supabase
          .from('group_bookings')
          .select('primary_contact_booking_id, bookings!primary_contact_booking_id(customer_id, users!inner(email))')
          .eq('id', participant.group_booking_id)
          .single();

        const primaryContactEmail = (groupBooking as any)?.bookings?.users?.email || 'the primary contact';

        return handleApiError(
          new Error("Only the primary contact can reschedule group bookings"),
          `Only the primary contact can reschedule group bookings. Please contact ${primaryContactEmail}.`,
          "GROUP_BOOKING_RESTRICTION",
          403
        );
      }
    }

    // Check if booking can be rescheduled (same policy as cancellation)
    const policy = await getCancellationPolicy(
      supabase,
      booking.provider_id,
      booking.location_type as 'at_salon' | 'at_home'
    );

    if (policy) {
      const checkResult = canCancelBooking(
        {
          id: booking.id,
          created_at: booking.created_at,
          scheduled_at: booking.scheduled_at,
          location_type: booking.location_type as 'at_salon' | 'at_home',
        },
        policy
      );

      if (!checkResult.allowed) {
        return handleApiError(
          new Error(checkResult.reason || "Rescheduling not allowed"),
          checkResult.reason || "Rescheduling not allowed",
          "RESCHEDULE_BLOCKED",
          403
        );
      }
    }

    // Check if new time slot is available
    const bookingServices = booking.booking_services as any[];
    if (bookingServices.length === 0) {
      return handleApiError(
        new Error("Booking has no services"),
        "Booking has no services",
        "VALIDATION_ERROR",
        400
      );
    }

    const firstService = bookingServices[0];
    const staffId = firstService.staff_id;

    if (!staffId) {
      return handleApiError(
        new Error("Booking has no assigned staff"),
        "Booking has no assigned staff",
        "VALIDATION_ERROR",
        400
      );
    }

    // Total blocked span = sum(durations) + sum(buffers) to match book flow
    let totalDuration = 0;
    bookingServices.forEach((bs: any) => {
      const dur = bs.duration_minutes ?? bs.offerings?.duration_minutes ?? 60;
      const buf = bs.offerings?.buffer_minutes ?? 15;
      totalDuration += dur + buf;
    });

    // Load availability constraints for new date
    const newDate = newDatetime.toISOString().split('T')[0];
    const constraints = await loadAvailabilityConstraints(supabase, staffId, newDate);

    // Check if new slot is available
    const slots = calculateAvailableSlots(
      constraints,
      totalDuration,
      newDate,
      {
        slotInterval: 15,
        travelBuffer: booking.location_type === 'at_home' ? 30 : 0,
      }
    );

    const requestedTime = newDatetime.toTimeString().substring(0, 5); // HH:MM
    const isAvailable = slots.some((slot) => slot.time === requestedTime && slot.available);

    if (!isAvailable) {
      return handleApiError(
        new Error("Selected time slot is not available"),
        "Selected time slot is not available. Please choose another time.",
        "SLOT_UNAVAILABLE",
        409
      );
    }

    // Update booking scheduled_at
    const { data: updatedBooking, error: updateError } = await adminSupabase
      .from('bookings')
      .update({
        scheduled_at: newDatetime.toISOString(),
      })
      .eq('id', bookingId)
      .select()
      .single();

    if (updateError) {
      throw updateError;
    }

    // Update all booking_services with new times
    let cursor = newDatetime;
    const updatePromises = bookingServices.map(async (bs: any) => {
      const start = new Date(cursor);
      const duration = bs.duration_minutes || bs.offerings?.duration_minutes || 60;
      const end = new Date(start.getTime() + duration * 60000);
      const buffer = bs.offerings?.buffer_minutes || 15;

      const { error } = await adminSupabase
        .from('booking_services')
        .update({
          scheduled_start_at: start.toISOString(),
          scheduled_end_at: end.toISOString(),
        })
        .eq('id', bs.id);

      if (error) {
        throw error;
      }

      // Advance cursor by duration + buffer
      cursor = new Date(end.getTime() + buffer * 60000);
    });

    await Promise.all(updatePromises);

    // Create booking event
    await adminSupabase.from('booking_events').insert({
      booking_id: bookingId,
      event_type: 'rescheduled',
      event_data: {
        old_datetime: booking.scheduled_at,
        new_datetime: newDatetime.toISOString(),
        rescheduled_by: user.id,
      },
      created_by: user.id,
    });

    // Send reschedule notification
    const { sendRescheduleNotification } = await import('@/lib/bookings/notifications');
    await sendRescheduleNotification(
      bookingId,
      new Date(booking.scheduled_at),
      newDatetime
    );

    // Track Amplitude event
    try {
      await trackServer(EVENT_BOOKING_RESCHEDULED, {
        portal: "client",
        provider_id: booking.provider_id,
        booking_id: bookingId,
        old_scheduled_at: booking.scheduled_at,
        new_scheduled_at: newDatetime.toISOString(),
      }, user.id);
    } catch (amplitudeError) {
      console.error("[Amplitude] Failed to track booking reschedule:", amplitudeError);
    }

    return successResponse({
      booking: updatedBooking,
      message: "Booking rescheduled successfully",
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        new Error(error.issues.map((e: any) => e.message).join(", ")),
        "Validation failed",
        "VALIDATION_ERROR",
        400
      );
    }
    return handleApiError(error, "Failed to reschedule booking");
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi } from "@/lib/supabase/api-helpers";
/**
 * GET /api/me/bookings/[id]
 * 
 * Get a specific booking by ID
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);

    const supabase = await getSupabaseServer();
    const { id } = await params;

    const { data: booking, error } = await supabase
      .from("bookings")
      .select(`
        *,
        version,
        provider:providers(
          id,
          business_name,
          slug,
          phone,
          email
        ),
        group_bookings(ref_number),
        location:provider_locations(
          id,
          name,
          address_line1,
          address_line2,
          city,
          country
        ),
        booking_services:booking_services(
          id,
          offering_id,
          staff_id,
          duration_minutes,
          price,
          guest_name,
          offering:offerings(
            id,
            title,
            duration_minutes,
            price
          ),
          staff:provider_staff(
            id,
            name
          )
        ),
        booking_addons:booking_addons(
          id,
          addon_id,
          quantity,
          price,
          offering:offerings(
            id,
            title,
            price
          )
        ),
        booking_products:booking_products(
          id,
          product_id,
          quantity,
          unit_price,
          total_price,
          products:products!booking_products_product_id_fkey(
            id,
            name,
            retail_price
          )
        ),
        additional_charges:additional_charges(
          id,
          description,
          amount,
          currency,
          status,
          requested_at,
          paid_at
        )
      `)
      .eq("id", id)
      .eq("customer_id", auth.user.id)
      .single();

    if (error || !booking) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Booking not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    // Transform booking data to match confirmation page format
    const bookingData = booking as any;
    const transformedBooking = {
      id: bookingData.id,
      booking_number: bookingData.booking_number,
      status: bookingData.status,
      selected_datetime: bookingData.scheduled_at,
      location_type: bookingData.location_type === "at_salon" ? "at_salon" : "at_home",
      total_amount: bookingData.total_amount,
      currency: bookingData.currency,
      services: (bookingData.booking_services || []).map((bs: any) => ({
        id: bs.id,
        offering_id: bs.offering_id,
        offering_name: bs.offering?.title || "Service",
        staff_id: bs.staff_id,
        staff_name: bs.staff?.name || null,
        duration_minutes: bs.duration_minutes || bs.offering?.duration_minutes || 0,
        price: bs.price || bs.offering?.price || 0,
        guest_name: bs.guest_name || undefined,
      })),
      addons: (bookingData.booking_addons || []).map((ba: any) => ({
        id: ba.id,
        offering_id: ba.addon_id, // Note: addon_id references offerings table
        offering_name: ba.offering?.title || "Addon",
        price: ba.price || ba.offering?.price || 0,
      })),
      products: (bookingData.booking_products || []).map((bp: any) => ({
        id: bp.id,
        product_id: bp.product_id,
        product_name: bp.products?.name || "Product",
        quantity: bp.quantity || 1,
        unit_price: bp.unit_price || bp.products?.retail_price || 0,
        total_price: bp.total_price || (bp.unit_price || bp.products?.retail_price || 0) * (bp.quantity || 1),
      })),
      address: bookingData.location_type === "at_home" && bookingData.address_line1 ? {
        line1: bookingData.address_line1 || "",
        line2: bookingData.address_line2 || undefined,
        city: bookingData.address_city || "",
        state: bookingData.address_state || undefined,
        country: bookingData.address_country || "",
        postal_code: bookingData.address_postal_code || undefined,
        latitude: bookingData.address_latitude || undefined,
        longitude: bookingData.address_longitude || undefined,
      } : null,
      location: bookingData.location ? {
        name: bookingData.location.name,
        address: [
          bookingData.location.address_line1,
          bookingData.location.address_line2,
          bookingData.location.city,
          bookingData.location.country,
        ].filter(Boolean).join(", "),
      } : undefined,
      client_info: {
        first_name: auth.user.user_metadata?.first_name || "",
        last_name: auth.user.user_metadata?.last_name || "",
        email: auth.user.email || "",
        phone: auth.user.user_metadata?.phone || "",
      },
      special_requests: bookingData.special_requests,
      is_group_booking: !!bookingData.group_booking_id,
      group_booking_ref: bookingData.group_bookings?.ref_number ?? null,
      provider: bookingData.provider ? {
        id: bookingData.provider.id,
        business_name: bookingData.provider.business_name,
        slug: bookingData.provider.slug,
        phone: bookingData.provider.phone,
        email: bookingData.provider.email,
      } : undefined,
      additional_charges: (bookingData.additional_charges || []).map((ac: any) => ({
        id: ac.id,
        description: ac.description,
        amount: Number(ac.amount),
        currency: ac.currency,
        status: ac.status,
        requested_at: ac.requested_at,
        paid_at: ac.paid_at,
      })),
      // Calculate outstanding balance (original booking + unpaid additional charges - total_paid)
      outstanding_balance: (() => {
        const bookingTotal = Number(bookingData.total_amount || 0);
        const totalPaid = Number(bookingData.total_paid || 0);
        const unpaidCharges = (bookingData.additional_charges || [])
          .filter((ac: any) => ac.status !== 'paid' && ac.status !== 'rejected')
          .reduce((sum: number, ac: any) => sum + Number(ac.amount || 0), 0);
        return Math.max(0, bookingTotal + unpaidCharges - totalPaid);
      })(),
    };

    return NextResponse.json({
      data: transformedBooking,
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/me/bookings/[id]:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch booking",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  handleApiError,
  successResponse,
  notFoundResponse,
  errorResponse,
} from "@/lib/supabase/api-helpers";
import { isValidOTPFormat, isOTPExpired } from "@/lib/otp/generator";
import type { Booking } from "@/types/beautonomi";
import { z } from "zod";

const verifyArrivalSchema = z.object({
  otp: z.string().min(6).max(6),
});

/**
 * POST /api/me/bookings/[id]/verify-arrival
 * 
 * Customer verifies provider arrival with OTP
 * Only for at-home bookings
 */
export async function POST(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Allow any authenticated user (customer, provider, etc.)
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer();
    const { id } = await params;
    const body = await request.json();

    const validationResult = verifyArrivalSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Invalid OTP format",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    const { otp } = validationResult.data;

    // Validate OTP format
    if (!isValidOTPFormat(otp)) {
      return errorResponse("OTP must be 6 digits", "INVALID_OTP_FORMAT", 400);
    }

    // Get booking
    const { data: booking, error: bookingError } = await supabase
      .from("bookings")
      .select("*")
      .eq("id", id)
      .eq("customer_id", user.id)
      .single();

    if (bookingError || !booking) {
      return notFoundResponse("Booking not found");
    }

    const bookingData = booking as any;

    // Only allow for at-home bookings
    if (bookingData.location_type !== "at_home") {
      return errorResponse("This endpoint is only for at-home bookings", "INVALID_REQUEST", 400);
    }

    // Check if OTP exists
    if (!bookingData.arrival_otp) {
      return errorResponse("No OTP has been generated for this booking", "NO_OTP", 400);
    }

    // Check if OTP is expired
    if (bookingData.arrival_otp_expires_at && isOTPExpired(bookingData.arrival_otp_expires_at)) {
      return errorResponse(
        "OTP has expired. Please request a new one from the provider.",
        "OTP_EXPIRED",
        400
      );
    }

    // Check if already verified
    if (bookingData.arrival_otp_verified) {
      return errorResponse("OTP has already been verified", "ALREADY_VERIFIED", 400);
    }

    // Verify OTP
    if (bookingData.arrival_otp !== otp) {
      return errorResponse("Invalid OTP. Please check and try again.", "INVALID_OTP", 400);
    }

    // Create OTP verified event
    const { error: eventError } = await supabase
      .from("booking_events")
      .insert({
        booking_id: id,
        event_type: "otp_verified",
        event_data: {
          verified_at: new Date().toISOString(),
        },
        created_by: user.id,
      });

    if (eventError) {
      console.error("Error creating booking event:", eventError);
      // Continue - OTP verification is the important part
    }

    // Update booking
    const { error: updateError } = await supabase
      .from("bookings")
      .update({
        arrival_otp_verified: true,
        updated_at: new Date().toISOString(),
      })
      .eq("id", id);

    if (updateError) {
      return handleApiError(updateError, "Failed to update booking");
    }

    // Fetch updated booking
    const { data: updatedBooking } = await supabase
      .from("bookings")
      .select("*")
      .eq("id", id)
      .single();

    return successResponse({
      booking: updatedBooking as Booking,
      message: "OTP verified successfully. Provider arrival confirmed.",
    });
  } catch (error) {
    return handleApiError(error, "Failed to verify OTP");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, getPaginationParams, createPaginatedResponse } from "@/lib/supabase/api-helpers";
import type { Booking, PaginatedResponse } from "@/types/beautonomi";
import { mapStatusFromCustomer, mapStatusToCustomer } from "@/lib/utils/booking-status";

/**
 * GET /api/me/bookings
 * 
 * Get current user's bookings
 */
export async function GET(request: NextRequest) {
  try {
    // Require customer role (or provider/admin who can also be customers)
    let user;
    try {
      const authResult = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
      user = authResult.user;
    } catch (authError) {
      console.error("Auth error in bookings API:", authError);
      return handleApiError(authError, "Authentication failed");
    }

    const supabase = await getSupabaseServer();
    const { searchParams } = new URL(request.url);

    const status = searchParams.get("status");
    const { page, limit, offset } = getPaginationParams(request);

    console.log("Bookings API called:", { status, page, limit, offset, userId: user.id });

    // Start with a basic query (include version for conflict detection and booking_services)
    let query = supabase
      .from("bookings")
      .select(`
        *,
        version,
        provider:providers (
          id,
          business_name,
          slug
        ),
        group_bookings (
          ref_number
        ),
        booking_services (
          id,
          offering_id,
          staff_id,
          duration_minutes,
          price,
          guest_name,
          offering:offerings (
            id,
            title,
            duration_minutes,
            price
          ),
          staff:provider_staff (
            id,
            name
          )
        ),
        booking_addons (
          id,
          addon_id,
          quantity,
          price,
          offering:offerings (
            id,
            title,
            price
          )
        ),
        booking_products (
          id,
          product_id,
          quantity,
          unit_price,
          total_price,
          products:products!booking_products_product_id_fkey (
            id,
            name,
            retail_price
          )
        )
      `, { count: "exact" })
      .eq("customer_id", user.id);

    // Map frontend status values to database queries using centralized utility
    const now = new Date().toISOString();

    // For "past" status, we need to fetch all non-cancelled bookings and filter in memory
    // because we need to match: (status = 'completed' OR scheduled_at < now)
    const needsInMemoryFilter = status === "past";

    // Apply status filters using centralized mapping
    if (status === "upcoming") {
      // Upcoming: pending, confirmed, or in_progress bookings scheduled in the future
      const dbStatuses = mapStatusFromCustomer("upcoming");
      query = query
        .in("status", dbStatuses)
        .gte("scheduled_at", now);
    } else if (status === "past") {
      // Past: fetch all non-cancelled bookings, we'll filter in memory
      query = query.neq("status", "cancelled");
    } else if (status === "cancelled") {
      // Cancelled: only cancelled bookings
      query = query.eq("status", "cancelled");
    } else if (status) {
      // If a specific status is provided, use it directly
      query = query.eq("status", status);
    }

    // Add ordering
    query = query.order("scheduled_at", { ascending: false });

    // For "past" status, fetch all matching records first to get accurate count
    let allBookings: any[] = [];
    let totalCount = 0;

    if (needsInMemoryFilter) {
      // Fetch all bookings without pagination to filter properly
      try {
        const { data: allData, error: allError, count: allCount } = await query;
        if (allError) {
          console.error("Bookings query error (all):", {
            error: allError,
            message: allError.message,
            details: allError.details,
            hint: allError.hint,
            code: allError.code,
          });
          // Return empty results for any query error
          allBookings = [];
          totalCount = 0;
        } else {
          allBookings = allData || [];
          totalCount = allCount || 0;
        }
      } catch (queryException) {
        console.error("Exception during bookings query (all):", queryException);
        allBookings = [];
        totalCount = 0;
      }
    } else {
      // For other statuses, use pagination
      try {
        const { data, error, count } = await query.range(offset, offset + limit - 1);
        if (error) {
          console.error("Bookings query error:", {
            error,
            message: error.message,
            details: error.details,
            hint: error.hint,
            code: error.code,
          });
          // For any query error when there might be no bookings, return empty results
          // This handles RLS issues, missing tables, etc. gracefully
          allBookings = [];
          totalCount = 0;
        } else {
          allBookings = data || [];
          totalCount = count || 0;
        }
      } catch (queryError) {
        console.error("Exception during bookings query:", queryError);
        // Return empty results instead of failing
        allBookings = [];
        totalCount = 0;
      }
    }

    // Filter "past" bookings in memory
    let filteredBookings = allBookings;
    if (needsInMemoryFilter) {
      filteredBookings = allBookings.filter(
        (booking) =>
          booking.status === "completed" ||
          (booking.scheduled_at && new Date(booking.scheduled_at) < new Date(now))
      );
      totalCount = filteredBookings.length;

      // Apply pagination after filtering
      filteredBookings = filteredBookings.slice(offset, offset + limit);
    }

    // Transform bookings to match Booking interface
    const transformedBookings = (filteredBookings || []).map((booking: any) => {
      // Keep database status for consistency, add customer status for display
      const customerStatus = mapStatusToCustomer(booking.status, booking.scheduled_at);

      // Transform booking_services to BookingServiceDetail format
      const services = (booking.booking_services || []).map((bs: any) => ({
        id: bs.id,
        offering_id: bs.offering_id,
        offering_name: bs.offering?.title || "Service",
        staff_id: bs.staff_id,
        staff_name: bs.staff?.name || null,
        duration_minutes: bs.duration_minutes || bs.offering?.duration_minutes || 0,
        price: bs.price || bs.offering?.price || 0,
        guest_name: bs.guest_name || undefined,
      }));

      // Transform booking_addons to BookingAddon format
      const addons = (booking.booking_addons || []).map((ba: any) => ({
        id: ba.id,
        offering_id: ba.addon_id, // Note: addon_id references offerings table
        offering_name: ba.offering?.title || "Addon",
        price: ba.price || ba.offering?.price || 0,
      }));

      // Transform booking_products
      const products = (booking.booking_products || []).map((bp: any) => ({
        id: bp.id,
        product_id: bp.product_id,
        product_name: bp.products?.name || "Product",
        quantity: bp.quantity || 1,
        unit_price: bp.unit_price || bp.products?.retail_price || 0,
        total_price: bp.total_price || (bp.unit_price || bp.products?.retail_price || 0) * (bp.quantity || 1),
      }));

      // Transform address if it exists
      const address = booking.location_type === "at_home" && booking.address_line1 ? {
        line1: booking.address_line1 || "",
        line2: booking.address_line2 || undefined,
        city: booking.address_city || "",
        state: booking.address_state || undefined,
        country: booking.address_country || "",
        postal_code: booking.address_postal_code || undefined,
        latitude: booking.address_latitude || undefined,
        longitude: booking.address_longitude || undefined,
      } : null;

      return {
        ...booking,
        // Keep database status for consistency, add customer status for display
        status: booking.status, // Database status (pending, confirmed, etc.)
        customer_status: customerStatus, // Customer portal status (upcoming, past, cancelled)
        provider_name: booking.provider?.business_name || "Provider",
        provider_slug: booking.provider?.slug || null,
        is_group_booking: !!booking.group_booking_id,
        group_booking_ref: booking.group_bookings?.ref_number ?? null,
        services,
        addons,
        products,
        address,
        // Ensure all required fields are present
        subtotal: booking.subtotal || 0,
        tip_amount: booking.tip_amount || 0,
        discount_amount: booking.discount_amount || 0,
        total_amount: booking.total_amount || 0,
        currency: booking.currency || "ZAR",
        payment_status: booking.payment_status || "pending",
        loyalty_points_earned: booking.loyalty_points_earned || 0,
        loyalty_points_used: booking.loyalty_points_used || 0,
      };
    });

    const result: PaginatedResponse<Booking> = createPaginatedResponse(
      transformedBookings as Booking[],
      totalCount,
      page,
      limit
    );

    console.log("Bookings API success:", { 
      status, 
      returnedCount: filteredBookings.length, 
      totalCount 
    });

    return successResponse(result);
  } catch (error) {
    console.error("Bookings API error details:", {
      error,
      message: error instanceof Error ? error.message : String(error),
      stack: error instanceof Error ? error.stack : undefined,
    });

    // Return empty results instead of error to prevent 500
    // This allows the UI to show "no bookings" instead of an error
    const emptyResult: PaginatedResponse<Booking> = createPaginatedResponse(
      [] as Booking[],
      0,
      1,
      20
    );

    return successResponse(emptyResult);
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  errorResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";
import { z } from "zod";

const updateSchema = z.object({
  quantity: z.number().int().min(1).max(100),
});

/**
 * PATCH /api/me/cart/[id]
 * Update cart item quantity
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    const { user } = await requireRoleInApi(
      ["customer", "provider_owner", "provider_staff", "superadmin"],
      request,
    );
    const body = await request.json();
    const parsed = updateSchema.parse(body);
    const supabase = await getSupabaseServer();

    // Get the cart item + product/variant stock
    const { data: cartItem, error: cartErr } = await (supabase.from("cart_items") as any)
      .select("id, product_id, product_variant_id, user_id")
      .eq("id", id)
      .eq("user_id", user.id)
      .single();

    if (cartErr || !cartItem) {
      return errorResponse("Cart item not found", "NOT_FOUND", 404);
    }

    let maxQty = 999;
    if (cartItem.product_variant_id) {
      const { data: variant } = await (supabase.from("product_variants") as any)
        .select("quantity")
        .eq("id", cartItem.product_variant_id)
        .single();
      maxQty = variant?.quantity ?? 0;
    } else {
      const { data: product } = await (supabase.from("products") as any)
        .select("quantity")
        .eq("id", cartItem.product_id)
        .single();
      maxQty = product?.quantity ?? 0;
    }

    if (parsed.quantity > maxQty) {
      return errorResponse(
        `Only ${maxQty} items available`,
        "INSUFFICIENT_STOCK",
        400,
      );
    }

    const { data, error } = await (supabase.from("cart_items") as any)
      .update({ quantity: parsed.quantity })
      .eq("id", id)
      .eq("user_id", user.id)
      .select()
      .single();

    if (error) throw error;

    return successResponse({ item: data });
  } catch (err) {
    return handleApiError(err, "Failed to update cart item");
  }
}

/**
 * DELETE /api/me/cart/[id]
 * Remove a single cart item
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    const { user } = await requireRoleInApi(
      ["customer", "provider_owner", "provider_staff", "superadmin"],
      request,
    );
    const supabase = await getSupabaseServer();

    const { error } = await (supabase.from("cart_items") as any)
      .delete()
      .eq("id", id)
      .eq("user_id", user.id);

    if (error) throw error;

    return successResponse({ deleted: true });
  } catch (err) {
    return handleApiError(err, "Failed to remove cart item");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  errorResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";
import { z } from "zod";

const addSchema = z.object({
  product_id: z.string().uuid(),
  product_variant_id: z.string().uuid().optional().nullable(),
  quantity: z.number().int().min(1).max(100).default(1),
});

/**
 * GET /api/me/cart
 * List cart items with product details + stock validation
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(
      ["customer", "provider_owner", "provider_staff", "superadmin"],
      request,
    );
    const supabase = await getSupabaseServer();

    const { data: items, error } = await (supabase.from("cart_items") as any)
      .select(
        `
        id,
        quantity,
        product_variant_id,
        created_at,
        updated_at,
        product:products (
          id, name, retail_price, image_urls, quantity, is_active, retail_sales_enabled,
          brand, category, provider_id, has_variants
        ),
        product_variant:product_variants (
          id, retail_price, quantity, option_values
        ),
        provider:providers (
          id, business_name, slug
        )
      `,
      )
      .eq("user_id", user.id)
      .order("created_at", { ascending: false });

    if (error) throw error;

    const enriched = (items ?? []).map((item: any) => {
      const effectiveQty = item.product_variant ? item.product_variant.quantity : item.product?.quantity ?? 0;
      const effectivePrice = item.product_variant ? item.product_variant.retail_price : item.product?.retail_price ?? 0;
      return {
        ...item,
        effective_price: effectivePrice,
        in_stock:
          item.product?.is_active &&
          item.product?.retail_sales_enabled &&
          effectiveQty >= item.quantity,
        stock_available: effectiveQty,
      };
    });

    return successResponse({ items: enriched });
  } catch (err) {
    return handleApiError(err, "Failed to fetch cart");
  }
}

/**
 * POST /api/me/cart
 * Add product to cart (upserts: increments quantity if already in cart)
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(
      ["customer", "provider_owner", "provider_staff", "superadmin"],
      request,
    );
    const body = await request.json();
    const parsed = addSchema.parse(body);
    const supabase = await getSupabaseServer();

    // Validate the product exists and is available
    const { data: product, error: prodErr } = await (supabase.from("products") as any)
      .select("id, provider_id, quantity, is_active, retail_sales_enabled, retail_price, name, has_variants")
      .eq("id", parsed.product_id)
      .single();

    if (prodErr || !product) {
      return errorResponse("Product not found", "NOT_FOUND", 404);
    }
    if (!product.is_active || !product.retail_sales_enabled) {
      return errorResponse("Product is not available for purchase", "UNAVAILABLE", 400);
    }

    const variantId = parsed.product_variant_id || null;
    let effectiveQuantity = product.quantity;
    if (product.has_variants && variantId) {
      const { data: variant, error: varErr } = await (supabase.from("product_variants") as any)
        .select("id, product_id, quantity, retail_price")
        .eq("id", variantId)
        .eq("product_id", parsed.product_id)
        .single();
      if (varErr || !variant) {
        return errorResponse("Variant not found", "NOT_FOUND", 404);
      }
      effectiveQuantity = variant.quantity ?? 0;
    } else if (product.has_variants && !variantId) {
      return errorResponse("Please select a variant", "VARIANT_REQUIRED", 400);
    }

    if (effectiveQuantity < parsed.quantity) {
      return errorResponse(
        `Only ${effectiveQuantity} items available`,
        "INSUFFICIENT_STOCK",
        400,
      );
    }

    // Upsert: match by (user_id, product_id, product_variant_id)
    const existingQuery = (supabase.from("cart_items") as any)
      .select("id, quantity")
      .eq("user_id", user.id)
      .eq("product_id", parsed.product_id);
    if (variantId) {
      existingQuery.eq("product_variant_id", variantId);
    } else {
      existingQuery.is("product_variant_id", null);
    }
    const { data: existing } = await existingQuery.maybeSingle();

    let result;
    if (existing) {
      const newQty = existing.quantity + parsed.quantity;
      if (newQty > effectiveQuantity) {
        return errorResponse(
          `Only ${effectiveQuantity} items available (you have ${existing.quantity} in cart)`,
          "INSUFFICIENT_STOCK",
          400,
        );
      }
      const { data, error } = await (supabase.from("cart_items") as any)
        .update({ quantity: newQty })
        .eq("id", existing.id)
        .select()
        .single();
      if (error) throw error;
      result = data;
    } else {
      const { data, error } = await (supabase.from("cart_items") as any)
        .insert({
          user_id: user.id,
          product_id: parsed.product_id,
          product_variant_id: variantId,
          provider_id: product.provider_id,
          quantity: parsed.quantity,
        })
        .select()
        .single();
      if (error) throw error;
      result = data;
    }

    return successResponse({ item: result }, 201);
  } catch (err) {
    return handleApiError(err, "Failed to add to cart");
  }
}

