import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { z } from "zod";

const createSchema = z.object({
  provider_id: z.string().uuid("Invalid provider ID"),
  booking_id: z.string().uuid().optional().nullable(),
});

/**
 * POST /api/me/conversations/create
 * 
 * Create a new conversation with a provider
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer();

    const body = createSchema.parse(await request.json());
    const { provider_id, booking_id } = body;

    // Check if conversation already exists
    // For conversations without booking_id, we should find any conversation with this provider
    // For conversations with booking_id, we should find the specific booking conversation
    let query = supabase
      .from("conversations")
      .select("id")
      .eq("customer_id", user.id)
      .eq("provider_id", provider_id);

    // Properly handle NULL booking_id comparison
    if (booking_id) {
      query = query.eq("booking_id", booking_id);
    } else {
      // For non-booking conversations, check for NULL booking_id
      query = query.is("booking_id", null);
    }

    const { data: existing } = await query.maybeSingle();

    if (existing) {
      return successResponse({ id: existing.id, created: false });
    }

    // Create new conversation
    const { data: newConv, error: createError } = await (supabase.from("conversations") as any)
      .insert({
        booking_id: booking_id || null,
        customer_id: user.id,
        provider_id: provider_id,
        last_message_at: new Date().toISOString(),
        last_message_preview: "",
        last_message_sender_id: user.id,
        unread_count_customer: 0,
        unread_count_provider: 0,
      })
      .select("id")
      .single();

    if (createError) throw createError;

    return successResponse({ id: newConv.id, created: true });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return errorResponse(error.issues.map((e: any) => e.message).join(", "), "VALIDATION_ERROR", 400);
    }
    return handleApiError(error, "Failed to create conversation");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, getPaginationParams, createPaginatedResponse } from "@/lib/supabase/api-helpers";
import type { Conversation, PaginatedResponse } from "@/types/beautonomi";

/**
 * GET /api/me/conversations
 *
 * Returns the current user's conversations ordered by most recent message.
 * Filters out conversations that have never had a message (no last_message_preview).
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);

    const bookingId = searchParams.get("booking_id");
    const { page, limit, offset } = getPaginationParams(request);
    const wantsPaginated = searchParams.has("page") || searchParams.has("limit");

    let query = supabase
      .from("conversations")
      .select(
        `
        id,
        booking_id,
        provider_id,
        customer_id,
        last_message_at,
        last_message_preview,
        unread_count_customer,
        unread_count_provider,
        provider:providers(id, business_name, thumbnail_url, avatar_url, phone, email),
        booking:bookings(id, booking_number)
      `,
        { count: "exact" }
      )
      .eq("customer_id", user.id)
      .not("last_message_at", "is", null)
      .order("last_message_at", { ascending: false, nullsFirst: false });

    if (bookingId) {
      query = query.eq("booking_id", bookingId);
    }

    const { data: conversations, error, count } = wantsPaginated
      ? await query.range(offset, offset + limit - 1)
      : await query.limit(50);

    if (error) {
      if (error.code === 'PGRST116' || error.message?.includes('permission') || error.message?.includes('does not exist')) {
        return successResponse([]);
      }
      throw error;
    }

    const mapped = (conversations || []).map((c: any) => ({
      id: c.id,
      booking_id: c.booking_id || null,
      provider_id: c.provider_id || null,
      customer_id: c.customer_id,
      last_message_at: c.last_message_at,
      unread_count: c.unread_count_customer ?? 0,
      provider_name: c.provider?.business_name || null,
      provider_phone: c.provider?.phone || null,
      provider_email: c.provider?.email || null,
      booking_number: c.booking?.booking_number || null,
      avatar: c.provider?.avatar_url ?? c.provider?.thumbnail_url ?? null,
      last_message_preview: c.last_message_preview || null,
      provider: c.provider
        ? { business_name: c.provider.business_name, thumbnail_url: c.provider.thumbnail_url, avatar_url: c.provider.avatar_url ?? null }
        : undefined,
      unread_count_customer: c.unread_count_customer ?? 0,
    }));

    if (!wantsPaginated) {
      return successResponse(mapped);
    }

    const result: PaginatedResponse<Conversation> = createPaginatedResponse(
      mapped as any,
      count ?? mapped.length,
      page,
      limit
    );

    return successResponse(result as any);
  } catch (error) {
    return handleApiError(error, "Failed to fetch conversations");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, notFoundResponse } from "@/lib/supabase/api-helpers";
import { initializePaystackTransaction } from "@/lib/payments/paystack-server";
import { computeCustomOfferPricing } from "../../_helpers/custom-offer-pricing";

export async function POST(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { user } = await requireRoleInApi(["customer", "superadmin"], request);
    const supabase = await getSupabaseServer();
    const { id } = await params;

    let body: { tip_amount?: number; promotion_code?: string } = {};
    try {
      body = (await request.json()) || {};
    } catch {
      // no body
    }

    // Load offer + request and validate ownership
    const { data: offerRow, error: offerError } = await supabase
      .from("custom_offers")
      .select("*, request:custom_requests(id, customer_id, provider_id, preferred_start_at, location_type)")
      .eq("id", id)
      .single();
    if (offerError || !offerRow) return notFoundResponse("Offer not found");

    const offer = offerRow as any;
    const req = offer.request as any;
    if (req?.customer_id !== user.id) return notFoundResponse("Offer not found");

    if (offer.status === "paid" || offer.status === "accepted") {
      return successResponse({ paymentUrl: offer.payment_url, alreadyAccepted: true });
    }

    // Expiry check
    if (offer.expiration_at && new Date(offer.expiration_at).getTime() < Date.now()) {
      await (supabase.from("custom_offers") as any).update({ status: "expired" }).eq("id", id);
      return handleApiError(new Error("Offer has expired"), "Offer expired");
    }

    const travelFee = Number(offer.travel_fee ?? 0) >= 0 ? Number(offer.travel_fee ?? 0) : 0;
    const pricing = await computeCustomOfferPricing(supabase, {
      offerPrice: Number(offer.price || 0),
      travelFee,
      currency: offer.currency || "ZAR",
      providerId: req.provider_id,
      customerId: req.customer_id,
      tipAmount: body.tip_amount,
      promotionCode: body.promotion_code ?? null,
      locationType: req.location_type || "at_salon",
      locationId: offer.location_id ?? null,
    });

    if (pricing.ok === false) {
      return handleApiError(new Error(pricing.error), pricing.error);
    }

    const { result } = pricing;
    const reference = `co_${id}_${Date.now()}`;
    const appUrl = process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000";
    const callbackUrl = `${appUrl}/checkout/success?payment_type=custom_offer&offer_id=${encodeURIComponent(id)}`;

    const email = (user as any).email || "customer@example.com";
    const amountKobo = Math.round(result.totalAmount * 100);

    const init = await initializePaystackTransaction({
      email,
      amountInSmallestUnit: amountKobo,
      currency: offer.currency || "ZAR",
      reference,
      callback_url: callbackUrl,
      metadata: {
        custom_offer_id: id,
        custom_request_id: offer.request_id,
        tip_amount: result.tipAmount,
        tax_amount: result.taxAmount,
        tax_rate: result.taxRate,
        travel_fee: result.travelFee,
        service_fee_amount: result.serviceFeeAmount,
        service_fee_percentage: result.serviceFeePercentage,
        promotion_id: result.promotionId ?? "",
        promotion_discount_amount: result.promotionDiscountAmount,
        commission_base: result.commissionBase,
      },
    });

    const paymentUrl = init.data.authorization_url;

    await (supabase.from("custom_offers") as any)
      .update({
        status: "payment_pending",
        payment_reference: reference,
        payment_url: paymentUrl,
        updated_at: new Date().toISOString(),
      })
      .eq("id", id);

    return successResponse({ paymentUrl });
  } catch (error) {
    return handleApiError(error, "Failed to accept offer");
  }
}

/**
 * Custom offer pricing: tax, platform service fee, promo code, tip.
 * Mirrors logic from validate-booking for consistency.
 */

import type { SupabaseClient } from "@supabase/supabase-js";
import { getEffectiveTaxRate } from "@/lib/platform-tax-settings";

export interface CustomOfferPricingInput {
  offerPrice: number;
  travelFee: number;
  currency: string;
  providerId: string;
  customerId: string;
  tipAmount?: number;
  promotionCode?: string | null;
  locationType?: "at_salon" | "at_home";
  locationId?: string | null;
}

export interface CustomOfferPricingResult {
  subtotal: number;
  travelFee: number;
  promotionId: string | null;
  promotionDiscountAmount: number;
  discountAmount: number;
  taxRate: number;
  taxAmount: number;
  serviceFeePercentage: number;
  serviceFeeAmount: number;
  tipAmount: number;
  totalAmount: number;
  commissionBase: number;
}

export async function computeCustomOfferPricing(
  supabase: SupabaseClient,
  input: CustomOfferPricingInput
): Promise<{ ok: true; result: CustomOfferPricingResult } | { ok: false; error: string }> {
  const {
    offerPrice,
    travelFee,
    currency,
    providerId,
    customerId,
    tipAmount: inputTip = 0,
    promotionCode = null,
    locationType = "at_salon",
    locationId = null,
  } = input;

  const subtotalBeforeDiscount = Math.max(0, offerPrice) + Math.max(0, travelFee);

  // Load provider for tax, tips, fee config
  const { data: provider } = await supabase
    .from("providers")
    .select("tax_rate_percent, tips_enabled, customer_fee_config_id")
    .eq("id", providerId)
    .single();

  const tipsEnabled = Boolean((provider as any)?.tips_enabled ?? true);
  const tipAmount = tipsEnabled ? Math.max(0, Number(inputTip) || 0) : 0;

  // Promo code
  let promotionId: string | null = null;
  let promotionDiscountAmount = 0;
  const promoCode = (promotionCode || "").toString().trim().toUpperCase();

  if (promoCode) {
    const { data: promo } = await (supabase.from("promotions") as any)
      .select(
        "id, code, type, value, min_purchase_amount, max_discount_amount, valid_from, valid_until, usage_limit, usage_count, is_active, location_id"
      )
      .eq("code", promoCode)
      .single();

    if (promo) {
      const now = new Date();
      const validFrom = promo.valid_from ? new Date(promo.valid_from) : null;
      const validUntil = promo.valid_until ? new Date(promo.valid_until) : null;
      const withinWindow = (!validFrom || now >= validFrom) && (!validUntil || now <= validUntil);
      const underLimit = promo.usage_limit == null || (promo.usage_count || 0) < promo.usage_limit;
      const meetsMin = !promo.min_purchase_amount || subtotalBeforeDiscount >= Number(promo.min_purchase_amount);
      const locationOk =
        promo.location_id == null || (locationType === "at_salon" && locationId === promo.location_id);

      if (promo.is_active && withinWindow && underLimit && meetsMin && locationOk) {
        if (promo.type === "percentage") {
          promotionDiscountAmount = (subtotalBeforeDiscount * Number(promo.value || 0)) / 100;
        } else {
          promotionDiscountAmount = Number(promo.value || 0);
        }
        if (promo.max_discount_amount) {
          promotionDiscountAmount = Math.min(promotionDiscountAmount, Number(promo.max_discount_amount));
        }
        promotionDiscountAmount = Math.max(0, Math.min(promotionDiscountAmount, subtotalBeforeDiscount));
        promotionId = promo.id;
      }
    }
  }

  const subtotalAfterDiscount = Math.max(0, subtotalBeforeDiscount - promotionDiscountAmount);
  const discountAmount = promotionDiscountAmount;

  // Tax: provider rate or platform default
  const taxRate = await getEffectiveTaxRate(providerId, (provider as any)?.tax_rate_percent ?? null);
  const taxAmount =
    taxRate > 0 ? Number(((subtotalAfterDiscount * taxRate) / 100).toFixed(2)) : 0;

  // Platform service fee: provider fee config or platform settings
  let serviceFeeAmount = 0;
  let serviceFeePercentage = 0;

  if ((provider as any)?.customer_fee_config_id) {
    const { data: feeConfig } = await supabase
      .from("platform_fee_config")
      .select("id, fee_type, fee_percentage, fee_fixed_amount, min_booking_amount, max_fee_amount")
      .eq("id", (provider as any).customer_fee_config_id)
      .eq("is_active", true)
      .single();

    if (feeConfig) {
      const minBookingAmount = Number(feeConfig.min_booking_amount || 0);
      if (subtotalAfterDiscount >= minBookingAmount) {
        if (feeConfig.fee_type === "percentage") {
          serviceFeePercentage = Number(feeConfig.fee_percentage || 0);
          serviceFeeAmount = Number(((subtotalAfterDiscount * serviceFeePercentage) / 100).toFixed(2));
          if (feeConfig.max_fee_amount) {
            serviceFeeAmount = Math.min(serviceFeeAmount, Number(feeConfig.max_fee_amount));
          }
        } else if (feeConfig.fee_type === "fixed_amount") {
          serviceFeeAmount = Number(feeConfig.fee_fixed_amount || 0);
        }
      }
    }
  }

  if (serviceFeeAmount === 0) {
    const { data: platformRow } = await (supabase.from("platform_settings") as any)
      .select("settings")
      .eq("is_active", true)
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    const payoutSettings = (platformRow as any)?.settings?.payouts || {};
    const feeType = payoutSettings.platform_service_fee_type || "percentage";
    const feePct = payoutSettings.platform_service_fee_percentage ?? 0;
    const feeFixed = payoutSettings.platform_service_fee_fixed ?? 0;

    if (feeType === "percentage") {
      serviceFeePercentage = feePct;
      serviceFeeAmount = Number(((subtotalAfterDiscount * serviceFeePercentage) / 100).toFixed(2));
    } else {
      serviceFeeAmount = feeFixed;
    }
  }

  const totalAmount = Number(
    (subtotalAfterDiscount + taxAmount + serviceFeeAmount + tipAmount).toFixed(2)
  );
  const commissionBase = subtotalAfterDiscount;

  return {
    ok: true,
    result: {
      subtotal: Number(offerPrice),
      travelFee: Number(travelFee),
      promotionId,
      promotionDiscountAmount,
      discountAmount,
      taxRate,
      taxAmount,
      serviceFeePercentage,
      serviceFeeAmount,
      tipAmount,
      totalAmount,
      commissionBase,
    },
  };
}

import { NextRequest } from "next/server";
import { z } from "zod";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

const createSchema = z.object({
  provider_id: z.string().uuid(),
  service_category_id: z.string().uuid().nullable().optional(),
  location_type: z.enum(["at_home", "at_salon"]).default("at_salon"),
  description: z.string().min(10).max(4000),
  budget_min: z.number().min(0).nullable().optional(),
  budget_max: z.number().min(0).nullable().optional(),
  preferred_start_at: z.string().nullable().optional(),
  duration_minutes: z.number().int().min(15).max(8 * 60).default(60),
  image_urls: z.array(z.string().url()).max(6).optional().default([]),
}).refine((data) => {
  // Ensure budget_max >= budget_min if both are provided (matches database constraint)
  if (data.budget_min != null && data.budget_max != null) {
    return data.budget_max >= data.budget_min;
  }
  return true;
}, {
  message: "Maximum budget must be greater than or equal to minimum budget",
  path: ["budget_max"],
});

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["customer", "superadmin"], request);
    const supabase = await getSupabaseServer();

    const { data, error } = await supabase
      .from("custom_requests")
      .select(
        `
        *,
        provider:providers(id, business_name, slug, user_id),
        attachments:custom_request_attachments(id, url, created_at),
        offers:custom_offers(id, price, currency, duration_minutes, expiration_at, notes, status, payment_url, payment_reference, paid_at, created_at, staff_id, location_id, scheduled_at, staff:provider_staff(id, name), location:provider_locations(id, name))
      `
      )
      .eq("customer_id", user.id)
      .order("created_at", { ascending: false });
    if (error) throw error;
    return successResponse(data || []);
  } catch (error) {
    return handleApiError(error, "Failed to fetch custom requests");
  }
}

export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["customer", "superadmin"], request);
    const supabase = await getSupabaseServer();

    const body = createSchema.parse(await request.json());

    const preferredIso = body.preferred_start_at ? new Date(body.preferred_start_at).toISOString() : null;
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + 7);

    const { data: created, error: createError } = await supabase
      .from("custom_requests")
      .insert({
        customer_id: user.id,
        provider_id: body.provider_id,
        service_category_id: body.service_category_id ?? null,
        location_type: body.location_type,
        description: body.description,
        budget_min: body.budget_min ?? null,
        budget_max: body.budget_max ?? null,
        preferred_start_at: preferredIso,
        duration_minutes: body.duration_minutes,
        status: "pending",
        expires_at: expiresAt.toISOString(),
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .select()
      .single();
    if (createError) throw createError;

    if (body.image_urls.length > 0) {
      const attachments = body.image_urls.map((url) => ({
        request_id: (created as any).id,
        url,
        created_at: new Date().toISOString(),
      }));
      const { error: attachmentsError } = await supabase
        .from("custom_request_attachments")
        .insert(attachments);
      if (attachmentsError) {
        console.error("Failed to insert attachments:", attachmentsError);
        // Continue even if attachments fail
      }
    }

    // Also send via messages: create/get a customer<->provider conversation and post a message (best-effort)
    try {
      const { data: existingConv } = await supabase
        .from("conversations")
        .select("id")
        .eq("customer_id", user.id)
        .eq("provider_id", body.provider_id)
        .is("booking_id", null)
        .order("created_at", { ascending: true })
        .limit(1)
        .maybeSingle();

      let convId = (existingConv as any)?.id;

      if (!convId) {
        const { data: newConv, error: convError } = await supabase
          .from("conversations")
          .insert({
            booking_id: null,
            customer_id: user.id,
            provider_id: body.provider_id,
            last_message_at: new Date().toISOString(),
            last_message_preview: "",
            last_message_sender_id: user.id,
            unread_count_customer: 0,
            unread_count_provider: 0,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          })
          .select("id")
          .single();

        if (!convError && newConv) {
          convId = (newConv as any)?.id;
        }
      }

      if (convId) {
        const preview = body.description.length > 200 ? body.description.slice(0, 200) + "ΓÇª" : body.description;
        const messageContent = `Custom request: ${preview}`;
        const { error: messageError } = await supabase
          .from("messages")
          .insert({
            conversation_id: convId,
            sender_id: user.id,
            sender_role: "customer",
            content: messageContent,
            attachments: [
              {
                type: "custom_request",
                request_id: (created as any).id,
                provider_id: body.provider_id,
              },
            ],
            is_read: false,
            created_at: new Date().toISOString(),
          });
        if (messageError) {
          console.error("Failed to insert message:", messageError);
          // Continue even if message fails
        } else {
          // Update conversation metadata
          const { data: currentConv } = await supabase
            .from("conversations")
            .select("unread_count_provider")
            .eq("id", convId)
            .single();

          await supabase
            .from("conversations")
            .update({
              last_message_at: new Date().toISOString(),
              last_message_preview: messageContent,
              last_message_sender_id: user.id,
              unread_count_provider: ((currentConv as any)?.unread_count_provider || 0) + 1,
              updated_at: new Date().toISOString(),
            })
            .eq("id", convId);
        }
      }
    } catch {
      // ignore messaging failures
    }

    // Notify provider owner (best-effort)
    try {
      const { data: providerRow } = await supabase
        .from("providers")
        .select("user_id, business_name")
        .eq("id", body.provider_id)
        .single();
      const providerUserId = (providerRow as any)?.user_id;
      if (providerUserId) {
        // Send push notification (try template first, fallback to hardcoded)
        try {
          const { sendToUser, sendTemplateNotification, getNotificationTemplate } = await import("@/lib/notifications/onesignal");

          // Try to use notification template
          const template = await getNotificationTemplate("provider_custom_request");

          if (template && template.enabled) {
            // Use template with variables
            await sendTemplateNotification(
              "provider_custom_request",
              [providerUserId],
              {
                customer_name: user.full_name || user.email || "A customer",
                description_preview: body.description.slice(0, 50) + "...",
                request_id: (created as any).id,
                provider_id: body.provider_id,
              },
              template.channels || ["push"]
            );
          } else {
            // Fallback to direct notification
            await sendToUser(providerUserId, {
              title: "New Custom Request",
              message: `A customer sent you a custom service request: ${body.description.slice(0, 50)}...`,
              data: { type: "custom_request", request_id: (created as any).id, provider_id: body.provider_id },
              url: `/provider/custom-requests?request_id=${(created as any).id}`,
            });
          }
        } catch (notifError) {
          console.error("Failed to send push notification:", notifError);
        }

        // Also create an in-app notification record (if notifications table exists)
        try {
          const { data: notificationExists } = await supabase
            .from("notifications")
            .select("id")
            .limit(1)
            .maybeSingle();

          if (notificationExists !== null) {
            // Use template content if available, otherwise use fallback
            let notificationTitle = "New Custom Request";
            let notificationMessage = `A customer sent you a custom service request.`;

            // Get template again for in-app notification
            const { getNotificationTemplate: getNotificationTemplate2 } = await import("@/lib/notifications/onesignal");
            const inAppTemplate = await getNotificationTemplate2("provider_custom_request");

            if (inAppTemplate && inAppTemplate.enabled) {
              // Replace template variables for in-app notification
              notificationTitle = inAppTemplate.title
                .replace(/\{\{customer_name\}\}/g, user.full_name || user.email || "A customer")
                .replace(/\{\{description_preview\}\}/g, body.description.slice(0, 50) + "...");
              notificationMessage = inAppTemplate.body
                .replace(/\{\{customer_name\}\}/g, user.full_name || user.email || "A customer")
                .replace(/\{\{description_preview\}\}/g, body.description.slice(0, 50) + "...");
            }

            // Notifications table exists, create a record
            await supabase
              .from("notifications")
              .insert({
                user_id: providerUserId,
                type: "custom_request",
                title: notificationTitle,
                message: notificationMessage,
                data: { request_id: (created as any).id, provider_id: body.provider_id },
                is_read: false,
                created_at: new Date().toISOString(),
              });
          }
        } catch (notifError) {
          // Notifications table might not exist, ignore
          console.debug("Notifications table not available:", notifError);
        }
      }
    } catch (error) {
      console.error("Failed to notify provider:", error);
      // Continue even if notification fails
    }

    return successResponse(created);
  } catch (error) {
    return handleApiError(error, "Failed to create custom request");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRole } from "@/lib/supabase/auth-server";

export async function GET(_request: NextRequest) {
  try {
    const supabase = await getSupabaseServer();
    const supabaseAdmin = getSupabaseAdmin();
    const { user } = await requireRole(["customer", "provider_owner", "provider_staff"]);

    const giftCardIds = new Set<string>();

    // 1) Gift cards from orders purchased by this user
    const { data: orders } = await supabase
      .from("gift_card_orders")
      .select("gift_card_id")
      .eq("purchaser_user_id", user.id)
      .eq("status", "paid")
      .not("gift_card_id", "is", null);

    for (const o of orders || []) {
      if (o.gift_card_id) giftCardIds.add(o.gift_card_id);
    }

    // 2) Gift cards from redemptions (used by this user at checkout)
    const { data: redemptions } = await supabase
      .from("gift_card_redemptions")
      .select("gift_card_id")
      .eq("user_id", user.id);

    for (const r of redemptions || []) {
      if (r.gift_card_id) giftCardIds.add(r.gift_card_id);
    }

    // 3) Admin-created gift cards assigned to this user's email (metadata.recipient_email)
    if (user.email) {
      const { data: allActive } = await supabaseAdmin
        .from("gift_cards")
        .select("id, metadata")
        .eq("is_active", true)
        .or(`expires_at.is.null,expires_at.gt.${new Date().toISOString()}`);

      const emailLower = user.email.trim().toLowerCase();
      for (const c of allActive || []) {
        const recipient = (c.metadata as Record<string, any>)?.recipient_email;
        if (typeof recipient === "string" && recipient.toLowerCase() === emailLower) {
          giftCardIds.add(c.id);
        }
      }
    }

    if (giftCardIds.size === 0) {
      return NextResponse.json({ gift_cards: [] });
    }

    const ids = Array.from(giftCardIds);
    const { data: giftCards, error } = await supabase
      .from("gift_cards")
      .select("*")
      .in("id", ids)
      .order("created_at", { ascending: false });

    if (error) throw error;

    return NextResponse.json({
      gift_cards: giftCards || [],
    });
  } catch (error: any) {
    console.error("Error fetching user gift cards:", error);
    return NextResponse.json(
      { error: error.message || "Failed to fetch gift cards" },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { successResponse, handleApiError, requireAuthInApi } from "@/lib/supabase/api-helpers";
import { rescheduleGroupBooking, isPrimaryContact, getGroupBooking } from "@/lib/bookings/group-booking";
import { loadAvailabilityConstraints } from "@/lib/availability/load-constraints";
import { calculateAvailableSlots } from "@/lib/availability/calculate-slots";
import { z } from "zod";

const rescheduleSchema = z.object({
  new_datetime: z.string().datetime("Invalid datetime format"),
});

/**
 * POST /api/me/group-bookings/[id]/reschedule
 * 
 * Reschedule an entire group booking (only primary contact can do this)
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireAuthInApi(request);
    const { id: groupBookingId } = await params;
    const body = await request.json();

    // Validate input
    const validated = rescheduleSchema.parse(body);
    const newDatetime = new Date(validated.new_datetime);

    const supabase = await getSupabaseServer();
    const adminSupabase = getSupabaseAdmin();

    // Load group booking
    const groupBooking = await getGroupBooking(supabase, groupBookingId);
    if (!groupBooking) {
      return handleApiError(
        new Error("Group booking not found"),
        "Group booking not found",
        "NOT_FOUND",
        404
      );
    }

    // Verify user is primary contact
    const isPrimary = await isPrimaryContact(supabase, user.id, groupBookingId);
    if (!isPrimary) {
      return handleApiError(
        new Error("Unauthorized"),
        "Only the primary contact can reschedule group bookings",
        "UNAUTHORIZED",
        403
      );
    }

    // Check availability for all bookings in the group
    // For simplicity, we'll check if the new time works for all bookings
    // In a more sophisticated implementation, we'd check each booking's staff availability
    const bookings = groupBooking.bookings || [];

    // Calculate time offset
    const originalScheduledAt = new Date(groupBooking.scheduled_at);
    const _timeOffset = newDatetime.getTime() - originalScheduledAt.getTime();

    // Check availability for each booking (simplified - checks first booking's staff)
    if (bookings.length > 0) {
      const firstBooking = bookings[0];
      // Get staff from first booking service
      const { data: firstService } = await supabase
        .from('booking_services')
        .select('staff_id, duration_minutes')
        .eq('booking_id', firstBooking.id)
        .limit(1)
        .single();

      if (firstService?.staff_id) {
        const newDate = newDatetime.toISOString().split('T')[0];
        const constraints = await loadAvailabilityConstraints(supabase, firstService.staff_id, newDate);

        // Total blocked span = sum(durations) + sum(buffers) across all group booking services
        let totalDuration = 0;
        for (const booking of bookings) {
          const { data: services } = await supabase
            .from('booking_services')
            .select('duration_minutes, offerings(buffer_minutes)')
            .eq('booking_id', booking.id);
          services?.forEach((s: any) => {
            const dur = s.duration_minutes ?? 60;
            const buf = s.offerings?.buffer_minutes ?? 15;
            totalDuration += dur + buf;
          });
        }

        const slots = calculateAvailableSlots(
          constraints,
          totalDuration,
          newDate,
          {
            slotInterval: 15,
            travelBuffer: 0, // Could be enhanced for at-home bookings
          }
        );

        const requestedTime = newDatetime.toTimeString().substring(0, 5); // HH:MM
        const isAvailable = slots.some((slot) => slot.time === requestedTime && slot.available);

        if (!isAvailable) {
          return handleApiError(
            new Error("Selected time slot is not available for all bookings"),
            "Selected time slot is not available. Please choose another time.",
            "SLOT_UNAVAILABLE",
            409
          );
        }
      }
    }

    // Reschedule the group booking
    await rescheduleGroupBooking(adminSupabase, groupBookingId, newDatetime);

    // Create booking events for all bookings
    for (const booking of bookings) {
      await adminSupabase.from('booking_events').insert({
        booking_id: booking.id,
        event_type: 'rescheduled',
        event_data: {
          old_datetime: groupBooking.scheduled_at,
          new_datetime: newDatetime.toISOString(),
          rescheduled_by: user.id,
          group_booking_id: groupBookingId,
        },
        created_by: user.id,
      });
    }

    // Send reschedule notifications
    const { sendRescheduleNotification } = await import('@/lib/bookings/notifications');
    for (const booking of bookings) {
      await sendRescheduleNotification(
        booking.id,
        originalScheduledAt,
        newDatetime
      );
    }

    return successResponse({
      message: "Group booking rescheduled successfully",
      group_booking_id: groupBookingId,
      new_scheduled_at: newDatetime.toISOString(),
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        new Error(error.issues.map(e => e.message).join(", ")),
        "Validation failed",
        "VALIDATION_ERROR",
        400
      );
    }
    return handleApiError(error, "Failed to reschedule group booking");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/me/loyalty
 * 
 * Get current user's loyalty points, balance, and milestones
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);

    // Get user's loyalty points balance using the function
    let pointsBalance = 0;
    let pointsHistory: any[] = [];

    try {
      // Use the get_user_loyalty_balance function
      const { data: balanceData, error: balanceError } = await supabase
        .rpc("get_user_loyalty_balance", { p_user_id: user.id });

      if (balanceError) {
        console.warn("Error calling get_user_loyalty_balance:", balanceError);
        // Fallback: calculate manually
        const { data: transactions } = await supabase
          .from("loyalty_point_transactions")
          .select("points, transaction_type, expires_at")
          .eq("user_id", user.id);
        
        if (transactions) {
          pointsBalance = transactions.reduce((sum, t) => {
            const isExpired = t.expires_at && new Date(t.expires_at) < new Date();
            if (isExpired) return sum;
            
            if (t.transaction_type === "earned" || t.transaction_type === "adjusted") {
              return sum + Number(t.points || 0);
            } else if (t.transaction_type === "redeemed" || t.transaction_type === "expired") {
              return sum - Number(t.points || 0);
            }
            return sum;
          }, 0);
          pointsBalance = Math.max(pointsBalance, 0);
        }
      } else if (balanceData !== null) {
        pointsBalance = Number(balanceData) || 0;
      }

      // Get points history/transactions
      const { data: history, error: historyError } = await supabase
        .from("loyalty_point_transactions")
        .select("id, points, transaction_type, description, created_at")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .limit(50);

      if (!historyError && history) {
        pointsHistory = history;
      }
    } catch {
      // Tables might not exist, use defaults
      console.warn("Loyalty points tables not found, using default balance");
    }

    // Get active loyalty rule to calculate redemption value
    let redemptionRate = 100; // Default: 100 points = 1 currency unit
    let currency = "ZAR";
    let pointsPerCurrency = 1;

    try {
      const { data: activeRule, error: ruleError } = await supabase
        .from("loyalty_rules")
        .select("points_per_currency_unit, currency, redemption_rate")
        .eq("is_active", true)
        .order("effective_from", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (!ruleError && activeRule) {
        redemptionRate = Number(activeRule.redemption_rate) || 100;
        currency = activeRule.currency || "ZAR";
        pointsPerCurrency = Number(activeRule.points_per_currency_unit) || 1;
      }
    } catch {
      console.warn("loyalty_rules table not found, using defaults");
    }

    // Get available milestones
    let milestones: any[] = [];
    let nextMilestone: any = null;

    try {
      const { data: allMilestones, error: milestonesError } = await supabase
        .from("loyalty_milestones")
        .select("id, name, description, points_threshold, reward_type, reward_amount, reward_currency")
        .eq("is_active", true)
        .order("points_threshold", { ascending: true });

      if (!milestonesError && allMilestones) {
        milestones = allMilestones;
        // Find next milestone user hasn't reached
        nextMilestone = allMilestones.find((m) => m.points_threshold > pointsBalance) || null;
      }
    } catch {
      console.warn("loyalty_milestones table not found");
    }

    // Calculate redemption value
    const redemptionValue = pointsBalance / redemptionRate;

    return successResponse({
      points_balance: pointsBalance,
      redemption_value: redemptionValue,
      redemption_currency: currency,
      redemption_rate: redemptionRate,
      points_per_currency_unit: pointsPerCurrency,
      next_milestone: nextMilestone,
      available_milestones: milestones,
      history: pointsHistory,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch loyalty points");
  }
}

import { NextRequest } from "next/server";
import { z } from "zod";
import { getSupabaseServer } from "@/lib/supabase/server";
import { handleApiError, successResponse, errorResponse } from "@/lib/supabase/api-helpers";
import { convertToSmallestUnit, generateTransactionReference } from "@/lib/payments/paystack";
import { initializePaystackTransaction } from "@/lib/payments/paystack-server";

const schema = z.object({
  plan_id: z.string().uuid(),
});

/**
 * POST /api/me/memberships/purchase
 * Body: { plan_id }
 */
export async function POST(request: NextRequest) {
  try {
    const supabase = await getSupabaseServer();
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) return errorResponse("Authentication required", "AUTH_REQUIRED", 401);

    const body = await request.json();
    const parsed = schema.safeParse(body);
    if (!parsed.success) return errorResponse("Validation failed", "VALIDATION_ERROR", 400, parsed.error.issues);

    const { data: plan, error: planError } = await (supabase.from("membership_plans") as any)
      .select("*")
      .eq("id", parsed.data.plan_id)
      .eq("is_active", true)
      .single();

    if (planError || !plan) return errorResponse("Membership plan not found", "NOT_FOUND", 404);

    const planData = plan as any;
    const amount = Number(planData.price_monthly || 0);
    const currency = planData.currency || "ZAR";

    const { data: order, error: orderError } = await (supabase.from("membership_orders") as any)
      .insert({
        user_id: user.id,
        provider_id: planData.provider_id,
        plan_id: planData.id,
        amount,
        currency,
        status: "pending",
      })
      .select("*")
      .single();

    if (orderError || !order) throw orderError || new Error("Failed to create membership order");

    const reference = generateTransactionReference("membership", order.id);
    const callbackUrl = `${process.env.NEXT_PUBLIC_APP_URL || ""}/checkout/success`;

    const paystackData = await initializePaystackTransaction({
      email: user.email!,
      amountInSmallestUnit: convertToSmallestUnit(amount),
      currency,
      reference,
      callback_url: callbackUrl,
      metadata: {
        membership_order_id: order.id,
        user_id: user.id,
        provider_id: planData.provider_id,
        plan_id: planData.id,
      },
    });

    const paymentUrl = paystackData?.data?.authorization_url || null;
    await (supabase.from("membership_orders") as any)
      .update({ paystack_reference: reference })
      .eq("id", order.id);

    return successResponse({ order_id: order.id, reference, payment_url: paymentUrl });
  } catch (error) {
    return handleApiError(error, "Failed to initialize membership purchase");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRoleInApi, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";

/**
 * Verify the caller has access to a conversation. Returns the role ("customer" | "provider").
 * Throws if access is denied.
 */
async function verifyConversationAccess(
  supabase: Awaited<ReturnType<typeof getSupabaseServer>>,
  conversationId: string,
  userId: string
): Promise<{ conv: any; role: "customer" | "provider" }> {
  const { data: conv } = await supabase
    .from("conversations")
    .select("id, customer_id, provider_id")
    .eq("id", conversationId)
    .single();

  if (!conv) throw Object.assign(new Error("Conversation not found"), { status: 404 });

  if (conv.customer_id === userId) return { conv, role: "customer" };

  const { data: providerRow } = await supabase
    .from("providers")
    .select("id, user_id")
    .eq("id", conv.provider_id)
    .single();

  if (providerRow && (providerRow as any).user_id === userId) {
    return { conv, role: "provider" };
  }

  const { data: staff } = await supabase
    .from("provider_staff")
    .select("id")
    .eq("provider_id", conv.provider_id)
    .eq("user_id", userId)
    .maybeSingle();

  if (staff) return { conv, role: "provider" };

  throw Object.assign(new Error("Not authorized"), { status: 403 });
}

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(
      ["customer", "provider_owner", "provider_staff", "superadmin"],
      request
    );
    const supabase = await getSupabaseServer(request);

    const conversationId = request.nextUrl.searchParams.get("conversation_id");
    if (!conversationId) {
      return errorResponse("conversation_id is required", "VALIDATION_ERROR", 400);
    }

    const cursor = request.nextUrl.searchParams.get("cursor");
    const limitParam = request.nextUrl.searchParams.get("limit");
    const limit = Math.min(Math.max(parseInt(limitParam || "50", 10), 1), 100);

    const { conv: _conv, role } = await verifyConversationAccess(supabase, conversationId, user.id);

    let query = supabase
      .from("messages")
      .select(
        `id, conversation_id, sender_id, sender_role, content, attachments, is_read, read_at, created_at,
         sender:users!messages_sender_id_fkey(id, full_name, avatar_url)`
      )
      .eq("conversation_id", conversationId)
      .order("created_at", { ascending: false })
      .limit(limit + 1);

    if (cursor) {
      query = query.lt("created_at", cursor);
    }

    const { data: rawMessages, error } = await query;
    if (error) throw error;

    const items = rawMessages || [];
    const hasMore = items.length > limit;
    const slice = hasMore ? items.slice(0, limit) : items;

    const messages = slice.reverse();
    const nextCursor = hasMore ? slice[0]?.created_at : undefined;

    const transformed = messages.map((m: any) => ({
      id: m.id,
      conversation_id: m.conversation_id,
      sender_id: m.sender_id,
      sender_name: m.sender?.full_name || "User",
      sender_role: m.sender_role,
      content: m.content,
      attachments: m.attachments || [],
      created_at: m.created_at,
      read_at: m.read_at,
    }));

    // Fire-and-forget: mark unread messages as read so sender sees read receipt (use admin to bypass RLS)
    markAsRead(conversationId, user.id, role).catch(() => {});

    return successResponse({
      messages: transformed,
      next_cursor: nextCursor,
      has_more: hasMore,
    });
  } catch (error: any) {
    if (error?.status === 404) return errorResponse("Conversation not found", "NOT_FOUND", 404);
    if (error?.status === 403) return errorResponse("Not authorized", "FORBIDDEN", 403);
    return handleApiError(error, "Failed to fetch messages");
  }
}

async function markAsRead(
  conversationId: string,
  userId: string,
  role: "customer" | "provider"
) {
  const admin = await getSupabaseAdmin();
  const now = new Date().toISOString();
  await Promise.all([
    admin
      .from("messages")
      .update({ is_read: true, read_at: now })
      .eq("conversation_id", conversationId)
      .eq("is_read", false)
      .neq("sender_id", userId),
    role === "customer"
      ? admin.from("conversations").update({ unread_count_customer: 0 }).eq("id", conversationId)
      : admin.from("conversations").update({ unread_count_provider: 0 }).eq("id", conversationId),
  ]);
}

export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(
      ["customer", "provider_owner", "provider_staff", "superadmin"],
      request
    );
    const supabase = await getSupabaseServer(request);

    const body = await request.json();
    const { conversation_id, content, attachments } = body;

    if (!conversation_id) return errorResponse("conversation_id is required", "VALIDATION_ERROR", 400);
    if (!content && (!attachments || attachments.length === 0)) {
      return errorResponse("Message content or attachments are required", "VALIDATION_ERROR", 400);
    }

    const { conv, role } = await verifyConversationAccess(supabase, conversation_id, user.id);
    const isCustomer = role === "customer";

    const { data: msg, error } = await (supabase.from("messages") as any)
      .insert({
        conversation_id,
        sender_id: user.id,
        sender_role: user.role,
        content: content ? String(content) : "",
        attachments: attachments || [],
        is_read: false,
        created_at: new Date().toISOString(),
      })
      .select()
      .single();
    if (error) throw error;

    const messagePreview = content
      ? content.length > 80 ? content.slice(0, 80) + "..." : content
      : attachments?.length ? "Sent an attachment" : "";

    // Fire-and-forget: update conversation metadata + send notifications
    updateConversationMeta(supabase, conversation_id, user.id, messagePreview, isCustomer).catch(() => {});
    sendMessageNotification(supabase, conv, user, msg.id, messagePreview, isCustomer).catch((e) =>
      console.error("Notification error:", e)
    );

    return successResponse({
      id: msg.id,
      conversation_id,
      sender_id: msg.sender_id,
      sender_role: msg.sender_role,
      content: msg.content,
      created_at: msg.created_at,
    });
  } catch (error: any) {
    if (error?.status === 404) return errorResponse("Conversation not found", "NOT_FOUND", 404);
    if (error?.status === 403) return errorResponse("Not authorized", "FORBIDDEN", 403);
    return handleApiError(error, "Failed to send message");
  }
}

async function updateConversationMeta(
  supabase: Awaited<ReturnType<typeof getSupabaseServer>>,
  conversationId: string,
  senderId: string,
  preview: string,
  isCustomer: boolean
) {
  const updatePayload: Record<string, any> = {
    last_message_at: new Date().toISOString(),
    last_message_preview: preview,
    last_message_sender_id: senderId,
  };
  if (isCustomer) {
    updatePayload.unread_count_provider = (await supabase
      .from("conversations")
      .select("unread_count_provider")
      .eq("id", conversationId)
      .single()
      .then(r => ((r.data as any)?.unread_count_provider ?? 0) + 1));
  } else {
    updatePayload.unread_count_customer = (await supabase
      .from("conversations")
      .select("unread_count_customer")
      .eq("id", conversationId)
      .single()
      .then(r => ((r.data as any)?.unread_count_customer ?? 0) + 1));
  }
  await supabase.from("conversations").update(updatePayload).eq("id", conversationId);
}

async function sendMessageNotification(
  supabase: Awaited<ReturnType<typeof getSupabaseServer>>,
  conv: any,
  user: any,
  messageId: string,
  messagePreview: string,
  isCustomer: boolean
) {
  let recipientUserId: string | null = null;

  if (isCustomer) {
    const { data: providerRow } = await supabase
      .from("providers")
      .select("user_id")
      .eq("id", conv.provider_id)
      .single();
    if (providerRow) recipientUserId = (providerRow as any).user_id;
  } else {
    recipientUserId = conv.customer_id;
  }

  if (!recipientUserId || recipientUserId === user.id) return;

  try {
    const { sendToUser, sendTemplateNotification, getNotificationTemplate } = await import("@/lib/notifications/onesignal");
    const templateKey = isCustomer ? "provider_new_message" : "customer_new_message";
    const template = await getNotificationTemplate(templateKey);

    if (template?.enabled) {
      await sendTemplateNotification(
        templateKey,
        [recipientUserId],
        {
          sender_name: user.full_name || user.email || "Someone",
          message_preview: messagePreview,
          conversation_id: conv.id,
        },
        template.channels || ["push"]
      );
    } else {
      await sendToUser(recipientUserId, {
        title: isCustomer ? "New Message from Customer" : "New Message from Provider",
        message: messagePreview,
        data: { type: "new_message", conversation_id: conv.id, message_id: messageId },
        url: isCustomer ? `/provider/messaging` : `/account-settings/messages?conversation=${conv.id}`,
      });
    }
  } catch {}

  try {
    await supabase.from("notifications").insert({
      user_id: recipientUserId,
      type: "new_message",
      title: isCustomer ? "New message" : "New message from provider",
      message: messagePreview,
      data: { conversation_id: conv.id, message_id: messageId },
      is_read: false,
      created_at: new Date().toISOString(),
    });
  } catch {}
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";

/**
 * POST /api/me/messages/upload
 * 
 * Uploads attachments (images, videos, documents) for messages to Supabase Storage.
 * Returns the public URLs that can be used in the message.
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer();

    const formData = await request.formData();
    const files = formData.getAll("files") as File[];
    const conversationId = formData.get("conversation_id") as string;

    if (!files || files.length === 0) {
      return errorResponse("No files provided", "VALIDATION_ERROR", 400);
    }

    if (!conversationId) {
      return errorResponse("conversation_id is required", "VALIDATION_ERROR", 400);
    }

    // Verify access to conversation
    const { data: conv } = await supabase
      .from("conversations")
      .select("id, customer_id, provider_id")
      .eq("id", conversationId)
      .single();
    
    if (!conv) {
      return errorResponse("Conversation not found", "NOT_FOUND", 404);
    }

    const isCustomer = conv.customer_id === user.id;
    let isProvider = false;
    if (!isCustomer) {
      const { data: providerRow } = await supabase.from("providers").select("id, user_id").eq("id", conv.provider_id).single();
      if (providerRow && (providerRow as any).user_id === user.id) isProvider = true;
      if (!isProvider) {
        const { data: staff } = await supabase
          .from("provider_staff")
          .select("id")
          .eq("provider_id", conv.provider_id)
          .eq("user_id", user.id)
          .maybeSingle();
        isProvider = Boolean(staff);
      }
    }

    if (!isCustomer && !isProvider) {
      return errorResponse("Not authorized to upload files to this conversation", "FORBIDDEN", 403);
    }

    if (files.length > 10) {
      return errorResponse("Maximum 10 files allowed per message", "VALIDATION_ERROR", 400);
    }

    // Validate file types and sizes
    const allowedImageTypes = ["image/jpeg", "image/jpg", "image/png", "image/webp", "image/gif"];
    const allowedVideoTypes = ["video/mp4", "video/webm", "video/quicktime", "video/x-msvideo"];
    const allowedDocTypes = ["application/pdf", "application/msword", "application/vnd.openxmlformats-officedocument.wordprocessingml.document"];
    const allowedTypes = [...allowedImageTypes, ...allowedVideoTypes, ...allowedDocTypes];
    
    const maxImageSize = 10 * 1024 * 1024; // 10MB for images
    const maxVideoSize = 50 * 1024 * 1024; // 50MB for videos
    const maxDocSize = 10 * 1024 * 1024; // 10MB for documents

    for (const file of files) {
      if (!allowedTypes.includes(file.type)) {
        return errorResponse(
          `Invalid file type: ${file.name}. Allowed types: Images (JPEG, PNG, WebP, GIF), Videos (MP4, WebM, MOV, AVI), Documents (PDF, DOC, DOCX)`,
          "VALIDATION_ERROR",
          400
        );
      }
      
      let maxSize = maxDocSize;
      if (allowedImageTypes.includes(file.type)) {
        maxSize = maxImageSize;
      } else if (allowedVideoTypes.includes(file.type)) {
        maxSize = maxVideoSize;
      }
      
      if (file.size > maxSize) {
        const sizeMB = Math.round(maxSize / (1024 * 1024));
        return errorResponse(
          `File too large: ${file.name}. Maximum size is ${sizeMB}MB`,
          "VALIDATION_ERROR",
          400
        );
      }
    }

    // Check if storage bucket exists
    const { data: buckets } = await supabase.storage.listBuckets();
    const bucketName = "message-attachments";
    const bucketExists = buckets?.some((b) => b.name === bucketName);

    if (!bucketExists) {
      // Try to create the bucket (requires admin privileges)
      const { error: createError } = await supabase.storage.createBucket(bucketName, {
        public: true,
        fileSizeLimit: 52428800, // 50MB
        allowedMimeTypes: allowedTypes,
      });

      if (createError) {
        console.error("Failed to create bucket:", createError);
        throw new Error(
          'Storage bucket "message-attachments" not found. Please create it in Supabase Dashboard > Storage.'
        );
      }
    }

    // Use service role client for storage operations (bypasses RLS)
    const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
    
    let storageClient = supabase;
    if (serviceRoleKey && supabaseUrl) {
      storageClient = createClient(supabaseUrl, serviceRoleKey, {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      });
    }

    // Upload files to Supabase Storage
    // Storage path: message-attachments/{conversation_id}/{user_id}/{timestamp}-{index}-{random}.{ext}
    const uploadedAttachments: Array<{ url: string; type: string; name: string; size: number }> = [];
    const timestamp = Date.now();
    const userId = user.id;

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const fileExt = file.name.split(".").pop() || "jpg";
      const fileName = `${conversationId}/${userId}/${timestamp}-${i}-${Math.random().toString(36).substring(7)}.${fileExt}`;

      // Convert File to ArrayBuffer then Buffer
      const arrayBuffer = await file.arrayBuffer();
      const buffer = Buffer.from(arrayBuffer);

      // Upload to Supabase Storage
      const { data: _uploadData, error: uploadError } = await storageClient.storage
        .from(bucketName)
        .upload(fileName, buffer, {
          contentType: file.type,
          cacheControl: "3600",
          upsert: false,
        });

      if (uploadError) {
        console.error(`Failed to upload file ${file.name}:`, uploadError);
        continue;
      }

      // Get public URL
      const {
        data: { publicUrl },
      } = storageClient.storage.from(bucketName).getPublicUrl(fileName);

      if (publicUrl) {
        uploadedAttachments.push({
          url: publicUrl,
          type: file.type,
          name: file.name,
          size: file.size,
        });
      }
    }

    if (uploadedAttachments.length === 0) {
      return errorResponse("Failed to upload any files", "UPLOAD_ERROR", 500);
    }

    return successResponse({
      attachments: uploadedAttachments,
      count: uploadedAttachments.length,
    });
  } catch (error) {
    return handleApiError(error, "Failed to upload files");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/me/notification-preferences
 * 
 * Get current user's notification preferences
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer();

    // Get notification preferences from user_profiles
    let profileData: any = null;
    let preferences: any = null;

    try {
      const { data, error } = await supabase
        .from("user_profiles")
        .select("notification_preferences")
        .eq("user_id", user.id)
        .maybeSingle();

      if (error && error.code !== 'PGRST116') {
        // If column doesn't exist, return default preferences instead of throwing
        if (error.code === '42703' || error.message?.includes('column') || error.message?.includes('does not exist')) {
          console.warn('Notification preferences column may not exist in user_profiles table:', error.message);
          profileData = null;
        } else {
          throw error;
        }
      } else {
        profileData = data;
      }
    } catch (err: any) {
      // Handle column not found errors gracefully
      if (err.code === '42703' || err.message?.includes('column') || err.message?.includes('does not exist')) {
        console.warn('Notification preferences column may not exist in user_profiles table:', err.message);
        profileData = null;
      } else {
        throw err;
      }
    }

    // Default notification preferences
    const defaultPreferences = {
      inspiration_and_offers: { email: true, sms: true, push: false },
      news_and_programs: { email: true, sms: true, push: false },
      feedback: { email: true, sms: false, push: false },
      travel_regulations: { email: true, sms: true, push: false },
      account_activity: { email: true, sms: true, push: false },
      client_policies: { email: true, sms: false, push: false },
      reminders: { email: true, sms: true, push: false },
      subscription_renewal: { email: true, sms: false, push: false },
      messages: { email: true, sms: true, push: true },
      unsubscribe_marketing: false,
    };

    preferences = profileData?.notification_preferences || defaultPreferences;

    return successResponse(preferences);
  } catch (error) {
    return handleApiError(error, "Failed to fetch notification preferences");
  }
}

/**
 * PATCH /api/me/notification-preferences
 * 
 * Update current user's notification preferences
 */
export async function PATCH(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer();
    const body = await request.json();

    // Get existing preferences
    let existingProfile: any = null;
    try {
      const { data, error } = await supabase
        .from("user_profiles")
        .select("notification_preferences")
        .eq("user_id", user.id)
        .maybeSingle();

      if (error && error.code !== 'PGRST116') {
        // If column doesn't exist, use defaults
        if (error.code === '42703' || error.message?.includes('column') || error.message?.includes('does not exist')) {
          console.warn('Notification preferences column may not exist:', error.message);
          existingProfile = null;
        } else {
          throw error;
        }
      } else {
        existingProfile = data;
      }
    } catch (err: any) {
      // Handle column not found errors gracefully
      if (err.code === '42703' || err.message?.includes('column') || err.message?.includes('does not exist')) {
        console.warn('Notification preferences column may not exist:', err.message);
        existingProfile = null;
      } else {
        throw err;
      }
    }

    const defaultPreferences = {
      inspiration_and_offers: { email: true, sms: true, push: false },
      news_and_programs: { email: true, sms: true, push: false },
      feedback: { email: true, sms: false, push: false },
      travel_regulations: { email: true, sms: true, push: false },
      account_activity: { email: true, sms: true, push: false },
      client_policies: { email: true, sms: false, push: false },
      reminders: { email: true, sms: true, push: false },
      subscription_renewal: { email: true, sms: false, push: false },
      messages: { email: true, sms: true, push: true },
      unsubscribe_marketing: false,
    };

    const currentPreferences = existingProfile?.notification_preferences || defaultPreferences;
    
    // Merge with new preferences (deep merge for nested objects)
    const updatedPreferences: any = { ...currentPreferences };
    
    for (const [key, value] of Object.entries(body)) {
      if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        updatedPreferences[key] = { ...updatedPreferences[key], ...value };
      } else {
        updatedPreferences[key] = value;
      }
    }

    // Update or insert
    let profileData: any = null;
    try {
      const { data, error: checkError } = await supabase
        .from("user_profiles")
        .select("id")
        .eq("user_id", user.id)
        .maybeSingle();

      if (checkError && checkError.code !== 'PGRST116') {
        // If table doesn't exist or other critical error, throw
        // But allow PGRST116 (no rows found) to continue
        throw checkError;
      }
      profileData = data;
    } catch (err: any) {
      // Only throw if it's not a "no rows found" error
      if (err.code !== 'PGRST116') {
        throw err;
      }
    }

    let result;
    try {
      if (profileData) {
        const { data, error } = await supabase
          .from("user_profiles")
          .update({ notification_preferences: updatedPreferences })
          .eq("user_id", user.id)
          .select("notification_preferences")
          .single();

        if (error) {
          // If column doesn't exist, provide helpful error
          if (error.code === '42703' || error.message?.includes('column') || error.message?.includes('does not exist')) {
            throw new Error('Notification preferences column not found. Please run database migration 105_add_tax_info_to_user_profiles.sql');
          }
          throw error;
        }
        result = data?.notification_preferences || {};
      } else {
        const { data, error } = await supabase
          .from("user_profiles")
          .insert({
            user_id: user.id,
            notification_preferences: updatedPreferences,
          })
          .select("notification_preferences")
          .single();

        if (error) {
          // If column doesn't exist, provide helpful error
          if (error.code === '42703' || error.message?.includes('column') || error.message?.includes('does not exist')) {
            throw new Error('Notification preferences column not found. Please run database migration 105_add_tax_info_to_user_profiles.sql');
          }
          throw error;
        }
        result = data?.notification_preferences || {};
      }
    } catch (err: any) {
      // Provide helpful error message for missing columns
      if (err.code === '42703' || err.message?.includes('column') || err.message?.includes('does not exist')) {
        throw new Error('Notification preferences column not found. Please run database migration 105_add_tax_info_to_user_profiles.sql');
      }
      throw err;
    }

    return successResponse(result);
  } catch (error) {
    return handleApiError(error, "Failed to update notification preferences");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/me/notifications
 *
 * Get customer's notifications
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer();

    const { searchParams } = new URL(request.url);
    const limit = parseInt(searchParams.get("limit") || "20");
    const unreadOnly = searchParams.get("unread_only") === "true";

    let query = supabase
      .from("notifications")
      .select("*")
      .eq("user_id", user.id)
      .order("created_at", { ascending: false })
      .limit(limit);

    if (unreadOnly) {
      query = query.eq("is_read", false);
    }

    const { data: notifications, error } = await query;

    if (error) {
      throw error;
    }

    // Get unread count
    const { count: unreadCount } = await supabase
      .from("notifications")
      .select("*", { count: "exact", head: true })
      .eq("user_id", user.id)
      .eq("is_read", false);
    
    // Transform notifications to match frontend expectations
    const transformedNotifications = (notifications || []).map((n: any) => ({
      ...n,
      read: n.is_read,
      timestamp: n.created_at,
    }));

    return successResponse({
      notifications: transformedNotifications,
      total_unread: unreadCount || 0,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch notifications");
  }
}

