import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  errorResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";
import { isFeatureEnabledServer } from "@/lib/server/feature-flags";
import { z } from "zod";

const createOrderSchema = z.object({
  provider_id: z.string().uuid(),
  fulfillment_type: z.enum(["collection", "delivery"]),
  delivery_address_id: z.string().uuid().optional(),
  delivery_instructions: z.string().max(500).optional(),
  collection_location_id: z.string().uuid().optional(),
  payment_method: z.enum(["paystack", "cash", "yoco", "card_on_delivery", "wallet"]).optional(),
  use_wallet: z.boolean().optional(),
});

/**
 * GET /api/me/orders
 * List customer's product orders
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(
      ["customer", "provider_owner", "provider_staff", "superadmin"],
      request,
    );
    const supabase = await getSupabaseServer();

    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "20");
    const status = searchParams.get("status");
    const offset = (page - 1) * limit;

    let query = (supabase.from("product_orders") as any)
      .select(
        `
        *,
        items:product_order_items (
          id, product_name, product_image_url, quantity, unit_price, total_price
        ),
        provider:providers (
          id, business_name, slug
        )
      `,
        { count: "exact" },
      )
      .eq("customer_id", user.id)
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (status) {
      query = query.eq("status", status);
    }

    const { data: orders, error, count } = await query;
    if (error) throw error;

    return successResponse({
      orders: orders ?? [],
      pagination: {
        page,
        limit,
        total: count ?? 0,
        totalPages: Math.ceil((count ?? 0) / limit),
      },
    });
  } catch (err) {
    return handleApiError(err, "Failed to fetch orders");
  }
}

/**
 * POST /api/me/orders
 * Create a new product order from cart items for a specific provider.
 * Validates stock, decrements inventory, calculates totals.
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(
      ["customer", "provider_owner", "provider_staff", "superadmin"],
      request,
    );
    const body = await request.json();
    const parsed = createOrderSchema.parse(body);
    const supabase = await getSupabaseServer();

    if (parsed.fulfillment_type === "delivery" && !parsed.delivery_address_id) {
      return errorResponse("Delivery address is required for delivery orders", "VALIDATION", 400);
    }
    if (parsed.fulfillment_type === "collection" && !parsed.collection_location_id) {
      return errorResponse("Collection location is required", "VALIDATION", 400);
    }

    const paymentMethod = parsed.payment_method ?? "paystack";
    if (paymentMethod === "paystack") {
      const paystackEnabled = await isFeatureEnabledServer("payment_paystack");
      if (!paystackEnabled) {
        return errorResponse(
          "Online card payment is currently unavailable. Please choose pay on delivery or another method.",
          "FEATURE_DISABLED",
          400
        );
      }
    }
    if (parsed.use_wallet === true) {
      const walletEnabled = await isFeatureEnabledServer("payment_wallet");
      if (!walletEnabled) {
        return errorResponse(
          "Wallet payment is currently unavailable.",
          "FEATURE_DISABLED",
          400
        );
      }
    }

    // Get cart items for this provider (include product_variant when present)
    const { data: cartItems, error: cartErr } = await (supabase.from("cart_items") as any)
      .select(
        `
        id, quantity, product_variant_id,
        product:products (
          id, name, retail_price, quantity, is_active, retail_sales_enabled,
          image_urls, tax_rate, provider_id, has_variants
        ),
        product_variant:product_variants (
          id, retail_price, quantity
        )
      `,
      )
      .eq("user_id", user.id)
      .eq("provider_id", parsed.provider_id);

    if (cartErr) throw cartErr;
    if (!cartItems || cartItems.length === 0) {
      return errorResponse("No cart items found for this provider", "EMPTY_CART", 400);
    }

    // Validate stock for all items (use variant quantity when variant)
    const stockErrors: string[] = [];
    for (const item of cartItems) {
      const p = item.product;
      const variant = item.product_variant;
      const effectiveQty = variant ? (variant.quantity ?? 0) : (p?.quantity ?? 0);
      if (!p || !p.is_active || !p.retail_sales_enabled) {
        stockErrors.push(`${p?.name ?? "Unknown product"} is no longer available`);
      } else if (p.has_variants && !variant) {
        stockErrors.push(`${p.name}: variant required`);
      } else if (effectiveQty < item.quantity) {
        stockErrors.push(`${p.name}: only ${effectiveQty} available (requested ${item.quantity})`);
      }
    }
    if (stockErrors.length > 0) {
      return errorResponse(stockErrors.join("; "), "INSUFFICIENT_STOCK", 400);
    }

    // Get shipping config for delivery fee
    let deliveryFee = 0;
    if (parsed.fulfillment_type === "delivery") {
      const { data: shipConfig } = await (supabase.from("provider_shipping_config") as any)
        .select("delivery_fee, free_delivery_threshold")
        .eq("provider_id", parsed.provider_id)
        .maybeSingle();

      if (shipConfig) {
        deliveryFee = parseFloat(shipConfig.delivery_fee) || 0;
        const subtotalCalc = cartItems.reduce(
          (sum: number, ci: any) => {
            const price = ci.product_variant ? ci.product_variant.retail_price : ci.product.retail_price;
            return sum + (parseFloat(price) || 0) * ci.quantity;
          },
          0,
        );
        if (
          shipConfig.free_delivery_threshold &&
          subtotalCalc >= parseFloat(shipConfig.free_delivery_threshold)
        ) {
          deliveryFee = 0;
        }
      }
    }

    // Calculate totals
    let subtotal = 0;
    let taxAmount = 0;
    const orderItems: Array<{
      product_id: string;
      product_variant_id: string | null;
      product_name: string;
      product_image_url: string | null;
      quantity: number;
      unit_price: number;
      total_price: number;
    }> = [];

    for (const item of cartItems) {
      const p = item.product;
      const variant = item.product_variant;
      const unitPrice = variant ? parseFloat(variant.retail_price) : parseFloat(p.retail_price);
      const lineTotal = unitPrice * item.quantity;
      const lineTax = lineTotal * (parseFloat(p.tax_rate || "0") / 100);
      subtotal += lineTotal;
      taxAmount += lineTax;
      orderItems.push({
        product_id: p.id,
        product_variant_id: variant?.id ?? null,
        product_name: p.name,
        product_image_url: p.image_urls?.[0] ?? null,
        quantity: item.quantity,
        unit_price: unitPrice,
        total_price: lineTotal,
      });
    }

    // Calculate platform fee for online orders
    let platformFee = 0;
    const isOnline = !["cash", "yoco"].includes(parsed.payment_method ?? "paystack");
    if (isOnline) {
      const { data: settingsRow } = await (supabase.from("platform_settings") as any)
        .select("settings")
        .eq("is_active", true)
        .limit(1)
        .maybeSingle();

      const payouts = (settingsRow?.settings as Record<string, any>)?.payouts as Record<string, any> | undefined;
      if (payouts) {
        const feeType = (payouts.platform_service_fee_type as string) || "percentage";
        if (feeType === "fixed") {
          platformFee = Number(payouts.platform_service_fee_fixed) || 0;
        } else {
          const pct = Number(payouts.platform_service_fee_percentage) || 5;
          platformFee = Math.round(subtotal * pct) / 100;
        }
      } else {
        platformFee = Math.round(subtotal * 5) / 100;
      }
    }

    const totalAmount = subtotal + taxAmount + deliveryFee + platformFee;

    // Determine wallet amount to apply (debit happens after order is created so we have order id)
    let walletAmountApplied = 0;
    const useWallet = parsed.use_wallet === true;
    if (useWallet && totalAmount > 0) {
      const { data: walletRow } = await (supabase.from("user_wallets") as any)
        .select("id, balance, currency")
        .eq("user_id", user.id)
        .maybeSingle();
      const balance = Number((walletRow as any)?.balance ?? 0);
      if (balance > 0) walletAmountApplied = Math.min(balance, totalAmount);
    }
    const amountAfterWallet = Math.max(0, totalAmount - walletAmountApplied);
    const paidWithWalletOnly = amountAfterWallet <= 0 && walletAmountApplied > 0;

    // Generate order number
    const { data: seqData } = await supabase.rpc("nextval", {
      seq_name: "product_order_number_seq",
    }) as any;
    const orderNum = `BO-${seqData ?? Date.now()}`;

    // Create order (wallet_amount and payment_status when paid by wallet)
    const { data: order, error: orderErr } = await (supabase.from("product_orders") as any)
      .insert({
        order_number: orderNum,
        customer_id: user.id,
        provider_id: parsed.provider_id,
        fulfillment_type: parsed.fulfillment_type,
        delivery_address_id: parsed.delivery_address_id ?? null,
        delivery_instructions: parsed.delivery_instructions ?? null,
        collection_location_id: parsed.collection_location_id ?? null,
        subtotal: subtotal.toFixed(2),
        tax_amount: taxAmount.toFixed(2),
        delivery_fee: deliveryFee.toFixed(2),
        platform_fee: platformFee.toFixed(2),
        total_amount: totalAmount.toFixed(2),
        wallet_amount: walletAmountApplied.toFixed(2),
        payment_method: paidWithWalletOnly ? "wallet" : (parsed.payment_method ?? "paystack"),
        payment_status: paidWithWalletOnly ? "paid" : "pending",
        order_source: "online",
      })
      .select()
      .single();

    if (orderErr) throw orderErr;

    // Debit wallet after order exists (so we can attach order id to transaction)
    if (walletAmountApplied > 0) {
      await (supabase.rpc as any)("wallet_debit_self", {
        p_amount: walletAmountApplied,
        p_description: `Product order ${order.order_number}`,
        p_reference_id: order.id,
        p_reference_type: "product_order",
      });
    }

    // Create order items
    const itemsToInsert = orderItems.map((oi) => ({
      ...oi,
      order_id: order.id,
      unit_price: oi.unit_price.toFixed(2),
      total_price: oi.total_price.toFixed(2),
    }));

    const { error: itemsErr } = await (supabase.from("product_order_items") as any).insert(
      itemsToInsert,
    );
    if (itemsErr) throw itemsErr;

    // Decrement stock for each product (variant or product-level)
    for (const item of cartItems) {
      if (item.product_variant_id) {
        await (supabase.rpc as any)("decrement_product_variant_stock", {
          p_variant_id: item.product_variant_id,
          p_quantity: item.quantity,
        });
      } else {
        await supabase.rpc("decrement_product_stock" as any, {
          p_product_id: item.product.id,
          p_quantity: item.quantity,
        });
      }
    }

    // Clear cart items for this provider
    await (supabase.from("cart_items") as any)
      .delete()
      .eq("user_id", user.id)
      .eq("provider_id", parsed.provider_id);

    // Notify provider of new order
    const { data: provider } = await (supabase.from("providers") as any)
      .select("owner_id")
      .eq("id", parsed.provider_id)
      .single();

    if (provider?.owner_id) {
      await supabase.from("notifications").insert({
        user_id: provider.owner_id,
        type: "product_order_placed",
        title: "New Product Order",
        message: `New order ${orderNum} received ΓÇö R${totalAmount.toFixed(2)} (${orderItems.length} items)`,
        metadata: {
          product_order_id: order.id,
          order_number: orderNum,
          total_amount: totalAmount,
        },
        link: "/provider/ecommerce/orders",
      }).then(() => {}, () => {});
    }

    // Order confirmation to customer via OneSignal notification template (push + email)
    try {
      const { notifyOrderConfirmation } = await import("@/lib/notifications/notification-service");
      await notifyOrderConfirmation(
        user.id,
        order.id,
        order.order_number,
        totalAmount,
        ["push", "email"],
      );
    } catch (notifyErr) {
      console.warn("Order confirmation notification failed:", notifyErr);
    }

    return successResponse({
      order: { ...order, items: orderItems },
      paid_with_wallet: paidWithWalletOnly,
      amount_due: amountAfterWallet,
    }, 201);
  } catch (err) {
    return handleApiError(err, "Failed to create order");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { z } from "zod";

const patchSchema = z.object({
  is_default: z.boolean().optional(),
});

/**
 * PATCH /api/me/payment-methods/[id]
 *
 * Update a payment method (e.g. set as primary/default card).
 * Only the owner can update their payment methods.
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);
    const { id } = await params;
    const supabase = await getSupabaseServer(request);

    if (!id) {
      return errorResponse("Payment method id is required", "VALIDATION_ERROR", 400);
    }

    const body = await request.json().catch(() => ({}));
    const parsed = patchSchema.safeParse(body);
    if (!parsed.success) {
      return errorResponse(
        parsed.error.issues.map((i) => i.message).join(", "),
        "VALIDATION_ERROR",
        400
      );
    }

    const { is_default } = parsed.data;

    // Ensure the payment method belongs to the user
    const { data: existing, error: fetchErr } = await supabase
      .from("payment_methods")
      .select("id, user_id")
      .eq("id", id)
      .eq("user_id", user.id)
      .eq("is_active", true)
      .single();

    if (fetchErr || !existing) {
      return errorResponse("Payment method not found", "NOT_FOUND", 404);
    }

    if (is_default === true) {
      // Unset other defaults for this user
      await (supabase.from("payment_methods") as any)
        .update({ is_default: false })
        .eq("user_id", user.id)
        .eq("is_default", true);

      const { data: updated, error: updateErr } = await (supabase.from("payment_methods") as any)
        .update({ is_default: true, updated_at: new Date().toISOString() })
        .eq("id", id)
        .eq("user_id", user.id)
        .select()
        .single();

      if (updateErr) throw updateErr;
      return successResponse(updated);
    }

    // Other fields could be supported here (e.g. is_default: false)
    return successResponse(existing);
  } catch (error) {
    return handleApiError(error, "Failed to update payment method");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { initializePaystackTransaction } from "@/lib/payments/paystack-server";
import { convertToSmallestUnit, generateTransactionReference } from "@/lib/payments/paystack";
import { z } from "zod";

const bodySchema = z.object({
  set_as_default: z.boolean().optional(),
  callback_url: z.string().url().optional(),
});

/**
 * POST /api/me/payment-methods/initialize-verification
 *
 * Start a small temporary charge (e.g. R1) to verify and save a card without a booking.
 * Customer pays on Paystack; we save the card on charge.success. The small amount can be
 * refunded separately or used as per product policy.
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer(request);

    const body = await request.json().catch(() => ({}));
    const parsed = bodySchema.safeParse(body);
    const { set_as_default, callback_url } = parsed.success ? parsed.data : { set_as_default: false, callback_url: undefined };

    // Get user email (required by Paystack)
    const { data: userRow } = await supabase
      .from("users")
      .select("email")
      .eq("id", user.id)
      .single();
    const email = (userRow as any)?.email ?? (user as any).email;
    if (!email || typeof email !== "string") {
      return errorResponse("Email is required to add a card. Please set your email in account settings.", "VALIDATION_ERROR", 400);
    }

    const currency = "ZAR";
    const amountInCurrency = 1; // R1 (or minimum) for verification
    const amountInSmallestUnit = convertToSmallestUnit(amountInCurrency);
    const reference = generateTransactionReference("card_verify", user.id);

    const baseUrl = process.env.NEXT_PUBLIC_APP_URL || "";
    const paystackData = await initializePaystackTransaction({
      email,
      amountInSmallestUnit,
      currency,
      reference,
      callback_url: callback_url || `${baseUrl}/account/settings/payments?card_verified=1`,
      metadata: {
        customer_id: user.id,
        save_card: true,
        set_as_default: set_as_default ?? false,
        kind: "card_verification",
      },
    });

    return successResponse({
      authorization_url: paystackData.data.authorization_url,
      access_code: paystackData.data.access_code,
      reference: paystackData.data.reference,
    });
  } catch (error) {
    return handleApiError(error, "Failed to start card verification");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { z } from "zod";

const addCardSchema = z.object({
  card_number: z.string().min(12).max(19),
  expiry_month: z.number().int().min(1).max(12),
  expiry_year: z.number().int().min(2020).max(2100),
  cvv: z.string().optional(),
  cardholder_name: z.string().min(1).max(120),
  billing_address: z.any().optional(),
  is_default: z.boolean().optional(),
});

/**
 * GET /api/me/payment-methods
 * 
 * Get user's payment methods
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer();

    const { data: methods, error } = await supabase
      .from("payment_methods")
      .select("id, type, provider, last_four, expiry_month, expiry_year, card_brand, is_default, is_active, metadata, created_at")
      .eq("user_id", user.id)
      .eq("is_active", true)
      .order("is_default", { ascending: false })
      .order("created_at", { ascending: false });

    if (error) {
      throw error;
    }

    // Backwards-compatible shape for existing UI (card_type/last4/cardholder_name)
    const shaped = (methods || []).map((m: any) => ({
      id: m.id,
      type: m.type,
      provider: m.provider || undefined, // Include provider to identify Paystack cards
      card_type: m.card_brand || undefined,
      last4: m.last_four || undefined,
      expiry_month: m.expiry_month || undefined,
      expiry_year: m.expiry_year || undefined,
      cardholder_name: m.metadata?.cardholder_name || undefined,
      is_default: m.is_default,
      is_active: m.is_active,
      created_at: m.created_at,
    }));

    return successResponse(shaped);
  } catch (error) {
    return handleApiError(error, "Failed to fetch payment methods");
  }
}

/**
 * POST /api/me/payment-methods
 * 
 * Add a new payment method
 * 
 * NOTE: Cards are saved automatically via Paystack when you make a payment.
 * This endpoint is kept for backward compatibility but cards should be saved
 * through the Paystack payment flow with the "save_card" option.
 * 
 * To save a card:
 * 1. Make a payment via Paystack
 * 2. Include "save_card: true" in the payment metadata
 * 3. Paystack will return an authorization_code
 * 4. The webhook will automatically save the card
 */
export async function POST(request: NextRequest) {
  try {
    await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);

    const _body = addCardSchema.parse(await request.json());

    // Cards should be saved via Paystack payment flow, not manually
    // This endpoint is deprecated for card saving
    return handleApiError(
      new Error("Cards must be saved through Paystack payment flow. Make a payment with 'save_card: true' option."),
      "Card saving via manual entry is not supported. Please save your card during checkout.",
      "DEPRECATED_METHOD",
      400
    );
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(new Error(error.issues.map((e: any) => e.message).join(", ")), "Validation failed", "VALIDATION_ERROR", 400);
    }
    return handleApiError(error, "Failed to add payment method");
  }
}

/**
 * DELETE /api/me/payment-methods
 * 
 * Remove a payment method (id should be in request body)
 */
export async function DELETE(
  request: NextRequest
) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer();
    const body = await request.json();
    const { id } = body;

    if (!id) {
      return handleApiError(
        new Error("Payment method id is required"),
        "Validation failed",
        "VALIDATION_ERROR",
        400
      );
    }

    const { error } = await (supabase
      .from("payment_methods") as any)
      .update({ is_active: false })
      .eq("id", id)
      .eq("user_id", user.id);

    if (error) {
      throw error;
    }

    return successResponse({ success: true });
  } catch (error) {
    return handleApiError(error, "Failed to remove payment method");
  }
}

function _getCardType(cardNumber: string): string {
  const number = cardNumber.replace(/\s/g, "");
  if (/^4/.test(number)) return "visa";
  if (/^5[1-5]/.test(number)) return "mastercard";
  if (/^3[47]/.test(number)) return "amex";
  if (/^6(?:011|5)/.test(number)) return "discover";
  return "unknown";
}

