 * Get current user's extended profile data (profile questions)
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer();

    const { data: profileData, error } = await supabase
      .from("user_profiles")
      .select("*")
      .eq("user_id", user.id)
      .maybeSingle(); // Use maybeSingle instead of single to avoid errors if no profile exists

    if (error) {
      // Only throw if it's not a "no rows" error
      if (error.code !== 'PGRST116') {
        throw error;
      }
      // If no profile exists, return null
      return successResponse(null);
    }

    return successResponse(profileData || null);
  } catch (error) {
    return handleApiError(error, "Failed to fetch profile data");
  }
}

/**
 * POST /api/me/profile-data
 * 
 * Create or update current user's extended profile data
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer();
    const body = await request.json();

    const {
      avatar_url,
      about,
      school,
      work,
      location,
      languages,
      decade_born,
      favorite_song,
      obsessed_with,
      fun_fact,
      useless_skill,
      biography_title,
      spend_time,
      pets,
      interests,
      travel_destinations,
      show_travel_history,
    } = body;

    // Check if profile exists
    const { data: existingProfile, error: checkError } = await supabase
      .from("user_profiles")
      .select("id")
      .eq("user_id", user.id)
      .maybeSingle();

    if (checkError && checkError.code !== 'PGRST116') {
      throw checkError;
    }

    const profileData: Record<string, any> = {
      user_id: user.id,
      // updated_at is handled by database trigger
    };

    // Only include fields that are provided
    // Handle null values explicitly - convert null to null, but allow empty arrays
    if (avatar_url !== undefined) profileData.avatar_url = avatar_url;
    if (about !== undefined) profileData.about = about;
    if (school !== undefined) profileData.school = school;
    if (work !== undefined) profileData.work = work;
    if (location !== undefined) profileData.location = location;
    if (languages !== undefined) profileData.languages = languages || [];
    if (decade_born !== undefined) profileData.decade_born = decade_born;
    if (favorite_song !== undefined) profileData.favorite_song = favorite_song;
    if (obsessed_with !== undefined) profileData.obsessed_with = obsessed_with;
    if (fun_fact !== undefined) profileData.fun_fact = fun_fact;
    if (useless_skill !== undefined) profileData.useless_skill = useless_skill;
    if (biography_title !== undefined) profileData.biography_title = biography_title;
    if (spend_time !== undefined) profileData.spend_time = spend_time;
    if (pets !== undefined) profileData.pets = pets;
    if (interests !== undefined) profileData.interests = interests || [];
    if (travel_destinations !== undefined) profileData.travel_destinations = travel_destinations || [];
    if (show_travel_history !== undefined) profileData.show_travel_history = show_travel_history;

    let result;
    if (existingProfile) {
      // Update existing profile
      const { data, error } = await supabase
        .from("user_profiles")
        .update(profileData)
        .eq("user_id", user.id)
        .select()
        .single();

      if (error) {
        console.error("Error updating profile:", error);
        throw error;
      }
      result = data;
    } else {
      // Create new profile
      const { data, error } = await supabase
        .from("user_profiles")
        .insert(profileData)
        .select()
        .single();

      if (error) {
        console.error("Error creating profile:", error);
        throw error;
      }
      result = data;
    }

    // Also update avatar_url in users table if provided
    if (avatar_url !== undefined) {
      await supabase
        .from("users")
        .update({ avatar_url })
        .eq("id", user.id);
    }

    return successResponse(result);
  } catch (error) {
    return handleApiError(error, "Failed to save profile data");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, notFoundResponse, handleApiError, requireRoleInApi } from "@/lib/supabase/api-helpers";
import type { User } from "@/types/beautonomi";

/**
 * GET /api/me/profile
 * 
 * Get current user's profile
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);

    const { data: userData, error } = await supabase
      .from("users")
      .select("*")
      .eq("id", user.id)
      .single();

    if (error || !userData) {
      return notFoundResponse("User not found");
    }

    // Get default address, verification, and profile data in parallel for better performance
    const [addressResult, verificationResult, profileResult] = await Promise.allSettled([
      supabase
        .from("user_addresses")
        .select("*")
        .eq("user_id", user.id)
        .eq("is_default", true)
        .maybeSingle(), // Use maybeSingle to avoid errors if no address exists
      supabase
        .from("user_verifications")
        .select("id, status, submitted_at, rejection_reason")
        .eq("user_id", user.id)
        .order("submitted_at", { ascending: false })
        .limit(1)
        .maybeSingle(), // Use maybeSingle to avoid errors if no verification exists
      supabase
        .from("user_profiles")
        .select("beauty_preferences, privacy_settings, business_preferences")
        .eq("user_id", user.id)
        .maybeSingle(),
    ]);

    const defaultAddress = addressResult.status === 'fulfilled' ? addressResult.value.data : null;
    const verification = verificationResult.status === 'fulfilled' ? verificationResult.value.data : null;
    const profileData = profileResult.status === 'fulfilled' ? profileResult.value.data : null;

    // Parse full_name into first_name and last_name
    const fullName = userData.full_name || "";
    const nameParts = fullName.trim().split(/\s+/);
    const first_name = nameParts[0] || "";
    const last_name = nameParts.slice(1).join(" ") || "";

    // Determine verification status
    const verificationStatus = verification?.status || (userData as any).identity_verification_status || 'none';
    const identityVerified = verificationStatus === 'approved';

    // Format response to match frontend expectations
    const formattedData = {
      ...userData,
      first_name,
      last_name,
      preferred_name: (userData as any).preferred_name || null,
      handle: (userData as any).handle || null,
      email_verified: (userData as any).email_verified || false,
      phone_verified: (userData as any).phone_verified || false,
      address: defaultAddress ? {
        country: defaultAddress.country || "",
        line1: defaultAddress.address_line1 || "",
        line2: defaultAddress.address_line2 || "",
        city: defaultAddress.city || "",
        state: defaultAddress.state || "",
        postal_code: defaultAddress.postal_code || "",
        street: defaultAddress.address_line1 || "",
        apt: defaultAddress.address_line2 || "",
        zip: defaultAddress.postal_code || "",
      } : null,
      emergency_contact: {
        name: userData.emergency_contact_name || "",
        relationship: userData.emergency_contact_relationship || "",
        language: userData.preferred_language || "",
        email: (userData as any).emergency_contact_email || "",
        country_code: (userData as any).emergency_contact_country_code || "",
        phone: userData.emergency_contact_phone || "",
      },
      identity_verified: identityVerified,
      identity_verification_status: verificationStatus,
      identity_verification_submitted_at: verification?.submitted_at || null,
      identity_verification_rejection_reason: verification?.rejection_reason || null,
      beauty_preferences: profileData?.beauty_preferences || {},
      privacy_settings: profileData?.privacy_settings || { services_booked_visible: false },
      business_preferences: profileData?.business_preferences || { email: null, enabled: false },
      password_changed_at: (userData as any).password_changed_at || null,
    };

    return successResponse(formattedData as any);
  } catch (error) {
    // Log the error for debugging
    console.error("Error in GET /api/me/profile:", error);
    return handleApiError(error, "Failed to fetch profile");
  }
}

/**
 * PATCH /api/me/profile
 * 
 * Update current user's profile
 */
export async function PATCH(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
    const body = await request.json();
    const supabase = await getSupabaseServer(request);

    const updates: Record<string, any> = {};

    // Handle first_name and last_name (combine into full_name)
    if (body.first_name !== undefined || body.last_name !== undefined) {
      const { data: currentUser } = await supabase
        .from("users")
        .select("full_name")
        .eq("id", user.id)
        .single();

      const currentFullName = currentUser?.full_name || "";
      const nameParts = currentFullName.trim().split(/\s+/);
      const currentFirst = nameParts[0] || "";
      const currentLast = nameParts.slice(1).join(" ") || "";

      const first = body.first_name !== undefined ? body.first_name : currentFirst;
      const last = body.last_name !== undefined ? body.last_name : currentLast;
      updates.full_name = `${first} ${last}`.trim();
    }

    // Handle preferred_name
    if (body.preferred_name !== undefined) {
      updates.preferred_name = body.preferred_name || null;
    }

    // Handle handle (username)
    if (body.handle !== undefined) {
      const handle = body.handle?.trim() || null;
      if (handle) {
        // Validate handle format (alphanumeric + underscore, 3-50 chars)
        if (!/^[a-zA-Z0-9_]{3,50}$/.test(handle)) {
          throw new Error("Handle must be 3-50 characters and contain only letters, numbers, and underscores");
        }
        // Check if handle is already taken (case-insensitive)
        const { data: existingUser } = await supabase
          .from("users")
          .select("id")
          .eq("handle", handle)
          .neq("id", user.id)
          .maybeSingle();

        if (existingUser) {
          throw new Error("This handle is already taken");
        }
      }
      updates.handle = handle;
    }

    // Handle other user fields
    if (body.phone !== undefined) updates.phone = body.phone;
    if (body.avatar_url !== undefined) updates.avatar_url = body.avatar_url;
    if (body.date_of_birth !== undefined) updates.date_of_birth = body.date_of_birth;
    if (body.preferred_language !== undefined) updates.preferred_language = body.preferred_language;
    if (body.preferred_currency !== undefined) updates.preferred_currency = body.preferred_currency;
    if (body.timezone !== undefined) updates.timezone = body.timezone;
    if (body.email_verified !== undefined) updates.email_verified = body.email_verified;
    if (body.phone_verified !== undefined) updates.phone_verified = body.phone_verified;

    // Handle emergency_contact object
    if (body.emergency_contact !== undefined) {
      const ec = body.emergency_contact;
      if (ec.name !== undefined) updates.emergency_contact_name = ec.name || null;
      if (ec.phone !== undefined) updates.emergency_contact_phone = ec.phone || null;
      if (ec.relationship !== undefined) updates.emergency_contact_relationship = ec.relationship || null;
      if (ec.language !== undefined) updates.preferred_language = ec.language || null;
      if (ec.email !== undefined) updates.emergency_contact_email = ec.email || null;
      if (ec.country_code !== undefined) updates.emergency_contact_country_code = ec.country_code || null;
    }

    // Handle address object
    if (body.address !== undefined) {
      const address = body.address;

      // Check if default address exists
      const { data: existingAddress } = await supabase
        .from("user_addresses")
        .select("id")
        .eq("user_id", user.id)
        .eq("is_default", true)
        .single();

      const addressData = {
        user_id: user.id,
        address_line1: address.line1 || address.street || "",
        address_line2: address.line2 || address.apt || "",
        city: address.city || "",
        state: address.state || "",
        postal_code: address.postal_code || address.zip || "",
        country: address.country || "",
        is_default: true,
      };

      if (existingAddress) {
        // Update existing default address
        const { error: addressError } = await supabase
          .from("user_addresses")
          .update(addressData)
          .eq("id", existingAddress.id);

        if (addressError) {
          throw new Error(`Failed to update address: ${addressError.message}`);
        }
      } else {
        // Create new default address (unset other defaults first)
        await supabase
          .from("user_addresses")
          .update({ is_default: false })
          .eq("user_id", user.id)
          .eq("is_default", true);

        const { error: addressError } = await supabase
          .from("user_addresses")
          .insert(addressData);

        if (addressError) {
          throw new Error(`Failed to create address: ${addressError.message}`);
        }
      }
    }

    // Handle business preferences (Beautonomi for Business)
    if (body.business_email !== undefined || body.business_features_enabled !== undefined) {
      const { data: existingProfile } = await supabase
        .from("user_profiles")
        .select("business_preferences")
        .eq("user_id", user.id)
        .maybeSingle();
      const current = (existingProfile as any)?.business_preferences || { email: null, enabled: false };
      const businessPreferences = {
        email: body.business_email !== undefined ? (body.business_email || null) : current.email,
        enabled: body.business_features_enabled !== undefined ? Boolean(body.business_features_enabled) : current.enabled,
      };
      if (existingProfile) {
        const { error: profileError } = await supabase
          .from("user_profiles")
          .update({ business_preferences: businessPreferences })
          .eq("user_id", user.id);
        if (profileError) throw new Error(`Failed to update business preferences: ${profileError.message}`);
      } else {
        const { error: profileError } = await supabase
          .from("user_profiles")
          .insert({ user_id: user.id, business_preferences: businessPreferences });
        if (profileError) throw new Error(`Failed to save business preferences: ${profileError.message}`);
      }
    }

    // Update email in auth.users if provided
    if (body.email !== undefined) {
      const { error: emailError } = await supabase.auth.updateUser({
        email: body.email,
      });
      if (emailError) {
        throw new Error(`Failed to update email: ${emailError.message}`);
      }
      updates.email = body.email;
    }

    // Update user record
    if (Object.keys(updates).length > 0) {
      const { data: userData, error } = await supabase
        .from("users")
        .update(updates)
        .eq("id", user.id)
        .select()
        .single();

      if (error || !userData) {
        throw new Error(error?.message || "Failed to update profile");
      }

      // Return formatted response
      const { data: defaultAddress } = await supabase
        .from("user_addresses")
        .select("*")
        .eq("user_id", user.id)
        .eq("is_default", true)
        .single();

      const { data: verification } = await supabase
        .from("user_verifications")
        .select("id, status")
        .eq("user_id", user.id)
        .eq("status", "approved")
        .limit(1)
        .single();

      const fullName = userData.full_name || "";
      const nameParts = fullName.trim().split(/\s+/);
      const first_name = nameParts[0] || "";
      const last_name = nameParts.slice(1).join(" ") || "";

      // Get updated profile data
      const { data: updatedProfileData } = await supabase
        .from("user_profiles")
        .select("beauty_preferences, privacy_settings")
        .eq("user_id", user.id)
        .maybeSingle();

      const formattedData = {
        ...userData,
        first_name,
        last_name,
        preferred_name: (userData as any).preferred_name || null,
        handle: (userData as any).handle || null,
        email_verified: (userData as any).email_verified || false,
        phone_verified: (userData as any).phone_verified || false,
        address: defaultAddress ? {
          country: defaultAddress.country || "",
          line1: defaultAddress.address_line1 || "",
          line2: defaultAddress.address_line2 || "",
          city: defaultAddress.city || "",
          state: defaultAddress.state || "",
          postal_code: defaultAddress.postal_code || "",
          street: defaultAddress.address_line1 || "",
          apt: defaultAddress.address_line2 || "",
          zip: defaultAddress.postal_code || "",
        } : null,
        emergency_contact: {
          name: userData.emergency_contact_name || "",
          relationship: userData.emergency_contact_relationship || "",
          language: userData.preferred_language || "",
          email: (userData as any).emergency_contact_email || "",
          country_code: (userData as any).emergency_contact_country_code || "",
          phone: userData.emergency_contact_phone || "",
        },
        identity_verified: verification ? true : false,
        identity_verification_status: verification?.status || (userData as any).identity_verification_status || null,
        beauty_preferences: updatedProfileData?.beauty_preferences || {},
        privacy_settings: updatedProfileData?.privacy_settings || { services_booked_visible: false },
      };

      return successResponse(formattedData as any);
    }

    // If no updates, return current data
    const { data: userData } = await supabase
      .from("users")
      .select("*")
      .eq("id", user.id)
      .single();

    return successResponse(userData as User);
  } catch (error) {
    return handleApiError(error, "Failed to update profile");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { z } from "zod";

const upsertSchema = z.object({
  provider_id: z.string().uuid("Invalid provider_id"),
});

/**
 * GET /api/me/recently-viewed
 *
 * Returns providers the current user has recently viewed (most recent first)
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer();

    const { searchParams } = new URL(request.url);
    const limit = Math.min(50, Math.max(1, parseInt(searchParams.get("limit") || "24", 10)));

    // First, get the recently viewed records
    const { data: rows, error: rowsError } = await (supabase
      .from("recently_viewed_providers") as any)
      .select("viewed_at, provider_id")
      .eq("user_id", user.id)
      .order("viewed_at", { ascending: false })
      .limit(limit);

    if (rowsError) {
      console.error("Error fetching recently_viewed_providers:", {
        error: rowsError,
        message: rowsError.message,
        code: rowsError.code,
        details: rowsError.details,
        hint: rowsError.hint,
        userId: user.id,
      });

      // Check if it's a table not found error
      if (rowsError.message?.includes("does not exist") || rowsError.code === "42P01") {
        console.warn("recently_viewed_providers table not found - returning empty array");
        return successResponse([]);
      }

      // Check if it's an RLS/permission error
      if (rowsError.code === "42501" || rowsError.message?.includes("permission denied") || rowsError.message?.includes("row-level security")) {
        console.warn("RLS policy blocking access to recently_viewed_providers - returning empty array");
        return successResponse([]);
      }

      // For other errors, still return empty array to prevent page breakage
      console.warn("Unknown error fetching recently_viewed_providers - returning empty array:", rowsError);
      return successResponse([]);
    }

    if (!rows || rows.length === 0) {
      return successResponse([]);
    }

    // Extract provider IDs
    const providerIds = rows.map((r: any) => r.provider_id).filter(Boolean);

    if (providerIds.length === 0) {
      return successResponse([]);
    }

    // Fetch providers separately to avoid RLS issues with foreign key queries
    const { data: providers, error: providersError } = await (supabase
      .from("providers") as any)
      .select(`
        id,
        slug,
        business_name,
        business_type,
        rating,
        review_count,
        thumbnail_url,
        avatar_url,
        city,
        country,
        description,
        status,
        is_featured,
        is_verified,
        starting_price,
        currency
      `)
      .in("id", providerIds);

    if (providersError) {
      console.error("Error fetching providers for recently viewed:", {
        error: providersError,
        message: providersError.message,
        code: providersError.code,
        providerIds: providerIds.slice(0, 5), // Log first 5 IDs
      });

      // If providers can't be fetched, return empty array with viewed records
      // This way the user at least knows they have viewed items, even if we can't show details
      return successResponse([]);
    }

    // Create a map of provider_id -> viewed_at
    const viewedAtMap = new Map(rows.map((r: any) => [r.provider_id, r.viewed_at]));

    // Combine providers with viewed_at timestamps, maintaining order
    const providersWithViewedAt = (providers || [])
      .map((p: any) => ({
        ...p,
        viewed_at: viewedAtMap.get(p.id) || new Date().toISOString(),
      }))
      .sort((a: any, b: any) => {
        const aTime = new Date(a.viewed_at).getTime();
        const bTime = new Date(b.viewed_at).getTime();
        return bTime - aTime; // Most recent first
      });

    return successResponse(providersWithViewedAt);
  } catch (error) {
    console.error("Unexpected error in GET /api/me/recently-viewed:", error);
    // Return empty array instead of error to prevent page breakage
    return successResponse([]);
  }
}

/**
 * POST /api/me/recently-viewed
 *
 * Upserts a provider view for the current user
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer();

    const body = upsertSchema.parse(await request.json());
    const now = new Date().toISOString();

    const { error } = await (supabase.from("recently_viewed_providers") as any).upsert(
      {
        user_id: user.id,
        provider_id: body.provider_id,
        viewed_at: now,
      },
      { onConflict: "user_id,provider_id" }
    );

    if (error) throw error;

    return successResponse({ success: true });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(new Error(error.issues.map((e) => e.message).join(", ")), "Validation failed");
    }
    return handleApiError(error, "Failed to track provider view");
  }
}

/**
 * DELETE /api/me/recently-viewed
 *
 * Clears recently viewed history (or removes a single provider if provider_id provided)
 */
export async function DELETE(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer();
    const { searchParams } = new URL(request.url);
    const providerId = searchParams.get("provider_id");

    let query = (supabase.from("recently_viewed_providers") as any).delete().eq("user_id", user.id);
    if (providerId) query = query.eq("provider_id", providerId);

    const { error } = await query;
    if (error) throw error;

    return successResponse({ success: true });
  } catch (error) {
    return handleApiError(error, "Failed to clear recently viewed providers");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  errorResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";

/**
 * POST /api/me/referrals/attach
 *
 * Attach the current user to a referrer (e.g. after signup with ?ref=CODE).
 * Sets users.referred_by for the current user. Idempotent; only sets if not already set.
 *
 * Body: { referral_code: string }
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(
      ["customer", "provider_owner", "provider_staff", "superadmin"],
      request
    );
    const supabase = await getSupabaseServer(request);

    const body = await request.json();
    const referral_code =
      typeof body?.referral_code === "string" ? body.referral_code.trim() : null;

    if (!referral_code) {
      return errorResponse(
        "referral_code is required",
        "VALIDATION_ERROR",
        400
      );
    }

    // Resolve code to referrer user id
    const { data: referrer, error: lookupError } = await supabase
      .from("users")
      .select("id")
      .or(`handle.eq.${referral_code},id.eq.${referral_code}`)
      .limit(1)
      .maybeSingle();

    if (lookupError || !referrer) {
      return errorResponse(
        "Invalid referral code",
        "NOT_FOUND",
        404
      );
    }

    const referrerId = (referrer as { id: string }).id;
    if (referrerId === user.id) {
      return errorResponse(
        "Cannot attach your own referral code",
        "VALIDATION_ERROR",
        400
      );
    }

    // Only set referred_by if not already set (first signup attribution wins)
    const { data: current } = await supabase
      .from("users")
      .select("referred_by")
      .eq("id", user.id)
      .single();

    if ((current as any)?.referred_by) {
      return successResponse({ attached: false, message: "Already referred" });
    }

    const { error: updateError } = await supabase
      .from("users")
      .update({ referred_by: referrerId })
      .eq("id", user.id);

    if (updateError) {
      return handleApiError(updateError, "Failed to attach referral");
    }

    return successResponse({ attached: true, referrer_id: referrerId });
  } catch (error) {
    return handleApiError(error, "Failed to attach referral");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import {
  requireRoleInApi,
  successResponse,
  errorResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";

const REFERRAL_SETTINGS_ID = "00000000-0000-0000-0000-000000000001";

/**
 * POST /api/me/referrals/track
 *
 * Records a referral conversion when a referred user makes their first
 * booking. Uses referral_settings (single-row). Awards loyalty points to referrer.
 *
 * Body:
 *   - booking_id: string       ΓÇö the newly-created booking ID (required)
 *   - referral_code?: string   ΓÇö optional; if omitted, uses current user's referred_by
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi([
      "customer",
      "provider_owner",
      "provider_staff",
      "superadmin",
    ], request);
    const supabaseAdmin = await getSupabaseAdmin();

    const body = await request.json();
    const { referral_code: codeFromBody, booking_id } = body;

    if (!booking_id) {
      return errorResponse(
        "booking_id is required",
        "VALIDATION_ERROR",
        400
      );
    }

    let referrerUser: { id: string; handle: string } | null = null;
    let referralCode: string;

    if (codeFromBody) {
      // Look up referrer by code (handle or short-id)
      const { data, error: referrerError } = await supabaseAdmin
        .from("users")
        .select("id, handle")
        .or(`handle.eq.${codeFromBody},id.ilike.${codeFromBody}%`)
        .limit(1)
        .maybeSingle();

      if (referrerError) {
        console.error("[referrals/track] Referrer lookup error:", referrerError);
        return handleApiError(referrerError, "Failed to look up referral code");
      }
      referrerUser = data;
      referralCode = codeFromBody;
    } else {
      // Use current user's referred_by (set at signup via ref=)
      const { data: me } = await supabaseAdmin
        .from("users")
        .select("referred_by")
        .eq("id", user.id)
        .single();

      if (!me?.referred_by) {
        return errorResponse(
          "No referral to attribute. Use referral_code or sign up with a referral link.",
          "VALIDATION_ERROR",
          400
        );
      }

      const { data: referrer } = await supabaseAdmin
        .from("users")
        .select("id, handle")
        .eq("id", (me as any).referred_by)
        .single();

      referrerUser = referrer;
      referralCode = referrer?.handle || (referrer as any)?.id?.slice(0, 8) || String((me as any).referred_by);
    }

    if (!referrerUser) {
      return errorResponse(
        "Invalid referral code or referrer not found",
        "NOT_FOUND",
        404
      );
    }

    if (referrerUser.id === user.id) {
      return errorResponse(
        "Cannot use your own referral code",
        "VALIDATION_ERROR",
        400
      );
    }

    // Load referral reward settings (single-row table; column is referral_amount not reward_amount)
    let rewardAmount = 50;
    let rewardCurrency = "ZAR";
    try {
      const { data: settings } = await supabaseAdmin
        .from("referral_settings")
        .select("referral_amount, referral_currency")
        .eq("id", REFERRAL_SETTINGS_ID)
        .maybeSingle();

      if (settings) {
        rewardAmount = Number((settings as any).referral_amount) || 50;
        rewardCurrency = (settings as any).referral_currency || "ZAR";
      }
    } catch {
      // use defaults
    }

    // Uniqueness: one reward per referred user (first booking only). No double-credit on later bookings.
    try {
      const { data: existingForUser } = await supabaseAdmin
        .from("user_referrals")
        .select("id")
        .eq("referred_user_id", user.id)
        .limit(1)
        .maybeSingle();

      if (existingForUser) {
        return successResponse(
          { referral_id: existingForUser.id, status: "already_converted" },
          200
        );
      }
    } catch {
      // proceed
    }

    // Optional: same booking already tracked (idempotent)
    try {
      const { data: existingForBooking } = await supabaseAdmin
        .from("user_referrals")
        .select("id")
        .eq("referred_user_id", user.id)
        .eq("booking_id", booking_id)
        .maybeSingle();
      if (existingForBooking) {
        return successResponse(
          { referral_id: existingForBooking.id, status: "already_tracked" },
          200
        );
      }
    } catch {
      // proceed
    }

    // Insert referral record (booking_id column added in migration 241)
    let referralRecord: any = null;
    try {
      const { data, error: insertError } = await supabaseAdmin
        .from("user_referrals")
        .insert({
          referrer_id: referrerUser.id,
          referred_user_id: user.id,
          referral_code: referralCode,
          booking_id: booking_id,
          reward_amount: rewardAmount,
          reward_currency: rewardCurrency,
          status: "completed",
        })
        .select()
        .single();

      if (insertError) {
        console.error("[referrals/track] Insert error:", insertError);
        return handleApiError(insertError, "Failed to record referral");
      }

      referralRecord = data;
    } catch (err) {
      console.error("[referrals/track] Insert exception:", err);
      return errorResponse(
        "Failed to record referral ΓÇö user_referrals table may not exist",
        "INTERNAL_ERROR",
        500
      );
    }

    // Credit referrer's wallet (platform pays this; see revenue impact in admin referral settings)
    try {
      await supabaseAdmin.rpc("wallet_credit_admin", {
        p_user_id: referrerUser.id,
        p_amount: rewardAmount,
        p_currency: rewardCurrency,
        p_description: `Referral reward ΓÇö referred user completed first booking`,
        p_reference_id: referralRecord?.id ?? null,
        p_reference_type: "referral",
      });
    } catch (walletErr) {
      console.warn("[referrals/track] Could not credit wallet:", walletErr);
    }

    // Optional: record in loyalty_point_transactions for audit (points = reward amount)
    try {
      await supabaseAdmin.from("loyalty_point_transactions").insert({
        user_id: referrerUser.id,
        points: Math.round(rewardAmount),
        transaction_type: "earned",
        description: "Referral reward",
        reference_id: referralRecord?.id ?? null,
        reference_type: "referral",
      });
    } catch {
      // Non-fatal
    }

    return successResponse(
      {
        referral_id: referralRecord?.id,
        referrer_id: referrerUser.id,
        reward_amount: rewardAmount,
        reward_currency: rewardCurrency,
        status: "completed",
      },
      201
    );
  } catch (error) {
    return handleApiError(error, "Failed to track referral");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, handleApiError, successResponse } from "@/lib/supabase/api-helpers";

/**
 * POST /api/me/request-data
 * 
 * Request a personal data export for the current user
 * This will create a data export request that can be processed asynchronously
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer();

    // Check if there's already a pending request
    const { data: existingUser } = await supabase
      .from("users")
      .select("data_export_requested_at, data_export_ready_at")
      .eq("id", user.id)
      .single();

    if (existingUser?.data_export_requested_at && !existingUser?.data_export_ready_at) {
      return NextResponse.json(
        { error: "You already have a pending data export request. Please wait for it to be processed." },
        { status: 400 }
      );
    }

    // Update user with data export request timestamp
    const { error: updateError } = await supabase
      .from("users")
      .update({
        data_export_requested_at: new Date().toISOString(),
        data_export_ready_at: null,
        data_export_download_url: null,
      })
      .eq("id", user.id);

    if (updateError) {
      throw updateError;
    }

    // Generate data export immediately
    try {
      const exportData: Record<string, any> = {
        exportDate: new Date().toISOString(),
        userId: user.id,
        userEmail: user.email,
      };

      // Collect user profile data
      const { data: userData } = await supabase
        .from("users")
        .select("*")
        .eq("id", user.id)
        .single();
      exportData.profile = userData;

      // Collect user profile extended data
      const { data: userProfile } = await supabase
        .from("user_profiles")
        .select("*")
        .eq("user_id", user.id)
        .single();
      exportData.extendedProfile = userProfile;

      // Collect bookings
      const { data: bookings } = await supabase
        .from("bookings")
        .select("*")
        .or(`customer_id.eq.${user.id},provider_id.eq.${user.id}`);
      exportData.bookings = bookings || [];

      // Collect messages and conversations
      const { data: conversations } = await supabase
        .from("conversations")
        .select("*")
        .or(`customer_id.eq.${user.id},provider_id.eq.${user.id}`);
      exportData.conversations = conversations || [];

      if (conversations && conversations.length > 0) {
        const conversationIds = conversations.map(c => c.id);
        const { data: messages } = await supabase
          .from("messages")
          .select("*")
          .in("conversation_id", conversationIds);
        exportData.messages = messages || [];
      } else {
        exportData.messages = [];
      }

      // Collect reviews
      const { data: reviews } = await supabase
        .from("reviews")
        .select("*")
        .or(`reviewer_id.eq.${user.id},reviewee_id.eq.${user.id}`);
      exportData.reviews = reviews || [];

      // Collect addresses
      const { data: addresses } = await supabase
        .from("addresses")
        .select("*")
        .eq("user_id", user.id);
      exportData.addresses = addresses || [];

      // Collect payment methods
      const { data: paymentMethods } = await supabase
        .from("payment_methods")
        .select("*")
        .eq("user_id", user.id);
      exportData.paymentMethods = paymentMethods || [];

      // Collect wishlists
      const { data: wishlists } = await supabase
        .from("wishlists")
        .select("*")
        .eq("user_id", user.id);
      exportData.wishlists = wishlists || [];

      // Collect user coupons
      const { data: userCoupons } = await supabase
        .from("user_coupons")
        .select("*")
        .eq("user_id", user.id);
      exportData.coupons = userCoupons || [];

      // Collect wallet data
      const { data: wallet } = await supabase
        .from("user_wallets")
        .select("*")
        .eq("user_id", user.id)
        .single();
      exportData.wallet = wallet;

      // Collect identity verification data
      const { data: verifications } = await supabase
        .from("user_verifications")
        .select("*")
        .eq("user_id", user.id);
      exportData.verifications = verifications || [];

      // Collect custom requests
      const { data: customRequests } = await supabase
        .from("custom_requests")
        .select("*")
        .eq("user_id", user.id);
      exportData.customRequests = customRequests || [];

      // Generate JSON file content
      const jsonContent = JSON.stringify(exportData, null, 2);
      const base64Content = Buffer.from(jsonContent).toString('base64');

      // Create a data URL for immediate download
      // In production, you could upload to Supabase Storage or S3 and generate a signed URL
      const downloadUrl = `data:application/json;base64,${base64Content}`;

      // Update user with ready status
      const { error: readyError } = await supabase
        .from("users")
        .update({
          data_export_ready_at: new Date().toISOString(),
          data_export_download_url: downloadUrl,
        })
        .eq("id", user.id);

      if (readyError) {
        throw readyError;
      }

      return successResponse({
        message: "Your data export is ready for download.",
        requestedAt: new Date().toISOString(),
        downloadUrl: downloadUrl,
        dataSize: jsonContent.length,
        fileName: `beautonomi-data-export-${user.id}-${new Date().toISOString().split('T')[0]}.json`,
      });
    } catch (exportError) {
      // If export generation fails, still mark as requested but log error
      console.error("Data export generation error:", exportError);
      return successResponse({
        message: "Your data export request has been submitted. We'll process it and notify you when ready.",
        requestedAt: new Date().toISOString(),
      });
    }
  } catch (error) {
    return handleApiError(error, "Failed to request data export");
  }
}

