      .from("user_wallets")
      .select("id, user_id, balance, currency, updated_at, created_at")
      .eq("user_id", user.id)
      .single();
    if (walletError) throw walletError;

    const { data: txs, error: txError } = await supabase
      .from("wallet_transactions")
      .select("id, wallet_id, type, amount, description, reference_id, reference_type, created_at")
      .eq("wallet_id", (wallet as any).id)
      .order("created_at", { ascending: false })
      .limit(50);
    if (txError) throw txError;

    return successResponse({
      wallet,
      transactions: txs || [],
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch wallet");
  }
}

import { NextRequest } from "next/server";
import { z } from "zod";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { convertToSmallestUnit } from "@/lib/payments/paystack";
import { initializePaystackTransaction } from "@/lib/payments/paystack-server";

const schema = z.object({
  amount: z.number().positive(),
});

export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer();

    const body = schema.parse(await request.json());

    const { data: userRow } = await supabase.from("users").select("email, preferred_currency").eq("id", user.id).single();
    const currency = (userRow as any)?.preferred_currency || "ZAR";
    const email = (userRow as any)?.email;
    if (!email) throw new Error("User email is required");

    // Create pending topup row first (we'll update with reference + payment_url)
    const { data: topup, error: topupError } = await (supabase.from("wallet_topups") as any)
      .insert({
        user_id: user.id,
        amount: Number(body.amount),
        currency,
        status: "pending",
      })
      .select()
      .single();
    if (topupError) throw topupError;

    const reference = `wallet_topup_${(topup as any).id}`;
    const callbackUrl = `${process.env.NEXT_PUBLIC_APP_URL || ""}/checkout/success?payment_type=wallet_topup`;

    const paystackData = await initializePaystackTransaction({
      email,
      amountInSmallestUnit: convertToSmallestUnit(Number(body.amount)),
      currency,
      reference,
      callback_url: callbackUrl,
      metadata: {
        wallet_topup_id: (topup as any).id,
        user_id: user.id,
        amount: Number(body.amount),
        currency,
      },
    });

    const paymentUrl = paystackData?.data?.authorization_url || null;

    await (supabase.from("wallet_topups") as any)
      .update({
        paystack_reference: reference,
        payment_url: paymentUrl,
      })
      .eq("id", (topup as any).id);

    return successResponse({
      topup_id: (topup as any).id,
      payment_url: paymentUrl,
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(error, "Invalid request data", "VALIDATION_ERROR", 400);
    }
    return handleApiError(error, "Failed to initialize wallet topup");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/me/wishlists/[id]/items
 *
 * Get all items in a specific wishlist
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer();
    const { id: wishlistId } = await params;

    // Verify wishlist belongs to user
    const { data: wishlist, error: wlError } = await (supabase.from("wishlists") as any)
      .select("id")
      .eq("id", wishlistId)
      .eq("user_id", user.id)
      .single();

    if (wlError || !wishlist) {
      return successResponse([], 200); // Return empty array if wishlist not found
    }

    // Get items
    const { data: items, error: itemsError } = await (supabase.from("wishlist_items") as any)
      .select("id, item_type, item_id, created_at")
      .eq("wishlist_id", wishlistId)
      .order("created_at", { ascending: false });

    if (itemsError) throw itemsError;

    if (!items || items.length === 0) {
      return successResponse([]);
    }

    // Filter for provider items and get provider IDs
    const providerItems = items.filter((item: any) => item.item_type === "provider");
    const providerIds = providerItems.map((item: any) => item.item_id);

    if (providerIds.length === 0) {
      return successResponse([]);
    }

    // Fetch full provider data
    const { data: providers, error: providersError } = await (supabase.from("providers") as any)
      .select(`
        id,
        slug,
        business_name,
        business_type,
        rating_average,
        review_count,
        thumbnail_url,
        avatar_url,
        description,
        status,
        is_featured,
        is_verified,
        currency
      `)
      .in("id", providerIds)
      .eq("status", "active");

    if (providersError) {
      console.error("Error fetching providers:", providersError);
      throw providersError;
    }

    // Create a map of provider_id -> created_at (when it was added to wishlist)
    const addedAtMap = new Map(providerItems.map((item: any) => [item.item_id, item.created_at]));

    // Combine providers with added_at timestamp, maintaining order
    const providersWithAddedAt = (providers || [])
      .map((p: any) => ({
        ...p,
        added_at: addedAtMap.get(p.id) || new Date().toISOString(),
      }))
      .sort((a: any, b: any) => {
        const aTime = new Date(a.added_at).getTime();
        const bTime = new Date(b.added_at).getTime();
        return bTime - aTime; // Most recently added first
      });

    return successResponse(providersWithAddedAt);
  } catch (error) {
    return handleApiError(error, "Failed to load wishlist items");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { z } from "zod";

const checkSchema = z.object({
  item_type: z.enum(["provider", "offering", "package"]),
  item_id: z.string().uuid(),
});

/**
 * POST /api/me/wishlists/check
 * 
 * Quickly checks if an item is in any of the user's wishlists.
 * Returns { is_in_wishlist: boolean, wishlist_id?: string }
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer();

    const body = checkSchema.parse(await request.json());

    // Get all wishlists for the user
    const { data: wishlists, error: wishlistsError } = await supabase
      .from("wishlists")
      .select("id")
      .eq("user_id", user.id);

    if (wishlistsError) {
      throw wishlistsError;
    }

    if (!wishlists || wishlists.length === 0) {
      return successResponse({ is_in_wishlist: false });
    }

    const wishlistIds = wishlists.map((w: any) => w.id);

    // Check if item exists in any wishlist
    const { data: item, error: itemError } = await supabase
      .from("wishlist_items")
      .select("wishlist_id")
      .eq("item_type", body.item_type)
      .eq("item_id", body.item_id)
      .in("wishlist_id", wishlistIds)
      .maybeSingle();

    if (itemError && itemError.code !== "PGRST116") {
      // PGRST116: "Results contain 0 rows" for maybeSingle
      throw itemError;
    }

    return successResponse({
      is_in_wishlist: !!item,
      wishlist_id: item?.wishlist_id || null,
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(new Error(error.issues.map((e) => e.message).join(", ")), "Validation failed");
    }
    return handleApiError(error, "Failed to check wishlist status");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse } from "@/lib/supabase/api-helpers";

/**
 * GET /api/me/wishlists/providers
 *
 * Get all saved providers from all wishlists (for main wishlist page)
 */
export async function GET(request: NextRequest) {
  try {
    let user;
    try {
      const result = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);
      user = result.user;
    } catch (authError) {
      console.error("Authentication error:", authError);
      // Return empty array if auth fails
      return successResponse([]);
    }
    
    const supabase = await getSupabaseServer();

    // Get all wishlists for user
    const { data: wishlists, error: wishlistError } = await (supabase.from("wishlists") as any)
      .select("id")
      .eq("user_id", user.id);

    if (wishlistError) {
      console.error("Error fetching wishlists:", wishlistError);
      // Return empty array instead of throwing
      return successResponse([]);
    }

    if (!wishlists || wishlists.length === 0) {
      return successResponse([]);
    }

    const wishlistIds = wishlists.map((w: any) => w.id);

    // Get all provider items from all wishlists
    const { data: items, error: itemsError } = await (supabase.from("wishlist_items") as any)
      .select("id, item_type, item_id, wishlist_id, created_at")
      .in("wishlist_id", wishlistIds)
      .eq("item_type", "provider")
      .order("created_at", { ascending: false });

    if (itemsError) {
      console.error("Error fetching wishlist items:", itemsError);
      // Return empty array instead of throwing
      return successResponse([]);
    }

    if (!items || items.length === 0) {
      return successResponse([]);
    }

    // Get unique provider IDs
    const providerIds = Array.from(new Set(items.map((item: any) => item.item_id)));
    
    console.log("Wishlist providers API - Found items:", {
      totalItems: items.length,
      uniqueProviderIds: providerIds.length,
      providerIds: providerIds.slice(0, 5),
    });

    if (providerIds.length === 0) {
      return successResponse([]);
    }

    // Fetch provider data (use rating_average, not rating)
    const { data: providers, error: providersError } = await (supabase.from("providers") as any)
      .select("id, slug, business_name, business_type, rating_average, review_count, thumbnail_url, avatar_url, description, status, is_featured, is_verified, currency")
      .in("id", providerIds);

    console.log("Wishlist providers API - Fetched providers:", {
      count: providers?.length || 0,
      providers: providers?.slice(0, 2).map((p: any) => ({
        id: p.id,
        business_name: p.business_name,
        rating_average: p.rating_average,
        review_count: p.review_count,
      })),
    });

    if (providersError) {
      console.error("Error fetching providers:", {
        error: providersError,
        message: providersError.message,
        code: providersError.code,
        details: providersError.details,
        providerIds: providerIds.slice(0, 5), // Log first 5 IDs
      });
      // Return empty array instead of throwing to prevent page breakage
      return successResponse([]);
    }

    if (!providers || providers.length === 0) {
      return successResponse([]);
    }

    // Fetch locations for all providers (include location_type for salon vs base)
    const { data: locations, error: locationsError } = await supabase
      .from("provider_locations")
      .select("provider_id, city, country, is_primary, location_type")
      .in("provider_id", providerIds)
      .eq("is_active", true)
      .order("is_primary", { ascending: false });

    if (locationsError) {
      console.error("Error fetching locations:", locationsError);
    }

    // Create location map (prefer primary location)
    const locationMap = new Map<string, { city: string; country: string }>();
    if (locations) {
      locations.forEach((loc: any) => {
        if (!locationMap.has(loc.provider_id)) {
          locationMap.set(loc.provider_id, {
            city: loc.city || "",
            country: loc.country || "",
          });
        }
      });
    }

    // Fetch minimum prices from offerings
    const { data: offerings, error: offeringsError } = await supabase
      .from("offerings")
      .select("provider_id, price, currency, service:services(supports_at_home)")
      .in("provider_id", providerIds)
      .eq("is_active", true)
      .not("price", "is", null)
      .gt("price", 0)
      .order("price", { ascending: true });

    if (offeringsError) {
      console.error("Error fetching offerings:", offeringsError);
    }

    // Also fetch prices from services as fallback
    const { data: services, error: servicesError } = await supabase
      .from("services")
      .select("provider_id, price, currency, supports_at_home")
      .in("provider_id", providerIds)
      .eq("is_active", true)
      .not("price", "is", null)
      .gt("price", 0)
      .order("price", { ascending: true });

    if (servicesError) {
      console.error("Error fetching services:", servicesError);
    }

    // Create price map and service type map
    const priceMap = new Map<string, { price: number; currency: string }>();
    const serviceTypeMap = new Map<string, { supports_house_calls: boolean; supports_salon: boolean }>();

    // Process offerings first (preferred source)
    if (offerings && offerings.length > 0) {
      offerings.forEach((offering: any) => {
        if (offering.price != null && offering.price > 0) {
          const existing = priceMap.get(offering.provider_id);
          if (!existing || Number(offering.price) < existing.price) {
            priceMap.set(offering.provider_id, {
              price: Number(offering.price),
              currency: offering.currency || "ZAR",
            });
          }
        }
        const serviceType = serviceTypeMap.get(offering.provider_id) || { supports_house_calls: false, supports_salon: false };
        if (offering.service?.supports_at_home) {
          serviceType.supports_house_calls = true;
        }
        serviceType.supports_salon = true; // If provider has offerings, they support salon
        serviceTypeMap.set(offering.provider_id, serviceType);
      });
    }

    // Process services as fallback
    if (services && services.length > 0) {
      services.forEach((service: any) => {
        if (service.price != null && service.price > 0) {
          const existing = priceMap.get(service.provider_id);
          const servicePrice = Number(service.price);
          if (!existing || servicePrice < existing.price) {
            priceMap.set(service.provider_id, {
              price: servicePrice,
              currency: service.currency || "ZAR",
            });
          }
        }
        const serviceType = serviceTypeMap.get(service.provider_id) || { supports_house_calls: false, supports_salon: false };
        if (service.supports_at_home) {
          serviceType.supports_house_calls = true;
        }
        serviceType.supports_salon = true;
        serviceTypeMap.set(service.provider_id, serviceType);
      });
    }

    // Salon support only from locations with location_type = 'salon' (base = distance-only)
    if (locations && locations.length > 0) {
      locations.forEach((loc: any) => {
        if ((loc.location_type || "salon") !== "salon") return;
        const serviceType = serviceTypeMap.get(loc.provider_id) || { supports_house_calls: false, supports_salon: false };
        serviceType.supports_salon = true;
        serviceTypeMap.set(loc.provider_id, serviceType);
      });
    }

    // Create a map of provider_id -> created_at (when it was added to wishlist)
    const addedAtMap = new Map(items.map((item: any) => [item.item_id, item.created_at]));

    // Combine providers with all additional data, maintaining order
    // Map to PublicProviderCard structure (rating_average -> rating)
    const providersWithAddedAt = (providers || [])
      .map((p: any) => {
        const location = locationMap.get(p.id);
        const priceInfo = priceMap.get(p.id);
        const serviceType = serviceTypeMap.get(p.id) || { supports_house_calls: false, supports_salon: false };

        // Map to PublicProviderCard structure
        const mapped: any = {
          id: p.id,
          slug: p.slug || "",
          business_name: p.business_name || "",
          business_type: p.business_type || "salon",
          rating: p.rating_average || 0, // Map rating_average to rating
          review_count: p.review_count || 0,
          thumbnail_url: p.thumbnail_url || null,
          avatar_url: p.avatar_url ?? null,
          city: location?.city || "",
          country: location?.country || "",
          is_featured: p.is_featured || false,
          is_verified: p.is_verified || false,
          starting_price: priceInfo?.price,
          currency: priceInfo?.currency || p.currency || "ZAR",
          description: p.description || null,
          supports_house_calls: Boolean(serviceType.supports_house_calls),
          supports_salon: Boolean(serviceType.supports_salon),
          // Keep added_at for sorting, but it's not part of PublicProviderCard
          added_at: addedAtMap.get(p.id) || new Date().toISOString(),
        };
        return mapped;
      })
      .sort((a: any, b: any) => {
        const aTime = new Date(a.added_at).getTime();
        const bTime = new Date(b.added_at).getTime();
        return bTime - aTime; // Most recently added first
      });

    console.log("Wishlist providers API - Returning providers:", {
      count: providersWithAddedAt.length,
      sample: providersWithAddedAt.slice(0, 1).map((p: any) => ({
        id: p.id,
        business_name: p.business_name,
        hasAllFields: !!(p.id && p.slug && p.business_name),
      })),
    });

    return successResponse(providersWithAddedAt);
  } catch (error) {
    console.error("Unexpected error in GET /api/me/wishlists/providers:", error);
    // Return empty array instead of error to prevent page breakage
    return successResponse([]);
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { z } from "zod";

const createSchema = z.object({
  name: z.string().min(1, "Name is required").max(80, "Name is too long"),
  is_public: z.boolean().optional(),
});

async function ensureDefaultWishlist(userId: string) {
  const supabase = await getSupabaseServer();

  const { data: existing, error: listError } = await (supabase.from("wishlists") as any)
    .select("id")
    .eq("user_id", userId)
    .eq("is_default", true)
    .limit(1);

  if (listError) throw listError;
  if (existing && existing.length > 0) return existing[0].id as string;

  const { data: created, error: createError } = await (supabase.from("wishlists") as any)
    .insert({
      user_id: userId,
      name: "Favorites",
      is_default: true,
      is_public: false,
    })
    .select("id")
    .single();

  if (createError) throw createError;
  return created.id as string;
}

/**
 * GET /api/me/wishlists
 *
 * Lists the current user's wishlists with item counts and simple cover images.
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer();

    // Ensure default wishlist exists
    try {
      await ensureDefaultWishlist(user.id);
    } catch (ensureError) {
      console.error("Error ensuring default wishlist:", ensureError);
      // Continue even if default wishlist creation fails
    }

    const { data: wishlists, error: wishlistError } = await (supabase.from("wishlists") as any)
      .select("id, name, is_default, is_public, created_at, updated_at")
      .eq("user_id", user.id)
      .order("is_default", { ascending: false })
      .order("updated_at", { ascending: false });

    if (wishlistError) {
      console.error("Error fetching wishlists:", wishlistError);
      throw wishlistError;
    }

    const wishlistIds = (wishlists || []).map((w: any) => w.id);
    if (wishlistIds.length === 0) return successResponse([]);

    const { data: items, error: itemsError } = await (supabase.from("wishlist_items") as any)
      .select("wishlist_id, item_type, item_id, created_at")
      .in("wishlist_id", wishlistIds)
      .order("created_at", { ascending: false });

    if (itemsError) {
      console.error("Error fetching wishlist items:", itemsError);
      throw itemsError;
    }

    const itemsByWishlist = new Map<string, any[]>();
    for (const item of items || []) {
      const key = item.wishlist_id as string;
      if (!itemsByWishlist.has(key)) itemsByWishlist.set(key, []);
      itemsByWishlist.get(key)!.push(item);
    }

    const providerItemIds = Array.from(
      new Set((items || []).filter((i: any) => i.item_type === "provider").map((i: any) => i.item_id))
    );

    const providerThumbs = new Map<string, string>();
    if (providerItemIds.length > 0) {
      try {
        const { data: providers, error: provError } = await (supabase.from("providers") as any)
          .select("id, thumbnail_url")
          .in("id", providerItemIds);
        if (provError) {
          console.error("Error fetching provider thumbnails:", provError);
          // Continue without thumbnails if this fails
        } else {
          for (const p of providers || []) {
            if (p?.thumbnail_url) providerThumbs.set(p.id, p.thumbnail_url);
          }
        }
      } catch (thumbError) {
        console.error("Error fetching provider thumbnails:", thumbError);
        // Continue without thumbnails
      }
    }

    const response = (wishlists || []).map((w: any) => {
      const wlItems = itemsByWishlist.get(w.id) || [];
      const providerCoverImages: string[] = [];
      for (const i of wlItems) {
        if (i.item_type !== "provider") continue;
        const url = providerThumbs.get(i.item_id);
        if (url) providerCoverImages.push(url);
        if (providerCoverImages.length >= 4) break;
      }
      return {
        ...w,
        item_count: wlItems.length,
        cover_images: providerCoverImages,
      };
    });

    return successResponse(response);
  } catch (error) {
    return handleApiError(error, "Failed to load wishlists");
  }
}

/**
 * POST /api/me/wishlists
 *
 * Creates a new wishlist for the current user.
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer();

    const body = createSchema.parse(await request.json());

    const { data: created, error } = await (supabase.from("wishlists") as any)
      .insert({
        user_id: user.id,
        name: body.name,
        is_default: false,
        is_public: body.is_public ?? false,
      })
      .select("id, name, is_default, is_public, created_at, updated_at")
      .single();

    if (error) throw error;
    return successResponse(created, 201);
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(new Error(error.issues.map((e) => e.message).join(", ")), "Validation failed");
    }
    return handleApiError(error, "Failed to create wishlist");
  }
}

