const toggleSchema = z.object({
  wishlist_id: z.string().uuid().optional(),
  item_type: z.enum(["provider", "offering", "package"]),
  item_id: z.string().uuid(),
});

async function getOrCreateDefaultWishlistId(userId: string): Promise<string> {
