/**
 * POST /api/me/wishlists/toggle
 *
 * Adds/removes an item from a wishlist. If wishlist_id not provided, uses default wishlist.
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["customer", "provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer();

    const body = toggleSchema.parse(await request.json());

    const wishlistId = body.wishlist_id || (await getOrCreateDefaultWishlistId(user.id));

    // Ensure wishlist belongs to user
    const { data: wishlist, error: wlError } = await (supabase.from("wishlists") as any)
      .select("id")
      .eq("id", wishlistId)
      .eq("user_id", user.id)
      .single();
    if (wlError || !wishlist) {
      return successResponse({ success: false, message: "Wishlist not found" }, 404);
    }

    const { data: existing, error: existingError } = await (supabase.from("wishlist_items") as any)
      .select("id")
      .eq("wishlist_id", wishlistId)
      .eq("item_type", body.item_type)
      .eq("item_id", body.item_id)
      .maybeSingle();

    if (existingError && existingError.code !== "PGRST116") {
      // PGRST116: "Results contain 0 rows" for maybeSingle in some setups
      throw existingError;
    }

    if (existing?.id) {
      const { error: delError } = await (supabase.from("wishlist_items") as any)
        .delete()
        .eq("id", existing.id)
        .eq("wishlist_id", wishlistId);
      if (delError) throw delError;
      return successResponse({ success: true, action: "removed", wishlist_id: wishlistId });
    }

    const { error: insError } = await (supabase.from("wishlist_items") as any).insert({
      wishlist_id: wishlistId,
      item_type: body.item_type,
      item_id: body.item_id,
    });
    if (insError) throw insError;

    return successResponse({ success: true, action: "added", wishlist_id: wishlistId });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(new Error(error.issues.map((e) => e.message).join(", ")), "Validation failed");
    }
    return handleApiError(error, "Failed to toggle wishlist item");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { chargeAuthorization, convertToSmallestUnit } from "@/lib/payments/paystack-complete";
import { z } from "zod";

const chargeSavedCardSchema = z.object({
  payment_method_id: z.string().uuid(),
  amount: z.number().positive(),
  currency: z.string().optional().default("ZAR"),
  email: z.string().email(),
  metadata: z.record(z.string(), z.any()).optional(),
});

/**
 * POST /api/payments/charge-saved-card
 * 
 * Charge a saved Paystack card using authorization code
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['customer', 'provider_owner', 'provider_staff', 'superadmin']);

    const body = chargeSavedCardSchema.parse(await request.json());

    const supabase = await getSupabaseServer();

    // Get the payment method
    const { data: paymentMethod, error: pmError } = await (supabase
      .from("payment_methods") as any)
      .select("*")
      .eq("id", body.payment_method_id)
      .eq("user_id", user.id)
      .eq("is_active", true)
      .eq("provider", "paystack")
      .single();

    if (pmError || !paymentMethod) {
      return handleApiError(
        new Error("Payment method not found or invalid"),
        "Payment method not found",
        "NOT_FOUND",
        404
      );
    }

    // Verify the payment method belongs to the user
    if (paymentMethod.user_id !== user.id) {
      return handleApiError(
        new Error("Unauthorized"),
        "You don't have permission to use this payment method",
        "UNAUTHORIZED",
        403
      );
    }

    // Get authorization code
    const authorizationCode = paymentMethod.provider_payment_method_id;

    if (!authorizationCode || !authorizationCode.startsWith("AUTH_")) {
      return handleApiError(
        new Error("Invalid payment method"),
        "This payment method is not a valid Paystack authorization",
        "INVALID_METHOD",
        400
      );
    }

    // Charge the card
    const amountInSmallestUnit = convertToSmallestUnit(body.amount);

    const chargeResult = await chargeAuthorization(
      authorizationCode,
      body.email,
      amountInSmallestUnit,
      {
        ...body.metadata,
        payment_method_id: body.payment_method_id,
        user_id: user.id,
      }
    );

    if (!chargeResult.status) {
      return handleApiError(
        new Error(chargeResult.message || "Charge failed"),
        "Failed to charge card",
        "CHARGE_FAILED",
        400
      );
    }

    return successResponse({
      transaction: chargeResult.data,
      reference: chargeResult.data.reference,
      status: chargeResult.data.status,
      message: chargeResult.message,
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        new Error(error.issues.map((e) => e.message).join(", ")),
        "Validation failed",
        "VALIDATION_ERROR",
        400
      );
    }
    return handleApiError(error, "Failed to charge saved card");
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole, unauthorizedResponse } from "@/lib/auth/requireRole";
import {
  convertToSmallestUnit,
  validateAmount,
  generateTransactionReference,
} from "@/lib/payments/paystack";
import { initializePaystackTransaction } from "@/lib/payments/paystack-server";

/**
 * POST /api/payments/initialize
 * 
 * Initialize Paystack payment for a booking
 */
export async function POST(request: Request) {
  try {
    const auth = await requireRole(["customer"]);
    if (!auth) {
      return unauthorizedResponse("Authentication required");
    }

    const supabase = await getSupabaseServer();
    const body = await request.json();
    const { booking_id, amount, currency, email, callback_url, metadata: clientMetadata } = body;
    const saveCard = clientMetadata?.save_card === true;
    const setAsDefault = clientMetadata?.set_as_default === true;

    if (!booking_id || !amount || !email) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "booking_id, amount, and email are required",
            code: "VALIDATION_ERROR",
          },
        },
        { status: 400 }
      );
    }

    // Verify booking belongs to user
    const { data: booking } = await supabase
      .from("bookings")
      .select("id, customer_id, total_amount, status")
      .eq("id", booking_id)
      .eq("customer_id", auth.user.id)
      .single();

    if (!booking) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Booking not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    const bookingData = booking as any;

    if (bookingData.status !== "pending") {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Booking is not in pending status",
            code: "INVALID_STATUS",
          },
        },
        { status: 400 }
      );
    }

    // Validate amount
    const amountValidation = validateAmount(parseFloat(amount));
    if (!amountValidation.valid) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: amountValidation.error || "Invalid amount",
            code: "INVALID_AMOUNT",
          },
        },
        { status: 400 }
      );
    }

    // Convert amount to smallest currency unit (kobo/cents)
    const amountInSmallestUnit = convertToSmallestUnit(parseFloat(amount));
    const transactionReference = generateTransactionReference("booking", booking_id);

    // Get platform settings for split code (transaction split for commission)
    const { data: platformSettings } = await (supabase
      .from("platform_settings") as any)
      .select("settings")
      .single();

    const payoutSettings = platformSettings?.settings?.payouts;
    let splitCode: string | undefined;

    // Get active split code if transaction splits are configured
    if (payoutSettings?.use_transaction_splits) {
      const { data: activeSplit } = await (supabase
        .from("paystack_splits") as any)
        .select("split_code")
        .eq("active", true)
        .eq("currency", currency || "ZAR")
        .single();

      if (activeSplit) {
        splitCode = activeSplit.split_code;
      }
    }

    // Get provider subaccount if provider-specific split is needed
    const { data: bookingDetails } = await (supabase
      .from("bookings") as any)
      .select("provider_id")
      .eq("id", booking_id)
      .single();

    let subaccount: string | undefined;
    if (bookingDetails?.provider_id) {
      const { data: providerSubaccount } = await (supabase
        .from("provider_paystack_subaccounts") as any)
        .select("subaccount_code")
        .eq("provider_id", bookingDetails.provider_id)
        .eq("active", true)
        .single();

      if (providerSubaccount) {
        subaccount = providerSubaccount.subaccount_code;
      }
    }

    // Initialize transaction with split if configured
    const paystackData = await initializePaystackTransaction({
      email,
      amountInSmallestUnit,
      currency: currency || "ZAR",
      reference: transactionReference,
      callback_url: callback_url || `${process.env.NEXT_PUBLIC_APP_URL || ""}/checkout/success`,
      metadata: {
        booking_id,
        customer_id: auth.user.id,
        save_card: saveCard,
        set_as_default: setAsDefault,
        custom_fields: [
          {
            display_name: "Booking ID",
            variable_name: "booking_id",
            value: booking_id,
          },
        ],
      },
      ...(splitCode ? { split_code: splitCode } : {}),
      ...(subaccount ? { subaccount } : {}),
    });

    // Store payment reference in booking
    await (supabase
      .from("bookings") as any)
      .update({
        payment_reference: paystackData.data.reference,
        payment_status: "pending",
      })
      .eq("id", booking_id);

    return NextResponse.json({
      data: {
        authorization_url: paystackData.data.authorization_url,
        access_code: paystackData.data.access_code,
        reference: paystackData.data.reference,
      },
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/payments/initialize:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to initialize payment",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

/**
 * Charge Event Handlers
 *
 * Handles charge.success and charge.failed Paystack webhook events including:
 *   - Standard booking payments
 *   - Custom offer payments
 *   - Wallet top-ups
 *   - Gift card orders
 *   - Membership orders
 *   - Provider subscription orders (one-time & authorization)
 *   - Additional charges on existing bookings
 */
import { NextResponse } from "next/server";
import { convertFromSmallestUnit } from "@/lib/payments/paystack";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { trackServer } from "@/lib/analytics/amplitude/server";
import { EVENT_PAYMENT_SUCCESS, EVENT_PAYMENT_FAILED } from "@/lib/analytics/amplitude/types";
import type { PaystackEvent, SupabaseClient } from "./shared";
import { savePaystackAuthorization, generateGiftCardCode } from "./shared";

// ΓöÇΓöÇΓöÇ Exported Handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Handle charge.success events ΓÇö booking fulfilment, card saving, ledger entries
 */
export async function handleChargeSuccess(
  event: PaystackEvent,
  supabase: SupabaseClient,
): Promise<NextResponse> {
  await processSuccessfulPayment(event.data, supabase);
  return NextResponse.json({ received: true });
}

/**
 * Handle charge.failed events ΓÇö mark bookings failed, void gift-card holds, etc.
 */
export async function handleChargeFailed(
  event: PaystackEvent,
  supabase: SupabaseClient,
): Promise<NextResponse> {
  await processFailedPayment(event.data, supabase);
  return NextResponse.json({ received: true });
}

// ΓöÇΓöÇΓöÇ charge.success internals ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

async function processSuccessfulPayment(data: any, supabase: SupabaseClient) {
  const { reference, metadata, amount, fees, customer, authorization } = data;

  if (!reference || !metadata?.booking_id) {
    // Non-booking flows (gift cards, subscriptions, etc.)
    if (metadata?.custom_offer_id) {
      await handleCustomOfferSuccess({ reference, metadata, amount, fees, customer }, supabase);
      return;
    }
    if (metadata?.wallet_topup_id) {
      await handleWalletTopupSuccess({ reference, metadata, amount }, supabase);
      return;
    }
    if (metadata?.gift_card_order_id) {
      await handleGiftCardOrderSuccess({ reference, metadata, amount }, supabase);
      return;
    }
    if (metadata?.membership_order_id) {
      await handleMembershipOrderSuccess({ reference, metadata }, supabase);
      return;
    }
    if (metadata?.provider_subscription_order_id) {
      if (metadata?.kind === "subscription_authorization") {
        await handleSubscriptionAuthorizationSuccess(
          { reference, metadata, amount, fees, customer, authorization: data.authorization },
          supabase,
        );
      } else {
        await handleProviderSubscriptionOrderSuccess(
          { reference, metadata, amount, fees, customer },
          supabase,
        );
      }
      return;
    }
    if (metadata?.ads_budget_order_id) {
      await handleAdsBudgetOrderSuccess({ reference, metadata, amount, fees }, supabase);
      return;
    }
    console.error("Missing reference or booking_id in payment data");
    return;
  }

  // Additional charge payment flow
  if (metadata?.additional_charge_id) {
    await handleAdditionalChargeSuccess({ reference, metadata, amount, fees, customer }, supabase);
    return;
  }

  // ΓöÇΓöÇ Standard booking payment ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const { data: booking, error: bookingError } = await supabase
    .from("bookings")
    .select("*")
    .eq("id", metadata.booking_id)
    .single();

  if (bookingError || !booking) {
    console.error("Booking not found:", metadata.booking_id);
    return;
  }

  const bookingData = booking as any;

  // Check if already processed
  if (bookingData.payment_status === "paid" && bookingData.payment_reference === reference) {
    console.log(`Payment ${reference} already processed`);
    return;
  }

  // Calculate amounts (Paystack amounts are in smallest currency unit)
  const amountInCurrency = convertFromSmallestUnit(amount || 0);
  const feesInCurrency = convertFromSmallestUnit(fees || 0);
  const netAmount = amountInCurrency - feesInCurrency;

  // Tip/Tax/Travel fees/Service fee are excluded from commission
  const tipAmount = Number(metadata?.tip_amount ?? bookingData.tip_amount ?? 0);
  const taxAmount = Number(metadata?.tax_amount ?? bookingData.tax_amount ?? 0);
  const travelFee = Number(metadata?.travel_fee ?? bookingData.travel_fee ?? 0);
  const serviceFeeAmount = Number(
    metadata?.service_fee_amount ??
      bookingData.service_fee_amount ??
      bookingData.platform_service_fee ??
      0,
  );
  const commissionBase = Number(
    metadata?.commission_base ??
      Number(bookingData.total_amount || 0) - tipAmount - taxAmount - travelFee - serviceFeeAmount,
  );

  // Get platform commission settings
  const { data: settingsRow } = await (supabase.from("platform_settings") as any)
    .select("settings")
    .eq("is_active", true)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  const payoutSettings = (settingsRow as any)?.settings?.payouts || {};
  const commissionEnabled = payoutSettings.commission_enabled !== false;
  const commissionRate = commissionEnabled
    ? (payoutSettings.platform_commission_percentage ?? 0)
    : 0;

  const platformCommission =
    commissionEnabled && commissionRate > 0 ? (commissionBase * commissionRate) / 100 : 0;

  const providerEarnings = commissionBase - platformCommission + travelFee + tipAmount;

  // Update booking payment status
  const { error: updateError } = await (supabase.from("bookings") as any)
    .update({
      payment_status: "paid",
      payment_reference: reference,
      payment_date: new Date().toISOString(),
      payment_provider: "paystack",
      status: "confirmed",
    })
    .eq("id", metadata.booking_id);

  if (updateError) {
    console.error("Error updating booking payment status:", updateError);
    throw updateError;
  }

  // Gift cards: capture reserved redemption
  try {
    const captureResult = await (supabase.rpc as any)("capture_gift_card_redemption", {
      p_booking_id: metadata.booking_id,
    });

    if (captureResult === false || captureResult === null) {
      console.warn(
        `Gift card redemption capture failed for booking ${metadata.booking_id}. Check if gift card expired.`,
      );
    }
  } catch (gcError: any) {
    const errorMessage = gcError?.message || String(gcError);

    if (errorMessage.includes("expired") || errorMessage.includes("no longer active")) {
      console.warn(
        `Gift card expired for booking ${metadata.booking_id}. Redemption voided:`,
        errorMessage,
      );

      await (supabase.from("bookings") as any)
        .update({
          gift_card_id: null,
          gift_card_amount: 0,
        })
        .eq("id", metadata.booking_id);
    } else {
      console.error("Error capturing gift card redemption:", gcError);
    }
  }

  // Loyalty points: deduct if used (idempotent; same as verify so only one path applies)
  const loyaltyPointsUsed = Number(
    metadata?.loyalty_points_used ?? bookingData?.loyalty_points_used ?? 0
  );
  if (loyaltyPointsUsed > 0 && (metadata?.customer_id || bookingData?.customer_id)) {
    const customerId = metadata?.customer_id || bookingData?.customer_id;
    try {
      const { data: existingRedeem } = await (supabase.from("loyalty_point_transactions") as any)
        .select("id")
        .eq("user_id", customerId)
        .eq("reference_id", metadata.booking_id)
        .eq("reference_type", "booking")
        .eq("transaction_type", "redeemed")
        .maybeSingle();
      if (!existingRedeem) {
        await (supabase.from("loyalty_point_transactions") as any).insert({
          user_id: customerId,
          points: loyaltyPointsUsed,
          transaction_type: "redeemed",
          description: `Redeemed for booking ${bookingData?.booking_number || metadata.booking_id}`,
          reference_id: metadata.booking_id,
          reference_type: "booking",
        });
        await (supabase.from("bookings") as any)
          .update({ loyalty_points_used: loyaltyPointsUsed })
          .eq("id", metadata.booking_id);
      }
    } catch (loyaltyErr: any) {
      console.error("Loyalty points deduction failed:", loyaltyErr?.message || loyaltyErr);
    }
  }

  // Save card if requested and authorization is reusable
  if (
    metadata?.save_card &&
    authorization?.authorization_code &&
    authorization?.reusable &&
    customer?.email &&
    metadata?.customer_id
  ) {
    try {
      await savePaystackAuthorization({
        userId: metadata.customer_id,
        email: customer.email,
        authorizationCode: authorization.authorization_code,
        lastFour: authorization.last4,
        expiryMonth: parseInt(authorization.exp_month || "0"),
        expiryYear: parseInt(authorization.exp_year || "0"),
        cardBrand: authorization.brand || authorization.card_type || "unknown",
        isDefault: metadata.set_as_default === true,
        supabase,
      });
    } catch (saveError) {
      console.error("Error saving payment method:", saveError);
    }
  }

  // Create payment transaction record
  await (supabase.from("payment_transactions") as any).insert({
    booking_id: metadata.booking_id,
    reference,
    amount: amountInCurrency,
    fees: feesInCurrency,
    net_amount: netAmount,
    status: "success",
    provider: "paystack",
    metadata: {
      paystack_reference: reference,
      customer_email: customer?.email,
      customer_code: customer?.customer_code,
    },
    created_at: new Date().toISOString(),
  });

  // Update primary payments table
  await (supabase.from("payments") as any)
    .update({
      status: "paid",
      payment_provider: "paystack",
      payment_provider_transaction_id: reference,
      processed_at: new Date().toISOString(),
      payment_provider_response: data,
    })
    .eq("booking_id", metadata.booking_id)
    .eq("payment_provider", "paystack");

  // Create finance ledger entries ΓÇö platform fee
  await (supabase.from("finance_transactions") as any).insert({
    booking_id: metadata.booking_id,
    provider_id: bookingData.provider_id || null,
    transaction_type: "payment",
    amount: commissionBase,
    fees: feesInCurrency,
    commission: platformCommission,
    net: platformCommission,
    description: `Payment for booking ${bookingData.booking_number}`,
    created_at: new Date().toISOString(),
  });

  // Provider earnings entry
  await (supabase.from("finance_transactions") as any).insert({
    booking_id: metadata.booking_id,
    provider_id: bookingData.provider_id || null,
    transaction_type: "provider_earnings",
    amount: providerEarnings,
    fees: 0,
    commission: 0,
    net: providerEarnings,
    description: `Provider earnings for booking ${bookingData.booking_number}`,
    created_at: new Date().toISOString(),
  });

  // Platform service fee entry
  if (serviceFeeAmount > 0) {
    await (supabase.from("finance_transactions") as any).insert({
      booking_id: metadata.booking_id,
      provider_id: bookingData.provider_id || null,
      transaction_type: "service_fee",
      amount: serviceFeeAmount,
      fees: 0,
      commission: 0,
      net: serviceFeeAmount,
      description: `Service fee for booking ${bookingData.booking_number}`,
      created_at: new Date().toISOString(),
    });
  }

  // Tip / Tax / Travel fee reporting rows
  await (supabase.from("finance_transactions") as any).insert([
    {
      booking_id: metadata.booking_id,
      provider_id: bookingData.provider_id || null,
      transaction_type: "tip",
      amount: tipAmount,
      fees: 0,
      commission: 0,
      net: 0,
      description: `Tip for booking ${bookingData.booking_number}`,
      created_at: new Date().toISOString(),
    },
    {
      booking_id: metadata.booking_id,
      provider_id: bookingData.provider_id || null,
      transaction_type: "tax",
      amount: taxAmount,
      fees: 0,
      commission: 0,
      net: 0,
      description: `Tax for booking ${bookingData.booking_number}`,
      created_at: new Date().toISOString(),
    },
    ...(travelFee > 0
      ? [
          {
            booking_id: metadata.booking_id,
            provider_id: bookingData.provider_id || null,
            transaction_type: "travel_fee",
            amount: travelFee,
            fees: 0,
            commission: 0,
            net: 0,
            description: `Travel fee for booking ${bookingData.booking_number}`,
            created_at: new Date().toISOString(),
          },
        ]
      : []),
  ]);

  // Promotions: record usage (idempotent)
  try {
    const promoId = bookingData.promotion_id;
    const promoDiscount = Number(bookingData.promotion_discount_amount || 0);
    if (promoId && promoDiscount > 0) {
      const { data: usageRow, error: usageError } = await (
        supabase.from("promotion_usage") as any
      )
        .insert({
          promotion_id: promoId,
          user_id: bookingData.customer_id,
          booking_id: metadata.booking_id,
          discount_amount: promoDiscount,
          used_at: new Date().toISOString(),
        })
        .select("id")
        .single();

      if (!usageError && usageRow?.id) {
        const { data: promoRow } = await (supabase.from("promotions") as any)
          .select("usage_count")
          .eq("id", promoId)
          .single();
        const nextCount = Number(promoRow?.usage_count || 0) + 1;
        await (supabase.from("promotions") as any)
          .update({ usage_count: nextCount })
          .eq("id", promoId);
      }
    }
  } catch (promoError) {
    const msg = promoError instanceof Error ? promoError.message : String(promoError);
    if (!msg.toLowerCase().includes("duplicate") && !msg.toLowerCase().includes("unique")) {
      console.error("Error recording promotion usage:", promoError);
    }
  }

  // Send OneSignal notifications
  try {
    const { sendToUser } = await import("@/lib/notifications/onesignal");

    await sendToUser(bookingData.customer_id, {
      title: "Payment Confirmed",
      message: `Your payment for booking ${bookingData.booking_number} has been confirmed.`,
      data: {
        type: "payment_success",
        booking_id: metadata.booking_id,
      },
      url: `/account-settings/bookings`,
    });

    const { data: providerRow } = await supabase
      .from("providers")
      .select("user_id")
      .eq("id", bookingData.provider_id)
      .single();

    const providerUserId = (providerRow as any)?.user_id;
    if (providerUserId) {
      await sendToUser(providerUserId, {
        title: "New Booking Payment",
        message: `Payment received for booking ${bookingData.booking_number}.`,
        data: {
          type: "booking_payment",
          booking_id: metadata.booking_id,
        },
        url: `/provider/bookings/${metadata.booking_id}`,
      });
    }
  } catch (notifError) {
    console.error("Error sending notifications:", notifError);
  }

  // Track Amplitude event
  try {
    await trackServer(
      EVENT_PAYMENT_SUCCESS,
      {
        portal: "client",
        booking_id: metadata.booking_id,
        amount: amountInCurrency,
        currency: metadata?.currency || bookingData.currency || "ZAR",
        payment_method: metadata?.save_card ? "saved_card" : "new_card",
        payment_provider: "paystack",
        transaction_id: reference,
      },
      bookingData.customer_id,
    );
  } catch (amplitudeError) {
    console.error("[Amplitude] Failed to track payment success:", amplitudeError);
  }

  console.log(`Booking ${metadata.booking_id} payment confirmed (${reference})`);
}

// ΓöÇΓöÇΓöÇ charge.failed internals ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

async function processFailedPayment(data: any, supabase: SupabaseClient) {
  const { reference, metadata, message, gateway_response } = data;

  if (!reference || !metadata?.booking_id) {
    if (metadata?.custom_offer_id) {
      await handleCustomOfferFailed({ reference, metadata, message, gateway_response }, supabase);
      return;
    }
    if (metadata?.wallet_topup_id) {
      await handleWalletTopupFailed({ reference, metadata, message, gateway_response }, supabase);
      return;
    }
    if (metadata?.gift_card_order_id) {
      await handleGiftCardOrderFailed({ reference, metadata, message }, supabase);
      return;
    }
    if (metadata?.membership_order_id) {
      await handleMembershipOrderFailed({ reference, metadata, message }, supabase);
      return;
    }
    if (metadata?.provider_subscription_order_id) {
      await handleProviderSubscriptionOrderFailed({ reference, metadata, message }, supabase);
      return;
    }
    if (metadata?.ads_budget_order_id) {
      await (supabase.from("ads_budget_orders") as any)
        .update({ status: "failed", updated_at: new Date().toISOString() })
        .eq("id", metadata.ads_budget_order_id);
      return;
    }
    console.error("Missing reference or booking_id in payment data");
    return;
  }

  // Additional charge failure flow
  if (metadata?.additional_charge_id) {
    await handleAdditionalChargeFailed(
      { reference, metadata, message, gateway_response },
      supabase,
    );
    return;
  }

  // ΓöÇΓöÇ Standard booking failure ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const { data: booking } = await supabase
    .from("bookings")
    .select("customer_id, booking_number")
    .eq("id", metadata.booking_id)
    .single();

  if (!booking) {
    console.error("Booking not found:", metadata.booking_id);
    return;
  }

  const bookingData = booking as any;

  // If wallet was used as partial payment, refund it immediately
  const walletAmountApplied = Number(metadata?.wallet_amount_applied ?? 0);
  if (walletAmountApplied > 0) {
    try {
      await (supabase.rpc as any)("wallet_credit_admin", {
        p_user_id: bookingData.customer_id,
        p_amount: walletAmountApplied,
        p_currency: metadata?.currency || "ZAR",
        p_description: `Wallet refund (payment failed) for booking ${bookingData.booking_number}`,
        p_reference_id: metadata.booking_id,
        p_reference_type: "booking_payment_failed",
      });

      await (supabase.from("bookings") as any)
        .update({ wallet_amount: 0 })
        .eq("id", metadata.booking_id);
    } catch (e) {
      console.error("Failed to refund wallet on charge.failed:", e);
    }
  }

  // Update booking payment status
  const { error: updateError } = await (supabase.from("bookings") as any)
    .update({
      payment_status: "failed",
      payment_reference: reference,
      payment_provider: "paystack",
    })
    .eq("id", metadata.booking_id);

  if (updateError) {
    console.error("Error updating booking payment status:", updateError);
    throw updateError;
  }

  // Gift cards: void reserved redemption and restore balance
  try {
    await (supabase.rpc as any)("void_gift_card_redemption", {
      p_booking_id: metadata.booking_id,
    });
  } catch (gcError) {
    console.error("Error voiding gift card redemption:", gcError);
  }

  // Create payment transaction record
  await (supabase.from("payment_transactions") as any).insert({
    booking_id: metadata.booking_id,
    reference,
    amount: 0,
    fees: 0,
    net_amount: 0,
    status: "failed",
    provider: "paystack",
    metadata: {
      paystack_reference: reference,
      failure_reason: message,
    },
    created_at: new Date().toISOString(),
  });

  await (supabase.from("payments") as any)
    .update({
      status: "failed",
      payment_provider: "paystack",
      payment_provider_transaction_id: reference,
      failed_at: new Date().toISOString(),
      failure_reason: message || gateway_response || "paystack_charge_failed",
      payment_provider_response: data,
    })
    .eq("booking_id", metadata.booking_id)
    .eq("payment_provider", "paystack");

  // Notify customer
  try {
    const { sendToUser } = await import("@/lib/notifications/onesignal");

    await sendToUser(bookingData.customer_id, {
      title: "Payment Failed",
      message: `Your payment for booking ${bookingData.booking_number} could not be processed. Please try again.`,
      data: {
        type: "payment_failed",
        booking_id: metadata.booking_id,
      },
      url: `/checkout`,
    });
  } catch (notifError) {
    console.error("Error sending notification:", notifError);
  }

  // Track Amplitude event
  try {
    const amt = Number(metadata?.amount_to_collect || 0);
    await trackServer(
      EVENT_PAYMENT_FAILED,
      {
        portal: "client",
        booking_id: metadata.booking_id,
        amount: amt,
        currency: metadata?.currency || "ZAR",
        payment_method: metadata?.save_card ? "saved_card" : "new_card",
        payment_provider: "paystack",
        error_code: message || gateway_response || "unknown",
      },
      bookingData.customer_id,
    );
  } catch (amplitudeError) {
    console.error("[Amplitude] Failed to track payment failed:", amplitudeError);
  }

  console.log(`Booking ${metadata.booking_id} payment failed (${reference})`);
}

// ΓöÇΓöÇΓöÇ Custom Offer ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

async function handleCustomOfferSuccess(
  payload: { reference: string; metadata: any; amount?: number; fees?: number; customer?: any },
  supabase: SupabaseClient,
) {
  const offerId = payload.metadata.custom_offer_id as string;
  if (!offerId) return;

  // Use admin client to bypass RLS (required for booking creation)
  const adminSupabase = getSupabaseAdmin();

  const { data: offerRow } = await adminSupabase
    .from("custom_offers")
    .select("*, request:custom_requests(*)")
    .eq("id", offerId)
    .single();
  if (!offerRow) return;
  const offer = offerRow as any;
  const req = offer.request as any;

  // Idempotency: if booking already created, just ensure status is paid
  if (offer.status === "paid" && offer.booking_id) return;

  const amountInCurrency = convertFromSmallestUnit(payload.amount || 0);
  const feesInCurrency = convertFromSmallestUnit(payload.fees || 0);
  const netAmount = amountInCurrency - feesInCurrency;

  const meta = payload.metadata || {};
  const travelFee = Number(meta.travel_fee ?? offer.travel_fee ?? 0) >= 0 ? Number(meta.travel_fee ?? offer.travel_fee ?? 0) : 0;
  const tipAmount = Number(meta.tip_amount ?? 0);
  const taxAmount = Number(meta.tax_amount ?? 0);
  const taxRate = Number(meta.tax_rate ?? 0);
  const serviceFeeAmount = Number(meta.service_fee_amount ?? 0);
  const serviceFeePercentage = Number(meta.service_fee_percentage ?? 0);
  const promotionDiscountAmount = Number(meta.promotion_discount_amount ?? 0);
  const promotionId = meta.promotion_id && String(meta.promotion_id).trim() ? meta.promotion_id : null;

  const offeringTitle = (req.service_name && String(req.service_name).trim()) ? String(req.service_name).trim() : "Custom Service";
  const { data: createdOffering, error: offeringError } = await adminSupabase
    .from("offerings")
    .insert({
      provider_id: req.provider_id,
      master_service_id: null,
      title: offeringTitle,
      description: req.description,
      category_id: req.service_category_id || null,
      subcategory_id: null,
      duration_minutes: offer.duration_minutes,
      buffer_minutes: 0,
      price: offer.price,
      currency: offer.currency || "ZAR",
      supports_at_home: req.location_type === "at_home",
      supports_at_salon: req.location_type === "at_salon",
      is_active: false,
      display_order: 0,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    })
    .select()
    .single();

  if (offeringError || !createdOffering) {
    console.error("Failed to create offering for custom offer:", offeringError);
    return;
  }

  // Create booking: use offer scheduled_at, then request preferred_start_at, else start of next hour (so it shows on calendar)
  let scheduledAt: string;
  if (offer.scheduled_at) {
    scheduledAt = new Date(offer.scheduled_at).toISOString();
  } else if (req.preferred_start_at) {
    scheduledAt = new Date(req.preferred_start_at).toISOString();
  } else {
    const nextHour = new Date(Date.now() + 60 * 60 * 1000);
    nextHour.setMinutes(0, 0, 0);
    scheduledAt = nextHour.toISOString();
  }
  const bookingSubtotal = Number(offer.price || 0);

  const bookingInsert: any = {
    booking_number: "",
    customer_id: req.customer_id,
    provider_id: req.provider_id,
    status: "confirmed",
    location_type: req.location_type || "at_salon",
    location_id: req.location_type === "at_salon" && offer.location_id ? offer.location_id : null,
    scheduled_at: scheduledAt,
    subtotal: bookingSubtotal,
    tip_amount: tipAmount,
    discount_amount: promotionDiscountAmount,
    tax_rate: taxRate,
    tax_amount: taxAmount,
    service_fee_percentage: 0,
    service_fee_amount: serviceFeeAmount,
    total_amount: amountInCurrency,
    currency: offer.currency || "ZAR",
    payment_status: "paid",
    payment_reference: payload.reference,
    payment_date: new Date().toISOString(),
    payment_provider: "paystack",
    special_requests: `Custom order: ${req.description}`,
    loyalty_points_earned: 0,
    loyalty_points_used: 0,
    promotion_id: promotionId,
    promotion_discount_amount: promotionDiscountAmount,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  if (req.location_type === "at_home" && (req.address_line1 || req.address_city || req.address_country)) {
    bookingInsert.address_line1 = req.address_line1 ?? null;
    bookingInsert.address_line2 = req.address_line2 ?? null;
    bookingInsert.address_city = req.address_city ?? null;
    bookingInsert.address_state = req.address_state ?? null;
    bookingInsert.address_country = req.address_country ?? null;
    bookingInsert.address_postal_code = req.address_postal_code ?? null;
  }
  if (travelFee > 0) {
    bookingInsert.travel_fee = travelFee;
  }

  const { data: booking, error: bookingError } = await adminSupabase
    .from("bookings")
    .insert(bookingInsert)
    .select()
    .single();

  if (bookingError || !booking) {
    console.error("Failed to create booking for custom offer:", bookingError);
    return;
  }

  // Booking service row
  const start = new Date(scheduledAt);
  const end = new Date(start.getTime() + Number(offer.duration_minutes || 60) * 60 * 1000);
  const assignedStaffId = offer.staff_id || null;

  const { error: bookingServiceError } = await adminSupabase
    .from("booking_services")
    .insert({
      booking_id: booking.id,
      offering_id: createdOffering.id,
      staff_id: assignedStaffId,
      duration_minutes: Number(offer.duration_minutes || 60),
      price: bookingSubtotal,
      currency: offer.currency || "ZAR",
      scheduled_start_at: start.toISOString(),
      scheduled_end_at: end.toISOString(),
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    });

  if (bookingServiceError) {
    console.error("Failed to create booking service for custom offer:", bookingServiceError);
  }

  // Update custom offer status and link booking
  await adminSupabase
    .from("custom_offers")
    .update({
      status: "paid",
      booking_id: booking.id,
      paid_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    })
    .eq("id", offerId);

  // Create payments row so booking has a consistent payment record (reports, portal)
  await (adminSupabase.from("payments") as any).insert({
    booking_id: booking.id,
    user_id: req.customer_id,
    provider_id: req.provider_id,
    payment_number: "",
    amount: amountInCurrency,
    currency: offer.currency || "ZAR",
    status: "paid",
    payment_provider: "paystack",
    payment_provider_transaction_id: payload.reference,
    payment_provider_response: {},
    processed_at: new Date().toISOString(),
    description: `Custom offer payment`,
    metadata: { custom_offer_id: offerId },
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  });

  // Commission + ledger entries (use metadata.commission_base when present for tax/fee-aware base)
  const { data: settingsRow } = await adminSupabase
    .from("platform_settings")
    .select("settings")
    .eq("is_active", true)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  const commissionRate =
    (settingsRow as any)?.settings?.payouts?.platform_commission_percentage ?? 15;
  const commissionBase = Number(meta.commission_base) > 0 ? Number(meta.commission_base) : Math.max(0, bookingSubtotal + travelFee - promotionDiscountAmount);
  const platformCommission = (commissionBase * commissionRate) / 100;
  const providerEarnings = commissionBase - platformCommission;

  await adminSupabase.from("payment_transactions").insert({
    booking_id: booking.id,
    reference: payload.reference,
    amount: amountInCurrency,
    fees: feesInCurrency,
    net_amount: netAmount,
    status: "success",
    provider: "paystack",
    metadata: { custom_offer_id: offerId, customer_email: payload.customer?.email },
    created_at: new Date().toISOString(),
  });

  await adminSupabase.from("finance_transactions").insert([
    {
      booking_id: booking.id,
      provider_id: req.provider_id,
      transaction_type: "payment",
      amount: commissionBase,
      fees: feesInCurrency,
      commission: platformCommission,
      net: platformCommission,
      description: `Custom order payment`,
      created_at: new Date().toISOString(),
    },
    {
      booking_id: booking.id,
      provider_id: req.provider_id,
      transaction_type: "provider_earnings",
      amount: providerEarnings,
      fees: 0,
      commission: 0,
      net: providerEarnings,
      description: `Provider earnings (custom order)`,
      created_at: new Date().toISOString(),
    },
  ]);

  // Service fee, tip, tax, travel fee ledger entries
  const extraRows: any[] = [];
  if (serviceFeeAmount > 0) {
    extraRows.push({
      booking_id: booking.id,
      provider_id: req.provider_id,
      transaction_type: "service_fee",
      amount: serviceFeeAmount,
      fees: 0,
      commission: 0,
      net: serviceFeeAmount,
      description: `Service fee (custom order)`,
      created_at: new Date().toISOString(),
    });
  }
  extraRows.push(
    {
      booking_id: booking.id,
      provider_id: req.provider_id,
      transaction_type: "tip",
      amount: tipAmount,
      fees: 0,
      commission: 0,
      net: 0,
      description: `Tip (custom order)`,
      created_at: new Date().toISOString(),
    },
    {
      booking_id: booking.id,
      provider_id: req.provider_id,
      transaction_type: "tax",
      amount: taxAmount,
      fees: 0,
      commission: 0,
      net: 0,
      description: `Tax (custom order)`,
      created_at: new Date().toISOString(),
    }
  );
  if (travelFee > 0) {
    extraRows.push({
      booking_id: booking.id,
      provider_id: req.provider_id,
      transaction_type: "travel_fee",
      amount: travelFee,
      fees: 0,
      commission: 0,
      net: 0,
      description: `Travel fee (custom order)`,
      created_at: new Date().toISOString(),
    });
  }
  if (extraRows.length > 0) {
    await adminSupabase.from("finance_transactions").insert(extraRows);
  }

  // Record promotion usage (idempotent)
  if (promotionId && promotionDiscountAmount > 0) {
    try {
      await (adminSupabase.from("promotion_usage") as any)
        .insert({
          promotion_id: promotionId,
          user_id: req.customer_id,
          booking_id: booking.id,
          discount_amount: promotionDiscountAmount,
          used_at: new Date().toISOString(),
        })
        .select("id")
        .single();
      const { data: promoRow } = await (adminSupabase.from("promotions") as any)
        .select("usage_count")
        .eq("id", promotionId)
        .single();
      const nextCount = Number(promoRow?.usage_count || 0) + 1;
      await (adminSupabase.from("promotions") as any)
        .update({ usage_count: nextCount })
        .eq("id", promotionId);
    } catch (promoErr: any) {
      const msg = promoErr?.message || String(promoErr);
      if (!msg.toLowerCase().includes("duplicate") && !msg.toLowerCase().includes("unique")) {
        console.error("Error recording custom offer promotion usage:", promoErr);
      }
    }
  }

  // Update custom request status to fulfilled
  await adminSupabase
    .from("custom_requests")
    .update({ status: "fulfilled", updated_at: new Date().toISOString() })
    .eq("id", req.id);

  // Post a "paid + booking created" message into conversation (best-effort)
  try {
    if (booking) {
      const { data: providerRow } = await adminSupabase
        .from("providers")
        .select("user_id")
        .eq("id", req.provider_id)
        .single();
      const providerUserId = (providerRow as any)?.user_id as string | undefined;

      const { data: conv } = await adminSupabase
        .from("conversations")
        .select("id, booking_id")
        .eq("customer_id", req.customer_id)
        .eq("provider_id", req.provider_id)
        .order("created_at", { ascending: true })
        .limit(1)
        .maybeSingle();

      const convId = (conv as any)?.id as string | undefined;
      if (convId) {
        if (!(conv as any)?.booking_id) {
          await adminSupabase
            .from("conversations")
            .update({ booking_id: booking.id, updated_at: new Date().toISOString() })
            .eq("id", convId);
        }

        if (providerUserId) {
          await adminSupabase.from("messages").insert({
            conversation_id: convId,
            sender_id: providerUserId,
            sender_role: "provider_owner",
            content: `Payment received ΓÇö booking created${booking.booking_number ? ` (#${booking.booking_number})` : ""}.`,
            attachments: [
              {
                type: "custom_offer_paid",
                offer_id: offerId,
                booking_id: booking.id,
                booking_number: booking.booking_number || null,
              },
            ],
            is_read: false,
            created_at: new Date().toISOString(),
          });
        }
      }
    }
  } catch {
    // ignore messaging failures
  }

  // Notify both parties (best-effort)
  try {
    const { sendToUsers } = await import("@/lib/notifications/onesignal");
    const { data: providerRow } = await supabase
      .from("providers")
      .select("user_id")
      .eq("id", req.provider_id)
      .single();
    const providerUserId = (providerRow as any)?.user_id;
    const recipients = [req.customer_id, providerUserId].filter(Boolean);
    if (recipients.length > 0) {
      await sendToUsers(recipients, {
        title: "Custom Order Paid",
        message: "Your custom order has been paid and a booking has been created.",
        data: {
          type: "custom_order_paid",
          custom_offer_id: offerId,
          booking_id: (booking as any)?.id,
        },
        url: "/account-settings/bookings",
      });
    }
  } catch {
    // ignore
  }
}

async function handleCustomOfferFailed(
  payload: { reference: string; metadata: any; message?: string; gateway_response?: string },
  supabase: SupabaseClient,
) {
  const offerId = payload.metadata.custom_offer_id as string;
