// ΓöÇΓöÇΓöÇ Subscription Authorization ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

async function handleSubscriptionAuthorizationSuccess(
  payload: {
    reference: string;
    metadata: any;
    amount: number;
    fees: number;
    customer: any;
    authorization?: any;
  },
  supabase: SupabaseClient,
) {
  const { reference, metadata, amount, fees, authorization } = payload;
  const orderId = metadata.provider_subscription_order_id as string;
  const providerId = metadata.provider_id as string;
  const planId = metadata.plan_id as string;
  const billingPeriod = (metadata.billing_period || "monthly") as "monthly" | "yearly";
  const customerCode = metadata.customer_code as string;

  if (!orderId || !providerId || !planId) {
    console.error("Missing required metadata for subscription authorization");
    return;
  }

  const authCode = authorization?.authorization_code;
  if (!authCode || !authorization?.reusable) {
    console.error("No reusable authorization code in payment response");
    return;
  }

  const amountInCurrency = convertFromSmallestUnit(amount || 0);
  const feesInCurrency = convertFromSmallestUnit(fees || 0);
  const netAmount = amountInCurrency - feesInCurrency;

  await (supabase.from("provider_subscription_orders") as any)
    .update({
      status: "paid",
      paystack_reference: reference,
      paid_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    })
    .eq("id", orderId);

  const { data: existingSub } = await supabase
    .from("provider_subscriptions")
    .select("id")
    .eq("provider_id", providerId)
    .single();

  if (existingSub) {
    await (supabase.from("provider_subscriptions") as any)
      .update({
        paystack_authorization_code: authCode,
        paystack_customer_code: customerCode,
        updated_at: new Date().toISOString(),
      })
      .eq("id", (existingSub as any).id);
  } else {
    await (supabase.from("provider_subscriptions") as any).insert({
      provider_id: providerId,
      plan_id: planId,
      status: "pending",
      billing_period: billingPeriod,
      auto_renew: false,
      paystack_authorization_code: authCode,
      paystack_customer_code: customerCode,
      updated_at: new Date().toISOString(),
    });
  }

  await (supabase.from("payment_transactions") as any).insert({
    booking_id: null,
    reference,
    amount: amountInCurrency,
    fees: feesInCurrency,
    net_amount: netAmount,
    status: "success",
    provider: "paystack",
    transaction_type: "charge",
    metadata: {
      kind: "subscription_authorization",
      provider_subscription_order_id: orderId,
      provider_id: providerId,
      plan_id: planId,
      authorization_code: authCode,
    },
    created_at: new Date().toISOString(),
  });

  // Now automatically create the Paystack subscription
  try {
    const { createSubscription } = await import("@/lib/payments/paystack-complete");
    const paystackPlanCode =
      billingPeriod === "yearly"
        ? (
            await supabase
              .from("subscription_plans")
              .select("paystack_plan_code_yearly")
              .eq("id", planId)
              .single()
          ).data?.paystack_plan_code_yearly
        : (
            await supabase
              .from("subscription_plans")
              .select("paystack_plan_code_monthly")
              .eq("id", planId)
              .single()
          ).data?.paystack_plan_code_monthly;

    if (paystackPlanCode) {
      const subscriptionResponse = await createSubscription({
        customer: customerCode,
        plan: paystackPlanCode,
        authorization: authCode,
      });

      const paystackSubscription = subscriptionResponse.data;

      await (supabase.from("provider_subscriptions") as any)
        .update({
          status: "active",
          paystack_subscription_code: paystackSubscription?.subscription_code,
          next_payment_date: paystackSubscription?.next_payment_date
            ? new Date(paystackSubscription.next_payment_date).toISOString()
            : null,
          started_at: new Date().toISOString(),
          auto_renew: true,
          updated_at: new Date().toISOString(),
        })
        .eq("provider_id", providerId);
    }
  } catch (err: any) {
    console.error("Failed to create Paystack subscription after authorization:", err);
  }
}

// ΓöÇΓöÇΓöÇ Additional Charges ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

async function handleAdditionalChargeSuccess(
  payload: { reference: string; metadata: any; amount: any; fees: any; customer: any },
  supabase: SupabaseClient,
) {
  const { reference, metadata, amount, fees, customer } = payload;

  const bookingId = metadata.booking_id as string;
  const chargeId = metadata.additional_charge_id as string;

  const { data: booking } = await supabase
    .from("bookings")
    .select("*")
    .eq("id", bookingId)
    .single();
  if (!booking) return;
  const bookingData = booking as any;
  const providerId = bookingData.provider_id || null;

  const { data: charge } = await (supabase.from("additional_charges") as any)
    .select("*")
    .eq("id", chargeId)
    .eq("booking_id", bookingId)
    .single();

  if (!charge) return;
  if ((charge as any).status === "paid") return;

  const amountInCurrency = convertFromSmallestUnit(amount || 0);
  const feesInCurrency = convertFromSmallestUnit(fees || 0);
  const netAmount = amountInCurrency - feesInCurrency;

  // Commission
  const { data: settingsRow } = await (supabase.from("platform_settings") as any)
    .select("settings")
    .eq("is_active", true)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  const commissionRate =
    (settingsRow as any)?.settings?.payouts?.platform_commission_percentage ?? 15;
  const platformCommission = (netAmount * commissionRate) / 100;
  const providerEarnings = netAmount - platformCommission;

  await (supabase.from("additional_charges") as any)
    .update({
      status: "paid",
      paid_at: new Date().toISOString(),
    })
    .eq("id", chargeId)
    .eq("booking_id", bookingId);

  await (supabase.from("bookings") as any)
    .update({
      total_amount: Number(bookingData.total_amount || 0) + Number((charge as any).amount || 0),
      updated_at: new Date().toISOString(),
    })
    .eq("id", bookingId);

  await (supabase.from("payment_transactions") as any).insert({
    booking_id: bookingId,
    reference,
    amount: amountInCurrency,
    fees: feesInCurrency,
    net_amount: netAmount,
    status: "success",
    provider: "paystack",
    transaction_type: "additional_charge",
    metadata: {
      additional_charge_id: chargeId,
      customer_email: customer?.email,
    },
    created_at: new Date().toISOString(),
  });

  await (supabase.from("finance_transactions") as any).insert({
    booking_id: bookingId,
    provider_id: providerId,
    transaction_type: "additional_charge_payment",
    amount: netAmount,
    fees: feesInCurrency,
    commission: platformCommission,
    net: platformCommission,
    description: `Additional charge payment for booking ${bookingData.booking_number}`,
    created_at: new Date().toISOString(),
  });

  await (supabase.from("finance_transactions") as any).insert({
    booking_id: bookingId,
    provider_id: providerId,
    transaction_type: "provider_earnings",
    amount: providerEarnings,
    fees: 0,
    commission: 0,
    net: providerEarnings,
    description: `Provider earnings (additional charge) for booking ${bookingData.booking_number}`,
    created_at: new Date().toISOString(),
  });

  await (supabase.from("payments") as any)
    .update({
      status: "paid",
      payment_provider: "paystack",
      payment_provider_transaction_id: reference,
      processed_at: new Date().toISOString(),
      payment_provider_response: { ...payload },
    })
    .eq("booking_id", bookingId)
    .eq("payment_provider", "paystack")
    .eq("payment_provider_transaction_id", reference);

  await (supabase.from("booking_events") as any).insert({
    booking_id: bookingId,
    event_type: "additional_payment_paid",
    event_data: { charge_id: chargeId, reference, amount: amountInCurrency },
    created_by: bookingData.customer_id,
  });

  // Notify customer + provider
  try {
    const { sendToUser } = await import("@/lib/notifications/onesignal");
    await sendToUser(bookingData.customer_id, {
      title: "Additional Payment Confirmed",
      message: `Your additional payment of ${bookingData.currency || "ZAR"} ${amountInCurrency.toFixed(2)} was successful.`,
      data: {
        type: "additional_payment_paid",
        booking_id: bookingId,
        charge_id: chargeId,
      },
      url: `/account-settings/bookings/${bookingId}`,
    });

    const { data: providerRow } = await supabase
      .from("providers")
      .select("user_id")
      .eq("id", bookingData.provider_id)
      .single();
    const providerUserId = (providerRow as any)?.user_id;
    if (providerUserId) {
      await sendToUser(providerUserId, {
        title: "Additional Payment Received",
        message: `Additional payment received for booking ${bookingData.booking_number}.`,
        data: {
          type: "additional_payment_paid_provider",
          booking_id: bookingId,
          charge_id: chargeId,
        },
        url: `/provider/bookings/${bookingId}`,
      });
    }
  } catch (notifError) {
    console.error("Error sending additional charge success notifications:", notifError);
  }
}

async function handleAdditionalChargeFailed(
  payload: { reference: string; metadata: any; message: any; gateway_response: any },
  supabase: SupabaseClient,
) {
  const { reference, metadata, message, gateway_response } = payload;
  const bookingId = metadata.booking_id as string;
  const chargeId = metadata.additional_charge_id as string;

  const { data: booking } = await supabase
    .from("bookings")
    .select("*")
    .eq("id", bookingId)
    .single();
  if (!booking) return;
  const bookingData = booking as any;

  await (supabase.from("payment_transactions") as any).insert({
    booking_id: bookingId,
    reference,
    amount: 0,
    fees: 0,
    net_amount: 0,
    status: "failed",
    provider: "paystack",
    transaction_type: "additional_charge",
    metadata: {
      additional_charge_id: chargeId,
      failure_reason: message || gateway_response || "paystack_charge_failed",
    },
    created_at: new Date().toISOString(),
  });

  await (supabase.from("payments") as any)
    .update({
      status: "failed",
      payment_provider: "paystack",
      payment_provider_transaction_id: reference,
      failed_at: new Date().toISOString(),
      failure_reason: message || gateway_response || "paystack_charge_failed",
      payment_provider_response: { ...payload },
    })
    .eq("booking_id", bookingId)
    .eq("payment_provider", "paystack")
    .eq("payment_provider_transaction_id", reference);

  await (supabase.from("booking_events") as any).insert({
    booking_id: bookingId,
    event_type: "additional_payment_failed",
    event_data: { charge_id: chargeId, reference },
    created_by: bookingData.customer_id,
  });

  try {
    const { sendToUser } = await import("@/lib/notifications/onesignal");
    await sendToUser(bookingData.customer_id, {
      title: "Additional Payment Failed",
      message: `Your additional payment could not be processed. Please try again.`,
      data: {
        type: "additional_payment_failed",
        booking_id: bookingId,
        charge_id: chargeId,
      },
      url: `/account-settings/bookings/${bookingId}`,
    });
  } catch (notifError) {
    console.error("Error sending additional charge failure notification:", notifError);
  }
}

/**
 * Refund Event Handlers
 *
 * Handles Paystack refund webhook events:
 *   - refund.processed ΓÇö Refund completed successfully
 *   - refund.failed    ΓÇö Refund failed
 */
import { NextResponse } from "next/server";
import { convertFromSmallestUnit } from "@/lib/payments/paystack";
import type { PaystackEvent, SupabaseClient } from "./shared";

// ΓöÇΓöÇΓöÇ Exported Handler ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Handle all refund.* events ΓÇö update payment / transaction records.
 */
export async function handleRefundEvent(
  event: PaystackEvent,
  supabase: SupabaseClient,
): Promise<NextResponse> {
  const { event: eventType, data } = event;

  if (eventType === "refund.processed") {
    await handleRefundProcessed(data, supabase);
  } else if (eventType === "refund.failed") {
    await handleRefundFailed(data, supabase);
  } else {
    console.log(`Unhandled refund event type: ${eventType}`);
  }

  return NextResponse.json({ received: true });
}

// ΓöÇΓöÇΓöÇ Internal Handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

async function handleRefundProcessed(data: any, supabase: SupabaseClient) {
  const reference = data?.transaction_reference || data?.reference;
  const refundAmount = data?.amount ? convertFromSmallestUnit(data.amount) : 0;
  const refundReference = data?.refund_reference || data?.id;

  if (!reference) {
    console.log("Refund processed event missing transaction reference");
    return;
  }

  // Find the original payment transaction
  const { data: txn } = await (supabase.from("payment_transactions") as any)
    .select("id, booking_id")
    .eq("reference", reference)
    .eq("status", "success")
    .maybeSingle();

  // Record refund transaction
  await (supabase.from("payment_transactions") as any).insert({
    booking_id: txn?.booking_id || null,
    reference: String(refundReference || reference),
    amount: refundAmount,
    fees: 0,
    net_amount: refundAmount,
    status: "refunded",
    provider: "paystack",
    transaction_type: "refund",
    metadata: {
      original_reference: reference,
      refund_reference: refundReference,
      paystack_data: data,
    },
    created_at: new Date().toISOString(),
  });

  // If linked to a booking, update its payment status
  if (txn?.booking_id) {
    await (supabase.from("bookings") as any)
      .update({
        payment_status: "refunded",
        updated_at: new Date().toISOString(),
      })
      .eq("id", txn.booking_id);

    // Finance ledger entry
    await (supabase.from("finance_transactions") as any).insert({
      booking_id: txn.booking_id,
      provider_id: null,
      transaction_type: "refund",
      amount: refundAmount,
      fees: 0,
      commission: 0,
      net: -refundAmount,
      description: `Refund processed (${reference})`,
      created_at: new Date().toISOString(),
    });
  }

  console.log(`Refund processed for transaction ${reference} ΓÇö ${refundAmount}`);
}

async function handleRefundFailed(data: any, supabase: SupabaseClient) {
  const reference = data?.transaction_reference || data?.reference;
  const refundReference = data?.refund_reference || data?.id;
  const reason = data?.message || data?.gateway_response || "Refund failed";

  if (!reference) {
    console.log("Refund failed event missing transaction reference");
    return;
  }

  // Record failed refund for audit
  await (supabase.from("payment_transactions") as any).insert({
    booking_id: null,
    reference: String(refundReference || reference),
    amount: 0,
    fees: 0,
    net_amount: 0,
    status: "failed",
    provider: "paystack",
    transaction_type: "refund",
    metadata: {
      original_reference: reference,
      refund_reference: refundReference,
      failure_reason: reason,
      paystack_data: data,
    },
    created_at: new Date().toISOString(),
  });

  console.log(`Refund failed for transaction ${reference}: ${reason}`);
}

/**
 * Shared utilities, types, and helpers for Paystack webhook handlers
 */
import type { SupabaseClient } from "@supabase/supabase-js";

// ΓöÇΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export type { SupabaseClient };

/**
 * Top-level Paystack webhook event envelope.
 * `data` varies per event type so we keep it loosely typed.
 */
export interface PaystackEvent {
  event: string;
  data: Record<string, any>;
  id?: string | number;
}

// ΓöÇΓöÇΓöÇ Shared Helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Save Paystack authorization code as a payment method
 */
export async function savePaystackAuthorization({
  userId,
  email,
  authorizationCode,
  lastFour,
  expiryMonth,
  expiryYear,
  cardBrand,
  isDefault,
  supabase,
}: {
  userId: string;
  email: string;
  authorizationCode: string;
  lastFour: string;
  expiryMonth: number;
  expiryYear: number;
  cardBrand: string;
  isDefault?: boolean;
  supabase: SupabaseClient;
}) {
  // Check if this authorization code already exists for this user
  const { data: existing } = await (supabase
    .from("payment_methods") as any)
    .select("id")
    .eq("user_id", userId)
    .eq("provider", "paystack")
    .eq("provider_payment_method_id", authorizationCode)
    .eq("is_active", true)
    .maybeSingle();

  if (existing) {
    // Update existing payment method
    const updateData: any = {
      last_four: lastFour,
      expiry_month: expiryMonth,
      expiry_year: expiryYear,
      card_brand: cardBrand.toLowerCase(),
      updated_at: new Date().toISOString(),
    };

    if (isDefault) {
      // Unset other defaults first
      await (supabase
        .from("payment_methods") as any)
        .update({ is_default: false })
        .eq("user_id", userId)
        .eq("is_default", true);
      updateData.is_default = true;
    }

    await (supabase
      .from("payment_methods") as any)
      .update(updateData)
      .eq("id", existing.id);

    return existing.id;
  }

  // If this is set as default, unset other defaults
  if (isDefault) {
    await (supabase
      .from("payment_methods") as any)
      .update({ is_default: false })
      .eq("user_id", userId)
      .eq("is_default", true);
  }

  // Create new payment method
  const { data: method, error } = await (supabase
    .from("payment_methods") as any)
    .insert({
      user_id: userId,
      type: "card",
      provider: "paystack",
      provider_payment_method_id: authorizationCode,
      last_four: lastFour,
      expiry_month: expiryMonth,
      expiry_year: expiryYear,
      card_brand: cardBrand.toLowerCase(),
      metadata: {
        email,
        saved_via: "paystack_transaction",
      },
      is_default: isDefault || false,
      is_active: true,
    })
    .select()
    .single();

  if (error) {
    throw error;
  }

  return method.id;
}

/**
 * Generate a unique, human-readable gift card code (16 chars, uppercase)
 */
export function generateGiftCardCode(): string {
  const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let out = "GC-";
  for (let i = 0; i < 16; i++) out += alphabet[Math.floor(Math.random() * alphabet.length)];
  return out;
}

/**
 * Subscription Event Handlers
 *
 * Handles subscription-related webhook events from Paystack:
 *   - subscription.create   ΓÇö New subscription created
 *   - subscription.disable  ΓÇö Subscription disabled / cancelled
 *   - subscription.enable   ΓÇö Subscription re-enabled
 *   - subscription.not_renew ΓÇö Subscription flagged as non-renewing
 *   - invoice.create        ΓÇö New invoice for subscription renewal
 *   - invoice.payment_failed ΓÇö Subscription payment failed
 */
import { NextResponse } from "next/server";
import { convertFromSmallestUnit } from "@/lib/payments/paystack";
import type { PaystackEvent, SupabaseClient } from "./shared";

// ΓöÇΓöÇΓöÇ Exported Handler ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Route a subscription / invoice event to the correct internal handler.
 */
export async function handleSubscriptionEvent(
  event: PaystackEvent,
  supabase: SupabaseClient,
): Promise<NextResponse> {
  const { event: eventType, data } = event;

  if (eventType === "subscription.create") {
    await handleSubscriptionCreate(data, supabase);
  } else if (eventType === "subscription.disable") {
    await handleSubscriptionDisable(data, supabase);
  } else if (eventType === "subscription.enable") {
    await handleSubscriptionEnable(data, supabase);
  } else if (eventType === "subscription.not_renew") {
    await handleSubscriptionNotRenew(data, supabase);
  } else if (eventType === "invoice.create" || eventType === "invoice.payment_failed") {
    await handleSubscriptionInvoice(data, eventType, supabase);
  } else {
    console.log(`Unhandled subscription event type: ${eventType}`);
  }

  return NextResponse.json({ received: true });
}

// ΓöÇΓöÇΓöÇ Internal Handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

async function handleSubscriptionCreate(payload: any, supabase: SupabaseClient) {
  const subscriptionCode = payload.subscription_code;
  const customerCode = payload.customer?.customer_code || payload.customer_code;
  const planCode = payload.plan?.plan_code || payload.plan_code;
  const status = payload.status;
  const nextPaymentDate = payload.next_payment_date;

  if (!subscriptionCode) {
    console.error("Missing subscription_code in subscription.create event");
    return;
  }

  // Find provider by customer code or email
  const { data: customer } = await supabase
    .from("users")
    .select("id, email")
    .eq("email", payload.customer?.email || "")
    .single();

  if (!customer) {
    console.error("Customer not found for subscription:", customerCode);
    return;
  }

  const { data: provider } = await supabase
    .from("providers")
    .select("id")
    .eq("user_id", customer.id)
    .single();

  if (!provider) {
    console.error("Provider not found for user:", customer.id);
    return;
  }

  // Find plan by Paystack plan code
  const { data: plan } = await supabase
    .from("subscription_plans")
    .select("id")
    .or(`paystack_plan_code_monthly.eq.${planCode},paystack_plan_code_yearly.eq.${planCode}`)
    .single();

  if (!plan) {
    console.error("Plan not found for Paystack plan code:", planCode);
    return;
  }

  // Determine billing period from plan
  const { data: planDetails } = await supabase
    .from("subscription_plans")
    .select("paystack_plan_code_monthly, paystack_plan_code_yearly")
    .eq("id", plan.id)
    .single();

  const billingPeriod =
    (planDetails as any)?.paystack_plan_code_monthly === planCode ? "monthly" : "yearly";

  // Update or create subscription
  await (supabase.from("provider_subscriptions") as any).upsert(
    {
      provider_id: provider.id,
      plan_id: plan.id,
      status: status === "active" ? "active" : "inactive",
      paystack_subscription_code: subscriptionCode,
      paystack_customer_code: customerCode,
      paystack_authorization_code: payload.authorization?.authorization_code,
      billing_period: billingPeriod,
      auto_renew: true,
      next_payment_date: nextPaymentDate
        ? new Date(nextPaymentDate).toISOString()
        : null,
      started_at: payload.createdAt
        ? new Date(payload.createdAt).toISOString()
        : new Date().toISOString(),
      updated_at: new Date().toISOString(),
    },
    { onConflict: "provider_id" },
  );
}

async function handleSubscriptionDisable(payload: any, supabase: SupabaseClient) {
  const subscriptionCode = payload.subscription_code;

  if (!subscriptionCode) {
    console.error("Missing subscription_code in subscription.disable event");
    return;
  }

  await (supabase.from("provider_subscriptions") as any)
    .update({
      status: "cancelled",
      auto_renew: false,
      cancelled_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    })
    .eq("paystack_subscription_code", subscriptionCode);
}

async function handleSubscriptionEnable(payload: any, supabase: SupabaseClient) {
  const subscriptionCode = payload.subscription_code;
  const nextPaymentDate = payload.next_payment_date;

  if (!subscriptionCode) {
    console.error("Missing subscription_code in subscription.enable event");
    return;
  }

  await (supabase.from("provider_subscriptions") as any)
    .update({
      status: "active",
      auto_renew: true,
      next_payment_date: nextPaymentDate
        ? new Date(nextPaymentDate).toISOString()
        : null,
      cancelled_at: null,
      updated_at: new Date().toISOString(),
    })
    .eq("paystack_subscription_code", subscriptionCode);
}

async function handleSubscriptionNotRenew(payload: any, supabase: SupabaseClient) {
  const subscriptionCode = payload.subscription_code;

  if (!subscriptionCode) {
    console.error("Missing subscription_code in subscription.not_renew event");
    return;
  }

  await (supabase.from("provider_subscriptions") as any)
    .update({
      auto_renew: false,
      updated_at: new Date().toISOString(),
    })
    .eq("paystack_subscription_code", subscriptionCode);

  console.log(`Subscription ${subscriptionCode} marked as non-renewing`);
}

async function handleSubscriptionInvoice(
  payload: any,
  eventType: string,
  supabase: SupabaseClient,
) {
  const subscriptionCode =
    payload.subscription?.subscription_code || payload.subscription_code;
  const invoiceCode = payload.invoice_code || payload.code;
  const amount = payload.amount || 0;
  const fees = payload.fees || 0;
  const status = payload.status;
  const paidAt = payload.paid_at;

  if (!subscriptionCode) {
    console.error("Missing subscription_code in invoice event");
    return;
  }

  const { data: subscription } = await supabase
    .from("provider_subscriptions")
    .select("provider_id, plan_id")
    .eq("paystack_subscription_code", subscriptionCode)
    .single();

  if (!subscription) {
    console.error("Subscription not found:", subscriptionCode);
    return;
  }

  const providerId = (subscription as any).provider_id;

  if (eventType === "invoice.create") {
    const dueDate = payload.due_date;
    await (supabase.from("provider_subscriptions") as any)
      .update({
        next_payment_date: dueDate ? new Date(dueDate).toISOString() : null,
        updated_at: new Date().toISOString(),
      })
      .eq("paystack_subscription_code", subscriptionCode);
  } else if (eventType === "invoice.payment_failed") {
    await (supabase.from("provider_subscriptions") as any)
      .update({
        status: "past_due",
        updated_at: new Date().toISOString(),
      })
      .eq("paystack_subscription_code", subscriptionCode);

    await (supabase.from("payment_transactions") as any).insert({
      booking_id: null,
      reference: invoiceCode,
      amount: convertFromSmallestUnit(amount),
      fees: convertFromSmallestUnit(fees),
      net_amount: convertFromSmallestUnit(amount - fees),
      status: "failed",
      provider: "paystack",
      transaction_type: "provider_subscription_payment",
      metadata: {
        subscription_code: subscriptionCode,
        invoice_code: invoiceCode,
        kind: "subscription_renewal",
      },
      created_at: new Date().toISOString(),
    });
  } else if (status === "success" && paidAt) {
    // Successful renewal
    const amountInCurrency = convertFromSmallestUnit(amount);
    const feesInCurrency = convertFromSmallestUnit(fees);
    const netAmount = amountInCurrency - feesInCurrency;

    const { data: subscriptionDetails } = await supabase
      .from("provider_subscriptions")
      .select("billing_period, plan_id, provider_id")
      .eq("paystack_subscription_code", subscriptionCode)
      .single();

    const now = new Date();
    const expiresAt = new Date(now);
    expiresAt.setMonth(expiresAt.getMonth() + 1);

    const nextPaymentDate = payload.next_payment_date || expiresAt;

    await (supabase.from("provider_subscriptions") as any)
      .update({
        status: "active",
        last_payment_date: new Date(paidAt).toISOString(),
        expires_at: expiresAt.toISOString(),
        next_payment_date: nextPaymentDate
          ? new Date(nextPaymentDate as string | Date).toISOString()
          : null,
        updated_at: new Date().toISOString(),
      })
      .eq("paystack_subscription_code", subscriptionCode);

    await (supabase.from("payment_transactions") as any).insert({
      booking_id: null,
      reference: invoiceCode,
      amount: amountInCurrency,
      fees: feesInCurrency,
      net_amount: netAmount,
      status: "success",
      provider: "paystack",
      transaction_type: "provider_subscription_payment",
      metadata: {
        subscription_code: subscriptionCode,
        invoice_code: invoiceCode,
        kind: "subscription_renewal",
      },
      created_at: new Date().toISOString(),
    });

    await (supabase.from("finance_transactions") as any).insert({
      booking_id: null,
      provider_id: providerId,
      transaction_type: "provider_subscription_payment",
      amount: netAmount,
      fees: feesInCurrency,
      commission: 0,
      net: netAmount,
      description: `Provider subscription renewal payment`,
      created_at: new Date().toISOString(),
    });

    // Send subscription_renewed notification
    if (subscriptionDetails) {
      try {
        const { sendTemplateNotification } = await import("@/lib/notifications/onesignal");
        const subDetails = subscriptionDetails as any;
        const billingPeriod = subDetails.billing_period || "monthly";

        const { data: plan } = await supabase
          .from("subscription_plans")
          .select("name, currency, price_monthly, price_yearly")
          .eq("id", subDetails.plan_id)
          .single();

        const { data: provider } = await supabase
          .from("providers")
          .select("user_id, business_name")
          .eq("id", subDetails.provider_id)
          .single();

        if (provider?.user_id && plan) {
          const planAmount =
            billingPeriod === "yearly"
              ? plan.price_yearly || netAmount
              : plan.price_monthly || netAmount;
          const currency = plan.currency || "ZAR";

          await sendTemplateNotification(
            "subscription_renewed",
            [provider.user_id],
            {
              business_name: provider.business_name || "Provider",
              plan_name: plan.name || "Current Plan",
              amount: `${currency} ${planAmount.toLocaleString()}`,
              billing_period: billingPeriod,
              next_payment_date: new Date(
                nextPaymentDate as string | Date,
              ).toLocaleDateString(),
              app_url: process.env.NEXT_PUBLIC_APP_URL || "https://beautonomi.com",
              year: new Date().getFullYear().toString(),
            },
            ["push", "email", "sms"],
          );
        }
      } catch (notifError) {
        console.error("Error sending subscription renewal notification:", notifError);
      }
    }
  }
}

/**
 * Transfer Event Handlers
 *
 * Handles Paystack transfer webhook events:
 *   - transfer.success   ΓÇö Payout completed successfully
 *   - transfer.failed    ΓÇö Payout failed
 *   - transfer.reversed  ΓÇö Payout was reversed
 *   - Other transfer.*   ΓÇö Stored for audit trail
 */
import { NextResponse } from "next/server";
import type { PaystackEvent, SupabaseClient } from "./shared";

// ΓöÇΓöÇΓöÇ Exported Handler ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Handle all transfer.* events ΓÇö update payout records.
 */
export async function handleTransferEvent(
  event: PaystackEvent,
  supabase: SupabaseClient,
): Promise<NextResponse> {
  const { event: eventType, data } = event;

  const transferCode =
    data?.transfer_code || data?.transferCode || data?.transfer?.transfer_code;
  const reference = data?.reference || data?.transfer?.reference;

  if (!transferCode && !reference) {
    console.log(`Transfer event missing transfer_code/reference: ${eventType}`);
    return NextResponse.json({ received: true });
  }

  // Find payout by transfer_code first, then fallback to reference
  const { data: payout } = await (supabase.from("payouts") as any)
    .select("*")
    .or(
      [
        transferCode ? `transfer_code.eq.${transferCode}` : null,
        transferCode ? `payout_provider_transaction_id.eq.${transferCode}` : null,
        reference ? `payout_provider_transaction_id.eq.${reference}` : null,
      ]
        .filter(Boolean)
        .join(","),
    )
    .maybeSingle();

  if (!payout) {
    console.log(
      `No payout found for transfer event ${eventType} (${transferCode || reference})`,
    );
    return NextResponse.json({ received: true });
  }

  const payoutData = payout as any;

  // Idempotency: if already terminal, don't flip
  if (["completed", "failed"].includes(payoutData.status)) {
    return NextResponse.json({ received: true });
  }

  if (eventType === "transfer.success") {
    await (supabase.from("payouts") as any)
      .update({
        status: "completed",
        completed_at: new Date().toISOString(),
        payout_provider: "paystack",
        payout_provider_transaction_id:
          transferCode || payoutData.payout_provider_transaction_id,
        payout_provider_response: data,
        transfer_code: transferCode || payoutData.transfer_code,
        transfer_id: data?.id || payoutData.transfer_id,
      })
      .eq("id", payoutData.id);

    return NextResponse.json({ received: true });
  }

  if (eventType === "transfer.failed" || eventType === "transfer.reversed") {
    const failureReason =
      data?.reason || data?.message || data?.gateway_response || eventType;
    await (supabase.from("payouts") as any)
      .update({
        status: "failed",
        failed_at: new Date().toISOString(),
        failure_reason: String(failureReason).slice(0, 500),
        payout_provider: "paystack",
        payout_provider_transaction_id:
          transferCode || payoutData.payout_provider_transaction_id,
        payout_provider_response: data,
        transfer_code: transferCode || payoutData.transfer_code,
        transfer_id: data?.id || payoutData.transfer_id,
      })
      .eq("id", payoutData.id);

    return NextResponse.json({ received: true });
  }

  // Other transfer events: keep as processing but store latest provider response
  await (supabase.from("payouts") as any)
    .update({
      status: payoutData.status || "processing",
      payout_provider: "paystack",
      payout_provider_transaction_id:
        transferCode || payoutData.payout_provider_transaction_id,
      payout_provider_response: data,
      transfer_code: transferCode || payoutData.transfer_code,
      transfer_id: data?.id || payoutData.transfer_id,
    })
    .eq("id", payoutData.id);

  return NextResponse.json({ received: true });
}

import { NextResponse } from "next/server";
import crypto from "crypto";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { getPaystackSecretKey } from "@/lib/payments/paystack-server";
import { handleChargeSuccess, handleChargeFailed } from "./_handlers/charge-success";
import { handleSubscriptionEvent } from "./_handlers/subscription-events";
import { handleTransferEvent } from "./_handlers/transfer-events";
import { handleRefundEvent } from "./_handlers/refund-events";
import type { PaystackEvent } from "./_handlers/shared";

/**
 * POST /api/payments/webhook
 *
 * Paystack webhook handler ΓÇö thin router.
 *
 * 1. Verifies the HMAC-SHA512 signature
 * 2. Parses the event type from the body
 * 3. Performs idempotency check (webhook_events table)
 * 4. Routes to the appropriate handler based on event type
 * 5. Marks the event as processed / failed
 * 6. Returns 200 for unhandled event types
 */
export async function POST(request: Request) {
  try {
    // ΓöÇΓöÇ 1. Read body & verify signature ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const body = await request.text();
    const signature = request.headers.get("x-paystack-signature");

    if (!signature) {
      return NextResponse.json({ error: "Missing signature" }, { status: 400 });
    }

    const paystackSecretKey = await getPaystackSecretKey();

    const hash = crypto
      .createHmac("sha512", paystackSecretKey)
      .update(body)
      .digest("hex");

    if (hash !== signature) {
      console.error("Invalid webhook signature");
      return NextResponse.json({ error: "Invalid signature" }, { status: 401 });
    }

    // ΓöÇΓöÇ 2. Parse event ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const event: PaystackEvent = JSON.parse(body);
    const { event: eventType, data } = event;

    if (!eventType || !data) {
      console.error("Invalid webhook payload structure");
      return NextResponse.json({ error: "Invalid webhook payload" }, { status: 400 });
    }

    // ΓöÇΓöÇ 3. Idempotency check ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const supabase = getSupabaseAdmin();
    const eventId = event.id || data.id || data.reference;

    if (eventId) {
      const { error: insertError } = await supabase
        .from("webhook_events")
        .insert({
          event_id: eventId,
          source: "paystack",
          event_type: eventType,
          payload: event,
          status: "processing",
          processed_at: null,
        })
        .select("id, status")
        .single();

      if (insertError) {
        if (
          insertError.code === "23505" ||
          insertError.message?.includes("unique") ||
          insertError.message?.includes("duplicate")
        ) {
          const { data: existingEvent } = await supabase
            .from("webhook_events")
            .select("id, status")
            .eq("event_id", eventId)
            .eq("source", "paystack")
            .single();

          if (existingEvent) {
            if ((existingEvent as any).status === "processed") {
              console.log(`Event ${eventId} already processed, skipping`);
              return NextResponse.json({ received: true, duplicate: true });
            } else if ((existingEvent as any).status === "processing") {
              console.log(`Event ${eventId} is being processed by another instance`);
              return NextResponse.json({ received: true, processing: true });
            }
          }
        }

        throw insertError;
      }
    }

    // ΓöÇΓöÇ 4. Route to handler ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    let processingError: Error | null = null;
    try {
      let response: NextResponse;

      if (eventType === "charge.success") {
        response = await handleChargeSuccess(event, supabase);
      } else if (eventType === "charge.failed") {
        response = await handleChargeFailed(event, supabase);
      } else if (eventType.startsWith("transfer.")) {
        response = await handleTransferEvent(event, supabase);
      } else if (
        eventType === "subscription.create" ||
        eventType === "subscription.disable" ||
        eventType === "subscription.enable" ||
        eventType === "subscription.not_renew" ||
        eventType === "invoice.create" ||
        eventType === "invoice.payment_failed"
      ) {
        response = await handleSubscriptionEvent(event, supabase);
      } else if (eventType.startsWith("refund.")) {
        response = await handleRefundEvent(event, supabase);
      } else {
        console.log(`Unhandled event type: ${eventType}`);
        response = NextResponse.json({ received: true });
      }

      // ΓöÇΓöÇ 5a. Mark as processed ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      if (eventId) {
        await (supabase.from("webhook_events") as any)
          .update({
            status: "processed",
            processed_at: new Date().toISOString(),
          })
          .eq("event_id", eventId)
          .eq("source", "paystack");
      }

      return response;
    } catch (error) {
      processingError =
        error instanceof Error ? error : new Error(String(error));
      console.error("Error processing webhook:", processingError);

      // ΓöÇΓöÇ 5b. Mark as failed ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      if (eventId) {
        await (supabase.from("webhook_events") as any)
          .update({
            status: "failed",
            error_message: processingError.message,
            processed_at: new Date().toISOString(),
          })
          .eq("event_id", eventId)
          .eq("source", "paystack");
      }

      // Add to reconciliation queue for charge events
      if (eventType === "charge.success" || eventType === "charge.failed") {
        const bookingId = event?.data?.metadata?.booking_id;
        const reference = event?.data?.reference;

        if (bookingId && reference) {
          try {
            await (supabase.from("payment_reconciliation_queue") as any).insert({
              booking_id: bookingId,
              payment_reference: reference,
              payment_provider: "paystack",
              status: "pending",
              error_message: processingError.message,
              attempt_count: 1,
              next_retry_at: new Date(
                Date.now() + 5 * 60 * 1000,
              ).toISOString(),
            });
          } catch (reconError) {
            console.error(
              "Failed to add to reconciliation queue:",
              reconError,
            );
          }
        }
      }

      // Still return 200 to Paystack (we'll retry manually)
      return NextResponse.json({
        received: true,
        error: processingError.message,
      });
    }
  } catch (error) {
    console.error("Unexpected error in /api/payments/webhook:", error);
    return NextResponse.json(
      { error: "Webhook processing failed" },
      { status: 500 },
    );
  }
}

/**
 * Paystack Subscription Webhook Handlers
 * 
 * Handles subscription-related webhook events from Paystack:
 * - subscription.create: New subscription created
 * - subscription.disable: Subscription disabled/cancelled
 * - subscription.enable: Subscription re-enabled
 * - invoice.create: New invoice for subscription renewal
 * - invoice.payment_failed: Subscription payment failed
 */

import { convertFromSmallestUnit } from "@/lib/payments/paystack";

/**
 * Handle subscription.create event
 */
export async function handleSubscriptionCreate(payload: any, supabase: any) {
  const subscriptionCode = payload.subscription_code;
  const customerCode = payload.customer?.customer_code || payload.customer_code;
  const planCode = payload.plan?.plan_code || payload.plan_code;
  const status = payload.status;
  const nextPaymentDate = payload.next_payment_date;

  if (!subscriptionCode) {
    console.error("Missing subscription_code in subscription.create event");
    return;
  }

  // Find provider by customer code or email
  const { data: customer } = await supabase
    .from("users")
    .select("id, email")
    .eq("email", payload.customer?.email || "")
    .single();

  if (!customer) {
    console.error("Customer not found for subscription:", customerCode);
    return;
  }

  // Find provider
  const { data: provider } = await supabase
    .from("providers")
    .select("id")
    .eq("user_id", customer.id)
    .single();

  if (!provider) {
    console.error("Provider not found for user:", customer.id);
    return;
  }

  // Find plan by Paystack plan code
  const { data: plan } = await supabase
    .from("subscription_plans")
    .select("id")
    .or(`paystack_plan_code_monthly.eq.${planCode},paystack_plan_code_yearly.eq.${planCode}`)
    .single();

  if (!plan) {
    console.error("Plan not found for Paystack plan code:", planCode);
    return;
  }

  // Determine billing period from plan
  const { data: planDetails } = await supabase
    .from("subscription_plans")
    .select("paystack_plan_code_monthly, paystack_plan_code_yearly")
    .eq("id", plan.id)
    .single();

  const billingPeriod = 
    (planDetails as any)?.paystack_plan_code_monthly === planCode ? "monthly" : "yearly";

  // Update or create subscription
  await (supabase.from("provider_subscriptions") as any).upsert({
    provider_id: provider.id,
    plan_id: plan.id,
    status: status === "active" ? "active" : "inactive",
    paystack_subscription_code: subscriptionCode,
    paystack_customer_code: customerCode,
    paystack_authorization_code: payload.authorization?.authorization_code,
    billing_period: billingPeriod,
    auto_renew: true,
