export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const providerId = await getProviderId(request);
    if (!providerId) return errorResponse("Provider not found", "NOT_FOUND", 404);

    const body = await request.json();
    const supabase = getSupabaseAdmin();
    const impressionPackId = body.impression_pack_id ?? null;
    let budget = Number(body.budget) || 0;
    let packImpressions: number | null = null;
    if (impressionPackId) {
      const { data: pack } = await supabase
        .from("ads_impression_packs")
        .select("id, impressions, price_zar")
        .eq("id", impressionPackId)
        .eq("is_active", true)
        .single();
      if (!pack) return errorResponse("Invalid or inactive impression pack", "VALIDATION", 400);
      budget = Number((pack as any).price_zar);
      packImpressions = Number((pack as any).impressions);
    } else {
      budget = Number(body.budget) || 0;
    }
    const dailyBudget = body.daily_budget != null ? Number(body.daily_budget) : null;
    const bidCpc = Number(body.bid_cpc) || 0;
    const startAt = body.start_at ?? null;
    const endAt = body.end_at ?? null;
    const targeting = body.targeting ?? {};
    const bidSettings = body.bid_settings ?? {};

    const { data: config } = await supabase.from("ads_module_config").select("enabled").eq("environment", process.env.NODE_ENV === "production" ? "production" : "development").maybeSingle();
    if (!config?.enabled) return errorResponse("Ads module is disabled", "DISABLED", 403);

    const currency = "ZAR";
    const insertBudget = budget > 0 ? 0 : budget;

    const { data: campaign, error: campaignError } = await supabase
      .from("ads_campaigns")
      .insert({
        provider_id: providerId,
        status: "draft",
        budget: insertBudget,
        spent: 0,
        daily_budget: packImpressions != null ? null : dailyBudget,
        bid_cpc: packImpressions != null ? 0 : bidCpc,
        start_at: startAt,
        end_at: endAt,
        targeting,
        bid_settings: bidSettings,
        pack_impressions: packImpressions,
      })
      .select()
      .single();

    if (campaignError || !campaign) throw campaignError || new Error("Failed to create campaign");

    if (budget <= 0) {
      return successResponse(campaign);
    }

    const { data: order, error: orderError } = await supabase
      .from("ads_budget_orders")
      .insert({
        provider_id: providerId,
        campaign_id: campaign.id,
        amount: budget,
        currency,
        status: "pending",
      })
      .select()
      .single();

    if (orderError || !order) throw orderError || new Error("Failed to create budget order");

    const { data: userRow } = await supabase.from("users").select("email").eq("id", user.id).single();
    const email = (userRow as any)?.email || user.email;
    if (!email) return errorResponse("User email required for payment", "VALIDATION", 400);

    const reference = generateTransactionReference("ads_budget", order.id);
    const baseUrl = process.env.NEXT_PUBLIC_APP_URL || "";
    const callbackUrl = `${baseUrl}/provider/settings/ads?payment_success=1&order_id=${order.id}`;

    const paystackData = await initializePaystackTransaction({
      email,
      amountInSmallestUnit: Math.max(100, convertToSmallestUnit(budget)),
      currency,
      reference,
      callback_url: callbackUrl,
      metadata: {
        ads_budget_order_id: order.id,
        provider_id: providerId,
        campaign_id: campaign.id,
      },
    });

    await supabase
      .from("ads_budget_orders")
      .update({ paystack_reference: reference, updated_at: new Date().toISOString() })
      .eq("id", order.id);

    const paymentUrl = paystackData?.data?.authorization_url || null;
    return successResponse({
      campaign,
      requires_payment: true,
      payment_url: paymentUrl,
      order_id: order.id,
    });
  } catch (error) {
    return handleApiError(error as Error, "Failed to create campaign");
  }
}

/**
 * GET /api/provider/ads/performance - Ad performance: impressions, clicks, spend, sales (bookings from ads)
 * Query: start_date, end_date, campaign_id (optional)
 */

import { NextRequest } from "next/server";
import { requireRoleInApi, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { getSupabaseAdmin } from "@/lib/supabase/admin";

async function getProviderId(request: NextRequest): Promise<string | null> {
  const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
  const supabase = getSupabaseAdmin();
  const { data: byOwner } = await supabase.from("providers").select("id").eq("user_id", user.id).limit(1).maybeSingle();
  if (byOwner) return byOwner.id;
  const { data: staff } = await supabase.from("provider_staff").select("provider_id").eq("user_id", user.id).limit(1).maybeSingle();
  return staff?.provider_id ?? null;
}

export async function GET(request: NextRequest) {
  try {
    const providerId = await getProviderId(request);
    if (!providerId) return errorResponse("Provider not found", "NOT_FOUND", 404);

    const { searchParams } = new URL(request.url);
    const startDate = searchParams.get("start_date") ?? undefined;
    const endDate = searchParams.get("end_date") ?? undefined;
    const campaignId = searchParams.get("campaign_id") ?? undefined;

    const supabase = getSupabaseAdmin();

    let eventsQuery = supabase
      .from("ads_events")
      .select("id, campaign_id, event_type, created_at, attribution")
      .eq("provider_id", providerId);
    if (startDate) eventsQuery = eventsQuery.gte("created_at", startDate);
    if (endDate) eventsQuery = eventsQuery.lte("created_at", endDate);
    if (campaignId) eventsQuery = eventsQuery.eq("campaign_id", campaignId);
    const { data: events } = await eventsQuery.order("created_at", { ascending: false });

    const impressions = (events ?? []).filter((e: any) => e.event_type === "impression").length;
    const clicks = (events ?? []).filter((e: any) => e.event_type === "click").length;
    const books = (events ?? []).filter((e: any) => e.event_type === "book").length;

    const { data: campaigns } = await supabase
      .from("ads_campaigns")
      .select("id, status, budget, spent, bid_cpc, created_at")
      .eq("provider_id", providerId);
    const totalSpent = (campaigns ?? []).reduce((s: number, c: any) => s + Number(c.spent ?? 0), 0);

    const byCampaign: Record<string, { impressions: number; clicks: number; books: number; spent: number }> = {};
    for (const e of events ?? []) {
      const cid = e.campaign_id ?? "uncategorized";
      if (!byCampaign[cid]) byCampaign[cid] = { impressions: 0, clicks: 0, books: 0, spent: 0 };
      if (e.event_type === "impression") byCampaign[cid].impressions += 1;
      if (e.event_type === "click") byCampaign[cid].clicks += 1;
      if (e.event_type === "book") byCampaign[cid].books += 1;
    }
    for (const c of campaigns ?? []) {
      if (!byCampaign[c.id]) byCampaign[c.id] = { impressions: 0, clicks: 0, books: 0, spent: 0 };
      byCampaign[c.id].spent = Number(c.spent ?? 0);
    }

    return successResponse({
      summary: {
        impressions,
        clicks,
        spend: totalSpent,
        sales: books,
      },
      by_campaign: byCampaign,
      events: (events ?? []).slice(0, 100),
    });
  } catch (error) {
    return handleApiError(error as Error, "Failed to load ad performance");
  }
}

import { NextRequest } from "next/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, errorResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { callGemini } from "@/lib/ai/gemini";
import { getProviderContext, formatCapsuleForPrompt } from "@/lib/ai/provider-context";
import { enforceAiBudget, logAiUsage } from "@/lib/ai/enforce-budget";
import { checkProviderAiEntitlement } from "@/lib/ai/entitlements";

const ENV = process.env.VERCEL_ENV ?? process.env.NODE_ENV ?? "production";
const ENVIRONMENT = ENV === "production" ? "production" : ENV === "staging" ? "staging" : "development";

const FEATURE_TEMPLATES: Record<
  string,
  { system: string; userPrompt: string; model: string }
> = {
  "ai.provider.profile_completion": {
    system: `You are a helpful assistant for beauty and wellness providers. Given the provider context, suggest improvements for their profile: headline, short bio, specialties, FAQ, and policies. Respond with a JSON object: { "suggested_profile_patch": { "headline": string, "bio": string, "specialties": string[], "faq": string[], "policies": string[] } }. Only include fields you suggest; omit null.`,
    userPrompt: "Suggest profile improvements based on the provider context.",
    model: "gemini-1.5-flash",
  },
  "ai.provider.content_studio": {
    system: `You are a social media assistant for beauty and wellness providers. Given the provider context, suggest post captions and hashtags. Respond with a JSON object: { "post_captions": string[], "hashtags": string[], "short_description": string }. Keep captions concise and on-brand.`,
    userPrompt: "Suggest post captions, hashtags, and a short description for the provider.",
    model: "gemini-1.5-flash",
  },
};

/**
 * POST /api/provider/ai/[feature_key]
 * Body: { input?: string } (optional extra context)
 * Returns: { data: <feature-specific JSON>, error: null } or error.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ feature_key: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return errorResponse("Provider context required", "FORBIDDEN", 403);
    }

    const { feature_key } = await params;
    if (!FEATURE_TEMPLATES[feature_key]) {
      return errorResponse("Unknown AI feature", "NOT_FOUND", 404);
    }

    const entitlementCheck = await checkProviderAiEntitlement(providerId, feature_key);
    if (!entitlementCheck.allowed) {
      return errorResponse(
        entitlementCheck.reason ?? "Feature not available for your plan",
        "ENTITLEMENT",
        403
      );
    }

    const budget = await enforceAiBudget({
      feature_key,
      actor_user_id: user.id,
      provider_id: providerId,
      role: user.role ?? "provider_staff",
      environment: ENVIRONMENT,
    });
    if (!budget.allowed) {
      return successResponse({
        disabled: true,
        reason: budget.reason,
        fallback_mode: budget.fallback_mode ?? "off",
      });
    }

    const admin = getSupabaseAdmin();
    const { data: geminiRow } = await admin
      .from("gemini_integration_config")
      .select("api_key_secret, default_model")
      .eq("environment", ENVIRONMENT)
      .eq("enabled", true)
      .maybeSingle();

    const apiKey = (geminiRow as { api_key_secret?: string } | null)?.api_key_secret;
    if (!apiKey) {
      return errorResponse("AI not configured", "CONFIG", 503);
    }

    const capsule = await getProviderContext(providerId);
    const contextBlock = capsule ? formatCapsuleForPrompt(capsule) : "No provider context.";
    const template = FEATURE_TEMPLATES[feature_key];
    const system = `${template.system}\n\n${contextBlock}`;
    const body = await request.json().catch(() => ({}));
    const userInput = (body as { input?: string }).input ?? "";
    const userPrompt = userInput ? `${template.userPrompt}\n\nAdditional context: ${userInput}` : template.userPrompt;

    const model = (geminiRow as { default_model?: string })?.default_model ?? template.model;
    const result = await callGemini({
      apiKey,
      model,
      system,
      user: userPrompt,
      temperature: 0.3,
      maxTokens: entitlementCheck.entitlement?.max_tokens ?? 600,
    });

    await logAiUsage({
      actor_user_id: user.id,
      provider_id: providerId,
      feature_key,
      model,
      tokens_in: result.tokensIn,
      tokens_out: result.tokensOut,
      cost_estimate: 0,
      success: result.success,
      error_code: result.errorCode ?? null,
    });

    if (!result.success) {
      return errorResponse(result.errorCode ?? "AI request failed", "AI_ERROR", 502);
    }

    let parsed: any = null;
    try {
      const trimmed = result.text.trim();
      const jsonMatch = trimmed.match(/\{[\s\S]*\}/);
      if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
    } catch {
      parsed = { raw: result.text };
    }

    return successResponse(parsed);
  } catch (error) {
    return handleApiError(error as Error, "AI request failed");
  }
}

import { NextRequest } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { getProviderRevenue } from "@/lib/reports/revenue-helpers";
import { subMonths, startOfMonth, endOfMonth } from "date-fns";

/**
 * GET /api/provider/analytics
 * 
 * Get provider analytics dashboard data (optimized)
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    
    // Use service role client for better performance
    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) {
      return successResponse({
        revenue: { total: 0, thisMonth: 0, lastMonth: 0, growth: "0" },
        bookings: { total: 0, thisMonth: 0, lastMonth: 0, upcoming: 0, growth: "0" },
        customers: { total: 0, repeat: 0, new: 0 },
        services: [],
        trends: [],
      });
    }

    const searchParams = request.nextUrl.searchParams;
    const _period = searchParams.get("period") || "month";

    // Calculate date ranges
    const now = new Date();
    const thisMonthStart = startOfMonth(now);
    const thisMonthEnd = endOfMonth(now);
    const lastMonthStart = startOfMonth(subMonths(now, 1));
    const lastMonthEnd = endOfMonth(subMonths(now, 1));
    const _twelveMonthsAgo = subMonths(now, 12);
    
    // Ensure this month query only includes up to current date (not future)
    const thisMonthEndDate = now < thisMonthEnd ? now : thisMonthEnd;

    // Parallel queries for better performance
    const [
      revenueResult,
      bookingsResult,
      upcomingBookingsResult,
      serviceDataResult,
      customerDataResult,
    ] = await Promise.all([
      // Revenue from finance_transactions (accurate provider earnings)
      Promise.all([
        getProviderRevenue(supabaseAdmin, providerId, new Date(0), now),
        getProviderRevenue(supabaseAdmin, providerId, thisMonthStart, thisMonthEndDate),
        getProviderRevenue(supabaseAdmin, providerId, lastMonthStart, lastMonthEnd),
      ]),
      // Booking counts (parallel queries)
      Promise.all([
        supabaseAdmin
          .from("bookings")
          .select("id, created_at", { count: "exact", head: true })
          .eq("provider_id", providerId),
        supabaseAdmin
          .from("bookings")
          .select("id")
          .eq("provider_id", providerId)
          .gte("created_at", thisMonthStart.toISOString())
          .lte("created_at", thisMonthEndDate.toISOString()),
        supabaseAdmin
          .from("bookings")
          .select("id")
          .eq("provider_id", providerId)
          .gte("created_at", lastMonthStart.toISOString())
          .lte("created_at", lastMonthEnd.toISOString()),
      ]),
      // Upcoming bookings
      supabaseAdmin
        .from("bookings")
        .select("id", { count: "exact", head: true })
        .eq("provider_id", providerId)
        .eq("status", "confirmed")
        .gt("scheduled_at", now.toISOString()),
      // Service popularity (simplified query)
      supabaseAdmin
        .from("booking_services")
        .select(`
          offering_id,
          price,
          offerings:offering_id (
            id,
            title
          )
        `)
        .eq("offerings.provider_id", providerId)
        .limit(1000), // Limit to prevent huge queries
      // Customer analytics
      supabaseAdmin
        .from("bookings")
        .select("customer_id")
        .eq("provider_id", providerId),
    ]);

    // Extract revenue data
    const [allTimeRevenue, thisMonthRevenueData, lastMonthRevenueData] = revenueResult;
    const totalRevenue = allTimeRevenue.totalRevenue;
    const thisMonthRevenue = thisMonthRevenueData.totalRevenue;
    const lastMonthRevenue = lastMonthRevenueData.totalRevenue;

    // Extract booking counts
    const [totalBookingsCount, thisMonthBookingsData, lastMonthBookingsData] = bookingsResult;
    const totalBookings = totalBookingsCount.count || 0;
    const thisMonthBookings = thisMonthBookingsData.data?.length || 0;
    const lastMonthBookings = lastMonthBookingsData.data?.length || 0;
    const upcomingBookings = upcomingBookingsResult.count || 0;

    // Process service stats
    const serviceStats = new Map<string, { name: string; count: number; revenue: number }>();
    if (serviceDataResult.data) {
      for (const service of serviceDataResult.data) {
        const offering = service.offerings as any;
        if (!offering) continue;
        const key = offering.id;
        if (!serviceStats.has(key)) {
          serviceStats.set(key, {
            name: offering.title || "Service",
            count: 0,
            revenue: 0,
          });
        }
        const stat = serviceStats.get(key)!;
        stat.count++;
        stat.revenue += Number(service.price || 0);
      }
    }

    // Revenue trends (last 12 months) - optimized single query approach
    const _trends: Array<{ month: string; revenue: number; bookings: number }> = [];
    const trendPromises: Promise<{ month: string; revenue: number; bookings: number }>[] = [];
    
    for (let i = 11; i >= 0; i--) {
      const monthDate = startOfMonth(subMonths(now, i));
      const monthEnd = endOfMonth(subMonths(now, i));
      const monthStr = monthDate.toLocaleDateString("en-US", { month: "short", year: "numeric" });

      trendPromises.push(
        Promise.all([
          getProviderRevenue(supabaseAdmin, providerId, monthDate, monthEnd),
          supabaseAdmin
            .from("bookings")
            .select("id", { count: "exact", head: true })
            .eq("provider_id", providerId)
            .gte("created_at", monthDate.toISOString())
            .lte("created_at", monthEnd.toISOString()),
        ]).then(([revenueData, bookingsData]) => ({
          month: monthStr,
          revenue: revenueData.totalRevenue,
          bookings: bookingsData.count || 0,
        }))
      );
    }

    const trendsData = await Promise.all(trendPromises);

    // Customer analytics
    const customerData = customerDataResult.data || [];
    const uniqueCustomers = new Set(customerData.map((b) => b.customer_id).filter(Boolean));
    const customerCounts = new Map<string, number>();
    customerData.forEach((b) => {
      if (b.customer_id) {
        customerCounts.set(b.customer_id, (customerCounts.get(b.customer_id) || 0) + 1);
      }
    });
    const repeatCustomers = Array.from(customerCounts.values()).filter((count) => count > 1).length;

    // Calculate growth percentages
    let revenueGrowth: string;
    if (lastMonthRevenue === 0) {
      revenueGrowth = thisMonthRevenue > 0 ? "New" : "0";
    } else {
      const growth = ((thisMonthRevenue - lastMonthRevenue) / lastMonthRevenue * 100);
      revenueGrowth = growth.toFixed(1);
    }

    let bookingsGrowth: string;
    if (lastMonthBookings === 0) {
      bookingsGrowth = thisMonthBookings > 0 ? "New" : "0";
    } else {
      const growth = ((thisMonthBookings - lastMonthBookings) / lastMonthBookings * 100);
      bookingsGrowth = growth.toFixed(1);
    }

    return successResponse({
      revenue: {
        total: totalRevenue,
        thisMonth: thisMonthRevenue,
        lastMonth: lastMonthRevenue,
        growth: revenueGrowth,
      },
      bookings: {
        total: totalBookings,
        thisMonth: thisMonthBookings,
        lastMonth: lastMonthBookings,
        upcoming: upcomingBookings,
        growth: bookingsGrowth,
      },
      customers: {
        total: uniqueCustomers.size,
        repeat: repeatCustomers,
        new: uniqueCustomers.size - repeatCustomers,
      },
      services: Array.from(serviceStats.values())
        .sort((a, b) => b.revenue - a.revenue)
        .slice(0, 10), // Top 10 services
      trends: trendsData,
    });
  } catch (error) {
    console.error("Error in analytics API:", error);
    return handleApiError(error, "Failed to fetch analytics");
  }
}

/**
 * Automation Execution API
 * 
 * This endpoint is called by a background job/cron service to execute automations.
 * It checks for automations that need to be triggered and sends messages via
 * the provider's configured Twilio/Mailchimp integrations.
 * 
 * Usage: This should be called periodically (e.g., every 5-15 minutes) by a cron job
 * or background service to check and execute pending automations.
 */

import { NextRequest } from "next/server";
import { successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { sendMessage } from "@/lib/marketing/unified-service";
import { subDays, subMinutes } from "date-fns";
import type { SupabaseClient } from "@supabase/supabase-js";

/**
 * POST /api/provider/automations/execute
 * 
 * Execute pending automations for all providers
 * This should be called by a cron job or background service
 */
export async function POST(request: NextRequest) {
  try {
    // Verify this is called from an authorized source (cron job, background service)
    const authHeader = request.headers.get("authorization");
    const cronSecret = process.env.CRON_SECRET || process.env.INTERNAL_API_SECRET;

    if (cronSecret && authHeader !== `Bearer ${cronSecret}`) {
      return handleApiError(
        new Error("Unauthorized - This endpoint requires cron secret"),
        "Unauthorized",
        "UNAUTHORIZED",
        401
      );
    }

    const supabaseAdmin = getSupabaseAdmin();
    const now = new Date();
    const executedAutomations: string[] = [];
    const errors: Array<{ automationId: string; error: string }> = [];

    // Get all active automations
    const { data: automations, error: automationsError } = await supabaseAdmin
      .from("marketing_automations")
      .select("*")
      .eq("is_active", true);

    if (automationsError) {
      throw automationsError;
    }

    if (!automations || automations.length === 0) {
      return successResponse({
        executed: 0,
        message: "No active automations to execute",
      });
    }

    // Process each automation
    for (const automation of automations) {
      try {
        const shouldExecute = await shouldExecuteAutomation(supabaseAdmin, automation, now);

        if (!shouldExecute.shouldRun) {
          continue;
        }

        // Get the target customer(s) for this automation
        const customers = await getAutomationRecipients(
          supabaseAdmin,
          automation.provider_id,
          automation.trigger_type,
          automation.trigger_config,
          shouldExecute.context
        );

        if (customers.length === 0) {
          continue; // No recipients for this automation
        }

        // Get automation message content
        const messageContent = await getAutomationMessage(
          automation,
          shouldExecute.context
        );

        if (!messageContent) {
          errors.push({
            automationId: automation.id,
            error: "No message content configured",
          });
          continue;
        }

        // Send messages to all recipients
        for (const customer of customers) {
          try {
            // Check if we've already sent this automation to this customer recently
            const alreadySent = await checkIfAlreadySent(
              supabaseAdmin,
              automation.id,
              customer.id,
              shouldExecute.context
            );

            if (alreadySent) {
              continue; // Skip - already sent
            }

            // Replace template variables in message
            const personalizedContent = personalizeMessage(
              messageContent.body,
              customer,
              shouldExecute.context
            );
            const personalizedSubject = personalizeMessage(
              messageContent.subject || "",
              customer,
              shouldExecute.context
            );

            const result = await sendMessage(
              automation.provider_id,
              automation.action_type as "email" | "sms" | "whatsapp",
              {
                to: customer.contact,
                subject: personalizedSubject || undefined,
                content: personalizedContent,
                fromName: messageContent.fromName,
              }
            );

            if (!result.success) {
              errors.push({
                automationId: automation.id,
                error: result.error || "Failed to send message",
              });
            } else {
              // Log successful execution to prevent duplicates
              await logAutomationExecution(
                supabaseAdmin,
                automation.id,
                customer.id,
                result.messageId ?? "",
                automation.action_type
              );
            }
          } catch (error: any) {
            errors.push({
              automationId: automation.id,
              error: error.message || "Failed to send message",
            });
          }
        }

        executedAutomations.push(automation.id);
      } catch (error: any) {
        errors.push({
          automationId: automation.id,
          error: error.message || "Failed to execute automation",
        });
      }
    }

    return successResponse({
      executed: executedAutomations.length,
      automationIds: executedAutomations,
      errors: errors.length > 0 ? errors : undefined,
    });
  } catch (error) {
    console.error("Error executing automations:", error);
    return handleApiError(error, "Failed to execute automations");
  }
}

/**
 * Determine if an automation should be executed now
 */
async function shouldExecuteAutomation(
  supabaseAdmin: SupabaseClient,
  automation: any,
  now: Date
): Promise<{ shouldRun: boolean; context?: any }> {
  const triggerType = automation.trigger_type;
  const triggerConfig = automation.trigger_config || {};
  const delayMinutes = automation.delay_minutes || 0;

  switch (triggerType) {
    case "appointment_reminder": {
      const hoursBefore = triggerConfig.hours_before || 24;
      const minutesBefore = triggerConfig.minutes_before || hoursBefore * 60;
      const targetTime = subMinutes(now, minutesBefore - delayMinutes);

      // Find appointments scheduled at the target time
      const { data: bookings } = await supabaseAdmin
        .from("bookings")
        .select("id, scheduled_at, customer_id, status")
        .eq("provider_id", automation.provider_id)
        .eq("status", "confirmed")
        .gte("scheduled_at", targetTime.toISOString())
        .lte("scheduled_at", new Date(targetTime.getTime() + 15 * 60 * 1000).toISOString()); // 15 min window

      if (bookings && bookings.length > 0) {
        return {
          shouldRun: true,
          context: { bookings },
        };
      }
      return { shouldRun: false };
    }

    case "booking_completed": {
      const targetTime = subMinutes(now, delayMinutes);
      const windowStart = subMinutes(targetTime, 15); // 15 min window

      // Find recently completed bookings
      const { data: bookings } = await supabaseAdmin
        .from("bookings")
        .select("id, customer_id, completed_at, status")
        .eq("provider_id", automation.provider_id)
        .eq("status", "completed")
        .gte("completed_at", windowStart.toISOString())
        .lte("completed_at", targetTime.toISOString());

      if (bookings && bookings.length > 0) {
        return {
          shouldRun: true,
          context: { bookings },
        };
      }
      return { shouldRun: false };
    }

    case "appointment_no_show": {
      const targetTime = subMinutes(now, delayMinutes);
      const windowStart = subMinutes(targetTime, 15);

      // Find no-show appointments
      const { data: bookings } = await supabaseAdmin
        .from("bookings")
        .select("id, customer_id, scheduled_at, status")
        .eq("provider_id", automation.provider_id)
        .eq("status", "no_show")
        .gte("scheduled_at", windowStart.toISOString())
        .lte("scheduled_at", targetTime.toISOString());

      if (bookings && bookings.length > 0) {
        return {
          shouldRun: true,
          context: { bookings },
        };
      }
      return { shouldRun: false };
    }

    case "client_inactive": {
      const days = triggerConfig.days || 30;
      const _cutoffDate = subDays(now, days);

      // Find clients who haven't booked since cutoff date
      const { data: inactiveClients } = await supabaseAdmin
        .rpc("get_inactive_clients", {
          p_provider_id: automation.provider_id,
          p_days: days,
        });

      if (inactiveClients && inactiveClients.length > 0) {
        return {
          shouldRun: true,
          context: { clients: inactiveClients },
        };
      }
      return { shouldRun: false };
    }

    case "client_birthday": {
      // Check for clients with birthdays today who have booked with this provider
      // Get distinct customers who have booked with this provider
      const { data: providerBookings } = await supabaseAdmin
        .from("bookings")
        .select("customer_id")
        .eq("provider_id", automation.provider_id)
        .not("customer_id", "is", null);

      if (!providerBookings || providerBookings.length === 0) {
        return { shouldRun: false };
      }

      const customerIds = [...new Set(providerBookings.map((b: any) => b.customer_id))];

      // Find which of these customers have birthdays today
      // Users table has date_of_birth (DATE type)
      const month = now.getMonth() + 1; // 1-12
      const day = now.getDate();

      const { data: birthdayUsers } = await supabaseAdmin
        .from("users")
        .select("id")
        .in("id", customerIds)
        .not("date_of_birth", "is", null);

      // Filter users whose birthday is today
      const birthdayClients = birthdayUsers?.filter((user: any) => {
        if (!user.date_of_birth) return false;
        const birthDate = new Date(user.date_of_birth);
        return birthDate.getMonth() + 1 === month && birthDate.getDate() === day;
      }).map((user: any) => ({ user_id: user.id })) || [];

      if (birthdayClients.length > 0) {
        return {
          shouldRun: true,
          context: { clients: birthdayClients },
        };
      }
      return { shouldRun: false };
    }

    case "appointment_rescheduled": {
      const targetTime = subMinutes(now, delayMinutes);
      const windowStart = subMinutes(targetTime, 15);

      // Find recently rescheduled appointments
      const { data: bookings } = await supabaseAdmin
        .from("bookings")
        .select("id, customer_id, updated_at, status")
        .eq("provider_id", automation.provider_id)
        .eq("status", "rescheduled")
        .gte("updated_at", windowStart.toISOString())
        .lte("updated_at", targetTime.toISOString());

      if (bookings && bookings.length > 0) {
        return {
          shouldRun: true,
          context: { bookings },
        };
      }
      return { shouldRun: false };
    }

    case "new_lead": {
      const minutesAgo = triggerConfig.minutes || delayMinutes || 60;
      const targetTime = subMinutes(now, minutesAgo);
      const windowStart = subMinutes(targetTime, 15);

      // Find new inquiries/leads (bookings with status 'pending' or 'inquiry')
      const { data: leads } = await supabaseAdmin
        .from("bookings")
        .select("id, customer_id, created_at, status")
        .eq("provider_id", automation.provider_id)
        .in("status", ["pending", "inquiry"])
        .gte("created_at", windowStart.toISOString())
        .lte("created_at", targetTime.toISOString());

      if (leads && leads.length > 0) {
        return {
          shouldRun: true,
          context: { bookings: leads },
        };
      }
      return { shouldRun: false };
    }

    case "package_expiring": {
      const daysBefore = triggerConfig.days_before || 7;
      const expiryDate = new Date(now);
      expiryDate.setDate(expiryDate.getDate() + daysBefore);

      // Find packages expiring soon
      const { data: packages } = await supabaseAdmin
        .from("service_packages")
        .select("id, customer_id, expires_at")
        .eq("provider_id", automation.provider_id)
        .eq("is_active", true)
        .lte("expires_at", expiryDate.toISOString())
        .gte("expires_at", now.toISOString());

      if (packages && packages.length > 0) {
        return {
          shouldRun: true,
          context: { packages },
        };
      }
      return { shouldRun: false };
    }

    case "visit_milestone": {
      const visitCount = triggerConfig.visit_count || 10;

      // Find clients who have reached the visit milestone
      const { data: milestoneClients } = await supabaseAdmin
        .rpc("get_clients_by_visit_count", {
          p_provider_id: automation.provider_id,
          p_visit_count: visitCount,
        });

      if (milestoneClients && milestoneClients.length > 0) {
        return {
          shouldRun: true,
          context: { clients: milestoneClients },
        };
      }
      return { shouldRun: false };
    }

    case "client_anniversary": {
      const years = triggerConfig.years || 1;
      const anniversaryDate = new Date(now);
      anniversaryDate.setFullYear(anniversaryDate.getFullYear() - years);

      // Find clients who first booked exactly X years ago (within a 7-day window)
      const { data: anniversaryClients } = await supabaseAdmin
        .rpc("get_clients_by_first_booking_date", {
          p_provider_id: automation.provider_id,
          p_years_ago: years,
        });

      if (anniversaryClients && anniversaryClients.length > 0) {
        return {
          shouldRun: true,
          context: { clients: anniversaryClients },
        };
      }
      return { shouldRun: false };
    }

    case "referral_received": {
      const targetTime = subMinutes(now, delayMinutes);
      const windowStart = subMinutes(targetTime, 60); // 1 hour window

      // Bookings tagged with a provider referral source (e.g. Instagram, Friend) from Settings ΓåÆ Referral Sources
      const { data: referrals } = await supabaseAdmin
        .from("bookings")
        .select("id, customer_id, created_at, referral_source_id")
        .eq("provider_id", automation.provider_id)
        .not("referral_source_id", "is", null)
        .gte("created_at", windowStart.toISOString())
        .lte("created_at", targetTime.toISOString());

      if (referrals && referrals.length > 0) {
        return {
          shouldRun: true,
          context: { bookings: referrals },
        };
      }
      return { shouldRun: false };
    }

    case "seasonal_promotion": {
      // Check if it's a seasonal period (e.g., holidays, summer, etc.)
      // This is a simple implementation - you might want more sophisticated logic
      const month = now.getMonth() + 1; // 1-12
      const day = now.getDate();

      // Example: Check for major holidays or seasonal periods
      const isHolidaySeason = (month === 11 && day >= 20) || (month === 12) || (month === 1 && day <= 7); // Nov 20 - Jan 7
      const isSummer = month >= 6 && month <= 8;
      const isValentines = month === 2 && day >= 10 && day <= 16;

      if (isHolidaySeason || isSummer || isValentines) {
        // Get active clients for seasonal promotion
        const { data: activeClients } = await supabaseAdmin
          .rpc("get_active_clients", {
            p_provider_id: automation.provider_id,
            p_days: 90, // Active in last 90 days
          });

        if (activeClients && activeClients.length > 0) {
          return {
            shouldRun: true,
            context: { clients: activeClients },
          };
        }
      }
      return { shouldRun: false };
    }

    case "holiday": {
      // Similar to seasonal, but more specific to holidays
      const month = now.getMonth() + 1;
      const day = now.getDate();

      // Major holidays
      const isHoliday = 
        (month === 1 && day === 1) || // New Year
        (month === 2 && day === 14) || // Valentine's
        (month === 12 && day === 25) || // Christmas
        (month === 12 && day === 31); // New Year's Eve

      if (isHoliday) {
        const { data: clients } = await supabaseAdmin
          .rpc("get_active_clients", {
            p_provider_id: automation.provider_id,
            p_days: 180,
          });

        if (clients && clients.length > 0) {
          return {
            shouldRun: true,
            context: { clients },
          };
        }
      }
      return { shouldRun: false };
    }

    // Add more trigger types as needed
    default:
      console.warn(`Unsupported trigger type: ${triggerType}`);
      return { shouldRun: false };
  }
}

