import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { generateOTP, getOTPExpiry } from "@/lib/otp/generator";
import { sendOTPToCustomer } from "@/lib/otp/notifications";
import { generateVerificationCode, getQRCodeExpiry, type QRCodeData } from "@/lib/qr/generator";
import { getVerificationSettings } from "@/lib/platform-settings";
import type { Booking } from "@/types/beautonomi";

/**
 * POST /api/provider/bookings/[id]/arrive
 * 
 * Mark provider as arrived and generate OTP for customer verification
 * Only for at-home bookings
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer(request);
    const { id } = await params;
    const body = await request.json();
    const { latitude, longitude } = body; // Optional: provider's current location

    // Get provider ID
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Get provider business name
    const { data: provider } = await supabase
      .from("providers")
      .select("business_name")
      .eq("id", providerId)
      .single();

    const providerData = provider as any;

    // Get booking details
    const { data: booking, error: bookingError } = await supabase
      .from("bookings")
      .select(`
        *,
        customers:users!bookings_customer_id_fkey(id, full_name, email, phone)
      `)
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (bookingError || !booking) {
      return notFoundResponse("Booking not found");
    }

    const bookingData = booking as any;

    // Only allow for at-home bookings
    if (bookingData.location_type !== "at_home") {
      return errorResponse("This endpoint is only for at-home bookings", "INVALID_REQUEST", 400);
    }

    // Check if booking is in correct state
    if (bookingData.status !== "confirmed" && bookingData.current_stage !== "provider_on_way") {
      return errorResponse("Provider must start journey before arriving", "INVALID_STATUS", 400);
    }

    // Get platform verification settings
    const verificationSettings = await getVerificationSettings();
    const { otp_enabled, qr_code_enabled, require_verification } = verificationSettings;

    // If verification is not required, just mark as arrived without OTP/QR code
    if (!require_verification) {
      // Create booking event
      const { error: eventError } = await supabase
        .from("booking_events")
        .insert({
          booking_id: id,
          event_type: "provider_arrived",
          event_data: {
            location: latitude && longitude ? { lat: latitude, lng: longitude } : null,
            arrived_at: new Date().toISOString(),
            verification_method: "simple_confirmation",
          },
          created_by: user.id,
        });

      if (eventError) {
        throw eventError;
      }

      // Update booking - simple confirmation, no verification needed
      const { error: updateError } = await supabase
        .from("bookings")
        .update({
          current_stage: "provider_arrived",
          arrival_otp_verified: true, // Auto-verified with simple confirmation
          qr_code_verified: true,
          updated_at: new Date().toISOString(),
        })
        .eq("id", id);

      if (updateError) {
        throw updateError;
      }

      // Fetch updated booking
      const { data: updatedBooking } = await supabase
        .from("bookings")
        .select("*")
        .eq("id", id)
        .single();

      return successResponse({
        booking: updatedBooking as Booking,
        otp: null,
        qr_code: null,
        verification_code: null,
        message: "Arrival confirmed (simple confirmation mode)",
      });
    }

    // Verification is required - generate OTP and/or QR code based on settings
    // Validate that at least one verification method is enabled
    if (!otp_enabled && !qr_code_enabled) {
      // If both are disabled but verification is required, this is an invalid state
      // Fall back to simple confirmation
      console.warn("Verification required but both OTP and QR code are disabled. Using simple confirmation.");
      // Continue with simple confirmation logic below
    }

    let otp: string | null = null;
    let otpExpiresAt: Date | null = null;
    if (otp_enabled) {
      otp = generateOTP();
      otpExpiresAt = getOTPExpiry();
    }

    // Generate QR code if enabled
    let qrVerificationCode: string | null = null;
    let qrExpiresAt: Date | null = null;
    let qrCodeData: QRCodeData | null = null;
    if (qr_code_enabled) {
      qrVerificationCode = generateVerificationCode();
      qrExpiresAt = getQRCodeExpiry();
      qrCodeData = {
        booking_id: id,
        booking_number: bookingData.booking_number,
        verification_code: qrVerificationCode,
        expires_at: qrExpiresAt.toISOString(),
        type: "arrival_verification",
      };
    }

    // If both verification methods are disabled, treat as simple confirmation
    if (!otp_enabled && !qr_code_enabled) {
      // Update booking - simple confirmation, no verification needed
      const { error: updateError } = await supabase
        .from("bookings")
        .update({
          current_stage: "provider_arrived",
          arrival_otp_verified: true, // Auto-verified with simple confirmation
          qr_code_verified: true,
          updated_at: new Date().toISOString(),
        })
        .eq("id", id);

      if (updateError) {
        throw updateError;
      }

      // Fetch updated booking
      const { data: updatedBooking } = await supabase
        .from("bookings")
        .select("*")
        .eq("id", id)
        .single();

      return successResponse({
        booking: updatedBooking as Booking,
        otp: null,
        qr_code: null,
        verification_code: null,
        message: "Arrival confirmed (simple confirmation mode - verification methods disabled)",
      });
    }

    // Create booking event
    const { error: eventError } = await supabase
      .from("booking_events")
      .insert({
        booking_id: id,
        event_type: "provider_arrived",
        event_data: {
          otp: otp,
          qr_code: qrCodeData,
          location: latitude && longitude ? { lat: latitude, lng: longitude } : null,
          arrived_at: new Date().toISOString(),
        },
        created_by: user.id,
      });

    if (eventError) {
      throw eventError;
    }

    // Create OTP sent event if OTP is enabled
    if (otp_enabled && otp && otpExpiresAt) {
      await supabase
        .from("booking_events")
        .insert({
          booking_id: id,
          event_type: "otp_sent",
          event_data: {
            otp: otp,
            expires_at: otpExpiresAt.toISOString(),
          },
          created_by: user.id,
        });
    }

    // Create QR code generated event if QR code is enabled
    if (qr_code_enabled && qrCodeData && qrExpiresAt) {
      await supabase
        .from("booking_events")
        .insert({
          booking_id: id,
          event_type: "qr_code_generated",
          event_data: {
            qr_code: qrCodeData,
            expires_at: qrExpiresAt.toISOString(),
          },
          created_by: user.id,
        });
    }

    // Update booking with OTP and/or QR code based on settings
    const updateData: any = {
      current_stage: "provider_arrived",
      updated_at: new Date().toISOString(),
    };

    if (otp_enabled && otp && otpExpiresAt) {
      updateData.arrival_otp = otp;
      updateData.arrival_otp_expires_at = otpExpiresAt.toISOString();
      updateData.arrival_otp_verified = false;
    } else {
      // If OTP is disabled, clear OTP fields
      updateData.arrival_otp = null;
      updateData.arrival_otp_expires_at = null;
      updateData.arrival_otp_verified = false;
    }

    if (qr_code_enabled && qrCodeData && qrVerificationCode && qrExpiresAt) {
      updateData.qr_code_data = qrCodeData;
      updateData.qr_code_verification_code = qrVerificationCode;
      updateData.qr_code_expires_at = qrExpiresAt.toISOString();
      updateData.qr_code_verified = false;
    } else {
      // If QR code is disabled, clear QR code fields
      updateData.qr_code_data = null;
      updateData.qr_code_verification_code = null;
      updateData.qr_code_expires_at = null;
      updateData.qr_code_verified = false;
    }

    const { error: updateError } = await supabase
      .from("bookings")
      .update(updateData)
      .eq("id", id);

    if (updateError) {
      throw updateError;
    }

    // Send OTP to customer if enabled
    const customer = bookingData.customers;
    if (customer && otp_enabled && otp) {
      try {
        await sendOTPToCustomer({
          customerId: customer.id,
          phone: customer.phone || "",
          email: customer.email || "",
          otp: otp,
          bookingNumber: bookingData.booking_number,
          providerName: providerData?.business_name || "Provider",
          customerName: customer.full_name || "Customer",
        });
      } catch (otpError) {
        // If OTP sending fails, log but don't fail the request
        // QR code is still available as fallback
        console.error("Failed to send OTP, QR code available as fallback:", otpError);
      }
    }

    // Fetch updated booking
    const { data: updatedBooking } = await supabase
      .from("bookings")
      .select("*")
      .eq("id", id)
      .single();

    return successResponse({
      booking: updatedBooking as Booking,
      otp: otp, // Return OTP for provider to manually share if needed (null if disabled)
      qr_code: qrCodeData, // Return QR code data (null if disabled)
      verification_code: qrVerificationCode, // QR code verification code (null if disabled)
      message: !require_verification
        ? "Arrival confirmed (simple confirmation mode)"
        : otp_enabled && qr_code_enabled && otp && qrCodeData
        ? "OTP and QR code generated. OTP sent to customer."
        : otp_enabled && otp
        ? "OTP generated and sent to customer."
        : qr_code_enabled && qrCodeData
        ? "QR code generated for verification."
        : "Arrival marked. No verification required.",
    });
  } catch (error) {
    return handleApiError(error, "Failed to mark provider as arrived");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/provider/bookings/[id]/audit-log
 * 
 * Get audit log for a specific booking
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer(request);
    const { id } = await params;

    // Get provider ID
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return successResponse([]);
    }

    // Verify booking belongs to provider
    const { data: booking } = await supabase
      .from("bookings")
      .select("id")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (!booking) {
      return successResponse([]);
    }

    // Get audit log entries
    const { data: auditLogs, error } = await supabase
      .from("booking_audit_log")
      .select(`
        *,
        created_by_user:users!booking_audit_log_created_by_fkey(full_name, email)
      `)
      .eq("booking_id", id)
      .order("created_at", { ascending: false });

    if (error) {
      console.error("Error fetching audit log:", error);
      return successResponse([]);
    }

    // Transform to include user names
    const transformedLogs = (auditLogs || []).map((log: any) => ({
      id: log.id,
      booking_id: log.booking_id,
      event_type: log.event_type,
      event_data: log.event_data,
      created_by: log.created_by,
      created_by_name: log.created_by_user?.full_name || log.created_by_user?.email || "System",
      created_at: log.created_at,
    }));

    return successResponse(transformedLogs);
  } catch (error) {
    return handleApiError(error, "Failed to fetch audit log");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import type { Booking } from "@/types/beautonomi";
import { awardPointsForBooking, checkProviderMilestones } from "@/lib/services/provider-gamification";

/**
 * POST /api/provider/bookings/[id]/complete-service
 * 
 * Mark service as completed.
 * Awards both provider reward points and customer loyalty points (only on completion).
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer(request);
    const { id } = await params;

    // Get provider ID
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Get booking
    const { data: booking, error: bookingError } = await supabase
      .from("bookings")
      .select("*")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (bookingError || !booking) {
      return notFoundResponse("Booking not found");
    }

    const bookingData = booking as any;

    // Check if service is in progress
    if (bookingData.status !== "in_progress" && bookingData.current_stage !== "service_started") {
      return errorResponse("Service must be started before completing", "INVALID_STATUS", 400);
    }

    // Create booking event
    const { error: eventError } = await supabase
      .from("booking_events")
      .insert({
        booking_id: id,
        event_type: "service_completed",
        event_data: {
          completed_at: new Date().toISOString(),
        },
        created_by: user.id,
      });

    if (eventError) {
      console.error("Error creating booking event:", eventError);
    }

    // Update booking
    const { error: updateError } = await supabase
      .from("bookings")
      .update({
        status: "completed",
        current_stage: "service_completed",
        completed_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .eq("id", id);

    if (updateError) {
      throw updateError;
    }

    // Fetch updated booking
    const { data: updatedBooking } = await supabase
      .from("bookings")
      .select("*")
      .eq("id", id)
      .single();

    // Award provider reward points and customer loyalty points (non-blocking, only on completion)
    if (updatedBooking) {
      awardPointsForBooking(providerId, id).catch(err => 
        console.error('Failed to award provider points for booking:', err)
      );
      checkProviderMilestones(providerId).catch(err => 
        console.error('Failed to check milestones:', err)
      );

      // Award customer loyalty points for completed booking (using loyalty_rules)
      const customerId = (updatedBooking as any).customer_id;
      const subtotal = (updatedBooking as any).subtotal || 0;
      if (subtotal > 0 && customerId) {
        (async () => {
          try {
            const supabaseAdmin = await getSupabaseAdmin();
            const { calculateLoyaltyPoints } = await import("@/lib/loyalty/calculate-points");
            const { data: existing } = await supabaseAdmin
              .from("loyalty_point_transactions")
              .select("id")
              .eq("reference_id", id)
              .eq("reference_type", "booking")
              .eq("transaction_type", "earned")
              .maybeSingle();
            if (!existing) {
              const currency = (updatedBooking as any).currency || "ZAR";
              const pointsEarned = await calculateLoyaltyPoints(subtotal, supabaseAdmin, currency);
              if (pointsEarned > 0) {
                await supabaseAdmin.from("loyalty_point_transactions").insert({
                  user_id: customerId,
                  transaction_type: "earned",
                  points: pointsEarned,
                  description: `Points earned for completed booking ${(updatedBooking as any).booking_number || id}`,
                  reference_id: id,
                  reference_type: "booking",
                  expires_at: null,
                });
                await supabaseAdmin.from("bookings").update({ loyalty_points_earned: pointsEarned }).eq("id", id);
              }
            }
          } catch (err) {
            console.error('Failed to award customer loyalty points on completion:', err);
          }
        })();
      }
    }

    return successResponse({
      booking: updatedBooking as Booking,
      message: "Service completed successfully",
    });
  } catch (error) {
    return handleApiError(error, "Failed to complete service");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { getProviderIdForUser, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";

/**
 * POST /api/provider/bookings/[id]/mark-paid
 * 
 * Mark a booking as paid (cash/card/other payment method)
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Check permission to process payments
    const permissionCheck = await requirePermission('process_payments', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    if (!user) return notFoundResponse("User not found");

    const supabase = await getSupabaseServer(request);
    const supabaseAdmin = await getSupabaseAdmin();
    const { id: bookingId } = await params;
    const body = await request.json();

    // Get provider ID
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Validate input
    const { 
      payment_method, 
      amount, 
      notes,
      reference 
    } = body;

    if (!payment_method || !['cash', 'card', 'mobile', 'bank_transfer', 'other'].includes(payment_method)) {
      return errorResponse(
        "Valid payment_method is required (cash, card, mobile, bank_transfer, other)",
        "VALIDATION_ERROR",
        400
      );
    }

    // Verify booking exists and belongs to provider
    const { data: booking, error: bookingError } = await supabase
      .from("bookings")
      .select("id, total_amount, payment_status, provider_id, customer_id, booking_number, ref_number, total_paid, location_id, location_type")
      .eq("id", bookingId)
      .eq("provider_id", providerId)
      .single();

    if (bookingError || !booking) {
      return notFoundResponse("Booking not found");
    }

    // If booking is missing location_id and it's an at_salon booking, set it to provider's first location
    if (!booking.location_id && booking.location_type === "at_salon") {
      const { data: providerLocations } = await supabaseAdmin
        .from("provider_locations")
        .select("id")
        .eq("provider_id", providerId)
        .order("created_at", { ascending: true })
        .limit(1);

      if (providerLocations && providerLocations.length > 0) {
        const defaultLocationId = providerLocations[0].id;
        const { error: updateError } = await supabaseAdmin
          .from("bookings")
          .update({ location_id: defaultLocationId })
          .eq("id", bookingId);

        if (!updateError) {
          console.log(`Updated booking ${bookingId} with location_id ${defaultLocationId}`);
        } else {
          console.warn(`Failed to update location_id for booking ${bookingId}:`, updateError);
        }
      }
    }

    // Check if already fully paid
    const currentTotalPaid = booking.total_paid || 0;
    const bookingTotal = booking.total_amount || 0;
    const remainingBalance = bookingTotal - currentTotalPaid;

    if (currentTotalPaid >= bookingTotal) {
      return errorResponse(
        "Booking is already fully paid",
        "ALREADY_PAID",
        400
      );
    }

    // Use provided amount or remaining balance (to avoid overpayment)
    // If amount is provided and it's the full total, use it
    // Otherwise, use the remaining balance
    let paymentAmount: number;
    if (amount) {
      // If user explicitly provided an amount, use it (but warn if it exceeds remaining)
      paymentAmount = amount;
      if (paymentAmount > remainingBalance) {
        console.warn(`Payment amount (${paymentAmount}) exceeds remaining balance (${remainingBalance}). Using provided amount.`);
      }
    } else {
      // Default to remaining balance to complete the payment
      paymentAmount = remainingBalance;
    }

    if (paymentAmount <= 0) {
      return errorResponse(
        "Payment amount must be greater than 0",
        "VALIDATION_ERROR",
        400
      );
    }

    // Determine payment provider based on method
    let paymentProvider = 'other';
    if (payment_method === 'cash') {
      paymentProvider = 'cash';
    } else if (payment_method === 'card') {
      paymentProvider = 'yoco'; // Yoco card terminal or manual terminal
    }

    // Create payment record using a database function to properly handle enum types
    // The status column is an enum, and there may be triggers that also need enum values
    // Using RPC ensures proper type casting
    let payment: any = null;
    let paymentError: any = null;

    // Try using a database function first (if it exists)
    try {
      const { data: rpcPayment, error: rpcError } = await supabaseAdmin.rpc(
        'create_booking_payment',
        {
          p_booking_id: bookingId,
          p_amount: paymentAmount,
          p_payment_method: payment_method,
          p_payment_provider: paymentProvider,
          p_status: 'completed',
          p_notes: notes || `Payment received via ${payment_method}`,
          p_created_by: user.id,
          p_reference: reference || null,
        }
      );

      if (!rpcError && rpcPayment) {
        payment = Array.isArray(rpcPayment) ? rpcPayment[0] : rpcPayment;
      } else if (rpcError && !rpcError.message?.includes('function') && !rpcError.message?.includes('does not exist')) {
        paymentError = rpcError;
      }
    } catch {
      // RPC function doesn't exist or failed, continue to fallback
      console.log("RPC function not available, using direct insert");
    }

    // Fallback: Direct insert (may fail due to enum, but we'll handle it)
    if (!payment && !paymentError) {
      const paymentData: any = {
        booking_id: bookingId,
        amount: paymentAmount,
        payment_method,
        payment_provider: paymentProvider,
        status: 'completed', // Explicitly set status to 'completed' so trigger counts it
        notes: notes || `Payment received via ${payment_method}`,
        created_by: user.id,
      };

      if (reference) {
        paymentData.reference = reference;
      }

      // Try insert with status
      const { data: paymentInserted, error: insertError } = await supabaseAdmin
        .from("booking_payments")
        .insert(paymentData)
        .select()
        .single();

      if (insertError) {
        // If insert fails due to status enum, try without status and update after
        if (insertError.message?.includes('status') || insertError.message?.includes('enum')) {
          delete paymentData.status;
          const { data: paymentWithoutStatus, error: insertError2 } = await supabaseAdmin
            .from("booking_payments")
            .insert(paymentData)
            .select()
            .single();

          if (insertError2) {
            paymentError = insertError2;
          } else {
            payment = paymentWithoutStatus;
            // Update status after insert
            const { error: updateError } = await supabaseAdmin
              .from("booking_payments")
              .update({ status: 'completed' })
              .eq("id", payment.id);

            if (updateError) {
              console.warn("Failed to update payment status after insert:", updateError);
              // Payment was created but status might not be set - trigger should still work
            } else {
              // Refresh to get updated status
              const { data: updated } = await supabaseAdmin
                .from("booking_payments")
                .select()
                .eq("id", payment.id)
                .single();
              if (updated) payment = updated;
            }
          }
        } else {
          paymentError = insertError;
        }
      } else {
        payment = paymentInserted;

        // Verify status is set correctly
        if (payment && payment.status !== 'completed') {
          const { error: updateError } = await supabaseAdmin
            .from("booking_payments")
            .update({ status: 'completed' })
            .eq("id", payment.id);

          if (!updateError) {
            // Refresh to get updated status
            const { data: updated } = await supabaseAdmin
              .from("booking_payments")
              .select()
              .eq("id", payment.id)
              .single();
            if (updated) payment = updated;
          }
        }
      }
    }

    if (paymentError || !payment) {
      console.error("Error creating payment record:", paymentError);
      const errorMessage = paymentError?.message || "Failed to create payment record";
      const errorDetails = paymentError?.details || paymentError;

      // Provide helpful error message for enum type issues
      if (errorMessage.includes('payment_status') && errorMessage.includes('enum')) {
        return errorResponse(
          `Database enum error: The payment_status trigger needs to be updated to cast enum values properly. Please run migration 140_fix_payment_status_enum_cast.sql to fix this. Error: ${errorMessage}`,
          "PAYMENT_ENUM_ERROR",
          500,
          errorDetails
        );
      }

      return errorResponse(
        errorMessage,
        "PAYMENT_CREATE_ERROR",
        500,
        errorDetails
      );
    }

    // Verify payment was created with correct status and amount
    if (payment.status !== 'completed') {
      console.warn(`Payment created with status '${payment.status}' instead of 'completed'. Attempting to fix...`);
      const { error: fixError } = await supabaseAdmin
        .from("booking_payments")
        .update({ status: 'completed' })
        .eq("id", payment.id);

      if (fixError) {
        console.error("Failed to fix payment status:", fixError);
      } else {
        // Refresh payment to get updated status
        const { data: updatedPayment } = await supabaseAdmin
          .from("booking_payments")
          .select()
          .eq("id", payment.id)
          .single();
        if (updatedPayment) {
          payment = updatedPayment;
        }
      }
    }

    // Verify the trigger updated the booking correctly
    // Wait a moment for trigger to execute, then check
    await new Promise(resolve => setTimeout(resolve, 100));

    const { data: updatedBooking } = await supabaseAdmin
      .from("bookings")
      .select("total_paid, payment_status")
      .eq("id", bookingId)
      .single();

    if (updatedBooking) {
      console.log(`Payment created: R${paymentAmount.toFixed(2)}. Booking total_paid: R${(updatedBooking.total_paid || 0).toFixed(2)}, status: ${updatedBooking.payment_status}`);

      // If total_paid doesn't match expected, log warning
      const expectedTotalPaid = (currentTotalPaid || 0) + paymentAmount;
      if (Math.abs((updatedBooking.total_paid || 0) - expectedTotalPaid) > 0.01) {
        console.warn(`Payment trigger may not have fired correctly. Expected total_paid: R${expectedTotalPaid.toFixed(2)}, Actual: R${(updatedBooking.total_paid || 0).toFixed(2)}`);
      }
    }

    // Note: Booking payment status will be automatically updated by database trigger
    // The trigger update_booking_payment_status() handles this based on payment records

    // Create notification for customer (will be sent via OneSignal)
    try {
      await supabaseAdmin.from("notifications").insert({
        user_id: booking.customer_id,
        type: "payment_received",
        title: "Payment Confirmed",
        message: `Your payment of R${paymentAmount.toFixed(2)} has been received and confirmed.`,
        metadata: {
          booking_id: bookingId,
          payment_id: payment.id,
          amount: paymentAmount,
          payment_method,
        },
        link: `/account-settings/bookings/${bookingId}`,
      });

      // Send push notification via OneSignal using template
      try {
        const { sendTemplateNotification } = await import("@/lib/notifications/onesignal");
        const bookingRef = booking.ref_number || booking.booking_number || bookingId.slice(0, 8).toUpperCase();
        await sendTemplateNotification(
          "payment_successful",
          [booking.customer_id],
          {
            amount: `R${paymentAmount.toFixed(2)}`,
            booking_number: bookingRef,
            payment_method: payment_method,
            transaction_id: payment.id,
            booking_id: bookingId,
          },
          ["push", "email"]
        );
      } catch (pushError) {
        console.warn("OneSignal push notification failed:", pushError);
      }
    } catch (notifError) {
      console.warn("Failed to create payment notification:", notifError);
    }

    return successResponse({ 
      payment,
      message: "Booking marked as paid successfully" 
    });
  } catch (error) {
    return handleApiError(error, "Failed to mark booking as paid");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
