import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import {
  successResponse,
  handleApiError,
  getProviderIdForUser,
} from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";

/**
 * GET /api/provider/clients/conversations
 * Get all customers that have had conversations with the provider
 */
export async function GET(request: NextRequest) {
  try {
    // Check permission to view clients (pass request for Bearer token from mobile)
    const permissionCheck = await requirePermission("view_clients", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const supabaseAdmin = await getSupabaseAdmin(); // Use admin client to bypass RLS
    const { searchParams } = new URL(request.url);
    const _locationId = searchParams.get("location_id");
    const searchQuery = searchParams.get("search");
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return handleApiError(new Error("Provider not found"), "Provider account required", 403);
    }

    // Get provider's user_id to exclude self-conversations
    const { data: providerData } = await supabase
      .from("providers")
      .select("user_id")
      .eq("id", providerId)
      .single();
    
    const providerUserId = providerData?.user_id;

    // Get all unique customers from conversations
    // First, get conversations with messages (either have last_message_preview or have messages)
    let conversationsQuery = supabase
      .from("conversations")
      .select("customer_id, last_message_at, last_message_preview, created_at")
      .eq("provider_id", providerId)
      .not("last_message_preview", "is", null); // Only get conversations with a message preview
    
    // Exclude conversations where provider is messaging themselves
    if (providerUserId) {
      conversationsQuery = conversationsQuery.neq("customer_id", providerUserId);
    }
    
    const { data: conversations, error: conversationsError } = await conversationsQuery;

    if (conversationsError) {
      throw conversationsError;
    }

    if (!conversations || conversations.length === 0) {
      return successResponse([]);
    }

    // Get unique customer IDs
    const customerIds = [...new Set(conversations.map((c: any) => c.customer_id).filter(Boolean))];
    
    if (customerIds.length === 0) {
      return successResponse([]);
    }

    // Get customer details using admin client to bypass RLS
    const { data: customers, error: customersError } = await supabaseAdmin
      .from("users")
      .select("id, full_name, email, phone, avatar_url, rating_average, review_count, date_of_birth, email_notifications_enabled, sms_notifications_enabled")
      .in("id", customerIds);

    if (customersError) {
      console.error("Error fetching customer data from conversations:", customersError);
      throw customersError;
    }

    // Group conversations by customer and get the most recent message date
    const customerConversations: Record<
      string,
      {
        customer_id: string;
        last_message_date: string;
        conversation_count: number;
      }
    > = {};

    conversations.forEach((conv: any) => {
      if (!conv.customer_id) return;

      if (!customerConversations[conv.customer_id]) {
        customerConversations[conv.customer_id] = {
          customer_id: conv.customer_id,
          last_message_date: conv.last_message_at || conv.created_at,
          conversation_count: 0,
        };
      }

      customerConversations[conv.customer_id].conversation_count += 1;

      // Update last message date if this is more recent
      const convDate = conv.last_message_at || conv.created_at;
      if (new Date(convDate) > new Date(customerConversations[conv.customer_id].last_message_date)) {
        customerConversations[conv.customer_id].last_message_date = convDate;
      }
    });

    // Get saved client IDs to mark which ones are already saved
    const { data: savedClients } = await supabase
      .from("provider_clients")
      .select("customer_id")
      .eq("provider_id", providerId)
      .in("customer_id", customerIds);

    const savedCustomerIds = new Set(savedClients?.map((c) => c.customer_id) || []);

    // Get booking stats for these customers (to show if they've booked)
    const { data: bookings } = await supabase
      .from("bookings")
      .select("customer_id, completed_at, total_amount")
      .eq("provider_id", providerId)
      .in("customer_id", customerIds)
      .eq("status", "completed");

    // Calculate booking stats per customer
    const bookingStats: Record<string, { total_bookings: number; total_spent: number; last_service_date?: string }> = {};
    bookings?.forEach((booking) => {
      if (!bookingStats[booking.customer_id]) {
        bookingStats[booking.customer_id] = {
          total_bookings: 0,
          total_spent: 0,
        };
      }
      bookingStats[booking.customer_id].total_bookings += 1;
      bookingStats[booking.customer_id].total_spent += Number(booking.total_amount || 0);
      if (booking.completed_at) {
        const completedDate = booking.completed_at;
        if (!bookingStats[booking.customer_id].last_service_date || 
            new Date(completedDate) > new Date(bookingStats[booking.customer_id].last_service_date)) {
          bookingStats[booking.customer_id].last_service_date = completedDate;
        }
      }
    });

    // Combine data
    const conversationCustomers = customers?.map((customer) => {
      const convData = customerConversations[customer.id];
      const bookingData = bookingStats[customer.id];
      
      return {
        customer_id: customer.id,
        customer,
        last_message_date: convData?.last_message_date || null,
        conversation_count: convData?.conversation_count || 0,
        last_service_date: bookingData?.last_service_date || null,
        total_bookings: bookingData?.total_bookings || 0,
        total_spent: bookingData?.total_spent || 0,
        is_saved: savedCustomerIds.has(customer.id),
        has_booked: !!bookingData,
      };
    }) || [];

    // Sort by last message date (most recent first)
    conversationCustomers.sort((a, b) => {
      const dateA = a.last_message_date ? new Date(a.last_message_date).getTime() : 0;
      const dateB = b.last_message_date ? new Date(b.last_message_date).getTime() : 0;
      return dateB - dateA;
    });

    // If search query is provided, filter by name, email, or phone
    let filteredCustomers = conversationCustomers;
    if (searchQuery && searchQuery.trim().length > 0) {
      const searchLower = searchQuery.toLowerCase().trim();
      filteredCustomers = conversationCustomers.filter((item) => {
        const customer = item.customer;
        if (!customer) return false;
        
        const nameMatch = customer.full_name?.toLowerCase().includes(searchLower);
        const emailMatch = customer.email?.toLowerCase().includes(searchLower);
        const phoneMatch = customer.phone?.toLowerCase().includes(searchLower);
        
        return nameMatch || emailMatch || phoneMatch;
      });
    }

    return successResponse(filteredCustomers);
  } catch (error) {
    return handleApiError(error, "Failed to load conversation customers");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import {
  successResponse,
  handleApiError,
  getProviderIdForUser,
  normalizePhoneToE164,
} from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";

/**
 * Helper function to create a walk-in email
 */
function createWalkInEmail(): string {
  return `walkin-${Date.now()}-${Math.random().toString(36).substring(2, 9)}@beautonomi.invalid`;
}

/**
 * Helper function to wait for user profile row to be created by trigger
 */
async function _waitForUserProfileRow(
  supabase: any,
  userId: string,
  maxAttempts = 20
): Promise<void> {
  for (let i = 0; i < maxAttempts; i++) {
    const { data, error } = await supabase
      .from("users")
      .select("id")
      .eq("id", userId)
      .single();

    if (data) {
      return;
    }

    // If we get a specific error (not just "not found"), log it
    if (error && error.code !== 'PGRST116') {
      console.error(`Error checking for user profile (attempt ${i + 1}):`, error);
    }

    await new Promise((resolve) => setTimeout(resolve, 300));
  }

  // Try one more time to get the actual error
  const { error: finalError } = await supabase
    .from("users")
    .select("id")
    .eq("id", userId)
    .single();

  if (finalError) {
    throw new Error(`User profile row was not created: ${finalError.message || JSON.stringify(finalError)}`);
  }

  throw new Error("User profile row was not created in time (trigger may not have fired)");
}

/**
 * POST /api/provider/clients/create
 * Create a new client (user) and add them to provider's client list
 */
export async function POST(request: NextRequest) {
  try {
    // Check permission to edit clients (pass request for Bearer token from mobile)
    const permissionCheck = await requirePermission("edit_clients", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const supabaseAdmin = await getSupabaseAdmin();
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return handleApiError(new Error("Provider not found"), "Provider account required", 403);
    }

    const body = await request.json();

    // Validate required fields
    if (!body.full_name && (!body.first_name || !body.last_name)) {
      return handleApiError(
        new Error("Full name or first name and last name are required"),
        "Validation error",
        400
      );
    }

    // Combine first_name and last_name into full_name if needed
    const full_name = body.full_name || `${body.first_name} ${body.last_name}`.trim();

    // Create email if not provided
    const email = body.email || createWalkInEmail();

    // Validate and format phone number to E.164 if provided
    // Use helper function to normalize phone number (removes + prefix, handles leading 0)
    // Accept countryCode from request body to handle numbers starting with 0
    const phone = normalizePhoneToE164(body.phone, body.countryCode);

    if (body.phone && !phone) {
      console.warn(`Phone number "${body.phone}" is not in valid E.164 format. It will be stored in user profile but not in auth.`);
    }

    // Check if user already exists by email
    let customerId: string | null = null;
    if (body.email) {
      const { data: existingUser } = await supabaseAdmin
        .from("users")
        .select("id")
        .eq("email", email)
        .maybeSingle();

      if (existingUser) {
        customerId = existingUser.id;
      }
    }

    // Also check by phone if email didn't work
    if (!customerId && body.phone) {
      const { data: existingUser } = await supabaseAdmin
        .from("users")
        .select("id")
        .eq("phone", body.phone)
        .maybeSingle();

      if (existingUser) {
        customerId = existingUser.id;
      }
    }

    // If user doesn't exist, create new user
    if (!customerId) {
      let authUserId: string | undefined;

      // OPTION 1: Try to create auth user using Supabase Admin SDK
      try {
        const { data: createdUser, error: createUserError } = await supabaseAdmin.auth.admin.createUser({
          email: email,
          email_confirm: true,
          user_metadata: {
            full_name: full_name,
            phone: body.phone || null,
            role: "customer",
          },
        });

        if (createdUser?.user?.id) {
          authUserId = createdUser.user.id;
          console.log(`Γ£ô Created auth user via SDK: ${authUserId}`);
        } else if (createUserError) {
          console.warn("Auth SDK creation failed:", createUserError.message);
        }
      } catch (authError: any) {
        console.error("Exception during auth SDK creation:", authError.message);
      }

      // OPTION 2: If SDK failed, try direct database query to find existing user
      if (!authUserId) {
        try {
          console.log("Attempting to find existing auth user by email...");
          const { data: existingUsers, error: queryError } = await supabaseAdmin
            .from("users")
            .select("id")
            .eq("email", email)
            .limit(1);

          if (existingUsers && existingUsers.length > 0) {
            authUserId = existingUsers[0].id;
            console.log(`Γ£ô Found existing user in public.users: ${authUserId}`);
          } else if (queryError) {
            console.error("Error querying existing users:", queryError);
          }
        } catch (lookupError) {
          console.error("Exception looking up existing user:", lookupError);
        }
      }

      // OPTION 3: If still no user, use bypass function to insert directly (NUCLEAR OPTION)
      if (!authUserId) {
        try {
          console.log("Attempting direct user creation via bypass function...");

          // Call the bypass function that creates both auth.users and public.users
          const { data: bypassResult, error: bypassError } = await supabaseAdmin
            .rpc('create_user_bypass_trigger', {
              p_email: email,
              p_full_name: full_name,
              p_phone: body.phone || null,
              p_role: 'customer'
            });

          if (bypassResult && bypassResult.success && bypassResult.user_id) {
            authUserId = bypassResult.user_id;
            customerId = authUserId;
            console.log(`Γ£ô Created user via bypass function: ${authUserId}`);

            // User and wallet already created by the function, skip manual creation below
            // Jump directly to client creation
            const { error: clientError } = await supabaseAdmin
              .from("provider_clients")
              .insert({
                provider_id: providerId,
                customer_id: customerId,
                notes: body.notes || "",
              });

            if (clientError) {
              throw clientError;
            }

            // Fetch the created user details
            const { data: userData } = await supabaseAdmin
              .from("users")
              .select("id, email, full_name, phone, created_at")
              .eq("id", customerId)
              .single();

            return NextResponse.json({
              success: true,
              data: userData,
            });
          } else {
            console.error("Bypass function failed:", bypassResult?.error || bypassError);
          }
        } catch (sqlError: any) {
          console.error("Exception during bypass function:", sqlError.message);
        }
      }

      // FINAL FALLBACK: If all methods failed, return error
      if (!authUserId) {
        console.error("All auth creation methods failed. Cannot proceed without auth user.");
        return handleApiError(
          new Error("Failed to create user account. Please apply migration 200 (create_user_bypass_trigger function) or contact support."),
          "Failed to create client",
          500
        );
      }

      customerId = authUserId;

      // If we reach here, customerId should be set (either from successful creation or from error recovery)
      if (!customerId) {
        return handleApiError(
          new Error("User ID not available after creation attempt"),
          "Failed to create client",
          500
        );
      }

      // Manually create user profile (bypass trigger completely)
      console.log(`Creating user profile for ${customerId} (bypassing trigger)`);

      const { data: _manualUser, error: manualError } = await supabaseAdmin
        .from("users")
        .insert({
          id: customerId,
          email: email,
          full_name: full_name,
          phone: body.phone || null,
          role: "customer",
        })
        .select()
        .single();

      if (manualError && manualError.code !== '23505') { // Ignore duplicate key errors
        console.error("Error creating user profile:", manualError);

        // If user already exists, just update it
        const { error: updateError } = await supabaseAdmin
          .from("users")
          .update({
            email: email,
            full_name: full_name,
            phone: body.phone || null,
          })
          .eq("id", customerId);

        if (updateError) {
          console.error("Error updating existing user profile:", updateError);
        }
      }

      // Create wallet for new user
      try {
        await supabaseAdmin
          .from("user_wallets")
          .insert({
            user_id: customerId,
            currency: "ZAR",
          });
      } catch (walletError: any) {
        if (walletError?.code !== '23505') { // Ignore duplicate key errors
          console.warn("Error creating wallet:", walletError);
        }
      }

      console.log("Successfully created user profile manually");

      // Update user profile with all additional fields
      const userUpdates: Record<string, any> = {
        full_name: full_name,
      };

      if (body.preferred_name) userUpdates.preferred_name = body.preferred_name;
      if (body.phone) userUpdates.phone = body.phone;
      if (body.date_of_birth) userUpdates.date_of_birth = body.date_of_birth;
      if (body.emergency_contact_name) userUpdates.emergency_contact_name = body.emergency_contact_name;
      if (body.emergency_contact_phone) userUpdates.emergency_contact_phone = body.emergency_contact_phone;
      if (body.emergency_contact_relationship) userUpdates.emergency_contact_relationship = body.emergency_contact_relationship;
      if (body.preferred_language) userUpdates.preferred_language = body.preferred_language;
      if (body.preferred_currency) userUpdates.preferred_currency = body.preferred_currency;
      if (body.timezone) userUpdates.timezone = body.timezone;
      if (body.email_notifications_enabled !== undefined) userUpdates.email_notifications_enabled = body.email_notifications_enabled;
      if (body.sms_notifications_enabled !== undefined) userUpdates.sms_notifications_enabled = body.sms_notifications_enabled;
      if (body.push_notifications_enabled !== undefined) userUpdates.push_notifications_enabled = body.push_notifications_enabled;

      const { error: updateError } = await supabaseAdmin
        .from("users")
        .update(userUpdates)
        .eq("id", customerId);

      if (updateError) {
        console.error("Error updating user profile:", updateError);
        // If this is a critical error (not just a constraint issue), we should handle it
        if (updateError.code && !updateError.code.startsWith('23')) { // 23xxx are constraint violations
          return handleApiError(
            new Error(`Failed to update user profile: ${updateError.message || JSON.stringify(updateError)}`),
            "Database error creating new user",
            500
          );
        }
        // For constraint violations, just log and continue
      }

      // Create address if provided
      if (body.address && body.address.line1 && body.address.city) {
        const addressData = {
          user_id: customerId,
          address_line1: body.address.line1,
          address_line2: body.address.line2 || null,
          city: body.address.city,
          state: body.address.state || null,
          postal_code: body.address.postal_code || null,
          country: body.address.country || "ZA",
          is_default: true,
        };

        // Unset other defaults first
        await supabaseAdmin
          .from("user_addresses")
          .update({ is_default: false })
          .eq("user_id", customerId)
          .eq("is_default", true);

        const { error: addressError } = await supabaseAdmin
          .from("user_addresses")
          .insert(addressData);

        if (addressError) {
          console.error("Error creating address:", addressError);
          // Don't fail, just log the error
        }
      }
    } else {
      // User exists, update their profile if needed
      const userUpdates: Record<string, any> = {};

      if (body.preferred_name) userUpdates.preferred_name = body.preferred_name;
      if (body.phone) userUpdates.phone = body.phone;
      if (body.date_of_birth) userUpdates.date_of_birth = body.date_of_birth;
      if (body.emergency_contact_name) userUpdates.emergency_contact_name = body.emergency_contact_name;
      if (body.emergency_contact_phone) userUpdates.emergency_contact_phone = body.emergency_contact_phone;
      if (body.emergency_contact_relationship) userUpdates.emergency_contact_relationship = body.emergency_contact_relationship;
      if (body.preferred_language) userUpdates.preferred_language = body.preferred_language;
      if (body.preferred_currency) userUpdates.preferred_currency = body.preferred_currency;
      if (body.timezone) userUpdates.timezone = body.timezone;
      if (body.email_notifications_enabled !== undefined) userUpdates.email_notifications_enabled = body.email_notifications_enabled;
      if (body.sms_notifications_enabled !== undefined) userUpdates.sms_notifications_enabled = body.sms_notifications_enabled;
      if (body.push_notifications_enabled !== undefined) userUpdates.push_notifications_enabled = body.push_notifications_enabled;

      if (Object.keys(userUpdates).length > 0) {
        const { error: updateError } = await supabaseAdmin
          .from("users")
          .update(userUpdates)
          .eq("id", customerId);

        if (updateError) {
          console.error("Error updating existing user:", updateError);
        }
      }

      // Update or create address if provided
      if (body.address && body.address.line1 && body.address.city) {
        const { data: existingAddress } = await supabaseAdmin
          .from("user_addresses")
          .select("id")
          .eq("user_id", customerId)
          .eq("is_default", true)
          .maybeSingle();

        const addressData = {
          user_id: customerId,
          address_line1: body.address.line1,
          address_line2: body.address.line2 || null,
          city: body.address.city,
          state: body.address.state || null,
          postal_code: body.address.postal_code || null,
          country: body.address.country || "ZA",
          is_default: true,
        };

        if (existingAddress) {
          await supabaseAdmin
            .from("user_addresses")
            .update(addressData)
            .eq("id", existingAddress.id);
        } else {
          await supabaseAdmin
            .from("user_addresses")
            .update({ is_default: false })
            .eq("user_id", customerId)
            .eq("is_default", true);

          await supabaseAdmin
            .from("user_addresses")
            .insert(addressData);
        }
      }
    }

    // Now add to provider_clients table
    const { data: existingClient } = await supabaseAdmin
      .from("provider_clients")
      .select("id")
      .eq("provider_id", providerId)
      .eq("customer_id", customerId)
      .maybeSingle();

    let providerClient;
    if (existingClient) {
      // Update existing
      const { data, error } = await supabaseAdmin
        .from("provider_clients")
        .update({
          notes: body.notes || null,
          updated_at: new Date().toISOString(),
        })
        .eq("id", existingClient.id)
        .select()
        .single();

      if (error) throw error;
      providerClient = data;
    } else {
      // Create new
      const { data, error } = await supabaseAdmin
        .from("provider_clients")
        .insert({
          provider_id: providerId,
          customer_id: customerId,
          notes: body.notes || null,
        })
        .select()
        .single();

      if (error) throw error;
      providerClient = data;
    }

    // Fetch full user data
    const { data: userData } = await supabaseAdmin
      .from("users")
      .select("*")
      .eq("id", customerId)
      .single();

    // Parse full_name into first_name and last_name for response
    const fullName = userData?.full_name || "";
    const nameParts = fullName.trim().split(/\s+/);
    const first_name = nameParts[0] || "";
    const last_name = nameParts.slice(1).join(" ") || "";

    return successResponse({
      ...providerClient,
      customer: {
        ...userData,
        first_name,
        last_name,
      },
    });
  } catch (error) {
    console.error("Unexpected error in create client route:", error);
    const errorMessage = error instanceof Error 
      ? error.message 
      : typeof error === 'string' 
        ? error 
        : "Unknown error occurred";

    // Check if it's already a handled error with a specific message
    if (errorMessage.includes("Database error creating new user") || 
        errorMessage.includes("Failed to create user")) {
      return handleApiError(error, "Failed to create client", 500);
    }

    return handleApiError(
      new Error(`Failed to create client: ${errorMessage}`),
      "Failed to create client",
      500
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import {
  successResponse,
  handleApiError,
  getProviderIdForUser,
} from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";

/**
 * GET /api/provider/clients
 * Get all saved clients for the provider
 */
export async function GET(request: NextRequest) {
  try {
    // Check permission to view clients (pass request for Bearer token from mobile)
    const permissionCheck = await requirePermission("view_clients", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);
    const locationId = searchParams.get("location_id");
    const searchQuery = searchParams.get("search");
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return handleApiError(new Error("Provider not found"), "Provider account required", 403);
    }

    const clientsQuery = supabase
      .from("provider_clients")
      .select("id, notes, tags, is_favorite, last_service_date, total_bookings, total_spent, created_at, customer_id")
      .eq("provider_id", providerId);

    // If location_id is provided (and no search), also fetch customer IDs with bookings at that location
    // We still show ALL saved clients but can mark which ones have location-specific bookings
    let _locationCustomerIds: Set<string> | null = null;
    if (locationId && !searchQuery) {
      const { data: locationBookings } = await supabase
        .from("bookings")
        .select("customer_id")
        .eq("provider_id", providerId)
        .or(`location_id.eq.${locationId},location_id.is.null`);

      _locationCustomerIds = new Set((locationBookings || []).map((b: any) => b.customer_id));
    }

    const { data: clients, error } = await clientsQuery
      .order("is_favorite", { ascending: false })
      .order("last_service_date", { ascending: false, nullsFirst: false });

    if (error) {
      throw error;
    }

    if (!clients || clients.length === 0) {
      return successResponse([]);
    }

    // Fetch customer details using admin client to bypass RLS
    const customerIds = clients.map((c) => c.customer_id);
    const supabaseAdmin = await getSupabaseAdmin();
    const { data: customers, error: customersError } = await supabaseAdmin
      .from("users")
      .select("id, full_name, email, phone, avatar_url, rating_average, review_count, date_of_birth, email_notifications_enabled, sms_notifications_enabled")
      .in("id", customerIds);

    if (customersError) {
      console.error("Error fetching customer data from users table (admin client):", customersError);
      throw customersError;
    }

    // Log missing customers for debugging
    if (customers && customers.length < customerIds.length) {
      const foundIds = new Set(customers.map((c: any) => c.id));
      const missingIds = customerIds.filter(id => !foundIds.has(id));
      if (missingIds.length > 0) {
        console.warn(`ΓÜá∩╕Å ${missingIds.length} customer IDs in provider_clients but not found in users table:`, missingIds);
      }
    }

    // Combine data - include all clients even if customer data is missing
    const _foundCustomerIds = new Set(customers?.map((c: any) => c.id) || []);
    let clientsWithCustomers = clients.map((client) => {
      const customer = customers?.find((c) => c.id === client.customer_id);

      // If customer not found, create minimal customer object
      if (!customer) {
        return {
          ...client,
          customer: {
            id: client.customer_id,
            full_name: null,
            email: null,
            phone: null,
            avatar_url: null,
            rating_average: null,
            review_count: 0,
          },
        };
      }

      return {
        ...client,
        customer,
      };
    });

    // If search query is provided, filter by name, email, or phone
    if (searchQuery && searchQuery.trim().length > 0) {
      const searchLower = searchQuery.toLowerCase().trim();
      clientsWithCustomers = clientsWithCustomers.filter((client) => {
        const customer = client.customer;
        if (!customer) return false;

        const nameMatch = customer.full_name?.toLowerCase().includes(searchLower);
        const emailMatch = customer.email?.toLowerCase().includes(searchLower);
        const phoneMatch = customer.phone?.toLowerCase().includes(searchLower);

        return nameMatch || emailMatch || phoneMatch;
      });
    }

    return successResponse(clientsWithCustomers);
  } catch (error) {
    return handleApiError(error, "Failed to load clients");
  }
}

/**
 * POST /api/provider/clients
 * Save a new client
 */
export async function POST(request: NextRequest) {
  try {
    // Check permission to edit clients (pass request for Bearer token from mobile)
    const permissionCheck = await requirePermission("edit_clients", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return handleApiError(new Error("Provider not found"), "Provider account required", 403);
    }

    const body = await request.json();
    const { customer_id, notes, tags, is_favorite } = body;

    if (!customer_id) {
      return handleApiError(new Error("customer_id is required"), "Validation error", 400);
    }

    // Check if client already exists
    const { data: existing } = await supabase
      .from("provider_clients")
      .select("id")
      .eq("provider_id", providerId)
      .eq("customer_id", customer_id)
      .single();

    if (existing) {
      // Update existing
      const { data, error } = await supabase
        .from("provider_clients")
        .update({
          notes: notes || null,
          tags: tags && tags.length > 0 ? tags : null,
          is_favorite: is_favorite || false,
          updated_at: new Date().toISOString(),
        })
        .eq("id", existing.id)
        .select()
        .single();

      if (error) throw error;
      return successResponse(data);
    }

    // Create new
    const { data, error } = await supabase
      .from("provider_clients")
      .insert({
        provider_id: providerId,
        customer_id,
        notes: notes || null,
        tags: tags && tags.length > 0 ? tags : null,
        is_favorite: is_favorite || false,
      })
      .select()
      .single();

    if (error) throw error;

    return successResponse(data);
  } catch (error) {
    return handleApiError(error, "Failed to save client");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import {
  successResponse,
  handleApiError,
  getProviderIdForUser,
} from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";

/**
 * GET /api/provider/clients/serviced
 * Get all customers that have been serviced (from bookings)
 */
export async function GET(request: NextRequest) {
  try {
    // Check permission to view clients (pass request for Bearer token from mobile)
    const permissionCheck = await requirePermission("view_clients", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);
    const locationId = searchParams.get("location_id");
    const searchQuery = searchParams.get("search");
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return handleApiError(new Error("Provider not found"), "Provider account required", 403);
    }

    // Get all unique customers from active bookings (not cancelled/no_show)
    let bookingsQuery = supabase
      .from("bookings")
      .select("customer_id, scheduled_at, completed_at, total_amount, location_id, status")
      .eq("provider_id", providerId)
      .not("status", "in", '("cancelled","no_show")');

    // Filter by location if provided
    if (locationId) {
      bookingsQuery = bookingsQuery.eq("location_id", locationId);
    }

    const { data: bookings, error: bookingsError } = await bookingsQuery;

    if (bookingsError) throw bookingsError;

    // Group by customer and calculate stats
    const customerStats: Record<
      string,
      {
        customer_id: string;
        last_service_date: string;
        total_bookings: number;
        total_spent: number;
      }
    > = {};

    bookings?.forEach((booking) => {
      const serviceDate = booking.completed_at || booking.scheduled_at;
      if (!serviceDate) return;

      if (!customerStats[booking.customer_id]) {
        customerStats[booking.customer_id] = {
          customer_id: booking.customer_id,
          last_service_date: serviceDate,
          total_bookings: 0,
          total_spent: 0,
        };
      }

      customerStats[booking.customer_id].total_bookings += 1;
      customerStats[booking.customer_id].total_spent += Number(booking.total_amount || 0);

      if (
        new Date(serviceDate) >
        new Date(customerStats[booking.customer_id].last_service_date)
      ) {
        customerStats[booking.customer_id].last_service_date = serviceDate;
      }
    });

    // Get customer details and check if they're saved
    const customerIds = Object.keys(customerStats);
    if (customerIds.length === 0) {
      return successResponse([]);
    }

    // Use admin client to bypass RLS when fetching customer data
    const supabaseAdmin = await getSupabaseAdmin();
    const { data: customers, error: customersError } = await supabaseAdmin
      .from("users")
      .select("id, full_name, email, phone, avatar_url, rating_average, review_count, date_of_birth, email_notifications_enabled, sms_notifications_enabled")
      .in("id", customerIds);

    if (customersError) {
      console.error("Error fetching customer data from users table (admin client):", customersError);
      throw customersError;
    }

    // Log missing customers for debugging
    if (customers && customers.length < customerIds.length) {
      const foundIds = new Set(customers.map((c: any) => c.id));
      const missingIds = customerIds.filter(id => !foundIds.has(id));
      if (missingIds.length > 0) {
        console.warn(`ΓÜá∩╕Å ${missingIds.length} customer IDs in bookings but not found in users table:`, missingIds);
      }
    }

    // Get saved client IDs
    const { data: savedClients } = await supabase
      .from("provider_clients")
      .select("customer_id")
      .eq("provider_id", providerId)
      .in("customer_id", customerIds);

    const savedCustomerIds = new Set(savedClients?.map((c) => c.customer_id) || []);

    // Combine data - only include customers that were found in users table
    // For customers not found, we'll still include them with basic info from booking stats
    const foundCustomerIds = new Set(customers?.map((c: any) => c.id) || []);
    const missingCustomerIds = customerIds.filter(id => !foundCustomerIds.has(id));

    // Include found customers
    const servicedCustomers = customers?.map((customer) => ({
      customer_id: customer.id,
      customer,
      last_service_date: customerStats[customer.id].last_service_date,
      total_bookings: customerStats[customer.id].total_bookings,
      total_spent: customerStats[customer.id].total_spent,
      is_saved: savedCustomerIds.has(customer.id),
    })) || [];

    // Include missing customers with minimal info (they exist in bookings but not in users table)
    const missingCustomers = missingCustomerIds.map((customerId) => ({
      customer_id: customerId,
      customer: {
        id: customerId,
        full_name: null, // Will show as "Unknown"
        email: null,
        phone: null,
        avatar_url: null,
        rating_average: null,
        review_count: 0,
      },
      last_service_date: customerStats[customerId].last_service_date,
      total_bookings: customerStats[customerId].total_bookings,
      total_spent: customerStats[customerId].total_spent,
      is_saved: savedCustomerIds.has(customerId),
    }));

    const allServicedCustomers = [...servicedCustomers, ...missingCustomers];

    // Sort by last service date (most recent first)
    allServicedCustomers.sort(
      (a, b) =>
        new Date(b.last_service_date).getTime() - new Date(a.last_service_date).getTime()
    );

    // If search query is provided, filter by name, email, or phone
    let filteredCustomers = allServicedCustomers;
    if (searchQuery && searchQuery.trim().length > 0) {
      const searchLower = searchQuery.toLowerCase().trim();
      filteredCustomers = allServicedCustomers.filter((item) => {
        const customer = item.customer;
        if (!customer) return false;

        const nameMatch = customer.full_name?.toLowerCase().includes(searchLower);
        const emailMatch = customer.email?.toLowerCase().includes(searchLower);
        const phoneMatch = customer.phone?.toLowerCase().includes(searchLower);

        return nameMatch || emailMatch || phoneMatch;
      });
    }

    return successResponse(filteredCustomers);
  } catch (error) {
    return handleApiError(error, "Failed to load serviced customers");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { getProviderIdForUser, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { checkMessageLimit, formatLimitError } from "@/lib/subscriptions/limit-checker";
import { z } from "zod";

/**
 * GET /api/provider/conversations/[id]/messages
 * 
 * Get messages for a conversation
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Check permission to view messages
    const permissionCheck = await requirePermission("view_messages", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const { id } = await params;
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const { data: conversation, error: convError } = await supabase
      .from("conversations")
      .select("id, provider_id")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (convError || !conversation) {
      return notFoundResponse("Conversation not found");
    }

    // Get messages
    const { data: messages, error } = await supabase
      .from("messages")
      .select(`
        id,
        conversation_id,
        sender_id,
        sender_role,
        content,
        attachments,
        is_read,
        read_at,
        created_at
      `)
      .eq("conversation_id", id)
      .order("created_at", { ascending: true });

    if (error) {
      throw error;
    }

    // Mark messages as read
    await supabase
      .from("messages")
      .update({ is_read: true, read_at: new Date().toISOString() })
      .eq("conversation_id", id)
      .eq("is_read", false)
      .neq("sender_id", user.id);

    // Update conversation unread count (provider side)
    await supabase
      .from("conversations")
      .update({ unread_count_provider: 0 })
      .eq("id", id);

    // Fetch sender data using admin client to bypass RLS
    const senderIds = [...new Set((messages || []).map((m: any) => m.sender_id).filter(Boolean))];
    let senderMap: Record<string, any> = {};
    
    if (senderIds.length > 0) {
      const supabaseAdmin = await getSupabaseAdmin();
      const { data: senders } = await supabaseAdmin
        .from("users")
        .select("id, full_name, email, avatar_url")
        .in("id", senderIds);
      
      if (senders && senders.length > 0) {
        senderMap = senders.reduce((acc: Record<string, any>, sender: any) => {
          acc[sender.id] = sender;
          return acc;
        }, {});
      }
    }

    const transformed = (messages || []).map((msg: any) => {
      const sender = senderMap[msg.sender_id];
      
      // Determine sender name - prioritize full_name, then email, then fallback
      let senderName = "Unknown";
      if (sender) {
        if (sender.full_name && sender.full_name.trim()) {
          senderName = sender.full_name.trim();
        } else if (sender.email) {
          senderName = sender.email;
        }
      }
      
      return {
        id: msg.id,
        conversation_id: msg.conversation_id,
        sender_id: msg.sender_id,
        sender_name: senderName,
        sender_avatar: sender?.avatar_url || null,
        content: msg.content,
        attachments: msg.attachments || [],
        is_read: msg.is_read,
        read_at: msg.read_at, // Include read_at for read receipts
        sender_type: msg.sender_role === "customer" ? "customer" : "provider",
        created_at: msg.created_at,
      };
    });

    return successResponse(transformed);
  } catch (error) {
    return handleApiError(error, "Failed to fetch messages");
  }
}

/**
 * POST /api/provider/conversations/[id]/messages
 * 
 * Send a message in a conversation
 */
const sendMessageSchema = z.object({
  content: z.string().optional(),
  attachments: z.array(z.object({
    url: z.string(),
    type: z.string(),
    name: z.string().optional(),
    size: z.number().optional(),
  })).optional(),
}).refine((data) => data.content || (data.attachments && data.attachments.length > 0), {
  message: "Either content or attachments must be provided",
});

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Check permission to send messages
    const permissionCheck = await requirePermission("send_messages", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const { id } = await params;
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const { data: conversation, error: convError } = await supabase
      .from("conversations")
      .select("id, provider_id")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (convError || !conversation) {
      return notFoundResponse("Conversation not found");
    }

    // Check subscription message limit (but allow messaging even without subscription)
    // Messaging is a core feature and should work even without a subscription
    // Only enforce limits if there's an active subscription with explicit limits
    try {
      const messageLimitCheck = await checkMessageLimit(providerId);
      
      // Only block if:
      // 1. There's an actual limit (limitValue is not null)
      // 2. The limit has been exceeded (currentCount >= limitValue)
      // 3. The plan name is not empty (meaning there's an active subscription)
      if (!messageLimitCheck.canProceed && 
          messageLimitCheck.limitValue !== null && 
          messageLimitCheck.planName && 
          messageLimitCheck.planName.trim() !== "" &&
          messageLimitCheck.currentCount >= messageLimitCheck.limitValue) {
        // Only block if there's an active subscription with a limit that's been exceeded
        return errorResponse(
          formatLimitError(messageLimitCheck),
          "SUBSCRIPTION_LIMIT_EXCEEDED",
          403
        );
      }
      // Allow messaging if:
      // - No subscription (planName is empty)
      // - Limit is null (unlimited)
      // - Limit hasn't been exceeded yet
    } catch (limitError) {
      // If limit check fails, allow messaging anyway (don't block core functionality)
      console.warn("Message limit check failed, allowing message:", limitError);
    }

    const body = await request.json();
    const validated = sendMessageSchema.parse(body);

    // Create message
    const { data: message, error: messageError } = await supabase
      .from("messages")
      .insert({
        conversation_id: id,
        sender_id: user.id,
        sender_role: user.role,
        content: validated.content || "",
        attachments: validated.attachments || [],
        is_read: false,
        created_at: new Date().toISOString(),
      })
      .select()
      .single();

    if (messageError) {
      throw messageError;
    }

    // Send notification to customer (best-effort)
    try {
      const { data: convData } = await supabase
        .from("conversations")
        .select("customer_id")
        .eq("id", id)
        .single();

      if (convData && convData.customer_id) {
        const customerId = convData.customer_id;
        const messagePreview = validated.content 
          ? (validated.content.length > 50 ? validated.content.slice(0, 50) + "..." : validated.content)
          : (validated.attachments && validated.attachments.length > 0 ? "Sent an attachment" : "New message");

        // Send OneSignal push notification (try template first, fallback to hardcoded)
        const { sendToUser: _sendToUser, sendTemplateNotification, getNotificationTemplate } = await import("@/lib/notifications/onesignal");
        
        // Try to use notification template
        const template = await getNotificationTemplate("customer_new_message");
        
        if (template && template.enabled) {
          // Get provider name for template
          const { data: providerData } = await supabase
            .from("providers")
            .select("business_name")
            .eq("id", providerId)
            .single();
          
          // Use template with variables
          await sendTemplateNotification(
            "customer_new_message",
            [customerId],
            {
              provider_name: providerData?.business_name || "Your provider",
              message_preview: messagePreview,
              conversation_id: id,
            },
            template.channels || ["push"]
          );
        } else {
          // Fallback: Try to use template, but if template doesn't exist, log warning
          console.warn("Notification template 'new_message' not found, skipping notification");
        }

        // Create in-app notification record
        try {
          const { data: notificationExists } = await supabase
            .from("notifications")
            .select("id")
            .limit(1)
            .maybeSingle();
          
          if (notificationExists !== null) {
            await supabase
              .from("notifications")
              .insert({
                user_id: customerId,
                type: "new_message",
                title: "New Message from Provider",
                message: messagePreview,
                data: { conversation_id: id, message_id: message.id },
                is_read: false,
                created_at: new Date().toISOString(),
              });
          }
        } catch (notifError) {
          console.debug("Failed to create notification record:", notifError);
        }
      }
    } catch (notifError) {
      // Don't fail message send if notification fails
      console.error("Failed to send message notification:", notifError);
    }

    // Conversation unread counts + last message preview handled by DB trigger.

    return successResponse({
      id: message.id,
      conversation_id: id,
      sender_id: user.id,
      content: validated.content,
      is_read: false,
      sender_type: "provider",
      created_at: message.created_at,
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(error, "Invalid request data", 400);
    }
    return handleApiError(error, "Failed to send message");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { getProviderIdForUser, successResponse, handleApiError, notFoundResponse } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";

/**
 * GET /api/provider/conversations/[id]
 *
 * Get a single conversation with messages (used by mobile chat screen).
 * Marks all messages from the customer as read and sets unread_count_provider to 0 (read receipt).
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const permissionCheck = await requirePermission("view_messages", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const { id: conversationId } = await params;
    if (!conversationId) {
      return notFoundResponse("Conversation ID is required");
    }
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const { data: conversation, error: convError } = await supabase
      .from("conversations")
      .select("id, customer_id, provider_id, booking_id, last_message_at, last_message_preview, unread_count_provider, created_at")
      .eq("id", conversationId)
      .eq("provider_id", providerId)
      .single();

    if (convError || !conversation) {
      return notFoundResponse("Conversation not found");
    }

    // Fetch customer info
    const supabaseAdmin = await getSupabaseAdmin();
    const { data: customer } = await supabaseAdmin
      .from("users")
      .select("id, full_name, email, phone, avatar_url")
      .eq("id", conversation.customer_id)
      .single();

    let customerName = "Customer";
    if (customer?.full_name?.trim()) {
      customerName = customer.full_name.trim();
    } else if (customer?.email) {
      customerName = customer.email;
    }

    // Fetch messages
    const { data: messages, error: msgError } = await supabase
      .from("messages")
      .select("id, conversation_id, sender_id, sender_role, content, attachments, is_read, read_at, created_at")
      .eq("conversation_id", conversationId)
      .order("created_at", { ascending: true });

    if (msgError) throw msgError;

    // Mark unread messages as read
    await supabase
      .from("messages")
      .update({ is_read: true, read_at: new Date().toISOString() })
      .eq("conversation_id", conversationId)
      .eq("is_read", false)
      .neq("sender_id", user.id);

    await supabase
      .from("conversations")
      .update({ unread_count_provider: 0 })
      .eq("id", conversationId);

    const transformedMessages = (messages || []).map((msg: any) => ({
      id: msg.id,
      content: msg.content,
      sender_type: msg.sender_role === "customer" ? "customer" : "provider",
      created_at: msg.created_at,
      read_at: msg.read_at,
      attachments: msg.attachments ?? [],
    }));

    return successResponse({
      id: conversation.id,
      customer_id: conversation.customer_id,
      customer_name: customerName,
      customer_avatar_url: customer?.avatar_url || null,
      customer_phone: (customer as any)?.phone ?? null,
      customer_email: customer?.email ?? null,
      messages: transformedMessages,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch conversation");
  }
}

/**
 * POST /api/provider/conversations/create
 * When the client hits .../conversations/create, some routers match [id]=create.
 * Delegate to create logic so POST always works.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  if (id === "create") {
    const { createConversation } = await import("../_helpers/create-conversation");
    return createConversation(request);
  }
  return notFoundResponse("Conversation not found");
}

/**
 * DELETE /api/provider/conversations/[id]
 *
 * Delete a conversation (provider side - soft delete)
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const permissionCheck = await requirePermission("view_messages", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const { id: conversationId } = await params;
    if (!conversationId) {
      return notFoundResponse("Conversation ID is required");
    }
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Verify the conversation belongs to this provider
    const { data: conversation, error: fetchError } = await supabase
      .from("conversations")
      .select("id, customer_id, provider_id")
      .eq("id", conversationId)
      .eq("provider_id", providerId)
      .single();

    if (fetchError || !conversation) {
      return notFoundResponse("Conversation not found or you don't have permission to delete it");
    }

    // Soft delete: Delete the conversation (hard delete for now, can be changed to soft delete later)
    // For soft delete, we could add a `provider_deleted_at` field and filter it out in queries
    const { error: deleteError } = await supabase
      .from("conversations")
      .delete()
      .eq("id", conversationId);

    if (deleteError) {
      throw deleteError;
    }

    return successResponse({ deleted: true });
  } catch (error) {
    return handleApiError(error, "Failed to delete conversation");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getProviderIdForUser, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { z } from "zod";

const createSchema = z.object({
  customer_id: z.string().uuid("Invalid customer ID"),
  booking_id: z.string().uuid().optional().nullable(),
});

/**
 * Shared logic for POST create conversation.
 * Used by both /api/provider/conversations/create and /api/provider/conversations/[id] when id=create.
 */
export async function createConversation(request: NextRequest): Promise<Response> {
  try {
    const permissionCheck = await requirePermission("send_messages", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return handleApiError(new Error("Provider not found"), "Provider account required", 403);
    }

    const body = createSchema.parse(await request.json());
    const { customer_id, booking_id } = body;

    const { data: customer, error: customerError } = await supabase
      .from("users")
      .select("id, email")
      .eq("id", customer_id)
      .single();

    if (customerError || !customer) {
      return handleApiError(new Error("Customer not found"), "Customer not found", 404);
    }

    if (customer.email?.includes("beautonomi.invalid") || customer.email?.includes("beautonomi.local")) {
      return handleApiError(
        new Error("Customer is not registered"),
        "This customer is not registered on Beautonomi. Only registered customers can receive chat messages.",
        400
      );
    }

    let query = supabase
      .from("conversations")
      .select("id")
      .eq("customer_id", customer_id)
      .eq("provider_id", providerId);

    if (booking_id) {
      query = query.eq("booking_id", booking_id);
    } else {
      query = query.is("booking_id", null);
    }

    const { data: existing } = await query.maybeSingle();

    if (existing) {
      return successResponse({ id: existing.id, created: false });
    }

    const { data: newConv, error: createError } = await supabase
      .from("conversations")
      .insert({
        booking_id: booking_id || null,
        customer_id: customer_id,
        provider_id: providerId,
        last_message_at: new Date().toISOString(),
        last_message_preview: "",
        last_message_sender_id: user.id,
        unread_count_customer: 0,
        unread_count_provider: 0,
      })
      .select("id")
      .single();

    if (createError) throw createError;

    return successResponse({ id: newConv.id, created: true });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        error,
        error.issues.map((e: any) => e.message).join(", "),
        "VALIDATION_ERROR",
        400
      );
    }
    return handleApiError(error, "Failed to create conversation");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { getProviderIdForUser, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { createConversation } from "./_helpers/create-conversation";

/**
 * POST /api/provider/conversations
 *
 * Create a new conversation with a customer (provider-initiated).
 * Same behavior as POST /api/provider/conversations/create.
 */
export async function POST(request: NextRequest) {
  return createConversation(request);
}

/**
 * GET /api/provider/conversations
 * 
 * Get provider's conversations with customers
 */
export async function GET(request: NextRequest) {
  try {
    // Check permission to view messages
    const permissionCheck = await requirePermission("view_messages", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    // If user doesn't have a provider_id, return empty array (they might be setting up)
    if (!providerId) {
      console.log(`No provider ID found for user ${user.id}, returning empty conversations list`);
      return successResponse([]);
    }

    // Get provider's user_id to filter out self-conversations
    const { data: providerData } = await supabase
      .from("providers")
      .select("user_id")
      .eq("id", providerId)
      .single();

    const providerUserId = providerData?.user_id;

    // First, get conversations - exclude conversations where provider is messaging themselves
    let query = supabase
      .from("conversations")
      .select(
        `
        id,
        booking_id,
        customer_id,
        provider_id,
        last_message_at,
        last_message_preview,
        unread_count_provider,
        is_archived_provider,
        created_at,
        booking:bookings!conversations_booking_id_fkey(id, booking_number)
      `
      )
      .eq("provider_id", providerId);

    // Filter out conversations where customer_id equals provider's user_id (provider messaging themselves)
    if (providerUserId) {
      query = query.neq("customer_id", providerUserId);
    }

    const { data: conversations, error } = await query
      .order("last_message_at", { ascending: false, nullsFirst: false });

    if (error) {
      throw error;
    }

    // Filter out conversations with no messages (no last_message_preview and check if messages exist)
    // Only show conversations that have at least one message
    const conversationIds = (conversations || []).map((c: any) => c.id);
    let conversationsWithMessages = conversations || [];

    if (conversationIds.length > 0) {
      // Check which conversations have messages
      const { data: messagesData } = await supabase
        .from("messages")
        .select("conversation_id")
        .in("conversation_id", conversationIds)
        .limit(1000); // Reasonable limit

      if (messagesData && messagesData.length > 0) {
        const conversationIdsWithMessages = new Set(
          messagesData.map((m: any) => m.conversation_id)
        );

        // Filter to only include conversations that have messages OR have a last_message_preview
        conversationsWithMessages = (conversations || []).filter((conv: any) => {
          return conversationIdsWithMessages.has(conv.id) || 
                 (conv.last_message_preview && conv.last_message_preview.trim() !== "");
        });
      } else {
        // No messages found, only include conversations with last_message_preview
        conversationsWithMessages = (conversations || []).filter((conv: any) => {
          return conv.last_message_preview && conv.last_message_preview.trim() !== "";
        });
      }
    }

    if (error) {
      throw error;
    }

    // Fetch customer data separately using admin client to bypass RLS
    const customerIds = [...new Set(conversationsWithMessages.map((c: any) => c.customer_id).filter(Boolean))];
    let customerMap: Record<string, any> = {};

    if (customerIds.length > 0) {
      // Use admin client to bypass RLS policies on users table
      const supabaseAdmin = await getSupabaseAdmin();
      const { data: customers, error: customerError } = await supabaseAdmin
        .from("users")
        .select("id, full_name, email, phone, avatar_url")
        .in("id", customerIds);

      if (customerError) {
        console.error("Error fetching customer data from users table:", customerError);
      }

      if (customers && customers.length > 0) {
        customerMap = customers.reduce((acc: Record<string, any>, customer: any) => {
          acc[customer.id] = customer;
          return acc;
        }, {});

        console.log(`Γ£à Fetched ${customers.length} customers for ${customerIds.length} conversations`);

        // Check if we're missing any customers (data integrity issue)
        const foundIds = new Set(customers.map((c: any) => c.id));
        const missingIds = customerIds.filter(id => !foundIds.has(id));
        if (missingIds.length > 0) {
          console.warn(`ΓÜá∩╕Å Data integrity issue: ${missingIds.length} customer IDs in conversations but not in users table:`, missingIds);
        }
      } else if (customerIds.length > 0) {
        console.warn(`ΓÜá∩╕Å No customers found in users table for ${customerIds.length} customer IDs`);
        console.warn(`Customer IDs:`, customerIds);
      }
    }

    const transformed = conversationsWithMessages.map((conv: any) => {
      // Try to get customer from join first, then from map
      const customer = conv.customer || customerMap[conv.customer_id];

      // Determine customer name - prioritize full_name, then email, then fallback
      let customerName = "Customer";
      if (customer) {
        if (customer.full_name && customer.full_name.trim()) {
          customerName = customer.full_name.trim();
        } else if (customer.email) {
          customerName = customer.email;
        }
      }
      // If customer not found, we'll use "Customer" as fallback
      // This is logged above in the missing customers check

      return {
        id: conv.id,
        customer_id: conv.customer_id,
        customer_name: customerName,
        customer_avatar: customer?.avatar_url || null,
        customer_email: customer?.email || null,
        customer_phone: customer?.phone || null,
        last_message: conv.last_message_preview || "",
        last_message_time: conv.last_message_at || conv.created_at,
        last_message_at: conv.last_message_at || conv.created_at, // Ensure last_message_at is set
        last_message_preview: conv.last_message_preview || "", // Ensure last_message_preview is set
        unread_count: conv.unread_count_provider || 0,
        status: conv.is_archived_provider ? "archived" : "active",
        booking_id: conv.booking_id || null,
        booking_number: conv.booking?.booking_number || null,
        // For provider portal, avatar should be customer avatar
        avatar: customer?.avatar_url || null,
        provider_id: conv.provider_id, // Include provider_id for consistency
      };
    });

    return successResponse(transformed);
  } catch (error) {
    return handleApiError(error, "Failed to fetch conversations");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { getProviderIdForUser, successResponse, notFoundResponse, errorResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { requireRoleInApi } from "@/lib/supabase/api-helpers";

/**
 * POST /api/provider/custom-offers/[id]/retract
 * Withdraw a pending custom offer. Updates the offer status and marks the in-chat message as withdrawn.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const supabaseAdmin = getSupabaseAdmin();
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const { id: offerId } = await params;

    const { data: offer, error: offerError } = await supabase
      .from("custom_offers")
      .select("id, provider_id, status")
      .eq("id", offerId)
      .single();

    if (offerError || !offer) return notFoundResponse("Offer not found");
    if ((offer as any).provider_id !== providerId) return notFoundResponse("Offer not found");

    const status = (offer as { status: string }).status;
    if (status === "withdrawn") {
      return successResponse({ withdrawn: true, alreadyWithdrawn: true });
    }
    const allowedStatuses = ["pending", "payment_pending"];
    if (!allowedStatuses.includes(status)) {
      return errorResponse(
        `This offer can no longer be withdrawn. Current status: ${status}. Only pending or payment_pending offers can be withdrawn.`,
        "OFFER_NOT_WITHDRAWABLE",
        400,
        { currentStatus: status }
      );
    }

    await supabaseAdmin
      .from("custom_offers")
      .update({ status: "withdrawn", updated_at: new Date().toISOString() })
      .eq("id", offerId);

    // Find messages that reference this offer and set withdrawn on the attachment
    const { data: messages } = await supabaseAdmin
      .from("messages")
      .select("id, attachments")
      .not("attachments", "is", null);

    for (const msg of messages || []) {
      const attachments = (msg as any).attachments;
      if (!Array.isArray(attachments)) continue;
      const updated = attachments.map((a: any) =>
        a.type === "custom_offer" && a.offer_id === offerId ? { ...a, withdrawn: true } : a
      );
      if (JSON.stringify(updated) !== JSON.stringify(attachments)) {
        await supabaseAdmin.from("messages").update({ attachments: updated }).eq("id", (msg as any).id);
      }
    }

    return successResponse({ withdrawn: true });
  } catch (error) {
    return handleApiError(error, "Failed to retract offer");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getProviderIdForUser, successResponse, notFoundResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { requireRoleInApi } from "@/lib/supabase/api-helpers";

/**
 * GET /api/provider/custom-offers/[id]
 * Fetch a single offer with its request for editing/resend. Provider must own the offer.
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const { id: offerId } = await params;

    const { data: row, error } = await supabase
      .from("custom_offers")
      .select(`
        id,
        request_id,
        provider_id,
        price,
        currency,
        duration_minutes,
        expiration_at,
        notes,
        staff_id,
        travel_fee,
        status,
        request:custom_requests(
          id,
          customer_id,
          provider_id,
          service_category_id,
          service_name,
          location_type,
          description,
          preferred_start_at,
          address_line1,
          address_line2,
          address_city,
          address_state,
          address_country,
          address_postal_code
        )
      `)
      .eq("id", offerId)
      .single();

    if (error || !row) return notFoundResponse("Offer not found");
    const offer = row as any;
    if (offer.provider_id !== providerId) return notFoundResponse("Offer not found");

    return successResponse(offer);
  } catch (error) {
    return handleApiError(error, "Failed to fetch offer");
  }
}

import { NextRequest } from "next/server";
import { z } from "zod";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError, notFoundResponse } from "@/lib/supabase/api-helpers";

const createCustomOfferSchema = z.object({
  customer_id: z.string().uuid(),
  conversation_id: z.string().uuid().optional().nullable(), // if provided, post message to this thread
  service_category_id: z.string().uuid().nullable().optional(),
  service_name: z.string().min(1).max(256).optional().nullable(),
  location_type: z.enum(["at_home", "at_salon"]).default("at_salon"),
  description: z.string().min(10).max(4000),
  price: z.number().min(0),
  currency: z.string().min(3).max(5).default("ZAR"),
  duration_minutes: z.number().int().min(15).max(8 * 60),
  expiration_at: z.string(), // ISO
  notes: z.string().max(4000).optional().nullable(),
  preferred_start_at: z.string().nullable().optional(),
  image_urls: z.array(z.string().url()).max(6).optional().default([]),
  staff_id: z.string().uuid().optional().nullable(),
  location_id: z.string().uuid().optional().nullable(), // For at_salon: venue for the booking
  // For at_home: address used when creating booking after customer accepts
  address_line1: z.string().max(500).optional().nullable(),
  address_line2: z.string().max(500).optional().nullable(),
  address_city: z.string().max(200).optional().nullable(),
  address_state: z.string().max(200).optional().nullable(),
  address_country: z.string().max(100).optional().nullable(),
  address_postal_code: z.string().max(20).optional().nullable(),
  travel_fee: z.number().min(0).optional().nullable(),
});

/**
 * POST /api/provider/custom-offers/create
 * Create a custom request and offer in one go (provider-initiated).
 * Supports: service_name, service_category_id, location_type (at_salon/at_home), address for at_home,
 * travel_fee for at_home, description, price, duration, expiration, notes, preferred_start_at, staff_id, image_urls.
 * When accepted and paid, a single booking is created with one booking_service (the custom offering).
 * Variants/addons/packages/products: currently one service per offer; addons can be added to the booking
 * after creation by the provider, or supported in a future iteration with a line-items payload.
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const body = createCustomOfferSchema.parse(await request.json());

    // Verify customer exists (admin client bypasses RLS so provider can resolve customer_id)
    const supabaseAdmin = getSupabaseAdmin();
    const { data: customer } = await supabaseAdmin
      .from("users")
      .select("id, full_name, email")
      .eq("id", body.customer_id)
      .single();

    if (!customer) {
      return handleApiError(new Error("Customer not found"), "Customer not found", 404);
    }

    const preferredIso = body.preferred_start_at ? new Date(body.preferred_start_at).toISOString() : null;
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + 7);

    // Verify staff_id belongs to this provider (if provided)
    if (body.staff_id) {
      const { data: staffRow } = await supabase
        .from("provider_staff")
        .select("id, provider_id")
        .eq("id", body.staff_id)
        .eq("provider_id", providerId)
        .single();

      if (!staffRow) {
        return handleApiError(new Error("Staff member not found or does not belong to this provider"), "Invalid staff assignment", 400);
      }
    }

    // Verify location_id belongs to this provider (if provided, for at_salon)
    if (body.location_id) {
      const { data: locRow } = await supabase
        .from("provider_locations")
        .select("id")
        .eq("id", body.location_id)
        .eq("provider_id", providerId)
        .single();
      if (!locRow) {
        return handleApiError(new Error("Location not found or does not belong to this provider"), "Invalid location", 400);
      }
    }

    // Create custom request (provider-initiated)
    const { data: createdRequest, error: createRequestError } = await supabase
      .from("custom_requests")
      .insert({
        customer_id: body.customer_id,
        provider_id: providerId,
        service_category_id: body.service_category_id ?? null,
        service_name: body.service_name ?? null,
        location_type: body.location_type,
        description: body.description,
        budget_min: null,
        budget_max: null,
        preferred_start_at: preferredIso,
        duration_minutes: body.duration_minutes,
        status: "offered",
        expires_at: expiresAt.toISOString(),
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
        address_line1: body.address_line1 ?? null,
        address_line2: body.address_line2 ?? null,
        address_city: body.address_city ?? null,
        address_state: body.address_state ?? null,
        address_country: body.address_country ?? null,
        address_postal_code: body.address_postal_code ?? null,
      })
      .select()
      .single();

    if (createRequestError) throw createRequestError;

    // Add attachments if any
    if (body.image_urls.length > 0) {
      const attachments = body.image_urls.map((url) => ({
        request_id: (createdRequest as any).id,
        url,
        created_at: new Date().toISOString(),
      }));
      const { error: attachmentsError } = await supabase
        .from("custom_request_attachments")
        .insert(attachments);
      if (attachmentsError) {
        console.error("Failed to insert attachments:", attachmentsError);
        // Continue even if attachments fail
      }
    }

    const travelFeeAmount = body.location_type === "at_home" && body.travel_fee != null && body.travel_fee >= 0
      ? Number(body.travel_fee)
      : 0;

    // Create the offer immediately
    const expIso = new Date(body.expiration_at).toISOString();
    const { data: offer, error: createOfferError } = await supabase
      .from("custom_offers")
      .insert({
        request_id: (createdRequest as any).id,
        provider_id: providerId,
        price: body.price,
        currency: body.currency,
        duration_minutes: body.duration_minutes,
        expiration_at: expIso,
        notes: body.notes ?? null,
        staff_id: body.staff_id || null,
        location_id: body.location_id ?? null,
        scheduled_at: preferredIso,
        travel_fee: travelFeeAmount,
        status: "pending",
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .select()
      .single();

    if (createOfferError) throw createOfferError;

    // Send via messages: use conversation_id if provided (same thread), else find or create general conversation.
    // Use admin client so RLS cannot block the insert; include preferred_start_at so the card can show date/time.
    try {
      let convId: string | null = null;

      if (body.conversation_id) {
        const { data: conv } = await supabaseAdmin
          .from("conversations")
          .select("id")
          .eq("id", body.conversation_id)
          .eq("customer_id", body.customer_id)
          .eq("provider_id", providerId)
          .single();
        convId = (conv as any)?.id ?? null;
      }

      if (!convId) {
        const { data: existingConv } = await supabaseAdmin
          .from("conversations")
          .select("id")
          .eq("customer_id", body.customer_id)
          .eq("provider_id", providerId)
          .is("booking_id", null)
          .order("last_message_at", { ascending: false })
          .limit(1)
          .maybeSingle();
        convId = (existingConv as any)?.id ?? null;
      }

      if (!convId) {
        const { data: newConv, error: convError } = await supabaseAdmin
          .from("conversations")
          .insert({
            booking_id: null,
            customer_id: body.customer_id,
            provider_id: providerId,
            last_message_at: new Date().toISOString(),
            last_message_preview: "",
            last_message_sender_id: user.id,
            unread_count_customer: 0,
            unread_count_provider: 0,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          })
          .select("id")
          .single();

        if (!convError && newConv) {
          convId = (newConv as any)?.id;
        }
      }

      if (convId) {
        const preview = body.description.length > 200 ? body.description.slice(0, 200) + "ΓÇª" : body.description;
        const messageContent = `Custom offer: ${body.currency} ${body.price} ΓÇó ${body.duration_minutes} mins\n\n${preview}`;
        const { error: messageError } = await supabaseAdmin
          .from("messages")
          .insert({
            conversation_id: convId,
            sender_id: user.id,
            sender_role: user.role,
            content: messageContent,
            attachments: [
              {
                type: "custom_offer",
                request_id: (createdRequest as any).id,
                offer_id: (offer as any).id,
                price: body.price,
                currency: body.currency,
                duration_minutes: body.duration_minutes,
                expiration_at: expIso,
                preferred_start_at: preferredIso ?? null,
              },
            ],
            is_read: false,
            created_at: new Date().toISOString(),
          });

        if (!messageError) {
          const { data: currentConv } = await supabaseAdmin
            .from("conversations")
            .select("unread_count_customer")
            .eq("id", convId)
            .single();

          await supabaseAdmin
            .from("conversations")
            .update({
              last_message_at: new Date().toISOString(),
              last_message_preview: messageContent,
              last_message_sender_id: user.id,
              unread_count_customer: ((currentConv as any)?.unread_count_customer ?? 0) + 1,
              updated_at: new Date().toISOString(),
            })
            .eq("id", convId);
        }
      }
    } catch (err) {
      console.warn("Custom offer: failed to post message to conversation", err);
    }

    // Notify customer (best-effort)
    try {
      const { sendToUser: _sendToUser, sendTemplateNotification, getNotificationTemplate } = await import("@/lib/notifications/onesignal");

      // Try to use notification template
      const template = await getNotificationTemplate("customer_custom_offer");

      if (template && template.enabled) {
        // Use template with variables
        await sendTemplateNotification(
          "customer_custom_offer",
          [body.customer_id],
          {
            provider_name: (await supabase.from("providers").select("business_name").eq("id", providerId).single()).data?.business_name || "A provider",
            price: body.price.toString(),
            currency: body.currency,
            request_id: (createdRequest as any).id,
            offer_id: (offer as any).id,
          },
          template.channels || ["push"]
        );
      } else {
        // Fallback: Log warning if template doesn't exist
        console.warn("Notification template 'customer_custom_offer' not found, skipping notification");
      }

      // Create in-app notification record
      try {
        const { data: notificationExists } = await supabase
          .from("notifications")
          .select("id")
          .limit(1)
          .maybeSingle();

        if (notificationExists !== null) {
          await supabase
            .from("notifications")
            .insert({
              user_id: body.customer_id,
              type: "custom_offer",
              title: "Custom Offer Received",
              message: "A provider sent you a custom service offer. Review and accept to proceed.",
              data: { request_id: (createdRequest as any).id, offer_id: (offer as any).id },
              is_read: false,
              created_at: new Date().toISOString(),
            });
        }
      } catch (notifError) {
        console.debug("Failed to create notification record:", notifError);
      }
    } catch {
      // ignore
    }

    return successResponse({
      request: createdRequest,
      offer: offer,
    });
  } catch (error) {
    return handleApiError(error, "Failed to create custom offer");
  }
}

import { NextRequest } from "next/server";
import { z } from "zod";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError, notFoundResponse } from "@/lib/supabase/api-helpers";

const createOfferSchema = z.object({
  price: z.number().min(0),
  currency: z.string().min(3).max(5).default("ZAR"),
  duration_minutes: z.number().int().min(15).max(8 * 60),
  expiration_at: z.string(), // ISO
  notes: z.string().max(4000).optional().nullable(),
  staff_id: z.string().uuid().optional().nullable(),
  location_id: z.string().uuid().optional().nullable(),
  scheduled_at: z.string().optional().nullable(), // ISO or datetime-local string; proposed appointment time when paid
});

export async function POST(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const { id } = await params;
    const body = createOfferSchema.parse(await request.json());

    // Ensure request belongs to this provider
    const { data: reqRow } = await supabase
      .from("custom_requests")
      .select("id, customer_id, provider_id, status")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();
    if (!reqRow) return notFoundResponse("Custom request not found");

    // Validate staff_id and location_id belong to this provider
    if (body.staff_id) {
      const { data: staffRow } = await supabase
        .from("provider_staff")
        .select("id")
        .eq("id", body.staff_id)
        .eq("provider_id", providerId)
        .single();
      if (!staffRow) return handleApiError(new Error("Staff not found"), "Invalid staff", 400);
    }
    if (body.location_id) {
      const { data: locRow } = await supabase
        .from("provider_locations")
        .select("id")
        .eq("id", body.location_id)
        .eq("provider_id", providerId)
        .single();
      if (!locRow) return handleApiError(new Error("Location not found"), "Invalid location", 400);
    }

    const expIso = new Date(body.expiration_at).toISOString();

    const { data: offer, error } = await supabase
      .from("custom_offers")
      .insert({
        request_id: id,
        provider_id: providerId,
        price: body.price,
        currency: body.currency,
        duration_minutes: body.duration_minutes,
        expiration_at: expIso,
        notes: body.notes ?? null,
        staff_id: body.staff_id ?? null,
        location_id: body.location_id ?? null,
        scheduled_at: body.scheduled_at ? new Date(body.scheduled_at).toISOString() : null,
        status: "pending",
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .select()
      .single();
    if (error) throw error;

    // Mark request as offered
    await supabase
      .from("custom_requests")
      .update({ status: "offered", updated_at: new Date().toISOString() })
      .eq("id", id);

    // Also send via messages: post an offer message in the customer<->provider conversation (best-effort)
    try {
      const customerId = (reqRow as any).customer_id as string;
      // Use the most recently active conversation so the offer appears in the same thread the customer is likely in
      const { data: existingConv } = await supabase
        .from("conversations")
        .select("id")
        .eq("customer_id", customerId)
        .eq("provider_id", providerId)
        .is("booking_id", null)
        .order("last_message_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      let convId = (existingConv as any)?.id;

      if (!convId) {
        const { data: newConv, error: convError } = await supabase
          .from("conversations")
          .insert({
            booking_id: null,
            customer_id: customerId,
            provider_id: providerId,
            last_message_at: new Date().toISOString(),
            last_message_preview: "",
            last_message_sender_id: user.id,
            unread_count_customer: 0,
            unread_count_provider: 0,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          })
          .select("id")
          .single();

        if (!convError && newConv) {
          convId = (newConv as any)?.id;
        }
      }

      if (convId) {
        const messageContent = `Custom offer: ${body.currency} ${body.price} ΓÇó ${body.duration_minutes} mins`;
        const { error: messageError } = await supabase
          .from("messages")
          .insert({
            conversation_id: convId,
            sender_id: user.id,
            sender_role: user.role,
            content: messageContent,
            attachments: [
              {
                type: "custom_offer",
                request_id: id,
                offer_id: (offer as any).id,
                price: body.price,
                currency: body.currency,
                duration_minutes: body.duration_minutes,
                expiration_at: expIso,
              },
            ],
            is_read: false,
            created_at: new Date().toISOString(),
          });

        if (!messageError) {
          // Update conversation metadata
          const { data: currentConv } = await supabase
            .from("conversations")
            .select("unread_count_customer")
            .eq("id", convId)
            .single();

          await supabase
            .from("conversations")
            .update({
              last_message_at: new Date().toISOString(),
              last_message_preview: messageContent,
              last_message_sender_id: user.id,
              unread_count_customer: ((currentConv as any)?.unread_count_customer || 0) + 1,
              updated_at: new Date().toISOString(),
            })
            .eq("id", convId);
        }
      }
    } catch {
      // ignore
    }

    // Notify customer using template (best-effort)
    try {
      const { sendTemplateNotification, getNotificationTemplate } = await import("@/lib/notifications/onesignal");
      const template = await getNotificationTemplate("customer_custom_offer");

      if (template && template.enabled) {
        await sendTemplateNotification(
          "customer_custom_offer",
          [(reqRow as any).customer_id],
          {
            provider_name: (reqRow as any)?.providers?.business_name || "A provider",
            price: body.price.toString(),
            currency: body.currency,
            request_id: id,
            offer_id: (offer as any).id,
          },
          template.channels || ["push", "email"]
        );
      } else {
        console.warn("Notification template 'customer_custom_offer' not found, skipping notification");
      }
    } catch {
      // ignore notification errors
    }

    return successResponse(offer);
  } catch (error) {
    return handleApiError(error, "Failed to create custom offer");
  }
}

import { NextRequest } from 'next/server';
import { requireRoleInApi, getProviderIdForUser, notFoundResponse, successResponse, handleApiError } from '@/lib/supabase/api-helpers';
import { createClient } from '@supabase/supabase-js';

export async function GET(request: NextRequest) {
  try {
    // Require provider_owner or provider_staff role
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);

    // Get location_id from query params if provided
    const { searchParams } = new URL(request.url);
    const locationId = searchParams.get('location_id');

    // Use service role client for all queries to avoid RLS infinite recursion
    // This is safe because we're already authenticated and checking user_id matches
    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) return notFoundResponse("Provider not found");

    const { data: providerData, error: providerError } = await supabaseAdmin
      .from('providers')
      .select('id, status, business_name, rating_average, review_count')
      .eq('id', providerId)
      .maybeSingle();
    if (providerError || !providerData) {
      return handleApiError(
        new Error(providerError?.message ?? 'Provider not found'),
        'PROVIDER_FETCH_ERROR',
        500
      );
    }

    const now = new Date();
    const startOfToday = new Date(now);
    startOfToday.setHours(0, 0, 0, 0);
    const startOfWeek = new Date(now);
    startOfWeek.setDate(now.getDate() - now.getDay());
    startOfWeek.setHours(0, 0, 0, 0);
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    const startOfLastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const endOfLastMonth = new Date(now.getFullYear(), now.getMonth(), 0);

    // Optimize: Get only necessary fields for faster queries
    // Load status, created_at, scheduled_at, and location_type in parallel with finance data
    // Build bookings query with optional location filter
    // IMPORTANT: Include 'id' and 'location_type' fields for location filtering and metrics
    let bookingsQuery = supabaseAdmin
      .from('bookings')
      .select('id, status, created_at, scheduled_at, location_id, location_type')
      .eq('provider_id', providerId);

    // If location filter is provided, show bookings for that location
    // When no location is selected, show all bookings (including those with NULL location_id)
    // Note: Bookings with NULL location_id (walk-in clients) are only shown when no location filter is applied
    if (locationId) {
      bookingsQuery = bookingsQuery.eq('location_id', locationId);
    }
    // When no locationId is provided, the query will return all bookings including NULL location_id

    // For finance transactions, we need to filter by location through bookings
    // This requires a join or subquery. For now, we'll filter finance transactions
    // by checking if they're related to bookings with the selected location
    const financeQuery = supabaseAdmin
      .from("finance_transactions")
      .select("transaction_type, amount, net, created_at, booking_id")
      .eq("provider_id", providerId);

    // If location filter is provided, we'll need to filter finance transactions
    // by joining with bookings. For performance, we'll do this in memory after fetching
    const [bookingsResult, ledgerResult] = await Promise.all([
      bookingsQuery,
      financeQuery
    ]);

    if (bookingsResult.error) {
      throw bookingsResult.error;
    }

    const allBookings = bookingsResult.data || [];
    const totalBookings = allBookings.length;

    // Debug: Log booking statuses to help diagnose issues
    if (process.env.NODE_ENV === 'development') {
      const statusCounts = allBookings.reduce((acc: Record<string, number>, booking: any) => {
        acc[booking.status] = (acc[booking.status] || 0) + 1;
        return acc;
      }, {});
      console.log('Dashboard booking status counts:', {
        total: totalBookings,
        statusCounts,
        locationId: locationId || 'all',
      });
    }

    // Count by status (single pass through array - faster than multiple filters)
    let confirmedBookings = 0;
    let completedBookings = 0;
    let cancelledBookings = 0;
    let noShowBookings = 0;
    let pendingBookings = 0;

    // Count by location_type for at-home vs at-salon breakdown
    let atHomeBookings = 0;
    let atSalonBookings = 0;
    let atHomeCompleted = 0;
    let atSalonCompleted = 0;
    let atHomeConfirmed = 0;
    let atSalonConfirmed = 0;
    let atHomePending = 0;
    let atSalonPending = 0;
    let atHomeCancelled = 0;
    let atSalonCancelled = 0;
    let atHomeNoShow = 0;
    let atSalonNoShow = 0;

    for (const booking of allBookings) {
      // Count by status
      switch (booking.status) {
        case 'confirmed': 
          confirmedBookings++; 
          if (booking.location_type === 'at_home') atHomeConfirmed++;
          else if (booking.location_type === 'at_salon') atSalonConfirmed++;
          break;
        case 'completed': 
          completedBookings++; 
          if (booking.location_type === 'at_home') atHomeCompleted++;
          else if (booking.location_type === 'at_salon') atSalonCompleted++;
          break;
        case 'cancelled': 
          cancelledBookings++; 
          if (booking.location_type === 'at_home') atHomeCancelled++;
          else if (booking.location_type === 'at_salon') atSalonCancelled++;
          break;
        case 'no_show': 
          noShowBookings++; 
          if (booking.location_type === 'at_home') atHomeNoShow++;
          else if (booking.location_type === 'at_salon') atSalonNoShow++;
          break;
        case 'pending': 
          pendingBookings++; 
          if (booking.location_type === 'at_home') atHomePending++;
          else if (booking.location_type === 'at_salon') atSalonPending++;
          break;
        // Note: 'in_progress' status exists but is not shown in dashboard status breakdown
        // It's counted in active_bookings calculation
      }

      // Count by location_type
      if (booking.location_type === 'at_home') {
        atHomeBookings++;
      } else if (booking.location_type === 'at_salon') {
        atSalonBookings++;
      }
    }

    // Revenue streams from finance ledger (already loaded in parallel above)
    let rows = ledgerResult.data || [];

    // Filter finance transactions by location if location_id is provided
    // We need to join with bookings to get location_id
    if (locationId && rows.length > 0) {
      // Get booking IDs for the selected location
      const locationBookingIds = new Set(
        allBookings.map((b: any) => b.id)
      );

      // Filter finance transactions to only those related to bookings in this location
      rows = rows.filter((r: any) => {
        // If transaction has booking_id, check if booking is in selected location
        if (r.booking_id) {
          return locationBookingIds.has(r.booking_id);
        }
        // For transactions without booking_id (e.g., gift cards, memberships),
        // we might want to include them or exclude them based on business logic
        // For now, exclude them when filtering by location
        return false;
      });
    }

    // Optimize: Pre-filter and pre-parse dates for faster processing
    const parsedRows = rows.map((r: any) => ({
      ...r,
      createdDate: new Date(r.created_at),
      netValue: Number(r.net ?? r.amount ?? 0),
      amountValue: Number(r.amount || 0),
    }));

    // Optimized sum functions - single pass with pre-parsed data
    const sumNet = (types: string[], start?: Date, end?: Date) => {
      let sum = 0;
      for (const r of parsedRows) {
        if (!types.includes(r.transaction_type)) continue;
        if (start && r.createdDate < start) continue;
        if (end && r.createdDate > end) continue;
        sum += r.netValue;
      }
      return sum;
    };

    const sumAmount = (types: string[], start?: Date, end?: Date) => {
      let sum = 0;
      for (const r of parsedRows) {
        if (!types.includes(r.transaction_type)) continue;
        if (start && r.createdDate < start) continue;
        if (end && r.createdDate > end) continue;
        sum += r.amountValue;
      }
      return sum;
    };

    // Total provider revenue is the provider earnings stream (includes bookings, add-ons, gift cards, memberships, and refund impacts).
    const providerEarningsTotal = sumNet(["provider_earnings"]);
    const totalRevenue = providerEarningsTotal;

    // Gross sales (for reporting) ΓÇö does not change provider net directly here.
    const giftCardSalesTotal = sumAmount(["gift_card_sale"]);
    const membershipSalesTotal = sumAmount(["membership_sale"]);

    // Travel fees (separate from provider_earnings, goes 100% to provider)
    const travelFeesToday = sumNet(["travel_fee"], startOfToday);
    const travelFeesThisMonth = sumNet(["travel_fee"], startOfMonth);
    const travelFeesLastMonth = sumNet(["travel_fee"], startOfLastMonth, endOfLastMonth);
    const travelFeesTotal = sumNet(["travel_fee"]);

    // Refund impact on provider earnings (negative provider_earnings rows) - optimized
    let refundsTotal = 0;
    for (const r of parsedRows) {
      if (r.transaction_type === "provider_earnings" && r.netValue < 0) {
        refundsTotal += r.netValue;
      }
    }

    const revenueToday = sumNet(["provider_earnings"], startOfToday);
    const revenueThisWeek = sumNet(["provider_earnings"], startOfWeek);
    const revenueThisMonth = sumNet(["provider_earnings"], startOfMonth);
    const revenueLastMonth = sumNet(["provider_earnings"], startOfLastMonth, endOfLastMonth);

    const revenueGrowth =
      revenueLastMonth !== 0
        ? Math.round(((revenueThisMonth - revenueLastMonth) / Math.abs(revenueLastMonth)) * 100)
        : 0;

    // Calculate time-based metrics in single pass (optimized)
    let upcomingBookingsToday = 0;
    let bookingsScheduledThisWeek = 0;
    let bookingsScheduledThisMonth = 0;

    const todayEnd = new Date(startOfToday.getTime() + 24 * 60 * 60 * 1000);
    const startOfNextWeek = new Date(startOfWeek.getTime() + 7 * 24 * 60 * 60 * 1000);
    const startOfNextMonth = new Date(now.getFullYear(), now.getMonth() + 1, 1);

    for (const booking of allBookings) {
      const scheduledDate = booking.scheduled_at ? new Date(booking.scheduled_at) : null;

      if (!scheduledDate) continue; // Skip unscheduled bookings

      // Upcoming bookings today (scheduled for today, not created today)
      if (booking.status === 'confirmed' && scheduledDate >= startOfToday && scheduledDate < todayEnd) {
        upcomingBookingsToday++;
      }

      // Bookings scheduled this week (not created this week)
      if (scheduledDate >= startOfWeek && scheduledDate < startOfNextWeek) {
        bookingsScheduledThisWeek++;
      }

      // Bookings scheduled this month (not created this month)
      if (scheduledDate >= startOfMonth && scheduledDate < startOfNextMonth) {
        bookingsScheduledThisMonth++;
      }
    }

    // Calculate available balance and pending payments
    // For available balance: filter provider_earnings by location, but include all payouts (provider-level)
    const financeBalanceQuery = supabaseAdmin
      .from('finance_transactions')
      .select('amount, net, transaction_type, booking_id')
      .eq('provider_id', providerId)
      .in('transaction_type', ['provider_earnings', 'payout', 'platform_fee']);

    const { data: financeData } = await financeBalanceQuery;

    let availableBalance = 0;
    const locationBookingIdsSet = locationId ? new Set(allBookings.map((b: any) => b.id)) : null;

    for (const txn of (financeData || [])) {
      if (txn.transaction_type === 'provider_earnings') {
        // Filter provider_earnings by location if location_id is provided
        if (locationId && locationBookingIdsSet) {
          if (txn.booking_id && locationBookingIdsSet.has(txn.booking_id)) {
            availableBalance += Number(txn.net || 0);
          }
          // Skip transactions without booking_id when filtering by location
        } else {
          // No location filter - include all provider_earnings
          availableBalance += Number(txn.net || 0);
        }
      } else if (txn.transaction_type === 'payout') {
        // Payouts are provider-level, not location-specific, so always include
        availableBalance -= Number(txn.amount || 0);
      }
    }

    // Subtract pending/processing payout requests so dashboard matches finance "available for payout"
    const { data: pendingPayoutRows } = await supabaseAdmin
      .from('payouts')
      .select('amount')
      .eq('provider_id', providerId)
      .in('status', ['pending', 'processing']);
    const pendingPayoutSum = (pendingPayoutRows || []).reduce((s: number, p: any) => s + Number(p.amount || 0), 0);
    availableBalance = Math.max(0, availableBalance - pendingPayoutSum);

    // Calculate pending payments (unpaid bookings)
    let unpaidBookingsQuery = supabaseAdmin
      .from('bookings')
      .select('total_amount, payment_status')
      .eq('provider_id', providerId)
      .in('payment_status', ['pending', 'partially_paid'])
      .not('status', 'in', '(cancelled,no_show)');

    if (locationId) {
      unpaidBookingsQuery = unpaidBookingsQuery.eq('location_id', locationId);
    }

    const { data: unpaidBookings } = await unpaidBookingsQuery;

    const pendingPaymentsAmount = unpaidBookings?.reduce((sum, b) => sum + (b.total_amount || 0), 0) || 0;
    const pendingPaymentsCount = unpaidBookings?.length || 0;

    // Calculate performance metrics
    const completionRate = totalBookings > 0 ? (completedBookings / totalBookings) * 100 : 0;
    const noShowRate = totalBookings > 0 ? (noShowBookings / totalBookings) * 100 : 0;

    // Fetch gamification data (points, badge, milestones) - use admin client
    const { data: gamificationData } = await supabaseAdmin
      .from('provider_points')
      .select(`
        total_points,
        lifetime_points,
        current_tier_points,
        badge_earned_at,
        badge_expires_at,
        provider_badges!provider_points_current_badge_id_fkey (
          id,
          name,
          slug,
          description,
          icon_url,
          tier,
          color,
          requirements,
          benefits
        )
      `)
      .eq('provider_id', providerId)
      .maybeSingle();

    const { data: milestones } = await supabaseAdmin
      .from('provider_milestones')
      .select('milestone_type, achieved_at')
      .eq('provider_id', providerId)
      .order('achieved_at', { ascending: false })
      .limit(10);

    const { data: recentTransactions } = await supabaseAdmin
      .from('provider_point_transactions')
      .select('points, source, description, created_at')
      .eq('provider_id', providerId)
      .order('created_at', { ascending: false })
      .limit(10);

    // Calculate progress to next badge
    let progressToNextBadge = null;
    const badge = Array.isArray(gamificationData?.provider_badges) ? gamificationData?.provider_badges?.[0] : gamificationData?.provider_badges;
    if (gamificationData) {
      const currentTier = badge?.tier || 0;
      const currentPoints = gamificationData.total_points || 0;

      // Fetch all active badges to find the next one
      const { data: allBadges } = await supabaseAdmin
        .from('provider_badges')
        .select('id, name, tier, color, requirements')
        .eq('is_active', true)
        .order('tier', { ascending: true });

      if (allBadges && allBadges.length > 0) {
        const nextBadge = allBadges.find(b => b.tier > currentTier);
        if (nextBadge) {
          const requiredPoints = (nextBadge.requirements as any)?.points || 0;
          const pointsNeeded = Math.max(0, requiredPoints - currentPoints);
          const progressPercentage = requiredPoints > 0 
            ? Math.min(100, Math.round((currentPoints / requiredPoints) * 100))
            : 0;

          progressToNextBadge = {
            badge: {
              id: nextBadge.id,
              name: nextBadge.name,
              tier: nextBadge.tier,
              color: nextBadge.color,
              requirements: nextBadge.requirements,
            },
            current_points: currentPoints,
            required_points: requiredPoints,
            points_needed: pointsNeeded,
            progress_percentage: progressPercentage,
          };
        }
      }
    }

    const gamification = gamificationData ? {
      total_points: gamificationData.total_points || 0,
      lifetime_points: gamificationData.lifetime_points || 0,
      current_tier_points: gamificationData.current_tier_points || 0,
      current_badge: badge ? {
        id: badge.id,
        name: badge.name,
        slug: badge.slug,
        description: badge.description,
        icon_url: badge.icon_url,
        tier: badge.tier,
        color: badge.color,
        requirements: badge.requirements,
        benefits: badge.benefits,
      } : null,
      badge_earned_at: gamificationData.badge_earned_at,
      badge_expires_at: gamificationData.badge_expires_at,
      milestones: milestones || [],
      recent_transactions: recentTransactions || [],
      progress_to_next_badge: progressToNextBadge,
    } : null;

    const response = successResponse({
      // Booking counts
      total_bookings: totalBookings,
      active_bookings: totalBookings - cancelledBookings - noShowBookings,
      confirmed_bookings: confirmedBookings,
      completed_bookings: completedBookings,
      cancelled_bookings: cancelledBookings,
      no_show_bookings: noShowBookings,
      pending_bookings: pendingBookings,

      // Location type breakdown
      at_home_bookings: atHomeBookings,
      at_salon_bookings: atSalonBookings,
      at_home_completed: atHomeCompleted,
      at_salon_completed: atSalonCompleted,
      at_home_confirmed: atHomeConfirmed,
      at_salon_confirmed: atSalonConfirmed,
      at_home_pending: atHomePending,
      at_salon_pending: atSalonPending,
      at_home_cancelled: atHomeCancelled,
      at_salon_cancelled: atSalonCancelled,
      at_home_no_show: atHomeNoShow,
      at_salon_no_show: atSalonNoShow,

      // Revenue - Current period (primary)
      revenue_today: revenueToday,
      revenue_this_week: revenueThisWeek,
      revenue_this_month: revenueThisMonth,
      revenue_growth: revenueGrowth,

      // Revenue - Lifetime (secondary)
      lifetime_revenue: totalRevenue,

      // Financial status
      available_balance: Math.max(0, availableBalance),
      pending_payments_amount: pendingPaymentsAmount,
      pending_payments_count: pendingPaymentsCount,

      // Revenue streams
      service_earnings_total: providerEarningsTotal,
      gift_card_sales_total: giftCardSalesTotal,
      membership_sales_total: membershipSalesTotal,
      refunds_total: Math.abs(refundsTotal), // Show as positive number

      // Travel fees breakdown
      travel_fees_total: travelFeesTotal,
      travel_fees_today: travelFeesToday,
      travel_fees_this_month: travelFeesThisMonth,
      travel_fees_last_month: travelFeesLastMonth,

      // Performance metrics
      completion_rate: completionRate,
      no_show_rate: noShowRate,
      average_rating: providerData?.rating_average || 0,
      total_reviews: providerData?.review_count || 0,

      // Schedule (by scheduled_at, not created_at)
      appointments_today: upcomingBookingsToday,
      appointments_this_week: bookingsScheduledThisWeek,
      appointments_this_month: bookingsScheduledThisMonth,

      // Gamification
      gamification: gamification,
    });

    // Add cache headers for faster subsequent requests (5 seconds)
    response.headers.set('Cache-Control', 'private, max-age=5, stale-while-revalidate=10');

    return response;
  } catch (error) {
    // Log the full error object for better debugging
    console.error('Error loading dashboard:', error);
    return handleApiError(error, 'Failed to load dashboard data');
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  handleApiError,
  getProviderIdForUser,
} from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";

/**
 * GET /api/provider/distance-settings
 * Get distance settings for the provider
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return handleApiError(
        new Error("Provider not found"),
        "Provider not found",
        "NOT_FOUND",
        404
      );
    }

    // Get distance settings from providers table
    const { data: provider, error } = await supabase
      .from("providers")
      .select("max_service_distance_km, is_distance_filter_enabled")
      .eq("id", providerId)
      .single();

    if (error) {
      throw error;
    }

    if (!provider) {
      return handleApiError(
        new Error("Provider not found"),
        "Provider not found",
        "NOT_FOUND",
        404
      );
    }

    const result = {
      max_service_distance_km: provider.max_service_distance_km || 10.00,
      is_distance_filter_enabled: provider.is_distance_filter_enabled || false,
    };

    return successResponse(result);
  } catch (error) {
    return handleApiError(error, "Failed to load distance settings");
  }
}

/**
 * PATCH /api/provider/distance-settings
 * Update distance settings for the provider
 */
export async function PATCH(request: NextRequest) {
  try {
    const permissionCheck = await requirePermission("edit_settings", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }

    const supabase = await getSupabaseServer(request);
    const body = await request.json();
    const providerId = await getProviderIdForUser(permissionCheck.user!.id);

    if (!providerId) {
      return handleApiError(
        new Error("Provider not found"),
        "Provider not found",
        "NOT_FOUND",
        404
      );
    }

    const updates: any = {};

    if (body.max_service_distance_km !== undefined) {
      const distance = parseFloat(body.max_service_distance_km);
      if (isNaN(distance) || distance < 1 || distance > 100) {
        return handleApiError(
          new Error("Invalid distance"),
          "Distance must be between 1 and 100 km",
          "VALIDATION_ERROR",
          400
        );
      }
      updates.max_service_distance_km = distance;
    }

    if (body.is_distance_filter_enabled !== undefined) {
      updates.is_distance_filter_enabled = Boolean(body.is_distance_filter_enabled);
    }

    const { data: provider, error } = await supabase
      .from("providers")
      .update(updates)
      .eq("id", providerId)
      .select("max_service_distance_km, is_distance_filter_enabled")
      .single();

    if (error) {
      throw error;
    }

    const result = {
      max_service_distance_km: provider.max_service_distance_km || 10.00,
      is_distance_filter_enabled: provider.is_distance_filter_enabled || false,
    };

    return successResponse(result);
  } catch (error) {
    return handleApiError(error, "Failed to update distance settings");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError, errorResponse, notFoundResponse } from "@/lib/supabase/api-helpers";
import { checkMarketingFeatureAccess } from "@/lib/subscriptions/feature-access";
import { z } from "zod";

const putSchema = z.object({
  provider_name: z.enum(["sendgrid", "mailchimp"]),
  api_key: z.string().min(1, "API key is required"),
  api_secret: z.string().optional(),
  from_email: z.string().email("Invalid email format"),
  from_name: z.string().optional().default("Beautonomi"),
  is_enabled: z.boolean().optional().default(false),
});

/**
 * GET /api/provider/email-integration
 * Get provider's email integration settings
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);

    // For superadmin, allow viewing any provider's integration
    let providerId: string | null = null;
    if (user.role === "superadmin") {
      const { searchParams } = new URL(request.url);
      const providerIdParam = searchParams.get("provider_id");
      if (providerIdParam) {
        providerId = providerIdParam;
      } else {
        return errorResponse("provider_id is required for superadmin", "VALIDATION_ERROR", 400);
      }
    } else {
      providerId = await getProviderIdForUser(user.id, supabase);
      if (!providerId) {
        return notFoundResponse("Provider not found");
      }
    }

    const { data: integration, error } = await supabase
      .from("provider_email_integrations")
      .select("*")
      .eq("provider_id", providerId)
      .maybeSingle();

    if (error) {
      throw error;
    }

    // Mask sensitive data in response
    if (integration) {
      integration.api_key = integration.api_key ? "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" : "";
      if (integration.api_secret) {
        integration.api_secret = "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó";
      }
    }

    // Return empty object if no integration exists yet
    return successResponse(integration || null);
  } catch (error: any) {
    console.error("Error fetching email integration:", error);
    return handleApiError(error, "Failed to fetch email integration");
  }
}

/**
 * PUT /api/provider/email-integration
 * Create or update provider's email integration
 */
export async function PUT(request: NextRequest) {
  try {
    // Only provider owners and superadmins can update integrations
    const { user } = await requireRoleInApi(['provider_owner', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    // For superadmin, allow updating any provider's integration
    let providerId: string | null = null;
    if (user.role === "superadmin") {
      const { searchParams } = new URL(request.url);
      const providerIdParam = searchParams.get("provider_id");
      if (providerIdParam) {
        providerId = providerIdParam;
      } else {
        return errorResponse("provider_id is required for superadmin", "VALIDATION_ERROR", 400);
      }
    } else {
      providerId = await getProviderIdForUser(user.id, supabase);
      if (!providerId) {
        return notFoundResponse("Provider not found");
      }
    }

    // Check subscription allows custom integrations (skip for superadmin)
    if (user.role !== "superadmin") {
      const marketingAccess = await checkMarketingFeatureAccess(providerId);
      if (!marketingAccess.customIntegrations) {
        return errorResponse(
          "Marketing integrations require a subscription upgrade. Please upgrade your plan to use custom email integrations.",
          "SUBSCRIPTION_REQUIRED",
          403
        );
      }
    }

    // Validate input
    const validated = putSchema.parse(body);
    const { provider_name, api_key, api_secret, from_email, from_name, is_enabled } = validated;

    // Validate SendGrid API key format (starts with SG.)
    if (provider_name === "sendgrid" && !api_key.startsWith("SG.")) {
      return errorResponse("Invalid SendGrid API key format. Should start with 'SG.'", "VALIDATION_ERROR", 400);
    }

    // Validate Mailchimp API key format (contains datacenter like -us1)
    if (provider_name === "mailchimp" && !api_key.includes("-")) {
      return errorResponse("Invalid Mailchimp API key format. Should include datacenter (e.g., xxxxx-us1)", "VALIDATION_ERROR", 400);
    }

    // Check if integration exists
    const { data: existing } = await supabase
      .from("provider_email_integrations")
      .select("id, api_key, api_secret, connected_date")
      .eq("provider_id", providerId)
      .maybeSingle();

    // If API key is masked (ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó), keep the existing value
    const integrationData: any = {
      provider_id: providerId,
      provider_name,
      from_email,
      from_name: from_name || "Beautonomi",
      is_enabled: is_enabled !== undefined ? is_enabled : false,
    };

    // Only update API key if it's not masked
    if (api_key && api_key !== "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó") {
      integrationData.api_key = api_key;
    } else if (existing?.api_key) {
      // Keep existing API key if masked value provided
      integrationData.api_key = existing.api_key;
    } else {
      return errorResponse("API key is required", "VALIDATION_ERROR", 400);
    }

    // Only update API secret if provided and not masked
    if (api_secret && api_secret !== "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó") {
      integrationData.api_secret = api_secret;
    } else if (existing?.api_secret && api_secret === "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó") {
      // Keep existing API secret if masked value provided
      integrationData.api_secret = existing.api_secret;
    }

    if (is_enabled && !existing?.connected_date) {
      integrationData.connected_date = new Date().toISOString();
    }

    let result;
    if (existing) {
      // Update existing
      const { data, error } = await supabase
        .from("provider_email_integrations")
        .update(integrationData)
        .eq("id", existing.id)
        .select()
        .single();

      if (error) throw error;
      result = data;
    } else {
      // Create new
      const { data, error } = await supabase
        .from("provider_email_integrations")
        .insert(integrationData)
        .select()
        .single();

      if (error) throw error;
      result = data;
    }

    // Mask sensitive data in response
    if (result) {
      result.api_key = result.api_key ? "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" : "";
      if (result.api_secret) {
        result.api_secret = "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó";
      }
    }

    return successResponse(result);
  } catch (error: any) {
    if (error instanceof z.ZodError) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        error.issues
      );
    }
    console.error("Error saving email integration:", error);
    return handleApiError(error, "Failed to save email integration");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
