import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, handleApiError } from "@/lib/supabase/api-helpers";

function csvEscape(value: any): string {
  const s = String(value ?? "");
  if (/[",\n\r]/.test(s)) return `"${s.replaceAll('"', '""')}"`;
  return s;
}

function formatRangeStart(range: string, now: Date): Date {
  if (range === "week") return new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7);
  if (range === "year") return new Date(now.getFullYear() - 1, now.getMonth(), now.getDate());
  if (range === "all") return new Date(0);
  return new Date(now.getFullYear(), now.getMonth(), 1); // month default
}

/**
 * GET /api/provider/finance/export?range=month|week|year|all
 * Returns a basic CSV export of finance_transactions for the provider.
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return new Response("id,created_at,transaction_type,amount,net,description\n", {
        status: 200,
        headers: {
          "Content-Type": "text/csv; charset=utf-8",
          "Content-Disposition": `attachment; filename="provider-finance.csv"`,
        },
      });
    }

    const { searchParams } = new URL(request.url);
    const range = searchParams.get("range") || "month";
    const now = new Date();
    const startDate = formatRangeStart(range, now);
    const startIso = startDate.toISOString();
    const endIso = now.toISOString();

    const { data, error } = await supabase
      .from("finance_transactions")
      .select("id, created_at, transaction_type, amount, net, description")
      .eq("provider_id", providerId)
      .gte("created_at", startIso)
      .lte("created_at", endIso)
      .order("created_at", { ascending: false })
      .limit(5000);
    if (error) throw error;

    const header = ["id", "created_at", "transaction_type", "amount", "net", "description"];
    const lines = [header.join(",")];
    for (const r of data || []) {
      lines.push(
        [
          csvEscape((r as any).id),
          csvEscape((r as any).created_at),
          csvEscape((r as any).transaction_type),
          csvEscape((r as any).amount),
          csvEscape((r as any).net),
          csvEscape((r as any).description),
        ].join(",")
      );
    }

    const filename = `provider-finance-${range}-${now.toISOString().slice(0, 10)}.csv`;
    return new Response(lines.join("\n") + "\n", {
      status: 200,
      headers: {
        "Content-Type": "text/csv; charset=utf-8",
        "Content-Disposition": `attachment; filename="${filename}"`,
      },
    });
  } catch (error) {
    return handleApiError(error, "Failed to export finance CSV");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { getAvailablePayoutBalance } from "@/lib/provider/available-payout-balance";

/**
 * GET /api/provider/finance
 * 
 * Get provider's financial data (earnings, transactions, etc.)
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);
    const locationId = searchParams.get("location_id");
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      const { data: platformRow } = await (supabase as any)
        .from("platform_settings")
        .select("settings")
        .eq("is_active", true)
        .limit(1)
        .maybeSingle();
      const minimumPayout = (platformRow?.settings as any)?.payouts?.minimum_payout_amount ?? 100;
      return successResponse({
        earnings: {
          total_earnings: 0,
          pending_payouts: 0,
          available_balance: 0,
          minimum_payout_amount: minimumPayout,
          this_month: 0,
          last_month: 0,
          growth_percentage: 0,
        },
        transactions: [],
      });
    }

    // Get date range
    const range = searchParams.get("range") || "month";
    const now = new Date();
    let startDate: Date;
    let lastMonthStart: Date;
    let lastMonthEnd: Date;

    if (range === "week") {
      startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7);
      lastMonthStart = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 14);
      lastMonthEnd = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7);
    } else if (range === "year") {
      startDate = new Date(now.getFullYear() - 1, now.getMonth(), now.getDate());
      lastMonthStart = new Date(now.getFullYear() - 1, now.getMonth() - 1, 1);
      lastMonthEnd = new Date(now.getFullYear() - 1, now.getMonth(), 0);
    } else {
      // month (default)
      startDate = new Date(now.getFullYear(), now.getMonth(), 1);
      lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
      lastMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0);
    }

    // Provider earnings are ledger-driven.
    // Provider streams:
    // - provider_earnings (bookings + additional charges)
    // - membership_sale (if provider offers memberships)
    // - gift_card_sale (if provider offers gift cards)
    // - refunds (negative; impacts provider net depending on policy, shown separately)
    const startIso = range === "all" ? "1970-01-01T00:00:00.000Z" : startDate.toISOString();
    const nowIso = now.toISOString();

    // Build finance transactions query
    const financeQuery = supabase
      .from("finance_transactions")
      .select("id, transaction_type, amount, net, created_at, description, booking_id")
      .eq("provider_id", providerId)
      .gte("created_at", startIso)
      .lte("created_at", nowIso)
      .order("created_at", { ascending: false })
      .limit(200);

    const { data: ledgerRows, error: ledgerError } = await financeQuery;

    if (ledgerError) throw ledgerError;

    let rows = ledgerRows || [];

    // Fetch booking information for transactions that have booking_id
    // This is needed to check booking_source (walk-in vs online) and payment_provider for filtering
    const bookingIds = [...new Set(rows.filter((r: any) => r.booking_id).map((r: any) => r.booking_id))];
    let bookingMap: Record<string, { booking_source: string | null; location_id: string | null; payment_provider: string | null }> = {};

    if (bookingIds.length > 0) {
      // Fetch bookings
      const { data: bookings } = await supabase
        .from("bookings")
        .select("id, booking_source, location_id")
        .in("id", bookingIds);

      // Fetch payment provider from booking_payments (to check if walk-in paid via Paystack)
      const { data: bookingPayments } = await supabase
        .from("booking_payments")
        .select("booking_id, payment_provider")
        .in("booking_id", bookingIds)
        .eq("status", "completed")
        .order("created_at", { ascending: false });

      if (bookings) {
        bookingMap = bookings.reduce((acc: any, b: any) => {
          // Find the most recent payment for this booking
          const payment = bookingPayments?.find((p: any) => p.booking_id === b.id);
          acc[b.id] = {
            booking_source: b.booking_source || null,
            location_id: b.location_id || null,
            payment_provider: payment?.payment_provider || null,
          };
          return acc;
        }, {});
      }
    }

    // Enrich rows with booking information
    rows = rows.map((r: any) => ({
      ...r,
      booking_source: r.booking_id ? (bookingMap[r.booking_id]?.booking_source || null) : null,
      location_id: r.booking_id ? (bookingMap[r.booking_id]?.location_id || null) : null,
      payment_provider: r.booking_id ? (bookingMap[r.booking_id]?.payment_provider || null) : null,
    }));

    // Filter by location if location_id is provided
    if (locationId && rows.length > 0) {
      rows = rows.filter((r: any) => {
        // If transaction has booking_id, check if booking is in selected location
        if (r.booking_id && r.location_id) {
          return r.location_id === locationId;
        }
        // For transactions without booking_id (e.g., gift cards, memberships),
        // exclude them when filtering by location (they're provider-wide)
        return false;
      });
    }
    const sumNet = (types: string[], within?: { start: Date; end: Date }, excludeWalkIn: boolean = false) =>
      rows
        .filter((r: any) => types.includes(r.transaction_type))
        .filter((r: any) => {
          // Exclude walk-in bookings if requested (for available balance calculation)
          // BUT: Include walk-in bookings where payment was via Paystack (platform holds the money)
          // Only exclude walk-ins where payment was direct (cash, yoco, etc.)
          if (excludeWalkIn && r.booking_id && r.booking_source === 'walk_in') {
            // If payment_provider is 'paystack', include it (platform holds the money)
            // Otherwise exclude it (provider already received payment directly)
            if (r.payment_provider === 'paystack') {
              // Include - platform holds the money
              return true;
            }
            // Exclude - provider received payment directly (cash, yoco, etc.)
            return false;
          }
          if (!within) return true;
          const d = new Date(r.created_at);
          return d >= within.start && d <= within.end;
        })
        .reduce((s: number, r: any) => s + Number(r.net ?? r.amount ?? 0), 0);

    const sumAmount = (types: string[], within?: { start: Date; end: Date }) =>
      rows
        .filter((r: any) => types.includes(r.transaction_type))
        .filter((r: any) => {
          if (!within) return true;
          const d = new Date(r.created_at);
          return d >= within.start && d <= within.end;
        })
        .reduce((s: number, r: any) => s + Number(r.amount || 0), 0);

    const providerEarningsTotal = sumNet(["provider_earnings"]);
    const providerEarningsThis = sumNet(["provider_earnings"], { start: startDate, end: now });
    const providerEarningsLast = sumNet(["provider_earnings"], { start: lastMonthStart, end: lastMonthEnd });

    const membershipSalesTotal = sumAmount(["membership_sale"], { start: startDate, end: now });
    const giftCardSalesTotal = sumAmount(["gift_card_sale"], { start: startDate, end: now });
    const travelFeesTotal = sumNet(["travel_fee"]);
    const travelFeesThisPeriod = sumNet(["travel_fee"], { start: startDate, end: now });
    const refundsTotal = rows
      .filter((r: any) => r.transaction_type === "provider_earnings")
      .reduce((s: number, r: any) => s + (Number(r.net || 0) < 0 ? Number(r.net || 0) : 0), 0);

    const thisMonthTotal = providerEarningsThis;
    const lastMonthTotal = providerEarningsLast;

    const growthPercentage =
      lastMonthTotal !== 0 ? ((thisMonthTotal - lastMonthTotal) / Math.abs(lastMonthTotal)) * 100 : (thisMonthTotal > 0 ? 100 : 0);

    // Available balance and pending payouts: use ledger + payouts table (aligned with payouts API validation).
    const { availableBalance, pendingPayoutsSum } = await getAvailablePayoutBalance(supabase, providerId);
    const pendingPayouts = pendingPayoutsSum;

    // Filter out internal transaction types that providers shouldn't see
    // "payment" type represents platform commission (internal accounting)
    // Only show transactions relevant to providers: provider_earnings, refunds, tips, travel_fees, etc.
    const visibleTransactionTypes = [
      "provider_earnings",
      "refund",
      "tip",
      "travel_fee",
      "service_fee",
      "tax",
      "membership_sale",
      "gift_card_sale",
    ];

    const transactions = rows
      .filter((r: any) => visibleTransactionTypes.includes(r.transaction_type))
      .slice(0, 50)
      .map((r: any) => ({
        id: r.id,
        booking_id: r.booking_id || null,
        transaction_type: r.transaction_type,
        type:
          r.transaction_type === "refund"
            ? ("refund" as const)
            : r.transaction_type === "provider_earnings"
            ? ("booking" as const)
            : ("booking" as const),
        date: r.created_at,
        amount: Number(r.amount || 0),
        net: Number(r.net ?? r.amount ?? 0),
        fees: Number(r.fees || 0),
        commission: Number(r.commission || 0),
        currency: "ZAR",
        status: "completed" as const,
        description: r.description || r.transaction_type,
      }));

    const { data: platformRow } = await (supabase as any)
      .from("platform_settings")
      .select("settings")
      .eq("is_active", true)
      .limit(1)
      .maybeSingle();
    const minimumPayoutAmount = (platformRow?.settings as any)?.payouts?.minimum_payout_amount ?? 100;

    return successResponse({
      earnings: {
        total_earnings: providerEarningsTotal,
        pending_payouts: pendingPayouts,
        available_balance: availableBalance,
        minimum_payout_amount: minimumPayoutAmount,
        this_month: thisMonthTotal,
        last_month: lastMonthTotal,
        growth_percentage: Math.round(growthPercentage * 10) / 10,
        bookings_earnings_total: providerEarningsTotal,
        gift_card_sales_this_period: giftCardSalesTotal,
        membership_sales_this_period: membershipSalesTotal,
        travel_fees_total: travelFeesTotal,
        travel_fees_this_period: travelFeesThisPeriod,
        refunds_total: refundsTotal,
      },
      transactions: transactions,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch finance data");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/provider/finance/vat-reports
 * 
 * Get VAT reports for bi-monthly periods (aligned with SARS periods)
 * SARS periods: Jan-Feb, Mar-Apr, May-Jun, Jul-Aug, Sep-Oct, Nov-Dec
 * Deadlines: 25th of month after period (e.g., Jan-Feb period deadline is 25 Mar)
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);
    const providerId = await getProviderIdForUser(user.id, supabase);
    
    if (!providerId) {
      return successResponse({ reports: [] });
    }

    // Check if provider is VAT-registered
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("is_vat_registered, vat_number")
      .eq("id", providerId)
      .single();

    if (providerError) throw providerError;

    if (!provider?.is_vat_registered) {
      return successResponse({ 
        reports: [],
        provider: {
          vat_number: null,
          is_vat_registered: false,
        },
        year: parseInt(searchParams.get("year") || new Date().getFullYear().toString()),
        message: "Provider is not VAT-registered. VAT reports are only available for VAT-registered providers."
      });
    }

    // Get year filter (default: current year)
    const year = parseInt(searchParams.get("year") || new Date().getFullYear().toString());

    // Calculate bi-monthly periods for the year
    const periods = [];
    for (let month = 0; month < 12; month += 2) {
      const periodStart = new Date(year, month, 1);
      const periodEnd = new Date(year, month + 2, 0); // Last day of second month
      const deadlineDate = new Date(year, month + 2, 25); // 25th of month after period
      
      periods.push({
        period_start: periodStart.toISOString().split('T')[0],
        period_end: periodEnd.toISOString().split('T')[0],
        deadline_date: deadlineDate.toISOString().split('T')[0],
        period_label: `${periodStart.toLocaleDateString('en-ZA', { month: 'short', year: 'numeric' })} - ${periodEnd.toLocaleDateString('en-ZA', { month: 'short', year: 'numeric' })}`,
      });
    }

    // Get VAT transactions for each period
    const reports = await Promise.all(
      periods.map(async (period) => {
        const { data: vatTransactions, error: vatError } = await supabase
          .from("finance_transactions")
          .select("id, net, created_at, booking_id, description")
          .eq("provider_id", providerId)
          .eq("transaction_type", "tax")
          .gte("created_at", `${period.period_start}T00:00:00.000Z`)
          .lte("created_at", `${period.period_end}T23:59:59.999Z`);

        if (vatError) {
          console.error(`Error fetching VAT for period ${period.period_label}:`, vatError);
          return {
            ...period,
            vat_collected: 0,
            transaction_count: 0,
            transactions: [],
            error: vatError.message,
          };
        }

        const vatCollected = (vatTransactions || []).reduce(
          (sum, t) => sum + Number(t.net || 0),
          0
        );

        // Get booking details for transactions
        const bookingIds = [...new Set((vatTransactions || []).map(t => t.booking_id).filter(Boolean))];
        let bookings: any[] = [];
        if (bookingIds.length > 0) {
          const { data: bookingData } = await supabase
            .from("bookings")
            .select("id, booking_number, scheduled_at, total_amount, tax_amount")
            .in("id", bookingIds);
          bookings = bookingData || [];
        }

        // Check if reminder was sent and remittance status
        const { data: reminder } = await supabase
          .from("vat_remittance_reminders")
          .select("id, sent_at, days_before_deadline, remitted_to_sars, remitted_at")
          .eq("provider_id", providerId)
          .eq("period_start", period.period_start)
          .eq("period_end", period.period_end)
          .order("sent_at", { ascending: false })
          .limit(1)
          .maybeSingle();

        const now = new Date();
        const deadline = new Date(period.deadline_date);
        const daysUntilDeadline = Math.ceil((deadline.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
        const isOverdue = deadline < now && vatCollected > 0;

        return {
          ...period,
          vat_collected: vatCollected,
          vat_collected_formatted: new Intl.NumberFormat('en-ZA', {
            style: 'currency',
            currency: 'ZAR',
          }).format(vatCollected),
          transaction_count: vatTransactions?.length || 0,
          transactions: (vatTransactions || []).map(t => {
            const booking = bookings.find(b => b.id === t.booking_id);
            return {
              id: t.id,
              amount: Number(t.net || 0),
              booking_number: booking?.booking_number || 'N/A',
              booking_date: booking?.scheduled_at || t.created_at,
              description: t.description,
            };
          }),
          reminder_sent: reminder ? {
            sent_at: reminder.sent_at,
            days_before_deadline: reminder.days_before_deadline,
          } : null,
          reminder_id: reminder?.id || null,
          remitted_to_sars: reminder?.remitted_to_sars || false,
          remitted_at: reminder?.remitted_at || null,
          days_until_deadline: daysUntilDeadline,
          is_overdue: deadline < now && vatCollected > 0 && !(reminder?.remitted_to_sars),
          status: reminder?.remitted_to_sars ? 'remitted' : (isOverdue ? 'overdue' : daysUntilDeadline <= 7 ? 'due_soon' : 'upcoming'),
        };
      })
    );

    // Sort by period start (most recent first)
    reports.sort((a, b) => 
      new Date(b.period_start).getTime() - new Date(a.period_start).getTime()
    );

    return successResponse({
      reports,
      provider: {
        vat_number: provider.vat_number,
        is_vat_registered: provider.is_vat_registered,
      },
      year,
    });
  } catch (error) {
    return handleApiError(error, "Failed to load VAT reports");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  handleApiError,
  getProviderIdForUser,
  notFoundResponse,
} from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";

/**
 * GET /api/provider/forms
 * Return intake/consent/waiver forms with their fields.
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(
      ["provider_owner", "provider_staff"],
      request
    );
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const { searchParams } = new URL(request.url);
    const formType = searchParams.get("form_type");

    let query = supabase
      .from("provider_forms")
      .select(`
        id, title, description, form_type, is_required, is_active, created_at, updated_at,
        fields:provider_form_fields(id, name, field_type, is_required, sort_order)
      `)
      .eq("provider_id", providerId);

    if (formType) {
      query = query.eq("form_type", formType);
    }

    const { data: forms, error } = await query
      .order("created_at", { ascending: false });

    if (error) {
      throw error;
    }

    // Sort fields by sort_order within each form
    const sorted = (forms || []).map((f: any) => ({
      ...f,
      fields: (f.fields || []).sort((a: any, b: any) => a.sort_order - b.sort_order),
    }));

    return successResponse(sorted);
  } catch (error) {
    return handleApiError(error, "Failed to load forms");
  }
}

/**
 * POST /api/provider/forms
 * Create a new form.
 * Body: { title: string, description?: string, form_type?: string, is_required?: boolean }
 */
export async function POST(request: NextRequest) {
  try {
    const permissionCheck = await requirePermission("edit_settings", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const body = await request.json();
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const { title, description, form_type, is_required } = body;

    if (!title || typeof title !== "string") {
      return handleApiError(
        new Error("title is required"),
        "title is required",
        "VALIDATION_ERROR",
        400
      );
    }

    const { data: form, error } = await supabase
      .from("provider_forms")
      .insert({
        provider_id: providerId,
        title,
        description: description || null,
        form_type: form_type || "intake",
        is_required: is_required ?? false,
        is_active: true,
      })
      .select(`
        id, title, description, form_type, is_required, is_active, created_at, updated_at,
        fields:provider_form_fields(id, name, field_type, is_required, sort_order)
      `)
      .single();

    if (error) {
      throw error;
    }

    return successResponse(form, 201);
  } catch (error) {
    return handleApiError(error, "Failed to create form");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { requireRoleInApi, successResponse, handleApiError, getProviderIdForUser } from "@/lib/supabase/api-helpers";
import { recalculateProviderGamification } from "@/lib/services/provider-gamification";

/**
 * GET /api/provider/gamification
 * 
 * Get provider gamification data (points, badge, milestones, transactions)
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);

    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return handleApiError(
        new Error('Provider not found'),
        'NOT_FOUND',
        404
      );
    }

    // Fetch gamification data
    const { data: pointsData, error: pointsError } = await supabase
      .from('provider_points')
      .select(`
        id,
        total_points,
        lifetime_points,
        current_tier_points,
        badge_earned_at,
        badge_expires_at,
        last_calculated_at,
        provider_badges!provider_points_current_badge_id_fkey (
          id,
          name,
          slug,
          description,
          icon_url,
          tier,
          color,
          requirements,
          benefits
        )
      `)
      .eq('provider_id', providerId)
      .maybeSingle();

    if (pointsError) {
      throw pointsError;
    }

    // Fetch milestones
    const { data: milestones, error: milestonesError } = await supabase
      .from('provider_milestones')
      .select('id, milestone_type, achieved_at, metadata')
      .eq('provider_id', providerId)
      .order('achieved_at', { ascending: false });

    if (milestonesError) {
      throw milestonesError;
    }

    // Fetch recent transactions
    const { searchParams } = new URL(request.url);
    const limit = parseInt(searchParams.get('limit') || '20');
    const offset = parseInt(searchParams.get('offset') || '0');

    const { data: transactions, error: transactionsError } = await supabase
      .from('provider_point_transactions')
      .select('id, points, source, source_id, description, created_at')
      .eq('provider_id', providerId)
      .order('created_at', { ascending: false })
      .range(offset, offset + limit - 1);

    if (transactionsError) {
      throw transactionsError;
    }

    // Fetch all available badges for progress tracking
    const { data: allBadges, error: badgesError } = await supabase
      .from('provider_badges')
      .select('*')
      .eq('is_active', true)
      .order('tier', { ascending: true });

    if (badgesError) {
      throw badgesError;
    }

    // Get provider stats - calculate directly from source data for accuracy
    const supabaseAdmin = getSupabaseAdmin();

    // Calculate total bookings directly from bookings table
    const { count: totalBookingsCount } = await supabaseAdmin
      .from('bookings')
      .select('*', { count: 'exact', head: true })
      .eq('provider_id', providerId);

    // Calculate reviews and rating directly from reviews table
    const { data: reviewsData, count: reviewCount } = await supabaseAdmin
      .from('reviews')
      .select('rating', { count: 'exact' })
      .eq('provider_id', providerId);

    let averageRating = 0;
    if (reviewsData && reviewsData.length > 0) {
      const sum = reviewsData.reduce((acc, review) => acc + (Number(review.rating) || 0), 0);
      averageRating = sum / reviewsData.length;
    }

    // Calculate total earnings from finance_ledger (same as dashboard) for consistency
    // This includes provider_earnings from bookings, add-ons, gift cards, memberships, and refund impacts
    const { data: ledgerRows } = await supabaseAdmin
      .from('finance_ledger')
      .select('net, transaction_type')
      .eq('provider_id', providerId)
      .eq('transaction_type', 'provider_earnings');

    let totalEarnings = 0;
    if (ledgerRows) {
      totalEarnings = ledgerRows.reduce((sum, row) => {
        return sum + (Number(row.net ?? 0) || 0);
      }, 0);
    }

    // Calculate progress to next badge
    let progressToNextBadge = null;

    const badge = Array.isArray(pointsData?.provider_badges) ? pointsData?.provider_badges?.[0] : pointsData?.provider_badges;
    if (allBadges && pointsData) {
      const currentTier = badge?.tier || 0;
      const nextBadgeCandidate = allBadges.find(b => b.tier > currentTier);

      if (nextBadgeCandidate) {
        const _nextBadge = nextBadgeCandidate;
        const requiredPoints = (nextBadgeCandidate.requirements as any)?.points || 0;
        const currentPoints = pointsData.total_points || 0;
        const progress = requiredPoints > 0 
          ? Math.min(100, Math.round((currentPoints / requiredPoints) * 100))
          : 0;
        progressToNextBadge = {
          badge: nextBadgeCandidate,
          current_points: currentPoints,
          required_points: requiredPoints,
          points_needed: Math.max(0, requiredPoints - currentPoints),
          progress_percentage: progress,
        };
      }
    }

    return successResponse({
      points: {
        total: pointsData?.total_points || 0,
        lifetime: pointsData?.lifetime_points || 0,
        current_tier: pointsData?.current_tier_points || 0,
        last_calculated: pointsData?.last_calculated_at,
      },
      current_badge: badge ? {
        id: badge.id,
        name: badge.name,
        slug: badge.slug,
        description: badge.description,
        icon_url: badge.icon_url,
        tier: badge.tier,
        color: badge.color,
        requirements: badge.requirements,
        benefits: badge.benefits,
        earned_at: pointsData.badge_earned_at,
        expires_at: pointsData.badge_expires_at,
      } : null,
      milestones: milestones || [],
      transactions: transactions || [],
      progress_to_next_badge: progressToNextBadge,
      provider_stats: {
        total_bookings: totalBookingsCount || 0,
        review_count: reviewCount || 0,
        rating_average: averageRating,
        total_earnings: totalEarnings,
      },
    });
  } catch (error) {
    return handleApiError(error, 'Failed to fetch gamification data');
  }
}

/**
 * POST /api/provider/gamification
 * 
 * Manually trigger recalculation of provider points and badges
 */
export async function POST(request: NextRequest) {
  try {
    const supabase = await getSupabaseServer(request);
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);

    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return handleApiError(
        new Error('Provider not found'),
        'NOT_FOUND',
        404
      );
    }

    const supabaseAdmin = getSupabaseAdmin();

    // Check if provider has any transactions, if not, backfill them
    const { count: transactionCount } = await supabaseAdmin
      .from('provider_point_transactions')
      .select('*', { count: 'exact', head: true })
      .eq('provider_id', providerId);

    // If no transactions exist, backfill historical data
    if (transactionCount === 0) {
      try {
        await supabaseAdmin.rpc('backfill_provider_point_transactions', {
          p_provider_id: providerId,
        });
      } catch (backfillError) {
        console.warn('Failed to backfill transactions:', backfillError);
        // Continue with recalculation even if backfill fails
      }
    }

    // Recalculate gamification
    const result = await recalculateProviderGamification(providerId);

    return successResponse({
      message: 'Gamification recalculated successfully',
      points: result.points,
      badge_id: result.badge_id,
      transactions_backfilled: transactionCount === 0,
    });
  } catch (error) {
    return handleApiError(error, 'Failed to recalculate gamification');
  }
}

