      .map((i: any) => {
        const pr = payRunMap.get(i.pay_run_id);
        if (!pr) return null;
        return {
        pay_run_id: pr?.id,
        pay_period_start: pr?.pay_period_start,
        pay_period_end: pr?.pay_period_end,
