      .sort((a: any, b: any) => new Date(b.pay_period_end).getTime() - new Date(a.pay_period_end).getTime())
      .slice(0, 24);

    return successResponse(payStubs);
  } catch (error) {
    return handleApiError(error, "Failed to load my earnings");
  }
