/**
 * PATCH /api/provider/payment-methods/[id]
 * Update a payment method
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const permissionCheck = await requirePermission("edit_settings", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }

    const supabase = await getSupabaseServer(request);
    const body = await request.json();
    const providerId = await getProviderIdForUser(permissionCheck.user!.id);

    if (!providerId) {
      return handleApiError(
        new Error("Provider not found"),
        "Provider not found",
        "NOT_FOUND",
        404
      );
    }

    const updates: any = {};

    if (body.name !== undefined) updates.name = body.name;
    if (body.is_default !== undefined) updates.is_default = body.is_default;
    if (body.is_active !== undefined) updates.is_active = body.is_active;
    if (body.metadata !== undefined) updates.metadata = body.metadata;

    const { data: paymentMethod, error } = await supabase
      .from("provider_payment_methods")
      .update(updates)
      .eq("id", id)
      .eq("provider_id", providerId)
      .select()
      .single();

    if (error) {
      throw error;
    }

    if (!paymentMethod) {
      return handleApiError(
        new Error("Payment method not found"),
        "Payment method not found",
        "NOT_FOUND",
        404
      );
    }

    return successResponse(paymentMethod);
  } catch (error) {
    return handleApiError(error, "Failed to update payment method");
  }
}

/**
 * DELETE /api/provider/payment-methods/[id]
 * Delete a payment method
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const permissionCheck = await requirePermission("edit_settings", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }

    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(permissionCheck.user!.id);

    if (!providerId) {
      return handleApiError(
        new Error("Provider not found"),
        "Provider not found",
        "NOT_FOUND",
        404
      );
    }

    // Soft delete by setting is_active to false
    const { error } = await supabase
      .from("provider_payment_methods")
      .update({ is_active: false })
      .eq("id", id)
      .eq("provider_id", providerId);

    if (error) {
      throw error;
    }

    return successResponse({ success: true });
  } catch (error) {
    return handleApiError(error, "Failed to delete payment method");
  }
}

import { NextRequest } from "next/server";
import { requireRoleInApi, getProviderIdForUser, notFoundResponse, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";

/**
 * GET /api/provider/payments
 * 
 * List payment transactions for provider
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) return notFoundResponse("Provider not found");

    const { searchParams } = new URL(request.url);
    
    // Parse query parameters
    const search = searchParams.get('search');
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '20');
    const offset = (page - 1) * limit;
    const dateFrom = searchParams.get('date_from');
    const dateTo = searchParams.get('date_to');
    const paymentMethod = searchParams.get('payment_method');
    const teamMemberId = searchParams.get('team_member_id');

    // Get bookings for this provider
    let bookingsQuery = supabaseAdmin
      .from('bookings')
      .select('id, scheduled_at, ref_number, booking_number')
      .eq('provider_id', providerId);

    if (dateFrom) {
      bookingsQuery = bookingsQuery.gte('scheduled_at', `${dateFrom}T00:00:00`);
    }
    if (dateTo) {
      bookingsQuery = bookingsQuery.lte('scheduled_at', `${dateTo}T23:59:59`);
    }

    const { data: bookings, error: bookingsError } = await bookingsQuery;

    if (bookingsError) {
      throw bookingsError;
    }

    const bookingIds = bookings?.map(b => b.id) || [];
    const bookingMap = new Map(bookings?.map(b => [b.id, b]) || []);

    if (bookingIds.length === 0) {
      return successResponse({
        data: [],
        total: 0,
        page,
        limit,
        total_pages: 1,
      });
    }

    // Get booking payments
    let paymentsQuery = supabaseAdmin
      .from('booking_payments')
      .select(`
        id,
        booking_id,
        amount,
        payment_method,
        payment_provider,
        status,
        notes,
        created_at,
        created_by,
        bookings!inner(
          id,
          scheduled_at,
          duration_minutes,
          ref_number,
          booking_number
        )
      `, { count: 'exact' })
      .in('booking_id', bookingIds)
      .order('created_at', { ascending: false });

    // Apply filters
    if (paymentMethod) {
      paymentsQuery = paymentsQuery.eq('payment_method', paymentMethod);
    }

    // Apply pagination
    paymentsQuery = paymentsQuery.range(offset, offset + limit - 1);

    const { data: payments, error: paymentsError, count } = await paymentsQuery;

    if (paymentsError) {
      throw paymentsError;
    }

    // Get team member info if needed
    const teamMemberIds = new Set<string>();
    payments?.forEach((p: any) => {
      if (p.created_by) {
        teamMemberIds.add(p.created_by);
      }
    });

    let teamMembersMap = new Map();
    if (teamMemberIds.size > 0) {
      const { data: teamMembers } = await supabaseAdmin
        .from('provider_staff')
        .select('id, name')
        .in('id', Array.from(teamMemberIds));
      
      teamMembersMap = new Map(teamMembers?.map(tm => [tm.id, tm.name]) || []);
    }

    // Map to PaymentTransaction format
    const transactions = (payments || []).map((p: any) => {
      const booking = p.bookings || bookingMap.get(p.booking_id);
      const teamMemberName = p.created_by ? teamMembersMap.get(p.created_by) : undefined;

      return {
        id: p.id,
        ref_number: booking?.ref_number || booking?.booking_number || `PAY-${p.id.slice(0, 8).toUpperCase()}`,
        payment_date: p.created_at,
        appointment_id: p.booking_id,
        appointment_duration: booking?.duration_minutes,
        team_member_id: p.created_by || undefined,
        team_member_name: teamMemberName,
        method: p.payment_method === 'yoco' ? 'yoco' : 
                p.payment_method === 'paystack' ? 'card' :
                p.payment_method === 'card' ? 'card' :
                p.payment_method === 'cash' ? 'cash' :
                p.payment_method === 'bank_transfer' ? 'cash' : // Map bank_transfer to cash for display
                'cash', // Default fallback
        amount: Number(p.amount || 0),
        status: p.status === 'completed' ? 'completed' : 
                p.status === 'pending' ? 'pending' : 'failed',
        yoco_payment_id: p.payment_provider === 'yoco' ? p.id : undefined,
        yoco_device_id: undefined, // Would need to join with yoco_payments table
      };
    });

    // Apply search filter if provided
    let filteredTransactions = transactions;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredTransactions = transactions.filter(t => 
        t.ref_number.toLowerCase().includes(searchLower) ||
        t.team_member_name?.toLowerCase().includes(searchLower) ||
        t.method.toLowerCase().includes(searchLower)
      );
    }

    // Apply team member filter if provided
    if (teamMemberId) {
      filteredTransactions = filteredTransactions.filter(t => t.team_member_id === teamMemberId);
    }

    const totalPages = count ? Math.ceil(count / limit) : 1;

    return successResponse({
      data: filteredTransactions,
      total: count || filteredTransactions.length,
      page,
      limit,
      total_pages: totalPages,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch payment transactions");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  getProviderIdForUser,
  successResponse,
  notFoundResponse,
  handleApiError,
  errorResponse,
} from "@/lib/supabase/api-helpers";
import { updateTransferRecipient } from "@/lib/payments/paystack-complete";
import { z } from "zod";

const updateAccountSchema = z.object({
  account_name: z.string().min(1).optional(),
  description: z.string().optional(),
  email: z.string().email().optional(),
  active: z.boolean().optional(),
});

/**
 * GET /api/provider/payout-accounts/[id]
 * 
 * Get a specific payout account
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const { id } = await params;

    const { data: account, error } = await supabase
      .from("provider_payout_accounts")
      .select("*")
      .eq("id", id)
      .eq("provider_id", providerId)
      .is("deleted_at", null)
      .single();

    if (error || !account) {
      return notFoundResponse("Payout account not found");
    }

    return successResponse(account);
  } catch (error) {
    return handleApiError(error, "Failed to fetch payout account");
  }
}

/**
 * PATCH /api/provider/payout-accounts/[id]
 * 
 * Update a payout account
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const { id } = await params;
    const body = await request.json();
    const validationResult = updateAccountSchema.safeParse(body);

    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    // Get existing account
    const { data: account, error: fetchError } = await supabase
      .from("provider_payout_accounts")
      .select("*")
      .eq("id", id)
      .eq("provider_id", providerId)
      .is("deleted_at", null)
      .single();

    if (fetchError || !account) {
      return notFoundResponse("Payout account not found");
    }

    // Update in Paystack if recipient_code exists
    if (account.recipient_code && (validationResult.data.account_name || validationResult.data.email)) {
      try {
        await updateTransferRecipient(account.recipient_code, {
          name: validationResult.data.account_name || account.account_name,
          email: validationResult.data.email || undefined,
          description: validationResult.data.description || undefined,
        });
      } catch (paystackError) {
        console.error("Failed to update Paystack recipient:", paystackError);
        // Continue with database update even if Paystack update fails
      }
    }

    // Update in database
    const updateData: any = {};
    if (validationResult.data.account_name) updateData.account_name = validationResult.data.account_name;
    if (validationResult.data.description !== undefined) {
      updateData.metadata = {
        ...(account.metadata || {}),
        description: validationResult.data.description,
      };
    }
    if (validationResult.data.active !== undefined) updateData.active = validationResult.data.active;

    const { data: updatedAccount, error: updateError } = await supabase
      .from("provider_payout_accounts")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (updateError) {
      throw updateError;
    }

    return successResponse(updatedAccount);
  } catch (error) {
    return handleApiError(error, "Failed to update payout account");
  }
}

/**
 * DELETE /api/provider/payout-accounts/[id]
 * 
 * Delete (soft delete) a payout account
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const { id } = await params;

    // Get existing account
    const { data: account, error: fetchError } = await supabase
      .from("provider_payout_accounts")
      .select("*")
      .eq("id", id)
      .eq("provider_id", providerId)
      .is("deleted_at", null)
      .single();

    if (fetchError || !account) {
      return notFoundResponse("Payout account not found");
    }

    // Soft delete in database
    const { error: deleteError } = await supabase
      .from("provider_payout_accounts")
      .update({
        active: false,
        deleted_at: new Date().toISOString(),
      })
      .eq("id", id);

    if (deleteError) {
      throw deleteError;
    }

    // Optionally delete from Paystack (commented out to preserve history)
    // try {
    //   await deleteTransferRecipient(account.recipient_code);
    // } catch (paystackError) {
    //   console.error("Failed to delete Paystack recipient:", paystackError);
    // }

    return successResponse({ message: "Payout account deleted successfully" });
  } catch (error) {
    return handleApiError(error, "Failed to delete payout account");
  }
}

import { NextRequest } from "next/server";
import { requireRoleInApi, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { listBanks } from "@/lib/payments/paystack-complete";

/** Paystack expects: south africa | nigeria | ghana | kenya (same as /api/public/banks). */
const ISO_TO_PAYSTACK_COUNTRY: Record<string, string> = {
  ZA: "south africa",
  NG: "nigeria",
  GH: "ghana",
  KE: "kenya",
};

const COUNTRY_CURRENCY: Record<string, string> = {
  ZA: "ZAR",
  NG: "NGN",
  GH: "GHS",
  KE: "KES",
};

/**
 * GET /api/provider/payout-accounts/banks
 *
 * List banks from Paystack for a given country (same Paystack API as web /api/public/banks).
 * Used by mobile and web to show bank dropdown when adding payout accounts.
 * Country: ISO code (ZA, NG, GH, KE) ΓÇö converted to Paystack format internally.
 */
export async function GET(request: NextRequest) {
  try {
    await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const { searchParams } = new URL(request.url);
    const countryParam = (searchParams.get("country") || "ZA").trim();
    const isoCountry = countryParam.length === 2 ? countryParam.toUpperCase() : "ZA";
    const paystackCountry = ISO_TO_PAYSTACK_COUNTRY[isoCountry] ?? countryParam.toLowerCase();
    const currency = COUNTRY_CURRENCY[isoCountry] ?? "ZAR";

    const result = await listBanks({
      country: paystackCountry,
      currency,
      perPage: 100,
    });

    const rawData = result.data;
    const list = Array.isArray(rawData)
      ? rawData
      : (rawData as any)?.data ?? [];
    if (!result.status) {
      return errorResponse(
        result.message || "Failed to load banks",
        "PAYSTACK_ERROR",
        400
      );
    }

    const banks = (list as any[]).map((b: any) => ({
      id: b.id,
      code: b.code ?? b.slug ?? String(b.id),
      name: b.name,
      country: isoCountry,
      currency: b.currency ?? currency,
    }));

    return successResponse({ banks, country: isoCountry, currency });
  } catch (error) {
    return handleApiError(error, "Failed to fetch banks");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  getProviderIdForUser,
  successResponse,
  notFoundResponse,
  handleApiError,
  errorResponse,
} from "@/lib/supabase/api-helpers";
import {
  createTransferRecipient,
  deleteTransferRecipient,
  verifyAccount,
} from "@/lib/payments/paystack-complete";
import { z } from "zod";

const createAccountSchema = z.object({
  type: z.enum(["nuban"]),
  account_number: z.string().min(8).max(15),
  bank_code: z.string().min(1),
  account_name: z.string().min(1),
  currency: z.string().min(1).default("ZAR"),
  country: z.string().optional(),
  /** If provided, server skips Paystack verify (saves cost: ZAR 3/call in South Africa). Use when client already called /verify. */
  verified_account_name: z.string().min(1).optional(),
  description: z.string().optional(),
  email: z.string().email().optional(),
});

/**
 * GET /api/provider/payout-accounts
 * 
 * List provider's payout accounts (bank accounts)
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const { data: accounts, error } = await supabase
      .from("provider_payout_accounts")
      .select("*")
      .eq("provider_id", providerId)
      .is("deleted_at", null)
      .order("created_at", { ascending: false });

    if (error) {
      throw error;
    }

    return successResponse(accounts || []);
  } catch (error) {
    return handleApiError(error, "Failed to fetch payout accounts");
  }
}

/**
 * POST /api/provider/payout-accounts
 * 
 * Add a new bank account for payouts
 * Creates a Paystack transfer recipient and stores it
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const body = await request.json();
    const validationResult = createAccountSchema.safeParse(body);

    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues.map((issue) => ({
          path: issue.path.join("."),
          message: issue.message,
        }))
      );
    }

    const { account_number, bank_code, account_name, type, currency, country, verified_account_name, description, email } = validationResult.data;

    // Superadmin-controlled: skip Paystack verify when platform setting is on (saves ZAR 3 in SA; if transfer fails, provider uploads bank confirmation letter).
    const { data: platformRow } = await (supabase as any)
      .from("platform_settings")
      .select("settings")
      .eq("is_active", true)
      .limit(1)
      .maybeSingle();
    const skipVerify = (platformRow?.settings as any)?.paystack?.skip_payout_account_verification === true;

    // Resolve display name: skip verify (superadmin setting), use pre-verified name, or call Paystack verify
    let resolvedName: string;
    if (skipVerify) {
      resolvedName = account_name.trim();
    } else if (verified_account_name?.trim()) {
      resolvedName = verified_account_name.trim();
    } else {
      const verifyResult = await verifyAccount({ account_number, bank_code });
      if (!verifyResult.status || !verifyResult.data?.account_name) {
        return errorResponse(
          verifyResult.message || "Invalid bank account. Please check the account number and bank.",
          "ACCOUNT_VERIFICATION_FAILED",
          400
        );
      }
      resolvedName = verifyResult.data.account_name;
    }

    // Create transfer recipient in Paystack (use resolved name for exact match)
    const paystackRecipient = await createTransferRecipient({
      type: type as "nuban",
      name: resolvedName,
      account_number,
      bank_code,
      currency: currency || "ZAR",
      description: description || `Payout account for ${resolvedName}`,
      email: email || undefined,
      metadata: {
        provider_id: providerId,
        added_by: user.id,
      },
    });

    if (!paystackRecipient.data) {
      return errorResponse(
        paystackRecipient.message || "Failed to create transfer recipient",
        "PAYSTACK_ERROR",
        500
      );
    }

    // Extract account details from Paystack response (align with DB schema)
    const details = (paystackRecipient.data as any)?.details;
    const accountNumberLast4 = account_number.slice(-4);

    // Store in database - all columns must match provider_payout_accounts schema
    const { data: savedAccount, error: saveError } = await supabase
      .from("provider_payout_accounts")
      .insert({
        provider_id: providerId,
        recipient_code: paystackRecipient.data.recipient_code,
        recipient_id: paystackRecipient.data.id ?? null,
        type: paystackRecipient.data.type || "nuban",
        account_number_last4: accountNumberLast4,
        account_name: details?.account_name || resolvedName || account_name,
        bank_code: details?.bank_code || bank_code,
        bank_name: details?.bank_name ?? null,
        currency: paystackRecipient.data.currency || currency,
        active: paystackRecipient.data.active !== false,
        metadata: {
          paystack_response: paystackRecipient.data,
          added_by: user.id,
          country: country ?? undefined,
        },
      })
      .select()
      .single();

    if (saveError) {
      // If save fails, try to delete the Paystack recipient
      try {
        await deleteTransferRecipient(paystackRecipient.data.recipient_code);
      } catch (deleteError) {
        console.error("Failed to cleanup Paystack recipient:", deleteError);
      }
      throw saveError;
    }

    return successResponse(savedAccount);
  } catch (error) {
    return handleApiError(error, "Failed to add payout account");
  }
}

import { NextRequest } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { getAvailablePayoutBalance } from "@/lib/provider/available-payout-balance";

/**
 * GET /api/provider/payouts
 *
 * List provider payouts from payouts table.
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);

    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);

    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const status = searchParams.get("status");
    const startDate = searchParams.get("start_date");
    const endDate = searchParams.get("end_date");

    let query = supabase
      .from("payouts")
      .select("*")
      .eq("provider_id", providerId)
      .order("created_at", { ascending: false });

    if (status) {
      query = query.eq("status", status);
    }

    if (startDate) {
      query = query.gte("created_at", `${startDate}T00:00:00`);
    }

    if (endDate) {
      query = query.lte("created_at", `${endDate}T23:59:59`);
    }

    const { data: payouts, error } = await query;

    if (error) {
      throw error;
    }

    // Map to provider-friendly shape (requested_at = created_at for display)
    const mapped = (payouts || []).map((p: any) => ({
      ...p,
      requested_at: p.created_at,
      notes: p.payout_account_details?.notes ?? p.notes ?? null,
    }));

    return successResponse(mapped);
  } catch (error) {
    return handleApiError(error, "Failed to fetch payouts");
  }
}

/**
 * POST /api/provider/payouts
 *
 * Request a payout. Creates record in payouts table for admin to process.
 * Uses service role to bypass RLS (we validate provider + balance server-side).
 */
export async function POST(request: NextRequest) {
  try {
    const permissionCheck = await requirePermission("process_payments", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;

    const supabase = await getSupabaseServer(request);
    const body = await request.json();
    const { amount, bank_account_id, notes } = body;

    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    if (!amount || amount <= 0) {
      return errorResponse("Amount must be greater than 0", "VALIDATION_ERROR", 400);
    }

    const numAmount = Number(amount);
    const { data: platformRow } = await (supabase as any)
      .from("platform_settings")
      .select("settings")
      .eq("is_active", true)
      .limit(1)
      .maybeSingle();
    const minimumPayout = (platformRow?.settings as any)?.payouts?.minimum_payout_amount ?? 100;
    if (numAmount < minimumPayout) {
      return errorResponse(
        `Minimum payout amount is ${minimumPayout} ZAR. You requested ${numAmount}.`,
        "BELOW_MINIMUM_PAYOUT",
        400
      );
    }

    const { availableBalance } = await getAvailablePayoutBalance(supabase, providerId);

    if (amount > availableBalance) {
      return errorResponse(
        `Insufficient balance. Available: ${availableBalance}, Requested: ${amount}`,
        "INSUFFICIENT_BALANCE",
        400
      );
    }

    // Resolve payout account: use bank_account_id from body if valid, else primary (latest active)
    const { data: accounts } = await supabase
      .from("provider_payout_accounts")
      .select("id, recipient_code, account_name, account_number_last4, bank_name")
      .eq("provider_id", providerId)
      .eq("active", true)
      .is("deleted_at", null)
      .order("created_at", { ascending: false });

    const accountList = accounts || [];
    if (accountList.length === 0) {
      return errorResponse(
        "Add at least one bank account in Settings ΓåÆ Payout Accounts to request a payout.",
        "NO_PAYOUT_ACCOUNT",
        400
      );
    }

    const chosenAccount = bank_account_id
      ? accountList.find((a: any) => a.id === bank_account_id)
      : accountList[0];
    if (bank_account_id && !chosenAccount) {
      return errorResponse("Selected bank account not found or inactive.", "INVALID_ACCOUNT", 400);
    }
    const payoutAccountId = chosenAccount?.id ?? accountList[0].id;

    // Insert into payouts table (service role bypasses RLS)
    const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
    if (!serviceRoleKey) {
      throw new Error("SUPABASE_SERVICE_ROLE_KEY not configured");
    }

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      serviceRoleKey
    );

    const payoutAccountDetails = {
      ...(notes && { notes }),
      bank_account_id: payoutAccountId,
    };

    const { data: payout, error: payoutError } = await supabaseAdmin
      .from("payouts")
      .insert({
        provider_id: providerId,
        payout_number: "",
        amount: Number(amount),
        currency: "ZAR",
        status: "pending",
        payout_method: "bank_transfer",
        payout_account_details: Object.keys(payoutAccountDetails).length > 0 ? payoutAccountDetails : {},
        platform_fee_amount: 0,
        platform_fee_percentage: 15,
        net_amount: Number(amount),
        scheduled_at: new Date().toISOString(),
      })
      .select()
      .single();

    if (payoutError) {
      throw payoutError;
    }


    try {
      await supabaseAdmin.from("notifications").insert({
        user_id: user.id,
        type: "payout_requested",
        title: "Payout Requested",
        message: `Payout request of ${amount} ZAR has been submitted`,
        metadata: { payout_id: payout.id, amount },
      });
    } catch {
      // Ignore notification errors
    }

    return successResponse({
      ...payout,
      requested_at: payout.created_at,
      notes: notes || null,
    });
  } catch (error) {
    return handleApiError(error, "Failed to create payout request");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  getProviderIdForUser,
  successResponse,
  notFoundResponse,
  errorResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";
import { z } from "zod";

const updateSchema = z.object({
  status: z
    .enum([
      "confirmed",
      "processing",
      "ready_for_collection",
      "shipped",
      "delivered",
      "cancelled",
      "refunded",
    ])
    .optional(),
  tracking_number: z.string().max(100).optional(),
  estimated_delivery_date: z.string().optional(),
  cancellation_reason: z.string().max(500).optional(),
});

const STATUS_TRANSITIONS: Record<string, string[]> = {
  pending: ["confirmed", "cancelled"],
  confirmed: ["processing", "cancelled"],
  processing: ["ready_for_collection", "shipped", "cancelled"],
  ready_for_collection: ["delivered", "cancelled"],
  shipped: ["delivered"],
  delivered: ["refunded"],
  cancelled: [],
  refunded: [],
};

/**
 * GET /api/provider/product-orders/[id]
 * Get order detail for provider
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const { data: order, error } = await (supabase.from("product_orders") as any)
      .select(
        `
        *,
        items:product_order_items (
          id, product_id, product_variant_id, product_name, product_image_url, quantity, unit_price, total_price,
          product_variant:product_variants(id, option_values)
        ),
        customer:users!product_orders_customer_id_fkey (
          id, full_name, email, avatar_url, phone
        ),
        delivery_address:user_addresses (
          id, label, address_line1, address_line2, city, state, postal_code, country,
          apartment_unit, building_name, floor_number, parking_instructions, location_landmarks
        ),
        collection_location:provider_locations (
          id, name, address_line1, city
        )
      `,
      )
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (error || !order) {
      return notFoundResponse("Order not found");
    }

    return successResponse({ order });
  } catch (err) {
    return handleApiError(err, "Failed to fetch order");
  }
}

/**
 * PATCH /api/provider/product-orders/[id]
 * Update order status with transition validation
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const body = await request.json();
    const parsed = updateSchema.parse(body);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    // Get current order
    const { data: order, error: fetchErr } = await (supabase.from("product_orders") as any)
      .select("id, status, provider_id")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (fetchErr || !order) {
      return notFoundResponse("Order not found");
    }

    // Validate status transition
    if (parsed.status) {
      const allowed = STATUS_TRANSITIONS[order.status] ?? [];
      if (!allowed.includes(parsed.status)) {
        return errorResponse(
          `Cannot transition from "${order.status}" to "${parsed.status}"`,
          "INVALID_TRANSITION",
          400,
        );
      }
    }

    // Build update payload
    const updatePayload: Record<string, any> = {};
    if (parsed.status) {
      updatePayload.status = parsed.status;
      if (parsed.status === "confirmed") updatePayload.confirmed_at = new Date().toISOString();
      if (parsed.status === "shipped") updatePayload.shipped_at = new Date().toISOString();
      if (parsed.status === "delivered") updatePayload.delivered_at = new Date().toISOString();
      if (parsed.status === "cancelled") {
        updatePayload.cancelled_at = new Date().toISOString();
        updatePayload.cancellation_reason = parsed.cancellation_reason ?? null;
      }
      if (parsed.status === "delivered" || parsed.status === "shipped") {
        updatePayload.payment_status = "paid";
      }
      if (parsed.status === "refunded") {
        updatePayload.payment_status = "refunded";
      }
    }
    if (parsed.tracking_number) updatePayload.tracking_number = parsed.tracking_number;
    if (parsed.estimated_delivery_date)
      updatePayload.estimated_delivery_date = parsed.estimated_delivery_date;

    // On cancellation, restore stock (variant or product-level)
    if (parsed.status === "cancelled") {
      const { data: items } = await (supabase.from("product_order_items") as any)
        .select("product_id, product_variant_id, quantity")
        .eq("order_id", id);

      if (items) {
        for (const item of items) {
          if (item.product_variant_id) {
            try {
              await (supabase.rpc as any)("increment_product_variant_stock", {
                p_variant_id: item.product_variant_id,
                p_quantity: item.quantity,
              });
            } catch {
              const { data: v } = await (supabase.from("product_variants") as any)
                .select("quantity")
                .eq("id", item.product_variant_id)
                .single();
              if (v) {
                await (supabase.from("product_variants") as any)
                  .update({ quantity: (v.quantity ?? 0) + item.quantity })
                  .eq("id", item.product_variant_id);
              }
            }
          } else {
            try {
              await supabase.rpc("increment_product_stock" as any, {
                p_product_id: item.product_id,
                p_quantity: item.quantity,
              });
            } catch {
              const { data: prod } = await (supabase.from("products") as any)
                .select("quantity")
                .eq("id", item.product_id)
                .single();
              if (prod) {
                await (supabase.from("products") as any)
                  .update({ quantity: (prod.quantity ?? 0) + item.quantity })
                  .eq("id", item.product_id);
              }
            }
          }
        }
      }
    }

    const { data: updated, error: updateErr } = await (supabase.from("product_orders") as any)
      .update(updatePayload)
      .eq("id", id)
      .select("*, customer:users!product_orders_customer_id_fkey(id, full_name)")
      .single();

    if (updateErr) throw updateErr;

    // Dispatch notification to customer based on status change
    if (parsed.status && updated?.customer?.id) {
      const notificationMap: Record<string, { type: string; title: string; message: string }> = {
        confirmed: {
          type: "product_order_confirmed",
          title: "Order Confirmed",
          message: `Your order ${updated.order_number} has been confirmed and is being prepared.`,
        },
        shipped: {
          type: "product_order_shipped",
          title: "Order Shipped",
          message: `Your order ${updated.order_number} has been shipped.${parsed.tracking_number ? ` Tracking: ${parsed.tracking_number}` : ""}`,
        },
        ready_for_collection: {
          type: "product_order_ready_collection",
          title: "Ready for Collection",
          message: `Your order ${updated.order_number} is ready for collection.`,
        },
        delivered: {
          type: "product_order_delivered",
          title: "Order Delivered",
          message: `Your order ${updated.order_number} has been delivered. Enjoy!`,
        },
        cancelled: {
          type: "product_order_cancelled",
          title: "Order Cancelled",
          message: `Your order ${updated.order_number} has been cancelled.${parsed.cancellation_reason ? ` Reason: ${parsed.cancellation_reason}` : ""}`,
        },
      };

      const notif = notificationMap[parsed.status];
      if (notif) {
        await supabase.from("notifications").insert({
          user_id: updated.customer.id,
          type: notif.type,
          title: notif.title,
          message: notif.message,
          metadata: {
            product_order_id: id,
            order_number: updated.order_number,
            status: parsed.status,
          },
          link: "/product-orders",
        }).then(() => {}, () => {});
      }
    }

    return successResponse({ order: updated });
  } catch (err) {
    return handleApiError(err, "Failed to update order");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  getProviderIdForUser,
  successResponse,
  notFoundResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";

/**
 * GET /api/provider/product-orders
 * List product orders for the provider
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "20");
    const status = searchParams.get("status");
    const offset = (page - 1) * limit;

    let query = (supabase.from("product_orders") as any)
      .select(
        `
        *,
        items:product_order_items (
          id, product_id, product_variant_id, product_name, product_image_url, quantity, unit_price, total_price,
          product_variant:product_variants(id, option_values)
        ),
        customer:users!product_orders_customer_id_fkey (
          id, full_name, email, avatar_url
        )
      `,
        { count: "exact" },
      )
      .eq("provider_id", providerId)
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (status) {
      query = query.eq("status", status);
    }

    const { data: orders, error, count } = await query;
    if (error) throw error;

    return successResponse({
      orders: orders ?? [],
      pagination: {
        page,
        limit,
        total: count ?? 0,
        totalPages: Math.ceil((count ?? 0) / limit),
      },
    });
  } catch (err) {
    return handleApiError(err, "Failed to fetch product orders");
  }
}

import { NextRequest } from "next/server";
