      .update({
        provider_response: parsed.provider_response,
        provider_response_at: new Date().toISOString(),
      })
      .eq("id", id)
      .select()
      .single();

    if (error) throw error;

    return successResponse({ review: updated });
  } catch (err) {
    return handleApiError(err, "Failed to respond to review");
  }
}

