 */
export async function GET(request: NextRequest) {
  try {
    const permissionCheck = await requirePermission('view_client_ratings', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return handleApiError(new Error("Provider not found"), "Provider account required", 403);
    }

    const searchParams = request.nextUrl.searchParams;
    const customerId = searchParams.get("customer_id");
    const locationId = searchParams.get("location_id");
    const limit = parseInt(searchParams.get("limit") || "50");
    const offset = parseInt(searchParams.get("offset") || "0");

    // Build query for individual ratings
    let query = supabase
      .from("provider_client_ratings")
      .select(`
        id,
        booking_id,
        customer_id,
        location_id,
        rating,
        comment,
        is_visible,
        created_at,
        updated_at,
        bookings:bookings!provider_client_ratings_booking_id_fkey(
          id,
          booking_number,
          scheduled_at,
          completed_at,
          status
        )
      `)
      .eq("provider_id", providerId)
      .eq("is_visible", true)
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (customerId) {
      query = query.eq("customer_id", customerId);
    }

    if (locationId) {
      query = query.eq("location_id", locationId);
    }

    const { data: ratings, error } = await query;

    if (error) throw error;

    // Transform ratings to include booking info
    const transformedRatings = (ratings || []).map((rating: any) => ({
      id: rating.id,
      booking_id: rating.booking_id,
      booking_number: rating.bookings?.booking_number || null,
      customer_id: rating.customer_id,
      location_id: rating.location_id,
      rating: rating.rating,
      comment: rating.comment,
      is_visible: rating.is_visible,
      created_at: rating.created_at,
      updated_at: rating.updated_at,
      scheduled_at: rating.bookings?.scheduled_at || null,
      completed_at: rating.bookings?.completed_at || null,
      booking_status: rating.bookings?.status || null,
    }));

    return successResponse({
      ratings: transformedRatings,
      total: transformedRatings.length,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch ratings");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getProviderIdForUser, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { z } from "zod";

const createRatingSchema = z.object({
  booking_id: z.string().uuid("Invalid booking ID"),
  rating: z.number().int().min(1).max(5),
  comment: z.string().optional(),
  location_id: z.string().uuid().optional().nullable(),
});

/**
 * POST /api/provider/ratings
 * 
 * Create a provider-to-client rating
 */
export async function POST(request: NextRequest) {
  try {
    const permissionCheck = await requirePermission('rate_clients', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return handleApiError(new Error("Provider not found"), "Provider account required", 403);
    }

    const body = createRatingSchema.parse(await request.json());
    const { booking_id, rating, comment, location_id } = body;

    // Verify booking exists and belongs to provider
    const { data: booking, error: bookingError } = await supabase
      .from("bookings")
      .select("id, provider_id, customer_id, status")
      .eq("id", booking_id)
      .eq("provider_id", providerId)
      .single();

    if (bookingError || !booking) {
      return handleApiError(new Error("Booking not found"), "Booking not found or doesn't belong to your provider", 404);
    }

    // Only allow ratings for completed or no_show bookings
    if (!["completed", "no_show"].includes(booking.status)) {
      return handleApiError(
        new Error("Invalid booking status"),
        "Ratings can only be created for completed or no-show bookings",
        400
      );
    }

    // Check if rating already exists
    const { data: existing } = await supabase
      .from("provider_client_ratings")
      .select("id")
      .eq("booking_id", booking_id)
      .single();

    if (existing) {
      return handleApiError(new Error("Rating already exists"), "A rating already exists for this booking", 400);
    }

    // Create rating
    const { data: newRating, error: createError } = await supabase
      .from("provider_client_ratings")
      .insert({
        booking_id,
        provider_id: providerId,
        customer_id: booking.customer_id,
        location_id: location_id || null,
        rating,
        comment: comment || null,
        is_visible: true,
      })
      .select("id, rating, comment, created_at")
      .single();

    if (createError) throw createError;

    return successResponse(newRating);
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        error,
        error.issues.map((e: any) => e.message).join(", "),
        "VALIDATION_ERROR",
        400
      );
    }
    return handleApiError(error, "Failed to create rating");
  }
}

/**
 * GET /api/provider/ratings
 * 
 * Get aggregate ratings for customers (provider view)
 * Returns aggregate statistics, not individual reviews
 */
export async function GET(request: NextRequest) {
  try {
    const permissionCheck = await requirePermission('view_client_ratings', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return handleApiError(new Error("Provider not found"), "Provider account required", 403);
    }

    const searchParams = request.nextUrl.searchParams;
    const customerId = searchParams.get("customer_id");
    const locationId = searchParams.get("location_id");
    const bookingId = searchParams.get("booking_id");

    // If booking_id is provided, check if rating exists for that booking
    if (bookingId) {
      const { data: existingRating, error: checkError } = await supabase
        .from("provider_client_ratings")
        .select("id")
        .eq("booking_id", bookingId)
        .eq("provider_id", providerId)
        .maybeSingle();

      if (checkError) {
        throw checkError;
      }

      return successResponse({
        has_rating: !!existingRating,
      });
    }

    // Build query for aggregate statistics
    let query = supabase
      .from("provider_client_ratings")
      .select("rating")
      .eq("provider_id", providerId)
      .eq("is_visible", true);

    if (customerId) {
      query = query.eq("customer_id", customerId);
    }

    if (locationId) {
      query = query.eq("location_id", locationId);
    }

    const { data: ratings, error } = await query;

    if (error) throw error;

    // Calculate aggregate statistics
    const totalRatings = ratings?.length || 0;
    const averageRating = totalRatings > 0
      ? ratings.reduce((sum, r) => sum + r.rating, 0) / totalRatings
      : 0;
    
    const ratingDistribution = [1, 2, 3, 4, 5].map(star => ({
      stars: star,
      count: ratings?.filter(r => r.rating === star).length || 0,
    }));

    return successResponse({
      total_ratings: totalRatings,
      average_rating: Math.round(averageRating * 100) / 100,
      rating_distribution: ratingDistribution,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch ratings");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, handleApiError } from "@/lib/supabase/api-helpers";

export interface ReferenceDataItem {
  id: string;
  type: string;
  value: string;
  label: string;
  description?: string;
  display_order: number;
  is_active: boolean;
  metadata: Record<string, any>;
}

export interface ReferenceDataResponse {
  [type: string]: ReferenceDataItem[];
}

/**
 * GET /api/provider/reference-data
 * 
 * Get all reference data for dropdowns and selections.
 * Optionally filter by type using query parameter: ?type=service_type,duration
 * 
 * Available types:
 * - service_type: Service types (basic, package, addon, variant)
 * - duration: Service duration options
 * - price_type: Pricing types (fixed, from, free, varies)
 * - availability: Who can book (everyone, women, men)
 * - tax_rate: Tax rate options
 * - team_role: Team member roles
 * - reminder_unit: Reminder time units (days, weeks, months)
 * - extra_time: Extra/buffer time options
 * - payment_method: Payment methods
 * - booking_status: Booking status options
 * - currency: Currency options
 * - cancellation_reason: Cancellation reasons
 * - discount_type: Discount types
 * - notification_channel: Notification channels
 */
export async function GET(request: NextRequest) {
  try {
    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);
    const typesParam = searchParams.get("type");
    const activeOnly = searchParams.get("active") !== "false"; // Default to active only

    // Build query
    let query = supabase
      .from("reference_data")
      .select("*")
      .order("type")
      .order("display_order", { ascending: true });

    // Filter by active status
    if (activeOnly) {
      query = query.eq("is_active", true);
    }

    // Filter by types if specified
    if (typesParam) {
      const types = typesParam.split(",").map(t => t.trim());
      query = query.in("type", types);
    }

    const { data, error } = await query;

    if (error) {
      throw error;
    }

    // Group by type for easier consumption
    const groupedData: ReferenceDataResponse = {};
    
    (data || []).forEach((item: ReferenceDataItem) => {
      if (!groupedData[item.type]) {
        groupedData[item.type] = [];
      }
      groupedData[item.type].push({
        id: item.id,
        type: item.type,
        value: item.value,
        label: item.label,
        description: item.description,
        display_order: item.display_order,
        is_active: item.is_active,
        metadata: item.metadata || {},
      });
    });

    return successResponse(groupedData);
  } catch (error) {
    return handleApiError(error, "Failed to fetch reference data");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, handleApiError, getProviderIdForUser, notFoundResponse, errorResponse } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { z } from "zod";

const updateSchema = z.object({
  name: z.string().min(1).optional(),
  description: z.string().optional(),
  is_active: z.boolean().optional(),
});

/**
 * PATCH /api/provider/referral-sources/[id]
 * Update a referral source
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Check permission to edit settings
    const permissionCheck = await requirePermission('edit_settings', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const { id } = await params;
    const body = await request.json();
    const validationResult = updateSchema.safeParse(body);

    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    // For superadmin, allow updating any source; for providers, only their own
    let providerId: string | null = null;
    if (user.role === "superadmin") {
      // Get provider_id from the source itself
      const { data: sourceCheck } = await supabase
        .from("referral_sources")
        .select("provider_id")
        .eq("id", id)
        .single();
      if (sourceCheck) {
        providerId = sourceCheck.provider_id;
      }
    } else {
      providerId = await getProviderIdForUser(user.id, supabase);
      if (!providerId) {
        return notFoundResponse("Provider not found");
      }
    }

    // Verify referral source exists
    let verifyQuery = supabase
      .from("referral_sources")
      .select("id")
      .eq("id", id);

    if (providerId) {
      verifyQuery = verifyQuery.eq("provider_id", providerId);
    }

    const { data: existing } = await verifyQuery.single();

    if (!existing) {
      return notFoundResponse("Referral source not found");
    }

    // Prepare update data
    const updateData: any = {};
    if (validationResult.data.name !== undefined) {
      updateData.name = validationResult.data.name.trim();
    }
    if (validationResult.data.description !== undefined) {
      updateData.description = validationResult.data.description?.trim() || null;
    }
    if (validationResult.data.is_active !== undefined) {
      updateData.is_active = validationResult.data.is_active;
    }
    updateData.updated_at = new Date().toISOString();

    const { data, error } = await supabase
      .from("referral_sources")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (error) {
      throw error;
    }

    return successResponse(data);
  } catch (error) {
    return handleApiError(error, "Failed to update referral source");
  }
}

