      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );    const searchParams = request.nextUrl.searchParams;
    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) return notFoundResponse("Provider not found");

    let fromDate = searchParams.get("from")
      ? new Date(searchParams.get("from")!)
      : subDays(new Date(), 30);
    const toDate = searchParams.get("to")
      ? new Date(searchParams.get("to")!)
      : new Date();

    const daysDiff = Math.ceil((toDate.getTime() - fromDate.getTime()) / (1000 * 60 * 60 * 24));
    if (daysDiff > MAX_REPORT_DAYS) {
      fromDate = subDays(toDate, MAX_REPORT_DAYS);
    }

    // Get no-show bookings (simplified query to avoid deep nesting)
    const { data: noShowBookings, error: bookingsError } = await supabaseAdmin
      .from("bookings")
      .select(
        `
        id,
        total_amount,
        scheduled_at,
        customer_id,
        booking_services (
          id,
          staff_id
        )
      `
      )
      .eq("provider_id", providerId)
      .eq("status", "no_show")
      .gte("scheduled_at", fromDate.toISOString())
      .lte("scheduled_at", toDate.toISOString())
      .order("scheduled_at", { ascending: false })
      .limit(MAX_BOOKINGS_FOR_REPORT);

    if (bookingsError) {
      console.error("Error fetching no-show bookings:", bookingsError);
      return handleApiError(
        new Error(`Failed to fetch no-show bookings: ${bookingsError.message}`),
        "BOOKINGS_FETCH_ERROR",
        500
      );
    }

    // Get client information separately
    const clientIds = new Set<string>();
    noShowBookings?.forEach((booking: any) => {
      if (booking.customer_id) {
        clientIds.add(booking.customer_id);
      }
    });

    const clientMap = new Map<string, { full_name: string; email: string }>();
    if (clientIds.size > 0) {
      const { data: clients, error: clientError } = await supabaseAdmin
        .from("users")
        .select("id, full_name, email")
        .in("id", Array.from(clientIds));

      if (clientError) {
        console.warn("Error fetching clients:", clientError);
      } else {
        clients?.forEach((client: any) => {
          clientMap.set(client.id, {
            full_name: client.full_name || "Unknown",
            email: client.email || "",
          });
        });
      }
    }

    // Get staff information separately
    const staffIds = new Set<string>();
    noShowBookings?.forEach((booking: any) => {
      booking.booking_services?.forEach((bs: any) => {
        if (bs.staff_id) {
          staffIds.add(bs.staff_id);
        }
      });
    });

    const staffNameMap = new Map<string, string>();
    if (staffIds.size > 0) {
      const { data: staffMembers, error: staffError } = await supabaseAdmin
        .from("provider_staff")
        .select("id, user_id, users(full_name)")
        .in("id", Array.from(staffIds));

      if (staffError) {
        console.warn("Error fetching staff:", staffError);
      } else {
        staffMembers?.forEach((staff: any) => {
          const staffName = staff.users?.full_name || "Unknown";
          staffNameMap.set(staff.id, staffName);
        });
      }
    }

    // Get total bookings for no-show rate (capped for performance)
    const { data: allBookings } = await supabaseAdmin
      .from("bookings")
      .select("id")
      .eq("provider_id", providerId)
      .gte("scheduled_at", fromDate.toISOString())
      .lte("scheduled_at", toDate.toISOString())
      .limit(MAX_BOOKINGS_FOR_REPORT);

    const totalBookings = allBookings?.length || 0;
    const totalNoShows = noShowBookings?.length || 0;
    const noShowRate = totalBookings > 0 ? (totalNoShows / totalBookings) * 100 : 0;

    // Calculate lost revenue from finance_transactions (what provider would have earned)
    const noShowBookingIds = noShowBookings?.map((b) => b.id) || [];
    let lostRevenue = 0;
    if (noShowBookingIds.length > 0) {
      const { revenueByBooking } = await getProviderRevenue(
        supabaseAdmin,
        providerId,
        fromDate,
        toDate
      );
      // Sum revenue for no-show bookings (if they had finance_transactions)
      noShowBookingIds.forEach((bookingId) => {
        lostRevenue += revenueByBooking.get(bookingId) || 0;
      });
    }

    // Group by client (repeat offenders)
    const repeatOffenderMap = new Map<string, { name: string; email: string; count: number; revenue: number }>();
    noShowBookings?.forEach((booking) => {
      const clientId = booking.customer_id;
      if (clientId) {
        const clientInfo = clientMap.get(clientId) || { full_name: "Unknown", email: "" };
        const existing = repeatOffenderMap.get(clientId) || {
          name: clientInfo.full_name,
          email: clientInfo.email,
          count: 0,
          revenue: 0,
        };
        existing.count += 1;
        // Note: For client-level analysis, we could use finance_transactions here too
        // but for now keeping total_amount for client perspective
        existing.revenue += Number(booking.total_amount || 0);
        repeatOffenderMap.set(clientId, existing);
      }
    });

    const repeatOffenders = Array.from(repeatOffenderMap.values())
      .filter((c) => c.count > 1)
      .sort((a, b) => b.count - a.count);

    // Group by staff
    const staffBreakdownMap = new Map<string, { name: string; count: number }>();
    noShowBookings?.forEach((booking) => {
      booking.booking_services?.forEach((bs: any) => {
        if (bs.staff_id) {
          const staffName = staffNameMap.get(bs.staff_id) || "Unknown";
          const existing = staffBreakdownMap.get(bs.staff_id) || { name: staffName, count: 0 };
          existing.count += 1;
          staffBreakdownMap.set(bs.staff_id, existing);
        }
      });
    });

    const staffBreakdown = Array.from(staffBreakdownMap.values())
      .sort((a, b) => b.count - a.count);

    return successResponse({
      totalNoShows,
      totalBookings,
      noShowRate,
      lostRevenue,
      repeatOffenders,
      staffBreakdown,
      recentNoShows: noShowBookings?.slice(0, 20) || [],
    });
  } catch (error) {
    return handleApiError(error, "NO_SHOWS_ERROR", 500);
  }
}

import { NextRequest } from "next/server";
import { requireRoleInApi, getProviderIdForUser, notFoundResponse, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays, getDay } from "date-fns";

const DAY_NAMES = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      { auth: { autoRefreshToken: false, persistSession: false } },
    );    const sp = request.nextUrl.searchParams;
    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) return notFoundResponse("Provider not found");

    const fromDate = sp.get("from") ? new Date(sp.get("from")!) : subDays(new Date(), 30);
    const toDate = sp.get("to") ? new Date(sp.get("to")!) : new Date();

    const { data: bookings } = await supabaseAdmin
      .from("bookings")
      .select("id, status, scheduled_at, cancellation_reason")
      .eq("provider_id", providerId)
      .gte("scheduled_at", fromDate.toISOString())
      .lte("scheduled_at", new Date(toDate.getTime() + 86400000).toISOString());

    const all = bookings || [];
    const total = all.length;

    const statusCounts = new Map<string, number>();
    const dayOfWeekCounts = new Map<string, number>();
    const cancelReasons = new Map<string, number>();
    let completedCount = 0;
    let cancelledCount = 0;
    let noShowCount = 0;

    DAY_NAMES.forEach((d) => dayOfWeekCounts.set(d, 0));

    all.forEach((b: any) => {
      statusCounts.set(b.status, (statusCounts.get(b.status) ?? 0) + 1);
      const dayName = DAY_NAMES[getDay(new Date(b.scheduled_at))] ?? "Mon";
      dayOfWeekCounts.set(dayName, (dayOfWeekCounts.get(dayName) ?? 0) + 1);

      if (b.status === "completed") completedCount++;
      else if (b.status === "cancelled") {
        cancelledCount++;
        if (b.cancellation_reason) {
          cancelReasons.set(b.cancellation_reason, (cancelReasons.get(b.cancellation_reason) ?? 0) + 1);
        }
      } else if (b.status === "no_show") noShowCount++;
    });

    const daysDiff = Math.max(1, Math.ceil((toDate.getTime() - fromDate.getTime()) / 86400000));

    return successResponse({
      total_bookings: total,
      by_status: Array.from(statusCounts.entries()).map(([status, count]) => ({ status, count })),
      by_day_of_week: DAY_NAMES.map((day) => ({ day, count: dayOfWeekCounts.get(day) ?? 0 })),
      completion_rate: total > 0 ? (completedCount / total) * 100 : 0,
      cancellation_count: cancelledCount,
      no_show_count: noShowCount,
      avg_per_day: total / daysDiff,
      cancellation_reasons: Array.from(cancelReasons.entries())
        .map(([reason, count]) => ({ reason, count }))
        .sort((a, b) => b.count - a.count),
    });
  } catch (error) {
    console.error("Error in bookings report:", error);
    return handleApiError(error, "Failed to generate bookings report");
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays } from "date-fns";
import { getProviderRevenue } from "@/lib/reports/revenue-helpers";
import { MAX_REPORT_DAYS, MAX_BOOKINGS_FOR_REPORT } from "@/lib/reports/constants";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );    const searchParams = request.nextUrl.searchParams;
    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) return notFoundResponse("Provider not found");

    const locationId = searchParams.get("location_id");
    let fromDate = searchParams.get("from")
      ? new Date(searchParams.get("from")!)
      : subDays(new Date(), 30);
    const toDate = searchParams.get("to")
      ? new Date(searchParams.get("to")!)
      : new Date();

    const daysDiff = Math.ceil((toDate.getTime() - fromDate.getTime()) / (1000 * 60 * 60 * 24));
    if (daysDiff > MAX_REPORT_DAYS) {
      fromDate = subDays(toDate, MAX_REPORT_DAYS);
    }

    // Get all bookings
    let bookingsQuery = supabaseAdmin
      .from("bookings")
      .select(
        `
        id,
        total_amount,
        scheduled_at,
        status,
        customer_id,
        location_id,
        booking_services (
          id,
          price,
          offering_id,
          staff_id,
          offerings:offering_id (
            title
          )
        )
      `
      )
      .eq("provider_id", providerId)
      .gte("scheduled_at", fromDate.toISOString())
      .lte("scheduled_at", toDate.toISOString());

    // Filter by location if provided
    if (locationId) {
      bookingsQuery = bookingsQuery.eq("location_id", locationId);
    }

    const { data: bookings, error: bookingsError } = await bookingsQuery
      .order("scheduled_at", { ascending: false })
      .limit(MAX_BOOKINGS_FOR_REPORT);

    if (bookingsError) {
      return handleApiError(
        new Error("Failed to fetch bookings"),
        "BOOKINGS_FETCH_ERROR",
        500
      );
    }

    // Get provider revenue from finance_transactions
    const { totalRevenue, revenueByBooking, revenueByDate } = await getProviderRevenue(
      supabaseAdmin,
      providerId,
      fromDate,
      toDate,
      locationId || undefined
    );

    // Calculate summary metrics
    const totalBookings = bookings?.length || 0;
    const averageBookingValue = totalBookings > 0 ? totalRevenue / totalBookings : 0;

    // Group by status
    const statusCounts: Record<string, number> = {};
    const statusRevenue: Record<string, number> = {};
    bookings?.forEach((booking) => {
      const status = booking.status || "unknown";
      statusCounts[status] = (statusCounts[status] || 0) + 1;
      // Use revenue from finance_transactions for this booking
      const bookingRevenue = revenueByBooking.get(booking.id) || 0;
      statusRevenue[status] = (statusRevenue[status] || 0) + bookingRevenue;
    });

    // Group by day (use finance_transactions revenue)
    const bookingsByDay = new Map<string, { count: number; revenue: number }>();
    bookings?.forEach((booking) => {
      const date = new Date(booking.scheduled_at).toISOString().split("T")[0];
      const existing = bookingsByDay.get(date) || { count: 0, revenue: 0 };
      existing.count += 1;
      bookingsByDay.set(date, existing);
    });
    // Add revenue from finance_transactions
    revenueByDate.forEach((revenue, date) => {
      const existing = bookingsByDay.get(date) || { count: 0, revenue: 0 };
      existing.revenue += revenue;
      bookingsByDay.set(date, existing);
    });

    const dailyBookings = Array.from(bookingsByDay.entries())
      .map(([date, data]) => ({ date, count: data.count, revenue: data.revenue }))
      .sort((a, b) => a.date.localeCompare(b.date));

    // Group by service - use finance_transactions revenue (consistent with status breakdown)
    const serviceMap = new Map<string, { serviceName: string; bookings: number; revenue: number }>();
    (bookings || []).forEach((booking) => {
      const bookingRevenue = revenueByBooking.get(booking.id) || 0;
      if (!booking.booking_services || !Array.isArray(booking.booking_services)) return;
      const totalServicePrice = booking.booking_services.reduce(
        (sum: number, s: any) => sum + Number(s.price || 0),
        0
      );
      booking.booking_services.forEach((bs: any) => {
        const serviceName = bs.offerings?.title || "Unknown";
        const existing = serviceMap.get(serviceName) || { serviceName, bookings: 0, revenue: 0 };
        existing.bookings += 1;
        const serviceProportion = totalServicePrice > 0
          ? Number(bs.price || 0) / totalServicePrice
          : 1 / booking.booking_services.length;
        existing.revenue += bookingRevenue * serviceProportion;
        serviceMap.set(serviceName, existing);
      });
    });

    const topServices = Array.from(serviceMap.values())
      .sort((a, b) => b.bookings - a.bookings)
      .slice(0, 10);

    return successResponse({
      totalBookings,
      totalRevenue,
      averageBookingValue,
      statusBreakdown: Object.entries(statusCounts).map(([status, count]) => ({
        status,
        count,
        revenue: statusRevenue[status] || 0,
        percentage: totalBookings > 0 ? (count / totalBookings) * 100 : 0,
      })),
      dailyBookings,
      topServices,
    });
  } catch (error) {
    return handleApiError(error, "BOOKING_SUMMARY_ERROR", 500);
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays, subMonths } from "date-fns";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    const { data: providerData, error: providerError } = await supabaseAdmin
      .from('providers')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();

    if (providerError || !providerData?.id) {
      return handleApiError(
        new Error('Provider profile not found'),
        'NOT_FOUND',
        404
      );
    }
    const searchParams = request.nextUrl.searchParams;
    const locationId = searchParams.get("location_id");
    const period = searchParams.get("period") || "month"; // month, quarter, year

    let fromDate: Date;
    const toDate = new Date();

    switch (period) {
      case "month":
        fromDate = subMonths(toDate, 1);
        break;
      case "quarter":
        fromDate = subMonths(toDate, 3);
        break;
      case "year":
        fromDate = subMonths(toDate, 12);
        break;
      default:
        fromDate = subMonths(toDate, 1);
    }

    // Get bookings
    let bookingsQuery = supabaseAdmin
      .from("bookings")
      .select("id, total_amount, scheduled_at, status, customer_id, location_id")
      .eq("provider_id", providerId)
      .gte("scheduled_at", fromDate.toISOString())
      .lte("scheduled_at", toDate.toISOString());

    // Filter by location if provided
    if (locationId) {
      bookingsQuery = bookingsQuery.eq("location_id", locationId);
    }

    const { data: bookings, error: bookingsError } = await bookingsQuery;

    if (bookingsError) {
      return handleApiError(
        new Error("Failed to fetch bookings"),
        "BOOKINGS_FETCH_ERROR",
        500
      );
    }

    // Get staff
    const { data: staff } = await supabaseAdmin
      .from("provider_staff")
      .select("id")
      .eq("provider_id", providerId);

    // Get payments
    const bookingIds = bookings?.map((b) => b.id) || [];
    let paymentsQuery = supabaseAdmin
      .from("payments")
      .select("id, amount, status, refunded_amount")
      .gte("created_at", fromDate.toISOString())
      .lte("created_at", toDate.toISOString());

    if (bookingIds.length > 0) {
      paymentsQuery = paymentsQuery.in("booking_id", bookingIds);
    } else {
      paymentsQuery = paymentsQuery.eq("booking_id", "00000000-0000-0000-0000-000000000000");
    }

    const { data: payments } = await paymentsQuery;

    // Calculate metrics from finance_transactions (more accurate - uses actual provider earnings)
    // Get provider earnings from finance_transactions for the period
    const financeQuery = supabaseAdmin
      .from("finance_transactions")
      .select("id, transaction_type, amount, net, booking_id, created_at")
      .eq("provider_id", providerId)
      .in("transaction_type", ["provider_earnings", "travel_fee", "tip"])
      .gte("created_at", fromDate.toISOString())
      .lte("created_at", toDate.toISOString());

    const { data: financeTransactions } = await financeQuery;

    // Get booking information for filtering by location and booking_source
    const financeBookingIds = [...new Set((financeTransactions || []).filter((t: any) => t.booking_id).map((t: any) => t.booking_id))];
    let bookingMap: Record<string, { booking_source: string | null; location_id: string | null }> = {};

    if (financeBookingIds.length > 0) {
      let bookingsForFinanceQuery = supabaseAdmin
        .from("bookings")
        .select("id, booking_source, location_id")
        .in("id", financeBookingIds);

      if (locationId) {
        bookingsForFinanceQuery = bookingsForFinanceQuery.eq("location_id", locationId);
      }

      const { data: bookingsForFinance } = await bookingsForFinanceQuery;

      if (bookingsForFinance) {
        bookingMap = bookingsForFinance.reduce((acc: any, b: any) => {
          acc[b.id] = {
            booking_source: b.booking_source || null,
            location_id: b.location_id || null,
          };
          return acc;
        }, {});
      }
    }

    // Filter transactions by location and include all (for reports, we show all earnings)
    const validTransactions = (financeTransactions || []).filter((t: any) => {
      if (!t.booking_id) return true; // Include non-booking transactions
      if (locationId && bookingMap[t.booking_id]?.location_id !== locationId) return false;
      return true;
    });

    // Calculate revenue from finance_transactions (actual provider earnings)
    const totalRevenue = validTransactions.reduce((sum: number, t: any) => sum + Number(t.net || t.amount || 0), 0);
    const totalBookings = bookings?.length || 0;
    const completedBookings = bookings?.filter((b) => b.status === "completed").length || 0;
    const cancelledBookings = bookings?.filter((b) => b.status === "cancelled").length || 0;
    const noShows = bookings?.filter((b) => b.status === "no_show").length || 0;

    const uniqueClients = new Set(bookings?.map((b) => b.customer_id).filter(Boolean)).size;
    const totalStaff = staff?.length || 0;

    const totalPayments = payments?.length || 0;
    const successfulPayments = payments?.filter((p) => p.status === "completed").length || 0;
    const totalRefunded = payments?.reduce((sum, p) => sum + Number(p.refunded_amount || 0), 0) || 0;
    const netRevenue = totalRevenue - totalRefunded;

    // Calculate average booking value from provider earnings (not booking total)
    // Group finance transactions by booking to get earnings per booking
    const earningsByBooking = new Map<string, number>();
    validTransactions.forEach((t: any) => {
      if (t.booking_id) {
        const current = earningsByBooking.get(t.booking_id) || 0;
        earningsByBooking.set(t.booking_id, current + Number(t.net || t.amount || 0));
      }
    });
    const totalEarningsFromBookings = Array.from(earningsByBooking.values()).reduce((sum, val) => sum + val, 0);
    const bookingsWithEarnings = earningsByBooking.size;
    const averageBookingValue = bookingsWithEarnings > 0 ? totalEarningsFromBookings / bookingsWithEarnings : 0;
    const completionRate = totalBookings > 0 ? (completedBookings / totalBookings) * 100 : 0;
    const cancellationRate = totalBookings > 0 ? (cancelledBookings / totalBookings) * 100 : 0;
    const noShowRate = totalBookings > 0 ? (noShows / totalBookings) * 100 : 0;

    // Get previous period for growth (using finance_transactions for accuracy)
    const daysDiff = Math.ceil((toDate.getTime() - fromDate.getTime()) / (1000 * 60 * 60 * 24));
    const prevFromDate = subDays(fromDate, daysDiff);
    const prevToDate = fromDate;

    const prevFinanceQuery = supabaseAdmin
      .from("finance_transactions")
      .select("net, amount, booking_id")
      .eq("provider_id", providerId)
      .in("transaction_type", ["provider_earnings", "travel_fee", "tip"])
      .gte("created_at", prevFromDate.toISOString())
      .lte("created_at", prevToDate.toISOString());

    const { data: prevFinanceTransactions } = await prevFinanceQuery;

    // Filter by location if needed
    const prevValidTransactions = (prevFinanceTransactions || []).filter((t: any) => {
      if (!t.booking_id) return true;
      if (locationId && bookingMap[t.booking_id]?.location_id !== locationId) return false;
      return true;
    });

    const prevRevenue = prevValidTransactions.reduce((sum: number, t: any) => sum + Number(t.net || t.amount || 0), 0);
    const revenueGrowth = prevRevenue > 0 ? ((totalRevenue - prevRevenue) / prevRevenue) * 100 : 0;

    return successResponse({
      period,
      totalRevenue,
      netRevenue,
      totalBookings,
      completedBookings,
      cancelledBookings,
      noShows,
      uniqueClients,
      totalStaff,
      totalPayments,
      successfulPayments,
      totalRefunded,
      averageBookingValue,
      completionRate,
      cancellationRate,
      noShowRate,
      revenueGrowth,
    });
  } catch (error) {
    return handleApiError(error, "BUSINESS_OVERVIEW_ERROR", 500);
  }
}

