    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    const { data: providerData, error: providerError } = await supabaseAdmin
      .from('providers')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();

    if (providerError || !providerData?.id) {
      return handleApiError(
        new Error('Provider profile not found'),
        'NOT_FOUND',
        404
      );
    }
    const searchParams = request.nextUrl.searchParams;
    const fromDate = searchParams.get("from")
      ? new Date(searchParams.get("from")!)
      : subMonths(new Date(), 6);
    const toDate = searchParams.get("to")
      ? new Date(searchParams.get("to")!)
      : new Date();

    // Get all bookings to find first visit per client
    const { data: allBookings, error: allBookingsError } = await supabaseAdmin
      .from("bookings")
      .select("id, customer_id, scheduled_at, total_amount, status")
      .eq("provider_id", providerId)
      .order("scheduled_at", { ascending: true });

    if (allBookingsError) {
      return handleApiError(
        new Error("Failed to fetch bookings"),
        "BOOKINGS_FETCH_ERROR",
        500
      );
    }

    // Find first booking per client
    const firstBookingMap = new Map<string, any>();
    allBookings?.forEach((booking) => {
      if (booking.customer_id && !firstBookingMap.has(booking.customer_id)) {
        firstBookingMap.set(booking.customer_id, booking);
      }
    });

    // Filter new clients (first booking in date range)
    const newClients = Array.from(firstBookingMap.values())
      .filter((booking) => {
        const firstVisit = new Date(booking.scheduled_at);
        return firstVisit >= fromDate && firstVisit <= toDate;
      })
      .map((booking) => ({
        customerId: booking.customer_id,
        firstVisit: booking.scheduled_at,
        firstBookingValue: Number(booking.total_amount || 0),
      }));

    // Get client details
    const clientIds = newClients.map((c) => c.customerId);
    const { data: clients } = await supabaseAdmin
      .from("users")
      .select("id, full_name, email, created_at")
      .in("id", clientIds);

    const clientMap = new Map(clients?.map((c) => [c.id, c]) || []);

    // Enrich new clients with details and calculate if they returned
    const enrichedNewClients = newClients.map((client) => {
      const clientDetails = clientMap.get(client.customerId);
      const allClientBookings = allBookings?.filter((b) => b.customer_id === client.customerId) || [];
      const hasReturned = allClientBookings.length > 1;
      const totalSpent = allClientBookings.reduce((sum, b) => sum + Number(b.total_amount || 0), 0);

      return {
        customerId: client.customerId,
        clientName: clientDetails?.full_name || "Unknown",
        email: clientDetails?.email || "",
        firstVisit: client.firstVisit,
        firstBookingValue: client.firstBookingValue,
        hasReturned,
        totalBookings: allClientBookings.length,
        totalSpent,
      };
    }).sort((a, b) => new Date(b.firstVisit).getTime() - new Date(a.firstVisit).getTime());

    // Summary metrics
    const totalNewClients = enrichedNewClients.length;
    const returnedClients = enrichedNewClients.filter((c) => c.hasReturned).length;
    const returnRate = totalNewClients > 0 ? (returnedClients / totalNewClients) * 100 : 0;
    const totalFirstBookingValue = enrichedNewClients.reduce((sum, c) => sum + c.firstBookingValue, 0);
    const averageFirstBookingValue = totalNewClients > 0 ? totalFirstBookingValue / totalNewClients : 0;

    // Group by month
    const monthlyNewClients = new Map<string, number>();
    enrichedNewClients.forEach((client) => {
      const date = new Date(client.firstVisit);
      const monthKey = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
      monthlyNewClients.set(monthKey, (monthlyNewClients.get(monthKey) || 0) + 1);
    });

    const monthlyBreakdown = Array.from(monthlyNewClients.entries())
      .map(([month, count]) => ({ month, count }))
      .sort((a, b) => a.month.localeCompare(b.month));

    return successResponse({
      totalNewClients,
      returnedClients,
      returnRate,
      totalFirstBookingValue,
      averageFirstBookingValue,
      monthlyBreakdown,
      newClients: enrichedNewClients.slice(0, 50), // Limit to 50 most recent
    });
  } catch (error) {
    return handleApiError(error, "NEW_CLIENTS_ERROR", 500);
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays, subMonths, format, startOfMonth } from "date-fns";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      { auth: { autoRefreshToken: false, persistSession: false } },
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) return notFoundResponse("Provider not found");
    const sp = request.nextUrl.searchParams;
    const fromDate = sp.get("from") ? new Date(sp.get("from")!) : subDays(new Date(), 30);
    const toDate = sp.get("to") ? new Date(sp.get("to")!) : new Date();

    const { data: bookings } = await supabaseAdmin
      .from("bookings")
      .select("id, customer_id, created_at, total_amount, status")
      .eq("provider_id", providerId)
      .gte("scheduled_at", fromDate.toISOString())
      .lte("scheduled_at", new Date(toDate.getTime() + 86400000).toISOString())
      .not("status", "in", "(cancelled,no_show)");

    const all = bookings || [];
    const customerIds = new Set(all.map((b: any) => b.customer_id).filter(Boolean));
    const firstBookingMap = new Map<string, string>();
    all.forEach((b: any) => {
      if (!b.customer_id) return;
      const existing = firstBookingMap.get(b.customer_id);
      if (!existing || new Date(b.created_at) < new Date(existing)) {
        firstBookingMap.set(b.customer_id, b.created_at);
      }
    });

    let newClients = 0;
    let returningClients = 0;
    customerIds.forEach((cid) => {
      const firstDate = firstBookingMap.get(cid);
      if (firstDate && new Date(firstDate) >= fromDate) newClients++;
      else returningClients++;
    });

    const spendByCustomer = new Map<string, { spend: number; visits: number; name: string }>();
    all.forEach((b: any) => {
      if (!b.customer_id) return;
      const existing = spendByCustomer.get(b.customer_id) || { spend: 0, visits: 0, name: b.customer_id };
      existing.spend += Number(b.total_amount || 0);
      existing.visits += 1;
      spendByCustomer.set(b.customer_id, existing);
    });

    const topClientIds = Array.from(spendByCustomer.entries())
      .sort((a, b) => b[1].spend - a[1].spend)
      .slice(0, 10);

    let topClients: { name: string; spend: number; visits: number }[] = [];
    if (topClientIds.length > 0) {
      const { data: customers } = await supabaseAdmin
        .from("users")
        .select("id, full_name")
        .in("id", topClientIds.map(([id]) => id));
      const nameMap = new Map((customers || []).map((c: any) => [c.id, c.full_name || "Unknown"]));
      topClients = topClientIds.map(([id, data]) => ({
        name: nameMap.get(id) || "Client",
        spend: data.spend,
        visits: data.visits,
      }));
    }

    const months: { month: string; count: number }[] = [];
    for (let i = 5; i >= 0; i--) {
      const m = subMonths(new Date(), i);
      const label = format(m, "MMM yyyy");
      const mStart = startOfMonth(m);
      const mEnd = startOfMonth(subMonths(new Date(), i - 1));
      const count = all.filter((b: any) => {
        const d = new Date(b.created_at);
        return d >= mStart && d < mEnd;
      }).length;
      months.push({ month: label, count });
    }

    const totalClients = customerIds.size;
    const retentionRate = totalClients > 0 ? (returningClients / totalClients) * 100 : 0;
    const avgLifetimeValue = totalClients > 0
      ? all.reduce((s, b: any) => s + Number(b.total_amount || 0), 0) / totalClients
      : 0;

    return successResponse({
      new_clients: newClients,
      returning_clients: returningClients,
      total_clients: totalClients,
      retention_rate: retentionRate,
      avg_lifetime_value: avgLifetimeValue,
      top_clients: topClients,
      growth: months,
    });
  } catch (error) {
    console.error("Error in clients report:", error);
    return handleApiError(error, "Failed to generate clients report");
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays } from "date-fns";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    const { data: providerData, error: providerError } = await supabaseAdmin
      .from('providers')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();

    if (providerError || !providerData?.id) {
      return handleApiError(
        new Error('Provider profile not found'),
        'NOT_FOUND',
        404
      );
    }
    const searchParams = request.nextUrl.searchParams;
    const fromDate = searchParams.get("from")
      ? new Date(searchParams.get("from")!)
      : subDays(new Date(), 90);
    const toDate = searchParams.get("to")
      ? new Date(searchParams.get("to")!)
      : new Date();

    // Get all bookings for this provider (simplified query to avoid nested join issues)
    const { data: bookings, error: bookingsError } = await supabaseAdmin
      .from('bookings')
      .select(`
        id,
        customer_id,
        total_amount,
        scheduled_at,
        status
      `)
      .eq('provider_id', providerId)
      .gte('scheduled_at', fromDate.toISOString())
      .lte('scheduled_at', toDate.toISOString());

    if (bookingsError) {
      console.error("Error fetching bookings:", bookingsError);
      return handleApiError(
        new Error(`Failed to fetch bookings: ${bookingsError.message}`),
        'BOOKINGS_FETCH_ERROR',
        500
      );
    }

    // Get client information separately
    const clientIds = new Set<string>();
    bookings?.forEach((booking: any) => {
      if (booking.customer_id) {
        clientIds.add(booking.customer_id);
      }
    });

    const clientInfoMap = new Map<string, { full_name: string }>();
    if (clientIds.size > 0) {
      const { data: clients, error: clientError } = await supabaseAdmin
        .from("users")
        .select("id, full_name")
        .in("id", Array.from(clientIds));

      if (clientError) {
        console.warn("Error fetching clients:", clientError);
      } else {
        clients?.forEach((client: any) => {
          clientInfoMap.set(client.id, {
            full_name: client.full_name || "Unknown",
          });
        });
      }
    }

    // Get all unique clients
    const clientMap = new Map<string, {
      clientId: string;
      clientName: string;
      totalBookings: number;
      totalSpent: number;
      lastVisit: string;
      firstVisit: string;
      bookings: any[];
    }>();

    bookings?.forEach((booking: any) => {
      const clientId = booking.customer_id;
      const clientInfo = clientInfoMap.get(clientId) || { full_name: "Unknown" };
      const existing = clientMap.get(clientId) || {
        clientId,
        clientName: clientInfo.full_name,
        totalBookings: 0,
        totalSpent: 0,
        lastVisit: booking.scheduled_at,
        firstVisit: booking.scheduled_at,
        bookings: [],
      };

      existing.totalBookings += 1;
      existing.totalSpent += Number(booking.total_amount || 0);
      existing.bookings.push(booking);

      if (new Date(booking.scheduled_at) > new Date(existing.lastVisit)) {
        existing.lastVisit = booking.scheduled_at;
      }
      if (new Date(booking.scheduled_at) < new Date(existing.firstVisit)) {
        existing.firstVisit = booking.scheduled_at;
      }

      clientMap.set(clientId, existing);
    });

    const clients = Array.from(clientMap.values());
    const totalClients = clients.length;

    // Get new clients (first booking in date range)
    const newClients = clients.filter((client) => {
      const firstVisit = new Date(client.firstVisit);
      return firstVisit >= fromDate && firstVisit <= toDate;
    }).length;

    // Get returning clients (more than 1 booking)
    const returningClients = clients.filter((c) => c.totalBookings > 1).length;

    // Calculate averages
    const averageBookingsPerClient =
      totalClients > 0
        ? clients.reduce((sum, c) => sum + c.totalBookings, 0) / totalClients
        : 0;

    const averageLifetimeValue =
      totalClients > 0
        ? clients.reduce((sum, c) => sum + c.totalSpent, 0) / totalClients
        : 0;

    // Get reviews for completed bookings to calculate average ratings
    const completedBookingIds = bookings
      ?.filter((b: any) => b.status === 'completed')
      .map((b: any) => b.id) || [];

    const reviewsMap = new Map<string, number[]>();

    if (completedBookingIds.length > 0) {
      const { data: reviews, error: reviewsError } = await supabaseAdmin
        .from('reviews')
        .select('booking_id, rating')
        .in('booking_id', completedBookingIds)
        .not('rating', 'is', null);

      if (!reviewsError && reviews) {
        reviews.forEach((review: any) => {
          const booking = bookings?.find((b: any) => b.id === review.booking_id);
          if (booking?.customer_id) {
            if (!reviewsMap.has(booking.customer_id)) {
              reviewsMap.set(booking.customer_id, []);
            }
            reviewsMap.get(booking.customer_id)!.push(review.rating);
          }
        });
      }
    }

    // Get top clients by revenue
    const topClients = clients
      .sort((a, b) => b.totalSpent - a.totalSpent)
      .slice(0, 10)
      .map((client) => {
        // Calculate average rating for this client from reviews
        const clientRatings = reviewsMap.get(client.clientId) || [];
        const averageRating = clientRatings.length > 0
          ? clientRatings.reduce((sum, rating) => sum + rating, 0) / clientRatings.length
          : 0;

        return {
          clientId: client.clientId,
          clientName: client.clientName,
          totalBookings: client.totalBookings,
          totalSpent: client.totalSpent,
          lastVisit: client.lastVisit,
          averageRating: Math.round(averageRating * 10) / 10, // Round to 1 decimal place
        };
      });

    // Calculate retention rate (simplified - clients who returned)
    const retentionRate =
      totalClients > 0 ? (returningClients / totalClients) * 100 : 0;

    return successResponse({
      totalClients,
      newClients,
      returningClients,
      averageBookingsPerClient,
      averageLifetimeValue,
      topClients,
      clientRetention: {
        period: `${Math.ceil((toDate.getTime() - fromDate.getTime()) / (1000 * 60 * 60 * 24))} days`,
        retentionRate,
      },
    });
  } catch (error) {
    console.error("Error in client summary report:", error);
    return handleApiError(error, "Failed to generate client summary report");
  }
}

