import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays } from "date-fns";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    const { data: providerData, error: providerError } = await supabaseAdmin
      .from('providers')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();

    if (providerError || !providerData?.id) {
      return handleApiError(
        new Error('Provider profile not found'),
        'NOT_FOUND',
        404
      );
    }
    const searchParams = request.nextUrl.searchParams;
    const fromDate = searchParams.get("from")
      ? new Date(searchParams.get("from")!)
      : subDays(new Date(), 30);
    const toDate = searchParams.get("to")
      ? new Date(searchParams.get("to")!)
      : new Date();

    // Get bookings with packages (both via package_id and via booking_services with service_type='package')
    const { data: bookings, error: bookingsError } = await supabaseAdmin
      .from("bookings")
      .select(
        `
        id,
        total_amount,
        scheduled_at,
        status,
        package_id,
        service_packages:package_id (
          id,
          name,
          price
        ),
        booking_services (
          id,
          price,
          offering_id,
          offerings:offering_id (
            id,
            title,
            service_type
          )
        )
      `
      )
      .eq("provider_id", providerId)
      .gte("scheduled_at", fromDate.toISOString())
      .lte("scheduled_at", toDate.toISOString())
      .in("status", ["confirmed", "completed"]);

    if (bookingsError) {
      return handleApiError(
        new Error("Failed to fetch bookings"),
        "BOOKINGS_FETCH_ERROR",
        500
      );
    }

    // Filter for bookings with packages (either via package_id or service_type = 'package')
    const packageBookings = bookings?.filter((booking) =>
      booking.package_id || 
      booking.booking_services?.some((bs: any) => bs.offerings?.service_type === 'package')
    ) || [];

    // Aggregate package sales
    const packageMap = new Map<string, {
      packageId: string;
      packageName: string;
      bookings: number;
      revenue: number;
      averageValue: number;
    }>();

    packageBookings.forEach((booking) => {
      // Handle bookings with package_id (newer approach)
      if (booking.package_id && (booking as any).service_packages) {
        const pkg = (booking as any).service_packages;
        const packageId = pkg.id;
        const existing = packageMap.get(packageId) || {
          packageId,
          packageName: pkg.name || "Unknown Package",
          bookings: 0,
          revenue: 0,
          averageValue: 0,
        };
        existing.bookings += 1;
        existing.revenue += Number(booking.total_amount || 0);
        packageMap.set(packageId, existing);
      }
      
      // Handle bookings with package services (legacy approach)
      booking.booking_services?.forEach((bs: any) => {
        if (bs.offerings?.service_type === 'package') {
          const packageId = bs.offerings.id;
          const existing = packageMap.get(packageId) || {
            packageId,
            packageName: bs.offerings.title || "Unknown Package",
            bookings: 0,
            revenue: 0,
            averageValue: 0,
          };
          existing.bookings += 1;
          existing.revenue += Number(bs.price || booking.total_amount || 0);
          packageMap.set(packageId, existing);
        }
      });
    });

    const packageSales = Array.from(packageMap.values())
      .map((pkg) => ({
        ...pkg,
        averageValue: pkg.bookings > 0 ? pkg.revenue / pkg.bookings : 0,
      }))
      .sort((a, b) => b.revenue - a.revenue);

    const totalPackagesSold = packageSales.reduce((sum, p) => sum + p.bookings, 0);
    const totalRevenue = packageSales.reduce((sum, p) => sum + p.revenue, 0);
    const averagePackageValue = packageSales.length > 0 ? totalRevenue / totalPackagesSold : 0;

    return successResponse({
      totalPackagesSold,
      totalRevenue,
      averagePackageValue,
      packageSales,
    });
  } catch (error) {
    return handleApiError(error, "PACKAGE_SALES_ERROR", 500);
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays } from "date-fns";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    const { data: providerData, error: providerError } = await supabaseAdmin
      .from('providers')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();

    if (providerError || !providerData?.id) {
      return handleApiError(
        new Error('Provider profile not found'),
        'NOT_FOUND',
        404
      );
    }
    const searchParams = request.nextUrl.searchParams;
    const fromDate = searchParams.get("from")
      ? new Date(searchParams.get("from")!)
      : subDays(new Date(), 90);
    const toDate = searchParams.get("to")
      ? new Date(searchParams.get("to")!)
      : new Date();

    // Get bookings with packages (both via package_id and via booking_services with service_type='package')
    const { data: bookings, error: bookingsError } = await supabaseAdmin
      .from("bookings")
      .select(
        `
        id,
        customer_id,
        scheduled_at,
        status,
        package_id,
        service_packages:package_id (
          id,
          name
        ),
        booking_services (
          id,
          offering_id,
          offerings:offering_id (
            id,
            title,
            service_type
          )
        ),
        users (
          full_name,
          email
        )
      `
      )
      .eq("provider_id", providerId)
      .gte("scheduled_at", fromDate.toISOString())
      .lte("scheduled_at", toDate.toISOString())
      .in("status", ["confirmed", "completed"]);

    if (bookingsError) {
      return handleApiError(
        new Error("Failed to fetch bookings"),
        "BOOKINGS_FETCH_ERROR",
        500
      );
    }

    // Filter for bookings with packages (either via package_id or service_type = 'package')
    const packageBookings = bookings?.filter((booking) =>
      booking.package_id || 
      booking.booking_services?.some((bs: any) => bs.offerings?.service_type === 'package')
    ) || [];

    // Aggregate by package
    const packageMap = new Map<string, {
      packageId: string;
      packageName: string;
      totalUsage: number;
      uniqueClients: Set<string>;
      averageUsagePerClient: number;
    }>();

    packageBookings.forEach((booking) => {
      // Handle bookings with package_id (newer approach)
      if (booking.package_id && (booking as any).service_packages) {
        const pkg = (booking as any).service_packages;
        const packageId = pkg.id;
        const existing = packageMap.get(packageId) || {
          packageId,
          packageName: pkg.name || "Unknown Package",
          totalUsage: 0,
          uniqueClients: new Set<string>(),
          averageUsagePerClient: 0,
        };
        existing.totalUsage += 1;
        if (booking.customer_id) {
          existing.uniqueClients.add(booking.customer_id);
        }
        packageMap.set(packageId, existing);
      }
      
      // Handle bookings with package services (legacy approach)
      booking.booking_services?.forEach((bs: any) => {
        if (bs.offerings?.service_type === 'package') {
          const packageId = bs.offerings.id;
          const existing = packageMap.get(packageId) || {
            packageId,
            packageName: bs.offerings.title || "Unknown Package",
            totalUsage: 0,
            uniqueClients: new Set<string>(),
            averageUsagePerClient: 0,
          };
          existing.totalUsage += 1;
          if (booking.customer_id) {
            existing.uniqueClients.add(booking.customer_id);
          }
          packageMap.set(packageId, existing);
        }
      });
    });

    const packageUsage = Array.from(packageMap.values())
      .map((pkg) => ({
        ...pkg,
        uniqueClientsCount: pkg.uniqueClients.size,
        averageUsagePerClient: pkg.uniqueClients.size > 0 ? pkg.totalUsage / pkg.uniqueClients.size : 0,
      }))
      .sort((a, b) => b.totalUsage - a.totalUsage);

    // Aggregate by client
    const clientMap = new Map<string, {
      clientId: string;
      clientName: string;
      email: string;
      packagesUsed: number;
    }>();

    packageBookings.forEach((booking) => {
      const clientId = booking.customer_id;
      if (!clientId) return;

      const client = booking.users as any;
      const existing = clientMap.get(clientId) || {
        clientId,
        clientName: client?.full_name || "Unknown",
        email: client?.email || "",
        packagesUsed: 0,
      };
      existing.packagesUsed += 1;
      clientMap.set(clientId, existing);
    });

    const topClients = Array.from(clientMap.values())
      .sort((a, b) => b.packagesUsed - a.packagesUsed)
      .slice(0, 20);

    const totalPackagesUsed = packageUsage.reduce((sum, p) => sum + p.totalUsage, 0);
    const totalUniqueClients = new Set(
      packageBookings.map((b) => b.customer_id).filter(Boolean)
    ).size;

    return successResponse({
      totalPackagesUsed,
      totalUniqueClients,
      packageUsage,
      topClients,
    });
  } catch (error) {
    return handleApiError(error, "PACKAGE_USAGE_ERROR", 500);
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays } from "date-fns";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      { auth: { autoRefreshToken: false, persistSession: false } },
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) return notFoundResponse("Provider not found");
    const sp = request.nextUrl.searchParams;
    const fromDate = sp.get("from") ? new Date(sp.get("from")!) : subDays(new Date(), 30);
    const toDate = sp.get("to") ? new Date(sp.get("to")!) : new Date();
    const endIso = new Date(toDate.getTime() + 86400000).toISOString();

    const { data: txns } = await supabaseAdmin
      .from("finance_transactions")
      .select("transaction_type, amount, net, created_at, metadata")
      .eq("provider_id", providerId)
      .gte("created_at", fromDate.toISOString())
      .lte("created_at", endIso);

    const all = txns || [];
    let totalCollected = 0;
    let totalRefunded = 0;
    const methodMap = new Map<string, { amount: number; count: number }>();

    all.forEach((t: any) => {
      const val = Number(t.net ?? t.amount ?? 0);
      if (t.transaction_type === "provider_earnings") {
        if (val >= 0) totalCollected += val;
        else totalRefunded += Math.abs(val);
      }
      const method = (t.metadata as any)?.payment_method || "other";
      const existing = methodMap.get(method) || { amount: 0, count: 0 };
      if (val > 0) {
        existing.amount += val;
        existing.count += 1;
      }
      methodMap.set(method, existing);
    });

    const { data: payouts } = await supabaseAdmin
      .from("finance_transactions")
      .select("amount, created_at, transaction_type")
      .eq("provider_id", providerId)
      .eq("transaction_type", "payout")
      .order("created_at", { ascending: false })
      .limit(5);

    const recentPayouts = (payouts || []).map((p: any) => ({
      date: p.created_at,
      amount: Number(p.amount || 0),
      status: "completed",
    }));

    return successResponse({
      total_collected: totalCollected,
      total_refunded: totalRefunded,
      net_revenue: totalCollected - totalRefunded,
      by_method: Array.from(methodMap.entries())
        .map(([method, data]) => ({ method, ...data }))
        .sort((a, b) => b.amount - a.amount),
      recent_payouts: recentPayouts,
      recent_refunds: [],
    });
  } catch (error) {
    console.error("Error in payments report:", error);
    return handleApiError(error, "Failed to generate payments report");
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      { auth: { autoRefreshToken: false, persistSession: false } },
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) return notFoundResponse("Provider not found");
    const { data: products } = await supabaseAdmin
      .from("provider_products")
      .select("id, name, stock_quantity, reorder_point, price")
      .eq("provider_id", providerId)
      .eq("is_active", true);

    const { data: orderItems } = await supabaseAdmin
      .from("product_order_items")
      .select("product_id, quantity, unit_price, product_orders!inner(provider_id, status)")
      .eq("product_orders.provider_id", providerId)
      .not("product_orders.status", "in", "(cancelled,refunded)");

    const salesMap = new Map<string, { name: string; units: number; revenue: number; stock: number }>();

    (products || []).forEach((p: any) => {
      salesMap.set(p.id, { name: p.name, units: 0, revenue: 0, stock: Number(p.stock_quantity || 0) });
    });

    (orderItems || []).forEach((item: any) => {
      const existing = salesMap.get(item.product_id);
      if (existing) {
        existing.units += Number(item.quantity || 0);
        existing.revenue += Number(item.quantity || 0) * Number(item.unit_price || 0);
      }
    });

    const entries = Array.from(salesMap.values());
    const topProducts = entries
      .map((p) => ({ name: p.name, units_sold: p.units, revenue: p.revenue, current_stock: p.stock }))
      .sort((a, b) => b.units_sold - a.units_sold);

    const lowStock = (products || [])
      .filter((p: any) => p.stock_quantity !== null && p.reorder_point !== null && p.stock_quantity <= p.reorder_point)
      .map((p: any) => ({ name: p.name, stock: p.stock_quantity, reorder_point: p.reorder_point }));

    return successResponse({
      total_product_revenue: entries.reduce((s, p) => s + p.revenue, 0),
      total_units_sold: entries.reduce((s, p) => s + p.units, 0),
      top_products: topProducts,
      low_stock: lowStock,
      package_usage: [],
      package_revenue: 0,
    });
  } catch (error) {
    console.error("Error in products report:", error);
    return handleApiError(error, "Failed to generate products report");
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays } from "date-fns";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    const { data: providerData, error: providerError } = await supabaseAdmin
      .from('providers')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();

    if (providerError || !providerData?.id) {
      return handleApiError(
        new Error('Provider profile not found'),
        'NOT_FOUND',
        404
      );
    }
    const searchParams = request.nextUrl.searchParams;
    const fromDate = searchParams.get("from")
      ? new Date(searchParams.get("from")!)
      : subDays(new Date(), 30);
    const toDate = searchParams.get("to")
      ? new Date(searchParams.get("to")!)
      : new Date();

    // Get bookings with product sales in date range
    // Only include completed/confirmed bookings - cancelled/no_show shouldn't count as revenue
    // Also get sales (POS) with product sales
    const [bookingsResult, salesResult] = await Promise.all([
      supabaseAdmin
        .from('bookings')
        .select(`
          id,
          booking_products (
            id,
            product_id,
            quantity,
            unit_price,
            total_price,
            products (
              id,
              name,
              category,
              supply_price
            )
          )
        `)
        .eq('provider_id', providerId)
        .in('status', ['completed', 'confirmed', 'arrived', 'started'])
        .gte('scheduled_at', fromDate.toISOString())
        .lte('scheduled_at', toDate.toISOString()),
      supabaseAdmin
        .from('sales')
        .select(`
          id,
          sale_items (
            id,
            item_id,
            item_name,
            item_type,
            quantity,
            unit_price,
            total_price
          )
        `)
        .eq('provider_id', providerId)
        .eq('payment_status', 'completed')
        .gte('sale_date', fromDate.toISOString())
        .lte('sale_date', toDate.toISOString())
    ]);

    const { data: bookings, error: bookingsError } = bookingsResult;
    const { data: sales, error: salesError } = salesResult;

    // Handle errors gracefully
    if (bookingsError && !bookingsError.message.includes('booking_products')) {
      console.error("Error fetching bookings:", bookingsError);
    }
    if (salesError && !salesError.message.includes('sale_items')) {
      console.error("Error fetching sales:", salesError);
    }

    // Aggregate product sales (revenue + profit)
    const productSalesMap = new Map<string, {
      productId: string;
      productName: string;
      quantitySold: number;
      revenue: number;
      cost: number;
      profit: number;
      prices: number[];
    }>();

    const categoryMap = new Map<string, { quantitySold: number; revenue: number; cost: number; profit: number }>();

    // Process booking products
    // Revenue: use total_price (line total) when available, else quantity * unit_price
    // Per schema: total_price = unit_price * quantity
    (bookings || []).forEach((booking: any) => {
      if (!booking.booking_products || !Array.isArray(booking.booking_products)) {
        return;
      }

      booking.booking_products.forEach((bp: any) => {
        const productId = bp.product_id;
        const productName = bp.products?.name || 'Unknown Product';
        const category = bp.products?.category || 'Uncategorized';
        const quantity = Number(bp.quantity || 0);
        const unitPrice = Number(bp.unit_price || 0);
        const totalPrice = Number(bp.total_price || 0);
        // Use total_price directly (line total) - multiplying by quantity when total_price exists would double-count
        const revenue = totalPrice > 0 ? totalPrice : quantity * unitPrice;
        const supplyPrice = Number(bp.products?.supply_price || 0);
        const cost = quantity * supplyPrice;
        const profit = revenue - cost;

        // Track by product
        const existing = productSalesMap.get(productId) || {
          productId,
          productName,
          quantitySold: 0,
          revenue: 0,
          cost: 0,
          profit: 0,
          prices: [],
        };
        existing.quantitySold += quantity;
        existing.revenue += revenue;
        existing.cost += cost;
        existing.profit += profit;
        existing.prices.push(unitPrice || (quantity > 0 ? revenue / quantity : 0));
        productSalesMap.set(productId, existing);

        // Track by category
        const catExisting = categoryMap.get(category) || {
          quantitySold: 0,
          revenue: 0,
          cost: 0,
          profit: 0,
        };
        catExisting.quantitySold += quantity;
        catExisting.revenue += revenue;
        catExisting.cost += cost;
        catExisting.profit += profit;
        categoryMap.set(category, catExisting);
      });
    });

    // Get product details for sale items
    const saleItemProductIds = new Set<string>();
    (sales || []).forEach((sale: any) => {
      if (sale.sale_items && Array.isArray(sale.sale_items)) {
        sale.sale_items.forEach((item: any) => {
          if (item.item_type === 'product' && item.item_id) {
            saleItemProductIds.add(item.item_id);
          }
        });
      }
    });

    const productMap = new Map<string, { name: string; category: string; supplyPrice: number }>();
    if (saleItemProductIds.size > 0) {
      const { data: productsData } = await supabaseAdmin
        .from('products')
        .select('id, name, category, supply_price')
        .in('id', Array.from(saleItemProductIds));

      productsData?.forEach((p: any) => {
        productMap.set(p.id, {
          name: p.name || 'Unknown',
          category: p.category || 'Uncategorized',
          supplyPrice: Number(p.supply_price || 0),
        });
      });
    }

    // Process sales (POS) products
    // Revenue: use total_price (line total) when available, else quantity * unit_price
    (sales || []).forEach((sale: any) => {
      if (!sale.sale_items || !Array.isArray(sale.sale_items)) {
        return;
      }

      sale.sale_items.forEach((item: any) => {
        // Only process product items (not services)
        if (item.item_type !== 'product' || !item.item_id) {
          return;
        }

        const productId = item.item_id;
        const productInfo = productMap.get(productId);
        const productName = productInfo?.name || item.item_name || 'Unknown Product';
        const category = productInfo?.category || 'Uncategorized';
        const quantity = Number(item.quantity || 0);
        const unitPrice = Number(item.unit_price || 0);
        const totalPrice = Number(item.total_price || 0);
        // Use total_price directly (line total) - avoids undercounting when unit_price is 0
        const revenue = totalPrice > 0 ? totalPrice : quantity * unitPrice;
        const supplyPrice = productInfo?.supplyPrice ?? 0;
        const cost = quantity * supplyPrice;
        const profit = revenue - cost;

        // Track by product
        const existing = productSalesMap.get(productId) || {
          productId,
          productName,
          quantitySold: 0,
          revenue: 0,
          cost: 0,
          profit: 0,
          prices: [],
        };
        existing.quantitySold += quantity;
        existing.revenue += revenue;
        existing.cost += cost;
        existing.profit += profit;
        existing.prices.push(unitPrice || (quantity > 0 ? revenue / quantity : 0));
        productSalesMap.set(productId, existing);

        // Track by category
        const catExisting = categoryMap.get(category) || {
          quantitySold: 0,
          revenue: 0,
          cost: 0,
          profit: 0,
        };
        catExisting.quantitySold += quantity;
        catExisting.revenue += revenue;
        catExisting.cost += cost;
        catExisting.profit += profit;
        categoryMap.set(category, catExisting);
      });
    });

    const totalProductsSold = Array.from(productSalesMap.values())
      .reduce((sum, p) => sum + p.quantitySold, 0);
    const totalRevenue = Array.from(productSalesMap.values())
      .reduce((sum, p) => sum + p.revenue, 0);
    const totalCost = Array.from(productSalesMap.values())
      .reduce((sum, p) => sum + p.cost, 0);
    const totalProfit = totalRevenue - totalCost;
    const averageProductValue = totalProductsSold > 0 ? totalRevenue / totalProductsSold : 0;

    const topProducts = Array.from(productSalesMap.values())
      .map((product) => ({
        productId: product.productId,
        productName: product.productName,
        quantitySold: product.quantitySold,
        revenue: product.revenue,
        cost: product.cost,
        profit: product.profit,
        averagePrice: product.prices.length > 0
          ? product.prices.reduce((sum, p) => sum + p, 0) / product.prices.length
          : 0,
      }))
      .sort((a, b) => b.revenue - a.revenue)
      .slice(0, 10);

    const productsByCategory = Array.from(categoryMap.entries())
      .map(([category, data]) => ({
        category,
        quantitySold: data.quantitySold,
        revenue: data.revenue,
        cost: data.cost,
        profit: data.profit,
      }))
      .sort((a, b) => b.revenue - a.revenue);

    return successResponse({
      totalProductsSold,
      totalRevenue,
      totalCost,
      totalProfit,
      averageProductValue,
      topProducts,
      productsByCategory,
    });
  } catch (error) {
    console.error("Error in product sales report:", error);
    return handleApiError(error, "Failed to generate product sales report");
  }
}

import { NextRequest } from "next/server";
import { requireRoleInApi, successResponse, handleApiError, getProviderIdForUser } from "@/lib/supabase/api-helpers";
