      .from('booking_products')
      .select(`
        id,
        product_id,
        quantity,
        unit_price,
        total_price,
        products (
          id,
          name,
          category,
          retail_price
        )
      `);

    if (bookingIds.length > 0) {
      bookingProductsQuery = bookingProductsQuery.in('booking_id', bookingIds);
    } else {
      bookingProductsQuery = bookingProductsQuery.eq('booking_id', '00000000-0000-0000-0000-000000000000');
    }

    const { data: bookingProducts, error: bookingProductsError } = await bookingProductsQuery;

    // Get sale_items (POS products)
    let saleItemsQuery = supabaseAdmin
      .from('sale_items')
      .select(`
        id,
        item_id,
        item_name,
        item_type,
        quantity,
        unit_price,
        total_price
      `)
      .eq('item_type', 'product');

    if (saleIds.length > 0) {
      saleItemsQuery = saleItemsQuery.in('sale_id', saleIds);
    } else {
      saleItemsQuery = saleItemsQuery.eq('sale_id', '00000000-0000-0000-0000-000000000000');
    }

    const { data: saleItems, error: saleItemsError } = await saleItemsQuery;

    // Get product details for sale items
    const saleItemProductIds = new Set<string>();
    saleItems?.forEach((item: any) => {
      if (item.item_id) {
        saleItemProductIds.add(item.item_id);
      }
    });

    const saleItemProductMap = new Map<string, { name: string; category: string; retail_price: number }>();
    if (saleItemProductIds.size > 0) {
      const { data: productsData } = await supabaseAdmin
        .from('products')
        .select('id, name, category, retail_price')
        .in('id', Array.from(saleItemProductIds));

      productsData?.forEach((p: any) => {
        saleItemProductMap.set(p.id, {
          name: p.name || 'Unknown',
          category: p.category || 'Uncategorized',
          retail_price: Number(p.retail_price || 0)
        });
      });
    }

    // Handle errors gracefully
    if (bookingProductsError && !bookingProductsError.message.includes('booking_products')) {
      console.error("Error fetching booking products:", bookingProductsError);
    }
    if (saleItemsError && !saleItemsError.message.includes('sale_items')) {
      console.error("Error fetching sale items:", saleItemsError);
    }

    // Aggregate by product
    const productMap = new Map<string, {
      productId: string;
      productName: string;
      category: string;
      totalQuantity: number;
      totalRevenue: number;
      averagePrice: number;
      timesSold: number;
    }>();

    // Process booking products
    bookingProducts?.forEach((bp: any) => {
      const product = bp.products;
      if (!product) return;

      const productId = product.id;
      const existing = productMap.get(productId) || {
        productId,
        productName: product.name || "Unknown",
        category: product.category || "Uncategorized",
        totalQuantity: 0,
        totalRevenue: 0,
        averagePrice: 0,
        timesSold: 0,
      };

      const quantity = Number(bp.quantity || 1);
      const price = Number(bp.unit_price || bp.total_price || product.retail_price || 0);

      existing.totalQuantity += quantity;
      existing.totalRevenue += price * quantity;
      existing.timesSold += 1;
      productMap.set(productId, existing);
    });

    // Process sale items (POS products)
    saleItems?.forEach((item: any) => {
      if (!item.item_id) return; // Skip if no product ID

      const productInfo = saleItemProductMap.get(item.item_id);
      const productId = item.item_id;
      const existing = productMap.get(productId) || {
        productId,
        productName: productInfo?.name || item.item_name || "Unknown",
        category: productInfo?.category || "Uncategorized",
        totalQuantity: 0,
        totalRevenue: 0,
        averagePrice: 0,
        timesSold: 0,
      };

      const quantity = Number(item.quantity || 1);
      const price = Number(item.unit_price || item.total_price || productInfo?.retail_price || 0);

      existing.totalQuantity += quantity;
      existing.totalRevenue += price * quantity;
      existing.timesSold += 1;
      productMap.set(productId, existing);
    });

    const topProducts = Array.from(productMap.values())
      .map((product) => ({
        ...product,
        averagePrice: product.totalQuantity > 0 ? product.totalRevenue / product.totalQuantity : 0,
      }))
      .sort((a, b) => b.totalRevenue - a.totalRevenue)
      .slice(0, limit);

    const totalProductsSold = topProducts.reduce((sum, p) => sum + p.totalQuantity, 0);
    const totalRevenue = topProducts.reduce((sum, p) => sum + p.totalRevenue, 0);

    return successResponse({
      topProducts,
      totalProductsSold,
      totalRevenue,
    });
  } catch (error) {
    return handleApiError(error, "TOP_PRODUCTS_ERROR", 500);
  }
}

import { NextRequest } from "next/server";
import { requireRoleInApi, getProviderIdForUser, notFoundResponse, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays, eachDayOfInterval, format } from "date-fns";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      { auth: { autoRefreshToken: false, persistSession: false } },
    );    const sp = request.nextUrl.searchParams;
    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) return notFoundResponse("Provider not found");

    const fromDate = sp.get("from") ? new Date(sp.get("from")!) : subDays(new Date(), 30);
    const toDate = sp.get("to") ? new Date(sp.get("to")!) : new Date();

    const [earningsRes, bookingsRes] = await Promise.all([
      supabaseAdmin
        .from("finance_transactions")
        .select("net, amount, created_at, booking_id")
        .eq("provider_id", providerId)
        .eq("transaction_type", "provider_earnings")
        .gte("created_at", fromDate.toISOString())
        .lte("created_at", new Date(toDate.getTime() + 86400000).toISOString()),
      supabaseAdmin
        .from("bookings")
        .select("id, scheduled_at, booking_services(price, staff_id, offerings:offering_id(title)), provider_staff:booking_services(staff_id, provider_staff:staff_id(users(full_name)))")
        .eq("provider_id", providerId)
        .gte("scheduled_at", fromDate.toISOString())
        .lte("scheduled_at", new Date(toDate.getTime() + 86400000).toISOString())
        .not("status", "in", "(cancelled,no_show)"),
    ]);

    const rows = earningsRes.data || [];
    const totalRevenue = rows.reduce((s, r: any) => s + Number(r.net ?? r.amount ?? 0), 0);

    const prevFrom = subDays(fromDate, Math.ceil((toDate.getTime() - fromDate.getTime()) / 86400000));
    const { data: prevRows } = await supabaseAdmin
      .from("finance_transactions")
      .select("net, amount")
      .eq("provider_id", providerId)
      .eq("transaction_type", "provider_earnings")
      .gte("created_at", prevFrom.toISOString())
      .lte("created_at", fromDate.toISOString());
    const previousRevenue = (prevRows || []).reduce((s, r: any) => s + Number(r.net ?? r.amount ?? 0), 0);

    const days = eachDayOfInterval({ start: fromDate, end: toDate });
    const dailyMap = new Map<string, number>();
    days.forEach((d) => dailyMap.set(format(d, "yyyy-MM-dd"), 0));
    rows.forEach((r: any) => {
      const day = format(new Date(r.created_at), "yyyy-MM-dd");
      dailyMap.set(day, (dailyMap.get(day) ?? 0) + Number(r.net ?? r.amount ?? 0));
    });
    const daily_trend = days.map((d) => ({ date: format(d, "yyyy-MM-dd"), revenue: dailyMap.get(format(d, "yyyy-MM-dd")) ?? 0 }));

    const serviceMap = new Map<string, number>();
    const _staffMap = new Map<string, number>();
    const revenueByBooking = new Map<string, number>();
    rows.forEach((r: any) => {
      if (r.booking_id) revenueByBooking.set(r.booking_id, (revenueByBooking.get(r.booking_id) ?? 0) + Number(r.net ?? r.amount ?? 0));
    });

    (bookingsRes.data || []).forEach((b: any) => {
      const bRev = revenueByBooking.get(b.id) || 0;
      const services = b.booking_services || [];
      const total = services.reduce((s: number, sv: any) => s + Number(sv.price || 0), 0);
      services.forEach((sv: any) => {
        const name = sv.offerings?.title || "Unknown";
        const proportion = total > 0 ? Number(sv.price || 0) / total : 1 / Math.max(services.length, 1);
        serviceMap.set(name, (serviceMap.get(name) ?? 0) + bRev * proportion);
      });
    });

    const revenue_by_service = Array.from(serviceMap.entries())
      .map(([service, revenue]) => ({ service, revenue }))
      .sort((a, b) => b.revenue - a.revenue);

    const transactionCount = rows.length;

    return successResponse({
      total_revenue: totalRevenue,
      previous_revenue: previousRevenue,
      revenue_by_service,
      revenue_by_staff: [] as { staff: string; revenue: number }[],
      daily_trend,
      avg_per_booking: transactionCount > 0 ? totalRevenue / transactionCount : 0,
      transaction_count: transactionCount,
    });
  } catch (error) {
    console.error("Error in revenue report:", error);
    return handleApiError(error, "Failed to generate revenue report");
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays } from "date-fns";
import { getProviderRevenue } from "@/lib/reports/revenue-helpers";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    const { data: providerData, error: providerError } = await supabaseAdmin
      .from('providers')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();

    if (providerError || !providerData?.id) {
      return handleApiError(
        new Error('Provider profile not found'),
        'NOT_FOUND',
        404
      );
    }
    const searchParams = request.nextUrl.searchParams;
    const fromDate = searchParams.get("from")
      ? new Date(searchParams.get("from")!)
      : subDays(new Date(), 30);
    const toDate = searchParams.get("to")
      ? new Date(searchParams.get("to")!)
      : new Date();

    // Get bookings with services (simplified query to avoid deep nesting)
    const { data: bookings, error: bookingsError } = await supabaseAdmin
      .from("bookings")
      .select(
        `
        id,
        total_amount,
        scheduled_at,
        status,
        booking_services (
          id,
          price,
          offering_id,
          offerings:offering_id (
            id,
            title,
            duration_minutes,
            provider_category_id
          )
        )
      `
      )
      .eq("provider_id", providerId)
      .gte("scheduled_at", fromDate.toISOString())
      .lte("scheduled_at", toDate.toISOString())
      .in("status", ["confirmed", "completed"]);

    if (bookingsError) {
      console.error("Error fetching bookings:", bookingsError);
      return handleApiError(
        new Error(`Failed to fetch bookings: ${bookingsError.message}`),
        "BOOKINGS_FETCH_ERROR",
        500
      );
    }

    // Get category information separately to avoid deep nesting
    const categoryIds = new Set<string>();
    bookings?.forEach((booking: any) => {
      booking.booking_services?.forEach((bs: any) => {
        if (bs.offerings?.provider_category_id) {
          categoryIds.add(bs.offerings.provider_category_id);
        }
      });
    });

    const categoryMap = new Map<string, string>();
    if (categoryIds.size > 0) {
      const { data: categories, error: categoryError } = await supabaseAdmin
        .from("provider_categories")
        .select("id, name")
        .in("id", Array.from(categoryIds));

      if (categoryError) {
        console.warn("Error fetching categories:", categoryError);
        // Continue without category names - will default to "Uncategorized"
      } else {
        categories?.forEach((cat: any) => {
          categoryMap.set(cat.id, cat.name || "Uncategorized");
        });
      }
    }

    // Get provider revenue from finance_transactions (actual earnings - consistent with other reports)
    const { revenueByBooking } = await getProviderRevenue(
      supabaseAdmin,
      providerId,
      fromDate,
      toDate
    );

    // Aggregate by service - distribute booking revenue proportionally across services
    const serviceMap = new Map<string, {
      serviceId: string;
      serviceName: string;
      category: string;
      duration: number;
      bookings: number;
      revenue: number;
      averagePrice: number;
    }>();

    (bookings || []).forEach((booking: any) => {
      const bookingRevenue = revenueByBooking.get(booking.id) || 0;
      if (!booking.booking_services || !Array.isArray(booking.booking_services)) return;

      const totalServicePrice = booking.booking_services.reduce(
        (sum: number, s: any) => sum + Number(s.price || 0),
        0
      );

      booking.booking_services.forEach((bs: any) => {
        const service = bs.offerings;
        if (!service) return;

        const serviceId = service.id;
        const categoryName = service.provider_category_id
          ? (categoryMap.get(service.provider_category_id) || "Uncategorized")
          : "Uncategorized";
        const existing = serviceMap.get(serviceId) || {
          serviceId,
          serviceName: service.title || "Unknown",
          category: categoryName,
          duration: service.duration_minutes || 0,
          bookings: 0,
          revenue: 0,
          averagePrice: 0,
        };

        existing.bookings += 1;
        const serviceProportion = totalServicePrice > 0
          ? Number(bs.price || 0) / totalServicePrice
          : 1 / booking.booking_services.length;
        existing.revenue += bookingRevenue * serviceProportion;
        serviceMap.set(serviceId, existing);
      });
    });

    // Calculate averages and sort
    const servicePerformance = Array.from(serviceMap.values())
      .map((service) => ({
        ...service,
        averagePrice: service.bookings > 0 ? service.revenue / service.bookings : 0,
      }))
      .sort((a, b) => b.revenue - a.revenue);

    // Aggregate by category
    const categoryPerformanceMap = new Map<string, {
      categoryName: string;
      services: number;
      bookings: number;
      revenue: number;
    }>();

    servicePerformance.forEach((service) => {
      const existing = categoryPerformanceMap.get(service.category) || {
        categoryName: service.category,
        services: 0,
        bookings: 0,
        revenue: 0,
      };
      existing.services += 1;
      existing.bookings += service.bookings;
      existing.revenue += service.revenue;
      categoryPerformanceMap.set(service.category, existing);
    });

    const categoryPerformance = Array.from(categoryPerformanceMap.values())
      .sort((a, b) => b.revenue - a.revenue);

    // Summary metrics
    const totalServices = servicePerformance.length;
    const totalBookings = servicePerformance.reduce((sum, s) => sum + s.bookings, 0);
    const totalRevenue = servicePerformance.reduce((sum, s) => sum + s.revenue, 0);
    const averageServiceRevenue = totalServices > 0 ? totalRevenue / totalServices : 0;

    return successResponse({
      totalServices,
      totalBookings,
      totalRevenue,
      averageServiceRevenue,
      topServices: servicePerformance.slice(0, 10),
      categoryPerformance,
      allServices: servicePerformance,
    });
  } catch (error) {
    return handleApiError(error, "SERVICE_PERFORMANCE_ERROR", 500);
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays } from "date-fns";
import { getProviderRevenue, getPreviousPeriodRevenue } from "@/lib/reports/revenue-helpers";
import { MAX_REPORT_DAYS, MAX_BOOKINGS_FOR_REPORT } from "@/lib/reports/constants";

export async function GET(request: NextRequest) {
  try {
    // Require provider_owner or provider_staff role
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);    // Use service role client for all queries to avoid RLS infinite recursion
    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    // Get provider ID for user
    const { data: providerData, error: providerError } = await supabaseAdmin
      .from('providers')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();

    if (providerError) {
      console.error('Error fetching provider:', providerError);
      return handleApiError(
        new Error(`Failed to fetch provider: ${providerError.message}`),
        'PROVIDER_FETCH_ERROR',
        500
      );
    }

    if (!providerData || !providerId) {
      return handleApiError(
        new Error('Provider profile not found. Please complete onboarding first.'),
        'NOT_FOUND',
        404
      );
    }
    // Get date range from query params
    const searchParams = request.nextUrl.searchParams;
    const locationId = searchParams.get("location_id");
    let fromDate = searchParams.get("from")
      ? new Date(searchParams.get("from")!)
      : subDays(new Date(), 30);
    const toDate = searchParams.get("to")
      ? new Date(searchParams.get("to")!)
      : new Date();

    const daysDiff = Math.ceil((toDate.getTime() - fromDate.getTime()) / (1000 * 60 * 60 * 24));
    if (daysDiff > MAX_REPORT_DAYS) {
      fromDate = subDays(toDate, MAX_REPORT_DAYS);
    }

    // Get bookings in date range (simplified query to avoid nested join issues)
    let bookingsQuery = supabaseAdmin
      .from("bookings")
      .select(
        `
        id,
        scheduled_at,
        status,
        location_id,
        booking_services (
          id,
          price,
          offering_id,
          staff_id,
          offerings:offering_id (
            title
          )
        )
      `
      )
      .eq("provider_id", providerId)
      .gte("scheduled_at", fromDate.toISOString())
      .lte("scheduled_at", toDate.toISOString());

    // Filter by location if provided
    if (locationId) {
      bookingsQuery = bookingsQuery.eq("location_id", locationId);
    }

    const { data: bookings, error: bookingsError } = await bookingsQuery
      .order("scheduled_at", { ascending: false })
      .limit(MAX_BOOKINGS_FOR_REPORT);

    if (bookingsError) {
      console.error("Error fetching bookings:", bookingsError);
      return handleApiError(
        new Error(`Failed to fetch bookings: ${bookingsError.message}`),
        "BOOKINGS_FETCH_ERROR",
        500
      );
    }

    // Get staff information separately to avoid deep nesting issues
    const staffIds = new Set<string>();
    bookings?.forEach((booking: any) => {
      booking.booking_services?.forEach((service: any) => {
        if (service.staff_id) {
          staffIds.add(service.staff_id);
        }
      });
    });

    const staffMap = new Map<string, string>();
    if (staffIds.size > 0) {
      const { data: staffMembers, error: staffError } = await supabaseAdmin
        .from("provider_staff")
        .select("id, user_id, users(full_name)")
        .in("id", Array.from(staffIds));

      if (staffError) {
        console.warn("Error fetching staff information:", staffError);
        // Continue without staff names - will default to "Unassigned"
      } else {
        staffMembers?.forEach((staff: any) => {
          const staffName = staff.users?.full_name || "Unassigned";
          staffMap.set(staff.id, staffName);
        });
      }
    }

    // Get provider revenue from finance_transactions (actual earnings)
    const { totalRevenue, revenueByBooking, revenueByDate } = await getProviderRevenue(
      supabaseAdmin,
      providerId,
      fromDate,
      toDate,
      locationId || undefined
    );

    const totalBookings = bookings?.length || 0;
    const averageBookingValue = totalBookings > 0 ? totalRevenue / totalBookings : 0;

    // Get previous period for comparison
    const prevRevenue = await getPreviousPeriodRevenue(
      supabaseAdmin,
      providerId,
      fromDate,
      toDate,
      locationId || undefined
    );

    const periodDays = Math.ceil(
      (toDate.getTime() - fromDate.getTime()) / (1000 * 60 * 60 * 24)
    );
    const prevFromDate = subDays(fromDate, periodDays);
    const prevToDate = fromDate;

    const { data: prevBookings } = await supabaseAdmin
      .from("bookings")
      .select("id")
      .eq("provider_id", providerId)
      .gte("scheduled_at", prevFromDate.toISOString())
      .lte("scheduled_at", prevToDate.toISOString());

    const prevBookingsCount = prevBookings?.length || 0;

    const revenueGrowth =
      prevRevenue > 0 ? ((totalRevenue - prevRevenue) / prevRevenue) * 100 : 0;
    const bookingsGrowth =
      prevBookingsCount > 0
        ? ((totalBookings - prevBookingsCount) / prevBookingsCount) * 100
        : 0;

    // Revenue by day (from finance_transactions)
    const revenueByDay = Array.from(revenueByDate.entries())
      .map(([date, revenue]) => {
        // Count bookings for this date
        const bookingsForDate = bookings?.filter(
          (b) => new Date(b.scheduled_at).toISOString().split("T")[0] === date
        ).length || 0;
        return { date, revenue, bookings: bookingsForDate };
      })
      .sort((a, b) => a.date.localeCompare(b.date));

    // Revenue by service (use booking revenue from finance_transactions)
    const revenueByServiceMap = new Map<
      string,
      { revenue: number; bookings: number }
    >();
    // Safely process bookings - use finance_transactions revenue per booking
    (bookings || []).forEach((booking) => {
      const bookingRevenue = revenueByBooking.get(booking.id) || 0;
      if (!booking.booking_services || !Array.isArray(booking.booking_services)) {
        return;
      }
      // Distribute booking revenue proportionally across services
      const totalServicePrice = booking.booking_services.reduce(
        (sum: number, s: any) => sum + Number(s.price || 0),
        0
      );
      booking.booking_services.forEach((service: any) => {
        const serviceName = service.offerings?.title || "Unknown Service";
        const serviceProportion =
          totalServicePrice > 0
            ? Number(service.price || 0) / totalServicePrice
            : 1 / booking.booking_services.length;
        const serviceRevenue = bookingRevenue * serviceProportion;
        const existing = revenueByServiceMap.get(serviceName) || {
          revenue: 0,
          bookings: 0,
        };
        revenueByServiceMap.set(serviceName, {
          revenue: existing.revenue + serviceRevenue,
          bookings: existing.bookings + 1,
        });
      });
    });

    const revenueByService = Array.from(revenueByServiceMap.entries())
      .map(([serviceName, data]) => ({ serviceName, ...data }))
      .sort((a, b) => b.revenue - a.revenue);

    // Revenue by staff (use booking revenue from finance_transactions)
    const revenueByStaffMap = new Map<
      string,
      { revenue: number; bookings: number }
    >();
    // Safely process bookings for staff revenue
    (bookings || []).forEach((booking) => {
      const bookingRevenue = revenueByBooking.get(booking.id) || 0;
      if (!booking.booking_services || !Array.isArray(booking.booking_services)) {
        return;
      }
      // Distribute booking revenue proportionally across services/staff
      const totalServicePrice = booking.booking_services.reduce(
        (sum: number, s: any) => sum + Number(s.price || 0),
        0
      );
      booking.booking_services.forEach((service: any) => {
        const staffName = service.staff_id 
          ? (staffMap.get(service.staff_id) || "Unassigned")
          : "Unassigned";
        const serviceProportion =
          totalServicePrice > 0
            ? Number(service.price || 0) / totalServicePrice
            : 1 / booking.booking_services.length;
        const staffRevenue = bookingRevenue * serviceProportion;
        const existing = revenueByStaffMap.get(staffName) || {
          revenue: 0,
          bookings: 0,
        };
        revenueByStaffMap.set(staffName, {
          revenue: existing.revenue + staffRevenue,
          bookings: existing.bookings + 1,
        });
      });
    });

    const revenueByStaff = Array.from(revenueByStaffMap.entries())
      .map(([staffName, data]) => ({ staffName, ...data }))
      .sort((a, b) => b.revenue - a.revenue);

    return successResponse({
      totalRevenue,
      totalBookings,
      averageBookingValue,
      revenueGrowth,
      bookingsGrowth,
      revenueByDay,
      revenueByService,
      revenueByStaff,
    });
  } catch (error) {
    console.error("Error in sales summary report:", error);
    return handleApiError(error, "Failed to generate sales summary report");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";

/**
 * POST /api/provider/reports/schedule
 * 
 * Schedule a report to be generated and sent automatically
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return errorResponse("Provider not found", "NOT_FOUND", 404);
    }

    const { report_type, frequency, day_of_week, day_of_month, time, recipients, format } = body;

    if (!report_type || !frequency || !recipients || !format) {
      return errorResponse("Missing required fields: report_type, frequency, recipients, format", "VALIDATION_ERROR", 400);
    }

    const scheduleData: any = {
      provider_id: providerId,
      report_type,
      frequency, // daily, weekly, monthly
      day_of_week: day_of_week || null,
      day_of_month: day_of_month || null,
      time: time || "09:00",
      recipients: Array.isArray(recipients) ? recipients : [recipients],
      format, // csv, pdf
      is_active: true,
      created_by: user.id,
    };

    // Check if schedule already exists for this report type
    const { data: existing } = await supabase
      .from("report_schedules")
      .select("id")
      .eq("provider_id", providerId)
      .eq("report_type", report_type)
      .eq("is_active", true)
      .maybeSingle();

    if (existing) {
      // Update existing schedule
      const { data: schedule, error } = await supabase
        .from("report_schedules")
        .update(scheduleData)
        .eq("id", existing.id)
        .select()
        .single();

      if (error) {
        throw error;
      }

      return successResponse(schedule);
    } else {
      // Create new schedule
      const { data: schedule, error } = await supabase
        .from("report_schedules")
        .insert(scheduleData)
        .select()
        .single();

      if (error) {
        throw error;
      }

      return successResponse(schedule, 201);
    }
  } catch (error: any) {
    console.error("Error scheduling report:", error);
    return handleApiError(error, "Failed to schedule report");
  }
}

/**
 * GET /api/provider/reports/schedule
 * 
 * Get all scheduled reports for the provider
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);

    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return errorResponse("Provider not found", "NOT_FOUND", 404);
    }

    const { data: schedules, error } = await supabase
      .from("report_schedules")
      .select("*")
      .eq("provider_id", providerId)
      .order("created_at", { ascending: false });

    if (error) {
      throw error;
    }

    return successResponse(schedules || []);
  } catch (error: any) {
    console.error("Error fetching scheduled reports:", error);
    return handleApiError(error, "Failed to fetch scheduled reports");
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays } from "date-fns";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      { auth: { autoRefreshToken: false, persistSession: false } },
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) return notFoundResponse("Provider not found");
    const sp = request.nextUrl.searchParams;
    const fromDate = sp.get("from") ? new Date(sp.get("from")!) : subDays(new Date(), 30);
    const toDate = sp.get("to") ? new Date(sp.get("to")!) : new Date();

    const { data: bookingServices } = await supabaseAdmin
      .from("booking_services")
      .select("price, duration_minutes, offerings:offering_id(title), bookings!inner(provider_id, status, scheduled_at)")
      .eq("bookings.provider_id", providerId)
      .gte("bookings.scheduled_at", fromDate.toISOString())
      .lte("bookings.scheduled_at", new Date(toDate.getTime() + 86400000).toISOString())
      .not("bookings.status", "in", "(cancelled,no_show)");

    const serviceMap = new Map<string, { bookings: number; revenue: number; totalDuration: number }>();

    (bookingServices || []).forEach((bs: any) => {
      const name = bs.offerings?.title || "Unknown Service";
      const existing = serviceMap.get(name) || { bookings: 0, revenue: 0, totalDuration: 0 };
      existing.bookings += 1;
      existing.revenue += Number(bs.price || 0);
      existing.totalDuration += Number(bs.duration_minutes || 0);
      serviceMap.set(name, existing);
    });

    const entries = Array.from(serviceMap.entries());
    const totalRevenue = entries.reduce((s, [, d]) => s + d.revenue, 0);
    const totalBookings = entries.reduce((s, [, d]) => s + d.bookings, 0);

    return successResponse({
      most_popular: entries
        .map(([service, d]) => ({ service, bookings: d.bookings }))
        .sort((a, b) => b.bookings - a.bookings),
      revenue_by_service: entries
        .map(([service, d]) => ({ service, revenue: d.revenue }))
        .sort((a, b) => b.revenue - a.revenue),
      avg_duration: entries
        .map(([service, d]) => ({ service, minutes: d.bookings > 0 ? Math.round(d.totalDuration / d.bookings) : 0 })),
      total_service_revenue: totalRevenue,
      avg_service_price: totalBookings > 0 ? totalRevenue / totalBookings : 0,
    });
  } catch (error) {
    console.error("Error in services report:", error);
    return handleApiError(error, "Failed to generate services report");
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays } from "date-fns";
import { calculateStaffCommission } from "@/lib/payroll/commission-calculator";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    const { data: providerData, error: providerError } = await supabaseAdmin
      .from('providers')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();

    if (providerError || !providerData?.id) {
      return handleApiError(
        new Error('Provider profile not found'),
        'NOT_FOUND',
        404
      );
    }
    const searchParams = request.nextUrl.searchParams;
    const fromDate = searchParams.get("from")
      ? new Date(searchParams.get("from")!)
      : subDays(new Date(), 30);
    const toDate = searchParams.get("to")
      ? new Date(searchParams.get("to")!)
      : new Date();
    const staffIdFilter = searchParams.get("staff_id");

    // Get staff members
    let staffQuery = supabaseAdmin
      .from("provider_staff")
      .select(
        `
        id,
        user_id,
        service_commission_rate,
        product_commission_rate,
        commission_rate,
        commission_enabled,
        users (
          full_name
        )
      `
      )
      .eq("provider_id", providerId)
      .eq("is_active", true);

    if (staffIdFilter) {
      staffQuery = staffQuery.eq("id", staffIdFilter);
    }

    const { data: staffMembers, error: staffError } = await staffQuery;

    if (staffError) {
      return handleApiError(
        new Error("Failed to fetch staff"),
        "STAFF_FETCH_ERROR",
        500
      );
    }

    const commissionData = await Promise.all(
      (staffMembers || []).map(async (staff) => {
        const commission = await calculateStaffCommission(
          supabaseAdmin,
          providerId,
          staff.id,
          fromDate,
          toDate
        );

        const serviceRate = staff.service_commission_rate ?? staff.commission_rate ?? 0;
        const productRate = staff.product_commission_rate ?? staff.commission_rate ?? 0;
        const displayRate = serviceRate || productRate || 0;

        return {
          staffId: staff.id,
          staffName: (staff.users as any)?.full_name || "Unknown",
          commissionRate: displayRate,
          totalBookings: commission.totalBookings,
          totalRevenue: commission.totalRevenue,
          totalCommission: commission.totalCommission,
          averageCommission:
            commission.totalBookings > 0
              ? commission.totalCommission / commission.totalBookings
              : 0,
        };
      })
    );

    const sorted = commissionData.sort((a, b) => b.totalCommission - a.totalCommission);

    const totalCommission = sorted.reduce((sum, s) => sum + s.totalCommission, 0);
    const totalRevenue = sorted.reduce((sum, s) => sum + s.totalRevenue, 0);
    const averageCommissionRate = sorted.length > 0
      ? sorted.reduce((sum, s) => sum + s.commissionRate, 0) / sorted.length
      : 0;

    return successResponse({
      totalCommission,
      totalRevenue,
      averageCommissionRate,
      staffCommissions: sorted,
    });
  } catch (error) {
    return handleApiError(error, "COMMISSION_REPORT_ERROR", 500);
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays } from "date-fns";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    const { data: providerData, error: providerError } = await supabaseAdmin
      .from('providers')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();

    if (providerError || !providerData?.id) {
      return handleApiError(
        new Error('Provider profile not found'),
        'NOT_FOUND',
        404
      );
    }
    const searchParams = request.nextUrl.searchParams;
    const fromDate = searchParams.get("from")
      ? new Date(searchParams.get("from")!)
      : subDays(new Date(), 30);
    const toDate = searchParams.get("to")
      ? new Date(searchParams.get("to")!)
      : new Date();
    const staffId = searchParams.get("staff_id");

    // Get staff members
    let staffQuery = supabaseAdmin
      .from("provider_staff")
      .select(
        `
        id,
        user_id,
        users (
          full_name
        )
      `
      )
      .eq("provider_id", providerId);

    if (staffId) {
      staffQuery = staffQuery.eq("id", staffId);
    }

    const { data: staffMembers, error: staffError } = await staffQuery;

    if (staffError) {
      return handleApiError(
        new Error("Failed to fetch staff"),
        "STAFF_FETCH_ERROR",
        500
      );
    }

    // Get bookings with actual start/end times
    const bookingsQuery = supabaseAdmin
      .from("bookings")
      .select(
        `
        id,
        scheduled_at,
        status,
        booking_services (
          id,
          staff_id,
          actual_start_at,
          actual_end_at,
          offerings:offering_id (
            duration_minutes
          )
        )
      `
      )
      .eq("provider_id", providerId)
      .gte("scheduled_at", fromDate.toISOString())
      .lte("scheduled_at", toDate.toISOString());

    const { data: bookings, error: bookingsError } = await bookingsQuery;

    if (bookingsError) {
      return handleApiError(
        new Error("Failed to fetch bookings"),
        "BOOKINGS_FETCH_ERROR",
        500
      );
    }

    // Calculate hours for each staff member
    const hoursData = (staffMembers || []).map((staff) => {
      const staffBookings = bookings?.filter((booking) =>
        booking.booking_services?.some((bs: any) => bs.staff_id === staff.id)
      ) || [];

      let totalHours = 0;
      let scheduledHours = 0;
      let completedBookings = 0;
      let onTimeBookings = 0;

      staffBookings.forEach((booking: any) => {
        booking.booking_services?.forEach((bs: any) => {
          if (bs.staff_id === staff.id) {
            const duration = bs.offerings?.duration_minutes || 0;
            scheduledHours += duration / 60; // Convert minutes to hours

            if (bs.actual_start_at && bs.actual_end_at) {
              const start = new Date(bs.actual_start_at);
              const end = new Date(bs.actual_end_at);
              const hours = (end.getTime() - start.getTime()) / (1000 * 60 * 60);
              totalHours += hours;
              completedBookings += 1;

              // Check if on time (within 15 minutes of scheduled)
              const scheduled = new Date(booking.scheduled_at);
              const diff = Math.abs(start.getTime() - scheduled.getTime()) / (1000 * 60);
              if (diff <= 15) {
                onTimeBookings += 1;
              }
            }
          }
        });
      });

      const averageHoursPerDay = totalHours > 0 && staffBookings.length > 0
        ? totalHours / (Math.ceil((toDate.getTime() - fromDate.getTime()) / (1000 * 60 * 60 * 24)) || 1)
        : 0;

      return {
        staffId: staff.id,
        staffName: (staff.users as any)?.full_name || "Unknown",
        totalHours,
        scheduledHours,
        completedBookings,
        onTimeBookings,
        averageHoursPerDay,
        attendanceRate: staffBookings.length > 0
          ? (completedBookings / staffBookings.length) * 100
          : 0,
        onTimeRate: completedBookings > 0
          ? (onTimeBookings / completedBookings) * 100
          : 0,
      };
    }).sort((a, b) => b.totalHours - a.totalHours);

    // Summary
    const totalHours = hoursData.reduce((sum, s) => sum + s.totalHours, 0);
    const totalScheduledHours = hoursData.reduce((sum, s) => sum + s.scheduledHours, 0);
    const averageHoursPerStaff = hoursData.length > 0 ? totalHours / hoursData.length : 0;

    return successResponse({
      totalHours,
      totalScheduledHours,
      averageHoursPerStaff,
      staffHours: hoursData,
    });
  } catch (error) {
    return handleApiError(error, "STAFF_HOURS_ERROR", 500);
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { canAccessReportType } from "@/lib/subscriptions/report-gating";
import { createClient } from "@supabase/supabase-js";
import { subDays } from "date-fns";
import { getProviderRevenue } from "@/lib/reports/revenue-helpers";
import { calculateStaffCommission } from "@/lib/payroll/commission-calculator";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);    // Check subscription allows advanced reports (staff reports are advanced)
    const accessCheck = await canAccessReportType(user.id, "staff");
    if (!accessCheck.allowed) {
      return accessCheck.error!;
    }

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    const { data: providerData, error: providerError } = await supabaseAdmin
      .from('providers')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle();

    if (providerError || !providerData?.id) {
      return handleApiError(
        new Error('Provider profile not found'),
        'NOT_FOUND',
        404
      );
    }
    const searchParams = request.nextUrl.searchParams;
    const fromDate = searchParams.get("from")
      ? new Date(searchParams.get("from")!)
      : subDays(new Date(), 30);
    const toDate = searchParams.get("to")
      ? new Date(searchParams.get("to")!)
      : new Date();
    const staffId = searchParams.get("staffId");

    // Get all staff members for this provider
    let staffQuery = supabaseAdmin
      .from('provider_staff')
      .select(`
        id,
        user_id,
        users (
          full_name
        )
      `)
      .eq('provider_id', providerId)
      .eq('is_active', true);

    if (staffId) {
      staffQuery = staffQuery.eq('id', staffId);
    }

    const { data: staffMembers, error: staffError } = await staffQuery;

    if (staffError) {
      return handleApiError(
        new Error('Failed to fetch staff members'),
        'STAFF_FETCH_ERROR',
        500
      );
    }

    // Get provider revenue from finance_transactions
    const { revenueByBooking } = await getProviderRevenue(
      supabaseAdmin,
      providerId,
      fromDate,
      toDate
    );

    // Get bookings for date range
    const bookingsQuery = supabaseAdmin
      .from('bookings')
      .select(`
        id,
        status,
        scheduled_at,
        completed_at,
        booking_services (
          id,
          price,
          staff_id,
          actual_start_at,
          actual_end_at
        )
      `)
      .eq('provider_id', providerId)
      .gte('scheduled_at', fromDate.toISOString())
      .lte('scheduled_at', toDate.toISOString());

    const { data: bookings, error: bookingsError } = await bookingsQuery;

    if (bookingsError) {
      return handleApiError(
        new Error('Failed to fetch bookings'),
        'BOOKINGS_FETCH_ERROR',
        500
      );
    }

    // Get reviews for staff members
    // Note: reviews table has staff_rating as JSONB, not staff_id directly
    const { data: reviews } = await supabaseAdmin
      .from('reviews')
      .select('staff_rating, rating, booking_id')
      .eq('provider_id', providerId)
      .gte('created_at', fromDate.toISOString())
      .lte('created_at', toDate.toISOString());

    // Calculate performance metrics for each staff member
    const staffPerformance = await Promise.all((staffMembers || []).map(async (staff: any) => {
      const staffBookings = bookings?.filter((booking: any) =>
        booking.booking_services?.some((service: any) => service.staff_id === staff.id)
      ) || [];

      // Filter reviews by staff_rating JSONB field
      // staff_rating format: {staff_id: "...", rating: 5} or null
      const staffReviews = (reviews || []).filter((r: any) => {
        if (!r.staff_rating || typeof r.staff_rating !== 'object') return false;
        return r.staff_rating.staff_id === staff.id;
      }) || [];

      const totalBookings = staffBookings.length;
      const completedBookings = staffBookings.filter((b: any) => b.status === 'completed').length;
      const cancelledBookings = staffBookings.filter((b: any) => b.status === 'cancelled').length;
      const noShows = staffBookings.filter((b: any) => b.status === 'no_show').length;

      // Calculate revenue from finance_transactions, distributed proportionally by service price
      let totalRevenue = 0;
      staffBookings.forEach((booking: any) => {
        const bookingRevenue = revenueByBooking.get(booking.id) || 0;
        if (!booking.booking_services || !Array.isArray(booking.booking_services)) {
          return;
        }
        // Find services assigned to this staff member
        const staffServices = booking.booking_services.filter(
          (service: any) => service.staff_id === staff.id
        );
        if (staffServices.length === 0) return;

        // Calculate total price of all services in booking
        const totalServicePrice = booking.booking_services.reduce(
          (sum: number, s: any) => sum + Number(s.price || 0),
          0
        );
        // Calculate staff's portion of revenue
        const staffServicePrice = staffServices.reduce(
          (sum: number, s: any) => sum + Number(s.price || 0),
          0
        );
        const staffProportion = totalServicePrice > 0 ? staffServicePrice / totalServicePrice : 0;
        totalRevenue += bookingRevenue * staffProportion;
      });

      const averageBookingValue = totalBookings > 0 ? totalRevenue / totalBookings : 0;

      // Calculate total hours worked
      let totalHours = 0;
      staffBookings.forEach((booking: any) => {
        if (!booking.booking_services || !Array.isArray(booking.booking_services)) {
          return;
        }
        booking.booking_services.forEach((service: any) => {
          if (service.actual_start_at && service.actual_end_at) {
            const start = new Date(service.actual_start_at);
            const end = new Date(service.actual_end_at);
            const hours = (end.getTime() - start.getTime()) / (1000 * 60 * 60);
            totalHours += hours;
          }
        });
      });

      // Get rating from staff_rating JSONB field or fallback to main rating
      const averageRating =
        staffReviews.length > 0
          ? staffReviews.reduce((sum: number, r: any) => {
              const staffRating = r.staff_rating?.rating || r.rating || 0;
              return sum + Number(staffRating);
            }, 0) / staffReviews.length
          : 0;

      // Calculate commission using staff-specific rates
      const commissionResult = await calculateStaffCommission(
        supabaseAdmin,
        providerId,
        staff.id,
        fromDate,
        toDate
      );
      const commissionEarned = commissionResult.totalCommission;

      return {
        staffId: staff.id,
        staffName: staff.users?.full_name || 'Unknown',
        totalBookings,
        completedBookings,
        cancelledBookings,
        noShows,
        totalRevenue,
        averageBookingValue,
        totalHours,
        averageRating,
        totalReviews: staffReviews.length,
        commissionEarned,
      };
    }));

    // Calculate summary
    const summary = {
      totalStaff: staffPerformance.length,
      totalBookings: staffPerformance.reduce((sum, s) => sum + s.totalBookings, 0),
      totalRevenue: staffPerformance.reduce((sum, s) => sum + s.totalRevenue, 0),
      averageRating:
        staffPerformance.length > 0
          ? staffPerformance.reduce((sum, s) => sum + s.averageRating, 0) /
            staffPerformance.length
          : 0,
    };

    return successResponse({
      staffMembers: staffPerformance.sort((a, b) => b.totalRevenue - a.totalRevenue),
      summary,
    });
  } catch (error) {
    console.error("Error in staff performance report:", error);
    return handleApiError(error, "Failed to generate staff performance report");
  }
}

