      staffMap.set(s.id, { name, bookings: 0, revenue: 0, completed: 0 });
    });

    (bookingServices || []).forEach((bs: any) => {
      if (!bs.staff_id) return;
      const existing = staffMap.get(bs.staff_id) || { name: "Unassigned", bookings: 0, revenue: 0, completed: 0 };
      existing.bookings += 1;
      existing.revenue += Number(bs.price || 0);
      if ((bs.bookings as any)?.status === "completed") existing.completed += 1;
      staffMap.set(bs.staff_id, existing);
    });

    const staff = Array.from(staffMap.values())
      .map((s) => ({
        name: s.name,
        bookings: s.bookings,
        revenue: s.revenue,
        rating: 0,
        hours_worked: 0,
        commission: 0,
        completion_rate: s.bookings > 0 ? (s.completed / s.bookings) * 100 : 0,
      }))
      .sort((a, b) => b.revenue - a.revenue);

    return successResponse({
      staff,
      total_hours: 0,
      total_commission: 0,
    });
  } catch (error) {
    console.error("Error in staff report:", error);
    return handleApiError(error, "Failed to generate staff report");
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(
      ["provider_owner", "provider_staff", "superadmin"],
      request,
    );    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      { auth: { autoRefreshToken: false, persistSession: false } },
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    const { data: providerData, error: providerError } = await supabaseAdmin
      .from("providers")
      .select("id")
      .eq("user_id", user.id)
      .maybeSingle();

    if (providerError || !providerData?.id) {
      return handleApiError(
        new Error("Provider profile not found."),
        "NOT_FOUND",
        404,
      );
    }
    const searchParams = request.nextUrl.searchParams;
    const limit = Math.min(parseInt(searchParams.get("limit") ?? "5", 10), 20);

    const { data: bookingServices, error: bsError } = await supabaseAdmin
      .from("booking_services")
      .select(
        `
        id,
        price,
        offering_id,
        bookings!inner (id, provider_id, status),
        offerings:offering_id (title)
      `,
      )
      .eq("bookings.provider_id", providerId)
      .not("bookings.status", "in", "(cancelled,no_show)");

    if (bsError) {
      console.error("Error fetching booking services:", bsError);
      return handleApiError(
        new Error(`Failed to fetch services: ${bsError.message}`),
        "FETCH_ERROR",
        500,
      );
    }

    const serviceMap = new Map<
      string,
      { service_name: string; booking_count: number; total_revenue: number }
    >();

    (bookingServices || []).forEach((bs: any) => {
      const name = bs.offerings?.title || "Unknown Service";
      const existing = serviceMap.get(name) || {
        service_name: name,
        booking_count: 0,
        total_revenue: 0,
      };
      existing.booking_count += 1;
      existing.total_revenue += Number(bs.price || 0);
      serviceMap.set(name, existing);
    });

    const result = Array.from(serviceMap.values())
      .sort((a, b) => b.booking_count - a.booking_count)
      .slice(0, limit);

    return successResponse(result);
  } catch (error) {
    console.error("Error in top-services report:", error);
    return handleApiError(error, "Failed to generate top services report");
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays, format, eachDayOfInterval } from "date-fns";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(
      ["provider_owner", "provider_staff", "superadmin"],
      request,
    );    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      { auth: { autoRefreshToken: false, persistSession: false } },
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    const { data: providerData, error: providerError } = await supabaseAdmin
      .from("providers")
      .select("id")
      .eq("user_id", user.id)
      .maybeSingle();

    if (providerError || !providerData?.id) {
      return handleApiError(
        new Error("Provider profile not found."),
        "NOT_FOUND",
        404,
      );
    }
    const searchParams = request.nextUrl.searchParams;
    const startDate = searchParams.get("start_date")
      ? new Date(searchParams.get("start_date")!)
      : subDays(new Date(), 6);
    const endDate = searchParams.get("end_date")
      ? new Date(searchParams.get("end_date")!)
      : new Date();

    const { data: rows } = await supabaseAdmin
      .from("finance_transactions")
      .select("net, amount, created_at")
      .eq("provider_id", providerId)
      .eq("transaction_type", "provider_earnings")
      .gte("created_at", startDate.toISOString())
      .lte("created_at", new Date(endDate.getTime() + 86400000).toISOString());

    const revenueMap = new Map<string, number>();
    const days = eachDayOfInterval({ start: startDate, end: endDate });
    days.forEach((d) => revenueMap.set(format(d, "yyyy-MM-dd"), 0));

    (rows || []).forEach((r: any) => {
      const day = format(new Date(r.created_at), "yyyy-MM-dd");
      const val = Number(r.net ?? r.amount ?? 0);
      revenueMap.set(day, (revenueMap.get(day) ?? 0) + val);
    });

    const result = days.map((d) => ({
      day: format(d, "yyyy-MM-dd"),
      revenue: revenueMap.get(format(d, "yyyy-MM-dd")) ?? 0,
    }));

    return successResponse(result);
  } catch (error) {
    console.error("Error in weekly-revenue report:", error);
    return handleApiError(error, "Failed to generate weekly revenue report");
  }
}

