      `)
      .single();

    if (insertError || !newResource) {
      throw insertError || new Error("Failed to create resource");
    }

    // Transform response to match UI expectations
    const group = Array.isArray((newResource as any).resource_groups)
      ? (newResource as any).resource_groups[0]
      : (newResource as any).resource_groups;

    const transformedResource = {
      id: newResource.id,
      name: newResource.name,
      description: newResource.description || null,
      capacity: newResource.capacity || null,
      is_active: newResource.is_active ?? true,
      group_name: group?.name || null,
      group_color: group?.color || null,
      group_id: newResource.group_id || null,
      provider_id: newResource.provider_id,
      created_at: newResource.created_at,
      updated_at: newResource.updated_at,
    };

    return successResponse(transformedResource);
  } catch (error) {
    return handleApiError(error, "Failed to create resource");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  getProviderIdForUser,
  successResponse,
  notFoundResponse,
  errorResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";
import { z } from "zod";

const updateSchema = z.object({
  action: z.enum(["approve", "reject", "mark_received", "process_refund"]),
  provider_notes: z.string().max(500).optional(),
  return_method: z.enum(["drop_off", "courier", "not_required"]).optional(),
  resolution: z.enum(["full_refund", "partial_refund", "replacement", "store_credit", "denied"]).optional(),
  refund_processed_amount: z.number().min(0).optional(),
});

const STATUS_TRANSITIONS: Record<string, Record<string, string>> = {
  pending: { approve: "approved", reject: "rejected" },
  approved: { mark_received: "item_received" },
  item_received: { process_refund: "refunded" },
};

/**
 * GET /api/provider/returns/[id]
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const { data, error } = await (supabase.from("product_return_requests") as any)
      .select(
        `*,
        order:product_orders(order_number, total_amount, fulfillment_type, items:product_order_items(*)),
        customer:users!product_return_requests_customer_id_fkey(id, full_name, email, phone, avatar_url)`,
      )
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (error || !data) return notFoundResponse("Return request not found");
    return successResponse({ return_request: data });
  } catch (err) {
    return handleApiError(err, "Failed to fetch return request");
  }
}

/**
 * PATCH /api/provider/returns/[id] ΓÇö provider actions on a return
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const body = await request.json();
    const parsed = updateSchema.parse(body);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const { data: req } = await (supabase.from("product_return_requests") as any)
      .select("id, status, refund_amount, order_id, quantity, order_item_id, customer_id")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (!req) return notFoundResponse("Return request not found");

    const transitions = STATUS_TRANSITIONS[req.status];
    if (!transitions || !transitions[parsed.action]) {
      return errorResponse(
        `Cannot perform "${parsed.action}" on a return with status "${req.status}"`,
        "INVALID_TRANSITION",
        400,
      );
    }

    const update: Record<string, any> = {
      status: transitions[parsed.action],
    };

    if (parsed.provider_notes) update.provider_notes = parsed.provider_notes;

    if (parsed.action === "approve") {
      update.approved_at = new Date().toISOString();
      update.return_method = parsed.return_method ?? "drop_off";
      update.resolution = parsed.resolution ?? "full_refund";
    }

    if (parsed.action === "reject") {
      update.rejected_at = new Date().toISOString();
      update.resolution = "denied";
    }

    if (parsed.action === "mark_received") {
      update.item_received_at = new Date().toISOString();
    }

    if (parsed.action === "process_refund") {
      update.refunded_at = new Date().toISOString();
      update.refund_processed_amount =
        parsed.refund_processed_amount ?? Number(req.refund_amount);
      update.refund_method = "original_payment";
      update.resolved_by = user.id;

      // Restore stock (variant or product-level)
      if (req.order_item_id) {
        const { data: orderItem } = await (supabase.from("product_order_items") as any)
          .select("product_id, product_variant_id, quantity")
          .eq("id", req.order_item_id)
          .single();
        if (orderItem) {
          const qty = req.quantity ?? orderItem.quantity ?? 1;
          if (orderItem.product_variant_id) {
            try {
              await (supabase.rpc as any)("increment_product_variant_stock", {
                p_variant_id: orderItem.product_variant_id,
                p_quantity: qty,
              });
            } catch {
              const { data: v } = await (supabase.from("product_variants") as any)
                .select("quantity")
                .eq("id", orderItem.product_variant_id)
                .single();
              if (v) {
                await (supabase.from("product_variants") as any)
                  .update({ quantity: (v.quantity ?? 0) + qty })
                  .eq("id", orderItem.product_variant_id);
              }
            }
          } else {
            const { data: prod } = await (supabase.from("products") as any)
              .select("quantity")
              .eq("id", orderItem.product_id)
              .single();
            if (prod) {
              await (supabase.from("products") as any)
                .update({ quantity: (prod.quantity ?? 0) + qty })
                .eq("id", orderItem.product_id);
            }
          }
        }
      }
    }

    const { data, error } = await (supabase.from("product_return_requests") as any)
      .update(update)
      .eq("id", id)
      .select("*, order:product_orders(order_number)")
      .single();

    if (error) throw error;

    // Notify customer of return status change
    const notifMap: Record<string, { type: string; title: string; message: string }> = {
      approve: {
        type: "product_return_approved",
        title: "Return Approved",
        message: `Your return request for order ${data?.order?.order_number} has been approved.`,
      },
      reject: {
        type: "product_return_rejected",
        title: "Return Update",
        message: `Your return request for order ${data?.order?.order_number} was not approved.${parsed.provider_notes ? ` Reason: ${parsed.provider_notes}` : ""} You can escalate if needed.`,
      },
      process_refund: {
        type: "product_return_refunded",
        title: "Refund Processed",
        message: `Your refund of R${Number(update.refund_processed_amount ?? req.refund_amount).toFixed(2)} for order ${data?.order?.order_number} has been processed.`,
      },
    };

    const notif = notifMap[parsed.action];
    if (notif && req.customer_id) {
      await supabase.from("notifications").insert({
        user_id: (req as any).customer_id ?? data.customer_id,
        type: notif.type,
        title: notif.title,
        message: notif.message,
        metadata: { return_request_id: id },
        link: "/product-orders",
      }).then(() => {}, () => {});
    }

    return successResponse({ return_request: data });
  } catch (err) {
    return handleApiError(err, "Failed to update return request");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  getProviderIdForUser,
  successResponse,
  notFoundResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";

/**
 * GET /api/provider/returns ΓÇö list return requests for provider
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const { searchParams } = new URL(request.url);
    const status = searchParams.get("status");
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "20");
    const offset = (page - 1) * limit;

    let query = (supabase.from("product_return_requests") as any)
      .select(
        `*,
        order:product_orders(order_number, total_amount),
        customer:users!product_return_requests_customer_id_fkey(id, full_name, email, avatar_url)`,
        { count: "exact" },
      )
      .eq("provider_id", providerId)
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (status) query = query.eq("status", status);

    const { data, error, count } = await query;
    if (error) throw error;

    return successResponse({
      returns: data ?? [],
      pagination: { page, limit, total: count ?? 0, totalPages: Math.ceil((count ?? 0) / limit) },
    });
  } catch (err) {
    return handleApiError(err, "Failed to fetch return requests");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { z } from "zod";

const moderateSchema = z.object({
  action: z.enum(["flag", "unflag", "hide", "unhide"]),
  reason: z.string().optional(),
});

/**
 * POST /api/provider/reviews/[id]/moderate
 * 
 * Provider flags/hides a review (for moderation)
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const { id: reviewId } = await params;
    const body = await request.json();

    // Validate input
    const validated = moderateSchema.parse(body);

    // Get provider ID
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Get review
    const { data: review, error: reviewError } = await supabase
      .from("reviews")
      .select("id, provider_id, is_flagged, is_visible")
      .eq("id", reviewId)
      .single();

    if (reviewError || !review) {
      return notFoundResponse("Review not found");
    }

    // Verify review belongs to provider (or user is superadmin)
    if (review.provider_id !== providerId && user.role !== 'superadmin') {
      return errorResponse(
        "You can only moderate reviews for your own business",
        "UNAUTHORIZED",
        403
      );
    }

    // Update review based on action
    const updateData: any = {};
    if (validated.action === 'flag') {
      updateData.is_flagged = true;
      updateData.flagged_reason = validated.reason || 'Flagged by provider';
      updateData.flagged_by = user.id;
    } else if (validated.action === 'unflag') {
      updateData.is_flagged = false;
      updateData.flagged_reason = null;
      updateData.flagged_by = null;
    } else if (validated.action === 'hide') {
      updateData.is_visible = false;
    } else if (validated.action === 'unhide') {
      updateData.is_visible = true;
    }

    const { data: updatedReview, error: updateError } = await supabase
      .from("reviews")
      .update(updateData)
      .eq("id", reviewId)
      .select()
      .single();

    if (updateError) {
      throw updateError;
    }

    // Notify admin if review is flagged
    if (validated.action === 'flag') {
      try {
        const { data: admins } = await supabase
          .from("users")
          .select("id")
          .eq("role", "superadmin")
          .limit(5);

        if (admins) {
          for (const admin of admins) {
            await supabase.from("notifications").insert({
              user_id: admin.id,
              type: "review_flagged",
              title: "Review Flagged for Moderation",
              message: `A review has been flagged by a provider and requires moderation.`,
              metadata: {
                review_id: reviewId,
                provider_id: providerId,
                reason: validated.reason,
              },
              link: `/admin/reviews/${reviewId}`,
            });
          }
        }
      } catch (notifError) {
        console.warn("Failed to notify admins of flagged review:", notifError);
      }
    }

    return successResponse({
      review: updatedReview,
      message: `Review ${validated.action}ed successfully`,
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return errorResponse(
        error.issues.map((e) => e.message).join(", "),
        "VALIDATION_ERROR",
        400
      );
    }
    return handleApiError(error, "Failed to moderate review");
  }
}

