    if (!review || reviewData.bookings?.provider_id !== providerData.id) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Review not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    if (!review.provider_response) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "No response exists to edit. Use POST to create a response.",
            code: "NO_RESPONSE",
          },
        },
        { status: 400 }
      );
    }

    // Get customer ID from review
    const { data: reviewWithCustomer } = await supabase
      .from("reviews")
      .select(`
        id,
        customer_id,
        booking_id,
        bookings:bookings!reviews_booking_id_fkey(
          customer_id,
          provider_id
        )
      `)
      .eq("id", id)
      .single();

    // Update review response
    const { data: updatedReview, error: updateError } = await (supabase
      .from("reviews") as any)
      .update({
        provider_response: response,
        updated_at: new Date().toISOString(),
      })
      .eq("id", id)
      .select()
      .single();

    if (updateError || !updatedReview) {
      console.error("Error updating review response:", updateError);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to update review response",
            code: "UPDATE_ERROR",
          },
        },
        { status: 500 }
      );
    }

    // Notify customer that provider updated their response
    const customerId = reviewWithCustomer?.customer_id || (reviewWithCustomer as any)?.bookings?.customer_id;
    if (customerId) {
      try {
        await supabase.from("notifications").insert({
          user_id: customerId,
          type: "review_response_updated",
          title: "Provider Updated Their Response",
          message: `The provider has updated their response to your review.`,
          metadata: {
            review_id: id,
            booking_id: reviewWithCustomer?.booking_id || (reviewWithCustomer as any)?.bookings?.id,
            provider_id: providerData.id,
          },
        });
      } catch (notifError) {
        // Log but don't fail the request
        console.warn("Failed to create notification for review response update:", notifError);
      }
    }

    return NextResponse.json({
      data: updatedReview,
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in PATCH /api/provider/reviews/[id]/response:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to update review response",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  handleApiError,
  getProviderIdForUser,
  notFoundResponse,
  errorResponse,
} from "@/lib/supabase/api-helpers";
import { z } from "zod";

const updateSchema = z.object({
  name: z.string().min(1).optional(),
  description: z.string().optional(),
  permissions: z.record(z.string(), z.boolean()).optional(),
  is_active: z.boolean().optional(),
});

/**
 * PATCH /api/provider/roles/[id]
 * Update a role
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner"], request);
    const supabase = await getSupabaseServer(request);
    const { id } = await params;
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const body = await request.json();
    const validationResult = updateSchema.safeParse(body);

    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    // Verify role belongs to provider
    const { data: existing } = await supabase
      .from("provider_roles")
      .select("id")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (!existing) {
      return notFoundResponse("Role not found");
    }

    const updateData: any = {};
    if (validationResult.data.name !== undefined) {
      updateData.name = validationResult.data.name;
    }
    if (validationResult.data.description !== undefined) {
      updateData.description = validationResult.data.description || null;
    }
    if (validationResult.data.permissions !== undefined) {
      updateData.permissions = validationResult.data.permissions;
    }
    if (validationResult.data.is_active !== undefined) {
      updateData.is_active = validationResult.data.is_active;
    }

    const { data, error } = await supabase
      .from("provider_roles")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (error) {
      throw error;
    }

    return successResponse({
      ...data,
      permissions:
        data.permissions && typeof data.permissions === "string"
          ? JSON.parse(data.permissions)
          : data.permissions || {},
    });
  } catch (error) {
    return handleApiError(error, "Failed to update role");
  }
}

/**
 * DELETE /api/provider/roles/[id]
 * Delete a role
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner"], request);
    const supabase = await getSupabaseServer(request);
    const { id } = await params;
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Verify role belongs to provider
    const { data: existing } = await supabase
      .from("provider_roles")
      .select("id")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (!existing) {
      return notFoundResponse("Role not found");
    }

    const { error } = await supabase.from("provider_roles").delete().eq("id", id);

    if (error) {
      throw error;
    }

    return successResponse({ success: true });
  } catch (error) {
    return handleApiError(error, "Failed to delete role");
  }
}

