import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, handleApiError, successResponse, badRequestResponse } from "@/lib/supabase/api-helpers";

/**
 * POST /api/provider/routes/optimize
 * Optimize route for a specific date
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff'], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return badRequestResponse("Provider not found");
    }

    const body = await request.json();
    const { date, staff_id } = body;

    if (!date) {
      return badRequestResponse("date is required (YYYY-MM-DD format)");
    }

    // Get or create route
    const { data: routeIdRaw, error: routeError } = await supabase
      .rpc('get_or_create_route', {
        p_provider_id: providerId,
        p_route_date: date,
        p_staff_id: staff_id || null,
      });

    if (routeError) {
      throw routeError;
    }

    // PostgREST can return scalar UUID as string or single-element array
    const routeId = Array.isArray(routeIdRaw) ? routeIdRaw[0] : routeIdRaw;
    if (!routeId) {
      throw new Error("Failed to get or create route");
    }

    // Get all at-home bookings for the day (bookings table uses address_latitude, address_longitude per 005_bookings)
    const { data: bookings, error: bookingsError } = await supabase
      .from("bookings")
      .select(`
        id,
        scheduled_at,
        duration,
        location_type,
        address_line1,
        address_city,
        address_state,
        address_postal_code,
        address_latitude,
        address_longitude,
        customer:users!bookings_customer_id_fkey (
          id,
          full_name
        )
      `)
      .eq("provider_id", providerId)
      .eq("location_type", "at_home")
      .gte("scheduled_at", `${date}T00:00:00Z`)
      .lt("scheduled_at", `${date}T23:59:59Z`)
      .not("status", "in", '(cancelled,no_show)')
      .order("scheduled_at", { ascending: true });

    if (bookingsError) {
      throw bookingsError;
    }

    if (!bookings || bookings.length === 0) {
      return successResponse({
        route_id: routeId,
        bookings_count: 0,
        message: "No at-home bookings found for this date",
      });
    }

    // Get provider's starting location (provider_locations uses latitude/longitude per 003_providers)
    const { data: providerLocation } = await supabase
      .from("provider_locations")
      .select("latitude, longitude, address_line1, city, state")
      .eq("provider_id", providerId)
      .eq("is_primary", true)
      .single();

    const startLat = (providerLocation as any)?.latitude ?? (providerLocation as any)?.address_lat ?? 0;
    const startLng = (providerLocation as any)?.longitude ?? (providerLocation as any)?.address_lng ?? 0;
    const startingLocation = providerLocation || { latitude: 0, longitude: 0, address_line1: "Provider Location" };

    // Set starting_address on the route so calculate_route_savings can use it (avoids NULL and 500s)
    await supabase
      .from("travel_routes")
      .update({
        starting_address: { lat: startLat, lng: startLng, address: (startingLocation as any)?.address_line1 ?? "Provider Location" },
        updated_at: new Date().toISOString(),
      })
      .eq("id", routeId);

    // Create route segments
    let previousLocation = {
      lat: (providerLocation as any)?.latitude ?? (providerLocation as any)?.address_lat ?? startLat,
      lng: (providerLocation as any)?.longitude ?? (providerLocation as any)?.address_lng ?? startLng,
      address: ("address_line1" in (startingLocation as any) ? (startingLocation as any).address_line1 : null) || "Provider Location",
    };
    let previousBookingId = null;
    let segmentOrder = 1;
    let totalDistance = 0;
    let totalDuration = 0;

    const segments = [];

    for (const booking of bookings) {
      const bLat = (booking as any).address_latitude ?? (booking as any).address_lat;
      const bLng = (booking as any).address_longitude ?? (booking as any).address_lng;
      if (bLat == null || bLng == null) {
        continue; // Skip bookings without coordinates
      }

      const currentLocation = {
        lat: bLat,
        lng: bLng,
        address: (booking as any).address_line1 || "Customer Location",
      };

      // Calculate distance (RPC may return scalar or single-element array)
      const { data: distanceData } = await supabase
        .rpc('calculate_distance_km', {
          lat1: previousLocation.lat,
          lng1: previousLocation.lng,
          lat2: currentLocation.lat,
          lng2: currentLocation.lng,
        });
      const distance = Number(Array.isArray(distanceData) ? distanceData[0] : distanceData) || 0;
      totalDistance += distance;

      // Estimate duration (assume average speed of 40 km/h)
      const duration = Math.ceil((distance / 40) * 60); // minutes
      totalDuration += duration;

      // Calculate travel fee (RPC may return scalar or single-element array)
      const { data: travelFeeData } = await supabase
        .rpc('calculate_chained_travel_fee', {
          distance_km: distance,
          is_first_in_route: segmentOrder === 1,
        });
      const travelFee = Number(Array.isArray(travelFeeData) ? travelFeeData[0] : travelFeeData) || 0;

      // Create segment
      const { data: segment, error: segmentError } = await supabase
        .from("route_segments")
        .insert({
          route_id: routeId,
          from_booking_id: previousBookingId,
          to_booking_id: booking.id,
          segment_order: segmentOrder,
          distance_km: distance,
          duration_minutes: duration,
          travel_fee_calculated: travelFee,
          travel_fee_charged: travelFee,
          from_location: previousLocation,
          to_location: currentLocation,
        })
        .select()
        .single();

      if (segmentError) {
        console.error("Error creating segment:", segmentError);
      } else {
        segments.push({
          from: previousBookingId ? `Booking ${previousBookingId}` : "Starting Location",
          to: booking.id,
          distance_km: distance,
          duration_minutes: duration,
          travel_fee: travelFee,
          customer: Array.isArray(booking.customer) ? booking.customer?.[0]?.full_name : (booking.customer as { full_name?: string })?.full_name,
          scheduled_at: booking.scheduled_at,
        });

        // Update booking with route information
        await supabase
          .from("bookings")
          .update({
            route_segment_id: segment.id,
            travel_distance_km: distance,
            travel_duration_minutes: duration,
            previous_booking_id: previousBookingId,
            travel_fee_method: 'route_chained',
            travel_fee: travelFee,
          })
          .eq("id", booking.id);

        // Update previous booking's next_booking_id
        if (previousBookingId) {
          await supabase
            .from("bookings")
            .update({ next_booking_id: booking.id })
            .eq("id", previousBookingId);
        }
      }

      previousLocation = currentLocation;
      previousBookingId = booking.id;
      segmentOrder++;
    }

    // Update route with totals
    await supabase
      .from("travel_routes")
      .update({
        total_distance_km: totalDistance,
        total_duration_minutes: totalDuration,
        optimization_status: 'optimized',
        optimized_at: new Date().toISOString(),
      })
      .eq("id", routeId);

    // Calculate savings (best-effort; avoid 500 if RPC or config is missing)
    let savings = {
      standard_total: 0,
      chained_total: 0,
      savings: 0,
      savings_percentage: 0,
    };
    const { data: savingsData, error: savingsError } = await supabase
      .rpc('calculate_route_savings', { p_route_id: routeId });
    if (!savingsError && savingsData?.[0]) {
      const row = savingsData[0] as any;
      savings = {
        standard_total: Number(row.standard_total ?? 0),
        chained_total: Number(row.chained_total ?? 0),
        savings: Number(row.savings ?? 0),
        savings_percentage: Number(row.savings_percentage ?? 0),
      };
    }

    return successResponse({
      route_id: routeId,
      bookings_count: bookings.length,
      segments_created: segments.length,
      total_distance_km: totalDistance,
      total_duration_minutes: totalDuration,
      segments,
      savings: {
        standard_total: savings.standard_total,
        chained_total: savings.chained_total,
        amount_saved: savings.savings,
        percentage_saved: savings.savings_percentage,
      },
    });

  } catch (error) {
    return handleApiError(error, "Failed to optimize route");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, handleApiError, successResponse, badRequestResponse } from "@/lib/supabase/api-helpers";

/**
 * GET /api/provider/routes?date=YYYY-MM-DD
 * Get route for a specific date with all segments
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff'], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return badRequestResponse("Provider not found");
    }

    const url = new URL(request.url);
    const date = url.searchParams.get("date");
    const staff_id = url.searchParams.get("staff_id");

    if (!date) {
      return badRequestResponse("date parameter is required (YYYY-MM-DD format)");
    }

    // Get route for the date (when no staff_id, match routes where staff_id IS NULL)
    let query = supabase
      .from("travel_routes")
      .select("*")
      .eq("provider_id", providerId)
      .eq("route_date", date);
    if (staff_id != null && staff_id !== "") {
      query = query.eq("staff_id", staff_id);
    } else {
      query = query.is("staff_id", null);
    }
    const { data: route, error: routeError } = await query.single();

    if (routeError && routeError.code !== 'PGRST116') {
      throw routeError;
    }

    if (!route) {
      return successResponse({
        route: null,
        segments: [],
        message: "No route found for this date",
      });
    }

    // Get all segments for this route
    const { data: segments, error: segmentsError } = await supabase
      .from("route_segments")
      .select(`
        *,
        to_booking:bookings!route_segments_to_booking_id_fkey (
          id,
          ref_number,
          scheduled_at,
          duration,
          status,
          customer:users!bookings_customer_id_fkey (
            id,
            full_name,
            email,
            phone
          )
        )
      `)
      .eq("route_id", route.id)
      .order("segment_order", { ascending: true });

    if (segmentsError) {
      throw segmentsError;
    }

    // Calculate savings (best-effort; RPC can fail if starting_address is null or config missing)
    let savings = {
      standard_total: 0,
      chained_total: 0,
      savings: 0,
      savings_percentage: 0,
    };
    try {
      const { data: savingsData } = await supabase
        .rpc('calculate_route_savings', { p_route_id: route.id });
      if (savingsData?.[0]) {
        const row = savingsData[0] as Record<string, any>;
        savings = {
          standard_total: Number(row.standard_total ?? 0),
          chained_total: Number(row.chained_total ?? 0),
          savings: Number(row.savings ?? 0),
          savings_percentage: Number(row.savings_percentage ?? 0),
        };
      }
    } catch {
      // use defaults
    }

    return successResponse({
      route: {
        id: route.id,
        date: route.route_date,
        total_distance_km: route.total_distance_km,
        total_duration_minutes: route.total_duration_minutes,
        optimization_status: route.optimization_status,
        optimized_at: route.optimized_at,
        starting_location: route.starting_address,
        ending_location: route.ending_address,
      },
      segments: segments?.map(s => ({
        id: s.id,
        order: s.segment_order,
        distance_km: s.distance_km,
        duration_minutes: s.duration_minutes,
        travel_fee_calculated: s.travel_fee_calculated,
        travel_fee_charged: s.travel_fee_charged,
        from_location: s.from_location,
        to_location: s.to_location,
        booking: s.to_booking ? {
          id: s.to_booking.id,
          ref_number: s.to_booking.ref_number,
          scheduled_at: s.to_booking.scheduled_at,
          duration: s.to_booking.duration,
          status: s.to_booking.status,
          customer: s.to_booking.customer,
        } : null,
      })) || [],
      savings,
    });

  } catch (error) {
    return handleApiError(error, "Failed to fetch route");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getProviderIdForUser, notFoundResponse, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { createClient } from "@supabase/supabase-js";

/**
 * GET /api/provider/sales
 * 
 * List sales for provider
 */
export async function GET(request: NextRequest) {
  try {
    // Check permission to view sales
    const permissionCheck = await requirePermission('view_sales', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) return notFoundResponse("Provider not found");

    const { searchParams } = new URL(request.url);

    // Parse query parameters
    const search = searchParams.get('search');
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '20');
    const offset = (page - 1) * limit;
    const dateFrom = searchParams.get('date_from');
    const dateTo = searchParams.get('date_to');
    const locationId = searchParams.get('location_id');

    // Build query (simplified to avoid nested join issues)
    let salesQuery = supabaseAdmin
      .from('sales')
      .select(`
        id,
        sale_number,
        ref_number,
        sale_date,
        subtotal,
        tax_amount,
        discount_amount,
        total_amount,
        payment_method,
        payment_status,
        notes,
        created_at,
        customer_id,
        staff_id,
        location_id
      `, { count: 'exact' })
      .eq('provider_id', providerId)
      .order('sale_date', { ascending: false });

    // Apply location filter
    if (locationId) {
      salesQuery = salesQuery.eq('location_id', locationId);
    }

    // Apply date filters
    if (dateFrom) {
      salesQuery = salesQuery.gte('sale_date', `${dateFrom}T00:00:00`);
    }
    if (dateTo) {
      salesQuery = salesQuery.lte('sale_date', `${dateTo}T23:59:59`);
    }

    // Apply pagination
    salesQuery = salesQuery.range(offset, offset + limit - 1);

    const { data: sales, error: salesError, count } = await salesQuery;

    if (salesError) {
      console.error("Error fetching sales:", salesError);
      throw salesError;
    }

    // Get related data separately to avoid nested join issues
    const saleIds = (sales || []).map(s => s.id);
    const customerIds = new Set<string>();
    const staffIds = new Set<string>();
    const locationIds = new Set<string>();

    (sales || []).forEach((sale: any) => {
      if (sale.customer_id) customerIds.add(sale.customer_id);
      if (sale.staff_id) staffIds.add(sale.staff_id);
      if (sale.location_id) locationIds.add(sale.location_id);
    });

    // Fetch customers
    const customerMap = new Map<string, { full_name: string; email: string }>();
    if (customerIds.size > 0) {
      const { data: customers, error: customerError } = await supabaseAdmin
        .from('users')
        .select('id, full_name, email')
        .in('id', Array.from(customerIds));

      if (customerError) {
        console.warn("Error fetching customers:", customerError);
      } else {
        customers?.forEach((customer: any) => {
          customerMap.set(customer.id, {
            full_name: customer.full_name || "Unknown",
            email: customer.email || "",
          });
        });
      }
    }

    // Fetch staff
    const staffMap = new Map<string, string>();
    if (staffIds.size > 0) {
      const { data: staffMembers, error: staffError } = await supabaseAdmin
        .from('provider_staff')
        .select('id, name')
        .in('id', Array.from(staffIds));

      if (staffError) {
        console.warn("Error fetching staff:", staffError);
      } else {
        staffMembers?.forEach((staff: any) => {
          staffMap.set(staff.id, staff.name || "Unknown");
        });
      }
    }

    // Fetch locations
    const locationMap = new Map<string, string>();
    if (locationIds.size > 0) {
      const { data: locations, error: locationError } = await supabaseAdmin
        .from('provider_locations')
        .select('id, name')
        .in('id', Array.from(locationIds));

      if (locationError) {
        console.warn("Error fetching locations:", locationError);
      } else {
        locations?.forEach((location: any) => {
          locationMap.set(location.id, location.name || "Unknown");
        });
      }
    }

    // Get sale items for each sale
    const itemsMap = new Map();

    if (saleIds.length > 0) {
      const { data: items } = await supabaseAdmin
        .from('sale_items')
        .select('*')
        .in('sale_id', saleIds);

      // Group items by sale_id
      (items || []).forEach((item: any) => {
        if (!itemsMap.has(item.sale_id)) {
          itemsMap.set(item.sale_id, []);
        }
        itemsMap.get(item.sale_id).push({
          id: item.id,
          type: item.item_type,
          name: item.item_name,
          quantity: item.quantity,
          unit_price: Number(item.unit_price),
          total: Number(item.total_price),
        });
      });
    }

    // Transform to Sale format
    const transformedSales = (sales || []).map((sale: any) => {
      const customerInfo = sale.customer_id ? customerMap.get(sale.customer_id) : null;
      const staffName = sale.staff_id ? staffMap.get(sale.staff_id) : null;

      return {
        id: sale.id,
        ref_number: sale.ref_number || sale.sale_number,
        client_name: customerInfo?.full_name || null,
        date: sale.sale_date,
        items: itemsMap.get(sale.id) || [],
        subtotal: Number(sale.subtotal || 0),
        tax: Number(sale.tax_amount || 0),
        total: Number(sale.total_amount || 0),
        payment_method: sale.payment_method || 'cash',
        team_member_id: sale.staff_id || null,
        team_member_name: staffName || null,
      };
    });

    // Apply search filter if provided
    let filteredSales = transformedSales;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredSales = transformedSales.filter(s => 
        s.ref_number.toLowerCase().includes(searchLower) ||
        s.client_name?.toLowerCase().includes(searchLower)
      );
    }

    const totalPages = count ? Math.ceil(count / limit) : 1;

    return successResponse({
      data: filteredSales,
      total: count || filteredSales.length,
      page,
      limit,
      total_pages: totalPages,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch sales");
  }
}

/**
 * POST /api/provider/sales
 * 
 * Create a new sale
 */
export async function POST(request: NextRequest) {
  try {
    // Check permission to create sales
    const permissionCheck = await requirePermission('create_sales', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;

    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return handleApiError(
        new Error('Provider profile not found'),
        'NOT_FOUND',
        404
      );
    }

    const body = await request.json();
    const {
      location_id,
      customer_id,
      staff_id,
      sale_date,
      items,
      subtotal,
      tax_rate,
      tax_amount,
      discount_amount,
      total_amount,
      payment_method,
      payment_status,
      payment_reference,
      service_location_type,
      house_call_address,
      notes,
    } = body;

    // Validate required fields
    if (!items || !Array.isArray(items) || items.length === 0) {
      return handleApiError(
        new Error('At least one item is required'),
        'VALIDATION_ERROR',
        400
      );
    }

    if (total_amount === undefined || total_amount === null) {
      return handleApiError(
        new Error('Total amount is required'),
        'VALIDATION_ERROR',
        400
      );
    }

    // Calculate totals if not provided
    const calculatedSubtotal = subtotal || items.reduce((sum: number, item: any) => 
      sum + (item.unit_price || 0) * (item.quantity || 1), 0
    );
    const calculatedTax = tax_amount || (calculatedSubtotal * (tax_rate || 0));
    const calculatedTotal = total_amount || (calculatedSubtotal + calculatedTax - (discount_amount || 0));

    // Create sale
    const { data: sale, error: saleError } = await supabase
      .from('sales')
      .insert({
        provider_id: providerId,
        location_id: location_id || null,
        customer_id: customer_id || null,
        staff_id: staff_id || null,
        sale_date: sale_date || new Date().toISOString(),
        subtotal: calculatedSubtotal,
        tax_rate: tax_rate || 0,
        tax_amount: calculatedTax,
        discount_amount: discount_amount || 0,
        total_amount: calculatedTotal,
        payment_method: payment_method || 'cash',
        payment_status: payment_status || 'completed',
        notes: payment_reference 
          ? `${notes || ''}\nPayment Reference: ${payment_reference}`.trim() 
          : service_location_type === 'house-call' && house_call_address
          ? `${notes || ''}\nHouse Call Address: ${house_call_address.address_line1}, ${house_call_address.city}${house_call_address.postal_code ? `, ${house_call_address.postal_code}` : ''}`.trim()
          : (notes || null),
        created_by: user.id,
      })
      .select()
      .single();

    if (saleError) {
      throw saleError;
    }

    // Create sale items
    const saleItems = items.map((item: any) => ({
      sale_id: sale.id,
      item_type: item.type || 'product',
      item_id: item.item_id || null,
      item_name: item.name,
      quantity: item.quantity || 1,
      unit_price: item.unit_price || 0,
      total_price: (item.unit_price || 0) * (item.quantity || 1),
    }));

    const { error: itemsError } = await supabase
      .from('sale_items')
      .insert(saleItems);

    if (itemsError) {
      // Rollback sale creation
      await supabase.from('sales').delete().eq('id', sale.id);
      throw itemsError;
    }

    // Fetch complete sale with items (simplified query)
    const { data: fetchedSaleItems } = await supabase
      .from('sale_items')
      .select('*')
      .eq('sale_id', sale.id);

    // Get customer and staff info separately
    let clientName = null;
    let staffName = null;

    if (sale.customer_id) {
      const { data: customer } = await supabase
        .from('users')
        .select('full_name')
        .eq('id', sale.customer_id)
        .single();
      clientName = customer?.full_name || null;
    }

    if (sale.staff_id) {
      const { data: staff } = await supabase
        .from('provider_staff')
        .select('name')
        .eq('id', sale.staff_id)
        .single();
      staffName = staff?.name || null;
    }

    return successResponse({
      id: sale.id,
      ref_number: sale.ref_number || sale.sale_number,
      client_name: clientName,
      date: sale.sale_date,
      items: (fetchedSaleItems || []).map((item: any) => ({
        id: item.id,
        type: item.item_type,
        name: item.item_name,
        quantity: item.quantity,
        unit_price: Number(item.unit_price),
        total: Number(item.total_price),
      })),
      subtotal: Number(sale.subtotal),
      tax: Number(sale.tax_amount),
      total: Number(sale.total_amount),
      payment_method: sale.payment_method,
      team_member_id: sale.staff_id || null,
      team_member_name: staffName,
    });
  } catch (error) {
    return handleApiError(error, "Failed to create sale");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import {
  getProviderIdForUser,
  successResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";
import { requireRoleInApi } from "@/lib/supabase/api-helpers";

export interface ProviderSearchSuggestion {
  type: "client" | "appointment" | "service";
  id: string;
  title: string;
  subtitle?: string;
  url: string;
}

export interface ProviderSearchResult {
  suggestions: ProviderSearchSuggestion[];
}

/**
 * GET /api/provider/search
 *
 * Provider-scoped global search across clients, appointments, and services.
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi([
      "provider_owner",
      "provider_staff",
      "superadmin",
    ], request);
    const supabase = await getSupabaseServer(request);
    const supabaseAdmin = await getSupabaseAdmin();

    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return successResponse({ suggestions: [] });
    }

    const { searchParams } = new URL(request.url);
    const q = searchParams.get("q")?.trim() || "";
    const limit = Math.min(
      parseInt(searchParams.get("limit") || "10", 10),
      20
    );

    if (q.length < 2) {
      return successResponse({ suggestions: [] });
    }

    const searchTerm = `%${q.toLowerCase()}%`;
    const suggestions: ProviderSearchSuggestion[] = [];

    // 1. Search clients (provider_clients + users)
    const { data: providerClients } = await supabaseAdmin
      .from("provider_clients")
      .select("id, customer_id")
      .eq("provider_id", providerId)
      .limit(100);

    if (providerClients && providerClients.length > 0) {
      const customerIds = providerClients.map((c) => c.customer_id);
      const clientMap = new Map(
        providerClients.map((c) => [c.customer_id, c.id])
      );

      const { data: customers } = await supabaseAdmin
        .from("users")
        .select("id, full_name, email, phone")
        .in("id", customerIds)
        .or(
          `full_name.ilike.${searchTerm},email.ilike.${searchTerm},phone.ilike.${searchTerm}`
        )
        .limit(limit);

      if (customers) {
        for (const c of customers) {
          const providerClientId = clientMap.get(c.id);
          suggestions.push({
            type: "client",
            id: providerClientId || c.id,
            title: (c as any).full_name || (c as any).email || "Unknown",
            subtitle: (c as any).email || (c as any).phone,
            url: `/provider/clients?customerId=${(c as any).id}`,
          });
        }
      }
    }

    // 2. Search bookings (by booking_number or customer name)
    const { data: bookings } = await supabaseAdmin
      .from("bookings")
      .select(
        `
        id,
        booking_number,
        scheduled_start_at,
        status,
        customer_id,
        customers:users!bookings_customer_id_fkey(id, full_name, email)
      `
      )
      .eq("provider_id", providerId)
      .or(`booking_number.ilike.${searchTerm}`)
      .order("scheduled_start_at", { ascending: false })
      .limit(limit);

    if (bookings) {
      for (const b of bookings) {
        const customer = (b as any).customers;
        const customerName = customer?.full_name || customer?.email || "";
        const scheduledDate = (b as any).scheduled_start_at
          ? new Date((b as any).scheduled_start_at).toLocaleDateString(
              "en-ZA",
              {
                month: "short",
                day: "numeric",
                year: "numeric",
              }
            )
          : "";
        suggestions.push({
          type: "appointment",
          id: (b as any).id,
          title: (b as any).booking_number || `Booking`,
          subtitle: customerName
            ? `${customerName} ┬╖ ${scheduledDate}`
            : scheduledDate,
          url: `/provider/calendar?date=${
            (b as any).scheduled_start_at?.split("T")[0] || ""
          }&appointment=${(b as any).id}`,
        });
      }
    }

    // If we didn't find bookings by number, try by customer name
    if (bookings?.length === 0) {
      const { data: matchingCustomers } = await supabaseAdmin
        .from("users")
        .select("id")
        .or(
          `full_name.ilike.${searchTerm},email.ilike.${searchTerm},phone.ilike.${searchTerm}`
        )
        .limit(5);

      if (matchingCustomers && matchingCustomers.length > 0) {
        const customerIds = matchingCustomers.map((c) => (c as any).id);
        const { data: customerBookings } = await supabaseAdmin
          .from("bookings")
          .select(
            `
            id,
            booking_number,
            scheduled_start_at,
            customers:users!bookings_customer_id_fkey(id, full_name, email)
          `
          )
          .eq("provider_id", providerId)
          .in("customer_id", customerIds)
          .order("scheduled_start_at", { ascending: false })
          .limit(limit);

        if (customerBookings) {
          for (const b of customerBookings) {
            const customer = (b as any).customers;
            const scheduledDate = (b as any).scheduled_start_at
              ? new Date((b as any).scheduled_start_at).toLocaleDateString(
                  "en-ZA",
                  {
                    month: "short",
                    day: "numeric",
                    year: "numeric",
                  }
                )
              : "";
            suggestions.push({
              type: "appointment",
              id: (b as any).id,
              title: (b as any).booking_number || `Booking`,
              subtitle: customer
                ? `${customer.full_name || customer.email} ┬╖ ${scheduledDate}`
                : scheduledDate,
              url: `/provider/calendar?date=${
                (b as any).scheduled_start_at?.split("T")[0] || ""
              }&appointment=${(b as any).id}`,
            });
          }
        }
      }
    }

    // 3. Search services (offerings)
    const { data: services } = await supabaseAdmin
      .from("offerings")
      .select("id, title, description, price, duration_minutes")
      .eq("provider_id", providerId)
      .eq("is_active", true)
      .or(`title.ilike.${searchTerm},description.ilike.${searchTerm}`)
      .limit(limit);

    if (services) {
      for (const s of services) {
        const priceStr = (s as any).price
          ? `R${Number((s as any).price).toFixed(0)}`
          : "";
        const durationStr = (s as any).duration_minutes
          ? `${(s as any).duration_minutes} min`
          : "";
        const subtitle = [priceStr, durationStr].filter(Boolean).join(" ┬╖ ");
        suggestions.push({
          type: "service",
          id: (s as any).id,
          title: (s as any).title,
          subtitle: subtitle || undefined,
          url: `/provider/catalogue/services?service=${(s as any).id}`,
        });
      }
    }

    // Deduplicate by id+type and limit total
    const seen = new Set<string>();
    const unique = suggestions.filter((s) => {
      const key = `${s.type}:${s.id}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });

    return successResponse({
      suggestions: unique.slice(0, limit),
    });
  } catch (error) {
    return handleApiError(error, "Failed to search");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  handleApiError,
  getProviderIdForUser,
  badRequestResponse,
  notFoundResponse,
} from "@/lib/supabase/api-helpers";
import { z } from "zod";

const updateServiceZoneSchema = z.object({
  name: z.string().min(1).optional(),
  zone_type: z.enum(["postal_code", "city", "polygon", "radius"]).optional(),
  postal_codes: z.array(z.string()).optional(),
  cities: z.array(z.string()).optional(),
  polygon_coordinates: z.any().optional(),
  center_latitude: z.number().optional(),
  center_longitude: z.number().optional(),
  radius_km: z.number().positive().optional(),
  travel_fee: z.number().min(0).optional(),
  currency: z.string().length(3).optional(),
  travel_time_minutes: z.number().int().positive().optional(),
  description: z.string().optional().nullable(),
  is_active: z.boolean().optional(),
});

/**
 * GET /api/provider/service-zones/[id]
 * Get a specific service zone
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    const { id } = await params;

    if (!providerId) {
      return badRequestResponse("Provider not found");
    }

    const { data: zone, error } = await supabase
      .from("service_zones")
      .select("*")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (error || !zone) {
      return notFoundResponse("Service zone not found");
    }

    return successResponse(zone);
  } catch (error) {
    return handleApiError(error, "Failed to fetch service zone");
  }
}

/**
 * PATCH /api/provider/service-zones/[id]
 * Update a service zone
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    const { id } = await params;

    if (!providerId) {
      return badRequestResponse("Provider not found");
    }

    // Verify zone belongs to provider
    const { data: existingZone, error: fetchError } = await supabase
      .from("service_zones")
      .select("id, zone_type")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (fetchError || !existingZone) {
      return notFoundResponse("Service zone not found");
    }

    const body = await request.json();
    const validationResult = updateServiceZoneSchema.safeParse(body);

    if (!validationResult.success) {
      return badRequestResponse(
        validationResult.error.issues.map((i) => i.message).join(", ")
      );
    }

    const data = validationResult.data;
    const zoneType = data.zone_type || existingZone.zone_type;

    // Validate zone type specific fields if zone_type is being updated
    if (data.zone_type) {
      if (zoneType === "postal_code" && (!data.postal_codes || data.postal_codes.length === 0)) {
        return badRequestResponse("Postal codes are required for postal_code zones");
      }
      if (zoneType === "city" && (!data.cities || data.cities.length === 0)) {
        return badRequestResponse("Cities are required for city zones");
      }
      if (zoneType === "polygon" && !data.polygon_coordinates) {
        return badRequestResponse("Polygon coordinates are required for polygon zones");
      }
      if (zoneType === "radius") {
        if (!data.center_latitude || !data.center_longitude || !data.radius_km) {
          return badRequestResponse("Center coordinates and radius are required for radius zones");
        }
      }
    }

    const updateData: any = {};
    if (data.name !== undefined) updateData.name = data.name;
    if (data.zone_type !== undefined) updateData.zone_type = data.zone_type;
    if (data.postal_codes !== undefined) updateData.postal_codes = data.postal_codes;
    if (data.cities !== undefined) updateData.cities = data.cities;
    if (data.polygon_coordinates !== undefined) updateData.polygon_coordinates = data.polygon_coordinates;
    if (data.center_latitude !== undefined) updateData.center_latitude = data.center_latitude;
    if (data.center_longitude !== undefined) updateData.center_longitude = data.center_longitude;
    if (data.radius_km !== undefined) updateData.radius_km = data.radius_km;
    if (data.travel_fee !== undefined) updateData.travel_fee = data.travel_fee;
    if (data.currency !== undefined) updateData.currency = data.currency;
    if (data.travel_time_minutes !== undefined) updateData.travel_time_minutes = data.travel_time_minutes;
    if (data.description !== undefined) updateData.description = data.description;
    if (data.is_active !== undefined) updateData.is_active = data.is_active;

    const { data: zone, error } = await supabase
      .from("service_zones")
      .update(updateData)
      .eq("id", id)
      .eq("provider_id", providerId)
      .select()
      .single();

    if (error) {
      throw error;
    }

    return successResponse(zone);
  } catch (error) {
    return handleApiError(error, "Failed to update service zone");
  }
}

/**
 * DELETE /api/provider/service-zones/[id]
 * Delete a service zone
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    const { id } = await params;

    if (!providerId) {
      return badRequestResponse("Provider not found");
    }

    const { error } = await supabase
      .from("service_zones")
      .delete()
      .eq("id", id)
      .eq("provider_id", providerId);

    if (error) {
      throw error;
    }

    return successResponse({ success: true });
  } catch (error) {
    return handleApiError(error, "Failed to delete service zone");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  handleApiError,
  getProviderIdForUser,
  badRequestResponse,
} from "@/lib/supabase/api-helpers";

/**
 * GET /api/provider/service-zones/analytics
 * Get analytics for service zones
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return badRequestResponse("Provider not found");
    }

    const { searchParams } = new URL(request.url);
    const startDate = searchParams.get("start_date");
    const endDate = searchParams.get("end_date");

    // Get provider's zone selections (new two-tier system)
    const { data: zoneSelections, error: selectionsError } = await supabase
      .from("provider_zone_selections")
      .select(`
        id,
        platform_zone_id,
        is_active,
        platform_zone:platform_zones(
          id,
          name,
          zone_type,
          postal_codes,
          cities
        )
      `)
      .eq("provider_id", providerId);

    if (selectionsError) {
      throw selectionsError;
    }

    // Fallback: Also check old service_zones table (for migration period)
    const { data: oldZones, error: _oldZonesError } = await supabase
      .from("service_zones")
      .select("id, name, zone_type, is_active, postal_codes, cities")
      .eq("provider_id", providerId);

    // Combine both (prefer new system)
    const zones = (zoneSelections || []).map((selection: any) => ({
      id: selection.platform_zone?.id || selection.id,
      name: selection.platform_zone?.name || "Unknown Zone",
      zone_type: selection.platform_zone?.zone_type || "unknown",
      is_active: selection.is_active,
      postal_codes: selection.platform_zone?.postal_codes,
      cities: selection.platform_zone?.cities,
      selection_id: selection.id,
    })).concat(
      (oldZones || []).map((zone: any) => ({
        id: zone.id,
        name: zone.name,
        zone_type: zone.zone_type,
        is_active: zone.is_active,
        postal_codes: zone.postal_codes,
        cities: zone.cities,
        selection_id: null,
      }))
    );

    // Build date filter
    let bookingsQuery = supabase
      .from("bookings")
      .select("id, service_address, address_city, address_postal_code, total_amount, travel_fee, created_at, status")
      .eq("provider_id", providerId)
      .eq("location_type", "at_home");

    if (startDate) {
      bookingsQuery = bookingsQuery.gte("created_at", startDate);
    }
    if (endDate) {
      bookingsQuery = bookingsQuery.lte("created_at", endDate);
    }

    const { data: bookings, error: bookingsError } = await bookingsQuery;

    if (bookingsError) {
      throw bookingsError;
    }

    // Match bookings to zones
    const zoneStats = zones?.map((zone) => {
      const matchingBookings = bookings?.filter((booking) => {
        if (zone.zone_type === "postal_code" && zone.postal_codes) {
          return booking.address_postal_code && 
            zone.postal_codes.includes(booking.address_postal_code);
        } else if (zone.zone_type === "city" && zone.cities) {
          return booking.address_city && 
            zone.cities.some((city: string) => 
              city.toLowerCase().trim() === booking.address_city?.toLowerCase().trim()
            );
        }
        // For polygon and radius, we'd need coordinates - skip for now
        return false;
      }) || [];

      const totalBookings = matchingBookings.length;
      const completedBookings = matchingBookings.filter((b) => b.status === "completed").length;
      const totalRevenue = matchingBookings.reduce((sum, b) => sum + parseFloat(b.total_amount || "0"), 0);
      const totalTravelFees = matchingBookings.reduce((sum, b) => sum + parseFloat(b.travel_fee || "0"), 0);

      return {
        zone_id: zone.id,
        zone_name: zone.name,
        zone_type: zone.zone_type,
        is_active: zone.is_active,
        selection_id: zone.selection_id,
        total_bookings: totalBookings,
        completed_bookings: completedBookings,
        cancelled_bookings: matchingBookings.filter((b) => b.status === "cancelled").length,
        total_revenue: totalRevenue,
        total_travel_fees: totalTravelFees,
        average_booking_value: totalBookings > 0 ? totalRevenue / totalBookings : 0,
        completion_rate: totalBookings > 0 ? (completedBookings / totalBookings) * 100 : 0,
      };
    }) || [];

    // Overall stats
    const totalAtHomeBookings = bookings?.length || 0;
    const totalRevenue = bookings?.reduce((sum, b) => sum + parseFloat(b.total_amount || "0"), 0) || 0;
    const totalTravelFees = bookings?.reduce((sum, b) => sum + parseFloat(b.travel_fee || "0"), 0) || 0;

    return successResponse({
      zones: zoneStats,
      summary: {
        total_zones: zones?.length || 0,
        active_zones: zones?.filter((z) => z.is_active).length || 0,
        total_at_home_bookings: totalAtHomeBookings,
        total_revenue: totalRevenue,
        total_travel_fees: totalTravelFees,
        average_booking_value: totalAtHomeBookings > 0 ? totalRevenue / totalAtHomeBookings : 0,
      },
      period: {
        start_date: startDate || null,
        end_date: endDate || null,
      },
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch zone analytics");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, notFoundResponse, handleApiError, getProviderIdForUser, requireRoleInApi } from "@/lib/supabase/api-helpers";

type Params = { params: Promise<{ id: string; addonId: string }> };

/**
 * PATCH /api/provider/services/[id]/addons/[addonId]
 */
export async function PATCH(request: NextRequest, { params }: Params) {
  try {
    const { id: _serviceId, addonId } = await params;
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const { data: existing } = await supabase
      .from("offerings")
      .select("id, provider_id")
      .eq("id", addonId)
      .eq("provider_id", providerId)
      .eq("service_type", "addon")
      .single();

    if (!existing) return notFoundResponse("Add-on not found");

    const body = await request.json();
    const updateData: Record<string, any> = {};
    if (body.name !== undefined) updateData.title = body.name;
    if (body.price !== undefined) updateData.price = Number(body.price);
    if (body.duration_minutes !== undefined) updateData.duration_minutes = Number(body.duration_minutes);

    if (Object.keys(updateData).length === 0) {
      return NextResponse.json({ error: "No fields to update" }, { status: 400 });
    }

    const { data: addon, error } = await supabase
      .from("offerings")
      .update(updateData)
      .eq("id", addonId)
      .select()
      .single();

    if (error) throw error;

    return successResponse(addon);
  } catch (error) {
    return handleApiError(error, "Failed to update add-on");
  }
}

