      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const body = await request.json();
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const updates: Record<string, any> = {};

    if (body.currency !== undefined) {
      updates.currency = body.currency;
    }
    if (body.taxRatePercent !== undefined) {
      updates.tax_rate_percent = Number(body.taxRatePercent);
    }
    if (body.isVatRegistered !== undefined) {
      updates.is_vat_registered = body.isVatRegistered;
    }
    if (body.vatNumber !== undefined) {
      updates.vat_number = body.vatNumber || null;
    }
    if (body.requiresDeposit !== undefined) {
      updates.requires_deposit = body.requiresDeposit;
    }
    if (body.depositPercentage !== undefined) {
      updates.deposit_percentage = Number(body.depositPercentage);
    }
    if (body.noShowFeeEnabled !== undefined) {
      updates.no_show_fee_enabled = body.noShowFeeEnabled;
    }
    if (body.noShowFeeAmount !== undefined) {
      updates.no_show_fee_amount = Number(body.noShowFeeAmount);
    }
    if (body.acceptCash !== undefined) {
      updates.accept_cash = body.acceptCash;
    }
    if (body.acceptCard !== undefined) {
      updates.accept_card = body.acceptCard;
    }
    if (body.acceptOnline !== undefined) {
      updates.accept_online = body.acceptOnline;
    }
    if (body.taxInclusive !== undefined) {
      updates.tax_inclusive = body.taxInclusive;
    }
    if (body.tipsEnabled !== undefined) {
      updates.tips_enabled = body.tipsEnabled;
    }
    if (body.tipPresets !== undefined) {
      updates.tip_presets = body.tipPresets;
    }
    if (body.receiptAutoSend !== undefined) {
      updates.receipt_auto_send = body.receiptAutoSend;
    }
    if (body.tipsDistribution !== undefined) {
      updates.tips_distribution = body.tipsDistribution;
    }

    const { data: provider, error } = await supabase
      .from("providers")
      .update(updates)
      .eq("id", providerId)
      .select()
      .single();

    if (error) {
      throw error;
    }

    return successResponse(provider);
  } catch (error) {
    return handleApiError(error, "Failed to update payment settings");
  }
}

import { NextRequest } from "next/server";
import { z } from "zod";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { getPlatformSalesDefaults, getPlatformSalesConstraints, validateAgainstConstraints, mergeWithPlatformDefaults } from "@/lib/platform-sales-settings";

/**
 * GET/PATCH /api/provider/settings/sales/receipt
 * Stores settings on providers.*
 * Uses platform defaults if provider hasn't set custom values.
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    // Get platform defaults
    const platformDefaults = await getPlatformSalesDefaults();

    if (!providerId) {
      return successResponse({ 
        receipt_prefix: platformDefaults.receipt_prefix ?? "REC",
        receipt_next_number: platformDefaults.receipt_next_number ?? 1,
        receipt_header: platformDefaults.receipt_header ?? null,
        receipt_footer: platformDefaults.receipt_footer ?? null,
        isUsingPlatformDefault: true,
      });
    }

    const { data, error } = await supabase
      .from("providers")
      .select("receipt_prefix, receipt_next_number, receipt_header, receipt_footer")
      .eq("id", providerId)
      .single();

    if (error) throw error;

    const providerSettings = {
      receipt_prefix: (data as any)?.receipt_prefix,
      receipt_next_number: (data as any)?.receipt_next_number,
      receipt_header: (data as any)?.receipt_header,
      receipt_footer: (data as any)?.receipt_footer,
    };

    const isUsingPlatformDefault = 
      !providerSettings.receipt_prefix && 
      !providerSettings.receipt_next_number &&
      providerSettings.receipt_header === null &&
      providerSettings.receipt_footer === null;

    const merged = mergeWithPlatformDefaults(providerSettings, {
      receipt_prefix: platformDefaults.receipt_prefix ?? "REC",
      receipt_next_number: platformDefaults.receipt_next_number ?? 1,
      receipt_header: platformDefaults.receipt_header ?? null,
      receipt_footer: platformDefaults.receipt_footer ?? null,
    });

    return successResponse({
      receipt_prefix: merged.receipt_prefix || "REC",
      receipt_next_number: Number(merged.receipt_next_number || 1),
      receipt_header: merged.receipt_header ?? null,
      receipt_footer: merged.receipt_footer ?? null,
      isUsingPlatformDefault,
    });
  } catch (error) {
    return handleApiError(error, "Failed to load receipt settings");
  }
}

export async function PATCH(request: NextRequest) {
  try {
    // Check permission to edit settings
    const permissionCheck = await requirePermission('edit_settings', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) throw new Error("Provider profile not found");

    // Get constraints for validation
    const constraints = await getPlatformSalesConstraints();

    // Create dynamic schema based on constraints
    const patchSchema = z.object({
      receipt_prefix: z.string().min(1).max(constraints.max_receipt_prefix_length ?? 20).optional(),
      receipt_next_number: z.number().int().min(constraints.min_receipt_next_number ?? 1).optional(),
      receipt_header: z.string().max(constraints.max_receipt_header_length ?? 2000).nullable().optional(),
      receipt_footer: z.string().max(constraints.max_receipt_footer_length ?? 2000).nullable().optional(),
    });

    const body = patchSchema.parse(await request.json());

    // Validate each field against constraints
    if (body.receipt_prefix !== undefined) {
      const validation = validateAgainstConstraints("receipt_prefix", body.receipt_prefix, constraints);
      if (!validation.valid) {
        return errorResponse(validation.error || "Invalid receipt prefix", "VALIDATION_ERROR", 400);
      }
    }

    if (body.receipt_next_number !== undefined) {
      const validation = validateAgainstConstraints("receipt_next_number", body.receipt_next_number, constraints);
      if (!validation.valid) {
        return errorResponse(validation.error || "Invalid receipt next number", "VALIDATION_ERROR", 400);
      }
    }

    if (body.receipt_header !== undefined) {
      const validation = validateAgainstConstraints("receipt_header", body.receipt_header, constraints);
      if (!validation.valid) {
        return errorResponse(validation.error || "Invalid receipt header", "VALIDATION_ERROR", 400);
      }
    }

    if (body.receipt_footer !== undefined) {
      const validation = validateAgainstConstraints("receipt_footer", body.receipt_footer, constraints);
      if (!validation.valid) {
        return errorResponse(validation.error || "Invalid receipt footer", "VALIDATION_ERROR", 400);
      }
    }

    const update: any = { ...body, updated_at: new Date().toISOString() };

    const { data, error } = await (supabase.from("providers") as any)
      .update(update)
      .eq("id", providerId)
      .select("receipt_prefix, receipt_next_number, receipt_header, receipt_footer")
      .single();
    if (error) throw error;

    return successResponse({
      receipt_prefix: (data as any)?.receipt_prefix || "REC",
      receipt_next_number: Number((data as any)?.receipt_next_number || 1),
      receipt_header: (data as any)?.receipt_header ?? null,
      receipt_footer: (data as any)?.receipt_footer ?? null,
      isUsingPlatformDefault: false,
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return errorResponse("Invalid request data", "VALIDATION_ERROR", 400, error.issues);
    }
    return handleApiError(error, "Failed to update receipt settings");
  }
}

import { NextRequest } from "next/server";
import { z } from "zod";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { getPlatformSalesDefaults, getPlatformSalesConstraints, validateAgainstConstraints } from "@/lib/platform-sales-settings";

const patchSchema = z.object({
  tax_rate_percent: z.number().min(0).max(100).optional(),
  is_vat_registered: z.boolean().optional(),
  vat_number: z.string().optional().nullable(),
});

/**
 * GET/PATCH /api/provider/settings/sales/taxes
 * Provider tax configuration (stored on providers.tax_rate_percent).
 * Uses platform defaults if provider hasn't set a custom value.
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "superadmin"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    // Get platform defaults
    const platformDefaults = await getPlatformSalesDefaults();

    if (!providerId) {
      return successResponse({ 
        tax_rate_percent: platformDefaults.tax_rate_percent ?? 0,
        isUsingPlatformDefault: true,
      });
    }

    const { data, error } = await supabase
      .from("providers")
      .select("tax_rate_percent, is_vat_registered, vat_number")
      .eq("id", providerId)
      .single();

    if (error) throw error;

    const providerTaxRate = (data as any)?.tax_rate_percent;
    const isUsingPlatformDefault = providerTaxRate === null || providerTaxRate === undefined;
    const taxRate = isUsingPlatformDefault 
      ? (platformDefaults.tax_rate_percent ?? 0)
      : Number(providerTaxRate);

    const isVatRegistered = (data as any)?.is_vat_registered ?? false;
    const vatNumber = (data as any)?.vat_number ?? null;

    return successResponse({ 
      tax_rate_percent: taxRate,
      is_vat_registered: isVatRegistered,
      vat_number: vatNumber,
      isUsingPlatformDefault,
    });
  } catch (error) {
    return handleApiError(error, "Failed to load tax settings");
  }
}

export async function PATCH(request: NextRequest) {
  try {
    // Check permission to edit settings
    const permissionCheck = await requirePermission('edit_settings', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) throw new Error("Provider profile not found");

    const body = patchSchema.parse(await request.json());

    // Prepare update object
    const updateData: any = { updated_at: new Date().toISOString() };

    // Handle VAT registration status
    if (body.is_vat_registered !== undefined) {
      updateData.is_vat_registered = body.is_vat_registered;

      // If registering for VAT, set tax rate to 15% (South African standard VAT rate)
      if (body.is_vat_registered === true) {
        updateData.tax_rate_percent = 15;
        // Require VAT number if registering
        if (!body.vat_number || body.vat_number.trim() === '') {
          return errorResponse("VAT number is required when registering for VAT", "VALIDATION_ERROR", 400);
        }
        updateData.vat_number = body.vat_number.trim();
      } else {
        // If unregistering from VAT, set tax rate to 0%
        updateData.tax_rate_percent = 0;
        updateData.vat_number = null;
      }
    }

    // Handle VAT number update (if VAT registered)
    if (body.vat_number !== undefined && body.is_vat_registered !== false) {
      // Validate VAT number format (South African VAT numbers: 4XXXXXXXXX - 10 digits starting with 4)
      if (body.vat_number && body.vat_number.trim() !== '') {
        const vatRegex = /^4\d{9}$/;
        if (!vatRegex.test(body.vat_number.trim())) {
          return errorResponse("Invalid VAT number format. South African VAT numbers must be 10 digits starting with 4 (e.g., 4123456789)", "VALIDATION_ERROR", 400);
        }
        updateData.vat_number = body.vat_number.trim();
      }
    }

    // Handle manual tax rate override (only if not setting VAT registration)
    if (body.tax_rate_percent !== undefined && body.is_vat_registered === undefined) {
      // Validate against platform constraints
      const constraints = await getPlatformSalesConstraints();
      const validation = validateAgainstConstraints("tax_rate_percent", body.tax_rate_percent, constraints);

      if (!validation.valid) {
        return errorResponse(validation.error || "Invalid tax rate", "VALIDATION_ERROR", 400);
      }

      updateData.tax_rate_percent = body.tax_rate_percent;

      // Auto-set VAT registration based on tax rate (15% = VAT registered in SA)
      if (body.tax_rate_percent === 15) {
        updateData.is_vat_registered = true;
      } else if (body.tax_rate_percent === 0) {
        updateData.is_vat_registered = false;
        updateData.vat_number = null;
      }
    }

    const { data, error } = await (supabase.from("providers") as any)
      .update(updateData)
      .eq("id", providerId)
      .select("tax_rate_percent, is_vat_registered, vat_number")
      .single();
    if (error) throw error;

    return successResponse({ 
      tax_rate_percent: Number((data as any)?.tax_rate_percent || 0),
      is_vat_registered: (data as any)?.is_vat_registered ?? false,
      vat_number: (data as any)?.vat_number ?? null,
      isUsingPlatformDefault: false,
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return errorResponse("Invalid request data", "VALIDATION_ERROR", 400, error.issues);
    }
    return handleApiError(error, "Failed to update tax settings");
  }
}

