import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { z } from "zod";

const createShiftSchema = z.object({
  staff_id: z.string().uuid(),
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  start_time: z.string().regex(/^\d{2}:\d{2}$/),
  end_time: z.string().regex(/^\d{2}:\d{2}$/),
  notes: z.string().optional(),
  is_recurring: z.boolean().optional(),
  recurring_pattern: z.any().optional(),
});

/**
 * GET /api/provider/shifts
 * 
 * Get provider's staff shifts
 * Query params: week_start (YYYY-MM-DD), staff_id (optional)
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer(request);
    const searchParams = request.nextUrl.searchParams;
    const weekStart = searchParams.get('week_start');
    const staffId = searchParams.get('staff_id');

    // Get provider ID
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    let query = supabase
      .from("staff_shifts")
      .select(`
        id,
        staff_id,
        date,
        start_time,
        end_time,
        notes,
        is_recurring,
        recurring_pattern,
        provider_staff:staff_id(id, name:users(full_name))
      `)
      .eq("provider_id", providerId)
      .order("date", { ascending: true });

    // Filter by date range (week)
    if (weekStart) {
      const start = new Date(weekStart);
      const end = new Date(start);
      end.setDate(end.getDate() + 6);
      query = query.gte("date", start.toISOString().split("T")[0])
                   .lte("date", end.toISOString().split("T")[0]);
    }

    // Filter by staff member
    if (staffId) {
      query = query.eq("staff_id", staffId);
    }

    const { data: shifts, error } = await query;

    if (error) {
      throw error;
    }

    // Transform response to match expected format
    const transformedShifts = (shifts || []).map((shift: any) => ({
      id: shift.id,
      team_member_id: shift.staff_id,
      team_member_name: shift.provider_staff?.name?.full_name || "Staff",
      date: shift.date,
      start_time: shift.start_time.substring(0, 5), // HH:MM format
      end_time: shift.end_time.substring(0, 5),
      notes: shift.notes,
      is_recurring: shift.is_recurring,
      recurring_pattern: shift.recurring_pattern,
    }));

    return successResponse(transformedShifts);
  } catch (error) {
    return handleApiError(error, "Failed to fetch shifts");
  }
}

/**
 * POST /api/provider/shifts
 * 
 * Create a new shift
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'superadmin'], request);

    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    // Validate input
    const validationResult = createShiftSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    const { staff_id, date, start_time, end_time, notes, is_recurring, recurring_pattern } = validationResult.data;

    // Get provider ID
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Verify staff belongs to provider
    const { data: staff } = await supabase
      .from("provider_staff")
      .select("id")
      .eq("id", staff_id)
      .eq("provider_id", providerId)
      .single();

    if (!staff) {
      return notFoundResponse("Staff member not found");
    }

    // Create shift
    const { data: newShift, error: insertError } = await (supabase
      .from("staff_shifts") as any)
      .insert({
        provider_id: providerId,
        staff_id,
        date,
        start_time,
        end_time,
        notes,
        is_recurring: is_recurring || false,
        recurring_pattern,
      })
      .select(`
        id,
        staff_id,
        date,
        start_time,
        end_time,
        notes,
        is_recurring,
        recurring_pattern
      `)
      .single();

    if (insertError || !newShift) {
      throw insertError || new Error("Failed to create shift");
    }

    // Transform response
    const transformedShift = {
      id: newShift.id,
      team_member_id: newShift.staff_id,
      date: newShift.date,
      start_time: newShift.start_time.substring(0, 5),
      end_time: newShift.end_time.substring(0, 5),
      notes: newShift.notes,
      is_recurring: newShift.is_recurring,
      recurring_pattern: newShift.recurring_pattern,
    };

    return successResponse(transformedShift);
  } catch (error) {
    return handleApiError(error, "Failed to create shift");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  getProviderIdForUser,
  successResponse,
  notFoundResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";
import { z } from "zod";

const updateSchema = z.object({
  offers_delivery: z.boolean().optional(),
  offers_collection: z.boolean().optional(),
  delivery_fee: z.number().min(0).optional(),
  free_delivery_threshold: z.number().min(0).nullable().optional(),
  delivery_radius_km: z.number().min(0).nullable().optional(),
  estimated_delivery_days: z.number().int().min(1).optional(),
  delivery_notes: z.string().max(500).nullable().optional(),
});

/**
 * GET /api/provider/shipping-config
 * Get current shipping configuration
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const { data, error } = await (supabase.from("provider_shipping_config") as any)
      .select("*")
      .eq("provider_id", providerId)
      .maybeSingle();

    if (error) throw error;

    // Return defaults if no config exists
    const config = data ?? {
      provider_id: providerId,
      offers_delivery: false,
      offers_collection: true,
      delivery_fee: 0,
      free_delivery_threshold: null,
      delivery_radius_km: null,
      estimated_delivery_days: 3,
      delivery_notes: null,
    };

    return successResponse({ config });
  } catch (err) {
    return handleApiError(err, "Failed to fetch shipping config");
  }
}

/**
 * PUT /api/provider/shipping-config
 * Create or update shipping configuration (upsert)
 */
export async function PUT(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const body = await request.json();
    const parsed = updateSchema.parse(body);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    const { data: existing } = await (supabase.from("provider_shipping_config") as any)
      .select("id")
      .eq("provider_id", providerId)
      .maybeSingle();

    let result;
    if (existing) {
      const { data, error } = await (supabase.from("provider_shipping_config") as any)
        .update(parsed)
        .eq("provider_id", providerId)
        .select()
        .single();
      if (error) throw error;
      result = data;
    } else {
      const { data, error } = await (supabase.from("provider_shipping_config") as any)
        .insert({ provider_id: providerId, ...parsed })
        .select()
        .single();
      if (error) throw error;
      result = data;
    }

    return successResponse({ config: result });
  } catch (err) {
    return handleApiError(err, "Failed to update shipping config");
  }
}

import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";

export async function GET(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      { auth: { autoRefreshToken: false, persistSession: false } },
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) return notFoundResponse("Provider not found");
    const sp = request.nextUrl.searchParams;
    const limit = Math.min(parseInt(sp.get("limit") || "10", 10), 50);

    const { data: bookingServiceIds } = await supabaseAdmin
      .from("booking_services")
      .select("booking_id")
      .eq("staff_id", id);

    const bookingIds = [...new Set((bookingServiceIds || []).map((bs: any) => bs.booking_id))];

    if (bookingIds.length === 0) {
      return successResponse([]);
    }

    const { data: bookings } = await supabaseAdmin
      .from("bookings")
      .select(`
        id, booking_number, status, scheduled_at, total_amount, currency,
        customers:customer_id(full_name),
        booking_services(offerings:offering_id(title))
      `)
      .eq("provider_id", providerId)
      .in("id", bookingIds)
      .order("scheduled_at", { ascending: false })
      .limit(limit);

    const result = (bookings || []).map((b: any) => ({
      id: b.id,
      booking_number: b.booking_number,
      status: b.status,
      scheduled_at: b.scheduled_at,
      customer_name: b.customers?.full_name || "Walk-in",
      service_names: (b.booking_services || []).map((bs: any) => bs.offerings?.title || "Service").filter(Boolean),
      total_amount: Number(b.total_amount || 0),
      currency: b.currency || "ZAR",
    }));

    return successResponse(result);
  } catch (error) {
    return handleApiError(error, "Failed to load staff bookings");
  }
}

