    // Verify staff belongs to provider
    const { data: staff, error: staffError } = await supabase
      .from("provider_staff")
      .select("id, user_id, time_clock_enabled, time_clock_pin")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (staffError || !staff) {
      return notFoundResponse("Staff member not found");
    }

    // If PIN provided, verify it
    if (body.pin && staff.time_clock_pin !== body.pin) {
      return errorResponse("Invalid PIN", "INVALID_PIN", 401);
    }

    // Check if already clocked in (has active time card)
    const today = new Date().toISOString().split('T')[0];
    const { data: activeTimeCard } = await supabase
      .from("staff_time_cards")
      .select("id")
      .eq("staff_id", id)
      .eq("date", today)
      .is("clock_out_time", null)
      .maybeSingle();

    if (activeTimeCard) {
      return errorResponse("Staff member is already clocked in", "ALREADY_CLOCKED_IN", 400);
    }

    // Create time card entry
    const now = new Date();
    const { data: timeCard, error: insertError } = await supabase
      .from("staff_time_cards")
      .insert({
        staff_id: id,
        provider_id: providerId,
        date: today,
        clock_in_time: now.toISOString(),
        clock_out_time: null,
      })
      .select()
      .single();

    if (insertError) {
      // If table doesn't exist, create a simple response
      if (insertError.code === '42P01') {
        // Table doesn't exist - return success with mock data for now
        return successResponse({
          id: `temp-${Date.now()}`,
          staff_id: id,
          date: today,
          clock_in_time: now.toISOString(),
          clock_out_time: null,
          status: "clocked_in",
        });
      }
      throw insertError;
    }

    return successResponse({
      id: timeCard.id,
      staff_id: id,
      date: today,
      clock_in_time: timeCard.clock_in_time,
      clock_out_time: null,
      status: "clocked_in",
    });
  } catch (error) {
    return handleApiError(error, "Failed to clock in");
  }
}

/**
 * PATCH /api/provider/staff/[id]/time-clock/clock-out
 * 
 * Clock out a staff member
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const { id } = await params;

    // Get provider ID
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Verify staff belongs to provider
    const { data: staff } = await supabase
      .from("provider_staff")
      .select("id")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (!staff) {
      return notFoundResponse("Staff member not found");
    }

    // Find active time card
    const today = new Date().toISOString().split('T')[0];
    const { data: timeCard, error: findError } = await supabase
      .from("staff_time_cards")
      .select("id, clock_in_time")
      .eq("staff_id", id)
      .eq("date", today)
      .is("clock_out_time", null)
      .single();

    if (findError || !timeCard) {
      if (findError?.code === 'PGRST116') {
        return errorResponse("No active clock-in found", "NO_ACTIVE_CLOCK_IN", 400);
      }
      // If table doesn't exist, return success
      if (findError?.code === '42P01') {
        return successResponse({ success: true });
      }
      throw findError;
    }

    // Update time card (total_hours will be auto-calculated by trigger)
    const clockOut = new Date();
    const { data: updatedCard, error: updateError } = await supabase
      .from("staff_time_cards")
      .update({
        clock_out_time: clockOut.toISOString(),
        // total_hours will be automatically calculated by database trigger
      })
      .eq("id", timeCard.id)
      .select()
      .single();

    if (updateError) {
      if (updateError.code === '42P01') {
        return successResponse({ success: true });
      }
      throw updateError;
    }

    return successResponse({
      id: updatedCard.id,
      staff_id: id,
      date: today,
      clock_in_time: updatedCard.clock_in_time,
      clock_out_time: updatedCard.clock_out_time,
      total_hours: updatedCard.total_hours,
      status: "clocked_out",
    });
  } catch (error) {
    return handleApiError(error, "Failed to clock out");
  }
}

/**
 * GET /api/provider/staff/[id]/time-clock
 * 
 * Get time cards for a staff member
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const { id } = await params;
    const { searchParams } = new URL(request.url);
    const dateFrom = searchParams.get("date_from");
    const dateTo = searchParams.get("date_to");

    // Get provider ID
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Verify staff belongs to provider
    const { data: staff } = await supabase
      .from("provider_staff")
      .select("id, name")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (!staff) {
      return notFoundResponse("Staff member not found");
    }

    // Build query
    let query = supabase
      .from("staff_time_cards")
      .select("*")
      .eq("staff_id", id)
      .order("date", { ascending: false })
      .order("clock_in_time", { ascending: false });

    if (dateFrom) {
      query = query.gte("date", dateFrom);
    }
    if (dateTo) {
      query = query.lte("date", dateTo);
    }

    const { data: timeCards, error } = await query;

    if (error) {
      // If table doesn't exist, return empty array
      if (error.code === '42P01') {
        return successResponse([]);
      }
      throw error;
    }

    // Transform response
    const transformed = (timeCards || []).map((card: any) => ({
      id: card.id,
      team_member_id: card.staff_id,
      team_member_name: staff.name,
      date: card.date,
      clock_in_time: card.clock_in_time ? new Date(card.clock_in_time).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }) : null,
      clock_out_time: card.clock_out_time ? new Date(card.clock_out_time).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }) : null,
      total_hours: card.total_hours || null,
      status: card.clock_out_time ? "clocked_out" : "clocked_in",
    }));

    return successResponse(transformed);
  } catch (error) {
    return handleApiError(error, "Failed to fetch time cards");
  }
}

/**
 * PUT /api/provider/staff/[id]/time-clock/[timeCardId]
 * 
 * Update a time card
 */
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; timeCardId: string }> }
) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const { id, timeCardId } = await params;
    const body = await request.json();

    // Get provider ID
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Verify staff belongs to provider
    const { data: staff } = await supabase
      .from("provider_staff")
      .select("id")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (!staff) {
      return notFoundResponse("Staff member not found");
    }

    // Build update data
    const updateData: any = {};
    if (body.clock_in_time) {
      updateData.clock_in_time = new Date(body.clock_in_time).toISOString();
    }
    if (body.clock_out_time !== undefined) {
      updateData.clock_out_time = body.clock_out_time ? new Date(body.clock_out_time).toISOString() : null;
    }

    // Note: total_hours will be automatically calculated by database trigger
    // when clock_out_time is set, so we don't need to calculate it here

    // Update time card
    const { data: updatedCard, error: updateError } = await supabase
      .from("staff_time_cards")
      .update(updateData)
      .eq("id", timeCardId)
      .eq("staff_id", id)
      .select()
      .single();

    if (updateError) {
      if (updateError.code === '42P01') {
        return successResponse({ success: true });
      }
      throw updateError;
    }

    return successResponse(updatedCard);
  } catch (error) {
    return handleApiError(error, "Failed to update time card");
  }
}

import { NextRequest } from "next/server";
import { requireRoleInApi, successResponse, notFoundResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { getProviderRevenue } from "@/lib/reports/revenue-helpers";
import { calculateStaffCommission } from "@/lib/payroll/commission-calculator";
import { getTipsByStaff } from "@/lib/payroll/tips-helper";

export interface StaffTotalsItem {
  team_member_id: string;
  team_member_name: string;
  appointments_count: number;
  revenue: number;
  tips: number;
  hours_worked: number;
  commission: number;
  rating?: number;
}

/**
 * GET /api/provider/staff/[id]/totals
 * Get staff totals for a specific member
 * Query: date (YYYY-MM-DD), period (daily|weekly), start_date, end_date
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);
    const { id } = await params;

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      { auth: { autoRefreshToken: false, persistSession: false } }
    );

    const { data: providerAsOwner } = await supabaseAdmin
      .from("providers")
      .select("id")
      .eq("user_id", user.id)
      .maybeSingle();

    const { data: staffAsUser } = await supabaseAdmin
      .from("provider_staff")
      .select("provider_id")
      .eq("user_id", user.id)
      .maybeSingle();

    const providerId = providerAsOwner?.id ?? staffAsUser?.provider_id;
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const { data: staff } = await supabaseAdmin
      .from("provider_staff")
      .select("id, user_id, users(full_name)")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (!staff) {
      return notFoundResponse("Staff member not found");
    }

    const { searchParams } = new URL(request.url);
    const period = searchParams.get("period") || "daily";
    const dateStr = searchParams.get("date");
    const startDateStr = searchParams.get("start_date");
    const endDateStr = searchParams.get("end_date");

    let fromDate: Date;
    let toDate: Date;

    if (period === "daily" && dateStr) {
      fromDate = new Date(dateStr);
      fromDate.setHours(0, 0, 0, 0);
      toDate = new Date(dateStr);
      toDate.setHours(23, 59, 59, 999);
    } else if (period === "weekly" && startDateStr && endDateStr) {
      fromDate = new Date(startDateStr);
      fromDate.setHours(0, 0, 0, 0);
      toDate = new Date(endDateStr);
      toDate.setHours(23, 59, 59, 999);
    } else {
      const fallback = new Date();
      fromDate = new Date(fallback);
      fromDate.setDate(fallback.getDate() - 7);
      toDate = new Date();
    }

    const commission = await calculateStaffCommission(
      supabaseAdmin,
      providerId,
      id,
      fromDate,
      toDate
    );

    const { revenueByBooking } = await getProviderRevenue(
      supabaseAdmin,
      providerId,
      fromDate,
      toDate
    );

    const { data: bookings } = await supabaseAdmin
      .from("bookings")
      .select("id, status, booking_services(id, staff_id, price)")
      .eq("provider_id", providerId)
      .gte("scheduled_at", fromDate.toISOString())
      .lte("scheduled_at", toDate.toISOString())
      .in("status", ["confirmed", "completed"]);

    let appointmentsCount = 0;
    let revenue = 0;
    for (const b of bookings || []) {
      const services = (b as any).booking_services || [];
      const staffServices = services.filter((s: any) => s.staff_id === id);
      if (staffServices.length === 0) continue;
      appointmentsCount += 1;
      const totalPrice = services.reduce((s: number, x: any) => s + Number(x.price || 0), 0);
      const staffPrice = staffServices.reduce((s: number, x: any) => s + Number(x.price || 0), 0);
      if (totalPrice > 0) {
        revenue += (revenueByBooking.get((b as any).id) || 0) * (staffPrice / totalPrice);
      }
    }

    const { data: timeCards } = await supabaseAdmin
      .from("staff_time_cards")
      .select("total_hours")
      .eq("staff_id", id)
      .gte("date", fromDate.toISOString().split("T")[0])
      .lte("date", toDate.toISOString().split("T")[0])
      .not("total_hours", "is", null);

    const hoursWorked = (timeCards || []).reduce(
      (s: number, tc: any) => s + Number(tc.total_hours || 0),
      0
    );

    const tipsByStaff = await getTipsByStaff(supabaseAdmin, providerId, fromDate, toDate);
    const tips = tipsByStaff.get(id) || 0;

    const item: StaffTotalsItem = {
      team_member_id: id,
      team_member_name: (staff.users as any)?.full_name || "Unknown",
      appointments_count: appointmentsCount,
      revenue,
      tips,
      hours_worked: hoursWorked,
      commission: commission.totalCommission,
      rating: undefined,
    };

    return successResponse([item]);
  } catch (error) {
    return handleApiError(error, "Failed to load staff totals");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/provider/staff/available
 * 
 * Get available staff for a specific date/time and service
 * 
 * Query params:
 * - date: YYYY-MM-DD
 * - startTime: HH:mm
 * - endTime: HH:mm
 * - serviceId: UUID (optional - filter by who offers this service)
 * - locationId: UUID (optional - filter by location)
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff'], request);
    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);

    // Get provider ID
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return successResponse({ data: [] });
    }

    // Get query params
    const date = searchParams.get('date');
    const startTime = searchParams.get('startTime');
    const endTime = searchParams.get('endTime');
    const serviceId = searchParams.get('serviceId');
    const locationId = searchParams.get('locationId');

    // Base query: get all active staff
    let query = supabase
      .from("provider_staff")
      .select(`
        *,
        staff_services!left(service_id, offering_id),
        staff_schedules!left(day_of_week, start_time, end_time, is_working),
        staff_time_off!left(start_date, end_date, reason),
        provider_staff_locations!left(location_id)
      `)
      .eq("provider_id", providerId)
      .eq("is_active", true);

    // Filter by location if provided (using junction table)
    if (locationId) {
      query = query.eq("provider_staff_locations.location_id", locationId);
    }

    const { data: staff, error } = await query;

    if (error) {
      throw error;
    }

    if (!staff) {
      return successResponse({ data: [] });
    }

    // Pre-fetch all bookings for this provider on this date
    const existingBookingsMap: Record<string, any[]> = {};
    if (date && startTime && endTime) {
      const { data: dayBookings } = await supabase
        .from("booking_services")
        .select("staff_id, start_time, end_time, booking:bookings!inner(status, scheduled_at)")
        .eq("booking.provider_id", providerId)
        .in("booking.status", ["confirmed", "checked_in", "in_progress"]);

      // Group by staff_id
      for (const bs of dayBookings || []) {
        if (!existingBookingsMap[bs.staff_id]) existingBookingsMap[bs.staff_id] = [];
        existingBookingsMap[bs.staff_id].push(bs);
      }
    }

    // Filter staff based on availability
    const availableStaff = staff.filter(member => {
      // 1. Check if staff offers the service (if serviceId provided)
      if (serviceId) {
        const offersService = (member as any).staff_services?.some(
          (ss: any) => ss.service_id === serviceId || ss.offering_id === serviceId
        );
        if (!offersService) return false;
      }

      // 2. Check if working on this day/time (if date/time provided)
      if (date && startTime && endTime) {
        const dayOfWeek = new Date(date).getDay(); // 0 = Sunday, 6 = Saturday
        const schedule = (member as any).staff_schedules?.find(
          (s: any) => s.day_of_week === dayOfWeek
        );

        // Not working this day
        if (!schedule || !schedule.is_working) return false;

        // Check if time slot is within working hours
        if (schedule.start_time && schedule.end_time) {
          if (startTime < schedule.start_time || endTime > schedule.end_time) {
            return false;
          }
        }
      }

      // 3. Check if on time off (if date provided)
      if (date) {
        const isOnTimeOff = (member as any).staff_time_off?.some((timeOff: any) => {
          return date >= timeOff.start_date && date <= timeOff.end_date;
        });
        if (isOnTimeOff) return false;
      }

      // 4. Check if already booked at this time (if date/time provided)
      if (date && startTime && endTime) {
        const staffBookings = existingBookingsMap[member.id] || [];
        const hasConflict = staffBookings.some((b: any) => {
          const bDate = (b.booking as any)?.scheduled_at?.split('T')[0];
          return bDate === date; // Staff is busy on this date at this time
        });
        if (hasConflict) return false;
      }

      return true;
    });

    // Clean up response (remove joined tables)
    const cleanedStaff = availableStaff.map(member => {
      const { staff_services: _staff_services, staff_schedules: _staff_schedules, staff_time_off: _staff_time_off, provider_staff_locations: _provider_staff_locations, ...rest } = member as any;
      return rest;
    });

    return successResponse({ data: cleanedStaff });
  } catch (error) {
    return handleApiError(error, "Failed to fetch available staff");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { checkStaffManagementFeatureAccess } from "@/lib/subscriptions/feature-access";
import { checkStaffLimit, formatLimitError } from "@/lib/subscriptions/limit-checker";
import { z } from "zod";

interface StaffMember {
  id: string;
  name: string;
  email: string;
  phone?: string;
  role: "provider_staff";
  is_active: boolean;
}

/**
 * GET /api/provider/staff
 *
 * PROVIDER STAFF vs ADMIN STAFF (Cross-Portal boundary):
 * - Provider staff: returns ONLY staff for the current provider (via getProviderIdForUser).
 * - Admin staff: GET /api/admin/staff returns ALL provider_staff across providers (superadmin only).
 * - Same provider_staff table; different scoping. See admin/staff/route.ts for boundary doc.
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);

    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);
    const locationId = searchParams.get("location_id");

    // Get provider ID
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      console.error("Provider not found for user:", user.id);
      return notFoundResponse("Provider not found");
    }

    // Check if provider is a freelancer
    const { data: providerData } = await supabase
      .from("providers")
      .select("business_type")
      .eq("id", providerId)
      .single();

    const isFreelancer = providerData?.business_type === 'freelancer';

    // If location_id is provided, first get staff IDs assigned to that location
    let staffIds: string[] | null = null;
    if (locationId) {
      const { data: assignments, error: assignmentError } = await supabase
        .from("provider_staff_locations")
        .select("staff_id")
        .eq("location_id", locationId);

      if (assignmentError) {
        throw assignmentError;
      }

      staffIds = assignments?.map(a => a.staff_id) || [];

      // For freelancers: if no assignment found, check if location belongs to provider
      // This is a fallback for edge cases where assignment might be missing
      if (isFreelancer && staffIds.length === 0) {
        const { data: locationData } = await supabase
          .from("provider_locations")
          .select("id")
          .eq("id", locationId)
          .eq("provider_id", providerId)
          .single();

        // If location belongs to freelancer, get their staff ID
        if (locationData) {
          const { data: freelancerStaff } = await supabase
            .from("provider_staff")
            .select("id")
            .eq("provider_id", providerId)
            .eq("role", "owner")
            .limit(1);

          if (freelancerStaff && freelancerStaff.length > 0) {
            staffIds = [freelancerStaff[0].id];
          }
        }
      }

      // If still no staff found, return empty array
      if (!staffIds || staffIds.length === 0) {
        return successResponse([]);
      }
    }

    // Build staff query with optional location filter
    // Start with basic fields to avoid RLS issues with nested relationships
    let staffQuery = supabase
      .from("provider_staff")
      .select(
        `
        id,
        user_id,
        provider_id,
        name,
        email,
        phone,
        avatar_url,
        role,
        is_active,
        mobile_ready,
        working_hours
      `
      )
      .eq("provider_id", providerId);

    // If location_id is provided, filter by staff IDs
    if (locationId && staffIds && staffIds.length > 0) {
      staffQuery = staffQuery.in("id", staffIds);
    }

    const { data: staff, error } = await staffQuery.order("created_at", { ascending: false });

    if (error) {
      console.error("Error fetching staff:", error);
      throw error;
    }

    // Fetch related data separately to avoid RLS issues
    const staffWithDetails = await Promise.all(
      (staff || []).map(async (member: any) => {
        // Try to fetch user data if user_id exists
        let userData = null;
        if (member.user_id) {
          const { data: user } = await supabase
            .from("users")
            .select("id, full_name, email, phone, avatar_url")
            .eq("id", member.user_id)
            .maybeSingle();
          userData = user;
        }

        // Try to fetch location assignments separately to avoid RLS issues
        let locations: any[] = [];
        try {
          const { data: assignments } = await supabase
            .from("provider_staff_locations")
            .select("location_id, is_primary")
            .eq("staff_id", member.id);

          if (assignments && assignments.length > 0) {
            // Fetch location details separately
            const locationIds = assignments.map(a => a.location_id);
            const { data: locationDetails } = await supabase
              .from("provider_locations")
              .select("id, name, city")
              .in("id", locationIds);

            const locationMap = new Map((locationDetails || []).map((loc: any) => [loc.id, loc]));

            locations = assignments.map((sl: any) => {
              const location = locationMap.get(sl.location_id);
              return {
                location_id: sl.location_id,
                location_name: location?.name || null,
                location_city: location?.city || null,
                is_primary: sl.is_primary || false,
              };
            });
          }
        } catch (locError) {
          console.warn("Error fetching staff locations:", locError);
          // Continue without location data
        }

        return {
          ...member,
          users: userData,
          staff_locations: locations,
        };
      })
    );

    // Transform to match expected format
    // Use provider_staff data first (since we store it there), then fall back to users table
    // Map database role format to API format
    const transformedStaff = (staffWithDetails || []).map((member: any) => {
      // Map database role (owner/manager/employee) to API format (provider_owner/provider_manager/provider_staff)
      const apiRole = member.role === "owner" ? "provider_owner"
                   : member.role === "manager" ? "provider_manager"
                   : "provider_staff";

      // Extract location assignments (staff_locations have location_name/location_city from join)
      const locations = (member.staff_locations || []).map((sl: any) => ({
        location_id: sl.location_id,
        location_name: sl.location_name ?? sl.location?.name ?? null,
        location_city: sl.location_city ?? sl.location?.city ?? null,
        is_primary: sl.is_primary || false,
      }));

      return {
        id: member.id,
        name: member.name || member.users?.full_name || "Staff Member",
        email: member.email || member.users?.email || "",
        phone: member.phone || member.users?.phone || null,
        avatar_url: member.avatar_url || member.users?.avatar_url || null,
        role: apiRole,
        is_active: member.is_active ?? true,
        mobileReady: member.mobile_ready ?? false, // Map snake_case to camelCase
        locations: locations, // Include location assignments
        primary_location_id: locations.find((l: any) => l.is_primary)?.location_id || null,
        working_hours: member.working_hours ?? null, // For calendar: staff-specific working hours
      };
    });

    return successResponse(transformedStaff as StaffMember[]);
  } catch (error) {
    console.error("Staff API error:", error);
    // Provide more specific error message
    if (error instanceof Error) {
      if (error.message.includes("Authentication") || error.message.includes("permissions")) {
        return handleApiError(error, "Authentication failed. Please log in again.", "AUTH_ERROR", 401);
      }
      if (error.message.includes("Provider not found")) {
        return handleApiError(error, "Provider account not found.", "PROVIDER_NOT_FOUND", 404);
      }
    }
    return handleApiError(error, "Failed to fetch staff");
  }
}

const addStaffSchema = z.object({
  email: z.string().email("Invalid email address"),
  role: z.string().optional().default("provider_staff"),
  name: z.string().optional(),
  phone: z.string().optional().nullable(),
  mobileReady: z.boolean().optional().default(false),
});

/**
 * POST /api/provider/staff
 * 
 * Add a new staff member
 */
export async function POST(request: Request) {
  try {
    // Check permission to manage team
    const permissionCheck = await requirePermission('manage_team', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;

    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Check subscription allows staff management
    const staffAccess = await checkStaffManagementFeatureAccess(providerId);
    if (!staffAccess.enabled) {
      return errorResponse(
        "Staff management requires a subscription upgrade. Please upgrade your plan to add staff members.",
        "SUBSCRIPTION_REQUIRED",
        403
      );
    }

    // Check staff limit using new limit checker
    const staffLimitCheck = await checkStaffLimit(providerId);
    if (!staffLimitCheck.canProceed) {
      return errorResponse(
        formatLimitError(staffLimitCheck),
        "SUBSCRIPTION_LIMIT_EXCEEDED",
        403
      );
    }

    const body = await request.json();

    // Validate input
    const validationResult = addStaffSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    const { email, role, name, phone, mobileReady } = validationResult.data;

    // Map API role format to database role format
    // API uses: provider_staff, provider_manager, provider_owner
    // Database expects: employee, manager, owner
    const dbRole = role === "provider_owner" ? "owner" 
                 : role === "provider_manager" ? "manager" 
                 : "employee";

    // Find user by email or create if doesn't exist
    let { data: foundUser, error: _findUserError } = await supabase
      .from("users")
      .select("id, full_name, email, phone")
      .eq("email", email)
      .maybeSingle();

    if (!foundUser) {
      // User doesn't exist - we need to create an auth user first
      // Since users table references auth.users, we need to use Supabase Admin
      try {
        // Check if service role key is available
        if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
          console.error("SUPABASE_SERVICE_ROLE_KEY is not set");
          return errorResponse(
            "Server configuration error: Service role key not configured. Cannot create users automatically.",
            "CONFIG_ERROR",
            500
          );
        }

        const { createClient } = await import("@supabase/supabase-js");
        const supabaseAdmin = createClient(
          process.env.NEXT_PUBLIC_SUPABASE_URL!,
          process.env.SUPABASE_SERVICE_ROLE_KEY!,
          {
            auth: {
              autoRefreshToken: false,
              persistSession: false,
            },
          }
        );

        const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

        if (!providerId) return notFoundResponse("Provider not found");


        // Create auth user with a temporary password (user will need to reset)
        const tempPassword = `Temp${Math.random().toString(36).slice(-12)}!`;
        console.log("Creating auth user for:", email);
        const { data: authUser, error: authError } = await supabaseAdmin.auth.admin.createUser({
          email: email,
          password: tempPassword,
          email_confirm: true, // Auto-confirm email
          user_metadata: {
            full_name: name || email.split("@")[0],
            name: name || email.split("@")[0], // Also set 'name' for trigger compatibility
            phone: phone || null,
            role: "customer", // Default role
          },
        });

        if (authError || !authUser?.user) {
          console.error("Failed to create auth user:", authError);
          return errorResponse(
            `Failed to create user account: ${authError?.message || "Unknown error"}. The user may need to sign up first.`,
            "USER_CREATION_ERROR",
            500,
            authError
          );
        }

        console.log("Auth user created, waiting for trigger...", authUser.user.id);

        // Wait a moment for the trigger to create the user record
        // Try multiple times in case trigger is slow
        // Use admin client to bypass RLS when checking for user profile
        let createdUser = null;
        let fetchError = null;
        for (let i = 0; i < 5; i++) {
          await new Promise(resolve => setTimeout(resolve, 500));
          // Use admin client to bypass RLS when checking for user profile
          const { data: user, error: err } = await supabaseAdmin
            .from("users")
            .select("id, full_name, email, phone")
            .eq("id", authUser.user.id)
            .maybeSingle();

          if (user) {
            createdUser = user;
            break;
          }
          fetchError = err;
        }

        if (!createdUser) {
          console.error("Failed to fetch created user after retries, attempting manual creation:", fetchError);

          // Fallback: Try to fetch the user profile one more time with admin client
          // The profile might exist but wasn't visible due to RLS
          try {
            const { data: finalUser, error: _finalError } = await supabaseAdmin
              .from("users")
              .select("id, full_name, email, phone")
              .eq("id", authUser.user.id)
              .maybeSingle();

            if (finalUser) {
              createdUser = finalUser;
              console.log("User profile found with admin client:", createdUser.id);
            } else {
              // If still not found, try to create manually (in case trigger truly didn't fire)
              const { data: manualUser, error: manualError } = await supabaseAdmin
                .from("users")
                .insert({
                  id: authUser.user.id,
                  email: email,
                  full_name: name || email.split("@")[0],
                  phone: phone || null,
                  role: "customer",
                })
                .select("id, full_name, email, phone")
                .single();

              if (manualUser) {
                createdUser = manualUser;
                console.log("User profile created manually:", createdUser.id);
              } else if (manualError?.code === '23505') {
                // Duplicate key error - user already exists, fetch it
                const { data: existingUser } = await supabaseAdmin
                  .from("users")
                  .select("id, full_name, email, phone")
                  .eq("id", authUser.user.id)
                  .single();
                if (existingUser) {
                  createdUser = existingUser;
                  console.log("User profile found after duplicate key error:", createdUser.id);
                } else {
                  throw manualError || new Error("Failed to create or fetch user profile");
                }
              } else {
                throw manualError || new Error("Failed to create user profile manually");
              }
            }
          } catch (manualError: any) {
            console.error("Failed to fetch or create user profile:", manualError);
            return errorResponse(
              "User account created but profile not found. Please try again or contact support.",
              "USER_FETCH_ERROR",
              500,
              manualError || fetchError
            );
          }
        }

        console.log("User profile found:", createdUser.id);
        foundUser = createdUser;
      } catch (error: any) {
        console.error("Error creating user:", error);
        return errorResponse(
          `Failed to create user: ${error?.message || "Unknown error"}. Please ensure the user exists or contact support.`,
          "USER_CREATION_ERROR",
          500,
          error
        );
      }
    }

    // Check if already a staff member
    const { data: existingStaff } = await supabase
      .from("provider_staff")
      .select("id")
      .eq("provider_id", providerId)
      .eq("user_id", foundUser.id)
      .maybeSingle();

    if (existingStaff) {
      return errorResponse("User is already a staff member", "DUPLICATE_ERROR", 400);
    }

    // Add staff member
    const { data: newStaff, error: insertError } = await (supabase
      .from("provider_staff") as any)
      .insert({
        provider_id: providerId,
        user_id: foundUser.id,
        name: name || foundUser.full_name || foundUser.email?.split("@")[0] || "Staff Member",
        email: foundUser.email,
        phone: foundUser.phone,
        role: dbRole,
        is_active: true,
        mobile_ready: mobileReady || false,
      })
      .select(
        `
        id,
        user_id,
        provider_id,
        role,
        is_active,
        users:user_id(id, full_name, email, phone)
      `
      )
      .single();

    if (insertError || !newStaff) {
      console.error("Failed to insert staff member:", insertError);
      throw insertError || new Error("Failed to create staff member");
    }

    console.log("Staff member created successfully:", newStaff.id);

    // Transform response
    // Map database role format back to API format
    // Database uses: owner, manager, employee
    // API expects: provider_owner, provider_manager, provider_staff
    const apiRole = newStaff.role === "owner" ? "provider_owner"
                  : newStaff.role === "manager" ? "provider_manager"
                  : "provider_staff";

    const transformedStaff = {
      id: newStaff.id,
      name: newStaff.name || newStaff.users?.full_name || "Staff Member",
      email: newStaff.email || newStaff.users?.email || "",
      phone: newStaff.phone || newStaff.users?.phone || null,
      role: apiRole,
      is_active: newStaff.is_active ?? true,
    };

    return successResponse(transformedStaff as StaffMember);
  } catch (error) {
    return handleApiError(error, "Failed to add staff member");
  }
}

import { NextRequest } from "next/server";
import { requireRoleInApi, successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { getProviderRevenue } from "@/lib/reports/revenue-helpers";
import { calculateStaffCommission } from "@/lib/payroll/commission-calculator";
import { getTipsByStaff } from "@/lib/payroll/tips-helper";

export interface StaffTotalsItem {
  team_member_id: string;
  team_member_name: string;
  appointments_count: number;
  revenue: number;
  tips: number;
  hours_worked: number;
  commission: number;
  rating?: number;
}

/**
 * GET /api/provider/staff/totals
 * Aggregate staff totals for date or date range
 * Query: date (YYYY-MM-DD), period (daily|weekly), start_date, end_date
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      { auth: { autoRefreshToken: false, persistSession: false } }
    );

    const { data: providerAsOwner } = await supabaseAdmin
      .from("providers")
      .select("id")
      .eq("user_id", user.id)
      .maybeSingle();

    const { data: staffAsUser } = await supabaseAdmin
      .from("provider_staff")
      .select("provider_id")
      .eq("user_id", user.id)
      .maybeSingle();

    const providerId = providerAsOwner?.id ?? staffAsUser?.provider_id;
    if (!providerId) {
      return handleApiError(new Error("Provider not found"), "NOT_FOUND", 404);
    }

    const { searchParams } = new URL(request.url);
    const period = searchParams.get("period") || "daily";
    const dateStr = searchParams.get("date");
    const startDateStr = searchParams.get("start_date");
    const endDateStr = searchParams.get("end_date");

    let fromDate: Date;
    let toDate: Date;

    if (period === "daily" && dateStr) {
      fromDate = new Date(dateStr);
      fromDate.setHours(0, 0, 0, 0);
      toDate = new Date(dateStr);
      toDate.setHours(23, 59, 59, 999);
    } else if (period === "weekly" && startDateStr && endDateStr) {
      fromDate = new Date(startDateStr);
      fromDate.setHours(0, 0, 0, 0);
      toDate = new Date(endDateStr);
      toDate.setHours(23, 59, 59, 999);
    } else {
      const fallback = new Date();
      fromDate = new Date(fallback);
      fromDate.setDate(fallback.getDate() - 7);
      toDate = new Date();
    }

    const { data: staffMembers } = await supabaseAdmin
      .from("provider_staff")
      .select("id, user_id, users(full_name)")
      .eq("provider_id", providerId)
      .eq("is_active", true);

    if (!staffMembers?.length) {
      return successResponse([]);
    }

    const { revenueByBooking } = await getProviderRevenue(
      supabaseAdmin,
      providerId,
      fromDate,
      toDate
    );

    const { data: bookings } = await supabaseAdmin
      .from("bookings")
      .select(`
        id,
        status,
        booking_services(id, staff_id, price)
      `)
      .eq("provider_id", providerId)
      .gte("scheduled_at", fromDate.toISOString())
      .lte("scheduled_at", toDate.toISOString())
      .in("status", ["confirmed", "completed"]);

    const { data: timeCards } = await supabaseAdmin
      .from("staff_time_cards")
      .select("staff_id, total_hours")
      .in("staff_id", staffMembers.map((s: any) => s.id))
      .gte("date", fromDate.toISOString().split("T")[0])
      .lte("date", toDate.toISOString().split("T")[0])
      .not("total_hours", "is", null);

    const hoursByStaff = new Map<string, number>();
    for (const tc of timeCards || []) {
      const s = (tc as any).staff_id;
      hoursByStaff.set(s, (hoursByStaff.get(s) || 0) + Number((tc as any).total_hours || 0));
    }

    const tipsByStaff = await getTipsByStaff(supabaseAdmin, providerId, fromDate, toDate);

    const results: StaffTotalsItem[] = [];

    for (const staff of staffMembers) {
      const commission = await calculateStaffCommission(
        supabaseAdmin,
        providerId,
        staff.id,
        fromDate,
        toDate
      );

      let appointmentsCount = 0;
      let revenue = 0;
      for (const b of bookings || []) {
        const services = (b as any).booking_services || [];
        const staffServices = services.filter((s: any) => s.staff_id === staff.id);
        if (staffServices.length === 0) continue;
        appointmentsCount += 1;
        const totalPrice = services.reduce((s: number, x: any) => s + Number(x.price || 0), 0);
        const staffPrice = staffServices.reduce((s: number, x: any) => s + Number(x.price || 0), 0);
        if (totalPrice > 0) {
          revenue += (revenueByBooking.get((b as any).id) || 0) * (staffPrice / totalPrice);
        }
      }

      results.push({
        team_member_id: staff.id,
        team_member_name: (staff.users as any)?.full_name || "Unknown",
        appointments_count: appointmentsCount,
        revenue,
        tips: tipsByStaff.get(staff.id) || 0,
        hours_worked: hoursByStaff.get(staff.id) || 0,
        commission: commission.totalCommission,
        rating: undefined,
      });
    }

    return successResponse(results);
  } catch (error) {
    return handleApiError(error, "Failed to load staff totals");
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseServer } from '@/lib/supabase/server';
import { requireRoleInApi, getProviderIdForUser, notFoundResponse, successResponse, handleApiError } from '@/lib/supabase/api-helpers';
import { sendTemplateNotification } from "@/lib/notifications/onesignal";
import { createClient } from '@supabase/supabase-js';
import { disableSubscription } from '@/lib/payments/paystack-complete';
import { getPaystackSecretKey } from '@/lib/payments/paystack-server';

/**
 * POST /api/provider/subscription/cancel
 * 
 * Cancel provider subscription
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");

    // Get subscription with plan details before cancelling
    const { data: subscriptionToCancel } = await supabase
      .from('provider_subscriptions')
      .select(`
        id,
        plan_id,
        expires_at,
        paystack_subscription_code,
        subscription_plans:plan_id(name)
      `)
      .eq('provider_id', providerId)
      .eq('status', 'active')
      .single();

    if (!subscriptionToCancel) {
      return handleApiError(new Error('No active subscription found'), 'No active subscription found');
    }

    // Cancel Paystack subscription if it exists
    const paystackSubscriptionCode = (subscriptionToCancel as any).paystack_subscription_code;
    if (paystackSubscriptionCode) {
      try {
        const secretKey = await getPaystackSecretKey();
        await disableSubscription(paystackSubscriptionCode, secretKey);
      } catch (paystackError) {
        console.error("Error disabling Paystack subscription:", paystackError);
        // Continue with cancellation even if Paystack call fails
      }
    }

    const { data: subscription, error } = await supabase
      .from('provider_subscriptions')
      .update({
        status: 'cancelled',
        cancelled_at: new Date().toISOString(),
        auto_renew: false,
        updated_at: new Date().toISOString(),
      })
      .eq('provider_id', providerId)
      .eq('status', 'active')
      .select()
      .single();

    if (error) {
      throw error;
    }

    // Get provider details for notification
    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const { data: providerData } = await supabaseAdmin
      .from("providers")
      .select("id, business_name, user_id")
      .eq("id", providerId)
      .single();

    // Send cancellation notification
    if (providerData?.user_id) {
      try {
        const expiresAt = (subscriptionToCancel as any).expires_at 
          ? new Date((subscriptionToCancel as any).expires_at).toLocaleDateString()
          : "End of billing period";
        const planName = (subscriptionToCancel as any).subscription_plans?.name || "Current Plan";

        await sendTemplateNotification(
          "subscription_cancelled",
          [providerData.user_id],
          {
            business_name: providerData.business_name || "Provider",
            plan_name: planName,
            expires_at: expiresAt,
            app_url: process.env.NEXT_PUBLIC_APP_URL || "https://beautonomi.com",
            year: new Date().getFullYear().toString(),
          },
          ["push", "email", "sms"]
        );
      } catch (notifError) {
        console.error("Error sending cancellation notification:", notifError);
        // Don't fail the request if notification fails
      }
    }

    return successResponse(subscription || { success: true });
  } catch (error) {
    return handleApiError(error, 'Failed to cancel subscription');
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseServer } from '@/lib/supabase/server';
import { requireRoleInApi, successResponse, handleApiError, getProviderIdForUser } from '@/lib/supabase/api-helpers';
import { z } from 'zod';
import { convertToSmallestUnit, generateTransactionReference } from "@/lib/payments/paystack";
import { initializePaystackTransaction } from "@/lib/payments/paystack-server";
import { createCustomer, fetchCustomer } from '@/lib/payments/paystack-complete';

const initializePaymentSchema = z.object({
  plan_id: z.string().uuid('Plan ID is required'),
  billing_period: z.enum(["monthly", "yearly"]).default("monthly"),
});

/**
 * POST /api/provider/subscription/initialize-payment
 * 
 * Initialize payment to get authorization code for subscription
 * This is needed for first-time subscriptions before creating recurring subscription
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    const body = await request.json();

    const { plan_id, billing_period } = initializePaymentSchema.parse(body);

    // Get subscription plan
    const { data: plan, error: planError } = await supabase
      .from("subscription_plans")
      .select("id, name, currency, price_monthly, price_yearly, is_active, is_free, paystack_plan_code_monthly, paystack_plan_code_yearly")
      .eq("id", plan_id)
      .single();

    if (planError || !plan || (plan as any).is_active === false) {
      throw planError || new Error("Subscription plan not found");
    }

    if ((plan as any).is_free) {
      throw new Error("Payment initialization not needed for free plans");
    }

    const amount =
      billing_period === "yearly"
        ? Number((plan as any).price_yearly || 0)
        : Number((plan as any).price_monthly || 0);

    if (!amount || amount <= 0) {
      throw new Error("Invalid plan amount for selected billing period");
    }

    // Get or create Paystack customer
    const { data: userEmailRow } = await supabase
      .from("users")
      .select("email, first_name, last_name, phone")
      .eq("id", user.id)
      .single();

    const email = userEmailRow?.email || user.email;
    if (!email) throw new Error("User email is required for payment");

    let customerCode: string;
    try {
      // Try to fetch existing customer
      const customerResponse = await fetchCustomer(email);
      customerCode = customerResponse.data?.customer_code || email;
    } catch {
      // Create new customer if doesn't exist
      try {
        const customerResponse = await createCustomer({
          email,
          first_name: userEmailRow?.first_name || undefined,
          last_name: userEmailRow?.last_name || undefined,
          phone: userEmailRow?.phone || undefined,
        });
        customerCode = customerResponse.data?.customer_code || email;
      } catch (err: any) {
        throw new Error(`Failed to create Paystack customer: ${err.message}`);
      }
    }

    // Create order for tracking
    const { data: order, error: orderError } = await (supabase.from("provider_subscription_orders") as any)
      .insert({
        provider_id: providerId,
        plan_id,
        billing_period,
        amount,
        currency: (plan as any).currency || "ZAR",
        status: "pending",
      })
      .select("*")
      .single();

    if (orderError || !order) {
      throw orderError || new Error("Failed to create subscription order");
    }

    // Initialize Paystack transaction
    const reference = generateTransactionReference("provider_subscription_auth", order.id);
    const callbackUrl = `${process.env.NEXT_PUBLIC_APP_URL || ""}/provider/subscription?payment_success=true&order_id=${order.id}`;

    const paystackData = await initializePaystackTransaction({
      email,
      amountInSmallestUnit: convertToSmallestUnit(amount),
      currency: (plan as any).currency || "ZAR",
      reference,
      callback_url: callbackUrl,
      metadata: {
        provider_subscription_order_id: order.id,
        provider_id: providerId,
        plan_id,
        billing_period,
        customer_code: customerCode,
        kind: "subscription_authorization",
      },
    });

    const paymentUrl = paystackData?.data?.authorization_url || null;

    await (supabase.from("provider_subscription_orders") as any)
      .update({ 
        paystack_reference: reference, 
        updated_at: new Date().toISOString() 
      })
      .eq("id", order.id);

    return successResponse({ 
      order_id: order.id, 
      payment_url: paymentUrl,
      customer_code: customerCode,
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        new Error(error.issues.map(e => e.message).join(', ')),
        'Validation failed',
        'VALIDATION_ERROR',
        400
      );
    }
    return handleApiError(error, 'Failed to initialize subscription payment');
  }
}

import { NextRequest } from "next/server";
