import { NextRequest } from 'next/server';
import { getSupabaseServer } from '@/lib/supabase/server';
import { requireRoleInApi, successResponse, handleApiError, getProviderIdForUser, notFoundResponse } from '@/lib/supabase/api-helpers';
import { convertToSmallestUnit, generateTransactionReference } from "@/lib/payments/paystack";
import { initializePaystackTransaction } from "@/lib/payments/paystack-server";

/**
 * POST /api/provider/subscription/renew
 * 
 * Renew provider subscription
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    // Get current subscription
    const { data: subscription } = await supabase
      .from('provider_subscriptions')
      .select('*')
      .eq('provider_id', providerId)
      .single();

    if (!subscription) {
      return notFoundResponse('No subscription found');
    }

    const sub = subscription as any;
    const billingPeriod = (sub.billing_period || "monthly") as "monthly" | "yearly";

    const { data: plan, error: planError } = await supabase
      .from("subscription_plans")
      .select("id, name, currency, price_monthly, price_yearly, is_active")
      .eq("id", sub.plan_id)
      .single();
    if (planError || !plan || (plan as any).is_active === false) {
      throw planError || new Error("Subscription plan not found");
    }

    const amount =
      billingPeriod === "yearly"
        ? Number((plan as any).price_yearly || 0)
        : Number((plan as any).price_monthly || 0);
    if (!amount || amount <= 0) throw new Error("Invalid plan amount");

    const { data: order, error: orderError } = await (supabase.from("provider_subscription_orders") as any)
      .insert({
        provider_id: providerId,
        plan_id: sub.plan_id,
        billing_period: billingPeriod,
        amount,
        currency: (plan as any).currency || "ZAR",
        status: "pending",
      })
      .select("*")
      .single();
    if (orderError || !order) throw orderError || new Error("Failed to create subscription order");

    const { data: userEmailRow } = await supabase
      .from("users")
      .select("email")
      .eq("id", user.id)
      .single();
    const email = userEmailRow?.email || user.email;
    if (!email) throw new Error("User email is required for payment");

    const reference = generateTransactionReference("provider_subscription", order.id);
    const callbackUrl = `${process.env.NEXT_PUBLIC_APP_URL || ""}/checkout/success?payment_type=provider_subscription`;

    const paystackData = await initializePaystackTransaction({
      email,
      amountInSmallestUnit: convertToSmallestUnit(amount),
      currency: (plan as any).currency || "ZAR",
      reference,
      callback_url: callbackUrl,
      metadata: {
        provider_subscription_order_id: order.id,
        provider_id: providerId,
        plan_id: sub.plan_id,
        billing_period: billingPeriod,
      },
    });

    const paymentUrl = paystackData?.data?.authorization_url || null;

    await (supabase.from("provider_subscription_orders") as any)
      .update({ paystack_reference: reference, updated_at: new Date().toISOString() })
      .eq("id", order.id);

    return successResponse({ order_id: order.id, payment_url: paymentUrl });
  } catch (error) {
    return handleApiError(error, 'Failed to renew subscription');
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseServer } from '@/lib/supabase/server';
import { requireRoleInApi, successResponse, handleApiError, getProviderIdForUser } from '@/lib/supabase/api-helpers';

/**
 * GET /api/provider/subscription
 * 
 * Get provider's subscription information
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    const { data: subscription, error: subError } = await supabase
      .from('provider_subscriptions')
      .select('*, plan:subscription_plans(id, name, price_monthly, price_yearly, currency, features)')
      .eq('provider_id', providerId)
      .maybeSingle();

    if (subError) {
      throw subError;
    }

    if (!subscription) return successResponse(null);

    // Auto-mark expired if past expires_at (best-effort)
    const expiresAt = (subscription as any).expires_at ? new Date((subscription as any).expires_at) : null;
    if ((subscription as any).status === "active" && expiresAt && expiresAt < new Date()) {
      await (supabase.from("provider_subscriptions") as any)
        .update({ status: "expired", updated_at: new Date().toISOString() })
        .eq("id", (subscription as any).id);
      return successResponse({ ...(subscription as any), status: "expired" });
    }

    return successResponse(subscription as any);
  } catch (error) {
    return handleApiError(error, 'Failed to fetch subscription');
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseServer } from '@/lib/supabase/server';
import { requireRoleInApi, getProviderIdForUser, notFoundResponse, successResponse, handleApiError } from '@/lib/supabase/api-helpers';
import { z } from 'zod';
import { createCustomer, fetchCustomer, createSubscription } from '@/lib/payments/paystack-complete';
import { sendTemplateNotification } from "@/lib/notifications/onesignal";
import { createClient } from '@supabase/supabase-js';

const upgradeSubscriptionSchema = z.object({
  plan_id: z.string().uuid('Plan ID is required'),
  billing_period: z.enum(["monthly", "yearly"]).default("monthly"),
});

/**
 * POST /api/provider/subscription/upgrade
 * 
 * Upgrade provider subscription using Paystack native subscriptions
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) return notFoundResponse("Provider not found");
    const body = await request.json();

    const { plan_id, billing_period } = upgradeSubscriptionSchema.parse(body);

    // Get subscription plan
    const { data: plan, error: planError } = await supabase
      .from("subscription_plans")
      .select("id, name, currency, price_monthly, price_yearly, is_active, is_free, paystack_plan_code_monthly, paystack_plan_code_yearly")
      .eq("id", plan_id)
      .single();

    if (planError || !plan || (plan as any).is_active === false) {
      throw planError || new Error("Subscription plan not found");
    }

    // Handle free tier
    if ((plan as any).is_free) {
      // For free tier, just create subscription record without Paystack
      const now = new Date();
      const expiresAt = new Date(now);
      expiresAt.setFullYear(expiresAt.getFullYear() + 1); // Free tier valid for 1 year

      const { data: subscription, error: subError } = await (supabase.from("provider_subscriptions") as any)
        .upsert({
          provider_id: providerId,
          plan_id,
          status: "active",
          started_at: now.toISOString(),
          expires_at: expiresAt.toISOString(),
          billing_period: "yearly",
          auto_renew: false,
          updated_at: new Date().toISOString(),
        }, { onConflict: "provider_id" })
        .select()
        .single();

      if (subError) throw subError;

      // For free tier, send notification if upgrading from paid plan
      const supabaseAdmin = createClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.SUPABASE_SERVICE_ROLE_KEY!,
        {
          auth: {
            autoRefreshToken: false,
            persistSession: false,
          },
        }
      );

      const { data: providerData } = await supabaseAdmin
        .from("providers")
        .select("id, business_name, user_id")
        .eq("id", providerId)
        .single();

      // Get old subscription plan for comparison
      const { data: oldSubscription } = await supabaseAdmin
        .from("provider_subscriptions")
        .select("plan_id, subscription_plans:plan_id(name, price_monthly, price_yearly)")
        .eq("provider_id", providerId)
        .neq("id", (subscription as any).id)
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (providerData?.user_id && oldSubscription) {
        const oldPlan = (oldSubscription as any).subscription_plans;
        const oldPlanName = oldPlan?.name || "Previous Plan";
        const newPlanName = (plan as any).name;

        try {
          await sendTemplateNotification(
            "subscription_downgraded", // Free tier is typically a downgrade
            [providerData.user_id],
            {
              business_name: providerData.business_name || "Provider",
              plan_name: newPlanName,
              old_plan_name: oldPlanName,
              new_amount: "Free",
              billing_period: "yearly",
              effective_date: new Date().toLocaleDateString(),
              app_url: process.env.NEXT_PUBLIC_APP_URL || "https://beautonomi.com",
              year: new Date().getFullYear().toString(),
            },
            ["push", "email", "sms"]
          );
        } catch (notifError) {
          console.error("Error sending free tier notification:", notifError);
        }
      }

      return successResponse({ subscription_id: (subscription as any).id, is_free: true });
    }

    // For paid plans, use Paystack subscriptions
    const paystackPlanCode = billing_period === "yearly" 
      ? (plan as any).paystack_plan_code_yearly 
      : (plan as any).paystack_plan_code_monthly;

    if (!paystackPlanCode) {
      throw new Error(`Paystack plan code not found for ${billing_period} billing period`);
    }

    // Get or create Paystack customer
    const { data: userEmailRow } = await supabase
      .from("users")
      .select("email, first_name, last_name, phone")
      .eq("id", user.id)
      .single();

    const email = userEmailRow?.email || user.email;
    if (!email) throw new Error("User email is required for payment");

    let customerCode: string;
    try {
      // Try to fetch existing customer
      const customerResponse = await fetchCustomer(email);
      customerCode = customerResponse.data?.customer_code || email;
    } catch {
      // Create new customer if doesn't exist
      try {
        const customerResponse = await createCustomer({
          email,
          first_name: userEmailRow?.first_name || undefined,
          last_name: userEmailRow?.last_name || undefined,
          phone: userEmailRow?.phone || undefined,
        });
        customerCode = customerResponse.data?.customer_code || email;
      } catch (err: any) {
        throw new Error(`Failed to create Paystack customer: ${err.message}`);
      }
    }

    // Create Paystack subscription
    // Note: This requires an authorization code from a previous transaction
    // For first-time subscriptions, we'll need to initialize a transaction first
    // to get the authorization code, then create the subscription

    // Check if provider has existing subscription with authorization
    // Also get old plan details for notification
    const { data: existingSub } = await supabase
      .from("provider_subscriptions")
      .select(`
        paystack_authorization_code, 
        paystack_customer_code,
        plan_id,
        subscription_plans:plan_id(name, price_monthly, price_yearly)
      `)
      .eq("provider_id", providerId)
      .eq("status", "active")
      .single();

    const authorizationCode = (existingSub as any)?.paystack_authorization_code;
    const oldPlan = (existingSub as any)?.subscription_plans;

    if (!authorizationCode) {
      // No authorization code - need to initialize payment first
      // Return a flag indicating payment initialization is needed
      return successResponse({ 
        requires_payment: true,
        customer_code: customerCode,
        plan_code: paystackPlanCode,
        message: "Payment authorization required. Please complete a payment first."
      });
    }

    // Create subscription with authorization code
    try {
      const subscriptionResponse = await createSubscription({
        customer: customerCode,
        plan: paystackPlanCode,
        authorization: authorizationCode,
      });

      const paystackSubscription = subscriptionResponse.data;

      // Update or create subscription record
      const now = new Date();
      const { data: subscription, error: subError } = await (supabase.from("provider_subscriptions") as any)
        .upsert({
          provider_id: providerId,
          plan_id,
          status: "active",
          started_at: now.toISOString(),
          billing_period,
          auto_renew: true,
          paystack_subscription_code: paystackSubscription?.subscription_code,
          paystack_authorization_code: authorizationCode,
          paystack_customer_code: customerCode,
          next_payment_date: paystackSubscription?.next_payment_date,
          updated_at: new Date().toISOString(),
        }, { onConflict: "provider_id" })
        .select()
        .single();

      if (subError) throw subError;

      // Get provider and plan details for notification
      const supabaseAdmin = createClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.SUPABASE_SERVICE_ROLE_KEY!,
        {
          auth: {
            autoRefreshToken: false,
            persistSession: false,
          },
        }
      );

      const { data: providerData } = await supabaseAdmin
        .from("providers")
        .select("id, business_name, user_id")
        .eq("id", providerId)
        .single();

      const oldPlanName = oldPlan?.name || "Previous Plan";
      const newPlanName = (plan as any).name;
      const newAmount = billing_period === "yearly" 
        ? (plan as any).price_yearly 
        : (plan as any).price_monthly;
      const nextPaymentDate = paystackSubscription?.next_payment_date 
        ? new Date(paystackSubscription.next_payment_date).toLocaleDateString()
        : "N/A";

      // Determine if upgrade or downgrade by comparing plan prices
      const oldPrice = oldPlan 
        ? (billing_period === "yearly" ? oldPlan.price_yearly : oldPlan.price_monthly)
        : null;

      const isUpgrade = !oldPrice || (newAmount && oldPrice && newAmount > oldPrice);
      const templateKey = isUpgrade ? "subscription_upgraded" : "subscription_downgraded";

      // Send notification
      if (providerData?.user_id) {
        try {
          await sendTemplateNotification(
            templateKey,
            [providerData.user_id],
            {
              business_name: providerData.business_name || "Provider",
              plan_name: newPlanName,
              old_plan_name: oldPlanName,
              new_amount: newAmount ? `${(plan as any).currency || "ZAR"} ${newAmount.toLocaleString()}` : "N/A",
              billing_period: billing_period,
              next_payment_date: nextPaymentDate,
              effective_date: new Date().toLocaleDateString(),
              app_url: process.env.NEXT_PUBLIC_APP_URL || "https://beautonomi.com",
              year: new Date().getFullYear().toString(),
            },
            ["push", "email", "sms"]
          );
        } catch (notifError) {
          console.error("Error sending subscription notification:", notifError);
          // Don't fail the request if notification fails
        }
      }

      return successResponse({ 
        subscription_id: (subscription as any).id,
        paystack_subscription_code: paystackSubscription?.subscription_code,
      });
    } catch (err: any) {
      console.error("Paystack subscription creation error:", err);
      throw new Error(`Failed to create Paystack subscription: ${err.message}`);
    }
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        new Error(error.issues.map(e => e.message).join(', ')),
        'Validation failed',
        'VALIDATION_ERROR',
        400
      );
    }
    return handleApiError(error, 'Failed to upgrade subscription');
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { getPaystackSecretKey } from "@/lib/payments/paystack-server";
import { z } from "zod";
import { createClient } from "@supabase/supabase-js";

const createSubscriptionSchema = z.object({
  plan_id: z.string().uuid("Invalid plan ID"),
  billing_period: z.enum(["monthly", "yearly"]),
});/**
 * POST /api/provider/subscriptions/create
 * 
 * Create a Paystack subscription for a provider
 * Following Paystack subscription API: https://paystack.com/docs/payments/subscriptions/
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'superadmin'], request);
    if (!user) {
      return errorResponse("Authentication required", "UNAUTHORIZED", 401);
    }

    const _supabase = await getSupabaseServer(request);
    const body = await request.json();

    // Validate input
    const validationResult = createSubscriptionSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Invalid input data",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    const { plan_id, billing_period } = validationResult.data;

    // Use admin client to bypass RLS
    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);

    if (!providerId) return notFoundResponse("Provider not found");


    // Get provider
    const { data: provider, error: providerError } = await supabaseAdmin
      .from("providers")
      .select("id, user_id, business_name, email, phone")
      .eq("user_id", user.id)
      .single();

    if (providerError || !provider) {
      return errorResponse("Provider not found", "NOT_FOUND", 404);
    }

    // Get pricing plan
    const { data: pricingPlan, error: planError } = await supabaseAdmin
      .from("pricing_plans")
      .select("id, name, price, paystack_plan_code_monthly, paystack_plan_code_yearly, subscription_plan_id")
      .eq("id", plan_id)
      .eq("is_active", true)
      .single();

    if (planError || !pricingPlan) {
      return errorResponse("Pricing plan not found or inactive", "NOT_FOUND", 404);
    }

    // Get Paystack plan code based on billing period
    const paystackPlanCode = billing_period === "monthly" 
      ? (pricingPlan as any).paystack_plan_code_monthly
      : (pricingPlan as any).paystack_plan_code_yearly;

    if (!paystackPlanCode) {
      return errorResponse(
        `Paystack plan code not configured for ${billing_period} billing`,
        "CONFIGURATION_ERROR",
        400
      );
    }

    // Get user email for Paystack customer
    const { data: userData } = await supabaseAdmin
      .from("users")
      .select("email, full_name")
      .eq("id", user.id)
      .single();

    const customerEmail = userData?.email || (provider as any).email;
    if (!customerEmail) {
      return errorResponse("User email is required for subscription", "VALIDATION_ERROR", 400);
    }

    // Check if provider already has an active subscription
    const { data: existingSubscription } = await supabaseAdmin
      .from("provider_subscriptions")
      .select("id, status")
      .eq("provider_id", providerId)
      .in("status", ["active", "trialing"])
      .maybeSingle();

    if (existingSubscription) {
      return errorResponse(
        "Provider already has an active subscription",
        "CONFLICT",
        409
      );
    }

    // Get Paystack secret key
    const secretKey = await getPaystackSecretKey();

    // Create Paystack customer if doesn't exist
    let paystackCustomerCode: string;
    try {
      // Check if customer exists
      const customerResponse = await fetch(
        `https://api.paystack.co/customer?email=${encodeURIComponent(customerEmail)}`,
        {
          method: "GET",
          headers: {
            Authorization: `Bearer ${secretKey}`,
            "Content-Type": "application/json",
          },
        }
      );

      const customerData = await customerResponse.json();
      
      if (customerData.status && customerData.data && customerData.data.length > 0) {
        // Customer exists
        paystackCustomerCode = customerData.data[0].customer_code;
      } else {
        // Create new customer
        const createCustomerResponse = await fetch("https://api.paystack.co/customer", {
          method: "POST",
          headers: {
            Authorization: `Bearer ${secretKey}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            email: customerEmail,
            first_name: userData?.full_name?.split(" ")[0] || "",
            last_name: userData?.full_name?.split(" ").slice(1).join(" ") || "",
            phone: (provider as any).phone || "",
          }),
        });

        const createCustomerData = await createCustomerResponse.json();
        if (!createCustomerResponse.ok || !createCustomerData.status) {
          throw new Error(createCustomerData.message || "Failed to create Paystack customer");
        }

        paystackCustomerCode = createCustomerData.data.customer_code;
      }
    } catch (error: any) {
      console.error("Error creating/fetching Paystack customer:", error);
      return errorResponse(
        `Failed to create Paystack customer: ${error.message}`,
        "PAYSTACK_ERROR",
        500
      );
    }

    // Create Paystack subscription
    // Note: For subscriptions, we need to initialize a transaction first to get authorization
    // Then create the subscription with that authorization
    // This is a simplified version - in production, you'd handle the payment authorization flow first
    try {
      const subscriptionResponse = await fetch("https://api.paystack.co/subscription", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${secretKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          customer: paystackCustomerCode,
          plan: paystackPlanCode,
        }),
      });

      const subscriptionData = await subscriptionResponse.json();
      
      if (!subscriptionResponse.ok || !subscriptionData.status) {
        throw new Error(subscriptionData.message || "Failed to create Paystack subscription");
      }

      const paystackSubscription = subscriptionData.data;

      // provider_subscriptions.plan_id must reference subscription_plans(id), not pricing_plans
      const subscriptionPlanId = (pricingPlan as any).subscription_plan_id;
      if (!subscriptionPlanId) {
        return errorResponse(
          "This pricing plan is not linked to a subscription plan. Link it in Admin ΓåÆ Pricing Plans.",
          "CONFIGURATION_ERROR",
          400
        );
      }

      // Create provider_subscription record
      const { data: providerSubscription, error: subError } = await (supabaseAdmin
        .from("provider_subscriptions") as any)
        .insert({
          provider_id: providerId,
          plan_id: subscriptionPlanId,
          status: paystackSubscription.status === "active" ? "active" : "trialing",
          paystack_subscription_code: paystackSubscription.subscription_code,
          paystack_customer_code: paystackCustomerCode,
          paystack_authorization_code: paystackSubscription.authorization?.authorization_code || null,
          billing_period: billing_period,
          auto_renew: true,
          next_payment_date: paystackSubscription.next_payment_date 
            ? new Date(paystackSubscription.next_payment_date).toISOString() 
            : null,
          started_at: paystackSubscription.createdAt 
            ? new Date(paystackSubscription.createdAt).toISOString() 
            : new Date().toISOString(),
          expires_at: billing_period === "monthly"
            ? new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString() // 30 days
            : new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString(), // 365 days
        })
        .select()
        .single();

      if (subError || !providerSubscription) {
        console.error("Error creating provider subscription:", subError);
        // Note: Paystack subscription was created, but DB record failed
        // In production, you might want to handle this differently
        return errorResponse(
          "Subscription created in Paystack but failed to save locally",
          "DATABASE_ERROR",
          500
        );
      }

      return successResponse({
        subscription: providerSubscription,
        paystack_subscription_code: paystackSubscription.subscription_code,
        authorization_url: paystackSubscription.authorization?.authorization_url || null,
        message: "Subscription created successfully",
      });
    } catch (error: any) {
      console.error("Error creating Paystack subscription:", error);
      return errorResponse(
        `Failed to create Paystack subscription: ${error.message}`,
        "PAYSTACK_ERROR",
        500
      );
    }
  } catch (error) {
    return handleApiError(error, "Failed to create subscription");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  handleApiError,
  getProviderIdForUser,
  notFoundResponse,
} from "@/lib/supabase/api-helpers";

/**
 * GET /api/provider/team
 * Alias for /api/provider/staff ΓÇö returns team members for the current provider.
 * The mobile app calls this endpoint; it queries the same `provider_staff` table.
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(
      ["provider_owner", "provider_staff", "superadmin"],
      request
    );

    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const { searchParams } = new URL(request.url);
    const locationId = searchParams.get("location_id");

    // If location_id provided, get staff assigned to that location first
    let staffIds: string[] | null = null;
    if (locationId) {
      const { data: assignments, error: assignmentError } = await supabase
        .from("provider_staff_locations")
        .select("staff_id")
        .eq("location_id", locationId);

      if (assignmentError) {
        throw assignmentError;
      }

      staffIds = assignments?.map((a) => a.staff_id) || [];

      if (staffIds.length === 0) {
        return successResponse([]);
      }
    }

    let query = supabase
      .from("provider_staff")
      .select(
        `
        id,
        user_id,
        provider_id,
        name,
        email,
        phone,
        avatar_url,
        role,
        is_active,
        commission_percentage,
        bio,
        mobile_ready
      `
      )
      .eq("provider_id", providerId);

    if (locationId && staffIds && staffIds.length > 0) {
      query = query.in("id", staffIds);
    }

    const { data: staff, error } = await query.order("created_at", {
      ascending: false,
    });

    if (error) {
      throw error;
    }

    // Map database roles to API format
    const transformedStaff = (staff || []).map((member: any) => {
      const apiRole =
        member.role === "owner"
          ? "provider_owner"
          : member.role === "manager"
            ? "provider_manager"
            : "provider_staff";

      return {
        id: member.id,
        user_id: member.user_id,
        provider_id: member.provider_id,
        name: member.name || "Staff Member",
        email: member.email || "",
        phone: member.phone || null,
        avatar_url: member.avatar_url || null,
        bio: member.bio || null,
        role: apiRole,
        is_active: member.is_active ?? true,
        commission_percentage: member.commission_percentage ?? 0,
        mobileReady: member.mobile_ready ?? false,
      };
    });

    return successResponse(transformedStaff);
  } catch (error) {
    return handleApiError(error, "Failed to fetch team members");
  }
}

