import { NextRequest } from "next/server";
import {  requireRoleInApi, getProviderIdForUser, successResponse, notFoundResponse, handleApiError  } from "@/lib/supabase/api-helpers";
import { createClient } from "@supabase/supabase-js";
import { subDays, subMonths, startOfDay, startOfWeek, startOfMonth } from "date-fns";

export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff", "superadmin"], request);

    const supabaseAdmin = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      { auth: { autoRefreshToken: false, persistSession: false } },
    );

    const providerId = await getProviderIdForUser(user.id, supabaseAdmin);
    if (!providerId) return notFoundResponse("Provider not found");
    const sp = request.nextUrl.searchParams;
    const period = sp.get("period") || "month";
    const limit = Math.min(parseInt(sp.get("limit") || "50", 10), 200);

    const locationId = sp.get("location_id") || null;
    let fromDate: Date;
    switch (period) {
      case "today": fromDate = startOfDay(new Date()); break;
      case "week": fromDate = startOfWeek(new Date(), { weekStartsOn: 1 }); break;
      case "month": fromDate = startOfMonth(new Date()); break;
      case "3months": fromDate = subMonths(new Date(), 3); break;
      case "year": fromDate = subMonths(new Date(), 12); break;
      case "all": fromDate = new Date(2000, 0, 1); break;
      default: fromDate = subDays(new Date(), 30);
    }

    const query = supabaseAdmin
      .from("finance_transactions")
      .select("id, transaction_type, amount, net, created_at, booking_id, metadata")
      .eq("provider_id", providerId)
      .gte("created_at", fromDate.toISOString())
      .order("created_at", { ascending: false })
      .limit(limit);

    const { data: txnsRaw } = await query;
    let txns = txnsRaw ?? [];

    // Filter by location_id when provided (match portal finance behaviour)
    if (locationId && txns.length > 0) {
      const bookingIds = [...new Set(txns.filter((t: any) => t.booking_id).map((t: any) => t.booking_id))];
      if (bookingIds.length > 0) {
        const { data: bookings } = await supabaseAdmin
          .from("bookings")
          .select("id")
          .in("id", bookingIds)
          .eq("location_id", locationId);
        const allowedIds = new Set((bookings ?? []).map((b: any) => b.id));
        txns = txns.filter((t: any) => !t.booking_id || allowedIds.has(t.booking_id));
      } else {
        // No booking-linked transactions in this set; keep only non-booking (payouts, fees)
        txns = txns.filter((t: any) => !t.booking_id);
      }
    }

    const typeMap: Record<string, string> = {
      provider_earnings: "payment",
      payout: "payout",
      platform_fee: "fee",
      travel_fee: "payment",
      tip: "tip",
      refund: "refund",
    };

    const transactions = txns.map((t: any) => {
      const net = Number(t.net ?? t.amount ?? 0);
      let type = typeMap[t.transaction_type] || "payment";
      if (t.transaction_type === "provider_earnings" && net < 0) type = "refund";

      return {
        id: t.id,
        type,
        amount: Math.abs(net),
        description: t.transaction_type === "payout"
          ? "Payout to bank"
          : t.transaction_type === "platform_fee"
            ? "Platform fee"
            : net < 0 ? "Refund" : "Service payment",
        status: "completed",
        created_at: t.created_at,
        client_name: null,
      };
    });

    return successResponse(transactions);
  } catch (error) {
    console.error("Error fetching transactions:", error);
    return handleApiError(error, "Failed to load transactions");
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseServer } from '@/lib/supabase/server';
import { requireRoleInApi, successResponse, handleApiError, getProviderIdForUser } from '@/lib/supabase/api-helpers';
import { requirePermission } from "@/lib/auth/requirePermission";
import { z } from 'zod';

const travelFeesSchema = z.object({
  enabled: z.boolean().optional(),
  rate_per_km: z.number().min(0).optional(),
  minimum_fee: z.number().min(0).optional(),
  maximum_fee: z.number().min(0).nullable().optional(),
  currency: z.string().optional(),
  use_platform_default: z.boolean().optional(),
});

/**
 * GET /api/provider/travel-fees
 * 
 * Get provider's travel fee settings
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const { searchParams } = new URL(request.url);
    const providerIdParam = searchParams.get("provider_id"); // For superadmin to view specific provider

    // For superadmin, allow viewing any provider's settings
    let providerId: string | null = null;
    if (user.role === "superadmin" && providerIdParam) {
      providerId = providerIdParam;
    } else {
      // For providers, get their own provider ID
      providerId = await getProviderIdForUser(user.id, supabase);
      if (!providerId) {
        return handleApiError(new Error("Provider not found"), "Provider account required", 403);
      }
    }

    let query = supabase
      .from('provider_travel_fee_settings')
      .select('*');

    if (providerId) {
      query = query.eq('provider_id', providerId);
    }

    const { data: travelFeeSettings, error } = await query.single();

    // Return default if not found
    if (error && error.code === 'PGRST116') {
      return successResponse({
        enabled: true,
        rate_per_km: null,
        minimum_fee: null,
        maximum_fee: null,
        currency: 'ZAR',
        use_platform_default: true,
      });
    }

    if (error) {
      throw error;
    }

    return successResponse(travelFeeSettings);
  } catch (error) {
    return handleApiError(error, 'Failed to fetch travel fee settings');
  }
}

/**
 * PATCH /api/provider/travel-fees
 * 
 * Update provider's travel fee settings
 */
export async function PATCH(request: NextRequest) {
  try {
    // Check permission to edit settings
    const permissionCheck = await requirePermission('edit_settings', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    // For superadmin, allow updating any provider's settings via provider_id in body
    let providerId: string | null = null;
    if (user.role === "superadmin" && body.provider_id) {
      providerId = body.provider_id;
      delete body.provider_id; // Remove from body before validation
    } else {
      providerId = await getProviderIdForUser(user.id, supabase);
      if (!providerId) {
        return handleApiError(new Error("Provider not found"), "Provider account required", 403);
      }
    }

    const validatedData = travelFeesSchema.parse(body);

    // Get platform settings to validate against limits
    const { data: platformSettings } = await supabase
      .from('platform_settings')
      .select('settings')
      .eq('is_active', true)
      .single();

    const travelFees = platformSettings?.settings?.travel_fees || {};

    // Validate against platform limits if provider is setting custom rates
    if (!validatedData.use_platform_default && validatedData.rate_per_km !== undefined) {
      const minRate = travelFees.provider_min_rate_per_km || 0;
      const maxRate = travelFees.provider_max_rate_per_km || 50;
      if (validatedData.rate_per_km < minRate || validatedData.rate_per_km > maxRate) {
        return handleApiError(
          new Error(`Rate per km must be between ${minRate} and ${maxRate}`),
          'Validation failed',
          'VALIDATION_ERROR',
          400
        );
      }
    }

    if (!validatedData.use_platform_default && validatedData.minimum_fee !== undefined) {
      const minFee = travelFees.provider_min_minimum_fee || 0;
      const maxFee = travelFees.provider_max_minimum_fee || 100;
      if (validatedData.minimum_fee < minFee || validatedData.minimum_fee > maxFee) {
        return handleApiError(
          new Error(`Minimum fee must be between ${minFee} and ${maxFee}`),
          'Validation failed',
          'VALIDATION_ERROR',
          400
        );
      }
    }

    const { data: settings, error } = await supabase
      .from('provider_travel_fee_settings')
      .upsert(
        {
          provider_id: providerId,
          enabled: validatedData.enabled !== false,
          rate_per_km: validatedData.rate_per_km,
          minimum_fee: validatedData.minimum_fee,
          maximum_fee: validatedData.maximum_fee ?? null,
          currency: validatedData.currency || 'ZAR',
          use_platform_default: validatedData.use_platform_default !== false,
          updated_at: new Date().toISOString(),
        },
        {
          onConflict: 'provider_id',
        }
      )
      .select()
      .single();

    if (error) {
      throw error;
    }

    return successResponse(settings);
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        new Error(error.issues.map((e: any) => e.message).join(', ')),
        'Validation failed',
        'VALIDATION_ERROR',
        400
      );
    }
    return handleApiError(error, 'Failed to update travel fee settings');
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError, notFoundResponse } from "@/lib/supabase/api-helpers";

/**
 * GET /api/provider/twilio-integration/balance
 * 
 * Get Twilio account balance (remaining SMS credits/messages)
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Get Twilio integration
    const { data: integration, error: integrationError } = await supabase
      .from("provider_twilio_integrations")
      .select("*")
      .eq("provider_id", providerId)
      .maybeSingle();

    if (integrationError) {
      throw integrationError;
    }

    if (!integration || !integration.account_sid || !integration.auth_token) {
      return successResponse({
        balance: null,
        currency: null,
        hasIntegration: false,
        message: "Twilio integration not configured",
      });
    }

    // Fetch balance from Twilio API
    try {
      const accountSid = integration.account_sid;
      const authToken = integration.auth_token;
      
      const response = await fetch(
        `https://api.twilio.com/2010-04-01/Accounts/${accountSid}.json`,
        {
          method: "GET",
          headers: {
            "Authorization": `Basic ${Buffer.from(`${accountSid}:${authToken}`).toString("base64")}`,
          },
        }
      );

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || `Twilio API error: ${response.status}`);
      }

      const accountData = await response.json();
      
      // Twilio returns balance as a string (e.g., "10.50")
      const balance = parseFloat(accountData.balance || "0");
      const currency = accountData.currency || "USD";

      // Estimate messages remaining (assuming average SMS cost)
      // This is approximate - actual cost varies by country/carrier
      const estimatedCostPerSMS = 0.0075; // ~$0.0075 per SMS (varies by region)
      const estimatedMessagesRemaining = Math.floor(balance / estimatedCostPerSMS);

      return successResponse({
        balance,
        currency,
        estimatedMessagesRemaining,
        hasIntegration: true,
        accountStatus: accountData.status,
      });
    } catch (twilioError: any) {
      // If Twilio API fails, return error but don't fail the request
      console.error("Error fetching Twilio balance:", twilioError);
      return successResponse({
        balance: null,
        currency: null,
        hasIntegration: true,
        error: twilioError.message || "Failed to fetch balance from Twilio",
        message: "Unable to fetch balance. Please check your Twilio credentials.",
      });
    }
  } catch (error) {
    return handleApiError(error, "Failed to fetch Twilio balance");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError, errorResponse, notFoundResponse } from "@/lib/supabase/api-helpers";
import { checkMarketingFeatureAccess } from "@/lib/subscriptions/feature-access";
import { z } from "zod";

const putSchema = z.object({
  account_sid: z.string().min(1, "Account SID is required"),
  auth_token: z.string().min(1, "Auth token is required"),
  sms_from_number: z.string().optional(),
  whatsapp_from_number: z.string().optional(),
  is_sms_enabled: z.boolean().optional().default(false),
  is_whatsapp_enabled: z.boolean().optional().default(false),
});

/**
 * GET /api/provider/twilio-integration
 * Get provider's Twilio integration settings
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);

    // For superadmin, allow viewing any provider's integration
    let providerId: string | null = null;
    if (user.role === "superadmin") {
      const { searchParams } = new URL(request.url);
      const providerIdParam = searchParams.get("provider_id");
      if (providerIdParam) {
        providerId = providerIdParam;
      } else {
        return errorResponse("provider_id is required for superadmin", "VALIDATION_ERROR", 400);
      }
    } else {
      providerId = await getProviderIdForUser(user.id, supabase);
      if (!providerId) {
        return notFoundResponse("Provider not found");
      }
    }

    const { data: integration, error } = await supabase
      .from("provider_twilio_integrations")
      .select("*")
      .eq("provider_id", providerId)
      .maybeSingle();

    if (error) {
      throw error;
    }

    // Mask sensitive data in response
    if (integration) {
      integration.account_sid = integration.account_sid ? "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" : "";
      integration.auth_token = integration.auth_token ? "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" : "";
    }

    return successResponse(integration || null);
  } catch (error: any) {
    console.error("Error fetching Twilio integration:", error);
    return handleApiError(error, "Failed to fetch Twilio integration");
  }
}

/**
 * PUT /api/provider/twilio-integration
 * Create or update provider's Twilio integration
 */
export async function PUT(request: NextRequest) {
  try {
    // Only provider owners and superadmins can update integrations
    const { user } = await requireRoleInApi(['provider_owner', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    // For superadmin, allow updating any provider's integration
    let providerId: string | null = null;
    if (user.role === "superadmin") {
      const { searchParams } = new URL(request.url);
      const providerIdParam = searchParams.get("provider_id");
      if (providerIdParam) {
        providerId = providerIdParam;
      } else {
        return errorResponse("provider_id is required for superadmin", "VALIDATION_ERROR", 400);
      }
    } else {
      providerId = await getProviderIdForUser(user.id, supabase);
      if (!providerId) {
        return notFoundResponse("Provider not found");
      }
    }

    // Check subscription allows custom integrations (skip for superadmin)
    if (user.role !== "superadmin") {
      const marketingAccess = await checkMarketingFeatureAccess(providerId);
      if (!marketingAccess.customIntegrations) {
        return errorResponse(
          "Marketing integrations require a subscription upgrade. Please upgrade your plan to use custom SMS/WhatsApp integrations.",
          "SUBSCRIPTION_REQUIRED",
          403
        );
      }
    }

    // Validate input
    const validated = putSchema.parse(body);
    const { 
      account_sid, 
      auth_token, 
      sms_from_number, 
      whatsapp_from_number,
      is_sms_enabled,
      is_whatsapp_enabled 
    } = validated;

    // Validate Twilio Account SID format (starts with AC)
    if (!account_sid.startsWith("AC")) {
      return errorResponse("Invalid Twilio Account SID format. Should start with 'AC'", "VALIDATION_ERROR", 400);
    }

    // Validate phone number formats if provided
    const phoneRegex = /^\+?[1-9]\d{1,14}$/;
    if (sms_from_number) {
      const cleanNumber = sms_from_number.replace(/\D/g, "");
      if (!phoneRegex.test(cleanNumber)) {
        return errorResponse("Invalid SMS from number format. Use E.164 format (e.g., +1234567890)", "VALIDATION_ERROR", 400);
      }
    }

    if (whatsapp_from_number) {
      const cleanNumber = whatsapp_from_number.replace("whatsapp:", "").replace(/\D/g, "");
      if (!phoneRegex.test(cleanNumber)) {
        return errorResponse("Invalid WhatsApp from number format. Use E.164 format (e.g., +1234567890)", "VALIDATION_ERROR", 400);
      }
    }

    // Check if integration exists
    const { data: existing } = await supabase
      .from("provider_twilio_integrations")
      .select("id, account_sid, auth_token, connected_date")
      .eq("provider_id", providerId)
      .maybeSingle();

    const integrationData: any = {
      provider_id: providerId,
      is_sms_enabled: is_sms_enabled !== undefined ? is_sms_enabled : false,
      is_whatsapp_enabled: is_whatsapp_enabled !== undefined ? is_whatsapp_enabled : false,
    };

    // Only update credentials if they're not masked
    if (account_sid && account_sid !== "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó") {
      integrationData.account_sid = account_sid;
    } else if (existing?.account_sid) {
      // Keep existing if masked value provided
      integrationData.account_sid = existing.account_sid;
    } else {
      return errorResponse("Account SID is required", "VALIDATION_ERROR", 400);
    }

    if (auth_token && auth_token !== "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó") {
      integrationData.auth_token = auth_token;
    } else if (existing?.auth_token) {
      // Keep existing if masked value provided
      integrationData.auth_token = existing.auth_token;
    } else {
      return errorResponse("Auth token is required", "VALIDATION_ERROR", 400);
    }

    if (sms_from_number) {
      integrationData.sms_from_number = sms_from_number;
    }

    if (whatsapp_from_number) {
      // Ensure WhatsApp number is in correct format
      const formatted = whatsapp_from_number.startsWith("whatsapp:") 
        ? whatsapp_from_number 
        : `whatsapp:${whatsapp_from_number}`;
      integrationData.whatsapp_from_number = formatted;
    }

    if ((is_sms_enabled || is_whatsapp_enabled) && !existing?.connected_date) {
      integrationData.connected_date = new Date().toISOString();
    }

    let result;
    if (existing) {
      // Update existing
      const { data, error } = await supabase
        .from("provider_twilio_integrations")
        .update(integrationData)
        .eq("id", existing.id)
        .select()
        .single();

      if (error) throw error;
      result = data;
    } else {
      // Create new
      const { data, error } = await supabase
        .from("provider_twilio_integrations")
        .insert(integrationData)
        .select()
        .single();

      if (error) throw error;
      result = data;
    }

    // Mask sensitive data in response
    if (result) {
      result.account_sid = result.account_sid ? "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" : "";
      result.auth_token = result.auth_token ? "ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" : "";
    }

    return successResponse(result);
  } catch (error: any) {
    if (error instanceof z.ZodError) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        error.issues
      );
    }
    console.error("Error saving Twilio integration:", error);
    return handleApiError(error, "Failed to save Twilio integration");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRoleInApi, getProviderIdForUser, successResponse, handleApiError, errorResponse, notFoundResponse } from "@/lib/supabase/api-helpers";
import { z } from "zod";

const testSchema = z.object({
  test_phone: z.string().min(1, "Phone number is required"),
  channel: z.enum(["sms", "whatsapp"] as const, "Channel must be 'sms' or 'whatsapp'"),
});

/**
 * POST /api/provider/twilio-integration/test
 * Test the Twilio integration by sending a test SMS or WhatsApp
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(['provider_owner', 'provider_staff', 'superadmin'], request);
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    // Validate input
    const validated = testSchema.parse(body);
    const { test_phone, channel } = validated;

    // Validate phone number format
    const phoneRegex = /^\+?[1-9]\d{1,14}$/;
    const cleanPhone = test_phone.replace(/\D/g, "");
    if (!phoneRegex.test(cleanPhone)) {
      return errorResponse("Invalid phone number format. Use E.164 format (e.g., +1234567890)", "VALIDATION_ERROR", 400);
    }

    // For superadmin, allow testing any provider's integration
    let providerId: string | null = null;
    if (user.role === "superadmin") {
      const { searchParams } = new URL(request.url);
      const providerIdParam = searchParams.get("provider_id");
      if (providerIdParam) {
        providerId = providerIdParam;
      } else {
        return errorResponse("provider_id is required for superadmin", "VALIDATION_ERROR", 400);
      }
    } else {
      providerId = await getProviderIdForUser(user.id, supabase);
      if (!providerId) {
        return notFoundResponse("Provider not found");
      }
    }

    // Get integration
    const { data: integration, error: fetchError } = await supabase
      .from("provider_twilio_integrations")
      .select("*")
      .eq("provider_id", providerId)
      .single();

    if (fetchError || !integration) {
      return errorResponse("Twilio integration not configured", "NOT_FOUND", 404);
    }

    if (channel === "sms" && (!integration.is_sms_enabled || !integration.sms_from_number)) {
      return errorResponse("SMS is not enabled or configured", "VALIDATION_ERROR", 400);
    }

    if (channel === "whatsapp" && (!integration.is_whatsapp_enabled || !integration.whatsapp_from_number)) {
      return errorResponse("WhatsApp is not enabled or configured", "VALIDATION_ERROR", 400);
    }

    // Import unified marketing service
    const { sendMessage } = await import("@/lib/marketing/unified-service");

    // Send test message
    const result = await sendMessage(
      providerId,
      channel,
      {
        to: test_phone,
        content: `Test ${channel.toUpperCase()} from Beautonomi. If you received this, your integration is working correctly!`,
      }
    );

    // Update test status
    const updateData: any = {
      last_tested_at: new Date().toISOString(),
    };

    if (channel === "sms") {
      updateData.sms_test_status = result.success ? "success" : "failed";
      updateData.sms_test_error = result.error || null;
    } else {
      updateData.whatsapp_test_status = result.success ? "success" : "failed";
      updateData.whatsapp_test_error = result.error || null;
    }

    await supabase
      .from("provider_twilio_integrations")
      .update(updateData)
      .eq("id", integration.id);

    if (result.success) {
      return successResponse({ message: `Test ${channel.toUpperCase()} sent successfully` });
    } else {
      return errorResponse(result.error || `Failed to send test ${channel}`, "TEST_FAILED", 400);
    }
  } catch (error: any) {
    if (error instanceof z.ZodError) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        error.issues
      );
    }
    console.error("Error testing Twilio integration:", error);
    return handleApiError(error, "Failed to test Twilio integration");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireAuthInApi,
  successResponse,
  handleApiError,
  getProviderIdForUser,
} from "@/lib/supabase/api-helpers";

/**
 * POST /api/provider/upgrade-to-salon
 * Upgrade a freelancer provider to salon status
 */
export async function POST(request: NextRequest) {
  try {
    const { user } = await requireAuthInApi(request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return handleApiError(
        new Error("Provider not found"),
        "Provider account required",
        403
      );
    }

    // Check current business type and subscription
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("business_type, subscription_plan_id, capabilities")
      .eq("id", providerId)
      .single();

    if (providerError) {
      throw providerError;
    }

    if (!provider) {
      return handleApiError(
        new Error("Provider not found"),
        "Provider account not found",
        404
      );
    }

    // Validate current business type
    if (provider.business_type !== "freelancer") {
      return handleApiError(
        new Error("Already a salon"),
        provider.business_type === "salon"
          ? "Provider is already a salon"
          : "Invalid business type for upgrade",
        400
      );
    }

    // Check if already upgraded (via capabilities)
    if (
      provider.capabilities &&
      typeof provider.capabilities === "object" &&
      (provider.capabilities as any).upgraded_from === "freelancer"
    ) {
      return handleApiError(
        new Error("Already upgraded"),
        "This provider has already been upgraded",
        400
      );
    }

    // Optional: Check subscription allows upgrade
    if (provider.subscription_plan_id) {
      const { data: plan } = await supabase
        .from("subscription_plans")
        .select("features")
        .eq("id", provider.subscription_plan_id)
        .single();

      if (plan?.features) {
        const features = plan.features as any;
        // If subscription explicitly disallows upgrade, block it
        if (features.allows_salon_upgrade === false) {
          return handleApiError(
            new Error("Subscription doesn't allow upgrade"),
            "Please upgrade your subscription plan to enable salon features",
            403
          );
        }
      }
    }

    // Execute upgrade function
    const { data: upgradeResult, error: upgradeError } = await supabase.rpc(
      "upgrade_freelancer_to_salon",
      { p_provider_id: providerId }
    );

    if (upgradeError) {
      console.error("Upgrade error:", upgradeError);
      throw upgradeError;
    }

    // Get updated provider data
    const { data: updatedProvider } = await supabase
      .from("providers")
      .select("id, business_type, capabilities")
      .eq("id", providerId)
      .single();

    return successResponse({
      upgraded: true,
      message: "Successfully upgraded to salon",
      provider: updatedProvider,
      details: upgradeResult,
    });
  } catch (error: any) {
    console.error("Error upgrading to salon:", error);
    return handleApiError(
      error,
      error.message || "Failed to upgrade to salon"
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getProviderIdForUser, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { z } from "zod";

const updateWaitingRoomEntrySchema = z.object({
  status: z.enum(["waiting", "in_service", "completed", "left"]).optional(),
  estimated_wait_time: z.number().optional(),
  position: z.number().optional(),
  notes: z.string().optional(),
});

/**
 * GET /api/provider/waiting-room/[id]
 * Get a specific waiting room entry (by appointment/booking ID)
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const permissionCheck = await requirePermission("view_calendar", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const { id } = await params;
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Query booking by ID
    const { data: booking, error } = await supabase
      .from("bookings")
      .select(`
        id,
        booking_number,
        customer_id,
        customer_name,
        customer_email,
        customer_phone,
        service_id,
        service_name,
        staff_id,
        scheduled_at,
        checked_in_time,
        status,
        notes,
        provider_staff:staff_id(
          id,
          name:users(full_name)
        )
      `)
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (error || !booking) {
      return notFoundResponse("Waiting room entry not found");
    }

    // Transform booking to waiting room entry
    let wrStatus: "waiting" | "in_service" | "completed" | "left" = "waiting";
    if (booking.status === "started") {
      wrStatus = "in_service";
    } else if (booking.status === "completed") {
      wrStatus = "completed";
    } else if (booking.status === "cancelled" || booking.status === "no_show") {
      wrStatus = "left";
    }

    const staff = Array.isArray(booking.provider_staff) ? booking.provider_staff?.[0] : booking.provider_staff;
    const nameData = staff?.name;
    const staffName = Array.isArray(nameData) ? nameData?.[0]?.full_name : (nameData as { full_name?: string })?.full_name;
    const entry = {
      id: booking.id,
      appointment_id: booking.id,
      client_name: booking.customer_name || "Client",
      client_email: booking.customer_email,
      client_phone: booking.customer_phone,
      service_id: booking.service_id,
      service_name: booking.service_name || "Service",
      team_member_id: booking.staff_id,
      team_member_name: staffName || (staff as { full_name?: string })?.full_name || "Staff",
      checked_in_time: booking.checked_in_time || booking.scheduled_at,
      checked_in_method: "staff" as const,
      status: wrStatus,
      notes: booking.notes,
      position: undefined,
      estimated_wait_time: undefined,
    };

    return successResponse(entry);
  } catch (error) {
    return handleApiError(error, "Failed to fetch waiting room entry");
  }
}

/**
 * PATCH /api/provider/waiting-room/[id]
 * Update waiting room entry status (updates the booking status)
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const permissionCheck = await requirePermission("edit_appointments", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const { id } = await params;
    const body = await request.json();

    const validationResult = updateWaitingRoomEntrySchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Verify booking belongs to provider
    const { data: booking } = await supabase
      .from("bookings")
      .select("id, status, checked_in_time")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (!booking) {
      return notFoundResponse("Waiting room entry not found");
    }

    // Map waiting room status to booking status
    let bookingStatus = booking.status;
    if (validationResult.data.status === "in_service") {
      bookingStatus = "started";
    } else if (validationResult.data.status === "completed") {
      bookingStatus = "completed";
    } else if (validationResult.data.status === "waiting") {
      bookingStatus = "waiting";
    }

    // Update booking
    const updateData: any = {
      status: bookingStatus,
    };

    // If marking as in service and not already checked in, set checked_in_time
    if (validationResult.data.status === "in_service" && !booking.checked_in_time) {
      updateData.checked_in_time = new Date().toISOString();
    }

    // If marking as completed, set completed_at
    if (validationResult.data.status === "completed") {
      updateData.completed_at = new Date().toISOString();
    }

    const { data: updatedBooking, error } = await supabase
      .from("bookings")
      .update(updateData)
      .eq("id", id)
      .select(`
        id,
        booking_number,
        customer_id,
        customer_name,
        customer_email,
        customer_phone,
        service_id,
        service_name,
        staff_id,
        scheduled_at,
        checked_in_time,
        status,
        notes,
        provider_staff:staff_id(
          id,
          name:users(full_name)
        )
      `)
      .single();

    if (error) {
      throw error;
    }

    // Transform back to waiting room entry format
    let wrStatus: "waiting" | "in_service" | "completed" | "left" = "waiting";
    if (updatedBooking.status === "started") {
      wrStatus = "in_service";
    } else if (updatedBooking.status === "completed") {
      wrStatus = "completed";
    } else if (updatedBooking.status === "cancelled" || updatedBooking.status === "no_show") {
      wrStatus = "left";
    }

    const updStaff = Array.isArray(updatedBooking.provider_staff) ? updatedBooking.provider_staff?.[0] : updatedBooking.provider_staff;
    const updNameData = updStaff?.name;
    const updStaffName = Array.isArray(updNameData) ? updNameData?.[0]?.full_name : (updNameData as { full_name?: string })?.full_name;
    const entry = {
      id: updatedBooking.id,
      appointment_id: updatedBooking.id,
      client_name: updatedBooking.customer_name || "Client",
      client_email: updatedBooking.customer_email,
      client_phone: updatedBooking.customer_phone,
      service_id: updatedBooking.service_id,
      service_name: updatedBooking.service_name || "Service",
      team_member_id: updatedBooking.staff_id,
      team_member_name: updStaffName || (updStaff as { full_name?: string })?.full_name || "Staff",
      checked_in_time: updatedBooking.checked_in_time || updatedBooking.scheduled_at,
      checked_in_method: "staff" as const,
      status: wrStatus,
      notes: updatedBooking.notes,
      position: undefined,
      estimated_wait_time: undefined,
    };

    return successResponse(entry);
  } catch (error) {
    return handleApiError(error, "Failed to update waiting room entry");
  }
}

/**
 * DELETE /api/provider/waiting-room/[id]
 * Remove entry from waiting room (marks appointment as left/cancelled)
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const permissionCheck = await requirePermission("cancel_appointments", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const { id } = await params;
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Verify booking belongs to provider
    const { data: booking } = await supabase
      .from("bookings")
      .select("id")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (!booking) {
      return notFoundResponse("Waiting room entry not found");
    }

    // Mark as cancelled/left (don't actually delete the booking)
    const { error } = await supabase
      .from("bookings")
      .update({
        status: "cancelled",
        cancellation_reason: "Client left waiting room",
      })
      .eq("id", id);

    if (error) {
      throw error;
    }

    return successResponse({ success: true });
  } catch (error) {
    return handleApiError(error, "Failed to remove from waiting room");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getProviderIdForUser, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { z } from "zod";

const createWaitingRoomEntrySchema = z.object({
  client_name: z.string().min(1),
  client_email: z.string().email().optional(),
  client_phone: z.string().optional(),
  appointment_id: z.string().uuid().optional(),
  service_id: z.string().uuid().optional(),
  service_name: z.string().optional(),
  team_member_id: z.string().uuid().optional(),
  team_member_name: z.string().optional(),
  checked_in_method: z.enum(["self", "staff", "online"]).default("staff"),
  estimated_wait_time: z.number().optional(),
  notes: z.string().optional(),
});

/**
 * GET /api/provider/waiting-room
 * 
 * Get waiting room entries (appointments that are checked in and waiting)
 * The waiting room shows appointments with status "WAITING" (checked in but not started)
 */
export async function GET(request: NextRequest) {
  try {
    const permissionCheck = await requirePermission("view_calendar", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const searchParams = request.nextUrl.searchParams;
    const status = searchParams.get("status");
    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Query bookings that are checked in (status = 'waiting' or 'checked_in')
    // These are appointments where the client has checked in but service hasn't started
    let query = supabase
      .from("bookings")
      .select(`
        id,
        booking_number,
        customer_id,
        customer_name,
        customer_email,
        customer_phone,
        service_id,
        service_name,
        staff_id,
        scheduled_at,
        checked_in_time,
        status,
        notes,
        provider_staff:staff_id(
          id,
          name:users(full_name)
        )
      `)
      .eq("provider_id", providerId)
      .in("status", ["waiting", "checked_in", "confirmed"])
      .not("checked_in_time", "is", null)
      .order("checked_in_time", { ascending: true });

    // Filter by status if provided
    if (status && status !== 'all') {
      if (status === 'waiting') {
        query = query.in("status", ["waiting", "checked_in", "confirmed"]);
      } else if (status === 'in_service') {
        query = query.eq("status", "started");
      } else if (status === 'completed') {
        query = query.eq("status", "completed");
      }
    }

    const { data: bookings, error } = await query;

    if (error) {
      throw error;
    }

    // Transform bookings to waiting room entries
    const entries = (bookings || []).map((booking: any) => {
      // Determine waiting room status from booking status
      let wrStatus: "waiting" | "in_service" | "completed" | "left" = "waiting";
      if (booking.status === "started") {
        wrStatus = "in_service";
      } else if (booking.status === "completed") {
        wrStatus = "completed";
      } else if (booking.status === "cancelled" || booking.status === "no_show") {
        wrStatus = "left";
      }

      return {
        id: booking.id,
        appointment_id: booking.id,
        client_name: booking.customer_name || "Client",
        client_email: booking.customer_email,
        client_phone: booking.customer_phone,
        service_id: booking.service_id,
        service_name: booking.service_name || "Service",
        team_member_id: booking.staff_id,
        team_member_name: booking.provider_staff?.name || booking.provider_staff?.full_name || "Staff",
        checked_in_time: booking.checked_in_time || booking.scheduled_at,
        checked_in_method: "staff" as const, // Default to staff, could be enhanced
        status: wrStatus,
        notes: booking.notes,
        position: undefined, // Could calculate based on check-in time order
        estimated_wait_time: undefined,
      };
    });

    return successResponse(entries);
  } catch (error) {
    return handleApiError(error, "Failed to fetch waiting room entries");
  }
}

/**
 * POST /api/provider/waiting-room
 * 
 * Add entry to waiting room
 */
export async function POST(request: NextRequest) {
  try {
    const permissionCheck = await requirePermission("create_appointments", request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const supabase = await getSupabaseServer(request);
    const body = await request.json();

    const validationResult = createWaitingRoomEntrySchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const data = validationResult.data;
    const checkedInTime = new Date().toISOString();

    // If appointment_id is provided, update the existing booking
    if (data.appointment_id) {
      const { data: booking, error: bookingError } = await supabase
        .from("bookings")
        .update({
          checked_in_time: checkedInTime,
          status: "checked_in", // Set status to checked_in
        })
        .eq("id", data.appointment_id)
        .eq("provider_id", providerId)
        .select(`
          id,
          booking_number,
          customer_id,
          customer_name,
          customer_email,
          customer_phone,
          service_id,
          service_name,
          staff_id,
          scheduled_at,
          checked_in_time,
          status,
          notes,
          provider_staff:staff_id(
            id,
            name:users(full_name)
          )
        `)
        .single();

      if (bookingError || !booking) {
        return handleApiError(
          bookingError || new Error("Booking not found"),
          "Failed to check in booking"
        );
      }

      // Transform to waiting room entry format
      const entry = {
        id: booking.id,
        appointment_id: booking.id,
        client_name: booking.customer_name || data.client_name || "Client",
        client_email: booking.customer_email || data.client_email,
        client_phone: booking.customer_phone || data.client_phone,
        service_id: booking.service_id || data.service_id,
        service_name: booking.service_name || data.service_name || "Service",
        team_member_id: booking.staff_id || data.team_member_id,
        team_member_name: (booking.provider_staff as any)?.name || data.team_member_name || "Staff",
        checked_in_time: booking.checked_in_time || checkedInTime,
        checked_in_method: data.checked_in_method || "staff",
        status: "waiting" as const,
        notes: booking.notes || data.notes,
        position: undefined,
        estimated_wait_time: data.estimated_wait_time,
      };

      return successResponse(entry);
    }

    // If no appointment_id, create a new booking for walk-in
    // This is for walk-in clients who don't have a pre-existing appointment
    const { data: newBooking, error: createError } = await supabase
      .from("bookings")
      .insert({
        provider_id: providerId,
        customer_id: null, // Walk-in, no customer account
        customer_name: data.client_name,
        customer_email: data.client_email,
        customer_phone: data.client_phone,
        scheduled_at: new Date().toISOString(), // Current time for walk-in
        location_type: 'at_salon',
        status: 'checked_in',
        checked_in_time: checkedInTime,
        staff_id: data.team_member_id || null,
        notes: data.notes || null,
      })
      .select(`
        id,
        booking_number,
        customer_id,
        customer_name,
        customer_email,
        customer_phone,
        service_id,
        service_name,
        staff_id,
        scheduled_at,
        checked_in_time,
        status,
        notes,
        provider_staff:staff_id(
          id,
          name:users(full_name)
        )
      `)
      .single();

    if (createError || !newBooking) {
      return handleApiError(
        createError || new Error("Failed to create booking"),
        "Failed to add to waiting room"
      );
    }

    // If service_id is provided, create booking_service entry
    if (data.service_id) {
      // Get service details
      const { data: service } = await supabase
        .from("offerings")
        .select("id, duration_minutes, price, title")
        .eq("id", data.service_id)
        .single();

      if (service) {
        const serviceStart = new Date(checkedInTime);
        const serviceEnd = new Date(serviceStart.getTime() + (service.duration_minutes || 60) * 60000);

        await supabase
          .from("booking_services")
          .insert({
            booking_id: newBooking.id,
            offering_id: data.service_id,
            staff_id: data.team_member_id || null,
            scheduled_start_at: serviceStart.toISOString(),
            scheduled_end_at: serviceEnd.toISOString(),
            duration_minutes: service.duration_minutes || 60,
            price: service.price || 0,
            currency: 'ZAR',
          });

        // Update booking with service info
        await supabase
          .from("bookings")
          .update({
            service_id: data.service_id,
            service_name: service.title || data.service_name,
          })
          .eq("id", newBooking.id);
      }
    }

    // Transform to waiting room entry format
    const entry = {
      id: newBooking.id,
      appointment_id: newBooking.id,
      client_name: newBooking.customer_name || data.client_name,
      client_email: newBooking.customer_email || data.client_email,
      client_phone: newBooking.customer_phone || data.client_phone,
      service_id: newBooking.service_id || data.service_id,
      service_name: newBooking.service_name || data.service_name || "Service",
      team_member_id: newBooking.staff_id || data.team_member_id,
      team_member_name: (newBooking.provider_staff as any)?.name || data.team_member_name || "Staff",
      checked_in_time: newBooking.checked_in_time || checkedInTime,
      checked_in_method: data.checked_in_method || "staff",
      status: "waiting" as const,
      notes: newBooking.notes || data.notes,
      position: undefined,
      estimated_wait_time: data.estimated_wait_time,
    };

    return successResponse(entry);
  } catch (error) {
    return handleApiError(error, "Failed to add to waiting room");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getProviderIdForUser, successResponse, notFoundResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";

/**
 * POST /api/provider/waitlist/[id]/notify
 * 
 * Send notification to waitlist entry client
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const permissionCheck = await requirePermission('send_messages', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;

    const supabase = await getSupabaseServer(request);
    const { id } = await params;

    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Verify entry belongs to provider and get full details
    const { data: entry, error: fetchError } = await supabase
      .from("waitlist_entries")
      .select(`
        id,
        customer_id,
        customer_name,
        customer_email,
        customer_phone,
        service_id,
        preferred_date,
        preferred_time_start,
        status,
        providers!inner(
          id,
          business_name,
          user_id
        ),
        offerings:service_id(
          id,
          title
        )
      `)
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (fetchError || !entry) {
      return notFoundResponse("Waitlist entry not found");
    }

    // Update status to notified
    const { data: updatedEntry, error: updateError } = await supabase
      .from("waitlist_entries")
      .update({
        status: 'contacted', // Using 'contacted' as equivalent to 'notified'
        notified_at: new Date().toISOString(),
      })
      .eq("id", id)
      .select()
      .single();

    if (updateError || !updatedEntry) {
      throw updateError || new Error("Failed to update waitlist entry");
    }

    // Send notification via OneSignal using template
    try {
      const { sendTemplateNotification } = await import("@/lib/notifications/onesignal");

      // Determine notification channels based on available contact info
      const channels: ("push" | "email" | "sms")[] = ["push"];
      if (entry.customer_email) {
        channels.push("email");
      }
      if (entry.customer_phone) {
        channels.push("sms");
      }

      // Build template variables
      const serviceName = (entry.offerings as any)?.title || "your requested service";
      const providerName = (entry.providers as any)?.business_name || "the salon";
      const preferredDate = entry.preferred_date 
        ? new Date(entry.preferred_date).toLocaleDateString()
        : "soon";
      const preferredTime = entry.preferred_time_start || "";

      // Send notification using template if customer_id exists
      if (entry.customer_id) {
        const notificationResult = await sendTemplateNotification(
          "booking_waitlist_available",
          [entry.customer_id],
          {
            provider_name: providerName,
            available_date: preferredDate,
            available_time: preferredTime,
            services: serviceName,
            provider_id: providerId,
            waitlist_entry_id: entry.id,
          },
          channels
        );

        if (!notificationResult.success) {
          console.warn("Failed to send waitlist notification:", notificationResult.error);
        }
      } else if (entry.customer_email || entry.customer_phone) {
        // If no customer_id but we have email/phone, log for manual follow-up
        console.log("Waitlist notification would be sent to:", {
          email: entry.customer_email,
          phone: entry.customer_phone,
          provider: providerName,
          service: serviceName,
          date: preferredDate,
        });
      }
    } catch (notificationError) {
      // Log error but don't fail the request
      console.error("Error sending waitlist notification:", notificationError);
    }

    return successResponse({
      success: true,
      message: "Notification sent successfully",
      entry: updatedEntry,
    });
  } catch (error) {
    return handleApiError(error, "Failed to notify waitlist entry");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { z } from "zod";

const quickBookSchema = z.object({
  date: z.string().date(),
  time: z.string().regex(/^\d{2}:\d{2}$/), // HH:MM format
  staff_id: z.string().uuid().optional(),
});

/**
 * POST /api/provider/waitlist/[id]/quick-book
 * 
 * Convert waitlist entry to booking (quick booking)
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const permissionCheck = await requirePermission('create_appointments', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;
    const { id: waitlistEntryId } = await params;
    const body = await request.json();

    const validationResult = quickBookSchema.safeParse(body);
    if (!validationResult.success) {
      return handleApiError(
        new Error(validationResult.error.issues.map((e: any) => e.message).join(", ")),
        "Validation failed",
        "VALIDATION_ERROR",
        400
      );
    }

    const { date, time, staff_id } = validationResult.data;
    const supabase = await getSupabaseServer(request);
    const adminSupabase = getSupabaseAdmin();

    // Load waitlist entry
    const { data: entry, error: entryError } = await supabase
      .from('waitlist_entries')
      .select('*, providers!inner(id, user_id)')
      .eq('id', waitlistEntryId)
      .single();

    if (entryError || !entry) {
      return handleApiError(
        new Error("Waitlist entry not found"),
        "Waitlist entry not found",
        "NOT_FOUND",
        404
      );
    }

    // Verify user owns the provider
    if (entry.providers.user_id !== user.id) {
      return handleApiError(
        new Error("Unauthorized"),
        "You can only book waitlist entries for your own provider",
        "UNAUTHORIZED",
        403
      );
    }

    if (entry.status !== 'waiting' && entry.status !== 'contacted') {
      return handleApiError(
        new Error("Waitlist entry is not available for booking"),
        "This waitlist entry cannot be booked",
        "INVALID_STATUS",
        400
      );
    }

    // Get service details
    let serviceDuration = 60;
    let servicePrice = 0;
    if (entry.service_id) {
      const { data: service } = await supabase
        .from('offerings')
        .select('duration_minutes, price')
        .eq('id', entry.service_id)
        .single();

      if (service) {
        serviceDuration = service.duration_minutes || 60;
        servicePrice = service.price || 0;
      }
    }

    // Create booking datetime
    const [hours, minutes] = time.split(':').map(Number);
    const bookingDatetime = new Date(date);
    bookingDatetime.setHours(hours, minutes, 0, 0);

    const bookingEnd = new Date(bookingDatetime.getTime() + serviceDuration * 60000);

    // Create booking
    const { data: booking, error: bookingError } = await adminSupabase
      .from('bookings')
      .insert({
        provider_id: entry.provider_id,
        customer_id: entry.customer_id,
        scheduled_at: bookingDatetime.toISOString(),
        location_type: 'at_salon', // Default, could be configurable
        status: 'confirmed',
        price: servicePrice,
        currency: 'ZAR', // Default, should come from provider
        guest_name: entry.customer_name,
      })
      .select()
      .single();

    if (bookingError) {
      throw bookingError;
    }

    // Create booking service if service_id exists
    if (entry.service_id) {
      const { error: serviceError } = await adminSupabase
        .from('booking_services')
        .insert({
          booking_id: booking.id,
          offering_id: entry.service_id,
          staff_id: staff_id || entry.staff_id || null,
          scheduled_start_at: bookingDatetime.toISOString(),
          scheduled_end_at: bookingEnd.toISOString(),
          duration_minutes: serviceDuration,
          price: servicePrice,
          currency: 'ZAR',
        });

      if (serviceError) {
        throw serviceError;
      }
    }

    // Update waitlist entry status to 'booked'
    const { error: updateError } = await adminSupabase
      .from('waitlist_entries')
      .update({
        status: 'booked',
        updated_at: new Date().toISOString(),
      })
      .eq('id', waitlistEntryId);

    if (updateError) {
      throw updateError;
    }

    // Create booking event
    await adminSupabase.from('booking_events').insert({
      booking_id: booking.id,
      event_type: 'created',
      event_data: {
        source: 'waitlist',
        waitlist_entry_id: waitlistEntryId,
      },
      created_by: user.id,
    });

    // Send booking confirmation notification
    const { sendBookingConfirmationNotification } = await import('@/lib/bookings/notifications');
    await sendBookingConfirmationNotification(booking.id);

    return successResponse({
      booking,
      message: "Booking created from waitlist successfully",
    });
  } catch (error) {
    return handleApiError(error, "Failed to create booking from waitlist");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getProviderIdForUser, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { requirePermission } from "@/lib/auth/requirePermission";
import { z } from "zod";

const updateWaitlistSchema = z.object({
  customer_name: z.string().min(1).optional(),
  customer_email: z.string().email().optional(),
  customer_phone: z.string().optional(),
  service_id: z.string().uuid().nullable().optional(),
  staff_id: z.string().uuid().nullable().optional(),
  preferred_date: z.string().nullable().optional(),
  preferred_time: z.string().nullable().optional(), // Single time field from frontend
  preferred_time_start: z.string().nullable().optional(),
  preferred_time_end: z.string().nullable().optional(),
  notes: z.string().nullable().optional(),
  status: z.enum(['waiting', 'contacted', 'booked', 'cancelled']).optional(),
  priority: z.number().optional(),
});

/**
 * GET /api/provider/waitlist/[id]
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const permissionCheck = await requirePermission('view_calendar', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;

    const supabase = await getSupabaseServer(request);
    const { id } = await params;

    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    const { data: entry, error } = await supabase
      .from("waitlist_entries")
      .select(`
        *,
        offerings:service_id(id, title),
        provider_staff:staff_id(id, name:users(full_name))
      `)
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (error || !entry) {
      return notFoundResponse("Waitlist entry not found");
    }

    // Transform to match frontend WaitlistEntry type
    const transformedEntry = {
      id: entry.id,
      customer_id: entry.customer_id,
      customer_name: entry.customer_name,
      customer_email: entry.customer_email,
      customer_phone: entry.customer_phone,
      service_id: entry.service_id,
      service_name: (entry as any).offerings?.title || "",
      staff_id: entry.staff_id,
      staff_name: (entry as any).provider_staff?.name?.full_name || "",
      preferred_date: entry.preferred_date,
      preferred_time: entry.preferred_time_start || undefined,
      preferred_time_start: entry.preferred_time_start,
      preferred_time_end: entry.preferred_time_end,
      notes: entry.notes,
      priority: entry.priority === 0 ? "normal" : entry.priority > 0 ? "high" : "low",
      status: entry.status === "waiting" ? "active" : entry.status,
      created_at: entry.created_at,
      created_date: entry.created_at,
      notified_date: entry.notified_at,
    };

    return successResponse(transformedEntry);
  } catch (error) {
    return handleApiError(error, "Failed to fetch waitlist entry");
  }
}

/**
 * PATCH /api/provider/waitlist/[id]
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const permissionCheck = await requirePermission('edit_appointments', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;

    const supabase = await getSupabaseServer(request);
    const { id } = await params;
    const body = await request.json();

    const validationResult = updateWaitlistSchema.safeParse(body);
    if (!validationResult.success) {
      return errorResponse(
        "Validation failed",
        "VALIDATION_ERROR",
        400,
        validationResult.error.issues
      );
    }

    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Verify entry belongs to provider
    const { data: existingEntry } = await supabase
      .from("waitlist_entries")
      .select("id")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (!existingEntry) {
      return notFoundResponse("Waitlist entry not found");
    }

    // Map preferred_time to preferred_time_start if provided
    const updateData: any = { ...validationResult.data };
    if (updateData.preferred_time && !updateData.preferred_time_start) {
      updateData.preferred_time_start = updateData.preferred_time;
      delete updateData.preferred_time;
    }

    // Update entry
    const { data: updatedEntry, error: updateError } = await (supabase
      .from("waitlist_entries") as any)
      .update(updateData)
      .eq("id", id)
      .select(`
        *,
        offerings:service_id(id, title),
        provider_staff:staff_id(id, name:users(full_name))
      `)
      .single();

    if (updateError || !updatedEntry) {
      throw updateError || new Error("Failed to update waitlist entry");
    }

    // Transform to match frontend WaitlistEntry type
    const transformedEntry = {
      id: updatedEntry.id,
      customer_id: updatedEntry.customer_id,
      customer_name: updatedEntry.customer_name,
      customer_email: updatedEntry.customer_email,
      customer_phone: updatedEntry.customer_phone,
      service_id: updatedEntry.service_id,
      service_name: (updatedEntry as any).offerings?.title || "",
      staff_id: updatedEntry.staff_id,
      staff_name: (updatedEntry as any).provider_staff?.name?.full_name || "",
      preferred_date: updatedEntry.preferred_date,
      preferred_time: updatedEntry.preferred_time_start || undefined,
      preferred_time_start: updatedEntry.preferred_time_start,
      preferred_time_end: updatedEntry.preferred_time_end,
      notes: updatedEntry.notes,
      priority: updatedEntry.priority === 0 ? "normal" : updatedEntry.priority > 0 ? "high" : "low",
      status: updatedEntry.status === "waiting" ? "active" : updatedEntry.status,
      created_at: updatedEntry.created_at,
      created_date: updatedEntry.created_at,
      notified_date: updatedEntry.notified_at,
    };

    return successResponse(transformedEntry);
  } catch (error) {
    return handleApiError(error, "Failed to update waitlist entry");
  }
}

/**
 * DELETE /api/provider/waitlist/[id]
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const permissionCheck = await requirePermission('edit_appointments', request);
    if (!permissionCheck.authorized) {
      return permissionCheck.response!;
    }
    const { user } = permissionCheck;

    const supabase = await getSupabaseServer(request);
    const { id } = await params;

    const providerId = await getProviderIdForUser(user.id, supabase);
    if (!providerId) {
      return notFoundResponse("Provider not found");
    }

    // Verify entry belongs to provider
    const { data: existingEntry } = await supabase
      .from("waitlist_entries")
      .select("id")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (!existingEntry) {
      return notFoundResponse("Waitlist entry not found");
    }

    const { error: deleteError } = await supabase
      .from("waitlist_entries")
