      },
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/provider/yoco/integration:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch integration",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
