import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import crypto from "crypto";
import { YOCO_WEBHOOK_EVENTS } from "@/lib/payments/yoco";

/**
 * POST /api/provider/yoco/webhook
 * 
 * Yoco webhook handler for payment and refund notifications
 * 
 * According to Yoco API: https://developer.yoco.com/api-reference/checkout-api/webhook-events
 * 
 * Webhook events:
 * - payment.notification
 * - refund.notification.success.full
 * - refund.notification.success.partial
 * - refund.notification.failure.full
 * - refund.notification.failure.partial
 */
export async function POST(request: Request) {
  try {
    const body = await request.text();
    const signature = request.headers.get("x-yoco-signature");
    const webhookId = request.headers.get("x-yoco-webhook-id");

    if (!signature || !webhookId) {
      console.error("Missing Yoco webhook signature or ID");
      return NextResponse.json(
        { error: "Missing signature or webhook ID" },
        { status: 400 }
      );
    }

    const supabase = await getSupabaseServer(request);
    const event = JSON.parse(body);

    // Verify webhook signature
    // Get webhook secret from database (stored per provider or globally)
    // For now, we'll verify against provider's webhook_secret
    const { data: webhookConfig } = await supabase
      .from("provider_yoco_webhooks")
      .select("webhook_secret, provider_id")
      .eq("webhook_id", webhookId)
      .single();

    if (!webhookConfig) {
      // Try to verify with global webhook secret from env
      const globalWebhookSecret = process.env.YOCO_WEBHOOK_SECRET;
      if (globalWebhookSecret) {
        const hash = crypto
          .createHmac("sha256", globalWebhookSecret)
          .update(body)
          .digest("hex");

        if (hash !== signature) {
          console.error("Invalid Yoco webhook signature");
          return NextResponse.json(
            { error: "Invalid signature" },
            { status: 401 }
          );
        }
      } else {
        console.error("No webhook secret configured");
        return NextResponse.json(
          { error: "Webhook not configured" },
          { status: 500 }
        );
      }
    } else {
      // Verify with provider-specific secret
      const hash = crypto
        .createHmac("sha256", (webhookConfig as any).webhook_secret)
        .update(body)
        .digest("hex");

      if (hash !== signature) {
        console.error("Invalid Yoco webhook signature");
        return NextResponse.json(
          { error: "Invalid signature" },
          { status: 401 }
        );
      }
    }

    // Log webhook event
    await (supabase
      .from("provider_yoco_webhook_events") as any)
      .insert({
        webhook_id: webhookId,
        event_type: event.type,
        payload: event,
        signature,
        status: "received",
        created_at: new Date().toISOString(),
      });

    // Handle different event types
    try {
      const { type, data } = event;

      switch (type) {
        case YOCO_WEBHOOK_EVENTS.PAYMENT_NOTIFICATION:
          await handlePaymentNotification(data, supabase);
          break;

        case YOCO_WEBHOOK_EVENTS.REFUND_NOTIFICATION_SUCCESS_FULL:
        case YOCO_WEBHOOK_EVENTS.REFUND_NOTIFICATION_SUCCESS_PARTIAL:
          await handleRefundSuccess(data, supabase);
          break;

        case YOCO_WEBHOOK_EVENTS.REFUND_NOTIFICATION_FAILURE_FULL:
        case YOCO_WEBHOOK_EVENTS.REFUND_NOTIFICATION_FAILURE_PARTIAL:
          await handleRefundFailure(data, supabase);
          break;

        default:
          console.log(`Unhandled Yoco webhook event type: ${type}`);
      }

      // Mark webhook as processed
      await (supabase
        .from("provider_yoco_webhook_events") as any)
        .update({
          status: "processed",
          processed_at: new Date().toISOString(),
        })
        .eq("webhook_id", webhookId);

    } catch (error) {
      console.error("Error processing Yoco webhook:", error);

      // Mark as failed
      await (supabase
        .from("provider_yoco_webhook_events") as any)
        .update({
          status: "failed",
          error_message: error instanceof Error ? error.message : String(error),
          processed_at: new Date().toISOString(),
        })
        .eq("webhook_id", webhookId);

      // Still return 200 to acknowledge receipt
      return NextResponse.json({
        received: true,
        error: error instanceof Error ? error.message : "Processing error",
      });
    }

    return NextResponse.json({ received: true });
  } catch (error) {
    console.error("Unexpected error in /api/provider/yoco/webhook:", error);
    return NextResponse.json(
      { error: "Webhook processing failed" },
      { status: 500 }
    );
  }
}

async function handlePaymentNotification(data: any, supabase: any) {
  const { id, amount, currency, status, metadata } = data;

  if (!id || !metadata?.provider_id) {
    console.error("Missing payment ID or provider ID in webhook data");
    return;
  }

  // Update payment status
  const { error } = await (supabase
    .from("provider_yoco_payments") as any)
    .update({
      status: status === "successful" ? "successful" : status === "failed" ? "failed" : "pending",
      updated_at: new Date().toISOString(),
    })
    .eq("yoco_payment_id", id);

  if (error) {
    console.error("Error updating payment status:", error);
  }

  // If payment successful, create booking_payment record
  // This will trigger automatic creation of finance_transactions via database trigger
  if (status === "successful" && metadata.appointment_id) {
    const bookingId = metadata.appointment_id;
    const amountInCurrency = amount / 100; // Yoco uses cents

    // Get booking details
    const { data: booking } = await supabase
      .from("bookings")
      .select("id, booking_number, provider_id, total_amount, payment_status, location_id, location_type")
      .eq("id", bookingId)
      .single();

    // If booking is missing location_id and it's an at_salon booking, set it to provider's first location
    if (booking && !booking.location_id && booking.location_type === "at_salon") {
      const { getSupabaseAdmin } = await import("@/lib/supabase/admin");
      const supabaseAdmin = await getSupabaseAdmin();

      const { data: providerLocations } = await supabaseAdmin
        .from("provider_locations")
        .select("id")
        .eq("provider_id", booking.provider_id)
        .order("created_at", { ascending: true })
        .limit(1);

      if (providerLocations && providerLocations.length > 0) {
        const defaultLocationId = providerLocations[0].id;
        const { error: updateError } = await supabaseAdmin
          .from("bookings")
          .update({ location_id: defaultLocationId })
          .eq("id", bookingId);

        if (!updateError) {
          console.log(`Updated booking ${bookingId} with location_id ${defaultLocationId} via Yoco webhook`);
        } else {
          console.warn(`Failed to update location_id for booking ${bookingId}:`, updateError);
        }
      }
    }

    if (booking && booking.payment_status !== "paid") {
      // Idempotency: skip if we've already recorded this Yoco payment
      const { data: existingPayment } = await supabase
        .from("booking_payments")
        .select("id")
        .eq("payment_provider_id", id)
        .maybeSingle();
      if (existingPayment) {
        console.log(`Yoco payment ${id} already recorded, skipping (idempotent)`);
        return;
      }

      console.log(`Creating booking_payment for booking ${booking.booking_number} via Yoco terminal`);

      // Create booking_payment record (this will trigger finance_transactions creation via migration 169)
      const { error: paymentError } = await supabase
        .from("booking_payments")
        .insert({
          booking_id: bookingId,
          amount: amountInCurrency,
          payment_method: "card",
          payment_provider: "yoco",
          payment_provider_id: id, // Yoco payment ID
          payment_provider_data: {
            yoco_payment_id: id,
            device_id: metadata.device_id,
            currency: currency,
          },
          status: "completed",
          notes: `Yoco card terminal payment - ${id}`,
          created_by: metadata.processed_by || null,
          created_at: new Date().toISOString(),
        });

      if (paymentError) {
        console.error("Error creating booking_payment:", paymentError);
        // Fallback: Update booking directly if booking_payment creation fails
        await (supabase
          .from("bookings") as any)
          .update({
            payment_status: "paid",
            payment_date: new Date().toISOString(),
          })
          .eq("id", bookingId);
      } else {
        console.log(`Γ£à Booking payment created for ${booking.booking_number} via Yoco terminal. Finance transactions will be auto-created by trigger.`);
        // The trigger (migration 169) will automatically:
        // 1. Create finance_transactions (payment & provider_earnings)
        // 2. Update booking.payment_status to "paid"
        // 3. Update booking.total_paid
      }
    } else if (booking && booking.payment_status === "paid") {
      console.log(`Booking ${booking.booking_number} is already marked as paid, skipping`);
    }
  }

  // Send notification
  try {
    const { sendToUser } = await import("@/lib/notifications/onesignal");
    if (metadata.processed_by) {
      await sendToUser(metadata.processed_by, {
        title: status === "successful" ? "Payment Successful" : "Payment Failed",
        message: `Payment ${status === "successful" ? "completed" : "failed"} for amount ${(amount / 100).toFixed(2)} ${currency}`,
        data: {
          type: "yoco_payment",
          payment_id: id,
          status,
        },
      });
    }
  } catch (notifError) {
    console.error("Error sending notification:", notifError);
  }
}

async function handleRefundSuccess(data: any, supabase: any) {
  const { id, amount, currency, metadata } = data;

  // Create refund record
  await (supabase
    .from("provider_yoco_refunds") as any)
    .insert({
      yoco_refund_id: id,
      payment_id: metadata?.payment_id,
      amount: amount,
      currency: currency || "ZAR",
      status: "successful",
      created_at: new Date().toISOString(),
    });

  // Update payment status
  if (metadata?.payment_id) {
    await (supabase
      .from("provider_yoco_payments") as any)
      .update({
        refund_status: amount === data.original_amount ? "fully_refunded" : "partially_refunded",
        refund_amount: amount,
        updated_at: new Date().toISOString(),
      })
      .eq("yoco_payment_id", metadata.payment_id);
  }
}

async function handleRefundFailure(data: any, supabase: any) {
  const { id, error, metadata } = data;

  // Create refund failure record
  await (supabase
    .from("provider_yoco_refunds") as any)
    .insert({
      yoco_refund_id: id,
      payment_id: metadata?.payment_id,
      status: "failed",
      error_message: error?.message || "Refund failed",
      created_at: new Date().toISOString(),
    });
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  handleApiError,
  getProviderIdForUser,
  badRequestResponse,
  notFoundResponse,
} from "@/lib/supabase/api-helpers";
import { z } from "zod";

const updateZoneSelectionSchema = z.object({
  travel_fee: z.number().min(0).optional(),
  currency: z.string().length(3).optional(),
  travel_time_minutes: z.number().int().positive().optional(),
  description: z.string().optional().nullable(),
  is_active: z.boolean().optional(),
});

/**
 * GET /api/provider/zone-selections/[id]
 * Get a specific zone selection
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    const { id } = await params;

    if (!providerId) {
      return badRequestResponse("Provider not found");
    }

    const { data: selection, error } = await supabase
      .from("provider_zone_selections")
      .select(`
        *,
        platform_zone:platform_zones(*)
      `)
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (error || !selection) {
      return notFoundResponse("Zone selection not found");
    }

    return successResponse(selection);
  } catch (error) {
    return handleApiError(error, "Failed to fetch zone selection");
  }
}

/**
 * PATCH /api/provider/zone-selections/[id]
 * Update a zone selection (pricing, etc.)
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    const { id } = await params;

    if (!providerId) {
      return badRequestResponse("Provider not found");
    }

    // Verify selection belongs to provider
    const { data: existing, error: fetchError } = await supabase
      .from("provider_zone_selections")
      .select("id")
      .eq("id", id)
      .eq("provider_id", providerId)
      .single();

    if (fetchError || !existing) {
      return notFoundResponse("Zone selection not found");
    }

    const body = await request.json();
    const validationResult = updateZoneSelectionSchema.safeParse(body);

    if (!validationResult.success) {
      return badRequestResponse(
        validationResult.error.issues.map((i) => i.message).join(", ")
      );
    }

    const data = validationResult.data;
    const updateData: any = {};
    if (data.travel_fee !== undefined) updateData.travel_fee = data.travel_fee;
    if (data.currency !== undefined) updateData.currency = data.currency;
    if (data.travel_time_minutes !== undefined) updateData.travel_time_minutes = data.travel_time_minutes;
    if (data.description !== undefined) updateData.description = data.description;
    if (data.is_active !== undefined) updateData.is_active = data.is_active;

    const { data: selection, error } = await supabase
      .from("provider_zone_selections")
      .update(updateData)
      .eq("id", id)
      .eq("provider_id", providerId)
      .select(`
        *,
        platform_zone:platform_zones(*)
      `)
      .single();

    if (error) {
      throw error;
    }

    return successResponse(selection);
  } catch (error) {
    return handleApiError(error, "Failed to update zone selection");
  }
}

/**
 * DELETE /api/provider/zone-selections/[id]
 * Remove a zone selection (opt out of zone)
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);
    const { id } = await params;

    if (!providerId) {
      return badRequestResponse("Provider not found");
    }

    const { error } = await supabase
      .from("provider_zone_selections")
      .delete()
      .eq("id", id)
      .eq("provider_id", providerId);

    if (error) {
      throw error;
    }

    return successResponse({ success: true });
  } catch (error) {
    return handleApiError(error, "Failed to remove zone selection");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  requireRoleInApi,
  successResponse,
  handleApiError,
  getProviderIdForUser,
} from "@/lib/supabase/api-helpers";
import { getMapboxService } from "@/lib/mapbox/mapbox";

/**
 * GET /api/provider/zone-selections/suggest
 * 
 * Auto-suggest platform zones based on provider's primary location
 * This makes it easier for providers to select relevant zones
 */
export async function GET(request: NextRequest) {
  try {
    const { user } = await requireRoleInApi(["provider_owner", "provider_staff"], request);
    const supabase = await getSupabaseServer(request);
    const providerId = await getProviderIdForUser(user.id, supabase);

    if (!providerId) {
      return successResponse({ suggested_zones: [], message: "Provider not found" });
    }

    // Get provider's primary location (provider_locations uses latitude/longitude per 003_providers)
    const { data: primaryLocation, error: locationError } = await supabase
      .from("provider_locations")
      .select("latitude, longitude, city, postal_code, country")
      .eq("provider_id", providerId)
      .eq("is_primary", true)
      .single();

    const plLat = (primaryLocation as any)?.latitude ?? (primaryLocation as any)?.address_lat;
    const plLng = (primaryLocation as any)?.longitude ?? (primaryLocation as any)?.address_lng;
    if (locationError || !primaryLocation || plLat == null || plLng == null) {
      return successResponse({
        suggested_zones: [],
        message: "Please set up your primary location first to get zone suggestions",
      });
    }

    const providerCoordinates = {
      latitude: plLat,
      longitude: plLng,
    };

    // Get all active platform zones
    const { data: platformZones, error: zonesError } = await supabase
      .from("platform_zones")
      .select("*")
      .eq("is_active", true);

    if (zonesError) {
      throw zonesError;
    }

    // Get provider's existing selections
    const { data: existingSelections, error: selectionsError } = await supabase
      .from("provider_zone_selections")
      .select("platform_zone_id")
      .eq("provider_id", providerId);

    if (selectionsError) {
      throw selectionsError;
    }

    const selectedZoneIds = new Set((existingSelections || []).map((s) => s.platform_zone_id));

    // Check which zones match the provider's location
    const mapbox = await getMapboxService();
    const suggestedZones: any[] = [];
    const otherZones: any[] = [];

    for (const zone of platformZones || []) {
      // Skip if already selected
      if (selectedZoneIds.has(zone.id)) {
        continue;
      }

      let isMatch = false;
      let matchReason = "";

      // Check postal code match
      if (zone.zone_type === "postal_code" && zone.postal_codes && primaryLocation.postal_code) {
        const normalizedPostal = primaryLocation.postal_code.replace(/\s/g, "");
        isMatch = zone.postal_codes.some((pc: string) => pc.replace(/\s/g, "") === normalizedPostal);
        if (isMatch) {
          matchReason = `Your postal code (${primaryLocation.postal_code}) is in this zone`;
        }
      }

      // Check city match
      if (!isMatch && zone.zone_type === "city" && zone.cities && primaryLocation.city) {
        const normalizedCity = primaryLocation.city.toLowerCase().trim();
        isMatch = zone.cities.some((c: string) => c.toLowerCase().trim() === normalizedCity);
        if (isMatch) {
          matchReason = `Your city (${primaryLocation.city}) is in this zone`;
        }
      }

      // Check radius match
      if (!isMatch && zone.zone_type === "radius" && zone.center_latitude && zone.center_longitude && zone.radius_km) {
        const zoneCenter = {
          latitude: parseFloat(zone.center_latitude.toString()),
          longitude: parseFloat(zone.center_longitude.toString()),
        };
        const distance = mapbox.calculateDistance(zoneCenter, providerCoordinates);
        isMatch = distance <= zone.radius_km;
        if (isMatch) {
          matchReason = `Your location is ${distance.toFixed(1)}km from zone center (within ${zone.radius_km}km radius)`;
        }
      }

      // Check polygon match
      if (!isMatch && zone.zone_type === "polygon" && zone.polygon_coordinates) {
        const polygon = zone.polygon_coordinates;
        if (Array.isArray(polygon) && polygon.length > 0) {
          const ring = Array.isArray(polygon[0]) ? polygon[0] : polygon;
          const polygonCoords = ring.map((coord: any) => {
            if (Array.isArray(coord)) {
              return { longitude: coord[0], latitude: coord[1] };
            }
            return { longitude: coord.lng || coord.longitude, latitude: coord.lat || coord.latitude };
          });

          // Point-in-polygon check
          let inside = false;
          for (let i = 0, j = polygonCoords.length - 1; i < polygonCoords.length; j = i++) {
            const xi = polygonCoords[i].longitude;
            const yi = polygonCoords[i].latitude;
            const xj = polygonCoords[j].longitude;
            const yj = polygonCoords[j].latitude;

            const intersect =
              yi > providerCoordinates.latitude !== yj > providerCoordinates.latitude &&
              providerCoordinates.longitude < ((xj - xi) * (providerCoordinates.latitude - yi)) / (yj - yi) + xi;

            if (intersect) inside = !inside;
          }
          isMatch = inside;
          if (isMatch) {
            matchReason = "Your location is within this polygon zone";
          }
        }
      }

      const zoneWithMatch = {
        ...zone,
        match_reason: matchReason,
        is_suggested: isMatch,
      };

      if (isMatch) {
        suggestedZones.push(zoneWithMatch);
      } else {
        otherZones.push(zoneWithMatch);
      }
    }

    // Sort suggested zones by relevance (postal_code > city > radius > polygon)
    const sortPriority: Record<string, number> = {
      postal_code: 1,
      city: 2,
      radius: 3,
      polygon: 4,
    };

    suggestedZones.sort((a, b) => {
      const priorityA = sortPriority[a.zone_type] || 99;
      const priorityB = sortPriority[b.zone_type] || 99;
      return priorityA - priorityB;
    });

    return successResponse({
      suggested_zones: suggestedZones,
      other_zones: otherZones,
      provider_location: {
        city: primaryLocation.city,
        postal_code: primaryLocation.postal_code,
        coordinates: providerCoordinates,
      },
    });
  } catch (error) {
    return handleApiError(error, "Failed to suggest zones");
  }
}

/**
 * Safety tests for public config endpoints: response shape and no secret fields.
 * These tests assert allowed shapes and forbidden-key checks. Full route integration
 * (with Supabase/Next context) is done via scripts/prod/verify-public-endpoints.mjs
 * against a running server.
 */

import { describe, it, expect } from "vitest";

const FORBIDDEN_IN_RESPONSE = [
  "api_key_server",
  "api_key_secret",
  "secret_key",
  "webhook_secret",
  "rest_api_key",
  "client_secret",
  "access_token",
  "private_key",
  "paystack_secret",
  "amplitude_secret",
  "onesignal_rest",
];

function assertNoSecrets(obj: any, path = ""): string[] {
  if (obj === null || obj === undefined) return [];
  const found: string[] = [];
  const str = JSON.stringify(obj).toLowerCase();
  for (const key of FORBIDDEN_IN_RESPONSE) {
    if (str.includes(key.toLowerCase())) {
      found.push(key + (path ? " in " + path : ""));
    }
  }
  if (typeof obj === "object" && !Array.isArray(obj)) {
    for (const [k, v] of Object.entries(obj)) {
      found.push(...assertNoSecrets(v, path ? `${path}.${k}` : k));
    }
  }
  if (Array.isArray(obj)) {
    obj.forEach((item, i) => found.push(...assertNoSecrets(item, `${path}[${i}]`)));
  }
  return found;
}

describe("Public config response safety (shape and forbidden keys)", () => {
  it("analytics-config allowed keys only", () => {
    const allowed = [
      "api_key_public",
      "environment",
      "enabled_client_portal",
      "enabled_provider_portal",
      "enabled_admin_portal",
      "guides_enabled",
      "surveys_enabled",
      "sampling_rate",
      "debug_mode",
    ];
    const safeConfig = Object.fromEntries(allowed.map((k) => [k, k === "api_key_public" ? "pk_xxx" : true]));
    expect(Object.keys(safeConfig).sort()).toEqual(allowed.sort());
    expect(assertNoSecrets(safeConfig)).toEqual([]);
  });

  it("third-party-config safe shape has no secret keys", () => {
    const safeData = {
      data: {
        onesignal: { app_id: "xxx", safari_web_id: null, enabled: true },
        mapbox: { public_token: "pk.xxx", enabled: true },
      },
      error: null,
    };
    expect(assertNoSecrets(safeData)).toEqual([]);
    const bad = { data: { onesignal: { app_id: "x", rest_api_key: "secret" } }, error: null };
    expect(assertNoSecrets(bad).length).toBeGreaterThan(0);
  });

  it("branding allowed keys only", () => {
    const allowed = ["site_name", "logo_url", "favicon_url", "primary_color", "secondary_color"];
    const safe = {
      data: {
        site_name: "Beautonomi",
        logo_url: "/logo.svg",
        favicon_url: "/favicon.ico",
        primary_color: "#FF0077",
        secondary_color: "#D60565",
      },
      error: null,
    };
    expect(Object.keys((safe as any).data).sort()).toEqual(allowed.sort());
    expect(assertNoSecrets(safe)).toEqual([]);
  });

  it("forbidden key detection catches secret_key", () => {
    const bad = { api_key_public: "x", secret_key: "sk_live" };
    expect(assertNoSecrets(bad).length).toBeGreaterThan(0);
  });
});

