import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";

/**
 * GET /api/public/addons
 * 
 * Get available addons for a service or provider (public endpoint)
 */
export async function GET(request: Request) {
  try {
    const supabase = await getSupabaseServer();
    const { searchParams } = new URL(request.url);
    const serviceId = searchParams.get("service_id");
    const providerId = searchParams.get("provider_id");
    const locationId = searchParams.get("location_id");
    const type = searchParams.get("type");

    let query = supabase
      .from("service_addons")
      .select("*")
      .eq("is_active", true)
      .order("is_recommended", { ascending: false })
      .order("sort_order", { ascending: true })
      .order("name", { ascending: true });

    if (providerId) {
      // Get provider-specific addons and global addons
      query = query.or(`provider_id.eq.${providerId},provider_id.is.null`);
    } else {
      // Only global addons
      query = query.is("provider_id", null);
    }

    if (type) {
      query = query.eq("type", type);
    }

    const { data: addons, error } = await query;

    if (error) {
      console.error("Error fetching addons:", error);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to fetch addons",
            code: "FETCH_ERROR",
          },
        },
        { status: 500 }
      );
    }

    // Filter by location (branch): when location_id provided, only addons available at that location
    let filteredAddons = addons ?? [];
    if (locationId && filteredAddons.length > 0) {
      const addonIds = filteredAddons.map((a: any) => a.id);
      const { data: addonLocs } = await supabase
        .from("addon_locations")
        .select("addon_id")
        .in("addon_id", addonIds)
        .eq("location_id", locationId);
      const addonIdsAtLocation = new Set((addonLocs ?? []).map((r: any) => r.addon_id));
      const { data: allAddonLocs } = await supabase
        .from("addon_locations")
        .select("addon_id")
        .in("addon_id", addonIds);
      const addonIdsWithRestriction = new Set((allAddonLocs ?? []).map((r: any) => r.addon_id));
      filteredAddons = filteredAddons.filter(
        (a: any) => !addonIdsWithRestriction.has(a.id) || addonIdsAtLocation.has(a.id)
      );
    }

    // Filter by service if specified
    if (serviceId && filteredAddons.length > 0) {
      const { data: associations } = await supabase
        .from("service_addon_associations")
        .select("addon_id")
        .eq("service_id", serviceId);

      const associatedAddonIds = new Set(associations?.map((a: any) => a.addon_id) || []);

      // Include addons that are either:
      // 1. Associated with this service
      // 2. Not restricted to specific services (no associations)
      const { data: allAssociations } = await supabase
        .from("service_addon_associations")
        .select("addon_id");

      const addonsWithRestrictions = new Set(
        allAssociations?.map((a: any) => a.addon_id) || []
      );

      const byService = filteredAddons.filter((addon: any) => {
        if (!addonsWithRestrictions.has(addon.id)) return true;
        return associatedAddonIds.has(addon.id);
      });

      return NextResponse.json({
        data: byService,
        error: null,
      });
    }

    return NextResponse.json({
      data: filteredAddons,
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/public/addons:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch addons",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

/**
 * POST /api/public/ads/event - Record ad event (click or book) from customer app.
 * Body: { event_type: 'click' | 'book', campaign_id, provider_id, idempotency_key?, attribution? }
 */

import { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const eventType = body.event_type === "click" || body.event_type === "book" ? body.event_type : null;
    const campaignId = body.campaign_id ?? null;
    const providerId = body.provider_id ?? null;
    const idempotencyKey = body.idempotency_key ?? null;
    const attribution = body.attribution && typeof body.attribution === "object" ? body.attribution : {};

    if (!eventType || !campaignId || !providerId) {
      return NextResponse.json(
        { data: null, error: { message: "event_type, campaign_id, and provider_id are required", code: "VALIDATION" } },
        { status: 400 }
      );
    }

    const supabase = getSupabaseAdmin();
    const key = idempotencyKey ?? `public:${eventType}:${campaignId}:${providerId}:${Date.now()}`;
    const { error } = await supabase.from("ads_events").upsert(
      {
        campaign_id: campaignId,
        provider_id: providerId,
        event_type: eventType,
        idempotency_key: key,
        attribution: { ...attribution, source: "public_api" },
      },
      { onConflict: "idempotency_key", ignoreDuplicates: true }
    );

    if (error) throw error;
    return NextResponse.json({ data: { recorded: true }, error: null });
  } catch (error: any) {
    console.warn("Ads event record failed:", error);
    return NextResponse.json(
      { data: null, error: { message: error?.message ?? "Failed to record event", code: "INTERNAL" } },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";

export const dynamic = "force-dynamic";
export const revalidate = 300; // 5 minutes

/**
 * Public endpoint to get Amplitude analytics configuration
 * Returns safe config (no server keys) for client-side SDK initialization
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const environment = searchParams.get("environment") || "production";

    const supabase = getSupabaseAdmin();

    const { data, error } = await supabase
      .from("amplitude_integration_config")
      .select("api_key_public, environment, enabled_client_portal, enabled_provider_portal, enabled_admin_portal, guides_enabled, surveys_enabled, sampling_rate, debug_mode")
      .eq("environment", environment)
      .maybeSingle();

    if (error) {
      console.error("Error fetching Amplitude config:", error);
      // Return empty config if error (SDK won't initialize)
      return NextResponse.json({
        api_key_public: null,
        environment: environment,
        enabled_client_portal: false,
        enabled_provider_portal: false,
        enabled_admin_portal: false,
        guides_enabled: false,
        surveys_enabled: false,
        sampling_rate: 1.0,
        debug_mode: false,
      });
    }

    if (!data) {
      // No config found for this environment
      return NextResponse.json({
        api_key_public: null,
        environment: environment,
        enabled_client_portal: false,
        enabled_provider_portal: false,
        enabled_admin_portal: false,
        guides_enabled: false,
        surveys_enabled: false,
        sampling_rate: 1.0,
        debug_mode: false,
      });
    }

    // Return safe config (no server keys) - pick only allowed fields to prevent leaks
    const safeConfig = {
      api_key_public: data.api_key_public,
      environment: data.environment,
      enabled_client_portal: data.enabled_client_portal,
      enabled_provider_portal: data.enabled_provider_portal,
      enabled_admin_portal: data.enabled_admin_portal,
      guides_enabled: data.guides_enabled,
      surveys_enabled: data.surveys_enabled,
      sampling_rate: data.sampling_rate,
      debug_mode: data.debug_mode,
    };
    return NextResponse.json(safeConfig, {
      headers: {
        "Cache-Control": "public, s-maxage=300, stale-while-revalidate=600",
      },
    });
  } catch (error: any) {
    console.error("Error in analytics-config endpoint:", error);
    // Return safe defaults on error
    return NextResponse.json({
      api_key_public: null,
      environment: "production",
      enabled_client_portal: false,
      enabled_provider_portal: false,
      enabled_admin_portal: false,
      guides_enabled: false,
      surveys_enabled: false,
      sampling_rate: 1.0,
      debug_mode: false,
    });
  }
}

