    })
    .optional()
    .nullable(),
  guest_fingerprint_hash: z.string().optional().nullable(),
  resource_ids: z.array(z.string().uuid()).optional(),
});

const HOLD_EXPIRY_MINUTES = 7;

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const parsed = createHoldSchema.safeParse(body);

    if (!parsed.success) {
      return handleApiError(
        new Error(parsed.error.issues.map((e) => e.message).join(", ")),
        "Validation failed",
        "VALIDATION_ERROR",
        400
      );
    }

    const {
      provider_id,
      staff_id: bodyStaffId,
      services,
      start_at,
      end_at,
      location_type,
      location_id,
      address,
      guest_fingerprint_hash,
      resource_ids,
    } = parsed.data;

    const startDate = new Date(start_at);
    const endDate = new Date(end_at);
    if (endDate <= startDate) {
      return handleApiError(
        new Error("end_at must be after start_at"),
        "Invalid time range",
        "VALIDATION_ERROR",
        400
      );
    }

    const supabase = getSupabaseAdmin();
    const nowIso = new Date().toISOString();

    // Rate limiting
    const rateLimit = checkHoldRateLimit(request, guest_fingerprint_hash || null);
    if (!rateLimit.allowed) {
      return handleApiError(
        new Error(rateLimit.reason),
        rateLimit.reason!,
        "RATE_LIMIT_EXCEEDED",
        429
      );
    }

    // Max 1 active, non-expired hold per fingerprint
    if (guest_fingerprint_hash) {
      const { data: activeHold } = await supabase
        .from("booking_holds")
        .select("id")
        .eq("guest_fingerprint_hash", guest_fingerprint_hash)
        .eq("hold_status", "active")
        .gt("expires_at", nowIso)
        .limit(1)
        .maybeSingle();
      if (activeHold) {
        return handleApiError(
          new Error("You already have an active booking hold. Please complete or cancel it first."),
          "You already have an active booking hold. Please complete or cancel it first.",
          "ACTIVE_HOLD_EXISTS",
          429
        );
      }
    }

    // Load provider
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("id, currency, status")
      .eq("id", provider_id)
      .single();

    if (providerError || !provider) {
      return handleApiError(
        new Error("Provider not found"),
        "Provider not found",
        "NOT_FOUND",
        404
      );
    }

    if (provider.status !== "active") {
      return handleApiError(
        new Error("Provider is not available for booking"),
        "Provider is not available",
        "PROVIDER_INACTIVE",
        400
      );
    }

    const currency = provider.currency || "ZAR";

    // Load offerings and build snapshot
    const offeringIds = services.map((s) => s.offering_id);
    const { data: offerings, error: offeringsError } = await supabase
      .from("offerings")
      .select(
        "id, provider_id, duration_minutes, buffer_minutes, price, currency, is_active, at_home_price_adjustment, supports_at_home"
      )
      .in("id", offeringIds);

    if (offeringsError) throw offeringsError;

    const offeringById = new Map(
      (offerings || []).map((o) => [o.id, o])
    );

    for (const s of services) {
      const off = offeringById.get(s.offering_id);
      if (!off || off.provider_id !== provider_id || !off.is_active) {
        return handleApiError(
          new Error("Invalid service selection"),
          "Invalid service selection",
          "VALIDATION_ERROR",
          400
        );
      }
      if (
        location_type === "at_home" &&
        off.supports_at_home === false
      ) {
        return handleApiError(
          new Error("One or more services do not support at-home"),
          "At-home not supported",
          "VALIDATION_ERROR",
          400
        );
      }
    }

    // Resolve staff_id: use body staff_id or first service's staff_id. null = "anyone" mode (assign at confirm).
    const staffId = bodyStaffId ?? services[0]?.staff_id ?? null;

    // Build booking_services_snapshot
    let cursor = new Date(startDate);
    const bookingServicesSnapshot: Array<{
      offering_id: string;
      staff_id: string | null;
      duration_minutes: number;
      price: number;
      currency: string;
      scheduled_start_at: string;
      scheduled_end_at: string;
    }> = [];

    for (const s of services) {
      const off = offeringById.get(s.offering_id);
      if (!off) continue;
      const duration = Number(off.duration_minutes || 0);
      const price =
        location_type === "at_home" && off.at_home_price_adjustment
          ? Number(off.price || 0) + Number(off.at_home_price_adjustment || 0)
          : Number(off.price || 0);
      const start = new Date(cursor);
      const end = new Date(cursor.getTime() + duration * 60000);
      bookingServicesSnapshot.push({
        offering_id: off.id,
        staff_id: s.staff_id ?? staffId,
        duration_minutes: duration,
        price,
        currency: off.currency || currency,
        scheduled_start_at: start.toISOString(),
        scheduled_end_at: end.toISOString(),
      });
      cursor = new Date(end.getTime() + Number(off.buffer_minutes || 0) * 60000);
    }

    const lastOffering = offeringById.get(services[services.length - 1].offering_id);
    const bufferMinutes = Number(lastOffering?.buffer_minutes || 15);
    // If client sent full block end (slot start + totalSpan including last buffer), don't add buffer again
    const expectedBlockEnd = new Date(cursor.getTime() + bufferMinutes * 60000);
    const clientSentFullSpan = endDate.getTime() >= expectedBlockEnd.getTime() - 60000;
    const bufferForConflict = clientSentFullSpan ? 0 : bufferMinutes;

    // Check for conflicts: existing bookings (skip when staff_id is null / "anyone" mode)
    if (staffId) {
      const conflictResult = await checkBookingConflict(
        supabase as any,
        staffId,
        startDate,
        endDate,
        bufferForConflict
      );
      if (conflictResult.hasConflict) {
        return handleApiError(
          new Error("This time slot is no longer available. Please select another time."),
          "This time slot is no longer available. Please select another time.",
          "CONFLICT",
          409
        );
      }
    }

    // Check for overlapping active, non-expired holds: same staff, or same provider when staff_id is null (anyone mode)
    const overlapQuery = supabase
      .from("booking_holds")
      .select("id")
      .eq("hold_status", "active")
      .gt("expires_at", nowIso)
      .lt("start_at", endDate.toISOString())
      .gt("end_at", startDate.toISOString());
    if (staffId) {
      overlapQuery.eq("staff_id", staffId);
    } else {
      overlapQuery.eq("provider_id", provider_id);
    }
    const { data: overlappingHolds } = await overlapQuery.limit(1);

    if (overlappingHolds && overlappingHolds.length > 0) {
      return handleApiError(
        new Error("This time slot is no longer available. Please select another time."),
        "This time slot is no longer available. Please select another time.",
        "CONFLICT",
        409
      );
    }

    // Location validation
    if (location_type === "at_salon" && !location_id) {
      return handleApiError(
        new Error("location_id is required for at_salon bookings"),
        "location_id is required for at_salon",
        "VALIDATION_ERROR",
        400
      );
    }
    if (location_type === "at_home" && !address) {
      return handleApiError(
        new Error("address is required for at_home bookings"),
        "address is required for at_home",
        "VALIDATION_ERROR",
        400
      );
    }

    let holdMetadata: Record<string, any> = {};
    if (location_type === "at_home" && address && address.latitude != null && address.longitude != null) {
      try {
        const travelResult = await calculateTravelFeeForHold(supabase, provider_id, {
          latitude: address.latitude,
          longitude: address.longitude,
          line1: address.line1,
          city: address.city,
          country: address.country,
          postal_code: address.postal_code,
        });
        holdMetadata = {
          travel_fee: travelResult.withinServiceArea ? travelResult.travelFee : 0,
          travel_distance_km: travelResult.distanceKm,
        };
      } catch {
        holdMetadata = { travel_fee: 0, travel_distance_km: 0 };
      }
    }
    if (resource_ids && resource_ids.length > 0) {
      holdMetadata = { ...holdMetadata, resource_ids };
    }

    const expiresAt = new Date(Date.now() + HOLD_EXPIRY_MINUTES * 60 * 1000);

    const { data: hold, error: insertError } = await supabase
      .from("booking_holds")
      .insert({
        provider_id,
        staff_id: staffId,
        booking_services_snapshot: bookingServicesSnapshot,
        start_at: start_at,
        end_at: end_at,
        location_type,
        location_id: location_id || null,
        address_snapshot: address || null,
        hold_status: "active",
        expires_at: expiresAt.toISOString(),
        created_by_user_id: null,
        guest_fingerprint_hash: guest_fingerprint_hash || null,
        metadata: holdMetadata,
      })
      .select("id, expires_at")
      .single();

    if (insertError) {
      // DB exclusion constraint: only one active non-expired hold per (staff|provider) and time range
      const err = insertError as { code?: string; details?: string; message?: string };
      const isExclusionViolation =
        err.code === "23P01" ||
        [err.details, err.message].some(
          (t) =>
            t &&
            (t.includes("booking_holds_no_overlap_staff") ||
              t.includes("booking_holds_no_overlap_provider_anyone"))
        );
      if (isExclusionViolation) {
        return handleApiError(
          new Error("This time slot is no longer available. Please select another time."),
          "This time slot is no longer available. Please select another time.",
          "CONFLICT",
          409
        );
      }
      throw insertError;
    }

    incrementHoldRateLimit(request, guest_fingerprint_hash || null);

    if (!hold) {
      return handleApiError(
        new Error("Failed to create hold"),
        "Failed to create hold",
        "CREATE_ERROR",
        500
      );
    }

    return successResponse({
      hold_id: hold.id,
      expires_at: hold.expires_at,
    });
  } catch (error) {
    return handleApiError(error, "Failed to create booking hold");
  }
}

import { SupabaseClient } from "@supabase/supabase-js";
import { handleApiError } from "@/lib/supabase/api-helpers";
import type { BookingDraft } from "@/types/beautonomi";
import type { ValidatedBookingData } from "./validate-booking";

// ΓöÇΓöÇΓöÇ Interfaces ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface CreatedBookingResult {
  booking: any;
  createdBookingServices: any[];
}

// ΓöÇΓöÇΓöÇ Main function ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Create the booking row + booking_services in the database via the atomic
 * `create_booking_with_locking` RPC, then insert addons, products, group
 * booking records, resource assignments, and double-booking events.
 *
 * Returns either a `CreatedBookingResult` or a NextResponse error.
 */
export async function createBookingRecord(
  supabase: SupabaseClient,
  adminSupabase: SupabaseClient,
  draft: BookingDraft,
  validatedDraft: Record<string, any>,
  v: ValidatedBookingData,
  userId: string
): Promise<CreatedBookingResult | Response> {
  // ΓöÇΓöÇ Build the booking row ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const bookingData: Record<string, any> = {
    booking_number: "", // Set by DB trigger
    customer_id: v.customerId,
    provider_id: draft.provider_id,
    status: v.appointmentStatus,
    location_type: draft.location_type,
    location_id: (draft as any).location_id || null,
    booking_source: "online",
    scheduled_at: draft.selected_datetime,
    package_id: (draft as any).package_id || null,
    subtotal: v.subtotal,
    travel_fee: v.travelFee,
    service_fee_config_id: v.serviceFeeConfigId,
    service_fee_percentage: v.serviceFeePercentage,
    service_fee_amount: v.serviceFeeAmount,
    service_fee_paid_by: "customer",
    tip_amount: v.tipAmount,
    tax_amount: v.taxAmount,
    discount_amount: v.packageDiscountAmount + v.promoDiscountAmount,
    discount_code: v.promoCode || null,
    promotion_discount_amount: v.promoDiscountAmount,
    membership_discount_amount: v.membershipDiscountAmount,
    total_amount: v.totalAmount,
    currency: v.currency,
    payment_status: "pending" as const,
    special_requests: draft.special_requests || null,
    loyalty_points_earned: v.loyaltyPointsEarned,
    promotion_id: v.promotionId,
    membership_plan_id: v.membershipPlanId,
  };

  // Flatten address for at-home bookings
  if (draft.location_type === "at_home" && draft.address) {
    bookingData.address_line1 = draft.address.line1;
    bookingData.address_line2 = draft.address.line2 || null;
    bookingData.address_city = draft.address.city;
    bookingData.address_state = draft.address.state || null;
    bookingData.address_country = draft.address.country;
    bookingData.address_postal_code = draft.address.postal_code || null;
    bookingData.address_latitude = draft.address.latitude ?? null;
    bookingData.address_longitude = draft.address.longitude ?? null;
  }

  // Group booking flag
  if (validatedDraft.is_group_booking) {
    bookingData.is_group_booking = true;
  }

  // ΓöÇΓöÇ Atomic insert via RPC ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const { data: bookingId, error: bookingError } = await adminSupabase.rpc(
    "create_booking_with_locking",
    {
      p_booking_data: bookingData,
      p_booking_services: v.bookingServicesData,
      p_staff_id: draft.services[0].staff_id || null,
      p_start_at: v.selectedDatetime.toISOString(),
      p_end_at: v.bookingEnd.toISOString(),
    }
  );

  if (bookingError) {
    const msg = (bookingError as { message?: string }).message ?? "";
    if (msg.includes("BOOKING_SLOT_CONFLICT")) {
      return handleApiError(
        new Error("This time slot is no longer available. Please select another time."),
        "This time slot is no longer available. Please select another time.",
        "CONFLICT",
        409
      );
    }
    throw bookingError;
  }

  if (!bookingId) {
    return handleApiError(
      new Error("Failed to create booking"),
      "Failed to create booking",
      "CREATE_ERROR",
      500
    );
  }

  // ΓöÇΓöÇ Fetch the created booking ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const { data: booking, error: fetchError } = await adminSupabase
    .from("bookings")
    .select()
    .eq("id", bookingId)
    .single();

  if (fetchError || !booking) {
    return handleApiError(
      new Error("Failed to fetch created booking"),
      "Failed to fetch created booking",
      "FETCH_ERROR",
      500
    );
  }

  const loyaltyPointsUsed = Number((validatedDraft as any).loyalty_points_used ?? 0);
  if (loyaltyPointsUsed > 0) {
    await adminSupabase
      .from("bookings")
      .update({ loyalty_points_used: loyaltyPointsUsed })
      .eq("id", bookingId);
  }

  // Set guest_name from client_info so booking appears correctly in provider calendar
  const clientInfo = validatedDraft.client_info as { firstName?: string; lastName?: string } | undefined;
  if (clientInfo && (clientInfo.firstName || clientInfo.lastName)) {
    const guestName = [clientInfo.firstName, clientInfo.lastName].filter(Boolean).join(" ").trim();
    if (guestName) {
      await adminSupabase.from("bookings").update({ guest_name: guestName }).eq("id", bookingId);
      (booking as any).guest_name = guestName;
    }
  }

  // ΓöÇΓöÇ Group booking ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  if (v.isGroupBooking && v.groupParticipants && v.groupParticipants.length > 0) {
    const clientInfo = validatedDraft.client_info || {};

    try {
      const { createGroupBooking } = await import("@/lib/bookings/group-booking");
      const { createGroupBookingServices } = await import("@/lib/bookings/group-booking-services");

      // Build servicesMap for all participants (primary + group) so every participant's services get correct timing
      const allOfferingIds = new Set<string>(
        draft.services.map((s: any) => s.offering_id).concat(
          (v.groupParticipants || []).flatMap((p: any) => p.service_ids ?? p.serviceIds ?? [])
        )
      );
      const servicesMap = new Map();
      for (const offeringId of allOfferingIds) {
        const off = v.offeringById.get(offeringId);
        if (!off) continue;
        const primaryService = draft.services.find((s: any) => s.offering_id === offeringId);
        servicesMap.set(offeringId, {
          offering_id: off.id,
          staff_id: primaryService?.staff_id ?? null,
          duration_minutes: Number(off.duration_minutes),
          price: Number(off.price),
          currency: v.currency,
        });
      }

      await createGroupBookingServices(
        adminSupabase,
        booking.id,
        v.selectedDatetime,
        v.groupParticipants.map((p: any, i: number) => ({
          id: p.id || `p-${i}-${Date.now()}`,
          name: p.name,
          serviceIds: p.service_ids ?? p.serviceIds ?? [],
        })),
        servicesMap
      );

      const groupBooking = await createGroupBooking(
        adminSupabase,
        draft.provider_id,
        booking.id,
        [booking.id],
        [
          {
            booking_id: booking.id,
            participant_name: clientInfo.name || booking.guest_name || "Primary Contact",
            participant_email: clientInfo.email || null,
            participant_phone: clientInfo.phone || null,
            is_primary_contact: true,
          },
          ...v.groupParticipants.map((p: any) => ({
            booking_id: booking.id,
            participant_name: p.name,
            participant_email: p.email || null,
            participant_phone: p.phone || null,
            is_primary_contact: false,
          })),
        ]
      );

      (booking as any).group_booking_id = groupBooking.id;
      (booking as any).group_booking_ref = groupBooking.ref_number;

      await adminSupabase
        .from("bookings")
        .update({ group_booking_id: groupBooking.id })
        .eq("id", booking.id);

      // Send group notifications (best-effort)
      try {
        const { sendGroupBookingNotifications } = await import(
          "@/lib/bookings/group-booking-notifications"
        );
        await sendGroupBookingNotifications(supabase, booking.id, groupBooking.id);
      } catch (notifError) {
        console.error("Failed to send group booking notifications:", notifError);
      }
    } catch (err: any) {
      console.error("Failed to create group booking:", err);
      // If table doesn't exist, that's okay ΓÇô feature not fully deployed yet
      if (!err.message?.includes("does not exist") && !err.code?.includes("42P01")) {
        // Log only non-missing-table errors
      }
    }
  }

  // ΓöÇΓöÇ Fetch created booking_services ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const { error: bookingServicesError, data: createdBookingServices } = await adminSupabase
    .from("booking_services")
    .select()
    .eq("booking_id", booking.id);

  if (bookingServicesError) throw bookingServicesError;

  // ΓöÇΓöÇ Resource assignments ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const draftResourceIds = (draft as any).resource_ids as string[] | undefined;
  if (v.allResourceIds.length > 0 && createdBookingServices) {
    const { assignResourcesToBooking, getRequiredResourcesForOffering } = await import(
      "@/lib/resources/assignment"
    );
    const resourceAssignments: any[] = [];
    let resourceCursor = 0;

    for (const service of createdBookingServices) {
      const requiredResources = await getRequiredResourcesForOffering(
        supabase,
        service.offering_id
      );
      const count = requiredResources.length;
      if (count === 0) continue;

      if (Array.isArray(draftResourceIds) && resourceCursor < draftResourceIds.length) {
        for (let i = 0; i < count && resourceCursor < draftResourceIds.length; i++) {
          resourceAssignments.push({
            booking_id: booking.id,
            booking_service_id: service.id,
            resource_id: draftResourceIds[resourceCursor++],
            scheduled_start_at: service.scheduled_start_at,
            scheduled_end_at: service.scheduled_end_at,
          });
        }
      } else {
        for (const resourceId of requiredResources) {
          resourceAssignments.push({
            booking_id: booking.id,
            booking_service_id: service.id,
            resource_id: resourceId,
            scheduled_start_at: service.scheduled_start_at,
            scheduled_end_at: service.scheduled_end_at,
          });
        }
      }
    }

    if (resourceAssignments.length > 0) {
      await assignResourcesToBooking(adminSupabase, resourceAssignments);
    }
  }

  // ΓöÇΓöÇ Double-booking override event ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  if (v.allowOverride && v.conflictResult?.hasConflict) {
    await adminSupabase.from("booking_events").insert({
      booking_id: booking.id,
      event_type: "double_booking_override",
      event_data: {
        reason: "Manual override allowed by provider settings",
        warning_acknowledged: true,
        conflicting_bookings:
          v.conflictResult.conflictingBookings?.map((cb: any) => cb.booking_id) || [],
      },
      created_by: userId,
    });
  }

  // ΓöÇΓöÇ Addons ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const addonIds = (draft.addons || []) as string[];
  if (addonIds.length > 0) {
    const bookingAddonsRows = addonIds.map((id) => ({
      booking_id: booking.id,
      addon_id: id,
      quantity: 1,
      price: Number(v.addonById.get(id)?.price || 0),
      currency: v.currency,
    }));
    const { error: bookingAddonsError } = await adminSupabase
      .from("booking_addons")
      .insert(bookingAddonsRows);
    if (bookingAddonsError) throw bookingAddonsError;
  }

  // ΓöÇΓöÇ Products ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const products = (draft as any).products || [];
  if (products.length > 0) {
    const primaryStaffId = draft.services?.[0]?.staff_id ?? null;
    const bookingProductsRows = products.map((product: any) => ({
      booking_id: booking.id,
      product_id: product.productId,
      product_variant_id: product.productVariantId ?? null,
      quantity: product.quantity,
      unit_price: product.unitPrice,
      total_price: product.totalPrice,
      currency: v.currency,
      staff_id: primaryStaffId,
    }));

    const { error: bookingProductsError } = await adminSupabase
      .from("booking_products")
      .insert(bookingProductsRows);
    if (bookingProductsError) throw bookingProductsError;

    // Update stock (variant or product-level)
    for (const product of products) {
      if (product.productVariantId) {
        try {
          await (adminSupabase.rpc as any)("decrement_product_variant_stock", {
            p_variant_id: product.productVariantId,
            p_quantity: product.quantity,
          });
        } catch {
          const { data: vrow } = await adminSupabase
            .from("product_variants")
            .select("quantity")
            .eq("id", product.productVariantId)
            .single();
          if (vrow) {
            await adminSupabase
              .from("product_variants")
              .update({ quantity: Math.max(0, (vrow.quantity ?? 0) - product.quantity) })
              .eq("id", product.productVariantId);
          }
        }
      } else {
        const productData = v.productById.get((product as any).productId ?? product.product_id);
        if (productData?.track_stock_quantity) {
          const newQuantity = (productData.quantity || 0) - product.quantity;
          await adminSupabase
            .from("products")
            .update({ quantity: Math.max(0, newQuantity) })
            .eq("id", product.productId);
        }
      }
    }
  }

  return {
    booking,
    createdBookingServices: createdBookingServices || [],
  };
}

import { SupabaseClient } from "@supabase/supabase-js";
import { trackServer } from "@/lib/analytics/amplitude/server";
import {
  EVENT_BOOKING_CONFIRMED,
  EVENT_BOOKING_HOLD_CREATED,
} from "@/lib/analytics/amplitude/types";
import type { BookingDraft } from "@/types/beautonomi";
import type { ValidatedBookingData } from "./validate-booking";

// ΓöÇΓöÇΓöÇ Interfaces ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface PostBookingInput {
  supabase: SupabaseClient;
  draft: BookingDraft;
  validatedDraft: Record<string, any>;
  v: ValidatedBookingData;
  booking: any;
  paymentUrl: string | null;
  savedPaymentMethodId?: string | null;
}

// ΓöÇΓöÇΓöÇ Main function ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Execute post-booking side effects that should not block the booking
 * response (cache invalidation, waitlist matching, analytics).
 *
 * All errors are swallowed so a failed side-effect never breaks the booking.
 */
export async function postBookingEffects(input: PostBookingInput): Promise<void> {
  const { supabase, draft, validatedDraft, v, booking, savedPaymentMethodId } = input;

  // ΓöÇΓöÇ Invalidate availability cache ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  try {
    const { invalidateAvailabilityCache } = await import(
      "@/lib/availability/cache-invalidation"
    );
    const bookedDate = new Date(draft.selected_datetime).toISOString().split("T")[0];
    const firstStaffId = draft.services[0]?.staff_id;
    if (firstStaffId) {
      await invalidateAvailabilityCache(supabase, firstStaffId, bookedDate);
    }
  } catch (error) {
    console.error("Error invalidating availability cache:", error);
  }

  // ΓöÇΓöÇ Waitlist matching (background, non-blocking) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  Promise.resolve().then(async () => {
    try {
      const { findWaitlistMatches } = await import("@/lib/waitlist/matching");
      const { processWaitlistMatches } = await import("@/lib/waitlist/auto-booking");

      const matches = await findWaitlistMatches(supabase, draft.provider_id);
      await processWaitlistMatches(supabase, matches.slice(0, 5), draft.provider_id);
    } catch (error) {
      console.error("Error checking waitlist after booking creation:", error);
    }
  });

  // ΓöÇΓöÇ Amplitude analytics ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  try {
    const userId = v.customerId || null;
    const holdId = validatedDraft.hold_id;

    if (holdId) {
      await trackServer(
        EVENT_BOOKING_HOLD_CREATED,
        {
          portal: "client",
          provider_id: draft.provider_id,
          hold_id: holdId,
          service_ids: draft.services.map((s) => s.offering_id),
          scheduled_at: draft.selected_datetime,
        },
        userId
      );
    }

    await trackServer(
      EVENT_BOOKING_CONFIRMED,
      {
        portal: "client",
        provider_id: draft.provider_id,
        booking_id: booking.id,
        total_amount: v.totalAmount,
        currency: v.currency,
        service_ids: draft.services.map((s) => s.offering_id),
        location_type: draft.location_type,
        payment_method: savedPaymentMethodId ? "saved_card" : "new_card",
      },
      userId
    );
  } catch (amplitudeError) {
    console.error("[Amplitude] Failed to track booking event:", amplitudeError);
  }
}

import { SupabaseClient } from "@supabase/supabase-js";
import { handleApiError } from "@/lib/supabase/api-helpers";
import { isFeatureEnabledServer } from "@/lib/server/feature-flags";
import { convertToSmallestUnit, generateTransactionReference } from "@/lib/payments/paystack";
import { initializePaystackTransaction } from "@/lib/payments/paystack-server";
import { chargeAuthorization } from "@/lib/payments/paystack-complete";
import { getAppointmentSettingsFromDB } from "@/lib/provider-portal/appointment-settings";
import type { BookingDraft } from "@/types/beautonomi";
import type { ValidatedBookingData } from "./validate-booking";

// ΓöÇΓöÇΓöÇ Interfaces ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface PaymentResult {
  paymentUrl: string | null;
}

export interface ProcessPaymentInput {
  supabase: SupabaseClient;
  supabaseAdmin: SupabaseClient;
  draft: BookingDraft;
  validatedDraft: Record<string, any>;
  v: ValidatedBookingData;
  booking: any;
}

// ΓöÇΓöÇΓöÇ Main function ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Process the payment for a booking.
 *
 * Handles: deposit calculation, gift card reservation, wallet debit,
 * Paystack card payment (new or saved), and cash-payment bookings.
 *
 * Returns either a `PaymentResult` or a NextResponse error.
 */
export async function processPayment(
  input: ProcessPaymentInput
): Promise<PaymentResult | Response> {
  const { supabase, supabaseAdmin, draft, validatedDraft, v, booking } = input;

  const paymentMethod = validatedDraft.payment_method || "card";
  const paymentOption = validatedDraft.payment_option || "deposit";

  // ΓöÇΓöÇ Determine amount to collect ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  let amountToCollect = v.totalAmount;
  if (v.provider.requires_deposit) {
    const pct = Number(v.provider.deposit_percentage || 30);
    const deposit = Math.ceil((v.totalAmount * pct) / 100);
    amountToCollect = paymentOption === "full" ? v.totalAmount : deposit;
  }

  // ΓöÇΓöÇ Gift card reservation ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const giftCardCode = (validatedDraft.gift_card_code || "").toString().trim().toUpperCase();
  let giftCardAmountApplied = 0;
  let giftCardId: string | null = null;

  if (giftCardCode && amountToCollect > 0) {
    const giftCardsEnabled = await isFeatureEnabledServer("gift_cards");
    if (!giftCardsEnabled) {
      return handleApiError(
        new Error("Gift cards are currently unavailable"),
        "Gift cards are currently unavailable.",
        "FEATURE_DISABLED",
        400
      );
    }
    const applyAmount = Math.max(0, amountToCollect);
    if (applyAmount > 0) {
      const { data: reserved, error: reserveError } = await (supabase.rpc as any)(
        "reserve_gift_card_redemption",
        {
          p_code: giftCardCode,
          p_amount: applyAmount,
          p_booking_id: booking.id,
          p_currency: v.currency,
        }
      );

      if (reserveError) {
        return handleApiError(
          reserveError,
          reserveError.message || "Invalid gift card",
          "GIFT_CARD_INVALID",
          400
        );
      }

      const row = Array.isArray(reserved) ? reserved[0] : reserved;
      giftCardId = row?.gift_card_id || null;
      giftCardAmountApplied = applyAmount;

      await (supabase.from("bookings") as any)
        .update({
          gift_card_id: giftCardId,
          gift_card_amount: giftCardAmountApplied,
        })
        .eq("id", booking.id);

      amountToCollect = Math.max(0, amountToCollect - giftCardAmountApplied);
    }
  }

  // Capture gift card immediately if no card payment or nothing left
  if (giftCardAmountApplied > 0 && (paymentMethod !== "card" || amountToCollect <= 0)) {
    await (supabase.rpc as any)("capture_gift_card_redemption", { p_booking_id: booking.id });
  }

  // ΓöÇΓöÇ Wallet application ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const useWallet = Boolean(validatedDraft.use_wallet);
  let walletAmountApplied = 0;

  if (useWallet && amountToCollect > 0) {
    const walletEnabled = await isFeatureEnabledServer("payment_wallet");
    if (!walletEnabled) {
      return handleApiError(
        new Error("Wallet payments are currently unavailable"),
        "Wallet payments are currently unavailable.",
        "FEATURE_DISABLED",
        400
      );
    }
    try {
      const { data: wallet } = await supabase
        .from("user_wallets")
        .select("balance, currency")
        .eq("user_id", v.customerId)
        .maybeSingle();

      const walletBalance = Number((wallet as any)?.balance || 0);
      if (walletBalance > 0) {
        walletAmountApplied = Math.min(walletBalance, amountToCollect);

        await (supabase.rpc as any)("wallet_debit_self", {
          p_amount: walletAmountApplied,
          p_description: `Wallet spend for booking ${booking.booking_number}`,
          p_reference_id: booking.id,
          p_reference_type: "booking",
        });

        await (supabase.from("bookings") as any)
          .update({ wallet_amount: walletAmountApplied })
          .eq("id", booking.id);

        amountToCollect = Math.max(0, amountToCollect - walletAmountApplied);
      }
    } catch (e: any) {
      return handleApiError(e, e?.message || "Wallet payment failed", "WALLET_ERROR", 400);
    }
  }

  // ΓöÇΓöÇ Fully covered by gift card / wallet ΓåÆ mark paid immediately ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  if (amountToCollect <= 0) {
    const appointmentSettings = await getAppointmentSettingsFromDB(
      supabaseAdmin,
      draft.provider_id
    );
    const shouldAutoConfirmStatus = !appointmentSettings.requireConfirmationForBookings;

    const loyaltyPointsUsed = Number((validatedDraft as any).loyalty_points_used ?? 0);
    if (loyaltyPointsUsed > 0) {
      await (supabase.from("bookings") as any)
        .update({ loyalty_points_used: loyaltyPointsUsed })
        .eq("id", booking.id);
      try {
        await (supabase.from("loyalty_point_transactions") as any).insert({
          user_id: v.customerId,
          points: loyaltyPointsUsed,
          transaction_type: "redeemed",
          description: `Redeemed for booking ${booking.booking_number}`,
          reference_id: booking.id,
          reference_type: "booking",
        });
      } catch (e: any) {
        console.error("Loyalty points deduction (no-gateway path):", e?.message || e);
      }
    }

    await (supabase.from("bookings") as any)
      .update({
        payment_status: "paid",
        payment_provider: walletAmountApplied > 0 ? "wallet" : "gift_card",
        payment_date: new Date().toISOString(),
        status: shouldAutoConfirmStatus ? "confirmed" : "pending",
      })
      .eq("id", booking.id);

    // ΓöÇΓöÇ Ledger entries (no gateway fees) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    await insertNoGatewayLedger(supabase, {
      booking,
      draft,
      v,
      giftCardAmountApplied,
      giftCardCode,
      walletAmountApplied,
    });

    return { paymentUrl: null };
  }

  // ΓöÇΓöÇ Card payment ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  let paymentUrl: string | null = null;

  if (paymentMethod === "card") {
    const paystackEnabled = await isFeatureEnabledServer("payment_paystack");
    if (!paystackEnabled) {
      return handleApiError(
        new Error("Online card payment is currently unavailable"),
        "Online card payment is currently unavailable. Please choose cash or another method.",
        "FEATURE_DISABLED",
        400
      );
    }

    const { data: userEmailRow } = await supabase
      .from("users")
      .select("email")
      .eq("id", v.customerId)
      .single();

    const email = userEmailRow?.email;
    if (!email) {
      return handleApiError(
        new Error("User email is required for payment"),
        "User email is required",
        "VALIDATION_ERROR",
        400
      );
    }

    const reference = generateTransactionReference("booking", booking.id);
    const callbackUrl = `${process.env.NEXT_PUBLIC_APP_URL || ""}/checkout/success`;

    const savedPaymentMethodId = (draft as any).payment_method_id;
    const saveCard = (draft as any).save_card === true;
    const setAsDefault = (draft as any).set_as_default === true;

    if (savedPaymentMethodId) {
      // ΓöÇΓöÇ Saved card charge ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      const { data: savedCard, error: cardError } = await (supabase.from("payment_methods") as any)
        .select("*")
        .eq("id", savedPaymentMethodId)
        .eq("user_id", v.customerId)
        .eq("is_active", true)
        .eq("provider", "paystack")
        .single();

      if (cardError || !savedCard) {
        return handleApiError(
          new Error("Saved payment method not found"),
          "Saved payment method not found or invalid",
          "NOT_FOUND",
          404
        );
      }

      const loyaltyPointsUsed = Number((validatedDraft as any).loyalty_points_used ?? 0);
      const chargeResult = await chargeAuthorization(
        savedCard.provider_payment_method_id,
        email,
        convertToSmallestUnit(amountToCollect),
        {
          booking_id: booking.id,
          customer_id: v.customerId,
          amount_to_collect: amountToCollect,
          gift_card_amount_applied: giftCardAmountApplied,
          gift_card_code: giftCardCode || null,
          wallet_amount_applied: walletAmountApplied,
          currency: v.currency,
          tip_amount: v.tipAmount,
          tax_amount: v.taxAmount,
          travel_fee: v.travelFee,
          service_fee_amount: v.serviceFeeAmount,
          service_fee_percentage: v.serviceFeePercentage,
          commission_base: v.commissionBase,
          payment_method_id: savedPaymentMethodId,
          hold_id: validatedDraft.hold_id || null,
          loyalty_points_used: loyaltyPointsUsed > 0 ? loyaltyPointsUsed : undefined,
        }
      );

      if (!chargeResult.status) {
        return handleApiError(
          new Error(chargeResult.message || "Payment failed"),
          "Failed to charge saved card",
          "PAYMENT_FAILED",
          400
        );
      }

      paymentUrl = null;

      await (supabase.from("bookings") as any)
        .update({
          payment_reference: chargeResult.data.reference,
          payment_provider: "paystack",
          payment_status: "pending",
        })
        .eq("id", booking.id);

      await (supabase.from("payments") as any).insert({
        booking_id: booking.id,
        user_id: v.customerId,
        provider_id: draft.provider_id,
        payment_number: "",
        amount: amountToCollect,
        currency: v.currency,
        status: "pending",
        payment_provider: "paystack",
        payment_provider_transaction_id: chargeResult.data.reference,
        payment_provider_response: chargeResult,
        payment_method_id: savedPaymentMethodId,
        description: `Payment for booking ${booking.booking_number}`,
        metadata: {
          payment_option: v.provider.requires_deposit ? paymentOption : "full",
          gift_card_amount_applied: giftCardAmountApplied,
          gift_card_code: giftCardCode || null,
          wallet_amount_applied: walletAmountApplied,
          saved_card_used: true,
        },
      });
    } else {
      // ΓöÇΓöÇ New card (Paystack redirect) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      const loyaltyPointsUsed = Number((validatedDraft as any).loyalty_points_used ?? 0);
      const paystackData = await initializePaystackTransaction({
        email,
        amountInSmallestUnit: convertToSmallestUnit(amountToCollect),
        currency: v.currency,
        reference,
        callback_url: callbackUrl,
        metadata: {
          booking_id: booking.id,
          customer_id: v.customerId,
          amount_to_collect: amountToCollect,
          gift_card_amount_applied: giftCardAmountApplied,
          gift_card_code: giftCardCode || null,
          wallet_amount_applied: walletAmountApplied,
          currency: v.currency,
          tip_amount: v.tipAmount,
          tax_amount: v.taxAmount,
          travel_fee: v.travelFee,
          service_fee_amount: v.serviceFeeAmount,
          service_fee_percentage: v.serviceFeePercentage,
          commission_base: v.commissionBase,
          save_card: saveCard,
          set_as_default: setAsDefault,
          hold_id: validatedDraft.hold_id || undefined,
          loyalty_points_used: loyaltyPointsUsed > 0 ? loyaltyPointsUsed : undefined,
        },
      });

      paymentUrl = paystackData?.data?.authorization_url || null;

      await (supabase.from("bookings") as any)
        .update({
          payment_reference: reference,
          payment_provider: "paystack",
          payment_status: "pending",
        })
        .eq("id", booking.id);

      await (supabase.from("payments") as any).insert({
        booking_id: booking.id,
        user_id: v.customerId,
        provider_id: draft.provider_id,
        payment_number: "",
        amount: amountToCollect,
        currency: v.currency,
        status: "pending",
        payment_provider: "paystack",
        payment_provider_transaction_id: reference,
        payment_provider_response: paystackData,
        description: `Payment for booking ${booking.booking_number}`,
        metadata: {
          payment_option: v.provider.requires_deposit ? paymentOption : "full",
          gift_card_amount_applied: giftCardAmountApplied,
          gift_card_code: giftCardCode || null,
          wallet_amount_applied: walletAmountApplied,
          save_card: saveCard,
        },
      });
    }
  }

  return { paymentUrl };
}

// ΓöÇΓöÇΓöÇ Private helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Insert payment_transactions + finance_transactions when no external gateway
 * is involved (gift-card / wallet covers the full amount).
 */
async function insertNoGatewayLedger(
  supabase: SupabaseClient,
  ctx: {
    booking: any;
    draft: BookingDraft;
    v: ValidatedBookingData;
    giftCardAmountApplied: number;
    giftCardCode: string;
    walletAmountApplied: number;
  }
) {
  const { booking, draft, v, giftCardAmountApplied, giftCardCode: _giftCardCode, walletAmountApplied } = ctx;

  // Platform settings for commission
  const { data: settingsRow } = await (supabase.from("platform_settings") as any)
    .select("settings")
    .eq("is_active", true)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  const payoutSettings = (settingsRow as any)?.settings?.payouts || {};
  const commissionEnabled = payoutSettings.commission_enabled !== false;
  const commissionRate = commissionEnabled
    ? (payoutSettings.platform_commission_percentage ?? 0)
    : 0;

  const platformCommission =
    commissionEnabled && commissionRate > 0 ? (v.commissionBase * commissionRate) / 100 : 0;

  const providerEarnings = v.commissionBase - platformCommission + v.travelFee + v.tipAmount;

  const internalRef =
    walletAmountApplied > 0
      ? `wallet_booking_${booking.id}`
      : `giftcard_booking_${booking.id}`;

  await (supabase.from("payment_transactions") as any).insert({
    booking_id: booking.id,
    reference: internalRef,
    amount: v.totalAmount,
    fees: 0,
    net_amount: v.totalAmount,
    status: "success",
    provider: walletAmountApplied > 0 ? "wallet" : "gift_card",
    transaction_type: "charge",
    metadata: {
      kind: walletAmountApplied > 0 ? "wallet_booking" : "gift_card_booking",
      gift_card_amount_applied: giftCardAmountApplied,
      wallet_amount_applied: walletAmountApplied,
    },
    created_at: new Date().toISOString(),
  });

  await (supabase.from("finance_transactions") as any).insert([
    {
      booking_id: booking.id,
      provider_id: draft.provider_id,
      transaction_type: "payment",
      amount: v.commissionBase,
      fees: 0,
      commission: platformCommission,
      net: platformCommission,
      description: `Payment for booking ${booking.booking_number} (gift card)`,
      created_at: new Date().toISOString(),
    },
    {
      booking_id: booking.id,
      provider_id: draft.provider_id,
      transaction_type: "provider_earnings",
      amount: providerEarnings,
      fees: 0,
      commission: 0,
      net: providerEarnings,
      description: `Provider earnings for booking ${booking.booking_number} (gift card)`,
      created_at: new Date().toISOString(),
    },
    {
      booking_id: booking.id,
      provider_id: draft.provider_id,
      transaction_type: "service_fee",
      amount: v.serviceFeeAmount,
      fees: 0,
      commission: 0,
      net: v.serviceFeeAmount,
      description: `Service fee for booking ${booking.booking_number}`,
      created_at: new Date().toISOString(),
    },
    {
      booking_id: booking.id,
      provider_id: draft.provider_id,
      transaction_type: "tip",
      amount: v.tipAmount,
      fees: 0,
      commission: 0,
      net: 0,
      description: `Tip for booking ${booking.booking_number}`,
      created_at: new Date().toISOString(),
    },
    {
      booking_id: booking.id,
      provider_id: draft.provider_id,
      transaction_type: "tax",
      amount: v.taxAmount,
      fees: 0,
      commission: 0,
      net: 0,
      description: `Tax for booking ${booking.booking_number}`,
      created_at: new Date().toISOString(),
    },
    ...(v.travelFee > 0
      ? [
          {
            booking_id: booking.id,
            provider_id: draft.provider_id,
            transaction_type: "travel_fee",
            amount: v.travelFee,
            fees: 0,
            commission: 0,
            net: 0,
            description: `Travel fee for booking ${booking.booking_number}`,
            created_at: new Date().toISOString(),
          },
        ]
      : []),
    ...(v.serviceFeeAmount > 0
      ? [
          {
            booking_id: booking.id,
            provider_id: draft.provider_id,
            transaction_type: "service_fee",
            amount: v.serviceFeeAmount,
            fees: 0,
            commission: 0,
            net: v.serviceFeeAmount,
            description: `Service fee for booking ${booking.booking_number}`,
            created_at: new Date().toISOString(),
          },
        ]
      : []),
  ]);
}

import { SupabaseClient } from "@supabase/supabase-js";
import { handleApiError } from "@/lib/supabase/api-helpers";
import { checkBookingLimit, formatLimitError } from "@/lib/subscriptions/limit-checker";
import type { BookingDraft } from "@/types/beautonomi";

// ΓöÇΓöÇΓöÇ Interfaces ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface ValidatedBookingData {
  customerId: string;
  provider: ProviderRow;
  currency: string;

  /** Maps offering id ΓåÆ offering row */
  offeringById: Map<string, any>;
  /** Maps addon id ΓåÆ addon row */
  addonById: Map<string, any>;
  /** Maps product id ΓåÆ product row */
  productById: Map<string, any>;

  servicesSubtotal: number;
  addonsSubtotal: number;
  productsSubtotal: number;
  travelFee: number;
  packageDiscountAmount: number;
  promoDiscountAmount: number;
  promotionId: string | null;
  promoCode: string;
  subtotal: number;

  membershipPlanId: string | null;
  membershipDiscountAmount: number;
  subtotalAfterMembership: number;
  commissionBase: number;

  tipAmount: number;
  taxRate: number;
  taxAmount: number;

  serviceFeeAmount: number;
  serviceFeePercentage: number;
  serviceFeeConfigId: string | null;

  totalAmount: number;
  loyaltyPointsEarned: number;

  /** Appointment status determined by provider settings */
  appointmentStatus: string;

  /** Conflict-check results */
  allowOverride: boolean;
  conflictResult: ConflictResult | null;

  /** Resource IDs required across all services */
  allResourceIds: string[];

  /** Pre-built booking_services rows + total duration */
  bookingServicesData: any[];
  totalDuration: number;
  bookingEnd: Date;
  selectedDatetime: Date;

  /** Group booking data */
  isGroupBooking: boolean;
  groupParticipants: any[] | null;
}

export interface ProviderRow {
  id: string;
  currency: string | null;
  requires_deposit: boolean;
  deposit_percentage: number | null;
  status: string;
  tax_rate_percent: number | null;
  tips_enabled: boolean | null;
  customer_fee_config_id: string | null;
  minimum_mobile_booking_amount: number | null;
}

export interface ConflictResult {
  hasConflict?: boolean;
  conflictingBookings?: Array<{ booking_id: string }>;
}

// ΓöÇΓöÇΓöÇ Main validation function ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Validate and enrich a booking draft.
 *
 * Returns either a `ValidatedBookingData` object (on success)
 * or a NextResponse error (if any check fails). The caller should
 * check `response instanceof Response` to know which it got.
 */
export async function validateBooking(
  supabase: SupabaseClient,
  supabaseAdmin: SupabaseClient,
  draft: BookingDraft,
  validatedDraft: Record<string, any>,
  userId: string
): Promise<ValidatedBookingData | Response> {
  // ΓöÇΓöÇ Auth / user row ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const { data: userRow, error: userRowError } = await supabase
    .from("users")
    .select("id")
    .eq("id", userId)
    .single();

  if (userRowError || !userRow) {
    return handleApiError(
      new Error("User profile not found"),
      "User profile not found",
      "NOT_FOUND",
      404
    );
  }

  const customerId = userRow.id as string;

  // ΓöÇΓöÇ Location validation ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  if (draft.location_type === "at_salon" && !draft.location_id) {
    return handleApiError(
      new Error("location_id is required for at_salon bookings"),
      "location_id is required for at_salon bookings",
      "VALIDATION_ERROR",
      400
    );
  }
  if (draft.location_type === "at_salon" && draft.location_id) {
    const { data: loc } = await supabase
      .from("provider_locations")
      .select("id, location_type")
      .eq("id", draft.location_id)
      .eq("provider_id", draft.provider_id)
      .eq("is_active", true)
      .maybeSingle();
    if (!loc) {
      return handleApiError(
        new Error("Selected location is not available"),
        "Selected location is not available",
        "VALIDATION_ERROR",
        400
      );
    }
    if ((loc as any).location_type === "base") {
      return handleApiError(
        new Error("This provider does not accept in-studio bookings at this location"),
        "This location is for distance reference only; please book at home.",
        "VALIDATION_ERROR",
        400
      );
    }
  }
  if (draft.location_type === "at_home" && !draft.address) {
    return handleApiError(
      new Error("address is required for at_home bookings"),
      "address is required for at_home bookings",
      "VALIDATION_ERROR",
      400
    );
  }

  // ΓöÇΓöÇ Provider ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const { data: provider, error: providerError } = await supabase
    .from("providers")
    .select(
      "id, currency, requires_deposit, deposit_percentage, status, tax_rate_percent, tips_enabled, customer_fee_config_id, minimum_mobile_booking_amount"
    )
    .eq("id", draft.provider_id)
    .single();

  if (providerError || !provider) {
    return handleApiError(new Error("Provider not found"), "Provider not found", "NOT_FOUND", 404);
  }

  if (provider.status !== "active") {
    return handleApiError(
      new Error("Provider is not available"),
      "Provider is not available",
      "PROVIDER_INACTIVE",
      400
    );
  }

  // ΓöÇΓöÇ Subscription limit ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const bookingLimitCheck = await checkBookingLimit(provider.id);
  if (!bookingLimitCheck.canProceed) {
    return handleApiError(
      new Error(formatLimitError(bookingLimitCheck)),
      formatLimitError(bookingLimitCheck),
      "SUBSCRIPTION_LIMIT_EXCEEDED",
      403
    );
  }

  // ΓöÇΓöÇ Offerings ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  let offeringIds = draft.services.map((s) => s.offering_id);
  const isGroupBookingDraft =
    Boolean(validatedDraft.is_group_booking) && Array.isArray(validatedDraft.group_participants) && validatedDraft.group_participants.length > 0;
  if (isGroupBookingDraft) {
    const groupIds = (validatedDraft.group_participants as any[]).flatMap(
      (p: any) => p.service_ids ?? p.serviceIds ?? []
    );
    offeringIds = [...new Set([...offeringIds, ...groupIds])];
  }
  const { data: offerings, error: offeringsError } = await supabase
    .from("offerings")
    .select(
      "id, provider_id, title, duration_minutes, buffer_minutes, price, currency, supports_at_home, at_home_price_adjustment, is_active"
    )
    .in("id", offeringIds);

  if (offeringsError) throw offeringsError;

  const offeringById = new Map<string, any>();
  for (const o of offerings || []) offeringById.set(o.id, o);

  for (const s of draft.services) {
    const off = offeringById.get(s.offering_id);
    if (!off || off.provider_id !== draft.provider_id || !off.is_active) {
      return handleApiError(
        new Error("Invalid service selection"),
        "Invalid service selection",
        "VALIDATION_ERROR",
        400
      );
    }
    if (draft.location_type === "at_home" && off.supports_at_home === false) {
      return handleApiError(
        new Error("One or more services do not support at-home"),
        "At-home not supported",
        "VALIDATION_ERROR",
        400
      );
    }
  }

  // Validate group participants' offerings (same provider, active)
  if (isGroupBookingDraft) {
    for (const p of validatedDraft.group_participants as any[]) {
      const ids = p.service_ids ?? p.serviceIds ?? [];
      for (const id of ids) {
        const off = offeringById.get(id);
        if (!off || off.provider_id !== draft.provider_id || !off.is_active) {
          return handleApiError(
            new Error("Invalid service selection for group participant"),
            "Invalid service selection",
            "VALIDATION_ERROR",
            400
          );
        }
      }
    }
  }

  // ΓöÇΓöÇ Addons ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const addonIds = draft.addons || [];
  const addonById = new Map<string, any>();
  if (addonIds.length > 0) {
    const { data: addons, error: addonsError } = await supabase
      .from("service_addons")
      .select("id, provider_id, price, currency, is_active")
      .in("id", addonIds);
    if (addonsError) throw addonsError;
    for (const a of addons || []) addonById.set(a.id, a);
    for (const id of addonIds) {
      const a = addonById.get(id);
      if (!a || a.provider_id !== draft.provider_id || !a.is_active) {
        return handleApiError(
          new Error("Invalid add-on selection"),
          "Invalid add-on selection",
          "VALIDATION_ERROR",
          400
        );
      }
    }
    // Branch: at_salon with location_id ΓÇö addon must be available at that location
    if (draft.location_type === "at_salon" && draft.location_id) {
      const { data: addonLocs } = await supabase
        .from("addon_locations")
        .select("addon_id")
        .in("addon_id", addonIds);
      const addonsWithRestriction = new Set((addonLocs ?? []).map((r: any) => r.addon_id));
      const { data: atLocation } = await supabase
        .from("addon_locations")
        .select("addon_id")
        .in("addon_id", addonIds)
        .eq("location_id", draft.location_id);
      const addonIdsAtLocation = new Set((atLocation ?? []).map((r: any) => r.addon_id));
      for (const id of addonIds) {
        if (addonsWithRestriction.has(id) && !addonIdsAtLocation.has(id)) {
          return handleApiError(
            new Error("One or more add-ons are not available at the selected location"),
            "Add-on not available at this location",
            "VALIDATION_ERROR",
            400
          );
        }
      }
    }
  }

  // ΓöÇΓöÇ Products ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const currency = provider.currency || "ZAR";
  const products = (draft as any).products || [];
  const productById = new Map<string, any>();
  let productsSubtotal = 0;

  if (products.length > 0) {
    const productIds = products.map((p: any) => p.productId ?? p.product_id);
    const { data: productRows, error: productsError } = await supabase
      .from("products")
      .select("id, provider_id, name, retail_price, currency, is_active, track_stock_quantity, quantity")
      .in("id", productIds);

    if (productsError) throw productsError;

    for (const p of productRows || []) productById.set(p.id, p);

    for (const product of products) {
      const productData = productById.get((product as any).productId ?? product.product_id);
      if (!productData || productData.provider_id !== draft.provider_id || !productData.is_active) {
        return handleApiError(
          new Error("Invalid product selection"),
          "Invalid product selection",
          "VALIDATION_ERROR",
          400
        );
      }
      if (productData.track_stock_quantity && product.quantity > (productData.quantity || 0)) {
        return handleApiError(
          new Error(`Insufficient stock for ${productData.name}`),
          `Only ${productData.quantity || 0} units available for ${productData.name}`,
          "INSUFFICIENT_STOCK",
          400
        );
      }
      productsSubtotal += (product as any).totalPrice ?? productData.retail_price * product.quantity;
    }
  }

  // ΓöÇΓöÇ Price calculations ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const servicesSubtotal = draft.services.reduce((sum, s) => {
    const off = offeringById.get(s.offering_id);
    const base = Number(off.price || 0);
    const homeAdj = draft.location_type === "at_home" ? Number(off.at_home_price_adjustment || 0) : 0;
    return sum + base + homeAdj;
  }, 0);

  const addonsSubtotal = addonIds.reduce(
    (sum, id) => sum + Number(addonById.get(id)?.price || 0),
    0
  );

  const travelFee = draft.location_type === "at_home" ? (draft.travel_fee || 0) : 0;

  // ΓöÇΓöÇ Package discount ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  let packageDiscountAmount = 0;
  if ((draft as any).package_id) {
    const { data: pkg, error: pkgError } = await supabase
      .from("service_packages")
      .select("id, provider_id, price, currency, discount_percentage")
      .eq("id", (draft as any).package_id)
      .single();
    if (pkgError || !pkg || pkg.provider_id !== draft.provider_id) {
      return handleApiError(
        new Error("Invalid package selection"),
        "Invalid package selection",
        "VALIDATION_ERROR",
        400
      );
    }
    // Branch: at_salon with location_id ΓÇö package must be available at that location
    if (draft.location_type === "at_salon" && draft.location_id) {
      const { data: allPkgLocs } = await supabase
        .from("package_locations")
        .select("location_id")
        .eq("package_id", (draft as any).package_id);
      if (allPkgLocs && allPkgLocs.length > 0) {
        const allowedLocationIds = new Set(allPkgLocs.map((r: any) => r.location_id));
        if (!allowedLocationIds.has(draft.location_id)) {
          return handleApiError(
            new Error("This package is not available at the selected location"),
            "Package not available at this location",
            "VALIDATION_ERROR",
            400
          );
        }
      }
    }
    if (pkg.price !== null && pkg.price !== undefined) {
      packageDiscountAmount = Math.max(0, servicesSubtotal - Number(pkg.price));
    } else if (pkg.discount_percentage) {
      packageDiscountAmount = Math.max(0, (servicesSubtotal * Number(pkg.discount_percentage)) / 100);
    }
  }

  // ΓöÇΓöÇ Promo code ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  let promotionId: string | null = null;
  let promoDiscountAmount = 0;
  const promoCode = (validatedDraft.promotion_code || "").toString().trim().toUpperCase();
  const prePromoSubtotal =
    Math.max(0, servicesSubtotal - packageDiscountAmount) + addonsSubtotal + productsSubtotal + travelFee;

  if (promoCode) {
    const { data: promo } = await (supabase.from("promotions") as any)
      .select(
        "id, code, type, value, min_purchase_amount, max_discount_amount, valid_from, valid_until, usage_limit, usage_count, is_active, location_id"
      )
      .eq("code", promoCode)
      .single();

    if (promo) {
      const now = new Date();
      const validFrom = promo.valid_from ? new Date(promo.valid_from) : null;
      const validUntil = promo.valid_until ? new Date(promo.valid_until) : null;

      const withinWindow = (!validFrom || now >= validFrom) && (!validUntil || now <= validUntil);
      const underLimit = promo.usage_limit == null || (promo.usage_count || 0) < promo.usage_limit;
      const meetsMin = !promo.min_purchase_amount || prePromoSubtotal >= Number(promo.min_purchase_amount);
      // Branch: if promotion is restricted to a location, only valid for at_salon bookings at that location
      const locationOk =
        promo.location_id == null ||
        (draft.location_type === "at_salon" && draft.location_id === promo.location_id);

      if (promo.is_active && withinWindow && underLimit && meetsMin && locationOk) {
        if (promo.type === "percentage")
          promoDiscountAmount = (prePromoSubtotal * Number(promo.value || 0)) / 100;
        else promoDiscountAmount = Number(promo.value || 0);

        if (promo.max_discount_amount)
          promoDiscountAmount = Math.min(promoDiscountAmount, Number(promo.max_discount_amount));
        promoDiscountAmount = Math.max(0, Math.min(promoDiscountAmount, prePromoSubtotal));
        promotionId = promo.id;
      }
    }
  }

  const subtotal = Math.max(0, prePromoSubtotal - promoDiscountAmount);

  // ΓöÇΓöÇ Minimum mobile booking amount ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  if (draft.location_type === "at_home" && provider.minimum_mobile_booking_amount) {
    const minimumAmount = Number(provider.minimum_mobile_booking_amount);
    if (minimumAmount > 0 && subtotal < minimumAmount) {
      return handleApiError(
        new Error(`Minimum order amount for house calls is ${minimumAmount.toFixed(2)} ${currency}`),
        `Minimum order amount for house calls is ${minimumAmount.toFixed(2)} ${currency}. Your current order is ${subtotal.toFixed(2)} ${currency}. Please add more services or book at the salon instead.`,
        "MINIMUM_ORDER_NOT_MET",
        400
      );
    }
  }

  // ΓöÇΓöÇ Commission base ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const commissionBaseBeforeMembership =
    Math.max(0, servicesSubtotal - packageDiscountAmount) + addonsSubtotal + productsSubtotal - promoDiscountAmount;

  // ΓöÇΓöÇ Membership discount ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  let membershipPlanId: string | null = null;
  let membershipDiscountAmount = 0;
  try {
    const { data: membership } = await (supabase.from("user_memberships") as any)
      .select("status, expires_at, plan:membership_plans(id, provider_id, discount_percent, is_active)")
      .eq("user_id", customerId)
      .eq("provider_id", draft.provider_id)
      .maybeSingle();

    const isExpired = membership?.expires_at ? new Date(membership.expires_at) < new Date() : false;
    const active = membership?.status === "active" && !isExpired && membership?.plan?.is_active !== false;

    if (active) {
      membershipPlanId = membership.plan?.id || null;
      const pct = Number(membership.plan?.discount_percent || 0);
      if (pct > 0) {
        membershipDiscountAmount = Math.max(0, (subtotal * pct) / 100);
        membershipDiscountAmount = Math.min(membershipDiscountAmount, subtotal);
      }
    }
  } catch {
    // ignore ΓÇô membership tables may not exist in some dev envs
  }

  const subtotalAfterMembership = Math.max(0, subtotal - membershipDiscountAmount);
  const commissionBase = Math.max(0, commissionBaseBeforeMembership - membershipDiscountAmount);

  // ΓöÇΓöÇ Tips / Tax ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const tipsEnabled = Boolean((provider as any)?.tips_enabled ?? true);
  const tipAmount = tipsEnabled ? (draft.tip_amount || 0) : 0;

  let taxRate = Number((provider as any)?.tax_rate_percent || 0);
  if (taxRate === 0) {
    const { getPlatformDefaultTaxRate } = await import("@/lib/platform-tax-settings");
    taxRate = await getPlatformDefaultTaxRate();
  }
  const taxAmount = taxRate > 0 ? Number(((subtotalAfterMembership * taxRate) / 100).toFixed(2)) : 0;

  // ΓöÇΓöÇ Service fee ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  let serviceFeeAmount = 0;
  let serviceFeePercentage = 0;
  let serviceFeeConfigId: string | null = null;

  if ((provider as any)?.customer_fee_config_id) {
    const { data: feeConfig } = await supabase
      .from("platform_fee_config")
      .select("id, fee_type, fee_percentage, fee_fixed_amount, min_booking_amount, max_fee_amount")
      .eq("id", (provider as any).customer_fee_config_id)
      .eq("is_active", true)
      .single();

    if (feeConfig) {
      serviceFeeConfigId = feeConfig.id;
      const minBookingAmount = Number(feeConfig.min_booking_amount || 0);

      if (subtotalAfterMembership >= minBookingAmount) {
        if (feeConfig.fee_type === "percentage") {
          serviceFeePercentage = Number(feeConfig.fee_percentage || 0);
          serviceFeeAmount = Number(((subtotalAfterMembership * serviceFeePercentage) / 100).toFixed(2));
          if (feeConfig.max_fee_amount) {
            serviceFeeAmount = Math.min(serviceFeeAmount, Number(feeConfig.max_fee_amount));
          }
        } else if (feeConfig.fee_type === "fixed_amount") {
          serviceFeeAmount = Number(feeConfig.fee_fixed_amount || 0);
        }
      }
    }
  }

  // Fallback to platform settings if no provider fee config
  if (serviceFeeAmount === 0 && !serviceFeeConfigId) {
    const { data: platformSettingsRow } = await (supabase.from("platform_settings") as any)
      .select("settings")
      .eq("is_active", true)
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    const payoutSettings = (platformSettingsRow as any)?.settings?.payouts || {};
    const serviceFeeType = payoutSettings.platform_service_fee_type || "percentage";
    const fallbackFeePercentage = payoutSettings.platform_service_fee_percentage || 0;
    const fallbackFeeFixed = payoutSettings.platform_service_fee_fixed || 0;

    if (serviceFeeType === "percentage") {
      serviceFeePercentage = fallbackFeePercentage;
      serviceFeeAmount = Number(((subtotalAfterMembership * serviceFeePercentage) / 100).toFixed(2));
    } else {
      serviceFeeAmount = fallbackFeeFixed;
    }
  }

  const totalAmount = subtotalAfterMembership + tipAmount + taxAmount + serviceFeeAmount;

  // ΓöÇΓöÇ Loyalty points ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  let loyaltyPointsEarned = 0;
  const { data: loyaltyRule } = await supabase
    .from("loyalty_rules")
    .select("points_per_currency_unit, currency")
    .eq("is_active", true)
    .eq("currency", currency)
    .order("effective_from", { ascending: false })
    .limit(1)
    .maybeSingle();

  if (loyaltyRule?.points_per_currency_unit) {
    loyaltyPointsEarned = Math.floor(totalAmount * Number(loyaltyRule.points_per_currency_unit));
  }

  // ΓöÇΓöÇ Appointment status ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const { determineAppointmentStatusFromDB } = await import(
    "@/lib/provider-portal/appointment-settings"
  );
  const appointmentStatus = await determineAppointmentStatusFromDB(supabaseAdmin, draft.provider_id);

  // ΓöÇΓöÇ Group booking duration (for conflict check) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const isGroupBooking =
    Boolean(validatedDraft.is_group_booking) && Boolean(validatedDraft.group_participants);
  const groupParticipants = isGroupBooking ? validatedDraft.group_participants : null;
  let groupTotalDurationMinutes: number | null = null;
  if (isGroupBooking && groupParticipants && groupParticipants.length > 0) {
    const { calculateGroupBookingDuration } = await import(
      "@/lib/bookings/group-booking-services"
    );
    const durationMap = new Map<string, { duration_minutes: number }>();
    for (const o of offeringById.values()) {
      durationMap.set(o.id, { duration_minutes: Number(o.duration_minutes || 0) });
    }
    const primaryServiceIds = (draft.services || []).map((s: any) => s.offering_id);
    const allParticipantsForDuration = [
      { serviceIds: primaryServiceIds },
      ...(groupParticipants as any[]).map((p: any) => ({
        serviceIds: p.service_ids ?? p.serviceIds ?? [],
      })),
    ];
    groupTotalDurationMinutes = calculateGroupBookingDuration(allParticipantsForDuration, durationMap);
  }

  // ΓöÇΓöÇ Time-slot conflict check ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const firstService = draft.services[0];
  let allowOverride = false;
  let conflictResult: ConflictResult | null = null;

  if (firstService.staff_id) {
    const selectedDatetime = new Date(draft.selected_datetime);

    let checkDuration = 0;
    if (groupTotalDurationMinutes != null) {
      checkDuration = groupTotalDurationMinutes;
      const lastPrimaryOffering = offeringById.get(draft.services[draft.services.length - 1].offering_id);
      checkDuration += Number(lastPrimaryOffering?.buffer_minutes || 0);
      checkDuration += Number(lastPrimaryOffering?.processing_minutes || 0);
      checkDuration += Number(lastPrimaryOffering?.finishing_minutes || 0);
    } else {
      for (const s of draft.services) {
        const off = offeringById.get(s.offering_id);
        checkDuration += Number(off.duration_minutes || 0);
        checkDuration += Number(off.buffer_minutes || 0);
        checkDuration += Number(off.processing_minutes || 0);
        checkDuration += Number(off.finishing_minutes || 0);
      }
    }

    if (draft.location_type === "at_home" && draft.address?.latitude && draft.address?.longitude) {
      const { getTravelBufferForAtHomeBooking } = await import("@/lib/availability/travel-buffers");
      const travelBuffer = await getTravelBufferForAtHomeBooking(
        supabase,
        firstService.staff_id,
        selectedDatetime,
        { lat: draft.address.latitude, lng: draft.address.longitude }
      );
      checkDuration += travelBuffer;
    }

    const bookingEndForConflict = new Date(selectedDatetime.getTime() + checkDuration * 60000);

    const { lockBookingServices, canOverrideDoubleBooking } = await import(
      "@/lib/bookings/conflict-check"
    );
    conflictResult = await lockBookingServices(
      supabase,
      firstService.staff_id,
      selectedDatetime,
      bookingEndForConflict,
      Number(
        offeringById.get(draft.services[draft.services.length - 1].offering_id).buffer_minutes || 15
      )
    );

    if (conflictResult.hasConflict) {
      allowOverride = await canOverrideDoubleBooking(supabase, draft.provider_id);

      if (!allowOverride) {
        return handleApiError(
          new Error("This time slot is no longer available. Please select another time."),
          "This time slot is no longer available. Please select another time.",
          "CONFLICT",
          409
        );
      }
      console.warn("Double booking override allowed for provider:", draft.provider_id);
    }
  }

  // ΓöÇΓöÇ Resource availability ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const { getRequiredResourcesForOffering, checkResourceAvailability } = await import(
    "@/lib/resources/assignment"
  );
  let allResourceIds: string[] = [];

  const draftResourceIds = (draft as any).resource_ids;
  if (Array.isArray(draftResourceIds) && draftResourceIds.length > 0) {
    allResourceIds = draftResourceIds;
  } else {
    for (const s of draft.services) {
      const requiredResources = await getRequiredResourcesForOffering(supabase, s.offering_id);
      if (requiredResources.length >= 1) {
        allResourceIds.push(requiredResources[0]);
      }
    }
  }

  if (allResourceIds.length > 0) {
    const selectedDatetime = new Date(draft.selected_datetime);
    let resDuration = 0;
    for (const s of draft.services) {
      const off = offeringById.get(s.offering_id);
      resDuration += Number(off.duration_minutes || 0);
    }
    const resEnd = new Date(selectedDatetime.getTime() + resDuration * 60000);

    const resourceCheck = await checkResourceAvailability(
      supabase,
      [...new Set(allResourceIds)],
      selectedDatetime,
      resEnd
    );

    if (!resourceCheck.available) {
      return handleApiError(
        new Error("Required resources are not available"),
        `Required resources are not available: ${resourceCheck.conflicts.map((c: any) => c.reason).join(", ")}`,
        "RESOURCE_UNAVAILABLE",
        409
      );
    }
  }

  // ΓöÇΓöÇ Build booking_services data ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  let bookingServicesData: any[];
  let totalDuration = 0;

  if (isGroupBooking && groupParticipants && groupParticipants.length > 0) {
    const { calculateGroupBookingDuration } = await import(
      "@/lib/bookings/group-booking-services"
    );

    const servicesMap = new Map();
    for (const s of draft.services) {
      const off = offeringById.get(s.offering_id);
      servicesMap.set(s.offering_id, {
        offering_id: off.id,
        staff_id: s.staff_id || null,
        duration_minutes: Number(off.duration_minutes),
        price: Number(off.price),
        currency,
        buffer_minutes: Number(off.buffer_minutes || 0),
      });
    }

    // Primary = booker; their services are draft.services. Others are in group_participants (each with service_ids).
    const primaryServiceIds = (draft.services || []).map((s: any) => s.offering_id);
    const allParticipantsForDuration = [
      { serviceIds: primaryServiceIds },
      ...groupParticipants.map((p: any) => ({ serviceIds: p.service_ids ?? p.serviceIds ?? [] })),
    ];
    totalDuration = calculateGroupBookingDuration(allParticipantsForDuration, servicesMap);

    // Booking services data = primary's services only (one booking row; createGroupBookingServices adds others' services)
    let cursor = new Date(draft.selected_datetime);
    bookingServicesData = primaryServiceIds
      .map((serviceId: string) => {
        const s = draft.services.find((serv: any) => serv.offering_id === serviceId);
        if (!s) return null;
        const off = offeringById.get(s.offering_id);
        const start = new Date(cursor);
        const end = new Date(start.getTime() + Number(off.duration_minutes) * 60000);
        cursor = new Date(end.getTime() + Number(off.buffer_minutes || 0) * 60000);
        return {
          offering_id: off.id,
          staff_id: s.staff_id || null,
          duration_minutes: Number(off.duration_minutes),
          price: Number(off.price),
          currency,
          scheduled_start_at: start.toISOString(),
          scheduled_end_at: end.toISOString(),
        };
      })
      .filter(Boolean) as any[];

    if (bookingServicesData.length === 0 && draft.services.length > 0) {
      const s = draft.services[0];
      const off = offeringById.get(s.offering_id);
      const start = new Date(draft.selected_datetime);
      const end = new Date(start.getTime() + Number(off.duration_minutes) * 60000);
      bookingServicesData = [
        {
          offering_id: off.id,
          staff_id: s.staff_id || null,
          duration_minutes: Number(off.duration_minutes),
          price: Number(off.price),
          currency,
          scheduled_start_at: start.toISOString(),
          scheduled_end_at: end.toISOString(),
        },
      ];
    }
  } else {
    let cursor = new Date(draft.selected_datetime);
    bookingServicesData = draft.services.map((s) => {
      const off = offeringById.get(s.offering_id);
      const start = new Date(cursor);
      const end = new Date(start.getTime() + Number(off.duration_minutes) * 60000);
      cursor = new Date(end.getTime() + Number(off.buffer_minutes || 0) * 60000);
      totalDuration += Number(off.duration_minutes);

      return {
        offering_id: off.id,
        staff_id: s.staff_id || null,
        duration_minutes: Number(off.duration_minutes),
        price: Number(off.price),
        currency,
        scheduled_start_at: start.toISOString(),
        scheduled_end_at: end.toISOString(),
      };
    });

    // When "anyone" / no preference: assign a random available staff so booking appears on calendar
    const allStaffNull = bookingServicesData.every((s: any) => !s.staff_id);
    if (allStaffNull && draft.provider_id) {
      const { data: staffRows } = await supabaseAdmin
        .from("provider_staff")
        .select("id")
        .eq("provider_id", draft.provider_id)
        .eq("is_active", true)
        .limit(10);
      const staffIds = (staffRows || []).map((r: any) => r.id);
      if (staffIds.length > 0) {
        const assignId = staffIds[Math.floor(Math.random() * staffIds.length)];
        bookingServicesData = bookingServicesData.map((s: any) => ({ ...s, staff_id: assignId }));
      }
    }
  }

  // Ensure totalDuration is non-zero
  if (totalDuration === 0) {
    for (const s of draft.services) {
      const off = offeringById.get(s.offering_id);
      totalDuration += Number(off.duration_minutes || 0);
    }
  }

  const selectedDatetime = new Date(draft.selected_datetime);
  // Include last service's buffer so RPC / conflict check use full blocked span
  const lastOffering = draft.services.length
    ? offeringById.get(draft.services[draft.services.length - 1].offering_id)
    : null;
  const lastBufferMinutes = Number(lastOffering?.buffer_minutes || 0);
  const bookingEnd = new Date(
    selectedDatetime.getTime() + (totalDuration + lastBufferMinutes) * 60000
  );

  // ΓöÇΓöÇ Return enriched data ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  return {
    customerId,
    provider: provider as any as ProviderRow,
    currency,

    offeringById,
    addonById,
    productById,

    servicesSubtotal,
    addonsSubtotal,
    productsSubtotal,
    travelFee,
    packageDiscountAmount,
    promoDiscountAmount,
    promotionId,
    promoCode,
    subtotal,

    membershipPlanId,
    membershipDiscountAmount,
    subtotalAfterMembership,
    commissionBase,

    tipAmount,
    taxRate,
    taxAmount,

    serviceFeeAmount,
    serviceFeePercentage,
    serviceFeeConfigId,

    totalAmount,
    loyaltyPointsEarned,

    appointmentStatus,

    allowOverride,
    conflictResult,

    allResourceIds,

    bookingServicesData,
    totalDuration,
    bookingEnd,
    selectedDatetime,

    isGroupBooking,
    groupParticipants,
  };
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { z } from "zod";
import type { BookingDraft } from "@/types/beautonomi";

import { validateBooking } from "./_helpers/validate-booking";
import { createBookingRecord } from "./_helpers/create-booking-record";
import { processPayment } from "./_helpers/process-payment";
import { postBookingEffects } from "./_helpers/post-booking";
import { ensureUserProfileForAuthUser } from "./_helpers/ensure-user-profile";

const bookingDraftSchema = z.object({
  provider_id: z.string().uuid("Invalid provider ID"),
  services: z
    .array(
      z.object({
        offering_id: z.string().uuid("Invalid offering ID"),
        staff_id: z.string().uuid("Invalid staff ID").optional().nullable(),
      })
    )
    .min(1, "At least one service is required"),
  selected_datetime: z.string().datetime("Invalid datetime format"),
  location_type: z.enum(["at_home", "at_salon"]),
  location_id: z.string().uuid().optional().nullable(),
  address: z
    .object({
      line1: z.string().min(1),
      line2: z.string().optional(),
      city: z.string().min(1),
      state: z.string().optional(),
      country: z.string().min(1),
      postal_code: z.string().optional(),
      latitude: z.number().optional(),
      longitude: z.number().optional(),
      apartment_unit: z.string().optional().nullable(),
      building_name: z.string().optional().nullable(),
      floor_number: z.string().optional().nullable(),
      access_codes: z.record(z.string(), z.string()).optional().nullable(),
      parking_instructions: z.string().optional().nullable(),
      location_landmarks: z.string().optional().nullable(),
    })
    .optional()
    .nullable(),
  addons: z.array(z.string().uuid("Invalid addon ID")).optional(),
  products: z.array(
    z.object({
      productId: z.string().uuid("Invalid product ID"),
      quantity: z.number().int().positive("Quantity must be positive"),
      unitPrice: z.number().min(0, "Unit price must be non-negative"),
      totalPrice: z.number().min(0, "Total price must be non-negative"),
    })
  ).optional(),
  package_id: z.string().uuid().optional().nullable(),
  tip_amount: z.number().min(0).optional(),
  travel_fee: z.number().min(0).optional(),
  special_requests: z.string().optional().nullable(),
  house_call_instructions: z.string().optional().nullable(),
  client_info: z.any().optional(),
  payment_method: z.enum(["card", "cash", "giftcard"]).optional(),
  payment_method_id: z.string().uuid().optional().nullable(),
  payment_option: z.enum(["deposit", "full"]).optional(),
  save_card: z.boolean().optional(),
  set_as_default: z.boolean().optional(),
  promotion_code: z.string().optional().nullable(),
  gift_card_code: z.string().optional().nullable(),
  membership_plan_id: z.string().uuid().optional().nullable(),
  use_wallet: z.boolean().optional(),
  is_group_booking: z.boolean().optional(),
  group_participants: z.array(
    z.object({
      name: z.string(),
      email: z.string().optional().nullable(),
      phone: z.string().optional().nullable(),
      service_ids: z.array(z.string().uuid()),
      notes: z.string().optional().nullable(),
    })
  ).optional().nullable(),
  hold_id: z.string().uuid().optional().nullable(),
  loyalty_points_used: z.number().int().min(0).optional(),
});

/**
 * POST /api/public/bookings
 *
 * Create a new booking (public endpoint, but may require auth for some features)
 */
export async function POST(request: NextRequest) {
  try {
    const supabase = await getSupabaseServer();
    const body = await request.json();

    // 1. Parse & validate input
    let validatedDraft;
    try {
      validatedDraft = bookingDraftSchema.parse(body);
    } catch (validationError: any) {
      throw validationError;
    }
    const draft: BookingDraft = validatedDraft as BookingDraft;

    // 2. Authenticate user
    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      return handleApiError(
        new Error("Authentication required"),
        "Authentication required",
        "AUTH_REQUIRED",
        401
      );
    }

    const supabaseAdmin = await getSupabaseAdmin();

    // 2.5. Ensure user has a public profile (handles new sign-ins where trigger hasn't run yet)
    await ensureUserProfileForAuthUser(supabaseAdmin, user);

    // 3. Validate booking (provider, services, pricing, conflicts, resources)
    const validationResult = await validateBooking(
      supabase,
      supabaseAdmin,
      draft,
      validatedDraft as Record<string, any>,
      user.id
    );

    // If validation returned an error Response, forward it
    if (validationResult instanceof Response) {
      return validationResult;
    }

    const v = validationResult;

    // 4. Create booking record (DB insert + addons/products/group)
    const createResult = await createBookingRecord(
      supabase,
      supabaseAdmin,
      draft,
      validatedDraft as Record<string, any>,
      v,
      user.id
    );

    if (createResult instanceof Response) {
      return createResult;
    }

    const { booking } = createResult;

    // 5. Process payment (gift card, wallet, Paystack card, cash)
    const paymentResult = await processPayment({
      supabase,
      supabaseAdmin,
      draft,
      validatedDraft: validatedDraft as Record<string, any>,
      v,
      booking,
    });

    if (paymentResult instanceof Response) {
      return paymentResult;
    }

    const { paymentUrl } = paymentResult;

    // 6. Post-booking side effects (cache, waitlist, analytics) ΓÇö fire & forget
    const savedPaymentMethodId = (draft as any).payment_method_id || null;
    await postBookingEffects({
      supabase,
      draft,
      validatedDraft: validatedDraft as Record<string, any>,
      v,
      booking,
      paymentUrl,
      savedPaymentMethodId,
    });

    // 7. Return response
    return successResponse({
      booking_id: booking.id,
      booking_number: booking.booking_number,
      payment_url: paymentUrl,
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        new Error(error.issues.map((e: any) => e.message).join(", ")),
        "Validation failed",
        "VALIDATION_ERROR",
        400
      );
    }
    return handleApiError(error, "Failed to create booking");
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";

/**
 * GET /api/public/categories/global/[slug]
 * 
 * Get single global category with associated providers
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ slug: string }> }
) {
  try {
    const { slug } = await params;
    
    const supabase = await getSupabaseServer();

    const { data: category, error } = await supabase
      .from("global_service_categories")
      .select("*")
      .eq("slug", slug)
      .eq("is_active", true)
      .single();

    if (error || !category) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Category not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    // Get providers associated with this category
    const { data: associations, error: assocError } = await supabase
      .from("provider_global_category_associations")
      .select(`
        provider_id,
        providers!inner (
          id,
          slug,
          business_name,
          rating,
          review_count,
          thumbnail_url,
          avatar_url,
          city,
          country,
          is_verified,
          starting_price,
          currency
        )
      `)
      .eq("global_category_id", category.id);

    if (assocError) {
      console.error("Error fetching provider associations:", assocError);
    }

    const providers = (associations || []).map((assoc: any) => assoc.providers).filter(Boolean);

    return NextResponse.json({
      data: {
        ...category,
        providers: providers || [],
        provider_count: providers.length,
      },
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/public/categories/global/[slug]:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch category",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/public/categories/global
 * 
 * Get all active global categories (for home page)
 * Only returns featured categories by default, or all if ?all=true
 */
export async function GET(request: NextRequest) {
  try {
    const supabase = await getSupabaseServer();
    const { searchParams } = new URL(request.url);
    const _all = searchParams.get("all") === "true";

    let query = supabase
      .from("global_service_categories")
      .select("*")
      .eq("is_active", true)
      .order("display_order", { ascending: true })
      .order("name", { ascending: true });

    // Return all active categories by default (not just featured)
    // Featured filter is only applied if explicitly requested via ?featured=true
    const featuredOnly = searchParams.get("featured") === "true";
    if (featuredOnly) {
      query = query.eq("is_featured", true);
    }

    const { data: categories, error } = await query;

    if (error) {
      console.error("Error fetching global categories:", error);
      // Check if it's a table not found error or any database error
      if (error.code === "42P01" || error.message?.includes("does not exist") || error.code === "PGRST116") {
        console.warn("Table 'global_service_categories' may not exist in database, returning empty array");
        // Return empty array instead of error to allow fallback in frontend
        return successResponse([]);
      }
      // For any other error, also return empty array to prevent 500 errors
      console.warn("Error fetching categories, returning empty array:", error);
      return successResponse([]);
    }

    console.log(`Found ${categories?.length || 0} global service categories (featuredOnly: ${featuredOnly})`);

    // If no categories found, return empty array
    if (!categories || categories.length === 0) {
      console.warn("No categories found in global_service_categories table");
      return successResponse([]);
    }

    // Get provider count for each category (with error handling)
    const categoriesWithCounts = await Promise.all(
      (categories || []).map(async (category: any) => {
        try {
          const { count, error: countError } = await supabase
            .from("provider_global_category_associations")
            .select("*", { count: "exact", head: true })
            .eq("global_category_id", category.id);

          // If count query fails, just set count to 0
          if (countError) {
            console.warn(`Failed to get count for category ${category.id}:`, countError);
            return {
              ...category,
              provider_count: 0,
            };
          }

          return {
            ...category,
            provider_count: count || 0,
          };
        } catch (err) {
          console.warn(`Error getting provider count for category ${category.id}:`, err);
          return {
            ...category,
            provider_count: 0,
          };
        }
      })
    );

    console.log(`Returning ${categoriesWithCounts.length} categories with provider counts`);
    return successResponse(categoriesWithCounts);
  } catch (error) {
    return handleApiError(error, "Failed to fetch global categories");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, handleApiError } from "@/lib/supabase/api-helpers";
import { z } from "zod";

const createCityWaitlistSchema = z.object({
  city_name: z.string().min(1, "City name is required"),
  name: z.string().min(1, "Name is required"),
  email: z.string().email().optional().or(z.literal("")),
  phone: z.string().optional(),
  is_building_owner: z.boolean().optional().default(false),
  building_address: z.string().optional(),
  notes: z.string().optional(),
});

/**
 * POST /api/public/city-waitlist
 * 
 * Join city waitlist (public endpoint, no auth required)
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const validationResult = createCityWaitlistSchema.safeParse(body);

    if (!validationResult.success) {
      return handleApiError(
        new Error(validationResult.error.issues.map((e: any) => e.message).join(", ")),
        "Validation failed",
        "VALIDATION_ERROR",
        400
      );
    }

    const data = validationResult.data;
    const supabase = await getSupabaseServer();

    // Get user_id if authenticated
    const { data: { user } } = await supabase.auth.getUser();
    const userId = user?.id || null;

    // Check for duplicate entries (same email or phone for same city)
    if (data.email || data.phone) {
      let duplicateQuery = supabase
        .from('city_waitlist')
        .select('id')
        .eq('city_name', data.city_name)
        .eq('status', 'pending');

      if (data.email && data.phone) {
        duplicateQuery = duplicateQuery.or(`email.eq.${data.email.trim()},phone.eq.${data.phone.trim()}`);
      } else if (data.email) {
        duplicateQuery = duplicateQuery.eq('email', data.email.trim());
      } else if (data.phone) {
        duplicateQuery = duplicateQuery.eq('phone', data.phone.trim());
      }

      const { data: existing } = await duplicateQuery.limit(1).maybeSingle();

      if (existing) {
        return handleApiError(
          new Error("You're already on the waitlist for this city"),
          "You're already on the waitlist for this city",
          "DUPLICATE_ENTRY",
          409
        );
      }
    }

    // Create waitlist entry
    const { data: entry, error: insertError } = await supabase
      .from('city_waitlist')
      .insert({
        user_id: userId,
        city_name: data.city_name.trim(),
        name: data.name.trim(),
        email: data.email?.trim() || null,
        phone: data.phone?.trim() || null,
        is_building_owner: data.is_building_owner || false,
        building_address: data.building_address?.trim() || null,
        notes: data.notes?.trim() || null,
        status: 'pending',
      })
      .select()
      .single();

    if (insertError) {
      throw insertError;
    }

    return successResponse({
      entry: {
        id: entry.id,
        city_name: entry.city_name,
        name: entry.name,
        message: "Successfully joined the waitlist! We'll notify you when Beautonomi becomes available in your city.",
      },
    });
  } catch (error) {
    return handleApiError(error, "Failed to join city waitlist");
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";

/**
 * GET /api/public/content/pages/[slug]
 * 
 * Public endpoint to fetch page content (for pages like privacy-policy, terms, etc.)
 * Only returns active content
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ slug: string }> }
) {
  try {
    const supabase = await getSupabaseServer();
    const { slug } = await params;
    
    // Fetch all active content for this page slug
    const { data: pages, error } = await supabase
      .from("page_content")
      .select("*")
      .eq("page_slug", slug)
      .eq("is_active", true)
      .order("display_order", { ascending: true })
      .order("created_at", { ascending: false });

    if (error) {
      console.error("Error fetching page content:", error);
      return NextResponse.json(
        {
          data: [],
          error: null,
        },
        { status: 200 } // Return empty array instead of error
      );
    }

    // Transform to frontend format
    const content = (pages || []).map((p: any) => ({
      id: p.id,
      page_slug: p.page_slug,
      section_key: p.section_key,
      content_type: p.content_type,
      content: p.content,
      metadata: p.metadata || {},
      order: p.display_order || 0,
    }));

    return NextResponse.json({
      data: content,
