      supabaseAdmin.from("distance_module_config").select("enabled").eq("environment", env).maybeSingle(),
    ]);
    const radiusKmParam = new URL(request.url).searchParams.get("radius_km");
    const radiusKm = radiusKmParam ? parseFloat(radiusKmParam) : null;

    let data = result?.data ?? { all: [], topRated: [], nearest: [], hottest: [], upcoming: [], browseByCity: [], sponsored: [] as PublicProviderCard[] };
    const sponsored: PublicProviderCard[] = [];

    if (distanceRow?.data?.enabled && radiusKm != null && radiusKm > 0 && Array.isArray(data.nearest)) {
      data = {
        ...data,
        nearest: (data.nearest as PublicProviderCard[]).filter((p) => p.distance_km != null && p.distance_km <= radiusKm),
      };
    }

    if (rankingRow?.data?.enabled && (data.topRated?.length > 0 || data.hottest?.length > 0)) {
      const providerIds = [...new Set([...(data.topRated ?? []).map((p: PublicProviderCard) => p.id), ...(data.hottest ?? []).map((p: PublicProviderCard) => p.id)])];
      const { data: scores } = await supabaseAdmin.from("provider_quality_score").select("provider_id, computed_score").in("provider_id", providerIds);
      const scoreMap = new Map<string, number>((scores ?? []).map((s: { provider_id: string; computed_score: number }) => [s.provider_id, Number(s.computed_score)]));
      const sortByScore = (a: PublicProviderCard, b: PublicProviderCard) => (scoreMap.get(b.id) ?? 0) - (scoreMap.get(a.id) ?? 0);
      data = {
        ...data,
        topRated: [...(data.topRated ?? [])].sort(sortByScore),
        hottest: [...(data.hottest ?? [])].sort(sortByScore),
      };
    }

    if (adsRow?.data?.enabled && adsRow.data.max_sponsored_slots) {
      const maxSlots = Math.min(Number(adsRow.data.max_sponsored_slots) || 5, 10);
      const { data: campaigns } = await supabaseAdmin.from("ads_campaigns").select("provider_id").eq("status", "active").limit(maxSlots * 2);
      const providerIds = [...new Set((campaigns ?? []).map((c: { provider_id: string }) => c.provider_id))].slice(0, maxSlots);
      if (providerIds.length > 0) {
        const { data: providersRaw } = await supabaseAdmin.from("providers").select("id, slug, business_name, business_type, rating_average, review_count, thumbnail_url, avatar_url, is_featured, is_verified, description, currency").in("id", providerIds).eq("status", "active");
        if (providersRaw?.length) {
          const allMap = new Map((data.all ?? []).map((p: PublicProviderCard) => [p.id, p]));
          for (const p of providersRaw as any[]) {
            const card = allMap.get(p.id) ?? {
              id: p.id,
              slug: p.slug,
              business_name: p.business_name,
              business_type: p.business_type || "salon",
              rating: p.rating_average ?? 0,
              review_count: p.review_count ?? 0,
              thumbnail_url: p.thumbnail_url,
              avatar_url: p.avatar_url ?? null,
              city: "",
              country: "",
              is_featured: p.is_featured ?? false,
              is_verified: p.is_verified ?? false,
              starting_price: null,
              currency: p.currency ?? "ZAR",
              description: p.description ?? null,
              distance_km: null,
              supports_house_calls: false,
              supports_salon: false,
              current_badge: null,
            };
            sponsored.push(card);
          }
        }
      }
      data = { ...data, sponsored } as typeof data & { sponsored: PublicProviderCard[] };
    }

    const response = NextResponse.json({ ...result, data });
    response.headers.set('Cache-Control', 'public, s-maxage=60, stale-while-revalidate=300');
    return response;
  } catch (error: any) {
    const err = error instanceof Error ? error : new Error(String(error));
    console.error("Unexpected error in /api/public/home:", err.message, err.stack);
    // Return empty data instead of error to prevent page crash
    const errorResponse = NextResponse.json({
      data: {
        all: [],
        topRated: [],
        nearest: [],
        hottest: [],
        upcoming: [],
        browseByCity: [],
      },
      error: null,
    }, { status: 200 }); // Return 200 with empty data instead of 500

    // Cache error responses for shorter time
    errorResponse.headers.set('Cache-Control', 'public, s-maxage=10, stale-while-revalidate=30');

    return errorResponse;
  }
}

import { NextRequest, NextResponse } from "next/server";

/**
 * GET /api/public/ip-geolocation
 * 
 * Get user's location based on their IP address
 * Returns country, city, postal code, and approximate coordinates
 */
/**
 * Check if IP is in a reserved/private range
 */
function isReservedIP(ip: string): boolean {
  // Check for localhost, private ranges, etc.
  if (ip === "127.0.0.1" || ip === "::1" || ip === "localhost") {
    return true;
  }
  
  // Check for private IP ranges
  const privateRanges = [
    /^10\./,           // 10.0.0.0/8
    /^172\.(1[6-9]|2[0-9]|3[0-1])\./, // 172.16.0.0/12
    /^192\.168\./,    // 192.168.0.0/16
    /^169\.254\./,    // Link-local
    /^fc00:/,         // IPv6 private
    /^fe80:/,         // IPv6 link-local
  ];
  
  return privateRanges.some(range => range.test(ip));
}

export async function GET(request: NextRequest) {
  try {
    // Get client IP address from headers
    const forwarded = request.headers.get("x-forwarded-for");
    const realIp = request.headers.get("x-real-ip");
    const ip = forwarded?.split(",")[0]?.trim() || realIp || "";

    if (!ip) {
      return NextResponse.json({ data: null, error: null });
    }

    // For localhost/private IPs, return 200 with null data (avoids 400 in dev console)
    if (isReservedIP(ip)) {
      return NextResponse.json({
        data: null,
        error: null,
      });
    }

    // Use ipapi.co for IP geolocation (free tier: 1000 requests/day)
    // Alternative: ip-api.com (free tier: 45 requests/minute)
    try {
      const response = await fetch(`https://ipapi.co/${ip}/json/`, {
        headers: {
          "User-Agent": "Beautonomi/1.0",
        },
      });

      if (!response.ok) {
        throw new Error(`IP geolocation service returned ${response.status}`);
      }

      const data = await response.json();

      // Check for error in response
      if (data.error) {
        // Fallback to ip-api.com if ipapi.co fails
        return await getLocationFromIpApi(ip);
      }

      // Extract relevant location data
      const locationData = {
        country: data.country_name || data.country || null,
        countryCode: data.country_code || null,
        city: data.city || null,
        postalCode: data.postal || data.postal_code || null,
        region: data.region || data.region_name || null,
        latitude: data.latitude || null,
        longitude: data.longitude || null,
        timezone: data.timezone || null,
        ip: data.ip || ip,
      };

      return NextResponse.json({
        data: locationData,
        error: null,
      });
    } catch (ipapiError) {
      // Fallback to ip-api.com
      console.warn("ipapi.co failed, trying ip-api.com:", ipapiError);
      return await getLocationFromIpApi(ip);
    }
  } catch (error: any) {
    console.error("Error in IP geolocation:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: error.message || "Failed to get location from IP",
          code: "GEOLOCATION_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

/**
 * Fallback function to get location from ip-api.com
 */
async function getLocationFromIpApi(ip: string) {
  try {
    const response = await fetch(`http://ip-api.com/json/${ip}?fields=status,message,country,countryCode,city,zip,lat,lon,regionName,timezone,query`, {
      headers: {
        "User-Agent": "Beautonomi/1.0",
      },
    });

    if (!response.ok) {
      throw new Error(`IP geolocation service returned ${response.status}`);
    }

    const data = await response.json();

    if (data.status === "fail") {
      throw new Error(data.message || "Failed to get location");
    }

    const locationData = {
      country: data.country || null,
      countryCode: data.countryCode || null,
      city: data.city || null,
      postalCode: data.zip || null,
      region: data.regionName || null,
      latitude: data.lat || null,
      longitude: data.lon || null,
      timezone: data.timezone || null,
      ip: data.query || ip,
    };

    return NextResponse.json({
      data: locationData,
      error: null,
    });
  } catch (error: any) {
    console.error("Error in ip-api.com fallback:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: error.message || "Failed to get location from IP",
          code: "GEOLOCATION_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";

/**
 * GET /api/public/page-content?page_slug=gift-card
 * 
 * Public API to fetch page content for a specific page slug
 * Returns only active content
 */
export async function GET(request: Request) {
  try {
    const supabase = await getSupabaseServer();
    const { searchParams } = new URL(request.url);
    const pageSlug = searchParams.get("page_slug");

    if (!pageSlug) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "page_slug parameter is required",
            code: "MISSING_PARAMETER",
          },
        },
        { status: 400 }
      );
    }

    const { data: pages, error } = await supabase
      .from("page_content")
      .select("*")
      .eq("page_slug", pageSlug)
      .eq("is_active", true)
      .order("display_order", { ascending: true })
      .order("created_at", { ascending: false });

    if (error) {
      console.error("Error fetching page content:", error);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to fetch page content",
            code: "FETCH_ERROR",
          },
        },
        { status: 500 }
      );
    }

    // Transform to a map by section_key for easy access
    const contentMap: Record<string, any> = {};
    (pages || []).forEach((page: any) => {
      contentMap[page.section_key] = {
        content: page.content,
        content_type: page.content_type,
        metadata: page.metadata || {},
      };
    });

    return NextResponse.json({
      data: contentMap,
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/public/page-content:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch page content",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

