import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";

/**
 * GET /api/public/platform-settings
 * 
 * Get platform-wide locale and currency settings (public endpoint)
 */
export async function GET() {
  try {
    const supabase = await getSupabaseServer();

    // Get platform settings
    const { data: settings, error } = await supabase
      .from("platform_settings")
      .select("*")
      .eq("is_active", true)
      .single();

    if (error && error.code !== "PGRST116") {
      // PGRST116 = no rows returned, which is okay for first time setup
      console.error("Error fetching platform settings:", error);
    }

    // Get currency info if currency code is set
    let currencyInfo = null;
    if (settings?.localization?.default_currency) {
      const { data: currency } = await supabase
        .from("iso_currencies")
        .select("code, symbol, name, decimal_places")
        .eq("code", settings.localization.default_currency)
        .eq("is_active", true)
        .single();

      if (currency) {
        currencyInfo = currency;
      }
    }

    // Supported languages from iso_languages (single source with Admin ISO Codes)
    let supportedLanguages: string[] = settings?.localization?.supported_languages ?? [];
    let languages_meta: Array<{ code: string; name: string; nativeName: string; isDefault: boolean }> = [];
    const { data: isoLanguages } = await supabase
      .from("iso_languages")
      .select("code, name, native_name, is_default")
      .eq("is_active", true)
      .order("name", { ascending: true });
    if (isoLanguages?.length) {
      supportedLanguages = isoLanguages.map((r) => r.code);
      languages_meta = isoLanguages.map((r) => ({
        code: r.code,
        name: r.name,
        nativeName: r.native_name ?? r.name,
        isDefault: Boolean(r.is_default),
      }));
    }
    if (!supportedLanguages.length) {
      supportedLanguages = ["en", "af", "zu"];
    }

    // Merge settings with currency info
    const response = {
      default_currency: settings?.localization?.default_currency || "ZAR",
      default_language: settings?.localization?.default_language || "en",
      timezone: settings?.localization?.timezone || "Africa/Johannesburg",
      supported_currencies: settings?.localization?.supported_currencies || ["ZAR", "USD", "EUR"],
      supported_languages: supportedLanguages,
      languages_meta: languages_meta.length ? languages_meta : undefined,
      currency_info: currencyInfo || {
        code: settings?.localization?.default_currency || "ZAR",
        symbol: "R",
        name: "South African Rand",
        decimal_places: 2,
      },
    };

    return NextResponse.json({
      data: response,
      error: null,
    });
  } catch (error: any) {
    console.error("Unexpected error in /api/public/platform-settings:", error);
    return NextResponse.json(
      {
        data: {
          default_currency: "ZAR",
          default_language: "en",
          timezone: "Africa/Johannesburg",
          supported_currencies: ["ZAR", "USD", "EUR"],
          supported_languages: ["en", "af", "zu"],
          languages_meta: undefined,
          currency_info: {
            code: "ZAR",
            symbol: "R",
            name: "South African Rand",
            decimal_places: 2,
          },
        },
        error: null,
      },
      { status: 200 } // Return defaults even on error
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import {
  successResponse,
  notFoundResponse,
  handleApiError,
} from "@/lib/supabase/api-helpers";

/**
 * GET /api/public/products/[id]
 * Product detail with reviews summary, provider info, and shipping config
 */
export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const { id } = await params;
    const supabase = await getSupabaseServer();

    const { data: product, error } = await (supabase.from("products") as any)
      .select(
        `
        id, name, slug, brand, category, short_description, long_description, description,
        retail_price, supply_price, currency, image_urls, quantity, tags, measure, amount,
        tax_rate, weight_grams, is_active, retail_sales_enabled, created_at,
        has_variants, variant_option_types,
        provider:providers (
          id, business_name, slug, logo_url, description
        )
      `,
      )
      .eq("id", id)
      .eq("is_active", true)
      .eq("retail_sales_enabled", true)
      .single();

    if (error || !product) {
      return notFoundResponse("Product not found");
    }

    if (product.has_variants) {
      const { data: variants } = await (supabase.from("product_variants") as any)
        .select("id, product_id, option_values, sort_order, retail_price, quantity, sku, image_url")
        .eq("product_id", id)
        .order("sort_order");
      (product as any).variants = (variants || []).sort((a: any, b: any) => (a.sort_order ?? 0) - (b.sort_order ?? 0));
    } else {
      (product as any).variants = [];
    }

    // Get reviews summary
    const { data: reviewStats } = await (supabase.from("product_reviews") as any)
      .select("rating")
      .eq("product_id", id)
      .eq("is_visible", true);

    const reviews = reviewStats ?? [];
    const avgRating =
      reviews.length > 0
        ? reviews.reduce((sum: number, r: any) => sum + r.rating, 0) / reviews.length
        : 0;

    // Get recent reviews
    const { data: recentReviews } = await (supabase.from("product_reviews") as any)
      .select(
        `
        id, rating, title, comment, image_urls, is_verified_purchase,
        helpful_count, provider_response, provider_response_at, created_at,
        customer:users!product_reviews_customer_id_fkey (
          id, full_name, avatar_url
        )
      `,
      )
      .eq("product_id", id)
      .eq("is_visible", true)
      .order("created_at", { ascending: false })
      .limit(10);

    // Get shipping config for this provider
    const { data: shippingConfig } = await (supabase.from("provider_shipping_config") as any)
      .select("*")
      .eq("provider_id", product.provider.id)
      .maybeSingle();

    // Get collection locations
    const { data: locations } = await (supabase.from("provider_locations") as any)
      .select("id, name, address_line1, city, state, working_hours")
      .eq("provider_id", product.provider.id)
      .eq("is_active", true);

    // Related products from the same provider
    const { data: related } = await (supabase.from("products") as any)
      .select("id, name, slug, retail_price, image_urls, brand, category")
      .eq("provider_id", product.provider.id)
      .eq("is_active", true)
      .eq("retail_sales_enabled", true)
      .neq("id", id)
      .gt("quantity", 0)
      .limit(8);

    return successResponse({
      product,
      reviews: {
        average_rating: Math.round(avgRating * 10) / 10,
        total_count: reviews.length,
        recent: recentReviews ?? [],
      },
      shipping: shippingConfig ?? { offers_delivery: false, offers_collection: true },
      collection_locations: locations ?? [],
      related_products: related ?? [],
    });
  } catch (err) {
    return handleApiError(err, "Failed to fetch product");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/public/products
 * Browse all retail-enabled products across providers.
 * Query params: search, category, provider_id, tags, sort, page, limit
 */
export async function GET(request: NextRequest) {
  try {
    const supabase = await getSupabaseServer();
    const { searchParams } = new URL(request.url);

    const search = searchParams.get("search");
    const category = searchParams.get("category");
    const providerId = searchParams.get("provider_id");
    const tags = searchParams.get("tags");
    const sort = searchParams.get("sort") || "newest";
    const page = parseInt(searchParams.get("page") || "1");
    const limit = Math.min(parseInt(searchParams.get("limit") || "24"), 50);
    const offset = (page - 1) * limit;

    let query = (supabase.from("products") as any)
      .select(
        `
        id, name, slug, brand, category, retail_price, image_urls, short_description,
        quantity, tags, created_at,
        provider:providers (
          id, business_name, slug, logo_url
        )
      `,
        { count: "exact" },
      )
      .eq("is_active", true)
      .eq("retail_sales_enabled", true)
      .gt("quantity", 0);

    if (search) {
      query = query.or(
        `name.ilike.%${search}%,brand.ilike.%${search}%,short_description.ilike.%${search}%`,
      );
    }
    if (category) {
      query = query.eq("category", category);
    }
    if (providerId) {
      query = query.eq("provider_id", providerId);
    }
    if (tags) {
      const tagList = tags.split(",").map((t) => t.trim());
      query = query.overlaps("tags", tagList);
    }

    switch (sort) {
      case "price_asc":
        query = query.order("retail_price", { ascending: true });
        break;
      case "price_desc":
        query = query.order("retail_price", { ascending: false });
        break;
      case "name":
        query = query.order("name", { ascending: true });
        break;
      case "newest":
      default:
        query = query.order("created_at", { ascending: false });
        break;
    }

    query = query.range(offset, offset + limit - 1);

    const { data: products, error, count } = await query;
    if (error) {
      console.error("[GET /api/public/products] Supabase error:", error.message, error.details);
      return successResponse({
        products: [],
        categories: [],
        pagination: { page, limit, total: 0, totalPages: 0 },
      });
    }

    // Get distinct categories for filter chips (non-blocking: ignore errors)
    let uniqueCategories: string[] = [];
    try {
      const { data: categories } = await (supabase.from("products") as any)
        .select("category")
        .eq("is_active", true)
        .eq("retail_sales_enabled", true)
        .gt("quantity", 0)
        .not("category", "is", null)
        .limit(50);
      const categoryList = (categories ?? []) as Array<{ category?: string }>;
      const categoryStrings = categoryList.map((c) => c.category).filter((x): x is string => Boolean(x));
      uniqueCategories = [...new Set(categoryStrings)];
    } catch {
      // keep uniqueCategories []
    }

    return successResponse({
      products: products ?? [],
      categories: uniqueCategories,
      pagination: {
        page,
        limit,
        total: count ?? 0,
        totalPages: Math.ceil((count ?? 0) / limit),
      },
    });
  } catch (err) {
    console.error("[GET /api/public/products]", err);
    return handleApiError(err, "Failed to fetch products");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";

/**
 * GET /api/public/products/shipping-config?provider_id=...
 * Public endpoint: returns shipping config for a given provider
 */
export async function GET(request: NextRequest) {
  try {
    const providerId = request.nextUrl.searchParams.get("provider_id");
    if (!providerId) {
      return NextResponse.json(
        { error: "provider_id is required" },
        { status: 400 },
      );
    }

    const supabase = await getSupabaseServer();

    const { data, error } = await (supabase.from("provider_shipping_config") as any)
      .select("offers_delivery, offers_collection, delivery_fee, free_delivery_threshold, delivery_radius_km, estimated_delivery_days, delivery_notes, collection_notes")
      .eq("provider_id", providerId)
      .maybeSingle();

    if (error) throw error;

    const config = data ?? {
      offers_delivery: false,
      offers_collection: true,
      delivery_fee: 0,
      free_delivery_threshold: null,
      delivery_radius_km: null,
      estimated_delivery_days: 3,
      delivery_notes: null,
      collection_notes: null,
    };

    return NextResponse.json({ data: { shipping: config } });
  } catch (err) {
    console.error("Error fetching public shipping config:", err);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { NextResponse } from "next/server";
import { checkResourceAvailability } from "@/lib/resources/assignment";

/**
 * POST /api/public/providers/[slug]/availability/resources/check
 * Check which resources are available for a time range.
 * Body: { resource_ids: string[], start_at: string (ISO), end_at: string (ISO) }
 *       or { resource_ids: string[], date: string (YYYY-MM-DD), time: string (HH:MM), duration_minutes?: number }
 * Returns: { available: Record<resourceId, boolean> }
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string }> }
) {
  try {
    const supabase = await getSupabaseServer();
    const { slug } = await params;
    const body = await request.json().catch(() => ({}));

    const resourceIds = Array.isArray(body.resource_ids)
      ? body.resource_ids.filter((id: any) => typeof id === "string")
      : [];
    if (resourceIds.length === 0) {
      return NextResponse.json({ available: {}, error: null });
    }

    let startAt: Date;
    let endAt: Date;

    if (body.start_at && body.end_at) {
      startAt = new Date(body.start_at);
      endAt = new Date(body.end_at);
    } else if (body.date && body.time) {
      const durationMinutes = typeof body.duration_minutes === "number" ? body.duration_minutes : 60;
      const dateStr = String(body.date).trim();
      const timeStr = String(body.time).trim();
      startAt = new Date(`${dateStr}T${timeStr}:00`);
      endAt = new Date(startAt.getTime() + durationMinutes * 60 * 1000);
    } else {
      return NextResponse.json(
        { available: {}, error: { message: "Provide start_at/end_at or date/time and optional duration_minutes" } },
        { status: 400 }
      );
    }

    if (Number.isNaN(startAt.getTime()) || Number.isNaN(endAt.getTime())) {
      return NextResponse.json(
        { available: {}, error: { message: "Invalid date or time" } },
        { status: 400 }
      );
    }

    const { data: provider } = await supabase
      .from("providers")
      .select("id")
      .eq("slug", decodeURIComponent(slug))
      .eq("status", "active")
      .maybeSingle();

    if (!provider) {
      return NextResponse.json(
        { available: {}, error: { message: "Provider not found" } },
        { status: 404 }
      );
    }

    const result = await checkResourceAvailability(
      supabase,
      resourceIds,
      startAt,
      endAt
    );

    const available: Record<string, boolean> = {};
    for (const id of resourceIds) {
      available[id] = !result.conflicts.some((c) => c.resource_id === id);
    }

    return NextResponse.json({ available, error: null });
  } catch (error) {
    console.error("Error in POST resources/check:", error);
    return NextResponse.json(
      { available: {}, error: { message: "Failed to check availability" } },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import type { AvailabilitySlot } from "@/types/beautonomi";

type WorkingHoursDay = {
  is_open?: boolean;
  open_time?: string; // "09:00"
  close_time?: string; // "17:00"
  breaks?: { start: string; end: string }[]; // e.g. [{ start: "12:00", end: "13:00" }]
};

const DAY_KEYS = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"] as const;
function dayKeyFromDate(date: Date): (typeof DAY_KEYS)[number] {
  const d = date.getDay();
  return DAY_KEYS[d];
}

function parseTimeToMinutes(time: string): number | null {
  const m = /^(\d{1,2}):(\d{2})$/.exec(time);
  if (!m) return null;
  const hh = parseInt(m[1], 10);
  const mm = parseInt(m[2], 10);
  if (Number.isNaN(hh) || Number.isNaN(mm) || hh < 0 || hh > 23 || mm < 0 || mm > 59) return null;
  return hh * 60 + mm;
}

function isoAtLocalDateMinutes(dateStr: string, minutes: number): string {
  // Interprets `${dateStr}T..` in server local timezone. This matches existing behavior in the codebase.
  const hh = Math.floor(minutes / 60)
    .toString()
    .padStart(2, "0");
  const mm = (minutes % 60).toString().padStart(2, "0");
  return new Date(`${dateStr}T${hh}:${mm}:00`).toISOString();
}

function overlaps(aStart: string, aEnd: string, bStart: string, bEnd: string) {
  const as = new Date(aStart).getTime();
  const ae = new Date(aEnd).getTime();
  const bs = new Date(bStart).getTime();
  const be = new Date(bEnd).getTime();
  return as < be && ae > bs;
}

/**
 * GET /api/public/providers/[slug]/availability
 *
 * Get available time slots for the public book flow (express/online booking).
 * Accepts duration_minutes and buffer_minutes so multi-service and group
 * bookings can pass total span. Reschedule/portal use a separate pipeline:
 * loadAvailabilityConstraints + calculateAvailableSlots (see /api/portal/availability).
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ slug: string }> }
) {
  try {
    const supabase = await getSupabaseServer();
    const { slug } = await params;
    const { searchParams } = new URL(request.url);

    const date = searchParams.get("date");
    const serviceId = searchParams.get("service_id");
    const staffId = searchParams.get("staff_id");
    const locationId = searchParams.get("location_id");
    const paramDuration = searchParams.get("duration_minutes");
    const paramBuffer = searchParams.get("buffer_minutes");
    const minNoticeMinutes = parseInt(searchParams.get("min_notice_minutes") || "0");
    const maxAdvanceDays = parseInt(searchParams.get("max_advance_days") || "365");

    if (!date) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Date parameter is required",
            code: "VALIDATION_ERROR",
          },
        },
        { status: 400 }
      );
    }

    const effectiveMinNotice = Number.isNaN(minNoticeMinutes) || minNoticeMinutes < 0 ? 0 : minNoticeMinutes;
    const effectiveMaxAdvance = Number.isNaN(maxAdvanceDays) || maxAdvanceDays < 1 ? 365 : maxAdvanceDays;

    // Get provider
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("id")
      .eq("slug", slug)
      .eq("status", "active")
      .single();

    if (providerError || !provider) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Provider not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    // Duration and buffer: use query params when provided (e.g. multi-service total); else use single offering when service_id given
    let durationMinutes = paramDuration != null ? parseInt(paramDuration, 10) : NaN;
    let bufferMinutes = paramBuffer != null ? parseInt(paramBuffer, 10) : NaN;
    if (serviceId) {
      const { data: offering, error: offeringError } = await supabase
        .from("offerings")
        .select("id, provider_id, duration_minutes, buffer_minutes, is_active")
        .eq("id", serviceId)
        .single();
      if (!offeringError && offering && offering.provider_id === provider.id && offering.is_active) {
        if (Number.isNaN(durationMinutes) || durationMinutes <= 0)
          durationMinutes = Number(offering.duration_minutes) || 60;
        if (Number.isNaN(bufferMinutes) || bufferMinutes < 0)
          bufferMinutes = Number(offering.buffer_minutes) || 0;
      }
    }
    if (Number.isNaN(durationMinutes) || durationMinutes <= 0) durationMinutes = 60;
    if (Number.isNaN(bufferMinutes) || bufferMinutes < 0) bufferMinutes = 0;

    // "any" or synthetic "provider-*" (solo provider with no provider_staff rows) = aggregate slots
    const anyoneMode =
      staffId === "any" ||
      staffId === "" ||
      (typeof staffId === "string" && staffId.startsWith("provider-"));
    const effectiveStaffId = anyoneMode ? null : staffId;

    // Determine working hours: prefer staff hours if staff_id provided, otherwise location hours (primary/selected)
    const day = dayKeyFromDate(new Date(`${date}T00:00:00`));

    let staffHours: WorkingHoursDay | null = null;
    let staffList: Array<{ id: string; working_hours: Record<string, WorkingHoursDay> | null }> = [];

    if (anyoneMode) {
      const { data: allStaff, error: staffListError } = await supabase
        .from("provider_staff")
        .select("id, working_hours")
        .eq("provider_id", provider.id)
        .eq("is_active", true);
      if (!staffListError && allStaff) {
        staffList = allStaff.map((s) => ({
          id: s.id,
          working_hours: s.working_hours as Record<string, WorkingHoursDay> | null,
        }));
      }
    } else if (effectiveStaffId) {
      const { data: staff, error: staffError } = await supabase
        .from("provider_staff")
        .select("id, provider_id, is_active, working_hours")
        .eq("id", effectiveStaffId)
        .single();
      if (!staffError && staff && staff.provider_id === provider.id && staff.is_active) {
        staffHours = (staff.working_hours || {})[day] || null;
      }
    }

    let locationHours: WorkingHoursDay | null = null;
    if (locationId) {
      const { data: loc, error: locError } = await supabase
        .from("provider_locations")
        .select("id, provider_id, is_active, working_hours")
        .eq("id", locationId)
        .single();
      if (!locError && loc && loc.provider_id === provider.id && loc.is_active) {
        locationHours = (loc.working_hours || {})[day] || null;
      }
    } else {
      const { data: locs, error: locsError } = await supabase
        .from("provider_locations")
        .select("id, provider_id, is_active, is_primary, working_hours")
        .eq("provider_id", provider.id)
        .eq("is_active", true)
        .order("is_primary", { ascending: false })
        .order("created_at", { ascending: true })
        .limit(1);
      if (!locsError && locs && locs.length > 0) {
        locationHours = (locs[0].working_hours || {})[day] || null;
      }
    }

    const defaultHours: WorkingHoursDay = { is_open: true, open_time: "09:00", close_time: "18:00" };

    // Fetch existing booking conflicts for the day
    const startOfDayIso = isoAtLocalDateMinutes(date, 0);
    const endOfDayIso = isoAtLocalDateMinutes(date, 24 * 60 - 1);

    const { data: bookings, error: bookingsError } = await supabase
      .from("bookings")
      .select("id, status, provider_id, location_id")
      .eq("provider_id", provider.id)
      .gte("scheduled_at", startOfDayIso)
      .lte("scheduled_at", endOfDayIso)
      .not("status", "in", "(cancelled,no_show)");

    if (bookingsError) throw bookingsError;

    const bookingIds = (bookings || []).map((b) => b.id);
    let busyIntervals: Array<{ start: string; end: string; staff_id?: string | null }> = [];

    if (bookingIds.length > 0) {
      const { data: svcRows, error: svcError } = await supabase
        .from("booking_services")
        .select("scheduled_start_at, scheduled_end_at, staff_id, booking_id")
        .in("booking_id", bookingIds);
      if (svcError) throw svcError;
      busyIntervals = (svcRows || []).map((r) => ({
        start: r.scheduled_start_at,
        end: r.scheduled_end_at,
        staff_id: r.staff_id,
      }));
    }

    // Fetch availability blocks that overlap this day (block.end_at > startOfDay AND block.start_at < endOfDay)
    const { data: blocks, error: blocksError } = await supabase
      .from("availability_blocks")
      .select("start_at, end_at, staff_id, location_id")
      .eq("provider_id", provider.id)
      .gt("end_at", startOfDayIso)
      .lt("start_at", endOfDayIso);
    if (blocksError) throw blocksError;

    const step = 15;
    const slotDuration = durationMinutes;
    const totalSpan = slotDuration + bufferMinutes;

    const buildSlotsForStaff = (
      hours: WorkingHoursDay | null,
      sid: string | null
    ): AvailabilitySlot[] => {
      const chosen = hours || locationHours || defaultHours;
      const isOpen = chosen.is_open !== false;
      const openMin = parseTimeToMinutes(chosen.open_time || "09:00");
      const closeMin = parseTimeToMinutes(chosen.close_time || "18:00");
      if (!isOpen || openMin === null || closeMin === null || closeMin <= openMin) {
        return [];
      }
      const breakRanges: Array<{ start: number; end: number }> = [];
      for (const br of chosen.breaks ?? []) {
        const bs = parseTimeToMinutes(br.start);
        const be = parseTimeToMinutes(br.end);
        if (bs !== null && be !== null && be > bs) breakRanges.push({ start: bs, end: be });
      }
      const slotOverlapsBreak = (slotStartMin: number, slotEndMin: number) =>
        breakRanges.some((br) => slotStartMin < br.end && slotEndMin > br.start);

      const slots: AvailabilitySlot[] = [];
      for (let startMin = openMin; startMin + slotDuration <= closeMin; startMin += step) {
        const slotEndMin = startMin + slotDuration;
        if (slotOverlapsBreak(startMin, slotEndMin)) continue;
        const slotStartIso = isoAtLocalDateMinutes(date, startMin);
        const slotEndIso = isoAtLocalDateMinutes(date, slotEndMin);
        const blockEndIso = isoAtLocalDateMinutes(date, startMin + totalSpan);
        if (startMin + totalSpan > closeMin) continue;
        let available = true;
        for (const b of busyIntervals) {
          if (sid && b.staff_id && b.staff_id !== sid) continue;
          if (overlaps(slotStartIso, blockEndIso, b.start, b.end)) {
            available = false;
            break;
          }
        }
        if (available) {
          for (const blk of blocks || []) {
            if (sid && blk.staff_id && blk.staff_id !== sid) continue;
            if (locationId && blk.location_id && blk.location_id !== locationId) continue;
            if (overlaps(slotStartIso, blockEndIso, blk.start_at, blk.end_at)) {
              available = false;
              break;
            }
          }
        }
        // Return slot end as start + totalSpan so clients (holds) store the full blocked period including buffer
        const slotEndFullIso = isoAtLocalDateMinutes(date, startMin + totalSpan);
        slots.push({
          start: slotStartIso,
          end: slotEndFullIso,
          staff_id: sid || undefined,
          location_id: locationId || undefined,
          is_available: available,
        });
      }
      return slots;
    };

    let slots: AvailabilitySlot[];

    if (anyoneMode && staffList.length > 0) {
      const slotToStaff = new Map<string, string>();
      const allStarts = new Set<string>();
      for (const s of staffList) {
        // Use staff's working_hours; fallback to location/default is inside buildSlotsForStaff
        const hours = (s.working_hours || {})[day] || null;
        const staffSlots = buildSlotsForStaff(hours ?? locationHours, s.id);
        for (const slot of staffSlots) {
          allStarts.add(slot.start);
          if (slot.is_available && !slotToStaff.has(slot.start)) {
            slotToStaff.set(slot.start, s.id);
          }
        }
      }
      const totalSpan = slotDuration + bufferMinutes;
      slots = Array.from(allStarts)
        .sort()
        .map((start) => {
          const end = new Date(start);
          end.setMinutes(end.getMinutes() + totalSpan);
          const availableStaffId = slotToStaff.get(start);
          return {
            start,
            end: end.toISOString(),
            staff_id: availableStaffId || undefined,
            location_id: locationId || undefined,
            is_available: !!availableStaffId,
          };
        });
    } else {
      const chosen = staffHours || locationHours || defaultHours;
      const isOpen = chosen.is_open !== false;
      const openMin = parseTimeToMinutes(chosen.open_time || "09:00");
      const closeMin = parseTimeToMinutes(chosen.close_time || "18:00");
      if (!isOpen || openMin === null || closeMin === null || closeMin <= openMin) {
        return NextResponse.json({ data: { slots: [] }, error: null });
      }
      slots = buildSlotsForStaff(staffHours || locationHours || defaultHours, effectiveStaffId);
    }

    // Filter by max_advance_days: reject dates too far in the future
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const dateObj = new Date(`${date}T00:00:00`);
    dateObj.setHours(0, 0, 0, 0);
    const daysFromToday = Math.floor((dateObj.getTime() - today.getTime()) / (24 * 60 * 60 * 1000));
    if (daysFromToday > effectiveMaxAdvance) {
      return NextResponse.json({ data: { slots: [] }, error: null });
    }

    // Filter by min_notice_minutes: exclude slots starting before now + min notice
    if (effectiveMinNotice > 0 && date === today.toISOString().split("T")[0]) {
      const cutoff = new Date(Date.now() + effectiveMinNotice * 60 * 1000);
      slots = slots.filter((s) => new Date(s.start) >= cutoff);
    }

    // Filter by resource availability when service requires resources
    if (serviceId && slots.length > 0) {
      const { data: offeringRes } = await supabase
        .from("offering_resources")
        .select("resource_id")
        .eq("offering_id", serviceId)
        .eq("required", true);
      const resourceIds = [...new Set((offeringRes || []).map((r: any) => r.resource_id))];
      if (resourceIds.length > 0) {
        const { checkResourceAvailability } = await import("@/lib/resources/assignment");
        const slotDurationMs = durationMinutes * 60 * 1000;
        const availableSlots: AvailabilitySlot[] = [];
        for (const slot of slots) {
          const startAt = new Date(slot.start);
          const endAt = new Date(startAt.getTime() + slotDurationMs);
          const check = await checkResourceAvailability(supabase, resourceIds, startAt, endAt);
          if (check.available) {
            availableSlots.push(slot);
          } else {
            availableSlots.push({ ...slot, is_available: false });
          }
        }
        slots = availableSlots;
      }
    }

    return NextResponse.json({
      data: {
        slots: slots,
      },
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/public/providers/[slug]/availability:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch availability",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";

/**
 * GET /api/public/providers/[slug]/membership-plans
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ slug: string }> }
) {
  try {
    const supabase = await getSupabaseServer();
    const { slug } = await params;

    // First, get the provider by slug to get the id
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("id")
      .eq("slug", slug)
      .eq("status", "active")
      .single();

    if (providerError || !provider) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Provider not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    const providerData = provider as any;

    // Get membership plans for this provider
    const { data: plans, error: plansError } = await (supabase.from("membership_plans") as any)
      .select("id, provider_id, name, description, price_monthly, currency, discount_percent, is_active")
      .eq("provider_id", providerData.id)
      .eq("is_active", true)
      .order("created_at", { ascending: false });

    if (plansError) {
      console.error("Error fetching membership plans:", plansError);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to fetch membership plans",
            code: "FETCH_ERROR",
          },
        },
        { status: 500 }
      );
    }

    return NextResponse.json({ data: { plans: plans || [] }, error: null });
  } catch (error) {
    console.error("Unexpected error in /api/public/providers/[slug]/membership-plans:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch membership plans",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import type { OfferingCard } from "@/types/beautonomi";

/**
 * GET /api/public/providers/[slug]/offerings
 * 
 * Get all active offerings for a provider
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ slug: string }> }
) {
  try {
    const supabase = await getSupabaseServer();
    const { slug } = await params;

    // Get provider
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("id")
      .eq("slug", slug)
      .eq("status", "active")
      .single();

    if (providerError || !provider) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Provider not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    const providerData = provider as any;

    // Get offerings with master service info, provider category, and category
    const { data: offerings, error: offeringsError } = await supabase
      .from("offerings")
      .select(`
        *,
        master_service:master_service_id (
          id,
          name
        ),
        provider_categories:provider_category_id (
          id,
          name,
          color,
          display_order,
          description
        )
      `)
      .eq("provider_id", providerData.id)
      .eq("is_active", true)
      .order("title");

    if (offeringsError) {
      console.error("Error fetching offerings:", offeringsError);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to fetch offerings",
            code: "FETCH_ERROR",
          },
        },
        { status: 500 }
      );
    }

    // Transform to include master_service_name
    // Priority: provider_categories.name > master_service.name > category_name > "Other Services"
    const transformedOfferings = (offerings || []).map((offering: any) => {
      // Try to get category name from multiple sources
      let categoryName: string | null = null;
      
      // First priority: provider_categories name (provider's custom category)
      if (offering.provider_categories?.name) {
        categoryName = offering.provider_categories.name;
      }
      // Second priority: master_service name (from relationship)
      else if (offering.master_service?.name) {
        categoryName = offering.master_service.name;
      }
      // Third priority: category_name field directly on offering
      else if (offering.category_name) {
        categoryName = offering.category_name;
      }
      
      // Final fallback: use "Other Services" only if no category found
      if (!categoryName || categoryName.trim() === "") {
        categoryName = "Other Services";
      }
      
      return {
        ...offering,
        master_service_name: categoryName,
      };
    });

    return NextResponse.json({
      data: transformedOfferings as OfferingCard[],
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/public/providers/[slug]/offerings:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch offerings",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/public/providers/[slug]/packages
 *
 * Get all active service packages for a provider (public endpoint)
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string }> }
) {
  try {
    const { slug } = await params;
    const supabase = await getSupabaseServer();

    // Decode slug safely
    let decodedSlug: string;
    try {
      decodedSlug = decodeURIComponent(slug);
    } catch {
      decodedSlug = slug;
    }

    // Get provider by slug
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("id")
      .eq("slug", decodedSlug)
      .eq("status", "active")
      .single();

    let providerId: string | null = null;

    if (providerError || !provider) {
      // Try original slug if decoded fails
      const retry = await supabase
        .from("providers")
        .select("id")
        .eq("slug", slug)
        .eq("status", "active")
        .single();

      if (retry.error || !retry.data) {
        return successResponse([]); // Return empty array instead of 404
      }
      providerId = retry.data.id;
    } else {
      providerId = provider.id;
    }

    const { searchParams } = new URL(request.url);
    const locationId = searchParams.get("location_id");

    // Get all active packages for this provider
    const { data: packages, error: packagesError } = await supabase
      .from("service_packages")
      .select(`
        id,
        name,
        description,
        price,
        currency,
        discount_percentage,
        is_active,
        created_at
      `)
      .eq("provider_id", providerId)
      .eq("is_active", true)
      .order("created_at", { ascending: false });

    if (packagesError) {
      throw packagesError;
    }

    let filteredPackages = packages ?? [];
    if (locationId && filteredPackages.length > 0) {
      const pkgIds = filteredPackages.map((p: any) => p.id);
      const { data: atLocation } = await supabase
        .from("package_locations")
        .select("package_id")
        .in("package_id", pkgIds)
        .eq("location_id", locationId);
      const packageIdsAtLocation = new Set((atLocation ?? []).map((r: any) => r.package_id));
      const { data: allPkgLocs } = await supabase
        .from("package_locations")
        .select("package_id")
        .in("package_id", pkgIds);
      const packageIdsWithRestriction = new Set((allPkgLocs ?? []).map((r: any) => r.package_id));
      filteredPackages = filteredPackages.filter(
        (p: any) => !packageIdsWithRestriction.has(p.id) || packageIdsAtLocation.has(p.id)
      );
    }

    // Get items (services and products) included in each package
    const packageIds = filteredPackages.map((pkg: any) => pkg.id);

    if (packageIds.length > 0) {
      const { data: packageItems, error: itemsError } = await supabase
        .from("service_package_items")
        .select(`
          package_id,
          offering_id,
          product_id,
          quantity,
          offerings:offering_id(id, title, duration_minutes),
          products:product_id(id, name, retail_price, sku, brand)
        `)
        .in("package_id", packageIds);

      if (!itemsError && packageItems) {
        // Group items by package
        const itemsByPackage: Record<string, any[]> = {};
        packageItems.forEach((item: any) => {
          if (!itemsByPackage[item.package_id]) {
            itemsByPackage[item.package_id] = [];
          }
          if (item.offering) {
            itemsByPackage[item.package_id].push({
              id: item.offering.id,
              title: item.offering.title,
              type: "service",
              duration_minutes: item.offering.duration_minutes,
              quantity: item.quantity,
            });
          } else if (item.products) {
            itemsByPackage[item.package_id].push({
              id: item.products.id,
              title: item.products.name,
              type: "product",
              price: item.products.retail_price,
              sku: item.products.sku,
              brand: item.products.brand,
              quantity: item.quantity,
            });
          }
        });

        // Add items to each package
        filteredPackages.forEach((pkg: any) => {
          pkg.items = itemsByPackage[pkg.id] || [];
          pkg.services = itemsByPackage[pkg.id]?.filter((item: any) => item.type === "service") || [];
        });
      }
    }

    return successResponse(filteredPackages);
  } catch (error) {
    return handleApiError(error, "Failed to fetch packages");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/public/providers/[slug]/products
 * 
 * Get products available for booking (retail_sales_enabled = true)
 */
export async function GET(
  request: NextRequest,
  { params }: { params: { slug: string } }
) {
  try {
    const supabase = await getSupabaseServer();
    const { slug } = params;

    // Get provider by slug
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("id, status")
      .eq("slug", slug)
      .eq("status", "active")
      .single();

    if (providerError || !provider) {
      return NextResponse.json(
        { error: "Provider not found" },
        { status: 404 }
      );
    }

    // Get products available for retail sales (include has_variants)
    const { data: products, error: productsError } = await supabase
      .from("products")
      .select("id, name, short_description, description, retail_price, image_url, image_urls, quantity, track_stock_quantity, currency, has_variants, variant_option_types")
      .eq("provider_id", provider.id)
      .eq("is_active", true)
      .eq("retail_sales_enabled", true)
      .order("name", { ascending: true });

    if (productsError) {
      console.error("Error fetching products:", productsError);
      return handleApiError(productsError, "Failed to fetch products");
    }

    const productIds = (products || []).map((p: any) => p.id);
    const variantsByProduct: Record<string, any[]> = {};
    if (productIds.length > 0) {
      const { data: variants } = await supabase
        .from("product_variants")
        .select("id, product_id, option_values, sort_order, retail_price, quantity, sku")
        .in("product_id", productIds)
        .order("sort_order");
      (variants || []).forEach((v: any) => {
        if (!variantsByProduct[v.product_id]) variantsByProduct[v.product_id] = [];
        variantsByProduct[v.product_id].push(v);
      });
    }

    // Transform products for frontend
    const transformedProducts = (products || []).map((product: any) => {
      const withVariants = Boolean(product.has_variants) && Array.isArray(variantsByProduct[product.id]) && variantsByProduct[product.id].length > 0;
      const variantList = withVariants ? variantsByProduct[product.id].sort((a: any, b: any) => (a.sort_order ?? 0) - (b.sort_order ?? 0)) : [];
      const minPrice = withVariants && variantList.length ? Math.min(...variantList.map((v: any) => Number(v.retail_price || 0))) : Number(product.retail_price || 0);
      const inStock = withVariants ? variantList.some((v: any) => (v.quantity || 0) > 0) : (product.track_stock_quantity ? (product.quantity || 0) > 0 : true);
      const totalQty = withVariants ? variantList.reduce((s: number, v: any) => s + (v.quantity || 0), 0) : (product.quantity || 0);
      return {
        id: product.id,
        name: product.name,
        description: product.short_description || product.description || "",
        price: minPrice,
        currency: product.currency || "ZAR",
        imageUrl: product.image_url || (product.image_urls && product.image_urls.length > 0 ? product.image_urls[0] : null),
        inStock,
        quantity: totalQty,
        track_stock_quantity: product.track_stock_quantity || false,
        hasVariants: withVariants,
        variantOptionTypes: product.variant_option_types || [],
        variants: variantList.map((v: any) => ({ id: v.id, option_values: v.option_values, retail_price: Number(v.retail_price || 0), quantity: v.quantity || 0 })),
      };
    });

    return successResponse(transformedProducts);
  } catch (error) {
    return handleApiError(error, "Failed to fetch products");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { NextResponse } from "next/server";

/**
 * GET /api/public/providers/[slug]/resources
 * Returns resources required or optional for the given service(s).
 * Query: service_ids=id1,id2 (offering IDs). If empty, returns all active resources for the provider.
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string }> }
) {
  try {
    const supabase = await getSupabaseServer();
    const { slug } = await params;
    const { searchParams } = new URL(request.url);
    const serviceIdsParam = searchParams.get("service_ids");
    const serviceIds = serviceIdsParam
      ? serviceIdsParam.split(",").map((s) => s.trim()).filter(Boolean)
      : [];

    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("id")
      .eq("slug", decodeURIComponent(slug))
      .eq("status", "active")
      .maybeSingle();

    if (providerError || !provider) {
      return NextResponse.json(
        { data: null, error: { message: "Provider not found", code: "NOT_FOUND" } },
        { status: 404 }
      );
    }

    const providerId = (provider as { id: string }).id;

    if (serviceIds.length === 0) {
      const { data: resources, error: resError } = await supabase
        .from("resources")
        .select(`
          id,
          name,
          description,
          capacity,
          group_id,
          resource_groups(id, name)
        `)
        .eq("provider_id", providerId)
        .eq("is_active", true)
        .order("name");

      if (resError) throw resError;

      const list = (resources || []).map((r: any) => {
        const group = Array.isArray(r.resource_groups) ? r.resource_groups[0] : r.resource_groups;
        return {
          id: r.id,
          name: r.name,
          description: r.description ?? null,
          capacity: r.capacity ?? 1,
          resource_group_id: r.group_id ?? null,
          resource_group_name: group?.name ?? null,
          is_required: false,
        };
      });
      return NextResponse.json({ data: list, resources: list, error: null });
    }

    const { data: offeringResources, error: orError } = await supabase
      .from("offering_resources")
      .select("resource_id, required")
      .in("offering_id", serviceIds);

    if (orError) throw orError;

    const resourceIds = [...new Set((offeringResources || []).map((r: any) => r.resource_id))];
    if (resourceIds.length === 0) {
      return NextResponse.json({ data: [], resources: [], error: null });
    }

    const requiredSet = new Set(
      (offeringResources || [])
        .filter((r: any) => r.required === true)
        .map((r: any) => r.resource_id)
    );

    const { data: resources, error: resError } = await supabase
      .from("resources")
      .select(`
        id,
        name,
        description,
        capacity,
        group_id,
        resource_groups(id, name)
      `)
      .in("id", resourceIds)
      .eq("is_active", true)
      .order("name");

    if (resError) throw resError;

    const list = (resources || []).map((r: any) => {
      const group = Array.isArray(r.resource_groups) ? r.resource_groups[0] : r.resource_groups;
      return {
        id: r.id,
        name: r.name,
        description: r.description ?? null,
        capacity: r.capacity ?? 1,
        resource_group_id: r.group_id ?? null,
        resource_group_name: group?.name ?? null,
        is_required: requiredSet.has(r.id),
      };
    });

    return NextResponse.json({ data: list, resources: list, error: null });
  } catch (error) {
    console.error("Error in GET /api/public/providers/[slug]/resources:", error);
    return NextResponse.json(
      { data: null, resources: [], error: { message: "Failed to fetch resources", code: "INTERNAL_ERROR" } },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";

/**
 * GET /api/public/providers/[slug]/reviews
 * 
 * Returns reviews for a provider (public view).
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ slug: string }> }
) {
  try {
    const supabase = await getSupabaseServer();
    const { slug } = await params;
    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "20");
    const offset = (page - 1) * limit;

    // First get the provider ID from slug
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("id")
      .eq("slug", slug)
      .eq("status", "active")
      .single();

    if (providerError || !provider) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Provider not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    // Fetch reviews with user information
    const { data: reviews, error: reviewsError, count } = await supabase
      .from("reviews")
      .select(`
        id,
        rating,
        comment,
        created_at,
        users:user_id (
          id,
          full_name,
          avatar_url
        )
      `, { count: "exact" })
      .eq("provider_id", provider.id)
      .eq("status", "published")
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);

    if (reviewsError) {
      console.error("Error fetching reviews:", reviewsError);
      return NextResponse.json(
        {
          data: { reviews: [], total: 0, page, limit },
          error: null,
        }
      );
    }

    const formattedReviews = (reviews || []).map((review: any) => {
      const user = review.users || {};
      const reviewerName = user.full_name || "Anonymous";
      const reviewerInitial = reviewerName.charAt(0).toUpperCase();
      
      return {
        id: review.id,
        reviewerName,
        reviewerInitial,
        date: new Date(review.created_at).toLocaleString("en-US", {
          weekday: "short",
          year: "numeric",
          month: "short",
          day: "numeric",
          hour: "numeric",
          minute: "2-digit",
        }),
        rating: review.rating || 5,
        text: review.comment || "",
        avatar_url: user.avatar_url,
      };
    });

    return NextResponse.json({
      data: {
        reviews: formattedReviews,
        total: count || 0,
        page,
        limit,
        has_more: (count || 0) > offset + limit,
      },
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/public/providers/[slug]/reviews:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch reviews",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import type { PublicProviderDetail } from "@/types/beautonomi";

// Increase timeout for this route
export const maxDuration = 30; // 30 seconds
// Cache provider profiles for 5 minutes (they don't change often)
export const revalidate = 300;

/**
 * GET /api/public/providers/[slug]
 * 
 * Returns detailed provider information for public viewing.
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ slug: string }> }
) {
  try {
    const supabase = await getSupabaseServer();
    const { slug: rawSlug } = await params;

    // Decode slug in case it's URL encoded (safely)
    let slug: string;
    let decodedSlug: string;
    try {
      decodedSlug = decodeURIComponent(rawSlug);
      slug = decodedSlug;
    } catch {
      // If decoding fails, use original
      slug = rawSlug;
      decodedSlug = rawSlug;
    }

    console.log(`[Provider API] Fetching provider with slug: ${decodedSlug} (raw: ${rawSlug})`);

    // Fetch provider - use left join for users to avoid filtering out providers if user doesn't exist
    // Note: accepts_custom_requests may not exist in all databases, so we'll fetch it separately if needed
    let provider: any;
    let providerError: any;
    const initial = await supabase
      .from("providers")
      .select(`
        id,
        slug,
        business_name,
        business_type,
        description,
        rating_average,
        review_count,
        thumbnail_url,
        avatar_url,
        gallery,
        is_featured,
        is_verified,
        currency,
        years_in_business,
        tax_rate_percent,
        tips_enabled,
        website,
        social_media_links,
        accepts_custom_requests,
        response_rate,
        response_time_hours,
        languages_spoken,
        offers_mobile_services,
        minimum_mobile_booking_amount,
        user_id,
        users(include_in_search_engines)
      `)
      .eq("slug", decodedSlug)
      .eq("status", "active")
      .maybeSingle(); // Use maybeSingle instead of single to avoid errors if not found
    provider = initial.data;
    providerError = initial.error;

    // If not found with decoded slug, try original slug
    if (providerError || !provider) {
      console.log(`[Provider API] Not found with decoded slug, trying original: ${slug}`);
      const retry = await supabase
        .from("providers")
        .select(`
          id,
          slug,
          business_name,
          business_type,
          description,
          rating_average,
          review_count,
          thumbnail_url,
          avatar_url,
          gallery,
          is_featured,
          is_verified,
          currency,
          years_in_business,
          tax_rate_percent,
          tips_enabled,
          offers_mobile_services,
          minimum_mobile_booking_amount,
          user_id,
          users(include_in_search_engines)
        `)
        .eq("slug", slug)
        .eq("status", "active")
        .maybeSingle(); // Use maybeSingle instead of single

      provider = retry.data;
      providerError = retry.error;
    }

    if (providerError || !provider) {
      console.error(`[Provider API] Provider not found. Slug: ${decodedSlug}, Original: ${slug}, Error:`, providerError);
      console.error(`[Provider API] Error details:`, {
        code: providerError?.code,
        message: providerError?.message,
        details: providerError?.details,
        hint: providerError?.hint,
      });

      // Try to find by ID if slug looks like a UUID
      if (slug.match(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i)) {
        console.log(`[Provider API] Slug looks like UUID, trying to find by ID: ${slug}`);
        const { data: providerById, error: idError } = await supabase
          .from("providers")
          .select(`
            id,
            slug,
            business_name,
            business_type,
            description,
            rating_average,
            review_count,
            thumbnail_url,
            avatar_url,
            gallery,
            is_featured,
            is_verified,
            currency,
            years_in_business,
            user_id,
            users(include_in_search_engines)
          `)
          .eq("id", slug)
          .eq("status", "active")
          .single();

        if (providerById && !idError) {
          console.log(`[Provider API] Found provider by ID: ${providerById.business_name}`);
          provider = providerById;
          providerError = null;
        }
      }

      if (providerError || !provider) {
        // Last attempt: try without status filter (in case status is not 'active' but provider exists)
        console.log(`[Provider API] Trying without status filter as last attempt`);
        const lastAttempt = await supabase
          .from("providers")
          .select(`
            id,
            slug,
            business_name,
            business_type,
            description,
            rating_average,
            review_count,
            thumbnail_url,
            avatar_url,
            gallery,
            is_featured,
            is_verified,
            currency,
            years_in_business,
            tax_rate_percent,
            tips_enabled,
            status,
            user_id,
            users(include_in_search_engines)
          `)
          .eq("slug", decodedSlug)
          .single();

        if (lastAttempt.data && !lastAttempt.error) {
          console.log(`[Provider API] Found provider but status is: ${lastAttempt.data.status}`);
          // If provider exists but status is not active, still return it but log a warning
          if (lastAttempt.data.status !== 'active') {
            console.warn(`[Provider API] Provider ${lastAttempt.data.business_name} is not active (status: ${lastAttempt.data.status})`);
          }
          provider = lastAttempt.data;
          providerError = null;
        } else {
          return NextResponse.json(
            {
              data: null,
              error: {
                message: "Provider not found",
                code: "NOT_FOUND",
                details: {
                  slug: decodedSlug,
                  originalSlug: slug,
                  error: providerError?.message || "No provider found with this slug",
                },
              },
            },
            { status: 404 }
          );
        }
      }
    }

    console.log(`[Provider API] Found provider: ${provider.business_name} (ID: ${provider.id})`);

    const providerData = provider as any;

    // Check if provider has include_in_search_engines enabled
    // The users relation should be available from the select query
    const userData = (providerData as any).users;
    const includeInSearchEngines = userData?.include_in_search_engines ?? false;

    // Extract new fields from provider data (with fallbacks for migration period)
    const acceptsCustomRequests = providerData.accepts_custom_requests ?? true;
    const website = providerData.website ?? null;
    const socialMediaLinks = providerData.social_media_links ?? {};
    const responseRate = providerData.response_rate ?? 100;
    const responseTimeHours = providerData.response_time_hours ?? 1;
    const languagesSpoken = providerData.languages_spoken ?? ['English'];

    // Fetch all related data in parallel for better performance
    const [
      locationsResult,
      offeringsResult,
      staffCountResult,
      policiesResult,
      pointsResult,
    ] = await Promise.all([
      // Fetch locations
      supabase
        .from("provider_locations")
        .select("*")
        .eq("provider_id", providerData.id)
        .eq("is_active", true),

      // Fetch categories and prices (from offerings) - also get supports_at_home
      supabase
        .from("offerings")
        .select("category_id, price, currency, category_name, provider_category_id, supports_at_home, service_id")
        .eq("provider_id", providerData.id)
        .eq("is_active", true)
        .limit(100), // Limit to prevent huge queries

      // Fetch staff count (for salons)
      providerData.business_type === "salon"
        ? supabase
            .from("provider_staff")
            .select("*", { count: "exact", head: true })
            .eq("provider_id", providerData.id)
            .eq("is_active", true)
        : Promise.resolve({ count: 0 }),

      // Fetch policies
      supabase
        .from("provider_policies")
        .select("*")
        .eq("provider_id", providerData.id)
        .maybeSingle(),

      // Fetch points and badge
      supabase
        .from("provider_points")
        .select(`
          total_points,
          current_badge_id,
          provider_badges!provider_points_current_badge_id_fkey (
            id,
            name,
            slug,
            description,
            icon_url,
            tier,
            color,
            requirements,
            benefits
          )
        `)
        .eq("provider_id", providerData.id)
        .maybeSingle(),
    ]);

    const locations = locationsResult.data || [];
    const offerings = offeringsResult.data || [];
    const staffCount = staffCountResult.count || undefined;
    const policies = policiesResult.data;
    const pointsData = pointsResult.data;

    // Extract badge from points data (Supabase may return relation as array)
    let currentBadge = null;
    const badge = Array.isArray(pointsData?.provider_badges) ? pointsData?.provider_badges?.[0] : pointsData?.provider_badges;
    if (badge) {
      currentBadge = {
        id: badge.id,
        name: badge.name,
        slug: badge.slug,
        description: badge.description,
        icon_url: badge.icon_url,
        tier: badge.tier,
        color: badge.color,
        requirements: badge.requirements,
        benefits: badge.benefits,
      };
    }

    // Get category names - prioritize provider_categories, then global_service_categories
    const categories: string[] = [];

    // Get provider category IDs
    const providerCategoryIds = Array.from(
      new Set(offerings?.map((o: any) => o.provider_category_id).filter(Boolean) || [])
    );

    if (providerCategoryIds.length > 0) {
      const { data: providerCategoryData } = await supabase
        .from("provider_categories")
        .select("name")
        .in("id", providerCategoryIds);
      categories.push(...(providerCategoryData?.map((c: any) => c.name) || []));
    }

    // Get category names from global_service_categories
    const categoryIds = Array.from(
      new Set(offerings?.map((o: any) => o.category_id).filter(Boolean) || [])
    );
    if (categoryIds.length > 0) {
      const { data: categoryData } = await supabase
        .from("global_service_categories")
        .select("name")
        .in("id", categoryIds);
      const globalCategories = categoryData?.map((c: any) => c.name) || [];
      categories.push(...globalCategories.filter((c: string) => !categories.includes(c)));
    }

    const offeringsData = offerings as any;
    const offeringCategories = Array.from(
      new Set(offeringsData?.map((o: any) => o.category_name).filter(Boolean) || [])
    );
    // Merge both category sources
    categories.push(...(Array.from(offeringCategories) as string[]).filter((c) => !categories.includes(c)));

    // Get primary location for city/country
    const primaryLocation = locations?.find((loc: any) => loc.is_primary) || locations?.[0];
    const city = primaryLocation?.city || "";
    const country = primaryLocation?.country || "";

    // Calculate starting_price from offerings
    let startingPrice: number | undefined;
    if (offerings && offerings.length > 0) {
      const prices = (offerings as any[])
        .filter((o: any) => o.price && o.price > 0)
        .map((o: any) => o.price);
      if (prices.length > 0) {
        startingPrice = Math.min(...prices);
      }
    }

    // Determine service type support (house calls and salon)
    let supportsHouseCalls = false;
    let supportsSalon = false;

    // Check if provider supports house calls (any offering with supports_at_home = true)
    if (offerings && offerings.length > 0) {
      supportsHouseCalls = (offerings as any[]).some((o: any) => o.supports_at_home === true);
    }

    // Also check services table for supports_at_home if no offerings found
    if (!supportsHouseCalls && offerings && offerings.length > 0) {
      const serviceIds = (offerings as any[])
        .map((o: any) => o.service_id)
        .filter(Boolean);

      if (serviceIds.length > 0) {
        const { data: servicesData } = await supabase
          .from("services")
          .select("supports_at_home")
          .in("id", serviceIds)
          .limit(100);

        if (servicesData && servicesData.length > 0) {
          supportsHouseCalls = servicesData.some((s: any) => s.supports_at_home === true);
        }
      }
    }

    // Support salon only if provider has at least one physical salon location (location_type = 'salon').
    // Base-only locations (location_type = 'base') are for distance/travel onlyΓÇömobile-only freelancers.
    const salonLocations = (locations || []).filter((l: any) => (l.location_type || "salon") === "salon");
    supportsSalon = salonLocations.length > 0;

    // Ensure business_name is not null/undefined
    if (!providerData.business_name) {
      console.warn(`Provider ${providerData.id} (slug: ${slug}) has no business_name`);
    }

    const result: PublicProviderDetail = {
      id: providerData.id,
      slug: providerData.slug,
      business_name: providerData.business_name || "Provider",
      business_type: providerData.business_type,
      rating: providerData.rating_average ?? 0,
      review_count: providerData.review_count ?? 0,
      thumbnail_url: providerData.thumbnail_url,
      avatar_url: providerData.avatar_url ?? null,
      city: city,
      country: country,
      is_featured: providerData.is_featured ?? false,
      is_verified: providerData.is_verified ?? false,
      starting_price: startingPrice,
      currency: providerData.currency || "ZAR",
      description: providerData.description || "",
      gallery: providerData.gallery || [],
      categories: categories as string[],
      supports_house_calls: supportsHouseCalls,
      supports_salon: supportsSalon,
      // Include location_type so booking flow can show only salon locations for "Visit Salon"; base = distance-only (mobile-only).
      locations: ((locations || []) as any[]).map((loc: any) => ({
        id: loc.id,
        provider_id: loc.provider_id,
        name: loc.name,
        address_line1: loc.address_line1,
        address_line2: loc.address_line2,
        city: loc.city,
        state: loc.state,
        country: loc.country,
        postal_code: loc.postal_code,
        latitude: loc.latitude,
        longitude: loc.longitude,
        phone: loc.phone,
        is_active: loc.is_active,
        working_hours: loc.working_hours,
        location_type: loc.location_type || "salon",
        created_at: loc.created_at,
        updated_at: loc.updated_at,
      })),
      policies: policies
        ? {
            cancellation_window_hours: (policies as any).cancellation_window_hours,
            requires_deposit: (policies as any).requires_deposit,
            deposit_percentage: (policies as any).deposit_percentage,
            no_show_fee_enabled: (policies as any).no_show_fee_enabled,
            no_show_fee_amount: (policies as any).no_show_fee_amount,
            currency: (policies as any).currency,
          }
        : {
            cancellation_window_hours: 24,
            requires_deposit: false,
            no_show_fee_enabled: false,
            currency: providerData.currency,
          },
      staff_count: staffCount,
      years_in_business: providerData.years_in_business,
      accepts_custom_requests: acceptsCustomRequests,
      website: website,
      social_media_links: socialMediaLinks,
      response_rate: responseRate,
      response_time_hours: responseTimeHours,
      languages_spoken: languagesSpoken,
      current_badge: currentBadge,
      total_points: pointsData?.total_points || undefined,
    };

    const response = NextResponse.json({
      data: result,
      error: null,
    });

    // Cache provider profiles for 5 minutes
    response.headers.set('Cache-Control', 'public, s-maxage=300, stale-while-revalidate=600');

    // Add X-Robots-Tag header to control search engine indexing
    // If include_in_search_engines is false, tell search engines not to index this page
    if (!includeInSearchEngines) {
      response.headers.set('X-Robots-Tag', 'noindex, nofollow');
    }

    return response;
  } catch (error) {
    console.error("Unexpected error in /api/public/providers/[slug]:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch provider",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, handleApiError, notFoundResponse } from "@/lib/supabase/api-helpers";

/**
 * GET /api/public/providers/[slug]/service-zones
 * 
 * Returns service zones for a provider (for display purposes)
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ slug: string }> }
) {
  try {
    const supabase = await getSupabaseServer();
    const { slug: rawSlug } = await params;
    
    // Decode slug
    let slug: string;
    try {
      slug = decodeURIComponent(rawSlug);
    } catch {
      slug = rawSlug;
    }

    // Get provider ID
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("id")
      .eq("slug", slug)
      .eq("status", "active")
      .single();

    if (providerError || !provider) {
      return notFoundResponse("Provider not found");
    }

    // Get platform zones that this provider has selected
    const { data: providerZoneSelections, error: zonesError } = await supabase
      .from("provider_zone_selections")
      .select(`
        id,
        travel_fee,
        travel_time_minutes,
        platform_zone:platform_zones (
          id,
          name,
          zone_type,
          description,
          cities,
          postal_codes,
          center_latitude,
          center_longitude,
          radius_km
        )
      `)
      .eq("provider_id", provider.id)
      .eq("is_active", true);

    if (zonesError) {
      throw zonesError;
    }

    // Format zones for display
    const zones = (providerZoneSelections || []).map((selection: any) => {
      const zone = selection.platform_zone;
      if (!zone) return null;

      return {
        id: zone.id,
        name: zone.name,
        type: zone.zone_type,
        description: zone.description,
        travelFee: selection.travel_fee,
        travelTimeMinutes: selection.travel_time_minutes,
        // Format coverage info for display
        coverage: zone.zone_type === "city" && zone.cities
          ? `Cities: ${zone.cities.join(", ")}`
          : zone.zone_type === "postal_code" && zone.postal_codes
          ? `${zone.postal_codes.length} postal code${zone.postal_codes.length > 1 ? "s" : ""}`
          : zone.zone_type === "radius" && zone.radius_km
          ? `Within ${zone.radius_km}km radius`
          : zone.zone_type === "polygon"
          ? "Custom area"
          : "Service area",
      };
    }).filter(Boolean);

    // Also check legacy service_zones table for backward compatibility
    const { data: legacyZones, error: legacyError } = await supabase
      .from("service_zones")
      .select("*")
      .eq("provider_id", provider.id)
      .eq("is_active", true);

    if (!legacyError && legacyZones && legacyZones.length > 0) {
      const legacyFormatted = legacyZones.map((zone: any) => ({
        id: zone.id,
        name: zone.name,
        type: zone.zone_type,
        description: null,
        travelFee: zone.travel_fee,
        travelTimeMinutes: zone.travel_time_minutes,
        coverage: zone.zone_type === "city" && zone.cities
          ? `Cities: ${zone.cities.join(", ")}`
          : zone.zone_type === "postal_code" && zone.postal_codes
          ? `${zone.postal_codes.length} postal code${zone.postal_codes.length > 1 ? "s" : ""}`
          : zone.zone_type === "radius" && zone.radius_km
          ? `Within ${zone.radius_km}km radius`
          : "Service area",
      }));

      zones.push(...legacyFormatted);
    }

    return successResponse({
      zones: zones,
      providerId: provider.id,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch service zones");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, notFoundResponse, handleApiError } from "@/lib/supabase/api-helpers";

/** Empty addons response so booking flow never 404s on addons */
function emptyAddonsResponse(serviceId: string) {
  return successResponse({
    service_id: serviceId,
    service_name: null,
    categories: [],
    all_addons: [],
    total_count: 0,
    has_recommended: false,
  });
}

/**
 * GET /api/public/providers/[slug]/services/[serviceId]/addons
 *
 * Get all add-ons applicable to a specific service (public endpoint for checkout).
 * Accepts either an offering id or a service id. Returns 200 with empty addons when
 * the service is not found so the booking flow does not break.
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string; serviceId: string }> }
) {
  try {
    const { slug, serviceId } = await params;
    const supabase = await getSupabaseServer();

    // Get provider by slug
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("id")
      .eq("slug", slug)
      .single();

    if (providerError || !provider) {
      return notFoundResponse("Provider not found");
    }

    // Resolve service: try as offering id first, then as service_id on offerings
    let service: { id: string; title: string; provider_id: string; service_id?: string | null } | null = null;
    const byOfferingId = await supabase
      .from("offerings")
      .select("id, title, provider_id, service_id")
      .eq("id", serviceId)
      .eq("provider_id", provider.id)
      .single();

    if (byOfferingId.data) {
      service = byOfferingId.data;
    } else {
      const byServiceId = await supabase
        .from("offerings")
        .select("id, title, provider_id, service_id")
        .eq("service_id", serviceId)
        .eq("provider_id", provider.id)
        .limit(1)
        .maybeSingle();
      if (byServiceId.data) service = byServiceId.data;
    }

    if (!service) {
      return emptyAddonsResponse(serviceId);
    }

    // applicable_service_ids may reference service_id or offering id; match both when available
    const orClause =
      service.service_id && service.service_id !== serviceId
        ? `applicable_service_ids.is.null,applicable_service_ids.cs.{${serviceId}},applicable_service_ids.cs.{${service.service_id}}`
        : `applicable_service_ids.is.null,applicable_service_ids.cs.{${serviceId}}`;

    const { data: addons, error } = await supabase
      .from("offerings")
      .select(`
        id,
        title,
        description,
        price,
        duration_minutes,
        currency,
        addon_category,
        is_recommended,
        applicable_service_ids,
        display_order
      `)
      .eq("provider_id", provider.id)
      .eq("service_type", "addon")
      .eq("is_active", true)
      .eq("online_booking_enabled", true)
      .or(orClause)
      .order("is_recommended", { ascending: false })
      .order("addon_category")
      .order("display_order");

    if (error) {
      throw error;
    }

    // Group add-ons by category
    const groupedAddons: Record<string, { name: string; addons: any[] }> = {};

    const categoryLabels: Record<string, string> = {
      hair_treatments: "Hair Treatments",
      nail_enhancements: "Nail Enhancements",
      skin_treatments: "Skin Treatments",
      massage_extras: "Massage Extras",
      styling_extras: "Styling Extras",
      waxing_extras: "Waxing Extras",
      general: "Additional Options",
    };

    (addons || []).forEach((addon: any) => {
      const category = addon.addon_category || "general";
      if (!groupedAddons[category]) {
        groupedAddons[category] = {
          name: categoryLabels[category] || category,
          addons: [],
        };
      }
      groupedAddons[category].addons.push({
        id: addon.id,
        title: addon.title,
        description: addon.description,
        price: addon.price,
        duration_minutes: addon.duration_minutes,
        currency: addon.currency,
        is_recommended: addon.is_recommended,
      });
    });

    // Convert to sorted array (recommended categories first)
    const sortedCategories = Object.entries(groupedAddons)
      .map(([key, value]) => ({
        category: key,
        name: value.name,
        addons: value.addons,
      }))
      .sort((a, b) => {
        // Put categories with recommended items first
        const aHasRecommended = a.addons.some((addon) => addon.is_recommended);
        const bHasRecommended = b.addons.some((addon) => addon.is_recommended);
        if (aHasRecommended && !bHasRecommended) return -1;
        if (!aHasRecommended && bHasRecommended) return 1;
        return 0;
      });

    return successResponse({
      service_id: serviceId,
      service_name: service.title,
      categories: sortedCategories,
      all_addons: addons || [],
      total_count: (addons || []).length,
      has_recommended: (addons || []).some((a: any) => a.is_recommended),
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch add-ons");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, notFoundResponse, handleApiError } from "@/lib/supabase/api-helpers";

/**
 * GET /api/public/providers/[slug]/services/[serviceId]/variants
 * 
 * Get all variants for a specific service (public endpoint for booking)
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string; serviceId: string }> }
) {
  try {
    const { slug, serviceId } = await params;
    const supabase = await getSupabaseServer();

    // Get provider by slug
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("id")
      .eq("slug", slug)
      .single();

    if (providerError || !provider) {
      return notFoundResponse("Provider not found");
    }

    // Verify the service belongs to this provider
    const { data: service, error: serviceError } = await supabase
      .from("offerings")
      .select("id, title, provider_id, service_type")
      .eq("id", serviceId)
      .eq("provider_id", provider.id)
      .single();

    if (serviceError || !service) {
      return notFoundResponse("Service not found");
    }

    // Get all variants for this service
    const { data: variants, error } = await supabase
      .from("offerings")
      .select(`
        id,
        title,
        variant_name,
        description,
        price,
        duration_minutes,
        currency,
        variant_sort_order,
        display_order
      `)
      .eq("parent_service_id", serviceId)
      .eq("service_type", "variant")
      .eq("is_active", true)
      .order("variant_sort_order")
      .order("price");

    if (error) {
      throw error;
    }

    return successResponse({
      parent_service: {
        id: service.id,
        title: service.title,
        service_type: service.service_type,
      },
      variants: (variants || []).map((v: any) => ({
        id: v.id,
        title: v.title,
        variant_name: v.variant_name,
        description: v.description,
        price: parseFloat(v.price || 0),
        duration: v.duration_minutes,
        currency: v.currency || "ZAR",
      })),
      total_count: (variants || []).length,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch variants");
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, notFoundResponse, handleApiError } from "@/lib/supabase/api-helpers";

interface ServiceWithVariants {
  id: string;
  title: string;
  description: string | null;
  price: number;
  duration_minutes: number;
  currency: string;
  service_type: string;
  category_id: string | null;
  category_name: string | null;
  supports_at_home: boolean;
  supports_at_salon: boolean;
  has_variants: boolean;
  variants: any[];
}

/**
 * GET /api/public/providers/[slug]/services
 * 
 * Get all bookable services for a provider (public endpoint for checkout)
 * - Filters out add-ons (they're shown separately during checkout)
 * - Groups variants under their parent service
 * - Returns services organized by category
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string }> }
) {
  try {
    const { slug: providerSlug } = await params;
    const supabase = await getSupabaseServer();

    // Get provider by slug
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("id, business_name, slug")
      .eq("slug", providerSlug)
      .single();

    if (providerError || !provider) {
      return notFoundResponse("Provider not found");
    }

    // Get all active services (excluding add-ons and variants with parents)
    const { data: services, error: servicesError } = await supabase
      .from("offerings")
      .select(`
        id,
        title,
        description,
        price,
        duration_minutes,
        currency,
        service_type,
        service_available_for,
        supports_at_home,
        supports_at_salon,
        online_booking_enabled,
        parent_service_id,
        variant_name,
        variant_sort_order,
        display_order,
        provider_category_id,
        provider_categories (
          id,
          name,
          color,
          display_order
        )
      `)
      .eq("provider_id", provider.id)
      .eq("is_active", true)
      .eq("online_booking_enabled", true)
      .neq("service_type", "addon") // Exclude add-ons
      .order("display_order");

    if (servicesError) {
      throw servicesError;
    }

    // Separate parent services and variants
    const parentServices: any[] = [];
    const variantsByParent: Record<string, any[]> = {};

    (services || []).forEach((service: any) => {
      if (service.service_type === "variant" && service.parent_service_id) {
        // This is a variant - group it under parent
        if (!variantsByParent[service.parent_service_id]) {
          variantsByParent[service.parent_service_id] = [];
        }
        variantsByParent[service.parent_service_id].push({
          id: service.id,
          title: service.title,
          variant_name: service.variant_name || service.title,
          description: service.description,
          price: service.price,
          duration_minutes: service.duration_minutes,
          currency: service.currency,
          variant_sort_order: service.variant_sort_order,
        });
      } else if (!service.parent_service_id) {
        // This is a parent/standalone service
        parentServices.push(service);
      }
    });

    // Build final service list with variants attached
    const servicesWithVariants: ServiceWithVariants[] = parentServices.map((service) => {
      const variants = variantsByParent[service.id] || [];
      // Sort variants by sort_order then price
      variants.sort((a, b) => (a.variant_sort_order || 0) - (b.variant_sort_order || 0) || a.price - b.price);

      return {
        id: service.id,
        title: service.title,
        description: service.description,
        price: service.price,
        duration_minutes: service.duration_minutes,
        currency: service.currency,
        service_type: service.service_type,
        service_available_for: service.service_available_for,
        category_id: service.provider_category_id,
        category_name: service.provider_categories?.name || null,
        category_color: service.provider_categories?.color || null,
        category_order: service.provider_categories?.display_order || 0,
        supports_at_home: service.supports_at_home || false,
        supports_at_salon: service.supports_at_salon !== false,
        has_variants: variants.length > 0,
        variants: variants,
        display_order: service.display_order,
      };
    });

    // Group by category
    const categories: Record<string, { name: string; color: string | null; order: number; services: ServiceWithVariants[] }> = {};

    servicesWithVariants.forEach((service) => {
      const categoryId = service.category_id || "uncategorized";
      const categoryName = service.category_name || "Other Services";

      if (!categories[categoryId]) {
        categories[categoryId] = {
          name: categoryName,
          color: (service as any).category_color || null,
          order: (service as any).category_order || 999,
          services: [],
        };
      }
      categories[categoryId].services.push(service);
    });

    // Convert to sorted array
    const sortedCategories = Object.entries(categories)
      .map(([id, cat]) => ({
        id,
        name: cat.name,
        color: cat.color,
        services: cat.services.sort((a, b) => ((a as any).display_order || 0) - ((b as any).display_order || 0)),
      }))
      .sort((a, b) => {
        const orderA = categories[a.id]?.order || 999;
        const orderB = categories[b.id]?.order || 999;
        return orderA - orderB;
      });

    return successResponse({
      provider: {
        id: provider.id,
        business_name: provider.business_name,
        slug: provider.slug,
      },
      categories: sortedCategories,
      total_services: servicesWithVariants.length,
    });
  } catch (error) {
    return handleApiError(error, "Failed to fetch services");
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";

/**
 * GET /api/public/providers/[slug]/staff
 *
 * Returns staff members for a provider (public view).
 * When the provider has no provider_staff rows (e.g. solo/freelancer), returns one synthetic
 * option so the booking UI can still show a choice.
 */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ slug: string }> }
) {
  try {
    const supabase = await getSupabaseServer();
    let { slug } = await params;
    try {
      slug = decodeURIComponent(slug);
    } catch {
      // keep slug as-is if decode fails
    }

    // First get the provider (id + business_name for synthetic staff when needed)
    const { data: provider, error: providerError } = await supabase
      .from("providers")
      .select("id, business_name")
      .eq("slug", slug)
      .eq("status", "active")
      .single();

    if (providerError || !provider) {
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Provider not found",
            code: "NOT_FOUND",
          },
        },
        { status: 404 }
      );
    }

    // Fetch active staff members (provider_staff has no specialties column; use [] in response)
    const { data: staff, error: staffError } = await supabase
      .from("provider_staff")
      .select(`
        id,
        name,
        role,
        avatar_url,
        bio,
        is_active
      `)
      .eq("provider_id", provider.id)
      .eq("is_active", true)
      .order("name");

    if (staffError) {
      console.error("Error fetching staff:", staffError);
      return NextResponse.json(
        {
          data: [],
          error: null,
        }
      );
    }

    let staffMembers = (staff || []).map((member: any) => ({
      id: member.id,
      name: member.name || "Staff Member",
      role: member.role || "Staff",
      avatar_url: member.avatar_url,
      bio: member.bio,
      specialties: member.specialties || [],
      mobileReady: true,
    }));

    // When provider has no staff rows (e.g. solo/freelancer), return one synthetic option
    // so the step shows a selectable specialist; availability treats provider-* as "any"
    if (staffMembers.length === 0 && provider?.id && provider?.business_name) {
      staffMembers = [
        {
          id: `provider-${provider.id}`,
          name: provider.business_name,
          role: "Your specialist",
          avatar_url: null,
          bio: null,
          specialties: [],
          mobileReady: true,
        },
      ];
    }

    return NextResponse.json({
      data: staffMembers,
      error: null,
    });
  } catch (error) {
    console.error("Unexpected error in /api/public/providers/[slug]/staff:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to fetch staff",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { runAdsAuction, recordAdImpressions } from "@/lib/ads/auction";
import type { SearchFilters, SearchResult } from "@/types/beautonomi";

export const dynamic = "force-dynamic";
// Cache search results for 30 seconds
export const revalidate = 30;

/**
 * GET /api/public/search
 * 
 * Search for providers and services based on filters.
 */
export async function GET(request: Request) {
  try {
    const supabase = await getSupabaseServer();
    const { searchParams } = new URL(request.url);

    // Debug logging
    console.log("Search API called with params:", Object.fromEntries(searchParams.entries()));

    // Get text query for provider name search (accept both "query" and "q" for compatibility)
    const queryText = searchParams.get("query") || searchParams.get("q") || undefined;

    // Parse filters from query params
    const filters: SearchFilters = {
      category: searchParams.get("category") || undefined,
      subcategory: searchParams.get("subcategory") || undefined,
      service: searchParams.get("service") || undefined,
      at_home: searchParams.get("at_home") === "true" ? true : undefined,
      date: searchParams.get("date") || undefined,
      time_preference: (searchParams.get("time_preference") as any) || undefined,
      price_min: searchParams.get("price_min") ? Number(searchParams.get("price_min")) : undefined,
      price_max: searchParams.get("price_max") ? Number(searchParams.get("price_max")) : undefined,
      rating_min: searchParams.get("rating_min") ? Number(searchParams.get("rating_min")) : undefined,
      sort_by: (searchParams.get("sort_by") as any) || "relevance",
      page: searchParams.get("page") ? Number(searchParams.get("page")) : 1,
      limit: searchParams.get("limit") ? Number(searchParams.get("limit")) : 20,
    };

    // Location filters
    const city = searchParams.get("city");
    const country = searchParams.get("country");
    const lat = searchParams.get("lat");
    const lng = searchParams.get("lng");
    const radius = searchParams.get("radius_km");

    if (city || country || (lat && lng)) {
      filters.location = {
        city: city || undefined,
        country: country || undefined,
        latitude: lat ? Number(lat) : undefined,
        longitude: lng ? Number(lng) : undefined,
        radius_km: radius ? Number(radius) : undefined,
      };
    }

    const page = filters.page || 1;
    const limit = filters.limit || 20;
    const offset = (page - 1) * limit;

    // Build query with count
    // Note: city and country are in provider_locations, not providers table
    // starting_price may need to be calculated from offerings
    let query = supabase
      .from("providers")
      .select(`
        id,
        slug,
        business_name,
        business_type,
        description,
        rating_average,
        review_count,
        thumbnail_url,
        avatar_url,
        is_featured,
        is_verified,
        currency
      `, { count: "exact" })
      .eq("status", "active");

    // Apply text search for provider name
    // Search in business_name and description
    if (queryText && queryText.trim()) {
      const searchTerm = queryText.trim();
      // Use or() to search across multiple fields with proper wildcard syntax
      query = query.or(`business_name.ilike.%${searchTerm}%,description.ilike.%${searchTerm}%`);
    }

    // Apply filters
    // Location filtering needs to go through provider_locations
    // We'll filter by provider IDs that match the location criteria
    let locationProviderIds: string[] | undefined;
    if (filters.location?.city || filters.location?.country) {
      const locationQuery = supabase
        .from("provider_locations")
        .select("provider_id")
        .eq("is_active", true);

      // Use case-insensitive matching for city and country with partial matching
      if (filters.location?.city) {
        const cityValue = filters.location.city.trim();
        locationQuery.ilike("city", `%${cityValue}%`);
      }
      if (filters.location?.country) {
        const countryValue = filters.location.country.trim();
        locationQuery.ilike("country", `%${countryValue}%`);
      }

      const { data: locations, error: locationError } = await locationQuery;

      if (locationError) {
        console.error("Error querying provider_locations:", locationError);
        // Continue without location filter if there's an error
        locationProviderIds = undefined;
      } else {
        locationProviderIds = locations?.map((loc: any) => loc.provider_id) || [];
      }

      if (locationProviderIds && locationProviderIds.length === 0) {
        // No providers match location criteria, return empty result
        return NextResponse.json({
          data: {
            providers: [],
            services: [],
            total: 0,
            page: page,
            limit: limit,
            has_more: false,
          },
          error: null,
        });
      }

      if (locationProviderIds && locationProviderIds.length > 0) {
        query = query.in("id", locationProviderIds);
      }
    }

    if (filters.rating_min) {
      query = query.gte("rating_average", filters.rating_min);
    }

    // Apply sorting
    switch (filters.sort_by) {
      case "price_low":
        // Note: starting_price doesn't exist, would need to calculate from offerings
        // For now, sort by rating as fallback
        query = query.order("rating_average", { ascending: true });
        break;
      case "price_high":
        // Note: starting_price doesn't exist, would need to calculate from offerings
        // For now, sort by rating as fallback
        query = query.order("rating_average", { ascending: false });
        break;
      case "rating":
        query = query.order("rating_average", { ascending: false });
        break;
      case "relevance":
      default:
        query = query.order("is_featured", { ascending: false }).order("rating_average", { ascending: false });
        break;
    }

    // Apply pagination
    query = query.range(offset, offset + limit - 1);

    const { data: providers, error, count } = await query;

    if (error) {
      console.error("Error searching providers:", error);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to search providers",
            code: "SEARCH_ERROR",
          },
        },
        { status: 500 }
      );
    }

    console.log(`Found ${providers?.length || 0} providers (total: ${count || 0})`);

    if (!providers || providers.length === 0) {
      return NextResponse.json({
        data: {
          providers: [],
          services: [],
          total: count || 0,
          page: page,
          limit: limit,
          has_more: false,
        },
        error: null,
      });
    }

    // Get provider IDs to fetch additional data
    const providerIds = providers.map((p: any) => p.id);

    // Fetch locations for all providers
    const { data: locations } = await supabase
      .from("provider_locations")
      .select("provider_id, city, country, is_primary")
      .in("provider_id", providerIds)
      .eq("is_active", true)
      .order("is_primary", { ascending: false }); // Primary location first

    // Create a map of provider_id -> location (prefer primary)
    const locationMap = new Map<string, { city: string; country: string }>();
    if (locations) {
      locations.forEach((loc: any) => {
        if (!locationMap.has(loc.provider_id)) {
          locationMap.set(loc.provider_id, {
            city: loc.city,
            country: loc.country,
          });
        }
      });
    }

    // Fetch minimum prices from offerings for each provider
    const { data: offerings } = await supabase
      .from("offerings")
      .select("provider_id, price, currency")
      .in("provider_id", providerIds)
      .eq("is_active", true);

    // Create a map of provider_id -> minimum price
    const priceMap = new Map<string, { price: number; currency: string }>();
    if (offerings) {
      offerings.forEach((offering: any) => {
        const existing = priceMap.get(offering.provider_id);
        if (!existing || offering.price < existing.price) {
          priceMap.set(offering.provider_id, {
            price: offering.price,
            currency: offering.currency,
          });
        }
      });
    }

    // Transform providers to match PublicProviderCard type
    const transformedProviders = providers.map((provider: any) => {
      const location = locationMap.get(provider.id);
      const priceInfo = priceMap.get(provider.id);

      return {
        id: provider.id,
        slug: provider.slug,
        business_name: provider.business_name,
        business_type: provider.business_type,
        rating: provider.rating_average || 0,
        review_count: provider.review_count || 0,
        thumbnail_url: provider.thumbnail_url,
        avatar_url: provider.avatar_url ?? null,
        city: location?.city || "",
        country: location?.country || "",
        is_featured: provider.is_featured || false,
        is_verified: provider.is_verified || false,
        starting_price: priceInfo?.price,
        currency: priceInfo?.currency || provider.currency || "ZAR",
      };
    });

    // Sponsored slots: run auction and merge winners at top
    let finalProviders = transformedProviders;
    const sponsoredProviderIds = new Set<string>();
    try {
      const winners = await runAdsAuction({
        categorySlug: filters.category || undefined,
        maxSlots: 5,
        excludeProviderIds: [],
      });
      if (winners.length > 0) {
        const supabaseAdmin = getSupabaseAdmin();
        const winnerProviderIds = [...new Set(winners.map((w) => w.provider_id))];
        const winnerToCampaign = new Map(winners.map((w) => [w.provider_id, w.campaign_id]));
        const { data: sponsoredProviders } = await supabaseAdmin
          .from("providers")
          .select("id, slug, business_name, business_type, rating_average, review_count, thumbnail_url, avatar_url, is_featured, is_verified, currency")
          .in("id", winnerProviderIds)
          .eq("status", "active");
        const { data: sponsoredLocations } = await supabaseAdmin
          .from("provider_locations")
          .select("provider_id, city, country, is_primary")
          .in("provider_id", winnerProviderIds)
          .eq("is_active", true)
          .order("is_primary", { ascending: false });
        const { data: sponsoredOfferings } = await supabaseAdmin
          .from("offerings")
          .select("provider_id, price, currency")
          .in("provider_id", winnerProviderIds)
          .eq("is_active", true);
        const locMap = new Map<string, { city: string; country: string }>();
        (sponsoredLocations ?? []).forEach((loc: any) => {
          if (!locMap.has(loc.provider_id)) locMap.set(loc.provider_id, { city: loc.city || "", country: loc.country || "" });
        });
        const priceMapSponsored = new Map<string, { price: number; currency: string }>();
        (sponsoredOfferings ?? []).forEach((o: any) => {
          const ex = priceMapSponsored.get(o.provider_id);
          if (!ex || o.price < ex.price) priceMapSponsored.set(o.provider_id, { price: o.price, currency: o.currency || "ZAR" });
        });
        const sponsoredCards = (sponsoredProviders ?? []).map((p: any) => {
          sponsoredProviderIds.add(p.id);
          const loc = locMap.get(p.id);
          const priceInfo = priceMapSponsored.get(p.id);
          return {
            id: p.id,
            slug: p.slug,
            business_name: p.business_name,
            business_type: p.business_type || "salon",
            rating: p.rating_average || 0,
            review_count: p.review_count || 0,
            thumbnail_url: p.thumbnail_url,
            avatar_url: p.avatar_url ?? null,
            city: loc?.city ?? "",
            country: loc?.country ?? "",
            is_featured: p.is_featured ?? false,
            is_verified: p.is_verified ?? false,
            starting_price: priceInfo?.price,
            currency: priceInfo?.currency ?? p.currency ?? "ZAR",
            is_sponsored: true,
            campaign_id: winnerToCampaign.get(p.id) ?? null,
          };
        });
        // Order sponsored by auction order (winners order)
        const order = new Map(winners.map((w, i) => [w.provider_id, i]));
        sponsoredCards.sort((a, b) => (order.get(a.id) ?? 99) - (order.get(b.id) ?? 99));
        const organicOnly = transformedProviders.filter((p: any) => !sponsoredProviderIds.has(p.id));
        finalProviders = [...sponsoredCards, ...organicOnly];
        const idempotencyPrefix = `search:${Date.now()}:${filters.category ?? "all"}:${page}`;
        await recordAdImpressions(winners, idempotencyPrefix);
      }
    } catch (e) {
      console.warn("Ads auction failed, returning organic only:", e);
    }

    console.log(`Returning ${finalProviders.length} providers (${sponsoredProviderIds.size} sponsored)`);

    // Also search services/offerings
    let serviceResults: any[] = [];
    const searchQuery = searchParams.get('q') || searchParams.get('query');
    if (searchQuery) {
      const { data: offerings } = await supabase
        .from("offerings")
        .select("id, name, description, price, duration_minutes, type, provider_id, provider:providers(id, business_name, slug, avatar_url)")
        .eq("is_active", true)
        .eq("type", "service")
        .or(`name.ilike.%${searchQuery}%,description.ilike.%${searchQuery}%`)
        .limit(20);
      serviceResults = offerings || [];
    }
    const services: any[] = serviceResults;

    const result: SearchResult = {
      providers: finalProviders,
      services: services,
      total: count || 0,
      page: page,
      limit: limit,
      has_more: (count || 0) > offset + limit,
    };

    const response = NextResponse.json({
      data: result,
      error: null,
    });

    // Cache search results for 30 seconds
    response.headers.set('Cache-Control', 'public, s-maxage=30, stale-while-revalidate=60');

    return response;
  } catch (error) {
    console.error("Unexpected error in /api/public/search:", error);
    return NextResponse.json(
      {
        data: null,
        error: {
          message: "Failed to perform search",
          code: "INTERNAL_ERROR",
        },
      },
      { status: 500 }
    );
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseServer } from '@/lib/supabase/server';
import { successResponse, handleApiError } from '@/lib/supabase/api-helpers';
import { z } from 'zod';

const suggestionsSchema = z.object({
  q: z.string().min(1, 'Query is required').max(100, 'Query too long'),
  limit: z.number().int().min(1).max(20).optional().default(10),
});

/**
 * GET /api/public/search/suggestions
 * 
 * Get search suggestions based on query
 * Returns services, providers, and categories that match
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const query = searchParams.get('q') || '';
    const limit = parseInt(searchParams.get('limit') || '10', 10);

    const data = suggestionsSchema.parse({ q: query, limit });

    if (!data.q || data.q.trim().length < 1) {
      return successResponse({ suggestions: [] });
    }

    const supabase = await getSupabaseServer();
    const searchTerm = data.q.trim();

    // Search services - use separate queries for better compatibility
    const { data: servicesByName, error: servicesByNameError } = await supabase
      .from('services')
      .select('id, name, category_id, category:service_categories(name)')
      .ilike('name', `%${searchTerm}%`)
      .eq('is_active', true)
      .limit(Math.ceil(data.limit / 3));

    const { data: servicesByDesc, error: servicesByDescError } = await supabase
      .from('services')
      .select('id, name, category_id, category:service_categories(name)')
      .ilike('description', `%${searchTerm}%`)
      .eq('is_active', true)
      .limit(Math.ceil(data.limit / 3));

    // Combine and deduplicate results
    const serviceMap = new Map();
    (servicesByName || []).forEach((s: any) => serviceMap.set(s.id, s));
    (servicesByDesc || []).forEach((s: any) => {
      if (!serviceMap.has(s.id)) {
        serviceMap.set(s.id, s);
      }
    });
    const services = Array.from(serviceMap.values()).slice(0, Math.ceil(data.limit / 3));
    const servicesError = servicesByNameError || servicesByDescError;

    // Search providers
    // Use separate queries for better compatibility and to search description field
    const { data: providersByName, error: providersByNameError } = await supabase
      .from('providers')
      .select('id, business_name, description')
      .ilike('business_name', `%${searchTerm}%`)
      .eq('status', 'active')
      .limit(Math.ceil(data.limit / 3));

    // Only search description if it's not null/empty
    const { data: providersByDesc, error: providersByDescError } = await supabase
      .from('providers')
      .select('id, business_name, description')
      .not('description', 'is', null)
      .ilike('description', `%${searchTerm}%`)
      .eq('status', 'active')
      .limit(Math.ceil(data.limit / 3));

    // Combine and deduplicate results
    const providerMap = new Map();
    (providersByName || []).forEach((p: any) => providerMap.set(p.id, p));
    (providersByDesc || []).forEach((p: any) => {
      if (!providerMap.has(p.id)) {
        providerMap.set(p.id, p);
      }
    });
    const providers = Array.from(providerMap.values()).slice(0, Math.ceil(data.limit / 3));
    const providersError = providersByNameError || providersByDescError;

    // Search categories
    const { data: categories, error: categoriesError } = await supabase
      .from('service_categories')
      .select('id, name, slug')
      .ilike('name', `%${searchTerm}%`)
      .eq('is_active', true)
      .limit(Math.ceil(data.limit / 3));

    // Log errors with more detail
    if (servicesError) {
      console.error('Error fetching service suggestions:', servicesError);
      console.error('Service search term:', searchTerm);
    }
    if (providersError) {
      console.error('Error fetching provider suggestions:', providersError);
      console.error('Provider search term:', searchTerm);
      console.error('Providers by name:', providersByName?.length || 0);
      console.error('Providers by desc:', providersByDesc?.length || 0);
    }
    if (categoriesError) {
      console.error('Error fetching category suggestions:', categoriesError);
    }

    // Debug logging
    console.log(`[Search Suggestions] Query: "${searchTerm}", Found: ${services?.length || 0} services, ${providers?.length || 0} providers, ${categories?.length || 0} categories`);

    // Format suggestions
    const suggestions: Array<{
      type: 'service' | 'provider' | 'category';
      id: string;
      name: string;
      url: string;
      category?: string;
    }> = [];

    // Add service suggestions
    (services || []).forEach((service: any) => {
      suggestions.push({
        type: 'service',
        id: service.id,
        name: service.name,
        url: `/search?q=${encodeURIComponent(service.name)}&type=service`,
        category: service.category?.name,
      });
    });

    // Add provider suggestions
    (providers || []).forEach((provider: any) => {
      suggestions.push({
        type: 'provider',
        id: provider.id,
        name: provider.business_name || 'Unknown',
        url: `/search?q=${encodeURIComponent(provider.business_name)}&type=provider`,
      });
    });

    // Add category suggestions
    (categories || []).forEach((category: any) => {
      suggestions.push({
        type: 'category',
        id: category.id,
        name: category.name,
        url: `/category/${category.slug}`,
      });
    });

    // Sort by relevance (exact matches first, then partial matches)
    const queryLower = data.q.toLowerCase();
    suggestions.sort((a, b) => {
      const aExact = a.name.toLowerCase().startsWith(queryLower);
      const bExact = b.name.toLowerCase().startsWith(queryLower);
      if (aExact && !bExact) return -1;
      if (!aExact && bExact) return 1;
      return a.name.localeCompare(b.name);
    });

    // Limit results
    const limitedSuggestions = suggestions.slice(0, data.limit);

    return successResponse({
      suggestions: limitedSuggestions,
      query: data.q,
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return handleApiError(
        new Error(error.issues.map(e => e.message).join(', ')),
        'Validation failed',
        'VALIDATION_ERROR',
        400
      );
    }
    return handleApiError(error, 'Failed to fetch search suggestions');
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse, handleApiError } from "@/lib/supabase/api-helpers";

interface PlatformBranding {
  site_name: string;
  logo_url: string;
  favicon_url: string;
  primary_color: string;
  secondary_color: string;
}

/**
 * GET /api/public/settings/branding
 * 
 * Get platform branding settings (public endpoint, no auth required)
 */
export async function GET(_request: NextRequest) {
  try {
    const supabase = await getSupabaseServer();

    // Default branding values
    const defaultBranding: PlatformBranding = {
      site_name: "Beautonomi",
      logo_url: "/images/logo.svg",
      favicon_url: "/favicon.ico",
      primary_color: "#FF0077",
      secondary_color: "#D60565",
    };

    // If Supabase client is null, return defaults
    if (!supabase) {
      return successResponse(defaultBranding);
    }

    // Try to get from database (table might not exist yet)
    try {
      const { data: settings, error: settingsError } = await (supabase
        .from("platform_settings") as any)
        .select("settings")
        .single();

      // If table doesn't exist or no settings found, return defaults
      if (settingsError || !settings) {
        return successResponse(defaultBranding);
      }

      if (settings && (settings as any).settings && (settings as any).settings.branding) {
        const raw = (settings as any).settings.branding as Record<string, any>;
        const safe: PlatformBranding = {
          site_name: typeof raw.site_name === "string" ? raw.site_name : defaultBranding.site_name,
          logo_url: typeof raw.logo_url === "string" ? raw.logo_url : defaultBranding.logo_url,
          favicon_url: typeof raw.favicon_url === "string" ? raw.favicon_url : defaultBranding.favicon_url,
          primary_color: typeof raw.primary_color === "string" ? raw.primary_color : defaultBranding.primary_color,
          secondary_color: typeof raw.secondary_color === "string" ? raw.secondary_color : defaultBranding.secondary_color,
        };
        return successResponse(safe);
      }
    } catch (error) {
      // Table might not exist, return default settings
      console.warn("Platform settings table may not exist, using defaults:", error);
    }

    return successResponse(defaultBranding);
  } catch (error) {
    return handleApiError(error, "Failed to load branding settings");
  }
}

