            currency: 'ZAR',
            billing_period: 'monthly',
            features: [
              'Up to 50 bookings per month',
              'Basic analytics',
              'Email support',
              'Mobile app access',
            ],
          },
          {
            id: 'professional',
            name: 'Professional',
            price: 199,
            currency: 'ZAR',
            billing_period: 'monthly',
            features: [
              'Unlimited bookings',
              'Advanced analytics',
              'Priority support',
              'Custom branding',
              'API access',
            ],
            is_popular: true,
          },
          {
            id: 'enterprise',
            name: 'Enterprise',
            price: 399,
            currency: 'ZAR',
            billing_period: 'monthly',
