    }

    // Shape expected by provider subscription UI: flatten into monthly/yearly options.
    const out = (plans || []).flatMap((p: any) => {
      const features =
        Array.isArray(p.features) ? p.features : (p.features ? Object.values(p.features) : []);
      const options: any[] = [];
      if (p.price_monthly != null) {
        options.push({
          id: `${p.id}:monthly`,
          plan_id: p.id,
          name: p.name,
          price: Number(p.price_monthly),
          currency: p.currency || "ZAR",
          billing_period: "monthly",
          features,
          is_popular: (p as any).is_popular || false,
        });
      }
      if (p.price_yearly != null) {
        options.push({
          id: `${p.id}:yearly`,
          plan_id: p.id,
          name: p.name,
          price: Number(p.price_yearly),
          currency: p.currency || "ZAR",
          billing_period: "yearly",
          features,
          is_popular: (p as any).is_popular || false,
        });
      }
      return options;
    });

    return NextResponse.json({ data: out });
  } catch (error) {
    console.error('Error in subscription-plans GET route:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { unstable_cache } from "next/cache";

/**
 * GET /api/public/third-party-config
 * 
 * Public endpoint to get third-party service configuration (safe keys only)
 * This is cached and doesn't require authentication
 */
export const GET = unstable_cache(
  async (request: Request) => {
    try {
      const { searchParams } = new URL(request.url);
      const service = searchParams.get("service"); // onesignal, mapbox, amplitude, google

      const supabase = await getSupabaseServer();
      const { data: settings } = await (supabase
        .from("platform_settings") as any)
        .select("settings")
        .single();

      if (settings && (settings as any).settings) {
        const config: any = {};

        // OneSignal - return app_id only (safe to expose)
        if (!service || service === "onesignal") {
          if ((settings as any).settings.onesignal?.enabled) {
            config.onesignal = {
              app_id: (settings as any).settings.onesignal.app_id,
              safari_web_id: (settings as any).settings.onesignal.safari_web_id,
              enabled: true,
            };
          }
        }

        // Mapbox - return public token only
        if (!service || service === "mapbox") {
          if ((settings as any).settings.mapbox?.enabled) {
            config.mapbox = {
              public_token: (settings as any).settings.mapbox.public_token,
              enabled: true,
            };
          }
        }

        // Amplitude - return API key only (safe to expose)
        if (!service || service === "amplitude") {
          if ((settings as any).settings.amplitude?.enabled) {
            config.amplitude = {
              api_key: (settings as any).settings.amplitude.api_key,
              enabled: true,
            };
          }
        }

        // Google - return public keys only
        if (!service || service === "google") {
          if ((settings as any).settings.google?.enabled) {
            config.google = {
              maps_api_key: (settings as any).settings.google.maps_api_key,
              places_api_key: (settings as any).settings.google.places_api_key,
              analytics_id: (settings as any).settings.google.analytics_id,
              enabled: true,
            };
          }
        }

        return NextResponse.json({
          data: service ? config[service] : config,
          error: null,
        });
      }

      // Fallback
      return NextResponse.json({
        data: {},
        error: null,
      });
    } catch (error) {
      console.error("Error fetching third-party config:", error);
      return NextResponse.json(
        {
          data: null,
          error: {
            message: "Failed to fetch third-party configuration",
            code: "INTERNAL_ERROR",
          },
        },
        { status: 500 }
      );
    }
  },
  ["third-party-config-public"],
  {
    revalidate: 3600, // Revalidate every hour
    tags: ["platform-settings"],
  }
);

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireAuthInApi, successResponse, notFoundResponse, handleApiError, errorResponse } from "@/lib/supabase/api-helpers";
import { z } from "zod";

const updateRecurringSchema = z.object({
  is_active: z.boolean().optional(),
  end_date: z.string().date().optional().nullable(),
});

/**
 * PATCH /api/recurring-bookings/[id]
 * 
 * Update a recurring booking (pause/resume/cancel)
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireAuthInApi(request);
    const supabase = await getSupabaseServer();
    const { id } = await params;
    const body = await request.json();

    const validated = updateRecurringSchema.parse(body);

    // Verify ownership
    const { data: existing } = await supabase
      .from("recurring_appointments")
      .select("id")
      .eq("id", id)
      .eq("customer_id", user.id)
      .single();

    if (!existing) {
      return notFoundResponse("Recurring booking not found");
    }

    // Update
    const updateData: any = {};
    if (validated.is_active !== undefined) updateData.is_active = validated.is_active;
    if (validated.end_date !== undefined) updateData.end_date = validated.end_date;

    const { data: updated, error } = await supabase
      .from("recurring_appointments")
      .update(updateData)
      .eq("id", id)
      .select()
      .single();

    if (error) {
      throw error;
    }

    return successResponse({
      recurring: updated,
      message: "Recurring booking updated successfully",
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return errorResponse(
        error.issues.map((e) => e.message).join(", "),
        "VALIDATION_ERROR",
        400
      );
    }
    return handleApiError(error, "Failed to update recurring booking");
  }
}

/**
 * DELETE /api/recurring-bookings/[id]
 * 
 * Cancel a recurring booking
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireAuthInApi(request);
    const supabase = await getSupabaseServer();
    const { id } = await params;

    // Verify ownership
    const { data: existing } = await supabase
      .from("recurring_appointments")
      .select("id")
      .eq("id", id)
      .eq("customer_id", user.id)
      .single();

    if (!existing) {
      return notFoundResponse("Recurring booking not found");
    }

    // Deactivate instead of delete
    const { error } = await supabase
      .from("recurring_appointments")
      .update({ is_active: false, end_date: new Date().toISOString().split("T")[0] })
      .eq("id", id);

    if (error) {
      throw error;
    }

    return successResponse({
      message: "Recurring booking cancelled successfully",
    });
  } catch (error) {
    return handleApiError(error, "Failed to cancel recurring booking");
  }
}

import { NextRequest } from 'next/server';
import { getSupabaseServer } from '@/lib/supabase/server';
import { requireRoleInApi, successResponse, handleApiError, notFoundResponse, requireAuthInApi } from '@/lib/supabase/api-helpers';

/**
 * PATCH /api/reviews/[id]
 * 
 * Update a review - allows providers to rate customers
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { user } = await requireAuthInApi(request);
    const supabase = await getSupabaseServer();
    const { id: reviewId } = await params;
    const body = await request.json();

    // Verify review exists
    const { data: review, error: reviewError } = await supabase
      .from('reviews')
      .select('id, provider_id, booking_id, customer_rating')
      .eq('id', reviewId)
      .single();

    if (reviewError || !review) {
      return notFoundResponse('Review not found');
    }

    // Check if user is a provider and owns this review
    const { data: provider } = await supabase
      .from('providers')
      .select('id, user_id')
      .eq('id', review.provider_id)
      .eq('user_id', user.id)
      .single();

    if (!provider) {
      return handleApiError(new Error('Unauthorized'), 'You can only rate customers for your own bookings');
    }

    // Verify booking is completed
    const { data: booking } = await supabase
      .from('bookings')
      .select('id, status')
      .eq('id', review.booking_id)
      .single();

    if (!booking || booking.status !== 'completed') {
      return handleApiError(new Error('Invalid booking status'), 'You can only rate customers for completed bookings');
    }

    // Prepare update data
    const updateData: any = {};
    
    if (body.customer_rating !== undefined) {
      if (body.customer_rating < 1 || body.customer_rating > 5) {
        return handleApiError(new Error('Invalid rating'), 'Rating must be between 1 and 5');
      }
      updateData.customer_rating = body.customer_rating;
      updateData.customer_rating_created_at = new Date().toISOString();
    }

    if (body.customer_comment !== undefined) {
      updateData.customer_comment = body.customer_comment || null;
    }

    // Update review
    const { data: updatedReview, error: updateError } = await supabase
      .from('reviews')
      .update(updateData)
      .eq('id', reviewId)
      .select()
      .single();

    if (updateError) {
      throw updateError;
    }

    return successResponse(updatedReview);
  } catch (error) {
    return handleApiError(error, 'Failed to update review');
  }
}

/**
 * DELETE /api/reviews/[id]
 * 
 * Delete a review (superadmin only)
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    await requireRoleInApi(['superadmin']);
    const supabase = await getSupabaseServer();
    const { id: reviewId } = await params;

    // Verify review exists
    const { data: review } = await supabase
      .from('reviews')
      .select('id')
      .eq('id', reviewId)
      .single();

    if (!review) {
      return notFoundResponse('Review not found');
    }

    const { error } = await supabase
      .from('reviews')
      .delete()
      .eq('id', reviewId);

    if (error) {
      throw error;
    }

    return successResponse({ success: true });
  } catch (error) {
    return handleApiError(error, 'Failed to delete review');
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getSupabaseServer } from '@/lib/supabase/server';
import { fuzzySearch } from '@/lib/utils/fuzzy-search';

export async function GET(request: NextRequest) {
  try {
    const supabase = await getSupabaseServer();
    const searchParams = request.nextUrl.searchParams;
    const query = searchParams.get('q') || '';
    const limit = parseInt(searchParams.get('limit') || '20');
    const type = searchParams.get('type') || 'all'; // 'providers', 'services', 'all'

    if (!query || query.trim().length < 2) {
      return NextResponse.json({
        data: {
          providers: [],
          services: [],
        },
      });
    }

    const results: {
      providers: any[];
      services: any[];
    } = {
      providers: [],
      services: [],
    };

    // Search providers
    if (type === 'all' || type === 'providers') {
      const { data: providers, error: providersError } = await supabase
        .from('providers')
        .select(`
          id,
          business_name,
          slug,
          description,
          city,
          state,
          country,
          average_rating,
          total_reviews,
          profile_image_url
        `)
        .eq('is_active', true)
        .eq('is_approved', true)
        .limit(100);

      if (!providersError && providers) {
        const fuzzyProviders = fuzzySearch(
          providers,
          query,
          (provider) => [
            provider.business_name || '',
            provider.description || '',
            provider.city || '',
            provider.state || '',
            provider.country || '',
          ],
          0.4
        );

        results.providers = fuzzyProviders.slice(0, limit).map(p => ({
          id: p.id,
          name: p.business_name,
          slug: p.slug,
          description: p.description,
          location: [p.city, p.state, p.country].filter(Boolean).join(', '),
          rating: p.average_rating,
          reviews: p.total_reviews,
          image: p.profile_image_url,
        }));
      }
    }

    // Search services
    if (type === 'all' || type === 'services') {
      const { data: services, error: servicesError } = await supabase
        .from('services')
        .select(`
          id,
          name,
          description,
          price,
          duration_minutes,
          category_id,
          provider_id,
          providers!inner(business_name, slug)
        `)
        .eq('is_active', true)
        .limit(100);

      if (!servicesError && services) {
        const fuzzyServices = fuzzySearch(
          services,
          query,
          (service) => [
            service.name || '',
            service.description || '',
            (service.providers as any)?.business_name || '',
          ],
          0.4
        );

        results.services = fuzzyServices.slice(0, limit).map(s => ({
          id: s.id,
          name: s.name,
          description: s.description,
          price: s.price,
          duration: s.duration_minutes,
          provider: {
            id: s.provider_id,
            name: (s.providers as any)?.business_name,
            slug: (s.providers as any)?.slug,
          },
        }));
      }
    }

    return NextResponse.json({
      data: results,
    });
  } catch (error) {
    console.error('Error in fuzzy search route:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { successResponse } from "@/lib/supabase/api-helpers";

export const dynamic = "force-dynamic";
// Cache services for 2 minutes (they don't change often during booking)
export const revalidate = 120;

/**
 * GET /api/services
 * 
 * Get services filtered by type (salon or mobile)
 * Query params: type, providerSlug
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const type = searchParams.get("type"); // "salon" or "mobile"
    const providerSlug = searchParams.get("providerSlug");
    const serviceIdFromBooking = searchParams.get("serviceId"); // New: serviceId from booking flow

    if (!providerSlug && !serviceIdFromBooking) {
      console.warn("[Services API] No providerSlug or serviceId provided, returning empty array.");
      return successResponse([]);
    }

    // Use server client (same as partner profile endpoint which works)
    // This ensures consistent behavior with the partner profile page
    const supabase = await getSupabaseServer();
    if (!supabase) {
      console.error("[Services API] Database connection not available");
      const response = successResponse([]);
      response.headers.set('Cache-Control', 'public, s-maxage=10, stale-while-revalidate=30');
      return response;
    }

    // Log some sample providers to help debug slug issues
    const { data: sampleProviders, error: sampleError } = await supabase
      .from("providers")
      .select("id, business_name, slug, status")
      .limit(5);
    if (sampleError) {
      console.error("[Services API] Error fetching sample providers:", sampleError);
    } else {
      console.log("[Services API] Sample active providers:", sampleProviders?.filter(p => p.status === 'active').map(p => ({ id: p.id, slug: p.slug, status: p.status })));
    }

    console.log(`[Services API] Searching for providerSlug: ${providerSlug}, or serviceId: ${serviceIdFromBooking}`);

    let provider;

    // First, try to find provider via serviceId if provided (most reliable)
    if (serviceIdFromBooking) {
      console.log(`[Services API] Attempting to find provider via serviceId: ${serviceIdFromBooking}`);
      const { data: serviceData, error: serviceError } = await supabase
        .from("offerings")
        .select("provider_id")
        .eq("id", serviceIdFromBooking)
        .single();

      if (serviceError) {
        console.error(`[Services API] Error fetching service by ID ${serviceIdFromBooking}:`, serviceError);
      } else if (serviceData && serviceData.provider_id) {
        console.log(`[Services API] Found provider ID ${serviceData.provider_id} via service ID.`);
        // Verify the provider exists (don't filter by status - we found it via serviceId)
        const { data: providerData, error: providerError } = await supabase
          .from("providers")
          .select("id, slug, status")
          .eq("id", serviceData.provider_id)
          .single();

        if (providerError) {
          console.error(`[Services API] Error verifying provider ${serviceData.provider_id}:`, providerError);
        } else if (providerData) {
          provider = providerData;
          console.log(`[Services API] Verified provider: ${providerData.id}, slug: ${providerData.slug}, status: ${providerData.status}`);
        } else {
          console.error(`[Services API] Provider ${serviceData.provider_id} not found in providers table`);
        }
      } else {
        console.error(`[Services API] Service ${serviceIdFromBooking} found but has no provider_id`);
      }
    }

    // If provider not found via serviceId, try slug-based lookup
    // Match the exact logic from /api/public/providers/[slug]/offerings which works
    if (!provider && providerSlug) {
      try {
        const decodedSlug = decodeURIComponent(providerSlug);
        console.log(`[Services API] Looking for provider with slug: "${decodedSlug}" (original: "${providerSlug}")`);

        // First try: exact match with decoded slug and active status (matches partner profile endpoint)
        const { data: providerData, error: decodeError } = await supabase
          .from("providers")
          .select("id, slug, status")
          .eq("slug", decodedSlug)
          .eq("status", "active")
          .single();

        console.log(`[Services API] First lookup result:`, { providerData, error: decodeError });

        if (providerData && !decodeError) {
          provider = providerData;
        } else {
          // Try with original slug (no decoding)
          const { data: providerData2, error: originalError } = await supabase
            .from("providers")
            .select("id, slug, status")
            .eq("slug", providerSlug)
            .eq("status", "active")
            .single();

          console.log(`[Services API] Second lookup result:`, { providerData: providerData2, error: originalError });

          if (providerData2 && !originalError) {
            provider = providerData2;
          } else {
            // Last resort: try without status filter (in case provider exists but status is different)
            // This matches the fallback in partner profile endpoint
            const { data: providerData3 } = await supabase
              .from("providers")
              .select("id, slug, status")
              .eq("slug", decodedSlug)
              .limit(1)
              .maybeSingle();

            if (!providerData3) {
              // Try original slug without status
              const { data: providerData4 } = await supabase
                .from("providers")
                .select("id, slug, status")
                .eq("slug", providerSlug)
                .limit(1)
                .maybeSingle();

              if (providerData4) {
                console.log(`[Services API] Found provider without status filter: ${providerData4.slug}, status: ${providerData4.status}`);
                provider = providerData4;
              }
            } else {
              console.log(`[Services API] Found provider without status filter: ${providerData3.slug}, status: ${providerData3.status}`);
              provider = providerData3;
            }
          }
        }
      } catch (error) {
        console.error(`[Services API] Error fetching provider by slug:`, error);
      }
    }

    if (!provider || !provider.id) {
      console.error(`[Services API] Final: Provider not found for slug: ${providerSlug} or serviceId: ${serviceIdFromBooking}.`);

      // Last resort: if we have a serviceId, try to get provider directly from the service
      if (serviceIdFromBooking) {
        console.log(`[Services API] Last resort: Fetching service ${serviceIdFromBooking} to get provider...`);
        const { data: lastResortService, error: lastResortError } = await supabase
          .from("offerings")
          .select("provider_id, id, title, description, duration_minutes, price, currency, supports_at_home, supports_at_salon, provider_category_id, parent_service_id, service_type, is_active, display_order, online_booking_enabled")
          .eq("id", serviceIdFromBooking)
          .single();

        if (lastResortService && !lastResortError && lastResortService.provider_id) {
          console.log(`[Services API] Found service directly, provider_id: ${lastResortService.provider_id}`);
          // Use this service as the only result
          if (lastResortService.is_active && lastResortService.online_booking_enabled !== false) {
            const services = [{
              id: lastResortService.id,
              title: lastResortService.title,
              description: lastResortService.description,
              duration: lastResortService.duration_minutes,
              price: parseFloat(lastResortService.price || 0),
              currency: lastResortService.currency || "ZAR",
              category: "Other", // Will be resolved from provider_category_id later
              hasAddons: false,
              hasVariants: false,
            }];
            console.log(`[Services API] Returning direct service:`, services[0]);
            const response = successResponse(services);
            response.headers.set('Cache-Control', 'public, s-maxage=120, stale-while-revalidate=300');
            return response;
          }
        }
      }

      const response = successResponse([]);
      response.headers.set('Cache-Control', 'public, s-maxage=60, stale-while-revalidate=120');
      return response;
    }

    console.log(`[Services API] Final: Found provider ID: ${provider.id} for slug: ${providerSlug}, type filter: ${type}`);

    // If we have a specific serviceId, fetch it first to ensure it's included
    let requestedService: any = null;
    if (serviceIdFromBooking) {
      console.log(`[Services API] Fetching specific service ${serviceIdFromBooking}...`);
      const { data: directService, error: directError } = await supabase
        .from("offerings")
        .select(`
          id,
          title,
          description,
          duration_minutes,
          price,
          currency,
          supports_at_home,
          supports_at_salon,
          provider_category_id,
          parent_service_id,
          service_type,
          is_active,
          display_order,
          online_booking_enabled
        `)
        .eq("id", serviceIdFromBooking)
        .eq("provider_id", provider.id)
        .single();

      if (directError) {
        console.error(`[Services API] Error fetching specific service:`, directError);
      } else if (directService) {
        requestedService = directService;
        console.log(`[Services API] Found requested service:`, {
          id: directService.id,
          title: directService.title,
          service_type: directService.service_type,
          is_active: directService.is_active,
          online_booking_enabled: directService.online_booking_enabled
        });
      } else {
        console.warn(`[Services API] Requested service ${serviceIdFromBooking} not found`);
      }
    }

    // First, let's check ALL offerings for this provider (without filters) for debugging
    const { data: allOfferingsDebug, error: _debugError } = await supabase
      .from("offerings")
      .select("id, title, service_type, is_active, provider_id")
      .eq("provider_id", provider.id);

    console.log(`[Services API] DEBUG: Total offerings for provider ${provider.id} (no filters): ${allOfferingsDebug?.length || 0}`);
    if (allOfferingsDebug && allOfferingsDebug.length > 0) {
      console.log(`[Services API] DEBUG: Sample offerings:`, allOfferingsDebug.slice(0, 5).map((o: any) => ({
        id: o.id,
        title: o.title,
        service_type: o.service_type,
        is_active: o.is_active
      })));
    }

    // Query offerings directly - we know the service exists here
    // Filter out variants (only show base services) unless a specific serviceId is requested
    const { data: offeringsData, error } = await supabase
      .from("offerings")
      .select(`
        id,
        title,
        description,
        duration_minutes,
        price,
        currency,
        supports_at_home,
        supports_at_salon,
        provider_category_id,
        parent_service_id,
        service_type,
        is_active,
        display_order,
        online_booking_enabled
      `)
      .eq("provider_id", provider.id)
      .eq("is_active", true)
      .order("display_order", { ascending: true, nullsFirst: false });

    let offerings = offeringsData;

    console.log(`[Services API] Raw query for provider ${provider.id}: ${offerings?.length || 0} offerings`);
    if (error) {
      console.error("[Services API] Error fetching offerings:", error);
      console.error("[Services API] Error details:", JSON.stringify(error, null, 2));
    } else if (offerings && offerings.length > 0) {
      console.log(`[Services API] Found offerings:`, offerings.map((o: any) => ({
        id: o.id,
        title: o.title,
        service_type: o.service_type,
        online_booking_enabled: o.online_booking_enabled,
        is_active: o.is_active
      })));
    } else {
      console.warn(`[Services API] No offerings found for provider ${provider.id} with is_active=true`);
      // If we have a requested service, use it even if the query returned nothing
      if (requestedService && requestedService.is_active) {
        console.log(`[Services API] Using requested service since query returned empty`);
        offerings = [requestedService];
      }
    }

    if (error) {
      console.error("[Services API] Error fetching offerings:", error);
      // Even if there's an error, try to return the requested service if we have it
      if (requestedService && requestedService.is_active) {
        console.log(`[Services API] Error occurred but returning requested service anyway`);
        offerings = [requestedService];
      } else {
        console.warn("[Services API] Returning empty services array due to offerings fetch error.");
        const response = successResponse([]);
        response.headers.set('Cache-Control', 'public, s-maxage=10, stale-while-revalidate=30');
        return response;
      }
    }

    // Ensure requested service is in the offerings array if it exists
    if (requestedService && requestedService.is_active) {
      const alreadyIncluded = offerings?.some((o: any) => o.id === requestedService.id);
      if (!alreadyIncluded) {
        console.log(`[Services API] Adding requested service to offerings array`);
        offerings = [requestedService, ...(offerings || [])];
      }
    }

    console.log(`[Services API] Query returned ${offerings?.length || 0} offerings before JS filtering.`);
    if (offerings && offerings.length > 0) {
      console.log(`[Services API] Sample raw offerings:`, offerings.slice(0, 3).map((o: any) => ({
        id: o.id,
        title: o.title,
        service_type: o.service_type,
        is_active: o.is_active
      })));
    }

    // Filter offerings: exclude variants (unless specifically requested), and filter by online_booking_enabled
    let filteredOfferings = (offerings || []).filter((o: any) => {
      // Always include the service that was clicked (if serviceId provided) - even if it's a variant
      if (serviceIdFromBooking && o.id === serviceIdFromBooking) {
        console.log(`[Services API] Including requested service ${serviceIdFromBooking} (type: ${o.service_type})`);
        return true;
      }

      // Exclude variants (service_type = "variant")
      if (o.service_type === "variant") {
        return false;
      }

      // Include if online_booking_enabled is true or not set (null/undefined)
      // Only exclude if explicitly false
      if (o.online_booking_enabled === false) {
        return false;
      }

      return true;
    });

    console.log(`[Services API] After filtering: ${filteredOfferings.length} offerings`);
    if (filteredOfferings.length > 0) {
      console.log(`[Services API] Sample filtered offerings:`, filteredOfferings.slice(0, 3).map((o: any) => ({
        id: o.id,
        title: o.title,
        service_type: o.service_type,
        online_booking_enabled: o.online_booking_enabled,
        is_active: o.is_active
      })));
    }

    // If we have a serviceId from booking but it's not in the filtered results, fetch it directly
    if (serviceIdFromBooking && !filteredOfferings.find((o: any) => o.id === serviceIdFromBooking)) {
      console.log(`[Services API] Requested service ${serviceIdFromBooking} not in filtered results, fetching directly...`);
      const { data: directService, error: directError } = await supabase
        .from("offerings")
        .select(`
          id,
          title,
          description,
          duration_minutes,
          price,
          currency,
          supports_at_home,
          supports_at_salon,
          provider_category_id,
          parent_service_id,
          service_type,
          is_active,
          display_order,
          online_booking_enabled
        `)
        .eq("id", serviceIdFromBooking)
        .eq("provider_id", provider.id)
        .single();

      if (directError) {
        console.error(`[Services API] Error fetching direct service:`, directError);
      } else if (directService) {
        console.log(`[Services API] Found direct service:`, {
          id: directService.id,
          title: directService.title,
          service_type: directService.service_type,
          is_active: directService.is_active,
          online_booking_enabled: directService.online_booking_enabled
        });
        // Only add if it's active (we'll check online_booking_enabled in the filter)
        if (directService.is_active) {
          filteredOfferings = [directService, ...filteredOfferings];
          console.log(`[Services API] Added requested service ${serviceIdFromBooking} to results.`);
        }
      }
    }

    if (filteredOfferings.length === 0) {
      console.log(`[Services API] No active, non-variant offerings found for provider ${provider.id}.`);
      // If we have a serviceId, try to fetch that specific service even if it's inactive or a variant
      if (serviceIdFromBooking) {
        console.log(`[Services API] Attempting to fetch specific service ${serviceIdFromBooking} regardless of filters...`);
        const { data: specificService, error: specificError } = await supabase
          .from("offerings")
          .select(`
            id,
            title,
            description,
            duration_minutes,
            price,
            currency,
            supports_at_home,
            supports_at_salon,
            provider_category_id,
            parent_service_id,
            service_type,
            is_active,
            display_order,
            online_booking_enabled
          `)
          .eq("id", serviceIdFromBooking)
          .eq("provider_id", provider.id)
          .single();

        if (specificService && !specificError) {
          console.log(`[Services API] Found specific service: ${specificService.title} (type: ${specificService.service_type})`);
          // Use this service as the only offering
          const services = [{
            id: specificService.id,
            title: specificService.title,
            description: specificService.description,
            duration: specificService.duration_minutes,
            price: parseFloat(specificService.price || 0),
            currency: specificService.currency || "ZAR",
            category: "Other", // Will be resolved from provider_category_id later
            hasAddons: false,
            hasVariants: false,
          }];
          const response = successResponse(services);
          response.headers.set('Cache-Control', 'public, s-maxage=120, stale-while-revalidate=300');
          return response;
        }
      }
      const response = successResponse([]);
      response.headers.set('Cache-Control', 'public, s-maxage=120, stale-while-revalidate=300');
      return response;
    }

    // Filter by type - if type is "mobile", only show mobile services
    // If type is "salon" or not specified, show all services (both salon and mobile)
    let typeFilteredOfferings = filteredOfferings;
    if (type === "mobile") {
      typeFilteredOfferings = filteredOfferings.filter((o: any) => o.supports_at_home === true);
      console.log(`[Services API] After mobile filter: ${typeFilteredOfferings.length} offerings`);
    }

    if (error) {
      console.error("[Services API] Error fetching offerings:", error);
      // Return empty array instead of throwing to prevent booking flow from breaking
      console.warn("[Services API] Returning empty services array due to error");
      const response = successResponse([]);
      response.headers.set('Cache-Control', 'public, s-maxage=10, stale-while-revalidate=30');
      return response;
    }

    // If no offerings found after type filtering, return empty array early
    // But only if we don't have a requested service that should be included
    if ((!typeFilteredOfferings || typeFilteredOfferings.length === 0) && !requestedService) {
      console.log(`[Services API] No offerings found for provider ${provider.id} after type filtering`);
      const response = successResponse([]);
      response.headers.set('Cache-Control', 'public, s-maxage=120, stale-while-revalidate=300');
      return response;
    }

    // Fetch provider categories and check for variants/addons in parallel
    const providerCategoryIds = Array.from(
      new Set(typeFilteredOfferings.map((o: any) => o.provider_category_id).filter(Boolean))
    );
    const serviceIds = typeFilteredOfferings.map((o: any) => o.id);

    // Run parallel queries for better performance
    const [categoryResult, variantResult, addonResult] = await Promise.allSettled([
      // Fetch categories
      providerCategoryIds.length > 0 ? supabase
        .from("provider_categories")
        .select("id, name")
        .in("id", providerCategoryIds) : Promise.resolve({ data: null, error: null }),

      // Check for variants
      serviceIds.length > 0 ? supabase
        .from("offerings")
        .select("parent_service_id")
        .in("parent_service_id", serviceIds)
        .eq("service_type", "variant")
        .eq("is_active", true) : Promise.resolve({ data: null, error: null }),

      // Check for addons
      serviceIds.length > 0 ? supabase
        .from("offerings")
        .select("applicable_service_ids")
        .eq("service_type", "addon")
        .eq("is_active", true)
        .eq("online_booking_enabled", true)
        .eq("provider_id", provider.id) : Promise.resolve({ data: null, error: null })
    ]);

    // Extract category data
    let categoryMap: Record<string, string> = {};
    if (categoryResult.status === "fulfilled" && categoryResult.value.data) {
      categoryMap = (categoryResult.value.data || []).reduce((acc: Record<string, string>, cat: any) => {
        acc[cat.id] = cat.name;
        return acc;
      }, {});
    }

    // Extract variant data
    const servicesWithVariants = new Set<string>();
    if (variantResult.status === "fulfilled" && variantResult.value.data) {
      (variantResult.value.data || []).forEach((v: any) => {
        if (v.parent_service_id) {
          servicesWithVariants.add(v.parent_service_id);
        }
      });
    }

    // Extract addon data
    const servicesWithAddons = new Set<string>();
    if (addonResult.status === "fulfilled" && addonResult.value.data) {
      (addonResult.value.data || []).forEach((addon: any) => {
        if (!addon.applicable_service_ids || addon.applicable_service_ids.length === 0) {
          // Addon applies to all services
          serviceIds.forEach((id: string) => servicesWithAddons.add(id));
        } else {
          // Addon applies to specific services
          addon.applicable_service_ids.forEach((id: string) => servicesWithAddons.add(id));
        }
      });
    }

    // Transform to service format
    const services = typeFilteredOfferings.map((offering: any) => ({
      id: offering.id,
      title: offering.title,
      description: offering.description,
      duration: offering.duration_minutes,
      price: parseFloat(offering.price || 0),
      currency: offering.currency || "ZAR",
      category: categoryMap[offering.provider_category_id] || "Other",
      hasAddons: servicesWithAddons.has(offering.id),
      hasVariants: servicesWithVariants.has(offering.id),
    }));

    console.log(`[Services API] Final services count after transformation: ${services.length}`);

    const response = successResponse(services);

    // Add caching headers
    response.headers.set('Cache-Control', 'public, s-maxage=120, stale-while-revalidate=300');

    return response;
  } catch (error) {
    console.error("[Services API] Unexpected error:", error);
    // Return empty array instead of error to prevent booking flow from breaking
    // The frontend will show "No services available" message
    const response = successResponse([]);
    response.headers.set('Cache-Control', 'public, s-maxage=10, stale-while-revalidate=30');
    return response;
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase/server";
import { generateStaffCalendar } from "@/lib/ical/generator";

/**
 * GET /api/staff/[id]/calendar.ics
 * 
 * Generate iCal file for staff member's appointments
 * Public endpoint (no auth required) - uses staff ID as access token
 * Only includes appointments, not time blocks (per Mangomint requirements)
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id: staffId } = await params;
    const supabase = await getSupabaseServer();

    // Load staff member details
    const { data: staff, error: staffError } = await supabase
      .from('provider_staff')
      .select(`
        id,
        name,
        email,
        users!inner (
          email
        )
      `)
      .eq('id', staffId)
      .single();

    if (staffError || !staff) {
      return new Response('Staff member not found', { status: 404 });
    }

    // Load appointments for this staff member
    // Only include confirmed/upcoming appointments (not cancelled)
    const { data: appointments, error: appointmentsError } = await supabase
      .from('booking_services')
      .select(`
        id,
        scheduled_start_at,
        scheduled_end_at,
        duration_minutes,
        bookings!inner (
          id,
          booking_number,
          scheduled_at,
          status,
          guest_name,
          location_type,
          location_id,
          customers (
            name,
            email
          ),
          providers (
            name
          ),
          locations (
            name,
            address
          )
        ),
        offerings (
          title
        )
      `)
      .eq('staff_id', staffId)
      .gte('scheduled_start_at', new Date().toISOString()) // Only future appointments
      .neq('bookings.status', 'cancelled')
      .order('scheduled_start_at', { ascending: true });

    if (appointmentsError) {
      console.error('Error loading appointments:', appointmentsError);
      return new Response('Error loading appointments', { status: 500 });
    }

    // Transform to calendar events format
    const calendarAppointments = (appointments || []).map((apt: any) => {
      const booking = apt.bookings;
      const customer = booking?.customers;
      const provider = booking?.providers;
      const location = booking?.locations;

      return {
        id: apt.id,
        booking_number: booking?.booking_number || '',
        scheduled_at: apt.scheduled_start_at,
        duration_minutes: apt.duration_minutes,
        customer_name: booking?.guest_name || customer?.name,
        customer_email: customer?.email,
        service_title: apt.offerings?.title,
        location_name: location?.name,
        location_address: location?.address,
        provider_name: provider?.name,
        status: booking?.status || 'confirmed',
      };
    });

    // Generate iCal content
    const staffEmail = (staff.users as any)?.email || staff.email || 'staff@beautonomi.com';
    const staffName = staff.name || 'Staff Member';
    const icalContent = generateStaffCalendar(calendarAppointments, staffName, staffEmail);

    // Return as iCal file
    return new Response(icalContent, {
      headers: {
        'Content-Type': 'text/calendar; charset=utf-8',
        'Content-Disposition': `attachment; filename="beautonomi-calendar-${staffId}.ics"`,
      },
    });
  } catch (error) {
    console.error('Error generating iCal:', error);
    return new Response('Error generating calendar', { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import crypto from 'crypto';
import { getSupabaseAdmin } from '@/lib/supabase/admin';
import { getPaystackSecretKey } from '@/lib/payments/paystack-server';

/**
 * Paystack Webhook Handler
 * 
 * Handles Paystack webhook events for payment confirmations
 * Reference: https://paystack.com/docs/payments/webhooks/
 * 
 * IMPORTANT: Paystack uses HMAC SHA512 for webhook signature verification
 */

/**
 * Verify Paystack webhook signature
 * 
 * Algorithm: HMAC SHA512
 * Header: x-paystack-signature
 */
function verifyPaystackWebhook(
  payload: string,
  signature: string,
  secretKey: string
): boolean {
  const hash = crypto
    .createHmac('sha512', secretKey)
    .update(payload)
    .digest('hex');

  return hash === signature;
}

/**
 * POST /api/webhooks/paystack
 * 
 * Webhook endpoint for Paystack events
 */
export async function POST(request: NextRequest) {
  try {
    // Get raw body (important: must use raw body for signature verification)
    const body = await request.text();
    const signature = request.headers.get('x-paystack-signature');

    if (!signature) {
      console.error('Paystack webhook: Missing signature header');
      return NextResponse.json(
        { error: 'Missing signature' },
        { status: 401 }
      );
    }

    // Get Paystack secret key for signature verification
    const secretKey = await getPaystackSecretKey();

    // Verify webhook signature
    const isValid = verifyPaystackWebhook(body, signature, secretKey);

    if (!isValid) {
      console.error('Paystack webhook: Invalid signature');
      return NextResponse.json(
        { error: 'Invalid signature' },
        { status: 401 }
      );
    }

    // Parse event
    const event = JSON.parse(body);
    const supabase = getSupabaseAdmin();

    console.log('Paystack webhook event received:', event.event);

    // Handle different event types
    switch (event.event) {
      case 'charge.success': {
        // Payment successful
        const { reference, amount, customer, metadata, id } = event.data;

        console.log('Processing successful payment:', {
          reference,
          amount: amount / 100, // Convert from kobo to ZAR
          transactionId: id,
        });

        // Extract booking ID from reference or metadata
        const bookingId = reference.startsWith('booking_')
          ? reference.split('_')[1]
          : metadata?.booking_id;

        if (!bookingId) {
          console.error('Paystack webhook: No booking ID found in payment', { reference, metadata });
          return NextResponse.json({ error: 'No booking ID' }, { status: 400 });
        }

        // Get booking details
        const { data: booking, error: bookingError } = await supabase
          .from('bookings')
          .select('id, customer_id, total_amount, ref_number')
          .eq('id', bookingId)
          .single();

        if (bookingError || !booking) {
          console.error('Paystack webhook: Booking not found', { bookingId, error: bookingError });
          return NextResponse.json({ error: 'Booking not found' }, { status: 404 });
        }

        // Record payment in database
        const { data: payment, error: paymentError } = await supabase
          .from('booking_payments')
          .insert({
            booking_id: bookingId,
            amount: amount / 100, // Convert from kobo to ZAR
            payment_method: 'card', // Paystack supports multiple methods, default to card
            payment_provider: 'paystack',
            payment_provider_id: id, // Paystack transaction ID
            status: 'completed',
            notes: `Payment processed via Paystack. Ref: ${reference}`,
            metadata: {
              paystack_reference: reference,
              paystack_customer: customer,
              paystack_metadata: metadata,
            },
          })
          .select()
          .single();

        if (paymentError || !payment) {
          console.error('Paystack webhook: Failed to record payment', { 
            bookingId, 
            error: paymentError 
          });
          return NextResponse.json({ error: 'Failed to record payment' }, { status: 500 });
        }

        console.log('Payment recorded successfully:', payment.id);

        // If payment was from hold flow, mark hold as consumed (idempotent)
        const holdId = metadata?.hold_id;
        if (holdId) {
          const { error: holdUpdateError } = await supabase
            .from('booking_holds')
            .update({
              hold_status: 'consumed',
            })
            .eq('id', holdId)
            .eq('hold_status', 'active');
          if (holdUpdateError) {
            console.warn('Failed to update hold status (may already be consumed):', holdUpdateError);
          }
        }

        // Send confirmation notification via OneSignal
        try {
          const { sendToUser } = await import('@/lib/notifications/onesignal');
          await sendToUser(booking.customer_id, {
            title: 'Payment Confirmed',
            message: `Your payment of R${(amount / 100).toFixed(2)} has been received and confirmed.`,
            type: 'payment_received',
            bookingId: bookingId,
            url: `/account-settings/bookings/${bookingId}`,
            data: {
              type: 'payment_received',
              booking_id: bookingId,
              payment_id: payment.id,
              amount: amount / 100,
            },
          }, ['push']);

          console.log('OneSignal notification sent to customer:', booking.customer_id);
        } catch (notifError) {
          console.warn('Failed to send OneSignal notification:', notifError);
          // Don't fail the webhook if notification fails
        }

        break;
      }

      case 'transfer.success': {
        // Transfer successful (for refunds or payouts)
        console.log('Transfer successful:', event.data);
        // Handle transfer success if needed
        break;
      }

      case 'transfer.failed': {
        // Transfer failed
        console.error('Transfer failed:', event.data);
        // Handle transfer failure if needed
        break;
      }

      case 'refund.processed': {
        // Refund processed
        const { transaction, amount, id } = event.data;

        console.log('Processing refund:', {
          transaction,
          amount: amount / 100,
          refundId: id,
        });

        // Find the original payment by Paystack transaction ID
        const { data: originalPayment } = await supabase
          .from('booking_payments')
          .select('id, booking_id, booking:bookings(customer_id)')
          .eq('payment_provider_id', transaction)
          .single();

        if (originalPayment) {
          // Record refund
          const { data: refund, error: refundError } = await supabase
            .from('booking_refunds')
            .insert({
              booking_id: originalPayment.booking_id,
              payment_id: originalPayment.id,
              amount: amount / 100,
              reason: 'Processed via Paystack',
              refund_method: 'original',
              refund_provider: 'paystack',
              refund_provider_id: id,
              status: 'completed',
              notes: `Refund processed by Paystack. Transaction: ${transaction}`,
            })
            .select()
            .single();

          if (!refundError && refund) {
            console.log('Refund recorded successfully:', refund.id);

            // Send refund notification
            try {
              const { sendToUser } = await import('@/lib/notifications/onesignal');
              const customerId = (originalPayment.booking as any)?.customer_id;

              if (customerId) {
                await sendToUser(customerId, {
                  title: 'Refund Processed',
                  message: `A refund of R${(amount / 100).toFixed(2)} has been processed to your original payment method.`,
                  type: 'refund_processed',
                  bookingId: originalPayment.booking_id,
                  url: `/account-settings/bookings/${originalPayment.booking_id}`,
                  data: {
                    type: 'refund_processed',
                    booking_id: originalPayment.booking_id,
                    refund_id: refund.id,
                    amount: amount / 100,
                  },
                }, ['push']);
              }
            } catch (notifError) {
              console.warn('Failed to send refund notification:', notifError);
            }
          } else {
            console.error('Failed to record refund:', refundError);
          }
        }

        break;
      }

      default:
        console.log('Unhandled Paystack event:', event.event);
    }

    // Always return 200 OK to acknowledge webhook receipt
    // Paystack retries webhooks if not acknowledged
    return NextResponse.json({ received: true, event: event.event });

  } catch (error: any) {
    console.error('Paystack webhook error:', error);

    // Return 200 even on error to prevent Paystack from retrying
    // (we've already logged the error)
    return NextResponse.json(
      { received: true, error: error.message },
      { status: 200 }
    );
  }
}

