/**
 * Auth callback GET: OAuth code exchange and recovery (token_hash + type) redirects.
 */

import { describe, it, expect, vi, beforeEach } from "vitest";
import { NextRequest } from "next/server";

const mockGetSupabaseServer = vi.fn();

vi.mock("@/lib/supabase/server", () => ({
  getSupabaseServer: (...args: any[]) => mockGetSupabaseServer(...args),
}));

describe("GET /auth/callback", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("redirects to reset-password when token_hash and type=recovery and verifyOtp succeeds", async () => {
    const mockVerifyOtp = vi.fn().mockResolvedValue({ error: null });
    mockGetSupabaseServer.mockResolvedValue({
      auth: {
        verifyOtp: mockVerifyOtp,
      },
    });

    const { GET } = await import("../route");
    const req = new NextRequest(
      "https://app.example.com/auth/callback?token_hash=abc123&type=recovery"
    );
    const res = await GET(req);

    expect(res.status).toBe(307);
    expect(res.headers.get("location")).toBe(
      "https://app.example.com/account-settings/login-and-security/reset-password"
    );
    expect(mockVerifyOtp).toHaveBeenCalledWith({
      token_hash: "abc123",
      type: "recovery",
    });
  });

  it("redirects to booking with error when token_hash and type=recovery but verifyOtp fails", async () => {
    const mockVerifyOtp = vi.fn().mockResolvedValue({
      error: { message: "Invalid or expired link" },
    });
    mockGetSupabaseServer.mockResolvedValue({
      auth: { verifyOtp: mockVerifyOtp },
    });

    const { GET } = await import("../route");
    const req = new NextRequest(
      "https://app.example.com/auth/callback?token_hash=bad&type=recovery"
    );
    const res = await GET(req);

    expect(res.status).toBe(307);
    const location = res.headers.get("location") ?? "";
    expect(location).toContain("/booking?error=");
    expect(location).toContain(encodeURIComponent("Invalid or expired link"));
  });

  it("redirects to booking when error param is present", async () => {
    const { GET } = await import("../route");
    const req = new NextRequest(
      "https://app.example.com/auth/callback?error=access_denied&error_description=User+cancelled"
    );
    const res = await GET(req);

    expect(res.status).toBe(307);
    expect(res.headers.get("location")).toContain("/booking?error=");
    expect(mockGetSupabaseServer).not.toHaveBeenCalled();
  });

  it("redirects to next param when token_hash and type=signup and verifyOtp succeeds", async () => {
    const mockVerifyOtp = vi.fn().mockResolvedValue({ error: null });
    mockGetSupabaseServer.mockResolvedValue({
      auth: { verifyOtp: mockVerifyOtp },
    });

    const { GET } = await import("../route");
    const req = new NextRequest(
      "https://app.example.com/auth/callback?token_hash=xyz&type=signup&next=/provider"
    );
    const res = await GET(req);

    expect(res.status).toBe(307);
    expect(res.headers.get("location")).toBe("https://app.example.com/provider");
    expect(mockVerifyOtp).toHaveBeenCalledWith({ token_hash: "xyz", type: "signup" });
  });

  it("redirects to booking with missing_code when no code and no token_hash", async () => {
    mockGetSupabaseServer.mockResolvedValue({ auth: {} });

    const { GET } = await import("../route");
    const req = new NextRequest("https://app.example.com/auth/callback");
    const res = await GET(req);

    expect(res.status).toBe(307);
    expect(res.headers.get("location")).toContain("/booking?error=missing_code");
  });
});

"use client";
import { useState, useEffect } from "react";
import Image from "next/image";
import { Button } from "@/components/ui/button";
import { Carousel } from "@/components/ui/carousel";
import WestMidtown from "./../../../../public/images/bee67cf3-ec5f-4585-a3ec-d12d84187206.jpg";
import Apartments from "./../../../../public/images/c9d2943f-5615-455d-b80d-67b8e615f307.jpg";
import Olive from "./../../../../public/images/5a69d072-2e18-4494-a688-caa005224aad.jpg";
import Sentral from "./../../../../public/images/a78b22a2-e081-4fa4-a7f2-e756d9699801.jpg";
import OldTown from "./../../../../public/images/7b03a67c-eab4-429c-8764-e691f9ef3ad9.jpg";
import Park from "./../../../../public/images/edd9fec5-dbea-45dd-8a79-37e3f1c2a9e2.jpg";

export default function TheCarousel() {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);

  const slides = [
    {
      image: WestMidtown,
      title:
        "WeΓÇÖve partnered with Beautonomi-friendly apartment buildings across the US to make it easier to Beautonomi your place.",
      subtitle: {
        title: "West Midtown at Star Metals",
        location: "Atlanta, Georgia",
      },
    },
    {
      image: Olive,
      title:
        "WeΓÇÖve partnered with Beautonomi-friendly apartment buildings across the US to make it easier to Beautonomi your place.",
      subtitle: {
        title: "525 Olive Apartments",
        location: "San Diego, California",
      },
    },
    {
      image: Sentral,
      title:
        "WeΓÇÖve partnered with Beautonomi-friendly apartment buildings across the US to make it easier to Beautonomi your place.",
      subtitle: {
        title: "Sentral Apartments",
        location: "Denver, Colorado",
      },
    },
    {
      image: Apartments,
      title:
        "WeΓÇÖve partnered with Beautonomi-friendly apartment buildings across the US to make it easier to Beautonomi your place.",
      subtitle: {
        title: "Park 12 Apartments",
        location: "San Diego, California",
      },
    },
    {
      image: OldTown,
      title:
        "WeΓÇÖve partnered with Beautonomi-friendly apartment buildings across the US to make it easier to Beautonomi your place.",
      subtitle: {
        title: "Old Town Apartments",
        location: "Scottsdale, Arizona",
      },
    },
    {
      image: Park,
      title:
        "WeΓÇÖve partnered with Beautonomi-friendly apartment buildings across the US to make it easier to Beautonomi your place.",
      subtitle: {
        title: "Park 12 Apartments",
        location: "San Diego, California",
      },
    },
  ];

  useEffect(() => {
    let intervalId: NodeJS.Timeout | null = null;

    if (isPlaying) {
      intervalId = setInterval(() => {
        setCurrentIndex((prevIndex) =>
          prevIndex < slides.length - 1 ? prevIndex + 1 : 0
        );
      }, 2000); // Change slide every second
    }

    return () => {
      if (intervalId) clearInterval(intervalId);
    };
  }, [isPlaying, slides.length]);

  const handlePrev = () => {
    setCurrentIndex((prevIndex) =>
      prevIndex > 0 ? prevIndex - 1 : slides.length - 1
    );
  };

  const handleNext = () => {
    setCurrentIndex((prevIndex) =>
      prevIndex < slides.length - 1 ? prevIndex + 1 : 0
    );
  };

  const handlePausePlay = () => {
    setIsPlaying((prev) => !prev);
  };

  return (
    <div className="container">
      <div className="flex justify-center items-center mb-20 md:mb-[140px]">
        <Carousel className="w-full h-full rounded-[32px] shadow-lg overflow-hidden">
          <div className="flex flex-col-reverse md:flex-row">
            <div className="w-full md:w-1/2 h-full">
              <Image
                src={slides[currentIndex].image}
                alt="Carousel Image"
                layout="responsive"
                className="h-full"
              />
            </div>
            <div className="w-full md:w-1/2 bg-primary px-10 pt-8 lg:pt-10 pb-4 flex flex-col justify-between">
              <div>
                <h2 className="text-[22px] lg:text-[40px] font-normal  leading-0 lg:leading-[50px] mb-6">
                  {slides[currentIndex].title}
                </h2>
              </div>
              <div>
                <p className="text-base lg:text-2xl  font-normal">
                  {slides[currentIndex].subtitle.title}
                </p>
                <p className="font-normal text-base lg:text-2xl  mb-4">
                  {slides[currentIndex].subtitle.location}
                </p>
                <div className="flex items-center gap-3">
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={handlePrev}
                    className="border h-7 w-7 rounded-full border-black bg-white"
                  >
                    <ChevronLeftIcon className="h-5 w-5" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={handlePausePlay}
                    className="border h-7 w-7 rounded-full border-black bg-white"
                  >
                    {isPlaying ? (
                      <PauseIcon className="h-5 w-5" />
                    ) : (
                      <PlayIcon className="h-5 w-5" />
                    )}
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={handleNext}
                    className="border h-7 w-7 rounded-full border-black bg-white"
                  >
                    <ChevronRightIcon className="h-5 w-5" />
                  </Button>
                </div>
              </div>
            </div>
          </div>
        </Carousel>
      </div>
    </div>
  );
}

