"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/providers/AuthProvider";
import { Button } from "@/components/ui/button";
import { BeautonomiGateModal } from "./BeautonomiGateModal";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import Link from "next/link";
import Image from "next/image";
import { ChevronLeft, Loader2 } from "lucide-react";
import { formatCurrency } from "@/lib/utils";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

interface Provider {
  id: string;
  slug: string;
  business_name: string;
}

interface OnlineBookingSettings {
  staff_selection_mode: "client_chooses" | "anyone_default" | "hidden_auto_assign";
  require_auth_step: "checkout" | "before_time_selection";
  min_notice_minutes: number;
  max_advance_days: number;
}

interface OnlineBookingFlowProps {
  provider: Provider;
  queryParams?: {
    service?: string;
    staff?: string;
    location?: string;
    location_type?: "at_home" | "at_salon";
    anyone?: boolean;
    date?: string;
    auth_return?: string;
  };
  embed?: boolean;
}

interface Service {
  id: string;
  title: string;
  duration_minutes: number;
  price: number;
  currency: string;
}

interface Staff {
  id: string;
  name: string;
  role: string;
}

interface Location {
  id: string;
  name: string;
  address_line1: string;
  city: string;
  country: string;
  is_primary: boolean;
}

interface AtHomeAddress {
  line1: string;
  line2?: string;
  city: string;
  state?: string;
  country: string;
  postal_code?: string;
}

type Step = "services" | "venue" | "staff" | "calendar" | "slots";

const defaultSettings: OnlineBookingSettings = {
  staff_selection_mode: "client_chooses",
  require_auth_step: "checkout",
  min_notice_minutes: 60,
  max_advance_days: 90,
};

export default function OnlineBookingFlow({
  provider,
  queryParams = {},
  embed = false,
}: OnlineBookingFlowProps) {
  const router = useRouter();
  const { user } = useAuth();
  const [step, setStep] = useState<Step>("services");
  const [services, setServices] = useState<Service[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [locations, setLocations] = useState<Location[]>([]);
  const [selectedService, setSelectedService] = useState<Service | null>(null);
  const [selectedStaff, setSelectedStaff] = useState<Staff | null>(null);
  const [locationType, setLocationType] = useState<"at_salon" | "at_home">(
    queryParams.location_type ?? "at_salon"
  );
  const [selectedLocation, setSelectedLocation] = useState<Location | null>(null);
  const [atHomeAddress, setAtHomeAddress] = useState<AtHomeAddress>({
    line1: "",
    city: "",
    country: "ZA",
  });
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [slots, setSlots] = useState<{ time: string; start: string; end: string }[]>([]);
  const [loadingSlots, setLoadingSlots] = useState(false);
  const [creatingHold, setCreatingHold] = useState(false);
  const [holdId, setHoldId] = useState<string | null>(null);
  const [gateOpen, setGateOpen] = useState(false);
  const [preAuthGateOpen, setPreAuthGateOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [settings, setSettings] = useState<OnlineBookingSettings>(defaultSettings);

  const goToCalendarOrAuth = () => {
    if (authBeforeSlots && !user) {
      // Persist state for restore after OAuth redirect
      try {
        if (typeof sessionStorage !== "undefined") {
          sessionStorage.setItem(
            "beautonomi_preauth_state",
            JSON.stringify({
              selectedService,
              selectedStaff,
              selectedLocation,
              locationType,
              atHomeAddress,
            })
          );
        }
      } catch {
        // ignore
      }
      setPreAuthGateOpen(true);
    } else {
      setStep("calendar");
    }
  };

  const showStaffStep =
    settings.staff_selection_mode === "client_chooses";
  const _defaultToAnyone = settings.staff_selection_mode === "anyone_default";
  const authBeforeSlots = settings.require_auth_step === "before_time_selection";

  useEffect(() => {
    Promise.all([
      fetcher.get<{ data: { offerings?: Service[] } }>(
        `/api/public/providers/${provider.slug}/offerings`
      ),
      fetcher.get<{ data: { staff?: Staff[] } }>(
        `/api/public/providers/${provider.slug}/staff`
      ),
      fetcher
        .get<{ data: { id: string; slug: string; locations?: Location[] } }>(
          `/api/public/providers/${provider.slug}`
        )
        .catch(() => ({ data: { locations: [] } })),
      fetcher
        .get<{ data: OnlineBookingSettings }>(
          `/api/public/providers/${provider.slug}/online-booking-settings`
        )
        .catch(() => ({ data: defaultSettings })),
    ])
      .then(([svcRes, staffRes, provRes, settingsRes]) => {
        const offerings = (svcRes.data as any)?.offerings ?? (svcRes.data as any) ?? [];
        const servicesList = Array.isArray(offerings) ? offerings : [];
        setServices(servicesList);
        const staffList = (staffRes.data as any)?.staff ?? (staffRes.data as any) ?? [];
        setStaff(Array.isArray(staffList) ? staffList : []);
        const locs = (provRes.data as any)?.locations ?? [];
        setLocations(Array.isArray(locs) ? locs : []);
        if (locs?.length > 0) {
          setSelectedLocation((prev) => {
            if (prev) return prev;
            if (queryParams.location) {
              const match = (locs as Location[]).find(
                (l) => l.id === queryParams.location || (l as any).slug === queryParams.location
              );
              if (match) return match;
            }
            return locs.find((l: Location) => l.is_primary) ?? locs[0];
          });
        }
        const s = (settingsRes as any)?.data ?? defaultSettings;
        setSettings(s);

        if (queryParams.service) {
          const match = servicesList.find(
            (svc: Service) => svc.id === queryParams.service || (svc as any).slug === queryParams.service
          );
          if (match) setSelectedService(match);
        }
        if (
          queryParams.anyone ||
          (s as OnlineBookingSettings).staff_selection_mode === "anyone_default" ||
          (s as OnlineBookingSettings).staff_selection_mode === "hidden_auto_assign"
        ) {
          setSelectedStaff({ id: "any", name: "Anyone available", role: "" });
        } else if (queryParams.staff) {
          const staffMatch = (Array.isArray(staffList) ? staffList : []).find(
            (st: Staff) => st.id === queryParams.staff || (st as any).slug === queryParams.staff
          );
          if (staffMatch) setSelectedStaff(staffMatch);
        }
      })
      .catch((e) => {
        toast.error(e instanceof FetchError ? e.message : "Failed to load");
      })
      .finally(() => setIsLoading(false));
  }, [provider.slug, queryParams.service, queryParams.staff, queryParams.anyone, queryParams.location]);

  useEffect(() => {
    if (queryParams.auth_return === "slots" && queryParams.date && user && selectedService && selectedStaff) {
      const d = new Date(queryParams.date);
      if (!isNaN(d.getTime())) {
        setSelectedDate(d);
        setStep("slots");
      }
    }
  }, [queryParams.auth_return, queryParams.date, user, selectedService, selectedStaff]);

  useEffect(() => {
    if (queryParams.auth_return === "calendar" && user) {
      // Restore state from sessionStorage (lost during OAuth redirect)
      try {
        const saved = typeof sessionStorage !== "undefined" && sessionStorage.getItem("beautonomi_preauth_state");
        if (saved) {
          const parsed = JSON.parse(saved);
          if (parsed.selectedService && services.some((s) => s.id === parsed.selectedService.id)) {
            setSelectedService(parsed.selectedService);
          }
          if (parsed.selectedStaff) {
            setSelectedStaff(
              parsed.selectedStaff.id === "any"
                ? { id: "any", name: "Anyone available", role: "" }
                : staff.find((s) => s.id === parsed.selectedStaff.id) ?? parsed.selectedStaff
            );
          }
          if (parsed.selectedLocation && locations.some((l: Location) => l.id === parsed.selectedLocation?.id)) {
            setSelectedLocation(parsed.selectedLocation);
          }
          if (parsed.locationType) setLocationType(parsed.locationType);
          if (parsed.atHomeAddress && Object.keys(parsed.atHomeAddress).length > 0) {
            setAtHomeAddress((prev) => ({ ...prev, ...parsed.atHomeAddress }));
          }
          sessionStorage.removeItem("beautonomi_preauth_state");
        }
      } catch {
        // ignore restore errors
      }
      setStep("calendar");
    }
  }, [queryParams.auth_return, user, services, staff, locations]);

  useEffect(() => {
    if (step !== "slots" || !selectedDate || !selectedService || !selectedStaff) return;
    setLoadingSlots(true);
    const dateStr = selectedDate.toISOString().split("T")[0];
    const staffParam = selectedStaff.id === "any" ? "any" : selectedStaff.id;
    fetcher
      .get<{ data: { slots?: any[] } }>(
        `/api/public/providers/${provider.slug}/availability?date=${dateStr}&service_id=${selectedService.id}&staff_id=${staffParam}&duration_minutes=${selectedService.duration_minutes}&location_id=${selectedLocation?.id ?? ""}&min_notice_minutes=${settings.min_notice_minutes}&max_advance_days=${settings.max_advance_days}`
      )
      .then((res) => {
        const s = (res.data as any)?.slots ?? res.data ?? [];
        setSlots(Array.isArray(s) ? s : []);
      })
      .catch(() => setSlots([]))
      .finally(() => setLoadingSlots(false));
  }, [step, selectedDate, selectedService, selectedStaff, selectedLocation, provider.slug, settings.min_notice_minutes, settings.max_advance_days]);

  const handleSecureSlot = async (
    slotStart: string,
    slotEnd: string,
    slotStaffId?: string
  ) => {
    if (!selectedService || !selectedStaff) return;
    if (locationType === "at_home" && (!atHomeAddress.line1?.trim() || !atHomeAddress.city?.trim())) {
      toast.error("Please enter your address for at-home booking");
      return;
    }
    const staffIdForHold =
      slotStaffId ?? (selectedStaff.id !== "any" ? selectedStaff.id : null);
    if (!staffIdForHold) {
      toast.error("Unable to secure this slot. Please select a specific staff member.");
      return;
    }
    setCreatingHold(true);
    try {
      let addressPayload: {
        line1: string;
        city: string;
        country: string;
        line2?: string;
        state?: string;
        postal_code?: string;
        latitude?: number;
        longitude?: number;
      } | null = null;

      if (
        locationType === "at_home" &&
        atHomeAddress.line1.trim() &&
        atHomeAddress.city.trim()
      ) {
        addressPayload = {
          line1: atHomeAddress.line1.trim(),
          city: atHomeAddress.city.trim(),
          country: atHomeAddress.country.trim() || "ZA",
          line2: atHomeAddress.line2,
          state: atHomeAddress.state,
          postal_code: atHomeAddress.postal_code,
        };
        try {
          const query = [atHomeAddress.line1.trim(), atHomeAddress.city.trim(), atHomeAddress.country.trim() || "ZA"].filter(Boolean).join(", ");
          const geocodeRes = await fetcher.post<{ data: Array<{ center: [number, number] }> }>("/api/mapbox/geocode", { query, limit: 1 });
          const results = (geocodeRes as any)?.data ?? [];
          if (results.length > 0 && results[0].center) {
            const [lng, lat] = results[0].center;
            addressPayload.latitude = lat;
            addressPayload.longitude = lng;
          }
        } catch {
          // Proceed without coords; travel fee will be 0
        }
      }

      const res = await fetcher.post<{ data: { hold_id: string; expires_at: string } }>(
        "/api/public/booking-holds",
        {
          provider_id: provider.id,
          staff_id: staffIdForHold,
          services: [{ offering_id: selectedService.id, staff_id: staffIdForHold }],
          start_at: slotStart,
          end_at: slotEnd,
          location_type: locationType,
          location_id: locationType === "at_salon" ? selectedLocation?.id : null,
          address: addressPayload,
        }
      );
      const id = (res.data as any)?.hold_id ?? res.data?.hold_id;
      if (id) {
        setHoldId(id);
        setGateOpen(true);
      } else {
        toast.error("Failed to secure slot");
      }
    } catch (e) {
      toast.error(e instanceof FetchError ? e.message : "Failed to secure slot");
    } finally {
      setCreatingHold(false);
    }
  };

  const handleAuthComplete = () => {
    setGateOpen(false);
    if (holdId) {
      router.push(`/book/continue?hold_id=${holdId}`);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className={`min-h-screen bg-background ${embed ? "p-2" : ""}`}>
      <div className={`mx-auto space-y-6 ${embed ? "max-w-md p-3" : "max-w-lg p-6"}`}>
        <div className="flex items-center gap-3">
          <Link href="/" className="shrink-0" aria-label="Beautonomi home">
            <Image src="/images/logo.svg" alt="Beautonomi" width={120} height={32} className="h-8 w-auto" />
          </Link>
        </div>
        <h1 className={embed ? "text-lg font-semibold" : "text-2xl font-semibold"}>
          Book with {provider.business_name}
        </h1>

        {step === "services" && (
          <div className="space-y-4">
            <h2 className="font-medium">Select a service</h2>
            {services.length === 0 ? (
              <p className="text-muted-foreground">No services available</p>
            ) : (
              <div className="space-y-2">
                {services.map((s) => (
                  <button
                    key={s.id}
                    onClick={() => {
                      setSelectedService(s);
                      setStep("venue");
                    }}
                    className="w-full text-left p-4 rounded-lg border hover:bg-muted/50 transition-colors"
                  >
                    <div className="font-medium">{s.title}</div>
                    <div className="text-sm text-muted-foreground">
                      {s.duration_minutes} min ┬╖ {formatCurrency(s.price, s.currency)}
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        )}

        {step === "venue" && (
          <div className="space-y-4">
            <Button variant="ghost" size="sm" onClick={() => setStep("services")}>
              <ChevronLeft className="h-4 w-4" /> Back
            </Button>
            <h2 className="font-medium">Where?</h2>
            <div className="flex gap-3">
              <Button
                variant={locationType === "at_salon" ? "default" : "outline"}
                onClick={() => setLocationType("at_salon")}
              >
                At salon
              </Button>
              <Button
                variant={locationType === "at_home" ? "default" : "outline"}
                onClick={() => setLocationType("at_home")}
              >
                At my location
              </Button>
            </div>
            {locationType === "at_salon" && locations.length > 1 && (
              <div className="space-y-2">
                {locations.map((loc) => (
                  <button
                    key={loc.id}
                    onClick={() => setSelectedLocation(loc)}
                    className={`w-full text-left p-3 rounded border ${
                      selectedLocation?.id === loc.id ? "border-primary" : ""
                    }`}
                  >
                    {loc.name} ┬╖ {loc.address_line1}, {loc.city}
                  </button>
                ))}
              </div>
            )}
            {locationType === "at_salon" && locations.length === 0 && (
              <p className="text-sm text-amber-600">
                This provider has no locations. Please choose &quot;At my location&quot; or select another provider.
              </p>
            )}
            {locationType === "at_home" && (
              <div className="space-y-3">
                <Label>Address (required for at-home bookings)</Label>
                <Input
                  placeholder="Street address"
                  value={atHomeAddress.line1}
                  onChange={(e) =>
                    setAtHomeAddress((a) => ({ ...a, line1: e.target.value }))
                  }
                />
                <div className="grid grid-cols-2 gap-2">
                  <Input
                    placeholder="City"
                    value={atHomeAddress.city}
                    onChange={(e) =>
                      setAtHomeAddress((a) => ({ ...a, city: e.target.value }))
                    }
                  />
                  <Input
                    placeholder="Country"
                    value={atHomeAddress.country}
                    onChange={(e) =>
                      setAtHomeAddress((a) => ({ ...a, country: e.target.value }))
                    }
                  />
                </div>
              </div>
            )}
            <Button
              onClick={() => {
                if (!showStaffStep) {
                  setSelectedStaff((prev) =>
                    prev?.id === "any" ? prev : { id: "any", name: "Anyone available", role: "" }
                  );
                  goToCalendarOrAuth();
                } else {
                  setStep("staff");
                }
              }}
              disabled={
                (locationType === "at_salon" && locations.length === 0) ||
                (locationType === "at_home" && (!atHomeAddress.line1.trim() || !atHomeAddress.city.trim()))
              }
            >
              Next
            </Button>
          </div>
        )}

        {step === "staff" && showStaffStep && (
          <div className="space-y-4">
            <Button variant="ghost" size="sm" onClick={() => setStep("venue")}>
              <ChevronLeft className="h-4 w-4" /> Back
            </Button>
            <h2 className="font-medium">Who?</h2>
            <div className="space-y-2">
              <button
                onClick={() => {
                  setSelectedStaff({ id: "any", name: "Anyone available", role: "" });
                  goToCalendarOrAuth();
                }}
                className={`w-full text-left p-4 rounded-lg border hover:bg-muted/50 transition-colors ${
                  selectedStaff?.id === "any" ? "border-primary" : ""
                }`}
              >
                Anyone available
              </button>
              {staff.map((s) => (
                <button
                  key={s.id}
                  onClick={() => {
                    setSelectedStaff(s);
                    goToCalendarOrAuth();
                  }}
                  className={`w-full text-left p-4 rounded-lg border hover:bg-muted/50 transition-colors ${
                    selectedStaff?.id === s.id ? "border-primary" : ""
                  }`}
                >
                  {s.name} ┬╖ {s.role}
                </button>
              ))}
            </div>
          </div>
        )}

        {step === "calendar" && (
          <div className="space-y-4">
            <Button variant="ghost" size="sm" onClick={() => setStep(showStaffStep ? "staff" : "venue")}>
              <ChevronLeft className="h-4 w-4" /> Back
            </Button>
            <h2 className="font-medium">Pick a date</h2>
            <div className="grid grid-cols-7 gap-1">
              {Array.from({ length: Math.min(settings.max_advance_days, 90) }, (_, i) => {
                const d = new Date();
                d.setDate(d.getDate() + i);
                const isSelected =
                  selectedDate?.toDateString() === d.toDateString();
                return (
                  <button
                    key={i}
                    onClick={() => setSelectedDate(d)}
                    className={`p-2 rounded text-sm ${
                      isSelected ? "bg-primary text-primary-foreground" : "hover:bg-muted"
                    }`}
                  >
                    {d.getDate()}
                  </button>
                );
              })}
            </div>
            <Button
              onClick={() => setStep("slots")}
              disabled={!selectedDate}
            >
              Next
            </Button>
          </div>
        )}

        {step === "slots" && (
          <div className="space-y-4">
            <Button variant="ghost" size="sm" onClick={() => setStep("calendar")}>
              <ChevronLeft className="h-4 w-4" /> Back
            </Button>
            <h2 className="font-medium">Pick a time</h2>
            {loadingSlots ? (
              <Loader2 className="h-6 w-6 animate-spin" />
            ) : slots.length === 0 ? (
              <p className="text-muted-foreground">No slots available for this date</p>
            ) : (
              <div className="grid grid-cols-3 gap-2">
                {slots
                  .filter((slot) => (slot as any).is_available !== false)
                  .map((slot, i) => {
                    const start = (slot as any).start ?? (slot as any).time ?? slot;
                    const end = (slot as any).end ?? start;
                    const slotStaffId = (slot as any).staff_id;
                    const displayTime =
                      typeof start === "string"
                        ? new Date(start).toLocaleTimeString([], {
                            hour: "2-digit",
                            minute: "2-digit",
                          })
                        : String(start);
                    return (
                      <Button
                        key={i}
                        variant="outline"
                        size="sm"
                        onClick={() =>
                          handleSecureSlot(start, end, slotStaffId)
                        }
                        disabled={creatingHold}
                      >
                      {creatingHold ? (
                        <Loader2 className="h-4 w-4 animate-spin" />
                      ) : (
                        displayTime
                      )}
                    </Button>
                  );
                })}
              </div>
            )}
          </div>
        )}
      </div>

      <BeautonomiGateModal
        holdId={holdId ?? ""}
        open={gateOpen || preAuthGateOpen}
        onAuthComplete={handleAuthComplete}
        onClose={() => {
          setGateOpen(false);
          setPreAuthGateOpen(false);
        }}
        redirectUrl={
          preAuthGateOpen
            ? `${typeof window !== "undefined" ? window.location.origin : ""}/book/${provider.slug}?auth_return=calendar&location_type=${locationType}${selectedService ? `&service=${selectedService.id}` : ""}${selectedStaff ? (selectedStaff.id === "any" ? "&anyone=true" : `&staff=${selectedStaff.id}`) : ""}${selectedLocation ? `&location=${selectedLocation.id}` : ""}`
            : undefined
        }
      />
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/providers/AuthProvider";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import { Loader2, ChevronRight } from "lucide-react";
import { formatCurrency } from "@/lib/utils";
import { BeautonomiGateModal } from "./BeautonomiGateModal";
import {
  BookingNav,
  StepVenue,
  StepCategory,
  StepServices,
  StepAddons,
  StepGroupParticipants,
  StepStaff,
  StepSchedule,
  StepIntake,
  StepReview,
} from "./booking-engine";
import ResourceSelection from "@/components/booking/ResourceSelection";
import type {
  BookingData,
  BookingStep,
  LocationOption,
  ServiceOption,
  PackageOption,
  StaffOption,
  AddonOption,
  ServiceVariant,
  BookingServiceEntry,
  ProviderCategoryOption,
} from "../types/booking-engine";

import {
  BOOKING_ACCENT,
  BOOKING_BG,
  BOOKING_GLASS_BG,
  BOOKING_EDGE,
  BOOKING_SHADOW_MAIN,
  BOOKING_SHADOW_CARD,
  PLATFORM_NAME,
  BOOKING_TEXT_SECONDARY,
  BOOKING_TEXT_PRIMARY,
} from "../constants";

const defaultBookingData: BookingData = {
  venueType: "at_salon",
  selectedLocation: null,
  atHomeAddress: { line1: "", city: "", country: "ZA" },
  selectedCategory: null,
  selectedPackage: null,
  selectedServices: [],
  selectedAddonIds: [],
  addonsSubtotal: 0,
  selectedStaff: null,
  selectedDate: null,
  selectedSlot: null,
  selectedResourceIds: [],
  client: {
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    specialRequests: "",
  },
  currency: "ZAR",
  servicesSubtotal: 0,
  totalDurationMinutes: 0,
};

interface Provider {
  id: string;
  slug: string;
  business_name: string;
}

interface OnlineBookingSettings {
  staff_selection_mode: "client_chooses" | "anyone_default" | "hidden_auto_assign";
  require_auth_step: "checkout" | "before_time_selection";
  min_notice_minutes: number;
  max_advance_days: number;
  allow_pay_in_person?: boolean;
  deposit_required?: boolean;
  deposit_amount?: number | null;
  deposit_percent?: number | null;
  allow_online_waitlist?: boolean;
}

interface GroupBookingSettings {
  enabled: boolean;
  maxGroupSize: number;
  excludedServices: string[];
  enabledLocations: string[];
}

interface ProviderFormField {
  id: string;
  name: string;
  field_type: string;
  is_required: boolean;
  sort_order: number;
}

interface ProviderForm {
  id: string;
  title: string;
  description: string | null;
  form_type: string;
  is_required: boolean;
  is_active: boolean;
  fields: ProviderFormField[];
}

interface CancellationPolicy {
  policy_text?: string;
  hours_before_cutoff?: number;
  late_cancellation_type?: "no_refund" | "partial_refund" | "full_refund";
}

interface OnlineBookingFlowNewProps {
  provider: Provider;
  queryParams?: {
    service?: string;
    staff?: string;
    location?: string;
    location_type?: "at_home" | "at_salon";
    anyone?: boolean;
    date?: string;
    auth_return?: string;
  };
  embed?: boolean;
}

export default function OnlineBookingFlowNew({
  provider,
  queryParams = {},
  embed = false,
}: OnlineBookingFlowNewProps) {
  // #region agent log (only when NEXT_PUBLIC_DEBUG_INGEST_URL is set)
  const debugIngestUrl = typeof process !== "undefined" ? process.env?.NEXT_PUBLIC_DEBUG_INGEST_URL : undefined;
  if (debugIngestUrl) {
    fetch(debugIngestUrl, { method: "POST", headers: { "Content-Type": "application/json", "X-Debug-Session-Id": "9fda2d" }, body: JSON.stringify({ sessionId: "9fda2d", location: "OnlineBookingFlowNew.tsx:component-entry", message: "render start", data: { slug: provider?.slug }, timestamp: Date.now(), hypothesisId: "H1" }) }).catch(() => {});
  }
  // #endregion
  const router = useRouter();
  const { user } = useAuth();

  const [step, setStep] = useState<BookingStep>("venue");
  const [bookingData, setBookingData] = useState<BookingData>(() => ({
    ...defaultBookingData,
    venueType: (queryParams.location_type as "at_salon" | "at_home") ?? "at_salon",
  }));

  // #region agent log
  if (debugIngestUrl) {
    fetch(debugIngestUrl, { method: "POST", headers: { "Content-Type": "application/json", "X-Debug-Session-Id": "9fda2d" }, body: JSON.stringify({ sessionId: "9fda2d", location: "OnlineBookingFlowNew.tsx:before-useCallback", message: "about to define updateData", data: {}, timestamp: Date.now(), hypothesisId: "H2" }) }).catch(() => {});
  }
  // #endregion
  const updateDataRef = useRef<(patch: Partial<BookingData>) => void>(() => {});
  const updateDataImpl = useCallback((patch: Partial<BookingData>) => {
    setBookingData((prev) => {
      const next = { ...prev, ...patch };
      const servicesSubtotal = next.selectedServices.reduce((s, e) => s + e.price, 0);
      return {
        ...next,
        servicesSubtotal: next.selectedPackage ? (next.selectedPackage.price ?? servicesSubtotal) : servicesSubtotal,
        totalDurationMinutes: next.selectedServices.reduce((s, e) => s + e.duration_minutes, 0),
        currency: next.selectedServices[0]?.currency ?? next.currency ?? "ZAR",
      };
    });
  }, []);
  updateDataRef.current = updateDataImpl;
  const updateData = useCallback((patch: Partial<BookingData>) => updateDataRef.current(patch), []);

  // #region agent log
  if (debugIngestUrl) {
    fetch(debugIngestUrl, { method: "POST", headers: { "Content-Type": "application/json", "X-Debug-Session-Id": "9fda2d" }, body: JSON.stringify({ sessionId: "9fda2d", location: "OnlineBookingFlowNew.tsx:after-updateData", message: "updateData defined", data: {}, timestamp: Date.now(), hypothesisId: "H3" }) }).catch(() => {});
  }
  // #endregion
  const [locations, setLocations] = useState<LocationOption[]>([]);
  const [offerings, setOfferings] = useState<ServiceOption[]>([]);
  const [packages, setPackages] = useState<PackageOption[]>([]);
  const [staff, setStaff] = useState<StaffOption[]>([]);
  const [addons, setAddons] = useState<AddonOption[]>([]);
  const [variantsByServiceId, setVariantsByServiceId] = useState<Record<string, ServiceVariant[]>>({});
  const [settings, setSettings] = useState<OnlineBookingSettings>({
    staff_selection_mode: "client_chooses",
    require_auth_step: "checkout",
    min_notice_minutes: 60,
    max_advance_days: 90,
  });

  const [slots, setSlots] = useState<Array<{ start: string; end: string; staff_id?: string; is_available?: boolean }>>([]);
  const [loadingSlots, setLoadingSlots] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [holdId, setHoldId] = useState<string | null>(null);
  const [gateOpen, setGateOpen] = useState(false);
  const [preAuthGateOpen, setPreAuthGateOpen] = useState(false);
  const [creatingHold, setCreatingHold] = useState(false);
  const [providerForms, setProviderForms] = useState<ProviderForm[]>([]);
  const [bookingCustomDefinitions, setBookingCustomDefinitions] = useState<Array<{ id: string; name: string; label: string; field_type: string; is_required: boolean }>>([]);
  const [cancellationPolicy, setCancellationPolicy] = useState<CancellationPolicy | null>(null);
  const [groupBookingSettings, setGroupBookingSettings] = useState<GroupBookingSettings>({
    enabled: false,
    maxGroupSize: 10,
    excludedServices: [],
    enabledLocations: [],
  });

  const showStaffStep = settings.staff_selection_mode === "client_chooses";
  const showGroupStep = groupBookingSettings.enabled === true;
  const authBeforeSlots = settings.require_auth_step === "before_time_selection";

  // Derive provider categories from offerings (unique by provider_category_id)
  const categories: ProviderCategoryOption[] = (() => {
    const seen = new Map<string, ProviderCategoryOption>();
    for (const o of offerings as (ServiceOption & { provider_categories?: { id: string; name: string; description?: string | null; display_order?: number; color?: string | null }; master_service_name?: string })[]) {
      const cat = (o as any).provider_categories;
      if (cat?.id && cat?.name) {
        if (!seen.has(cat.id)) {
          seen.set(cat.id, { id: cat.id, name: cat.name, description: cat.description ?? null, color: cat.color ?? null, display_order: cat.display_order ?? 0 });
        }
      } else {
        if (!seen.has("_other")) {
          seen.set("_other", { id: "_other", name: "Other Services", description: null, display_order: 999 });
        }
      }
    }
    const list = Array.from(seen.values()).sort((a, b) => (a.display_order ?? 0) - (b.display_order ?? 0));
    if (list.length === 0) return [{ id: "_all", name: "Services", description: "All services" }];
    return list;
  })();

  // Offerings filtered by selected category for the services step
  const offeringsForStep = (() => {
    if (!bookingData.selectedCategory) return offerings;
    const cat = bookingData.selectedCategory;
    if (cat.id === "_all") return offerings;
    if (cat.id === "_other") {
      return (offerings as any[]).filter((o) => !o.provider_categories?.id && !o.provider_category_id);
    }
    return (offerings as any[]).filter(
      (o) => o.provider_categories?.id === cat.id || o.provider_category_id === cat.id || o.master_service_name === cat.name
    );
  })();

  // Auto-select single category when only one exists
  useEffect(() => {
    // #region agent log
    if (debugIngestUrl) {
      fetch(debugIngestUrl, { method: "POST", headers: { "Content-Type": "application/json", "X-Debug-Session-Id": "9fda2d" }, body: JSON.stringify({ sessionId: "9fda2d", location: "OnlineBookingFlowNew.tsx:effect-category", message: "effect runs", data: { step, categoriesLen: categories?.length, runId: "post-fix" }, timestamp: Date.now(), hypothesisId: "H4" }) }).catch(() => {});
    }
    // #endregion
    if (step === "category" && categories.length === 1 && !bookingData.selectedCategory) {
      updateDataRef.current({ selectedCategory: categories[0] });
    }
  }, [step, categories, bookingData.selectedCategory]);

  useEffect(() => {
    setBookingData((prev) => {
      const addonsSubtotal = prev.selectedAddonIds.reduce((sum, id) => {
        const a = addons.find((x) => x.id === id);
        return sum + (a ? a.price : 0);
      }, 0);
      return { ...prev, addonsSubtotal };
    });
  }, [addons, bookingData.selectedAddonIds]);

  // Group booking: slot duration = max(primary duration, each participant's total duration) so one time slot fits everyone
  useEffect(() => {
    if (!bookingData.isGroupBooking || !bookingData.groupParticipants?.length) return;
    const primaryDur = bookingData.selectedServices.reduce((s, e) => s + e.duration_minutes, 0);
    let maxDur = primaryDur;
    for (const p of bookingData.groupParticipants) {
      const pDur = p.service_ids.reduce(
        (sum, id) => sum + (offerings.find((o) => o.id === id)?.duration_minutes ?? 0),
        0
      );
      maxDur = Math.max(maxDur, pDur);
    }
    setBookingData((prev) => (prev.totalDurationMinutes === maxDur ? prev : { ...prev, totalDurationMinutes: maxDur }));
  }, [
    bookingData.isGroupBooking,
    bookingData.groupParticipants,
    bookingData.selectedServices,
    offerings,
  ]);

  useEffect(() => {
    const load = async () => {
      try {
        const [offeringsRes, staffRes, providerRes, settingsRes, packagesRes] = await Promise.all([
          fetcher.get<{ data: ServiceOption[] }>(`/api/public/providers/${provider.slug}/offerings`),
          fetcher
            .get<{ data: StaffOption[] }>(`/api/public/providers/${provider.slug}/staff`)
            .catch(() => ({ data: [] })),
          fetcher.get<{ data: { locations?: LocationOption[] } }>(`/api/public/providers/${provider.slug}`),
          fetcher.get<{ data: OnlineBookingSettings }>(`/api/public/providers/${provider.slug}/online-booking-settings`).catch(() => ({ data: null })),
          fetcher.get<{ data: PackageOption[] }>(`/api/public/providers/${provider.slug}/packages`).catch(() => ({ data: [] })),
        ]);

        const rawOfferings = (offeringsRes as any)?.data ?? offeringsRes ?? [];
        const list = Array.isArray(rawOfferings) ? rawOfferings : [];
        const baseServices = list.filter(
          (o: any) => o.service_type !== "addon" && !o.parent_service_id
        );
        setOfferings(baseServices);

        const staffList = (staffRes as any)?.data ?? staffRes ?? [];
        const staffArray = Array.isArray(staffList) ? staffList : [];
        setStaff(staffArray);

        const locs = (providerRes as any)?.data?.locations ?? [];
        setLocations(Array.isArray(locs) ? locs : []);
        const salonLocs = Array.isArray(locs) ? locs.filter((l: any) => (l.location_type || "salon") === "salon") : [];
        if (salonLocs.length > 0) {
          const primary = salonLocs.find((l: LocationOption) => l.is_primary) ?? salonLocs[0];
          const fromQuery = queryParams.location ? salonLocs.find((l: any) => l.id === queryParams.location || (l as any).slug === queryParams.location) : null;
          setBookingData((prev) => ({
            ...prev,
            venueType: "at_salon",
            selectedLocation: fromQuery ?? primary,
          }));
        } else {
          setBookingData((prev) => ({
            ...prev,
            venueType: "at_home",
            selectedLocation: null,
          }));
        }

        const s = (settingsRes as any)?.data;
        if (s) setSettings(s);

        const pkgList = (packagesRes as any)?.data ?? packagesRes ?? [];
        setPackages(Array.isArray(pkgList) ? pkgList : []);

        const variantPromises = baseServices.map((svc: any) =>
          fetcher.get(`/api/public/providers/${provider.slug}/services/${svc.id}/variants`).catch(() => ({ data: { variants: [] } }))
        );
        const variantResults = await Promise.all(variantPromises);
        const map: Record<string, ServiceVariant[]> = {};
        baseServices.forEach((svc: any, i: number) => {
          const res = variantResults[i] as any;
          const variants = res?.data?.variants ?? res?.variants ?? [];
          if (variants.length > 0) map[svc.id] = variants;
        });
        setVariantsByServiceId(map);

        if (queryParams.service) {
          const match = list.find((s: any) => s.id === queryParams.service || (s as any).slug === queryParams.service);
          if (match) {
            setBookingData((prev) => ({
              ...prev,
              selectedServices: [
                {
                  offering_id: match.id,
                  title: match.title,
                  duration_minutes: match.duration_minutes,
                  price: match.price,
                  currency: match.currency ?? "ZAR",
                },
              ],
            }));
          }
        }
        if (queryParams.anyone || s?.staff_selection_mode === "anyone_default") {
          setBookingData((prev) => ({ ...prev, selectedStaff: { id: "any", name: "No preference", role: "Anyone available" } }));
        } else if (queryParams.staff && staffArray.length > 0) {
          const st = staffArray.find((s: StaffOption) => s.id === queryParams.staff);
          if (st) setBookingData((prev) => ({ ...prev, selectedStaff: st }));
        }

        // Group booking settings (for group step)
        const groupRes = await fetcher
          .get<{ data?: { enabled?: boolean; maxGroupSize?: number; excludedServices?: string[]; enabledLocations?: string[] } }>(
            `/api/public/providers/${provider.slug}/group-booking-settings`
          )
          .catch(() => ({ data: { enabled: false, maxGroupSize: 10, excludedServices: [], enabledLocations: [] } }));
        const g = (groupRes as any)?.data ?? groupRes ?? {};
        setGroupBookingSettings({
          enabled: g.enabled === true,
          maxGroupSize: typeof g.maxGroupSize === "number" ? g.maxGroupSize : 10,
          excludedServices: Array.isArray(g.excludedServices) ? g.excludedServices : [],
          enabledLocations: Array.isArray(g.enabledLocations) ? g.enabledLocations : [],
        });

        // Load provider forms and booking custom field definitions for intake step
        const [formsRes, customRes] = await Promise.all([
          fetcher.get<{ data?: { forms?: ProviderForm[] }; forms?: ProviderForm[] }>(`/api/public/provider-forms?provider_id=${provider.id}`).catch(() => ({ data: { forms: [] } })),
          fetcher.get<{ data?: { definitions?: Array<{ id: string; name: string; label: string; field_type: string; is_required: boolean }> } }>("/api/custom-fields/definitions?entity_type=booking").catch(() => ({ data: { definitions: [] } })),
        ]);
        const formsData = (formsRes as { data?: { forms?: ProviderForm[] }; forms?: ProviderForm[] })?.data ?? formsRes;
        const formsList =
          Array.isArray((formsData as { forms?: ProviderForm[] }).forms)
            ? (formsData as { forms: ProviderForm[] }).forms
            : Array.isArray((formsData as { data?: { forms?: ProviderForm[] } }).data?.forms)
              ? (formsData as { data: { forms: ProviderForm[] } }).data.forms
              : [];
        setProviderForms(formsList);
        const defs = (customRes as { data?: { definitions?: Array<{ id: string; name: string; label: string; field_type: string; is_required: boolean }> } })?.data?.definitions ?? [];
        setBookingCustomDefinitions(Array.isArray(defs) ? defs : []);
      } catch (e) {
        toast.error(e instanceof FetchError ? e.message : "Failed to load");
      } finally {
        setIsLoading(false);
      }
    };
    load();
  }, [provider.slug, provider.id, queryParams.service, queryParams.staff, queryParams.anyone, queryParams.location]);

  // Load cancellation policy when we have provider and venue (for review step)
  useEffect(() => {
    if (!provider.id || step !== "review") return;
    const locationType = bookingData.venueType === "at_home" ? "at_home" : "at_salon";
    fetcher
      .get<{ data?: CancellationPolicy[] }>(`/api/public/cancellation-policy?provider_id=${provider.id}&location_type=${locationType}`)
      .then((res) => {
        const data = (res as { data?: CancellationPolicy[] })?.data;
        if (data && data.length > 0) setCancellationPolicy(data[0]);
        else
          setCancellationPolicy({
            policy_text: "Cancellations must be made at least 24 hours before your appointment. Cancellations made within 24 hours may be subject to a cancellation fee.",
            hours_before_cutoff: 24,
            late_cancellation_type: "no_refund",
          });
      })
      .catch(() =>
        setCancellationPolicy({
          policy_text: "Cancellations must be made at least 24 hours before your appointment.",
          hours_before_cutoff: 24,
          late_cancellation_type: "no_refund",
        })
      );
  }, [provider.id, bookingData.venueType, step]);

  const primaryServiceId = bookingData.selectedServices[0]?.offering_id;
  useEffect(() => {
    if (!primaryServiceId) {
      setAddons([]);
      return;
    }
    fetcher
      .get<{ data: { all_addons?: AddonOption[] }; all_addons?: AddonOption[] }>(
        `/api/public/providers/${provider.slug}/services/${primaryServiceId}/addons`
      )
      .then((res) => {
        const data = res as any;
        const list = data?.data?.all_addons ?? data?.all_addons ?? data?.data ?? [];
        setAddons(Array.isArray(list) ? list : []);
      })
      .catch(() => setAddons([]));
  }, [provider.slug, primaryServiceId]);

  // Total slot span = sum(durations) + sum(buffers) so slots match hold/booking block. For group booking use max across primary and all participants.
  const slotParams = (() => {
    const offeringsList = offerings as Array<{ id: string; duration_minutes?: number; buffer_minutes?: number }>;
    const spanForOfferingIds = (ids: string[]) => {
      let total = 0;
      for (let i = 0; i < ids.length; i++) {
        const off = offeringsList.find((o) => o.id === ids[i]);
        const dur = off?.duration_minutes ?? 60;
        const buf = off?.buffer_minutes ?? 15;
        total += dur + buf;
      }
      return total;
    };
    const primaryIds = bookingData.selectedServices.map((s) => s.offering_id || (s as any).id).filter(Boolean);
    const primarySpan = primaryIds.length
      ? spanForOfferingIds(primaryIds)
      : bookingData.selectedServices.reduce((s, e) => s + ((e as any).duration_minutes ?? 60), 0) + 15;
    if (!bookingData.isGroupBooking || !bookingData.groupParticipants?.length) {
      const durationMinutes = primaryIds.length
        ? primarySpan - ((offeringsList.find((o) => o.id === primaryIds[primaryIds.length - 1])?.buffer_minutes ?? 15))
        : primarySpan - 15;
      const bufferMinutesLast = primaryIds.length
        ? (offeringsList.find((o) => o.id === primaryIds[primaryIds.length - 1])?.buffer_minutes ?? 15)
        : 15;
      return { durationMinutes: durationMinutes || 60, bufferMinutes: bufferMinutesLast };
    }
    let maxSpan = primarySpan;
    for (const p of bookingData.groupParticipants) {
      const ids = p.service_ids ?? (p as any).serviceIds ?? [];
      if (ids.length) maxSpan = Math.max(maxSpan, spanForOfferingIds(ids));
    }
    return { durationMinutes: maxSpan || 60, bufferMinutes: 0 };
  })();

  useEffect(() => {
    if (step !== "schedule" || !bookingData.selectedDate || bookingData.selectedServices.length === 0) return;
    const staffId = bookingData.selectedStaff?.id === "any" ? "any" : bookingData.selectedStaff?.id ?? "any";
    const dateStr = bookingData.selectedDate.toISOString().split("T")[0];
    const { durationMinutes, bufferMinutes } = slotParams;
    const serviceId = bookingData.selectedServices[0].offering_id;
    setLoadingSlots(true);
    const url = `/api/public/providers/${provider.slug}/availability?date=${dateStr}&service_id=${serviceId}&staff_id=${staffId}&duration_minutes=${durationMinutes}&buffer_minutes=${bufferMinutes}&location_id=${bookingData.selectedLocation?.id ?? ""}&min_notice_minutes=${settings.min_notice_minutes}&max_advance_days=${settings.max_advance_days}`;
    fetcher
      .get<{ data: any[] }>(url)
      .then((res) => {
        const raw = (res as any)?.data?.slots ?? (res as any)?.data ?? res ?? [];
        const list = Array.isArray(raw) ? raw : [];
        setSlots(
          list.map((s: any) => ({
            start: s.start ?? s.time,
            end: s.end ?? s.start ?? s.time,
            staff_id: s.staff_id,
            is_available: s.is_available !== false,
          }))
        );
      })
      .catch(() => setSlots([]))
      .finally(() => setLoadingSlots(false));
  }, [
    step,
    bookingData.selectedDate,
    bookingData.selectedServices,
    bookingData.selectedStaff,
    bookingData.selectedLocation,
    provider.slug,
    settings.min_notice_minutes,
    settings.max_advance_days,
    slotParams.durationMinutes,
    slotParams.bufferMinutes,
  ]);

  const stepsOrder: BookingStep[] = (() => {
    const base: BookingStep[] = ["venue", "category", "services", "addons"];
    if (showGroupStep) base.push("group");
    if (showStaffStep) base.push("staff");
    base.push("schedule", "resources", "intake", "review");
    return base;
  })();

  const goBack = () => {
    const i = stepsOrder.indexOf(step);
    if (i > 0) setStep(stepsOrder[i - 1]);
  };

  const handleNextAvailable = async () => {
    const dateStr = (d: Date) => d.toISOString().split("T")[0];
    const staffId = bookingData.selectedStaff?.id === "any" ? "any" : bookingData.selectedStaff?.id ?? "any";
    const { durationMinutes, bufferMinutes } = slotParams;
    const serviceId = bookingData.selectedServices[0]?.offering_id;
    if (!serviceId) return;
    for (let offset = 0; offset < Math.min(14, settings.max_advance_days); offset++) {
      const d = new Date();
      d.setDate(d.getDate() + offset);
      const url = `/api/public/providers/${provider.slug}/availability?date=${dateStr(d)}&service_id=${serviceId}&staff_id=${staffId}&duration_minutes=${durationMinutes}&buffer_minutes=${bufferMinutes}&location_id=${bookingData.selectedLocation?.id ?? ""}&min_notice_minutes=${settings.min_notice_minutes}&max_advance_days=${settings.max_advance_days}`;
      const res = await fetcher.get<{ data: any[] }>(url).catch(() => ({ data: [] }));
      const raw = (res as any)?.data?.slots ?? (res as any)?.data ?? [];
      const list = Array.isArray(raw) ? raw : [];
      const available = list.filter((s: any) => s.is_available !== false);
      if (available.length > 0) {
        setBookingData((prev) => ({ ...prev, selectedDate: d, selectedSlot: null }));
        setSlots(
          list.map((s: any) => ({
            start: s.start ?? s.time,
            end: s.end ?? s.start ?? s.time,
            staff_id: s.staff_id,
            is_available: s.is_available !== false,
          }))
        );
        setStep("schedule");
        return;
      }
    }
    toast.error("No available slots in the next two weeks");
  };

  const handleConfirm = async () => {
    if (bookingData.selectedServices.length === 0 || !bookingData.selectedSlot) return;
    if (bookingData.policyAccepted !== true) {
      toast.error("Please accept the cancellation policy to continue.");
      return;
    }
    // "any" or synthetic "provider-*" => send null so backend assigns staff
    const rawStaffId = bookingData.selectedSlot.staff_id ?? (bookingData.selectedStaff?.id !== "any" ? bookingData.selectedStaff?.id : null);
    const staffIdForHold =
      !rawStaffId || rawStaffId === "any" || String(rawStaffId).startsWith("provider-") ? null : rawStaffId;
    if (bookingData.venueType === "at_home" && (!bookingData.atHomeAddress.line1?.trim() || !bookingData.atHomeAddress.city?.trim())) {
      toast.error("Please enter your address for at-home booking");
      return;
    }

    setCreatingHold(true);
    try {
      let addressPayload: {
        line1: string;
        city: string;
        country: string;
        line2?: string;
        state?: string;
        postal_code?: string;
        latitude?: number;
        longitude?: number;
      } | null = null;

      if (
        bookingData.venueType === "at_home" &&
        bookingData.atHomeAddress.line1?.trim() &&
        bookingData.atHomeAddress.city?.trim()
      ) {
        addressPayload = {
          line1: bookingData.atHomeAddress.line1.trim(),
          city: bookingData.atHomeAddress.city.trim(),
          country: bookingData.atHomeAddress.country || "ZA",
          line2: bookingData.atHomeAddress.line2,
          state: bookingData.atHomeAddress.state,
          postal_code: bookingData.atHomeAddress.postal_code,
        };
        const hasCoords =
          typeof bookingData.atHomeAddress.latitude === "number" &&
          typeof bookingData.atHomeAddress.longitude === "number" &&
          Math.abs(bookingData.atHomeAddress.latitude) > 0.0001 &&
          Math.abs(bookingData.atHomeAddress.longitude) > 0.0001;
        if (hasCoords) {
          addressPayload.latitude = bookingData.atHomeAddress.latitude!;
          addressPayload.longitude = bookingData.atHomeAddress.longitude!;
        } else {
          try {
            const query = [bookingData.atHomeAddress.line1.trim(), bookingData.atHomeAddress.city.trim(), bookingData.atHomeAddress.country || "ZA"].filter(Boolean).join(", ");
            const geocodeRes = await fetcher.post<{ data: Array<{ center: [number, number] }> }>("/api/mapbox/geocode", { query, limit: 1 });
            const results = (geocodeRes as any)?.data ?? [];
            if (results.length > 0 && results[0].center) {
              const [lng, lat] = results[0].center;
              addressPayload.latitude = lat;
              addressPayload.longitude = lng;
            }
          } catch {
            // Proceed without coords; travel fee will be 0
          }
        }
      }

      const services = bookingData.selectedServices.map((s) => ({
        offering_id: s.offering_id,
        staff_id: staffIdForHold,
      }));
      const res = await fetcher.post<{ data: { hold_id: string } }>("/api/public/booking-holds", {
        provider_id: provider.id,
        staff_id: staffIdForHold,
        services,
        start_at: bookingData.selectedSlot.start,
        end_at: bookingData.selectedSlot.end,
        location_type: bookingData.venueType,
        location_id: bookingData.venueType === "at_salon" ? bookingData.selectedLocation?.id ?? null : null,
        address: addressPayload,
        resource_ids: bookingData.selectedResourceIds?.length ? bookingData.selectedResourceIds : undefined,
      });
      const id = (res as any)?.data?.hold_id ?? (res as any)?.hold_id;
      if (id) {
        setHoldId(id);
        try {
          sessionStorage.setItem("beautonomi_booking_client", JSON.stringify(bookingData.client));
          sessionStorage.setItem("beautonomi_booking_addons", JSON.stringify(bookingData.selectedAddonIds));
          sessionStorage.setItem("beautonomi_booking_special_requests", bookingData.client.specialRequests || "");
          sessionStorage.setItem("beautonomi_booking_provider_form_responses", JSON.stringify(bookingData.provider_form_responses ?? {}));
          sessionStorage.setItem("beautonomi_booking_custom_field_values", JSON.stringify(bookingData.custom_field_values ?? {}));
          if (bookingData.isGroupBooking && bookingData.groupParticipants?.length) {
            sessionStorage.setItem(
              "beautonomi_booking_group",
              JSON.stringify({
                isGroupBooking: true,
                groupParticipants: bookingData.groupParticipants.map((p) => ({
                  name: p.name,
                  email: p.email ?? null,
                  phone: p.phone ?? null,
                  service_ids: p.service_ids,
                  notes: p.notes ?? null,
                })),
              })
            );
          } else {
            sessionStorage.removeItem("beautonomi_booking_group");
          }
        } catch {}
        if (authBeforeSlots && !user) {
          setPreAuthGateOpen(true);
        } else {
          setGateOpen(true);
        }
      } else {
        toast.error("Failed to secure slot");
      }
    } catch (e) {
      toast.error(e instanceof FetchError ? e.message : "Failed to secure slot");
    } finally {
      setCreatingHold(false);
    }
  };

  const handleAuthComplete = () => {
    setGateOpen(false);
    setPreAuthGateOpen(false);
    if (holdId) router.push(`/book/continue?hold_id=${holdId}`);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center" style={{ backgroundColor: BOOKING_BG }}>
        <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
      </div>
    );
  }

  const summarySteps: BookingStep[] = ["services", "addons", "staff", "schedule", "resources", "intake"];
  const showSummaryPill = summarySteps.includes(step) && bookingData.selectedServices.length > 0;

  const content = (
    <>
      <BookingNav
        currentStep={step}
        onBack={step !== "venue" ? goBack : undefined}
        showStepper={true}
        embed={embed}
        steps={stepsOrder}
        providerName={provider.business_name}
        platformName={PLATFORM_NAME}
        accentColor={BOOKING_ACCENT}
      />

      <main className={embed ? "mx-auto max-w-md px-4 py-6" : "flex-1 overflow-y-auto px-6 py-8 pb-8 min-h-0"}>
        {step === "category" && (
          <StepCategory
            categories={categories}
            selectedCategory={bookingData.selectedCategory}
            onSelectCategory={(category) => updateData({ selectedCategory: category })}
            onNext={() => setStep("services")}
          />
        )}
        {step === "venue" && (
          <StepVenue
            data={bookingData}
            locations={locations.filter((l) => (l.location_type || "salon") === "salon")}
            onChange={updateData}
            onNext={() => setStep("category")}
            providerName={provider.business_name}
          />
        )}

        {step === "services" && (
          <StepServices
            data={bookingData}
            offerings={offeringsForStep}
            categoryName={bookingData.selectedCategory?.name}
            packages={packages}
            variantsByServiceId={variantsByServiceId}
            onSelectPackage={(pkg) => {
              if (!pkg) {
                setBookingData((prev) => ({ ...prev, selectedPackage: null, selectedServices: [] }));
                return;
              }
              const services = (pkg.services ?? (pkg as any).items?.filter((x: any) => x.type === "service") ?? []).map(
                (s: any) => ({
                  offering_id: s.id,
                  title: s.title,
                  duration_minutes: s.duration_minutes ?? 60,
                  price: 0,
                  currency: pkg.currency,
                })
              );
              const totalDuration = services.reduce((a: number, b: BookingServiceEntry) => a + b.duration_minutes, 0);
              setBookingData((prev) => ({
                ...prev,
                selectedPackage: pkg,
                selectedServices: services,
                servicesSubtotal: pkg.price,
                totalDurationMinutes: totalDuration,
              }));
            }}
            onSelectService={(entries) => {
              setBookingData((prev) => ({
                ...prev,
                selectedPackage: null,
                selectedServices: entries,
                servicesSubtotal: entries.reduce((s, e) => s + e.price, 0),
                totalDurationMinutes: entries.reduce((s, e) => s + e.duration_minutes, 0),
              }));
            }}
            onNext={() => setStep("addons")}
            isAtHome={bookingData.venueType === "at_home"}
          />
        )}

        {step === "addons" && (
          <StepAddons
            data={bookingData}
            addons={addons}
            onToggleAddon={(addonId, _price) => {
              setBookingData((prev) => {
                const ids = prev.selectedAddonIds.includes(addonId)
                  ? prev.selectedAddonIds.filter((id) => id !== addonId)
                  : [...prev.selectedAddonIds, addonId];
                const addonsSubtotal = ids.reduce((sum, id) => {
                  const a = addons.find((x) => x.id === id);
                  return sum + (a ? a.price : 0);
                }, 0);
                return { ...prev, selectedAddonIds: ids, addonsSubtotal };
              });
            }}
            onNext={() => (showGroupStep ? setStep("group") : showStaffStep ? setStep("staff") : setStep("schedule"))}
          />
        )}

        {step === "group" && (
          <StepGroupParticipants
            data={bookingData}
            offerings={offeringsForStep}
            maxGroupSize={groupBookingSettings.maxGroupSize}
            onToggleGroup={(isGroup) =>
              setBookingData((prev) => ({
                ...prev,
                isGroupBooking: isGroup,
                groupParticipants: isGroup ? prev.groupParticipants ?? [] : undefined,
              }))
            }
            onUpdateParticipants={(participants) =>
              setBookingData((prev) => ({ ...prev, groupParticipants: participants }))
            }
            onNext={() => (showStaffStep ? setStep("staff") : setStep("schedule"))}
          />
        )}

        {step === "staff" && (
          <StepStaff
            data={bookingData}
            staff={staff}
            onSelectStaff={(s) => updateData({ selectedStaff: s })}
            onNext={() => setStep("schedule")}
          />
        )}

        {step === "schedule" && (
          <StepSchedule
            data={bookingData}
            slots={slots}
            loadingSlots={loadingSlots}
            selectedDate={bookingData.selectedDate}
            onSelectDate={(date) => updateData({ selectedDate: date, selectedSlot: null })}
            onSelectSlot={(slot) => updateData({ selectedSlot: slot })}
            onNextAvailable={handleNextAvailable}
            onNext={() => setStep("resources")}
            maxAdvanceDays={settings.max_advance_days}
            providerId={provider.id}
            serviceId={bookingData.selectedServices[0]?.offering_id ?? null}
            waitlistEnabled={settings.allow_online_waitlist !== false}
          />
        )}

        {step === "resources" && (
          <div className="space-y-6">
            <ResourceSelection
              providerId={provider.slug}
              serviceIds={bookingData.selectedServices.map((s) => s.offering_id)}
              selectedDate={bookingData.selectedDate}
              selectedTimeSlot={bookingData.selectedSlot?.start ?? null}
              selectedResources={bookingData.selectedResourceIds}
              onResourceChange={(ids) => setBookingData((prev) => ({ ...prev, selectedResourceIds: ids }))}
              durationMinutes={bookingData.totalDurationMinutes || 60}
            />
            <div className="flex justify-end">
              <button
                type="button"
                onClick={() => setStep("intake")}
                className="rounded-xl px-6 py-3 font-semibold text-white min-h-[48px] min-w-[120px] touch-manipulation"
                style={{ backgroundColor: BOOKING_ACCENT }}
              >
                Continue
              </button>
            </div>
          </div>
        )}

        {step === "intake" && (
          <StepIntake
            data={bookingData}
            providerForms={providerForms}
            bookingCustomDefinitions={bookingCustomDefinitions}
            onChange={(client) =>
              setBookingData((prev) => ({ ...prev, client: { ...prev.client, ...client } }))
            }
            onProviderFormResponsesChange={(responses) =>
              setBookingData((prev) => ({ ...prev, provider_form_responses: responses }))
            }
            onCustomFieldValuesChange={(values) =>
              setBookingData((prev) => ({ ...prev, custom_field_values: values }))
            }
            onNext={() => setStep("review")}
          />
        )}

        {step === "review" && (
          <StepReview
            data={bookingData}
            providerName={provider.business_name}
            cancellationPolicy={cancellationPolicy}
            paymentSettings={{
              deposit_required: settings.deposit_required,
              allow_pay_in_person: settings.allow_pay_in_person,
              deposit_amount: settings.deposit_amount,
              deposit_percent: settings.deposit_percent,
            }}
            onPolicyAcceptedChange={(accepted) =>
              setBookingData((prev) => ({ ...prev, policyAccepted: accepted }))
            }
            onConfirm={handleConfirm}
            isCreatingHold={creatingHold}
          />
        )}
      </main>

      {/* Bottom summary bar: takes layout space so it never covers the Continue button */}
      {!embed && (
        <div
          className="flex-shrink-0 flex items-center justify-between gap-4 px-6 py-4 safe-area-pb min-h-[72px]"
          style={{
            background: BOOKING_GLASS_BG,
            backdropFilter: "blur(16px) saturate(180%)",
            WebkitBackdropFilter: "blur(16px) saturate(180%)",
            borderTop: `1px solid ${BOOKING_EDGE}`,
          }}
        >
          <div className="flex items-center gap-2 opacity-50">
            <span
              className="text-[10px] font-black uppercase tracking-widest"
              style={{ color: BOOKING_TEXT_SECONDARY }}
            >
              {PLATFORM_NAME}
            </span>
          </div>
          {showSummaryPill && (
            <button
              type="button"
              onClick={() => setStep("review")}
              className="rounded-2xl px-5 py-3 text-xs font-bold flex items-center gap-2 touch-manipulation min-h-[44px] transition-transform duration-200 active:scale-[0.98]"
              style={{
                backgroundColor: BOOKING_TEXT_PRIMARY,
                color: "#fff",
                boxShadow: BOOKING_SHADOW_CARD,
                border: `1px solid ${BOOKING_EDGE}`,
              }}
            >
              Summary
              <span className="opacity-80">
                {formatCurrency(bookingData.servicesSubtotal + bookingData.addonsSubtotal, bookingData.currency)}
              </span>
              <ChevronRight size={14} className="opacity-70" />
            </button>
          )}
        </div>
      )}

      {embed && stepsOrder.indexOf(step) >= 0 && step !== "review" && (
        <footer className="fixed bottom-0 left-0 right-0 z-30 border-t border-gray-200/80 bg-white/95 backdrop-blur-md p-4">
          <button
            type="button"
            onClick={() => setStep("review")}
            className="w-full rounded-xl h-12 font-medium text-gray-800 bg-gray-100 hover:bg-gray-200 transition-colors flex items-center justify-center gap-2 touch-manipulation"
          >
            <span>Summary</span>
            <span className="text-sm text-gray-500">
              {formatCurrency(bookingData.servicesSubtotal + bookingData.addonsSubtotal, bookingData.currency)} ┬╖ {bookingData.selectedServices.length} {bookingData.selectedServices.length === 1 ? "service" : "services"}
            </span>
          </button>
        </footer>
      )}

      <BeautonomiGateModal
        holdId={holdId ?? ""}
        open={gateOpen || preAuthGateOpen}
        onAuthComplete={handleAuthComplete}
        onClose={() => {
          setGateOpen(false);
          setPreAuthGateOpen(false);
        }}
        redirectUrl={
          preAuthGateOpen
            ? `${typeof window !== "undefined" ? window.location.origin : ""}/book/${provider.slug}?auth_return=calendar`
            : undefined
        }
      />
    </>
  );

  if (embed) {
    return (
      <div className="min-h-screen pb-8" style={{ backgroundColor: BOOKING_BG }}>
        {content}
      </div>
    );
  }

  return (
    <div
      className="min-h-screen flex justify-center items-start min-[640px]:items-center min-[640px]:py-8 antialiased"
      style={{ backgroundColor: BOOKING_BG }}
    >
      <div
        className="w-full max-w-[430px] min-h-screen min-[640px]:h-[90vh] min-[640px]:min-h-0 min-[640px]:max-h-[90vh] overflow-hidden flex flex-col relative min-[640px]:rounded-[3rem]"
        style={{
          background: BOOKING_GLASS_BG,
          backdropFilter: "blur(16px) saturate(180%)",
          WebkitBackdropFilter: "blur(16px) saturate(180%)",
          boxShadow: BOOKING_SHADOW_MAIN,
          border: `1px solid ${BOOKING_EDGE}`,
          color: "#222222",
        }}
      >
        {content}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Loader2, Calendar, X, ChevronDown, ChevronUp } from "lucide-react";
import { cn } from "@/lib/utils";
import type { BookingData } from "../../types/booking-engine";
import { normalizePhoneToE164, DEFAULT_PHONE_COUNTRY_CODE } from "@/lib/phone";
import {
  BOOKING_ACCENT,
  BOOKING_WAITLIST_BG,
  BOOKING_WAITLIST_TEXT,
  BOOKING_BORDER,
  BOOKING_EDGE,
  BOOKING_GLASS_BG,
  BOOKING_SHADOW_CARD,
  BOOKING_RADIUS_CARD,
  BOOKING_RADIUS_BUTTON,
  BOOKING_RADIUS_PILL,
  BOOKING_TEXT_PRIMARY,
  BOOKING_TEXT_SECONDARY,
  MIN_TAP,
  BOOKING_ACTIVE_SCALE,
} from "../../constants";

const WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function getSlotPeriod(start: string): "morning" | "afternoon" | "evening" {
  const hour = new Date(start).getHours();
  if (hour < 12) return "morning";
  if (hour < 17) return "afternoon";
  return "evening";
}

function isoToHHMM(iso: string): string {
  const d = new Date(iso);
  const h = d.getHours();
  const m = d.getMinutes();
  return `${h.toString().padStart(2, "0")}:${m.toString().padStart(2, "0")}`;
}

function isUuid(s: string | undefined): boolean {
  if (!s || typeof s !== "string") return false;
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s);
}

export type ScheduleSlot = { start: string; end: string; staff_id?: string; is_available?: boolean };

interface StepScheduleProps {
  data: BookingData;
  slots: ScheduleSlot[];
  loadingSlots: boolean;
  selectedDate: Date | null;
  onSelectDate: (date: Date) => void;
  onSelectSlot: (slot: ScheduleSlot) => void;
  onNextAvailable: () => void;
  onNext: () => void;
  maxAdvanceDays: number;
  providerId?: string;
  serviceId?: string | null;
  /** When false, unavailable slots are shown grayed out but without "Join Waitlist" */
  waitlistEnabled?: boolean;
}

export function StepSchedule({
  data,
  slots,
  loadingSlots,
  selectedDate,
  onSelectDate,
  onSelectSlot,
  onNextAvailable,
  onNext,
  maxAdvanceDays,
  providerId = "",
  serviceId = null,
  waitlistEnabled = true,
}: StepScheduleProps) {
  const router = useRouter();
  const [showMonthCalendar, setShowMonthCalendar] = useState(false);
  const [waitlistSlot, setWaitlistSlot] = useState<ScheduleSlot | null>(null);
  const [waitlistSubmitting, setWaitlistSubmitting] = useState(false);
  const [waitlistForm, setWaitlistForm] = useState({ name: "", email: "", phone: "" });
  const [expandedPeriods, setExpandedPeriods] = useState<Set<string>>(new Set(["MORNING"]));
  const togglePeriod = (label: string) => {
    setExpandedPeriods((prev) => {
      const next = new Set(prev);
      if (next.has(label)) next.delete(label);
      else next.add(label);
      return next;
    });
  };

  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const days: Date[] = [];
  const daysToShow = Math.min(maxAdvanceDays, 21);
  for (let i = 0; i < daysToShow; i++) {
    const d = new Date(today);
    d.setDate(today.getDate() + i);
    days.push(d);
  }

  const formatDay = (d: Date) => d.getDate().toString();
  const formatDayShort = (d: Date) => WEEKDAYS[d.getDay()].slice(0, 2);
  const formatSlot = (start: string) =>
    new Date(start).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  const hasSelection = data.selectedDate != null && data.selectedSlot != null;

  const availableSlots = slots.filter((s) => s.is_available !== false);
  const morningSlots = slots.filter((s) => getSlotPeriod(s.start) === "morning");
  const afternoonSlots = slots.filter((s) => getSlotPeriod(s.start) === "afternoon");
  const eveningSlots = slots.filter((s) => getSlotPeriod(s.start) === "evening");
  const periodGroups = [
    { label: "MORNING", slots: morningSlots },
    { label: "AFTERNOON", slots: afternoonSlots },
    { label: "EVENING", slots: eveningSlots },
  ];

  const timezoneLabel =
    typeof Intl !== "undefined"
      ? new Date().toLocaleTimeString("en-ZA", { timeZoneName: "short" }).split(" ").pop() || "SAST"
      : "SAST";

  const cardStyle = {
    background: BOOKING_GLASS_BG,
    backdropFilter: "blur(16px) saturate(180%)",
    WebkitBackdropFilter: "blur(16px) saturate(180%)",
    border: `1px solid ${BOOKING_EDGE}`,
    borderRadius: BOOKING_RADIUS_CARD,
    boxShadow: BOOKING_SHADOW_CARD,
  };

  const handleJoinWaitlist = async () => {
    if (!waitlistSlot || !providerId || !waitlistForm.name.trim()) return;
    setWaitlistSubmitting(true);
    try {
      const rawPhone = waitlistForm.phone.trim();
      const phoneE164 = rawPhone
        ? normalizePhoneToE164(rawPhone, DEFAULT_PHONE_COUNTRY_CODE) || normalizePhoneToE164(rawPhone) || rawPhone
        : undefined;
      const body: Record<string, any> = {
        provider_id: providerId,
        customer_name: waitlistForm.name.trim(),
        customer_email: waitlistForm.email.trim() || undefined,
        customer_phone: phoneE164,
        preferred_date: selectedDate?.toISOString().split("T")[0],
        preferred_time_start: isoToHHMM(waitlistSlot.start),
        preferred_time_end: isoToHHMM(waitlistSlot.end),
      };
      if (serviceId && isUuid(serviceId)) body.service_id = serviceId;
      if (waitlistSlot.staff_id && isUuid(waitlistSlot.staff_id)) body.staff_id = waitlistSlot.staff_id;

      const res = await fetch("/api/public/waitlist", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      const errData = await res.json().catch(() => ({}));
      if (!res.ok) {
        const code = errData?.error?.code;
        const msg =
          res.status === 403 && (code === "FEATURE_DISABLED" || code === "NOT_FOUND")
            ? "This provider doesn't offer waitlist."
            : errData?.error?.message || "Could not join waitlist.";
        throw new Error(msg);
      }
      router.push("/checkout/success?waitlist=1");
      return;
    } catch (e) {
      alert(e instanceof Error ? e.message : "Could not join waitlist");
    } finally {
      setWaitlistSubmitting(false);
    }
  };

  const monthForCalendar = selectedDate
    ? new Date(selectedDate.getFullYear(), selectedDate.getMonth(), 1)
    : new Date(today.getFullYear(), today.getMonth(), 1);
  const year = monthForCalendar.getFullYear();
  const month = monthForCalendar.getMonth();
  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month + 1, 0);
  const startPad = firstDay.getDay();
  const daysInMonth = lastDay.getDate();
  const monthDays: (Date | null)[] = [];
  for (let i = 0; i < startPad; i++) monthDays.push(null);
  for (let d = 1; d <= daysInMonth; d++) monthDays.push(new Date(year, month, d));

  const availableLabelColor = "#16a34a";

  return (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div className="text-left">
        <h2 className="text-2xl font-semibold tracking-tight" style={{ color: BOOKING_TEXT_PRIMARY }}>
          Find an Opening
        </h2>
        <p className="mt-1.5 text-sm" style={{ color: BOOKING_TEXT_SECONDARY }}>
          All times shown in your local timezone.
        </p>
      </div>

      <button
        type="button"
        onClick={onNextAvailable}
        className={cn(
          "w-full rounded-2xl border-2 border-dashed py-3.5 font-semibold transition-all touch-manipulation flex items-center justify-center gap-2",
          MIN_TAP,
          BOOKING_ACTIVE_SCALE
        )}
        style={{
          color: BOOKING_ACCENT,
          borderColor: BOOKING_ACCENT,
          backgroundColor: BOOKING_WAITLIST_BG,
        }}
      >
        Next available
      </button>

      <div>
        <div className="flex items-center justify-between mb-2">
          <p className="text-sm font-medium" style={{ color: BOOKING_TEXT_PRIMARY }}>
            Date
          </p>
          <button
            type="button"
            onClick={() => setShowMonthCalendar(true)}
            className="text-xs flex items-center gap-1 min-h-[44px] min-w-[44px] justify-end touch-manipulation"
            style={{ color: BOOKING_ACCENT }}
          >
            <Calendar className="h-3.5 w-3.5" />
            Full month
          </button>
        </div>
        <div
          className="flex gap-2 overflow-x-auto pb-2 snap-x snap-mandatory"
          style={{ scrollbarWidth: "none", msOverflowStyle: "none", WebkitOverflowScrolling: "touch" }}
        >
          {days.map((d) => {
            const isSelected = selectedDate?.toDateString() === d.toDateString();
            const isToday = d.toDateString() === today.toDateString();
            return (
              <button
                key={d.toISOString()}
                type="button"
                onClick={() => onSelectDate(d)}
                className={cn(
                  "shrink-0 snap-center rounded-2xl min-w-[64px] py-3 px-3 transition-all touch-manipulation flex flex-col items-center justify-center",
                  MIN_TAP,
                  BOOKING_ACTIVE_SCALE
                )}
                style={
                  isSelected
                    ? {
                        background: BOOKING_GLASS_BG,
                        backdropFilter: "blur(16px) saturate(180%)",
                        border: `2px solid ${BOOKING_ACCENT}`,
                        color: BOOKING_ACCENT,
                        boxShadow: BOOKING_SHADOW_CARD,
                      }
                    : {
                        background: isToday ? "rgba(0,0,0,0.06)" : "rgba(255,255,255,0.7)",
                        border: `1px solid ${BOOKING_EDGE}`,
                        color: BOOKING_TEXT_PRIMARY,
                      }
                }
              >
                <span className="text-[10px] font-medium uppercase" style={{ opacity: 0.8 }}>
                  {formatDayShort(d)}
                </span>
                <span className="text-lg font-semibold mt-0.5">{formatDay(d)}</span>
              </button>
            );
          })}
        </div>
        <p className="text-xs mt-2" style={{ color: BOOKING_TEXT_SECONDARY }}>
          Times shown in your local timezone ({timezoneLabel})
        </p>
      </div>

      {showMonthCalendar && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4"
          style={{ backgroundColor: "rgba(0,0,0,0.4)" }}
          onClick={() => setShowMonthCalendar(false)}
        >
          <div
            className="w-full max-w-sm rounded-3xl p-5 shadow-xl"
            style={cardStyle}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between mb-4">
              <span className="font-semibold" style={{ color: BOOKING_TEXT_PRIMARY }}>
                {MONTHS[month]} {year}
              </span>
              <button
                type="button"
                onClick={() => setShowMonthCalendar(false)}
                className="p-2 rounded-full touch-manipulation"
                style={{ color: BOOKING_TEXT_SECONDARY }}
                aria-label="Close"
              >
                <X className="h-5 w-5" />
              </button>
            </div>
            <div className="grid grid-cols-7 gap-1">
              {WEEKDAYS.map((w) => (
                <div key={w} className="text-center text-xs py-1" style={{ color: BOOKING_TEXT_SECONDARY }}>
                  {w}
                </div>
              ))}
              {monthDays.map((d, i) => (
                <div key={i} className="flex items-center justify-center">
                  {d ? (
                    <button
                      type="button"
                      onClick={() => {
                        onSelectDate(d);
                        setShowMonthCalendar(false);
                      }}
                      className={cn(
                        "w-10 h-10 rounded-xl text-sm font-medium touch-manipulation",
                        selectedDate?.toDateString() === d.toDateString()
                          ? "text-white"
                          : d.toDateString() === today.toDateString()
                          ? "bg-gray-200"
                          : "hover:bg-black/5"
                      )}
                      style={{
                        backgroundColor:
                          selectedDate?.toDateString() === d.toDateString() ? BOOKING_ACCENT : undefined,
                        color:
                          selectedDate?.toDateString() === d.toDateString()
                            ? "#fff"
                            : d < today
                            ? BOOKING_TEXT_SECONDARY
                            : BOOKING_TEXT_PRIMARY,
                      }}
                    >
                      {d.getDate()}
                    </button>
                  ) : null}
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {waitlistSlot && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4"
          style={{ backgroundColor: "rgba(0,0,0,0.4)" }}
          onClick={() => !waitlistSubmitting && setWaitlistSlot(null)}
        >
          <div
            className="w-full max-w-sm rounded-3xl p-5 shadow-xl space-y-4"
            style={cardStyle}
            onClick={(e) => e.stopPropagation()}
          >
            <h3 className="font-semibold" style={{ color: BOOKING_TEXT_PRIMARY }}>
              Join waitlist
            </h3>
            <p className="text-sm" style={{ color: BOOKING_TEXT_SECONDARY }}>
              We'll notify you when {formatSlot(waitlistSlot.start)} becomes available.
            </p>
            <input
              type="text"
              placeholder="Your name *"
              value={waitlistForm.name}
              onChange={(e) => setWaitlistForm((f) => ({ ...f, name: e.target.value }))}
              className="w-full rounded-xl border px-4 py-3 text-sm min-h-[44px]"
              style={{ borderColor: BOOKING_BORDER }}
            />
            <input
              type="email"
              placeholder="Email"
              value={waitlistForm.email}
              onChange={(e) => setWaitlistForm((f) => ({ ...f, email: e.target.value }))}
              className="w-full rounded-xl border px-4 py-3 text-sm min-h-[44px]"
              style={{ borderColor: BOOKING_BORDER }}
            />
            <input
              type="tel"
              placeholder="Phone"
              value={waitlistForm.phone}
              onChange={(e) => setWaitlistForm((f) => ({ ...f, phone: e.target.value }))}
              className="w-full rounded-xl border px-4 py-3 text-sm min-h-[44px]"
              style={{ borderColor: BOOKING_BORDER }}
            />
            <div className="flex gap-2">
              <button
                type="button"
                onClick={() => setWaitlistSlot(null)}
                disabled={waitlistSubmitting}
                className="flex-1 rounded-xl py-3 font-medium border min-h-[44px]"
                style={{ borderColor: BOOKING_BORDER, color: BOOKING_TEXT_PRIMARY }}
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={handleJoinWaitlist}
                disabled={waitlistSubmitting || !waitlistForm.name.trim()}
                className="flex-1 rounded-xl py-3 font-semibold text-white min-h-[44px] disabled:opacity-50"
                style={{ backgroundColor: BOOKING_ACCENT }}
              >
                {waitlistSubmitting ? "Joining..." : "Join waitlist"}
              </button>
            </div>
          </div>
        </div>
      )}

      {selectedDate && (
        <div className="p-5 rounded-3xl" style={cardStyle}>
          <p className="text-sm font-medium mb-3" style={{ color: BOOKING_TEXT_PRIMARY }}>
            Time
          </p>
          {loadingSlots ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="h-8 w-8 animate-spin" style={{ color: BOOKING_TEXT_SECONDARY }} />
            </div>
          ) : slots.length === 0 ? (
            <p
              className="text-sm py-4 text-center rounded-2xl"
              style={{ backgroundColor: "rgba(0,0,0,0.04)", color: BOOKING_TEXT_SECONDARY }}
            >
              No slots available this day. Try another date.
            </p>
          ) : (
            <div className="space-y-2">
              {periodGroups.map(
                (group) =>
                  group.slots.length > 0 && (
                    <div key={group.label} className="rounded-xl border overflow-hidden" style={{ borderColor: BOOKING_BORDER }}>
                      <button
                        type="button"
                        onClick={() => togglePeriod(group.label)}
                        className={cn(
                          "w-full flex items-center justify-between px-4 py-3 text-left touch-manipulation",
                          MIN_TAP,
                          BOOKING_ACTIVE_SCALE
                        )}
                        style={{ backgroundColor: "rgba(0,0,0,0.03)", color: BOOKING_TEXT_PRIMARY }}
                      >
                        <span className="text-xs font-medium uppercase tracking-wider">
                          {group.label}
                        </span>
                        {expandedPeriods.has(group.label) ? (
                          <ChevronUp className="h-4 w-4" style={{ color: BOOKING_TEXT_SECONDARY }} />
                        ) : (
                          <ChevronDown className="h-4 w-4" style={{ color: BOOKING_TEXT_SECONDARY }} />
                        )}
                      </button>
                      {expandedPeriods.has(group.label) && (
                      <div className="px-4 pb-3 pt-1 flex flex-wrap gap-2">
                        {group.slots.map((slot, i) => {
                          const isAvailable = slot.is_available !== false;
                          const isSelected =
                            isAvailable && data.selectedSlot?.start === slot.start;
                          if (isAvailable) {
                            return (
                              <button
                                key={i}
                                type="button"
                                onClick={() => onSelectSlot(slot)}
                                className={cn(
                                  "rounded-xl py-3 px-4 text-sm font-medium transition-all touch-manipulation min-w-[80px] flex flex-col items-center gap-0.5",
                                  MIN_TAP,
                                  BOOKING_ACTIVE_SCALE
                                )}
                                style={{
                                  borderRadius: BOOKING_RADIUS_PILL,
                                  backgroundColor: isSelected ? BOOKING_ACCENT : "rgba(0,0,0,0.04)",
                                  color: isSelected ? "#fff" : BOOKING_TEXT_PRIMARY,
                                  border: isSelected ? "none" : `1px solid ${BOOKING_BORDER}`,
                                }}
                              >
                                <span>{formatSlot(slot.start)}</span>
                                <span className="text-[10px] font-semibold" style={{ color: isSelected ? "#fff" : availableLabelColor }}>
                                  Available
                                </span>
                              </button>
                            );
                          }
                          return (
                            <button
                              key={i}
                              type="button"
                              onClick={() => waitlistEnabled && providerId && setWaitlistSlot(slot)}
                              disabled={!waitlistEnabled}
                              className={cn(
                                "rounded-xl py-3 px-4 text-sm font-medium transition-all touch-manipulation min-w-[80px] flex flex-col items-center gap-0.5",
                                MIN_TAP,
                                BOOKING_ACTIVE_SCALE
                              )}
                              style={{
                                borderRadius: BOOKING_RADIUS_PILL,
                                backgroundColor: "rgba(0,0,0,0.06)",
                                color: BOOKING_TEXT_SECONDARY,
                                border: `1px solid ${BOOKING_BORDER}`,
                              }}
                            >
                              <span>{formatSlot(slot.start)}</span>
                              {waitlistEnabled && (
                                <span
                                  className="text-[10px] font-semibold"
                                  style={{ color: BOOKING_WAITLIST_TEXT }}
                                >
                                  Join Waitlist
                                </span>
                              )}
                            </button>
                          );
                        })}
                      </div>
                      )}
                    </div>
                  )
              )}
            </div>
          )}
        </div>
      )}

      <button
        type="button"
        onClick={onNext}
        disabled={!hasSelection}
        className={cn(
          "w-full rounded-2xl h-12 font-semibold text-white transition-all touch-manipulation disabled:opacity-50 disabled:active:scale-100",
          MIN_TAP,
          BOOKING_ACTIVE_SCALE
        )}
        style={{
          backgroundColor: BOOKING_ACCENT,
          borderRadius: BOOKING_RADIUS_BUTTON,
          boxShadow: BOOKING_SHADOW_CARD,
        }}
      >
        Continue
      </button>
    </div>
  );
}

"use client";

import { Sparkles, Clock, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { formatCurrency } from "@/lib/utils";
import type {
  BookingData,
  ServiceOption,
  PackageOption,
  ServiceVariant,
  BookingServiceEntry,
} from "../../types/booking-engine";
import {
  BOOKING_ACCENT,
  BOOKING_WAITLIST_BG,
  BOOKING_BORDER,
  BOOKING_EDGE,
  BOOKING_SHADOW_CARD,
  BOOKING_RADIUS_CARD,
  BOOKING_RADIUS_BUTTON,
  BOOKING_RADIUS_PILL,
  BOOKING_TEXT_PRIMARY,
  BOOKING_TEXT_SECONDARY,
  MIN_TAP,
  BOOKING_ACTIVE_SCALE,
} from "../../constants";

const cardStyle = {
  background: "rgba(255,255,255,0.85)",
  backdropFilter: "blur(16px) saturate(180%)",
  WebkitBackdropFilter: "blur(16px) saturate(180%)",
  border: `1px solid ${BOOKING_EDGE}`,
  borderRadius: BOOKING_RADIUS_CARD,
  boxShadow: BOOKING_SHADOW_CARD,
};

interface StepServicesProps {
  data: BookingData;
  offerings: ServiceOption[];
  packages: PackageOption[];
  variantsByServiceId: Record<string, ServiceVariant[]>;
  onSelectPackage: (pkg: PackageOption | null) => void;
  onSelectService: (entries: BookingServiceEntry[]) => void;
  onNext: () => void;
  isAtHome: boolean;
  /** When set, shown as section title (e.g. "Hair Menu") */
  categoryName?: string | null;
}

export function StepServices({
  data,
  offerings,
  packages,
  variantsByServiceId,
  onSelectPackage,
  onSelectService,
  onNext,
  isAtHome,
  categoryName,
}: StepServicesProps) {
  const hasSelection =
    (data.selectedPackage != null && data.selectedServices.length > 0) ||
    (data.selectedPackage == null && data.selectedServices.length > 0);

  const baseServices = offerings.filter(
    (o) => !(o as any).parent_service_id && (o as any).service_type !== "addon"
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div className="text-left">
        <h2 className="text-2xl font-semibold tracking-tight" style={{ color: BOOKING_TEXT_PRIMARY }}>
          {categoryName ? `${categoryName} Menu` : "What would you like?"}
        </h2>
        <p className="mt-1.5 text-sm" style={{ color: BOOKING_TEXT_SECONDARY }}>
          {categoryName ? "Choose a service from this category" : "Choose a package or a single service"}
        </p>
      </div>

      {packages.length > 0 && (
        <div className="p-5 space-y-4 rounded-3xl" style={cardStyle}>
          <h3 className="text-sm font-medium flex items-center gap-2" style={{ color: BOOKING_TEXT_SECONDARY }}>
            <Sparkles className="h-4 w-4" style={{ color: BOOKING_ACCENT }} />
            Packages
          </h3>
          <div className="space-y-3">
            {packages.map((pkg, i) => {
              const isSelected = data.selectedPackage?.id === pkg.id;
              const discount = pkg.discount_percentage ?? 0;
              const hasSavings = discount > 0;
              return (
                <button
                  key={pkg.id}
                  type="button"
                  onClick={() => {
                    onSelectPackage(isSelected ? null : pkg);
                    if (isSelected) onSelectService([]);
                    else {
                      const items = pkg.services ?? pkg.items?.filter((x: any) => x.type === "service") ?? [];
                      const entries: BookingServiceEntry[] = items.map((item: any) => ({
                        offering_id: item.id,
                        title: item.title,
                        duration_minutes: item.duration_minutes ?? 60,
                        price: 0,
                        currency: pkg.currency,
                      }));
                      if (entries.length > 0) {
                        onSelectService(entries);
                      } else {
                        onSelectService([
                          {
                            offering_id: pkg.id as any,
                            title: pkg.name,
                            duration_minutes: 60,
                            price: pkg.price,
                            currency: pkg.currency,
                          },
                        ]);
                      }
                    }
                  }}
                  className={cn(
                    "w-full text-left rounded-2xl border-2 p-4 transition-all touch-manipulation relative overflow-hidden",
                    MIN_TAP,
                    BOOKING_ACTIVE_SCALE
                  )}
                  style={{
                    borderColor: isSelected ? BOOKING_ACCENT : BOOKING_BORDER,
                    backgroundColor: isSelected ? BOOKING_WAITLIST_BG : "rgba(0,0,0,0.02)",
                  }}
                >
                  {hasSavings && (
                    <span
                      className="absolute top-3 right-3 text-xs font-semibold px-2.5 py-1 rounded-full text-white"
                      style={{ backgroundColor: BOOKING_ACCENT }}
                    >
                      Save {discount}%
                    </span>
                  )}
                  <span className="font-semibold block" style={{ color: BOOKING_TEXT_PRIMARY }}>
                    {pkg.name}
                  </span>
                  {pkg.description && (
                    <p className="text-sm mt-1 line-clamp-2" style={{ color: BOOKING_TEXT_SECONDARY }}>
                      {pkg.description}
                    </p>
                  )}
                  <p className="text-sm mt-2" style={{ color: BOOKING_TEXT_SECONDARY }}>
                    {pkg.services?.length ?? pkg.items?.length ?? 0} included ┬╖{" "}
                    <strong style={{ color: BOOKING_ACCENT }}>{formatCurrency(pkg.price, pkg.currency)}</strong>
                  </p>
                </button>
              );
            })}
          </div>
        </div>
      )}

      <div className="p-5 space-y-4 rounded-3xl" style={cardStyle}>
        <h3 className="text-sm font-medium text-left" style={{ color: BOOKING_TEXT_SECONDARY }}>
          Services
        </h3>
        <div className="space-y-2">
          {baseServices.map((svc) => {
            const variants = variantsByServiceId[svc.id];
            const hasVariants = variants && variants.length > 0;
            const price =
              isAtHome && svc.at_home_price_adjustment
                ? svc.price + (svc.at_home_price_adjustment ?? 0)
                : svc.price;

            if (hasVariants) {
              return (
                <div
                  key={svc.id}
                  className="rounded-2xl border overflow-hidden"
                  style={{ borderColor: BOOKING_BORDER, backgroundColor: "rgba(0,0,0,0.02)" }}
                >
                  <div className="px-4 py-3 border-b" style={{ borderColor: BOOKING_EDGE }}>
                    <span className="font-medium" style={{ color: BOOKING_TEXT_PRIMARY }}>
                      {svc.title}
                    </span>
                  </div>
                  <div className="p-3 flex flex-wrap gap-2">
                    {variants.map((v) => {
                      const isSelected = data.selectedServices.some((e) => e.offering_id === v.id);
                      return (
                        <button
                          key={v.id}
                          type="button"
                          onClick={() => {
                            onSelectPackage(null);
                            const entry = {
                              offering_id: v.id,
                              title: v.title,
                              duration_minutes: v.duration,
                              price: v.price,
                              currency: v.currency,
                            };
                            onSelectService(
                              isSelected
                                ? data.selectedServices.filter((e) => e.offering_id !== v.id)
                                : [...data.selectedServices.filter((e) => e.offering_id !== svc.id), entry]
                            );
                          }}
                          className={cn(
                            "rounded-xl px-4 py-2.5 text-sm font-medium transition-all touch-manipulation min-h-[44px]",
                            BOOKING_ACTIVE_SCALE
                          )}
                          style={{
                            borderRadius: BOOKING_RADIUS_PILL,
                            backgroundColor: isSelected ? BOOKING_ACCENT : "rgba(0,0,0,0.06)",
                            color: isSelected ? "#fff" : BOOKING_TEXT_PRIMARY,
                          }}
                        >
                          {v.variant_name ?? v.title} ┬╖ {formatCurrency(v.price, v.currency)}
                        </button>
                      );
                    })}
                  </div>
                </div>
              );
            }

            const isSelected = data.selectedServices.some((e) => e.offering_id === svc.id);
            return (
              <button
                key={svc.id}
                type="button"
                onClick={() => {
                  onSelectPackage(null);
                  const entry = {
                    offering_id: svc.id,
                    title: svc.title,
                    duration_minutes: svc.duration_minutes,
                    price,
                    currency: svc.currency,
                  };
                  onSelectService(
                    isSelected
                      ? data.selectedServices.filter((e) => e.offering_id !== svc.id)
                      : [...data.selectedServices, entry]
                  );
                }}
                className={cn(
                  "w-full text-left rounded-2xl border-2 px-4 py-3.5 transition-all touch-manipulation flex items-center gap-3",
                  MIN_TAP,
                  BOOKING_ACTIVE_SCALE
                )}
                style={{
                  borderColor: isSelected ? BOOKING_ACCENT : BOOKING_BORDER,
                  backgroundColor: isSelected ? BOOKING_WAITLIST_BG : "rgba(0,0,0,0.02)",
                }}
              >
                <div className="flex-1 min-w-0">
                  <span className="font-medium block" style={{ color: BOOKING_TEXT_PRIMARY }}>
                    {svc.title}
                  </span>
                  <p className="text-sm mt-0.5 flex items-center gap-1.5" style={{ color: BOOKING_TEXT_SECONDARY }}>
                    <Clock className="h-3.5 w-3.5 shrink-0" />
                    {svc.duration_minutes} min
                  </p>
                </div>
                <span className="text-sm font-semibold shrink-0" style={{ color: BOOKING_TEXT_PRIMARY }}>
                  from {formatCurrency(price, svc.currency)}
                </span>
                <ChevronRight className="h-5 w-5 shrink-0" style={{ color: BOOKING_TEXT_SECONDARY }} />
              </button>
            );
          })}
        </div>
      </div>

      <button
        type="button"
        onClick={onNext}
        disabled={!hasSelection}
        className={cn(
          "w-full rounded-2xl h-12 font-semibold text-white touch-manipulation transition-all duration-300 disabled:opacity-50 disabled:active:scale-100",
          MIN_TAP,
          BOOKING_ACTIVE_SCALE
        )}
        style={{
          backgroundColor: BOOKING_ACCENT,
          borderRadius: BOOKING_RADIUS_BUTTON,
          boxShadow: BOOKING_SHADOW_CARD,
        }}
      >
        Continue
      </button>
    </div>
  );
}

