                            },
                          });
                        }}
                        placeholder="Buzzer code"
                        className="text-sm"
                      />
                      <Label htmlFor="buzzerCode" className="text-xs text-blue-600 mt-0.5 block">Buzzer</Label>
                    </div>
                    <div>
                      <Input
                        id="doorCode"
                        value={bookingState.address.accessCodes?.door || ""}
