                >
                  Save Address
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        </motion.div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { User, Mail, Phone, FileText } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { useTranslation } from "@beautonomi/i18n";
import { BookingState } from "../booking-flow";

interface StepYourInfoProps {
  bookingState: BookingState;
  updateBookingState: (updates: Partial<BookingState>) => void;
  onNext: () => void;
}

// Email validation regex
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

// Phone validation - basic check for digits and length
const validatePhone = (phone: string): boolean => {
  const digitsOnly = phone.replace(/\D/g, "");
  return digitsOnly.length >= 10 && digitsOnly.length <= 15;
};

export default function StepYourInfo({
  bookingState,
  updateBookingState,
  onNext: _onNext,
}: StepYourInfoProps) {
  const [clientInfo, setClientInfo] = useState(
    bookingState.clientInfo || {
      firstName: "",
      lastName: "",
      email: "",
      phone: "",
      specialRequests: "",
    }
  );
  const { t } = useTranslation();
  const [errors, setErrors] = useState<{
    firstName?: string;
    lastName?: string;
    email?: string;
    phone?: string;
  }>({});

  const validate = (): boolean => {
    const newErrors: typeof errors = {};

    if (!clientInfo.firstName.trim()) {
      newErrors.firstName = "First name is required";
    }

    if (!clientInfo.lastName.trim()) {
      newErrors.lastName = "Last name is required";
    }

    if (!clientInfo.email.trim()) {
      newErrors.email = "Email is required";
    } else if (!EMAIL_REGEX.test(clientInfo.email)) {
      newErrors.email = "Please enter a valid email address";
    }

    if (!clientInfo.phone.trim()) {
      newErrors.phone = "Phone number is required";
    } else if (!validatePhone(clientInfo.phone)) {
      newErrors.phone = "Please enter a valid phone number";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const _handleNext = () => {
    if (validate()) {
      updateBookingState({ clientInfo });
      _onNext();
    }
  };

  return (
    <div className="px-4 py-6 space-y-6">
      <div>
        <h2 className="text-2xl font-semibold text-gray-900 mb-2">
          {t("booking.yourInfo")}
        </h2>
        <p className="text-gray-600">
          We'll use this to confirm your booking and send reminders
        </p>
      </div>

      <div className="space-y-4">
        {/* First Name */}
        <div>
          <Label htmlFor="firstName" className="flex items-center gap-2">
            <User className="w-4 h-4" />
            First Name *
          </Label>
          <Input
            id="firstName"
            value={clientInfo.firstName}
            onChange={(e) => {
              setClientInfo({ ...clientInfo, firstName: e.target.value });
              if (errors.firstName) {
                setErrors({ ...errors, firstName: undefined });
              }
            }}
            className={`mt-1 touch-target ${errors.firstName ? "border-red-500" : ""}`}
            placeholder="John"
            required
          />
          {errors.firstName && (
            <p className="text-sm text-red-500 mt-1">{errors.firstName}</p>
          )}
        </div>

        {/* Last Name */}
        <div>
          <Label htmlFor="lastName" className="flex items-center gap-2">
            <User className="w-4 h-4" />
            Last Name *
          </Label>
          <Input
            id="lastName"
            value={clientInfo.lastName}
            onChange={(e) => {
              setClientInfo({ ...clientInfo, lastName: e.target.value });
              if (errors.lastName) {
                setErrors({ ...errors, lastName: undefined });
              }
            }}
            className={`mt-1 touch-target ${errors.lastName ? "border-red-500" : ""}`}
            placeholder="Doe"
            required
          />
          {errors.lastName && (
            <p className="text-sm text-red-500 mt-1">{errors.lastName}</p>
          )}
        </div>

        {/* Email */}
        <div>
          <Label htmlFor="email" className="flex items-center gap-2">
            <Mail className="w-4 h-4" />
            {t("auth.email")} *
          </Label>
          <Input
            id="email"
            type="email"
            value={clientInfo.email}
            onChange={(e) => {
              setClientInfo({ ...clientInfo, email: e.target.value });
              if (errors.email) {
                setErrors({ ...errors, email: undefined });
              }
            }}
            className={`mt-1 touch-target ${errors.email ? "border-red-500" : ""}`}
            placeholder="john.doe@example.com"
            required
          />
          {errors.email && (
            <p className="text-sm text-red-500 mt-1">{errors.email}</p>
          )}
        </div>

        {/* Phone */}
        <div>
          <Label htmlFor="phone" className="flex items-center gap-2">
            <Phone className="w-4 h-4" />
            {t("auth.phone")} *
          </Label>
          <Input
            id="phone"
            type="tel"
            value={clientInfo.phone}
            onChange={(e) => {
              setClientInfo({ ...clientInfo, phone: e.target.value });
              if (errors.phone) {
                setErrors({ ...errors, phone: undefined });
              }
            }}
            className={`mt-1 touch-target ${errors.phone ? "border-red-500" : ""}`}
            placeholder="+971 50 123 4567"
            required
          />
          {errors.phone && (
            <p className="text-sm text-red-500 mt-1">{errors.phone}</p>
          )}
        </div>

        {/* Special Requests */}
        <div>
          <Label htmlFor="specialRequests" className="flex items-center gap-2">
            <FileText className="w-4 h-4" />
            {t("booking.specialRequests")} ({t("common.optional")})
          </Label>
          <Textarea
            id="specialRequests"
            value={clientInfo.specialRequests}
            onChange={(e) =>
              setClientInfo({ ...clientInfo, specialRequests: e.target.value })
            }
            rows={3}
            className="mt-1 touch-target"
            placeholder="Any allergies, preferences, or special instructions..."
          />
        </div>

        {/* House Call Specific Instructions - Only show for mobile bookings */}
        {bookingState.mode === "mobile" && (
          <div>
            <Label htmlFor="houseCallInstructions" className="flex items-center gap-2">
              <FileText className="w-4 h-4" />
              House Call Instructions (Optional)
            </Label>
            <Textarea
              id="houseCallInstructions"
              value={clientInfo.houseCallInstructions || ""}
              onChange={(e) =>
                setClientInfo({ ...clientInfo, houseCallInstructions: e.target.value })
              }
              rows={3}
              className="mt-1 touch-target"
              placeholder="Equipment needed, accessibility requirements, pet information, or other house call specific instructions..."
            />
            <p className="text-xs text-gray-500 mt-1">
              This information helps your provider prepare for the visit
            </p>
          </div>
        )}
      </div>

      {/* Continue as Guest Option */}
      <div className="pt-4 border-t">
        <p className="text-sm text-gray-600 text-center">
          Don't have an account?{" "}
          <button
            onClick={() => {
              window.location.href = `/login?redirect=${encodeURIComponent(window.location.pathname)}`;
            }}
            className="text-[#FF0077] underline font-medium"
          >
            Continue as guest
          </button>
        </p>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState, useRef } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { motion } from "framer-motion";
import { CheckCircle, Calendar, MapPin, Clock, Mail, Phone, Download, Share2, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { getGoogleCalendarUrl, getOutlookCalendarUrl, downloadICS } from "@/lib/calendar/ics";
import { formatCurrency, formatDate, formatTime } from "@/lib/utils";
import LoadingTimeout from "@/components/ui/loading-timeout";
import BeautonomiHeader from "@/components/layout/beautonomi-header";

interface BookingDetails {
  id: string;
  booking_number: string;
  status: string;
  selected_datetime: string;
  location_type: "at_home" | "at_salon";
  total_amount: number;
  currency: string;
  services: Array<{
    title: string;
    duration: number;
    price: number;
    staff_name?: string;
  }>;
  addons?: Array<{
    title: string;
    price: number;
  }>;
  address?: {
    line1: string;
    line2?: string;
    city: string;
    country: string;
  };
  location?: {
    name: string;
    address: string;
  };
  client_info?: {
    first_name: string;
    last_name: string;
    email: string;
    phone: string;
  };
  special_requests?: string;
  provider?: {
    business_name: string;
    phone?: string;
    email?: string;
  };
}

export default function BookingConfirmationPage() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const bookingId = searchParams.get("bookingId");
  const [booking, setBooking] = useState<BookingDetails | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const referralTracked = useRef(false);

  useEffect(() => {
    if (!bookingId) {
      setError("Booking ID not found");
      setIsLoading(false);
      return;
    }

    const loadBooking = async () => {
      try {
        setIsLoading(true);
        const response = await fetcher.get<{ data: BookingDetails }>(
          `/api/me/bookings/${bookingId}`
        );
        setBooking(response.data);
      } catch (err) {
        const errorMessage =
          err instanceof FetchError
            ? err.message
            : "Failed to load booking details";
        setError(errorMessage);
        console.error("Error loading booking:", err);
      } finally {
        setIsLoading(false);
      }
    };

    loadBooking();
  }, [bookingId]);

  // Attribute referral conversion when user has referred_by and completes this booking (fire once)
  useEffect(() => {
    if (!bookingId || !booking || referralTracked.current) return;
    referralTracked.current = true;
    fetcher
      .post("/api/me/referrals/track", { booking_id: bookingId })
      .catch(() => {});
  }, [bookingId, booking]);

  const handleDownloadReceipt = () => {
    // Open receipt page in new tab for printing/saving as PDF
    const id = searchParams.get("bookingId") || searchParams.get("booking_id");
    if (id) {
      window.open(`/account-settings/bookings/${id}/receipt`, "_blank");
    } else {
      window.print();
    }
  };

  const handleShare = () => {
    if (navigator.share && booking) {
      navigator.share({
        title: `Booking Confirmation - ${booking.booking_number}`,
        text: `I've booked ${booking.services.length} service(s) with ${booking.provider?.business_name || "provider"}`,
        url: window.location.href,
      });
    }
  };

  const totalDurationMinutes = booking?.services?.reduce((sum, s) => sum + (s.duration || 0), 0) ?? 0;
  const bookingStart = booking?.selected_datetime ? new Date(booking.selected_datetime) : null;
  const bookingEnd = bookingStart
    ? new Date(bookingStart.getTime() + totalDurationMinutes * 60 * 1000)
    : null;
  const locationStr =
    !booking || booking.location_type === "at_home"
      ? booking?.address
        ? `${booking.address.line1}${booking.address.line2 ? `, ${booking.address.line2}` : ""}, ${booking.address.city}`
        : "Address TBD"
      : booking?.location?.address ?? booking?.location?.name ?? booking?.provider?.business_name ?? "Salon";
  const calendarEvent =
    bookingStart && bookingEnd
      ? {
          title: `Appointment with ${booking.provider?.business_name || "provider"}`,
          description: `Booking #${booking.booking_number}\n${booking.services?.map((s) => `${s.title} (${s.duration} min)`).join("\n") ?? ""}`,
          location: locationStr,
          start: bookingStart,
          end: bookingEnd,
        }
      : null;

  if (isLoading) {
    return (
      <div className="min-h-screen bg-white">
        <BeautonomiHeader />
        <div className="flex items-center justify-center min-h-[60vh]">
          <LoadingTimeout loadingMessage="Loading booking confirmation..." />
        </div>
      </div>
    );
  }

  if (error || !booking) {
    return (
      <div className="min-h-screen bg-white">
        <BeautonomiHeader />
        <div className="flex items-center justify-center min-h-[60vh] px-4">
          <div className="text-center max-w-md">
            <h1 className="text-2xl font-semibold text-gray-900 mb-2">
              Booking Not Found
            </h1>
            <p className="text-gray-600 mb-6">{error || "Unable to load booking details"}</p>
            <Button
              onClick={() => router.push("/")}
              className="bg-[#FF0077] hover:bg-[#D60565]"
            >
              Go Home
            </Button>
          </div>
        </div>
      </div>
    );
  }

  const bookingDate = new Date(booking.selected_datetime);

  return (
    <div className="min-h-screen bg-gray-50">
      <BeautonomiHeader />

      <div className="max-w-2xl mx-auto px-4 py-8">
        {/* Success Header */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center mb-8"
        >
          <motion.div
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ type: "spring", stiffness: 200, damping: 15 }}
            className="inline-block mb-4"
          >
            <CheckCircle className="w-20 h-20 text-green-500" />
          </motion.div>
          <h1 className="text-3xl font-bold text-gray-900 mb-2">
            Booking Confirmed!
          </h1>
          <p className="text-gray-600">
            Your booking has been confirmed. We've sent a confirmation email to{" "}
            {booking.client_info?.email || "your email"}.
          </p>
          <p className="text-sm text-gray-500 mt-2">
            Booking #{booking.booking_number}
          </p>
        </motion.div>

        {/* Booking Details Card */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="bg-white rounded-xl shadow-lg overflow-hidden mb-6"
        >
          <div className="p-6 space-y-6">
            {/* Date & Time */}
            <div className="flex items-start gap-4">
              <div className="p-3 bg-pink-50 rounded-lg">
                <Calendar className="w-6 h-6 text-[#FF0077]" />
              </div>
              <div className="flex-1">
                <h3 className="font-semibold text-gray-900 mb-1">Date & Time</h3>
                <p className="text-gray-600">{formatDate(bookingDate)}</p>
                <p className="text-gray-600">{formatTime(bookingDate.toISOString())}</p>
              </div>
            </div>

            {/* Location */}
            <div className="flex items-start gap-4">
              <div className="p-3 bg-pink-50 rounded-lg">
                <MapPin className="w-6 h-6 text-[#FF0077]" />
              </div>
              <div className="flex-1">
                <h3 className="font-semibold text-gray-900 mb-1">
                  {booking.location_type === "at_home" ? "House Call" : "At the Salon"}
                </h3>
                {booking.location_type === "at_home" && booking.address ? (
                  <p className="text-gray-600">
                    {booking.address.line1}
                    {booking.address.line2 && `, ${booking.address.line2}`}
                    <br />
                    {booking.address.city}, {booking.address.country}
                  </p>
                ) : booking.location ? (
                  <p className="text-gray-600">{booking.location.address}</p>
                ) : (
                  <p className="text-gray-600">{booking.provider?.business_name}</p>
                )}
              </div>
            </div>

            {/* Services */}
            <div className="border-t pt-6">
              <h3 className="font-semibold text-gray-900 mb-4">Services</h3>
              <div className="space-y-3">
                {booking.services.map((service, index) => (
                  <div key={index} className="flex justify-between items-start">
                    <div className="flex-1">
                      <p className="font-medium text-gray-900">{service.title}</p>
                      {service.staff_name && (
                        <p className="text-sm text-gray-600">with {service.staff_name}</p>
                      )}
                      <p className="text-sm text-gray-500">
                        <Clock className="w-3 h-3 inline mr-1" />
                        {service.duration} min
                      </p>
                    </div>
                    <p className="font-semibold text-gray-900">
                      {formatCurrency(service.price, booking.currency)}
                    </p>
                  </div>
                ))}
                {booking.addons && booking.addons.length > 0 && (
                  <>
                    {booking.addons.map((addon, index) => (
                      <div key={`addon-${index}`} className="flex justify-between items-start pl-4">
                        <div className="flex-1">
                          <p className="text-gray-600">+ {addon.title}</p>
                        </div>
                        <p className="font-semibold text-gray-900">
                          {formatCurrency(addon.price, booking.currency)}
                        </p>
                      </div>
                    ))}
                  </>
                )}
              </div>
            </div>

            {/* Total */}
            <div className="border-t pt-4">
              <div className="flex justify-between items-center">
                <span className="text-lg font-semibold text-gray-900">Total</span>
                <span className="text-2xl font-bold text-[#FF0077]">
                  {formatCurrency(booking.total_amount, booking.currency)}
                </span>
              </div>
            </div>

            {/* Special Requests */}
            {booking.special_requests && (
              <div className="border-t pt-4">
                <h3 className="font-semibold text-gray-900 mb-2">Special Requests</h3>
                <p className="text-gray-600">{booking.special_requests}</p>
              </div>
            )}

            {/* Provider Contact */}
            {booking.provider && (
              <div className="border-t pt-4">
                <h3 className="font-semibold text-gray-900 mb-3">Provider Contact</h3>
                <div className="space-y-2">
                  <p className="text-gray-900 font-medium">{booking.provider.business_name}</p>
                  {booking.provider.phone && (
                    <p className="text-gray-600 flex items-center gap-2">
                      <Phone className="w-4 h-4" />
                      {booking.provider.phone}
                    </p>
                  )}
                  {booking.provider.email && (
                    <p className="text-gray-600 flex items-center gap-2">
                      <Mail className="w-4 h-4" />
                      {booking.provider.email}
                    </p>
                  )}
                </div>
              </div>
            )}
          </div>
        </motion.div>

        {/* Add to calendar */}
        {calendarEvent && (
          <div className="mb-6">
            <p className="text-sm font-medium text-gray-700 mb-2">Add to your calendar</p>
            <div className="flex flex-wrap gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => window.open(getGoogleCalendarUrl(calendarEvent), "_blank")}
              >
                <Plus className="w-4 h-4 mr-1" />
                Google Calendar
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => window.open(getOutlookCalendarUrl(calendarEvent), "_blank")}
              >
                Outlook
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => {
                  downloadICS(calendarEvent, `booking-${booking.booking_number}.ics`);
                }}
              >
                .ICS file
              </Button>
            </div>
          </div>
        )}

        {/* Action Buttons */}
        <div className="flex flex-col sm:flex-row gap-3">
          <Button
            onClick={handleDownloadReceipt}
            variant="outline"
            className="flex-1 touch-target"
          >
