import React, { useState } from 'react';
import { Calendar } from '@/components/ui/calendar';
import { Button } from '@/components/ui/button';
import Image from 'next/image';
import Keyboard from './../../../../public/images/keyboard-icon.svg';
import { useResponsive } from '@/hooks/useMobile';

interface DateSelectorProps {
  checkInDate: Date | null;
  checkOutDate: Date | null;
  onCheckInDateChange: (date: Date | null) => void;
  onCheckOutDateChange: (date: Date | null) => void;
}

const DateSelector: React.FC<DateSelectorProps> = ({
  checkInDate,
  checkOutDate,
  onCheckInDateChange,
  onCheckOutDateChange
}) => {
  const [isCheckInSelected, setIsCheckInSelected] = useState<boolean>(true);
  const [isPopupOpen, setIsPopupOpen] = useState<boolean>(false);
  const numberOfMonths = useResponsive({ mobile: 1, desktop: 2 });

  const minimumNights = 2;

  const keyboardShortcuts = [
    { key: "Γå╡", description: "Select the date in focus" },
    { key: "ΓåÉ/ΓåÆ", description: "Move backward (left) and forward (right) by one day" },
    { key: "Γåæ/Γåô", description: "Move backward (up) and forward (down) by one week" },
    { key: "PgUp/PgDn", description: "Switch months" },
    { key: "Home/End", description: "Go to the first or last day of a week" },
    { key: "?", description: "Open this panel" },
  ];

  const handleDateSelect = (date: Date | null) => {
    if (date) {
      if (isCheckInSelected) {
        onCheckInDateChange(date);
        setIsCheckInSelected(false);
      } else {
        if (checkInDate) {
          const timeDiff = date.getTime() - checkInDate.getTime();
          const selectedNights = Math.ceil(timeDiff / (1000 * 3600 * 24));

          if (selectedNights >= minimumNights) {
            onCheckOutDateChange(date);
          } else {
            alert(`Minimum stay is ${minimumNights} nights.`);
          }
        }
      }
    }
  };

  const calculateNights = () => {
    if (checkInDate && checkOutDate) {
      const timeDiff = checkOutDate.getTime() - checkInDate.getTime();
      return Math.ceil(timeDiff / (1000 * 3600 * 24));
    }
    return 0;
  };

  const clearDates = () => {
    onCheckInDateChange(null);
    onCheckOutDateChange(null);
    setIsCheckInSelected(true);
  };

  const nights = calculateNights();

  const getDisplayText = () => {
    if (!checkInDate) {
      return "Select check-in date.";
    } else if (!checkOutDate) {
      return "Select checkout date.";
    } else if (nights > 0) {
      return `${nights} night${nights > 1 ? "s" : ""} in Downtown Dubai`;
    }
    return "";
  };

  const togglePopup = () => {
    setIsPopupOpen(!isPopupOpen);
  };

  return (
    <div className="container">
      <div className="mt-4">
        <p className="text-[22px] font-normal  text-secondary">
          {getDisplayText()}
        </p>
        <p className="text-sm font-normal  text-destructive mb-4">
          Minimum stay: 2 nights
        </p>
      </div>
      <div className="mb-5">
        <div className="w-full">
          <Calendar
            mode="single"
            selected={isCheckInSelected ? checkInDate : checkOutDate}
            onSelect={handleDateSelect}
            initialFocus
            numberOfMonths={numberOfMonths} // Set the number of months based on screen size
            to={checkOutDate ? checkOutDate : undefined}
            className="w-full"
            classNames={{
              // @ts-expect-error
              day: ({ date }: any) => {
                const isSelected =
                  date?.toDateString() === checkInDate?.toDateString() ||
                  date?.toDateString() === checkOutDate?.toDateString();
                return isSelected ? "bg-black text-white" : "";
              },
            }}
          />
        </div>
      </div>

      <div className="flex justify-between mt-4">
        <Image
          src={Keyboard}
          alt="Keyboard Icon"
          onClick={togglePopup}
          className="cursor-pointer"
        />
        <Button variant="underline" onClick={clearDates}>
          Clear Dates
        </Button>
      </div>

      {isPopupOpen && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
          <div className="bg-white p-6 rounded-lg shadow-lg max-w-md w-full relative">
            <h2 className="text-lg font-semibold mb-12">Keyboard Shortcuts</h2>
            <div className="space-y-3">
              {keyboardShortcuts.map((shortcut, index) => (
                <div key={index} className="flex items-center gap-10">
                  <p className="bg-primary text-secondary text-xs font-normal  px-2 py-1 rounded mr-4 min-w-[60px] text-center">
                    {shortcut.key}
                  </p>
                  <p className="text-base font-normal  text-destructive max-w-60 text-left">
                    {shortcut.description}
                  </p>
                </div>
              ))}
            </div>
            <div className="mt-6 text-right">
              <Button variant="underline" onClick={togglePopup}>
                Back to Calendar
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DateSelector;

"use client";
import React, { useState, useEffect } from "react";
import Image from "next/image";
import UserImage from "./../../../../public/images/8aa5cbca-b607-4a45-bd0c-2d63a663aa30.webp";
import Image1 from "./../../../../public/images/svg-gobbler(3).svg";
import Badge from "./../../../../public/images/badge.svg";
import { Button } from "@/components/ui/button";
import Image2 from "./../../../../public/images/svg-gobbler(5).svg";
import Arrow from "./../../../../public/images/Arrow.svg";
import Link from "next/link";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";

interface ProviderInfoProps {
  slug?: string;
  id?: string;
}

export default function ProviderInfo({ slug, id }: ProviderInfoProps) {
  const [provider, setProvider] = useState<any>(null);
  const [staff, _setStaff] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadProviderData = async () => {
      if (!slug && !id) {
        setIsLoading(false);
        return;
      }

      try {
        setIsLoading(true);
        setError(null);
        const providerSlug = slug || id;
        
        // Load provider
        const providerResponse = await fetch(`/api/public/providers/${providerSlug}`);
        if (providerResponse.ok) {
          const providerData = await providerResponse.json();
          const loadedProvider = providerData.data;
          setProvider(loadedProvider);

          // Load staff if provider is a salon (only for authenticated provider owners)
          // For public view, staff will be shown via PartnerTeam component
          // This component is mainly for provider info display
        }
      } catch (err) {
        console.error("Error loading provider data:", err);
        setError("Failed to load provider information");
      } finally {
        setIsLoading(false);
      }
    };

    loadProviderData();
  }, [slug, id]);

  // Calculate stats from provider data
  const infoData = provider ? [
    { value: provider.review_count?.toString() || "0", label: "Reviews" },
    { value: provider.rating?.toFixed(2) || "0.00", label: "Rating" },
    { value: provider.years_in_business?.toString() || "0", label: "Years beauty partner" },
  ] : [
    { value: "0", label: "Reviews" },
    { value: "0.00", label: "Rating" },
    { value: "0", label: "Years beauty partner" },
  ];

  // Use real staff data or empty array
  const teamMembers = staff.length > 0 ? staff.map((member) => ({
    name: member.full_name || member.name || "Team Member",
    image: member.avatar_url || UserImage,
  })) : [];

  const providerDetails = [
    { detail: "Response rate: 100%" },
    { detail: "Responds within an hour" },
  ];

  if (isLoading) {
    return (
      <div className="max-w-[2340px] mx-auto px-8">
        <LoadingTimeout loadingMessage="Loading provider information..." />
      </div>
    );
  }

  if (error || !provider) {
    return (
      <div className="max-w-[2340px] mx-auto px-8">
        <EmptyState
          title="Provider information unavailable"
          description={error || "Unable to load provider details"}
        />
      </div>
    );
  }

  return (
    <div className="max-w-[2340px] mx-auto px-8">
      <div className="mb-12 lg:mb-14 border-b pb-16">
        <h2 className="text-[22px] font-normal  text-secondary mb-6">
          Meet your Provider
        </h2>
        <div className="flex-col lg:flex-row flex gap-9 lg:gap-28 max-w-full mx-auto">
          <div className="max-w-[379px] w-full">
            <Link href="/partner-owner-page">
              <div className="flex-row flex gap-20 py-3 pl-10 shadow-xl border items-center rounded-xl justify-center mb-8">
                <div className="relative w-full">
                  <div className="bg-muted h-8 w-8 justify-center items-center flex rounded-full absolute right-0 top-16">
                    <Image src={Badge} alt="" className="h-4 w-4" />
                  </div>
                  <div className="w-24 h-24 mb-2 rounded-full mx-auto overflow-hidden bg-gray-200 flex items-center justify-center">
                    {(provider?.avatar_url || provider?.thumbnail_url) ? (
                      <Image
                        src={provider.avatar_url || provider.thumbnail_url}
                        alt={provider.business_name || "Provider"}
                        width={96}
                        height={96}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <p className="text-2xl font-bold text-gray-600">
                        {provider?.business_name?.charAt(0).toUpperCase() || "P"}
                      </p>
                    )}
                  </div>
                  <p className="text-3xl text-secondary font-bold text-center">
                    {provider?.business_name || "Provider"}
                  </p>
                  <div className="flex gap-1 justify-center">
                    <Image src={Image1} alt="" />
                    <p className="text-sm text-secondary font-normal  text-center">
                      Super Partner
                    </p>
                  </div>
                </div>
                <div className="w-full">
                  {infoData.map((item, index) => (
                    <div
                      key={index}
                      className={`mb-2 pb-2 ${
                        index === infoData.length - 1 ? "" : "border-b"
                      }`}
                    >
                      <p className="text-[22px] font-bold Beautonomi-bold text-secondary">
                        {item.value}
                      </p>
                      <p className="text-[10px] font-light  text-secondary">
                        {item.label}
                      </p>
                    </div>
                  ))}
                </div>
              </div>
            </Link>
            <Link href="/">
              <div className="flex gap-2 items-center border-b lg:border-none pb-8">
                <p className="underline text-base font-normal  text-secondary">
                  Show more
                </p>
                <Image src={Arrow} alt="" className="h-3 w-3" />
              </div>
            </Link>
          </div>
          <div className="">
            {provider && (
              <>
                <h2 className="text-lg font-normal  text-secondary mb-3">
                  {provider.business_name} {provider.is_verified ? "is a Verified Partner" : "is a Partner"}
                </h2>
                <p className="text-base font-light  text-secondary mb-6">
                  {provider.description || "Top Professionals are experienced, highly-rated experts dedicated to delivering exceptional beauty services."}
                </p>
                {teamMembers.length > 0 && (
                  <div className="mb-6">
                    <h3 className="text-lg font-normal  text-secondary mb-3">
                      Team Members
                    </h3>
                    {teamMembers.map((member, index) => (
                      <div key={index} className="flex items-center gap-3 mb-4">
                        <div className="rounded-full h-12 w-12 overflow-hidden bg-gray-200 flex items-center justify-center">
                          {typeof member.image === 'string' ? (
                            <Image
                              src={member.image}
                              alt={member.name}
                              width={48}
                              height={48}
                              className="w-full h-full object-cover"
                            />
                          ) : (
                            <Image
                              src={member.image}
                              alt={member.name}
                              className="w-full h-full object-cover"
                            />
                          )}
                        </div>
                        <p className="text-base font-light  text-secondary">
                          {member.name}
                        </p>
                      </div>
                    ))}
                  </div>
                )}
                <div className="border-b pb-8 mb-7">
                  <h3 className="text-lg font-normal  text-secondary mb-3">
                    Provider details
                  </h3>
                  <div className="mb-8">
                    {providerDetails.map((detail, index) => (
                      <p
                        key={index}
                        className="text-base font-light  text-secondary"
                      >
                        {detail.detail}
                      </p>
                    ))}
                  </div>
                  <Button variant="default">Message Provider</Button>
                </div>
              </>
            )}
            <div className="flex gap-2 items-center">
              <Image src={Image2} alt="" className="h-6 w-6" />
              <p className="text-xs font-light  text-secondary">
                To protect your payment, never transfer money or communicate
                outside of the Beautonomi website or app.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";
import React, { useState } from "react";
import { useRouter } from "next/navigation";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
const PartnerBuy: React.FC<{ id?: string; slug?: string }> = ({ id: providerId, slug: _slug }) => {
  const router = useRouter();
  const [isLoading, setIsLoading] = useState(false);

  const handleBuyGiftCard = async () => {
    if (!providerId) {
      router.push("/gift-card");
      return;
    }

    try {
      setIsLoading(true);
      // Default amount for quick buy; user can also go to /gift-card for custom.
      const res = await fetcher.post<{ data: { payment_url: string }; error: null }>(`/api/public/gift-cards/purchase`, {
        amount: 500,
        provider_id: providerId,
      });
      const url = res?.data?.payment_url;
      if (url) {
        window.location.href = url;
        return;
      }
      toast.success("Purchase started. Check your Payments & Gift Cards.");
    } catch (e) {
      toast.error(e instanceof FetchError ? e.message : "Failed to start gift card purchase");
      router.push("/gift-card");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-[2340px] mx-auto px-4 md:px-10 py-8">
      <h2 className="text-2xl font-semibold mb-6">Gift Cards</h2>
      
      <div className="max-w-3xl">
        <div className="border border-gray-200 rounded-lg p-6">
          <div className="mb-4">
            <h3 className="text-lg font-semibold mb-2">Treat yourself or a friend</h3>
            <p className="text-gray-600 text-sm mb-4">
              Purchase a gift card for future visits to this provider. Gift cards can be used for any service or booking.
            </p>
          </div>
          <button
            onClick={handleBuyGiftCard}
            disabled={isLoading}
            className="w-full bg-gray-900 text-white py-3 rounded-lg hover:bg-gray-800 transition-colors font-medium disabled:opacity-60"
          >
            {isLoading ? "Redirecting..." : "Buy Gift Card"}
          </button>
        </div>

        {/* Info about custom service requests */}
        <div className="mt-6 p-4 bg-gray-50 rounded-lg border border-gray-200">
          <p className="text-sm text-gray-600">
            <strong className="font-medium text-gray-900">Need a custom service?</strong>{" "}
            Use the <strong className="font-medium text-gray-900">"Request Custom Service"</strong> tab above 
            to submit a detailed request with your specific requirements, budget, preferred dates, and inspiration images.
          </p>
        </div>
      </div>
    </div>
  );
};

