            icon={AlertCircle}
          />
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-[2340px] mx-auto px-4 md:px-10 py-8 md:py-12">
      {/* Header Section with Explanation */}
      <div className="max-w-3xl mx-auto mb-8 md:mb-10">
        <div className="flex items-center gap-3 mb-4">
