"use client";
import React, { useState, useEffect, Suspense } from 'react'
import { useSearchParams } from 'next/navigation'
import RentalPhotos from './rental-photos'
import ActionToolbar from './action-toolbar'
import Footer from '@/components/layout/footer'
import LoadingTimeout from '@/components/ui/loading-timeout'
import EmptyState from '@/components/ui/empty-state'
import { fetcher, FetchError, FetchTimeoutError } from '@/lib/http/fetcher'
import type { PublicProviderDetail } from '@/types/beautonomi'

const GalleryContent = () => {
  const searchParams = useSearchParams()
  const [provider, setProvider] = useState<PublicProviderDetail | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [currentSlug, setCurrentSlug] = useState<string | null>(null)

  useEffect(() => {
    const loadProvider = async () => {
      // Get slug from URL params - try multiple parameter names
      const slugParam = searchParams.get("slug") || 
                       searchParams.get("partnerId") || 
                       searchParams.get("providerSlug")
      const slug = slugParam ? decodeURIComponent(slugParam) : null

      // Use stored slug if URL params are missing (for page refreshes)
      let finalSlug = slug || currentSlug

      // Also try to get slug from the current URL path if not in query params
      if (!finalSlug && typeof window !== 'undefined') {
        // Try to extract from referrer or previous navigation
        const referrer = document.referrer
        if (referrer) {
          try {
            const referrerUrl = new URL(referrer)
            const referrerSlug = referrerUrl.searchParams.get("slug")
            if (referrerSlug) {
              finalSlug = decodeURIComponent(referrerSlug)
            }
          } catch {
            // Ignore URL parsing errors
          }
        }
      }

      if (!finalSlug) {
        setError("Provider slug is required. Please navigate from the provider profile page.")
        setIsLoading(false)
        return
      }

      try {
        setIsLoading(true)
        setError(null)
        const response = await fetcher.get<{
          data: PublicProviderDetail
          error: null
        }>(`/api/public/providers/${encodeURIComponent(finalSlug)}`, {
          timeoutMs: 15000,
        })
        setProvider(response.data)
        // Store the slug for future use
        if (response.data.slug) {
          setCurrentSlug(response.data.slug)
          // Update URL if slug is missing from query params
          if (!slug && typeof window !== 'undefined') {
            const newUrl = new URL(window.location.href)
            newUrl.searchParams.set('slug', response.data.slug)
            window.history.replaceState({}, '', newUrl.toString())
          }
        }
      } catch (err) {
        const errorMessage =
          err instanceof FetchTimeoutError
            ? "Request timed out. Please try again."
            : err instanceof FetchError
            ? err.message
            : "Failed to load provider"
        setError(errorMessage)
        console.error("Error loading provider:", err)
      } finally {
        setIsLoading(false)
      }
    }

    loadProvider()
  }, [searchParams])

  if (isLoading) {
    return (
      <div>
        <ActionToolbar />
        <div className="container mx-auto px-4 py-8">
          <LoadingTimeout loadingMessage="Loading gallery..." />
        </div>
        <Footer />
      </div>
    )
  }

  if (error || !provider) {
    return (
      <div>
        <ActionToolbar />
        <div className="container mx-auto px-4 py-8">
          <EmptyState
            title="Gallery unavailable"
            description={error || "Unable to load gallery images"}
          />
        </div>
        <Footer />
      </div>
    )
  }

  return (
    <div>
      <Suspense fallback={<div className="sticky top-0 z-10 bg-white py-6"><div className="container"><div className="flex justify-between items-center"><div>Loading...</div></div></div></div>}>
        <ActionToolbar />
      </Suspense>
      <RentalPhotos 
        gallery={provider.gallery || []} 
        businessName={provider.business_name}
        slug={provider.slug}
      />
      <Footer />
    </div>
  )
}

const page = () => {
  return (
    <Suspense fallback={
      <div>
        <ActionToolbar />
        <div className="container mx-auto px-4 py-8">
          <LoadingTimeout loadingMessage="Loading gallery..." />
        </div>
        <Footer />
      </div>
    }>
      <GalleryContent />
    </Suspense>
  )
}

export default page

"use client";
import React from "react";
import EmptyState from "@/components/ui/empty-state";

interface RentalPhotosProps {
  gallery?: string[];
  businessName?: string;
  slug?: string;
}

const RentalPhotos: React.FC<RentalPhotosProps> = ({ gallery = [], businessName = "Provider" }) => {
  // If no gallery images, show empty state
  if (!gallery || gallery.length === 0) {
    return (
      <div className="container">
        <div className="py-8">
          <EmptyState
            title="No photos available"
            description="This provider hasn't added any photos to their gallery yet."
          />
        </div>
      </div>
    );
  }

  // Group images into sections for better display
  // For now, we'll display all images in a simple grid
  // You can enhance this later to group by category if needed
  const imagesPerSection = 4;
  const sections = [];

  for (let i = 0; i < gallery.length; i += imagesPerSection) {
    const sectionImages = gallery.slice(i, i + imagesPerSection);
    sections.push({
      sectionId: `section-${Math.floor(i / imagesPerSection)}`,
      images: sectionImages,
      title: `Gallery ${Math.floor(i / imagesPerSection) + 1}`,
    });
  }

  const scrollToSection = (sectionId: string) => {
    const element = document.getElementById(sectionId);
    if (element) {
      element.scrollIntoView({ behavior: "smooth" });
    }
  };

  return (
    <div className="container">
      <div>
        <h2 className="text-[22px] font-normal text-secondary mb-6">
          Photo tour
        </h2>

        {/* Section Navigation - only show if multiple sections */}
        {sections.length > 1 && (
          <div
            className="flex overflow-x-scroll md:overflow-auto md:flex-wrap gap-7 gap-y-0 border-b md:border-none pb-11 md:pb-0 mb-10 md:mb-12"
            style={{ scrollbarWidth: "none", msOverflowStyle: "none" }}
          >
            {sections.map((section, _idx) => (
              <div
                key={section.sectionId}
                onClick={() => scrollToSection(section.sectionId)}
                className="cursor-pointer"
              >
                <div className="relative w-[340px] md:w-[145px] h-[340px] md:h-[145px]">
                  <img
                    src={section.images[0]}
                    alt={`${businessName} - ${section.title}`}
                    className="w-full h-full object-cover rounded-md"
                  />
                </div>
                <p className="text-sm font-normal text-secondary mt-2 mb-3">
                  {section.title}
                </p>
              </div>
            ))}
          </div>
        )}

        {/* Image Sections */}
        {sections.map((section, _sectionIdx) => (
          <div
            key={section.sectionId}
            id={section.sectionId}
            className="block md:grid grid-cols-12 mb-9 md:mb-6"
          >
            {sections.length > 1 && (
              <div className="col-span-4 mb-6">
                <h3 className="text-[22px] font-normal text-secondary">
                  {section.title}
                </h3>
                <p className="text-sm font-normal text-destructive">
                  {section.images.length} {section.images.length === 1 ? 'photo' : 'photos'}
                </p>
              </div>
            )}
            <div className={sections.length > 1 ? "col-span-8 mb-6" : "col-span-12 mb-6"}>
              <div>
                {/* First image full width if multiple images */}
                {section.images.length > 1 && (
                  <img
                    src={section.images[0]}
                    alt={`${businessName} - ${section.title} - Image 1`}
                    className="w-full mb-3 rounded-lg"
                  />
                )}
                {/* Remaining images in grid */}
                {section.images.length > 1 && (
                  <div className="grid grid-cols-2 gap-2 w-full">
                    {section.images.slice(1).map((imageUrl, i) => (
                      <img
                        key={i}
                        src={imageUrl}
                        alt={`${businessName} - ${section.title} - Image ${i + 2}`}
                        className="w-full rounded-lg"
                      />
                    ))}
                  </div>
                )}
                {/* Single image display */}
                {section.images.length === 1 && (
                  <img
                    src={section.images[0]}
                    alt={`${businessName} - ${section.title}`}
                    className="w-full rounded-lg"
                  />
                )}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

