                <div className="flex items-center gap-2 mb-2">
                  <CheckCircle2 className="h-5 w-5 text-green-600" />
                  <h3 className="font-semibold text-green-900">Profile Complete! ≡ƒÄë</h3>
                </div>
                <p className="text-sm text-green-800">
