            )}
          </div>

          {/* Top 3 Items */}
          {!isComplete && completionData.topItems.length > 0 && (
            <Card className="bg-white border border-gray-200 shadow-sm">
              <CardHeader>
                <CardTitle className="text-lg font-semibold">Top 3 to Complete</CardTitle>
