"use client";
import { Scissors, Sparkles, Heart, Star } from "lucide-react"
import { Switch } from "@/components/ui/switch"
import { useEffect, useState } from "react";
import { fetcher } from "@/lib/http/fetcher";

interface BookedService {
  id: string;
  service_name?: string;
  offering_name?: string;
  scheduled_start_at?: string;
}

interface PreferencesProps {
  travelDestinations: string[] | null;
  setTravelDestinations: (value: string[] | null) => void;
  showTravelHistory: boolean;
  setShowTravelHistory: (value: boolean) => void;
}

export default function Preferences({ 
  travelDestinations: _travelDestinations, 
  setTravelDestinations: _setTravelDestinations,
  showTravelHistory,
  setShowTravelHistory,
}: PreferencesProps) {
  const [bookedServices, setBookedServices] = useState<BookedService[]>([]);
  const [isLoadingServices, setIsLoadingServices] = useState(true);

  useEffect(() => {
    const loadBookedServices = async () => {
      try {
        setIsLoadingServices(true);
        // Fetch upcoming bookings - use upcoming status to get confirmed/paid future bookings
        const response = await fetcher.get<{ data: { data: any[] } | unknown[] }>("/api/me/bookings?status=upcoming&limit=10");
        // Handle both paginated and non-paginated responses
        const bookingsData = Array.isArray(response.data) 
          ? response.data 
          : (response.data?.data || []);
        
        // Extract service information from bookings
        // Booking type has services: BookingServiceDetail[] with offering_name
        const services: BookedService[] = [];
        for (const booking of bookingsData) {
          // Check both 'services' (from Booking type) and 'booking_services' (from DB query)
          const bookingServices = booking.services || booking.booking_services || [];
          
          if (Array.isArray(bookingServices) && bookingServices.length > 0) {
            for (const service of bookingServices) {
              if (services.length >= 4) break;
              const serviceName = service.offering_name || 
                                 service.offering?.name || 
                                 service.name || 
                                 "Service";
              services.push({
                id: service.id || `${booking.id}-${services.length}`,
                service_name: serviceName,
                offering_name: service.offering_name || service.offering?.name,
                scheduled_start_at: service.scheduled_start_at || booking.scheduled_at,
              });
            }
          } else if (services.length < 4) {
            // If no services array, try to get service name from booking level
            const serviceName = booking.service_name || booking.offering_name || "Service";
            services.push({
              id: booking.id,
              service_name: serviceName,
              offering_name: booking.offering_name,
              scheduled_start_at: booking.scheduled_at,
            });
          }
          if (services.length >= 4) break;
        }
        
        setBookedServices(services);
      } catch (error) {
        console.error("Failed to load booked services:", error);
        // Don't show error to user - just show empty state
        setBookedServices([]);
      } finally {
        setIsLoadingServices(false);
      }
    };

    loadBookedServices();
  }, []);

  const icons = [Scissors, Sparkles, Heart, Star];
  const displayServices = bookedServices.length > 0 ? bookedServices : [];
  const emptySlots = 4 - displayServices.length;

  return (
    <div className="max-w-3xl mx-auto px-6 border-b mb-8 pb-10">
      <div className="flex justify-between items-center mb-1">
        <h2 className="text-[22px] font-medium text-gray-800">Services {"you've"} booked</h2>
        <Switch checked={showTravelHistory} onCheckedChange={setShowTravelHistory} />
      </div>
      <p className="text-sm text-destructive font-light mb-10">
        Choose whether other people can see the beauty services {"you've"} booked on Beautonomi.
      </p>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
        {isLoadingServices ? (
          // Show loading placeholders
          [Scissors, Sparkles, Heart, Star].map((Icon, index) => (
            <div
              key={`loading-${index}`}
              className="flex flex-col items-center justify-between bg-white"
            >
              <div className="flex items-center justify-center border border-gray-300 rounded-md w-full py-8 mb-5 animate-pulse">
                <Icon className="w-14 h-14 text-gray-300" />
              </div>
              <span className="text-sm text-gray-300 font-light">Loading...</span>
            </div>
          ))
        ) : (
          <>
            {/* Display actual booked services */}
            {displayServices.map((service, index) => {
              const Icon = icons[index % icons.length];
              const serviceName = service.service_name || service.offering_name || "Service";
              return (
                <div
                  key={service.id}
                  className="flex flex-col items-center justify-between bg-white"
                >
                  <div className="flex items-center justify-center border border-gray-300 rounded-md w-full py-8 mb-5">
                    <Icon className="w-14 h-14 text-gray-500" />
                  </div>
                  <span className="text-sm text-gray-400 font-light truncate w-full text-center px-1" title={serviceName}>
                    {serviceName}
                  </span>
                </div>
              );
            })}
            {/* Show empty slots as "Next service" */}
            {emptySlots > 0 && Array.from({ length: emptySlots }).map((_, index) => {
              const Icon = icons[(displayServices.length + index) % icons.length];
              return (
                <div
                  key={`empty-${index}`}
                  className="flex flex-col items-center justify-between bg-white"
                >
                  <div className="flex items-center justify-center border border-gray-300 rounded-md w-full py-8 mb-5">
                    <Icon className="w-14 h-14 text-gray-500" />
                  </div>
                  <span className="text-sm text-destructive font-light">Next service</span>
                </div>
              );
            })}
          </>
        )}
      </div>
    </div>
  )
}

import React from "react";
import { getSupabaseServer } from "@/lib/supabase/server";
import { requireRole } from "@/lib/supabase/auth-server";
import AuthGuard from "@/components/auth/auth-guard";
import ProfilePageClient from "./components/ProfilePageClient";
import type { ProfileUser, ProfileData, CompletionData } from "@/types/profile";
import Breadcrumb from "@/components/ui/breadcrumb";
import BottomNav from "@/components/layout/bottom-nav";
import BackButton from "@/app/account-settings/components/back-button";

export const dynamic = "force-dynamic";

async function calculateCompletionData(
  supabase: any,
  userId: string,
  userData: any,
  profileData: any
): Promise<CompletionData> {
  // Get verification status
  const { data: verification } = await supabase
    .from("user_verifications")
    .select("status")
    .eq("user_id", userId)
    .order("submitted_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  // Calculate completion for each item
  const checklistItems = [
    {
      id: "photo",
      label: "Add profile photo",
      timeEstimate: "30 sec",
      completed: !!userData.avatar_url,
      required: false,
    },
    {
      id: "email",
      label: "Verify email",
      timeEstimate: "1 min",
      completed: userData.email_verified || false,
      required: true,
    },
    {
      id: "preferred_name",
      label: "Add preferred name",
      timeEstimate: "30 sec",
      completed: !!userData.preferred_name,
      required: false,
    },
    {
      id: "bio",
      label: "Add bio",
      timeEstimate: "2 min",
      completed: !!(profileData?.about),
      required: false,
    },
    {
      id: "identity",
      label: "Verify identity",
      timeEstimate: "5 min",
      completed: verification?.status === "approved",
      required: false,
    },
    {
      id: "phone",
      label: "Add phone",
      timeEstimate: "1 min",
      completed: !!userData.phone,
      required: false,
    },
    {
      id: "address",
      label: "Add address",
      timeEstimate: "2 min",
      completed: false, // Will check address separately
      required: false,
    },
    {
      id: "emergency_contact",
      label: "Add emergency contact",
      timeEstimate: "1 min",
      completed: !!userData.emergency_contact_name,
      required: false,
    },
    {
      id: "profile_questions",
      label: "Answer 3 profile questions",
      timeEstimate: "3 min",
      completed: false, // Will calculate separately
      required: false,
    },
    {
      id: "interests",
      label: "Add interests",
      timeEstimate: "1 min",
      completed: !!(profileData?.interests && profileData.interests.length > 0),
      required: false,
    },
    {
      id: "beauty_preferences",
      label: "Add beauty preferences",
      timeEstimate: "3 min",
      completed: false, // Will check beauty preferences
      required: false,
    },
  ];

  // Check address
  const { data: address } = await supabase
    .from("user_addresses")
    .select("id")
    .eq("user_id", userId)
    .eq("is_default", true)
    .maybeSingle();

  checklistItems[6].completed = !!address;

  // Check profile questions (at least 3 answered)
  const answeredQuestions = profileData ? [
    profileData.school,
    profileData.work,
    profileData.location,
    profileData.decade_born,
    profileData.favorite_song,
    profileData.obsessed_with,
    profileData.fun_fact,
    profileData.useless_skill,
    profileData.biography_title,
    profileData.spend_time,
    profileData.pets,
  ].filter(Boolean).length : 0;

  checklistItems[8].completed = answeredQuestions >= 3;

  // Check beauty preferences (at least one field filled)
  const beautyPrefs = profileData?.beauty_preferences || {};
  const hasBeautyPrefs = Object.keys(beautyPrefs).some(key => {
    const value = beautyPrefs[key];
    if (Array.isArray(value)) return value.length > 0;
    if (typeof value === 'string') return value.trim().length > 0;
    return !!value;
  });
  checklistItems[10].completed = hasBeautyPrefs;

  // Calculate totals
  const completed = checklistItems.filter(item => item.completed).length;
  const total = checklistItems.length;
  const percentage = Math.round((completed / total) * 100);

  // Get top 3 incomplete items
  const topItems = checklistItems
    .filter(item => !item.completed)
    .slice(0, 3);

  return {
    completed,
    total,
    percentage,
    topItems,
  };
}

async function getProfileData(): Promise<{
  user: ProfileUser | null;
  profileData: ProfileData | null;
  completionData: CompletionData | null;
}> {
  try {
    const { user } = await requireRole(['customer', 'provider_owner', 'provider_staff', 'superadmin']);
    const supabase = await getSupabaseServer();

    // Fetch all data in parallel
    const [userResult, profileResult] = await Promise.allSettled([
      // User profile
      supabase
        .from("users")
        .select("*")
        .eq("id", user.id)
        .single(),
      // Profile data (about, interests, beauty_preferences)
      supabase
        .from("user_profiles")
        .select("*")
        .eq("user_id", user.id)
        .maybeSingle(),
    ]);

    // Process user data
    let userData: ProfileUser | null = null;
    if (userResult.status === "fulfilled" && userResult.value.data) {
      const user = userResult.value.data;

      // Get address
      const { data: address } = await supabase
        .from("user_addresses")
        .select("*")
        .eq("user_id", user.id)
        .eq("is_default", true)
        .maybeSingle();

      // Get verification
      const { data: verification } = await supabase
        .from("user_verifications")
        .select("id, status, submitted_at, rejection_reason, document_url, document_type, country")
        .eq("user_id", user.id)
        .order("submitted_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      // Get profile preferences
      const { data: profilePrefs } = await supabase
        .from("user_profiles")
        .select("beauty_preferences, privacy_settings")
        .eq("user_id", user.id)
        .maybeSingle();

      // Parse full_name
      const fullName = user.full_name || "";
      const nameParts = fullName.trim().split(/\s+/);
      const first_name = nameParts[0] || "";
      const last_name = nameParts.slice(1).join(" ") || "";

      // Only show pending if there's actually a submitted verification
      // If no verification record exists or it hasn't been submitted, show as 'none'
      let verificationStatus = 'none';
      if (verification?.submitted_at) {
        verificationStatus = verification.status || 'none';
      } else if ((user as any).identity_verification_status && (user as any).identity_verification_status !== 'none') {
        // Fallback to user table status only if it's not 'none'
        verificationStatus = (user as any).identity_verification_status;
      }

      userData = {
        ...user,
        first_name,
        last_name,
        preferred_name: (user as any).preferred_name || null,
        handle: (user as any).handle || null,
        email_verified: (user as any).email_verified || false,
        phone_verified: (user as any).phone_verified || false,
        address: address ? {
          country: address.country || "",
          line1: address.address_line1 || "",
          line2: address.address_line2 || "",
          city: address.city || "",
          state: address.state || "",
          postal_code: address.postal_code || "",
        } : null,
        emergency_contact: {
          name: user.emergency_contact_name || "",
          relationship: user.emergency_contact_relationship || "",
          language: user.preferred_language || "",
          email: (user as any).emergency_contact_email || "",
          country_code: (user as any).emergency_contact_country_code || "",
          phone: user.emergency_contact_phone || "",
        },
        identity_verified: verificationStatus === 'approved',
        identity_verification_status: verificationStatus,
        identity_verification_submitted_at: verification?.submitted_at || null,
        identity_verification_rejection_reason: verification?.rejection_reason || null,
        identity_verification_document_url: verification?.document_url || null,
        identity_verification_document_type: verification?.document_type || null,
        identity_verification_id: verification?.id || null,
        beauty_preferences: profilePrefs?.beauty_preferences || {},
        privacy_settings: profilePrefs?.privacy_settings || { services_booked_visible: false },
      } as ProfileUser;
    }

    // Process profile data
    let profileData: ProfileData | null = null;
    let fullProfileData: any = null;
    if (profileResult.status === "fulfilled" && profileResult.value.data) {
      fullProfileData = profileResult.value.data;
      profileData = {
        about: fullProfileData.about || null,
        interests: fullProfileData.interests || null,
      };
    }

    // Calculate completion data
    let completionData: CompletionData | null = null;
    if (userResult.status === "fulfilled" && userResult.value.data) {
      completionData = await calculateCompletionData(
        supabase,
        user.id,
        userResult.value.data,
        fullProfileData
      );
    }

    return {
      user: userData,
      profileData,
      completionData,
    };
  } catch (error) {
    console.error("Error fetching profile data:", error);
    return {
      user: null,
      profileData: null,
      completionData: null,
    };
  }
}

export default async function ProfilePage() {
  const { user, profileData, completionData } = await getProfileData();

  return (
    <AuthGuard>
      <div className="min-h-screen bg-zinc-50/50 pb-20 md:pb-0">
