"use client";

import React, { useState, useEffect } from "react";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { TrendingUp, TrendingDown, DollarSign, Calendar, Users, Package } from "lucide-react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { PageHeader } from "@/components/provider/PageHeader";
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from "recharts";

interface AnalyticsData {
  revenue: {
    total: number;
    thisMonth: number;
    lastMonth: number;
    growth: string;
  };
  bookings: {
    total: number;
    thisMonth: number;
    lastMonth: number;
    upcoming: number;
    growth: string;
  };
  customers: {
    total: number;
    repeat: number;
    new: number;
  };
  services: Array<{
    name: string;
    count: number;
    revenue: number;
  }>;
  trends: Array<{
    month: string;
    revenue: number;
    bookings: number;
  }>;
}

export default function ProviderAnalyticsPage() {
  const [analytics, setAnalytics] = useState<AnalyticsData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [period, setPeriod] = useState<"month" | "week" | "year">("month");

  useEffect(() => {
    loadAnalytics();
  }, [period]);

  const loadAnalytics = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const response = await fetcher.get<{ data: AnalyticsData }>(
        `/api/provider/analytics?period=${period}`,
        { timeoutMs: 30000 } // 30 second timeout
      );
      setAnalytics(response.data);
    } catch (err) {
      setError(err instanceof FetchError ? err.message : "Failed to load analytics");
      console.error("Error loading analytics:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-ZA", {
      style: "currency",
      currency: "ZAR",
    }).format(amount);
  };

  if (isLoading) {
    return (
      <SettingsDetailLayout
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Analytics" },
        ]}
      >
        <LoadingTimeout loadingMessage="Loading analytics..." />
      </SettingsDetailLayout>
    );
  }

  if (error || !analytics) {
    return (
      <SettingsDetailLayout
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Analytics" },
        ]}
      >
        <div className="text-center py-8">
          <p className="text-red-600">{error || "Failed to load analytics"}</p>
        </div>
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      breadcrumbs={[
        { label: "Home", href: "/" },
        { label: "Provider", href: "/provider" },
        { label: "Analytics" },
      ]}
      showCloseButton={false}
    >
      <div className="space-y-6">
        <PageHeader
          title="Analytics Dashboard"
          subtitle="Track your business performance and growth"
          actions={
            <div className="flex gap-2">
              <button
                onClick={() => setPeriod("week")}
                className={`px-4 py-2 rounded text-sm font-medium transition-colors ${
                  period === "week" 
                    ? "bg-[#FF0077] text-white" 
                    : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                }`}
              >
                Week
              </button>
              <button
                onClick={() => setPeriod("month")}
                className={`px-4 py-2 rounded text-sm font-medium transition-colors ${
                  period === "month" 
                    ? "bg-[#FF0077] text-white" 
                    : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                }`}
              >
                Month
              </button>
              <button
                onClick={() => setPeriod("year")}
                className={`px-4 py-2 rounded text-sm font-medium transition-colors ${
                  period === "year" 
                    ? "bg-[#FF0077] text-white" 
                    : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                }`}
              >
                Year
              </button>
            </div>
          }
        />

        {/* Key Metrics */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Revenue</CardTitle>
              <DollarSign className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatCurrency(analytics.revenue.total)}</div>
              <p className="text-xs text-muted-foreground">
                This month: {formatCurrency(analytics.revenue.thisMonth)}
                {analytics.revenue.lastMonth > 0 && (
                  <span className="ml-2">ΓÇó Last month: {formatCurrency(analytics.revenue.lastMonth)}</span>
                )}
              </p>
              <div className="flex items-center mt-2">
                {analytics.revenue.growth === "New" || (analytics.revenue.growth !== "0" && parseFloat(analytics.revenue.growth) >= 0) ? (
                  <TrendingUp className="h-4 w-4 text-green-600 mr-1" />
                ) : analytics.revenue.growth === "0" ? null : (
                  <TrendingDown className="h-4 w-4 text-red-600 mr-1" />
                )}
                <span className={`text-xs ${
                  analytics.revenue.growth === "New" || (analytics.revenue.growth !== "0" && parseFloat(analytics.revenue.growth) >= 0)
                    ? "text-green-600"
                    : analytics.revenue.growth === "0"
                    ? "text-gray-600"
                    : "text-red-600"
                }`}>
                  {analytics.revenue.growth === "New" 
                    ? "New revenue this month" 
                    : `${analytics.revenue.growth}% vs last month`}
                </span>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Bookings</CardTitle>
              <Calendar className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{analytics.bookings.total}</div>
              <p className="text-xs text-muted-foreground">
                This month: {analytics.bookings.thisMonth} ΓÇó Upcoming: {analytics.bookings.upcoming}
                {analytics.bookings.lastMonth > 0 && (
                  <span className="ml-2">ΓÇó Last month: {analytics.bookings.lastMonth}</span>
                )}
              </p>
              <div className="flex items-center mt-2">
                {analytics.bookings.growth === "New" || (analytics.bookings.growth !== "0" && parseFloat(analytics.bookings.growth) >= 0) ? (
                  <TrendingUp className="h-4 w-4 text-green-600 mr-1" />
                ) : analytics.bookings.growth === "0" ? null : (
                  <TrendingDown className="h-4 w-4 text-red-600 mr-1" />
                )}
                <span className={`text-xs ${
                  analytics.bookings.growth === "New" || (analytics.bookings.growth !== "0" && parseFloat(analytics.bookings.growth) >= 0)
                    ? "text-green-600"
                    : analytics.bookings.growth === "0"
                    ? "text-gray-600"
                    : "text-red-600"
                }`}>
                  {analytics.bookings.growth === "New" 
                    ? "New bookings this month" 
                    : `${analytics.bookings.growth}% vs last month`}
                </span>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Customers</CardTitle>
              <Users className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{analytics.customers.total}</div>
              <p className="text-xs text-muted-foreground">
                Repeat: {analytics.customers.repeat} ΓÇó New: {analytics.customers.new}
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Top Services</CardTitle>
              <Package className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{analytics.services.length}</div>
              <p className="text-xs text-muted-foreground">
                {analytics.services[0]?.name || "N/A"}
              </p>
            </CardContent>
          </Card>
        </div>

        {/* Revenue Trends Chart */}
        <Card className="mb-6">
          <CardHeader>
            <CardTitle>Revenue Trends (Last 12 Months)</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={300}>
              <LineChart data={analytics.trends}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="month" />
                <YAxis />
                <Tooltip formatter={(value: number) => formatCurrency(value)} />
                <Legend />
                <Line type="monotone" dataKey="revenue" stroke="#FF0077" strokeWidth={2} name="Revenue" />
              </LineChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>

        {/* Bookings Trends Chart */}
        <Card className="mb-6">
          <CardHeader>
            <CardTitle>Booking Trends (Last 12 Months)</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={analytics.trends}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="month" />
                <YAxis />
                <Tooltip />
                <Legend />
                <Bar dataKey="bookings" fill="#FF0077" name="Bookings" />
              </BarChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>

        {/* Top Services */}
        <Card>
          <CardHeader>
            <CardTitle>Top Performing Services</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {analytics.services.slice(0, 10).map((service, index) => (
                <div key={index} className="flex justify-between items-center p-3 border rounded-lg">
                  <div>
                    <p className="font-medium">{service.name}</p>
                    <p className="text-sm text-gray-600">{service.count} bookings</p>
                  </div>
                  <p className="font-semibold">{formatCurrency(service.revenue)}</p>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { Appointment, FilterParams, PaginationParams, TeamMember, ServiceItem, Salon } from "@/lib/provider-portal/types";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { AppointmentStatusBadge } from "@/components/provider-portal/AppointmentStatusBadge";
import { Money } from "@/components/provider-portal/Money";
import { YocoPaymentDialog } from "@/components/provider-portal/YocoPaymentDialog";
import { Search, Filter, CreditCard, Plus } from "lucide-react";
import Pagination from "@/components/ui/pagination";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { SyncIndicator } from "@/components/provider/SyncIndicator";
import type { YocoPayment } from "@/lib/provider-portal/types";
import { openViewMode } from "@/stores/appointment-sidebar-store";
import { AppointmentSidebar } from "@/components/appointments";

export default function ProviderAppointments() {
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [lastSynced, setLastSynced] = useState<Date | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [dateRange, setDateRange] = useState<string>("month");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [yocoDialogOpen, setYocoDialogOpen] = useState(false);
  const [selectedAppointment, setSelectedAppointment] = useState<Appointment | null>(null);
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [services, setServices] = useState<ServiceItem[]>([]);
  const [locations, setLocations] = useState<Salon[]>([]);

  useEffect(() => {
    loadAppointments();
    loadSidebarData();
  }, [page, statusFilter, dateRange]);

  const loadSidebarData = async () => {
    try {
      const [teamMembers, services, locations] = await Promise.all([
        providerApi.listTeamMembers(),
        providerApi.listServices(),
        providerApi.getSalons(),
      ]);
      setTeamMembers(teamMembers || []);
      setServices(services || []);
      setLocations(locations || []);
    } catch (error) {
      console.error("Failed to load sidebar data:", error);
      // Set empty arrays as fallback
      setTeamMembers([]);
      setServices([]);
      setLocations([]);
    }
  };

  const loadAppointments = async (isBackground = false) => {
    try {
      if (!isBackground) {
        setIsLoading(true);
      } else {
        setIsRefreshing(true);
      }
      const filters: FilterParams = {
        search: searchQuery || undefined,
        status: statusFilter !== "all" ? statusFilter : undefined,
      };

      if (dateRange === "month") {
        const now = new Date();
        filters.date_from = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split("T")[0];
        filters.date_to = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split("T")[0];
      }

      const pagination: PaginationParams = { page, limit: 20 };
      const response = await providerApi.listAppointments(filters, pagination);
      setAppointments(response.data);
      setTotalPages(response.total_pages);
      setLastSynced(new Date());
    } catch (error) {
      console.error("Failed to load appointments:", error);
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  };

  const handleSearch = () => {
    setPage(1);
    loadAppointments();
  };

  const handleYocoPayment = (appointment: Appointment) => {
    setSelectedAppointment(appointment);
    setYocoDialogOpen(true);
  };

  const handlePaymentSuccess = (_payment: YocoPayment) => {
    // Reload appointments to reflect payment status
    loadAppointments(false);
  };

  const handleAppointmentClick = (appointment: Appointment) => {
    openViewMode(appointment);
  };

  // Check if payment button should be shown (only when payment is pending or not paid, and not cancelled)
  const shouldShowPaymentButton = (appointment: Appointment) => {
    // Don't show payment button for cancelled appointments (check multiple variations)
    const status = appointment.status?.toLowerCase().trim();
    if (status === "cancelled" || status === "canceled") {
      return false;
    }

    // Don't show if already paid
    const paymentStatus = appointment.payment_status?.toLowerCase().trim();
    if (paymentStatus === "paid") {
      return false;
    }

    // Show button for pending or unpaid bookings that are not cancelled
    return paymentStatus === "pending" || !paymentStatus;
  };

  // Auto-refresh appointments every 30 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      loadAppointments(true); // Background refresh
    }, 30000);
    return () => clearInterval(interval);
  }, []);

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading appointments..." />;
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Breadcrumbs */}
      <nav className="bg-white border-b border-gray-200 px-4 sm:px-6 lg:px-8">
        <div className="flex items-center space-x-2 py-3 text-sm">
          <a href="/provider/dashboard" className="text-gray-500 hover:text-gray-700 transition-colors">
            Dashboard
          </a>
          <span className="text-gray-400">/</span>
          <span className="text-gray-900 font-medium">Appointments</span>
        </div>
      </nav>

      <div className="px-4 sm:px-6 lg:px-8 py-6">
        {/* Header with Add Button */}
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-2xl font-semibold text-gray-900">Appointments</h1>
            <p className="mt-1 text-sm text-gray-500">Manage your appointments and bookings</p>
          </div>
          <Button 
            onClick={() => {
              window.dispatchEvent(new CustomEvent('open-appointment-sidebar'));
            }}
            className="bg-[#FF0077] hover:bg-[#E6006B] text-white shadow-sm"
          >
            <Plus className="w-4 h-4 mr-2" />
            New Appointment
          </Button>
        </div>

        {/* Sync Indicator */}
      <div className="mb-4 flex items-center justify-between">
        <SyncIndicator 
          isSyncing={isRefreshing} 
          lastSynced={lastSynced}
          size="sm"
        />
      </div>

        {/* Filters */}
        <div className="mb-6 flex flex-col md:flex-row gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
          <Input
            placeholder="Search by client, service, or ref number..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && handleSearch()}
            className="pl-10"
          />
        </div>
        <Select value={dateRange} onValueChange={setDateRange}>
          <SelectTrigger className="w-full md:w-48">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="today">Today</SelectItem>
            <SelectItem value="week">This Week</SelectItem>
            <SelectItem value="month">Month to Date</SelectItem>
            <SelectItem value="custom">Custom Range</SelectItem>
          </SelectContent>
        </Select>
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-full md:w-48">
            <SelectValue placeholder="Status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Statuses</SelectItem>
            <SelectItem value="booked">Booked</SelectItem>
            <SelectItem value="started">Started</SelectItem>
            <SelectItem value="completed">Completed</SelectItem>
            <SelectItem value="cancelled">Cancelled</SelectItem>
          </SelectContent>
        </Select>
        <Button variant="outline">
          <Filter className="w-4 h-4 mr-2" />
          Filter
        </Button>
      </div>

      {/* Table - Mobile Card View, Desktop Table View */}
      {appointments.length === 0 ? (
        <EmptyState
          title="No appointments found"
          description="Appointments will appear here when you have bookings"
        />
      ) : (
        <>
          {/* Desktop table view */}
          <div className="hidden md:block bg-white border border-gray-200 rounded-xl overflow-hidden shadow-sm">
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow className="bg-gray-50">
                    <TableHead className="font-semibold">Ref #</TableHead>
                    <TableHead className="font-semibold">Client</TableHead>
                    <TableHead className="font-semibold">Service</TableHead>
                    <TableHead className="font-semibold">Date & Time</TableHead>
                    <TableHead className="font-semibold">Team Member</TableHead>
                    <TableHead className="font-semibold">Price</TableHead>
                    <TableHead className="font-semibold">Status</TableHead>
                    <TableHead className="text-right font-semibold">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {appointments.map((apt) => (
                    <TableRow 
                      key={apt.id}
                      className="cursor-pointer hover:bg-gray-50 transition-colors"
                      onClick={() => handleAppointmentClick(apt)}
                    >
                      <TableCell className="font-medium text-blue-600">{apt.ref_number}</TableCell>
                      <TableCell>
                        <div>
                          <div className="font-medium">{apt.client_name}</div>
                          <div className="text-xs text-gray-500">by {apt.created_by}</div>
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="max-w-[200px] truncate" title={apt.service_name}>
                          {apt.service_name}
                        </div>
                      </TableCell>
                      <TableCell>
                        <div>
                          <div className="font-medium">{apt.scheduled_date}</div>
                          <div className="text-xs text-gray-500">{apt.scheduled_time} ({apt.duration_minutes}min)</div>
                        </div>
                      </TableCell>
                      <TableCell>
                        <span className={apt.team_member_name ? "font-medium" : "text-gray-400 italic"}>
                          {apt.team_member_name || "Unassigned"}
                        </span>
                      </TableCell>
                      <TableCell>
                        <Money amount={apt.price} className="font-semibold" />
                      </TableCell>
                      <TableCell>
                        <AppointmentStatusBadge status={apt.status} />
                      </TableCell>
                      <TableCell className="text-right" onClick={(e) => e.stopPropagation()}>
                        {shouldShowPaymentButton(apt) ? (
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleYocoPayment(apt)}
                            className="gap-2"
                          >
                            <CreditCard className="w-3 h-3" />
                            Pay
                          </Button>
                        ) : (
                          <span className="text-sm text-green-600 font-medium">Γ£ô Paid</span>
                        )}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </div>

          {/* Mobile card view */}
          <div className="md:hidden space-y-3">
            {appointments.map((apt) => (
              <div 
                key={apt.id} 
                className="bg-white border border-gray-200 rounded-xl p-4 space-y-3 cursor-pointer hover:shadow-md transition-all shadow-sm"
                onClick={() => handleAppointmentClick(apt)}
              >
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <p className="font-semibold text-lg">{apt.client_name}</p>
                    <p className="text-xs text-gray-500 mt-1">
                      {apt.ref_number} ΓÇó {apt.created_by}
                    </p>
                  </div>
                  <AppointmentStatusBadge status={apt.status} />
                </div>

                <div className="grid grid-cols-2 gap-2 text-sm py-2 border-t border-gray-100">
                  <div>
                    <span className="text-gray-500 text-xs">Service</span>
                    <p className="font-medium truncate" title={apt.service_name}>{apt.service_name}</p>
                  </div>
                  <div>
                    <span className="text-gray-500 text-xs">Team Member</span>
                    <p className={apt.team_member_name ? "font-medium" : "text-gray-400 italic"}>
                      {apt.team_member_name || "Unassigned"}
                    </p>
                  </div>
                  <div>
                    <span className="text-gray-500 text-xs">Date</span>
                    <p className="font-medium">{apt.scheduled_date}</p>
                  </div>
                  <div>
                    <span className="text-gray-500 text-xs">Time</span>
                    <p className="font-medium">{apt.scheduled_time}</p>
                  </div>
                </div>

                <div className="flex items-center justify-between pt-2 border-t border-gray-100">
                  <div>
                    <span className="text-xs text-gray-500">Total</span>
                    <p className="font-bold text-lg"><Money amount={apt.price} /></p>
                  </div>
                  {shouldShowPaymentButton(apt) ? (
                    <Button
                      variant="outline"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleYocoPayment(apt);
                      }}
                      className="min-h-[44px] gap-2"
                    >
                      <CreditCard className="w-4 h-4" />
                      Pay
                    </Button>
                  ) : (
                    <span className="text-sm text-green-600 font-medium">Γ£ô Paid</span>
                  )}
                </div>
              </div>
            ))}
          </div>

          {totalPages > 1 && (
            <div className="mt-4">
              <Pagination
                currentPage={page}
                totalPages={totalPages}
                onPageChange={setPage}
              />
            </div>
          )}
        </>
      )}

      {selectedAppointment && (
        <YocoPaymentDialog
          open={yocoDialogOpen}
          onOpenChange={setYocoDialogOpen}
          amount={selectedAppointment.price}
          appointmentId={selectedAppointment.id}
          onSuccess={handlePaymentSuccess}
        />
      )}

        {/* Appointment Sidebar - full detail view with payment collection */}
        <AppointmentSidebar
          teamMembers={teamMembers}
          services={services}
          locations={locations}
          onAppointmentCreated={() => loadAppointments()}
          onAppointmentUpdated={() => loadAppointments()}
          onAppointmentDeleted={() => loadAppointments()}
        />
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Calendar,
  Clock,
  User,
  MapPin,
  Phone,
  Mail,
  DollarSign,
  CheckCircle2,
  XCircle,
} from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import type { Booking, AdditionalCharge } from "@/types/beautonomi";
import { toast } from "sonner";
import Link from "next/link";
import { BookingAuditLog } from "@/components/provider/BookingAuditLog";
import { BookingConflictAlert } from "@/components/provider/BookingConflictAlert";
import { SafetyPanicButton } from "@/components/safety/SafetyPanicButton";

export default function ProviderBookingDetail() {
  const params = useParams();
  const router = useRouter();
  const bookingId = params.id as string;

  const [booking, setBooking] = useState<Booking | null>(null);
  const [additionalCharges, setAdditionalCharges] = useState<AdditionalCharge[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isUpdating, setIsUpdating] = useState(false);
  const [chargeDescription, setChargeDescription] = useState("");
  const [chargeAmount, setChargeAmount] = useState<string>("");
  const [isRequestingCharge, setIsRequestingCharge] = useState(false);
  const [conflictError, setConflictError] = useState<string | null>(null);

  // Reschedule state
  const [showReschedule, setShowReschedule] = useState(false);
  const [rescheduleDate, setRescheduleDate] = useState("");
  const [rescheduleTime, setRescheduleTime] = useState("");
  const [isRescheduling, setIsRescheduling] = useState(false);

  // Mark paid state
  const [showMarkPaid, setShowMarkPaid] = useState(false);
  const [markPaidMethod, setMarkPaidMethod] = useState("cash");
  const [isMarkingPaid, setIsMarkingPaid] = useState(false);

  // Refund state
  const [showRefund, setShowRefund] = useState(false);
  const [refundAmount, setRefundAmount] = useState("");
  const [isRefunding, setIsRefunding] = useState(false);

  // Notes state
  const [editingNotes, setEditingNotes] = useState(false);
  const [notesText, setNotesText] = useState("");
  const [isSavingNotes, setIsSavingNotes] = useState(false);

  // Provider forms (for labelling form responses)
  const [providerForms, setProviderForms] = useState<Array<{ id: string; title: string; fields: Array<{ id: string; name: string }> }>>([]);

  useEffect(() => {
    loadBooking();
    loadAdditionalCharges();
  }, [bookingId]);

  useEffect(() => {
    if (!booking?.provider_form_responses || Object.keys(booking.provider_form_responses).length === 0) return;
    fetcher.get<{ data: Array<{ id: string; title: string; fields?: Array<{ id: string; name: string }> }> }>("/api/provider/forms")
      .then((res) => {
        const list = (res as { data?: Array<{ id: string; title: string; fields?: Array<{ id: string; name: string }> }> })?.data ?? [];
        setProviderForms(list.map((f) => ({ id: f.id, title: f.title, fields: f.fields ?? [] })));
      })
      .catch((err) => {
        if (process.env.NODE_ENV === "development") console.warn("[Provider booking] Failed to load forms list", err);
      });
  }, [booking?.provider_form_responses]);

  const loadBooking = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetcher.get<{ data: Booking }>(
        `/api/provider/bookings/${bookingId}`
      );
      setBooking(response.data);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load booking";
      setError(errorMessage);
      console.error("Error loading booking:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const loadAdditionalCharges = async () => {
    try {
      const response = await fetcher.get<{ data: { charges: AdditionalCharge[] } }>(
        `/api/provider/bookings/${bookingId}/additional-charges`
      );
      setAdditionalCharges(response.data.charges || []);
    } catch (err) {
      console.error("Error loading additional charges:", err);
    }
  };

  const handleStatusChange = async (newStatus: string) => {
    if (!booking) return;

    try {
      setIsUpdating(true);
      setConflictError(null);
      const response = await fetcher.patch<{ booking: Booking; conflict?: boolean }>(
        `/api/provider/bookings/${bookingId}`,
        {
          status: newStatus,
          version: (booking as any).version, // Include version for conflict detection
        }
      );

      if (response.conflict) {
        setConflictError("This booking was modified by another user. Please refresh and try again.");
        toast.error("Conflict detected. Please refresh and try again.");
        return;
      }

      setBooking({ ...booking, status: newStatus as any, ...response.booking });
      toast.success("Booking status updated");
      loadBooking(); // Reload to get latest version
    } catch (error) {
      if (error instanceof FetchError && error.status === 409) {
        setConflictError("This booking was modified by another user. Please refresh and try again.");
        toast.error("Conflict detected. Please refresh and try again.");
      } else {
        toast.error("Failed to update booking status");
      }
    } finally {
      setIsUpdating(false);
    }
  };

  const handleRequestAdditionalCharge = async () => {
    if (!chargeDescription.trim()) {
      toast.error("Please enter a description");
      return;
    }
    const amountNum = Number(chargeAmount);
    if (!Number.isFinite(amountNum) || amountNum <= 0) {
      toast.error("Please enter a valid amount");
      return;
    }

    try {
      setIsRequestingCharge(true);
      await fetcher.post(`/api/provider/bookings/${bookingId}/request-payment`, {
        description: chargeDescription.trim(),
        amount: amountNum,
      });
      toast.success("Additional payment requested");
      setChargeDescription("");
      setChargeAmount("");
      loadAdditionalCharges();
    } catch (err) {
      toast.error(err instanceof FetchError ? err.message : "Failed to request payment");
    } finally {
      setIsRequestingCharge(false);
    }
  };

  const handleReschedule = async () => {
    if (!rescheduleDate || !rescheduleTime) {
      toast.error("Please select both date and time");
      return;
    }
    try {
      setIsRescheduling(true);
      await fetcher.patch(`/api/provider/bookings/${bookingId}`, {
        scheduled_at: `${rescheduleDate}T${rescheduleTime}:00`,
        version: (booking as any)?.version,
      });
      toast.success("Booking rescheduled");
      setShowReschedule(false);
      loadBooking();
    } catch (err) {
      if (err instanceof FetchError && err.status === 409) {
        setConflictError("This booking was modified. Please refresh and try again.");
      } else {
        toast.error("Failed to reschedule");
      }
    } finally {
      setIsRescheduling(false);
    }
  };

  const handleMarkPaid = async () => {
    try {
      setIsMarkingPaid(true);
      await fetcher.post(`/api/provider/bookings/${bookingId}/mark-paid`, {
        payment_method: markPaidMethod,
      });
      toast.success("Booking marked as paid");
      setShowMarkPaid(false);
      loadBooking();
    } catch (err) {
      toast.error(err instanceof FetchError ? err.message : "Failed to mark as paid");
    } finally {
      setIsMarkingPaid(false);
    }
  };

  const handleRefund = async () => {
    const amount = parseFloat(refundAmount);
    if (!Number.isFinite(amount) || amount <= 0) {
      toast.error("Please enter a valid refund amount");
      return;
    }
    try {
      setIsRefunding(true);
      await fetcher.post(`/api/provider/bookings/${bookingId}/refund`, {
        amount,
      });
      toast.success("Refund processed");
      setShowRefund(false);
      setRefundAmount("");
      loadBooking();
    } catch (err) {
      toast.error(err instanceof FetchError ? err.message : "Failed to process refund");
    } finally {
      setIsRefunding(false);
    }
  };

  const handleSaveNotes = async () => {
    try {
      setIsSavingNotes(true);
      await fetcher.patch(`/api/provider/bookings/${bookingId}`, {
        special_requests: notesText,
        version: (booking as any)?.version,
      });
      toast.success("Notes saved");
      setEditingNotes(false);
      loadBooking();
    } catch {
      toast.error("Failed to save notes");
    } finally {
      setIsSavingNotes(false);
    }
  };

  const isActive = ["pending", "booked", "confirmed"].includes(booking?.status ?? "");
  const isStarted = ["started", "in_progress"].includes(booking?.status ?? "");
  const totalPaid = (booking as any)?.total_paid ?? 0;
  const totalRefunded = (booking as any)?.total_refunded ?? 0;
  const totalAmount = (booking as any)?.total_amount ?? 0;
  const outstanding = totalAmount - totalPaid + totalRefunded;
  const canMarkPaid = outstanding > 0 && (booking?.status === "completed" || isStarted);
  const canRefund = totalPaid > 0 && totalRefunded < totalPaid;

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading booking details..." />
      </div>
    );
  }

  if (error || !booking) {
    return (
      <div className="container mx-auto px-4 py-8">
        <EmptyState
          title="Booking not found"
          description={error || "The booking you're looking for doesn't exist"}
          action={{
            label: "Go Back",
            onClick: () => router.push("/provider/bookings"),
          }}
        />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["provider_owner", "provider_staff"]}>
      <div className="container mx-auto px-4 py-8 max-w-4xl">
        <div className="mb-6 flex items-center justify-between flex-wrap gap-2">
          <Link
            href="/provider/bookings"
            className="text-sm text-gray-600 hover:text-gray-900"
          >
            ΓåÉ Back to Bookings
          </Link>
          <div className="flex items-center gap-2">
            <SafetyPanicButton bookingId={bookingId} variant="outline" size="sm" />
            <BookingAuditLog bookingId={bookingId} />
          </div>
        </div>

        {/* Conflict Alert */}
        {conflictError && (
          <BookingConflictAlert
            conflictMessage={conflictError}
            onRefresh={() => {
              setConflictError(null);
              loadBooking();
            }}
            onDismiss={() => setConflictError(null)}
          />
        )}

        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-3xl font-semibold mb-2">
              Booking #{booking.booking_number}
            </h1>
            <span
              className={`inline-block px-3 py-1 rounded-full text-sm font-medium ${
                booking.status === "confirmed"
                  ? "bg-green-100 text-green-800"
                  : booking.status === "pending"
                  ? "bg-yellow-100 text-yellow-800"
                  : booking.status === "cancelled"
                  ? "bg-red-100 text-red-800"
                  : "bg-blue-100 text-blue-800"
              }`}
            >
              {booking.status}
            </span>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
          {/* Customer Info */}
          <div className="bg-white border rounded-lg p-6">
            <h2 className="text-xl font-semibold mb-4">Customer Information</h2>
            <div className="space-y-4">
              <div>
                <p className="text-sm text-gray-600">Name</p>
                <p className="font-medium">{(booking as any).customer_name || "Guest"}</p>
              </div>
              {(booking as any).customer_phone && (
                <div className="flex items-center gap-2">
                  <Phone className="w-4 h-4 text-gray-400" />
                  <a
                    href={`tel:${(booking as any).customer_phone}`}
                    className="text-blue-600 hover:underline"
                  >
                    {(booking as any).customer_phone}
                  </a>
                </div>
              )}
              {(booking as any).customer_email && (
                <div className="flex items-center gap-2">
                  <Mail className="w-4 h-4 text-gray-400" />
                  <a
                    href={`mailto:${(booking as any).customer_email}`}
                    className="text-blue-600 hover:underline"
                  >
                    {(booking as any).customer_email}
                  </a>
                </div>
              )}
            </div>
          </div>

          {/* Booking Details */}
          <div className="bg-white border rounded-lg p-6">
            <h2 className="text-xl font-semibold mb-4">Booking Details</h2>
            <div className="space-y-4">
              <div className="flex items-start gap-3">
                <Calendar className="w-5 h-5 text-gray-400 mt-0.5" />
                <div>
                  <p className="text-sm text-gray-600">Date</p>
                  <p className="font-medium">
                    {new Date(booking.scheduled_at).toLocaleDateString("en-US", {
                      weekday: "long",
                      year: "numeric",
                      month: "long",
                      day: "numeric",
                    })}
                  </p>
                </div>
              </div>
              <div className="flex items-start gap-3">
                <Clock className="w-5 h-5 text-gray-400 mt-0.5" />
                <div>
                  <p className="text-sm text-gray-600">Time</p>
                  <p className="font-medium">
                    {new Date(booking.scheduled_at).toLocaleTimeString("en-US", {
                      hour: "2-digit",
                      minute: "2-digit",
                    })}
                  </p>
                </div>
              </div>
              <div className="flex items-start gap-3">
                <MapPin className="w-5 h-5 text-gray-400 mt-0.5" />
                <div className="flex-1">
                  <p className="text-sm text-gray-600">Location</p>
                  {booking.location_type === "at_salon" ? (
                    <p className="font-medium">
                      {(booking as any).location_name || "At Salon"}
                    </p>
                  ) : booking.address ? (
                    <div className="space-y-1">
                      <p className="font-medium">
                        {booking.address.line1}
                        {booking.address.line2 && `, ${booking.address.line2}`}
                      </p>
                      {booking.address.apartment_unit && (
                        <p className="text-sm text-gray-600">Unit: {booking.address.apartment_unit}</p>
                      )}
                      {booking.address.building_name && (
                        <p className="text-sm text-gray-600">Building: {booking.address.building_name}</p>
                      )}
                      {booking.address.floor_number && (
                        <p className="text-sm text-gray-600">Floor: {booking.address.floor_number}</p>
                      )}
                      <p className="text-sm text-gray-600">
                        {booking.address.city}
                        {booking.address.state && `, ${booking.address.state}`}
                        {booking.address.postal_code && ` ${booking.address.postal_code}`}
                      </p>
                      <p className="text-sm text-gray-600">{booking.address.country}</p>
                      {booking.address.access_codes && (
                        <div className="mt-2 pt-2 border-t border-gray-200 space-y-1">
                          <p className="text-xs font-medium text-gray-700">Access Codes:</p>
                          {typeof booking.address.access_codes === 'object' && (
                            <>
                              {booking.address.access_codes.gate && (
                                <p className="text-xs text-gray-600">Gate: {booking.address.access_codes.gate}</p>
                              )}
                              {booking.address.access_codes.buzzer && (
                                <p className="text-xs text-gray-600">Buzzer: {booking.address.access_codes.buzzer}</p>
                              )}
                              {booking.address.access_codes.door && (
                                <p className="text-xs text-gray-600">Door: {booking.address.access_codes.door}</p>
                              )}
                            </>
                          )}
                        </div>
                      )}
                      {booking.address.parking_instructions && (
                        <div className="mt-2 pt-2 border-t border-gray-200">
                          <p className="text-xs font-medium text-gray-700">Parking:</p>
                          <p className="text-xs text-gray-600">{booking.address.parking_instructions}</p>
                        </div>
                      )}
                      {booking.address.location_landmarks && (
                        <div className="mt-2 pt-2 border-t border-gray-200">
                          <p className="text-xs font-medium text-gray-700">Landmarks:</p>
                          <p className="text-xs text-gray-600">{booking.address.location_landmarks}</p>
                        </div>
                      )}
                      {booking.address.latitude && booking.address.longitude && (
                        <a
                          href={`https://www.google.com/maps?q=${booking.address.latitude},${booking.address.longitude}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-xs text-blue-600 hover:underline mt-1 inline-block"
                        >
                          View on Google Maps ΓåÆ
                        </a>
                      )}
                    </div>
                  ) : (
                    <p className="font-medium">At customer location</p>
                  )}
                </div>
              </div>
              {(booking as any).staff_name && (
                <div className="flex items-start gap-3">
                  <User className="w-5 h-5 text-gray-400 mt-0.5" />
                  <div>
                    <p className="text-sm text-gray-600">Assigned Staff</p>
                    <p className="font-medium">{(booking as any).staff_name}</p>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Services */}
        <div className="bg-white border rounded-lg p-6 mb-6">
          <h2 className="text-xl font-semibold mb-4">Services</h2>
          <div className="space-y-3">
            {booking.services?.map((service, index) => (
              <div
                key={index}
                className="flex justify-between items-center py-3 border-b last:border-0"
              >
                <div>
                  <p className="font-medium">{(service as any).offering_name || "Service"}</p>
                  {(service as any).duration && (
                    <p className="text-sm text-gray-600">{(service as any).duration} mins</p>
                  )}
                </div>
                {(service as any).price && (
                  <p className="font-medium">
                    {booking.currency} {((service as any).price).toFixed(2)}
                  </p>
                )}
              </div>
            ))}
            {(!booking.services || booking.services.length === 0) && (
              <p className="text-sm text-gray-500">No services</p>
            )}
          </div>
        </div>

        {/* Products */}
        {booking.products && booking.products.length > 0 && (
          <div className="bg-white border rounded-lg p-6 mb-6">
            <h2 className="text-xl font-semibold mb-4">Products</h2>
            <div className="space-y-3">
              {booking.products.map((product: any, index: number) => (
                <div
                  key={product.id || index}
                  className="flex justify-between items-center py-3 border-b last:border-0"
                >
                  <div>
                    <p className="font-medium">{product.product_name || "Product"}</p>
                    <p className="text-sm text-gray-600">Quantity: {product.quantity}</p>
                  </div>
                  <p className="font-medium">
                    {booking.currency} {product.total_price.toFixed(2)}
                  </p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Special Requests & House Call Instructions */}
        {(booking.special_requests || (booking as any).house_call_instructions) && (
          <div className="bg-white border rounded-lg p-6 mb-6">
            <h2 className="text-xl font-semibold mb-4">Special Instructions</h2>
            <div className="space-y-4">
              {booking.special_requests && (
                <div>
                  <p className="text-sm font-medium text-gray-700 mb-1">General Requests</p>
                  <p className="text-sm text-gray-600 whitespace-pre-wrap">{booking.special_requests}</p>
                </div>
