                      {m === "eft" ? "EFT" : m}
                    </Button>
                  ))}
                </div>
              </div>
              <div className="flex gap-3">
                <Button onClick={handleMarkPaid} disabled={isMarkingPaid} className="flex-1 bg-emerald-600 hover:bg-emerald-700">
                  {isMarkingPaid ? "Processing..." : "Confirm Payment"}
