                              <th className="text-left p-2 font-medium">Barcode</th>
                              <th className="text-left p-2 font-medium">Qty</th>
                              <th className="text-left p-2 font-medium">Supply (ZAR)</th>
                              <th className="text-left p-2 font-medium">Retail (ZAR)</th>
