            {/* Right Column - Photos */}
            <div className="space-y-6">
               <div className="bg-pink-50 rounded-xl p-6 text-center border-2 border-dashed border-pink-200 min-h-[400px] flex flex-col">
                  <h4 className="font-medium mb-4">Product Photo</h4>

                  {/* Main Photo */}
                  {formData.mainImageUrl ? (
                    <div className="relative mb-4 w-full h-64 rounded-lg overflow-hidden">
                      <Image
                        src={formData.mainImageUrl}
                        alt="Main product"
                        fill
                        className="object-cover rounded-lg"
                        unoptimized
                      />
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        className="absolute top-2 right-2 bg-white hover:bg-gray-100"
                        onClick={() => setFormData({ ...formData, mainImageUrl: "", imageUrls: formData.imageUrls.filter(url => url !== formData.mainImageUrl) })}
                      >
                        <X className="h-4 w-4" />
                      </Button>
                      <div className="mt-2">
                        <span className="text-xs bg-[#FF0077] text-white px-2 py-1 rounded">Main Photo</span>
                      </div>
                    </div>
                  ) : (
                    <div className="flex-1 flex flex-col items-center justify-center mb-4">
                      <div className="bg-[#FF0077] text-white rounded-full w-24 h-24 flex items-center justify-center mx-auto mb-4">
                        <Camera className="w-12 h-12" />
                      </div>
                      <input
                        type="file"
                        id="mainImageUpload"
                        accept="image/*"
                        className="hidden"
                        onChange={async (e) => {
                          const file = e.target.files?.[0];
                          if (file) {
                            await handleImageUpload(file, true);
                          }
                        }}
                        disabled={uploadingImages}
                      />
                      <Button 
                        type="button"
                        variant="outline" 
                        className="w-full mb-4"
                        onClick={() => document.getElementById("mainImageUpload")?.click()}
                        disabled={uploadingImages}
                      >
                        <Upload className="w-4 h-4 mr-2" />
                        {uploadingImages ? "Uploading..." : "Add Photo"}
                      </Button>
                    </div>
                  )}

                  {/* Additional Photos */}
                  <div className="grid grid-cols-2 gap-2 mt-4">
                    {formData.imageUrls
                      .filter((url) => url !== formData.mainImageUrl && !url.startsWith("data:"))
                      .slice(0, 2)
                      .map((url, index) => (
                        <div key={index} className="relative aspect-square bg-pink-100 rounded-lg overflow-hidden group">
                          <Image src={url} alt={`Product ${index + 2}`} fill className="object-cover" unoptimized />
                          <Button
                            type="button"
                            variant="ghost"
                            size="icon"
                            className="absolute top-1 right-1 bg-white/80 hover:bg-white opacity-0 group-hover:opacity-100 transition-opacity"
                            onClick={() => {
                              const newUrls = formData.imageUrls.filter((u) => u !== url);
                              const newMain = formData.mainImageUrl === url ? "" : formData.mainImageUrl;
                              setFormData({ ...formData, imageUrls: newUrls, mainImageUrl: newMain });
                            }}
                          >
                            <X className="h-3 w-3" />
                          </Button>
                        </div>
                      ))}
                    {formData.imageUrls.filter(url => url !== formData.mainImageUrl && !url.startsWith("data:")).length < 2 && (
                      <div 
                        className={`aspect-square bg-pink-100 rounded-lg flex flex-col items-center justify-center text-pink-500 cursor-pointer hover:bg-pink-200 transition-colors ${uploadingImages ? "opacity-50 cursor-not-allowed" : ""}`}
                        onClick={() => !uploadingImages && document.getElementById("additionalImageUpload")?.click()}
                      >
                        <Camera className="w-6 h-6 mb-1" />
                        <span className="text-xs">{uploadingImages ? "Uploading..." : "Add more Photos"}</span>
                      </div>
                    )}
                  </div>

                  <input
                    type="file"
                    id="additionalImageUpload"
                    accept="image/*"
                    className="hidden"
                    multiple
                    onChange={async (e) => {
                      const files = Array.from(e.target.files || []);
                      for (const file of files) {
                        await handleImageUpload(file, false);
                      }
                    }}
                    disabled={uploadingImages}
                  />
               </div>
            </div>
          </div>

          <div className="flex justify-end gap-2 pt-4 border-t sticky bottom-0 bg-white pb-4 z-10">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" className="bg-[#FF0077] hover:bg-[#D60565] min-w-[100px]">
              Save
            </Button>
          </div>
        </form>

        {/* Quick Create Brand Dialog */}
        <QuickDialog open={isBrandDialogOpen} onOpenChange={setIsBrandDialogOpen}>
          <QuickDialogContent>
            <QuickDialogHeader>
              <QuickDialogTitle>Add New Brand</QuickDialogTitle>
            </QuickDialogHeader>
            <div className="space-y-4 py-4">
              <div>
                <Label htmlFor="newBrandName">Brand Name</Label>
                <Input
                  id="newBrandName"
                  value={newBrandName}
                  onChange={(e) => setNewBrandName(e.target.value)}
                  placeholder="Enter brand name"
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      e.preventDefault();
                      handleCreateBrand();
                    }
                  }}
                />
              </div>
            </div>
            <QuickDialogFooter>
              <Button variant="outline" onClick={() => setIsBrandDialogOpen(false)}>
                Cancel
              </Button>
              <Button onClick={handleCreateBrand} className="bg-[#FF0077] hover:bg-[#D60565]">
                Add Brand
              </Button>
            </QuickDialogFooter>
          </QuickDialogContent>
        </QuickDialog>

        {/* Quick Create Supplier Dialog */}
        <QuickDialog open={isSupplierDialogOpen} onOpenChange={setIsSupplierDialogOpen}>
          <QuickDialogContent>
            <QuickDialogHeader>
              <QuickDialogTitle>Add New Supplier</QuickDialogTitle>
            </QuickDialogHeader>
            <div className="space-y-4 py-4">
              <div>
                <Label htmlFor="newSupplierName">Supplier Name</Label>
                <Input
                  id="newSupplierName"
                  value={newSupplierName}
                  onChange={(e) => setNewSupplierName(e.target.value)}
                  placeholder="Enter supplier name"
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      e.preventDefault();
                      handleCreateSupplier();
                    }
                  }}
                />
              </div>
            </div>
            <QuickDialogFooter>
              <Button variant="outline" onClick={() => setIsSupplierDialogOpen(false)}>
                Cancel
              </Button>
              <Button onClick={handleCreateSupplier} className="bg-[#FF0077] hover:bg-[#D60565]">
                Add Supplier
              </Button>
            </QuickDialogFooter>
          </QuickDialogContent>
        </QuickDialog>

        {/* Quick Create Product Category Dialog */}
        <QuickDialog open={isCategoryDialogOpen} onOpenChange={setIsCategoryDialogOpen}>
          <QuickDialogContent>
            <QuickDialogHeader>
              <QuickDialogTitle>Add New Product Category</QuickDialogTitle>
            </QuickDialogHeader>
            <div className="space-y-4 py-4">
              <div>
                <Label htmlFor="newCategoryName">Product Category Name</Label>
                <Input
                  id="newCategoryName"
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                  placeholder="Enter product category name"
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      e.preventDefault();
                      handleCreateCategory();
                    }
                  }}
                />
                <p className="text-xs text-gray-500 mt-1">
                  This category will be available for products only
                </p>
              </div>
            </div>
            <QuickDialogFooter>
              <Button variant="outline" onClick={() => setIsCategoryDialogOpen(false)}>
                Cancel
              </Button>
              <Button onClick={handleCreateCategory} className="bg-[#FF0077] hover:bg-[#D60565]">
                Add Product Category
              </Button>
            </QuickDialogFooter>
          </QuickDialogContent>
        </QuickDialog>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { ProductItem, FilterParams, PaginationParams } from "@/lib/provider-portal/types";
import { PageHeader } from "@/components/provider/PageHeader";
import { DataTableShell } from "@/components/provider/DataTableShell";
import { SectionCard } from "@/components/provider/SectionCard";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Money } from "@/components/provider-portal/Money";
import { Plus, MoreVertical, Upload, Edit, Copy, Archive, Trash2, Package, AlertTriangle, TrendingUp, TrendingDown, Search } from "lucide-react";
import Pagination from "@/components/ui/pagination";
import { Skeleton } from "@/components/ui/skeleton";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  DropdownMenuSeparator,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { ProductCreateEditDialog } from "./components/ProductCreateEditDialog";
import { ProductFiltersSheet } from "./components/ProductFiltersSheet";
import { toast } from "sonner";
import { fetcher } from "@/lib/http/fetcher";
import Breadcrumb from "@/components/ui/breadcrumb";
import { cn } from "@/lib/utils";

export default function ProviderProducts() {
  const [products, setProducts] = useState<ProductItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [debouncedSearchQuery, setDebouncedSearchQuery] = useState("");
  const [searchSuggestions, setSearchSuggestions] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [selectedProduct, setSelectedProduct] = useState<ProductItem | null>(null);
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [isFiltersOpen, setIsFiltersOpen] = useState(false);
  const [isStockDialogOpen, setIsStockDialogOpen] = useState(false);
  const [stockAction, setStockAction] = useState<"add" | "remove">("add");

  const [metrics, setMetrics] = useState({
    totalProducts: 0,
    lowStockProducts: 0,
    outOfStockProducts: 0,
    totalInventoryValue: 0,
  });

  // Inventory stats - use metrics from API
  const { totalProducts, lowStockProducts, outOfStockProducts, totalInventoryValue } = metrics;
  const productsArray = Array.isArray(products) ? products : [];

  // Debounce search query
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearchQuery(searchQuery);
    }, 300);

    return () => clearTimeout(timer);
  }, [searchQuery]);

  // Load products when debounced search query or page changes
  useEffect(() => {
    loadProducts();
    loadMetrics();
  }, [page, debouncedSearchQuery]);

  // Generate search suggestions from products
  useEffect(() => {
    if (searchQuery.trim().length > 0 && productsArray.length > 0) {
      const query = searchQuery.toLowerCase();
      const suggestions = productsArray
        .filter(product => 
          product.name.toLowerCase().includes(query) ||
          product.sku?.toLowerCase().includes(query) ||
          product.barcode?.toLowerCase().includes(query) ||
          product.category?.toLowerCase().includes(query)
        )
        .slice(0, 5)
        .map(product => product.name);
      setSearchSuggestions(suggestions);
      setShowSuggestions(suggestions.length > 0);
    } else {
      setSearchSuggestions([]);
      setShowSuggestions(false);
    }
  }, [searchQuery, productsArray]);

  const loadMetrics = async () => {
    try {
      const data = await fetcher.get<{ data?: any }>("/api/provider/products/metrics");
      setMetrics(data.data || {
        totalProducts: 0,
        lowStockProducts: 0,
        outOfStockProducts: 0,
        totalInventoryValue: 0,
      });
    } catch (error) {
      console.error("Failed to load metrics:", error);
    }
  };

  const loadProducts = async () => {
    try {
      setIsLoading(true);
      const filters: FilterParams = {
        search: debouncedSearchQuery || undefined,
      };
      const pagination: PaginationParams = { page, limit: 20 };
      const response = await providerApi.listProducts(filters, pagination);

      const productsList = Array.isArray(response.data) ? response.data : [];
      setProducts(productsList);
      setTotalPages(response.total_pages || 1);
    } catch (error) {
      console.error("Failed to load products:", error);
      toast.error("Failed to load products");
      setProducts([]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreate = () => {
    setSelectedProduct(null);
    setIsCreateDialogOpen(true);
  };

  const handleEdit = (product: ProductItem) => {
    setSelectedProduct(product);
    setIsCreateDialogOpen(true);
  };

  const handleDelete = async (product: ProductItem) => {
    if (confirm(`Are you sure you want to delete "${product.name}"?`)) {
      try {
        await providerApi.deleteProduct(product.id);
        toast.success("Product deleted");
        loadProducts();
      } catch {
        toast.error("Failed to delete product");
      }
    }
  };

  const handleSave = () => {
    setIsCreateDialogOpen(false);
    const wasEdit = !!selectedProduct;
    setSelectedProduct(null);

    // Reload products and metrics after a short delay to ensure backend has processed
    setTimeout(() => {
      loadProducts();
      loadMetrics();
    }, 500);

    toast.success(wasEdit ? "Product updated" : "Product created");
  };

  const handleAdjustStock = (product: ProductItem, action: "add" | "remove") => {
    setSelectedProduct(product);
    setStockAction(action);
    setIsStockDialogOpen(true);
  };

  const handleStockAdjustment = async (quantity: number, _reason: string) => {
    if (!selectedProduct) return;

    try {
      const newQuantity = stockAction === "add" 
        ? selectedProduct.quantity + quantity 
        : Math.max(0, selectedProduct.quantity - quantity);

      await providerApi.updateProduct(selectedProduct.id, { quantity: newQuantity });
      toast.success(`Stock ${stockAction === "add" ? "added" : "removed"} successfully`);
      setIsStockDialogOpen(false);

      // Reload both products and metrics immediately
      await Promise.all([loadProducts(), loadMetrics()]);
    } catch {
      toast.error("Failed to update stock");
    }
  };

  return (
    <div>
      <Breadcrumb
        items={[
          { label: "Dashboard", href: "/provider/dashboard" },
          { label: "Catalogue", href: "/provider/catalogue" },
          { label: "Products" },
        ]}
      />
        <PageHeader
          title="Product list"
          subtitle="Manage your inventory with Beautonomi product list"
          primaryAction={{
            label: "Add Product",
            onClick: handleCreate,
            icon: <Plus className="w-4 h-4 mr-2" />,
          }}
          actions={
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline">
                <Plus className="w-4 h-4 mr-2" />
                Add
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent>
              <DropdownMenuItem onClick={handleCreate}>
                <Plus className="w-4 h-4 mr-2" />
                Add Product
              </DropdownMenuItem>
              <DropdownMenuItem>
                <Upload className="w-4 h-4 mr-2" />
                Import CSV
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        }
      />

      {/* Inventory Stats */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4 mb-4 sm:mb-6">
        <SectionCard className="p-3 sm:p-4">
          <div className="flex items-center gap-2 sm:gap-3">
            <div className="p-2 bg-blue-100 rounded-lg flex-shrink-0">
              <Package className="w-4 h-4 sm:w-5 sm:h-5 text-blue-600" />
            </div>
            <div className="min-w-0">
              <p className="text-xl sm:text-2xl font-semibold truncate">{totalProducts}</p>
              <p className="text-xs sm:text-sm text-gray-600 truncate">Total Products</p>
            </div>
          </div>
        </SectionCard>
        <SectionCard className="p-3 sm:p-4">
          <div className="flex items-center gap-2 sm:gap-3">
            <div className="p-2 bg-yellow-100 rounded-lg flex-shrink-0">
              <AlertTriangle className="w-4 h-4 sm:w-5 sm:h-5 text-yellow-600" />
            </div>
            <div className="min-w-0">
              <p className="text-xl sm:text-2xl font-semibold truncate">{lowStockProducts}</p>
              <p className="text-xs sm:text-sm text-gray-600 truncate">Low Stock</p>
            </div>
          </div>
        </SectionCard>
        <SectionCard className="p-3 sm:p-4">
          <div className="flex items-center gap-2 sm:gap-3">
            <div className="p-2 bg-red-100 rounded-lg flex-shrink-0">
              <Package className="w-4 h-4 sm:w-5 sm:h-5 text-red-600" />
            </div>
            <div className="min-w-0">
              <p className="text-xl sm:text-2xl font-semibold truncate">{outOfStockProducts}</p>
              <p className="text-xs sm:text-sm text-gray-600 truncate">Out of Stock</p>
            </div>
          </div>
        </SectionCard>
        <SectionCard className="p-3 sm:p-4">
          <div className="flex items-center gap-2 sm:gap-3">
            <div className="p-2 bg-green-100 rounded-lg flex-shrink-0">
              <TrendingUp className="w-4 h-4 sm:w-5 sm:h-5 text-green-600" />
            </div>
            <div className="min-w-0">
              <p className="text-xl sm:text-2xl font-semibold truncate">
                <Money amount={totalInventoryValue} />
              </p>
              <p className="text-xs sm:text-sm text-gray-600 truncate">Inventory Value</p>
            </div>
          </div>
        </SectionCard>
      </div>

      <div className="relative">
        <DataTableShell
          searchPlaceholder="Search products..."
          searchValue={searchQuery}
          onSearchChange={(value) => {
            setSearchQuery(value);
            setShowSuggestions(value.trim().length > 0);
          }}
          filterButton={{
            label: "Filter",
            onClick: () => setIsFiltersOpen(true),
          }}
          addButton={{
            label: "Add",
            onClick: handleCreate,
          }}
        >
        {isLoading ? (
          <SectionCard>
            <div className="space-y-3">
              {[...Array(5)].map((_, i) => (
                <Skeleton key={i} className="h-16 w-full" />
              ))}
            </div>
          </SectionCard>
        ) : productsArray.length === 0 ? (
          <SectionCard className="p-4 sm:p-6 lg:p-8">
            <div className="text-center max-w-md mx-auto">
              <div className="mb-4 sm:mb-6 flex justify-center">
                <div className="w-20 h-20 sm:w-24 sm:h-24 bg-yellow-100 rounded-full flex items-center justify-center">
                  <Package className="w-10 h-10 sm:w-12 sm:h-12 text-yellow-600" />
                </div>
              </div>
              <h2 className="text-xl sm:text-2xl font-semibold text-gray-900 mb-2 sm:mb-3 px-2">
                Manage your inventory with Beautonomi product list
              </h2>
              <p className="text-sm sm:text-base text-gray-600 mb-4 sm:mb-6 px-2">
                Organize and manage your products and services efficiently
              </p>
              <ul className="text-left space-y-2 mb-6 sm:mb-8 text-gray-600 text-sm sm:text-base px-4">
                <li className="flex items-start gap-2">
                  <span className="text-[#FF0077] mt-1 flex-shrink-0">ΓÇó</span>
                  <span>Start with a single product or import many at once</span>
                </li>
                <li className="flex items-start gap-2">
                  <span className="text-[#FF0077] mt-1 flex-shrink-0">ΓÇó</span>
                  <span>Organise your list by adding brands and categories</span>
                </li>
                <li className="flex items-start gap-2">
                  <span className="text-[#FF0077] mt-1 flex-shrink-0">ΓÇó</span>
                  <span>Set pricing and manage inventory levels</span>
                </li>
              </ul>
              <div className="flex flex-col sm:flex-row gap-3 justify-center px-4">
                <button
                  onClick={handleCreate}
                  className="w-full sm:w-auto px-6 py-3 sm:py-2.5 bg-[#FF0077] text-white rounded-lg font-medium hover:bg-[#D60565] active:bg-[#C00454] transition-colors min-h-[44px] touch-manipulation"
                >
                  Start now
                </button>
                <button className="w-full sm:w-auto px-6 py-3 sm:py-2.5 text-[#FF0077] font-medium hover:underline active:opacity-70 min-h-[44px] touch-manipulation">
                  Learn more
                </button>
              </div>
            </div>
          </SectionCard>
        ) : (
          <SectionCard className="p-0 overflow-hidden">
            {/* Mobile Card View */}
            <div className="block lg:hidden divide-y divide-gray-200">
              {productsArray.map((product) => (
                <div key={product.id} className="p-4 space-y-3">
                  <div className="flex items-start justify-between gap-3">
                    <div className="flex items-start gap-3 flex-1 min-w-0">
                      {product.image_url && (
                        <img
                          src={product.image_url}
                          alt={product.name}
                          className="w-16 h-16 object-cover rounded-lg flex-shrink-0"
                        />
                      )}
                      <div className="flex-1 min-w-0">
                        <h3 className="font-medium text-gray-900 truncate">{product.name}</h3>
                        <p className="text-xs text-gray-500 mt-1">SKU: {product.sku || "N/A"}</p>
                        {product.barcode && (
                          <p className="text-xs text-gray-500">Barcode: {product.barcode}</p>
                        )}
                      </div>
                    </div>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="icon" className="h-8 w-8 flex-shrink-0">
                          <MoreVertical className="w-4 h-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={() => handleEdit(product)}>
                          <Edit className="w-4 h-4 mr-2" />
                          Edit
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => handleAdjustStock(product, "add")}>
                          <TrendingUp className="w-4 h-4 mr-2" />
                          Add Stock
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => handleAdjustStock(product, "remove")}>
                          <TrendingDown className="w-4 h-4 mr-2" />
                          Remove Stock
                        </DropdownMenuItem>
                        <DropdownMenuSeparator />
                        <DropdownMenuItem
                          onClick={() => handleDelete(product)}
                          className="text-red-600"
                        >
                          <Trash2 className="w-4 h-4 mr-2" />
                          Delete
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                  <div className="grid grid-cols-2 gap-3 text-sm">
                    <div>
                      <p className="text-gray-500">Category</p>
                      <p className="font-medium">{product.category || "-"}</p>
                    </div>
                    <div>
                      <p className="text-gray-500">Quantity</p>
                      <p className={cn(
                        "font-medium",
                        product.quantity === 0 && "text-red-600",
                        product.quantity > 0 && product.quantity <= 5 && "text-yellow-600"
                      )}>
                        {product.quantity}
                      </p>
                    </div>
                    <div>
                      <p className="text-gray-500">Supplier</p>
                      <p className="font-medium">{product.supplier || "-"}</p>
                    </div>
                    <div>
                      <p className="text-gray-500">Price</p>
                      <p className="font-medium"><Money amount={product.retail_price} /></p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
            {/* Desktop Table View */}
            <div className="hidden lg:block overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Product name</TableHead>
                    <TableHead>Category</TableHead>
                    <TableHead>Supplier</TableHead>
                    <TableHead>Quantity</TableHead>
                    <TableHead className="text-right">Retail Price</TableHead>
                    <TableHead className="w-12"></TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {productsArray.map((product) => (
                    <TableRow key={product.id}>
                      <TableCell>
                        <div className="flex items-center gap-3">
                          {product.image_url ? (
                            <img
                              src={product.image_url}
                              alt={product.name}
                              className="w-10 h-10 rounded object-cover"
                            />
                          ) : (
                            <div className="w-10 h-10 rounded bg-gray-100 flex items-center justify-center">
                              <span className="text-xs text-gray-500">
                                {product.name.charAt(0)}
                              </span>
                            </div>
                          )}
                          <div>
                            <p className="font-medium">{product.name}</p>
                            <p className="text-xs text-gray-500">
                              {product.barcode && `Barcode: ${product.barcode}`}
                              {product.barcode && product.sku && ` `}
                              {product.sku && `SKU: ${product.sku}`}
                            </p>
                          </div>
                        </div>
                      </TableCell>
                      <TableCell>{product.category}</TableCell>
                      <TableCell>{product.supplier || "-"}</TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          <span className={
                            product.quantity === 0 
                              ? "text-red-600 font-medium" 
                              : product.quantity <= (product.low_stock_level || 5)
                                ? "text-yellow-600 font-medium" 
                                : ""
                          }>
                            {product.quantity}
                          </span>
                          {product.quantity === 0 && (
                            <span className="px-1.5 py-0.5 text-xs bg-red-100 text-red-700 rounded">
                              Out
                            </span>
                          )}
                          {product.quantity > 0 && product.quantity <= (product.low_stock_level || 5) && (
                            <span className="px-1.5 py-0.5 text-xs bg-yellow-100 text-yellow-700 rounded">
                              Low
                            </span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell className="text-right font-medium">
                        <Money amount={product.retail_price} />
                      </TableCell>
                      <TableCell>
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="icon" className="h-8 w-8">
                              <MoreVertical className="w-4 h-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleEdit(product)}>
                              <Edit className="w-4 h-4 mr-2" />
                              Edit
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleAdjustStock(product, "add")}>
                              <TrendingUp className="w-4 h-4 mr-2" />
                              Add Stock
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleAdjustStock(product, "remove")}>
                              <TrendingDown className="w-4 h-4 mr-2" />
                              Remove Stock
                            </DropdownMenuItem>
                            <DropdownMenuItem>
                              <Copy className="w-4 h-4 mr-2" />
                              Duplicate
                            </DropdownMenuItem>
                            <DropdownMenuItem>
                              <Archive className="w-4 h-4 mr-2" />
                              Archive
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem
                              onClick={() => handleDelete(product)}
                              className="text-red-600"
                            >
                              <Trash2 className="w-4 h-4 mr-2" />
                              Delete
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
            {totalPages > 1 && (
              <div className="p-3 sm:p-4 border-t">
                <Pagination
                  currentPage={page}
                  totalPages={totalPages}
                  onPageChange={setPage}
                />
              </div>
            )}
          </SectionCard>
        )}
        </DataTableShell>

        {/* Search Suggestions Dropdown */}
        {showSuggestions && searchSuggestions.length > 0 && (
          <div className="absolute z-50 top-16 left-0 w-full md:max-w-md bg-white border border-gray-200 rounded-lg shadow-lg max-h-60 overflow-y-auto">
            {searchSuggestions.map((suggestion, index) => (
              <button
                key={index}
                onClick={() => {
                  setSearchQuery(suggestion);
                  setShowSuggestions(false);
                }}
                className="w-full text-left px-4 py-2 hover:bg-gray-100 transition-colors border-b border-gray-100 last:border-b-0"
              >
                <div className="flex items-center gap-2">
                  <Search className="w-4 h-4 text-gray-400" />
                  <span className="text-sm text-gray-700">{suggestion}</span>
                </div>
              </button>
            ))}
          </div>
        )}
      </div>

      <ProductCreateEditDialog
        open={isCreateDialogOpen}
        onOpenChange={setIsCreateDialogOpen}
        product={selectedProduct}
        onSave={handleSave}
      />

      <ProductFiltersSheet
        open={isFiltersOpen}
        onOpenChange={setIsFiltersOpen}
      />

      {/* Stock Adjustment Dialog */}
      <StockAdjustmentDialog
        open={isStockDialogOpen}
        onOpenChange={setIsStockDialogOpen}
        product={selectedProduct}
        action={stockAction}
        onSubmit={handleStockAdjustment}
      />
    </div>
  );
}

// Stock Adjustment Dialog Component
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

function StockAdjustmentDialog({
  open,
  onOpenChange,
  product,
  action,
  onSubmit,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  product: ProductItem | null;
  action: "add" | "remove";
  onSubmit: (quantity: number, reason: string) => void;
}) {
  const [quantity, setQuantity] = useState(1);
  const [reason, setReason] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (open) {
      setQuantity(1);
      setReason("");
    }
  }, [open]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (quantity <= 0) {
      toast.error("Please enter a valid quantity");
      return;
    }
    setIsLoading(true);
    try {
      await onSubmit(quantity, reason);
    } finally {
      setIsLoading(false);
    }
  };

  if (!product) return null;

  const stockReasons = action === "add"
    ? ["Purchase Order", "Return", "Correction", "Other"]
    : ["Sale", "Damaged", "Expired", "Lost", "Other"];

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>
            {action === "add" ? "Add Stock" : "Remove Stock"}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="bg-gray-50 p-4 rounded-lg">
            <div className="flex items-center gap-3">
              {product.image_url ? (
                <img
                  src={product.image_url}
                  alt={product.name}
                  className="w-12 h-12 rounded object-cover"
                />
              ) : (
                <div className="w-12 h-12 rounded bg-gray-200 flex items-center justify-center">
                  <Package className="w-6 h-6 text-gray-400" />
                </div>
              )}
              <div>
                <p className="font-medium">{product.name}</p>
                <p className="text-sm text-gray-600">
                  Current stock: <span className="font-medium">{product.quantity}</span>
                </p>
              </div>
            </div>
          </div>

          <div>
            <Label htmlFor="quantity">Quantity *</Label>
            <Input
              id="quantity"
              type="number"
              min={1}
              max={action === "remove" ? product.quantity : undefined}
              value={quantity}
              onChange={(e) => setQuantity(parseInt(e.target.value) || 0)}
              required
            />
            <p className="text-xs text-gray-500 mt-1">
              New stock will be: {action === "add" 
                ? product.quantity + quantity 
                : Math.max(0, product.quantity - quantity)}
            </p>
          </div>

          <div>
            <Label htmlFor="reason">Reason</Label>
            <Select value={reason} onValueChange={setReason}>
              <SelectTrigger>
                <SelectValue placeholder="Select reason" />
              </SelectTrigger>
              <SelectContent>
                {stockReasons.map((r) => (
                  <SelectItem key={r} value={r}>
                    {r}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isLoading}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isLoading}
              className={action === "add" 
                ? "bg-green-600 hover:bg-green-700" 
                : "bg-red-600 hover:bg-red-700"}
            >
              {isLoading ? "Updating..." : action === "add" ? "Add Stock" : "Remove Stock"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Plus, X, Clock, Users, Calendar } from "lucide-react";
import { toast } from "sonner";

interface AdvancedPricingRule {
  id: string;
  type: "time_based" | "location_based" | "client_type" | "package" | "seasonal";
  name: string;
  enabled: boolean;
  conditions: Record<string, any>;
  priceAdjustment: {
    type: "fixed" | "percentage";
    value: number;
  };
}

interface AdvancedPricingModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSave: (rules: AdvancedPricingRule[]) => void;
  initialRules?: AdvancedPricingRule[];
}

export function AdvancedPricingModal({
  open,
  onOpenChange,
  onSave,
  initialRules = [],
}: AdvancedPricingModalProps) {
  const [rules, setRules] = useState<AdvancedPricingRule[]>(initialRules);
  const [activeTab, setActiveTab] = useState<string>("time");

  const addRule = (type: AdvancedPricingRule["type"]) => {
    const newRule: AdvancedPricingRule = {
      id: `rule-${Date.now()}`,
      type,
      name: "",
      enabled: true,
      conditions: getDefaultConditions(type),
      priceAdjustment: {
        type: "percentage",
        value: 0,
      },
    };
    setRules([...rules, newRule]);
  };

  const getDefaultConditions = (type: AdvancedPricingRule["type"]): Record<string, any> => {
    switch (type) {
      case "time_based":
        return {
          days: [],
          startTime: "09:00",
          endTime: "17:00",
        };
      case "location_based":
        return {
          locationIds: [],
        };
      case "client_type":
        return {
          clientType: "new", // "new" | "returning" | "vip"
        };
      case "package":
        return {
          minServices: 1,
          discountType: "percentage",
        };
      case "seasonal":
        return {
          startDate: "",
          endDate: "",
        };
      default:
        return {};
    }
  };

  const updateRule = (id: string, updates: Partial<AdvancedPricingRule>) => {
    setRules(rules.map((rule) => (rule.id === id ? { ...rule, ...updates } : rule)));
  };

  const updateRuleCondition = (id: string, conditionKey: string, value: any) => {
    setRules(
      rules.map((rule) =>
        rule.id === id
          ? {
              ...rule,
              conditions: {
                ...rule.conditions,
                [conditionKey]: value,
              },
            }
          : rule
      )
    );
  };

  const removeRule = (id: string) => {
    setRules(rules.filter((rule) => rule.id !== id));
  };

  const handleSave = () => {
    // Validate rules
    const invalidRules = rules.filter(
      (rule) => !rule.name || (rule.enabled && rule.priceAdjustment.value === 0)
    );

    if (invalidRules.length > 0) {
      toast.error("Please complete all required fields for enabled rules");
      return;
    }

    onSave(rules);
    toast.success("Advanced pricing rules saved");
    onOpenChange(false);
  };

  const renderTimeBasedRule = (rule: AdvancedPricingRule) => (
    <Card key={rule.id} className="mb-4">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Switch
              checked={rule.enabled}
              onCheckedChange={(checked) => updateRule(rule.id, { enabled: checked })}
            />
            <CardTitle className="text-base">Time-Based Pricing</CardTitle>
          </div>
          <Button
            variant="ghost"
            size="icon"
            onClick={() => removeRule(rule.id)}
            className="h-8 w-8"
          >
            <X className="h-4 w-4" />
          </Button>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        <div>
          <Label>Rule Name</Label>
          <Input
            placeholder="e.g., Peak Hours, Weekend Pricing"
            value={rule.name}
            onChange={(e) => updateRule(rule.id, { name: e.target.value })}
            className="mt-1.5"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <Label>Start Time</Label>
            <Input
              type="time"
              value={rule.conditions.startTime || "09:00"}
              onChange={(e) => updateRuleCondition(rule.id, "startTime", e.target.value)}
              className="mt-1.5"
            />
          </div>
          <div>
            <Label>End Time</Label>
            <Input
              type="time"
              value={rule.conditions.endTime || "17:00"}
              onChange={(e) => updateRuleCondition(rule.id, "endTime", e.target.value)}
              className="mt-1.5"
            />
          </div>
        </div>

        <div>
          <Label>Days of Week</Label>
          <div className="flex flex-wrap gap-2 mt-1.5">
            {["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"].map(
              (day) => {
                const days = rule.conditions.days || [];
                const isSelected = days.includes(day);
                return (
                  <Button
                    key={day}
                    type="button"
                    variant={isSelected ? "default" : "outline"}
                    size="sm"
                    onClick={() => {
                      const newDays = isSelected
                        ? days.filter((d: string) => d !== day)
                        : [...days, day];
                      updateRuleCondition(rule.id, "days", newDays);
                    }}
                  >
                    {day.slice(0, 3)}
                  </Button>
                );
              }
            )}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <Label>Price Adjustment Type</Label>
            <Select
              value={rule.priceAdjustment.type}
              onValueChange={(value: "fixed" | "percentage") =>
                updateRule(rule.id, {
                  priceAdjustment: { ...rule.priceAdjustment, type: value },
                })
              }
            >
              <SelectTrigger className="mt-1.5">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="percentage">Percentage</SelectItem>
                <SelectItem value="fixed">Fixed Amount</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label>
              {rule.priceAdjustment.type === "percentage" ? "Percentage (%)" : "Amount (R)"}
            </Label>
            <Input
              type="number"
              step={rule.priceAdjustment.type === "percentage" ? 1 : 0.01}
              value={rule.priceAdjustment.value}
              onChange={(e) =>
                updateRule(rule.id, {
                  priceAdjustment: {
                    ...rule.priceAdjustment,
                    value: parseFloat(e.target.value) || 0,
                  },
                })
              }
              className="mt-1.5"
              placeholder={rule.priceAdjustment.type === "percentage" ? "10" : "50.00"}
            />
          </div>
        </div>
      </CardContent>
    </Card>
  );

  const renderClientTypeRule = (rule: AdvancedPricingRule) => (
    <Card key={rule.id} className="mb-4">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Switch
              checked={rule.enabled}
              onCheckedChange={(checked) => updateRule(rule.id, { enabled: checked })}
            />
            <CardTitle className="text-base">Client Type Pricing</CardTitle>
          </div>
          <Button
            variant="ghost"
            size="icon"
            onClick={() => removeRule(rule.id)}
            className="h-8 w-8"
          >
            <X className="h-4 w-4" />
          </Button>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        <div>
          <Label>Rule Name</Label>
          <Input
            placeholder="e.g., New Client Discount, VIP Pricing"
            value={rule.name}
            onChange={(e) => updateRule(rule.id, { name: e.target.value })}
            className="mt-1.5"
          />
        </div>

        <div>
          <Label>Client Type</Label>
          <Select
            value={rule.conditions.clientType || "new"}
            onValueChange={(value) => updateRuleCondition(rule.id, "clientType", value)}
          >
            <SelectTrigger className="mt-1.5">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="new">New Clients</SelectItem>
              <SelectItem value="returning">Returning Clients</SelectItem>
              <SelectItem value="vip">VIP Clients</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <Label>Price Adjustment Type</Label>
            <Select
              value={rule.priceAdjustment.type}
              onValueChange={(value: "fixed" | "percentage") =>
                updateRule(rule.id, {
                  priceAdjustment: { ...rule.priceAdjustment, type: value },
                })
              }
            >
              <SelectTrigger className="mt-1.5">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="percentage">Percentage</SelectItem>
                <SelectItem value="fixed">Fixed Amount</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label>
              {rule.priceAdjustment.type === "percentage" ? "Percentage (%)" : "Amount (R)"}
            </Label>
            <Input
              type="number"
              step={rule.priceAdjustment.type === "percentage" ? 1 : 0.01}
              value={rule.priceAdjustment.value}
              onChange={(e) =>
                updateRule(rule.id, {
                  priceAdjustment: {
                    ...rule.priceAdjustment,
                    value: parseFloat(e.target.value) || 0,
                  },
                })
              }
              className="mt-1.5"
            />
          </div>
        </div>
      </CardContent>
    </Card>
  );

  const renderSeasonalRule = (rule: AdvancedPricingRule) => (
    <Card key={rule.id} className="mb-4">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Switch
              checked={rule.enabled}
              onCheckedChange={(checked) => updateRule(rule.id, { enabled: checked })}
            />
            <CardTitle className="text-base">Seasonal Pricing</CardTitle>
          </div>
          <Button
            variant="ghost"
            size="icon"
            onClick={() => removeRule(rule.id)}
            className="h-8 w-8"
          >
            <X className="h-4 w-4" />
          </Button>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        <div>
          <Label>Rule Name</Label>
          <Input
            placeholder="e.g., Holiday Season, Summer Special"
            value={rule.name}
            onChange={(e) => updateRule(rule.id, { name: e.target.value })}
            className="mt-1.5"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <Label>Start Date</Label>
            <Input
              type="date"
              value={rule.conditions.startDate || ""}
              onChange={(e) => updateRuleCondition(rule.id, "startDate", e.target.value)}
              className="mt-1.5"
            />
          </div>
          <div>
            <Label>End Date</Label>
            <Input
              type="date"
              value={rule.conditions.endDate || ""}
              onChange={(e) => updateRuleCondition(rule.id, "endDate", e.target.value)}
              className="mt-1.5"
            />
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <Label>Price Adjustment Type</Label>
            <Select
              value={rule.priceAdjustment.type}
              onValueChange={(value: "fixed" | "percentage") =>
                updateRule(rule.id, {
                  priceAdjustment: { ...rule.priceAdjustment, type: value },
                })
              }
            >
              <SelectTrigger className="mt-1.5">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="percentage">Percentage</SelectItem>
                <SelectItem value="fixed">Fixed Amount</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label>
              {rule.priceAdjustment.type === "percentage" ? "Percentage (%)" : "Amount (R)"}
            </Label>
            <Input
              type="number"
              step={rule.priceAdjustment.type === "percentage" ? 1 : 0.01}
              value={rule.priceAdjustment.value}
              onChange={(e) =>
                updateRule(rule.id, {
                  priceAdjustment: {
                    ...rule.priceAdjustment,
                    value: parseFloat(e.target.value) || 0,
                  },
                })
              }
              className="mt-1.5"
            />
          </div>
        </div>
      </CardContent>
    </Card>
  );

  const timeBasedRules = rules.filter((r) => r.type === "time_based");
  const clientTypeRules = rules.filter((r) => r.type === "client_type");
  const seasonalRules = rules.filter((r) => r.type === "seasonal");

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Advanced Pricing Options</DialogTitle>
          <DialogDescription>
            Set up custom pricing rules based on time, client type, seasons, and more. These rules
            will automatically adjust the base price when conditions are met.
          </DialogDescription>
        </DialogHeader>

        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="time" className="flex items-center gap-2">
              <Clock className="w-4 h-4" />
              Time-Based
            </TabsTrigger>
            <TabsTrigger value="client" className="flex items-center gap-2">
              <Users className="w-4 h-4" />
              Client Type
            </TabsTrigger>
            <TabsTrigger value="seasonal" className="flex items-center gap-2">
              <Calendar className="w-4 h-4" />
              Seasonal
            </TabsTrigger>
          </TabsList>

          <TabsContent value="time" className="space-y-4 mt-4">
            {timeBasedRules.map(renderTimeBasedRule)}
            <Button
              type="button"
              variant="outline"
              onClick={() => addRule("time_based")}
              className="w-full"
            >
              <Plus className="w-4 h-4 mr-2" />
              Add Time-Based Rule
            </Button>
            {timeBasedRules.length === 0 && (
              <Card className="border-dashed">
                <CardContent className="flex flex-col items-center justify-center py-8">
                  <Clock className="w-12 h-12 text-gray-300 mb-2" />
                  <p className="text-sm text-gray-500 text-center">
                    No time-based pricing rules. Add one to set different prices for specific times
                    or days.
                  </p>
                </CardContent>
              </Card>
            )}
          </TabsContent>

          <TabsContent value="client" className="space-y-4 mt-4">
            {clientTypeRules.map(renderClientTypeRule)}
            <Button
              type="button"
              variant="outline"
              onClick={() => addRule("client_type")}
              className="w-full"
            >
              <Plus className="w-4 h-4 mr-2" />
              Add Client Type Rule
            </Button>
            {clientTypeRules.length === 0 && (
              <Card className="border-dashed">
                <CardContent className="flex flex-col items-center justify-center py-8">
                  <Users className="w-12 h-12 text-gray-300 mb-2" />
                  <p className="text-sm text-gray-500 text-center">
                    No client type pricing rules. Add one to offer discounts or premiums based on
                    client type.
                  </p>
                </CardContent>
              </Card>
            )}
          </TabsContent>

          <TabsContent value="seasonal" className="space-y-4 mt-4">
            {seasonalRules.map(renderSeasonalRule)}
            <Button
              type="button"
              variant="outline"
              onClick={() => addRule("seasonal")}
              className="w-full"
            >
              <Plus className="w-4 h-4 mr-2" />
              Add Seasonal Rule
            </Button>
            {seasonalRules.length === 0 && (
              <Card className="border-dashed">
                <CardContent className="flex flex-col items-center justify-center py-8">
                  <Calendar className="w-12 h-12 text-gray-300 mb-2" />
                  <p className="text-sm text-gray-500 text-center">
                    No seasonal pricing rules. Add one to adjust prices during specific date
                    ranges.
                  </p>
                </CardContent>
              </Card>
            )}
          </TabsContent>
        </Tabs>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={handleSave}>Save Rules</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Checkbox } from "@/components/ui/checkbox";
import { Separator } from "@/components/ui/separator";
import { providerApi } from "@/lib/provider-portal/api";
import type { ServiceCategory, TeamMember, ServiceItem } from "@/lib/provider-portal/types";
import Image from "next/image";
import { X, Plus } from "lucide-react";
import { toast } from "sonner";
import { useReferenceData } from "@/hooks/useReferenceData";
import { AdvancedPricingModal } from "./AdvancedPricingModal";
import { handleError } from "@/lib/provider-portal/error-handler";
import { invalidateSetupStatusCache } from "@/lib/provider-portal/setup-status-utils";

interface ServiceCreateEditDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  service?: any;
  categoryId?: string | null;
  categories: ServiceCategory[];
  onSave: () => void;
  onCategoriesChange?: () => void; // Callback to refresh categories from parent
}

interface PricingOption {
  id: string;
  duration: number;
  priceType: string;
  price: number;
  pricingName: string;
}

export function ServiceCreateEditDialog({
  open,
  onOpenChange,
  service,
  categoryId,
  categories,
  onSave,
  onCategoriesChange,
}: ServiceCreateEditDialogProps) {
  // Fetch reference data for all dropdowns
  const { 
    getOptions, 
    isLoading: _isLoadingReferenceData 
  } = useReferenceData([
    "service_type", 
    "duration", 
    "price_type", 
    "availability", 
    "tax_rate", 
    "team_role", 
    "reminder_unit", 
    "extra_time",
    "addon_category"
  ]);

  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [allServices, setAllServices] = useState<ServiceItem[]>([]);
  const [providerResources, setProviderResources] = useState<Array<{ id: string; name: string; group_name?: string | null }>>([]);
  const [isLoadingTeam, setIsLoadingTeam] = useState(false);
  const [isLoadingServices, setIsLoadingServices] = useState(false);
  const [isLoadingResources, setIsLoadingResources] = useState(false);
  const [showIncludedServicesDialog, setShowIncludedServicesDialog] = useState(false);
  const [showCategoryDialog, setShowCategoryDialog] = useState(false);
  const [showTeamMemberDialog, setShowTeamMemberDialog] = useState(false);
  const [showAdvancedPricingModal, setShowAdvancedPricingModal] = useState(false);
  const [advancedPricingRules, setAdvancedPricingRules] = useState<any[]>([]);
  const [pricingOptions, setPricingOptions] = useState<PricingOption[]>([
    { id: "1", duration: 60, priceType: "fixed", price: 0, pricingName: "" }
  ]);

  // Category creation form state
  const [categoryFormData, setCategoryFormData] = useState({
    name: "",
    color: "#FF0077",
    description: "",
  });

  // Team member creation form state
  const [teamMemberFormData, setTeamMemberFormData] = useState({
    name: "",
    email: "",
    mobile: "",
    role: "staff" as "owner" | "manager" | "staff",
  });

  const [formData, setFormData] = useState({
    name: "",
    serviceType: "basic",
    includedServices: [] as string[],
    description: "",
    aftercareDescription: "",
    availableFor: "everyone",
    categoryId: categoryId || "",

    onlineBookable: true,

    selectedTeamMembers: [] as string[],
    teamMemberCommissionEnabled: false,

    extraTimeEnabled: false,
    extraTimeDuration: 0,

    reminderToRebookEnabled: false,
    reminderToRebookWeeks: 4,

    serviceCostPercentage: 0,

    taxRate: 0,
    isActive: true,

    // Location support
    supportsAtSalon: true,
    supportsAtHome: false,
    atHomeRadiusKm: 0,
    atHomePriceAdjustment: 0,

    // Add-on specific fields
    addonCategory: "general",
    applicableServiceIds: [] as string[],  // Which services can have this add-on
    isRecommended: false,

    // Variant specific fields
    parentServiceId: "",  // Parent service for variants
    variantName: "",  // Short name for variant (e.g., "Short Hair")
    variantSortOrder: 0,

    // Resource requirements (rooms, equipment) for this service
    offeringResources: [] as Array<{ resource_id: string; required: boolean }>,
  });

  const loadProviderResources = async () => {
    try {
      setIsLoadingResources(true);
      const list = await providerApi.listResources();
      setProviderResources((list || []).map((r: any) => ({ id: r.id, name: r.name, group_name: r.group_name ?? null })));
    } catch {
      setProviderResources([]);
    } finally {
      setIsLoadingResources(false);
    }
  };

  // Load team members, services, and resources when dialog opens
  useEffect(() => {
    if (open) {
      loadTeamMembers();
      loadAllServices();
      loadProviderResources();
    }
  }, [open]);

  // Update categoryId when prop changes
  useEffect(() => {
    if (categoryId) {
      setFormData(prev => ({ ...prev, categoryId: categoryId }));
    }
  }, [categoryId]);

  // Update formData when categories change
  useEffect(() => {
    if (categories.length > 0 && !formData.categoryId && categoryId) {
      setFormData(prev => ({ ...prev, categoryId: categoryId }));
    }
    // Reload services when categories change (in case new services were added)
    if (open && categories.length > 0) {
      loadAllServices();
    }
  }, [categories, open]);

  const loadTeamMembers = async () => {
    try {
      setIsLoadingTeam(true);
      const members = await providerApi.listTeamMembers();
      setTeamMembers(members || []);
    } catch (error) {
      handleError(error, {
        action: "loadTeamMembers",
        resource: "team members",
      }, { showToast: false });
      setTeamMembers([]);
    } finally {
      setIsLoadingTeam(false);
    }
  };

  const handleCreateCategory = async () => {
    if (!categoryFormData.name.trim()) {
      toast.error("Category name is required");
      return;
    }

    try {
      const newCategory = await providerApi.createServiceCategory({
        name: categoryFormData.name,
        color: categoryFormData.color,
        description: categoryFormData.description,
      });
      toast.success("Category created");
      setShowCategoryDialog(false);
      setCategoryFormData({ name: "", color: "#FF0077", description: "" });

      // Refresh categories from parent
      if (onCategoriesChange) {
        onCategoriesChange();
      }

      // Auto-select the newly created category
      setFormData(prev => ({ ...prev, categoryId: newCategory.id }));
    } catch (error: any) {
      handleError(error, {
        action: "createCategory",
        resource: "service category",
      });
    }
  };

  const handleCreateTeamMember = async () => {
    if (!teamMemberFormData.name.trim() || !teamMemberFormData.email.trim() || !teamMemberFormData.mobile.trim()) {
      toast.error("Name, email, and mobile are required");
      return;
    }

    try {
      const newMember = await providerApi.createTeamMember({
        name: teamMemberFormData.name,
        email: teamMemberFormData.email,
        mobile: teamMemberFormData.mobile,
        role: teamMemberFormData.role === "staff" ? "employee" : teamMemberFormData.role,
      });
      toast.success("Team member created");
      setShowTeamMemberDialog(false);
      setTeamMemberFormData({ name: "", email: "", mobile: "", role: "staff" });

      // Refresh team members
      await loadTeamMembers();

      // Auto-select the newly created team member
      setFormData(prev => ({
        ...prev,
        selectedTeamMembers: [...prev.selectedTeamMembers, newMember.id],
      }));
    } catch (error: any) {
      handleError(error, {
        action: "createTeamMember",
        resource: "team member",
      });
      toast.error(error?.message || "Failed to create team member");
    }
  };

  const loadAllServices = async () => {
    try {
      setIsLoadingServices(true);
      // First try to get all services from categories prop
      const allServicesList: ServiceItem[] = [];
      if (categories && categories.length > 0) {
        categories.forEach(category => {
          if (category.services && category.services.length > 0) {
            category.services.forEach(svc => {
              // Exclude the current service if editing
              if (svc && svc.id !== service?.id) {
                allServicesList.push(svc);
              }
            });
          }
        });
      }

      // Always try to fetch from API to ensure we have the latest data
      try {
        const categoriesFromApi = await providerApi.listServiceCategories();
        const apiServicesList: ServiceItem[] = [];
        categoriesFromApi.forEach(category => {
          if (category.services && category.services.length > 0) {
            category.services.forEach(svc => {
              if (svc && svc.id !== service?.id) {
                apiServicesList.push(svc);
              }
            });
          }
        });

        // Use API services if available, otherwise fall back to prop services
        if (apiServicesList.length > 0) {
          setAllServices(apiServicesList);
        } else if (allServicesList.length > 0) {
          setAllServices(allServicesList);
        } else {
          setAllServices([]);
        }
      } catch (apiError) {
        console.warn("Failed to fetch services from API, using categories prop:", apiError);
        // Fall back to services from categories prop
        setAllServices(allServicesList);
      }
    } catch (error) {
      handleError(error, {
        action: "loadServices",
        resource: "services",
      }, { showToast: false });
      setAllServices([]);
    } finally {
      setIsLoadingServices(false);
    }
  };

  useEffect(() => {
    if (service) {
      setFormData({
        name: service.name || "",
        serviceType: service.service_type || "basic",
        includedServices: service.included_services || [],
        description: service.description || "",
        aftercareDescription: service.aftercare_description || "",
        availableFor: service.service_available_for || "everyone",
        categoryId: service.provider_category_id || service.category_id || categoryId || "",

        onlineBookable: service.online_booking_enabled !== false,

        selectedTeamMembers: service.team_member_ids || [],
        teamMemberCommissionEnabled: service.team_member_commission_enabled || false,

        extraTimeEnabled: service.extra_time_enabled || false,
        extraTimeDuration: service.extra_time_duration || 0,

        reminderToRebookEnabled: service.reminder_to_rebook_enabled || false,
        reminderToRebookWeeks: service.reminder_to_rebook_weeks || 4,

        serviceCostPercentage: service.service_cost_percentage || 0,

        taxRate: service.tax_rate || 0,
        isActive: service.is_active !== false,

        // Location support
        supportsAtSalon: service.supports_at_salon !== false,
        supportsAtHome: service.supports_at_home || false,
        atHomeRadiusKm: service.at_home_radius_km || 0,
        atHomePriceAdjustment: service.at_home_price_adjustment || 0,

        // Add-on specific fields
        addonCategory: service.addon_category || "general",
        applicableServiceIds: service.applicable_service_ids || [],
        isRecommended: service.is_recommended || false,

        // Variant specific fields
        parentServiceId: service.parent_service_id || "",
        variantName: service.variant_name || "",
        variantSortOrder: service.variant_sort_order || 0,
        offeringResources: [],
      });

      // Load pricing options if they exist
      if (service.pricing_options && Array.isArray(service.pricing_options)) {
        setPricingOptions(service.pricing_options);
      } else if (service.duration_minutes || service.price) {
        setPricingOptions([{
          id: "1",
          duration: service.duration_minutes || 60,
          priceType: service.price_type || "fixed",
          price: service.price || 0,
          pricingName: service.pricing_name || "",
        }]);
      }

      // Load advanced pricing rules if they exist
      if (service.advanced_pricing_rules && Array.isArray(service.advanced_pricing_rules)) {
        setAdvancedPricingRules(service.advanced_pricing_rules);
      } else {
        setAdvancedPricingRules([]);
      }

      // Load resource requirements for this service
      providerApi.getServiceResources(service.id).then((resList) => {
        setFormData((prev) => ({ ...prev, offeringResources: Array.isArray(resList) ? resList : [] }));
      }).catch(() => {
        setFormData((prev) => ({ ...prev, offeringResources: [] }));
      });
    } else {
      setFormData({
        name: "",
        serviceType: "basic",
        includedServices: [],
        description: "",
        aftercareDescription: "",
        availableFor: "everyone",
        categoryId: categoryId || "",
        onlineBookable: true,
        selectedTeamMembers: [],
        teamMemberCommissionEnabled: false,
        extraTimeEnabled: false,
        extraTimeDuration: 0,
        reminderToRebookEnabled: false,
        reminderToRebookWeeks: 4,
        serviceCostPercentage: 0,
        taxRate: 0,
        isActive: true,

        // Location support defaults
        supportsAtSalon: true,
        supportsAtHome: false,
        atHomeRadiusKm: 0,
        atHomePriceAdjustment: 0,

        // Add-on defaults
        addonCategory: "general",
        applicableServiceIds: [],
        isRecommended: false,

        // Variant defaults
        parentServiceId: "",
        variantName: "",
        variantSortOrder: 0,

        offeringResources: [],
      });
      setPricingOptions([{ id: "1", duration: 60, priceType: "fixed", price: 0, pricingName: "" }]);
    }
  }, [service, categoryId, open]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name.trim()) {
      toast.error("Service name is required");
      return;
    }
    if (!formData.categoryId) {
      toast.error("Service category is required");
      return;
    }

    // Validate variant fields
    if (formData.serviceType === "variant") {
      if (!formData.parentServiceId) {
        toast.error("Parent service is required for variants");
        return;
      }
    }

    try {
      // Prepare service data with all fields
      const serviceData: any = {
        name: formData.name,
        service_type: formData.serviceType,
        provider_category_id: formData.categoryId,
        description: formData.description,
        aftercare_description: formData.aftercareDescription,
        service_available_for: formData.availableFor,
        online_booking_enabled: formData.onlineBookable,
        team_member_ids: formData.selectedTeamMembers,
        team_member_commission_enabled: formData.teamMemberCommissionEnabled,
        duration_minutes: primaryPricing.duration,
        price: primaryPricing.price,
        price_type: primaryPricing.priceType,
        pricing_name: primaryPricing.pricingName,
        pricing_options: pricingOptions,
        advanced_pricing_rules: advancedPricingRules,
        extra_time_enabled: formData.extraTimeEnabled,
        extra_time_duration: formData.extraTimeDuration,
        reminder_to_rebook_enabled: formData.reminderToRebookEnabled,
        reminder_to_rebook_weeks: formData.reminderToRebookWeeks,
        service_cost_percentage: formData.serviceCostPercentage,
        tax_rate: formData.taxRate,
        included_services: formData.includedServices,
        is_active: formData.isActive,

        // Location support
        supports_at_salon: formData.supportsAtSalon,
        supports_at_home: formData.supportsAtHome,
        at_home_radius_km: formData.supportsAtHome ? formData.atHomeRadiusKm : null,
        at_home_price_adjustment: formData.supportsAtHome ? formData.atHomePriceAdjustment : 0,

        // Add-on specific fields
        addon_category: formData.serviceType === "addon" ? formData.addonCategory : null,
        applicable_service_ids: formData.serviceType === "addon" && formData.applicableServiceIds.length > 0 
          ? formData.applicableServiceIds 
          : null,
        is_recommended: formData.serviceType === "addon" ? formData.isRecommended : false,

        // Variant specific fields
        parent_service_id: formData.serviceType === "variant" ? formData.parentServiceId || null : null,
        variant_name: formData.serviceType === "variant" ? formData.variantName || null : null,
        variant_sort_order: formData.serviceType === "variant" ? formData.variantSortOrder : 0,
      };

      let savedServiceId: string;
      if (service) {
        await providerApi.updateService(service.id, serviceData);
        savedServiceId = service.id;
        toast.success("Service updated successfully");
      } else {
        const created = await providerApi.createService(serviceData);
        savedServiceId = created.id;
        toast.success("Service created successfully");
      }
      if (formData.offeringResources?.length) {
        await providerApi.setServiceResources(savedServiceId, formData.offeringResources);
      } else {
        await providerApi.setServiceResources(savedServiceId, []);
      }
      invalidateSetupStatusCache();
      onSave();
    } catch (error: any) {
      handleError(error, {
        action: service ? "updateService" : "createService",
        resource: "service",
      });
    }
  };

  const handleSelectAllTeamMembers = (checked: boolean) => {
    if (checked) {
      setFormData({
        ...formData,
        selectedTeamMembers: teamMembers.map(m => m.id),
      });
    } else {
      setFormData({
        ...formData,
        selectedTeamMembers: [],
      });
    }
  };

  const handleTeamMemberToggle = (memberId: string, checked: boolean) => {
    if (checked) {
      setFormData({
        ...formData,
        selectedTeamMembers: [...formData.selectedTeamMembers, memberId],
      });
    } else {
      setFormData({
        ...formData,
        selectedTeamMembers: formData.selectedTeamMembers.filter(id => id !== memberId),
      });
    }
  };

  const handleIncludedServiceToggle = (serviceId: string, checked: boolean) => {
    if (checked) {
      setFormData({
        ...formData,
        includedServices: [...formData.includedServices, serviceId],
      });
    } else {
      setFormData({
        ...formData,
        includedServices: formData.includedServices.filter(id => id !== serviceId),
      });
    }
  };

  const handleAddPricingOption = () => {
    setPricingOptions([
      ...pricingOptions,
      { id: Date.now().toString(), duration: 60, priceType: "fixed", price: 0, pricingName: "" }
    ]);
  };

  const handleRemovePricingOption = (id: string) => {
    if (pricingOptions.length > 1) {
      setPricingOptions(pricingOptions.filter(opt => opt.id !== id));
    }
  };

  const handlePricingOptionChange = (id: string, field: keyof PricingOption, value: any) => {
    setPricingOptions(pricingOptions.map(opt => 
      opt.id === id ? { ...opt, [field]: value } : opt
    ));
  };

  const allTeamMembersSelected = teamMembers.length > 0 && formData.selectedTeamMembers.length === teamMembers.length;
  const primaryPricing: PricingOption = pricingOptions[0] || { id: "1", duration: 60, priceType: "fixed", price: 0, pricingName: "" };
  const serviceCostAmount = primaryPricing.price > 0 && formData.serviceCostPercentage > 0
    ? (primaryPricing.price * formData.serviceCostPercentage / 100)
    : 0;

  const includedServicesList = allServices.filter(s => formData.includedServices.includes(s.id));
  const availableServicesForInclusion = allServices.filter(s => s.id !== service?.id);

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="max-w-[95vw] sm:max-w-2xl lg:max-w-3xl max-h-[95vh] sm:max-h-[90vh] overflow-y-auto p-4 sm:p-6">
          <DialogHeader className="px-0 sm:px-0">
            <DialogTitle className="text-lg sm:text-xl">{service ? "Edit Service" : "Create Service"}</DialogTitle>
            <DialogDescription className="text-xs sm:text-sm text-gray-500 mt-1">
              {service ? "Update the service details below" : "Add a new service to your catalogue. Clients will see the service name in their notifications and booking confirmations."}
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-4 sm:space-y-6 px-0 sm:px-0">

            {/* Basic Info */}
            <div className="space-y-3 sm:space-y-4">
              <div>
                <h3 className="text-base sm:text-lg font-semibold mb-3 sm:mb-4">Basic Information</h3>
              </div>

              <div>
                <Label htmlFor="name" className="text-sm sm:text-base">Service name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="e.g., Signature Haircut, Full Body Massage, Classic Manicure"
                  required
                  className="mt-1.5"
                />
                <p className="text-xs text-gray-500 mt-1.5">
                  Make sure the service name can be understood independently. Clients will only see the <strong>service name</strong> in their notifications, not the category name.
                </p>
              </div>

              <div>
                <Label htmlFor="serviceType" className="text-sm sm:text-base">Service type</Label>
                <Select 
                  value={formData.serviceType} 
                  onValueChange={(val) => setFormData({ ...formData, serviceType: val })}
                >
                  <SelectTrigger className="mt-1.5">
                    <SelectValue placeholder="Select service type" />
                  </SelectTrigger>
                  <SelectContent>
                    {getOptions("service_type").map((option) => (
                      <SelectItem key={option.value} value={option.value}>
                        {option.label}{option.description ? ` (${option.description})` : ""}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <p className="text-xs text-gray-500 mt-1.5">Choose how this service appears to clients in your booking system</p>
              </div>

              {formData.serviceType === "package" && (
                <div>
                  <Label className="text-sm sm:text-base">Included services</Label>
                  <div className="border rounded-md p-3 bg-pink-50 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2 sm:gap-0 text-sm min-h-[48px] mt-1.5">
                    {formData.includedServices.length === 0 ? (
                      <span className="text-gray-500 text-xs sm:text-sm">No services included</span>
                    ) : (
                      <div className="flex flex-wrap gap-2 flex-1">
                        {includedServicesList.map(service => (
                          <span key={service.id} className="px-2 py-1 bg-white rounded text-xs">
                            {service.name}
                          </span>
                        ))}
                      </div>
                    )}
                    <Button 
                      type="button"
                      variant="link" 
                      className="text-[#FF0077] p-0 h-auto text-xs sm:text-sm whitespace-nowrap"
                      onClick={() => setShowIncludedServicesDialog(true)}
                      disabled={allServices.length === 0}
                    >
                      {formData.includedServices.length === 0 ? "Add" : "Edit"}
                    </Button>
                  </div>
                  <p className="text-xs text-gray-500 mt-1.5">Select which services are included in this package</p>
                </div>
              )}

              {/* Add-on specific fields */}
              {formData.serviceType === "addon" && (
                <div className="space-y-4 p-4 bg-blue-50 rounded-lg border border-blue-200">
                  <div className="flex items-center gap-2 text-blue-700 font-medium">
                    <Plus className="w-4 h-4" />
                    <span>Add-on Configuration</span>
                  </div>

                  <div>
                    <Label className="text-sm sm:text-base">Add-on category</Label>
                    <Select 
                      value={formData.addonCategory} 
                      onValueChange={(val) => setFormData({ ...formData, addonCategory: val })}
                    >
                      <SelectTrigger className="mt-1.5">
                        <SelectValue placeholder="Select category" />
                      </SelectTrigger>
                      <SelectContent>
                        {getOptions("addon_category").map((opt) => (
                          <SelectItem key={opt.value} value={opt.value}>
                            {opt.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <p className="text-xs text-gray-500 mt-1.5">Group similar add-ons together during checkout</p>
                  </div>

                  <div>
                    <Label className="text-sm sm:text-base">Applicable services</Label>
                    <div className="border rounded-md p-3 bg-white flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2 sm:gap-0 text-sm min-h-[48px] mt-1.5">
                      {formData.applicableServiceIds.length === 0 ? (
                        <span className="text-gray-500 text-xs sm:text-sm">Available for all services</span>
                      ) : (
                        <div className="flex flex-wrap gap-2 flex-1">
                          {formData.applicableServiceIds.map(serviceId => {
                            const svc = allServices.find(s => s.id === serviceId);
                            return (
                              <span key={serviceId} className="px-2 py-1 bg-blue-100 rounded text-xs">
                                {svc?.name || serviceId}
                              </span>
                            );
                          })}
                        </div>
