    return (
      <RoleGuard allowedRoles={["provider_owner", "provider_staff", "superadmin"]}>
        <div className="min-h-screen bg-gray-50">
          <div className="max-w-5xl mx-auto p-4 md:p-6 lg:p-8">
            <div className="text-center py-12">
