"use client";

import { useEffect, useState, useCallback } from "react";
import { fetcher } from "@/lib/http/fetcher";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import {
  ShoppingBag,
  ChevronLeft,
  ChevronRight,
  X,
} from "lucide-react";

interface ProductOrder {
  id: string;
  order_number: string;
  status: string;
  total_amount: number;
  payment_status: string;
  fulfillment_type: string;
  tracking_number: string | null;
  created_at: string;
  customer: { id: string; full_name: string; email: string };
  items: {
    id: string;
    product_name: string;
    quantity: number;
    total_price: number;
    product_variant?: { option_values?: Record<string, string> } | null;
  }[];
}

const STATUS_ACTIONS: Record<string, { next: string; label: string; color: string }[]> = {
  pending: [
    { next: "confirmed", label: "Confirm Order", color: "bg-blue-600 hover:bg-blue-700" },
    { next: "cancelled", label: "Cancel", color: "bg-red-600 hover:bg-red-700" },
  ],
  confirmed: [
    { next: "processing", label: "Start Processing", color: "bg-purple-600 hover:bg-purple-700" },
  ],
  processing: [
    { next: "shipped", label: "Mark Shipped", color: "bg-indigo-600 hover:bg-indigo-700" },
    { next: "ready_for_collection", label: "Ready for Collection", color: "bg-teal-600 hover:bg-teal-700" },
  ],
  shipped: [
    { next: "delivered", label: "Mark Delivered", color: "bg-green-600 hover:bg-green-700" },
  ],
  ready_for_collection: [
    { next: "delivered", label: "Collected", color: "bg-green-600 hover:bg-green-700" },
  ],
};

const STATUS_BADGE: Record<string, "default" | "destructive" | "outline" | "secondary"> = {
  pending: "outline",
  confirmed: "secondary",
  processing: "secondary",
  shipped: "default",
  ready_for_collection: "default",
  delivered: "default",
  cancelled: "destructive",
};

export default function ProviderProductOrdersPage() {
  const [orders, setOrders] = useState<ProductOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState("");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [updating, setUpdating] = useState<string | null>(null);
  const [error, setError] = useState("");

  const [trackingDialog, setTrackingDialog] = useState<{ orderId: string; status: string } | null>(null);
  const [trackingInput, setTrackingInput] = useState("");

  const fetchOrders = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      params.set("page", String(page));
      if (statusFilter) params.set("status", statusFilter);

      const res = await fetcher.get<{
        data: { orders: ProductOrder[]; pagination: { totalPages: number } };
      }>(`/api/provider/product-orders?${params}`);

      if (res?.data) {
        setOrders(res.data.orders);
        setTotalPages(res.data.pagination.totalPages);
      }
    } catch {
      setError("Failed to load orders");
    }
    setLoading(false);
  }, [page, statusFilter]);

  useEffect(() => {
    const id = setTimeout(() => fetchOrders(), 0);
    return () => clearTimeout(id);
  }, [fetchOrders]);

  const handleStatusUpdate = async (orderId: string, newStatus: string) => {
    if (newStatus === "shipped") {
      setTrackingDialog({ orderId, status: newStatus });
      setTrackingInput("");
      return;
    }
    await submitStatusUpdate(orderId, newStatus);
  };

  const submitStatusUpdate = async (orderId: string, newStatus: string, trackingNumber?: string) => {
    setUpdating(orderId);
    setError("");
    try {
      const payload: Record<string, any> = { status: newStatus };
      if (trackingNumber) payload.tracking_number = trackingNumber;
      await fetcher.patch(`/api/provider/product-orders/${orderId}`, payload);
      fetchOrders();
    } catch {
      setError("Failed to update order status");
    }
    setUpdating(null);
    setTrackingDialog(null);
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-gray-900">Product Orders</h1>
        <p className="text-sm text-gray-500 mt-1">Manage customer product purchases and fulfillment</p>
      </div>

      {error && (
        <div className="flex items-center justify-between bg-red-50 border border-red-200 rounded-lg px-4 py-3 text-sm text-red-700">
          {error}
          <button onClick={() => setError("")}><X className="w-4 h-4" /></button>
        </div>
      )}

      <div className="flex items-center gap-3 flex-wrap">
        {["", "pending", "confirmed", "processing", "shipped", "ready_for_collection", "delivered", "cancelled"].map(
          (s) => (
            <button
              key={s}
              onClick={() => { setStatusFilter(s); setPage(1); }}
              className={`px-3 py-1.5 rounded-full text-sm font-medium transition-colors ${
                statusFilter === s
                  ? "bg-pink-600 text-white"
                  : "bg-gray-100 text-gray-700 hover:bg-gray-200"
              }`}
            >
              {s ? s.replace(/_/g, " ") : "All"}
            </button>
          ),
        )}
      </div>

      <div className="bg-white rounded-xl border overflow-hidden">
        {loading ? (
          <div className="p-12 text-center text-gray-500">Loading...</div>
        ) : orders.length === 0 ? (
          <div className="p-12 text-center">
            <ShoppingBag className="w-12 h-12 text-gray-300 mx-auto mb-3" />
            <p className="text-gray-500">No orders found</p>
          </div>
        ) : (
          <div className="divide-y">
            {orders.map((o) => {
              const actions = STATUS_ACTIONS[o.status] ?? [];
              return (
                <div key={o.id} className="p-5 hover:bg-gray-50 transition-colors">
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-3 mb-2">
                        <span className="font-bold text-gray-900 text-lg">{o.order_number}</span>
                        <Badge variant={STATUS_BADGE[o.status] ?? "outline"}>
                          {o.status.replace(/_/g, " ")}
                        </Badge>
                        <Badge variant={o.payment_status === "paid" ? "default" : "outline"}>
                          {o.payment_status}
                        </Badge>
                      </div>
                      <p className="text-sm text-gray-700">
                        <span className="font-medium">{o.customer?.full_name}</span>{" "}
                        <span className="text-gray-400">({o.customer?.email})</span>
                      </p>
                      <div className="mt-2 space-y-1">
                        {o.items?.map((item) => (
                          <div key={item.id} className="flex items-center gap-2 text-sm text-gray-600">
                            <span className="text-gray-400">{item.quantity}x</span>
                            <span>
                              {item.product_name}
                              {item.product_variant?.option_values && Object.keys(item.product_variant.option_values).length > 0 && (
                                <span className="text-gray-500"> ┬╖ {Object.values(item.product_variant.option_values).join(", ")}</span>
                              )}
                            </span>
                            <span className="text-gray-400">R{Number(item.total_price).toFixed(2)}</span>
                          </div>
                        ))}
                      </div>
                      {o.tracking_number && (
                        <p className="text-xs text-blue-600 mt-2">Tracking: {o.tracking_number}</p>
                      )}
                    </div>
                    <div className="text-right shrink-0">
                      <p className="text-xl font-bold text-gray-900">R{Number(o.total_amount).toFixed(2)}</p>
                      <p className="text-xs text-gray-500 mt-1">
                        {new Date(o.created_at).toLocaleDateString()} ┬╖{" "}
                        {o.fulfillment_type === "delivery" ? "Delivery" : "Collection"}
                      </p>
                      {actions.length > 0 && (
                        <div className="flex gap-2 mt-3 justify-end">
                          {actions.map((a) => (
                            <button
                              key={a.next}
                              onClick={() => handleStatusUpdate(o.id, a.next)}
                              disabled={updating === o.id}
                              className={`px-3 py-1.5 text-xs font-medium text-white rounded-lg ${a.color} disabled:opacity-50`}
                            >
                              {updating === o.id ? "..." : a.label}
                            </button>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-2">
          <button onClick={() => setPage(Math.max(1, page - 1))} disabled={page <= 1} className="p-2 border rounded-lg hover:bg-gray-50 disabled:opacity-50">
            <ChevronLeft className="w-4 h-4" />
          </button>
          <span className="text-sm text-gray-600">Page {page} of {totalPages}</span>
          <button onClick={() => setPage(Math.min(totalPages, page + 1))} disabled={page >= totalPages} className="p-2 border rounded-lg hover:bg-gray-50 disabled:opacity-50">
            <ChevronRight className="w-4 h-4" />
          </button>
        </div>
      )}

      {/* Tracking number dialog */}
      {trackingDialog && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
          <div className="bg-white rounded-2xl p-6 w-full max-w-md shadow-xl">
            <h3 className="text-lg font-bold text-gray-900 mb-2">Enter Tracking Number</h3>
            <p className="text-sm text-gray-500 mb-4">Provide a tracking number for the shipment (optional).</p>
            <Input
              value={trackingInput}
              onChange={(e) => setTrackingInput(e.target.value)}
              placeholder="e.g. TRACK-12345"
              className="mb-4"
            />
            <div className="flex gap-3 justify-end">
              <button
                onClick={() => setTrackingDialog(null)}
                className="px-4 py-2 text-sm font-medium text-gray-700 border rounded-lg hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={() => submitStatusUpdate(trackingDialog.orderId, trackingDialog.status, trackingInput || undefined)}
                disabled={updating === trackingDialog.orderId}
                className="px-4 py-2 text-sm font-medium text-white bg-pink-600 rounded-lg hover:bg-pink-700 disabled:opacity-50"
              >
                {updating ? "Updating..." : "Confirm & Ship"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { fetcher } from "@/lib/http/fetcher";
import { Undo2, ChevronLeft, ChevronRight, X } from "lucide-react";

interface ReturnRequest {
  id: string;
  product_name: string;
  reason: string;
  description: string | null;
  quantity: number;
  refund_amount: number;
  status: string;
  provider_notes: string | null;
  created_at: string;
  order: { order_number: string };
  customer: { full_name: string; email: string };
}

const STATUS_COLORS: Record<string, string> = {
  pending: "bg-amber-100 text-amber-800",
  approved: "bg-blue-100 text-blue-800",
  item_received: "bg-purple-100 text-purple-800",
  refunded: "bg-green-100 text-green-800",
  rejected: "bg-red-100 text-red-800",
  escalated: "bg-red-200 text-red-900",
  resolved_by_admin: "bg-gray-100 text-gray-700",
  cancelled: "bg-gray-100 text-gray-600",
};

const ACTIONS: Record<string, { action: string; label: string; color: string }[]> = {
  pending: [
    { action: "approve", label: "Approve", color: "bg-blue-600 hover:bg-blue-700" },
    { action: "reject", label: "Reject", color: "bg-red-600 hover:bg-red-700" },
  ],
  approved: [
    { action: "mark_received", label: "Item Received", color: "bg-purple-600 hover:bg-purple-700" },
  ],
  item_received: [
    { action: "process_refund", label: "Process Refund", color: "bg-green-600 hover:bg-green-700" },
  ],
};

interface ActionDialog {
  returnId: string;
  action: string;
  label: string;
}

export default function ProviderReturnsPage() {
  const [returns, setReturns] = useState<ReturnRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState("");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [updating, setUpdating] = useState<string | null>(null);
  const [error, setError] = useState("");

  const [dialog, setDialog] = useState<ActionDialog | null>(null);
  const [dialogNotes, setDialogNotes] = useState("");
  const [dialogReturnMethod, setDialogReturnMethod] = useState("drop_off");

  const fetchReturns = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      params.set("page", String(page));
      if (statusFilter) params.set("status", statusFilter);

      const res = await fetcher.get<{
        data: { returns: ReturnRequest[]; pagination: { totalPages: number } };
      }>(`/api/provider/returns?${params}`);

      if (res?.data) {
        setReturns(res.data.returns);
        setTotalPages(res.data.pagination.totalPages);
      }
    } catch {
      setError("Failed to load returns");
    }
    setLoading(false);
  }, [page, statusFilter]);

  useEffect(() => {
    const id = setTimeout(() => fetchReturns(), 0);
    return () => clearTimeout(id);
  }, [fetchReturns]);

  const openActionDialog = (returnId: string, action: string, label: string) => {
    setDialog({ returnId, action, label });
    setDialogNotes("");
    setDialogReturnMethod("drop_off");
  };

  const submitAction = async () => {
    if (!dialog) return;
    setUpdating(dialog.returnId);
    setError("");
    try {
      const payload: Record<string, any> = { action: dialog.action };
      if (dialogNotes) payload.provider_notes = dialogNotes;
      if (dialog.action === "approve") {
        payload.return_method = dialogReturnMethod;
        payload.resolution = "full_refund";
      }

      await fetcher.patch(`/api/provider/returns/${dialog.returnId}`, payload);
      fetchReturns();
    } catch {
      setError("Failed to update return");
    }
    setUpdating(null);
    setDialog(null);
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-gray-900">Returns & Refunds</h1>
        <p className="text-sm text-gray-500 mt-1">Manage customer return requests and process refunds</p>
      </div>

      {error && (
        <div className="flex items-center justify-between bg-red-50 border border-red-200 rounded-lg px-4 py-3 text-sm text-red-700">
          {error}
          <button onClick={() => setError("")}><X className="w-4 h-4" /></button>
        </div>
      )}

      <div className="flex items-center gap-3 flex-wrap">
        {["", "pending", "approved", "item_received", "refunded", "rejected", "escalated"].map(
          (s) => (
            <button
              key={s}
              onClick={() => { setStatusFilter(s); setPage(1); }}
              className={`px-3 py-1.5 rounded-full text-sm font-medium transition-colors ${
                statusFilter === s
                  ? "bg-pink-600 text-white"
                  : "bg-gray-100 text-gray-700 hover:bg-gray-200"
              }`}
            >
              {s ? s.replace(/_/g, " ") : "All"}
            </button>
          ),
        )}
      </div>

      <div className="bg-white rounded-xl border overflow-hidden">
        {loading ? (
          <div className="p-12 text-center text-gray-500">Loading...</div>
        ) : returns.length === 0 ? (
          <div className="p-12 text-center">
            <Undo2 className="w-12 h-12 text-gray-300 mx-auto mb-3" />
            <p className="text-gray-500">No return requests</p>
          </div>
        ) : (
          <div className="divide-y">
            {returns.map((r) => {
              const actions = ACTIONS[r.status] ?? [];
              return (
                <div key={r.id} className="p-5 hover:bg-gray-50 transition-colors">
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="font-semibold text-gray-900">{r.order?.order_number}</span>
                        <span
                          className={`text-xs px-2 py-0.5 rounded-full font-medium ${STATUS_COLORS[r.status]}`}
                        >
                          {r.status.replace(/_/g, " ")}
                        </span>
                      </div>
                      <p className="text-sm text-gray-700">{r.product_name}</p>
                      <div className="flex items-center gap-4 mt-1 text-xs text-gray-500">
                        <span>{r.customer?.full_name}</span>
                        <span>Reason: {r.reason.replace(/_/g, " ")}</span>
                        <span>Qty: {r.quantity}</span>
                      </div>
                      {r.description && (
                        <p className="text-xs text-gray-400 mt-2 italic">&quot;{r.description}&quot;</p>
                      )}
                      {r.provider_notes && (
                        <p className="text-xs text-blue-600 mt-1">Notes: {r.provider_notes}</p>
                      )}
                    </div>
                    <div className="text-right shrink-0">
                      <p className="text-lg font-bold text-gray-900">R{Number(r.refund_amount).toFixed(2)}</p>
                      <p className="text-xs text-gray-500">
                        {new Date(r.created_at).toLocaleDateString()}
                      </p>
                      {actions.length > 0 && (
                        <div className="flex gap-2 mt-2 justify-end">
                          {actions.map((a) => (
                            <button
                              key={a.action}
                              onClick={() => openActionDialog(r.id, a.action, a.label)}
                              disabled={updating === r.id}
                              className={`px-3 py-1.5 text-xs font-medium text-white rounded-lg ${a.color} disabled:opacity-50`}
                            >
                              {updating === r.id ? "..." : a.label}
                            </button>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-2">
          <button onClick={() => setPage(Math.max(1, page - 1))} disabled={page <= 1} className="p-2 border rounded-lg hover:bg-gray-50 disabled:opacity-50">
            <ChevronLeft className="w-4 h-4" />
          </button>
          <span className="text-sm text-gray-600">Page {page} of {totalPages}</span>
          <button onClick={() => setPage(Math.min(totalPages, page + 1))} disabled={page >= totalPages} className="p-2 border rounded-lg hover:bg-gray-50 disabled:opacity-50">
            <ChevronRight className="w-4 h-4" />
          </button>
        </div>
      )}

      {/* Action dialog */}
      {dialog && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
          <div className="bg-white rounded-2xl p-6 w-full max-w-md shadow-xl">
            <h3 className="text-lg font-bold text-gray-900 mb-4">{dialog.label}</h3>

            {dialog.action === "approve" && (
              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 mb-2">Return Method</label>
                <div className="grid grid-cols-3 gap-2">
                  {[
                    { value: "drop_off", label: "Drop Off" },
                    { value: "courier", label: "Courier" },
                    { value: "not_required", label: "Not Required" },
                  ].map((m) => (
                    <button
                      key={m.value}
                      onClick={() => setDialogReturnMethod(m.value)}
                      className={`px-3 py-2 text-xs font-medium rounded-lg border-2 transition-colors ${
                        dialogReturnMethod === m.value
                          ? "border-pink-500 bg-pink-50 text-pink-700"
                          : "border-gray-200 text-gray-600 hover:bg-gray-50"
                      }`}
                    >
                      {m.label}
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">Notes (optional)</label>
              <textarea
                value={dialogNotes}
                onChange={(e) => setDialogNotes(e.target.value)}
                placeholder="Add any notes for the customer..."
                rows={3}
                className="w-full border rounded-lg p-3 text-sm resize-none focus:ring-2 focus:ring-pink-500 focus:border-pink-500"
              />
            </div>

            <div className="flex gap-3 justify-end">
              <button
                onClick={() => setDialog(null)}
                className="px-4 py-2 text-sm font-medium text-gray-700 border rounded-lg hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={submitAction}
                disabled={!!updating}
                className="px-4 py-2 text-sm font-medium text-white bg-pink-600 rounded-lg hover:bg-pink-700 disabled:opacity-50"
              >
                {updating ? "Processing..." : "Confirm"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { fetcher } from "@/lib/http/fetcher";
import {
  Search,
  Plus,
  Minus,
  ShoppingCart,
  Loader2,
  CheckCircle2,
  Banknote,
  CreditCard,
  X,
  User,
  Phone,
  History,
} from "lucide-react";

interface Product {
  id: string;
  name: string;
  brand: string | null;
  retail_price: number;
  quantity: number;
  image_urls: string[];
  is_active: boolean;
}

interface CartItem {
  product: Product;
  qty: number;
}

interface WalkInOrder {
  id: string;
  order_number: string;
  total_amount: number;
  payment_method: string;
  customer_name: string | null;
  created_at: string;
  items: Array<{ product_name: string; quantity: number; unit_price: number }>;
}

export default function WalkInSalePage() {
  const [products, setProducts] = useState<Product[]>([]);
  const [search, setSearch] = useState("");
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customerName, setCustomerName] = useState("");
  const [customerPhone, setCustomerPhone] = useState("");
  const [paymentMethod, setPaymentMethod] = useState<"cash" | "yoco">("cash");
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);
  const [success, setSuccess] = useState<{ orderNumber: string; total: number } | null>(null);
  const [error, setError] = useState("");
  const [recentSales, setRecentSales] = useState<WalkInOrder[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  const fetchProducts = useCallback(async () => {
    setLoading(true);
    const res = await fetcher.get<{ data: { products: Product[] } }>("/api/provider/products?limit=200");
    if (res?.data?.products) {
      setProducts(res.data.products.filter((p) => p.is_active && p.quantity > 0));
    }
    setLoading(false);
  }, []);

  const fetchHistory = useCallback(async () => {
    const res = await fetcher.get<{ data: { sales: WalkInOrder[] } }>(
      "/api/provider/product-sales?limit=20",
    );
    if (res?.data?.sales) setRecentSales(res.data.sales);
  }, []);

  useEffect(() => {
    const id = setTimeout(() => fetchProducts(), 0);
    return () => clearTimeout(id);
  }, [fetchProducts]);

  const filtered = products.filter(
    (p) =>
      (p?.name ?? "").toLowerCase().includes((search ?? "").toLowerCase()) ||
      (p?.brand ?? "").toLowerCase().includes((search ?? "").toLowerCase()),
  );

  const addToCart = (product: Product) => {
    setCart((prev) => {
      const existing = prev.find((c) => c.product.id === product.id);
      if (existing) {
        if (existing.qty >= product.quantity) return prev;
        return prev.map((c) =>
          c.product.id === product.id ? { ...c, qty: c.qty + 1 } : c,
        );
      }
      return [...prev, { product, qty: 1 }];
    });
  };

  const updateQty = (productId: string, delta: number) => {
    setCart((prev) =>
      prev
        .map((c) => {
          if (c.product.id !== productId) return c;
          const newQty = c.qty + delta;
          if (newQty <= 0) return null;
          if (newQty > c.product.quantity) return c;
          return { ...c, qty: newQty };
        })
        .filter(Boolean) as CartItem[],
    );
  };

  const removeFromCart = (productId: string) => {
    setCart((prev) => prev.filter((c) => c.product.id !== productId));
  };

  const total = cart.reduce((s, c) => s + c.product.retail_price * c.qty, 0);

  const handleSale = async () => {
    if (cart.length === 0 || processing) return;
    setProcessing(true);
    setError("");

    try {
      const res = await fetcher.post<{
        data: { order: { order_number: string } };
        error?: string;
      }>("/api/provider/product-sales", {
        items: cart.map((c) => ({
          product_id: c.product.id,
          quantity: c.qty,
        })),
        payment_method: paymentMethod,
        customer_name: customerName || undefined,
        customer_phone: customerPhone || undefined,
      });

      if (res?.data?.order) {
        setSuccess({ orderNumber: res.data.order.order_number, total });
        setCart([]);
        setCustomerName("");
        setCustomerPhone("");
        fetchProducts();
      } else {
        setError((res as any)?.error || "Failed to process sale");
      }
    } catch (err: any) {
      setError(err?.message || "Something went wrong");
    }
    setProcessing(false);
  };

  if (success) {
    return (
      <div className="flex min-h-[60vh] flex-col items-center justify-center">
        <CheckCircle2 className="mb-4 h-16 w-16 text-green-500" />
        <h2 className="mb-2 text-2xl font-bold text-gray-900">Sale Complete!</h2>
        <p className="mb-1 text-gray-600">Order: {success.orderNumber}</p>
        <p className="mb-6 text-2xl font-bold text-pink-600">
          R{success.total.toFixed(2)}
        </p>
        <button
          onClick={() => setSuccess(null)}
          className="rounded-xl bg-pink-600 px-8 py-3 font-semibold text-white hover:bg-pink-700 transition-colors"
        >
          New Sale
        </button>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="mx-auto max-w-7xl px-4 py-6 sm:px-6 lg:px-8">
        <div className="mb-6 flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">Walk-in Sale</h1>
            <p className="text-sm text-gray-500">Process in-person product sales (cash or Yoco)</p>
          </div>
          <button
            onClick={() => {
              setShowHistory(!showHistory);
              if (!showHistory) fetchHistory();
            }}
            className="flex items-center gap-2 rounded-lg border border-gray-200 bg-white px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50"
          >
            <History className="h-4 w-4" />
            {showHistory ? "Back to POS" : "Sales History"}
          </button>
        </div>

        {showHistory ? (
          <div className="space-y-4">
            {recentSales.length === 0 ? (
              <div className="py-16 text-center text-gray-400">
                <History className="mx-auto mb-4 h-12 w-12" />
                <p>No walk-in sales yet</p>
              </div>
            ) : (
              recentSales.map((sale) => (
                <div key={sale.id} className="rounded-xl bg-white border p-5">
                  <div className="flex items-center justify-between mb-3">
                    <div>
                      <span className="font-bold text-gray-900">{sale.order_number}</span>
                      {sale.customer_name && (
                        <span className="ml-3 text-sm text-gray-500">{sale.customer_name}</span>
                      )}
                    </div>
                    <div className="text-right">
                      <p className="font-bold text-pink-600">R{Number(sale.total_amount).toFixed(2)}</p>
                      <p className="text-xs text-gray-400">
                        {new Date(sale.created_at).toLocaleString("en-ZA")}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2 text-xs text-gray-500">
                    {sale.payment_method === "cash" ? (
                      <Banknote className="h-3.5 w-3.5" />
                    ) : (
                      <CreditCard className="h-3.5 w-3.5" />
                    )}
                    <span className="capitalize">{sale.payment_method}</span>
                    <span className="text-gray-300">┬╖</span>
                    <span>{sale.items?.length ?? 0} item(s)</span>
                  </div>
                </div>
              ))
            )}
          </div>
        ) : (
          <div className="grid gap-6 lg:grid-cols-5">
            {/* Product catalog - left */}
            <div className="lg:col-span-3">
              <div className="relative mb-4">
                <Search className="absolute left-3 top-3 h-4 w-4 text-gray-400" />
                <input
                  type="text"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  placeholder="Search products..."
                  className="w-full rounded-xl border border-gray-200 bg-white py-3 pl-10 pr-4 text-sm focus:border-pink-500 focus:outline-none focus:ring-1 focus:ring-pink-500"
                />
              </div>

              {loading ? (
                <div className="flex items-center justify-center py-16">
                  <Loader2 className="h-8 w-8 animate-spin text-pink-500" />
                </div>
              ) : filtered.length === 0 ? (
                <div className="py-16 text-center text-gray-400">No products in stock</div>
              ) : (
                <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
                  {filtered.map((product) => {
                    const inCart = cart.find((c) => c.product.id === product.id);
                    return (
                      <button
                        key={product.id}
                        onClick={() => addToCart(product)}
                        className="group relative overflow-hidden rounded-xl border bg-white p-3 text-left transition hover:border-pink-300 hover:shadow-sm"
                      >
                        {inCart && (
                          <span className="absolute right-2 top-2 flex h-6 w-6 items-center justify-center rounded-full bg-pink-600 text-xs font-bold text-white">
                            {inCart.qty}
                          </span>
                        )}
                        <p className="text-sm font-semibold text-gray-900 line-clamp-2">
                          {product.name}
                        </p>
                        {product.brand && (
                          <p className="text-xs text-gray-400">{product.brand}</p>
                        )}
                        <div className="mt-2 flex items-center justify-between">
                          <span className="font-bold text-pink-600">
                            R{product.retail_price.toFixed(2)}
                          </span>
                          <span className="text-xs text-gray-400">
                            {product.quantity} in stock
                          </span>
                        </div>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Cart - right */}
            <div className="lg:col-span-2">
              <div className="sticky top-6 rounded-2xl border bg-white shadow-sm">
                <div className="border-b px-5 py-4">
                  <h2 className="flex items-center gap-2 font-bold text-gray-900">
                    <ShoppingCart className="h-5 w-5" />
                    Sale ({cart.reduce((s, c) => s + c.qty, 0)})
                  </h2>
                </div>

                {cart.length === 0 ? (
                  <div className="px-5 py-10 text-center text-gray-400 text-sm">
                    Tap products to add them
                  </div>
                ) : (
                  <div className="max-h-[320px] divide-y overflow-y-auto px-5">
                    {cart.map((item) => (
                      <div key={item.product.id} className="flex items-center gap-3 py-3">
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-gray-900 truncate">
                            {item.product.name}
                          </p>
                          <p className="text-xs text-gray-400">
                            R{item.product.retail_price.toFixed(2)} each
                          </p>
                        </div>
                        <div className="flex items-center gap-1.5">
                          <button
                            onClick={() => updateQty(item.product.id, -1)}
                            className="flex h-7 w-7 items-center justify-center rounded-full border text-gray-500 hover:bg-gray-50"
                          >
                            <Minus className="h-3.5 w-3.5" />
                          </button>
                          <span className="w-7 text-center text-sm font-bold">{item.qty}</span>
                          <button
                            onClick={() => updateQty(item.product.id, 1)}
                            className="flex h-7 w-7 items-center justify-center rounded-full border text-gray-500 hover:bg-gray-50"
                          >
                            <Plus className="h-3.5 w-3.5" />
                          </button>
                        </div>
                        <span className="w-20 text-right text-sm font-semibold text-gray-900">
                          R{(item.product.retail_price * item.qty).toFixed(2)}
                        </span>
                        <button
                          onClick={() => removeFromCart(item.product.id)}
                          className="text-gray-300 hover:text-red-500"
                        >
                          <X className="h-4 w-4" />
                        </button>
                      </div>
                    ))}
                  </div>
                )}

                {/* Customer info (optional) */}
                <div className="border-t px-5 py-4 space-y-3">
                  <div className="flex gap-3">
                    <div className="relative flex-1">
                      <User className="absolute left-3 top-2.5 h-4 w-4 text-gray-400" />
                      <input
                        type="text"
                        value={customerName}
                        onChange={(e) => setCustomerName(e.target.value)}
                        placeholder="Customer name (optional)"
                        className="w-full rounded-lg border border-gray-200 py-2 pl-9 pr-3 text-sm focus:border-pink-500 focus:outline-none"
                      />
                    </div>
                    <div className="relative flex-1">
                      <Phone className="absolute left-3 top-2.5 h-4 w-4 text-gray-400" />
                      <input
                        type="tel"
                        value={customerPhone}
                        onChange={(e) => setCustomerPhone(e.target.value)}
                        placeholder="Phone (optional)"
                        className="w-full rounded-lg border border-gray-200 py-2 pl-9 pr-3 text-sm focus:border-pink-500 focus:outline-none"
                      />
                    </div>
                  </div>

                  {/* Payment method */}
                  <div className="grid grid-cols-2 gap-2">
                    <button
                      onClick={() => setPaymentMethod("cash")}
                      className={`flex items-center justify-center gap-2 rounded-lg border-2 py-2.5 text-sm font-medium transition-colors ${
                        paymentMethod === "cash"
                          ? "border-pink-500 bg-pink-50 text-pink-700"
                          : "border-gray-200 text-gray-600 hover:bg-gray-50"
                      }`}
                    >
                      <Banknote className="h-4 w-4" />
                      Cash
                    </button>
                    <button
                      onClick={() => setPaymentMethod("yoco")}
                      className={`flex items-center justify-center gap-2 rounded-lg border-2 py-2.5 text-sm font-medium transition-colors ${
                        paymentMethod === "yoco"
                          ? "border-pink-500 bg-pink-50 text-pink-700"
                          : "border-gray-200 text-gray-600 hover:bg-gray-50"
                      }`}
                    >
                      <CreditCard className="h-4 w-4" />
                      Yoco Card
                    </button>
                  </div>
                </div>

                {/* Total + confirm */}
                <div className="border-t px-5 py-4">
                  <div className="mb-4 flex items-center justify-between">
                    <span className="text-lg font-semibold text-gray-900">Total</span>
                    <span className="text-2xl font-extrabold text-pink-600">
                      R{total.toFixed(2)}
                    </span>
                  </div>

                  {error && (
                    <div className="mb-3 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-600">
                      {error}
                    </div>
                  )}

                  <button
                    onClick={handleSale}
                    disabled={cart.length === 0 || processing}
                    className="w-full rounded-xl bg-pink-600 py-3.5 text-center font-bold text-white transition-colors hover:bg-pink-700 disabled:opacity-50 flex items-center justify-center gap-2"
                  >
                    {processing ? (
                      <>
                        <Loader2 className="h-5 w-5 animate-spin" />
                        Processing...
                      </>
                    ) : (
                      `Complete Sale ΓÇö R${total.toFixed(2)}`
                    )}
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

