"use client";

/**
 * Embed entry for provider app in-app WebView.
 * Waits for session to be injected by the app (window.__providerAppSession), then sets session and redirects to path.
 * Used so providers can view any provider portal page inside the app without leaving it.
 */
import { useEffect, useState } from "react";
import { useSearchParams } from "next/navigation";
import { getSupabaseClient } from "@/lib/supabase/client";

declare global {
  interface Window {
    __providerAppSession?: { access_token: string; refresh_token: string };
    __providerAppSessionReady?: () => void;
  }
}

export default function ProviderEmbedPage() {
  const searchParams = useSearchParams();
  const path = searchParams.get("path") || "/provider/dashboard";
  const [status, setStatus] = useState<"waiting" | "setting" | "redirecting" | "error">("waiting");
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    const supabase = getSupabaseClient();
    if (!supabase) {
      setStatus("error");
      setErrorMsg("Client not available");
      return;
    }

    const getSessionFromHash = (): { access_token: string; refresh_token: string } | null => {
      const hash = typeof window !== "undefined" ? window.location.hash.slice(1) : "";
      if (!hash) return null;
      try {
        const decoded = decodeURIComponent(hash);
        const data = JSON.parse(decoded) as { access_token?: string; refresh_token?: string };
        if (data?.access_token && data?.refresh_token) return { access_token: data.access_token, refresh_token: data.refresh_token };
      } catch {
        // ignore
      }
      return null;
    };

    const applySession = async (): Promise<boolean> => {
      const session = getSessionFromHash() || window.__providerAppSession;
      if (!session?.access_token || !session.refresh_token) return false;
      setStatus("setting");
      try {
        const { error } = await supabase.auth.setSession({
          access_token: session.access_token,
          refresh_token: session.refresh_token,
        });
        if (cancelled) return true;
        if (error) {
          setStatus("error");
          setErrorMsg(error.message);
          return true;
        }
        setStatus("redirecting");
        const target = path.startsWith("/") ? path : `/${path}`;
        window.location.replace(target);
        return true;
      } catch (e) {
        if (!cancelled) {
          setStatus("error");
          setErrorMsg(e instanceof Error ? e.message : "Failed to set session");
        }
        return true;
      }
    };

    const timeoutMs = 12_000;
    const timeoutId = setTimeout(() => {
      if (cancelled) return;
      setStatus("error");
      setErrorMsg("Session not received. Open this from the provider app while signed in, or use the link below.");
    }, timeoutMs);

    let checkId: ReturnType<typeof setTimeout>;
    const check = async () => {
      if (await applySession()) return;
      if (cancelled) return;
      checkId = setTimeout(check, 200);
    };
    checkId = setTimeout(check, 100);

    return () => {
      cancelled = true;
      clearTimeout(checkId);
      clearTimeout(timeoutId);
    };
  }, [path]);

  return (
    <div className="flex min-h-screen flex-col items-center justify-center bg-gray-50 p-6">
      {status === "waiting" && (
        <>
          <div className="h-10 w-10 animate-spin rounded-full border-2 border-[#FF0077] border-t-transparent" />
          <p className="mt-4 text-gray-600">Loading session from appΓÇª</p>
        </>
      )}
      {status === "setting" && (
        <>
          <div className="h-10 w-10 animate-spin rounded-full border-2 border-[#FF0077] border-t-transparent" />
          <p className="mt-4 text-gray-600">Signing you inΓÇª</p>
        </>
      )}
      {status === "redirecting" && (
        <>
          <div className="h-10 w-10 animate-spin rounded-full border-2 border-[#FF0077] border-t-transparent" />
          <p className="mt-4 text-gray-600">RedirectingΓÇª</p>
        </>
      )}
      {status === "error" && (
        <>
          <p className="text-red-600">{errorMsg || "Something went wrong."}</p>
          <a href="/provider" className="mt-4 text-[#FF0077] underline">Open provider portal</a>
        </>
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useRouter, useParams } from "next/navigation";
import Link from "next/link";
import { ExplorePostForm } from "@/components/provider/ExplorePostForm";
import RoleGuard from "@/components/auth/RoleGuard";
import { fetcher } from "@/lib/http/fetcher";
import { Loader2, ChevronLeft } from "lucide-react";
import type { ExplorePost } from "@/types/explore";

export default function ProviderExploreEditPage() {
  const router = useRouter();
  const params = useParams();
  const id = params?.id as string;
  const [post, setPost] = useState<ExplorePost | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    fetcher
      .get<{ data: ExplorePost }>(`/api/explore/posts/mine`)
      .then((res: any) => {
        const data = res?.data ?? res;
        const list = Array.isArray(data) ? data : (data?.data ? [data.data] : []);
        const found = list.find((p: ExplorePost) => p.id === id);
        setPost(found ?? null);
      })
      .catch(() => setPost(null))
      .finally(() => setIsLoading(false));
  }, [id]);

  if (isLoading) {
    return (
      <RoleGuard
        allowedRoles={["provider_owner", "provider_staff"]}
        redirectTo="/provider/dashboard"
        showLoading={false}
      >
        <div className="min-h-screen bg-white flex items-center justify-center">
          <Loader2 className="w-10 h-10 animate-spin text-[#FF0077]" />
        </div>
      </RoleGuard>
    );
  }

  if (!post) {
    return (
      <RoleGuard
        allowedRoles={["provider_owner", "provider_staff"]}
        redirectTo="/provider/dashboard"
        showLoading={false}
      >
        <div className="min-h-screen bg-white flex flex-col items-center justify-center px-4">
          <p className="text-gray-600 mb-4">Post not found</p>
          <button
            onClick={() => router.push("/provider/explore")}
            className="text-[#FF0077] hover:underline"
          >
            Back to Explore
          </button>
        </div>
      </RoleGuard>
    );
  }

  // media_urls from API are full URLs; ExplorePostForm expects paths for edit
  const postForForm: ExplorePost = {
    ...post,
    media_urls: (post.media_urls ?? []).map((url) => {
      const match = url.match(/\/explore-posts\/(.+)$/);
      return match ? match[1] : url;
    }),
  };

  return (
    <RoleGuard
      allowedRoles={["provider_owner", "provider_staff"]}
      redirectTo="/provider/dashboard"
      showLoading={false}
    >
      <div className="min-h-screen bg-white">
