                      <span>{post.comment_count ?? 0} comments</span>
                      {typeof post.view_count === "number" && (
                        <span>{post.view_count} views</span>
                      )}
                      {post.status === "published" && (
                        <Link
                          href="/explore"
                          target="_blank"
                          rel="noopener noreferrer"
                          className="ml-auto flex items-center gap-1 text-[#FF0077] hover:underline"
                        >
                          <ExternalLink className="w-3 h-3" />
                          View on Explore
                        </Link>
                      )}
                    </div>
                    <div className="flex gap-2 flex-wrap">
                      <Link href={`/provider/explore/${post.id}`}>
                        <Button variant="outline" size="sm">
                          <MessageCircle className="w-3 h-3 mr-1" />
                          View & comments
                        </Button>
                      </Link>
                      <Link href={`/provider/explore/${post.id}/edit`}>
                        <Button variant="outline" size="sm">
                          <Pencil className="w-3 h-3 mr-1" />
                          Edit
                        </Button>
                      </Link>
                      <Button
                        variant="outline"
                        size="sm"
                        className="text-red-600 hover:bg-red-50 border-red-200"
                        onClick={() => handleDelete(post.id)}
                      >
                        <Trash2 className="w-3 h-3" />
                      </Button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { ExpressBookingLink } from "@/lib/provider-portal/types";
import { PageHeader } from "@/components/provider/PageHeader";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Plus, Edit, Trash2, Copy, ExternalLink, Eye } from "lucide-react";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { SectionCard } from "@/components/provider/SectionCard";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
