import { Checkbox } from "@/components/ui/checkbox";
import { toast } from "sonner";

export default function ExpressBookingLinksPage() {
  const [links, setLinks] = useState<ExpressBookingLink[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [selectedLink, setSelectedLink] = useState<ExpressBookingLink | null>(null);

  const loadLinks = useCallback(async () => {
    try {
      setIsLoading(true);
      const data = await providerApi.listExpressBookingLinks();
      setLinks(data);
    } catch (error) {
      console.error("Failed to load express booking links:", error);
      toast.error("Failed to load express booking links");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadLinks();
  }, [loadLinks]);

  const handleCreate = () => {
    setSelectedLink(null);
    setIsDialogOpen(true);
  };

  const handleEdit = (link: ExpressBookingLink) => {
    setSelectedLink(link);
    setIsDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this booking link?")) return;

    try {
      await providerApi.deleteExpressBookingLink(id);
      toast.success("Link deleted");
      loadLinks();
    } catch (error) {
      console.error("Failed to delete link:", error);
      toast.error("Failed to delete link");
    }
  };

  const handleCopyLink = (link: ExpressBookingLink) => {
    navigator.clipboard.writeText(link.full_url);
    toast.success("Link copied to clipboard");
  };

  const handleViewLink = (link: ExpressBookingLink) => {
    window.open(link.full_url, "_blank");
  };

  const isExpired = (link: ExpressBookingLink) => {
    if (!link.expires_at) return false;
    return new Date(link.expires_at) < new Date();
  };

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading express booking links..." />;
  }

  return (
    <div>
      <PageHeader
        title="Express Booking Links"
        subtitle="Create quick booking links for specific services or team members"
        primaryAction={{
          label: "New Link",
          onClick: handleCreate,
          icon: <Plus className="w-4 h-4 mr-2" />,
        }}
      />

      {links.length === 0 ? (
        <SectionCard className="p-12">
          <EmptyState
            title="No express booking links"
            description="Create booking links to share with clients for quick appointment booking"
            action={{
              label: "Create Link",
              onClick: handleCreate,
            }}
          />
        </SectionCard>
      ) : (
        <SectionCard className="p-0 overflow-hidden">
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Name</TableHead>
                  <TableHead>Short Code</TableHead>
                  <TableHead>Service</TableHead>
                  <TableHead>Team Member</TableHead>
                  <TableHead>Usage</TableHead>
                  <TableHead>Expires</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {links.map((link) => (
                  <TableRow key={link.id}>
                    <TableCell className="font-medium">{link.name}</TableCell>
                    <TableCell>
                      <code className="px-2 py-1 bg-gray-100 rounded text-sm">
                        {link.short_code}
                      </code>
                    </TableCell>
                    <TableCell>
                      {link.service_id ? (
                        <Badge variant="outline">Pre-selected</Badge>
                      ) : (
                        <span className="text-gray-400">Any</span>
                      )}
                    </TableCell>
                    <TableCell>
                      {link.team_member_id ? (
                        <Badge variant="outline">Pre-selected</Badge>
                      ) : (
                        <span className="text-gray-400">Any</span>
                      )}
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-1">
                        <Eye className="w-3 h-3 text-gray-400" />
                        <span>{link.usage_count} clicks</span>
                      </div>
                    </TableCell>
                    <TableCell>
                      {link.expires_at ? (
                        <span
                          className={
                            isExpired(link)
                              ? "text-red-600"
                              : new Date(link.expires_at) <
                                new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)
                              ? "text-yellow-600"
                              : ""
                          }
                        >
                          {new Date(link.expires_at).toLocaleDateString()}
                        </span>
                      ) : (
                        <span className="text-gray-400">Never</span>
                      )}
                    </TableCell>
                    <TableCell>
                      {!link.is_active ? (
                        <Badge className="bg-gray-100 text-gray-800">Inactive</Badge>
                      ) : isExpired(link) ? (
                        <Badge className="bg-red-100 text-red-800">Expired</Badge>
                      ) : (
                        <Badge className="bg-green-100 text-green-800">Active</Badge>
                      )}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex items-center justify-end gap-2">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleCopyLink(link)}
                          title="Copy link"
                        >
                          <Copy className="w-3 h-3" />
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleViewLink(link)}
                          title="View link"
                        >
                          <ExternalLink className="w-3 h-3" />
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleEdit(link)}
                        >
                          <Edit className="w-3 h-3 mr-1" />
                          Edit
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleDelete(link.id)}
                          className="text-red-600 hover:text-red-700"
                        >
                          <Trash2 className="w-3 h-3 mr-1" />
                          Delete
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        </SectionCard>
      )}

      <ExpressBookingLinkDialog
        open={isDialogOpen}
        onOpenChange={setIsDialogOpen}
        link={selectedLink}
        onSuccess={loadLinks}
      />
    </div>
  );
}

// Express Booking Link Create/Edit Dialog
function ExpressBookingLinkDialog({
  open,
  onOpenChange,
  link,
  onSuccess,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  link: ExpressBookingLink | null;
  onSuccess: () => void;
}) {
  const [formData, setFormData] = useState({
    name: "",
    short_code: "",
    service_id: "",
    team_member_id: "",
    expires_at: "",
    is_active: true,
  });
  const [isLoading, setIsLoading] = useState(false);
  const [services, setServices] = useState<any[]>([]);
  const [teamMembers, setTeamMembers] = useState<any[]>([]);

  useEffect(() => {
    if (open) {
      loadData();
      if (link) {
        setFormData({
          name: link.name,
          short_code: link.short_code,
          service_id: link.service_id || "",
          team_member_id: link.team_member_id || "",
          expires_at: link.expires_at
            ? new Date(link.expires_at).toISOString().split("T")[0]
            : "",
          is_active: link.is_active,
        });
      } else {
        // Generate random short code for new links
        const randomCode = Math.random().toString(36).substring(2, 8).toUpperCase();
        setFormData({
          name: "",
          short_code: randomCode,
          service_id: "",
          team_member_id: "",
          expires_at: "",
          is_active: true,
        });
      }
    }
  }, [open, link]);

  const loadData = async () => {
    try {
      const [categories, members] = await Promise.all([
        providerApi.listServiceCategories(),
        providerApi.listTeamMembers(),
      ]);
      setServices(categories.flatMap((cat) => cat.services));
      setTeamMembers(members);
    } catch (error) {
      console.error("Failed to load data:", error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const linkData: any = {
        name: formData.name,
        short_code: formData.short_code,
        is_active: formData.is_active,
        expires_at: formData.expires_at
          ? new Date(formData.expires_at).toISOString()
          : undefined,
      };

      if (formData.service_id) {
        linkData.service_id = formData.service_id;
      }

      if (formData.team_member_id) {
        linkData.team_member_id = formData.team_member_id;
      }

      if (link) {
        await providerApi.updateExpressBookingLink(link.id, linkData);
        toast.success("Link updated");
      } else {
        await providerApi.createExpressBookingLink(linkData);
        toast.success("Link created");
      }
      onSuccess();
      onOpenChange(false);
    } catch (error) {
      console.error("Failed to save link:", error);
      toast.error("Failed to save link");
    } finally {
      setIsLoading(false);
    }
  };

  const generateRandomCode = () => {
    const randomCode = Math.random().toString(36).substring(2, 8).toUpperCase();
    setFormData({ ...formData, short_code: randomCode });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{link ? "Edit Booking Link" : "New Express Booking Link"}</DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="name">Link Name *</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              placeholder="e.g., Haircut Special Booking"
              required
            />
          </div>

          <div>
            <Label htmlFor="short_code">Short Code *</Label>
            <div className="flex gap-2">
              <Input
                id="short_code"
                value={formData.short_code}
                onChange={(e) =>
                  setFormData({ ...formData, short_code: e.target.value.toUpperCase() })
                }
                placeholder="ABC123"
                required
                maxLength={10}
              />
              <Button
                type="button"
                variant="outline"
                onClick={generateRandomCode}
              >
                Generate
              </Button>
            </div>
            <p className="text-xs text-gray-500 mt-1">
              URL will be: {typeof window !== "undefined" && window.location.origin}/book/
              {formData.short_code}
            </p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="service_id">Pre-select Service (Optional)</Label>
              <Select
                value={formData.service_id}
                onValueChange={(value) =>
                  setFormData({ ...formData, service_id: value })
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="Any service" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">Any service</SelectItem>
                  {services.map((service) => (
                    <SelectItem key={service.id} value={service.id}>
                      {service.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label htmlFor="team_member_id">Pre-select Team Member (Optional)</Label>
              <Select
                value={formData.team_member_id}
                onValueChange={(value) =>
                  setFormData({ ...formData, team_member_id: value })
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="Any team member" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">Any team member</SelectItem>
                  {teamMembers.map((member) => (
                    <SelectItem key={member.id} value={member.id}>
                      {member.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div>
            <Label htmlFor="expires_at">Expiration Date (Optional)</Label>
            <Input
              id="expires_at"
              type="date"
              value={formData.expires_at}
              onChange={(e) => setFormData({ ...formData, expires_at: e.target.value })}
            />
            <p className="text-xs text-gray-500 mt-1">
              Leave empty for no expiration
            </p>
          </div>

          <div className="flex items-center gap-2">
            <Checkbox
              id="is_active"
              checked={formData.is_active}
              onCheckedChange={(checked) =>
                setFormData({ ...formData, is_active: !!checked })
              }
            />
            <Label htmlFor="is_active" className="cursor-pointer">
              Active
            </Label>
          </div>

          <div className="p-3 bg-blue-50 rounded-lg text-sm text-blue-800">
            <p className="font-medium mb-1">How it works:</p>
            <ul className="list-disc list-inside space-y-1">
              <li>Share the generated link with clients</li>
              <li>Clients can book appointments directly</li>
              <li>Pre-selected options will be pre-filled in the booking form</li>
              <li>Track usage to see how many clients use each link</li>
            </ul>
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isLoading}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isLoading}
              className="bg-[#FF0077] hover:bg-[#D60565]"
            >
              {isLoading ? "Saving..." : link ? "Update" : "Create"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { DollarSign, TrendingUp, Calendar, Download, ArrowUpRight, FileText } from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { useProviderPortal } from "@/providers/provider-portal/ProviderPortalProvider";
import { usePermissions } from "@/hooks/usePermissions";
import { Lock } from "lucide-react";

interface EarningsData {
  total_earnings: number;
  pending_payouts: number;
  available_balance: number;
  minimum_payout_amount?: number;
  this_month: number;
  last_month: number;
  growth_percentage: number;
  bookings_earnings_total?: number;
  gift_card_sales_this_period?: number;
  membership_sales_this_period?: number;
  travel_fees_total?: number;
  travel_fees_this_period?: number;
  refunds_total?: number;
}

interface Transaction {
  id: string;
  booking_id?: string | null;
  transaction_type?: string;
  type: "booking" | "payout" | "refund";
  amount: number;
  net?: number;
  fees?: number;
  commission?: number;
  currency: string;
  description: string;
  date: string;
  status: "completed" | "pending" | "failed";
}

interface Payout {
  id: string;
  provider_id: string;
  amount: number;
  currency: string;
  status: "pending" | "processing" | "completed" | "failed" | "cancelled";
  bank_account_id?: string;
  notes?: string;
  requested_at: string;
  processed_at?: string;
  failure_reason?: string;
}

interface PayoutAccount {
  id: string;
  account_name: string;
  account_number_last4: string;
  bank_name: string | null;
  active: boolean;
}

export default function ProviderFinance() {
  const { selectedLocationId } = useProviderPortal();
  const { hasPermission } = usePermissions();
  const canRequestPayout = hasPermission("process_payments");

  const [earnings, setEarnings] = useState<EarningsData | null>(null);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [payouts, setPayouts] = useState<Payout[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [dateRange, setDateRange] = useState<"week" | "month" | "year" | "all">("month");
  const [showPayoutDialog, setShowPayoutDialog] = useState(false);
  const [payoutAmount, setPayoutAmount] = useState("");
  const [payoutNotes, setPayoutNotes] = useState("");
  const [payoutAccounts, setPayoutAccounts] = useState<PayoutAccount[]>([]);
  const [selectedBankId, setSelectedBankId] = useState<string>("");
  const [isRequestingPayout, setIsRequestingPayout] = useState(false);
  const [selectedTransaction, setSelectedTransaction] = useState<Transaction | null>(null);
  const [showTransactionDialog, setShowTransactionDialog] = useState(false);
  const [transactionDetails, setTransactionDetails] = useState<any>(null);
  const [isLoadingDetails, setIsLoadingDetails] = useState(false);

  useEffect(() => {
    loadFinanceData();
    loadPayouts();
    loadPayoutAccounts();
  }, [dateRange, selectedLocationId]);

  const loadFinanceData = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const url = selectedLocationId
        ? `/api/provider/finance?range=${dateRange}&location_id=${selectedLocationId}`
        : `/api/provider/finance?range=${dateRange}`;

      const response = await fetcher.get<{
        data: { earnings: EarningsData; transactions: Transaction[] };
      }>(url);
      setEarnings(response.data.earnings);
      setTransactions(response.data.transactions);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load finance data";
      setError(errorMessage);
      console.error("Error loading finance data:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const loadPayouts = async () => {
    try {
      const response = await fetcher.get<{ data: Payout[] }>("/api/provider/payouts");
      setPayouts(response.data || []);
    } catch (err) {
      console.warn("Failed to load payouts:", err);
    }
  };

  const loadPayoutAccounts = async () => {
    try {
      const response = await fetcher.get<{ data: PayoutAccount[] }>("/api/provider/payout-accounts");
      const accts = response.data || [];
      setPayoutAccounts(accts);
      if (accts.length > 0 && !selectedBankId) setSelectedBankId(accts[0].id);
    } catch (err) {
      console.warn("Failed to load payout accounts:", err);
    }
  };

  const handleRequestPayout = async () => {
    if (!payoutAmount || parseFloat(payoutAmount) <= 0) {
      toast.error("Please enter a valid payout amount");
      return;
    }

    const minimumPayout = earnings?.minimum_payout_amount ?? 100;
    if (parseFloat(payoutAmount) < minimumPayout) {
      toast.error(`Minimum payout is ZAR ${minimumPayout.toLocaleString()}`);
      return;
    }
    if (!earnings || parseFloat(payoutAmount) > earnings.available_balance) {
      toast.error("Insufficient balance for this payout");
      return;
    }

    try {
      setIsRequestingPayout(true);
      const primaryId = payoutAccounts[0]?.id;
      await fetcher.post("/api/provider/payouts", {
        amount: parseFloat(payoutAmount),
        notes: payoutNotes || null,
        bank_account_id: selectedBankId || primaryId || undefined,
      });

      toast.success("Payout request submitted successfully");
      setShowPayoutDialog(false);
      setPayoutAmount("");
      setPayoutNotes("");
      loadFinanceData();
      loadPayouts();
      loadPayoutAccounts();
    } catch (err) {
      const errorMessage =
        err instanceof FetchError
          ? err.message
          : "Failed to request payout";
      toast.error(errorMessage);
      console.error("Error requesting payout:", err);
    } finally {
      setIsRequestingPayout(false);
    }
  };

  const handleExport = () => {
    try {
      const url = `/api/provider/finance/export?range=${encodeURIComponent(dateRange)}`;
      // Browser will download due to Content-Disposition on the response.
      window.open(url, "_blank", "noopener,noreferrer");
    } catch {
      alert("Failed to start export");
    }
  };

  const handleTransactionClick = async (transaction: Transaction) => {
    setSelectedTransaction(transaction);
    setShowTransactionDialog(true);
    setIsLoadingDetails(true);
    setTransactionDetails(null);

    try {
      // If transaction has a booking_id, fetch booking details
      if (transaction.booking_id) {
        try {
          const response = await fetcher.get<{ data: any }>(`/api/provider/bookings/${transaction.booking_id}`);
          setTransactionDetails(response?.data ?? null);
        } catch (bookingError: any) {
          // Booking might not exist or provider doesn't have access
          // Silently handle - we'll just show transaction info without booking details
          console.warn("Could not load booking details:", bookingError.message);
          setTransactionDetails(null);
        }
      }
      // For non-booking transactions (gift cards, memberships), transactionDetails stays null
      // and we'll just show the transaction info
    } catch (err) {
      console.error("Failed to load transaction details:", err);
      // Don't show error to user - just show transaction info without booking details
      setTransactionDetails(null);
    } finally {
      setIsLoadingDetails(false);
    }
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading finance data..." />
      </div>
    );
  }

  if (error || !earnings) {
    return (
      <div className="container mx-auto px-4 py-8">
        <EmptyState
          title="Failed to load finance data"
          description={error || "Unable to load earnings information"}
          action={{
            label: "Retry",
            onClick: loadFinanceData,
          }}
        />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["provider_owner", "provider_staff"]} redirectTo="/provider/dashboard">
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-6">
          <div>
            <h1 className="text-3xl font-semibold mb-2">Finance & Earnings</h1>
            <p className="text-gray-600">Track your revenue and earnings</p>
          </div>
          <div className="flex flex-wrap gap-2 mt-4 md:mt-0 items-center">
            {canRequestPayout ? (
            <Dialog open={showPayoutDialog} onOpenChange={setShowPayoutDialog}>
              <DialogTrigger asChild>
                <Button className="bg-[#FF0077] hover:bg-[#D60565]">
                  <ArrowUpRight className="w-4 h-4 mr-2" />
                  Request Payout
                </Button>
              </DialogTrigger>
              <DialogContent>
                <DialogHeader>
                  <DialogTitle>Request Payout</DialogTitle>
                  <DialogDescription>
                    Request a payout from your available balance
                  </DialogDescription>
                </DialogHeader>
                <div className="space-y-4 py-4">
                  <div>
                    <Label htmlFor="available-balance">Available Balance</Label>
                    <Input
                      id="available-balance"
                      value={`ZAR ${earnings.available_balance.toLocaleString()}`}
                      disabled
                      className="mt-1"
                    />
                  </div>
                  <div>
                    <Label htmlFor="payout-amount">Payout Amount (ZAR) * ΓÇö min ZAR {(earnings.minimum_payout_amount ?? 100).toLocaleString()}</Label>
                    <Input
                      id="payout-amount"
                      type="number"
                      min={earnings.minimum_payout_amount ?? 100}
                      max={earnings.available_balance}
                      step="0.01"
                      value={payoutAmount}
                      onChange={(e) => setPayoutAmount(e.target.value)}
                      placeholder="Enter amount"
                      className="mt-1"
                    />
                    {payoutAmount && parseFloat(payoutAmount) < (earnings.minimum_payout_amount ?? 100) && (
                      <p className="text-sm text-red-600 mt-1">
                        Below minimum payout (ZAR {(earnings.minimum_payout_amount ?? 100).toLocaleString()})
                      </p>
                    )}
                    {payoutAmount && parseFloat(payoutAmount) > earnings.available_balance && (
                      <p className="text-sm text-red-600 mt-1">
                        Amount exceeds available balance
                      </p>
                    )}
                  </div>
                  {payoutAccounts.length === 0 && (
                    <p className="text-sm text-amber-600">
                      Add a bank account in Settings ΓåÆ Payout Accounts to receive payouts.
                    </p>
                  )}
                  {payoutAccounts.length > 1 && (
                    <div>
                      <Label>Pay out to</Label>
                      <select
                        className="mt-1 w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
                        value={selectedBankId || payoutAccounts[0]?.id}
                        onChange={(e) => setSelectedBankId(e.target.value)}
                      >
                        {payoutAccounts.map((a) => (
                          <option key={a.id} value={a.id}>
                            {a.account_name} ****{a.account_number_last4}
                            {a.bank_name ? ` (${a.bank_name})` : ""}
                          </option>
                        ))}
                      </select>
                      <p className="text-xs text-gray-500 mt-1">Payouts will be sent to this account</p>
                    </div>
                  )}
                  {payoutAccounts.length === 1 && (
                    <p className="text-xs text-gray-500">
                      Payout will be sent to {payoutAccounts[0].account_name} ****{payoutAccounts[0].account_number_last4}.
                    </p>
                  )}
                  <div>
                    <Label htmlFor="payout-notes">Notes (Optional)</Label>
                    <Textarea
                      id="payout-notes"
                      value={payoutNotes}
                      onChange={(e) => setPayoutNotes(e.target.value)}
                      placeholder="Add any notes about this payout request"
                      className="mt-1"
                      rows={3}
                    />
                  </div>
                </div>
                <DialogFooter>
                  <Button
                    variant="outline"
                    onClick={() => {
                      setShowPayoutDialog(false);
                      setPayoutAmount("");
                      setPayoutNotes("");
                    }}
                  >
                    Cancel
                  </Button>
                  <Button
                    onClick={handleRequestPayout}
                    disabled={isRequestingPayout || payoutAccounts.length === 0 || !payoutAmount || parseFloat(payoutAmount) < (earnings.minimum_payout_amount ?? 100) || parseFloat(payoutAmount) > earnings.available_balance}
                    className="bg-[#FF0077] hover:bg-[#D60565]"
                  >
                    {isRequestingPayout ? "Submitting..." : "Request Payout"}
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>
            ) : (
              <div className="flex items-center gap-2 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-sm text-amber-800">
                <Lock className="h-4 w-4 flex-shrink-0" />
                <span>You don&apos;t have permission to request payouts. Contact your administrator.</span>
              </div>
            )}
            <Button variant="outline" onClick={handleExport}>
              <Download className="w-4 h-4 mr-2" />
              Export
            </Button>
            <Button 
              variant="outline" 
              onClick={() => window.location.href = "/provider/finance/vat-reports"}
              className="flex items-center gap-2"
            >
              <FileText className="w-4 h-4" />
              VAT Reports
            </Button>
          </div>
        </div>

        {/* Earnings Overview */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
          <div className="bg-white border rounded-lg p-6">
            <div className="flex items-center justify-between mb-2">
              <p className="text-sm text-gray-600">Total Earnings</p>
              <DollarSign className="w-5 h-5 text-gray-400" />
            </div>
            <p className="text-3xl font-semibold">
              ZAR {earnings.total_earnings.toLocaleString()}
            </p>
          </div>
          <div className="bg-white border rounded-lg p-6">
            <div className="flex items-center justify-between mb-2">
              <p className="text-sm text-gray-600">Available Balance</p>
              <TrendingUp className="w-5 h-5 text-gray-400" />
            </div>
            <p className="text-3xl font-semibold text-green-600">
              ZAR {earnings.available_balance.toLocaleString()}
            </p>
          </div>
          <div className="bg-white border rounded-lg p-6">
            <div className="flex items-center justify-between mb-2">
              <p className="text-sm text-gray-600">Pending Payouts</p>
              <Calendar className="w-5 h-5 text-gray-400" />
            </div>
            <p className="text-3xl font-semibold text-yellow-600">
              ZAR {earnings.pending_payouts.toLocaleString()}
            </p>
          </div>
        </div>

        {/* Revenue Streams */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-6 mb-8">
          <div className="bg-white border rounded-lg p-6">
            <p className="text-sm text-gray-600 mb-2">Service Earnings</p>
            <p className="text-2xl font-semibold">
              ZAR {(earnings.bookings_earnings_total || 0).toLocaleString()}
            </p>
          </div>
          <div className="bg-white border rounded-lg p-6">
            <p className="text-sm text-gray-600 mb-2">Travel Fees</p>
            <p className="text-2xl font-semibold text-purple-600">
              ZAR {(earnings.travel_fees_this_period || 0).toLocaleString()}
            </p>
            <p className="text-xs text-gray-500 mt-1">From at-home bookings</p>
          </div>
          <div className="bg-white border rounded-lg p-6">
            <p className="text-sm text-gray-600 mb-2">Gift Card Sales</p>
            <p className="text-2xl font-semibold">
              ZAR {(earnings.gift_card_sales_this_period || 0).toLocaleString()}
            </p>
          </div>
          <div className="bg-white border rounded-lg p-6">
            <p className="text-sm text-gray-600 mb-2">Membership Sales</p>
            <p className="text-2xl font-semibold">
              ZAR {(earnings.membership_sales_this_period || 0).toLocaleString()}
            </p>
          </div>
          <div className="bg-white border rounded-lg p-6">
            <p className="text-sm text-gray-600 mb-2">Refunds</p>
            <p className="text-2xl font-semibold text-red-600">
              ZAR {(earnings.refunds_total || 0).toLocaleString()}
            </p>
          </div>
        </div>

        {/* Monthly Comparison */}
        <div className="bg-white border rounded-lg p-6 mb-8">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-semibold">Monthly Earnings</h2>
            <div className="flex gap-2">
              {(["week", "month", "year", "all"] as const).map((range) => (
                <button
                  key={range}
                  onClick={() => setDateRange(range)}
                  className={`px-3 py-1 rounded text-sm capitalize ${
                    dateRange === range
                      ? "bg-blue-600 text-white"
                      : "bg-gray-100 text-gray-700"
                  }`}
                >
                  {range}
                </button>
              ))}
            </div>
          </div>
          <div className="grid grid-cols-2 gap-6">
            <div>
              <p className="text-sm text-gray-600 mb-1">This Month</p>
              <p className="text-2xl font-semibold">
                ZAR {earnings.this_month.toLocaleString()}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600 mb-1">Last Month</p>
              <p className="text-2xl font-semibold">
                ZAR {earnings.last_month.toLocaleString()}
              </p>
              <p className="text-sm text-green-600 mt-1">
                +{earnings.growth_percentage}% growth
              </p>
            </div>
          </div>
        </div>

        {/* Payouts */}
        {payouts.length > 0 && (
          <div className="bg-white border rounded-lg p-6 mb-8">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-semibold">Payout History</h2>
            </div>
            <div className="space-y-4">
              {payouts.map((payout) => (
                <div key={payout.id} className="flex items-center justify-between py-4 border-b last:border-0">
                  <div className="flex-1">
                    <p className="font-medium">
                      Payout Request - {payout.currency} {payout.amount.toFixed(2)}
                    </p>
                    <p className="text-sm text-gray-600">
                      Requested: {new Date(payout.requested_at).toLocaleDateString("en-US", {
                        year: "numeric",
                        month: "long",
                        day: "numeric",
                      })}
                    </p>
                    {payout.notes && (
                      <p className="text-sm text-gray-500 mt-1">{payout.notes}</p>
                    )}
                  </div>
                  <span
                    className={`px-3 py-1 rounded text-sm font-medium ${
                      payout.status === "completed"
                        ? "bg-green-100 text-green-800"
                        : payout.status === "pending" || payout.status === "processing"
                        ? "bg-yellow-100 text-yellow-800"
                        : payout.status === "failed"
                        ? "bg-red-100 text-red-800"
                        : "bg-gray-100 text-gray-800"
                    }`}
                  >
                    {payout.status}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Transactions */}
        <div className="bg-white border rounded-lg p-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-semibold">Transaction History</h2>
          </div>

          {transactions.length === 0 ? (
            <EmptyState
              title="No transactions yet"
              description="Your transaction history will appear here"
            />
          ) : (
            <div className="space-y-4">
              {transactions.map((transaction) => (
                <TransactionRow 
                  key={transaction.id} 
                  transaction={transaction}
                  onClick={() => handleTransactionClick(transaction)}
                />
              ))}
            </div>
          )}
        </div>

        {/* Transaction Details Dialog */}
        <Dialog open={showTransactionDialog} onOpenChange={setShowTransactionDialog}>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>Transaction Details</DialogTitle>
              <DialogDescription>
                Detailed information about this transaction
              </DialogDescription>
            </DialogHeader>

            {isLoadingDetails ? (
              <div className="py-8 text-center">
                <p className="text-gray-600">Loading transaction details...</p>
              </div>
            ) : selectedTransaction ? (
              <div className="space-y-6 py-4">
                {/* Transaction Overview */}
                <div className="bg-gray-50 rounded-lg p-4">
                  <h3 className="font-semibold mb-3">Transaction Overview</h3>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span className="text-gray-600">Description:</span>
                      <span className="font-medium">{selectedTransaction.description}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-600">Date:</span>
                      <span className="font-medium">
                        {new Date(selectedTransaction.date).toLocaleDateString("en-US", {
                          year: "numeric",
                          month: "long",
                          day: "numeric",
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-600">Status:</span>
                      <span className="font-medium capitalize">{selectedTransaction.status}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-600">Type:</span>
                      <span className="font-medium capitalize">{selectedTransaction.transaction_type?.replace("_", " ") || selectedTransaction.type}</span>
                    </div>
                  </div>
                </div>

                {/* Amount Breakdown */}
                <div className="bg-gray-50 rounded-lg p-4">
                  <h3 className="font-semibold mb-3">Amount Breakdown</h3>
                  <div className="space-y-2">
                    {selectedTransaction.net !== undefined && selectedTransaction.net !== selectedTransaction.amount && (
                      <>
                        <div className="flex justify-between">
                          <span className="text-gray-600">Gross Amount:</span>
                          <span className="font-medium">
                            {selectedTransaction.currency} {selectedTransaction.amount.toFixed(2)}
                          </span>
                        </div>
                        {selectedTransaction.fees && selectedTransaction.fees > 0 && (
                          <div className="flex justify-between">
                            <span className="text-gray-600">Fees:</span>
                            <span className="font-medium text-red-600">
                              -{selectedTransaction.currency} {selectedTransaction.fees.toFixed(2)}
                            </span>
                          </div>
                        )}
                        {selectedTransaction.commission && selectedTransaction.commission > 0 && (
                          <div className="flex justify-between">
                            <span className="text-gray-600">Platform Commission:</span>
                            <span className="font-medium text-red-600">
                              -{selectedTransaction.currency} {selectedTransaction.commission.toFixed(2)}
                            </span>
                          </div>
                        )}
                        <div className="flex justify-between pt-2 border-t">
                          <span className="font-semibold">Net Amount:</span>
                          <span className="font-semibold text-green-600">
                            {selectedTransaction.currency} {selectedTransaction.net.toFixed(2)}
                          </span>
                        </div>
                      </>
                    )}
                    {(!selectedTransaction.net || selectedTransaction.net === selectedTransaction.amount) && (
                      <div className="flex justify-between">
                        <span className="font-semibold">Amount:</span>
                        <span className="font-semibold text-green-600">
                          {selectedTransaction.currency} {selectedTransaction.amount.toFixed(2)}
                        </span>
                      </div>
                    )}
                  </div>
                </div>

                {/* Booking Details (if available) */}
                {transactionDetails && selectedTransaction.booking_id && (
                  <div className="bg-gray-50 rounded-lg p-4">
                    <h3 className="font-semibold mb-3">Booking Details</h3>
                    <div className="space-y-2">
                      {transactionDetails.booking_number && (
                        <div className="flex justify-between">
                          <span className="text-gray-600">Booking Number:</span>
                          <span className="font-medium">{transactionDetails.booking_number}</span>
                        </div>
                      )}
                      {transactionDetails.total_amount && (
                        <div className="flex justify-between">
                          <span className="text-gray-600">Booking Total:</span>
                          <span className="font-medium">
                            ZAR {Number(transactionDetails.total_amount).toFixed(2)}
                          </span>
                        </div>
                      )}
                      {transactionDetails.service_fee_amount && Number(transactionDetails.service_fee_amount) > 0 && (
                        <div className="flex justify-between">
                          <span className="text-gray-600">Service Fee:</span>
                          <span className="font-medium">
                            ZAR {Number(transactionDetails.service_fee_amount).toFixed(2)}
                          </span>
                        </div>
                      )}
                      {transactionDetails.tax_amount && Number(transactionDetails.tax_amount) > 0 && (
                        <div className="flex justify-between">
                          <span className="text-gray-600">Tax (VAT):</span>
                          <span className="font-medium">
                            ZAR {Number(transactionDetails.tax_amount).toFixed(2)}
                          </span>
                        </div>
                      )}
                      {transactionDetails.travel_fee && Number(transactionDetails.travel_fee) > 0 && (
                        <div className="flex justify-between">
                          <span className="text-gray-600">Travel Fee:</span>
                          <span className="font-medium">
                            ZAR {Number(transactionDetails.travel_fee).toFixed(2)}
                          </span>
                        </div>
                      )}
                      {transactionDetails.booking_source && (
                        <div className="flex justify-between">
                          <span className="text-gray-600">Booking Source:</span>
                          <span className="font-medium capitalize">
                            {transactionDetails.booking_source.replace("_", " ")}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="py-8 text-center">
                <p className="text-gray-600">No additional details available</p>
              </div>
            )}
          </DialogContent>
        </Dialog>
      </div>
    </RoleGuard>
  );
}

function TransactionRow({ transaction, onClick }: { transaction: Transaction; onClick: () => void }) {
  const getTypeColor = () => {
    switch (transaction.type) {
      case "booking":
        return "text-green-600";
      case "payout":
        return "text-blue-600";
      case "refund":
        return "text-red-600";
      default:
        return "text-gray-600";
    }
  };

  const getStatusColor = () => {
    switch (transaction.status) {
      case "completed":
        return "bg-green-100 text-green-800";
      case "pending":
        return "bg-yellow-100 text-yellow-800";
      case "failed":
        return "bg-red-100 text-red-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  return (
    <div 
      className="flex items-center justify-between py-4 border-b last:border-0 cursor-pointer hover:bg-gray-50 transition-colors rounded px-2 -mx-2"
      onClick={onClick}
    >
      <div className="flex-1">
        <p className="font-medium">{transaction.description}</p>
        <p className="text-sm text-gray-600">
          {new Date(transaction.date).toLocaleDateString("en-US", {
            year: "numeric",
            month: "long",
            day: "numeric",
          })}
        </p>
      </div>
      <div className="flex items-center gap-4">
        <p className={`font-semibold ${getTypeColor()}`}>
          {transaction.type === "payout" || transaction.type === "refund"
            ? "-"
            : "+"}
          {transaction.currency} {transaction.amount.toFixed(2)}
        </p>
        <span
          className={`px-2 py-1 rounded text-xs font-medium ${getStatusColor()}`}
        >
          {transaction.status}
        </span>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Download, AlertCircle, CheckCircle2, Clock, FileText } from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface VATReport {
  period_start: string;
  period_end: string;
  deadline_date: string;
  period_label: string;
  vat_collected: number;
  vat_collected_formatted: string;
  transaction_count: number;
  transactions: Array<{
    id: string;
    amount: number;
    booking_number: string;
    booking_date: string;
    description: string;
  }>;
  reminder_sent: {
    sent_at: string;
    days_before_deadline: number;
  } | null;
  days_until_deadline: number;
  is_overdue: boolean;
  status: 'overdue' | 'due_soon' | 'upcoming';
  remitted_to_sars: boolean;
  remitted_at: string | null;
  reminder_id: string | null; // ID of the reminder record for marking as remitted
}

interface VATReportsData {
  reports: VATReport[];
  provider: {
    vat_number: string | null;
    is_vat_registered: boolean;
  };
  year: number;
  message?: string;
}

export default function VATReportsPage() {
  const [data, setData] = useState<VATReportsData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());

  useEffect(() => {
    loadReports();
    // Check for upcoming VAT reminders on page load (on-demand, no cron needed)
    checkVATReminders();
  }, [selectedYear]);

  const checkVATReminders = async () => {
    // This is a lightweight check that runs when the page loads
    // It only checks if reminders should be shown, doesn't send them automatically
    // Providers can see reminders in the UI and choose to act on them
    try {
      // Silently check - don't show errors to user
      await fetcher.get("/api/provider/finance/vat-reports/check-reminders").catch(() => {});
    } catch {
      // Ignore errors - this is a background check
    }
  };

  const loadReports = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetcher.get<VATReportsData>(
        `/api/provider/finance/vat-reports?year=${selectedYear}`
      );
      setData(response);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load VAT reports";
      setError(errorMessage);
      console.error("Error loading VAT reports:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const markAsRemitted = async (report: VATReport) => {
    if (!report.reminder_id) {
      toast.error("Unable to mark as remitted. Please refresh the page.");
      return;
    }

    try {
      await fetcher.patch(`/api/provider/finance/vat-reports/${report.reminder_id}/mark-remitted`, {
        period_start: report.period_start,
        period_end: report.period_end,
      });
      toast.success("Marked as remitted to SARS");
      loadReports(); // Reload to update status
    } catch (err) {
      const errorMessage =
        err instanceof FetchError
          ? err.message
          : "Failed to mark as remitted";
      toast.error(errorMessage);
    }
  };

  const exportReport = (report: VATReport) => {
    // Create CSV content
    const csvRows = [
      ['VAT Remittance Report', ''],
      ['Period', report.period_label],
      ['Period Start', report.period_start],
      ['Period End', report.period_end],
      ['Deadline', report.deadline_date],
      ['VAT Collected', report.vat_collected_formatted],
      ['Transaction Count', report.transaction_count.toString()],
      [''],
      ['Booking Number', 'Date', 'VAT Amount', 'Description'],
      ...report.transactions.map(t => [
        t.booking_number,
        new Date(t.booking_date).toLocaleDateString('en-ZA'),
        `R${t.amount.toFixed(2)}`,
        t.description || ''
      ])
    ];

    const csvContent = csvRows.map(row => row.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `vat-report-${report.period_start}-${report.period_end}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    
    toast.success("VAT report exported successfully");
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading VAT reports..." />
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="container mx-auto px-4 py-8">
        <EmptyState
          title="Failed to load VAT reports"
          description={error || "An error occurred while loading VAT reports"}
          action={{
            label: "Try Again",
            onClick: loadReports,
          }}
        />
      </div>
    );
  }

  if (!data.provider.is_vat_registered) {
    return (
      <div className="container mx-auto px-4 py-8 max-w-4xl">
        <div className="bg-white border rounded-lg p-8 text-center">
          <AlertCircle className="w-16 h-16 text-gray-400 mx-auto mb-4" />
          <h2 className="text-2xl font-semibold mb-2">VAT Reports Not Available</h2>
          <p className="text-gray-600 mb-4">
            You are not VAT registered. VAT reports are only available for VAT-registered providers.
          </p>
          <p className="text-sm text-gray-500 mb-6">
            If you need to register for VAT, please visit{" "}
            <a
              href="https://www.sars.gov.za/individuals/tax-types/value-added-tax-vat/"
              target="_blank"
              rel="noopener noreferrer"
              className="text-[#FF0077] hover:underline"
            >
              SARS website
            </a>
            . VAT registration is mandatory for businesses with annual turnover of R1 million or more.
          </p>
          <Button
            onClick={() => window.location.href = "/provider/settings/sales/taxes"}
            className="bg-[#FF0077] hover:bg-[#D60565]"
          >
            Update VAT Registration Status
          </Button>
        </div>
      </div>
    );
  }

  const currentYear = new Date().getFullYear();
  const years = Array.from({ length: 3 }, (_, i) => currentYear - i);

  return (
    <RoleGuard allowedRoles={["provider_owner", "provider_staff"]}>
      <div className="container mx-auto px-4 py-8 max-w-6xl">
        <div className="mb-6 flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-semibold mb-2">VAT Reports</h1>
            <p className="text-gray-600">
              Bi-monthly VAT reports for SARS submission
              {data.provider.vat_number && (
                <span className="ml-2 text-sm">ΓÇó VAT Number: {data.provider.vat_number}</span>
              )}
            </p>
          </div>
          <div className="flex items-center gap-3">
            <Select value={selectedYear.toString()} onValueChange={(v) => setSelectedYear(parseInt(v))}>
              <SelectTrigger className="w-32">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {years.map(year => (
                  <SelectItem key={year} value={year.toString()}>
                    {year}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>

        {data.reports.length === 0 ? (
          <div className="bg-white border rounded-lg p-8 text-center">
            <FileText className="w-16 h-16 text-gray-400 mx-auto mb-4" />
            <h2 className="text-xl font-semibold mb-2">No VAT Reports Available</h2>
            <p className="text-gray-600">
              No VAT transactions found for {selectedYear}. VAT reports will appear here once you have bookings with VAT collected.
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {data.reports.map((report, index) => (
              <div
                key={index}
                className={`bg-white border rounded-lg p-6 ${
                  report.is_overdue
                    ? "border-red-300 bg-red-50"
                    : report.status === "due_soon"
                    ? "border-yellow-300 bg-yellow-50"
                    : "border-gray-200"
                }`}
              >
                <div className="flex items-start justify-between mb-4">
                  <div>
                    <div className="flex items-center gap-3 mb-2">
                      <h3 className="text-xl font-semibold">{report.period_label}</h3>
                      {report.is_overdue ? (
                        <span className="px-3 py-1 bg-red-100 text-red-800 rounded-full text-sm font-medium flex items-center gap-1">
                          <AlertCircle className="w-4 h-4" />
                          Overdue
                        </span>
                      ) : report.status === "due_soon" ? (
                        <span className="px-3 py-1 bg-yellow-100 text-yellow-800 rounded-full text-sm font-medium flex items-center gap-1">
                          <Clock className="w-4 h-4" />
                          Due Soon
                        </span>
                      ) : (
                        <span className="px-3 py-1 bg-green-100 text-green-800 rounded-full text-sm font-medium flex items-center gap-1">
                          <CheckCircle2 className="w-4 h-4" />
                          Upcoming
                        </span>
                      )}
                    </div>
                    <div className="text-sm text-gray-600 space-y-1">
                      <p>
                        <strong>Period:</strong> {new Date(report.period_start).toLocaleDateString('en-ZA')} - {new Date(report.period_end).toLocaleDateString('en-ZA')}
                      </p>
                      <p>
                        <strong>Deadline:</strong> {new Date(report.deadline_date).toLocaleDateString('en-ZA', { 
                          day: 'numeric', 
                          month: 'long', 
                          year: 'numeric' 
                        })}
                        {report.days_until_deadline > 0 && (
                          <span className="ml-2">
                            ({report.days_until_deadline} {report.days_until_deadline === 1 ? 'day' : 'days'} remaining)
                          </span>
                        )}
                      </p>
                      {report.reminder_sent && (
                        <p className="text-xs text-gray-500">
                          Reminder sent {new Date(report.reminder_sent.sent_at).toLocaleDateString('en-ZA')} 
                          ({report.reminder_sent.days_before_deadline} days before deadline)
                        </p>
                      )}
                    </div>
                  </div>
                  <div className="text-right">
                    <div className="text-2xl font-bold text-[#FF0077] mb-1">
                      {report.vat_collected_formatted}
                    </div>
                    <p className="text-sm text-gray-600">
                      {report.transaction_count} {report.transaction_count === 1 ? 'transaction' : 'transactions'}
                    </p>
                  </div>
                </div>

                {report.transactions.length > 0 && (
                  <div className="mt-4 border-t pt-4">
                    <div className="flex items-center justify-between mb-3">
                      <h4 className="font-semibold">Transaction Details</h4>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => exportReport(report)}
                        className="flex items-center gap-2"
                      >
                        <Download className="w-4 h-4" />
                        Export CSV
                      </Button>
                    </div>
                    <div className="overflow-x-auto">
                      <table className="w-full text-sm">
                        <thead>
                          <tr className="border-b">
                            <th className="text-left py-2 px-3">Booking #</th>
                            <th className="text-left py-2 px-3">Date</th>
                            <th className="text-right py-2 px-3">VAT Amount</th>
                            <th className="text-left py-2 px-3">Description</th>
                          </tr>
                        </thead>
                        <tbody>
                          {report.transactions.map((transaction) => (
                            <tr key={transaction.id} className="border-b">
                              <td className="py-2 px-3">{transaction.booking_number}</td>
                              <td className="py-2 px-3">
                                {new Date(transaction.booking_date).toLocaleDateString('en-ZA')}
                              </td>
                              <td className="text-right py-2 px-3 font-medium">
                                R{transaction.amount.toFixed(2)}
                              </td>
                              <td className="py-2 px-3 text-gray-600">
                                {transaction.description || 'N/A'}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}

                <div className="mt-4 pt-4 border-t">
                  {report.remitted_to_sars ? (
                    <div className="bg-green-50 border border-green-200 rounded-lg p-3">
                      <div className="flex items-center justify-between">
                        <div>
                          <p className="text-sm text-green-800 font-medium mb-1">
                            Γ£ô Remitted to SARS
                          </p>
                          <p className="text-xs text-green-700">
                            Confirmed on {report.remitted_at ? new Date(report.remitted_at).toLocaleDateString('en-ZA', { 
                              day: 'numeric', 
                              month: 'long', 
                              year: 'numeric',
                              hour: '2-digit',
                              minute: '2-digit'
                            }) : 'N/A'}
                          </p>
                        </div>
                        <CheckCircle2 className="w-6 h-6 text-green-600" />
                      </div>
                    </div>
                  ) : (
                    <div className="bg-blue-50 border border-blue-200 rounded-lg p-3">
                      <div className="mb-3">
                        <p className="text-sm text-blue-800">
                          <strong>Next Steps:</strong> Remit {report.vat_collected_formatted} to SARS by{" "}
                          {new Date(report.deadline_date).toLocaleDateString('en-ZA', { 
                            day: 'numeric', 
                            month: 'long', 
                            year: 'numeric' 
                          })}.{" "}
                          <a
                            href="https://www.sars.gov.za/individuals/tax-types/value-added-tax-vat/"
                            target="_blank"
                            rel="noopener noreferrer"
                            className="underline font-medium"
                          >
                            Submit via SARS eFiling ΓåÆ
                          </a>
                        </p>
                      </div>
                      <Button
                        onClick={() => markAsRemitted(report)}
                        className="w-full bg-green-600 hover:bg-green-700 text-white"
                      >
                        <CheckCircle2 className="w-4 h-4 mr-2" />
                        Mark as Remitted to SARS
                      </Button>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { PageHeader } from "@/components/provider/PageHeader";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { 
  Trophy, 
  Star, 
  Award, 
  TrendingUp, 
  RefreshCw,
  CheckCircle2,
  Clock,
  Gift,
  Zap
} from "lucide-react";
import Image from "next/image";
import { fetcher } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { handleError } from "@/lib/provider-portal/error-handler";

interface GamificationData {
  points: {
    total: number;
    lifetime: number;
    current_tier: number;
    last_calculated: string | null;
  };
  current_badge: {
    id: string;
    name: string;
    slug: string;
    description: string | null;
    icon_url: string | null;
    tier: number;
    color: string;
    requirements: {
      points?: number;
      min_rating?: number;
      min_reviews?: number;
      min_bookings?: number;
    };
    benefits: {
      free_subscription?: boolean;
      featured?: boolean;
    };
    earned_at: string | null;
    expires_at: string | null;
  } | null;
  milestones: Array<{
    id: string;
    milestone_type: string;
    achieved_at: string;
    metadata: Record<string, any>;
  }>;
  transactions: Array<{
    id: string;
    points: number;
    source: string;
    source_id: string | null;
    description: string | null;
    created_at: string;
  }>;
  progress_to_next_badge: {
    badge: {
      id: string;
      name: string;
      tier: number;
      color: string;
      requirements: {
        points?: number;
      };
    };
    current_points: number;
    required_points: number;
    points_needed: number;
    progress_percentage: number;
  } | null;
  provider_stats: {
    total_bookings: number;
    review_count: number;
    rating_average: number;
    total_earnings: number;
  };
}

export default function ProviderGamificationPage() {
  const [data, setData] = useState<GamificationData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isRecalculating, setIsRecalculating] = useState(false);

  const loadGamificationData = async (initializeIfNeeded = false) => {
    try {
      setIsLoading(true);
      setError(null);
      
      const response = await fetcher.get<{ data: GamificationData }>(
        "/api/provider/gamification"
      );
      
      // If no points data exists and we should initialize, try to initialize
      if (initializeIfNeeded && (!response.data.points || response.data.points.total === 0)) {
        try {
          // Try to recalculate which will initialize if needed
          await fetcher.post("/api/provider/gamification", {});
          // Reload data after initialization
          const updatedResponse = await fetcher.get<{ data: GamificationData }>(
            "/api/provider/gamification"
          );
          setData(updatedResponse.data);
        } catch (initErr) {
          // If initialization fails, still show the data we have
          console.warn("Failed to initialize points:", initErr);
          setData(response.data);
        }
      } else {
        setData(response.data);
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : "Failed to load gamification data";
      setError(errorMessage);
      handleError(err, {
        action: "loadGamification",
        resource: "gamification data",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleRecalculate = async () => {
    try {
      setIsRecalculating(true);
      
      await fetcher.post("/api/provider/gamification", {});
      
      // Reload data after recalculation
      await loadGamificationData();
    } catch (err) {
      handleError(err, {
        action: "recalculateGamification",
        resource: "gamification data",
      });
    } finally {
      setIsRecalculating(false);
    }
  };

  useEffect(() => {
    // Try to initialize if no data exists
    loadGamificationData(true);
  }, []);

  if (isLoading) {
    return (
      <SettingsDetailLayout
        title="Rewards"
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Rewards" }
        ]}
      >
        <LoadingTimeout loadingMessage="Loading rewards data..." timeoutMs={10000} />
      </SettingsDetailLayout>
    );
  }

  if (error || !data) {
    return (
      <SettingsDetailLayout
        title="Rewards"
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Rewards" }
        ]}
      >
        <EmptyState
          title="Failed to load rewards data"
          description={error || "Unable to load your points and badges"}
          action={{
            label: "Retry",
            onClick: loadGamificationData,
          }}
        />
      </SettingsDetailLayout>
    );
  }

  const formatDate = (dateString: string | null) => {
    if (!dateString) return "N/A";
    return new Date(dateString).toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  const formatSource = (source: string) => {
    const sourceMap: Record<string, string> = {
      booking_completed: "Completed Booking",
      review_received: "Review Received",
      milestone: "Milestone Achievement",
      admin_adjustment: "Admin Adjustment",
    };
    return sourceMap[source] || source.replace(/_/g, " ").replace(/\b\w/g, (l) => l.toUpperCase());
  };

  return (
    <SettingsDetailLayout
      title="Rewards"
      breadcrumbs={[
        { label: "Home", href: "/" },
        { label: "Provider", href: "/provider" },
        { label: "Rewards" }
      ]}
    >
      <PageHeader
        title="Rewards & Achievements"
        subtitle="Track your points, badges, and milestones"
      />

      {/* Current Badge & Points Overview */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        {/* Current Badge */}
        <Card className="md:col-span-2">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Trophy className="w-5 h-5" />
              Current Badge
            </CardTitle>
          </CardHeader>
          <CardContent>
            {data.current_badge ? (
              <div className="space-y-4">
                <div className="flex items-center gap-4">
                  <div
                    className="w-20 h-20 rounded-full flex items-center justify-center text-white text-2xl font-bold shadow-lg"
                    style={{ backgroundColor: data.current_badge.color || "#6366f1" }}
                  >
                    {data.current_badge.icon_url ? (
                      <Image
                        src={data.current_badge.icon_url}
                        alt={data.current_badge.name}
                        width={80}
                        height={80}
                        className="w-full h-full rounded-full object-cover"
                        unoptimized
                      />
                    ) : (
                      <Trophy className="w-10 h-10" />
                    )}
                  </div>
                  <div className="flex-1">
                    <h3 className="text-xl font-bold mb-1">{data.current_badge.name}</h3>
                    {data.current_badge.description && (
                      <p className="text-sm text-gray-600 mb-2">{data.current_badge.description}</p>
                    )}
                    <div className="flex flex-wrap gap-2">
                      {data.current_badge?.benefits?.free_subscription && (
                        <Badge variant="outline" className="bg-green-50 text-green-700 border-green-200">
                          <Gift className="w-3 h-3 mr-1" />
                          Free Subscription
                        </Badge>
                      )}
                      {data.current_badge?.benefits?.featured && (
                        <Badge variant="outline" className="bg-blue-50 text-blue-700 border-blue-200">
                          <Star className="w-3 h-3 mr-1" />
                          Featured
                        </Badge>
                      )}
                    </div>
                    {data.current_badge.earned_at && (
                      <p className="text-xs text-gray-500 mt-2">
                        Earned on {formatDate(data.current_badge.earned_at)}
                      </p>
                    )}
                  </div>
                </div>
              </div>
            ) : (
              <div className="text-center py-8">
                <Award className="w-12 h-12 text-gray-400 mx-auto mb-2" />
                <p className="text-gray-600">No badge yet. Keep earning points to unlock your first badge!</p>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Points Summary */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Zap className="w-5 h-5" />
              Points
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <div>
                <p className="text-sm text-gray-600 mb-1">Total Points</p>
                <p className="text-3xl font-bold">{data.points.total.toLocaleString()}</p>
              </div>
              <div>
                <p className="text-sm text-gray-600 mb-1">Lifetime Points</p>
                <p className="text-2xl font-semibold text-gray-700">{data.points.lifetime.toLocaleString()}</p>
              </div>
              <div>
                <p className="text-sm text-gray-600 mb-1">Current Tier Points</p>
                <p className="text-xl font-semibold text-purple-600">{data.points.current_tier.toLocaleString()}</p>
              </div>
              <Button
                onClick={handleRecalculate}
                disabled={isRecalculating}
                variant="outline"
                size="sm"
                className="w-full"
              >
                <RefreshCw className={`w-4 h-4 mr-2 ${isRecalculating ? "animate-spin" : ""}`} />
                {isRecalculating ? "Recalculating..." : "Recalculate"}
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Progress to Next Badge */}
      {data.progress_to_next_badge && (
        <Card className="mb-6">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <TrendingUp className="w-5 h-5" />
              Progress to Next Badge
            </CardTitle>
            <CardDescription>
              {data.progress_to_next_badge.badge.name}
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {/* Points Display with Star */}
              <div className="flex items-baseline gap-2 mb-4">
                <span className="text-2xl sm:text-3xl font-bold text-gray-900 flex items-center gap-2">
                  {data.progress_to_next_badge.current_points.toLocaleString()}
                  <Star className="w-5 h-5 sm:w-6 sm:h-6 text-[#FF0077] fill-[#FF0077]" />
                </span>
                <span className="text-base sm:text-lg text-gray-600">
                  / {data.progress_to_next_badge.required_points.toLocaleString()} points
                </span>
                <span className="ml-auto text-xs sm:text-sm text-gray-600 font-semibold">
                  {data.progress_to_next_badge.progress_percentage}%
                </span>
              </div>
              
              {/* Progress Bar */}
              <div className="relative mt-4">
                <div className="relative h-2 bg-gray-200 rounded-full overflow-hidden">
                  <div 
                    className="absolute top-0 left-0 h-full bg-gradient-to-r from-[#FF0077] to-[#D60565] rounded-full transition-all duration-500 ease-out"
                    style={{ width: `${data.progress_to_next_badge.progress_percentage}%` }}
                  />
                </div>
              </div>
              
              {/* Points Needed & Encouragement */}
              {data.progress_to_next_badge.points_needed > 0 ? (
                <div className="space-y-2">
                  <p className="text-sm sm:text-base text-gray-700">
                    <span className="font-semibold text-[#FF0077]">{data.progress_to_next_badge.points_needed.toLocaleString()}</span> more points needed
                  </p>
                  <p className="text-xs sm:text-sm text-gray-600 italic">
                    ≡ƒÆí Keep earning points by completing bookings and receiving great reviews!
                  </p>
                </div>
              ) : (
                <p className="text-sm sm:text-base text-[#FF0077] font-semibold">
                  ≡ƒÄë You've reached the requirements!
                </p>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Tabs for Milestones and Transactions */}
      <Tabs defaultValue="milestones" className="mb-6">
        <TabsList className="grid w-full grid-cols-2">
          <TabsTrigger value="milestones">
            <Award className="w-4 h-4 mr-2" />
            Milestones ({data.milestones.length})
          </TabsTrigger>
          <TabsTrigger value="transactions">
            <Clock className="w-4 h-4 mr-2" />
            Point History ({data.transactions.length})
          </TabsTrigger>
        </TabsList>

        <TabsContent value="milestones">
          <Card>
            <CardHeader>
              <CardTitle>Achievements</CardTitle>
              <CardDescription>Milestones you've unlocked</CardDescription>
            </CardHeader>
            <CardContent>
              {data.milestones.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {data.milestones.map((milestone) => (
                    <div
                      key={milestone.id}
                      className="border rounded-lg p-4 hover:shadow-md transition-shadow"
                    >
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full bg-gradient-to-br from-[#FF0077] to-[#4fd1c5] flex items-center justify-center">
                          <CheckCircle2 className="w-5 h-5 text-white" />
                        </div>
                        <div className="flex-1">
                          <h4 className="font-semibold">
                            {milestone.milestone_type.replace(/_/g, " ").replace(/\b\w/g, (l) => l.toUpperCase())}
                          </h4>
                          <p className="text-xs text-gray-500">
                            {formatDate(milestone.achieved_at)}
                          </p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8">
                  <Award className="w-12 h-12 text-gray-400 mx-auto mb-2" />
                  <p className="text-gray-600">No milestones unlocked yet. Keep working to earn achievements!</p>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="transactions">
          <Card>
            <CardHeader>
              <CardTitle>Point Transactions</CardTitle>
              <CardDescription>History of all point awards and deductions</CardDescription>
            </CardHeader>
            <CardContent>
              {data.transactions.length > 0 ? (
                <div className="space-y-3">
                  {data.transactions.map((transaction) => (
                    <div
                      key={transaction.id}
                      className="flex items-center justify-between p-3 border rounded-lg hover:bg-gray-50 transition-colors"
                    >
                      <div className="flex items-center gap-3">
                        <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                          transaction.points > 0 
                            ? "bg-green-100 text-green-600" 
                            : "bg-red-100 text-red-600"
                        }`}>
                          {transaction.points > 0 ? (
                            <TrendingUp className="w-5 h-5" />
                          ) : (
                            <TrendingUp className="w-5 h-5 rotate-180" />
                          )}
                        </div>
                        <div>
                          <p className="font-medium">{formatSource(transaction.source)}</p>
                          {transaction.description && (
                            <p className="text-sm text-gray-600">{transaction.description}</p>
                          )}
                          <p className="text-xs text-gray-500">{formatDate(transaction.created_at)}</p>
                        </div>
                      </div>
                      <div className={`text-lg font-bold ${
                        transaction.points > 0 ? "text-green-600" : "text-red-600"
                      }`}>
                        {transaction.points > 0 ? "+" : ""}{transaction.points}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8">
                  <Clock className="w-12 h-12 text-gray-400 mx-auto mb-2" />
                  <p className="text-gray-600">No transactions yet. Complete bookings and receive reviews to earn points!</p>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Provider Stats */}
      <Card>
        <CardHeader>
          <CardTitle>Your Stats</CardTitle>
          <CardDescription>Statistics that contribute to your points</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="text-center p-4 border rounded-lg">
              <p className="text-2xl font-bold">{data.provider_stats.total_bookings}</p>
              <p className="text-sm text-gray-600">Total Bookings</p>
            </div>
            <div className="text-center p-4 border rounded-lg">
              <p className="text-2xl font-bold">{data.provider_stats.review_count}</p>
              <p className="text-sm text-gray-600">Reviews</p>
            </div>
            <div className="text-center p-4 border rounded-lg">
              <p className="text-2xl font-bold">
                {data.provider_stats.rating_average > 0 
                  ? data.provider_stats.rating_average.toFixed(1) 
                  : "N/A"}
              </p>
              <p className="text-sm text-gray-600">Average Rating</p>
            </div>
          </div>
        </CardContent>
      </Card>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Check, ChevronRight, ArrowRight, Sparkles, RefreshCw } from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { Progress } from "@/components/ui/progress";
import LoadingTimeout from "@/components/ui/loading-timeout";

interface SetupStep {
  id: string;
  title: string;
  description: string;
  completed: boolean;
  required: boolean;
  link: string;
}

interface SetupStatus {
  isComplete: boolean;
  completionPercentage: number;
  steps: SetupStep[];
}

export default function GetStartedPage() {
  const router = useRouter();
  const [setupStatus, setSetupStatus] = useState<SetupStatus | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const lastFetchRef = React.useRef<number>(0);
  const MIN_REFRESH_INTERVAL_MS = 2000;

  useEffect(() => {
    loadSetupStatus();
  }, []);

  // Refresh when user returns to this page (visibility/focus) - always refetch to show latest progress
  useEffect(() => {
    const handleRefresh = () => {
      if (document.visibilityState !== "visible") return;
      const now = Date.now();
      if (now - lastFetchRef.current < MIN_REFRESH_INTERVAL_MS) return;
      lastFetchRef.current = now;
      sessionStorage.removeItem("shouldRefreshSetupStatus");
      loadSetupStatus(true);
    };

    const handleVisibilityChange = () => {
      if (document.visibilityState === "visible" && !isLoading) handleRefresh();
    };

    const handleFocus = () => {
      if (!isLoading) handleRefresh();
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);
    window.addEventListener("focus", handleFocus);
    return () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      window.removeEventListener("focus", handleFocus);
    };
  }, [isLoading]);

  const loadSetupStatus = async (isRefresh = false) => {
    try {
      if (isRefresh) {
        setIsRefreshing(true);
      } else {
        setIsLoading(true);
      }
      setError(null);
      const response = await fetcher.get<{ data: SetupStatus }>(
        `/api/provider/setup-status?_=${Date.now()}`
      );
      setSetupStatus(response.data ?? { isComplete: false, completionPercentage: 0, steps: [] });
      lastFetchRef.current = Date.now();
      if (isRefresh) {
        toast.success("Status updated");
      }
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load setup status";
      setError(errorMessage);
      console.error("Error loading setup status:", err);
      if (isRefresh) {
        toast.error("Failed to refresh status");
      }
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  };

  const handleStepClick = (step: SetupStep) => {
    // Navigate to the step's link with return parameter
    const returnUrl = encodeURIComponent("/provider/get-started");
    const separator = step.link.includes("?") ? "&" : "?";
    // Store return URL in sessionStorage for easy access
    if (typeof window !== 'undefined') {
      sessionStorage.setItem('getStartedReturnUrl', '/provider/get-started');
      // Also store a flag to trigger refresh when returning
      sessionStorage.setItem('shouldRefreshSetupStatus', 'true');
    }
    router.push(`${step.link}${separator}returnTo=${returnUrl}`);
  };

  const handleCompleteLater = () => {
    router.push("/provider/dashboard");
  };

  if (isLoading) {
    return (
      <SettingsDetailLayout
        title="Get Started"
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Get Started" },
        ]}
      >
        <LoadingTimeout loadingMessage="Loading setup status..." />
      </SettingsDetailLayout>
    );
  }

  if (error || !setupStatus) {
    return (
      <SettingsDetailLayout
        title="Get Started"
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Get Started" },
        ]}
      >
        <div className="bg-white rounded-lg border p-6">
          <p className="text-red-600">{error || "Failed to load setup status"}</p>
          <Button onClick={() => loadSetupStatus()} className="mt-4">
            Retry
          </Button>
        </div>
      </SettingsDetailLayout>
    );
  }

  // No steps = no provider record yet (complete onboarding first)
  if (!setupStatus.steps || setupStatus.steps.length === 0) {
    return (
      <SettingsDetailLayout
        title="Get Started"
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Get Started" },
        ]}
      >
        <div className="bg-white rounded-lg border p-6">
          <p className="text-gray-700 mb-4">
            Complete onboarding first to set up your provider account and see your setup steps.
          </p>
          <Button onClick={() => router.push("/provider/onboarding")} className="bg-[#FF0077] hover:bg-[#D60565] text-white">
            Go to Onboarding
          </Button>
        </div>
      </SettingsDetailLayout>
    );
  }

  // If setup is complete, show success message and redirect option
  if (setupStatus.isComplete) {
    return (
      <SettingsDetailLayout
        title="Get Started"
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Get Started" },
        ]}
      >
        <div className="max-w-4xl mx-auto">
          <div className="bg-gradient-to-r from-green-50 to-emerald-50 rounded-xl p-8 mb-6 text-center border-2 border-green-200">
            <div className="flex flex-col items-center">
              <div className="w-20 h-20 bg-green-500 rounded-full flex items-center justify-center mb-4 animate-pulse">
                <Check className="w-12 h-12 text-white" />
              </div>
              <h1 className="text-3xl font-bold text-green-800 mb-2">≡ƒÄë Setup Complete!</h1>
              <p className="text-lg text-green-700 mb-6">
                You're all set to start accepting bookings and making money!
              </p>
              <div className="flex gap-4">
                <Button
                  onClick={() => router.push("/provider/dashboard")}
                  className="bg-[#FF0077] hover:bg-[#D60565] text-white"
                >
                  Go to Dashboard
                  <ArrowRight className="w-4 h-4 ml-2" />
                </Button>
                <Button
                  variant="outline"
                  onClick={() => router.push("/provider/catalogue/services")}
                  className="border-green-300 text-green-700 hover:bg-green-50"
                >
                  Manage Services
                </Button>
              </div>
            </div>
          </div>
        </div>
      </SettingsDetailLayout>
    );
  }

  // Sort steps: required first, then by completion status (incomplete first)
  const sortedSteps = [...setupStatus.steps].sort((a, b) => {
    // Required steps come first
    if (a.required && !b.required) return -1;
    if (!a.required && b.required) return 1;
    // Within same required status, incomplete come first
    if (!a.completed && b.completed) return -1;
    if (a.completed && !b.completed) return 1;
    return 0;
  });

  const requiredSteps = sortedSteps.filter((step) => step.required);
  const completedRequiredSteps = requiredSteps.filter((step) => step.completed).length;
  const allRequiredComplete = completedRequiredSteps === requiredSteps.length;
  const _totalSteps = sortedSteps.length;

  return (
    <SettingsDetailLayout
      title="Get Started"
      breadcrumbs={[
        { label: "Home", href: "/" },
        { label: "Provider", href: "/provider" },
        { label: "Get Started" },
      ]}
    >
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="bg-gradient-to-r from-[#FF0077] to-[#D60565] rounded-xl p-8 mb-6 text-white">
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-3">
                  <Sparkles className="w-8 h-8" />
                  <h1 className="text-3xl font-bold">Get Started</h1>
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => loadSetupStatus(true)}
                  disabled={isRefreshing}
                  className="text-white hover:text-white/90 hover:bg-white/10 disabled:opacity-50"
                  title="Refresh status"
                >
                  <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
                </Button>
              </div>
              <p className="text-lg text-white/90 mb-4">
                {completedRequiredSteps === requiredSteps.length
                  ? "≡ƒÄë All required steps completed! You're ready to start accepting bookings."
                  : completedRequiredSteps > 0
                  ? `You have ${requiredSteps.length - completedRequiredSteps} required step${requiredSteps.length - completedRequiredSteps === 1 ? '' : 's'} remaining. Complete them to start making money!`
                  : `Complete these steps to start accepting bookings and making money!`}
              </p>
              <div className="flex items-center gap-4">
                <div className="flex-1">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-sm font-medium">
                      {setupStatus.completionPercentage}% Complete
                    </span>
                    <span className="text-sm">
                      {completedRequiredSteps} of {requiredSteps.length} required steps
                    </span>
                  </div>
                  <Progress
                    value={setupStatus.completionPercentage}
                    className="h-3 bg-white/20"
                  />
                </div>
              </div>
            </div>
            {allRequiredComplete && (
              <div className="ml-6 bg-white/20 rounded-lg p-4 animate-pulse">
                <Check className="w-12 h-12" />
              </div>
            )}
          </div>
        </div>

        {/* Steps List */}
        <div className="space-y-4 mb-6">
          {sortedSteps.map((step, index) => {
            // Determine step number (only count required steps for numbering, but show all)
            const stepNumber = index + 1;
            return (
            <div
              key={step.id}
              className={`bg-white rounded-lg border-2 p-6 transition-all cursor-pointer hover:shadow-lg hover:scale-[1.01] ${
                step.completed
                  ? "border-green-200 bg-green-50/30 hover:border-green-300"
                  : step.required
                  ? "border-[#FF0077]/30 hover:border-[#FF0077]/50"
                  : "border-gray-200 hover:border-gray-300"
              }`}
              onClick={() => handleStepClick(step)}
            >
              <div className="flex items-start justify-between">
                <div className="flex items-start gap-4 flex-1">
                  <div
                    className={`flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center font-bold text-lg ${
                      step.completed
                        ? "bg-green-500 text-white"
                        : "bg-gray-200 text-gray-600"
                    }`}
                  >
                    {step.completed ? (
                      <Check className="w-6 h-6" />
                    ) : (
                      <span>{stepNumber}</span>
                    )}
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <h3 className="text-lg font-semibold text-gray-900">
                        {step.title}
                      </h3>
                      {step.required && (
                        <span className="text-xs bg-[#FF0077] text-white px-2 py-0.5 rounded-full">
                          Required
                        </span>
                      )}
                    </div>
                    <p className="text-gray-600 mb-3">{step.description}</p>
                    <Button
                      onClick={() => handleStepClick(step)}
                      variant={step.completed ? "outline" : "default"}
                      className={`transition-all ${
                        step.completed
                          ? "border-green-500 text-green-700 hover:bg-green-50 hover:border-green-600"
                          : "bg-[#FF0077] hover:bg-[#D60565] text-white shadow-sm hover:shadow-md"
                      }`}
                    >
                      {step.completed ? "Update" : "Set Up"}
                      <ChevronRight className="w-4 h-4 ml-2" />
                    </Button>
                  </div>
                </div>
              </div>
            </div>
            );
          })}
        </div>

        {/* Footer Actions */}
        <div className={`flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 rounded-lg border p-6 transition-all ${
          allRequiredComplete 
            ? "bg-gradient-to-r from-green-50 to-emerald-50 border-green-200" 
            : "bg-white border-gray-200"
        }`}>
          <div className="flex-1">
            <p className={`text-sm ${allRequiredComplete ? "text-green-800 font-medium" : "text-gray-600"}`}>
              {allRequiredComplete
                ? "≡ƒÄë Great! You're all set to start accepting bookings and making money!"
                : completedRequiredSteps > 0
                ? `You have ${requiredSteps.length - completedRequiredSteps} required step${requiredSteps.length - completedRequiredSteps === 1 ? '' : 's'} remaining. Complete them to start accepting bookings and making money!`
                : `Complete the required steps above to start accepting bookings.`}
            </p>
          </div>
          <div className="flex gap-3 w-full sm:w-auto">
            <Button
              variant="outline"
              onClick={handleCompleteLater}
              className="border-gray-300 flex-1 sm:flex-none"
            >
              Complete Later
            </Button>
            {allRequiredComplete && (
              <Button
                onClick={() => router.push("/provider/dashboard")}
                className="bg-[#FF0077] hover:bg-[#D60565] text-white flex-1 sm:flex-none"
              >
                Go to Dashboard
                <ArrowRight className="w-4 h-4 ml-2" />
              </Button>
            )}
          </div>
        </div>

        {/* Tips Section */}
        {!allRequiredComplete && (
          <div className="mt-6 bg-blue-50 border border-blue-200 rounded-lg p-6">
            <h3 className="font-semibold text-blue-900 mb-2">≡ƒÆí Quick Tips</h3>
            <ul className="space-y-2 text-sm text-blue-800">
              <li>ΓÇó Complete required steps first to start accepting bookings</li>
              <li>ΓÇó You can always come back to update optional settings later</li>
              <li>ΓÇó Adding photos helps customers discover your services</li>
              <li>ΓÇó Set up payment processing to receive payments automatically</li>
            </ul>
          </div>
        )}
      </div>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Plus, Edit, Trash2, MapPin, Phone, Clock, Sparkles } from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";
import AddressAutocomplete from "@/components/mapbox/AddressAutocomplete";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";

interface Location {
  id: string;
  name: string;
  address_line1: string;
  address_line2?: string;
  city: string;
  state: string;
  postal_code: string;
  country: string;
  phone?: string;
  email?: string;
  operating_hours?: {
    [key: string]: { open: string; close: string; closed: boolean };
  };
  is_active: boolean;
  latitude?: number;
  longitude?: number;
}

export default function ProviderLocations() {
  const [locations, setLocations] = useState<Location[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingLocation, setEditingLocation] = useState<Location | null>(null);
  const [showZoneSuggestions, setShowZoneSuggestions] = useState(false);
  const [suggestedZones, setSuggestedZones] = useState<any[]>([]);

  useEffect(() => {
    loadLocations();

    // Check for zone suggestions from location save
    const checkZoneSuggestions = () => {
      if ((window as any).__showZoneSuggestions && (window as any).__zoneSuggestions) {
        setSuggestedZones((window as any).__zoneSuggestions);
        setShowZoneSuggestions(true);
        (window as any).__showZoneSuggestions = false;
        (window as any).__zoneSuggestions = null;
      }
    };

    // Check immediately and also set up interval for delayed checks
    checkZoneSuggestions();
    const interval = setInterval(checkZoneSuggestions, 500);

    return () => clearInterval(interval);
  }, []);

  const loadLocations = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetcher.get<{ data: Location[] }>(
        "/api/provider/locations"
      );
      setLocations(response.data);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load locations";
      setError(errorMessage);
      console.error("Error loading locations:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this location?")) return;

    try {
      await fetcher.delete(`/api/provider/locations/${id}`);
      toast.success("Location deleted successfully");
      loadLocations();
    } catch {
      toast.error("Failed to delete location");
    }
  };

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading locations..." />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["provider_owner"]}>
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-6">
          <div>
            <h1 className="text-3xl font-semibold mb-2">Locations</h1>
            <p className="text-gray-600">Manage your business locations</p>
          </div>
          <Button onClick={() => setShowAddModal(true)}>
            <Plus className="w-4 h-4 mr-2" />
            Add Location
          </Button>
        </div>

        {/* Locations List */}
        {error ? (
          <EmptyState
            title="Failed to load locations"
            description={error}
            action={{
              label: "Retry",
              onClick: loadLocations,
            }}
          />
        ) : locations.length === 0 ? (
          <EmptyState
            title="No locations yet"
            description="Add your first business location to get started"
            action={{
              label: "Add Location",
              onClick: () => setShowAddModal(true),
            }}
          />
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {locations.map((location) => (
              <LocationCard
                key={location.id}
                location={location}
                onEdit={() => setEditingLocation(location)}
                onDelete={() => handleDelete(location.id)}
              />
            ))}
          </div>
        )}

        {/* Add/Edit Modal */}
        {(showAddModal || editingLocation) && (
          <LocationModal
            location={editingLocation}
            onClose={() => {
              setShowAddModal(false);
              setEditingLocation(null);
            }}
            onSave={() => {
              setShowAddModal(false);
              setEditingLocation(null);
              loadLocations();
            }}
          />
        )}

        {/* Zone Suggestions Modal */}
        {showZoneSuggestions && suggestedZones.length > 0 && (
          <ZoneSuggestionsModal
            zones={suggestedZones}
            onClose={() => setShowZoneSuggestions(false)}
            onSelectZone={(zoneId) => {
              window.location.href = `/provider/settings/service-zones?select=${zoneId}`;
            }}
          />
        )}
      </div>
    </RoleGuard>
  );
}

function ZoneSuggestionsModal({
  zones,
  onClose,
  onSelectZone,
}: {
  zones: any[];
  onClose: () => void;
  onSelectZone: (zoneId: string) => void;
}) {
  return (
    <Dialog open={true} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-blue-100 rounded-lg">
              <Sparkles className="w-6 h-6 text-blue-600" />
            </div>
            <div>
              <DialogTitle>Service Zone Suggestions</DialogTitle>
              <DialogDescription className="mt-1">
                We found {zones.length} zone{zones.length !== 1 ? "s" : ""} matching your location. Select zones to start offering at-home services.
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        <div className="space-y-3 mb-6">
          {zones.map((zone) => (
            <div
              key={zone.id}
              className="border-2 border-blue-200 rounded-lg p-4 bg-blue-50 hover:bg-blue-100 transition-colors"
            >
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <h3 className="font-semibold text-lg mb-1">{zone.name}</h3>
                  <p className="text-sm text-blue-700 mb-2">{zone.match_reason}</p>
                  <p className="text-xs text-gray-600">
                    Type: {zone.zone_type === "postal_code" ? "Postal Code" : 
                           zone.zone_type === "city" ? "City" :
                           zone.zone_type === "radius" ? "Radius" : "Polygon"}
                  </p>
                </div>
                <Button
                  onClick={() => onSelectZone(zone.id)}
                  className="bg-[#FF0077] hover:bg-[#D60565] text-white ml-4"
                >
                  Select Zone
                </Button>
              </div>
            </div>
          ))}
        </div>

        <div className="flex gap-2 justify-end pt-4 border-t">
          <Button variant="outline" onClick={onClose}>
            Maybe Later
          </Button>
          <Button
            onClick={() => {
              window.location.href = "/provider/settings/service-zones";
            }}
            className="bg-[#FF0077] hover:bg-[#D60565] text-white"
          >
            View All Zones
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

