function LocationModal({
  location,
  onClose,
  onSave,
}: {
  location: Location | null;
  onClose: () => void;
  onSave: () => void;
}) {
  const [formData, setFormData] = useState({
    name: location?.name || "",
    address_line1: location?.address_line1 || "",
    address_line2: location?.address_line2 || "",
    city: location?.city || "",
    state: location?.state || "",
    postal_code: location?.postal_code || "",
    country: location?.country || "South Africa",
    phone: location?.phone || "",
    email: location?.email || "",
    is_active: location?.is_active ?? true,
    latitude: location?.latitude || undefined,
    longitude: location?.longitude || undefined,
  });
  const [isSaving, setIsSaving] = useState(false);

  const handleAddressSelect = (address: {
    address_line1: string;
    city: string;
    state?: string;
    postal_code?: string;
    country: string;
    latitude: number;
    longitude: number;
  }) => {
    setFormData({
      ...formData,
      address_line1: address.address_line1,
      city: address.city,
      state: address.state || "",
      postal_code: address.postal_code || "",
      country: address.country,
      latitude: address.latitude,
      longitude: address.longitude,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Client-side validation for required fields
    if (!formData.name?.trim()) {
      toast.error("Location name is required");
      return;
    }
    if (!formData.address_line1?.trim()) {
      toast.error("Address is required");
      return;
    }
    if (!formData.city?.trim()) {
      toast.error("City is required");
      return;
    }
    if (!formData.country?.trim()) {
      toast.error("Country is required");
      return;
    }

    try {
      setIsSaving(true);

      const submitData = {
        name: formData.name.trim(),
        address_line1: formData.address_line1.trim(),
        address_line2: formData.address_line2?.trim() || null,
        city: formData.city.trim(),
        state: formData.state?.trim() || null,
        postal_code: formData.postal_code?.trim() || null,
        country: formData.country.trim(),
        phone: formData.phone?.trim() || null,
        email: formData.email?.trim() || null,
        is_active: formData.is_active,
        latitude: formData.latitude || null,
        longitude: formData.longitude || null,
      };

      let response;
      if (location) {
        response = await fetcher.patch<{ data: any }>(`/api/provider/locations/${location.id}`, submitData);
      } else {
        response = await fetcher.post<{ data: any }>("/api/provider/locations", submitData);
      }

      toast.success(location ? "Location updated" : "Location added");

      // Check if zone suggestions are available
      if (response.data?._metadata?.has_zone_suggestions && response.data?._metadata?.suggested_zones?.length > 0) {
        // Store suggestions for modal display
        (window as any).__zoneSuggestions = response.data._metadata.suggested_zones;
        (window as any).__showZoneSuggestions = true;
      }

      onSave();
    } catch (error: any) {
      const errorMessage = error?.message || "Failed to save location";
      toast.error(errorMessage);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-2xl font-semibold mb-4">
          {location ? "Edit Location" : "Add Location"}
        </h2>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="name">Location Name *</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              placeholder="Main Salon, Branch Location, etc."
              required
            />
          </div>

          <div>
            <Label htmlFor="address">Address *</Label>
            <p className="text-sm text-gray-600 mb-2">
              Start typing an address and select from suggestions. Address will be automatically geocoded with coordinates.
            </p>
            <AddressAutocomplete
              value={formData.address_line1}
              onChange={handleAddressSelect}
              placeholder="Start typing an address..."
              country={formData.country}
              required
            />
          </div>

          <div>
            <Label htmlFor="address_line2">Apt/Suite (optional)</Label>
            <Input
              id="address_line2"
              value={formData.address_line2}
              onChange={(e) =>
                setFormData({ ...formData, address_line2: e.target.value })
              }
              placeholder="Apt 4B, Suite 201, etc."
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="city">City *</Label>
              <Input
                id="city"
                value={formData.city}
                onChange={(e) => setFormData({ ...formData, city: e.target.value })}
                required
              />
            </div>
            <div>
              <Label htmlFor="state">State/Province</Label>
              <Input
                id="state"
                value={formData.state}
                onChange={(e) => setFormData({ ...formData, state: e.target.value })}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="postal_code">Postal Code</Label>
              <Input
                id="postal_code"
                value={formData.postal_code}
                onChange={(e) =>
                  setFormData({ ...formData, postal_code: e.target.value })
                }
              />
            </div>
            <div>
              <Label htmlFor="country">Country *</Label>
              <Input
                id="country"
                value={formData.country}
                onChange={(e) =>
                  setFormData({ ...formData, country: e.target.value })
                }
                required
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="phone">Phone</Label>
              <Input
                id="phone"
                type="tel"
                value={formData.phone}
                onChange={(e) =>
                  setFormData({ ...formData, phone: e.target.value })
                }
              />
            </div>
            <div>
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) =>
                  setFormData({ ...formData, email: e.target.value })
                }
              />
            </div>
          </div>

          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="is_active"
              checked={formData.is_active}
              onChange={(e) =>
                setFormData({ ...formData, is_active: e.target.checked })
              }
            />
            <Label htmlFor="is_active">Active (visible to customers)</Label>
          </div>

          <div className="flex gap-2 pt-4">
            <Button type="button" variant="outline" onClick={onClose} className="flex-1">
              Cancel
            </Button>
            <Button 
              type="submit" 
              disabled={isSaving || !formData.name?.trim() || !formData.address_line1?.trim() || !formData.city?.trim() || !formData.country?.trim()} 
              className="flex-1"
            >
              {isSaving ? "Saving..." : location ? "Update" : "Add"}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { MessageSquare, Mail, Smartphone } from "lucide-react";

interface MessagePreviewDialogProps {
  open: boolean;
  onClose: () => void;
  automation: {
    id: string;
    name: string;
    description: string;
    trigger: string;
    type: "reminder" | "update" | "booking" | "milestone";
    action_type?: string;
    message_template?: string;
    subject?: string;
  };
  onSave: (messageTemplate: string, subject?: string) => Promise<void>;
}

export function MessagePreviewDialog({
  open,
  onClose,
  automation,
  onSave,
}: MessagePreviewDialogProps) {
  const [messageTemplate, setMessageTemplate] = useState(
    automation.message_template || ""
  );
  const [subject, setSubject] = useState(automation.subject || "");
  const [isSaving, setIsSaving] = useState(false);
  const [preview, setPreview] = useState("");

  // Generate preview with sample data
  const generatePreview = () => {
    let previewText = messageTemplate;
    previewText = previewText.replace(/\{\{name\}\}/g, "Sarah");
    previewText = previewText.replace(/\{\{customer_name\}\}/g, "Sarah");
    previewText = previewText.replace(/\{\{appointment_date\}\}/g, "March 15, 2024");
    previewText = previewText.replace(/\{\{appointment_time\}\}/g, "2:00 PM");
    previewText = previewText.replace(/\{\{booking_number\}\}/g, "BK-12345");
    previewText = previewText.replace(/\{\{package_expiry_date\}\}/g, "April 1, 2024");
    setPreview(previewText);
  };

  React.useEffect(() => {
    generatePreview();
  }, [messageTemplate]);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await onSave(messageTemplate, subject || undefined);
      onClose();
    } catch (error) {
      console.error("Failed to save message:", error);
    } finally {
      setIsSaving(false);
    }
  };

  const actionType = automation.action_type || "sms";
  const isEmail = actionType === "email";

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            {isEmail ? (
              <Mail className="w-5 h-5" />
            ) : (
              <Smartphone className="w-5 h-5" />
            )}
            Message Template: {automation.name}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div>
            <Label>Trigger</Label>
            <Badge variant="outline" className="mt-1">
              {automation.trigger}
            </Badge>
          </div>

          {isEmail && (
            <div>
              <Label htmlFor="subject">Email Subject</Label>
              <Input
                id="subject"
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                placeholder="Enter email subject"
                className="mt-1"
              />
            </div>
          )}

          <div>
            <Label htmlFor="message">Message Template</Label>
            <Textarea
              id="message"
              value={messageTemplate}
              onChange={(e) => setMessageTemplate(e.target.value)}
              placeholder="Enter your message template. Use {{name}}, {{appointment_date}}, etc. for personalization."
              className="mt-1 min-h-[150px] font-mono text-sm"
            />
            <p className="text-xs text-gray-500 mt-1">
              Available variables: {`{{name}}`}, {`{{appointment_date}}`}, {`{{appointment_time}}`}, {`{{booking_number}}`}, {`{{package_expiry_date}}`}
            </p>
          </div>

          <div>
            <Label>Preview</Label>
            <div className="mt-1 p-4 bg-gray-50 rounded-lg border">
              <div className="flex items-start gap-2 mb-2">
                <MessageSquare className="w-4 h-4 text-gray-500 mt-0.5" />
                <div className="flex-1">
                  {isEmail && subject && (
                    <div className="font-semibold text-sm mb-2">{subject}</div>
                  )}
                  <div className="text-sm whitespace-pre-wrap">{preview || "Preview will appear here..."}</div>
                </div>
              </div>
            </div>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={isSaving}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={isSaving || !messageTemplate}>
            {isSaving ? "Saving..." : "Save Template"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import type { Automation } from "@/lib/provider-portal/types";
import { PageHeader } from "@/components/provider/PageHeader";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Info, Link as LinkIcon, Edit, History, Settings } from "lucide-react";
import { toast } from "sonner";
import NextLink from "next/link";
import { MessagePreviewDialog } from "./components/MessagePreviewDialog";
import { SubscriptionGate } from "@/components/provider/SubscriptionGate";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { format } from "date-fns";

export default function ProviderAutomations() {
  const [automations, setAutomations] = useState<Automation[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("reminders");
  const [smsBalance, setSmsBalance] = useState<number | null>(null);
  const [isLoadingBalance, setIsLoadingBalance] = useState(false);
  const [previewDialogOpen, setPreviewDialogOpen] = useState(false);
  const [selectedAutomation, setSelectedAutomation] = useState<Automation | null>(null);
  const [historyDialogOpen, setHistoryDialogOpen] = useState(false);
  const [executionHistory, setExecutionHistory] = useState<any[]>([]);
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);
  const [subscriptionRequired, setSubscriptionRequired] = useState(false);

  useEffect(() => {
    // Load automations and SMS balance in parallel
    Promise.all([
      loadAutomations().catch(() => {
        // Errors are handled in loadAutomations, just prevent unhandled promise rejection
      }),
      loadSmsBalance().catch(() => {
        // Errors are handled in loadSmsBalance, just prevent unhandled promise rejection
      }),
    ]);
  }, []);

  const loadSmsBalance = async () => {
    try {
      setIsLoadingBalance(true);
      const response = await fetcher.get<{ 
        data: { 
          balance: number | null; 
          estimatedMessagesRemaining: number | null;
          hasIntegration: boolean;
        } 
      }>("/api/provider/twilio-integration/balance", {
        timeoutMs: 10000,
      });

      if (response.data?.hasIntegration && response.data.estimatedMessagesRemaining !== null) {
        setSmsBalance(response.data.estimatedMessagesRemaining);
      } else {
        // Default to null if no integration or balance unavailable
        setSmsBalance(null);
      }
    } catch (error) {
      console.error("Failed to load SMS balance:", error);
      // Don't show error toast - balance is optional
      setSmsBalance(null);
    } finally {
      setIsLoadingBalance(false);
    }
  };

  const loadAutomations = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data: any[] }>("/api/provider/automations", {
        timeoutMs: 30000,
      });

      // Store raw data for template activation
      const rawAutomations = response.data || [];

      // Map database structure to Automation type
      const mappedAutomations: Automation[] = rawAutomations.map((auto: any) => {
        const isTemplate = auto.is_template === true;

        // Map trigger type to automation type
        const mapType = (triggerType: string): "reminder" | "update" | "booking" | "milestone" => {
          if (!triggerType) return "reminder";
          const type = triggerType.toLowerCase();
          if (type.includes("reminder") || type.includes("before")) return "reminder";
          if (type.includes("update") || type.includes("confirmed") || type.includes("cancelled") || 
              type.includes("rescheduled") || type.includes("no_show")) return "update";
          if (type.includes("booking") || type.includes("completed") || type.includes("inactive") || 
              type.includes("lead") || type.includes("package_expiring") || type.includes("seasonal")) return "booking";
          if (type.includes("birthday") || type.includes("anniversary") || type.includes("milestone") || 
              type.includes("visit_milestone") || type.includes("referral") || type.includes("holiday")) return "milestone";
          return "reminder";
        };

        // Format trigger display
        const formatTrigger = (triggerType: string, triggerConfig: any): string => {
          if (triggerConfig?.hours_before) {
            return `${triggerConfig.hours_before}h before`;
          }
          if (triggerConfig?.minutes_before) {
            const hours = Math.floor(triggerConfig.minutes_before / 60);
            const minutes = triggerConfig.minutes_before % 60;
            if (hours > 0 && minutes > 0) return `${hours}h ${minutes}m before`;
            if (hours > 0) return `${hours}h before`;
            return `${minutes}m before`;
          }
          return triggerType || "";
        };

        return {
          id: auto.id,
          name: auto.name,
          type: mapType(auto.trigger_type),
          trigger: formatTrigger(auto.trigger_type, auto.trigger_config),
          is_active: isTemplate ? false : (auto.is_active ?? true),
          description: auto.description || "Automated message",
          is_template: isTemplate,
          // Store raw data for template activation
          _raw: auto,
        };
      });

      setAutomations(mappedAutomations);
      setSubscriptionRequired(false);
    } catch (error) {
      // Check if it's a subscription error first (before logging)
      if (error instanceof FetchError) {
        const isSubscriptionError = 
          error.code === "SUBSCRIPTION_REQUIRED" || 
          error.message?.toLowerCase().includes("subscription upgrade") ||
          error.message?.toLowerCase().includes("starter plan") ||
          error.message?.toLowerCase().includes("subscription") ||
          error.status === 403;

        if (isSubscriptionError) {
          // Handle subscription error gracefully - no console error, no toast
          setSubscriptionRequired(true);
          setIsLoading(false);
          return; // Exit early, don't show error toast
        }

        // For other FetchErrors, log and show toast
        console.error("Failed to load automations:", error);
        toast.error(error.message || "Failed to load automations");
      } else {
        // For non-FetchErrors, log and show toast
        console.error("Failed to load automations:", error);
        toast.error("Failed to load automations");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const toggleAutomation = async (id: string, isActive: boolean) => {
    try {
      // Find the automation in the current list to check if it's a template
      const automation = automations.find((a) => a.id === id);

      if (!automation) {
        toast.error("Automation not found");
        return;
      }

      // Check if this is a template (starts with "template-" or is marked as template)
      // Templates are inactive by default and need to be "activated" (created as real automation)
      const isTemplate = automation.is_template === true || id.startsWith("template-");

      if (isTemplate && !isActive) {
        // Create the automation from template using raw database data
        if (!automation._raw) {
          toast.error("Template data not available");
          return;
        }

        const raw = automation._raw;
        await fetcher.post("/api/provider/automations", {
          name: raw.name,
          trigger_type: raw.trigger_type,
          trigger_config: raw.trigger_config || {},
          action_type: raw.action_type || "sms",
          action_config: raw.action_config || {},
          delay_minutes: raw.delay_minutes || 0,
          is_active: true,
          description: raw.description,
        });
        toast.success("Automation enabled");
      } else {
        // Update existing automation
        await fetcher.patch(`/api/provider/automations/${id}`, {
          is_active: !isActive,
        });
        toast.success(`Automation ${!isActive ? "enabled" : "disabled"}`);
      }
      loadAutomations();
    } catch (error: any) {
      console.error("Failed to toggle automation:", error);
      toast.error(error?.message || "Failed to update automation");
    }
  };

  const filteredAutomations = automations.filter((auto) => {
    if (activeTab === "reminders") return auto.type === "reminder";
    if (activeTab === "updates") return auto.type === "update";
    if (activeTab === "bookings") return auto.type === "booking";
    if (activeTab === "milestones") return auto.type === "milestone";
    return true;
  });

  return (
    <div>
      <PageHeader
        title="Automations"
        subtitle="Set up automated messages and reminders"
      />

      {/* Subscription Gate */}
      {subscriptionRequired && (
        <div className="mb-6">
          <SubscriptionGate
            feature="Marketing Automations"
            message="Marketing automations require a subscription upgrade"
            upgradeMessage="Upgrade to Starter plan or higher to access marketing automations and send automated messages to your clients."
            showUpgradeButton={true}
          />
        </div>
      )}

      {/* Don't show content if subscription is required */}
      {!subscriptionRequired && (
        <>
          {/* Top-up Card */}
      <SectionCard className="mb-6 bg-gradient-to-r from-[#FF0077]/10 to-[#D60565]/10 border-[#FF0077]/20">
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
          <div className="flex-1">
            <div className="flex items-center gap-2 mb-2">
              <Info className="w-5 h-5 text-[#FF0077]" />
              <h3 className="font-semibold">Ensure your text messages send with automatic top-ups</h3>
            </div>
            <p className="text-sm text-gray-600">
              Never miss a message. Set up automatic top-ups to keep your communications flowing.
            </p>
          </div>
          <Button 
            className="bg-[#FF0077] hover:bg-[#D60565] whitespace-nowrap"
            onClick={() => {
              // Navigate to Twilio integration settings
              window.location.href = "/provider/settings/integrations";
            }}
          >
            <Settings className="w-4 h-4 mr-2" />
            Set up
          </Button>
        </div>
      </SectionCard>

      {/* Quick Links Card */}
      <div className="mb-6 grid grid-cols-1 md:grid-cols-2 gap-4">
        <SectionCard className="w-full md:w-auto">
          <div className="flex items-center justify-between gap-4">
            <div>
              <p className="text-sm text-gray-600">Text messages remaining</p>
              {isLoadingBalance ? (
                <p className="text-2xl font-semibold animate-pulse">...</p>
              ) : smsBalance !== null ? (
                <p className="text-2xl font-semibold">{smsBalance.toLocaleString()}</p>
              ) : (
                <p className="text-2xl font-semibold text-gray-400">N/A</p>
              )}
            </div>
            <Button 
              variant="outline" 
              size="sm"
              onClick={loadSmsBalance}
              disabled={isLoadingBalance}
            >
              {isLoadingBalance ? "Loading..." : "View Balance"}
            </Button>
          </div>
        </SectionCard>

        <SectionCard className="w-full md:w-auto bg-gradient-to-r from-blue-50 to-indigo-50 border-blue-200">
          <div className="flex items-center justify-between gap-4">
            <div className="flex-1">
              <div className="flex items-center gap-2 mb-1">
                <LinkIcon className="w-4 h-4 text-blue-600" />
                <p className="text-sm font-medium text-gray-700">Express Booking Links</p>
              </div>
              <p className="text-xs text-gray-600">Create quick booking links for clients</p>
            </div>
            <NextLink href="/provider/express-booking">
              <Button size="sm" className="bg-blue-600 hover:bg-blue-700">
                Manage Links
              </Button>
            </NextLink>
          </div>
        </SectionCard>

        <SectionCard className="w-full md:w-auto bg-gradient-to-r from-purple-50 to-pink-50 border-purple-200">
          <div className="flex items-center justify-between gap-4">
            <div className="flex-1">
              <div className="flex items-center gap-2 mb-1">
                <Info className="w-4 h-4 text-purple-600" />
                <p className="text-sm font-medium text-gray-700">Marketing Campaigns</p>
              </div>
              <p className="text-xs text-gray-600">Create email and SMS campaigns</p>
            </div>
            <NextLink href="/provider/marketing/campaigns">
              <Button size="sm" className="bg-purple-600 hover:bg-purple-700">
                Manage Campaigns
              </Button>
            </NextLink>
          </div>
        </SectionCard>
      </div>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger value="reminders">Reminders</TabsTrigger>
          <TabsTrigger value="updates">Appointment updates</TabsTrigger>
          <TabsTrigger value="bookings">Increase bookings</TabsTrigger>
          <TabsTrigger value="milestones">Celebrate milestones</TabsTrigger>
        </TabsList>

        <TabsContent value={activeTab} className="mt-6">
          {isLoading ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {[...Array(6)].map((_, i) => (
                <Skeleton key={i} className="h-48" />
              ))}
            </div>
          ) : filteredAutomations.length === 0 ? (
            <SectionCard className="p-12 text-center">
              <p className="text-gray-600 mb-4">No {activeTab} automations yet</p>
              <Button
                variant="outline"
                onClick={() => console.log("Create automation")}
              >
                Create Automation
              </Button>
            </SectionCard>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {filteredAutomations.map((automation) => (
                <SectionCard key={automation.id} className="p-6">
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex-1">
                      <h3 className="font-semibold mb-1">{automation.name}</h3>
                      <p className="text-sm text-gray-600 mb-3">{automation.description}</p>
                      <Badge variant="outline" className="text-xs">
                        {automation.trigger}
                      </Badge>
                    </div>
                    <Switch
                      checked={automation.is_active}
                      onCheckedChange={() => toggleAutomation(automation.id, automation.is_active)}
                    />
                  </div>
                  <div className="flex gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      className="flex-1"
                      onClick={() => {
                        setSelectedAutomation(automation);
                        setPreviewDialogOpen(true);
                      }}
                    >
                      <Edit className="w-4 h-4 mr-2" />
                      Edit Message
                    </Button>
                    {!automation.is_template && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={async () => {
                          setSelectedAutomation(automation);
                          setHistoryDialogOpen(true);
                          await loadExecutionHistory(automation.id);
                        }}
                      >
                        <History className="w-4 h-4" />
                      </Button>
                    )}
                  </div>
                </SectionCard>
              ))}
            </div>
          )}
        </TabsContent>
      </Tabs>
        </>
      )}

      {/* Message Preview/Edit Dialog */}
      {selectedAutomation && (
        <MessagePreviewDialog
          open={previewDialogOpen}
          onClose={() => {
            setPreviewDialogOpen(false);
            setSelectedAutomation(null);
          }}
          automation={{
            id: selectedAutomation.id,
            name: selectedAutomation.name,
            description: selectedAutomation.description || "",
            trigger: selectedAutomation.trigger,
            type: selectedAutomation.type,
            action_type: (selectedAutomation as any)._raw?.action_type || "sms",
            message_template: (selectedAutomation as any)._raw?.action_config?.message_template || "",
            subject: (selectedAutomation as any)._raw?.action_config?.subject || "",
          }}
          onSave={async (messageTemplate, subject) => {
            await fetcher.patch(`/api/provider/automations/${selectedAutomation.id}`, {
              action_config: {
                message_template: messageTemplate,
                ...(subject && { subject }),
              },
            });
            toast.success("Message template updated");
            loadAutomations();
          }}
        />
      )}

      {/* Execution History Dialog */}
      <Dialog open={historyDialogOpen} onOpenChange={setHistoryDialogOpen}>
        <DialogContent className="max-w-3xl max-h-[80vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Execution History: {selectedAutomation?.name}</DialogTitle>
          </DialogHeader>
          {isLoadingHistory ? (
            <div className="py-8 text-center">Loading history...</div>
          ) : executionHistory.length === 0 ? (
            <div className="py-8 text-center text-gray-500">
              No executions yet. This automation hasn't been triggered.
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Date</TableHead>
                  <TableHead>Customer</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Message ID</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {executionHistory.map((execution) => (
                  <TableRow key={execution.id}>
                    <TableCell>
                      {format(new Date(execution.executed_at), "MMM d, yyyy h:mm a")}
                    </TableCell>
                    <TableCell>
                      {execution.customer?.full_name || execution.customer?.email || "Unknown"}
                    </TableCell>
                    <TableCell>
                      <Badge variant={execution.message_id ? "default" : "secondary"}>
                        {execution.message_id ? "Sent" : "Pending"}
                      </Badge>
                    </TableCell>
                    <TableCell className="font-mono text-xs">
                      {execution.message_id || "N/A"}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );

  const loadExecutionHistory = async (automationId: string) => {
    try {
      setIsLoadingHistory(true);
      const response = await fetcher.get<{ data: any[] }>(`/api/provider/automations/${automationId}/executions`);
      setExecutionHistory(response?.data ?? []);
    } catch (error) {
      console.error("Failed to load execution history:", error);
      toast.error("Failed to load execution history");
    } finally {
      setIsLoadingHistory(false);
    }
  };
}

"use client";

import React from "react";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";

interface SegmentCriteria {
  min_bookings?: number;
  max_bookings?: number;
  min_spent?: number;
  max_spent?: number;
  last_booking_days?: number;
  tags?: string[];
  is_favorite?: boolean;
}

interface SegmentBuilderProps {
  criteria: SegmentCriteria;
  onCriteriaChange: (criteria: SegmentCriteria) => void;
  availableTags?: string[];
}

export default function SegmentBuilder({ criteria, onCriteriaChange, availableTags: _availableTags = [] }: SegmentBuilderProps) {
  const updateCriteria = (key: keyof SegmentCriteria, value: any) => {
    onCriteriaChange({ ...criteria, [key]: value });
  };

  return (
    <div className="space-y-4">
      <div>
        <Label className="text-sm font-medium mb-2 block">Booking Criteria</Label>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <Label htmlFor="min_bookings" className="text-xs text-gray-500">Min Bookings</Label>
            <Input
              id="min_bookings"
              type="number"
              min="0"
              value={criteria.min_bookings || ""}
              onChange={(e) => updateCriteria("min_bookings", e.target.value ? parseInt(e.target.value) : undefined)}
              placeholder="0"
            />
          </div>
          <div>
            <Label htmlFor="max_bookings" className="text-xs text-gray-500">Max Bookings</Label>
            <Input
              id="max_bookings"
              type="number"
              min="0"
              value={criteria.max_bookings || ""}
              onChange={(e) => updateCriteria("max_bookings", e.target.value ? parseInt(e.target.value) : undefined)}
              placeholder="Unlimited"
            />
          </div>
        </div>
      </div>

      <div>
        <Label className="text-sm font-medium mb-2 block">Spending Criteria</Label>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <Label htmlFor="min_spent" className="text-xs text-gray-500">Min Spent ($)</Label>
            <Input
              id="min_spent"
              type="number"
              min="0"
              step="0.01"
              value={criteria.min_spent || ""}
              onChange={(e) => updateCriteria("min_spent", e.target.value ? parseFloat(e.target.value) : undefined)}
              placeholder="0.00"
            />
          </div>
          <div>
            <Label htmlFor="max_spent" className="text-xs text-gray-500">Max Spent ($)</Label>
            <Input
              id="max_spent"
              type="number"
              min="0"
              step="0.01"
              value={criteria.max_spent || ""}
              onChange={(e) => updateCriteria("max_spent", e.target.value ? parseFloat(e.target.value) : undefined)}
              placeholder="Unlimited"
            />
          </div>
        </div>
      </div>

      <div>
        <Label htmlFor="last_booking_days" className="text-sm font-medium mb-2 block">Last Booking</Label>
        <Select
          value={criteria.last_booking_days?.toString() || ""}
          onValueChange={(value) => updateCriteria("last_booking_days", value ? parseInt(value) : undefined)}
        >
          <SelectTrigger>
            <SelectValue placeholder="Any time" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="">Any time</SelectItem>
            <SelectItem value="7">Last 7 days</SelectItem>
            <SelectItem value="30">Last 30 days</SelectItem>
            <SelectItem value="60">Last 60 days</SelectItem>
            <SelectItem value="90">Last 90 days</SelectItem>
            <SelectItem value="180">Last 6 months</SelectItem>
            <SelectItem value="365">Last year</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div>
        <Label className="text-sm font-medium mb-2 block">Client Status</Label>
        <div className="flex items-center space-x-2">
          <Checkbox
            id="is_favorite"
            checked={criteria.is_favorite === true}
            onCheckedChange={(checked) => updateCriteria("is_favorite", checked ? true : undefined)}
          />
          <Label htmlFor="is_favorite" className="text-sm font-normal cursor-pointer">
            Only favorite clients
          </Label>
        </div>
      </div>

      {/* Tags filtering: hidden until implemented. availableTags prop reserved for future use. */}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { PageHeader } from "@/components/provider/PageHeader";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Plus, Mail, MessageSquare, Send, Edit, Trash2, Users, MessageCircle } from "lucide-react";
import { FetchError } from "@/lib/http/fetcher";
import { providerApi } from "@/lib/provider-portal/api";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { format } from "date-fns";
import ClientSelector from "./components/ClientSelector";
import SegmentBuilder from "./components/SegmentBuilder";

interface Campaign {
  id: string;
  name: string;
  type: "email" | "sms" | "whatsapp";
  subject?: string;
  content: string;
  recipient_type: "all_clients" | "segment" | "custom";
  recipient_ids?: string[];
  segment_criteria?: {
    min_bookings?: number;
    max_bookings?: number;
    min_spent?: number;
    max_spent?: number;
    last_booking_days?: number;
    tags?: string[];
    is_favorite?: boolean;
  };
  status: "draft" | "scheduled" | "sending" | "sent" | "cancelled";
  scheduled_at?: string;
  sent_at?: string;
  total_recipients: number;
  sent_count: number;
  opened_count?: number;
  clicked_count?: number;
  created_at: string;
}

export default function MarketingCampaignsPage() {
  const [campaigns, setCampaigns] = useState<Campaign[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [selectedCampaign, setSelectedCampaign] = useState<Campaign | null>(null);
  const [activeTab, setActiveTab] = useState<"email" | "sms" | "whatsapp">("email");

  // Form state
  const [formData, setFormData] = useState({
    name: "",
    type: "email" as "email" | "sms" | "whatsapp",
    subject: "",
    content: "",
    recipient_type: "all_clients" as "all_clients" | "segment" | "custom",
    recipient_ids: [] as string[],
    segment_criteria: {} as Campaign["segment_criteria"],
    scheduled_at: "",
  });

  useEffect(() => {
    loadCampaigns();
  }, []);

  const loadCampaigns = async () => {
    try {
      setIsLoading(true);
      const data = await providerApi.listCampaigns();
      setCampaigns((data || []) as any as Campaign[]);
    } catch (error) {
      console.error("Failed to load campaigns:", error);
      toast.error("Failed to load campaigns");
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreate = () => {
    setSelectedCampaign(null);
    setFormData({
      name: "",
      type: "email",
      subject: "",
      content: "",
      recipient_type: "all_clients",
      recipient_ids: [],
      segment_criteria: {},
      scheduled_at: "",
    });
    setIsDialogOpen(true);
  };

  const handleEdit = (campaign: Campaign) => {
    setSelectedCampaign(campaign);
    setFormData({
      name: campaign.name,
      type: campaign.type,
      subject: campaign.subject || "",
      content: campaign.content,
      recipient_type: campaign.recipient_type,
      recipient_ids: campaign.recipient_ids || [],
      segment_criteria: campaign.segment_criteria || {},
      scheduled_at: campaign.scheduled_at || "",
    });
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    try {
      if (!formData.name || !formData.content) {
        toast.error("Please fill in all required fields");
        return;
      }

      if (formData.type === "email" && !formData.subject) {
        toast.error("Email campaigns require a subject");
        return;
      }

      if (formData.recipient_type === "custom" && formData.recipient_ids.length === 0) {
        toast.error("Please select at least one client for custom recipient list");
        return;
      }

      if (formData.recipient_type === "segment") {
        const hasCriteria = Object.keys(formData.segment_criteria || {}).length > 0;
        if (!hasCriteria) {
          toast.error("Please set at least one segmentation criteria");
          return;
        }
      }

      const payload: any = {
        name: formData.name,
        type: formData.type,
        content: formData.content,
        recipient_type: formData.recipient_type,
      };

      if (formData.type === "email") {
        payload.subject = formData.subject;
      }

      if (formData.recipient_type === "custom") {
        payload.recipient_ids = formData.recipient_ids;
      }

      if (formData.recipient_type === "segment") {
        payload.segment_criteria = formData.segment_criteria;
      }

      if (formData.scheduled_at) {
        payload.scheduled_at = formData.scheduled_at;
      }

      if (selectedCampaign) {
        await providerApi.updateCampaign(selectedCampaign.id, payload);
        toast.success("Campaign updated successfully");
      } else {
        await providerApi.createCampaign(payload);
        toast.success("Campaign created successfully");
      }

      setIsDialogOpen(false);
      loadCampaigns();
    } catch (error) {
      const errorMessage = error instanceof FetchError ? error.message : "Failed to save campaign";
      toast.error(errorMessage);
    }
  };

  const handleSend = async (campaignId: string) => {
    try {
      await providerApi.sendCampaign(campaignId);
      toast.success("Campaign sent successfully");
      loadCampaigns();
    } catch (error) {
      const errorMessage = error instanceof FetchError ? error.message : "Failed to send campaign";
      toast.error(errorMessage);
    }
  };

  const handleDelete = async (campaignId: string) => {
    if (!confirm("Are you sure you want to delete this campaign?")) return;

    try {
      await providerApi.deleteCampaign(campaignId);
      toast.success("Campaign deleted successfully");
      loadCampaigns();
    } catch (error) {
      const errorMessage = error instanceof FetchError ? error.message : "Failed to delete campaign";
      toast.error(errorMessage);
    }
  };

  const getStatusBadge = (status: string) => {
    const variants: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
      draft: "outline",
      scheduled: "secondary",
      sending: "default",
      sent: "default",
      cancelled: "destructive",
    };

    return (
      <Badge variant={variants[status] || "outline"}>
        {status.charAt(0).toUpperCase() + status.slice(1)}
      </Badge>
    );
  };

  const filteredCampaigns = campaigns.filter((c) => {
    if (activeTab === "whatsapp") {
      return c.type === "whatsapp";
    }
    return c.type === activeTab;
  });

  if (isLoading) {
    return (
      <div>
        <PageHeader title="Marketing Campaigns" subtitle="Create and manage email and SMS campaigns" />
        <LoadingTimeout loadingMessage="Loading campaigns..." />
      </div>
    );
  }

  return (
    <div>
      <PageHeader
        title="Marketing Campaigns"
        subtitle="Create and manage email, SMS, and WhatsApp campaigns to engage with your clients"
      />

      <div className="mb-6 flex justify-end">
        <Button onClick={handleCreate} className="bg-[#FF0077] hover:bg-[#D60565]">
          <Plus className="w-4 h-4 mr-2" />
          Create Campaign
        </Button>
      </div>

      <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as "email" | "sms" | "whatsapp")}>
        <TabsList>
          <TabsTrigger value="email">
            <Mail className="w-4 h-4 mr-2" />
            Email Campaigns
          </TabsTrigger>
          <TabsTrigger value="sms">
            <MessageSquare className="w-4 h-4 mr-2" />
            SMS Campaigns
          </TabsTrigger>
          <TabsTrigger value="whatsapp">
            <MessageCircle className="w-4 h-4 mr-2" />
            WhatsApp Campaigns
          </TabsTrigger>
        </TabsList>

        <TabsContent value={activeTab} className="mt-6">
          {filteredCampaigns.length === 0 ? (
            <EmptyState
              title={`No ${activeTab.toUpperCase()} campaigns yet`}
              description="Create your first campaign to start engaging with your clients"
              action={{
                label: "Create Campaign",
                onClick: handleCreate,
              }}
            />
          ) : (
            <SectionCard>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Name</TableHead>
                    <TableHead>Type</TableHead>
                    <TableHead>Recipients</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Sent</TableHead>
                    <TableHead>Created</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredCampaigns.map((campaign) => (
                    <TableRow key={campaign.id}>
                      <TableCell className="font-medium">{campaign.name}</TableCell>
                      <TableCell>
                        {campaign.type === "email" ? (
                          <Mail className="w-4 h-4 text-blue-600" />
                        ) : campaign.type === "whatsapp" ? (
                          <MessageCircle className="w-4 h-4 text-green-600" />
                        ) : (
                          <MessageSquare className="w-4 h-4 text-green-500" />
                        )}
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-1">
                          <Users className="w-4 h-4 text-gray-400" />
                          {campaign.sent_count > 0
                            ? `${campaign.sent_count} / ${campaign.total_recipients}`
                            : campaign.total_recipients}
                        </div>
                      </TableCell>
                      <TableCell>{getStatusBadge(campaign.status)}</TableCell>
                      <TableCell>
                        {campaign.sent_at
                          ? format(new Date(campaign.sent_at), "MMM d, yyyy")
                          : campaign.scheduled_at
                          ? format(new Date(campaign.scheduled_at), "MMM d, yyyy")
                          : "-"}
                      </TableCell>
                      <TableCell>{format(new Date(campaign.created_at), "MMM d, yyyy")}</TableCell>
                      <TableCell className="text-right">
                        <div className="flex items-center justify-end gap-2">
                          {campaign.status === "draft" && (
                            <>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => handleEdit(campaign)}
                              >
                                <Edit className="w-4 h-4" />
                              </Button>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => handleSend(campaign.id)}
                              >
                                <Send className="w-4 h-4" />
                              </Button>
                            </>
                          )}
                          {campaign.status !== "sent" && (
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleDelete(campaign.id)}
                            >
                              <Trash2 className="w-4 h-4 text-red-600" />
                            </Button>
                          )}
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </SectionCard>
          )}
        </TabsContent>
      </Tabs>

      {/* Create/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {selectedCampaign ? "Edit Campaign" : "Create Campaign"}
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div>
              <Label htmlFor="name">Campaign Name *</Label>
              <Input
                id="name"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                placeholder="Summer Promotion 2025"
              />
            </div>

            <div>
              <Label htmlFor="type">Campaign Type *</Label>
              <Select
                value={formData.type}
                onValueChange={(value) => setFormData({ ...formData, type: value as "email" | "sms" | "whatsapp" })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="email">Email</SelectItem>
                  <SelectItem value="sms">SMS</SelectItem>
                  <SelectItem value="whatsapp">WhatsApp</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {formData.type === "email" && (
              <div>
                <Label htmlFor="subject">Subject *</Label>
                <Input
                  id="subject"
                  value={formData.subject}
                  onChange={(e) => setFormData({ ...formData, subject: e.target.value })}
                  placeholder="Special Offer: 20% Off All Services"
                />
              </div>
            )}

            <div>
              <Label htmlFor="content">Message Content *</Label>
              <Textarea
                id="content"
                value={formData.content}
                onChange={(e) => setFormData({ ...formData, content: e.target.value })}
                placeholder={
                  formData.type === "email" 
                    ? "Enter your email content here..." 
                    : formData.type === "whatsapp"
                    ? "Enter your WhatsApp message here..."
                    : "Enter your SMS message here..."
                }
                rows={formData.type === "email" ? 10 : 5}
                maxLength={formData.type === "sms" || formData.type === "whatsapp" ? 160 : undefined}
              />
              {(formData.type === "sms" || formData.type === "whatsapp") && (
                <p className="text-sm text-gray-500 mt-1">
                  {formData.content.length}/160 characters
                </p>
              )}
            </div>

            <div>
              <Label htmlFor="recipient_type">Recipients *</Label>
              <Select
                value={formData.recipient_type}
                onValueChange={(value) => {
                  const newRecipientType = value as "all_clients" | "segment" | "custom";
                  setFormData({ 
                    ...formData, 
                    recipient_type: newRecipientType,
                    // Reset related fields when changing recipient type
                    recipient_ids: newRecipientType === "custom" ? formData.recipient_ids : [],
                    segment_criteria: newRecipientType === "segment" ? formData.segment_criteria : {},
                  });
                }}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all_clients">All Clients</SelectItem>
                  <SelectItem value="segment">Segment</SelectItem>
                  <SelectItem value="custom">Custom List</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {formData.recipient_type === "custom" && (
              <div className="border rounded-lg p-4 bg-gray-50">
                <ClientSelector
                  selectedIds={formData.recipient_ids}
                  onSelectionChange={(ids) => setFormData({ ...formData, recipient_ids: ids })}
                />
              </div>
            )}

            {formData.recipient_type === "segment" && (
              <div className="border rounded-lg p-4 bg-gray-50">
                <SegmentBuilder
                  criteria={formData.segment_criteria || {}}
                  onCriteriaChange={(criteria) => setFormData({ ...formData, segment_criteria: criteria })}
                />
              </div>
            )}

            <div>
              <Label htmlFor="scheduled_at">Schedule (Optional)</Label>
              <Input
                id="scheduled_at"
                type="datetime-local"
                value={formData.scheduled_at}
                onChange={(e) => setFormData({ ...formData, scheduled_at: e.target.value })}
              />
              <p className="text-sm text-gray-500 mt-1">
                Leave empty to send immediately when you click "Send"
              </p>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSave} className="bg-[#FF0077] hover:bg-[#D60565]">
              {selectedCampaign ? "Update" : "Create"} Campaign
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useSearchParams } from "next/navigation";
import RoleGuard from "@/components/auth/RoleGuard";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import { toast } from "sonner";
import WhatsAppChat from "@/components/messaging/whatsapp-chat";
import ConversationList from "@/components/messaging/conversation-list";
import { getSupabaseClient } from "@/lib/supabase/client";
import BackButton from "@/app/account-settings/components/back-button";
import Breadcrumb from "@/app/account-settings/components/breadcrumb";

interface Conversation {
  id: string;
  customer_id: string;
  customer_name: string;
  customer_phone?: string | null;
  customer_email?: string | null;
  customer_avatar?: string;
  last_message?: string;
  last_message_time?: string;
  unread_count: number;
  booking_id?: string;
  booking_number?: string;
  provider_id?: string;
  last_message_at: string;
  last_message_preview?: string;
  avatar?: string; // For backward compatibility
}

export default function ProviderMessaging() {
  const searchParams = useSearchParams();
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [selectedConversation, setSelectedConversation] = useState<Conversation | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentUserId, setCurrentUserId] = useState<string>("");
  const [showChat, setShowChat] = useState(false);

  useEffect(() => {
    loadCurrentUser();
    loadConversations();
    const unsubscribe = subscribeToConversations();
    return () => {
      if (unsubscribe) unsubscribe();
    };
  }, []);

  // Handle conversation selection from URL
  useEffect(() => {
    const conversationId = searchParams.get("conversationId");
    if (conversationId && conversations.length > 0) {
      const conversation = conversations.find(c => c.id === conversationId);
      if (conversation) {
        setSelectedConversation(conversation);
        setShowChat(true);
      }
    }
  }, [searchParams, conversations]);

  // Ensure chat is shown when conversation is selected (especially on desktop)
  useEffect(() => {
    if (selectedConversation && !showChat) {
      // On desktop, always show chat if conversation is selected
      // On mobile, only show if explicitly set
      if (typeof window !== 'undefined' && window.innerWidth >= 768) {
        setShowChat(true);
      }
    }
  }, [selectedConversation, showChat]);

  const loadCurrentUser = async () => {
    try {
      const supabase = getSupabaseClient();
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        setCurrentUserId(user.id);
      }
    } catch (err) {
      console.error("Error loading current user:", err);
    }
  };

  const loadConversations = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetcher.get<{ data: Conversation[] }>(
        "/api/provider/conversations",
        { timeoutMs: 15000 } // 15 second timeout
      );

      // Handle case where response.data might be undefined or null
      if (!response || !response.data) {
        setConversations([]);
        return;
      }

      // Transform provider conversations to match the expected format
      const transformed = (response.data || []).map((conv) => ({
        ...conv,
        // For provider portal, show customer name and contact details
        provider_name: undefined,
        customer_name: conv.customer_name || "Customer",
        customer_phone: conv.customer_phone ?? null,
        customer_email: conv.customer_email ?? null,
        avatar: conv.customer_avatar || conv.avatar || null,
        last_message_at: conv.last_message_time || conv.last_message_at || new Date().toISOString(),
        last_message_preview: conv.last_message || conv.last_message_preview || "",
        unread_count: conv.unread_count || 0,
        customer_id: conv.customer_id,
        provider_id: conv.provider_id,
        booking_id: conv.booking_id || null,
        booking_number: conv.booking_number || null,
      }));

      setConversations(transformed);
    } catch (err) {
      let errorMessage = "Failed to load conversations";

      if (err instanceof FetchTimeoutError) {
        errorMessage = "Request timed out. Please try again.";
      } else if (err instanceof FetchError) {
        // Provide more specific error messages based on status code
        if (err.status === 401) {
          errorMessage = "Please sign in to view your conversations.";
        } else if (err.status === 403) {
          errorMessage = "You don't have permission to view conversations. Please contact support if you believe this is an error.";
        } else if (err.status === 404) {
          errorMessage = "Conversations endpoint not found.";
        } else if (err.status === 0) {
          errorMessage = "Network error: Unable to reach server. Please check your connection.";
        } else if (err.status >= 500) {
          errorMessage = "Server error. Please try again later.";
        } else {
          errorMessage = err.message || `Failed to fetch conversations (${err.status})`;
        }

        // Log detailed error for debugging
        console.error("Error loading conversations:", {
          message: err.message,
          status: err.status,
          code: err.code,
          details: err.details,
        });
      } else {
        errorMessage = err instanceof Error ? err.message : "An unexpected error occurred";
        console.error("Error loading conversations:", err);
      }

      setError(errorMessage);
      // Set empty array on error to prevent UI issues
      setConversations([]);
      // Show toast notification for user feedback
      toast.error(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const subscribeToConversations = () => {
    const supabase = getSupabaseClient();

    // Debounce conversation reloads to prevent excessive API calls
    let reloadTimeout: NodeJS.Timeout | null = null;
    const debouncedReload = () => {
      if (reloadTimeout) {
        clearTimeout(reloadTimeout);
      }
      reloadTimeout = setTimeout(() => {
        loadConversations();
      }, 1000); // Wait 1 second before reloading to batch updates
    };

    // Subscribe to conversation updates
    const channel = supabase
      .channel("provider-conversations-updates")
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "conversations",
        },
        () => {
          debouncedReload();
        }
      )
      .subscribe();

    return () => {
      if (reloadTimeout) {
        clearTimeout(reloadTimeout);
      }
      try {
        supabase.removeChannel(channel);
      } catch {
        // Ignore when channel is still connecting (e.g. React Strict Mode unmount)
      }
    };
  };

  const handleSelectConversation = (conversation: Conversation) => {
    setSelectedConversation(conversation);
    setShowChat(true);
    // Ensure chat is visible on mobile
    if (window.innerWidth < 768) {
      setShowChat(true);
    }
  };

  const handleBack = () => {
    // On mobile, hide chat and show list
    if (window.innerWidth < 768) {
      setShowChat(false);
    }
    // Don't clear selectedConversation on desktop - keep it selected in the list
    // Only clear on mobile when going back
    if (window.innerWidth < 768) {
      setSelectedConversation(null);
    }
  };

  if (isLoading) {
    return (
      <RoleGuard allowedRoles={["provider_owner", "provider_staff"]}>
        <div className="container mx-auto px-4 py-8">
          <LoadingTimeout loadingMessage="Loading messages..." />
        </div>
      </RoleGuard>
    );
  }

  return (
    <RoleGuard allowedRoles={["provider_owner", "provider_staff"]}>
      <div className="flex flex-col h-screen bg-white overflow-hidden">
        {/* Mobile Header - Only show when list is visible, not when chat is open */}
        {!showChat && (
          <div className="md:hidden border-b border-[#e9edef] bg-white px-4 py-3">
            <BackButton href="/provider/dashboard" />
            <h1 className="text-xl font-semibold text-[#111b21] mt-2">Messages</h1>
          </div>
        )}

        {/* Desktop Header */}
        <div className="hidden md:block border-b border-[#e9edef] bg-white px-6 py-4">
          <Breadcrumb
            items={[
              { label: "Dashboard", href: "/provider/dashboard" },
              { label: "Messages" },
            ]}
          />
        </div>

        {/* Main Content */}
        <div className="flex flex-1 overflow-hidden relative">
          {/* Conversations List */}
          <div
            className={`${
              showChat ? "hidden md:block" : "block"
            } w-full md:w-96 flex-shrink-0 absolute md:relative inset-0 z-10 md:z-auto bg-white`}
          >
            {error && !isLoading ? (
              <div className="flex flex-col items-center justify-center h-full p-8 text-center">
                <div className="w-16 h-16 rounded-full bg-red-100 mx-auto mb-4 flex items-center justify-center">
                  <svg
                    className="w-8 h-8 text-red-600"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
                    />
                  </svg>
                </div>
                <p className="text-[#111b21] text-sm font-medium mb-2">{error}</p>
                <button
                  onClick={loadConversations}
                  className="mt-4 px-4 py-2 bg-[#008489] text-white rounded-lg text-sm font-medium hover:bg-[#006a6f] transition-colors"
                >
                  Try Again
                </button>
              </div>
            ) : (
              <ConversationList
                conversations={conversations}
                selectedConversationId={selectedConversation?.id}
                onSelectConversation={handleSelectConversation as any}
                currentUserId={currentUserId}
                isLoading={isLoading}
                isProviderView={true}
              />
            )}
          </div>

          {/* Chat View - Full screen on mobile when open */}
          <div
            className={`${
              showChat ? "block" : "hidden md:block"
            } flex-1 flex flex-col absolute md:relative inset-0 z-20 md:z-auto bg-white h-full overflow-hidden min-h-0`}
          >
            {selectedConversation ? (
              <WhatsAppChat
                conversation={selectedConversation}
                currentUserId={currentUserId}
                onBack={handleBack}
                onConversationUpdate={loadConversations}
                messagesEndpoint="/api/provider/conversations"
              />
            ) : (
              <div className="flex flex-col h-full bg-[#f0f2f5] items-center justify-center px-4">
                <div className="text-center p-6 md:p-8 max-w-sm">
                  <div className="w-16 h-16 md:w-20 md:h-20 rounded-full bg-[#008489] mx-auto mb-4 flex items-center justify-center">
                    <svg
                      className="w-8 h-8 md:w-10 md:h-10 text-white"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"
                      />
                    </svg>
                  </div>
                  <p className="text-[#667781] text-sm md:text-base font-medium">Select a conversation</p>
                  <p className="text-[#667781] text-xs md:text-sm mt-1">
                    Choose a customer conversation to start messaging
                  </p>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { PageHeader } from "@/components/provider/PageHeader";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  ArrowUpRight,
  Building2,
  CreditCard,
  ChevronRight,
  Loader2,
  AlertCircle,
} from "lucide-react";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { usePermissions } from "@/hooks/usePermissions";
import { Lock } from "lucide-react";

interface EarningsData {
  total_earnings: number;
  pending_payouts: number;
  available_balance: number;
  minimum_payout_amount?: number;
  this_month: number;
  last_month: number;
  growth_percentage: number;
}

interface PayoutAccount {
  id: string;
  account_name: string;
  account_number_last4: string;
  bank_name: string | null;
  active: boolean;
  created_at: string;
}

interface Payout {
  id: string;
  amount: number;
  currency: string;
  status: string;
  requested_at: string;
  notes?: string | null;
}

export default function FinanceHubPage() {
  const { hasPermission } = usePermissions();
  const canRequestPayout = hasPermission("process_payments");

  const [earnings, setEarnings] = useState<EarningsData | null>(null);
  const [accounts, setAccounts] = useState<PayoutAccount[]>([]);
  const [payouts, setPayouts] = useState<Payout[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showPayoutDialog, setShowPayoutDialog] = useState(false);
  const [payoutAmount, setPayoutAmount] = useState("");
  const [payoutNotes, setPayoutNotes] = useState("");
  const [selectedBankId, setSelectedBankId] = useState<string>("");
  const [isRequestingPayout, setIsRequestingPayout] = useState(false);

  const loadData = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const [financeRes, accountsRes, payoutsRes] = await Promise.all([
        fetcher.get<{ data: { earnings: EarningsData } }>("/api/provider/finance?range=month"),
        fetcher.get<{ data: PayoutAccount[] }>("/api/provider/payout-accounts"),
        fetcher.get<{ data: Payout[] }>("/api/provider/payouts"),
      ]);
      setEarnings(financeRes.data?.earnings ?? null);
      const accts = accountsRes.data || [];
      setAccounts(accts);
      setPayouts(payoutsRes.data || []);
      if (accts.length > 0 && !selectedBankId) {
        setSelectedBankId(accts[0].id);
      }
    } catch (err) {
      const msg = err instanceof FetchError ? err.message : "Failed to load finance data";
      setError(msg);
      console.error("Error loading finance hub:", err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const primaryAccount = accounts.find((a) => a.active) ?? accounts[0];
  const availableBalance = earnings?.available_balance ?? 0;
  const pendingPayouts = earnings?.pending_payouts ?? 0;
  const minimumPayout = earnings?.minimum_payout_amount ?? 100;

  const handleRequestPayout = async () => {
    const amount = parseFloat(payoutAmount);
    if (!payoutAmount || amount <= 0) {
      toast.error("Please enter a valid payout amount");
      return;
    }
    if (amount < minimumPayout) {
      toast.error(`Minimum payout is ZAR ${minimumPayout.toLocaleString()}`);
      return;
    }
    if (amount > availableBalance) {
      toast.error("Insufficient balance for this payout");
      return;
    }
    if (accounts.length === 0) {
      toast.error("Add a bank account first in Settings ΓåÆ Payout Accounts");
      return;
    }

    try {
      setIsRequestingPayout(true);
      await fetcher.post("/api/provider/payouts", {
        amount,
        notes: payoutNotes || undefined,
        bank_account_id: selectedBankId || primaryAccount?.id || undefined,
      });
      toast.success("Payout request submitted");
      setShowPayoutDialog(false);
      setPayoutAmount("");
      setPayoutNotes("");
      loadData();
    } catch (err) {
      const msg = err instanceof FetchError ? err.message : "Failed to request payout";
      toast.error(msg);
    } finally {
      setIsRequestingPayout(false);
    }
  };

  if (isLoading) {
    return (
      <div>
        <PageHeader
          title="Finance Hub"
          subtitle="Earnings and payouts"
          breadcrumbs={[
            { label: "Home", href: "/provider/dashboard" },
            { label: "More", href: "/provider/more" },
            { label: "Finance Hub" },
          ]}
        />
        <LoadingTimeout loadingMessage="Loading finance..." />
      </div>
    );
  }

  return (
    <div>
      <PageHeader
        title="Finance Hub"
        subtitle="Available balance, payouts, and bank account"
        breadcrumbs={[
          { label: "Home", href: "/provider/dashboard" },
          { label: "More", href: "/provider/more" },
          { label: "Finance Hub" },
        ]}
      />

      {error && (
        <Alert className="mb-6 border-amber-200 bg-amber-50">
          <AlertCircle className="h-4 w-4 text-amber-600" />
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}

      <div className="space-y-6">
        {/* Available for payout */}
        <div className="rounded-xl border border-gray-200 bg-white p-5 shadow-sm">
          <h2 className="text-sm font-semibold uppercase tracking-wider text-gray-500 mb-3">
            Available for payout
          </h2>
          <p className="text-3xl font-semibold text-green-600">
            ZAR {(earnings?.available_balance ?? 0).toLocaleString()}
          </p>
          <p className="text-sm text-gray-500 mt-1">
            This is the amount you can request to be paid out to your bank account. Minimum payout: ZAR {minimumPayout.toLocaleString()}.
          </p>
          {pendingPayouts > 0 && (
            <p className="text-sm text-amber-600 mt-2">
              Pending payout requests: ZAR {pendingPayouts.toLocaleString()}
            </p>
          )}
          <div className="mt-4 flex flex-wrap gap-2 items-center">
            {canRequestPayout ? (
              <Button
                className="bg-[#FF0077] hover:bg-[#D60565]"
                onClick={() => setShowPayoutDialog(true)}
                disabled={availableBalance <= 0 || accounts.length === 0}
              >
                <ArrowUpRight className="w-4 h-4 mr-2" />
                Request Payout
              </Button>
            ) : (
              <div className="flex items-center gap-2 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-sm text-amber-800">
                <Lock className="h-4 w-4 flex-shrink-0" />
                <span>You don&apos;t have permission to request payouts. Contact your administrator.</span>
              </div>
            )}
            <Button variant="outline" asChild>
              <Link href="/provider/finance">Full finance & earnings</Link>
            </Button>
          </div>
        </div>

        {/* Bank account ΓÇö clear which one we pay out to */}
        <div className="rounded-xl border border-gray-200 bg-white p-5 shadow-sm">
          <h2 className="text-sm font-semibold uppercase tracking-wider text-gray-500 mb-3 flex items-center gap-2">
            <CreditCard className="h-4 w-4" />
            Payout bank account
          </h2>
          {primaryAccount ? (
            <>
              <p className="text-sm text-gray-600 mb-2">
                Payouts will be sent to this account:
              </p>
              <div className="flex items-center justify-between rounded-lg border border-gray-200 bg-gray-50 p-4">
                <div className="flex items-center gap-3">
                  <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-[#FF0077]/10 text-[#FF0077]">
                    <Building2 className="h-5 w-5" />
                  </div>
                  <div>
                    <p className="font-medium text-gray-900">{primaryAccount.account_name}</p>
                    <p className="text-sm text-gray-500">
                      ****{primaryAccount.account_number_last4}
                      {primaryAccount.bank_name ? ` ┬╖ ${primaryAccount.bank_name}` : ""}
                    </p>
                  </div>
                </div>
                <span className="rounded-full bg-green-100 px-2.5 py-0.5 text-xs font-medium text-green-800">
                  Primary
                </span>
              </div>
              {accounts.length > 1 && (
                <p className="text-xs text-gray-500 mt-2">
                  You have {accounts.length} bank accounts. You can choose which to use when requesting a payout.
                </p>
              )}
              <Button variant="outline" size="sm" className="mt-4" asChild>
                <Link href="/provider/settings/payout-accounts">
                  Manage bank accounts
                  <ChevronRight className="ml-1 h-4 w-4" />
                </Link>
              </Button>
            </>
          ) : (
            <Alert className="border-amber-200 bg-amber-50">
              <AlertCircle className="h-4 w-4 text-amber-600" />
              <AlertDescription>
                <p className="font-medium text-gray-900">No bank account added</p>
                <p className="text-sm text-gray-600 mt-1">
                  Add a bank account to receive payouts. Request payout will be available after you add one.
                </p>
                <Button size="sm" className="mt-3 bg-[#FF0077] hover:bg-[#D60565]" asChild>
                  <Link href="/provider/settings/payout-accounts">Add bank account</Link>
                </Button>
              </AlertDescription>
            </Alert>
          )}
        </div>

        {/* Payout history */}
        {payouts.length > 0 && (
          <div className="rounded-xl border border-gray-200 bg-white p-5 shadow-sm">
            <h2 className="text-sm font-semibold uppercase tracking-wider text-gray-500 mb-3">
              Recent payout requests
            </h2>
            <ul className="space-y-3">
              {payouts.slice(0, 10).map((p) => (
                <li
                  key={p.id}
                  className="flex items-center justify-between py-3 border-b border-gray-100 last:border-0"
                >
                  <div>
                    <p className="font-medium">
                      {p.currency} {p.amount.toLocaleString()}
                    </p>
                    <p className="text-sm text-gray-500">
                      {new Date(p.requested_at).toLocaleDateString("en-ZA", {
                        dateStyle: "medium",
                      })}
                    </p>
                  </div>
                  <span
                    className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${
                      p.status === "completed"
                        ? "bg-green-100 text-green-800"
                        : p.status === "pending" || p.status === "processing"
                        ? "bg-amber-100 text-amber-800"
                        : p.status === "failed"
                        ? "bg-red-100 text-red-800"
                        : "bg-gray-100 text-gray-800"
                    }`}
                  >
                    {p.status}
                  </span>
                </li>
              ))}
            </ul>
            <Button variant="ghost" size="sm" className="mt-2" asChild>
              <Link href="/provider/finance">View all on Finance page</Link>
            </Button>
          </div>
        )}
      </div>

      {/* Request Payout Dialog (only open when user has permission) */}
      <Dialog open={showPayoutDialog && canRequestPayout} onOpenChange={setShowPayoutDialog}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Request Payout</DialogTitle>
            <DialogDescription>
              Amount will be sent to your selected bank account. Processing times depend on your bank.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div>
              <Label>Available for payout</Label>
              <Input
                value={`ZAR ${availableBalance.toLocaleString()}`}
                disabled
                className="mt-1 bg-gray-50"
              />
            </div>
            <div>
              <Label htmlFor="payout-amount">Amount (ZAR) * ΓÇö min ZAR {minimumPayout.toLocaleString()}</Label>
              <Input
                id="payout-amount"
                type="number"
                min={minimumPayout}
                max={availableBalance}
                step="0.01"
                value={payoutAmount}
                onChange={(e) => setPayoutAmount(e.target.value)}
                placeholder="0.00"
                className="mt-1"
              />
              {payoutAmount && parseFloat(payoutAmount) < minimumPayout && (
                <p className="text-sm text-red-600 mt-1">Below minimum payout (ZAR {minimumPayout.toLocaleString()})</p>
              )}
              {payoutAmount && parseFloat(payoutAmount) > availableBalance && (
                <p className="text-sm text-red-600 mt-1">Amount exceeds available balance</p>
              )}
            </div>
            {accounts.length > 1 && (
              <div>
                <Label>Pay out to</Label>
                <Select
                  value={selectedBankId || primaryAccount?.id}
                  onValueChange={setSelectedBankId}
                >
                  <SelectTrigger className="mt-1">
                    <SelectValue placeholder="Select account" />
                  </SelectTrigger>
                  <SelectContent>
                    {accounts.map((a) => (
                      <SelectItem key={a.id} value={a.id}>
                        {a.account_name} ****{a.account_number_last4}
                        {a.bank_name ? ` (${a.bank_name})` : ""}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <p className="text-xs text-gray-500 mt-1">Payouts will be sent to this account</p>
              </div>
            )}
            <div>
              <Label htmlFor="payout-notes">Notes (optional)</Label>
              <Textarea
                id="payout-notes"
                value={payoutNotes}
                onChange={(e) => setPayoutNotes(e.target.value)}
                placeholder="Any notes for this request"
                className="mt-1"
                rows={2}
              />
            </div>
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setShowPayoutDialog(false);
                setPayoutAmount("");
                setPayoutNotes("");
              }}
            >
              Cancel
            </Button>
            <Button
              onClick={handleRequestPayout}
              disabled={
                isRequestingPayout ||
                !payoutAmount ||
                parseFloat(payoutAmount) < minimumPayout ||
                parseFloat(payoutAmount) > availableBalance
              }
              className="bg-[#FF0077] hover:bg-[#D60565]"
            >
              {isRequestingPayout ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Submitting...
                </>
              ) : (
                "Request Payout"
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useAuth } from "@/providers/AuthProvider";
import {
  Bell,
  Calendar,
  DollarSign,
  User,
  Clock,
  CheckCircle2,
  AlertTriangle,
  Package,
  Users,
  Settings,
  FileText,
  Zap,
} from "lucide-react";
import { PageHeader } from "@/components/provider/PageHeader";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { fetcher } from "@/lib/http/fetcher";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";

interface Notification {
  id: string;
  type: string;
  title: string;
  message: string;
  timestamp: string;
  link?: string;
  priority: "low" | "medium" | "high";
  read: boolean;
  metadata?: Record<string, any>;
}

const getNotificationIcon = (type: string) => {
  switch (type) {
    case "appointment_reminder":
    case "appointment_cancelled":
    case "appointment_rescheduled":
    case "new_appointment":
      return Calendar;
    case "payment_received":
    case "payout_processed":
    case "refund_processed":
      return DollarSign;
    case "new_client":
    case "client_message":
      return User;
    case "staff_clock_in":
    case "staff_clock_out":
    case "shift_reminder":
      return Clock;
    case "service_booking":
    case "product_order":
      return Package;
    case "team_member_added":
    case "team_member_updated":
      return Users;
    case "system_update":
    case "maintenance":
      return Settings;
    case "report_ready":
    case "document_ready":
      return FileText;
    case "payment_failed":
    case "subscription_expiring":
      return AlertTriangle;
    case "account_verification":
      return CheckCircle2;
    case "high_priority":
      return Zap;
    default:
      return Bell;
  }
};

const getPriorityColor = (priority: string) => {
  switch (priority) {
    case "high":
      return "text-red-600 bg-red-50 border-red-200";
    case "medium":
      return "text-yellow-600 bg-yellow-50 border-yellow-200";
    default:
      return "text-blue-600 bg-blue-50 border-blue-200";
  }
};

const formatTimeAgo = (timestamp: string) => {
  const now = new Date();
  const time = new Date(timestamp);
  const diffInSeconds = Math.floor((now.getTime() - time.getTime()) / 1000);

  if (diffInSeconds < 60) return "Just now";
  if (diffInSeconds < 3600) return `${Math.floor(diffInSeconds / 60)}m ago`;
  if (diffInSeconds < 86400) return `${Math.floor(diffInSeconds / 3600)}h ago`;
  if (diffInSeconds < 604800) return `${Math.floor(diffInSeconds / 86400)}d ago`;
  return time.toLocaleDateString();
};

export default function ProviderNotificationsPage() {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [totalUnread, setTotalUnread] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const router = useRouter();
  const { user } = useAuth();

  const loadNotifications = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data?: { notifications: Notification[]; total_unread: number } }>(
        "/api/provider/notifications?limit=100"
      );
      const data = response.data ?? response;
      setNotifications((data as any).notifications || []);
      setTotalUnread((data as any).total_unread || 0);
    } catch (error) {
      console.error("Failed to load notifications:", error);
      toast.error("Failed to load notifications");
      setNotifications([]);
      setTotalUnread(0);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (user?.id) {
      loadNotifications();
    } else {
      setIsLoading(false);
    }
  }, [user?.id]);

  const handleNotificationClick = async (notification: Notification) => {
    if (!notification.read) {
      try {
        await fetcher.post(`/api/provider/notifications/${notification.id}/read`);
        setNotifications((prev) =>
          prev.map((n) => (n.id === notification.id ? { ...n, read: true } : n))
        );
        setTotalUnread((prev) => Math.max(0, prev - 1));
      } catch (error) {
        console.error("Failed to mark notification as read:", error);
      }
    }
    if (notification.link) {
      router.push(notification.link);
    }
  };

  const handleMarkAllRead = async () => {
    try {
      await fetcher.post("/api/provider/notifications/mark-all-read");
      setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
      setTotalUnread(0);
      toast.success("All notifications marked as read");
    } catch (error) {
      console.error("Failed to mark all as read:", error);
      toast.error("Failed to mark all as read");
    }
  };

  return (
    <div className="space-y-6">
      <PageHeader
        title="Notifications"
        subtitle="View and manage your notifications"
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Notifications" },
        ]}
      />

      <SectionCard>
        {isLoading ? (
          <div className="py-12">
            <LoadingTimeout loadingMessage="Loading notifications..." />
          </div>
        ) : notifications.length === 0 ? (
          <div className="py-12 text-center text-gray-500">
            <CheckCircle2 className="w-12 h-12 mx-auto mb-4 text-gray-400" />
            <p className="text-base font-medium mb-2">No new notifications</p>
            <Link
              href="/provider/settings/notifications"
              className="text-sm text-[#FF0077] hover:underline"
            >
              Manage notifications
            </Link>
          </div>
        ) : (
          <>
            <div className="flex items-center justify-between mb-4">
              <p className="text-sm text-gray-600">
                {totalUnread > 0 ? `${totalUnread} unread` : "All caught up"}
              </p>
              {totalUnread > 0 && (
                <Button variant="outline" size="sm" onClick={handleMarkAllRead}>
                  Mark all read
                </Button>
              )}
            </div>
            <div className="divide-y">
              {notifications.map((notification) => {
                const Icon = getNotificationIcon(notification.type);
                return (
                  <button
                    key={notification.id}
                    onClick={() => handleNotificationClick(notification)}
                    className={cn(
                      "w-full text-left p-4 hover:bg-gray-50 transition-colors",
                      !notification.read && "bg-blue-50/50"
                    )}
                  >
                    <div className="flex items-start gap-3">
                      <div
                        className={cn(
                          "p-2 rounded-lg border flex-shrink-0",
                          getPriorityColor(notification.priority)
                        )}
                      >
                        <Icon className="w-4 h-4" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between gap-2 mb-1">
                          <p
                            className={cn(
                              "font-medium text-sm text-gray-900",
                              !notification.read && "font-semibold"
                            )}
                          >
                            {notification.title}
                          </p>
                          {!notification.read && (
                            <span className="w-2 h-2 bg-[#FF0077] rounded-full flex-shrink-0 mt-1.5" />
                          )}
                        </div>
                        <p className="text-sm text-gray-600 line-clamp-2 mb-1">{notification.message}</p>
                        <span className="text-xs text-gray-500">{formatTimeAgo(notification.timestamp)}</span>
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>
          </>
        )}
      </SectionCard>

      <div className="text-center">
        <Link
          href="/provider/settings/notifications"
          className="text-sm text-[#FF0077] hover:underline"
        >
          Manage notifications
        </Link>
      </div>
    </div>
  );
}

