"use client";

import React, { useState, useEffect } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { PaymentTransaction, FilterParams, PaginationParams } from "@/lib/provider-portal/types";
import { PageHeader } from "@/components/provider/PageHeader";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Money } from "@/components/provider-portal/Money";
import { Search, Filter, MoreVertical } from "lucide-react";
import Pagination from "@/components/ui/pagination";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { SectionCard } from "@/components/provider/SectionCard";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

export default function ProviderPayments() {
  const [payments, setPayments] = useState<PaymentTransaction[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [dateRange, setDateRange] = useState<string>("month");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);

  useEffect(() => {
    loadPayments();
  }, [page, dateRange]);

  const loadPayments = async () => {
    try {
      setIsLoading(true);
      const filters: FilterParams = {
        search: searchQuery || undefined,
      };

      if (dateRange === "month") {
        const now = new Date();
        filters.date_from = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split("T")[0];
        filters.date_to = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split("T")[0];
      }

      const pagination: PaginationParams = { page, limit: 20 };
      const response = await providerApi.listPayments(filters, pagination);
      setPayments(response.data);
      setTotalPages(response.total_pages);
    } catch (error) {
      console.error("Failed to load payments:", error);
    } finally {
      setIsLoading(false);
    }
  };

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading payments..." />;
  }

  return (
    <div>
      <PageHeader
        title="Payments"
        subtitle="View all payment transactions"
        actions={
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline">
                <MoreVertical className="w-4 h-4 mr-2" />
                Options
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent>
              <DropdownMenuItem>Export</DropdownMenuItem>
              <DropdownMenuItem>Print</DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        }
      />

      {/* Filters */}
      <div className="mb-6 flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
          <Input
            placeholder="Search payments..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10"
          />
        </div>
        <Select value={dateRange} onValueChange={setDateRange}>
          <SelectTrigger className="w-full md:w-48">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="today">Today</SelectItem>
            <SelectItem value="week">This Week</SelectItem>
            <SelectItem value="month">Month to Date</SelectItem>
            <SelectItem value="custom">Custom Range</SelectItem>
          </SelectContent>
        </Select>
        <Button variant="outline">
          <Filter className="w-4 h-4 mr-2" />
          Filter
        </Button>
      </div>

      {/* Payments List */}
      {payments.length === 0 ? (
        <SectionCard className="p-12 text-center">
          <EmptyState
            title="No payment transactions yet"
            description="Payment transactions will appear here"
            />
          </SectionCard>
      ) : (
        <>
          <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Ref #</TableHead>
                  <TableHead>Payment Date</TableHead>
                  <TableHead>Duration</TableHead>
                  <TableHead>Team Member</TableHead>
                  <TableHead>Method</TableHead>
                  <TableHead className="text-right">Amount</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {payments.map((payment) => (
                  <TableRow key={payment.id}>
                    <TableCell className="font-medium">{payment.ref_number}</TableCell>
                    <TableCell>{new Date(payment.payment_date).toLocaleDateString()}</TableCell>
                    <TableCell>
                      {payment.appointment_duration ? `${payment.appointment_duration} min` : "-"}
                    </TableCell>
                    <TableCell>{payment.team_member_name || "-"}</TableCell>
                    <TableCell className="capitalize">{payment.method.replace("_", " ")}</TableCell>
                    <TableCell className="text-right font-semibold">
                      <Money amount={payment.amount} />
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>

          {totalPages > 1 && (
            <div className="mt-4">
              <Pagination
                currentPage={page}
                totalPages={totalPages}
                onPageChange={setPage}
              />
            </div>
          )}
        </>
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { RecurringAppointment, RecurrencePattern, FilterParams, PaginationParams } from "@/lib/provider-portal/types";
import { PageHeader } from "@/components/provider/PageHeader";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Search, Calendar, Repeat, Edit, Trash2, MoreVertical } from "lucide-react";
import Pagination from "@/components/ui/pagination";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { SectionCard } from "@/components/provider/SectionCard";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Money } from "@/components/provider-portal/Money";
import { toast } from "sonner";

export default function RecurringAppointmentsPage() {
  const [appointments, setAppointments] = useState<RecurringAppointment[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [selectedAppointment, setSelectedAppointment] = useState<RecurringAppointment | null>(null);
  const [editMode, setEditMode] = useState<"single" | "series">("single");

  const loadAppointments = useCallback(async () => {
    try {
      setIsLoading(true);
      const filters: FilterParams = {
        search: searchQuery || undefined,
      };

      const pagination: PaginationParams = { page, limit: 20 };
      const response = await providerApi.listRecurringAppointments(filters, pagination);
      setAppointments(response.data);
      setTotalPages(response.total_pages);
    } catch (error) {
      console.error("Failed to load recurring appointments:", error);
      toast.error("Failed to load recurring appointments");
    } finally {
      setIsLoading(false);
    }
  }, [page, searchQuery]);

  useEffect(() => {
    loadAppointments();
  }, [loadAppointments]);

  const handleSearch = () => {
    setPage(1);
    loadAppointments();
  };

  const handleEdit = (appointment: RecurringAppointment, mode: "single" | "series") => {
    setSelectedAppointment(appointment);
    setEditMode(mode);
    setIsEditDialogOpen(true);
  };

  const handleDelete = async (appointment: RecurringAppointment, deleteSeries: boolean) => {
    const message = deleteSeries
      ? "Are you sure you want to delete this entire recurring series?"
      : "Are you sure you want to delete this appointment instance?";
    
    if (!confirm(message)) return;

    try {
      await providerApi.deleteRecurringAppointment(appointment.id, deleteSeries);
      toast.success(deleteSeries ? "Series deleted" : "Appointment deleted");
      loadAppointments();
    } catch (error) {
      console.error("Failed to delete appointment:", error);
      toast.error("Failed to delete appointment");
    }
  };

  const getPatternLabel = (pattern: string) => {
    switch (pattern) {
      case "daily":
        return "Daily";
      case "weekly":
        return "Weekly";
      case "biweekly":
        return "Bi-weekly";
      case "monthly":
        return "Monthly";
      default:
        return pattern;
    }
  };

  const getStatusColor = (status: RecurringAppointment["status"]) => {
    switch (status) {
      case "booked":
        return "bg-blue-100 text-blue-800";
      case "started":
        return "bg-yellow-100 text-yellow-800";
      case "completed":
        return "bg-green-100 text-green-800";
      case "cancelled":
        return "bg-gray-100 text-gray-800";
    }
  };

  // Group appointments by series
  const _groupedBySeries = appointments.reduce((acc, apt) => {
    if (!acc[apt.series_id]) {
      acc[apt.series_id] = [];
    }
    acc[apt.series_id].push(apt);
    return acc;
  }, {} as Record<string, RecurringAppointment[]>);

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading recurring appointments..." />;
  }

  return (
    <div>
      <PageHeader
        title="Recurring Appointments"
        subtitle="Manage your repeating appointments and series"
      />

      {/* Filters */}
      <div className="mb-6 flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
          <Input
            placeholder="Search by client or service..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && handleSearch()}
            className="pl-10"
          />
        </div>
        <Button onClick={handleSearch} className="bg-[#FF0077] hover:bg-[#D60565]">
          Search
        </Button>
      </div>

      {/* Appointments List */}
      {appointments.length === 0 ? (
        <SectionCard className="p-12">
          <EmptyState
            title="No recurring appointments"
            description="Create recurring appointments from the calendar or appointment dialog"
          />
        </SectionCard>
      ) : (
        <>
          <SectionCard className="p-0 overflow-hidden">
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Client</TableHead>
                    <TableHead>Service</TableHead>
                    <TableHead>Team Member</TableHead>
                    <TableHead>Schedule</TableHead>
                    <TableHead>Pattern</TableHead>
                    <TableHead>Next Date</TableHead>
                    <TableHead>Price</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {appointments.map((apt) => (
                    <TableRow key={apt.id}>
                      <TableCell className="font-medium">{apt.client_name}</TableCell>
                      <TableCell>{apt.service_name}</TableCell>
                      <TableCell>{apt.team_member_name}</TableCell>
                      <TableCell>
                        <div className="flex items-center gap-1 text-sm">
                          <Calendar className="w-3 h-3" />
                          <span>{apt.scheduled_date}</span>
                          <span className="text-gray-400">@</span>
                          <span>{apt.scheduled_time}</span>
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-1">
                          <Repeat className="w-3 h-3 text-gray-400" />
                          <span>{getPatternLabel(apt.recurrence_rule.pattern)}</span>
                        </div>
                      </TableCell>
                      <TableCell>
                        {new Date(apt.scheduled_date) >= new Date()
                          ? new Date(apt.scheduled_date).toLocaleDateString()
                          : "Past"}
                      </TableCell>
                      <TableCell>
                        <Money amount={apt.price} />
                      </TableCell>
                      <TableCell>
                        <Badge className={getStatusColor(apt.status)}>
                          {apt.status}
                        </Badge>
                        {apt.is_exception && (
                          <Badge variant="outline" className="ml-2">
                            Modified
                          </Badge>
                        )}
                      </TableCell>
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm">
                              <MoreVertical className="w-4 h-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleEdit(apt, "single")}>
                              <Edit className="w-4 h-4 mr-2" />
                              Edit This Instance
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleEdit(apt, "series")}>
                              <Edit className="w-4 h-4 mr-2" />
                              Edit Entire Series
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem
                              onClick={() => handleDelete(apt, false)}
                              className="text-red-600"
                            >
                              <Trash2 className="w-4 h-4 mr-2" />
                              Delete This Instance
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              onClick={() => handleDelete(apt, true)}
                              className="text-red-600"
                            >
                              <Trash2 className="w-4 h-4 mr-2" />
                              Delete Entire Series
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </SectionCard>

          {totalPages > 1 && (
            <div className="mt-4">
              <Pagination
                currentPage={page}
                totalPages={totalPages}
                onPageChange={setPage}
              />
            </div>
          )}
        </>
      )}

      {/* Edit Dialog */}
      {selectedAppointment && (
        <RecurringAppointmentEditDialog
          open={isEditDialogOpen}
          onOpenChange={setIsEditDialogOpen}
          appointment={selectedAppointment}
          editMode={editMode}
          onSuccess={loadAppointments}
        />
      )}
    </div>
  );
}

// Edit Recurring Appointment Dialog
function RecurringAppointmentEditDialog({
  open,
  onOpenChange,
  appointment,
  editMode,
  onSuccess,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  appointment: RecurringAppointment;
  editMode: "single" | "series";
  onSuccess: () => void;
}) {
  const [formData, setFormData] = useState({
    scheduled_date: appointment.scheduled_date,
    scheduled_time: appointment.scheduled_time,
    duration_minutes: appointment.duration_minutes,
    price: appointment.price,
    notes: appointment.notes || "",
    recurrence_pattern: appointment.recurrence_rule.pattern,
    recurrence_end_date: appointment.recurrence_rule.end_date || "",
    recurrence_occurrences: appointment.recurrence_rule.occurrences || undefined,
  });
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      if (editMode === "series") {
        await providerApi.updateRecurringSeries(appointment.series_id, {
          scheduled_date: formData.scheduled_date,
          scheduled_time: formData.scheduled_time,
          duration_minutes: formData.duration_minutes,
          price: formData.price,
          notes: formData.notes,
          recurrence_rule: {
            pattern: formData.recurrence_pattern as any,
            interval: formData.recurrence_pattern === "biweekly" ? 2 : 1,
            end_date: formData.recurrence_end_date || undefined,
            occurrences: formData.recurrence_occurrences,
          },
        });
        toast.success("Series updated");
      } else {
        await providerApi.updateRecurringAppointment(appointment.id, {
          scheduled_date: formData.scheduled_date,
          scheduled_time: formData.scheduled_time,
          duration_minutes: formData.duration_minutes,
          price: formData.price,
          notes: formData.notes,
        });
        toast.success("Appointment updated");
      }
      onSuccess();
      onOpenChange(false);
    } catch (error) {
      console.error("Failed to update appointment:", error);
      toast.error("Failed to update appointment");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {editMode === "series" ? "Edit Recurring Series" : "Edit Appointment Instance"}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="p-3 bg-blue-50 rounded-lg text-sm text-blue-800">
            {editMode === "series"
              ? "Changes will apply to all future appointments in this series."
              : "This will create an exception for this specific appointment."}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="scheduled_date">Date</Label>
              <Input
                id="scheduled_date"
                type="date"
                value={formData.scheduled_date}
                onChange={(e) =>
                  setFormData({ ...formData, scheduled_date: e.target.value })
                }
                required
              />
            </div>
            <div>
              <Label htmlFor="scheduled_time">Time</Label>
              <Input
                id="scheduled_time"
                type="time"
                value={formData.scheduled_time}
                onChange={(e) =>
                  setFormData({ ...formData, scheduled_time: e.target.value })
                }
                required
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="duration_minutes">Duration (minutes)</Label>
              <Input
                id="duration_minutes"
                type="number"
                value={formData.duration_minutes}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    duration_minutes: parseInt(e.target.value) || 60,
                  })
                }
                min={15}
                step={15}
              />
            </div>
            <div>
              <Label htmlFor="price">Price (R)</Label>
              <Input
                id="price"
                type="number"
                value={formData.price}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    price: parseFloat(e.target.value) || 0,
                  })
                }
                min={0}
                step={0.01}
              />
            </div>
          </div>

          {editMode === "series" && (
            <>
              <div>
                <Label htmlFor="recurrence_pattern">Recurrence Pattern</Label>
                <Select
                  value={formData.recurrence_pattern}
                  onValueChange={(value) =>
                    setFormData({ ...formData, recurrence_pattern: value as RecurrencePattern })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="daily">Daily</SelectItem>
                    <SelectItem value="weekly">Weekly</SelectItem>
                    <SelectItem value="biweekly">Bi-weekly</SelectItem>
                    <SelectItem value="monthly">Monthly</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="recurrence_end_date">End Date (Optional)</Label>
                  <Input
                    id="recurrence_end_date"
                    type="date"
                    value={formData.recurrence_end_date}
                    onChange={(e) =>
                      setFormData({ ...formData, recurrence_end_date: e.target.value })
                    }
                  />
                </div>
                <div>
                  <Label htmlFor="recurrence_occurrences">Number of Occurrences</Label>
                  <Input
                    id="recurrence_occurrences"
                    type="number"
                    min={1}
                    value={formData.recurrence_occurrences || ""}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        recurrence_occurrences: parseInt(e.target.value) || undefined,
                      })
                    }
                    placeholder="Leave empty for no limit"
                  />
                </div>
              </div>
            </>
          )}

          <div>
            <Label htmlFor="notes">Notes</Label>
            <Textarea
              id="notes"
              value={formData.notes}
              onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
              rows={3}
            />
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isLoading}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isLoading}
              className="bg-[#FF0077] hover:bg-[#D60565]"
            >
              {isLoading ? "Saving..." : "Update"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { PageHeader } from "@/components/provider/PageHeader";
import { ReportFilters, DateRange } from "../../components/ReportFilters";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Download, XCircle, DollarSign, AlertTriangle } from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import { subDays, format } from "date-fns";
import { ReportSkeleton } from "../../components/ReportSkeleton";
import { EmptyReportState } from "../../components/EmptyReportState";
import { exportToCSV, formatReportDataForExport } from "../../utils/export";

interface CancellationsData {
  totalCancelled: number;
  totalBookings: number;
  cancellationRate: number;
  lostRevenue: number;
  cancellationReasons: Array<{
    reason: string;
    count: number;
    percentage: number;
  }>;
  dailyBreakdown: Array<{
    date: string;
    count: number;
  }>;
  recentCancellations: Array<{
    id: string;
    total_amount: number;
    scheduled_at: string;
    cancelled_at: string;
    cancellation_reason: string;
    users: {
      full_name: string;
      email: string;
    } | null;
  }>;
}

export default function CancellationsReport() {
  const [dateRange, setDateRange] = useState<DateRange>({
    from: subDays(new Date(), 30),
    to: new Date(),
  });
  const [data, setData] = useState<CancellationsData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadReport();
  }, [dateRange]);

  const loadReport = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      if (dateRange.from) {
        params.append("from", dateRange.from.toISOString());
      }
      if (dateRange.to) {
        params.append("to", dateRange.to.toISOString());
      }

      const response = await fetcher.get<{ data: CancellationsData }>(
        `/api/provider/reports/bookings/cancellations?${params.toString()}`
      );
      setData(response.data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load report");
      console.error("Error loading cancellations:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleReset = () => {
    setDateRange({
      from: subDays(new Date(), 30),
      to: new Date(),
    });
  };

  const handleExport = () => {
    if (!data) return;
    const exportData = formatReportDataForExport(data, "cancellations");
    exportToCSV(exportData, "cancellations-report");
  };

  if (isLoading) {
    return (
      <SettingsDetailLayout
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Reports", href: "/provider/reports" },
          { label: "Cancellations" },
        ]}
      >
        <ReportSkeleton />
      </SettingsDetailLayout>
    );
  }

  if (error || !data) {
    return (
      <SettingsDetailLayout
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Reports", href: "/provider/reports" },
          { label: "Cancellations" },
        ]}
      >
        <EmptyReportState
          title="Failed to load report"
          description={error || "Unable to load cancellations data"}
        />
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      breadcrumbs={[
        { label: "Home", href: "/" },
        { label: "Provider", href: "/provider" },
        { label: "Reports", href: "/provider/reports" },
        { label: "Cancellations" },
      ]}
      showCloseButton={false}
    >
      <div className="space-y-6">
        <PageHeader
          title="Cancellations"
          subtitle="Track booking cancellations and lost revenue"
          actions={
            <Button variant="outline" onClick={handleExport}>
              <Download className="w-4 h-4 mr-2" />
              Export
            </Button>
          }
        />

        <ReportFilters
          dateRange={dateRange}
          onDateRangeChange={setDateRange}
          onReset={handleReset}
        />

        {/* Summary Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <Card className="border-gray-200">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium text-gray-600">Total Cancelled</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center justify-between">
                <p className="text-2xl font-semibold text-gray-900">{data.totalCancelled}</p>
                <XCircle className="w-5 h-5 text-red-600" />
              </div>
            </CardContent>
          </Card>

          <Card className="border-gray-200">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium text-gray-600">Cancellation Rate</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center justify-between">
                <p className="text-2xl font-semibold text-gray-900">
                  {data.cancellationRate.toFixed(1)}%
                </p>
                <AlertTriangle className="w-5 h-5 text-orange-600" />
              </div>
            </CardContent>
          </Card>

          <Card className="border-gray-200">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium text-gray-600">Lost Revenue</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center justify-between">
                <p className="text-2xl font-semibold text-gray-900">
                  ZAR {data.lostRevenue.toLocaleString()}
                </p>
                <DollarSign className="w-5 h-5 text-red-600" />
              </div>
            </CardContent>
          </Card>

          <Card className="border-gray-200">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium text-gray-600">Total Bookings</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center justify-between">
                <p className="text-2xl font-semibold text-gray-900">{data.totalBookings}</p>
                <XCircle className="w-5 h-5 text-gray-600" />
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Cancellation Reasons */}
        <Card className="border-gray-200">
          <CardHeader>
            <CardTitle>Cancellation Reasons</CardTitle>
          </CardHeader>
          <CardContent>
            {data.cancellationReasons.length === 0 ? (
              <EmptyReportState title="No cancellation reasons" description="No cancellation reasons available." />
            ) : (
              <div className="space-y-3">
                {data.cancellationReasons.map((reason) => (
                  <div
                    key={reason.reason}
                    className="flex items-center justify-between p-3 rounded-lg border border-gray-200"
                  >
                    <div>
                      <p className="font-medium text-gray-900">{reason.reason}</p>
                      <p className="text-sm text-gray-600">
                        {reason.percentage.toFixed(1)}% of cancellations
                      </p>
                    </div>
                    <p className="font-semibold text-gray-900">{reason.count} cancellations</p>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Recent Cancellations */}
        <Card className="border-gray-200">
          <CardHeader>
            <CardTitle>Recent Cancellations</CardTitle>
          </CardHeader>
          <CardContent>
            {data.recentCancellations.length === 0 ? (
              <EmptyReportState title="No cancellations" description="No cancellations in the selected period." />
            ) : (
              <div className="space-y-3">
                {data.recentCancellations.map((booking) => (
                  <div
                    key={booking.id}
                    className="flex items-center justify-between p-3 rounded-lg border border-gray-200"
                  >
                    <div>
                      <p className="font-medium text-gray-900">
                        {booking.users?.full_name || "Unknown Client"}
                      </p>
                      <p className="text-sm text-gray-600">
                        {format(new Date(booking.scheduled_at), "MMM dd, yyyy 'at' h:mm a")}
                      </p>
                      {booking.cancellation_reason && (
                        <p className="text-xs text-gray-500 mt-1">
                          Reason: {booking.cancellation_reason}
                        </p>
                      )}
                    </div>
                    <div className="text-right">
                      <p className="font-semibold text-gray-900">
                        ZAR {Number(booking.total_amount || 0).toLocaleString()}
                      </p>
                      <p className="text-xs text-gray-500">
                        {format(new Date(booking.cancelled_at || booking.scheduled_at), "MMM dd")}
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </SettingsDetailLayout>
  );
}

