                  {data.noShowRate.toFixed(1)}%
                </p>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Status Breakdown */}
        {data.bookingsByStatus && data.bookingsByStatus.length > 0 ? (
          <Card className="border-gray-200">
            <CardHeader>
              <CardTitle>Booking Status Breakdown</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {data.bookingsByStatus.map((item) => {
                const config = statusConfig[item.status as keyof typeof statusConfig];
                const Icon = config?.icon || Clock;
                const label = config?.label || item.status;

                return (
                  <div
                    key={item.status}
                    className="flex items-center justify-between p-4 bg-gray-50 rounded-lg"
                  >
                    <div className="flex items-center gap-3">
                      <div className={`p-2 rounded-lg ${config?.color || "bg-gray-100"}`}>
                        <Icon className="w-5 h-5" />
                      </div>
                      <div>
                        <p className="text-sm font-medium text-gray-900">{label}</p>
                        <p className="text-xs text-gray-600">
                          {item.count} booking{item.count !== 1 ? "s" : ""}
                        </p>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-sm font-semibold text-gray-900">
                        {item.percentage.toFixed(1)}%
                      </p>
                      <p className="text-xs text-gray-600">
                        ZAR {item.revenue.toLocaleString()}
                      </p>
                    </div>
                  </div>
                  );
                })}
              </div>
            </CardContent>
          </Card>
        ) : (
          <Card className="border-gray-200">
            <CardHeader>
              <CardTitle>Booking Status Breakdown</CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-sm text-gray-600 text-center py-8">
                No booking data available for the selected period.
              </p>
            </CardContent>
          </Card>
        )}
      </div>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { PageHeader } from "@/components/provider/PageHeader";
import { ReportFilters, DateRange } from "../../components/ReportFilters";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Download, Calendar, DollarSign, TrendingUp } from "lucide-react";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { subDays } from "date-fns";
import { ReportSkeleton } from "../../components/ReportSkeleton";
import { EmptyReportState } from "../../components/EmptyReportState";
import { SubscriptionGate } from "@/components/provider/SubscriptionGate";
import { RevenueChart } from "../../components/RevenueChart";
import { exportToCSV, exportToPDF, formatReportDataForExport } from "../../utils/export";

interface BookingSummaryData {
  totalBookings: number;
  totalRevenue: number;
  averageBookingValue: number;
  statusBreakdown: Array<{
    status: string;
    count: number;
    revenue: number;
    percentage: number;
  }>;
  dailyBookings: Array<{
    date: string;
    count: number;
    revenue: number;
  }>;
  topServices: Array<{
    serviceName: string;
    bookings: number;
    revenue: number;
  }>;
}

export default function BookingSummaryReport() {
  const [dateRange, setDateRange] = useState<DateRange>({
    from: subDays(new Date(), 30),
    to: new Date(),
  });
  const [data, setData] = useState<BookingSummaryData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isSubscriptionRequired, setIsSubscriptionRequired] = useState(false);

  useEffect(() => {
    loadReport();
  }, [dateRange]);

  const loadReport = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      if (dateRange.from) {
        params.append("from", dateRange.from.toISOString());
      }
      if (dateRange.to) {
        params.append("to", dateRange.to.toISOString());
      }

      const response = await fetcher.get<{ data: BookingSummaryData }>(
        `/api/provider/reports/bookings/summary?${params.toString()}`
      );
      setData(response.data);
    } catch (err) {
      if (err instanceof FetchError && err.code === "SUBSCRIPTION_REQUIRED") {
        setIsSubscriptionRequired(true);
        setError(null);
      } else {
        setError(err instanceof Error ? err.message : "Failed to load report");
        setIsSubscriptionRequired(false);
      }
      console.error("Error loading booking summary:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleReset = () => {
    setDateRange({
      from: subDays(new Date(), 30),
      to: new Date(),
    });
  };

  const handleExport = (format: "csv" | "pdf" = "csv") => {
    if (!data) return;
    if (format === "csv") {
      const exportData = formatReportDataForExport(data, "booking-summary");
      exportToCSV(exportData, "booking-summary-report");
    } else {
      exportToPDF("booking-summary-report", "booking-summary-report", "Booking Summary Report");
    }
  };

  const getStatusColor = (status: string) => {
    switch (status.toLowerCase()) {
      case "completed":
        return "bg-green-100 text-green-800";
      case "confirmed":
        return "bg-blue-100 text-blue-800";
      case "cancelled":
        return "bg-red-100 text-red-800";
      case "no_show":
        return "bg-orange-100 text-orange-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  if (isLoading) {
    return (
      <SettingsDetailLayout
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Reports", href: "/provider/reports" },
          { label: "Booking Summary" },
        ]}
      >
        <ReportSkeleton />
      </SettingsDetailLayout>
    );
  }

  if (isSubscriptionRequired) {
    return (
      <SettingsDetailLayout
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Reports", href: "/provider/reports" },
          { label: "Booking Summary" },
        ]}
      >
        <div className="space-y-6">
          <PageHeader
            title="Booking Summary"
            subtitle="Analyze booking patterns and client behavior"
          />
          <SubscriptionGate
            feature="Booking Summary Reports"
            message="Basic reports require a subscription upgrade."
            upgradeMessage="Upgrade to Starter plan or higher to access booking analytics and insights."
          />
        </div>
      </SettingsDetailLayout>
    );
  }

  if (error || !data) {
    return (
      <SettingsDetailLayout
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Reports", href: "/provider/reports" },
          { label: "Booking Summary" },
        ]}
      >
        <EmptyReportState
          title="Failed to load report"
          description={error || "Unable to load booking summary data"}
        />
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      breadcrumbs={[
        { label: "Home", href: "/" },
        { label: "Provider", href: "/provider" },
        { label: "Reports", href: "/provider/reports" },
        { label: "Booking Summary" },
      ]}
      showCloseButton={false}
    >
      <div className="space-y-6" id="booking-summary-report">
        <PageHeader
          title="Booking Summary"
          subtitle="Overview of all bookings and performance"
          actions={
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => handleExport("csv")}>
                <Download className="w-4 h-4 mr-2" />
                Export CSV
              </Button>
              <Button variant="outline" onClick={() => handleExport("pdf")}>
                <Download className="w-4 h-4 mr-2" />
                Export PDF
              </Button>
            </div>
          }
        />

        <ReportFilters
          dateRange={dateRange}
          onDateRangeChange={setDateRange}
          onReset={handleReset}
        />

        {/* Summary Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <Card className="border-gray-200">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium text-gray-600">Total Bookings</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center justify-between">
                <p className="text-2xl font-semibold text-gray-900">{data.totalBookings}</p>
                <Calendar className="w-5 h-5 text-purple-600" />
              </div>
            </CardContent>
          </Card>

          <Card className="border-gray-200">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium text-gray-600">Total Revenue</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center justify-between">
                <p className="text-2xl font-semibold text-gray-900">
                  ZAR {data.totalRevenue.toLocaleString()}
                </p>
                <DollarSign className="w-5 h-5 text-green-600" />
              </div>
            </CardContent>
          </Card>

          <Card className="border-gray-200">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium text-gray-600">Average Booking Value</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center justify-between">
                <p className="text-2xl font-semibold text-gray-900">
                  ZAR {data.averageBookingValue.toLocaleString()}
                </p>
                <TrendingUp className="w-5 h-5 text-blue-600" />
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Daily Bookings Chart */}
        <Card className="border-gray-200">
          <CardHeader>
            <CardTitle>Daily Bookings</CardTitle>
          </CardHeader>
          <CardContent>
            {data.dailyBookings.length === 0 ? (
              <EmptyReportState title="No bookings found" description="No bookings in the selected period." />
            ) : (
              <RevenueChart
                data={data.dailyBookings.map((d) => ({
                  date: d.date,
                  revenue: d.revenue,
                  bookings: d.count,
                }))}
                type="bar"
              />
            )}
          </CardContent>
        </Card>

        {/* Status Breakdown */}
        <Card className="border-gray-200">
          <CardHeader>
            <CardTitle>Status Breakdown</CardTitle>
          </CardHeader>
          <CardContent>
            {data.statusBreakdown.length === 0 ? (
              <EmptyReportState title="No status data" description="No status breakdown available." />
            ) : (
              <div className="space-y-3">
                {data.statusBreakdown.map((status) => (
                  <div
                    key={status.status}
                    className="flex items-center justify-between p-3 rounded-lg border border-gray-200"
                  >
                    <div className="flex items-center gap-3">
                      <span className={`px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(status.status)}`}>
                        {status.status}
                      </span>
                      <span className="text-sm text-gray-600">
                        {status.percentage.toFixed(1)}%
                      </span>
                    </div>
                    <div className="text-right">
                      <p className="font-semibold text-gray-900">{status.count} bookings</p>
                      <p className="text-sm text-gray-600">
                        ZAR {status.revenue.toLocaleString()}
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Top Services */}
        <Card className="border-gray-200">
          <CardHeader>
            <CardTitle>Top Services</CardTitle>
          </CardHeader>
          <CardContent>
            {data.topServices.length === 0 ? (
              <EmptyReportState title="No services found" description="No service data available." />
            ) : (
              <div className="space-y-3">
                {data.topServices.map((service, index) => (
                  <div
                    key={service.serviceName}
                    className="flex items-center justify-between p-3 rounded-lg border border-gray-200"
                  >
                    <div className="flex items-center gap-3">
                      <div className="flex items-center justify-center w-8 h-8 rounded-full bg-[#FF0077] text-white font-semibold text-sm">
                        {index + 1}
                      </div>
                      <p className="font-medium text-gray-900">{service.serviceName}</p>
                    </div>
                    <div className="text-right">
                      <p className="font-semibold text-gray-900">{service.bookings} bookings</p>
                      <p className="text-sm text-gray-600">
                        ZAR {service.revenue.toLocaleString()}
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { PageHeader } from "@/components/provider/PageHeader";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Download, TrendingUp, TrendingDown } from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import { ReportSkeleton } from "../../components/ReportSkeleton";
import { EmptyReportState } from "../../components/EmptyReportState";
import { exportToCSV, formatReportDataForExport } from "../../utils/export";

interface BusinessComparisonData {
  period: string;
  current: {
    revenue: number;
    bookings: number;
    completed: number;
    clients: number;
    averageValue: number;
  };
  previous: {
    revenue: number;
    bookings: number;
    completed: number;
    clients: number;
    averageValue: number;
  };
  growth: {
    revenue: number;
    bookings: number;
    clients: number;
  };
}

export default function BusinessComparisonReport() {
  const [period, setPeriod] = useState("month");
  const [data, setData] = useState<BusinessComparisonData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadReport();
  }, [period]);

  const loadReport = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      params.append("period", period);

      const response = await fetcher.get<{ data: BusinessComparisonData }>(
        `/api/provider/reports/business/comparison?${params.toString()}`
      );
      setData(response.data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load report");
      console.error("Error loading business comparison:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleExport = () => {
    if (!data) return;
    const exportData = formatReportDataForExport(data, "business-comparison");
    exportToCSV(exportData, "business-comparison-report");
  };

  const formatPeriod = (p: string) => {
    switch (p) {
      case "month":
        return "Month";
      case "quarter":
        return "Quarter";
      case "year":
        return "Year";
      default:
        return p;
    }
  };

  if (isLoading) {
    return (
      <SettingsDetailLayout
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Reports", href: "/provider/reports" },
          { label: "Period Comparison" },
        ]}
      >
        <ReportSkeleton />
      </SettingsDetailLayout>
    );
  }

  if (error || !data) {
    return (
      <SettingsDetailLayout
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Reports", href: "/provider/reports" },
          { label: "Period Comparison" },
        ]}
      >
        <EmptyReportState
          title="Failed to load report"
          description={error || "Unable to load comparison data"}
        />
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      breadcrumbs={[
        { label: "Home", href: "/" },
        { label: "Provider", href: "/provider" },
        { label: "Reports", href: "/provider/reports" },
        { label: "Period Comparison" },
      ]}
      showCloseButton={false}
    >
      <div className="space-y-6">
        <PageHeader
          title="Period Comparison"
          subtitle="Compare performance across different time periods"
          actions={
            <Button variant="outline" onClick={handleExport}>
              <Download className="w-4 h-4 mr-2" />
              Export
            </Button>
          }
        />

        {/* Period Selector */}
        <div className="flex items-center gap-4">
          <Select value={period} onValueChange={setPeriod}>
            <SelectTrigger className="w-[180px]">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="month">Monthly</SelectItem>
              <SelectItem value="quarter">Quarterly</SelectItem>
              <SelectItem value="year">Yearly</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Comparison Cards */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Revenue Comparison */}
          <Card className="border-gray-200">
            <CardHeader>
              <CardTitle>Revenue</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div>
                  <p className="text-sm text-gray-600 mb-1">Current {formatPeriod(period)}</p>
                  <p className="text-2xl font-semibold text-gray-900">
                    ZAR {data.current.revenue.toLocaleString()}
                  </p>
                </div>
                <div>
                  <p className="text-sm text-gray-600 mb-1">Previous {formatPeriod(period)}</p>
                  <p className="text-xl font-medium text-gray-700">
                    ZAR {data.previous.revenue.toLocaleString()}
                  </p>
                </div>
                <div className="flex items-center gap-2 pt-2 border-t">
                  {data.growth.revenue >= 0 ? (
                    <TrendingUp className="w-5 h-5 text-green-600" />
                  ) : (
                    <TrendingDown className="w-5 h-5 text-red-600" />
                  )}
                  <p className={`text-lg font-semibold ${data.growth.revenue >= 0 ? "text-green-600" : "text-red-600"}`}>
                    {data.growth.revenue >= 0 ? "+" : ""}{data.growth.revenue.toFixed(1)}%
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Bookings Comparison */}
          <Card className="border-gray-200">
            <CardHeader>
              <CardTitle>Bookings</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div>
                  <p className="text-sm text-gray-600 mb-1">Current {formatPeriod(period)}</p>
                  <p className="text-2xl font-semibold text-gray-900">{data.current.bookings}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600 mb-1">Previous {formatPeriod(period)}</p>
                  <p className="text-xl font-medium text-gray-700">{data.previous.bookings}</p>
                </div>
                <div className="flex items-center gap-2 pt-2 border-t">
                  {data.growth.bookings >= 0 ? (
                    <TrendingUp className="w-5 h-5 text-green-600" />
                  ) : (
                    <TrendingDown className="w-5 h-5 text-red-600" />
                  )}
                  <p className={`text-lg font-semibold ${data.growth.bookings >= 0 ? "text-green-600" : "text-red-600"}`}>
                    {data.growth.bookings >= 0 ? "+" : ""}{data.growth.bookings.toFixed(1)}%
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Clients Comparison */}
          <Card className="border-gray-200">
            <CardHeader>
              <CardTitle>Clients</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div>
                  <p className="text-sm text-gray-600 mb-1">Current {formatPeriod(period)}</p>
                  <p className="text-2xl font-semibold text-gray-900">{data.current.clients}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600 mb-1">Previous {formatPeriod(period)}</p>
                  <p className="text-xl font-medium text-gray-700">{data.previous.clients}</p>
                </div>
                <div className="flex items-center gap-2 pt-2 border-t">
                  {data.growth.clients >= 0 ? (
                    <TrendingUp className="w-5 h-5 text-green-600" />
                  ) : (
                    <TrendingDown className="w-5 h-5 text-red-600" />
                  )}
                  <p className={`text-lg font-semibold ${data.growth.clients >= 0 ? "text-green-600" : "text-red-600"}`}>
                    {data.growth.clients >= 0 ? "+" : ""}{data.growth.clients.toFixed(1)}%
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Average Value Comparison */}
          <Card className="border-gray-200">
            <CardHeader>
              <CardTitle>Average Booking Value</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div>
                  <p className="text-sm text-gray-600 mb-1">Current {formatPeriod(period)}</p>
                  <p className="text-2xl font-semibold text-gray-900">
                    ZAR {data.current.averageValue.toLocaleString()}
                  </p>
                </div>
                <div>
                  <p className="text-sm text-gray-600 mb-1">Previous {formatPeriod(period)}</p>
                  <p className="text-xl font-medium text-gray-700">
                    ZAR {data.previous.averageValue.toLocaleString()}
                  </p>
                </div>
                <div className="pt-2 border-t">
                  <p className="text-sm text-gray-600">
                    Change: {((data.current.averageValue - data.previous.averageValue) / (data.previous.averageValue || 1) * 100).toFixed(1)}%
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { PageHeader } from "@/components/provider/PageHeader";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Download, DollarSign, Calendar, Clock } from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import { format } from "date-fns";
import { ReportSkeleton } from "../../components/ReportSkeleton";
import { EmptyReportState } from "../../components/EmptyReportState";
import { exportToCSV, exportToPDF, formatReportDataForExport } from "../../utils/export";

interface BusinessDashboardData {
  today: {
    revenue: number;
    bookings: number;
    completed: number;
  };
  week: {
    revenue: number;
    bookings: number;
  };
  month: {
    revenue: number;
    bookings: number;
    clients: number;
  };
  upcomingBookings: Array<{
    id: string;
    scheduled_at: string;
    status: string;
    total_amount: number;
  }>;
  recentBookings: Array<{
    id: string;
    scheduled_at: string;
    status: string;
    total_amount: number;
  }>;
}

export default function BusinessDashboardReport() {
  const [data, setData] = useState<BusinessDashboardData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadReport();
  }, []);

  const loadReport = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetcher.get<{ data: BusinessDashboardData }>(
        `/api/provider/reports/business/dashboard`
      );
      setData(response.data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load report");
      console.error("Error loading business dashboard:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleExport = (format: "csv" | "pdf" = "csv") => {
    if (!data) return;
    if (format === "csv") {
      const exportData = formatReportDataForExport(data, "business-dashboard");
      exportToCSV(exportData, "business-dashboard-report");
    } else {
      exportToPDF("business-dashboard-report", "business-dashboard-report", "Business Performance Dashboard");
    }
  };

  if (isLoading) {
    return (
      <SettingsDetailLayout
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Reports", href: "/provider/reports" },
          { label: "Performance Dashboard" },
        ]}
      >
        <ReportSkeleton />
      </SettingsDetailLayout>
    );
  }

  if (error || !data) {
    return (
      <SettingsDetailLayout
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Reports", href: "/provider/reports" },
          { label: "Performance Dashboard" },
        ]}
      >
        <EmptyReportState
          title="Failed to load report"
          description={error || "Unable to load dashboard data"}
        />
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      breadcrumbs={[
        { label: "Home", href: "/" },
        { label: "Provider", href: "/provider" },
        { label: "Reports", href: "/provider/reports" },
        { label: "Performance Dashboard" },
      ]}
      showCloseButton={false}
    >
      <div className="space-y-6" id="business-dashboard-report">
        <PageHeader
          title="Performance Dashboard"
          subtitle="Real-time view of your business performance"
          actions={
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => handleExport("csv")}>
                <Download className="w-4 h-4 mr-2" />
                Export CSV
              </Button>
              <Button variant="outline" onClick={() => handleExport("pdf")}>
                <Download className="w-4 h-4 mr-2" />
                Export PDF
              </Button>
            </div>
          }
        />

        {/* Today's Metrics */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <Card className="border-gray-200">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium text-gray-600">Today's Revenue</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center justify-between">
                <p className="text-2xl font-semibold text-gray-900">
                  ZAR {data.today.revenue.toLocaleString()}
                </p>
                <DollarSign className="w-5 h-5 text-green-600" />
              </div>
            </CardContent>
          </Card>

          <Card className="border-gray-200">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium text-gray-600">Today's Bookings</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center justify-between">
                <p className="text-2xl font-semibold text-gray-900">{data.today.bookings}</p>
                <Calendar className="w-5 h-5 text-blue-600" />
              </div>
              <p className="text-xs text-gray-500 mt-1">{data.today.completed} completed</p>
            </CardContent>
          </Card>

          <Card className="border-gray-200">
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium text-gray-600">This Week</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-2xl font-semibold text-gray-900">
                    ZAR {data.week.revenue.toLocaleString()}
                  </p>
                  <p className="text-xs text-gray-500 mt-1">{data.week.bookings} bookings</p>
                </div>
                <Calendar className="w-5 h-5 text-purple-600" />
              </div>
            </CardContent>
          </Card>
        </div>

        {/* This Month */}
        <Card className="border-gray-200">
          <CardHeader>
            <CardTitle>This Month</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div className="p-3 rounded-lg border border-gray-200">
                <p className="text-sm text-gray-600 mb-1">Revenue</p>
                <p className="text-2xl font-semibold text-gray-900">
                  ZAR {data.month.revenue.toLocaleString()}
                </p>
              </div>
              <div className="p-3 rounded-lg border border-gray-200">
                <p className="text-sm text-gray-600 mb-1">Bookings</p>
                <p className="text-2xl font-semibold text-gray-900">{data.month.bookings}</p>
              </div>
              <div className="p-3 rounded-lg border border-gray-200">
                <p className="text-sm text-gray-600 mb-1">Clients</p>
                <p className="text-2xl font-semibold text-gray-900">{data.month.clients}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Upcoming Bookings */}
        <Card className="border-gray-200">
          <CardHeader>
            <CardTitle>Upcoming Bookings</CardTitle>
          </CardHeader>
          <CardContent>
            {data.upcomingBookings.length === 0 ? (
              <EmptyReportState title="No upcoming bookings" description="No upcoming bookings scheduled." />
            ) : (
              <div className="space-y-3">
                {data.upcomingBookings.map((booking) => (
                  <div
                    key={booking.id}
                    className="flex items-center justify-between p-3 rounded-lg border border-gray-200"
