          </Card>
        )}

        {/* Revenue by Staff */}
        {data.revenueByStaff && data.revenueByStaff.length > 0 ? (
          <Card className="border-gray-200">
            <CardHeader>
              <CardTitle>Revenue by Staff</CardTitle>
