import { exportToCSV, formatReportDataForExport } from "../../utils/export";

interface CommissionData {
  totalCommission: number;
  totalRevenue: number;
  averageCommissionRate: number;
  staffCommissions: Array<{
    staffId: string;
    staffName: string;
    commissionRate: number;
    totalBookings: number;
    totalRevenue: number;
    totalCommission: number;
    averageCommission: number;
  }>;
}

export default function CommissionReport() {
  const [dateRange, setDateRange] = useState<DateRange>({
    from: subDays(new Date(), 30),
    to: new Date(),
  });
  const [data, setData] = useState<CommissionData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadReport();
  }, [dateRange]);

  const loadReport = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const params = new URLSearchParams();
      if (dateRange.from) {
        params.append("from", dateRange.from.toISOString());
      }
      if (dateRange.to) {
        params.append("to", dateRange.to.toISOString());
      }

      const response = await fetcher.get<{ data: CommissionData }>(
        `/api/provider/reports/staff/commission?${params.toString()}`
      );
      setData(response.data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load report");
      console.error("Error loading commission report:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleReset = () => {
    setDateRange({
      from: subDays(new Date(), 30),
      to: new Date(),
    });
