      return [
        { Metric: "Total Payouts", Value: data.totalPayouts || 0 },
        { Metric: "Total Payout Amount", Value: `ZAR ${(data.totalPayoutAmount || 0).toLocaleString()}` },
        ...(data.monthlyBreakdown || []).map((m: any) => ({
          Month: m.month,
          Count: m.count || 0,
          Amount: `ZAR ${(m.amount || 0).toLocaleString()}`,
        })),
        ...(data.recentPayouts || []).map((p: any) => ({
          Date: p.createdAt,
          Amount: `ZAR ${(p.payoutAmount || p.amount || 0).toLocaleString()}`,
        })),
      ];

    case "top-products":
      return [
        { Metric: "Total Products Sold", Value: data.totalProductsSold || 0 },
        { Metric: "Total Revenue", Value: `ZAR ${data.totalRevenue?.toLocaleString() || 0}` },
        ...(data.topProducts || []).map((p: any) => ({
          Product: p.productName || p.name,
          "Quantity Sold": p.totalQuantity || p.quantitySold || 0,
          Revenue: `ZAR ${(p.totalRevenue || p.revenue || 0).toLocaleString()}`,
        })),
      ];

    case "payment-methods":
      return (data.methods || []).map((m: any) => ({
        Method: m.method,
        "Total Count": m.totalCount || 0,
        "Total Amount": `ZAR ${(m.totalAmount || 0).toLocaleString()}`,
      }));

    case "refunds":
      return [
        { Metric: "Total Refunds", Value: data.totalRefunds || 0 },
        { Metric: "Total Refund Amount", Value: `ZAR ${data.totalRefundAmount?.toLocaleString() || 0}` },
        ...(data.methodBreakdown || data.refunds || []).map((r: any) => ({
          Method: r.method,
          Count: r.count || 0,
          Amount: `ZAR ${(r.amount || 0).toLocaleString()}`,
        })),
      ];

    case "inventory":
      return [
        { Metric: "Total Products", Value: data.totalProducts || 0 },
        { Metric: "Stock Value", Value: `ZAR ${(data.totalStockValue || 0).toLocaleString()}` },
        ...(data.lowStockProducts || data.allProducts || []).map((p: any) => ({
          Product: p.name || p.productName,
          Stock: p.quantity || 0,
          "Retail Price": `ZAR ${(p.retail_price || 0).toLocaleString()}`,
          Value: `ZAR ${((p.quantity || 0) * (p.retail_price || 0)).toLocaleString()}`,
        })),
      ];

    case "commission":
      return (data.staffCommissions || data.commissionData || []).map((s: any) => ({
        "Staff Name": s.staffName || s.name,
        "Total Revenue": `ZAR ${(s.totalRevenue || 0).toLocaleString()}`,
        "Commission": `ZAR ${(s.totalCommission || s.commissionEarned || 0).toLocaleString()}`,
      }));

    case "staff-hours":
      return (data.staffHours || data.hoursData || []).map((s: any) => ({
        "Staff Name": s.staffName || s.name,
        "Total Hours": (s.totalHours || 0).toFixed(1),
        Bookings: s.completedBookings || s.totalBookings || 0,
      }));

    default:
      // Generic export - try to flatten the data
      if (Array.isArray(data)) {
        return data;
      }
      // If it's an object, try to find array properties
      const arrayKeys = Object.keys(data).filter((key) => Array.isArray(data[key]));
      if (arrayKeys.length > 0) {
        return data[arrayKeys[0]];
      }
      return [data];
  }
}

"use client";

import React, { useState, useEffect } from "react";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Star, MessageSquare, Flag, Eye, EyeOff, Edit2, Send } from "lucide-react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { PageHeader } from "@/components/provider/PageHeader";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";

interface Review {
  id: string;
  rating: number;
  comment: string | null;
  provider_response: string | null;
  provider_response_at: string | null;
  is_flagged: boolean;
  is_visible: boolean;
  created_at: string;
  customer: {
    id: string;
    full_name: string;
    email: string;
  };
  booking: {
    id: string;
    booking_number: string;
    scheduled_at: string;
  };
}

export default function ProviderReviewsPage() {
  const [reviews, setReviews] = useState<Review[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<"all" | "pending_response" | "responded">("all");
  const [_selectedReview, setSelectedReview] = useState<Review | null>(null);
  const [responseText, setResponseText] = useState("");
  const [isResponding, setIsResponding] = useState(false);
  const [isModerating, setIsModerating] = useState(false);

  useEffect(() => {
    loadReviews();
  }, [statusFilter]);

  const loadReviews = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const response = await fetcher.get<{ data: { reviews: Review[] } }>(
        `/api/provider/reviews?status=${statusFilter}`,
        { timeoutMs: 30000 } // 30 second timeout
      );
      setReviews(response.data.reviews || []);
    } catch (err) {
      setError(err instanceof FetchError ? err.message : "Failed to load reviews");
      console.error("Error loading reviews:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleRespond = async (reviewId: string, isEdit: boolean = false) => {
    if (!responseText.trim()) {
      toast.error("Please enter a response");
      return;
    }

    try {
      setIsResponding(true);
      const endpoint = `/api/provider/reviews/${reviewId}/respond`;
      await fetcher[isEdit ? "PATCH" : "POST"](endpoint, {
        response: responseText.trim(),
      });

      toast.success(isEdit ? "Response updated successfully" : "Response added successfully");
      setSelectedReview(null);
      setResponseText("");
      loadReviews();
    } catch (err) {
      toast.error(err instanceof FetchError ? err.message : "Failed to save response");
      console.error("Error saving response:", err);
    } finally {
      setIsResponding(false);
    }
  };

  const handleModerate = async (reviewId: string, action: "flag" | "unflag" | "hide" | "unhide", reason?: string) => {
    try {
      setIsModerating(true);
      await fetcher.post(`/api/provider/reviews/${reviewId}/moderate`, {
        action,
        reason,
      });

      toast.success(`Review ${action}ed successfully`);
      loadReviews();
    } catch (err) {
      toast.error(err instanceof FetchError ? err.message : "Failed to moderate review");
      console.error("Error moderating review:", err);
    } finally {
      setIsModerating(false);
    }
  };

  if (isLoading) {
    return (
      <SettingsDetailLayout
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Reviews" },
        ]}
      >
        <LoadingTimeout loadingMessage="Loading reviews..." />
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      breadcrumbs={[
        { label: "Home", href: "/" },
        { label: "Provider", href: "/provider" },
        { label: "Reviews" },
      ]}
      showCloseButton={false}
    >
      <div className="space-y-6">
        <PageHeader
          title="Reviews"
          subtitle="Manage and respond to customer reviews"
        />

        <div className="flex gap-2">
            <Button
              variant={statusFilter === "all" ? "default" : "outline"}
              onClick={() => setStatusFilter("all")}
            >
              All Reviews
            </Button>
            <Button
              variant={statusFilter === "pending_response" ? "default" : "outline"}
              onClick={() => setStatusFilter("pending_response")}
            >
              Pending Response
            </Button>
            <Button
              variant={statusFilter === "responded" ? "default" : "outline"}
              onClick={() => setStatusFilter("responded")}
            >
              Responded
            </Button>
          </div>

        {error && (
          <div className="p-4 bg-red-50 border border-red-200 rounded-lg">
            <p className="text-red-600">{error}</p>
          </div>
        )}

        <div className="space-y-4">
          {reviews.length === 0 ? (
            <Card>
              <CardContent className="py-8 text-center">
                <p className="text-gray-600">No reviews found</p>
              </CardContent>
            </Card>
          ) : (
            reviews.map((review) => (
              <Card key={review.id}>
                <CardHeader>
                  <div className="flex justify-between items-start">
                    <div>
                      <div className="flex items-center gap-2 mb-2">
                        <div className="flex">
                          {[1, 2, 3, 4, 5].map((star) => (
                            <Star
                              key={star}
                              className={`w-5 h-5 ${
                                star <= review.rating
                                  ? "fill-yellow-400 text-yellow-400"
                                  : "text-gray-300"
                              }`}
                            />
                          ))}
                        </div>
                        <span className="font-semibold">{review.rating}.0</span>
                      </div>
                      <p className="font-medium">{review.customer.full_name}</p>
                      <p className="text-sm text-gray-600">
                        Booking #{review.booking.booking_number} ΓÇó {new Date(review.created_at).toLocaleDateString()}
                      </p>
                    </div>
                    <div className="flex gap-2">
                      {review.is_flagged && (
                        <Badge variant="destructive">Flagged</Badge>
                      )}
                      {!review.is_visible && (
                        <Badge variant="secondary">Hidden</Badge>
                      )}
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  {review.comment && (
                    <p className="mb-4 text-gray-700">{review.comment}</p>
                  )}

                  {review.provider_response ? (
                    <div className="mb-4 p-4 bg-blue-50 rounded-lg">
                      <div className="flex justify-between items-start mb-2">
                        <p className="font-semibold text-blue-900">Your Response</p>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => {
                            setSelectedReview(review);
                            setResponseText(review.provider_response || "");
                          }}
                        >
                          <Edit2 className="w-4 h-4 mr-1" />
                          Edit
                        </Button>
                      </div>
                      <p className="text-blue-800">{review.provider_response}</p>
                      <p className="text-xs text-blue-600 mt-2">
                        {new Date(review.provider_response_at || "").toLocaleDateString()}
                      </p>
                    </div>
                  ) : (
                    <Dialog>
                      <DialogTrigger asChild>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => {
                            setSelectedReview(review);
                            setResponseText("");
                          }}
                        >
                          <MessageSquare className="w-4 h-4 mr-2" />
                          Respond
                        </Button>
                      </DialogTrigger>
                      <DialogContent>
                        <DialogHeader>
                          <DialogTitle>Respond to Review</DialogTitle>
                        </DialogHeader>
                        <div className="space-y-4">
                          <Textarea
                            placeholder="Write your response..."
                            value={responseText}
                            onChange={(e) => setResponseText(e.target.value)}
                            rows={6}
                            maxLength={1000}
                          />
                          <div className="flex justify-end gap-2">
                            <Button
                              variant="outline"
                              onClick={() => {
                                setSelectedReview(null);
                                setResponseText("");
                              }}
                            >
                              Cancel
                            </Button>
                            <Button
                              onClick={() => handleRespond(review.id, false)}
                              disabled={isResponding}
                            >
                              <Send className="w-4 h-4 mr-2" />
                              Send Response
                            </Button>
                          </div>
                        </div>
                      </DialogContent>
                    </Dialog>
                  )}

                  <div className="flex gap-2 mt-4 pt-4 border-t">
                    {!review.is_flagged && (
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleModerate(review.id, "flag", "Inappropriate content")}
                        disabled={isModerating}
                      >
                        <Flag className="w-4 h-4 mr-1" />
                        Flag
                      </Button>
                    )}
                    {review.is_flagged && (
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleModerate(review.id, "unflag")}
                        disabled={isModerating}
                      >
                        Unflag
                      </Button>
                    )}
                    {review.is_visible ? (
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleModerate(review.id, "hide")}
                        disabled={isModerating}
                      >
                        <EyeOff className="w-4 h-4 mr-1" />
                        Hide
                      </Button>
                    ) : (
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleModerate(review.id, "unhide")}
                        disabled={isModerating}
                      >
                        <Eye className="w-4 h-4 mr-1" />
                        Show
                      </Button>
                    )}
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>
      </div>
    </SettingsDetailLayout>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Calendar } from "@/components/ui/calendar";
import { Loader2, MapPin, Navigation, Clock, DollarSign, TrendingDown, Route } from "lucide-react";
import { toast } from "sonner";
import { formatCurrency } from "@/lib/pricing/calculate-booking-price-complete";
import { fetcher } from "@/lib/http/fetcher";

interface RouteSegment {
  id: string;
  order: number;
  distance_km: number;
  duration_minutes: number;
  travel_fee_calculated: number;
  travel_fee_charged: number;
  from_location: any;
  to_location: any;
  booking: {
    id: string;
    ref_number: string;
    scheduled_at: string;
    duration: number;
    status: string;
    customer: {
      full_name: string;
      phone: string;
    };
  };
}

interface RouteData {
  route: {
    id: string;
    date: string;
    total_distance_km: number;
    total_duration_minutes: number;
    optimization_status: string;
    optimized_at: string;
  };
  segments: RouteSegment[];
  savings: {
    standard_total: number;
    chained_total: number;
    savings: number;
    savings_percentage: number;
  };
}

export default function RoutesPage() {
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [loading, setLoading] = useState(false);
  const [optimizing, setOptimizing] = useState(false);
  const [routeData, setRouteData] = useState<RouteData | null>(null);

  useEffect(() => {
    if (selectedDate) {
      fetchRoute();
    }
  }, [selectedDate]);

  const fetchRoute = async () => {
    setLoading(true);
    try {
      const dateStr = selectedDate.toISOString().split('T')[0];
      const response = await fetcher.get<{ data: RouteData }>(`/api/provider/routes?date=${dateStr}`);
      const data = response.data;
      if (data?.route) {
        setRouteData(data);
      } else {
        setRouteData(null);
      }
    } catch (error) {
      console.error("Failed to fetch route:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleOptimize = async () => {
    setOptimizing(true);
    try {
      const dateStr = selectedDate.toISOString().split('T')[0];
      const res = await fetcher.post<{ data: { savings: { amount_saved: number; percentage_saved: number } } }>(
        '/api/provider/routes/optimize',
        { date: dateStr }
      );
      const data = res.data;

      toast.success(`Route optimized! Saved ${formatCurrency(data?.savings?.amount_saved ?? 0)} (${data?.savings?.percentage_saved ?? 0}%)`);

      fetchRoute();
    } catch (error: any) {
      toast.error(error.message);
    } finally {
      setOptimizing(false);
    }
  };

  const formatTime = (isoString: string) => {
    return new Date(isoString).toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  return (
    <div className="container max-w-7xl py-8 space-y-8">
      <div>
        <h1 className="text-3xl font-bold">Route Optimizer</h1>
        <p className="text-muted-foreground mt-2">
          Optimize travel routes for at-home appointments and reduce travel fees
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column - Date Selector */}
        <Card>
          <CardHeader>
            <CardTitle>Select Date</CardTitle>
            <CardDescription>Choose a date to view or optimize routes</CardDescription>
          </CardHeader>
          <CardContent>
            <Calendar
              mode="single"
              selected={selectedDate}
              onSelect={(date) => date && setSelectedDate(date)}
              className="rounded-md border"
            />
            <Button
              className="w-full mt-4"
              onClick={handleOptimize}
              disabled={optimizing || loading}
            >
              {optimizing ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Optimizing...
                </>
              ) : (
                <>
                  <Route className="w-4 h-4 mr-2" />
                  Optimize Route
                </>
              )}
            </Button>
          </CardContent>
        </Card>

        {/* Right Column - Route Details */}
        <div className="lg:col-span-2 space-y-6">
          {loading ? (
            <Card>
              <CardContent className="flex items-center justify-center py-12">
                <Loader2 className="w-8 h-8 animate-spin text-primary" />
              </CardContent>
            </Card>
          ) : !routeData ? (
            <Card>
              <CardContent className="flex flex-col items-center justify-center py-12 text-center">
                <Navigation className="w-12 h-12 text-muted-foreground mb-4" />
                <h3 className="text-lg font-semibold mb-2">No Route Found</h3>
                <p className="text-muted-foreground mb-4">
                  No at-home appointments scheduled for this date, or route hasn't been optimized yet.
                </p>
                <Button onClick={handleOptimize} disabled={optimizing}>
                  <Route className="w-4 h-4 mr-2" />
                  Create Route
                </Button>
              </CardContent>
            </Card>
          ) : (
            <>
              {/* Route Summary */}
              <Card className="border-2 border-primary/20">
                <CardHeader>
                  <CardTitle className="flex items-center justify-between">
                    <span className="flex items-center gap-2">
                      <Route className="w-6 h-6 text-primary" />
                      Route for {new Date(routeData.route.date).toLocaleDateString()}
                    </span>
                    <Badge variant={routeData.route.optimization_status === 'optimized' ? 'default' : 'secondary'}>
                      {routeData.route.optimization_status}
                    </Badge>
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <div className="bg-background rounded-lg p-4 border">
                      <p className="text-sm text-muted-foreground mb-1">Appointments</p>
                      <p className="text-2xl font-bold">{routeData.segments.length}</p>
                    </div>
                    <div className="bg-background rounded-lg p-4 border">
                      <p className="text-sm text-muted-foreground mb-1">Total Distance</p>
                      <p className="text-2xl font-bold">{routeData.route.total_distance_km.toFixed(1)} km</p>
                    </div>
                    <div className="bg-background rounded-lg p-4 border">
                      <p className="text-sm text-muted-foreground mb-1">Travel Time</p>
                      <p className="text-2xl font-bold">{routeData.route.total_duration_minutes} min</p>
