import React, { useState, useEffect } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { Sale, FilterParams, PaginationParams } from "@/lib/provider-portal/types";
import { PageHeader } from "@/components/provider/PageHeader";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Money } from "@/components/provider-portal/Money";
import { YocoPaymentDialog } from "@/components/provider-portal/YocoPaymentDialog";
import { NewSaleDialog } from "@/components/provider-portal/NewSaleDialog";
import { Search, Filter, Plus, CreditCard, Calendar, User, ShoppingBag } from "lucide-react";
import Pagination from "@/components/ui/pagination";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { SectionCard } from "@/components/provider/SectionCard";
import type { YocoPayment } from "@/lib/provider-portal/types";
import { useProviderPortal } from "@/providers/provider-portal/ProviderPortalProvider";
import { ProtectedPage } from "@/components/provider/ProtectedPage";

function ProviderSalesContent() {
  const { selectedLocationId } = useProviderPortal();
  const [sales, setSales] = useState<Sale[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [dateRange, setDateRange] = useState<string>("month");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [yocoDialogOpen, setYocoDialogOpen] = useState(false);
  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [isNewSaleDialogOpen, setIsNewSaleDialogOpen] = useState(false);

  useEffect(() => {
    loadSales();
  }, [page, dateRange, selectedLocationId]);

  // Optimized debounced search (reduced from 500ms to 300ms for faster response)
  useEffect(() => {
    const debounceTimer = setTimeout(() => {
      if (page === 1) {
        loadSales();
      } else {
        setPage(1); // Reset to first page when searching
      }
    }, 300);

    return () => clearTimeout(debounceTimer);
  }, [searchQuery]);

  const loadSales = async () => {
    try {
      setIsLoading(true);
      const filters: FilterParams = {
        search: searchQuery || undefined,
        location_id: selectedLocationId || undefined,
      };

      if (dateRange === "month") {
        const now = new Date();
        filters.date_from = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split("T")[0];
        filters.date_to = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split("T")[0];
      }

      const pagination: PaginationParams = { page, limit: 20 };
      const response = await providerApi.listSales(filters, pagination);
      setSales(response.data);
      setTotalPages(response.total_pages);
    } catch (error) {
      console.error("Failed to load sales:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreateSale = () => {
    setIsNewSaleDialogOpen(true);
  };

  const handleSaleSuccess = () => {
    setIsNewSaleDialogOpen(false);
    loadSales();
  };

  const handleYocoPayment = (sale: Sale) => {
    setSelectedSale(sale);
    setYocoDialogOpen(true);
  };

  const handlePaymentSuccess = (_payment: YocoPayment) => {
    // Reload sales to reflect payment status
    loadSales();
  };

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading sales..." />;
  }

  return (
    <div className="pb-4 md:pb-0">
      {/* Mobile-first header */}
      <div className="sticky top-0 z-10 bg-white border-b md:border-none md:bg-transparent mb-4 md:mb-6">
        <div className="flex items-center justify-between p-4 md:p-0">
          <div>
            <h1 className="text-2xl font-bold md:hidden">Sales</h1>
            <div className="hidden md:block">
              <PageHeader
                title="Sales"
                subtitle="Track your sales and transactions"
                primaryAction={{
                label: "New Sale",
                onClick: handleCreateSale,
                icon: <Plus className="w-4 h-4 mr-2" />,
              }}
              />
            </div>
          </div>
          <Button
            onClick={handleCreateSale}
            className="md:hidden bg-[#FF0077] hover:bg-[#D60565] h-11 px-4 rounded-full shadow-lg active:scale-95 transition-transform"
            size="lg"
          >
            <Plus className="w-5 h-5 mr-2" />
            New Sale
          </Button>
        </div>
      </div>

      {/* Mobile-optimized filters */}
      <div className="px-4 md:px-0 mb-4 md:mb-6 space-y-3 md:space-y-0 md:flex md:flex-row md:gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
          <Input
            placeholder="Search sales..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-11 h-12 text-base md:pl-10 md:h-10 md:text-sm"
          />
        </div>
        <div className="flex gap-2 md:block">
          <Select value={dateRange} onValueChange={setDateRange}>
            <SelectTrigger className="w-full h-12 text-base md:h-10 md:w-48 md:text-sm">
              <Calendar className="w-4 h-4 mr-2" />
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="today">Today</SelectItem>
              <SelectItem value="week">This Week</SelectItem>
              <SelectItem value="month">Month to Date</SelectItem>
              <SelectItem value="custom">Custom Range</SelectItem>
            </SelectContent>
          </Select>
          <Button variant="outline" className="h-12 px-4 md:h-10 md:px-3 active:scale-95 transition-transform">
            <Filter className="w-5 h-5 md:w-4 md:h-4" />
            <span className="ml-2 md:ml-2 md:hidden">Filter</span>
          </Button>
        </div>
      </div>

      {/* Sales List - Mobile Cards / Desktop Table */}
      {sales.length === 0 ? (
        <SectionCard className="p-8 md:p-12 text-center mx-4 md:mx-0">
          <EmptyState
            title="No Sales yet"
            description="Click here to make a new sale"
            action={{
              label: "New Sale",
              onClick: handleCreateSale,
            }}
          />
        </SectionCard>
      ) : (
        <>
          {/* Mobile Card View */}
          <div className="md:hidden px-4 space-y-3">
            {sales.map((sale) => (
              <div
                key={sale.id}
                className="bg-white rounded-xl border border-gray-200 p-4 shadow-sm active:scale-[0.98] transition-transform"
              >
                <div className="flex items-start justify-between mb-3">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <span className="text-xs font-semibold text-[#FF0077] bg-[#FF0077]/10 px-2 py-1 rounded">
                        {sale.ref_number}
                      </span>
                      <span className="text-xs text-gray-500">
                        {new Date(sale.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                      </span>
                    </div>
                    <div className="flex items-center gap-2 mt-2">
                      <User className="w-4 h-4 text-gray-400" />
                      <span className="font-medium text-sm">{sale.client_name || "Walk-in"}</span>
                    </div>
                  </div>
                  <div className="text-right">
                    <div className="text-lg font-bold text-[#FF0077]">
                      <Money amount={sale.total} />
                    </div>
                    <div className="text-xs text-gray-500 mt-1">{sale.payment_method}</div>
                  </div>
                </div>

                <div className="flex items-center justify-between pt-3 border-t">
                  <div className="flex items-center gap-4 text-xs text-gray-600">
                    <div className="flex items-center gap-1">
                      <ShoppingBag className="w-3 h-3" />
                      <span>{sale.items.length} items</span>
                    </div>
                    {sale.team_member_name && (
                      <span className="text-gray-500">{sale.team_member_name}</span>
                    )}
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => handleYocoPayment(sale)}
                    className="h-8 px-3 text-xs active:scale-95 transition-transform"
                  >
                    <CreditCard className="w-3 h-3 mr-1" />
                    Pay
                  </Button>
                </div>
              </div>
            ))}
          </div>

          {/* Desktop Table View */}
          <div className="hidden md:block bg-white border border-gray-200 rounded-lg overflow-hidden">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Ref #</TableHead>
                  <TableHead>Client</TableHead>
                  <TableHead>Date</TableHead>
                  <TableHead>Items</TableHead>
                  <TableHead>Subtotal</TableHead>
                  <TableHead>Tax</TableHead>
                  <TableHead>Total</TableHead>
                  <TableHead>Payment Method</TableHead>
                  <TableHead>Team Member</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {sales.map((sale) => (
                  <TableRow key={sale.id} className="hover:bg-gray-50 transition-colors">
                    <TableCell className="font-medium">{sale.ref_number}</TableCell>
                    <TableCell>{sale.client_name || "Walk-in"}</TableCell>
                    <TableCell>{new Date(sale.date).toLocaleDateString()}</TableCell>
                    <TableCell>{sale.items.length} items</TableCell>
                    <TableCell>
                      <Money amount={sale.subtotal} />
                    </TableCell>
                    <TableCell>
                      <Money amount={sale.tax} />
                    </TableCell>
                    <TableCell className="font-semibold">
                      <Money amount={sale.total} />
                    </TableCell>
                    <TableCell>{sale.payment_method}</TableCell>
                    <TableCell>{sale.team_member_name || "-"}</TableCell>
                    <TableCell className="text-right">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleYocoPayment(sale)}
                        className="gap-2"
                      >
                        <CreditCard className="w-3 h-3" />
                        Pay
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>

          {totalPages > 1 && (
            <div className="mt-6 px-4 md:px-0">
              <Pagination
                currentPage={page}
                totalPages={totalPages}
                onPageChange={setPage}
              />
            </div>
          )}
        </>
      )}

      {selectedSale && (
        <YocoPaymentDialog
          open={yocoDialogOpen}
          onOpenChange={setYocoDialogOpen}
          amount={selectedSale.total}
          saleId={selectedSale.id}
          onSuccess={handlePaymentSuccess}
        />
      )}

      <NewSaleDialog
        open={isNewSaleDialogOpen}
        onOpenChange={setIsNewSaleDialogOpen}
        onSuccess={handleSaleSuccess}
      />
    </div>
  );
}

export default function ProviderSales() {
  return (
    <ProtectedPage
      permission="view_sales"
      message="You don't have permission to view sales. Contact your administrator to request access."
    >
      <ProviderSalesContent />
    </ProtectedPage>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Plus,
  Edit,
  Trash2,
  Search,
  DollarSign,
  Clock,
  Tag,
} from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import type { OfferingCard } from "@/types/beautonomi";
import { toast } from "sonner";

export default function ProviderServices() {
  const [services, setServices] = useState<OfferingCard[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingService, setEditingService] = useState<OfferingCard | null>(null);

  useEffect(() => {
    loadServices();
  }, []);

  const loadServices = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await fetcher.get<{ data: OfferingCard[] }>(
        "/api/provider/services"
      );
      setServices(response.data);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load services";
      setError(errorMessage);
      console.error("Error loading services:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this service?")) return;

    try {
      await fetcher.delete(`/api/provider/services/${id}`);
      toast.success("Service deleted successfully");
      loadServices();
    } catch {
      toast.error("Failed to delete service");
    }
  };

  const filteredServices = services.filter((service) =>
    (service?.title ?? "").toLowerCase().includes((searchQuery ?? "").toLowerCase())
  );

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading services..." />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["provider_owner", "provider_staff"]}>
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-6">
          <div>
            <h1 className="text-3xl font-semibold mb-2">Services</h1>
            <p className="text-gray-600">Manage your service offerings</p>
          </div>
          <Button onClick={() => setShowAddModal(true)}>
            <Plus className="w-4 h-4 mr-2" />
            Add Service
          </Button>
        </div>

        {/* Search */}
        <div className="mb-6">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
            <Input
              placeholder="Search services..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10"
            />
          </div>
        </div>

        {/* Services List */}
        {error ? (
          <EmptyState
            title="Failed to load services"
            description={error}
            action={{
              label: "Retry",
              onClick: loadServices,
            }}
          />
        ) : filteredServices.length === 0 ? (
          <EmptyState
            title="No services yet"
            description="Get started by adding your first service offering"
            action={{
              label: "Add Service",
              onClick: () => setShowAddModal(true),
            }}
          />
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredServices.map((service) => (
              <ServiceCard
                key={service.id}
                service={service}
                onEdit={() => setEditingService(service)}
                onDelete={() => handleDelete(service.id)}
              />
            ))}
          </div>
        )}

        {/* Add/Edit Modal */}
        {(showAddModal || editingService) && (
          <ServiceModal
            service={editingService}
            onClose={() => {
              setShowAddModal(false);
              setEditingService(null);
            }}
            onSave={() => {
              setShowAddModal(false);
              setEditingService(null);
              loadServices();
            }}
          />
        )}
      </div>
    </RoleGuard>
  );
}

function ServiceCard({
  service,
  onEdit,
  onDelete,
}: {
  service: OfferingCard;
  onEdit: () => void;
  onDelete: () => void;
}) {
  return (
    <div className="bg-white border rounded-lg p-6 hover:shadow-md transition-shadow">
      <div className="flex justify-between items-start mb-4">
        <h3 className="text-lg font-semibold">{service.title}</h3>
        <div className="flex gap-2">
          <button
            onClick={onEdit}
            className="p-1 text-gray-600 hover:text-blue-600 transition-colors"
          >
            <Edit className="w-4 h-4" />
          </button>
          <button
            onClick={onDelete}
            className="p-1 text-gray-600 hover:text-red-600 transition-colors"
          >
            <Trash2 className="w-4 h-4" />
          </button>
        </div>
      </div>

      <div className="space-y-2 text-sm text-gray-600">
        <div className="flex items-center gap-2">
          <DollarSign className="w-4 h-4" />
          <span>
            {service.currency} {service.price?.toFixed(2)}
          </span>
        </div>
        {service.duration_minutes && (
          <div className="flex items-center gap-2">
            <Clock className="w-4 h-4" />
            <span>{service.duration_minutes} minutes</span>
          </div>
        )}
        {(service as any).category_name && (
          <div className="flex items-center gap-2">
            <Tag className="w-4 h-4" />
            <span>{(service as any).category_name}</span>
          </div>
        )}
      </div>

      {service.description && (
        <p className="mt-4 text-sm text-gray-600 line-clamp-2">
          {service.description}
        </p>
      )}

      <div className="mt-4 pt-4 border-t">
        <span
          className={`inline-block px-2 py-1 rounded text-xs font-medium ${
            service.is_active
              ? "bg-green-100 text-green-800"
              : "bg-gray-100 text-gray-800"
          }`}
        >
          {service.is_active ? "Active" : "Inactive"}
        </span>
      </div>
    </div>
  );
}

function ServiceModal({
  service,
  onClose,
  onSave,
}: {
  service: OfferingCard | null;
  onClose: () => void;
  onSave: () => void;
}) {
  const [formData, setFormData] = useState({
    title: service?.title || "",
    description: service?.description || "",
    price: service?.price || 0,
    duration_minutes: service?.duration_minutes || 60,
    category_id: (service as any)?.category_id || "",
    is_active: service?.is_active ?? true,
  });
  const [isSaving, setIsSaving] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setIsSaving(true);

      if (service) {
        await fetcher.patch(`/api/provider/services/${service.id}`, formData);
      } else {
        await fetcher.post("/api/provider/services", formData);
      }

      toast.success(service ? "Service updated" : "Service created");
      onSave();
    } catch {
      toast.error("Failed to save service");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-2xl font-semibold mb-4">
          {service ? "Edit Service" : "Add Service"}
        </h2>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="title">Service Name *</Label>
            <Input
              id="title"
              value={formData.title}
              onChange={(e) =>
                setFormData({ ...formData, title: e.target.value })
              }
              required
            />
          </div>

          <div>
            <Label htmlFor="description">Description</Label>
            <textarea
              id="description"
              value={formData.description}
              onChange={(e) =>
                setFormData({ ...formData, description: e.target.value })
              }
              className="w-full p-2 border rounded-md min-h-[100px]"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="price">Price (ZAR) *</Label>
              <Input
                id="price"
                type="number"
                step="0.01"
                value={formData.price}
                onChange={(e) =>
                  setFormData({ ...formData, price: parseFloat(e.target.value) })
                }
                required
              />
            </div>
            <div>
              <Label htmlFor="duration">Duration (minutes) *</Label>
              <Input
                id="duration"
                type="number"
                value={formData.duration_minutes}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    duration_minutes: parseInt(e.target.value),
                  })
                }
                required
              />
            </div>
          </div>

          <div>
            <Label htmlFor="category">Category</Label>
            <Input
              id="category"
              value={formData.category_id}
              onChange={(e) =>
                setFormData({ ...formData, category_id: e.target.value })
              }
              placeholder="Category ID"
            />
          </div>

          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="is_active"
              checked={formData.is_active}
              onChange={(e) =>
                setFormData({ ...formData, is_active: e.target.checked })
              }
            />
            <Label htmlFor="is_active">Active (visible to customers)</Label>
          </div>

          <div className="flex gap-2 pt-4">
            <Button type="button" variant="outline" onClick={onClose} className="flex-1">
              Cancel
            </Button>
            <Button type="submit" disabled={isSaving} className="flex-1">
              {isSaving ? "Saving..." : service ? "Update" : "Create"}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { fetcher } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";
import { Plus, Edit, Trash2 } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { providerApi } from "@/lib/provider-portal/api";

interface ServiceAddon {
  id: string;
  name: string;
  description?: string | null;
  type: "service" | "product" | "upgrade";
  category?: string | null;
  price: number;
  currency: string;
  duration_minutes?: number | null;
  is_active: boolean;
  is_recommended: boolean;
  image_url?: string | null;
  provider_id?: string | null;
  service_ids: string[];
  max_quantity?: number | null;
  requires_service: boolean;
  sort_order: number;
}

export default function ProviderAddons() {
  const [addons, setAddons] = useState<ServiceAddon[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showDialog, setShowDialog] = useState(false);
  const [editingAddon, setEditingAddon] = useState<ServiceAddon | null>(null);
  const [services, setServices] = useState<Array<{ id: string; title: string }>>([]);
  const [filterType, setFilterType] = useState<string>("all");

  useEffect(() => {
    loadAddons();
    loadServices();
  }, [filterType]);

  const loadAddons = async () => {
    try {
      setIsLoading(true);
      const params = filterType !== "all" ? `?type=${filterType}` : "";
      const response = await fetcher.get<{ data: ServiceAddon[] }>(`/api/provider/addons${params}`);
      setAddons(response.data || []);
    } catch (error) {
      console.error("Error loading addons:", error);
      toast.error("Failed to load addons");
    } finally {
      setIsLoading(false);
    }
  };

  const loadServices = async () => {
    try {
      const categories = await providerApi.listServiceCategories();
      // Flatten all services from all categories
      const allServices: Array<{ id: string; title: string }> = [];
      categories.forEach((category) => {
        category.services?.forEach((service) => {
          allServices.push({ id: service.id, title: service.name });
        });
      });
      setServices(allServices);
    } catch (error) {
      console.error("Error loading services:", error);
    }
  };

  const handleCreate = () => {
    setEditingAddon(null);
    setShowDialog(true);
  };

  const handleEdit = (addon: ServiceAddon) => {
    setEditingAddon(addon);
    setShowDialog(true);
  };

  const handleDelete = async (addon: ServiceAddon) => {
    if (!confirm(`Are you sure you want to delete "${addon.name}"?`)) return;

    try {
      await fetcher.delete(`/api/provider/addons/${addon.id}`);
      toast.success("Addon deleted");
      loadAddons();
    } catch {
      toast.error("Failed to delete addon");
    }
  };

  const handleSave = async (addonData: any) => {
    try {
      if (editingAddon) {
        await fetcher.put(`/api/provider/addons/${editingAddon.id}`, addonData);
        toast.success("Addon updated");
      } else {
        await fetcher.post("/api/provider/addons", addonData);
        toast.success("Addon created");
      }
      setShowDialog(false);
      setEditingAddon(null);
      loadAddons();
    } catch (error: any) {
      toast.error(error.message || "Failed to save addon");
    }
  };

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading addons..." />;
  }

  const filteredAddons = filterType === "all" ? addons : addons.filter((a) => a.type === filterType);

  return (
    <RoleGuard allowedRoles={["provider_owner"]}>
      <SettingsDetailLayout
        title="Service Addons"
        subtitle="Manage addons, products, and upgrades for your services"
        backHref="/provider/settings"
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Settings", href: "/provider/settings" },
          { label: "Service Addons" },
        ]}
      >
        <SectionCard>
          <div className="mb-6 flex justify-between items-center">
            <div className="flex-1">
              <p className="text-sm text-gray-600 mb-4">
                Create addons that customers can add to their bookings to increase revenue and enhance their experience.
              </p>
            </div>
            <Button onClick={handleCreate} className="bg-[#FF0077] hover:bg-[#D60565]">
              <Plus className="w-4 h-4 mr-2" />
              Add Addon
            </Button>
          </div>

          <div className="mb-4">
            <Select value={filterType} onValueChange={setFilterType}>
              <SelectTrigger className="w-48">
                <SelectValue placeholder="Filter by type" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Types</SelectItem>
                <SelectItem value="service">Services</SelectItem>
                <SelectItem value="product">Products</SelectItem>
                <SelectItem value="upgrade">Upgrades</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {filteredAddons.length === 0 ? (
            <EmptyState
              title="No addons"
              description="Create addons to offer additional services, products, or upgrades"
              action={{
                label: "Add Addon",
                onClick: handleCreate,
              }}
            />
          ) : (
            <div className="bg-white border rounded-lg overflow-hidden">
              <table className="w-full">
                <thead className="bg-gray-50 border-b">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Name</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Type</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Price</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Duration</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {filteredAddons.map((addon) => (
                    <tr key={addon.id} className="hover:bg-gray-50">
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-2">
                          <span className="font-medium">{addon.name}</span>
                          {addon.is_recommended && (
                            <Badge variant="default" className="bg-pink-100 text-pink-800">
                              Recommended
                            </Badge>
                          )}
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <Badge variant={addon.type === "service" ? "default" : "secondary"}>
                          {addon.type}
                        </Badge>
                      </td>
                      <td className="px-6 py-4">
                        {addon.currency} {addon.price.toFixed(2)}
                      </td>
                      <td className="px-6 py-4">
                        {addon.duration_minutes ? `${addon.duration_minutes} mins` : "-"}
                      </td>
                      <td className="px-6 py-4">
                        <Badge className={addon.is_active ? "bg-green-100 text-green-800" : "bg-gray-100 text-gray-800"}>
                          {addon.is_active ? "Active" : "Inactive"}
                        </Badge>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex gap-2">
                          <Button variant="ghost" size="sm" onClick={() => handleEdit(addon)}>
                            <Edit className="w-4 h-4" />
                          </Button>
                          <Button variant="ghost" size="sm" onClick={() => handleDelete(addon)}>
                            <Trash2 className="w-4 h-4 text-red-600" />
                          </Button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {showDialog && (
            <AddonDialog
              addon={editingAddon}
              services={services}
              onClose={() => {
                setShowDialog(false);
                setEditingAddon(null);
              }}
              onSave={handleSave}
            />
          )}
        </SectionCard>
      </SettingsDetailLayout>
    </RoleGuard>
  );
}

function AddonDialog({
  addon,
  services,
  onClose,
  onSave,
}: {
  addon: ServiceAddon | null;
  services: Array<{ id: string; title: string }>;
  onClose: () => void;
  onSave: (data: any) => void;
}) {
  const [formData, setFormData] = useState({
    name: addon?.name || "",
    description: addon?.description || "",
    type: (addon?.type || "service") as "service" | "product" | "upgrade",
    category: addon?.category || "",
    price: addon?.price || 0,
    currency: addon?.currency || "ZAR",
    duration_minutes: addon?.duration_minutes || null,
    is_active: addon?.is_active ?? true,
    is_recommended: addon?.is_recommended ?? false,
    image_url: addon?.image_url || "",
    service_ids: addon?.service_ids || [],
    max_quantity: addon?.max_quantity || null,
    requires_service: addon?.requires_service ?? false,
    sort_order: addon?.sort_order || 0,
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      duration_minutes: formData.duration_minutes || null,
      max_quantity: formData.max_quantity || null,
      price: parseFloat(formData.price.toString()),
      sort_order: parseInt(formData.sort_order.toString()),
    });
  };

  const toggleService = (serviceId: string) => {
    setFormData((prev) => ({
      ...prev,
      service_ids: prev.service_ids.includes(serviceId)
        ? prev.service_ids.filter((id) => id !== serviceId)
        : [...prev.service_ids, serviceId],
    }));
  };

  return (
    <Dialog open={true} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{addon ? "Edit Addon" : "Add Addon"}</DialogTitle>
          <DialogDescription>
            Create addons that customers can add to their bookings
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="name">Name *</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              required
            />
          </div>

          <div>
            <Label htmlFor="description">Description</Label>
            <textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              className="w-full p-2 border rounded-md min-h-[80px]"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="type">Type *</Label>
              <Select
                value={formData.type}
                onValueChange={(value) => setFormData({ ...formData, type: value as any })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="service">Service</SelectItem>
                  <SelectItem value="product">Product</SelectItem>
                  <SelectItem value="upgrade">Upgrade</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label htmlFor="category">Category</Label>
              <Input
                id="category"
                value={formData.category}
                onChange={(e) => setFormData({ ...formData, category: e.target.value })}
              />
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div>
              <Label htmlFor="price">Price *</Label>
              <Input
                id="price"
                type="number"
                min="0"
                step="0.01"
                value={formData.price}
                onChange={(e) => setFormData({ ...formData, price: parseFloat(e.target.value) || 0 })}
                required
              />
            </div>

            <div>
              <Label htmlFor="currency">Currency *</Label>
              <Input
                id="currency"
                value={formData.currency}
                onChange={(e) => setFormData({ ...formData, currency: e.target.value.toUpperCase() })}
                maxLength={3}
                required
              />
            </div>

            <div>
              <Label htmlFor="duration_minutes">Duration (mins)</Label>
              <Input
                id="duration_minutes"
                type="number"
                min="0"
                value={formData.duration_minutes || ""}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    duration_minutes: e.target.value ? parseInt(e.target.value) : null,
                  })
                }
              />
            </div>
          </div>

          <div>
            <Label htmlFor="image_url">Image URL</Label>
            <Input
              id="image_url"
              type="url"
              value={formData.image_url}
              onChange={(e) => setFormData({ ...formData, image_url: e.target.value })}
            />
          </div>

          <div>
            <Label>Associated Services</Label>
            <div className="mt-2 max-h-40 overflow-y-auto border rounded-md p-2">
              {services.length === 0 ? (
                <p className="text-sm text-gray-500">No services available</p>
              ) : (
                <div className="space-y-2">
                  {services.map((service) => (
                    <label key={service.id} className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={formData.service_ids.includes(service.id)}
                        onChange={() => toggleService(service.id)}
                      />
                      <span className="text-sm">{service.title}</span>
                    </label>
                  ))}
                </div>
              )}
            </div>
            <p className="text-xs text-gray-500 mt-1">
              Select services this addon can be added to. Leave empty to allow with any service.
            </p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="max_quantity">Max Quantity</Label>
              <Input
                id="max_quantity"
                type="number"
                min="1"
                value={formData.max_quantity || ""}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    max_quantity: e.target.value ? parseInt(e.target.value) : null,
                  })
                }
              />
            </div>

            <div>
              <Label htmlFor="sort_order">Sort Order</Label>
              <Input
                id="sort_order"
                type="number"
                value={formData.sort_order}
                onChange={(e) =>
                  setFormData({ ...formData, sort_order: parseInt(e.target.value) || 0 })
                }
              />
            </div>
          </div>

          <div className="flex items-center gap-6">
            <label className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={formData.is_active}
                onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
              />
              <span>Active</span>
            </label>
            <label className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={formData.is_recommended}
                onChange={(e) => setFormData({ ...formData, is_recommended: e.target.checked })}
              />
              <span>Recommended</span>
            </label>
            <label className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={formData.requires_service}
                onChange={(e) => setFormData({ ...formData, requires_service: e.target.checked })}
              />
              <span>Requires Service</span>
            </label>
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit" className="bg-[#FF0077] hover:bg-[#D60565]">
              {addon ? "Update" : "Create"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useSearchParams } from "next/navigation";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { useModuleConfig, useFeatureFlag } from "@/providers/ConfigBundleProvider";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import {
  Plus,
  Loader2,
  Pause,
  Play,
  MousePointer,
  Eye,
  Banknote,
  ShoppingBag,
} from "lucide-react";
import LoadingTimeout from "@/components/ui/loading-timeout";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Checkbox } from "@/components/ui/checkbox";

type Campaign = {
  id: string;
  status: string;
  budget: number;
  spent: number;
  daily_budget?: number | null;
  bid_cpc?: number;
  pack_impressions?: number | null;
  start_at: string | null;
  end_at: string | null;
  targeting?: { global_category_ids?: string[] };
  created_at: string;
};

type GlobalCategory = { id: string; name: string; slug: string };

type PerformanceSummary = {
  impressions: number;
  clicks: number;
  spend: number;
  sales: number;
};

type ImpressionPack = { id: string; impressions: number; price_zar: number; display_order: number };

export default function ProviderAdsPage() {
  const searchParams = useSearchParams();
  const adsConfig = useModuleConfig("ads") as { enabled?: boolean } | undefined;
  const adsEnabled = useFeatureFlag("ads.enabled");
  const [campaigns, setCampaigns] = useState<Campaign[]>([]);
  const [performance, setPerformance] = useState<PerformanceSummary | null>(null);
  const [packs, setPacks] = useState<ImpressionPack[]>([]);
  const [globalCategories, setGlobalCategories] = useState<GlobalCategory[]>([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [creatingPackId, setCreatingPackId] = useState<string | null>(null);
  const [updating, setUpdating] = useState<string | null>(null);
  const [editCampaign, setEditCampaign] = useState<Campaign | null>(null);
  const [form, setForm] = useState({
    budget: "",
    daily_budget: "",
    bid_cpc: "",
    global_category_ids: [] as string[],
  });
  const [createForm, setCreateForm] = useState({
    budget: "",
    daily_budget: "",
    bid_cpc: "",
    global_category_ids: [] as string[],
  });

  const enabled = Boolean(adsConfig?.enabled) || adsEnabled;

  const loadCampaigns = async () => {
    try {
      const res = await fetcher.get<{ data: Campaign[] }>("/api/provider/ads/campaigns");
      setCampaigns(res.data ?? []);
    } catch {
      setCampaigns([]);
    }
  };

  const loadPerformance = async () => {
    try {
      const res = await fetcher.get<{
        data: { summary: PerformanceSummary };
      }>("/api/provider/ads/performance");
      setPerformance(res.data?.summary ?? null);
    } catch {
      setPerformance(null);
    }
  };

  useEffect(() => {
    if (!enabled) {
      setLoading(false);
      return;
    }
    (async () => {
      setLoading(true);
      await Promise.all([loadCampaigns(), loadPerformance()]);
      try {
        const [catRes, packsRes] = await Promise.all([
          fetcher.get<{ data: GlobalCategory[] }>("/api/public/categories/global?all=true"),
          fetcher.get<{ data: ImpressionPack[] }>("/api/provider/ads/packs"),
        ]);
        setGlobalCategories(Array.isArray(catRes.data) ? catRes.data : []);
        setPacks(Array.isArray(packsRes.data) ? packsRes.data : []);
      } catch {
        setGlobalCategories([]);
        setPacks([]);
      } finally {
        setLoading(false);
      }
    })();
  }, [enabled]);

  useEffect(() => {
    if (searchParams.get("payment_success") === "1") {
      toast.success("Payment successful. Your campaign budget is now active.");
      loadCampaigns();
      loadPerformance();
      window.history.replaceState({}, "", "/provider/settings/ads");
    }
  }, [searchParams]);

  const createDraft = async () => {
    const num = parseFloat(createForm.budget);
    if (!Number.isFinite(num) || num < 0) {
      toast.error("Enter a valid total budget");
      return;
    }
    setCreating(true);
    try {
      const res = await fetcher.post<{
        data: Campaign | { campaign: Campaign; requires_payment: boolean; payment_url: string | null; order_id: string };
      }>("/api/provider/ads/campaigns", {
        budget: num,
        daily_budget: createForm.daily_budget ? parseFloat(createForm.daily_budget) : null,
        bid_cpc: createForm.bid_cpc ? parseFloat(createForm.bid_cpc) : 0,
        targeting: {
          global_category_ids:
            createForm.global_category_ids.length > 0 ? createForm.global_category_ids : undefined,
        },
      });
      const data = res.data as any;
      const campaign = data?.campaign ?? data;
      setCampaigns((prev) => [campaign, ...prev]);
      setCreateForm({ budget: "", daily_budget: "", bid_cpc: "", global_category_ids: [] });
      if (data?.requires_payment && data?.payment_url) {
        toast.success("Redirecting to payment. Complete payment to fund your campaign.");
        window.location.href = data.payment_url;
        return;
      }
      toast.success("Campaign created (draft). Activate it when ready.");
    } catch {
      toast.error("Failed to create campaign");
    } finally {
      setCreating(false);
    }
  };

  const buyPack = async (pack: ImpressionPack) => {
    setCreatingPackId(pack.id);
    try {
      const res = await fetcher.post<{
        data: Campaign | { campaign: Campaign; requires_payment: boolean; payment_url: string | null; order_id: string };
      }>("/api/provider/ads/campaigns", {
        impression_pack_id: pack.id,
        targeting: {
          global_category_ids:
            createForm.global_category_ids.length > 0 ? createForm.global_category_ids : undefined,
        },
      });
      const data = res.data as any;
      const campaign = data?.campaign ?? data;
      setCampaigns((prev) => [campaign, ...prev]);
      if (data?.requires_payment && data?.payment_url) {
        toast.success(`Redirecting to payment for ${pack.impressions} impressions.`);
        window.location.href = data.payment_url;
        return;
      }
      toast.success("Campaign created.");
    } catch {
      toast.error("Failed to create campaign");
    } finally {
      setCreatingPackId(null);
    }
  };

  const updateCampaign = async () => {
    if (!editCampaign) return;
    setUpdating(editCampaign.id);
    try {
      await fetcher.patch(`/api/provider/ads/campaigns/${editCampaign.id}`, {
        budget: form.budget ? parseFloat(form.budget) : undefined,
        daily_budget: form.daily_budget === "" ? null : form.daily_budget ? parseFloat(form.daily_budget) : undefined,
        bid_cpc: form.bid_cpc ? parseFloat(form.bid_cpc) : undefined,
        targeting: { global_category_ids: form.global_category_ids },
      });
      await loadCampaigns();
      setEditCampaign(null);
      toast.success("Campaign updated");
    } catch {
      toast.error("Failed to update campaign");
    } finally {
      setUpdating(null);
    }
  };

  const setStatus = async (campaignId: string, status: "active" | "paused" | "ended") => {
    setUpdating(campaignId);
    try {
      await fetcher.patch(`/api/provider/ads/campaigns/${campaignId}`, { status });
      await loadCampaigns();
      toast.success(status === "active" ? "Campaign activated" : status === "paused" ? "Campaign paused" : "Campaign ended");
    } catch {
      toast.error("Failed to update status");
    } finally {
      setUpdating(null);
    }
  };

  const openEdit = (c: Campaign) => {
    setEditCampaign(c);
    setForm({
      budget: String(c.budget ?? ""),
      daily_budget: c.daily_budget != null ? String(c.daily_budget) : "",
      bid_cpc: c.bid_cpc != null ? String(c.bid_cpc) : "",
      global_category_ids: c.targeting?.global_category_ids ?? [],
    });
  };

  if (loading) {
    return (
      <SettingsDetailLayout title="Paid ads" subtitle="Boost your visibility with sponsored slots.">
        <LoadingTimeout loadingMessage="Loading..." />
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      title="Growth & Marketing ΓÇö Paid ads"
      subtitle="Create and manage boosted profile campaigns. Placement in search depends on your bid, profile quality, and relevance to the customer. Set daily or total budget and target specific categories."
    >
      {!enabled && (
        <Alert className="mb-6">
          <AlertDescription>
            Paid ads are not enabled. Contact support or enable the ads module in Control Plane.
          </AlertDescription>
        </Alert>
      )}

      {/* Ad Performance Dashboard */}
      {enabled && performance && (
        <SectionCard title="Ad Performance" className="mb-6">
          <p className="text-sm text-muted-foreground mb-4">
            Track impressions, clicks, spend, and sales generated by your ads.
          </p>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="rounded-lg border p-4 flex items-center gap-3">
              <Eye className="h-8 w-8 text-muted-foreground" />
              <div>
                <p className="text-2xl font-semibold">{performance.impressions}</p>
                <p className="text-xs text-muted-foreground">Impressions</p>
              </div>
            </div>
            <div className="rounded-lg border p-4 flex items-center gap-3">
              <MousePointer className="h-8 w-8 text-muted-foreground" />
              <div>
                <p className="text-2xl font-semibold">{performance.clicks}</p>
                <p className="text-xs text-muted-foreground">Clicks</p>
              </div>
            </div>
            <div className="rounded-lg border p-4 flex items-center gap-3">
              <Banknote className="h-8 w-8 text-muted-foreground" />
              <div>
                <p className="text-2xl font-semibold">ZAR {Number(performance.spend).toFixed(2)}</p>
                <p className="text-xs text-muted-foreground">Spend</p>
              </div>
            </div>
            <div className="rounded-lg border p-4 flex items-center gap-3">
              <ShoppingBag className="h-8 w-8 text-muted-foreground" />
              <div>
                <p className="text-2xl font-semibold">{performance.sales}</p>
                <p className="text-xs text-muted-foreground">Sales (bookings)</p>
              </div>
            </div>
          </div>
        </SectionCard>
      )}

      <SectionCard title="Campaigns">
        <div className="space-y-4">
          {enabled && (
            <>
              {packs.length > 0 && (
                <div>
                  <Label className="text-base font-medium">Buy impressions</Label>
                <p className="text-sm text-muted-foreground mb-3">Choose a pack ΓÇö you pay once and get a fixed number of impressions. Easy to estimate.</p>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-4">
                  {packs.map((pack) => (
                    <button
                      key={pack.id}
                      type="button"
                      onClick={() => buyPack(pack)}
