                    variant="destructive"
                    size="sm"
                    onClick={() => deleteBlock(b.id)}
                  >
                    Remove
                  </Button>
                </div>
              ))}
            </div>
          )}
        </div>
      </SectionCard>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { PageHeader } from "@/components/provider/PageHeader";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { Separator } from "@/components/ui/separator";
import { providerApi } from "@/lib/provider-portal/api";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import { Save, MapPin } from "lucide-react";
import type { ServiceItem, ServiceCategory } from "@/lib/provider-portal/types";

interface Location {
  id: string;
  name: string;
  address_line1: string;
  city: string;
  is_active: boolean;
}

export default function GroupAppointmentsSettings() {
  const [_isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [services, setServices] = useState<ServiceItem[]>([]);
  const [locations, setLocations] = useState<Location[]>([]);

  const [settings, setSettings] = useState({
    enableGroupBooking: false,
    allowOnlineGroupBooking: false,
    maxGroupSize: 5,
    enabledLocations: [] as string[], // Location IDs where group booking is enabled
    excludedServices: [] as string[], // Service IDs excluded from online group booking
  });

  useEffect(() => {
    loadSettings();
    loadServices();
    loadLocations();
  }, []);

  const loadSettings = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{
        data: {
          enableGroupBooking: boolean;
          allowOnlineGroupBooking: boolean;
          maxGroupSize: number;
          enabledLocations: string[];
          excludedServices: string[];
        };
      }>("/api/provider/settings/group-bookings");
      setSettings(response.data);
    } catch (error) {
      console.error("Failed to load settings:", error);
      toast.error("Failed to load settings");
      // Keep defaults on error
      setSettings({
        enableGroupBooking: false,
        allowOnlineGroupBooking: false,
        maxGroupSize: 5,
        enabledLocations: [],
        excludedServices: [],
      });
    } finally {
      setIsLoading(false);
    }
  };

  const loadServices = async () => {
    try {
      const categories = await providerApi.listServiceCategories();
      const allServices = categories.flatMap((cat: ServiceCategory) => cat.services || []);
      setServices(allServices);
    } catch (error) {
      console.error("Failed to load services:", error);
    }
  };

  const loadLocations = async () => {
    try {
      const response = await fetcher.get<{ data: Location[] }>("/api/provider/locations");
      setLocations(response.data.filter(loc => loc.is_active));
    } catch (error) {
      console.error("Failed to load locations:", error);
      // Don't show error toast - locations are optional
    }
  };

  const handleSave = async () => {
    try {
      setIsSaving(true);
      await fetcher.patch("/api/provider/settings/group-bookings", {
        enable_group_booking: settings.enableGroupBooking,
        allow_online_group_booking: settings.allowOnlineGroupBooking,
        max_group_size: settings.maxGroupSize,
        enabled_locations: settings.enabledLocations,
        excluded_services: settings.excludedServices,
      });
      toast.success("Group booking settings saved successfully");
    } catch (error: any) {
      console.error("Failed to save settings:", error);
      toast.error(error.message || "Failed to save settings");
    } finally {
      setIsSaving(false);
    }
  };

  const handleServiceToggle = (serviceId: string, checked: boolean) => {
    if (checked) {
      setSettings({
        ...settings,
        excludedServices: [...settings.excludedServices, serviceId],
      });
    } else {
      setSettings({
        ...settings,
        excludedServices: settings.excludedServices.filter((id) => id !== serviceId),
      });
    }
  };

  return (
    <div>
      <PageHeader
        title="Group Appointments"
        subtitle="Configure group booking settings for your business"
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Settings", href: "/provider/settings" },
          { label: "Group Appointments" },
        ]}
      />

      <div className="space-y-6">
        {/* Enable Group Booking */}
        <SectionCard>
          <div className="space-y-4">
            <div>
              <h3 className="text-lg font-semibold mb-2">Group Booking Settings</h3>
              <p className="text-sm text-gray-600">
                Enable group appointments to allow multiple clients to be scheduled together
              </p>
            </div>

            <Separator />

            {/* Enable scheduling of group appointments */}
            <div className="flex items-start gap-4 p-4 bg-gray-50 rounded-lg">
              <Switch
                checked={settings.enableGroupBooking}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, enableGroupBooking: checked })
                }
                className="mt-1"
              />
              <div className="flex-1">
                <Label className="text-base font-medium cursor-pointer">
                  Enable scheduling of group appointments
                </Label>
                <p className="text-sm text-gray-500 mt-1">
                  Allow staff members to create and manage group appointments from the calendar
                </p>
              </div>
            </div>

            {/* Allow clients to book group appointments online */}
            {settings.enableGroupBooking && (
              <>
                <div className="flex items-start gap-4 p-4 bg-gray-50 rounded-lg">
                  <Switch
                    checked={settings.allowOnlineGroupBooking}
                    onCheckedChange={(checked) =>
                      setSettings({ ...settings, allowOnlineGroupBooking: checked })
                    }
                    className="mt-1"
                  />
                  <div className="flex-1">
                    <Label className="text-base font-medium cursor-pointer">
                      Allow clients to book group appointments online
                    </Label>
                    <p className="text-sm text-gray-500 mt-1">
                      Enable group booking in your online booking page for clients
                    </p>
                  </div>
                </div>

                {settings.allowOnlineGroupBooking && (
                  <div className="ml-0 sm:ml-12 space-y-4 p-4 bg-blue-50 rounded-lg border border-blue-200">
                    {/* Maximum Group Size */}
                    <div>
                      <Label htmlFor="maxGroupSize" className="text-sm font-medium">
                        Maximum Group Size
                      </Label>
                      <Input
                        id="maxGroupSize"
                        type="number"
                        min={2}
                        max={10}
                        value={settings.maxGroupSize}
                        onChange={(e) =>
                          setSettings({
                            ...settings,
                            maxGroupSize: parseInt(e.target.value) || 5,
                          })
                        }
                        className="mt-1.5 max-w-[120px]"
                      />
                      <p className="text-xs text-gray-500 mt-1.5">
                        Maximum number of clients that can be added to a group appointment via online booking (2-10). This limit does not apply to group appointments created from the calendar by staff members.
                      </p>
                    </div>

                    {/* Location Support */}
                    <div>
                      <Label className="text-sm font-medium mb-2 block">
                        Enable Group Booking for Locations
                      </Label>
                      <p className="text-xs text-gray-500 mb-3">
                        Select which locations support group bookings in online booking
                      </p>
                      <div className="space-y-2">
                        <div className="flex items-center gap-2 p-2 bg-white rounded border">
                          <Checkbox
                            checked={true}
                            onCheckedChange={() => {}}
                          />
                          <div className="flex items-center gap-2">
                            <MapPin className="w-4 h-4 text-gray-400" />
                            <span className="text-sm">All Locations</span>
                          </div>
                        </div>
                        {/* Location selector */}
                        {locations.length > 0 && (
                          <div className="mt-2 space-y-2">
                            {locations.map((loc) => (
                              <div key={loc.id} className="flex items-center gap-2 p-2 bg-white rounded border">
                                <Checkbox
                                  checked={settings.enabledLocations.includes(loc.id)}
                                  onCheckedChange={(checked) => {
                                    if (checked) {
                                      setSettings({
                                        ...settings,
                                        enabledLocations: [...settings.enabledLocations, loc.id],
                                      });
                                    } else {
                                      setSettings({
                                        ...settings,
                                        enabledLocations: settings.enabledLocations.filter(id => id !== loc.id),
                                      });
                                    }
                                  }}
                                />
                                <div className="flex items-center gap-2 flex-1">
                                  <MapPin className="w-4 h-4 text-gray-400" />
                                  <div>
                                    <span className="text-sm font-medium">{loc.name}</span>
                                    <p className="text-xs text-gray-500">{loc.address_line1}, {loc.city}</p>
                                  </div>
                                </div>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    </div>

                    {/* Excluded Services */}
                    <div>
                      <Label className="text-sm font-medium mb-2 block">
                        Exclude Services from Online Group Booking
                      </Label>
                      <p className="text-xs text-gray-500 mb-3">
                        Select services that should not be available for group booking online. This only excludes them from group appointments, not individual bookings.
                      </p>
                      <div className="max-h-60 overflow-y-auto border rounded-lg p-3 space-y-2 bg-white">
                        {services.length === 0 ? (
                          <p className="text-sm text-gray-500 text-center py-4">
                            No services available
                          </p>
                        ) : (
                          services.map((service) => (
                            <div
                              key={service.id}
                              className="flex items-center gap-2 p-2 hover:bg-gray-50 rounded"
                            >
                              <Checkbox
                                checked={settings.excludedServices.includes(service.id)}
                                onCheckedChange={(checked) =>
                                  handleServiceToggle(service.id, checked as boolean)
                                }
                              />
                              <Label className="text-sm font-normal cursor-pointer flex-1">
                                {service.name}
                              </Label>
                            </div>
                          ))
                        )}
                      </div>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        </SectionCard>

        {/* Save Button */}
        <div className="flex justify-end gap-3">
          <Button
            onClick={handleSave}
            disabled={isSaving}
            className="bg-[#FF0077] hover:bg-[#D60565] min-h-[44px] touch-manipulation"
          >
            <Save className="w-4 h-4 mr-2" />
            {isSaving ? "Saving..." : "Save Settings"}
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Info, Link2, Copy, Check, QrCode } from "lucide-react";
import { toast } from "sonner";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
interface MangomintSettings {
  staff_selection_mode: "client_chooses" | "anyone_default" | "hidden_auto_assign";
  require_auth_step: "checkout" | "before_time_selection";
  min_notice_minutes: number;
  max_advance_days: number;
  allow_pay_in_person: boolean;
  deposit_required: boolean;
  deposit_amount: number | null;
  deposit_percent: number | null;
}

interface OnlineBookingSettings {
  enabled: boolean;
  advanceNoticeHours: number;
  cancellationHours: number;
}

interface BookingLinkData {
  url: string;
  embed_url: string;
  slug: string;
  business_name: string;
  online_booking_enabled: boolean;
}

export default function OnlineBookingSettings() {
  const [settings, setSettings] = useState<OnlineBookingSettings>({
    enabled: true,
    advanceNoticeHours: 24,
    cancellationHours: 24,
  });
  const [originalSettings, setOriginalSettings] = useState<OnlineBookingSettings | null>(null);
  const [mangomint, setMangomint] = useState<MangomintSettings | null>(null);
  const [originalMangomint, setOriginalMangomint] = useState<MangomintSettings | null>(null);
  const [bookingLink, setBookingLink] = useState<BookingLinkData | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showQr, setShowQr] = useState(false);
  const [qrDataUrl, setQrDataUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [isSavingMangomint, setIsSavingMangomint] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadSettings();
  }, []);

  useEffect(() => {
    if (settings.enabled) {
      fetcher
        .get<{ data: BookingLinkData }>("/api/provider/booking-link")
        .then((res) => setBookingLink((res as any)?.data ?? res))
        .catch(() => setBookingLink(null));
    } else {
      setBookingLink(null);
    }
  }, [settings.enabled]);

  const loadSettings = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const [bookingRes, mangomintRes] = await Promise.all([
        fetcher.get<{ data: OnlineBookingSettings }>(
          "/api/provider/settings/online-booking"
        ),
        fetcher
          .get<{ data: MangomintSettings }>(
            "/api/provider/settings/online-booking-mangomint"
          )
          .catch(() => null),
      ]);
      setSettings(bookingRes.data);
      setOriginalSettings(bookingRes.data);
      const m = mangomintRes && (mangomintRes as { data?: MangomintSettings }).data;
      const mangomintDefaults: MangomintSettings = {
        staff_selection_mode: "client_chooses",
        require_auth_step: "checkout",
        min_notice_minutes: 60,
        max_advance_days: 90,
        allow_pay_in_person: false,
        deposit_required: false,
        deposit_amount: null,
        deposit_percent: null,
      };
      setMangomint(m ?? mangomintDefaults);
      setOriginalMangomint(m ?? mangomintDefaults);
    } catch (err) {
      const errorMessage =
        err instanceof FetchError
          ? err.message
          : "Failed to load online booking settings";
      setError(errorMessage);
      console.error("Error loading online booking settings:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSaveMangomint = async () => {
    if (!mangomint) return;
    try {
      setIsSavingMangomint(true);
      const response = await fetcher.patch<{ data: MangomintSettings }>(
        "/api/provider/settings/online-booking-mangomint",
        mangomint
      );
      setMangomint(response.data);
      setOriginalMangomint(response.data);
      toast.success("Booking flow settings updated");
    } catch (err) {
      toast.error(
        err instanceof FetchError
          ? err.message
          : "Failed to update booking flow settings"
      );
    } finally {
      setIsSavingMangomint(false);
    }
  };

  const generateQr = async (url: string) => {
    try {
      const qrcode = await import("qrcode");
      const dataUrl = await qrcode.toDataURL(url, {
        width: 256,
        margin: 2,
      });
      setQrDataUrl(dataUrl);
      setShowQr(true);
    } catch {
      toast.error("Failed to generate QR code");
    }
  };

  const handleSave = async () => {
    try {
      setIsSaving(true);

      // Validate settings before saving
      if (settings.advanceNoticeHours < 0 || settings.advanceNoticeHours > 168) {
        toast.error("Advance notice must be between 0 and 168 hours");
        return;
      }

      if (settings.cancellationHours < 0 || settings.cancellationHours > 168) {
        toast.error("Cancellation notice must be between 0 and 168 hours");
        return;
      }

      const response = await fetcher.patch<{ data: OnlineBookingSettings }>(
        "/api/provider/settings/online-booking",
        settings
      );

      // Update with response data to ensure consistency
      setSettings(response.data);
      setOriginalSettings(response.data);
      toast.success("Online booking settings updated successfully");
    } catch (err) {
      const errorMessage =
        err instanceof FetchError
          ? err.message
          : "Failed to update online booking settings";
      toast.error(errorMessage);
      console.error("Error saving online booking settings:", err);
    } finally {
      setIsSaving(false);
    }
  };

  const hasChanges =
    originalSettings && JSON.stringify(settings) !== JSON.stringify(originalSettings);
  const hasMangomintChanges =
    mangomint &&
    originalMangomint &&
    JSON.stringify(mangomint) !== JSON.stringify(originalMangomint);

  const breadcrumbs = [
    { label: "Home", href: "/" },
    { label: "Provider", href: "/provider" },
    { label: "Settings", href: "/provider/settings" },
    { label: "Online Booking" },
  ];

  if (isLoading) {
    return (
      <SettingsDetailLayout
        title="Online Booking"
        subtitle="Configure online booking preferences"
        breadcrumbs={breadcrumbs}
      >
        <LoadingTimeout loadingMessage="Loading online booking settings..." />
      </SettingsDetailLayout>
    );
  }

  if (error && !originalSettings) {
    return (
      <SettingsDetailLayout
        title="Online Booking"
        subtitle="Configure online booking preferences"
        breadcrumbs={breadcrumbs}
      >
        <EmptyState
          title="Failed to load settings"
          description={error}
          action={{
            label: "Retry",
            onClick: loadSettings,
          }}
        />
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      title="Online Booking"
      subtitle="Configure online booking preferences"
      onSave={handleSave}
      saveLabel={isSaving ? "Saving..." : "Save Changes"}
      saveDisabled={isSaving || !hasChanges}
      breadcrumbs={breadcrumbs}
    >
      <SectionCard className="w-full">
        <div className="space-y-6 sm:space-y-8">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div className="flex-1">
              <Label className="text-base sm:text-lg font-medium block mb-2">
                Enable Online Booking
              </Label>
              <p className="text-sm text-gray-600">
                Allow clients to book appointments online through your booking page
              </p>
            </div>
            <div className="flex-shrink-0">
              <Switch
                checked={settings.enabled}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, enabled: checked })
                }
              />
            </div>
          </div>

          {settings.enabled && (
            <>
              <div className="border-t pt-6 space-y-6">
                <Alert className="border-blue-200 bg-blue-50">
                  <Info className="w-4 h-4 text-blue-600" />
                  <AlertDescription className="text-sm text-blue-800">
                    Configure advance notice and cancellation requirements for online bookings.
                  </AlertDescription>
                </Alert>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                  <div>
                    <Label htmlFor="advanceNoticeHours" className="text-sm sm:text-base font-medium block mb-2">
                      Advance Notice (Hours)
                    </Label>
                    <Input
                      id="advanceNoticeHours"
                      type="number"
                      min="0"
                      max="168"
                      value={settings.advanceNoticeHours}
                      onChange={(e) => {
                        const value = parseInt(e.target.value) || 0;
                        const clampedValue = Math.max(0, Math.min(168, value));
                        setSettings({
                          ...settings,
                          advanceNoticeHours: clampedValue,
                        });
                      }}
                      className="w-full"
                    />
                    <p className="text-xs sm:text-sm text-gray-500 mt-2">
                      Minimum hours in advance clients must book
                    </p>
                  </div>

                  <div>
                    <Label htmlFor="cancellationHours" className="text-sm sm:text-base font-medium block mb-2">
                      Cancellation Notice (Hours)
                    </Label>
                    <Input
                      id="cancellationHours"
                      type="number"
                      min="0"
                      max="168"
                      value={settings.cancellationHours}
                      onChange={(e) => {
                        const value = parseInt(e.target.value) || 0;
                        const clampedValue = Math.max(0, Math.min(168, value));
                        setSettings({
                          ...settings,
                          cancellationHours: clampedValue,
                        });
                      }}
                      className="w-full"
                    />
                    <p className="text-xs sm:text-sm text-gray-500 mt-2">
                      Minimum hours before appointment for cancellation
                    </p>
                  </div>
                </div>
              </div>

              {bookingLink && (
                <div className="border-t pt-6 space-y-6">
                  <h3 className="font-medium flex items-center gap-2">
                    <Link2 className="h-4 w-4" />
                    Direct booking link
                  </h3>
                  <div className="flex gap-2">
                    <Input
                      readOnly
                      value={bookingLink.url}
                      className="font-mono text-sm"
                    />
                    <Button
                      variant="outline"
                      size="icon"
                      onClick={() => {
                        navigator.clipboard.writeText(bookingLink.url);
                        setCopiedField("url");
                        toast.success("Link copied to clipboard");
                        setTimeout(() => setCopiedField(null), 2000);
                      }}
                    >
                      {copiedField === "url" ? (
                        <Check className="h-4 w-4 text-green-600" />
                      ) : (
                        <Copy className="h-4 w-4" />
                      )}
                    </Button>
                    <Button
                      variant="outline"
                      size="icon"
                      onClick={() => generateQr(bookingLink.url)}
                      title="Show QR code"
                    >
                      <QrCode className="h-4 w-4" />
                    </Button>
                  </div>
                  {showQr && qrDataUrl && (
                    <div className="flex flex-col items-center gap-2 p-4 bg-muted/30 rounded-lg">
                      <img
                        src={qrDataUrl}
                        alt="Booking QR code"
                        className="w-48 h-48 object-contain"
                      />
                      <p className="text-xs text-muted-foreground">
                        Clients can scan to open your booking page
                      </p>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => setShowQr(false)}
                      >
                        Close
                      </Button>
                    </div>
                  )}
                  <p className="text-xs text-gray-500">
                    Share this link so clients can book directly.
                  </p>

                  {/* Embed URL */}
                  <div className="space-y-2">
                    <Label className="font-medium">Embed URL (for iframes)</Label>
                    <div className="flex gap-2">
                      <Input
                        readOnly
                        value={bookingLink.embed_url}
                        className="font-mono text-sm"
                      />
                      <Button
                        variant="outline"
                        size="icon"
                        onClick={() => {
                          navigator.clipboard.writeText(bookingLink.embed_url);
                          setCopiedField("embed_url");
                          toast.success("Embed URL copied");
                          setTimeout(() => setCopiedField(null), 2000);
                        }}
                      >
                        {copiedField === "embed_url" ? (
                          <Check className="h-4 w-4 text-green-600" />
                        ) : (
                          <Copy className="h-4 w-4" />
                        )}
                      </Button>
                    </div>
                  </div>

                  {/* Iframe snippet */}
                  <div className="space-y-2">
                    <Label className="font-medium">Embed with iframe</Label>
                    <p className="text-xs text-gray-500 mb-2">
                      Paste this code into your website to show the full booking flow in an iframe.
                    </p>
                    <div className="relative group">
                      <pre className="p-3 pr-10 bg-muted rounded-md text-xs overflow-x-auto">
                        <code>{`<iframe src="${bookingLink.embed_url}" width="100%" height="800" frameborder="0" title="Book an appointment"></iframe>`}</code>
                      </pre>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="absolute top-2 right-2 h-7 w-7"
                        onClick={() => {
                          const snippet = `<iframe src="${bookingLink.embed_url}" width="100%" height="800" frameborder="0" title="Book an appointment"></iframe>`;
                          navigator.clipboard.writeText(snippet);
                          setCopiedField("iframe");
                          toast.success("Iframe code copied");
                          setTimeout(() => setCopiedField(null), 2000);
                        }}
                      >
                        {copiedField === "iframe" ? (
                          <Check className="h-4 w-4 text-green-600" />
                        ) : (
                          <Copy className="h-4 w-4" />
                        )}
                      </Button>
                    </div>
                  </div>

                  {/* Script embed instructions */}
                  <div className="space-y-2">
                    <Label className="font-medium">Embed with script (Book Now button)</Label>
                    <p className="text-xs text-gray-500 mb-2">
                      Add a &quot;Book Now&quot; button that opens the booking page in a new tab. Replace{" "}
                      <code className="bg-muted px-1 rounded">{bookingLink.slug || "your-slug"}</code>{" "}
