                    className="mt-1"
                  />
                  <div className="flex-1">
                    <Label className="text-sm font-medium cursor-pointer">
                      Allow client self check-in
                    </Label>
                    <p className="text-xs text-gray-500 mt-1">
                      Clients can check themselves into the waiting room via online booking or mobile app
                    </p>
                  </div>
                </div>

                <div className="flex items-start gap-4 p-3 bg-white rounded-lg">
                  <Switch
                    checked={settings.showEstimatedWaitTime}
                    onCheckedChange={(checked) =>
                      setSettings({ ...settings, showEstimatedWaitTime: checked })
                    }
                    className="mt-1"
                  />
                  <div className="flex-1">
                    <Label className="text-sm font-medium cursor-pointer">
                      Show estimated wait time
                    </Label>
                    <p className="text-xs text-gray-500 mt-1">
                      Display estimated wait time to clients in the waiting room
                    </p>
                  </div>
                </div>
              </div>
            )}
          </div>
        </SectionCard>

        {/* Online Waitlist */}
        <SectionCard>
          <div className="space-y-4">
            <div>
              <h3 className="text-lg font-semibold mb-2 flex items-center gap-2">
                <MessageSquare className="w-5 h-5" />
                Online Waitlist
              </h3>
              <p className="text-sm text-gray-600">
                Allow clients to join waitlist from online booking
              </p>
            </div>

            <Separator />

            <div className="flex items-start gap-4 p-4 bg-gray-50 rounded-lg">
              <Switch
                checked={settings.allowOnlineWaitlist}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, allowOnlineWaitlist: checked })
                }
                className="mt-1"
              />
              <div className="flex-1">
                <Label className="text-base font-medium cursor-pointer">
                  Allow clients to join waitlist online
                </Label>
                <p className="text-sm text-gray-500 mt-1">
                  Clients can add themselves to the waitlist when no appointments are available in online booking
                </p>
              </div>
            </div>
          </div>
        </SectionCard>

        {/* General Settings */}
        <SectionCard>
          <div className="space-y-4">
            <div>
              <h3 className="text-lg font-semibold mb-2 flex items-center gap-2">
                <Clock className="w-5 h-5" />
                General Settings
              </h3>
            </div>

            <Separator />

            <div className="space-y-4">
              <div>
                <Label htmlFor="maxWaitlistSize" className="text-sm font-medium">
                  Maximum Waitlist Size
                </Label>
                <Input
                  id="maxWaitlistSize"
                  type="number"
                  min={10}
                  max={500}
                  value={settings.maxWaitlistSize}
                  onChange={(e) =>
                    setSettings({
                      ...settings,
                      maxWaitlistSize: parseInt(e.target.value) || 50,
                    })
                  }
                  className="mt-1.5 max-w-[120px]"
                />
                <p className="text-xs text-gray-500 mt-1.5">
                  Maximum number of active waitlist entries allowed
                </p>
              </div>

              <div>
                <Label htmlFor="autoRemoveAfterDays" className="text-sm font-medium">
                  Auto-remove after (days)
                </Label>
                <Input
                  id="autoRemoveAfterDays"
                  type="number"
                  min={1}
                  max={365}
                  value={settings.autoRemoveAfterDays}
                  onChange={(e) =>
                    setSettings({
                      ...settings,
                      autoRemoveAfterDays: parseInt(e.target.value) || 30,
                    })
                  }
                  className="mt-1.5 max-w-[120px]"
                />
                <p className="text-xs text-gray-500 mt-1.5">
                  Automatically remove waitlist entries after this many days if not converted to appointment
                </p>
              </div>
            </div>
          </div>
        </SectionCard>

        {/* Save Button */}
        <div className="flex justify-end gap-3">
          <Button
            onClick={handleSave}
            disabled={isSaving}
            className="bg-[#FF0077] hover:bg-[#D60565] min-h-[44px] touch-manipulation"
          >
            <Save className="w-4 h-4 mr-2" />
            {isSaving ? "Saving..." : "Save Settings"}
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import React from "react";
import { useAppointmentSettings } from "@/hooks/useAppointmentSettings";
import { APPOINTMENT_STATUS } from "@/lib/provider-portal/constants";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Info } from "lucide-react";

const statusLabels: Record<string, string> = {
  pending: "Pending",
  booked: "Booked",
  started: "Started",
  completed: "Completed",
  cancelled: "Cancelled",
  no_show: "No Show",
};

export default function AppointmentSettingsPage() {
  const { settings, isLoading, error, updateSettings } = useAppointmentSettings();
  const [localSettings, setLocalSettings] = React.useState(settings);
  const [isSaving, setIsSaving] = React.useState(false);
  const [originalSettings, setOriginalSettings] = React.useState(settings);

  // Update local settings when settings change
  React.useEffect(() => {
    if (settings) {
      setLocalSettings(settings);
      setOriginalSettings(settings);
    }
  }, [settings]);

  const handleSave = async () => {
    try {
      setIsSaving(true);
      await updateSettings(localSettings);
      setOriginalSettings(localSettings);
      toast.success("Appointment settings saved successfully");
    } catch (error: any) {
      toast.error(error.message || "Failed to save settings");
    } finally {
      setIsSaving(false);
    }
  };

  const hasChanges = originalSettings && JSON.stringify(localSettings) !== JSON.stringify(originalSettings);

  const breadcrumbs = [
    { label: "Home", href: "/" },
    { label: "Provider", href: "/provider" },
    { label: "Settings", href: "/provider/settings" },
    { label: "Appointment Settings" },
  ];

  if (isLoading) {
    return (
      <SettingsDetailLayout
        title="Appointment Settings"
        subtitle="Configure default appointment status and confirmation behavior"
        breadcrumbs={breadcrumbs}
      >
        <LoadingTimeout loadingMessage="Loading appointment settings..." />
      </SettingsDetailLayout>
    );
  }

  if (error && !originalSettings) {
    return (
      <SettingsDetailLayout
        title="Appointment Settings"
        subtitle="Configure default appointment status and confirmation behavior"
        breadcrumbs={breadcrumbs}
      >
        <EmptyState
          title="Failed to load settings"
          description={error}
          action={{
            label: "Retry",
            onClick: () => window.location.reload(),
          }}
        />
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      title="Appointment Settings"
      subtitle="Configure default appointment status and confirmation behavior"
      onSave={handleSave}
      saveLabel={isSaving ? "Saving..." : "Save Changes"}
      saveDisabled={isSaving || !hasChanges}
      breadcrumbs={breadcrumbs}
    >
      <SectionCard className="w-full">
        <div className="space-y-6 sm:space-y-8">
          {/* Default Status Selection */}
          <div className="space-y-4">
            <div>
              <Label htmlFor="default-status" className="text-base sm:text-lg font-medium block mb-2">
                Default Appointment Status
              </Label>
              <p className="text-sm text-gray-600 mb-4">
                Choose the default status for new appointments when they are created
              </p>
              <Select
                value={localSettings?.defaultAppointmentStatus || APPOINTMENT_STATUS.BOOKED}
                onValueChange={(value) =>
                  setLocalSettings({ ...localSettings, defaultAppointmentStatus: value })
                }
              >
                <SelectTrigger id="default-status" className="w-full sm:w-auto min-w-[200px]">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {Object.entries(APPOINTMENT_STATUS).map(([key, value]) => (
                    <SelectItem key={key} value={value}>
                      {statusLabels[value] || value}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <p className="text-xs sm:text-sm text-gray-500 mt-2">
                New appointments will be created with this status unless specified otherwise
              </p>
            </div>
          </div>

          {/* Auto-Confirm Switch */}
          <div className="border-t pt-6">
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
              <div className="flex-1">
                <Label htmlFor="auto-confirm" className="text-base sm:text-lg font-medium block mb-2">
                  Auto-Confirm Appointments
                </Label>
                <p className="text-sm text-gray-600">
                  Automatically confirm appointments when they are created (if default status is "Pending")
                </p>
              </div>
              <div className="flex-shrink-0">
                <Switch
                  id="auto-confirm"
                  checked={localSettings?.autoConfirmAppointments || false}
                  onCheckedChange={(checked) =>
                    setLocalSettings({ ...localSettings, autoConfirmAppointments: checked })
                  }
                />
              </div>
            </div>
          </div>

          {/* Require Confirmation Switch */}
          <div className="border-t pt-6">
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
              <div className="flex-1">
                <Label htmlFor="require-confirmation" className="text-base sm:text-lg font-medium block mb-2">
                  Require Confirmation
                </Label>
                <p className="text-sm text-gray-600">
                  Require manual confirmation before appointments are marked as "Booked"
                </p>
              </div>
              <div className="flex-shrink-0">
                <Switch
                  id="require-confirmation"
                  checked={localSettings?.requireConfirmationForBookings || false}
                  onCheckedChange={(checked) =>
                    setLocalSettings({ ...localSettings, requireConfirmationForBookings: checked })
                  }
                />
              </div>
            </div>
          </div>

          {/* Info Alert */}
          <Alert className="border-blue-200 bg-blue-50">
            <Info className="w-4 h-4 text-blue-600" />
            <AlertDescription className="text-sm text-blue-800">
              These settings apply to all new appointments created through the provider portal.
              Existing appointments are not affected.
            </AlertDescription>
          </Alert>

          {/* Last Updated */}
          {localSettings?.updatedAt && (
            <p className="text-xs text-gray-500 text-center pt-4 border-t">
              Last updated: {new Date(localSettings.updatedAt).toLocaleString()}
            </p>
          )}
        </div>
      </SectionCard>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import { Download, ArrowLeft, CheckCircle2, Clock, AlertCircle, FileText } from "lucide-react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

interface Invoice {
  id: string;
  invoice_number: string;
  invoice_type: string;
  period_start: string;
  period_end: string;
  issue_date: string;
  due_date: string;
  subtotal: number;
  tax_rate: number;
  tax_amount: number;
  total_amount: number;
  amount_paid: number;
  amount_due: number;
  status: string;
  notes: string | null;
  line_items: any[];
  payments: any[];
}

export default function InvoiceDetailPage() {
  const params = useParams();
  const router = useRouter();
  const invoiceId = params.id as string;
  const [invoice, setInvoice] = useState<Invoice | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    loadInvoice();
  }, [invoiceId]);

  const loadInvoice = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data: Invoice }>(
        `/api/provider/invoices/${invoiceId}`
      );
      setInvoice(response.data);
    } catch (error) {
      console.error("Error loading invoice:", error);
      toast.error("Failed to load invoice");
    } finally {
      setIsLoading(false);
    }
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-ZA", {
      style: "currency",
      currency: "ZAR",
    }).format(amount);
  };

  const formatDate = (date: string) => {
    return new Date(date).toLocaleDateString("en-ZA", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  const getStatusBadge = (status: string) => {
    const variants: Record<string, { variant: "default" | "secondary" | "outline"; icon: any }> = {
      paid: { variant: "default", icon: CheckCircle2 },
      sent: { variant: "secondary", icon: Clock },
      overdue: { variant: "outline", icon: AlertCircle },
      draft: { variant: "outline", icon: FileText },
      partially_paid: { variant: "secondary", icon: Clock },
    };

    const config = variants[status] || { variant: "outline" as const, icon: FileText };
    const Icon = config.icon;

    return (
      <Badge variant={config.variant} className="flex items-center gap-1 w-fit">
        <Icon className="w-3 h-3" />
        {status.replace("_", " ").toUpperCase()}
      </Badge>
    );
  };

  const breadcrumbs = [
    { label: "Home", href: "/" },
    { label: "Provider", href: "/provider" },
    { label: "Settings", href: "/provider/settings" },
    { label: "Billing", href: "/provider/settings/billing" },
    { label: "Invoice" },
  ];

  if (isLoading) {
    return (
      <SettingsDetailLayout
        title="Invoice Details"
        subtitle="View invoice information"
        breadcrumbs={breadcrumbs}
      >
        <LoadingTimeout loadingMessage="Loading invoice..." />
      </SettingsDetailLayout>
    );
  }

  if (!invoice) {
    return (
      <SettingsDetailLayout
        title="Invoice Details"
        subtitle="View invoice information"
        breadcrumbs={breadcrumbs}
      >
        <div className="text-center py-12">
          <p className="text-gray-600">Invoice not found</p>
          <Button
            variant="outline"
            onClick={() => router.back()}
            className="mt-4"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            Go Back
          </Button>
        </div>
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      title="Invoice Details"
      subtitle={`Invoice ${invoice.invoice_number}`}
      breadcrumbs={breadcrumbs}
    >
      <div className="space-y-6">
        {/* Invoice Header */}
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 p-4 bg-gray-50 rounded-lg">
          <div>
            <h2 className="text-2xl font-bold text-[#FF0077]">{invoice.invoice_number}</h2>
            <p className="text-sm text-gray-600 mt-1">
              {formatDate(invoice.issue_date)}
            </p>
          </div>
          <div className="flex items-center gap-4">
            {getStatusBadge(invoice.status)}
            <Button
              variant="outline"
              onClick={() => window.open(`/api/provider/invoices/${invoiceId}/download`, "_blank")}
            >
              <Download className="w-4 h-4 mr-2" />
              Download
            </Button>
          </div>
        </div>

        {/* Invoice Details */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="p-4 border border-gray-200 rounded-lg">
            <h3 className="font-semibold text-sm text-gray-600 mb-2">Billing Period</h3>
            <p className="text-sm">
              {formatDate(invoice.period_start)} - {formatDate(invoice.period_end)}
            </p>
          </div>
          <div className="p-4 border border-gray-200 rounded-lg">
            <h3 className="font-semibold text-sm text-gray-600 mb-2">Due Date</h3>
            <p className="text-sm">{formatDate(invoice.due_date)}</p>
          </div>
        </div>

        {/* Line Items */}
        <div className="border border-gray-200 rounded-lg overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Description</TableHead>
                <TableHead className="text-right">Quantity</TableHead>
                <TableHead className="text-right">Unit Price</TableHead>
                <TableHead className="text-right">Total</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {(invoice.line_items || []).map((item: any) => (
                <TableRow key={item.id}>
                  <TableCell>{item.description}</TableCell>
                  <TableCell className="text-right">{item.quantity}</TableCell>
                  <TableCell className="text-right">{formatCurrency(item.unit_price)}</TableCell>
                  <TableCell className="text-right font-medium">
                    {formatCurrency(item.total_price)}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>

        {/* Totals */}
        <div className="flex justify-end">
          <div className="w-full md:w-96 space-y-2">
            <div className="flex justify-between text-sm">
              <span className="text-gray-600">Subtotal:</span>
              <span>{formatCurrency(invoice.subtotal)}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-gray-600">Tax ({invoice.tax_rate}%):</span>
              <span>{formatCurrency(invoice.tax_amount)}</span>
            </div>
            <div className="flex justify-between text-lg font-bold pt-2 border-t">
              <span>Total:</span>
              <span>{formatCurrency(invoice.total_amount)}</span>
            </div>
            {invoice.amount_paid > 0 && (
              <>
                <div className="flex justify-between text-sm pt-2 border-t">
                  <span className="text-gray-600">Amount Paid:</span>
                  <span className="text-green-600">{formatCurrency(invoice.amount_paid)}</span>
                </div>
                <div className="flex justify-between text-lg font-bold pt-2 border-t">
                  <span>Amount Due:</span>
                  <span>{formatCurrency(invoice.amount_due)}</span>
                </div>
              </>
            )}
          </div>
        </div>

        {/* Payments */}
        {invoice.payments && invoice.payments.length > 0 && (
          <div>
            <h3 className="font-semibold mb-4">Payment History</h3>
            <div className="border border-gray-200 rounded-lg overflow-hidden">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Date</TableHead>
                    <TableHead>Amount</TableHead>
                    <TableHead>Reference</TableHead>
                    <TableHead>Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {invoice.payments.map((payment: any) => (
                    <TableRow key={payment.id}>
                      <TableCell>{formatDate(payment.payment_date)}</TableCell>
                      <TableCell className="font-medium">
                        {formatCurrency(payment.amount)}
                      </TableCell>
                      <TableCell>{payment.payment_reference || "-"}</TableCell>
                      <TableCell>
                        <Badge variant={payment.status === "completed" ? "default" : "outline"}>
                          {payment.status}
                        </Badge>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </div>
        )}

        {/* Notes */}
        {invoice.notes && (
          <div className="p-4 bg-gray-50 rounded-lg">
            <h3 className="font-semibold text-sm text-gray-600 mb-2">Notes</h3>
            <p className="text-sm">{invoice.notes}</p>
          </div>
        )}

        {/* Back Button */}
        <div className="flex justify-start">
          <Button variant="outline" onClick={() => router.back()}>
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Billing
          </Button>
        </div>
      </div>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Plus, FileText, Loader2, CreditCard, Trash2, Download, Eye, CheckCircle2, Clock, AlertCircle } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import EmptyState from "@/components/ui/empty-state";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import AddressForm from "@/components/mapbox/AddressForm";

interface BillingData {
  billingAddress: any;
  billingEmail: string | null;
  billingPhone: string | null;
  paymentMethods: any[];
  invoices: any[];
}

export default function BillingSettings() {
  const [billingData, setBillingData] = useState<BillingData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showBillingDialog, setShowBillingDialog] = useState(false);
  const [billingForm, setBillingForm] = useState({
    email: "",
    phone: "",
    address: null as any,
  });

  useEffect(() => {
    loadBillingData();
  }, []);

  const loadBillingData = async () => {
    try {
      setIsLoading(true);
      setError(null);

      // Load billing settings, payment methods, and invoices in parallel
      const [billingResponse, paymentMethodsResponse, invoicesResponse] = await Promise.all([
        fetcher.get<{ data: BillingData }>("/api/provider/settings/billing"),
        fetcher.get<{ data: any[] }>("/api/provider/payment-methods").catch(() => ({ data: [] })),
        fetcher.get<{ data: { invoices: any[] } }>("/api/provider/invoices").catch(() => ({ data: { invoices: [] } })),
      ]);

      const billingInfo = billingResponse.data;
      const paymentMethods = paymentMethodsResponse.data || [];
      const invoices = invoicesResponse.data?.invoices || [];

      setBillingData({
        ...billingInfo,
        paymentMethods,
        invoices,
      });
      setBillingForm({
        email: billingInfo.billingEmail || "",
        phone: billingInfo.billingPhone || "",
        address: billingInfo.billingAddress,
      });
    } catch (err) {
      const errorMessage =
        err instanceof FetchError
          ? err.message
          : "Failed to load billing information";
      setError(errorMessage);
      console.error("Error loading billing data:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSaveBilling = async () => {
    // Validate address if provided (address is optional for billing, but if provided, must be complete)
    if (billingForm.address) {
      if (billingForm.address.address_line1 && (!billingForm.address.city || !billingForm.address.country)) {
        toast.error("Please complete the address (city and country are required if address is provided)");
        return;
      }
    }

    try {
      setIsSaving(true);
      await fetcher.patch("/api/provider/settings/billing", {
        billingEmail: billingForm.email || null,
        billingPhone: billingForm.phone || null,
        billingAddress: billingForm.address,
      });
      setShowBillingDialog(false);
      toast.success("Billing information updated successfully");
      loadBillingData();
    } catch (err) {
      const errorMessage =
        err instanceof FetchError
          ? err.message
          : "Failed to update billing information";
      toast.error(errorMessage);
      console.error("Error saving billing data:", err);
    } finally {
      setIsSaving(false);
    }
  };

  const breadcrumbs = [
    { label: "Home", href: "/" },
    { label: "Provider", href: "/provider" },
    { label: "Settings", href: "/provider/settings" },
    { label: "Billing" },
  ];

  if (isLoading) {
    return (
      <SettingsDetailLayout
        title="Billing details and Invoices"
        subtitle="Manage your billing information and view invoices"
        breadcrumbs={breadcrumbs}
      >
        <LoadingTimeout loadingMessage="Loading billing information..." />
      </SettingsDetailLayout>
    );
  }

  if (error && !billingData) {
    return (
      <SettingsDetailLayout
        title="Billing details and Invoices"
        subtitle="Manage your billing information and view invoices"
        breadcrumbs={breadcrumbs}
      >
        <EmptyState
          title="Failed to load billing information"
          description={error}
          action={{
            label: "Retry",
            onClick: loadBillingData,
          }}
        />
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      title="Billing details and Invoices"
      subtitle="Manage your billing information and view invoices"
      breadcrumbs={breadcrumbs}
    >
      {/* Billing Address */}
      <SectionCard title="Billing Address" className="w-full">
        {billingData?.billingAddress || billingForm.email || billingForm.phone ? (
          <div className="space-y-4">
            {billingForm.email && (
              <div>
                <Label className="text-sm font-medium text-gray-700">Billing Email</Label>
                <p className="text-sm text-gray-600 mt-1">{billingForm.email}</p>
              </div>
            )}
            {billingForm.phone && (
              <div>
                <Label className="text-sm font-medium text-gray-700">Billing Phone</Label>
                <p className="text-sm text-gray-600 mt-1">{billingForm.phone}</p>
              </div>
            )}
            {billingForm.address && (
              <div>
                <Label className="text-sm font-medium text-gray-700">Billing Address</Label>
                <p className="text-sm text-gray-600 mt-1">
                  {billingForm.address.address_line1}
                  {billingForm.address.city && `, ${billingForm.address.city}`}
                  {billingForm.address.country && `, ${billingForm.address.country}`}
                </p>
              </div>
            )}
            <Button
              onClick={() => setShowBillingDialog(true)}
              variant="outline"
              className="w-full sm:w-auto"
            >
              <Plus className="w-4 h-4 mr-2" />
              Update Billing Details
            </Button>
          </div>
        ) : (
          <Alert className="border-gray-200 bg-gray-50">
            <AlertDescription className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
              <span className="text-sm text-gray-600">No billing address added</span>
              <Button
                size="sm"
                className="bg-[#FF0077] hover:bg-[#D60565] w-full sm:w-auto"
                onClick={() => setShowBillingDialog(true)}
              >
                <Plus className="w-4 h-4 mr-2" />
                Add billing details
              </Button>
            </AlertDescription>
          </Alert>
        )}
      </SectionCard>

      {/* Default Payment Method */}
      <SectionCard title="Default Payment Method" className="w-full">
        <PaymentMethodsSection
          paymentMethods={billingData?.paymentMethods || []}
          onRefresh={loadBillingData}
        />
      </SectionCard>

      {/* Sales & Fees */}
      <SectionCard title="Sales & Fees" className="w-full">
        <InvoicesSection
          invoices={billingData?.invoices || []}
          onRefresh={loadBillingData}
        />
      </SectionCard>

      {/* Billing Details Dialog */}
      <Dialog open={showBillingDialog} onOpenChange={setShowBillingDialog}>
        <DialogContent className="max-w-[95vw] sm:max-w-2xl max-h-[95vh] overflow-y-auto p-4 sm:p-6">
          <DialogHeader>
            <DialogTitle>Billing Details</DialogTitle>
            <DialogDescription>
              Update your billing address and contact information
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 sm:space-y-6">
            <div>
              <Label htmlFor="billingEmail" className="text-sm sm:text-base">
                Billing Email
              </Label>
              <Input
                id="billingEmail"
                type="email"
                value={billingForm.email}
                onChange={(e) => setBillingForm({ ...billingForm, email: e.target.value })}
                placeholder="billing@example.com"
                className="mt-1 w-full"
              />
            </div>
            <div>
              <Label htmlFor="billingPhone" className="text-sm sm:text-base">
                Billing Phone
              </Label>
              <Input
                id="billingPhone"
                type="tel"
                value={billingForm.phone}
                onChange={(e) => setBillingForm({ ...billingForm, phone: e.target.value })}
                placeholder="+27 11 123 4567"
                className="mt-1 w-full"
              />
            </div>
            <div>
              <Label className="text-sm sm:text-base mb-2 block">Billing Address</Label>
              <AddressForm
                initialAddress={billingForm.address}
                onSave={(address) => setBillingForm({ ...billingForm, address })}
                showLabel={false}
                asForm={false}
              />
            </div>
          </div>
          <DialogFooter className="flex-col sm:flex-row gap-2">
            <Button
              variant="outline"
              onClick={() => setShowBillingDialog(false)}
              className="w-full sm:w-auto"
            >
              Cancel
            </Button>
            <Button
              onClick={handleSaveBilling}
              disabled={isSaving}
              className="bg-[#FF0077] hover:bg-[#D60565] w-full sm:w-auto"
            >
              {isSaving ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Saving...
                </>
              ) : (
                "Save Changes"
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </SettingsDetailLayout>
  );
}

// Payment Methods Section Component
function PaymentMethodsSection({ paymentMethods, onRefresh }: { paymentMethods: any[]; onRefresh: () => void }) {
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    type: "credit_card",
    name: "",
    last4: "",
    expiry_month: "",
    expiry_year: "",
    bank_name: "",
    account_type: "checking",
    is_default: false,
  });

  const handleAddPaymentMethod = async () => {
    try {
      await fetcher.post("/api/provider/payment-methods", formData);
      toast.success("Payment method added successfully");
      setShowAddDialog(false);
      setFormData({
        type: "credit_card",
        name: "",
        last4: "",
        expiry_month: "",
        expiry_year: "",
        bank_name: "",
        account_type: "checking",
        is_default: false,
      });
      onRefresh();
    } catch {
      toast.error("Failed to add payment method");
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to remove this payment method?")) return;
    try {
      setIsDeleting(id);
      await fetcher.delete(`/api/provider/payment-methods/${id}`);
      toast.success("Payment method removed");
      onRefresh();
    } catch {
      toast.error("Failed to remove payment method");
    } finally {
      setIsDeleting(null);
    }
  };

  const handleSetDefault = async (id: string) => {
    try {
      await fetcher.patch(`/api/provider/payment-methods/${id}`, { is_default: true });
      toast.success("Default payment method updated");
      onRefresh();
    } catch {
      toast.error("Failed to update default payment method");
    }
  };

  if (paymentMethods.length === 0) {
    return (
      <Alert className="border-gray-200 bg-gray-50">
        <AlertDescription className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <span className="text-sm text-gray-600">No payment method set</span>
          <Button
            size="sm"
            className="bg-[#FF0077] hover:bg-[#D60565] w-full sm:w-auto"
            onClick={() => setShowAddDialog(true)}
          >
            <Plus className="w-4 h-4 mr-2" />
            Add payment method
          </Button>
        </AlertDescription>
      </Alert>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <p className="text-sm text-gray-600">
          {paymentMethods.length} payment method{paymentMethods.length !== 1 ? "s" : ""}
        </p>
        <Button
          size="sm"
          variant="outline"
          onClick={() => setShowAddDialog(true)}
        >
          <Plus className="w-4 h-4 mr-2" />
          Add payment method
        </Button>
      </div>

      <div className="space-y-3">
        {paymentMethods.map((method) => (
          <div
            key={method.id}
            className="flex items-center justify-between p-4 border border-gray-200 rounded-lg"
          >
            <div className="flex items-center gap-3">
              <CreditCard className="w-5 h-5 text-gray-400" />
              <div>
                <div className="flex items-center gap-2">
                  <p className="font-medium text-sm">{method.name}</p>
                  {method.is_default && (
                    <Badge variant="outline" className="text-xs">Default</Badge>
                  )}
                </div>
                {method.last4 && (
                  <p className="text-xs text-gray-500">ΓÇóΓÇóΓÇóΓÇó {method.last4}</p>
                )}
                {method.expiry_month && method.expiry_year && (
                  <p className="text-xs text-gray-500">
                    Expires {method.expiry_month}/{method.expiry_year}
                  </p>
                )}
              </div>
            </div>
            <div className="flex items-center gap-2">
              {!method.is_default && (
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => handleSetDefault(method.id)}
                >
                  Set as default
                </Button>
              )}
              <Button
                size="sm"
                variant="ghost"
                onClick={() => handleDelete(method.id)}
                disabled={isDeleting === method.id}
              >
                <Trash2 className="w-4 h-4 text-red-500" />
              </Button>
            </div>
          </div>
        ))}
      </div>

      {/* Add Payment Method Dialog */}
      <Dialog open={showAddDialog} onOpenChange={setShowAddDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Add Payment Method</DialogTitle>
            <DialogDescription>
              Add a payment method for paying platform fees
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>Type</Label>
              <Select
                value={formData.type}
                onValueChange={(value) => setFormData({ ...formData, type: value })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="credit_card">Credit Card</SelectItem>
                  <SelectItem value="debit_card">Debit Card</SelectItem>
                  <SelectItem value="bank_account">Bank Account</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Name</Label>
              <Input
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                placeholder="e.g., Visa ending in 1234"
              />
            </div>
            {(formData.type === "credit_card" || formData.type === "debit_card") && (
              <>
                <div>
                  <Label>Last 4 digits</Label>
                  <Input
                    value={formData.last4}
                    onChange={(e) => setFormData({ ...formData, last4: e.target.value })}
                    placeholder="1234"
                    maxLength={4}
                  />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label>Expiry Month</Label>
                    <Input
                      type="number"
                      min="1"
                      max="12"
                      value={formData.expiry_month}
                      onChange={(e) => setFormData({ ...formData, expiry_month: e.target.value })}
                      placeholder="MM"
                    />
                  </div>
                  <div>
                    <Label>Expiry Year</Label>
                    <Input
                      type="number"
                      min={new Date().getFullYear()}
                      value={formData.expiry_year}
                      onChange={(e) => setFormData({ ...formData, expiry_year: e.target.value })}
                      placeholder="YYYY"
                    />
                  </div>
                </div>
              </>
            )}
            {formData.type === "bank_account" && (
              <>
                <div>
                  <Label>Bank Name</Label>
                  <Input
                    value={formData.bank_name}
                    onChange={(e) => setFormData({ ...formData, bank_name: e.target.value })}
                    placeholder="e.g., Standard Bank"
                  />
                </div>
                <div>
                  <Label>Account Type</Label>
                  <Select
                    value={formData.account_type}
                    onValueChange={(value) => setFormData({ ...formData, account_type: value })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="checking">Checking</SelectItem>
                      <SelectItem value="savings">Savings</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </>
            )}
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                id="is_default"
                checked={formData.is_default}
                onChange={(e) => setFormData({ ...formData, is_default: e.target.checked })}
                className="rounded"
              />
              <Label htmlFor="is_default" className="cursor-pointer">
                Set as default payment method
              </Label>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowAddDialog(false)}>
              Cancel
            </Button>
            <Button
              onClick={handleAddPaymentMethod}
              className="bg-[#FF0077] hover:bg-[#D60565]"
            >
              Add Payment Method
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// Invoices Section Component
function InvoicesSection({ invoices, onRefresh: _onRefresh }: { invoices: any[]; onRefresh: () => void }) {
  const [selectedStatus, setSelectedStatus] = useState<string>("all");

  const filteredInvoices = selectedStatus === "all"
    ? invoices
    : invoices.filter((inv) => inv.status === selectedStatus);

  const getStatusBadge = (status: string) => {
    const variants: Record<string, { variant: "default" | "secondary" | "outline"; icon: any }> = {
      paid: { variant: "default", icon: CheckCircle2 },
      sent: { variant: "secondary", icon: Clock },
      overdue: { variant: "outline", icon: AlertCircle },
      draft: { variant: "outline", icon: FileText },
      partially_paid: { variant: "secondary", icon: Clock },
    };

    const config = variants[status] || { variant: "outline" as const, icon: FileText };
    const Icon = config.icon;

    return (
      <Badge variant={config.variant} className="flex items-center gap-1">
        <Icon className="w-3 h-3" />
        {status.replace("_", " ").toUpperCase()}
      </Badge>
    );
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-ZA", {
      style: "currency",
      currency: "ZAR",
    }).format(amount);
  };

  if (invoices.length === 0) {
    return (
      <div className="py-8 sm:py-12 text-center">
        <EmptyState
          title="No invoices yet"
          description="Your platform fee invoices will appear here"
          icon={FileText}
        />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <p className="text-sm text-gray-600">
          {invoices.length} invoice{invoices.length !== 1 ? "s" : ""}
        </p>
        <Select value={selectedStatus} onValueChange={setSelectedStatus}>
          <SelectTrigger className="w-full sm:w-48">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Statuses</SelectItem>
            <SelectItem value="draft">Draft</SelectItem>
            <SelectItem value="sent">Sent</SelectItem>
            <SelectItem value="paid">Paid</SelectItem>
            <SelectItem value="partially_paid">Partially Paid</SelectItem>
            <SelectItem value="overdue">Overdue</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div className="border border-gray-200 rounded-lg overflow-hidden">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Invoice #</TableHead>
              <TableHead>Period</TableHead>
              <TableHead>Issue Date</TableHead>
              <TableHead>Due Date</TableHead>
              <TableHead>Amount</TableHead>
              <TableHead>Status</TableHead>
              <TableHead className="text-right">Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {filteredInvoices.map((invoice) => (
              <TableRow key={invoice.id}>
                <TableCell className="font-medium">{invoice.invoice_number}</TableCell>
                <TableCell className="text-sm text-gray-600">
                  {new Date(invoice.period_start).toLocaleDateString()} - {new Date(invoice.period_end).toLocaleDateString()}
                </TableCell>
                <TableCell>{new Date(invoice.issue_date).toLocaleDateString()}</TableCell>
                <TableCell>{new Date(invoice.due_date).toLocaleDateString()}</TableCell>
                <TableCell className="font-medium">{formatCurrency(invoice.total_amount)}</TableCell>
                <TableCell>{getStatusBadge(invoice.status)}</TableCell>
                <TableCell className="text-right">
                  <div className="flex justify-end gap-2">
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => window.open(`/api/provider/invoices/${invoice.id}/download`, "_blank")}
                    >
                      <Download className="w-4 h-4" />
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => window.location.href = `/provider/settings/billing/invoices/${invoice.id}`}
                    >
                      <Eye className="w-4 h-4" />
                    </Button>
                  </div>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { PageHeader } from "@/components/provider/PageHeader";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Info, Check, AlertCircle } from "lucide-react";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import RoleGuard from "@/components/auth/RoleGuard";
import { useRouter } from "next/navigation";

export default function BusinessDescriptionPage() {
  const router = useRouter();
  const [description, setDescription] = useState("");
  const [originalDescription, setOriginalDescription] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    loadDescription();
  }, []);

  const loadDescription = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data: { description: string | null } }>(
        "/api/me/provider"
      );
      const desc = response.data?.description || "";
      setDescription(desc);
      setOriginalDescription(desc);
    } catch (error) {
      console.error("Error loading description:", error);
      toast.error("Failed to load business description");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    try {
      setIsSaving(true);

      // Validation
      if (description.length > 2000) {
        toast.error("Description must be 2000 characters or less");
        return;
      }

      const response = await fetcher.patch<{ data?: any }>("/api/provider/profile", {
        description: description || null,
      });

      if (response?.data) {
        setOriginalDescription(description);
        toast.success("Business description updated successfully");
        router.push("/provider/settings");
      }
    } catch (error) {
      const errorMessage =
        error instanceof FetchError
          ? error.message
          : "Failed to update description. Please try again.";
      toast.error(errorMessage);
    } finally {
      setIsSaving(false);
    }
  };

  const handleUseTemplate = () => {
    const templates = [
      "Welcome to our salon! We specialize in premium beauty services with years of experience. Our team is dedicated to providing exceptional service in a relaxing, professional environment. We use only premium products and stay up-to-date with the latest techniques and trends.",
      "At our salon, we believe beauty is an art form. Our skilled professionals are passionate about helping you look and feel your best. From haircuts to facials, we offer a full range of services tailored to your unique needs.",
      "We are your trusted partner for all your beauty and wellness needs. Our commitment to excellence and customer satisfaction sets us apart. Experience the difference with our personalized approach and attention to detail.",
    ];
    const randomTemplate = templates[Math.floor(Math.random() * templates.length)];
    setDescription(randomTemplate);
  };

  const hasChanges = description !== originalDescription;
  const isGoodLength = description.length >= 50 && description.length <= 2000;
  const showWarning = description.length > 0 && description.length < 50;

  if (isLoading) {
    return (
      <RoleGuard allowedRoles={["provider_owner", "provider_staff"]} redirectTo="/provider/dashboard">
        <div className="w-full max-w-full overflow-x-hidden">
          <PageHeader 
          title="Business Description" 
          subtitle="Edit your business description"
          breadcrumbs={[
            { label: "Home", href: "/" },
            { label: "Provider", href: "/provider" },
            { label: "Settings", href: "/provider/settings" },
            { label: "Business Description" }
          ]}
        />
          <div className="flex items-center justify-center py-12">
            <div className="text-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#FF0077] mx-auto mb-4"></div>
              <p className="text-gray-600">Loading...</p>
            </div>
          </div>
        </div>
      </RoleGuard>
    );
  }

  return (
    <RoleGuard allowedRoles={["provider_owner", "provider_staff"]} redirectTo="/provider/dashboard">
      <div className="w-full max-w-full overflow-x-hidden">
        <PageHeader
          title="Business Description"
          subtitle="Edit the description that customers see on your profile"
          breadcrumbs={[
            { label: "Home", href: "/" },
            { label: "Provider", href: "/provider" },
            { label: "Settings", href: "/provider/settings" },
            { label: "Business Description" }
          ]}
        />

        <div className="max-w-3xl mt-6 w-full max-w-full overflow-x-hidden">
          <Alert className="mb-6 w-full max-w-full">
            <Info className="w-4 h-4 flex-shrink-0" />
            <AlertDescription className="break-words">
              Your business description appears in the "About" tab on your public profile. 
              A good description helps customers understand what makes your business unique.
            </AlertDescription>
          </Alert>

          <div className="bg-white rounded-lg shadow-sm p-4 sm:p-6 space-y-4 w-full max-w-full overflow-x-hidden">
            <div className="w-full">
              <Label htmlFor="description" className="block w-full">
                <span className="block sm:inline">Description</span>
                <span className="text-gray-500 font-normal text-xs ml-0 sm:ml-2 block sm:inline">
                  (Recommended: 50-500 characters)
                </span>
              </Label>
              <Textarea
                id="description"
                value={description}
                onChange={(e) => {
                  const value = e.target.value;
                  if (value.length <= 2000) {
                    setDescription(value);
                  }
                }}
                placeholder="Tell customers about your business, your expertise, what makes you unique, and what they can expect..."
                className="min-h-[200px] mt-2 w-full max-w-full"
                maxLength={2000}
              />
              <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between mt-2 gap-2 w-full">
                <p className="text-xs text-gray-500 min-w-0 flex-1 w-full sm:w-auto">
                  {showWarning ? (
                    <span className="text-amber-600 flex items-start gap-1 flex-wrap">
                      <AlertCircle className="w-3 h-3 flex-shrink-0 mt-0.5" />
                      <span className="break-words flex-1 min-w-0">Consider adding more details ({description.length}/50 minimum recommended)</span>
                    </span>
                  ) : (
                    <span className="flex items-center gap-2 flex-wrap">
                      <span className="whitespace-nowrap">{description.length}/2000 characters</span>
                      {isGoodLength && (
                        <span className="text-green-600 flex items-center gap-1 whitespace-nowrap">
                          <Check className="w-3 h-3 flex-shrink-0" />
                          <span>Good length</span>
                        </span>
                      )}
                    </span>
                  )}
                </p>
                <button
                  type="button"
                  onClick={handleUseTemplate}
                  className="text-xs text-[#FF0077] hover:underline whitespace-nowrap flex-shrink-0 self-start sm:self-auto"
                >
                  Use template
                </button>
              </div>
            </div>

            {/* Preview */}
            {description && (
              <div className="mt-6 pt-6 border-t w-full">
                <Label className="text-sm font-medium mb-2 block">Preview</Label>
                <div className="bg-gray-50 p-4 rounded-lg border w-full overflow-x-hidden">
                  <p className="text-sm text-gray-700 whitespace-pre-wrap leading-relaxed break-words">
                    {description}
                  </p>
                </div>
                <p className="text-xs text-gray-500 mt-2">
                  This is how customers will see your description on your profile
                </p>
              </div>
            )}

            <div className="flex flex-col sm:flex-row gap-3 pt-4 border-t w-full">
              <Button
                onClick={handleSave}
                disabled={isSaving || !hasChanges}
                className="bg-[#FF0077] hover:bg-[#D60565] text-white w-full sm:w-auto"
              >
                {isSaving ? "Saving..." : "Save Changes"}
              </Button>
              <Button
                variant="outline"
                onClick={() => {
                  setDescription(originalDescription);
                  toast.info("Changes discarded");
                }}
                disabled={!hasChanges || isSaving}
                className="w-full sm:w-auto"
              >
                Cancel
              </Button>
            </div>
          </div>
        </div>
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { providerApi } from "@/lib/provider-portal/api";
import type { CalendarSync, CalendarProvider } from "@/lib/provider-portal/types";
import { PageHeader } from "@/components/provider/PageHeader";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { SectionCard } from "@/components/provider/SectionCard";
import { Plus, Trash2, RefreshCw, Calendar } from "lucide-react";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { toast } from "sonner";
import { format } from "date-fns";

export default function CalendarIntegrationPage() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const [syncs, setSyncs] = useState<CalendarSync[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [_selectedProvider, _setSelectedProvider] = useState<CalendarProvider | null>(null);
  const [_enabledProviders, setEnabledProviders] = useState<string[]>([]);

  // Check for OAuth callback results
  useEffect(() => {
    const success = searchParams?.get("success");
    const error = searchParams?.get("error");
    const provider = searchParams?.get("provider");

    if (success === "true" && provider) {
      toast.success(`${provider} calendar connected successfully`);
      loadSyncs();
      // Clean URL
      router.replace("/provider/settings/calendar-integration");
    } else if (error) {
      toast.error(`Failed to connect calendar: ${error}`);
      router.replace("/provider/settings/calendar-integration");
    }
  }, [searchParams, router]);

  const loadSyncs = useCallback(async () => {
    try {
      setIsLoading(true);
      const data = await providerApi.listCalendarSyncs();
      setSyncs(data);

      // Load enabled providers
      try {
        const { fetcher } = await import("@/lib/http/fetcher");
        const result = await fetcher.get<{ data: { providers?: string[] } }>("/api/provider/calendar/providers");
        setEnabledProviders(result.data?.providers || []);
      } catch (error) {
        console.warn("Failed to load enabled providers, showing all:", error);
        // If we can't load enabled providers, show all by default
        setEnabledProviders(["google", "outlook", "apple"]);
      }
    } catch (error) {
      console.error("Failed to load calendar syncs:", error);
      toast.error("Failed to load calendar integrations");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadSyncs();
  }, [loadSyncs]);

  const _handleConnect = async (provider: CalendarProvider) => {
    try {
      const { url } = await providerApi.getCalendarAuthUrl(provider);
      // Redirect to OAuth URL (will redirect back after auth)
      window.location.href = url;
    } catch (error: any) {
      console.error("Failed to initiate calendar connection:", error);
      const errorMessage = error?.error?.message || error?.message || "Failed to connect calendar";
      const errorCode = error?.error?.code;

      if (errorCode === "CONFIG_ERROR") {
        toast.error(
          "Calendar integration is not configured. Please contact your administrator to set up OAuth credentials.",
          { duration: 8000 }
        );
      } else if (errorCode === "INTEGRATION_DISABLED") {
        toast.error(
          errorMessage || "This calendar provider is not enabled. Please contact your administrator.",
          { duration: 8000 }
        );
      } else {
        toast.error(errorMessage);
      }
    }
  };

  const handleDisconnect = async (id: string) => {
    if (!confirm("Are you sure you want to disconnect this calendar?")) return;

    try {
      await providerApi.deleteCalendarSync(id);
      toast.success("Calendar disconnected");
      loadSyncs();
    } catch (error) {
      console.error("Failed to disconnect calendar:", error);
      toast.error("Failed to disconnect calendar");
    }
  };

  const handleSync = async (sync: CalendarSync) => {
    try {
      toast.info("Syncing calendar...");
      await providerApi.syncCalendarToAppointments(sync.id);
      toast.success("Calendar synced successfully");
      loadSyncs();
    } catch (error) {
      console.error("Failed to sync calendar:", error);
      toast.error("Failed to sync calendar");
    }
  };

  const getProviderName = (provider: CalendarProvider) => {
    switch (provider) {
      case "google":
        return "Google Calendar";
      case "apple":
        return "Apple Calendar (iCal)";
      case "outlook":
        return "Microsoft Outlook";
    }
  };

  const getProviderIcon = (_provider: CalendarProvider) => {
    return <Calendar className="w-5 h-5" />;
  };

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading calendar integrations..." />;
  }

  return (
    <div>
      <PageHeader
        title="Calendar Integration"
        subtitle="Sync your appointments with external calendars"
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Settings", href: "/provider/settings" },
          { label: "Calendar Integration" },
        ]}
        primaryAction={{
          label: "Connect Calendar",
          onClick: () => setIsDialogOpen(true),
          icon: <Plus className="w-4 h-4 mr-2" />,
        }}
      />

      {syncs.length === 0 ? (
        <SectionCard className="p-12">
          <EmptyState
            title="No calendar integrations"
            description="Connect your calendar to sync appointments automatically"
            action={{
              label: "Connect Calendar",
              onClick: () => setIsDialogOpen(true),
            }}
          />
        </SectionCard>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {syncs.map((sync) => (
            <SectionCard key={sync.id} className="p-6">
              <div className="flex items-start justify-between mb-4">
                <div className="flex items-center gap-3">
                  {getProviderIcon(sync.provider)}
                  <div>
                    <h3 className="font-semibold">{getProviderName(sync.provider)}</h3>
                    <p className="text-sm text-gray-600">
                      {sync.sync_direction === "two_way" ? "Two-way sync" : "One-way sync"}
                    </p>
                  </div>
                </div>
                {sync.is_active ? (
                  <Badge className="bg-green-100 text-green-800">Active</Badge>
                ) : (
                  <Badge className="bg-gray-100 text-gray-800">Inactive</Badge>
                )}
              </div>

              {sync.last_sync_date && (
                <div className="mb-4 text-sm text-gray-600">
                  <p>Last synced: {format(new Date(sync.last_sync_date), "PPp")}</p>
                </div>
              )}

              {sync.sync_errors && sync.sync_errors.length > 0 && (
                <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg">
                  <p className="text-sm font-medium text-red-800 mb-1">Sync Errors:</p>
                  <ul className="text-xs text-red-600 space-y-1">
                    {sync.sync_errors.map((error, idx) => (
                      <li key={idx}>ΓÇó {error}</li>
                    ))}
                  </ul>
                </div>
              )}

              <div className="flex items-center gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => handleSync(sync)}
                  disabled={!sync.is_active}
                >
                  <RefreshCw className="w-4 h-4 mr-2" />
                  Sync Now
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => handleDisconnect(sync.id)}
                  className="text-red-600 hover:text-red-700"
                >
                  <Trash2 className="w-4 h-4 mr-2" />
                  Disconnect
                </Button>
              </div>
            </SectionCard>
          ))}
        </div>
      )}

      <ConnectCalendarDialog
        open={isDialogOpen}
        onOpenChange={setIsDialogOpen}
        onSuccess={loadSyncs}
      />
    </div>
  );
}

// Connect Calendar Dialog
function ConnectCalendarDialog({
  open,
  onOpenChange,
  onSuccess: _onSuccess,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess: () => void;
}) {
  const [selectedProvider, setSelectedProvider] = useState<CalendarProvider>("google");
  const [syncDirection, setSyncDirection] = useState<"one_way" | "two_way">("two_way");
  const [isConnecting, setIsConnecting] = useState(false);
  const [enabledProviders, setEnabledProviders] = useState<string[]>([]);

  // Load enabled providers when dialog opens
  useEffect(() => {
    if (open) {
      import("@/lib/http/fetcher").then(({ fetcher }) =>
        fetcher.get<{ data: { providers?: string[] } }>("/api/provider/calendar/providers")
      )
        .then((result) => {
          const providers = result.data?.providers || [];
          setEnabledProviders(providers);
          // Set default provider to first enabled one
          if (providers.length > 0 && !providers.includes(selectedProvider)) {
            setSelectedProvider(providers[0] as CalendarProvider);
          }
        })
        .catch((error) => {
          console.warn("Failed to load enabled providers:", error);
          // Default to all providers if we can't load
          setEnabledProviders(["google", "outlook", "apple"]);
        });
    }
  }, [open, selectedProvider]);

  const handleConnect = async () => {
    setIsConnecting(true);
    try {
      const { url } = await providerApi.getCalendarAuthUrl(selectedProvider);
      // Redirect to OAuth URL
      window.location.href = url;
    } catch (error: any) {
      console.error("Failed to connect calendar:", error);
      const errorMessage = error?.error?.message || error?.message || "Failed to connect calendar";
      const errorCode = error?.error?.code;

      if (errorCode === "CONFIG_ERROR") {
        toast.error(
          "Calendar integration is not configured. Please contact your administrator to set up OAuth credentials.",
          { duration: 8000 }
        );
      } else if (errorCode === "INTEGRATION_DISABLED") {
        toast.error(
          errorMessage || "This calendar provider is not enabled. Please contact your administrator.",
          { duration: 8000 }
        );
      } else {
        toast.error(errorMessage);
      }
      setIsConnecting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Connect Calendar</DialogTitle>
          <DialogDescription>
            Choose a calendar provider to sync your appointments
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          <div>
            <Label htmlFor="provider">Calendar Provider</Label>
            <Select
              value={selectedProvider}
              onValueChange={(value) => setSelectedProvider(value as CalendarProvider)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {enabledProviders.includes("google") && (
                  <SelectItem value="google">Google Calendar</SelectItem>
                )}
                {enabledProviders.includes("outlook") && (
                  <SelectItem value="outlook">Microsoft Outlook</SelectItem>
                )}
                {enabledProviders.includes("apple") && (
                  <SelectItem value="apple">Apple Calendar (iCal)</SelectItem>
                )}
                {enabledProviders.length === 0 && (
                  <SelectItem value="none" disabled>
                    No calendar providers enabled
                  </SelectItem>
                )}
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label>Sync Direction</Label>
            <div className="space-y-2 mt-2">
              <div className="flex items-center gap-2">
                <Checkbox
                  id="two_way"
                  checked={syncDirection === "two_way"}
                  onCheckedChange={(checked) =>
                    setSyncDirection(checked ? "two_way" : "one_way")
                  }
                />
                <Label htmlFor="two_way" className="cursor-pointer">
                  Two-way sync (recommended)
                </Label>
              </div>
              <p className="text-xs text-gray-500 ml-6">
                Changes in either calendar will sync to the other
              </p>
              <div className="flex items-center gap-2">
                <Checkbox
                  id="one_way"
                  checked={syncDirection === "one_way"}
                  onCheckedChange={(checked) =>
                    setSyncDirection(checked ? "one_way" : "two_way")
                  }
                />
                <Label htmlFor="one_way" className="cursor-pointer">
                  One-way sync (appointments ΓåÆ calendar only)
                </Label>
              </div>
            </div>
          </div>

          <div className="p-3 bg-blue-50 rounded-lg text-sm text-blue-800">
            <p className="font-medium mb-1">How it works:</p>
            <ul className="list-disc list-inside space-y-1 text-xs">
              <li>Appointments will automatically sync to your calendar</li>
              <li>You can view and manage appointments from your calendar app</li>
              <li>Changes made in your calendar can sync back (two-way only)</li>
            </ul>
          </div>
        </div>

        <DialogFooter>
          <Button
            type="button"
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isConnecting}
          >
            Cancel
          </Button>
          <Button
            onClick={handleConnect}
            disabled={isConnecting}
            className="bg-[#FF0077] hover:bg-[#D60565]"
          >
            {isConnecting ? "Connecting..." : "Connect Calendar"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

