"use client";

import React, { useState, useEffect } from "react";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Plus, Edit, Trash2, MapPin, ArrowLeft } from "lucide-react";
import Link from "next/link";
import { PageHeader } from "@/components/provider/PageHeader";
import EmptyState from "@/components/ui/empty-state";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import { useSearchParams } from "next/navigation";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import AddressForm from "@/components/mapbox/AddressForm";
import { OperatingHoursEditor, type OperatingHours } from "@/components/provider/OperatingHoursEditor";
import { invalidateSetupStatusCache } from "@/lib/provider-portal/setup-status-utils";

interface Location {
  id: string;
  name: string;
  address_line1: string;
  address_line2?: string | null;
  city: string;
  state?: string | null;
  postal_code?: string | null;
  country: string;
  latitude?: number | null;
  longitude?: number | null;
  phone?: string | null;
  description?: string | null;
  is_active: boolean;
  /** 'salon' = clients can visit; 'base' = distance/travel only (mobile-only) */
  location_type?: "salon" | "base";
  operating_hours?: OperatingHours;
}

export default function LocationsSettings() {
  const [locations, setLocations] = useState<Location[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showDialog, setShowDialog] = useState(false);
  const [editingLocation, setEditingLocation] = useState<Location | null>(null);
  const searchParams = useSearchParams();
  const returnTo = searchParams.get("returnTo");

  useEffect(() => {
    loadLocations();
  }, []);

  const loadLocations = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data: Location[] }>("/api/provider/locations");
      setLocations(response.data || []);
    } catch (error) {
      console.error("Error loading locations:", error);
      toast.error("Failed to load locations");
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreate = () => {
    setEditingLocation(null);
    setShowDialog(true);
  };

  const handleEdit = (location: Location) => {
    setEditingLocation(location);
    setShowDialog(true);
  };

  const handleDelete = async (location: Location) => {
    if (!confirm(`Are you sure you want to delete "${location.name}"?`)) return;

    try {
      await fetcher.delete(`/api/provider/locations/${location.id}`);
      toast.success("Location deleted");
      loadLocations();
    } catch {
      toast.error("Failed to delete location");
    }
  };

  const handleSave = async (locationData: any) => {
    try {
      if (editingLocation) {
        await fetcher.patch(`/api/provider/locations/${editingLocation.id}`, locationData);
        toast.success("Location updated");
      } else {
        await fetcher.post("/api/provider/locations", {
          name: locationData.label || "Location",
          ...locationData,
        });
        toast.success("Location created");
      }
      setShowDialog(false);
      setEditingLocation(null);
      invalidateSetupStatusCache();
      loadLocations();
    } catch (error: any) {
      toast.error(error.message || "Failed to save location");
    }
  };

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading locations..." />;
  }

  return (
    <div>
      <PageHeader
        title="Locations"
        subtitle="Manage your business locations"
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          ...(returnTo ? [{ label: "Get Started", href: returnTo }] : []),
          { label: "Settings", href: "/provider/settings" },
          { label: "Locations" }
        ]}
        primaryAction={{
          label: "Add a new location",
          onClick: handleCreate,
          icon: <Plus className="w-4 h-4 mr-2" />,
        }}
      />

      {/* Return to Get Started banner */}
      {returnTo && (
        <div className="mb-6 bg-gradient-to-r from-[#FF0077]/10 to-[#D60565]/10 border border-[#FF0077]/30 rounded-lg p-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <MapPin className="w-5 h-5 text-[#FF0077]" />
            <div>
              <p className="text-sm font-medium text-gray-900">
                Complete this step to continue your setup
              </p>
              <p className="text-xs text-gray-600">
                Add your business location to help customers find you
              </p>
            </div>
          </div>
          <Link href={returnTo}>
            <Button variant="outline" size="sm" className="border-[#FF0077]/30 text-[#FF0077] hover:bg-[#FF0077]/10">
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Get Started
            </Button>
          </Link>
        </div>
      )}

      {locations.length === 0 ? (
        <SectionCard className="p-12">
          <EmptyState
            title="No locations yet"
            description="Add your business address for travel distance and fees. Add a salon location when clients can visit you in-studio."
            action={{
              label: "Add Location",
              onClick: handleCreate,
            }}
          />
        </SectionCard>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {locations.map((location) => (
            <SectionCard key={location.id} className="relative">
              <div className="flex gap-4">
                {/* Map Preview Placeholder */}
                <div className="w-32 h-32 rounded-lg bg-gray-100 flex items-center justify-center flex-shrink-0">
                  <MapPin className="w-8 h-8 text-gray-400" />
                </div>

                <div className="flex-1">
                  <div className="flex items-start justify-between mb-2">
                    <div>
                      <h3 className="font-semibold text-lg">{location.name}</h3>
                      <div className="flex flex-wrap gap-2 mt-1">
                        {location.is_active && (
                          <span className="text-xs text-[#FF0077] font-medium">Active</span>
                        )}
                        {(location.location_type || "salon") === "salon" ? (
                          <span className="text-xs bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400 px-2 py-0.5 rounded font-medium">
                            Salon ΓÇö clients can visit
                          </span>
                        ) : (
                          <span className="text-xs bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400 px-2 py-0.5 rounded font-medium">
                            Base address (travel distance only)
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                  <p className="text-sm text-gray-600 mb-2">
                    {location.address_line1}
                    {location.address_line2 && `, ${location.address_line2}`}
                  </p>
                  <p className="text-sm text-gray-600 mb-4">
                    {location.city}
                    {location.state && `, ${location.state}`}
                    {location.postal_code && ` ${location.postal_code}`}
                    {`, ${location.country}`}
                  </p>
                  {location.latitude && location.longitude && (
                    <p className="text-xs text-gray-400 mb-4">
                      Coordinates: {location.latitude.toFixed(6)}, {location.longitude.toFixed(6)}
                    </p>
                  )}
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleEdit(location)}
                    >
                      <Edit className="w-4 h-4 mr-2" />
                      Edit
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleDelete(location)}
                      className="text-red-600 hover:text-red-700"
                    >
                      <Trash2 className="w-4 h-4 mr-2" />
                      Delete
                    </Button>
                  </div>
                </div>
              </div>
            </SectionCard>
          ))}
        </div>
      )}

      {showDialog && (
        <LocationDialog
          location={editingLocation}
          onClose={() => {
            setShowDialog(false);
            setEditingLocation(null);
          }}
          onSave={handleSave}
        />
      )}
    </div>
  );
}

function LocationDialog({
  location,
  onClose,
  onSave,
}: {
  location: Location | null;
  onClose: () => void;
  onSave: (data: any) => void;
}) {
  const defaultHours: OperatingHours = {
    monday: { open: "09:00", close: "18:00", closed: false },
    tuesday: { open: "09:00", close: "18:00", closed: false },
    wednesday: { open: "09:00", close: "18:00", closed: false },
    thursday: { open: "09:00", close: "18:00", closed: false },
    friday: { open: "09:00", close: "18:00", closed: false },
    saturday: { open: "09:00", close: "18:00", closed: false },
    sunday: { open: "09:00", close: "18:00", closed: true },
  };

  const [formData, setFormData] = useState({
    label: location?.name || "",
    address_line1: location?.address_line1 || "",
    address_line2: location?.address_line2 || "",
    city: location?.city || "",
    state: location?.state || "",
    postal_code: location?.postal_code || "",
    country: location?.country || "",
    phone: location?.phone || "",
    description: location?.description || "",
    latitude: location?.latitude || undefined,
    longitude: location?.longitude || undefined,
    operating_hours: location?.operating_hours || defaultHours,
    location_type: (location?.location_type || "salon") as "salon" | "base",
  });

  const handleAddressSelect = (address: {
    address_line1: string;
    city: string;
    state?: string;
    postal_code?: string;
    country: string;
    latitude: number;
    longitude: number;
  }) => {
    setFormData({
      ...formData,
      address_line1: address.address_line1,
      city: address.city,
      state: address.state || "",
      postal_code: address.postal_code || "",
      country: address.country,
      latitude: address.latitude,
      longitude: address.longitude,
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      name: formData.label,
      ...formData,
      operating_hours: formData.operating_hours,
      location_type: formData.location_type,
    });
  };

  return (
    <Dialog open={true} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{location ? "Edit Location" : "Add Location"}</DialogTitle>
          <DialogDescription>
            {location
              ? "Update address and location type. Salon locations allow in-studio bookings."
              : "Add a business location. Choose Salon if clients can visit; Base if you only do house calls. Address will be geocoded."}
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label>Location type</Label>
            <p className="text-sm text-muted-foreground mb-2">
              Salon = clients can book in-studio. Base = used only for travel distance (mobile-only).
            </p>
            <div className="flex flex-col sm:flex-row gap-3 sm:gap-6">
              <label
                className={`flex items-center gap-2 cursor-pointer rounded-lg border p-3 hover:bg-muted/50 ${
                  formData.location_type === "salon" ? "border-[#FF0077] bg-[#FF0077]/5" : ""
                }`}
              >
                <input
                  type="radio"
                  name="location_type"
                  checked={formData.location_type === "salon"}
                  onChange={() => setFormData({ ...formData, location_type: "salon" })}
                  className="rounded-full border-gray-300 text-[#FF0077]"
                />
                <span className="text-sm font-medium">Salon / studio ΓÇö clients can visit</span>
              </label>
              <label
                className={`flex items-center gap-2 cursor-pointer rounded-lg border p-3 hover:bg-muted/50 ${
                  formData.location_type === "base" ? "border-[#FF0077] bg-[#FF0077]/5" : ""
                }`}
              >
                <input
                  type="radio"
                  name="location_type"
                  checked={formData.location_type === "base"}
                  onChange={() => setFormData({ ...formData, location_type: "base" })}
                  className="rounded-full border-gray-300 text-[#FF0077]"
                />
                <span className="text-sm font-medium">Base address only (travel distance)</span>
              </label>
            </div>
          </div>
          <div>
            <Label htmlFor="name">Location Name *</Label>
            <Input
              id="name"
              value={formData.label}
              onChange={(e) => setFormData({ ...formData, label: e.target.value })}
              placeholder="Main Branch"
              required
            />
          </div>

          <div>
            <Label htmlFor="address">Address *</Label>
            <AddressForm
              initialAddress={location ? {
                address_line1: location.address_line1,
                address_line2: location.address_line2 || undefined,
                city: location.city,
                state: location.state || undefined,
                postal_code: location.postal_code || undefined,
                country: location.country,
                latitude: location.latitude || undefined,
                longitude: location.longitude || undefined,
              } : undefined}
              onSave={(address) => {
                handleAddressSelect(address);
                // Auto-submit if editing existing location
                if (location) {
                  onSave({
                    name: formData.label,
                    ...address,
                    phone: formData.phone,
                  });
                }
              }}
              showLabel={false}
              asForm={false}
            />
          </div>

          <div>
            <Label htmlFor="phone">Phone (Optional)</Label>
            <Input
              id="phone"
              type="tel"
              value={formData.phone}
              onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
              placeholder="+27 11 123 4567"
            />
          </div>

          <div>
            <Label htmlFor="description">Location Description (Optional)</Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => {
                const value = e.target.value;
                if (value.length <= 36) {
                  setFormData({ ...formData, description: value });
                }
              }}
              rows={2}
              maxLength={36}
              placeholder="Brief description of this location..."
            />
            <p className="text-xs text-gray-500 mt-1">
              {formData.description.length}/36 characters
            </p>
          </div>

          <div>
            <Label>Operating Hours</Label>
            <p className="text-sm text-gray-600 mb-3">
              Set the opening and closing times for each day of the week
            </p>
            <OperatingHoursEditor
              hours={formData.operating_hours}
              onChange={(hours) => setFormData({ ...formData, operating_hours: hours })}
            />
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit" disabled={!formData.label || !formData.address_line1 || !formData.city}>
              {location ? "Update" : "Create"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { NoteTemplate, NoteType } from "@/lib/provider-portal/types";
import { PageHeader } from "@/components/provider/PageHeader";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Plus, Edit, Trash2, Eye, EyeOff } from "lucide-react";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { SectionCard } from "@/components/provider/SectionCard";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { toast } from "sonner";

export default function NoteTemplatesPage() {
  const [templates, setTemplates] = useState<NoteTemplate[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [selectedTemplate, setSelectedTemplate] = useState<NoteTemplate | null>(null);

  const loadTemplates = useCallback(async () => {
    try {
      setIsLoading(true);
      const data = await providerApi.listNoteTemplates();
      setTemplates(data);
    } catch (error: any) {
      console.error("Failed to load note templates:", error);
      const errorMessage = error?.message || "Failed to load note templates";
      toast.error(errorMessage);
      setTemplates([]);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadTemplates();
  }, [loadTemplates]);

  const handleCreate = () => {
    setSelectedTemplate(null);
    setIsDialogOpen(true);
  };

  const handleEdit = (template: NoteTemplate) => {
    setSelectedTemplate(template);
    setIsDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this template? This action cannot be undone.")) return;

    try {
      await providerApi.deleteNoteTemplate(id);
      toast.success("Template deleted successfully");
      await loadTemplates();
    } catch (error: any) {
      console.error("Failed to delete template:", error);
      const errorMessage = error?.message || "Failed to delete template";
      toast.error(errorMessage);
    }
  };

  const getTypeColor = (type: NoteType) => {
    switch (type) {
      case "internal":
        return "bg-blue-100 text-blue-800";
      case "client_visible":
        return "bg-green-100 text-green-800";
      case "system":
        return "bg-gray-100 text-gray-800";
    }
  };

  if (isLoading) {
    return <LoadingTimeout loadingMessage="Loading note templates..." />;
  }

  return (
    <div>
      <PageHeader
        title="Note Templates"
        subtitle="Create reusable note templates for quick appointment notes"
        breadcrumbs={[
          { label: "Home", href: "/" },
          { label: "Provider", href: "/provider" },
          { label: "Settings", href: "/provider/settings" },
          { label: "Note Templates" },
        ]}
        primaryAction={{
          label: "New Template",
          onClick: handleCreate,
          icon: <Plus className="w-4 h-4 mr-2" />,
        }}
      />

      {templates.length === 0 ? (
        <SectionCard className="p-12">
          <EmptyState
            title="No note templates"
            description="Create templates to quickly add common notes to appointments"
            action={{
              label: "Create Template",
              onClick: handleCreate,
            }}
          />
        </SectionCard>
      ) : (
        <SectionCard className="p-0 overflow-hidden">
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Name</TableHead>
                  <TableHead>Type</TableHead>
                  <TableHead>Content</TableHead>
                  <TableHead>Category</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {templates.map((template) => (
                  <TableRow key={template.id}>
                    <TableCell className="font-medium">{template.name}</TableCell>
                    <TableCell>
                      <Badge className={getTypeColor(template.type)}>
                        {template.type === "internal" ? (
                          <span className="flex items-center gap-1">
                            <EyeOff className="w-3 h-3" />
                            Internal
                          </span>
                        ) : (
                          <span className="flex items-center gap-1">
                            <Eye className="w-3 h-3" />
                            Client Visible
                          </span>
                        )}
                      </Badge>
                    </TableCell>
                    <TableCell className="max-w-md truncate">
                      {template.content}
                    </TableCell>
                    <TableCell>{template.category || "-"}</TableCell>
                    <TableCell>
                      {template.is_active ? (
                        <Badge className="bg-green-100 text-green-800">Active</Badge>
                      ) : (
                        <Badge className="bg-gray-100 text-gray-800">Inactive</Badge>
                      )}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex items-center justify-end gap-2">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleEdit(template)}
                        >
                          <Edit className="w-3 h-3 mr-1" />
                          Edit
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleDelete(template.id)}
                          className="text-red-600 hover:text-red-700"
                        >
                          <Trash2 className="w-3 h-3 mr-1" />
                          Delete
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        </SectionCard>
      )}

      <NoteTemplateDialog
        open={isDialogOpen}
        onOpenChange={setIsDialogOpen}
        template={selectedTemplate}
        onSuccess={loadTemplates}
      />
    </div>
  );
}

// Note Template Create/Edit Dialog
function NoteTemplateDialog({
  open,
  onOpenChange,
  template,
  onSuccess,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  template: NoteTemplate | null;
  onSuccess: () => void;
}) {
  const [formData, setFormData] = useState({
    name: "",
    content: "",
    type: "internal" as NoteType,
    category: "",
    is_active: true,
  });
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (open) {
      if (template) {
        setFormData({
          name: template.name,
          content: template.content,
          type: template.type,
          category: template.category || "",
          is_active: template.is_active,
        });
      } else {
        setFormData({
          name: "",
          content: "",
          type: "internal",
          category: "",
          is_active: true,
        });
      }
    }
  }, [open, template]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Validate form
    if (!formData.name.trim()) {
      toast.error("Template name is required");
      return;
    }
    
    if (!formData.content.trim()) {
      toast.error("Template content is required");
      return;
    }

    setIsLoading(true);

    try {
      if (template) {
        await providerApi.updateNoteTemplate(template.id, {
          name: formData.name.trim(),
          content: formData.content.trim(),
          type: formData.type,
          category: formData.category.trim() || undefined,
          is_active: formData.is_active,
        });
        toast.success("Template updated successfully");
      } else {
        await providerApi.createNoteTemplate({
          name: formData.name.trim(),
          content: formData.content.trim(),
          type: formData.type,
          category: formData.category.trim() || undefined,
          is_active: formData.is_active,
        });
        toast.success("Template created successfully");
      }
      onSuccess();
      onOpenChange(false);
    } catch (error: any) {
      console.error("Failed to save template:", error);
      const errorMessage = error?.message || "Failed to save template";
      toast.error(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{template ? "Edit Template" : "New Note Template"}</DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="name">Template Name *</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              placeholder="e.g., Follow-up reminder"
              required
            />
          </div>

          <div>
            <Label htmlFor="type">Note Type *</Label>
            <Select
              value={formData.type}
              onValueChange={(value) => setFormData({ ...formData, type: value as NoteType })}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="internal">
                  <div className="flex items-center gap-2">
                    <EyeOff className="w-4 h-4" />
                    <span>Internal (Staff only)</span>
                  </div>
                </SelectItem>
                <SelectItem value="client_visible">
                  <div className="flex items-center gap-2">
                    <Eye className="w-4 h-4" />
                    <span>Client Visible</span>
                  </div>
                </SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label htmlFor="category">Category (Optional)</Label>
            <Input
              id="category"
              value={formData.category}
              onChange={(e) => setFormData({ ...formData, category: e.target.value })}
              placeholder="e.g., Follow-up, Reminder, Special Request"
            />
          </div>

          <div>
            <Label htmlFor="content">Template Content *</Label>
            <Textarea
              id="content"
              value={formData.content}
              onChange={(e) => setFormData({ ...formData, content: e.target.value })}
              rows={6}
              placeholder="Enter template content. You can use variables like {{client_name}}, {{service_name}}, etc."
              required
            />
            <p className="text-xs text-gray-500 mt-1">
              Tip: Use this template when adding notes to appointments for consistency
            </p>
          </div>

          <div className="flex items-center gap-2">
            <Checkbox
              id="is_active"
              checked={formData.is_active}
              onCheckedChange={(checked) =>
                setFormData({ ...formData, is_active: !!checked })
              }
            />
            <Label htmlFor="is_active" className="cursor-pointer">
              Active
            </Label>
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isLoading}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isLoading}
              className="bg-[#FF0077] hover:bg-[#D60565]"
            >
              {isLoading ? "Saving..." : template ? "Update" : "Create"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { Clock } from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { OperatingHoursEditor, type OperatingHours } from "@/components/provider/OperatingHoursEditor";
import { invalidateSetupStatusCache } from "@/lib/provider-portal/setup-status-utils";

interface Location {
  id: string;
  name: string;
  address_line1: string;
  city: string;
  state?: string | null;
  country: string;
  operating_hours?: OperatingHours;
}

export default function OperatingHoursSettings() {
  const [locations, setLocations] = useState<Location[]>([]);
  const [selectedLocationId, setSelectedLocationId] = useState<string | null>(null);
  const [operatingHours, setOperatingHours] = useState<OperatingHours>({});
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);

  useEffect(() => {
    loadLocations();
  }, []);

  useEffect(() => {
    if (selectedLocationId) {
      const location = locations.find((loc) => loc.id === selectedLocationId);
      if (location) {
        const defaultHours: OperatingHours = {
          monday: { open: "09:00", close: "18:00", closed: false },
          tuesday: { open: "09:00", close: "18:00", closed: false },
          wednesday: { open: "09:00", close: "18:00", closed: false },
          thursday: { open: "09:00", close: "18:00", closed: false },
          friday: { open: "09:00", close: "18:00", closed: false },
          saturday: { open: "09:00", close: "18:00", closed: false },
          sunday: { open: "09:00", close: "18:00", closed: true },
        };
        setOperatingHours(location.operating_hours || defaultHours);
        setHasChanges(false);
      }
    }
  }, [selectedLocationId, locations]);

  const loadLocations = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data: Location[] }>("/api/provider/locations");
      const locationsData = response.data || [];
      setLocations(locationsData);
      
      // Auto-select first location if available
      if (locationsData.length > 0 && !selectedLocationId) {
        setSelectedLocationId(locationsData[0].id);
      }
    } catch (error) {
      console.error("Error loading locations:", error);
      toast.error("Failed to load locations");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!selectedLocationId) {
      toast.error("Please select a location");
      return;
    }

    try {
      setIsSaving(true);
      await fetcher.patch(`/api/provider/locations/${selectedLocationId}`, {
        operating_hours: operatingHours,
      });
      toast.success("Operating hours updated successfully");
      setHasChanges(false);
      invalidateSetupStatusCache();
      // Reload locations to get updated data
      await loadLocations();
    } catch (error: any) {
      toast.error(error.message || "Failed to save operating hours");
    } finally {
      setIsSaving(false);
    }
  };

  const handleHoursChange = (hours: OperatingHours) => {
    setOperatingHours(hours);
    setHasChanges(true);
  };

  const selectedLocation = locations.find((loc) => loc.id === selectedLocationId);

  const breadcrumbs = [
    { label: "Home", href: "/" },
    { label: "Provider", href: "/provider" },
    { label: "Settings", href: "/provider/settings" },
    { label: "Operating Hours" },
  ];

  if (isLoading) {
    return (
      <SettingsDetailLayout
        title="Operating Hours"
        subtitle="Manage opening and closing times for your locations"
        breadcrumbs={breadcrumbs}
      >
        <LoadingTimeout loadingMessage="Loading locations..." />
      </SettingsDetailLayout>
    );
  }

  if (locations.length === 0) {
    return (
      <SettingsDetailLayout
        title="Operating Hours"
        subtitle="Manage opening and closing times for your locations"
        breadcrumbs={breadcrumbs}
      >
        <SectionCard className="p-12">
          <EmptyState
            title="No locations found"
            description="Add a location first to manage operating hours"
            action={{
              label: "Add Location",
              onClick: () => (window.location.href = "/provider/settings/locations"),
            }}
          />
        </SectionCard>
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      title="Operating Hours"
      subtitle="Manage opening and closing times for your locations"
      onSave={handleSave}
      saveLabel={isSaving ? "Saving..." : "Save Changes"}
      saveDisabled={isSaving || !hasChanges || !selectedLocationId}
      breadcrumbs={breadcrumbs}
    >
      <SectionCard className="w-full">
        <div className="space-y-6">
          {/* Location Selector */}
          <div className="space-y-2">
            <Label htmlFor="location-select">Select Location</Label>
            <Select
              value={selectedLocationId || ""}
              onValueChange={setSelectedLocationId}
            >
              <SelectTrigger id="location-select" className="w-full sm:w-auto min-w-[300px]">
                <SelectValue placeholder="Select a location" />
              </SelectTrigger>
              <SelectContent>
                {locations.map((location) => (
                  <SelectItem key={location.id} value={location.id}>
                    {location.name} - {location.city}, {location.country}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {selectedLocation && (
              <p className="text-sm text-gray-600">
                {selectedLocation.address_line1}, {selectedLocation.city}
                {selectedLocation.state && `, ${selectedLocation.state}`}
              </p>
            )}
          </div>

          {/* Operating Hours Editor */}
          {selectedLocationId && (
            <div className="space-y-4">
              <div>
                <h3 className="text-lg font-semibold mb-2 flex items-center gap-2">
                  <Clock className="w-5 h-5" />
                  Operating Hours
                </h3>
                <p className="text-sm text-gray-600 mb-4">
                  Set the opening and closing times for each day of the week. Uncheck "Open" to mark a day as closed.
                </p>
                <OperatingHoursEditor
                  hours={operatingHours}
                  onChange={handleHoursChange}
                />
              </div>
            </div>
          )}

          {/* Info Note */}
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
            <p className="text-sm text-blue-800">
              <strong>Note:</strong> Operating hours determine when customers can book appointments at this location.
              Make sure to keep these hours up to date to avoid booking conflicts.
            </p>
          </div>
        </div>
      </SectionCard>
    </SettingsDetailLayout>
  );
}

