"use client";

import React, { useEffect, useState } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";

interface TravelFeeSettings {
  enabled: boolean;
  rate_per_km: number | null;
  minimum_fee: number | null;
  maximum_fee: number | null;
  currency: string;
  use_platform_default: boolean;
}

interface PlatformLimits {
  provider_min_rate_per_km: number;
  provider_max_rate_per_km: number;
  provider_min_minimum_fee: number;
  provider_max_minimum_fee: number;
  allow_provider_customization: boolean;
}

export default function TravelFeesSettings() {
  const [settings, setSettings] = useState<TravelFeeSettings>({
    enabled: true,
    rate_per_km: null,
    minimum_fee: null,
    maximum_fee: null,
    currency: 'ZAR',
    use_platform_default: true,
  });
  const [platformLimits, setPlatformLimits] = useState<PlatformLimits | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        setIsLoading(true);

        // Load provider settings
        const res = await fetcher.get<{ data: TravelFeeSettings }>(
          "/api/provider/travel-fees"
        );
        setSettings(res.data);

        // Load platform limits from travel fees endpoint
        // This endpoint now allows providers to read limits
        try {
          const platformRes = await fetcher.get<{ data: any }>(
            "/api/provider/travel-fees/platform-limits"
          );
          setPlatformLimits({
            provider_min_rate_per_km: platformRes.data.provider_min_rate_per_km || 0,
            provider_max_rate_per_km: platformRes.data.provider_max_rate_per_km || 50,
            provider_min_minimum_fee: platformRes.data.provider_min_minimum_fee || 0,
            provider_max_minimum_fee: platformRes.data.provider_max_minimum_fee || 100,
            allow_provider_customization: platformRes.data.allow_provider_customization !== false,
          });
        } catch (platformError: any) {
          // If platform limits can't be loaded, use defaults
          console.warn("Failed to load platform limits, using defaults:", platformError);
          setPlatformLimits({
            provider_min_rate_per_km: 0,
            provider_max_rate_per_km: 50,
            provider_min_minimum_fee: 0,
            provider_max_minimum_fee: 100,
            allow_provider_customization: true,
          });
        }
      } catch (e: any) {
        console.error("Error loading travel fee settings:", e);
        const errorMessage = e instanceof FetchError
          ? e.message
          : e?.error?.message || "Failed to load travel fee settings";
        toast.error(errorMessage);
      } finally {
        setIsLoading(false);
      }
    };
    load();
  }, []);

  const onSave = async () => {
    try {
      setIsSaving(true);

      // Validate against platform limits if using custom rates
      if (!settings.use_platform_default && platformLimits) {
        if (settings.rate_per_km !== null) {
          if (settings.rate_per_km < platformLimits.provider_min_rate_per_km || 
              settings.rate_per_km > platformLimits.provider_max_rate_per_km) {
            toast.error(
              `Rate per km must be between ${platformLimits.provider_min_rate_per_km} and ${platformLimits.provider_max_rate_per_km}`
            );
            return;
          }
        }
        if (settings.minimum_fee !== null) {
          if (settings.minimum_fee < platformLimits.provider_min_minimum_fee || 
              settings.minimum_fee > platformLimits.provider_max_minimum_fee) {
            toast.error(
              `Minimum fee must be between ${platformLimits.provider_min_minimum_fee} and ${platformLimits.provider_max_minimum_fee}`
            );
            return;
          }
        }
      }

      // Validate maximum fee if set
      if (settings.maximum_fee !== null && settings.maximum_fee < 0) {
        toast.error("Maximum fee cannot be negative");
        return;
      }

      // Validate currency
      if (settings.currency && settings.currency.length !== 3) {
        toast.error("Currency must be a 3-letter code (e.g., ZAR, USD)");
        return;
      }

      const res = await fetcher.patch<{ data: TravelFeeSettings }>(
        "/api/provider/travel-fees",
        settings
      );
      setSettings(res.data);
      toast.success("Travel fee settings saved successfully");
    } catch (e: any) {
      const errorMessage = e instanceof FetchError
        ? e.message
        : e?.error?.message || "Failed to save travel fee settings";
      toast.error(errorMessage);
      console.error("Error saving travel fee settings:", e);
    } finally {
      setIsSaving(false);
    }
  };

  const breadcrumbs = [
    { label: "Home", href: "/" },
    { label: "Provider", href: "/provider" },
    { label: "Settings", href: "/provider/settings" },
    { label: "Sales", href: "/provider/settings/sales/yoco-integration" },
    { label: "Travel Fees" },
  ];

  if (isLoading) {
    return (
      <SettingsDetailLayout
        title="Travel Fees"
        subtitle="Configure travel fees for at-home services"
        onSave={onSave}
        isSaving={isSaving}
        breadcrumbs={breadcrumbs}
      >
        <SectionCard>
          <LoadingTimeout loadingMessage="Loading travel fee settings..." />
        </SectionCard>
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      title="Travel Fees"
      subtitle="Configure travel fees for at-home services"
      onSave={onSave}
      isSaving={isSaving}
      breadcrumbs={breadcrumbs}
    >
      <SectionCard>
        <div className="space-y-6">
          <div className="flex items-center justify-between">
            <div>
              <Label>Enable Travel Fees</Label>
              <p className="text-sm text-gray-600 mt-1">
                Charge customers for travel to their location
              </p>
            </div>
            <Checkbox
              checked={settings.enabled}
              onCheckedChange={(checked) => 
                setSettings({ ...settings, enabled: checked === true })
              }
            />
          </div>

          {settings.enabled && (
            <>
              <div className="flex items-center justify-between border-t pt-4">
                <div>
                  <Label>Use Platform Default Rates</Label>
                  <p className="text-sm text-gray-600 mt-1">
                    Use the platform's default travel fee rates
                  </p>
                </div>
                <Checkbox
                  checked={settings.use_platform_default}
                  onCheckedChange={(checked) => 
                    setSettings({ ...settings, use_platform_default: checked === true })
                  }
                />
              </div>

              {!settings.use_platform_default && platformLimits?.allow_provider_customization && (
                <div className="space-y-4 border-t pt-4">
                  <p className="text-sm font-medium text-gray-700">
                    Custom Travel Fee Rates
                  </p>

                  <div>
                    <Label htmlFor="rate_per_km">
                      Rate per Kilometer ({settings.currency})
                      {platformLimits && (
                        <span className="text-xs text-gray-500 ml-2">
                          (Min: {platformLimits.provider_min_rate_per_km}, Max: {platformLimits.provider_max_rate_per_km})
                        </span>
                      )}
                    </Label>
                    <Input
                      id="rate_per_km"
                      type="number"
                      inputMode="decimal"
                      min={platformLimits?.provider_min_rate_per_km || 0}
                      max={platformLimits?.provider_max_rate_per_km || 50}
                      step={0.01}
                      value={settings.rate_per_km || ""}
                      onChange={(e) => 
                        setSettings({ 
                          ...settings, 
                          rate_per_km: e.target.value ? parseFloat(e.target.value) : null 
                        })
                      }
                      className="mt-1"
                    />
                    <p className="text-xs text-gray-500 mt-1">
                      Amount charged per kilometer traveled
                    </p>
                  </div>

                  <div>
                    <Label htmlFor="minimum_fee">
                      Minimum Fee ({settings.currency})
                      {platformLimits && (
                        <span className="text-xs text-gray-500 ml-2">
                          (Min: {platformLimits.provider_min_minimum_fee}, Max: {platformLimits.provider_max_minimum_fee})
                        </span>
                      )}
                    </Label>
                    <Input
                      id="minimum_fee"
                      type="number"
                      inputMode="decimal"
                      min={platformLimits?.provider_min_minimum_fee || 0}
                      max={platformLimits?.provider_max_minimum_fee || 100}
                      step={0.01}
                      value={settings.minimum_fee || ""}
                      onChange={(e) => 
                        setSettings({ 
                          ...settings, 
                          minimum_fee: e.target.value ? parseFloat(e.target.value) : null 
                        })
                      }
                      className="mt-1"
                    />
                    <p className="text-xs text-gray-500 mt-1">
                      Minimum travel fee regardless of distance
                    </p>
                  </div>

                  <div>
                    <Label htmlFor="maximum_fee">
                      Maximum Fee ({settings.currency}) - Optional
                    </Label>
                    <Input
                      id="maximum_fee"
                      type="number"
                      inputMode="decimal"
                      min={0}
                      step={0.01}
                      value={settings.maximum_fee || ""}
                      onChange={(e) => 
                        setSettings({ 
                          ...settings, 
                          maximum_fee: e.target.value ? parseFloat(e.target.value) : null 
                        })
                      }
                      className="mt-1"
                      placeholder="No maximum"
                    />
                    <p className="text-xs text-gray-500 mt-1">
                      Maximum travel fee cap (leave empty for no limit)
                    </p>
                  </div>

                  <div>
                    <Label htmlFor="currency">Currency</Label>
                    <Input
                      id="currency"
                      type="text"
                      value={settings.currency}
                      onChange={(e) => 
                        setSettings({ ...settings, currency: e.target.value.toUpperCase() })
                      }
                      className="mt-1"
                      maxLength={3}
                    />
                    <p className="text-xs text-gray-500 mt-1">
                      Currency code (e.g., ZAR, USD)
                    </p>
                  </div>
                </div>
              )}

              {!platformLimits?.allow_provider_customization && (
                <div className="border-t pt-4">
                  <p className="text-sm text-gray-600">
                    Provider customization is currently disabled by the platform. 
                    You must use the platform default rates.
                  </p>
                </div>
              )}
            </>
          )}
        </div>
      </SectionCard>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";

export default function UpsellingSettings() {
  const [enabled, setEnabled] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    loadSettings();
  }, []);

  const loadSettings = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data: { enabled: boolean } }>(
        "/api/provider/settings/sales/upselling"
      );
      setEnabled(response.data.enabled);
    } catch (error: any) {
      console.error("Error loading settings:", error);
      // Keep default on error
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    try {
      setIsSaving(true);
      await fetcher.patch("/api/provider/settings/sales/upselling", {
        upselling_enabled: enabled,
      });
      toast.success("Upselling settings saved");
    } catch (error: any) {
      toast.error(error.message || "Failed to save settings");
    } finally {
      setIsSaving(false);
    }
  };

  const breadcrumbs = [
    { label: "Home", href: "/" },
    { label: "Provider", href: "/provider" },
    { label: "Settings", href: "/provider/settings" },
    { label: "Sales", href: "/provider/settings/sales/yoco-integration" },
    { label: "Upselling" },
  ];

  if (isLoading) {
    return (
      <SettingsDetailLayout
        title="Upselling"
        subtitle="Configure upselling preferences"
        breadcrumbs={breadcrumbs}
      >
        <SectionCard>
          <div className="text-center py-8 text-sm text-gray-600">Loading...</div>
        </SectionCard>
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout
      title="Upselling"
      subtitle="Configure upselling preferences"
      onSave={handleSave}
      saveLabel={isSaving ? "Saving..." : "Save Changes"}
      saveDisabled={isSaving}
      breadcrumbs={breadcrumbs}
    >
      <SectionCard>
        <div className="flex items-center justify-between p-4 bg-gray-50 rounded-lg">
          <div className="flex-1">
            <Label className="text-base font-medium cursor-pointer">Enable Upselling</Label>
            <p className="text-sm text-gray-600 mt-1">Suggest additional services or products</p>
          </div>
          <Switch checked={enabled} onCheckedChange={setEnabled} />
        </div>
      </SectionCard>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { YocoIntegration, YocoDevice } from "@/lib/provider-portal/types";
import { SectionCard } from "@/components/provider/SectionCard";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { CheckCircle2, XCircle, ExternalLink, CreditCard } from "lucide-react";
import { toast } from "sonner";
import Link from "next/link";
import { SubscriptionGate } from "@/components/provider/SubscriptionGate";
import { invalidateSetupStatusCache } from "@/lib/provider-portal/setup-status-utils";

export default function YocoIntegrationPage() {
  const [integration, setIntegration] = useState<YocoIntegration | null>(null);
  const [devices, setDevices] = useState<YocoDevice[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [showKeys, setShowKeys] = useState(false);
  const [subscriptionRequired, setSubscriptionRequired] = useState(false);

  const [formData, setFormData] = useState({
    secret_key: "",
    public_key: "",
    webhook_secret: "",
  });

  useEffect(() => {
    let isMounted = true;

    const loadData = async () => {
      try {
        setIsLoading(true);
        const [integrationData, devicesData] = await Promise.all([
          providerApi.getYocoIntegration(),
          providerApi.listYocoDevices(),
        ]);

        // Only update state if component is still mounted
        if (!isMounted) return;

        setIntegration(integrationData);
        setDevices(devicesData);
        // Only populate form if keys are not masked (API returns "***" for security)
        // If masked, leave form empty so user can enter keys
        setFormData({
          secret_key: integrationData.secret_key && integrationData.secret_key !== "***" ? integrationData.secret_key : "",
          public_key: integrationData.public_key && integrationData.public_key !== "***" ? integrationData.public_key : "",
          webhook_secret: integrationData.webhook_secret && integrationData.webhook_secret !== "***" ? integrationData.webhook_secret : "",
        });
      } catch (error: any) {
        // Don't update state or show errors if component unmounted
        if (!isMounted) return;

        // Ignore AbortError (cancelled requests)
        if (error?.name === 'AbortError' || error?.message?.includes('aborted')) {
          return;
        }

        console.error("Failed to load Yoco integration:", error);
        if (error?.code === "SUBSCRIPTION_REQUIRED" || error?.error?.code === "SUBSCRIPTION_REQUIRED") {
          setSubscriptionRequired(true);
        } else if (error?.name !== 'FetchTimeoutError' || !(error as any).__cancelled) {
          // Only show error if not a cancelled request
          toast.error("Failed to load Yoco integration");
        }
      } finally {
        if (isMounted) {
          setIsLoading(false);
        }
      }
    };

    loadData();

    return () => {
      isMounted = false;
    };
  }, []);

  const handleToggle = async (enabled: boolean) => {
    try {
      setIsSaving(true);
      const updated = await providerApi.updateYocoIntegration({ is_enabled: enabled });
      setIntegration(updated);
      invalidateSetupStatusCache();
      toast.success(enabled ? "Yoco integration enabled" : "Yoco integration disabled");
    } catch (error: any) {
      console.error("Failed to update integration:", error);
      if (error?.code === "SUBSCRIPTION_REQUIRED" || error?.error?.code === "SUBSCRIPTION_REQUIRED") {
        setSubscriptionRequired(true);
        toast.error("Subscription upgrade required to use Yoco integration");
      } else {
        toast.error("Failed to update integration");
      }
    } finally {
      setIsSaving(false);
    }
  };

  const handleSaveKeys = async () => {
    try {
      setIsSaving(true);
      const updated = await providerApi.updateYocoIntegration({
        secret_key: formData.secret_key,
        public_key: formData.public_key,
        webhook_secret: formData.webhook_secret,
      });
      setIntegration(updated);
      invalidateSetupStatusCache();
      toast.success("API keys saved successfully");
      setShowKeys(false);
    } catch (error: any) {
      console.error("Failed to save keys:", error);
      if (error?.code === "SUBSCRIPTION_REQUIRED" || error?.error?.code === "SUBSCRIPTION_REQUIRED") {
        setSubscriptionRequired(true);
        toast.error("Subscription upgrade required to configure Yoco integration");
      } else {
        toast.error("Failed to save API keys");
      }
    } finally {
      setIsSaving(false);
    }
  };

  const breadcrumbs = [
    { label: "Home", href: "/" },
    { label: "Provider", href: "/provider" },
    { label: "Settings", href: "/provider/settings" },
    { label: "Yoco Integration" },
  ];

  if (isLoading) {
    return (
      <SettingsDetailLayout 
        title="Yoco Integration" 
        subtitle="Connect your Yoco payment devices to accept card payments"
        breadcrumbs={breadcrumbs}
      >
        <div className="space-y-6">
          <div className="h-8 bg-gray-200 rounded animate-pulse" />
          <div className="h-64 bg-gray-200 rounded animate-pulse" />
        </div>
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout 
      title="Yoco Integration" 
      subtitle="Connect your Yoco payment devices to accept card payments"
      breadcrumbs={breadcrumbs}
    >
      <div className="space-y-6">
        {/* Subscription Gate */}
        {subscriptionRequired && (
          <SubscriptionGate
            feature="yoco_integration"
            message="Yoco integration requires a subscription upgrade"
            upgradeMessage="Upgrade to Starter plan or higher to connect Yoco payment devices"
          />
        )}

        {/* Integration Status */}
        <SectionCard>
          <div className="flex items-center justify-between mb-4">
            <div>
              <h3 className="text-lg font-semibold mb-1">Yoco Integration</h3>
              <p className="text-sm text-gray-600">
                Enable Yoco Web POS to accept card payments on your devices
              </p>
            </div>
            <div className="flex items-center gap-3">
              {integration?.is_enabled ? (
                <Badge variant="default" className="bg-green-500">
                  <CheckCircle2 className="w-3 h-3 mr-1" />
                  Connected
                </Badge>
              ) : (
                <Badge variant="secondary">
                  <XCircle className="w-3 h-3 mr-1" />
                  Disconnected
                </Badge>
              )}
              <Switch
                checked={integration?.is_enabled || false}
                onCheckedChange={handleToggle}
                disabled={isSaving}
              />
            </div>
          </div>

          {integration?.is_enabled && (
            <Alert className="bg-green-50 border-green-200">
              <CheckCircle2 className="h-4 w-4 text-green-600" />
              <AlertDescription className="text-green-800">
                Yoco integration is active. You can now process payments through your connected devices.
              </AlertDescription>
            </Alert>
          )}
        </SectionCard>

        {/* API Keys */}
        <SectionCard>
          <div className="flex items-center justify-between mb-4">
            <div>
              <h3 className="text-lg font-semibold mb-1">API Credentials</h3>
              <p className="text-sm text-gray-600">
                Your Yoco API keys for secure payment processing
              </p>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setShowKeys(!showKeys)}
            >
              {showKeys ? "Hide" : "Show"} Keys
            </Button>
          </div>

          {showKeys ? (
            <div className="space-y-4">
              <div>
                <Label htmlFor="secret_key">Secret Key</Label>
                <Input
                  id="secret_key"
                  type="password"
                  placeholder="sk_live_..."
                  value={formData.secret_key}
                  onChange={(e) =>
                    setFormData({ ...formData, secret_key: e.target.value })
                  }
                  className="mt-1"
                />
                <p className="text-xs text-gray-500 mt-1">
                  Keep this key secure. Never share it publicly.
                </p>
              </div>

              <div>
                <Label htmlFor="public_key">Public Key</Label>
                <Input
                  id="public_key"
                  type="text"
                  placeholder="pk_live_..."
                  value={formData.public_key}
                  onChange={(e) =>
                    setFormData({ ...formData, public_key: e.target.value })
                  }
                  className="mt-1"
                />
              </div>

              <div>
                <Label htmlFor="webhook_secret">Webhook Secret (Optional)</Label>
                <Input
                  id="webhook_secret"
                  type="password"
                  placeholder="whsec_..."
                  value={formData.webhook_secret}
                  onChange={(e) =>
                    setFormData({ ...formData, webhook_secret: e.target.value })
                  }
                  className="mt-1"
                />
                <p className="text-xs text-gray-500 mt-1">
                  Used to verify webhook requests from Yoco
                </p>
              </div>

              <div className="flex gap-3">
                <Button onClick={handleSaveKeys} disabled={isSaving}>
                  Save Keys
                </Button>
                <Button
                  variant="outline"
                  onClick={() => {
                    // Reset to empty if keys are masked, otherwise reset to current values
                    setFormData({
                      secret_key: integration?.secret_key && integration.secret_key !== "***" ? integration.secret_key : "",
                      public_key: integration?.public_key && integration.public_key !== "***" ? integration.public_key : "",
                      webhook_secret: integration?.webhook_secret && integration.webhook_secret !== "***" ? integration.webhook_secret : "",
                    });
                  }}
                >
                  Reset
                </Button>
              </div>
            </div>
          ) : (
            <div className="text-sm text-gray-600">
              {integration?.secret_key && integration.secret_key !== "***" ? (
                <p>API keys are configured. Click "Show Keys" to view or update them.</p>
              ) : integration?.secret_key === "***" ? (
                <p>API keys are configured (masked for security). Click "Show Keys" to update them.</p>
              ) : (
                <p>No API keys configured. Add your Yoco API credentials to get started.</p>
              )}
            </div>
          )}

          <div className="mt-4 pt-4 border-t">
            <a
              href="https://developer.yoco.com/api-reference"
              target="_blank"
              rel="noopener noreferrer"
              className="text-sm text-pink-600 hover:text-pink-700 flex items-center gap-2"
            >
              <ExternalLink className="w-4 h-4" />
              View Yoco API Documentation
            </a>
          </div>
        </SectionCard>

        {/* Connected Devices */}
        <SectionCard>
          <div className="flex items-center justify-between mb-4">
            <div>
              <h3 className="text-lg font-semibold mb-1">Payment Devices</h3>
              <p className="text-sm text-gray-600">
                Manage your Yoco Web POS devices
              </p>
            </div>
            <Link href="/provider/settings/sales/yoco-devices">
              <Button variant="outline" size="sm">
                <CreditCard className="w-4 h-4 mr-2" />
                Manage Devices
              </Button>
            </Link>
          </div>

          {devices.length === 0 ? (
            <div className="text-center py-8 text-gray-500">
              <CreditCard className="w-12 h-12 mx-auto mb-3 text-gray-400" />
              <p className="text-sm">No devices connected</p>
              <Link href="/provider/settings/sales/yoco-devices">
                <Button variant="outline" size="sm" className="mt-3">
                  Add Your First Device
                </Button>
              </Link>
            </div>
          ) : (
            <div className="space-y-3">
              {devices.slice(0, 3).map((device) => (
                <div
                  key={device.id}
                  className="flex items-center justify-between p-3 border border-gray-200 rounded-lg"
                >
                  <div>
                    <p className="font-medium">{device.name}</p>
                    <p className="text-sm text-gray-600">
                      {device.location_name || "No location"} ΓÇó {device.total_transactions || 0} transactions
                    </p>
                  </div>
                  <Badge variant={device.is_active ? "default" : "secondary"}>
                    {device.is_active ? "Active" : "Inactive"}
                  </Badge>
                </div>
              ))}
              {devices.length > 3 && (
                <Link href="/provider/settings/sales/yoco-devices">
                  <Button variant="ghost" size="sm" className="w-full">
                    View all {devices.length} devices
                  </Button>
                </Link>
              )}
            </div>
          )}
        </SectionCard>

        {/* Connection Info */}
        {integration?.connected_date && (
          <SectionCard>
            <h3 className="text-lg font-semibold mb-3">Connection Details</h3>
            <div className="space-y-2 text-sm">
              <div className="flex justify-between">
                <span className="text-gray-600">Connected:</span>
                <span>{new Date(integration.connected_date).toLocaleDateString()}</span>
              </div>
              {integration.last_sync && (
                <div className="flex justify-between">
                  <span className="text-gray-600">Last Sync:</span>
                  <span>{new Date(integration.last_sync).toLocaleString()}</span>
                </div>
              )}
            </div>
          </SectionCard>
        )}
      </div>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { useModuleConfig, useFeatureFlag } from "@/providers/ConfigBundleProvider";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import { MapPin, Loader2 } from "lucide-react";
import LoadingTimeout from "@/components/ui/loading-timeout";
import { Alert, AlertDescription } from "@/components/ui/alert";

type ServiceArea = {
  provider_id: string;
  mode: "radius" | "zones";
  radius_km: number | null;
  home_latitude: number | null;
  home_longitude: number | null;
  zones: any[];
};

export default function ServiceAreaPage() {
  const distanceConfig = useModuleConfig("distance") as { enabled?: boolean; default_radius_km?: number; max_radius_km?: number } | undefined;
  const radiusEnabled = useFeatureFlag("distance.provider_radius.enabled");
  const [data, setData] = useState<ServiceArea | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    mode: "radius" as "radius" | "zones",
    radius_km: "",
    home_latitude: "",
    home_longitude: "",
  });

  const enabled = Boolean(distanceConfig?.enabled) || radiusEnabled;

  useEffect(() => {
    (async () => {
      try {
        const res = await fetcher.get<{ data: ServiceArea | null }>("/api/provider/service-area");
        const d = res.data;
        if (d) {
          setData(d);
          setForm({
            mode: d.mode ?? "radius",
            radius_km: d.radius_km != null ? String(d.radius_km) : "",
            home_latitude: d.home_latitude != null ? String(d.home_latitude) : "",
            home_longitude: d.home_longitude != null ? String(d.home_longitude) : "",
          });
        }
      } catch {
        setData(null);
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const save = async () => {
    setSaving(true);
    try {
      await fetcher.put("/api/provider/service-area", {
        mode: form.mode,
        radius_km: form.mode === "radius" && form.radius_km ? parseFloat(form.radius_km) : null,
        home_latitude: form.mode === "radius" && form.home_latitude ? parseFloat(form.home_latitude) : null,
        home_longitude: form.mode === "radius" && form.home_longitude ? parseFloat(form.home_longitude) : null,
        zones: form.mode === "zones" ? (data?.zones ?? []) : [],
      });
      toast.success("Service area saved");
      const res = await fetcher.get<{ data: ServiceArea | null }>("/api/provider/service-area");
      setData(res.data ?? null);
    } catch {
      toast.error("Failed to save");
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <SettingsDetailLayout title="Service area" subtitle="Set your service radius or zones for house calls.">
        <LoadingTimeout loadingMessage="Loading..." />
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout title="Service area" subtitle="Define how far you travel for at-home bookings (Tinder-style radius).">
      {!enabled && (
        <Alert className="mb-6">
          <AlertDescription>Service area is not enabled. Enable the distance module in Control Plane to use this.</AlertDescription>
        </Alert>
      )}

      <SectionCard title="Service area">
        <div className="space-y-6">
          <RadioGroup
            value={form.mode}
            onValueChange={(v) => setForm((p) => ({ ...p, mode: v as "radius" | "zones" }))}
            className="flex gap-4"
          >
            <div className="flex items-center space-x-2">
              <RadioGroupItem value="radius" id="mode-radius" />
              <Label htmlFor="mode-radius">Radius (km from my location)</Label>
            </div>
            <div className="flex items-center space-x-2">
              <RadioGroupItem value="zones" id="mode-zones" />
              <Label htmlFor="mode-zones">Zones (use Service Zones)</Label>
            </div>
          </RadioGroup>

          {form.mode === "radius" && (
            <>
              <div>
                <Label>Radius (km)</Label>
                <Input
                  type="number"
                  min={0}
                  step={0.5}
                  placeholder={String(distanceConfig?.default_radius_km ?? 10)}
                  value={form.radius_km}
                  onChange={(e) => setForm((p) => ({ ...p, radius_km: e.target.value }))}
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Home latitude (optional)</Label>
                  <Input
                    type="number"
                    step="any"
                    placeholder="e.g. -33.9249"
                    value={form.home_latitude}
                    onChange={(e) => setForm((p) => ({ ...p, home_latitude: e.target.value }))}
                  />
                </div>
                <div>
                  <Label>Home longitude (optional)</Label>
                  <Input
                    type="number"
                    step="any"
                    placeholder="e.g. 18.4241"
                    value={form.home_longitude}
                    onChange={(e) => setForm((p) => ({ ...p, home_longitude: e.target.value }))}
                  />
                </div>
              </div>
            </>
          )}

          {form.mode === "zones" && (
            <p className="text-sm text-muted-foreground">
              Manage your service zones in <a href="/provider/settings/service-zones" className="text-primary underline">Service Zones</a>. They will be used for at-home booking availability.
            </p>
          )}

          <Button onClick={save} disabled={saving || !enabled}>
            {saving ? <><Loader2 className="h-4 w-4 animate-spin mr-2" /> SavingΓÇª</> : <><MapPin className="h-4 w-4 mr-2" /> Save</>}
          </Button>
        </div>
      </SectionCard>
    </SettingsDetailLayout>
  );
}

