"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { PageHeader } from "@/components/provider/PageHeader";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { Plus, Edit, Trash2, Loader2, TrendingUp, CheckCircle2, XCircle, Sparkles } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import ZoneMapViewer from "@/components/mapbox/ZoneMapViewer";
import { OnboardingTour } from "@/components/onboarding/OnboardingTour";

interface PlatformZone {
  id: string;
  name: string;
  zone_type: "postal_code" | "city" | "polygon" | "radius";
  postal_codes?: string[];
  cities?: string[];
  polygon_coordinates?: any;
  center_latitude?: number;
  center_longitude?: number;
  radius_km?: number;
  description?: string;
  is_active: boolean;
}

interface ZoneSelection {
  id: string;
  platform_zone_id: string;
  travel_fee: number;
  currency: string;
  travel_time_minutes: number;
  description?: string;
  is_active: boolean;
}

interface ZoneWithSelection {
  platform_zone: PlatformZone;
  selection: ZoneSelection | null;
  is_selected: boolean;
}

export default function ServiceZonesPage() {
  const [zonesWithSelections, setZonesWithSelections] = useState<ZoneWithSelection[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [selectedPlatformZone, setSelectedPlatformZone] = useState<PlatformZone | null>(null);
  const [editingSelection, setEditingSelection] = useState<ZoneSelection | null>(null);
  const [formData, setFormData] = useState({
    travel_fee: 0,
    currency: "ZAR",
    travel_time_minutes: 30,
    description: "",
    is_active: true,
  });
  const [providerLocation, setProviderLocation] = useState<{ latitude: number; longitude: number } | undefined>();
  const [suggestedZones, setSuggestedZones] = useState<any[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(true);

  // Onboarding tour steps
  const tourSteps = [
    {
      id: "intro",
      title: "Welcome to Service Zones",
      description: "Service zones define where you offer at-home services. Select zones that match your business location and set your travel fees.",
      targetSelector: "[data-tour='page-header']",
      position: "bottom" as const,
    },
    {
      id: "suggested-zones",
      title: "Suggested Zones",
      description: "These zones match your primary business location. We recommend selecting them first for faster setup.",
      targetSelector: "[data-tour='suggested-zones']",
      position: "bottom" as const,
    },
    {
      id: "selected-zones",
      title: "Your Selected Zones",
      description: "Zones you've selected will appear here. You can edit pricing or remove zones at any time.",
      targetSelector: "[data-tour='selected-zones']",
      position: "bottom" as const,
    },
    {
      id: "available-zones",
      title: "Available Zones",
      description: "Browse all platform zones. Click 'Select Zone' to add them and set your custom pricing.",
      targetSelector: "[data-tour='available-zones']",
      position: "top" as const,
    },
  ];

  useEffect(() => {
    loadZones();
    loadProviderLocation();
    loadSuggestedZones();
  }, []);

  const loadSuggestedZones = async () => {
    try {
      const response = await fetcher.get<{ data: { suggested_zones: any[] } }>("/api/provider/zone-selections/suggest");
      setSuggestedZones(response.data?.suggested_zones || []);
    } catch (error) {
      console.warn("Failed to load suggested zones:", error);
    }
  };

  const loadProviderLocation = async () => {
    try {
      const response = await fetcher.get<{ data: any[] }>("/api/provider/locations");
      const primaryLocation = response.data?.find((loc: any) => loc.is_primary);
      const lat = primaryLocation?.latitude ?? primaryLocation?.address_lat;
      const lng = primaryLocation?.longitude ?? primaryLocation?.address_lng;
      if (lat != null && lng != null) {
        setProviderLocation({ latitude: lat, longitude: lng });
      }
    } catch (error) {
      console.warn("Failed to load provider location:", error);
    }
  };

  const loadZones = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data: ZoneWithSelection[] }>("/api/provider/zone-selections");
      setZonesWithSelections(response.data || []);
    } catch (error) {
      toast.error("Failed to load platform zones");
      console.error("Error loading zones:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSelectZone = (platformZone: PlatformZone) => {
    setSelectedPlatformZone(platformZone);
    setEditingSelection(null);
    setFormData({
      travel_fee: 0,
      currency: "ZAR",
      travel_time_minutes: 30,
      description: "",
      is_active: true,
    });
    setIsDialogOpen(true);
  };

  const handleEditSelection = (zoneWithSelection: ZoneWithSelection) => {
    if (!zoneWithSelection.selection) return;
    setSelectedPlatformZone(zoneWithSelection.platform_zone);
    setEditingSelection(zoneWithSelection.selection);
    setFormData({
      travel_fee: zoneWithSelection.selection.travel_fee,
      currency: zoneWithSelection.selection.currency,
      travel_time_minutes: zoneWithSelection.selection.travel_time_minutes,
      description: zoneWithSelection.selection.description || "",
      is_active: zoneWithSelection.selection.is_active,
    });
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    if (!selectedPlatformZone) return;

    try {
      setIsSaving(true);

      if (editingSelection) {
        // Update existing selection
        await fetcher.patch(`/api/provider/zone-selections/${editingSelection.id}`, {
          ...formData,
        });
        toast.success("Zone selection updated");
      } else {
        // Create new selection
        await fetcher.post("/api/provider/zone-selections", {
          platform_zone_id: selectedPlatformZone.id,
          ...formData,
        });
        toast.success("Zone selected successfully");
      }

      setIsDialogOpen(false);
      setSelectedPlatformZone(null);
      setEditingSelection(null);
      loadZones();
    } catch (error) {
      toast.error(
        error instanceof FetchError
          ? error.message
          : "Failed to save zone selection"
      );
      console.error("Error saving selection:", error);
    } finally {
      setIsSaving(false);
    }
  };

  const handleRemoveSelection = async (selectionId: string) => {
    if (!confirm("Are you sure you want to remove this zone selection?")) {
      return;
    }

    try {
      await fetcher.delete(`/api/provider/zone-selections/${selectionId}`);
      toast.success("Zone selection removed");
      loadZones();
    } catch (error) {
      toast.error("Failed to remove zone selection");
      console.error("Error removing selection:", error);
    }
  };

  const getZoneTypeLabel = (type: PlatformZone["zone_type"]) => {
    const labels: Record<PlatformZone["zone_type"], string> = {
      postal_code: "Postal Code",
      city: "City",
      polygon: "Polygon",
      radius: "Radius",
    };
    return labels[type];
  };

  const getZoneDetails = (zone: PlatformZone) => {
    if (zone.zone_type === "postal_code" && zone.postal_codes) {
      return `${zone.postal_codes.length} postal codes`;
    }
    if (zone.zone_type === "city" && zone.cities) {
      return `${zone.cities.length} cities`;
    }
    if (zone.zone_type === "radius" && zone.radius_km) {
      return `${zone.radius_km}km radius`;
    }
    if (zone.zone_type === "polygon") {
      return "Polygon zone";
    }
    return "-";
  };

  const selectedZones = zonesWithSelections.filter((z) => z.is_selected);
  const availableZones = zonesWithSelections.filter((z) => !z.is_selected);

  const breadcrumbs = [
    { label: "Home", href: "/" },
    { label: "Provider", href: "/provider" },
    { label: "Settings", href: "/provider/settings" },
    { label: "Service Zones" },
  ];

  if (isLoading) {
    return (
      <SettingsDetailLayout breadcrumbs={breadcrumbs}>
        <LoadingTimeout loadingMessage="Loading platform zones..." />
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout breadcrumbs={breadcrumbs}>
      <OnboardingTour
        steps={tourSteps}
        storageKey="service-zones-tour-completed"
        onComplete={() => {
          toast.success("Tour completed! You can restart it anytime from the help menu.");
        }}
      />

      <PageHeader
        title="Service Zones"
        subtitle="Select platform zones where you provide at-home services and set your own pricing. You can only select from zones created by the platform administrator."
        data-tour="page-header"
      />

      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <Button
            variant="outline"
            onClick={() => {
              localStorage.removeItem("service-zones-tour-completed");
              window.location.reload();
            }}
            className="text-sm"
          >
            <Sparkles className="w-4 h-4 mr-2" />
            Restart Tour
          </Button>
          <Button
            variant="outline"
            onClick={() => window.location.href = "/provider/settings/service-zones/analytics"}
          >
            <TrendingUp className="w-4 h-4 mr-2" />
            View Analytics
          </Button>
        </div>

        {/* Suggested Zones Based on Location */}
        {showSuggestions && suggestedZones.length > 0 && (
          <SectionCard className="bg-blue-50 border-blue-200" data-tour="suggested-zones">
            <div className="flex items-start justify-between mb-4">
              <div>
                <h3 className="font-semibold text-lg mb-1 flex items-center gap-2">
                  <CheckCircle2 className="w-5 h-5 text-blue-600" />
                  Suggested Zones (Based on Your Location)
                </h3>
                <p className="text-sm text-gray-600">
                  These zones match your primary business location. We recommend selecting them first.
                </p>
              </div>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setShowSuggestions(false)}
              >
                <XCircle className="w-4 h-4" />
              </Button>
            </div>
            <div className="grid gap-4">
              {suggestedZones.map((zone) => {
                const existingSelection = zonesWithSelections.find(
                  (z) => z.platform_zone.id === zone.id
                );
                const isSelected = existingSelection?.is_selected || false;

                return (
                  <div
                    key={zone.id}
                    className="border-2 border-blue-300 rounded-lg p-4 bg-white hover:bg-blue-50 transition-colors"
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-2">
                          <h4 className="font-semibold">{zone.name}</h4>
                          <Badge variant="default" className="bg-blue-600">
                            Suggested
                          </Badge>
                          <Badge variant="outline">{getZoneTypeLabel(zone.zone_type)}</Badge>
                        </div>
                        <p className="text-sm text-blue-700 mb-2">
                          {zone.match_reason}
                        </p>
                        <div className="space-y-1 text-sm text-gray-600">
                          <p>
                            <strong>Zone Details:</strong> {getZoneDetails(zone)}
                          </p>
                        </div>
                      </div>
                      {isSelected ? (
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => existingSelection && handleEditSelection(existingSelection)}
                        >
                          <Edit className="w-4 h-4 mr-2" />
                          Edit
                        </Button>
                      ) : (
                        <Button
                          onClick={() => handleSelectZone(zone)}
                          className="bg-[#FF0077] hover:bg-[#D60565]"
                        >
                          <Plus className="w-4 h-4 mr-2" />
                          Select Zone
                        </Button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </SectionCard>
        )}

        {/* Selected Zones */}
        {selectedZones.length > 0 && (
          <SectionCard data-tour="selected-zones">
            <h3 className="font-semibold text-lg mb-4">Your Selected Zones</h3>
            <div className="grid gap-4">
              {selectedZones.map((zoneWithSelection) => (
                <div
                  key={zoneWithSelection.platform_zone.id}
                  className="border rounded-lg p-4 hover:bg-gray-50 transition-colors"
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <h4 className="font-semibold">{zoneWithSelection.platform_zone.name}</h4>
                        <Badge variant={zoneWithSelection.selection?.is_active ? "default" : "secondary"}>
                          {zoneWithSelection.selection?.is_active ? "Active" : "Inactive"}
                        </Badge>
                        <Badge variant="outline">{getZoneTypeLabel(zoneWithSelection.platform_zone.zone_type)}</Badge>
                      </div>
                      <div className="space-y-1 text-sm text-gray-600">
                        <p>
                          <strong>Your Travel Fee:</strong> {zoneWithSelection.selection?.currency} {zoneWithSelection.selection?.travel_fee.toFixed(2)}
                        </p>
                        <p>
                          <strong>Travel Time:</strong> {zoneWithSelection.selection?.travel_time_minutes} minutes
                        </p>
                        <p>
                          <strong>Zone Details:</strong> {getZoneDetails(zoneWithSelection.platform_zone)}
                        </p>
                        {zoneWithSelection.platform_zone.description && (
                          <p className="mt-2 text-gray-500">{zoneWithSelection.platform_zone.description}</p>
                        )}
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleEditSelection(zoneWithSelection)}
                      >
                        <Edit className="w-4 h-4" />
                      </Button>
                      {zoneWithSelection.selection && (
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleRemoveSelection(zoneWithSelection.selection!.id)}
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </SectionCard>
        )}

        {/* Available Zones */}
        <SectionCard data-tour="available-zones">
          <h3 className="font-semibold text-lg mb-4">Available Platform Zones</h3>
          {availableZones.length === 0 ? (
            <EmptyState
              title="No available zones"
              description="All platform zones have been selected, or no platform zones are available. Contact support if you need additional zones."
            />
          ) : (
            <div className="grid gap-4">
              {availableZones.map((zoneWithSelection) => (
                <div
                  key={zoneWithSelection.platform_zone.id}
                  className="border rounded-lg p-4 hover:bg-gray-50 transition-colors"
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <h4 className="font-semibold">{zoneWithSelection.platform_zone.name}</h4>
                        <Badge variant="outline">{getZoneTypeLabel(zoneWithSelection.platform_zone.zone_type)}</Badge>
                      </div>
                      <div className="space-y-1 text-sm text-gray-600">
                        <p>
                          <strong>Zone Details:</strong> {getZoneDetails(zoneWithSelection.platform_zone)}
                        </p>
                        {zoneWithSelection.platform_zone.description && (
                          <p className="mt-2 text-gray-500">{zoneWithSelection.platform_zone.description}</p>
                        )}
                      </div>
                    </div>
                    <Button
                      onClick={() => handleSelectZone(zoneWithSelection.platform_zone)}
                      className="bg-[#FF0077] hover:bg-[#D60565]"
                    >
                      <Plus className="w-4 h-4 mr-2" />
                      Select Zone
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </SectionCard>

        {/* Map Visualization */}
        {selectedZones.length > 0 && (
          <SectionCard>
            <h3 className="font-semibold mb-4">Zone Map</h3>
            <ZoneMapViewer
              zones={selectedZones.map((z) => ({
                id: z.platform_zone.id,
                name: z.platform_zone.name,
                zone_type: z.platform_zone.zone_type,
                polygon_coordinates: z.platform_zone.polygon_coordinates,
                center_latitude: z.platform_zone.center_latitude,
                center_longitude: z.platform_zone.center_longitude,
                radius_km: z.platform_zone.radius_km,
                travel_fee: z.selection?.travel_fee || 0,
                is_active: z.selection?.is_active || false,
              }))}
              providerLocation={providerLocation}
              height="400px"
            />
          </SectionCard>
        )}
      </div>

      {/* Select/Edit Zone Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editingSelection ? "Edit Zone Selection" : "Select Platform Zone"}
            </DialogTitle>
            <DialogDescription>
              {selectedPlatformZone && (
                <>
                  Setting pricing for <strong>{selectedPlatformZone.name}</strong>. Customers can only book at-home services if their address is within this zone.
                </>
              )}
            </DialogDescription>
          </DialogHeader>

          {selectedPlatformZone && (
            <div className="space-y-4">
              <div className="bg-gray-50 rounded-lg p-4">
                <p className="text-sm font-medium mb-2">Platform Zone: {selectedPlatformZone.name}</p>
                <p className="text-xs text-gray-600">
                  Type: {getZoneTypeLabel(selectedPlatformZone.zone_type)} ΓÇó {getZoneDetails(selectedPlatformZone)}
                </p>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="travel_fee">Travel Fee *</Label>
                  <Input
                    id="travel_fee"
                    type="number"
                    step="0.01"
                    min="0"
                    value={formData.travel_fee}
                    onChange={(e) => setFormData({ ...formData, travel_fee: parseFloat(e.target.value) || 0 })}
                    required
                  />
                </div>
                <div>
                  <Label htmlFor="currency">Currency *</Label>
                  <Input
                    id="currency"
                    value={formData.currency}
                    onChange={(e) => setFormData({ ...formData, currency: e.target.value.toUpperCase() })}
                    maxLength={3}
                    required
                  />
                </div>
              </div>

              <div>
                <Label htmlFor="travel_time_minutes">Travel Time (minutes) *</Label>
                <Input
                  id="travel_time_minutes"
                  type="number"
                  min="1"
                  value={formData.travel_time_minutes}
                  onChange={(e) => setFormData({ ...formData, travel_time_minutes: parseInt(e.target.value) || 30 })}
                  required
                />
              </div>

              <div>
                <Label htmlFor="description">Description (Optional)</Label>
                <Textarea
                  id="description"
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  placeholder="Optional notes about this zone"
                  rows={3}
                />
              </div>

              <div className="flex items-center space-x-2">
                <Checkbox
                  id="is_active"
                  checked={formData.is_active}
                  onCheckedChange={(checked) => setFormData({ ...formData, is_active: checked === true })}
                />
                <Label htmlFor="is_active" className="cursor-pointer">
                  Active (accept bookings in this zone)
                </Label>
              </div>

              <div className="flex justify-end gap-2 pt-4">
                <Button variant="outline" onClick={() => {
                  setIsDialogOpen(false);
                  setSelectedPlatformZone(null);
                  setEditingSelection(null);
                }} disabled={isSaving}>
                  Cancel
                </Button>
                <Button onClick={handleSave} disabled={isSaving} className="bg-[#FF0077] hover:bg-[#D60565]">
                  {isSaving ? (
                    <>
                      <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                      Saving...
                    </>
                  ) : (
                    editingSelection ? "Update" : "Select Zone"
                  )}
                </Button>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Plus, Edit, Trash2 } from "lucide-react";
import EmptyState from "@/components/ui/empty-state";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import LoadingTimeout from "@/components/ui/loading-timeout";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";

interface MembershipPlan {
  id: string;
  name: string;
  description: string | null;
  price_monthly: number;
  currency: string;
  discount_percent: number;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

export default function MembershipsSettings() {
  const [plans, setPlans] = useState<MembershipPlan[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingPlan, setEditingPlan] = useState<MembershipPlan | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    description: "",
    price_monthly: "",
    discount_percent: "",
    is_active: true,
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const loadPlans = async () => {
    try {
      setIsLoading(true);
      const res = await fetcher.get<{ data: { plans: MembershipPlan[] } }>(`/api/provider/membership-plans`);
      setPlans(res.data.plans || []);
    } catch (error: any) {
      console.error("Error loading membership plans:", error);
      const errorMessage = error instanceof FetchError
        ? error.message
        : error?.error?.message || "Failed to load membership plans";
      toast.error(errorMessage);
      setPlans([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadPlans();
  }, []);

  const handleCreate = () => {
    setEditingPlan(null);
    setFormData({
      name: "",
      description: "",
      price_monthly: "",
      discount_percent: "",
      is_active: true,
    });
    setIsDialogOpen(true);
  };

  const handleEdit = (plan: MembershipPlan) => {
    setEditingPlan(plan);
    setFormData({
      name: plan.name,
      description: plan.description || "",
      price_monthly: plan.price_monthly.toString(),
      discount_percent: plan.discount_percent.toString(),
      is_active: plan.is_active,
    });
    setIsDialogOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this membership plan? This action cannot be undone.")) return;

    try {
      await fetcher.delete(`/api/provider/membership-plans/${id}`);
      toast.success("Membership plan deleted successfully");
      await loadPlans();
    } catch (error: any) {
      const errorMessage = error instanceof FetchError
        ? error.message
        : error?.error?.message || "Failed to delete membership plan";
      toast.error(errorMessage);
      console.error("Error deleting membership plan:", error);
    }
  };

  const handleSave = async () => {
    try {
      if (!formData.name.trim()) {
        toast.error("Plan name is required");
        return;
      }

      const priceNum = Number(formData.price_monthly);
      if (!Number.isFinite(priceNum) || priceNum < 0) {
        toast.error("Please enter a valid price (0 or greater)");
        return;
      }

      const discountNum = formData.discount_percent ? Number(formData.discount_percent) : 0;
      if (!Number.isFinite(discountNum) || discountNum < 0 || discountNum > 100) {
        toast.error("Discount must be between 0 and 100");
        return;
      }

      setIsSubmitting(true);

      if (editingPlan) {
        await fetcher.patch(`/api/provider/membership-plans/${editingPlan.id}`, {
          name: formData.name.trim(),
          description: formData.description.trim() || null,
          price_monthly: priceNum,
          discount_percent: discountNum,
          is_active: formData.is_active,
        });
        toast.success("Membership plan updated successfully");
      } else {
        await fetcher.post(`/api/provider/membership-plans`, {
          name: formData.name.trim(),
          description: formData.description.trim() || null,
          price_monthly: priceNum,
          discount_percent: discountNum,
          is_active: formData.is_active,
        });
        toast.success("Membership plan created successfully");
      }

      setIsDialogOpen(false);
      await loadPlans();
    } catch (error: any) {
      const errorMessage = error instanceof FetchError
        ? error.message
        : error?.error?.message || "Failed to save membership plan";
      toast.error(errorMessage);
      console.error("Error saving membership plan:", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const formatCurrency = (amount: number, currency: string = "ZAR") => {
    return new Intl.NumberFormat("en-ZA", {
      style: "currency",
      currency: currency,
    }).format(amount);
  };

  return (
    <SettingsDetailLayout
      title="Memberships"
      subtitle="Set up membership plans for your clients"
      onSave={() => loadPlans()}
      breadcrumbs={[
        { label: "Home", href: "/" },
        { label: "Provider", href: "/provider" },
        { label: "Settings", href: "/provider/settings" },
        { label: "Memberships" },
      ]}
    >
      <div className="space-y-4 sm:space-y-6">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div>
            <p className="text-sm text-gray-600">
              Create membership plans that offer recurring services and discounts to your clients
            </p>
          </div>
          <Button
            onClick={handleCreate}
            className="w-full sm:w-auto bg-[#FF0077] hover:bg-[#D60565] min-h-[44px] touch-manipulation"
          >
            <Plus className="w-4 h-4 mr-2" />
            Add Plan
          </Button>
        </div>

        {isLoading ? (
          <SectionCard>
            <LoadingTimeout loadingMessage="Loading membership plans..." />
          </SectionCard>
        ) : plans.length === 0 ? (
          <SectionCard className="p-8 sm:p-12">
            <EmptyState
              title="No membership plans yet"
              description="Create membership plans to offer recurring services and discounts to your clients"
              action={{
                label: "Add Plan",
                onClick: handleCreate,
              }}
            />
          </SectionCard>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {plans.map((plan) => (
              <SectionCard key={plan.id} className="p-4 sm:p-6">
                <div className="flex items-start justify-between mb-3">
                  <div className="flex-1">
                    <h3 className="font-semibold text-base sm:text-lg mb-1">{plan.name}</h3>
                    {plan.description && (
                      <p className="text-sm text-gray-600 mb-2">{plan.description}</p>
                    )}
                    <div className="space-y-1 mb-2">
                      <p className="text-sm font-medium text-gray-900">
                        {formatCurrency(plan.price_monthly, plan.currency)}/month
                      </p>
                      {plan.discount_percent > 0 && (
                        <p className="text-sm text-gray-600">
                          {plan.discount_percent}% discount on services
                        </p>
                      )}
                    </div>
                    <Badge
                      className={plan.is_active ? "bg-green-100 text-green-800" : "bg-gray-100 text-gray-800"}
                    >
                      {plan.is_active ? "Active" : "Inactive"}
                    </Badge>
                  </div>
                </div>
                <div className="flex gap-2 mt-4">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => handleEdit(plan)}
                    className="flex-1 min-h-[36px] touch-manipulation"
                  >
                    <Edit className="w-3 h-3 mr-1" />
                    Edit
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => handleDelete(plan.id)}
                    className="text-red-600 hover:text-red-700 flex-1 min-h-[36px] touch-manipulation"
                  >
                    <Trash2 className="w-3 h-3 mr-1" />
                    Delete
                  </Button>
                </div>
              </SectionCard>
            ))}
          </div>
        )}
      </div>

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-[95vw] sm:max-w-md p-4 sm:p-6">
          <DialogHeader>
            <DialogTitle>
              {editingPlan ? "Edit Membership Plan" : "Add Membership Plan"}
            </DialogTitle>
            <DialogDescription>
              {editingPlan
                ? "Update membership plan information"
                : "Create a new membership plan for your clients"}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div>
              <Label htmlFor="name">Plan Name *</Label>
              <Input
                id="name"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                placeholder="e.g., Premium Membership"
                className="mt-1.5 min-h-[44px] touch-manipulation"
                required
              />
            </div>
            <div>
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="Optional description of the plan benefits"
                rows={3}
                className="mt-1.5"
              />
            </div>
            <div>
              <Label htmlFor="price_monthly">Monthly Price *</Label>
              <Input
                id="price_monthly"
                type="number"
                step="0.01"
                min="0"
                value={formData.price_monthly}
                onChange={(e) => setFormData({ ...formData, price_monthly: e.target.value })}
                placeholder="0.00"
                className="mt-1.5 min-h-[44px] touch-manipulation"
                required
              />
            </div>
            <div>
              <Label htmlFor="discount_percent">Discount Percentage</Label>
              <Input
                id="discount_percent"
                type="number"
                step="0.01"
                min="0"
                max="100"
                value={formData.discount_percent}
                onChange={(e) => setFormData({ ...formData, discount_percent: e.target.value })}
                placeholder="0"
                className="mt-1.5 min-h-[44px] touch-manipulation"
              />
              <p className="text-xs text-gray-500 mt-1">Discount percentage (0-100) applied to services</p>
            </div>
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                id="is_active"
                checked={formData.is_active}
                onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                className="w-4 h-4"
              />
              <Label htmlFor="is_active" className="cursor-pointer">
                Active
              </Label>
            </div>
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setIsDialogOpen(false)}
              className="min-h-[44px] touch-manipulation"
            >
              Cancel
            </Button>
            <Button
              onClick={handleSave}
              disabled={isSubmitting}
              className="bg-[#FF0077] hover:bg-[#D60565] min-h-[44px] touch-manipulation"
            >
              {isSubmitting ? "Saving..." : editingPlan ? "Update" : "Create"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Separator } from "@/components/ui/separator";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { providerApi } from "@/lib/provider-portal/api";
import { fetcher } from "@/lib/http/fetcher";
import type { TeamMember } from "@/lib/provider-portal/types";
import { toast } from "sonner";
import { DollarSign, Percent, Clock, Calendar, TrendingUp, Plus, Trash2 } from "lucide-react";
import { Skeleton } from "@/components/ui/skeleton";

interface CommissionTier {
  id?: string;
  min_revenue: number;
  commission_rate: number;
  tier_order?: number;
}

interface CommissionSettings {
  enabled: boolean;
  service_commission_rate: number;
  product_commission_rate: number;
  hourly_rate: number;
  salary: number;
  tips_enabled: boolean;
  tiers: CommissionTier[];
}

export default function CommissionsSettings() {
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [selectedMember, setSelectedMember] = useState<string | null>(null);
  const [settings, setSettings] = useState<CommissionSettings>({
    enabled: false,
    service_commission_rate: 0,
    product_commission_rate: 0,
    hourly_rate: 0,
    salary: 0,
    tips_enabled: true,
    tiers: [],
  });
  const [_compensationType, setCompensationType] = useState<"commission" | "hourly" | "salary" | "mixed">("commission");
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    loadTeamMembers();
  }, []);

  useEffect(() => {
    if (selectedMember) {
      loadCommissionSettings(selectedMember);
    }
  }, [selectedMember]);

  const loadTeamMembers = async () => {
    try {
      setIsLoading(true);
      const members = await providerApi.listTeamMembers();
      setTeamMembers(members.filter((m) => m.is_active));
      if (members.length > 0 && !selectedMember) {
        setSelectedMember(members[0].id);
      }
    } catch (error) {
      console.error("Failed to load team members:", error);
      toast.error("Failed to load team members");
    } finally {
      setIsLoading(false);
    }
  };

  const loadCommissionSettings = async (memberId: string) => {
    try {
      const response = await fetcher.get<{
        data: {
          enabled: boolean;
          serviceCommissionRate: number;
          productCommissionRate: number;
          hourlyRate: number;
          salary: number;
          tipsEnabled: boolean;
          tiers?: { id: string; minRevenue: number; commissionRate: number; tierOrder: number }[];
        };
      }>(`/api/provider/staff/${memberId}/commission`);
      const tiers = (response.data.tiers || []).map((t) => ({
        id: t.id,
        min_revenue: t.minRevenue,
        commission_rate: t.commissionRate,
        tier_order: t.tierOrder,
      }));
      setSettings({
        enabled: response.data.enabled,
        service_commission_rate: response.data.serviceCommissionRate,
        product_commission_rate: response.data.productCommissionRate,
        hourly_rate: response.data.hourlyRate,
        salary: response.data.salary,
        tips_enabled: response.data.tipsEnabled,
        tiers,
      });
      // Determine compensation type based on what's set
      if (response.data.salary > 0) {
        setCompensationType("salary");
      } else if (response.data.hourlyRate > 0) {
        setCompensationType("hourly");
      } else if (response.data.enabled) {
        setCompensationType("commission");
      } else {
        setCompensationType("commission");
      }
    } catch (error) {
      console.error("Failed to load commission settings:", error);
      // Use default values on error
      setSettings({
        enabled: false,
        service_commission_rate: 0,
        product_commission_rate: 0,
        hourly_rate: 0,
        salary: 0,
        tips_enabled: true,
        tiers: [],
      });
      setCompensationType("commission");
    }
  };

  const handleSave = async () => {
    if (!selectedMember) return;

    setIsSaving(true);
    try {
      await fetcher.patch(`/api/provider/staff/${selectedMember}/commission`, {
        commission_enabled: settings.enabled,
        service_commission_rate: settings.service_commission_rate,
        product_commission_rate: settings.product_commission_rate,
        hourly_rate: settings.hourly_rate,
        salary: settings.salary,
        tips_enabled: settings.tips_enabled,
        tiers: settings.tiers.map((t, i) => ({
          min_revenue: t.min_revenue,
          commission_rate: t.commission_rate,
          tier_order: t.tier_order ?? i,
        })),
      });
      toast.success("Commission settings saved successfully");
    } catch (error: any) {
      console.error("Failed to save commission settings:", error);
      toast.error(error.message || "Failed to save commission settings");
    } finally {
      setIsSaving(false);
    }
  };

  const selectedMemberData = teamMembers.find((m) => m.id === selectedMember);

  return (
    <SettingsDetailLayout
      title="Commissions & Compensation"
      subtitle="Configure how your team members are compensated"
      onSave={handleSave}
      saveLabel={isSaving ? "Saving..." : "Save Settings"}
      breadcrumbs={[
        { label: "Home", href: "/" },
        { label: "Provider", href: "/provider" },
        { label: "Settings", href: "/provider/settings" },
        { label: "Team", href: "/provider/settings/team/roles" },
        { label: "Commissions" },
      ]}
    >
      {isLoading ? (
        <SectionCard>
          <Skeleton className="h-64 w-full" />
        </SectionCard>
      ) : teamMembers.length === 0 ? (
        <SectionCard className="p-8 sm:p-12 text-center">
          <p className="text-gray-600 mb-4">No active team members found</p>
          <Button onClick={() => window.location.href = "/provider/team/members"}>
            Add Team Members
          </Button>
        </SectionCard>
      ) : (
        <div className="space-y-4 sm:space-y-6">
          {/* Team Member Selector */}
          <SectionCard>
            <div className="space-y-4">
              <div>
                <Label className="text-sm sm:text-base font-semibold mb-2 block">
                  Select Team Member
                </Label>
                <Select value={selectedMember || ""} onValueChange={setSelectedMember}>
                  <SelectTrigger className="min-h-[44px] touch-manipulation">
                    <SelectValue placeholder="Select a team member" />
                  </SelectTrigger>
                  <SelectContent>
                    {teamMembers.map((member) => (
                      <SelectItem key={member.id} value={member.id}>
                        <div className="flex items-center gap-2">
                          <Avatar className="w-6 h-6">
                            <AvatarFallback className="bg-[#FF0077]/10 text-[#FF0077] text-xs">
                              {member.name.charAt(0)}
                            </AvatarFallback>
                          </Avatar>
                          <span>{member.name}</span>
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {selectedMemberData && (
                <div className="p-3 sm:p-4 bg-gray-50 rounded-lg">
                  <div className="flex items-center gap-3">
                    <Avatar className="w-10 h-10 sm:w-12 sm:h-12">
                      <AvatarFallback className="bg-[#FF0077]/10 text-[#FF0077]">
                        {selectedMemberData.name.charAt(0)}
                      </AvatarFallback>
                    </Avatar>
                    <div>
                      <p className="font-medium text-sm sm:text-base">{selectedMemberData.name}</p>
                      <p className="text-xs sm:text-sm text-gray-500">{selectedMemberData.email}</p>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </SectionCard>

          {/* Compensation Settings */}
          {selectedMember && (
            <Tabs defaultValue="commission" className="w-full">
              <TabsList className="grid w-full grid-cols-2 sm:grid-cols-4 mb-4 sm:mb-6">
                <TabsTrigger value="commission" className="text-xs sm:text-sm">Commission</TabsTrigger>
                <TabsTrigger value="hourly" className="text-xs sm:text-sm">Hourly</TabsTrigger>
                <TabsTrigger value="salary" className="text-xs sm:text-sm">Salary</TabsTrigger>
                <TabsTrigger value="tips" className="text-xs sm:text-sm">Tips</TabsTrigger>
              </TabsList>

              {/* Commission Tab */}
              <TabsContent value="commission" className="space-y-4 sm:space-y-6">
                <SectionCard>
                  <div className="space-y-4">
                    <div className="flex items-start gap-4 p-4 bg-gray-50 rounded-lg">
                      <Switch
                        checked={settings.enabled}
                        onCheckedChange={(checked) => setSettings({ ...settings, enabled: checked })}
                        className="mt-1"
                      />
                      <div className="flex-1">
                        <Label className="text-sm sm:text-base font-medium cursor-pointer flex items-center gap-2">
                          <Percent className="w-4 h-4" />
                          Enable Commission
                        </Label>
                        <p className="text-xs text-gray-500 mt-1">
                          Enable commission-based compensation for this team member
                        </p>
                      </div>
                    </div>

                    {settings.enabled && (
                      <div className="ml-0 sm:ml-12 space-y-4 p-4 bg-blue-50 rounded-lg border border-blue-200">
                        <div>
                          <Label htmlFor="service_commission_rate" className="text-sm font-medium">
                            Service Commission Rate (%)
                          </Label>
                          <div className="relative mt-1.5">
                            <Input
                              id="service_commission_rate"
                              type="number"
                              min={0}
                              max={100}
                              step={0.1}
                              value={settings.service_commission_rate}
                              onChange={(e) =>
                                setSettings({
                                  ...settings,
                                  service_commission_rate: parseFloat(e.target.value) || 0,
                                })
                              }
                              className="min-h-[44px] touch-manipulation pr-10"
                              placeholder="0.0"
                            />
                            <Percent className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                          </div>
                          <p className="text-xs text-gray-500 mt-1.5">
                            Percentage of service price paid as commission
                          </p>
                        </div>

                        <Separator />

                        <div>
                          <Label htmlFor="product_commission_rate" className="text-sm font-medium">
                            Product Commission Rate (%)
                          </Label>
                          <div className="relative mt-1.5">
                            <Input
                              id="product_commission_rate"
                              type="number"
                              min={0}
                              max={100}
                              step={0.1}
                              value={settings.product_commission_rate}
                              onChange={(e) =>
                                setSettings({
                                  ...settings,
                                  product_commission_rate: parseFloat(e.target.value) || 0,
                                })
                              }
                              className="min-h-[44px] touch-manipulation pr-10"
                              placeholder="0.0"
                            />
                            <Percent className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                          </div>
                          <p className="text-xs text-gray-500 mt-1.5">
                            Percentage of product price paid as commission
                          </p>
                        </div>

                        <Separator />

                        <div>
                          <Label className="text-sm font-medium">Tiered Commission (Optional)</Label>
                          <p className="text-xs text-gray-500 mt-1 mb-3">
                            When period revenue reaches a threshold, the higher rate applies to all revenue. Add tiers in ascending order of min revenue.
                          </p>
                          <div className="space-y-3">
                            {settings.tiers.map((tier, idx) => (
                              <div key={tier.id ?? idx} className="flex items-center gap-2 p-3 bg-white border rounded-lg">
                                <div className="flex-1 grid grid-cols-2 gap-2">
                                  <div>
                                    <Label className="text-xs">Min Revenue (R)</Label>
                                    <Input
                                      type="number"
                                      min={0}
                                      step={1}
                                      value={tier.min_revenue}
                                      onChange={(e) => {
                                        const v = parseFloat(e.target.value) || 0;
                                        const next = [...settings.tiers];
                                        next[idx] = { ...next[idx], min_revenue: v };
                                        setSettings({ ...settings, tiers: next });
                                      }}
                                      placeholder="0"
                                      className="h-9"
                                    />
                                  </div>
                                  <div>
                                    <Label className="text-xs">Rate (%)</Label>
                                    <Input
                                      type="number"
                                      min={0}
                                      max={100}
                                      step={0.1}
                                      value={tier.commission_rate}
                                      onChange={(e) => {
                                        const v = parseFloat(e.target.value) || 0;
                                        const next = [...settings.tiers];
                                        next[idx] = { ...next[idx], commission_rate: v };
                                        setSettings({ ...settings, tiers: next });
                                      }}
                                      placeholder="0"
                                      className="h-9"
                                    />
                                  </div>
                                </div>
                                <Button
                                  type="button"
                                  variant="ghost"
                                  size="icon"
                                  className="text-red-600 hover:text-red-700 shrink-0 mt-5"
                                  onClick={() => {
                                    const next = settings.tiers.filter((_, i) => i !== idx);
                                    setSettings({ ...settings, tiers: next });
                                  }}
                                >
                                  <Trash2 className="w-4 h-4" />
                                </Button>
                              </div>
                            ))}
                            <Button
                              type="button"
                              variant="outline"
                              size="sm"
                              onClick={() =>
                                setSettings({
                                  ...settings,
                                  tiers: [...settings.tiers, { min_revenue: 0, commission_rate: 0 }],
                                })
                              }
                            >
                              <Plus className="w-4 h-4 mr-1" />
                              Add tier
                            </Button>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </SectionCard>
              </TabsContent>

              {/* Hourly Tab */}
              <TabsContent value="hourly" className="space-y-4 sm:space-y-6">
                <SectionCard>
                  <div className="space-y-4">
                    <div>
                      <Label htmlFor="hourly_rate" className="text-sm sm:text-base font-medium">
                        Hourly Rate (R)
                      </Label>
                      <div className="relative mt-1.5">
                        <Input
                          id="hourly_rate"
                          type="number"
                          min={0}
                          step={0.01}
                          value={settings.hourly_rate}
                          onChange={(e) =>
                            setSettings({
                              ...settings,
                              hourly_rate: parseFloat(e.target.value) || 0,
                            })
                          }
                          className="min-h-[44px] touch-manipulation pl-8"
                          placeholder="0.00"
                        />
                        <DollarSign className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                      </div>
                      <p className="text-xs text-gray-500 mt-1.5">
                        Hourly wage for hourly-based compensation
                      </p>
                    </div>

                    <div className="p-3 sm:p-4 bg-blue-50 rounded-lg border border-blue-200">
                      <div className="flex items-start gap-2">
                        <Clock className="w-4 h-4 text-blue-600 flex-shrink-0 mt-0.5" />
                        <div>
                          <p className="text-xs font-medium text-blue-900 mb-1">
                            Time Clock Integration
                          </p>
                          <p className="text-xs text-blue-700">
                            Hourly rate will be calculated based on time clock entries. Make sure time clock is enabled for this team member.
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                </SectionCard>
              </TabsContent>

              {/* Salary Tab */}
              <TabsContent value="salary" className="space-y-4 sm:space-y-6">
                <SectionCard>
                  <div className="space-y-4">
                    <div>
                      <Label htmlFor="salary" className="text-sm sm:text-base font-medium">
                        Monthly Salary (R)
                      </Label>
                      <div className="relative mt-1.5">
                        <Input
                          id="salary"
                          type="number"
                          min={0}
                          step={0.01}
                          value={settings.salary}
                          onChange={(e) =>
                            setSettings({
                              ...settings,
                              salary: parseFloat(e.target.value) || 0,
                            })
                          }
                          className="min-h-[44px] touch-manipulation pl-8"
                          placeholder="0.00"
                        />
                        <DollarSign className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                      </div>
                      <p className="text-xs text-gray-500 mt-1.5">
                        Fixed monthly salary for salaried staff members
                      </p>
                    </div>

                    <div className="p-3 sm:p-4 bg-blue-50 rounded-lg border border-blue-200">
                      <div className="flex items-start gap-2">
                        <Calendar className="w-4 h-4 text-blue-600 flex-shrink-0 mt-0.5" />
                        <div>
                          <p className="text-xs font-medium text-blue-900 mb-1">
                            Salary Payment
                          </p>
                          <p className="text-xs text-blue-700">
                            Salary is paid monthly regardless of hours worked or services performed.
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                </SectionCard>
              </TabsContent>

              {/* Tips Tab */}
              <TabsContent value="tips" className="space-y-4 sm:space-y-6">
                <SectionCard>
                  <div className="space-y-4">
                    <div className="flex items-start gap-4 p-4 bg-gray-50 rounded-lg">
                      <Switch
                        checked={settings.tips_enabled}
                        onCheckedChange={(checked) =>
                          setSettings({ ...settings, tips_enabled: checked })
                        }
                        className="mt-1"
                      />
                      <div className="flex-1">
                        <Label className="text-sm sm:text-base font-medium cursor-pointer flex items-center gap-2">
                          <TrendingUp className="w-4 h-4" />
                          Enable Tips
                        </Label>
                        <p className="text-xs text-gray-500 mt-1">
                          Allow this team member to receive tips from clients during checkout
                        </p>
                      </div>
                    </div>

                    {settings.tips_enabled && (
                      <div className="ml-0 sm:ml-12 p-4 bg-blue-50 rounded-lg border border-blue-200">
                        <p className="text-xs font-medium text-blue-900 mb-2">
                          Tips Information
                        </p>
                        <ul className="text-xs text-blue-700 space-y-1 list-disc list-inside">
                          <li>Tips can be added during checkout</li>
                          <li>Tips can be split between multiple staff members</li>
                          <li>Tips are tracked separately from commissions and wages</li>
                          <li>Tips can be paid out in cash or included in payroll</li>
                        </ul>
                      </div>
                    )}
                  </div>
                </SectionCard>
              </TabsContent>
            </Tabs>
          )}
        </div>
      )}
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Separator } from "@/components/ui/separator";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { providerApi } from "@/lib/provider-portal/api";
import { fetcher } from "@/lib/http/fetcher";
import type { TeamMember } from "@/lib/provider-portal/types";
import { toast } from "sonner";
import { Bell, Mail, Phone, Monitor, Clock, Calendar, User, AlertCircle } from "lucide-react";
import { Skeleton } from "@/components/ui/skeleton";

interface NotificationSettings {
  email_enabled: boolean;
  sms_enabled: boolean;
  desktop_enabled: boolean;
  appointment_reminders: boolean;
  appointment_cancellations: boolean;
  appointment_reschedules: boolean;
  new_bookings: boolean;
  daily_schedule: boolean;
  weekly_schedule: boolean;
  reminder_time: string; // e.g., "24h", "2h", "30m"
}

export default function NotificationsSettings() {
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [selectedMember, setSelectedMember] = useState<string | null>(null);
  const [settings, setSettings] = useState<NotificationSettings>({
    email_enabled: true,
    sms_enabled: true,
    desktop_enabled: false,
    appointment_reminders: true,
    appointment_cancellations: true,
    appointment_reschedules: true,
    new_bookings: true,
    daily_schedule: true,
    weekly_schedule: false,
    reminder_time: "24h",
  });
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    loadTeamMembers();
  }, []);

  useEffect(() => {
    if (selectedMember) {
      loadNotificationSettings(selectedMember);
    }
  }, [selectedMember]);

  const loadTeamMembers = async () => {
    try {
      setIsLoading(true);
      const members = await providerApi.listTeamMembers();
      setTeamMembers(members.filter((m) => m.is_active));
      if (members.length > 0 && !selectedMember) {
        setSelectedMember(members[0].id);
      }
    } catch (error) {
      console.error("Failed to load team members:", error);
      toast.error("Failed to load team members");
    } finally {
      setIsLoading(false);
    }
  };

  const loadNotificationSettings = async (memberId: string) => {
    try {
      const response = await fetcher.get<{
        data: {
          emailEnabled: boolean;
          smsEnabled: boolean;
          desktopEnabled: boolean;
          appointmentReminders: boolean;
          appointmentCancellations: boolean;
          appointmentReschedules: boolean;
          newBookings: boolean;
          dailySchedule: boolean;
          weeklySchedule: boolean;
          reminderTime: string;
        };
      }>(`/api/provider/staff/${memberId}/notifications`);
      setSettings({
        email_enabled: response.data.emailEnabled,
        sms_enabled: response.data.smsEnabled,
        desktop_enabled: response.data.desktopEnabled,
        appointment_reminders: response.data.appointmentReminders,
        appointment_cancellations: response.data.appointmentCancellations,
        appointment_reschedules: response.data.appointmentReschedules,
        new_bookings: response.data.newBookings,
        daily_schedule: response.data.dailySchedule,
        weekly_schedule: response.data.weeklySchedule,
        reminder_time: response.data.reminderTime,
      });
    } catch (error) {
      console.error("Failed to load notification settings:", error);
      // Use default values on error
      setSettings({
        email_enabled: true,
        sms_enabled: true,
        desktop_enabled: false,
        appointment_reminders: true,
        appointment_cancellations: true,
        appointment_reschedules: true,
        new_bookings: true,
        daily_schedule: true,
        weekly_schedule: false,
        reminder_time: "24h",
      });
    }
  };

  const handleSave = async () => {
    if (!selectedMember) return;

    setIsSaving(true);
    try {
      await fetcher.patch(`/api/provider/staff/${selectedMember}/notifications`, {
        email_enabled: settings.email_enabled,
        sms_enabled: settings.sms_enabled,
        desktop_enabled: settings.desktop_enabled,
        appointment_reminders: settings.appointment_reminders,
        appointment_cancellations: settings.appointment_cancellations,
        appointment_reschedules: settings.appointment_reschedules,
        new_bookings: settings.new_bookings,
        daily_schedule: settings.daily_schedule,
        weekly_schedule: settings.weekly_schedule,
        reminder_time: settings.reminder_time,
      });
      toast.success("Notification settings saved successfully");
    } catch (error: any) {
      console.error("Failed to save notification settings:", error);
      toast.error(error.message || "Failed to save notification settings");
    } finally {
      setIsSaving(false);
    }
  };

  const selectedMemberData = teamMembers.find((m) => m.id === selectedMember);

  return (
    <SettingsDetailLayout
      title="Staff Notifications"
      subtitle="Configure how team members receive notifications"
      onSave={handleSave}
      saveLabel={isSaving ? "Saving..." : "Save Settings"}
      breadcrumbs={[
        { label: "Home", href: "/" },
        { label: "Provider", href: "/provider" },
        { label: "Settings", href: "/provider/settings" },
        { label: "Team", href: "/provider/settings/team/roles" },
        { label: "Staff Notifications" },
      ]}
    >
      {isLoading ? (
        <SectionCard>
          <Skeleton className="h-64 w-full" />
        </SectionCard>
      ) : teamMembers.length === 0 ? (
        <SectionCard className="p-8 sm:p-12 text-center">
          <p className="text-gray-600 mb-4">No active team members found</p>
          <Button onClick={() => window.location.href = "/provider/team/members"}>
