                </li>
                <li className="flex items-start gap-2">
                  <CheckCircle2 className="w-4 h-4 text-green-600 mt-0.5 flex-shrink-0" />
                  <span>
                    You'll be added as the owner in the team management system
                  </span>
                </li>
                <li className="flex items-start gap-2">
                  <CheckCircle2 className="w-4 h-4 text-green-600 mt-0.5 flex-shrink-0" />
                  <span>
                    All your existing bookings, reviews, and data will be
                    preserved
                  </span>
                </li>
                <li className="flex items-start gap-2">
                  <CheckCircle2 className="w-4 h-4 text-green-600 mt-0.5 flex-shrink-0" />
                  <span>
                    Your primary location will be marked automatically
                  </span>
                </li>
                <li className="flex items-start gap-2">
                  <CheckCircle2 className="w-4 h-4 text-green-600 mt-0.5 flex-shrink-0" />
                  <span>
                    You can immediately start adding team members and locations
                  </span>
                </li>
              </ul>
            </div>

            <div className="pt-4 border-t">
              <Button
                onClick={() => setShowConfirmDialog(true)}
                className="w-full sm:w-auto bg-[#FF0077] hover:bg-[#D60565] text-white"
                size="lg"
              >
                Upgrade to Salon
              </Button>
            </div>
          </div>
        </SectionCard>
      </div>

      <Dialog open={showConfirmDialog} onOpenChange={setShowConfirmDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Confirm Upgrade to Salon</DialogTitle>
            <DialogDescription>
              Are you sure you want to upgrade your account to a salon? This
              will:
              <ul className="list-disc list-inside mt-2 space-y-1 text-sm">
                <li>Change your business type to salon</li>
                <li>Enable team management features</li>
                <li>Allow multiple locations</li>
                <li>Add you as the owner in the team system</li>
              </ul>
              <p className="mt-3 font-medium">
                This action cannot be undone, but all your existing data will be
                preserved.
              </p>
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowConfirmDialog(false)}
              disabled={isUpgrading}
            >
              Cancel
            </Button>
            <Button
              onClick={handleUpgrade}
              disabled={isUpgrading}
              className="bg-[#FF0077] hover:bg-[#D60565] text-white"
            >
              {isUpgrading ? "Upgrading..." : "Confirm Upgrade"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect, useRef, useCallback } from "react";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { useModuleConfig, useFeatureFlag } from "@/providers/ConfigBundleProvider";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import { ShieldCheck, ShieldAlert, Loader2 } from "lucide-react";
import LoadingTimeout from "@/components/ui/loading-timeout";

type VerificationStatus = "pending" | "in_progress" | "approved" | "rejected" | "reset";

export default function VerificationPage() {
  const sumsubConfig = useModuleConfig("sumsub") as { enabled?: boolean } | undefined;
  const verificationEnabled = useFeatureFlag("verification.sumsub.enabled");
  const [status, setStatus] = useState<VerificationStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [launching, setLaunching] = useState(false);
  const [sdkReady, setSdkReady] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const enabled = Boolean(sumsubConfig?.enabled) || verificationEnabled;

  const loadStatus = useCallback(async () => {
    try {
      const res = await fetcher.get<{ data: { status: VerificationStatus } }>("/api/provider/verification/status");
      setStatus(res.data?.status ?? "pending");
    } catch {
      setStatus("pending");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadStatus();
  }, [loadStatus]);

  const getNewToken = useCallback(async () => {
    const res = await fetcher.get<{ data: { access_token: string } }>("/api/provider/verification/sumsub/token");
    return res.data?.access_token ?? "";
  }, []);

  const launchVerification = async () => {
    if (!enabled || !containerRef.current) return;
    setLaunching(true);
    try {
      const tokenRes = await fetcher.get<{ data: { access_token: string } }>("/api/provider/verification/sumsub/token");
      const token = tokenRes.data?.access_token;
      if (!token) {
        toast.error("Could not start verification");
        setLaunching(false);
        return;
      }
      setSdkReady(true);
      setStatus("in_progress");

      const script = document.createElement("script");
      script.src = "https://static.sumsub.com/idensic/static/sns-websdk-builder.js";
      script.async = true;
      script.onload = () => {
        const w = window as any as { snsWebSdk?: { init: (token: string, refresh: () => Promise<string>) => void } };
        if (w.snsWebSdk?.init && containerRef.current) {
          try {
            w.snsWebSdk.init(token, getNewToken);
          } catch (e) {
            console.error("Sumsub init error:", e);
            toast.error("Verification could not be loaded. Try again or contact support.");
          }
        }
        setLaunching(false);
      };
      script.onerror = () => {
        toast.error("Verification service failed to load. Try again later.");
        setLaunching(false);
      };
      document.body.appendChild(script);
    } catch {
      toast.error("Failed to start verification");
      setLaunching(false);
    }
  };

  if (loading) {
    return (
      <SettingsDetailLayout title="Identity verification" subtitle="Verify your identity with Sumsub (KYC).">
        <LoadingTimeout loadingMessage="Loading..." />
      </SettingsDetailLayout>
    );
  }

  return (
    <SettingsDetailLayout title="Identity verification" subtitle="Verify your identity for payouts and compliance.">
      {!enabled && (
        <Alert className="mb-6">
          <AlertDescription>Verification is not enabled for your region. Contact support if you need to verify.</AlertDescription>
        </Alert>
      )}

      <SectionCard title="Verification status">
        <div className="flex flex-col gap-4">
          <div className="flex items-center gap-3">
            {status === "approved" && (
              <>
                <ShieldCheck className="h-8 w-8 text-green-600" />
                <div>
                  <p className="font-medium">Verified</p>
                  <p className="text-sm text-muted-foreground">Your identity has been verified.</p>
                </div>
                <Badge variant="default" className="bg-green-600">Approved</Badge>
              </>
            )}
            {(status === "pending" || status === "in_progress" || status === null) && (
              <>
                <ShieldAlert className="h-8 w-8 text-amber-600" />
                <div>
                  <p className="font-medium">{status === "in_progress" ? "Verification in progress" : "Not verified"}</p>
                  <p className="text-sm text-muted-foreground">
                    {status === "in_progress" ? "Complete the steps in the form below." : "Verify your identity to enable payouts and compliance."}
                  </p>
                </div>
                {status === "in_progress" && <Badge variant="secondary">In progress</Badge>}
              </>
            )}
            {status === "rejected" && (
              <>
                <ShieldAlert className="h-8 w-8 text-red-600" />
                <div>
                  <p className="font-medium">Verification declined</p>
                  <p className="text-sm text-muted-foreground">Contact support to resolve.</p>
                </div>
                <Badge variant="destructive">Rejected</Badge>
              </>
            )}
          </div>

          {enabled && status !== "approved" && (
            <>
              {!sdkReady ? (
                <Button onClick={launchVerification} disabled={launching}>
                  {launching ? <><Loader2 className="h-4 w-4 animate-spin mr-2" /> StartingΓÇª</> : "Start verification"}
                </Button>
              ) : (
                <div ref={containerRef} id="sumsub-websdk-container" className="min-h-[400px] w-full" />
              )}
            </>
          )}
        </div>
      </SectionCard>
    </SettingsDetailLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Plus, Trash2, Edit2, CreditCard } from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import { PageHeader } from "@/components/provider/PageHeader";

interface YocoTerminal {
  id: string;
  device_id: string;
  device_name: string;
  location_name: string;
  active: boolean;
  created_at: string;
}

export default function YocoTerminalsPage() {
  const [terminals, setTerminals] = useState<YocoTerminal[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingTerminal, setEditingTerminal] = useState<YocoTerminal | null>(null);
  const [formData, setFormData] = useState({
    device_id: "",
    device_name: "",
    api_key: "",
    secret_key: "",
    location_name: "",
  });

  useEffect(() => {
    loadTerminals();
  }, []);

  const loadTerminals = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data?: YocoTerminal[] }>("/api/provider/yoco/terminals");
      setTerminals(response?.data ?? []);
    } catch {
      toast.error("Failed to load terminals");
    } finally {
      setIsLoading(false);
    }
  };

  const handleOpenDialog = (terminal?: YocoTerminal) => {
    if (terminal) {
      setEditingTerminal(terminal);
      setFormData({
        device_id: terminal.device_id,
        device_name: terminal.device_name,
        api_key: "",
        secret_key: "",
        location_name: terminal.location_name || "",
      });
    } else {
      setEditingTerminal(null);
      setFormData({
        device_id: "",
        device_name: "",
        api_key: "",
        secret_key: "",
        location_name: "",
      });
    }
    setIsDialogOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (editingTerminal) {
        await fetcher.put(`/api/provider/yoco/terminals/${editingTerminal.id}`, formData);
        toast.success("Terminal updated successfully");
      } else {
        await fetcher.post("/api/provider/yoco/terminals", formData);
        toast.success("Terminal registered successfully");
      }
      setIsDialogOpen(false);
      loadTerminals();
    } catch (error: any) {
      toast.error(error.message || "Failed to save terminal");
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this terminal?")) {
      return;
    }
    try {
      await fetcher.delete(`/api/provider/yoco/terminals/${id}`);
      toast.success("Terminal deleted successfully");
      loadTerminals();
    } catch (error: any) {
      toast.error(error.message || "Failed to delete terminal");
    }
  };

  return (
    <RoleGuard allowedRoles={["provider_owner", "provider_staff"]}>
      <div className="container mx-auto px-4 py-8 max-w-6xl">
        <PageHeader
          title="Yoco Terminals"
          subtitle="Manage your Yoco payment terminals for accepting in-person payments"
          breadcrumbs={[
            { label: "Home", href: "/" },
            { label: "Provider", href: "/provider" },
            { label: "Settings", href: "/provider/settings" },
            { label: "Yoco Terminals" }
          ]}
        />

        <div className="mb-4">
          <Button
            onClick={() => handleOpenDialog()}
            className="touch-target"
          >
            <Plus className="w-4 h-4 mr-2" />
            Register New Terminal
          </Button>
        </div>

        {isLoading ? (
          <div className="text-center py-8">Loading terminals...</div>
        ) : terminals.length === 0 ? (
          <div className="text-center py-8 text-gray-500">
            No terminals registered. Click "Register New Terminal" to add one.
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {terminals.map((terminal) => (
              <div
                key={terminal.id}
                className="border rounded-lg p-4 bg-white hover:shadow-md transition-shadow"
              >
                <div className="flex items-start justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <CreditCard className="w-5 h-5 text-gray-400" />
                    <div>
                      <h3 className="font-semibold text-sm sm:text-base">{terminal.device_name}</h3>
                      <p className="text-xs text-gray-500">{terminal.location_name}</p>
                    </div>
                  </div>
                  <div className="flex gap-1">
                    <button
                      onClick={() => handleOpenDialog(terminal)}
                      className="p-1 hover:bg-gray-100 rounded touch-target"
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => handleDelete(terminal.id)}
                      className="p-1 hover:bg-red-50 rounded touch-target"
                    >
                      <Trash2 className="w-4 h-4 text-red-600" />
                    </button>
                  </div>
                </div>
                <div className="space-y-1 text-xs sm:text-sm">
                  <p className="text-gray-600">
                    <span className="font-medium">Device ID:</span> {terminal.device_id}
                  </p>
                  <p className="text-gray-600">
                    <span className="font-medium">Status:</span>{" "}
                    <span className={terminal.active ? "text-green-600" : "text-red-600"}>
                      {terminal.active ? "Active" : "Inactive"}
                    </span>
                  </p>
                </div>
              </div>
            ))}
          </div>
        )}

        <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
          <DialogContent className="max-w-md">
            <DialogHeader>
              <DialogTitle>
                {editingTerminal ? "Edit Terminal" : "Register New Terminal"}
              </DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label htmlFor="device_id">Device ID *</Label>
                <Input
                  id="device_id"
                  value={formData.device_id}
                  onChange={(e) => setFormData({ ...formData, device_id: e.target.value })}
                  required
                  disabled={!!editingTerminal}
                  className="text-sm sm:text-base"
                />
              </div>
              <div>
                <Label htmlFor="device_name">Device Name *</Label>
                <Input
                  id="device_name"
                  value={formData.device_name}
                  onChange={(e) => setFormData({ ...formData, device_name: e.target.value })}
                  required
                  className="text-sm sm:text-base"
                />
              </div>
              <div>
                <Label htmlFor="location_name">Location Name</Label>
                <Input
                  id="location_name"
                  value={formData.location_name}
                  onChange={(e) => setFormData({ ...formData, location_name: e.target.value })}
                  placeholder="Main Location"
                  className="text-sm sm:text-base"
                />
              </div>
              {!editingTerminal && (
                <>
                  <div>
                    <Label htmlFor="api_key">API Key *</Label>
                    <Input
                      id="api_key"
                      type="password"
                      value={formData.api_key}
                      onChange={(e) => setFormData({ ...formData, api_key: e.target.value })}
                      required
                      className="text-sm sm:text-base font-mono"
                    />
                  </div>
                  <div>
                    <Label htmlFor="secret_key">Secret Key *</Label>
                    <Input
                      id="secret_key"
                      type="password"
                      value={formData.secret_key}
                      onChange={(e) => setFormData({ ...formData, secret_key: e.target.value })}
                      required
                      className="text-sm sm:text-base font-mono"
                    />
                  </div>
                </>
              )}
              <DialogFooter>
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setIsDialogOpen(false)}
                  className="touch-target"
                >
                  Cancel
                </Button>
                <Button type="submit" className="touch-target">
                  {editingTerminal ? "Update" : "Register"}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import RoleGuard from "@/components/auth/RoleGuard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Plus, Edit, Trash2, Search, User, Mail, Phone, Home, Filter } from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";
import { useProviderPortal } from "@/providers/provider-portal/ProviderPortalProvider";
import { Checkbox } from "@/components/ui/checkbox";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";

interface StaffLocation {
  location_id: string;
  location_name?: string;
  location_city?: string;
  is_primary: boolean;
}

interface StaffMember {
  id: string;
  name: string;
  email: string;
  phone?: string;
  role: string;
  is_active: boolean;
  avatar_url?: string;
  locations?: StaffLocation[];
  primary_location_id?: string | null;
  mobileReady?: boolean;
}

export default function ProviderStaff() {
  const { selectedLocationId, salons: _salons } = useProviderPortal();
  const [staff, setStaff] = useState<StaffMember[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingStaff, setEditingStaff] = useState<StaffMember | null>(null);
  const [mobileFilter, setMobileFilter] = useState<"all" | "mobile" | "not-mobile">("all");

  useEffect(() => {
    loadStaff();
  }, [selectedLocationId]);

  // If location is selected, filter staff to only those assigned to that location
  // If no location selected, show all staff

  const loadStaff = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const url = selectedLocationId
        ? `/api/provider/staff?location_id=${selectedLocationId}`
        : "/api/provider/staff";

      const response = await fetcher.get<{ data: StaffMember[] }>(url);
      setStaff(response.data);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load staff";
      setError(errorMessage);
      console.error("Error loading staff:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to remove this staff member?")) return;

    try {
      await fetcher.delete(`/api/provider/staff/${id}`);
      toast.success("Staff member removed successfully");
      loadStaff();
    } catch {
      toast.error("Failed to remove staff member");
    }
  };

  const filteredStaff = staff.filter((member) => {
    const matchesSearch =
      (member?.name ?? "").toLowerCase().includes((searchQuery ?? "").toLowerCase()) ||
      (member?.email ?? "").toLowerCase().includes((searchQuery ?? "").toLowerCase());

    if (!matchesSearch) return false;

    // Apply mobile filter
    if (mobileFilter === "mobile") {
      return member.mobileReady === true;
    } else if (mobileFilter === "not-mobile") {
      return member.mobileReady !== true;
    }

    return true;
  });

  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8">
        <LoadingTimeout loadingMessage="Loading staff..." />
      </div>
    );
  }

  return (
    <RoleGuard allowedRoles={["provider_owner"]}>
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-6">
          <div>
            <h1 className="text-3xl font-semibold mb-2">Staff Management</h1>
            <p className="text-gray-600">Manage your team members</p>
          </div>
          <Button onClick={() => setShowAddModal(true)}>
            <Plus className="w-4 h-4 mr-2" />
            Add Staff Member
          </Button>
        </div>

        {/* Search and Filter */}
        <div className="mb-6 space-y-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
            <Input
              placeholder="Search staff by name or email..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10"
            />
          </div>
          <div className="flex items-center gap-2">
            <Filter className="w-4 h-4 text-gray-500" />
            <select
              value={mobileFilter}
              onChange={(e) => setMobileFilter(e.target.value as "all" | "mobile" | "not-mobile")}
              className="px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#FF0077]"
            >
              <option value="all">All Staff</option>
              <option value="mobile">Mobile Ready Only</option>
              <option value="not-mobile">Not Mobile Ready</option>
            </select>
          </div>
        </div>

        {/* Staff List */}
        {error ? (
          <EmptyState
            title="Failed to load staff"
            description={error}
            action={{
              label: "Retry",
              onClick: loadStaff,
            }}
          />
        ) : filteredStaff.length === 0 ? (
          <EmptyState
            title="No staff members yet"
            description="Add your first team member to get started"
            action={{
              label: "Add Staff Member",
              onClick: () => setShowAddModal(true),
            }}
          />
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredStaff.map((member) => (
              <StaffCard
                key={member.id}
                member={member}
                onEdit={() => setEditingStaff(member)}
                onDelete={() => handleDelete(member.id)}
              />
            ))}
          </div>
        )}

        {/* Add/Edit Modal */}
        {(showAddModal || editingStaff) && (
          <StaffModal
            staff={editingStaff}
            onClose={() => {
              setShowAddModal(false);
              setEditingStaff(null);
            }}
            onSave={() => {
              setShowAddModal(false);
              setEditingStaff(null);
              loadStaff();
            }}
          />
        )}
      </div>
    </RoleGuard>
  );
}

