function StaffModal({
  staff,
  onClose,
  onSave,
}: {
  staff: StaffMember | null;
  onClose: () => void;
  onSave: () => void;
}) {
  const { salons } = useProviderPortal();
  const [formData, setFormData] = useState({
    name: staff?.name || "",
    email: staff?.email || "",
    phone: staff?.phone || "",
    role: staff?.role || "staff",
    is_active: staff?.is_active ?? true,
    mobileReady: staff?.mobileReady ?? false,
  });
  const [selectedLocations, setSelectedLocations] = useState<string[]>(
    staff?.locations?.map(l => l.location_id) || []
  );
  const [primaryLocationId, setPrimaryLocationId] = useState<string | null>(
    staff?.primary_location_id || null
  );
  const [isSaving, setIsSaving] = useState(false);
  const [isLoadingLocations, setIsLoadingLocations] = useState(false);

  // Update formData when staff changes (for editing)
  useEffect(() => {
    if (staff) {
      setFormData({
        name: staff.name || "",
        email: staff.email || "",
        phone: staff.phone || "",
        role: staff.role || "staff",
        is_active: staff.is_active ?? true,
        mobileReady: staff.mobileReady ?? false,
      });
      setSelectedLocations(staff.locations?.map(l => l.location_id) || []);
      setPrimaryLocationId(staff.primary_location_id || null);
    } else {
      // Reset form for new staff
      setFormData({
        name: "",
        email: "",
        phone: "",
        role: "staff",
        is_active: true,
        mobileReady: false,
      });
      setSelectedLocations([]);
      setPrimaryLocationId(null);
    }
  }, [staff]);

  // Load location assignments when editing
  useEffect(() => {
    if (staff?.id) {
      loadStaffLocations();
    }
  }, [staff?.id]);

  const loadStaffLocations = async () => {
    if (!staff?.id) return;
    try {
      setIsLoadingLocations(true);
      const response = await fetcher.get<{ data: Array<{ location_id: string; is_primary: boolean }> }>(
        `/api/provider/staff/${staff.id}/locations`
      );
      const assignments = response.data || [];
      setSelectedLocations(assignments.map(a => a.location_id));
      const primary = assignments.find(a => a.is_primary);
      setPrimaryLocationId(primary?.location_id || null);
    } catch (error) {
      console.error("Failed to load staff locations:", error);
    } finally {
      setIsLoadingLocations(false);
    }
  };

  const handleLocationToggle = (locationId: string) => {
    setSelectedLocations(prev => {
      if (prev.includes(locationId)) {
        // If removing primary location, clear it
        if (primaryLocationId === locationId) {
          setPrimaryLocationId(null);
        }
        return prev.filter(id => id !== locationId);
      } else {
        return [...prev, locationId];
      }
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setIsSaving(true);

      // Save staff member first
      if (staff) {
        await fetcher.patch(`/api/provider/staff/${staff.id}`, formData);
      } else {
        const response = await fetcher.post<{ data: { id: string } }>("/api/provider/staff", formData);
        // If new staff, save locations after creation
        if (response.data?.id && selectedLocations.length > 0) {
          await fetcher.put(`/api/provider/staff/${response.data.id}/locations`, {
            location_ids: selectedLocations,
            primary_location_id: primaryLocationId || undefined,
          });
        }
      }

      // Update location assignments for existing staff
      if (staff?.id && selectedLocations.length > 0) {
        await fetcher.put(`/api/provider/staff/${staff.id}/locations`, {
          location_ids: selectedLocations,
          primary_location_id: primaryLocationId || undefined,
        });
      } else if (staff?.id && selectedLocations.length === 0) {
        // Remove all location assignments
        await fetcher.delete(`/api/provider/staff/${staff.id}/locations`);
      }

      toast.success(staff ? "Staff member updated" : "Staff member added");
      onSave();
    } catch {
      toast.error("Failed to save staff member");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
        <h2 className="text-2xl font-semibold mb-4">
          {staff ? "Edit Staff Member" : "Add Staff Member"}
        </h2>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="name">Name *</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              required
            />
          </div>

          <div>
            <Label htmlFor="email">Email *</Label>
            <Input
              id="email"
              type="email"
              value={formData.email}
              onChange={(e) =>
                setFormData({ ...formData, email: e.target.value })
              }
              required
            />
          </div>

          <div>
            <Label htmlFor="phone">Phone</Label>
            <Input
              id="phone"
              type="tel"
              value={formData.phone}
              onChange={(e) =>
                setFormData({ ...formData, phone: e.target.value })
              }
            />
          </div>

          <div className="flex items-center space-x-2">
            <Checkbox
              id="mobileReady"
              checked={formData.mobileReady}
              onCheckedChange={(checked) =>
                setFormData({ ...formData, mobileReady: checked === true })
              }
            />
            <Label htmlFor="mobileReady" className="cursor-pointer">
              Mobile Ready (can perform at-home services)
            </Label>
          </div>

          <div>
            <Label htmlFor="role">Role *</Label>
            <select
              id="role"
              value={formData.role}
              onChange={(e) =>
                setFormData({ ...formData, role: e.target.value })
              }
              className="w-full p-2 border rounded-md"
              required
            >
              <option value="staff">Staff</option>
              <option value="manager">Manager</option>
              <option value="admin">Admin</option>
            </select>
          </div>

          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="is_active"
              checked={formData.is_active}
              onChange={(e) =>
                setFormData({ ...formData, is_active: e.target.checked })
              }
            />
            <Label htmlFor="is_active">Active (can receive bookings)</Label>
          </div>

          {/* Location Assignments */}
          {salons && salons.length > 0 && (
            <div className="space-y-3 pt-4 border-t">
              <Label>Location Assignments</Label>
              <p className="text-sm text-gray-600">
                Select which locations this staff member can work at. You can assign them to multiple locations.
              </p>

              <div className="space-y-2 max-h-48 overflow-y-auto">
                {salons.map((location) => (
                  <div key={location.id} className="flex items-start gap-3">
                    <Checkbox
                      id={`location-${location.id}`}
                      checked={selectedLocations.includes(location.id)}
                      onCheckedChange={() => handleLocationToggle(location.id)}
                      disabled={isLoadingLocations}
                    />
                    <div className="flex-1">
                      <Label
                        htmlFor={`location-${location.id}`}
                        className="font-medium cursor-pointer"
                      >
                        {location.name}
                      </Label>
                      {location.city && (
                        <p className="text-xs text-gray-500">{location.city}</p>
                      )}
                    </div>
                  </div>
                ))}
              </div>

              {/* Primary Location Selection */}
              {selectedLocations.length > 0 && (
                <div className="pt-3 border-t">
                  <Label className="mb-2 block">Primary Location</Label>
                  <p className="text-sm text-gray-600 mb-2">
                    Select the primary location for this staff member (optional).
                  </p>
                  <RadioGroup
                    value={primaryLocationId || ""}
                    onValueChange={(value) => setPrimaryLocationId(value || null)}
                  >
                    <div className="space-y-2">
                      {selectedLocations.map((locId) => {
                        const location = salons.find(l => l.id === locId);
                        if (!location) return null;
                        return (
                          <div key={locId} className="flex items-center gap-2">
                            <RadioGroupItem value={locId} id={`primary-${locId}`} />
                            <Label htmlFor={`primary-${locId}`} className="cursor-pointer">
                              {location.name}
                              {location.city && ` (${location.city})`}
                            </Label>
                          </div>
                        );
                      })}
                      <div className="flex items-center gap-2">
                        <RadioGroupItem value="" id="primary-none" />
                        <Label htmlFor="primary-none" className="cursor-pointer text-gray-500">
                          No primary location
                        </Label>
                      </div>
                    </div>
                  </RadioGroup>
                </div>
              )}
            </div>
          )}

          <div className="flex gap-2 pt-4">
            <Button type="button" variant="outline" onClick={onClose} className="flex-1">
              Cancel
            </Button>
            <Button type="submit" disabled={isSaving} className="flex-1">
              {isSaving ? "Saving..." : staff ? "Update" : "Add"}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Check, CreditCard, Calendar } from "lucide-react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import LoadingTimeout from "@/components/ui/loading-timeout";
import EmptyState from "@/components/ui/empty-state";
import { toast } from "sonner";
import { SettingsDetailLayout } from "@/components/provider/SettingsDetailLayout";
import { PageHeader } from "@/components/provider/PageHeader";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";

interface SubscriptionPlan {
  id: string;
  plan_id: string;
  name: string;
  price: number;
  currency: string;
  billing_period: "monthly" | "yearly";
  features: string[];
  is_popular?: boolean;
}

interface ProviderSubscription {
  id: string;
  plan_id: string;
  status: "active" | "expired" | "cancelled" | "past_due" | "trial";
  started_at?: string;
  expires_at?: string;
  billing_period?: "monthly" | "yearly";
  auto_renew?: boolean;
  plan?: any;
}

export default function SubscriptionPage() {
  const [subscription, setSubscription] = useState<ProviderSubscription | null>(null);
  const [plans, setPlans] = useState<SubscriptionPlan[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showUpgradeDialog, setShowUpgradeDialog] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadData();

    // Check if returning from payment success
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get("payment_success") === "true") {
      toast.success("Payment successful! Your subscription is being activated...");
      // Reload after a short delay to allow webhook to process
      setTimeout(() => {
        loadData();
      }, 2000);
      // Clean up URL
      window.history.replaceState({}, "", window.location.pathname);
    }
  }, []);

  const loadData = async () => {
    try {
      setIsLoading(true);
      setError(null);

      const [subscriptionRes, plansRes] = await Promise.all([
        fetcher.get<{ data: ProviderSubscription }>("/api/provider/subscription"),
        fetcher.get<{ data: SubscriptionPlan[] }>("/api/public/subscription-plans"),
      ]);

      setSubscription(subscriptionRes.data);
      setPlans(plansRes.data || []);
    } catch (err) {
      const errorMessage =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
          ? err.message
          : "Failed to load subscription data";
      setError(errorMessage);
      console.error("Error loading subscription:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpgrade = async (planId: string) => {
    try {
      const plan = plans.find((p) => p.id === planId);
      if (!plan) throw new Error("Plan not found");

      // Try to upgrade directly (may work if authorization exists)
      const res = await fetcher.post<{ 
        data: { 
          payment_url?: string | null;
          requires_payment?: boolean;
          is_free?: boolean;
          subscription_id?: string;
        } 
      }>(
        "/api/provider/subscription/upgrade",
        { plan_id: plan.plan_id, billing_period: plan.billing_period }
      );

      const data = (res as any).data;

      // Free tier - subscription created directly
      if (data.is_free) {
        toast.success("Free subscription activated!");
        setShowUpgradeDialog(false);
        loadData();
        return;
      }

      // If subscription created successfully
      if (data.subscription_id && !data.requires_payment) {
        toast.success("Subscription activated successfully!");
        setShowUpgradeDialog(false);
        loadData();
        return;
      }

      // If payment authorization is required
      if (data.requires_payment || data.payment_url) {
        // Initialize payment to get authorization
        const paymentRes = await fetcher.post<{ 
          data: { 
            payment_url: string | null;
            order_id: string;
          } 
        }>(
          "/api/provider/subscription/initialize-payment",
          { plan_id: plan.plan_id, billing_period: plan.billing_period }
        );

        const paymentUrl = (paymentRes as any).data?.payment_url;
        if (paymentUrl) {
          window.location.href = paymentUrl;
          return;
        }
      }

      // Fallback to direct payment URL if available
      if (data.payment_url) {
        window.location.href = data.payment_url;
        return;
      }

      toast.success("Subscription checkout started");
      setShowUpgradeDialog(false);
    } catch (error) {
      toast.error("Failed to upgrade subscription");
      console.error("Error upgrading subscription:", error);
    }
  };

  const handleCancel = async () => {
    if (!confirm("Are you sure you want to cancel your subscription? You'll lose access at the end of your billing period.")) {
      return;
    }

    try {
      await fetcher.post("/api/provider/subscription/cancel");
      toast.success("Subscription cancelled. You'll retain access until the end of your billing period.");
      loadData();
    } catch (error) {
      toast.error("Failed to cancel subscription");
      console.error("Error cancelling subscription:", error);
    }
  };

  const handleRenew = async () => {
    try {
      const res = await fetcher.post<{ data: { payment_url: string | null } }>(
        "/api/provider/subscription/renew"
      );
      const url = (res as any).data?.payment_url;
      if (url) {
        window.location.href = url;
        return;
      }
      toast.success("Subscription renewal started");
    } catch (error) {
      toast.error("Failed to renew subscription");
      console.error("Error renewing subscription:", error);
    }
  };

  if (isLoading) {
    return (
      <SettingsDetailLayout>
        <LoadingTimeout loadingMessage="Loading subscription..." />
      </SettingsDetailLayout>
    );
  }

  if (error && !subscription) {
    return (
      <SettingsDetailLayout>
        <EmptyState
          title="Failed to load subscription"
          description={error}
          action={{
            label: "Retry",
            onClick: loadData,
          }}
        />
      </SettingsDetailLayout>
    );
  }

  const currentPlan = subscription?.plan || plans.find((p) => p.plan_id === subscription?.plan_id);
  const expiresAt = subscription?.expires_at ? new Date(subscription.expires_at) : null;

  return (
    <SettingsDetailLayout>
      <PageHeader
        title="Subscription Management"
        subtitle="Manage your Beautonomi subscription plan"
      />

      {subscription ? (
        <div className="space-y-6">
          {/* Current Subscription Card */}
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <div>
                  <CardTitle className="flex items-center gap-2">
                    Current Subscription
                    {subscription.status === "active" && (
                      <Badge variant="secondary" className="bg-green-100 text-green-800">
                        Active
                      </Badge>
                    )}
                    {subscription.status === "expired" && (
                      <Badge variant="secondary" className="bg-gray-100 text-gray-800">
                        Expired
                      </Badge>
                    )}
                    {subscription.status === "cancelled" && (
                      <Badge variant="secondary" className="bg-yellow-100 text-yellow-800">
                        Cancelled
                      </Badge>
                    )}
                  </CardTitle>
                  <CardDescription>
                    {currentPlan?.name || "No plan selected"}
                  </CardDescription>
                </div>
              </div>
            </CardHeader>
            <CardContent className="space-y-4">
              {subscription.status === "active" && expiresAt && (
                <div className="flex items-center gap-2 text-sm text-gray-600">
                  <Calendar className="w-4 h-4" />
                  <span>
                    Expires on: {expiresAt.toLocaleDateString()}
                  </span>
                </div>
              )}

              {currentPlan && (
                <div>
                  <p className="text-2xl font-bold mb-2">
                    {currentPlan.currency} {currentPlan.price}
                    <span className="text-base font-normal text-gray-600">
                      /{currentPlan.billing_period === "monthly" ? "month" : "year"}
                    </span>
                  </p>
                  <div className="space-y-2">
                    <p className="font-medium">Features included:</p>
                    <ul className="space-y-1">
                      {currentPlan.features.map((feature, index) => (
                        <li key={index} className="flex items-center gap-2 text-sm">
                          <Check className="w-4 h-4 text-green-600" />
                          {feature}
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              )}

              <div className="flex gap-2 pt-4 border-t">
                {subscription.status !== "active" && (
                  <Button onClick={() => setShowUpgradeDialog(true)}>
                    <CreditCard className="w-4 h-4 mr-2" />
                    Choose Plan
                  </Button>
                )}
                {subscription.status === "active" && (
                  <>
                    <Button onClick={handleRenew} variant="outline">
                      Renew
                    </Button>
                    <Button onClick={handleCancel} variant="outline" className="text-red-600">
                      Cancel Subscription
                    </Button>
                  </>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Available Plans */}
          {plans.length > 0 && (
            <div>
              <h3 className="text-xl font-semibold mb-4">Available Plans</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {plans.map((plan) => (
                  <Card
                    key={plan.id}
                    className={
                      plan.is_popular
                        ? "border-2 border-[#FF0077] relative"
                        : subscription?.plan_id === plan.id
                        ? "border-2 border-gray-300"
                        : ""
                    }
                  >
                    {plan.is_popular && (
                      <div className="absolute -top-3 left-1/2 -translate-x-1/2">
                        <Badge className="bg-[#FF0077] text-white">Most Popular</Badge>
                      </div>
                    )}
                    {subscription?.plan_id === plan.id && (
                      <div className="absolute -top-3 left-1/2 -translate-x-1/2">
                        <Badge variant="secondary">Current Plan</Badge>
                      </div>
                    )}
                    <CardHeader>
                      <CardTitle>{plan.name}</CardTitle>
                      <CardDescription>
                        <span className="text-2xl font-bold">
                          {plan.currency} {plan.price}
                        </span>
                        <span className="text-sm text-gray-600">
                          /{plan.billing_period === "monthly" ? "month" : "year"}
                        </span>
                      </CardDescription>
                    </CardHeader>
                    <CardContent>
                      <ul className="space-y-2 mb-4">
                        {plan.features.map((feature, index) => (
                          <li key={index} className="flex items-center gap-2 text-sm">
                            <Check className="w-4 h-4 text-green-600" />
                            {feature}
                          </li>
                        ))}
                      </ul>
                      {subscription?.plan_id !== plan.id && (
                        <Button
                          className="w-full"
                          onClick={() => handleUpgrade(plan.id)}
                          variant={plan.is_popular ? "default" : "outline"}
                        >
                          {subscription?.status === "trial" ? "Upgrade from Trial" : "Switch Plan"}
                        </Button>
                      )}
                    </CardContent>
                  </Card>
                ))}
              </div>
            </div>
          )}
        </div>
      ) : (
        <EmptyState
          title="No subscription yet"
          description="Choose a subscription plan to activate billing"
          action={{
            label: "Choose Plan",
            onClick: () => setShowUpgradeDialog(true),
          }}
        />
      )}

      <UpgradeDialog
        open={showUpgradeDialog}
        onClose={() => setShowUpgradeDialog(false)}
        plans={plans}
        onUpgrade={handleUpgrade}
      />
    </SettingsDetailLayout>
  );
}

function UpgradeDialog({
  open,
  onClose,
  plans,
  onUpgrade,
}: {
  open: boolean;
  onClose: () => void;
  plans: SubscriptionPlan[];
  onUpgrade: (planId: string) => void;
}) {
  const [selectedPlan, setSelectedPlan] = useState<string | null>(null);

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>Upgrade Your Subscription</DialogTitle>
          <DialogDescription>
            Choose a plan to continue using Beautonomi after your free trial
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          {plans.map((plan) => (
            <div
              key={plan.id}
              className={`border rounded-lg p-4 cursor-pointer transition-colors ${
                selectedPlan === plan.id
                  ? "border-[#FF0077] bg-pink-50"
                  : "border-gray-200 hover:border-gray-300"
              }`}
              onClick={() => setSelectedPlan(plan.id)}
            >
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="font-semibold">{plan.name}</h4>
                  <p className="text-sm text-gray-600">
                    {plan.currency} {plan.price}/{plan.billing_period === "monthly" ? "month" : "year"}
                  </p>
                </div>
                <input
                  type="radio"
                  checked={selectedPlan === plan.id}
                  onChange={() => setSelectedPlan(plan.id)}
                />
              </div>
            </div>
          ))}
          <div className="flex justify-end gap-2 pt-4">
            <Button variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button
              onClick={() => {
                if (selectedPlan) {
                  onUpgrade(selectedPlan);
                }
              }}
              disabled={!selectedPlan}
            >
              Upgrade
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { TeamMember } from "@/lib/provider-portal/types";
import { PageHeader } from "@/components/provider/PageHeader";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Skeleton } from "@/components/ui/skeleton";
import { CalendarIcon, Plus, X, Users, Calendar as CalendarIcon2 } from "lucide-react";
import { format } from "date-fns";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";

interface DayOff {
  id: string;
  team_member_id: string;
  team_member_name: string;
  date: string;
  reason?: string;
}

export default function DaysOffPage() {
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [daysOff, setDaysOff] = useState<DayOff[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [selectedMembers, setSelectedMembers] = useState<string[]>([]);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);
  const [reason, setReason] = useState("");

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setIsLoading(true);
      const members = await providerApi.listTeamMembers();
      setTeamMembers(members.filter((m) => m.is_active));

      // Load days off from API for all members
      const { fetcher } = await import("@/lib/http/fetcher");
      const allDaysOff: any[] = [];
      for (const member of members) {
        try {
          const response = await fetcher.get<{ data: any[] }>(`/api/provider/staff/${member.id}/days-off`);
          const memberDaysOff = (response.data || []).map((dayOff: any) => ({
            ...dayOff,
            team_member_id: dayOff.staff_id || member.id,
            team_member_name: member.name,
          }));
          allDaysOff.push(...memberDaysOff);
        } catch (error) {
          console.error(`Failed to load days off for ${member.name}:`, error);
        }
      }
      setDaysOff(allDaysOff);
    } catch (error) {
      console.error("Failed to load data:", error);
      toast.error("Failed to load data");
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddDayOff = () => {
    setSelectedMembers([]);
    setSelectedDate(undefined);
    setReason("");
    setIsDialogOpen(true);
  };

  const handleSaveDayOff = async () => {
    if (!selectedDate || selectedMembers.length === 0) {
      toast.error("Please select at least one team member and a date");
      return;
    }

    try {
      const { fetcher } = await import("@/lib/http/fetcher");
      const dateStr = format(selectedDate, "yyyy-MM-dd");

      // Save days off for all selected members
      for (const memberId of selectedMembers) {
        await fetcher.post(`/api/provider/staff/${memberId}/days-off`, {
          date: dateStr,
          reason: reason,
          type: reason, // Use reason as type for now
        });
      }

      toast.success(`Day off set for ${selectedMembers.length} team member(s)`);
      setIsDialogOpen(false);
      loadData();
    } catch (error: any) {
      console.error("Failed to save day off:", error);
      toast.error(error?.message || "Failed to save day off");
    }
  };

  const handleRemoveDayOff = async (dayOff: DayOff) => {
    if (!confirm("Are you sure you want to remove this day off?")) return;

    try {
      const { fetcher } = await import("@/lib/http/fetcher");
      await fetcher.delete(`/api/provider/staff/${dayOff.team_member_id}/days-off/${dayOff.id}`);
      toast.success("Day off removed");
      loadData();
    } catch (error: any) {
      console.error("Failed to remove day off:", error);
      toast.error(error?.message || "Failed to remove day off");
    }
  };

  const toggleMemberSelection = (memberId: string) => {
    setSelectedMembers((prev) =>
      prev.includes(memberId)
        ? prev.filter((id) => id !== memberId)
        : [...prev, memberId]
    );
  };

  const toggleSelectAll = () => {
    if (selectedMembers.length === teamMembers.length) {
      setSelectedMembers([]);
    } else {
      setSelectedMembers(teamMembers.map((m) => m.id));
    }
  };

  return (
    <div>
      <PageHeader
        title="Days Off"
        subtitle="Manage team member days off and time off requests"
        primaryAction={{
          label: "Set Day Off",
          onClick: handleAddDayOff,
          icon: <Plus className="w-4 h-4 mr-2" />,
        }}
      />

      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 sm:gap-4 mb-4 sm:mb-6">
        <SectionCard className="p-3 sm:p-4">
          <div className="flex items-center gap-2 sm:gap-3">
            <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0">
              <CalendarIcon2 className="w-5 h-5 sm:w-6 sm:h-6 text-blue-600" />
            </div>
            <div className="min-w-0 flex-1">
              <div className="text-xs sm:text-sm text-gray-600">Total Days Off</div>
              <div className="text-base sm:text-lg font-semibold truncate">
                {daysOff.length}
              </div>
            </div>
          </div>
        </SectionCard>
        <SectionCard className="p-3 sm:p-4">
          <div className="flex items-center gap-2 sm:gap-3">
            <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-full bg-purple-100 flex items-center justify-center flex-shrink-0">
              <Users className="w-5 h-5 sm:w-6 sm:h-6 text-purple-600" />
            </div>
            <div className="min-w-0 flex-1">
              <div className="text-xs sm:text-sm text-gray-600">This Month</div>
              <div className="text-base sm:text-lg font-semibold truncate">
                {daysOff.filter((d) => {
                  const date = new Date(d.date);
                  const now = new Date();
                  return date.getMonth() === now.getMonth() && date.getFullYear() === now.getFullYear();
                }).length}
              </div>
            </div>
          </div>
        </SectionCard>
        <SectionCard className="p-3 sm:p-4">
          <div className="flex items-center gap-2 sm:gap-3">
            <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-full bg-[#FF0077]/10 flex items-center justify-center flex-shrink-0">
              <CalendarIcon2 className="w-5 h-5 sm:w-6 sm:h-6 text-[#FF0077]" />
            </div>
            <div className="min-w-0 flex-1">
              <div className="text-xs sm:text-sm text-gray-600">Upcoming</div>
              <div className="text-base sm:text-lg font-semibold truncate">
                {daysOff.filter((d) => new Date(d.date) >= new Date()).length}
              </div>
            </div>
          </div>
        </SectionCard>
      </div>

      {/* Days Off List */}
      {isLoading ? (
        <SectionCard>
          <Skeleton className="h-64 w-full" />
        </SectionCard>
      ) : daysOff.length === 0 ? (
        <SectionCard className="p-8 sm:p-12 text-center">
          <CalendarIcon2 className="w-12 h-12 sm:w-16 sm:h-16 text-gray-300 mx-auto mb-4" />
          <p className="text-gray-600 mb-4">No days off scheduled</p>
          <Button onClick={handleAddDayOff} className="min-h-[44px] touch-manipulation">
            <Plus className="w-4 h-4 mr-2" />
            Set Day Off
          </Button>
        </SectionCard>
      ) : (
        <SectionCard className="p-0 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="px-4 py-3 text-left text-xs sm:text-sm font-medium text-gray-700">Team Member</th>
                  <th className="px-4 py-3 text-left text-xs sm:text-sm font-medium text-gray-700">Date</th>
                  <th className="px-4 py-3 text-left text-xs sm:text-sm font-medium text-gray-700">Reason</th>
                  <th className="px-4 py-3 text-right text-xs sm:text-sm font-medium text-gray-700">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y">
                {daysOff.map((dayOff) => {
                  const member = teamMembers.find((m) => m.id === dayOff.team_member_id);
                  const isPast = new Date(dayOff.date) < new Date();
                  return (
                    <tr key={dayOff.id} className="hover:bg-gray-50">
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-2 sm:gap-3">
                          <Avatar className="w-8 h-8 sm:w-10 sm:h-10">
                            <AvatarFallback className="bg-[#FF0077]/10 text-[#FF0077] text-xs sm:text-sm">
                              {member?.name.charAt(0) || "?"}
                            </AvatarFallback>
                          </Avatar>
                          <span className="text-sm sm:text-base font-medium">{dayOff.team_member_name}</span>
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-2">
                          <span className="text-sm sm:text-base">
                            {format(new Date(dayOff.date), "MMM d, yyyy")}
                          </span>
                          {isPast ? (
                            <Badge variant="outline" className="text-xs">Past</Badge>
                          ) : (
                            <Badge className="bg-green-100 text-green-800 text-xs">Upcoming</Badge>
                          )}
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <span className="text-sm text-gray-600">{dayOff.reason || "-"}</span>
                      </td>
                      <td className="px-4 py-3 text-right">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleRemoveDayOff(dayOff)}
                          className="min-h-[36px] touch-manipulation"
                        >
                          <X className="w-4 h-4" />
                        </Button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </SectionCard>
      )}

      {/* Add Day Off Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-[95vw] sm:max-w-2xl max-h-[95vh] overflow-y-auto p-4 sm:p-6">
          <DialogHeader>
            <DialogTitle className="text-base sm:text-lg font-semibold">
              Set Day Off
            </DialogTitle>
            <p className="text-xs sm:text-sm text-gray-500 mt-1">
              Set a day off for one or multiple team members
            </p>
          </DialogHeader>

          <div className="space-y-4 sm:space-y-6">
            {/* Team Member Selection */}
            <div>
              <div className="flex items-center justify-between mb-3">
                <Label className="text-sm sm:text-base font-medium">Select Team Members</Label>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={toggleSelectAll}
                  className="text-xs min-h-[32px] touch-manipulation"
                >
                  {selectedMembers.length === teamMembers.length ? "Deselect All" : "Select All"}
                </Button>
              </div>
              <div className="space-y-2 max-h-48 overflow-y-auto border rounded-lg p-3">
                {teamMembers.map((member) => (
                  <div
                    key={member.id}
                    className="flex items-center gap-3 p-2 hover:bg-gray-50 rounded-lg cursor-pointer"
                    onClick={() => toggleMemberSelection(member.id)}
                  >
                    <Checkbox
                      checked={selectedMembers.includes(member.id)}
                      onCheckedChange={() => toggleMemberSelection(member.id)}
                    />
                    <Avatar className="w-8 h-8">
                      <AvatarFallback className="bg-[#FF0077]/10 text-[#FF0077] text-xs">
                        {member.name.charAt(0)}
                      </AvatarFallback>
                    </Avatar>
                    <span className="text-sm font-medium flex-1">{member.name}</span>
                  </div>
                ))}
              </div>
            </div>

            {/* Date Selection */}
            <div>
              <Label className="text-sm sm:text-base font-medium mb-2 block">Date *</Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={cn(
                      "w-full justify-start text-left font-normal min-h-[44px] touch-manipulation",
                      !selectedDate && "text-muted-foreground"
                    )}
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {selectedDate ? format(selectedDate, "PPP") : "Pick a date"}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0" align="start">
                  <Calendar
                    mode="single"
                    selected={selectedDate}
                    onSelect={setSelectedDate}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>
            </div>

            {/* Reason */}
            <div>
              <Label htmlFor="reason" className="text-sm sm:text-base font-medium">Reason (Optional)</Label>
              <Input
                id="reason"
                value={reason}
                onChange={(e) => setReason(e.target.value)}
                placeholder="e.g., Vacation, Sick leave, Personal"
                className="mt-1.5 min-h-[44px] touch-manipulation"
              />
            </div>
          </div>

          <DialogFooter className="flex-col-reverse sm:flex-row gap-2 sm:gap-2 -mx-4 sm:-mx-6 px-4 sm:px-6 pt-4 border-t">
            <Button
              type="button"
              variant="outline"
              onClick={() => setIsDialogOpen(false)}
              className="w-full sm:w-auto min-h-[44px] touch-manipulation"
            >
              Cancel
            </Button>
            <Button
              type="button"
              onClick={handleSaveDayOff}
              className="w-full sm:w-auto bg-[#FF0077] hover:bg-[#D60565] min-h-[44px] touch-manipulation"
            >
              Set Day Off
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

