  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { DollarSign, Plus, ChevronRight, Calendar } from "lucide-react";
import { format, startOfWeek, endOfWeek, subDays } from "date-fns";
import { toast } from "sonner";
import Link from "next/link";
import { fetcher } from "@/lib/http/fetcher";

interface PayRun {
  id: string;
  pay_period_start: string;
  pay_period_end: string;
  status: string;
  created_at: string;
  approved_at?: string;
}

export default function PayrollPage() {
  const [payRuns, setPayRuns] = useState<PayRun[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [periodStart, setPeriodStart] = useState(format(startOfWeek(subDays(new Date(), 7)), "yyyy-MM-dd"));
  const [periodEnd, setPeriodEnd] = useState(format(endOfWeek(subDays(new Date(), 7)), "yyyy-MM-dd"));
  const [periodType, setPeriodType] = useState<"weekly" | "monthly">("weekly");
  const [isCreating, setIsCreating] = useState(false);

  useEffect(() => {
    loadPayRuns();
  }, []);

  const loadPayRuns = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data: PayRun[] }>("/api/provider/pay-runs");
      setPayRuns(response?.data ?? []);
    } catch (err) {
      console.error("Failed to load pay runs:", err);
      toast.error("Failed to load pay runs");
      setPayRuns([]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreate = async () => {
    try {
      setIsCreating(true);
      const res = await fetcher.post<{ data: { id: string } }>("/api/provider/pay-runs", {
        pay_period_start: periodStart,
        pay_period_end: periodEnd,
        period_type: periodType,
      });
      const id = (res as any)?.data?.id ?? (res as any)?.id;
      toast.success("Pay run created");
      setIsCreateOpen(false);
      if (id) window.location.href = `/provider/team/payroll/${id}`;
      else loadPayRuns();
    } catch (err: any) {
      toast.error(err?.message || "Failed to create pay run");
    } finally {
      setIsCreating(false);
    }
  };

  const statusColor = (s: string) => {
    if (s === "draft") return "bg-amber-100 text-amber-800";
    if (s === "approved") return "bg-blue-100 text-blue-800";
    if (s === "paid") return "bg-green-100 text-green-800";
    return "bg-gray-100 text-gray-800";
  };

  return (
    <div className="w-full max-w-full space-y-4 sm:space-y-6">
      <PageHeader
        title="Payroll"
        subtitle="Manage pay runs and staff payments"
        primaryAction={{
          label: "New Pay Run",
          onClick: () => setIsCreateOpen(true),
          icon: <Plus className="w-4 h-4 mr-2" />,
        }}
      />

      {isLoading ? (
        <SectionCard>
          <Skeleton className="h-48 w-full" />
        </SectionCard>
      ) : payRuns.length === 0 ? (
        <SectionCard className="p-8 text-center">
          <DollarSign className="w-12 h-12 text-gray-400 mx-auto mb-4" />
          <h3 className="font-medium text-gray-900 mb-2">No pay runs yet</h3>
          <p className="text-sm text-gray-600 mb-4">Create your first pay run to get started</p>
          <Button onClick={() => setIsCreateOpen(true)} className="bg-[#FF0077] hover:bg-[#D60565]">
            Create Pay Run
          </Button>
        </SectionCard>
      ) : (
        <SectionCard>
          <div className="divide-y">
            {payRuns.map((pr) => (
              <Link
                key={pr.id}
                href={`/provider/team/payroll/${pr.id}`}
                className="flex items-center justify-between py-4 hover:bg-gray-50 px-2 -mx-2 rounded-lg transition-colors"
              >
                <div className="flex items-center gap-3">
                  <Calendar className="w-5 h-5 text-gray-500" />
                  <div>
                    <p className="font-medium">
                      {format(new Date(pr.pay_period_start), "MMM d")} ΓÇô {format(new Date(pr.pay_period_end), "MMM d, yyyy")}
                    </p>
                    <p className="text-xs text-gray-500">Created {format(new Date(pr.created_at), "MMM d, yyyy")}</p>
                  </div>
                  <Badge className={statusColor(pr.status)}>{pr.status}</Badge>
                </div>
                <ChevronRight className="w-5 h-5 text-gray-400" />
              </Link>
            ))}
          </div>
        </SectionCard>
      )}

      <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create Pay Run</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div>
              <Label>Period Start</Label>
              <Input
                type="date"
                value={periodStart}
                onChange={(e) => setPeriodStart(e.target.value)}
                className="mt-1"
              />
            </div>
            <div>
              <Label>Period End</Label>
              <Input
                type="date"
                value={periodEnd}
                onChange={(e) => setPeriodEnd(e.target.value)}
                className="mt-1"
              />
            </div>
            <div>
              <Label>Period Type</Label>
              <select
                value={periodType}
                onChange={(e) => setPeriodType(e.target.value as "weekly" | "monthly")}
                className="w-full mt-1 h-10 rounded-md border border-input bg-background px-3 py-2"
              >
                <option value="weekly">Weekly</option>
                <option value="monthly">Monthly</option>
              </select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsCreateOpen(false)}>Cancel</Button>
            <Button onClick={handleCreate} disabled={isCreating} className="bg-[#FF0077] hover:bg-[#D60565]">
              {isCreating ? "Creating..." : "Create"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Separator } from "@/components/ui/separator";
import { Repeat } from "lucide-react";
import type { Shift, TeamMember } from "@/lib/provider-portal/types";

interface ShiftCreateEditDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  shift?: Shift | null;
  member?: TeamMember | null;
  date?: string;
  members: TeamMember[];
  onSave: () => void;
}

export function ShiftCreateEditDialog({
  open,
  onOpenChange,
  shift,
  member,
  date,
  members,
  onSave,
}: ShiftCreateEditDialogProps) {
  const [formData, setFormData] = useState({
    teamMemberId: "",
    date: "",
    startTime: "09:00",
    endTime: "17:00",
    isRepeating: false,
    repeatPattern: "weekly" as "daily" | "weekly" | "biweekly" | "monthly",
    repeatEndDate: "",
    repeatEndsAfter: "",
    isAlternating: false,
    alternatingWeek: "week1" as "week1" | "week2",
  });

  useEffect(() => {
    queueMicrotask(() => {
      if (shift) {
        const recurringPattern = shift.recurring_pattern || {};
        const isRepeating = shift.is_recurring || false;
        const isAlternating = recurringPattern.type === "alternating" || false;
        setFormData({
          teamMemberId: shift.team_member_id,
          date: shift.date,
          startTime: shift.start_time,
          endTime: shift.end_time,
          isRepeating: isRepeating,
          repeatPattern: (recurringPattern.pattern as "daily" | "weekly" | "monthly" | "biweekly") || "weekly",
          repeatEndDate: String(recurringPattern.end_date ?? ""),
          repeatEndsAfter: String(recurringPattern.ends_after ?? ""),
          isAlternating: isAlternating,
          alternatingWeek: ((recurringPattern.alternating_week as string) || "week1") as "week1" | "week2",
        });
      } else {
        setFormData({
          teamMemberId: member?.id || "",
          date: date || new Date().toISOString().split("T")[0],
          startTime: "09:00",
          endTime: "17:00",
          isRepeating: false,
          repeatPattern: "weekly",
          repeatEndDate: "",
          repeatEndsAfter: "",
          isAlternating: false,
          alternatingWeek: "week1",
        });
      }
    });
  }, [shift, member, date, open]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave();
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[95vw] sm:max-w-2xl max-h-[95vh] overflow-y-auto p-4 sm:p-6">
        <DialogHeader>
          <DialogTitle className="text-base sm:text-lg font-semibold">
            {shift ? "Edit Shift" : "Add Shift"}
          </DialogTitle>
          <p className="text-xs sm:text-sm text-gray-500 mt-1">
            {shift 
              ? "Update shift details and schedule"
              : "Create a new shift or repeating schedule"}
          </p>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4 sm:space-y-6">
          <div>
            <Label htmlFor="teamMemberId" className="text-sm sm:text-base">Team Member *</Label>
            <Select
              value={formData.teamMemberId}
              onValueChange={(value) => setFormData({ ...formData, teamMemberId: value })}
              required
            >
              <SelectTrigger className="mt-1.5 min-h-[44px] touch-manipulation">
                <SelectValue placeholder="Select team member" />
              </SelectTrigger>
              <SelectContent>
                {members.map((m) => (
                  <SelectItem key={m.id} value={m.id}>
                    {m.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label htmlFor="date" className="text-sm sm:text-base">Date *</Label>
            <Input
              id="date"
              type="date"
              value={formData.date}
              onChange={(e) => setFormData({ ...formData, date: e.target.value })}
              required
              className="mt-1.5 min-h-[44px] touch-manipulation"
            />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4">
            <div>
              <Label htmlFor="startTime" className="text-sm sm:text-base">Start Time *</Label>
              <Input
                id="startTime"
                type="time"
                value={formData.startTime}
                onChange={(e) => setFormData({ ...formData, startTime: e.target.value })}
                required
                className="mt-1.5 min-h-[44px] touch-manipulation"
              />
            </div>
            <div>
              <Label htmlFor="endTime" className="text-sm sm:text-base">End Time *</Label>
              <Input
                id="endTime"
                type="time"
                value={formData.endTime}
                onChange={(e) => setFormData({ ...formData, endTime: e.target.value })}
                required
                className="mt-1.5 min-h-[44px] touch-manipulation"
              />
            </div>
          </div>

          <Separator />

          {/* Alternating Hours (Bi-weekly) */}
          <div className="space-y-4">
            <div className="flex items-start gap-4 p-4 bg-gray-50 rounded-lg">
              <Switch
                checked={formData.isAlternating}
                onCheckedChange={(checked) => setFormData({ ...formData, isAlternating: checked })}
                className="mt-1"
              />
              <div className="flex-1">
                <Label className="text-sm sm:text-base font-medium cursor-pointer flex items-center gap-2">
                  <Repeat className="w-4 h-4" />
                  Alternating Hours (Bi-weekly Schedule)
                </Label>
                <p className="text-xs text-gray-500 mt-1">
                  Set up alternating hours that repeat every other week
                </p>
              </div>
            </div>

            {formData.isAlternating && (
              <div className="ml-0 sm:ml-12 space-y-3 p-4 bg-blue-50 rounded-lg border border-blue-200">
                <div>
                  <Label htmlFor="alternatingWeek" className="text-sm font-medium">
                    Which Week?
                  </Label>
                  <Select
                    value={formData.alternatingWeek}
                    onValueChange={(value: any) => setFormData({ ...formData, alternatingWeek: value })}
                  >
                    <SelectTrigger className="mt-1.5 min-h-[44px] touch-manipulation">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="week1">Week 1</SelectItem>
                      <SelectItem value="week2">Week 2</SelectItem>
                    </SelectContent>
                  </Select>
                  <p className="text-xs text-gray-500 mt-1.5">
                    Select which week this schedule applies to. The opposite week will be automatically set as off.
                  </p>
                </div>
              </div>
            )}
          </div>

          <Separator />

          {/* Repeating Shift */}
          <div className="space-y-4">
            <div className="flex items-start gap-4 p-4 bg-gray-50 rounded-lg">
              <Switch
                checked={formData.isRepeating}
                onCheckedChange={(checked) => setFormData({ ...formData, isRepeating: checked })}
                className="mt-1"
              />
              <div className="flex-1">
                <Label className="text-sm sm:text-base font-medium cursor-pointer flex items-center gap-2">
                  <Repeat className="w-4 h-4" />
                  Repeating Shift
                </Label>
                <p className="text-xs text-gray-500 mt-1">
                  Create a repeating shift pattern
                </p>
              </div>
            </div>

            {formData.isRepeating && (
              <div className="ml-0 sm:ml-12 space-y-4 p-4 bg-blue-50 rounded-lg border border-blue-200">
                <div>
                  <Label htmlFor="repeatPattern" className="text-sm font-medium">
                    Repeat Pattern
                  </Label>
                  <Select
                    value={formData.repeatPattern}
                    onValueChange={(value: any) => setFormData({ ...formData, repeatPattern: value })}
                  >
                    <SelectTrigger className="mt-1.5 min-h-[44px] touch-manipulation">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="daily">Daily</SelectItem>
                      <SelectItem value="weekly">Weekly</SelectItem>
                      <SelectItem value="biweekly">Bi-weekly (Every 2 weeks)</SelectItem>
                      <SelectItem value="monthly">Monthly</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <Label className="text-sm font-medium mb-2 block">Repeat Ends</Label>
                  <div className="space-y-2">
                    <div className="flex items-center gap-2">
                      <input
                        type="radio"
                        id="repeatNever"
                        name="repeatEnds"
                        checked={!formData.repeatEndDate && !formData.repeatEndsAfter}
                        onChange={() => setFormData({ ...formData, repeatEndDate: "", repeatEndsAfter: "" })}
                        className="w-4 h-4"
                      />
                      <Label htmlFor="repeatNever" className="text-sm cursor-pointer">
                        Never
                      </Label>
                    </div>
                    <div className="flex items-center gap-2">
                      <input
                        type="radio"
                        id="repeatEndDate"
                        name="repeatEnds"
                        checked={!!formData.repeatEndDate}
                        onChange={() => setFormData({ ...formData, repeatEndDate: new Date().toISOString().split("T")[0], repeatEndsAfter: "" })}
                        className="w-4 h-4"
                      />
                      <Label htmlFor="repeatEndDate" className="text-sm cursor-pointer">
                        On date
                      </Label>
                      {formData.repeatEndDate && (
                        <Input
                          type="date"
                          value={formData.repeatEndDate}
                          onChange={(e) => setFormData({ ...formData, repeatEndDate: e.target.value })}
                          className="ml-2 flex-1 min-h-[44px] touch-manipulation"
                        />
                      )}
                    </div>
                    <div className="flex items-center gap-2">
                      <input
                        type="radio"
                        id="repeatEndsAfter"
                        name="repeatEnds"
                        checked={!!formData.repeatEndsAfter}
                        onChange={() => setFormData({ ...formData, repeatEndsAfter: "10", repeatEndDate: "" })}
                        className="w-4 h-4"
                      />
                      <Label htmlFor="repeatEndsAfter" className="text-sm cursor-pointer">
                        After
                      </Label>
                      {formData.repeatEndsAfter && (
                        <div className="ml-2 flex items-center gap-2">
                          <Input
                            type="number"
                            min={1}
                            value={formData.repeatEndsAfter}
                            onChange={(e) => setFormData({ ...formData, repeatEndsAfter: e.target.value })}
                            className="w-20 min-h-[44px] touch-manipulation"
                          />
                          <span className="text-sm text-gray-600">occurrences</span>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>

          <DialogFooter className="flex-col-reverse sm:flex-row gap-2 sm:gap-2 -mx-4 sm:-mx-6 px-4 sm:px-6 pt-4 border-t">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="w-full sm:w-auto min-h-[44px] touch-manipulation"
            >
              Cancel
            </Button>
            <Button
              type="submit"
              className="w-full sm:w-auto bg-[#FF0077] hover:bg-[#D60565] min-h-[44px] touch-manipulation"
            >
              {shift ? "Update" : "Create"} Shift
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { Shift, TeamMember } from "@/lib/provider-portal/types";
import { PageHeader } from "@/components/provider/PageHeader";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { ChevronLeft, ChevronRight, Plus, Pencil } from "lucide-react";
import { ShiftCreateEditDialog } from "./components/ShiftCreateEditDialog";
import { toast } from "sonner";

export default function ProviderShifts() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [weekStart, setWeekStart] = useState(() => {
    const date = new Date();
    const day = date.getDay();
    const diff = date.getDate() - day;
    return new Date(date.setDate(diff));
  });
  const [selectedShift, setSelectedShift] = useState<Shift | null>(null);
  const [selectedMember, setSelectedMember] = useState<TeamMember | null>(null);
  const [selectedDate, setSelectedDate] = useState<string>("");
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);

  useEffect(() => {
    loadData();
  }, [weekStart]);

  const loadData = async () => {
    try {
      setIsLoading(true);
      const [shiftsData, members] = await Promise.all([
        providerApi.listShifts(weekStart.toISOString().split("T")[0]),
        providerApi.listTeamMembers(),
      ]);
      setShifts(shiftsData);
      setTeamMembers(members);
    } catch (error) {
      console.error("Failed to load shifts:", error);
      toast.error("Failed to load shifts");
    } finally {
      setIsLoading(false);
    }
  };

  const navigateWeek = (direction: "prev" | "next") => {
    const newDate = new Date(weekStart);
    newDate.setDate(newDate.getDate() + (direction === "next" ? 7 : -7));
    setWeekStart(newDate);
  };

  const goToToday = () => {
    const date = new Date();
    const day = date.getDay();
    const diff = date.getDate() - day;
    setWeekStart(new Date(date.setDate(diff)));
  };

  const getWeekDays = () => {
    const days = [];
    for (let i = 0; i < 7; i++) {
      const date = new Date(weekStart);
      date.setDate(date.getDate() + i);
      days.push(date);
    }
    return days;
  };

  const getShiftForMemberAndDay = (memberId: string, date: string) => {
    return shifts.find(
      (shift) => shift.team_member_id === memberId && shift.date === date
    );
  };

  const handleAddShift = (memberId?: string, date?: string) => {
    setSelectedShift(null);
    setSelectedMember(memberId ? teamMembers.find((m) => m.id === memberId) || null : null);
    setSelectedDate(date || "");
    setIsCreateDialogOpen(true);
  };

  const handleEditShift = (shift: Shift) => {
    setSelectedShift(shift);
    setSelectedMember(teamMembers.find((m) => m.id === shift.team_member_id) || null);
    setSelectedDate(shift.date);
    setIsCreateDialogOpen(true);
  };

  const handleSave = () => {
    setIsCreateDialogOpen(false);
    setSelectedShift(null);
    setSelectedMember(null);
    setSelectedDate("");
    loadData();
    toast.success(selectedShift ? "Shift updated" : "Shift created");
  };

  const weekDays = getWeekDays();

  return (
    <div>
      <PageHeader
        title="Scheduled Shifts"
        subtitle="Manage your team's schedule"
        primaryAction={{
          label: "Add Shift",
          onClick: () => handleAddShift(),
          icon: <Plus className="w-4 h-4 mr-2" />,
        }}
      />

      {/* Week Navigation */}
      <SectionCard className="mb-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Button variant="outline" size="icon" onClick={() => navigateWeek("prev")}>
              <ChevronLeft className="w-4 h-4" />
            </Button>
            <Button variant="outline" onClick={goToToday}>
              Today
            </Button>
            <Button variant="outline" size="icon" onClick={() => navigateWeek("next")}>
              <ChevronRight className="w-4 h-4" />
            </Button>
            <span className="ml-4 font-medium">
              {weekDays[0].toLocaleDateString("en-US", { month: "short", day: "numeric" })} -{" "}
              {weekDays[6].toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
            </span>
          </div>
        </div>
      </SectionCard>

      {/* Shifts Table */}
      {isLoading ? (
        <SectionCard>
          <Skeleton className="h-64 w-full" />
        </SectionCard>
      ) : teamMembers.length === 0 ? (
        <SectionCard className="p-12 text-center">
          <p className="text-gray-600 mb-4">No team members found</p>
          <Button variant="outline" onClick={() => window.location.href = "/provider/team/members"}>
            Add Team Members
          </Button>
        </SectionCard>
      ) : (
        <SectionCard className="p-0 overflow-hidden">
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Team Member</TableHead>
                  {weekDays.map((day, index) => (
                    <TableHead key={index} className="text-center min-w-[120px]">
                      <div className="flex flex-col">
                        <span className="text-xs text-gray-500">
                          {day.toLocaleDateString("en-US", { weekday: "short" })}
                        </span>
                        <span className="font-medium">
                          {day.toLocaleDateString("en-US", { day: "numeric", month: "short" })}
                        </span>
                      </div>
                    </TableHead>
                  ))}
                </TableRow>
              </TableHeader>
              <TableBody>
                {teamMembers.map((member) => (
                  <TableRow key={member.id}>
                    <TableCell className="font-medium">{member.name}</TableCell>
                    {weekDays.map((day, dayIndex) => {
                      const shift = getShiftForMemberAndDay(
                        member.id,
                        day.toISOString().split("T")[0]
                      );
                      return (
                        <TableCell key={dayIndex} className="text-center">
                          {shift ? (
                            <div className="flex items-center justify-center gap-2">
                              <Badge variant="outline" className="bg-[#FF0077]/10 text-[#FF0077] border-[#FF0077]/20">
                                {shift.start_time} - {shift.end_time}
                              </Badge>
                              <Button
                                variant="ghost"
                                size="icon"
                                className="h-6 w-6"
                                onClick={() => handleEditShift(shift)}
                              >
                                <Pencil className="w-3 h-3" />
                              </Button>
                            </div>
                          ) : (
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleAddShift(member.id, day.toISOString().split("T")[0])}
                            >
                              <Plus className="w-4 h-4" />
                            </Button>
                          )}
                        </TableCell>
                      );
                    })}
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        </SectionCard>
      )}

      <ShiftCreateEditDialog
        open={isCreateDialogOpen}
        onOpenChange={setIsCreateDialogOpen}
        shift={selectedShift}
        member={selectedMember}
        date={selectedDate}
        members={teamMembers}
        onSave={handleSave}
      />
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { TeamMember } from "@/lib/provider-portal/types";
import { PageHeader } from "@/components/provider/PageHeader";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Skeleton } from "@/components/ui/skeleton";
import { Clock, LogIn, LogOut, Edit, Users } from "lucide-react";
import { format } from "date-fns";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";

interface TimeCard {
  id: string;
  team_member_id: string;
  team_member_name: string;
  date: string;
  clock_in_time: string;
  clock_out_time?: string;
  total_hours?: number;
  status: "clocked_in" | "clocked_out";
}

export default function TimeClockPage() {
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [timeCards, setTimeCards] = useState<TimeCard[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("clock");
  const [_selectedMember, _setSelectedMember] = useState<string | null>(null);
  const [pin, setPin] = useState("");
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [editingTimeCard, setEditingTimeCard] = useState<TimeCard | null>(null);

  useEffect(() => {
    loadData();
    // Auto-refresh every 30 seconds
    const interval = setInterval(loadData, 30000);
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
    try {
      setIsLoading(true);
      const members = await providerApi.listTeamMembers();
      setTeamMembers(members.filter((m) => m.is_active && m.time_clock_enabled));

      // Load time cards from API
      const { fetcher } = await import("@/lib/http/fetcher");
      const response = await fetcher.get<{ data: TimeCard[] }>("/api/provider/time-clock");
      setTimeCards(response.data || []);
    } catch (error) {
      console.error("Failed to load data:", error);
      toast.error("Failed to load data");
      setTimeCards([]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleClockIn = async (memberId: string) => {
    try {
      const { fetcher } = await import("@/lib/http/fetcher");
      await fetcher.post(`/api/provider/staff/${memberId}/time-clock/clock-in`, {});
      toast.success("Clocked in successfully");
      loadData();
    } catch (error: any) {
      console.error("Failed to clock in:", error);
      toast.error(error?.message || "Failed to clock in");
    }
  };

  const handleClockOut = async (memberId: string) => {
    try {
      const { fetcher } = await import("@/lib/http/fetcher");
      await fetcher.post(`/api/provider/staff/${memberId}/time-clock/clock-out`, {});
      toast.success("Clocked out successfully");
      loadData();
    } catch (error: any) {
      console.error("Failed to clock out:", error);
      toast.error(error?.message || "Failed to clock out");
    }
  };

  const handlePinClockIn = async () => {
    if (!pin || pin.length !== 4) {
      toast.error("Please enter a 4-digit PIN");
      return;
    }

    try {
      const { fetcher } = await import("@/lib/http/fetcher");
      const response = await fetcher.post<{ data: { staff_id: string } }>("/api/provider/time-clock/clock-in-pin", { pin });
      if (response.data) {
        toast.success("Clocked in successfully");
        setPin("");
        loadData();
      }
    } catch (error: any) {
      console.error("Failed to clock in with PIN:", error);
      toast.error(error?.message || "Invalid PIN");
    }
  };

  const handleEditTimeCard = (timeCard: TimeCard) => {
    setEditingTimeCard(timeCard);
    setIsEditDialogOpen(true);
  };

  const getClockedInMembers = () => {
    return timeCards.filter((tc) => tc.status === "clocked_in");
  };

  const getTodayTimeCards = () => {
    const today = format(new Date(), "yyyy-MM-dd");
    return timeCards.filter((tc) => tc.date === today);
  };

  const getTotalHoursToday = () => {
    return getTodayTimeCards().reduce((total, tc) => total + (tc.total_hours || 0), 0);
  };

  return (
    <div>
      <PageHeader
        title="Time Clock"
        subtitle="Manage staff clock in/out and time cards"
      />

      {/* Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 sm:gap-4 mb-4 sm:mb-6">
        <SectionCard className="p-3 sm:p-4">
          <div className="flex items-center gap-2 sm:gap-3">
            <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-full bg-green-100 flex items-center justify-center flex-shrink-0">
              <LogIn className="w-5 h-5 sm:w-6 sm:h-6 text-green-600" />
            </div>
            <div className="min-w-0 flex-1">
              <div className="text-xs sm:text-sm text-gray-600">Clocked In</div>
              <div className="text-base sm:text-lg font-semibold truncate">
                {getClockedInMembers().length}
              </div>
            </div>
          </div>
        </SectionCard>
        <SectionCard className="p-3 sm:p-4">
          <div className="flex items-center gap-2 sm:gap-3">
            <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-full bg-blue-100 flex items-center justify-center flex-shrink-0">
              <Clock className="w-5 h-5 sm:w-6 sm:h-6 text-blue-600" />
            </div>
            <div className="min-w-0 flex-1">
              <div className="text-xs sm:text-sm text-gray-600">Today</div>
              <div className="text-base sm:text-lg font-semibold truncate">
                {getTodayTimeCards().length}
              </div>
            </div>
          </div>
        </SectionCard>
        <SectionCard className="p-3 sm:p-4">
          <div className="flex items-center gap-2 sm:gap-3">
            <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-full bg-purple-100 flex items-center justify-center flex-shrink-0">
              <Clock className="w-5 h-5 sm:w-6 sm:h-6 text-purple-600" />
            </div>
            <div className="min-w-0 flex-1">
              <div className="text-xs sm:text-sm text-gray-600">Hours Today</div>
              <div className="text-base sm:text-lg font-semibold truncate">
                {getTotalHoursToday().toFixed(1)}h
              </div>
            </div>
          </div>
        </SectionCard>
        <SectionCard className="p-3 sm:p-4">
          <div className="flex items-center gap-2 sm:gap-3">
            <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-full bg-[#FF0077]/10 flex items-center justify-center flex-shrink-0">
              <Users className="w-5 h-5 sm:w-6 sm:h-6 text-[#FF0077]" />
            </div>
            <div className="min-w-0 flex-1">
              <div className="text-xs sm:text-sm text-gray-600">Total Staff</div>
              <div className="text-base sm:text-lg font-semibold truncate">
                {teamMembers.length}
              </div>
            </div>
          </div>
        </SectionCard>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
        <TabsList className="grid w-full grid-cols-2 mb-4 sm:mb-6">
          <TabsTrigger value="clock" className="text-xs sm:text-sm">Clock In/Out</TabsTrigger>
          <TabsTrigger value="timecards" className="text-xs sm:text-sm">Time Cards</TabsTrigger>
        </TabsList>

        {/* Clock In/Out Tab */}
        <TabsContent value="clock" className="space-y-4 sm:space-y-6">
          {/* PIN Clock In (Front Desk) */}
          <SectionCard>
            <div className="space-y-4">
              <h3 className="text-sm sm:text-base font-semibold">Front Desk Clock In</h3>
              <p className="text-xs sm:text-sm text-gray-500">
                Enter PIN to clock in/out on front desk device
              </p>
              <div className="flex gap-2">
                <Input
                  type="text"
                  placeholder="Enter 4-digit PIN"
                  value={pin}
                  onChange={(e) => setPin(e.target.value.replace(/\D/g, "").slice(0, 4))}
                  maxLength={4}
                  className="flex-1 min-h-[44px] touch-manipulation text-center text-2xl tracking-widest"
                />
                <Button
                  onClick={handlePinClockIn}
                  className="bg-[#FF0077] hover:bg-[#D60565] min-h-[44px] touch-manipulation"
                >
                  Clock In
                </Button>
              </div>
            </div>
          </SectionCard>

          {/* Staff Clock In/Out */}
          <SectionCard>
            <div className="space-y-4">
              <h3 className="text-sm sm:text-base font-semibold">Staff Clock In/Out</h3>
              {isLoading ? (
                <Skeleton className="h-32 w-full" />
              ) : teamMembers.length === 0 ? (
                <p className="text-sm text-gray-500 text-center py-8">
                  No staff members with time clock enabled
                </p>
              ) : (
                <div className="space-y-3">
                  {teamMembers.map((member) => {
                    const isClockedIn = getClockedInMembers().some((tc) => tc.team_member_id === member.id);
                    return (
                      <div
                        key={member.id}
                        className="flex items-center justify-between p-3 sm:p-4 bg-gray-50 rounded-lg"
                      >
                        <div className="flex items-center gap-3">
                          <Avatar className="w-10 h-10 sm:w-12 sm:h-12">
                            <AvatarFallback className="bg-[#FF0077]/10 text-[#FF0077]">
                              {member.name.charAt(0)}
                            </AvatarFallback>
                          </Avatar>
                          <div>
                            <p className="font-medium text-sm sm:text-base">{member.name}</p>
                            <p className="text-xs text-gray-500">{member.email}</p>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          {isClockedIn ? (
                            <>
                              <Badge className="bg-green-100 text-green-800">Clocked In</Badge>
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={() => handleClockOut(member.id)}
                                className="min-h-[36px] touch-manipulation"
                              >
                                <LogOut className="w-4 h-4 mr-2" />
                                Clock Out
                              </Button>
                            </>
                          ) : (
                            <Button
                              size="sm"
                              onClick={() => handleClockIn(member.id)}
                              className="bg-[#FF0077] hover:bg-[#D60565] min-h-[36px] touch-manipulation"
                            >
                              <LogIn className="w-4 h-4 mr-2" />
                              Clock In
                            </Button>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </SectionCard>
        </TabsContent>

        {/* Time Cards Tab */}
        <TabsContent value="timecards" className="space-y-4 sm:space-y-6">
          <SectionCard className="p-0 overflow-hidden">
            {isLoading ? (
              <div className="p-4">
                <Skeleton className="h-64 w-full" />
              </div>
            ) : timeCards.length === 0 ? (
              <div className="p-8 sm:p-12 text-center">
                <Clock className="w-12 h-12 sm:w-16 sm:h-16 text-gray-300 mx-auto mb-4" />
                <p className="text-gray-600 mb-4">No time cards found</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Staff Member</TableHead>
                      <TableHead>Date</TableHead>
                      <TableHead>Clock In</TableHead>
                      <TableHead>Clock Out</TableHead>
                      <TableHead>Total Hours</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {timeCards.map((timeCard) => (
                      <TableRow key={timeCard.id}>
                        <TableCell>
                          <div className="flex items-center gap-2">
                            <Avatar className="w-8 h-8">
                              <AvatarFallback className="bg-[#FF0077]/10 text-[#FF0077] text-xs">
                                {timeCard.team_member_name.charAt(0)}
                              </AvatarFallback>
                            </Avatar>
                            <span className="text-sm font-medium">{timeCard.team_member_name}</span>
                          </div>
                        </TableCell>
                        <TableCell className="text-sm">
                          {format(new Date(timeCard.date), "MMM d, yyyy")}
                        </TableCell>
                        <TableCell className="text-sm">{timeCard.clock_in_time}</TableCell>
                        <TableCell className="text-sm">
                          {timeCard.clock_out_time || (
                            <Badge className="bg-green-100 text-green-800 text-xs">In Progress</Badge>
                          )}
                        </TableCell>
                        <TableCell className="text-sm font-medium">
                          {timeCard.total_hours ? `${timeCard.total_hours.toFixed(1)}h` : "-"}
                        </TableCell>
                        <TableCell className="text-right">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleEditTimeCard(timeCard)}
                            className="min-h-[36px] touch-manipulation"
                          >
                            <Edit className="w-4 h-4" />
                          </Button>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            )}
          </SectionCard>
        </TabsContent>
      </Tabs>

      {/* Edit Time Card Dialog */}
      <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
        <DialogContent className="max-w-[95vw] sm:max-w-md p-4 sm:p-6">
          <DialogHeader>
            <DialogTitle className="text-base sm:text-lg font-semibold">Edit Time Card</DialogTitle>
          </DialogHeader>
          {editingTimeCard && (
            <div className="space-y-4">
              <div>
                <Label className="text-sm font-medium">Clock In Time</Label>
                <Input
                  type="time"
                  defaultValue={editingTimeCard.clock_in_time}
                  className="mt-1.5 min-h-[44px] touch-manipulation"
                />
              </div>
              <div>
                <Label className="text-sm font-medium">Clock Out Time</Label>
                <Input
                  type="time"
                  defaultValue={editingTimeCard.clock_out_time || ""}
                  className="mt-1.5 min-h-[44px] touch-manipulation"
                />
              </div>
            </div>
          )}
          <DialogFooter className="flex-col-reverse sm:flex-row gap-2 -mx-4 sm:-mx-6 px-4 sm:px-6 pt-4 border-t">
            <Button
              variant="outline"
              onClick={() => setIsEditDialogOpen(false)}
              className="w-full sm:w-auto min-h-[44px] touch-manipulation"
            >
              Cancel
            </Button>
            <Button
              onClick={async () => {
                if (!editingTimeCard) return;
                try {
                  const { fetcher } = await import("@/lib/http/fetcher");
                  const clockInInput = (document.querySelector('input[type="time"]') as HTMLInputElement)?.value;
                  const clockOutInput = (document.querySelectorAll('input[type="time"]')[1] as HTMLInputElement)?.value;

                  const updateData: any = {};
                  if (clockInInput) {
                    const today = editingTimeCard.date;
                    updateData.clock_in_time = new Date(`${today}T${clockInInput}`).toISOString();
                  }
                  if (clockOutInput !== undefined) {
                    if (clockOutInput) {
                      const today = editingTimeCard.date;
                      updateData.clock_out_time = new Date(`${today}T${clockOutInput}`).toISOString();
                    } else {
                      updateData.clock_out_time = null;
                    }
                  }

                  await fetcher.put(`/api/provider/staff/${editingTimeCard.team_member_id}/time-clock/${editingTimeCard.id}`, updateData);
                  toast.success("Time card updated");
                  setIsEditDialogOpen(false);
                  loadData();
                } catch (error: any) {
                  console.error("Failed to update time card:", error);
                  toast.error(error?.message || "Failed to update time card");
                }
              }}
              className="w-full sm:w-auto bg-[#FF0077] hover:bg-[#D60565] min-h-[44px] touch-manipulation"
            >
              Save Changes
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { TeamMember } from "@/lib/provider-portal/types";
import { PageHeader } from "@/components/provider/PageHeader";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Skeleton } from "@/components/ui/skeleton";
import { Calendar, DollarSign, Clock, TrendingUp, ChevronLeft, ChevronRight } from "lucide-react";
import { format, startOfWeek, endOfWeek } from "date-fns";
import { handleError, withRetry } from "@/lib/provider-portal/error-handler";

interface StaffTotals {
  team_member_id: string;
  team_member_name: string;
  appointments_count: number;
  revenue: number;
  tips: number;
  hours_worked: number;
  commission: number;
  rating?: number;
}

export default function StaffTotalsPage() {
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [selectedMember, setSelectedMember] = useState<string | null>(null);
  const [totals, setTotals] = useState<StaffTotals[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("daily");
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [weekStart, setWeekStart] = useState(() => startOfWeek(new Date()));

  useEffect(() => {
    loadTeamMembers();
  }, []);

  useEffect(() => {
    if (activeTab === "daily") {
      loadDailyTotals();
    } else {
      loadWeeklyTotals();
    }
  }, [activeTab, selectedDate, weekStart, selectedMember]);

  const loadTeamMembers = async () => {
    try {
      const members = await providerApi.listTeamMembers();
      setTeamMembers(members.filter((m) => m.is_active));
      if (members.length > 0 && !selectedMember) {
        setSelectedMember("all");
      }
    } catch (error) {
      handleError(error, {
        action: "loadTeamMembers",
        resource: "team members",
      });
    }
  };

  const loadDailyTotals = async () => {
    setIsLoading(true);
    try {
      const { fetcher } = await import("@/lib/http/fetcher");
      const dateStr = format(selectedDate, "yyyy-MM-dd");
      
      let endpoint = "/api/provider/staff/totals";
      const params = new URLSearchParams({
        date: dateStr,
        period: "daily"
      });
      
      if (selectedMember && selectedMember !== "all") {
        endpoint = `/api/provider/staff/${selectedMember}/totals`;
      }
      
      const response = await withRetry(
        () => fetcher.get<{ data: StaffTotals[] }>(
          `${endpoint}?${params.toString()}`
        ),
        {
          maxRetries: 2,
          retryDelay: 1000,
        }
      );
      
      setTotals(response.data || []);
    } catch (error) {
      handleError(error, {
        action: "loadDailyTotals",
        resource: "staff totals",
      });
      setTotals([]);
    } finally {
      setIsLoading(false);
    }
  };

  const loadWeeklyTotals = async () => {
    setIsLoading(true);
    try {
      const { fetcher } = await import("@/lib/http/fetcher");
      const weekStartStr = format(weekStart, "yyyy-MM-dd");
      const weekEndStr = format(endOfWeek(weekStart), "yyyy-MM-dd");
      
      let endpoint = "/api/provider/staff/totals";
      const params = new URLSearchParams({
        start_date: weekStartStr,
        end_date: weekEndStr,
        period: "weekly"
      });
      
      if (selectedMember && selectedMember !== "all") {
        endpoint = `/api/provider/staff/${selectedMember}/totals`;
      }
      
      const response = await withRetry(
        () => fetcher.get<{ data: StaffTotals[] }>(
          `${endpoint}?${params.toString()}`
        ),
        {
          maxRetries: 2,
          retryDelay: 1000,
        }
      );
      
      setTotals(response.data || []);
    } catch (error) {
      handleError(error, {
        action: "loadWeeklyTotals",
        resource: "staff totals",
      });
      setTotals([]);
    } finally {
      setIsLoading(false);
    }
  };

  const navigateDate = (direction: "prev" | "next") => {
    if (activeTab === "daily") {
      setSelectedDate((prev) => {
        const newDate = new Date(prev);
        newDate.setDate(newDate.getDate() + (direction === "next" ? 1 : -1));
        return newDate;
      });
    } else {
      setWeekStart((prev) => {
        const newDate = new Date(prev);
        newDate.setDate(newDate.getDate() + (direction === "next" ? 7 : -7));
        return newDate;
      });
    }
  };

  const goToToday = () => {
    setSelectedDate(new Date());
    setWeekStart(startOfWeek(new Date()));
  };

  const getTotalStats = () => {
    return totals.reduce(
      (acc, total) => ({
        appointments: acc.appointments + total.appointments_count,
        revenue: acc.revenue + total.revenue,
        tips: acc.tips + total.tips,
        hours: acc.hours + total.hours_worked,
        commission: acc.commission + total.commission,
      }),
      { appointments: 0, revenue: 0, tips: 0, hours: 0, commission: 0 }
    );
  };

  const filteredTotals = selectedMember && selectedMember !== "all"
    ? totals.filter((t) => t.team_member_id === selectedMember)
    : totals;

  const stats = getTotalStats();

  return (
    <div>
      <PageHeader
        title="Staff Totals"
        subtitle="View daily and weekly performance metrics for your team"
      />

      {/* Date Navigation */}
      <SectionCard className="mb-4 sm:mb-6">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <Button variant="outline" size="icon" onClick={() => navigateDate("prev")} className="min-h-[44px] min-w-[44px] touch-manipulation">
              <ChevronLeft className="w-4 h-4" />
            </Button>
            <Button variant="outline" onClick={goToToday} className="min-h-[44px] touch-manipulation">
              Today
            </Button>
            <Button variant="outline" size="icon" onClick={() => navigateDate("next")} className="min-h-[44px] min-w-[44px] touch-manipulation">
              <ChevronRight className="w-4 h-4" />
            </Button>
            <span className="ml-2 sm:ml-4 font-medium text-sm sm:text-base">
              {activeTab === "daily"
                ? format(selectedDate, "EEEE, MMM d, yyyy")
                : `${format(weekStart, "MMM d")} - ${format(endOfWeek(weekStart), "MMM d, yyyy")}`}
            </span>
          </div>
          <Select value={selectedMember || "all"} onValueChange={setSelectedMember}>
            <SelectTrigger className="w-full sm:w-[200px] min-h-[44px] touch-manipulation">
