"use client";

import { useState, useEffect } from "react";
import { useSearchParams } from "next/navigation";
import * as Sentry from "@sentry/nextjs";

/**
 * Sentry test page. Visit /sentry-example-page and click a button to send
 * a test error to Sentry (org: beautonomi, project: web-nextjs).
 * Or visit /sentry-example-page?trigger=1 to trigger on load.
 */
const TEST_MESSAGE = "Beautonomi Sentry test - web-nextjs";

async function sendTestToSentry() {
  Sentry.captureException(new Error(TEST_MESSAGE), {
    tags: { source: "sentry-example-page" },
  });
  await Sentry.flush(2000);
}

function triggerUncaughtError() {
  // Intentionally call undefined to trigger an uncaught error
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  (window as any).myUndefinedFunction();
}

export default function SentryExamplePage() {
  const [status, setStatus] = useState<"idle" | "sending" | "sent" | "error">("idle");
  const [serverStatus, setServerStatus] = useState<"idle" | "sending" | "sent" | "error">("idle");
  const [eventId, setEventId] = useState<string | null>(null);
  const [serverEventId, setServerEventId] = useState<string | null>(null);
  const searchParams = useSearchParams();

  useEffect(() => {
    if (typeof window === "undefined") return;
    if (searchParams.get("trigger") === "1") {
      setStatus("sending");
      sendTestToSentry()
        .then(() => setStatus("sent"))
        .catch(() => setStatus("error"));
    }
  }, [searchParams]);

  const onCaptureClick = async () => {
    setStatus("sending");
    try {
      const id = Sentry.captureException(new Error(TEST_MESSAGE), {
        tags: { source: "sentry-example-page" },
      });
      setEventId(id ?? null);
      await Sentry.flush(2000);
      setStatus("sent");
    } catch {
      setStatus("error");
    }
  };

  const onUncaughtClick = () => {
    setStatus("sent");
    triggerUncaughtError();
  };

  const onServerTestClick = async () => {
    setServerStatus("sending");
    setServerEventId(null);
    try {
      const res = await fetch("/api/sentry-test");
      const data = await res.json();
      if (!res.ok) {
        setServerStatus("error");
        return;
      }
      setServerEventId(data.eventId ?? null);
      setServerStatus("sent");
    } catch {
      setServerStatus("error");
    }
  };

  return (
    <div className="mx-auto max-w-lg px-6 py-12 space-y-6">
      <h1 className="text-2xl font-semibold">Sentry test page</h1>
      <p className="text-muted-foreground">
        Send a test error to Sentry (beautonomi / web-nextjs). Check{" "}
        <a
          href="https://sentry.io/organizations/beautonomi/issues/?project=4510963809452112"
          target="_blank"
          rel="noopener noreferrer"
          className="text-primary underline"
        >
          Sentry ΓåÆ Issues
        </a>
        .
      </p>

      <div className="flex flex-col gap-3">
        <button
          type="button"
          onClick={onServerTestClick}
          disabled={serverStatus === "sending"}
          className="rounded-md bg-primary px-4 py-2 text-primary-foreground hover:opacity-90 disabled:opacity-50"
        >
          {serverStatus === "sending" ? "SendingΓÇª" : "Send test from server (recommended)"}
        </button>
        <p className="text-xs text-muted-foreground">
          Uses the serverΓÇÖs SENTRY_DSN. If this shows up in Sentry, your project is connected.
        </p>
        <button
          type="button"
          onClick={onCaptureClick}
          disabled={status === "sending"}
          className="rounded-md border border-input bg-background px-4 py-2 hover:bg-accent disabled:opacity-50"
        >
          {status === "sending" ? "SendingΓÇª" : "Send test from browser (client)"}
        </button>
        <button
          type="button"
          onClick={onUncaughtClick}
          className="rounded-md border border-input bg-background px-4 py-2 hover:bg-accent"
        >
          Trigger uncaught error (myUndefinedFunction)
        </button>
      </div>

      {(status === "sent" || serverStatus === "sent") && (
        <p className="text-sm text-green-600 dark:text-green-400">
          Event sent. {eventId && `Client event ID: ${eventId}. `}
          {serverEventId && `Server event ID: ${serverEventId}. `}
          Refresh Sentry Issues in a few seconds.
        </p>
      )}
      {(status === "error" || serverStatus === "error") && (
        <p className="text-sm text-destructive">Failed to send. Check console and steps below.</p>
      )}

      <div className="mt-8 rounded-md border border-border bg-muted/50 p-4 text-sm text-muted-foreground space-y-2">
        <p className="font-medium text-foreground">If issues donΓÇÖt appear in Sentry:</p>
        <ol className="list-decimal list-inside space-y-1">
          <li>Restart the dev server (NEXT_PUBLIC_* is set at startup).</li>
          <li>Clear build cache: <code className="bg-muted px-1">cd apps/web && pnpm clean && pnpm dev</code>.</li>
          <li>In browser DevTools ΓåÆ Network, filter by &quot;sentry&quot; or &quot;ingest&quot;; you should see a request to ingest.de.sentry.io after clicking.</li>
          <li>Run <code className="bg-muted px-1">node scripts/check-sentry-env.mjs</code> in apps/web to verify env vars.</li>
        </ol>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { useParams, useRouter } from "next/navigation";
import Image from "next/image";
import Link from "next/link";
import { useAuth } from "@/providers/AuthProvider";

interface ProductVariant {
  id: string;
  option_values: Record<string, string>;
  sort_order?: number;
  retail_price: number;
  quantity: number;
  sku?: string | null;
  image_url?: string | null;
}

interface ProductDetail {
  id: string;
  name: string;
  brand: string | null;
  category: string | null;
  short_description: string | null;
  long_description: string | null;
  description: string | null;
  retail_price: number;
  currency?: string | null;
  image_urls: string[];
  quantity: number;
  tags: string[];
  has_variants?: boolean;
  variant_option_types?: Array<{ name: string; values: string[] }>;
  variants?: ProductVariant[];
  provider: { id: string; business_name: string; slug: string; logo_url: string | null };
}

/** Format price with currency (default ZAR/R). */
function formatPrice(price: number, currency?: string | null): string {
  const code = (currency || "ZAR").toUpperCase();
  if (code === "ZAR") return `R${price.toFixed(2)}`;
  return `${code} ${price.toFixed(2)}`;
}

interface Review {
  id: string;
  rating: number;
  title: string | null;
  comment: string | null;
  is_verified_purchase: boolean;
  created_at: string;
  customer: { full_name: string; avatar_url: string | null };
  provider_response: string | null;
}

interface RelatedProduct {
  id: string;
  name: string;
  retail_price: number;
  image_urls: string[];
  brand: string | null;
}

function Stars({ rating }: { rating: number }) {
  return (
    <div className="flex gap-0.5">
      {[1, 2, 3, 4, 5].map((i) => (
        <svg
          key={i}
          className={`h-4 w-4 ${i <= Math.round(rating) ? "text-yellow-400" : "text-gray-200"}`}
          fill="currentColor"
          viewBox="0 0 20 20"
        >
          <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
        </svg>
      ))}
    </div>
  );
}

export default function ProductDetailPage() {
  const params = useParams();
  const router = useRouter();
  const { user } = useAuth();
  const [product, setProduct] = useState<ProductDetail | null>(null);
  const [reviews, setReviews] = useState<{ average_rating: number; total_count: number; recent: Review[] }>({
    average_rating: 0,
    total_count: 0,
    recent: [],
  });
  const [related, setRelated] = useState<RelatedProduct[]>([]);
  const [shipping, setShipping] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [quantity, setQuantity] = useState(1);
  const [activeImage, setActiveImage] = useState(0);
  const [addingToCart, setAddingToCart] = useState(false);
  const [cartMessage, setCartMessage] = useState<{ text: string; type: "success" | "error" } | null>(null);
  const [selectedVariantId, setSelectedVariantId] = useState<string | null>(null);

  const hasVariants = Boolean(product?.has_variants && product?.variants?.length);
  const variants = product?.variants ?? [];
  const selectedVariant = hasVariants && selectedVariantId ? variants.find((v) => v.id === selectedVariantId) : null;
  const displayPrice = hasVariants && selectedVariant ? selectedVariant.retail_price : (product?.retail_price ?? 0);
  const displayQuantity = hasVariants && selectedVariant ? selectedVariant.quantity : (product?.quantity ?? 0);
  const inStockFromVariant = hasVariants ? (selectedVariant ? selectedVariant.quantity > 0 : false) : undefined;

  const handleAddToCart = useCallback(async () => {
    if (!product || addingToCart) return;
    if (hasVariants && !selectedVariantId) {
      setCartMessage({ text: "Please select a variant", type: "error" });
      return;
    }
    if (!user) {
      router.push(`/account-settings?redirect=${encodeURIComponent(`/shop/${product.id}`)}`);
      return;
    }
    setAddingToCart(true);
    setCartMessage(null);
    try {
      const res = await fetch("/api/me/cart", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          product_id: product.id,
          quantity,
          ...(hasVariants && selectedVariantId ? { product_variant_id: selectedVariantId } : {}),
        }),
      });
      const json = await res.json();
      if (res.ok) {
        setCartMessage({ text: "Added to cart!", type: "success" });
        setTimeout(() => setCartMessage(null), 3000);
        if (typeof window !== "undefined") {
          window.dispatchEvent(new CustomEvent("beautonomi:cart-updated"));
        }
      } else if (res.status === 401) {
        setCartMessage({
          text: "Please sign in to add to cart.",
          type: "error",
        });
        router.push(`/account-settings?redirect=${encodeURIComponent(`/shop/${product.id}`)}`);
      } else {
        setCartMessage({ text: json.error?.message || json.error || "Failed to add to cart", type: "error" });
      }
    } catch {
      setCartMessage({ text: "Something went wrong", type: "error" });
    }
    setAddingToCart(false);
  }, [product, quantity, addingToCart, user, router, hasVariants, selectedVariantId]);

  useEffect(() => {
    if (!params.id) return;
    (async () => {
      setLoading(true);
      setSelectedVariantId(null);
      try {
        const res = await fetch(`/api/public/products/${params.id}`);
        const json = await res.json();
        if (json.data) {
          const p = json.data.product;
          setProduct(p);
          setReviews(json.data.reviews);
          setRelated(json.data.related_products);
          setShipping(json.data.shipping);
          if (p?.has_variants && Array.isArray(p.variants) && p.variants.length > 0) {
            const firstInStock = p.variants.find((v: ProductVariant) => (v.quantity || 0) > 0);
            setSelectedVariantId(firstInStock ? firstInStock.id : p.variants[0].id);
          }
        }
      } catch { /* ignore */ }
      setLoading(false);
    })();
  }, [params.id]);

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-pink-200 border-t-pink-600" />
      </div>
    );
  }

  if (!product) {
    return (
      <div className="flex min-h-screen flex-col items-center justify-center text-gray-400">
        <p className="text-lg">Product not found</p>
        <button onClick={() => router.back()} className="mt-4 text-pink-600 hover:underline">
          Go back
        </button>
      </div>
    );
  }

  const desc = product.long_description || product.description || product.short_description;
  const inStock = inStockFromVariant !== undefined ? inStockFromVariant : product.quantity > 0;
  const maxQty = hasVariants && selectedVariant ? selectedVariant.quantity : product.quantity;

  return (
    <div className="min-h-screen bg-white">
      <div className="mx-auto max-w-6xl px-4 py-8 sm:px-6 lg:px-8">
        <button onClick={() => router.back()} className="mb-6 flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700">
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
          Back to Shop
        </button>

        <div className="grid gap-8 lg:grid-cols-2">
          {/* Images */}
          <div>
            <div className="relative aspect-square overflow-hidden rounded-2xl bg-gray-100">
              {product.image_urls[activeImage] ? (
                <Image
                  src={product.image_urls[activeImage]}
                  alt={product.name}
                  fill
                  className="object-cover"
                  sizes="(max-width: 1024px) 100vw, 50vw"
                  priority
                />
              ) : (
                <div className="flex h-full items-center justify-center text-gray-300">
                  <svg className="h-20 w-20" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" />
                  </svg>
                </div>
              )}
            </div>
            {product.image_urls.length > 1 && (
              <div className="mt-4 flex gap-3">
                {product.image_urls.map((url, i) => (
                  <button
                    key={i}
                    onClick={() => setActiveImage(i)}
                    className={`relative h-20 w-20 overflow-hidden rounded-xl border-2 transition ${
                      i === activeImage ? "border-pink-500" : "border-transparent"
                    }`}
                  >
                    <Image src={url} alt="" fill className="object-cover" sizes="80px" />
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Info */}
          <div>
            {product.brand && <p className="mb-1 text-sm font-medium text-gray-400">{product.brand}</p>}
            <h1 className="text-2xl font-bold text-gray-900 sm:text-3xl">{product.name}</h1>

            {hasVariants && variants.length > 0 && (
              <div className="mt-3">
                <p className="text-sm font-medium text-gray-700 mb-2">
                  {product.variant_option_types?.[0]?.name ?? "Option"}
                </p>
