                  {variants.map((v) => {
                    const label = Object.entries(v.option_values).map(([, val]) => val).join(" / ");
                    const isSelected = selectedVariantId === v.id;
                    const outOfStock = (v.quantity || 0) <= 0;
                    return (
                      <button
                        key={v.id}
                        type="button"
                        onClick={() => !outOfStock && setSelectedVariantId(v.id)}
                        disabled={outOfStock}
