source:
"use client";

import { useEffect, useState, useCallback } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { fetcher } from "@/lib/http/fetcher";
import { useAuth } from "@/providers/AuthProvider";
import { useFeatureFlag } from "@/hooks/useFeatureFlag";
import {
  Store,
  Truck,
  Loader2,
  ShoppingBag,
  ChevronLeft,
  AlertCircle,
} from "lucide-react";
import Link from "next/link";

interface CartItem {
  id: string;
  quantity: number;
  effective_price?: number;
  product_variant?: { option_values?: Record<string, string> } | null;
  product: {
    id: string;
    name: string;
    retail_price: number;
    image_urls: string[];
  };
}

interface Address {
  id: string;
  label: string | null;
  address_line1: string;
  city: string;
  postal_code: string | null;
  is_default: boolean;
}

interface Location {
  id: string;
  name: string;
  address_line1: string;
  city: string;
}

interface ShippingConfig {
  offers_delivery: boolean;
  offers_collection: boolean;
  delivery_fee: number;
  free_delivery_threshold: number | null;
  estimated_delivery_days: number;
}

export default function ProductCheckoutPage() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const { user } = useAuth();
  const providerId = searchParams.get("provider_id");

  const [items, setItems] = useState<CartItem[]>([]);
  const [addresses, setAddresses] = useState<Address[]>([]);
  const [locations, setLocations] = useState<Location[]>([]);
  const [shippingConfig, setShippingConfig] = useState<ShippingConfig | null>(null);
  const [loading, setLoading] = useState(true);
  const [placing, setPlacing] = useState(false);

  const [fulfillment, setFulfillment] = useState<"collection" | "delivery">("collection");
  const [selectedAddress, setSelectedAddress] = useState<string>("");
  const [selectedLocation, setSelectedLocation] = useState<string>("");
  const [paymentMethod, setPaymentMethod] = useState<"paystack" | "card_on_delivery">("paystack");
  const [useWallet, setUseWallet] = useState(false);
  const [walletBalance, setWalletBalance] = useState(0);
  const [platformFeeConfig, setPlatformFeeConfig] = useState({ type: "percentage", percentage: 5, fixed: 0, show: true });
  const { enabled: paystackEnabled } = useFeatureFlag("payment_paystack");
  const { enabled: walletEnabled } = useFeatureFlag("payment_wallet");

  useEffect(() => {
    if (!providerId) return;
    (async () => {
      setLoading(true);

      // Fetch cart
      const cartRes = await fetcher.get<{ data: { items: CartItem[] } }>("/api/me/cart");
      const allItems = cartRes?.data?.items ?? [];
      const providerItems = allItems.filter(
        (item: any) => (item.provider?.id ?? item.product?.provider_id) === providerId,
      );
      setItems(providerItems);

      // Fetch addresses
      const addrRes = await fetcher.get<{ data: { addresses: Address[] } | Address[] }>(
        "/api/me/addresses",
      );
      const addrData = addrRes?.data;
      const addrList = Array.isArray(addrData) ? addrData : (addrData as any)?.addresses ?? [];
      setAddresses(addrList);
      const def = addrList.find((a: Address) => a.is_default);
      if (def) setSelectedAddress(def.id);

      // Fetch locations
      const locRes = await fetcher.get<{ data: { locations: Location[] } | Location[] }>(
        `/api/public/provider-locations?provider_id=${providerId}`,
      );
      const locData = locRes?.data;
      const locList = Array.isArray(locData) ? locData : (locData as any)?.locations ?? [];
      setLocations(locList);
      if (locList.length > 0) setSelectedLocation(locList[0].id);

      // Fetch shipping config
      const shipRes = await fetcher.get<{ data: any }>(
        `/api/public/products/shipping-config?provider_id=${providerId}`,
      );
      if (shipRes?.data) {
        const sc = shipRes.data?.shipping ?? shipRes.data?.config ?? shipRes.data;
        setShippingConfig(sc);
        if (!sc.offers_collection && sc.offers_delivery) setFulfillment("delivery");
      }

      // Fetch platform fees
      const feeRes = await fetcher.get<{ data: any }>("/api/public/platform-fees");
      if (feeRes?.data) {
        setPlatformFeeConfig({
          type: feeRes.data.platform_service_fee_type ?? "percentage",
          percentage: feeRes.data.platform_service_fee_percentage ?? 5,
          fixed: feeRes.data.platform_service_fee_fixed ?? 0,
          show: feeRes.data.show_service_fee_to_customer !== false,
        });
      }

      // Fetch wallet balance (for "Use wallet" option)
      if (user) {
        try {
          const walletRes = await fetcher.get<{ data: { wallet: { balance: number } } }>("/api/me/wallet", { cache: "no-store" });
          if (walletRes?.data?.wallet) setWalletBalance(Number(walletRes.data.wallet.balance) || 0);
        } catch {
          // ignore
        }
      }

      setLoading(false);
    })();
  }, [providerId, user]);

  // When Paystack is disabled, default to pay on delivery
  useEffect(() => {
    if (!paystackEnabled && paymentMethod === "paystack") {
      setPaymentMethod("card_on_delivery");
    }
  }, [paystackEnabled, paymentMethod]);

  const linePrice = (i: CartItem) => (i.effective_price ?? i.product?.retail_price ?? 0) * i.quantity;
  const subtotal = items.reduce(
    (s, i) => s + linePrice(i),
    0,
  );
  const deliveryFee =
    fulfillment === "delivery" && shippingConfig
      ? shippingConfig.free_delivery_threshold && subtotal >= shippingConfig.free_delivery_threshold
        ? 0
        : Number(shippingConfig.delivery_fee) || 0
      : 0;
  const platformFee =
    paymentMethod === "paystack"
      ? platformFeeConfig.type === "fixed"
        ? platformFeeConfig.fixed
        : Math.round(subtotal * platformFeeConfig.percentage) / 100
      : 0;
  const total = subtotal + deliveryFee + platformFee;

  const handlePlaceOrder = useCallback(async () => {
    if (!providerId) return;
    if (fulfillment === "delivery" && !selectedAddress) return;
    if (fulfillment === "collection" && !selectedLocation) return;

    setPlacing(true);

    const orderRes = await fetcher.post<{
      data: { order: { id: string; order_number: string }; paid_with_wallet?: boolean; amount_due?: number };
    }>("/api/me/orders", {
      provider_id: providerId,
      fulfillment_type: fulfillment,
      delivery_address_id: fulfillment === "delivery" ? selectedAddress : undefined,
      collection_location_id: fulfillment === "collection" ? selectedLocation : undefined,
      payment_method: paymentMethod,
      use_wallet: paymentMethod === "paystack" ? useWallet : false,
    });

    const order = orderRes?.data?.order;
    const paidWithWallet = orderRes?.data?.paid_with_wallet === true;
    const amountDue = orderRes?.data?.amount_due ?? total;

    if (paymentMethod === "card_on_delivery" || paidWithWallet) {
      setPlacing(false);
      router.push("/account-settings/orders");
      return;
    }

    if (!order || !user?.email) {
      setPlacing(false);
      router.push("/account-settings/orders");
      return;
    }

    // Initialize Paystack for remaining amount
    const payRes = await fetcher.post<{
      data: { authorization_url: string; reference: string };
    }>("/api/paystack/initialize", {
      email: user.email,
      amount: Math.round(amountDue * 100),
      metadata: {
        product_order_id: order.id,
        order_number: order.order_number,
        type: "product_order",
      },
    });

    setPlacing(false);

    if (payRes?.data?.authorization_url) {
      window.location.href = payRes.data.authorization_url;
    } else {
      router.push("/account-settings/orders");
    }
  }, [providerId, fulfillment, selectedAddress, selectedLocation, user, total, router]);

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-pink-500" />
      </div>
    );
  }

  if (!providerId || items.length === 0) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <ShoppingBag className="w-16 h-16 text-gray-300 mx-auto mb-4" />
          <h2 className="text-xl font-bold text-gray-900 mb-2">No items to checkout</h2>
          <Link href="/cart" className="text-pink-600 hover:underline">
            Back to cart
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-3xl mx-auto px-4">
        <Link
          href="/cart"
          className="inline-flex items-center gap-1 text-sm text-gray-500 hover:text-gray-700 mb-6"
        >
          <ChevronLeft className="w-4 h-4" />
          Back to cart
        </Link>

        <h1 className="text-2xl font-bold text-gray-900 mb-6">Checkout</h1>

        <div className="grid gap-6">
          {/* Fulfillment type */}
          <div className="bg-white rounded-xl border p-6">
            <h3 className="font-semibold text-gray-900 mb-4">How would you like to receive your order?</h3>
            <div className="grid grid-cols-2 gap-4">
              {shippingConfig?.offers_collection !== false && (
                <button
                  onClick={() => setFulfillment("collection")}
                  className={`p-4 rounded-xl border-2 text-center transition-colors ${
                    fulfillment === "collection"
                      ? "border-pink-500 bg-pink-50"
                      : "border-gray-200 hover:border-gray-300"
                  }`}
                >
                  <Store className={`w-6 h-6 mx-auto mb-2 ${fulfillment === "collection" ? "text-pink-600" : "text-gray-400"}`} />
                  <p className={`font-medium ${fulfillment === "collection" ? "text-pink-600" : "text-gray-700"}`}>
                    Collection
                  </p>
                  <p className="text-xs text-gray-400 mt-1">Free</p>
                </button>
              )}
              {shippingConfig?.offers_delivery && (
                <button
                  onClick={() => setFulfillment("delivery")}
                  className={`p-4 rounded-xl border-2 text-center transition-colors ${
                    fulfillment === "delivery"
                      ? "border-pink-500 bg-pink-50"
                      : "border-gray-200 hover:border-gray-300"
                  }`}
                >
                  <Truck className={`w-6 h-6 mx-auto mb-2 ${fulfillment === "delivery" ? "text-pink-600" : "text-gray-400"}`} />
                  <p className={`font-medium ${fulfillment === "delivery" ? "text-pink-600" : "text-gray-700"}`}>
                    Delivery
                  </p>
                  <p className="text-xs text-gray-400 mt-1">
                    {deliveryFee === 0 ? "Free" : `R${deliveryFee.toFixed(2)}`}
                  </p>
                </button>
              )}
            </div>
          </div>

          {/* Collection point or delivery address */}
          {fulfillment === "collection" && locations.length > 0 && (
            <div className="bg-white rounded-xl border p-6">
              <h3 className="font-semibold text-gray-900 mb-4">Collection Point</h3>
              <div className="space-y-3">
                {locations.map((loc) => (
                  <label
                    key={loc.id}
                    className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                      selectedLocation === loc.id ? "border-pink-500 bg-pink-50" : "border-gray-200 hover:bg-gray-50"
                    }`}
                  >
                    <input
                      type="radio"
                      name="location"
                      checked={selectedLocation === loc.id}
                      onChange={() => setSelectedLocation(loc.id)}
                      className="accent-pink-600"
                    />
                    <div>
                      <p className="font-medium text-gray-900">{loc.name}</p>
                      <p className="text-sm text-gray-500">
                        {loc.address_line1}, {loc.city}
                      </p>
                    </div>
                  </label>
                ))}
              </div>
            </div>
          )}

          {fulfillment === "delivery" && (
            <div className="bg-white rounded-xl border p-6">
              <h3 className="font-semibold text-gray-900 mb-4">Delivery Address</h3>
              {shippingConfig?.estimated_delivery_days != null && Number(shippingConfig.estimated_delivery_days) > 0 && (
                <p className="text-sm text-gray-500 mb-4">
                  Estimated delivery: within {Number(shippingConfig.estimated_delivery_days)} business day{Number(shippingConfig.estimated_delivery_days) !== 1 ? "s" : ""}
                </p>
              )}
              {addresses.length === 0 ? (
                <div className="text-center py-4">
                  <AlertCircle className="w-8 h-8 text-gray-300 mx-auto mb-2" />
                  <p className="text-gray-500 mb-3">No saved addresses</p>
                  <Link
                    href="/account-settings/addresses"
                    className="text-pink-600 font-medium hover:underline"
                  >
                    Add an address
                  </Link>
                </div>
              ) : (
                <div className="space-y-3">
                  {addresses.map((addr) => (
                    <label
                      key={addr.id}
                      className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                        selectedAddress === addr.id ? "border-pink-500 bg-pink-50" : "border-gray-200 hover:bg-gray-50"
                      }`}
                    >
                      <input
                        type="radio"
                        name="address"
                        checked={selectedAddress === addr.id}
                        onChange={() => setSelectedAddress(addr.id)}
                        className="accent-pink-600"
                      />
                      <div>
                        <p className="font-medium text-gray-900">{addr.label ?? "Address"}</p>
                        <p className="text-sm text-gray-500">
                          {addr.address_line1}, {addr.city}
                          {addr.postal_code ? `, ${addr.postal_code}` : ""}
                        </p>
                      </div>
                    </label>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* Payment method */}
          <div className="bg-white rounded-xl border p-6">
            <h3 className="font-semibold text-gray-900 mb-4">Payment Method</h3>
            {!paystackEnabled && (
              <p className="text-sm text-amber-700 bg-amber-50 border border-amber-200 rounded-lg p-3 mb-4">
                Online payment is currently unavailable. Please pay when you receive your order.
              </p>
            )}
            <div className="space-y-3">
              {paystackEnabled && (
                <label
                  className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                    paymentMethod === "paystack" ? "border-pink-500 bg-pink-50" : "border-gray-200 hover:bg-gray-50"
                  }`}
                >
                  <input
                    type="radio"
                    name="payment"
                    checked={paymentMethod === "paystack"}
                    onChange={() => setPaymentMethod("paystack")}
                    className="accent-pink-600"
                  />
                  <div>
                    <p className="font-medium text-gray-900">Pay Online</p>
                    <p className="text-xs text-gray-500">Secure payment via Paystack (card, EFT, etc.)</p>
                  </div>
                </label>
              )}
              {paymentMethod === "paystack" && user && walletBalance > 0 && walletEnabled && (
                <label className="flex items-center gap-3 p-3 rounded-lg border border-gray-200 bg-gray-50/50 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={useWallet}
                    onChange={(e) => setUseWallet(e.target.checked)}
                    className="accent-pink-600 rounded"
                  />
                  <span className="text-sm text-gray-700">
                    Use wallet balance ΓÇö R{Number(walletBalance).toFixed(2)} available
                  </span>
                </label>
              )}
              <label
                className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                  paymentMethod === "card_on_delivery" ? "border-pink-500 bg-pink-50" : "border-gray-200 hover:bg-gray-50"
                }`}
              >
                <input
                  type="radio"
                  name="payment"
                  checked={paymentMethod === "card_on_delivery"}
                  onChange={() => setPaymentMethod("card_on_delivery")}
                  className="accent-pink-600"
                />
                <div>
                  <p className="font-medium text-gray-900">
                    Pay at {fulfillment === "delivery" ? "Delivery" : "Collection"}
                  </p>
                  <p className="text-xs text-gray-500">Cash or card when you receive your order</p>
                </div>
              </label>
            </div>
            {paymentMethod === "paystack" && platformFeeConfig.show && platformFee > 0 && (
              <div className="mt-3 p-3 bg-amber-50 rounded-lg text-sm text-amber-800">
                A platform service fee of R{platformFee.toFixed(2)} applies to online payments
              </div>
            )}
          </div>

          {/* Order summary */}
          <div className="bg-white rounded-xl border p-6">
            <h3 className="font-semibold text-gray-900 mb-4">Order Summary</h3>
            <div className="space-y-3 mb-4">
              {items.map((item) => (
                <div key={item.id} className="flex justify-between text-sm">
                  <span className="text-gray-700">
                    {item.product?.name}
                    {item.product_variant?.option_values && Object.keys(item.product_variant.option_values).length > 0 && (
                      <span className="text-gray-500 font-normal"> ┬╖ {Object.entries(item.product_variant.option_values).map(([, v]) => v).join(", ")}</span>
                    )}{" "}
                    x{item.quantity}
                  </span>
                  <span className="font-medium text-gray-900">
                    R{linePrice(item).toFixed(2)}
                  </span>
                </div>
              ))}
            </div>
            <div className="border-t pt-3 space-y-2">
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Subtotal</span>
                <span className="text-gray-900">R{subtotal.toFixed(2)}</span>
              </div>
              {fulfillment === "delivery" && (
                <div className="flex justify-between text-sm">
                  <span className="text-gray-500">Delivery</span>
                  <span className={deliveryFee === 0 ? "text-green-600" : "text-gray-900"}>
                    {deliveryFee === 0 ? "Free" : `R${deliveryFee.toFixed(2)}`}
                  </span>
                </div>
              )}
              {platformFee > 0 && platformFeeConfig.show && (
                <div className="flex justify-between text-sm">
                  <span className="text-gray-500">Service Fee</span>
                  <span className="text-gray-900">R{platformFee.toFixed(2)}</span>
                </div>
              )}
              <div className="flex justify-between text-lg font-bold pt-2 border-t">
                <span className="text-gray-900">Total</span>
                <span className="text-pink-600">R{total.toFixed(2)}</span>
              </div>
            </div>
          </div>

          {/* Pay button */}
          <button
            onClick={handlePlaceOrder}
            disabled={placing}
            className="w-full py-4 bg-pink-600 text-white rounded-xl font-bold text-lg hover:bg-pink-700 transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
          >
            {placing ? (
              <>
                <Loader2 className="w-5 h-5 animate-spin" />
                Processing...
              </>
            ) : (
              `${paymentMethod === "paystack" ? "Pay &" : ""} Place Order ΓÇö R${total.toFixed(2)}`
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { CheckCircle, XCircle, Loader2, ShoppingBag } from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import Link from "next/link";

export default function ProductPaymentCallback() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const [status, setStatus] = useState<"loading" | "success" | "error">("loading");
  const [message, setMessage] = useState("");
  const [orderNumber, setOrderNumber] = useState("");

  useEffect(() => {
    const verifyPayment = async () => {
      const reference = searchParams.get("reference");
      if (!reference) {
        setStatus("error");
        setMessage("Payment reference not found");
        return;
      }

      try {
        const response = await fetcher.get<{
          data: {
            status: string;
            type?: string;
            productOrderId?: string;
            orderNumber?: string;
            message?: string;
          };
        }>(`/api/paystack/verify?reference=${reference}`);

        if (response.data.status === "success") {
          setStatus("success");
          setOrderNumber(response.data.orderNumber ?? "");
          setMessage("Payment successful! Your order has been confirmed.");

          setTimeout(() => {
            router.push("/account-settings/orders");
          }, 4000);
        } else {
          setStatus("error");
          setMessage(response.data.message || "Payment verification failed");
        }
      } catch (error: any) {
        setStatus("error");
        setMessage(error.message || "Payment verification failed");
      }
    };

    verifyPayment();
  }, [searchParams, router]);

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-lg p-8 max-w-md w-full text-center">
        {status === "loading" && (
          <>
            <Loader2 className="w-16 h-16 text-pink-500 animate-spin mx-auto mb-4" />
            <h2 className="text-xl font-bold text-gray-900 mb-2">Verifying Payment</h2>
            <p className="text-gray-500">Please wait while we confirm your payment...</p>
          </>
        )}

        {status === "success" && (
          <>
            <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <CheckCircle className="w-10 h-10 text-green-600" />
            </div>
            <h2 className="text-xl font-bold text-gray-900 mb-2">Payment Successful!</h2>
            {orderNumber && (
              <p className="text-lg font-semibold text-pink-600 mb-2">Order #{orderNumber}</p>
            )}
            <p className="text-gray-500 mb-6">{message}</p>
            <p className="text-sm text-gray-400 mb-4">Redirecting to your orders...</p>
            <Link
              href="/account-settings/orders"
              className="inline-flex items-center gap-2 px-6 py-3 bg-pink-600 text-white rounded-xl font-medium hover:bg-pink-700 transition-colors"
            >
              <ShoppingBag className="w-4 h-4" />
              View My Orders
            </Link>
          </>
        )}

        {status === "error" && (
          <>
            <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <XCircle className="w-10 h-10 text-red-600" />
            </div>
            <h2 className="text-xl font-bold text-gray-900 mb-2">Payment Failed</h2>
            <p className="text-gray-500 mb-6">{message}</p>
            <div className="flex gap-3 justify-center">
              <Link
                href="/shop"
                className="px-5 py-2.5 border border-gray-200 rounded-xl text-gray-700 font-medium hover:bg-gray-50"
              >
                Back to Shop
              </Link>
              <Link
                href="/account-settings/orders"
                className="px-5 py-2.5 bg-pink-600 text-white rounded-xl font-medium hover:bg-pink-700"
              >
                View Orders
              </Link>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import Image from "next/image";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { motion } from "framer-motion";
import { Users, Briefcase, ArrowRight, CreditCard, Globe } from "lucide-react";
import LoginModal from "@/components/global/login-modal";
import InlineSignupForm from "@/components/global/inline-signup-form";
import { fetcher } from "@/lib/http/fetcher";
import logo from "../../../public/images/logo.svg";

interface SignupPageContent {
  headline?: string;
  sub_heading?: string;
  provider_card_title?: string;
  provider_card_micro_copy?: string;
  provider_card_description?: string;
  provider_card_badge?: string;
  customer_card_title?: string;
  customer_card_description?: string;
  customer_card_sub_description?: string;
  testimonial_quote?: string;
  testimonial_attribution?: string;
  testimonial_pure_commerce?: string;
  testimonial_yoco_support?: string;
  background_image_url?: string;
  footer_text?: string;
}

export default function SignupPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [selectedPersona, setSelectedPersona] = useState<"customer" | "provider" | null>(null);
  const [content, setContent] = useState<SignupPageContent>({});
  const [_isLoadingContent, setIsLoadingContent] = useState(true);
  const [highlightedCard, setHighlightedCard] = useState<"customer" | "provider" | null>(null);

  // Determine which card to highlight and auto-select based on referrer or query parameter
  useEffect(() => {
    // Check query parameter first
    const type = searchParams.get("type");
    if (type === "provider" || type === "customer") {
      setHighlightedCard(type);
      // Auto-select persona if type is clear and not already selected
      if (selectedPersona !== type) {
        setSelectedPersona(type);
      }
      return;
    }

    // Check referrer as fallback
    if (typeof window !== "undefined") {
      const referrer = document.referrer;
      
      // Only check referrer if it exists and is from the same origin
      if (referrer) {
        try {
          const referrerUrl = new URL(referrer);
          const currentUrl = new URL(window.location.href);
          
          // Only use referrer if it's from the same origin
          if (referrerUrl.origin === currentUrl.origin) {
            const referrerPath = referrerUrl.pathname;

            // If coming from /become-a-partner, highlight provider card and auto-select
            if (referrerPath.includes("/become-a-partner")) {
              setHighlightedCard("provider");
              if (selectedPersona !== "provider") {
                setSelectedPersona("provider");
              }
              return;
            }
            // If coming from home page (main customer page), highlight customer card and auto-select
            else if (referrerPath === "/" || referrerPath === "") {
              setHighlightedCard("customer");
              if (selectedPersona !== "customer") {
                setSelectedPersona("customer");
              }
              return;
            }
          }
        } catch {
          // Invalid referrer URL, ignore
        }
      }
      
      // Default: no specific highlight (provider card is already styled as highlighted by default)
      setHighlightedCard(null);
    }
  }, [searchParams]);

  // Fetch content from CMS
  useEffect(() => {
    const loadContent = async () => {
      try {
        const response = await fetcher.get<{ data: SignupPageContent; error: null }>("/api/public/signup-content");
        setContent(response.data || {});
      } catch (error) {
        console.error("Error loading signup page content:", error);
        // Use defaults if API fails
        setContent({});
      } finally {
        setIsLoadingContent(false);
      }
    };
    loadContent();
  }, []);

  const handlePersonaSelect = (persona: "customer" | "provider") => {
    setSelectedPersona(persona);
    // Show signup form on the same page - no navigation or modal
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row overflow-hidden bg-[#FBFBFB]">
      {/* Mobile: Lifestyle Banner - First on mobile */}
      <div className="md:hidden w-full h-[35vh] relative overflow-hidden">
        <div
          className="absolute inset-0 bg-cover bg-center"
          style={{
            backgroundImage: `url('${content.background_image_url || "https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?q=80&w=2000&auto=format&fit=crop"}')`,
            filter: "grayscale(0.3)",
          }}
        >
          {/* Bottom-to-top gradient fade */}
          <div className="absolute inset-0 bg-gradient-to-t from-[#FBFBFB] via-[#FBFBFB]/50 to-transparent" />
        </div>
      </div>

      {/* Left Column - Functional (1fr) */}
      <div className="w-full md:w-[38.2%] bg-[#FBFBFB] flex flex-col">
        {/* Logo */}
        <div className="p-6 md:p-8">
          <Link href="/" className="inline-block">
            <Image src={logo} alt="Beautonomi Logo" className="h-8 w-auto" />
          </Link>
        </div>

        {/* Centered Selection Area */}
        <div className="flex-1 flex items-center justify-center px-6 md:px-12 pb-8">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, ease: "easeOut" }}
            className="w-full max-w-md"
          >
            {/* Headline */}
            <h1 className="font-black text-[#191C1F] text-4xl md:text-5xl lg:text-6xl tracking-tighter leading-[0.9] mb-4">
              {content.headline || "Elevate every encounter."}
            </h1>
            
            {/* Sub-heading */}
            <p className="font-medium text-lg text-gray-500 tracking-tight mb-8">
              {content.sub_heading || "Choose how you want to join Beautonomi"}
            </p>

            {/* Selection Cards - Only show if no persona selected */}
            {!selectedPersona && (
              <div className="space-y-4">
                {/* Render cards in order based on highlighted card */}
                {highlightedCard === "customer" ? (
                  <>
                    {/* For Customers Card - Show first when highlighted */}
                    <motion.button
                      onClick={() => handlePersonaSelect("customer")}
                      whileHover={{ y: -4 }}
                      whileTap={{ scale: 0.98 }}
                      className={`w-full rounded-[28px] p-6 text-left shadow-sm hover:shadow-md transition-all duration-300 group ${
                        highlightedCard === "customer"
                          ? "border-2 border-[#FF0077]/20 bg-white"
