"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { Loader2, MapPin } from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import { useAuth } from "@/providers/AuthProvider";

interface CityWaitlistModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  defaultCity?: string;
}

export default function CityWaitlistModal({
  open,
  onOpenChange,
  defaultCity = "",
}: CityWaitlistModalProps) {
  const { user } = useAuth();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formData, setFormData] = useState({
    city_name: defaultCity,
    name: user?.full_name || "",
    email: user?.email || "",
    phone: "",
    is_building_owner: false,
    building_address: "",
    notes: "",
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.city_name.trim()) {
      toast.error("Please enter a city name");
      return;
    }

    if (!formData.name.trim()) {
      toast.error("Please enter your name");
      return;
    }

    setIsSubmitting(true);
    try {
      const response = await fetcher.post<{ data?: { entry?: { message?: string } } }>("/api/public/city-waitlist", formData);
      
      toast.success(response?.data?.entry?.message || "Successfully joined the waitlist!");
      onOpenChange(false);
      
      // Reset form
      setFormData({
        city_name: defaultCity,
        name: user?.full_name || "",
        email: user?.email || "",
        phone: "",
        is_building_owner: false,
        building_address: "",
        notes: "",
      });
    } catch (error: any) {
      const errorMessage = error.message || "Failed to join waitlist. Please try again.";
      toast.error(errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <MapPin className="w-5 h-5" />
            Join City Waitlist
          </DialogTitle>
          <DialogDescription>
            We'll notify you when Beautonomi becomes available in your city.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="city_name">City Name *</Label>
            <Input
              id="city_name"
              value={formData.city_name}
              onChange={(e) => setFormData({ ...formData, city_name: e.target.value })}
              placeholder="e.g., New York, Los Angeles"
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="name">Your Name *</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              placeholder="Your full name"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                placeholder="your@email.com"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="phone">Phone</Label>
              <Input
                id="phone"
                type="tel"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                placeholder="+27 123 456 789"
              />
            </div>
          </div>

          <div className="flex items-center space-x-2">
            <Checkbox
              id="is_building_owner"
              checked={formData.is_building_owner}
              onCheckedChange={(checked) =>
                setFormData({ ...formData, is_building_owner: checked === true })
              }
            />
            <Label
              htmlFor="is_building_owner"
              className="text-sm font-normal leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
            >
              I'm a building owner interested in making my property Beautonomi-friendly
            </Label>
          </div>

          {formData.is_building_owner && (
            <div className="space-y-2">
              <Label htmlFor="building_address">Building Address</Label>
              <Input
                id="building_address"
                value={formData.building_address}
                onChange={(e) => setFormData({ ...formData, building_address: e.target.value })}
                placeholder="Street address, City, State"
              />
            </div>
          )}

          <div className="space-y-2">
            <Label htmlFor="notes">Additional Notes (Optional)</Label>
            <Textarea
              id="notes"
              value={formData.notes}
              onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
              placeholder="Tell us more about your interest..."
              rows={3}
            />
          </div>

          <div className="flex gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="flex-1"
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              className="flex-1 bg-[#FF0077] hover:bg-[#D60565]"
              disabled={isSubmitting || !formData.city_name.trim() || !formData.name.trim()}
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Joining...
                </>
              ) : (
                <>
                  <MapPin className="w-4 h-4 mr-2" />
                  Join Waitlist
                </>
              )}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";

export type CustomFieldDefinition = {
  id: string;
  name: string;
  label: string;
  field_type: string;
  entity_type: string;
  is_required: boolean;
  placeholder: string | null;
  help_text: string | null;
  default_value: string | null;
  display_order: number;
  validation_rules: Record<string, any> | null;
};

export interface CustomFieldsFormProps {
  entityType: "user" | "provider" | "booking" | "service";
  entityId?: string | null;
  /** When entityId is not set (e.g. creating a booking), pass initial values and get updates via onChange */
  initialValues?: Record<string, string | number | boolean | null>;
  onChange?: (values: Record<string, string | number | boolean | null>) => void;
  /** If true, show a "Save" button and save to API when entityId is set */
  showSaveButton?: boolean;
  /** Compact layout (e.g. inline in a card) */
  compact?: boolean;
}

export function CustomFieldsForm({
  entityType,
  entityId,
  initialValues = {},
  onChange,
  showSaveButton = true,
  compact = false,
}: CustomFieldsFormProps) {
  const [definitions, setDefinitions] = useState<CustomFieldDefinition[]>([]);
  const [values, setValues] = useState<Record<string, string | number | boolean | null>>({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const loadDefinitions = useCallback(async () => {
    try {
      const res = await fetcher.get<{ data: { definitions: CustomFieldDefinition[] } }>(
        `/api/custom-fields/definitions?entity_type=${entityType}`
      );
      const list = (res as { data?: { definitions?: CustomFieldDefinition[] } }).data?.definitions ?? [];
      setDefinitions(list);
      return list;
    } catch (e) {
      console.error("Failed to load custom field definitions:", e);
      setDefinitions([]);
      return [];
    }
  }, [entityType]);

  const loadValuesForDefinitions = useCallback(
    async (defs: CustomFieldDefinition[]) => {
      if (!entityId) return;
      try {
        const res = await fetcher.get<{ data: { values: Record<string, string> } }>(
          `/api/custom-fields/values?entity_type=${entityType}&entity_id=${entityId}`
        );
        const raw = (res as { data?: { values?: Record<string, string> } }).data?.values ?? {};
        const normalized: Record<string, string | number | boolean | null> = {};
        defs.forEach((f) => {
          const v = raw[f.name];
          if (v !== undefined) {
            if (f.field_type === "number") normalized[f.name] = Number(v) || 0;
            else if (f.field_type === "checkbox") normalized[f.name] = v === "true" || v === "1";
            else normalized[f.name] = v;
          } else if (f.default_value !== null && f.default_value !== undefined) {
            normalized[f.name] = f.default_value;
          } else {
            normalized[f.name] = f.field_type === "checkbox" ? false : "";
          }
        });
        setValues(normalized);
      } catch {
        setValues(initialValues);
      } finally {
        setLoading(false);
      }
    },
    [entityType, entityId, initialValues]
  );

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    loadDefinitions().then((list) => {
      if (cancelled) return;
      setDefinitions(list);
      if (entityId) {
        loadValuesForDefinitions(list);
      } else {
        const start: Record<string, string | number | boolean | null> = {};
        list.forEach((f) => {
          if (initialValues[f.name] !== undefined) {
            start[f.name] = initialValues[f.name];
          } else if (f.default_value !== null && f.default_value !== undefined) {
            start[f.name] = f.default_value;
          } else {
            start[f.name] = f.field_type === "checkbox" ? false : "";
          }
        });
        setValues(start);
        onChange?.(start);
        setLoading(false);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [entityType, entityId, loadDefinitions, loadValuesForDefinitions, initialValues]);

  const updateValue = (name: string, value: string | number | boolean | null) => {
    setValues((prev) => {
      const next = { ...prev, [name]: value };
      onChange?.(next);
      return next;
    });
  };

  const handleSave = async () => {
    if (!entityId) return;
    setSaving(true);
    try {
      await fetcher.put("/api/custom-fields/values", {
        entity_type: entityType,
        entity_id: entityId,
        values: values,
      });
      toast.success("Custom fields saved");
    } catch (err) {
      toast.error(err instanceof FetchError ? err.message : "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  if (loading && definitions.length === 0) {
    return null;
  }

  if (definitions.length === 0) {
    return null;
  }

  const optionsFromRules = (rules: Record<string, any> | null): string[] => {
    if (!rules) return [];
    const opts = rules.options;
    if (Array.isArray(opts)) return opts.map(String);
    if (typeof opts === "string") return opts.split(",").map((s) => s.trim());
    return [];
  };

  return (
    <div className={compact ? "space-y-3" : "space-y-4"}>
      {definitions.map((field) => (
        <div key={field.id} className={compact ? "space-y-1" : "space-y-2"}>
          <Label className={field.is_required ? "required" : ""}>
            {field.label}
            {field.is_required && " *"}
          </Label>
          {field.help_text && (
            <p className="text-xs text-muted-foreground">{field.help_text}</p>
          )}
          {field.field_type === "text" && (
            <Input
              value={String(values[field.name] ?? "")}
              onChange={(e) => updateValue(field.name, e.target.value)}
              placeholder={field.placeholder ?? undefined}
            />
          )}
          {field.field_type === "textarea" && (
            <Textarea
              value={String(values[field.name] ?? "")}
              onChange={(e) => updateValue(field.name, e.target.value)}
              placeholder={field.placeholder ?? undefined}
              rows={3}
            />
          )}
          {field.field_type === "number" && (
            <Input
              type="number"
              value={values[field.name] === undefined || values[field.name] === null ? "" : typeof values[field.name] === "boolean" ? String(values[field.name]) : (values[field.name] as string | number)}
              onChange={(e) =>
                updateValue(field.name, e.target.value === "" ? "" : Number(e.target.value))
              }
              placeholder={field.placeholder ?? undefined}
            />
          )}
          {field.field_type === "email" && (
            <Input
              type="email"
              value={String(values[field.name] ?? "")}
              onChange={(e) => updateValue(field.name, e.target.value)}
              placeholder={field.placeholder ?? undefined}
            />
          )}
          {field.field_type === "phone" && (
            <Input
              type="tel"
              value={String(values[field.name] ?? "")}
              onChange={(e) => updateValue(field.name, e.target.value)}
              placeholder={field.placeholder ?? undefined}
            />
          )}
          {field.field_type === "date" && (
            <Input
              type="date"
              value={String(values[field.name] ?? "")}
              onChange={(e) => updateValue(field.name, e.target.value)}
            />
          )}
          {field.field_type === "select" && (
            <Select
              value={String(values[field.name] ?? "")}
              onValueChange={(v) => updateValue(field.name, v)}
            >
              <SelectTrigger>
                <SelectValue placeholder={field.placeholder ?? "Select..."} />
              </SelectTrigger>
              <SelectContent>
                {optionsFromRules(field.validation_rules).map((opt) => (
                  <SelectItem key={opt} value={opt}>
                    {opt}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          )}
          {field.field_type === "checkbox" && (
            <div className="flex items-center gap-2">
              <Checkbox
                checked={Boolean(values[field.name])}
                onCheckedChange={(checked) =>
                  updateValue(field.name, checked === true)
                }
              />
              <span className="text-sm text-muted-foreground">
                {field.placeholder || field.help_text || "Yes"}
              </span>
            </div>
          )}
          {field.field_type === "radio" && (
            <RadioGroup
              value={String(values[field.name] ?? "")}
              onValueChange={(v) => updateValue(field.name, v)}
              className="flex flex-wrap gap-4"
            >
              {optionsFromRules(field.validation_rules).map((opt) => (
                <div key={opt} className="flex items-center gap-2" id={`${field.name}-${opt}`}>
                  <RadioGroupItem value={opt} id={`${field.name}-${opt}`} />
                  <Label htmlFor={`${field.name}-${opt}`} className="font-normal">
                    {opt}
                  </Label>
                </div>
              ))}
            </RadioGroup>
          )}
        </div>
      ))}
      {showSaveButton && entityId && (
        <button
          type="button"
          onClick={handleSave}
          disabled={saving}
          className="text-sm font-medium text-[#FF0077] hover:underline disabled:opacity-50"
        >
          {saving ? "Saving..." : "Save custom fields"}
        </button>
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  Bell,
  X,
  Calendar,
  DollarSign,
  Clock,
  CheckCircle2,
  MessageSquare,
  Package,
  Zap,
  Sparkles,
} from "lucide-react";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { fetcher } from "@/lib/http/fetcher";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { useAuth } from "@/providers/AuthProvider";

interface Notification {
  id: string;
  type: string;
  title: string;
  message: string;
  timestamp: string;
  link?: string;
  priority: 'low' | 'medium' | 'high';
  read: boolean;
  metadata?: Record<string, any>;
}

interface NotificationResponse {
  notifications: Notification[];
  total_unread: number;
}

const getNotificationIcon = (type: string) => {
  switch (type) {
    case 'new_message':
      return MessageSquare;
    case 'custom_offer':
      return Sparkles;
    case 'custom_request':
      return Package;
    case 'booking_confirmed':
    case 'booking_cancelled':
    case 'booking_rescheduled':
      return Calendar;
    case 'payment_received':
    case 'payment_failed':
    case 'refund_processed':
      return DollarSign;
    case 'appointment_reminder':
      return Clock;
    case 'account_verification':
      return CheckCircle2;
    case 'high_priority':
      return Zap;
    default:
      return Bell;
  }
};

const getPriorityColor = (priority: string) => {
  switch (priority) {
    case 'high':
      return 'text-red-600 bg-red-50 border-red-200';
    case 'medium':
      return 'text-yellow-600 bg-yellow-50 border-yellow-200';
    default:
      return 'text-blue-600 bg-blue-50 border-blue-200';
  }
};

const formatTimeAgo = (timestamp: string) => {
  const now = new Date();
  const time = new Date(timestamp);
  const diffInSeconds = Math.floor((now.getTime() - time.getTime()) / 1000);

  if (diffInSeconds < 60) return 'Just now';
  if (diffInSeconds < 3600) return `${Math.floor(diffInSeconds / 60)}m ago`;
  if (diffInSeconds < 86400) return `${Math.floor(diffInSeconds / 3600)}h ago`;
  if (diffInSeconds < 604800) return `${Math.floor(diffInSeconds / 86400)}d ago`;
  return time.toLocaleDateString();
};

export function CustomerNotificationsDropdown() {
  const [open, setOpen] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [totalUnread, setTotalUnread] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const router = useRouter();
  const { user } = useAuth();

  useEffect(() => {
    // Only fetch when user is authenticated (avoids 401 from API)
    if (!user?.id) {
      setIsLoading(false);
      setNotifications([]);
      setTotalUnread(0);
      return;
    }
    loadNotifications();

    // Refresh every 2 minutes
    const interval = setInterval(loadNotifications, 120000);

    // If popover is open, refresh more frequently (every 30 seconds)
    let fastInterval: NodeJS.Timeout | null = null;
    if (open) {
      fastInterval = setInterval(loadNotifications, 30000);
    }

    return () => {
      clearInterval(interval);
      if (fastInterval) clearInterval(fastInterval);
    };
  }, [open, user?.id]);

  const loadNotifications = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data?: NotificationResponse } & NotificationResponse>('/api/me/notifications');
      const data = response.data ?? response;
      setNotifications(data.notifications || []);
      setTotalUnread(data.total_unread || 0);
    } catch (error) {
      console.error('Failed to load notifications:', error);
      // Don't show error toast on initial load
      if (!isLoading) {
        toast.error('Failed to load notifications');
      }
      setNotifications([]);
      setTotalUnread(0);
    } finally {
      setIsLoading(false);
    }
  };

  const handleNotificationClick = async (notification: Notification) => {
    // Mark as read
    if (!notification.read) {
      try {
        await fetcher.post(`/api/me/notifications/${notification.id}/read`);
        setNotifications((prev) =>
          prev.map((n) =>
            n.id === notification.id ? { ...n, read: true } : n
          )
        );
        setTotalUnread((prev) => Math.max(0, prev - 1));
      } catch (error) {
        console.error('Failed to mark notification as read:', error);
      }
    }

    // Navigate if link exists
    if (notification.link) {
      setOpen(false);
      router.push(notification.link);
    } else if (notification.metadata?.conversation_id) {
      // Handle message notifications
      setOpen(false);
      router.push(`/account-settings/messages?conversation=${notification.metadata.conversation_id}`);
    } else if (notification.metadata?.request_id) {
      // Handle custom request/offer notifications
      setOpen(false);
      router.push('/account-settings/custom-requests');
    }
  };

  const handleMarkAllRead = async () => {
    try {
      await fetcher.post('/api/me/notifications/mark-all-read');
      setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
      setTotalUnread(0);
      toast.success('All notifications marked as read');
    } catch (error) {
      console.error('Failed to mark all as read:', error);
      toast.error('Failed to mark all as read');
    }
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className="relative min-h-[44px] min-w-[44px] touch-manipulation"
        >
          <Bell className="w-5 h-5" />
          {totalUnread > 0 && (
            <Badge
              variant="destructive"
              className="absolute -top-1 -right-1 h-5 min-w-5 px-1.5 flex items-center justify-center text-xs"
            >
              {totalUnread > 99 ? '99+' : totalUnread}
            </Badge>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-[95vw] sm:w-96 p-0 max-h-[85vh] overflow-hidden flex flex-col">
        <div className="flex items-center justify-between p-3 sm:p-4 border-b sticky top-0 bg-white z-10">
          <h3 className="font-semibold text-base sm:text-lg">Notifications</h3>
          <div className="flex items-center gap-2">
            {totalUnread > 0 && (
              <>
                <Badge variant="secondary" className="text-xs">
                  {totalUnread} new
                </Badge>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={handleMarkAllRead}
                  className="text-xs h-7 px-2 min-h-[28px] touch-manipulation"
                >
                  Mark all read
                </Button>
              </>
            )}
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setOpen(false)}
              className="h-7 w-7 min-h-[28px] min-w-[28px] touch-manipulation"
            >
              <X className="w-4 h-4" />
            </Button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto">
          {isLoading ? (
            <div className="p-8 text-center text-gray-500">
              <Clock className="w-8 h-8 mx-auto mb-2 animate-spin" />
              <p className="text-sm">Loading notifications...</p>
            </div>
          ) : notifications.length === 0 ? (
            <div className="p-8 text-center text-gray-500">
              <CheckCircle2 className="w-8 h-8 mx-auto mb-2 text-gray-400" />
              <p className="text-sm">No new notifications</p>
              <Link
                href="/account-settings/notifications"
                className="text-xs text-[#FF0077] hover:underline mt-2 inline-block"
                onClick={() => setOpen(false)}
              >
                Manage notifications
              </Link>
            </div>
          ) : (
            <div className="divide-y">
              {notifications.map((notification) => {
                const Icon = getNotificationIcon(notification.type);
                return (
                  <button
                    key={notification.id}
                    onClick={() => handleNotificationClick(notification)}
                    className={cn(
                      "w-full text-left p-3 sm:p-4 hover:bg-gray-50 transition-colors",
                      !notification.read && "bg-blue-50/50"
                    )}
                  >
                    <div className="flex items-start gap-3">
                      <div
                        className={cn(
                          "p-2 rounded-lg border flex-shrink-0",
                          getPriorityColor(notification.priority)
                        )}
                      >
                        <Icon className="w-4 h-4" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between gap-2 mb-1">
                          <p className={cn(
                            "font-medium text-sm text-gray-900",
                            !notification.read && "font-semibold"
                          )}>
                            {notification.title}
                          </p>
                          {!notification.read && (
                            <span className="w-2 h-2 bg-[#FF0077] rounded-full flex-shrink-0 mt-1.5" />
                          )}
                        </div>
                        <p className="text-sm text-gray-600 line-clamp-2 mb-1">
                          {notification.message}
                        </p>
                        <span className="text-xs text-gray-500">
                          {formatTimeAgo(notification.timestamp)}
                        </span>
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>
          )}
        </div>

        <div className="p-3 border-t bg-gray-50 sticky bottom-0">
          <Link
            href="/account-settings/notifications"
            className="text-sm text-[#FF0077] hover:underline text-center block"
            onClick={() => setOpen(false)}
          >
            View all notifications
          </Link>
        </div>
      </PopoverContent>
    </Popover>
  );
}

