"use client";

import React, { useState, useEffect } from "react";
import { useAuth } from "@/providers/AuthProvider";
import { AlertCircle, X, Mail } from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

/**
 * EmailVerificationBanner
 * 
 * Shows a banner when user's email is not verified.
 * Smart detection: Only shows if account is recent (created within 7 days) and email_confirmed_at is null.
 * This handles both cases:
 * - If verification is ENABLED: Shows until user verifies
 * - If verification is DISABLED: User can dismiss, won't show for old accounts
 */
export default function EmailVerificationBanner() {
  const { user, session, resendVerificationEmail } = useAuth();
  const [isDismissed, setIsDismissed] = useState(false);
  const [isResending, setIsResending] = useState(false);
  
  // Check if banner was dismissed in localStorage
  useEffect(() => {
    if (user?.id) {
      const dismissedKey = `email-verification-dismissed-${user.id}`;
      const wasDismissed = localStorage.getItem(dismissedKey) === 'true';
      setIsDismissed(wasDismissed);
    }
  }, [user?.id]);

  // Don't show if:
  // - No user
  // - No session (not logged in)
  // - User dismissed it
  if (!user || !session || isDismissed) {
    return null;
  }

  // Check email verification status from session
  const emailConfirmedAt = session.user.email_confirmed_at;
  if (emailConfirmedAt) {
    // Email is verified, don't show
    return null;
  }

  // Check if account is recent (created within last 7 days)
  // This helps distinguish between "verification required" vs "verification disabled"
  // If email verification is disabled in Supabase, email_confirmed_at will be null
  // but users can still log in, so we only show the banner for recent accounts
  const accountAge = user.created_at 
    ? (Date.now() - new Date(user.created_at).getTime()) / (1000 * 60 * 60 * 24) // days
    : Infinity;
  
  // Only show for accounts created within last 7 days
  // Older accounts likely have verification disabled or user already verified
  // If email verification is disabled in Supabase, this banner shouldn't show at all
  // because users can log in without verification
  if (accountAge > 7) {
    return null;
  }
  
  // Additional check: If user has a valid session but email_confirmed_at is null,
  // it likely means email verification is disabled in Supabase settings
  // In that case, don't show the banner (user can use the app without verification)
  // We can't directly check Supabase settings, but if user is logged in and can access the app,
  // verification is likely not required

  const handleResend = async () => {
    try {
      setIsResending(true);
      await resendVerificationEmail();
      toast.success("Verification email sent! Please check your inbox.");
    } catch (error: any) {
      toast.error(error.message || "Failed to send verification email. Please try again.");
    } finally {
      setIsResending(false);
    }
  };

  return (
    <div className="bg-amber-50 border-l-4 border-amber-400 p-4 mb-6 rounded-r-lg">
      <div className="flex items-start">
        <div className="flex-shrink-0">
          <AlertCircle className="h-5 w-5 text-amber-600" />
        </div>
        <div className="ml-3 flex-1">
          <div className="flex items-center justify-between">
            <div className="flex-1">
              <h3 className="text-sm font-medium text-amber-800">
                Verify your email address
              </h3>
              <div className="mt-2 text-sm text-amber-700">
                <p>
                  We've sent a verification email to <strong>{user.email}</strong>. 
                  Please check your inbox and click the verification link to activate your account.
                </p>
              </div>
              <div className="mt-3 flex flex-wrap gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleResend}
                  disabled={isResending}
                  className="bg-white hover:bg-amber-100 border-amber-300 text-amber-800"
                >
                  <Mail className="h-4 w-4 mr-2" />
                  {isResending ? "Sending..." : "Resend verification email"}
                </Button>
              </div>
            </div>
            <button
              onClick={() => {
                setIsDismissed(true);
                // Remember dismissal in localStorage
                if (user?.id) {
                  localStorage.setItem(`email-verification-dismissed-${user.id}`, 'true');
                }
              }}
              className="ml-4 flex-shrink-0 text-amber-600 hover:text-amber-800"
              aria-label="Dismiss"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState, useRef } from "react";
import { useAuth } from "@/providers/AuthProvider";
import { usePlatformSettings } from "@/providers/PlatformSettingsProvider";

/**
 * FaviconSpinner Component
 * 
 * Detects Fast Refresh events and authentication loading, showing a spinning favicon wheel.
 * This provides visual feedback during development hot reloads and auth checks.
 */
export default function FaviconSpinner() {
  const { isLoading: authLoading } = useAuth();
  const { branding } = usePlatformSettings();
  const [isFastRefreshRebuilding, setIsFastRefreshRebuilding] = useState(false);
  const shouldShowSpinner = authLoading || isFastRefreshRebuilding;
  
  const animationFrameIdRef = useRef<number | null>(null);
  const rotationRef = useRef(0);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const ctxRef = useRef<CanvasRenderingContext2D | null>(null);

  // Set up console interceptors once (only in development)
  useEffect(() => {
    if (process.env.NODE_ENV !== "development") {
      return;
    }

    const originalLog = console.log;
    const originalWarn = console.warn;
    const originalError = console.error;
    
    const checkFastRefresh = (message: string) => {
      if (message.includes("[Fast Refresh] rebuilding")) {
        setIsFastRefreshRebuilding(true);
      }
      if (message.includes("[Fast Refresh] done")) {
        setTimeout(() => {
          setIsFastRefreshRebuilding(false);
        }, 300);
      }
    };
    
    console.log = function(...args: any[]) {
      const message = args.join(" ");
      if (message.includes("[Fast Refresh]")) {
        checkFastRefresh(message);
      }
      originalLog.apply(console, args);
    };
    
    console.warn = function(...args: any[]) {
      const message = args.join(" ");
      if (message.includes("[Fast Refresh]")) {
        checkFastRefresh(message);
      }
      originalWarn.apply(console, args);
    };
    
    console.error = function(...args: any[]) {
      const message = args.join(" ");
      if (message.includes("[Fast Refresh]")) {
        checkFastRefresh(message);
      }
      originalError.apply(console, args);
    };

    return () => {
      console.log = originalLog;
      console.warn = originalWarn;
      console.error = originalError;
    };
  }, []);

  // Set up canvas once
  useEffect(() => {
    const canvas = document.createElement("canvas");
    canvas.width = 32;
    canvas.height = 32;
    const ctx = canvas.getContext("2d");
    if (ctx) {
      canvasRef.current = canvas;
      ctxRef.current = ctx;
    }
  }, []);

  // Animation effect
  useEffect(() => {
    if (!ctxRef.current || !canvasRef.current) return;

    const ctx = ctxRef.current;
    const canvas = canvasRef.current;

    // Function to draw spinning wheel on favicon
    const drawSpinner = () => {
      const centerX = 16;
      const centerY = 16;
      const radius = 14;
      const time = Date.now() / 50;
      
      ctx.clearRect(0, 0, 32, 32);
      
      // Draw background circle with gradient using platform colors
      const primaryColor = branding?.primary_color || "#FF0077";
      const secondaryColor = branding?.secondary_color || "#D60565";
      const gradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, radius);
      gradient.addColorStop(0, primaryColor);
      gradient.addColorStop(1, secondaryColor);
      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
      ctx.fill();
      
      // Draw spinning segments
      const segments = 12;
      const segmentAngle = (Math.PI * 2) / segments;
      
      for (let i = 0; i < segments; i++) {
        const angle = (i * segmentAngle) + rotationRef.current;
        const wave = Math.sin(angle * 2 + time * 0.1);
        const opacity = 0.4 + (wave + 1) / 2 * 0.6;
        
        ctx.save();
        ctx.translate(centerX, centerY);
        ctx.rotate(angle);
        ctx.fillStyle = `rgba(255, 255, 255, ${opacity})`;
        ctx.beginPath();
        const x = -1.5;
        const y = -11;
        const w = 3;
        const h = 4;
        const r = 1.5;
        ctx.moveTo(x + r, y);
        ctx.lineTo(x + w - r, y);
        ctx.quadraticCurveTo(x + w, y, x + w, y + r);
        ctx.lineTo(x + w, y + h - r);
        ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
        ctx.lineTo(x + r, y + h);
        ctx.quadraticCurveTo(x, y + h, x, y + h - r);
        ctx.lineTo(x, y + r);
        ctx.quadraticCurveTo(x, y, x + r, y);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
      }
      
      rotationRef.current += 0.15;
      if (rotationRef.current > Math.PI * 2) {
        rotationRef.current -= Math.PI * 2;
      }
    };

    // Function to update favicon
    const updateFavicon = () => {
      const link = document.querySelector("link[rel='icon']") as HTMLLinkElement;
      
      if (shouldShowSpinner) {
        drawSpinner();
        const dataUrl = canvas.toDataURL("image/png");
        
        if (link) {
          link.href = dataUrl;
        } else {
          const newLink = document.createElement("link");
          newLink.rel = "icon";
          newLink.href = dataUrl;
          document.head.appendChild(newLink);
        }
      } else {
        // Don't restore favicon here - let DynamicBranding handle it
        // This prevents conflicts and ensures the platform favicon is used
      }
    };

    // Animation loop
    const animate = () => {
      if (shouldShowSpinner) {
        updateFavicon();
        animationFrameIdRef.current = requestAnimationFrame(animate);
      } else {
        updateFavicon();
        if (animationFrameIdRef.current) {
          cancelAnimationFrame(animationFrameIdRef.current);
          animationFrameIdRef.current = null;
        }
      }
    };

    // Start or stop animation based on shouldShowSpinner
    if (shouldShowSpinner) {
      animate();
    } else {
      updateFavicon();
    }

    // Cleanup
    return () => {
      if (animationFrameIdRef.current) {
        cancelAnimationFrame(animationFrameIdRef.current);
        animationFrameIdRef.current = null;
      }
      // Don't restore favicon on cleanup - let DynamicBranding handle it
      // This ensures the platform favicon is properly restored
    };
  }, [shouldShowSpinner, branding]);

  return null;
}

"use client";
import React, { useState, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { FaApple, FaFacebook, FaGoogle } from "react-icons/fa6";
import { CiMail } from "react-icons/ci";
import { AlertCircle, Eye, EyeOff } from "lucide-react";
import { useAuth } from "@/providers/AuthProvider";
import { signIn as signInAuth, signUp as signUpAuth, signInWithOAuth, resendVerificationEmail } from "@/lib/supabase/auth";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";

interface InlineSignupFormProps {
  redirectContext?: "provider" | "customer";
  onAuthSuccess?: () => void;
  redirectUrl?: string;
  /** Referral code from signup?ref=CODE ΓÇö attached after signup for attribution */
  referralCode?: string;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function getPasswordStrength(pw: string): { score: number; label: string; color: string } {
  let score = 0;
  if (pw.length >= 8) score++;
  if (pw.length >= 12) score++;
  if (/[A-Z]/.test(pw)) score++;
  if (/[0-9]/.test(pw)) score++;
  if (/[^A-Za-z0-9]/.test(pw)) score++;
  if (score <= 1) return { score, label: "Weak", color: "bg-red-500" };
  if (score <= 2) return { score, label: "Fair", color: "bg-amber-500" };
  if (score <= 3) return { score, label: "Good", color: "bg-blue-500" };
  return { score, label: "Strong", color: "bg-green-500" };
}

export default function InlineSignupForm({ redirectContext, onAuthSuccess, redirectUrl, referralCode }: InlineSignupFormProps) {
  const router = useRouter();
  const { refreshUser, role: _contextRole, user } = useAuth();
  
  const [isLoading, setIsLoading] = useState(false);
  const [showEmailForm, setShowEmailForm] = useState(true);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [fullName, setFullName] = useState("");
  const [phone, setPhone] = useState("");
  const [countryCode, setCountryCode] = useState("+27");
  const [error, setError] = useState<string | null>(null);
  const [showPasswordField, setShowPasswordField] = useState(false);
  const [showResendVerification, setShowResendVerification] = useState(false);
  const [isResendingVerification, setIsResendingVerification] = useState(false);
  const [agreeTerms, setAgreeTerms] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  // Close form and call onAuthSuccess when user becomes authenticated
  useEffect(() => {
    if (user && onAuthSuccess) {
      setTimeout(() => {
        onAuthSuccess();
      }, 300);
    }
  }, [user, onAuthSuccess]);

  // After login/signup: attach referral if ref was stored (e.g. from email verification return)
  useEffect(() => {
    if (!user?.id || typeof window === "undefined") return;
    const storedRef = sessionStorage.getItem("referral_ref");
    if (!storedRef?.trim()) return;
    sessionStorage.removeItem("referral_ref");
    fetcher.post("/api/me/referrals/attach", { referral_code: storedRef.trim() }).catch(() => {});
  }, [user?.id]);

  const handleEmailContinue = () => {
    setError(null);
    if (!fullName?.trim()) {
      setError("Full name is required");
      return;
    }
    if (!email?.trim()) {
      setError("Email is required");
      return;
    }
    if (!EMAIL_RE.test(email.trim())) {
      setError("Please enter a valid email address");
      return;
    }
    setShowPasswordField(true);
  };

  const handleEmailAuth = async () => {
    setError(null);
    setShowResendVerification(false);

    const trimmedEmail = email.trim();
    const trimmedPassword = password.trim();

    if (!fullName?.trim()) {
      setError("Full name is required");
      return;
    }
    if (!trimmedEmail) {
      setError("Email is required");
      return;
    }
    if (!EMAIL_RE.test(trimmedEmail)) {
      setError("Please enter a valid email address");
      return;
    }
    if (!trimmedPassword) {
      setError("Password is required");
      return;
    }
    if (trimmedPassword.length < 8) {
      setError("Password must be at least 8 characters");
      return;
    }
    const strength = getPasswordStrength(trimmedPassword);
    if (strength.score < 2) {
      setError("Use a stronger password (add uppercase, numbers, or symbols)");
      return;
    }
    if (!agreeTerms) {
      setError("Please agree to the Terms of Service and Privacy Policy");
      return;
    }

    setIsLoading(true);
    setError(null);
    setShowResendVerification(false);

    if (referralCode?.trim() && typeof window !== "undefined") {
      sessionStorage.setItem("referral_ref", referralCode.trim());
    }

    try {

      const userRole = redirectContext === "provider" ? "provider_owner" : "customer";

      const signupResult = await signUpAuth({
        email: trimmedEmail,
        password: trimmedPassword,
        fullName: fullName?.trim(),
        phone: phone ? `${countryCode}${phone}` : undefined,
        role: userRole,
      });

      if (signupResult?.session) {
        toast.success("Account created successfully! Welcome to Beautonomi.");
        await refreshUser();
        if (referralCode?.trim()) {
          try {
            await fetcher.post("/api/me/referrals/attach", { referral_code: referralCode.trim() });
          } catch {
            // Non-blocking; attribution may already be set
          }
        }
        await new Promise(resolve => setTimeout(resolve, 300));
        
        if (onAuthSuccess) {
          onAuthSuccess();
          return;
        }
        
        if (redirectContext === "provider") {
          router.push("/provider/onboarding");
        } else if (redirectUrl) {
          router.push(redirectUrl);
        } else {
          // For customers, redirect to onboarding flow
          router.push("/onboarding");
        }
      } else if (signupResult?.user) {
        try {
          const loginResult = await signInAuth({ email: trimmedEmail, password: trimmedPassword });
          
          if (loginResult?.session) {
            toast.success("Account created successfully! Welcome to Beautonomi.");
            await refreshUser();
            if (referralCode?.trim()) {
              try {
                await fetcher.post("/api/me/referrals/attach", { referral_code: referralCode.trim() });
              } catch {
                // Non-blocking
              }
            }
            await new Promise(resolve => setTimeout(resolve, 300));
            
            if (onAuthSuccess) {
              onAuthSuccess();
              return;
            }
            
            if (redirectContext === "provider") {
              router.push("/provider/onboarding");
            } else if (redirectUrl) {
              router.push(redirectUrl);
            } else {
              // For customers, redirect to onboarding flow
              router.push("/onboarding");
            }
          } else {
            throw new Error("Email verification required");
          }
        } catch (loginError: any) {
          console.log("Auto-login after signup failed, email verification is required:", loginError);
          toast.success(
            "Account created! Please check your email to verify your account. You'll be able to log in after verification.",
            { duration: 6000 }
          );
          setShowResendVerification(true);
          setShowPasswordField(true);
        }
      } else {
        throw new Error("Failed to create account. Please try again.");
      }
    } catch (error: any) {
      console.error("Auth error:", error);
      const errorMessage = error.message || "Authentication failed. Please try again.";
      const lowerErrorMessage = errorMessage.toLowerCase();
      
      if (lowerErrorMessage.includes("email not confirmed") || 
          lowerErrorMessage.includes("email_not_confirmed") ||
          lowerErrorMessage.includes("verify your email")) {
        setError("Please verify your email address before logging in. Check your inbox for the verification email.");
        setShowResendVerification(true);
      } else if (lowerErrorMessage.includes("invalid login credentials") || 
                 lowerErrorMessage.includes("invalid credentials")) {
        setError("Invalid login credentials. Please check your email and password.");
        setShowResendVerification(true);
      } else {
        setError(errorMessage);
        if (lowerErrorMessage.includes("email")) {
          setShowResendVerification(true);
        } else {
          setShowResendVerification(false);
        }
      }
      toast.error(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleResendVerification = async () => {
    if (!email) {
      toast.error("Please enter your email address first");
      return;
    }

    setIsResendingVerification(true);
    try {
      await resendVerificationEmail(email.trim());
      toast.success("Verification email sent! Please check your inbox and spam folder.");
      setShowResendVerification(false);
    } catch (error: any) {
      console.error("Error resending verification email:", error);
      const errorMessage = error.message || "Failed to send verification email.";
      const lowerError = errorMessage.toLowerCase();
      if (lowerError.includes("user not found") || 
          lowerError.includes("email not found") ||
          lowerError.includes("no user found")) {
        toast.error("No account found with this email address. Please check your email or sign up.");
      } else if (lowerError.includes("already verified") || 
                 lowerError.includes("email already confirmed")) {
        toast.error("This email is already verified. Please check your password or try signing in again.");
        setShowResendVerification(false);
      } else {
        toast.error(errorMessage + " Please try again.");
      }
    } finally {
      setIsResendingVerification(false);
    }
  };

  const handlePhoneAuth = async () => {
    if (!phone) {
      setError("Phone number is required");
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      toast.info("Phone authentication coming soon. Please use email for now.");
      setShowEmailForm(true);
    } catch (error: any) {
      setError(error.message || "Phone authentication failed");
      toast.error(error.message || "Phone authentication failed");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSocialLogin = async (provider: "google" | "facebook" | "apple") => {
    setIsLoading(true);
    setError(null);

    try {
      const currentUrl = typeof window !== 'undefined' ? window.location.href : '';
      await signInWithOAuth(provider, currentUrl);
      toast.info(`Redirecting to ${provider}...`);
    } catch (error: any) {
      console.error("OAuth error:", error);
      setError(error.message || `Failed to sign in with ${provider}`);
      toast.error(error.message || `Failed to sign in with ${provider}`);
      setIsLoading(false);
    }
  };

  return (
    <div className="w-full">
      <h2 className="text-xl sm:text-2xl font-bold mb-6 sm:mb-8">Welcome to Beautonomi</h2>
      
      {/* Error Message */}
      {error && (
        <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg">
          <div className="flex items-start gap-2">
            <AlertCircle className="h-5 w-5 text-red-600 flex-shrink-0 mt-0.5" />
            <div className="flex-1">
              <p className="text-sm text-red-600">{error}</p>
              {showResendVerification && (
                <div className="mt-2">
                  <p className="text-xs text-gray-600 mb-1">
                    If you haven't verified your email yet:
                  </p>
                  <button
                    onClick={handleResendVerification}
                    disabled={isResendingVerification}
                    className="text-sm text-blue-600 underline hover:text-blue-800 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {isResendingVerification ? "Sending..." : "Resend verification email"}
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Phone Input (Default) */}
      {!showEmailForm && (
        <>
          <div className="mb-4">
            <div className="border border-gray-300 rounded-lg overflow-hidden">
              <div className="border-b border-gray-300 px-4 py-2 bg-gray-50">
                <Label className="text-xs font-medium text-gray-700">Country code</Label>
                <Select value={countryCode} onValueChange={setCountryCode}>
                  <SelectTrigger className="w-full border-none px-0 pt-1 text-base font-semibold bg-transparent h-auto">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="+27">South Africa (+27)</SelectItem>
                    <SelectItem value="+254">Kenya (+254)</SelectItem>
                    <SelectItem value="+233">Ghana (+233)</SelectItem>
                    <SelectItem value="+234">Nigeria (+234)</SelectItem>
                    <SelectItem value="+20">Egypt (+20)</SelectItem>
                    <SelectItem value="+1">USA (+1)</SelectItem>
                    <SelectItem value="+44">UK (+44)</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="px-4 py-3">
                <Input
                  type="tel"
                  className="text-base border-0 px-0 h-auto focus-visible:ring-0 focus-visible:ring-offset-0"
                  placeholder="Phone number"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  autoComplete="tel"
                  inputMode="tel"
                />
              </div>
            </div>
          </div>
          
          <p className="text-xs text-gray-600 mb-6">
            {"We'll"} call or text you to confirm your number. Standard message and data rates apply.{" "}
            <Link href="/privacy-policy" className="font-semibold underline hover:text-[#FF0077]">Privacy Policy</Link>
          </p>
          
          <Button 
            className="w-full bg-gradient-to-r from-[#FF0077] to-[#D60565] hover:from-[#E6006A] hover:to-[#C00555] text-white h-12 text-base font-medium mb-6"
            onClick={handlePhoneAuth}
            disabled={isLoading}
          >
            {isLoading ? "Processing..." : "Continue"}
          </Button>
        </>
      )}

      {/* Email Form */}
      {showEmailForm && (
        <>
          {/* Step 1: Email Input */}
          {!showPasswordField && (
            <>
              <div className="mb-4">
                <Label className="text-sm font-medium text-gray-700 mb-2 block">Full name</Label>
                <Input
                  type="text"
                  className="text-base h-12 border-gray-300"
                  placeholder="Full name"
                  value={fullName}
                  onChange={(e) => setFullName(e.target.value)}
                  autoComplete="name"
                />
              </div>
              <div className="mb-6">
                <Label className="text-sm font-medium text-gray-700 mb-2 block">Email</Label>
                <Input
                  type="email"
                  className="text-base h-12 border-gray-300"
                  placeholder="Email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  autoComplete="email"
                  inputMode="email"
                />
              </div>
              <Button 
                className="w-full bg-gradient-to-r from-[#FF0077] to-[#D60565] hover:from-[#E6006A] hover:to-[#C00555] text-white h-12 text-base font-medium mb-6"
                onClick={handleEmailContinue}
                disabled={isLoading || !email?.trim() || !fullName?.trim()}
              >
                Continue
              </Button>
              
              {/* Separator */}
              <div className="flex items-center my-6">
                <div className="flex-grow border-t border-gray-300"></div>
                <span className="flex-shrink mx-4 text-sm text-gray-600">or</span>
                <div className="flex-grow border-t border-gray-300"></div>
              </div>

              {/* Social Login Options */}
              <Button
                variant="outline"
                className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
                onClick={() => handleSocialLogin("google")}
                disabled={isLoading}
              >
                <FaGoogle className="text-lg" />
                <span>Continue with Google</span>
              </Button>
              
              <Button
                variant="outline"
                className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
                onClick={() => handleSocialLogin("apple")}
                disabled={isLoading}
              >
                <FaApple className="text-lg" />
                <span>Continue with Apple</span>
              </Button>
              
              <Button
                variant="outline"
                className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
                onClick={() => {
                  setShowEmailForm(false);
                  setError(null);
                }}
