                  className="mt-0.5"
                  aria-describedby="signup-terms-text"
                />
                <label htmlFor="signup-agree-terms" id="signup-terms-text" className="text-sm text-gray-600 cursor-pointer">
                  I agree to the{" "}
                  <Link href="/terms-and-condition" className="text-[#FF0077] font-medium underline hover:no-underline" target="_blank" rel="noopener noreferrer">
                    Terms of Service
                  </Link>{" "}
                  and{" "}
                  <Link href="/privacy-policy" className="text-[#FF0077] font-medium underline hover:no-underline" target="_blank" rel="noopener noreferrer">
                    Privacy Policy
                  </Link>
                </label>
              </div>
              <Button 
                className="w-full bg-gradient-to-r from-[#FF0077] to-[#D60565] hover:from-[#E6006A] hover:to-[#C00555] text-white h-12 text-base font-medium mb-4"
                onClick={handleEmailAuth}
                disabled={isLoading || !password || !agreeTerms}
              >
                {isLoading ? "Creating account..." : "Sign up"}
              </Button>
              <div className="text-center space-y-2">
                <button
                  onClick={() => {
                    setShowPasswordField(false);
                    setError(null);
                  }}
                  className="block w-full text-sm text-gray-600 hover:text-gray-900 underline"
                >
                  Back
                </button>
              </div>
            </>
          )}
        </>
      )}

      {/* Separator for phone form */}
      {!showEmailForm && (
        <div className="flex items-center my-6">
          <div className="flex-grow border-t border-gray-300"></div>
          <span className="flex-shrink mx-4 text-sm text-gray-600">or</span>
          <div className="flex-grow border-t border-gray-300"></div>
        </div>
      )}

      {/* Social Login Options for phone form */}
      {!showEmailForm && (
        <>
          <Button
            variant="outline"
            className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
            onClick={() => handleSocialLogin("google")}
            disabled={isLoading}
          >
            <FaGoogle className="text-lg" />
            <span>Continue with Google</span>
          </Button>
          
          <Button
            variant="outline"
            className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
            onClick={() => handleSocialLogin("apple")}
            disabled={isLoading}
          >
            <FaApple className="text-lg" />
            <span>Continue with Apple</span>
          </Button>
          
          <Button
            variant="outline"
            className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
            onClick={() => {
              setShowEmailForm(true);
              setError(null);
            }}
            disabled={isLoading}
          >
            <CiMail className="text-lg" />
            <span>Continue with email</span>
          </Button>
          
          <Button
            variant="outline"
            className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
            onClick={() => handleSocialLogin("facebook")}
            disabled={isLoading}
          >
            <FaFacebook className="text-lg text-blue-600" />
            <span>Continue with Facebook</span>
          </Button>
        </>
      )}
    </div>
  );
}

// components/global/LocationModal.tsx

import { useState, useEffect } from "react";
import { Input } from "@/components/ui/input"; // Assuming you have an Input component
import { Button } from "@/components/ui/button"; // Assuming you have a Button component
import { X } from "lucide-react";

interface LocationModalProps {
  showModal: boolean;
  closeModal: () => void;
  defaultValue?: string;
  onSave?: (value: string) => void;
}

export default function LocationModal({ showModal, closeModal, defaultValue = "", onSave }: LocationModalProps) {
  const [location, setLocation] = useState(defaultValue);
  const [searchResults, setSearchResults] = useState<string[]>([]);
  const [selectedLocation, setSelectedLocation] = useState<string>(defaultValue);

  useEffect(() => {
    queueMicrotask(() => {
      setLocation(defaultValue);
      setSelectedLocation(defaultValue);
    });
  }, [defaultValue, showModal]);

  // Perform the search when location changes using Mapbox
  useEffect(() => {
    if (location.trim().length < 3) {
      queueMicrotask(() => setSearchResults([]));
      return;
    }

    const fetchResults = async () => {
      try {
        const response = await fetch("/api/mapbox/geocode", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            query: location,
            limit: 5,
          }),
        });
        const data = await response.json();
        if (data.data) {
          setSearchResults(data.data.map((result: any) => result.place_name));
        } else {
          setSearchResults([]);
        }
      } catch (error) {
        console.error("Error fetching search results:", error);
        setSearchResults([]);
      }
    };

    const debounceTimer = setTimeout(fetchResults, 300);
    return () => clearTimeout(debounceTimer);
  }, [location]);

  return (
    showModal && (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
        <div className="bg-white rounded-lg p-6 max-w-lg w-full relative">
          <X className="h-5 w-5  cursor-pointer mb-7" onClick={closeModal} />
          <h2 className="text-[26px] font-medium text-secondary mb-8">Where you live?</h2>
          <div className="border rounded-full border-secondary mb-20 flex items-center">
            <Input
              type="text"
              placeholder="Search for your city"
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              className="rounded-full flex-grow"
            />
          </div>
          {searchResults.length > 0 && (
            <ul className="mt-4 border-t pt-2">
              {searchResults.map((result, index) => (
                <li 
                  key={index} 
                  className="py-1 px-2 hover:bg-gray-200 rounded cursor-pointer"
                  onClick={() => {
                    setSelectedLocation(result);
                    setLocation(result);
                    setSearchResults([]);
                  }}
                >
                  {result}
                </li>
              ))}
            </ul>
          )}
          <div className="mt-4 justify-end flex">
          <Button onClick={() => {
            if (onSave) {
              onSave(selectedLocation || location);
            }
            closeModal();
          }}>Save</Button>
        </div>
        </div>
      </div>
    )
  );
}

"use client";
import React, { useState, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { FaApple, FaFacebook, FaGoogle } from "react-icons/fa6";
import { CiMail } from "react-icons/ci";
import { X, AlertCircle, Eye, EyeOff } from "lucide-react";
import { useAuth } from "@/providers/AuthProvider";
import { signIn as signInAuth, signUp as signUpAuth, signInWithOAuth, resendVerificationEmail } from "@/lib/supabase/auth";
import { toast } from "sonner";


interface LoginModalProps {
  open: boolean;
  setOpen: (open: boolean) => void;
  initialMode?: "login" | "signup";
  redirectContext?: "provider" | "customer"; // Context for where signup was initiated
  onAuthSuccess?: () => void; // Callback when authentication succeeds
  redirectUrl?: string; // URL to redirect to after auth (for OAuth callbacks)
}

export default function LoginModal({ open, setOpen, initialMode, redirectContext, onAuthSuccess, redirectUrl }: LoginModalProps) {
  const router = useRouter();
  const { refreshUser, role: contextRole, user } = useAuth();

  // Close modal and call onAuthSuccess when user becomes authenticated
  useEffect(() => {
    if (user && open && onAuthSuccess) {
      // User just logged in, close modal and call callback
      setOpen(false);
      // Small delay to ensure state is updated
      setTimeout(() => {
        onAuthSuccess();
      }, 300);
    }
  }, [user, open, onAuthSuccess, setOpen]);
  const [isLoading, setIsLoading] = useState(false);
  const [showEmailForm, setShowEmailForm] = useState(false);
  const [isSignup, setIsSignup] = useState(initialMode === "signup");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [fullName, setFullName] = useState("");
  const [phone, setPhone] = useState("");
  const [countryCode, setCountryCode] = useState("+27");
  const [error, setError] = useState<string | null>(null);
  const [showPasswordField, setShowPasswordField] = useState(false);
  const [showResendVerification, setShowResendVerification] = useState(false);
  const [isResendingVerification, setIsResendingVerification] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  // Reset form when modal opens/closes
  useEffect(() => {
    if (open) {
      // If initialMode is provided (login or signup), show email form directly
      // Otherwise, show phone input first
      setShowEmailForm(initialMode === "login" || initialMode === "signup");
      setIsSignup(initialMode === "signup");
      // Don't show password field separately for login mode - we'll show it inline
      setShowPasswordField(false);
      setError(null);
      setEmail("");
      setPassword("");
      setFullName("");
      setPhone("");
      setShowResendVerification(false);
      setShowPassword(false);
    }
  }, [open, initialMode]);

  const handleEmailContinue = () => {
    if (!email) {
      setError("Email is required");
      return;
    }
    setShowPasswordField(true);
    setError(null);
  };

  const handleEmailAuth = async () => {
    // Clear any previous errors immediately
    setError(null);
    setShowResendVerification(false);

    if (!email || !password) {
      setError("Email and password are required");
      return;
    }

    // Trim email and password to avoid whitespace issues
    const trimmedEmail = email.trim();
    const trimmedPassword = password.trim();

    if (!trimmedEmail || !trimmedPassword) {
      setError("Email and password are required");
      return;
    }

    setIsLoading(true);
    // Ensure error is cleared before attempting login
    setError(null);
    setShowResendVerification(false);

    try {
      if (isSignup) {
        // Sign up new user
        if (!fullName) {
          setError("Full name is required");
          setIsLoading(false);
          return;
        }

        // Set role based on redirect context - if signing up from provider flow, set as provider_owner
        const userRole = redirectContext === "provider" ? "provider_owner" : "customer";

        const signupResult = await signUpAuth({
          email: trimmedEmail,
          password: trimmedPassword,
          fullName: fullName?.trim(),
          phone: phone ? `${countryCode}${phone}` : undefined,
          role: userRole,
        });

        // Check if we have a session (user is logged in)
        // If email verification is disabled, Supabase returns a session immediately
        // If email verification is enabled, session will be null until email is verified
        if (signupResult?.session) {
          // User is logged in (email verification disabled or already verified)
          toast.success("Account created successfully! Welcome to Beautonomi.");

          // Wait for auth state to update
          await refreshUser();

          // Small delay to ensure auth context is updated
          await new Promise(resolve => setTimeout(resolve, 300));

          setOpen(false);

          // Call onAuthSuccess callback if provided (e.g., continue booking)
          if (onAuthSuccess) {
            onAuthSuccess();
            return;
          }

          // Context-aware redirect: if signing up from provider flow, go to onboarding
          if (redirectContext === "provider") {
            router.push("/provider/onboarding");
          } else if (redirectUrl) {
            router.push(redirectUrl);
          } else {
            router.push("/account-settings");
          }
        } else if (signupResult?.user) {
          // User was created but no session - this means email verification is required
          // Try to sign in immediately as a fallback (in case verification is actually disabled)
          try {
            const loginResult = await signInAuth({ email: trimmedEmail, password: trimmedPassword });

            // Check if login actually created a session
            if (loginResult?.session) {
              toast.success("Account created successfully! Welcome to Beautonomi.");

              // Wait for auth state to update
              await refreshUser();

              // Small delay to ensure auth context is updated
              await new Promise(resolve => setTimeout(resolve, 300));

              setOpen(false);

              // Call onAuthSuccess callback if provided
              if (onAuthSuccess) {
                onAuthSuccess();
                return;
              }

              if (redirectContext === "provider") {
                router.push("/provider/onboarding");
              } else if (redirectUrl) {
                router.push(redirectUrl);
              } else {
                router.push("/account-settings");
              }
            } else {
              // Login didn't create a session - email verification is required
              throw new Error("Email verification required");
            }
          } catch (loginError: any) {
            // If login fails, email verification is required
            console.log("Auto-login after signup failed, email verification is required:", loginError);

            // Don't close modal or redirect - user needs to verify email first
            toast.success(
              "Account created! Please check your email to verify your account. You'll be able to log in after verification.",
              { duration: 6000 }
            );

            // Switch to login mode and show resend verification option
            setIsSignup(false);
            setShowResendVerification(true);
            setShowPasswordField(true);

            // Don't redirect - let user verify email first
            // The modal will stay open so they can resend verification if needed
          }
        } else {
          // Unexpected case - user wasn't created
          throw new Error("Failed to create account. Please try again.");
        }
      } else {
        // Sign in existing user
        await signInAuth({ email: trimmedEmail, password: trimmedPassword });

        // Clear any errors on successful sign in
        setError(null);
        setShowResendVerification(false);

        // Refresh user data to get updated role (this already includes role in the returned user)
        // Add timeout handling - if refreshUser times out, try to get role from session
        let updatedUser = await refreshUser();

        // If refreshUser timed out or returned null, wait a bit and try once more (max 2 retries)
        let retries = 0;
        while (!updatedUser && retries < 2) {
          // Wait a moment for auth state to settle
          await new Promise(resolve => setTimeout(resolve, 500));
          updatedUser = await refreshUser();
          retries++;
        }

        // Get role directly from updated user
        let userRole = updatedUser?.role;

        // If we still don't have a role after retries, wait a bit more for auth context to update
        if (!userRole) {
          // Wait for auth state change listener to update the context
          await new Promise(resolve => setTimeout(resolve, 500));
          // Try one more time
          updatedUser = await refreshUser();
          userRole = updatedUser?.role;
        }

        // Final role check
        const finalRole = userRole || contextRole;

        // Only close modal and redirect if we have a role
        if (finalRole) {
          // Clear any errors before closing
          setError(null);
          setShowResendVerification(false);
          toast.success("Logged in successfully!");
          setOpen(false);

          // Role-based redirect after login - immediate redirect
          // Use replace instead of push to avoid back button issues
          if (finalRole === "superadmin") {
            router.replace("/admin/dashboard");
          } else if (finalRole === "provider_owner" || finalRole === "provider_staff") {
            router.replace("/provider/dashboard");
          } else if (redirectUrl) {
            router.replace(redirectUrl);
          } else {
            // If redirectContext is provider, send customers to onboarding to become a provider
            if (redirectContext === "provider") {
              router.replace("/provider/onboarding");
            } else {
              router.replace("/");
            }
          }
        } else {
          // Role not loaded yet: if provider context, redirect to dashboard so RoleGuard can show loading
          if (redirectContext === "provider") {
            setError(null);
            setOpen(false);
            toast.success("Logged in successfully!");
            router.replace("/provider/dashboard");
          } else {
            const errorMsg = "Login successful, but unable to load user profile. Please refresh the page.";
            setError(errorMsg);
            toast.error(errorMsg);
          }
          setIsLoading(false);
        }
      }
    } catch (error: any) {
      console.error("Auth error:", error);
      const errorMessage = error.message || "Authentication failed. Please try again.";

      // Check for specific error types
      const lowerErrorMessage = errorMessage.toLowerCase();

      // Check if this is specifically an email verification issue
      if (lowerErrorMessage.includes("email not confirmed") || 
          lowerErrorMessage.includes("email_not_confirmed") ||
          lowerErrorMessage.includes("verify your email")) {
        setError("Please verify your email address before logging in. Check your inbox for the verification email.");
        setShowResendVerification(true);
      } 
      // Check if this is invalid credentials (could be wrong password OR unverified email)
      else if (lowerErrorMessage.includes("invalid login credentials") || 
               lowerErrorMessage.includes("invalid credentials")) {
        // Show clear error message
        setError("Invalid login credentials. Please check your email and password.");
        // Show resend verification as a secondary option (less prominent)
        // This helps users who might have unverified emails, but doesn't assume that's the issue
        setShowResendVerification(true);
      } 
      // Other errors
      else {
        setError(errorMessage);
        // Only show resend verification for email-related errors
        if (lowerErrorMessage.includes("email")) {
          setShowResendVerification(true);
        } else {
          setShowResendVerification(false);
        }
      }
      toast.error(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleResendVerification = async () => {
    if (!email) {
      toast.error("Please enter your email address first");
      return;
    }

    setIsResendingVerification(true);
    try {
      await resendVerificationEmail(email.trim());
      toast.success("Verification email sent! Please check your inbox and spam folder.");
      setShowResendVerification(false);
    } catch (error: any) {
      console.error("Error resending verification email:", error);
      const errorMessage = error.message || "Failed to send verification email.";

      // Check if the error indicates the email doesn't need verification or doesn't exist
      const lowerError = errorMessage.toLowerCase();
      if (lowerError.includes("user not found") || 
          lowerError.includes("email not found") ||
          lowerError.includes("no user found")) {
        toast.error("No account found with this email address. Please check your email or sign up.");
      } else if (lowerError.includes("already verified") || 
                 lowerError.includes("email already confirmed")) {
        toast.error("This email is already verified. Please check your password or try signing in again.");
        setShowResendVerification(false);
      } else {
        toast.error(errorMessage + " Please try again.");
      }
    } finally {
      setIsResendingVerification(false);
    }
  };

  const handleEmailButtonClick = () => {
    setShowEmailForm(true);
    // Default to login unless initialMode is explicitly signup
    setIsSignup(initialMode === "signup");
    setError(null);
  };

  const handlePhoneAuth = async () => {
    if (!phone) {
      setError("Phone number is required");
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const _fullPhone = `${countryCode}${phone}`;
      // For phone auth, we'll use email/password flow with phone as identifier
      // In production, you'd implement proper phone OTP flow
      toast.info("Phone authentication coming soon. Please use email for now.");
      setShowEmailForm(true);
    } catch (error: any) {
      setError(error.message || "Phone authentication failed");
      toast.error(error.message || "Phone authentication failed");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSocialLogin = async (provider: "google" | "facebook" | "apple") => {
    setIsLoading(true);
    setError(null);

    try {
      // Callback must be /auth/callback so the code can be exchanged. Add next= for post-login redirect.
      const origin = typeof window !== "undefined" ? window.location.origin : "";
      const callbackUrl =
        redirectContext === "provider"
          ? `${origin}/auth/callback?next=/provider/dashboard`
          : `${origin}/auth/callback`;
      await signInWithOAuth(provider, callbackUrl);
      // OAuth will redirect, so we don't need to do anything else here
      toast.info(`Redirecting to ${provider}...`);
    } catch (error: any) {
      console.error("OAuth error:", error);
      setError(error.message || `Failed to sign in with ${provider}`);
      toast.error(error.message || `Failed to sign in with ${provider}`);
      setIsLoading(false);
    }
  };
  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="w-full max-w-[95vw] sm:max-w-[575px] m-0 sm:m-4 p-0 z-[9999] overflow-auto max-h-[90vh] sm:max-h-[80vh] rounded-none sm:rounded-lg bg-white">
        <DialogHeader className="border-b border-gray-300 px-4 sm:px-6 py-3 sm:py-4 relative">
          <button
            onClick={() => setOpen(false)}
            className="absolute left-3 sm:left-4 top-3 sm:top-4 text-gray-500 hover:text-gray-700 p-1 touch-manipulation"
            aria-label="Close"
          >
            <X className="h-5 w-5" />
          </button>
          <DialogTitle className="text-center text-base sm:text-lg font-semibold">
            Log in or sign up
          </DialogTitle>
          <DialogDescription className="sr-only">
            Log in or create a new Beautonomi account to access all features
          </DialogDescription>
        </DialogHeader>
        <div className="mt-4 sm:mt-6 px-4 sm:px-6 pb-4 sm:pb-6">
          <h2 className="text-xl sm:text-2xl font-bold mb-6 sm:mb-8">Welcome to Beautonomi</h2>

          {/* Error Message */}
          {error && (
            <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg">
              <div className="flex items-start gap-2">
                <AlertCircle className="h-5 w-5 text-red-600 flex-shrink-0 mt-0.5" />
                <div className="flex-1">
                  <p className="text-sm text-red-600">{error}</p>
                  {showResendVerification && (
                    <div className="mt-2">
                      <p className="text-xs text-gray-600 mb-1">
                        If you haven't verified your email yet:
                      </p>
                      <button
                        onClick={handleResendVerification}
                        disabled={isResendingVerification}
                        className="text-sm text-blue-600 underline hover:text-blue-800 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        {isResendingVerification ? "Sending..." : "Resend verification email"}
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* Phone Input (Default) */}
          {!showEmailForm && (
            <>
              {/* Country Code and Phone Number - Integrated Design */}
              <div className="mb-4">
                <div className="border border-gray-300 rounded-lg overflow-hidden">
                  <div className="border-b border-gray-300 px-4 py-2 bg-gray-50">
                    <Label className="text-xs font-medium text-gray-700">Country code</Label>
                    <Select value={countryCode} onValueChange={setCountryCode}>
                      <SelectTrigger className="w-full border-none px-0 pt-1 text-base font-semibold bg-transparent h-auto">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="+27">South Africa (+27)</SelectItem>
                        <SelectItem value="+254">Kenya (+254)</SelectItem>
                        <SelectItem value="+233">Ghana (+233)</SelectItem>
                        <SelectItem value="+234">Nigeria (+234)</SelectItem>
                        <SelectItem value="+20">Egypt (+20)</SelectItem>
                        <SelectItem value="+1">USA (+1)</SelectItem>
                        <SelectItem value="+44">UK (+44)</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="px-4 py-3">
                    <Input
                      type="tel"
                      className="text-base border-0 px-0 h-auto focus-visible:ring-0 focus-visible:ring-offset-0"
                      placeholder="Phone number"
                      value={phone}
                      onChange={(e) => setPhone(e.target.value)}
                      autoComplete="tel"
                      inputMode="tel"
                    />
                  </div>
                </div>
              </div>

              <p className="text-xs text-gray-600 mb-6">
                {"We'll"} call or text you to confirm your number. Standard message and data rates apply.{" "}
                <span className="font-semibold underline cursor-pointer hover:text-gray-900">Privacy Policy</span>
              </p>

              <Button 
                className="w-full bg-gradient-to-r from-[#FF0077] to-[#D60565] hover:from-[#E6006A] hover:to-[#C00555] text-white h-12 text-base font-medium mb-6"
                onClick={handlePhoneAuth}
                disabled={isLoading}
              >
                {isLoading ? "Processing..." : "Continue"}
              </Button>
            </>
          )}

          {/* Email Form (shown when "Continue with email" is clicked) */}
          {showEmailForm && (
            <>
              {/* Step 1: Email Input (or both email and password for login mode) */}
              {!showPasswordField && (
                <>
                  {isSignup && (
                    <div className="mb-4">
                      <Label className="text-sm font-medium text-gray-700 mb-2 block">Full name</Label>
                      <Input
                        type="text"
                        className="text-base h-12 border-gray-300"
                        placeholder="Full name"
                        value={fullName}
                        onChange={(e) => setFullName(e.target.value)}
                        onKeyDown={(e) => {
                          if (e.key === "Enter" && fullName && email && !isLoading) {
                            handleEmailContinue();
                          }
                        }}
                        autoComplete="name"
                        autoFocus
                      />
                    </div>
                  )}
                  <div className="mb-4">
                    <Label className="text-sm font-medium text-gray-700 mb-2 block">Email</Label>
                    <Input
                      type="email"
                      className="text-base h-12 border-gray-300"
                      placeholder="Email"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" && email && !isLoading) {
                          if (initialMode === "login") {
                            // In login mode, focus password field if it exists, otherwise continue
                            const passwordInput = document.querySelector('input[type="password"], input[type="text"][placeholder="Password"]') as HTMLInputElement;
                            if (passwordInput) {
                              passwordInput.focus();
                            } else {
                              handleEmailContinue();
                            }
                          } else {
                            handleEmailContinue();
                          }
                        }
                      }}
                      autoComplete={isSignup ? "email" : "username"}
                      inputMode="email"
                      autoFocus={!isSignup}
                    />
                  </div>
                  {/* Show password field immediately in login mode (when not signup) */}
                  {!isSignup && (
                    <div className="mb-6">
                      <Label className="text-sm font-medium text-gray-700 mb-2 block">Password</Label>
                      <div className="relative">
                        <Input
                          type={showPassword ? "text" : "password"}
                          className="text-base h-12 border-gray-300 pr-10"
                          placeholder="Password"
                          value={password}
                          onChange={(e) => {
                            setPassword(e.target.value);
                            if (error) {
                              setError(null);
                              setShowResendVerification(false);
                            }
                          }}
                          onKeyDown={(e) => {
                            if (e.key === "Enter" && email && password && !isLoading) {
                              handleEmailAuth();
                            }
                          }}
                          autoComplete="current-password"
                        />
                        <button
                          type="button"
                          onClick={() => setShowPassword(!showPassword)}
                          className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#FF0077] rounded p-1"
                          aria-label={showPassword ? "Hide password" : "Show password"}
                          tabIndex={0}
                        >
                          {showPassword ? (
                            <EyeOff className="h-5 w-5" />
                          ) : (
                            <Eye className="h-5 w-5" />
                          )}
                        </button>
                      </div>
                    </div>
                  )}
                  {!isSignup && (
                    <div className="mb-4 text-center">
                      <Link
                        href="/forgot-password"
                        onClick={() => setOpen(false)}
                        className="text-sm text-gray-600 hover:text-[#FF0077]"
                      >
                        Forgot your password? <span className="font-semibold text-[#FF0077]">Reset it</span>
                      </Link>
                    </div>
                  )}
                  <Button 
                    className="w-full bg-gradient-to-r from-[#FF0077] to-[#D60565] hover:from-[#E6006A] hover:to-[#C00555] text-white h-12 text-base font-medium mb-6"
                    onClick={!isSignup ? handleEmailAuth : handleEmailContinue}
                    disabled={isLoading || !email || (!isSignup && !password)}
                  >
                    {!isSignup ? (isLoading ? "Logging in..." : "Log in") : "Continue"}
                  </Button>

                  {/* Separator */}
                  <div className="flex items-center my-6">
                    <div className="flex-grow border-t border-gray-300"></div>
                    <span className="flex-shrink mx-4 text-sm text-gray-600">or</span>
                    <div className="flex-grow border-t border-gray-300"></div>
                  </div>

                  {/* Social Login Options */}
                  <Button
                    variant="outline"
                    className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
                    onClick={() => handleSocialLogin("google")}
                    disabled={isLoading}
                  >
                    <FaGoogle className="text-lg" />
                    <span>Continue with Google</span>
                  </Button>

                  <Button
                    variant="outline"
                    className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
                    onClick={() => handleSocialLogin("apple")}
                    disabled={isLoading}
                  >
                    <FaApple className="text-lg" />
                    <span>Continue with Apple</span>
                  </Button>

                  <Button
                    variant="outline"
                    className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
                    onClick={() => {
                      setShowEmailForm(false);
                      setError(null);
                    }}
                    disabled={isLoading}
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" />
                    </svg>
                    <span>Continue with Phone</span>
                  </Button>

                  <Button
                    variant="outline"
                    className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
                    onClick={() => handleSocialLogin("facebook")}
                    disabled={isLoading}
                  >
                    <FaFacebook className="text-lg text-blue-600" />
                    <span>Continue with Facebook</span>
                  </Button>

                  {/* Need help link */}
                  <div className="text-center mt-6">
                    <button
                      onClick={() => {
                        window.open("/help", "_blank");
                      }}
                      className="text-sm text-gray-600 hover:text-gray-900 underline"
                    >
                      Need help?
                    </button>
                  </div>
                </>
              )}

              {/* Step 2: Password Input (after email is entered) */}
              {showPasswordField && (
                <>
                  <div className="mb-4">
                    <Label className="text-sm font-medium text-gray-700 mb-2 block">Password</Label>
                    <div className="relative">
                      <Input
                        type={showPassword ? "text" : "password"}
                        className="text-base h-12 border-gray-300 pr-10"
                        placeholder="Password"
                        value={password}
                        onChange={(e) => {
                          setPassword(e.target.value);
                          // Clear error when user starts typing
                          if (error) {
                            setError(null);
                            setShowResendVerification(false);
                          }
                        }}
                        onKeyDown={(e) => {
                          if (e.key === "Enter" && email && password && !isLoading) {
                            handleEmailAuth();
                          }
                        }}
                        autoComplete={isSignup ? "new-password" : "current-password"}
                        autoFocus={showPasswordField}
                      />
                      <button
                        type="button"
                        onClick={() => setShowPassword(!showPassword)}
                        className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#FF0077] rounded p-1"
                        aria-label={showPassword ? "Hide password" : "Show password"}
                        tabIndex={0}
                      >
                        {showPassword ? (
                          <EyeOff className="h-5 w-5" />
                        ) : (
                          <Eye className="h-5 w-5" />
                        )}
                      </button>
                    </div>
                  </div>
                  <Button 
                    className="w-full bg-gradient-to-r from-[#FF0077] to-[#D60565] hover:from-[#E6006A] hover:to-[#C00555] text-white h-12 text-base font-medium mb-4"
                    onClick={handleEmailAuth}
                    disabled={isLoading || !password}
                  >
                    {isLoading 
                      ? (isSignup ? "Creating account..." : "Logging in...") 
                      : (isSignup ? "Sign up" : "Log in")
                    }
                  </Button>
                  <div className="text-center space-y-2">
                    {!isSignup && (
                      <Link
                        href="/forgot-password"
                        onClick={() => setOpen(false)}
                        className="block w-full text-sm text-[#FF0077] hover:underline font-medium"
                      >
                        Forgot your password?
                      </Link>
                    )}
                    <button
                      onClick={() => {
                        setShowPasswordField(false);
                        setError(null);
                      }}
                      className="block w-full text-sm text-gray-600 hover:text-gray-900 underline"
                    >
                      Back
                    </button>
                    <button
                      onClick={() => {
                        setIsSignup(!isSignup);
                        setError(null);
                      }}
                      className="block w-full text-sm text-gray-600 hover:text-gray-900 hover:underline"
                    >
                      {isSignup ? "Already have an account? Log in" : "Don't have an account? Sign up"}
                    </button>
                  </div>
                </>
              )}
            </>
          )}

          {/* Separator */}
          {!showEmailForm && (
            <div className="flex items-center my-6">
              <div className="flex-grow border-t border-gray-300"></div>
              <span className="flex-shrink mx-4 text-sm text-gray-600">or</span>
              <div className="flex-grow border-t border-gray-300"></div>
            </div>
          )}

          {/* Social Login Options */}
          {!showEmailForm && (
            <>
              <Button
                variant="outline"
                className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
                onClick={() => handleSocialLogin("google")}
                disabled={isLoading}
              >
                <FaGoogle className="text-lg" />
                <span>Continue with Google</span>
              </Button>

              <Button
                variant="outline"
                className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
                onClick={() => handleSocialLogin("apple")}
                disabled={isLoading}
              >
                <FaApple className="text-lg" />
                <span>Continue with Apple</span>
              </Button>

              <Button
                variant="outline"
                className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
                onClick={handleEmailButtonClick}
                disabled={isLoading}
              >
                <CiMail className="text-lg" />
                <span>Continue with email</span>
              </Button>

              <Button
                variant="outline"
                className="w-full mb-3 flex items-center justify-start gap-3 px-4 h-12 hover:bg-gray-50 border-gray-300 text-base"
                onClick={() => handleSocialLogin("facebook")}
                disabled={isLoading}
              >
                <FaFacebook className="text-lg text-blue-600" />
                <span>Continue with Facebook</span>
              </Button>
            </>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Star, X, Smartphone, ExternalLink } from "lucide-react";
import Image from "next/image";
import { fetcher } from "@/lib/http/fetcher";
import GooglePlayStore from '../../../public/images/playstore-svgrepo-com.svg';
import Apple from '../../../public/images/apple-173-svgrepo-com.svg';

interface RateUsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

interface AppStoreInfo {
  name: string;
  icon: any;
  url: string;
  buttonText: string;
  platform: 'ios' | 'android' | 'huawei';
}

export default function RateUsModal({ isOpen, onClose }: RateUsModalProps) {
  const [_platform, setPlatform] = useState<'ios' | 'android' | 'huawei' | null>(null);
  const [appStoreInfo, setAppStoreInfo] = useState<AppStoreInfo | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [availableStores, setAvailableStores] = useState<AppStoreInfo[]>([]);

  useEffect(() => {
    if (typeof window !== 'undefined' && isOpen) {
      // Detect platform
      const userAgent = window.navigator.userAgent.toLowerCase();
      let detectedPlatform: 'ios' | 'android' | 'huawei' | null = null;

      if (userAgent.includes('iphone') || userAgent.includes('ipad')) {
        detectedPlatform = 'ios';
      } else if (userAgent.includes('huawei') || userAgent.includes('honor')) {
        detectedPlatform = 'huawei';
      } else if (userAgent.includes('android')) {
        detectedPlatform = 'android';
      }

      setPlatform(detectedPlatform);
      loadAppStoreUrls(detectedPlatform);
    }
  }, [isOpen]);

  const loadAppStoreUrls = async (detectedPlatform: 'ios' | 'android' | 'huawei' | null) => {
    try {
      setIsLoading(true);

      // Fetch app store URLs from API
      // Use try-catch to handle errors gracefully without throwing
      let apps: any = null;
      try {
        const response = await fetcher.get<{ data: any }>('/api/public/apps?type=customer');
        apps = response.data;
      } catch (fetchError) {
        // Silently fall back to defaults if API fails
        console.warn('Could not fetch app settings, using defaults:', fetchError);
        apps = null; // Will trigger fallback logic below
      }

      // If no apps data, use fallback defaults
      if (!apps) {
        apps = {
          ios: {
            enabled: true,
            app_store_url: 'https://apps.apple.com/app/beautonomi-customer',
          },
          android: {
            enabled: true,
            package_name: 'com.beautonomi.customer',
            download_url: 'https://play.google.com/store/apps/details?id=com.beautonomi.customer',
          },
          huawei: {
            enabled: false,
          },
        };
      }

      const stores: AppStoreInfo[] = [];

      // iOS App Store
      if (apps?.ios?.enabled && apps.ios.app_store_url) {
        stores.push({
          name: 'App Store',
          icon: Apple,
          url: apps.ios.app_store_url,
          buttonText: 'Rate on App Store',
          platform: 'ios'
        });
      }

      // Google Play Store
      if (apps?.android?.enabled) {
        // For ratings, we need Play Store URL format
        // If download_url is already a Play Store URL, use it; otherwise construct from package_name
        let playStoreUrl = apps.android.download_url;

        if (!playStoreUrl || !playStoreUrl.includes('play.google.com')) {
          // Construct Play Store rating URL from package_name
          const packageName = apps.android.package_name || 'com.beautonomi';
          playStoreUrl = `https://play.google.com/store/apps/details?id=${packageName}`;
        }

        stores.push({
          name: 'Google Play Store',
          icon: GooglePlayStore,
          url: playStoreUrl,
          buttonText: 'Rate on Google Play',
          platform: 'android'
        });
      }

      // Huawei AppGallery
      if (apps?.huawei?.enabled && apps.huawei.app_gallery_url) {
        stores.push({
          name: 'Huawei AppGallery',
          icon: Smartphone, // Use Smartphone icon as fallback for Huawei
          url: apps.huawei.app_gallery_url,
          buttonText: 'Rate on AppGallery',
          platform: 'huawei'
        });
      }

      setAvailableStores(stores);

      // Set the store info based on detected platform, or default to first available
      if (detectedPlatform) {
        const platformStore = stores.find(s => s.platform === detectedPlatform);
        if (platformStore) {
          setAppStoreInfo(platformStore);
        } else if (stores.length > 0) {
          setAppStoreInfo(stores[0]);
        }
      } else if (stores.length > 0) {
        setAppStoreInfo(stores[0]);
      }

    } catch {
      // Silent fallback - don't log errors to console as they're expected in some cases
      // Fallback to default URLs
      const fallbackStore: AppStoreInfo = detectedPlatform === 'ios' 
        ? {
            name: 'App Store',
            icon: Apple,
            url: 'https://apps.apple.com/app/beautonomi-customer',
            buttonText: 'Rate on App Store',
            platform: 'ios'
          }
        : {
            name: 'Google Play Store',
            icon: GooglePlayStore,
            url: 'https://play.google.com/store/apps/details?id=com.beautonomi.customer',
            buttonText: 'Rate on Google Play',
            platform: 'android'
          };
      setAppStoreInfo(fallbackStore);
      setAvailableStores([fallbackStore]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleRate = () => {
    if (appStoreInfo) {
      window.open(appStoreInfo.url, '_blank', 'noopener,noreferrer');
      onClose();
    }
  };

  const handleStoreSelect = (store: AppStoreInfo) => {
    setAppStoreInfo(store);
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="w-full max-w-[95vw] sm:max-w-lg z-[9999] p-0 border-0 bg-transparent shadow-none">
        <motion.div
          initial={{ opacity: 0, scale: 0.95, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 20 }}
          transition={{ type: "spring", stiffness: 300, damping: 30 }}
          className="backdrop-blur-2xl bg-white/90 border border-white/40 shadow-2xl rounded-2xl p-6 md:p-8"
        >
          {/* Close Button */}
          <button
            onClick={onClose}
            className="absolute top-4 right-4 p-2 text-gray-400 hover:text-gray-600 transition-colors rounded-full hover:bg-gray-100"
          >
            <X className="w-5 h-5" />
          </button>

          <DialogHeader className="text-center mb-6">
            <motion.div
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
            >
              <DialogTitle className="text-2xl md:text-3xl font-semibold tracking-tighter text-gray-900 mb-2">
                Enjoying Beautonomi?
              </DialogTitle>
              <p className="text-sm md:text-base font-light text-gray-600 mt-2">
                Your feedback helps us improve! Please take a moment to rate us on the {appStoreInfo?.name || 'App Store'}.
              </p>
            </motion.div>
          </DialogHeader>

          {/* Stars */}
          <motion.div
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ delay: 0.2 }}
            className="flex justify-center gap-1 mb-6"
          >
            {[1, 2, 3, 4, 5].map((star) => (
              <motion.div
                key={star}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 + star * 0.05 }}
                whileHover={{ scale: 1.2, rotate: 10 }}
              >
                <Star className="h-8 w-8 md:h-10 md:w-10 fill-yellow-400 text-yellow-400 drop-shadow-sm" />
              </motion.div>
            ))}
          </motion.div>

          {/* Store Selection (if multiple stores available) */}
          {availableStores.length > 1 && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.3 }}
              className="mb-6"
            >
              <p className="text-xs font-medium text-gray-500 mb-3 text-center">Select your app store:</p>
              <div className="flex flex-wrap justify-center gap-2">
                {availableStores.map((store) => (
                  <motion.button
                    key={store.platform}
                    onClick={() => handleStoreSelect(store)}
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    className={`flex items-center gap-2 px-4 py-2 rounded-lg border transition-all ${
                      appStoreInfo?.platform === store.platform
                        ? 'bg-pink-50 border-[#FF0077] text-[#FF0077]'
                        : 'bg-white/60 border-gray-200 text-gray-600 hover:border-gray-300'
                    }`}
                  >
                    <Image
                      src={store.icon}
                      alt={store.name}
                      className="h-4 w-4"
                      width={16}
                      height={16}
                    />
                    <span className="text-xs font-medium">{store.name}</span>
                  </motion.button>
                ))}
              </div>
            </motion.div>
          )}

          {/* Action Buttons */}
          <div className="flex flex-col gap-3">
            {appStoreInfo && !isLoading ? (
              <motion.div
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
              >
                <Button
                  onClick={handleRate}
                  className="w-full bg-gradient-to-r from-[#FF0077] to-[#E6006A] hover:from-[#E6006A] hover:to-[#FF0077] text-white shadow-lg h-12 text-base font-semibold"
                  size="lg"
                >
                  <Image
                    src={appStoreInfo.icon}
                    alt={appStoreInfo.name}
                    className="h-5 w-5 mr-2"
                    width={20}
                    height={20}
                  />
                  {appStoreInfo.buttonText}
                  <ExternalLink className="w-4 h-4 ml-2" />
                </Button>
              </motion.div>
            ) : (
              <Button
                disabled
                className="w-full bg-gray-200 text-gray-400 cursor-not-allowed h-12"
                size="lg"
              >
                <Smartphone className="w-5 h-5 mr-2 animate-pulse" />
                Loading...
              </Button>
            )}

            <motion.div
              whileHover={{ scale: 1.01 }}
              whileTap={{ scale: 0.99 }}
            >
              <Button
                onClick={onClose}
                variant="outline"
                className="w-full border-gray-200 hover:bg-gray-50 text-gray-700 h-12 text-base font-medium"
                size="lg"
              >
                Maybe Later
              </Button>
            </motion.div>
          </div>
        </motion.div>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect, useRef } from "react";
import Image from "next/image";
import { Search, MapPin, Calendar, Clock, Home, Briefcase, History, Loader2, CheckCircle2, AlertCircle } from "lucide-react";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import { Calendar as CalendarComponent } from "@/components/ui/calendar";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { format } from "date-fns";
import Link from "next/link";
import AddressAutocomplete from "@/components/mapbox/AddressAutocomplete";
import { useRecentLocations, type RecentLocation } from "@/hooks/useRecentLocations";
import { useServiceAvailability } from "@/hooks/useServiceAvailability";
import { useUserLocation } from "@/hooks/useUserLocation";
import { toast } from "sonner";

import Hair from "./../../.././public/images/hair-cut.png";
import Nails from "./../../../public/images/care.png";
import Massage from "./../../../public/images/massage.png";
import Eyebrows from "./../../../public/images/hair-removal.png";
import Barbering from "./../../../public/images/barbershop.png";

const categories = [
  {
    name: "Hair & styling",
    icon: Hair,
    subcategories: ["Haircut", "Hair coloring", "Hair extensions"],
  },
  {
    name: "Nails",
    icon: Nails,
    subcategories: ["Manicure", "Pedicure", "Nail art"],
  },
  {
    name: "Eyebrows & eyelashes",
    icon: Eyebrows,
    subcategories: ["Eyebrow threading", "Eyelash extensions", "Microblading"],
  },
  {
    name: "Massage",
    icon: Massage,
    subcategories: [
      "Swedish massage",
      "Deep tissue massage",
      "Hot stone massage",
    ],
  },
  {
    name: "Barbering",
    icon: Barbering,
    subcategories: ["Men's haircut", "Beard trim", "Hot towel shave"],
  },
];

const timeSlots = ["Any time", "Morning", "Afternoon", "Evening"];

interface SearchBarProps {
  searchQuery: string;
  onSearchSubmit: (query: string) => void;
}

interface LocationState {
  address: string;
  latitude: number;
  longitude: number;
  city?: string;
  country?: string;
}

const SearchBar: React.FC<SearchBarProps> = ({
  searchQuery,
  onSearchSubmit,
}) => {
  const [inputValue, _setInputValue] = useState(searchQuery);
  const [treatment, setTreatment] = useState("");
  const [locationState, setLocationState] = useState<LocationState | null>(null);
  const [locationSearchQuery, setLocationSearchQuery] = useState("");
  const [date, setDate] = useState<Date | undefined>(undefined);
  const [timeSlot, setTimeSlot] = useState("Any time");
  const [fromTime, setFromTime] = useState("");
  const [toTime, setToTime] = useState("");
  const [categorySearch, setCategorySearch] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("");
  const [selectedSubcategory, setSelectedSubcategory] = useState("");
  const [_showLocationLabelDialog, setShowLocationLabelDialog] = useState(false);
  const [_locationToLabel, setLocationToLabel] = useState<RecentLocation | null>(null);
  const [_newLabel, setNewLabel] = useState("");

  // New state to control popover visibility
  const [isServicePopoverOpen, setIsServicePopoverOpen] = useState(false);
  const [isLocationPopoverOpen, setIsLocationPopoverOpen] = useState(false);
  const [isDatePopoverOpen, setIsDatePopoverOpen] = useState(false);
  const [isTimePopoverOpen, setIsTimePopoverOpen] = useState(false);

  const searchBarRef = useRef<HTMLDivElement>(null);
  const { location: userLocation } = useUserLocation();
  const { recentLocations, addLocation, updateLocationLabel } = useRecentLocations();
  const { availability, checkAvailability, reset: resetAvailability } = useServiceAvailability();

  // Sync with header location
  useEffect(() => {
    if (userLocation) {
      queueMicrotask(() =>
        setLocationState({
          address: userLocation.address,
          latitude: userLocation.latitude,
          longitude: userLocation.longitude,
        })
      );
    }
  }, [userLocation]);

  // Check service availability when location changes
  useEffect(() => {
    if (locationState?.latitude && locationState?.longitude) {
      checkAvailability(locationState.latitude, locationState.longitude);
    } else {
      resetAvailability();
    }
  }, [locationState, checkAvailability, resetAvailability]);

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 0) {
        setIsServicePopoverOpen(false);
        setIsLocationPopoverOpen(false);
        setIsDatePopoverOpen(false);
        setIsTimePopoverOpen(false);
      }
    };

    window.addEventListener('scroll', handleScroll);

    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  useEffect(() => {
    queueMicrotask(() => {
      if (selectedCategory && selectedSubcategory) {
        setTreatment(`${selectedCategory} - ${selectedSubcategory}`);
      } else if (selectedCategory) {
        setTreatment(selectedCategory);
      }
    });
  }, [selectedCategory, selectedSubcategory]);

  const handleSearch = () => {
    console.log({ treatment, location: locationState, date, timeSlot, fromTime, toTime });
    onSearchSubmit(inputValue);
  };

  const filteredCategories = categories.filter((category) =>
    (category?.name ?? "").toLowerCase().includes((categorySearch ?? "").toLowerCase())
  );

  const handleCategorySelect = (category: string) => {
    setSelectedCategory(category);
    setSelectedSubcategory("");
    setCategorySearch("");
  };

  const handleSubcategorySelect = (subcategory: string) => {
    setSelectedSubcategory(subcategory);
    setTreatment(`${selectedCategory} - ${subcategory}`);
    setIsServicePopoverOpen(false);
  };

  const formatTime = (time: string) => {
    const [hours, minutes] = time.split(":").map(Number);
    const ampm = hours >= 12 ? "PM" : "AM";
    const formattedHours = hours % 12 || 12;
    return `${formattedHours}:${minutes.toString().padStart(2, "0")} ${ampm}`;
  };

  const handleFromTimeChange = (selectedTime: string) => {
    setFromTime(selectedTime);

    const [hour, minutes] = selectedTime.split(":").map(Number);
    const newToHour = (hour + 2) % 24;
    const formattedNewToTime = `${newToHour
      .toString()
      .padStart(2, "0")}:${minutes.toString().padStart(2, "0")}`;

    setToTime(formattedNewToTime);
  };

  const truncateLocation = (loc: string) => {
    return loc.length > 20 ? loc.substring(0, 20) + "..." : loc;
  };

  const handleAddressSelect = (address: {
    address_line1: string;
    city: string;
    state?: string;
    postal_code?: string;
    country: string;
    latitude: number;
    longitude: number;
    place_name?: string;
  }) => {
    const addressString = address.place_name || `${address.address_line1}, ${address.city}, ${address.country}`;

    setLocationState({
      address: addressString,
      latitude: address.latitude,
      longitude: address.longitude,
      city: address.city,
      country: address.country,
    });

    // Save to localStorage and dispatch event (sync with header)
    const locationData = {
      latitude: address.latitude,
      longitude: address.longitude,
      address: addressString,
    };
    localStorage.setItem("userLocation", JSON.stringify(locationData));
    window.dispatchEvent(new CustomEvent("userLocationChanged", { detail: locationData }));

    // Add to recent locations
    addLocation({
      address: addressString,
      latitude: address.latitude,
      longitude: address.longitude,
      city: address.city,
      country: address.country,
    });

    setIsLocationPopoverOpen(false);
    setLocationSearchQuery("");
  };

  const handleSelectRecentLocation = (recentLoc: RecentLocation) => {
    setLocationState({
      address: recentLoc.address,
      latitude: recentLoc.latitude,
      longitude: recentLoc.longitude,
      city: recentLoc.city,
      country: recentLoc.country,
    });

    // Save to localStorage and dispatch event
    const locationData = {
      latitude: recentLoc.latitude,
      longitude: recentLoc.longitude,
      address: recentLoc.address,
    };
    localStorage.setItem("userLocation", JSON.stringify(locationData));
    window.dispatchEvent(new CustomEvent("userLocationChanged", { detail: locationData }));

    setIsLocationPopoverOpen(false);
  };

  const handleGetCurrentLocation = () => {
    if (!navigator.geolocation) {
      toast.error("Geolocation is not supported by your browser");
      return;
    }

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const { latitude, longitude } = position.coords;

        try {
          const response = await fetch("/api/mapbox/geocode", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              query: `${longitude},${latitude}`,
              limit: 1,
            }),
          });

          const data = await response.json();
          if (data.data && data.data.length > 0) {
            const address = data.data[0].place_name;
            handleAddressSelect({
              address_line1: address.split(",")[0] || address,
              city: data.data[0].context?.find((c: any) => c.id.startsWith("place."))?.text || "",
              country: data.data[0].context?.find((c: any) => c.id.startsWith("country."))?.text || "",
              latitude,
              longitude,
              place_name: address,
            });
            toast.success("Location updated");
          } else {
            toast.error("Could not find address for this location");
          }
        } catch (error) {
          console.error("Error reverse geocoding:", error);
          toast.error("Failed to get address");
        }
      },
      (error) => {
        console.error("Error getting location:", error);
        toast.error("Unable to get your location. Please enable location permissions.");
      }
    );
  };

  const _handleSetLocationLabel = (loc: RecentLocation, label: string) => {
    updateLocationLabel(loc.id, label);
    setShowLocationLabelDialog(false);
    setLocationToLabel(null);
    setNewLabel("");
    toast.success(`Location saved as "${label}"`);
  };

  const homeLocation = recentLocations.find((loc) => loc.label === "Home");
  const workLocation = recentLocations.find((loc) => loc.label === "Work");
  const otherRecentLocations = recentLocations.filter(
    (loc) => loc.label !== "Home" && loc.label !== "Work"
  );

  return (
    <div ref={searchBarRef} className="flex relative flex-col sm:flex-row items-center bg-white rounded-full searchShadow border border-[#DDDDDD]">
      <Popover open={isServicePopoverOpen} onOpenChange={setIsServicePopoverOpen}>
        <PopoverTrigger
          asChild
          className="border border-transparent hover:bg-[#F2F2F2] pl-4 rounded-l-full py-3 rounded-full ml-1 w-1/4"
        >
          <Button
            variant="outline"
            className="w-full justify-start text-left font-light flex flex-col items-start"
          >
            <label
              htmlFor="service-needed"
              className="text-xs text-muted font-bold ml-7"
            >
              Service needed?
            </label>
            <div className="flex items-center w-32">
              <Search
                className="h-4 w-4 text-[#161616] mr-3"
                aria-hidden="true"
              />
              <span
                id="service-needed"
                className="text-[#767A7C] font-light truncate"
              >
                {treatment || "Any treatment or venue"}
              </span>
            </div>
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-[300px] rounded-3xl mt-1 ml-10">
          <div className="space-y-4">
            <h4 className="font-normal">Top categories</h4>
            <Input
              placeholder="Search categories"
              value={categorySearch}
              onChange={(e) => setCategorySearch(e.target.value)}
              className="mb-2"
            />
            <div className="grid grid-cols-1 gap-2 max-h-72 overflow-y-auto">
              {selectedCategory ? (
                <>
                  <button
                    className="justify-start flex text-destructive"
                    onClick={() => setSelectedCategory("")}
                  >
                    ΓåÉ Back to categories
                  </button>
                  {categories
                    .find((cat) => cat.name === selectedCategory)
                    ?.subcategories.map((subcategory) => (
                      <div
                        key={subcategory}
                        className="flex items-center gap-4 rounded-md px-2 py-2 hover:bg-gray-100 cursor-pointer"
                        onClick={() => handleSubcategorySelect(subcategory)}
                      >
                        <span className="flex justify-center items-center rounded-sm border border-gray-300 w-10 h-10 bg-white">
                          <Image
                            src={
                              categories.find(
                                (cat) => cat.name === selectedCategory
                              )?.icon || ""
                            }
                            alt={subcategory}
                            width={24}
                            height={24}
                          />
                        </span>
                        <span className="text-sm font-light">
                          {subcategory}
                        </span>
                      </div>
                    ))}
                </>
              ) : (
                filteredCategories.map((category) => (
                  <div
                    key={category.name}
                    className="flex items-center gap-4 rounded-md px-2 py-2 hover:bg-gray-100 cursor-pointer"
                    onClick={() => handleCategorySelect(category.name)}
                  >
                    <span className="flex justify-center items-center rounded-sm border border-gray-300 w-10 h-10 bg-white">
                      <Image
                        src={category.icon}
                        alt={category.name}
                        width={24}
                        height={24}
                      />
                    </span>
                    <span className="text-sm font-light">{category.name}</span>
                  </div>
                ))
              )}
            </div>
          </div>
        </PopoverContent>
      </Popover>

      <div className="w-2 h-6 bg-[#c8cacd]" />

      <Popover open={isLocationPopoverOpen} onOpenChange={setIsLocationPopoverOpen}>
        <PopoverTrigger
          asChild
          className="border border-transparent hover:bg-[#F2F2F2] pl-4 rounded-full w-1/4"
        >
          <Button
            variant="outline"
            className="w-full justify-start text-left font-light flex flex-col items-start"
          >
            <label
              htmlFor="service-needed"
              className="text-xs text-muted font-bold ml-7"
            >
              Where?
            </label>
            <div className="flex items-center w-full">
              <MapPin className="h-4 w-4 text-[#161616]" />
              <span className="text-[#767A7C] font-light ml-3 truncate">
                {locationState ? truncateLocation(locationState.address) : "Current location"}
