  onChange?: (address: {
    address_line1: string;
    city: string;
    state?: string;
    postal_code?: string;
    country: string;
    latitude: number;
    longitude: number;
    place_name?: string;
  }) => void;
  onInputChange?: (value: string) => void;
  placeholder?: string;
  label?: string;
  country?: string;
  proximity?: { latitude: number; longitude: number };
  required?: boolean;
  className?: string;
  disabled?: boolean;
}

export default function AddressAutocomplete({
  value = "",
  onChange,
  onInputChange,
  placeholder = "Search for an address...",
  label,
  country,
  proximity,
  required = false,
  className = "",
  disabled = false,
}: AddressAutocompleteProps) {
  const [query, setQuery] = useState(value);
  const [suggestions, setSuggestions] = useState<AddressSuggestion[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const containerRef = useRef<HTMLDivElement>(null);
  const debounceTimerRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    setQuery(value);
  }, [value]);

  useEffect(() => {
    // Close suggestions when clicking outside
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const searchAddresses = async (searchQuery: string) => {
    // Reduced minimum to 2 characters for faster autocomplete
    if (searchQuery.trim().length < 2) {
      setSuggestions([]);
      setShowSuggestions(false);
      return;
    }

    try {
      setIsLoading(true);
      const payload: any = {
        query: searchQuery,
        limit: 5,
      };

      // Use country code for Mapbox (e.g., "ZA" for South Africa)
      // Mapbox expects ISO 3166-1 alpha-2 country codes
      if (country) {
        // If it's already a 2-letter code, use it directly
        // Otherwise, Mapbox will try to match by name
        payload.country = country.length === 2 ? country.toUpperCase() : country;
      }

      if (proximity) {
        payload.proximity = {
          longitude: proximity.longitude,
          latitude: proximity.latitude,
        };
      }

      const response = await fetcher.post<{ data: AddressSuggestion[] }>(
        "/api/mapbox/geocode",
        payload
      );

      // Handle response - data might be empty array if Mapbox isn't configured
      const results = response.data || [];
      setSuggestions(results);

      // Only show suggestions if we have results
      if (results.length > 0) {
        setShowSuggestions(true);
        setSelectedIndex(-1);
      } else {
        setShowSuggestions(false);
      }
    } catch (error) {
      console.error("Error searching addresses:", error);
      // Silently fail - user can still manually enter address
      // Don't show error to user, just don't show suggestions
      setSuggestions([]);
      setShowSuggestions(false);
    } finally {
      setIsLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newQuery = e.target.value;
    setQuery(newQuery);
    onInputChange?.(newQuery);

    // Clear suggestions if query is too short
    if (newQuery.trim().length < 2) {
      setSuggestions([]);
      setShowSuggestions(false);
      return;
    }

    // Debounce search - reduced delay for faster response
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
    }

    debounceTimerRef.current = setTimeout(() => {
      searchAddresses(newQuery);
    }, 250); // Reduced from 300ms to 250ms for faster autocomplete
  };

  // Handle manual address entry when user finishes typing (on blur)
  // This allows the form to work even if Mapbox autocomplete isn't available
  const handleBlur = () => {
    // Only update if user typed something and didn't select a suggestion
    // This ensures manual entry works even without Mapbox
    if (onChange && query.trim().length > 0) {
      // Check if this is a manual entry (no suggestions shown or query doesn't match)
      const isManualEntry = !showSuggestions || 
        suggestions.length === 0 ||
        !suggestions.some(s => s.place_name === query);

      if (isManualEntry) {
        // User typed manually - update address_line1
        // Note: We set city to empty string, but the form will preserve manually entered values
        // because the parent component's handleAddressSelect merges with existing data
        onChange({
          address_line1: query.trim(),
          city: '', // User will fill this manually in the city field
          state: undefined,
          postal_code: undefined,
          country: country || '',
          latitude: 0, // Optional - can be geocoded later if Mapbox is configured
          longitude: 0,
        });
      }
    }
    // If required and empty, the HTML5 validation will handle it via the required attribute
    setShowSuggestions(false);
  };

  const parseAddress = (suggestion: AddressSuggestion) => {
    const context = suggestion.context || [];
    const addressParts: any = {
      address_line1: "",
      city: "",
      state: "",
      postal_code: "",
      country: "",
      latitude: suggestion.center[1],
      longitude: suggestion.center[0],
      place_name: suggestion.place_name,
    };

    // Parse context to extract address components
    // Mapbox context array is ordered from most specific to least specific
    for (const item of context) {
      if (item.id.startsWith("place.")) {
        // City/town
        if (!addressParts.city) {
          addressParts.city = item.text;
        }
      } else if (item.id.startsWith("district.")) {
        // District (sometimes used for city)
        if (!addressParts.city) {
          addressParts.city = item.text;
        }
      } else if (item.id.startsWith("region.")) {
        // State/Province
        addressParts.state = item.text;
      } else if (item.id.startsWith("postcode.")) {
        // Postal code
        addressParts.postal_code = item.text;
      } else if (item.id.startsWith("country.")) {
        // Country
        addressParts.country = item.text;
      }
    }

    // Extract street address from place_name
    // Format is usually: "Street Address, City, State, Postal Code, Country"
    const placeParts = suggestion.place_name.split(",").map(p => p.trim());

    if (placeParts.length > 0) {
      // First part is usually the street address
      addressParts.address_line1 = placeParts[0];

      // If we don't have city from context, try to get it from place_name
      if (!addressParts.city && placeParts.length > 1) {
        addressParts.city = placeParts[1];
      }

      // If we don't have state from context, try to get it from place_name
      if (!addressParts.state && placeParts.length > 2) {
        addressParts.state = placeParts[2];
      }

      // If we don't have postal code from context, try to get it from place_name
      if (!addressParts.postal_code && placeParts.length > 3) {
        // Check if it looks like a postal code (numbers or alphanumeric)
        const possiblePostal = placeParts[3];
        if (/^[0-9A-Z\s-]+$/.test(possiblePostal) && possiblePostal.length <= 10) {
          addressParts.postal_code = possiblePostal;
        }
      }
    }

    // Fallback: if country wasn't found, use the provided country prop
    if (!addressParts.country && country) {
      addressParts.country = country;
    }

    return addressParts;
  };

  const handleSelectSuggestion = (suggestion: AddressSuggestion) => {
    const address = parseAddress(suggestion);
    // Use the full place_name for display, but the parsed address_line1 for the actual address
    setQuery(suggestion.place_name);
    setShowSuggestions(false);
    setSuggestions([]);
    setSelectedIndex(-1);

    if (onChange) {
      onChange(address);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (suggestions.length === 0) return;

    if (e.key === "ArrowDown") {
      e.preventDefault();
      setSelectedIndex((prev) => (prev < suggestions.length - 1 ? prev + 1 : prev));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setSelectedIndex((prev) => (prev > 0 ? prev - 1 : -1));
    } else if (e.key === "Enter") {
      e.preventDefault();
      // Select the highlighted suggestion, or the first one if none is highlighted
      const indexToSelect = selectedIndex >= 0 ? selectedIndex : 0;
      if (suggestions[indexToSelect]) {
        handleSelectSuggestion(suggestions[indexToSelect]);
      }
    } else if (e.key === "Escape") {
      e.preventDefault();
      setShowSuggestions(false);
      setSelectedIndex(-1);
    }
  };

  return (
    <div ref={containerRef} className={`relative ${className}`}>
      {label && (
        <Label htmlFor="address-autocomplete" className="mb-2 block">
          {label}
          {required && <span className="text-red-500 ml-1">*</span>}
        </Label>
      )}
      <div className="relative">
        <MapPin className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
        <Input
          id="address-autocomplete"
          type="text"
          value={query}
          onChange={handleInputChange}
          onBlur={handleBlur}
          onKeyDown={handleKeyDown}
          onFocus={() => {
            if (suggestions.length > 0) {
              setShowSuggestions(true);
            }
          }}
          placeholder={placeholder}
          className="pl-10"
          required={required}
          disabled={disabled}
        />
        {isLoading && (
          <Loader2 className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4 animate-spin" />
        )}
      </div>

      {showSuggestions && suggestions.length > 0 && (
        <div className="absolute z-50 w-full mt-1 bg-white border border-gray-200 rounded-lg shadow-xl max-h-60 overflow-y-auto">
          {suggestions.map((suggestion, index) => (
            <button
              key={suggestion.id}
              type="button"
              onClick={() => handleSelectSuggestion(suggestion)}
              onMouseEnter={() => setSelectedIndex(index)}
              className={`w-full text-left px-4 py-3 hover:bg-[#FF0077]/5 transition-colors border-b border-gray-100 last:border-b-0 ${
                index === selectedIndex ? "bg-[#FF0077]/10" : "bg-white"
              } ${index === 0 ? "rounded-t-lg" : ""} ${
                index === suggestions.length - 1 ? "rounded-b-lg" : ""
              }`}
            >
              <div className="flex items-start gap-3">
                <MapPin className={`w-4 h-4 mt-0.5 flex-shrink-0 ${
                  index === selectedIndex ? "text-[#FF0077]" : "text-gray-400"
                }`} />
                <div className="flex-1 min-w-0">
                  <p className={`text-sm font-medium truncate ${
                    index === selectedIndex ? "text-[#FF0077]" : "text-gray-900"
                  }`}>
                    {suggestion.place_name}
                  </p>
                </div>
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import AddressAutocomplete from "./AddressAutocomplete";

interface AddressFormProps {
  initialAddress?: {
    label?: string;
    address_line1?: string;
    address_line2?: string;
    city?: string;
    state?: string;
    postal_code?: string;
    country?: string;
    latitude?: number;
    longitude?: number;
    apartment_unit?: string;
    building_name?: string;
    floor_number?: string;
    access_codes?: { gate?: string; buzzer?: string; door?: string } | string;
    parking_instructions?: string;
    location_landmarks?: string;
  };
  onSave: (address: any) => void | Promise<void>;
  onCancel?: () => void;
  showLabel?: boolean;
  country?: string;
  proximity?: { latitude: number; longitude: number };
  asForm?: boolean; // If false, renders as div instead of form (to avoid nested forms)
  showHouseCallFields?: boolean; // Show house call specific fields
}

export default function AddressForm({
  initialAddress,
  onSave,
  onCancel,
  showLabel = true,
  country,
  proximity,
  asForm = true,
  showHouseCallFields = true, // Default to true for saved addresses
}: AddressFormProps) {
  // Parse access_codes if it's a string (from database JSONB)
  const parseAccessCodes = (codes: any): { gate?: string; buzzer?: string; door?: string } => {
    if (!codes) return {};
    if (typeof codes === 'string') {
      try {
        return JSON.parse(codes);
      } catch {
        return {};
      }
    }
    return codes;
  };

  const [formData, setFormData] = useState({
    label: initialAddress?.label || "",
    address_line1: initialAddress?.address_line1 || "",
    address_line2: initialAddress?.address_line2 || "",
    city: initialAddress?.city || "",
    state: initialAddress?.state || "",
    postal_code: initialAddress?.postal_code || "",
    country: initialAddress?.country || country || "",
    latitude: initialAddress?.latitude || undefined,
    longitude: initialAddress?.longitude || undefined,
    apartment_unit: initialAddress?.apartment_unit || "",
    building_name: initialAddress?.building_name || "",
    floor_number: initialAddress?.floor_number || "",
    access_codes: parseAccessCodes(initialAddress?.access_codes),
    parking_instructions: initialAddress?.parking_instructions || "",
    location_landmarks: initialAddress?.location_landmarks || "",
  });
  const [isSaving, setIsSaving] = useState(false);

  const handleAddressSelect = (address: {
    address_line1: string;
    city: string;
    state?: string;
    postal_code?: string;
    country: string;
    latitude: number;
    longitude: number;
    place_name?: string;
  }) => {
    setFormData({
      ...formData,
      address_line1: address.address_line1,
      city: address.city,
      state: address.state || "",
      postal_code: address.postal_code || "",
      country: address.country,
      latitude: address.latitude,
      longitude: address.longitude,
    });
  };

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    try {
      setIsSaving(true);
      await onSave(formData);
    } catch (error) {
      console.error("Error saving address:", error);
    } finally {
      setIsSaving(false);
    }
  };

  const FormWrapper = asForm ? 'form' : 'div';
  const formProps = asForm ? { onSubmit: handleSubmit } : {};

  return (
    <FormWrapper {...formProps} className="space-y-4">
      {showLabel && (
        <div>
          <Label htmlFor="label">Label (e.g., Home, Work)</Label>
          <Input
            id="label"
            value={formData.label}
            onChange={(e) => setFormData({ ...formData, label: e.target.value })}
            placeholder="Home"
          />
        </div>
      )}

      <div>
        <Label htmlFor="address">Address *</Label>
        <AddressAutocomplete
          value={formData.address_line1}
          onChange={handleAddressSelect}
          placeholder="Start typing an address..."
          country={formData.country || country}
          proximity={proximity}
          required
        />
      </div>

      <div>
        <Label htmlFor="address_line2">Apartment, suite, etc. (optional)</Label>
        <Input
          id="address_line2"
          value={formData.address_line2}
          onChange={(e) => setFormData({ ...formData, address_line2: e.target.value })}
          placeholder="Apt 4B"
        />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label htmlFor="city">City *</Label>
          <Input
            id="city"
            value={formData.city}
            onChange={(e) => setFormData({ ...formData, city: e.target.value })}
            required
          />
        </div>

        <div>
          <Label htmlFor="state">State/Province</Label>
          <Input
            id="state"
            value={formData.state}
            onChange={(e) => setFormData({ ...formData, state: e.target.value })}
          />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label htmlFor="postal_code">Postal Code</Label>
          <Input
            id="postal_code"
            value={formData.postal_code}
            onChange={(e) => setFormData({ ...formData, postal_code: e.target.value })}
          />
        </div>

        <div>
          <Label htmlFor="country">Country *</Label>
          <Input
            id="country"
            value={formData.country}
            onChange={(e) => setFormData({ ...formData, country: e.target.value })}
            required
          />
        </div>
      </div>

      {/* House Call Specific Fields */}
      {showHouseCallFields && (
        <div className="space-y-4 pt-4 border-t">
          <p className="text-sm font-medium text-gray-700">Additional Location Details (Optional)</p>
          <p className="text-xs text-gray-500 mb-3">
            Help service providers find you easily by providing these details
          </p>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <Label htmlFor="apartment_unit">Apartment/Unit Number</Label>
              <Input
                id="apartment_unit"
                value={formData.apartment_unit}
                onChange={(e) => setFormData({ ...formData, apartment_unit: e.target.value })}
                placeholder="e.g., Apt 5B, Unit 12"
              />
            </div>

            <div>
              <Label htmlFor="building_name">Building/Complex Name</Label>
              <Input
                id="building_name"
                value={formData.building_name}
                onChange={(e) => setFormData({ ...formData, building_name: e.target.value })}
                placeholder="e.g., Sunset Towers"
              />
            </div>

            <div>
              <Label htmlFor="floor_number">Floor Number</Label>
              <Input
                id="floor_number"
                value={formData.floor_number}
                onChange={(e) => setFormData({ ...formData, floor_number: e.target.value })}
                placeholder="e.g., 3rd Floor"
              />
            </div>

            <div>
              <Label htmlFor="parking_instructions">Parking Instructions</Label>
              <Input
                id="parking_instructions"
                value={formData.parking_instructions}
                onChange={(e) => setFormData({ ...formData, parking_instructions: e.target.value })}
                placeholder="e.g., Free street parking, Visitor parking lot"
              />
            </div>
          </div>

          <div>
            <Label htmlFor="access_codes" className="mb-2 block">Access Codes (Optional)</Label>
            <div className="grid grid-cols-3 gap-2">
              <div>
                <Input
                  id="gate_code"
                  value={formData.access_codes?.gate || ""}
                  onChange={(e) => setFormData({
                    ...formData,
                    access_codes: { ...formData.access_codes, gate: e.target.value },
                  })}
                  placeholder="Gate code"
                />
                <Label htmlFor="gate_code" className="text-xs text-gray-500 mt-0.5 block">Gate</Label>
              </div>
              <div>
                <Input
                  id="buzzer_code"
                  value={formData.access_codes?.buzzer || ""}
                  onChange={(e) => setFormData({
                    ...formData,
                    access_codes: { ...formData.access_codes, buzzer: e.target.value },
                  })}
                  placeholder="Buzzer code"
                />
                <Label htmlFor="buzzer_code" className="text-xs text-gray-500 mt-0.5 block">Buzzer</Label>
              </div>
              <div>
                <Input
                  id="door_code"
                  value={formData.access_codes?.door || ""}
                  onChange={(e) => setFormData({
                    ...formData,
                    access_codes: { ...formData.access_codes, door: e.target.value },
                  })}
                  placeholder="Door code"
                />
                <Label htmlFor="door_code" className="text-xs text-gray-500 mt-0.5 block">Door</Label>
              </div>
            </div>
          </div>

          <div>
            <Label htmlFor="location_landmarks">Landmarks/Directions</Label>
            <Input
              id="location_landmarks"
              value={formData.location_landmarks}
              onChange={(e) => setFormData({ ...formData, location_landmarks: e.target.value })}
              placeholder="e.g., Next to the blue mailbox, red door"
            />
          </div>
        </div>
      )}

      <div className="flex gap-2 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button 
          type={asForm ? "submit" : "button"} 
          onClick={asForm ? undefined : handleSubmit}
          disabled={isSaving || !formData.address_line1 || !formData.city || !formData.country}
        >
          {isSaving ? "Saving..." : "Save Address"}
        </Button>
      </div>
    </FormWrapper>
  );
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import { getMapboxService } from "@/lib/mapbox/mapbox";
import { Button } from "@/components/ui/button";
import { Loader2, Save, X } from "lucide-react";
import { toast } from "sonner";

interface ServiceZone {
  id?: string;
  name: string;
  zone_type: "postal_code" | "city" | "polygon" | "radius";
  polygon_coordinates?: any;
  center_latitude?: number;
  center_longitude?: number;
  radius_km?: number;
  travel_fee: number;
  is_active: boolean;
}

interface ServiceZoneMapProps {
  zones: ServiceZone[];
  providerLocation?: { latitude: number; longitude: number };
  onZoneCreate?: (zone: Partial<ServiceZone>) => void;
  onZoneUpdate?: (zoneId: string, zone: Partial<ServiceZone>) => void;
  onZoneDelete?: (zoneId: string) => void;
  editable?: boolean;
  height?: string;
}

export default function ServiceZoneMap({
  zones,
  providerLocation,
  onZoneCreate,
  onZoneUpdate: _onZoneUpdate,
  onZoneDelete: _onZoneDelete,
  editable = false,
  height = "500px",
}: ServiceZoneMapProps) {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [_isDrawing, _setIsDrawing] = useState(false);
  const [drawingPolygon, setDrawingPolygon] = useState<any[]>([]);
  const [_selectedZone, _setSelectedZone] = useState<ServiceZone | null>(null);

  useEffect(() => {
    if (!mapContainerRef.current) return;

    let mapInstance: any = null;
    let mapboxgl: any = null;

    const initMap = async () => {
      try {
        // Dynamically import mapbox-gl
        mapboxgl = (await import("mapbox-gl")).default;
        // @ts-expect-error - @mapbox/mapbox-gl-draw has no type declarations
        const MapboxDraw = (await import("@mapbox/mapbox-gl-draw")).default;

        // Get Mapbox access token
        const mapbox = await getMapboxService();
        const accessToken = (mapbox as any).config.accessToken;

        if (!accessToken) {
          throw new Error("Mapbox access token not configured");
        }

        // Set access token
        mapboxgl.accessToken = accessToken;

        // Initialize map
        mapInstance = new mapboxgl.Map({
          container: mapContainerRef.current!,
          style: "mapbox://styles/mapbox/streets-v12",
          center: providerLocation
            ? [providerLocation.longitude, providerLocation.latitude]
            : [28.0473, -26.2041], // Default to Johannesburg
          zoom: providerLocation ? 12 : 10,
        });

        mapRef.current = mapInstance;

        // Add navigation controls
        mapInstance.addControl(new mapboxgl.NavigationControl(), "top-right");

        // Initialize draw control if editable
        let draw: any = null;
        if (editable) {
          draw = new MapboxDraw({
            displayControlsDefault: false,
            controls: {
              polygon: true,
              trash: true,
            },
          });
          mapInstance.addControl(draw, "top-left");

          // Handle polygon creation
          mapInstance.on("draw.create", (e: any) => {
            const feature = e.features[0];
            if (feature.geometry.type === "Polygon") {
              const coordinates = feature.geometry.coordinates[0];
              setDrawingPolygon(
                coordinates.map(([lng, lat]: [number, number]) => ({
                  longitude: lng,
                  latitude: lat,
                }))
              );
            }
          });

          mapInstance.on("draw.update", (e: any) => {
            const feature = e.features[0];
            if (feature.geometry.type === "Polygon") {
              const coordinates = feature.geometry.coordinates[0];
              setDrawingPolygon(
                coordinates.map(([lng, lat]: [number, number]) => ({
                  longitude: lng,
                  latitude: lat,
                }))
              );
            }
          });

          mapInstance.on("draw.delete", () => {
            setDrawingPolygon([]);
          });
        }

        // Wait for map to load
        mapInstance.on("load", () => {
          // Add provider location marker
          if (providerLocation) {
            new mapboxgl.Marker({ color: "#FF0077" })
              .setLngLat([providerLocation.longitude, providerLocation.latitude])
              .setPopup(new mapboxgl.Popup().setHTML("<b>Your Location</b>"))
              .addTo(mapInstance);
          }

          // Add zone polygons
          zones.forEach((zone) => {
            if (zone.zone_type === "polygon" && zone.polygon_coordinates) {
              const coordinates = zone.polygon_coordinates[0] || zone.polygon_coordinates;
              const polygonCoords = coordinates.map((coord: any) => {
                if (Array.isArray(coord)) {
                  return coord;
                }
                return [coord.longitude, coord.latitude];
              });

              // Close the polygon
              if (polygonCoords.length > 0) {
                polygonCoords.push(polygonCoords[0]);
              }

              mapInstance.addSource(`zone-${zone.id}`, {
                type: "geojson",
                data: {
                  type: "Feature",
                  geometry: {
                    type: "Polygon",
                    coordinates: [polygonCoords],
                  },
                },
              });

              mapInstance.addLayer({
                id: `zone-${zone.id}-fill`,
                type: "fill",
                source: `zone-${zone.id}`,
                paint: {
                  "fill-color": zone.is_active ? "#FF0077" : "#999999",
                  "fill-opacity": 0.3,
                },
              });

              mapInstance.addLayer({
                id: `zone-${zone.id}-outline`,
                type: "line",
                source: `zone-${zone.id}`,
                paint: {
                  "line-color": zone.is_active ? "#FF0077" : "#999999",
                  "line-width": 2,
                },
              });
            } else if (zone.zone_type === "radius" && zone.center_latitude && zone.center_longitude && zone.radius_km) {
              // Add radius circle
              const center = [zone.center_longitude, zone.center_latitude];
              const _radiusMeters = zone.radius_km * 1000;

              // Create circle using turf.js (would need to import)
              // For now, add a marker at center
              new mapboxgl.Marker({ color: zone.is_active ? "#FF0077" : "#999999" })
                .setLngLat(center)
                .setPopup(
                  new mapboxgl.Popup().setHTML(
                    `<b>${zone.name}</b><br/>Radius: ${zone.radius_km}km`
                  )
                )
                .addTo(mapInstance);
            }
          });

          setIsLoading(false);
        });

        mapInstance.on("error", (e: any) => {
          console.error("Map error:", e);
          setIsLoading(false);
        });
      } catch (error: any) {
        console.error("Failed to initialize map:", error);
        toast.error("Failed to load map. Please check Mapbox configuration.");
        setIsLoading(false);
      }
    };

    initMap();

    return () => {
      if (mapInstance) {
        mapInstance.remove();
      }
    };
  }, [zones, providerLocation, editable]);

  const handleSavePolygon = () => {
    if (drawingPolygon.length < 3) {
      toast.error("Polygon must have at least 3 points");
      return;
    }

    if (onZoneCreate) {
      onZoneCreate({
        zone_type: "polygon",
        polygon_coordinates: [drawingPolygon.map((p) => [p.longitude, p.latitude])],
        name: `Zone ${zones.length + 1}`,
        travel_fee: 0,
        is_active: true,
      });
      setDrawingPolygon([]);
      toast.success("Polygon zone created");
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center" style={{ height }}>
        <Loader2 className="w-6 h-6 animate-spin text-[#FF0077]" />
      </div>
    );
  }

  return (
    <div className="relative">
      <div ref={mapContainerRef} style={{ height, width: "100%" }} className="rounded-lg" />

      {editable && drawingPolygon.length > 0 && (
        <div className="absolute top-4 left-4 bg-white p-4 rounded-lg shadow-lg z-10">
          <p className="text-sm mb-2">Drawing polygon ({drawingPolygon.length} points)</p>
          <div className="flex gap-2">
            <Button size="sm" onClick={handleSavePolygon} className="bg-[#FF0077] hover:bg-[#D60565]">
              <Save className="w-4 h-4 mr-1" />
              Save Zone
            </Button>
            <Button
              size="sm"
              variant="outline"
              onClick={() => {
                setDrawingPolygon([]);
                if (mapRef.current) {
                  // Clear draw control
                  const draw = mapRef.current.getDraw();
                  if (draw) {
                    draw.deleteAll();
                  }
                }
              }}
            >
              <X className="w-4 h-4 mr-1" />
              Cancel
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { Loader2 } from "lucide-react";

interface ServiceZone {
  id?: string;
  name: string;
  zone_type: "postal_code" | "city" | "polygon" | "radius";
  polygon_coordinates?: any;
  center_latitude?: number;
  center_longitude?: number;
  radius_km?: number;
  travel_fee: number;
  is_active: boolean;
}

interface ZoneMapViewerProps {
  zones: ServiceZone[];
  providerLocation?: { latitude: number; longitude: number };
  height?: string;
  onZoneClick?: (zone: ServiceZone) => void;
}

/**
 * Simple zone map viewer using iframe with Mapbox Static Images API
 * Falls back to a simple visualization if Mapbox is not available
 */
export default function ZoneMapViewer({
  zones,
  providerLocation,
  height = "400px",
  onZoneClick,
}: ZoneMapViewerProps) {
  const [mapUrl, setMapUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const generateMapUrl = async () => {
      try {
        // Try to get Mapbox token
        await fetch("/api/mapbox/geocode", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ query: "test", limit: 1 }),
        });

        // If Mapbox is configured, we can use it
        // For now, use a simple Google Maps embed or static image
        const center = providerLocation || { latitude: -26.2041, longitude: 28.0473 };
        
        // Create a simple map using Google Maps embed (fallback)
        const googleMapsUrl = `https://www.google.com/maps/embed/v1/place?key=AIzaSyBFw0Qbyq9zTFTd-tUY6d-s6U4uO3vJz8&q=${center.latitude},${center.longitude}&zoom=12`;
        setMapUrl(googleMapsUrl);
      } catch {
        console.warn("Mapbox not available, using fallback");
        // Fallback: use a simple visualization
        setMapUrl(null);
      } finally {
        setIsLoading(false);
      }
    };

    generateMapUrl();
  }, [providerLocation, zones]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center border rounded-lg" style={{ height }}>
        <Loader2 className="w-6 h-6 animate-spin text-[#FF0077]" />
      </div>
    );
  }

  if (!mapUrl) {
    // Fallback: Simple list view
    return (
      <div className="border rounded-lg p-4" style={{ height, overflowY: "auto" }}>
        <h3 className="font-semibold mb-4">Service Zones</h3>
        <div className="space-y-2">
          {zones.map((zone, index) => (
            <div
              key={zone.id || index}
              className={`p-3 border rounded-lg cursor-pointer hover:bg-gray-50 ${
                zone.is_active ? "border-[#FF0077]" : "border-gray-300"
              }`}
              onClick={() => onZoneClick?.(zone)}
            >
              <div className="flex items-center justify-between">
                <div>
                  <p className="font-medium">{zone.name}</p>
                  <p className="text-sm text-gray-600">
                    {zone.zone_type === "postal_code" && "Postal Code Zone"}
                    {zone.zone_type === "city" && "City Zone"}
                    {zone.zone_type === "radius" && `Radius: ${zone.radius_km}km`}
                    {zone.zone_type === "polygon" && "Polygon Zone"}
                  </p>
                </div>
                <span
                  className={`px-2 py-1 rounded text-xs ${
                    zone.is_active ? "bg-green-100 text-green-800" : "bg-gray-100 text-gray-800"
                  }`}
                >
                  {zone.is_active ? "Active" : "Inactive"}
                </span>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="border rounded-lg overflow-hidden" style={{ height }}>
      <iframe
        src={mapUrl}
        width="100%"
        height="100%"
        style={{ border: 0 }}
        allowFullScreen
        loading="lazy"
        referrerPolicy="no-referrer-when-downgrade"
      />
    </div>
  );
}

"use client";
import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import Image from "next/image";
import { Sparkles, X, Upload } from "lucide-react";

interface CustomOfferModalProps {
  isOpen: boolean;
  onClose: () => void;
  customerId: string;
  customerName?: string;
  conversationId?: string | null;
  editOfferId?: string | null;
  onSuccess?: () => void;
}

export default function CustomOfferModal({
  isOpen,
  onClose,
  customerId,
  customerName,
  conversationId,
  editOfferId,
  onSuccess,
}: CustomOfferModalProps) {
  const [serviceName, setServiceName] = useState("");
  const [description, setDescription] = useState("");
  const [price, setPrice] = useState("");
  const [currency, setCurrency] = useState("ZAR");
  const [durationMinutes, setDurationMinutes] = useState("60");
  const [locationType, setLocationType] = useState<"at_home" | "at_salon">("at_salon");
  const [expirationDays, setExpirationDays] = useState("7");
  const [notes, setNotes] = useState("");
  const [preferredStartAt, setPreferredStartAt] = useState("");
  const [imageUrls, setImageUrls] = useState<string[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [serviceCategoryId, setServiceCategoryId] = useState<string | null>(null);
  const [categories, setCategories] = useState<Array<{ id: string; name: string }>>([]);
  const [staffId, setStaffId] = useState<string | null>(null);
  const [staffMembers, setStaffMembers] = useState<Array<{ id: string; name: string; is_active: boolean }>>([]);
  const [addressLine1, setAddressLine1] = useState("");
  const [addressCity, setAddressCity] = useState("");
  const [addressCountry, setAddressCountry] = useState("");
  const [travelFee, setTravelFee] = useState("");

  const isEditMode = Boolean(editOfferId);

  // Load service categories and staff members; when editing, load offer to pre-fill
  useEffect(() => {
    if (isOpen) {
      loadCategories();
      loadStaffMembers();
      if (editOfferId) {
        loadOfferForEdit(editOfferId);
      }
    }
  }, [isOpen, editOfferId]);

  const loadOfferForEdit = async (offerId: string) => {
    try {
      const res = await fetcher.get<{ data: any }>(`/api/provider/custom-offers/${offerId}`);
      const offer = res?.data;
      if (!offer) return;
      const req = offer.request;
      setPrice(String(offer.price ?? ""));
      setCurrency(offer.currency ?? "ZAR");
      setDurationMinutes(String(offer.duration_minutes ?? 60));
      setNotes(offer.notes ?? "");
      setStaffId(offer.staff_id ?? null);
      setTravelFee(offer.travel_fee != null ? String(offer.travel_fee) : "");
      if (req) {
        setServiceName(req.service_name ?? "");
        setDescription(req.description ?? "");
        setLocationType(req.location_type === "at_home" ? "at_home" : "at_salon");
        setServiceCategoryId(req.service_category_id ?? null);
        setAddressLine1(req.address_line1 ?? "");
        setAddressCity(req.address_city ?? "");
        setAddressCountry(req.address_country ?? "");
        if (req.preferred_start_at) {
          const d = new Date(req.preferred_start_at);
          setPreferredStartAt(d.toISOString().slice(0, 16));
        }
      }
    } catch (err) {
      console.error("Failed to load offer for edit:", err);
      toast.error("Could not load offer");
    }
  };

  const loadCategories = async () => {
    try {
      const response = await fetcher.get<{ data: Array<{ id: string; name: string }> }>("/api/public/categories/global");
      setCategories(response.data || []);
    } catch (err) {
      console.error("Failed to load categories:", err);
      // Continue without categories
    }
  };

  const loadStaffMembers = async () => {
    try {
      const response = await fetcher.get<{ data: Array<{ id: string; name: string; is_active: boolean }> }>("/api/provider/staff");
      // Only show active staff members
      const activeStaff = (response.data || []).filter((staff) => staff.is_active);
      setStaffMembers(activeStaff);
    } catch (err) {
      console.error("Failed to load staff members:", err);
      // Continue without staff selection
    }
  };

  const handleQuickTemplate = (template: string) => {
    const templates: Record<string, string> = {
      "Wedding Package": `I'd like to offer you a complete wedding package including hair, makeup, and nails. This includes a trial session before the wedding day. Perfect for your special day!`,
      "Special Occasion": `I have a special offer for your upcoming occasion. This includes full styling and makeup services tailored to your needs.`,
      "Package Deal": `I'm offering you a discounted package deal for multiple services. This is a great value opportunity!`,
      "Group Booking": `I can offer you a group booking discount for multiple people. Perfect for events, parties, or special occasions!`,
    };
    setDescription(templates[template] || "");
  };

  const _handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    if (imageUrls.length + files.length > 6) {
      toast.error("Maximum 6 images allowed");
      return;
    }

    // For now, we'll need to upload images to get URLs
    // This is a simplified version - you may need to implement actual image upload
    toast.info("Image upload functionality needs to be implemented");
  };

  const removeImage = (index: number) => {
    setImageUrls((prev) => prev.filter((_, i) => i !== index));
  };

  const calculateExpirationDate = (days: number): string => {
    const date = new Date();
    date.setDate(date.getDate() + days);
    return date.toISOString();
  };

  const isValid = () => {
    return (
      description.trim().length >= 10 &&
      description.trim().length <= 4000 &&
      price &&
      Number(price) >= 0 &&
      durationMinutes &&
      Number(durationMinutes) >= 15 &&
      Number(durationMinutes) <= 480 &&
      expirationDays &&
      Number(expirationDays) > 0
    );
  };

  const handleSubmit = async () => {
    if (!isValid()) {
      toast.error("Please fill in all required fields correctly");
      return;
    }

    try {
      setIsSubmitting(true);

      // Convert datetime-local to ISO string if provided
      let preferredStartAtIso: string | null = null;
      if (preferredStartAt) {
        const date = new Date(preferredStartAt);
        if (!isNaN(date.getTime())) {
          preferredStartAtIso = date.toISOString();
        }
      }

      const expirationAt = calculateExpirationDate(Number(expirationDays));

      const payload: Record<string, any> = {
        customer_id: customerId,
        service_category_id: serviceCategoryId || null,
        location_type: locationType,
        description: description.trim(),
        price: Number(price),
        currency: currency,
        duration_minutes: Number(durationMinutes),
        expiration_at: expirationAt,
        notes: notes.trim() || null,
        preferred_start_at: preferredStartAtIso,
        image_urls: imageUrls,
        staff_id: staffId || null,
      };
      if (conversationId) payload.conversation_id = conversationId;
      if (serviceName.trim()) payload.service_name = serviceName.trim();
      if (locationType === "at_home") {
        if (addressLine1.trim()) payload.address_line1 = addressLine1.trim();
        if (addressCity.trim()) payload.address_city = addressCity.trim();
        if (addressCountry.trim()) payload.address_country = addressCountry.trim();
        const fee = Number(travelFee);
        if (!Number.isNaN(fee) && fee >= 0) payload.travel_fee = fee;
      }

      if (editOfferId) {
        await fetcher.post(`/api/provider/custom-offers/${editOfferId}/retract`, {});
      }
      await fetcher.post<{ data: { request: any; offer: any } }>("/api/provider/custom-offers/create", payload);

      toast.success(isEditMode ? "Offer updated and resent." : "Custom offer sent successfully!");
      onSuccess?.();
      handleClose();
    } catch (err) {
      const errorMessage =
        err instanceof FetchError
          ? err.message
          : "Failed to send custom offer. Please try again.";
      toast.error(errorMessage);
      console.error("Error creating custom offer:", err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClose = () => {
    setServiceName("");
    setDescription("");
    setPrice("");
    setCurrency("ZAR");
    setDurationMinutes("60");
    setLocationType("at_salon");
    setExpirationDays("7");
    setNotes("");
    setPreferredStartAt("");
    setImageUrls([]);
    setServiceCategoryId(null);
    setStaffId(null);
    setAddressLine1("");
    setAddressCity("");
    setAddressCountry("");
    setTravelFee("");
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-2xl font-semibold flex items-center gap-2">
            <Sparkles className="w-6 h-6 text-[#FF0077]" />
            {isEditMode ? "Edit & resend offer" : `Send Custom Offer to ${customerName || "Customer"}`}
          </DialogTitle>
          <DialogDescription>
            {isEditMode
              ? "Update the offer and resend. The previous offer will be withdrawn and a new message will appear in this conversation."
              : "Create a personalized service offer for this customer. The offer will be sent as a message in your conversation."}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6 py-4">
          {/* Quick Templates */}
          <div>
            <Label className="text-sm font-semibold mb-2 block">Quick Templates</Label>
            <div className="flex flex-wrap gap-2">
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => handleQuickTemplate("Wedding Package")}
                className="rounded-full text-xs"
              >
                Wedding Package
              </Button>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => handleQuickTemplate("Special Occasion")}
                className="rounded-full text-xs"
              >
                Special Occasion
              </Button>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => handleQuickTemplate("Package Deal")}
                className="rounded-full text-xs"
              >
                Package Deal
              </Button>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => handleQuickTemplate("Group Booking")}
                className="rounded-full text-xs"
              >
                Group Booking
              </Button>
            </div>
          </div>

          {/* Service name (optional) - used as booking/calendar title when accepted */}
          <div className="space-y-2">
            <Label htmlFor="serviceName" className="text-sm font-semibold">
              Service name (optional)
            </Label>
            <Input
              id="serviceName"
              value={serviceName}
              onChange={(e) => setServiceName(e.target.value)}
              placeholder="e.g. Haircut & Styling"
            />
          </div>

          {/* Description */}
          <div className="space-y-2">
            <Label htmlFor="description" className="text-sm font-semibold flex items-center gap-2">
              Service Description <span className="text-red-500">*</span>
            </Label>
            <Textarea
              id="description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Describe the service you're offering. Include details about what's included, style preferences, special features, etc."
              rows={5}
              className="resize-none"
            />
            <p className="text-xs text-gray-500">
              {description.trim().length} / 10-4000 characters
            </p>
          </div>

          {/* Price and Currency */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="price" className="text-sm font-semibold">
                Price <span className="text-red-500">*</span>
              </Label>
              <Input
                id="price"
                type="number"
                min="0"
                step="0.01"
                value={price}
                onChange={(e) => setPrice(e.target.value)}
                placeholder="0.00"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="currency" className="text-sm font-semibold">
                Currency <span className="text-red-500">*</span>
              </Label>
              <Select value={currency} onValueChange={setCurrency}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ZAR">ZAR (South African Rand)</SelectItem>
                  <SelectItem value="USD">USD (US Dollar)</SelectItem>
                  <SelectItem value="EUR">EUR (Euro)</SelectItem>
                  <SelectItem value="GBP">GBP (British Pound)</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Duration and Location */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="duration" className="text-sm font-semibold">
                Duration (minutes) <span className="text-red-500">*</span>
              </Label>
              <Input
                id="duration"
                type="number"
                min="15"
                max="480"
                value={durationMinutes}
                onChange={(e) => setDurationMinutes(e.target.value)}
                placeholder="60"
              />
              <p className="text-xs text-gray-500">15-480 minutes (1-8 hours)</p>
            </div>
            <div className="space-y-2">
              <Label htmlFor="location" className="text-sm font-semibold">
                Location Type <span className="text-red-500">*</span>
              </Label>
              <Select value={locationType} onValueChange={(value: "at_home" | "at_salon") => setLocationType(value)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="at_salon">At Salon</SelectItem>
                  <SelectItem value="at_home">At Home</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Expiration and Preferred Start */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="expiration" className="text-sm font-semibold">
                Offer Expires In (days) <span className="text-red-500">*</span>
              </Label>
              <Input
                id="expiration"
                type="number"
                min="1"
                max="30"
                value={expirationDays}
                onChange={(e) => setExpirationDays(e.target.value)}
                placeholder="7"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="preferredStart" className="text-sm font-semibold">
                Preferred Start Date (optional)
              </Label>
              <Input
                id="preferredStart"
                type="datetime-local"
                value={preferredStartAt}
                onChange={(e) => setPreferredStartAt(e.target.value)}
                min={new Date().toISOString().slice(0, 16)}
              />
            </div>
          </div>

          {/* At home: address + optional travel fee */}
          {locationType === "at_home" && (
            <>
              <div className="space-y-2">
                <Label className="text-sm font-semibold">Address (for at home)</Label>
                <Input
                  value={addressLine1}
                  onChange={(e) => setAddressLine1(e.target.value)}
                  placeholder="Street address"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label className="text-sm font-semibold">City</Label>
                  <Input
                    value={addressCity}
                    onChange={(e) => setAddressCity(e.target.value)}
                    placeholder="City"
                  />
                </div>
                <div className="space-y-2">
                  <Label className="text-sm font-semibold">Country</Label>
                  <Input
                    value={addressCountry}
                    onChange={(e) => setAddressCountry(e.target.value)}
                    placeholder="Country"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <Label className="text-sm font-semibold">Travel fee (optional, ZAR)</Label>
                <Input
                  type="number"
                  min="0"
                  step="1"
                  value={travelFee}
                  onChange={(e) => setTravelFee(e.target.value)}
                  placeholder="e.g. 50"
                />
                <p className="text-xs text-gray-500">Add a travel fee for this house call. Leave empty for no fee.</p>
              </div>
            </>
          )}

          {/* Service Category (optional) */}
          {categories.length > 0 && (
            <div className="space-y-2">
              <Label htmlFor="category" className="text-sm font-semibold">
                Service Category (optional)
              </Label>
              <Select value={serviceCategoryId || ""} onValueChange={(value) => setServiceCategoryId(value || null)}>
                <SelectTrigger>
                  <SelectValue placeholder="Select a category (optional)" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">None</SelectItem>
                  {categories.map((cat) => (
                    <SelectItem key={cat.id} value={cat.id}>
                      {cat.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* Staff Assignment (optional) */}
          {staffMembers.length > 0 && (
            <div className="space-y-2">
              <Label htmlFor="staff" className="text-sm font-semibold">
                Assign to Staff Member (optional)
              </Label>
              <Select value={staffId || ""} onValueChange={(value) => setStaffId(value || null)}>
                <SelectTrigger>
                  <SelectValue placeholder="Select a staff member (optional)" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">No specific assignment</SelectItem>
                  {staffMembers.map((staff) => (
                    <SelectItem key={staff.id} value={staff.id}>
                      {staff.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <p className="text-xs text-gray-500">
                If assigned, this staff member will be assigned to the booking when the offer is accepted
              </p>
            </div>
          )}

          {/* Notes */}
          <div className="space-y-2">
            <Label htmlFor="notes" className="text-sm font-semibold">
              Additional Notes (optional)
            </Label>
            <Textarea
              id="notes"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="Any additional information, terms, or special conditions..."
              rows={3}
              className="resize-none"
            />
            <p className="text-xs text-gray-500">Max 4000 characters</p>
          </div>

          {/* Image Upload (optional) */}
          <div className="space-y-2">
            <Label className="text-sm font-semibold">Inspiration Images (optional)</Label>
            <div className="border-2 border-dashed border-gray-300 rounded-lg p-4">
              <div className="flex flex-col items-center justify-center gap-2">
                <Upload className="w-8 h-8 text-gray-400" />
                <p className="text-sm text-gray-500">Image upload coming soon</p>
                <p className="text-xs text-gray-400">Max 6 images</p>
              </div>
            </div>
            {imageUrls.length > 0 && (
              <div className="grid grid-cols-3 gap-2 mt-2">
                {imageUrls.map((url, index) => (
                  <div key={index} className="relative aspect-video">
                    <Image src={url} alt={`Preview ${index + 1}`} fill className="object-cover rounded" unoptimized />
                    <button
                      type="button"
                      onClick={() => removeImage(index)}
                      className="absolute top-1 right-1 bg-red-500 text-white rounded-full w-5 h-5 flex items-center justify-center text-xs"
                    >
                      <X className="w-3 h-3" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Footer Actions */}
        <div className="flex justify-end gap-3 pt-4 border-t">
          <Button variant="outline" onClick={handleClose} disabled={isSubmitting}>
            Cancel
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={!isValid() || isSubmitting}
            className="bg-gradient-to-r from-[#FF0077] to-[#D60565] hover:from-[#E6006A] hover:to-[#C00555] text-white"
          >
            {isSubmitting ? "Sending..." : "Send Offer"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";
import { useState, useRef, useEffect } from "react";
import { Send, ArrowLeft, MoreVertical, Phone, Tag, User, Mail, Copy, Check, Paperclip, X, File, Play, Trash2, Pencil, Undo2, Info } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { getSupabaseClient } from "@/lib/supabase/client";
import { toast } from "sonner";
import { format, isToday, isYesterday } from "date-fns";
import CustomOfferModal from "./custom-offer-modal";
import Image from "next/image";

interface Attachment {
  url: string;
  type: string;
  name: string;
  size?: number;
  currency?: string;
  price?: number;
  duration_minutes?: number;
  offer_id?: string;
  preferred_start_at?: string | null;
  withdrawn?: boolean;
}

interface Message {
  id: string;
  conversation_id: string;
  sender_id: string;
  sender_name?: string;
  sender_role?: string;
  content: string;
  attachments?: Attachment[];
  created_at: string;
  read_at?: string;
  is_read?: boolean;
}

interface Conversation {
  id: string;
  booking_id?: string;
  provider_id?: string;
  customer_id: string;
  last_message_at: string;
  unread_count: number;
  provider_name?: string;
  provider_phone?: string;
  provider_email?: string;
  customer_name?: string;
  customer_phone?: string | null;
  customer_email?: string | null;
  booking_number?: string;
  avatar?: string;
  customer_avatar?: string;
}

interface WhatsAppChatProps {
  conversation: Conversation | null;
  currentUserId: string;
  onBack?: () => void;
  onConversationUpdate?: () => void;
  messagesEndpoint?: string; // Optional custom endpoint for messages
}

export default function WhatsAppChat({
  conversation,
  currentUserId,
  onBack,
  onConversationUpdate,
  messagesEndpoint,
}: WhatsAppChatProps) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [messageInput, setMessageInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isSending, setIsSending] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [showCustomOfferModal, setShowCustomOfferModal] = useState(false);
  const [editOfferId, setEditOfferId] = useState<string | null>(null);
  const [copiedPhone, setCopiedPhone] = useState(false);
  const [copiedEmail, setCopiedEmail] = useState(false);
  const [hasInitiallyScrolled, setHasInitiallyScrolled] = useState(false);
  const [shouldAutoScroll, setShouldAutoScroll] = useState(false);
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const [filePreviews, setFilePreviews] = useState<Array<{ file: File; preview: string }>>([]);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isNearBottomRef = useRef(true);

  // Determine if this is a provider chat (provider uses messagesEndpoint)
  const isProviderChat = !!messagesEndpoint;

  // In provider view use customer contact; in customer view use provider contact
  const contactPhone = isProviderChat ? conversation?.customer_phone : conversation?.provider_phone;
  const contactEmail = isProviderChat ? conversation?.customer_email : conversation?.provider_email;

  const handlePhoneCall = () => {
    if (!contactPhone) {
      toast.error("Phone number not available");
      return;
    }
    window.location.href = `tel:${contactPhone}`;
  };

  const handleCopyPhone = async () => {
    if (!contactPhone) {
      toast.error("Phone number not available");
      return;
    }
    try {
      await navigator.clipboard.writeText(contactPhone);
      setCopiedPhone(true);
      toast.success("Phone number copied");
      setTimeout(() => setCopiedPhone(false), 2000);
    } catch {
      toast.error("Failed to copy phone number");
    }
  };

  const handleCopyEmail = async () => {
    if (!contactEmail) {
      toast.error("Email not available");
      return;
    }
    try {
      await navigator.clipboard.writeText(contactEmail);
      setCopiedEmail(true);
      toast.success("Email copied");
      setTimeout(() => setCopiedEmail(false), 2000);
    } catch {
      toast.error("Failed to copy email");
    }
  };

  const handleViewProfile = () => {
    if (isProviderChat) {
      // Provider viewing customer profile
      if (!conversation?.customer_id) {
        toast.error("Customer information not available");
        return;
      }
      window.location.href = `/provider/customers/${conversation.customer_id}/profile`;
    } else {
      // Customer viewing provider profile
      if (!conversation?.provider_id) {
        toast.error("Provider information not available");
        return;
      }
      window.location.href = `/partner-profile?slug=${conversation.provider_id}`;
    }
  };

  const handleDeleteConversation = async () => {
    if (!conversation || !conversation.id) {
      toast.error("Cannot delete: Conversation ID is missing");
      setShowDeleteDialog(false);
      return;
    }

    setIsDeleting(true);
    try {
      const endpoint = isProviderChat
        ? `/api/provider/conversations/${conversation.id}`
        : `/api/me/conversations/${conversation.id}`;

      await fetcher.delete(endpoint);

      toast.success("Conversation deleted");
      setShowDeleteDialog(false);

      // Call onConversationUpdate to refresh the list
      if (onConversationUpdate) {
        onConversationUpdate();
      }

      // Navigate back to conversation list
      if (onBack) {
        onBack();
      }
    } catch (error) {
      console.error("Error deleting conversation:", error);
      toast.error("Failed to delete conversation. Please try again.");
    } finally {
      setIsDeleting(false);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;

    // Validate file types and sizes
    const allowedImageTypes = ["image/jpeg", "image/jpg", "image/png", "image/webp", "image/gif"];
    const allowedVideoTypes = ["video/mp4", "video/webm", "video/quicktime", "video/x-msvideo"];
    const allowedDocTypes = ["application/pdf", "application/msword", "application/vnd.openxmlformats-officedocument.wordprocessingml.document"];
    const allowedTypes = [...allowedImageTypes, ...allowedVideoTypes, ...allowedDocTypes];

    const maxImageSize = 10 * 1024 * 1024; // 10MB
    const maxVideoSize = 50 * 1024 * 1024; // 50MB
    const maxDocSize = 10 * 1024 * 1024; // 10MB

    const validFiles: File[] = [];
    const _previews: Array<{ file: File; preview: string }> = [];

    for (const file of files) {
      if (!allowedTypes.includes(file.type)) {
        toast.error(`${file.name}: Invalid file type`);
        continue;
      }

      let maxSize = maxDocSize;
      if (allowedImageTypes.includes(file.type)) {
        maxSize = maxImageSize;
      } else if (allowedVideoTypes.includes(file.type)) {
        maxSize = maxVideoSize;
      }

      if (file.size > maxSize) {
        const sizeMB = Math.round(maxSize / (1024 * 1024));
        toast.error(`${file.name}: File too large (max ${sizeMB}MB)`);
        continue;
      }

      validFiles.push(file);

      // Create preview for images
      if (allowedImageTypes.includes(file.type)) {
        const reader = new FileReader();
        reader.onload = (e) => {
          const preview = e.target?.result as string;
          setFilePreviews((prev) => [...prev, { file, preview }]);
        };
        reader.readAsDataURL(file);
      }
    }

    if (validFiles.length > 0) {
      setSelectedFiles((prev) => [...prev, ...validFiles]);
      toast.success(`${validFiles.length} file(s) selected`);
    }

    // Reset input
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const removeFile = (index: number) => {
    setSelectedFiles((prev) => prev.filter((_, i) => i !== index));
    setFilePreviews((prev) => prev.filter((_, i) => i !== index));
  };

  const clearFiles = () => {
    setSelectedFiles([]);
    setFilePreviews([]);
  };

  const isImage = (type: string) => {
    return type.startsWith("image/");
  };

  const isVideo = (type: string) => {
    return type.startsWith("video/");
  };

  // Check if user is near bottom of messages
  const checkIfNearBottom = () => {
    if (!messagesContainerRef.current) return false;
    const container = messagesContainerRef.current;
    const threshold = 100; // pixels from bottom
    const isNearBottom = container.scrollHeight - container.scrollTop - container.clientHeight < threshold;
    isNearBottomRef.current = isNearBottom;
    return isNearBottom;
  };

  // Scroll to bottom when new messages arrive (only if user is near bottom or it's their own message)
  useEffect(() => {
    if (messages.length === 0) return;

    // On initial load, scroll to bottom once (but only if chat is visible)
    if (!hasInitiallyScrolled) {
      // Wait a bit longer to ensure the container is rendered
      setTimeout(() => {
        const container = messagesContainerRef.current;
        if (container) {
          scrollToBottom(false); // Instant scroll on initial load
          setHasInitiallyScrolled(true);
        }
      }, 200);
      return;
    }

    // For new messages, only auto-scroll if user is near bottom or should auto-scroll
    if (shouldAutoScroll || isNearBottomRef.current) {
      setTimeout(() => {
        const container = messagesContainerRef.current;
        if (container) {
          scrollToBottom(true); // Smooth scroll for new messages
          setShouldAutoScroll(false);
        }
      }, 50);
    }
  }, [messages.length, hasInitiallyScrolled, shouldAutoScroll]);

  // Track scroll position
  useEffect(() => {
    const container = messagesContainerRef.current;
    if (!container) return;

    const handleScroll = () => {
      checkIfNearBottom();
    };

    container.addEventListener('scroll', handleScroll);
    return () => container.removeEventListener('scroll', handleScroll);
  }, []);

  // Auto-focus input after sending message
  useEffect(() => {
    if (!isSending && messageInput === "") {
      inputRef.current?.focus();
    }
  }, [isSending, messageInput]);

  // Load messages when conversation changes. Defer realtime so React Strict Mode unmount doesn't call removeChannel before connect.
  useEffect(() => {
    if (conversation) {
      setHasInitiallyScrolled(false);
      setShouldAutoScroll(false);
      loadMessages();
      let cancelled = false;
      let unsubscribe: (() => void) | null = null;
      const timer = setTimeout(() => {
        if (!cancelled) unsubscribe = subscribeToMessages();
      }, 200);
      setTimeout(() => inputRef.current?.focus(), 100);
      return () => {
        cancelled = true;
        clearTimeout(timer);
        if (unsubscribe) {
          try {
            unsubscribe();
          } catch {
            // Ignore when channel is still connecting
          }
        }
      };
    } else {
      setMessages([]);
      setHasInitiallyScrolled(false);
    }
  }, [conversation?.id]);

  const scrollToBottom = (smooth: boolean = true) => {
    // Scroll the messages container, not the entire page
    const container = messagesContainerRef.current;
    if (container) {
      // Prevent any window/document scrolling
      const scrollTop = window.scrollY || document.documentElement.scrollTop;

      container.scrollTo({
        top: container.scrollHeight,
        behavior: smooth ? "smooth" : "auto"
      });

      // Restore window scroll position if it changed (shouldn't happen, but safety check)
      requestAnimationFrame(() => {
        if (window.scrollY !== scrollTop || document.documentElement.scrollTop !== scrollTop) {
          window.scrollTo(0, scrollTop);
        }
      });
    }
  };

  const loadMessages = async () => {
    if (!conversation) return;
    try {
      setIsLoading(true);
      const endpoint = messagesEndpoint
        ? `/api/provider/conversations/${conversation.id}/messages`
        : `/api/me/messages?conversation_id=${conversation.id}`;
      const response = await fetcher.get<any>(endpoint);
      // Normalize: API may return { data: [...] }, { data: { messages: [...] } }, { messages: [...] }, or raw array
      const data = response && typeof response === "object" && "data" in response ? (response as { data: any }).data : response;
      let raw: any = [];
      if (Array.isArray(data)) {
        raw = data;
      } else if (data && typeof data === "object" && "messages" in data) {
        const m = (data as { messages: any }).messages;
        raw = Array.isArray(m) ? m : [];
      } else if (data && typeof data === "object" && "data" in data) {
        const d = (data as { data: any }).data;
        raw = Array.isArray(d) ? d : [];
      }
      const list: Message[] = Array.isArray(raw) ? raw : [];
      const transformed = list.map((msg: any) => ({
        ...msg,
        sender_role: msg.sender_type || msg.sender_role,
      }));
      transformed.sort((a, b) =>
        new Date(a.created_at).getTime() - new Date(b.created_at).getTime()
      );
      setMessages(transformed);
    } catch (err) {
      setMessages([]);
      toast.error("Failed to load messages");
      console.error("Error loading messages:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const subscribeToMessages = () => {
    if (!conversation) return () => {};

    const supabase = getSupabaseClient();
    const channelName = `messages:${conversation.id}`;
    const channel = supabase
      .channel(channelName)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "messages",
          filter: `conversation_id=eq.${conversation.id}`,
        },
        (payload) => {
          const newMessage = payload.new as Message;
          setMessages((prev) => {
            const safePrev = Array.isArray(prev) ? prev : [];
            // Remove any temporary optimistic messages with same content from same sender
            const filtered = safePrev.filter((m) => 
              !(m.id.startsWith('temp-') && 
                m.sender_id === newMessage.sender_id && 
                m.content === newMessage.content &&
                Math.abs(new Date(m.created_at).getTime() - new Date(newMessage.created_at).getTime()) < 5000)
            );

            // Avoid duplicates (check by ID)
            if (filtered.some((m) => m.id === newMessage.id)) {
              return filtered;
            }

            // Add new message and sort to maintain order
            const updated = [...filtered, newMessage];
            updated.sort((a, b) => 
              new Date(a.created_at).getTime() - new Date(b.created_at).getTime()
            );

            // Auto-scroll if it's a new message from current user or user is near bottom
            const isOwnMessage = newMessage.sender_id === currentUserId;
            if (isOwnMessage || isNearBottomRef.current) {
              setShouldAutoScroll(true);
            }
            return updated;
          });
          // Only update conversation list if it's not our own message (to avoid duplicate updates)
          // For own messages, we already handled it optimistically
          if (onConversationUpdate && newMessage.sender_id !== currentUserId) {
            // Debounce the update to prevent excessive calls
            setTimeout(() => {
              onConversationUpdate();
            }, 500);
          }
        }
      )
      .on(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "messages",
          filter: `conversation_id=eq.${conversation.id}`,
        },
        (payload) => {
          // Update message read status when it's marked as read
          const updatedMessage = payload.new as Message;
          setMessages((prev) => {
            const safePrev = Array.isArray(prev) ? prev : [];
            return safePrev.map((msg) => 
              msg.id === updatedMessage.id
                ? { ...msg, read_at: updatedMessage.read_at, is_read: updatedMessage.is_read }
                : msg
            );
          });
        }
      )
      .subscribe((status) => {
        if (status === "SUBSCRIBED") {
          console.log(`Subscribed to messages for conversation ${conversation.id}`);
        }
      });

    return () => {
      try {
        supabase.removeChannel(channel);
      } catch {
        // Ignore when channel is still connecting (e.g. React Strict Mode unmount)
      }
    };
  };

  const sendMessage = async () => {
    if ((!messageInput.trim() && selectedFiles.length === 0) || !conversation || isSending || isUploading) return;

    const messageContent = messageInput.trim();
    const tempId = `temp-${Date.now()}`;
    let uploadedAttachments: Attachment[] = [];

    // Upload files first if any
    if (selectedFiles.length > 0) {
      try {
        setIsUploading(true);
        const formData = new FormData();
        formData.append("conversation_id", conversation.id);
        selectedFiles.forEach((file) => {
          formData.append("files", file);
        });

        const uploadResponse = await fetch("/api/me/messages/upload", {
          method: "POST",
          body: formData,
        });

        if (!uploadResponse.ok) {
          const error = await uploadResponse.json();
          throw new Error(error.error?.message || "Failed to upload files");
        }

        const uploadData = await uploadResponse.json();
        uploadedAttachments = uploadData.data?.attachments || [];
      } catch (err: any) {
        toast.error(err.message || "Failed to upload files");
        setIsUploading(false);
        return;
      } finally {
        setIsUploading(false);
      }
    }

    // Optimistic UI update - show message immediately
    const optimisticMessage: Message = {
      id: tempId,
      conversation_id: conversation.id,
      sender_id: currentUserId,
      content: messageContent || (uploadedAttachments.length > 0 ? "≡ƒôÄ Attachment" : ""),
      attachments: uploadedAttachments,
      created_at: new Date().toISOString(),
      read_at: undefined,
    };

    setMessages((prev) => {
      const safePrev = Array.isArray(prev) ? prev : [];
      const updated = [...safePrev, optimisticMessage];
      updated.sort((a, b) =>
        new Date(a.created_at).getTime() - new Date(b.created_at).getTime()
      );
      return updated;
    });
    setMessageInput("");
    clearFiles();
    setShouldAutoScroll(true); // Auto-scroll for own messages

    try {
      setIsSending(true);
      // Use custom endpoint if provided, otherwise use default
      if (messagesEndpoint) {
        // For provider endpoint: /api/provider/conversations/[id]/messages
        await fetcher.post(`/api/provider/conversations/${conversation.id}/messages`, {
          content: messageContent || "",
          attachments: uploadedAttachments,
        });
      } else {
        // For customer endpoint: /api/me/messages
        await fetcher.post("/api/me/messages", {
          conversation_id: conversation.id,
          content: messageContent || "",
          attachments: uploadedAttachments,
        });
      }
      // Real-time subscription will update with actual message (replacing temp one)
      // Don't call onConversationUpdate here - let the subscription handle it
      // This prevents duplicate reloads and keeps the UI seamless
    } catch (err) {
      // Remove optimistic message on error
      setMessages((prev) => (Array.isArray(prev) ? prev : []).filter((m) => m.id !== tempId));

      // Handle subscription limit errors with better messaging
      let errorMessage = "Failed to send message";
      if (err instanceof FetchError) {
        if (err.status === 403 && err.message?.includes("subscription")) {
          errorMessage = "Message limit reached. Please upgrade your plan to send more messages.";
        } else {
          errorMessage = err.message || "Failed to send message";
        }
      }

      toast.error(errorMessage);
      console.error("Error sending message:", err);
      // Restore message input and files
      setMessageInput(messageContent);
      setSelectedFiles(selectedFiles);
    } finally {
      setIsSending(false);
    }
  };

  const formatMessageTime = (dateString: string) => {
    const date = new Date(dateString);
    if (isToday(date)) {
      return format(date, "HH:mm");
    } else if (isYesterday(date)) {
      return "Yesterday";
    } else {
      return format(date, "dd/MM/yyyy");
    }
  };

  const getContactName = () => {
    if (!conversation) return "";
    // For provider chat, show customer name; for customer chat, show provider name
    if (isProviderChat) {
      return conversation.customer_name || "Customer";
    } else {
      return conversation.provider_name || "Provider";
    }
  };

  const getContactAvatar = () => {
    if (!conversation) return "";
    // For provider chat, show customer avatar; for customer chat, show provider avatar
    if (isProviderChat) {
      return conversation.customer_avatar || conversation.avatar || "";
    } else {
      return conversation.avatar || "";
    }
  };

  if (!conversation) {
    return (
      <div className="flex flex-col h-full bg-[#f0f2f5] items-center justify-center">
        <div className="text-center p-8">
          <div className="w-16 h-16 rounded-full bg-[#FF0077] mx-auto mb-4 flex items-center justify-center">
            <Send className="w-8 h-8 text-white" />
          </div>
          <p className="text-[#667781] text-sm">Select a conversation to start messaging</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-gray-100 overflow-hidden relative">
