];

const SKIN_TYPES = [
  { value: "dry", label: "Dry", icon: "≡ƒÅ£∩╕Å" },
  { value: "oily", label: "Oily", icon: "≡ƒÆº" },
  { value: "combination", label: "Combination", icon: "ΓÜû∩╕Å" },
  { value: "sensitive", label: "Sensitive", icon: "≡ƒî┐" },
  { value: "normal", label: "Normal", icon: "Γ£¿" },
];

const ALLERGY_SUGGESTIONS = [
  "Fragrance",
  "Parabens",
  "Sulfates",
  "Alcohol",
  "Dye",
  "Formaldehyde",
  "Latex",
  "Nickel",
];

const PREFERRED_TIMES = [
  { value: "morning", label: "Morning" },
  { value: "afternoon", label: "Afternoon" },
  { value: "evening", label: "Evening" },
];

const DAYS_OF_WEEK = [
  { value: "monday", label: "Mon" },
  { value: "tuesday", label: "Tue" },
  { value: "wednesday", label: "Wed" },
  { value: "thursday", label: "Thu" },
  { value: "friday", label: "Fri" },
  { value: "saturday", label: "Sat" },
  { value: "sunday", label: "Sun" },
];

export default function BeautyPreferencesCard({
  preferences = {},
  onUpdate,
}: BeautyPreferencesCardProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState<BeautyPreferences>(preferences);
  const [allergyInput, setAllergyInput] = useState("");
  const [otherAppointmentStyle, setOtherAppointmentStyle] = useState("");

  const hasChanges = JSON.stringify(formData) !== JSON.stringify(preferences);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await fetcher.patch("/api/me/beauty-preferences", formData);
      toast.success("Beauty preferences saved");
      onUpdate?.();
    } catch (error: any) {
      toast.error(error.message || "Failed to save preferences");
    } finally {
      setIsSaving(false);
    }
  };

  const handleAddAllergy = () => {
    if (!allergyInput.trim()) return;
    const newAllergies = [...(formData.allergies || []), allergyInput.trim()];
    setFormData({ ...formData, allergies: newAllergies });
    setAllergyInput("");
  };

  const handleRemoveAllergy = (allergy: string) => {
    const newAllergies = (formData.allergies || []).filter((a) => a !== allergy);
    setFormData({ ...formData, allergies: newAllergies });
  };

  const handleAddSuggestedAllergy = (allergy: string) => {
    if ((formData.allergies || []).includes(allergy)) return;
    const newAllergies = [...(formData.allergies || []), allergy];
    setFormData({ ...formData, allergies: newAllergies });
  };

  const togglePreferredTime = (time: string) => {
    const current = formData.preferred_times || [];
    if (current.includes(time)) {
      setFormData({
        ...formData,
        preferred_times: current.filter((t) => t !== time),
      });
    } else {
      setFormData({
        ...formData,
        preferred_times: [...current, time],
      });
    }
  };

  const togglePreferredDay = (day: string) => {
    const current = formData.preferred_days || [];
    if (current.includes(day)) {
      setFormData({
        ...formData,
        preferred_days: current.filter((d) => d !== day),
      });
    } else {
      setFormData({
        ...formData,
        preferred_days: [...current, day],
      });
    }
  };

  return (
    <div className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl overflow-hidden">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="w-full p-6 flex items-center justify-between hover:bg-white/40 transition-colors"
        aria-expanded={isOpen}
      >
        <h3 className="text-lg font-semibold tracking-tight text-zinc-900">
          Beauty Preferences
        </h3>
        {isOpen ? (
          <ChevronUp className="h-5 w-5 text-zinc-500" />
        ) : (
          <ChevronDown className="h-5 w-5 text-zinc-500" />
        )}
      </button>

      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.3 }}
            className="overflow-hidden"
          >
            <div className="px-6 pb-6 space-y-6 border-t border-white/40">
              {/* Info Banner */}
              <div className="flex items-start gap-3 p-4 bg-blue-50/80 border border-blue-200/50 rounded-xl">
                <Info className="h-5 w-5 text-blue-600 flex-shrink-0 mt-0.5" />
                <p className="text-sm text-blue-800">
                  Provides data when you book. Helps them prepare for your appointment.
                </p>
              </div>

              {/* Hair Type */}
              <div>
                <label className="text-sm font-medium text-zinc-900 mb-3 block">
                  Hair Type/Texture
                </label>
                <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
                  {HAIR_TYPES.map((type) => (
                    <motion.button
                      key={type.value}
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      onClick={() => setFormData({ ...formData, hair_type: type.value })}
                      className={`
                        p-4 rounded-xl border-2 transition-all
                        ${
                          formData.hair_type === type.value
                              ? "bg-[#FF0077] text-white border-[#FF0077] shadow-lg"
                              : "bg-white/60 border-zinc-200 hover:border-zinc-300 text-zinc-700"
                        }
                      `}
                    >
                      <div className="text-2xl mb-1">{type.icon}</div>
                      <div className="text-xs font-medium">{type.label}</div>
                    </motion.button>
                  ))}
                </div>
              </div>

              {/* Skin Type */}
              <div>
                <label className="text-sm font-medium text-zinc-900 mb-3 block">
                  Skin Type
                </label>
                <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
                  {SKIN_TYPES.map((type) => (
                    <motion.button
                      key={type.value}
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      onClick={() => setFormData({ ...formData, skin_type: type.value })}
                      className={`
                        p-4 rounded-xl border-2 transition-all
                        ${
                          formData.skin_type === type.value
                              ? "bg-[#FF0077] text-white border-[#FF0077] shadow-lg"
                              : "bg-white/60 border-zinc-200 hover:border-zinc-300 text-zinc-700"
                        }
                      `}
                    >
                      <div className="text-2xl mb-1">{type.icon}</div>
                      <div className="text-xs font-medium">{type.label}</div>
                    </motion.button>
                  ))}
                </div>
              </div>

              {/* Allergies */}
              <div>
                <label className="text-sm font-medium text-zinc-900 mb-3 block">
                  Allergies & Sensitivities
                </label>
                <div className="space-y-3">
                  <div className="flex gap-2">
                    <input
                      type="text"
                      value={allergyInput}
                      onChange={(e) => setAllergyInput(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          e.preventDefault();
                          handleAddAllergy();
                        }
                      }}
                      placeholder="Add allergy or sensitivity"
                      className="flex-1 px-4 py-2 border border-zinc-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#FF0077] text-sm"
                    />
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={handleAddAllergy}
                      className="border-zinc-300"
                    >
                      <Plus className="h-4 w-4 mr-1" />
                      Add
                    </Button>
                  </div>
                  {ALLERGY_SUGGESTIONS.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {ALLERGY_SUGGESTIONS.map((allergy) => (
                        <motion.button
                          key={allergy}
                          whileHover={{ scale: 1.05 }}
                          whileTap={{ scale: 0.95 }}
                          onClick={() => handleAddSuggestedAllergy(allergy)}
                          disabled={(formData.allergies || []).includes(allergy)}
                          className={`
                            px-3 py-1.5 rounded-full text-xs font-medium border transition-all
                            ${
                              (formData.allergies || []).includes(allergy)
                                ? "bg-zinc-200 text-zinc-500 border-zinc-300 cursor-not-allowed"
                                : "bg-white/60 text-zinc-700 border-zinc-300 hover:bg-zinc-50"
                            }
                          `}
                        >
                          + {allergy}
                        </motion.button>
                      ))}
                    </div>
                  )}
                  {formData.allergies && formData.allergies.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {formData.allergies.map((allergy) => (
                        <motion.span
                          key={allergy}
                          initial={{ opacity: 0, scale: 0.8 }}
                          animate={{ opacity: 1, scale: 1 }}
                          className="px-3 py-1.5 rounded-full text-xs font-medium bg-[#FF0077] text-white flex items-center gap-2 group"
                        >
                          {allergy}
                          <button
                            onClick={() => handleRemoveAllergy(allergy)}
                            className="hover:bg-white/20 rounded-full p-0.5 transition-colors"
                            aria-label={`Remove ${allergy}`}
                          >
                            <X className="h-3 w-3" />
                          </button>
                        </motion.span>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              {/* Things to Avoid */}
              <div>
                <label htmlFor="things-to-avoid" className="text-sm font-medium text-zinc-900 mb-2 block">
                  Things to Avoid
                </label>
                <Textarea
                  id="things-to-avoid"
                  value={formData.things_to_avoid || ""}
                  onChange={(e) =>
                    setFormData({ ...formData, things_to_avoid: e.target.value })
                  }
                  placeholder="List any products, ingredients, or techniques to avoid"
                  rows={3}
                  maxLength={200}
                  className="border-zinc-300 focus:ring-[#FF0077]"
                />
              </div>

              {/* Appointment Style */}
              <div>
                <label className="text-sm font-medium text-zinc-900 mb-3 block">
                  Appointment Style
                </label>
                <AppointmentStyleToggle
                  value={formData.appointment_style || ""}
                  onChange={(value) => setFormData({ ...formData, appointment_style: value })}
                  otherValue={otherAppointmentStyle}
                  onOtherChange={setOtherAppointmentStyle}
                />
              </div>

              {/* Preferred Times */}
              <div>
                <label className="text-sm font-medium text-zinc-900 mb-3 block">
                  Preferred Times
                </label>
                <div className="flex flex-wrap gap-2">
                  {PREFERRED_TIMES.map((time) => {
                    const isSelected = (formData.preferred_times || []).includes(time.value);
                    return (
                      <motion.button
                        key={time.value}
                        whileHover={{ scale: 1.05 }}
                        whileTap={{ scale: 0.95 }}
                        onClick={() => togglePreferredTime(time.value)}
                        className={`
                          px-4 py-2 rounded-full text-sm font-medium border-2 transition-all
                          ${
                            isSelected
                              ? "bg-zinc-900 text-white border-zinc-900 shadow-lg"
                              : "bg-white/60 text-zinc-700 border-zinc-200 hover:border-zinc-300"
                          }
                        `}
                      >
                        {time.label}
                      </motion.button>
                    );
                  })}
                </div>
              </div>

              {/* Preferred Days */}
              <div>
                <label className="text-sm font-medium text-zinc-900 mb-3 block">
                  Preferred Days
                </label>
                <div className="grid grid-cols-4 md:grid-cols-7 gap-2">
                  {DAYS_OF_WEEK.map((day) => {
                    const isSelected = (formData.preferred_days || []).includes(day.value);
                    return (
                      <motion.button
                        key={day.value}
                        whileHover={{ scale: 1.05 }}
                        whileTap={{ scale: 0.95 }}
                        onClick={() => togglePreferredDay(day.value)}
                        className={`
                          px-3 py-2 rounded-lg text-xs font-medium border-2 transition-all
                          ${
                            isSelected
                              ? "bg-zinc-900 text-white border-zinc-900 shadow-lg"
                              : "bg-white/60 text-zinc-700 border-zinc-200 hover:border-zinc-300"
                          }
                        `}
                      >
                        {day.label}
                      </motion.button>
                    );
                  })}
                </div>
              </div>

              {/* Save Button */}
              {hasChanges && (
                <div className="pt-4 border-t border-zinc-200">
                  <Button
                    onClick={handleSave}
                    disabled={isSaving}
                    className="w-full bg-[#FF0077] hover:bg-[#E6006A] text-white"
                  >
                    {isSaving ? "Saving..." : "Save Preferences"}
                  </Button>
                </div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

// iOS Focus-mode style toggle
interface AppointmentStyleToggleProps {
  value: string;
  onChange: (value: string) => void;
  otherValue: string;
  onOtherChange: (value: string) => void;
}

function AppointmentStyleToggle({
  value,
  onChange,
  otherValue,
  onOtherChange,
}: AppointmentStyleToggleProps) {
  const [showOther, setShowOther] = useState(value === "other" || !!otherValue);

  return (
    <div className="space-y-3">
      <div className="relative inline-flex p-1 bg-zinc-100 rounded-full border border-zinc-200">
        <motion.div
          className="absolute inset-y-1 left-1 bg-white rounded-full shadow-sm"
          style={{
            width: "calc(33.333% - 0.25rem)",
          }}
          animate={{
            x: value === "quiet" ? 0 : value === "chatty" ? "100%" : "200%",
          }}
          transition={{ type: "spring", stiffness: 300, damping: 30 }}
        />
        <div className="relative flex gap-1">
          {["quiet", "chatty", "other"].map((option) => (
            <button
              key={option}
              onClick={() => {
                onChange(option);
                if (option === "other") {
                  setShowOther(true);
                } else {
                  setShowOther(false);
                  onOtherChange("");
                }
              }}
              className={`
                relative z-10 px-6 py-2 rounded-full text-sm font-medium transition-colors
                ${
                  value === option
                    ? "text-[#FF0077] font-semibold"
                    : "text-zinc-500 hover:text-zinc-700"
                }
              `}
            >
              {option === "quiet" ? "Quiet" : option === "chatty" ? "Chatty" : "Other"}
            </button>
          ))}
        </div>
      </div>
      {showOther && (
        <motion.div
          initial={{ opacity: 0, height: 0 }}
          animate={{ opacity: 1, height: "auto" }}
          exit={{ opacity: 0, height: 0 }}
        >
          <input
            type="text"
            value={otherValue}
            onChange={(e) => {
              onOtherChange(e.target.value);
              if (e.target.value) onChange("other");
            }}
            placeholder="Describe your preference"
            className="w-full px-4 py-2 border border-zinc-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#FF0077] text-sm"
          />
        </motion.div>
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { ChevronDown, ChevronUp, Info } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { fetcher } from "@/lib/http/fetcher";

interface BeautyPreferences {
  hair_type?: string;
  skin_type?: string;
  allergies?: string[];
  things_to_avoid?: string;
  appointment_style?: string;
  preferred_times?: string[];
  preferred_days?: string[];
  product_preferences?: string;
}

interface BeautyPreferencesSectionProps {
  preferences: BeautyPreferences;
  onUpdate?: () => void;
}

const HAIR_TYPES = [
  { value: "straight", label: "Straight" },
  { value: "wavy", label: "Wavy" },
  { value: "curly", label: "Curly" },
  { value: "coily", label: "Coily" },
  { value: "other", label: "Other" },
];

const SKIN_TYPES = [
  { value: "dry", label: "Dry" },
  { value: "oily", label: "Oily" },
  { value: "combination", label: "Combination" },
  { value: "sensitive", label: "Sensitive" },
  { value: "normal", label: "Normal" },
];

const APPOINTMENT_STYLES = [
  { value: "quiet", label: "Quiet" },
  { value: "chatty", label: "Chatty" },
  { value: "either", label: "Either" },
];

const PREFERRED_TIMES = [
  { value: "morning", label: "Morning" },
  { value: "afternoon", label: "Afternoon" },
  { value: "evening", label: "Evening" },
];

const DAYS_OF_WEEK = [
  { value: "monday", label: "Monday" },
  { value: "tuesday", label: "Tuesday" },
  { value: "wednesday", label: "Wednesday" },
  { value: "thursday", label: "Thursday" },
  { value: "friday", label: "Friday" },
  { value: "saturday", label: "Saturday" },
  { value: "sunday", label: "Sunday" },
];

const ALLERGY_SUGGESTIONS = [
  "Fragrance",
  "Parabens",
  "Sulfates",
  "Alcohol",
  "Dyes",
  "Formaldehyde",
  "Latex",
  "Nickel",
];

export default function BeautyPreferencesSection({
  preferences = {},
  onUpdate,
}: BeautyPreferencesSectionProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState<BeautyPreferences>(preferences);
  const [allergyInput, setAllergyInput] = useState("");

  useEffect(() => {
    setFormData(preferences);
  }, [preferences]);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await fetcher.patch("/api/me/beauty-preferences", formData);
      toast.success("Beauty preferences saved");
      onUpdate?.();
    } catch (error: any) {
      toast.error(error.message || "Failed to save preferences");
    } finally {
      setIsSaving(false);
    }
  };

  const handleAddAllergy = () => {
    if (!allergyInput.trim()) return;
    const newAllergies = [...(formData.allergies || []), allergyInput.trim()];
    setFormData({ ...formData, allergies: newAllergies });
    setAllergyInput("");
  };

  const handleRemoveAllergy = (allergy: string) => {
    const newAllergies = (formData.allergies || []).filter((a) => a !== allergy);
    setFormData({ ...formData, allergies: newAllergies });
  };

  const handleAddSuggestedAllergy = (allergy: string) => {
    if ((formData.allergies || []).includes(allergy)) return;
    const newAllergies = [...(formData.allergies || []), allergy];
    setFormData({ ...formData, allergies: newAllergies });
  };

  const hasChanges = JSON.stringify(formData) !== JSON.stringify(preferences);

  return (
    <Card id="beauty-preferences-section" className="w-full bg-white border border-gray-200 shadow-sm">
      <Collapsible open={isOpen} onOpenChange={setIsOpen}>
        <CollapsibleTrigger asChild>
          <CardHeader className="cursor-pointer hover:bg-gray-50 transition-colors bg-white border-b border-gray-200">
            <div className="flex items-center justify-between">
              <CardTitle className="text-lg font-semibold text-gray-900">
                Beauty Preferences
              </CardTitle>
              {isOpen ? (
                <ChevronUp className="w-5 h-5 text-gray-500" />
              ) : (
                <ChevronDown className="w-5 h-5 text-gray-500" />
              )}
            </div>
          </CardHeader>
        </CollapsibleTrigger>
        <CollapsibleContent className="overflow-hidden transition-all duration-300 data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down">
          <CardContent className="pt-4 bg-white space-y-6">
            <div className="flex items-start gap-2 p-3 bg-blue-50 border border-blue-200 rounded-lg">
              <Info className="h-4 w-4 text-blue-600 flex-shrink-0 mt-0.5" />
              <p className="text-sm text-blue-800">
                Providers see this when you book. Helps them prepare for your appointment.
              </p>
            </div>

            {/* Hair Type */}
            <div>
              <Label htmlFor="hair-type">Hair Type/Texture</Label>
              <Select
                value={formData.hair_type || ""}
                onValueChange={(value) =>
                  setFormData({ ...formData, hair_type: value })
                }
              >
                <SelectTrigger id="hair-type">
                  <SelectValue placeholder="Select hair type" />
                </SelectTrigger>
                <SelectContent>
                  {HAIR_TYPES.map((type) => (
                    <SelectItem key={type.value} value={type.value}>
                      {type.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Skin Type */}
            <div>
              <Label htmlFor="skin-type">Skin Type</Label>
              <Select
                value={formData.skin_type || ""}
                onValueChange={(value) =>
                  setFormData({ ...formData, skin_type: value })
                }
              >
                <SelectTrigger id="skin-type">
                  <SelectValue placeholder="Select skin type" />
                </SelectTrigger>
                <SelectContent>
                  {SKIN_TYPES.map((type) => (
                    <SelectItem key={type.value} value={type.value}>
                      {type.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Allergies */}
            <div>
              <Label htmlFor="allergies">Allergies & Sensitivities</Label>
              <div className="mt-2 space-y-2">
                <div className="flex gap-2">
                  <input
                    id="allergies"
                    type="text"
                    value={allergyInput}
                    onChange={(e) => setAllergyInput(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        e.preventDefault();
                        handleAddAllergy();
                      }
                    }}
                    placeholder="Add allergy or sensitivity"
                    className="flex-1 px-3 py-2 border border-gray-300 rounded-md text-sm"
                  />
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={handleAddAllergy}
                  >
                    Add
                  </Button>
                </div>
                {ALLERGY_SUGGESTIONS.length > 0 && (
                  <div className="flex flex-wrap gap-2">
                    {ALLERGY_SUGGESTIONS.map((allergy) => (
                      <Badge
                        key={allergy}
                        variant="outline"
                        className="cursor-pointer hover:bg-gray-100"
                        onClick={() => handleAddSuggestedAllergy(allergy)}
                      >
                        + {allergy}
                      </Badge>
                    ))}
                  </div>
                )}
                {formData.allergies && formData.allergies.length > 0 && (
                  <div className="flex flex-wrap gap-2">
                    {formData.allergies.map((allergy) => (
                      <Badge
                        key={allergy}
                        variant="default"
                        className="bg-gray-100 text-gray-700 hover:bg-gray-200"
                      >
                        {allergy}
                        <button
                          onClick={() => handleRemoveAllergy(allergy)}
                          className="ml-2 hover:text-red-600"
                        >
                          ├ù
                        </button>
                      </Badge>
                    ))}
                  </div>
                )}
              </div>
            </div>

            {/* Things to Avoid */}
            <div>
              <Label htmlFor="things-to-avoid">Things to Avoid</Label>
              <Textarea
                id="things-to-avoid"
                value={formData.things_to_avoid || ""}
                onChange={(e) =>
                  setFormData({ ...formData, things_to_avoid: e.target.value })
                }
                placeholder="List any products, ingredients, or techniques to avoid"
                rows={3}
                maxLength={200}
              />
            </div>

            {/* Appointment Style */}
            <div>
              <Label>Appointment Style</Label>
              <RadioGroup
                value={formData.appointment_style || ""}
                onValueChange={(value) =>
                  setFormData({ ...formData, appointment_style: value })
                }
                className="mt-2"
              >
                {APPOINTMENT_STYLES.map((style) => (
                  <div key={style.value} className="flex items-center space-x-2">
                    <RadioGroupItem value={style.value} id={style.value} />
                    <Label htmlFor={style.value} className="font-normal cursor-pointer">
                      {style.label}
                    </Label>
                  </div>
                ))}
              </RadioGroup>
            </div>

            {/* Preferred Times */}
            <div>
              <Label>Preferred Times</Label>
              <div className="mt-2 space-y-2">
                {PREFERRED_TIMES.map((time) => (
                  <div key={time.value} className="flex items-center space-x-2">
                    <Checkbox
                      id={time.value}
                      checked={(formData.preferred_times || []).includes(time.value)}
                      onCheckedChange={(checked) => {
                        const current = formData.preferred_times || [];
                        if (checked) {
                          setFormData({
                            ...formData,
                            preferred_times: [...current, time.value],
                          });
                        } else {
                          setFormData({
                            ...formData,
                            preferred_times: current.filter((t) => t !== time.value),
                          });
                        }
                      }}
                    />
                    <Label htmlFor={time.value} className="font-normal cursor-pointer">
                      {time.label}
                    </Label>
                  </div>
                ))}
              </div>
            </div>

            {/* Preferred Days */}
            <div>
              <Label>Preferred Days</Label>
              <div className="mt-2 grid grid-cols-2 gap-2">
                {DAYS_OF_WEEK.map((day) => (
                  <div key={day.value} className="flex items-center space-x-2">
                    <Checkbox
                      id={day.value}
                      checked={(formData.preferred_days || []).includes(day.value)}
                      onCheckedChange={(checked) => {
                        const current = formData.preferred_days || [];
                        if (checked) {
                          setFormData({
                            ...formData,
                            preferred_days: [...current, day.value],
                          });
                        } else {
                          setFormData({
                            ...formData,
                            preferred_days: current.filter((d) => d !== day.value),
                          });
                        }
                      }}
                    />
                    <Label htmlFor={day.value} className="font-normal cursor-pointer text-sm">
                      {day.label}
                    </Label>
                  </div>
                ))}
              </div>
            </div>

            {/* Product Preferences */}
            <div>
              <Label htmlFor="product-preferences">Product Preferences (Optional)</Label>
              <Textarea
                id="product-preferences"
                value={formData.product_preferences || ""}
                onChange={(e) =>
                  setFormData({ ...formData, product_preferences: e.target.value })
                }
                placeholder="Any specific product preferences or brands you prefer"
                rows={3}
                maxLength={200}
              />
            </div>

            {/* Save Button */}
            {hasChanges && (
              <div className="pt-4 border-t">
                <Button
                  onClick={handleSave}
                  disabled={isSaving}
                  className="w-full bg-[#FF0077] hover:bg-[#E6006A] text-white"
                >
                  {isSaving ? "Saving..." : "Save Preferences"}
                </Button>
              </div>
            )}
          </CardContent>
        </CollapsibleContent>
      </Collapsible>
    </Card>
  );
}

"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  ChevronDown,
  ChevronUp,
  Edit,
  Plus,
  Check,
  Lock,
  Shield,
  X,
  Eye,
} from "lucide-react";
import Image from "next/image";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { fetcher } from "@/lib/http/fetcher";
import type { ProfileUser } from "@/types/profile";

interface PersonalInfoCardProps {
  user: ProfileUser;
  onUpdate?: () => void;
}

interface EditModalProps {
  type: string;
  isOpen: boolean;
  onClose: () => void;
  onSave: (data: any) => Promise<void>;
  initialData?: any;
  user?: ProfileUser;
}

function EditModal({ type, isOpen, onClose, onSave, initialData, user }: EditModalProps) {
  const [formData, setFormData] = useState<any>(initialData || {});
  const [isSaving, setIsSaving] = useState(false);

  React.useEffect(() => {
    if (isOpen && initialData) {
      setFormData(initialData);
    }
  }, [isOpen, initialData]);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      await onSave(formData);
      onClose();
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.95 }}
        className="bg-white rounded-2xl p-6 max-w-md w-full shadow-2xl max-h-[90vh] overflow-y-auto"
      >
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-lg font-semibold">
            {type === "legalName" && "Legal Name"}
            {type === "preferredName" && "Preferred Name"}
            {type === "email" && "Email Address"}
            {type === "phone" && "Phone Number"}
            {type === "address" && "Address"}
            {type === "emergencyContact" && "Emergency Contact"}
            {type === "identity" && "Government ID"}
          </h3>
          <button
            onClick={onClose}
            className="text-zinc-500 hover:text-zinc-700"
            aria-label="Close"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {type === "legalName" && (
            <>
              <div>
                <Label htmlFor="first_name">First Name</Label>
                <Input
                  id="first_name"
                  value={formData.first_name || ""}
                  onChange={(e) => setFormData({ ...formData, first_name: e.target.value })}
                  required
                />
              </div>
              <div>
                <Label htmlFor="last_name">Last Name</Label>
                <Input
                  id="last_name"
                  value={formData.last_name || ""}
                  onChange={(e) => setFormData({ ...formData, last_name: e.target.value })}
                  required
                />
              </div>
            </>
          )}

          {type === "preferredName" && (
            <div>
              <Label htmlFor="preferred_name">Preferred Name</Label>
              <Input
                id="preferred_name"
                value={formData.preferred_name || ""}
                onChange={(e) => setFormData({ ...formData, preferred_name: e.target.value })}
                placeholder="How you'd like to be addressed"
              />
            </div>
          )}

          {type === "email" && (
            <div>
              <Label htmlFor="email">Email Address</Label>
              <Input
                id="email"
                type="email"
                value={formData.email || ""}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                required
              />
              <p className="text-xs text-zinc-500 mt-1">
                You'll need to verify your new email address
              </p>
            </div>
          )}

          {type === "phone" && (
            <div>
              <Label htmlFor="phone">Phone Number</Label>
              <Input
                id="phone"
                type="tel"
                value={formData.phone || ""}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                placeholder="+27 12 345 6789"
              />
            </div>
          )}

          {type === "address" && (
            <>
              <div>
                <Label htmlFor="line1">Street Address</Label>
                <Input
                  id="line1"
                  value={formData.line1 || ""}
                  onChange={(e) => setFormData({ ...formData, line1: e.target.value })}
                />
              </div>
              <div>
                <Label htmlFor="line2">Apt, Suite (optional)</Label>
                <Input
                  id="line2"
                  value={formData.line2 || ""}
                  onChange={(e) => setFormData({ ...formData, line2: e.target.value })}
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="city">City</Label>
                  <Input
                    id="city"
                    value={formData.city || ""}
                    onChange={(e) => setFormData({ ...formData, city: e.target.value })}
                  />
                </div>
                <div>
                  <Label htmlFor="state">State/Province</Label>
                  <Input
                    id="state"
                    value={formData.state || ""}
                    onChange={(e) => setFormData({ ...formData, state: e.target.value })}
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="postal_code">Postal Code</Label>
                  <Input
                    id="postal_code"
                    value={formData.postal_code || ""}
                    onChange={(e) => setFormData({ ...formData, postal_code: e.target.value })}
                  />
                </div>
                <div>
                  <Label htmlFor="country">Country</Label>
                  <Input
                    id="country"
                    value={formData.country || ""}
                    onChange={(e) => setFormData({ ...formData, country: e.target.value })}
                  />
                </div>
              </div>
            </>
          )}

          {type === "emergencyContact" && (
            <>
              <div>
                <Label htmlFor="name">Name</Label>
                <Input
                  id="name"
                  value={formData.name || ""}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  required
                />
              </div>
              <div>
                <Label htmlFor="relationship">Relationship</Label>
                <Input
                  id="relationship"
                  value={formData.relationship || ""}
                  onChange={(e) => setFormData({ ...formData, relationship: e.target.value })}
                  placeholder="e.g., Spouse, Parent, Friend"
                />
              </div>
              <div>
                <Label htmlFor="phone">Phone Number</Label>
                <Input
                  id="phone"
                  type="tel"
                  value={formData.phone || ""}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  required
                />
              </div>
              <div>
                <Label htmlFor="email">Email (optional)</Label>
                <Input
                  id="email"
                  type="email"
                  value={formData.email || ""}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                />
              </div>
            </>
          )}

          {type === "identity" && (
            <div className="space-y-4">
              <p className="text-sm text-zinc-600">
                Upload a government-issued ID for identity verification. This helps keep our community safe.
              </p>

              {/* Show existing document if available */}
              {user?.identity_verification_document_url && (
                <div className="p-3 bg-zinc-50 rounded-lg border border-zinc-200">
                  <p className="text-xs font-medium text-zinc-700 mb-2">Current document:</p>
                  <div className="flex items-center gap-2">
                    <Shield className="h-4 w-4 text-zinc-600" />
                    <span className="text-xs text-zinc-600 flex-1">
                      {user.identity_verification_document_type || "Document"} uploaded
                    </span>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="text-xs h-7"
                      onClick={() => window.open(user.identity_verification_document_url!, '_blank')}
                    >
                      <Eye className="h-3 w-3 mr-1" />
                      View
                    </Button>
                  </div>
                  <p className="text-xs text-zinc-500 mt-2">
                    You can upload a new document to replace this one.
                  </p>
                </div>
              )}

              <div>
                <Label htmlFor="document_type">Document Type</Label>
                <select
                  id="document_type"
                  value={formData.document_type || user?.identity_verification_document_type || ""}
                  onChange={(e) => setFormData({ ...formData, document_type: e.target.value })}
                  className="w-full px-3 py-2 border border-zinc-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#FF0077]"
                  required
                >
                  <option value="">Select document type</option>
                  <option value="license">Driver's License</option>
                  <option value="passport">Passport</option>
                  <option value="identity">National ID</option>
                </select>
              </div>
              <div>
                <Label htmlFor="file">Upload Document</Label>
                <Input
                  id="file"
                  type="file"
                  accept="image/*,.pdf"
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) {
                      setFormData({ ...formData, file });
                      // Show preview for images
                      if (file.type.startsWith('image/')) {
                        const reader = new FileReader();
                        reader.onloadend = () => {
                          setFormData(prev => ({ ...prev, file, preview: reader.result as string }));
                        };
                        reader.readAsDataURL(file);
                      } else {
                        setFormData(prev => ({ ...prev, file, preview: null }));
                      }
                    }
                  }}
                  required={!user?.identity_verification_document_url}
                />
                {formData.preview && (
                  <div className="mt-2 relative w-full h-48">
                    <Image
                      src={formData.preview}
                      alt="Preview"
                      fill
                      className="object-contain border border-zinc-300 rounded-lg"
                      unoptimized
                    />
                  </div>
                )}
                {formData.file && !formData.preview && (
                  <p className="text-xs text-zinc-600 mt-2">
                    Selected: {formData.file.name} ({(formData.file.size / 1024 / 1024).toFixed(2)} MB)
                  </p>
                )}
                <p className="text-xs text-zinc-500 mt-1">
                  Accepted: JPEG, PNG, WebP, PDF (Max 10MB)
                </p>
              </div>
            </div>
          )}

          <div className="flex gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={onClose}
              className="flex-1"
              disabled={isSaving}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              className="flex-1 bg-[#FF0077] hover:bg-[#E6006A] text-white"
              disabled={isSaving}
            >
              {isSaving ? "Saving..." : "Save"}
            </Button>
          </div>
        </form>
      </motion.div>
    </div>
  );
}

export default function PersonalInfoCard({ user, onUpdate }: PersonalInfoCardProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [editModal, setEditModal] = useState<{ type: string; isOpen: boolean; initialData?: any }>({
    type: "",
    isOpen: false,
    initialData: undefined,
  });

  const formatPhone = (phone: string | null) => {
    if (!phone) return "Not provided";
    const cleaned = phone.replace(/\D/g, "");
    if (cleaned.length >= 4) {
      return `${cleaned.substring(0, 3)} *** ***${cleaned.substring(cleaned.length - 4)}`;
    }
    return phone;
  };

  const formatEmail = (email: string) => {
    const parts = email.split("@");
    if (parts[0].length > 0) {
      return `${parts[0].substring(0, 1)}****@${parts[1] || ""}`;
    }
    return email;
  };

  const getVerificationStatus = () => {
    const status = user.identity_verification_status || "none";
    const hasSubmittedAt = !!user.identity_verification_submitted_at;

    // Only show "Under Review" if status is pending AND there's a submitted_at date
    // This means an actual verification was submitted
    if (status === "approved") {
      return { text: "Verified", color: "text-emerald-700 bg-emerald-50 border-emerald-200" };
    }
    if (status === "pending" && hasSubmittedAt) {
      return { text: "Under Review", color: "text-amber-700 bg-amber-50 border-amber-200" };
    }
    if (status === "rejected") {
      return { text: "Rejected", color: "text-red-700 bg-red-50 border-red-200" };
    }
    // Default: Not verified (no submission or status is 'none')
    return { text: "Not verified", color: "text-zinc-600 bg-zinc-50 border-zinc-200" };
  };

  const verificationStatus = getVerificationStatus();

  const handleSave = async (type: string, data: any): Promise<void> => {
    try {
      if (type === "legalName") {
        await fetcher.patch("/api/me/profile", {
          first_name: data.first_name,
          last_name: data.last_name,
        });
        toast.success("Legal name updated");
      } else if (type === "preferredName") {
        await fetcher.patch("/api/me/profile", {
          preferred_name: data.preferred_name || null,
        });
        toast.success("Preferred name updated");
      } else if (type === "email") {
        await fetcher.patch("/api/me/profile", {
          email: data.email,
        });
        toast.success("Email updated. Please check your inbox to verify.");
      } else if (type === "phone") {
        await fetcher.patch("/api/me/profile", {
          phone: data.phone,
        });
        toast.success("Phone number updated");
      } else if (type === "address") {
        await fetcher.patch("/api/me/profile", {
          address: {
            line1: data.line1,
            line2: data.line2,
            city: data.city,
            state: data.state,
            postal_code: data.postal_code,
            country: data.country,
          },
        });
        toast.success("Address updated");
      } else if (type === "emergencyContact") {
        await fetcher.patch("/api/me/profile", {
          emergency_contact: {
            name: data.name,
            relationship: data.relationship,
            phone: data.phone,
            email: data.email,
          },
        });
        toast.success("Emergency contact updated");
      } else if (type === "identity") {
        const formData = new FormData();
        formData.append("file", data.file);
        formData.append("document_type", data.document_type);
        formData.append("country", data.country || user.address?.country || "South Africa");

        const response = await fetch("/api/me/verification", {
          method: "POST",
          body: formData,
        });

        if (!response.ok) {
          const error = await response.json();
          throw new Error(error.error?.message || "Failed to upload ID");
        }

        toast.success("Government ID uploaded successfully! It will be reviewed by our team.");
      }

      onUpdate?.();
    } catch (error: any) {
      throw error;
    }
  };

  const openEditModal = (type: string) => {
    let initialData: any = {};

    if (type === "legalName") {
      initialData = { first_name: user.first_name || "", last_name: user.last_name || "" };
    } else if (type === "preferredName") {
      initialData = { preferred_name: user.preferred_name || "" };
    } else if (type === "email") {
      initialData = { email: user.email || "" };
    } else if (type === "phone") {
      initialData = { phone: user.phone || "" };
    } else if (type === "address") {
      initialData = {
        line1: user.address?.line1 || "",
        line2: user.address?.line2 || "",
        city: user.address?.city || "",
        state: user.address?.state || "",
        postal_code: user.address?.postal_code || "",
        country: user.address?.country || "",
      };
    } else if (type === "emergencyContact") {
      initialData = {
        name: user.emergency_contact?.name || "",
        relationship: user.emergency_contact?.relationship || "",
        phone: user.emergency_contact?.phone || "",
        email: user.emergency_contact?.email || "",
      };
    } else if (type === "identity") {
      initialData = {
        document_type: user.identity_verification_document_type || "",
        country: user.address?.country || "South Africa",
        file: null,
        preview: null,
      };
    }

    setEditModal({ type, isOpen: true, initialData });
  };

  return (
    <>
      <div className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl overflow-hidden">
        <button
          onClick={() => setIsOpen(!isOpen)}
          className="w-full p-6 flex items-center justify-between hover:bg-white/40 transition-colors"
          aria-expanded={isOpen}
        >
          <h3 className="text-lg font-semibold tracking-tight text-zinc-900">
            Personal Information
          </h3>
          {isOpen ? (
            <ChevronUp className="h-5 w-5 text-zinc-500" />
          ) : (
            <ChevronDown className="h-5 w-5 text-zinc-500" />
          )}
        </button>

        <AnimatePresence>
          {isOpen && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: "auto", opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={{ duration: 0.3 }}
              className="overflow-hidden"
            >
              <div className="px-6 pb-6 space-y-4 border-t border-white/40">
                {/* Legal Name */}
                <InfoRow
                  label="Legal name"
                  value={`${user.first_name || ""} ${user.last_name || ""}`.trim() || "Not provided"}
                  onEdit={() => openEditModal("legalName")}
                />

                {/* Preferred Name */}
                <InfoRow
                  label="Preferred name"
                  value={user.preferred_name || "Not provided"}
                  onEdit={user.preferred_name ? () => openEditModal("preferredName") : undefined}
                  onAdd={!user.preferred_name ? () => openEditModal("preferredName") : undefined}
                />

                {/* Email */}
                <InfoRow
                  label="Email address"
                  value={formatEmail(user.email)}
                  verified={user.email_verified}
                  onEdit={() => openEditModal("email")}
                />

                {/* Phone */}
                <InfoRow
                  label="Phone number"
                  value={formatPhone(user.phone)}
                  verified={user.phone_verified}
                  onEdit={() => openEditModal("phone")}
                />

                {/* Government ID */}
                <div className="pt-2">
                  <div className="flex items-center justify-between mb-2">
                    <label className="text-sm font-medium text-zinc-900">Government ID</label>
                  </div>
                  <div className={`
                    p-4 rounded-xl border-2 ${verificationStatus.color}
                    flex items-start gap-3
                  `}>
                    <Shield className="h-5 w-5 flex-shrink-0 mt-0.5" />
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium mb-1">{verificationStatus.text}</p>
                      {user.identity_verification_status === "pending" && user.identity_verification_submitted_at && (
                        <p className="text-xs opacity-70 mb-2">
                          Verification Pending / Under Review
                        </p>
                      )}
                      {user.identity_verification_status === "rejected" && user.identity_verification_rejection_reason && (
                        <p className="text-xs opacity-70 mb-2">
                          {user.identity_verification_rejection_reason}
                        </p>
                      )}
                      <div className="flex flex-wrap gap-2 mt-2">
                        {user.identity_verification_document_url && user.identity_verification_id && (
                          <Button
                            size="sm"
                            variant="outline"
                            className="border-zinc-300 hover:bg-zinc-50"
                            onClick={async () => {
                              try {
                                const viewResponse = await fetcher.get<{ data?: { signed_url?: string } }>(`/api/me/verification/${user.identity_verification_id}/view`);
                                if (viewResponse.data?.signed_url) {
                                  window.open(viewResponse.data.signed_url, '_blank');
                                } else {
                                  toast.error("Failed to load document");
                                }
                              } catch (error: any) {
                                console.error("Error viewing document:", error);
                                if (error.message?.includes('Bucket not found') || error.message?.includes('not configured')) {
                                  toast.error("Storage not configured. Please contact support.");
                                } else {
                                  toast.error(error.message || "Failed to view document");
                                }
                              }
                            }}
                          >
                            <Eye className="h-4 w-4 mr-1" />
                            View uploaded document
                          </Button>
                        )}
                        {(user.identity_verification_status === "none" || 
                          user.identity_verification_status === "rejected" ||
                          (user.identity_verification_status === "pending" && !user.identity_verification_document_url)) && (
                          <Button
                            size="sm"
                            className="bg-[#FF0077] hover:bg-[#E6006A] text-white"
                            onClick={() => openEditModal("identity")}
                          >
                            {user.identity_verification_status === "rejected" ? "Upload new document" : "Start verification"}
                          </Button>
                        )}
                      </div>
                    </div>
                  </div>
                </div>

                {/* Address */}
                <InfoRow
                  label="Address"
                  value={
                    user.address?.line1
                      ? `${user.address.line1}, ${user.address.city || ""}`
                      : "Not provided"
                  }
                  isOptional
                  onEdit={user.address ? () => openEditModal("address") : undefined}
                  onAdd={!user.address ? () => openEditModal("address") : undefined}
                />

                {/* Emergency Contact */}
                <InfoRow
                  label="Emergency contact"
                  value={user.emergency_contact?.name || "Not provided"}
                  isPrivate
                  onEdit={user.emergency_contact?.name ? () => openEditModal("emergencyContact") : undefined}
                  onAdd={!user.emergency_contact?.name ? () => openEditModal("emergencyContact") : undefined}
                />
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      <EditModal
        type={editModal.type}
        isOpen={editModal.isOpen}
        onClose={() => setEditModal({ type: "", isOpen: false, initialData: undefined })}
        onSave={(data) => handleSave(editModal.type, data)}
        initialData={editModal.initialData}
        user={user}
      />
    </>
  );
}

interface InfoRowProps {
  label: string;
  value: string;
  verified?: boolean;
  isPrivate?: boolean;
  isOptional?: boolean;
  onEdit?: () => void;
  onAdd?: () => void;
}

function InfoRow({
  label,
  value,
  verified,
  isPrivate,
  isOptional,
  onEdit,
  onAdd,
}: InfoRowProps) {
  return (
    <div className="py-3 border-b border-zinc-200/50 last:border-0">
      <div className="flex items-start justify-between gap-4">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className="text-sm font-medium text-zinc-900">{label}</span>
            {verified && (
              <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-emerald-50 text-emerald-700 border border-emerald-200 flex items-center gap-1">
                <Check className="h-3 w-3" />
                Verified
              </span>
            )}
            {isPrivate && (
              <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-zinc-50 text-zinc-600 border border-zinc-200 flex items-center gap-1">
                <Lock className="h-3 w-3" />
                Private
              </span>
            )}
            {isOptional && (
              <span className="text-xs text-zinc-400">Optional</span>
            )}
          </div>
          <p className="text-sm text-zinc-600">{value}</p>
        </div>
        {onEdit && (
          <Button
            variant="ghost"
            size="sm"
            onClick={onEdit}
            className="text-zinc-600 hover:text-[#FF0077]"
          >
            <Edit className="h-4 w-4 mr-1" />
            Edit
          </Button>
        )}
        {onAdd && (
          <Button
            variant="ghost"
            size="sm"
            onClick={onAdd}
            className="text-zinc-600 hover:text-[#FF0077]"
          >
            <Plus className="h-4 w-4 mr-1" />
            Add
          </Button>
        )}
      </div>
    </div>
  );
}

"use client";
import React, { useState, useEffect } from 'react';
import { toast } from "sonner";
import { Edit, Plus, Check, Lock } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { ChevronDown, ChevronUp } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import Image from "next/image";
import VerificationStatusCard from "./VerificationStatusCard";

interface PersonalInfoData {
  legalName: { first: string; last: string };
  preferredName: string;
  email: string;
  phone: string;
  governmentId: string;
  address: {
    country: string;
    street: string;
    apt: string;
    city: string;
    state: string;
    zip: string;
  };
  emergencyContact: {
    name: string;
    relationship: string;
    language: string;
    email: string;
    countryCode: string;
    phone: string;
  };
}

interface ModalContent {
  type: keyof PersonalInfoData;
  title: string;
  description: string;
  fields: { name: string; label: string; type: string; options?: string[]; accept?: string }[];
}

interface Country {
  code: string;
  name: string;
  phone_country_code: string | null;
}

interface VerificationData {
  status: "none" | "pending" | "verified" | "failed";
  submittedAt?: Date;
  failureReason?: string;
}

interface PersonalInfoSectionProps {
  onUpdate?: () => void;
}

const InfoItem: React.FC<{ 
  label: string; 
  value: string; 
  onEdit?: () => void; 
  onAdd?: () => void;
  verified?: boolean;
  isPrivate?: boolean;
  isOptional?: boolean;
}> = ({ label, value, onEdit, onAdd, verified, isPrivate, isOptional }) => (
  <div className="mb-4 pb-4 border-b border-gray-200 last:border-0">
    <div className="flex justify-between items-center mb-1">
      <div className="flex items-center gap-2">
        <span className="font-medium text-sm text-gray-900">{label}</span>
        {verified && (
          <Badge variant="outline" className="text-xs border-green-300 text-green-700 bg-green-50">
            <Check className="w-3 h-3 mr-1" />
            Verified
          </Badge>
        )}
        {isPrivate && (
          <Badge variant="outline" className="text-xs border-gray-300 text-gray-600 bg-gray-50">
            <Lock className="w-3 h-3 mr-1" />
            Private
          </Badge>
        )}
        {isOptional && (
          <Badge variant="outline" className="text-xs border-gray-300 text-gray-500 bg-gray-50">
            Optional
          </Badge>
        )}
      </div>
      {onEdit && (
        <button 
          className="text-sm text-[#FF0077] hover:text-[#D60565] underline font-medium transition-colors flex items-center gap-1" 
          onClick={onEdit}
        >
          <Edit className="w-3 h-3" />
          Edit
        </button>
      )}
      {onAdd && (
        <button 
          className="text-sm text-[#FF0077] hover:text-[#D60565] underline font-medium transition-colors flex items-center gap-1" 
          onClick={onAdd}
        >
          <Plus className="w-3 h-3" />
          Add
        </button>
      )}
    </div>
    <span className="text-sm text-gray-600">{value}</span>
  </div>
);

export default function PersonalInfoSection({ onUpdate }: PersonalInfoSectionProps) {
  // Auto-open if there are missing personal info fields (check via URL hash or prop)
  const [isOpen, setIsOpen] = useState(() => {
    if (typeof window !== 'undefined') {
      return window.location.hash === '#personal-info';
    }
    return false;
  });
  const [modalContent, setModalContent] = useState<ModalContent | null>(null);
  const [personalInfo, setPersonalInfo] = useState<PersonalInfoData>({
    legalName: { first: '', last: '' },
    preferredName: 'Not provided',
    email: '',
    phone: '',
    governmentId: 'Not provided',
    address: {
      country: '',
      street: '',
      apt: '',
      city: '',
      state: '',
      zip: '',
    },
    emergencyContact: {
      name: '',
      relationship: '',
      language: '',
      email: '',
      countryCode: '',
      phone: '',
    },
  });
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [countries, setCountries] = useState<Country[]>([]);
  const [defaultCountryCode, setDefaultCountryCode] = useState<string>("+27");
  const [defaultCountry, setDefaultCountry] = useState<string>("South Africa");
  const [languages, _setLanguages] = useState<string[]>(['English']);
  const [emailVerified, setEmailVerified] = useState(false);
  const [phoneVerified, setPhoneVerified] = useState(false);
  const [verificationData, setVerificationData] = useState<VerificationData>({ status: "none" });

  // Load data
  useEffect(() => {
    const loadData = async () => {
      try {
        setIsLoading(true);

        const [countriesResponse, settingsResponse, profileResponse] = await Promise.all([
          fetch("/api/public/countries"),
          fetch("/api/public/platform-settings"),
          fetch("/api/me/profile")
        ]);

        let loadedCountries: Country[] = [];
        if (countriesResponse.ok) {
          const countriesData = await countriesResponse.json();
          loadedCountries = countriesData.data || [];
          setCountries(loadedCountries);
        }

        if (settingsResponse.ok) {
          const settingsData = await settingsResponse.json();
          const defaultCountryCodeFromSettings = settingsData.data?.default_country_code || "+27";
          setDefaultCountryCode(defaultCountryCodeFromSettings);

          const country = loadedCountries.find(c => c.phone_country_code === defaultCountryCodeFromSettings);
          if (country) {
            setDefaultCountry(country.name);
          } else {
            const fallbackCountry = loadedCountries.find(c => c.code === "ZA") || loadedCountries[0];
            if (fallbackCountry) {
              setDefaultCountry(fallbackCountry.name);
            }
          }
        }

        if (profileResponse.ok) {
          const data = await profileResponse.json();
          const profile = data.data;

          setEmailVerified(profile.email_verified || false);
          setPhoneVerified(profile.phone_verified || false);

          // Set verification status
          const verificationStatus = profile.identity_verification_status || 'none';
          setVerificationData({
            status: verificationStatus === 'approved' ? 'verified' : verificationStatus === 'rejected' ? 'failed' : verificationStatus,
            submittedAt: profile.identity_verification_submitted_at ? new Date(profile.identity_verification_submitted_at) : undefined,
            failureReason: profile.identity_verification_rejection_reason,
          });

          let maskedEmail = '';
          if (profile.email) {
            const emailParts = profile.email.split('@');
            if (emailParts[0].length > 0) {
              maskedEmail = `${emailParts[0].substring(0, 1)}****@${emailParts[1] || ''}`;
            } else {
              maskedEmail = profile.email;
            }
          }

          let maskedPhone = '';
          if (profile.phone) {
            const phoneStr = profile.phone.replace(/\D/g, '');
            if (phoneStr.length >= 4) {
              maskedPhone = `${phoneStr.substring(0, 3)} *** ***${phoneStr.substring(phoneStr.length - 4)}`;
            } else {
              maskedPhone = profile.phone;
            }
          }

          setPersonalInfo({
            legalName: {
              first: profile.first_name || '',
              last: profile.last_name || '',
            },
            preferredName: profile.preferred_name || 'Not provided',
            email: maskedEmail,
            phone: maskedPhone || 'Not provided',
            governmentId: profile.government_id ? 'Provided' : (profile.identity_verification_status === 'pending' ? 'Pending verification' : 'Not provided'),
            address: profile.address ? {
              country: profile.address.country || '',
              street: profile.address.line1 || '',
              apt: profile.address.line2 || '',
              city: profile.address.city || '',
              state: profile.address.state || '',
              zip: profile.address.postal_code || '',
            } : {
              country: '',
              street: '',
              apt: '',
              city: '',
              state: '',
              zip: '',
            },
            emergencyContact: {
              name: profile.emergency_contact?.name || '',
              relationship: profile.emergency_contact?.relationship || '',
              language: profile.emergency_contact?.language || '',
              email: profile.emergency_contact?.email || '',
              countryCode: profile.emergency_contact?.country_code || '',
              phone: profile.emergency_contact?.phone || '',
            },
          });
        }
      } catch (error) {
        console.error("Error loading data:", error);
      } finally {
        setIsLoading(false);
      }
    };

    loadData();
  }, []);

  const openModal = (type: keyof PersonalInfoData) => {
    const content = getModalContent(type, countries, languages);
    setModalContent(content);
  };

  const closeModal = () => {
    setModalContent(null);
  };

  const saveChanges = async (type: keyof PersonalInfoData, newValue: any) => {
    try {
      setIsSaving(true);

      const updateData: any = {};

      if (type === 'legalName') {
        updateData.first_name = newValue.first;
        updateData.last_name = newValue.last;
      } else if (type === 'preferredName') {
        updateData.preferred_name = newValue.preferredName || null;
      } else if (type === 'email') {
        updateData.email = newValue.email;
      } else if (type === 'phone') {
        const countryCodeMatch = newValue.countryCode?.match(/\(([^)]+)\)/);
        const countryCode = countryCodeMatch ? countryCodeMatch[1] : '';
        updateData.phone = countryCode ? `${countryCode}${newValue.phone}` : newValue.phone;
      } else if (type === 'address') {
        updateData.address = {
          country: newValue.country,
          line1: newValue.street,
          line2: newValue.apt || '',
          city: newValue.city,
          state: newValue.state,
          postal_code: newValue.zip,
        };
      } else if (type === 'emergencyContact') {
        const countryCodeMatch = newValue.countryCode?.match(/\(([^)]+)\)/);
        const countryCode = countryCodeMatch ? countryCodeMatch[1] : '';
        updateData.emergency_contact = {
          name: newValue.name || null,
          relationship: newValue.relationship || null,
          language: newValue.language || null,
          email: newValue.email || null,
          country_code: countryCode || null,
          phone: newValue.phone || null,
        };
      } else if (type === 'governmentId') {
        const file = newValue.file;
        const documentType = newValue.documentType;
        const country = newValue.country || personalInfo.address.country || defaultCountry;

        if (!file) {
          toast.error("Please select a file to upload");
          return;
        }

        if (!documentType) {
          toast.error("Please select a document type");
          return;
        }

        if (!country) {
          toast.error("Please select a country");
          return;
        }

        const documentTypeMap: Record<string, string> = {
          "Driver's License": "license",
          "Passport": "passport",
          "National ID": "identity",
        };
        const apiDocumentType = documentTypeMap[documentType] || "identity";

        const formData = new FormData();
        formData.append('file', file);
        formData.append('document_type', apiDocumentType);
        formData.append('country', country);

        const verificationResponse = await fetch("/api/me/verification", {
          method: "POST",
          body: formData,
        });

        if (verificationResponse.ok) {
          toast.success("Government ID uploaded successfully! It will be reviewed by our team.");
          setPersonalInfo(prev => ({
            ...prev,
            governmentId: 'Pending verification',
          }));
          closeModal();
          onUpdate?.();
          return;
        } else {
          const error = await verificationResponse.json();
          toast.error(error.error?.message || "Failed to upload Government ID");
          return;
        }
      }

      const response = await fetch("/api/me/profile", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(updateData),
      });

      if (response.ok) {
        const reloadResponse = await fetch("/api/me/profile");
        if (reloadResponse.ok) {
          const reloadData = await reloadResponse.json();
          const profile = reloadData.data;

          let maskedEmail = '';
          if (profile.email) {
            const emailParts = profile.email.split('@');
            if (emailParts[0].length > 0) {
              maskedEmail = `${emailParts[0].substring(0, 1)}****@${emailParts[1] || ''}`;
            } else {
              maskedEmail = profile.email;
            }
          }

          let maskedPhone = '';
          if (profile.phone) {
            const phoneStr = profile.phone.replace(/\D/g, '');
            if (phoneStr.length >= 4) {
              maskedPhone = `${phoneStr.substring(0, 3)} *** ***${phoneStr.substring(phoneStr.length - 4)}`;
            } else {
              maskedPhone = profile.phone;
            }
          }

          setPersonalInfo({
            legalName: {
              first: profile.first_name || '',
              last: profile.last_name || '',
            },
            preferredName: profile.preferred_name || 'Not provided',
            email: maskedEmail,
            phone: maskedPhone || 'Not provided',
            governmentId: profile.government_id ? 'Provided' : (profile.identity_verification_status === 'pending' ? 'Pending verification' : 'Not provided'),
            address: profile.address ? {
              country: profile.address.country || '',
              street: profile.address.line1 || '',
              apt: profile.address.line2 || '',
              city: profile.address.city || '',
              state: profile.address.state || '',
              zip: profile.address.postal_code || '',
            } : {
              country: '',
              street: '',
              apt: '',
              city: '',
              state: '',
              zip: '',
            },
            emergencyContact: {
              name: profile.emergency_contact?.name || '',
              relationship: profile.emergency_contact?.relationship || '',
              language: profile.emergency_contact?.language || '',
              email: profile.emergency_contact?.email || '',
              countryCode: profile.emergency_contact?.country_code || '',
              phone: profile.emergency_contact?.phone || '',
            },
          });
        }
        closeModal();
        toast.success("Changes saved successfully!");
        onUpdate?.();
      } else {
        const error = await response.json();
        toast.error(error.error?.message || "Failed to save changes");
      }
    } catch (error) {
      console.error("Error saving changes:", error);
      toast.error("An error occurred. Please try again.");
    } finally {
      setIsSaving(false);
    }
  };

  const getModalContent = (type: keyof PersonalInfoData, countries: Country[] = [], languages: string[] = ['English']): ModalContent => {
    const phoneCountryOptions = countries
      .filter(c => c.phone_country_code)
      .map(c => `${c.name} (${c.phone_country_code})`);

    const addressCountryOptions = countries.map(c => c.name);
    const languageOptions = languages.length > 0 ? languages : ['English'];

    switch (type) {
      case 'legalName':
        return {
          type: 'legalName',
          title: 'Legal name',
          description: 'Make sure this matches the name on your government ID.',
          fields: [
            { name: 'first', label: 'First name on ID', type: 'text' },
            { name: 'last', label: 'Last name on ID', type: 'text' },
          ],
        };
      case 'preferredName':
        return {
          type: 'preferredName',
          title: 'Preferred name',
          description: 'This is how your first name will appear to Providers and clients.',
          fields: [
            { name: 'preferredName', label: 'Preferred name (optional)', type: 'text' },
          ],
        };
      case 'email':
        return {
          type: 'email',
          title: 'Email address',
          description: 'Use an address you\'ll always have access to.',
          fields: [
            { name: 'email', label: 'Email address', type: 'email' },
          ],
        };
      case 'phone':
        return {
          type: 'phone',
          title: 'Phone number',
          description: 'For notifications, reminders, and help logging in',
          fields: [
            { name: 'countryCode', label: 'Country code', type: 'select', options: phoneCountryOptions.length > 0 ? phoneCountryOptions : ['South Africa (+27)'] },
            { name: 'phone', label: 'Phone number', type: 'tel' },
          ],
        };
      case 'address':
        return {
          type: 'address',
          title: 'Address',
          description: 'Use a permanent address where you can receive mail.',
          fields: [
            { name: 'country', label: 'Country/region', type: 'select', options: addressCountryOptions.length > 0 ? addressCountryOptions : ['South Africa'] },
            { name: 'street', label: 'Street address', type: 'text' },
            { name: 'apt', label: 'Apt, suite. (optional)', type: 'text' },
            { name: 'city', label: 'City', type: 'text' },
            { name: 'state', label: 'State / Province / County / Region', type: 'text' },
            { name: 'zip', label: 'ZIP code', type: 'text' },
          ],
        };
      case 'emergencyContact':
        return {
          type: 'emergencyContact',
          title: 'Emergency contact',
          description: 'A trusted contact we can alert in an urgent situation.',
          fields: [
            { name: 'name', label: 'Name', type: 'text' },
            { name: 'relationship', label: 'Relationship', type: 'text' },
            { name: 'language', label: 'Preferred language', type: 'select', options: languageOptions },
            { name: 'email', label: 'Email', type: 'email' },
            { name: 'countryCode', label: 'Country code', type: 'select', options: phoneCountryOptions.length > 0 ? phoneCountryOptions : ['South Africa (+27)'] },
            { name: 'phone', label: 'Phone number', type: 'tel' },
          ],
        };
      case 'governmentId':
        return {
          type: 'governmentId',
          title: 'Government ID',
          description: 'Upload a government-issued ID for identity verification. This helps keep our community safe. Your document will be reviewed by our team.',
          fields: [
            { name: 'documentType', label: 'Document type', type: 'select', options: ['Driver\'s License', 'Passport', 'National ID'] },
            { name: 'country', label: 'Country', type: 'select', options: addressCountryOptions.length > 0 ? addressCountryOptions : ['South Africa'] },
            { name: 'file', label: 'Upload document', type: 'file', accept: 'image/*,.pdf' },
          ],
        };
      default:
        throw new Error(`Unknown modal type: ${type}`);
    }
  };

  if (isLoading) {
    return (
      <Card className="w-full bg-white border border-gray-200 shadow-sm">
        <CardHeader className="bg-white">
          <CardTitle className="text-lg font-semibold">Personal Information</CardTitle>
        </CardHeader>
        <CardContent className="bg-white">
          <p className="text-sm text-gray-600">Loading...</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <>
      <Card className="w-full bg-white border border-gray-200 shadow-sm">
        <Collapsible open={isOpen} onOpenChange={setIsOpen}>
          <CollapsibleTrigger asChild>
            <CardHeader className="cursor-pointer hover:bg-gray-50 transition-colors bg-white border-b border-gray-200">
              <div className="flex items-center justify-between">
                <CardTitle className="text-lg font-semibold text-gray-900">Personal Information</CardTitle>
                {isOpen ? <ChevronUp className="w-5 h-5 text-gray-500" /> : <ChevronDown className="w-5 h-5 text-gray-500" />}
              </div>
            </CardHeader>
          </CollapsibleTrigger>
          <CollapsibleContent className="overflow-hidden transition-all duration-300 data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down">
            <CardContent className="pt-4 bg-white space-y-4">
              <InfoItem
                label="Legal name"
                value={`${personalInfo.legalName.first} ${personalInfo.legalName.last}`}
                onEdit={() => openModal('legalName')}
              />
              <InfoItem
                label="Preferred name"
                value={personalInfo.preferredName}
                onEdit={personalInfo.preferredName !== 'Not provided' ? () => openModal('preferredName') : undefined}
                onAdd={personalInfo.preferredName === 'Not provided' ? () => openModal('preferredName') : undefined}
              />
              <InfoItem
                label="Email address"
                value={personalInfo.email}
                onEdit={() => openModal('email')}
                verified={emailVerified}
              />
              <InfoItem
                label="Phone number"
                value={personalInfo.phone}
                onEdit={() => openModal('phone')}
                verified={phoneVerified}
              />

              {/* Government ID Verification Card */}
              <div>
                <label className="text-sm font-medium text-gray-900 mb-2 block">Government ID</label>
                <VerificationStatusCard
                  status={verificationData.status}
                  submittedAt={verificationData.submittedAt}
                  failureReason={verificationData.failureReason}
                  onAction={() => openModal('governmentId')}
                />
              </div>

              <InfoItem
                label="Address"
                value={personalInfo.address.street && personalInfo.address.city ? `${personalInfo.address.street}, ${personalInfo.address.city}` : 'Not provided'}
                onEdit={personalInfo.address.street ? () => openModal('address') : undefined}
                onAdd={!personalInfo.address.street ? () => openModal('address') : undefined}
                isOptional={true}
              />
              <InfoItem
                label="Emergency contact"
                value={personalInfo.emergencyContact.name ? personalInfo.emergencyContact.name : 'Not provided'}
                onAdd={!personalInfo.emergencyContact.name ? () => openModal('emergencyContact') : undefined}
                onEdit={personalInfo.emergencyContact.name ? () => openModal('emergencyContact') : undefined}
                isPrivate={true}
              />
            </CardContent>
          </CollapsibleContent>
        </Collapsible>
      </Card>

      {modalContent && (
        <PersonalInfoModal
          content={modalContent}
          onClose={closeModal}
          onSave={(newValue) => saveChanges(modalContent.type, newValue)}
          isSaving={isSaving}
          initialData={personalInfo}
          countries={countries}
          defaultCountryCode={defaultCountryCode}
          defaultCountry={defaultCountry}
          languages={languages}
        />
      )}
    </>
  );
}

// Import the Modal component from personal-info page
// For now, I'll create a simplified version here
function PersonalInfoModal({ content, onClose, onSave, isSaving, initialData, countries, defaultCountryCode, defaultCountry, languages }: any) {
  const getInitialFormData = () => {
    if (!initialData) return {};

    switch (content.type) {
      case 'legalName':
        return { first: initialData.legalName.first, last: initialData.legalName.last };
      case 'preferredName':
        return { preferredName: initialData.preferredName !== 'Not provided' ? initialData.preferredName : '' };
      case 'email':
        return { email: '' };
      case 'phone':
        const defaultPhoneCountry = countries.find((c: Country) => c.phone_country_code === defaultCountryCode) || countries[0];
        return {
          countryCode: defaultPhoneCountry ? `${defaultPhoneCountry.name} (${defaultPhoneCountry.phone_country_code})` : `${defaultCountry} (${defaultCountryCode})`,
          phone: '',
        };
      case 'address':
        return {
          country: initialData.address.country || defaultCountry,
          street: initialData.address.street,
          apt: initialData.address.apt,
          city: initialData.address.city,
          state: initialData.address.state,
          zip: initialData.address.zip,
        };
      case 'emergencyContact':
        const defaultECCountry = countries.find((c: Country) => c.phone_country_code === defaultCountryCode) || countries[0];
        return {
          name: initialData.emergencyContact.name || '',
          relationship: initialData.emergencyContact.relationship || '',
          language: initialData.emergencyContact.language || languages[0] || 'English',
          email: initialData.emergencyContact.email || '',
          countryCode: initialData.emergencyContact.countryCode ? 
            (initialData.emergencyContact.countryCode.includes('+') 
              ? countries.find((c: Country) => c.phone_country_code === initialData.emergencyContact.countryCode) 
                ? `${countries.find((c: Country) => c.phone_country_code === initialData.emergencyContact.countryCode)!.name} (${initialData.emergencyContact.countryCode})`
                : initialData.emergencyContact.countryCode
              : initialData.emergencyContact.countryCode) 
            : (defaultECCountry ? `${defaultECCountry.name} (${defaultECCountry.phone_country_code})` : `${defaultCountry} (${defaultCountryCode})`),
          phone: initialData.emergencyContact.phone || '',
        };
      case 'governmentId':
        return {
          documentType: '',
          country: initialData.address.country || defaultCountry,
          file: null,
        };
      default:
        return {};
    }
  };

  const [formData, setFormData] = useState<any>(getInitialFormData());
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);

  useEffect(() => {
    queueMicrotask(() => {
      setFormData(getInitialFormData());
      setSelectedFile(null);
      setFilePreview(null);
    });
  }, [content.type, initialData, countries, defaultCountryCode, defaultCountry, languages]); // eslint-disable-line react-hooks/exhaustive-deps -- reset when modal content deps change

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedFile(file);
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
          setFilePreview(reader.result as string);
        };
        reader.readAsDataURL(file);
      } else {
        setFilePreview(null);
      }
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (content.type === 'governmentId' && selectedFile) {
      onSave({ ...formData, file: selectedFile });
    } else {
      onSave(formData);
    }
  };

  return (
    <div 
      className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50"
      onClick={onClose}
    >
      <div 
        className="bg-white p-6 rounded-lg w-full max-w-md mx-4 max-h-[90vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-bold">{content.title}</h2>
          <button 
            onClick={onClose} 
            className="text-gray-500 hover:text-gray-700 text-2xl leading-none"
            aria-label="Close"
          >
            ├ù
          </button>
        </div>
        <p className="mb-4 text-gray-600 text-sm">{content.description}</p>
        <form onSubmit={handleSubmit}>
          {content.fields.map((field: any) => (
            <div key={field.name} className="mb-4">
              <label className="block mb-2 text-sm font-medium text-gray-700" htmlFor={field.name}>
                {field.label}
              </label>
              {field.type === 'file' ? (
                <div>
                  <input
                    type="file"
                    id={field.name}
                    name={field.name}
                    accept={field.accept || "image/*,.pdf"}
                    className="w-full p-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#FF0077] focus:border-transparent"
                    onChange={handleFileChange}
                    required={content.type === 'governmentId'}
                  />
                  {filePreview && (
                    <div className="mt-2 relative w-full h-48">
                      <Image src={filePreview} alt="Preview" fill className="object-contain border border-gray-300 rounded-md" unoptimized />
                    </div>
                  )}
                  {selectedFile && !filePreview && (
                    <div className="mt-2 text-sm text-gray-600">
                      Selected: {selectedFile.name} ({(selectedFile.size / 1024 / 1024).toFixed(2)} MB)
                    </div>
                  )}
                  <p className="mt-1 text-xs text-gray-500">
                    Accepted formats: JPEG, PNG, WebP, PDF (Max 10MB)
                  </p>
                </div>
              ) : field.type === 'select' ? (
                <select
                  id={field.name}
                  name={field.name}
                  value={formData[field.name] || ''}
                  className="w-full p-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#FF0077] focus:border-transparent"
                  onChange={handleChange}
                  required={field.name !== 'apt' && field.name !== 'line2'}
                >
                  <option value="">Select {field.label}</option>
                  {field.options?.map((option: string) => (
                    <option key={option} value={option}>{option}</option>
                  ))}
                </select>
              ) : (
                <input
                  type={field.type}
                  id={field.name}
                  name={field.name}
                  value={formData[field.name] || ''}
                  className="w-full p-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#FF0077] focus:border-transparent"
                  onChange={handleChange}
                  required={field.name !== 'apt' && field.name !== 'line2' && field.name !== 'preferredName'}
                />
              )}
            </div>
          ))}
          <div className="flex justify-end gap-3 mt-6">
            <button
              type="button"
              onClick={onClose}
              disabled={isSaving}
              className="px-4 py-2 border border-gray-300 text-gray-700 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isSaving || (content.type === 'governmentId' && !selectedFile)}
              className="px-4 py-2 bg-black text-white rounded-md hover:bg-gray-800 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isSaving
                ? "Uploading..."
                : content.type === "phone"
                ? "Verify"
                : content.type === "governmentId"
                ? "Upload for Verification"
                : "Save"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import React from "react";
import { Camera } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { fetcher } from "@/lib/http/fetcher";

interface ProfileHeaderProps {
  preferredName: string | null;
  handle: string | null;
  avatarUrl: string | null;
  memberSince: Date;
  role: string;
  onUpdate?: () => void;
}

export default function ProfileHeader({
  preferredName,
  handle,
  avatarUrl,
  memberSince,
  role,
  onUpdate,
}: ProfileHeaderProps) {
  const [isUploading, setIsUploading] = React.useState(false);
  const [isEditingHandle, setIsEditingHandle] = React.useState(false);
  const [handleValue, setHandleValue] = React.useState(handle || "");

  const formatMemberSince = (date: Date) => {
    const now = new Date();
    const months = (now.getFullYear() - date.getFullYear()) * 12 + (now.getMonth() - date.getMonth());
    const years = Math.floor(months / 12);
    if (years > 0) {
      return `${years} ${years === 1 ? "year" : "years"} on Beautonomi`;
    }
    return `${months} ${months === 1 ? "month" : "months"} on Beautonomi`;
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file
    if (!file.type.startsWith("image/")) {
      toast.error("Please select an image file");
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      toast.error("Image must be less than 5MB");
      return;
    }

    setIsUploading(true);
    try {
      // Create FormData
      const formData = new FormData();
      formData.append("file", file);

      // Upload to Supabase Storage
      const uploadResponse = await fetch("/api/me/avatar", {
        method: "POST",
        body: formData,
      });

      if (!uploadResponse.ok) {
        const error = await uploadResponse.json();
        throw new Error(error.error?.message || "Failed to upload photo");
      }

      const { data } = await uploadResponse.json();
      
      // Update profile with new avatar URL
      await fetcher.patch("/api/me/profile", {
        avatar_url: data.url,
      });

      toast.success("Profile photo updated");
      onUpdate?.();
    } catch (error: any) {
      toast.error(error.message || "Failed to upload photo");
    } finally {
      setIsUploading(false);
    }
  };

  const handleSaveHandle = async () => {
    if (!handleValue.trim()) {
      toast.error("Handle cannot be empty");
      return;
    }

    if (!/^[a-zA-Z0-9_]{3,50}$/.test(handleValue)) {
      toast.error("Handle must be 3-50 characters and contain only letters, numbers, and underscores");
      return;
    }

    try {
      await fetcher.patch("/api/me/profile", {
        handle: handleValue.trim(),
      });

      toast.success("Handle updated");
      setIsEditingHandle(false);
      onUpdate?.();
    } catch (error: any) {
      toast.error(error.message || "Failed to update handle");
    }
  };

  const displayName = preferredName || "User";
  const initials = displayName
    .split(" ")
    .map((n) => n[0])
    .join("")
    .toUpperCase()
    .slice(0, 2);

  return (
    <div className="bg-white border border-gray-200 rounded-xl shadow-sm p-6">
      <div className="flex items-start gap-6">
        {/* Avatar */}
        <div className="relative">
          <Avatar className="h-20 w-20 md:h-24 md:w-24">
            <AvatarImage src={avatarUrl || undefined} alt={displayName} />
            <AvatarFallback className="bg-gray-100 text-gray-600 text-xl font-semibold">
              {initials}
            </AvatarFallback>
          </Avatar>
          <Sheet>
            <SheetTrigger asChild>
              <Button
                size="icon"
                variant="secondary"
                className="absolute -bottom-2 -right-2 h-8 w-8 rounded-full bg-white border-2 border-gray-200 shadow-sm hover:bg-gray-50"
                disabled={isUploading}
                aria-label="Update profile photo"
              >
                <Camera className="h-4 w-4 text-gray-600" />
              </Button>
            </SheetTrigger>
            <SheetContent className="bg-white">
              <SheetHeader>
                <SheetTitle>Update Profile Photo</SheetTitle>
                <SheetDescription>
                  Choose a photo from your device or take a new one.
                </SheetDescription>
              </SheetHeader>
              <div className="mt-6 space-y-4">
                <div>
                  <Label htmlFor="photo-upload" className="mb-2 block">
                    Select Photo
                  </Label>
                  <Input
                    id="photo-upload"
                    type="file"
                    accept="image/*"
                    onChange={handlePhotoUpload}
                    disabled={isUploading}
                  />
                </div>
                {isUploading && (
                  <p className="text-sm text-gray-500">Uploading...</p>
                )}
              </div>
            </SheetContent>
          </Sheet>
        </div>

        {/* Name and Info */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-3 mb-2">
            <h1 className="text-2xl md:text-3xl font-bold text-gray-900 truncate">
              {displayName}
            </h1>
            {handle && (
              <span className="text-sm text-gray-500">@{handle}</span>
            )}
          </div>
          {!handle && (
            <Sheet open={isEditingHandle} onOpenChange={setIsEditingHandle}>
              <SheetTrigger asChild>
                <Button variant="ghost" size="sm" className="text-xs text-gray-500 h-auto p-0">
                  Add handle
                </Button>
              </SheetTrigger>
              <SheetContent className="bg-white">
                <SheetHeader>
                  <SheetTitle>Add Handle</SheetTitle>
                  <SheetDescription>
                    Choose a unique username. This will be visible to others.
                  </SheetDescription>
                </SheetHeader>
                <div className="mt-6 space-y-4">
                  <div>
                    <Label htmlFor="handle-input">Handle</Label>
                    <Input
                      id="handle-input"
                      value={handleValue}
                      onChange={(e) => setHandleValue(e.target.value)}
                      placeholder="username"
                      maxLength={50}
                    />
                    <p className="text-xs text-gray-500 mt-1">
                      3-50 characters, letters, numbers, and underscores only
                    </p>
                  </div>
                  <Button onClick={handleSaveHandle} className="w-full">
                    Save
                  </Button>
                </div>
              </SheetContent>
            </Sheet>
          )}
          <p className="text-sm text-gray-500 capitalize">{role}</p>
          <p className="text-xs text-gray-400 mt-1">
            {formatMemberSince(memberSince)}
          </p>
        </div>
      </div>
    </div>
  );
}

