  const formatMemberSince = (date: Date) => {
    const now = new Date();
    const months = (now.getFullYear() - date.getFullYear()) * 12 + (now.getMonth() - date.getMonth());
    const years = Math.floor(months / 12);
    if (years > 0) {
      return `${years} ${years === 1 ? "year" : "years"} on Beautonomi`;
    }
    return `${months} ${months === 1 ? "month" : "months"} on Beautonomi`;
  };

  const memberSince = new Date(user.created_at);

  useEffect(() => {
    // Load loyalty points
    fetcher.get<{ data: { points_balance: number } }>("/api/me/loyalty")
      .then(res => setLoyaltyPoints(res.data.points_balance))
      .catch(() => {
        // Silently fail - loyalty points are optional
        setLoyaltyPoints(null);
      });
  }, []);

  const quickActions: QuickActionBadge[] = [
    {
      type: "email",
      label: "Email",
      verified: user.email_verified,
    },
    {
      type: "photo",
      label: "Photo",
      verified: !!user.avatar_url,
    },
    {
      type: "phone",
      label: "Phone",
      verified: user.phone_verified,
    },
    {
      type: "id",
      label: "ID",
      verified: user.identity_verified,
      pending: user.identity_verification_status === "pending",
    },
  ];

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith("image/")) {
      toast.error("Please select an image file");
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      toast.error("Image must be less than 5MB");
      return;
    }

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append("file", file);

      const uploadResponse = await fetch("/api/me/avatar", {
        method: "POST",
        body: formData,
      });

      if (!uploadResponse.ok) {
        const error = await uploadResponse.json();
        throw new Error(error.error?.message || "Failed to upload photo");
      }

      const { data } = await uploadResponse.json();
      
      await fetcher.patch("/api/me/profile", {
        avatar_url: data.url,
      });

      toast.success("Profile photo updated");
      onUpdate?.();
    } catch (error: any) {
      toast.error(error.message || "Failed to upload photo");
    } finally {
      setIsUploading(false);
    }
  };

  const handleSaveHandle = async () => {
    if (!handleValue.trim()) {
      toast.error("Handle cannot be empty");
      return;
    }

    if (!/^[a-zA-Z0-9_]{3,50}$/.test(handleValue)) {
      toast.error("Handle must be 3-50 characters and contain only letters, numbers, and underscores");
      return;
    }

    try {
      await fetcher.patch("/api/me/profile", {
        handle: handleValue.trim(),
      });

      toast.success("Handle updated");
      setIsEditingHandle(false);
      onUpdate?.();
    } catch (error: any) {
      toast.error(error.message || "Failed to update handle");
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4 }}
      className="backdrop-blur-2xl bg-white/60 border border-white/40 shadow-2xl rounded-2xl p-6 md:p-8"
    >
      <div className="flex flex-col md:flex-row items-start md:items-center gap-6">
        {/* Avatar */}
        <div className="relative group">
          <motion.div
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            className="relative"
          >
            <Avatar className="h-20 w-20 md:h-28 md:w-28 ring-4 ring-white/50 shadow-lg">
              <AvatarImage src={user.avatar_url || undefined} alt={displayName} />
              <AvatarFallback className="bg-gradient-to-br from-zinc-100 to-zinc-200 text-zinc-700 text-2xl font-semibold">
                {initials}
              </AvatarFallback>
            </Avatar>
            <label
              htmlFor="photo-upload"
              className="absolute -bottom-2 -right-2 h-10 w-10 rounded-full bg-white border-2 border-zinc-200 shadow-lg flex items-center justify-center cursor-pointer hover:bg-zinc-50 transition-colors group-hover:scale-110"
            >
              <Camera className="h-5 w-5 text-zinc-600" />
              <input
                id="photo-upload"
                type="file"
                accept="image/*"
                onChange={handlePhotoUpload}
                disabled={isUploading}
                className="hidden"
              />
            </label>
          </motion.div>
        </div>

        {/* Name and Info */}
        <div className="flex-1 min-w-0">
          <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-3 mb-2">
            <h1 className="text-2xl md:text-3xl font-semibold tracking-tight text-zinc-900">
              {displayName}
            </h1>
            {user.handle ? (
              <span className="text-sm text-zinc-500">@{user.handle}</span>
            ) : (
              <button
                onClick={() => setIsEditingHandle(true)}
                className="text-sm text-zinc-400 hover:text-[#FF0077] underline font-medium transition-colors text-left"
              >
                Add handle
              </button>
            )}
          </div>
          <div className="flex flex-wrap items-center gap-3 mb-3">
            <span className="text-sm font-medium text-zinc-600 capitalize">{user.role}</span>
            <span className="text-xs text-zinc-400">ΓÇó</span>
            <span className="text-xs text-zinc-500">{formatMemberSince(memberSince)}</span>
            {loyaltyPoints !== null && (
              <>
                <span className="text-xs text-zinc-400">ΓÇó</span>
                <Link 
                  href="/account-settings/loyalty"
                  className="text-xs text-[#FF0077] hover:text-[#E6006A] font-medium transition-colors flex items-center gap-1"
                >
                  <Sparkles className="h-3 w-3" />
                  {loyaltyPoints.toLocaleString()} points
                </Link>
              </>
            )}
          </div>

          {/* Quick Action Chips */}
          <div className="flex flex-wrap gap-2 mt-4">
            {quickActions.map((action) => (
              <motion.button
                key={action.type}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className={`
                  px-3 py-1.5 rounded-full text-xs font-medium transition-all
                  flex items-center gap-1.5
                  ${
                    action.verified
                      ? "bg-emerald-50 text-emerald-700 border border-emerald-200"
                      : action.pending
                      ? "bg-amber-50 text-amber-700 border border-amber-200"
                      : "bg-zinc-100 text-zinc-600 border border-zinc-200 hover:bg-zinc-200"
                  }
                `}
                onClick={() => {
                  // Scroll to relevant section or trigger action
                  if (action.type === "email") {
                    document.getElementById("personal-info-section")?.scrollIntoView({ behavior: "smooth" });
                  } else if (action.type === "phone") {
                    document.getElementById("personal-info-section")?.scrollIntoView({ behavior: "smooth" });
                  } else if (action.type === "id") {
                    document.getElementById("personal-info-section")?.scrollIntoView({ behavior: "smooth" });
                  }
                }}
              >
                {action.type === "email" && <Mail className="h-3 w-3" />}
                {action.type === "photo" && <Camera className="h-3 w-3" />}
                {action.type === "phone" && <Phone className="h-3 w-3" />}
                {action.type === "id" && <Shield className="h-3 w-3" />}
                {action.verified && <Check className="h-3 w-3" />}
                {action.label}
              </motion.button>
            ))}
          </div>
        </div>
      </div>

      {/* Handle Edit Modal */}
      {isEditingHandle && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white rounded-2xl p-6 max-w-md w-full shadow-2xl"
          >
            <h3 className="text-lg font-semibold mb-2">Add Handle</h3>
            <p className="text-sm text-zinc-600 mb-4">
              Choose a unique username. This will be visible to others.
            </p>
            <input
              type="text"
              value={handleValue}
              onChange={(e) => setHandleValue(e.target.value)}
              placeholder="username"
              maxLength={50}
              className="w-full px-4 py-2 border border-zinc-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#FF0077] mb-4"
              onKeyDown={(e) => {
                if (e.key === "Enter") handleSaveHandle();
                if (e.key === "Escape") setIsEditingHandle(false);
              }}
              autoFocus
            />
            <div className="flex gap-3">
              <Button
                variant="outline"
                onClick={() => setIsEditingHandle(false)}
                className="flex-1"
              >
                Cancel
              </Button>
              <Button
                onClick={handleSaveHandle}
                className="flex-1 bg-[#FF0077] hover:bg-[#E6006A] text-white"
              >
                Save
              </Button>
            </div>
          </motion.div>
        </div>
      )}
    </motion.div>
  );
}

"use client";

import React, { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { ChevronDown, ChevronUp, Lock, Globe } from "lucide-react";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { toast } from "sonner";
import { fetcher } from "@/lib/http/fetcher";
import Link from "next/link";
import { format } from "date-fns";

interface Booking {
  id: string;
  booking_number: string;
  scheduled_at: string;
  status: string;
  booking_services?: Array<{
    service_name?: string;
    offering_name?: string;
    offering?: {
      title?: string;
      master_service?: { name?: string };
    };
  }>;
}

interface ServicesBookedSectionProps {
  bookings: Booking[];
  isPublic: boolean;
  onUpdate?: () => void;
}

export default function ServicesBookedSection({
  bookings = [],
  isPublic = false,
  onUpdate,
}: ServicesBookedSectionProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [_pendingValue, setPendingValue] = useState(isPublic);

  const handleToggleChange = (checked: boolean) => {
    if (checked && !isPublic) {
      // Switching to public - show confirmation
      setPendingValue(true);
      setShowConfirmation(true);
    } else {
      // Switching to private - no confirmation needed
      handleSavePrivacy(checked);
    }
  };

  const handleSavePrivacy = async (value: boolean) => {
    setIsSaving(true);
    try {
      await fetcher.patch("/api/me/privacy-settings", {
        services_booked_visible: value,
      });
      toast.success("Privacy settings updated");
      onUpdate?.();
    } catch (error: any) {
      toast.error(error.message || "Failed to update privacy settings");
    } finally {
      setIsSaving(false);
      setShowConfirmation(false);
    }
  };

  const handleConfirmPublic = () => {
    handleSavePrivacy(true);
  };

  const upcomingBookings = bookings
    .filter((b) => {
      const scheduled = new Date(b.scheduled_at);
      return scheduled >= new Date() && b.status !== "cancelled";
    })
    .slice(0, 3);

  return (
    <>
      <Card className="w-full bg-white border border-gray-200 shadow-sm">
        <Collapsible open={isOpen} onOpenChange={setIsOpen}>
          <CollapsibleTrigger asChild>
            <CardHeader className="cursor-pointer hover:bg-gray-50 transition-colors bg-white border-b border-gray-200">
              <div className="flex items-center justify-between">
                <CardTitle className="text-lg font-semibold text-gray-900">
                  Services Booked
                </CardTitle>
                {isOpen ? (
                  <ChevronUp className="w-5 h-5 text-gray-500" />
                ) : (
                  <ChevronDown className="w-5 h-5 text-gray-500" />
                )}
              </div>
            </CardHeader>
          </CollapsibleTrigger>
          <CollapsibleContent className="overflow-hidden transition-all duration-300 data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down">
            <CardContent className="pt-4 bg-white space-y-4">
              {/* Privacy Toggle */}
              <div className="flex items-center justify-between p-4 bg-gray-50 rounded-lg border border-gray-200">
                <div className="flex items-center gap-3">
                  {isPublic ? (
                    <Globe className="h-5 w-5 text-gray-600" />
                  ) : (
                    <Lock className="h-5 w-5 text-gray-600" />
                  )}
                  <div>
                    <Label htmlFor="privacy-toggle" className="text-sm font-medium text-gray-900">
                      Show booking history to providers
                    </Label>
                    <p className="text-xs text-gray-500 mt-0.5">
                      Providers can see your booking history to understand your preferences
                    </p>
                  </div>
                </div>
                <Switch
                  id="privacy-toggle"
                  checked={isPublic}
                  onCheckedChange={handleToggleChange}
                  disabled={isSaving}
                />
              </div>

              {/* Bookings Preview */}
              {isPublic && (
                <>
                  {upcomingBookings.length > 0 ? (
                    <div className="space-y-3">
                      <div className="flex items-center justify-between">
                        <h4 className="text-sm font-semibold text-gray-900">
                          Upcoming Bookings
                        </h4>
                        <Link
                          href="/account-settings/bookings"
                          className="text-xs text-[#FF0077] hover:underline"
                        >
                          View all
                        </Link>
                      </div>
                      {upcomingBookings.map((booking) => {
                        const firstService = booking.booking_services?.[0];
                        const serviceName =
                          firstService?.service_name ||
                          firstService?.offering_name ||
                          firstService?.offering?.title ||
                          firstService?.offering?.master_service?.name ||
                          "Service";
                        const scheduledDate = new Date(booking.scheduled_at);

                        return (
                          <div
                            key={booking.id}
                            className="p-3 bg-gray-50 rounded-lg border border-gray-200"
                          >
                            <div className="flex items-start justify-between">
                              <div className="flex-1 min-w-0">
                                <p className="text-sm font-medium text-gray-900 truncate">
                                  {serviceName}
                                </p>
                                <p className="text-xs text-gray-500 mt-1">
                                  {format(scheduledDate, "MMM d, yyyy 'at' h:mm a")}
                                </p>
                                <p className="text-xs text-gray-400 mt-1">
                                  Booking #{booking.booking_number}
                                </p>
                              </div>
                              <span className="text-xs px-2 py-1 bg-blue-100 text-blue-700 rounded-full capitalize ml-2">
                                {booking.status}
                              </span>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  ) : (
                    <div className="text-center py-8 text-gray-500">
                      <p className="text-sm">No upcoming bookings</p>
                      <Link
                        href="/search"
                        className="text-xs text-[#FF0077] hover:underline mt-2 inline-block"
                      >
                        Browse services
                      </Link>
                    </div>
                  )}
                </>
              )}

              {!isPublic && (
                <div className="text-center py-8 text-gray-500">
                  <Lock className="h-8 w-8 mx-auto mb-2 text-gray-400" />
                  <p className="text-sm">Your bookings are private</p>
                </div>
              )}
            </CardContent>
          </CollapsibleContent>
        </Collapsible>
      </Card>

      {/* Confirmation Dialog */}
      <AlertDialog open={showConfirmation} onOpenChange={setShowConfirmation}>
        <AlertDialogContent className="bg-white">
          <AlertDialogHeader>
            <AlertDialogTitle>Make booking history public?</AlertDialogTitle>
            <AlertDialogDescription>
              Providers will be able to see your booking history. This helps them understand
              your preferences and provide better service. You can change this setting anytime.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setShowConfirmation(false)}>
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmPublic}
              className="bg-[#FF0077] hover:bg-[#E6006A] text-white"
            >
              Make Public
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { PhoneInput } from "@/components/ui/phone-input";
import { Switch } from "@/components/ui/switch";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import {
  X,
  User,
  Mail,
  MapPin,
  Save,
  CalendarIcon,
  Bell,
  Globe,
  Heart,
  ChevronDown,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { format } from "date-fns";

interface Client {
  id?: string;
  first_name: string;
  last_name: string;
  preferred_name?: string;
  email?: string;
  phone?: string;
  date_of_birth?: Date;
  address?: {
    line1: string;
    line2?: string;
    city: string;
    state?: string;
    postal_code?: string;
    country: string;
  };
  emergency_contact?: {
    name: string;
    phone: string;
    relationship: string;
  };
  preferred_language?: string;
  preferred_currency?: string;
  timezone?: string;
  communication_preferences?: {
    email_notifications: boolean;
    sms_notifications: boolean;
    push_notifications: boolean;
  };
  notes?: string;
}

interface AddClientDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: (client: Client) => void;
  defaultCountryCode?: string;
}

const LANGUAGES = [
  { value: "en", label: "English" },
  { value: "af", label: "Afrikaans" },
  { value: "zu", label: "Zulu" },
  { value: "xh", label: "Xhosa" },
  { value: "fr", label: "French" },
];

const CURRENCIES = [
  { value: "ZAR", label: "South African Rand (ZAR)" },
  { value: "USD", label: "US Dollar (USD)" },
  { value: "EUR", label: "Euro (EUR)" },
  { value: "GBP", label: "British Pound (GBP)" },
];

const TIMEZONES = [
  { value: "Africa/Johannesburg", label: "South Africa (SAST)" },
  { value: "Africa/Cairo", label: "Egypt (EET)" },
  { value: "Africa/Lagos", label: "Nigeria (WAT)" },
  { value: "Africa/Nairobi", label: "Kenya (EAT)" },
  { value: "UTC", label: "UTC" },
];

const EMERGENCY_RELATIONSHIPS = [
  "Spouse",
  "Parent",
  "Sibling",
  "Child",
  "Friend",
  "Other",
];

export function AddClientDialog({
  open,
  onOpenChange,
  onSuccess,
  defaultCountryCode = "+27",
}: AddClientDialogProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [defaultCountry, setDefaultCountry] = useState(defaultCountryCode);
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [formData, setFormData] = useState<Client>({
    first_name: "",
    last_name: "",
    preferred_name: "",
    email: "",
    phone: "",
    date_of_birth: undefined,
    address: {
      line1: "",
      line2: "",
      city: "",
      state: "",
      postal_code: "",
      country: "ZA",
    },
    emergency_contact: {
      name: "",
      phone: "",
      relationship: "",
    },
    preferred_language: "en",
    preferred_currency: "ZAR",
    timezone: "Africa/Johannesburg",
    communication_preferences: {
      email_notifications: true,
      sms_notifications: false,
      push_notifications: true,
    },
    notes: "",
  });

  useEffect(() => {
    if (open) {
      // Fetch default country code
      fetch("/api/public/platform-settings")
        .then((res) => res.json())
        .then((data) => {
          if (data.default_country_code) {
            setDefaultCountry(data.default_country_code);
          }
        })
        .catch(() => {});
    } else {
      // Reset form when closed
      setFormData({
        first_name: "",
        last_name: "",
        preferred_name: "",
        email: "",
        phone: "",
        date_of_birth: undefined,
        address: {
          line1: "",
          line2: "",
          city: "",
          state: "",
          postal_code: "",
          country: "ZA",
        },
        emergency_contact: {
          name: "",
          phone: "",
          relationship: "",
        },
        preferred_language: "en",
        preferred_currency: "ZAR",
        timezone: "Africa/Johannesburg",
        communication_preferences: {
          email_notifications: true,
          sms_notifications: false,
          push_notifications: true,
        },
        notes: "",
      });
      setShowAdvanced(false);
    }
  }, [open]);

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    
    if (!formData.first_name || !formData.last_name) {
      alert("Please enter client's first and last name");
      return;
    }

    setIsLoading(true);
    try {
      // Format phone number (remove spaces)
      const formattedPhone = formData.phone ? formData.phone.replace(/\s/g, '') : undefined;
      
      // Combine first_name and last_name into full_name
      const full_name = `${formData.first_name} ${formData.last_name}`.trim();
      
      // Create email if not provided (for walk-in clients)
      const email = formData.email || `walkin-${Date.now()}@beautonomi.local`;
      
      // Prepare user data
      const userData = {
        email,
        full_name,
        phone: formattedPhone,
        preferred_name: formData.preferred_name || null,
        date_of_birth: formData.date_of_birth ? format(formData.date_of_birth, "yyyy-MM-dd") : null,
        emergency_contact_name: formData.emergency_contact?.name || null,
        emergency_contact_phone: formData.emergency_contact?.phone || null,
        emergency_contact_relationship: formData.emergency_contact?.relationship || null,
        preferred_language: formData.preferred_language || "en",
        preferred_currency: formData.preferred_currency || "ZAR",
        timezone: formData.timezone || "Africa/Johannesburg",
        email_notifications_enabled: formData.communication_preferences?.email_notifications ?? true,
        sms_notifications_enabled: formData.communication_preferences?.sms_notifications ?? false,
        push_notifications_enabled: formData.communication_preferences?.push_notifications ?? true,
      };

      // Create address data if provided
      const addressData = formData.address?.line1 && formData.address?.city ? {
        address_line1: formData.address.line1,
        address_line2: formData.address.line2 || null,
        city: formData.address.city,
        state: formData.address.state || null,
        postal_code: formData.address.postal_code || null,
        country: formData.address.country || "ZA",
        is_default: true,
      } : null;

      // Call API to create client
      const response = await fetch("/api/provider/clients/create", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          first_name: formData.first_name,
          last_name: formData.last_name,
          ...userData,
          address: addressData,
          notes: formData.notes || null,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to create client");
      }

      const result = await response.json();
      onSuccess?.(result.data as Client);
      onOpenChange(false);
    } catch (error: any) {
      console.error("Failed to create client:", error);
      alert(error.message || "Failed to create client. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent 
        side="bottom" 
        className="h-[90vh] max-h-[90vh] rounded-t-3xl p-0 flex flex-col overflow-hidden font-sans bg-white"
