              </div>

              {/* Date of Birth */}
              <div className="space-y-3">
                <Label className="text-sm font-semibold text-gray-900">
                  Date of Birth
                </Label>
                <Popover>
                  <PopoverTrigger asChild>
                    <Button
                      variant="outline"
                      className={cn(
                        "w-full h-12 text-base justify-start text-left font-normal",
                        !formData.date_of_birth && "text-muted-foreground"
                      )}
