  appointments,
  maxItems = 5,
  onViewAll,
}: UpcomingAppointmentsWidgetProps) {
  const displayAppointments = appointments.slice(0, maxItems);

  const formatTime12h = (time: string) => {
    const [hour, minute] = time.split(":").map(Number);
    const ampm = hour >= 12 ? "PM" : "AM";
