"use client";

import React, { useState, useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import { Button } from "@/components/ui/button";
import { useModuleConfig, useFeatureFlag } from "@/providers/ConfigBundleProvider";
import { playRingtone } from "@/lib/on-demand/ringtone";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import { Bell } from "lucide-react";

interface OnDemandRequestRow {
  id: string;
  status: string;
  requested_at: string;
  expires_at: string;
  request_payload?: Record<string, any>;
}

export function OnDemandIncomingOverlay() {
  const onDemandConfig = useModuleConfig("on_demand");
  const [incomingRequest, setIncomingRequest] = useState<OnDemandRequestRow | null>(null);
  const [secondsLeft, setSecondsLeft] = useState<number | null>(null);
  const [accepting, setAccepting] = useState(false);
  const [declining, setDeclining] = useState(false);
  const seenIdsRef = useRef<Set<string>>(new Set());
  const ringtoneStopRef = useRef<(() => void) | null>(null);

  const acceptGlobalEnabled = useFeatureFlag("on_demand_accept_enabled");
  const acceptProviderEnabled = useFeatureFlag("on_demand_accept_provider_enabled");
  const onDemandAcceptEnabled = acceptGlobalEnabled && acceptProviderEnabled;

  useEffect(() => {
    if (!onDemandConfig.enabled || !onDemandAcceptEnabled) return;

    const poll = async () => {
      try {
        const res = await fetcher.get<{ data: OnDemandRequestRow[] }>("/api/provider/on-demand/requests");
        const list = (res.data ?? []) as OnDemandRequestRow[];
        const requested = list.filter((r) => r.status === "requested");
        const next = requested.find((r) => !seenIdsRef.current.has(r.id));
        if (next) {
          seenIdsRef.current.add(next.id);
          setIncomingRequest(next);
        }
      } catch {
        // ignore
      }
    };

    const interval = setInterval(poll, 10000);
    poll();
    return () => clearInterval(interval);
  }, [onDemandConfig.enabled, onDemandAcceptEnabled]);

  useEffect(() => {
    return () => {
      ringtoneStopRef.current?.();
    };
  }, []);

  useEffect(() => {
    if (!incomingRequest || incomingRequest.status !== "requested") return;
    if (!onDemandConfig.enabled || !onDemandConfig.ringtone_asset_path) return;
    ringtoneStopRef.current?.();
    playRingtone(
      {
        enabled: onDemandConfig.enabled,
        ringtone_asset_path: onDemandConfig.ringtone_asset_path,
        ring_duration_seconds: onDemandConfig.ring_duration_seconds ?? 20,
        ring_repeat: onDemandConfig.ring_repeat ?? true,
      },
      { environment: typeof window !== "undefined" && (window as any).__DEV__ ? "development" : "production" }
    ).then((ctrl) => {
      ringtoneStopRef.current = ctrl.stop;
    });
  }, [incomingRequest?.id, incomingRequest?.status, onDemandConfig.enabled, onDemandConfig.ringtone_asset_path]);

  useEffect(() => {
    if (!incomingRequest?.expires_at || incomingRequest.status !== "requested") return;
    const tick = () => {
      const now = Date.now();
      const exp = new Date(incomingRequest.expires_at).getTime();
      setSecondsLeft(Math.max(0, Math.ceil((exp - now) / 1000)));
    };
    tick();
    const interval = setInterval(tick, 1000);
    return () => clearInterval(interval);
  }, [incomingRequest?.expires_at, incomingRequest?.status]);

  const stopRingtoneAndClose = () => {
    ringtoneStopRef.current?.();
    setIncomingRequest(null);
  };

  const handleAccept = async () => {
    if (!incomingRequest?.id) return;
    ringtoneStopRef.current?.();
    setAccepting(true);
    try {
      const res = await fetcher.post<{ data: { request: OnDemandRequestRow; booking_id: string } }>(
        `/api/provider/on-demand/requests/${incomingRequest.id}/accept`,
        {}
      );
      const payload = (res as { data?: { request: OnDemandRequestRow; booking_id: string } }).data;
      if (payload?.booking_id) {
        toast.success("Request accepted");
        window.location.href = `/provider/bookings/${payload.booking_id}`;
      } else {
        toast.success("Request accepted");
        setIncomingRequest(null);
      }
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Failed to accept");
    } finally {
      setAccepting(false);
    }
  };

  const handleDecline = async () => {
    if (!incomingRequest?.id) return;
    ringtoneStopRef.current?.();
    setDeclining(true);
    try {
      await fetcher.post(`/api/provider/on-demand/requests/${incomingRequest.id}/decline`, {});
      toast.success("Request declined");
      setIncomingRequest(null);
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Failed to decline");
    } finally {
      setDeclining(false);
    }
  };

  if (!onDemandAcceptEnabled) return null;
  if (!incomingRequest || incomingRequest.status !== "requested") return null;

  const uiCopy = (onDemandConfig.ui_copy ?? {}) as Record<string, string>;
  const title = uiCopy.provider_incoming_title ?? "Incoming request";
  const subtitle = uiCopy.provider_incoming_subtitle ?? "A client is requesting a booking now";
  const acceptCta = uiCopy.provider_accept_cta ?? "Accept";
  const declineCta = uiCopy.provider_decline_cta ?? "Decline";

  const content = (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/60 p-4">
      <div className="w-full max-w-md rounded-2xl bg-white shadow-xl p-6">
        <div className="flex flex-col items-center text-center mb-6">
          <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center mb-4">
            <Bell className="h-8 w-8 text-primary" />
          </div>
          <h2 className="text-xl font-semibold text-gray-900">{title}</h2>
          <p className="text-gray-600 text-sm mt-1">{subtitle}</p>
        </div>
        {incomingRequest.request_payload?.services && (
          <p className="text-gray-500 text-sm mb-4">
            {(incomingRequest.request_payload.services as any[]).length} service(s) selected
          </p>
        )}
        {secondsLeft !== null && (
          <div className="text-center mb-6">
            <span className="text-2xl font-mono font-semibold text-gray-900">
              {Math.floor(secondsLeft / 60)}:{(secondsLeft % 60).toString().padStart(2, "0")}
            </span>
            <p className="text-xs text-gray-500 mt-1">Time remaining</p>
          </div>
        )}
        <div className="flex gap-3">
          <Button
            onClick={handleAccept}
            disabled={accepting || declining}
            className="flex-1"
          >
            {accepting ? "Accepting..." : acceptCta}
          </Button>
          <Button
            variant="outline"
            onClick={handleDecline}
            disabled={accepting || declining}
            className="flex-1"
          >
            {declining ? "Declining..." : declineCta}
          </Button>
        </div>
      </div>
    </div>
  );

  return typeof document !== "undefined" ? createPortal(content, document.body) : null;
}

"use client";

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Copy, Download, RefreshCw, QrCode, AlertCircle } from "lucide-react";
import { toast } from "sonner";
import { generateQRCodeDataURL, type QRCodeData } from "@/lib/qr/generator";

interface QRCodeDisplayProps {
  qrData: QRCodeData;
  onRefresh?: () => void;
  title?: string;
  description?: string;
}

export function QRCodeDisplay({
  qrData,
  onRefresh,
  title = "Verification QR Code",
  description = "Customer can scan this code to verify your arrival",
}: QRCodeDisplayProps) {
  const [qrCodeUrl, setQrCodeUrl] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);

  useEffect(() => {
    generateQR();
  }, [qrData]);

  const generateQR = async () => {
    try {
      setIsGenerating(true);
      const dataURL = await generateQRCodeDataURL(qrData);
      setQrCodeUrl(dataURL);
    } catch (error) {
      console.error("Failed to generate QR code:", error);
      toast.error("Failed to generate QR code");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDownload = () => {
    if (!qrCodeUrl) return;
    const link = document.createElement("a");
    link.href = qrCodeUrl;
    link.download = `qr-code-${qrData.booking_number}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    toast.success("QR code downloaded");
  };

  const handleCopyImage = async () => {
    if (!qrCodeUrl) return;
    try {
      const response = await fetch(qrCodeUrl);
      const blob = await response.blob();
      await navigator.clipboard.write([
        new ClipboardItem({ "image/png": blob }),
      ]);
      toast.success("QR code copied to clipboard");
    } catch (error) {
      console.error("Failed to copy QR code:", error);
      toast.error("Failed to copy QR code");
    }
  };

  const handleCopyCode = () => {
    navigator.clipboard.writeText(qrData.verification_code);
    toast.success("Verification code copied");
  };

  if (isGenerating) {
    return (
      <div className="flex items-center justify-center p-8 sm:p-12 bg-gradient-to-br from-gray-50 to-gray-100/50 rounded-xl border-2 border-dashed border-gray-300">
        <div className="text-center">
          <div className="relative w-12 h-12 sm:w-16 sm:h-16 mx-auto mb-3 sm:mb-4">
            <RefreshCw className="w-full h-full animate-spin text-[#FF0077]" />
            <div className="absolute inset-0 rounded-full border-2 border-[#FF0077]/20"></div>
          </div>
          <p className="text-sm sm:text-base font-medium text-gray-700">Generating QR code...</p>
          <p className="text-xs sm:text-sm text-gray-500 mt-1">Please wait</p>
        </div>
      </div>
    );
  }

  if (!qrCodeUrl) {
    return (
      <div className="p-4 sm:p-6 bg-red-50/50 border-2 border-red-200 rounded-xl">
        <div className="flex items-start gap-3">
          <AlertCircle className="w-5 h-5 text-red-600 mt-0.5 flex-shrink-0" />
          <div className="flex-1 min-w-0">
            <p className="text-sm sm:text-base font-semibold text-red-900 mb-1">Failed to generate QR code</p>
            <p className="text-xs sm:text-sm text-red-700 mb-3">Please try again or contact support if the issue persists.</p>
            {onRefresh && (
              <Button 
                onClick={onRefresh} 
                variant="outline" 
                size="sm" 
                className="w-full sm:w-auto min-h-[44px] touch-manipulation border-2 border-red-300 text-red-700 hover:bg-red-50"
              >
                <RefreshCw className="w-4 h-4 mr-2" />
                Try Again
              </Button>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="p-3 sm:p-4 bg-white border rounded-xl shadow-sm">
      <div className="flex items-start gap-2 sm:gap-3 mb-3 sm:mb-4">
        <div className="p-1.5 sm:p-2 bg-[#FF0077]/10 rounded-lg flex-shrink-0">
          <QrCode className="w-4 h-4 sm:w-5 sm:h-5 text-[#FF0077]" />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm sm:text-base font-semibold text-gray-900 mb-1 leading-tight">{title}</p>
          {description && (
            <p className="text-xs sm:text-sm text-gray-600 leading-relaxed">{description}</p>
          )}
        </div>
      </div>

      {/* QR Code Display - Mobile Optimized */}
      <div className="flex flex-col items-center mb-4 sm:mb-5">
        <div className="bg-white p-3 sm:p-4 rounded-xl border-2 border-gray-200 shadow-sm mb-3 sm:mb-4 w-full max-w-[280px] sm:max-w-none">
          <div className="aspect-square w-full flex items-center justify-center">
            <img
              src={qrCodeUrl}
              alt="QR Code"
              className="w-full h-full object-contain"
              style={{ maxWidth: '100%', maxHeight: '100%' }}
            />
          </div>
        </div>
        <div className="flex items-center gap-1.5 text-xs sm:text-sm text-gray-500">
          <QrCode className="w-3.5 h-3.5" />
          <span>Customer scans this code to verify</span>
        </div>
      </div>

      {/* Verification Code - Enhanced Mobile UX */}
      <div className="mb-4 sm:mb-5 p-3 sm:p-4 bg-gradient-to-br from-gray-50 to-gray-100/50 rounded-xl border border-gray-200">
        <div className="flex items-center justify-between mb-2">
          <p className="text-xs sm:text-sm font-semibold text-gray-700">Verification Code</p>
          <span className="text-[10px] sm:text-xs text-gray-500 font-medium">15 min expiry</span>
        </div>
        <div className="flex items-stretch gap-2 sm:gap-3">
          <div className="flex-1 bg-white border-2 border-gray-300 rounded-lg px-3 sm:px-4 py-3 sm:py-3.5 flex items-center justify-center min-h-[52px] sm:min-h-[56px]">
            <p className="text-xl sm:text-2xl font-mono font-bold text-center tracking-[0.2em] text-gray-900 select-all">
              {qrData.verification_code}
            </p>
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={handleCopyCode}
            className="min-w-[52px] sm:min-w-[56px] min-h-[52px] sm:min-h-[56px] touch-manipulation active:scale-95 transition-transform border-2"
            aria-label="Copy verification code"
          >
            <Copy className="w-5 h-5 sm:w-5 sm:h-5" />
          </Button>
        </div>
        <p className="text-[10px] sm:text-xs text-gray-500 mt-2.5 text-center">
          Tap code to select ΓÇó Share with customer
        </p>
      </div>

      {/* Actions - Mobile First Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-2 sm:gap-2.5">
        <Button
          variant="outline"
          onClick={handleDownload}
          className="w-full min-h-[48px] sm:min-h-[44px] touch-manipulation active:scale-[0.98] transition-transform font-medium text-sm sm:text-sm border-2 hover:bg-gray-50"
        >
          <Download className="w-4 h-4 sm:w-4 sm:h-4 mr-2 flex-shrink-0" />
          <span className="hidden xs:inline">Download</span>
          <span className="xs:hidden">Save</span>
        </Button>
        <Button
          variant="outline"
          onClick={handleCopyImage}
          className="w-full min-h-[48px] sm:min-h-[44px] touch-manipulation active:scale-[0.98] transition-transform font-medium text-sm sm:text-sm border-2 hover:bg-gray-50"
        >
          <Copy className="w-4 h-4 sm:w-4 sm:h-4 mr-2 flex-shrink-0" />
          <span className="hidden xs:inline">Copy Image</span>
          <span className="xs:hidden">Copy</span>
        </Button>
        {onRefresh && (
          <Button
            variant="outline"
            onClick={onRefresh}
            className="w-full min-h-[48px] sm:min-h-[44px] touch-manipulation active:scale-[0.98] transition-transform font-medium text-sm sm:text-sm border-2 hover:bg-gray-50"
          >
            <RefreshCw className="w-4 h-4 sm:w-4 sm:h-4 mr-2 flex-shrink-0" />
            <span className="hidden xs:inline">Refresh</span>
            <span className="xs:hidden">New</span>
          </Button>
        )}
      </div>
    </div>
  );
}

