"use client";

import React, { useRef, useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { X, Camera, AlertCircle } from "lucide-react";
import { toast } from "sonner";
import { validateQRCodeData, type QRCodeData } from "@/lib/qr/generator";

interface QRCodeScannerProps {
  onScan: (data: QRCodeData) => void;
  onClose: () => void;
  bookingId: string;
  title?: string;
}

export function QRCodeScanner({
  onScan,
  onClose,
  bookingId,
  title = "Scan QR Code",
}: QRCodeScannerProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [scannedData, setScannedData] = useState<QRCodeData | null>(null);

  useEffect(() => {
    startScanner();
    return () => {
      stopScanner();
    };
  }, []);

  const startScanner = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: "environment", // Use back camera on mobile
        },
      });

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
        setIsScanning(true);
      }
    } catch (err: any) {
      console.error("Error accessing camera:", err);
      setError("Unable to access camera. Please check permissions.");
      toast.error("Camera access denied");
    }
  };

  const stopScanner = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }
    setIsScanning(false);
  };

  const handleManualInput = () => {
    const code = prompt("Enter verification code:");
    if (code && code.length === 8) {
      // Create QR data from manual input
      const qrData: QRCodeData = {
        booking_id: bookingId,
        booking_number: "", // Will be validated on server
        verification_code: code.toUpperCase(),
        expires_at: new Date(Date.now() + 15 * 60 * 1000).toISOString(),
        type: "arrival_verification",
      };
      handleQRCodeScanned(qrData);
    } else if (code) {
      toast.error("Invalid verification code format");
    }
  };

  const handleQRCodeScanned = (data: QRCodeData) => {
    if (validateQRCodeData(data, bookingId)) {
      setScannedData(data);
      onScan(data);
      stopScanner();
    } else {
      toast.error("Invalid or expired QR code");
    }
  };

  // Note: For full QR code scanning, you would need to integrate a library like
  // @zxing/library or html5-qrcode. This is a basic implementation.
  // For now, we'll use manual input as a fallback.

  return (
    <div className="fixed inset-0 z-50 bg-black bg-opacity-75 flex items-center justify-center p-4">
      <div className="bg-white rounded-lg max-w-md w-full p-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold">{title}</h3>
          <Button
            variant="ghost"
            size="icon"
            onClick={() => {
              stopScanner();
              onClose();
            }}
          >
            <X className="w-5 h-5" />
          </Button>
        </div>

        {error ? (
          <div className="p-4 bg-red-50 border border-red-200 rounded-lg mb-4">
            <div className="flex items-start gap-2">
              <AlertCircle className="w-5 h-5 text-red-600 mt-0.5" />
              <div className="flex-1">
                <p className="text-sm font-medium text-red-900 mb-1">Camera Error</p>
                <p className="text-xs text-red-700">{error}</p>
              </div>
            </div>
          </div>
        ) : null}

        {/* Video Preview */}
        <div className="relative bg-black rounded-lg overflow-hidden mb-4" style={{ aspectRatio: "1" }}>
          {isScanning ? (
            <video
              ref={videoRef}
              autoPlay
              playsInline
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="flex items-center justify-center h-full">
              <Camera className="w-16 h-16 text-gray-400" />
            </div>
          )}
          {/* Scanning overlay */}
          {isScanning && (
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="w-64 h-64 border-4 border-[#FF0077] rounded-lg" />
            </div>
          )}
        </div>

        {/* Manual Input Fallback */}
        <div className="space-y-3">
          <p className="text-sm text-gray-600 text-center">
            Point camera at QR code or enter code manually
          </p>
          <Button
            onClick={handleManualInput}
            variant="outline"
            className="w-full min-h-[44px] touch-manipulation"
          >
            Enter Code Manually
          </Button>
          <Button
            onClick={() => {
              stopScanner();
              onClose();
            }}
            variant="ghost"
            className="w-full min-h-[44px] touch-manipulation"
          >
            Cancel
          </Button>
        </div>

        {scannedData && (
          <div className="mt-4 p-3 bg-green-50 border border-green-200 rounded-lg">
            <p className="text-sm text-green-800">
              QR code scanned successfully!
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Calendar, Loader2 } from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import { format, parseISO } from "date-fns";

interface AvailableSlot {
  date: string;
  time: string;
  staff_id: string;
  staff_name: string;
}

interface QuickBookingModalProps {
  isOpen: boolean;
  onClose: () => void;
  waitlistEntryId: string;
  clientName: string;
  serviceName: string;
  availableSlots: AvailableSlot[];
  onSuccess?: () => void;
}

export default function QuickBookingModal({
  isOpen,
  onClose,
  waitlistEntryId,
  clientName,
  serviceName,
  availableSlots,
  onSuccess,
}: QuickBookingModalProps) {
  const [selectedSlot, setSelectedSlot] = useState<string>("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (!selectedSlot) {
      toast.error("Please select a time slot");
      return;
    }

    setIsSubmitting(true);
    try {
      const [date, time, staffId] = selectedSlot.split("|");
      await fetcher.post(`/api/provider/waitlist/${waitlistEntryId}/quick-book`, {
        date,
        time,
        staff_id: staffId,
      });

      toast.success("Booking created successfully!");
      onClose();
      setSelectedSlot("");
      onSuccess?.();
    } catch (error: any) {
      toast.error(error.message || "Failed to create booking. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const slotOptions = availableSlots.map((slot) => ({
    value: `${slot.date}|${slot.time}|${slot.staff_id}`,
    label: `${format(parseISO(slot.date), "MMM d, yyyy")} at ${slot.time} with ${slot.staff_name}`,
    slot,
  }));

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>Quick Book from Waitlist</DialogTitle>
          <DialogDescription>
            Create a booking for {clientName} from the waitlist.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          <div className="bg-gray-50 p-4 rounded-lg">
            <div className="space-y-2">
              <div>
                <span className="text-sm font-medium text-gray-700">Client:</span>
                <span className="ml-2 text-sm text-gray-900">{clientName}</span>
              </div>
              <div>
                <span className="text-sm font-medium text-gray-700">Service:</span>
                <span className="ml-2 text-sm text-gray-900">{serviceName}</span>
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="slot">Select Time Slot *</Label>
            <Select value={selectedSlot} onValueChange={setSelectedSlot}>
              <SelectTrigger>
                <SelectValue placeholder="Choose a time slot" />
              </SelectTrigger>
              <SelectContent>
                {slotOptions.map((option) => (
                  <SelectItem key={option.value} value={option.value}>
                    <div className="flex items-center gap-2">
                      <Calendar className="w-4 h-4" />
                      <span>{option.label}</span>
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {slotOptions.length === 0 && (
              <p className="text-sm text-amber-600">
                No available slots. Please refresh the waitlist matches.
              </p>
            )}
          </div>

          {selectedSlot && (
            <div className="bg-blue-50 p-4 rounded-lg">
              <p className="text-sm text-blue-900">
                This will create a booking and notify the client automatically.
              </p>
            </div>
          )}

          <div className="flex gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={onClose}
              className="flex-1"
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              onClick={handleSubmit}
              className="flex-1 bg-[#FF0077] hover:bg-[#D60565]"
              disabled={isSubmitting || !selectedSlot || slotOptions.length === 0}
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Creating...
                </>
              ) : (
                "Create Booking"
              )}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Check, AlertCircle, Plus, Trash2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";

interface Resource {
  id: string;
  name: string;
  description?: string;
  resource_group_id?: string;
  resource_group_name?: string;
  capacity?: number;
}

interface BookingResource {
  id: string;
  resource_id: string;
  resource_name: string;
  booking_id: string;
}

interface ResourceAssignmentPanelProps {
  bookingId: string;
  bookingDate: Date;
  bookingTime: string;
  onUpdate?: () => void;
}

export default function ResourceAssignmentPanel({
  bookingId,
  bookingDate,
  bookingTime,
  onUpdate,
}: ResourceAssignmentPanelProps) {
  const [availableResources, setAvailableResources] = useState<Resource[]>([]);
  const [assignedResources, setAssignedResources] = useState<BookingResource[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [selectedResourceId, setSelectedResourceId] = useState<string>("");

  useEffect(() => {
    loadResources();
    loadAssignedResources();
  }, [bookingId]);

  const loadResources = async () => {
    setIsLoading(true);
    try {
      const response = await fetcher.get<{ data?: Resource[]; resources?: Resource[] }>(
        `/api/provider/resources`
      );
      const list = response.data ?? response.resources ?? [];
      setAvailableResources(Array.isArray(list) ? list : []);
    } catch (error: any) {
      toast.error(error.message || "Failed to load resources");
    } finally {
      setIsLoading(false);
    }
  };

  const loadAssignedResources = async () => {
    try {
      const response = await fetcher.get<{ data?: { resources?: BookingResource[] }; resources?: BookingResource[] }>(
        `/api/provider/bookings/${bookingId}/resources`
      );
      const list = response.data?.resources ?? response.resources ?? [];
      setAssignedResources(Array.isArray(list) ? list : []);
    } catch {
      setAssignedResources([]);
    }
  };

  const handleAssignResource = async () => {
    if (!selectedResourceId) return;

    setIsLoading(true);
    try {
      await fetcher.post(`/api/provider/bookings/${bookingId}/resources`, {
        resource_id: selectedResourceId,
      });

      toast.success("Resource assigned successfully");
      setSelectedResourceId("");
      loadAssignedResources();
      onUpdate?.();
    } catch (error: any) {
      const msg = (error as { message?: string })?.message ?? "Failed to assign resource";
      toast.error(msg.includes("not available") ? "This resource is not available at this time" : msg);
    } finally {
      setIsLoading(false);
    }
  };

  const handleRemoveResource = async (resourceId: string) => {
    setIsLoading(true);
    try {
      await fetcher.delete(
        `/api/provider/bookings/${bookingId}/resources/${resourceId}`
      );
      toast.success("Resource removed successfully");
      loadAssignedResources();
      onUpdate?.();
    } catch (error: any) {
      toast.error(error.message || "Failed to remove resource");
    } finally {
      setIsLoading(false);
    }
  };

  const unassignedResources = availableResources.filter(
    (r) => !assignedResources.some((ar) => ar.resource_id === r.id)
  );

  return (
    <Card>
      <CardHeader>
        <CardTitle>Resource Assignment</CardTitle>
        <CardDescription>
          Assign resources (rooms, equipment) to this booking
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Assigned Resources */}
        {assignedResources.length > 0 && (
          <div className="space-y-2">
            <Label>Assigned Resources</Label>
            <div className="space-y-2">
              {assignedResources.map((resource) => (
                <div
                  key={resource.id}
                  className="flex items-center justify-between p-3 bg-gray-50 rounded-lg"
                >
                  <div className="flex items-center gap-2">
                    <Check className="w-4 h-4 text-green-600" />
                    <span className="text-sm font-medium">{resource.resource_name}</span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleRemoveResource(resource.id)}
                    className="text-red-600 hover:text-red-700"
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Assign New Resource */}
        {unassignedResources.length > 0 && (
          <div className="space-y-2">
            <Label>Assign Resource</Label>
            <div className="flex gap-2">
              <Select value={selectedResourceId} onValueChange={setSelectedResourceId}>
                <SelectTrigger className="flex-1">
                  <SelectValue placeholder="Select a resource" />
                </SelectTrigger>
                <SelectContent>
                  {unassignedResources.map((resource) => (
                    <SelectItem key={resource.id} value={resource.id}>
                      {resource.name}
                      {resource.resource_group_name && (
                        <span className="text-gray-500 ml-2">
                          ({resource.resource_group_name})
                        </span>
                      )}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Button
                onClick={handleAssignResource}
                disabled={!selectedResourceId || isLoading}
                className="bg-[#FF0077] hover:bg-[#D60565]"
              >
                <Plus className="w-4 h-4 mr-1" />
                Assign
              </Button>
            </div>
          </div>
        )}

        {availableResources.length === 0 && (
          <div className="text-center py-8 text-gray-500">
            <AlertCircle className="w-8 h-8 mx-auto mb-2 text-gray-400" />
            <p className="text-sm">No resources available</p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import React, { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { CalendarIcon } from "lucide-react";
import { format } from "date-fns";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { fetcher } from "@/lib/http/fetcher";
import type { TeamMember } from "@/lib/provider-portal/types";

interface SetDayOffDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  staffMember: TeamMember | null;
  selectedDate?: Date;
  onSuccess?: () => void;
}

export function SetDayOffDialog({
  open,
  onOpenChange,
  staffMember,
  selectedDate: initialDate,
  onSuccess,
}: SetDayOffDialogProps) {
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(initialDate || new Date());
  const [reason, setReason] = useState("");
  const [isSaving, setIsSaving] = useState(false);

  React.useEffect(() => {
    if (open && initialDate) {
      setSelectedDate(initialDate);
    }
    if (!open) {
      setReason("");
    }
  }, [open, initialDate]);

  const handleSave = async () => {
    if (!staffMember) {
      toast.error("No staff member selected");
      return;
    }

    if (!selectedDate) {
      toast.error("Please select a date");
      return;
    }

    try {
      setIsSaving(true);
      const dateStr = format(selectedDate, "yyyy-MM-dd");
      
      await fetcher.post(`/api/provider/staff/${staffMember.id}/days-off`, {
        date: dateStr,
        reason: reason || undefined,
        type: reason || "Day Off",
      });

      toast.success(`Day off set for ${staffMember.name}`);
      onOpenChange(false);
      onSuccess?.();
    } catch (error: any) {
      console.error("Failed to set day off:", error);
      toast.error(error?.message || "Failed to set day off");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Set Day Off</DialogTitle>
        </DialogHeader>
        <div className="grid gap-4 py-4">
          <div className="space-y-2">
            <Label>Staff Member</Label>
            <div className="text-sm text-gray-600 font-medium">
              {staffMember?.name || "No staff member selected"}
            </div>
          </div>

          <div className="space-y-2">
            <Label>Date</Label>
            <Popover>
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  className={cn(
                    "w-full justify-start text-left font-normal",
                    !selectedDate && "text-muted-foreground"
                  )}
                >
                  <CalendarIcon className="mr-2 h-4 w-4" />
                  {selectedDate ? format(selectedDate, "PPP") : "Pick a date"}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0" align="start">
                <Calendar
                  mode="single"
                  selected={selectedDate}
                  onSelect={setSelectedDate}
                  initialFocus
                />
              </PopoverContent>
            </Popover>
          </div>

          <div className="space-y-2">
            <Label htmlFor="reason">Reason (Optional)</Label>
            <Input
              id="reason"
              placeholder="e.g., Vacation, Sick leave, Personal"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
            />
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isSaving}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={isSaving || !selectedDate}>
            {isSaving ? "Saving..." : "Set Day Off"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import type { TimeBlock, BlockedTimeType, TeamMember, RecurrencePattern } from "@/lib/provider-portal/types";
import { providerApi } from "@/lib/provider-portal/api";
import { toast } from "sonner";

interface TimeBlockDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  block?: TimeBlock | null;
  blockedTimeTypes: BlockedTimeType[];
  onSuccess?: () => void;
}

export function TimeBlockDialog({
  open,
  onOpenChange,
  block,
  blockedTimeTypes,
  onSuccess,
}: TimeBlockDialogProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);

  const [formData, setFormData] = useState({
    name: block?.name || "",
    description: block?.description || "",
    team_member_id: block?.team_member_id || "",
    date: block?.date || new Date().toISOString().split("T")[0],
    start_time: block?.start_time || "09:00",
    end_time: block?.end_time || "10:00",
    is_recurring: block?.is_recurring || false,
    blocked_time_type_id: block?.blocked_time_type_id || "",
    recurrence_pattern: block?.recurrence_rule?.pattern || "weekly",
    recurrence_end_date: block?.recurrence_rule?.end_date || "",
    recurrence_occurrences: block?.recurrence_rule?.occurrences || undefined,
  });

  useEffect(() => {
    if (open) {
      loadTeamMembers();
      if (block) {
        setFormData({
          name: block.name,
          description: block.description || "",
          team_member_id: block.team_member_id || "",
          date: block.date,
          start_time: block.start_time,
          end_time: block.end_time,
          is_recurring: block.is_recurring,
          blocked_time_type_id: block.blocked_time_type_id || "",
          recurrence_pattern: block.recurrence_rule?.pattern || "weekly",
          recurrence_end_date: block.recurrence_rule?.end_date || "",
          recurrence_occurrences: block.recurrence_rule?.occurrences,
        });
      }
    }
  }, [open, block]);

  const loadTeamMembers = async () => {
    try {
      const members = await providerApi.listTeamMembers();
      setTeamMembers(members);
    } catch (error) {
      console.error("Failed to load team members:", error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const blockData: Partial<TimeBlock> = {
        name: formData.name,
        description: formData.description,
        team_member_id: formData.team_member_id || undefined,
        team_member_name: teamMembers.find((m) => m.id === formData.team_member_id)?.name,
        date: formData.date,
        start_time: formData.start_time,
        end_time: formData.end_time,
        is_recurring: formData.is_recurring,
        blocked_time_type_id: formData.blocked_time_type_id || undefined,
        blocked_time_type_name: blockedTimeTypes.find((t) => t.id === formData.blocked_time_type_id)?.name,
        recurrence_rule: formData.is_recurring
          ? {
              pattern: formData.recurrence_pattern as any,
              interval: formData.recurrence_pattern === "biweekly" ? 2 : 1,
              end_date: formData.recurrence_end_date || undefined,
              occurrences: formData.recurrence_occurrences,
            }
          : undefined,
      };

      if (block) {
        await providerApi.updateTimeBlock(block.id, blockData);
        toast.success("Time block updated");
      } else {
        await providerApi.createTimeBlock(blockData);
        toast.success("Time block created");
      }
      onSuccess?.();
      onOpenChange(false);
    } catch (error) {
      console.error("Failed to save time block:", error);
      toast.error("Failed to save time block");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{block ? "Edit Time Block" : "New Time Block"}</DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="name">Name *</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              placeholder="e.g., Lunch Break, Training Session"
              required
            />
          </div>

          <div>
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              rows={2}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="team_member_id">Team Member (Optional)</Label>
              <Select
                value={formData.team_member_id}
                onValueChange={(value) => setFormData({ ...formData, team_member_id: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="All team members" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">All team members</SelectItem>
                  {teamMembers.map((member) => (
                    <SelectItem key={member.id} value={member.id}>
                      {member.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label htmlFor="blocked_time_type_id">Blocked Time Type</Label>
              <Select
                value={formData.blocked_time_type_id}
                onValueChange={(value) => setFormData({ ...formData, blocked_time_type_id: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">None</SelectItem>
                  {blockedTimeTypes.map((type) => (
                    <SelectItem key={type.id} value={type.id}>
                      {type.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div>
              <Label htmlFor="date">Date *</Label>
              <Input
                id="date"
                type="date"
                value={formData.date}
                onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                required
              />
            </div>
            <div>
              <Label htmlFor="start_time">Start Time *</Label>
              <Input
                id="start_time"
                type="time"
                value={formData.start_time}
                onChange={(e) => setFormData({ ...formData, start_time: e.target.value })}
                required
              />
            </div>
            <div>
              <Label htmlFor="end_time">End Time *</Label>
              <Input
                id="end_time"
                type="time"
                value={formData.end_time}
                onChange={(e) => setFormData({ ...formData, end_time: e.target.value })}
                required
              />
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Checkbox
              id="is_recurring"
              checked={formData.is_recurring}
              onCheckedChange={(checked) =>
                setFormData({ ...formData, is_recurring: !!checked })
              }
            />
            <Label htmlFor="is_recurring" className="cursor-pointer">
              Recurring time block
            </Label>
          </div>

          {formData.is_recurring && (
            <div className="space-y-4 pl-6 border-l-2">
              <div>
                <Label htmlFor="recurrence_pattern">Recurrence Pattern</Label>
                <Select
                  value={formData.recurrence_pattern}
                  onValueChange={(value) =>
                    setFormData({ ...formData, recurrence_pattern: value as RecurrencePattern })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="daily">Daily</SelectItem>
                    <SelectItem value="weekly">Weekly</SelectItem>
                    <SelectItem value="biweekly">Bi-weekly</SelectItem>
                    <SelectItem value="monthly">Monthly</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="recurrence_end_date">End Date (Optional)</Label>
                  <Input
                    id="recurrence_end_date"
                    type="date"
                    value={formData.recurrence_end_date}
                    onChange={(e) =>
                      setFormData({ ...formData, recurrence_end_date: e.target.value })
                    }
                  />
                </div>
                <div>
                  <Label htmlFor="recurrence_occurrences">Number of Occurrences</Label>
                  <Input
                    id="recurrence_occurrences"
                    type="number"
                    min={1}
                    value={formData.recurrence_occurrences || ""}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        recurrence_occurrences: parseInt(e.target.value) || undefined,
                      })
                    }
                    placeholder="Leave empty for no limit"
                  />
                </div>
              </div>
            </div>
          )}

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isLoading}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isLoading}
              className="bg-[#FF0077] hover:bg-[#D60565]"
            >
              {isLoading ? "Saving..." : block ? "Update" : "Create"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect, useRef } from "react";
import { SectionCard } from "@/components/provider/SectionCard";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Search, User, Clock, CheckCircle, RefreshCw, Eye } from "lucide-react";
import type { WaitingRoomEntry } from "@/lib/provider-portal/types";
import { providerApi } from "@/lib/provider-portal/api";
import { toast } from "sonner";
import { format } from "date-fns";
import { useModuleConfig } from "@/providers/ConfigBundleProvider";
import { playRingtone } from "@/lib/on-demand/ringtone";

interface VirtualWaitingRoomProps {
  onEntrySelect?: (entry: WaitingRoomEntry) => void;
}

export function VirtualWaitingRoom({ onEntrySelect: _onEntrySelect }: VirtualWaitingRoomProps) {
  const [entries, setEntries] = useState<WaitingRoomEntry[]>([]);
  const [_isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, _setStatusFilter] = useState<"all" | "waiting" | "in_service" | "completed">("all");
  const onDemandConfig = useModuleConfig("on_demand");
  const prevWaitingCountRef = useRef<number | null>(null);
  const ringtoneStopRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    return () => {
      ringtoneStopRef.current?.();
    };
  }, []);

  useEffect(() => {
    loadEntries();
    // Auto-refresh every 30 seconds
    const interval = setInterval(loadEntries, 30000);
    return () => clearInterval(interval);
  }, [statusFilter]);

  const loadEntries = async () => {
    try {
      setIsLoading(true);
      const response = await providerApi.listWaitingRoomEntries();
      const waitingCount = response.filter((e) => e.status === "waiting").length;
      if (
        onDemandConfig.enabled &&
        onDemandConfig.ringtone_asset_path &&
        prevWaitingCountRef.current !== null &&
        waitingCount > prevWaitingCountRef.current
      ) {
        ringtoneStopRef.current?.();
        const ctrl = await playRingtone(
          {
            enabled: onDemandConfig.enabled,
            ringtone_asset_path: onDemandConfig.ringtone_asset_path,
            ring_duration_seconds: onDemandConfig.ring_duration_seconds ?? 20,
            ring_repeat: onDemandConfig.ring_repeat ?? true,
          },
          { environment: "production" }
        );
        ringtoneStopRef.current = ctrl.stop;
      }
      prevWaitingCountRef.current = waitingCount;
      setEntries(response);
    } catch (error) {
      console.error("Failed to load waiting room entries:", error);
      toast.error("Failed to load waiting room");
    } finally {
      setIsLoading(false);
    }
  };

  const handleStatusChange = async (entryId: string, newStatus: WaitingRoomEntry["status"]) => {
    try {
      await providerApi.updateWaitingRoomEntry(entryId, { status: newStatus });
      toast.success("Status updated");
      loadEntries();
    } catch (error) {
      console.error("Failed to update status:", error);
      toast.error("Failed to update status");
    }
  };

  const filteredEntries = entries.filter((entry) => {
    const matchesSearch =
      (entry?.client_name ?? "").toLowerCase().includes((searchQuery ?? "").toLowerCase()) ||
      (entry?.service_name ?? "").toLowerCase().includes((searchQuery ?? "").toLowerCase()) ||
      (entry?.client_phone ?? "").includes(searchQuery ?? "");

    const matchesStatus = statusFilter === "all" || entry.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  const waitingEntries = filteredEntries.filter(e => e.status === "waiting");
  const inServiceEntries = filteredEntries.filter(e => e.status === "in_service");
  const completedEntries = filteredEntries.filter(e => e.status === "completed");

  const getStatusColor = (status: WaitingRoomEntry["status"]) => {
    switch (status) {
      case "waiting":
        return "bg-yellow-100 text-yellow-800";
      case "in_service":
        return "bg-blue-100 text-blue-800";
      case "completed":
        return "bg-green-100 text-green-800";
      case "left":
        return "bg-gray-100 text-gray-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  const formatWaitTime = (checkedInTime: string) => {
    const now = new Date();
    const checkedIn = new Date(checkedInTime);
    const diffMinutes = Math.floor((now.getTime() - checkedIn.getTime()) / 60000);

    if (diffMinutes < 60) {
      return `${diffMinutes} min`;
    }
    const hours = Math.floor(diffMinutes / 60);
    const minutes = diffMinutes % 60;
    return `${hours}h ${minutes}m`;
  };

  return (
    <div className="space-y-4 sm:space-y-6">
      {/* Header with Stats */}
