"use client";

import { useState, useEffect } from "react";
import { Calendar, Clock, User, CheckCircle2, AlertCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { format, parseISO } from "date-fns";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import QuickBookingModal from "./QuickBookingModal";

interface WaitlistMatch {
  waitlist_entry_id: string;
  client_name: string;
  client_email?: string;
  client_phone?: string;
  service_name: string;
  preferred_date?: string;
  preferred_time_start?: string;
  preferred_time_end?: string;
  preferred_staff_id?: string;
  preferred_staff_name?: string;
  match_score: number;
  available_slots: Array<{
    date: string;
    time: string;
    staff_id: string;
    staff_name: string;
  }>;
}

interface WaitlistMatchesDashboardProps {
  providerId: string;
}

export default function WaitlistMatchesDashboard({ providerId }: WaitlistMatchesDashboardProps) {
  const [matches, setMatches] = useState<WaitlistMatch[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedDate, setSelectedDate] = useState<string>("");
  const [selectedStaff, setSelectedStaff] = useState<string>("all");
  const [selectedMatch, setSelectedMatch] = useState<WaitlistMatch | null>(null);
  const [isQuickBookingOpen, setIsQuickBookingOpen] = useState(false);

  useEffect(() => {
    loadMatches();
  }, [providerId, selectedDate, selectedStaff]);

  const loadMatches = async () => {
    setIsLoading(true);
    try {
      const params = new URLSearchParams();
      if (selectedDate) params.append("date", selectedDate);
      if (selectedStaff !== "all") params.append("staff_id", selectedStaff);

      const response = await fetcher.get<{ matches: WaitlistMatch[] }>(
        `/api/provider/waitlist/matches?${params.toString()}`
      );
      setMatches(response.matches || []);
    } catch (error: any) {
      toast.error(error.message || "Failed to load waitlist matches");
    } finally {
      setIsLoading(false);
    }
  };

  const handleQuickBook = (match: WaitlistMatch) => {
    setSelectedMatch(match);
    setIsQuickBookingOpen(true);
  };

  const handleBookingSuccess = () => {
    setIsQuickBookingOpen(false);
    setSelectedMatch(null);
    loadMatches();
    toast.success("Booking created successfully!");
  };

  const getScoreColor = (score: number) => {
    if (score >= 150) return "bg-green-100 text-green-700";
    if (score >= 100) return "bg-blue-100 text-blue-700";
    if (score >= 50) return "bg-amber-100 text-amber-700";
    return "bg-gray-100 text-gray-700";
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Waitlist Matches</h2>
          <p className="text-gray-600 mt-1">
            Find waitlist entries that match available slots
          </p>
        </div>
        <Button onClick={loadMatches} variant="outline">
          Refresh
        </Button>
      </div>

      {/* Filters */}
      <div className="flex gap-4">
        <div className="flex-1">
          <label className="text-sm font-medium mb-2 block">Date</label>
          <input
            type="date"
            value={selectedDate}
            onChange={(e) => setSelectedDate(e.target.value)}
            className="w-full px-3 py-2 border rounded-md"
            min={format(new Date(), "yyyy-MM-dd")}
          />
        </div>
        <div className="flex-1">
          <label className="text-sm font-medium mb-2 block">Staff</label>
          <Select value={selectedStaff} onValueChange={setSelectedStaff}>
            <SelectTrigger>
              <SelectValue placeholder="All staff" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All staff</SelectItem>
              {/* Staff options would be loaded from API */}
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Matches List */}
      {isLoading ? (
        <div className="text-center py-12">
          <p className="text-gray-500">Loading matches...</p>
        </div>
      ) : matches.length === 0 ? (
        <Card>
          <CardContent className="py-12 text-center">
            <AlertCircle className="w-12 h-12 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-semibold mb-2">No matches found</h3>
            <p className="text-gray-500">
              No waitlist entries match available slots for the selected criteria.
            </p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-4">
          {matches.map((match) => (
            <Card key={match.waitlist_entry_id} className="hover:shadow-md transition-shadow">
              <CardHeader>
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      <CardTitle className="text-lg">{match.client_name}</CardTitle>
                      <Badge className={getScoreColor(match.match_score)}>
                        Score: {match.match_score}
                      </Badge>
                    </div>
                    <CardDescription>{match.service_name}</CardDescription>
                  </div>
                  <Button
                    onClick={() => handleQuickBook(match)}
                    className="bg-[#FF0077] hover:bg-[#D60565]"
                  >
                    Quick Book
                  </Button>
                </div>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {/* Preferences */}
                  <div className="space-y-2">
                    <h4 className="text-sm font-semibold text-gray-700">Preferences</h4>
                    {match.preferred_date && (
                      <div className="flex items-center gap-2 text-sm text-gray-600">
                        <Calendar className="w-4 h-4" />
                        <span>{format(parseISO(match.preferred_date), "MMM d, yyyy")}</span>
                      </div>
                    )}
                    {match.preferred_time_start && match.preferred_time_end && (
                      <div className="flex items-center gap-2 text-sm text-gray-600">
                        <Clock className="w-4 h-4" />
                        <span>
                          {match.preferred_time_start} - {match.preferred_time_end}
                        </span>
                      </div>
                    )}
                    {match.preferred_staff_name && (
                      <div className="flex items-center gap-2 text-sm text-gray-600">
                        <User className="w-4 h-4" />
                        <span>{match.preferred_staff_name}</span>
                      </div>
                    )}
                  </div>

                  {/* Available Slots */}
                  <div className="space-y-2">
                    <h4 className="text-sm font-semibold text-gray-700">
                      Available Slots ({match.available_slots.length})
                    </h4>
                    {match.available_slots.length > 0 ? (
                      <div className="space-y-1">
                        {match.available_slots.slice(0, 3).map((slot, idx) => (
                          <div
                            key={idx}
                            className="flex items-center gap-2 text-sm text-gray-600 bg-gray-50 p-2 rounded"
                          >
                            <CheckCircle2 className="w-4 h-4 text-green-600" />
                            <span>
                              {format(parseISO(slot.date), "MMM d")} at {slot.time} with{" "}
                              {slot.staff_name}
                            </span>
                          </div>
                        ))}
                        {match.available_slots.length > 3 && (
                          <p className="text-xs text-gray-500">
                            +{match.available_slots.length - 3} more slots
                          </p>
                        )}
                      </div>
                    ) : (
                      <p className="text-sm text-gray-500">No available slots</p>
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Quick Booking Modal */}
      {selectedMatch && (
        <QuickBookingModal
          isOpen={isQuickBookingOpen}
          onClose={() => {
            setIsQuickBookingOpen(false);
            setSelectedMatch(null);
          }}
          waitlistEntryId={selectedMatch.waitlist_entry_id}
          clientName={selectedMatch.client_name}
          serviceName={selectedMatch.service_name}
          availableSlots={selectedMatch.available_slots}
          onSuccess={handleBookingSuccess}
        />
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { YocoDevice, YocoPayment } from "@/lib/provider-portal/types";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { CreditCard, Loader2, CheckCircle2, XCircle } from "lucide-react";
import { toast } from "sonner";
import { Money } from "./Money";

interface YocoPaymentDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  amount: number; // Amount in Rands (will be converted to cents)
  appointmentId?: string;
  saleId?: string;
  onSuccess?: (payment: YocoPayment) => void;
}

export function YocoPaymentDialog({
  open,
  onOpenChange,
  amount,
  appointmentId,
  saleId,
  onSuccess,
}: YocoPaymentDialogProps) {
  const [devices, setDevices] = useState<YocoDevice[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>("");
  const [customAmount, setCustomAmount] = useState<string>(amount.toString());
  const [isProcessing, setIsProcessing] = useState(false);
  const [paymentResult, setPaymentResult] = useState<YocoPayment | null>(null);

  useEffect(() => {
    if (open) {
      loadDevices();
      setCustomAmount(amount.toString());
      setPaymentResult(null);
    }
  }, [open, amount]);

  const loadDevices = async () => {
    try {
      const data = await providerApi.listYocoDevices();
      const activeDevices = data.filter((d) => d.is_active);
      setDevices(activeDevices);
      if (activeDevices.length > 0 && !selectedDeviceId) {
        setSelectedDeviceId(activeDevices[0].id);
      }
    } catch (error) {
      console.error("Failed to load devices:", error);
      toast.error("Failed to load payment devices");
    }
  };

  const handleProcessPayment = async () => {
    if (!selectedDeviceId) {
      toast.error("Please select a payment device");
      return;
    }

    const amount = parseFloat(customAmount);
    if (isNaN(amount) || amount <= 0) {
      toast.error("Please enter a valid amount");
      return;
    }

    try {
      setIsProcessing(true);
      setPaymentResult(null);

      // API expects amount in Rands (will convert to cents server-side)
      const payment = await providerApi.createYocoPayment({
        device_id: selectedDeviceId,
        amount: amount, // Amount in Rands
        currency: "ZAR",
        appointment_id: appointmentId,
        sale_id: saleId,
        metadata: {
          appointment_ref: appointmentId,
          sale_ref: saleId,
        },
      });

      setPaymentResult(payment);

      if (payment.status === "successful") {
        toast.success("Payment processed successfully!");
        onSuccess?.(payment);
        setTimeout(() => {
          onOpenChange(false);
        }, 2000);
      } else {
        toast.error(payment.error_message || "Payment failed");
      }
    } catch (error) {
      console.error("Payment processing failed:", error);
      toast.error("Failed to process payment");
    } finally {
      setIsProcessing(false);
    }
  };

  const selectedDevice = devices.find((d) => d.id === selectedDeviceId);
  const amountInCents = Math.round(parseFloat(customAmount) * 100) || 0;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <CreditCard className="w-5 h-5" />
            Process Yoco Payment
          </DialogTitle>
          <DialogDescription>
            Process a card payment through your Yoco device
          </DialogDescription>
        </DialogHeader>

        {paymentResult ? (
          <div className="space-y-4 py-4">
            {paymentResult.status === "successful" ? (
              <Alert className="bg-green-50 border-green-200">
                <CheckCircle2 className="h-4 w-4 text-green-600" />
                <AlertDescription className="text-green-800">
                  <div className="font-semibold mb-1">Payment Successful!</div>
                  <div className="text-sm space-y-1">
                    <div>Payment ID: {paymentResult.yoco_payment_id}</div>
                    <div>Amount: <Money amount={paymentResult.amount / 100} /></div>
                    <div>Device: {paymentResult.device_name}</div>
                  </div>
                </AlertDescription>
              </Alert>
            ) : (
              <Alert className="bg-red-50 border-red-200">
                <XCircle className="h-4 w-4 text-red-600" />
                <AlertDescription className="text-red-800">
                  <div className="font-semibold mb-1">Payment Failed</div>
                  <div className="text-sm">
                    {paymentResult.error_message || "Payment could not be processed"}
                  </div>
                </AlertDescription>
              </Alert>
            )}
          </div>
        ) : (
          <div className="space-y-4 py-4">
            <div>
              <Label htmlFor="device">Payment Device</Label>
              <Select value={selectedDeviceId} onValueChange={setSelectedDeviceId}>
                <SelectTrigger id="device" className="mt-1">
                  <SelectValue placeholder="Select a device" />
                </SelectTrigger>
                <SelectContent>
                  {devices.length === 0 ? (
                    <SelectItem value="" disabled>
                      No active devices available
                    </SelectItem>
                  ) : (
                    devices.map((device) => (
                      <SelectItem key={device.id} value={device.id}>
                        {device.name} {device.location_name && `(${device.location_name})`}
                      </SelectItem>
                    ))
                  )}
                </SelectContent>
              </Select>
              {devices.length === 0 && (
                <p className="text-xs text-gray-500 mt-1">
                  <a
                    href="/provider/settings/sales/yoco-devices"
                    className="text-pink-600 hover:underline"
                  >
                    Add a device
                  </a>{" "}
                  to process payments
                </p>
              )}
            </div>

            <div>
              <Label htmlFor="amount">Amount (ZAR)</Label>
              <Input
                id="amount"
                type="number"
                step="0.01"
                min="0.01"
                value={customAmount}
                onChange={(e) => setCustomAmount(e.target.value)}
                className="mt-1"
                disabled={isProcessing}
              />
              <p className="text-xs text-gray-500 mt-1">
                Amount: <Money amount={amountInCents / 100} />
              </p>
            </div>

            {selectedDevice && (
              <div className="p-3 bg-gray-50 rounded-lg text-sm">
                <div className="flex justify-between mb-1">
                  <span className="text-gray-600">Device:</span>
                  <span className="font-medium">{selectedDevice.name}</span>
                </div>
                {selectedDevice.location_name && (
                  <div className="flex justify-between">
                    <span className="text-gray-600">Location:</span>
                    <span>{selectedDevice.location_name}</span>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        <DialogFooter>
          {paymentResult ? (
            <Button onClick={() => onOpenChange(false)}>
              Close
            </Button>
          ) : (
            <>
              <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isProcessing}>
                Cancel
              </Button>
              <Button
                onClick={handleProcessPayment}
                disabled={isProcessing || !selectedDeviceId || devices.length === 0}
              >
                {isProcessing ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    Processing...
                  </>
                ) : (
                  <>
                    <CreditCard className="w-4 h-4 mr-2" />
                    Process Payment
                  </>
                )}
              </Button>
            </>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { History, User, Clock } from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Badge } from "@/components/ui/badge";
import LoadingTimeout from "@/components/ui/loading-timeout";

interface AuditLogEntry {
  id: string;
  booking_id: string;
  event_type: string;
  event_data: {
    previous_status?: string;
    new_status?: string;
    field?: string;
    old_value?: any;
    new_value?: any;
    reason?: string;
  };
  created_by: string;
  created_by_name?: string;
  created_at: string;
}

interface BookingAuditLogProps {
  bookingId: string;
  trigger?: React.ReactNode;
}

export function BookingAuditLog({ bookingId, trigger }: BookingAuditLogProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [auditLogs, setAuditLogs] = useState<AuditLogEntry[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (isOpen && bookingId) {
      loadAuditLogs();
    }
  }, [isOpen, bookingId]);

  const loadAuditLogs = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data: AuditLogEntry[] }>(
        `/api/provider/bookings/${bookingId}/audit-log`
      );
      setAuditLogs(response.data || []);
    } catch (error) {
      console.error("Failed to load audit logs:", error);
      setAuditLogs([]);
    } finally {
      setIsLoading(false);
    }
  };

  const getEventTypeLabel = (eventType: string): string => {
    const labels: Record<string, string> = {
      created: "Created",
      confirmed: "Confirmed",
      service_started: "Service Started",
      service_completed: "Service Completed",
      cancelled: "Cancelled",
      status_changed: "Status Changed",
      payment_received: "Payment Received",
      refunded: "Refunded",
      rescheduled: "Rescheduled",
      note_added: "Note Added",
    };
    return labels[eventType] || eventType;
  };

  const getStatusColor = (status?: string): string => {
    const colors: Record<string, string> = {
      pending: "bg-yellow-100 text-yellow-800",
      confirmed: "bg-green-100 text-green-800",
      in_progress: "bg-blue-100 text-blue-800",
      completed: "bg-purple-100 text-purple-800",
      cancelled: "bg-red-100 text-red-800",
    };
    return colors[status || ""] || "bg-gray-100 text-gray-800";
  };

  return (
    <Dialog open={isOpen} onOpenChange={setIsOpen}>
      <DialogTrigger asChild>
        {trigger || (
          <Button variant="outline" size="sm">
            <History className="w-4 h-4 mr-2" />
            View History
          </Button>
        )}
      </DialogTrigger>
      <DialogContent className="max-w-2xl max-h-[80vh]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <History className="w-5 h-5" />
            Booking History & Audit Log
          </DialogTitle>
        </DialogHeader>
        <ScrollArea className="max-h-[60vh] pr-4">
          {isLoading ? (
            <div className="py-8">
              <LoadingTimeout loadingMessage="Loading audit log..." />
            </div>
          ) : auditLogs.length === 0 ? (
            <div className="py-8 text-center text-gray-500">
              No audit log entries found
            </div>
          ) : (
            <div className="space-y-4">
              {auditLogs.map((entry) => (
                <div
                  key={entry.id}
                  className="border rounded-lg p-4 space-y-2"
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <Badge variant="outline">
                          {getEventTypeLabel(entry.event_type)}
                        </Badge>
                        {entry.event_data.previous_status && (
                          <>
                            <span className="text-gray-400">ΓåÆ</span>
                            <Badge className={getStatusColor(entry.event_data.previous_status)}>
                              {entry.event_data.previous_status}
                            </Badge>
                            <span className="text-gray-400">ΓåÆ</span>
                            <Badge className={getStatusColor(entry.event_data.new_status)}>
                              {entry.event_data.new_status}
                            </Badge>
                          </>
                        )}
                      </div>
                      {entry.event_data.reason && (
                        <p className="text-sm text-gray-600 mb-2">
                          Reason: {entry.event_data.reason}
                        </p>
                      )}
                      {entry.event_data.field && (
                        <p className="text-sm text-gray-600">
                          {entry.event_data.field}:{" "}
                          <span className="line-through text-red-500">
                            {String(entry.event_data.old_value)}
                          </span>{" "}
                          ΓåÆ{" "}
                          <span className="text-green-500">
                            {String(entry.event_data.new_value)}
                          </span>
                        </p>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-4 text-xs text-gray-500 pt-2 border-t">
                    <div className="flex items-center gap-1">
                      <User className="w-3 h-3" />
                      <span>{entry.created_by_name || "System"}</span>
                    </div>
                    <div className="flex items-center gap-1">
                      <Clock className="w-3 h-3" />
                      <span>
                        {new Date(entry.created_at).toLocaleString("en-US", {
                          year: "numeric",
                          month: "short",
                          day: "numeric",
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                      </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </ScrollArea>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useRef, useCallback, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { fetcher, FetchError } from "@/lib/http/fetcher";
import { toast } from "sonner";
import {
  Loader2,
  Upload,
  X,
  ChevronLeft,
  ChevronRight,
  Camera,
  ImageIcon,
  FlipHorizontal,
} from "lucide-react";
import type { ExplorePost } from "@/types/explore";

const ALLOWED_IMAGE_TYPES = ["image/jpeg", "image/jpg", "image/png", "image/webp"];
const ALLOWED_VIDEO_TYPES = ["video/mp4", "video/webm", "video/quicktime"];
const ALLOWED_TYPES = [...ALLOWED_IMAGE_TYPES, ...ALLOWED_VIDEO_TYPES];
const MAX_IMAGE_SIZE = 5 * 1024 * 1024; // 5MB
const MAX_VIDEO_SIZE = 50 * 1024 * 1024; // 50MB

const VIDEO_EXTENSIONS = [".mp4", ".webm", ".mov"];

function isVideoPath(path: string): boolean {
  const lower = path.toLowerCase();
  return VIDEO_EXTENSIONS.some((ext) => lower.endsWith(ext));
}

interface ExplorePostFormProps {
  post?: ExplorePost;
  onSuccess: () => void;
  onCancel?: () => void;
}

export function ExplorePostForm({
  post,
  onSuccess,
  onCancel,
}: ExplorePostFormProps) {
  const [caption, setCaption] = useState(post?.caption ?? "");
  const [tags, setTags] = useState<string[]>(post?.tags ?? []);
  const [tagInput, setTagInput] = useState("");
  const [mediaPaths, setMediaPaths] = useState<string[]>(() => {
    if (!post?.media_urls?.length) return [];
    return post.media_urls.map((url) => {
      if (url.startsWith("http")) {
        const m = url.match(/\/explore-posts\/(.+)$/);
        return m ? m[1] : url;
      }
      return url;
    });
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [activeSlide, setActiveSlide] = useState(0);
  const [isPosted, setIsPosted] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [captureMode, setCaptureMode] = useState<"idle" | "camera" | "gallery">("idle");
  const [captureType, setCaptureType] = useState<"photo" | "video">("photo");
  const [isRecording, setIsRecording] = useState(false);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [facingMode, setFacingMode] = useState<"user" | "environment">("environment");
  const fileInputRef = useRef<HTMLInputElement>(null);
  const carouselRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const triggerFileSelect = () => fileInputRef.current?.click();

  const stopCamera = useCallback(() => {
    streamRef.current?.getTracks().forEach((t) => t.stop());
    streamRef.current = null;
  }, []);

  const startCamera = useCallback(
    async (mode?: "user" | "environment") => {
      const nextMode = mode ?? facingMode;
      if (mode) setFacingMode(mode);
      setCameraError(null);
      stopCamera();
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: nextMode, width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: captureType === "video",
        });
        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err: any) {
        setCameraError(err?.message || "Camera access denied");
        toast.error("Could not access camera");
      }
    },
    [captureType, stopCamera, facingMode]
  );

  useEffect(() => {
    if (captureMode === "camera") {
      startCamera();
    }
    return () => {
      if (captureMode !== "camera") stopCamera();
    };
  }, [captureMode, startCamera, stopCamera]);

  const capturePhoto = useCallback(() => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas || !streamRef.current || !video.videoWidth) return;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.drawImage(video, 0, 0);
    canvas.toBlob(
      async (blob) => {
        if (!blob) return;
        const file = new File([blob], `capture-${Date.now()}.jpg`, { type: "image/jpeg" });
        await uploadFile(file);
      },
      "image/jpeg",
      0.92
    );
  }, []);

  const startRecording = useCallback(() => {
    if (!streamRef.current || !videoRef.current) return;
    chunksRef.current = [];
    const mimeType =
      MediaRecorder.isTypeSupported("video/webm;codecs=vp9")
        ? "video/webm;codecs=vp9"
        : MediaRecorder.isTypeSupported("video/webm")
          ? "video/webm"
          : MediaRecorder.isTypeSupported("video/mp4")
            ? "video/mp4"
            : "";
    const recorder = new MediaRecorder(streamRef.current, mimeType
      ? { mimeType, videoBitsPerSecond: 2500000 }
      : { videoBitsPerSecond: 2500000 });
    recorder.ondataavailable = (e) => {
      if (e.data.size > 0) chunksRef.current.push(e.data);
    };
    const recMimeType = recorder.mimeType;
    recorder.onstop = async () => {
      const type = recMimeType || "video/webm";
      const ext = type.includes("mp4") ? "mp4" : "webm";
      const blob = new Blob(chunksRef.current, { type });
      const file = new File([blob], `record-${Date.now()}.${ext}`, { type });
      await uploadFile(file);
    };
    recorder.start();
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
  }, []);

  const stopRecording = useCallback(() => {
    mediaRecorderRef.current?.stop();
    mediaRecorderRef.current = null;
    setIsRecording(false);
  }, []);

  const uploadFile = async (file: File) => {
    if (!ALLOWED_TYPES.includes(file.type)) {
      toast.error("Invalid file type");
      return;
    }
    const isVideo = ALLOWED_VIDEO_TYPES.includes(file.type);
    const maxSize = isVideo ? MAX_VIDEO_SIZE : MAX_IMAGE_SIZE;
    if (file.size > maxSize) {
      toast.error(`File too large. Max ${isVideo ? "50MB" : "5MB"}.`);
      return;
    }
    setIsUploading(true);
    try {
      const fd = new FormData();
      fd.append("file", file);
      const res = await fetcher.post<{ data: { path: string } }>(
        "/api/explore/upload",
        fd as any
      );
      const path = (res as any)?.data?.path;
      if (path) {
        setMediaPaths((p) => [...p, path]);
        setCaptureMode("idle");
        stopCamera();
      }
    } catch {
      toast.error("Upload failed");
    } finally {
      setIsUploading(false);
    }
  };

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      setIsDragging(false);
      const files = e.dataTransfer?.files;
      if (!files?.length) return;
      const input = fileInputRef.current;
      if (input) {
        const dt = new DataTransfer();
        for (let i = 0; i < files.length; i++) dt.items.add(files[i]);
        input.files = dt.files;
        input.dispatchEvent(new Event("change", { bubbles: true }));
      }
    },
    []
  );

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    if (!e.currentTarget.contains(e.relatedTarget as Node)) setIsDragging(false);
  }, []);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files?.length) return;

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      if (!ALLOWED_TYPES.includes(file.type)) {
        toast.error(`${file.name}: Invalid type. Use JPEG, PNG, WebP, MP4, or WebM.`);
        continue;
      }
      const isVideo = ALLOWED_VIDEO_TYPES.includes(file.type);
      const maxSize = isVideo ? MAX_VIDEO_SIZE : MAX_IMAGE_SIZE;
      if (file.size > maxSize) {
        toast.error(`${file.name}: Max ${isVideo ? "50MB" : "5MB"}.`);
        continue;
      }
      await uploadFile(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const removeMedia = (index: number) => {
    setMediaPaths((p) => p.filter((_, i) => i !== index));
    setActiveSlide((prev) => Math.min(prev, Math.max(0, mediaPaths.length - 2)));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!mediaPaths.length) {
      toast.error("Add at least one photo or video.");
      return;
    }
    setIsSubmitting(true);
    try {
      if (post) {
        await fetcher.patch(`/api/explore/posts/${post.id}`, {
          caption: caption || null,
          media_urls: mediaPaths,
          tags,
          status: post.status,
        });
        toast.success("Post updated.");
      } else {
        await fetcher.post("/api/explore/posts", {
          caption: caption || null,
          media_urls: mediaPaths,
          tags,
          status: "published",
        });
        setIsPosted(true);
        toast.success("Posted!");
        await new Promise((r) => setTimeout(r, 800));
      }
      onSuccess();
    } catch (err) {
      const msg = err instanceof FetchError ? err.message : "Failed to save post.";
      toast.error(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const supabaseUrl =
    typeof window !== "undefined" ? (process.env.NEXT_PUBLIC_SUPABASE_URL || "") : "";
  const getMediaUrl = (path: string) =>
    `${supabaseUrl}/storage/v1/object/public/explore-posts/${path}`;

  const scrollToSlide = useCallback((index: number) => {
    const el = carouselRef.current;
    if (!el) return;
    const child = el.children[index] as HTMLElement;
    if (child) {
      child.scrollIntoView({ behavior: "smooth", block: "nearest", inline: "center" });
    }
    setActiveSlide(index);
  }, []);

  // Camera capture UI
  if (captureMode === "camera") {
    return (
      <div className="flex flex-col">
        <div className="relative aspect-[4/5] max-h-[420px] rounded-2xl overflow-hidden bg-black">
          <video
            ref={videoRef}
            autoPlay
            playsInline
            muted
            className="w-full h-full object-cover"
          />
          <canvas ref={canvasRef} className="hidden" />
          {cameraError && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/80 text-white p-4 text-center">
              {cameraError}
            </div>
          )}

          {/* Top bar: back, switch camera, photo/video toggle */}
          <div className="absolute top-0 left-0 right-0 flex items-center justify-between p-4 bg-gradient-to-b from-black/60 to-transparent">
            <button
              type="button"
              onClick={() => {
                setCaptureMode("idle");
                stopCamera();
              }}
              className="p-2 rounded-full bg-black/40 text-white hover:bg-black/60"
            >
              <X className="w-5 h-5" />
            </button>
            <div className="flex gap-1 rounded-full bg-black/40 p-1">
              <button
                type="button"
                onClick={() => setCaptureType("photo")}
                className={`px-4 py-2 rounded-full text-sm font-medium transition-colors ${
                  captureType === "photo" ? "bg-white text-black" : "text-white"
                }`}
              >
                Photo
              </button>
              <button
                type="button"
                onClick={() => !isRecording && setCaptureType("video")}
                className={`px-4 py-2 rounded-full text-sm font-medium transition-colors ${
                  captureType === "video" ? "bg-white text-black" : "text-white"
                }`}
              >
                Video
              </button>
            </div>
            <button
              type="button"
              onClick={() => {
                const next = facingMode === "user" ? "environment" : "user";
                startCamera(next);
              }}
              className="p-2 rounded-full bg-black/40 text-white hover:bg-black/60"
            >
              <FlipHorizontal className="w-5 h-5" />
            </button>
          </div>

          {/* Capture button */}
          <div className="absolute bottom-6 left-0 right-0 flex justify-center">
            <button
              type="button"
              disabled={isUploading || !!cameraError}
              onMouseDown={captureType === "photo" ? capturePhoto : undefined}
              onMouseUp={captureType === "video" ? undefined : undefined}
              onTouchStart={captureType === "photo" ? capturePhoto : undefined}
              onClick={
                captureType === "video"
                  ? isRecording
                    ? stopRecording
                    : startRecording
                  : undefined
              }
              className={`relative w-16 h-16 rounded-full border-4 flex items-center justify-center transition-all ${
                isRecording
                  ? "bg-red-500 border-red-600 animate-pulse"
                  : "bg-white/90 border-white hover:scale-105 active:scale-95"
              }`}
            >
              {captureType === "video" && isRecording && (
                <div className="absolute -top-8 left-1/2 -translate-x-1/2 flex items-center gap-1 text-red-500 text-xs font-medium">
                  <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
                  Recording
                </div>
              )}
            </button>
          </div>
        </div>
        {isUploading && (
          <div className="mt-3 flex items-center gap-2 text-[#FF0077] text-sm">
            <Loader2 className="w-4 h-4 animate-spin" />
            Uploading...
          </div>
        )}
      </div>
    );
  }

  // Main form UI
  return (
    <form onSubmit={handleSubmit} className="flex flex-col min-h-0">
      <div className="relative">
        {mediaPaths.length > 0 ? (
          <div className="relative rounded-2xl overflow-hidden bg-black">
            <div
              ref={carouselRef}
              className="flex overflow-x-auto snap-x snap-mandatory scroll-smooth scrollbar-hide gap-0"
              style={{ scrollbarWidth: "none", msOverflowStyle: "none" }}
              onScroll={(e) => {
                const el = e.currentTarget;
                const scrollLeft = el.scrollLeft;
                const width = el.offsetWidth;
                const index = Math.round(scrollLeft / width);
                setActiveSlide(Math.min(index, mediaPaths.length - 1));
              }}
            >
              {mediaPaths.map((path, i) => (
                <div
                  key={path}
                  className="flex-shrink-0 w-full snap-center snap-always aspect-square"
                >
                  <div className="relative w-full h-full">
                    {isVideoPath(path) ? (
                      <video
                        src={getMediaUrl(path)}
                        controls
                        playsInline
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <img
                        src={getMediaUrl(path)}
                        alt=""
                        className="w-full h-full object-cover"
                      />
                    )}
                    <button
                      type="button"
                      onClick={() => removeMedia(i)}
                      className="absolute top-2 right-2 p-2 bg-black/50 hover:bg-black/70 rounded-full text-white transition-colors backdrop-blur-sm"
                    >
                      <X className="w-4 h-4" />
                    </button>
                    {mediaPaths.length > 1 && (
                      <span className="absolute top-2 left-2 px-2 py-0.5 bg-black/50 rounded-full text-white text-xs backdrop-blur-sm">
                        {i + 1} / {mediaPaths.length}
                      </span>
                    )}
                  </div>
                </div>
              ))}
            </div>

            {mediaPaths.length > 1 && (
              <div className="absolute bottom-3 left-0 right-0 flex justify-center gap-1.5">
                {mediaPaths.map((_, i) => (
                  <button
                    key={i}
                    type="button"
                    onClick={() => scrollToSlide(i)}
                    className={`w-2 h-2 rounded-full transition-all ${
                      i === activeSlide ? "bg-white w-4" : "bg-white/50 hover:bg-white/70"
                    }`}
                  />
                ))}
              </div>
            )}

            {mediaPaths.length > 1 && (
              <>
                <button
                  type="button"
                  onClick={() => scrollToSlide(Math.max(0, activeSlide - 1))}
                  className="hidden sm:flex absolute left-2 top-1/2 -translate-y-1/2 w-10 h-10 items-center justify-center rounded-full bg-black/40 hover:bg-black/60 text-white transition-colors"
                >
                  <ChevronLeft className="w-5 h-5" />
                </button>
                <button
                  type="button"
                  onClick={() =>
                    scrollToSlide(Math.min(mediaPaths.length - 1, activeSlide + 1))
                  }
                  className="hidden sm:flex absolute right-2 top-1/2 -translate-y-1/2 w-10 h-10 items-center justify-center rounded-full bg-black/40 hover:bg-black/60 text-white transition-colors"
                >
                  <ChevronRight className="w-5 h-5" />
                </button>
              </>
            )}
          </div>
