              key={tag}
              className="inline-flex items-center gap-1 px-3 py-1.5 rounded-full bg-[#FF0077]/10 text-[#FF0077] text-sm font-medium"
            >
              #{tag}
              <button
                type="button"
                onClick={() => setTags((prev) => prev.filter((t) => t !== tag))}
                className="ml-0.5 hover:text-[#FF0077]/70"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            </span>
          ))}
        </div>
        <div className="flex gap-2">
          <input
            type="text"
            value={tagInput}
            onChange={(e) => setTagInput(e.target.value.toLowerCase().replace(/[^a-z0-9\s-]/g, ""))}
            onKeyDown={(e) => {
              if ((e.key === "Enter" || e.key === ",") && tagInput.trim()) {
                e.preventDefault();
                const newTag = tagInput.trim().replace(/\s+/g, "-");
                if (newTag && !tags.includes(newTag) && tags.length < 10) {
                  setTags((prev) => [...prev, newTag]);
                }
                setTagInput("");
              }
            }}
            placeholder="e.g. hair, braids, balayage..."
            className="flex-1 rounded-lg border border-gray-200 px-3 py-2 text-sm placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-[#FF0077]/30 focus:border-[#FF0077]"
            maxLength={30}
          />
          <button
            type="button"
            onClick={() => {
              const newTag = tagInput.trim().replace(/\s+/g, "-");
              if (newTag && !tags.includes(newTag) && tags.length < 10) {
                setTags((prev) => [...prev, newTag]);
              }
              setTagInput("");
            }}
            disabled={!tagInput.trim() || tags.length >= 10}
            className="px-4 py-2 rounded-lg bg-gray-100 text-sm font-medium text-gray-700 hover:bg-gray-200 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            Add
          </button>
        </div>
        {/* Quick-add suggestions */}
        <div className="flex flex-wrap gap-1.5 mt-2">
          {["hair", "nails", "makeup", "skincare", "lashes", "braids", "barber", "spa", "facial", "balayage", "extensions", "gel-nails"]
            .filter((s) => !tags.includes(s))
            .slice(0, 8)
            .map((suggestion) => (
              <button
                key={suggestion}
                type="button"
                onClick={() => {
                  if (tags.length < 10) setTags((prev) => [...prev, suggestion]);
                }}
                className="px-2.5 py-1 rounded-full border border-gray-200 text-xs text-gray-500 hover:border-[#FF0077] hover:text-[#FF0077] transition-colors"
              >
                +{suggestion}
              </button>
            ))}
        </div>
        {tags.length >= 10 && (
          <p className="text-xs text-gray-400 mt-1">Maximum 10 tags per post</p>
        )}
      </div>

      <div className="mt-6 flex gap-3">
        <Button
          type="submit"
          disabled={isSubmitting || !mediaPaths.length}
          className="flex-1 h-12 rounded-xl bg-[#FF0077] hover:bg-[#D60565] text-white font-semibold text-base"
        >
          {isSubmitting ? (
            <Loader2 className="w-5 h-5 animate-spin" />
          ) : isPosted ? (
            "Posted!"
          ) : post ? (
            "Save changes"
          ) : (
            "Share"
          )}
        </Button>
        {onCancel && (
          <Button
            type="button"
            variant="outline"
            onClick={onCancel}
            className="h-12 rounded-xl px-6"
          >
            Cancel
          </Button>
        )}
      </div>
    </form>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { useGPSTracking } from "@/hooks/useGPSTracking";
import { Button } from "@/components/ui/button";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { MapPin, Navigation, AlertCircle, Loader2 } from "lucide-react";
import { Badge } from "@/components/ui/badge";

interface ProviderLocationTrackerProps {
  bookingId: string;
  destination?: {
    latitude: number;
    longitude: number;
  };
  onLocationUpdate?: (location: { latitude: number; longitude: number }) => void;
  autoStart?: boolean;
}

export default function ProviderLocationTracker({
  bookingId,
  destination,
  onLocationUpdate,
  autoStart = false,
}: ProviderLocationTrackerProps) {
  const {
    location,
    isTracking,
    isGPSAvailable,
    isEstimated,
    error,
    startTracking,
    stopTracking,
    estimateLocation,
  } = useGPSTracking({
    bookingId,
    enabled: autoStart,
    updateInterval: 10000, // 10 seconds
    fallbackToEstimated: true,
    onLocationUpdate: (loc) => {
      if (onLocationUpdate) {
        onLocationUpdate({ latitude: loc.latitude, longitude: loc.longitude });
      }
    },
  });

  const [distance, setDistance] = useState<number | null>(null);
  const [eta, setEta] = useState<number | null>(null);

  // Calculate distance and ETA to destination
  useEffect(() => {
    if (location && destination && !isEstimated) {
      const R = 6371; // Earth's radius in km
      const dLat = ((destination.latitude - location.latitude) * Math.PI) / 180;
      const dLon = ((destination.longitude - location.longitude) * Math.PI) / 180;
      const a =
        Math.sin(dLat / 2) * Math.sin(dLat / 2) +
        Math.cos((location.latitude * Math.PI) / 180) *
          Math.cos((destination.latitude * Math.PI) / 180) *
          Math.sin(dLon / 2) *
          Math.sin(dLon / 2);
      const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
      const calculatedDistance = R * c;
      const estimatedMinutes = Math.ceil((calculatedDistance / 40) * 60);
      queueMicrotask(() => {
        setDistance(calculatedDistance);
        setEta(estimatedMinutes);
      });
    } else {
      queueMicrotask(() => {
        setDistance(null);
        setEta(null);
      });
    }
  }, [location, destination, isEstimated]);

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <MapPin className="w-5 h-5 text-[#FF0077]" />
          <h3 className="font-semibold">Location Tracking</h3>
        </div>
        <div className="flex items-center gap-2">
          {isTracking ? (
            <>
              <Badge variant={isEstimated ? "secondary" : "default"}>
                {isEstimated ? "Estimated" : "Live"}
              </Badge>
              <Button variant="outline" size="sm" onClick={stopTracking}>
                Stop
              </Button>
            </>
          ) : (
            <Button
              size="sm"
              onClick={startTracking}
              className="bg-[#FF0077] hover:bg-[#D60565]"
            >
              <Navigation className="w-4 h-4 mr-2" />
              Start Tracking
            </Button>
          )}
        </div>
      </div>

      {error && (
        <Alert variant="destructive">
          <AlertCircle className="w-4 h-4" />
          <AlertDescription>
            {error.message}
            {isGPSAvailable === false && (
              <Button
                variant="link"
                size="sm"
                className="ml-2"
                onClick={() => estimateLocation("gps_unavailable")}
              >
                Use Estimated Location
              </Button>
            )}
          </AlertDescription>
        </Alert>
      )}

      {isEstimated && (
        <Alert>
          <AlertCircle className="w-4 h-4" />
          <AlertDescription>
            GPS unavailable. Using estimated location based on last known position.
          </AlertDescription>
        </Alert>
      )}

      {location && (
        <div className="bg-gray-50 rounded-lg p-4 space-y-2">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <p className="text-xs text-gray-600">Latitude</p>
              <p className="font-mono text-sm">{location.latitude.toFixed(6)}</p>
            </div>
            <div>
              <p className="text-xs text-gray-600">Longitude</p>
              <p className="font-mono text-sm">{location.longitude.toFixed(6)}</p>
            </div>
            {location.accuracy && (
              <div>
                <p className="text-xs text-gray-600">Accuracy</p>
                <p className="text-sm">{Math.round(location.accuracy)}m</p>
              </div>
            )}
            {distance !== null && (
              <div>
                <p className="text-xs text-gray-600">Distance to Destination</p>
                <p className="text-sm font-semibold">
                  {distance < 1
                    ? `${Math.round(distance * 1000)}m`
                    : `${distance.toFixed(2)}km`}
                </p>
              </div>
            )}
            {eta !== null && (
              <div>
                <p className="text-xs text-gray-600">Estimated Arrival</p>
                <p className="text-sm font-semibold">{eta} minutes</p>
              </div>
            )}
          </div>
        </div>
      )}

      {isTracking && !location && (
        <div className="flex items-center justify-center py-4">
          <Loader2 className="w-5 h-5 animate-spin text-[#FF0077]" />
          <span className="ml-2 text-sm text-gray-600">Getting location...</span>
        </div>
      )}

      {!isTracking && !location && (
        <p className="text-sm text-gray-500 text-center py-4">
          Click "Start Tracking" to begin sharing your location
        </p>
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  Bell,
  X,
  Calendar,
  DollarSign,
  User,
  Clock,
  CheckCircle2,
  AlertTriangle,
  Package,
  Users,
  Settings,
  FileText,
  Zap,
} from "lucide-react";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { fetcher, FetchTimeoutError } from "@/lib/http/fetcher";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { getSupabaseClient } from "@/lib/supabase/client";
import { useAuth } from "@/providers/AuthProvider";

interface Notification {
  id: string;
  type: string;
  title: string;
  message: string;
  timestamp: string;
  link?: string;
  priority: 'low' | 'medium' | 'high';
  read: boolean;
  metadata?: Record<string, any>;
}

interface NotificationResponse {
  notifications: Notification[];
  total_unread: number;
}

const getNotificationIcon = (type: string) => {
  switch (type) {
    case 'appointment_reminder':
    case 'appointment_cancelled':
    case 'appointment_rescheduled':
    case 'new_appointment':
      return Calendar;
    case 'payment_received':
    case 'payout_processed':
    case 'refund_processed':
      return DollarSign;
    case 'new_client':
    case 'client_message':
      return User;
    case 'staff_clock_in':
    case 'staff_clock_out':
    case 'shift_reminder':
      return Clock;
    case 'service_booking':
    case 'product_order':
      return Package;
    case 'team_member_added':
    case 'team_member_updated':
      return Users;
    case 'system_update':
    case 'maintenance':
      return Settings;
    case 'report_ready':
    case 'document_ready':
      return FileText;
    case 'payment_failed':
    case 'subscription_expiring':
      return AlertTriangle;
    case 'account_verification':
      return CheckCircle2;
    case 'high_priority':
      return Zap;
    default:
      return Bell;
  }
};

const getPriorityColor = (priority: string) => {
  switch (priority) {
    case 'high':
      return 'text-red-600 bg-red-50 border-red-200';
    case 'medium':
      return 'text-yellow-600 bg-yellow-50 border-yellow-200';
    default:
      return 'text-blue-600 bg-blue-50 border-blue-200';
  }
};

const formatTimeAgo = (timestamp: string) => {
  const now = new Date();
  const time = new Date(timestamp);
  const diffInSeconds = Math.floor((now.getTime() - time.getTime()) / 1000);

  if (diffInSeconds < 60) return 'Just now';
  if (diffInSeconds < 3600) return `${Math.floor(diffInSeconds / 60)}m ago`;
  if (diffInSeconds < 86400) return `${Math.floor(diffInSeconds / 3600)}h ago`;
  if (diffInSeconds < 604800) return `${Math.floor(diffInSeconds / 86400)}d ago`;
  return time.toLocaleDateString();
};

export function ProviderNotificationsDropdown() {
  const [open, setOpen] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [totalUnread, setTotalUnread] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const router = useRouter();
  const { user } = useAuth();

  useEffect(() => {
    // Only fetch notifications when user is authenticated (avoids 401 from API)
    if (user?.id) {
      loadNotifications();
    } else {
      setIsLoading(false);
      setNotifications([]);
      setTotalUnread(0);
    }

    // Set up real-time subscription for notifications
    const supabase = getSupabaseClient();
    let subscription: any = null;

    if (user?.id) {
      // Subscribe to new notifications for this user
      subscription = supabase
        .channel(`notifications:${user.id}`)
        .on(
          'postgres_changes',
          {
            event: 'INSERT',
            schema: 'public',
            table: 'notifications',
            filter: `user_id=eq.${user.id}`,
          },
          (payload) => {
            // New notification received
            const newNotification = payload.new as any;
            setNotifications((prev) => {
              // Check if notification already exists (avoid duplicates)
              if (prev.find((n) => n.id === newNotification.id)) {
                return prev;
              }
              return [{
                id: newNotification.id,
                type: newNotification.type,
                title: newNotification.title,
                message: newNotification.message,
                timestamp: newNotification.created_at,
                link: newNotification.link || undefined,
                priority: (newNotification.priority || 'low') as 'low' | 'medium' | 'high',
                read: newNotification.is_read || false,
                metadata: newNotification.metadata,
              }, ...prev];
            });

            if (!newNotification.is_read) {
              setTotalUnread((prev) => prev + 1);
              // Show toast for high priority notifications
              if (newNotification.priority === 'high') {
                toast.info(newNotification.title, {
                  description: newNotification.message,
                });
              }
            }
          }
        )
        .on(
          'postgres_changes',
          {
            event: 'UPDATE',
            schema: 'public',
            table: 'notifications',
            filter: `user_id=eq.${user.id}`,
          },
          (payload) => {
            // Notification updated (e.g., marked as read)
            const updatedNotification = payload.new as any;
            setNotifications((prev) =>
              prev.map((n) =>
                n.id === updatedNotification.id
                  ? {
                      ...n,
                      read: updatedNotification.is_read || false,
                    }
                  : n
              )
            );

            if (updatedNotification.is_read) {
              setTotalUnread((prev) => Math.max(0, prev - 1));
            }
          }
        )
        .subscribe();
    }

    // Fallback: Refresh every 5 minutes when authenticated
    const interval = user?.id ? setInterval(loadNotifications, 300000) : undefined;

    return () => {
      if (subscription) {
        try {
          supabase.removeChannel(subscription);
        } catch {
          // Ignore when channel is still connecting (e.g. React Strict Mode unmount)
        }
      }
      if (interval) clearInterval(interval);
    };
  }, [user?.id]);

  const loadNotifications = async () => {
    try {
      setIsLoading(true);
      const response = await fetcher.get<{ data: NotificationResponse }>('/api/provider/notifications');
      // API returns { data: { notifications: [], total_unread: 0 } }
      const notificationData: NotificationResponse = response.data ?? { notifications: [], total_unread: 0 };
      setNotifications(notificationData.notifications || []);
      setTotalUnread(notificationData.total_unread || 0);
    } catch (error) {
      // Suppress AbortErrors from cancelled requests (component unmounts, navigation)
      if (error instanceof FetchTimeoutError && error.message.includes('cancelled')) {
        return; // Silently ignore cancelled requests
      }
      console.error('Failed to load notifications:', error);
      // Don't show error toast on initial load
      if (!isLoading) {
        toast.error('Failed to load notifications');
      }
      setNotifications([]);
      setTotalUnread(0);
    } finally {
      setIsLoading(false);
    }
  };

  const handleNotificationClick = async (notification: Notification) => {
    // Mark as read
    if (!notification.read) {
      try {
        await fetcher.post(`/api/provider/notifications/${notification.id}/read`);
        setNotifications((prev) =>
          prev.map((n) =>
            n.id === notification.id ? { ...n, read: true } : n
          )
        );
        setTotalUnread((prev) => Math.max(0, prev - 1));
      } catch (error) {
        console.error('Failed to mark notification as read:', error);
      }
    }

    // Navigate if link exists
    if (notification.link) {
      setOpen(false);
      router.push(notification.link);
    }
  };

  const handleMarkAllRead = async () => {
    try {
      await fetcher.post('/api/provider/notifications/mark-all-read');
      setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
      setTotalUnread(0);
      toast.success('All notifications marked as read');
    } catch (error) {
      console.error('Failed to mark all as read:', error);
      toast.error('Failed to mark all as read');
    }
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className="relative min-h-[44px] min-w-[44px] touch-manipulation"
        >
          <Bell className="w-5 h-5" />
          {totalUnread > 0 && (
            <Badge
              variant="destructive"
              className="absolute -top-1 -right-1 h-5 min-w-5 px-1.5 flex items-center justify-center text-xs"
            >
              {totalUnread > 99 ? '99+' : totalUnread}
            </Badge>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-[95vw] sm:w-96 p-0 max-h-[85vh] overflow-hidden flex flex-col">
        <div className="flex items-center justify-between p-3 sm:p-4 border-b sticky top-0 bg-white z-10">
          <h3 className="font-semibold text-base sm:text-lg">Notifications</h3>
          <div className="flex items-center gap-2">
            {totalUnread > 0 && (
              <>
                <Badge variant="secondary" className="text-xs">
                  {totalUnread} new
                </Badge>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={handleMarkAllRead}
                  className="text-xs h-7 px-2 min-h-[28px] touch-manipulation"
                >
                  Mark all read
                </Button>
              </>
            )}
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setOpen(false)}
              className="h-7 w-7 min-h-[28px] min-w-[28px] touch-manipulation"
            >
              <X className="w-4 h-4" />
            </Button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto">
          {isLoading ? (
            <div className="p-8 text-center text-gray-500">
              <Clock className="w-8 h-8 mx-auto mb-2 animate-spin" />
              <p className="text-sm">Loading notifications...</p>
            </div>
          ) : notifications.length === 0 ? (
            <div className="p-8 text-center text-gray-500">
              <CheckCircle2 className="w-8 h-8 mx-auto mb-2 text-gray-400" />
              <p className="text-sm">No new notifications</p>
              <Link
                href="/provider/settings/notifications"
                className="text-xs text-[#FF0077] hover:underline mt-2 inline-block"
                onClick={() => setOpen(false)}
              >
                Manage notifications
              </Link>
            </div>
          ) : (
            <div className="divide-y">
              {notifications.map((notification) => {
                const Icon = getNotificationIcon(notification.type);
                return (
                  <button
                    key={notification.id}
                    onClick={() => handleNotificationClick(notification)}
                    className={cn(
                      "w-full text-left p-3 sm:p-4 hover:bg-gray-50 transition-colors",
                      !notification.read && "bg-blue-50/50"
                    )}
                  >
                    <div className="flex items-start gap-3">
                      <div
                        className={cn(
                          "p-2 rounded-lg border flex-shrink-0",
                          getPriorityColor(notification.priority)
                        )}
                      >
                        <Icon className="w-4 h-4" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between gap-2 mb-1">
                          <p className={cn(
                            "font-medium text-sm text-gray-900",
                            !notification.read && "font-semibold"
                          )}>
                            {notification.title}
                          </p>
                          {!notification.read && (
                            <span className="w-2 h-2 bg-[#FF0077] rounded-full flex-shrink-0 mt-1.5" />
                          )}
                        </div>
                        <p className="text-sm text-gray-600 line-clamp-2 mb-1">
                          {notification.message}
                        </p>
                        <span className="text-xs text-gray-500">
                          {formatTimeAgo(notification.timestamp)}
                        </span>
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>
          )}
        </div>

        <div className="p-3 border-t bg-gray-50 sticky bottom-0">
          <Link
            href="/provider/notifications"
            className="text-sm text-[#FF0077] hover:underline text-center block"
            onClick={() => setOpen(false)}
          >
            View all notifications
          </Link>
        </div>
      </PopoverContent>
    </Popover>
  );
}

