"use client";

import React from "react";
import { useRouter } from "next/navigation";
import { Trophy, Sparkles, Star } from "lucide-react";
import { Button } from "@/components/ui/button";

interface RewardsCardProps {
  gamification: {
    total_points: number;
    current_badge: {
      id: string;
      name: string;
      color: string;
    } | null;
    badge_earned_at?: string | null;
    progress_to_next_badge: {
      badge: {
        id: string;
        name: string;
        color: string;
      };
      current_points: number;
      required_points: number;
      points_needed: number;
      progress_percentage: number;
    } | null;
  };
}

export function RewardsCard({ gamification }: RewardsCardProps) {
  const router = useRouter();
  
  // Determine what to show - current badge or next badge progress
  const currentBadge = gamification.current_badge;
  const nextBadgeProgress = gamification.progress_to_next_badge;
  
  // If no badge yet, show progress to first badge
  // If has badge, show progress to next badge
  const displayBadge = currentBadge || nextBadgeProgress?.badge;
  const showProgress = nextBadgeProgress;
  const showGetStarted = !displayBadge && !showProgress;

  return (
    <div className="mb-4 sm:mb-6">
      <div 
        className="relative overflow-hidden rounded-2xl shadow-lg bg-white border border-gray-200"
      >
        <div className="relative p-6 sm:p-8">
          {/* Header */}
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-full bg-gradient-to-br from-[#FF0077] to-[#D60565] flex items-center justify-center">
                <Trophy className="w-6 h-6 text-white" />
              </div>
              <div>
                <h3 className="text-xl sm:text-2xl font-bold text-gray-900">Rewards & Achievements</h3>
                {currentBadge ? (
                  <>
                    <p className="text-sm sm:text-base text-gray-600 mt-0.5">Current: {currentBadge.name}</p>
                    {gamification.badge_earned_at && (() => {
                      const earnedAt = new Date(gamification.badge_earned_at).getTime();
                      const daysSince = (Date.now() - earnedAt) / (24 * 60 * 60 * 1000);
                      if (daysSince <= 14) {
                        return (
                          <p className="text-xs sm:text-sm text-amber-600 mt-0.5 font-medium">
                            ≡ƒÄë Congratulations on earning this badge!
                          </p>
                        );
                      }
                      return null;
                    })()}
                  </>
                ) : showGetStarted ? (
                  <p className="text-sm sm:text-base text-gray-600 mt-0.5">Earn points and unlock badges</p>
                ) : null}
              </div>
            </div>
          </div>

          {/* Progress Section */}
          {showProgress && (
            <div className="space-y-4">
              <div>
                <div className="flex items-center justify-between mb-2">
                  <p className="text-sm sm:text-base font-medium text-gray-700">
                    Progress to Next Badge
                  </p>
                  <span className="text-xs sm:text-sm text-gray-600 font-semibold">
                    {showProgress.progress_percentage}%
                  </span>
                </div>
                <h4 className="text-lg sm:text-xl font-bold mb-4 text-gray-900">{showProgress.badge.name}</h4>
                
                {/* Points Display with Star */}
                <div className="mb-6">
                  <div className="flex items-baseline gap-2 mb-4">
                    <span className="text-2xl sm:text-3xl font-bold text-gray-900 flex items-center gap-2">
                      {showProgress.current_points.toLocaleString()}
                      <Star className="w-5 h-5 sm:w-6 sm:h-6 text-[#FF0077] fill-[#FF0077]" />
                    </span>
                    <span className="text-base sm:text-lg text-gray-600">
                      / {showProgress.required_points.toLocaleString()} points
                    </span>
                  </div>
                  
                  {/* Roadmap Progress */}
                  <div className="relative mt-4">
                    {/* Roadmap Track */}
                    <div className="relative h-2 bg-gray-200 rounded-full overflow-hidden">
                      {/* Progress Fill */}
                      <div 
                        className="absolute top-0 left-0 h-full bg-gradient-to-r from-[#FF0077] to-[#D60565] rounded-full transition-all duration-500 ease-out"
                        style={{ width: `${showProgress.progress_percentage}%` }}
                      />
                    </div>
                  </div>
                </div>

                {/* Points Needed */}
                {showProgress.points_needed > 0 ? (
                  <div className="space-y-2">
                    <p className="text-sm sm:text-base text-gray-700">
                      <span className="font-semibold text-[#FF0077]">{showProgress.points_needed.toLocaleString()}</span> more points needed
                    </p>
                    <p className="text-sm font-medium text-gray-800">
                      YouΓÇÖre {showProgress.points_needed.toLocaleString()} points away from {showProgress.badge.name}.
                    </p>
                    <p className="text-xs sm:text-sm text-gray-600 italic">
                      ≡ƒÆí Keep earning points by completing bookings and receiving great reviews!
                    </p>
                  </div>
                ) : (
                  <p className="text-sm sm:text-base text-[#FF0077] font-semibold">
                    ≡ƒÄë You've reached the requirements!
                  </p>
                )}
              </div>
            </div>
          )}

          {/* No Progress (First Badge) or Get Started when no data yet */}
          {(!showProgress && !currentBadge && displayBadge) || showGetStarted ? (
            <div className="space-y-4">
              <div>
                <h4 className="text-lg sm:text-xl font-bold mb-2 text-gray-900">
                  {showGetStarted ? "Start earning" : "Get Started"}
                </h4>
                <p className="text-sm sm:text-base text-gray-700 mb-4">
                  {showGetStarted ? (
                    <>Complete bookings and get great reviews to earn points and unlock badges. Higher tiers unlock perks like featured placement and more.</>
                  ) : (
                    <>Start earning points to unlock your first badge: <span className="font-semibold text-[#FF0077]">{displayBadge.name}</span></>
                  )}
                </p>
                <div className="flex items-baseline gap-2 mb-3">
                  <span className="text-2xl sm:text-3xl font-bold text-gray-900 flex items-center gap-2">
                    {(gamification.total_points ?? 0).toLocaleString()}
                    <Star className="w-5 h-5 sm:w-6 sm:h-6 text-[#FF0077] fill-[#FF0077]" />
                  </span>
                  <span className="text-base sm:text-lg text-gray-600">points earned</span>
                </div>
                <p className="text-xs sm:text-sm text-gray-600 italic">
                  ≡ƒÆí Complete bookings and receive great reviews to earn more points!
                </p>
              </div>
            </div>
          ) : null}

          {/* Details Button */}
          <div className="mt-6 pt-6 border-t border-gray-200">
            <Button
              onClick={() => router.push("/provider/gamification")}
              variant="outline"
              className="w-full sm:w-auto border-[#FF0077] text-[#FF0077] hover:bg-[#FF0077] hover:text-white transition-colors"
            >
              <Sparkles className="w-4 h-4 mr-2" />
              Details
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React from "react";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { MessageCircle, Phone, Copy, X } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import type { FrontDeskBooking } from "@/lib/front-desk/types";
import { WorkflowStepper } from "./WorkflowStepper";
import { PaymentActions } from "./PaymentActions";
import {
  checkInBooking,
  arriveAtHome,
  startService,
  markReadyToPay,
  completeBooking,
  cancelBooking,
} from "@/lib/front-desk/actions";

const BADGE_PILLS: Record<string, string> = {
  late: "bg-red-50/90 text-red-900/90",
  arriving: "bg-blue-50/90 text-blue-900/80",
  checked_in: "bg-emerald-50/90 text-emerald-900/85",
  in_service: "bg-slate-100/90 text-slate-800",
  ready_to_pay: "bg-amber-50/90 text-amber-900/90",
  completed: "bg-emerald-50/90 text-emerald-800",
  cancelled: "bg-red-50/90 text-red-800",
  confirmed: "bg-slate-100/80 text-slate-700",
};

export interface CompleteRequestRatingPayload {
  bookingId: string;
  customerName: string;
  locationId?: string | null;
  locationName?: string | null;
}

interface ActionPanelProps {
  booking: FrontDeskBooking;
  onClose: () => void;
  onActionComplete: () => void;
  /** Call when booking is completed so parent can show required customer rating dialog */
  onCompleteRequestRating?: (payload: CompleteRequestRatingPayload) => void;
}

export function ActionPanel({ booking, onClose, onActionComplete, onCompleteRequestRating }: ActionPanelProps) {
  const customer = (booking as any).customers || {};
  const phone = customer.phone || customer.phone_number || "";
  const badge = booking.operationalBadge || "confirmed";
  const locationType = (booking as any).location_type as string | undefined;
  const isAtHome = locationType === "at_home";

  const handleCopyPhone = () => {
    if (phone) {
      navigator.clipboard.writeText(phone);
      toast.success("Phone copied");
    }
  };

  const handleMessage = () => {
    window.location.assign("/provider/messaging");
  };

  const runAction = async (fn: () => Promise<boolean>, opts?: { afterComplete?: () => void }) => {
    const ok = await fn();
    if (ok) {
      onActionComplete();
      opts?.afterComplete?.();
    }
  };

  const isReadyToPay = badge === "ready_to_pay";

  const getNextStep = (): { label: string; onClick: () => void } | null => {
    if (["completed", "cancelled"].includes(badge)) return null;
    if (badge === "ready_to_pay") return null;

    if (badge === "confirmed") {
      if (isAtHome) {
        return { label: "I've Arrived", onClick: () => runAction(() => arriveAtHome(booking.id)) };
      }
      return { label: "Check in", onClick: () => runAction(() => checkInBooking(booking.id, (booking as any).version)) };
    }
    if (["checked_in", "arriving", "late"].includes(badge)) {
      return { label: "Start service", onClick: () => runAction(() => startService(booking.id)) };
    }
    if (badge === "in_service") {
      return { label: "Ready to pay", onClick: () => runAction(() => markReadyToPay(booking.id)) };
    }
    return null;
  };

  const nextStep = getNextStep();

  return (
    <div className="flex flex-col h-full bg-[#FDFDFD]">
      {/* Header - Guest Folio */}
      <div className="p-8 pb-6 border-b border-[#0F172A]/[0.06] flex items-center justify-between shrink-0">
        <h3 className="font-semibold text-xl text-[#0F172A] truncate">
          {booking.customer_name || "Guest"}
        </h3>
        <Button
          variant="ghost"
          size="icon"
          onClick={onClose}
          className="shrink-0 rounded-2xl text-[#0F172A]/60 hover:bg-[#0F172A]/[0.06] hover:text-[#0F172A]"
        >
          <X className="h-5 w-5" />
        </Button>
      </div>

      <ScrollArea className="flex-1">
        <div className="p-8 space-y-8">
          {/* Status + Meta */}
          <div className="flex flex-wrap gap-3 items-center">
            {phone && (
              <span className="flex items-center gap-1.5 text-sm text-[#0F172A]/70">
                <Phone className="h-4 w-4" />
                {phone}
              </span>
            )}
            <span className="text-sm text-[#0F172A]/60">#{booking.booking_number}</span>
            <span
              className={cn(
                "px-2.5 py-1 rounded-full font-black text-[9px] uppercase tracking-widest",
                BADGE_PILLS[badge] || BADGE_PILLS.confirmed
              )}
            >
              {badge.replace("_", " ")}
            </span>
          </div>

          <WorkflowStepper currentBadge={badge} />

          {/* Guest Folio - Receipt-style transaction summary */}
          <div className="rounded-[2.5rem] border border-[#0F172A]/[0.08] bg-white/80 p-6 space-y-4 shadow-sm">
            <p className="text-[9px] font-black tracking-widest uppercase text-[#0F172A]/50">
              Guest Folio
            </p>
            <div className="space-y-3">
              {(booking.services || []).map((s: any, i: number) => (
                <div key={i} className="flex justify-between text-sm">
                  <span className="text-[#0F172A]/80">
                    {s.offering_name || s.service_name || "Service"}
                    {s.staff_name && ` ┬╖ ${s.staff_name}`}
                    {s.duration_minutes && ` ┬╖ ${s.duration_minutes} min`}
                  </span>
                </div>
              ))}
            </div>
            <p className="text-sm text-[#0F172A]/60">
              {new Date(booking.scheduled_at).toLocaleString("en-US", {
                weekday: "short",
                month: "short",
                day: "numeric",
                hour: "2-digit",
                minute: "2-digit",
              })}
            </p>
            {booking.location_name && (
              <p className="text-sm text-[#0F172A]/55">{booking.location_name}</p>
            )}
            <div className="pt-4 border-t border-[#0F172A]/[0.08]">
              <div className="flex justify-between items-baseline">
                <span className="text-sm text-[#0F172A]/60">Total</span>
                <span className="text-lg font-semibold text-[#0F172A]">
                  {booking.currency} {Number(booking.total_amount || 0).toFixed(2)}
                </span>
              </div>
            </div>
          </div>

          {/* Quick actions */}
          <div>
            <p className="text-[9px] font-black uppercase tracking-widest text-[#0F172A]/50 mb-3">
              Quick actions
            </p>
            <div className="flex flex-wrap gap-2">
              <Button
                variant="outline"
                size="sm"
                className="gap-2 rounded-2xl border-[#0F172A]/12 hover:bg-[#0F172A]/[0.04]"
                onClick={handleMessage}
              >
                <MessageCircle className="h-4 w-4" />
                Message
              </Button>
              {phone && (
                <Button
                  variant="outline"
                  size="sm"
                  className="gap-2 rounded-2xl border-[#0F172A]/12 hover:bg-[#0F172A]/[0.04]"
                  onClick={handleCopyPhone}
                >
                  <Copy className="h-4 w-4" />
                  Copy phone
                </Button>
              )}
            </div>
          </div>

          {/* Payment Footer or Next Step */}
          <div>
            <p className="text-[9px] font-black uppercase tracking-widest text-[#0F172A]/50 mb-4">
              {isReadyToPay ? "Payment" : "Workflow"}
            </p>

            {isReadyToPay ? (
              <div className="space-y-4">
                <PaymentActions
                  bookingId={booking.id}
                  totalAmount={Number(booking.total_amount || 0)}
                  totalPaid={Number((booking as any).total_paid || 0)}
                  currency={booking.currency || "ZAR"}
                  onComplete={onActionComplete}
                  variant="footer"
                />
                <Button
                  variant="outline"
                  size="sm"
                  className="w-full rounded-2xl border-[#0F172A]/12 hover:bg-[#0F172A]/[0.04] text-[#0F172A]"
                  onClick={() =>
                    runAction(() => completeBooking(booking.id, (booking as any).version), {
                      afterComplete: () =>
                        onCompleteRequestRating?.({
                          bookingId: booking.id,
                          customerName: booking.customer_name || "Customer",
                          locationId: (booking as any).location_id ?? null,
                          locationName: (booking as any).location_name ?? null,
                        }),
                    })
                  }
                >
                  Mark completed (cash / offline)
                </Button>
              </div>
            ) : nextStep ? (
              <Button
                size="lg"
                className="w-full h-14 rounded-[2.5rem] bg-[#0F172A] hover:bg-[#0F172A]/90 text-white font-semibold text-base shadow-lg transition-all duration-300"
                onClick={nextStep.onClick}
              >
                {nextStep.label}
              </Button>
            ) : null}
          </div>

          {/* Cancel */}
          {!["completed", "cancelled"].includes(badge) && (
            <Button
              variant="outline"
              size="sm"
              className="w-full rounded-2xl border-red-200 text-red-800 hover:bg-red-50 font-medium"
              onClick={() => runAction(() => cancelBooking(booking.id, undefined, (booking as any).version))}
            >
              Cancel booking
            </Button>
          )}
        </div>
      </ScrollArea>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { cn } from "@/lib/utils";
import type { FrontDeskBooking } from "@/lib/front-desk/types";
import {
  Loader2,
  MessageCircle,
  MoreVertical,
  Clock,
} from "lucide-react";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  checkInBooking,
  arriveAtHome,
  startService,
  markReadyToPay,
} from "@/lib/front-desk/actions";

/** Desaturated status pills - matches reference (lavender for in_service, etc.) */
const BADGE_STYLES: Record<string, string> = {
  late: "bg-rose-50 text-rose-700",
  arriving: "bg-sky-50 text-sky-700",
  checked_in: "bg-emerald-50 text-emerald-700",
  in_service: "bg-indigo-100 text-indigo-700",
  ready_to_pay: "bg-amber-50 text-amber-700",
  completed: "bg-emerald-50 text-emerald-600",
  cancelled: "bg-slate-100 text-slate-500",
  confirmed: "bg-slate-100 text-slate-600",
};

function getInitials(name: string) {
  return name
    .split(" ")
    .map((n) => n[0])
    .slice(0, 2)
    .join("")
    .toUpperCase() || "?";
}

function formatTime(date: Date | string): string {
  return new Date(date).toLocaleTimeString("en-US", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: true,
  });
}

interface BookingTileProps {
  booking: FrontDeskBooking;
  isSelected: boolean;
  onClick: () => void;
  onActionComplete?: () => void;
  isLoading?: boolean;
}

export function BookingTile({
  booking,
  isSelected,
  onClick,
  onActionComplete,
  isLoading,
}: BookingTileProps) {
  const name = booking.customer_name || "Customer";
  const badge = booking.operationalBadge || "confirmed";
  const locationType = (booking as any).location_type as string | undefined;
  const isAtHome = locationType === "at_home";

  // Combine services and products for display
  const serviceNames = (booking.services || [])
    .map((s: any) => s.offering_name || s.service_name || s.name || "Service")
    .filter(Boolean);
  const productNames = (booking.products || [])
    .map((p: any) => `${p.product_name || "Product"}${(p.quantity || 1) > 1 ? ` ├ù${p.quantity}` : ""}`)
    .filter(Boolean);
  const hasProducts = productNames.length > 0;
  const servicesAndProducts = [...serviceNames, ...productNames].slice(0, 3);
  const servicesProductsLabel = servicesAndProducts.length > 0 ? servicesAndProducts.join(" + ") : "ΓÇö";

  const paid =
    (booking as any).payment_status === "paid" ||
    ((booking as any).total_paid || 0) >= (booking.total_amount || 0);

  const runQuickAction = async (fn: () => Promise<boolean>) => {
    const ok = await fn();
    if (ok) onActionComplete?.();
  };

  const getQuickActions = (): Array<{ label: string; onClick: () => void }> => {
    const actions: Array<{ label: string; onClick: () => void }> = [];
    if (["completed", "cancelled"].includes(badge)) return actions;
    if (badge === "confirmed") {
      if (isAtHome) {
        actions.push({ label: "I've Arrived", onClick: () => runQuickAction(() => arriveAtHome(booking.id)) });
      } else {
        actions.push({
          label: "Check in",
          onClick: () => runQuickAction(() => checkInBooking(booking.id, (booking as any).version)),
        });
      }
    }
    if (["checked_in", "arriving", "late"].includes(badge)) {
      actions.push({ label: "Start service", onClick: () => runQuickAction(() => startService(booking.id)) });
    }
    if (badge === "in_service") {
      actions.push({ label: "Ready to pay", onClick: () => runQuickAction(() => markReadyToPay(booking.id)) });
    }
    return actions;
  };

  const quickActions = getQuickActions();
  const [isMessaging, setIsMessaging] = useState(false);

  const handleMessage = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const customerId = (booking as any).customer_id;
    if (!customerId) {
      toast.error("Customer not found for this booking.");
      return;
    }
    setIsMessaging(true);
    try {
      const data = await fetcher.post<{ data?: { id: string } }>("/api/provider/conversations/create", {
        customer_id: customerId,
        booking_id: booking.id,
      });
      const convId = data?.data?.id;
      if (convId) {
        window.location.assign(`/provider/messaging?conversationId=${convId}`);
      } else {
        toast.error("Could not open conversation.");
        setIsMessaging(false);
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : "Failed to open conversation.";
      toast.error(msg);
      setIsMessaging(false);
    }
  };

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={isLoading ? () => {} : onClick}
      onKeyDown={(e) => !isLoading && e.key === "Enter" && onClick()}
      className={cn(
        "group relative transition-all duration-300 rounded-[1.5rem] min-h-[192px] p-5 flex flex-col",
        "bg-white border",
        "shadow-sm hover:shadow-md",
        "active:scale-[0.99]",
        isSelected
          ? "border-black ring-1 ring-black shadow-xl bg-white"
          : "border-transparent",
        isLoading ? "cursor-wait opacity-80" : "cursor-pointer"
      )}
    >
      {/* Row 1: Identity (Left) + Status Pill (Right) */}
      <div className="flex items-start justify-between gap-3">
        <div className="flex items-center gap-3 min-w-0 flex-1">
          <div className="flex shrink-0 w-11 h-11 rounded-lg bg-slate-100 flex items-center justify-center font-semibold text-slate-600 text-sm tabular-nums">
            {getInitials(name)}
          </div>
          <div className="min-w-0">
            <h3 className="text-[15px] font-semibold text-slate-900 truncate">{name}</h3>
            <p className="flex items-center gap-1.5 text-[13px] text-slate-400 mt-0.5">
              <Clock className="h-3.5 w-3.5 shrink-0" />
              {formatTime(booking.scheduled_at)}
            </p>
          </div>
        </div>
        <span
          className={cn(
            "shrink-0 px-2.5 py-1 rounded-full text-[10px] font-semibold uppercase tracking-wider",
            BADGE_STYLES[badge] || BADGE_STYLES.confirmed
          )}
        >
          {badge.replace(/_/g, " ")}
        </span>
      </div>

      {/* Thin Line */}
      <div className="my-4 border-t border-slate-100" />

      {/* SERVICE Label + Service Name */}
      <div className="flex-1 min-h-0">
        <p className="text-[10px] font-medium uppercase tracking-wider text-slate-400">
          {hasProducts && serviceNames.length > 0 ? "SERVICE & PRODUCTS" : hasProducts ? "PRODUCTS" : "SERVICE"}
        </p>
        <p className="mt-1 text-base font-semibold text-slate-900 truncate">
          {servicesProductsLabel}
        </p>
      </div>

      {/* Thin Line */}
      <div className="my-4 border-t border-slate-100" />

      {/* Bottom: Price (Left) + Quick Action Icons (Right) */}
      <div className="flex items-center justify-between">
        <span className="text-lg font-bold text-slate-900 tabular-nums">
          {booking.currency} {Number(booking.total_amount || 0).toFixed(2)}
          {paid && (
            <span className="ml-1.5 inline-block w-2 h-2 rounded-full bg-emerald-500 align-middle" />
          )}
        </span>
        <div className="flex items-center gap-1" onClick={(e) => e.stopPropagation()}>
          <button
            type="button"
            onClick={handleMessage}
            disabled={isMessaging}
            className="p-2 rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-600 transition-colors disabled:opacity-70 disabled:cursor-wait"
            aria-label="Message"
          >
            {isMessaging ? <Loader2 className="h-4 w-4 animate-spin" /> : <MessageCircle className="h-4 w-4" />}
          </button>
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
                <button
                  type="button"
                  className="p-2 rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-600 transition-colors"
                  aria-label="More options"
                >
                  <MoreVertical className="h-4 w-4" />
                </button>
              </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-48 rounded-xl">
                {quickActions.map((action) => (
                    <DropdownMenuItem
                      key={action.label}
                      onClick={(e) => {
                        e.preventDefault();
                        action.onClick();
                      }}
                      className="cursor-pointer rounded-lg"
                    >
                      {action.label}
                    </DropdownMenuItem>
                ))}
                <DropdownMenuItem
                  onClick={(e) => {
                    e.preventDefault();
                    onClick();
                  }}
                  className="cursor-pointer rounded-lg"
                >
                  View details
                </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {isLoading && (
        <div className="absolute inset-0 rounded-[1.5rem] bg-white/80 flex items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-slate-400" />
        </div>
      )}
    </div>
  );
}

"use client";

/**
 * FOUND MAP (Discovery)
 * --------------------
 * Bookings: GET /api/provider/bookings?start_date=&end_date=&location_id=
 *   - Used by: src/app/provider/bookings/page.tsx
 *   - Fetcher: fetcher.get from lib/http/fetcher
 * Status updates: PATCH /api/provider/bookings/[id] (status, current_stage)
 *   - Check-in: current_stage: "client_arrived" (at-salon)
 *   - src/app/api/provider/bookings/[id]/route.ts
 * Workflow: POST /api/provider/bookings/[id]/arrive (at-home only)
 *   POST /api/provider/bookings/[id]/start-service
 *   POST /api/provider/bookings/[id]/complete-service
 *   POST /api/provider/bookings/[id]/mark-paid (requires process_payments)
 * Paystack: POST /api/provider/bookings/[id]/send-payment-link
 *   - delivery_method: email | sms | both
 * Yoco: POST /api/provider/bookings/[id]/mark-paid (payment_method: "card")
 * Permissions: requirePermission('edit_appointments'), requirePermission('process_payments')
 *   - src/lib/auth/requirePermission.ts, permissions.ts
 * Locations: fetcher.get /api/provider/locations, LocationSwitcher
 * Staff: providerApi.listTeamMembers(locationId)
 * Messaging: /provider/messaging, /api/provider/conversations
 * Waitlist: /provider/waitlist, POST /api/provider/waiting-room
 * Create booking: POST /api/provider/bookings, openCreateMode from appointment-sidebar-store
 */

import React, { useState, useMemo } from "react";
import { toast } from "sonner";
import { useProviderPortal } from "@/providers/provider-portal/ProviderPortalProvider";
import { useFrontDeskData } from "@/lib/front-desk/useFrontDeskData";
import { matchesQueueTab, getQueueCounts } from "@/lib/front-desk/operationalState";
import type { FrontDeskBooking } from "@/lib/front-desk/types";
import { openViewMode } from "@/stores/appointment-sidebar-store";
import { providerApi } from "@/lib/provider-portal/api";
import { CommandBar } from "./CommandBar";
import { CommandCenter } from "./CommandCenter";
import { BookingTile } from "./BookingTile";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Skeleton } from "@/components/ui/skeleton";
import EmptyState from "@/components/ui/empty-state";
import RoleGuard from "@/components/auth/RoleGuard";
import { PageHeader } from "@/components/provider/PageHeader";
import { format } from "date-fns";
import { AppointmentSidebar } from "@/components/appointments";
import { useAppointmentSidebar } from "@/stores/appointment-sidebar-store";

export function FrontDesk() {
  const { selectedLocationId, salons, setSelectedLocation } = useProviderPortal();
  const { selectedAppointmentId } = useAppointmentSidebar();
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [searchQuery, setSearchQuery] = useState("");
  const [activeTab, setActiveTab] = useState<string>("all");
  const [loadingAppointment, setLoadingAppointment] = useState<string | null>(null);

  const { bookings, staff, locations, services, loading, error, refetch } = useFrontDeskData({
    date: selectedDate,
    locationId: selectedLocationId,
    query: searchQuery,
  });

  const locationsList = useMemo(() => {
    if (salons?.length) return salons.map((s) => ({ id: s.id, name: s.name }));
    return locations;
  }, [salons, locations]);

  const filteredBookings = useMemo(() => {
    if (activeTab === "all") return bookings;
    return bookings.filter((b) => matchesQueueTab(b, activeTab));
  }, [bookings, activeTab]);

  const queueCounts = useMemo(() => getQueueCounts(bookings), [bookings]);

  const handleCardClick = async (b: FrontDeskBooking) => {
    setLoadingAppointment(b.id);
    try {
      const appointment = await providerApi.getAppointment(b.id);
      openViewMode(appointment);
    } catch {
      toast.error("Failed to load appointment");
    } finally {
      setLoadingAppointment(null);
    }
  };

  const handleActionComplete = () => {
    refetch();
  };

  if (loading && bookings.length === 0) {
    return (
      <RoleGuard allowedRoles={["provider_owner", "provider_staff"]}>
        <div className="container mx-auto p-8 bg-[#FDFDFD] min-h-[60vh]">
          <PageHeader
            title="Front Desk"
            subtitle="Manage today's appointments"
            breadcrumbs={[
              { label: "Home", href: "/" },
              { label: "Provider", href: "/provider" },
              { label: "Front Desk" },
            ]}
          />
          <div className="space-y-4">
            <Skeleton className="h-12 w-full" />
            <Skeleton className="h-10 w-48" />
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
              {[1, 2, 3, 4, 5, 6].map((i) => (
                <Skeleton key={i} className="h-32 rounded-lg" />
              ))}
            </div>
          </div>
        </div>
      </RoleGuard>
    );
  }

  return (
    <RoleGuard allowedRoles={["provider_owner", "provider_staff"]}>
      <div className="flex flex-col min-h-0 w-full max-w-full overflow-hidden bg-[#FDFDFD] rounded-2xl transition-all duration-500">
        <PageHeader
          title="Front Desk"
          subtitle={`${format(selectedDate, "EEEE, MMM d")} ΓÇó ${bookings.length} appointments`}
          breadcrumbs={[
            { label: "Home", href: "/" },
            { label: "Provider", href: "/provider" },
            { label: "Front Desk" },
          ]}
        />

        <div className="space-y-6 mb-6 p-8 pt-0">
          <CommandBar
            date={selectedDate}
            onDateChange={setSelectedDate}
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            locationId={selectedLocationId}
            locations={locationsList}
            onLocationChange={(id) => setSelectedLocation(id)}
            onRefetch={refetch}
          />

          <CommandCenter
            counts={queueCounts}
            activeFilter={activeTab}
            onFilterChange={setActiveTab}
          />
        </div>

        {error && (
          <EmptyState
            title="Failed to load"
            description={error}
            action={{ label: "Retry", onClick: refetch }}
          />
        )}

        {!error && (
          <div className="flex flex-1 min-h-0 p-8 pt-0">
            <div className="flex-1 min-w-[320px] min-h-0 flex flex-col">
              <ScrollArea className="flex-1 pr-3">
                <div className="grid gap-5 pb-8 grid-cols-1 md:grid-cols-2 transition-all duration-500">
                  {filteredBookings.map((b) => (
                    <BookingTile
                      key={b.id}
                      booking={b}
                      isSelected={selectedAppointmentId === b.id}
                      onClick={() => handleCardClick(b)}
                      onActionComplete={handleActionComplete}
                      isLoading={loadingAppointment === b.id}
                    />
                  ))}
                </div>
                {filteredBookings.length === 0 && (
                  <div className="py-16">
                    <EmptyState
                      title="No appointments"
                      description="No appointments match your filters"
                    />
                  </div>
                )}
              </ScrollArea>
            </div>
          </div>
        )}

        <AppointmentSidebar
          teamMembers={staff as any}
          services={services as any}
          locations={locationsList as any}
          onAppointmentCreated={handleActionComplete}
          onAppointmentUpdated={handleActionComplete}
          onAppointmentDeleted={handleActionComplete}
          onRefresh={refetch}
        />
      </div>
    </RoleGuard>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import RateCustomerModal from "./rate-customer-modal";
import { fetcher } from "@/lib/http/fetcher";
import { Star } from "lucide-react";
import type { Review } from "@/types/beautonomi";

interface CustomerRatingButtonProps {
  bookingId: string;
  customerId: string;
  customerName: string;
  bookingStatus: string;
  onRatingSubmitted?: () => void;
}

/**
 * Button component for providers to rate customers
 * Shows different states: not rated, already rated, or rating button
 */
export default function CustomerRatingButton({
  bookingId,
  customerId: _customerId,
  customerName,
  bookingStatus,
  onRatingSubmitted,
}: CustomerRatingButtonProps) {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [existingRating, setExistingRating] = useState<Review | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Only load rating if booking is completed
    if (bookingStatus === "completed") {
      loadExistingRating();
    } else {
      setIsLoading(false);
    }
  }, [bookingId, bookingStatus]);

  const loadExistingRating = async () => {
    try {
      const response = await fetcher.get<{ data: Review }>(
        `/api/me/reviews?booking_id=${bookingId}`
      );
      if (response.data && response.data.customer_rating) {
        setExistingRating(response.data);
      }
    } catch {
      // Review might not exist yet, that's okay
      console.log("No existing rating found");
    } finally {
      setIsLoading(false);
    }
  };

  const handleRatingSuccess = () => {
    loadExistingRating();
    onRatingSubmitted?.();
  };

  // Don't show button if booking is not completed
  if (bookingStatus !== "completed") {
    return null;
  }

  if (isLoading) {
    return (
      <Button variant="outline" disabled>
        Loading...
      </Button>
    );
  }

  // If already rated, show the rating
  if (existingRating?.customer_rating) {
    return (
      <div className="flex items-center gap-2 px-3 py-2 border rounded-md bg-gray-50">
        <div className="flex items-center gap-1">
          <Star className="h-4 w-4 text-yellow-400 fill-yellow-400" />
          <span className="text-sm font-medium">
            {existingRating.customer_rating}/5
          </span>
        </div>
        <span className="text-xs text-gray-500">Rated</span>
        <Button
          variant="ghost"
          size="sm"
          onClick={() => setIsModalOpen(true)}
          className="ml-auto text-xs"
        >
          Edit
        </Button>
      </div>
    );
  }

  // Show rate button
  return (
    <>
      <Button
        variant="outline"
        onClick={() => setIsModalOpen(true)}
        className="flex items-center gap-2"
      >
        <Star className="h-4 w-4" />
        Rate Customer
      </Button>
      <RateCustomerModal
        open={isModalOpen}
        onOpenChange={setIsModalOpen}
        bookingId={bookingId}
        customerName={customerName}
        onSuccess={handleRatingSuccess}
      />
    </>
  );
}

"use client";

import React, { useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Star } from "lucide-react";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { fetcher } from "@/lib/http/fetcher";
import { toast } from "sonner";

interface RateCustomerModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  bookingId: string;
  customerName: string;
  onSuccess?: () => void;
}

export default function RateCustomerModal({
  open,
  onOpenChange,
  bookingId,
  customerName,
  onSuccess,
}: RateCustomerModalProps) {
  const [rating, setRating] = useState<number>(0);
  const [hoveredRating, setHoveredRating] = useState<number>(0);
  const [comment, setComment] = useState<string>("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (rating === 0) {
      toast.error("Please select a rating");
      return;
    }

    try {
      setIsSubmitting(true);
      // First, check if a review exists for this booking
      const reviewResponse = await fetcher.get<{ data: any }>(
        `/api/me/reviews?booking_id=${bookingId}`
      );

      const reviewId = reviewResponse.data?.id;

      if (!reviewId) {
        // If no review exists, we need to create one first (this should be done by customer)
        // For now, we'll try to update the review with customer rating
        toast.error("Review not found. Customer must review first.");
        return;
      }

      // Update the review with customer rating
      const response = await fetcher.patch<{ data?: any; error?: { message?: string } }>(`/api/reviews/${reviewId}`, {
        customer_rating: rating,
        customer_comment: comment || null,
      });

      if (response.error) {
        throw new Error(response.error.message || "Failed to submit rating");
      }

      toast.success("Rating submitted successfully!");
      onSuccess?.();
      onOpenChange(false);
      // Reset form
      setRating(0);
      setComment("");
    } catch (error: any) {
      console.error("Error submitting rating:", error);
      toast.error(
        error.message || "Failed to submit rating. Please try again."
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClose = () => {
    if (!isSubmitting) {
      onOpenChange(false);
      setRating(0);
      setComment("");
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle className="text-2xl font-semibold">
            Rate {customerName}
          </DialogTitle>
          <DialogDescription>
            Share your experience with this customer to help other providers.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6 py-4">
          {/* Star Rating */}
          <div>
            <Label className="text-base font-medium mb-3 block">
              How would you rate this customer? *
            </Label>
            <div className="flex items-center gap-2">
              {[1, 2, 3, 4, 5].map((star) => (
                <button
                  key={star}
                  type="button"
                  onClick={() => setRating(star)}
                  onMouseEnter={() => setHoveredRating(star)}
                  onMouseLeave={() => setHoveredRating(0)}
                  disabled={isSubmitting}
                  className="focus:outline-none transition-transform hover:scale-110 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <Star
                    className={`h-10 w-10 ${
                      star <= (hoveredRating || rating)
                        ? "text-yellow-400 fill-yellow-400"
                        : "text-gray-300"
                    } transition-colors`}
                  />
                </button>
              ))}
              {rating > 0 && (
                <span className="ml-2 text-sm text-gray-600">
                  {rating === 1
                    ? "Poor"
                    : rating === 2
                    ? "Fair"
                    : rating === 3
                    ? "Good"
                    : rating === 4
                    ? "Very Good"
                    : "Excellent"}
                </span>
              )}
            </div>
          </div>

          {/* Comment */}
          <div>
            <Label htmlFor="comment" className="text-base font-medium mb-3 block">
              Add a comment (optional)
            </Label>
            <Textarea
              id="comment"
              placeholder="Share details about your experience with this customer..."
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              disabled={isSubmitting}
              rows={4}
              className="resize-none"
              maxLength={500}
            />
            <p className="text-xs text-gray-500 mt-1">
              {comment.length}/500 characters
            </p>
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-3 pt-2">
            <Button
              variant="outline"
              onClick={handleClose}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting || rating === 0}
              className="bg-gradient-to-r from-[#FF0077] to-[#D60565] hover:from-[#D60565] hover:to-[#FF0077] text-white"
            >
              {isSubmitting ? "Submitting..." : "Submit Rating"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import LimitWarning from "./LimitWarning";
import { fetcher } from "@/lib/http/fetcher";
import { useAuth } from "@/providers/AuthProvider";
import LoadingTimeout from "@/components/ui/loading-timeout";

interface UsageData {
  feature_type: string;
  current_usage: number;
  limit_value: number | null;
  percentage_used: number;
  is_unlimited: boolean;
  can_use: boolean;
  warning_threshold: boolean;
}

export default function UsageSummary() {
  const { user } = useAuth();
  const [usageData, setUsageData] = useState<UsageData[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadUsage = async () => {
      if (!user) {
        setLoading(false);
        return;
      }

      try {
        // Fetch usage summary
        const response = await fetcher.get<{ data: UsageData[] }>(
          `/api/provider/usage-summary`
        );
        setUsageData(response.data || []);
      } catch (error) {
        console.error("Error loading usage summary:", error);
        // Don't show error to user, just return empty
        setUsageData([]);
      } finally {
        setLoading(false);
      }
    };

    loadUsage();
  }, [user]);

  if (loading) {
    return <LoadingTimeout loadingMessage="Loading usage..." />;
  }

  if (usageData.length === 0) {
    return null;
  }

  const getFeatureLabel = (type: string) => {
    const labels: Record<string, string> = {
      bookings: "Bookings This Month",
      messages: "Messages This Month",
      staff: "Staff Members",
      locations: "Locations",
    };
    return labels[type] || type;
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Subscription Usage</CardTitle>
        <CardDescription>
          Track your current usage against plan limits
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {usageData.map((usage) => {
          if (usage.is_unlimited) {
            return (
              <div key={usage.feature_type} className="space-y-2">
                <div className="flex justify-between items-center">
                  <span className="text-sm font-medium">
                    {getFeatureLabel(usage.feature_type)}
                  </span>
                  <span className="text-sm text-green-600 font-semibold">
                    Unlimited
                  </span>
                </div>
              </div>
            );
          }

          const percentage = usage.percentage_used;
          const isWarning = usage.warning_threshold && percentage < 100;
          const isExceeded = !usage.can_use;

          return (
            <div key={usage.feature_type} className="space-y-2">
              <div className="flex justify-between items-center">
                <span className="text-sm font-medium">
                  {getFeatureLabel(usage.feature_type)}
                </span>
                <span
                  className={`text-sm font-semibold ${
                    isExceeded
                      ? "text-red-600"
                      : isWarning
                      ? "text-yellow-600"
                      : "text-gray-600"
                  }`}
                >
                  {usage.current_usage} / {usage.limit_value}
                </span>
              </div>
              <Progress
                value={Math.min(percentage, 100)}
                className={`h-2 ${
                  isExceeded
                    ? "bg-red-100"
                    : isWarning
                    ? "bg-yellow-100"
                    : ""
                }`}
              />
              {(isWarning || isExceeded) && (
                <LimitWarning
                  featureType={usage.feature_type as any}
                  currentUsage={usage.current_usage}
                  limit={usage.limit_value}
                  percentageUsed={percentage}
                  planName="Current Plan"
                />
              )}
            </div>
          );
        })}
      </CardContent>
    </Card>
  );
}

"use client"

import * as React from "react"
import * as AccordionPrimitive from "@radix-ui/react-accordion"
import { ChevronDown } from "lucide-react"

import { cn } from "@/lib/utils"

const Accordion = AccordionPrimitive.Root

const AccordionItem = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Item>
>(({ className, ...props }, ref) => (
  <AccordionPrimitive.Item
    ref={ref}
    className={cn("border-b", className)}
    {...props}
  />
))
AccordionItem.displayName = "AccordionItem"

const AccordionTrigger = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Trigger>
>(({ className, children, ...props }, ref) => {
  // Separate children into text content and button elements
  const childrenArray = React.Children.toArray(children);
  const textChildren: React.ReactNode[] = [];
  const buttonChildren: React.ReactNode[] = [];

  const isButtonElement = (child: React.ReactNode): boolean => {
    if (!React.isValidElement(child)) return false;
    
    // Check if it's a native button element
    if (child.type === 'button') return true;
    
    // Check if it's a Button component by checking displayName
    if (typeof child.type === 'object' && child.type !== null) {
      const componentType = child.type as any;
      if (componentType.displayName === 'Button') return true;
    }
    
    // Check props for Button-like characteristics
    const props = child.props as any;
    if (props && (props.variant !== undefined || props.size === 'icon' || props['aria-haspopup'])) {
      // Additional check: if it has button-like props but isn't explicitly a div/span, treat as button
      if (child.type !== 'div' && child.type !== 'span' && child.type !== 'p') {
        return true;
      }
    }
    
    return false;
  };

  childrenArray.forEach((child) => {
    if (isButtonElement(child)) {
      buttonChildren.push(child);
    } else {
      textChildren.push(child);
    }
  });

  return (
    <AccordionPrimitive.Header className="flex">
      <div className="flex flex-1 items-center justify-between w-full">
        <AccordionPrimitive.Trigger
          ref={ref}
          className={cn(
            "flex flex-1 items-center justify-between py-2 mb-3 font-normal transition-all [&[data-state=open]>svg]:rotate-180",
            className
          )}
          {...props}
        >
          <span className="flex-1">
            {textChildren}
          </span>
          <ChevronDown className="h-6 w-6 shrink-0 transition-transform duration-200" />
        </AccordionPrimitive.Trigger>
        {buttonChildren.length > 0 && (
          <div 
            className="flex items-center gap-2 ml-2"
            onClick={(e) => {
              // Prevent accordion toggle when clicking action buttons
              e.stopPropagation();
            }}
            onMouseDown={(e) => {
              // Also prevent on mouse down to avoid any interaction issues
              e.stopPropagation();
            }}
          >
            {buttonChildren}
          </div>
        )}
      </div>
    </AccordionPrimitive.Header>
  );
})
AccordionTrigger.displayName = AccordionPrimitive.Trigger.displayName

const AccordionContent = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Content>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Content
    ref={ref}
    className="overflow-hidden text-sm md:text-lg text-secondary font-normal  transition-all data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down"
    {...props}
  >
    <div className={cn("pb-4 pt-0", className)}>{children}</div>
  </AccordionPrimitive.Content>
))

AccordionContent.displayName = AccordionPrimitive.Content.displayName

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent }

