"use client";

import { useAmplitudeContext } from "@/providers/AmplitudeProvider";

/**
 * Hook to access Amplitude analytics client
 */
export function useAmplitude(): {
  track: (eventName: string, eventProperties?: Record<string, any>) => void;
  identify: (userId: string, userProperties?: Record<string, any>) => void;
  setUserProperties: (userProperties: Record<string, any>) => void;
  reset: () => void;
  isReady: boolean;
} {
  const { amplitude, isInitialized } = useAmplitudeContext();

  const track = (eventName: string, eventProperties?: Record<string, any>) => {
    if (amplitude && isInitialized) {
      amplitude.track(eventName, eventProperties);
    }
  };

  const identify = (userId: string, userProperties?: Record<string, any>) => {
    if (amplitude && isInitialized) {
      amplitude.identify(userId, userProperties);
    }
  };

  const setUserProperties = (userProperties: Record<string, any>) => {
    if (amplitude && isInitialized) {
      amplitude.setUserProperties(userProperties);
    }
  };

  const reset = () => {
    if (amplitude && isInitialized) {
      amplitude.reset();
    }
  };

  return {
    track,
    identify,
    setUserProperties,
    reset,
    isReady: isInitialized && !!amplitude,
  };
}

/**
 * Custom hook for API calls with loading and error states
 */

import { useState, useCallback } from 'react';
import { handleApiError } from '@/lib/api/client';
import { toast } from 'sonner';

export interface UseApiOptions<T> {
  showToast?: boolean;
  onSuccess?: (data: T) => void;
  onError?: (error: string) => void;
  initialData?: T | null;
}

export function useApi<T>(options: UseApiOptions<T> = {}) {
  const { showToast = true, onSuccess, onError, initialData = null } = options;

  const [data, setData] = useState<T | null>(initialData);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const execute = useCallback(
    async (apiCall: () => Promise<T>) => {
      try {
        setLoading(true);
        setError(null);

        const result = await apiCall();
        setData(result);

        if (onSuccess) {
          onSuccess(result);
        }

        return result;
      } catch (err) {
        const errorMessage = handleApiError(err);
        setError(errorMessage);

        if (showToast) {
          toast.error(errorMessage);
        }

        if (onError) {
          onError(errorMessage);
        }

        throw err;
      } finally {
        setLoading(false);
      }
    },
    [showToast, onSuccess, onError]
  );

  const reset = useCallback(() => {
    setData(initialData);
    setError(null);
  }, [initialData]);

  return {
    data,
    loading,
    error,
    execute,
    reset,
    setData, // Allow manual data updates if needed
  };
}

/**
 * Hook for fetching data on mount
 */
export function useApiData<T>(
  apiCall: () => Promise<T>,
  options: UseApiOptions<T> & { deps?: any[] } = {}
) {
  const { deps: _deps = [], ...apiOptions } = options;
  const api = useApi<T>(apiOptions);

  const fetchData = useCallback(async () => {
    return api.execute(apiCall);
  }, [api.execute, apiCall]);

  // Note: This hook doesn't auto-fetch on mount to avoid issues with SSR
  // Call fetchData() manually in useEffect if needed

  return {
    ...api,
    fetchData,
  };
}

/**
 * React Hook for Appointment Settings
 * 
 * Provides a hook to load and manage appointment settings in client components
 */

import { useState, useEffect } from "react";
import { fetcher } from "@/lib/http/fetcher";
import { DEFAULT_APPOINTMENT_STATUS } from "@/lib/provider-portal/constants";
import type { AppointmentSettings } from "@/lib/provider-portal/appointment-settings";

export function useAppointmentSettings() {
  const [settings, setSettings] = useState<AppointmentSettings>({
    defaultAppointmentStatus: DEFAULT_APPOINTMENT_STATUS,
    autoConfirmAppointments: false,
    requireConfirmationForBookings: true,
    updatedAt: null,
  });
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadSettings = async () => {
      try {
        setIsLoading(true);
        setError(null);
        const response = await fetcher.get<{ data: AppointmentSettings }>(
          "/api/provider/settings/appointments"
        );
        setSettings(response.data);
      } catch (err: any) {
        console.warn("Failed to load appointment settings:", err);
        setError(err.message || "Failed to load settings");
        // Keep default settings on error
      } finally {
        setIsLoading(false);
      }
    };

    loadSettings();
  }, []);

  const updateSettings = async (updates: Partial<AppointmentSettings>) => {
    try {
      setError(null);
      const response = await fetcher.patch<{ data: AppointmentSettings }>(
        "/api/provider/settings/appointments",
        updates
      );
      setSettings(response.data);
      return response.data;
    } catch (err: any) {
      const errorMessage = err.message || "Failed to update settings";
      setError(errorMessage);
      throw new Error(errorMessage);
    }
  };

  return {
    settings,
    isLoading,
    error,
    updateSettings,
    refetch: async () => {
      setIsLoading(true);
      try {
        const response = await fetcher.get<{ data: AppointmentSettings }>(
          "/api/provider/settings/appointments"
        );
        setSettings(response.data);
      } catch (err: any) {
        setError(err.message || "Failed to load settings");
      } finally {
        setIsLoading(false);
      }
    },
  };
}

"use client";

import { useRouter } from 'next/navigation';
import { useAuth } from '@/providers/AuthProvider';
import { FetchError } from '@/lib/http/fetcher';
import { useEffect } from 'react';

/**
 * Global error handler hook that redirects providers to provider portal
 * when they encounter 403 or 404 errors
 */
export function useErrorHandler() {
  const router = useRouter();
  const { user, role, isLoading } = useAuth();

  const handleError = (error: any) => {
    // Only handle FetchError with 403 or 404 status
    if (error instanceof FetchError && (error.status === 403 || error.status === 404)) {
      // Check if user is a provider
      if (!isLoading && user && role) {
        if (role === 'provider_owner' || role === 'provider_staff' || role === 'superadmin') {
          // Redirect to provider dashboard
          router.replace('/provider/dashboard');
          return true; // Indicates error was handled
        }
      }
    }
    return false; // Error not handled, let caller handle it
  };

  return { handleError };
}

/**
 * Global error handler that automatically redirects providers on 403/404
 * This can be used in a useEffect to catch unhandled errors
 */
export function useGlobalErrorRedirect() {
  const router = useRouter();
  const { user, role, isLoading } = useAuth();

  useEffect(() => {
    // Only set up global handler if user is a provider
    if (isLoading || !user || !role) return;
    if (role !== 'provider_owner' && role !== 'provider_staff' && role !== 'superadmin') return;

    const handleUnhandledError = (event: ErrorEvent) => {
      const error = event.error;
      if (error instanceof FetchError && (error.status === 403 || error.status === 404)) {
        // Only redirect if we're not already on a provider route
        if (!window.location.pathname.startsWith('/provider')) {
          event.preventDefault(); // Prevent default error handling
          router.replace('/provider/dashboard');
        }
      }
    };

    window.addEventListener('error', handleUnhandledError);
    return () => window.removeEventListener('error', handleUnhandledError);
  }, [user, role, isLoading, router]);
}

'use client';

import { useState, useEffect } from 'react';
import { isFeatureEnabled, checkMultipleFeatures } from '@/lib/feature-flags';

/**
 * Hook to check if a single feature is enabled
 * @param featureKey - The key of the feature to check
 * @returns { enabled: boolean, loading: boolean }
 */
export function useFeatureFlag(featureKey: string) {
  const [enabled, setEnabled] = useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    let mounted = true;

    async function checkFeature() {
      setLoading(true);
      try {
        const isEnabled = await isFeatureEnabled(featureKey);
        if (mounted) {
          setEnabled(isEnabled);
        }
      } catch (error) {
        console.error(`Error checking feature flag ${featureKey}:`, error);
        if (mounted) {
          setEnabled(false);
        }
      } finally {
        if (mounted) {
          setLoading(false);
        }
      }
    }

    checkFeature();

    return () => {
      mounted = false;
    };
  }, [featureKey]);

  return { enabled, loading };
}

/**
 * Hook to check multiple features at once
 * @param featureKeys - Array of feature keys to check
 * @returns { features: Record<string, boolean>, loading: boolean }
 */
export function useMultipleFeatureFlags(featureKeys: string[]) {
  const [features, setFeatures] = useState<Record<string, boolean>>({});
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    let mounted = true;

    async function checkFeatures() {
      setLoading(true);
      try {
        const results = await checkMultipleFeatures(featureKeys);
        if (mounted) {
          setFeatures(results);
        }
      } catch (error) {
        console.error('Error checking feature flags:', error);
        if (mounted) {
          // Set all to false on error
          const fallback = featureKeys.reduce(
            (acc, key) => ({ ...acc, [key]: false }),
            {}
          );
          setFeatures(fallback);
        }
      } finally {
        if (mounted) {
          setLoading(false);
        }
      }
    }

    if (featureKeys.length > 0) {
      checkFeatures();
    } else {
      setLoading(false);
    }

    return () => {
      mounted = false;
    };
  }, [featureKeys.join(',')]); // Re-run when keys change

  return { features, loading };
}

