  accuracy?: number;
  altitude?: number;
  heading?: number;
  speed?: number;
  timestamp: number;
}

interface UseGPSTrackingOptions {
  bookingId: string;
  enabled?: boolean;
  updateInterval?: number; // milliseconds
  onLocationUpdate?: (location: LocationData) => void;
  onError?: (error: Error) => void;
  fallbackToEstimated?: boolean;
}

interface UseGPSTrackingReturn {
  location: LocationData | null;
  isTracking: boolean;
  isGPSAvailable: boolean;
  isEstimated: boolean;
  error: Error | null;
  startTracking: () => void;
  stopTracking: () => void;
  updateLocation: (location: LocationData) => Promise<void>;
  estimateLocation: (reason: string) => Promise<void>;
}

/**
 * Hook for real-time GPS tracking with automatic fallback
 * 
 * Features:
 * - Automatic GPS tracking with periodic updates
 * - Fallback to estimated location when GPS unavailable
 * - Manual location updates
 * - Error handling and recovery
 */
export function useGPSTracking({
  bookingId,
  enabled = false,
  updateInterval = 10000, // 10 seconds default
  onLocationUpdate,
  onError,
  fallbackToEstimated = true,
}: UseGPSTrackingOptions): UseGPSTrackingReturn {
  const [location, setLocation] = useState<LocationData | null>(null);
  const [isTracking, setIsTracking] = useState(false);
  const [isGPSAvailable, setIsGPSAvailable] = useState(false);
  const [isEstimated, setIsEstimated] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  const watchIdRef = useRef<number | null>(null);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);
  const lastUpdateRef = useRef<number>(0);

  // Check if geolocation is available
  const checkGPSAvailability = useCallback(() => {
    if (!navigator.geolocation) {
      setIsGPSAvailable(false);
      return false;
    }
    setIsGPSAvailable(true);
    return true;
  }, []);

  // Update location to server
  const updateLocationToServer = useCallback(
    async (locationData: LocationData, isEstimated: boolean = false, estimatedReason?: string) => {
      try {
        const response = await fetcher.post<{
          data: { location: any; eta_minutes?: number; distance_km?: number };
        }>(`/api/provider/bookings/${bookingId}/location`, {
          latitude: locationData.latitude,
          longitude: locationData.longitude,
          accuracy: locationData.accuracy,
          altitude: locationData.altitude,
          heading: locationData.heading,
          speed: locationData.speed,
          is_estimated: isEstimated,
          estimated_reason: estimatedReason,
        });

        // Update local state
        setLocation(locationData);
        setIsEstimated(isEstimated);

        // Call callback
        if (onLocationUpdate) {
          onLocationUpdate(locationData);
        }

        return response.data;
      } catch (err) {
        const error = err instanceof FetchError ? err : new Error("Failed to update location");
        setError(error);
        if (onError) {
          onError(error);
        } else {
          console.error("GPS tracking error:", error);
        }
        throw error;
      }
    },
    [bookingId, onLocationUpdate, onError]
  );

  // Get current GPS position
  const getCurrentPosition = useCallback(
    (options?: PositionOptions): Promise<LocationData> => {
      return new Promise((resolve, reject) => {
        if (!navigator.geolocation) {
          reject(new Error("Geolocation is not supported"));
          return;
        }

        navigator.geolocation.getCurrentPosition(
          (position) => {
            const locationData: LocationData = {
              latitude: position.coords.latitude,
              longitude: position.coords.longitude,
              accuracy: position.coords.accuracy ?? undefined,
              altitude: position.coords.altitude ?? undefined,
              heading: position.coords.heading ?? undefined,
              speed: position.coords.speed ?? undefined,
              timestamp: position.timestamp,
            };
            resolve(locationData);
          },
          (error) => {
            reject(new Error(`GPS error: ${error.message}`));
          },
          {
            enableHighAccuracy: true,
            timeout: 10000,
            maximumAge: 5000,
            ...options,
          }
        );
      });
    },
    []
  );

  // Start GPS tracking
  const startTracking = useCallback(() => {
    if (isTracking) return;

    checkGPSAvailability();

    if (!navigator.geolocation) {
      if (fallbackToEstimated) {
        toast.warning("GPS not available. Using estimated location.");
        setIsEstimated(true);
        setIsTracking(true);
        // Start periodic estimated updates
        intervalRef.current = setInterval(() => {
          estimateLocation("gps_unavailable");
        }, updateInterval);
      } else {
        setError(new Error("Geolocation is not supported by your browser"));
        return;
      }
      return;
    }

    setIsTracking(true);
    setError(null);

    // Get initial position
    getCurrentPosition()
      .then((locationData) => {
        updateLocationToServer(locationData, false);
      })
      .catch((err) => {
        console.warn("Failed to get initial GPS position:", err);
        if (fallbackToEstimated) {
          toast.warning("GPS unavailable. Using estimated location.");
          estimateLocation("gps_error");
        } else {
          setError(err);
        }
      });

    // Watch position for continuous updates
    watchIdRef.current = navigator.geolocation.watchPosition(
      (position) => {
        const locationData: LocationData = {
          latitude: position.coords.latitude,
          longitude: position.coords.longitude,
          accuracy: position.coords.accuracy ?? undefined,
          altitude: position.coords.altitude ?? undefined,
          heading: position.coords.heading ?? undefined,
          speed: position.coords.speed ?? undefined,
          timestamp: position.timestamp,
        };

        // Throttle updates to server (don't update more than once per interval)
        const now = Date.now();
        if (now - lastUpdateRef.current >= updateInterval) {
          updateLocationToServer(locationData, false);
          lastUpdateRef.current = now;
        } else {
          // Update local state immediately for UI responsiveness
          setLocation(locationData);
          setIsEstimated(false);
          if (onLocationUpdate) {
            onLocationUpdate(locationData);
          }
        }
      },
      (error) => {
        console.warn("GPS watch error:", error);
        setIsGPSAvailable(false);
        
        if (fallbackToEstimated) {
          toast.warning("GPS signal lost. Using estimated location.");
          estimateLocation("gps_signal_lost");
        } else {
          setError(new Error(`GPS error: ${error.message}`));
        }
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 5000,
      }
    );
  }, [
    isTracking,
    fallbackToEstimated,
    checkGPSAvailability,
    getCurrentPosition,
    updateLocationToServer,
    updateInterval,
    onLocationUpdate,
  ]);

  // Stop GPS tracking
  const stopTracking = useCallback(() => {
    if (watchIdRef.current !== null) {
      navigator.geolocation.clearWatch(watchIdRef.current);
      watchIdRef.current = null;
    }

    if (intervalRef.current !== null) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }

    setIsTracking(false);
  }, []);

  // Manual location update
  const updateLocation = useCallback(
    async (locationData: LocationData) => {
      await updateLocationToServer(locationData, false);
    },
    [updateLocationToServer]
  );

  // Estimate location (fallback when GPS unavailable)
  const estimateLocation = useCallback(
    async (reason: string = "gps_unavailable") => {
      if (!location) {
        // If we have no previous location, we can't estimate
        setError(new Error("Cannot estimate location: no previous location data"));
        return;
      }

      // Use last known location with estimated flag
      const estimatedLocation: LocationData = {
        ...location,
        timestamp: Date.now(),
      };

      await updateLocationToServer(estimatedLocation, true, reason);
    },
    [location, updateLocationToServer]
  );

  // Auto-start if enabled
  useEffect(() => {
    if (enabled && !isTracking) {
      startTracking();
    } else if (!enabled && isTracking) {
      stopTracking();
    }

    return () => {
      stopTracking();
    };
  }, [enabled, isTracking, startTracking, stopTracking]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      stopTracking();
    };
  }, [stopTracking]);

  return {
    location,
    isTracking,
    isGPSAvailable,
    isEstimated,
    error,
    startTracking,
    stopTracking,
    updateLocation,
    estimateLocation,
  };
}

"use client";

import { useEffect, useState, useRef } from "react";
import { useAuth } from "@/providers/AuthProvider";

// Track if we've already warned about SDK not loading (module-level to persist across renders)
let hasWarnedAboutSdkNotLoaded = false;

/**
 * Hook to register device with OneSignal
 * 
 * Call this in customer/provider/admin layouts to register devices
 */
export function useOneSignal() {
  const { user } = useAuth();
  const [isRegistered, setIsRegistered] = useState(false);
  const [isOneSignalReady, setIsOneSignalReady] = useState(false);
  const hasWarnedRef = useRef(false);

  // Wait for OneSignal to be available
  useEffect(() => {
    if (typeof window === "undefined") return;

    const appId = process.env.NEXT_PUBLIC_ONESIGNAL_APP_ID;
    
    // Only check for OneSignal if App ID is configured
    if (!appId) {
      return;
    }

    // Check if OneSignal is already loaded
    if ((window as any).OneSignal) {
      queueMicrotask(() => setIsOneSignalReady(true));
      return;
    }

    // Poll for OneSignal to be loaded (in case script loads after this hook runs)
    const checkInterval = setInterval(() => {
      if ((window as any).OneSignal) {
        setIsOneSignalReady(true);
        clearInterval(checkInterval);
      }
    }, 100);

    // Cleanup after 10 seconds if OneSignal still isn't loaded
    const timeout = setTimeout(() => {
      clearInterval(checkInterval);
      if (!(window as any).OneSignal && !hasWarnedAboutSdkNotLoaded && !hasWarnedRef.current && process.env.NODE_ENV === "development") {
        console.warn("OneSignal SDK not loaded after 10 seconds. Make sure the script is included in the page.");
        hasWarnedAboutSdkNotLoaded = true;
        hasWarnedRef.current = true;
      }
    }, 10000);

    return () => {
      clearInterval(checkInterval);
      clearTimeout(timeout);
    };
  }, []);

  useEffect(() => {
    if (!user || !isOneSignalReady) return;

    const OneSignal = (window as any).OneSignal;
    const appId = process.env.NEXT_PUBLIC_ONESIGNAL_APP_ID;

    if (!appId) {
      // App ID warning is handled in OneSignalProvider, so we just return silently here
      return;
    }

    // Initialize OneSignal if not already initialized
    try {
      OneSignal.init({
        appId: appId,
        notifyButton: {
          enable: false, // We'll handle notifications in-app
        },
        allowLocalhostAsSecureOrigin: true,
      });
    } catch (error) {
      // OneSignal might already be initialized
      if (process.env.NODE_ENV === "development") {
        console.log("OneSignal already initialized or initialization error:", error);
      }
    }

    // Register device when user is logged in
    OneSignal.getUserId()
      .then((playerId: string | null) => {
        if (playerId) {
          registerDevice(playerId);
        } else {
          // Wait for user ID to be available
          OneSignal.on("subscriptionChange", (isSubscribed: boolean) => {
            if (isSubscribed) {
              OneSignal.getUserId().then((pid: string | null) => {
                if (pid) {
                  registerDevice(pid);
                }
              });
            }
          });
        }
      })
      .catch((error: any) => {
        if (process.env.NODE_ENV === "development") {
          console.error("Error getting OneSignal user ID:", error);
        }
      });

    async function registerDevice(playerId: string) {
      if (isRegistered) return;

      try {
        // Determine platform
        const platform = /iPhone|iPad|iPod/.test(navigator.userAgent)
          ? "ios"
          : /Android/.test(navigator.userAgent)
          ? "android"
          : "web";

        // Register with backend
        const response = await fetch("/api/me/devices", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            player_id: playerId,
            platform,
          }),
        });

        if (response.ok) {
          setIsRegistered(true);
          if (process.env.NODE_ENV === "development") {
            console.log("Device registered with OneSignal");
          }
        } else {
          if (process.env.NODE_ENV === "development") {
            console.error("Failed to register device:", await response.text());
          }
        }
      } catch (error) {
        console.error("Error registering device:", error);
      }
    }
  }, [user, isOneSignalReady, isRegistered]);

  return { isRegistered };
}

import { useState, useEffect } from "react";
import { fetcher } from "@/lib/http/fetcher";

interface PageContent {
  id: string;
  page_slug: string;
  section_key: string;
  content_type: "text" | "html" | "json" | "image" | "video";
  content: string;
  metadata?: Record<string, any>;
  order: number;
  is_active: boolean;
}

interface PageContentGrouped {
  [sectionKey: string]: PageContent[];
}

/**
 * Hook to fetch page content from the API
 * Returns content grouped by section_key
 */
export function usePageContent(pageSlug: string) {
  const [content, setContent] = useState<PageContentGrouped>({});
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchContent = async () => {
      try {
        setIsLoading(true);
        setError(null);
        const response = await fetcher.get<{
          data: PageContentGrouped | null;
          error: null | { message: string; code: string };
        }>(`/api/public/pages/${pageSlug}`);

        if (response.data) {
          setContent(response.data);
        } else {
          setContent({});
        }
      } catch (err) {
        console.error(`Error fetching page content for ${pageSlug}:`, err);
        setError("Failed to load content");
        setContent({});
      } finally {
        setIsLoading(false);
      }
    };

    if (pageSlug) {
      fetchContent();
    }
  }, [pageSlug]);

  /**
   * Get content for a specific section
   * Returns the first item if multiple exist, or null if not found
   */
  const getSectionContent = (sectionKey: string): string | null => {
    const section = content[sectionKey];
    if (!section || section.length === 0) {
      return null;
    }
    // Return the first item's content
    return section[0].content;
  };

  /**
   * Get all content items for a specific section
   */
  const getSectionItems = (sectionKey: string): PageContent[] => {
    return content[sectionKey] || [];
  };

  return {
    content,
    isLoading,
    error,
    getSectionContent,
    getSectionItems,
  };
}

"use client";

import { useState, useEffect, useCallback } from "react";

export interface ReferenceDataItem {
  id: string;
  type: string;
  value: string;
  label: string;
  description?: string;
  display_order: number;
  is_active: boolean;
  metadata: Record<string, any>;
}

export interface ReferenceDataMap {
  [type: string]: ReferenceDataItem[];
}

// Reference data types available
export type ReferenceDataType =
  | "service_type"
  | "duration"
  | "price_type"
  | "availability"
  | "tax_rate"
  | "team_role"
  | "reminder_unit"
  | "extra_time"
  | "payment_method"
  | "booking_status"
  | "currency"
  | "cancellation_reason"
  | "discount_type"
  | "notification_channel"
  | "product_unit"
  | "working_day"
  | "commission_type"
  | "addon_category";

// Cache for reference data to avoid repeated fetches
let referenceDataCache: ReferenceDataMap | null = null;
let cacheTimestamp: number | null = null;
const CACHE_DURATION = 5 * 60 * 1000; // 5 minutes

/**
 * Hook to fetch and use reference data for dropdowns across the provider portal.
 * 
 * @param types - Optional array of specific types to fetch. If not provided, fetches all.
 * @returns Object containing reference data, loading state, error, and helper functions
 * 
 * @example
 * ```tsx
 * const { data, isLoading, getOptions } = useReferenceData(["service_type", "duration"]);
 * 
 * // Use in a Select component
 * <Select>
 *   {getOptions("service_type").map(opt => (
 *     <SelectItem key={opt.value} value={opt.value}>{opt.label}</SelectItem>
 *   ))}
 * </Select>
 * ```
 */
export function useReferenceData(types?: ReferenceDataType[]) {
  const [data, setData] = useState<ReferenceDataMap>(referenceDataCache || {});
  const [isLoading, setIsLoading] = useState(!referenceDataCache);
  const [error, setError] = useState<string | null>(null);

  const fetchReferenceData = useCallback(async () => {
    // Check cache validity
    if (
      referenceDataCache &&
      cacheTimestamp &&
      Date.now() - cacheTimestamp < CACHE_DURATION
    ) {
      setData(referenceDataCache);
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      setError(null);

      const typesQuery = types?.length ? `?type=${types.join(",")}` : "";
      const response = await fetch(`/api/provider/reference-data${typesQuery}`);

      if (!response.ok) {
        throw new Error("Failed to fetch reference data");
      }

      const result = await response.json();
      const referenceData = result.data || {};

      // Update cache
      referenceDataCache = { ...referenceDataCache, ...referenceData };
      cacheTimestamp = Date.now();

      setData(referenceDataCache ?? {});
    } catch (err) {
      console.error("Error fetching reference data:", err);
      setError(err instanceof Error ? err.message : "Failed to fetch reference data");

      // Use fallback data if available
      if (referenceDataCache) {
        setData(referenceDataCache ?? {});
      }
    } finally {
      setIsLoading(false);
    }
  }, [types]);

  useEffect(() => {
    fetchReferenceData();
  }, [fetchReferenceData]);

  /**
   * Get options for a specific reference data type
   */
  const getOptions = useCallback(
    (type: ReferenceDataType): ReferenceDataItem[] => {
      return data[type] || [];
    },
    [data]
  );

  /**
   * Get a single option by type and value
   */
  const getOption = useCallback(
    (type: ReferenceDataType, value: string): ReferenceDataItem | undefined => {
      return data[type]?.find((item) => item.value === value);
    },
    [data]
  );

  /**
   * Get the label for a specific value
   */
  const getLabel = useCallback(
    (type: ReferenceDataType, value: string): string => {
      const option = getOption(type, value);
      return option?.label || value;
    },
    [getOption]
  );

  /**
   * Refresh the reference data (bypass cache)
   */
  const refresh = useCallback(async () => {
    referenceDataCache = null;
    cacheTimestamp = null;
    await fetchReferenceData();
  }, [fetchReferenceData]);

  return {
    data,
    isLoading,
    error,
    getOptions,
    getOption,
    getLabel,
    refresh,
  };
}

/**
 * Clear the reference data cache
 */
export function clearReferenceDataCache() {
  referenceDataCache = null;
  cacheTimestamp = null;
}

/**
 * Prefetch reference data (can be called on app init)
 */
export async function prefetchReferenceData(): Promise<ReferenceDataMap> {
  if (
    referenceDataCache &&
    cacheTimestamp &&
    Date.now() - cacheTimestamp < CACHE_DURATION
  ) {
    return referenceDataCache;
  }

  try {
    const response = await fetch("/api/provider/reference-data");
    if (!response.ok) {
      throw new Error("Failed to fetch reference data");
    }

    const result = await response.json();
    referenceDataCache = result.data || {};
    cacheTimestamp = Date.now();

    return referenceDataCache ?? {};
  } catch (err) {
    console.error("Error prefetching reference data:", err);
    return {};
  }
}

export default useReferenceData;

"use client";

import { useState, useEffect } from "react";
import { fetcher } from "@/lib/http/fetcher";
import { useAuth } from "@/providers/AuthProvider";

interface SavedAddress {
  id: string;
  label: string;
  address_line1: string;
  address_line2?: string | null;
  city: string;
  state?: string | null;
  postal_code?: string | null;
  country: string;
  latitude?: number | null;
  longitude?: number | null;
  is_default: boolean;
  created_at: string;
  updated_at: string;
  // House call specific fields
  apartment_unit?: string | null;
  building_name?: string | null;
  floor_number?: string | null;
  access_codes?: { gate?: string; buzzer?: string; door?: string } | string | null;
  parking_instructions?: string | null;
  location_landmarks?: string | null;
}

export function useSavedAddresses() {
  const { user, isLoading: authLoading } = useAuth();
  const [addresses, setAddresses] = useState<SavedAddress[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Only load addresses if user is authenticated
    if (!authLoading) {
      if (user) {
        loadAddresses();
      } else {
        // User not authenticated, set empty addresses
        setAddresses([]);
        setIsLoading(false);
        setError(null);
      }
    }
  }, [user, authLoading]);

  const loadAddresses = async () => {
    // Don't make API call if user is not authenticated
    if (!user) {
      setAddresses([]);
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      setError(null);
      const response = await fetcher.get<{ data: SavedAddress[] }>("/api/me/addresses", { cache: "no-store" });
      setAddresses(response.data || []);
    } catch (err: any) {
      // Only set error if it's not a 401/403 (unauthorized) error
      if (err.status !== 401 && err.status !== 403) {
        setError(err.message || "Failed to load addresses");
        console.error("Error loading addresses:", err);
      } else {
        // User not authenticated, clear addresses
        setAddresses([]);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const saveAddress = async (addressData: Omit<SavedAddress, "id" | "created_at" | "updated_at">) => {
    try {
      const response = await fetcher.post<{ data: SavedAddress }>("/api/me/addresses", addressData);
      await loadAddresses();
      return response.data;
    } catch (err: any) {
      throw new Error(err.message || "Failed to save address");
    }
  };

  const updateAddress = async (id: string, addressData: Partial<SavedAddress>) => {
    try {
      const response = await fetcher.put<{ data: SavedAddress }>(`/api/me/addresses/${id}`, addressData);
      await loadAddresses();
      return response.data;
    } catch (err: any) {
      throw new Error(err.message || "Failed to update address");
    }
  };

  const deleteAddress = async (id: string) => {
    try {
      await fetcher.delete(`/api/me/addresses/${id}`);
      await loadAddresses();
    } catch (err: any) {
      throw new Error(err.message || "Failed to delete address");
    }
  };

  const getDefaultAddress = () => {
    return addresses.find((addr) => addr.is_default) || addresses[0] || null;
  };

  return {
    addresses,
    isLoading,
    error,
    loadAddresses,
    saveAddress,
    updateAddress,
    deleteAddress,
    getDefaultAddress,
  };
}

"use client";

import { useState, useCallback } from "react";
import { fetcher } from "@/lib/http/fetcher";

export interface ServiceAvailability {
  in_zone: boolean;
  zones: Array<{
    id: string;
    name: string;
    type: string;
  }>;
  provider_count?: number;
  isLoading: boolean;
  error: string | null;
}

/**
 * Hook to check service availability at a location
 */
export function useServiceAvailability() {
  const [availability, setAvailability] = useState<ServiceAvailability>({
    in_zone: false,
    zones: [],
    isLoading: false,
    error: null,
  });

  const checkAvailability = useCallback(
    async (latitude: number, longitude: number, providerId?: string) => {
      setAvailability((prev) => ({ ...prev, isLoading: true, error: null }));

      try {
        // Check zone availability
        const zoneResponse = await fetcher.post<{
          data: {
            in_zone: boolean;
            zones: Array<{ id: string; name: string; type: string }>;
          };
        }>("/api/mapbox/check-zone", {
          point: { latitude, longitude },
          provider_id: providerId,
        });

        // Optionally get provider count (if API supports it)
        let providerCount: number | undefined;
        try {
          const searchResponse = await fetcher.get<{ data: { providers: any[] } }>(
            `/api/public/search?lat=${latitude}&lng=${longitude}&limit=1`
          );
          // Get total count from response if available
          providerCount = searchResponse.data?.providers?.length;
        } catch (err) {
          // Provider count is optional, don't fail if it errors
          console.log("Could not fetch provider count:", err);
        }

        setAvailability({
          in_zone: zoneResponse.data.in_zone,
          zones: zoneResponse.data.zones,
          provider_count: providerCount,
          isLoading: false,
          error: null,
        });
      } catch (error: any) {
        console.error("Error checking service availability:", error);
        setAvailability({
          in_zone: false,
          zones: [],
          isLoading: false,
          error: error.message || "Failed to check service availability",
        });
      }
    },
    []
  );

  const reset = useCallback(() => {
    setAvailability({
      in_zone: false,
      zones: [],
      isLoading: false,
      error: null,
    });
  }, []);

  return {
    availability,
    checkAvailability,
    reset,
  };
}

import { useState, useEffect } from 'react';
import { useAuth } from '@/providers/AuthProvider';
import { fetcher } from '@/lib/http/fetcher';

interface UsageData {
  feature_type: string;
  current_usage: number;
  limit_value: number | null;
  percentage_used: number;
  is_unlimited: boolean;
  can_use: boolean;
  warning_threshold: boolean;
}

export function useSubscriptionLimits() {
  const { user } = useAuth();
  const [usageData, setUsageData] = useState<UsageData[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadUsage = async () => {
      if (!user) {
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        setError(null);
        const response = await fetcher.get<{ data: UsageData[] }>(
          '/api/provider/usage-summary'
        );
        setUsageData(response.data || []);
      } catch (err: any) {
        console.error('Error loading usage summary:', err);
        setError(err.message || 'Failed to load usage data');
        setUsageData([]);
      } finally {
        setLoading(false);
      }
    };

    loadUsage();
    // Refresh every 5 minutes
    const interval = setInterval(loadUsage, 5 * 60 * 1000);
    return () => clearInterval(interval);
  }, [user]);

  const getUsageForFeature = (featureType: string): UsageData | null => {
    return usageData.find((u) => u.feature_type === featureType) || null;
  };

  const canUseFeature = (featureType: string): boolean => {
    const usage = getUsageForFeature(featureType);
    if (!usage) return true; // If no limit data, allow
    return usage.can_use;
  };

  const isNearLimit = (featureType: string): boolean => {
    const usage = getUsageForFeature(featureType);
    if (!usage) return false;
    return usage.warning_threshold && usage.percentage_used < 100;
  };

  const isAtLimit = (featureType: string): boolean => {
    const usage = getUsageForFeature(featureType);
    if (!usage) return false;
    return !usage.can_use;
  };

  return {
    usageData,
    loading,
    error,
    getUsageForFeature,
    canUseFeature,
    isNearLimit,
    isAtLimit,
    refresh: async () => {
      if (!user) return;
      try {
        setLoading(true);
        const response = await fetcher.get<{ data: UsageData[] }>(
          '/api/provider/usage-summary'
        );
        setUsageData(response.data || []);
      } catch (err: any) {
        setError(err.message || 'Failed to refresh usage data');
      } finally {
        setLoading(false);
      }
    },
  };
}

/**
 * Sponsored ads auction: when a buyer searches, we run an auction to decide which
 * ads appear in the top spots. Placement depends on bid, provider quality score,
 * and relevance (targeting vs search category).
 */

import { getSupabaseAdmin } from "@/lib/supabase/admin";

export interface AuctionParams {
  /** Search category (global_service_categories slug or id) ΓÇô used for relevance */
  categorySlug?: string | null;
  categoryId?: string | null;
  /** Max number of sponsored slots to return */
  maxSlots: number;
  /** Optional: exclude these provider IDs (e.g. already in organic results) to avoid duplicate */
  excludeProviderIds?: string[];
}

export interface AuctionWinner {
  campaign_id: string;
  provider_id: string;
  bid_cpc: number;
  quality_score: number;
  relevance: number;
}

/**
 * Cost per impression = bid_cpc * COST_PER_IMPRESSION_RATIO (ZAR).
 * Used for auction eligibility (daily cap estimate). Actual charge is applied by DB trigger
 * when an impression row is inserted into ads_events (see migration 261).
 */
export const COST_PER_IMPRESSION_RATIO = 0.05;

/**
 * Run auction: returns ordered list of (campaign_id, provider_id) for sponsored slots.
 * Does not record impressions; caller should record after merging into search results.
 */
export async function runAdsAuction(params: AuctionParams): Promise<AuctionWinner[]> {
  const supabase = getSupabaseAdmin();
  const { categoryId, categorySlug, maxSlots, excludeProviderIds = [] } = params;
  if (maxSlots <= 0) return [];

  const env = process.env.NODE_ENV === "production" ? "production" : "development";
  const { data: config } = await supabase
    .from("ads_module_config")
    .select("enabled, max_sponsored_slots")
    .eq("environment", env)
    .maybeSingle();

  if (!config?.enabled) return [];
  const limit = Math.min(maxSlots, Number(config.max_sponsored_slots) || 5, 10);

  // Resolve category id from slug if needed
  let globalCategoryId: string | null = categoryId ?? null;
  if (!globalCategoryId && categorySlug) {
    const { data: cat } = await supabase
      .from("global_service_categories")
      .select("id")
      .eq("slug", categorySlug)
      .eq("is_active", true)
      .maybeSingle();
    globalCategoryId = cat?.id ?? null;
  }

  const todayStart = new Date();
  todayStart.setUTCHours(0, 0, 0, 0);
  const todayStartIso = todayStart.toISOString();

  // Active campaigns with budget remaining (and optional daily cap; pack campaigns cap by impression count)
  const { data: campaigns } = await supabase
    .from("ads_campaigns")
    .select("id, provider_id, budget, spent, daily_budget, bid_cpc, targeting, pack_impressions")
    .eq("status", "active")
    .gt("budget", 0);

  if (!campaigns?.length) return [];

  const campaignIds = campaigns.map((c: any) => c.id);
  const { data: eventsToday } = await supabase
    .from("ads_events")
    .select("campaign_id")
    .in("campaign_id", campaignIds)
    .gte("created_at", todayStartIso);

  const todayCountByCampaign: Record<string, number> = {};
  (eventsToday ?? []).forEach((e: any) => {
    if (e.campaign_id) todayCountByCampaign[e.campaign_id] = (todayCountByCampaign[e.campaign_id] ?? 0) + 1;
  });

  const packCampaignIds = (campaigns as any[]).filter((c) => c.pack_impressions != null).map((c) => c.id);
  const impressionCountByCampaign: Record<string, number> = {};
  if (packCampaignIds.length > 0) {
    const { data: impressionCounts } = await supabase
      .from("ads_events")
      .select("campaign_id")
      .in("campaign_id", packCampaignIds)
      .eq("event_type", "impression");
    (impressionCounts ?? []).forEach((e: any) => {
      if (e.campaign_id) impressionCountByCampaign[e.campaign_id] = (impressionCountByCampaign[e.campaign_id] ?? 0) + 1;
    });
  }

  const eligible: Array<{
    id: string;
    provider_id: string;
    bid_cpc: number;
    targeting: { global_category_ids?: string[] };
    spent: number;
    daily_budget: number | null;
  }> = [];
  for (const c of campaigns as any[]) {
    if (c.pack_impressions != null) {
      const count = impressionCountByCampaign[c.id] ?? 0;
      if (count >= Number(c.pack_impressions)) continue;
    } else {
      const remaining = Number(c.budget) - Number(c.spent ?? 0);
      if (remaining <= 0) continue;
    }
    if (excludeProviderIds.includes(c.provider_id)) continue;
    const dailyBudget = c.daily_budget != null ? Number(c.daily_budget) : null;
    if (dailyBudget != null) {
      const todayImpressions = todayCountByCampaign[c.id] ?? 0;
      const costPerImp = c.pack_impressions != null ? Number(c.budget) / Number(c.pack_impressions) : Number(c.bid_cpc ?? 0) * COST_PER_IMPRESSION_RATIO;
      if (todayImpressions * costPerImp >= dailyBudget) continue;
    }
    const targeting = (c.targeting && typeof c.targeting === "object") ? c.targeting : {};
    const effectiveBid = c.pack_impressions != null ? Number(c.budget) / Number(c.pack_impressions) : Number(c.bid_cpc ?? 0);
    eligible.push({
      id: c.id,
      provider_id: c.provider_id,
      bid_cpc: effectiveBid,
      targeting: targeting,
      spent: Number(c.spent ?? 0),
      daily_budget: c.daily_budget != null ? Number(c.daily_budget) : null,
    });
  }

  if (eligible.length === 0) return [];

  const providerIds = [...new Set(eligible.map((e) => e.provider_id))];
  const { data: qualityRows } = await supabase
    .from("provider_quality_score")
    .select("provider_id, computed_score")
    .in("provider_id", providerIds);
  const qualityByProvider = new Map<string, number>();
  (qualityRows ?? []).forEach((r: any) => qualityByProvider.set(r.provider_id, Number(r.computed_score ?? 0)));

  // Relevance: 1 if campaign targets this category (or no category filter), else 0.5
  const scoreCandidates: AuctionWinner[] = eligible.map((c) => {
    const quality = qualityByProvider.get(c.provider_id) ?? 0.3;
    const categoryIds = c.targeting?.global_category_ids ?? [];
    const relevance =
      !globalCategoryId ? 1 : categoryIds.length === 0 ? 1 : categoryIds.includes(globalCategoryId) ? 1 : 0.5;
    return {
      campaign_id: c.id,
      provider_id: c.provider_id,
      bid_cpc: c.bid_cpc,
      quality_score: quality,
      relevance,
    };
  });

  // Rank by bid * quality * relevance (desc)
  scoreCandidates.sort((a, b) => {
    const scoreA = a.bid_cpc * (a.quality_score || 0.2) * a.relevance;
    const scoreB = b.bid_cpc * (b.quality_score || 0.2) * b.relevance;
    return scoreB - scoreA;
  });

  const winners = scoreCandidates.slice(0, limit);
  return winners;
}

/**
 * Record impression events for auction winners. Call after merging sponsored results into search.
 * idempotencyKey can be search_request_id or composite of (search, user, timestamp) to avoid double-counting.
 */
export async function recordAdImpressions(
  winners: AuctionWinner[],
  idempotencyPrefix: string
): Promise<void> {
  if (winners.length === 0) return;
  const supabase = getSupabaseAdmin();
  const rows = winners.map((w, i) => ({
    campaign_id: w.campaign_id,
    provider_id: w.provider_id,
    event_type: "impression",
    idempotency_key: `${idempotencyPrefix}:impression:${w.campaign_id}:${i}`,
    attribution: { source: "search", rank: i + 1 },
  }));
  await supabase.from("ads_events").upsert(rows, {
    onConflict: "idempotency_key",
    ignoreDuplicates: true,
  });
}

/**
 * Server-only Gemini API client.
 * API key must be passed from gemini_integration_config (never from env in this module).
 */

export interface CallGeminiParams {
  apiKey: string;
  model: string;
  system?: string;
  user: string;
  temperature?: number;
  maxTokens?: number;
  schema?: Record<string, any>;
}

export interface CallGeminiResult {
  text: string;
  tokensIn: number;
  tokensOut: number;
  success: boolean;
  errorCode?: string;
}

interface GeminiCandidatePart {
  text?: string;
}
interface GeminiCandidateContent {
  parts?: GeminiCandidatePart[];
}
interface GeminiCandidate {
  content?: GeminiCandidateContent;
}
interface GeminiUsageMetadata {
  promptTokenCount?: number;
  candidatesTokenCount?: number;
  totalTokenCount?: number;
}
interface GeminiResponse {
  candidates?: GeminiCandidate[];
  usageMetadata?: GeminiUsageMetadata;
}

/**
 * Call Gemini generateContent. Returns raw text and token counts.
 */
export async function callGemini(params: CallGeminiParams): Promise<CallGeminiResult> {
  const {
    apiKey,
    model,
    system = "",
    user,
    temperature = 0.3,
    maxTokens = 600,
  } = params;

  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${encodeURIComponent(apiKey)}`;

  const body: Record<string, any> = {
    contents: [{ parts: [{ text: user }] }],
    generationConfig: {
      temperature,
      maxOutputTokens: maxTokens,
    },
  };
  if (system) {
    body.system_instruction = { parts: [{ text: system }] };
  }

  try {
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });

    const data = await res.json();

    if (!res.ok) {
      const _errMessage = (data as { error?: { message?: string } }).error?.message ?? res.statusText;
      return {
        text: "",
        tokensIn: 0,
        tokensOut: 0,
        success: false,
        errorCode: `GEMINI_${res.status}`,
      };
    }

    const payload = data as GeminiResponse;
    const candidates = payload.candidates;
    const candidate = candidates?.[0];
    const text = candidate?.content?.parts?.map((p) => p.text ?? "").join("") ?? "";
    const usage = payload.usageMetadata;
    const tokensIn = usage?.promptTokenCount ?? 0;
    const tokensOut = usage?.candidatesTokenCount ?? usage?.totalTokenCount ?? 0;

    return { text, tokensIn, tokensOut, success: true };
  } catch (err) {
    console.error("Gemini call error:", err);
    return {
      text: "",
      tokensIn: 0,
      tokensOut: 0,
      success: false,
      errorCode: "GEMINI_NETWORK",
    };
  }
}

/**
 * Amplitude Client SDK Initialization
 */

import * as amplitude from "@amplitude/analytics-browser";
import { AmplitudeConfig } from "./types";
import { PluginPipeline, PluginContext } from "./plugins";

let pluginPipeline: PluginPipeline | null = null;
let isInitialized = false;

export interface AmplitudeClient {
  track: (eventName: string, eventProperties?: Record<string, any>) => void;
  identify: (userId: string, userProperties?: Record<string, any>) => void;
  setUserProperties: (userProperties: Record<string, any>) => void;
  reset: () => void;
  isReady: () => boolean;
}

/**
 * Initialize Amplitude SDK with config
 */
export async function initAmplitude(
  config: AmplitudeConfig,
  context: PluginContext
): Promise<AmplitudeClient | null> {
  if (isInitialized && pluginPipeline) {
    return createClient(pluginPipeline);
  }

  if (!config.api_key_public) {
    console.warn("[Amplitude] No API key provided, skipping initialization");
    return null;
  }

  try {
    // Initialize Amplitude SDK
    amplitude.init(config.api_key_public, {
      defaultTracking: {
        pageViews: false, // We'll track page views manually
        sessions: false, // We'll track sessions manually
        formInteractions: false,
        fileDownloads: false,
      },
    });

    // Create plugin pipeline
    pluginPipeline = new PluginPipeline(context);

    isInitialized = true;

    return createClient(pluginPipeline);
  } catch (error) {
    console.error("[Amplitude] Failed to initialize:", error);
    return null;
  }
}

function createClient(pipeline: PluginPipeline): AmplitudeClient {
  return {
    track: async (eventName: string, eventProperties?: Record<string, any>) => {
      try {
        // Process event through pipeline
        const processedEvent = await pipeline.execute({
          event_type: eventName,
          event_properties: eventProperties,
        });

        // Track with Amplitude SDK
        amplitude.track(processedEvent.event_type, processedEvent.event_properties);
      } catch (error) {
        console.error("[Amplitude] Error tracking event:", error);
      }
    },

    identify: (userId: string, userProperties?: Record<string, any>) => {
      try {
        amplitude.setUserId(userId);
        if (userProperties) {
          const identify = new amplitude.Identify();
          Object.entries(userProperties).forEach(([key, value]) => {
            identify.set(key, value);
          });
          amplitude.identify(identify);
        }
      } catch (error) {
        console.error("[Amplitude] Error identifying user:", error);
      }
    },

    setUserProperties: (userProperties: Record<string, any>) => {
      try {
        const identify = new amplitude.Identify();
        Object.entries(userProperties).forEach(([key, value]) => {
          identify.set(key, value);
        });
        amplitude.identify(identify);
      } catch (error) {
        console.error("[Amplitude] Error setting user properties:", error);
      }
    },

    reset: () => {
      try {
        amplitude.reset();
      } catch (error) {
        console.error("[Amplitude] Error resetting:", error);
      }
    },

    isReady: () => isInitialized && !!pluginPipeline,
  };
}

/**
 * Get current Amplitude instance (if initialized)
 */
export function getAmplitudeInstance(): AmplitudeClient | null {
  if (!isInitialized || !pluginPipeline) {
    return null;
  }
  return createClient(pluginPipeline);
}

/**
 * Privacy Plugin
 * Redacts PII from event properties
 */

import { AmplitudePlugin, PluginContext } from "./types";
import { AmplitudeEvent } from "../types";

const PII_DENYLIST = [
  "email",
  "phone",
  "phone_number",
  "message",
  "content",
  "notes",
  "special_requests",
  "address_line1",
  "address_line2",
  "address",
  "full_address",
  "password",
  "credit_card",
  "card_number",
  "ssn",
  "social_security_number",
];

export class PrivacyPlugin implements AmplitudePlugin {
  name = "privacy";
  private context: PluginContext;

  constructor(context: PluginContext) {
    this.context = context;
  }

  execute(event: AmplitudeEvent): AmplitudeEvent {
    const cleaned: AmplitudeEvent = { ...event };

    // Clean event properties
    if (cleaned.event_properties) {
      cleaned.event_properties = this.redactObject(cleaned.event_properties);
    }

    // Clean user properties
    if (cleaned.user_properties) {
      cleaned.user_properties = this.redactObject(cleaned.user_properties);
    }

    // Log redaction in debug mode
    if (this.context.config?.debug_mode) {
      const originalProps = JSON.stringify(event.event_properties || {});
      const cleanedProps = JSON.stringify(cleaned.event_properties || {});
      if (originalProps !== cleanedProps) {
        console.log("[Amplitude Privacy] Redacted PII from event properties");
      }
    }

    return cleaned;
  }

  private redactObject(obj: Record<string, any>): Record<string, any> {
    const cleaned: Record<string, any> = {};

    for (const [key, value] of Object.entries(obj)) {
      const lowerKey = key.toLowerCase();

      // Check if key matches denylist
      if (PII_DENYLIST.some((denied) => lowerKey.includes(denied))) {
        // Skip this property
        continue;
      }

      // Recursively clean nested objects
      if (value && typeof value === "object" && !Array.isArray(value) && !(value instanceof Date)) {
        cleaned[key] = this.redactObject(value);
      } else if (Array.isArray(value)) {
        // Clean array items if they're objects
        cleaned[key] = value.map((item) =>
          item && typeof item === "object" && !(item instanceof Date)
            ? this.redactObject(item)
            : item
        );
      } else {
        cleaned[key] = value;
      }
    }

    return cleaned;
  }
}

/**
 * Server-Side Amplitude Tracking
 * Uses Amplitude HTTP API for server-side event tracking.
 * Config is cached in-memory with a 5-minute TTL to avoid
 * querying the database on every track call.
 */

import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { AmplitudeEvent } from "./types";

const AMPLITUDE_API_ENDPOINT = "https://api2.amplitude.com/2/httpapi";

interface AmplitudeResponse {
  code: number;
  events_ingested?: number;
  events_dropped?: number;
  message?: string;
}

// --- In-memory config cache (5-minute TTL) ---

interface AmplitudeServerConfig {
  api_key_server: string | null;
  ingestion_endpoint: string | null;
}

let cachedConfig: AmplitudeServerConfig | null = null;
let cacheTimestamp = 0;
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

async function getCachedConfig(): Promise<AmplitudeServerConfig | null> {
  const now = Date.now();
  if (cachedConfig && now - cacheTimestamp < CACHE_TTL_MS) {
    return cachedConfig;
  }

  try {
    const supabase = getSupabaseAdmin();
    const { data: config } = await supabase
      .from("amplitude_integration_config")
      .select("api_key_server, ingestion_endpoint")
      .eq(
        "environment",
        process.env.NODE_ENV === "production" ? "production" : "development"
      )
      .maybeSingle();

    cachedConfig = config ?? null;
    cacheTimestamp = now;
    return cachedConfig;
  } catch (error) {
    console.error("[Amplitude Server] Failed to fetch config:", error);
    // Return stale cache if available, otherwise null
    return cachedConfig;
  }
}

/**
 * Track event server-side using Amplitude HTTP API
 */
export async function trackServer(
  eventName: string,
  properties?: Record<string, any>,
  userId?: string,
  options?: {
    apiKey?: string;
    ingestionEndpoint?: string;
  }
): Promise<void> {
  try {
    const config = await getCachedConfig();

    const apiKey = options?.apiKey || config?.api_key_server || process.env.AMPLITUDE_SERVER_API_KEY;
    const endpoint = options?.ingestionEndpoint || config?.ingestion_endpoint || AMPLITUDE_API_ENDPOINT;

    if (!apiKey) {
      console.warn("[Amplitude Server] No API key configured, skipping event tracking");
      return;
    }

    // Build event payload
    const event: AmplitudeEvent = {
      event_type: eventName,
      user_id: userId,
      event_properties: properties,
      time: Date.now(),
    };

    // Send to Amplitude
    const response = await fetch(endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        api_key: apiKey,
        events: [event],
      }),
    });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      console.error("[Amplitude Server] Failed to track event:", {
        status: response.status,
        error: errorData,
      });
      return;
    }

    const data: AmplitudeResponse = await response.json();

    if (data.code !== 200) {
      console.error("[Amplitude Server] Amplitude API error:", data);
    }
  } catch (error) {
    console.error("[Amplitude Server] Error tracking event:", error);
    // Don't throw - analytics failures shouldn't break the app
  }
}

/**
 * Track multiple events in a single batch
 */
export async function trackBatch(
  events: Array<{
    eventName: string;
    properties?: Record<string, any>;
    userId?: string;
  }>,
  options?: {
    apiKey?: string;
    ingestionEndpoint?: string;
  }
): Promise<void> {
  try {
    const config = await getCachedConfig();

    const apiKey = options?.apiKey || config?.api_key_server || process.env.AMPLITUDE_SERVER_API_KEY;
    const endpoint = options?.ingestionEndpoint || config?.ingestion_endpoint || AMPLITUDE_API_ENDPOINT;

    if (!apiKey) {
      console.warn("[Amplitude Server] No API key configured, skipping batch tracking");
      return;
    }

    // Build events payload
    const amplitudeEvents: AmplitudeEvent[] = events.map(({ eventName, properties, userId }) => ({
      event_type: eventName,
      user_id: userId,
      event_properties: properties,
      time: Date.now(),
    }));

    // Send to Amplitude
    const response = await fetch(endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        api_key: apiKey,
        events: amplitudeEvents,
      }),
    });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      console.error("[Amplitude Server] Failed to track batch:", {
        status: response.status,
        error: errorData,
      });
      return;
    }

    const data: AmplitudeResponse = await response.json();

    if (data.code !== 200) {
      console.error("[Amplitude Server] Amplitude API error:", data);
    }
  } catch (error) {
    console.error("[Amplitude Server] Error tracking batch:", error);
    // Don't throw - analytics failures shouldn't break the app
  }
}

/**
 * Amplitude Analytics Types
 */

export interface AmplitudeConfig {
  api_key_public: string | null;
  environment: "production" | "staging" | "development";
  enabled_client_portal: boolean;
  enabled_provider_portal: boolean;
  enabled_admin_portal: boolean;
  guides_enabled: boolean;
  surveys_enabled: boolean;
  sampling_rate: number;
  debug_mode: boolean;
}

export interface AmplitudeEvent {
  event_type: string;
  user_id?: string;
  device_id?: string;
  event_properties?: Record<string, any>;
  user_properties?: Record<string, any>;
  groups?: Record<string, any>;
  app_version?: string;
  platform?: string;
  os_name?: string;
  os_version?: string;
  device_brand?: string;
  device_model?: string;
  carrier?: string;
  country?: string;
