/**
 * Server-side role requirement helper
 * 
 * Use this in API routes and server components to check user roles.
 */

import { getSupabaseServer } from "@/lib/supabase/server";
import type { UserRole } from "@/types/beautonomi";
import { NextResponse } from "next/server";

export interface RequireRoleOptions {
  allowedRoles: UserRole[];
  redirectTo?: string;
}

/**
 * Requires user to have one of the allowed roles
 * 
 * @param allowedRoles - Array of roles that are allowed
 * @returns User object if authorized, null if not
 * @throws Redirects to login if not authenticated
 */
export async function requireRole(
  allowedRoles: UserRole[]
): Promise<{ user: { id: string; role: UserRole; email?: string; user_metadata?: any; full_name?: string | null } } | null> {
  const supabase = await getSupabaseServer();

  try {
    // Get authenticated user (validates with Supabase Auth server)
    const {
      data: { user: authUser },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !authUser) {
      // Check if it's a network/timeout error
      if (userError) {
        const errorMessage = userError.message?.toLowerCase() || '';
        const errorCause = (userError as any).cause;
        if (
          errorMessage.includes('timeout') ||
          errorMessage.includes('connect') ||
          errorMessage.includes('network') ||
          (errorCause && (
            errorCause.code === 'UND_ERR_CONNECT_TIMEOUT' ||
            errorCause.code === 'ECONNREFUSED' ||
            errorCause.code === 'ETIMEDOUT'
          ))
        ) {
          throw new Error(`Network error: ${userError.message}`);
        }
      }
      return null;
    }

    // Get user profile
    const { data: userData, error: userDataError } = await supabase
      .from('users')
      .select('id, role, full_name')
      .eq('id', authUser.id)
      .single();

    if (userDataError || !userData) {
      // Check if it's a network/timeout error
      if (userDataError) {
        const errorMessage = userDataError.message?.toLowerCase() || '';
        const errorCause = (userDataError as any).cause;
        const errorCode = userDataError.code || '';

        // Log the error for debugging
        console.error('Error fetching user data:', {
          code: errorCode,
          message: userDataError.message,
          details: userDataError.details,
          hint: userDataError.hint,
          userId: authUser.id
        });

        if (
          errorMessage.includes('timeout') ||
          errorMessage.includes('connect') ||
          errorMessage.includes('network') ||
          (errorCause && (
            errorCause.code === 'UND_ERR_CONNECT_TIMEOUT' ||
            errorCause.code === 'ECONNREFUSED' ||
            errorCause.code === 'ETIMEDOUT'
          ))
        ) {
          throw new Error(`Network error: ${userDataError.message}`);
        }

        // Check if user doesn't exist in users table (PGRST116)
        if (errorCode === 'PGRST116' || errorMessage.includes('no rows')) {
          console.error(`User ${authUser.id} exists in auth but not in users table`);
          throw new Error('User profile not found. Please contact support.');
        }

        // Check for RLS/permission errors
        if (errorCode === '42501' || errorMessage.includes('permission') || errorMessage.includes('policy')) {
          console.error(`RLS policy blocking access to user ${authUser.id}`);
          throw new Error('Permission denied: Unable to access user profile');
        }
      } else if (!userData) {
        // No error but no data - user doesn't exist in users table
        console.error(`User ${authUser.id} exists in auth but not in users table (no error returned)`);
        throw new Error('User profile not found. Please contact support.');
      }
      return null;
    }

    const userRole = (userData as any).role as UserRole;

    // Check if role is null or undefined
    if (!userRole) {
      console.error(`User ${authUser.id} has no role assigned in users table`);
      throw new Error('User role not assigned. Please contact support.');
    }

    // Check if user has required role
    if (!allowedRoles.includes(userRole)) {
      console.error(`User ${authUser.id} has role '${userRole}' but required one of: ${allowedRoles.join(', ')}`);
      return null;
    }

    return {
      user: {
        id: (userData as any).id,
        role: userRole,
        email: authUser.email,
        user_metadata: authUser.user_metadata,
        full_name: (userData as any).full_name,
      },
    };
  } catch (error) {
    // Handle network errors and timeouts
    if (error instanceof Error) {
      const errorMessage = error.message.toLowerCase();
      const errorCause = (error as any).cause;

      // Check for network/timeout errors
      if (
        errorMessage.includes('timeout') ||
        errorMessage.includes('connect') ||
        errorMessage.includes('fetch failed') ||
        (errorCause && (
          errorCause.code === 'UND_ERR_CONNECT_TIMEOUT' ||
          errorCause.code === 'ECONNREFUSED' ||
          errorCause.code === 'ETIMEDOUT'
        ))
      ) {
        // Re-throw network errors so they can be handled differently
        throw new Error(`Network error: ${error.message}`);
      }
    }
    // For other errors, return null (treat as auth failure)
    return null;
  }
}

/**
 * Creates a NextResponse error for unauthorized access
 */
export function unauthorizedResponse(message: string = "Unauthorized") {
  return NextResponse.json(
    { error: { message, code: "UNAUTHORIZED" } },
    { status: 401 }
  );
}

/**
 * Creates a NextResponse error for forbidden access (wrong role)
 */
export function forbiddenResponse(message: string = "Forbidden") {
  return NextResponse.json(
    { error: { message, code: "FORBIDDEN" } },
    { status: 403 }
  );
}

/**
 * Load Availability Constraints
 * Queries database for staff shifts, time blocks, and existing bookings
 */

import { SupabaseClient } from '@supabase/supabase-js';
import type {
  StaffShift,
  TimeBlock,
  BookingService,
  AvailabilityConstraints,
} from './types';
import { expandRecurringPattern } from './time-utils';

/**
 * Check if staff member has work hours enabled
 */
export async function checkWorkHoursEnabled(
  supabase: SupabaseClient,
  staffId: string | null
): Promise<boolean> {
  if (!staffId) {
    return false;
  }

  const { data: staffData, error } = await supabase
    .from('provider_staff')
    .select('work_hours_enabled')
    .eq('id', staffId)
    .single();

  if (error || !staffData) {
    // Default to true if we can't determine (backward compatibility)
    return true;
  }

  return staffData.work_hours_enabled ?? true;
}

/**
 * Load staff shifts for a given staff member and date
 * Returns empty array if work_hours_enabled is false
 */
export async function loadStaffShifts(
  supabase: SupabaseClient,
  staffId: string | null,
  date: string
): Promise<StaffShift[]> {
  if (!staffId) {
    return [];
  }

  // Check if work hours are enabled for this staff member
  const workHoursEnabled = await checkWorkHoursEnabled(supabase, staffId);
  
  // If work hours are disabled, return empty array (staff is not constrained by shifts)
  if (!workHoursEnabled) {
    return [];
  }

  // Query shifts for the specific date
  const { data: shifts, error } = await supabase
    .from('staff_shifts')
    .select('*')
    .eq('staff_id', staffId)
    .eq('date', date);

  if (error) {
    console.error('Error loading staff shifts:', error);
    return [];
  }

  if (!shifts) {
    return [];
  }

  // Also check for recurring shifts
  const { data: recurringShifts, error: recurringError } = await supabase
    .from('staff_shifts')
    .select('*')
    .eq('staff_id', staffId)
    .eq('is_recurring', true);

  if (!recurringError && recurringShifts) {
    const expandedRecurring = recurringShifts
      .filter((shift) => {
        if (!shift.recurring_pattern) return false;
        return expandRecurringPattern(
          shift.recurring_pattern as any,
          shift.date,
          date
        );
      })
      .map((shift) => ({
        ...shift,
        date, // Override date with target date
        is_recurring: false, // Mark as expanded
      }));

    return [...(shifts || []), ...expandedRecurring] as StaffShift[];
  }

  return (shifts || []) as StaffShift[];
}

/**
 * Load time blocks for a given staff member and date
 */
export async function loadTimeBlocks(
  supabase: SupabaseClient,
  staffId: string | null,
  date: string
): Promise<TimeBlock[]> {
  // Query time blocks for the specific date
  // staff_id = null means applies to all staff
  const query = supabase
    .from('time_blocks')
    .select('*')
    .eq('date', date)
    .eq('is_active', true);

  if (staffId) {
    query.or(`staff_id.eq.${staffId},staff_id.is.null`);
  } else {
    query.is('staff_id', null);
  }

  const { data: blocks, error } = await query;

  if (error) {
    console.error('Error loading time blocks:', error);
    return [];
  }

  if (!blocks) {
    return [];
  }

  // Also check for recurring blocks
  const recurringQuery = supabase
    .from('time_blocks')
    .select('*')
    .eq('is_recurring', true)
    .eq('is_active', true);

  if (staffId) {
    recurringQuery.or(`staff_id.eq.${staffId},staff_id.is.null`);
  } else {
    recurringQuery.is('staff_id', null);
  }

  const { data: recurringBlocks, error: recurringError } = await recurringQuery;

  if (!recurringError && recurringBlocks) {
    const expandedRecurring = recurringBlocks
      .filter((block) => {
        if (!block.recurring_pattern) return false;
        return expandRecurringPattern(
          block.recurring_pattern as any,
          block.date,
          date
        );
      })
      .map((block) => ({
        ...block,
        date, // Override date with target date
        is_recurring: false, // Mark as expanded
      }));

    return [...(blocks || []), ...expandedRecurring] as TimeBlock[];
  }

  return (blocks || []) as TimeBlock[];
}

/**
 * Load existing bookings for a given staff member and date
 * Includes buffer_minutes, processing_minutes, finishing_minutes from offerings table
 * Applies staff overrides if they exist
 */
export async function loadExistingBookings(
  supabase: SupabaseClient,
  staffId: string | null,
  date: string
): Promise<BookingService[]> {
  if (!staffId) {
    return [];
  }

  // Load staff overrides first
  const { data: staffData } = await supabase
    .from('provider_staff')
    .select('buffer_minutes_override, processing_minutes_override, finishing_minutes_override')
    .eq('id', staffId)
    .single();

  // Query booking_services for the date
  // Join with bookings to filter by status
  // Join with offerings to get buffer_minutes
  const { data: bookingServices, error } = await supabase
    .from('booking_services')
    .select(`
      id,
      booking_id,
      offering_id,
      staff_id,
      scheduled_start_at,
      scheduled_end_at,
      duration_minutes,
      bookings!inner (
        id,
        status
      ),
      offerings!inner (
        buffer_minutes,
        processing_minutes,
        finishing_minutes
      )
    `)
    .eq('staff_id', staffId)
    .gte('scheduled_start_at', `${date}T00:00:00`)
    .lt('scheduled_start_at', `${date}T23:59:59`)
    .neq('bookings.status', 'cancelled');

  if (error) {
    console.error('Error loading existing bookings:', error);
    return [];
  }

  if (!bookingServices) {
    return [];
  }

  // Transform to BookingService format, applying staff overrides
  return bookingServices
    .filter((bs: any) => {
      // Filter out cancelled bookings (should be handled by query but double-check)
      return bs.bookings?.status !== 'cancelled';
    })
    .map((bs: any) => {
      // Apply staff overrides if they exist, otherwise use service defaults
      const bufferMinutes = staffData?.buffer_minutes_override ?? bs.offerings?.buffer_minutes ?? 15;
      const processingMinutes = staffData?.processing_minutes_override ?? bs.offerings?.processing_minutes ?? 0;
      const finishingMinutes = staffData?.finishing_minutes_override ?? bs.offerings?.finishing_minutes ?? 0;

      return {
        id: bs.id,
        booking_id: bs.booking_id,
        offering_id: bs.offering_id,
        staff_id: bs.staff_id,
        scheduled_start_at: bs.scheduled_start_at,
        scheduled_end_at: bs.scheduled_end_at,
        duration_minutes: bs.duration_minutes,
        buffer_minutes: bufferMinutes,
        processing_minutes: processingMinutes,
        finishing_minutes: finishingMinutes,
      };
    }) as BookingService[];
}

/**
 * Load provider settings (gap avoidance, etc.)
 */
export async function loadProviderSettings(
  supabase: SupabaseClient,
  providerId: string
): Promise<{ avoidGaps: boolean; allowDoubleBookingManual: boolean }> {
  const { data: settings } = await supabase
    .from('provider_settings')
    .select('avoid_gaps, allow_double_booking_manual')
    .eq('provider_id', providerId)
    .single();

  return {
    avoidGaps: settings?.avoid_gaps ?? false,
    allowDoubleBookingManual: settings?.allow_double_booking_manual ?? false,
  };
}

/**
 * Load all constraints for availability calculation
 */
export async function loadAvailabilityConstraints(
  supabase: SupabaseClient,
  staffId: string | null,
  date: string,
  providerId?: string
): Promise<AvailabilityConstraints & { 
  providerSettings?: { avoidGaps: boolean; allowDoubleBookingManual: boolean };
  workHoursEnabled?: boolean;
}> {
  // Check work hours enabled first (needed for conditional loading)
  const workHoursEnabled = staffId ? await checkWorkHoursEnabled(supabase, staffId) : false;

  const [staffShifts, timeBlocks, existingBookings, providerSettings] = await Promise.all([
    loadStaffShifts(supabase, staffId, date),
    // Only load time blocks if work hours are enabled (time blocks are part of schedule management)
    workHoursEnabled ? loadTimeBlocks(supabase, staffId, date) : Promise.resolve([]),
    loadExistingBookings(supabase, staffId, date),
    providerId ? loadProviderSettings(supabase, providerId) : Promise.resolve(undefined),
  ]);

  return {
    staffShifts,
    timeBlocks,
    existingBookings,
    providerSettings,
    workHoursEnabled,
  } as AvailabilityConstraints & { 
    providerSettings?: { avoidGaps: boolean; allowDoubleBookingManual: boolean };
    workHoursEnabled?: boolean;
  };
}

/**
 * Resource Availability Utilities
 * Functions for checking resource conflicts and availability
 */

import { SupabaseClient } from '@supabase/supabase-js';

export interface Resource {
  id: string;
  provider_id: string;
  group_id: string | null;
  name: string;
  description: string | null;
  capacity: number;
  is_active: boolean;
}

export interface ResourceConflict {
  resourceId: string;
  resourceName: string;
  conflictingBookingId: string;
  conflictingTime: {
    start: string;
    end: string;
  };
}

/**
 * Check if resources are available for a time slot
 */
export async function checkResourceAvailability(
  supabase: SupabaseClient,
  resourceIds: string[],
  startAt: Date,
  endAt: Date,
  excludeBookingId?: string
): Promise<{ available: boolean; conflicts: ResourceConflict[] }> {
  if (resourceIds.length === 0) {
    return { available: true, conflicts: [] };
  }

  const conflicts: ResourceConflict[] = [];

  // Check each resource for conflicts
  for (const resourceId of resourceIds) {
    // Use RPC function if available, otherwise query directly
    const { data: isAvailable, error: rpcError } = await supabase.rpc(
      'check_resource_availability',
      {
        p_resource_id: resourceId,
        p_start_at: startAt.toISOString(),
        p_end_at: endAt.toISOString(),
        p_exclude_booking_id: excludeBookingId || null,
      }
    );

    if (!rpcError && isAvailable === false) {
      // Resource is not available, get conflict details
      const { data: conflictsData } = await supabase
        .from('booking_resources')
        .select(`
          booking_id,
          scheduled_start_at,
          scheduled_end_at,
          resources!inner (
            id,
            name
          )
        `)
        .eq('resource_id', resourceId)
        .lt('scheduled_start_at', endAt.toISOString())
        .gt('scheduled_end_at', startAt.toISOString())
        .neq('booking_id', excludeBookingId || '');

      if (conflictsData && conflictsData.length > 0) {
        for (const conflict of conflictsData) {
          conflicts.push({
            resourceId: resourceId,
            resourceName: (conflict.resources as any)?.name || 'Unknown',
            conflictingBookingId: conflict.booking_id,
            conflictingTime: {
              start: conflict.scheduled_start_at,
              end: conflict.scheduled_end_at,
            },
          });
        }
      }
    } else if (rpcError) {
      // Fallback: query directly if RPC doesn't exist
      const { data: conflictsData } = await supabase
        .from('booking_resources')
        .select(`
          booking_id,
          scheduled_start_at,
          scheduled_end_at,
          resources!inner (
            id,
            name
          ),
          bookings!inner (
            status
          )
        `)
        .eq('resource_id', resourceId)
        .lt('scheduled_start_at', endAt.toISOString())
        .gt('scheduled_end_at', startAt.toISOString())
        .neq('bookings.status', 'cancelled');

      if (excludeBookingId) {
        // Filter out the booking we're checking for (for reschedule scenarios)
        // This would need to be done in the query or after
      }

      if (conflictsData && conflictsData.length > 0) {
        for (const conflict of conflictsData) {
          if (excludeBookingId && conflict.booking_id === excludeBookingId) {
            continue; // Skip if it's the same booking
          }

          conflicts.push({
            resourceId: resourceId,
            resourceName: (conflict.resources as any)?.name || 'Unknown',
            conflictingBookingId: conflict.booking_id,
            conflictingTime: {
              start: conflict.scheduled_start_at,
              end: conflict.scheduled_end_at,
            },
          });
        }
      }
    }
  }

  return {
    available: conflicts.length === 0,
    conflicts,
  };
}

/**
 * Assign resources to a booking
 */
export async function assignResourcesToBooking(
  supabase: SupabaseClient,
  bookingId: string,
  bookingServiceId: string | null,
  resourceIds: string[],
  startAt: Date,
  endAt: Date
): Promise<void> {
  if (resourceIds.length === 0) {
    return;
  }

  const resourceAssignments = resourceIds.map((resourceId) => ({
    booking_id: bookingId,
    booking_service_id: bookingServiceId,
    resource_id: resourceId,
    scheduled_start_at: startAt.toISOString(),
    scheduled_end_at: endAt.toISOString(),
  }));

  const { error } = await supabase
    .from('booking_resources')
    .insert(resourceAssignments);

  if (error) {
    throw error;
  }
}

/**
 * Travel Time Buffer Calculation
 * Calculates travel time between consecutive at-home appointments
 */

import { SupabaseClient } from '@supabase/supabase-js';

export interface TravelTimeResult {
  distanceKm: number;
  estimatedMinutes: number;
  bufferMinutes: number; // ETA + 15 minutes safety margin
}

/**
 * Calculate travel time between two locations
 */
export async function calculateTravelTime(
  supabase: SupabaseClient,
  fromLat: number,
  fromLng: number,
  toLat: number,
  toLng: number
): Promise<TravelTimeResult> {
  try {
    // Use Mapbox distance API
    const response = await fetch(
      `/api/mapbox/distance?from=${fromLat},${fromLng}&to=${toLat},${toLng}`
    );

    if (!response.ok) {
      throw new Error('Failed to calculate travel time');
    }

    const data = await response.json();
    const distanceKm = data.distance || 0;
    const durationSeconds = data.duration || 0;
    const estimatedMinutes = Math.ceil(durationSeconds / 60);

    // Add 15 minutes safety margin
    const bufferMinutes = estimatedMinutes + 15;

    return {
      distanceKm,
      estimatedMinutes,
      bufferMinutes,
    };
  } catch (error) {
    console.error('Error calculating travel time:', error);
    // Fallback: estimate based on distance (assume 50 km/h average speed)
    const distanceKm = calculateHaversineDistance(fromLat, fromLng, toLat, toLng);
    const estimatedMinutes = Math.ceil((distanceKm / 50) * 60);
    const bufferMinutes = estimatedMinutes + 15;

    return {
      distanceKm,
      estimatedMinutes,
      bufferMinutes,
    };
  }
}

/**
 * Calculate distance between two points using Haversine formula
 */
function calculateHaversineDistance(
  lat1: number,
  lon1: number,
  lat2: number,
  lon2: number
): number {
  const R = 6371; // Earth's radius in km
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);

  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRad(lat1)) *
      Math.cos(toRad(lat2)) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

function toRad(degrees: number): number {
  return (degrees * Math.PI) / 180;
}

/**
 * Get travel buffer for at-home booking based on previous booking
 */
export async function getTravelBufferForAtHomeBooking(
  supabase: SupabaseClient,
  staffId: string,
  bookingDate: Date,
  bookingLocation: { lat: number; lng: number }
): Promise<number> {
  const date = bookingDate.toISOString().split('T')[0];

  // Find previous at-home booking for same staff on same day
  const { data: previousBooking } = await supabase
    .from('booking_services')
    .select(`
      scheduled_end_at,
      bookings!inner (
        location_type,
        address_latitude,
        address_longitude
      )
    `)
    .eq('staff_id', staffId)
    .eq('bookings.location_type', 'at_home')
    .lt('scheduled_end_at', bookingDate.toISOString())
    .gte('scheduled_start_at', `${date}T00:00:00`)
    .order('scheduled_end_at', { ascending: false })
    .limit(1)
    .single();

  if (!previousBooking || !previousBooking.bookings) {
    return 0; // No previous booking, no travel buffer needed
  }

  const prevBooking = previousBooking.bookings as any;
  if (!prevBooking.address_latitude || !prevBooking.address_longitude) {
    return 0; // No location data for previous booking
  }

  // Calculate travel time
  const travelTime = await calculateTravelTime(
    supabase,
    prevBooking.address_latitude,
    prevBooking.address_longitude,
    bookingLocation.lat,
    bookingLocation.lng
  );

  return travelTime.bufferMinutes;
}

/**
 * Appointment Reminders
 * Automated reminder system for upcoming bookings
 */

import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { sendTemplateNotification } from "@/lib/notifications/onesignal";

export interface ReminderConfig {
  hoursBefore: number[]; // e.g., [24, 2] for 24 hours and 2 hours before
  channels: ("push" | "email" | "sms")[];
}

const DEFAULT_REMINDER_CONFIG: ReminderConfig = {
  hoursBefore: [24, 2], // 24 hours and 2 hours before
  channels: ["push", "email"],
};

/**
 * Send appointment reminders for upcoming bookings
 */
export async function sendAppointmentReminders(config: ReminderConfig = DEFAULT_REMINDER_CONFIG) {
  const supabaseAdmin = getSupabaseAdmin();

  try {
    const now = new Date();
    const remindersSent: string[] = [];

    // Process each reminder time
    for (const hoursBefore of config.hoursBefore) {
      const reminderTime = new Date(now.getTime() + hoursBefore * 60 * 60 * 1000);
      const reminderTimeStart = new Date(reminderTime.getTime() - 30 * 60 * 1000); // 30 min window
      const reminderTimeEnd = new Date(reminderTime.getTime() + 30 * 60 * 1000);

      // Find bookings that need reminders
      const { data: bookings, error } = await supabaseAdmin
        .from("bookings")
        .select(`
          id,
          booking_number,
          scheduled_at,
          customer_id,
          provider_id,
          location_type,
          customers:users!bookings_customer_id_fkey(
            id,
            full_name,
            email,
            phone
          ),
          providers!inner(
            id,
            business_name
          ),
          booking_services(
            id,
            offering:offerings!inner(
              title
            )
          )
        `)
        .eq("status", "confirmed")
        .gte("scheduled_at", reminderTimeStart.toISOString())
        .lte("scheduled_at", reminderTimeEnd.toISOString())
        .is("cancelled_at", null);

      if (error) {
        console.error(`Error fetching bookings for ${hoursBefore}h reminder:`, error);
        continue;
      }

      if (!bookings || bookings.length === 0) {
        continue;
      }

      // Check which bookings haven't received this reminder yet
      for (const booking of bookings) {
        const reminderKey = `reminder_${hoursBefore}h_${booking.id}`;

        // Check if reminder already sent
        const { data: existingNotification } = await supabaseAdmin
          .from("notifications")
          .select("id")
          .eq("user_id", booking.customer_id)
          .eq("type", "appointment_reminder")
          .contains("metadata", { reminder_key: reminderKey })
          .limit(1);

        if (existingNotification && existingNotification.length > 0) {
          continue; // Already sent
        }

        const _customer = booking.customers as any;
        const provider = booking.providers as any;
        const services = (booking.booking_services || []).map((bs: any) => bs.offering?.title || "Service").join(", ");

        const scheduledDate = new Date(booking.scheduled_at);
        const dateStr = scheduledDate.toLocaleDateString("en-US", {
          weekday: "long",
          year: "numeric",
          month: "long",
          day: "numeric",
        });
        const timeStr = scheduledDate.toLocaleTimeString("en-US", {
          hour: "2-digit",
          minute: "2-digit",
          hour12: true,
        });

        // Create notification record
        await supabaseAdmin.from("notifications").insert({
          user_id: booking.customer_id,
          type: "appointment_reminder",
          title: `Appointment Reminder - ${hoursBefore} hour${hoursBefore > 1 ? "s" : ""} to go`,
          message: `Your appointment with ${provider.business_name} is in ${hoursBefore} hour${hoursBefore > 1 ? "s" : ""}. Date: ${dateStr} at ${timeStr}`,
          metadata: {
            booking_id: booking.id,
            reminder_key: reminderKey,
            hours_before: hoursBefore,
          },
          link: `/account-settings/bookings/${booking.id}`,
        });

        // Send push/email/SMS notification
        try {
          await sendTemplateNotification(
            "appointment_reminder",
            [booking.customer_id],
            {
              provider_name: provider.business_name,
              appointment_date: dateStr,
              appointment_time: timeStr,
              services: services,
              hours_before: hoursBefore.toString(),
              booking_number: booking.booking_number || "",
              booking_id: booking.id,
            },
            config.channels
          );

          remindersSent.push(booking.id);
        } catch (notifError) {
          console.error(`Error sending reminder for booking ${booking.id}:`, notifError);
        }
      }
    }

    return {
      success: true,
      remindersSent: remindersSent.length,
      totalBookings: remindersSent.length,
    };
  } catch (error) {
    console.error("Error sending appointment reminders:", error);
    throw error;
  }
}

/**
 * Send reminder for a specific booking (manual trigger)
 */
export async function sendBookingReminder(bookingId: string, hoursBefore: number) {
  const supabaseAdmin = getSupabaseAdmin();

  try {
    const { data: booking, error } = await supabaseAdmin
