      month: "long",
      day: "numeric",
    });
    const timeStr = scheduledDate.toLocaleTimeString("en-US", {
      hour: "2-digit",
      minute: "2-digit",
      hour12: true,
    });

    // Create notification
    await supabaseAdmin.from("notifications").insert({
      user_id: booking.customer_id,
      type: "appointment_reminder",
      title: `Appointment Reminder`,
      message: `Your appointment with ${provider.business_name} is coming up. Date: ${dateStr} at ${timeStr}`,
      metadata: {
        booking_id: booking.id,
        hours_before: hoursBefore,
      },
      link: `/account-settings/bookings/${booking.id}`,
    });

    // Send notification
    await sendTemplateNotification(
      "appointment_reminder",
      [booking.customer_id],
      {
        provider_name: provider.business_name,
        appointment_date: dateStr,
        appointment_time: timeStr,
        services: services,
        hours_before: hoursBefore.toString(),
        booking_number: booking.booking_number || "",
        booking_id: booking.id,
      },
      ["push", "email"]
    );

    return { success: true };
  } catch (error) {
    console.error("Error sending booking reminder:", error);
    throw error;
  }
}

/**
 * Cancellation Policy Logic
 * Checks if a booking can be cancelled based on policy rules
 */

export interface CancellationPolicy {
  id: string;
  provider_id: string;
  location_type: 'at_salon' | 'at_home' | null;
  hours_before_cutoff: number;
  grace_window_minutes: number;
  policy_text: string;
  late_cancellation_type: 'no_refund' | 'partial_refund' | 'full_refund';
  is_active: boolean;
}

export interface CancellationCheckResult {
  allowed: boolean;
  reason?: string;
  policy?: CancellationPolicy;
}

/**
 * Check if a booking can be cancelled based on policy
 */
export function canCancelBooking(
  booking: {
    id: string;
    created_at: string;
    scheduled_at: string;
    location_type: 'at_salon' | 'at_home';
  },
  policy: CancellationPolicy,
  currentTime: Date = new Date()
): CancellationCheckResult {
  const bookingCreatedAt = new Date(booking.created_at);
  const scheduledAt = new Date(booking.scheduled_at);

  // Check grace window: bookings created < grace_window_minutes ago can always be cancelled
  const graceWindowEnd = new Date(bookingCreatedAt.getTime() + policy.grace_window_minutes * 60000);
  if (currentTime <= graceWindowEnd) {
    return {
      allowed: true,
      policy,
    };
  }

  // Check hours-before cutoff
  const cutoffTime = new Date(scheduledAt.getTime() - policy.hours_before_cutoff * 60 * 60 * 1000);
  if (currentTime < cutoffTime) {
    return {
      allowed: true,
      policy,
    };
  }

  // Outside policy window
  return {
    allowed: false,
    reason: `Cancellations must be made at least ${policy.hours_before_cutoff} hours before the appointment. This booking can no longer be cancelled online.`,
    policy,
  };
}

/**
 * Get cancellation policy for a booking
 * Matches by provider_id and location_type (or NULL for both)
 */
export async function getCancellationPolicy(
  supabase: any,
  providerId: string,
  locationType: 'at_salon' | 'at_home'
): Promise<CancellationPolicy | null> {
  // First try to get location-specific policy
  const { data: locationPolicy } = await supabase
    .from('cancellation_policies')
    .select('*')
    .eq('provider_id', providerId)
    .eq('location_type', locationType)
    .eq('is_active', true)
    .maybeSingle();

  if (locationPolicy) {
    return locationPolicy as CancellationPolicy;
  }

  // Fall back to general policy (location_type IS NULL)
  const { data: generalPolicy } = await supabase
    .from('cancellation_policies')
    .select('*')
    .eq('provider_id', providerId)
    .is('location_type', null)
    .eq('is_active', true)
    .maybeSingle();

  if (generalPolicy) {
    return generalPolicy as CancellationPolicy;
  }

  // No policy found - return default
  return {
    id: '',
    provider_id: providerId,
    location_type: null,
    hours_before_cutoff: 24,
    grace_window_minutes: 15,
    policy_text: 'Cancellations must be made at least 24 hours before your appointment.',
    late_cancellation_type: 'no_refund',
    is_active: true,
  };
}

/**
 * Booking Conflict Detection
 * Checks for time overlaps before creating bookings
 */

import { SupabaseClient } from '@supabase/supabase-js';

export interface ConflictCheckResult {
  hasConflict: boolean;
  conflictingBookings?: Array<{
    booking_id: string;
    scheduled_start_at: string;
    scheduled_end_at: string;
  }>;
}

/**
 * Check if a booking time slot conflicts with existing bookings
 * Includes buffer time in the conflict check
 */
export async function checkBookingConflict(
  supabase: SupabaseClient,
  staffId: string,
  startAt: Date,
  endAt: Date,
  bufferMinutes: number = 15
): Promise<ConflictCheckResult> {
  // Calculate effective end time (including buffer)
  const effectiveEndAt = new Date(endAt.getTime() + bufferMinutes * 60000);

  // Query for overlapping bookings
  // We check if the new booking overlaps with any existing booking
  // Overlap occurs if: new_start < existing_end AND new_end > existing_start
  const { data: conflictingServices, error } = await supabase
    .from('booking_services')
    .select(`
      booking_id,
      scheduled_start_at,
      scheduled_end_at,
      bookings!inner (
        id,
        status
      ),
      offerings!inner (
        buffer_minutes
      )
    `)
    .eq('staff_id', staffId)
    .neq('bookings.status', 'cancelled')
    .lt('scheduled_start_at', effectiveEndAt.toISOString())
    .gt('scheduled_end_at', startAt.toISOString());

  if (error) {
    console.error('Error checking booking conflict:', error);
    // On error, assume conflict exists (fail-safe)
    return { hasConflict: true };
  }

  if (!conflictingServices || conflictingServices.length === 0) {
    return { hasConflict: false };
  }

  // Check if conflicts account for their own buffers
  // For each conflicting booking, add its buffer to the end time
  const actualConflicts = conflictingServices.filter((cs: any) => {
    const conflictStart = new Date(cs.scheduled_start_at);
    const conflictEnd = new Date(cs.scheduled_end_at);
    const conflictBuffer = cs.offerings?.buffer_minutes || 15;
    const conflictEffectiveEnd = new Date(conflictEnd.getTime() + conflictBuffer * 60000);

    // Check if there's actual overlap
    return startAt < conflictEffectiveEnd && effectiveEndAt > conflictStart;
  });

  if (actualConflicts.length === 0) {
    return { hasConflict: false };
  }

  return {
    hasConflict: true,
    conflictingBookings: actualConflicts.map((cs: any) => ({
      booking_id: cs.booking_id,
      scheduled_start_at: cs.scheduled_start_at,
      scheduled_end_at: cs.scheduled_end_at,
    })),
  };
}

/**
 * Lock booking services for a time range (for transaction)
 * Uses SELECT FOR UPDATE to prevent concurrent modifications
 * Returns a lock key that should be released after booking creation
 */
export async function lockBookingServices(
  supabase: SupabaseClient,
  staffId: string,
  startAt: Date,
  endAt: Date,
  bufferMinutes: number = 15
): Promise<{ hasConflict: boolean; conflictingBookings?: any[]; lockKey?: number }> {
  const effectiveEndAt = new Date(endAt.getTime() + bufferMinutes * 60000);

  // Generate a unique advisory lock key based on staff_id and time range
  // This ensures we can hold the lock across multiple operations
  const lockKey = generateAdvisoryLockKey(staffId, startAt, effectiveEndAt);

  // Acquire advisory lock (this will block other concurrent requests)
  // Note: Advisory locks are automatically released at transaction end
  // Since Supabase doesn't support transactions, we use a session-level lock
  const { data: _lockAcquired, error: lockError } = await supabase.rpc('acquire_booking_lock', {
    p_key: lockKey,
  });

  if (lockError) {
    // If advisory lock function doesn't exist, fall back to SELECT FOR UPDATE only
    console.warn('Advisory lock not available, using SELECT FOR UPDATE only');
  }

  // Use RPC function for SELECT FOR UPDATE (within the advisory lock)
  const { data: lockedRows, error } = await supabase.rpc('lock_booking_services_for_update', {
    p_staff_id: staffId,
    p_start_at: startAt.toISOString(),
    p_end_at: effectiveEndAt.toISOString(),
  });

  // If RPC doesn't exist, fall back to regular conflict check
  if (error && (error.message.includes('function') || error.message.includes('does not exist'))) {
    // Fallback to regular check
    return await checkBookingConflict(supabase, staffId, startAt, endAt, bufferMinutes);
  }

  if (error) {
    console.error('Error locking booking services:', error);
    throw error;
  }

  // If rows were returned, there's a conflict
  if (lockedRows && lockedRows.length > 0) {
    return {
      hasConflict: true,
      conflictingBookings: lockedRows,
      lockKey: lockKey,
    };
  }

  return { hasConflict: false, lockKey: lockKey };
}

/**
 * Generate a unique advisory lock key from staff_id and time range
 * Uses a hash function to create a consistent integer key
 */
function generateAdvisoryLockKey(staffId: string, startAt: Date, endAt: Date): number {
  // Create a hash from staff_id and time range
  // PostgreSQL advisory locks use bigint, but we'll use a 32-bit hash
  const hashString = `${staffId}-${startAt.getTime()}-${endAt.getTime()}`;
  let hash = 0;
  for (let i = 0; i < hashString.length; i++) {
    const char = hashString.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32-bit integer
  }
  // Use absolute value and ensure it's within PostgreSQL's bigint range
  return Math.abs(hash);
}

/**
 * Check if manual double booking override is allowed
 */
export async function canOverrideDoubleBooking(
  supabase: SupabaseClient,
  providerId: string
): Promise<boolean> {
  const { data: settings } = await supabase
    .from('provider_settings')
    .select('allow_double_booking_manual')
    .eq('provider_id', providerId)
    .single();

  return settings?.allow_double_booking_manual ?? false;
}

/**
 * Create a booking from a consumed hold
 * Used by /api/public/booking-holds/[id]/consume
 */

import { SupabaseClient } from "@supabase/supabase-js";
import { determineAppointmentStatusFromDB } from "@/lib/provider-portal/appointment-settings";
import { lockBookingServices } from "./conflict-check";

export interface HoldConsumeInput {
  holdId: string;
  customerId: string;
  clientInfo: {
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
    specialRequests?: string;
  };
  paymentMethod: "card" | "cash";
}

export interface CreateBookingFromHoldResult {
  bookingId: string;
  bookingNumber: string;
}

export async function createBookingFromHold(
  supabase: SupabaseClient,
  adminSupabase: SupabaseClient,
  hold: {
    id: string;
    provider_id: string;
    staff_id: string | null;
    booking_services_snapshot: any[];
    start_at: string;
    end_at: string;
    location_type: string;
    location_id: string | null;
    address_snapshot: any;
  },
  input: HoldConsumeInput
): Promise<CreateBookingFromHoldResult> {
  const services = hold.booking_services_snapshot as Array<{
    offering_id: string;
    staff_id: string | null;
    duration_minutes: number;
    price: number;
    currency: string;
    scheduled_start_at: string;
    scheduled_end_at: string;
  }>;

  if (!services.length) {
    throw new Error("Hold has no services");
  }

  const staffId = hold.staff_id ?? services[0]?.staff_id;
  if (!staffId) {
    throw new Error("Staff ID required for booking");
  }

  const currency = services[0]?.currency || "ZAR";
  const subtotal = services.reduce((sum, s) => sum + Number(s.price || 0), 0);

  // Load provider for tax/fee defaults
  const { data: provider, error: provErr } = await supabase
    .from("providers")
    .select("id, currency, tax_rate_percent, customer_fee_config_id, tips_enabled")
    .eq("id", hold.provider_id)
    .single();

  if (provErr || !provider) {
    throw new Error("Provider not found");
  }

  let taxRate = Number((provider as any)?.tax_rate_percent || 0);
  if (taxRate === 0) {
    const { getPlatformDefaultTaxRate } = await import("@/lib/platform-tax-settings");
    taxRate = await getPlatformDefaultTaxRate();
  }
  const taxAmount = taxRate > 0 ? Number(((subtotal * taxRate) / 100).toFixed(2)) : 0;

  let serviceFeeAmount = 0;
  let serviceFeePercentage = 0;
  if ((provider as any)?.customer_fee_config_id) {
    const { data: feeConfig } = await supabase
      .from("platform_fee_config")
      .select("id, fee_type, fee_percentage, fee_fixed_amount")
      .eq("id", (provider as any).customer_fee_config_id)
      .eq("is_active", true)
      .single();
    if (feeConfig) {
      if (feeConfig.fee_type === "percentage") {
        serviceFeePercentage = Number(feeConfig.fee_percentage || 0);
        serviceFeeAmount = Number(((subtotal * serviceFeePercentage) / 100).toFixed(2));
      } else {
        serviceFeeAmount = Number(feeConfig.fee_fixed_amount || 0);
      }
    }
  }

  const totalAmount = subtotal + taxAmount + serviceFeeAmount;
  const appointmentStatus = await determineAppointmentStatusFromDB(adminSupabase, hold.provider_id);

  const startAt = new Date(hold.start_at);
  const endAt = new Date(hold.end_at);

  // Re-check conflict before creating (slot may have been taken)
  const conflictResult = await lockBookingServices(
    supabase as any,
    staffId,
    startAt,
    endAt,
    15
  );
  if (conflictResult.hasConflict) {
    throw new Error("This time slot is no longer available. Please select another time.");
  }

  const bookingData: Record<string, any> = {
    customer_id: input.customerId,
    provider_id: hold.provider_id,
    status: appointmentStatus,
    location_type: hold.location_type,
    location_id: hold.location_id || null,
    scheduled_at: hold.start_at,
    subtotal,
    travel_fee: 0,
    service_fee_percentage: serviceFeePercentage,
    service_fee_amount: serviceFeeAmount,
    service_fee_paid_by: "customer",
    tip_amount: 0,
    tax_amount: taxAmount,
    discount_amount: 0,
    promotion_discount_amount: 0,
    membership_discount_amount: 0,
    total_amount: totalAmount,
    currency: currency,
    payment_status: input.paymentMethod === "cash" ? "pending" : "pending",
    special_requests: input.clientInfo.specialRequests || null,
    loyalty_points_earned: 0,
  };

  if (hold.location_type === "at_home" && hold.address_snapshot) {
    const addr = hold.address_snapshot as any;
    bookingData.address_line1 = addr.line1 || addr.address_line1;
    bookingData.address_line2 = addr.line2 || addr.address_line2 || null;
    bookingData.address_city = addr.city || addr.address_city;
    bookingData.address_state = addr.state || addr.address_state || null;
    bookingData.address_country = addr.country || addr.address_country;
    bookingData.address_postal_code = addr.postal_code || addr.postalCode || null;
    bookingData.address_latitude = addr.latitude ?? addr.lat ?? null;
    bookingData.address_longitude = addr.longitude ?? addr.lng ?? null;
  }

  const { data: bookingId, error: rpcError } = await adminSupabase.rpc("create_booking_with_locking", {
    p_booking_data: bookingData,
    p_booking_services: services,
    p_staff_id: staffId,
    p_start_at: hold.start_at,
    p_end_at: hold.end_at,
  });

  if (rpcError) {
    const msg = (rpcError as { message?: string }).message ?? "";
    if (msg.includes("BOOKING_SLOT_CONFLICT")) {
      throw new Error("This time slot is no longer available. Please select another time.");
    }
    throw rpcError;
  }
  if (!bookingId) throw new Error("Failed to create booking");

  const { data: booking } = await adminSupabase
    .from("bookings")
    .select("booking_number")
    .eq("id", bookingId)
    .single();

  return {
    bookingId,
    bookingNumber: (booking as any)?.booking_number || String(bookingId).slice(0, 8),
  };
}

/**
 * Group Booking Cancellation
 * Handle cancellation of group bookings (all participants or individual)
 */

import { SupabaseClient } from '@supabase/supabase-js';
import { getGroupBooking } from './group-booking';

/**
 * Cancel entire group booking (all participants)
 */
export async function cancelGroupBooking(
  supabase: SupabaseClient,
  groupBookingId: string,
  cancelledBy: string,
  reason?: string
): Promise<void> {
  const groupBooking = await getGroupBooking(supabase, groupBookingId);
  if (!groupBooking) {
    throw new Error('Group booking not found');
  }

  // Cancel all bookings in the group
  for (const booking of groupBooking.bookings) {
    await supabase
      .from('bookings')
      .update({
        status: 'cancelled',
        cancelled_at: new Date().toISOString(),
        cancelled_by: cancelledBy,
        cancellation_reason: reason || 'Group booking cancelled',
      })
      .eq('id', booking.id);
  }

  // Update group booking status
  await supabase
    .from('group_bookings')
    .update({
      status: 'cancelled',
      updated_at: new Date().toISOString(),
    })
    .eq('id', groupBookingId);
}

/**
 * Cancel individual participant from group booking
 */
export async function cancelGroupBookingParticipant(
  supabase: SupabaseClient,
  bookingId: string,
  participantId: string,
  cancelledBy: string,
  reason?: string
): Promise<void> {
  // Get participant details
  const { data: participant } = await supabase
    .from('booking_participants')
    .select('*, group_bookings(*)')
    .eq('booking_id', bookingId)
    .eq('id', participantId)
    .single();

  if (!participant) {
    throw new Error('Participant not found');
  }

  // Check if this is the primary contact
  if (participant.is_primary_contact) {
    // Primary contact cancellation cancels entire group
    const groupBooking = participant.group_bookings as any;
    if (groupBooking) {
      await cancelGroupBooking(supabase, groupBooking.id, cancelledBy, reason);
    }
  } else {
    // Remove participant's booking_services
    await supabase
      .from('booking_services')
      .delete()
      .eq('booking_id', bookingId)
      .eq('participant_id', participantId);

    // Remove participant record
    await supabase
      .from('booking_participants')
      .delete()
      .eq('id', participantId);

    // If this was the last participant, cancel the booking
    const { data: remainingParticipants } = await supabase
      .from('booking_participants')
      .select('id')
      .eq('booking_id', bookingId);

    if (!remainingParticipants || remainingParticipants.length === 0) {
      await supabase
        .from('bookings')
        .update({
          status: 'cancelled',
          cancelled_at: new Date().toISOString(),
          cancelled_by: cancelledBy,
          cancellation_reason: reason || 'All participants removed',
        })
        .eq('id', bookingId);
    }
  }
}

/**
 * Get group booking participants for cancellation notifications
 */
export async function getGroupBookingParticipantsForCancellation(
  supabase: SupabaseClient,
  groupBookingId: string
): Promise<Array<{
  participant_name: string;
  participant_email: string | null;
  participant_phone: string | null;
}>> {
  const groupBooking = await getGroupBooking(supabase, groupBookingId);
  if (!groupBooking) {
    return [];
  }

  return groupBooking.participants.map(p => ({
    participant_name: p.participant_name,
    participant_email: p.participant_email,
    participant_phone: p.participant_phone,
  }));
}

/**
 * Group Booking Notifications
 * Send notifications to all participants in a group booking
 */

import { SupabaseClient } from '@supabase/supabase-js';
import { getGroupBooking } from './group-booking';

/**
 * Send booking confirmation to all group participants
 */
export async function sendGroupBookingNotifications(
  supabase: SupabaseClient,
  bookingId: string,
  groupBookingId?: string
): Promise<void> {
  // Get group booking details
  let participants: Array<{
    participant_name: string;
    participant_email: string | null;
    participant_phone: string | null;
    is_primary_contact: boolean;
  }> = [];

  if (groupBookingId) {
    const groupBooking = await getGroupBooking(supabase, groupBookingId);
    if (groupBooking) {
      participants = groupBooking.participants.map(p => ({
        participant_name: p.participant_name,
        participant_email: p.participant_email,
        participant_phone: p.participant_phone,
        is_primary_contact: p.is_primary_contact,
      }));
    }
  } else {
    // Fallback: get participants from booking_participants table
    const { data: bookingParticipants } = await supabase
      .from('booking_participants')
      .select('participant_name, participant_email, participant_phone, is_primary_contact')
      .eq('booking_id', bookingId);

    if (bookingParticipants) {
      participants = bookingParticipants;
    }
  }

  // Get booking details
  const { data: booking } = await supabase
    .from('bookings')
    .select('id, booking_number, scheduled_at, provider_id, location_type')
    .eq('id', bookingId)
    .single();

  if (!booking) return;

  // Get provider details
  const { data: provider } = await supabase
    .from('providers')
    .select('business_name, slug')
    .eq('id', booking.provider_id)
    .single();

  // Send notifications to all participants
  for (const participant of participants) {
    if (participant.participant_email) {
      await sendGroupBookingEmail(
        participant.participant_email,
        participant.participant_name,
        booking,
        provider,
        participant.is_primary_contact
      );
    }

    if (participant.participant_phone) {
      await sendGroupBookingSMS(
        participant.participant_phone,
        participant.participant_name,
        booking,
        provider,
        participant.is_primary_contact
      );
    }
  }
}

/**
 * Send email notification to group participant
 */
async function sendGroupBookingEmail(
  email: string,
  name: string,
  booking: any,
  provider: any,
  isPrimary: boolean
): Promise<void> {
  const scheduledDate = new Date(booking.scheduled_at);
  const dateStr = scheduledDate.toLocaleDateString('en-US', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });
  const timeStr = scheduledDate.toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
  });

  const subject = isPrimary
    ? `Group Booking Confirmation - ${booking.booking_number}`
    : `You're Invited to a Group Booking - ${booking.booking_number}`;

  const body = `
Hi ${name},

${isPrimary 
  ? `Your group booking has been confirmed!`
  : `You've been added to a group booking!`}

Booking Details:
- Booking Number: ${booking.booking_number}
- Date & Time: ${dateStr} at ${timeStr}
- Provider: ${provider?.business_name || 'Beautonomi Partner'}
- Location: ${booking.location_type === 'at_salon' ? 'At Salon' : 'At Home'}

${isPrimary
  ? 'As the primary contact, you are responsible for this booking. All participants will receive their own confirmation.'
  : 'The primary contact will handle payment and coordination for this group booking.'}

View your booking:
${process.env.NEXT_PUBLIC_APP_URL || 'https://beautonomi.com'}/account-settings/bookings

Best regards,
Beautonomi Team
  `.trim();

  try {
    await fetch('/api/notifications/send-email', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        to: email,
        subject,
        body,
        type: 'group_booking_confirmation',
      }),
    });
  } catch (error) {
    console.warn('Email notification endpoint not available:', error);
  }
}

/**
 * Send SMS notification to group participant
 */
async function sendGroupBookingSMS(
  phone: string,
  name: string,
  booking: any,
  provider: any,
  isPrimary: boolean
): Promise<void> {
  const scheduledDate = new Date(booking.scheduled_at);
  const dateStr = scheduledDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  const timeStr = scheduledDate.toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
  });

  const message = isPrimary
    ? `Hi ${name}! Your group booking ${booking.booking_number} is confirmed for ${dateStr} at ${timeStr}. View: ${process.env.NEXT_PUBLIC_APP_URL || 'https://beautonomi.com'}/account-settings/bookings`
    : `Hi ${name}! You're added to group booking ${booking.booking_number} on ${dateStr} at ${timeStr}. View: ${process.env.NEXT_PUBLIC_APP_URL || 'https://beautonomi.com'}/account-settings/bookings`;

  try {
    await fetch('/api/notifications/send-sms', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        to: phone,
        message,
        type: 'group_booking_confirmation',
      }),
    });
  } catch (error) {
    console.warn('SMS notification endpoint not available:', error);
  }
}

/**
 * Group Booking Utilities
 * Functions for managing group bookings and linking individual bookings
 */

import { SupabaseClient } from '@supabase/supabase-js';

export interface GroupBooking {
  id: string;
  provider_id: string;
  primary_contact_booking_id: string | null;
  ref_number: string;
  scheduled_at: string;
  status: 'pending' | 'confirmed' | 'cancelled' | 'completed';
  created_at: string;
  updated_at: string;
}

export interface BookingParticipant {
  id: string;
  booking_id: string;
  group_booking_id: string;
  participant_name: string;
  participant_email: string | null;
  participant_phone: string | null;
  is_primary_contact: boolean;
  created_at: string;
  updated_at: string;
}

/**
 * Create a group booking and link individual bookings
 */
export async function createGroupBooking(
  supabase: SupabaseClient,
  providerId: string,
  primaryBookingId: string,
  bookingIds: string[],
  participants: Array<{
    booking_id: string;
    participant_name: string;
    participant_email?: string;
    participant_phone?: string;
    is_primary_contact?: boolean;
  }>
): Promise<GroupBooking> {
  // Get scheduled_at from primary booking
  const { data: primaryBooking, error: bookingError } = await supabase
    .from('bookings')
    .select('scheduled_at')
    .eq('id', primaryBookingId)
    .single();

  if (bookingError || !primaryBooking) {
    throw new Error('Primary booking not found');
  }

  // Generate reference number
  const { data: refNumber, error: refError } = await supabase.rpc('generate_group_booking_ref');

  if (refError) {
    // Fallback if RPC doesn't exist
    const fallbackRef = `GB-${Date.now().toString().slice(-10)}`;
    
    // Create group booking
    const { data: groupBooking, error: createError } = await supabase
      .from('group_bookings')
      .insert({
        provider_id: providerId,
        primary_contact_booking_id: primaryBookingId,
        ref_number: fallbackRef,
        scheduled_at: primaryBooking.scheduled_at,
        status: 'confirmed',
      })
      .select()
      .single();

    if (createError) {
      throw createError;
    }

    // Link participants
    await linkBookingsToGroup(supabase, groupBooking.id, participants);

    return groupBooking as GroupBooking;
  }

  // Create group booking with generated ref
  const { data: groupBooking, error: createError } = await supabase
    .from('group_bookings')
    .insert({
      provider_id: providerId,
      primary_contact_booking_id: primaryBookingId,
      ref_number: refNumber as string,
      scheduled_at: primaryBooking.scheduled_at,
      status: 'confirmed',
    })
    .select()
    .single();

  if (createError) {
    throw createError;
  }

  // Link participants
  await linkBookingsToGroup(supabase, groupBooking.id, participants);

  return groupBooking as GroupBooking;
}

/**
 * Link bookings to a group booking
 */
export async function linkBookingsToGroup(
  supabase: SupabaseClient,
  groupBookingId: string,
  participants: Array<{
    booking_id: string;
    participant_name: string;
    participant_email?: string;
    participant_phone?: string;
    is_primary_contact?: boolean;
  }>
): Promise<void> {
  const participantRecords = participants.map((p) => ({
    booking_id: p.booking_id,
    group_booking_id: groupBookingId,
    participant_name: p.participant_name,
    participant_email: p.participant_email || null,
    participant_phone: p.participant_phone || null,
    is_primary_contact: p.is_primary_contact || false,
  }));

  const { error } = await supabase
    .from('booking_participants')
    .insert(participantRecords);

  if (error) {
    throw error;
  }
}

/**
 * Get group booking with all linked bookings
 */
export async function getGroupBooking(
  supabase: SupabaseClient,
  groupBookingId: string
): Promise<GroupBooking & { bookings: any[]; participants: BookingParticipant[] } | null> {
  const { data: groupBooking, error } = await supabase
    .from('group_bookings')
    .select(`
      *,
      booking_participants (
        *,
        bookings (*)
      )
    `)
    .eq('id', groupBookingId)
    .single();

  if (error || !groupBooking) {
    return null;
  }

  const participants = (groupBooking.booking_participants || []) as BookingParticipant[];
  const bookings = participants.map((p: any) => p.bookings).filter(Boolean);

  return {
    ...(groupBooking as GroupBooking),
    bookings,
    participants,
  };
}

/**
 * Check if user is primary contact for a group booking
 */
export async function isPrimaryContact(
  supabase: SupabaseClient,
  userId: string,
  groupBookingId: string
): Promise<boolean> {
  const { data, error } = await supabase
    .from('group_bookings')
    .select(`
      primary_contact_booking_id,
      bookings!primary_contact_booking_id (
        customer_id
      )
    `)
    .eq('id', groupBookingId)
    .single();

  if (error || !data) {
    return false;
  }

  const primaryBooking = data.bookings as any;
  return primaryBooking?.customer_id === userId;
}

/**
 * Reschedule entire group booking
 * Only primary contact can do this
 */
export async function rescheduleGroupBooking(
  supabase: SupabaseClient,
  groupBookingId: string,
  newScheduledAt: Date
): Promise<void> {
  // Get all bookings in the group
  const { data: participants, error: participantsError } = await supabase
    .from('booking_participants')
    .select('booking_id, bookings!inner(scheduled_at, booking_services(*))')
    .eq('group_booking_id', groupBookingId);

  if (participantsError || !participants) {
    throw new Error('Failed to load group booking participants');
  }

  // Calculate time offset from original scheduled time
  const groupBooking = await getGroupBooking(supabase, groupBookingId);
  if (!groupBooking) {
    throw new Error('Group booking not found');
  }

  const originalScheduledAt = new Date(groupBooking.scheduled_at);
  const timeOffset = newScheduledAt.getTime() - originalScheduledAt.getTime();

  // Update each booking's scheduled_at
  for (const participant of participants) {
    const booking = (participant as any).bookings;
    if (!booking) continue;

    const originalBookingTime = new Date(booking.scheduled_at);
    const newBookingTime = new Date(originalBookingTime.getTime() + timeOffset);

    // Update booking
    await supabase
      .from('bookings')
      .update({
        scheduled_at: newBookingTime.toISOString(),
      })
      .eq('id', booking.id);

    // Update booking_services
    const services = booking.booking_services || [];
    for (const service of services) {
      const originalStart = new Date(service.scheduled_start_at);
      const originalEnd = new Date(service.scheduled_end_at);
      const duration = originalEnd.getTime() - originalStart.getTime();

      const newStart = new Date(originalStart.getTime() + timeOffset);
      const newEnd = new Date(newStart.getTime() + duration);

      await supabase
        .from('booking_services')
        .update({
          scheduled_start_at: newStart.toISOString(),
          scheduled_end_at: newEnd.toISOString(),
        })
        .eq('id', service.id);
    }
  }

  // Update group booking scheduled_at
  await supabase
    .from('group_bookings')
    .update({
      scheduled_at: newScheduledAt.toISOString(),
    })
    .eq('id', groupBookingId);
}

/**
 * Refund Processing Logic
 * Handles refunds for cancelled bookings based on cancellation policy
 */

import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { createRefund, convertToSmallestUnit } from "@/lib/payments/paystack-complete";
import type { CancellationPolicy } from "./cancellation-policy";

export interface RefundResult {
  success: boolean;
  refundId?: string;
  amount?: number;
  error?: string;
}

/**
 * Process refund for a cancelled booking
 */
export async function processBookingRefund(
  bookingId: string,
  bookingTotal: number,
  currency: string,
  policy: CancellationPolicy,
  paymentReference?: string
): Promise<RefundResult> {
  const supabaseAdmin = getSupabaseAdmin();

  try {
    // Determine refund amount based on policy
    let refundAmount = 0;
    let _refundType: 'full' | 'partial' | 'none' = 'none';

    if (policy.late_cancellation_type === 'full_refund') {
      refundAmount = bookingTotal;
      _refundType = 'full';
    } else if (policy.late_cancellation_type === 'partial_refund') {
      // Calculate partial refund (e.g., 50% or based on policy)
      // For now, default to 50% - can be made configurable
      refundAmount = bookingTotal * 0.5;
      _refundType = 'partial';
    } else {
      // No refund
      return {
        success: true,
        amount: 0,
      };
    }

    if (refundAmount <= 0) {
      return {
        success: true,
        amount: 0,
      };
    }

    // If no payment reference, check for payment records
    if (!paymentReference) {
      const { data: payments } = await supabaseAdmin
        .from("booking_payments")
        .select("reference, amount, payment_provider")
        .eq("booking_id", bookingId)
        .eq("status", "completed")
        .order("created_at", { ascending: false })
        .limit(1);

      if (payments && payments.length > 0) {
        const payment = payments[0];
        if (payment.payment_provider === 'paystack' && payment.reference) {
          paymentReference = payment.reference;
        }
      }
    }

    // If we have a Paystack payment reference, process refund via Paystack
    if (paymentReference) {
      try {
        const amountInSmallestUnit = convertToSmallestUnit(refundAmount);
        const refundResponse = await createRefund({
          transaction: paymentReference,
          amount: amountInSmallestUnit,
          currency: currency,
          customer_note: `Refund for cancelled booking ${bookingId}`,
          merchant_note: `Cancellation refund - Policy: ${policy.late_cancellation_type}`,
        });

        if (refundResponse.status && refundResponse.data) {
          // Create refund record
          const { data: refundRecord, error: refundError } = await supabaseAdmin
            .from("booking_refunds")
            .insert({
              booking_id: bookingId,
              amount: refundAmount,
              reason: `Cancellation refund - ${policy.late_cancellation_type}`,
              refund_method: 'original',
              refund_provider_id: refundResponse.data.id?.toString(),
              status: refundResponse.data.status === 'success' ? 'completed' : 'pending',
              notes: `Processed via Paystack. Refund ID: ${refundResponse.data.id}`,
            })
            .select()
            .single();

          if (refundError) {
            console.error("Error creating refund record:", refundError);
            // Continue even if record creation fails
          }

          return {
            success: refundResponse.status,
            refundId: refundRecord?.id || refundResponse.data.id?.toString(),
            amount: refundAmount,
          };
        }
      } catch (paystackError: any) {
        console.error("Paystack refund error:", paystackError);
        // Fall through to manual refund record
      }
    }

    // If Paystack refund failed or no payment reference, create manual refund record
    // (for cash payments or when Paystack refund is not possible)
    const { data: refundRecord, error: refundError } = await supabaseAdmin
      .from("booking_refunds")
      .insert({
        booking_id: bookingId,
        amount: refundAmount,
        reason: `Cancellation refund - ${policy.late_cancellation_type}`,
        refund_method: 'original',
        status: 'pending', // Manual processing required
        notes: `Manual refund processing required. Policy: ${policy.late_cancellation_type}`,
      })
      .select()
      .single();

    if (refundError) {
      throw refundError;
    }

    return {
      success: true,
      refundId: refundRecord.id,
      amount: refundAmount,
    };
  } catch (error: any) {
    console.error("Error processing refund:", error);
    return {
      success: false,
      error: error.message || "Failed to process refund",
    };
  }
}

import { getSupabaseServer } from '@/lib/supabase/server';
import type { RealtimeChannel } from '@supabase/supabase-js';

export interface Message {
  id: string;
  conversation_id: string;
  sender_id: string;
  content: string;
  created_at: string;
  read_at?: string;
  message_type?: 'text' | 'image' | 'file';
  metadata?: Record<string, any>;
}

export interface Conversation {
  id: string;
  participant_ids: string[];
  last_message_id?: string;
  last_message_at?: string;
  created_at: string;
  updated_at: string;
  booking_id?: string;
  metadata?: Record<string, any>;
}

export interface ConversationParticipant {
  id: string;
  conversation_id: string;
  user_id: string;
  last_read_at?: string;
  created_at: string;
}

/**
 * Get or create a conversation between two users
 */
export async function getOrCreateConversation(
  userId1: string,
  userId2: string,
  bookingId?: string
): Promise<Conversation> {
  const supabase = await getSupabaseServer();

  // Check if conversation already exists
  const { data: existing, error: findError } = await supabase
    .from('conversations')
    .select('*, conversation_participants(*)')
    .contains('participant_ids', [userId1, userId2])
    .maybeSingle();

  if (findError && findError.code !== 'PGRST116') {
    throw new Error(`Failed to find conversation: ${findError.message}`);
  }

  if (existing) {
    return existing as Conversation;
  }

  // Create new conversation
  const { data: newConversation, error: createError } = await supabase
    .from('conversations')
    .insert({
      participant_ids: [userId1, userId2],
      booking_id: bookingId,
    })
    .select()
    .single();

  if (createError) {
    throw new Error(`Failed to create conversation: ${createError.message}`);
  }

  // Create participants
  await Promise.all([
    supabase.from('conversation_participants').insert({
      conversation_id: newConversation.id,
      user_id: userId1,
    }),
    supabase.from('conversation_participants').insert({
      conversation_id: newConversation.id,
      user_id: userId2,
    }),
  ]);

  return newConversation as Conversation;
}

/**
 * Send a message in a conversation
 */
export async function sendMessage(
  conversationId: string,
  senderId: string,
  content: string,
  messageType: 'text' | 'image' | 'file' = 'text',
  metadata?: Record<string, any>
): Promise<Message> {
  const supabase = await getSupabaseServer();

  const { data: message, error } = await supabase
    .from('messages')
    .insert({
      conversation_id: conversationId,
      sender_id: senderId,
      content,
      message_type: messageType,
      metadata,
    })
    .select()
    .single();

  if (error) {
    throw new Error(`Failed to send message: ${error.message}`);
  }

  // Update conversation's last message
  await supabase
    .from('conversations')
    .update({
      last_message_id: message.id,
      last_message_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    })
    .eq('id', conversationId);

  return message as Message;
}

/**
 * Get messages for a conversation
 */
export async function getMessages(
  conversationId: string,
  limit: number = 50,
  before?: string
): Promise<Message[]> {
  const supabase = await getSupabaseServer();

  let query = supabase
    .from('messages')
    .select('*')
    .eq('conversation_id', conversationId)
    .order('created_at', { ascending: false })
    .limit(limit);

  if (before) {
    query = query.lt('created_at', before);
  }

  const { data, error } = await query;

  if (error) {
    throw new Error(`Failed to get messages: ${error.message}`);
  }

  return (data || []).reverse() as Message[];
}

/**
 * Get conversations for a user
 */
export async function getUserConversations(userId: string): Promise<Conversation[]> {
  const supabase = await getSupabaseServer();

  const { data, error } = await supabase
    .from('conversation_participants')
    .select('conversation_id, conversations(*)')
    .eq('user_id', userId);

  if (error) {
    throw new Error(`Failed to get conversations: ${error.message}`);
  }

  return (data || []).map((item: any) => item.conversations).filter(Boolean) as Conversation[];
}

/**
 * Mark messages as read
 */
export async function markMessagesAsRead(
  conversationId: string,
  userId: string
): Promise<void> {
  const supabase = await getSupabaseServer();

  // Update participant's last_read_at
  await supabase
    .from('conversation_participants')
    .update({ last_read_at: new Date().toISOString() })
    .eq('conversation_id', conversationId)
    .eq('user_id', userId);

  // Mark unread messages as read
  const { data: unreadMessages } = await supabase
    .from('messages')
    .select('id')
    .eq('conversation_id', conversationId)
    .neq('sender_id', userId)
    .is('read_at', null);

  if (unreadMessages && unreadMessages.length > 0) {
    await supabase
      .from('messages')
      .update({ read_at: new Date().toISOString() })
      .in('id', unreadMessages.map((m) => m.id));
  }
}

/**
 * Subscribe to new messages in a conversation
 */
export function subscribeToMessages(
  _conversationId: string,
  _callback: (message: Message) => void
): RealtimeChannel {
  // This would be used on the client side with Supabase client
  // For server-side, we'd use webhooks or polling
  throw new Error('subscribeToMessages should be used on client side with Supabase client');
}

"use client";

import { useEffect, useState } from "react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";

export interface PageContentItem {
  id: string;
  page_slug: string;
  section_key: string;
  content_type: "text" | "html" | "json" | "image" | "video";
  content: string;
  metadata?: Record<string, any>;
  order: number;
  is_active: boolean;
}

export type PageContent = Record<string, PageContentItem[]>;

/**
 * Hook to fetch and use page content from CMS
 * 
 * @param pageSlug - The slug of the page (e.g., "home", "about", "help")
 * @returns Object with content, loading state, and error
 */
export function usePageContent(pageSlug: string) {
  const [content, setContent] = useState<PageContent | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadContent = async () => {
      try {
        setIsLoading(true);
        setError(null);
        const response = await fetcher.get<{
          data: PageContent;
          error: null;
        }>(`/api/public/pages/${pageSlug}`);
        setContent(response.data || {});
      } catch (err) {
        const errorMessage =
          err instanceof FetchTimeoutError
            ? "Request timed out. Please try again."
            : err instanceof FetchError
            ? err.message
            : "Failed to load page content";
        setError(errorMessage);
        console.error("Error loading page content:", err);
      } finally {
        setIsLoading(false);
      }
    };

    if (pageSlug) {
      loadContent();
    }
  }, [pageSlug]);

  /**
   * Get content for a specific section
   */
  const getSection = (sectionKey: string): PageContentItem | null => {
    if (!content || !content[sectionKey] || content[sectionKey].length === 0) {
      return null;
    }
    // Return the first item (or highest order if sorted)
    return content[sectionKey][0];
  };

  /**
   * Get all content items for a specific section
   */
  const getSectionAll = (sectionKey: string): PageContentItem[] => {
    if (!content || !content[sectionKey]) {
      return [];
    }
    return content[sectionKey];
  };

  /**
   * Get content value for a section (returns the content string)
   */
  const getSectionContent = (sectionKey: string, defaultValue: string = ""): string => {
    const item = getSection(sectionKey);
    return item?.content || defaultValue;
  };

  return {
    content,
    isLoading,
    error,
    getSection,
    getSectionAll,
    getSectionContent,
  };
}

