/**
 * Feature Flags Utility
 * Functions to check if features are enabled
 */

export interface FeatureFlag {
  id: string;
  feature_key: string;
  feature_name: string;
  description: string | null;
  enabled: boolean;
  category: string | null;
  metadata: Record<string, any>;
