    cancellation_reason: null,
    services: [],
    addons: [],
    package_id: null,
    subtotal: 100,
    tip_amount: 0,
    total_amount: 100,
    currency: "ZAR",
    payment_status: "pending",
    payment_method: null,
    special_requests: null,
    loyalty_points_earned: 0,
