}

describe("getOperationalBadge", () => {
  it("returns cancelled for cancelled bookings", () => {
    const b = baseBooking({ status: "cancelled" });
    expect(getOperationalBadge(b)).toBe("cancelled");
  });

  it("returns completed for completed and fully paid bookings", () => {
    const b = baseBooking({ status: "completed", payment_status: "paid", total_paid: 100, total_amount: 100 } as any);
    expect(getOperationalBadge(b)).toBe("completed");
  });

  it("returns ready_to_pay for completed but unpaid bookings", () => {
    const b = baseBooking({ status: "completed", payment_status: "pending", total_paid: 0, total_amount: 100 } as any);
    expect(getOperationalBadge(b)).toBe("ready_to_pay");
  });

  it("returns in_service for in_progress bookings", () => {
    const b = baseBooking({
      status: "in_progress",
      current_stage: "service_started",
    } as any);
    expect(getOperationalBadge(b)).toBe("in_service");
  });

  it("returns checked_in when client_arrived (at-salon)", () => {
    const b = baseBooking({
      status: "confirmed",
      current_stage: "client_arrived",
      location_type: "at_salon",
    } as any);
    expect(getOperationalBadge(b)).toBe("checked_in");
  });

  it("returns late when start time passed by >10 min and still confirmed", () => {
    const past = new Date();
    past.setMinutes(past.getMinutes() - 15);
    const b = baseBooking({
      status: "confirmed",
      scheduled_at: past.toISOString(),
    });
    expect(getOperationalBadge(b)).toBe("late");
  });

  it("returns arriving when within 30 min of start", () => {
    const soon = new Date();
    soon.setMinutes(soon.getMinutes() + 20);
    const b = baseBooking({
      status: "confirmed",
      scheduled_at: soon.toISOString(),
    });
    expect(getOperationalBadge(b)).toBe("arriving");
  });

  it("returns ready_to_pay when service completed but payment pending", () => {
    const b = baseBooking({
      status: "in_progress",
      current_stage: "service_completed",
      payment_status: "pending",
      total_amount: 100,
      total_paid: 0,
    } as any);
    expect(getOperationalBadge(b)).toBe("ready_to_pay");
  });

  it("returns confirmed for future confirmed booking", () => {
    const future = new Date();
    future.setHours(future.getHours() + 2);
    const b = baseBooking({
      status: "confirmed",
      scheduled_at: future.toISOString(),
    });
    expect(getOperationalBadge(b)).toBe("confirmed");
  });
});

describe("matchesQueueTab", () => {
  it("all tab matches any booking", () => {
    const b = baseBooking({ status: "cancelled" });
    expect(matchesQueueTab(b, "all")).toBe(true);
  });

  it("arrivals tab matches late, arriving, checked_in", () => {
    const late = baseBooking({
      status: "confirmed",
      scheduled_at: new Date(Date.now() - 15 * 60 * 1000).toISOString(),
    });
    expect(matchesQueueTab(late, "arrivals")).toBe(true);

    const checked = baseBooking({
      status: "confirmed",
      current_stage: "client_arrived",
      location_type: "at_salon",
    } as any);
    expect(matchesQueueTab(checked, "arrivals")).toBe(true);
  });

  it("in_service tab matches only in_service", () => {
    const inSvc = baseBooking({
      status: "in_progress",
      current_stage: "service_started",
    } as any);
    expect(matchesQueueTab(inSvc, "in_service")).toBe(true);
    expect(matchesQueueTab(baseBooking({ status: "confirmed" }), "in_service")).toBe(false);
  });

  it("completed tab matches completed and cancelled", () => {
    expect(matchesQueueTab(baseBooking({ status: "completed", payment_status: "paid", total_paid: 100, total_amount: 100 } as any), "completed")).toBe(true);
    expect(matchesQueueTab(baseBooking({ status: "cancelled" }), "completed")).toBe(true);
  });
});

describe("getQueueCounts", () => {
  it("counts correctly for mixed bookings", () => {
    const bookings = [
      baseBooking({ status: "confirmed", id: "1" }),
      baseBooking({ status: "cancelled", id: "2" }),
      baseBooking({
        status: "in_progress",
        current_stage: "service_started",
        id: "3",
      } as any),
    ];
    const counts = getQueueCounts(bookings);
    expect(counts.all).toBe(3);
    expect(counts.completed).toBe(1);
    expect(counts.in_service).toBe(1);
  });
});

/**
 * Operational State Logic for Front Desk
 * Derives display badges from booking status, current_stage, and time.
 */

import type { Booking } from "@/types/beautonomi";
import type { OperationalBadge } from "./types";

const LATE_THRESHOLD_MINUTES = 10;
const ARRIVING_WINDOW_MINUTES = 30;

/**
 * Get the operational badge for a booking.
 * Used for queue tabs and tile display.
 */
export function getOperationalBadge(booking: Booking): OperationalBadge {
  const status = (booking as any).status as string;
  const currentStage = (booking as any).current_stage as string | undefined;
  const scheduledAt = booking.scheduled_at;
  const now = new Date();
  const scheduled = new Date(scheduledAt);
  const minutesPastStart = (now.getTime() - scheduled.getTime()) / (60 * 1000);
  const minutesUntilStart = (scheduled.getTime() - now.getTime()) / (60 * 1000);
  const locationType = (booking as any).location_type as string | undefined;
  const paymentStatus = (booking as any).payment_status as string | undefined;
  const totalPaid = (booking as any).total_paid as number | undefined;
  const totalAmount = (booking as any).total_amount as number | undefined;

  // Terminal states
  if (status === "cancelled" || status === "no_show") return "cancelled";
  if (status === "completed") {
    const fullyPaid = paymentStatus === "paid" || (totalPaid != null && totalAmount != null && totalPaid >= totalAmount);
    return fullyPaid ? "completed" : "ready_to_pay";
  }

  // In service
  if (status === "in_progress" || currentStage === "service_started") {
    // Service done (current_stage service_completed) but not marked completed - could be ready to pay
    if (currentStage === "service_completed") {
      const fullyPaid = paymentStatus === "paid" || (totalPaid != null && totalAmount != null && totalPaid >= totalAmount);
      return fullyPaid ? "completed" : "ready_to_pay";
    }
    return "in_service";
  }

  // Ready to pay: completed status in DB but we already handled completed above.
  // Alternative: status confirmed/in_progress and service_completed stage but payment pending
  if (currentStage === "service_completed" && paymentStatus !== "paid") {
    return "ready_to_pay";
  }

  // Checked in / arrived
  if (currentStage === "client_arrived" && locationType !== "at_home") {
    return "checked_in";
  }
  if (currentStage === "provider_arrived" && locationType === "at_home") {
    return "checked_in";
  }

  // Upcoming: confirmed/pending
  if (minutesPastStart > LATE_THRESHOLD_MINUTES) {
    return "late";
  }
  if (minutesUntilStart <= ARRIVING_WINDOW_MINUTES && minutesUntilStart >= 0) {
    return "arriving";
  }
  if (minutesUntilStart < 0 && minutesPastStart <= LATE_THRESHOLD_MINUTES) {
    return "arriving"; // Just started, within grace
  }

  return "confirmed";
}

/**
 * Check if a booking belongs to a given queue tab.
 */
export function matchesQueueTab(
  booking: Booking,
  tabId: string
): boolean {
  const badge = getOperationalBadge(booking);

  switch (tabId) {
    case "all":
      return true;
    case "arrivals":
      return ["late", "arriving", "checked_in"].includes(badge);
    case "in_service":
      return badge === "in_service";
    case "ready_to_pay":
      return badge === "ready_to_pay";
    case "completed":
      return badge === "completed" || badge === "cancelled";
    default:
      return true;
  }
}

/**
 * Count bookings per queue for badge display.
 */
export function getQueueCounts(
  bookings: Booking[]
): Record<string, number> {
  const counts: Record<string, number> = {
    all: bookings.length,
    arrivals: 0,
    in_service: 0,
    ready_to_pay: 0,
    completed: 0,
  };

  for (const b of bookings) {
    const badge = getOperationalBadge(b);
    if (["late", "arriving", "checked_in"].includes(badge)) counts.arrivals++;
    else if (badge === "in_service") counts.in_service++;
    else if (badge === "ready_to_pay") counts.ready_to_pay++;
    else if (badge === "completed" || badge === "cancelled") counts.completed++;
  }

  return counts;
}

/**
 * Front Desk Data Hook
 * Reuses fetcher + ProviderPortalProvider patterns.
 */

import { useState, useEffect, useCallback } from "react";
import { fetcher, FetchError, FetchTimeoutError } from "@/lib/http/fetcher";
import type { Booking } from "@/types/beautonomi";
import { getOperationalBadge } from "./operationalState";
import type { FrontDeskBooking } from "./types";

export interface UseFrontDeskDataInput {
  date: Date;
  locationId?: string | null;
  staffId?: string | null;
  query?: string;
}

export interface UseFrontDeskDataOutput {
  bookings: FrontDeskBooking[];
  staff: Array<{ id: string; name: string }>;
  locations: Array<{ id: string; name: string }>;
  services: Array<{ id: string; name: string; duration_minutes?: number; price?: number }>;
  loading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
}

/** Fetch staff from provider API (locations are from ProviderPortal) */
async function fetchStaff(locationId?: string | null): Promise<Array<{ id: string; name: string }>> {
  try {
    const { providerApi } = await import("@/lib/provider-portal/api");
    const members = await providerApi.listTeamMembers(locationId || undefined);
    return (members || []).map((m) => ({ id: m.id, name: m.name }));
  } catch {
    return [];
  }
}

/** Fetch locations from provider API */
async function fetchLocations(): Promise<Array<{ id: string; name: string }>> {
  try {
    const res = await fetcher.get<{ data: Array<{ id: string; name: string }> }>(
      "/api/provider/locations"
    );
    const data = (res as any)?.data ?? res;
    const arr = Array.isArray(data) ? data : [];
    return arr.map((l: any) => ({ id: l.id, name: l.name || l.address_line1 || "Location" }));
  } catch {
    return [];
  }
}

async function fetchServices(): Promise<Array<{ id: string; name: string; duration_minutes?: number; price?: number }>> {
  try {
    const { providerApi } = await import("@/lib/provider-portal/api");
    const svcs = await providerApi.listServices();
    return (svcs || []).map((s: any) => ({
      id: s.id,
      name: s.title || s.name || "Service",
      duration_minutes: s.duration_minutes || 60,
      price: s.price || 0,
    }));
  } catch {
    return [];
  }
}

export function useFrontDeskData(input: UseFrontDeskDataInput): UseFrontDeskDataOutput {
  const { date, locationId, query } = input;
  const [bookings, setBookings] = useState<FrontDeskBooking[]>([]);
  const [staff, setStaff] = useState<Array<{ id: string; name: string }>>([]);
  const [locations, setLocations] = useState<Array<{ id: string; name: string }>>([]);
  const [services, setServices] = useState<Array<{ id: string; name: string; duration_minutes?: number; price?: number }>>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const startDate = date.toISOString().slice(0, 10);
      const endDate = new Date(date);
      endDate.setDate(endDate.getDate() + 1);
      const endDateStr = endDate.toISOString().slice(0, 10);

      const params = new URLSearchParams();
      params.set("start_date", startDate);
      params.set("end_date", endDateStr);
      if (locationId) params.set("location_id", locationId);

      const [bookingsRes, staffData, locationsData, servicesData] = await Promise.all([
        fetcher.get<{ data: Booking[] }>(`/api/provider/bookings?${params.toString()}`, {
          timeoutMs: 8000,
        }),
        fetchStaff(locationId),
        fetchLocations(),
        fetchServices(),
      ]);

      const raw = (bookingsRes as any)?.data ?? bookingsRes;
      const arr = Array.isArray(raw) ? raw : [];
      const enriched: FrontDeskBooking[] = arr.map((b: any) => {
        const customer = b.customers || {};
        const loc = b.locations || {};
        const firstSvc = (b.services || [])[0];
        return {
          ...b,
          customer_name: customer.full_name || "Customer",
          staff_name: firstSvc?.staff_name || firstSvc?.staff?.name || "",
          location_name: loc.name || "",
          operationalBadge: getOperationalBadge(b),
        };
      });

      let filtered = enriched;
      if (query && query.trim()) {
        const q = query.toLowerCase().trim();
        filtered = enriched.filter(
          (b) =>
            (b.customer_name || "").toLowerCase().includes(q) ||
            (b.booking_number || "").toLowerCase().includes(q) ||
            ((b as any).customers?.phone || "").toLowerCase().includes(q)
        );
      }

      setBookings(filtered);
      setStaff(staffData);
      setLocations(locationsData);
      setServices(servicesData);
    } catch (err) {
      const msg =
        err instanceof FetchTimeoutError
          ? "Request timed out. Please try again."
          : err instanceof FetchError
            ? err.message
            : "Failed to load bookings";
      setError(msg);
      setBookings([]);
    } finally {
      setLoading(false);
    }
  }, [date, locationId, query]);

  useEffect(() => {
    load();
  }, [load]);

  return { bookings, staff, locations, services, loading, error, refetch: load };
}

/**
 * HTTP Fetcher Utility
 * 
 * A typed fetch wrapper with:
 * - Timeout support (default 12s)
 * - AbortController for cancellation
 * - FormData and JSON body support
 * - Typed errors
 * - Automatic error handling
 */

export interface FetchOptions extends Omit<RequestInit, 'body'> {
  body?: any; // Can be object (JSON) or FormData
  timeoutMs?: number;
  headers?: Record<string, string>;
}

export class FetchError extends Error {
  constructor(
    message: string,
    public status: number,
    public code?: string,
    public details?: any
  ) {
    super(message);
    this.name = 'FetchError';
  }
}

export class FetchTimeoutError extends Error {
  constructor(message: string = 'Request timeout') {
    super(message);
    this.name = 'FetchTimeoutError';
  }
}

/**
 * Fetches JSON from an API endpoint with timeout and error handling
 * 
 * @param url - The API endpoint URL (relative or absolute)
 * @param options - Fetch options including method, body, headers, timeout
 * @returns Promise resolving to typed JSON response
 * @throws FetchError for HTTP errors, FetchTimeoutError for timeouts
 */
export async function fetchJson<T = unknown>(
  url: string,
  options: FetchOptions = {}
): Promise<T> {
  const {
    method = 'GET',
    body,
    headers = {},
    timeoutMs = 10000, // Reduced to 10s for better responsiveness
    ...fetchOptions
  } = options;

  // Debug logging removed

  // Create AbortController for timeout
  const controller = new AbortController();
  const timeoutId = setTimeout(() => {
    // Debug logging removed
    controller.abort();
  }, timeoutMs);

  const requestStartTime = Date.now();
  try {
    // Prepare headers
    const requestHeaders: HeadersInit = {
      ...headers,
    };

    // Prepare body
    let requestBody: BodyInit | undefined;
    if (body) {
      if (body instanceof FormData) {
        // FormData - don't set Content-Type, browser will set it with boundary
        requestBody = body;
      } else {
        // JSON
        requestHeaders['Content-Type'] = 'application/json';
        requestBody = JSON.stringify(body);
      }
    }

    // Make request
    const response = await fetch(url, {
      method,
      headers: requestHeaders,
      body: requestBody,
      signal: controller.signal,
      ...fetchOptions,
    });

    const _requestDuration = Date.now() - requestStartTime;
    // Debug logging removed

    // Clear timeout on success
    clearTimeout(timeoutId);

    // Handle non-OK responses
    if (!response.ok) {
      let errorData: { message?: string; code?: string; details?: any } = {};

      try {
        const contentType = response.headers.get('content-type');
        if (contentType?.includes('application/json')) {
          const jsonData = await response.json();
          // Handle both { error: "..." } and { error: { message: "..." } } formats
          if (jsonData.error) {
            if (typeof jsonData.error === 'string') {
              errorData.message = jsonData.error;
            } else if (jsonData.error.message) {
              errorData.message = jsonData.error.message;
              errorData.code = jsonData.error.code;
              errorData.details = jsonData.error.details;
            }
          } else if (jsonData.message) {
            errorData.message = jsonData.message;
            errorData.code = jsonData.code;
            errorData.details = jsonData.details;
          } else {
            errorData = jsonData;
          }
        } else {
          const textResponse = await response.text();
          errorData.message = textResponse || `HTTP ${response.status}: ${response.statusText}`;
        }
      } catch {
        // If we can't parse the error response, use status text
        errorData.message = `HTTP ${response.status}: ${response.statusText || 'Unknown error'}`;
      }

      // Provide default messages for common status codes if no message is available
      if (!errorData.message) {
        switch (response.status) {
          case 401:
            errorData.message = 'Authentication required';
            errorData.code = 'UNAUTHORIZED';
            break;
          case 403:
            errorData.message = 'Access forbidden';
            errorData.code = 'FORBIDDEN';
            break;
          case 404:
            errorData.message = 'Resource not found';
            errorData.code = 'NOT_FOUND';
            break;
          case 409:
            errorData.message = 'Conflict: Resource already exists or is unavailable';
            errorData.code = 'CONFLICT';
            break;
          case 500:
            errorData.message = 'Internal server error';
            errorData.code = 'INTERNAL_ERROR';
            break;
          default:
            errorData.message = `Request failed with status ${response.status}`;
        }
      }

      throw new FetchError(
        errorData.message,
        response.status,
        errorData.code,
        errorData.details
      );
    }

    // Parse JSON response
    const contentType = response.headers.get('content-type');
    if (contentType?.includes('application/json')) {
      const jsonData = await response.json();
      // Debug logging removed
      return jsonData;
    }

    // If no JSON content type, return empty object (or handle as needed)
    return {} as T;
  } catch (error) {
    clearTimeout(timeoutId);

    // Handle abort (timeout or cancellation)
    if (error instanceof Error && (error.name === 'AbortError' || error.message.includes('aborted') || error.message.includes('signal is aborted'))) {
      // Check if it was a timeout or manual cancellation
      // If the signal was aborted, it's either a timeout or component unmount
      // For cancellations (not timeouts), we still throw FetchTimeoutError but mark it as cancelled
      // The error handlers and unhandled rejection handler will suppress it
      const wasTimeout = timeoutId !== null && controller.signal.aborted;
      const errorMessage = wasTimeout 
        ? `Request timed out after ${timeoutMs}ms`
        : 'Request was cancelled';
      // Convert to FetchTimeoutError - error handlers will suppress cancelled requests
      const timeoutError = new FetchTimeoutError(errorMessage);
      // Mark cancelled requests so they can be identified and suppressed
      if (!wasTimeout) {
        (timeoutError as any).__cancelled = true;
      }
      throw timeoutError;
    }

    // Re-throw FetchError as-is
    if (error instanceof FetchError) {
      throw error;
    }

    // Handle network errors
    if (error instanceof TypeError && error.message.includes('fetch')) {
      throw new FetchError(
        'Network error: Unable to reach server',
        0,
        'NETWORK_ERROR'
      );
    }

    // Unknown error
    throw new FetchError(
      error instanceof Error ? error.message : 'Unknown error occurred',
      0,
      'UNKNOWN_ERROR'
    );
  }
}

/**
 * Convenience methods for common HTTP methods
 */
export const fetcher = {
  get: <T = unknown>(url: string, options?: Omit<FetchOptions, 'method' | 'body'>) =>
    fetchJson<T>(url, { ...options, method: 'GET' }),

  post: <T = unknown>(url: string, body?: any, options?: Omit<FetchOptions, 'method' | 'body'>) =>
    fetchJson<T>(url, { ...options, method: 'POST', body }),

  patch: <T = unknown>(url: string, body?: any, options?: Omit<FetchOptions, 'method' | 'body'>) =>
    fetchJson<T>(url, { ...options, method: 'PATCH', body }),

  put: <T = unknown>(url: string, body?: any, options?: Omit<FetchOptions, 'method' | 'body'>) =>
    fetchJson<T>(url, { ...options, method: 'PUT', body }),

  delete: <T = unknown>(url: string, body?: any, options?: Omit<FetchOptions, 'method' | 'body'>) =>
    fetchJson<T>(url, { ...options, method: 'DELETE', body }),
};

/**
 * Inventory Stock Alerts
 * Monitors product stock levels and sends alerts when low
 */

import { getSupabaseAdmin } from "@/lib/supabase/admin";
import { sendTemplateNotification } from "@/lib/notifications/onesignal";

/**
 * Check for low stock products and send alerts
 */
export async function checkLowStockAndAlert(providerId?: string) {
  const supabaseAdmin = getSupabaseAdmin();

  try {
    // Build query for products with low stock
    let query = supabaseAdmin
      .from("products")
      .select(`
        id,
        name,
        quantity,
        low_stock_level,
        receive_low_stock_notifications,
        provider_id,
        providers!inner(
          id,
          user_id,
          business_name
        )
      `)
      .eq("track_stock_quantity", true)
      .eq("receive_low_stock_notifications", true)
      .eq("is_active", true);

    // Filter by provider if specified
    if (providerId) {
      query = query.eq("provider_id", providerId);
    }

    const { data: products, error } = await query;

    if (error) {
      throw error;
    }

    if (!products || products.length === 0) {
      return { checked: 0, alerted: 0 };
    }

    // Filter products that are at or below low stock level
    const lowStockProducts = products.filter(
      (product) => product.quantity <= (product.low_stock_level || 5)
    );

    if (lowStockProducts.length === 0) {
      return { checked: products.length, alerted: 0 };
    }

    // Group by provider to send one notification per provider
    const productsByProvider = new Map<string, typeof lowStockProducts>();

    for (const product of lowStockProducts) {
      const pid = product.provider_id;
      if (!productsByProvider.has(pid)) {
        productsByProvider.set(pid, []);
      }
      productsByProvider.get(pid)!.push(product);
    }

    // Send notifications
    let alertedCount = 0;
    for (const [pid, providerProducts] of productsByProvider.entries()) {
      const provider = providerProducts[0].providers as any;
      if (!provider?.user_id) continue;

      try {
        const productNames = providerProducts.map((p) => p.name).join(", ");
        const productList = providerProducts
          .map((p) => `${p.name} (${p.quantity} remaining, threshold: ${p.low_stock_level})`)
          .join("\n");

        // Create notification
        await supabaseAdmin.from("notifications").insert({
          user_id: provider.user_id,
          type: "low_stock_alert",
          title: "Low Stock Alert",
          message: `${providerProducts.length} product(s) are running low: ${productNames}`,
          metadata: {
            provider_id: pid,
            product_count: providerProducts.length,
            products: providerProducts.map((p) => ({
              id: p.id,
              name: p.name,
              quantity: p.quantity,
              low_stock_level: p.low_stock_level,
            })),
          },
          link: `/provider/products?low_stock=true`,
        });

        // Send push/email notification
        await sendTemplateNotification(
          "low_stock_alert",
          [provider.user_id],
          {
            product_count: providerProducts.length.toString(),
            product_names: productNames,
            provider_name: provider.business_name || "Your business",
            product_list: productList,
          },
          ["push", "email"]
        );

        alertedCount++;
      } catch (notifError) {
        console.error(`Error sending low stock alert for provider ${pid}:`, notifError);
      }
    }

    return {
      checked: products.length,
      alerted: alertedCount,
      lowStockCount: lowStockProducts.length,
    };
  } catch (error) {
    console.error("Error checking low stock:", error);
    throw error;
  }
}

/**
 * Check stock when product is sold (called from booking completion)
 */
export async function checkStockAfterSale(productId: string, quantitySold: number) {
  const supabaseAdmin = getSupabaseAdmin();

  try {
    const { data: product, error } = await supabaseAdmin
      .from("products")
      .select("id, quantity, low_stock_level, receive_low_stock_notifications, track_stock_quantity, provider_id, providers!inner(user_id)")
      .eq("id", productId)
      .single();

    if (error || !product) {
      return;
    }

    // Update stock if tracking is enabled
    if (product.track_stock_quantity) {
      const newQuantity = Math.max(0, product.quantity - quantitySold);
      await supabaseAdmin
        .from("products")
        .update({ quantity: newQuantity })
        .eq("id", productId);

      // Check if now low stock
      if (
        product.receive_low_stock_notifications &&
        newQuantity <= (product.low_stock_level || 5)
      ) {
        await checkLowStockAndAlert(product.provider_id);
      }
    }
  } catch (error) {
    console.error("Error checking stock after sale:", error);
  }
}

/**
 * Calculate loyalty points earned for a booking based on the active loyalty rule.
 * Aligns with validate-booking (loyalty_rules.points_per_currency_unit).
 *
 * @param bookingAmount - The booking amount (e.g. subtotal or total) in the currency
 * @param supabase - Supabase client instance
 * @param currency - Optional; if provided, only uses a rule for this currency
 * @returns The number of points earned
 */
export async function calculateLoyaltyPoints(
  bookingAmount: number,
  supabase: any,
  currency?: string
): Promise<number> {
  try {
    let query = supabase
      .from("loyalty_rules")
      .select("points_per_currency_unit, currency")
      .eq("is_active", true)
      .order("effective_from", { ascending: false })
      .limit(1);
    if (currency) {
      query = query.eq("currency", currency);
    }
    const { data: activeRule, error } = await query.maybeSingle();

    if (error || !activeRule) {
      return Math.floor(bookingAmount);
    }

    const pointsPerUnit = Number(activeRule.points_per_currency_unit) || 1;
    return Math.floor(bookingAmount * pointsPerUnit);
  } catch (error) {
    console.error("Error calculating loyalty points:", error);
    return Math.floor(bookingAmount);
  }
}

/**
 * Geocode a provider location that has address text but missing latitude/longitude.
 * Used for locations created by ensure_freelancer_location or any address-only create.
 */

import type { SupabaseClient } from "@supabase/supabase-js";
import { getMapboxService } from "./mapbox";

export interface GeocodeProviderLocationResult {
  ok: boolean;
  latitude?: number;
  longitude?: number;
  error?: string;
}

/**
 * Build a full address string from provider_locations fields.
 */
export function buildFullAddress(row: {
  address_line1?: string | null;
  address_line2?: string | null;
  city?: string | null;
  state?: string | null;
  postal_code?: string | null;
  country?: string | null;
}): string {
  return [
    row.address_line1,
    row.address_line2,
    row.city,
    row.state,
    row.postal_code,
    row.country,
  ]
    .filter(Boolean)
    .join(", ");
}

/**
 * Geocode a single provider location by id: if it has address but null coords,
 * call Mapbox and update the row. Returns { ok, latitude, longitude } or { ok: false, error }.
 */
export async function geocodeProviderLocation(
  supabase: SupabaseClient,
  locationId: string
): Promise<GeocodeProviderLocationResult> {
  const { data: row, error: fetchError } = await supabase
    .from("provider_locations")
    .select("id, address_line1, address_line2, city, state, postal_code, country, latitude, longitude")
    .eq("id", locationId)
    .single();

  if (fetchError || !row) {
    return { ok: false, error: fetchError?.message ?? "Location not found" };
  }

  const r = row as {
    address_line1?: string | null;
    address_line2?: string | null;
    city?: string | null;
    state?: string | null;
    postal_code?: string | null;
    country?: string | null;
    latitude?: number | null;
    longitude?: number | null;
  };

  if (r.latitude != null && r.longitude != null) {
    return { ok: true, latitude: r.latitude, longitude: r.longitude };
  }

  if (!r.address_line1 || !r.city || !r.country) {
    return { ok: false, error: "Address line1, city, and country required for geocoding" };
  }

  try {
    const mapbox = await getMapboxService();
    const fullAddress = buildFullAddress(r);
    const results = await mapbox.geocode(fullAddress, {
      country: r.country ?? undefined,
      limit: 1,
    });

    if (results.length === 0) {
      return { ok: false, error: "No geocode result" };
    }

    const result = results[0];
    const latitude = result.center[1];
    const longitude = result.center[0];

    const { error: updateError } = await supabase
      .from("provider_locations")
      .update({ latitude, longitude })
      .eq("id", locationId);

    if (updateError) {
      return { ok: false, error: updateError.message };
    }

    return { ok: true, latitude, longitude };
  } catch (err: any) {
    return { ok: false, error: err?.message ?? "Geocoding failed" };
  }
}

/**
 * Mapbox Integration Utilities
 * 
 * Provides functions for:
 * - Geocoding (address to coordinates)
 * - Reverse geocoding (coordinates to address)
 * - Distance calculation
 * - Route calculation
 * - Service zone management
 * - Polygon operations
 * 
 * Reference: https://docs.mapbox.com/api/
 */

export interface MapboxConfig {
  accessToken: string;
  baseUrl?: string;
}

export interface Coordinates {
  longitude: number;
  latitude: number;
}

export interface GeocodeResult {
  id: string;
  type: string;
  place_name: string;
  center: [number, number]; // [longitude, latitude]
  geometry: {
    type: string;
    coordinates: [number, number];
  };
  context?: Array<{
    id: string;
    text: string;
    short_code?: string;
  }>;
  properties?: Record<string, any>;
}

export interface RouteResult {
  distance: number; // in meters
  duration: number; // in seconds
  geometry: {
    type: string;
    coordinates: [number, number][];
  };
  legs: Array<{
    distance: number;
    duration: number;
    steps: Array<{
      distance: number;
      duration: number;
      geometry: {
        coordinates: [number, number][];
      };
      maneuver: {
        type: string;
        instruction: string;
      };
    }>;
  }>;
}

export interface DistanceMatrixResult {
  distances: number[][]; // in meters
  durations: number[][]; // in seconds
}

export interface ServiceZone {
  id: string;
  name: string;
  type: "radius" | "polygon";
  coordinates: Coordinates | Coordinates[]; // single point for radius, array for polygon
  radius_km?: number; // for radius type
  is_active: boolean;
}

class MapboxService {
  private config: MapboxConfig;

  constructor(config: MapboxConfig) {
    this.config = {
      baseUrl: "https://api.mapbox.com",
      ...config,
    };
  }

  /**
   * Geocode an address to coordinates
   */
  async geocode(query: string, options?: {
    proximity?: Coordinates;
    country?: string;
    types?: string[];
    limit?: number;
  }): Promise<GeocodeResult[]> {
    const params = new URLSearchParams({
      access_token: this.config.accessToken,
      q: query,
    });

    if (options?.proximity) {
      params.append("proximity", `${options.proximity.longitude},${options.proximity.latitude}`);
    }
    if (options?.country) {
      params.append("country", options.country);
    }
    if (options?.types) {
      params.append("types", options.types.join(","));
    }
    if (options?.limit) {
      params.append("limit", options.limit.toString());
    }

    const response = await fetch(
      `${this.config.baseUrl}/geocoding/v5/mapbox.places/${encodeURIComponent(query)}.json?${params}`
    );

    if (!response.ok) {
      throw new Error(`Mapbox geocoding failed: ${response.statusText}`);
    }

    const data = await response.json();
    return data.features || [];
  }

  /**
   * Reverse geocode coordinates to address
   */
  async reverseGeocode(coordinates: Coordinates): Promise<GeocodeResult | null> {
    const params = new URLSearchParams({
      access_token: this.config.accessToken,
    });

    const response = await fetch(
      `${this.config.baseUrl}/geocoding/v5/mapbox.places/${coordinates.longitude},${coordinates.latitude}.json?${params}`
    );

    if (!response.ok) {
      throw new Error(`Mapbox reverse geocoding failed: ${response.statusText}`);
    }

    const data = await response.json();
    return data.features?.[0] || null;
  }

  /**
   * Calculate distance between two points (Haversine formula)
   */
  calculateDistance(point1: Coordinates, point2: Coordinates): number {
    const R = 6371; // Earth's radius in kilometers
    const dLat = this.toRadians(point2.latitude - point1.latitude);
    const dLon = this.toRadians(point2.longitude - point1.longitude);

    const a =
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(this.toRadians(point1.latitude)) *
        Math.cos(this.toRadians(point2.latitude)) *
        Math.sin(dLon / 2) *
        Math.sin(dLon / 2);

    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c; // Distance in kilometers
  }

  /**
   * Calculate route between two or more points
   */
  async calculateRoute(waypoints: Coordinates[], options?: {
    profile?: "driving" | "walking" | "cycling";
    alternatives?: boolean;
    geometries?: "geojson" | "polyline" | "polyline6";
    overview?: "full" | "simplified" | "false";
    steps?: boolean;
  }): Promise<RouteResult> {
    const profile = options?.profile || "driving";
    const coordinates = waypoints
      .map((wp) => `${wp.longitude},${wp.latitude}`)
      .join(";");

    const params = new URLSearchParams({
      access_token: this.config.accessToken,
      geometries: options?.geometries || "geojson",
      overview: options?.overview || "full",
      steps: (options?.steps !== false).toString(),
      alternatives: (options?.alternatives || false).toString(),
    });

    const response = await fetch(
      `${this.config.baseUrl}/directions/v5/mapbox/${profile}/${coordinates}?${params}`
    );

    if (!response.ok) {
      throw new Error(`Mapbox routing failed: ${response.statusText}`);
    }

    const data = await response.json();
    if (!data.routes || data.routes.length === 0) {
      throw new Error("No route found");
    }

    const route = data.routes[0];
    return {
      distance: route.distance,
      duration: route.duration,
      geometry: route.geometry,
      legs: route.legs || [],
    };
  }

  /**
   * Calculate distance matrix for multiple points
   */
  async calculateDistanceMatrix(
    origins: Coordinates[],
    destinations: Coordinates[],
    options?: {
      profile?: "driving" | "walking" | "cycling";
    }
  ): Promise<DistanceMatrixResult> {
    const profile = options?.profile || "driving";
    const coordinates = [...origins, ...destinations]
      .map((coord) => `${coord.longitude},${coord.latitude}`)
      .join(";");

    const params = new URLSearchParams({
      access_token: this.config.accessToken,
      sources: Array.from({ length: origins.length }, (_, i) => i.toString()).join(";"),
      destinations: Array.from(
        { length: destinations.length },
        (_, i) => (origins.length + i).toString()
      ).join(";"),
    });

    const response = await fetch(
      `${this.config.baseUrl}/directions-matrix/v1/mapbox/${profile}/${coordinates}?${params}`
    );

    if (!response.ok) {
      throw new Error(`Mapbox distance matrix failed: ${response.statusText}`);
    }

    const data = await response.json();
    return {
      distances: data.distances || [],
      durations: data.durations || [],
    };
  }

  /**
   * Check if a point is within a service zone
   */
  isPointInZone(point: Coordinates, zone: ServiceZone): boolean {
    if (zone.type === "radius") {
      if (!zone.radius_km || !Array.isArray(zone.coordinates) || zone.coordinates.length === 0) {
        return false;
      }
      const center = zone.coordinates[0];
      const distance = this.calculateDistance(center, point);
      return distance <= zone.radius_km;
    } else if (zone.type === "polygon") {
      if (!Array.isArray(zone.coordinates) || zone.coordinates.length < 3) {
        return false;
      }
      return this.isPointInPolygon(point, zone.coordinates);
    }
    return false;
  }

  /**
   * Check if a point is inside a polygon (Ray casting algorithm)
   */
  private isPointInPolygon(point: Coordinates, polygon: Coordinates[]): boolean {
    let inside = false;
    for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
      const xi = polygon[i].longitude;
      const yi = polygon[i].latitude;
      const xj = polygon[j].longitude;
      const yj = polygon[j].latitude;

      const intersect =
        yi > point.latitude !== yj > point.latitude &&
        point.longitude < ((xj - xi) * (point.latitude - yi)) / (yj - yi) + xi;

      if (intersect) inside = !inside;
    }
    return inside;
  }

  /**
   * Calculate polygon area (in square kilometers)
   */
  calculatePolygonArea(polygon: Coordinates[]): number {
    if (polygon.length < 3) return 0;

    let area = 0;
    const R = 6371; // Earth's radius in kilometers

    for (let i = 0; i < polygon.length; i++) {
      const j = (i + 1) % polygon.length;
      const lat1 = this.toRadians(polygon[i].latitude);
      const lat2 = this.toRadians(polygon[j].latitude);
      const dLon = this.toRadians(polygon[j].longitude - polygon[i].longitude);

      area +=
        ((dLon / (2 * Math.PI)) *
          (2 * Math.PI * R * R * Math.sin(lat1) * Math.sin(lat2) +
            Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLon))) /
        2;
    }

    return Math.abs(area);
  }

  /**
   * Get bounding box for a set of coordinates
   */
  getBoundingBox(coordinates: Coordinates[]): {
    minLng: number;
    minLat: number;
    maxLng: number;
    maxLat: number;
  } {
    if (coordinates.length === 0) {
      throw new Error("Cannot calculate bounding box for empty coordinates");
    }

    let minLng = coordinates[0].longitude;
    let maxLng = coordinates[0].longitude;
    let minLat = coordinates[0].latitude;
    let maxLat = coordinates[0].latitude;

    for (const coord of coordinates) {
      minLng = Math.min(minLng, coord.longitude);
      maxLng = Math.max(maxLng, coord.longitude);
      minLat = Math.min(minLat, coord.latitude);
      maxLat = Math.max(maxLat, coord.latitude);
    }

    return { minLng, minLat, maxLng, maxLat };
  }

  private toRadians(degrees: number): number {
    return degrees * (Math.PI / 180);
  }
}

// Singleton instance
let mapboxInstance: MapboxService | null = null;

export async function getMapboxService(): Promise<MapboxService> {
  if (!mapboxInstance) {
    // Load secret access token from platform_secrets (fallback to env)
    const { getMapboxAccessToken } = await import("@/lib/platform/secrets");
    const accessToken = (await getMapboxAccessToken()) || "";

    if (!accessToken) {
      // Check if Mapbox is enabled in config
      try {
        const { getSupabaseServer } = await import("@/lib/supabase/server");
        const supabase = await getSupabaseServer();
        const { data: config } = await supabase
          .from("mapbox_config")
          .select("is_enabled")
          .single();

        // If Mapbox is explicitly disabled, return a service that will fail gracefully
        if (config && !config.is_enabled) {
          throw new Error("Mapbox is disabled in configuration");
        }
      } catch {
        // Config doesn't exist or error checking - continue with error
      }

      throw new Error("MAPBOX_ACCESS_TOKEN not configured. Please set it in the admin portal at /admin/mapbox or environment variables.");
    }
    mapboxInstance = new MapboxService({ accessToken });
  }
  return mapboxInstance;
}

export function createMapboxService(config: MapboxConfig): MapboxService {
  return new MapboxService(config);
}

/**
 * Unified Marketing Service
 * 
 * Provides a unified interface for sending marketing campaigns (emails, SMS, and WhatsApp)
 * using provider-configured integrations.
 * 
 * API References:
 * - SendGrid: https://docs.sendgrid.com/api-reference/mail-send/mail-send
 * - Mailchimp: https://mailchimp.com/developer/transactional/api/messages/send-new-message/
 * - Twilio: https://www.twilio.com/docs/usage/api
 */

import { getSupabaseServer } from "@/lib/supabase/server";
import type { SupabaseClient } from "@supabase/supabase-js";

export type MessagingChannel = "email" | "sms" | "whatsapp";
export type EmailProvider = "sendgrid" | "mailchimp";

export interface SendCampaignOptions {
  to: string | string[]; // Email address or phone number(s)
  subject?: string; // For email campaigns
  content: string; // Campaign message body
  from?: string; // From email/phone (optional, uses integration default)
  fromName?: string; // From name (optional)
  metadata?: Record<string, any>; // Additional campaign metadata
}

export interface SendCampaignResult {
  success: boolean;
  messageId?: string;
  error?: string;
  provider?: string;
}

export interface EmailIntegration {
  id: string;
  provider_id: string;
  provider_name: EmailProvider;
  api_key: string;
  api_secret?: string;
  from_email: string;
  from_name: string;
  is_enabled: boolean;
  test_status: "pending" | "success" | "failed";
}

export interface TwilioIntegration {
  id: string;
  provider_id: string;
  account_sid: string;
  auth_token: string;
  sms_from_number?: string;
  whatsapp_from_number?: string;
  is_sms_enabled: boolean;
  is_whatsapp_enabled: boolean;
  sms_test_status: "pending" | "success" | "failed";
  whatsapp_test_status: "pending" | "success" | "failed";
}

/**
 * Get provider's email integration
 */
export async function getEmailIntegration(
  supabase: SupabaseClient<any>,
  providerId: string
): Promise<EmailIntegration | null> {
  const { data, error } = await supabase
    .from("provider_email_integrations")
    .select("*")
    .eq("provider_id", providerId)
    .eq("is_enabled", true)
    .single();

  if (error || !data) {
    return null;
  }

  return data as EmailIntegration;
}

/**
 * Get provider's Twilio integration
 */
export async function getTwilioIntegration(
  supabase: SupabaseClient<any>,
  providerId: string
): Promise<TwilioIntegration | null> {
  const { data, error } = await supabase
    .from("provider_twilio_integrations")
    .select("*")
    .eq("provider_id", providerId)
    .single();

  if (error || !data) {
    return null;
  }

  return data as TwilioIntegration;
}

/**
 * Send marketing campaign using provider's integration
 */
export async function sendMessage(
  providerId: string,
  channel: MessagingChannel,
  options: SendCampaignOptions
): Promise<SendCampaignResult> {
  const supabase = await getSupabaseServer();

  if (channel === "email") {
    const integration = await getEmailIntegration(supabase, providerId);
    if (!integration) {
      return {
        success: false,
        error: "No active email integration found. Please configure SendGrid or Mailchimp in settings.",
      };
    }

    if (integration.provider_name === "sendgrid") {
      return await sendViaSendGrid(integration, options);
    } else if (integration.provider_name === "mailchimp") {
      return await sendViaMailchimp(integration, options);
    }
  } else if (channel === "sms" || channel === "whatsapp") {
    const integration = await getTwilioIntegration(supabase, providerId);
    if (!integration) {
      return {
        success: false,
        error: "No Twilio integration found. Please configure Twilio in settings.",
      };
    }

    if (channel === "sms") {
      if (!integration.is_sms_enabled || !integration.sms_from_number) {
        return {
          success: false,
          error: "SMS is not enabled or configured. Please enable SMS in Twilio settings.",
        };
      }
      return await sendViaTwilioSMS(integration, options);
    } else {
      if (!integration.is_whatsapp_enabled || !integration.whatsapp_from_number) {
        return {
          success: false,
          error: "WhatsApp is not enabled or configured. Please enable WhatsApp in Twilio settings.",
        };
      }
      return await sendViaTwilioWhatsApp(integration, options);
    }
  }

  return {
    success: false,
    error: `Unsupported channel: ${channel}`,
  };
}

// Email Provider Implementations

/**
 * Send via SendGrid v3 API
 * Documentation: https://docs.sendgrid.com/api-reference/mail-send/mail-send
 */
async function sendViaSendGrid(
  integration: EmailIntegration,
  options: SendCampaignOptions
): Promise<SendCampaignResult> {
  try {
    const apiKey = integration.api_key;
    if (!apiKey) {
      return { success: false, error: "SendGrid API key not configured" };
    }

    if (!options.subject) {
      return { success: false, error: "Email subject is required" };
    }

    const recipients = Array.isArray(options.to) ? options.to : [options.to];
    const fromEmail = options.from || integration.from_email;
    const fromName = options.fromName || integration.from_name || "Beautonomi";

    // SendGrid v3 API structure
    const payload = {
      personalizations: recipients.map(to => ({
        to: [{ email: to }],
      })),
      from: {
        email: fromEmail,
        name: fromName,
      },
      subject: options.subject,
      content: [
        {
          type: "text/html",
          value: options.content,
        },
      ],
    };

    const response = await fetch("https://api.sendgrid.com/v3/mail/send", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(payload),
    });

    // SendGrid returns 202 Accepted on success (no body)
    if (response.status === 202) {
      // Extract message ID from X-Message-Id header if available
      const messageId = response.headers.get("X-Message-Id");
      return {
        success: true,
        messageId: messageId || undefined,
        provider: "sendgrid",
      };
    }

    // Handle errors
    const errorText = await response.text();
    let errorMessage = "SendGrid API error";

    try {
      const errorJson = JSON.parse(errorText);
      errorMessage = errorJson.errors?.[0]?.message || errorJson.message || errorMessage;
    } catch {
      errorMessage = errorText || errorMessage;
    }

    return {
      success: false,
      error: errorMessage,
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}

/**
 * Send via Mailchimp Marketing API
 * For marketing campaigns, we use the Mailchimp Marketing API (v3.0)
 * Documentation: https://mailchimp.com/developer/marketing/api/campaigns/
 * 
 * Note: This creates and sends a campaign via Mailchimp's Marketing API.
 * Mailchimp Transactional (Mandrill) should only be used for transactional emails
 * (order confirmations, password resets, etc.), not marketing campaigns.
 */
async function sendViaMailchimp(
  integration: EmailIntegration,
  options: SendCampaignOptions
): Promise<SendCampaignResult> {
  try {
    const apiKey = integration.api_key || integration.api_secret;
    if (!apiKey) {
      return { success: false, error: "Mailchimp API key not configured" };
    }

    if (!options.subject) {
      return { success: false, error: "Email subject is required" };
    }

    // Extract datacenter from API key (format: xxxxx-us1)
    // Mailchimp API keys contain the datacenter suffix
    const parts = apiKey.split("-");
    const datacenter = parts.length > 1 ? parts[parts.length - 1] : "us1";
    const recipients = Array.isArray(options.to) ? options.to : [options.to];
    const fromEmail = options.from || integration.from_email;
    const fromName = options.fromName || integration.from_name || "Beautonomi";

    // For marketing campaigns, we need to:
    // 1. Create a temporary list/segment with recipients
    // 2. Create a campaign
    // 3. Send the campaign
    // 
    // Note: This is a simplified implementation. For production, you should:
    // - Maintain a permanent audience list
    // - Use segments or tags for targeting
    // - Schedule campaigns rather than immediate send

    const baseUrl = `https://${datacenter}.api.mailchimp.com/3.0`;
    const authHeader = `Basic ${Buffer.from(`anystring:${apiKey}`).toString('base64')}`;

    // Step 1: Create a temporary list for this campaign
    const listPayload = {
      name: `Campaign ${Date.now()}`,
      permission_reminder: "You're receiving this because you opted in.",
      email_type_option: false,
      contact: {
        company: fromName,
        address1: "",
        city: "",
        state: "",
        zip: "",
        country: "ZA",
      },
      campaign_defaults: {
        from_name: fromName,
        from_email: fromEmail,
        subject: options.subject,
        language: "en",
      },
    };

    const listResponse = await fetch(`${baseUrl}/lists`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": authHeader,
      },
      body: JSON.stringify(listPayload),
    });

    if (!listResponse.ok) {
      const errorText = await listResponse.text();
      return {
        success: false,
        error: `Failed to create audience list: ${errorText}`,
      };
    }

    const listData = await listResponse.json();
    const listId = listData.id;

    // Step 2: Add recipients to the list
    const membersPayload = {
      members: recipients.map(email => ({
        email_address: email,
        status: "subscribed",
      })),
      update_existing: false,
    };

    await fetch(`${baseUrl}/lists/${listId}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": authHeader,
      },
      body: JSON.stringify(membersPayload),
    });

    // Step 3: Create a campaign
    const campaignPayload = {
      type: "regular",
      recipients: {
        list_id: listId,
      },
      settings: {
        subject_line: options.subject,
        from_name: fromName,
        reply_to: fromEmail,
        title: `Campaign ${Date.now()}`,
      },
    };

    const campaignResponse = await fetch(`${baseUrl}/campaigns`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": authHeader,
      },
      body: JSON.stringify(campaignPayload),
    });

    if (!campaignResponse.ok) {
      const errorText = await campaignResponse.text();
      return {
        success: false,
        error: `Failed to create campaign: ${errorText}`,
      };
    }

    const campaignData = await campaignResponse.json();
    const campaignId = campaignData.id;

    // Step 4: Set campaign content
    const contentPayload = {
      html: options.content,
    };

    await fetch(`${baseUrl}/campaigns/${campaignId}/content`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        "Authorization": authHeader,
      },
      body: JSON.stringify(contentPayload),
    });

    // Step 5: Send the campaign
    const sendResponse = await fetch(`${baseUrl}/campaigns/${campaignId}/actions/send`, {
      method: "POST",
      headers: {
        "Authorization": authHeader,
      },
    });

    if (!sendResponse.ok) {
      const errorText = await sendResponse.text();
      return {
        success: false,
        error: `Failed to send campaign: ${errorText}`,
      };
    }

    return {
      success: true,
      messageId: campaignId,
      provider: "mailchimp",
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}

// SMS Provider Implementations

/**
 * Send SMS via Twilio API
 * Documentation: https://www.twilio.com/docs/usage/api
 * Endpoint: POST /2010-04-01/Accounts/{AccountSid}/Messages.json
 */
async function sendViaTwilioSMS(
  integration: TwilioIntegration,
  options: SendCampaignOptions
): Promise<SendCampaignResult> {
  try {
    const accountSid = integration.account_sid;
    const authToken = integration.auth_token;
    const fromNumber = integration.sms_from_number;

    if (!accountSid || !authToken || !fromNumber) {
      return { success: false, error: "Twilio SMS credentials not configured" };
    }

    if (!options.content) {
      return { success: false, error: "Message content is required" };
    }

    const recipients = Array.isArray(options.to) ? options.to : [options.to];

    // Twilio requires E.164 format phone numbers
    // Validate and send to each recipient
    const results = await Promise.all(
      recipients.map(async (to) => {
        // Ensure phone number is in E.164 format (starts with +)
        const toNumber = to.startsWith("+") ? to : `+${to.replace(/\D/g, "")}`;
        const fromNumberFormatted = fromNumber.startsWith("+") ? fromNumber : `+${fromNumber.replace(/\D/g, "")}`;

        const response = await fetch(
          `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`,
          {
            method: "POST",
            headers: {
              "Authorization": `Basic ${Buffer.from(`${accountSid}:${authToken}`).toString("base64")}`,
              "Content-Type": "application/x-www-form-urlencoded",
            },
            body: new URLSearchParams({
              From: fromNumberFormatted,
              To: toNumber,
              Body: options.content,
            }),
          }
        );

        if (!response.ok) {
          const error = await response.json();
          throw new Error(error.message || `Twilio API error: ${response.status}`);
        }

        return await response.json();
      })
    );

    // Return first message SID as the message ID
    return {
      success: true,
      messageId: results[0]?.sid,
      provider: "twilio_sms",
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}


// WhatsApp Provider Implementations

/**
 * Send WhatsApp via Twilio API
 * Documentation: https://www.twilio.com/docs/whatsapp
 * Uses the same Messages API but with whatsapp: prefix for phone numbers
 */
async function sendViaTwilioWhatsApp(
  integration: TwilioIntegration,
  options: SendCampaignOptions
): Promise<SendCampaignResult> {
  try {
    const accountSid = integration.account_sid;
    const authToken = integration.auth_token;
    const fromNumber = integration.whatsapp_from_number;

    if (!accountSid || !authToken || !fromNumber) {
      return { success: false, error: "Twilio WhatsApp credentials not configured" };
    }

    if (!options.content) {
      return { success: false, error: "Message content is required" };
    }

    const recipients = Array.isArray(options.to) ? options.to : [options.to];

    // Twilio WhatsApp requires whatsapp: prefix for phone numbers
    // Format: whatsapp:+14155238886
    const results = await Promise.all(
      recipients.map(async (to) => {
        // Ensure phone number is in E.164 format first, then add whatsapp: prefix
        let toNumber = to.startsWith("whatsapp:") ? to.replace("whatsapp:", "") : to;
        toNumber = toNumber.startsWith("+") ? toNumber : `+${toNumber.replace(/\D/g, "")}`;
        const toWhatsApp = `whatsapp:${toNumber}`;

        // Format from number
        const fromNumberFormatted = fromNumber.startsWith("whatsapp:") 
          ? fromNumber 
          : fromNumber.startsWith("+")
          ? `whatsapp:${fromNumber}`
          : `whatsapp:+${fromNumber.replace(/\D/g, "")}`;

        const response = await fetch(
          `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`,
          {
            method: "POST",
            headers: {
              "Authorization": `Basic ${Buffer.from(`${accountSid}:${authToken}`).toString("base64")}`,
              "Content-Type": "application/x-www-form-urlencoded",
            },
            body: new URLSearchParams({
              From: fromNumberFormatted,
              To: toWhatsApp,
              Body: options.content,
            }),
          }
        );

        if (!response.ok) {
          const error = await response.json();
          throw new Error(error.message || `Twilio WhatsApp API error: ${response.status}`);
        }

        return await response.json();
      })
    );

    return {
      success: true,
      messageId: results[0]?.sid,
      provider: "twilio_whatsapp",
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}

/**
 * Error Logging Service
 * Logs API errors and failures for monitoring and debugging
 */

import { createClient } from "@supabase/supabase-js";

export interface ErrorLog {
  id?: string;
  error_type: string;
  error_message: string;
  endpoint?: string;
  method?: string;
  status_code?: number;
  user_id?: string;
  provider_id?: string;
  request_data?: any;
  stack_trace?: string;
  severity: "low" | "medium" | "high" | "critical";
  created_at?: string;
}

class ErrorLogger {
  private supabaseAdmin: ReturnType<typeof createClient> | null = null;
  private isInitialized = false;

  private init() {
    if (this.isInitialized) return;

    try {
      // Never initialize on client - SUPABASE_SERVICE_ROLE_KEY is server-only
      if (typeof window !== "undefined") {
        this.isInitialized = true;
        return;
      }

      const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
      const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

      if (!supabaseUrl || !supabaseKey || typeof supabaseKey !== "string") {
        this.isInitialized = true;
        return;
      }

      this.supabaseAdmin = createClient(supabaseUrl, supabaseKey, {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      });
    } catch (error) {
      // Don't propagate - error logging must never break the app
      if (typeof console !== "undefined" && console.error) {
        console.error("Failed to initialize error logger:", error);
      }
    } finally {
      this.isInitialized = true;
    }
  }

  async logError(error: ErrorLog): Promise<void> {
    this.init();

    if (!this.supabaseAdmin) {
      // Fallback to console if Supabase not available
      console.error("Error Log:", error);
      return;
    }

    try {
      await this.supabaseAdmin.from("error_logs").insert({
        error_type: error.error_type,
        error_message: error.error_message,
        endpoint: error.endpoint,
        method: error.method,
        status_code: error.status_code,
        user_id: error.user_id,
        provider_id: error.provider_id,
        request_data: error.request_data,
        stack_trace: error.stack_trace,
        severity: error.severity,
      } as never);
    } catch (err) {
      // Don't throw - just log to console if database insert fails
      console.error("Failed to log error to database:", err);
      console.error("Original error:", error);
    }
  }

  async logApiError(
    endpoint: string,
    method: string,
    error: Error | unknown,
    userId?: string,
    providerId?: string,
    requestData?: any,
    statusCode?: number
  ): Promise<void> {
    const err = error as Error;
    const errorLog: ErrorLog = {
      error_type: err.name || "API_ERROR",
      error_message: err.message || String(error),
      endpoint,
      method,
      status_code: statusCode,
      user_id: userId,
      provider_id: providerId,
      request_data: requestData,
      stack_trace: err.stack,
      severity: this.determineSeverity(statusCode, error),
    };

    await this.logError(errorLog);
  }

  private determineSeverity(statusCode?: number, error?: any): ErrorLog["severity"] {
    if (statusCode) {
      if (statusCode >= 500) return "critical";
      if (statusCode >= 400) return "high";
      return "medium";
    }

    if (error?.message?.includes("timeout") || error?.message?.includes("network")) {
      return "high";
    }

    return "medium";
  }

  async getErrorLogs(filters?: {
    severity?: ErrorLog["severity"];
    endpoint?: string;
    provider_id?: string;
    start_date?: string;
    end_date?: string;
    limit?: number;
  }): Promise<ErrorLog[]> {
    this.init();

    if (!this.supabaseAdmin) {
      return [];
    }

    try {
      let query = this.supabaseAdmin
        .from("error_logs")
        .select("*")
        .order("created_at", { ascending: false });

      if (filters?.severity) {
        query = query.eq("severity", filters.severity);
      }
      if (filters?.endpoint) {
        query = query.ilike("endpoint", `%${filters.endpoint}%`);
      }
      if (filters?.provider_id) {
        query = query.eq("provider_id", filters.provider_id);
      }
      if (filters?.start_date) {
        query = query.gte("created_at", filters.start_date);
      }
      if (filters?.end_date) {
        query = query.lte("created_at", filters.end_date);
      }

      const limit = filters?.limit || 100;
      query = query.limit(limit);

      const { data, error } = await query;

      if (error) {
        console.error("Failed to fetch error logs:", error);
        return [];
      }

      return data || [];
    } catch (error) {
      console.error("Error fetching error logs:", error);
      return [];
    }
  }

  async getErrorStats(timeframe: "24h" | "7d" | "30d" = "24h"): Promise<{
    total: number;
    by_severity: Record<string, number>;
    by_endpoint: Array<{ endpoint: string; count: number }>;
    recent_errors: ErrorLog[];
  }> {
    this.init();

    if (!this.supabaseAdmin) {
      return {
        total: 0,
        by_severity: {},
        by_endpoint: [],
        recent_errors: [],
      };
    }

    try {
      const now = new Date();
      const startDate = new Date();

      switch (timeframe) {
        case "24h":
          startDate.setHours(now.getHours() - 24);
          break;
        case "7d":
          startDate.setDate(now.getDate() - 7);
          break;
        case "30d":
          startDate.setDate(now.getDate() - 30);
          break;
      }

      const { data, error } = await this.supabaseAdmin
        .from("error_logs")
        .select("*")
        .gte("created_at", startDate.toISOString())
        .order("created_at", { ascending: false });

      if (error) {
        console.error("Failed to fetch error stats:", error);
        return {
          total: 0,
          by_severity: {},
          by_endpoint: [],
          recent_errors: [],
        };
      }

      const logs = (data || []) as Array<{ severity?: string; endpoint?: string }>;

      // Calculate stats
      const by_severity: Record<string, number> = {};
      const by_endpoint_map: Record<string, number> = {};

      logs.forEach((log) => {
        const sev = log.severity ?? "unknown";
        by_severity[sev] = (by_severity[sev] || 0) + 1;
        if (log.endpoint) {
          by_endpoint_map[log.endpoint] = (by_endpoint_map[log.endpoint] || 0) + 1;
        }
      });

      const by_endpoint = Object.entries(by_endpoint_map)
        .map(([endpoint, count]) => ({ endpoint, count }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 10);

      return {
        total: logs.length,
        by_severity,
        by_endpoint,
        recent_errors: logs.slice(0, 20) as ErrorLog[],
      };
    } catch (error) {
      console.error("Error calculating error stats:", error);
      return {
        total: 0,
        by_severity: {},
        by_endpoint: [],
        recent_errors: [],
      };
    }
  }
}

