/**
 * Performance Optimization Utilities
 * 
 * Centralized utilities for optimizing provider portal performance
 */

import { useMemo, useCallback, RefObject } from 'react';

/**
 * Debounce function for API calls and user input
 */
export function debounce<T extends (...args: any[]) => unknown>(
  func: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeout: NodeJS.Timeout | null = null;
  
  return function executedFunction(...args: Parameters<T>) {
    const later = () => {
      timeout = null;
      func(...args);
    };
    
    if (timeout) {
      clearTimeout(timeout);
    }
    timeout = setTimeout(later, wait);
  };
}

/**
 * Throttle function for scroll and resize events
 */
export function throttle<T extends (...args: any[]) => unknown>(
  func: T,
  limit: number
): (...args: Parameters<T>) => void {
  let inThrottle: boolean;
  
  return function executedFunction(...args: Parameters<T>) {
    if (!inThrottle) {
      func(...args);
      inThrottle = true;
      setTimeout(() => (inThrottle = false), limit);
    }
  };
}

/**
 * Memoize expensive computations
 */
export function useMemoizedValue<T>(
  computeFn: () => T,
  deps: React.DependencyList
): T {
  return useMemo(computeFn, deps);
}

/**
 * Create a stable callback reference
 */
export function useStableCallback<T extends (...args: any[]) => unknown>(
  callback: T,
  deps: React.DependencyList
): T {
  return useCallback(callback, deps) as T;
}

/**
 * Intersection Observer for lazy loading
 */
export function useIntersectionObserver(
  elementRef: RefObject<Element>,
  options: IntersectionObserverInit = {}
) {
  const [isIntersecting, setIsIntersecting] = React.useState(false);
  
  React.useEffect(() => {
    const element = elementRef.current;
    if (!element) return;
    
    const observer = new IntersectionObserver(([entry]) => {
      setIsIntersecting(entry.isIntersecting);
    }, {
      threshold: 0.1,
      ...options,
    });
    
    observer.observe(element);
    
    return () => {
      observer.disconnect();
    };
  }, [elementRef, options]);
  
  return isIntersecting;
}

/**
 * Request deduplication cache
 */
class RequestCache {
  private cache = new Map<string, Promise<any>>();
  private timestamps = new Map<string, number>();
  private readonly TTL = 5 * 60 * 1000; // 5 minutes

  get<T>(key: string, fetcher: () => Promise<T>): Promise<T> {
    const cached = this.cache.get(key);
    const timestamp = this.timestamps.get(key);
    
    // Return cached promise if still valid
    if (cached && timestamp && Date.now() - timestamp < this.TTL) {
      return cached;
    }
    
    // Create new request
    const promise = fetcher().finally(() => {
      // Remove from cache after completion
      setTimeout(() => {
        this.cache.delete(key);
        this.timestamps.delete(key);
      }, this.TTL);
    });
    
    this.cache.set(key, promise);
    this.timestamps.set(key, Date.now());
    
    return promise;
  }

  invalidate(key: string) {
    this.cache.delete(key);
    this.timestamps.delete(key);
  }

  clear() {
    this.cache.clear();
    this.timestamps.clear();
  }
}

export const requestCache = new RequestCache();

/**
 * Virtual scrolling utilities
 */
export function calculateVirtualScrollRange(
  containerHeight: number,
  itemHeight: number,
  scrollTop: number,
  totalItems: number,
  overscan: number = 5
) {
  const startIndex = Math.max(0, Math.floor(scrollTop / itemHeight) - overscan);
  const endIndex = Math.min(
    totalItems - 1,
    Math.ceil((scrollTop + containerHeight) / itemHeight) + overscan
  );
  
  const visibleItems = endIndex - startIndex + 1;
  const offsetY = startIndex * itemHeight;
  
  return {
    startIndex,
    endIndex,
    visibleItems,
    offsetY,
  };
}

/**
 * Batch state updates to reduce re-renders
 */
export function useBatchedUpdates() {
  const updatesRef = React.useRef<(() => void)[]>([]);
  const timeoutRef = React.useRef<NodeJS.Timeout | null>(null);
  
  const batchUpdate = useCallback((update: () => void) => {
    updatesRef.current.push(update);
    
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    
    timeoutRef.current = setTimeout(() => {
      const updates = [...updatesRef.current];
      updatesRef.current = [];
      updates.forEach(update => update());
    }, 0);
  }, []);
  
  React.useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);
  
  return batchUpdate;
}

// Add React import
import React from 'react';

/**
 * Platform Sales Settings Helper
 * 
 * Provides utilities for managing platform-wide sales defaults and constraints
 * that providers can override with their own settings.
 */

import { getSupabaseServer } from "@/lib/supabase/server";

export interface PlatformSalesDefaults {
  tax_rate_percent?: number;
  receipt_prefix?: string;
  receipt_next_number?: number;
  receipt_header?: string | null;
  receipt_footer?: string | null;
  gift_cards_enabled?: boolean;
  gift_card_terms?: string | null;
  service_charge_name?: string;
  service_charge_rate?: number;
  upselling_enabled?: boolean;
}

export interface PlatformSalesConstraints {
  max_tax_rate_percent?: number;
  required_receipt_fields?: string[];
  max_receipt_prefix_length?: number;
  min_receipt_next_number?: number;
  max_receipt_header_length?: number;
  max_receipt_footer_length?: number;
}

export interface PlatformSalesSettings {
  defaults?: PlatformSalesDefaults;
  constraints?: PlatformSalesConstraints;
}

const DEFAULT_SALES_SETTINGS: PlatformSalesSettings = {
  defaults: {
    tax_rate_percent: 0,
    receipt_prefix: "REC",
    receipt_next_number: 1,
    receipt_header: null,
    receipt_footer: null,
    gift_cards_enabled: false,
    gift_card_terms: null,
    service_charge_name: "Service Charge",
    service_charge_rate: 0,
    upselling_enabled: false,
  },
  constraints: {
    max_tax_rate_percent: 30,
    required_receipt_fields: ["receipt_number", "date", "total"],
    max_receipt_prefix_length: 20,
    min_receipt_next_number: 1,
    max_receipt_header_length: 2000,
    max_receipt_footer_length: 2000,
  },
};

/**
 * Get platform sales settings (defaults and constraints)
 */
export async function getPlatformSalesSettings(): Promise<PlatformSalesSettings> {
  try {
    const supabase = await getSupabaseServer();
    
    const { data: settings, error } = await supabase
      .from("platform_settings")
      .select("settings")
      .eq("is_active", true)
      .single();

    if (error || !settings) {
      return DEFAULT_SALES_SETTINGS;
    }

    const platformSettings = (settings as any).settings || {};
    const salesSettings: PlatformSalesSettings = platformSettings.sales || {};

    // Merge with defaults to ensure all fields are present
    return {
      defaults: {
        ...DEFAULT_SALES_SETTINGS.defaults,
        ...salesSettings.defaults,
      },
      constraints: {
        ...DEFAULT_SALES_SETTINGS.constraints,
        ...salesSettings.constraints,
      },
    };
  } catch (error) {
    console.error("Error loading platform sales settings:", error);
    return DEFAULT_SALES_SETTINGS;
  }
}

/**
 * Get platform sales defaults
 */
export async function getPlatformSalesDefaults(): Promise<PlatformSalesDefaults> {
  const settings = await getPlatformSalesSettings();
  return settings.defaults || DEFAULT_SALES_SETTINGS.defaults!;
}

/**
 * Get platform sales constraints
 */
export async function getPlatformSalesConstraints(): Promise<PlatformSalesConstraints> {
  const settings = await getPlatformSalesSettings();
  return settings.constraints || DEFAULT_SALES_SETTINGS.constraints!;
}

/**
 * Merge provider settings with platform defaults
 * Provider settings take precedence over platform defaults
 */
export function mergeWithPlatformDefaults<T extends Record<string, any>>(
  providerSettings: Partial<T>,
  platformDefaults: Partial<T>
): T {
  return {
    ...platformDefaults,
    ...providerSettings,
  } as T;
}

/**
 * Validate provider settings against platform constraints
 */
export function validateAgainstConstraints(
  field: string,
  value: any,
  constraints: PlatformSalesConstraints
): { valid: boolean; error?: string } {
  switch (field) {
    case "tax_rate_percent":
      if (typeof value === "number") {
        const maxRate = constraints.max_tax_rate_percent ?? 30;
        if (value < 0 || value > maxRate) {
          return {
            valid: false,
            error: `Tax rate must be between 0 and ${maxRate}%`,
          };
        }
      }
      break;

    case "receipt_prefix":
      if (typeof value === "string") {
        const maxLength = constraints.max_receipt_prefix_length ?? 20;
        if (value.length > maxLength) {
          return {
            valid: false,
            error: `Receipt prefix must be ${maxLength} characters or less`,
          };
        }
      }
      break;

    case "receipt_next_number":
      if (typeof value === "number") {
        const minNumber = constraints.min_receipt_next_number ?? 1;
        if (value < minNumber) {
          return {
            valid: false,
            error: `Receipt next number must be at least ${minNumber}`,
          };
        }
      }
      break;

    case "receipt_header":
      if (typeof value === "string") {
        const maxLength = constraints.max_receipt_header_length ?? 2000;
        if (value.length > maxLength) {
          return {
            valid: false,
            error: `Receipt header must be ${maxLength} characters or less`,
          };
        }
      }
      break;

    case "receipt_footer":
      if (typeof value === "string") {
        const maxLength = constraints.max_receipt_footer_length ?? 2000;
        if (value.length > maxLength) {
          return {
            valid: false,
            error: `Receipt footer must be ${maxLength} characters or less`,
          };
        }
      }
      break;
  }

  return { valid: true };
}

/**
 * Platform Service Fee Settings Helper
 * 
 * Provides utilities for getting the effective service fee based on:
 * 1. Provider's customer_fee_config_id (from platform_fee_config table)
 * 2. Platform default service fee (from platform_settings)
 * 3. Hardcoded fallback (10%)
 */

import { getSupabaseAdmin } from "@/lib/supabase/admin";

const DEFAULT_SERVICE_FEE_PERCENTAGE = 10.00; // 10% fallback

export interface ServiceFeeConfig {
  percentage: number;
  fixedAmount?: number;
  feeType: "percentage" | "fixed_amount";
  minBookingAmount?: number;
  maxFeeAmount?: number;
}

/**
 * Get the effective service fee configuration for a provider
 * Priority: provider customer_fee_config_id ΓåÆ platform default ΓåÆ 10% fallback
 * 
 * @param providerId - Provider ID
 * @param subtotal - Booking subtotal (for checking min_booking_amount)
 * @returns Service fee configuration
 */
export async function getEffectiveServiceFeeConfig(
  providerId: string,
  subtotal: number = 0
): Promise<ServiceFeeConfig> {
  try {
    const supabaseAdmin = await getSupabaseAdmin();
    
    // Get provider's customer_fee_config_id
    const { data: provider } = await supabaseAdmin
      .from("providers")
      .select("customer_fee_config_id")
      .eq("id", providerId)
      .single();
    
    if (provider?.customer_fee_config_id) {
      const { data: feeConfig } = await supabaseAdmin
        .from("platform_fee_config")
        .select("fee_type, fee_percentage, fee_fixed_amount, min_booking_amount, max_fee_amount")
        .eq("id", provider.customer_fee_config_id)
        .eq("is_active", true)
        .single();
      
      if (feeConfig) {
        const minBookingAmount = Number(feeConfig.min_booking_amount || 0);
        
        // Only apply fee if booking meets minimum amount
        if (subtotal >= minBookingAmount) {
          if (feeConfig.fee_type === "percentage") {
            const percentage = Number(feeConfig.fee_percentage || 0);
            if (percentage > 0) {
              return {
                percentage,
                feeType: "percentage",
                minBookingAmount,
                maxFeeAmount: feeConfig.max_fee_amount ? Number(feeConfig.max_fee_amount) : undefined,
              };
            }
          } else if (feeConfig.fee_type === "fixed_amount") {
            const fixedAmount = Number(feeConfig.fee_fixed_amount || 0);
            if (fixedAmount > 0) {
              return {
                percentage: 0,
                fixedAmount,
                feeType: "fixed_amount",
                minBookingAmount,
              };
            }
          }
        }
      }
    }
    
    // Fallback to platform settings
    const { data: platformSettings } = await supabaseAdmin
      .from("platform_settings")
      .select("settings")
      .eq("is_active", true)
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    
    if (platformSettings?.settings) {
      const payoutSettings = (platformSettings.settings as any)?.payouts || {};
      const serviceFeeType = payoutSettings.platform_service_fee_type || "percentage";
      const fallbackFeePercentage = payoutSettings.platform_service_fee_percentage || 0;
      const fallbackFeeFixed = payoutSettings.platform_service_fee_fixed || 0;
      
      if (serviceFeeType === "percentage" && fallbackFeePercentage > 0) {
        return {
          percentage: fallbackFeePercentage,
          feeType: "percentage",
        };
      } else if (serviceFeeType === "fixed_amount" && fallbackFeeFixed > 0) {
        return {
          percentage: 0,
          fixedAmount: fallbackFeeFixed,
          feeType: "fixed_amount",
        };
      }
    }
    
    // Fallback to hardcoded default
    return {
      percentage: DEFAULT_SERVICE_FEE_PERCENTAGE,
      feeType: "percentage",
    };
  } catch (error) {
    console.warn("Failed to get service fee config from database, using fallback:", error);
    return {
      percentage: DEFAULT_SERVICE_FEE_PERCENTAGE,
      feeType: "percentage",
    };
  }
}

/**
 * Calculate service fee amount based on configuration and subtotal
 * 
 * @param config - Service fee configuration
 * @param subtotal - Booking subtotal (after discounts)
 * @returns Service fee amount
 */
export function calculateServiceFeeAmount(
  config: ServiceFeeConfig,
  subtotal: number
): number {
  if (config.minBookingAmount && subtotal < config.minBookingAmount) {
    return 0;
  }
  
  if (config.feeType === "fixed_amount" && config.fixedAmount) {
    return config.fixedAmount;
  }
  
  if (config.feeType === "percentage" && config.percentage > 0) {
    let amount = (subtotal * config.percentage) / 100;
    
    // Apply max fee cap if set
    if (config.maxFeeAmount) {
      amount = Math.min(amount, config.maxFeeAmount);
    }
    
    return Number(amount.toFixed(2));
  }
  
  return 0;
}

/**
 * Get the platform default service fee percentage
 * @returns Service fee percentage (e.g., 10.00 for 10%)
 */
export async function getPlatformDefaultServiceFeePercentage(): Promise<number> {
  try {
    const supabaseAdmin = await getSupabaseAdmin();
    
    const { data: platformSettings } = await supabaseAdmin
      .from("platform_settings")
      .select("settings")
      .eq("is_active", true)
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    
    if (platformSettings?.settings) {
      const payoutSettings = (platformSettings.settings as any)?.payouts || {};
      const serviceFeeType = payoutSettings.platform_service_fee_type || "percentage";
      const fallbackFeePercentage = payoutSettings.platform_service_fee_percentage || 0;
      
      if (serviceFeeType === "percentage" && fallbackFeePercentage > 0) {
        return fallbackFeePercentage;
      }
    }
    
    return DEFAULT_SERVICE_FEE_PERCENTAGE;
  } catch (error) {
    console.warn("Failed to get platform default service fee, using fallback:", error);
    return DEFAULT_SERVICE_FEE_PERCENTAGE;
  }
}

/**
 * Platform Settings Helper
 * 
 * Utility functions to get platform-wide settings
 */

import { getSupabaseServer } from "@/lib/supabase/server";

export interface VerificationSettings {
  otp_enabled: boolean;
  qr_code_enabled: boolean;
  require_verification: boolean;
}

/**
 * Get verification settings from platform settings
 */
export async function getVerificationSettings(): Promise<VerificationSettings> {
  try {
    const supabase = await getSupabaseServer();
    
    const { data: platformSettings, error } = await supabase
      .from("platform_settings")
      .select("settings")
      .eq("is_active", true)
