import type { SupabaseClient } from "@supabase/supabase-js";

/**
 * Compute available balance for payout (ledger-based):
 * - Sum provider_earnings (net) excluding direct walk-in (cash/Yoco) ΓÇö platform doesn't hold that money.
 * - Subtract completed payouts (finance_transactions type 'payout').
 * - Subtract pending/processing payout requests (payouts table).
 */
export async function getAvailablePayoutBalance(
  supabase: SupabaseClient,
  providerId: string
): Promise<{ availableBalance: number; pendingPayoutsSum: number }> {
  const allTime = "1970-01-01T00:00:00.000Z";
  const nowIso = new Date().toISOString();

  const { data: ledgerRows, error: ledgerError } = await supabase
    .from("finance_transactions")
    .select("id, transaction_type, amount, net, created_at, booking_id")
    .eq("provider_id", providerId)
    .in("transaction_type", ["provider_earnings", "payout"])
    .gte("created_at", allTime)
    .lte("created_at", nowIso)
    .order("created_at", { ascending: false });

  if (ledgerError) throw ledgerError;
  const rows = ledgerRows || [];

  const bookingIds = [...new Set(rows.filter((r: any) => r.booking_id).map((r: any) => r.booking_id))];
  let bookingMap: Record<string, { booking_source: string | null; payment_provider: string | null }> = {};

  if (bookingIds.length > 0) {
    const { data: bookings } = await supabase
      .from("bookings")
      .select("id, booking_source")
      .in("id", bookingIds);
    const { data: bookingPayments } = await supabase
      .from("booking_payments")
      .select("booking_id, payment_provider")
      .in("booking_id", bookingIds)
      .eq("status", "completed")
      .order("created_at", { ascending: false });

    if (bookings) {
      bookingMap = bookings.reduce((acc: any, b: any) => {
        const payment = bookingPayments?.find((p: any) => p.booking_id === b.id);
        acc[b.id] = {
          booking_source: b.booking_source || null,
          payment_provider: payment?.payment_provider || null,
        };
        return acc;
      }, {});
    }
  }

  let onlineEarnings = 0;
  let completedPayouts = 0;

  for (const r of rows) {
    const row = r as any;
    if (row.transaction_type === "payout") {
      completedPayouts += Number(row.amount || 0);
      continue;
    }
    if (row.transaction_type !== "provider_earnings") continue;
    // Exclude direct walk-in (platform doesn't hold the money)
    if (row.booking_id && bookingMap[row.booking_id]?.booking_source === "walk_in") {
      if (bookingMap[row.booking_id]?.payment_provider !== "paystack") continue;
    }
    onlineEarnings += Number(row.net ?? row.amount ?? 0);
  }

  const { data: pendingRows } = await supabase
    .from("payouts")
    .select("amount")
    .eq("provider_id", providerId)
    .in("status", ["pending", "processing"]);

  const pendingPayoutsSum = (pendingRows || []).reduce((s, p: any) => s + Number(p.amount || 0), 0);
  const availableBalance = Math.max(0, onlineEarnings - completedPayouts - pendingPayoutsSum);

  return { availableBalance, pendingPayoutsSum };
}

import { SupabaseClient } from "@supabase/supabase-js";

import { MAX_FINANCE_TRANSACTIONS } from "./constants";

/**
 * Get provider earnings from finance_transactions
 * This returns the actual net amount the provider receives (after platform commission)
 * 
 * Note: This automatically excludes walk-in bookings paid directly (cash/yoco) because
 * those don't create finance_transactions (provider received payment directly).
 * Only includes:
 * - Online bookings (always have finance_transactions)
 * - Walk-in bookings paid via Paystack (platform holds the money, creates finance_transactions)
 */
export async function getProviderRevenue(
  supabaseAdmin: SupabaseClient,
  providerId: string,
  fromDate: Date,
  toDate: Date,
  locationId?: string | null
): Promise<{
  totalRevenue: number;
  revenueByBooking: Map<string, number>;
  revenueByDate: Map<string, number>;
}> {
  // Get provider earnings from finance_transactions
  // This only includes transactions where the platform processed payment
  // (excludes walk-in bookings paid directly to provider)
  const { data: financeTransactions } = await supabaseAdmin
    .from("finance_transactions")
    .select("id, transaction_type, amount, net, booking_id, created_at")
    .eq("provider_id", providerId)
    .in("transaction_type", ["provider_earnings", "travel_fee", "tip"])
    .gte("created_at", fromDate.toISOString())
    .lte("created_at", toDate.toISOString())
    .order("created_at", { ascending: false })
    .limit(MAX_FINANCE_TRANSACTIONS);

  // Get booking information for filtering by location if needed
  const financeBookingIds = [
    ...new Set(
      (financeTransactions || [])
        .filter((t: any) => t.booking_id)
        .map((t: any) => t.booking_id)
    ),
  ];
  let bookingMap: Record<string, { location_id: string | null }> = {};

  if (locationId && financeBookingIds.length > 0) {
    const { data: bookingsForFinance } = await supabaseAdmin
      .from("bookings")
      .select("id, location_id")
      .in("id", financeBookingIds);

    if (bookingsForFinance) {
      bookingMap = bookingsForFinance.reduce((acc: any, b: any) => {
        acc[b.id] = { location_id: b.location_id || null };
        return acc;
      }, {});
    }
  }

  // Filter transactions by location if needed
  const validTransactions = (financeTransactions || []).filter((t: any) => {
    if (!t.booking_id) return true; // Include non-booking transactions
    if (locationId && bookingMap[t.booking_id]?.location_id !== locationId)
      return false;
    return true;
  });

  // Calculate total revenue
  const totalRevenue = validTransactions.reduce(
    (sum: number, t: any) => sum + Number(t.net || t.amount || 0),
    0
  );

  // Group by booking
  const revenueByBooking = new Map<string, number>();
  validTransactions.forEach((t: any) => {
    if (t.booking_id) {
      const current = revenueByBooking.get(t.booking_id) || 0;
      revenueByBooking.set(
        t.booking_id,
        current + Number(t.net || t.amount || 0)
      );
    }
  });

  // Group by date
  const revenueByDate = new Map<string, number>();
  validTransactions.forEach((t: any) => {
    const date = new Date(t.created_at).toISOString().split("T")[0];
    const current = revenueByDate.get(date) || 0;
    revenueByDate.set(date, current + Number(t.net || t.amount || 0));
  });

  return {
    totalRevenue,
    revenueByBooking,
    revenueByDate,
  };
}

/**
 * Get provider revenue for previous period (for growth calculations)
 */
export async function getPreviousPeriodRevenue(
  supabaseAdmin: SupabaseClient,
  providerId: string,
  fromDate: Date,
  toDate: Date,
  locationId?: string | null
): Promise<number> {
  const daysDiff = Math.ceil(
    (toDate.getTime() - fromDate.getTime()) / (1000 * 60 * 60 * 24)
  );
  const prevFromDate = new Date(fromDate.getTime() - daysDiff * 24 * 60 * 60 * 1000);
  const prevToDate = fromDate;

  const result = await getProviderRevenue(
    supabaseAdmin,
    providerId,
    prevFromDate,
    prevToDate,
    locationId
  );

  return result.totalRevenue;
}

/**
 * Resource Assignment Utilities
 * Handles resource assignment to bookings and conflict checking
 */

import { SupabaseClient } from '@supabase/supabase-js';

export interface ResourceRequirement {
  resource_id: string;
  required: boolean; // If false, resource is optional
}

export interface ResourceAssignment {
  booking_id: string;
  booking_service_id?: string;
  resource_id: string;
  scheduled_start_at: string;
  scheduled_end_at: string;
}

/**
 * Check if resources are available for a time slot
 */
export async function checkResourceAvailability(
  supabase: SupabaseClient,
  resourceIds: string[],
  startAt: Date,
  endAt: Date,
  excludeBookingId?: string
): Promise<{ available: boolean; conflicts: Array<{ resource_id: string; reason: string }> }> {
  if (resourceIds.length === 0) {
    return { available: true, conflicts: [] };
  }

  const conflicts: Array<{ resource_id: string; reason: string }> = [];

  // Check each resource
  for (const resourceId of resourceIds) {
    // Get resource capacity
    const { data: resource } = await supabase
      .from('resources')
      .select('id, capacity')
      .eq('id', resourceId)
      .single();

    if (!resource) {
      conflicts.push({ resource_id: resourceId, reason: 'Resource not found' });
      continue;
    }

    // Count concurrent bookings for this resource
    const { data: existingBookings, error } = await supabase
      .from('booking_resources')
      .select('id, booking_id')
      .eq('resource_id', resourceId)
      .lt('scheduled_start_at', endAt.toISOString())
      .gt('scheduled_end_at', startAt.toISOString())
      .neq('booking_id', excludeBookingId || '00000000-0000-0000-0000-000000000000'); // Exclude current booking if rescheduling

    if (error) {
      console.error('Error checking resource availability:', error);
      conflicts.push({ resource_id: resourceId, reason: 'Error checking availability' });
      continue;
    }

    // Check if at capacity
    const concurrentCount = existingBookings?.length || 0;
    if (concurrentCount >= resource.capacity) {
      conflicts.push({ resource_id: resourceId, reason: `Resource at capacity (${resource.capacity})` });
    }
  }

  return {
    available: conflicts.length === 0,
    conflicts,
  };
}

/**
 * Assign resources to a booking
 */
export async function assignResourcesToBooking(
  supabase: SupabaseClient,
  assignments: ResourceAssignment[]
): Promise<void> {
  if (assignments.length === 0) {
    return;
  }

  const { error } = await supabase
    .from('booking_resources')
    .insert(assignments);

  if (error) {
    throw new Error(`Failed to assign resources: ${error.message}`);
  }
}

/**
 * Get required resources for an offering
 */
export async function getRequiredResourcesForOffering(
  supabase: SupabaseClient,
  offeringId: string
): Promise<string[]> {
  // Check if offering_resources table exists
  const { data: offeringResources, error } = await supabase
    .from('offering_resources')
    .select('resource_id, required')
    .eq('offering_id', offeringId);

  if (error) {
    // Table might not exist, return empty array
    if (error.code === '42P01') {
      return [];
    }
    console.error('Error loading required resources:', error);
    return [];
  }

  // Return only required resources
  return (offeringResources || [])
    .filter((or: any) => or.required === true)
    .map((or: any) => or.resource_id);
}

/**
 * Scheduler Utilities
 * 
 * Helper functions for calendar operations.
 */

import { format, addDays, startOfWeek, isSameDay, getDay } from "date-fns";
import type { CalendarEvent, CalendarTimeBlock, ConflictValidation } from "./types";

/**
 * Generate time slots for a given range
 */
export function generateTimeSlots(
  startHour: number,
  endHour: number,
  slotDuration: number = 60
): string[] {
  const slots: string[] = [];
  const totalMinutes = (endHour - startHour) * 60;
  const slotCount = Math.floor(totalMinutes / slotDuration);
  
  for (let i = 0; i <= slotCount; i++) {
    const totalMins = startHour * 60 + i * slotDuration;
    const hour = Math.floor(totalMins / 60);
    const min = totalMins % 60;
    
    if (hour <= endHour) {
      slots.push(`${hour.toString().padStart(2, "0")}:${min.toString().padStart(2, "0")}`);
    }
  }
  
  return slots;
}

/**
 * Get dates for calendar view
 */
export function getDatesForView(
  selectedDate: Date,
  view: "day" | "week" | "3-days"
): Date[] {
  const dates: Date[] = [];
  
  if (view === "day") {
    dates.push(new Date(selectedDate));
  } else if (view === "3-days") {
    for (let i = 0; i < 3; i++) {
      dates.push(addDays(selectedDate, i));
    }
  } else {
    // Week view
    const weekStart = startOfWeek(selectedDate, { weekStartsOn: 1 });
    for (let i = 0; i < 7; i++) {
      dates.push(addDays(weekStart, i));
    }
  }
  
  return dates;
}

/**
 * Check if date is weekend
 */
export function isWeekend(date: Date): boolean {
  const day = getDay(date);
  return day === 0 || day === 6; // Sunday or Saturday
}

/**
 * Get events for a specific date and resource
 */
export function getEventsForDateAndResource(
  events: CalendarEvent[],
  date: Date,
  resourceId: string
): CalendarEvent[] {
  const dateStr = format(date, "yyyy-MM-dd");
  return events.filter(
    event => event.date === dateStr && event.resourceId === resourceId
  );
}

/**
 * Get time blocks for a specific date and resource
 */
export function getTimeBlocksForDateAndResource(
  timeBlocks: CalendarTimeBlock[],
  date: Date,
  resourceId: string
): CalendarTimeBlock[] {
  const dateStr = format(date, "yyyy-MM-dd");
  return timeBlocks.filter(
    block => block.date === dateStr && block.resourceId === resourceId
  );
}

/**
 * Check for appointment conflicts
 */
export function checkConflicts(
  newEvent: {
    date: string;
    startTime: string;
    endTime: string;
    resourceId: string;
  },
  existingEvents: CalendarEvent[],
  excludeEventId?: string
): ConflictValidation {
  const conflicts: Array<{ appointmentId: string; reason: string }> = [];
  
  // Filter events for same date and resource
  const relevantEvents = existingEvents.filter(
    event =>
      event.date === newEvent.date &&
      event.resourceId === newEvent.resourceId &&
      event.id !== excludeEventId
  );
  
  // Check for time overlaps
  for (const event of relevantEvents) {
    if (timeRangesOverlap(
      newEvent.startTime,
      newEvent.endTime,
      event.startTime,
      event.endTime
    )) {
      conflicts.push({
        appointmentId: event.id,
        reason: `Overlaps with ${event.title} (${event.startTime} - ${event.endTime})`,
      });
    }
  }
  
  return {
    hasConflict: conflicts.length > 0,
    conflicts,
    canOverride: true, // Allow override with warning
  };
}

/**
 * Check if two time ranges overlap
 */
export function timeRangesOverlap(
  start1: string,
  end1: string,
  start2: string,
  end2: string
): boolean {
  const [h1, m1] = start1.split(":").map(Number);
  const [h2, m2] = end1.split(":").map(Number);
  const [h3, m3] = start2.split(":").map(Number);
  const [h4, m4] = end2.split(":").map(Number);
  
  const mins1 = h1 * 60 + m1;
  const mins2 = h2 * 60 + m2;
  const mins3 = h3 * 60 + m3;
  const mins4 = h4 * 60 + m4;
  
  return mins1 < mins4 && mins2 > mins3;
}

/**
 * Snap time to nearest interval
 */
export function snapToInterval(
  time: string,
  intervalMinutes: number = 15
): string {
  const [hour, min] = time.split(":").map(Number);
  const totalMinutes = hour * 60 + min;
  const snappedMinutes = Math.round(totalMinutes / intervalMinutes) * intervalMinutes;
  const snappedHour = Math.floor(snappedMinutes / 60);
  const snappedMin = snappedMinutes % 60;
  
  return `${snappedHour.toString().padStart(2, "0")}:${snappedMin.toString().padStart(2, "0")}`;
}

/**
 * Get current time as HH:MM
 */
export function getCurrentTime(): string {
  const now = new Date();
  return `${now.getHours().toString().padStart(2, "0")}:${now.getMinutes().toString().padStart(2, "0")}`;
}

/**
 * Check if time is in the past
 */
export function isTimePast(date: string, time: string): boolean {
  const appointmentDate = new Date(`${date}T${time}`);
  return appointmentDate < new Date();
}

/**
 * Sort events by start time
 */
export function sortEventsByTime(events: CalendarEvent[]): CalendarEvent[] {
  return [...events].sort((a, b) => {
    if (a.date !== b.date) {
      return a.date.localeCompare(b.date);
    }
    return a.startTime.localeCompare(b.startTime);
  });
}

/**
 * Group events by date
 */
export function groupEventsByDate(events: CalendarEvent[]): Map<string, CalendarEvent[]> {
  const grouped = new Map<string, CalendarEvent[]>();
  
  for (const event of events) {
    if (!grouped.has(event.date)) {
      grouped.set(event.date, []);
    }
    grouped.get(event.date)!.push(event);
  }
  
  return grouped;
}

/**
 * Group events by resource
 */
export function groupEventsByResource(events: CalendarEvent[]): Map<string, CalendarEvent[]> {
  const grouped = new Map<string, CalendarEvent[]>();
  
  for (const event of events) {
    if (!grouped.has(event.resourceId)) {
      grouped.set(event.resourceId, []);
    }
    grouped.get(event.resourceId)!.push(event);
  }
  
  return grouped;
}

/**
 * Calculate total duration for events
 */
export function calculateTotalDuration(events: CalendarEvent[]): number {
  return events.reduce((total, event) => total + event.duration, 0);
}

/**
 * Format duration for display
 */
export function formatDuration(minutes: number): string {
  const hours = Math.floor(minutes / 60);
  const mins = minutes % 60;
  
  if (hours === 0) {
    return `${mins}m`;
  } else if (mins === 0) {
    return `${hours}h`;
  } else {
    return `${hours}h ${mins}m`;
  }
}

/**
 * Get date range label
 */
export function getDateRangeLabel(dates: Date[]): string {
  if (dates.length === 0) return "";
  if (dates.length === 1) return format(dates[0], "EEE, MMM d, yyyy");
  
  const first = dates[0];
  const last = dates[dates.length - 1];
  
  if (isSameDay(first, last)) {
    return format(first, "EEE, MMM d, yyyy");
  }
  
  return `${format(first, "MMM d")} - ${format(last, "d, yyyy")}`;
}

/**
 * Get short day label
 */
export function getShortDayLabel(date: Date): string {
  return format(date, "EEE d");
}

/**
 * Get time label with optional 12-hour format
 */
export function getTimeLabel(time: string, use12Hour: boolean = true): string {
  if (!use12Hour) return time;
  
  const [hour, min] = time.split(":").map(Number);
  const period = hour >= 12 ? "PM" : "AM";
  const displayHour = hour > 12 ? hour - 12 : hour === 0 ? 12 : hour;
  
  // Only show minutes if not on the hour
  if (min === 0) {
    return `${displayHour} ${period}`;
  }
  
  return `${displayHour}:${min.toString().padStart(2, "0")} ${period}`;
}

/**
 * Debounce function
 */
export function debounce<T extends (...args: any[]) => unknown>(
  func: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeout: NodeJS.Timeout | null = null;
  
  return function executedFunction(...args: Parameters<T>) {
    const later = () => {
      timeout = null;
      func(...args);
    };
    
    if (timeout) clearTimeout(timeout);
    timeout = setTimeout(later, wait);
  };
}

/**
 * Throttle function
 */
export function throttle<T extends (...args: any[]) => unknown>(
  func: T,
  limit: number
): (...args: Parameters<T>) => void {
  let inThrottle: boolean = false;
  
  return function executedFunction(...args: Parameters<T>) {
    if (!inThrottle) {
      func(...args);
      inThrottle = true;
      setTimeout(() => (inThrottle = false), limit);
    }
  };
}

/**
 * Deep clone object
 */
export function deepClone<T>(obj: T): T {
  return JSON.parse(JSON.stringify(obj));
}

/**
 * Create cache key from parameters
 */
export function createCacheKey(params: Record<string, any>): string {
  return Object.entries(params)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([key, value]) => `${key}:${value}`)
    .join("|");
}

/**
 * Concurrency Safety Utilities
 * 
 * Provides optimistic locking for appointment and time block mutations.
 * Uses version/updatedAt to detect stale data conflicts.
 * 
 * @module lib/scheduling/concurrency
 */

import { toast } from "sonner";

// ============================================================================
// TYPES
// ============================================================================

export interface VersionedEntity {
  id: string;
  version?: number;
  updated_at?: string;
}

export interface OptimisticLockError {
  type: "STALE_VERSION";
  message: string;
  currentVersion?: number;
  attemptedVersion?: number;
  serverUpdatedAt?: string;
}

export interface MutationOptions<T> {
  /** The entity being updated */
  entity: T & VersionedEntity;
  /** The mutation function to execute */
  mutation: () => Promise<T>;
  /** Callback when conflict is detected */
  onConflict?: (error: OptimisticLockError) => void;
  /** Callback to refetch the entity */
  onRefetch?: () => Promise<T>;
  /** Show default toast on conflict */
  showToast?: boolean;
}

// ============================================================================
// CONFLICT DETECTION
// ============================================================================

/**
 * Check if server response indicates a version conflict
 */
export function isVersionConflict(error: any): boolean {
  // Check for common conflict status codes
  if (error?.status === 409 || error?.status === 412) {
    return true;
  }
  
  // Check for conflict message in response
  const message = error?.message?.toLowerCase() || "";
  const errorCode = error?.code?.toLowerCase() || "";
  
  return (
    message.includes("version") ||
    message.includes("conflict") ||
    message.includes("stale") ||
    message.includes("updated by another") ||
    message.includes("concurrent") ||
    errorCode === "version_conflict" ||
    errorCode === "stale_entity"
  );
}

/**
 * Extract conflict details from error response
 */
export function extractConflictDetails(error: any): OptimisticLockError {
  return {
    type: "STALE_VERSION",
    message: error?.message || "This record was updated elsewhere. Please refresh and try again.",
    currentVersion: error?.data?.currentVersion,
    attemptedVersion: error?.data?.attemptedVersion,
    serverUpdatedAt: error?.data?.serverUpdatedAt,
  };
}

// ============================================================================
// OPTIMISTIC LOCKING WRAPPER
// ============================================================================

/**
 * Execute a mutation with optimistic locking support
 * 
 * If a version conflict is detected:
 * 1. Shows a toast notification (if enabled)
 * 2. Calls onConflict callback
 * 3. Optionally refetches the entity
 */
export async function withOptimisticLock<T>({
  entity: _entity,
  mutation,
  onConflict,
  onRefetch,
  showToast = true,
}: MutationOptions<T>): Promise<{ success: boolean; data?: T; conflict?: OptimisticLockError }> {
  try {
    const result = await mutation();
    return { success: true, data: result };
  } catch (error: any) {
    if (isVersionConflict(error)) {
      const conflictDetails = extractConflictDetails(error);
      
      if (showToast) {
        toast.error("This record was updated elsewhere", {
          description: "Please refresh to see the latest changes.",
          action: onRefetch ? {
            label: "Refresh",
            onClick: () => onRefetch(),
          } : undefined,
        });
      }
      
      onConflict?.(conflictDetails);
      
      // Optionally auto-refetch
      if (onRefetch) {
        try {
          await onRefetch();
        } catch (refetchError) {
          console.error("Failed to refetch after conflict:", refetchError);
        }
      }
      
      return { success: false, conflict: conflictDetails };
    }
    
    // Re-throw non-conflict errors
    throw error;
  }
}

// ============================================================================
// VERSION HEADER UTILS
// ============================================================================

/**
 * Add version headers to a fetch request
 */
export function addVersionHeaders(
  headers: Record<string, string>,
  entity: VersionedEntity
): Record<string, string> {
  const newHeaders = { ...headers };
  
  if (entity.version !== undefined) {
    newHeaders["If-Match"] = String(entity.version);
  }
  
  if (entity.updated_at) {
    newHeaders["If-Unmodified-Since"] = entity.updated_at;
  }
  
  return newHeaders;
}

/**
 * Create version payload for mutations
 */
export function createVersionPayload(entity: VersionedEntity): Record<string, any> {
  const payload: Record<string, any> = {};
  
  if (entity.version !== undefined) {
    payload.expected_version = entity.version;
  }
  
  if (entity.updated_at) {
    payload.expected_updated_at = entity.updated_at;
  }
  
  return payload;
}

// ============================================================================
// REACT HOOK
// ============================================================================

import { useCallback, useState } from "react";

interface UseConcurrentMutationOptions<T> {
  onSuccess?: (data: T) => void;
  onError?: (error: any) => void;
  onConflict?: (error: OptimisticLockError) => void;
  refetch?: () => Promise<T>;
}

/**
 * React hook for concurrent-safe mutations
 */
export function useConcurrentMutation<T, Args extends unknown[]>(
  mutationFn: (...args: Args) => Promise<T>,
  options: UseConcurrentMutationOptions<T> = {}
) {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<any>(null);
  const [hasConflict, setHasConflict] = useState(false);

  const mutate = useCallback(async (...args: Args): Promise<{ success: boolean; data?: T }> => {
    setIsLoading(true);
    setError(null);
    setHasConflict(false);

    try {
      const result = await mutationFn(...args);
      options.onSuccess?.(result);
      setIsLoading(false);
      return { success: true, data: result };
    } catch (err: any) {
      setIsLoading(false);
      
      if (isVersionConflict(err)) {
        setHasConflict(true);
        const conflictDetails = extractConflictDetails(err);
        
        toast.error("Record was updated elsewhere", {
          description: "Please refresh to see the latest changes.",
        });
        
        options.onConflict?.(conflictDetails);
        
        // Auto-refetch if provided
        if (options.refetch) {
          try {
            await options.refetch();
          } catch (refetchError) {
            console.error("Failed to refetch after conflict:", refetchError);
          }
        }
        
        return { success: false };
      }
      
      setError(err);
      options.onError?.(err);
      throw err;
    }
  }, [mutationFn, options]);

  const reset = useCallback(() => {
    setError(null);
    setHasConflict(false);
  }, []);

  return {
    mutate,
    isLoading,
    error,
    hasConflict,
    reset,
  };
}

// ============================================================================
// BATCH MUTATION SUPPORT
// ============================================================================

interface BatchMutationItem<T> {
  id: string;
  entity: T & VersionedEntity;
  mutation: () => Promise<T>;
}

interface BatchMutationResult<T> {
  successful: Array<{ id: string; data: T }>;
  failed: Array<{ id: string; error: any; isConflict: boolean }>;
}

/**
 * Execute multiple mutations with conflict detection
 * Continues processing even if some items conflict
 */
export async function batchMutateWithConflictDetection<T>(
  items: BatchMutationItem<T>[]
): Promise<BatchMutationResult<T>> {
  const result: BatchMutationResult<T> = {
    successful: [],
    failed: [],
  };

  for (const item of items) {
    try {
      const data = await item.mutation();
      result.successful.push({ id: item.id, data });
    } catch (error: any) {
      result.failed.push({
        id: item.id,
        error,
        isConflict: isVersionConflict(error),
      });
    }
  }

  // Show summary toast if there were conflicts
  const conflicts = result.failed.filter(f => f.isConflict);
  if (conflicts.length > 0) {
    toast.error(`${conflicts.length} item(s) had conflicts`, {
      description: "These records were updated elsewhere. Please refresh.",
    });
  }

  return result;
}

/**
 * Mangomint Adapter Layer
 * 
 * Maps existing Beautonomi types to Mangomint-like semantic models.
 * This adapter allows the UI to use consistent Mangomint semantics
 * while preserving existing data structures.
 * 
 * @module lib/scheduling/mangomintAdapter
 */

import type { Appointment, TimeBlock } from "@/lib/provider-portal/types";
import { addMinutes, parseISO } from "date-fns";
import { APPOINTMENT_STATUS } from "@/lib/provider-portal/constants";

// ============================================================================
// ENUMS - Mangomint Semantic Types
// ============================================================================

/**
 * Appointment status following Mangomint semantics
 */
export enum AppointmentStatus {
  UNCONFIRMED = "UNCONFIRMED",
  CONFIRMED = "CONFIRMED",
  WAITING = "WAITING",
  IN_SERVICE = "IN_SERVICE",
  COMPLETED = "COMPLETED",
  CANCELED = "CANCELED",
  NO_SHOW = "NO_SHOW",
}

/**
 * Appointment kind (booking type)
 */
export enum AppointmentKind {
  IN_SALON = "IN_SALON",
  WALK_IN = "WALK_IN",
  AT_HOME = "AT_HOME",
}

/**
 * Visual segment types within an appointment block
 */
export enum SegmentKind {
  SERVICE = "SERVICE",       // Main service time - solid fill
  BUFFER = "BUFFER",         // Buffer between clients - outlined
  PROCESSING = "PROCESSING", // Processing time (color developing) - semi-transparent
  FINISHING = "FINISHING",   // Finishing time - lighter fill
  TRAVEL = "TRAVEL",         // Travel time for at-home - striped
}

/**
 * Calendar block types
 */
export enum BlockKind {
  APPOINTMENT = "APPOINTMENT",
  TIME_BLOCK = "TIME_BLOCK",
  TRAVEL_BLOCK = "TRAVEL_BLOCK",
}

// ============================================================================
// VIEW MODEL TYPES
// ============================================================================

/**
 * A time segment within an appointment (for visual rendering)
 */
export interface AppointmentSegment {
  kind: SegmentKind;
  startTime: string; // HH:mm format
  endTime: string;   // HH:mm format
  durationMinutes: number;
}

/**
 * Icon flags for appointment metadata display
 */
export interface AppointmentIconFlags {
  isNewClient: boolean;
  hasNotes: boolean;
  isRepeating: boolean;
  hasMembership: boolean;
  hasFormsIncomplete: boolean;
  hasPhotos: boolean;
  hasConversation: boolean;
  isGroup: boolean;
  requestedProvider: boolean;
  requestedGender: string | null;
  hasCustomization: boolean;
  isWalkIn: boolean;
  isAtHome: boolean;
}

/**
 * Mangomint-style appointment view model
 */
export interface MangomintAppointment {
  // Core identity
  id: string;
  refNumber: string;
  
  // Timing (UTC stored, localized for display)
  startTimeUtc: Date;
  endTimeUtc: Date;
  startTimeLocal: string; // Display string
  endTimeLocal: string;   // Display string
  durationMinutes: number;
  
  // Relationships
  staffId: string;
  staffName: string;
  locationId: string | null;
  locationName: string | null;
  clientId: string | null;
  clientName: string;
  clientEmail: string | null;
  clientPhone: string | null;
  
  // Service info
  serviceName: string;
  serviceId: string;
  price: number;
  
  // Mangomint semantics
  status: AppointmentStatus;
  kind: AppointmentKind;
  
  // Visual segments
  segments: AppointmentSegment[];
  
  // Icon flags
  iconFlags: AppointmentIconFlags;
  
  // At-home specific
  address: string | null;
  travelFee: number | null;
  travelTimeMinutes: number | null;
  
  // Original appointment for mutations
  _original: Appointment;
}

/**
 * Mangomint-style calendar block (time block or travel block)
 */
export interface MangomintBlock {
  id: string;
  kind: BlockKind;
  staffId: string;
  startTime: string;
  endTime: string;
  durationMinutes: number;
  name: string;
  description?: string;
  color?: string;
  _original: TimeBlock;
}

// ============================================================================
// MAPPING FUNCTIONS
// ============================================================================

/**
 * Map existing appointment status to Mangomint semantic status.
 * For in-salon bookings: when status is booked/confirmed AND current_stage is 'client_arrived',
 * the client has checked in ΓåÆ WAITING (ready for service).
 */
export function mapStatus(
  statusOrAppointment: Appointment["status"] | Pick<Appointment, "status" | "current_stage" | "location_type">
): AppointmentStatus {
  const status = typeof statusOrAppointment === "string"
    ? statusOrAppointment
    : statusOrAppointment.status;
  const currentStage = typeof statusOrAppointment === "string" ? undefined : (statusOrAppointment as any).current_stage;
  const locationType = typeof statusOrAppointment === "string" ? undefined : (statusOrAppointment as any).location_type;

  // In-salon: status is booked/confirmed and client has arrived ΓåÆ WAITING (client checked in, ready for service)
  // Note: API may return "confirmed" (database format) which maps to "booked"
  const statusStr = status as string;
  if (
    (status === APPOINTMENT_STATUS.BOOKED || statusStr === "booked" || statusStr === "confirmed") &&
    currentStage === "client_arrived" &&
    locationType !== "at_home"
  ) {
    return AppointmentStatus.WAITING;
  }

  switch (status) {
    case APPOINTMENT_STATUS.PENDING:
    case "pending":
      return AppointmentStatus.UNCONFIRMED;
    case APPOINTMENT_STATUS.BOOKED:
    case "booked":
    case "confirmed":
      return AppointmentStatus.CONFIRMED;
    case APPOINTMENT_STATUS.STARTED:
    case "started":
    case "in_progress":
      return AppointmentStatus.IN_SERVICE;
    case APPOINTMENT_STATUS.COMPLETED:
    case "completed":
      return AppointmentStatus.COMPLETED;
    case APPOINTMENT_STATUS.CANCELLED:
    case "cancelled":
      return AppointmentStatus.CANCELED;
    case APPOINTMENT_STATUS.NO_SHOW:
    case "no_show":
      return AppointmentStatus.NO_SHOW;
    default:
      return AppointmentStatus.CONFIRMED;
  }
}

/**
 * Map Mangomint status back to existing appointment status
 */
export function unmapStatus(status: AppointmentStatus): Appointment["status"] {
  switch (status) {
    case AppointmentStatus.UNCONFIRMED:
      return APPOINTMENT_STATUS.PENDING;
    case AppointmentStatus.CONFIRMED:
      return APPOINTMENT_STATUS.BOOKED;
    case AppointmentStatus.WAITING:
      return APPOINTMENT_STATUS.BOOKED; // Map waiting to booked with separate flag
    case AppointmentStatus.IN_SERVICE:
      return APPOINTMENT_STATUS.STARTED;
    case AppointmentStatus.COMPLETED:
      return APPOINTMENT_STATUS.COMPLETED;
    case AppointmentStatus.CANCELED:
      return APPOINTMENT_STATUS.CANCELLED;
    case AppointmentStatus.NO_SHOW:
      return APPOINTMENT_STATUS.NO_SHOW;
    default:
      return APPOINTMENT_STATUS.BOOKED;
  }
}

/**
 * Determine appointment kind from appointment data
 */
export function mapKind(appointment: Appointment): AppointmentKind {
  // Check for at-home first
  if (appointment.location_type === "at_home") {
    return AppointmentKind.AT_HOME;
  }
  
  // Check for walk-in (could be a metadata flag or inferred from booking source)
  // For now, we can add a walk-in flag check if the metadata exists
  const metadata = appointment as any;
  if (metadata.is_walk_in || metadata.booking_source === "walk_in") {
    return AppointmentKind.WALK_IN;
  }
  
  return AppointmentKind.IN_SALON;
}

/**
 * Calculate time segments for an appointment
 * This considers buffer time, processing time, and finishing time
 */
export function calculateSegments(
  appointment: Appointment,
  options: {
    bufferMinutes?: number;
    processingMinutes?: number;
    finishingMinutes?: number;
    travelMinutesBefore?: number;
    travelMinutesAfter?: number;
  } = {}
): AppointmentSegment[] {
  const segments: AppointmentSegment[] = [];
  const [hour, minute] = appointment.scheduled_time.split(":").map(Number);
  
  let currentMinutes = hour * 60 + minute;
  
  // Pre-travel for at-home (if applicable)
  if (options.travelMinutesBefore && options.travelMinutesBefore > 0) {
    const travelStart = currentMinutes - options.travelMinutesBefore;
    segments.push({
      kind: SegmentKind.TRAVEL,
      startTime: minutesToTime(travelStart),
      endTime: minutesToTime(currentMinutes),
      durationMinutes: options.travelMinutesBefore,
    });
  }
  
  // Calculate service time (main duration minus optional segments)
  let remainingDuration = appointment.duration_minutes;
  
  // Buffer time at the beginning (if any)
  if (options.bufferMinutes && options.bufferMinutes > 0) {
    segments.push({
      kind: SegmentKind.BUFFER,
      startTime: minutesToTime(currentMinutes),
      endTime: minutesToTime(currentMinutes + options.bufferMinutes),
      durationMinutes: options.bufferMinutes,
    });
    currentMinutes += options.bufferMinutes;
    remainingDuration -= options.bufferMinutes;
  }
  
  // Finishing time at the end
  const finishingTime = options.finishingMinutes || 0;
  const processingTime = options.processingMinutes || 0;
  
  // Main service time
  const serviceTime = remainingDuration - finishingTime - processingTime;
  if (serviceTime > 0) {
    segments.push({
      kind: SegmentKind.SERVICE,
      startTime: minutesToTime(currentMinutes),
      endTime: minutesToTime(currentMinutes + serviceTime),
      durationMinutes: serviceTime,
    });
    currentMinutes += serviceTime;
  }
  
  // Processing time (e.g., color developing)
  if (processingTime > 0) {
    segments.push({
      kind: SegmentKind.PROCESSING,
      startTime: minutesToTime(currentMinutes),
      endTime: minutesToTime(currentMinutes + processingTime),
      durationMinutes: processingTime,
    });
    currentMinutes += processingTime;
  }
  
  // Finishing time
  if (finishingTime > 0) {
    segments.push({
      kind: SegmentKind.FINISHING,
      startTime: minutesToTime(currentMinutes),
      endTime: minutesToTime(currentMinutes + finishingTime),
      durationMinutes: finishingTime,
    });
    currentMinutes += finishingTime;
  }
  
  // Post-travel for at-home (if applicable)
  if (options.travelMinutesAfter && options.travelMinutesAfter > 0) {
    segments.push({
      kind: SegmentKind.TRAVEL,
      startTime: minutesToTime(currentMinutes),
      endTime: minutesToTime(currentMinutes + options.travelMinutesAfter),
      durationMinutes: options.travelMinutesAfter,
    });
  }
  
  // If no segments were added, add the entire duration as service
  if (segments.length === 0) {
    segments.push({
      kind: SegmentKind.SERVICE,
      startTime: appointment.scheduled_time,
      endTime: minutesToTime(hour * 60 + minute + appointment.duration_minutes),
      durationMinutes: appointment.duration_minutes,
    });
  }
  
  return segments;
}

/**
 * Extract icon flags from appointment metadata
 */
export function extractIconFlags(appointment: Appointment): AppointmentIconFlags {
  const metadata = appointment as any;
  
  return {
    isNewClient: metadata.is_new_client || false,
    hasNotes: !!appointment.notes || !!appointment.internal_notes,
    isRepeating: metadata.is_recurring || false,
    hasMembership: metadata.has_membership || false,
    hasFormsIncomplete: metadata.forms_incomplete || false,
    hasPhotos: metadata.has_photos || false,
    hasConversation: metadata.has_conversation || false,
    isGroup: appointment.is_group_booking || false,
    requestedProvider: metadata.requested_provider || false,
    requestedGender: metadata.requested_gender || null,
    hasCustomization: !!appointment.service_customization,
    isWalkIn: metadata.is_walk_in || false,
    isAtHome: appointment.location_type === "at_home",
  };
}

/**
 * Convert an existing appointment to Mangomint view model
 */
export function toMangomintAppointment(
  appointment: Appointment,
  options: {
    timezone?: string;
    bufferMinutes?: number;
    processingMinutes?: number;
    finishingMinutes?: number;
    travelMinutesBefore?: number;
    travelMinutesAfter?: number;
  } = {}
): MangomintAppointment {
  const startTimeUtc = parseISO(`${appointment.scheduled_date}T${appointment.scheduled_time}`);
  const endTimeUtc = addMinutes(startTimeUtc, appointment.duration_minutes);
  
  // Build address string for at-home
  let address: string | null = null;
  if (appointment.location_type === "at_home") {
    const parts = [
      appointment.address_line1,
      appointment.address_line2,
      appointment.address_city,
      appointment.address_postal_code,
    ].filter(Boolean);
    address = parts.join(", ") || null;
  }
  
  return {
    id: appointment.id,
    refNumber: appointment.ref_number,
    
    startTimeUtc,
    endTimeUtc,
    startTimeLocal: appointment.scheduled_time,
    endTimeLocal: minutesToTime(
      parseInt(appointment.scheduled_time.split(":")[0]) * 60 +
      parseInt(appointment.scheduled_time.split(":")[1]) +
      appointment.duration_minutes
    ),
    durationMinutes: appointment.duration_minutes,
    
    staffId: appointment.team_member_id,
    staffName: appointment.team_member_name,
    locationId: appointment.location_id || null,
    locationName: appointment.location_name || null,
    clientId: appointment.client_id || null,
    clientName: appointment.client_name,
    clientEmail: appointment.client_email || null,
    clientPhone: appointment.client_phone || null,
    
    serviceName: appointment.service_name,
    serviceId: appointment.service_id,
    price: appointment.price,
    
    status: mapStatus(appointment),
    kind: mapKind(appointment),
    
    segments: calculateSegments(appointment, options),
    iconFlags: extractIconFlags(appointment),
    
    address,
    travelFee: appointment.travel_fee || null,
    travelTimeMinutes: options.travelMinutesBefore || null,
    
    _original: appointment,
  };
}

/**
 * Convert a time block to Mangomint block model
 */
export function toMangomintBlock(timeBlock: TimeBlock): MangomintBlock {
  const [startH, startM] = timeBlock.start_time.split(":").map(Number);
  const [endH, endM] = timeBlock.end_time.split(":").map(Number);
  const durationMinutes = (endH * 60 + endM) - (startH * 60 + startM);
  
  return {
    id: timeBlock.id,
    kind: BlockKind.TIME_BLOCK,
    staffId: timeBlock.team_member_id || "",
    startTime: timeBlock.start_time,
    endTime: timeBlock.end_time,
    durationMinutes,
    name: timeBlock.name || timeBlock.blocked_time_type_name || "Blocked",
    description: timeBlock.description,
    color: undefined, // Can be added from blocked_time_type
    _original: timeBlock,
  };
}

/**
 * Generate virtual travel blocks for at-home appointments
 * These are computed blocks that don't exist in the database but 
 * should be visualized and considered for conflict checking
 */
export function generateTravelBlocks(
  appointment: MangomintAppointment,
  travelTimeMinutes: number
): MangomintBlock[] {
  if (appointment.kind !== AppointmentKind.AT_HOME || travelTimeMinutes <= 0) {
    return [];
  }

  const blocks: MangomintBlock[] = [];
  const startMin = timeToMinutes(appointment.startTimeLocal);
  const endMin = timeToMinutes(appointment.endTimeLocal);

  // Pre-appointment travel block
  const preTravelStartMin = startMin - travelTimeMinutes;
  if (preTravelStartMin >= 0) {
    blocks.push({
      id: `travel-pre-${appointment.id}`,
      kind: BlockKind.TRAVEL_BLOCK,
      staffId: appointment.staffId,
      startTime: minutesToTime(preTravelStartMin),
      endTime: appointment.startTimeLocal,
      durationMinutes: travelTimeMinutes,
      name: "Travel to client",
      description: `Travel time for ${appointment.clientName}`,
      color: "#60A5FA", // Blue
      _original: {} as TimeBlock, // Virtual block
    });
  }

  // Post-appointment travel block (return trip)
  const postTravelEndMin = endMin + travelTimeMinutes;
  if (postTravelEndMin <= 24 * 60) {
    blocks.push({
      id: `travel-post-${appointment.id}`,
      kind: BlockKind.TRAVEL_BLOCK,
      staffId: appointment.staffId,
      startTime: appointment.endTimeLocal,
      endTime: minutesToTime(postTravelEndMin),
      durationMinutes: travelTimeMinutes,
      name: "Return from client",
      description: `Return travel from ${appointment.clientName}`,
      color: "#60A5FA", // Blue
      _original: {} as TimeBlock, // Virtual block
    });
  }

  return blocks;
}

/**
 * Get all blocks (time blocks + virtual travel blocks) for conflict checking
 */
export function getAllBlocks(
  timeBlocks: TimeBlock[],
  appointments: Appointment[],
  defaultTravelTimeMinutes: number = 30
): MangomintBlock[] {
  const blocks: MangomintBlock[] = [];

  // Add actual time blocks
  for (const tb of timeBlocks) {
    blocks.push(toMangomintBlock(tb));
  }

  // Add virtual travel blocks for at-home appointments
  for (const apt of appointments) {
    if (apt.location_type === "at_home") {
      const mangomintApt = toMangomintAppointment(apt, {
        travelMinutesBefore: defaultTravelTimeMinutes,
        travelMinutesAfter: defaultTravelTimeMinutes,
      });
      
      // Get travel time from appointment or use default
      const travelTime = mangomintApt.travelTimeMinutes || defaultTravelTimeMinutes;
      const travelBlocks = generateTravelBlocks(mangomintApt, travelTime);
      blocks.push(...travelBlocks);
    }
  }

  return blocks;
}

// ============================================================================
// CONFLICT DETECTION HELPERS
// ============================================================================

/**
 * Check if two time intervals overlap
 */
export function overlaps(
  aStart: string,
  aEnd: string,
  bStart: string,
  bEnd: string
): boolean {
  const aStartMin = timeToMinutes(aStart);
  const aEndMin = timeToMinutes(aEnd);
  const bStartMin = timeToMinutes(bStart);
  const bEndMin = timeToMinutes(bEnd);
  
  return aStartMin < bEndMin && aEndMin > bStartMin;
}

/**
 * Check if an appointment can be placed at a target slot
 */
export function canPlace(
  appointment: MangomintAppointment | { startTime: string; durationMinutes: number; staffId: string },
  targetSlot: { date: string; time: string; staffId: string },
  existingAppointments: MangomintAppointment[],
  timeBlocks: MangomintBlock[],
  options: {
    allowDoubleBooking?: boolean;
    processingFreesProvider?: boolean;
  } = {}
): { valid: boolean; reason?: string; conflictsWith?: string[] } {
  const conflicts: string[] = [];
  
  const targetStartMin = timeToMinutes(targetSlot.time);
  const durationMin = "durationMinutes" in appointment 
    ? appointment.durationMinutes 
    : (appointment as MangomintAppointment)._original?.duration_minutes || 60;
  const targetEndTime = minutesToTime(targetStartMin + durationMin);
  
  // Check against existing appointments for the same staff on the same date
  for (const existing of existingAppointments) {
    // Skip self
    if ("id" in appointment && existing.id === appointment.id) continue;
    
    // Skip different staff
    if (existing.staffId !== targetSlot.staffId) continue;
    
    // Skip different date (if we have date info)
    // For now, assume appointments are filtered to the target date
    
    // Check overlap
    if (overlaps(targetSlot.time, targetEndTime, existing.startTimeLocal, existing.endTimeLocal)) {
      // If processing frees provider and the overlap is only with processing segment
      if (options.processingFreesProvider) {
        const processingSegments = existing.segments.filter(s => s.kind === SegmentKind.PROCESSING);
        if (processingSegments.length > 0) {
          const onlyOverlapsProcessing = processingSegments.some(seg => 
            overlaps(targetSlot.time, targetEndTime, seg.startTime, seg.endTime)
          );
          if (onlyOverlapsProcessing) continue;
        }
      }
      
      if (!options.allowDoubleBooking) {
        conflicts.push(existing.id);
      }
    }
  }
  
  // Check against time blocks
  for (const block of timeBlocks) {
    if (block.staffId !== targetSlot.staffId) continue;
    
    if (overlaps(targetSlot.time, targetEndTime, block.startTime, block.endTime)) {
      conflicts.push(`block:${block.id}`);
    }
  }
  
  if (conflicts.length > 0) {
    return {
      valid: false,
      reason: `Conflicts with ${conflicts.length} existing booking(s) or block(s)`,
      conflictsWith: conflicts,
    };
  }
  
  return { valid: true };
}

/**
 * Snap a time to the nearest increment
 */
export function snapToIncrement(time: string, incrementMinutes: number = 15): string {
  const minutes = timeToMinutes(time);
  const snapped = Math.round(minutes / incrementMinutes) * incrementMinutes;
  return minutesToTime(snapped);
}

/**
 * Get available slots for a staff member on a date
 */
export function getAvailableSlots(
  staffId: string,
  date: string,
  existingAppointments: MangomintAppointment[],
  timeBlocks: MangomintBlock[],
  workdayStart: string = "08:00",
  workdayEnd: string = "20:00",
  slotDuration: number = 30,
  incrementMinutes: number = 15
): string[] {
  const slots: string[] = [];
  const startMin = timeToMinutes(workdayStart);
  const endMin = timeToMinutes(workdayEnd);
  
  for (let min = startMin; min < endMin; min += incrementMinutes) {
    const slotTime = minutesToTime(min);
    const result = canPlace(
      { startTime: slotTime, durationMinutes: slotDuration, staffId },
      { date, time: slotTime, staffId },
      existingAppointments,
      timeBlocks
    );
    
    if (result.valid) {
      slots.push(slotTime);
    }
  }
  
  return slots;
}

