/**
 * Get provider's subscription tier and features
 */
async function getProviderSubscriptionTier(
  supabase: SupabaseClient<any>,
  providerId: string
): Promise<{
  planId?: string;
  planName?: string;
  features: any;
  isFree: boolean;
} | null> {
  // Try to get active subscription
  const { data: subscription } = await supabase
    .from("provider_subscriptions")
    .select(`
      plan_id,
      plan:subscription_plans(
        id,
        name,
        features,
        is_free
      )
    `)
    .eq("provider_id", providerId)
    .eq("status", "active")
    .gte("expires_at", new Date().toISOString())
    .maybeSingle();

  if (subscription?.plan) {
    const plan = subscription.plan as any;
    return {
      planId: plan.id,
      planName: plan.name,
      features: plan.features || {},
      isFree: plan.is_free || false,
    };
  }

  // If no active subscription, check badge free_subscription (get_provider_subscription_status)
  const { data: badgeStatus } = await supabase.rpc("get_provider_subscription_status", {
    p_provider_id: providerId,
  });
  if (badgeStatus === "active") {
    const { data: freePlan } = await supabase
      .from("subscription_plans")
      .select("id, name, features, is_free")
      .eq("is_free", true)
      .eq("is_active", true)
      .order("display_order")
      .limit(1)
      .maybeSingle();
    if (freePlan) {
      return {
        planId: freePlan.id,
        planName: freePlan.name,
        features: freePlan.features || {},
        isFree: true,
      };
    }
    // No free plan in DB: return minimal tier so feature checks pass
    return {
      planId: undefined,
      planName: "Badge benefit",
      features: { booking_online: true, reviews_ratings: true, basic_analytics: true },
      isFree: true,
    };
  }

  // Check for free tier from subscription_plans (existing behavior)
  const { data: freePlan } = await supabase
    .from("subscription_plans")
    .select("id, name, features, is_free")
    .eq("is_free", true)
    .eq("is_active", true)
    .order("display_order")
    .limit(1)
    .maybeSingle();

  if (freePlan) {
    return {
      planId: freePlan.id,
      planName: freePlan.name,
      features: freePlan.features || {},
      isFree: true,
    };
  }

  return null;
}

