/**
 * Report Gating Helper
 * 
 * Utility functions for gating report access based on subscription
 */

import { getSupabaseServer } from "@/lib/supabase/server";
import { getProviderIdForUser } from "@/lib/supabase/api-helpers";
import { checkAnalyticsFeatureAccess } from "./feature-access";
import { errorResponse } from "@/lib/supabase/api-helpers";

/**
 * Check if provider can access a specific report type
 */
export async function canAccessReport(
  userId: string,
  reportType: "basic" | "advanced" | "export" | "api"
): Promise<{ allowed: boolean; error?: any }> {
  const supabase = await getSupabaseServer();
  const providerId = await getProviderIdForUser(userId);
  
  if (!providerId) {
    return {
      allowed: false,
      error: errorResponse("Provider not found", "NOT_FOUND", 404),
    };
  }

  // Check if user is superadmin - allow access regardless of subscription
  const { data: userRole } = await supabase
    .from("user_roles")
    .select("role")
    .eq("user_id", userId)
    .eq("role", "superadmin")
    .maybeSingle();

  // Superadmins have full access to all reports
  if (userRole) {
    return { allowed: true };
  }

  const analyticsAccess = await checkAnalyticsFeatureAccess(providerId);

  if (!analyticsAccess.enabled) {
    return {
      allowed: false,
      error: errorResponse(
        "Reports require a subscription upgrade. Please upgrade your plan to access reports.",
        "SUBSCRIPTION_REQUIRED",
        403
      ),
    };
  }

  if (reportType === "basic" && !analyticsAccess.basicReports) {
    return {
      allowed: false,
      error: errorResponse(
        "Basic reports require a subscription upgrade. Please upgrade to Starter plan or higher.",
        "SUBSCRIPTION_REQUIRED",
        403
      ),
    };
  }

  if (reportType === "advanced" && !analyticsAccess.advancedReports) {
    return {
      allowed: false,
      error: errorResponse(
        "Advanced reports require a Professional plan or higher. Please upgrade to access detailed analytics.",
        "SUBSCRIPTION_REQUIRED",
        403
      ),
    };
  }

  if (reportType === "export" && !analyticsAccess.dataExport) {
    return {
      allowed: false,
      error: errorResponse(
        "Data export requires a Professional plan or higher. Please upgrade to export reports.",
        "SUBSCRIPTION_REQUIRED",
        403
      ),
    };
  }

  if (reportType === "api" && !analyticsAccess.apiAccess) {
    return {
      allowed: false,
      error: errorResponse(
        "API access requires an Enterprise plan. Please upgrade to access the API.",
        "SUBSCRIPTION_REQUIRED",
        403
      ),
    };
  }

  return { allowed: true };
}

/**
 * Check if provider can access a specific report type by name
 */
export async function canAccessReportType(
  userId: string,
  reportTypeName: string
): Promise<{ allowed: boolean; error?: any }> {
  const supabase = await getSupabaseServer();
  const providerId = await getProviderIdForUser(userId);
  
  if (!providerId) {
    return {
      allowed: false,
      error: errorResponse("Provider not found", "NOT_FOUND", 404),
    };
  }

  // Check if user is superadmin - allow access regardless of subscription
  const { data: userRole } = await supabase
    .from("user_roles")
    .select("role")
    .eq("user_id", userId)
    .eq("role", "superadmin")
    .maybeSingle();

  // Superadmins have full access to all reports
  if (userRole) {
    return { allowed: true };
  }

  const analyticsAccess = await checkAnalyticsFeatureAccess(providerId);

  if (!analyticsAccess.enabled) {
    return {
      allowed: false,
      error: errorResponse(
        "Reports require a subscription upgrade. Please upgrade your plan to access reports.",
        "SUBSCRIPTION_REQUIRED",
        403
      ),
    };
  }

  // Basic reports: sales, bookings
  const basicReports = ["sales", "bookings"];
  if (basicReports.includes(reportTypeName.toLowerCase())) {
    if (!analyticsAccess.basicReports) {
      return {
        allowed: false,
        error: errorResponse(
          "Basic reports require a subscription upgrade. Please upgrade to Starter plan or higher.",
          "SUBSCRIPTION_REQUIRED",
          403
        ),
      };
    }
    return { allowed: true };
  }

  // Advanced reports: staff, clients, products, payments, gift_cards, packages
  const advancedReports = ["staff", "clients", "products", "payments", "gift_cards", "packages"];
  if (advancedReports.includes(reportTypeName.toLowerCase())) {
    if (!analyticsAccess.advancedReports) {
      return {
        allowed: false,
        error: errorResponse(
          "Advanced reports require a Professional plan or higher. Please upgrade to access detailed analytics.",
          "SUBSCRIPTION_REQUIRED",
          403
        ),
      };
    }
    return { allowed: true };
  }

  // Default: require basic reports
  if (!analyticsAccess.basicReports) {
    return {
      allowed: false,
      error: errorResponse(
        "Reports require a subscription upgrade. Please upgrade your plan to access reports.",
        "SUBSCRIPTION_REQUIRED",
        403
      ),
    };
  }

  return { allowed: true };
}

/**
 * Supabase API Helpers
 * 
 * Common utilities for API routes.
 * Supports Bearer token for mobile/Expo - pass request as second arg to requireRoleInApi.
 */

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import * as Sentry from "@sentry/nextjs";
import { getSupabaseServer, createSupabaseClientFromToken } from "./server";
import { requireRole as requireRoleAuth } from '@/lib/auth/requireRole';
import type { UserRole } from '@/types/beautonomi';

export interface ApiError {
  message: string;
  code?: string;
  details?: any;
}

export interface ApiResponse<T> {
  data: T | null;
  error: ApiError | null;
}

/**
 * Create a successful API response
 */
export function successResponse<T>(data: T, status: number = 200) {
  return NextResponse.json<ApiResponse<T>>(
    {
      data,
      error: null,
    },
    { status }
  );
}

/**
 * Create an error API response
 */
export function errorResponse(
  message: string,
  code?: string,
  status = 400,
  details?: any
) {
  return NextResponse.json<ApiResponse<null>>(
    {
      data: null,
      error: {
        message,
        code,
        details,
      },
    },
    { status }
  );
}

/**
 * Create an unauthorized response
 */
export function unauthorizedResponse(message = 'Unauthorized') {
  return errorResponse(message, 'UNAUTHORIZED', 401);
}

/**
 * Create a forbidden response
 */
export function forbiddenResponse(message = 'Forbidden') {
  return errorResponse(message, 'FORBIDDEN', 403);
}

/**
 * Create a not found response
 */
export function notFoundResponse(message = 'Resource not found') {
  return errorResponse(message, 'NOT_FOUND', 404);
}

/** @deprecated Use errorResponse instead */
export function badRequestResponse(message: string) {
  return errorResponse(message, 'VALIDATION_ERROR', 400);
}

/**
 * Handle API route errors
 */
export function handleApiError(
  error: any,
  defaultMessage = "Internal server error",
  _codeOrStatus?: string | number,
  _statusCode?: number
) {
  console.error("API Error:", error);

  // Determine status code from arguments (backward compatibility)
  let status = typeof _codeOrStatus === "number" ? _codeOrStatus : (_statusCode ?? 500);
  let code = typeof _codeOrStatus === "string" ? _codeOrStatus : "INTERNAL_ERROR";

  if (error instanceof Error) {
    const errorMessage = error.message.toLowerCase();
    const errorCause = (error as any).cause;

    // Check for network/timeout errors
    if (
      errorMessage.includes("network error") ||
      errorMessage.includes("timeout") ||
      errorMessage.includes("connect") ||
      errorMessage.includes("fetch failed") ||
      (errorCause &&
        (errorCause.code === "UND_ERR_CONNECT_TIMEOUT" ||
          errorCause.code === "ECONNREFUSED" ||
          errorCause.code === "ETIMEDOUT"))
    ) {
      status = 503;
      code = "SERVICE_UNAVAILABLE";
      Sentry.captureException(error, { extra: { code, status } });
      return errorResponse(
        "Service temporarily unavailable. Please try again later.",
        code,
        status,
        process.env.NODE_ENV === "development" ? error.stack : undefined
      );
    }

    // Check for authentication/permission errors
    if (
      errorMessage.includes("insufficient permissions") ||
      errorMessage.includes("authentication required") ||
      errorMessage.includes("unauthorized")
    ) {
      status = 403;
      code = "FORBIDDEN";
    }

    Sentry.captureException(error, { extra: { code, status } });
    return errorResponse(
      error.message || defaultMessage,
      code,
      status,
      process.env.NODE_ENV === "development" ? error.stack : undefined
    );
  }

  Sentry.captureMessage(String(error), { level: "error", extra: { code, status } });
  return errorResponse(defaultMessage, code, status);
}

/**
 * Require authentication in API route
 */
export async function requireAuthInApi(request?: NextRequest | Request) {
  const supabase = await getSupabaseServer(request);
  const { data: { user }, error } = await supabase.auth.getUser();

  if (error || !user) {
    throw new Error('Authentication required');
  }

  return { user };
}

/**
 * Require role in API route.
 * Pass request as second arg for mobile/Expo Bearer token support.
 *
 * When 'superadmin' is in the allowed roles: superadmin bypasses provider scoping.
 * Routes must handle superadmin explicitly (e.g. accept provider_id query param for
 * cross-provider access). getProviderIdForUser returns null for superadmin.
 */
export async function requireRoleInApi(
  role: UserRole | UserRole[],
  request?: NextRequest | Request
) {
  const roles = Array.isArray(role) ? role : [role];

  // Mobile/Expo: try Bearer token first
  if (request) {
    const authHeader = request.headers.get("authorization");
    const token = authHeader?.startsWith("Bearer ") ? authHeader.slice(7) : null;
    if (token) {
      try {
        const supabase = createSupabaseClientFromToken(token);
        const { data: { user: authUser }, error } = await supabase.auth.getUser();
        if (error || !authUser) throw new Error("Authentication required");
        const { data: userData } = await supabase
          .from("users")
          .select("id, role, full_name")
          .eq("id", authUser.id)
          .single();
        if (!userData || !userData.role) throw new Error("User profile not found. Please contact support.");
        const userRole = userData.role as UserRole;
        if (!roles.includes(userRole))
          throw new Error(`Insufficient permissions: requires one of ${roles.join(", ")}`);
        return { user: { id: userData.id, role: userRole, email: authUser.email, user_metadata: authUser.user_metadata, full_name: userData.full_name } };
      } catch (err) {
        throw err;
      }
    }
  }

  try {
    const result = await requireRoleAuth(roles);

    if (!result) {
      // Check if it's a network error that was caught
      const supabase = await getSupabaseServer();
      const { data: { user: authUser }, error: authError } = await supabase.auth.getUser();
      // If we can't get the auth user, it might be a network/auth issue
      if (authError || !authUser) {
        if (authError?.message?.toLowerCase().includes('timeout') || 
            authError?.message?.toLowerCase().includes('network') ||
            authError?.message?.toLowerCase().includes('connect')) {
          throw new Error(`Network error: ${authError.message}`);
        }
        throw new Error('Authentication required');
      }

      // Try to get the user's actual role for better error message
      const { data: userData } = await supabase
        .from('users')
        .select('role')
        .eq('id', authUser.id)
        .single();

      const actualRole = userData?.role || 'none';
      console.error(`User ${authUser.id} has role '${actualRole}' but required one of: ${roles.join(', ')}`);

      // User is authenticated but doesn't have the required role
      throw new Error(`Insufficient permissions: User has role '${actualRole}' but requires one of: ${roles.join(', ')}`);
    }

    const supabase = await getSupabaseServer();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
      throw new Error('Authentication required');
    }

    // Return user object (session not needed, using getUser() for security)
    return { user: result.user };
  } catch (error) {
    // Re-throw network errors and other specific errors with their original message
    if (error instanceof Error && (
      error.message.startsWith('Network error:') ||
      error.message.startsWith('User profile not found') ||
      error.message.startsWith('User role not assigned') ||
      error.message.startsWith('Permission denied') ||
      error.message.toLowerCase().includes('timeout') ||
      error.message.toLowerCase().includes('connect')
    )) {
      throw error;
    }
    // Re-throw other errors as-is
    throw error;
  }
}

/**
 * Get pagination parameters from request
 */
export function getPaginationParams(request: Request) {
  const { searchParams } = new URL(request.url);
  const page = Math.max(1, parseInt(searchParams.get('page') || '1', 10));
  const limit = Math.min(100, Math.max(1, parseInt(searchParams.get('limit') || '20', 10)));
  const offset = (page - 1) * limit;

  return { page, limit, offset };
}

/**
 * Create paginated response
 */
export function createPaginatedResponse<T>(
  items: T[],
  total: number,
  page: number,
  limit: number
) {
  return {
    items,
    total,
    page,
    limit,
    has_more: total > page * limit,
  };
}

/**
 * Get provider ID for current user (works for both owners and staff)
 */
export async function getProviderIdForUser(
  userId: string,
  supabaseClient?: Awaited<ReturnType<typeof getSupabaseServer>>
): Promise<string | null> {
  const supabase = supabaseClient || await getSupabaseServer();

  // First check if user is a provider owner
  const { data: provider, error: providerError } = await supabase
    .from('providers')
    .select('id')
    .eq('user_id', userId)
    .maybeSingle();

  if (providerError) {
    console.error('Error fetching provider ID for user:', providerError);
  }

  if (provider) {
    return provider.id;
  }

  // Check if user is provider staff
  const { data: staff, error: staffError } = await supabase
    .from('provider_staff')
    .select('provider_id')
    .eq('user_id', userId)
    .eq('is_active', true)
    .maybeSingle();

  if (staffError) {
    console.error('Error fetching provider ID from staff:', staffError);
    return null;
  }

  if (staff) {
    return staff.provider_id;
  }

  return null;
}

/**
 * Check if user is provider owner or staff
 */
export async function isProviderUser(userId: string, providerId: string): Promise<boolean> {
  const supabase = await getSupabaseServer();

  // Check if user is provider owner
  const { data: provider } = await supabase
    .from('providers')
    .select('id')
    .eq('id', providerId)
    .eq('user_id', userId)
    .single();

  if (provider) {
    return true;
  }

  // Check if user is provider staff
  const { data: staff } = await supabase
    .from('provider_staff')
    .select('id')
    .eq('provider_id', providerId)
    .eq('user_id', userId)
    .eq('is_active', true)
    .single();

  return !!staff;
}

/**
 * Validate UUID format
 */
export function isValidUUID(uuid: string): boolean {
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  return uuidRegex.test(uuid);
}

/**
 * Parse and validate date
 */
export function parseDate(dateString: string | null): Date | null {
  if (!dateString) return null;

  const date = new Date(dateString);
  return isNaN(date.getTime()) ? null : date;
}

/**
 * Format date for database
 */
export function formatDateForDb(date: Date): string {
  return date.toISOString();
}

/**
 * Normalize phone number for Supabase Auth (without + prefix)
 * Validates phone number format but removes + prefix if present
 * Handles numbers starting with 0 by removing the 0 and using country code
 * 
 * @param phone - Phone number to normalize (can be with or without + prefix)
 * @param countryCode - Optional country code (e.g., "27" for South Africa) to use if phone starts with 0
 * @returns Normalized phone number without + prefix, or undefined if invalid
 */
export function normalizePhoneToE164(phone: string | null | undefined, countryCode?: string): string | undefined {
  if (!phone) {
    return undefined;
  }

  // Remove all spaces, dashes, parentheses, and other formatting
  let cleaned = phone.trim().replace(/[\s\-\(\)]/g, '');

  if (!cleaned) {
    return undefined;
  }

  // Remove + prefix if present
  if (cleaned.startsWith('+')) {
    cleaned = cleaned.substring(1);
  }

  // If phone starts with 0 and we have a country code, remove the 0 and prepend country code
  if (cleaned.startsWith('0') && countryCode) {
    // Remove the leading 0
    cleaned = cleaned.substring(1);
    // Remove + from country code if present
    const cleanCountryCode = countryCode.replace(/^\+/, '');
    // Combine country code with phone number
    cleaned = cleanCountryCode + cleaned;
  }

  // Validate format: should start with 1-9 and have 8-15 digits total (E.164 standard)
  if (/^[1-9]\d{7,14}$/.test(cleaned)) {
    // Return with + prefix for E.164 compliance (required by Supabase Auth)
    return '+' + cleaned;
  }

  // Invalid format
  return undefined;
}

/**
 * Supabase Authentication Helpers (Client-Side)
 * 
 * Client-side authentication functions that use getSupabaseClient.
 * For server-side functions, use auth-server.ts
 */

import { getSupabaseClient } from './client';
import type { UserRole } from '@/types/beautonomi';

export interface SignUpData {
  email: string;
  password: string;
  fullName?: string;
  phone?: string;
  role?: UserRole;
}

export interface SignInData {
  email: string;
  password: string;
}

/**
 * Sign up a new user (client-side)
 */
export async function signUp(data: SignUpData) {
  const supabase = getSupabaseClient();

  const { data: authData, error: authError } = await supabase.auth.signUp({
    email: data.email,
    password: data.password,
    options: {
      data: {
        full_name: data.fullName,
        phone: data.phone,
        role: data.role || 'customer',
      },
    },
  });

  if (authError) {
    // Provide more detailed error information for debugging
    const errorMessage = authError.message || 'Unknown error occurred during signup';
    console.error('Signup error details:', {
      message: authError.message,
      status: authError.status,
      name: authError.name,
      email: data.email,
    });
    throw new Error(errorMessage);
  }

  // Log successful signup details for debugging
  console.log('Signup successful:', {
    userId: authData.user?.id,
    email: authData.user?.email,
    hasSession: !!authData.session,
    emailConfirmed: !!authData.user?.email_confirmed_at,
    userCreated: !!authData.user,
    sessionExpiresAt: authData.session?.expires_at,
  });

  // If no session but user was created, log a warning
  if (authData.user && !authData.session) {
    console.warn('User created but no session returned. This may indicate email verification is enabled in Supabase settings.');
  }

  // User profile is created automatically via trigger
  return authData;
}

/**
 * Sign in a user (client-side)
 */
export async function signIn(data: SignInData) {
  const supabase = getSupabaseClient();

  const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
    email: data.email,
    password: data.password,
  });

  if (authError) {
    // Only log error details in development to avoid console noise
    if (process.env.NODE_ENV === 'development') {
      console.error('Sign in error details:', {
        message: authError.message,
        status: authError.status,
        name: authError.name,
        email: data.email,
        errorCode: (authError as any).code,
      });
    }

    // Check for specific error codes that might indicate email verification issues
    const errorCode = (authError as any).code;
    if (errorCode === 'email_not_confirmed' || authError.message.toLowerCase().includes('email not confirmed')) {
      throw new Error('Please verify your email address before logging in. Check your inbox for the verification email.');
    }

    // Provide more helpful error messages based on error type
    if (authError.message.toLowerCase().includes('invalid login credentials') || 
        authError.message.toLowerCase().includes('invalid credentials')) {
      // Generic error message - don't assume email verification is required
      // since it might be disabled in Supabase settings
      // This could mean: wrong password, user doesn't exist, or email not verified (if enabled)
      throw new Error('Invalid login credentials. Please check your email and password.');
    }

    throw new Error(authError.message);
  }

  // Success - return auth data
  return authData;
}

/**
 * Sign out current user (client-side)
 */
export async function signOut() {
  const supabase = getSupabaseClient();
  const { error } = await supabase.auth.signOut();

  if (error) {
    throw new Error(error.message);
  }
}

/**
 * Get current session (client-side)
 */
export async function getSession() {
  const supabase = getSupabaseClient();
  const { data, error } = await supabase.auth.getSession();

  if (error) {
    throw new Error(error.message);
  }

  return data.session;
}

/**
 * Get current user (client-side)
 */
export async function getCurrentUser() {
  const supabase = getSupabaseClient();
  const { data: { user }, error } = await supabase.auth.getUser();

  if (error) {
    throw new Error(error.message);
  }

  return user;
}


