/**
 * OAuth sign in
 */
export async function signInWithOAuth(provider: 'google' | 'facebook' | 'apple', redirectUrl?: string) {
  const supabase = getSupabaseClient();

  // Get the current URL for redirect
  // If redirectUrl is provided, use it; otherwise use default callback
  const redirectTo = typeof window !== 'undefined' 
    ? (redirectUrl || `${window.location.origin}/auth/callback`)
    : (redirectUrl || '/auth/callback');

  // Save current booking state to localStorage if we're in booking flow
  if (typeof window !== 'undefined' && window.location.pathname.includes('/booking')) {
    try {
      const bookingState = {
        path: window.location.pathname,
        search: window.location.search,
        timestamp: Date.now(),
      };
      localStorage.setItem('booking_redirect_state', JSON.stringify(bookingState));
    } catch (e) {
      console.warn('Failed to save booking state:', e);
    }
  }

  const { data, error } = await supabase.auth.signInWithOAuth({
    provider,
    options: {
      redirectTo,
      queryParams: {
        access_type: 'offline',
        prompt: 'consent',
      },
    },
  });

  if (error) {
    throw new Error(error.message);
  }

  // OAuth will redirect the browser, so we don't return data
  return data;
}

/**
 * Supabase Storage Utilities - Client Side Only
 * 
 * Helper functions for file uploads, image optimization, and storage management
 * This file only contains client-side safe code.
 */

import { getSupabaseClient } from './client';

export type BucketName = 
  | 'avatars'
  | 'provider-gallery'
  | 'service-images'
  | 'booking-documents'
  | 'verification-documents'
  | 'receipts';

export interface UploadOptions {
  bucket: BucketName;
  path: string;
  file: File | Blob;
  contentType?: string;
  cacheControl?: string;
  upsert?: boolean;
}

export interface UploadResult {
  path: string;
  fullPath: string;
  publicUrl: string;
}

export const IMAGE_CONSTRAINTS = {
  maxSizeBytes: 5 * 1024 * 1024, // 5MB
  maxSizeMB: 5,
  allowedTypes: ['image/jpeg', 'image/png', 'image/webp', 'image/gif'],
  allowedExtensions: ['.jpg', '.jpeg', '.png', '.webp', '.gif'],
};

/**
 * Upload file to Supabase Storage (client-side)
 */
export async function uploadFile(
  options: UploadOptions
): Promise<UploadResult> {
  const supabase = getSupabaseClient();
  const { bucket, path, file, contentType, cacheControl, upsert = false } = options;

  const fileExt = file instanceof File 
    ? file.name.split('.').pop() 
    : 'bin';

  const fileName = `${path}.${fileExt}`;
  const filePath = `${Date.now()}-${fileName}`;

  const { data, error } = await supabase.storage
    .from(bucket)
    .upload(filePath, file, {
      contentType: contentType || file.type || 'application/octet-stream',
      cacheControl: cacheControl || '3600',
      upsert,
    });

  if (error) {
    // Provide more detailed error message
    let errorMessage = `Failed to upload file: ${error.message}`;

    if (error.message.includes('row-level security') || error.message.includes('RLS')) {
      errorMessage += `\n\nThis is likely an RLS policy issue. Please ensure:
1. The storage bucket "${bucket}" exists
2. RLS policies have been applied (check migrations)
3. You have permission to upload to this bucket`;
    } else if (error.message.includes('not found') || error.message.includes('does not exist')) {
      errorMessage += `\n\nThe storage bucket "${bucket}" may not exist. Please create it in Supabase Dashboard > Storage`;
    }

    console.error('Storage upload error:', {
      bucket,
      path: filePath,
      error: error.message,
      errorCode: (error as any).statusCode,
    });

    throw new Error(errorMessage);
  }

  const { data: { publicUrl } } = supabase.storage
    .from(bucket)
    .getPublicUrl(filePath);

  return {
    path: filePath,
    fullPath: data.path,
    publicUrl,
  };
}

/**
 * Delete file from storage (client-side)
 */
export async function deleteFile(
  bucket: BucketName,
  path: string
): Promise<void> {
  const supabase = getSupabaseClient();

  const { error } = await supabase.storage
    .from(bucket)
    .remove([path]);

  if (error) {
    throw new Error(`Failed to delete file: ${error.message}`);
  }
}

/**
 * Get public URL for a file
 */
export function getPublicUrl(bucket: BucketName, path: string): string {
  const supabase = getSupabaseClient();
  const { data: { publicUrl } } = supabase.storage
    .from(bucket)
    .getPublicUrl(path);

  return publicUrl;
}

/**
 * List files in a bucket path
 */
export async function listFiles(
  bucket: BucketName,
  path?: string
): Promise<{ name: string; id: string; created_at: string }[]> {
  const supabase = getSupabaseClient();

  const { data, error } = await supabase.storage
    .from(bucket)
    .list(path || '', {
      sortBy: { column: 'created_at', order: 'desc' },
    });

  if (error) {
    throw new Error(`Failed to list files: ${error.message}`);
  }

  return data || [];
}

