/**
 * Compute travel fee and distance for a hold (at-home booking).
 * Used by POST /api/public/booking-holds when address has coordinates.
 * Mirrors the logic in /api/location/validate so hold checkout shows correct total.
 */
import type { SupabaseClient } from "@supabase/supabase-js";
import { getMapboxService } from "@/lib/mapbox/mapbox";
import { computeTravelFee, type TravelFeeRules } from "@/lib/travel/travelFeeEngine";
import { HOUSE_CALL_CONFIG } from "@/lib/config/house-call-config";

export interface HoldAddressInput {
  latitude: number;
  longitude: number;
  line1?: string;
  city?: string;
  country?: string;
  postal_code?: string;
}

export interface TravelFeeForHoldResult {
  travelFee: number;
  distanceKm: number;
  withinServiceArea: boolean;
}

export async function calculateTravelFeeForHold(
  supabase: SupabaseClient,
  providerId: string,
  address: HoldAddressInput
): Promise<TravelFeeForHoldResult> {
  const clientCoordinates = { latitude: address.latitude, longitude: address.longitude };
  const serviceAddress = {
    line1: address.line1 || "",
    city: address.city || "",
    country: address.country || HOUSE_CALL_CONFIG.DEFAULT_COUNTRY_NAME,
    postalCode: address.postal_code || "",
    coordinates: clientCoordinates,
  };

  const { data: provider } = await supabase
    .from("providers")
    .select("max_service_distance_km, is_distance_filter_enabled, offers_mobile_services")
    .eq("id", providerId)
    .single();

  if (!provider || provider.offers_mobile_services === false) {
    return { travelFee: 0, distanceKm: 0, withinServiceArea: false };
  }

  const { data: providerLocations } = await supabase
    .from("provider_locations")
    .select("id, latitude, longitude")
    .eq("provider_id", providerId)
    .eq("is_active", true)
    .order("is_primary", { ascending: false });

  if (!providerLocations?.length) {
    return { travelFee: 0, distanceKm: 0, withinServiceArea: false };
  }

  let mapbox;
  try {
    mapbox = await getMapboxService();
  } catch {
    return { travelFee: 0, distanceKm: 0, withinServiceArea: false };
  }

  type Loc = { latitude?: number | null; longitude?: number | null };
  let baseLocation: { latitude: number; longitude: number } | null = null;
  let nearestLocation = providerLocations[0] as Loc;
  let minDistance = Infinity;

  for (const loc of providerLocations as Loc[]) {
    const lat = loc.latitude ?? (loc as any).address_lat;
    const lng = loc.longitude ?? (loc as any).address_lng;
    if (lat == null || lng == null) continue;
    const dist = mapbox.calculateDistance({ latitude: lat, longitude: lng }, clientCoordinates);
    if (dist < minDistance) {
      minDistance = dist;
      nearestLocation = loc;
    }
  }

  const nlat = nearestLocation?.latitude ?? (nearestLocation as any)?.address_lat;
  const nlng = nearestLocation?.longitude ?? (nearestLocation as any)?.address_lng;
  if (nlat == null || nlng == null) {
    return { travelFee: 0, distanceKm: 0, withinServiceArea: false };
  }

  baseLocation = { latitude: nlat, longitude: nlng };

  const distanceKm = mapbox.calculateDistance(baseLocation, clientCoordinates);
  const maxDistance = provider.max_service_distance_km || HOUSE_CALL_CONFIG.DEFAULT_MAX_SERVICE_DISTANCE_KM;
  const isDistanceFilterEnabled = provider.is_distance_filter_enabled || false;

  let matchedZone: any = null;
  const { data: platformZones } = await supabase
    .from("platform_zones")
    .select("*")
    .eq("is_active", true);

  if (platformZones && platformZones.length > 0) {
    for (const zone of platformZones) {
      let isInZone = false;
      if (zone.zone_type === "postal_code" && serviceAddress.postalCode) {
        const normalizedPostal = serviceAddress.postalCode.replace(/\s/g, "");
        isInZone = zone.postal_codes?.some((pc: string) => pc.replace(/\s/g, "") === normalizedPostal) || false;
      } else if (zone.zone_type === "city" && serviceAddress.city) {
        const normalizedCity = serviceAddress.city.toLowerCase().trim();
        isInZone = zone.cities?.some((c: string) => c.toLowerCase().trim() === normalizedCity) || false;
      } else if (zone.zone_type === "radius" && zone.center_latitude && zone.center_longitude && zone.radius_km) {
        const zoneCenter = {
          latitude: parseFloat(zone.center_latitude.toString()),
          longitude: parseFloat(zone.center_longitude.toString()),
        };
        isInZone = mapbox.calculateDistance(zoneCenter, clientCoordinates) <= zone.radius_km;
      } else if (zone.zone_type === "polygon" && zone.polygon_coordinates) {
        const polygon = zone.polygon_coordinates;
        if (Array.isArray(polygon) && polygon.length > 0) {
          const ring = Array.isArray(polygon[0]) ? polygon[0] : polygon;
          const polygonCoords = ring.map((coord: any) => ({
            longitude: Array.isArray(coord) ? coord[0] : (coord.lng ?? coord.longitude),
            latitude: Array.isArray(coord) ? coord[1] : (coord.lat ?? coord.latitude),
          }));
          let inside = false;
          for (let i = 0, j = polygonCoords.length - 1; i < polygonCoords.length; j = i++) {
            const xi = polygonCoords[i].longitude, yi = polygonCoords[i].latitude;
            const xj = polygonCoords[j].longitude, yj = polygonCoords[j].latitude;
            const intersect =
              yi > clientCoordinates.latitude !== yj > clientCoordinates.latitude &&
              clientCoordinates.longitude < ((xj - xi) * (clientCoordinates.latitude - yi)) / (yj - yi) + xi;
            if (intersect) inside = !inside;
          }
          isInZone = inside;
        }
      }
      if (isInZone) {
        const { data: providerSelection } = await supabase
          .from("provider_zone_selections")
          .select("*")
          .eq("provider_id", providerId)
          .eq("platform_zone_id", zone.id)
          .eq("is_active", true)
          .single();
        if (providerSelection) {
          matchedZone = { ...zone, provider_selection: providerSelection };
          break;
        }
      }
    }
    if (!matchedZone && platformZones.length > 0) {
      return { travelFee: 0, distanceKm: parseFloat(distanceKm.toFixed(2)), withinServiceArea: false };
    }
  } else {
    const { data: serviceZones } = await supabase
      .from("service_zones")
      .select("*")
      .eq("provider_id", providerId)
      .eq("is_active", true);
    if (serviceZones?.length) {
      for (const zone of serviceZones) {
        let isInZone = false;
        if (zone.zone_type === "postal_code" && serviceAddress.postalCode) {
          isInZone = zone.postal_codes?.some((pc: string) => pc.replace(/\s/g, "") === serviceAddress.postalCode.replace(/\s/g, "")) || false;
        } else if (zone.zone_type === "city" && serviceAddress.city) {
          isInZone = zone.cities?.some((c: string) => c.toLowerCase().trim() === serviceAddress.city.toLowerCase().trim()) || false;
        }
        if (isInZone) {
          matchedZone = zone;
          break;
        }
      }
      if (!matchedZone) {
        return { travelFee: 0, distanceKm: parseFloat(distanceKm.toFixed(2)), withinServiceArea: false };
      }
    }
  }

  if (isDistanceFilterEnabled && distanceKm > maxDistance) {
    return { travelFee: 0, distanceKm: parseFloat(distanceKm.toFixed(2)), withinServiceArea: false };
  }

  const { data: travelFeeSettings } = await supabase
    .from("provider_travel_fee_settings")
    .select("*")
    .eq("provider_id", providerId)
    .eq("enabled", true)
    .single();

  const { data: platformSettings } = await supabase
    .from("platform_settings")
    .select("settings")
    .eq("is_active", true)
    .single();

  const platformTravelFees = platformSettings?.settings?.travel_fees || {
    default_rate_per_km: HOUSE_CALL_CONFIG.DEFAULT_TRAVEL_FEE.RATE_PER_KM,
    default_minimum_fee: HOUSE_CALL_CONFIG.DEFAULT_TRAVEL_FEE.MINIMUM_FEE,
    default_maximum_fee: HOUSE_CALL_CONFIG.DEFAULT_TRAVEL_FEE.MAXIMUM_FEE,
  };

  const usePlatformDefault = !travelFeeSettings || travelFeeSettings.use_platform_default;
  const travelFeeRules: TravelFeeRules = {
    strategy: "distance",
    perKmRate: usePlatformDefault ? platformTravelFees.default_rate_per_km : (travelFeeSettings?.rate_per_km ?? HOUSE_CALL_CONFIG.DEFAULT_TRAVEL_FEE.RATE_PER_KM),
    minimumFee: usePlatformDefault ? platformTravelFees.default_minimum_fee : (travelFeeSettings?.minimum_fee ?? HOUSE_CALL_CONFIG.DEFAULT_TRAVEL_FEE.MINIMUM_FEE),
    maximumFee: usePlatformDefault ? platformTravelFees.default_maximum_fee : (travelFeeSettings?.maximum_fee ?? HOUSE_CALL_CONFIG.DEFAULT_TRAVEL_FEE.MAXIMUM_FEE),
    maxRadiusKm: maxDistance,
    baseTravelTimeMinutes: HOUSE_CALL_CONFIG.BASE_TRAVEL_TIME_MINUTES,
    defaultMinutesPerKm: HOUSE_CALL_CONFIG.DEFAULT_MINUTES_PER_KM,
  };

  const travelFeeResult = computeTravelFee(baseLocation, serviceAddress, travelFeeRules);
  if (!travelFeeResult.withinServiceArea) {
    return {
      travelFee: 0,
      distanceKm: travelFeeResult.distanceKm ?? parseFloat(distanceKm.toFixed(2)),
      withinServiceArea: false,
    };
  }

  let finalTravelFee = travelFeeResult.fee;
  if (matchedZone?.provider_selection) {
    finalTravelFee = parseFloat(matchedZone.provider_selection.travel_fee.toString());
  } else if (matchedZone?.travel_fee != null) {
    finalTravelFee = parseFloat(matchedZone.travel_fee.toString());
  }

  return {
    travelFee: Math.round(finalTravelFee * 100) / 100,
    distanceKm: parseFloat((travelFeeResult.distanceKm ?? distanceKm).toFixed(2)),
    withinServiceArea: true,
  };
}

/**
 * CSV Export Utilities
 * 
 * Helper functions for generating CSV files from data
 */

/**
 * Convert an array of objects to CSV string
 */
export function arrayToCSV<T extends Record<string, any>>(
  data: T[],
  headers?: string[]
): string {
  if (data.length === 0) {
    return "";
  }

  // Use provided headers or extract from first object
  const keys = headers || Object.keys(data[0]);
  
  // Create header row
  const headerRow = keys.map((key) => escapeCSVValue(key)).join(",");
  
  // Create data rows
  const dataRows = data.map((row) => {
    return keys
      .map((key) => {
        const value = row[key];
        return escapeCSVValue(formatCSVValue(value));
      })
      .join(",");
  });
  
  return [headerRow, ...dataRows].join("\n");
}

/**
 * Escape CSV value (handle commas, quotes, newlines)
 */
function escapeCSVValue(value: any): string {
  if (value === null || value === undefined) {
    return "";
  }
  
  const stringValue = String(value);
  
  // If value contains comma, quote, or newline, wrap in quotes and escape quotes
  if (stringValue.includes(",") || stringValue.includes('"') || stringValue.includes("\n")) {
    return `"${stringValue.replace(/"/g, '""')}"`;
  }
  
  return stringValue;
}

/**
 * Format value for CSV (handle dates, arrays, objects)
 */
function formatCSVValue(value: any): string {
  if (value === null || value === undefined) {
    return "";
  }
  
  // Handle dates
  if (value instanceof Date) {
    return value.toISOString();
  }
  
  // Handle arrays
  if (Array.isArray(value)) {
    return value.join("; ");
  }
  
  // Handle objects
  if (typeof value === "object") {
    return JSON.stringify(value);
  }
  
  return String(value);
}

/**
 * Generate CSV filename with timestamp
 */
export function generateCSVFilename(prefix: string): string {
  const timestamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, -5);
  return `${prefix}-${timestamp}.csv`;
}

/**
 * Convert CSV string to Blob for download
 */
export function csvToBlob(csv: string): Blob {
  return new Blob([csv], { type: "text/csv;charset=utf-8;" });
}

/**
 * Structured Logging Utility
 * 
 * Provides consistent logging format for observability
 */

type LogLevel = "debug" | "info" | "warn" | "error";

interface LogContext {
  userId?: string;
  role?: string;
  requestId?: string;
  path?: string;
  method?: string;
  [key: string]: any;
}

class Logger {
  private formatMessage(level: LogLevel, message: string, context?: LogContext): string {
    const timestamp = new Date().toISOString();
    const logEntry = {
      timestamp,
      level: level.toUpperCase(),
      message,
      ...context,
    };
    
    return JSON.stringify(logEntry);
  }

  debug(message: string, context?: LogContext): void {
    if (process.env.NODE_ENV === "development") {
      console.debug(this.formatMessage("debug", message, context));
    }
  }

  info(message: string, context?: LogContext): void {
    console.log(this.formatMessage("info", message, context));
  }

  warn(message: string, context?: LogContext): void {
    console.warn(this.formatMessage("warn", message, context));
  }

  error(message: string, error?: Error | unknown, context?: LogContext): void {
    const errorContext = {
      ...context,
      error: error instanceof Error ? {
        name: error.name,
        message: error.message,
        stack: error.stack,
      } : String(error),
    };
    
    console.error(this.formatMessage("error", message, errorContext));
  }

  /**
   * Log API request
   */
  logRequest(method: string, path: string, userId?: string, role?: string): void {
    this.info(`${method} ${path}`, {
      method,
      path,
      userId,
      role,
      type: "api_request",
    });
  }

  /**
   * Log API response
   */
  logResponse(method: string, path: string, statusCode: number, duration?: number): void {
    this.info(`${method} ${path} - ${statusCode}`, {
      method,
      path,
      statusCode,
      duration,
      type: "api_response",
    });
  }

  /**
   * Log database operation
   */
  logDatabase(operation: string, table: string, context?: LogContext): void {
    this.debug(`DB ${operation} on ${table}`, {
      ...context,
      operation,
      table,
      type: "database",
    });
  }

  /**
   * Log payment transaction
   */
  logPayment(transactionId: string, status: string, amount?: number, context?: LogContext): void {
    this.info(`Payment ${status}`, {
      ...context,
      transactionId,
      status,
      amount,
      type: "payment",
    });
  }

  /**
   * Log notification
   */
  logNotification(eventType: string, recipients: string, status: string, context?: LogContext): void {
    this.info(`Notification ${status}`, {
      ...context,
      eventType,
      recipients,
      status,
      type: "notification",
    });
  }

  /**
   * Log admin action
   */
  logAdminAction(action: string, resource: string, resourceId: string, userId: string, context?: LogContext): void {
    this.info(`Admin ${action}`, {
      ...context,
      action,
      resource,
      resourceId,
      userId,
      type: "admin_action",
    });
  }
}

export const logger = new Logger();

/**
 * Waitlist Auto-Booking
 * Automatically creates bookings for waitlist entries when slots become available
 */

import { SupabaseClient } from '@supabase/supabase-js';
import type { WaitlistMatch } from './matching';
import { getSupabaseAdmin } from '@/lib/supabase/admin';

/**
 * Check if provider has auto-booking enabled
 */
export async function isAutoBookingEnabled(
  supabase: SupabaseClient,
  providerId: string
): Promise<boolean> {
  const { data: provider } = await supabase
    .from('providers')
    .select('waitlist_auto_booking_enabled')
    .eq('id', providerId)
    .single();

  return provider?.waitlist_auto_booking_enabled === true;
}

/**
 * Automatically create booking for waitlist entry
 */
export async function createAutoBooking(
  supabase: SupabaseClient,
  match: WaitlistMatch
): Promise<{ success: boolean; bookingId?: string; error?: string }> {
  const { entry, availableSlots } = match;

  if (availableSlots.length === 0) {
    return { success: false, error: 'No available slots' };
  }

  // Use the first available slot
  const selectedSlot = availableSlots[0];
  const slotDate = new Date(selectedSlot.date);
  const [hours, minutes] = selectedSlot.time.split(':').map(Number);
  slotDate.setHours(hours, minutes, 0, 0);

  // Get service details
  if (!entry.service_id) {
    return { success: false, error: 'Service ID required for auto-booking' };
  }

  const { data: service } = await supabase
    .from('offerings')
    .select('id, duration_minutes, price, currency, provider_id')
    .eq('id', entry.service_id)
    .single();

  if (!service) {
    return { success: false, error: 'Service not found' };
  }

  // Get staff ID (use entry staff_id or find available staff)
  let staffId = entry.staff_id;
  if (!staffId) {
    const { data: staff } = await supabase
      .from('provider_staff')
      .select('id')
      .eq('provider_id', entry.provider_id)
      .eq('is_active', true)
      .limit(1)
      .single();
    
    if (!staff) {
      return { success: false, error: 'No available staff' };
    }
    staffId = staff.id;
  }

  // Calculate end time
  const durationMinutes = Number(service.duration_minutes) || 60;
  const endTime = new Date(slotDate.getTime() + durationMinutes * 60000);

  // Create booking draft
  const adminSupabase = getSupabaseAdmin();
  
  try {
    // Create booking using the same RPC as regular bookings
    const bookingData = {
      provider_id: entry.provider_id,
      customer_id: entry.customer_id,
      guest_name: entry.customer_name,
      guest_email: entry.customer_email,
      guest_phone: entry.customer_phone,
      location_type: 'at_salon', // Default to salon, could be configurable
      scheduled_at: slotDate.toISOString(),
      status: 'pending', // Will need payment confirmation
      notes: `Auto-booked from waitlist. Original waitlist entry: ${entry.id}`,
    };

    const bookingServicesData = [{
      offering_id: service.id,
      staff_id: staffId,
      duration_minutes: durationMinutes,
      price: Number(service.price),
      currency: service.currency || 'ZAR',
      scheduled_start_at: slotDate.toISOString(),
      scheduled_end_at: endTime.toISOString(),
    }];

    const { data: bookingId, error: bookingError } = await adminSupabase.rpc(
      'create_booking_with_locking',
      {
        p_booking_data: bookingData as any,
        p_booking_services: bookingServicesData as any,
        p_staff_id: staffId,
        p_start_at: slotDate.toISOString(),
        p_end_at: endTime.toISOString(),
      }
    );

    if (bookingError || !bookingId) {
      return { 
        success: false, 
        error: bookingError?.message || 'Failed to create booking' 
      };
    }

    // Update waitlist entry status
    await supabase
      .from('waitlist_entries')
      .update({
        status: 'booked',
        booked_at: new Date().toISOString(),
        booking_id: bookingId,
      })
      .eq('id', entry.id);

    return { success: true, bookingId };
  } catch (error) {
    console.error('Error creating auto-booking:', error);
    return { 
      success: false, 
      error: error instanceof Error ? error.message : 'Unknown error' 
    };
  }
}

/**
 * Process waitlist matches with auto-booking if enabled
 */
export async function processWaitlistMatches(
  supabase: SupabaseClient,
  matches: WaitlistMatch[],
  providerId: string
): Promise<void> {
  const autoBookingEnabled = await isAutoBookingEnabled(supabase, providerId);

  for (const match of matches) {
    if (autoBookingEnabled) {
      // Attempt auto-booking
      const result = await createAutoBooking(supabase, match);
      
      if (result.success) {
        // Booking created successfully, send confirmation notification
        const { notifyWaitlistMatch } = await import('./notifications');
        await notifyWaitlistMatch(supabase, match, undefined);
        
        // Update notification to indicate auto-booking
        await supabase
          .from('waitlist_entries')
          .update({
            notes: `Auto-booked. Booking ID: ${result.bookingId}`,
          })
          .eq('id', match.entry.id);
      } else {
        // Auto-booking failed, send notification for manual booking
        const { notifyWaitlistMatch } = await import('./notifications');
        await notifyWaitlistMatch(supabase, match, undefined);
      }
    } else {
      // Auto-booking disabled, just send notification
      const { notifyWaitlistMatch } = await import('./notifications');
      await notifyWaitlistMatch(supabase, match, undefined);
    }
  }
}

/**
 * Waitlist Matching Logic
 * Matches waitlist entries with available booking slots
 */

import { getSupabaseAdmin } from "@/lib/supabase/admin";

export interface WaitlistMatch {
  entry: {
    id: string;
    provider_id?: string;
    service_id?: string;
    staff_id?: string | null;
    customer_id?: string;
    customer_email?: string;
    customer_name?: string;
    customer_phone?: string;
    [key: string]: any;
  };
  availableSlots: Array<{ date: string; time: string }>;
  matchReason?: string;
}
import { sendTemplateNotification } from "@/lib/notifications/onesignal";

/**
 * Match waitlist entries when a booking is cancelled
 */
export async function matchWaitlistOnCancellation(supabase: any, cancelledBookingId: string) {
  const supabaseAdmin = getSupabaseAdmin();

  try {
    // Get cancelled booking details
    const { data: booking, error: bookingError } = await supabase
      .from("bookings")
      .select(`
        id,
        provider_id,
        scheduled_at,
        booking_services(
          id,
          offering_id,
          staff_id,
          scheduled_start_at,
          scheduled_end_at
        )
      `)
      .eq("id", cancelledBookingId)
      .single();

    if (bookingError || !booking) {
      return;
    }

    const bookingServices = booking.booking_services as any[];
    if (bookingServices.length === 0) {
      return;
    }

    const firstService = bookingServices[0];
    const staffId = firstService.staff_id;
    const serviceId = firstService.offering_id;
    const scheduledDate = new Date(booking.scheduled_at);
    const dateStr = scheduledDate.toISOString().split("T")[0];
    const timeStr = scheduledDate.toTimeString().substring(0, 5);

    // Find matching waitlist entries
    const { data: waitlistEntries, error: waitlistError } = await supabaseAdmin
      .from("waitlist_entries")
      .select(`
        *,
        customer:users(
          id,
          email,
          full_name
        )
      `)
      .eq("provider_id", booking.provider_id)
      .eq("status", "waiting")
      .or(`staff_id.is.null,staff_id.eq.${staffId}`)
      .or(`service_id.is.null,service_id.eq.${serviceId}`)
      .or(`preferred_date.is.null,preferred_date.eq.${dateStr}`)
      .order("priority", { ascending: false })
      .order("created_at", { ascending: true })
      .limit(10); // Notify top 10 matches

    if (waitlistError || !waitlistEntries || waitlistEntries.length === 0) {
      return;
    }

    // Notify matching waitlist entries
    for (const entry of waitlistEntries) {
      const customer = entry.customer as any;
      if (!customer?.id) continue;

      try {
        // Create notification
        await supabaseAdmin.from("notifications").insert({
          user_id: customer.id,
          type: "waitlist_available",
          title: "Booking Slot Available!",
          message: `A booking slot has become available! Date: ${dateStr}, Time: ${timeStr}`,
          metadata: {
            waitlist_id: entry.id,
            booking_id: cancelledBookingId,
            available_date: dateStr,
            available_time: timeStr,
          },
          link: `/booking?provider=${booking.provider_id}&date=${dateStr}&time=${timeStr}`,
        });

        // Send push/email notification
        await sendTemplateNotification(
          "booking_waitlist_available",
          [customer.id],
          {
            provider_name: "Provider", // Could fetch provider name
            available_date: dateStr,
            available_time: timeStr,
            services: serviceId ? "Service" : "Services",
            provider_id: booking.provider_id,
          },
          ["push", "email"]
        );
      } catch (notifError) {
        console.error(`Error notifying waitlist entry ${entry.id}:`, notifError);
      }
    }
  } catch (error) {
    console.error("Error matching waitlist on cancellation:", error);
  }
}

/**
 * Find waitlist entries for a provider (for provider UI to see matches)
 */
export async function findWaitlistMatches(
  supabase: any,
  providerId: string,
  options?: { date?: string; staffId?: string | null; maxMatches?: number }
): Promise<any[]> {
  let query = supabase
    .from("waitlist_entries")
    .select(`
      *,
      customer:users(id, email, full_name)
    `)
    .eq("provider_id", providerId)
    .eq("status", "waiting")
    .order("priority", { ascending: false })
    .order("created_at", { ascending: true })
    .limit(options?.maxMatches ?? 10);

  if (options?.date) {
    query = query.or(`preferred_date.is.null,preferred_date.eq.${options.date}`);
  }
  if (options?.staffId) {
    query = query.or(`staff_id.is.null,staff_id.eq.${options.staffId}`);
  }

  const { data, error } = await query;
  if (error) throw error;
  return data ?? [];
}

/**
 * Check and match waitlist entries for a specific date/staff/service
 */
export async function checkWaitlistForAvailability(
  providerId: string,
  staffId: string | null,
  serviceId: string | null,
  date: string,
  time: string
) {
  const supabaseAdmin = getSupabaseAdmin();

  try {
    // Find matching waitlist entries
    const { data: waitlistEntries } = await supabaseAdmin
      .from("waitlist_entries")
      .select(`
        *,
        customer:users(
          id,
          email,
          full_name
        )
      `)
      .eq("provider_id", providerId)
      .eq("status", "waiting")
      .or(`preferred_date.is.null,preferred_date.eq.${date}`)
      .or(`staff_id.is.null,staff_id.eq.${staffId || "null"}`)
      .or(`service_id.is.null,service_id.eq.${serviceId || "null"}`)
      .order("priority", { ascending: false })
      .order("created_at", { ascending: true })
      .limit(10);

    if (!waitlistEntries || waitlistEntries.length === 0) {
      return { matched: 0 };
    }

    // Notify entries
    let notified = 0;
    for (const entry of waitlistEntries) {
      const customer = entry.customer as any;
      if (!customer?.id) continue;

      try {
        await supabaseAdmin.from("notifications").insert({
          user_id: customer.id,
          type: "waitlist_available",
          title: "Booking Slot Available!",
          message: `A booking slot has become available! Date: ${date}, Time: ${time}`,
          metadata: {
            waitlist_id: entry.id,
            available_date: date,
            available_time: time,
          },
          link: `/booking?provider=${providerId}&date=${date}&time=${time}`,
        });

        await sendTemplateNotification(
          "booking_waitlist_available",
          [customer.id],
          {
            provider_name: "Provider",
            available_date: date,
            available_time: time,
            services: serviceId ? "Service" : "Services",
            provider_id: providerId,
          },
          ["push", "email"]
        );

        notified++;
      } catch (notifError) {
        console.error(`Error notifying waitlist entry ${entry.id}:`, notifError);
      }
    }

    return { matched: notified };
  } catch (error) {
    console.error("Error checking waitlist for availability:", error);
    throw error;
  }
}

/**
 * WebSocket Client for Real-Time Updates
 * Replaces polling with WebSocket connections for instant updates
 */

export type WebSocketEventType = 
  | 'booking_created'
  | 'booking_updated'
  | 'booking_cancelled'
  | 'availability_changed'
  | 'waitlist_match'
  | 'appointment_status_changed';

export interface WebSocketEvent {
  type: WebSocketEventType;
  data: any;
  timestamp: string;
}

export type WebSocketEventHandler = (event: WebSocketEvent) => void;

class WebSocketManager {
  private ws: WebSocket | null = null;
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 5;
  private reconnectDelay = 1000;
  private handlers: Map<WebSocketEventType | '*', Set<WebSocketEventHandler>> = new Map();
  private isConnecting = false;
  private url: string;

  constructor() {
    // Use wss:// in production, ws:// in development
    const protocol = typeof window !== 'undefined' && window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const host = typeof window !== 'undefined' ? window.location.host : 'localhost:3000';
    this.url = `${protocol}//${host}/api/ws`;
  }

  /**
   * Connect to WebSocket server
   */
  connect(userId?: string, providerId?: string): Promise<void> {
    return new Promise((resolve, reject) => {
      if (this.ws?.readyState === WebSocket.OPEN) {
        resolve();
        return;
      }

      if (this.isConnecting) {
        // Wait for existing connection attempt
        const checkInterval = setInterval(() => {
          if (!this.isConnecting) {
            clearInterval(checkInterval);
            if (this.ws?.readyState === WebSocket.OPEN) {
              resolve();
            } else {
              reject(new Error('Connection failed'));
            }
          }
        }, 100);
        return;
      }

      this.isConnecting = true;

      try {
        // Add query params for authentication and context
        const params = new URLSearchParams();
        if (userId) params.set('userId', userId);
        if (providerId) params.set('providerId', providerId);
        const wsUrl = `${this.url}?${params.toString()}`;

        this.ws = new WebSocket(wsUrl);

        this.ws.onopen = () => {
          this.isConnecting = false;
          this.reconnectAttempts = 0;
          console.log('[WebSocket] Connected');
          resolve();
        };

        this.ws.onmessage = (event) => {
          try {
            const message: WebSocketEvent = JSON.parse(event.data);
            this.handleMessage(message);
          } catch (error) {
            console.error('[WebSocket] Error parsing message:', error);
          }
        };

        this.ws.onerror = (error) => {
          this.isConnecting = false;
          console.error('[WebSocket] Error:', error);
          reject(error);
        };

        this.ws.onclose = () => {
          this.isConnecting = false;
          console.log('[WebSocket] Disconnected');
          this.attemptReconnect(userId, providerId);
        };
      } catch (error) {
        this.isConnecting = false;
        reject(error);
      }
    });
  }

  /**
   * Attempt to reconnect with exponential backoff
   */
  private attemptReconnect(userId?: string, providerId?: string) {
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      console.error('[WebSocket] Max reconnection attempts reached');
      return;
    }

    this.reconnectAttempts++;
    const delay = this.reconnectDelay * Math.pow(2, this.reconnectAttempts - 1);

    setTimeout(() => {
      console.log(`[WebSocket] Reconnecting (attempt ${this.reconnectAttempts})...`);
      this.connect(userId, providerId).catch(() => {
        // Reconnection will be attempted again
      });
    }, delay);
  }

  /**
   * Handle incoming WebSocket message
   */
  private handleMessage(event: WebSocketEvent) {
    const handlers = this.handlers.get(event.type);
    if (handlers) {
      handlers.forEach(handler => {
        try {
          handler(event);
        } catch (error) {
          console.error(`[WebSocket] Error in handler for ${event.type}:`, error);
        }
      });
    }

    // Also call wildcard handlers
    const wildcardHandlers = this.handlers.get('*' as WebSocketEventType);
    if (wildcardHandlers) {
      wildcardHandlers.forEach(handler => {
        try {
          handler(event);
        } catch (error) {
          console.error('[WebSocket] Error in wildcard handler:', error);
        }
      });
    }
  }

  /**
   * Subscribe to WebSocket events
   */
  on(eventType: WebSocketEventType | '*', handler: WebSocketEventHandler) {
    if (!this.handlers.has(eventType)) {
      this.handlers.set(eventType, new Set());
    }
    this.handlers.get(eventType)!.add(handler);

    // Return unsubscribe function
    return () => {
      const handlers = this.handlers.get(eventType);
      if (handlers) {
        handlers.delete(handler);
        if (handlers.size === 0) {
          this.handlers.delete(eventType);
        }
      }
    };
  }

  /**
   * Unsubscribe from WebSocket events
   */
  off(eventType: WebSocketEventType | '*', handler: WebSocketEventHandler) {
    const handlers = this.handlers.get(eventType);
    if (handlers) {
      handlers.delete(handler);
      if (handlers.size === 0) {
        this.handlers.delete(eventType);
      }
    }
  }

  /**
   * Send message to WebSocket server
   */
  send(data: any) {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(data));
    } else {
      console.warn('[WebSocket] Cannot send message, connection not open');
    }
  }

  /**
   * Disconnect from WebSocket server
   */
  disconnect() {
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
    this.handlers.clear();
    this.reconnectAttempts = 0;
  }

  /**
   * Check if WebSocket is connected
   */
  isConnected(): boolean {
    return this.ws?.readyState === WebSocket.OPEN;
  }
}

// Singleton instance
let wsManager: WebSocketManager | null = null;

export function getWebSocketManager(): WebSocketManager {
  if (!wsManager) {
    wsManager = new WebSocketManager();
  }
  return wsManager;
}

