"use client";

import { createContext, useContext, useEffect, useState, useCallback, useRef } from "react";
import { useRouter, usePathname } from "next/navigation";
import { getSupabaseClient } from "@/lib/supabase/client";
import type { User, UserRole } from "@/types/beautonomi";
import type { Session } from "@supabase/supabase-js";

interface AuthContextType {
  user: User | null;
  session: Session | null;
  role: UserRole | null;
  isLoading: boolean;
  isEmailVerified: boolean; // Email verification status
  signOut: () => Promise<void>;
  refreshUser: () => Promise<User | null>;
  signIn: (email: string, password: string) => Promise<void>;
  signUp: (email: string, password: string, fullName?: string, phone?: string) => Promise<void>;
  resendVerificationEmail: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const userRef = useRef<User | null>(null);
  const isLoadingRef = useRef(false);
  const sessionRef = useRef<Session | null>(null);

  // Initial state from cache so refs are set on first render (prevents logout when tab switches / remount)
  function getInitialAuthFromCache(): { user: User | null; session: Session | null; role: UserRole | null } {
    if (typeof window === 'undefined') return { user: null, session: null, role: null };
    try {
      const cached = localStorage.getItem('beautonomi_auth_cache');
      if (cached) {
        const parsed = JSON.parse(cached);
        if (parsed.timestamp && Date.now() - parsed.timestamp < 24 * 60 * 60 * 1000) {
          return {
            user: parsed.user ?? null,
            session: parsed.session ?? null,
            role: parsed.role ?? null,
          };
        }
      }
    } catch {
      // Ignore
    }
    return { user: null, session: null, role: null };
  }

  const cached = getInitialAuthFromCache();
  const [user, setUser] = useState<User | null>(cached.user);
  const [session, setSession] = useState<Session | null>(cached.session);
  const [role, setRole] = useState<UserRole | null>(cached.role);
  const [isLoading, setIsLoading] = useState(true);
  const [isEmailVerified, setIsEmailVerified] = useState(true);
  const router = useRouter();
  const _pathname = usePathname();
  const supabase = getSupabaseClient();

  // Sync refs with initial cache so onAuthStateChange(!newSession) doesn't clear state before refs update
  if (cached.user && !userRef.current) userRef.current = cached.user;
  if (cached.session && !sessionRef.current) sessionRef.current = cached.session;

  // Save to cache whenever state changes - use localStorage for persistence
  useEffect(() => {
    if (typeof window !== 'undefined' && (user || session)) {
      try {
        localStorage.setItem('beautonomi_auth_cache', JSON.stringify({
          user,
          session,
          role,
          timestamp: Date.now(),
        }));
      } catch {
        // Ignore storage errors
      }
    }
  }, [user, session, role]);

  // Clear cache on explicit logout
  const clearAuthCache = useCallback(() => {
    if (typeof window !== 'undefined') {
      try {
        localStorage.removeItem('beautonomi_auth_cache');
        localStorage.removeItem('beautonomi_session_cache');
      } catch {
        // Ignore errors
      }
    }
  }, []);

  // Request deduplication: prevent concurrent refreshUser calls
  const refreshInProgress = useRef(false);
  const lastRefreshTime = useRef<number>(0);
  const pendingRefreshCallbacks = useRef<Array<{ resolve: (user: User | null) => void; reject: (error: any) => void }>>([]);
  const REFRESH_COOLDOWN = 2000; // 2 seconds cooldown between refresh attempts
  const TIMEOUT_WARNING_COOLDOWN = 10000; // Only log timeout warning once per 10 seconds
  const lastTimeoutWarningTime = useRef<number>(0);

  // Helper to check email verification status
  const checkEmailVerification = useCallback((currentSession: Session | null): boolean => {
    if (!currentSession?.user) return false;

    // If email_confirmed_at exists, email is definitely verified
    const emailConfirmedAt = currentSession.user.email_confirmed_at;
    if (emailConfirmedAt) return true;

    // If email_confirmed_at is null, we need to determine if verification is enabled or disabled
    // In Supabase:
    // - If email confirmation is DISABLED: user gets a session immediately, email_confirmed_at is null
    // - If email confirmation is ENABLED: user gets NO session until verified, email_confirmed_at is null until verified

    // Since we have a session here, it means either:
    // 1. Email confirmation is disabled (user is "verified" by default)
    // 2. Email confirmation is enabled AND user already verified (but email_confirmed_at might not be set yet)
    // 3. Email confirmation is enabled but verification was bypassed somehow

    // The safest approach: if we have a valid session, assume user is verified
    // The banner component will show if email_confirmed_at is null AND verification is actually required
    // This way, if verification is disabled, banner won't show (because we return true here)
    // If verification is enabled but not confirmed, banner will show (because email_confirmed_at is null)

    // In mock/development mode, always assume verified
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || '';
    const isMockMode = process.env.NODE_ENV !== "production" && (
      supabaseUrl.includes('placeholder') || 
      supabaseUrl === 'https://placeholder.supabase.co' ||
      !supabaseUrl || supabaseUrl === ''
    );

    if (isMockMode) return true;

    // If we have a session, user can access the app
    // This means either verification is disabled OR user is verified
    // We'll let the banner component make the final check
    return true;
  }, []);

  const refreshUser = useCallback(async (): Promise<User | null> => {
    // Request deduplication: if a refresh is already in progress, wait for it
    if (refreshInProgress.current) {
      return new Promise<User | null>((resolve, reject) => {
        pendingRefreshCallbacks.current.push({ resolve, reject });
      });
    }

    // Cooldown check: if we just refreshed recently, return cached user
    const timeSinceLastRefresh = Date.now() - lastRefreshTime.current;
    if (timeSinceLastRefresh < REFRESH_COOLDOWN && userRef.current) {
      return userRef.current;
    }

    // Mark refresh as in progress
    refreshInProgress.current = true;
    lastRefreshTime.current = Date.now();

    // Supabase client is null during SSR; skip and clear loading when on client
    if (!supabase) {
      setIsLoading(false);
      refreshInProgress.current = false;
      const result = userRef.current;
      pendingRefreshCallbacks.current.forEach((cb) => cb.resolve(result));
      pendingRefreshCallbacks.current = [];
      return result;
    }

    // Don't clear user state immediately - wait until we confirm no session
    // This prevents the flash of logout during rebuilds

    try {
      // Skip Supabase calls if using placeholder values (mock mode)
      const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || '';
      const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || '';

      // Check if we're in mock/development mode (only if using placeholder values)
      const isMockMode = process.env.NODE_ENV !== "production" && (
                        supabaseUrl.includes('placeholder') || 
                        supabaseUrl === 'https://placeholder.supabase.co' ||
                        supabaseAnonKey.includes('placeholder') ||
                        (!supabaseUrl || supabaseUrl === '') ||
                        (!supabaseAnonKey || supabaseAnonKey === '')
                      );

      if (isMockMode) {
        // In mock/development mode, set a mock provider user for testing
        const mockUser: User = {
          id: 'mock-provider-user',
          email: 'provider@beautonomi.com',
          full_name: 'Mock Provider',
          phone: '+27123456789',
          avatar_url: null,
          role: 'provider_owner',
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        };
        // Create a mock session object
        const mockSession: Session = {
          access_token: 'mock-token',
          refresh_token: 'mock-refresh-token',
          expires_in: 3600,
          expires_at: Math.floor(Date.now() / 1000) + 3600,
          token_type: 'bearer',
          user: {
            id: 'mock-provider-user',
            email: 'provider@beautonomi.com',
            app_metadata: {},
            user_metadata: {},
            aud: 'authenticated',
            created_at: new Date().toISOString(),
          },
        };
        setSession(mockSession);
        setUser(mockUser);
        setRole('provider_owner');
        setIsEmailVerified(true); // Mock users are always verified
        setIsLoading(false);

        // Resolve pending callbacks
        const result = mockUser;
        pendingRefreshCallbacks.current.forEach(cb => cb.resolve(result));
        pendingRefreshCallbacks.current = [];
        refreshInProgress.current = false;

        return mockUser;
      }

      // Get session and refresh if needed - with timeout to prevent hanging
      let currentSession = null;

      // Add timeout to getSession to prevent infinite loading
      const sessionTimeout = new Promise<{ data: { session: null }, error: null }>((resolve) => {
        setTimeout(() => {
          resolve({ data: { session: null }, error: null });
        }, 3000); // 3 second timeout
      });

      let sessionPromise: Promise<any>;
      try {
        sessionPromise = supabase.auth.getSession();
      } catch (error) {
        console.warn("Error creating session promise, Supabase client may be stale:", error);
        // If Supabase client is stale, try to get a fresh one
        const freshSupabase = getSupabaseClient();
        if (!freshSupabase) throw error;
        sessionPromise = freshSupabase.auth.getSession();
      }

      const sessionResult = await Promise.race([sessionPromise, sessionTimeout]);

      const { data: { session: initialSession }, error: sessionError } = sessionResult as any;

      if (sessionError) {
        console.error("Error getting session:", sessionError);
        // Only clear state if this is a real error, not a timeout
        // Timeouts might just mean slow network, not actual logout
        if (sessionError.message !== 'timeout' && sessionError.code !== 'PGRST301') {
          setSession(null);
          setUser(null);
          setRole(null);
          setIsEmailVerified(false);
        }
        setIsLoading(false);

        // Resolve pending callbacks with current user if available
        const result = userRef.current; // Return current user instead of null on timeout
        pendingRefreshCallbacks.current.forEach(cb => cb.resolve(result));
        pendingRefreshCallbacks.current = [];
        refreshInProgress.current = false;

        return result;
      }

      currentSession = initialSession;

      // If we have a session, try to refresh it to ensure it's valid
      // But don't block if refresh fails - use existing session
      if (currentSession) {
        try {
          // Add timeout to refresh to prevent hanging
          const refreshTimeout = new Promise<{ data: { session: null }, error: { message: 'timeout' } }>((resolve) => {
            setTimeout(() => {
              resolve({ data: { session: null }, error: { message: 'timeout' } });
            }, 2000); // 2 second timeout for refresh
          });

          const refreshPromise = supabase.auth.refreshSession();
          const refreshResult = await Promise.race([refreshPromise, refreshTimeout]);

          const { data: { session: refreshedSession }, error: refreshError } = refreshResult as any;

          if (!refreshError && refreshedSession) {
            currentSession = refreshedSession;
          } else if (refreshError) {
            // If refresh fails or times out, continue with existing session
            // The API will handle expired tokens
            if (refreshError.message !== 'timeout') {
              console.warn("Session refresh failed:", refreshError);
            }
            // Continue with existing session - let the API handle expired tokens
          }
        } catch (refreshError) {
          console.warn("Error refreshing session:", refreshError);
          // Continue with existing session
        }
      }

      setSession(currentSession);

      if (!currentSession?.user) {
        setUser(null);
        setRole(null);
        setIsEmailVerified(false);
        setIsLoading(false);

        // Resolve pending callbacks
        const result = null;
        pendingRefreshCallbacks.current.forEach(cb => cb.resolve(result));
        pendingRefreshCallbacks.current = [];
        refreshInProgress.current = false;

        return null;
      }

      // Check email verification status
      const emailVerified = checkEmailVerification(currentSession);
      setIsEmailVerified(emailVerified);

      // Try to get role from cache first (if available)
      let cachedRole: UserRole | null = null;
      if (typeof window !== 'undefined') {
        try {
          const cached = sessionStorage.getItem('user_role_cache');
          if (cached) {
            const parsed = JSON.parse(cached);
            if (parsed.userId === currentSession.user.id && parsed.timestamp && Date.now() - parsed.timestamp < 5 * 60 * 1000) {
              cachedRole = parsed.role;
            }
          }
        } catch {
          // Ignore cache errors
        }
      }

      // First, try a quick role-only query (faster than full profile)
      let userRole: UserRole | null = cachedRole;
      if (!userRole) {
        try {
          const roleTimeout = new Promise<null>((resolve) => {
            setTimeout(() => resolve(null), 2000); // 2 second timeout for role query
          });

          const roleQueryPromise = supabase
            .from('users')
            .select('role')
            .eq('id', currentSession.user.id)
            .maybeSingle();

          const roleResult = await Promise.race([roleQueryPromise, roleTimeout]) as { data?: { role: UserRole }; error?: any } | null;

          if (roleResult && !('error' in roleResult) && roleResult.data) {
            userRole = roleResult.data.role;
            // Cache the role
            if (typeof window !== 'undefined') {
              try {
                sessionStorage.setItem('user_role_cache', JSON.stringify({
                  userId: currentSession.user.id,
                  role: userRole,
                  timestamp: Date.now(),
                }));
              } catch {
                // Ignore cache errors
              }
            }
          }
        } catch (e) {
          console.warn("Role query failed, will try full profile query:", e);
        }
      }

      // Fetch user profile from database with timeout
      const timeoutPromise = new Promise<null>((resolve) => {
        setTimeout(() => resolve(null), 3000); // Increased to 3 seconds for better reliability
      });

      // Only select role first for faster redirect, then fetch full profile if needed
      const queryPromise = supabase
        .from('users')
        .select('id, role, email, full_name, phone, avatar_url, created_at, updated_at')
        .eq('id', currentSession.user.id)
        .maybeSingle(); // Use maybeSingle to avoid errors if user doesn't exist

      const result = await Promise.race([queryPromise, timeoutPromise]);

      if (result === null) {
        // Throttle timeout warnings: only log once per 10 seconds to reduce console noise
        const timeSinceLastWarning = Date.now() - lastTimeoutWarningTime.current;
        if (process.env.NODE_ENV === 'development' && timeSinceLastWarning >= TIMEOUT_WARNING_COOLDOWN) {
          lastTimeoutWarningTime.current = Date.now();
          console.warn("User profile query timed out after 3 seconds - using session data");
        }
        // Don't set user to null on timeout - use session data instead
        // This prevents premature logouts when database is slow
        // IMPORTANT: Preserve existing role if we have one (don't clear during tab switches)
        // Use cached role if available, otherwise try existing role, then session metadata, finally default to customer
        const fallbackRole = userRole || role || currentSession.user.user_metadata?.role || 'customer';
        const sessionUser: User = {
          id: currentSession.user.id,
          email: currentSession.user.email || '',
          full_name: currentSession.user.user_metadata?.full_name || '',
          phone: currentSession.user.user_metadata?.phone || null,
          avatar_url: currentSession.user.user_metadata?.avatar_url || null,
          role: fallbackRole,
          created_at: currentSession.user.created_at,
          updated_at: currentSession.user.updated_at || currentSession.user.created_at,
        };
        setUser(sessionUser);
        // Only update role if we got a new one, otherwise preserve existing
        if (userRole || !role) {
          setRole(fallbackRole);
        }
        setIsEmailVerified(emailVerified);
        setIsLoading(false);

        // Resolve pending callbacks
        pendingRefreshCallbacks.current.forEach(cb => cb.resolve(sessionUser));
        pendingRefreshCallbacks.current = [];
        refreshInProgress.current = false;

        return sessionUser;
      }

      const { data: userData, error: userError } = result as any;

      if (userError) {
        console.error("Error fetching user profile:", userError);
        // Don't clear user/role on error - preserve existing state
        // This prevents losing auth state during network issues or tab switches
        // Only clear if we truly have no existing state
        if (!userRef.current && !role) {
          setUser(null);
          setRole(null);
          setIsEmailVerified(false);
        }
        setIsLoading(false);

        // Resolve pending callbacks with existing user if available
        const result = userRef.current || null;
        pendingRefreshCallbacks.current.forEach(cb => cb.resolve(result));
        pendingRefreshCallbacks.current = [];
        refreshInProgress.current = false;

        return result;
      }

      if (!userData) {
        console.warn("User profile not found in database");
        // Don't clear user/role if profile not found - might be temporary
        // Only clear if we truly have no existing state
        if (!userRef.current && !role) {
          setUser(null);
          setRole(null);
          setIsEmailVerified(false);
        }
        setIsLoading(false);

        // Resolve pending callbacks with existing user if available
        const result = userRef.current || null;
        pendingRefreshCallbacks.current.forEach(cb => cb.resolve(result));
        pendingRefreshCallbacks.current = [];
        refreshInProgress.current = false;

        return result;
      }

      const user = userData as User;
      setUser(user);
      setRole(user.role);

      // Cache the role for future use
      if (typeof window !== 'undefined') {
        try {
          sessionStorage.setItem('user_role_cache', JSON.stringify({
            userId: user.id,
            role: user.role,
            timestamp: Date.now(),
          }));
        } catch {
          // Ignore cache errors
        }
      }

      setIsLoading(false);

      // Resolve pending callbacks
      pendingRefreshCallbacks.current.forEach(cb => cb.resolve(user));
      pendingRefreshCallbacks.current = [];
      refreshInProgress.current = false;

      return user;
    } catch (error) {
      console.error("Unexpected error in refreshUser:", error);
      setUser(null);
      setRole(null);
      setIsEmailVerified(false);
      setIsLoading(false);

      // Reject pending callbacks
      pendingRefreshCallbacks.current.forEach(cb => cb.reject(error));
      pendingRefreshCallbacks.current = [];
      refreshInProgress.current = false;

      return null;
    }
  }, [supabase, checkEmailVerification]);

  // Update refs when values change
  useEffect(() => {
    userRef.current = user;
    isLoadingRef.current = isLoading;
    sessionRef.current = session;
  }, [user, isLoading, session]);

  useEffect(() => {
    // Supabase client is null during SSR; effect runs on client so we need it
    if (!supabase) {
      setIsLoading(false);
      return;
    }
    let isMounted = true;
    let safetyTimeout: NodeJS.Timeout | null = null;
    let subscription: { unsubscribe: () => void } | null = null;
    const visibilityCheckTimeout: NodeJS.Timeout | null = null;
    let lastTokenRefreshTime = 0;
    const TOKEN_REFRESH_DEBOUNCE = 5000; // 5 seconds debounce for token refresh

    // Initial load with timeout fallback
    const loadAuth = async () => {
      try {
        // First, quickly check if we have a session before clearing user state
        // This prevents the "flash" of logout during HMR/rebuilds
        try {
          const { data: { session: quickSession } } = await supabase.auth.getSession();
          if (quickSession && !userRef.current) {
            // We have a session but no user state - this is likely a rebuild
            // Don't clear anything, just refresh in background
            refreshUser().catch(() => {
              // Ignore errors during background refresh
            });
            return;
          }
        } catch {
          // If quick check fails, proceed with normal flow
        }

        await refreshUser();
        // Clear timeout if auth loaded successfully
        if (isMounted && safetyTimeout) {
          clearTimeout(safetyTimeout);
          safetyTimeout = null;
        }
      } catch (error) {
        console.error("Error in initial auth load:", error);
        // Ensure loading state is cleared even on error
        if (isMounted) {
          setIsLoading(false);
        }
      }
    };

    // Add a safety timeout - if auth hasn't resolved in 10 seconds, clear loading state
    // This prevents the app from being stuck in a loading state indefinitely
    // Increased from 5s to 10s to reduce false warnings during slow network conditions
    // IMPORTANT: Don't fire timeout when tab is hidden (browser pauses JS execution)
    safetyTimeout = setTimeout(() => {
      if (isMounted) {
        // Don't fire timeout warnings when tab is hidden - browser pauses JS execution
        const isTabHidden = typeof document !== 'undefined' && document.visibilityState === 'hidden';
        if (isTabHidden) {
          // Tab is hidden - don't log warnings, just clear loading state silently
          setIsLoading(false);
          return;
        }
        // Only log warning if tab is visible
        if (process.env.NODE_ENV === 'development') {
          console.warn("Auth initialization taking too long, clearing loading state");
        }
        setIsLoading(false);
      }
    }, 10000);

    loadAuth();

    // Listen for auth changes
    const {
      data: { subscription: authSubscription },
    } = supabase.auth.onAuthStateChange(async (event, newSession) => {
      if (!isMounted) return;

      if (event === 'SIGNED_OUT') {
        // Explicit sign out - always clear state
        setSession(null);
        setUser(null);
        setRole(null);
        setIsEmailVerified(false);
        setIsLoading(false);
      } else if (!newSession) {
        // No new session, but not explicitly signed out (e.g. tab visibility, HMR)
        // 1) If we have state in refs, keep it - do not clear
        if (sessionRef.current || userRef.current || role) {
          return;
        }
        // 2) Re-check session from storage/cookies before clearing (recovers from spurious null events)
        supabase.auth.getSession().then(({ data: { session: recheckSession } }) => {
          if (!isMounted) return;
          if (recheckSession) {
            setSession(recheckSession);
            refreshUser().catch(() => {});
            return;
          }
          setSession(null);
          setUser(null);
          setRole(null);
          setIsEmailVerified(false);
          setIsLoading(false);
        });
      } else if (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED' || event === 'USER_UPDATED') {
        // Update session first to check verification status
        if (newSession) {
          setSession(newSession);
          const verified = checkEmailVerification(newSession);
          setIsEmailVerified(verified);

          // For TOKEN_REFRESHED, don't clear user state - just update session silently
          // This prevents the "flash" of logout/login during rebuilds and token refreshes
          if (event === 'TOKEN_REFRESHED') {
            // Token refreshed - just update session, don't refresh user to prevent loops
            // Only refresh user if we don't have one
            const now = Date.now();
            if (!userRef.current) {
              // No user but session exists - do full refresh
              await refreshUser();
            } else if (now - lastTokenRefreshTime > TOKEN_REFRESH_DEBOUNCE) {
              // Only refresh user if it's been more than 5 seconds since last refresh
              // This prevents rapid token refresh events from causing loops
              lastTokenRefreshTime = now;
              refreshUser().catch(() => {
                // If refresh fails, don't clear user - session is still valid
                console.warn("Background user refresh failed, but session is valid");
              });
            }
            // Otherwise, just update session silently - user state is still valid
          } else {
            // SIGNED_IN or USER_UPDATED: set optimistic user from session so UI updates immediately
            // (navbar, modal, etc. show logged-in state without waiting for refreshUser/DB)
            const su = newSession.user;
            const optimisticRole = (su.user_metadata?.role as UserRole) || role || 'customer';
            const optimisticUser: User = {
              id: su.id,
              email: su.email ?? '',
              full_name: su.user_metadata?.full_name ?? null,
              phone: su.user_metadata?.phone ?? null,
              avatar_url: su.user_metadata?.avatar_url ?? null,
              role: optimisticRole,
              created_at: su.created_at,
              updated_at: su.updated_at ?? su.created_at,
            };
            setUser(optimisticUser);
            setRole(optimisticRole);
            userRef.current = optimisticUser;
            // Then load full profile from DB (will overwrite with real role/data)
            await refreshUser();
            router.refresh();
          }
        }
      }
    });

    subscription = authSubscription;

    // When tab becomes visible again, re-validate session so we don't stay "logged out" if state was lost
    let visibilityDebounce: NodeJS.Timeout | null = null;
    const handleVisibilityChange = () => {
      if (document.visibilityState !== 'visible') return;
      if (visibilityDebounce) clearTimeout(visibilityDebounce);
      visibilityDebounce = setTimeout(() => {
        visibilityDebounce = null;
        if (!isMounted) return;
        // If we have no user but might have session in cookies, restore from Supabase
        if (!userRef.current) {
          supabase.auth.getSession().then(({ data: { session: s } }) => {
            if (!isMounted || !s) return;
            setSession(s);
            refreshUser().catch(() => {});
          });
        }
      }, 300);
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
      isMounted = false;
      if (safetyTimeout) clearTimeout(safetyTimeout);
      if (visibilityCheckTimeout) clearTimeout(visibilityCheckTimeout);
      if (visibilityDebounce) clearTimeout(visibilityDebounce);
      if (subscription) subscription.unsubscribe();
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
    // Only depend on stable functions, not state values that change frequently
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [refreshUser, supabase, checkEmailVerification]);

  const signOut = useCallback(async () => {
    if (!supabase) return;
    try {
      // Clear local state first
      setSession(null);
      setUser(null);
      setRole(null);
      setIsEmailVerified(false);

      // Clear auth cache
      clearAuthCache();

      // Sign out from Supabase
      const { error } = await supabase.auth.signOut();
      if (error) {
        console.error("Error signing out from Supabase:", error);
        // Continue with redirect even if there's an error
      }

      // Force navigation to home page
      router.push("/");
      router.refresh(); // Refresh to clear any cached data
    } catch (error) {
      console.error("Unexpected error signing out:", error);
      // Even on error, clear state and redirect
      setSession(null);
      setUser(null);
      setRole(null);
      setIsEmailVerified(false);
      router.push("/");
      router.refresh();
    }
  }, [supabase, router]);

  const signIn = useCallback(async (email: string, password: string) => {
    if (!supabase) return;
    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (error) {
        throw error;
      }

      if (data.session) {
        await refreshUser();
      }
    } catch (error) {
      console.error("Sign in error:", error);
      throw error;
    }
  }, [supabase, refreshUser]);

  const signUp = useCallback(async (
    email: string,
    password: string,
    fullName?: string,
    phone?: string
  ) => {
    if (!supabase) return;
    try {
      const { data, error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: {
            full_name: fullName,
            phone: phone,
            role: 'customer', // Default role
          },
        },
      });

      if (error) {
        throw error;
      }

      // User profile and wallet are created automatically via trigger
      // If email confirmation is disabled, we can refresh user immediately
      if (data.session) {
        // Wait a moment for the session to be fully established
        await new Promise(resolve => setTimeout(resolve, 200));
        await refreshUser();
        // Check verification status after signup
        const verified = checkEmailVerification(data.session);
        setIsEmailVerified(verified);
      } else {
        // No session means email confirmation is required
        setIsEmailVerified(false);
      }
    } catch (error) {
      console.error("Sign up error:", error);
      throw error;
    }
  }, [supabase, refreshUser, checkEmailVerification]);

  const resendVerificationEmail = useCallback(async () => {
    if (!supabase) return;
    try {
      const { error } = await supabase.auth.resend({
        type: 'signup',
        email: user?.email || '',
      });

      if (error) {
        throw error;
      }
    } catch (error: any) {
      console.error("Error resending verification email:", error);
      throw error;
    }
  }, [supabase, user]);

  return (
    <AuthContext.Provider
      value={{
        user,
        session,
        role,
        isLoading,
        isEmailVerified,
        signOut,
        refreshUser,
        signIn,
        signUp,
        resendVerificationEmail,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

"use client";

import React, { createContext, useContext, useCallback, useEffect, useState } from "react";
import { fetcher } from "@/lib/http/fetcher";

export type Platform = "web" | "customer" | "provider";
export type Environment = "production" | "staging" | "development";

export interface ConfigBundleMeta {
  env: Environment;
  platform: Platform;
  version: string | null;
  fetched_at: string;
}

export interface ResolvedFlag {
  enabled: boolean;
  rollout_percent?: number;
  platforms_allowed?: string[] | null;
  roles_allowed?: string[] | null;
  min_app_version?: string | null;
  environments_allowed?: string[] | null;
}

export interface OnDemandModuleConfig {
  enabled: boolean;
  ringtone_asset_path: string | null;
  ring_duration_seconds: number;
  ring_repeat: boolean;
  waiting_screen_timeout_seconds: number;
  provider_accept_window_seconds: number;
  ui_copy: Record<string, any>;
}

export interface PublicConfigBundle {
  meta: ConfigBundleMeta;
  amplitude: Record<string, any>;
  third_party: Record<string, any>;
  branding: Record<string, any>;
  flags: Record<string, ResolvedFlag>;
  modules: {
    on_demand: OnDemandModuleConfig;
    ai: Record<string, any>;
    ads: Record<string, any>;
    ranking: Record<string, any>;
    distance: Record<string, any>;
    sumsub: Record<string, any>;
    aura: Record<string, any>;
    safety: Record<string, any>;
  };
}

interface ConfigBundleContextValue {
  bundle: PublicConfigBundle | null;
  isLoading: boolean;
  error: string | null;
  refresh: () => Promise<void>;
}

const ConfigBundleContext = createContext<ConfigBundleContextValue | undefined>(undefined);

const defaultBundle: PublicConfigBundle = {
  meta: {
    env: "production",
    platform: "web",
    version: null,
    fetched_at: new Date().toISOString(),
  },
  amplitude: {},
  third_party: {},
  branding: {},
  flags: {},
  modules: {
    on_demand: {
      enabled: false,
      ringtone_asset_path: null,
      ring_duration_seconds: 20,
      ring_repeat: true,
      waiting_screen_timeout_seconds: 45,
      provider_accept_window_seconds: 30,
      ui_copy: {},
    },
    ai: {},
    ads: {},
    ranking: {},
    distance: {},
    sumsub: {},
    aura: {},
    safety: {},
  },
};

export function ConfigBundleProvider({
  children,
  platform = "web",
  environment = typeof window !== "undefined" && process.env.NODE_ENV === "development" ? "development" : "production",
}: {
  children: React.ReactNode;
  platform?: Platform;
  environment?: Environment;
}) {
  const [bundle, setBundle] = useState<PublicConfigBundle | null>(null);
  const [isLoading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const url = `/api/public/config-bundle?platform=${platform}&environment=${environment}`;
      const data = await fetcher.get<PublicConfigBundle>(url);
      setBundle(data ?? defaultBundle);
    } catch (e) {
      setBundle(defaultBundle);
      setError(e instanceof Error ? e.message : "Failed to load config");
    } finally {
      setLoading(false);
    }
  }, [platform, environment]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const value: ConfigBundleContextValue = {
    bundle,
    isLoading,
    error,
    refresh,
  };

  return (
    <ConfigBundleContext.Provider value={value}>
      {children}
    </ConfigBundleContext.Provider>
  );
}

export function useConfigBundle(): ConfigBundleContextValue {
  const ctx = useContext(ConfigBundleContext);
  if (ctx === undefined) {
    return {
      bundle: null,
      isLoading: true,
      error: null,
      refresh: async () => {},
    };
  }
  return ctx;
}

export function useFeatureFlag(key: string): boolean {
  const { bundle } = useConfigBundle();
  const flag = bundle?.flags?.[key];
  return flag?.enabled ?? false;
}

export function useModuleConfig<K extends keyof PublicConfigBundle["modules"]>(
  module: K
): PublicConfigBundle["modules"][K] {
  const { bundle } = useConfigBundle();
  const mod = bundle?.modules?.[module];
  return (mod ?? defaultBundle.modules[module]) as PublicConfigBundle["modules"][K];
}

export function useThirdPartyConfig(): PublicConfigBundle["third_party"] {
  const { bundle } = useConfigBundle();
  return bundle?.third_party ?? defaultBundle.third_party;
}

export function useAmplitudeConfig(): PublicConfigBundle["amplitude"] {
  const { bundle } = useConfigBundle();
  return bundle?.amplitude ?? defaultBundle.amplitude;
}

"use client";

import React, { createContext, useContext, useState, useEffect, useRef, ReactNode } from "react";
import { providerApi } from "@/lib/provider-portal/api";
import type { Provider, Salon } from "@/lib/provider-portal/types";
import { fetcher, FetchTimeoutError } from "@/lib/http/fetcher";

interface ProviderPortalState {
  provider: Provider | null;
  salons: Salon[];
  selectedLocationId: string | null;
  selectedTeamMemberId: string | null;
  sidebarCollapsed: boolean;
  dateView: "day" | "week" | "3-days";
  setupCompletion: number;
}

interface ProviderPortalContextType extends ProviderPortalState {
  setSelectedLocation: (locationId: string) => Promise<void>;
  setSelectedTeamMember: (memberId: string | null) => void;
  setSidebarCollapsed: (collapsed: boolean) => void;
  setDateView: (view: "day" | "week" | "3-days") => void;
  refreshProvider: () => Promise<void>;
  isLoading: boolean;
  loadError: string | null;
}

const ProviderPortalContext = createContext<ProviderPortalContextType | undefined>(undefined);

// Cache provider data to avoid reloading on every mount
let cachedProviderData: {
  provider: Provider | null;
  salons: Salon[];
  setupCompletion: number;
  timestamp: number;
} | null = null;
const CACHE_DURATION = 5 * 60 * 1000; // 5 minutes cache - longer for stability
const STORAGE_KEY = 'provider_portal_cache';

// Load from sessionStorage on module load
if (typeof window !== 'undefined') {
  try {
    const stored = sessionStorage.getItem(STORAGE_KEY);
    if (stored) {
      const parsed = JSON.parse(stored);
      if (parsed.timestamp && Date.now() - parsed.timestamp < CACHE_DURATION) {
        cachedProviderData = parsed;
      }
    }
  } catch {
    // Ignore storage errors
  }
}

// Request deduplication
const pendingRequests = new Map<string, Promise<any>>();

export function ProviderPortalProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<ProviderPortalState>({
    provider: null,
    salons: [],
    selectedLocationId: null,
    selectedTeamMemberId: null,
    sidebarCollapsed: false,
    dateView: "day",
    setupCompletion: 0,
  });
  const [isLoading, setIsLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const isLoadingRef = useRef(false);

  const loadProvider = async (skipCache = false) => {
    // Prevent concurrent loads - use request deduplication
    const requestKey = 'loadProvider';
    if (pendingRequests.has(requestKey)) {
      try {
        await pendingRequests.get(requestKey);
        return;
      } catch {
        // Continue with new request if previous failed
      }
    }

    // Check cache first (unless explicitly skipping)
    if (!skipCache && cachedProviderData && Date.now() - cachedProviderData.timestamp < CACHE_DURATION) {
      // Optimistically update UI immediately from cache
      setState((prev) => ({
        ...prev,
        provider: cachedProviderData!.provider,
        salons: cachedProviderData!.salons,
        selectedLocationId: cachedProviderData!.provider?.selected_location_id || cachedProviderData!.salons[0]?.id || null,
        setupCompletion: cachedProviderData!.setupCompletion,
      }));
      setIsLoading(false);
      setLoadError(null);

      // Refresh in background if cache is getting stale (> 2 minutes old)
      const cacheAge = Date.now() - cachedProviderData.timestamp;
      if (cacheAge > 2 * 60 * 1000) {
        // Background refresh without blocking UI
        loadProvider(true).catch(() => {
          // Silently fail background refresh
        });
      }
      return;
    }

    // Create request promise for deduplication
    const requestPromise = (async () => {
      try {
        isLoadingRef.current = true;
        setIsLoading(true);
        setLoadError(null);

        // Load critical data first, then setup status in parallel
        const [provider, salons] = await Promise.all([
          providerApi.getProvider().catch((err) => {
            console.error("Failed to get provider:", err);
            throw err;
          }),
          providerApi.getSalons().catch((err) => {
            console.error("Failed to get salons:", err);
            return []; // Return empty array on error - this is acceptable
          }),
        ]);

        // Load saved location from localStorage, or use provider's selected_location_id, or first salon
        const savedLocationId = typeof window !== 'undefined'
          ? localStorage.getItem('provider_selected_location_id')
          : null;
        const locationId = savedLocationId || provider.selected_location_id || salons[0]?.id || null;

        // Update UI immediately with provider and salons (optimistic update)
        const newState = {
          provider,
          salons,
          selectedLocationId: locationId,
        };

        setState((prev) => ({
          ...prev,
          ...newState,
        }));

        // Load setup status in background (non-blocking)
        // Use provider's setup_completion as immediate value, fetch fresh in background
        const setupCompletion = provider.setup_completion || 0;
        setState((prev) => ({
          ...prev,
          setupCompletion,
        }));

        // Load fresh setup status in background (non-blocking, with shorter timeout)
        fetcher.get<{ data: { completionPercentage: number } }>("/api/provider/setup-status", { timeoutMs: 5000 }) // Reduced from 20s to 5s
          .then((setupStatus) => {
            if (setupStatus?.data?.completionPercentage !== undefined) {
              setState((prev) => ({
                ...prev,
                setupCompletion: setupStatus.data.completionPercentage,
              }));
            }
          })
          .catch((error) => {
            // Suppress AbortErrors from cancelled requests (component unmounts)
            if (error instanceof FetchTimeoutError && error.message.includes('cancelled')) {
              return; // Silently ignore cancelled requests
            }
            // Ignore other setup status errors - use provider.setup_completion as fallback
          });

        // Update cache
        const cacheData = {
          provider,
          salons,
          setupCompletion,
          timestamp: Date.now(),
        };
        cachedProviderData = cacheData;

        // Persist to sessionStorage
        if (typeof window !== 'undefined') {
          try {
            sessionStorage.setItem(STORAGE_KEY, JSON.stringify(cacheData));
          } catch {
            // Ignore storage errors
          }
        }

        setState((prev) => ({
          ...prev,
          setupCompletion,
        }));
        setLoadError(null);
      } catch (error) {
        console.error("Failed to load provider data:", error);
        const errorMessage = error instanceof Error ? error.message : "Failed to load provider data";
        setLoadError(errorMessage);
        // Don't throw - allow page to render even if provider data fails
        // The page components should handle missing provider data gracefully
        throw error; // Re-throw for request deduplication
      } finally {
        isLoadingRef.current = false;
        setIsLoading(false);
        pendingRequests.delete(requestKey);
      }
    })();

    pendingRequests.set(requestKey, requestPromise);
    await requestPromise;
  };

  useEffect(() => {
    // Load selected location from localStorage on mount
    if (typeof window !== 'undefined') {
      try {
        const savedLocationId = localStorage.getItem('provider_selected_location_id');
        if (savedLocationId) {
          setState((prev) => ({ ...prev, selectedLocationId: savedLocationId }));
        }
      } catch {
        // Ignore storage errors
      }
    }

    // Only load if we don't have cached data or it's stale
    // This prevents unnecessary reloads when component remounts due to tab visibility
    if (!cachedProviderData || Date.now() - cachedProviderData.timestamp > CACHE_DURATION) {
      loadProvider();
    } else {
      // Use cached data immediately - don't show loading
      const cached = cachedProviderData;
      if (cached) {
        const savedLocationId = typeof window !== 'undefined' 
          ? localStorage.getItem('provider_selected_location_id')
          : null;
        const locationId = savedLocationId || cached.provider?.selected_location_id || cached.salons[0]?.id || null;

        setState((prev) => ({
          ...prev,
          provider: cached.provider,
          salons: cached.salons,
          selectedLocationId: locationId,
          setupCompletion: cached.setupCompletion,
        }));
        setIsLoading(false);
        setLoadError(null);
      }
    }
  }, []);

  const setSelectedLocation = async (locationId: string) => {
    // Optimistic update - update UI immediately
    setState((prev) => ({ ...prev, selectedLocationId: locationId }));

    // Persist to localStorage immediately
    if (typeof window !== 'undefined') {
      try {
        localStorage.setItem('provider_selected_location_id', locationId);
      } catch {
        // Ignore storage errors
      }
    }

    try {
      await providerApi.selectLocation(locationId);
      // Update provider cache if it exists
      if (cachedProviderData?.provider) {
        cachedProviderData.provider.selected_location_id = locationId;
        if (typeof window !== 'undefined') {
          try {
            sessionStorage.setItem(STORAGE_KEY, JSON.stringify(cachedProviderData));
          } catch {
            // Ignore storage errors
          }
        }
      }
    } catch (error) {
      console.error("Failed to select location:", error);
      // Revert on error - check localStorage first, then fallback
      const savedLocationId = typeof window !== 'undefined'
        ? localStorage.getItem('provider_selected_location_id')
        : null;
      const fallbackLocationId = savedLocationId || cachedProviderData?.provider?.selected_location_id || cachedProviderData?.salons[0]?.id || null;
      setState((prev) => ({ 
        ...prev, 
        selectedLocationId: fallbackLocationId
      }));
    }
  };

  const setSelectedTeamMember = (memberId: string | null) => {
    setState((prev) => ({ ...prev, selectedTeamMemberId: memberId }));
  };

  const setSidebarCollapsed = (collapsed: boolean) => {
    setState((prev) => ({ ...prev, sidebarCollapsed: collapsed }));
  };

  const setDateView = (view: "day" | "week" | "3-days") => {
    setState((prev) => ({ ...prev, dateView: view }));
  };

  const refreshProvider = async () => {
    // Clear cache and storage before refreshing
    cachedProviderData = null;
    if (typeof window !== 'undefined') {
      try {
        sessionStorage.removeItem(STORAGE_KEY);
      } catch {
        // Ignore storage errors
      }
    }
    await loadProvider(true);
  };

  return (
    <ProviderPortalContext.Provider
      value={{
        ...state,
        setSelectedLocation,
        setSelectedTeamMember,
        setSidebarCollapsed,
        setDateView,
        refreshProvider,
        isLoading,
        loadError,
      }}
    >
      {children}
    </ProviderPortalContext.Provider>
  );
}

export function useProviderPortal() {
  const context = useContext(ProviderPortalContext);
  if (context === undefined) {
    throw new Error("useProviderPortal must be used within a ProviderPortalProvider");
  }
  return context;
}

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { createServerClient } from '@supabase/ssr';

const ALLOWED_ORIGINS = [
  'http://localhost:8081',
  'http://localhost:8082',
  'http://localhost:8083',
  'http://localhost:8084',
  'http://localhost:3000',
  'http://localhost:3001',
  /^http:\/\/192\.168\.\d+\.\d+:\d+$/,
  /^http:\/\/10\.\d+\.\d+\.\d+:\d+$/,
];

function isAllowedOrigin(origin: string | null): boolean {
  if (!origin) return false;
  return ALLOWED_ORIGINS.some((allowed) =>
    typeof allowed === 'string' ? allowed === origin : allowed.test(origin),
  );
}

function corsHeaders(origin: string | null) {
  const headers: Record<string, string> = {
    'Access-Control-Allow-Methods': 'GET,POST,PUT,PATCH,DELETE,OPTIONS',
    'Access-Control-Allow-Headers':
      'Content-Type, Authorization, X-Requested-With, Accept, X-CSRF-Token, X-App',
    'Access-Control-Allow-Credentials': 'true',
    'Access-Control-Max-Age': '86400',
  };
  if (origin && isAllowedOrigin(origin)) {
    headers['Access-Control-Allow-Origin'] = origin;
  }
  return headers;
}

export async function proxy(request: NextRequest) {
  try {
    const { pathname } = request.nextUrl;
    const origin = request.headers.get('origin');

    // Handle CORS preflight for API routes
    if (pathname.startsWith('/api')) {
      if (request.method === 'OPTIONS') {
        return new NextResponse(null, { status: 204, headers: corsHeaders(origin) });
      }
      const response = NextResponse.next();
      if (origin && isAllowedOrigin(origin)) {
        const headers = corsHeaders(origin);
        Object.entries(headers).forEach(([key, value]) => {
          response.headers.set(key, value);
        });
      }
      return response;
    }

    // Public routes - no protection needed
    const publicRoutes = [
      '/',
      '/search',
      '/category',
      '/explore',
      '/partner-profile',
      '/help',
      '/news',
      '/resources',
      '/become-a-partner',
      '/career',
      '/login',
      '/forgot-password',
      '/signup',
      '/gift-card',
      '/privacy-policy',
      '/terms-and-condition',
      '/accessibility',
      '/against-discrimination',
      '/BCover-for-partners',
      '/beautonomi-friendly',
    ];

    const isPublicRoute = publicRoutes.some(route => pathname === route || pathname.startsWith(route + '/'));

    // Handle provider profile pages - check include_in_search_engines setting
    if (pathname === '/partner-profile' || pathname.startsWith('/partner-profile')) {
      const slug = request.nextUrl.searchParams.get('slug');

      if (slug) {
        try {
          // Create Supabase client for checking provider settings
          const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
          const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

          if (supabaseUrl && supabaseAnonKey) {
            const supabase = createServerClient(supabaseUrl, supabaseAnonKey, {
              cookies: {
                getAll() {
                  return request.cookies.getAll();
                },
                setAll() {
                  // No-op in proxy for read-only operations
                },
              },
            });

            // Fetch provider with user's include_in_search_engines setting
            const { data: provider } = await supabase
              .from("providers")
              .select(`
                id,
                user_id,
                users!inner(include_in_search_engines)
              `)
              .eq("slug", decodeURIComponent(slug))
              .eq("status", "active")
              .single();

            if (provider) {
              const userData = (provider as any).users;
              const includeInSearchEngines = userData?.include_in_search_engines ?? false;

              // Create response
              const response = NextResponse.next();

              // Set X-Robots-Tag header if include_in_search_engines is false
              if (!includeInSearchEngines) {
                response.headers.set('X-Robots-Tag', 'noindex, nofollow');
              }

              return response;
            }
          }
        } catch (error) {
          // On error, continue with normal flow
          console.error("Error checking provider SEO settings in proxy:", error);
        }
      }

      // Continue with normal flow if no slug or error
      return NextResponse.next();
    }

    if (isPublicRoute) {
      return NextResponse.next();
    }

  // Skip static files and Next.js internals
  if (
    pathname.startsWith('/_next') ||
    pathname.startsWith('/images') ||
    pathname.startsWith('/icons') ||
    pathname.startsWith('/fonts') ||
    pathname.match(/\.(svg|png|jpg|jpeg|gif|webp|ico)$/)
  ) {
    return NextResponse.next();
  }

  try {

    // Create Supabase client for proxy
    const response = NextResponse.next({
      request: {
        headers: request.headers,
      },
    });

    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

    if (!supabaseUrl || !supabaseAnonKey) {
      // If Supabase not configured, allow through (will fail at API level)
      console.warn("Supabase not configured in proxy");
      return response;
    }

    let supabase;
    let user = null;

    try {
      supabase = createServerClient(supabaseUrl, supabaseAnonKey, {
        cookies: {
          getAll() {
            return request.cookies.getAll();
          },
          setAll(cookiesToSet) {
            cookiesToSet.forEach(({ name, value, options }) => {
              request.cookies.set(name, value);
              response.cookies.set(name, value, options);
            });
          },
        },
      });

      // Get user - this authenticates the data by contacting Supabase Auth server
      // This is more secure than getSession() which reads directly from cookies
      // Using getUser() ensures the user data is verified with the Supabase Auth server
      const { data: { user: authenticatedUser }, error: userError } = await supabase.auth.getUser();

      if (!userError && authenticatedUser) {
        user = authenticatedUser;
      }
    } catch (error) {
      console.error("Error creating Supabase client or getting session:", error);
      // On error, allow through - let the page handle auth
      return response;
    }

    // Helper function to redirect to login
    const redirectToLogin = (redirectPath: string) => {
      const redirectUrl = new URL('/', request.url);
      redirectUrl.searchParams.set('redirect', redirectPath);
      redirectUrl.searchParams.set('login', 'true');
      return NextResponse.redirect(redirectUrl);
    };

    // Helper function to redirect to home
    const redirectToHome = () => {
      return NextResponse.redirect(new URL('/', request.url));
    };

    // Helper function to get user role with timeout
    const getUserRole = async (userId: string): Promise<string | null> => {
      try {
        if (!supabase) {
          console.error("Supabase client not available");
          return null;
        }

        // Add timeout to prevent hanging (reduced to 3 seconds for faster failure)
        const timeoutPromise = new Promise<null>((resolve) => {
          setTimeout(() => resolve(null), 3000); // 3 second timeout
        });

        // Only fetch role field for faster query
        const queryPromise = supabase
          .from('users')
          .select('role')
          .eq('id', userId)
          .maybeSingle(); // Use maybeSingle instead of single to avoid errors if user doesn't exist

        const result = await Promise.race([queryPromise, timeoutPromise]);

        if (result === null) {
          console.warn("getUserRole timed out after 3 seconds");
          return null;
        }

        const { data: userData, error: userError } = result as any;

        if (userError) {
          console.error("Error fetching user role:", userError);
          return null;
        }

        if (!userData) {
          console.warn("User not found in database");
          return null;
        }

        return (userData as { role: string }).role;
      } catch (error) {
        console.error("Exception in getUserRole:", error);
        return null;
      }
    };

    // Customer routes - require authentication (any role)
    if (
      pathname.startsWith('/account-settings') ||
      pathname.startsWith('/checkout') ||
      pathname.startsWith('/booking') ||
      pathname.startsWith('/profile')
    ) {
      if (!user) {
        return redirectToLogin(pathname);
      }
      // All authenticated users can access customer routes
      return response;
    }

    // Provider routes - require provider role (except onboarding which allows customers)
    if (pathname.startsWith('/provider')) {
      try {
        if (!user) {
          return redirectToLogin(pathname);
        }

        // Allow customers to access onboarding page
        if (pathname === '/provider/onboarding' || pathname.startsWith('/provider/onboarding/')) {
          return response;
        }

        const userRole = await getUserRole(user.id);

        if (!userRole) {
          return redirectToHome();
        }

        // Check if user is provider or admin
        if (!['provider_owner', 'provider_staff', 'superadmin'].includes(userRole)) {
          // Redirect to provider onboarding if not a provider
          return NextResponse.redirect(new URL('/become-a-partner', request.url));
        }

        return response;
      } catch (error) {
        console.error("Error in provider route proxy:", error);
        return redirectToHome();
      }
    }

    // Admin routes - require superadmin role
    if (pathname.startsWith('/admin')) {
      try {
        if (!user) {
          return redirectToLogin(pathname);
        }

        const userRole = await getUserRole(user.id);

        if (!userRole) {
          console.warn("User role not found for admin route access");
          return redirectToHome();
        }

        // Check if user is superadmin
        if (userRole !== 'superadmin') {
          return redirectToHome();
        }

        return response;
      } catch (error) {
        console.error("Error in admin route proxy:", error);
        // On error, redirect to home instead of causing 500
        return redirectToHome();
      }
    }

    // Default: allow through (for any other routes we haven't explicitly handled)
    return response;
  } catch (innerError) {
    // Catch errors in auth logic
    console.error("Error in proxy auth logic:", innerError);
    // Allow through on error
    return NextResponse.next();
  }
  } catch (error) {
    // Catch any unexpected errors in proxy (including pathname access)
    console.error("Unexpected error in proxy:", error);
    // Return a response to prevent 500 error
    return NextResponse.next();
  }
}

